INSERT INTO course_descriptions VALUES(1,2022,1,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-242','<div class="desc"> <p>This interdisciplinary course examines the migration of six million African Americans who left the rural South to move to cities in the North, Midwest and West in the first half of the twentieth century. Beginning with the “First Great Migration” of 1910-1930 and continuing through the “Second Great Migration” of the 1940s through the 1960s, we will explore the ways that this unprecedented demographic shift laid the groundwork for new forms of American popular culture as well as the emerging political campaigns and social movements of the long civil rights era.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(2,2022,2,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-270','<div class="desc"> <p>This course analyzes the social experience and cultural heritage of Asian Americans through their writing, and places them in a broader comparative context of multi-racial/ethnic American society. We will examine the development of Asian American literature, its social implications and historical context, and the diversity of subject matter that the literary scene of Asian American communities has consisted of since the mid-19th century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(3,2020,3,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/200/amst-290','<div class="desc"> <p>This course introduces students to key concerns and methods in American Studies by focusing on the significance of place, identity, and rights. While we will focus on the territory known as the United States, our readings and research will trouble the security of that designation. By examining the origins of settler colonialism in the Americas, focusing upon national borders and internal boundaries, and exploring the United States'' global reach, we will study and develop different ways of understanding "America" as a product of civic rights that are extended and denied. In discussing race, gender, and sexuality, we will discuss how marginalized and "illicit" identities have been conscripted into, and radically exposed, exclusionary ideas of what it means to be American. Our study of captivity and confinement, be it a consequence of enslavement or imprisonment, will further expose just what is at stake in achieving the freedoms encapsulated in the notion of the American Dream.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(4,2022,4,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Dis/Ability and Care Cultures in the U.S </strong></p> <p>In this introduction to dis/ability studies, we will examine constructions and understandings of disability and ability in the United States, and the ways in which questions of dis/ability reflect national understandings of identity and embodiment. We will think through theories of normativity as related to conceptions of an idealized able-bodied, productive subject, reading histories of disability in the U.S., such as Susan Marie Schweik’s <em>The Ugly Laws: Disability in Public</em> (2009) that establish how disability has been historically criminalized in the U.S. in racialized, gendered, and sexed ways. We will continue into the twentieth century to think about cultural constructions of disability after WWII through David Serlin’s <em>Replaceable You: Engineering the Body in Postwar America</em> (2004) and Ruth O’Brien’s <em>Crippled Justice: The History of Modern Disability Policy in the Workplace</em> (2001). To think through intersections of queer theory and queer of color critique with disability studies, we consider work by Eli Clare, Jasbir Puar, Mel Chen, Paul B. Preciado, Robert McRuer, Ellen Samuels, Rosemarie Garland-Thomson, Alison Kafer, and Sami Schalk. In the second half of the course, we will focus on contemporary questions of disability activism and disability justice, looking at work from the Disability Justice Collective, the Disability Visibility Project, Bay Area-based performance project Sins Invalid, and writings by disability justice activists such Leah Lakshmi Piepzna-Samarasinha, Alice Wong, and others. And finally, we will connect disability justice to other movements for justice, thinking about care in a broader sense, both the administration of care and care networks established by vulnerable communities to care for one another. We will look to care interventions made through harm reduction and mutual aid, detailed in texts like Dean Spade’s<em> Mutual Aid: Building Solidarity During this Crisis (and the Next)</em> (2020), to consider how these approaches seek to provide both aid in the immediate and re-imagine care cultures in the long-term.</p> <p><strong>Origins of the New Right</strong></p> <p>This course studies the twentieth century origins and myriad manifestation of the “New Right” in U. S. politics and culture. Starting in the 1920s with the rise of the second Ku Klux Klan and Christian Fundamentalism and homing in on the New Right’s various stages of development from the Cold War to the present, we will examine film, news media, television, critical theory, and historical analyses.</p> <p><strong>Latino/a Experience</strong></p> <p>This course will explore the history and experience of Latino/a immigrants in the United States, paying particular attention to how race, ethnicity, identity, politics, class, and gender influence the lives of Latino/a immigrants. We will also examine how they have influenced historical developments in different regions of the country, especially in terms of U.S. demographics. </p> <p><strong>Black Literary History and the Archive </strong></p> <p>How do we resurrect the lives of people who were considered unimportant, those whose contributions were dismissed and buried? What does the existing historical archive tell us about what is considered valuable and about what constitutes "memory"? This class examines the lives of two of the most important 19-century Black women writers, Harriet Jacobs and Harriet Wilson, as a means to develop the tools of literary recovery. As we expand the contours of the historical canon, we will also reflect on our own sense of the scope and shape of African American historical memory and the ways in which we organize history. How do we interpret religion, resistance, and labor activities that that fall "outside" of the most recognized narratives about African American experience? This class will take on these larger questions as we also engage in archival work in newspapers, census records, and beyond. </p> <p><strong>African American Literature: Race/Gender/Sexuality </strong></p> <p>This course is designed as a survey of African American literature. We will examine a multitude of genres, including: oral forms (spirituals, ballads, work songs), poetry, fiction, drama, and essays by authors such as: Phillis Wheatley, David Walker, Sojourner Truth, Frederick Douglass, Booker T. Washington, Ida B. Wells, W.E.B. DuBois, Langston Hughes, Nella Larson, Zora Neale Hurston, Jean Toomer, Jessie R. Faucet, Claude McKay, Richard Wright, Ralph Ellison, James Baldwin, Ann Petry, and Gwendolyn Brooks. Beyond strictly a "greatest hits" or "major authors" course, this class will also consider the ways African American writers interrogate complex categories of personal identity, which requires an in-depth investigation into the intersections of race, gender, sexuality, and socioeconomic class. Through lectures, class discussions, and student presentations, we will highlight the critical impact of African American literature on American culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5,2022,5,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/100/arab-101','<div class="desc"> <p>Introduction to Modern Standard Arabic and pronunciation, alphabet, simple oral communication, reading simple prose, and other basic language skills. Instruction in the fundamentals of Arabic grammar. May not be taken for credit by those with more than one year of previous high school study (grades 10, 11, 12) in Arabic or one semester of college study in Arabic. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6,2022,6,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/200/arab-201','<div class="desc"> <p>This course focuses on the development of communicative skills via reading, speaking, listening, and writing activities, while grammatical points are drilled intensively. Students begin to read and discuss cultural and literary texts, as well as simple media materials.</p> </div>','ARAB 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7,2022,7,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/100/arth-160','<div class="desc"> <p>This course is an introduction to the rich traditions of East Asian art and architecture from ancient times to the present. The course is loosely framed in chronological order and each week will engage in an in-depth analysis of a different type of object and monument that addresses a particular concept and/or question. The themes to be covered include burial art for afterlives, the narrativity of handscroll paintings, state Buddhism, social and metaphorical uses of ink and calligraphy, ideology around ceramics, and gender and politics of contemporary performance art. We will also pay attention to the ways in which arts and monuments came to acquire enduring value and relevance through museum display and cultural preservation practices of our times. We plan to schedule at least one field trip to a museum/archive. Furthermore, the course helps students gain skills and methods crucial to art historical research and writing, such as close looking, critical thinking, and self-reflective writing.<br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8,2022,8,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/100/arth-170','<div class="desc"> <p>What makes art “European”? This fundamental question accompanies our survey of the different artistic traditions that emerged around the Mediterranean for more than 40,000 years of history, from prehistoric times through antiquity to the end of the medieval era. Rather than looking at art as the product of different monolithic “civilizations,” progressing through time in isolation from another, we will consider how a diversity of artistic cultures emerged through constant exchange and borrowing from one another. Readings, lectures, assignments and discussion will encompass artworks from the realm of painting, sculpture, architecture and material culture from a “Europe” with constantly fluid and shifting borders. The course will develop skills of visual analysis in style, iconography and technique. Issues of gender, race, colonization and trade in the art of the ancient and medieval eras will also be addressed. In addition, we will explore how the art of the past has constantly been reimagined to fulfill more recent artistic and political ideologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9,2022,9,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/100/arth-180','<div class="desc"> <p>A selective survey of European and American painting and sculpture from the Renaissance to the mid-20th century. Coursework introduces students to the fundamental art historical practices of visual description and visual analysis. Readings, lectures, discussions and writing assignments focus on key artistic and visual conventions of the Euro-American tradition, from the invention of one-point perspective and illusionist models of art, to modernist critiques of those models in the 19th and 20th centuries. Major themes of the course will include changing approaches to visual narrative and description; the shifting status of the artist in Euro-American cultures; patronage, audience, art criticism and exhibition culture; issues of race, gender, identity and power in visual representation; abstraction and the rise of the avant-garde. Museum visit required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10,2022,10,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-275','<div class="desc"> <p>An introduction to the major works and issues of the period through an examination of key moments in Europe and the Mediterranean basin, from c. 300 CE to 1500 CE. A study of the forms, language, and uses of medieval visual culture will be related to the circumstances associated with the demise of the Roman Empire, migrations of Northern European peoples, the increasing power of secular rulers, the development of monasticism, and the theological perspective of the Roman Christian Church. Art and architecture associated with contemporary monotheistic religions (Judaism, Islam) will also be considered.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(11,2022,11,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-289','<div class="desc"> <p>This course will focus on modernist artistic practices in the United States and Europe between 1900 and 1950. We''ll look carefully at a wide range of practices, including painting, sculpture, photography, film and architecture. Coursework will include readings, discussions, and lectures about modernism, the rise of the avant-garde, and the role of exhibitions in the transformation of modern art. We will engage issues of gender, sexuality, race, class, and ethnicity, and the scholarship we read will encompass diverse approaches to analyzing and interpreting modern art.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(12,2022,12,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-374','<div class="desc"> <p>A survey of the painting, sculpture, and architecture of Italy, from about 1300 to 1500. All major figures, including Giotto, Ghiberti, Donatello, and Botticelli, will be considered. Works will be examined in terms of setting, patronage, and cultural context, in addition to questions of style and meaning.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(13,2022,13,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-389','<div class="desc"> <p>This course will explore the diverse forms of visual culture - painting, sculpture, photography, installation, performance, and video - produced after 1945. Through clusters of thematic and monographic lectures, we will investigate questions about artistic identity, the status and function of art in the post-World War II period, and the changing nature of avant-garde (and neo avant-garde) practices in the wake of the social cultural and economic changes of the 1960''s and 1970''s. Post-industrial society new movements advocating civil rights, feminism, and environmentalism will form the cultural backdrop of our work, as will more focused investigations of postmodernism critical theory''s increasingly central role in artistic culture and a burgeoning global network of artistic and cultural exchange and contestation. In addition to presenting a selective history of visual culture after 1945, this course will explore how changing ideas about race, ethnicity, gender, sexuality, and cultural identity have impacted the art and criticism of the period under consideration. At least one field trip to a gallery or museum will be required.</p> </div>','ARTH 180 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14,2022,14,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-390','<div class="desc"> <p>A research-intensive course on a topic within the history of art; coursework will include the process of researching and writing a scholarly essay and a focus on the methodologies of art historical scholarship. Required for Art History majors to fulfill the Second-Stage Writing Proficiency requirement. </p> <p><strong>Performance, Embodiment and the Dematerialization of Contemporary Art</strong></p> <p class="MsoNormal">When many people think of “Art” they envision a painting, a sculpture, a photograph, a lithograph or woodcut, or even an artist’s handmade book. Yet in the later years of the 20<sup>th</sup> century, artists drew on the disruptive works of the historical avant-gardes like Dada and Surrealism, as well as new ideas about the artist’s place in the world, to create work that looked and behaved very differently than traditional media. In the years after 1960, artists questioned the definition of art (is it a thing or is it an action or an event?). In turn, artists grew invested in making work that disrupted the more traditionally passive relationship between viewer and work; instead, the spatial, temporal and cultural contexts of art works became part of the work itself. Coupled with the desire by many artists to displace art from the traditional confines of the commercial gallery system, as well as to call into question the realities of individual and collective embodiment and identities, the effect of these new approaches was to expand the definitions of art to include performance, body art, installation, and institutional critique. Thus, artists transformed, and often dematerialized the “work of art” in favor of an art that could provoke action, communication, collaboration, and cultural critique. This seminar will enable us to explore these new modes of artistic practice in North America and Europe through provocative art historical and theoretical readings; student research projects; and activities and exhibitions at Oxy Arts and across Los Angeles.</p> <p><strong>Building the ‘American Pacific’</strong></p> <p>This course examines modern and contemporary architecture of the ‘American Pacific.’ Students will investigate the historical, social, cultural, political, climactic, and technological factors that have influenced the development of architecture in Hawai‘i, American SÄmoa, and Guam. Theoretical examinations about U.S. empire, race, and sovereignty allow us to challenge the very notion of an ‘American Pacific’ and frame our study of architecture as a complex interplay of evolving beliefs and meanings. An examination of Pacific Island spaces/places and their relationship to artistic endeavors by artists and architects reveal the ways in which indigenous and foreign identities influence the built environment. Students will engage with interdisciplinary and intersectional scholarship as we consider the architectural legacy of American expansion in the Pacific. Additional Core Requirement Met: Regional Focus.</p> <p><strong>Colonial Urbanism </strong></p> <p>In this course, we will examine the spatial legacy of colonial cities. The focus is on colonial urban spaces and architectural projects that were manifestations of the political, economic, and social relationships between the colonizers and the colonized. In relation, the role of imperialism - as it transpired in both the colonies and colonizing societies of Europe and the United States - will reveal the ways in which the imperial imagination was visible in physical form. Through a range of case studies, including sites in former European and American colonies of Asia and the Pacific, as well as former imperial centers, such as London and Washington D.C., students will develop a theoretical toolkit for the critical study of urban colonial environments.</p> <p><strong>Gender and Sexuality in 20th Century Art</strong></p> <p>This seminar will explore the how issues of gender and sexuality have shaped the practices of visual artists in the US and Europe in the 20th century. We will investigate how artists have engaged directly with these issues in their art, and we will also consider how the field of Art History itself has been impacted by practices and stereotypes about gender and sexuality. Additional Core Requirement Met: Global Connections.</p> </div>','Any 100- or 200-level Art History course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15,2022,15,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/100/arts-101','<div class="desc"> <p>Working with a variety of drawing materials - charcoal, pencil, ink, gouache, and acrylic paint - students investigate a fundamental aesthetic and visual vocabulary. Beginning with exercises in mark-making, then working through a formal study of basic visual elements and simple subject matter, students develop a working understanding of two-dimensional composition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16,2022,16,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/100/arts-102','<div class="desc"> <p>Beginning with a familiarization of paint gesture and mark, then working through a formal study of basic visual elements (line, shape, form, light, space, and color) and simple subject matter (still life, landscape, the figure, abstraction), students develop a basic understanding of image construction and two-dimensional composition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(17,2022,17,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/100/arts-103','<div class="desc"> <p>The aim of this course is to introduce the conceptual, technical, and critical tools central to contemporary sculpture practices. The class consists of a combination of technical seminars, in-class fabrication, critiques, field trips, informal lectures in contemporary art history, readings, and a series of short papers. Emphasis will be placed on the student''s ability to make, understand, discuss, and write about sculpture in a substantive way.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(18,2022,18,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/100/arts-105','<div class="desc"> <p>Printmaking Fundamentals is an introduction to the technical and conceptual properties of relief and intaglio printmaking. Through a series of projects, critique sessions, and written assignments, the course will introduce students to debates in contemporary printmaking, and the larger historical and cultural contexts that inform their work. The class will also feature visiting printmakers, field trips and other activities linking the coursework to the larger Los Angeles community.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(19,2022,20,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-215','<div class="desc"> <p>This is an introduction to the fine art of silkscreen printmaking. Students learn the historical, theoretical, and critical understanding of the process, with an emphasis on developing their artistic voice by completing specific assignments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(20,2022,21,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/300/arts-310','<div class="desc"> <p>Advanced study in painting and drawing, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year.</p> </div>','ARTS 102 and ARTS 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(21,2022,23,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/400/arts-490','<div class="desc"> <p>Group critiques of individual projects in student''s choice of medium. Discussion of techniques, exhibition problems, self-evaluation, and current art movements, in the context of the history of art. May earn up to a total of four units.</p> </div>','At least junior standing and ARTS 102, ARTS 103, ARTS 105, ARTS 203, and ARTS 210; OR ARTS 216; OR ARTS 217 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(22,2022,24,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bich-biochemistry/400/bich-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Biochemistry majors; to be taken both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(23,2022,25,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-103','<div class="desc"> <p><strong>Urban Ecology</strong></p> <p>Los Angeles is an urban ecosystem where people, nature, and the built environment interact. We will consider L.A., the second largest city in the U.S., as a case study of how organisms and the environment influence each other. Through reading, discussion, writing, gathering data, and exploration we will ask, what physical features define the Los Angeles environment? How have these changed over time, and what changes are likely to happen in the near future? What species of organisms (beyond palm trees, pets, rats, and cockroaches) inhabit this city? How does the physical environment affect urban species, and how do they, in turn, affect their environment? Students will develop proficiency in skills needed for the practice of biology, quantitative reasoning, and critical evaluation of scientific ideas and results. This course is an inquiry-based introduction to biological science in a format that includes both classroom activities and fieldwork. Field trips will occur during class time, with one required day-long field trip to be scheduled at the start of the semester.</p> <p><strong>Ecological Enhancement and Restoration</strong></p> <p>Biological, ecological, and social views regarding need, methods, and effects of restoration and enhancement of ecosystems. Recent events from California and the rest of the world are discussed, focusing on marine and terrestrial ecosystems, invasive species, over-harvesting, industrial impacts on the environment, and methods of mitigating or repairing damages. Examples of discussions include: methods of combating over-harvesting in the Pacific Ocean; natural and anthropogenic methods of recovering from forest fires; oil platforms functioning as artificial reefs to help endangered species thrive; also, how does a nuclear generating station affect a giant kelp forest, and what can be done to mitigate those damages?</p> <p><strong>Public Health Biology</strong></p> <p>This introductory course will offer an integrative biological perspective on public health issues, highlighting specific diseases of viral, bacterial, and environmental origin, as well as the influence of social and economic disparity. We will explore specific examples, such as rising antibiotic resistance, cholera and hepatitis outbreaks, cancer, and diabetes, to illustrate biological principles required to understand infectious and non-infectious diseases of public health importance.</p> <p><strong>Topics in Cancer Biology</strong></p> <p>This course will introduce students to the fundamentals of cancer biology. Topics will range from the biological origins of cancer to recent advances in diagnostics and therapeutics. Students will also be given a historical perspective of the bioethics surrounding cancer research and treatment. This course will highlight cutting edge research, with a focus on the detection and treatment of cancer in the age of personalized medicine.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(24,2022,26,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-105','<div class="desc"> <p>This course will be an introductory survey of marine organisms and their environment. It will cover fishes, invertebrates, mammals, reptiles, and algae. Included will be an investigation of behavior, ecology, adaptations, and environmental relationships to humans. An emphasis will be placed on forms common to California. <em>Includes one three-hour lab period per week; field trips will be included during the laboratory period. (Labs may take longer than the scheduled laboratory period to accommodate field trips.)</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(25,2022,28,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-106','<div class="desc"> <p>A component of the California Environmental Science Semester. Enrollment limited to first-year students enrolled in the California Environmental Science Semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(26,2022,30,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-110','<div class="desc"> <p>Principles and concepts of organismal structure and function, diversity, evolution, and ecology examined through case studies of organisms and their interactions with their environments. Emphasis will be placed on how organisms, from distinct biological groups, meet environmental challenges, such as: obtaining energy and nutrients, maintaining water and osmotic balances, reproducing, and finding a place to live. Students will learn to recognize and frame hypotheses about biological organisms and phenomena that can be tested (or falsified) by acquiring and analyzing appropriate evidence. Students will learn to acquire, analyze, and evaluate biological data through observation and experimentation in the laboratory and in the field. This course is designed for science majors and pre-health students; seniors may enroll by permission of instructor only. <em>Includes one three-hour laboratory per week.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(27,2022,32,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-115','<div class="desc"> <p>An introduction to the diversity, comparative anatomy, and physiology of animals. Emphasis is placed on the classification of animals, how animals are adapted to the environment, and the evolutionary relationships between the phyla. This class is designed for science majors. <em>Includes one three-hour laboratory per week.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(28,2022,34,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-130','<div class="desc"> <p>A concept-driven survey course designed to provide broad introduction to the biochemistry, physiology, and molecular biology of prokaryotic and eukaryotic cells. Topics include: structure/function; relationships of biological macromolecules; the roles of such molecules in cellular metabolism and membrane biology; molecular biology of DNA, RNA, and protein synthesis; the cell cycle; elementary genetics; and cellular communication. <em>Includes one three-hour laboratory per week. </em>Prerequisites may be taken concurrently with this course.</p> </div>','CHEM 120, CHEM 130 or permission of instructor ','BIO 130L ',NULL);
INSERT INTO course_descriptions VALUES(29,2022,36,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-224','<div class="desc"> <p>Intensive concept-driven exploration of genetic information transfer between generations. Topics include: Mendelian principles, allelic and genetic interactions at the phenotypic level, complex traits, genetic mapping, DNA repair and genome maintenance, epigenetics, and principles of gene regulation. <em>Includes one three-hour laboratory session per week, plus 1-2 hours arranged.</em></p> </div>','CHEM 120; or CHEM 130 and BIO 130; or permission of instructor ','BIO 224L ',NULL);
INSERT INTO course_descriptions VALUES(30,2017,37,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-224L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(31,2022,38,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-260','<div class="desc"> <p>The goal of this course is to introduce marine ecosystems and the physical and biological attributes contributing to their organization. The course will focus on the nearshore marine environment of the Southern California Bight, referencing examples from comparable ecosystems. It will introduce basic physical attributes and the organisms of these dynamic ecosystems. Students will learn how to collect data, in both field and laboratory settings, database management, advanced database queries, conduct basic statistical analyses, test hypotheses, produce graphics, and write scientific papers. This course will serve to prepare students for focused upper division courses and independent research. Labs may take longer than the scheduled lab period to accommodate field trips. <em>Includes one three-hour laboratory session per week.</em></p> </div>','BIO 105, BIO 106, BIO 110, or BIO 115; or permission of instructor ','BIO 260L ',NULL);
INSERT INTO course_descriptions VALUES(32,2017,39,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-260L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(33,2022,40,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-280','<div class="desc"> <p>A detailed analysis of the causes and consequences of biological evolution. The focus, here, is on understanding basic evolutionary mechanisms with plant and animal examples used to illustrate and clarify the fundamentals of the evolutionary process. Classical and recent contributions to our understanding of evolutionary biology are examined, including: population genetics, theoretical models, geographical variation, speciation, biogeography, phylogeny, reconstruction, molecular evolution, macroevolution, and the evolution of Homo sapiens.</p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(34,2022,41,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-310','<div class="desc"> <p>Introduction to the principles and practice of museology and the functioning of a research natural history museum. Emphasis will be on the development of the "museum conscience" and attendant curatorial skills, through extensive training as a curatorial assistant. Students will make use of the bird, mammal, and fish collections of the Moore Laboratory of Zoology (the world''s largest collections of Mexican birds and Southern California Rocky Reef fishes) and the Cosman Shell Collection at Occidental College. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(35,2022,42,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-322','<div class="desc"> <p>Survey of the basic principles that power biological processes in all living organisms. Includes introduction to biochemical techniques, enzyme structure and function, intermediary metabolism, synthesis and degradation of biological macromolecules, information transfer, and a concept-driven integration of these subjects into a biological context. This course meets the Biochemistry requirements for most graduate and professional schools. <em>Includes one three-hour laboratory per week. </em>Not open to students who have successfully completed Biology 349.</p> </div>','Biology 130 and Chemistry 220, or permission of instructor ','BIO 322L ',NULL);
INSERT INTO course_descriptions VALUES(36,2022,43,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-322l','<div class="desc"> <p>The application of techniques to study protein structure and function, including protein purification, column chromatography, enzyme kinetics, crystallography, and computer-aided structural analysis.</p> </div>',NULL,'BIO 322 ',NULL);
INSERT INTO course_descriptions VALUES(37,2022,44,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-330','<div class="desc"> <p>Introduction to current concepts of immunology, including immunoglobulin structure and function, T cells and B cells, cell-cell cooperation in the immune response, and the role of the major histocompatibility complex. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221, BIO 224, BIO 226, or permission of instructor ','BIO 330L',NULL);
INSERT INTO course_descriptions VALUES(38,2022,45,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-330l','<div class="desc"> <p>Introduction to essential immunological techniques, including immunization and immunoassay, such as ELISA; generation of hybridomas and screening and characterizing monoclonal antibodies; and introduction to other techniques, such as FACS. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 330 ',NULL);
INSERT INTO course_descriptions VALUES(39,2022,46,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-378','<div class="desc"> <p>Emphasizes the evolutionary approach to the study of animal behavior, drawing broadly from the various disciplines within biology concerned with the factors that determine which organisms survive and reproduce. The course material will be divided into four broad categories: sensory capabilities, feeding patterns, spacing patterns, and reproduction. For each topic, theory and application will be presented. Students will analyze research papers and lead discussions on an aspect of each major topic. The laboratory portion of the course will focus on observational and experimental approaches to studying animal behavior in the lab and in the field. We will make use of local resources, such as zoos, aquaria, wildlife conservation areas, veterinarians, and animal rehabilitation facilities. An independent research project is required. This course is designed for Biology majors, although it would be appropriate for students from other majors. <em>Includes one three-hour laboratory per week and weekend field trips to be announced.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 378L ',NULL);
INSERT INTO course_descriptions VALUES(40,2022,47,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-378l','<div class="desc"> <p>Laboratory techniques in Animal Behavior. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 378 ',NULL);
INSERT INTO course_descriptions VALUES(41,2022,48,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-395','<div class="desc"> <p>Research for approximately five hours per week for students to study in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(42,2022,49,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/400/bio-490','<div class="desc"> <p>Topics of these seminars will be announced at Spring pre-registration. Each senior must pass one seminar for the Comprehensive requirement. Each seminar meets two hours per week with extensive reading, discussion, and a major oral presentation by each student.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(43,2022,50,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/500/bio-590','<div class="desc"> <p>Preparation of the Master''s thesis in consultation with the advisor and committee members. Department approval required.</p> </div>','At least two courses of BIO 501 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(44,2022,51,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/100/chem-100','<div class="desc"> <p>Develop the skills necessary for a satisfactory introduction to general chemistry.</p> </div>','Open only for first year frosh with successful completion of a placement examination. Others only with permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(45,2022,52,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/100/chem-104','<div class="desc"> <p>This is a course suitable for non-majors and covers the chemical bases of life. The course will be structured around the chemistry of the fundamental building blocks of life - nucleic acids, proteins, polysaccharides, etc. - and how they interact to support the cellular life. Examples of the specific topics include the evolution of the human genome.</p> </div>','One high school science course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(46,2022,53,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/100/chem-120','<div class="desc"> <p>An introduction to the primary chemical concepts of atomic structure and quantum theory, periodic trends, molecular structure, chemical kinetics, equilibrium thermodynamics, and acids and bases. <em>Includes one three-hour laboratory per week.</em></p> </div>','Satisfactory performance on the Chemistry Placement Examination, or completion one First Year Seminar, or permission of instructor ','CHEM 120L ',NULL);
INSERT INTO course_descriptions VALUES(47,2017,54,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CHEM-Chemistry/100/CHEM-120L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(48,2022,55,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/100/chem-130','<div class="desc"> <p>An advanced presentation of topics in atomic structure, periodic trends, molecular structure, molecular symmetry, and vibrational spectroscopy. <em>Includes one three-hour laboratory per week.</em></p> </div>','AP Chemistry score of 4 or 5; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(49,2017,56,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CHEM-Chemistry/100/CHEM-130L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(50,2022,57,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/100/chem-195','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(51,2022,58,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/200/chem-220','<div class="desc"> <p>Introduction to the fundamental concepts of organic chemistry. The course explores the properties and structures of carbon-based molecules, and focuses on how these factors influence their reactivity. Special emphasis is placed on biologically relevant organic transformations, as well as the prevalence of organic chemistry in everyday lives. Includes one three-hour laboratory that focuses on the practical techniques employed when conducting reactions and purifying organic molecules.</p> </div>','CHEM 120, CHEM 130, or permission of instructor ','CHEM 220L ',NULL);
INSERT INTO course_descriptions VALUES(52,2017,59,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CHEM-Chemistry/200/CHEM-220L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(53,2022,60,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/200/chem-221','<div class="desc"> <p></p><p>Continuation of Organic Chemistry I. The course focuses on the reactivity of organic molecules, including molecules and reactions with biological relevance. Special emphasis is placed on mechanism and employing chemical reactions to develop strategies for multistep synthesis. Includes one three-hour laboratory that applies the techniques of organic chemistry to the synthesis of interesting organic molecules.</p><p></p> </div>','CHEM 220 ','CHEM 221L ',NULL);
INSERT INTO course_descriptions VALUES(54,2017,61,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CHEM-Chemistry/200/CHEM-221L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(55,2022,62,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/200/chem-295','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(56,2022,63,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-300','<div class="desc"> <p>An introduction to the principles of chemical thermodynamics and kinetics and their application to chemical systems.</p> </div>','Calculus 2, and PHYS 120 or PHYS 125; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(57,2022,64,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-300l','<div class="desc"> <p>Applications of chemical thermodynamics and kinetics. <em>One three-hour laboratory per week.</em></p> </div>','CHEM 300 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(58,2022,65,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-340','<div class="desc"> <p>Application of modern theories of physics and chemistry to the synthesis, bonding, and reactivity patterns of inorganic compounds. Special emphasis on the role of metal ions in biological systems.</p> </div>','CHEM 130 or CHEM 150; and CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(59,2022,66,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-340l','<div class="desc"> <p>Inorganic synthesis and structure confirmation. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 340 ',NULL);
INSERT INTO course_descriptions VALUES(60,2022,67,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-355','<div class="desc"> <p>The main focus of this course is utilizing biological and chemical databases for research. The course will investigate: (1) tools that are used to extract and analyze data on small molecule drugs and biological sequences from these databases; (2) algorithms and scoring schemes used in sequence alignment and homology searches; (3) the significance of this information in modern chemical and molecular biology medicine, pharmaceutical development, protein engineering and drug design, genetics, and molecular evolution.</p> </div>','CHEM 221 and BIO 130 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(61,2022,68,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-370','<div class="desc"> <p>A continuation of CHEM 340, focusing on the interface between organic and inorganic chemistry.</p> </div>','CHEM 300, CHEM 340, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(62,2022,69,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-395','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(63,2022,70,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/400/chem-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Chemistry majors.To be repeated both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(64,2022,71,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/100/chin-101','<div class="desc"> <p>Introduction to spoken standard Chinese (Mandarin), the pinyin romanization system, and the reading and writing of Chinese characters. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Chinese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(65,2022,72,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/200/chin-201','<div class="desc"> <p>A review of basic grammar. Reading and discussion of texts dealing with contemporary Chinese society and culture. Viewing and discussion of video programs. Composition writing and oral presentations.</p> </div>','CHIN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(66,2022,73,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/200/chin-272','<div class="desc"> <p>This seminar course will examine the rise of the martial arts novel (wuxia xiaoshuo) in the context of its historical and literary roots. We will focus on how the figure and chivalric code of the martial hero and heroine have persisted in the historical, literary, and popular imagination - through such works as Sima Qian''s historical biographies, <em>The Romance of the Three Kingdoms Outlaws of the Marsh</em>; Tang dynasty classical tales; Ming dynasty court-case fiction in the vernacular language; and Pu Songling''s classical strange tales written in the Qing period. We will also explore how the 20th century master of the martial arts novel, Jin Yong (Louis Cha), a journalist writing in exile in colonial Hong Kong, has captured the imagination of Chinese diasporic communities throughout the world and contributed to the rise of the transnational Chinese martial arts film. All readings and discussions will be in English. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(67,2022,74,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/300/chin-301','<div class="desc"> <p>Reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Introduction to the use of literary style Chinese and idioms in public discourse. Developing advanced level oral-aural and essay writing skills.</p> </div>','CHIN 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(68,2022,76,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/100/cogs-101','<div class="desc"> <p>An interdisciplinary introduction to the discovery of the mind through philosophical texts, psychological experiments, artificial intelligence, the study of nerve cells and neural networks, and investigations into language. The purpose of the course is to foster an appreciation of the wonder and complexity of minds and brains, both human and otherwise. Not open to seniors in Spring semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(69,2022,77,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/100/cogs-104','<div class="desc"> <p>This course provides a basic introduction to the nervous system. The course will include an introduction to how nerve and glial cells contribute to different brain functions. This course will also cover brain structures and systems and how they act to produce sensory experience, thought, emotion, and memory. Other topics might include: factors that affect embryonic development of the nervous system, and the effect of drugs, environment, stress, education, and age on the brain. This course is not open to students who have taken BIO 333, COGS 320, KINE 301, or PSYC 322.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(70,2022,78,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-301','<div class="desc"> <p>This course will address current cognitive science research as applied to learning and education. The concept of multiple intelligences, as well as strengths and weaknesses of individuals in acquisition of information, will be emphasized. We will also cover specific learning disabilities/differences and cognitive styles.</p> </div>','COGS 101, declared minor in Education, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(71,2022,80,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/400/cogs-490','<div class="desc"> <p>This course will support senior Cognitive Science majors as they conduct original research as part of their Senior Comprehensive requirement. </p> </div>','COGS 101 and senior standing in Cognitive Science; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(72,2022,81,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-155','<div class="desc"> <p>Principles of web design. Tools and techniques of elementary web programming, including: HTML, XHTML, CSS, JavaScript, HTTP, SSL, XML, and SQL. Introduction to network architecture and programming.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(73,2020,82,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/comp-computer-science/100/comp-161','<div class="desc"> <p>Introduction to computers and fundamentals of programming in Java. Classes, objects, and methods; variables and data types; decisions and iteration; arrays and array lists; Java, API, and important classes, such as String Math Graphics; simple algorithms; and programming techniques. This course serves as either a self-contained introduction to Java Programming, or the first step in the sequence of courses leading to the Computer Science minor. Not open to students who have taken, or are taking, COMP 157<em>.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(74,2022,85,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-280','<div class="desc"> <p>This course will examine the character of postcolonial theory in the Afro-Caribbean. Particular attention will be paid to the work of C.L.R. James, Walter Rodney, Franz Fanon, Marcus Garvey, Aimé Césaire, Eric Williams, Kamau Brathwaite, and Bob Marley. The course will also examine Rastafari as a religio-political protest movement. We will chart the musicological development of reggae and dub poetry as distinctive expressions of Rasta.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(75,2022,86,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-285','<div class="desc"> <p>This course will cover the early writings of Michel Foucault, paying particular attention to his psychological writings. We will conduct a close reading of <em>Madness and Civilization</em>.</p> </div>','Any 100-level CTSJ class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(76,2022,88,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-357','<div class="desc"> <p>This course employs interpretive tactics from critical legal theory and critical race theory in order to examine the use of law to justify and sustain U.S. colonial/imperial projects. We will look at how these projects are connected to the control of domestic populations (especially indigenous and racialized groups) and the expanding desire for territory. We will look at questions about nation, state, and sovereignty; law and hegemony; and relationships between "change" and maintenance of the same in legal discourse. The course will also investigate relationships between globalization, international legal regimes, and new forms of empire. We will consider specific topics that raise questions about ongoing operations of and resistances to imperialism, including: trafficking in persons, sovereignty and indigenous people''s rights, the legal status of territories and protectorates and the selective use of the U.S. Constitution in those locations, and issues rising from the "war on terror."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(77,2022,89,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-369','<div class="desc"> <p>The Clinical Psychology Laboratory (CPL) provides experiential opportunities for students interested in graduate study in Psychology, Law, or Social Justice. Students are given the opportunity to participate in the data analysis of clinical psychological assessments. Students will also participate in research on a Human Studies Committee approved project with the goal for an early exposure to the field, and with the objective to yield research data for presentation or publication. In some projects, students may have limited opportunities to observe and participate in forensic psychological assessments as prescribed in the respective protocols. Instructor interview and approval required. May be repeated three times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(78,2022,90,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-490','<div class="desc"> <p>This course is offered in conjunction with CTSJ majors'' ongoing research for the Senior Comprehensive Project. Seminar meetings will be devoted to discussion and critique of students'' work in progress, and to close readings of a select few texts in Critical Theory and Social Justice. Only open to senior CTSJ majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(79,2022,120,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-101','<div class="desc"> <p>The purposes of this course are: (1) to introduce fundamental tools and perspectives on the study of world politics, including major theories and analytical approaches to international relations, (2) to understand the historical evolution of the contemporary international system, with special emphasis on the post-World War II era, and (3) to apply theoretical and conceptual understandings of international relations to current issues in world politics. Emphasis is placed on the state and trans-state foundations of contemporary international relations. We will study this in the context of such key issues as economic development, "security," human rights, state-building, international organizations, terrorism, and the intersection of social relations with world politics. Open to first years and sophomores. Permission of instructor required for junior and senior enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(80,2017,122,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/200/DWA-220','<div class="desc"> <p>This course is an undergraduate survey of the field of international political economy (IPE). It is intended as an introduction for students who already have some background in the field of international relations and are interested in exploring international economic relations at a deeper level. The course covers major theoretical empirical and policy perspectives. The theme to be explored in this course is "National Interest vs. Global Governance?" - that is we will explore the theory and history of international political economy as an extension of national interest and an arena for the development of global governance and the question of whether or not these two dimensions of international political economy are compatible or competitive with each other. The first part of the course will cover the basic concepts and theoretical foundations of IPE. The focus is on core theoretical principles and approaches. The goal is to understand how theory is framed and "works" the potential inferences of this theory and the issues of contention within the field. The second part of the course draws on the theoretical foundations to examine a set of specific international economic issue arenas including international trade finance and economic development. SAME AS POLS 232</p> </div>','Economics 101 and 102. Open only to DWA majors. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(81,2020,123,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-235','<div class="desc"> <p>This course will explore nationalism and ethnicity from both a theoretical and an empirical perspective. Nationalist and ethnic discourses have been central to political movements, rebellions, and revolutions. The passions and commitment of individual members in these movements often lead to political ideologies and war tactics that are violent, and which encompass entire communities. The class will concentrate on two theoretical perspectives; mainly the debates between primordialism and constructivism. Two cases from South/Southeast Asia and Sub-Saharan Africa will be analyzed.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(82,2022,124,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-238','<div class="desc"> <p>This class will focus on South Asians who were indentured to British colonies from 1860, immediately following the abolition of slavery. Over one million Indians were indentured to Mauritius, South Africa, Guyana, Trinidad, and Fiji. South Asians currently constitute a substantial proportion of the population in each of these countries, and they are in the majority in Mauritius and Trinidad. We will conduct a comparative study based on theoretical perspectives related to the diaspora''s globalization, trans-state identities, and analytical themes associated with identity and citizenship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(83,2022,125,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-241','<div class="desc"> <p>A study of Middle-Eastern international relations in the context of three themes that structure the region''s modern political history: (1) colonialism: how the reaction against colonialism continued to define and limit Middle-Eastern politics, both internally and in its relations with outside powers, (2) religion: in particular, political Islam (or "fundamentalism") is a key variable in the region''s contemporary politics, but by no means all-defining, and (3) nationalism(s): a source of political identity and mobilization. How religious, national, linguistic, and ethnic nationalisms inform conflict and cooperation within the region. </p> <p>In the context of these three themes, we will explore the following regional issues with global implications: (1) the Arab-Israeli conflict - the flash point of conflict in the Middle-East, the Arab-Israeli conflict can only be understood on the basis of an informed appreciation of its historical and ideological underpinnings, (2) Iran - the Iranian revolution had an enormous impact on regional and international affairs. Current unrest within Iran is perhaps a harbinger of yet another radical shift in Iranian politics, and (3) domestic upheaval in the region, as seen in the Arab uprisings of 2011-2012.</p> <p>Despite this being an "IR" class, on-the-ground social and political movements ("domestic," yet transnationally informed) have an enormous impact on the region''s politics. This is particularly true in the shadow of the recent Arab uprisings, upon which we will place particular attention.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(84,2017,126,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/200/DWA-265','<div class="desc"> <p>This course will examine the political military economic and cultural interactions between the United States and the rest of the world from the Spanish-American War to the present day. Taking a much broader view than traditional diplomatic histories the course will weave together analyses of major diplomatic initiatives armed conflicts and the ways in which the cultures and economies of the U.S. and other nations have influenced one another. Topics will include the causes and consequences of wars the meaning of American empire and the flow of consumer goods languages music dance motion pictures fashion social norms and people to and from the U.S..</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(85,2022,127,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-295','<div class="desc"> <p>Topics vary semester to semester. </p> <p><strong>Trump Foreign Policy</strong></p> <p>Donald Trump campaigned on a platform of America First nationalism and anti-globalization. He expressed views out of the mainstream of bi-partisan United States foreign policy since World War II. Has President Trump made good on his promises to change dramatically America''s global role or has he had to adjust to the reality of the current international system and long-standing US policies and alliances? This course will survey all aspects of Trump foreign policy in order to try to understand continuity and change in America''s role in the world. Students will be asked to examine what Trump has and has not accomplished in the international arena, and to access the costs and benefits of his policies for America and for the global community.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(86,2017,128,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/300/DWA-331','<div class="desc"> <p>An inquiry into the field of ethical inquiry in international relations with a particular focus on the increasing recognition of the multiple frames of ethics contributed by the world''s religions. It is intended as an introduction for students who already have some background in the field of international relations and are interested in exploring the subject at a deeper level. Ethics has traditionally occupied an unenvious position in mainstream theories of international relations. Either it has been relegated to the margins of the field or placed in opposition to the contingencies of state practice. Denying their own normative foundations (Western) theories of international relations traditionally ignored the relevance of ethics for the conceptualization and practice of world politics. This course reviews alternative approaches to traditional international relations theory by placing ethics at the center of the field. The course focuses on the ethical underpinnings of state practice and analyzes a range of contemporary foreign policy issues in which ethical questions are likely to arise especially the protection of human rights the historical development and contemporary formulations of ethical norms for the use of force and distributive justice in the global economy. Special emphasis will be given to religious influences on national ethics; religion as a matter of conflict; religious communities as transnational agents for justice protection of human rights and peace; and ethical and religious contributions to reconciliation solidarity and peacemaking. The theme to be explored in this course is "State Interest vs. Universal Morality?" - that is we will explore the question of whether or not these two dimensions of international relations are compatible or competitive with each other.</p> </div>','DWA 101 . Open only to DWA majors with junior or senior standing.',NULL,NULL);
INSERT INTO course_descriptions VALUES(87,2022,129,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-340','<div class="desc"> <p>International law has taken an increasingly central, and often controversial, place in contemporary international relations. This junior writing seminar will explore the foundations of international law, human rights law, and humanitarian law. It will do so in the context of their intersections with topical issues that range from international criminal law, torture, non-state transnational actors, humanitarian interventions, and sexuality, and will have a particular focus on the theoretical foundations for human rights. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(88,2022,131,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/100/econ-101','<div class="desc"> <p>An introduction to the economic way of thinking that includes both micro- and macroeconomic topics. We begin with an analysis of how market supply and demand help allocate resources and discuss market power, market failures, and the role of government regulation. We explore the determination of gross domestic product, the problems of unemployment and inflation, and macroeconomic policy making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(89,2022,132,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/100/econ-102','<div class="desc"> <p>A continuation of ECON 101 that completes the coverage of economic principles by incorporating the development of more sophisticated analytical tools. Microeconomic topics include: production costs, the behavior of firms under different market structures (competition, monopoly, and oligopoly), taxation and income distribution, and input markets. Macroeconomic topics include: the Keynesian model of output determination, the monetary system, and the effects of fiscal and monetary policies.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(90,2022,133,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/200/econ-233','<div class="desc"> <p>Accounting principles and practices. Recording financial data assets, liabilities, owner equity income, and expenses; preparing and analyzing financial statements. Permission of instructor required for first year student enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(91,2022,134,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/200/econ-250','<div class="desc"> <p>Foundations of microeconomic theory. Topics include: the analysis of consumer theory and decision making; the theory of the firm under perfect competition, general equilibrium, and market inefficiency arising from monopolistic/oligopolistic/strategic behavior; incomplete information; externalities; and public goods. Should be completed before the end of the sophomore year. May be taken before or after ECON 251. Should not be taken in the same semester as ECON 251.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(92,2022,135,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/200/econ-251','<div class="desc"> <p>A study of the factors that influence and are involved with the national economy. Aggregate analysis as applied to problems of national income, accounting and determination, inflation, unemployment, modern economic growth, and the influence of the money supply. May be taken before or after ECON 250. Should not be taken in the same semester as ECON 250.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(93,2019,136,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/ECON-Economics/200/ECON-272','<div class="desc"> <p>The use of regression and correlation to test economic hypotheses. Emphasis will be on the use and interpretation of single equation regression techniques rather than on their derivation.</p> </div>','ECON 102 ; Calculus 1 and MATH 146 or equivalents; one additional Economics course above ECON 102 ; and familiarity with computers. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(94,2022,138,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-311','<div class="desc"> <p>Economic activity in a global context. The first part of the course covers the causes and consequences of international trade, with a consideration of both national welfare and income distribution issues. Coverage then turns to trade policy in theory and practice, with a focus on the current global trading environment under the World Trade Organization. The course finishes by examining international investment and debt issues, including the role played by the International Monetary Fund during global financial crises. May not be taken for credit by students who have taken DWA 220/POL 232.</p> </div>','ECON 102 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(95,2022,139,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-328','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women and minorities. Topics include: the economics of slavery, racial and sexual discrimination, labor market segmentation, wage differentials, labor force participation, red-lining, and income inequality. Relevant public policy issues such as affirmative action and welfare will also be addressed. Permission of instructor required for students who have successfully completed ECON 327 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(96,2022,140,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-350','<div class="desc"> <p>This course covers the application of economic theory and analytical tools to business and management decision making. Topics to be covered will include examples from a variety of fields, including: pricing, ethics, entrepreneurial startups, strategy, new products, acquisitions, marketing, human resources, and leadership. The course will include seven required writing assignments and 18 case studies with required student participation. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(97,2019,142,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/ECON-Economics/400/ECON-495','<div class="desc"> <p>An intensive application of economic analysis to issues chosen by the instructor in consultation with students during the course. The course emphasizes the development of analytical writing team-work and presentation skills and is meant to be an opportunity for students to apply their economic training to specific topics. Complete descriptions of the seminars offered in a given year will be mailed out to students prior to the Spring registration. Senior status is required for this course. Students who will be off campus in the fall of their senior year must contact the department chair by the end of their junior year to arrange a substitute senior seminar. </p> <p><strong>Section 1 - Austrian Economics:</strong> </p> <p>This seminar investigates an alternative approach to economics the Austrian School of Economics which emphasizes methodological individualism and subjectivism. The Austrian School traces its roots back to the works of the Spanish Scholastics of the sixteenth century and stress the importance of the individual private property limited government and the organizing power of the free-market. Students will read from authors such as Menger Mises Hayek Rothbard and Hoppe and evaluate various properties of a state-planned economy versus a decentralized free market economy. </p> <p><strong>Section 2 - </strong><strong>Open Economy Macroeconomics</strong></p> <p>In this section of Economics 495 we will build a theoretical framework and read empirical studies that allow us to understand many interesting questions in international macroeconomics: What is the role of monetary and fiscal policy in open economies? What are the tradeoffs between fixed and flexible exchange rates? How and why did the European Union evolve? How does the international financial system work? How do financial crises emerge and what can we do about them? Should we be concerned about balance of payment imbalances? A variety of class formats will be used, including mini-lectures, classroom discussions, and student presentations. Students write several short papers, participate in the analysis of Harvard Business School Cases and make an individual final presentation based on their final paper. <em>Prerequisites: Economics 272 (may be taken concurrently) and Economics 251.</em></p> <p><strong>Section 3 - <strong>Firm-level International Trade and Investment</strong></strong></p> <p>This seminar studies firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. Topics discussed include the decision to export, foreign direct investment, outsourcing/offshoring, GATT/WTO and various trade agreements. We use modern trade theory to analyze firm decision-making and also learn how firms engage in international commerce from empirical studies and business case studies. <em>Prerequisites: Economics 272 (may be taken concurrently) and Economics 250. May not be taken by any student who has taken or is planning on taking Economics 352.</em></p> <p><strong>Section 4 - <strong>Health Economics</strong></strong></p> <p>This seminar provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. <em>Prerequisites: Economics 272 (may be taken concurrently) and Economics 250. </em></p> </div>','ECON 272 (may be taken concurrently) and either ECON 250 or ECON 251 Section 1: ECON 272 (may be taken concurrently) and ECON 250 . May not be taken by any student who has taken or is planning on taking ECON 309 . Section 2: ECON 250 ( ECON 272 is helpful) May not be taken by any student who has taken or is planning on taking ECON 326 . Section 3: ECON 272 (may be taken concurrently) and ECON 250 . Section 4: ECON 272 (may be taken concurrently) and ECON 250 . May not be taken by any student who has taken or is planning on taking ECON 302 .',NULL,NULL);
INSERT INTO course_descriptions VALUES(98,2022,143,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/400/econ-498','<div class="desc"> <p>Independent research with one-on-one faculty mentoring. After a brief introduction to economic research methods, students will develop a topic and then write and present a senior thesis. Only open to seniors. Permission of instructor and department chair required.</p> </div>','ECON 250, ECON 251, and ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(99,2022,145,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/100/educ-140','<div class="desc"> <p>Occidental students work in the Academic Commons one-on-one with children from the community. While incorporating arts and integrating technology, students will engage their child with a variety of Language Arts activities in order to reconnect their child with the joy of reading and writing for pleasure. Students will build on their child''s strengths, skills, and interests by using culturally relevant pedagogy and critical literacy explorations. Students become part of a high-warmth, low-criticism community. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(100,2022,146,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-201','<div class="desc"> <p>In this introductory course, students study, as a community of learners, the historical, philosophical, political, sociological, economic, and psychological foundations of U.S. education in the public school. Using a variety of analytical lenses, students will critically engage with key texts to examine factors that influence power, control, and the quality of schooling for urban communities. Throughout the semester, we will focus our analysis on the possibility and potential of achieving "socially-just" relationships in urban school communities through teacher practice, educational leadership, and community-based activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(101,2022,147,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-205','<div class="desc"> <p>Analysis of the English language development of listening, speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public-school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction, sheltered/SDAIE approaches, English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(102,2022,148,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-207','<div class="desc"> <p>How are the American values of equity and opportunity evident in the history and structure of the nation''s public-school system? This course examines key U.S. Supreme Court decisions and the following areas of policy debate and conflict, with particular emphasis on the Constitution: bilingual education funding/expenditures, immigrant education, desegregation, special education, affirmative action, and equal resources.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(103,2022,149,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-215','<div class="desc"> <p>This course critically examines the history of the education of Africans in the United States, beginning at the Middle Passage, through Reconstruction and the post-bellum South, to contemporary post-industrial urban contexts. Emphasizing the sociohistorical and political-economic dimensions of schooling African Americans, the course explores the role of key factors in shaping the academic "success" and "failure" of Black students historically and in current K-16 contexts. Analysis of case law policy and practice will inform our understanding of African American experiences in schools nationally and locally. Further, we consider the implications these experiences hold for democratic participation and the overall life chances of African American citizens.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(104,2022,150,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/300/educ-300','<div class="desc"> <p>This seminar will provide students with an opportunity to gain field experiences in an educational setting in urban Los Angeles. Students will select either a public school, a community-based organization, or a policy-making group as a site in which to develop a field-based research project. Regular meetings of this seminar will guide students as they spend the semester in a carefully crafted and mutually agreed upon "internship/fieldwork" experience that will culminate in a semester-end project report that addresses an educational issue of import to the fieldwork site. May be repeated once for credit.</p> </div>','EDUC 201 and EDUC 207; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(105,2022,151,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/300/educ-314','<div class="desc"> <p>Principles and techniques for creating teacher-student-text interactions, vocabulary development, and comprehension and study skills in all school subjects for all students (including English language learners) at the junior high and senior high levels. Topics include: diagnostic procedures; activating background schemata; English language development; different instructional models; and constructivist-based instructional materials, skills, development, standards-based and high-stakes assessment, reading for English language learners/speakers, and procedures for improving students'' reading habits and interests.</p> </div>','EDUC 201 and EDUC 205 (may be taken concurrently); or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(106,2022,165,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/100/fren-101','<div class="desc"> <p>Introduction to French through a variety of communicative approaches. Emphasis is placed on speaking and listening, as well as grammar and writing. Students who have had more than one year of French in high school, or more than one quarter in college, may not take this course for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(107,2022,166,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/100/fren-102','<div class="desc"> <p>This course is a continuation of FREN 101. Students are introduced to the culture of the French-speaking world through readings and discussions.</p> </div>','FREN 101; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(108,2022,167,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/100/fren-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(109,2022,168,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/200/fren-201','<div class="desc"> <p>Oral work and composition based on the study of 20th century cultural history and contemporary issues of the French-speaking world. Integrated language laboratory program for aural comprehension and pronunciation. Advanced grammar.</p> </div>','FREN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(110,2022,169,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/200/fren-251','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(111,2022,170,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-355','<div class="desc"> <p>Readings and discussion in the French novel and philosophical texts, including works by Prévost, Diderot, Rousseau, Bernardin, de Saint-Pierre, Balzac, Stendhal, Flaubert, and Zola.</p> </div>','FREN 202; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(112,2022,171,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/100/geo-105','<div class="desc"> <p>Introduction to Geology with emphasis on the physical processes that shape the environment on the Earth''s surface. The course will cover the fundamentals of plate tectonics, rocks, minerals, geologic time, surface processes, and Earth''s interior. Special attention will be paid to geologic hazards (such as earthquakes, volcanoes, floods, and landslides), the history and future of global climate change, and the human impact on the environment. <em>Includes one two-hour laboratory per week and a one- or two-day field trip.</em> Students who have completed a substantive introductory Geology course are encouraged to seek permission of the instructor to enroll in any of the 200-level Geology courses.Open only to first- and second-year students.</p> </div>',NULL,'GEO 105L ',NULL);
INSERT INTO course_descriptions VALUES(113,2022,173,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-225','<div class="desc"> <p>Southern California’s spectacular geology is the natural laboratory for this project-based course. Working collaboratively, students will investigate geologic questions through fieldwork in the nearby deserts and mountains. The course will expand upon geologic knowledge from introductory geology classes and introduce students to the scientific processes and techniques geologists employ to understand the Earth and other planets. Special emphasis will be placed upon systematic field data collection using mobile GIS-based systems and communication of scientific results. The course will provide students from any major the opportunity to explore our local natural setting and actively participate in scientific inquiry. No experience beyond GEO 105 or GEO 106 is expected of participants and all equipment will be provided. </p> </div>','GEO 105 or GEO 106 ','GEO 225L ',NULL);
INSERT INTO course_descriptions VALUES(114,2022,179,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(115,2017,180,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/GEO-Geology/400/GEO-490','<div class="desc"> <p>This class focuses on student Senior Comprehensives research and covers proposal writing data analysis preparation of illustrations and oral and written presentation of research projects. Journal readings and discussions on topics related to student research are integral to the course. Careers and graduate school options in the Earth Sciences are also discussed.</p> </div>','Open only to senior Geology majors.',NULL,NULL);
INSERT INTO course_descriptions VALUES(116,2022,181,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/100/germ-101','<div class="desc"> <p>Introduces basic language skills, grammar, pronunciation, oral communication, and reading simple prose. Culture taught through readings, videos, and discussions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(117,2022,182,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/100/germ-151','<div class="desc"> <p>Oral practice based on articles in current periodicals and other subjects of general interest. Taught by a German language assistant from the University of the Saarland, under the supervision of a German instructor. Designed primarily for students who have completed GERM 102. Graded on Credit/No Credit basis; attendance is mandatory. Approximately two hours of work outside of class time required each week. May be repeated for credit.</p> </div>','GERM 102; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(118,2022,183,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-201','<div class="desc"> <p>An advanced course to build up comprehension, as well as oral and writing skills. Reading and discussion of literary and cultural texts supplemented with video films and T.V. news on current events in Germany. Practice in essay writing.</p> </div>','GERM 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(119,2022,184,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-251','<div class="desc"> <p>Open to all qualified students, but designed primarily for students preparing for Occidental-in-Germany program. May be repeated for credit.</p> </div>','GERM 152; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(120,2022,185,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-370','<div class="desc"> <p><strong>Bertolt Brecht and the Twenties</strong></p> <p>Bertolt Brecht is one of the most influential playwrights and aesthetic thinkers of the 20th century. In order to understand the scope and dimension of his work and its world wide influence, this course will focus on the artistic development of young Bertolt Brecht who, in the early 20''s, moved to Berlin, the capital of newly founded democratic Weimar Republic, and one of the most important cultural centers of the 20th century, and participated in practically all innovative tendencies and art forms of the time, from Expressionism and Dadaism to New Objectivity, from experimental theatre to radio and film. Some of his great early works, such as the <em>Three Penny Opera, </em>will be seen in the context of the time, especially the very turbulent last years of the Weimar Republic before Hitler''s rise to power. We will also look at Brecht''s legendary film<em> Kuhle Wampe,</em> and visit at least one contemporary production of a Brecht play staged at a theatre in Los Angeles. </p> <p><strong>Bertolt Brecht: The Great Plays</strong></p> <p>Brecht''s great plays changed the stage of world theatre. In order to understand and appreciate their powerful and long lasting influence, all major plays written during Brecht''s exile - i.e. in the years between 1933, when he was driven out of Germany, and 1948, when he returned to Switzerland and, ultimately, Berlin - will be discussed. Aside from detailed analyses of plays such as<em> Mother Courage, The Good Woman of Sezuan, The Caucasian Chalk Circle, </em>or <em>Life of Galilei,</em> Brecht''s developing theory of epic theatre, and the general conditions and dilemmas of exile, will be discussed. We will also look at Brecht''s role in Hollywood, his collaboration on the film <em>Hangmen Also Die</em>, and his successful attempts to direct his own plays on German and European stages after 1950. Students minoring in German or majoring in Group Languages or IPS will read most of the texts in the original language. </p> <p>Prerequisite for German minor and Group Language majors: GERM 202 or GERM 232. Open to all other non-first year students. The course is taught in English; no knowledge of German is required. </p> <p><strong>Memory, Trauma, and Victim Culture</strong></p> <p>This course is concerned with the cultural politics of memory and trauma after the catastrophic events of the Holocaust and World War II. We will start with basic questions such as: whose memories are sought and commemorated in the public sphere? What problems do traumatic events present for those attempting to represent them? Is trauma a useful cultural concept? What are the differences between individual and collective memory? The first part of the course analyzes memory and trauma on both the individual level and the collective level, and turns, then, to the specific processes that occur when traumatic events are remembered by survivors, as well as the collective processes involved when memories of traumatic events, such as the Holocaust, are shared with an audience who has no first-hand experience of them. The second part of the course aims to identify the recent fascination, especially in European and American culture, with the phenomenon of trauma, suffering, and victimhood. We will study the cultural politics of trauma and memory in relation to two events - the Holocaust and German suffering during World War II. The unit "Holocaust, Victimhood, and American-Jewish identity" explores how the kitsch nature of popular culture representations of the Holocaust (from the Anne Frank movie, to the very successful TV-series <em>Holocaust, </em>to the Hollywood movie <em>Schindler''s List</em>) created the paradigm for trauma culture at large. The unit "Germans in Collective Memory Between Perpetrators and Victims" discusses contemporary German memory discourse, which primarily focuses on the experience of German suffering as a consequence of the war and the Third Reich. However, to recast Germans as victim is highly problematic since the position of victim is already occupied by those people who were persecuted and murdered by the Germans/Nazis. Memory, trauma, and victimhood are crucial aspects of the experiences of Jews and Germans after 1945. A systematic exploration of these aspects (as manifested in a broad variety of cultural forms) promises important insights into recent history and culture. </p> <p><strong>Nazi Culture</strong></p> <p>After the Nazis came to power in 1933, they took over control of all aspects of German life. One of the first tasks the new government undertook, upon their ascension to power, was a synchronization of all professional and social organizations with Nazi ideology and policy. Joseph Goebbels, Nazi Minister for Popular Enlightenment and Propaganda, began an effort to bring German arts and culture in line with Nazi goals. The government purged cultural organizations of Jewish persons and other officials alleged to be politically suspect, or who performed or created art works that Nazi ideologues labeled "degenerate." Some 650 works, by such renowned artists as Max Beckmann, Marc Chagall, Otto Dix, Wassily Kandinsky, and Paul Klee, were declared "degenerate art" and removed from German museums. The Nazi "cultivation of art" also extended to the modern field of cinema, theater, music, architecture, youth education, and even to the lower levels of popular culture. Throughout the duration of the Nazi regime, "culture," in all its manifestations, played a crucial role. Political rallies, military parades, sports events, open air festivals, and other skillfully organized events were used, from the beginning, to suggest a "national awakening" and the "revolutionary spirit" of the new regime. The efforts of the Nazis to regulate German culture corresponded to what historian George Mosse calls an effort "toward a total culture" - i.e. an effort to influence, at the most basic level, the lives and actions of all Germans. This course will explore the various forms of culture during this time and will raise the question as to what extent "Nazi culture," or culture under Nazi domination, was capable of stabilizing the regime until its very end in 1945. Students minoring in German or majoring in Group Languages will read some of the course material in its original German. </p> <p>Prerequisite for German minor and Group Language majors: GERM 202 or GERM 232.</p> <p><strong>Marx Freud and the Frankfurt School</strong></p> <p>This seminar will explore the origins of the world famous Frankfurt School, a group of German social philosophers and theoreticians, which emerged at the Institute for Social Research of the University of Frankfurt am Main in the 1920''s. The group wanted: (1) to analyze the conditions of modern capitalism and its impact on society in general, on family and social structures, value systems, and mass culture; (2) critically review the theories of Karl Marx, Sigmund Freud, and Max Weber; and (3) to establish the principles and foundations of a "critical theory." We will read and discuss major works by Max Horkheimer, Theodor W. Adorno, Walter Benjamin, Herbert Marcuse, Erich Fromm, Siegfried Kracauer, Leo Loewenthal, and others. The seminar will focus on the "first phase" of the Frankfurt School, its beginnings and its work and development during the 30''s and 40''s - when the school relocated to New York and many of its collaborators lived in other American cities or abroad - and the immediate post WWII period. (A second seminar will follow next year and explore the school''s development and its world wide impact in the 60''s and 70''s.) The course is taught in English. Students minoring or majoring in German will read some of the original texts (especially Marx, Freud, Benjamin, and Kracauer,) that are written in German. Open only juniors and seniors.</p> <p>Cross-Listed as: CTSJ 370.</p> <p><strong>The Frankfurt School 1945 to the Present</strong></p> <p>Social analysis, cultural theory, and political action. This seminar will explore the history of the Frankfurt School after World War II when it was re-established in Frankfurt and began to play a crucial role in the development of a "critical theory" of society and culture during the West German "economical miracle;" afterwards, with the onset of the German (and international) student movement of the mid-60''s, it gained international reputation and impacted social, political, and cultural discourses in countries like France, Great Britain, Italy, and the United States. We will study, primarily, some of the major writings of Theodor W. Adorno (especially on art, music, cultural theory, and the lessons of Fascism), Herbert Marcuse (whose writings on social theory and aesthetics, "repressive tolerance," and "liberation" exerted a strong influence on the student movement), and of Jurgen Habermas, who became one of the most influential European intellectuals in the decades after 1970. This seminar is the continuation of an earlier class on the beginnings of the Frankfurt School and its history until 1945; participation in that earlier seminar is not required. The course is taught in English. Students minoring in German or majoring in Group Language or IPS will read some of the original texts in German.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(121,2022,186,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/100/grk-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Ancient Greece. Students will engage, from the beginning, with original texts from Homer, Sophocles, Plato and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Greeks, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(122,2022,187,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/200/grk-201','<div class="desc"> <p>Homer''s epics feature some of the best known, and varied, heroes of antiquity, like Achilles, Hector, Odysseus, and Penelope. In this class, we will read selections from the <em>Odyssey </em>and <em>Iliad </em>as a way to examine ancient conceptions of heroism. For students studying ancient Greek, this will primarily be a translation course and will serve as an introduction to epic poetry. Students without Greek are also welcome and can expect to approach the topics of the class by reading translated texts and modern scholarship.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(123,2022,188,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-101','<div class="desc"> <p>This course is an introduction to early North American/U.S. history, reaching from colonization to the Civil War. Of particular interest in this course will be the theme of cross-cultural interactions in the midst of transforming economies, an expanding nation, and unequal power relations. We will combine a broad introduction to early American history with an in-depth look at five case studies of individuals and communities encountering each other across borders of nation, religion, race, gender, ethnicity, and class. Each case study offers a unique perspective on the question of how broad economic structures of colonization, slavery, and the market revolution shaped human encounters between natives and newcomers, captives and captors, slaves and slaveholders, Northerners and Southerners. Ultimately, these case studies encourage a critical rethinking of concepts of liberty, equality, and democracy, which have formed the bedrock of master narratives in United States history. Within the context of these broad, sweeping themes, we will look closely at primary historical documents, produced by men and women of their time period, and we will carefully read the arguments of historians in our own time. The class will emphasize history as a process of critical interpretation.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(124,2022,189,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-141','<div class="desc"> <p>A survey of Chinese, Japanese, and Korean societies from the emergence of states to the present. Several themes explored include: the development of strong, centralized states; the emergence of a shared elite culture; the spread of popular religions; the continuing interaction between East Asian and other societies; contrasting roads taken by each society in order to meet the challenges of modernity; conflicts over imperialism, nationalism, and revolution; cultural debates over gender and generational issues. Finally, a review of the post-WWII era: opposing alignments in the Cold War; socialist state building and experimentations; military rule; democracy; mass culture; successive economic "miracles," and China''s re-emergence as a global power.</p> <p><strong>Survey Requirement Met:</strong> Asia</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(125,2022,190,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(126,2022,191,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-206','<div class="desc"> <p>This course will examine the variety of female experiences in 19th and 20th century America by looking at the class, racial, and ethnic dimensions that shaped women''s lives. A second major concern will be to study women in the context of the historical developments of their time; reform movements, westward migration, industrialization, and urbanization will be examined in light of their impact on women''s experiences and values. The course will also consider a number of themes, including: popular images of women, women and sexuality, women and the family, women and work, women as consumers, and women as reformers.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(127,2017,192,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/HIST-History/Europe/200/HIST-223','<div class="desc"> <p>History of France and of French creativity in literature and in the visual arts from the High Middle Ages to the Age of Enlightenment (12th to 18th centuries). <em>Students may petition for 300-level credit for this class with the completion of additional work arranged with the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(128,2022,193,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-234','<div class="desc"> <p>The class examines the political, social, and economic crises that shook the nations of Europe in the two decades following the First World War. In particular, we address the character of the crisis; the varied European responses to it; and the challenges represented by the end of the First World War, Depression, Fascism, the Second World War, and the Holocaust. While assessing the nature of the social, political, and economic crisis of interwar Europe, we will also pay close attention to historiographic debates on the rise and nature of Fascism and the origins of the Second World War. We focus strongly on primary sources such as the novels, film, and art of the era. Topics include: the "Lost Generation," the Weimar Republic, the Spanish Civil War, and the Popular Front in France.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(129,2022,194,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-242','<div class="desc"> <p>A chronological and thematic survey of the Chinese civilization from Neolithic times to about 1600. Major themes will include: the nature of the Chinese world order, family and lineage, gender issues, philosophical and religious transitions, political authority and its ideological underpinnings, dynastic cycles and broader patterns in socio-political movements, interactions with other civilizations, and the impact of technological and demographic changes over time. We shall use the comparative approach on specific themes to illuminate contrasts and similarities between Chinese and Western societies, and take note of recent archeological finds and new scholarly interpretations to better understand China''s dynamic past and rapidly changing present.</p> <p><strong>Survey Requirement Met:</strong> Asia</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(130,2020,195,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-247','<div class="desc"> <p>This survey will examine Japanese history from the emergence of the samurai class in the 12th century, to the Mejii Restoration of 1868. We will begin by considering the origins, and rise to power, of warriors as a discrete social group. Next, we will look at the balance of power between the Kyoto court, the new warrior government in Kamakura, and the powerful Buddhist institutions that defined the culture of the Medieval period. We will then examine the disintegration of central authority under the rule of the Ashikaga shoguns, leagues, and other local attempts to organize independently, and the concomitant cultural efflorescence of the 15th and 16th centuries. The course will conclude by examining the political structures, popular culture, and social stratification of the early modern (Edo or Tokugawa) period.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(131,2022,196,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-249','<div class="desc"> <p>Korea is unique, or so say the Koreans. In many ways, it is. Politically, of the democratic nations in the world, South Korea is one of the precious few to have achieved democracy through the blood and sacrifice of its everyday citizens, that is, from the bottom up. Economically, after the Korean War, Korea was one of the poorest nations in the world, ranking below sub-Saharan countries in terms of GDP; now it is a member of the G20. This survey will begin with the forced opening of the "Hermit Kingdom" in 1872, and conclude with the 21st century international phenomenon of K-pop.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(132,2022,197,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-258','<div class="desc"> <p>This course seeks to engage you in the fundamental problems of twentieth century Mexican history and introduce analytical frameworks for studying cultural politics. The central theme will be how the state and grassroots society negotiated the course of the nation and its political culture since 1875. We will critically examine the production of the dominant historical narrative and develop alternative ones that can help us understand the differences in the historical experiences of subaltern groups, including women, indigenous people, and <em>campesinos </em>within the Porfirian, revolutionary, and post-revolutionary periods. We will examine what is cultural about politics and what is political about culture through an interdisciplinary format, perspective and organization drawing upon the fields of history, anthropology, literature, and visual studies.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(133,2022,198,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-277','<div class="desc"> <p>This course explores the history of women as promoters of community health in the nineteenth- and twentieth-century United States. Although women have not traditionally held power in mainstream biomedical occupations and institutions, women have nevertheless been critical to health and healing in local communities as caregivers, activists, and practitioners. At times, working class women and women of color have also been demonized as carriers of contagion or even romanticized as repositories of traditional wisdom. Furthermore, women’s roles in community health have been heavily shaped by gendered and racial constructions of the body, disease, and wellbeing. Thus, while the focus of the course is on the social history of women’s health and healing, the theoretical framework of the course also aims to explore how ideologies of gender, race, class, and sexuality shape women’s relationship to community health as both caregivers and health-seekers. The course is organized by a set of common themes that cut across time, space, and racial/ethnic boundaries in U.S. History. Themes include: spirituality and healing; work and health; sexuality and reproduction; activism for health justice. An important goal of this course is to make connections between historical studies of women and health and present-day community health activism. Much of the course and especially the community partnership component focuses on the leadership of women of color in shaping agendas for community well-being. In the past, course participants have worked with the organizations Black Women for Wellness, California Latinas for Reproductive Justice, Visión y Compromiso, and Promesa Boyle Heights. We will continue to work this year with women’s health organizations and the Southern California Library on a Reproductive Justice community partnership. In addition, we will welcome several community health activists &amp; scholars to the class as guest speakers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(134,2022,199,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-282','<div class="desc"> <p>The term "Muslim World" is often criticized as imprecise. After all, Muslims constitute a fifth of humanity and live on six different continents. Nevertheless, Muslims often describe themselves as constituting a single community with shared sets of concerns. This class engages these differing views through an examination of the lives of Muslims over the past two centuries of globalization, colonialism, post-colonialism, nationalism, and ever-changing technologies of transportation and communication. Our inquiry will concentrate on how Muslims were caught up in, and reacted to, and, in turn, influenced the Great Transformation that reshaped the entire world over the past two centuries. Dealing with issues from state building to women''s rights to radical militancy, this class considers the various features of what we might call Muslim Modernity.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(135,2022,200,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-295','<div class="desc"> <p><strong>The Contested Ballot in American History</strong></p> <p>Voting is fundamental to American democracy. It is, one nineteenth-century reformer argued, “like breathing.” And yet across the nineteenth and twentieth centuries, vast numbers of Americans (at times even a majority of Americans) have been denied access to this fundamental democratic practice. This class investigates the curious and contested history of the ballot throughout American history. We will focus on both the formal rules governing the right to vote (state constitutions and federal interventions via constitutional amendment, SCOTUS decisions, and legislation) as well as the culture and practice of voting (ballot design, the timing of elections, and procedures around registration. The class will culminate with an examination of the state of voting in America in 2020 (the specifics to be determined as the election unfolds). </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(136,2022,201,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-300','<div class="desc"> <p>This course introduces students to the practice and writing of history through topical approaches. Students will explore methodological approaches to historical inquiry, conduct research projects, and improve their writing skills. Open to majors and minors only or by permission of instructor. Topics include:</p> <p><strong>Native American and Indigenous Histories</strong></p> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that scholars use to write Native American and Indigenous histories. The course highlights the field of ethnohistory, the interdisciplinary study of indigenous societies and cultures that draws from history, anthropology, archaeology, linguistics, and art history. The readings address the histories of First Nations peoples of North America, Central America, and South America, and explore a variety of topics, including native governance, sovereignty and resistance, lands and removals, wars, indigenous slavery, relations with the environment, gender and sexuality, and reproductive rights. The course is organized to illustrate major trends in ethnohistorical scholarship, and highlight shifts in themes, methods, and narrative frameworks over the last five decades.</p> <p><strong>Mexico-U.S. Borderlands</strong></p> <p>Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. Cross-Listed as: LLAS 304.</p> <p><strong>Christianity and Politics in America since 1945</strong></p> <p>Evangelicals and the Christian Right have become hot topics, but religion has long played an important role in the U.S. political arena. This junior historiography seminar will survey how historians have written about the relationship between Christianity and politics in America since the end of World War II. Much of the course will focus on histories of the Religious or Christian Right and its 1970s marriage with the Republican Party, which remains one of the most successful political partnerships in American history. But we will also trace the roots of this relationship in earlier histories about the role of the Protestant church in public life, Billy Graham''s rise to fame, and the work of Christians and other religious leaders in shaping U.S. engagement with the world during the Cold War.</p> <p><strong>The Fascist Revolution: Politics Culture and Society</strong></p> <p>This seminar closely studies the period known as Fascist Italy (1922 to 1945). Through a close analysis of the politics, culture, and society of Italy under Fascist dictatorship, we study the causes, character, and ramification of the Italian abandonment of democracy in the wake of World War I. Because it is a historiographic seminar, we examine the central debates of the field, such as whether Mussolini ruled primarily through coercion or consent, the extent of Fascist race ideology, and whether the regime was "modern" or "backward-looking." Other major themes include: Fascist cultural modernism, gender and Fascism, and the Italian road to empire and World War II. This course uses primary sources such as translated documents, memoirs, and diaries, as well as contemporary historical analyses. </p> <p><strong>Gender and Sexuality in Colonial Latin America</strong></p> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.<br/> <br/> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written. Cross-Listed as: LLAS 301.</p> <p><strong>Histories of the French and Haitian Revolutions</strong></p> <p>Many histories have been, and continue to be, written about these revolutions and they differ from each other substantially. This course examines this scholarly literature, taking into account the choices historians make as they compose their narratives. We will examine the roles of race, class, and gender in these accounts, why different events and social groups are featured centrally in some but not others. And we will consider such controversial criteria as "accuracy," "truth," "evidence," and even "fact" all of which are interpreted in numerous ways within the historian''s craft. </p> <p><strong>Histories of U.S. Empire</strong></p> <p>Was/Is the United States an empire, and if so, what kind of empire was/is it? This upper-level colloquium will familiarize history majors and other advanced students with scholarly debates over the history of U.S. imperialism and engagement in the world. Course readings draw from the writings of U.S. historians from the early twentieth century through the present. Particular attention will be given to the impact of the Cold War and the influence of the "cultural" and "transnational" turns on how historians have approached empire.</p> <p><strong>Interpreting Civil War, Emancipation, and Reconstruction</strong></p> <p>This junior colloquium will address major debates and approaches within the historiography of the United States Civil War, Emancipation, and Reconstruction. Students will explore how American racial politics and new scholarly approaches have shaped major debates over the causes and consequences of civil war and national reconstruction. The class will take both a chronological and topical approach to historiographic analysis. We will begin by reading work from the Dunning School and critical challenges to Dunning from historians on the Left, such as W. E. B. Du Bois in his 1935 study Black Reconstruction. To understand the impact of new methods and sources, we will examine the multi-decade collaboration of social historians called the Freedmen and Southern Society Project. In the second half of the course, we will explore more recent trends in scholarship, including economic history and cultural history, as well as gender and sexuality studies and critical race theory. Finally, the class will conclude by considering historical interpretations of Civil War and Reconstruction in U.S. popular culture, through film, fiction, and drama. Students will write their own historiographic analysis on a chosen topic within Civil War, Emancipation, and Reconstruction scholarship. </p> <p><strong>The Mexican Revolution</strong></p> <p>Studies of the Mexican Revolution have been at the forefront in the development of modern Latin American social, political, and cultural history. The studies have also contributed to comparative discussions in world history about the meanings of revolutionary experience in the twentieth century. However, historians and other social scientists have reached no consensus about the Mexican Revolution from its periodization to its actual existence. This seminar will examine the competing set of interpretations, alongside primary sources, to analyze the origins, course, and legacy of the Mexican Revolution. Prominent historiographical themes for the course include: conflict between elite liberalism and mass mobilization; agrarian reform and unionization within a capitalist project of development; corporate representation of social interests; the institutionalization of revolution; race, gender, and class in nationalist rhetoric; and the role of art, education, and science/technology in state formation. Cross-Listed as: LLAS 302.</p> <p><strong>Re-Assessing European Global Encounters </strong></p> <p>The twentieth century national movements of liberation, from modern European colonialism, initiated new histories of the previous early modern age of exploration (1300-1800), from the point of view of the enslaved, the conquered, the exploited, and the newly liberated. Each student will be writing a historiographical essay revealing changing interpretations of one distinctive global encounter. Historians are re-assessing, on the Mediterranean, both the Crusades and piracy and kidnapping. Scholars specializing in trade or colonialism of a particular nation-state, such as Portugal, Spain, Netherlands, England, and France are re-considering specific settlements and trading ports on the Atlantic and Pacific Rims. Class work will enhance student skills: we shall be discussing exemplary recent historical films and histories and we shall learn how to efficiently find diverse viewpoints through online and printed sources.</p> <p><strong>Reel History </strong></p> <p>This course will examine some of the ways that the history of France has been represented in films. Joan of Arc, The Return of Martin Guerre, Ridicule, The Rise to Power of Louis XIV, Danton La Nuit de Varennes, Abel Gance''s Napoleon, and Night and Fog are among the great movie classics to be analyzed. We will also deal with recent theoretical work on "historical" cinema. Are images as valid as written text when making meaningful connections with the past?</p> <p><strong>Writing the History of the Middle East </strong></p> <p>This course is a junior seminar on recent developments in the research and writing of history as practiced by professional historians of the modern Middle East. We will look at the history of historical writing about the region and the transformative developments in the field over the last thirty years or so. The objective is to cultivate your awareness of historiography and historical criticism. Historiography can be defined as the history of historical interpretation. Historical criticism refers to how we understand history as an object of study. To appreciate various modes of inquiry in the field, we will read exemplary texts embodying established traditions and new departures as well as critical works on the ideological roots of particular fields of history.</p> <p><strong>Writing World History</strong></p> <p>This junior seminar investigates various approaches to writing world history. The course is designed to help history majors understand historiography and historical criticism. By studying recent approaches to world history, students will learn how historical debate shapes the writing of history, how historians approach and critique each other''s work, and how different styles of historical research and writing have developed over time.</p> </div>','Unless otherwise noted, one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(137,2022,204,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-336','<div class="desc"> <p>This course traces the creation and development of the modern Italian nation state from an idea in the early 19th century through its creation in the middle 19th century to its turn to fascism in the 20th century. We will study the challenges faced by Italian politics and society as Italy moved from a disparate group of separate states toward a unified government and culture. We take an interdisciplinary approach to history and look at films, novels, and art to understand the character of modern Italian culture society, and politics. Starting in the late 18th century, the course covers themes such as: the character and legacy of Italian unification, the Southern Question, Fascism, the Mafia and postwar parliamentary democracy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(138,2022,205,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-390','<div class="desc"> <p><strong></strong></p> <p> Research topics vary semester to semester.</p> </div>','Satisfactory completion of at least one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(139,2022,206,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-395','<div class="desc"> <p><strong>American History According to Hollywood</strong></p> <p>This class investigates the way movies have shaped Americans’ understanding of their history. Surveying major developments across the twentieth century and into our own, we will examine films as imaginative primary sources that reveal the attitudes and anxieties of past eras (e.g. concerns about race and ethnicity, global power, gender and sexuality). The last third of the class will turn to a more intensive focus on the way movies have functioned as secondary sources, offering powerful (if partial) interpretations of earlier eras. Here students will focus on a select number of topics or events (e.g. the immigrant experience, WWII, “the West”) and trace the changing historical interpretations the films present. Ultimately, we will evaluate how “cinematic history” compares to “written history” and by what interpretive or evidentiary standards or criteria we should evaluate it.</p> <p><strong>Disneyland and Los Angeles</strong></p> <p>In the summer of 1955, amidst the orange groves of Southern California and next to a brand-new freeway, Disneyland Park appeared. Broadcast across the country through a hit television program that premiered the previous year, the new theme park became an instant national media sensation, drawing on a long and varied tradition of American popular amusements. But, it was also an institution with deep roots in the specific culture and history of greater Los Angeles itself. In this course, we will trace the complex dialogue between the iconic amusement park and its urban environment in Southern California over the last half of the 20th century, carefully analyzing urban and social history, film, and literature to discover what Disneyland can teach us about the history, built environment, and culture of the strange, sprawling megalopolis that surrounds it. </p> <p>Core Requirement Met: United States Diversity</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(140,2017,208,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ITAL-Italian/100/ITAL-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Italian feature film. <em>Graded on a Credit/No Credit basis only; attendance is mandatory. May be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(141,2022,209,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/100/japn-101','<div class="desc"> <p>Introduction to the language in all its aspects, basics of grammar and oral communication and the reading and writing of hiragana &amp; katakana through intensive drills and exercises. Introduction to formal and casual speech styles. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Japanese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(142,2022,210,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/200/japn-201','<div class="desc"> <p>While consolidating their knowledge of grammar basics, students will learn the keigo (honorific forms) system and a variety of additional verb forms, both inflectional and paraphrastic. Increased emphasis on conversational skills, as well as training in composing texts with coherence and accuracy. Introduction of additional kanji and their multiple readings (approximately 200 characters over the two semesters of the intermediate level).</p> </div>','JAPN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(143,2022,211,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/200/japn-273','<div class="desc"> <p>This course introduces literary traditions and aspects of Japanese popular culture under the Tokugawa <em>shogunate</em> (17th through mid-19th centuries), when education spread far beyond the elite samurai class and the people’s literacy rate rose to an unprecedented level thanks to long-lasting peace and economic development. We will primarily explore the rise of <em>haikai</em> (precursor to <em>haiku</em>), travel diaries, humorous oral narratives, and visual arts such as <em>ukiyo-e</em>, and examine how literary traditions practiced since ancient times are represented, transformed, and reinterpreted in those works. The course is given in English. Offered in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(144,2022,212,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/300/japn-301','<div class="desc"> <p>Further development of the four skills. Mastery of certain grammatical forms with increasing emphasis on the speaker''s attitudes or assumptions regarding the situation. Introduction of the humble form in the keigo system. Introduction of additional kanji (approximately 250) and their multiple readings over the two semesters of the advanced level.</p> </div>','JAPN 202 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(145,2022,214,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/100/kine-104','<div class="desc"> <p>Survey of kinesiology subdisciplines: human anatomy, exercise physiology, nutrition, motor learning, and sport and exercise psychology. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(146,2022,215,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/100/kine-196','<div class="desc"> <p>Supervised participation in the work of a nutrition exercise, or other health related company or agency. Permission of instructor required. Graded on a credit/no credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(147,2022,216,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/200/kine-295','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(148,2022,217,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-300','<div class="desc"> <p>This first semester covers musculoskeletal anatomy and provides an in-depth study of bone composition and development; joint morphology; muscle structure, function, mechanics, and movement analysis. Includes one three-hour laboratory per week. Not open to frosh.</p> </div>',NULL,'KINE 300L ',NULL);
INSERT INTO course_descriptions VALUES(149,2022,218,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-300l','<div class="desc"> <p>Three hour per week Human Anatomy laboratory.</p> </div>',NULL,'KINE 300 ',NULL);
INSERT INTO course_descriptions VALUES(150,2022,219,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-301','<div class="desc"> <p>A structural survey of the human body covering the nervous, endocrine, cardiovascular, lymphatic, respiratory, digestive, urinary, reproductive, and integumentary systems. Lecture will also include the special senses of vision, hearing, and olfaction. Includes one three-hour laboratory per week. Not open to frosh.</p> </div>',NULL,'KINE 301 ',NULL);
INSERT INTO course_descriptions VALUES(151,2022,220,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-301l','<div class="desc"> <p>Three hour per week Human Anatomy II laboratory.</p> </div>',NULL,'KINE 301 ',NULL);
INSERT INTO course_descriptions VALUES(152,2022,221,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-306','<div class="desc"> <p>Energy sources for human movement; substrate and energy metabolism during exercise; liver, skeletal, and cardiac muscle adaptations to acute and chronic exercise training.</p> </div>','CHEM 120 and KINE 307 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(153,2022,224,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','KINE 310L ',NULL);
INSERT INTO course_descriptions VALUES(154,2022,225,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'KINE 310',NULL);
INSERT INTO course_descriptions VALUES(155,2022,226,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-395','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(156,2022,227,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-396','<div class="desc"> <p>Supervised participation in the work of a nutrition exercise or other health related company or agency. Graded on a Credit/No Credit basis only. May be taken for up to a maximum of 4 units of credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(157,2022,228,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/100/latn-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Latin. Students will engage, from the beginning, with original texts from Virgil, Horace, Caesar, Cicero and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Romans, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(158,2022,229,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-105','<div class="desc"> <p>This is a topics course for students who would like to take a mathematics course that does not require taking any prior course in college-level mathematics. <em>Not open to seniors.</em><br/> <br/> <strong>Digital Security</strong></p> <p>In this course we will explore the world of digital security and the math that goes into keeping your information safe. Topics will include cryptography, hash functions, blockchain, and bitcoin.</p> <p><strong>Mathematical Thinking</strong></p> <p>Introduction to mathematical thinking. Investigation of mathematical patterns in counting, reasoning, motion and change, shape, symmetry, and position.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(159,2022,230,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-108','<div class="desc"> <p>The first of a two course sequence enriching the material in Calculus 1 with additional study of elementary functions, algebra, trigonometry, graphing, and mathematical expression. Weekly lab.</p> </div>','Calculus Placement Exam ',NULL,NULL);
INSERT INTO course_descriptions VALUES(160,2017,231,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MATH-Mathematics/100/MATH-108A','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(161,2022,232,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-110','<div class="desc"> <p>This course is a traditional first course in calculus covering basic differential calculus. Topics include limits, continuity, differentiation, differentiation rules, as well as applications to the natural and social sciences including optimization. Click here for a more detailed topics list. Weekly lab required.</p> </div>','Calculus Placement Exam ',NULL,NULL);
INSERT INTO course_descriptions VALUES(162,2017,233,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MATH-Mathematics/100/MATH-110A','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(163,2022,234,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-114','<div class="desc"> <p>This course is a more in-depth version of Mathematics 110. Intended for students interested in more mathematical rigor; recommended for students who expect to take mathematics courses beyond Calculus. It satisfies Calculus 1 prerequisites for subsequent courses. Weekly lab.<br/> <em></em></p> </div>','Math Placement Examination ',NULL,NULL);
INSERT INTO course_descriptions VALUES(164,2022,236,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-120','<div class="desc"> <p>This is a standard second-semester calculus course. The topics will include integration, methods of evaluating integrals, sequences, series, and Taylor series. Applications to the natural and social sciences will be included. Weekly lab required.</p> </div>','MATH 109, MATH 110, or MATH 114 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(165,2017,237,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MATH-Mathematics/100/MATH-120A','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(166,2022,238,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-128','<div class="desc"> <p>A one-semester course focusing on infinite sequences and series including power series and Taylor series. More advanced topics will be chosen by the professor which may include: techniques for solving differential equations mathematical modeling, Fourier Series, the Laplace Transform, and the Fourier Transform. The course assumes mastery of the basic skills, particularly integration techniques and differentiation rules from the successful completion of Advanced Placement (AB) Calculus. This course satisfies Calculus 1 and Calculus 2 prerequisites for subsequent courses. Weekly lab.</p> </div>','Permission of instructor or AP Calculus AB score of 4 or 5 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(167,2017,239,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MATH-Mathematics/100/MATH-128A','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(168,2019,240,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/MATH-Mathematics/100/MATH-146','<div class="desc"> <p>Comprehensive study of measures of central tendency variation probability the normal distribution sampling estimation confidence intervals and hypothesis testing. Introduction to use of technology in statistics. Real-life problems are used to illustrate methods. <em>Weekly lab. Not open to students who have completed or are currently enrolled in PSYC 201 BIO 368 MATH 150 or any Mathematics course above 200.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(169,2022,242,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-150','<div class="desc"> <p>An introductory course in statistics, emphasizing modern techniques of data analysis. Exploratory data analysis and graphical methods; random variables, statistical distributions, and linear models; classical, robust, and nonparametric methods for estimation and hypothesis testing; introduction to modern multivariate methods. Students will make significant use of a computer application specifically designed for data exploration. The course is strongly recommended for students who are going to use graphical techniques and statistics for research in their fields. Weekly lab.</p> </div>','A Calculus 1 course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(170,2022,243,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-160','<div class="desc"> <p>Formal and informal techniques for problem-solving developed by working on an intriguing collection of puzzles and problems which go beyond those encountered in the usual curriculum. These include problems which can be posed in elementary, mathematical, or logical terms, but which require strategy and ingenuity to solve.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(171,2022,244,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/200/math-201','<div class="desc"> <p>This seminar course is a writing-intensive Community Based Learning course designed to expose students to the complicated ways in which mathematics affects the community. The CBL component of this course involves tutoring and mathematics assistance at Franklin High School in nearby Highland Park. The seminar component involves meeting weekly with processing discussions and discussion of readings. Topics will include the teaching and learning of mathematics, as well as the role of mathematics in individuals'' lives and their community. May be taken twice for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(172,2022,245,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/200/math-210','<div class="desc"> <p>The language of sets and logic, including propositional and predicate calculus. Formal and informal proofs using truth tables, formal rules of inference, and mathematical induction. Congruences and modular arithmetic. Elementary counting techniques. Abstract relations including equivalence relations and orders.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(173,2022,246,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/200/math-212','<div class="desc"> <p>Calculus of functions of several variables, parametric curves and surfaces, and vector fields in 2- and 3-space with applications. Vectors, graphs, contour plots. Differentiation with application to optimization. Lagrange multipliers. Multiple and iterated integrals change of variable, and the Jacobian. Line and surface integrals. Vector analysis, Green''s, Gauss'', and Stokes'' Theorems. Applications to physics economics chemistry and mathematics.</p> </div>','A Calculus 2 course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(174,2022,247,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/200/math-214','<div class="desc"> <p>Introduction to basic concepts of linear algebra through the study of linear algebraic systems and matrix algebra. Topics include: an introduction to planes and lines, vector operations, subspaces, Gaussian elimination, linear independence, invertibility of matrices, orthogonality matrix operations, eigenvalues, and eigenspaces. The course stresses definitions and mathematical proof.</p> </div>','A Calculus 2 course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(175,2022,248,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-310','<div class="desc"> <p>A beginning course in advanced calculus and real analysis. Properties of the real number system, sequences and series of real numbers, the Heine-Borel and Bolzano-Weierstrass Theorems, continuity and uniform continuity sequences, and series of functions.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(176,2022,249,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-330','<div class="desc"> <p>Standard methods of calculus are used to study probability: sample spaces, random variables, distribution theory, estimating unknown parameters of distributions. Various applications to real life problems will be discussed. Moment-generating functions and other techniques to calculate moments and characterize distributions. Probabilistic inequalities and the central limit theorem. Point estimators and unbiasedness.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(177,2022,251,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-370','<div class="desc"> <p>This is a first course in studying numerical techniques in solving a variety of problems in mathematics using computer algorithms. Topics can include: methods for approximating solutions to algebraic equations, iterative methods for linear and nonlinear systems, interpolation and approximation, theory numerical integration, explicit and implicit methods for solving initial value problems, and boundary value problems. Error, estimation, stability, and performance are themes throughout. Students will be expected to be able to execute standard algorithms using a computer programming language by the end of the course.</p> </div>','MATH 212 and MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(178,2022,252,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-395','<div class="desc"> <p>Special topics in advanced mathematics selected largely by student interest and faculty agreement. May be repeated for credit. </p> <p style="color: #000000;"><strong>Real Analysis II</strong></p> <p style="color: #000000;">This is a second course in real analysis, further developing the concepts presented in MATH 310. Topics may include basic measure theory, the Lebesgue measure and Lebesgue''s theory of integration, normed linear spaces, and a rigorous treatment of limits and calculus in multidimensional spaces.</p> <p style="color: #000000;">Prerequisite: MATH 214 and MATH 310 or permission of instructor.</p> <p><strong>Advanced Differential Equations </strong></p> <p>The course will consist of advanced topics in differential equations not usually seen in either ordinary differential equations or partial differential equations, such as: delay differential equations and stochastic differential equations. Boundary value problems, numerical methods, and infinite series solutions. </p> <p> Prerequisite: MATH 340 or MATH 342 or permission of instructor. </p> <p><strong>Knot Theory</strong></p> <p>How knots are described mathematically, how one can distinguish different knots, create new knots, classify knots. Topics include: Reidemeister moves, links, knot colorings, alternating knots, braids, knots and graphs, knot invariants, mirror images, unknotting, number crossing, number applications to biology and chemistry.</p> <p>Prerequisite: MATH 210, MATH 212, or MATH 214 or permission of instructor</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(179,2022,253,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/400/math-400','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Introduction to Knot Theory</strong></p> <p>We learn how mathematics is used to understand knots and links, covering topics such as prime and composite knots, knot colorability and other invariants, and links in graphs.</p> <p><strong>Applied Mathematics</strong></p> <p>This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> <p><strong>Euler to Uhlenbeck (History of Mathematics)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Spring semester seminar will cover Euler to Mirzhakani and Uhlenbeck. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>Euclid to Newton (History of Mathematics)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Fall semester seminar will (roughly) cover Euclid to Leibnitz and Newton. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>Introductory Algebraic Number Theory</strong> </p> <p>One of the most basic facts in all of mathematics is the Fundamental Theorem of Arithmetic: given a positive integer <img alt="n" class="CToWUd" id="m_-717388230643633685l0.4701107051873412" src="https://ci4.googleusercontent.com/proxy/YC8nj2e8yBmjCq6iHNmwmKCdjEMLA1Rkg9GJ3zrI5rgl2Dm25s_TOAvkaywNnYQr_JYl-kfbaPoAk1awVJYg5EjXQffL2dYqAGm_NHlLgSa3Z5T7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09n" style="display:inline; height:7px; width:9px" title="n"/>, it has a unique (up to ordering) factorization into primes. The integers are not the only interesting set of numbers to work with though. For instance, suppose you are interested in solutions to the equation <img alt="x^2 + 1 = 0" class="CToWUd" id="m_-717388230643633685l0.27052074324938746" src="https://ci3.googleusercontent.com/proxy/xqcvy1KFxXc8K883M_1PDukXqcmZPm-5tB-iSAMkGkvFeFHMSOafhQR0uUvfixvpkuFdBXvok_lC_7waFw7tk0gW8wv3vqRPSjX-COISgNGMetOSfY0ffCmyU0Zq4BpjNPGK2YwXlx6nsA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091%09=%090" style="display:inline; height:15px; vertical-align:-1.1px; width:74px" title="x^2 + 1 = 0"/>. This naturally leads us to consider the number <img alt="i = \sqrt{-1}" class="CToWUd" id="m_-717388230643633685l0.3047216474584953" src="https://ci3.googleusercontent.com/proxy/jI9lkel1Wbpr5NOwIn5DWDtYBZ60cpzFgOtDWow484Xkd2YpuW52catXmqkkijXBDPPEeH2fk6x4MQ2-2yTaorDx5u-_pGbv5ks_d4E5C_t_scHGQDLxG6KnpH3R96QWXdRQq6ktp-8Xuw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09i%09=%09%5Csqrt%7B-1%7D" style="display:inline; height:16px; vertical-align:-2.934px; width:63px" title="i = \sqrt{-1}"/> as well. We can then define a new collection of numbers called the Gaussian integers <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.3979931267566288" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> which consist of elements of the form <img alt="a + b i" class="CToWUd" id="m_-717388230643633685l0.015155930074882695" src="https://ci3.googleusercontent.com/proxy/d6zGMURoQy94P-DoTtLy93G4MB8MbHK1GInDLAorcYJkCCWM4cFLTvHUWm7k9TPC45AYf_oh-vjDQfyz97qQtaBGFVOXHEw4i7gio3uVenCYoZ148Hq_WkbUWIOPw4ef6hw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a%09%2B%09b%09i" style="display:inline; height:12px; vertical-align:-1.1px; width:41px" title="a + b i"/> for <img alt="a,b \in \mathbb{Z}" class="CToWUd" id="m_-717388230643633685l0.3730528622472029" src="https://ci6.googleusercontent.com/proxy/T4yrmOhXbiVysYHo65u2ng0ifI58f9fbFBHbM7FJE00vaWEiH8RIEZJB72bFauQ0qwa34Xj0I6JsGgN8seXxxvnTVCRsFaCrfX6W98sTyi-vFckX0fl8aA-HQ5IAVRdlAuYbUGWfrJKGR2lSl0LKQaM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a,b%09%5Cin%09%5Cmathbb%7BZ%7D" style="display:inline; height:14px; vertical-align:-2.934px; width:53px" title="a,b \in \mathbb{Z}"/>. Given a prime <img alt="p \in \mathbb{Z}" class="CToWUd" id="m_-717388230643633685l0.6716878374913045" src="https://ci5.googleusercontent.com/proxy/I91pxfAy3o71ANU93zluf4FRJbNEGbX_SHuVKVPdohW_2Wwsw-Lgsztq4vsguB5AYJHfxGA4B3-lF8Z3Wf9vpwU6hcWFTZv3BO1mgkV4qOww6Cb2ajJ35ZUq_egaIzCfFdLLVUYR8f2pL09aP6pQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D" style="display:inline; height:14px; vertical-align:-2.934px; width:39px" title="p \in \mathbb{Z}"/>, we also have <img alt="p \in \mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.35769983375498393" src="https://ci3.googleusercontent.com/proxy/_X0boZvQHsr_aQSiVPqR6BIXlVDDGHiT4bYg4-VFaYiwAj2SRz9etcwOW-PHVF8NfxpBUeuJ2KgV1badjYAa0udYsnrsUF2BFfVyBBE3UMF1Rj8vNowRbWa4SiiuEuh9j8IcgeojBr0PlNAdaxl5cAy7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:53px" title="p \in \mathbb{Z}[i]"/>. Is <img alt="p" class="CToWUd" id="m_-717388230643633685l0.1517664126518219" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/> still prime in <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.5476717335800629" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/>? It turns out that sometimes, but not always! For instance, in <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.4503683865279826" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> we have <img alt="2 = (1 + i)(1 - i )" class="CToWUd" id="m_-717388230643633685l0.8909417025380852" src="https://ci4.googleusercontent.com/proxy/XvwjjHBgKnD2a36lesGEq1IkFArJpjXtTykglqE2EaWNBlM9_xg03JuwnNtjGawD0g8n7QvoWgwh0pmM6lceriWU9WXg1sBmtIfdlM6JSu5uMmM_t6F4oOAy0L7mm1LgnpxILKTxKFp-G3huy6k9DSkKdcdKLQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%092%09=%09(1%09%2B%09i)(1%09-%09i%09)" style="display:inline; height:16px; vertical-align:-3.667px; width:123px" title="2 = (1 + i)(1 - i )"/> and <img alt="5 = (2 + i) (2 - i)" class="CToWUd" id="m_-717388230643633685l0.9367616738022781" src="https://ci4.googleusercontent.com/proxy/FyVZr4VzL5yrRbSosqkqGx04BmK6zUcoqlCLddJPUxekXPW72sf-MpLR9B9lbMIdAqpHod1zFvoBVn0d4FaWXAABuCsa8KVM2RwNcTEFBrWHh230o_Yk-l_LQEcrvyNOIfwOXU53fdiRTvUTLUTe5B3slXa1sA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%095%09=%09(2%09%2B%09i)%09(2%09-%09i)" style="display:inline; height:16px; vertical-align:-3.667px; width:123px" title="5 = (2 + i) (2 - i)"/>, but <img alt="3" class="CToWUd" id="m_-717388230643633685l0.6355056826217114" src="https://ci6.googleusercontent.com/proxy/Er5UHWmuvViTqmbNTtg07Zo3TDld1PrKGZFpM1g1IYsbUxVg42LXa42yahDQowN9d1uGeAObmZqSYE6hywCYmc-qr5momXJ3Q9fqmsmt7t2msGmt=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%093" style="display:inline; height:11px; width:7px" title="3"/> is still prime! This fact is related to writing <img alt="p" class="CToWUd" id="m_-717388230643633685l0.7053141998565537" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/> as a sum of two squares as well as how the polynomial <img alt="x^2 + 1" class="CToWUd" id="m_-717388230643633685l0.2533482662405988" src="https://ci5.googleusercontent.com/proxy/O9U18DGHuRvAsqi0RA0hDNN3XN_cNoMh5A0X7XL4tEHMlZY45-T6w2Qf07anETTar4klaWwUOHcUdnWp5LQ2J3bAjhXiPRgi-45NwXEBc5Z2C7CwaVEmfvjIspVx6wcFjiM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091" style="display:inline; height:15px; vertical-align:-1.1px; width:43px" title="x^2 + 1"/> factors when considered modulo <img alt="p" class="CToWUd" id="m_-717388230643633685l0.41962974130248254" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/>. The study of how primes factor when considered in larger rings is referred to as algebraic number theory. In this course we will study algebraic number theory for the simplest cases of <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.719894371208375" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> and possibly other rings of the form <img alt="\mathbb{Z}[\sqrt{d}]" class="CToWUd" id="m_-717388230643633685l0.9347271008519611" src="https://ci3.googleusercontent.com/proxy/fykrb_Z6FYHa1OHSUz6l_6Ccl38TddheOZ5XqwFQDiTJtyJBJ2qrWG0-ZBvP45qpMtA0PEp7ENHRM7_NY_hSV-uPy-AwOGApOXctS2cmUXG322diPJNjCmvCdBrHDWjgJVN5jBXvfgSUS6PS8y57cGrr6A=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[%5Csqrt%7Bd%7D]" style="display:inline; height:18px; vertical-align:-3.667px; width:40px" title="\mathbb{Z}[\sqrt{d}]"/> to see the underpinnings of the overall vast theory. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(180,2022,255,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-101','<div class="desc"> <p>This course begins the four-semester music theory sequence covering the techniques of music for the student who has little or no previous musical training. Topics will include notation, modes, intervals, basic ear training, melody, harmony, rhythm, meter, and structural elements of music. Introductory exercises in composition of popular, jazz, and classical genres will be explored. The music studied will be chosen in collaboration with students and Music Department colleagues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(181,2020,256,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/100/musc-102','<div class="desc"> <p>This course will examine the diverse forms and social contexts of Latin American and Caribbean music while exploring the ways that musical performance has been used to negotiate power relations in the social political and economic spheres since the Conquest. Focusing on musical genres and movements from Argentina Brazil Cuba Haiti Mexico Peru and Trinidad students will learn to recognize the techniques and instruments used in a wide array of traditional and contemporary styles particularly those which have grown out of the hybridization of African Middle Eastern European Asian and Native American performance strategies. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(182,2022,257,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-103','<div class="desc"> <p class="sc-BodyText">This course surveys the musical styles and genres of Asia from India through the southeastern part of the continent and includes the countries and islands of the Pacific. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. Where appropriate distinctions will be made between classical and folk genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(183,2022,258,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-115','<div class="desc"> <p>A historical and cultural survey course of a select genre of vocal music, such as opera, song, musical theater, and choral music. Topics vary by semester and may satisfy different Core requirements.</p> <p><strong>Opera</strong></p> <p>Since its inception in late 16th-century Florence as a humanistic reimagining of Greek tragedy, opera has served as a catalyst for social and political change. The opera-loving agents advocating for this change have been diverse: philosophers (Jean-Jacques Rousseau, Friedrich Nietzsche, Kwame Anthony Appiah), writers (Walt Whitman, Langston Hughes, Toni Morrison), and activists (Theodor Herzl, W. E. B. Dubois, Martin Luther King), among many others, including the late jurist Ruth Bader Ginsburg, whose legal career was dedicated to advocating for gender equality and women''s rights. This iteration of this history-of-opera course will focus on the five operas that Justice Ginsburg wanted people to know: Mozart''s <em>Marriage of Figaro</em> and <em>Don Giovanni</em>, Verdi''s <em>Otello</em>, Puccini''s <em>The Girl of the Golden West</em>, and Strauss''s <em>Der Rosenkavalier</em>. In the first half of the course we will survey the history of opera in Europe, up to and including the two Mozart operas, which premiered in 1786 and 1787. We will study all five operas with attention to their plots'' legal and gender relations. Students will learn opera''s forms and styles and read primary documents written as responses to individual operas and opera writ large, all with the goal of understanding these operas'' political, philosophical, and cultural contexts as well as their messages for us today. No prior musical experience is required. <em><strong>Additional Core Requirement: Regional Focus.</strong></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(184,2022,259,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-120','<div class="desc"> <p>This course involves the study and performance of a wide variety of choral music, including Western classical genres, world music and folk songs, and pop songs. Students will improve their singing ability and sight-reading skills through this preparation and performance. The ensemble rehearses one evening each week and performs once each semester. Students may enroll for one or both semesters. Ensemble membership is open to all students. Students new to the ensemble should meet with the instructor during the first week of the semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(185,2022,260,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-121','<div class="desc"> <p>This course involves the study and performance of advanced choral music. Emphasis is placed on challenging, traditional choral repertoire as well as on world &amp; folk music and popular music. Includes many performances both on and off campus. Enrollment is for the full year and is by audition only during the first week of the fall semester. Sight reading ability and previous musical experience highly recommended. May be repeated seven times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(186,2022,261,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-122','<div class="desc"> <p>This course involves the study and performance of advanced choral music. Emphasis is placed on the challenging, traditional choral repertoire as well as on world &amp; folk music and popular music. Includes many performances<s>,</s> both on and off campus. Enrollment is for the full year and is by audition only during the first week of the fall semester. Sight reading ability and previous musical experience highly recommended. May be repeated seven times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(187,2022,262,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-123','<div class="desc"> <p class="sc-BodyText"></p> <p>Semester-long instruction with music tradition-bearers allows students to develop the technique and language to approach musical styles from outside the Western art music canon, while exposing them to alternative modes of musical pedagogy. In addition to practicing secular rumba drumming, students will study the sacred rhythms of Santeria and learn to sing the songs of the Orishas in the Yoruba dialect of Lucumi. In addition to weekly rehearsals with the ensemble, students will be expected to practice on their own and to participate in a public performance at the end of the semester. No prior music experience is required.</p> <p class="sc-BodyText"></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(188,2017,263,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MUSC-Music/Ensembles/MUSC-125','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(189,2022,264,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-126','<div class="desc"> <p>A symphonic wind ensemble for qualified instrumentalists from the college communities of Occidental and the California Institute of Technology (students, faculty, staff, and their families). The Orchestra presents concerts on both campuses during the year. Graded Credit/No Credit and may be repeated for up to eight units of credit. Ensemble membership is open to all students of the college by audition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(190,2022,265,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-127','<div class="desc"> <p class="sc-BodyText">The Occidental Jazz Ensemble consists of instrumentalists from Occidental who are interested in performing jazz of various styles. Charts and styles are determined according to the instrumentalists in the ensemble and their particular jazz interests. The Jazz Ensemble presents several concerts during the academic year. <em>Enrollment is by audition and then, if successful, permission of the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(191,2022,266,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-129','<div class="desc"> <p>Study and performance of chamber music for diverse combinations of instruments and voices. Students audition during the first week of the semester for our Director, who selects repertoire and form appropriate groups of student players. Students perform both music of the past (including the recent past) as well as new music composed for them by our music composition students, culminating in world premieres at the end-of-semester concert. Prerequisite: audition and permission of instructor. This course does not fulfill the ensemble requirement for scholarship recipients and Music majors. Only advanced pianists may use this course to fulfill the ensemble requirement for scholarship recipients and Music majors. May be repeated seven times for credit. Audition during the first week of the semester. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(192,2022,267,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-130','<div class="desc"> <p>The Occidental Symphony Orchestra is an orchestral ensemble that plays music from the Baroque era through today. Through its collaboration with Oxy''s music composition program, the Orchestra will perform and record new music, including film scores written for MAC student films. The Orchestra will frequently partner with the Occidental Glee Club to perform a large choral work with orchestral accompaniment. Enrollment is by audition during the first week of each semester. Instructor permission required. As the community orchestra for Northeast Los Angeles, the Orchestra is not only open to all students but also alumni and community members. May be repeated seven times for credit. Enrollment is by audition during the first week of each semester. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(193,2017,281,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MUSC-Music/Music-Courses/100/MUSC-150','<div class="desc"> Designed for students with some beginning experience in music theory and an ability to read music. Covers scales, keys, modes, intervals, and basic tonal harmony. </div>','Music 101, a passing grade on the Music Theory placement examination, an AP Music Theory score of 3 or higher, or permission of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(194,2017,283,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MUSC-Music/Music-Courses/200/MUSC-230','<div class="desc"> <p class="sc-BodyText">Topics include the continued study of theoretical historical and aesthetic principles underlying computer/electronic music leveraging the study of software applications (Logic MaxMSP Digital Performer ProTools Cloud Generator MetaSynth) towards the creation of electronic electro-acoustic and/or interactive multimedia composition. The class may include an emphasis on collaborative multimedia artwork such as film theater dance and multimedia installations covering the conceptual and practical aspects of creating and producing electro-acoustic music within that framework.</p> </div>','MUSC 100 or MUSA 100 or permission of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(195,2022,284,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-232','<div class="desc"> Prepares music majors to demonstrate competence in a broad range of keyboard skills: basic keyboard technique, sight reading, elementary repertoire, harmonization of melodies, transposition, and accompaniment. Satisfactory performance on the final exam is required to satisfy the Music major piano proficiency requirement. Graded on a Credit/No Credit basis only. </div>','MUSC 132 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(196,2022,285,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-257','<div class="desc"> <p>Writing exercises to develop technical facility; study of characteristics of instruments; exercises in scoring for various vocal and instrumental combinations. Permission of instructor required. <em>This course may be repeated five times for credit.</em></p> </div>','MUSC 113 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(197,2022,286,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-261','<div class="desc"> <p>This course surveys the two-plus centuries that gave rise to European art music''s most enduring legacies: opera, instrumental art music, and, especially, the major-minor tonal system, which, as the system that informs most music today, is arguably Europe''s greatest-ever cultural export. The emergence of this tonal system enables instrumental music to sustain a listener''s attention through dramatic forms and without the aid of words; comprehending how these forms behave is one of the central tasks of this course. In turn, the cultivation of instrumental genres will fuel the operatic accomplishments of Classical composers, notably Mozart. Our study of vocal and instrumental music proceeds chronologically and focuses on individual cities, starting with Florence at the end of the Renaissance and ending with Vienna, the music of Beethoven and Schubert, and the emergence of musical Romanticism. This course may be used by Music majors to fulfill the Second-Stage Writing Requirement. Not open to first-year students.</p> </div>','MUSC 101 or the equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(198,2022,287,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-272','<div class="desc"> <p class="sc-BodyText">Basic principles and gestures of instrumental conducting in a variety of genres: symphony concerto opera. We will also discuss the "business" of conducting and running rehearsals.</p> </div>','MUSC 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(199,2022,288,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-280','<div class="desc"> <p>This course offers an introduction to the principal concepts and methodologies of the field of ethnomusicology as well as the style and practices of selected world musical traditions. This course may be used by Music Majors to fulfill the college-wide Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(200,2022,289,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-285','<div class="desc"> <p>Various topics are offered. Each may be used by Music Majors to fulfill the College-wide Second-Stage Writing Requirement.</p> <p><strong>From Instagram to Digital Music Archive: Popular music and public memory in Latinx Los Angeles</strong></p> <p>In this class you will explore the role of social media in archiving popular music. In particular, you will work with an Instagram-based archive that documents several decades of Latinx rock n’ roll in Los Angeles. Questions you will consider include:</p> <p> · In the post-digital age, how does one “read” ephemera such as flyers and photographs posted on social media? How can they be re-articulated in scholarly contexts?</p> <p>· How are community and/or social media archives different from institutional archives and what role can they play in supporting and sustaining local communities, particularly Latinx communities in Los Angeles?</p> <p>· What are the specific challenges associated with archiving in Latinx and settler colonial contexts? </p> <p>Participating in this hybrid, arts and technology course that will combine both conceptual and practical methods, you will develop production skills in digital liberal arts as you interrogate social networks as scholarly and activist texts. Specifically, you will learn to create and access databases, and to develop archive-oriented websites using HTML, CSS, and the web-centered programming language, PHP. While no previous knowledge of computer coding or web design is required, students with specialized knowledge in these areas will be offered opportunities for more advanced project work. <em>Additional Core Requirement Met: U.S. Diversity.</em></p> <p><strong>Music and Social Protest</strong> </p> <p>Over the past century, music has played a central role in political and social movements that seek to shift the balance of power in local, national, and transnational contexts. From the songs of the African American freedom struggle to the music of the <em>nueva cancion</em> movement in Chile, from the live performance practice of the Occupy and immigrant rights movements to the raucous sounds of Russia''s Pussy Riot, music has been an important mode of circulating alternative political messages and inspiring rebellion against the status quo. How can music be used to convey political messages and extend the reach of social movements? Why does music enhance cohesion and solidarity among movement participants and/or sway or destabilize oppositional forces? Are there differences between mass-mediated modes of political protest and live, grassroots political performances? When voices raised in song become powerful, what protocols are established to censor and repress them? We will examine these questions in the context of social movements which have inspired mass participation, comparing and contrasting case studies from Europe, Asia, Africa, and the Americas. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(201,2022,290,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-374','<div class="desc"> <p class="sc-BodyText">Preparation for junior recital. Requirements include more extensive practice expectations as well as research and preparation of program notes. Approval of the department required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(202,2022,292,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/400/musc-474','<div class="desc"> <p>This course convenes senior Music majors with a Music Production concentration to workshop, share, and critique the work that will become part of the music portfolio they will submit in partial fulfillment of the Senior Comprehensive requirement. May be repeated once for credit. Junior or Senior standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(203,2022,293,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/400/musc-490','<div class="desc"> <p class="sc-BodyText">In this fall semester seminar students will work through a staged process to complete a draft of their senior comprehensive paper. In this critical persuasive essay students will engage recent scholarship in the fields of musicology ethnomusicology and/or music theory in order to develop and support an original thesis. Students undertaking research and/or fieldwork for their senior comprehensive projects will produce a complete draft of their twenty-five page (6250 word) critical essay. Students undertaking composition conducting instrumental or vocal recitals for their student comprehensive project will write a thesis-driven ten-page (2500 word) paper that explores a musical topic related to the materials they will present. Recitalists will also research and produce a draft of their recital program with program notes while composers will complete their recital portfolio and begin work on their recital program. Over the course of the semester students will discuss and share their work as well as analyze and discuss exemplary academic papers program notes liner notes and music reviews in order to develop their ability to write about music for academic and non-academic audiences in compelling ways.</p> </div>','Junior Standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(204,2022,294,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/100/phil-101','<div class="desc"> <p>This course introduces students to the central philosophical skills of critical thinking, careful reading, and analytical writing. Students will engage with a range of both historical and contemporary philosophical texts, from multiple regions and time periods, and with a range of philosophical questions that reflect the four content areas that structure our curriculum: (1) History of Philosophy, (2) Diversity in Philosophy, (3) Self &amp; Community, and (4) Mind &amp; World.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(205,2019,295,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-225','<div class="desc"> <p>We will study the formal properties of arguments and sets of statements. This will involve learning two formal languages the propositional calculus and the predicate calculus. Within these languages we will formalize the notions of validity soundness and consistency and show how these properties can be tested.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(206,2022,296,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-230','<div class="desc"> <p>Philosophical thinkers have asked a series of related questions about how to live: What is happiness? What kinds of human activities give our lives meaning? More generally, how must a person live to have lived well? This course will examine a variety of answers to these questions. As a significant component of the course, students will practice living within one of the traditions we study, and reflect upon that experience.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(207,2019,297,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-250','<div class="desc"> <p>This course is an introduction to the methods of ethics developed for addressing moral issues in the practice of health care and research. Methods addressed will include: professional ethics (practice standards and professional norms) casuistry the principles of biomedical ethics applied normative theory feminist bioethics and narrative ethics. We will use these methods to address a host of topics of concern to those participating in health care institutions either (directly) as providers or (somewhat less directly) as policy makers. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(208,2022,298,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-310','<div class="desc"> <p>A detailed examination of some central philosophical texts from the 17th and 18th centuries. Topics vary by semester.</p> <p><strong>Kant''s <em>Critique of Pure Reason</em></strong></p> <p>This course will consist in a detailed study of selected parts of Immanuel Kant''s <em>Critique of Pure Reason</em> – the most important and influential 18<sup>th</sup>-century work on philosophical issues about the relationship between mind and world, and an attempt to synthesize and build upon the rationalist and empiricist approaches to those questions. We will also read selections from some of the central figures in the traditions to which Kant is responding (including Rene Descartes as an exemplar of the rationalist tradition, and David Hume as an exemplar of the empiricist tradition), in order to contextualize the motivations for Kant''s project, and to frame the issues with which the <em>Critique of Pure Reason</em> is engaged.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(209,2022,299,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-340','<div class="desc"> <p>This course examines what science is and how science works. That we have clear and determinate answers to questions about the nature of evidence, reasoning and truth is assumed by the scientific enterprise, while philosophical examination shows these assumptions to be far from justified. By exploring the concept of evidence, the concept of truth, and the practices of reasoning in science, the course will analyze under just which conditions scientific claims are justified and what this means about the relation between scientific theorizing and truth.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(210,2019,300,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-353','<div class="desc"> Contemporary political debates often concern the relationship between social justice and health. This course addresses central issues in the philosophy of healthcare and public health, including: what is health? How is health related to well-being more broadly? What are the proper aims of public health and healthcare institutions? Does health enjoy a special moral importance? What is health equity? Is access to health care a fundamental (human) right? </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(211,2022,301,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-360','<div class="desc"> <p>What makes something, someone, or some place beautiful? Why do we value beauty? These questions will be explored across multiple domains, including: art, the natural world, the built environment, and human practices, including norms for human bodies. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(212,2022,302,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/400/phil-490','<div class="desc"> <p>Open only to students with senior standing in philosophy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(213,2022,304,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-121','<div class="desc"> <p>Instruction in regularly scheduled practices with competitive intercollegiate club opportunities. Open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(214,2022,305,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-123','<div class="desc"> <p>Instruction in regularly scheduled practices with competitive intercollegiate club opportunities. Open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(215,2022,306,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-124','<div class="desc"> <p>Participate in weekly Club Sports Women''s Rugby practices and competitive intercollegiate club opportunities. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(216,2022,307,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-125','<div class="desc"> <p>Includes performing at athletics games, spirit rallies and other onj-campus events. Off-campus competition/s vary by year. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical. Auditions will be held during the Fall Semester. Full year commitment required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(217,2022,308,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-126','<div class="desc"> <p>Includes performing at athletic events, spirit rallies and other on-campus events. Off-campus competition/s vary by year. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical. Auditions will be held during the Fall Semester. Full year commitment required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(218,2022,309,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-127','<div class="desc"> <p>The United States Tennis Association (USTA) promotes cardio tennis as a group activity featuring a circuit of drills that consistently elevate the heart rate into the aerobic training zone. Short cycles of high intensity work-outs and periods of rest similar to interval training. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(219,2022,310,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-128','<div class="desc"> <p>Spin I is an introductory course designed to expose students to the terminology and movements of cycling while preparing them for the advanced rides of Spin II. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(220,2022,311,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-129','<div class="desc"> <p>Students will learn the fundamentals of hip hop dance and will gain experience in learning hip hop choreography. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(221,2022,312,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-133','<div class="desc"> <p>Class concentrates on improving overall fitness through the use of an aerobic weight training program. Circuit training is a combination of high-intensity aerobic and resistance training primarily through the use of weight machines. It is idealto help control body weight tone muscles and improve cardiovascular fitness. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(222,2022,313,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-134','<div class="desc"> <p>Learn the fundamentals and history of the practice of Yoga. Over the course of the semester the practice will become more and more challenging and in depth; making gains in strength flexibility and the mental aspects of Yoga. Focuses will include: breathing techniques proper posturing different styles of Yoga the physiological side mental side and meditation side of Yoga. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(223,2022,314,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-148','<div class="desc"> Participate in weekly Club Sports Women''s Ultimate Frisbee practices and competitive intercollegiate club opportunities. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(224,2022,315,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-149','<div class="desc"> <p>Analysis of basic offensive and defensive techniques used in Karate including time speed and knowledge of body leverage. Cognitive knowledge of defense methods and their employment are also learned. Special emphasis on Shotokan Karate. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(225,2022,318,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-115','<div class="desc"> <p>The first of a two-course introduction to physics designed for life science and premedical students. Topics include Newton''s laws of motion gravitation work and energy conservation laws. Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</p> </div>','Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(226,2017,319,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/Introductory-Physics-Courses/PHYS-115L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(227,2020,320,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/phys-physics/100/phys-120','<div class="desc"> <p>Introduction to electricity and magnetism electronic circuits electromagnetic induction and Maxwell''s Equations. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(228,2017,321,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/Introductory-Physics-Courses/PHYS-120L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(229,2022,322,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-162','<div class="desc"> <p>A survey of the solar system, stars and stellar evolution, galaxies and cosmology. Students are expected to have a strong understanding of algebra and trigonometry. <span style="background-color: #ffffff; color: #222222;">Physics majors cannot take this course for credit toward the Physics major.</span><s></s></p> </div>','Passage of the equivalent of High School Algebra is required ',NULL,NULL);
INSERT INTO course_descriptions VALUES(230,2022,323,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-261','<div class="desc"> <p>An introduction to the numerical solutions of problems in physics. Applications are drawn from classical dynamics electrostatics magnetostatics relativistic dynamics and chaotic systems.</p> </div>','PHYS 110 or PHYS 115, PHYS 120 or PHYS 125, and COMP 131; or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(231,2022,324,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-310','<div class="desc"> <p>Survey of the elements of advanced mathematical ideas and techniques typically used in physics. Physical examples and intuition will be emphasized throughout. Topics covered will include Div Grad and Curl; matrices tensors and groups; complex analysis Fourier series and integrals; boundary and initial value problems; and special topics as time permits. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 117 and PHYS 120; and MATH 214 (may be taken concurrently with permission of instructor); or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(232,2022,325,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-315','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques, including literature search, analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(233,2022,326,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-320','<div class="desc"> <p>Motion of particles systems of particles and rigid bodies. conservation laws; coordinate transformations both stationary and moving; Hamilton''s and Lagrange''s equations. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 117, PHYS 120, and MATH 214; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(234,2022,328,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-395','<div class="desc"> <p>Research supervised by a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(235,2022,330,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/100/pols-101','<div class="desc"> <p>This course introduces students to the study of politics the discipline of political science and the development of public policy. Politics involves the study of power influence and ideas in public and private life at the personal local state national and international levels. Accordingly our exploration will examine how power operates in a variety of settings and will include readings in political theory American politics and law comparative politics research methods and international relations. Open to frosh and sophomores.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(236,2022,331,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-203','<div class="desc"> <p>The goal of the Campaign 2020 Internship class is to provide students with an experiential understanding of the practice of electoral campaigns. This course must be taken in conjunction with the POLS 204, Campaigns and Elections. Together, the two courses allow students to gain a deep understanding of the theory and practice of electoral politics in the United States. For Fall 2020, students will actively participate in an internship with a campaign of their choosing in their hometown or the Los Angeles County District Attorney’s race, which the <em>New York Times</em> has called the most important DA race in the country because of growing concern about the problems within our criminal justice system, including racism, policing, and incarceration. The internships will be done remotely, so it doesn’t matter whether students are living at home or on campus. Students will be expected to participate in their internship at least 8 hours per week during the fall semester. Students will schedule their internships for times that are mutually convenient to themselves and their campaign supervisor. Paired with the exploration of scholarship of Campaigns and Elections in POLS 204, students will connect the concepts learned in the classroom to their experiences in the campaign internships. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 204',NULL);
INSERT INTO course_descriptions VALUES(237,2022,332,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-206','<div class="desc"> <p>This course is an exploration of the historical and continuing significance of race in the American political system. The relevance and role of race in shaping political institutions public opinion political behavior and public policy will be examined. Special attention will be given to theoretical debates surrounding the meaning of race and how this changes depending on political context.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(238,2020,333,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/american-politics-and-public-policy/pols-209','<div class="desc"> Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(239,2020,334,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/comparative-politics-and-area-studies/pols-218','<div class="desc"> <p>A careful examination of contemporary Russian foreign policy. The focus will be on the complex of foreign policy relationships that have developed in the geographical space and sphere of influence formerly occupied by the Soviet Union. Russia''s relations with the United States with Western Europe with the Far East and with Central Europe will receive special attention. NATO expansion arms control the Balkan conflict and Russian policy toward the new states of the Caucasus and Central Asia and Russia''s relations with international financial institutions will all be evaluated.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(240,2022,335,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-244','<div class="desc"> <p>This course provides an introduction to constitutional law and constitutional theory examining the ways in which the Constitution distributes power among the branches government in the American political system and limits the exercise of those powers. The course will also consider the role of the judiciary in creating legal and political boundaries for society. Throughout the semester this course will focus not only on legal doctrine but also on the broader intellectual and political context in which it evolves. Using constitutional law cases and moot courts the course will explore the role of the United States Supreme Court as a civil liberties policymaker and the process through which decisions are reached. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(241,2020,337,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/political-theory/pols-252','<div class="desc"> <p>Traditional aristocratic society as described by Bodin; "self-seeking" the state of nature obligation and natural law in Hobbes and Locke; Rousseau on freedom and equality; utilitarianism and liberty in Bentham and Mill; the dialectical method history and self-consciousness in Hegel; alienation historical materialism and class struggle in Marx. <em>Not open to frosh.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(242,2022,338,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-295','<div class="desc"> <p> Topics in Politics. Can be repeated once for credit if topics differ.<em>NOTE: Different topics may satisfy different Core Program requirements</em>.</p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start"><strong>Comparing Colonial Legacies</strong></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start">A comparative analysis of colonial governing practices, processes and modes of decolonization, and their long-term effects on the states and societies of the postcolonial world. Critical questions focused on in this course will include the relative political legacies of different types of colonialism (i.e. settler, exploitative, internal) and different colonial powers, the effects of colonial policies regarding ethnic boundary-making, and the implications of enduring ties of various kinds between the post-colonial states and the former metropole. The geographical scope of this course will be broad, including, but not limited to, Latin America, the former Soviet Union, Sub-Saharan Africa, South Asia.<em> Core Requirement Met: Global Connections.</em></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start"><strong>Politics of Development</strong></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start">A comparative analysis of the politics and economics of states in the “developing world”, including an introduction to theories that link variation in political systems to levels of economic development. This course will also analyze questions such as the relationship of natural resource dependency to political regime characteristics, the determinants of foreign aid allocations, and the origins and roles of international development organizations. The geographical focus of the course includes Africa, Asia, Latin America, the Middle East, and the former Soviet Union. <em>Core Requirement Met: Global Connections</em>.</p> <p><strong>Politics of Immigration</strong></p> <p>Immigration is one of the most hotly contested issues in American politics, and has been for some time. Much of the debate about how to craft immigration policies has come from politicians at the national level in the U.S. Congress, which has the responsibility to create policy, but important voices in the debate also come from state legislatures and community organizations. In this class, we will learn about the central issues regarding immigration that have emerged in both the body politic and in scholarly discourse. Topics addressed will include: why people migrate, why anti-immigrant sentiment is prevalent, the politics of immigration control policies, demographic trends, and notions of exclusion and inclusion. Our goal in the class is to come to a better understanding of the political process regarding immigration and why it matters. <em>Core Requirement Met: United States Diversity</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(243,2022,340,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,'POLS 295',NULL);
INSERT INTO course_descriptions VALUES(244,2022,341,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-336','<div class="desc"> <p>This course is an examination of how American national security policy is conducted and explores the principles practices and problems related to contemporary American foreign policy making. The course will touch on the basic historical patterns of American foreign policy; however it will focus on current practices and operation of the foreign policy machinery in Washington as well as examine some contemporary cases to demonstrate how the system works. Close attention will be paid to the structures of national security decision-making involving the Presidency and the National Security Council the Congress the Departments of State and Defense as well as the Intelligence Community and other new national security agencies. For Politics, UEP, and DWA majors only.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(245,2022,344,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/200/psyc-200','<div class="desc"> <p>Introduces scientific methodology in the context of psychological research. Basic concepts in scientific inquiry and specific observational correlational and experimental techniques are covered. Includes an introduction to descriptive statistics. This course is a prerequisite to many 300-level courses in Psychology.</p> </div>','PSYC 101 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(246,2022,345,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/200/psyc-201','<div class="desc"> <p>Introduces parametric and nonparametric inferential statistics used in psychological science through analyses of variance appropriate to complex experimental designs. Includes a review of research methods and descriptive statistics and work with statistics software.</p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(247,2022,346,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/200/psyc-223','<div class="desc"> <p>This highly interactive seminar draws on theoretical, empirical, and narrative essays as well as structured in-class activities to provide students with an intellectual, applied, and personal understanding of contemporary intergroup relations. Course topics include: social identity development and implications; prejudice, stereotyping, and group differentiation; privilege, power, and oppression dynamics; conflict negotiation and resolution; and communication and group facilitation skills. Social justice issues are framed for gender, race, class, sexuality, and ability. Effective dialogue seminars are inclusive and enhanced by the participation of diverse identities, multiple disciplines, and a range of political perspectives. Placement form can be found at this link: https://oxy.qualtrics.com/jfe/form/SV_d4pBn2ZnPXYoC8Z Students must complete the placement form prior to advising week.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101, completion of placement form prior to beginning of advising week, and permission of instructor. Students with a background in any introductory social science course are encouraged to consider the seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(248,2022,347,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/200/psyc-295','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. Instructor permission required. <em>Graded on a Credit/No Credit basis only. PSYC 101 or PSYC 102 or relevant introductory course in another department and permission of instructor. May be repeated once for credit if the second project is different from the first. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(249,2022,348,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-321','<div class="desc"> <p>The study of continuity and change across development. Emphasis on application of research methods to issues related to cognitive emotional personality and social development. The course will focus primarily on these issues in infancy and childhood.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(250,2022,349,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-322','<div class="desc"> <p>The study of neural glandular and metabolic processes mediating behavior thought and feelings. This course is identical to PSYC 312 except that students who enroll in PSYC 322 may enroll concurrently or subsequently in the laboratory (PSYC 322L). Core Laboratory Science credit will only be awarded for students completing both PSYC 322 and PSYC 322L. Students who have received credit for PSYC 312 may not enroll.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 <div id="offered"></div>',NULL,NULL);
INSERT INTO course_descriptions VALUES(251,2022,350,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-322l','<div class="desc"> May be taken concurrently with Psychology 322. </div>','PSYC 200 (Students must earn a grade of C- or better) and PSYC 322 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(252,2022,351,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-323','<div class="desc"> <p>Behavior of individuals and groups in and across social contexts. Topics include self social cognition attitudes and persuasion liking and loving prejudice aggression and social conflict group identity consciousness and social action.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(253,2022,352,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-330','<div class="desc"> <p>The study of psychopathology including diagnosis and classification core dysfunctions and physiological and psychosocial causative factors. Intervention treatment and preventative strategies will also be discussed.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(254,2022,353,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-340','<div class="desc"> <p>Introduction to the study of theories and applications of psychology in profit and not-for-profit organizations. Representative topics include understanding how ability personality perception motivation leadership and group dynamics affect productivity and worker satisfaction. Issues of fairness and accuracy of assessment will also be discussed. Emphasis is on practical and personal learning of the dynamics of the work environment.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(255,2022,354,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-350','<div class="desc"> <p>The course will survey diverse psychological perspectives on gender and its personal and cultural implications. Will explore: meanings of gender evolutionary physiological developmental and sociocultural roots of gender difference; the relation of gender to cognition personality sexuality health interpersonal relationships and political power; the commensurability of various theoretical approaches to gender.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(256,2022,355,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-395','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required.<em>Graded on a Credit/No Credit basis only.</em></p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(257,2022,357,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-431','<div class="desc"> <p>Introduction to the techniques and processes of clinical psychology and psychotherapy. Topics include major schools of thought and approaches, specific techniques of assessment and treatment, relevant research, assessment of effectiveness, and issues of gender and culture. <em>Open only to seniors or by permission of instructor.</em></p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 and PSYC 330 (Students must earn a grade of C- or better in both) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(258,2022,358,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-490','<div class="desc"> <p>PSYC 490 seminars taught by Dr. Dess, Dr. Chapman or Dr. Schell can be applied to the Neuroscience minor. </p> <p><strong>Psychology and Law</strong></p> <p>Intersection of social science theory and data with law and legal procedure: Topics may include: normative and psychological theories of justice; eyewitness memory, deception detection, investigative interviewing and interrogations; jury selection and jury decision-making; forensic psychology and assessment; corrections and sentencing.</p> <p>Prerequisite: PSYC 200</p> <p><strong>Eating: From Cells to Society</strong></p> <p>Eating is fundamental to life more so than drinking or sex. It infuses the thoughts feelings and behavior of humans and other animals and thus serves as a model system for psychological inquiry. It is also for better and for worse intensely personal and thus serves as a model system for inquiry into the self. This course will explore eating from cellular to cultural levels of analysis. </p> <p>Prerequisites: PSYC 200 and one of the following: PSYC 302, PSYC 323, PSYC 321, or PSYC 336.</p> <p><strong>Teamwork Within Diverse Environments</strong></p> <p>Examination of how individual and group differences influence the performance of workgroups. The course focuses on theoretical and practical concerns related to the key topics of teamwork and leadership as they are performed within the context of a diverse work environment. Some related issues of fairness in managing diversity will also be introduced. </p> <p>Prerequisites: PSYC 201 and either PSYC 340 or PSYC 323. </p> <p><strong>Trauma</strong></p> <p>This course focuses on the experience of and responses to trauma in its many forms - natural disaster war and genocide child abuse assault and violence. The impact of trauma for both the individual and society at large are examined in the context of a stress coping resilience framework. Prevention and intervention strategies will be explored. </p> <p>Prerequisites: PSYC 330.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(259,2022,360,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-130','<div class="desc"> <p>This course is a survey of Jewish communities in antiquity from the late Babylonian exile to the emergence of Jewish Academies in the Diaspora. The first half of the course will focus on the formation of Jewish identity and the rise of competing Jewish factions and movements. We will study the central religious beliefs, texts, practices, and institutions that were held in common, yet simultaneously the source of deep division between sects. We will also study how sectarian movements -such as apocalypticism and messianism- were formed in response to Empire (Greek and Roman). In the second half we will consider issues of orthodoxy and heresy, as well as categories of insiders and outsiders. Finally, we will study the crystallization of orthodoxy in the rabbinic movement, considering issues of conversion, inter-religious polemic, conflict, and persecution.</p> <p>Throughout the course, students will engage with questions regarding Jewish identity and the evolving role of Jewish Scripture, its component parts, its interpretation, and its authority. Moreover, students will examine various models of religious leadership and practice, and various conclusions about the nature of God, the afterlife, the Messiah, and non-Jewish peoples.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(260,2022,361,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/resl-245','<div class="desc"> <p>A study of the religious traditions of the African diaspora in North America. We shall investigate the role of religion in Black culture and chart the development of the mainline Black Church. Islam religious traditions from the Caribbean Islands and new religions among African Americans will also be studied.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(261,2017,362,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/RELS-Religious-Studies/300/RELS-345','<div class="desc"> <p>This advanced seminar will investigate the meanings and traditions behind the popular American claim "I''m spiritual but not religious." What is spirituality in the American context? How and why does spirituality overtake religion in appeal and status? What historical features of American culture and society promote contemporary issues of spirituality?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(262,2019,363,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/RELS-Religious-Studies/300/RELS-370','<div class="desc"> <p>Questions about death dying and the afterlife plagued ancient cultures-Greeks Romans Jews and Christians. They asked: How does one live a life free of fear and anxiety over one''s inevitable and impending death? How can one die with dignity-whether violently or peacefully whether of one''s own volition or at the hands of other humans or God? How should the community structure rituals of death and what should be done with corpses? And how-if at all-will individuals live on in an afterlife? The central goal of this course is to familiarize students with the diversity of notions about death dying and afterlife in ancient cultures by analyzing literature (philosophical medical and poetic) rituals and monuments of the ancient Mediterranean world. We will then contextualize these ideas noting how and why they developed from driving concerns and circumstances of particular communities cultures and historical moments.</p> </div>','Only Junior and Senior students may enroll in this class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(263,2022,365,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/300/rels-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(264,2022,366,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/400/rels-490','<div class="desc"> <p>This seminar is offered in conjunction with Religious Studies majors'' ongoing research for the senior comprehensive project. Seminar meetings will be devoted to instruction on research and writing in the discipline of Religious Studies as well as discussion and critique of individual students'' work in progress. Open only to senior Religious Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(265,2022,368,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/100/rusn-101','<div class="desc"> <p>Introduction to the structure of the Russian language with an emphasis on reading and verbal communication. Films and laboratory assignments complement in-class work. May not be taken for credit by those with more than one year of high school study (grades 10 11 12) or one semester of college study of Russian.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(266,2022,369,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/200/rusn-201','<div class="desc"> <p>Development of reading skills through the use of original texts by Bulgakov Chekhov Pushkin and others; improvement of conversation skills accompanied by a review and expansion of grammar. Films and laboratory assignments complement in-class work.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(267,2022,370,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/200/rusn-274','<div class="desc"> <p>Focusing on Russian literature''s greatest depictions of war this course follows the evolution of war literature in Russia as it transforms from the folk epic to the Romantic tale of adventure to the bloody scenes of Tolstoy''s War and Peace into the Modernist portrayal of moral ambiguity in Isaac Babel''s Red Cavalry.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(268,2022,371,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/100/soc-101','<div class="desc"> <p>This course introduces students to the "sociological imagination"-a way of viewing events relationships and social phenomena which form the fabric of our lives and much of our history. We will examine the ways in which people are shaped influenced and controlled by their society and vice versa. In addition students will be encouraged to think about how sociology helps us understand and interpret the nature of social order and disorder. <em>Open only to frosh and sophomores or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(269,2022,372,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-205','<div class="desc"> <p>This course introduces the most influential paradigms of the 20th century. These include the American structural-functionalist paradigm the rational choice model the elite school various neo-Marxist arguments (including the theory of the world system as well as the culturalist Frankfurt school) and the symbolic interactionist paradigm. We conclude the course with an introduction to postmodernist theory. The course emphasizes critical analysis.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(270,2022,373,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-245','<div class="desc"> <p>This course examines the individual cultural and structural explanations for the presence and persistence of income and wealth inequality in the U.S. The impact of inequality on social groups and the social policies developed to curtail poverty are also considered.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(271,2022,374,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-265','<div class="desc"> <p>In this course we will critically examine the ways gender informs the social world in which we live. Our goals for this course will be 1) to reveal the "common-sense" world of gender around you; 2) to consider how we learn to "do" gender; 3) to expose the workings of the institutions that shape our gendered lives; and 4) to come to an understanding of the relationship between gender and the social structure.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(272,2022,375,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-304','<div class="desc"> <p>This course looks at the ways sociologists collect information about social phenomena with a special emphasis on what can be done to yield information that is trustworthy and useful for our theoretical understanding of social life. It assumes no background in research methods or statistics. We will talk about the scientific method the complexities of applying methods to social research ethics and bias and research design. You will be given an overview of major "quantitative" and "qualitative" methodologies including surveys interviews ethnography experiments participant observation or content analysis.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(273,2022,376,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-325','<div class="desc"> <p>This course introduces the field of criminology. The course is designed to provide a broad understanding of the etiology of crime (i.e. what causes crime?) the measurement of crime and theories of criminal punishment. We will also discuss a wide range of criminal behaviors with a focus on violent crime and property crime (e.g. homicide sexual assault shoplifting white collar crime etc.). The final component of the course focuses on the American criminal justice system. This course emphasizes a sociological approach to understanding crime criminal behavior and criminal justice.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(274,2022,377,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-330','<div class="desc"> <p>This course will focus on classical and contemporary theories of power and authority; theories of the state and various forms of state power the state and government the nature of democracy and political elites in modern society (especially the United States) as well as the social bases of political parties and voting behavior.</p> </div>','SOC 101, SOC 102, SOC 105, or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(275,2022,378,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/400/soc-490','<div class="desc"> <p>Seminar is offered in conjunction with sociology majors'' ongoing library research for the senior thesis. Seminar meetings will be devoted to discussion and critique of work in progress. We strongly encourage students to have taken Classic or Contemporary Theory Sociological Inquiry and Qualitative Quantitative or Field Methods before taking the senior seminar (always taught in the Fall). <em>Open only to senior Sociology majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(276,2022,380,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/100/span-101','<div class="desc"> <p>Introduction to Spanish through a variety of communicative approaches. Emphasis is placed on speaking and listening as well as grammar and writing. <em>Students who have had more than one year of Spanish in high school or more than one quarter in college may not take this course for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(277,2022,381,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/100/span-102','<div class="desc"> <p>This course is a continuation of SPAN 101. Students are introduced to the culture of the Spanish-speaking world through readings and discussions.</p> </div>','SPAN 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(278,2022,382,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/100/span-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only. </em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(279,2022,383,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/200/span-201','<div class="desc"> <p>This course focuses on the development of speaking and writing skills. Students read and discuss cultural and literary texts from a variety of Spanish-speaking countries. The fundamentals of Spanish grammar are reviewed.</p> </div>','SPAN 102 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(280,2022,384,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/200/span-202','<div class="desc"> <p>This course is intended to further develop language skills while introducing students to the fundamentals of literary analysis through a study of Mexican South American and Spanish literary texts. Particular emphasis is placed on oral communication and writing. <em>This course parallels SPAN 211 and is designed for non-native speakers of Spanish. Students may not take both for credit.</em></p> </div>','SPAN 201 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(281,2022,385,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/200/span-211','<div class="desc"> <p>This course is designed for students who have spoken some Spanish in the home and are able to understand spoken Spanish well. It aims to develop and improve students'' conceptual understanding of the grammatical structures of the Spanish language. Coursework emphasizes the practice of formal written and oral Spanish as well as the improvement of vocabulary with the goal of strengthening students’ fluency in academic and professional contexts. Principal readings consist of literary texts (e.g. short stories, literary essays, and drama) in order to prepare students for reading and writing in upper-level Spanish courses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(282,2022,386,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/200/span-251','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(283,2022,387,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-303','<div class="desc"> <p>An introduction to major twentieth-century works of literary fiction and cinema in Latin America, with attention to the interplay of fiction and history, read in the original Spanish: Gabriel García Márquez''s <em>One Hundred Years of Solitude</em>, Isabel Allende''s <em>The House of the Spirits</em>, and stories by Jorge Luis Borges, Julio Cortázar and Roberto Bolaño. Film screenings include Cuban director Tomás Gutiérrez Alea''s <em>Memories of Underdevelopment,</em> Chilean director Patricio Guzmán''s <em>Salvador Allende</em>, and Argentine director Lucrecia Martel''s <em>La ciénaga</em>.</p> </div>','SPAN 202, SPAN 211, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(284,2022,388,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-320','<div class="desc"> <p>An analysis of the relationship between literature and film, focusing on texts from the Spanish Golden Age and their film adaptations. Issues to be discussed include film adaptation as a cultural construct; narrative voice in literature and film; the transformation of the written word to the visual image; and the relationship between politics, literature, and film. This course includes a digital liberal arts laboratory in which students engage digitized and physical materials and develop necessary skills and critical frameworks for audiovisual and web-based course projects.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(285,2022,389,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-383','<div class="desc"> <p>This course offers a representative overview of Chicano literary production covering five genres: poetry theater novel short story and essay. An historical framework is outlined to establish the different periods of Chicano creativity from its origins to contemporary times using a series of works and authors to illustrate their respective social context.</p> </div>','SPAN 301, SPAN 302, SPAN 303, or SPAN 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(286,2022,390,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/400/span-490','<div class="desc"> <p>This course will provide an in-depth analysis of one or more of the following genres: drama poetry essay novel short story and film with an introduction to contemporary literary film and cultural studies theory. Texts will be drawn from Spain and Latin America. Open only to Spanish majors in their senior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(287,2022,392,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-101','<div class="desc"> <p>The ability to read a play with insight and imagination is foundational to studying and making theater. Because playscripts are meant for the stage and not the page, the techniques we use to read them are uniquely challenging. In this course, we study scripts by a variety of contemporary American playwrights, investigating the elusive relationship between the text and its ultimate destination - the live stage. By focusing on the essential elements of dramatic writing (including character, structure, language, and thematics), and placing scripts in their social, cultural and political contexts, we work to unlock each narrative’s full performative potential. Our understanding is enhanced by creative research projects and viewing key productions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(288,2022,393,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-110','<div class="desc"> <p>This course is the foundation of our acting program. In it our students explore how an actor gives life to words and moves from a script to active performance. Students work with Shakespeare''s sonnets as well as contemporary pieces to develop physical and verbal facility as well as interpretive skill.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(289,2022,394,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-120','<div class="desc"> <p>In this course we introduce students to many of the different areas of theater production with a primary focus on scenic construction, also including drafting, lighting equipment, rigging practices and special effects. <em>The course includes a laboratory through which techniques taught in class are applied. The laboratory averages 36 hours over the semester with laboratory schedules to be arranged with the instructor. Students are required to purchase some materials for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(290,2022,395,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-121','<div class="desc"> <p>Our production laboratories are applied courses for student designers, technicians and managers who are on crews of productions directed, designed or directly supervised by faculty members in the department. In order to complete a theater minor or major, students are required to complete production laboratories in two separate areas, one of which must be a running crew for a department production. The course may be repeated for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','THEA 120 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(291,2022,396,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-122','<div class="desc"> <p>These laboratories are designed for our student designers technicians and managers who are given primary responsibility on production crews directly supervised by faculty members in the department. In the laboratories students pursue additional research and practical applications beyond the requirements of THEA 121 and may use this course to meet one of the THEA 121 requirements for a major or minor. </p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(292,2022,397,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-130','<div class="desc"> <p>In this course students study the theory and apply the methodology of the Jose Limón Technique. Developed from the principles of fall and recovery the Limón Technique is built upon motion through succession suspension alignment and opposition. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(293,2022,398,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-133','<div class="desc"> <p>Tai Chi Chuan is the study and practice of slow controlled movement, breathing, and realignment of the body. Sometimes referred to as standing yoga, Tai Chi Chuan has been practiced for centuries for its many benefits, including stress management, disease prevention, and increase in energy. Our focus in this class is on relaxation, gentle movement, and meditation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(294,2022,399,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-134','<div class="desc"> <p>In <em>Beginning Ballet</em> we study the principles and execute the techniques of ballet based on the Vaganova method. Students are taught the fundamentals and elementary vocabulary of ballet through <em>barre</em> center and traveling combinations and exercises. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(295,2022,400,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-137','<div class="desc"> <p>This is an introduction to a study of choreography based on the Nikolais/Mettler methods of creating dances. Our tools include the manipulation of motion through space time shape and energy volumes within the context of the body and its surroundings; and our work culminates with studio performances of pieces choreographed by the students in the class. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(296,2022,401,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-139','<div class="desc"> <p>Exploring the richness of African dance and music traditions from four African regions, this course is devoted to the study of authentic dances, songs and drumming from Africa, as well as their historical and cultural contexts. Students may choose to focus on either dance or percussion. Percussion students will learn traditional rhythms for djembe and talking drum as they inform and interact with dance movements. Dancers begin with exercises to condition our bodies for the rigor of the African Dance forms -- developing strength, stamina, coordination, flexibility, and rhythmic awareness, and move to the informed and joyous practice of the dances. <em>Graded on a Credit/No Credit basis only. May be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(297,2017,402,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/THEA-Theater/100/THEA-140','<div class="desc"> <p>Students in this course are introduced to fundamental Afro-Caribbean dance techniques and complex body isolations. We explore dances that reflect the various African influences upon the Caribbean-particularly upon Cuba Jamaica Puerto Rico and Trinidad and Tobago. As we move through the semester students in the class acquire understanding of the particular relationship of the music to the dances as well as a broad understanding of the cultural historical and social content of the dances of the Caribbean. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(298,2022,403,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-142','<div class="desc"> <p>In this course students study folk and historical dances drawn from Eastern and Western Europe along with folk dances of the United States derived from those traditions. Performance opportunities may include Viennese waltz and dance-based children''s theater. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(299,2022,404,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-202','<div class="desc"> <p>Looking at a small number of Shakespeare''s scripts from the vantages of actor director and playwright we examine the unique and complex relationship between Shakespeare''s literary constructions and their possible performances. We analyze how through language and structure he develops characters of psychological complexity; how he develops stories from extra-theatrical material; and how in style and subject matter his scripts relate to one another. This course offers students a bridge between literary study and theatrical enactment: looking closely at Shakespeare''s designs from the perspective of the theater practitioner-from in most ways Shakespeare''s own perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(300,2022,405,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-210','<div class="desc"> <p>In this course students develop a deeper sense of physical expression, kinesthetic response, ensemble work, creativity, and imagination. Students apply this training in solo and scene work both in the studio and on camera. At the end of the semester, students apply the preparation and techniques learned throughout the semester in final scene projects using script analysis, character work, object work, and physical expression in both classical and contemporary texts. <em>There is a ticket fee not to exceed $50 for this course.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(301,2022,406,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-211','<div class="desc"> <p>Our Performance Laboratory is offered as an applied acting course based upon roles played in our professionally directed Keck Theater productions. This course is offered only for grades of Credit/No Credit and may be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(302,2017,407,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/THEA-Theater/200/THEA-233','<div class="desc"> <p>In this course students with a basic grounding in the discipline learn more advanced techniques of Tai Chi Chuan the study of slow controlled movement breathing and realignment of the body. <em>There is a course fee of $85. This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','Two semesters of THEA 133 or permission of the instructor',NULL,NULL);
INSERT INTO course_descriptions VALUES(303,2022,408,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-234','<div class="desc"> <p>Students develop and refine ballet technique based on the Vaganova Method. This course is offered only for grades of Credit/No Credit and may be repeated for credit.</p> </div>','Two semesters of THEA 134, by or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(304,2022,411,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-244','<div class="desc"> <p>Our stage management course introduces students to the art and techniques of stage management helping them acquire the theoretical knowledge and the practical skills to manage theatrical productions from casting through performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(305,2022,412,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-260','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take 260 and 261 in either order. In four intensive sessions, students learn five workshops geared to the third grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited.</p> </div>','THEA 110 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(306,2022,413,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-275','<div class="desc"> <p>Our course in scenic design provides intermediate training in technique and exploration of theory specifically aimed at designing scenery for the theater. Our students learn several methods for developing and communicating their design ideas including basic drawing and drafting concepts CAD drafting using <em>VectorWorks</em> and both physical and digital model-making. <em>There is a materials fee of $60 for this course.</em></p> </div>','THEA 120, THEA 175, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(307,2022,414,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-301','<div class="desc"> <p>As artists and scholars, we will discuss and study several key moments in theater history from Greek Drama to Medieval religious performances to modern and experimental theater. Throughout the semester we will examine theater-in-context, attending to the circumstances (political, social, historical, and artistic) surrounding the performance event. We will engage with drama theory to deepen our analysis of dramatic texts and the performances of them. With an emphasis on close readings, critical thinking, and creative engagement with the materials, we will interrogate the boundaries between performers and audience and the ways theater makers have used performance to challenge or affirm the status quo. <em>There is a ticket fee of $75 for this course.</em></p> </div>','THEA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(308,2022,415,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-310','<div class="desc"> <p>Acting 2 advances the techniques and skills introduced in Acting 1. Students will continue to explore character development and scene work through an array of texts and styles. Students will also explore acting methods that will help them become more flexible, daring, collaborative, and creative performers. An emphasis will be put on Solo-Performance techniques. Students will actively create a self-sustaining piece of solo theater from conception to creation and finally to the stage. Course participants will also discover and evaluate texts and performance practices of previous solo-theater practitioners. In the process, students will learn how to act with increased freedom and to create characters with genuine psychological complexity, accumulating tools and skills applicable to working both on stage and on screen.</p> </div>','THEA 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(309,2022,417,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-311','<div class="desc"> <p>Our upper-division applied acting course is available for students performing significant roles in professionally directed Theater Department productions. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit. It is available only with permission of the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(310,2022,418,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-370','<div class="desc"> <p>This course develops a deeper understanding of the process of costume design for theater and film. Students will develop individual costume processes by learning to research, conceptualize, and design. In addition to creative aspects of design, students will develop the ability to break down scripts for both the stage and screen, learn to budget for shows, and develop a language within the industry. Prior art experience is not mandatory. Free hand drawing, digital rendering, and collage will be explored and developed in projects for the course.</p> </div>','THEA 175 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(311,2022,419,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-380','<div class="desc"> <p>We engage our students in Playwriting with the art of writing for the live stage. Through reading scripts by established authors and generating original writing, students develop their dramatic skills and theatrical imaginations. Creative assignments focus on crafting well-developed characters, sound story structures and compelling dialogue. As a final project, each student writes and rewrites a short play. Sophomore standing or permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(312,2022,420,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-390','<div class="desc"> <p>For advanced theater students we offer an applied course for significant work undertaken in performance design technical theater or management in faculty-supervised projects. A student enrolled in this course works directly with a faculty mentor in the design and execution of the individual project. </p> <p>Section 1 - Advanced Projects in Theater: Story/Voice/Community </p> <p>Section 2 - On-campus projects</p> <p>Permission of instructor required. Course may be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(313,2022,421,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/400/thea-490','<div class="desc"> <p>This is a course for students engaged in senior comprehensive projects in Theater. <em>Only open to senior Theater majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(314,2022,423,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-101','<div class="desc"> <p>This is an introductory course on environment and society designed for students with an interest in urban and environmental issues who might want to pursue further studies in Urban and Environmental Policy. It is also offered for those who are interested in the topic even though they will be pursuing another major. The course will include lectures and presentations in several different topical areas; films and speakers that provide insight into the environmental problems and alternative solutions including those based here in Los Angeles; and class discussions and presentation sessions on the readings and topics. The course provides an broad introduction into core topics in urban and environmental policy such as: water issues (where our water comes from); wastes and hazards issues (sources and impacts of pollution); climate change transportation and land use issues (where we work and live and commute); nature in the city (the urban environment); and food system issues (where our food comes from and how it is manufactured and sold) the intersection of science and policy and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(315,2022,424,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-205','<div class="desc"> According to Thomas Jefferson, America was to be an "agrarian Republic" -- a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones as well. Indeed, for many early migrants, America was itself a "city on the hill" -- an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing in the second half specifically on Los Angeles, where new forms of decentralized urbanism took form in the twentieth century. We will explore not only suburbia and freeways, Disneyland and other quasiÂ­urban outposts, but also the changing character of the inner city in the midÂ­twentieth century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today -- multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism -- the changing character of public space, the turn to privatism, and the neglect of public transport infrastructures, challenges to democracy and equality -- are ultimately compatible with the American dream of the "city on the hill" for the twentyÂ­first century. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(316,2022,425,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-246','<div class="desc"> <p>This course will give students applied project management experience in sustainability and urban climate resilience. Students will work on projects with partner organizations in Los Angeles addressing issues such as organic waste management, food recovery, urban forestry, food supply chains, ecological restoration and more. This course will engage students in the larger movement for sustainability in Los Angeles as well as on campus. Note: this course will require students to travel independently off-campus. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(317,2022,426,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-304','<div class="desc"> <p>This course trains students in research methods and analysis to understand environmental economic social and political issues relevant to urban planning environmental studies and related policy areas. Students will learn quantitative and qualitative methods with a particular emphasis on community based research methods. Through class lectures discussions field work and group presentations students learn and apply the most commonly used strategies for collecting analyzing and presenting data used in urban and environmental policy research and analysis. Students will work with commonly used data sets such as the Census data sources for health property ownership toxic releases campaign contributions and other information used in urban planning environmental and public policy research. Students will also learn qualitative and basic quantitative research methods including survey construction and analysis participant observation case studies methodologyinterview techniques and basic data analysis using excel.The course will also address ethical challenges raised during collaborative research alongside community-based partners and advocacy groups. The course provides the research fundamentals for the comprehensive research projects in the UEP major.</p> </div>','UEP 101, UEP 106, POLS 106, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(318,2022,427,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305','<div class="desc"> In this course, students will learn how to document and analyze urban and environmental problems and public policies using quantitative data. Quantitative data provide a compelling means by which we can understand the magnitude of urban problems and who is impacted by these problems across demographic groups, neighborhoods, cities, and countries. Quantitative data can also help identify solutions, including public policies, and then evaluate the effectiveness of those solutions. Ultimately, our task is to develop quantitative reasoning skills in order to mobilize facts in the pursuit of a more just and equitable urban society. In the words of urban geographer Elvin Wyly: "Get mad. Get data. Get to work." Or, as Daniel Patrick Moynihan once said: "You can''t solve a problem until you first learn how to measure it." An important aspect of the course is how to make relevant and meaningful comparisons. How can we understand the size and significance of an urban problem such as low-wage work, or housing discrimination, racial profiling by police, or air pollution? We understand these issues best in relation to other outcomes: good jobs, nondiscriminatory housing and police practices, and clean air. We need to measure these outcomes in ways that we can compare them. Toward that goal, students will learn basic mathematical calculations and concepts such as percentages, rates, normalization, baselines, distributions, and probability. We will learn to read and interpret quantitative information presented in various formats, such as tables, graphs, geometric figures, or in text. Students will learn to assess numeric arguments and "answers" for reasonableness, as well as to recognize the limits of quantitative methods. Lastly, students will learn to evaluate how quantitative data is used, and sometimes misused, in the news media and public debates about social, economic, and environmental problems. Students will also engage basic questions of research: What data do we need to answer relevant policy questions? How can we devise a research project that would generate these data? Students will explore basic research methods using quantitative data, such as specifying a research question, research design, sampling, measurement, and validity. </div>',NULL,'UEP 305A ',NULL);
INSERT INTO course_descriptions VALUES(319,2022,428,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-310','<div class="desc"> <p>This seminar focuses the techniques of grassroots empowerment particularly in urban settings. This includes the following topics: developing leadership skills for citizen participation and problem solving using the media building coalitions choosing issues doing action-oriented research understanding the relations of power mobilizing constituencies developing a community oriented public policy agenda the history of community organizing in the U.S. and comparison between community development social work and direct action organizing approaches. <em>Must be taken simultaneously with UEP 311.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(320,2022,429,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-311','<div class="desc"> <p>This course provides opportunities for applying and learning through direct experience about the practice of community organization and leadership. Each student will work with a community-based organization engaged in influencing public policy for approximately 12-15 hours each week. Students will be supervised jointly by the faculty member and a staff person for the community organization. <em>Must be taken simultaneously with UEP 310.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(321,2022,430,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-410','<div class="desc"> <p>Intensive study of the making of national and local public policy in the U.S. including the political environment in which policy debates take place. Extensive use will be made of case studies on a variety of domestic and international issues. Students will participate in the development of a major research project related to their senior comprehensive project on an individual or group basis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(322,2022,432,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/100/amst-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(323,2020,433,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/200/amst-240','<div class="desc"> <p>In the 1970''s, African-American women writers dominated the literary market. The novels and memoirs of Toni Morrison, Maya Angelou, and Alice Walker were read and praised widely. Though the 1970''s saw a surge in their popularity, African-American women had been writing since the nation''s inception, as exemplified by Phillis Wheatley''s 1773 volume of poems. Throughout its literary history, African-American women''s writing has reflected upon, and often challenged, assumptions about American identity and experience, racial justice, and gender and sexual norms. This course surveys the long history of this literature and focuses, especially, on texts that supply world views inflected by the particular experience of living as American, black, and female. Authors under consideration include those mentioned above, as well as June Jordan, Audre Lorde, Toni Cade Bambara, Sojourner Truth, Sonia Sanchez, Octavia Butler, and Evie Shockley.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(324,2022,434,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(325,2022,435,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/300/amst-390','<div class="desc"> <p>This course engages students in the history, practice, and research methods in American Studies by focusing on the significance of place, identity, and rights.While we will focus on the territory known as the United States, our readings and research will trouble the security of that designation. By examining the origins of settler colonialism in the Americas, focusing upon national borders and internal boundaries, and exploring the United States'' global reach, we will study and develop different ways of understanding "America" as a product of civic rights that are extended and denied. Students will apply American Studies theoretical methods in a research project of their choosing, and majors will develop this work into their senior comprehensives project. Offered only in spring semester. Majors are encouraged to study abroad in the fall semester to align this requirement with their progress toward the major. </p> </div>','AMST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(326,2022,436,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/300/amst-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(327,2022,437,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/400/amst-490','<div class="desc"> <p>This course is designed to assist students with the completion of research papers on topics that reflect selected areas of emphasis in American Studies. It will provide an opportunity for seniors to synthesize their area of specialization with an analysis of critical issues in the study of American culture and society. Offered only in fall semester (following AMST 390 in the spring). </p> </div>','AMST 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(328,2022,438,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/400/amst-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(329,2022,440,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/100/arab-102','<div class="desc"> <p>Continuation of ARAB 101.</p> </div>','ARAB 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(330,2022,441,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/300/arab-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(331,2017,443,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-261','<div class="desc"> <p>A survey of Buddhist art as it originated in India and spread across Central Asia to China Japan and Tibet. We will devote special emphasis to the ways Buddhism and Buddhist art both changed and were changed by the various cultural traditions they encountered. We will also examine the history of "Western" encounters with Buddhism and how these have shaped - or biased - our understanding of Buddhist art and culture. Not open to students who have taken ARTH 160.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(332,2017,444,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-280','<div class="desc"> <p>This course is designed as an introduction to the life and work of Michelangelo Buonarroti (1475-1564). We will investigate his painting sculpture and architecture while considering its context within the major urban cultural centers in which he worked: Florence and Rome. The course will proceed chronologically but will vary from week to week as to relevant themes and methodological approaches to the career of arguably the most influential of all Renaissance artists. Among those topics to be explored: development and dissolution of a classical vocabulary; relationships between style and technique; art biography and self promotion; the relationship between Christianity and sexuality for Michelangelo and the Cinquecento; patronage and context in Florence and Rome; the development of classical form; meaning in the restored Sistine Chapel.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(333,2022,445,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-287','<div class="desc"> <p>What is a photograph? Is it a "document" or a "work of art"? Who makes a photograph and for whom does s/he make it? How and where do photographs circulate? What effect does the context in which a photograph is viewed have on its meaning? Designed as a selective history of photography in the 19th and 20th centuries, this course revolves around questions like these about the nature and function of photography in modern culture. Through varied course readings, in-class discussion, thematic lectures, and hands-on research, students will explore the medium of photography from multiple perspectives. In addition to learning about the different photographic genres - exploration and travel photography, studio and portrait work, medical and legal documentation, fine art prints, photojournalism - this class will push students to investigate photography''s position within a broader cultural field: the medium''s role in advertising and consumer culture; the production and circulation of ideas about race, gender, and national identity; and photography''s role in producing history itself. Readings will include primary source materials and theories of photographic meaning; students will be asked to grasp not only the medium''s technological and rhetorical functions, but also to develop their own critical perspectives on photography''s shifting relations to intellectual, social, and political ideologies. Coursework will include some community-based research, and a museum visit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(334,2022,446,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(335,2022,447,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/400/arth-490','<div class="desc"> <p>Open only to senior Art &amp; Art History majors with an emphasis in History of Art. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(336,2022,448,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/400/arth-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(337,2022,450,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-210','<div class="desc"> <p>Intermediate study in painting, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year.</p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(338,2022,451,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-217','<div class="desc"> <p>An introduction to new combined photo and drawing processes in printmaking, including: photo-sensitive emulsion on copper plates, solar etching, and paper plate lithography. This course will explore how photography can influence the many approaches to contemporary printmaking. Students should have an interest in creating photo images and some familiarity with Photoshop software.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(339,2020,453,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-325','<div class="desc"> <p>Advanced course in papermaking with emphasis on the creative potential of handmade paper. Projects include: colored pulp painting, cast paper, and sheet forming, with a major focus on making three handmade paper artists'' books.</p> </div>','One course in Studio Art ',NULL,NULL);
INSERT INTO course_descriptions VALUES(340,2022,454,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/300/arts-390','<div class="desc"> <p>Art in LA will explore the shifting roles of the contemporary artist, art writer, and curator in today''s diverse and globalized art world. Students will put theory into practice by engaging in art making, curating and writing about contemporary art in Los Angeles with the goal of creating an expansive critical space for their thoughts to flourish. The course will ask, "What are exhibitions?” investigating conventional and alternative curatorial practices that question the cultural, political, economic, regional, and social contexts shaping the exhibition of contemporary art. Students will collaborate to mount an exhibition of their own design, and will be encouraged to question the boundaries of the "white cube gallery," pushing art into surprising public and private spaces. <br/> <br/> Art in LA will feature behind the scenes visits to Los Angeles area exhibition venues and artists'' studios, enabling students to learn about the range of art practices and the practical exigencies of bringing art and its exhibition to fruition. This course will serve as the required advanced exhibition methods course for junior studio art majors, modeling the myriad of ways it means to be an artist in the world, and readying rising seniors for a robust comprehensive experience. Scheduled at the same time as the Studio Art Senior Seminar, the course is designed to facilitate collaboration between junior and senior art majors. Students in ARTS390 will participate in the ARTS490 senior comps critiques, provide feedback to senior''s artist statement drafts, and collaborate with the senior art majors in the installation of their comprehensive exhibition. </p> </div>','One 200-level ARTS course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(341,2022,455,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/300/arts-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(342,2022,456,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/400/arts-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(343,2022,457,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bich-biochemistry/400/bich-499','<div class="desc"> <p>Independent study under the supervision of a faculty member. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(344,2022,459,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-197','<div class="desc"> <p>Research in biology for students who do not have advanced competence in biology (see BIO 397). </p> </div>','Permission of instructor and department chair ',NULL,NULL);
INSERT INTO course_descriptions VALUES(345,2022,460,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-221','<div class="desc"> <p>This course focuses on understanding the processes in a cell, at a molecular level, that transfer information from genetic information through the expression of functional proteins. Topics include: basic structure of DNA, RNA, and proteins; gene structure; chromosomal organization; genomic structure and organization; DNA replication; transcription, translation, and processing of gene products; molecular regulation of gene expression, mechanisms in prokaryotes and eukaryotes; regulatory and catalytic RNA, including siRNA and miRNA; and the techniques to study these processes. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 and CHEM 220; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(346,2017,461,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-221L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(347,2022,462,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-250','<div class="desc"> <p>This course is a comprehensive introduction to the plant kingdom, emphasizing the ways in which organismal form and structure are shaped through evolutionary and ecological processes. The primary goal of the course is for students to learn how a major life form has adapted to physical factors, such as light and water, and to biological factors, such as fungi, insects, and vertebrates. Labs involve experimental analysis of fundamental processes, such as: water uptake, photosynthesis, and hormonal regulation, as well as hands-on investigation of the vegetative and reproductive adaptations of the plant kingdom. Independent lab projects and field trips are also key components of the course. <em>Includes one three hour laboratory session per week.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 250L ',NULL);
INSERT INTO course_descriptions VALUES(348,2017,463,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-250L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(349,2022,464,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-270','<div class="desc"> <p>Ecology explores the interactions between organisms and their biotic and abiotic environments at a variety of spatial and temporal scales. Topics include: factors affecting organisms at the population, community, and ecosystem levels and the effect of human actions on natural systems. Practical aspects of studying ecology involve work in the laboratory, computer simulations and modeling, and field work. This course emphasizes the fundamentals of study, design sampling, field techniques, data analysis, and written and oral presentation of results. <em>Includes one three-hour laboratory per week and weekend field trips to be arranged.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 270L ',NULL);
INSERT INTO course_descriptions VALUES(350,2017,465,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-270L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(351,2022,466,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-323','<div class="desc"> <p>An introduction to histology. Lectures present the structure and function of cells, tissues, and organs in healthy and diseased conditions. The laboratory introduces students to preparation of tissue for paraffin, plastic, and cryostat sectioning and examination by light and electron microscopy. Students work on projects of their own choice. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 and BIO 105 or BIO 115 ','BIO 323L ',NULL);
INSERT INTO course_descriptions VALUES(352,2022,467,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-323l','<div class="desc"> <p>Laboratory techniques in histology. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 323 ',NULL);
INSERT INTO course_descriptions VALUES(353,2022,468,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-325','<div class="desc"> <p>An introduction to the world of microbes, including viruses, archaea and bacteria, and their role in shaping and sustaining life on Earth. Emphases will be placed on structure, metabolism and bioenergetics, physiological and biochemical adaptations to unusual environments, phylogenetic analysis, biotechnology, microbial ecology, and biological interactions, including plant and animal symbioses. Laboratory exercises will include an exploration of microscopy, cultivation, biochemical techniques, and molecular tools for studying microorganisms. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 221, BIO 222, BIO 224 , BIO 270, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(354,2022,469,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-325l','<div class="desc"> <p>Students will examine microbial growth, form, and function, and will select familiar environments from which to investigate microbial life. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 325 ',NULL);
INSERT INTO course_descriptions VALUES(355,2022,470,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-340','<div class="desc"> <p>Dynamic physiological properties will be examined in single cells, tissues, and whole organisms. Emphasis will be placed on sensory physiology and neuroethology (study of the neural basis of natural animal behaviors). Laboratories will utilize advanced recording techniques, including microelectrodes, isometric tension measurements, semi-intact preparations, and modern electronics.</p> </div>','One of the following: BIO 226, BIO 240, BIO 333, CHEM 301, COGS 250, PSYC 312, PSYC 322, PSYC 403; or permission of instructor ','BIO 340L',NULL);
INSERT INTO course_descriptions VALUES(356,2022,471,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-340l','<div class="desc"> <p>Fundamental physiological processes will be investigated using advanced recording techniques, including microelectrodes, isometric tension measurements, semi-intact preparations, and modern electronics. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 340 ',NULL);
INSERT INTO course_descriptions VALUES(357,2022,472,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-369','<div class="desc"> <p>Biological oceanography will focus on the biology of the open ocean, with emphasis placed on relating parameters of the physical-chemical ocean to the distribution and abundance of marine organisms. We will focus on understanding the physical and biological processes of the Southern California marine area using field and laboratory techniques. Using examples from our local ecosystem, students will explore the intricacies of macro-scale oceanographic processes. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 260, BIO 270, or permission of instructor ','BIO 369L ',NULL);
INSERT INTO course_descriptions VALUES(358,2022,473,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-369l','<div class="desc"> <p>Laboratory techniques in Oceanography. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 369 ',NULL);
INSERT INTO course_descriptions VALUES(359,2022,474,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-397','<div class="desc"> <p>Directed research with individual faculty members for students with advanced competency to study in an area not otherwise included in the departmental curriculum. In addition to topics that may be studied on the Occidental campus, courses offered at the marine station of the Wrigley Institute for Environmental Studies may be taken for credit under this course number. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(360,2022,475,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/400/bio-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(361,2022,476,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/500/bio-501','<div class="desc"> <p>Supervised investigation by properly qualified graduate students working toward a Master''s degree. Students may not register for more than two courses of Research during any semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(362,2019,477,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/BIO-Biology/500/BIO-525','<div class="desc"> <p>An introduction to the world of microbes including viruses archaea and bacteria and their role in shaping and sustaining life on Earth. Emphases will be placed on structure metabolism and bioenergetics physiological and biochemical adaptations to unusual environments phylogenetic analysis biotechnology microbial ecology and biological interactions including plant and animal symbioses. Laboratory exercises will include an exploration of microscopy cultivation biochemical techniques and molecualr tools for studying microorganisms. Includes one three-hour laboratory per week.</p> </div>','BIO 221 BIO 222 BIO 224 or BIO 270 or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(363,2022,479,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/500/bio-599','<div class="desc"> <p>Continuing work on Master''s thesis. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(364,2022,481,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/200/chem-240','<div class="desc"> <p>Building on concepts developed in prerequisite classes, fundamental concepts in thermodynamics are developed from first principles, with subsequent application in chemical equilibrium and kinetics. Applications to biological systems and technology are emphasized. The substantive laboratory component focuses on developing analytical skills.</p> </div>','CHEM 120 or CHEM 130 ','CHEM 240L ',NULL);
INSERT INTO course_descriptions VALUES(365,2017,482,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CHEM-Chemistry/200/CHEM-240L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(366,2022,483,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/200/chem-280','<div class="desc"> <p>The course will explore the application of 1H, 13C, and two-dimensional NMR spectroscopy to the organic laboratory, as well as the important separation protocols such as: column chromatography, gas chromatography, and chiral HPLC. <em>Includes one-three hour laboratory per week.</em></p> </div>','CHEM 221 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(367,2022,485,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-350','<div class="desc"> <p>Biochemistry of macromolecules, with an emphasis on protein structure and function.</p> </div>','CHEM 221 and CHEM 240 ','CHEM 350L',NULL);
INSERT INTO course_descriptions VALUES(368,2022,486,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-350l','<div class="desc"> <p>Laboratory techniques in Biochemistry. <em>One three-hour laboratory per week.</em></p> </div>','CHEM 221 and CHEM 240 ','CHEM 350 ',NULL);
INSERT INTO course_descriptions VALUES(369,2022,487,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-360','<div class="desc"> <p>An introduction to the study of physical organic chemistry, with special emphasis on bioorganic chemistry, bio-macromolecular structure, and biological sequence analysis.</p> </div>','CHEM 221 and CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(370,2022,488,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-397','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(371,2022,489,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/400/chem-499','<div class="desc"> <p>Independent study leading to an honors project. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(372,2022,491,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/100/chin-102','<div class="desc"> <p>Continuation of Chinese I. Conversation, reading, elementary composition; completion of basic grammar.</p> </div>','CHIN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(373,2022,492,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/200/chin-202','<div class="desc"> <p>Continuation of CHIN 201.</p> </div>','CHIN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(374,2022,495,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/300/chin-350','<div class="desc"> <p>Readings in short classical Chinese texts, from pre-Qin historical, philosophical, and literary works that are the sources of sayings still common in modern vernacular Chinese. Students will learn the grammar, structure, and vocabulary of classical Chinese (wenyan) and gain advanced proficiency in modern spoken (baihua) and literary (shumianyu) Chinese, through exercises in oral and written discussion and analysis of the use of classical Chinese thought and sayings in contemporary Chinese language and culture. Course offered every four years.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(375,2022,496,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/300/chin-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(376,2022,498,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-210','<div class="desc"> <p>Can one create intelligent machines? Machines capable of posing and solving problems and capable of interacting effectively with a complex and dynamic environment? If so, how? And what insights into natural cognition do we gain through efforts to create artificial intelligence? Fundamental principles, architectures, and algorithms for machine perception, control, and problem-solving will be addressed. We will also look, in detail, at strategies for developing intelligent machines, including traditional Artificial Intelligence and the more recent perspectives of situated and embodied cognition. The laboratory component of the course will involve computing and simple robotic devices.</p> </div>','COGS 101, 4 units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(377,2017,499,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/COGS-Cognitive-Science/200/COGS-210L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(378,2022,500,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320','<div class="desc"> <p>This course will introduce students to the biology of the mind. It will provide an overview of neuroanatomy and characterize the neural mechanisms supporting complex cognitive processes including vision, attention, consciousness, language, memory, learning, emotion, and action. We will also emphasize the importance of converging methodologies in studying the link between the mind, brain, and behavior. Methodologies we consider include: behavioral measures of cognition, neuropsychology, electrophysiology, anatomical and functional neuroimaging, single-cell recordings, and computational modeling. Laboratory sessions will allow students to obtain hands-on experience with these methodologies, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>','COGS 201, PSYC 200, BIO 268, or permission of instructor ','COGS 320L ',NULL);
INSERT INTO course_descriptions VALUES(379,2022,501,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(380,2022,503,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-165','<div class="desc"> <p>Introduction to using Mathematica for mathematical calculation and programming.</p> </div>','Prior programming experience in any language OR any of the following Math courses: MATH 109, MATH 110, MATH 114, MATH 120, MATH 128, MATH 210, MATH 212, or MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(381,2020,504,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/comp-computer-science/200/comp-211','<div class="desc"> <p>Programming with linked data structures, including stacks, queues, trees, and linked lists. Object-oriented programming. Programming methodology. Computer systems. Ethics in computing. Weekly laboratory.<em></em></p> </div>','COMP 161 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(382,2022,506,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(383,2019,507,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/CTSJ-Critical-TheorySocial-Justice/100/CTSJ-186','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(384,2022,508,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-201','<div class="desc"> <p>This course examines intersectional gender representations in film, television, literature, memes, and other forms of contemporary popular culture. Students will learn theories of media influence and analyze the impact of pop culture in shaping cultural values and norms, primarily in the United States. Students will also examine how different identity groups are portrayed, and the effect of media under-representations, stereotypes, tropes, and other miss-representations on their social value and lived experiences.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(385,2020,509,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-230','<div class="desc"> <p>This class is designed to introduce the classical texts of Anglo-American queer theory, as well as explore recent trends in the field. While situating queer theory''s 1990''s academic advent in its historical context of identity politics, the emergence of the AIDS pandemic, and the U.S. "culture wars," the course will begin by reviewing crucial antecedents in gay and lesbian studies, psychoanalysis, and the interventions of Michel Foucault. Readings will include works by Judith Butler, Eve Sedgwick, Leo Bersani, Lee Edelman, and Teresa de Lauretis. Additional readings will trace recent debates over "what is still queer in queer theory?" as critics engage ongoing questions about neoliberalism, homonormativity, and politics, in the 21st century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(386,2022,510,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-257','<div class="desc"> <p>This course will take place at the Barry J. Nidorf Juvenile Hall with both Occidental College students and incarcerated students from the BJN Juvenile Hall. It will focus on the uses of the visual and performing arts, spoken word, and hip hop, as tools for positive social change, specifically examining the Prison Industrial Complex (PIC). Artists and activists have made use of artistic expression in efforts to educate about the PIC. By examining movements such as the Black Arts Movement, Theatre of the Oppressed, and Hip-Hop Theatre, students will gain an understanding of tangible ways in which artists have shaped and addressed social issues. Through collaboration with each other, students will create artistic and dialogical spaces for critical thinking. Students will create art-based workshops which they will then present to classmates. Students do not need to be artists to participate in the course, however, creative building will be an integral part of the curriculum. At the end of the course there will be a closing ceremony in which components of the workshops will be presented to the community, including the Warden and other officials. Readings include work by Augusto Boal, Paolo Freiere, Christian Parenti, and Manning Marable.</p> </div>','Sophomore standing and over the age of 18 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(387,2019,511,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/CTSJ-Critical-TheorySocial-Justice/300/CTSJ-320','<div class="desc"> <p>This class provides an opportunity for students who wish to continue and deepen their intellectual and community work to interact with a highly-motivated small group of students and community activists and organizations. Topics we will examine will be determined in consultation with community partners. Students will work together on a significant final project that links academic learning and community praxis and engagement. <em>Satisfies experiential learning requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(388,2020,513,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-337','<div class="desc"> <p>The course takes an interdisciplinary approach to the last decade''s increasing attention to Los Angeles as a historical origin point of United States'' LGBT history. Students are encouraged to "queer" the very concept of the archive by considering how minority voices and experiences register themselves across time, through both traditional archives and less formal communities of readership and historiography, wrought through alternative archives like pulp novels, comics, films, and even gossip. Students will be training in physical archival work, oral history, digital story telling, and mapping, all while considering the impact of the "Digital Revolution" and how LA''s particularly intersectional queer communities have mapped themselves across the so-called "digital divide." In addition to individual papers and presentations, the class will produce a "mixed media archive" as a student group final project that will both yield an exhibit at the end of the semester and serve as a template for an ongoing "queer LA archive" housed at Oxy.</p> </div>','Any 100- or 200-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(389,2022,514,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-384','<div class="desc"> <p>A close reading of the works of Georges Bataille, including: <em>The Impossible, The Unfinished System of Nonknowledge, The Accursed Share, On Nietzsche, Story of the Eye, The Dead Man, </em>and <em>Collected Poems. </em>First year students are not permitted to enroll in this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(390,2022,515,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(391,2022,516,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(392,2022,548,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-230','<div class="desc"> <p>This course will explore the evolution of women''s rights as human rights; the struggle of women''s movements to place gender-specific concerns on the international human rights agenda; and the relationship of the UN and its agencies to the broad feminist goal of advancing the political, economic, social, and cultural status of women. While "women" are, of necessity, central to the concerns of this course, the study of human rights will be approached from a gender perspective, recognizing that gender relations are key to understanding the nature, occurrence, and prevention of rights violations. Key themes to be covered in the course include: the relationship between the "crisis of masculinity" and women''s human rights, gender and economic rights, gender-based violence, and health and human rights.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(393,2022,549,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-234','<div class="desc"> <p>Revolutionary transformations and democratic transitions in Southern Africa have occurred under the conditions of the Cold War and within the framework of heightened globalization. Currently, direct foreign political interventions have been scaled back, but economic interventions by international organizations and foreign states have increased. Even though liberal democracy is winning favor the structural basis of inequality remains with increasing unemployment, poor education, weak health services, inadequate housing, soaring food and utility prices, and increasing levels of poverty. Opposition movements demand changes ranging from subsidized basic foodstuff to free education. This has contributed to political tensions as states scramble to suppress resistance while still trying to maintain the conditions required by global economic institutions. This course will examine some of the states in this region including South Africa, Mozambique, and Zimbabwe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(394,2022,551,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-260','<div class="desc"> <p>Research, discussion, and analysis of important issues in International Relations in preparation for a three-day college conference in early April. Student delegates role play as ambassadors for countries and present views negotiating with other representatives and arguing for possible resolutions in a simulation of the United Nations. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(395,2022,552,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-342','<div class="desc"> <p>This class will explore the various aspects of transnational identities, focusing on ways in which they challenge state borders and state nationalisms. The various aspects of transnational identities, like questions of citizenship, ethnicity, religion, gender, and generation will be analyzed. Special attention will be given to the ways in which Islamic beliefs have transcended state boundaries and the impact this has had on notions of citizenship. The class will also focus on a few case studies to highlight the various aspects of transnational identity. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(396,2022,553,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(397,2022,554,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-490','<div class="desc"> <p>Preparation, research, writing, and discussion of senior thesis projects in fulfillment of the Senior Comprehensive requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(398,2022,555,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/100/econ-197','<div class="desc"> <p>Internship in a business or management setting. Permission of instructor required. Course may not be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(399,2022,556,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/200/econ-297','<div class="desc"> <p>Application of modern research methods to current problems in Economics and related fields. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(400,2022,557,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-301','<div class="desc"> <p>The purpose of this course is to illustrate the role that economics can play in creating and improving environmental policy. We will apply the theories of economic efficiency, cost-benefit analysis, market failure, and property rights to environmental policy and regulation. We will cover the principles of market-based environmental policies and their applications in the world today. We will touch on all aspects of the economy''s interaction with the environment, including air and water pollution, global warming, environmental health, non-market valuation, and resource extraction.</p> </div>','ECON 101 or ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(401,2022,558,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-308','<div class="desc"> <p>This course studies the government''s role in a market economy, particularly policies that work through government spending and taxation. There are two primary motivations for government intervention: to correct a market failure or to mitigate poverty and inequality through redistribution. The course is organized around these two rationales, with attention to topics that include climate change, public education, health insurance, Social Security, welfare policy, and the taxation of goods, labor, and capital. We study how such government policies impact behavior and, as a consequence, how they should be designed to maximize welfare. This course also introduces students to the modern methodological approach in public economics that tightly connects economic theory with credible empirical evidence to generate policy insights.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(402,2022,559,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-320','<div class="desc"> <p>Theoretical and empirical analysis of the process of economic development in less developed countries. After examining several theories of growth and development, we will discuss inequality and poverty, the effects of population growth and rural-urban migration, saving and financial markets, international trade, foreign aid and foreign borrowing, agriculture, and the role of the government. Case studies will be drawn from the development experiences of Asian, Latin American, and African economies.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(403,2020,560,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/econ-economics/300/econ-361','<div class="desc"> <p>This course examines issues in Macroeconomics, beyond those typically addressed at the intermediate level, with a strong emphasis on macroeconomic policy. Specific topics include: intertemporal choice in macroeconomics, inflation, targeting and the risk management approach to monetary policy, international macroeconomics, recent advances in the study of the aggregate labor market, real business cycle models, government debt and the intertemporal government budget constraint, and time series macroeconomics.</p> </div>','ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(404,2022,561,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-395','<div class="desc"> <p>Topics vary semester to semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(405,2022,562,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-397','<div class="desc"> <p>Advanced independent research in Economics. For example, Advanced Econometrics can be taken on an independent study basis. Permission of instructor and department chair required.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(406,2017,563,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ECON-Economics/400/ECON-499','<div class="desc"> Independent research with one-on-one faculty mentoring. After a brief introduction to thesis research methods, students will develop a topic and then write and present an honors thesis. </div>','Senior status; Economics 250, 251, and 272 (or permission of the instructor); and permission of the department.',NULL,NULL);
INSERT INTO course_descriptions VALUES(407,2020,565,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/educ-education/200/educ-283','<div class="desc"> <p>This course covers the various uses of technology in the classroom, as well as other related issues (e.g. differential student access). Students demonstrate their understanding of computers and software through hands-on activities and class presentations. They illustrate how technology can be integrated across the curriculum in the classroom through written lesson plans and units. Students learn to access electronic databases for student/school-level information and for subject matter support.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(408,2022,566,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/300/educ-320','<div class="desc"> <p>Critical Race Theory (CRT) is a historic movement among legal scholars of color in the U.S. that has enjoyed widespread application in a number of disciplines, including Education. This course introduces students to CRT through a close reading of the key writings that formed the movement. We will examine the application of CRT in education, research, theory, and practice, contextualized in a variety of settings, including schools, community-based organizations, and other relevant spaces. Specific attention will be paid to the CRT methodology of counter-storytelling and its utility in centering the experiential knowledge of people of color in education.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(409,2022,568,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/300/educ-397','<div class="desc"> <p>Interested students must obtain <em>Guidelines for Independent Study</em> from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(410,2022,580,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/100/fren-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(411,2022,581,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/100/fren-197','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(412,2022,582,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/200/fren-202','<div class="desc"> <p>The methods and vocabulary of textual analysis introduced through close reading, discussion, and written commentary of selected poems, plays, and prose texts, from the Renaissance to the present. The techniques of French critical writing, oral explication de texte, and commentaire composé will be stressed. Includes study of general linguistic problems pertaining to the structure of modern French (vocabulary, phonetics, grammar style). This course is required of all French majors and minors and for students wishing to study in France.</p> </div>','FREN 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(413,2022,583,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/200/fren-252','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(414,2022,585,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-397','<div class="desc"> <p>Individual study of a major author, movement, or genre; or the teaching of French. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(415,2022,586,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/400/fren-490','<div class="desc"> <p>The seminar will focus on the close reading and informed discussion of texts from the major reading list (from Chanson de Roland and the Middle Ages to post-colonialism) within the context of literary theory (from Sainte-Beuve to Derrida), and it will focus on writing workshops designed to perfect analytical writing (techniques of the commentaire composé and the dissertation littéraire). Although open to all students, the seminar is intended, principally, to facilitate the completion of the Comprehensive examination in French. The seminar, readings, and activities will be tailored to meet individual student interests and needs. This course may be repeated for a total of 8 credits toward graduation, only 4 of which may count for the major.</p> </div>','FREN 350 or above ',NULL,NULL);
INSERT INTO course_descriptions VALUES(416,2022,587,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/400/fren-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(417,2022,589,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/100/geo-150','<div class="desc"> <p>This course focuses on teaching students how to access, integrate, and quantitatively evaluate many types of spatial information using different methods of analysis. Students use GIS software to understand, explore, and analyze information from a variety of sources, with an emphasis on understanding the geography of environmental health and the relationships between multiple determining factors. Students will learn fundamentals of geography and cartography, GIS techniques in quantitative spatial analysis, and introductory spatial statistics as applied to vector-based data. The tools and skills used in this course, and the analytical problem-solving projects used in laboratory and project assignments, will provide them with a means to better understand the environmental health risk and epidemiology, and enhance their ability to make informed and quantitative comparisons. (Students are encouraged to enroll in UEP 201, a course that explores how environmental factors impact human and ecological health).</p> </div>',NULL,'GEO 150L ',NULL);
INSERT INTO course_descriptions VALUES(418,2022,591,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-215','<div class="desc"> <p>The history of the Earth and life upon it, from the origin of the planet 4.6 billion years ago to the present. The course focuses on the chemical, physical, and biological processes that have affected the planet''s interior and surface, including atmosphere, hydrosphere, and lithosphere, through time. <em>Includes one three-hour laboratory per week and field trips.</em></p> </div>','GEO 105 or GEO 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(419,2022,593,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-235','<div class="desc"> <p>An introduction to plate tectonics and the geology of plate boundaries. Topics include: techniques for describing plate motions, earthquakes and seismology reversals of the earth''s magnetic field, the nature of the seafloor, and the geology of mountain belts. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 or GEO 106, or permission of instructor ','GEO 235L ',NULL);
INSERT INTO course_descriptions VALUES(420,2022,595,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-255','<div class="desc"> <p>This project-based course will delve into scientific questions in earth, environmental, and ecological sciences using digital data on a variety of scales, from our backyard to the globe. By investigating problems such as the timing of earthquakes on the San Andreas fault, sources of contaminants in steam water, geologic controls on plant growth, and potential effects of volcanic eruptions, students will deepen their knowledge of geologic processes and develop analytical abilities that are a foundation of scientific inquiry. Course material will focus on topics to be investigated in laboratory projects using digital tools such as geographic information systems, Excel, and Google Earth. </p> </div>','GEO 105, GEO 106, or permission of instructor ','GEO 255L ',NULL);
INSERT INTO course_descriptions VALUES(421,2022,597,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-325','<div class="desc"> <p>Study of the deformation of rocks and the structures produced. Rock mechanics are introduced and the nature and origin of folds, faults, and other structures are discussed, along with the relation of structures to tectonic settings. Course includes interpretation of areas displaying complex geological relations that illustrate structural principles. <em>Includes field trips and one three-hour laboratory per week.</em></p> </div>','GEO 225 ','GEO 325L ',NULL);
INSERT INTO course_descriptions VALUES(422,2022,598,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-325l','<div class="desc"> <em>Three-hour per week laboratory.</em> </div>',NULL,'GEO 325',NULL);
INSERT INTO course_descriptions VALUES(423,2022,599,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-390','<div class="desc"> <p>Two- or four-credit advanced courses on specialized topics in Geology. May be taken more than once with department approval as topics vary. </p> <p><strong>Science of Soils</strong></p> <p>The physical, chemical, and biological processes within soil systems are assessed. Emphasis is on factors governing the physical properties, nutrient availability, and plant growth and production within soils. How to classify soils and to assess nutrient cycling and contaminant fate will be covered. Recommended: introductory geology, chemistry and/or biology.</p> <p><strong>Paleontology: The Record of Life, Landscapes, and Changing Climate</strong></p> <p>This course will use the fossil record as a tool to explore the geologic controls on the evolution and extinction of life on earth. From Snowball Earth to the Great American Biotic Interchange, plate tectonics and climate change drive the distribution of life through time. We will examine paleontological and modern ecosystems through classes, labs, and field trips. Students should have completed GEO105 and at least one 200-level course in biology or geology.</p> <p><strong>Geochemistry</strong></p> <p>This course will explore the geochemical principles controlling fundamental geologic systems, from the "weathering engine," to the igneous-metamorphic-hydrothermal systems that form and shape planets. This overview of Geochemistry will focus on thermodynamics and kinetics, which allow us to assess these systems with regards to temperature, pressure, and time. Quantitative evaluation of earth processes through geochemical modeling will be conducted using the programs SUPCRT, Visual Minteq, and Geochemist''s Workbench (industry standards). Laboratories, workshops, and fieldtrip(s) will reinforce and expand on many of the topics covered in class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(424,2022,600,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/400/geo-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(425,2022,602,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/100/germ-102','<div class="desc"> <p>Continuation of GERM 101.</p> </div>','GERM 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(426,2022,603,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/100/germ-152','<div class="desc"> <p>Continuation of GERM 151. Designed primarily for students who have completed GERM 102. Graded on Credit/No Credit basis; attendance is mandatory. Approximately two hours of work outside of class required each week. May be repeated for credit.</p> </div>','GERM 102, GERM 151, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(427,2022,604,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-202','<div class="desc"> <p>Continuation of GERM 201 at an advanced level. Review of advanced German grammar, and exercises in stylistics and essay writing.</p> </div>','GERM 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(428,2022,605,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-252','<div class="desc"> <p>Continuation of GERM 251. May be repeated for credit.</p> </div>','GERM 251; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(429,2022,606,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-397','<div class="desc"> <p>Individual study of a major author, movement, genre, or translation technique. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(430,2022,607,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/100/grk-102','<div class="desc"> <p>Continuation of GRK 101 and reading of adapted Greek texts.</p> </div>','GRK 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(431,2022,608,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(432,2022,609,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-102','<div class="desc"> <p>This course provides an introduction to United States history from the Civil War to the early 21st century. Readings and lectures are structured around the core theme of American pluralism. They emphasize the changing demographics of the American population and consider the different strategies that Americans have used to negotiate this growing diversity over time. Topics covered include: Reconstruction, westward expansion and overseas imperialism, Industrialization and the Gilded Age, the Progressive Era, World War I, the Great Depression and New Deal, World War II and the rise of internationalism, the Cold War and third world decolonization, immigration reform and comparative civil rights movements, the Vietnam War and the rise of global dissent, conservatism and the "Reagan Revolution," America''s border wars, and the post-9/11 War on Terror. We will give particular attention to issues of race, ethnicity, gender, religion, sexuality, region, and class in the shaping of modern America. Other important themes include: the expansion of federal power and the government''s role in people''s lives, contests over national citizenship and identity, America''s changing role in the world and engagement with foreign peoples, and the demographic transformations wrought by international migration and conflicts.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(433,2022,610,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-122','<div class="desc"> <p>The course focuses on the rise, fall, and re-emergence of Europe as a global political, economic, and cultural force in the contemporary world. We begin with the Enlightenment in the 18th century and the dissemination of European power in the 19th century through capitalism, the industrial revolution, nationalism, and imperialism. We then turn to Europe’s crisis in the 20th century with attention to World War I, Fascism and Nazism, World War II and the Holocaust, and colonial wars of independence, to be followed by European rebirth in the form of reconstruction and European unity. The period 1990s to 2020s welcomed several former states of the USSR into the European Union, and witnessed UNESCO’s restoration of historic sites. Specific topics include the French Revolution, transformations in capitalism, the rise of the nation-state, colonialism and decolonization, liberalism, socialism, communism, changes in family structure and gender relations, and the movements for women''s, workers’, gay and lesbian and other minority rights.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(434,2022,611,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-151','<div class="desc"> <p>This course offers a survey of postcolonial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the 19th and 20th centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the 19th century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race; and the development of export agriculture. The second section introduces themes of the 20th century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources, including scholarly works, films, and primary sources to engage these topics and issues.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(435,2022,613,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-237','<div class="desc"> <p>In early modern times, popular conceptualizations of the intersection of gender and sexuality, ethnicity/race, and rank/class divided women from each other. Activist advocacy for women emerged from a debate on women''s nature to a debate on opportunities for women: to be educated, to write, to speak out, to preach, to express one''s individuality in dress and demeanor, or to work in one''s chosen occupation. For the transformation in political theory from Lockean family representation to Suffragette individual representation in the state, we shall explore the literature on "rights" from Wollstonecraft to United Nations declarations on global Women''s Rights &amp; current revival of American movement for Equal Rights Amendment. We shall experience together a diversity of films as students discuss the intersectionality of race, gender, class, religion, and sexualities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(436,2017,614,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/HIST-History/United-States/300/HIST-306','<div class="desc"> <p>This course will cover the domestic history of the U.S. from 1919 to 1945 and the social cultural and political changes accompanying America''s evolution into a modern society. Themes include: developments in work leisure and consumption; impact of depression and war on the organization of the public and private sectors; persistence of traditional values such as individualism and the success ethos in shaping response to change; and the diversity of America''s people and American experience. Prerequisite: Satisfactory completion of at least one American Studies or History course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(437,2022,615,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-312','<div class="desc"> <p>The circulation of labor goods people and cultures between Africa, Europe and the Americas created an Atlantic World whose history transcends continental and national boundaries. This course examines the relationship between race rights and revolution during the Atlantic Age of Revolution that stretched from roughly the mid-eighteen to mid-nineteenth centuries. In particular we will explore how Revolutions in British North America, France and Haiti influenced the movement to end the slave trade and slavery in the Americas and galvanized slave revolts and other movements for Black liberation and human rights around the Atlantic World. A variety of readings including autobiography social and political history and ethnography will illuminate not only the history of the Atlantic World but new forms of scholarly writing that break the mold of national historical narratives. Themes include: slavery slave revolt the discourse of human rights resistance religion labor and shifting ideologies of difference in particular gender class and race.</p> </div>','One History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(438,2020,617,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/300/hist-354','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(439,2022,618,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-385','<div class="desc"> <p>One of the most consistent “commonsense truths” about the Middle East and North Africa (MENA) region one encounters is that tensions generated by mutually antagonistic sectarian identities produce eruptions of political violence and civil strife. According to this view sectarian (and ethnic) identities are static and consist of an unchanging essential core not only independent of historical, political and economic developments, but indeed even <em>generative</em> of them. For some, the Lebanese Civil War of 1975-1990 seemed to confirm the “sectarian thesis” about the Middle East. Indeed, the war-torn Lebanese capital, Beirut (divided as it was between an eastern “Christian” enclave and a western “Muslim” enclave), became a metonym for sectarian conflict. Using the Lebanese Civil War as a case study, this class will test the “sectarian thesis” of identity formation in the MENA region.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(440,2022,619,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-397','<div class="desc"> <p>Reading tutorials, off-campus internships, and research projects are among options available. Permission of instructor and department chair required.</p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(441,2022,620,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/400/hist-490','<div class="desc"> <p>In this fall semester seminar, students will write a major paper that involves research and analysis of primary and secondary documents. Papers may concentrate on a geographical area or take a topical approach, such as History of Science and Medicine, Women''s History, or Revolutions. In addition, the seminar participants will read works by historians reflecting on their craft. The seminar culminates with individual oral presentations on the thesis research to the Department and campus community. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(442,2017,622,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ITAL-Italian/100/ITAL-152','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(443,2022,623,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/100/japn-102','<div class="desc"> <p>Continuation of JAPN 101. Further development of communication skills, both oral and written. Mastery of the basic conjugated forms of verbs and adjectives in the past-nonpast and positive-negative paradigms in both the polite -masu and plain forms. Students will learn to decode the speaker''s assumptions or attitudes as they are integrated into certain grammatical forms. Introduction to kanji (approximately 50 characters and their multiple readings).</p> </div>','JAPN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(444,2022,624,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/200/japn-202','<div class="desc"> <p>Continuation of JAPN 201. Further development of all four skills. Students will deepen their understanding of the speaker''s attitudes, as well as the spatial and temporal concepts integrated in grammatical forms. Mastery of at least 250 kanji, with their multiple readings, by the end of this level.</p> </div>','JAPN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(445,2022,625,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/300/japn-302','<div class="desc"> <p>Continuation of JAPN 301. While completing the essentials of the structure of Japanese, students will prepare for a higher level of learning with intensive training in reading and writing, in particular. Students are expected to master 500 kanji, and their multiple readings, in total by the end of this course.</p> </div>','JAPN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(446,2022,626,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/300/japn-350','<div class="desc"> <p>In this course, the student will study various tales of the supernatural, including folk tales, myths, and ghost stories created in the ancient, through early modern periods, both aurally (from CD) and in writing. All the kanji in the text are presented with furigana attached so that a substantial quantity of reading may be accomplished time-efficiently. While reading and interpreting the text, the student will attempt creative writing of his/her original stories following the specific narrative styles. The student will also be introduced to the rakugo, humorous story-telling, performed in the traditional Japanese variety theater called yose.</p> </div>','JAPN 302 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(447,2022,627,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/300/japn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(448,2022,628,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/100/kine-197','<div class="desc"> <p>Research in a subdiscipline of kinesiology for students who do not have advanced competence in kinesiology (see KINE 397). Permission of instructor required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(449,2022,629,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-302','<div class="desc"> <p>The application of muscle mechanics and Newtonian mechanics to the documentation and analysis of human movement. Lecture will also focus on the application of static and dynamic problem solving to human performance. Laboratory work will be integrated with the lecture material and will emphasize the use of electromyography and video analysis to document and study human performance. Includes one three-hour laboratory per week.</p> </div>','KINE 300 ','KINE 302L ',NULL);
INSERT INTO course_descriptions VALUES(450,2022,630,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-302l','<div class="desc"> <p>Three hour per week Biomechanics laboratory.</p> </div>',NULL,'KINE 302',NULL);
INSERT INTO course_descriptions VALUES(451,2022,631,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-305','<div class="desc"> <p>The study of human functions and their physiological adaptation to, and specification for, the stress of exercise. Cardiovascular and respiratory responses to exercise; use of calorimetry to study metabolism during exercise; effects of environmental stress on exercise performance; body composition; ergogenic aids and nutritional factors in exercise performance.</p> </div>','KINE 304 and CHEM 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(452,2022,632,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-311','<div class="desc"> <p>This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance, and level of participation of an individual or group.</p> </div>','PSYC 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(453,2022,634,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-397','<div class="desc"> <p>Individual study for students with advanced competence. Extensive study of a specialized topic or broad study of an area not otherwise included in the curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(454,2022,635,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/400/kine-490','<div class="desc"> <p>This seminar course examines a selected area of current topics in Kinesiology. It is the intent of this course to utilize an integrative approach to the advanced study of Kinesiology. Students will develop and write a comprehensive research paper in a subdiscipline of Kinesiology. Open to senior kinesiology majors with permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(455,2022,636,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/400/kine-499','<div class="desc"> <p>Data collection, analysis write-up, and presentation of Honors thesis. May be repeated both semesters of senior year.</p> </div>','Permission of department ',NULL,NULL);
INSERT INTO course_descriptions VALUES(456,2022,639,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/100/latn-102','<div class="desc"> <p>Continuation of LATN 101 and reading and interpretation of an original text.</p> </div>','LATN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(457,2022,640,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(458,2020,641,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/math-mathematics/100/math-104','<div class="desc"> <p>This course is designed to introduce a variety of mathematical topics stemming from the research of women mathematicians, both past and present, from Hypatia to current professors. In discussing the work of these women, we will also discuss the gender issues that are associated with being a female mathematician. Course material will be covered in lecture, research, in-class visitors, and activities. Course work will include research papers, a course project, and problem sets related to the mathematician of discussion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(459,2022,642,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-109','<div class="desc"> <p>Continuation of MATH 108. This course satisfies Calculus 1 prerequisites for subsequent courses. Weekly lab.</p> </div>','MATH 108 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(460,2017,643,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MATH-Mathematics/100/MATH-109A','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(461,2022,644,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-300','<div class="desc"> <p>This course is designed for mathematics majors to satisfy college-wide degree requirements and to demonstrate readiness for advancement in the major. The course includes preparation for and implementation of the Comprehensive Examination as well as completion of the Second Stage Writing Requirement. It emphasizes problem-solving, clear written expression, and oral communication in mathematics. <strong>Restricted to mathematics majors with at least junior standing.</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(462,2022,645,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-312','<div class="desc"> <p>The differential and integral calculus of complex-valued functions of a complex variable, emphasizing geometry and applications. The complex number system, analytic functions and the Cauchy-Riemann equations, elementary functions and conformal mappings, contour integration, Taylor and Laurent series, function theory. Applications to physics, engineering, and real analysis.</p> </div>','MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(463,2022,646,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-322','<div class="desc"> <p>Classical theory of numbers from ancient to modern. Prime numbers and factorization. Divisors, arithmetic functions, linear and quadratic congruences. Diophantine problems including the Fermat conjecture. Factoring methods.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(464,2022,647,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-332','<div class="desc"> <p>Theory and applications of statistical inference. Both Bayesian and classical parametric methods are considered. Point and interval estimation, hypothesis testing. Limit theorems and their use in approximation, maximum likelihood estimation, and the generalized likelihood ratio test. Introduction to linear models, nonparametric methods, and decision theory.</p> </div>','MATH 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(465,2022,648,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-342','<div class="desc"> <p>An introduction to the study of partial differential equations. This course will include the study of Fourier series; the separation of variables methods; and specifically, the wave, heat, and Laplace''s equations, as well as other elementary topics is PDEs. Numerical approximation techniques and applications to specific topics such as traffic flow, dispersive waves, or other areas may be included. Given in alternate years.</p> </div>','MATH 212, MATH 214, and MATH 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(466,2022,649,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(467,2022,650,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/400/math-499','<div class="desc"> <p>Students who have been accepted by the Department to do honors should register for MATH 499, in lieu of MATH 400. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(468,2020,652,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/100/musc-105','<div class="desc"> <p>This course surveys music of African Americans with an emphasis on 20th century classical and vernacular genres. We will examine this musical web in three units: Classical Jazz &amp; Blues and Rock &amp; Contemporary Vernaculars. Featured artists include William Grant, Still Marian Anderson, Margaret Bonds, Duke Ellington, Fats Waller, Big Mama Thornton, Sam Cooke, The Five Blind Boys of Alabama, Motown Stax Records and Atlantic Records, Jimi Hendrix, Sweet Honey in the Rock, and Mos Def. Through extensive listening reading and group dialogue this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(469,2020,653,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/100/musc-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(470,2022,654,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-119','<div class="desc"> <p>This course provides a general introduction to the elements and history of Western art ("classical") music over the last millennium, with a principal focus on Europe. Late in the course we will turn to art music of the Americas, concluding the course with a week on jazz. Students will focus on learning how to listen to music with an emphasis on identifying musical forms, genres, and styles. This focus will serve the larger goal of the course which is to show how understanding music can lead to not only our greater enjoyment of it but also a better understanding of history and culture. Students with no musical experience are especially welcome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(471,2022,657,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-151','<div class="desc"> <p>This course presents the basic principles of musical form and analysis, including simple counterpoint and the diatonic harmonic practice. Students will engage in analytic and compositional projects guided by their musical interests. The music studied will be chosen in collaboration with students and Music Department colleagues with an eye towards diversity and inclusion. Includes study of tonal sight singing, listening, and keyboard skills.</p> </div>','MUSC 101 or passing out of MUSC 101 with a sufficient score on the department''s Music Theory Placement Examination ','MUSC 151A ',NULL);
INSERT INTO course_descriptions VALUES(472,2022,659,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(473,2022,660,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-251','<div class="desc"> <p>This course deepens students'' understanding of diatonic harmonic practice with exposure to techniques for analysis and composition of popular and classical genres. We continue the study of musical form, exploring chromatic extensions of the diatonic practice. Students will engage in analytic and compositional projects. A diverse array of music will be studied chosen in collaboration with students and Music Department colleagues. Includes continued training in tonal sight singing, listening, and keyboard skills: introduction to chromaticism, related key modulations, modes, seventh chords; continued study of chord progressions and rhythmic studies.</p> </div>','MUSC 151 ','MUSC 251A ',NULL);
INSERT INTO course_descriptions VALUES(474,2019,662,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/MUSC-Music/200/MUSC-270','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(475,2022,663,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-295','<div class="desc"> <p>An interdisciplinary course that investigates the music and life of individual composers. Topics vary by semester. Different topics may satisfy different Core Program requirements.</p> <p><strong>Fryderyk Chopin</strong></p> <p>With little formal piano training and sick most of his life, the Polish composer-pianist Fryderyk Chopin (1810-1849) wrote music for the piano that revolutionized piano playing, piano music, and music in general, and has influenced composers and pianists since, including throughout jazz history. In this course, students will study Chopin''s music in context, focusing on his adult years in Paris. To do so, we must study not only piano repertoire, manufacture, pedagogy, and technique, but also Paris--its art, literature, history, music, theater, science, politics, and medicine--and living there in exile. With the only prerequisite being a reading knowledge of music, students from all disciplines are welcome and encouraged to explore Chopin''s music from their disciplinary perspective, especially in their individual semester-long projects. <em>Additional Core Requirement Met: Regional Focus</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(476,2022,666,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(477,2019,683,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-235','<div class="desc"> <p>A critical analysis of contemporary feminist theories and their philosophical roots. Topics for discussion will include: equality respect meaningful work parenting friendship sexual relations abortion rape pornography and prostitution.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(478,2020,684,'http://oxy.smartcatalogiq.com/en/2019-2020/Catalog/Course-Descriptions/PHIL-Philosophy/300/PHIL-305','<div class="desc"> <p>A detailed examination of some central philosophical texts from the 17th and 18th centuries.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(479,2022,685,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-330','<div class="desc"> <p>This course is an examination of the relationship between law and morality. It is organized around three questions: (1) What is law, and what is the relationship between law, morality, and democracy?, (2) Is there a moral obligation to obey the law?, (3) Can we morally enforce the law, that is, is punishment morally justifiable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(480,2022,686,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-350','<div class="desc"> <p>This course surveys results in the metatheory of first order logic including consistency, completeness, decidability, and undecidability.</p> </div>','PHIL 150 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(481,2020,687,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/phil-philosophy/300/phil-397','<div class="desc"> <p>Independent study project in Philosophy. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(482,2022,689,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-104','<div class="desc"> <p>This particular section is for serious trainers who want to concentrate on the development of the physique through a strenuous strength and plyometric program. We will execute specific exercises designed to develop explosive muscle mass and definition.</p> </div>','Prior powerlifting experience is required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(483,2022,691,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-130','<div class="desc"> <p>General fitness activities consisting of strength, agility and stretching exercises. The goal of this class will be to provide opportunities for participants to improve their overall fitness through class participation and increased knowledge to be applied once the class concludes. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(484,2022,692,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-131','<div class="desc"> <p>Spin II is an advanced cycling course for students who have completed Spin I or who can demonstrate proficient knowledge of terms and riding ability. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(485,2022,694,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-110','<div class="desc"> <p>Covers classical mechanics including kinematics and dynamics of particles and rigid bodies conservation laws and examination of specific force laws. <em>Includes one three-hour laboratory per week.</em></p> </div>','Calculus I (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(486,2017,695,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/Introductory-Physics-Courses/PHYS-110L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(487,2022,696,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-125','<div class="desc"> <p>The second of a two-course introduction to physics designed for life science and premedical students. Topics include electrostatics and electromagnetism electric circuits geometrical and physical optics. <em>Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</em></p> </div>','PHYS 110 or PHYS 115; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(488,2017,697,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/Introductory-Physics-Courses/PHYS-125L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(489,2022,698,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(490,2022,699,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-240','<div class="desc"> <p>Introduction to the physics of the twentieth century emphasizing special relativity and elementary quantum mechanics. Includes the breakdown of classical concepts; light quanta and matter waves; Schrödinger equation and solutions in 1 and 3 dimensions; hydrogen atom exclusion principle and the periodic table. Other topics include a selection from atomic nuclear particle and condensed-matter physics. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115, PHYS 117, and PHYS 120; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(491,2017,700,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/The-160-Series/PHYS-240L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(492,2017,701,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/The-160-Series/PHYS-250','<div class="desc"> <p>Connects the microscopic properties of the physical world with its macroscopic properties using classical and quantum statistics. Topics include classical and quantum ideal gasses classical thermodynamics phase transitions and kinetic theory.</p> </div>','PHYS 106 PHYS 110 or PHYS 115 and PHYS 120 ; or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(493,2022,702,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-316','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques including literature search analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(494,2022,703,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-330','<div class="desc"> <p>Electro- and magneto-statics Maxwell''s equations electrodynamics boundary value problems radiation. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 310 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(495,2022,705,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-340','<div class="desc"> <p>The foundations of the theory of quantum mechanics with applications to physical systems. Formal development of the postulates of quantum mechanics representation of states angular momentum spin and perturbation theory. Applications include the harmonic oscillator hydrogen atom and Zeeman effect. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 240 or CHEM 305, and PHYS 310, PHYS 320, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(496,2022,707,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-365','<div class="desc"> <p>Survey of the contemporary status of the quantum physics of subatomic particles and atomic nuclei. Emphasis is given to discussing and examining the fundamental constituents of matter (quarks and leptons) and the fundamental forces of nature (electromagnetism the strong nuclear force and the weak nuclear force). Topics include the classification and relationships among particles properties of nuclei and nuclear interactions (such as fission and fusion) electroweak and quantum chromodynamic interactions and the unification of the fundamental forces of nature. Applications to and insights derived from astrophysics and cosmology will also be included. Specific topics covered will be selected by the instructor.</p> </div>','PHYS 310 and PHYS 320 (may be taken concurrently); or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(497,2022,709,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-397','<div class="desc"> <p>Supervised investigation by properly qualified students. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(498,2022,710,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/400/phys-499','<div class="desc"> <p>Supervised investigation by students admitted by the department to the Honors Program. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(499,2022,712,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/100/pols-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(500,2022,715,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-226','<div class="desc"> <p>This course is an introduction to 20th Century Chinese politics. The course will explore the historical background to the current Chinese situation. Students will also examine the politics of China under Mao and during the subsequent reform period including the role of China in global politics.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(501,2022,720,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-258','<div class="desc"> <p>Is “racism” the appropriate concept to describe our contemporary racial problems? Many scholars have rejected the idea that the persistence of a number of racial ills – like racial inequality, racial discrimination and racial segregation – in the contemporary moment is evidence that racism also persists as a problem in the twenty-first century. “Racism,” these scholars argue, more accurately describes the Jim Crow South and the people in that era who consciously held explicit beliefs about white superiority over all other races. Though acknowledging changes in racial climate and the terrain of acceptable speech with regards to race, other scholars think that unequal racial outcomes, institutional practices and ideological beliefs connect our contemporary racial problems to racial problems that occurred in the 1960s and earlier. This course is an introduction to the scholarship on racism and has as a central aim to get us to judge together whether “racism” is the appropriate concept to describe and provide a frame through which to understand our contemporary problems concerning race. If it is, which accounts of racism are the most compelling to shed light on our current racial circumstances? What about these accounts are particularly pertinent? What can’t the accounts of racism addressed in class explain? If racism is not the right concept to capture our current struggles with race (or all aspects of it), what concepts if any do a better job and why? To facilitate a critical interrogation of the concept racism, this course will cover sociological, historical, social psychological, philosophical and political accounts of racism and related concepts like racial injustice, racial prejudice, race relations, and racial inequality.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(502,2022,721,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-264','<div class="desc"> <p>This course is a "hands-on" experience requiring students to live in New Orleans for most of January working to rebuild and restore the city while studying the politics of disasters disaster recovery federalism local politics grassroots politics activism race and public policy. <em>Permission of instructor required.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(503,2022,722,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(504,2022,725,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(505,2022,726,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/400/pols-495','<div class="desc"> <p>Politics majors are required to take Politics 495 in fulfillment of their senior comprehensive obligation. They therefore should have met or be in the process of meeting all requirements for the major. The Seminar meets in the spring semester but students will be expected to submit proposals for their research papers in the fall semester prior to the actual meeting of the Seminar. The Seminar itself will engage all students in an analytical review of a wide range of materials from various aspects of the discipline and will require that students write a major research paper in one particular sub-discipline of the field. Students qualifying for College Honors will be given an opportunity to write research papers that will be evaluated by the department for honors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(506,2022,731,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-301','<div class="desc"> <p>This course will introduce general concepts of learning in humans and other animals that will be rooted in the principles of learning developed from nonhuman animal research. Explores fundamental concepts phenomena and principles of learning such as reinforcement Pavlovian conditioning and retention/forgetting. Issues addressed are traditional views of learning biological and cognitive constraints the role of nonhuman animal models and the utility of learning theory.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(507,2020,732,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/psyc-psychology/300/psyc-303','<div class="desc"> This seminar course will look at a topic in neuroscience from a multidisciplinary perspective. The course will focus on critical analysis of research studies and methodologies. May be taken more than once for credit as the topics will differ each semester. </div>','COGS 201 , BIO 268 , PSYC 200 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(508,2022,736,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-334','<div class="desc"> <p>Consideration of psychological influences on health and illness including health-and illness-promoting behavior and lifestyles cognitive and emotional processes and social and institutional practices.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 (Student must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(509,2022,738,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-397','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(510,2022,739,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-499','<div class="desc"> <p>Data collection analysis and write-up of Honors thesis. Depending on the structure and timeline of the proposed project a student may take 4 credits in one semester or 2 credits for two semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(511,2022,742,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-150','<div class="desc"> <p>This course will introduce students to some of the major themes, issues, people, places, sights, and sounds of Islam past and present. This course is intended to highlight the manifold expressions of Muslim life through diverse historical, cultural, and geographical contexts. Its two broad aims are: 1) to provide students with basic knowledge of Islamic history, belief, and ritual life; and 2) to equip students with knowledge for critically and actively analyzing discussions of Islam in media and contemporary world events.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(512,2022,743,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(513,2022,746,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-242','<div class="desc"> <p>An exploration of the relationship between religion and environmental ethics. How do various world religions view the natural world and what role do they propose for human beings in nature? What is the history of environmental ethics and how does religion figure in that history? How are religious traditions such as Buddhism Christianity Hinduism Islam Judaism Native American Spirituality and Taoism rethinking their environmental views especially in light of ecofeminism perspectives?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(514,2020,748,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/rels-religious-studies/200/rels-260','<div class="desc"> <p>This course focuses on a variety of interests within Buddhist philosophy including views on time space and causality human understanding and knowledge the ideals of human life morality and ethics as well as overall worldview. The course provides instruction in the practice of reading Buddhist texts in translation from Indian Tibetan Chinese and Japanese originals. Lecture presentations discussions field trips and philosophical research projects are significant components of the course format.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(515,2022,750,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/300/rels-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(516,2022,751,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/400/rels-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(517,2022,752,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/100/rusn-102','<div class="desc"> <p>Continuation of RUSN 101; emphasis on reading and conversation.</p> </div>','RUSN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(518,2022,753,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/200/rusn-202','<div class="desc"> <p>Continuation of RUSN 201 with emphasis on reading skills; readings by Gogol Chukovsky Shukshin and others.</p> </div>','RUSN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(519,2022,754,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(520,2022,755,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/100/soc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(521,2022,756,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-240','<div class="desc"> <p>This course examines the social relations surrounding the production distribution preparation and consumption of food. In doing so we will try to understand how the issues and problems of daily life reflect larger social forces and how our understanding and actions shape the social world. This means that we will treat several major questions facing sociology today including inequalities and identities based on national racial/ethnic class and gender positions; work and family; the environment; globalization; and cultural change. By the end of the course you will be able to critically examine and evaluate the connections between food culture and society.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(522,2022,757,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-305','<div class="desc"> <p>This course introduces quantitative research methods and statistical analysis from a social science perspective. We will address the major components of the research process and will stress the importance of critical thinking in all matters numerical. We will cover measures of central tendency the normal curve probability frequency distributions correlation and regression. We will also talk about statistics and statistical reasoning in the media. By the end of the course you will have mastered basic statistical concepts and techniques and will be able to critically examine and evaluate the (mis)use of these concepts.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(523,2022,758,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-350','<div class="desc"> <p>This course examines why people protest for social change. We will examine the theoretical debates about the determinants of insurgency by focusing on the following models: the collective behavior the resource mobilization the political process as well as the cultural approach. We will also examine the theoretical debates on the extent to which social movements can be credited with political change. Your study of these theories will expose you to several case studies of real social movements in the United States Europe and Latin America. This is however a theory (not a history) course.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(524,2022,759,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-355','<div class="desc"> <p>This course will consider the role that sexuality plays in the American imagination especially the way that sexuality is constructed and serves as a mechanism of social control. In doing so special attention will be paid to the ways in which human sexuality intertwines with axes of power in contemporary America such as race ethnicity gender class and sexual orientation.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(525,2017,760,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/SOC-Sociology/300/SOC-360','<div class="desc"> <p>What are the effects of urbanism on human psychology and civic life? How does urbanization structure social and economic relations as well as signifying identities and cultural meanings? Is there a common "human ecology" of cities in "natural areas" such as the CBD skid row the "Tenderloin" or the "zone-in-transition"? We examine the urban underclass through case studies of the African American ghetto and Spanish Harlem with attention to public policy perspectives on urban poverty. Urban futures are considered through gentrification growth machine boosterism (sports and convention centers) and urban theme parking.</p> </div>','SOC 101 or POLS 101 or permission of Instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(526,2022,761,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-365','<div class="desc"> <p>The course will examine how mass communication systems such as radio television cinema and the Internet are produced and what they signify and represent of the social world and public life. We consider the relationship of the mass media to big business and the structure of capitalism. The ideological influences of the mass media are interrogated through concepts such as "mass culture" and "subculture". We examine how contemporary culture and everyday life are increasingly commodified through the systems and spectacles of consumption capitalism. How has globalization affected consumerism and the social construction of the contemporary self?</p> </div>','SOC 101, SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(527,2022,762,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-375','<div class="desc"> <p>This course examines the political economic and cultural changes that occur as societies shift from the traditional to the modern. Why are some nations mired in debt and dependency while others have become successful "newly-industrializing countries?" We consider leading intergovernmental organizations of the global economy such as the IMF World Bank and WTO. We investigate scenarios in cultural globalization including Americanization hybridization and fundamentalism. We consider intersectional social dynamics that disenfranchise the most powerless including women children indigenous and stateless peoples.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(528,2022,763,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(529,2022,764,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/400/soc-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(530,2022,765,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/100/span-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit.<em> Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(531,2022,766,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/100/span-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(532,2022,767,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/200/span-252','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(533,2022,768,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-304','<div class="desc"> <p>This course surveys Spanish Peninsular literature and culture from the late 18<sup>th</sup>-century through the early 21<sup>st</sup>-century. Students engage with various intellectual and literary movements, including Neoclassicism, Romanticism, Naturalism, Surrealism, and Postmodernism. Special attention is given to the development of democratic traditions in Spain, the clash of political ideologies during the Second Spanish Republic and the Spanish Civil War, the trauma and legacy of dictatorship, and the changes in Spanish society resulting from the assertion of the distinct languages and cultures of the Iberian Peninsula and from globalization and immigration. Authors read include Leandro Fernández de Moratín, Ángel de Saavedra, Emilia Pardo Bazán, Jacinto Benavente, Ramón Sender, Antonio Buero Vallejo, and Juan José Millás. Significant examples of modern Spanish art, architecture, and music are also studied.</p> </div>','SPAN 202, SPAN 211, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(534,2022,769,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-340','<div class="desc"> <p>This course serves as a general introduction to the study of the Spanish sound system. The objectives of this course include strengthening students'' Spanish pronunciation in the direction of a more native-like normative pronunciation and introducing them to phonetics and phonology. Students will be introduced to theoretical means of analyzing the sound system of a language. They will also examine contrasts between American English and Spanish and apply these concepts in exercises of both written transcription and oral production as well as with a linguistic analysis of spoken Spanish. Finally students will also be acquainted with phonological differences among the dialects of the Spanish language.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(535,2022,770,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-377','<div class="desc"> <p>Although magical realism remains a difficult term to define there is some consensus that Miguel Angel Asturias (from Guatemala) Alejo Carpentier (Cuba) Gabriel García Márquez (Colombia) and Isabel Allende (from Chile) are the most renowned practitioners of this literary genre. Pre-Columbian mythology peasant folklore popular Catholicism European surrealism the genealogical novel and an ethical pressure on Latin American writers to represent their national cultures all play a part in the development of magical realism in Latin America. The course explores why <em>Men of Maize</em> (Asturias) <em>The Kingdom of This World</em> (Carpentier) <em>One Hundred Years of Solitude</em> (García Márquez) and <em>The House of the Spirits</em> (Allende) are considered paradigmatic works of magical realism. Throughout the course students will be asked to reflect upon the contested meanings and history of the term "magical realism" as the term is applied to different works of Latin American fiction.</p> </div>','One 300-level Spanish course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(536,2022,771,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-382','<div class="desc"> <p>This course analyzes the narrative development of the contemporary Mexican novel from the Mexican Revolution to the present. Principal novelists studied in this seminar are Mariano Azuela Juan Rulfo Carlos Fuentes Gustavo Sainz Elena Poniatowska Angeles Mastretta and Laura Esquivel. This course combines textual analysis with the application of contemporary literary theory.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(537,2022,772,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-397','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(538,2022,773,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/400/span-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(539,2022,774,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-131','<div class="desc"> <p>In this course students learn the fundamentals of jazz and tap dance with an emphasis on body alignment strength flexibility rhythm and coordination. During the semester we experiment with lyrical and contemporary jazz combinations as well as tap variations designed to develop musicality self-expression and performance skills. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(540,2022,775,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-175','<div class="desc"> <p>This introductory design course grounds students in aesthetics as they relate to design for performance and the role of design in the collaborative process of production. Those students interested in becoming designers receive a foundational experience for specializations offered in subsequent classes. Students explore elements of design and the principles of composition as they can apply to theater and film. Over the semester students come to understand and acquire the skills to develop visual expressions of the meaning of play and film scripts. Through individual and group design projects, students learn to incorporate script analysis, design research, and visual presentation techniques. This course is intended for first and second year students. Juniors and seniors may enroll with the permission of the instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(541,2022,776,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-197','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(542,2022,777,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-212','<div class="desc"> <p>In this course student actors will continue to develop audition techniques introduced in <em>Introduction to Performance</em> and <em>Acting 1</em> applying them to the standard "general audition" format. In addition our students learn about the audition and casting process in professional theater through a guest speaker series of casting directors and professional film and stage actors. Not open to frosh. <em>Graded on a Credit/No Credit basis only. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(543,2022,778,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-215','<div class="desc"> <p>Working with selected scripts from the best of recent and contemporary screenplays our students develop techniques for working in front of a camera as a specific application of the work of both <em>Acting 1</em> and <em>Acting 2</em>. <em>There is a materials fee of $60 for this course. THEA 310 is strongly recommended as preparation.</em></p> </div>','THEA 210 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(544,2022,779,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-225','<div class="desc"> <p>In this course we introduce students to a variety of scenic techniques and materials employed in theatrical scene painting with aesthetic theory and period styles serving as the foundation of the work. Special materials are purchased for the students of the course. <em>There is a materials fee of $65 for this course.</em></p> </div>','THEA 120, THEA 175, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(545,2017,781,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/THEA-Theater/200/THEA-231','<div class="desc"> <p>Students with basic experience in jazz and tap dancing learn intermediate and advanced techniques in this course. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','Two semesters of THEA 131 or permission of the instructor',NULL,NULL);
INSERT INTO course_descriptions VALUES(546,2022,782,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-237','<div class="desc"> <p>Building upon the work from <em>Beginning Choreography</em> students develop more sophisticated choreographic strategies language and techniques with an emphasis on group choreography including site-specific work and studio performances. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','THEA 137 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(547,2022,783,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-261','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take THEA 260 and THEA 261 in either order. In four intensive sessions students learn five workshops geared to the fifth grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited. Graded on a CR/NC basis only.</p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(548,2022,784,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-316','<div class="desc"> <p>In this culmination of the Theater Department''s acting sequence our students explore through practice the demands Shakespeare''s scripts make upon actors. During the semester students in the class work with five to six of Shakespeare''s scripts from various genres in order to develop facility with Shakespeare''s verse and prose in performance.</p> </div>','THEA 202 and THEA 310; or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(549,2022,785,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-330','<div class="desc"> <p>Students in this course analyze the various requirements for producing live performance events. In developing solutions to the many difficulties presented by live events we examine in particular the artistic, legal and financial responsibilities of the producer. Through projects, case studies, and research, our students look at the creative and practical aspects of live presentations as they come to understand the myriad considerations required to successfully produce live performances for theater music and other cultural events. Not open to first year students.</p> </div>','THEA 120 and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(550,2022,787,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-397','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(551,2022,788,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/400/thea-410','<div class="desc"> <p>We introduce students to the art of directing. Our students explore the directing processes of script analysis, casting, working with actors, manipulation of space, use of sound and images, developing designs and mounting productions for theater. During the semester students in the class stage two performance sequences: one in a classroom format the other produced on the Keck stage. This course may be repeated for credit. Students must be at least of sophomore standing.</p> </div>','THEA 101 , THEA 120 , and THEA 210 . ',NULL,NULL);
INSERT INTO course_descriptions VALUES(552,2022,789,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-247','<div class="desc"> <p>This class is a collaboration between the Urban and Environmental Policy Institute (UEPI) and the FEAST (Food, Education, and Sustainability Team) student service to enhance student capacity to lead and engage with food and gardening projects both on campus and in the community. Through the implementation of projects in campus garden spaces, participation in community service learning projects, and field trips to innovative food programs in Los Angeles, students will gain hands-on understanding of food issues and will complete the course with the ability to help in the design, creation, and maintenance of a garden-based food or sustainability project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(553,2022,790,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty, housing, transportation, crime and violence, pollution, racial segregation and gentrification. It also examines how power is exercised by different groups including business, citizens'' groups, community organizations, unions, the media, mayors and other government officials. The course will also examine the role of city planning and planners, conflict and cooperation between cities and suburbs, problems of urban sprawl, loss of open space, water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe, Canada, and the developing world. Public policies to solve urban problems.</p> </div>','UEP 101, POLS 101, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(554,2022,791,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-303','<div class="desc"> <p>This course examines sustainable development from a social economic and environmental perspective. The course focuses on development strategies and approaches led by community-based labor and nonprofit organizations in a context of traditional public and private-sector economic development approaches. Through lectures field trips discussion guest speakers and class exercises students will examine the history and evolution of community and economic development strategies in urban neighborhoods and communities and link these approaches to the field of sustainable development. The course focuses on the historic and contemporary debates and issues in sustainable development and delves into the challenges and opportunities of sustainable development in Los Angeles by drawing on case examples from other urban regions across the country. Through the course students will: 1) understand the historical theoretical and policy context of community development; 2) understand community and economic decline and development processes; 3) examine the key strategies of community development and related field of community economic development; 4) explore the growing intersection of community development and sustainable development including the greening of jobs buildings and urban design.</p> </div>','UEP 101, UEP 106, POLS 106, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(555,2022,792,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-306','<div class="desc"> <p>This community based learning course explores a range food systems issues from a food justice lens. The course examines how our food system has been restructured over the last century to benefit large-scale agriculture interests, creating a global food system that emphasizes convenience and fast-food solutions for consumers, often to the detriment of low-income people and communities of color. Through in-depth class discussions, on-site field trips, and in-class speakers, the class will delve into the environmental, economic, health, cultural, and social impacts of to how food is grown, processed, manufactured, distributed, sold, and consumed in the U.S. The community based learning component of this course will involve project work with UEPI’s food programs as well as other Los Angeles-based nonprofit partners and food policy experts. Please note, the first half of the semester will be based in the classroom (T/Th 1:30-2:55pm). During the second half of the semester, class will be held only one time per week (from 11:45am-2:55pm) to accommodate field trips.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(556,2022,793,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-397','<div class="desc"> <p>Tutorial and Internship for junior or senior majors in Urban and Environmental Policy and other related disciplines under arrangement with faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(557,2022,794,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-411','<div class="desc"> <p>Seminar to organize and complete a senior project demonstrating competence in applied public policy. The form and format of each student''s project will vary. All students will make a presentation of their project and will critique each other''s project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(558,2020,797,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/100/amst-111','<div class="desc"> <p>(De)familiarizing Identity will acquaint students with a selected set of historical, philosophical, and scientific perspectives on how to think about the meaning of selves, and how identity is acquired. We explore individual and collective conceptions of self, as well as notions about what constitutes societies, nations, and peoples. We also look at related concepts of race, religion, gender, sexuality, and culture, examining how they influence each other and how they are connected to citizenship. We consider what identity meant prior to the European nation-state in ancient Greece and Rome, during U.S. imperial projects of the 19th and early 20th centuries in the Pacific Basin, and what it currently means in the era of globalization and transnationalism. In doing so, we explore the ways in which – or if – individual and/or collective identity entangles within culture. We ask: How do identities develop and change? What assumptions do people make about themselves and others regarding identity? How do identities influence how people approach and interact with the world? We will engage these questions through scholarly texts and oral traditions, works of art, film and media, and discussion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(559,2022,806,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-280','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(560,2022,807,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/300/arab-301','<div class="desc"> An advanced Arabic course intended for students who have taken Intermediate II. It introduces the language of the newspapers, magazines, and internet news sites. Students will gain access to different sources from the Arab world. </div>','ARAB 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(561,2017,808,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-270','<div class="desc"> <p>An investigation of the art and architecture of ancient Greece from the Bronze Age (c. 3000 BCE) to the colonization of Greek culture by Rome (c. 100 BCE). Sculpture metalwork mural painting vase painting and architecture will be considered with particular interest in how these forms are reflective of the fundamental political spiritual and philosophical developments during this era - as well as how these artistic forms serve as the foundation elements for European art history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(562,2017,809,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-274','<div class="desc"> <p>Roman art and architecture develop in response to increasingly complex issues of individual identity cosmopolitanism personal and state propaganda and the social and political pressures inspired by managing large and varied population concentrations. Roman visual culture addresses these challenges by adapting to new ideas and subject matter while at the same time maintaining traditional notions of personality organization and imperial supremacy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(563,2017,810,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-291','<div class="desc"> <p>A 2-unit seminar course to be taught by visiting curators critics art historians or artists focused on some aspect of the arts in Los Angeles. Topics will change in light of availability of top quality visiting faculty and will engage directly with current exhibitions events and issues relevant to the artistic culture of Los Angeles. </p> <p><strong>History of Green Architecture: </strong></p> <p>This course will pursue and ultimately aim to reconcile two separate questions about sustainability and architecture. To begin with what makes a particular building -- house office block or skyscraper -- green? Second and more fundamentally how has our understanding of the relationship between architecture and nature shifted over the centuries? The course will begin by looking at a range of depictions of that relationship in art architecture literature and philosophy before moving on to examine architecture''s role in the nascent environmental movement of the 1960s and 1970s. It will consider the rise and increasing codification of green architecture in the last 15 years in the U.S. and Europe isolating certain buildings as case studies and assessing in some depth recent debates over the American green-design rating system known as LEED. Finally we''ll ask what green architects might learn from the ways that other sustainability movements -- in transportation product design clean-energy and food policy -- have matured over the years. Students will visit a number of built examples of green architecture in and around Los Angeles. No prior study of architectural history is required. </p> <p><strong>Art and Crime: Plunder Fakes and Forensics: </strong></p> <p>This course explores the increasing use of forensic science to evaluate issues of authentication sourcing and repatriation of works of art. From the uncovering of forgeries and looted antiquities to the return of art stolen during WWII science and history law and ethics intersect in increasingly complex and interesting ways in this interdisciplinary art history course. Art Crime has received increasing attention over the past decade especially in Southern California. Los Angeles Museums (The Getty Bowers and Norton Simon) Museums dealers and collectors all face increased scrutiny as an ongoing series of scandals highlight weak points in our authentication systems. Forensic science and technical art history have helped address these important issues in art history and material culture. This course encompasses issues such as how are forgers unmasked how is plunder sourced and when should it be returned? These questions often lead to larger discussions on the limits of expertise and science the nature of authenticity what is valuable and why and who owns the past-that bring together art and science material culture and sustainability.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(564,2022,811,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-216','<div class="desc"> <p>An introduction to the process of lithography, a technique of printing from a drawn image on limestone. Course emphasis will be on the drawing and how the medium allows for evolving the visual image over time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(565,2020,812,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-320','<div class="desc"> <p>This course invites students with art experience from across the College, including visual arts, music theater, creative writing, etc., to pursue self-directed interdisciplinary art projects. Video installation, sound art, performance art, site-specific art, and collaborative projects will be the focus of the class. The class meets once a week for seminars and critical feedback, along with out of class visits to contemporary art and performance venues.</p> </div>','Any two Art History, Studio Art, Media Arts &amp; Culture, Music, Theater, or Creative Writing courses and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(566,2022,813,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-240','<div class="desc"> <p>Physical and metabolic activities of cells and tissues, properties of the cellular environment, regulatory and homeostatic functions of organ systems. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 plus any other 100-level Biology course (except BIO 103) or permission of instructor (BIO 130 may be taken concurrently) ','BIO 240L ',NULL);
INSERT INTO course_descriptions VALUES(567,2017,814,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-240L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(568,2022,815,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-333','<div class="desc"> <p>Emphasis on cell biology and physiology of neurons. Development and plasticity of the nervous system in invertebrates and vertebrates. Overview of selected central nervous system structures and their function and the cellular and molecular basis of selected nervous system diseases and disorders. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130; and BIO 240 or BIO 226 ','BIO 333L',NULL);
INSERT INTO course_descriptions VALUES(569,2022,816,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-333l','<div class="desc"> <p>Laboratory techniques in neurobiology. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 333 ',NULL);
INSERT INTO course_descriptions VALUES(570,2022,817,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/200/chin-274','<div class="desc"> <p>This seminar course will explore ghosts and other disembodied beings in the Chinese literary tradition, from the earliest historical documents, philosophical texts, and Buddhist tales, to the Six Dynasties zhiguai records of the strange, the Tang chuanqi tales of the marvelous, and Ming dynasty vernacular fiction. We will focus on recurring motifs and archetypes which weave the supernatural into love stories, especially as manifested in two Qing dynasty masterpieces: Pu Songling''s <em>Strange Tales</em> and Cao Xueqin''s <em>The Story of the Stone</em>. Modern stories and film will also be examined for their adaptations of traditional motifs and archetypes. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(571,2022,819,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-295','<div class="desc"> <p>This course explores a topic within the field of cognitive science. Topics vary by semester; past topics have included Intelligent Agents and Concepts. See the Department Chair for further information.</p> </div>','Any COGS course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(572,2022,820,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320l','<div class="desc"> <p>Laboratory sessions will allow students to get hands-on experience, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>',NULL,'COGS 320',NULL);
INSERT INTO course_descriptions VALUES(573,2022,821,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-395','<div class="desc"> <p>Directed research with a faculty member.</p> </div>','COGS 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(574,2022,822,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-311','<div class="desc"> <p>Comparative data structures and analysis of algorithms. Abstract data types. "Big O" notation, run time and memory allocation considerations, introduction to computational complexity. Selected topics and applications from graph theory, linear algebra, numerical analysis, and data compression. <em>Weekly lab.</em></p> </div>','COMP 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(575,2022,823,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-105','<div class="desc"> <p>This course will locate the topics of immigration and education within historical, legislative, and cultural debates on what it means to be an American and who has the right to an education. Students will explore and debate precedent-setting Supreme Court cases, such as Mendez v. Westminster, which challenged the segregation of Mexican children into separate schools, and Lau v. Nichols, which fought hard for non-English speaking students to have linguistic access to the public-school curricula. In addition, students will research the historical antecedents to the recent anti-immigrant movements in California, Arizona, and Colorado, which target the use of languages other than English in school settings, and have all but abolished bilingual public schools. Against this historical and legislative backdrop, students will examine ethnographic research detailing the persistent challenges that immigrant children face in schooling, including migrant children, and the ways in which they, their parents, and communities experience those challenges.</p> <p>This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CTSJ 105, DWA 282, and SOC 105.</p> </div>',NULL,'DWA 282, and SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(576,2022,824,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-140','<div class="desc"> <p>This course introduces students to critical theories concerning human sexuality. We read feminist, Marxist, psychoanalytic, structuralist, and poststructuralist theories of sexuality, and discuss what makes each of these theories "critical." Topics include: the political economy of marriage, the relationship between sexuality and procreation, uses of the erotic, homosociality, and the incitement to discourse. The authors we read include Engels, Freud, de Beauvoir, Levi-Strauss, Gayle Rubin, Andrea Dworkin, Foucault, and Judith Butler.</p> <h1 class="a-size-large a-spacing-none" id="title"></h1> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(577,2019,825,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/CTSJ-Critical-TheorySocial-Justice/200/CTSJ-286','<div class="desc"> <p>This course seeks to engage the emergent body of scholarship designated to deconstruct whiteness. It will examine the construction of whiteness in the historic legal and economic contexts which have allowed it to function as an enabling condition for privilege and race-based prejudice. Particular attention will be paid to the role of religion and psychology in the construction of whiteness. Texts will include <em>Race Traitor Critical White Studies The Invention of the White Race The Abolition of Whiteness White Trash and Even the Rat was White. Emphasis topic: Critical Race Theory.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(578,2022,827,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-221','<div class="desc"> <p>Against the backdrop of 840 million persons worldwide suffering from malnourishment, and nearly 1.3 billion people living on less than a dollar per day, this course surveys the fields of international development, wealth creation, and global welfare, from a historical, global, and comparative perspective. The course will introduce students to the field''s academic contours, building from the historic role of economics in pioneering and undergirding the field, to a broad understanding of the now interdisciplinary field that has emerged. The multi-disciplinary and interdisciplinary perspective of this introductory survey course is in keeping with an emerging global consensus that measures of poverty go beyond income and consumption, and that poverty reduction requires bridging disciplines (Economics, Political Science, History, Anthropology, Geography) and methods (quantitative and qualitative, observational and participatory). The course will be divided into two parts. During the first part of the course, students will be introduced to the main theoretical ideas on social, economic, and political development that have informed the field''s evolution. This will familiarize students with fundamental thinking on development, as well as the frontiers of research. The second part of the course will explore some of the current debates about development. Students will analyze such debates in a rigorously multi-dimensional and interdisciplinary manner.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(579,2022,828,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-250','<div class="desc"> <p>This course is an introduction to International Security and Strategic Studies. This field is, fundamentally, about both the use of force by, and violent conflict among, states and non-state actors. The course will be guided by general theoretical questions regarding security: how does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: how do states and non-state actors use force to persuade their enemies to take (coercion), or refrain from taking (deterrence), a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure and the intensity, duration, and consequences of military action? We will have a particular focus on emerging transnational security issues, intra-state security, and the relationship between security development and state failure. Pursuing answers to these questions will require an approach that integrates theory, history, and current events. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(580,2022,829,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-280','<div class="desc"> <p>This course explores the various facets of the globalization process and the politics of development. The first part of the course examines globalization, its causes and wide-ranging consequences, and its implications for U.S. domestic and foreign policy as well as for global governance. Has globalization benefited East Asia, Africa, and Latin America? What have been the differing impacts on those regions? Questions that will be addressed include: what are<br/> conceptual perspectives on globalization? What are the economic, cultural, and political dimensions of globalization? What are policy responses to the challenges globalization presents? The second part of the course examines the politics of various approaches to development and poverty reduction. This will include exploring how globalization is related to development, understanding current debates over foreign aid, and evaluating new and innovative strategies aimed at poverty alleviation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(581,2022,830,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-282','<div class="desc"> <p>A critical examination of greater Los Angeles and it''s economic, political, social, and cultural ties to the world economy and other countries--all the ways in which Los Angeles is an integral part of the post-Cold War global society. How does this globalization affect the life of Los Angeles and in what ways does Los Angeles contribute to globalization? What are the positive and negative impacts and the implications for United States foreign, economic, and social policies of Los Angeles as a Global City? </p> <p>This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CTSJ 105 and SOC 105.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(582,2022,831,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-299','<div class="desc"> <p>The goal of this course is to provide students with some of the tools to embark on systematic inquiry in Political Science. It will introduce students to qualitative methods in Political Science; ethical issues in qualitative research, proposal writing, and interviewing techniques; and finally, the essential components of a research paper (a proper research question, thesis, literature review, and case selection). Guidance through the Institutional Review Board process will be provided. This course is geared towards students preparing grant applications, preparing to conduct research abroad, and/or preparing for their Senior Comprehensive thesis since they will be expected to apply the methods they learn to their own research topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(583,2022,832,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-309','<div class="desc"> <p><strong></strong></p> <p> The Austrian School of Economics, so-named because of the national origin of its founders, is an alternative approach to Economics that emphasizes methodological individualism and subjectivism. The Austrian School of Economics traces its roots back to the works of the Spanish Scholastics of the 16th century and stresses the importance of the individual, private property, limited government, and the organizing power of the free-market. Students will read from authors such as Menger, Mises, Hayek, Kirzner, Rothbard, and Hoppe, and evaluate various properties of a state-planned economy versus a decentralized free market economy.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(584,2022,833,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-325','<div class="desc"> <p>The goal of Labor Economics is to enable you to use economic analysis and reasoning to understand wage and employment determination in U.S. labor markets. This course will expose you to current theoretical and empirical debates within the discipline. We will cover such topics as: labor force participation, labor demand, unemployment, labor mobility, wage structure, labor unions, human capital investments (education and training), internal labor markets, and labor market discrimination. Relevant public policy issues such as the minimum wage, living wage ordinances, compensating wage differentials, immigration policy, affirmative action, income inequality, and welfare programs will also be addressed in this course.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(585,2022,834,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-340','<div class="desc"> <p>This course will provide an introduction to the relatively new field of Behavioral Economics. Standard models of economic theory provide a useful, but not always realistic, way to characterize how individuals make decisions. In this course, we will investigate the evidence showing how people may behave in ways that are not predicted by this standard theory. Individuals may exhibit nonstandard preferences, nonstandard beliefs, or nonstandard decision-making. We will look at each of these in turn, with applications that may include saving, finance, labor supply, gift-giving, voting, and addiction. The methodology of the course will not itself deviate from the standard way of doing economics; we will state clear assumptions, build models, determine their logical conclusions, and think about how to empirically test both the assumptions and implications of such models.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(586,2022,835,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/100/educ-141','<div class="desc"> <p>Students work one-one with middle school students for extensive explorations in writing. Occidental students will collaborate and coach writing activities which will include narrative, expository, and analytical prompts. This course focuses on authentic, engaging writing and integrates the arts, technology, and critical literacy. Students work closely with the Critical Making Studio. This course is designed to deepen the critical and creative abilities of both groups of students while connecting written explorations to the California Common Core Standards. This course takes place on campus in the Academic Commons. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(587,2022,842,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-301','<div class="desc"> <p>An introduction to late 20th-century Francophone literary works (short stories, a novel, poetry) and films, from the Levant (Lebanon, Syria) and North Africa (Egypt, Tunisia, Algeria, and Morocco). The course underlines the diversity of this part of the world, the various ways in which French is used, and its relation to the native tongue-Arabic. The Arab Spring and questions of cultural/national identity are also examined. Among authors studied are Tahar Ben Jelloun (Morocco) and Lamia Ziadé.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(588,2022,843,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-350','<div class="desc"> <p>An introduction to the theory and practice of translation from English to French ("thème"), and French to English ("version"), as both a craft and an art, with its codes and principles. Although emphasis is placed on practice, the course examines important theoretical questions, such as translation as both a product and as a process. With some attention to the difference between "literal" and "free" translation, the course explores the lexical and semantic strategies that translators employ. The course begins with the smallest "unit of translation," and progresses to consider a wide variety of texts: fiction; poetry (song lyrics); advertisements, televisual and filmic. Students may choose to translate a business, technical, legal, medical, or literary text as part of their final project.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(589,2022,844,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-245','<div class="desc"> <p>An introduction to Earth''s climate system and the geological record of its change. Topics covered include: Earth''s radiative balance and the role of greenhouse gases, poleward transport of heat by the atmosphere and ocean, climate change on the plate tectonic timescale, the Cenozoic cooling, astronomical control of Pleistocene glacial cycles, rapid millennial-scale climate change, and the future of Earth''s climate. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 or GEO 106, or permission of instructor ','GEO 245L ',NULL);
INSERT INTO course_descriptions VALUES(590,2017,845,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/GEO-Geology/200/GEO-245L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(591,2020,846,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/geo-geology/300/geo-305','<div class="desc"> <p>The fundamentals of rock formation are explored through study of common rock-forming minerals and major rock types. Understanding of these processes is based on the physical, optical, chemical, and textural properties of minerals and rocks. The course includes a field trip to investigate rocks and minerals in some of California''s most interesting natural settings. <em>One three-hour laboratory per week and field trip.</em></p> </div>','GEO 105 or GEO 106 ','GEO 305L ',NULL);
INSERT INTO course_descriptions VALUES(592,2020,847,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/geo-geology/300/geo-305l','<div class="desc"> <p>Three-hour per week laboratory.</p> </div>',NULL,'GEO 305',NULL);
INSERT INTO course_descriptions VALUES(593,2022,848,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-182','<div class="desc"> <p>This is a survey course in which we will explore the cultural and social historical experience of the Middle East from the 19th century to the present. Our goal in this class is to develop a sense of how people in the region view themselves and their history. We consider the currents of social change wrought by political and economic transformation, focusing particularly on the rise of new social movements and cultural currents. Here we will focus on issues of gender, religion, new social categories, and notions of personhood, and new forms of collective and individual identity. Finally, we look at the emergence of modern nation-states and their attendant juridical notions of citizenship and minority status.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(594,2022,849,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-283','<div class="desc"> <p>This course examines the role of peasants and tribal formations in the process of nation and state building in the modern Middle East. In addition to looking at some of the empirical and theoretical problems inherent in defining and writing about "peasants" and "tribes," we will also consider how nationalism complicates these issues even more. We will investigate the ways that rural populations were incorporated into, or excluded from, the processes of state-formation. Finally, we will look at how representations of peasant/tribe, in ideologies of state-building and nationalism, shaped social and political relations within some of the region''s nation-states. While we will discuss the region as a whole, we will focus most of our attention on two empirical cases: Iraq and Egypt.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(595,2017,850,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/HIST-History/United-States/300/HIST-307','<div class="desc"> <p>This course concentrates on the 1950s and encourages students to move beyond the stereotypes of <em>Happy Days</em>. Using movies music television and written texts the class will explore the tensions of the Fifties the era of overt repression and covert rebellion stretching from the late 1940s to the early 1960s. Themes include the Cold War and McCarthyism early rock ''n roll the Beats the Bomb civil rights protests HUAC the "feminine mystique" sexuality and cultural icons such as Marilyn Monroe and James Dean.</p> </div>','Satisfactory completion of at least one American Studies or History course.',NULL,NULL);
INSERT INTO course_descriptions VALUES(596,2022,851,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-330','<div class="desc"> <p>The Storming of the Bastille, the Great Fear, the Women''s March, War with the rest of Europe, the September Massacres, the King''s trial and execution, Robespierre''s Republic of Virtue, the Reign of Terror, the Thermidorian reaction, the rise and fall of Napoleon, the impact of the rhetoric of revolution overseas, the end of slavery in France''s colonies, the transformation of French colonial Saint Domingue from slave colony into the new nation of Haiti, and the meaning of "liberty, equality, fraternity" for our own time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(597,2022,852,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing especially on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization, art forms, social structure, and religion in the colonial and modern periods and considers native responses to contemporary issues such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(598,2022,854,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/200/japn-271','<div class="desc"> <p>This course examines the art of storytelling via selected works of prose, fiction, and film, which were originally written/produced in the Japanese language in the early modern, through contemporary, periods. Through close reading of texts and visual images, the student will identify and analyze specific issues that are relevant to the critical messages and the development of the narrative. The course is given in English but those whose language proficiency permits may choose to read the texts in the original Japanese. Offered in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(599,2022,855,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/300/japn-340','<div class="desc"> <p>This course focuses on current trends in Japanese language and society. By reading newspaper articles; listening to TV/radio news; and intensively studying vocabulary related to world affairs, social issues, and government, the student will be trained to grasp the critical information conveyed by these sources and to report accurately various facts, events, and thoughts orally and in writing. The student will also be introduced to the common practice of unorthodox usage of the language in advertisement, copy, and comic strips to develop, further, their comprehensive language skills. Given in alternate years.</p> </div>','JAPN 302 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(600,2022,856,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/200/latn-201','<div class="desc"> <p>Advanced readings in Latin literature and/or philology in coordination with a classics course in ECLS (or another department affiliated with the classics program).</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(601,2022,857,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ling-linguistics/300/ling-301','<div class="desc"> <p>This course is designed as a solid introduction to and overview of the field of linguistics. Students will explore a number of topics that are at the core of linguistics. We begin with a theoretical background in subfields such as syntax, morphology, phonology, and phonetics. Then we move to broader issues such as sociolinguistics, language acquisition, psycho/neurolinguistics, and historical linguistics. Not normally open to first-year students.</p> </div>','One year of a modern language or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(602,2022,858,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-195','<div class="desc"> <p>Intensive study in an area of mathematics of the student''s choosing under the direct supervision of a member of the faculty.</p> </div>','Permission of the supervising instructor. May be repeated once for credit ',NULL,NULL);
INSERT INTO course_descriptions VALUES(603,2022,859,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-362','<div class="desc"> <p>General topology studies those properties (such as connectedness and compactness) which are preserved by continuous mappings. A disk and a solid square are topologically equivalent; so are a doughnut and a coffee cup; but a disk is different from a doughnut. This course enables you to construct your own proofs and counterexamples while getting to know the basic concepts behind modern mathematics.</p> </div>','MATH 210 and MATH 212 or MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(604,2022,862,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-262','<div class="desc"> <p class="sc-BodyText">This interdisciplinary course will survey the music of the long 19th century from the French Revolution to the beginning of World War I. We will commence by considering Beethoven''s response to Napoleon the Eroica Symphony in the context of post-Revolution European geo-politics and end with the musical cultures of turn-of-the-century Vienna Paris and New York City. Topics to be explored include the following: the Industrial Revolution and emergent technologies (including photography); landscape painting and poetry; nationalism (including "folk" music); aesthetics and philosophy; science and medicine; the expansion of tonal and formal musical language and the essaying of new musical forms; the public concert and music for home performance; and Richard Wagner and artistic responses to his music and writings.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(605,2022,863,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-273','<div class="desc"> <p>This course provides an introduction to choral conducting technique and the study of choral music. Using music drawn from across the choral repertoire, students will learn to develop their musical interpretation through score study and analysis and then translate this interpretation into a clear and expressive gestural vocabulary. The course will include the following areas: conducting gestures, rehearsal preparation and technique, score study &amp; performance practice, and basics of singing technique. Culminates in conducting the Occidental Glee Club in concert.</p> </div>','MUSC 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(606,2022,864,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-210','<div class="desc"> <p>We will address some of the fundamental issues in epistemology and metaphysics while reading selections from the works of some important philosophers from the modern period (1600-1800). Among the issues addressed will be the existence of the external world, the relation between the mental and the physical, and the foundation of our knowledge of the future. Philosophers covered will include Descartes, Leibniz, Locke, Berkeley, Hume, and Kant.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(607,2019,865,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-370','<div class="desc"> <p>We will examine a number of recently proposed accounts of meaning truth and reference. Issues that will come up will be whether there could be a private language what the role of mental content is how we should understand metaphor and whether truth is a redundant notion. Philosophers covered include Frege Russell Tarski Quine Putnam Kripke and Searle. <em>Given in alternate years</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(608,2022,866,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-135','<div class="desc"> <p>This intensive course focuses on sport-specific training injury prevention strength-building conditioning and fitness programming. The class is designed for the advanced athlete and includes strength training plyometrics and aerobic conditioning with specific application to athletic performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(609,2022,867,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-161','<div class="desc"> <p>Exploration of physical laws and processes through simple and geeky-cool devices and demonstrations many of which students will build themselves and keep. The toys will illuminate topics from across physics including classical mechanics thermodynamics electricity and magnetism. Course Fee: $125.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(610,2022,868,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-266','<div class="desc"> <p>An introduction to the theory of relativity. The first half of the course focusing on special relativity includes discussions of the relationship between space and time; mass and energy; and cause and effect. The second half of the course presents the fundamentals of the general theory of relativity with an emphasis on the physics of black holes.</p> </div>','PHYS 110 or PHYS 115; and PHYS 120 or PHYS 125; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(611,2022,871,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems make decisions draw inferences attend to their environment communicate remember and learn. Much of the material is applied to real-life settings.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(612,2022,872,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-385','<div class="desc"> <p style="margin-left:0in; margin-right:0in">The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101, SOC 101, HIST 102, AMST 101, or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(613,2022,873,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-428','<div class="desc"> <p>The study of social cognitive physical and psychological development during adolescence and emerging adulthood. Topics include sexual development and the social consequences of being sexually active the function of family support the increasingly important role of peer relationships drug abuse and antisocial behavior and school adjustment.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(614,2022,874,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-498','<div class="desc"> <p>This course involves applied psychological work in a variety of community settings. Students will assist professionals in mental health educational social services business or not-for-profit settings. <em>Instructor permission is required.</em></p> <p>Prerequisites: PSYC 200 and either PSYC 201 or three courses from the Fundamental Domains. For Practicum in Clinical Psychology one course must be PSYC 321 or PSYC 330. For Practicum in Organizational Psychology one course must be PSYC 340. A minimum grade of C- in all prerequisite course and a B average in Psychology courses are required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(615,2017,875,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/RELS-Religious-Studies/100/RELS-175','<div class="desc"> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(616,2022,876,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-270','<div class="desc"> <p>The course examines the relationship between the theological and ethical principles of Islam and political thought. After introducing the emergence and articulation of Islamic law (Shari''ah) and the Caliphate in the Islamic Empire we will study key scholars of Islamic jurisprudence. We will pay attention to the ways in which revelation and reason the individual and the state freedom and obedience are taken up in Islamic political philosophy as well as how these ideas have been in dialogue with the West (from engagement with ancient Greek philosophy to engagement with Western economic cultural and political modernity from the 18th century on). Finally studying the work of both modernizing and reactionary anti-modern Islamic thinkers the course will culminate in an examination of the ways in which contemporary Islamic legal and political thought addresses the relationship of religion and the state and the Western concept of "the secular".</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(617,2022,878,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/200/rusn-284','<div class="desc"> <p>An examination of the phenomenon of madness in Russian culture through literature and film. The main focus will be on the psychological literature of the 19th Century including the the murder novels of Dostoevsky as well as studies of madness by Lermontov Gogol Chekhov and others. This trend in Russian literature will be related to pathological features of Russian history (Tsarism Totalitarianism) to find underlying reasons why these features are so prevalent in the Russian arts. Films will include Tsar concerning Ivan the Terrible and Burnt By the Sun a chronicle of the Stalinist terror.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(618,2022,879,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/100/soc-105','<div class="desc"> <p>This course examines the role of youth cultures in the identity formation of immigrant adolescent youth residing in the Southwest region of the United States. Particular attention is paid to: (1) theories of acculturation and assimilation used to analyze the experiences of immigrant youth; (2) the impact of geographical location social class gender race sexuality popular culture mass media and technology; and (3) the intersection of youth cultures home cultures and mainstream society.</p> <p><span style="background-color: #ffffff; color: #222222;">This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CTSJ 105, DWA 282, and SOC 105.</span></p> </div>','SOC 101 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(619,2019,880,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/SPAN-Spanish/100/SPAN-105','<div class="desc"> <p>This course offers students the opportunity to analyze narrative stories films and other cultural artifacts that document a history of immigration and migration to Los Angeles from Mexico and Central America during the twentieth and twenty-first centuries.Many of the narratives films and other cultural works studied treat significant contemporary issues (e.g. the representation of history questions of identity and alterity questions of race and ethnicity globalization authority the construction of class and gender in society) that Los Angeles faces as an emblematic socio-cultural space that continuously shifts as consequence of new arrivals to the city. Emphasis will be placed on studying narratives and films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically this course presents a critical view of the representation of migrations to Los Angeles in order to understand how these migration stories function as a socio-cultural medium that document and occupy many geographical spaces that establish Los Angeles as a heterogeneous cultural place and space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(620,2022,881,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-314','<div class="desc"> <p>How do Latin American women writers and film-makers use language and sound? This course analyzes questions of social critique and the use of language in the short stories of Uruguayan writer Cristina Peri Rossi PuertoRican writer Rosario FerrÃ© and Brazilian writer Clarice Lispector as well as the use of voice music and mise-en-scÃ©ne in films by Latin American directors Gabriela David Maria Luisa Bemberg and Susana Amaral.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(621,2022,883,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-246','<div class="desc"> <p>In <em>Costume Construction</em> students acquire the skills necessary to construct basic garments for the stage. At the end of the course each student will build a costume piece.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(622,2022,884,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-210','<div class="desc"> <p>Los Angeles is a city often known for its traffic, air pollution, auto-centric land use patterns, and car culture. However, Los Angeles is also a place of transportation innovations and a public commitment to changing the way people move to and through Los Angeles in equitable and environmentally sustainable ways. This class provides an overview of urban transportation issues and systems, focusing on the impacts of mobility policies, systems and infrastructure on cities and on Los Angeles in particular. Through lectures, guest speakers, class exercises and projects, students will explore the history of transportation in the US as well as comparatively with other countries and understand the role of policy in shaping and defining transportation systems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(623,2022,886,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-212','<div class="desc"> <p>This course will be taught by L.A. School Board member Steve Zimmer. The course will consist of a series of high profile panel discussions about some of the major issues in Education today. These include "The Future of the Urban School District" "The Crisis in Public Education Funding" "Charter Schools and Public Education" and "The Future of Education Reform in Los Angeles and Beyond" among several topics to be developed. Board member Zimmer will then engage with students in a seminar discussion in the subsequent course UEP213 about the issues and debates and research opportunities that follow from the panel discussions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(624,2022,887,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-213','<div class="desc"> <p>This course will be taught by L.A. School Board member Steve Zimmer. Students taking the course will be required to enroll in UEP 212 and attend a series of high profile panel discussions about some of the major issues in Education today. These include "The Future of the Urban School District" "The Crisis in Public Education Funding" "Charter Schools and Public Education" and "The Future of Education Reform in Los Angeles and Beyond" among several topics to be developed. The seminar will then engage in discussions about the topics explored in the Panel discussions on the major controversies in Education and identify research topics related to the current policy debates within LAUSD as well as some of the broader debates within Education policy.</p> </div>',NULL,'UEP 212 ',NULL);
INSERT INTO course_descriptions VALUES(625,2022,888,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/200/arab-202','<div class="desc"> <p>Continuation of ARAB 201.</p> </div>','ARAB 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(626,2017,890,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/300/ARTH-362','<div class="desc"> <p>Chinese art and archaeology from the neolithic period through the Tang Dynasty. Readings in historical literary and religio-philosophical texts will contextualize the study of the formative period of Chinese art history. We will trace the emergence florescence and decline of ritual art in ancient China; the birth and ascent to dominance of the Confucian scholar-elite as consumers (and ultimately producers) of art; and the impact of the introduction of Buddhism on the history of Chinese art. Archaeological discoveries continue to deepen our understanding of ancient China and we will examine the most important excavations of the past 30 years.</p> </div>','ARTH 160 or Asian history course or permission of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(627,2022,892,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-203','<div class="desc"> <p>Intermediate study in sculpture, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year.</p> </div>','ARTS 103 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(628,2022,893,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-320','<div class="desc"> <p>Animal development, with an emphasis on the molecular mechanisms that regulate cell fate, cell adhesion and motility, and the formation of different tissue types. Cell signaling pathways and gene regulatory mechanisms that control development, and are relevant to adult stem cell biology and cancer biology, are stressed throughout the course. The laboratory focuses on major invertebrate and vertebrate model organisms and both classical and molecular genetic approaches used to study animal development. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 and BIO 221, BIO 224, or BIO 226 ','BIO 320L ',NULL);
INSERT INTO course_descriptions VALUES(629,2022,894,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-320l','<div class="desc"> <p>An introduction to classical and molecular methodologies used to study animal development. The laboratory focuses on early embryonic development of major invertebrate and vertebrate model organisms: sea urchins, C. elegans, zebrafish, and chick. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 320 ',NULL);
INSERT INTO course_descriptions VALUES(630,2022,895,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-350','<div class="desc"> <p>Symbioses are intimate associations involving two or more species. Symbiotic associations are widespread in nature and we can expect to find them in every type of ecological niche. This course will cover the diversity of symbiotic interactions that exist between both microbes and fungi and various eukaryotic hosts, including plants, animals, and protists, as well as other microorganisms. Topics in both lecture and lab will range from molecular to ecological, including the specific molecular communication between partners, the evolution of unusual host structures, novel physiological and biochemical capabilities, and the unique ecological advantages that many symbioses confer. This course will also include writing, presenting, and reviewing published work on various symbioses.</p> </div>','BIO 130 and BIO 105, BIO 106, BIO 110, or BIO 115; or permission of instructor ','BIO 350L ',NULL);
INSERT INTO course_descriptions VALUES(631,2022,896,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-350l','<div class="desc"> <p>Students will investigate the presence of bacterial symbionts within animals, plants, and protists using molecular and microscopic techniques. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 350',NULL);
INSERT INTO course_descriptions VALUES(632,2022,897,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-356','<div class="desc"> <p>The biology of marine fishes begins with a study of the phylogenetic evolution of fishes. Within this context, it discusses the physiology, ecology, and behavior of marine fishes, utilizing examples from our local fauna. Advanced methods of studying marine fishes will be covered, with an emphasis on field research in which the class will visit various marine habitats throughout Southern California. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 240, BIO 250, BIO 260, BIO 268, BIO 270, BIO 275, or BIO 280; or permission of instructor ','BIO 356L ',NULL);
INSERT INTO course_descriptions VALUES(633,2022,898,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-356l','<div class="desc"> <p>Laboratory techniques in marine fishes. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 356 ',NULL);
INSERT INTO course_descriptions VALUES(634,2022,899,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-380','<div class="desc"> <p>An investigation of physiological processes in plants, including photosynthesis; nutrient uptake and water relations and how they are affected by environmental conditions; and interactions with other organisms, including insects, vertebrates, and fungi. The emphasis will be on how to quantify and predict plant physiological responses to the particular ecological pressures of Southern California. Classroom discussions and presentations will focus on papers from the current scientific literature. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 250 or permission of instructor ','BIO 380L ',NULL);
INSERT INTO course_descriptions VALUES(635,2022,900,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-380l','<div class="desc"> <p>Instruction in contemporary physiological and environmental diagnostic instrumentation and analytical methods will be followed by independent investigations in the laboratory and field. Day-long and overnight field trips will be scheduled. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 380 ',NULL);
INSERT INTO course_descriptions VALUES(636,2022,901,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/100/chem-150','<div class="desc"> <p>Symmetry is a fundamental unifying aspect of nature and is found in many human creations, from art, music, and architecture, to mathematics and science. In chemistry, symmetry is central to understanding the interplay of molecular architecture and function. This course provides the student with a qualitative and formal conceptual framework for categorizing molecular structures.</p> </div>','CHEM 100, CHEM 120, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(637,2022,902,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-305','<div class="desc"> <p>An introduction to quantum mechanics, atomic and molecular structure, spectroscopy, statistical thermodynamics, kinetic molecular theory, and chemical applications of group theory.</p> </div>','CHEM 130 or CHEM 150, Calculus 2, and PHYS 120 or PHYS 125; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(638,2022,903,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-305l','<div class="desc"> <p>Atomic and molecular spectroscopy and modern techniques in physical chemistry. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 305 ',NULL);
INSERT INTO course_descriptions VALUES(639,2022,904,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-332','<div class="desc"> <p>Modern analytical instrumentation provides scientists and engineers with an impressive array of powerful tools for studying the composition and structure of matter, from the first electronic pH meter, to advanced three-dimensional MRI imaging spectrometers, to portable detectors explosive compounds. This course examines the statistical, electronic, physical, and chemical requirements for the construction and operation of modern analytical instruments.</p> </div>','CHEM 300 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(640,2022,906,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-242','<div class="desc"> <p>Computational modeling provides important insights into how the mind/brain may work. We will examine three different approaches that have been used to provide insights into cognition: symbolic methods, connectionism, and probabilistic methods. We will use computer software to explore how these approaches work in practice. Specific applications, such as perception, language, and memory will be covered. The assumptions and limitations of each approach, as well as the metaphor of mind/brain as a computer, will be critically considered. This course has a mandatory laboratory component which will include both experimentation and computer programming. No previous programming background is required.</p> </div>','COGS 101, PHIL 225, MATH 186, MATH 210, MATH 214, MATH 252, COMP 157, COMP 161, COMP 165, or COMP 211; or permission of instructor ','COGS 101 (can be taken concurrently) ',NULL);
INSERT INTO course_descriptions VALUES(641,2017,907,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/COGS-Cognitive-Science/200/COGS-242L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(642,2022,908,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-157','<div class="desc"> <p>Programming in C++, including: procedures; functions; control structures; files; structs; and elementary uses of pointers, objects, and classes. Does not assume any prior knowledge of C. Course offered in alternate years. Not offered every year. Not open to students who have taken, or are taking, COMP 161.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(643,2022,910,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-270','<div class="desc"> <p>This course looks cross-culturally at children and childhood and uses ethnographic case studies as a basis for examining the ways in which the very young participate in the social lives of their communities. The focus is on those between the ages of 5-12 and the primary topics include: children''s play, socialization, learning, political action, and productive work. We will explore the lives of children in horticultural, pastoral, rural, and urban societies in Africa, Asia, Polynesia, and the contemporary United States.</p> </div>','Any 100-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(644,2022,917,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-237','<div class="desc"> <p>The course will examine some of the communist countries that have survived the collapse of the Soviet Union, specifically: Cuba, Vietnam, and China. We will discuss the political and social life within each country, their relationship to the United States, and the prospects for political change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(645,2017,918,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/200/DWA-252','<div class="desc"> <p>While Washington policymakers during the Cold War paid only episodic attention to South Asia the region has become a focal point for U.S. security policy over the last decade or so. Since the nuclear weapon tests by India and Pakistan in 1998 their entrenched conflict-prone strategic rivalry has acquired a much more dangerous edge. The region is also the epicenter of global terrorism with Islamabad simultaneously acting as a sponsor of the Taliban forces fighting in Afghanistan and serving as a pivotal U.S. ally in the war against Islamist terrorism. Finally after decades of disdain about India''s strategic potential U.S. officials have invested singular energy in recent years in developing what is a tacitly anti-China security partnership with India. Although South Asia encompasses a number of countries this course will focus on the region''s two most important powers - India and Pakistan - and their relationships with the United States and China - the two extra-regional powers that have the most influence on regional affairs. The following topics will receive special attention: The sources of and prospects for the India-Pakistan strategic rivalry including the long-standing territorial dispute over Kashmir and the more recent competition for influence in Afghanistan. The effects of nuclear proliferation on India-Pakistan interactions. The economic rise of India and its implications for New Delhi''s security posture especially vis-à-vis Islamabad Washington and Beijing Pakistan''s national prospects and their security implications. China''s growing role in regional security affairs The emergence of non-traditional security challenges in the region (e.g. conflicts over access to natural resources population pressures.) The impact of South Asian security issues on U.S. strategic interests the development of U.S. bilateral relations with India and Pakistan and the management of the triangular relationship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(646,2022,919,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-337','<div class="desc"> <p>This course takes a more in-depth look at the theories and approaches of international relations. The goal of the course is to provide students with an appreciation of how theory is able to achieve three things: 1) explain, 2) critique, and 3) guide the actions of individuals, institutions, and states in the international arena. Theorizing, therefore, is not simply an abstract exercise but can have real world implications. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(647,2017,920,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/300/DWA-377','<div class="desc"> <p>Junior seminar on the global impact of the rising nations of Brazil India Russia and China--so-called BRIC countries--the growth of their economies and their growing political and economic influence on global power arrangements--and an analysis of the US response to the rise of these nations in the post-Cold War era of globalization. What is the intellectual justification of the course? Provide juniors and seniors in DWA and related majors with an analysis of key players on the international scene and a critical examination of how the US is responding to a multi-polar world.</p> </div>','DWA 101 or POLS 101 . Junior or senior standing in DWA or Politics',NULL,NULL);
INSERT INTO course_descriptions VALUES(648,2022,921,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-305','<div class="desc"> <p>This course is an introduction to the study of strategic interaction using the tools of game theory. The focus of the course is on developing a set of analytical techniques with the goal of understanding and using game theoretical models in economics. The first part of the course introduces the basic framework and tools of game theory. The second part of the course covers a number of economic (and some non-economic) applications of game theory; specific topics may include: auctions, bargaining, voting, and market competition.</p> </div>','ECON 250 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(649,2017,922,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ECON-Economics/300/ECON-312','<div class="desc"> <p>The theory and analysis of foreign exchange markets macroeconomic policy-making in an open economy setting international investment flows and international financial institutions. The course also examines the international monetary system over the past century and looks at innovations in global financial institutions.</p> </div>','ECON 251 .',NULL,NULL);
INSERT INTO course_descriptions VALUES(650,2022,923,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-315','<div class="desc"> <p>An empirical and analytical study of financial markets. Topics covered will include: net present value calculations, the capital asset pricing model, financial derivatives, the efficient market theory, the term structure of interest rates, and banking.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(651,2022,924,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-326','<div class="desc"> <p>An application of economic analysis to various topics in personnel economics, including: compensation and incentives, hiring, training, downsizing/buyouts, stock options, pensions, and teams, among many others. In order to add realism to, and applications for, the analysis, students will discuss and evaluate numerous real-world mini-cases and more formal case studies. Students will be evaluated on the quality of their written work, problem sets, examinations, and discussion; a variety of class formats will be used. Note: Students who take this course may not take Professor Moore''s section of ECON 495.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(652,2022,925,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States: Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students, and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(653,2022,938,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-342','<div class="desc"> <p>Landforms and their interpretation in terms of tectonic and climatic processes will be presented. The focus will be on landforms such as: mountain belts, faults, and landslides caused by active tectonic processes. Methods of dating and quantifying geologic events will be introduced. Scientific writing skills will be emphasized. <em>Includes one three-hour laboratory per week and field trip.</em></p> </div>','GEO 225 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(654,2022,939,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-345','<div class="desc"> <p>Petrology is the study of the origin, tectonic occurrence, geochemical evolution, and classification of igneous and metamorphic rocks. Students will address questions related to the origin of the Earth''s crust through examination of the textures, mineral assemblages, field relations, and compositional characteristics of igneous and metamorphic rocks. Laboratory work will engage students in the study of rocks in hand specimen and microscope, as well as the analysis and interpretation of experimental and geochemical datasets. <em>Includes one three-hour laboratory per week and multiple field trips.</em></p> </div>','GEO 305 ','GEO 345L ',NULL);
INSERT INTO course_descriptions VALUES(655,2022,940,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-345l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 345',NULL);
INSERT INTO course_descriptions VALUES(656,2022,941,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-232','<div class="desc"> <p>This course covers major trends and developments in the cultural history of postwar Germany. Topics include: the reconstruction of culture after 1945, the makeup of cultural institutions, the mass media, popular culture vs. traditional culture, the counter culture of the 60''s and early 70''s, and the problems of unification after 1989. Taught in German, with emphasis on oral presentations and essay writing. Readings include: literary texts, documentary material, newspaper, and magazine articles.</p> </div>','GERM 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(657,2022,942,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-121','<div class="desc"> <p>A survey of multiple Western civilizations and their interrelationships. Among ancients, we shall study Mesopotamians, Egyptians, Hebrews, Persians, Greeks, and Romans. In medieval times, we shall examine Catholic Europe, Greek Orthodox Byzantium, Islamic Civilization, and their interrelationships. We shall consider the treatment of women and of minorities, and shall highlight travelers between civilizations. We shall conclude with the European Renaissance and Reformation, Turkish hegemony in the Eastern Mediterranean, and the shift in trade from the Mediterranean to the Atlantic Ocean, as modern science and enlightenment challenge traditional civilizations.</p> <p><strong>Survey Requirement Met:</strong> Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(658,2017,943,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/HIST-History/Asia/200/HIST-243','<div class="desc"> <p>Chinese history from about 1600 to the present: encounter with the West maritime trade the growth of the domestic economy the rise of the Manchus and territorial expansion internal decline rebellions imperialism and revolution. Modernization efforts ideological struggles and the cultural and economic transformations under the People''s Republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(659,2022,944,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-248','<div class="desc"> <p>This course covers the history of Japan from the 1868 Mejii Restoration to the present, with particular focus on the emergence of modernity, the Pacific War, and popular culture. The first section of the course will examine Japan''s modern revolution in the Mejii Restoration, industrialization and modernization in the Mejii Period, and the development of Japanese colonialism. The second section of the course will focus on the Pacific War, the bombing of Hiroshima and Nagasaki, and the American occupation, with particular focus on the politics of gender and race. The third section of the course will look at Japan''s explosive postwar economic recovery and the consumer and popular culture it produced.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(660,2022,945,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-274','<div class="desc"> <p>From its earliest written records in ancient Mesopotamia and Egypt, medicine flourished through Greece and Rome, was then kept alive during the medieval golden age of Islamic science, then reawakened during the Renaissance, Scientific Revolution and Enlightenment in Europe, and then crossed the Atlantic to America where indigenous wisdom already thrived. This course traces the history of medicine through these different times, cultures and regions: theory and practice; great doctors and healers, both male and female; and the effects of epidemics, such as the Black Death, on the course of Western civilization. We will end with some historically based speculations about the medical future.</p> <p><strong>Survey Requirement Met:</strong> Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(661,2022,946,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-309','<div class="desc"> Developmental perspective of factors contributing to acquisition of motor control from infancy through adolescence. Emphasis placed on maturational and environmental factors. </div>','PSYC 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(662,2019,947,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/LANG-Language/200/LANG-260','<div class="desc"> <p>This new interdisciplinary course is an introduction into theater and drama methods in language teaching such as improvisation (based on Keith Johnston Augusto Boal and others) German and Swiss Drama pedagogy (based on Felix Rellstab Ulrike Hentschel and others) TPR (Total Physical Response James J. Asher) Biomechanics (based on Wsewolod Meyerhold) and others. We will begin with practical tryouts and discussions on the methods used. Specific Drama Pedagogy in language learning studies (Elektra Tselikas Manfred Schewe) will be included in the theoretical reflection part of the class. This teaching approach can be applied to different languages depending on the students'' backgrounds. A practical application in conjunction with CCBL is scheduled for the following year. The course is open to all students interested in language learning and teaching ESL theatre education and CCBL.</p> </div>','One year in Language instruction at Occidental or the equivalent.',NULL,NULL);
INSERT INTO course_descriptions VALUES(663,2022,948,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/100/math-186','<div class="desc"> <p>This course treats network and graphical models arising especially in biological and cognitive sciences. Methods include networks, graphs, and matrices; probability, conditional probability, and Markov chains; discrete-time dynamics and recurrent neural networks; Bayesian statistical inference on graphical models; and optimization on graphs, including dynamic programming. In the computing laboratory component (a separately-scheduled 1.5 hour session), students will learn to use MATLAB to build and analyze models. Students will complete projects in each major area of the course. Calculus is not a pre-requisite. While open to all students this course is intended as an alternative to calculus as a first course in college-level mathematics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(664,2022,949,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-320','<div class="desc"> <p>A first course in abstract algebra. Topics will be chosen from group theory (basic axioms and theorems concerning subgroups, cosets, normal subgroups, group homomorphisms), ring theory (basic axioms and theorems concerning subrings, ideals, ring homomorphisms, quotient rings), and field theory.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(665,2022,950,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-354','<div class="desc"> <p>Cantor''s naïve theory of sets and equinumerosity. Paradoxes and axiomatic set theory. Finite and infinite cardinal numbers, fixed point theory, applications to computer science. Well orderings, transfinite induction and recursion, the Axiom of Choice and its consequences, ordinal numbers, and the cumulative hierarchy of sets. Discussion of the Continuum Hypothesis and its relation to models of set theory.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(666,2022,951,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-372','<div class="desc"> <p>Optimal decision-making and modeling of deterministic and stochastic systems. Different systems of constraints lead to different methods. Linear integer dynamic programming and combinatorial algorithms. Practical problems from economics and game theory. Inventory strategies and stochastic models are analyzed by queuing theory.</p> </div>','MATH 210 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(667,2022,952,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-380','<div class="desc"> <p>Investigation of the existence and classification of arrangements. Topics to include: principles of enumeration, inclusion-exclusion, the pigeon-hole principle, Ramsey theory, generating functions, special counting sequences, and introductory graph theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(668,2022,953,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-104','<div class="desc"> <p class="sc-BodyText">This course surveys the musical styles and genres of the African continent and the Middle Eastern world. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(669,2022,954,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-114','<div class="desc"> <p class="sc-BodyText">This class introduces students to the world of the orchestra beginning with its historical development and followed by an in-depth exploration of its instruments. Each class will focus on a different instrument its history and its fundamental properties (range characteristics timbre etc.). Performance faculty and proficient student instrumentalists will provide routine in-class demonstrations of the instruments we study. In-class listening will supplement weekly listening assignments covering orchestral music from the Baroque to the present. The course will emphasize the relationships between instruments (e.g. what does an oboe and trumpet sound like when playing the same line simultaneously) and how these relationships inform a composer’s decision-making process when writing for an orchestra. No music theory background is required only an ability to read music notation at a basic level (treble clef bass clef scales etc.). This course will serve as a prerequisite to MUSC 258 (Introduction to Film Scoring) starting Fall 2016.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(670,2022,955,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-124','<div class="desc"> <p class="sc-BodyText"></p> Son Jarocho Ensemble introduces students to the songs and instrumental techniques of son jarocho, a musical genre from Veracruz, Mexico that mixes indigenous Mexican, African, Spanish, and Arabic sounds. The course will be taught by a master musician who brings over twenty years of musical experience to his classes. Students will learn to play jarana, the eight-stringed guitar that provides the harmonic scaffold for son jarocho. In addition to weekly rehearsals with the ensemble, students will be expected to practice on their own and to participate in a public performance at the end of the semester. No prior music experience is required. <p class="sc-BodyText"></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(671,2022,956,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-263','<div class="desc"> <p>This course picks up where MUSC 261 leaves off, with the emergence of musical Romanticism and, with it, an understanding of music, composer, and audience that still informs listening practices today. After surveying the music of the first generation of Romantic composers (with special attention to the music of Fryderyk Chopin), we turn to Richard Wagner’s music and writings and how they shaped the rise of modernism in music, with its new forms, genres, styles, and pitch systems. We then take up jazz, the radical experimentation of the 1920s ultra-modernists, and music under fascism. Thereafter, we study all subsequent major musical developments, through to post-minimalism and hip hop. Throughout, we will be alert to the political, philosophical, and cultural forces shaping the music at issue. This course may be used by Music majors to fulfill the College-wide Second-Stage Writing Requirement. Prerequisite: MUSC 101 or permission of instructor.</p> </div>','MUSC 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(672,2022,957,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-385','<div class="desc"> <p>Topics vary by semester.</p> <p><strong>Bach’s Cycles: Bach, Musical Systems, and the Enlightenment</strong></p> <p>This seminar will explore stylistic and structural issues in several monumental works of Bach. Two points of view will be taken: analytic, and musico-sociological. Works to be studied include the Goldberg Variations, the unaccompanied sonatas and partitas for violin, the unaccompanied suites for cello, the Well-Tempered Clavier, the Art of Fugue, and the Musical Offering. Topics for papers and presentations will be developed with attention to seminar participants’ particular interests. A course grade of B- or better, and satisfactory completion of a minimum of 15 pages of written work will satisfy the College’s second-stage writing requirement as implemented by the Music Department. Prerequisite: MUSC 250 (may be taken concurrently). </p> <p><strong>Music and Food</strong></p> <p><strong></strong>This interdisciplinary research seminar will examine the relationship between music and food and thus hearing and taste in Europe and the United States beginning with the 16th-century category of musical composition called “table music” and culminating in the present-day gastropub. Along the way we will explore topics such as the 18th-century emergence of aesthetics as a branch of philosophy the rise of the restaurant and gastronomy Dandyism and Decadent literature and “fine dining” in the United States. We will read scholarly literature from the fields of philosophy history cognitive science sociology literature and music. Students will carve out an area of research early on and develop it over the course of the semester culminating in a research presentation and final argument-driven research paper. The course will conclude with the recreation of a historical banquet.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(673,2019,958,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-300','<div class="desc"> <p>An examination of the moral and political philosophies of Socrates Plato and Aristotle. Questions for discussion will include: how should I live and what sort of person should I be? What is the nature of happiness? Can I be happy and also morally vicious? Do I have any good reason to act in the interests of others when they conflict with my own interests? What is the nature of justice and the just state? How do states affect our desires and aims? Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(674,2022,959,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-312','<div class="desc"> <p>Søren Kierkegaard (1813-1855), sometimes referred to as “the father of existentialism”, was a sharp critic of modern philosophy, institutionalized religion, and what he called “the present age”. For Kierkegaard, the fundamental problem of philosophy was to describe what it means and what it takes to become human—suggesting, ironically, that it is possible for a human being not to be human. The primary purpose of this course is to read Kierkegaard’s most influential texts closely, situate them in their historical and philosophical context (namely, early 19th Century Western Europe), and draw out their contemporary relevance, paying particular attention to the concepts of irony, anxiety, despair, love, and faith. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(675,2019,960,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-315','<div class="desc"> <p>This course offers philosophical readings of literary texts, including novels, plays, and poems. Fyodor Dostoevsky''s The Brothers Karamazov is a gripping story of murder and romantic rivalries, a wonderfully inventive literary work, and one of the finest philosophical novels ever written. We will read all of The Brothers Karamazov and discuss some of the main philosophical issues that it addresses. Course topics will include: (1) the conflict between faith and reason, and the role -- if any -- that faith occupies in a good life (2) the nature of love, and the meaning and significance of the command to "love your neighbor" (3) what it means for human beings to flourish, and what sort of community makes flourishing possible. We will also discuss more recent philosophical work and film on related topics. <em>Not open to first year students.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(676,2022,961,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-345','<div class="desc"> <p>How is it possible to study the mind scientifically? This class will explore philosophical issues about the application of scientific methods to cognitive phenomena, including questions such as the appropriate architecture of cognition, the possibility of artificial intelligence, the relation between commonsense psychology and theories in cognitive science, and the possibility of a scientific understanding of consciousness.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(677,2019,962,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-375','<div class="desc"> <p>This course will examine: (1) the theories of knowledge of such philosophers as Price Russell and Chisholm ("Foundationalists") (2) some of their critics such as Sellars and Quine and (3) recent work in naturalized epistemology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(678,2019,963,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-385','<div class="desc"> <p>The course will focus on contemporary readings that raise some of the most fundamental issues in metaphysics. The following questions are among those that will be addressed: Can we make sense of the idea that we are free agents? Can we understand the concept of causation? Is there a compelling argument for the existence of God? Is there any sense to be made of the claim that some claims are true by necessity while others are only contingently true? Are there true mathematical claims?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(679,2022,964,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-262','<div class="desc"> <p>Theoretical and experimental electronics fundamental to modern research. Includes one three-hour laboratory per week.</p> </div>','PHYS 120 or PHYS 125; or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(680,2017,965,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/The-160-Series/PHYS-262L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(681,2022,966,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-207','<div class="desc"> <p>This is a course about urban politics that takes Los Angeles as its case study. Because of the pattern of growth in the area Los Angeles is broadly defined to encompass the city the county and the region. Since politics is the study of power we will examine power in the context of the city; who has it who seeks it how has it shifted over time and what consequences result from it being exercised? Significant attention will be paid to the agency of those who have at various times had the least power in the city; how are they represented or not represented how can they influence the exercise of power? Many look to Los Angeles as a paradigmatic city. We will query the appropriateness of this observation as we identify key concepts in urban politics apply them to Los Angeles and then consider how much Los Angeles sets follows or deviates from trends.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(682,2020,968,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/political-theory/pols-253','<div class="desc"> <p>Nietzsche on nihilism power art and the creation of value; Durkheim on community and anomie; bureaucracy and authority in Weber; Freud on civilization''s discontents; the Marxisms of Lenin and Gramsci; Heidegger''s thoughts on Being; the existentialism of Sartre; the feminism of de Beauvoir; Marcuse Habermas and the Frankfurt School; Foucault and theories of power.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(683,2022,969,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-257','<div class="desc"> <p>This seminar surveys the historical roots of modern conservative and libertarian political ideas with particular attention to the persistent tension between tradition and innovation. The purpose of the seminar is to enable students to recognize recurring themes that have shaped political thought and action over several thousand years. Students will be graded on weekly essays and seminar participation.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(684,2020,970,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/comparative-politics-and-area-studies/pols-325','<div class="desc"> <p>A comparative study of major political and security developments in Europe. The course will focus on political cultures institutions and party systems in major countries. It will examine the evolution of Euro-institutions and current issues facing NATO and the European Union - including immigration and terrorism a resurgent Russia and the future of the transatlantic relationship. For Politics UEP and DWA majors only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(685,2022,971,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-302','<div class="desc"> <p>This course focuses on how sensory systems function, with emphasis on quantitative methodologies, neurophysiological mechanisms, structure/function relationships, and ecological contexts. How humans perceive the world is situated in a comparative landscape -- that is, human are assumed to be creatures with much in common with other creatures and yet different in some crucial ways tied to their evolutionary history and habitats. Attention is paid to phenomenology and philosophical issues, such as the relationship between perception and "reality." This course is distinguished from cognitive or social psychology approaches to perception, by virtue of its focus on evolutionarily old, fully embodied, and sensuous experience.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(686,2022,972,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-336','<div class="desc"> <p>This course surveys the emerging field of Evolutionary Psychology. It begins with the historical social and political context of evolutionary theory reviews tenets of modern evolutionary theory explores the relationship between evolution and other change processes and applies evolutionary reasoning to psychological phenomena and contemporary social issues.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(687,2022,973,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-448','<div class="desc"> <p>Introduction to and evaluation and application of classic and contemporary theories of personality including psychoanalytic humanistic behavioral cognitive and object relations models. Primary sources autobiographies and case studies will supplement traditional texts.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 and PSYC 321, PSYC 323, or PSYC 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(688,2022,974,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-460','<div class="desc"> <p>Psychological assessment involves the measurement and evaluation of psychological characteristics including cognitive ability personality traits motivation and more. A blend of theory-driven research and practical analysis techniques will be covered to explain how common and experimental instruments work and to examine whether certain methods are valid in academic organizational criminal and mental health contexts.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 201; and PSYC 321 or PSYC 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(689,2022,975,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-190','<div class="desc"> <p>From the 1st-6th centuries CE, early Christian communities throughout the Mediterranean had different ideas about who Jesus was, what kind of movement he inspired, and what it meant to be or to act like a Christian. In this course, students will investigate the variety of early Christian communities that structured their movements around the figure of Jesus by studying their primary sources: stories, letters, sermons, theological treatises, art, artifacts and architecture. Students will explore the practices and ethics that dictated the daily lives of early Christians, how they interacted with their Jewish and “pagan” neighbors, the theological issues debated among early Christian communities, including charges of "heresy" and the development of orthodoxy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(690,2022,976,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-250','<div class="desc"> <p>What is Religious Studies? Students in this course will answer this question first by tracing the historical formation of the academic study of religion (from monasteries to the university), and across various disciplines (sociology, psychology, anthropology, history, economics, etc.). We will then engage more deeply with the various theoretical and methodological tools available to scholars of religion by reading a range of scholarly works that illustrate these approaches and by giving students the opportunity to practice some of these approaches. In the end, students will become familiar with the landscape of the academic study of religion, will be able to assess the value and limitations of different scholarly approaches to the study of religion, and will have cultivated skills necessary to participate in conversations in the field. Required for Religious Studies majors and minors, recommended in the Sophomore or Junior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(691,2019,977,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/RELS-Religious-Studies/200/RELS-285','<div class="desc"> "We have killed God," Nietzsche explained. But the "Death of God" has not meant, and does not mean, the end of religion. If ''religion'' and ''theism'' are not the same thing, if human religious concerns and instincts go beyond a belief in God or gods, then what is religion? What is religion without God? This course will examine and compare two versions of ''religious atheism'' -- the Buddhist tradition and the philosophy of Friedrich Nietzsche. In the Buddhist tradition, we find a religious tradition that began without even addressing the question of God or gods and that has continued to develop a non-theistic spirituality for over two millennia. In juxtaposition to that tradition, we interpret Nietzsche''s philosophy, which rises out of the ashes of the "Death of God," as a radical revolution in Western spiritual understanding and explore its implications in relation to Buddhism. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(692,2020,978,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/rels-religious-studies/300/rels-347','<div class="desc"> <p>An intensive review of landmark cases concerning the establishment and free exercise of religion clauses of the first amendment. We will study the history and varying interpretation of these clauses. Students will focus on mastering the arguments presented in landmark cases concerning sabbath observance religion and the schools ritual animal sacrifice ritual drug use and religious displays in public places among others. <em>Open to juniors and seniors only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(693,2022,979,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-250','<div class="desc"> <p>This course provides a basic sociological understanding of relations among racial and ethnic groups in the United States. A sociological approach includes considering race and ethnicity as social constructs that permeate all social life are entrenched in social structures and institutions and shift and mutate over time and place. Such a perspective suggests that (1) race and racism are not merely the ''problems'' of/for subordinate racial and ethnic groups but are reflective of society-wide power relationships that deeply affect all of us on a daily basis (2) that racial and ethnic categories - including ''white'' - can be viewed usefully as the result of historical struggles over economic resources political access and cultural identity rather than as objective measures of biological difference and (3) the institutional forms of racism indelibly etched into this nation''s past did not end with civil rights legislation of the 1960s but continue to shape social institutions today.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(694,2022,980,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-255','<div class="desc"> <p>This course examines the role of youth cultures in the identity formation of adolescents residing throughout the United States. Particular attention is paid to 1) the impact of geographical location social class gender race sexuality popular culture mass media and technology; (2) the intersection of youth cultures and mainstream society; and (3) the contention that some youth cultures are "deviant".</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(695,2022,981,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-280','<div class="desc"> <p>Why does the United States incarcerate more of its population than any other nation in the world? Why does death by injection seem kinder and gentler-and thus more acceptable-than public hangings of the past? What are the consequences for justice and democracy in an era of unprecedented confinement and correctional supervision? Using various historical legal and sociological perspectives we will focus on questions such as these with an emphasis on: the cultural life of punishment crime control as a political issue the racial and class dynamics of punishment and inequality and contemporary issues surrounding modern penal sanctioning (e.g. mass incarceration) and its consequences. <em>This course is repeatable once for credit.</em></p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(696,2017,982,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/SOC-Sociology/400/SOC-420','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. To a lesser degree we will also examine Central American immigration from an international relations perspective.</p> </div>','SOC 101 or permission of Instructor.',NULL,NULL);
INSERT INTO course_descriptions VALUES(697,2022,984,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-302','<div class="desc"> <p>An introduction to Spanish Peninsular literature and culture from the Middle Ages to the 18<sup>th</sup> century. This course examines the cross-cultural elements (Arab, Jewish, French, Italian, Trans-Atlantic and others) that have influence Spanish literature across the centuries. Readings include Mozarabic poetry, the <em>Cantar de Mio Cid</em>, Medieval narratives, <em>La Celestina</em>, Renaissance poetry, selections of <em>Don Quijote</em>, and Golden Age dramas. The class also incorporates representative examples of art and films.</p> </div>','SPAN 202, SPAN 211, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(698,2022,985,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-353','<div class="desc"> <p>This course analyzes both pictorial and literary images of sacred and profane love in Medieval and Golden Spain. Through a comparative approach the course will explore the differences and similarities in the treatment of secular and religious love by painters (Velazquez Murillo Rivera etc) and writers (Garcilaso San Juan de la Cruz Gongora etc). Topics such as courtly love mystical experience and social conventions will be studied. At least two field trips to local museums will be scheduled.</p> </div>','SPAN 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(699,2022,986,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-362','<div class="desc"> <p>This course will focus on the theater of Federico García Lorca and the cinema of Luis Buñuel and Pedro Almodóvar. Students will engage in an in-depth study of García Lorca''s plays examining his theatrical representation of surrealism, gender, and sexuality in conjunction with key films of Buñuel and Almodóvar.</p> </div>','One Spanish 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(700,2022,987,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-378','<div class="desc"> The course adopts a multidisciplinary approach to the question of how place and landscape (Buenos Aires and the pampas) influence literary and filmic imagination. Buenos Aires is one of the great cities of Latin America. Readings for the course include nineteenth-century essays and stories which document the harnessing of the agricultural resources of Argentina into a meat-exporting economic machine; turn-of-the-century fiction and essays also document the transformation of Buenos Aires by new European immigration (often non-Spanish), the impact of European anarchist thought, and the architectural boom at the end of the nineteenth century. Mid-twentieth-century writers such as Borges, Cortázar and Sábato will be discussed in the context of their references to specific Buenos Aires neighborhoods (e.g. Chacarita, Belgrano, San Telmo, and Retiro). Through documentaries and narrative films, the second half of the Spring course introduces students to the rise of the Argentine Armed Forces, the enduring influence of Peronism, the trauma of the dictatorship years, and the economic and political contradictions of contemporary Argentina. </div>','SPAN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(701,2022,988,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-201','<div class="desc"> <p>We study the artistry of contemporary theatrical movements as well as American writers from divergent cultural and aesthetic backgrounds. By looking at movements and artists in their cultural and social contexts we explore the sources the aims and the artistic strategies of their works while developing an understanding of important new voices in American Theater. The focus of the class will vary from year to year. May be repeated for credit one time with a different topic.</p> <p><strong>The Black Arts Movement Explored and Deconstructed</strong></p> <p>An in-depth, intellectually stimulating exploration into the complex and impactful Black Arts Movement of the 1960s and 1970s. Through reading and analyzing the poems, plays and criticism of the time, as well as lectures and small group discussions and “on your feet” performance activities, students will gain insights into the people, the places, and the critical junctures that emerged during this profoundly explosive era of art and culture. Artists explored include Amiri Baraka, Sonia Sanchez, Nikki Giovanni, Henry Dumas, Audre Lorde, Ed Bullins, Ntozake Shange, and others. Themes/concepts include black identity, the connection between black arts and black power, the rejection of integration as an ideal, LGBTQ and Black Arts, the assassination of Malcolm X, John Coltrane and Sun Ra, black radical thought, the African-American male as a Christ figure, male chauvinism in Black Arts and Black Power, and “future directions,” i.e. the influence of the Black Arts Movement on other cultural movements and American aesthetics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(702,2019,990,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/THEA-Theater/200/THEA-245','<div class="desc"> <p>Students in <em>Stage Makeup</em> learn the fundamentals of makeup design for the theater. We cover a number of makeup techniques including basic three-dimensional corrective glamour character and old-age makeups as well as the creation of special makeup effects. During the semester our students put theory into practice as they create a variety of practical makeup designs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(703,2022,991,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(704,2022,992,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-302','<div class="desc"> <p>During the semester we study the works of various twentieth century playwrights. Different years will feature different playwrights: so one semester might look at farceurs another semester political pioneers and another European iconoclasts. In addition to reading several scripts by each playwright our students also attend live performances prepare research projects and create performance projects in response to the semester''s writers. Students may use this course to fulfill the Junior Writing Requirement for the Theater Major.<em> There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(705,2020,993,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/thea-theater/300/thea-320','<div class="desc"> <p>Building on the foundation of Introduction to Technical Theater, the students in this course learn advanced construction techniques, metal working and welding, furniture construction and repair. Students in the class will also act as crew chiefs for Theater Department productions.</p> </div>','THEA 120; and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(706,2022,994,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-325','<div class="desc"> <p>Studying the theories the psychological foundations and techniques of lighting design for the theater our students develop in this course an intellectual and practical foundation of this significant and accessible area of theater design. During the semester we guide students in the class through bothindividual and group design projects. <em>There is a material/tickets fee of $60 for this course which includes one two-hour laboratory session each week.</em></p> </div>','THEA 120, THEA 175, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(707,2022,995,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-204','<div class="desc"> <p>The course presents a broad view of the roots of environmentalism including the relationship of environmentalism with respect to issues of class race gender and ethnicity. It situates the history present day circumstances and future direction of the environmental movement within the broader study of environmental topics and methods. It also provides the background to understand better the significance of this crucial social movement and how it has addressed the complex relationships between urban industrial and natural environments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(708,2022,996,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-302','<div class="desc"> <p>This course examines how societies provide people with shelter - through market forces government policy and self-help efforts. The course will focus on the United States but will also look at other societies to help understand the strengths and weaknesses of the U.S. approach. Students will examine such housing problems as homelessness slums (substandard housing) the shortage of affordable housing racial segregation foreclosures and other topics. It will examine the pros and cons and different forms of rental housing and homeownership. It will look at the connection between housing issues and the environment public health education transportation suburbanization and sprawl poverty and inequality and racism. Students will explore housing as an aspect of our culture such as homeownership as the "American dream" and housing as a "haven." The course will explore the history of housing problems and housing policy including zoning racial discrimination finance public housing different government subsidies for housing and taxes. We will debate whether decent housing is a "right". We will look at housing problems and policies at the local state and national levels. Students will explore the politics of housing in terms of the various interest groups - including developers banks tenants community organizations landlords contractors unions and others -- involved in shaping housing policy. Students will also learn about housing as part of the "built environment" architecture land use urban design as a component of urban planning and as a part of "livable" cities. They will also examine housing as a component of real estate development and explore what housing developments - whether for-profit or non-profit - do.</p> </div>','UEP 101, ECON 101, POLS 101, SOC 101, UEP 106, or POLS 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(709,2022,997,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-395','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>Science, Technology, &amp; Justice: The Making of “Modern” Families</strong></p> <p>Does reproductive justice include a right to bear children using technological means? What about using 3<sup>rd</sup> parties like egg and sperm donors? Are reproductive technologies expanding definitions of family or reinforcing race, class, and gender inequalities? This upper-division seminar will examine reproduction from a social justice perspective, with particular attention to how the politics of reproduction are shaped by the intersecting inequalities of gender, race, class, dis/ability, and sexuality. Reproduction is not only a biological process; it is a battleground of social and political struggle. The course will familiarize students with foundational academic and activist approaches to reproduction. Students will learn about the history of and differences between reproductive rights and reproductive justice movements. We will then look at the new questions and challenges reproductive technologies raise for social justice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(710,2022,998,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-285','<div class="desc"> <p>This course will explore artistic practices in the U.S., North America, and Europe, during the long 19th century, from roughly 1789 to 1900. Lectures, discussions, and readings are designed to provide a thematically-driven, chronological overview of the period. Yet, the course will not be a traditional "survey," rather, it will focus on some of the key changes in ideas about artistic culture; art practice; and practices of regional, national, and transnational identity formation as expressed in visual art. This course will explore the role of art in social and political revolution, as well as its formative status as an engine of cultural imperialism in the 19th century, and, in addition will explore some of the more traditional approaches to studying the status of art, such as the role of the artist and the transformation of the art "market" in the wake of the industrial revolution. Key debates within the field of Art History will be explored, as well. Museum visits required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(711,2022,999,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/100/arts-107','<div class="desc"> <p>The aim of the Digital Photography course is to develop the conceptual, technical, and historical tools to develop a critical photography practice. The course will consist of a combination of technical seminars, critiques, class readings, field trips, lab time, and lectures in photographic history and contemporary art practice. The course will provide a technical introduction to the fundamentals of digital photography, including: camera operation, file management, image processing, Photoshop, printing techniques, and image presentation. Additionally, students will develop the critical skills needed to discuss photographs productively, participate in critiques, and generally situate their photographic production within a larger cultural and historical construct. Emphasis will be placed on student''s ability to make, understand, and discuss photographs in a substantive way. Lectures, critiques, and personal consultations will stress the interdependent concerns of technique and content. Underscoring the course''s outcomes of visual literacy are the centrality of photography to the historical development of modernity and the crucial role of digital photography in our image-centric globalized world. Throughout the course, students will be encouraged to integrate the breadth of their liberal arts studies in their image making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(712,2022,1002,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-290','<div class="desc"> <p>This two-unit course will offer students the opportunity to learn techniques of contemporary biology that are used in the laboratory and in the field. These may include: culture and handling of biological specimens, observational methods, imaging use of instrumentation to gather data, methods of data analysis, and identification of organisms. By the end of the semester, students will have been exposed to and gained practice in a diversity of techniques relevant to the practice of biological science. Graded on a credit/no credit basis only. May be repeated once for credit.</p> </div>',NULL,'BIO 103 (Urban Ecology) and BIO 198 ',NULL);
INSERT INTO course_descriptions VALUES(713,2022,1003,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-349','<div class="desc"> <p>This course explores the roles of the essential biological macromolecules, focusing on proteins, while covering lipids, carbohydrates, and nucleic acids. Topics include the structure and function of these macromolecules, as well as an investigation of the biochemical methods used to study them. Also included are topics covering proteomics, DNA-based information technologies, biosignaling, and an introduction to enzyme kinetics. This course is the first in a two-semester sequence of Biochemistry classes (with CHEM 350) that is required for Biochemistry majors. For a one semester Biochemistry class, see BIO 322.</p> </div>','BIO 130 and CHEM 220; or permission of instructor. Not open to students who have successfully completed BIO 322. ','BIO 349L ',NULL);
INSERT INTO course_descriptions VALUES(714,2022,1004,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-349l','<div class="desc"> <p>The application of techniques to study protein structure and function, including protein purification, column chromatography, enzyme kinetics, crystallography, and computer-aided structural analysis.</p> </div>',NULL,'BIO 349',NULL);
INSERT INTO course_descriptions VALUES(715,2022,1005,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/200/chin-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(716,2022,1006,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-230','<div class="desc"> <p>This course addresses the question: how can we understand the mind scientifically? We will explore answers to this question via a critical survey of neural and behavioral evidence bearing on the nature of core cognitive capacities, including perception, memory, emotion, decision-making, rationality, and consciousness. We will explore these sources of evidence in a comparative perspective, drawing on evidence of both human and (non-human) animal cognition, to more adequately characterize the general nature of cognition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(717,2022,1007,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-295','<div class="desc"> <p>This seminar will engage important topics and issues in Critical Theory and Social Justice. All CTSJ faculty will participate in order to facilitate an interdisciplinary engagement with complexities and nuances of these topics. Students from other CTSJ courses will be invited to participate in the construction of discourse around the topics. May be repeated for credit when offered with a different topic. Different topics may fulfill different Core Requirements.</p> <p><strong>Black Popular Culture // The Black Digital Age </strong></p> <p>This class is part of a series that takes up black popular culture as a social formation structured by both the shifting conditions of antiblackness and black objection in the 20th and 21st centuries. Rather than engage black popular culture as a representational form, the course queries the peculiarity of blackness’ cultural popularity within a society where black people remain disproportionately available to gratuitous violence and early death. As such, the course interrogates the ways in which the mainstream US popular culture economy is sustained by a deeply contradictory fascination with black bodies, black sociality, and black repertoires of performance within an antiblack society and argues that consumption of black life and black expressions is a modality of the ways in which blackness is put to use under white supremacy. The course is particularly concerned with how the audio-visual is a poignant site at which visual fixations on and pathologizations of blackness collide with black peoples’ expressions of objection, self-articulation, activism, and the forging of social space. In this light, this iteration of the course, queries the possibility of the “Black Digital Age” as the proliferation of black expressions within the 2010 to present moment in the audio-visual (TV, film, and videography, including Scandal, Moonlight, Insecure, Queen &amp; Slim, Native Son, Lemonade, When I Get Home, When They See Us, Fences, Random Acts of Flyness, and countless others) and social media (Youtube, Twitter, and Instagram) realms. We ask, what political, social, and historical developments in this moment have facilitated such a proliferation of black productions within the audio-visual; what is the social, political, and historical impact of these black productions; how have black artists reconfigured black visuality as a site of desire, pleasure, restitution, and power in the face of antiblack racism as visual degregation of blackness; and how might our social criticism and genuine engagement with these texts extend the project of black life, objection, and self-articulation in the face of ongoing antiblackness? Core Requirement Met: United States Diversity.</p> <p><strong>Social Movements/Representational Forms</strong></p> <p>In this course, we will examine the competing advocacy within social movements for documentary, fiction, journalism, lyric, abstraction, and other representational forms. For each social movement or political issue that we cover, students will compare multiple modes of representation, considering why they emerged, what their strengths and weaknesses were at each specific conjuncture, and what significance they have for future struggles. We will begin with some theoretical grounding and then proceed via a set of case studies. These may include: debates about realism vs. modernism in the Frankfurt school; testimonies in Latin America; confession vs. experimentation in feminist literature; reportage vs. the essay in journalism; and slogans, songs, and posters in queer activism.</p> <p><strong>Blackness, Gender, and Sexuality</strong></p> <p>In this course, students will deconstruct, critique, and reconsider our notions of “gender” and “sexuality” by thinking deeply, creatively, and rigorously about the ways in which blackness has been both central to modern conceptions of gender and sexuality and marked as the standard of sexual and gendered deviance. Students will consider “gender” and “sexuality” as historical, socially produced, and mutable categories that are co-constituted by structures of power including race, capitalism, and chattel slavery. Importantly, the course will focus on identifying the historical conditions and structures of power that have differently gendered black bodies in the Americas. By considering the particularities of black gendering, the course will identify how notions of gendered and sexual deviance and availability to antiblack violence have been central to producing black people as a population. Through concepts such as flesh, ungendering, availability, and queerness, students be able to unpack how black bodies are gendered in terms and social relations that are in excess of a binary and are not analogous to other racialized bodies. Finally, by looking at popular and cultural objects, the class will analyze how contemporary raced and gendered structures of power affect black people and communities. Core Requirement Met: United States Diversity.</p> <p><strong>Critical Theory and Psychopathology</strong></p> <p>This experimental interdisciplinary course considers the intersection of Critical Theory and psychopathology. The goal is to examine the ways in which central insights in Critical Theory might reorient our perspective on, and interventions against, mental disorders. By way of contemporary case studies, we will examine the directive to "care for the self" (Michel Foucault), the mandate "you must change your life" (Peter Solterdijk), the problems of death (Jacques Derrida), the work of forgiveness (Derrida), and the anguish of perversions (Georges Bataille). We will also re-read chronic pain (Friedrich Nietzsche), Generalized Anxiety Disorder (Sianne Ngai), Gender Dysphoria (Judith Butler), and Intermittent Explosive Disorder (Slavoj Zizek). We anticipate the emergence of a broader more powerful view of madness. Core Requirement Met: Global Connections.</p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(718,2022,1010,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-310','<div class="desc"> <p>As of late, religion has re-emerged on the political stage, offering different perspectives regarding political norms, values, and behavior. In this course, we will explore the various ways in which religion has been conceptualized and utilized in different political and cultural settings. Some of the questions that we will seek to answer are: in what ways can religion be separated from politics? What are the roles of religion and religious institutions in political life? How do religions and religious institutions respond to the challenges of a pluralist and secular modern world? Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(719,2017,1011,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/300/DWA-370','<div class="desc"> <p>This course investigates the contours of historical and contemporary debates about democracy in global politics. The central aim of the course is to make such terms as "pluralism" "representation" "freedom" and "democracy" which simultaneously serve as hollow tropes in contemporary political discourse and as the basis for a secular religious faith for many on the left and the right more difficult. Rather than cleansing these terms of their complications students are encouraged to see them from all sides interrogating their maddening paradoxes and ugly undertones while never losing sight of their awesome possibilities. Accordingly this course is divided into three sections. The first section offers a historical/philosophical overview of the rise of and a variety of challenges to the idea of democracy as both a political ideal and an institutional form from the advent of the American and French revolutions to today. The second section is devoted to various schools of thought on democratic governance with a special focus on post-World War II developments in democratic theory. The last section of the course focuses on contemporary politics of surrounding the discourse about and promotion of democratic values in a global context.</p> </div>','DWA 101',NULL,NULL);
INSERT INTO course_descriptions VALUES(720,2022,1012,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-410','<div class="desc"> <p>The abilities to locate, compile, synthesize, evaluate, and compellingly present complex and up-to-date knowledge on rapidly changing global issues - and to do so in a team - are highly valued across public, private, and civil society sectors. This course helps students learn and practice how to research, write, and present an extended policy-/practice-oriented report for a real-world client on a contemporary and exciting topic in World Affairs and practice being part of a high-functioning team. The topic and, thus, client will be unique each time the course is taught. The skills acquired and applied in Task Force help students stand out as they venture into the world and towards the jobs and activities they are passionate about in Diplomacy and World Affairs. This course may be repeated one time with permission of instructor.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(721,2022,1013,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-324','<div class="desc"> <p>This course examines the economic causes and consequences of immigration. The focus of the course will be on the United States'' experience. However, we will also examine aspects of other international migrations. The course will focus on the economic reasons that motivate people to migrate to other parts of the world, the labor market and fiscal impacts of immigration on sending and receiving countries, and the economic consequences of U.S. immigration policy choices.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(722,2022,1014,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/100/educ-145','<div class="desc"> <p>In this course, students will systematically examine the causes, challenges, and effects of several educational innovations in various school systems, from K-12 to higher education. The course will help students develop historical perspectives of schooling, critically examine the role and purpose of progress and innovation in our educational landscape in the United States, and understand how past, present, and future innovations impact our collective educational processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(723,2022,1015,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-219','<div class="desc"> <p>This course will analyze the educational infrastructure PK-16 pipeline to examine the nature of inequality. The following three areas will be examined: (1) theories of educational inequality, (2) research on inequality, and (3) policies of inequality. Students will gain a basic understanding of the theories of educational inequality as they relate to genetic, cultural, school, and societal perspectives, using critical theoretical lenses. Students will also examine the research addressing educational inequality, paying attention to designs, methods, and samples covered. And finally, students will analyze educational policies that either reproduce or eliminate inequalities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(724,2022,1016,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-365','<div class="desc"> <p>Psychological and political views of the "disruptive" female presence in literature, and in the critical theory of Derrida and Lacan. Works will range from 17th century fiction, to feminist writers including Beauvoir, Irigaray, and Cixous, as well as examples of women''s self-writing in the Francophone world. Taught in French and English. Counts for the French major and minor and for CSLC.</p> </div>','FREN 202; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(725,2022,1017,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-355','<div class="desc"> <p>This course is an introduction to the Earth''s ancient magnetic field and the magnetic properties of rocks. Students will learn how rocks acquire a magnetic signal and will explore how those signals relate to the structure of the geomagnetic field. Special emphasis is placed on collection of samples in the field and with special emphasis on laboratory techniques and applications. Strongly recommended for students considering research projects with Professors Bogue and Cromwell. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 or GEO 106 ','GEO 355L ',NULL);
INSERT INTO course_descriptions VALUES(726,2022,1018,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-355l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 355',NULL);
INSERT INTO course_descriptions VALUES(727,2022,1019,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-320','<div class="desc"> <br/> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into "new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the Humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. This course will meet three times a week, twice with CSLC 120, and a third weekly meeting in which all readings and discussion will be conducted in German. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(728,2022,1020,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-220','<div class="desc"> <p>This course provides an opportunity to vicariously "live" in historical cities considered to be creators of democratic or representative forms of government, as well as of great literature and art. Historian Thucydides, comic Aristophanes, and philosopher Plato draw us into Athenian gender/class socialization, politics, and culture; likewise, Boccaccio, the Medici family, and Machiavelli inform us of Florentine gender/class socialization, politics, and culture. Monumental architecture and gendered sculpture continue to serve to decorate and sustain the individuality of each city. By examining documents of daily life (including court cases concerning sexual acts) and the luxury products of the diverse crafts, we increase our knowledge of the controversial behavior and productivity of a wide spectrum of women and men. By focusing on two cities in their "golden age," the class will emphasize the shared positive, as well as negative, characteristics of ages historians have designated as "golden." History majors may petition for 300-level credit for this class with the completion of additional work arranged with the instructor. (May be taken as History 397 by writing a research paper in place of one class paper).</p> <p> <em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(729,2022,1021,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-328','<div class="desc"> <p>Ideas, politics, and society in 18th century Europe, especially France, where challenges to authority and tradition boosted confidence in reason and progress and eventually exploded the Old Regime. Particular attention will be given to the "republic of letters," of the philosophes whose mission was to bring about reform by "changing the common way of thinking." The role of women in this "salon" society will be examined, as will such controversial works as <em>Dangerous Liaisons</em> and the writings of the Marquis de Sade.</p> </div>','Satisfactory completion of at least one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(730,2022,1022,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-345','<div class="desc"> <p>This course will be a research seminar that confronts the history of the Holocaust through in-depth investigations into survivor testimonies and commemoration and memorialization. The course will examine the genocide of the European Jews by the National Socialist regime, introduce students to the history of Europe from 1919 to 1945, and raise questions about the moral and ethical legacies of the Holocaust. During the semester, we will use a variety of visual and written sources to document and analyze the systematic and bureaucratic murder of European Jews by the Nazis. Using the survivor testimonies archived at the USC Shoah Foundation Visual History Archive and the museum installation at the Museum of Tolerance, we will interrogate the emerging fields of witnessing and testimony in relationship to the memory of the Holocaust and the phenomenon of Holocaust commemoration and memorialization. We will ask questions about how individuals and society assimilated to the experience of genocide: what narrative choices, what linguistic choices, and what visual choices did survivors and the larger culture make when remembering and commemorating the Holocaust? In this way, the course will be interdisciplinary, combining the methods and sources of History, Jewish Studies, Cultural Studies, and Art History.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(731,2022,1023,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-352','<div class="desc"> <p>The logical foundation of the notion of a computable function underlying the workings of modern computers. Representation of the informal mathematical idea of calculability by canonical proxies: "general recursive functions," "Turing computable functions." Discussion of Church''s Thesis ,which asserts the adequacy of these representations. Survey of decidable and undecidable problems.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(732,2020,1024,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/200/musc-250','<div class="desc"> <p>This course deepens students'' exposure to techniques for analysis and composition in the style of eighteenth-nineteenth century common practice. We will study imitative genres and sectional forms (ternary, sonata, rondo), exploring chromatic extensions of diatonic practice. Students will engage in analytic and compositional projects in consultation with Music History faculty. Includes continued training in tonal sight singing, listening, and keyboard skills: introduction to chromaticism, related key modulations, modes, seventh chords; continued study of chord progressions and rhythmic studies.</p> </div>','MUSC 151/151A. Requires concurrent enrollment in MUSC 250A ',NULL,NULL);
INSERT INTO course_descriptions VALUES(733,2019,1027,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-290','<div class="desc"> <p>This course will explore foundational questions in the philosophy of art: What is art? Is there a quality or feature or function that all works of art share? How does art get its meaning? Does the artist or the viewer (or both or neither) determine the meaning of an artwork? (Why) do we value the authenticity or originality of an artwork? What determines whether something is a good work of art? Can art make us better (or worse) people? Can good works of art have morally bad properties? How can we be moved by fictions (that is how can we fear the monsters of horror films)?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(734,2019,1028,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-365','<div class="desc"> <p>We will look at a number of episodes in the history of science. Among the issues that will be addressed will be the following: When should we consider evidence as confirming a theory? What considerations should we use to decide between competing theories? Should we view our best theories as true or merely empirically adequate? Can there be a logic of scientific discovery? We will read works by philosophers and scientists including van Fraassen Reichenbach Feyerabend Newton and Galileo.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(735,2022,1029,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-208','<div class="desc"> <p>Examination of the impact that social protest movements have had on our society -and lessons that can apply to the current period. Case studies of the agrarian revolt (the Populists) the labor movement the women''s movement the civil rights movement the peace movement the student movement the environmental movement and the consumer/neighborhood movement. Topics include: What factors lead people to participate in social movements and political protest? Why do certain historical periods seem to feature large-scale protest and upheaval while others do not? How are social and political movements related to mainstream politics such as elections political parties voting and lobbying? What is the role of leaders activists and organizers? What strategies and tactics do movements employ? What does "success" mean for a protest movement? Do protest movements make a difference in achieving more social justice and changing public policy? In addition to classroom discussion attendance at a weekly film series is required.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(736,2022,1030,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-232','<div class="desc"> <p>This course is an undergraduate survey of the field of international political economy (IPE). It is intended as an introduction for students who already have some background in the field of international relations and are interested in exploring international economic relations at a deeper level. The course covers major theoretical empirical and policy perspectives. The theme to be explored in this course is "National Interest vs. Global Governance?" - that is we will explore the theory and history of international political economy as an extension of national interest and an arena for the development of global governance and the question of whether or not these two dimensions of international political economy are compatible or competitive with each other. The first part of the course will cover the basic concepts and theoretical foundations of IPE. The focus is on core theoretical principles and approaches. The goal is to understand how theory is framed and "works" the potential inferences of this theory and the issues of contention within the field. The second part of the course draws on the theoretical foundations to examine a set of specific international economic issue arenas including international trade finance and economic development.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(737,2022,1031,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-233','<div class="desc"> <p>This course is an introduction to international security and strategic studies. This field is fundamentally about both the use of force by and violent conflict among states and non-state actors. The course will be guided by general theoretical questions regarding security: How does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: How do states and non-state actors use force to persuade their enemies to take (coercion) or refrain from taking (deterrence) a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure the intensity duration and consequences of military action? We will have a particular focus on emerging transnational security issues intra-state security and the relationship among security development and state failure. Pursuing answers to these questions will require an approach that integrates theory history and current events.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(738,2022,1032,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-254','<div class="desc"> <p>This course will examine American political thought as it sets out and responds to the founding of the country. Specifically, we will read the Federalist papers, consider the impact of the American Revolution on the French Revolution, and explore how thinkers have reckoned with the American founding into the 21st century.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(739,2022,1035,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-145','<div class="desc"> <p>This introductory course uses two themes- experience and authority- to orient and guide students through an historical survey of religion in the United States. We will ask how people have made appeals to religious experience to establish, reinforce, and challenge political and religious authority. In addition to dominant forms of Protestant Christianity, we will learn about the rise of new religions like Spiritualism and Mormonism, Catholic and Jewish immigration in the late nineteenth century, and the growth of religions like Buddhism and Islam in the twentieth. Throughout the course, we will pay special attention to race and ethnicity, gender, and sexuality, asking how religion has alternately served as a vehicle for liberation and venue of oppression, and how religious debates dovetailed with the pressing social issues of the day.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(740,2022,1037,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-225','<div class="desc"> <p>This course provides an in-depth introduction to the traditions of Islamic mysticism. Students will explore the core teachings and practices of Sufism through the literary artistic and philosophical expressions of the great saints and masters of the tradition including figures like Rumi ibn Arabi Sohrawardi Mulla Sadra and al-Attar. We will situate Sufi thought and practice within broader Islamic thought and practice while attending to the unique modes in which Islamic mysticism has been institutionalized and transmitted.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(741,2017,1039,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/RUSN-Russian/200/RUSN-282','<div class="desc"> <p>The worldview and beliefs of the early Slavs particularly the Eastern Slavs were a complex synthesis of influences: Indo-European mythology Central Asian shamanism Scythian animal worship and ultimately a paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600 in order to understand how these people viewed the world and how this affected their lives and the development of Slavic culture. Communal village life legends folk genres and mythology their sources and their legacies are examined. There is a close study of the phenomenon of the vampire following its evolution from the Iron Age into eighteenth century Serbia as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined as well. In addition to analytical and historical texts readings include tales of supernatural beings and phenomena as well as testimony concerning encounters with the supernatural."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(742,2022,1040,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-395','<div class="desc"> <p>This course will function as an advanced seminar focusing on the research interests of the Sociology Department''s faculty. Topics vary.</p> <p><strong>Science, Technology, &amp; Justice: The Making of “Modern” Families</strong></p> <p>Does reproductive justice include a right to bear children using technological means? What about using 3<sup>rd</sup> parties like egg and sperm donors? Are reproductive technologies expanding definitions of family or reinforcing race, class, and gender inequalities? This upper-division seminar will examine reproduction from a social justice perspective, with particular attention to how the politics of reproduction are shaped by the intersecting inequalities of gender, race, class, dis/ability, and sexuality. Reproduction is not only a biological process; it is a battleground of social and political struggle. The course will familiarize students with foundational academic and activist approaches to reproduction. Students will learn about the history of and differences between reproductive rights and reproductive justice movements. We will then look at the new questions and challenges reproductive technologies raise for social justice. Cross Listed as UEP 395.</p> <p><strong>Policing, Power, and Violence</strong></p> <p>In this course, we will examine policing in the United States from the repression of Indigenous and enslaved peoples in the 18th century to the militarization of policing on the streets and the U.S.-Mexico border today. Using sociological understandings of power, we will analyze the judicial and extrajudicial violence that law enforcement agents engage in and how such violence serves to maintain the unjust and unequal social order. The course will close with us considering arguments for and against the abolition of police forces and prisons.</p> <p><strong>Sociology of the Southern U.S.</strong></p> <p>What, and where, is the South? Who is a southerner? What do they do down there, and why do they do what they do? Are the South and southerners still distinctive? By looking at all aspects of Southern life this course will unravel the enigma of the region while pondering a more inclusive and nuanced appreciation of "many Souths" and "southern cultures" including senses of regional identity and allegiance, and in representations of, and cultural stereotypes from and about, the South. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> <p><strong>Visualizing Gentrification: Bridging Land Use Data and Ethnography</strong></p> <p>Students are challenged with the myths and realities of gentrification in an immersive discussion. The proposed course weaves urban planning, mapping and data research with qualitative analysis to recognize gentrification drivers, examine the pending experiential trauma of displacement and the community''s aspirations and resistance. The course examines the communities of Northeast Los Angeles as they face three colossal planning projects that utilize gentrification as a catalyst and justification for their development.</p> <p>In a holistic examination of the landscape, course participants will embed with community and other partners to explore the social networks and their relationship to research data. Course discussions will include developing metrics from an activist and documentary perspective to establish the observable community. Students will operate in small teams in developing data and fostering outcomes that reveal the human narrative. They can be visual in nature from ethnographic studies to data visualization, but also critical analysis and policy recommendations of the conditions on the ground. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> </div>','SOC 101, SOC 102 or SOC 105 are prerequisites ',NULL,NULL);
INSERT INTO course_descriptions VALUES(743,2022,1042,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-248','<div class="desc"> <p>We introduce students to the theory and application of sound and music as elements of design for theater dance and other collaborative multimedia dramatic forms. Throughout the semester we address fundamental issues of sound design: including script analysis conceptual approaches to sound music underscoring working with audio equipment and sound editing. Over the semester our students learn how to work within a creative team of designers coordinating the many design elements of various dramatic forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(744,2022,1043,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/300/arab-302','<div class="desc"> <p>This is a continuation of Arabic in the Media I.</p> </div>','ARAB 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(745,2022,1044,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-278','<div class="desc"> <p>An exploration of art, architecture, and visual culture created within the context of Muslim-majority or Muslim-ruled societies within Western Asia, North Africa, and Europe from the 7th to the 21st centuries. Covers sacred and secular architecture and architectural decoration, sculpture, painting, manuscripts, textiles, and metalwork, including objects in Los Angeles area collections. The course also considers theoretical framings of the field, such as what is “Islamic” about Islamic art. We will also consider the circulation of Islamic art globally and the emergence of modern Islamic art, as well as the visual cultures of protest in contemporary Muslim-majority countries. Readings will include primary sources, exhibition catalogs, and scholarly articles; visits to museums and a mosque is anticipated. By the end of the course, students will be able to demonstrate knowledge of the diversity of Muslim arts historically and geographically. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(746,2022,1045,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-376','<div class="desc"> <p>High Renaissance and Mannerism. Among the artists considered are Leonardo da Vinci, Michelangelo, Titian, and Raphael. Of special consideration is the nature of the Papacy, as a patron of art, and the city of Rome, as a context for artistic activity. The course will also consider the reasons for the dissolution of the classical tradition during this time by artists such as Pontormo, Parmigianino, and Giulio Romano.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(747,2022,1048,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/300/arts-330','<div class="desc"> <p>Advanced study in printmaking including developing a theoretical, historical, and critical understanding of photo-based materials and media, including images on pronto plates and monotypes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(748,2022,1049,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-268','<div class="desc"> <p>The application of statistical methods to the solution of biological problems. Focus will be on applied statistics (as opposed to mathematical statistics) to study variation in nature. This course will survey descriptive statistics, probability and probability distributions, and methods of hypothesis testing (e.g. analysis of variance, regression correlation, goodness of fit, as well as selected nonparametric procedures). <em>Course includes laboratory workshops sessions.</em></p> </div>','BIO 130 and BIO 105, BIO 106, BIO 110 or BIO 115; or permission of instructor ','BIO 268L ',NULL);
INSERT INTO course_descriptions VALUES(749,2022,1050,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-275','<div class="desc"> <p>Identification and classification of plants found in the various vegetational communities of Southern California, with emphasis on understanding their ecological and evolutionary affinities. Current methods of field sampling and systematic analysis will be employed. <em>Includes one three-hour laboratory per week and other field trips to be arranged.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 275L ',NULL);
INSERT INTO course_descriptions VALUES(750,2017,1051,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-275L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(751,2022,1052,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-344','<div class="desc"> <p>The structure and functional organization of animal-like protists and invertebrates are examined as adaptations to life in specific habitats. The current use of these organisms in applied systems, such as aquaculture, and as models to study basic biological processes is discussed. Marine organisms and parasites are emphasized. The phylogenetic relationships between taxa are also debated. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130; and BIO 105 or BIO 115; or permission of instructor ','BIO 344L ',NULL);
INSERT INTO course_descriptions VALUES(752,2022,1053,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-344l','<div class="desc"> <p>Field and laboratory exercises designed to: (1) further expose students to invertebrate diversity; (2) examine and experiment with physiological processes such as locomotion, nutrient allocation, excretion, sensory function, and reproduction; (3) introduce parasite life cycles and parasite-host interactions; and (4) understand animal relationships based on morphological and molecular evidence. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 344 ',NULL);
INSERT INTO course_descriptions VALUES(753,2022,1054,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-360','<div class="desc"> <p>Avian Biology is the study of birds, with particular emphasis on identification, natural history, and evolution of birds local to Southern California.</p> </div>','BIO 130 and BIO 105, BIO 106, BIO 110, or BIO 115 ','BIO 360L ',NULL);
INSERT INTO course_descriptions VALUES(754,2022,1055,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-360l','<div class="desc"> <p>Laboratory techniques in Avian Biology. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 360',NULL);
INSERT INTO course_descriptions VALUES(755,2022,1056,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-380','<div class="desc"> <p>An introduction to the study of organic synthesis.</p> </div>','CHEM 300 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(756,2022,1057,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/300/chin-310','<div class="desc"> <p>Advanced reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Oral presentations, academic style discussions, and writing of essays and narratives.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(757,2022,1058,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/300/chin-330','<div class="desc"> <p>A survey of representative works of short fiction and film by 20th century and contemporary Chinese writers and film makers. Topic and content of the course will vary from year to year according to three areas of focus: mainland China, Taiwan/Hong Kong, and transnational Chinese. Students will read and view original works and practice oral and written summaries, commentaries, discussion, and analyses in Chinese. Students will also read essays on literature and film in Chinese, with some readings in English. This course may be taken three times.</p> <p><strong>Female Who Writes and Who is Written</strong></p> <p>This course will examine the relationship between culture and society in China by focusing on the images of women represented in modern and contemporary cultural production, including literary and cinematic texts. By investigating the images of women in both literature and cinema from the twentieth century onward, this course will explore the development and transformation of the status of women in different sociohistorical periods of China, and discuss the ways in which cinema and literature feature women to address issues of gender, family, society, national identity, cultural memory, and so forth. In addition to representative literary texts, students will develop skills to interpret and analyze audiovisual media by watching the film adaptations of the assigned literary texts, and discuss how literary texts and cinematic media have both been used to construct and shape the cultural scene in Chinese society. <em>Core Requirement Met: Regional Focus</em></p> </div>','CHIN 301 (or above) or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(758,2022,1059,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-330','<div class="desc"> <p>Language and cognition are intimately related. For this reason, Linguistics has had an extremely strong influence on Cognitive Science. This course studies language and linguistics in the context of Cognitive Science. We will address such questions as: how are language and thought related? How is language represented in the brain? How do we process language? To what extent is the human capacity for language innate? Is there a language of thought? What are the best ways to model language acquisition and language processing? We will cover some topics in traditional Linguistics and we will look at current research on connectionist and traditional artificial intelligence approaches to modeling language. Reading will include work by Chomsky, Pinker, McClelland, Rumelhart, Fodor, and Elman.</p> </div>','COGS 101 or LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(759,2022,1060,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-180','<div class="desc"> <p>Stupidity is neither ignorance nor organicity, but rather, a corollary of knowing and an element of normalcy, the double of intelligence, rather than its opposite. It is an artifact of our nature as finite beings, and one of the most powerful determinants of human destiny. Stupidity is always the name of the Other, and it is the sign of the feminine. This course in critical psychology follows the work of Friedrich Nietzsche, Gilles Deleuze, and most recently, Avital Ronell, in a philosophical examination of those operations and technologies that we conduct in order to render ourselves uncomprehending. Stupidity, which has been evicted from the philosophical premises and dumbed down by psychometric psychology, has returned in the postmodern discourse against nation, self, and truth, and makes itself felt in political life, ranging from the presidency to Beavis and Butt-head. This course examines stupidity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(760,2022,1061,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> <p><strong>Axes to Praxis: Music as Activism</strong></p> <p>This course aims to provide students with an understanding of the role of music in creating social change. Students will listen to the structure and content of songs and discuss how they can spark critical thought and become a catalyst for political action. The students will also explore how live musical experiences contribute to community building. Traditional, as well as contemporary musical styles, will be examined with an emphasis on the music of women, the LGBTQA community and people of color. We will learn about the contribution of artists and activists whose ideas have propelled society forward.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(761,2022,1062,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-259','<div class="desc"> <p>This course examines movements of bodies through political, legal, economic, and social exchanges. Drawing from a variety of materials (theory, literature, film), the course examines practices such as: human trafficking, organ transplantation, transnational adoption, and surrogacy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(762,2020,1063,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-332','<div class="desc"> <p>Sigmund Freud''s intervention in personal sexual life often overshadows how psychoanalysis uniquely theorized violence in the context of two world wars. This course will consider how contemporary social justice issues might be informed by psychoanalytic concepts, including: aggressivity, group identification, neighbor relations, and altruism. Readings include: Freud''s <em>Civilization and Its Discontents,</em> <em>Beyond the Pleasure Principle,</em> and key essays; Franz Fanon''s anti-racist masterpiece <em>Black Skin White Masks</em>; Melanie Klein''s studies of negative affect; queer theory''s relation to the death drive; and essays by contemporary critical theorists grappling with the ongoing problems of war, racism, class conflict, and sexual violence.</p> </div>','Any 200-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(763,2022,1064,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-395','<div class="desc"> <p>An advanced seminar in Critical Theory and Social Justice. May be repeated for credit with a different topic. <em>Different topics may meet different requirements.</em></p> <p><strong>Writing Trauma</strong><br/> This is a writing-intensive course with a focus on marginalized identities and social justice. It examines the process of writing with, about, and through trauma. During the semester, we will investigate the origins of trauma through a social justice lens and how writing can be a transformative political act. We will examine trauma and writing as they pertain to current events. Critical writing is an integral part of this course.</p> <p><strong>Indigenous Literature as Decolonial Praxis</strong></p> <p>This course will examine Indigenous literature as a form of political cultural production. Using settler colonialism as a context, the texts under examination will be understood as assertions of Indigenous sovereignty. As a result, readers'' will come to understand Indigeneity and Indigenous peoples more broadly. By examining primarily 20th and 21st century texts, a contemporary view of Indigenous epistemologies, including ideas of belonging, kinship networks, violence, etc., and social justice struggles will emerge as relevant to current decolonial efforts. <em>This class counts as a methods class for the CTSJ major.</em></p> <p><strong>White Queer Theory</strong></p> <p>This course critiques the ways in which queer theory and politics of the late 20th and 21st century have been a profound site through which whiteness has been able to reproduce and proliferate in the context of the neoliberal incorporation of raced, sexed, gendered difference into structures of capitalism and the US nation-state. As such, students will engage both the so-called critical texts of white American queer theory and texts from queer indigenous studies, black queer studies, women of color feminisms, and queer of color critique along with the burgeoning fields of black trans studies and trans of color critique that have rigorously critiqued the limits of the so-called critical texts to think [critically] about their reproduction of whiteness and the ways in with their thinking of queerness does not encapsulate the ways in which indigeneity, blackness, and other racialized formations are marked as sexually deviant, non-heteronormative, and queer, both as sexual identities and as populations. In order to thoroughly interrogate these proliferations students will engage a variety of texts that include theory, history, political movements, and popular culture — texts include the work of Foucault, Judith Butler, Glee, Paris is Burning, #ItGetsBetter, the phenomenon of Milo Yannopoulos (aka Milo Hanrahan), Christine Jorgensen, and the white queer antiblack backlash against the simultaneous passing of prop 8 in California and the election of Barack Obama as the first president; and the work Cathy Cohen, Qwo-Li Driskill, Jasbir Puar, Scott Morgensen, C. Riley Snorton, Roderick Ferguson, and other scholars who have reframed questions of queerness and its intersections with whiteness, settler colonialism, and racial capitalism through frameworks such as homonationalism, settler homonationalism, trans necropolitics, and the queerness of blackness. <em>This class counts as a methods class for the CTSJ major. </em>Core Requirement Met: United States Diversity.</p> <p><strong>Whiteness</strong></p> <p>This course seeks to engage the emergent body of scholarship known as Critical White Studies (CWS). This scholarship is designed to deconstruct the racial category “white.” We will examine the historical, legal, economic, gender, and aesthetic constructions of whiteness. Particular attention will be paid to the problem of blackface. We will also critically examine CWS. Core Requirement Met: United States Diversity.</p> <p><strong>Chattel Slavery and Its Afterlives</strong></p> <p>This course introduces students to the key theoretical and historical frameworks that elucidate the particularities of chattel slavery in the Americas both in its “pre-emancipation” manifestations and as, Saidiya Hartman notes, the ongoing machinations of captivity, domination, and dispossession by which antiblackness continues to structure and suture the world. In this course, the particularity of chattel slavery emphasizes how the economic and social function of the enslaved as laborer and commodity, the centrality of blackness as a fungible and immutable category of the enslaveable (non)human, and the massive global function of chattel slavery as the foundation of capitalism distinguishes this formation from other historical or regional structures of slavery, labor exploitation, trafficking, and racialized domination. Furthermore, students will be challenged to confront the ways in which the de jure abolition of chattel slavery (in 1865 in the US and across the Americas in the 19th century) has been a historical, legal, and structural misnomer that does not capture the ways in which societies, economies, and legal structures adapted to sustain rather than eradicate the global dependence on black subjection. Students will engage the prison industrial complex, abandonment &amp; deindustrialization, policing, geographic containment, the consumption of blackness as popular culture, formations of neoliberalism, and antiblack state and state-sanctioned terror as contemporary formations of chattel slavery’s afterlives. The course engages the geographic contexts of the US, Jamaica, Haiti, and other parts of the Caribbean. Cross-listed as BLST 375. <em>This class counts as a methods class for the CTSJ major. </em></p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(764,2022,1066,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-284','<div class="desc"> <p>A critical examination of the political and economic role that sports play in the globalized world - the diplomatic, political, and economic effects of the Olympics, the World Cup, other international sporting events, and the increased globalization of professional sports leagues across national boundaries. A look at case studies of ping-pong diplomacy, rugby reconciliation in South Africa, and soccer wars in Latin America, as well as an analysis of the impact of foreign players on national economies and societies, from American baseball players in Japan, to Russian ice hockey players in the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(765,2022,1067,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-329','<div class="desc"> <p>Trafficking in persons - the use of force, coercion, fraud, or deception for purposes of exploitation - is the third most profitable form of illicit activity, globally, following the traffic in drugs and arms. In this course, we will explore the different forms of trafficking, including domestic servitude, sweatshop labor, migrant agricultural work, and child soldiering, although the course will focus most closely on the topic of trafficking for purposes of sexual exploitation. Throughout the class, the causes, consequences, and responses to trafficking will be analyzed through a human rights lens. We will study the processes behind the construction of gender identities in order to gain insight into why particular populations are especially vulnerable to trafficking, and why certain constraints exist to prevent and respond to trafficking at both the domestic and international levels. We will study the relationship between trafficking and militarism, including the legacy of the United States'' military presence in Asia for sex tourism, and trafficking in the region today. And we will engage the debate over whether trafficking is a "discourse" that perpetuates relationships of dominance and subordination between the global North and South. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(766,2022,1068,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-338','<div class="desc"> <p>The place of human rights in the transnational Muslim world in comparative and theoretical perspective. The focus will be on 20th century political and ideological events in the Muslim world broadly defined to include its diverse formations. There will be particular attention paid to movements for the integration of human rights into domestic, international, and transnational politics, and attendant theoretical questions. The course will be reading-intensive and we will focus class discussions around each week''s readings. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(767,2022,1069,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-314','<div class="desc"> <p>This course examines the historical development and the role of institutions underlying market economies. It discusses the many forms which institutions (i.e. social norms, laws, and regulations) affect economic behavior and performance. Based on examples from United States and European economic history, topics will include: contract enforcement; trading institutions; political institutions; financial institutions; property rights in land and environmental resources; regulation of labor and capital markets; and the origin and development of one of the most important economic institutions, the firm. We will pay particular attention to institutions that emerged in response to market failures and to the changing nature of economic institutions over time.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(768,2022,1070,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-363','<div class="desc"> <p>The course is an exploration of various literary and cinematic representations of the French colonial history and its impact on the peoples of the Maghreb and West Africa. It examines narratives of war, dominion, racism, and collaboration. Films and literary texts examined include: <em>Les Indigènes </em>(Rachid Bouchareb); <em>Le Camp de Thiaroye</em> (Ousmene Sembene); <em>Le Vieux Nègre et la Médaille </em>(Ferdinand Oyono); and <em>Meursault, contre-enquête</em> (Kamel Daoud).</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(769,2020,1071,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/geo-geology/300/geo-390l','<div class="desc"> <p>Weekly three-hour laboratory in conjunction with GEO 390 Special Topics in Geology.</p> </div>',NULL,'GEO 390',NULL);
INSERT INTO course_descriptions VALUES(770,2022,1072,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-183','<div class="desc"> <p>This is a survey course in which we will explore the political and socio-economic history of the Middle East from the beginning of the Ottoman reforms of the 1830s until the present. Our aim is to provide a comprehensive overview and analysis of the events of the past two centuries. In addition to the Ottoman reform period, we will look at the rise of Mehmet Ali in Egypt, the incorporation of the region into the world economy, WWI and its continuing legacies in the region the development of the Arab/Israeli question, the revolutions of the 1950''s and the populist regimes they brought to power, the crisis in Lebanon, the Iranian Revolution, the war between Iran and Iraq, and the Iraqi invasion of Kuwait. We will also consider some of the principal features of the economy of the region: agriculture and land reform, oil and state, and labor migration from poor states to richer ones.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(771,2022,1073,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-235','<div class="desc"> <p>This course examines the history of modern Europe with a focus on popular and state-supported ideologies of exclusion and violence in the long 20th century (spanning 1890-2011). Central to this course is a focus on the discursive boundaries of civil society based on race and class. Throughout the course, we situate European developments in a world-historical framework as a way to understand the increasingly interdependent political, social, and economic relationships between Europe and the colonial periphery. We begin in fin de siècle Europe, and trace the polarization of national politics and the development of the contending state ideologies of fascism and communism. We explore the consequences of various programs of decolonization, as well as the popular revolts against cultural diversity and post-colonial immigration to the metropole. The course also investigates the origins and consequences of the neo-liberal "revolution" of the 1980''s, the ethnic violence stemming from the disintegration of the Soviet Union and eastern bloc nations, and the return of the radical right throughout Europe in the 1990''s. Our course readings combine secondary and primary sources, literature, as well as a wide range of cinematic and musical sources, in order to understand the evolution of European notions of race, national belonging, and political violence.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(772,2022,1074,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-246','<div class="desc"> <p>According to legend, the Korean people were born from the union of the son of the "Lord of Heaven" and a bear-woman, with a good measure of garlic and mugwort aiding the process. From these mythic origins, tracing roughly 2,000 years of Korean history, we will end with the forced opening of the Korean peninsula and people in the mid-19th century. The main objective of this class is to impart an understanding of the major social, cultural, political, and intellectual developments that occurred along the way.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(773,2022,1075,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-382','<div class="desc"> <p>Graph Theory is a beautiful area of mathematics with many applications. It is used in computer science, biology, urban planning, and many other contexts. Like other areas of discrete mathematics, Graph Theory has the property that the problems are often quite approachable and understandable. Sometimes the solutions to Graph Theory problems can be complex and often require clever arguments, thus the subject is quite pleasing to study. This class will build a solid foundation in Graph Theory for the students. Possible topics are: graph isomorphisms, coverings, and colorings; independence number, clique number, connectivity, network flows, and matching theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(774,2022,1076,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-117','<div class="desc"> <p class="sc-BodyText">This course will survey film music from its silent film era origins to the present focusing on its many functions through in-class viewing analysis and critique of film clips. The works of many prominent film composers as well as some lesserknown figures will be examined in terms of style and approach as well as their own views on the film-scoring process. Fundamental information on music film and psychology of music will be introduced and the role of music in other media (such as TV and experimental video) will be explored.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(775,2019,1077,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-240','<div class="desc"> <p>This course will philosophically examine the concept of race and the way race informs identity. Topics include the reality of race the origins and nature of the concept and the extent to which race does and should impact our social and personal identities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(776,2019,1078,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-255','<div class="desc"> <p>This course will examine the nature of environmental values and their role in decisions and public policies concerning environmental protection. Some of the questions we will address include: What is the relation between the environment and human health and well-being? Are there reasons other than human health and well-being for protecting the environment? How do we compare environmental values against other values in making reasonable decisions? What are the ethical issues involved in cost-benefit analysis? What are our duties to future generations and non-human animals?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(777,2019,1079,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-355','<div class="desc"> <p>The course will cover such topics as whether space and time exist how we know what the geometry of space and time is whether any sense can be made of the claim that time has a direction and the "paradoxes" of time travel. We will examine these questions in the context of both pre-relativistic and relativistic theories. The readings will range from historical figures such as Newton Leibniz and Mach to contemporary work by both philosophers and physicists including Hawking Thorne and Sklar. This course does not require previous exposure to Special or General Relativity and will not require as a prerequisite technical skills that go beyond high school mathematics and physics but the student is expected to be comfortable with algebraic and geometric reasoning.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(778,2019,1080,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-380','<div class="desc"> <p>Ludwig Wittgenstein (1889-1951) is a central figure in the two most important philosophical traditions of the twentieth century: First the attempt early in the century to characterize language thought and the world in terms of the newly available formalism of modern logic and second the attempt to show that any such formalization will fail to do justice to the rich complexity of language as a form of life a form inseparable from the social and historical context from which it springs. We will examine two principal works the <em>Tractatus Logico-Philosophicus </em>and the <em>Philosophical Investigations</em>. There will also be some treatment of the historical and philosophical context of Wittgenstein''s work and life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(779,2022,1081,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-164','<div class="desc"> <p>Identical in all respects to PHYS 165 except that there is no lab component. Students attend regularly scheduled lectures for PHYS 165, do the homework, and take the PHYS 165 exams.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(780,2022,1082,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-235','<div class="desc"> <p>This course focuses on the evolution of U.S. foreign policy in recent Administrations with special emphasis on the post-Cold War period. Attention is paid to American policy toward "emerging issues" for example the global environment development policy in the North/South dialogue ethnic violence and nationalist civil wars human rights and humanitarian relief. It explores how policy is formulated and implemented and analyzes the relationship of foreign policy to American economic and defense policies. It examines U.S. policy toward major regional power configurations-in Europe the Far East Latin America the Middle East South Asia and Africa.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(781,2022,1084,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-347','<div class="desc"> <p>Understanding how the law has defined race is of critical significance to the study of politics and the experience and history of race and race relations in America. The course examines definitions of race within legal precedent and how the law has created racial identities. The course considers the relationship between race and law in many different manifestations from the colonial period to the present day to understand theses complex intersections.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(782,2022,1086,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-403','<div class="desc"> <p>A study of the relation between psychological states and processes (cognition learning emotion psychopathology) and physiological response processes (autonomic nervous system responses covert muscle activity EEG FMRI). <em>Includes six three-hour laboratories per semester.</em></p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 200 or COGS310; and PSYC 322, PSYC 306, PSYC 330, PSYC 301, PSYC 448 or permission of instructor ','PSYC 403A <div id="offered"></div>',NULL);
INSERT INTO course_descriptions VALUES(783,2022,1087,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-232','<div class="desc"> <p>A study of the development of the religion of ancient Israel and its expression in the Hebrew Bible. Special emphasis will be placed on the emergence of the central ideas of Biblical religion which formed the foundation for early Judaism and in time of Christianity and Islam. In addition to close reading of selected Biblical texts in translation attention will be paid to the historical context in which ancient Israel lived and to the findings of modern critical scholarship and archeology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(784,2022,1088,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-240','<div class="desc"> <p>In this course we will explore the relationship between religion and revolution through a series of case studies from across the Americas. In 1907, a wealthy Mexican landowner named Francisco Madero regularly channeled the spirits of the dead. They instructed him to write a book advocating for democratic reform, which helped ignite the Mexican Revolution of 1910 that led to Madero''s being elected president. In 1930s Jamaica, the Rastafari movement emerged as a potent political force that raised black consciousness and challenged colonial British rule. And in the mid-century United States, a spiritually awake counterculture challenged the status quo and redefined the cultural trajectory of postwar America. Using these case studies, we will ask how religions - through prophesy, apocalypticism, and messianism - can unsettle even seemingly secure polities, as well as how religion can function to maintain the status quo.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(785,2022,1089,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-290','<div class="desc"> <p>The modern-day New Testament contains only a portion of the literature (i.e. gospels acts epistles and apocalypses) written by early Christians. This course will provide students the opportunity to study many of the texts that were not included in the Christian canon: the so-called apocrypha." We will investigate the process by which the Christian canon was formed how and why some texts that were beloved by many ordinary Christians were excluded from the canon by church officials and how the ideological and theological positions found in the rejected texts give us a lens into some of the most heated debates in early Christian communities. In addition to surveying apocryphal texts and their early Christian contexts the major assignment of the course will be to collaborate with Prof. Upson-Saia on her current research project: a study of how ideas found in the New Testament Apocrypha persist in Catholic tradition-specifically in Catholic doctrine art and liturgy-even though the texts themselves were excluded from the Christian Bible." <em>Open to Juniors and Seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(786,2022,1090,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/300/rels-351','<div class="desc"> <p>This course will survey the variety of ways early Christians defined and regulated sexuality, such as the function and purpose of sexual intercourse, same-gender intercourse, contraceptive practices, abortion, polygamy, monogamy, celibacy, and the normative "Christian family." We will analyze how opinions on such topics were as profoundly social, political, and economic as they were religio-ethical. From this analysis, we will better understand how modern (religious and secular) attitudes have been shaped by -- as well as diverge from -- the Christian sexual ethics of antiquity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(787,2022,1092,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-260','<div class="desc"> <p>In this course we will focus on sociological theories of deviance with an emphasis on how behaviors and identities are socially constructed as deviant (both today and historically). We will then turn our attention to major forms of deviance as typically defined in Western societies: criminal deviance "victimless crimes" and individuals with stigmatized identities. Throughout the course we will work to understand the complex relationship between social actors and audiences in defining deviance; the nature of social control in responding to deviance; and the experiences of "deviant" individuals.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(788,2022,1093,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-285','<div class="desc"> <p>The relationship between humans and the non-human environment is complex and problematic. We are part of and dependent upon the natural environment even while altering that environment for our own needs and purposes. As a way of broadly thinking about these interactions we will address the social causes consequences and responses to environmental disruption. By the end of the course you will be more adept at understanding how societal characteristics -- including cultures traditions beliefs values institutions and the like -- combine with environmental conditions to shape the impact that people have on their environments.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(789,2022,1094,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-315','<div class="desc"> <p>This course uses different sociological perspectives to examine social aspects of schooling and educational institutions in the U.S. Specifically the course focuses on factors that may impede and/or facilitate learning such as social class gender race and ethnicity teacher and parental expectations and peers. Additionally the role of education in the acculturation and assimilation process is considered as are the ways in which schools ameliorate and/or replicate social inequalities.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(790,2022,1095,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-301','<div class="desc"> <p>General survey of Pre-Columbian civilizations and literature of Meso and South America the impact of the Discovery the Conquest the Colonial Period and the processes leading to the Independence and the formation of the new Republics. Literary and historical readings compositions and short essays and presentations will be used to continue developing language skills.</p> </div>','SPAN 202, SPAN 211, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(791,2022,1096,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-312','<div class="desc"> <p>This course surveys the history of Spanish film from its inception to the present. The course introduces students to basic concepts of film studies including cinematography mise-en-scÃ¨ne sound narrative and style but emphasizes representation and in particular depictions of gender sexuality and national identity in the context of dictatorship and democracy. The course further introduces students to the auteurist tradition in Spanish cinema. The films studied vary from year to year but the course typically highlights the cinematic production of Luis BuÃ±uel Carlos Saura and Pedro AlmodÃ³var.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(792,2022,1097,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-341','<div class="desc"> <p>This course consists of an introduction to historical Hispanic linguistics. Students learn about the major phonological morphosyntactic and lexical changes that have occurred in the language from the time of the arrival of the Roman armies into the Iberian Peninsula until the present. Foreign influences on the evolution of the Spanish language are discussed briefly. The primary focus of this course is the internal history of the language from Vulgar Latin to Modern Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(793,2022,1098,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-363','<div class="desc"> <p>This course will apply current theories of autobiographical discourse to Spanish Latin American and U.S. Latino life-writing. Students will examine the relation of personal identity to dominant ideologies of gender race class and politics and will explore the role of memory and fantasy in literary self-expression. Authors studied will vary from year to year but will typically include Gloria AnzaldÃºa Reinaldo Arenas Juan Francisco Manzno Carmen MartÃ­n Gaite Rigoberta Menchu Constancia de la Mora and Mario Vargas Llosa. Students will have the opportunity to write their own autobiographies.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(794,2017,1101,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/THEA-Theater/200/THEA-240','<div class="desc"> <p>We move students further along in the study of movement covering the diverse Caribbean region from Cuba to Puerto Rico Jamaica and Trinidad and Tobago. As students develop a body of choreographic work they will learn improvisational techniques for soloing along with the place and importance of the Yoruba-based pantheon in the work. Matching specific dance steps to specific drum rhythms students learn to sing Yoruban songs as they perform the dances. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','Two semesters of THEA 140 or permission of the instructor',NULL,NULL);
INSERT INTO course_descriptions VALUES(795,2022,1102,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-250','<div class="desc"> <p>Period style can be characterized as the aesthetic traits common to a particular historic or cultural moment. For recorded media and live performance, writers, directors and designers set their storytelling in a framework of time and place. In this class, we explore examples of shifting styles across select non-Western and Western cultures and through time and seek to discern their influence on other cultures or historical periods. Through this exploration, we begin to understand how architecture, interior design, fashion history and the act of dressing evolved throughout the centuries and across cultures because of technological advancements, changes in economic and social class structures, in political climates and through appropriation of cultural aesthetics. Why was there a kimono specialist in the costume department of <em>Westworld</em>? How did Ruth E. Carter develop her Afrofuturist vision for <em>Black Panther</em>? Where would you find visual and dramaturgical resources for <em>Vietgone</em>, or <em>Hair</em>, or <em>Cambodian Rock Band</em>, the action of each set in a similar historical period but whose stories are told from very different cultural perspectives?We will investigate these and other questions through reading, and critical analysis of visual records, plays and films, in-class discussions, and presentations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(796,2022,1103,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-214','<div class="desc"> <p style="margin-left:0px; margin-right:0px">The struggle for control of our public education system in Los Angeles has become one of the most high profile conflicts facing the city and its residents. The stakes couldn’t be higher. The lives of children and the hopes and dreams their parents literally hang in the balance. In UEPI 214, Professor Steve Zimmer, a long-time teacher and the former President of the Los Angeles Unified School District Board of Education, will guide students through a journey in understanding the role of public education in our society and tensions over different visions and goals for public schools, including its mission to promote equality, equity, and mobility. The course will also explore how public policy can help or hinder public school’s equity mission. The class will examine the effects of expanding racial and economic segregation, increased standardized testing, and toxic stress have on students trying to pursue their dreams and the teachers trying to make those dreams come true. The class will also assess the impact of teacher tenure reform, the expansion of charter schools, the community schools movement and other policy based debates that could influence the future of teaching and learning. Through guest lectures, panels, films, and readings, students will understand the role that policy and collective action can play in pursuing a collaborative agenda. The final project will involve actually writing policies to be presented to the Board of Education and/or other policy makers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(797,2019,1104,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/ARAB-Arabic/200/ARAB-252','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Arabic feature film.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(798,2022,1105,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-373','<div class="desc"> <p>Painting, sculpture, architecture, and urban planning of Michelangelo Buonarroti. This course considers the development of the artist, from his apprenticeship in the shop of Domenico Ghirlandaio, through his late paintings in Rome. All works are considered for their stylistic, iconographic, and social context. Particular attention will be paid to the urban and specific patronage context of each work, which is critical in order to develop a more complete understanding of Michelangelo''s art and intellectual development. This course requires travel to Italy during the winter break.</p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(799,2020,1106,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/bio-biology/300/bio-326','<div class="desc"> <p>This course focuses on how to build the tree of life from DNA data, from how DNA evolves to how DNA mutations are analyzed to create phylogenies. Topics covered include the theory behind molecular evolution and various analytical methods, as well as its application to creating evolutionary histories of genes and organisms.</p> </div>','BIO 280 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(800,2022,1107,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-326l','<div class="desc"> <p>Laboratory sessions will involve hands-on generation of DNA data in the molecular lab as well as its analysis via a broad suite of modern software. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(801,2019,1110,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/CTSJ-Critical-TheorySocial-Justice/100/CTSJ-101','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(802,2022,1111,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-210','<div class="desc"> <p>Why did the London Bridge fall down? Is Rub-a-Dub-Dub really about bath time? Why didn''t an old man live in a shoe? Who is more imperialist Babar or Peter Pan? Is Tinky Winky gay? Is South Park a children''s show? Is Harry Potter a Hero? How tired was Rosa Parks? Using different critical approaches this course will examine children''s poetry, picture books, novels, cartoons, feature films, and music videos. Analysis will include topics related to gender, race, culture, and nation as they play out in the aesthetics, images, and poetics of children''s texts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(803,2022,1112,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-215','<div class="desc"> <p>This methods seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(804,2020,1113,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-233','<div class="desc"> <p>This course introduces students to literary questions of queerness, canonization, and nation, in the context of the United States'' 20th century discourses about homosexuality. Students will critically analyze the production of certain ideas of the nation through literature by examining questions raised through queer texts. The course will run concurrently with CTSJ 333: The Queer Novel; assignments for CTSJ 233 will be designed for a 200-level course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(805,2022,1115,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-231','<div class="desc"> <p>This course explores how assumptions of masculinity and femininity have informed foundational concepts and theories in the field of International Relations, the determination of what is considered to be worthy of investigation and what qualifies as appropriate methods of investigation, and who is (and is not) recognized as a subject of international politics. This course applies a gender lens to practical concerns in the field, including: political and economic development, human rights, and international security. It also engages the tensions associated with theorizing gender and IR, given the fluidity and intersectionality of identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(806,2017,1116,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/200/DWA-254','<div class="desc"> <p>The course will provide a conceptual framework for understanding the evolving scope and dimension of transnational security in the contemporary era. The unit will include an examination of the principal features of the current international system that are serving to foster gray area phenomenon; an analysis of five specific threats that have received particular attention in terms of their destabilizing potential (terrorism drug smuggling weapons trafficking maritime piracy the spread of disease pandemics environmental degradation/change); and an assessment of how these challenges can best be mitigated at both the domestic and global level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(807,2022,1118,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-401','<div class="desc"> <p>The topic of this course will change from year to year at the discretion of the Director of the Oxy at the UN Program. Topics may coincide with the annual theme of the United Nations.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(808,2022,1119,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-402','<div class="desc"> <p>The importance of conflict prevention and conflict resolution policies has long been recognized at the United Nations. The debate was originally focused on the effectiveness of peace-keeping operations and traditional diplomatic measures. Its parameters have been broadened considerably and now encompass longer term efforts to assist developing countries in enhancing durable structures conducive to peace and democratic stability and the targeted use of development cooperation. Combining theoretical/conceptual and practical concerns, and drawing from case studies of recent conflicts, the ultimate objective of the course is to identify feasible short-term and long-term conflict prevention strategies and tools and to develop practical suggestions to move from a culture of reaction to a culture of prevention. More specifically, the course will deal with: (1) the evolving meaning of prevention as it was understood in the Charter of the United Nations and subsequently shaped by the changing causes and nature of conflicts; (2) the main actors in conflict prevention against the backdrop of UN institutions; (3) the tools and practice of "operational" prevention (i.e. early warning, mediation, sanctions, peace operations, peace enforcement, and the role of regional organizations); (4) the tools and practice of "structural" prevention (good governance and democracy, mainstreaming human rights and gender, meeting post conflict reconstruction, and addressing the root causes of conflict); and (5) the significance of the emerging norm of the "responsibility to protect".</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(809,2022,1120,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-403','<div class="desc"> <p>This course will provide students with practical hands-on experience through an internship with a UN agency or a member state mission. This will be a professional undertaking, requiring intensive engagement with high-level responsibilities. The internship will be complemented throughout the semester, with the following three elements: (1) a bi-weekly seminar to fully process the learning and practical experiences of the internships; (2) a guest speaker series for dialogue with UN leaders; and (3) a bi-weekly analytic notebook that will provide an opportunity for students to critically analyze internship experiences, guest lectures, and assigned reading materials.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(810,2022,1121,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/100/econ-151','<div class="desc"> <p>The 21st century has witnessed an explosion of practical interest, research, and teaching on entrepreneurship and leadership across sectors of economic, social, and political life. Entrepreneurial leadership connects critical thinking to creative problem-solving and solution seeking. The range of models includes: technology innovators, social entrepreneurs, policy innovators, non-profit leaders, responsible business managers, among others. This course will provide students with a synthetic and multi-disciplinary overview to entrepreneurial leadership at the individual, organizational, and societal levels. Students will engage with the latest thinking, practical case-studies, and guest-entrepreneurs from the social, economic, cultural, and political spheres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(811,2022,1123,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-282','<div class="desc"> <p>The rise and fall of National Socialism are one of the most intensively studied topics in European history. Over six decades after its collapse, Nazi Germany continues to fascinate the general public, and with good reason. Although the fascist state lasted only for twelve years, it started history''s most destructive war, while committing crimes of unprecedented proportions. For the most part, it did so with the acquiescence of the German public. This class will investigate the rise of National Socialism as a political, social, and cultural phenomenon. The central focus will be on the decisive role of film and the visual arts as the most popular means of mass manipulation. This course is not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(812,2022,1124,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-325','<div class="desc"> <p>The European project - i.e. the gradual unification of the continent - which had been successful for decades, seems to undergo a fundamental crisis at present. This crisis has different aspects. Primarily, it has to do with the economic inequities within the European Union which became tangible in the aftermath of the world economic crisis of 2008. In its wake, the "weaker" economies, mostly at the periphery, were more affected than the stronger ones. But, there are also other problems, such as the lack of democratic structures, as well as strong leadership, the weight of a centralized bureaucracy, and the lack of a European public sphere. The course will take a look at the achievements of the European Union, the multiple reasons for its current crisis, and the various attempts to overcome it. Open only to juniors and seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(813,2022,1125,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/400/llas-490','<div class="desc"> <p>In this course, students will write their senior theses on Latin America or Latino communities. Seminar meetings will focus on issues concerning research methods and will guide students through the steps of writing a substantial essay. Students will present their findings in a public forum at the end of the course. Open only to LLAS majors.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(814,2019,1126,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-285','<div class="desc"> <p>Paradoxes and their resolution have played a significant role in the development of philosophy; they still have an influence on philosophy today. While Zeno''s paradoxes of motion where first posed about 2000 years ago there is still not a consensus about what to say about them. Semantic paradoxes such as the liar paradox and the paradoxes of vagueness reveal problems with everyday concepts such as truth and implication. Supertasks reveal problems with our understanding of infinity. What to say about these problems what they show us about how to understand space time infinity truth and implication for example are some of the issues we will discuss in this class. We will examine various paradoxes puzzles and purported paradoxes and discuss different proposed resolutions to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(815,2022,1127,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-150','<div class="desc"> Zumba is a high-energy fusion of Latin and International music with unique dance moves that sculpt and tone the body. The aerobic routines feature fast and slow rhythms to maximize caloric output and fat burning. Even if you have never danced or tried group exercise, Zumba is a perfect introduction to dancing for health. The movements are basic enough that anyone can follow, yet challenging enough that you never get bored. Course fee $125. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(816,2022,1128,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-267','<div class="desc"> <p>An introduction to the field of engineering. Students who have completed either of the introductory sequences in physics are well prepared to apply that knowledge to a wide variety of subjects. Applications covered include static equilibrium elastic properties of materials vibrations thermodynamics thermal properties of matter fluids waves and sound DC circuits and AC circuits.</p> </div>','PHYS 110 or PHYS 115; and PHYS 120 or PHYS 125 (may be taken concurrently); or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(817,2022,1130,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/100/psyc-101','<div class="desc"> <p>Introduction to the primary subject matter areas assumptions and methods of psychology as the science of behavior. Topics include: physiology, learning, perception, motivation, development, emotion, cognition, social processes, personality, and psychopathology. <em>This course is a prerequisite for all upper division coursework. Open only to frosh and sophomores. Core Credit only when taken at Occidental. Students with a 4 or 5 on the AP Psychology exam or a 6 or 7 on the IB Psychology exam are not eligible for Psych 101 but may take 200- or 300-level classes.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(818,2022,1133,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/200/rusn-278','<div class="desc"> <p>Stalin was arguably the first totalitarian dictator who created the model for similar regimes in the twentieth century. This course describes the changes Stalin brought to Soviet society the terrible consequences of his dictatorship and the reaction of cultural figures criticized as they rebelled against the system. This course examines those movements through popular culture film literature and first-hand testimony. The everyday life of Soviet citizens will be studied by looking at both permitted and forbidden forms of entertainment. The dissident movement that erupted in the 1960s and 1970s will be examined through the Sotsart artistic movement as well as short stories that circulated underground throughout the late Soviet period. Finally the course will look at Stalin''s legacy in Putin''s authoritarian Russia of the twenty-first century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(819,2022,1134,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-342','<div class="desc"> <p>This course consists of an introduction to the Spanish language and Spanish-speaking communities in the United States, home to the second-largest Spanish-speaking population in the world. We will focus on questions like: who are the principal groups of Spanish speakers in the U.S.? Where do they live, and how and when did they arrive to the U.S.? What are the principal linguistic features of their Spanish? In the U.S., who uses Spanish, and in what contexts, and for what purposes? What is the role of Spanish in public services, the media, and schools? In this course, we will also confront social issues such as language attitudes, bilingualism, and the interaction between language and identity. This course will be conducted in Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(820,2022,1135,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-190','<div class="desc"> <p>Theater Now takes students off campus and in to local performance venues to see the work of diverse artists making theater from a broad base of inspirations. A wide sample of local theater is represented – thematically, geographically, culturally. Friday evening field trips take students to a variety of Los Angeles’ artistic outlets, while Monday afternoon sessions with guest artists put class members in direct contact with the actors, writers, and directors whose plays and performance pieces they have seen. Our work offers a comprehensive introduction to active theater-going, L.A.''s performance community, the creative habits of working artists and the social, political and aesthetic ideas behind their work. T<em>here is a ticket fee not to exceed $75 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(821,2022,1136,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-203','<div class="desc"> <p>In this course we investigate a variety of 20th and 21st century theatrical productions across the globe staged during times of conflict and crisis: from online performances to amateur stages in restaurant back rooms in workers'' clubs and cafes to professional and Broadway theaters. From the 1920''s agitation trials (<em>Agitsudy</em>), mass spectacles and agitprop theater during the Russian Revolution to contemporary theater''s responses to COVID 19, anti-blackness, and other forms of racism and social oppression, we will examine how artists and activists use theater to respond to social and political unrest: sometimes as a tool to fight oppression and at other times as a tool to encourage obedience and propagate national political ideals. From performances staged in Sarajevo to Rio de Janeiro, from Mexico City to New Orleans, and from the streets of Moscow to the streets of New York City and beyond, the class thinks through art as activism and activism as art, examining how theatrical tactics transcend the boundaries of traditional performance spaces. We examine the performance theories and strategies emerging from these theatrical moments as we study seminal plays from these periods. For the final project, students in the class will develop performance projects in response to a contemporary crisis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(822,2020,1137,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-203','<div class="desc"> <p>This course explores the nation''s public health challenges the epidemiological basis of public health and ways that public health functions as a combination of science and politics. The course examines the special vulnerabilities of low income and medically underserved populations who often work reside attend school and play in neighborhoods with disproportionate exposures and poor quality medical care. The goal is to acquaint students with current public health issues especially as they concern community societal and environmental influences on health and well-being.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(823,2022,1138,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-295','<div class="desc"> Topics vary semester to semester. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(824,2020,1139,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-307','<div class="desc"> <p>The community health internship course is designed to provide students with real-world experiences to develop new skills and enhance insights into myriad community health issues concerns and solutions. Under supervision of the course instructor and in collaboration with a community proctor/partner students will intern for 8-hours a week at a health focused non-profit organization community clinic or government agency. A combination of internship experience class discussions written reports and journal entries will help students reflect on how health and health care are delivered in underserved communities. Before registering students should check to make sure that they are available during the preset internship hours. Internship hours and activities can be viewed at the Community Health Engagement website: http://bit.ly/1sDCTeJ</p> </div>','UEP 203 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(825,2022,1140,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-201','<div class="desc"> <p>This course provides students with opportunities to develop and practice the skills and habits that are foundational to academic writing and with knowledge of how to adapt these skills and habits for the varied writing demands students will encounter in college. This course fulfills (when passed with a grade of "C" or better) the college''s First Stage Writing Proficiency Requirement (and in some cases, the Second Stage Writing Proficiency Requirement), and it is also appropriate for students in various disciplines seeking to develop their writing, argument, analytic, and communication skills. All sections of this course focus on developing complex writing, analytical, and research skills for various audiences, disciplines, and genres. May be repeated to fulfill both the First- and Second-Stage Writing Requirements.</p> <p><strong>White Privilege and Working Class Grievance--Can We Talk about Class?</strong></p> <p>The readings and assignments in this course are designed to help students understand the social constructions of class hierarchies and the emerging theories about white identity politics, whiteness, and how race informs class analysis. We will engage in critical analysis and written argument to explore white identity, white supremacy, and the intersections of race, class and geography.</p> <p><strong>Writing, Rhetoric, and Formal Poetry</strong></p> <p>This section will focus on the relationship between poetry and rhetoric--more specifically, how form shapes understanding and is used to construct different types of rhetorical argument. We will study a variety of texts including poems, critical essays, biography, and literary and rhetorical theory.</p> <p><strong>Writing and the Rhetoric of Independent Film</strong></p> <p>This section will explore American independent film as an important art movement and alternative to traditional Hollywood filmmaking. We will study a select group of mostly recent works (2006-present) including those by the most noteworthy "mumblecore" writers/directors. </p> <p><strong>Writing, Gender, and Sexuality</strong></p> <p>This section will explore gender and sexuality in our contemporary American context. Drawing on readings from pop culture, critical theory, current events, and literature, we will examine how gender and sexuality are constructed, theorized, and represented, and how they intersect with other areas of identity including race and class.</p> <p><strong>Wanderlust Writing and Rhetoric</strong><br/> This section will explore the writing and rhetoric of wandering and adventure, from premodern adventure stories to the present-day #wanderlust as a synonym for free-spiritedness and Instagram humblebrags; our texts will be drawn primarily from literature, pop culture, and critical theory.</p> <p><strong>Protest Writing and Rhetoric</strong></p> <p>This section will examine the rhetoric, ideology, and context of protest genres, including social movements, speeches, literature, and visual texts, as we consider how writers, artists, and activists protest issues relating to race- and class-based oppression, gender inequity, ableism, colonialism, homophobia and heterosexism, and other concerns.</p> <p><strong>Writing on Travel</strong></p> <p>This section will examine travelers'' tales ranging from pilgrimages, the Grand Tour, island vacations, luxury cruises, and scientific expeditions, analyzing them from anthropological and post-modern critical perspectives, all while exploring images and texts from the 1700''s to the present.</p> </div>','Not open to first-year students ',NULL,NULL);
INSERT INTO course_descriptions VALUES(826,2022,1141,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-285','<div class="desc"> <p>This course is an intensive introduction to the theories and practices of a trade that is protected by the 1st Amendment of the U.S. Constitution, essential to democracy, and yet increasingly under threat. Taught by a Pulitzer Prize-winning report, editor, columnist, and author who bolsters his teaching with distinguished guest speakers, this class introduces students to the core values and nuts-and-bolts skills demanding by the rapidly changing field of journalism, while teaching critical thinking skills that are key to global citizenship. Students will learn to research, report, interview, and then write with rhetorical force in the concise, clear newswriting style that remains the foundation of journalism in its myriad, multi-media forms. This course focuses on media influences across a range of geographical locations including Europe, Asia, Central and South America, as well as the U.S. The course will focus on regions and nations that are most in the news at the moment of the course semester. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(827,2022,1142,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-295','<div class="desc"> <p>This class will engage the historical theoretical and cultural dimensions of rhetoric in a range of disciplines in the arts literature politics and philosophy. In readings from Aristotle to poststructuralist theory we will examine all aspects of the rhetorical situation (exigence audience and rhetor) and the contexts in which rhetorical acts occur. We will examine how language practices intersect with culture and identity including class race sexuality gender and nation as we consider how arguments are constructed and how writing and narrative transform culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(828,2022,1143,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-395','<div class="desc"> <p>An exploration of the theory and practice of writing instruction, this class emphasizes rhetorical strategies, audience expectations, and forms of academic discourse. This course also provides new advisers with an introduction to tutoring practices and strategies through Writing Center scholarship. Permission of instructor required.<em>This class is only for Peer Writing Advisers working in Writing Center. </em><em>May be repeated once for credit. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(829,2022,1145,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/200/arab-275','<div class="desc"> <p>A selection of literary works and films from the Arab world will be analyzed in the context of historical, cultural, social, and political developments from the last decades of the 20th century. The texts, in various genres - short story, novel, memoir, poetry - will highlight the heterogeneity and complexity of Arab countries, such as: Morocco, Tunisia, Egypt, Lebanon, Iraq, and Saudi Arabia. Some of the main themes that we will cover include: tradition versus religion, challenges of modernity, gender relations, social (im)mobility, and generational gap. The course will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(830,2022,1146,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-266','<div class="desc"> <p>An introduction to Japanese painting, sculpture, and architecture, from antiquity through the Tokugawa Period. Emphasis will be placed on the formation of an indigenous artistic tradition and its transformation under Chinese influence. The arts produced for patrons in Shinto, Buddhist, Zen courtly and samurai contexts will be examined. Museum visits required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(831,2022,1147,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-378','<div class="desc"> <p>An examination of the artistic traditions of Northern Europe from c. 1400 to 1600 CE. Points of consideration include significant artistic personalities and individual works, the relationship between patron and image, territorial distinctions, in addition to the connection between Northern and Southern (Italian) visual developments during this period.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(832,2019,1148,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/300/ARTH-387','<div class="desc"> <p>This course will focus on modernism and the avant-garde in the United States and Europe in the 20th century. Definitions of modernity the avant-garde and visual culture will frame our analysis of painting sculpture photography architecture and film. We will investigate these visual media paying close attention to the ways in which they engage with critique and negate the traditionsof western art history. Issues of gender sexuality race ethnicity and the politics of art will underscore our work together in this course. We will also explore how cultural and social revolutions emerging theories of modernism and the important role of art criticism and art exhibition have shaped not only 20th century visual culture but also the discourse of art history itself.</p> </div>','Any 100 or 200 level ARTH course or instructor permission. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(833,2022,1149,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/200/bio-226','<div class="desc"> <p>A course designed to provide a thorough understanding of the intracellular processes of eukaryotic cells. The course will discuss topics including the molecular basis of cellular organization, structure, and function; cell motility; organelle biogenesis and function; cellular communication and signaling; and intracellular processes such as apoptosis and autophagy. <em>Includes one three-hour laboratory session per week, plus two hours arranged.</em></p> </div>','BIO 130 ','BIO 226L ',NULL);
INSERT INTO course_descriptions VALUES(834,2017,1150,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-226L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(835,2019,1151,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/BIO-Biology/500/BIO-560','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(836,2019,1152,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/BIO-Biology/500/BIO-560L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(837,2022,1153,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-241','<div class="desc"> <p>As part of human cognition, our perception, production, and understanding of music has elicited many questions: what is music in relation to "sound"? Is music an evolutionary adaptation? What is the relationship of music and emotions or memory? Can music influence perception in other modalities? What is the meaning of music? Can music make us smarter? Is music a language? What is biological and what is cultural in the esthetics of music? This course will reframe many of these questions from the interdisciplinary standpoint of cognitive science, acoustics, music theory, and semiotics, to explore music as a cognitive process. Topics will include: the perception of pitch, timbre, rhythm, and localization; music and the brain; the cognitive aspect of the esthetics of music; the relationship between music and language in terms of their structures and neurological processing; music and memory; music and emotions; and music and meaning. We will also discuss the role music plays in cross-modal interactions, either in the real world or in films and multimedia art works.</p> </div>','Any Cognitive Science or Music class; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(838,2022,1154,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-106','<div class="desc"> <p>In the United States, roughly 80% of the population lives in urban regions (2000 U.S. Census), while according to United Nations figures, about 52% of people are urban-dwellers worldwide. This course will examine various representations of the modern metropolis through film, literature, and cultural theory. The city, as we experience it today, is the product of multiple historical, cultural, and social forces. Over the course of the semester, we will consider how cities have been shaped by these forces, as well as how they, in turn, shape our own experience and understanding of culture, history, and social practices. In an era of increasing globalization and mobility, the role of the metropolis continues to evolve and expand. As we consider representations of the city in a variety of films and novels from around the world, including some from our own city of Los Angeles, we will interrogate the ways in which the city has played a formative role in how we imagine life in the contemporary moment. In what ways has the city become a vehicle for the production of culture? How does life in the city serve to normativize certain notions of what it means to live in the modern world? How does life in rural spaces complicate representations of modernity that take the city as their norm? Does the city promote accessibility, or, alternatively, does it rigidify codes of exclusivity? These are some of the many questions we will address as we consume a spectrum of world cinema and literature. As we work our way through the material, we will strive to develop a complex understanding of how cities shape our cultural imagination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(839,2022,1155,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-311','<div class="desc"> <p>In this course, students examine contemporary child poverty, both in the United States and abroad. Topics include: how poverty is defined, both locally and globally; the numbers and distribution of poor children; as well as the causes of child poverty. Readings explore poverty in relation to education, economics, homelessness, child labor, family, gender, and race. Students analyze historical anti-poverty policies, such as: The New Deal, the War on Poverty, and the United Nations Convention on the rights of the child, as well as contemporary proposals to reduce child poverty, such as: childcare, welfare, job training, job creation, and tax policy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(840,2020,1156,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-370','<div class="desc"> <p>This seminar will explore the origins of the world famous Frankfurt School, a group of German social philosophers and theoreticians, which emerged at the Institute for Social Research of the University of Frankfurt am Main in the 1920''s. The group wanted: (1) to analyze the conditions of modern capitalism and its impact on society in general, on family and social structures, value systems, and mass culture; (2) critically review the theories of Karl Marx, Sigmund Freud, and Max Weber; and (3) to establish the principles and foundations of a "critical theory." We will read and discuss major works by Max Horkheimer, Theodor W. Adorno, Walter Benjamin, Herbert Marcuse, Erich Fromm, Siegfried Kracauer, Leo Loewenthal, and others. The seminar will focus on the "first phase" of the Frankfurt School, its beginnings and its work and development during the 30''s and 40''s - when the school relocated to New York and many of its collaborators lived in other American cities or abroad - and the immediate post WWII period. (A second seminar will follow next year and explore the school''s development and its world wide impact in the 60''s and 70''s.) The course is taught in English. Students minoring or majoring in German will read some of the original texts (especially Marx, Freud, Benjamin, and Kracauer,) that are written in German. Open only juniors and seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(841,2022,1159,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-244','<div class="desc"> <p>This course is a survey of Iranian politics and society, from the establishment of the Qajar dynasty in the late 19th century to the present. The aims of the course are twofold: (1) to introduce students to major events shaping Iranian politics over the last century. Among the topics covered are: the rise and demise of the Qajar dynasty, the Persian Constitutional Revolution, the rise and fall of the Pahlavi dynasty, the role of Western imperialism, the geopolitics of oil, the 1979 Iranian Revolution, the Iran-Iraq War, the crisis of theocracy, etc.; and (2) to expose students to a set of theoretical and analytical issues underlying Iran''s political development, such as: the causes and consequences of revolutions, state-society relations, secularism and modernization, fundamentalism and reform, pluralism and democracy, autocracy and clientelism, corruption and the rentier state. Above all, this course is design to help students think, talk, and write in an informed and critical manner about politics in modern Iran.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(842,2020,1160,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-249','<div class="desc"> <p>This course explores core concepts in global public health, the development of human rights'' instruments, and how these two fields have increasingly intersected in global and local public health work. Specifically, we will review public health methods of measurement and analysis - spanning epidemiological, economic, and political approaches - to understand if, and how, a rights-based approach to health can inform more critical and more productive approaches to issues such as HIV/AIDS and other sexual and reproductive health concerns. Finally, this course examines how global public health issues have generated dramatically different responses across and within regions, countries, and communities. We will focus, particularly, on the experience of Brazil, given its changing role in the global economy and its progressive public health approach.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(843,2017,1161,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/300/DWA-336','<div class="desc"> <p>This is an advanced seminar on the relationship between religion ideology and democracy in the Middle East; it presupposes background knowledge of the region and only basic exposure to comparative politics. The course surveys the historical and political trajectories of selected nationalisms and Islamist ideologies in the Middle East: Pan-Arabism various Arab territorial nationalisms Zionisms Turkish nationalisms Kurdish nationalisms and various strains of Islamism.</p> </div>','DWA 241',NULL,NULL);
INSERT INTO course_descriptions VALUES(844,2022,1162,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-350','<div class="desc"> <p>Each year this course will focus on some sub-set of contemporary issues in the global political economy. This could include topics such as: the state of the global economy and global economic crises, multinational corporations and corporate social responsibility, global production and supply chains, emerging forms of regulation in the global economy, transparency and accountability, and global inequality, among others. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(845,2022,1163,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-368','<div class="desc"> <p>America is the most powerful nation in the post-Cold War world but has not, as yet, forged a national consensus on post-Cold War foreign policy. The country and the world have repudiated the neo-Con Unilateralist approach of the Bush administration, but there is no agreed upon substitute. Various authors are proposing strategies from "ethical realism," to "liberal interventionism," to "neo-isolationism," and on. The course will critically examine proposals for a new American Grand Strategy from leading foreign policy thinkers and from groups such as the Princeton project. We will try to agree on what a workable Grand Strategy might be and analyze whether it might have widespread bi-partisan support at home and ample international support abroad. Open only to DWA or Politics majors with junior or senior standing.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(846,2022,1166,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-351','<div class="desc"> <p>In the current economic climate, what should macroeconomic policymakers do to help the U.S. economy? This course analyzes the current macroeconomic policy challenges facing the United States from the vantage point of modern macroeconomics and economic history. Students will read state-of-the-art empirical research in macroeconomics and develop a sense for how macroeconomists conduct research and make policy recommendations. Special emphasis will be placed on exposing students to the major developments of U.S. monetary and fiscal policy since the Great Depression and on the role of history in guiding contemporary macroeconomic policy decisions and debates.</p> </div>','ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(847,2022,1168,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/300/educ-350','<div class="desc"> <p>"How can the oppressed as divided unauthentic beings participate in developing the pedagogy of their liberation?" This course focuses on Freire''s theoretical, pedagogical, and practical contributions to contemporary movements in critical pedagogy, critical literacy, and educating for "social justice". Beginning with Franz Fanon''s influences on Freirean thinking about revolution and decolonization, we will analyze the construction of the "Pedagogy of the Oppressed". We pay particular attention to the role of the Hegelian dialectic as a driving philosophical method, as well as the significance of Freirean themes in understanding contemporary schooling, education, community activism, and vocation in general. Students will analyze, critique, and reflect upon their own framing philosophies for personal engagement with oppressed peoples and communities - towards the broader goal of defining an individual role in the development of a pedagogy of the oppressed that both negotiates and is informed by students'' multiple identities.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(848,2017,1169,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/GEO-Geology/100/GEO-150L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(849,2022,1170,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-342l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 342',NULL);
INSERT INTO course_descriptions VALUES(850,2017,1171,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/GRK-Greek/300/GRK-300','<div class="desc"> <p>This course will focus on two of the most powerful and most feared women in Greek literature Medea and Clytemnestra. We will examine these women in an ancient and modern literary context by reading Homer Aeschylus Euripides Apollonius and selections from contemporary scholars. No knowledge of Greek is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(851,2022,1172,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-224','<div class="desc"> <p>This course offers a chance to come to know a variety of individuals who lived in and travelled from the Italian peninsula in the 1300''s, 1400''s, and 1500''s. We shall journey to the Far East with Marco Polo; meet peoples of the Mediterranean; and "visit" the republics of Venice and Florence, the papal court of Rome, and the ducal courts of Urbino and Mantua. We shall enjoy distinctive creations in literature, education, philosophy, and the arts, and read letters about South American peoples from Amerigo Vespucci. Diplomat Machiavelli witnessed independent Italian city-states fall to French and Habsburg conquests and described such realistic politics; courtesan Veronica Franco successfully practiced her sexual trade while writing poems celebrating her true love, as well as her mercantile city-state. Students may petition for 300-Level credit for this class with the completion of additional work arranged with the instructor.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(852,2022,1173,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-226','<div class="desc"> <p>A history survey of the 14th-18th centuries: Renaissance, scientific advance, global encounters in Spanish and English empires, the Enlightenment, and revolutions (English, American, French). The luxury of European palaces and curiosity cabinets was based upon the exploitation of European peasants and global indigenous peoples. Students seeking origins of feminist and natural rights arguments will consider protest pamphlets, women''s writings, utopian fiction, and enlightenment stories (some with film versions), which created empathy for others.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(853,2022,1174,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-309','<div class="desc"> <p>This course examines the southern region of the United States as a “slave society,” that is, a society in which: 1) a system of enslaved labor and human commodification drove the region’s economy and 2) a powerful slaveholding minority held the reigns of political power. How did this minority white ruling class maintain their power over a large enslaved population (1 in 3 southerners by 1860) and a majority of non-slaveholding whites (3 out of 4 white southerners by 1860)? How did enslaved women and men create community, build solidarity, chart insurgent geographies, and establish a political tradition of resistance in the face of arbitrary and institutionalized violence? We will examine the rise of chattel slavery, its importance in American capitalism, and its impact on southern households, political institutions, religion, and cultural practices. Our readings will explore how a white supremacist system of transgenerational human property shaped the social relations and lived experiences of enslaved African Americans, common whites, slaveholding planters, and Indigenous nations of the South. How did these groups of southerners use religion, violence, and ideologies of sex, gender, race, and class either to challenge or reinforce existing power relations? How was the US nation as a whole complicit in the perpetuation of chattel slavery? Finally, how does the US as a nation continue to reckon with the legacies of chattel slavery in contemporary social movements, law, and culture? Course materials include primary documents, first-person narratives, film, music, and groundbreaking historical scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(854,2020,1175,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/400/hist-495','<div class="desc"> <p>The honors seminar is designed for history majors who have completed the HIST 490 Senior Seminar and have been approved by the HIST 490 instructors to continue on as candidates for Honors designation. Over the course of the semester each honors thesis writer will work with the seminar instructor on advanced methodologies and multiples drafts to expand his/her original research and revise the thesis from a 25-page paper to a 40-page (or more) paper. The seminar will culminate with a program of oral presentations in which each student will share his/her work with the Department and the campus community.</p> </div>','HIST 490 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(855,2022,1178,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/200/kine-201','<div class="desc"> <p>This course examines the social and cultural factors that influence sport and physical activity. The positive and negative consequences of the way sport is organized in American society will be discussed. We will explore the unifying power of sport, as well as how sport serves to reproduce many of the inequalities present in our society. Topics include: violence, substance abuse, media, gender, race/ethnicity, and social class, and their roles within sport and physical activity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(856,2022,1179,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-101','<div class="desc"> <p>This interdisciplinary course will introduce students to sources, methods, and approaches in the transnational study of Latin American and US Latino communities. We will focus on the social and cultural interaction of indigenous European, African, and Asian peoples from the colonial period to the present using a variety of primary and secondary materials including films, literature, historical documents, visual arts material, culture, music, scholarly books, and essays. Field experiences in Los Angeles will supplement the course materials. Specific course topics will vary by instructor but may include: migration, mestizaje, indigenism, imperialism, dependency, nationalism, urbanization, popular culture, and social movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(857,2022,1180,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ling-linguistics/300/ling-350','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','LING 301, COGS 101, PSYC 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(858,2022,1181,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/200/math-295','<div class="desc"> <p>Topics in mathematics selected largely by student interest and faculty agreement.</p> </div>','A Calculus 2 course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(859,2022,1182,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-360','<div class="desc"> <p>Axiomatic development of Euclidian and non-Euclidian geometries, including neutral and hyperbolic geometries, and possibly brief introductions to elliptic and projective geometries. The course will emphasize a rigorous and axiomatic approach to geometry and consequences of Euclid''s Parallel Postulate and its negations.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(860,2022,1183,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-112','<div class="desc"> <p class="sc-BodyText">Pop music blogs online social networks home recording studios and mashup/remix communities are emerging musical spaces in the digital era. In this course we will study music-cultures that are enabled and generated by digital media and technology. We ask how digital media shape the mode of production transmission and reception of contemporary popular music. Using principles of ethnomusicology we will examine how music as a "digital vernacular" creates a sense of place and self in the increasingly globalized world; how social media and technological institutions organize 21-century music participation at the grassroots independent level.<strong> A laptop computer is required.</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(861,2022,1184,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-241','<div class="desc"> <p>As part of human cognition, our perception, production, and understanding of music has elicited many questions: What is music in relation to "sound"? Is music an evolutionary adaptation? What is the relationship of music and emotions, or memory? Can music influence perception in other modalities? What is the meaning of music? Can music make us smarter? Is music a language? What is biological and what is cultural in the esthetics of music? This course will reframe many of these questions from the interdisciplinary standpoint of cognitive science, acoustics, music theory, and semiotics to explore music as a cognitive process. Topics will include the perception of pitch, timbre, rhythm, and localization; music and the brain; cognitive aspect of the esthetics of music; the relationship between music and language in terms of their structures and neurological processing; music and memory; music and emotions; music and meaning. We will also discuss the role music plays in cross-modal interactions, either in the real world, or in films and multimedia art works.</p> </div>','Any course in Music or Cognitive Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(862,2019,1185,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-325','<div class="desc"> <p>A survey of results in the metatheory of first order logic including consistency completeness decidability and undecidability.</p> </div>','PHIL 225 MATH 210 or permission of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(863,2022,1186,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-166','<div class="desc"> <p>An introduction to the theory of special relativity for both science and non-science majors. Topics include Einstein''s postulates the geometry of relativity the Lorentz transformations and the structure of spacetime.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(864,2022,1187,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-369','<div class="desc"> <p>Special topics in physics selected largely by student interest. Prerequisites vary with subject area. Possible topics include: group theory in physics applications of quantum mechanics in atomic nuclear and particle physics introduction to relativistic quantum mechanics nonlinear pattern forming systems hydrodynamic instabilities superfluidity and superconductivity methods of material science. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(865,2020,1189,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/political-theory/pols-251','<div class="desc"> The ideas of justice, obligation, freedom, and the good state in Plato and Aristotle; history and equality in the Old and New Testaments; Roman theories of law and politics; Christianity and the role of the state in St. Augustine and St. Thomas Aquinas; Machiavelli on political power and political regeneration. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(866,2022,1190,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/100/psyc-111','<div class="desc"> <p>The average adult possesses over 50000 concepts ranging from physical concepts like "force" and "density" to biological concepts like "growth" and "reproduction" to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich revise and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive developmental and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(867,2022,1191,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-215','<div class="desc"> <p>This course explores the dynamic religious and cultural landscape of East Asia, providing an overview of religion as it has been constructed in the states that are today known as China, Japan and Korea. In addition to learning about Confucianism, Daoism, Shintoism, and Buddhism, students will also learn about shamanistic and folk traditions, as well as practices that span across traditions, in order to provide students with tools to resist simplistic understandings of religious identity. Furthermore, taking both a chronological and comparative approach, the course leads students through the development of different traditions by situating them in their broader socio-political contexts. Finally, the course engages with multiple themes and perspectives, including the relationship between religion and the state, the development of institutions, literary and artistic expression, and gendered experiences of religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(868,2022,1192,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-281','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(869,2020,1193,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/rels-religious-studies/300/rels-365','<div class="desc"> <p>A study of moral/ethical thinking in the history of Buddhism. Through a close reading of selected Buddhist texts from India Tibet and China we will examine Buddhist theories of character development and virtue the ideals of human enlightenment towards which Buddhists aspire and the practices or disciplines thought adequate to this aspiration.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(870,2022,1194,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(871,2022,1195,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-335','<div class="desc"> <p>This course will focus on the changing dynamics of state power in Latin America from the 1960s through the present. We will compare Latin America''s hard-dictatorships (dictaduras) to various versions of soft(er)-authoritarianisms (dictablandas) before such states transitioned to electoral democracy. Beyond looking at the changing dynamics between states and their civil societies over time we will explore legacies of civil wars revolution military coups and dirty wars. We will not only look at how ordinary people fought back by struggling for political human and cultural rights but how their movements contributed to the recent democratic transitions characterized as "third-wave" democratization".</p> </div>','SOC 101, POLS 101, DWA 101, HIST 258, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(872,2022,1196,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-313','<div class="desc"> <p>This course offers students the opportunity to analyze films that have emerged in Latin America (e.g. Argentina, Brazil, Colombia, Cuba, Mexico, and Peru) as well as in the United States in the 20th and 21st Centuries. Many of the visual works studied treat significant contemporary issues in Latin America, such as the representation of history, questions of identity and alterity, questions of race and ethnicity, globalization, authority, the construction of class and gender in society. Emphasis will be placed on studying films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically, this course is a critical survey of the representation of Latin America with representative examples from different historical periods (beginning with the pre-Columbian and Colonial periods followed by the 19th and 20th Centuries). The goals of the course are to understand how film as a medium has functioned historically and aesthetically in its representations of different sectors of society.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(873,2022,1198,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-209','<div class="desc"> Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(874,2022,1199,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-246','<div class="desc"> <p>A socio-historical analysis of narratives and novels by African American writers. The course will examine the intellectual, political, and cultural influences on writers such as Frederick Douglass, Harriet Jacobs, Charles Chesnutt, Nella Larsen, Zora Neale Hurston, Ann Petry, James Baldwin, Toni Morrison, and Charles Johnson.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(875,2017,1200,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/100/ARTH-190','<div class="desc"> <p>This course provides a thematic introduction to Native North American Indian Art drawing from historic (pre and postcontact) precedents. Class discussion and lectures are generated from the conceptual themes of contact conflict exchange appropriation and re-appropriation of American Indian imagery materials and ideas rather than from the more descriptive categories such as Southwest painting or Plains beadwork. A concern with the social production of art in specific episodic contexts serves as a means of critically examining the circulation and appreciation of American Indian arts and material culture as fine art commodity political critique social marker religious icon and physical landmark.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(876,2017,1201,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-250','<div class="desc"> <p>This course critically examines films by and about American Indian and First Nations peoples including art films shorts cinema and documentaries. Themes addressed include: reflexivity the portrayal of Native women the urban experience indigenous aesthetics contemporary storytelling silence parody re-appropriation and conventional representations. Students will be introduced to the diverse settings of Native film (including the Navajo Nation (Dine) and Mohawk nations of Canada) as well as core historical topics such as American Indian veterans activism the boarding school experience and the emerging Native film industry.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(877,2022,1202,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-391','<div class="desc"> <p>A seminar focusing on a topic in the history of art taught by a practicing curator at a Los Angeles cultural institution. Course topic(s) change annually and will include off-campus hands-on work within the context of curatorial and exhibition practices. Course may be repeated for credit with a different topic.</p> <p><strong>The Art of Describing: 17th- century Dutch Paintings and Drawings at the Getty Museum</strong> <strong>(2 units)</strong></p> <p>Taught on site at the Getty Museum every other Friday, this class fosters a close study of 17<sup>th</sup>-century Dutch drawings and paintings. Examining the Getty’s collection of Dutch art through the lens of Svetlana Alpers’ groundbreaking book, <em>The Art of Describing</em>, this class explores the craft of representation and questions the narrative of the “Dutch Golden Age.”</p> <p><strong>East Asian Gardens: China, Japan, Korea—and California?</strong> <strong>(4 units)</strong></p> <p>What kinds of gardens have existed in East Asia, and what sorts of functions have they fulfilled? How have they engaged with broader visions of the cosmos, and how have they expressed such understandings? What happens to such gardens when they are translated into a cultural context very different from that in which they emerged? To answer these questions, this course, taught by a curator at the Huntington Library, will take a broad view of the history of East Asian garden-making, examining images, texts, films, and gardens from the 2nd century BCE to the present. We will investigate hunting parks constructed as microcosms of empires, holey rocks that inspired dream-journeys to immortal realms, Buddhist paradises accessible in this-worldly estates, and textual fantasies of gardens of the mind. Taking advantage of the Chinese and Japanese Gardens at the Huntington, this course will also explore how such concepts have been put into practice in the physical spaces of these gardens, where the course will be held each week. Moreover, we shall trace the very different histories of these two gardens in order to gain insights into California''s shifting relationship to East Asia over the course of the twentieth and twenty-first centuries. In taking this course, students will ultimately gain an understanding of the diversity of garden forms in East Asia; familiarity with key concepts used in garden-making; practice with the skills of visual and spatial analysis, as well as cultural and historical contextualization, necessary to discuss gardens meaningfully; and experience with curatorial strategies for making East Asian gardens accessible to diverse audiences. The final project will involve developing an interpretive program for one section of the Huntington’s gardens. <strong>This course meets on Friday, at the Huntington Library, Art Collections and Botanical Gardens</strong>. <em>Additional Core Requirement Met: Regional Focus and Pre-1800.</em></p> <p><strong>TRUE GRIT: American Prints from 1900 to 1950 (2 units)</strong></p> <p>This seminar engages the exhibition and the J. Paul Getty Museum:"True Grit: American Prints from 1900 to 1950" which opens on October 15, 2019. This exhibition, drawn from local museums and a private collection in Los Angeles, provides a vibrant survey of early twentieth-century American printmaking. Compelling depictions by Peggy Bacon, George Bellows, Mabel Dwight, Edward Hopper, Martin Lewis, Kyra Markham, and John Sloan convey a broad view of American culture that include dance halls and boxing rings, skyscrapers and subways, parks and tenement apartments. Using innovative printmaking techniques, these American artists captured the gritty world around them and came to terms with modern life. This seminar will examine the nature of American printmaking in the early twentieth century. In addition to working with the Getty curator in planning the installation of the exhibition itself, topics will include evolving printmaking techniques and the evolution of a uniquely American subject matter.</p> </div>','Any 100- or 200-level Art History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(878,2022,1203,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-290','<div class="desc"> <p><strong>Neutral and Authoritative Knowledge</strong></p> <p>this course is for anyone who is interested in world-building, in teaching others to teach themselves (alongside other co-teachers/learners). we will design and implement the course objectives together—laterally. we are all the students. we are all the instructors. no one is the expert but everyone knows some thing quite well. we will take what we know, make something from it, and likely call it "art" (or any other term that best suits your person). what will you bring to the table?</p> <p><strong>A Sustained Environment: Understanding and Caring for Bio-Cultural Diversity</strong></p> <p>This course coincides with the unprecedented environmental and pandemic challenges of our time, bringing a new urgency to understanding the complex and dynamic interrelations between human culture and the natural environment. Using embodied pedagogy to incorporate our bodies into the learning process, as well as indigenous, ecofeminist, and intersectional frameworks, we will analyze pressing ecological issues including climate change, nature rights, green capitalism, extractive economies, and environmental justice. We will reach to other environmentally focused resources on campus; host guest lectures and artist led workshops; conduct research and fieldwork in archives, libraries, and outdoor locations; and visit local initiatives that intersect art, science and environmental practices. Utilizing a range of contemporary aesthetic strategies, we will develop a research-based project to study and present environmental problematics around Occidental campus. Projects are expected to have a multidisciplinary approach, and can be developed individually or in collaboration. This course is open to all majors.</p> <p>Previous Wanlass Artists-in-Residence include: Lucky Dragons, CamLab, Rafa Esparza, Kenyatta A.C. Hinkle, Candice Lin, Shizu Saldamando, and Carolina Caycedo.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(879,2017,1204,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/BIO-Biology/200/BIO-268L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(880,2022,1205,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chin-chinese-studies/400/chin-460','<div class="desc"> <p>This advanced level course will introduce students to the art, practice, and intercultural contexts of translating Chinese into English. The class will discuss the content, linguistic form, and cultural contexts of a variety of authentic examples of written Chinese, followed by practice in producing readable English translations. Original Chinese texts will include short stories, essays, and media. This course is open to both non-native and native speakers of Chinese who wish to develop their bilingual skills and intercultural literacy. Class discussion will be conducted in Mandarin, Chinese, and English. May be repeated once for credit.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(881,2017,1206,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CLAS-Classical-Studies/200/CLAS-222','<div class="desc"> <p>This course is a survey of Greco-Roman myth with a particular focus on the representation function and meaning of the gods. Students will study these myths in their original socio-historic contexts but a large portion of the course will be devoted to a historic survey of modern theories of myth. This approach will allow students to appreciate myth''s relation to the various ritual philosophic and artistic contexts in which they appear both in the ancient world and beyond.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(882,2017,1207,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CLAS-Classical-Studies/200/CLAS-292','<div class="desc"> <p>In this course we will trace the European history of what we today call "love" from Ancient Greece to the Renaissance and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and ever-provoking concept: the lyrics of Sappho the dialogues of Plato the satirically erotic "technical manuals" of Ovid the Gospels of Christianity the troubled Confessions of Augustine the courtly tales of knights in the Middle Ages and the great all-encompassing journey of Dante''s through heaven and hell in the Divine Comedy. Significant attention will be paid to the way each of these works continues to contribute to our own modern notions of love in all their ecstatic heartbreaking inspiring and frustrating complexity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(883,2022,1213,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-225','<div class="desc"> <p>This course offers students an interdisciplinary introduction to the historical and philosophical foundations of human rights, the creation of the international human rights regime in the mid-20th century, the impact of social movements on the evolution of international human rights laws and norms, and the impediments to the realization of human rights in practice. Through exploring thematic concerns such as women''s rights, LGBT rights, torture, capital punishment, international responses to genocide, and corporate responsibility, we will engage contemporary debates surrounding the universality of human rights, the relationship between human rights and inter/national security, the duty-holders of human rights law, and the gap between human rights ideals and enforcement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(884,2022,1214,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-281','<div class="desc"> <p>This course will explore the past, present, and future role of media in shaping global change, and guide students in the development of a global media campaign. The campaign will be the culmination of an inquiry around media as a tool for social change. From pivotal news events of the last twenty years, to the rise of reality television, social media, and declining influence of print and broadcast journalism, this course will use media literacy case studies and comparative analysis of news coverage and critical analysis of cinema trends in art and culture to explore media''s impact on social norms and cultural-narratives. Specifically, we will examine the role of media in various revolutions worldwide - the recent role of social media in the overthrow and transition of the Egyptian government (the Square), the role of song in South Africa''s struggle for freedom, and international news coverage of the Feminist Movement and the Black Panther party. How is it that movements are organized using media as a tool for social change? Professional writers, media executives, and branding experts will be guest speakers for viewing-salons that will be scheduled throughout the semester. Students will learn media literacy skills and develop critical thinking by engaging with the role media plays in major historical, cultural, and social issues; become active learners as they gain proficiency to approach their own personal inquiries with creativity and scholarly rigor; gain expression through visual storytelling, data visualization, and social media, as they create their own global media campaign and present it at a final salon for the course; and participate in the shaping of the narrative around global social change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(885,2022,1215,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-283','<div class="desc"> <p>This course will study how the concept of soft power - first developed by Harvard professor Joe Nye - applies to interactions among nations in the 21st century. Soft power lies in the ability to attract and persuade, whereas hard power - the ability to coerce - grows out of a country''s military or economic might, especially in an imperial/colonial period. Students will analyze how trade, culture (music, food, sports, language, education), environment, and political institutions (democracy, corruption, human rights, etc.) contribute to a country''s soft power and make up its global brand. Students will analyze the current state of soft power in key nations and consider how countries and their citizens can affect the attractiveness of a country''s culture, ideas, and institutions in order to raise its soft power. The course will introduce students to the idea of global sustainable diplomacy, which pursues global goals using soft, not hard, power.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(886,2017,1216,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ECON-Economics/100/ECON-101A','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(887,2022,1217,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-319','<div class="desc"> <p>This course examines the application of economics to the law. Studies of actual cases reveal how economics can be applied to address such questions as: (1) whether an action violates the law, (2) who experiences economic harm as a result of that action, and (3) what the legally prescribed consequence is. Specific applications include: property rights related to technical innovation, competition in concentrated industries, and the extent of corporate liability. The primary context is the United States, but other legal systems provide some specific comparisons.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(888,2022,1218,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/100/educ-101','<div class="desc"> <p>In every major urban center across the United States, children and youth attend public schools managed by highly-bureaucratized administrative entities called ''school districts''. This course provides a historical survey of the evolution of U.S. urban schooling, tracing its development from the earliest community-based, one-room schoolhouses, to modern major urban unified school districts. We explore the roles that industrialization and immigration have played in the urbanization of communities, and the ways in which schools have adapted in order to provide for the socialization of the urban worker. We examine shifts in the politics of public education as it pertains to control over schools and schooling and the various stakeholders involved. We conclude with a look at the evolving roles of the teacher, school counselor, and the administrator - as well as a glimpse into what the future holds for both traditional and alternative forms of public schooling in urban school communities across the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(889,2020,1219,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/engl-english/100/engl-106','<div class="desc"> <p>In the United States, roughly 80% of the population lives in urban regions (2000 U.S. Census), while according to United Nations figures, about 52% of people are urban-dwellers worldwide. This course will examine various representations of the modern metropolis through film, literature, and cultural theory. The city, as we experience it today, is the product of multiple historical, cultural, and social forces. Over the course of the semester, we will consider how cities have been shaped by these forces, as well as how they, in turn, shape our own experience and understanding of culture, history, and social practices. In an era of increasing globalization and mobility, the role of the metropolis continues to evolve and expand. As we consider representations of the city in a variety of films and novels from around the world, including some from our own city of Los Angeles, we will interrogate the ways in which the city has played a formative role in how we imagine life in the contemporary moment. In what ways has the city become a vehicle for the production of culture? How does life in the city serve to normativize certain notions of what it means to live in the modern world? How does life in rural spaces complicate representations of modernity that take the city as their norm? Does the city promote accessibility, or, alternatively, does it rigidify codes of exclusivity? These are some of the many questions we will address as we consume a spectrum of world cinema and literature. As we work our way through the material, we will strive to develop a complex understanding of how cities shape our cultural imagination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(890,2020,1220,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/engl-english/100/engl-189','<div class="desc"> <p>A historical survey of the major literary genres from the colonial to the contemporary period emphasizing the persistent thematics of the American experience from a cross-cultural perspective. This class is particularly suited for students interested in the ways in which well-known American authors are in conversation with African Americans, Native Americans, Asian Americans, Latinos/as, and white women, who, until recently, had been left out of the literary canon. Open only to first year students. ENGL 189 satisfies an equivalent requirement to ENGL 289 within the English major. Students may not receive credit for both ENGL 189 and ENGL 289.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(891,2022,1221,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-287','<div class="desc"> <p>We might think that older literature by the likes of Chaucer, Shakespeare, and Milton is dustily conventional, a cultural tradition that we''re obliged to read (or compelled to disavow) but that has little relevance to our lives today. The goal of this class will be to persuade you, to the contrary, that the literature written during the period beginning with Chaucer''s Canterbury Tales in the late 14th century and ending with Milton''s Paradise Lost in the 17th century constitutes one of the most exciting and experimental moments in literary history, one that offers uniquely relevant lessons for contemporary thinking about community and storytelling, narrative and memory, truth and perception, race and power, as well as gender and sexuality. At the same time, we will explore what is productively strange, challenging, and even alienating about these texts from the past, measuring how their distance from us provides unique opportunities for thinking. We will also examine how authors such as Chaucer, Shakespeare, Spenser, and Milton came to constitute the foundation of the English literary canon, and how this canon has been used to advance (or to critique) English national and colonial ideologies. Together we’ll explore a set of analytic concepts and strategies for interpreting their unique texts that will make you a more sensitive, precise, and persuasive reader and writer.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(892,2022,1222,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-288','<div class="desc"> <p>Monsters and Monstrosity: literature is rife with portraits of monsters and monstrosity. From Homer''s <em>The Odyssey</em> and Grimm''s fairytales, to Mary Shelley''s <em>Frankenstein </em>and Salman Rushdie''s <em>Shame, </em>monsters challenge our everyday ideas about normality. Situated between the animal and the human, monstrous creatures are ciphers for difference that force us to consider what we regard as culturally abject or grotesque, as well as alluring. That these mythical figures continue to fascinate even as they frighten, is suggestive of their symbolic power in embodying both our latent desires and prohibitions. This course will explore the emergence of the monstrous aesthetic across several genres (epic, drama, novel, poetry, film) and periods (Renaissance to contemporary) to probe the shifting terrains of sexual, racial, and cultural otherness that monsters represent. Along the way, we will ask critical questions that arise from the study of monstrosity. What, for instance, separates monsters from humans? How does monstrosity define our notions about beauty and ugliness, desire and disgust? Does the monster appear each time under a different guise? If so, to what extent does it reshape our sensibility about what is socially abnormal? What can monsters teach us about the hopes and apprehensions of the cultures and times to which they belong? Ultimately, we will seek to understand how and why these ferocious figures also elicit sympathy in us toward those markedly unlike ourselves. Our reading list includes works by: Alfred Tennyson, William Blake, R.L. Stevenson, Mary Shelley, Patricia Highsmith, among others.</p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(893,2022,1223,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-289','<div class="desc"> <p>This survey grapples with the centrality of war to American literature--indeed, to American life. The course moves chronologically through Early American and the American Revolutionary Wars and ends with the War on Terror. We will examine the strengths and limits of depicting war through lyric poetry, short epic poetry, political pamphleteering, oratory, autobiography, and the novel. In addition to considering literary forms, this course considers what understudied voices have to say about what leads to war, the experience of war, and its aftermath. Our readings will include Phillis Wheatley, Timothy Dwight, Philip Freneau, Walt Whitman, Ernest Hemingway, Zora Neale Hurston, Philip Metres, and Solmaz Sharif, among others. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(894,2022,1224,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-290','<div class="desc"> <p>This course will introduce students to contemporary critical methodologies in literary studies. Students will engage a wide range of critical approaches to help ground their subsequent study of literature across the English department curriculum. By studying influential works of theory and criticism, students will become familiar with the historical genesis of literary studies, with special attention to the political, social, and other institutional factors informing the rise of particular methodologies in the academe. We will trace these critical genealogies so as to recognize and participate in the fullness of literary studies.</p> </div>','One First Year Seminar, WRD 201, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(895,2022,1226,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-341','<div class="desc"> <p>This course interrogates the crucial role of the law in British imperial governance by reading colonial legislation and court proceedings alongside works of 19th and early 20th century literature. Doing this allows us to examine how dominant legal paradigms were disseminated in the era''s cultural production and, in turn, how cultural ideals reflected in literature were materially implemented through the law. In addition, we will look at how literature often provided a viable means of contesting the normative terms of the law. </p> <p><strong>Major Requirement Met</strong>: Group II/IV</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(896,2022,1229,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-370','<div class="desc"> <p>Topics vary. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Trauma and Literature</strong></p> <p>How is trauma narrated? Can literature convey intense personal and collective suffering? Is our understanding of pain cultural? This course considers psychoanalytic ideas of historical and personal trauma reflected in literary works of the modern period. Our study will be interdisciplinary, considering how powerful concepts in the hermeneutic of psychoanalysis (repression; repetition compulsion; abjection; misrecognition; lack; affect etc.) have been generated by literary works, as well as challenged and absorbed into them. Insofar as traumatic experience produces a subjective breach, we will think about how certain forms and styles of literature are more or less suited to reflect the rupture. </p> <p>We will read formative texts of psychoanalysis (Freud; Lacan; Kristeva; Foucault and others) and trauma theory (Caruth; Silverman; Fanon; Nandy). Our survey of literary works includes texts by Jean Rhys, Toni Morrison, Han Kang, Teju Cole, among others. Core Requirement: Global Connections.</p> <p><strong>Major Requirement Met:</strong> Group III/IV</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(897,2022,1230,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-382','<div class="desc"> <p>The focus of this course is the writing of short fiction, though also where fiction might overlap with—and necessitate elements of—nonfiction, documentary, poetry. Students will build upon the foundations they established in prior writing workshops, while continuing to test the boundaries of their practice. Students will generate new work constantly— in sketchbooks, exercises, and story drafts—based on and inspired by readings, and especially their own preoccupations, curiosities, and experiences. We will read and discuss texts that both illuminate and complicate various formal possibilities, including by Etel Adnan, Jenny Boully, John Keene, Malika Mokeddem, Scholastique Mukasonga, Juan Rulfo, Sophia Terazawa, Jackie Wang, among others. And we will share and discuss our work in a workshop format. The discussions will be oriented towards asking questions, problem-solving, developing a generative relationship to revision, and towards challenging each other to go deeper into particular, perhaps unexpected, areas and aspects of our writing. Open to third- and fourth-year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(898,2022,1231,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-390','<div class="desc"> <p>The Junior Seminar is a small, discussion-oriented seminar required of all English majors, emphasizing advanced critical approaches to a literary topic. Enrollment is restricted to English majors who will pass the college''s Second-Stage Writing Requirement by satisfactory completion of the course writing requirements. Topics may vary year to year.</p> <p><strong>The Animal</strong></p> <p>This seminar will examine literary, filmic, and theoretical representations of the animal. Questions about the human as animal, and at the limit of animality, will be implicit in our discussion. Over the course of the semester, we will evaluate how the animal has been theorized and represented from the nineteenth century to the present. We will also consider the ways in which the animal has served as a cypher for exploring the category of the human. While the figure of the animal has provided a counterpoint to visions of humanity for centuries, emerging technologies and ideas about human consciousness have inflected the conversation in new and important ways. In what ways, for example, does contemporary technology compel us to reevaluate the distinctions between animal and human, on the one hand, and animal and object, on the other? The course will consider works such as Han Kang’s The Vegetarian, Werner Herzog’s Grizzly Man, Indra Sinha’s Animal’s People, and H.G. Wells The Island of Doctor Moreau.</p> <p><strong>Laughter and Non-Representation</strong></p> <p>While Aristotle is reputed to have written a treatise on comedy to match his famous discourse on tragedy, <em>The Poetics</em>, this is hard to believe as, in all his works, he shows almost no sense of humor. This first absence does not seem to have been filled in the many centuries that have followed. Both in number and quality, modern treatments of laughter seem inadequate. This weakness is perhaps because the funny is constitutively unavailable to rational representation. This class will explore laughter as exactly the embodied symptom that arises out of the intrinsic inadequacies of representation. After a quick critique of traditional theories of mimesis, we will explore the generation of laughter through various contemporary theories and attempt to understand its function for the liberation of the unrepresented in works thought funny, from Laurence Sterne to Ishmael Reed. Open only to junior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(899,2022,1232,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/400/engl-490','<div class="desc"> <p>In this course, seniors will design and carry out advanced research projects in areas of their own interests. Seminar meetings will be devoted to discussion of a core group of theoretical and/or historical texts (varying from year to year), and to practical issues of sophisticated literary critical work. The course will result in a substantial critical paper, a version of which will be presented at the Spring Senior Symposium, in satisfaction of Occidental''s Comprehensive requirement. Open only to senior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(900,2022,1233,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-208','<div class="desc"> <p>What does it mean to say that America is a "nation of immigrants?" This course explores the creation of America through the arrival of diverse peoples from five continents over several centuries. Topics include: the legal and political foundations of U.S. citizenship; the creation of the U.S.-Mexico border; the origins of illegal immigration; ethnic and diasporic identities; state power and resistance; popular culture; social movements; and the importance of race, as well as gender and sexuality, in shaping immigration policy and its enforcement. Special attention will also be given to exploring the diversity of immigrants'' experiences in America over time.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(901,2020,1234,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/300/hist-359','<div class="desc"> <p>This course traces the history of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire to provinces of northern Mexico and finally to the southwest region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, and nationalism. With particular attention to issues of race, gender, place, and power we will examine the Mexico-U.S. borderlands through Chicana/o history, Mexican history, and U.S. Western history as well as through fiction and art that explores the themes of boundaries, the body, and space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(902,2022,1236,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/200/kine-298','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Prior to enrollment, students are expected to have a basic background in Kinesiology and/or public health (e.g. KINE 104). No previous research experience required. Students are permitted to repeat KINE 298 for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(903,2022,1237,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-398','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Enrolled students will assume leadership responsibilities in course projects (e.g. become course liaison with community partners, develop research proposals, manage course mini-projects etc.). Can be repeated for credit.</p> </div>','KINE 298, KINE 307, and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(904,2022,1238,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ling-linguistics/300/ling-355','<div class="desc"> <p>This course provides an overview of the field of sociolinguistics. We will discuss language in its social context, and will examine how social and contextual factors influence language choice. Both quantitative methods, as well as qualitative methods, will be discussed.</p> </div>','LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(905,2022,1239,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/ensembles/musc-128','<div class="desc"> <p>This course will serve as an intensive laboratory component to the Occidental jazz program by having students learn the fundamentals of jazz theory including the following: extensions of common practice tonality; modes; form; notational practice and reading from charts; basic arranging and instrumentation; and transcription. Weekly written theory and listening assignments will be supplemented by performance assignments. In class students as well as instructor will critique one another''s performances. Permission of instructor required.</p> </div>',NULL,'MUSC 127 ',NULL);
INSERT INTO course_descriptions VALUES(906,2022,1240,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-215','<div class="desc"> <p class="sc-BodyText">The history of opera is a history of the continuous reinvention of a genre in order it to accommodate the time place and tastes of its audiences; as such opera provides a lens for studying cultural intellectual political and economic history. With now even non-operatic companies like the Los Angeles Philharmonic staging operas in Disney Hall opera has in the past three decades especially become a terrific lens for studying Los Angeles.This course will study opera as delimited by its production and reception in Los Angeles over the past century. We will research what operas were first produced in Los Angeles where and for what audiences and how the production and reception of opera and later zarzuela evolved over the course of the twentieth century and into the new millennium as Hollywood directors such as Woody Allen and William Friedkin have turned to directing opera. Students will attend operas principally at LA Opera our community partner but also at Long Beach Opera the Los Angeles Philharmonic and other SoCal venue.</p> </div>','Sophomore standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(907,2022,1241,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/100/musa-100','<div class="desc"> An introduction to the use of the Occidental electronic music studio and the creation of electronic music with synthesizers, computer and digital recorders. Graded on a Credit/No Credit basis only. May be repeated for credit. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(908,2020,1242,'http://oxy.smartcatalogiq.com/en/2019-2020/Catalog/Course-Descriptions/MUSA-Music-Applied-Study/100/MUSA-102','<div class="desc"> <p>Basic keyboard technique at the beginning through lower intermediate level. Fee: $195. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(909,2022,1243,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/100/musa-103','<div class="desc"> <p>An introduction to classical guitar including, basic technique and musicianship. The traditional repertoire as well as 20th century and flamenco will be explored. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(910,2022,1244,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/100/musa-104','<div class="desc"> <p>A further exploration of classical guitar, with emphasis on a thorough treatment of musicianship, technique, and expansion of the repertoire for the guitar soloist.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(911,2022,1245,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/100/musa-105','<div class="desc"> <p>The Alexander Technique helps students move naturally. They learn to prevent excess tension and replace it with a more effectively balanced movement pattern throughout the body. Does not satisfy Music Major applied music requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(912,2022,1246,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-201','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing/singing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(913,2022,1247,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-202','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(914,2022,1248,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-203','<div class="desc"> <p>Beginning to advanced instruction in improvisation, contemporary harmony, and reading lead sheets. Recommended for aspiring producers, composers, arrangers, and jazz or commercial keyboardists as a follow-up to MUSC 109. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a zero-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
