INSERT INTO course_descriptions VALUES(962,2022,1300,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-362','<div class="desc"> <p>At the turn of the century a series of discoveries transformed the ancient study of cosmology into a rigorous and well-tested theory of the universe. After a brief introduction to general relativity the equations governing the evolution of the universe will be developed and explored. Evidence in support of this standard model of cosmology and consequences will then be presented including supernovae standard candles the cosmic microwave background big bang nucleosynthesis dark matter and early-universe physics. The course will conclude with a presentation of recent topical subjects in this exciting field of study.</p> </div>','PHYS 117 and PHYS 240, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(963,2022,1301,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/400/phys-490','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(964,2022,1302,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-202','<div class="desc"> <p>This course examines how gender influences who participates in the American political process, from voting to campaigning and holding elected office. The course also examines how public policies are gendered in their design, implementation, and outcomes. The course adopts an intersectional approach, asking how gender interacts with other identities, including race, class, ethnicity, sexual, and disability, to fully understand how ideas about masculinity and femininity shapes access to political power in American society.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(965,2022,1303,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-204','<div class="desc"> <p>Students in this course will analyze historical and contemporary election campaigns in the United States, exploring such issues as the role of money, media, public opinion, voter registration laws, voter suppression, campaign strategy, staffing, and other topics. They will also examine the role of identity, alternative electoral systems and campaign reform options. The course will offer a particular focus on the most current election season, including campaigns for president, Congress, governor positions, and others. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 203 ',NULL);
INSERT INTO course_descriptions VALUES(966,2022,1304,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-212','<div class="desc"> <p>This community-based learning course introduces advanced undergraduates (sophomores juniors and seniors) to the study of voter mobilization via an ethnographic research project in Los Angeles. As part of the Fall congressional elections students will partner with community organizations in Los Angeles that are developing non-partisan Get Out the Vote (GOTV) initiatives. These organizations are based primarily in Latino/a and Asian-American communities. Students will study and evaluate these GOTV initiatives with the goal of analyzing assessing and reporting back on best practices in GOTV initiatives especially in ethnic minority communities. Course time will be divided between the classroom and the field. Students will receive training in and learn to critically evaluate field research methods-especially in the area of qualitative ethnographic research (interviews and observations). Students will also learn about the strategies practices and pitfalls of voter mobilization practices in urban communities. Offered Fall semester in even-years to coincide with the national elections. <em>Open to sophomores juniors and seniors with permission of the instructor only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(967,2022,1305,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-227','<div class="desc"> <p>A comparative analysis of the history culture and contemporary politics of the four countries in the dynamic East Asian region: China Japan Korea and Taiwan. This course will also cover the political economy of the East Asian industrialism.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(968,2022,1306,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-256','<div class="desc"> <p>This course will introduce students to several core analytical approaches in moral and political philosophy including consequentialism utilitarianism distributive justice freedom autonomy and an ethics of care. Students will apply these approaches to case studies in ethical decision-making in politics and policy and students will weigh arguments in favor or against specific courses of action. As such this course bridges readings in moral and political philosophy with "real world" problems confronted by policymakers and leaders. In evaluating resolutions to these problems students will sharpen their critical-thinking and decision-making skills. This is a course in applied ethics with material drawn both from philosophy and from policy.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(969,2022,1307,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-270','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, POLS 272) simultaneously. Students will participate in the daily activities of a campaign for United States President or United States Senate in a key "battleground" state. Students will gain experience in the highest level of politics and gain an understanding of how a national presidential campaign or a statewide United States Senate campaign is operated. Students will learn about political strategy voter contact and turnout messaging and polling communications volunteer recruitment and team-building fundraising and other key aspects of campaigns. The internship will involve working full-time (a minimum of 40 hours a week) from the first day of class until Election Day. Following that ten-week campaign fieldwork internship students will return to campus and participate in two seminars as part of Campaign Semester. Campaigns involve long hard days. The staff that students will work with will typically be working at least 14-16 hour days. Although students are required to work at least 8 hours a day they are likely to work more. As part of the Campaign Fieldwork Internship students will be required to read three books-biographies of each major party candidate and a book describing previous presidential campaigns. Students will be required to maintain an internship journal that will be handed in at the end of the 10-week internship. The journal will describe their activities (including the projects they work on campaign meetings and events relationship of the campaign to the media and to constituency groups) the internal dynamics and work of the campaign the different roles and tasks of staff and volunteers in the campaigns the way the media reports on the campaign the students'' reflections on these matters and at the end a summary of the campaign outcome. Students will be required to email the supervising Occidental faculty member at least once a week about their activities and reflections. The students will be supervised in the field by a campaign staff member. Students will participate through teleconferencing in a two-hour course meeting with other students and faculty three times during the semester. Students who will be working in different parts of the country will stay in touch with each other as well as with the faculty through Moodle a web-based course management system. The system allows faculty members to post readings facilitate discussions give and receive assignments etc. Students in various parts of the country will thus form a virtual classroom and on-line learning community. Some students may wish to document their experiences on the campaign trail observe events and interview staff and volunteers by making videos. If so these should be posted to the faculty and other students via the internet. Enrollment limited to students participating in the Campaign Semester Program.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(970,2022,1308,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-271','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. In this course which will take place during the last five weeks of the semester students explore theoretical and applied concepts pertaining to United States political campaigns. Students will examine the role of money media candidates interest groups leadership gender race and political parties in terms of who wins and loses elections. Learning will take place through assigned readings professor lectures guest lectures from campaign experts and candidates and peer dialogues. Student learning will be assessed by their contribution to the classroom experience (discussion dialogue) discussion of assigned readings and examinations. Enrollment limited to students participating in the Campaign Semester Program. The program is open to all Oxy students regardless of major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(971,2022,1309,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-272','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. This course entails production of a 25-page research essay addressing a major question pertaining to campaigns in American politics. Each student will work with a professor to craft a high-quality research paper that enters the academic debate on their selected topic incorporates extensive secondary data and existing research and presents original analysis based on the student''s campaign fieldwork. Enrollment limited to students participating in the Campaign Semester Program. Satisfies Junior Writing Requirement.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(972,2022,1310,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-300','<div class="desc"> <p>This course is an introduction to the process of conducting political science research including the formulation of research problems research design collection of data and statistical analysis and interpretation. Participants will learn to analyze political science data using statistical packages in a lab setting.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(973,2022,1311,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-345','<div class="desc"> <p>This course examines constitutional criminal procedure through an analysis of Fourth Amendment constitutional restraints on activities during the investigatory stage of the criminal process. Exploring Supreme Court decisions through doctrinal analysis and simulations the course questions the Supreme Court as a policymaker seeking to balance privacy rights with governmental intrusions.<em> Not open to first year students.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or instructor permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(974,2022,1312,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101, BLST 110, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(975,2020,1315,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/rels-religious-studies/300/rels-305','<div class="desc"> <p>The course will examine the discourses and practices that have shaped gender and sexuality in Islam and Islamicate cultures. The course will explore the articulations of gender and sexuality in Islamic scriptural legal and historical texts from the earliest period to the present placing those ideas and institutions within their broader historical social and political contexts. Special attention will be given to the way gender and sexuality are taken up in Islamicate cultures in the wake of Western imperialism and colonialism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(976,2022,1316,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-230','<div class="desc"> <p>This course examines the family as a social institution in the United States. The course emphasizes sociological and demographic perspectives on the family family change historically and contemporarily and the intersection of the family with social categories such as race and ethnicity sexual orientation gender and class. The course will highlight contemporary changes in marriage divorce and non-marital cohabitation in the United States but will also expose students to sociological thinking about family systems around the world.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(977,2022,1317,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-204','<div class="desc"> <p>In this course, we introduce students to the ways comedy can influence and transform society. We will study scripted as well as unscripted forms of performance, including stand-up, physical comedy, sketch, Teatro Campesino style <em>actos</em>, and faux news shows. Students learn the formal structure of the different comic forms through extensive writing and revision both individually and in collaboration with other students. Students develop an understanding of the role comedy plays in socio-political critique through research of issues about which they are passionate and in the subsequent creation of solo and group work illuminating those issues for their peers in a final cabaret performance. Not open to frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(978,2017,1318,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/THEA-Theater/300/THEA-321','<div class="desc"> <p>We help our students in this course develop the skills to analyze archive and document their creative and technical work; and we introduce them to various techniques for public presentation of the record of their work.</p> </div>','THEA 120 or THEA 175 or permission of the instructor',NULL,NULL);
INSERT INTO course_descriptions VALUES(979,2022,1319,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Encoding Equity: Art, AI, and the Aesthetics of Algorithmic Justice</strong></p> <p>Algorithms—and the human agents who train them—increasingly encode the structure of our world and lived experience. To inhabit an algorithmic present is to inhabit a space saturated with “engineered inequity” (Ruha Benjamin) and “algorithms of oppression” (Safiya Noble). Today, algorithms make determinations about housing, hiring, policing, incarceration, and the distribution of state social benefits. Despite their purported neutrality, AI systems have repeatedly been proven to exhibit biases that entrench and exacerbate structural inequalities. These models don’t merely make predictions about the world: they actively produce it.</p> <p>Yet, algorithmic decision-making unfolds in the opacity of the “black box,” and engineers themselves can struggle to articulate the logic of its outcomes. This poses a quandary: on the one hand, AI generates far-reaching, material effects that impact individuals and communities on an unprecedented scale. At the same time, algorithmic operations are concealed within a “black box,” hidden from view and made invisible.</p> <p>Over the last ten years, a growing cadre of artists has begun to confront this phenomenon in their practice. Their works stage interventions into AI systems, and envision how those systems might function otherwise. This class will attend to work by artists including Joy Buolamwini, Kate Crawford, Stephanie Dinkins, Mandy Harris Williams, Jennifer Moon, Mimi á»ná»¥á»ha, and Suzanne Kite. Their pieces will be paired with work in media studies and critical race studies by Ruha Benjamin, Safiya Noble, Cathy O’Neill, Virginia Eubanks, Timnit Gebru, and others. Reading across these coordinates, the class will consider how contemporary artists render algorithmic bias visible and imagine speculative futures optimized for equitable outcomes.</p> <p><strong>Japanese Art and Visual Culture in the Americas</strong></p> <p>In 2001, respected art historian Yoshiaki Shimizu contributed an article entitled “Japan in the American Museums: But Which Japan?” (<em>Art Bulletin</em>, 83:1 [March 2001], 123-134). The article questions what defines Japan and Japanese art by examining exhibitions of Japanese art at American museums as well as concordances and contradictions over the art of Japan among agents and players of art. The questions that the article posed are invigorating and valid nearly twenty years after its publication, but they deserve some updates. Inspired by Shimizu’s thematic approach, this course will consider Japanese art and visual representations of Japan in the Americas and expand the scope of the art of this day. The class looks at Japanese art and artists in Mexico, engages more actively with Japanese and Japanese American art in Los Angeles, and critically embraces popular culture and subculture. Other topics to be examined include Japonisme, new and creative woodblock prints, folk craft and modern design, abstract painting and performance, and women artists in New York as well as dealers, collections, and collectors of Japanese art in Los Angeles. <em>Additional </em><em>Core Requirement Met: Regional Focus (CPRF).</em></p> <p><strong>Materials and Materiality in Japanese Design</strong><br/> This course explores key materials and materiality in Japanese art and design. Each class is structured around a different type of material or a combination of materials, such as rock, paper, wood, metal, earth, silk, and food. We will look at these materials or uses of them cross-historically rather than chronologically—as an embodiment of spiritual/religious practice, representation of social class, identity of local community and environment, and/or artistic methodology, in addition to examining them simply as mediums and respective production techniques. <em>Additional </em><em>Core Requirement Met: Regional Focus (CPRF).</em></p> <p><strong>Art and Nuclear Technology, Destruction, and Contamination</strong></p> <p style="margin-left:0px; margin-right:0px">This course explores art and its relationship to nuclear technology, destruction, and contamination. The primary focus will be on postwar Japan but we will also investigate Disneyland and its link to the Atoms for Peace campaign, visual projects regarding nuclear accidents at Chernobyl and Fukushima in addition to the impacts of unclear technology, test sites, and nuclear waste isolation sites on image-making. Themes to be examined include Cold War culture and politics, art and disaster, trauma and memory studies, documentary art and art of witness, censorship, invisibility, activism, and dark tourism. Over the course of the semester, we will look at a variety of artistic genres and mediums, such as paintings, sculptures, photographs, installations, performances, animations and films, comics and picture books, designs, and public monuments as well as exhibitions and world expositions. <em>Additional </em><em>Core Requirement Met: Regional Focus (CPRF).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(980,2022,1320,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Imag(in)ing</strong><strong> War and Disaster in Modern and Contemporary Japan</strong></p> <p>This course explores how practitioners of art and visual culture have responded to physical and psychological damages that were caused by wars and disasters in modern and contemporary Japan. The course loosely follows a chronological order and a thematic framework. We will look at expansive materials, including colorful and playful woodblock prints (<em>ukiyo-</em>e) of natural disasters; prints and memorabilia of the Russo-Japanese war (1904-05); topography and the building of the Yasukuni Shrine and its exhibitions; the birth of the avant-garde and its relation to the Great Kanto Earthquake (1923); war documentary paintings and propaganda during WWII; atomic bomb photographs and memorials; reportage painting of the 1950s; anti-art and non-art movements of the expanded 1960s; <em>kawaii </em>(cuteness) and monstrosity in manga and animation; and socially engaged art about Fukushima. The course aims to enable students to analyze how politically inspired or socially engaged art developed in modern and contemporary Japan. <em>Additional Core Requirements Met: Regional Focus (CPRF).</em></p> <p><strong>Who Owns Art? </strong></p> <p>As art objects - especially those from antiquity - have become increasingly valuable, as both commodities and as national treasures, questions as to who owns art and who is best to care for these objects are essential to museum curators, academics, and politicians. There are several debates over who owns art of ancient civilizations like Greece and India. Do treasures like the Parthenon sculptures at the British Museum belong to Greece and should they be returned? Or should they remain in the museum where more people have access to them? This seminar will introduce students to laws enacted by UNESCO (United Nations Educational Scientific and Cultural Organization) to protect world, cultural, and national heritage, as well as to the examination of museum collecting policies in America. Specific cultural patrimony cases will also be examined and discussed. This seminar is for students who are interested in learning more about cultural patrimony, art law, and museums.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(981,2022,1322,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-370','<div class="desc"> <p>This course addresses contemporary approaches to ecology and conservation, with emphasis on ecological fieldwork in diverse locations. The course will have a regional focus, with the possibility of emphasis on desert, mountain, coastal, or tropical ecosystems. Students will conduct field research, including the design, implementation, data analysis, and presentation of research projects. Emphasis will be placed on the impacts of anthropogenic change on native ecosystems. </p> <p>This class has been designed to allow for meaningful field study in the region. Each section of this class meets for one full day per week to allow for fieldwork. The course will include overnight field trips, including several extended trips on weekends and outside of class hours, potentially during fall break.</p> <p>If one of the lab sections does not fill to capacity, that section may be closed and students asked to enroll in the other lab section.</p> </div>','BIO 260, BIO 270, GEO 225, or permission of instructor ','BIO 370L ',NULL);
INSERT INTO course_descriptions VALUES(982,2022,1323,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-370l','<div class="desc"> <p>The goal of the lab portion of this course is to enable students to conduct immersive field research on the ecology of natural systems. Contemporary techniques and tools will be used to monitor and assess biodiversity of natural communities and the extent of anthropogenic impact on these systems. Field trips will be conducted outside of assigned class times. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 370',NULL);
INSERT INTO course_descriptions VALUES(983,2022,1324,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-353','<div class="desc"> <p>An introduction to information theory that will focus on: (1) data: transmission, storage, lossless data compression (such as ZIP and LZW), lossy data compression (found in JPG or MP3 formats), channel capacity; (2) coding: optimal codes, error correcting codes, the several coding theorems of Claude Shannon; (3) measures of information: entropy, relative entropy, relation between entropy and information content; and (4) application topics that vary from year to year and might include: signal processing, image processing, pattern recognition, cryptography and data security, quantum computing, data analysis, and more.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','MATH 210 and MATH 214 or COMP 149; recommended MATH 146 or MATH 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(984,2020,1325,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-232','<div class="desc"> <p>This course introduces the methodologies and key theories of cultural studies, focusing on analyses of popular culture and subcultures. Readings will include selections from Roland Barthes, Walter Benjamin, bell hooks, Jean Baudrillard, Guy Deborg, Stuart Hall, Matthew Arnold, Raymond Williams, J. Halberstam, Michel de Certeau, Henry Louis Gates, Inderpal Grewal, Oliver Sacks, and others. We will focus on non-traditional academic disciplines and media, including: television studies, new media theory, performance studies, history of science, fashion, cartoons, built environments, slang, and fan culture, with the intention of honing rigorous research skills and critical argumentation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(985,2022,1326,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-340','<div class="desc"> <p>In this course, students learn how to do ethnographic research and writing by conducting exercises in participant-observation on or near campus. We review the history of the ethnographic method and its relation to anthropology and the colonial encounter. We also discuss what makes an ethnography critical, and the tensions between ethnography, sympathy, and critical theory. Authors we read include Malinowski Geertz, Delmos Jones, Dorinne Kondo, Renato Rosaldo, Ruth Behar, Jim Thomas, and Kamala Visweswaran.</p> </div>','Any 200-level CTSJ class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(986,2022,1327,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-229','<div class="desc"> <p>After a review of the historical, legal, and conceptual underpinnings of the international protection of human rights, students in this course will learn about human rights and mechanisms for their protection within the context of the United States and Latin America. Students will discuss key situations from the last half century involving challenges to human rights, including the phenomenon of disappearances common in Argentina and Chile in the 1970''s, violations of human rights during leading up to and during civil conflicts in Central America, and the impact of neoliberal economic reforms on human rights in the region. Students will explore the application of the death penalty in the United States, United States foreign policy on human rights in the Americas during the Cold War, and the claims of human rights abuse by the United States during the War on Terror. They will also have a chance to examine the United States from a double perspective: on the one hand as a key country with a major interest and impact on human rights conditions in Latin America, and, on the other, as a country with its own policy areas of struggle and progress.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(987,2022,1328,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-232','<div class="desc"> <p>Topics may vary semester to semester. </p> <p><strong>Transnational Social Movements</strong></p> <p>This course focuses on contemporary social movements with particular attention to transnational information flows. Concentrating on strategies, methods, and approaches to oppositional action, the course will study the global rise in the civilian mobilization against leaders and states perceived as corrupt and or unrepresentative. For example, organizations like <em>Black Lives Matter</em> have influenced and were influenced by <em>Rhodes Must Fall</em> in South Africa. Similar movements in Serbia, Egypt, China, Czechoslovakia, and Iran where unarmed people opposed powerful states encouraged the student protest movements in Hong Kong. Writers like Gene Sharpe, Erica Chenoweth, and others who have written extensively about non-violent means of protests, have influenced many of these contemporary organizations. Academic perspectives on social movements and revolutions will frame the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(988,2017,1329,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/200/DWA-255','<div class="desc"> <p>The course will use popular culture allegories as a strategy for building a complex understanding of the nature of transnational terrorism in the post-9/11 era and challenges faced by policy makers in this arena. It will begin with a review of key approaches and concepts in security studies and will confront different definitions of terrorism. The course will then go on to discuss certain policy responses that have elicited particular concern such as torture assassination surveillance programs detention without trial and deliberate entrapment. Cyborg Zombie and Lord of The Ring allegories will serve to illustrate different conceptual and practical approaches to terrorism. The course will conclude with an examination of the different implications for policy decision making suggested by the use of different allegories.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(989,2022,1330,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-285','<div class="desc"> <p>This course aims to introduce students to both analytic and normative approaches to the study and practice of diplomacy in international politics. In the first part of the course, we will chart the evolution of diplomacy from a tool of statecraft in the modern states system, to a practice of mediating disputes and estrangement in international society. The second part of the course is devoted to examining a series of historical case studies illustrative of the successes and failures of modern diplomacy. The last part of the course considers the utility and limitations of contemporary diplomatic practices for major international trends and developments, such as: globalization, militarism, financial crises, extremism, and environmental degradation. This course is, above all, designed to help students think, talk, and write in an informed and critical manner about complex and seemingly intractable global issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(990,2022,1331,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-327','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women in the United States, this course is designed as an overview of major theories, trends, and debates on the topic of gender in the labor market. We will examine gender differences in economic outcomes through the use of economic models, including feminist extensions and critiques of such models. Topics include: the family as an economic unit; gender differences in education, work, training, and income; and the economics of marriage, divorce, and fertility. Permission of instructor required for students who have successfully completed ECON 328 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(991,2022,1332,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-240','<div class="desc"> <p>This course will examine the physical and chemical process associated with geologic events that occur on the human time scale and harm society: earthquakes, volcanism, and mass wasting. Focusing on events from California, the course will include in-field examinations of local geological examples, as well as quantitative and qualitative evaluation of geophysical and geochemical datasets associated with well-documented case studies. <em>Includes one three-hour laboratory per week and required field trips.</em></p> </div>','GEO 105 or GEO 106 ','GEO 240 ',NULL);
INSERT INTO course_descriptions VALUES(992,2017,1333,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/GEO-Geology/200/GEO-240L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(993,2022,1334,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-315','<div class="desc"> <p>Study of the processes of sedimentation, the properties of sedimentary rocks, and the use of stratified sedimentary sequences for correlation, dating, and interpretation of depositional environments and geologic history. Course includes field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>','GEO 225; and GEO 105 or GEO 106 ','GEO 315L ',NULL);
INSERT INTO course_descriptions VALUES(994,2022,1335,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-315l','<div class="desc"> <p>Field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'GEO 315',NULL);
INSERT INTO course_descriptions VALUES(995,2022,1336,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-324','<div class="desc"> <p>Building on material learned in GEO 225 and GEO 305, this course involves the mapping of more complex areas. Fieldwork is the heart of this course and full participation in the 4-6 days of fieldwork is required. May be taken twice for credit.</p> </div>','GEO 225 and GEO 305 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(996,2022,1337,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/200/germ-280','<div class="desc"> <p>The onset of industrialization in the 19th century created the modern metropolis and the angst and attraction of the lifestyle that went with it. In this course, we will examine how writers and intellectuals of the late-19th and early-20th century described their experience of this new urban environment - analyzing their discoveries and discontents. In addition to fiction by Rainer M. Rilke, Emile Zola, Irmgard Keun, Alfred Döblin, Walter Benjamin, and others, we will also discuss seminal texts by architects, urban planners, and theorists, and look at how visual artists and filmmakers depicted the emerging streetscape of modernity. Students will have the opportunity to explore the impact of modern urbanization in a contemporary and global context through field trips and class projects. The course is taught in English. This course is not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(997,2022,1338,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-300','<div class="desc"> <p>The Romans, to a large extent, adopted the literary genres of the Greeks before them. In Roman hands, however, the genres of epic and tragedy evolved to reflect contemporary literary tastes and the emergence of Rome as the dominant power in the Mediterranean. In this course, we will consider the themes of war, love, and sacrifice in Latin literature by reading Vergil''s <em>Aeneid,</em> the little <em>Iliad</em> in Ovid''s <em>Metamorphoses,</em> and Seneca''s <em>Trojan Women</em>. Students will explore the differences between "Golden and Silver Age," Latin epic, and round out their examination of the course''s themes in the context of the tragic genre. No knowledge of Latin is needed (but is certainly welcome).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(998,2022,1340,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-392','<div class="desc"> <p>This course is intended to introduce students to common models used in biology. A variety of models, in terms of both biology and mathematics, will be covered. Biological topics include: action potential, generation genetic spread, cell motion, and pattern formation and circulation. These topics span a range of mathematical models, as well as including finite difference equations, and differential equations both linear and non-linear. The focus will be on model analysis and the translation between the mathematical language and the biological meaning. Such analysis will be done both quantitatively and qualitatively. Towards this end, topics seen in previous mathematical courses such as eigenvalues, phase portraits, and stability will be revisited. Relevant biology will be presented with each model. The course will be project based.</p> </div>','MATH 212 and MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(999,2019,1342,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-205','<div class="desc"> <p>An examination of the problems in moral and political philosophy created by and resulting from the historical events surrounding Athens in the 5th Century B.C. The course will examine historical writings (Herodotus Thucydides) Greek tragedy Pre-Socratic thought and Plato and developments in art with as much reference as possible to their social and economic contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1000,2022,1343,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-280','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics credits for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> will work four full days per week in an internship in a political office non-profit corporation or for-profit company engaged in political or policy work. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1001,2022,1344,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-281','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course develops leadership skills through the themes of public speaking professional writing networking interviewing and giving and receiving feedback. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirements for the major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 280 and POLS 281 and either POLS 282 POLS 283 POLS 284 POLS 285 or POLS 286) simultaneously. </p> <p>Students enrolled in the Washington Internship Institute in D.C. are required to take a political leadership seminar that explores how active global citizenship can advance career goals. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1002,2022,1345,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-285','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on politics and public policy in the Washington D.C. context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(1003,2022,1346,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-286','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on international relations. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills International Relations requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281 and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously.</p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C</strong>. are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(1004,2022,1347,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty housing transportation crime and violence pollution racial segregation and neighborhood change. It also examines how power is exercised by different groups including business citizens'' groups community organizations unions the media mayors and other government officials. The course will also examine the role of city planning and planners conflict and cooperation between cities and suburbs problems of urban sprawl loss of open space water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe Canada and the developing world. Public policies to solve urban problems.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1005,2022,1348,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-403a','<div class="desc"> Additional meeting time for Psychophysiology. </div>',NULL,'PSYC 403',NULL);
INSERT INTO course_descriptions VALUES(1006,2022,1349,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-444','<div class="desc"> <p>This course will examine contemporary research on higher-order cognition. Topics will include inductive reasoning deductive reasoning causal reasoning moral reasoning concept acquisition belief formation and analogical inference. Students will read empirical papers representing a variety of experimental methods and a variety of theoretical perspectives.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 200 and PSYC 301, PSYC 302, or PSYC 306 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1007,2022,1351,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-228','<div class="desc"> <p>In this course students will interrogate several overlapping categories of human identity. First we will seek to define the term Chican@ situating our understanding within the historical particularities in which it emerged as well as studying its economic political social and religious implications for U.S. Latin-Americans who identify as such. Second we will investigate the ways in which contemporary Chican@s understand Chican@ and religious identity to be interrelated specifically as a hybridization of Catholic Christianity along with the spiritual traditions of Africa Asia and the indigenous people of the Americas. We will also consider the ways in which Chican@s have looked to their spirituality and religious practices in order to construct narratives of identity belonging community and resistance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1008,2022,1353,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-320','<div class="desc"> <p>This course surveys sociological theories of health illness and medicine. Rather than focusing on the individual body as the site of disease the course examines the role of social context in shaping health and access to the healthcare system across population groups. The course focuses especially on medical intervention and the medicalization of disease social disparities in health and contemporary healthcare changes and challenges in the United States.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1009,2022,1354,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-370','<div class="desc"> <p>This course examines the social phenomenon of human violence. We first consider classical and contemporary sociological theories on violence and violent conflicts and the main sociological definitions of violence used over the last century. We then turn to empirical studies that explore the social processes and societal structures that give rise to the various forms of violence-intrapersonal interpersonal familial collective and political-and nonviolent movements presently observed throughout the world.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1010,2022,1355,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-351','<div class="desc"> <p>A study of Cervantes'' narrative and drama in the context of certain literary trends of the European Renaissance. The course will focus on the Novelas Ejemplares selected parts of Don Quijote and Entremeses and it will explore Cervantes'' treatment of the genres and currents which influenced his art.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1011,2019,1356,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/THEA-Theater/300/THEA-315','<div class="desc"> <p>The American musical presents unique challenges to performers. They act and they sing, and most importantly, they must act while singing. THey also need to understand both the literary and musical meaning of a work of musical theater, and how they two are intertwined. In this course, designed for the novice performer as well as the advanced actor or singer, we focus on introducing students to the art of acting a song. we place character within the context of the music and the story, and explore how the elements of healthy singing (including breath control, phrasing, and placement) express character. Through solo and collaborative selections from contemporary and classic musical theater, we examine the intersection of singing, acting, and movement unique to musical theater. May be repeated once for credit. </p> </div>','At least sophomore standing or permission of instructor.',NULL,NULL);
INSERT INTO course_descriptions VALUES(1012,2022,1357,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-201','<div class="desc"> <p>This course is designed to provide students with an understanding of the environmental factors impacting human and ecological health including consequences of natural and human-made hazards. Environmental health is a rapidly growing and interdisciplinary field that involves both science and public policy. It is integrated into numerous aspects of our lives both directly and indirectly. Topics to be covered include food safety water access and equality pesticides air quality the identification of environmental hazards the assessment of various risks (including exposure to dangerous chemicals used in toys food workplaces and other activities) and the social and biological causes of disease (epidemiology) Students will gain an understanding of environmental health analytical and scientific methods. We will also explore ways that communities and policy-makers seek to address environmental health challenges. A common thread running through the course will be an examination of how exposure to environmental and health risks vary among different population groups in the Los Angeles area in the United States and around the world and the ways that scientific issues become embedded in and inseparable from issues of policy regulation and justice. We will also explore the role of science in environmental policy-making the enforcement of regulations and the efforts of community groups to influence public policy. (Students are encouraged to enroll in Geology 150 a laboratory science that in parallel explores the spatial and geographic dimensions of environmental health.</p> <p>Not open to frosh without permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1013,2020,1358,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-308','<div class="desc"> <p> At the city and county level, Los Angeles is investing in new infrastructure, transit lines, housing, open space, and civic architecture to a degree rarely seen and arguably unprecedented in American urban history. The total public monies already earmarked through ballot and bond measures and other means is approaching $200 billion all told over the next several decades -- with a significant portion to be spent before 2028, when L.A. will play host to the Summer Olympics for a third time. What will these investments mean for the urban fabric, architectural character, and civic identity of Los Angeles? How can they be made in a coordinated, complementary, and efficient manner? How can they promote innovation while also guarding against displacement and the loss of affordable housing and/or the erasure of neighborhood culture and history? The course will be led by Christopher Hawthorne, professor of the practice at Occidental, who after spending 13 years as the architecture critic at the Los Angeles Times was appointed in 2018 by Los Angeles Mayor Eric Garcetti as the city''s first Chief Design Officer. Along with reading deeply into the urban and architectural history of Southern California, students will meet regularly with Hawthorne''s colleagues in city government and hear from key figures involved in shaping L.A.''s built environment and civic future at this pivotal, transitional moment.</p> </div>','UEP 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1014,2022,1359,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-250','<div class="desc"> <p>Writing in the Community may take many forms. Specific topics will vary. Students may repeat once for credit if taken as different topics. Current topics listed below:</p> <p><strong>Writing and the Los Angeles Experience</strong></p> <p>A combination writing workshop and community-based learning course, Writing and the Los Angeles Experience examines how Los Angeles shapes and is shaped by those who write about the city. Readings, class discussions, and writing assignments will engage the work of local writers whose work revolves around the city—such as Paul Beatty, Francesca Lia Block, Luis Rodriguez, and Brando Skyhorse—and the parts of Los Angeles that are central to their experience. Guest speakers and field trips to visit different areas of the city and attend live events will help us explore the way the city influences those who write about it, and the cultural, social, and political forces that make it tick. The work of this course is both critical and creative: students will write about our readings using conventional tools of academic writing and rhetoric, and respond to their own experiences of the city in reflections, stories, or other creative projects. Core Requirement Met: US Diversity and Fine Arts.</p> <p><strong>Professional Writing on Social Issues</strong></p> <p>This course encourages an engaged and dynamic approach to writing studies as it places writing in real-world contexts by partnering Oxy students with nonprofit community organizations in greater Los Angeles. Through these partnerships, students will identify local cultural and social concerns on topics such as homelessness/housing insecurity, poverty, immigration, education, and social activism, which represent the interests of our particular community groups. In this class we will explore a wide range of research and writing strategies common to both academic environments and the professional situations of our community partners, including primary or field research and both individual and collaborative writing projects in professional genres. This course will allow students to see community nonprofit organizations -- plus the cultural social and political issues and rhetoric surrounding them -- from the inside out. The work of this class is thus both scholarly and practical, motivating student learning by enlivening and enriching students'' approaches to writing studies. Core Requirement Met: Global Connections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1015,2022,1360,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-275','<div class="desc"> <p>This course is designed to give students the chance to combine skills in critical analysis and writing with their interests or training in the sciences. Students do not need to have a science background or be majoring in a science field to be successful in this class, but they do need to have an interest in science in order to write about it in compelling ways. The central goal of this course is to develop and refine skills in presenting scientific topics to popular audiences comprised mainly of non-scientists. Course readings and assignments will span a range of scientific fields, including environment and ecology, cognitive science, psychology, medicine and health, and life sciences. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1016,2022,1361,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-286','<div class="desc"> <p>In this course students will learn to combine the reporter''s craft with creative writing skills to produce compelling nonfiction. The class teaches students how accurate, factual stories can more fully convey insight into contemporary issues and the human condition by tapping the power of fictional techniques such as character development, use of dramatic tension, dialogue, and narrative structure. The course develops students'' research, reporting, and interviewing techniques, while focusing on the craft of writing. Using the spectrum of rhetorical devices, students will strive to create well-told stories about who we are, how we live, and the forces that shape our existence. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1017,2022,1362,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-301','<div class="desc"> <p>This advanced composition workshop explores creative nonfiction, a term that encompasses many genres, including memoir, profile writing, personal essay, humor, nature and travel writing, criticism, and narrative journalism, among others. This course will focus on 3-4 genres of creative nonfiction over the course of the semester. Each unit will pair a writing assignment in a particular genre with popular readings from that genre, by authors such as Paula Gunn Allen, Truman Capote, Ta-Nehisi Coates, Junot Díaz, Joan Didion, Audre Lorde, Adrienne Rich, Zadie Smith, and David Foster Wallace. The course will encourage experimentation while also paying close attention to audience, genre conventions, and other principles of successful writing. The workshop format relies on extensive peer review and revision, and each student will produce a capstone piece at the end of the semester after revision based on peer and instructor feedback. Prerequisite: student must have passed the first-year writing requirement and/or WRD 201.</p> </div>','Student must have passed the Core Writing Requirement or taken WRD 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1018,2020,1363,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/300/amst-375','<div class="desc"> <p>This seminar explores the social politics of race through the lens of color-conscious and color-blind ideologies. Topics focus on the construction of race; racial identity, development, and socialization for differently positioned group members; psychological impact of race and racial identification for academic achievement, esteem, and health; contemporary research on colorblind and color conscious ideologies and primes; and social policy. Interdisciplinary readings include psychological theory and research (Steele''s <em>Whistling</em>,Vivaldi Sue''s <em>Microaggressions</em>, contemporary journal articles), critical theory (Delgado and Stefanic''s "Critical Race Theory"), and sociology (Bonilla-Silva''s "Racism without Racists"). Heavily discussion-based.</p> </div>','Any American Studies course at the 200-level or above or either PSYC 321 or PSYC 323 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1019,2017,1364,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-254','<div class="desc"> <p>This course critically analyzes how the museum enterprise reflects and informs public culture. Students will gain an understanding of historical and current trends in museum studies and how these movements are impacted by shifting professional and popular standards. Topics include the collection and display of human beings as objects the politics of national museums racist memorabilia indigenous curation methods commodification and consumerism repatriation censorship and contested ideas about authenticity and authority. Case studies are drawn primarily from The United States and Canada and include the plantation museum American Indian cultural centers lynching postcards the Holocaust Museum and performance art. The relationship of the museum to a diverse public with often-contested agendas will be explored through class discussions independent student projects and written assignments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1020,2017,1365,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/200/ARTH-282','<div class="desc"> <p>The rise and fall of National Socialism is one of the most intensively studied topics in European history. Over six decades after its collapse Nazi Germany continues to fascinate the general public and with good reason. Although the fascist state lasted only for twelve years it started history''s most destructive war while committing crimes of unprecedented proportions. For the most part it did so with the acquiescence of the German public. This class will investigate the rise of National Socialism as a political social and cultural phenomenon. The central focus will be on the decisive role of film and the visual arts as most popular means of mass manipulation.</p> </div>','1st year students cannot enroll in this class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1021,2022,1366,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-227','<div class="desc"> <p>This class is an introduction to the historical art of letterpress printing using design elements with text and image. Students will complete a collaborative artist book with hand binding and original imagery using typographic design, hand typesetting, and letterpress printing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1022,2022,1367,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-336','<div class="desc"> <p>This course will examine interactions between the human host and infectious microbial pathogens, including bacteria, parasites, viruses, and fungi. Emphases will be placed on mechanisms of microbial defense (virulence factors), immune evasion and adaptation strategies, as well as the molecular and cellular mechanisms of the innate (immediate) response of the host in both immune and non-immune cells. Laboratory includes techniques used in clinical microbiology labs, including culture and identification techniques, as well as cell biology techniques. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221, BIO 224, BIO 226, or permission of instructor ','BIO 336 ',NULL);
INSERT INTO course_descriptions VALUES(1023,2022,1368,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-336l','<div class="desc"> <p>Laboratory includes techniques used in clinical microbiology labs, including culture and identification techniques, as well as cell biology techniques. Graded on a Credit/No Credit basis.</p> </div>',NULL,'BIO 336',NULL);
INSERT INTO course_descriptions VALUES(1024,2022,1369,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-301','<div class="desc"> <p>An introduction to the principles of chemical thermodynamics, kinetics, and spectroscopy, with a focus on applications to biochemical systems.</p> </div>','CHEM 221, Calculus 2, and PHYS 115 (or equivalents) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1025,2022,1371,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> </div>','COGS 101, four units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1026,2022,1372,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-255','<div class="desc"> <p>This course will examine intersecting and overlapping categories of "difference" by focusing on the lives of women of color. By looking at conditions that shape race, sexuality, gender, class, and cultural differences, this class will critically examine multiple discourses surrounding feminism, anti-racism, heteronormativity, and critiques of imperialism. We will consider contexts of individual and collective work for social change. Using personal essays, stories, scholarly writings, artistic works, music, film, and other media, the course will look at sources that women of color draw from to ground themselves and their activist work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1027,2020,1373,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-335','<div class="desc"> <p>This course examines the emergent field of queer of color critique. Combining woman of color feminism with queer theory, queer of color critique analyzes intersections of race, gender, sexuality, and class through interdisciplinary methodologies. This course will engage essential background and formative essays, including: the texts of Kimberlé Crenshaw, Gloria Anzaldúa, and Chandra Mohanty; cultural instances of race and sexuality''s crossings in work by James Baldwin, Cheryl Dunye, and Issac Julien; and recent critical work by such contemporary theorists as Roderick Ferguson, Jasbir Puar, and José Esteban Muñoz.</p> </div>','Any 100- or 200-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1028,2022,1377,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-248','<div class="desc"> <p>This course will examine major global public health problems and the range of responses from international organizations, transnational networks, and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century, the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as: HIV/AIDS, malaria, unsafe food and water, tobacco use, and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health, including morbidity; mortality; demography; epidemiology; and the political, social, and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political, economic, social, and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health, and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1029,2022,1378,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-217','<div class="desc"> <p>National reform efforts (e.g. Nation at Risk, No Child Left Behind, Race to the Top) have permeated the educational establishment for decades, yet the achievement gap between rich and poor and white and non-white students has shown no appreciable progress. This course will analyze current and past policies in education intended to improve the educational experience of all students and address this achievement gap. Students will receive an understanding of policy formation, the effect of applied research relative to educational policy, and then select a reform policy (e.g. value-added teacher pay, class size, charter schools, etc.) to further investigate as a project field assignment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1030,2022,1379,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-310','<div class="desc"> <p>Examining death in the imaginative and meditative culture of the 14th and early 15th centuries, this seminar will introduce advanced students to a wide range of Middle English literature. No prior knowledge of Middle English or medieval literature required. We will contextualize our work by looking at religious, philosophical, and medical texts about death, yet our focus will be on scenes of death, burial, mourning, and memorial in literary texts by Chaucer, the Pearl Poet, Julian of Norwich, and others. Asking how we can construe the ethical and political imagination of the medieval English literary world, we will also consider larger issues related to the literary awareness of death: the representability of death; the political and generic function of consolation, tragedy, and elegy; death''s relations to the sacred and the sovereign; the economics of death in the age of the plague; war and martyrdom; mourning and rebellion; dreams and the afterlife; gender, living, death, and anchoritism.</p> <p><strong>Major Requirement Met</strong>: Group I</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1031,2022,1380,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-365','<div class="desc"> <p>Topics may vary semester to semester.</p> <p><strong>The Refugee</strong></p> <p>This seminar will explore how refugees have portrayed themselves and have been portrayed in literature, memoir, testimony, film, and art. Our goal will be to appraise whether and how aesthetic attempts to capture the condition of refugees respond to and at times revise political discourses about those in exile. Among others, we will engage with the work of Hannah Arendt, Primo Levi, Giorgio Agamben, Edward Said, Gloria Anzaldua, W.G. Sebald, Mahmoud Darwish, Caryl Phillips, Ghassan Kanafani, and Viet Nguyen.</p> <p>Major Requirement Met: Group III/ IV</p> <p><strong>The Global Novel</strong></p> <p>This course will focus on literature and theory produced in the aftermath of the British Empire. By 1914 the British Empire had colonized almost 25% of the world, bringing diverse cultural traditions under the encyclopedic gaze of Western modernity. If part of the aim of the colonial apparatus was to collect knowledge of the world in ways that bodies, cultures, and landscapes could be understood and ordered by the West, contemporary societies are now negotiating their own means of self-representation in the often-violent space of postcolonial rupture. Throughout the term, we will work with texts and visual images produced out of, and in response to, the history of the colonial encounter. Drawing on a broad range of literary, filmic, and theoretical materials we will develop strategies for understanding the production and consumption of postcolonial representation, in both local and global contexts. As consumers of these cultural products within the space of the Western academy, we will be attentive to the function of the stereotype as we consider representations of gender and sexuality, violence and terrorism, class structures, and migration.</p> <p>Major Requirement Met: Group III.</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1032,2022,1381,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-380','<div class="desc"> <p>Our primary focus will be on fiction. Students will be required to respond thoughtfully and critically to assigned readings and to one another''s work. We will attend to general issues of craft, as well as to broader questions about the writing of fiction. Open only to juniors and seniors. May be repeated for credit.</p> </div>','ENGL 280 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1033,2022,1382,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-209','<div class="desc"> <p>This course traces the United States'' rise to global superpower over the first half of the 20th century; its engagement with, and interventions in, a decolonizing Cold War world; and, finally, its transition to its contemporary role as part of an increasingly multilateral and internationalist world order. Our investigation of U.S. engagement with the wider world rests on the understanding that as America''s influence on the world grew, so did the world''s influence on America. Lectures and readings will cover America''s political and military dealings with other powers - that is, U.S. diplomatic history as traditionally understood - but will also address Americans'' cultural, social, economic, and intellectual interactions with foreign peoples, both at home and abroad. Specific topics include: U.S. overseas imperialism, the U.S. role in both World Wars and the Cold War, the heightened significance of Asia and the Pacific World after 1940, internationalism and the creation of the United Nations, the emergence of the Third World and Washington''s ambivalent relationship to global decolonization, Americans'' involvement in the global revolutions of the 1960''s, the economic upheavals of the 1970''s, the end of the Cold War, and the politics of a post-Cold War and post-9/11 world.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1034,2022,1383,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/japn-japanese-studies/400/japn-460','<div class="desc"> <p>This advanced level course will develop the student''s skill in reading Japanese through the practice of translation. The class will read a number of excerpts from authentic texts of different genres and discuss the issues that are critical for accurate comprehension of the source text, by applying theories of general linguistics, socio-linguistics, and translation; then they try translating the Japanese texts into readable English. Through the process of identifying, articulating, and solving challenges to Japanese-English translations, the students will further improve not only their language skills but cultural literacy as well.</p> </div>','JAPN 302 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1035,2022,1384,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-304','<div class="desc"> <p>Introduction of principles of human physiology with special emphasis on a systems approach. Presentation of an integrative approach to basic physiology of major organs and organ systems, covering aspects of cell function, including membrane transport, excitability, metabolism, and functions of organs from the nervous muscular, respiratory, cardiovascular, gastrointestinal, renal, endocrine, and reproductive systems. Includes one three-hour laboratory per week.</p> </div>','KINE 301 or BIO 115 ','KINE 304L ',NULL);
INSERT INTO course_descriptions VALUES(1036,2022,1385,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/300/kine-304l','<div class="desc"> <p>Three hour per week laboratory for Human Physiology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1037,2022,1386,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1038,2022,1387,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ling-linguistics/300/ling-397','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1039,2022,1388,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-340','<div class="desc"> <p>This course will focus on theoretical qualitative and quantitative analyses of ordinary differential equations, from a modern perspective, using analytical, graphical, and numerical points of view. Topics can include: first-order linear and nonlinear differential equations, first order linear systems, second-order linear differential equations, autonomous differential equations and their bifurcations boundary value, problems solutions using infinite series, Laplace transforms, and various numerical approximation techniques.</p> </div>','MATH 212 and MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1040,2020,1389,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/200/musc-240','<div class="desc"> Production skills are at the heart of every recording since the onset of music technology. Since then, we cannot speak of something that is "the music itself" and another thing that is its production: "music" is embedded in its production, regardless of style or genre. Professional musicians are increasingly expected to have an understanding of audio engineering and to navigate digital audio workstations in order to record and produce polished tracks for themselves and others. In this course, students will learn to understand and manage complex sound systems, including recording studios and live sound reinforcement, microphone and recording techniques, acoustics and signal flow/processing, mixing and mastering, and digital audio workstations platforms such as Digital Performer, Pro Tools, and Logic. Through the hands-on production and analysis of state-of-the-art digital audio samples, student will gain skills to successfully navigate the private recording studios, large sound stages and control room environments in which the soundtracks for film, television, radio, and digital media are produced. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1041,2022,1390,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-258','<div class="desc"> <p>This course introduces students to the art of film scoring and provides an in-depth exploration of the field. We will discuss functions of film music and analyze preexisting scores that demonstrate varying dramatic situations, while also investigating the aesthetic relationship between film and music. Students will be required to write music for preexisting scenes throughout the course, as well as score student short films (senior comps) from Media Production majors. </p> </div>','Music 148 or permission of instructor (basic experience using Logic, Ableton Live, or other Digital Audio Workstation) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1042,2022,1391,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-282','<div class="desc"> <p class="sc-BodyText">North Indian (Hindustani) Classical Music is one of the most complete systems of musical expression found in the world today. Hindustani music is a vibrant contemporary art form that draws from an ancient historical tradition and rigorous theoretical structure to create performances that combine spontaneous creativity with virtuosic musicianship. In this course students will explore the musical and cultural aspects of this system through historical analysis and hands-on practice. Beginning with those elements of structure that Hindustani music shares with Western music (including the major scale) students will integrate theory practice and musicianship as part of a comprehensive introduction to North Indian music. The ability to read Western staff notation is highly recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1043,2017,1392,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MUSC-Music/MUSA-Music-Applied-Study/100/MUSA-101','<div class="desc"> <p>Fundamentals of singing: voice production diction repertoire musicianship. <em>Recommended as preparation for private lessons. Fee: $195.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1044,2022,1393,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-249','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique and awareness of and proficiency in Afro-Cuban style. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1045,2022,1394,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-250','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique and awareness of and proficiency in Afro-Cuban style. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1046,2022,1423,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/100/pols-140','<div class="desc"> <p>Law shapes the day to day experiences and functioning of individuals, communities, and institutions in multiple ways. This introductory course examines the diverse connections and relationships of law and society. The course will draw on theoretical and empirical perspectives from a diverse range of disciplines (such as legal studies, sociology, anthropology, and political science) to explore law and law’s role within the United States and internationally. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1047,2022,1424,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States and to assess how these communities seek political empowerment as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life such as the economy the state and the cultural system on the one hand and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States.; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications based on race class gender national origin and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1048,2020,1425,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/psyc-psychology/specialized-and-integrative-themes/psyc-375','<div class="desc"> <p>This seminar explores the social politics of race through the lens of color-conscious and color-blind ideologies. Topics focus on the construction of race; racial identity development and socialization for differently positioned group members; psychological impact of race and racial identification for academic achievement esteem and health; contemporary research on colorblind and color conscious ideologies and primes; and social policy. Interdisciplinary readings include Psychological theory and research (Steele''s Whistling Vivaldi Sue''s Microaggressions Contemporary journal articles) Critical Theory ( Delgado and Stefanic''s Critical Race Theory) and Sociology (Bonilla-Silva''s Racism without Racists). Heavily discussion-based.</p> </div>','Any American Studies course at the 200 or 300 level OR any of the following: PSYC 110, PSYC 323, or PSYC 333 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1049,2022,1426,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-380','<div class="desc"> <p>This course examines disaster as a social phenomenon and broader trends in managing calculating and responding to a variety of threats and catastrophes. We will focus on the history of disaster response and policy in the U.S. theories of reflexive modernity risk and trauma and cultural responses to calamity in California and in the U.S.more broadly. Case studies include Hurricane Katrina the BP Deepwater Horizon oil spill Fukushima and outbreaks of whooping cough and Ebola.</p> </div>','SOC 101, SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1050,2022,1427,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-343','<div class="desc"> <p>Language use symbolically represents fundamental dimensions of human behavior and social interaction. For instance, what can you immediately infer about a Spanish speaker who uses the word “zumo” to describe the orange beverage commonly drunk at breakfast? Most likely, they are from Spain, otherwise they might describe this beverage as "jugo."</p> <p>This course introduces the basic concepts of sociolinguistics, using Spanish as our tool of exploration and description. Sociolinguistics focuses on the symbolic value of language as an expression of group identity based on region, gender, ethnicity, socioeconomic class, age, or other ways of defining group affiliation. In this course, we describe key notions of sociolinguistics such as the speech community, the sociolinguistic variable, and field methods. The core goal of the course is to identify phonological and morphosyntactic variation throughout Spain, Latin America, and the US, and identify what this variation tells us about language change and development as well as about the social characteristics and identities of the speakers themselves. The course also surveys other related topics such as language contact, bilingualism, Spanish as a heritage language, language attitudes and language identity in the U.S. and elsewhere, language and law, language and age, and language and gender. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1051,2022,1428,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-398','<div class="desc"> <p>The goal of the Community Translation Internship is to provide students with an experiential understanding of the practice of translation. The Community Translation Internship allows students to learn through direct experience the different steps in the translation process as well as examine the challenges that bilingual professionals face in their efforts to reach out to underserved populations such as the Spanish-speaking communities. All students enrolled in the Community Translation Internship work with a community-based organization for an average of eight hours a week.</p> </div>','SPAN 340 or above and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1052,2020,1429,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-248','<div class="desc"> <p>The course will examine major global public health problems and the range of responses from international organizations transnational networks and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as HIV/AIDS malaria unsafe food and water tobacco use and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health including morbidity mortality demography epidemiology and the political social and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political economic social and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1053,2022,1430,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1054,2022,1431,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/100/wrd-135','<div class="desc"> <p>The Occidental Weekly practicum is for those who want to become section editors at the Occidental Weekly or simply want a further understanding of how daily journalism works. We will learn about ethics, management, editing and planning functions; we will not specifically study writing. Class assignments include three sets of story pitches and two news memos. The goal is for you to be ready to walk into a newsroom with an understanding of the language, disciplines, and best standards and practices. We will have occasional guest speakers on nuts-and-bolts topics, such as the use of language and the difference between news presentation in digital and in print. This is a graded course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1055,2022,1432,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-287','<div class="desc"> <p>The 21st century has seen an abrupt escalation of government, corporate, and nonprofit institutions'' use of technology-sharpened rhetorical tools to disseminate information and, increasingly, disinformation to individuals and the public. Journalism, one of democracy''s most important forces for distinguishing truth from propaganda, has simultaneously been decimated by technological and economic change. This course offers an insider''s perspective on the theory and practice of rhetorical persuasion. This course will examine the forces that shape public opinion about recent history''s most significant issues, including climate disruption, education, immigration, and war. With a focus on opinion journalism, this course examines historical and current practices globally in examples such as Nazi and Stalinist propaganda in WWII, to international discourse on Vietnam, Iraq, and Afghanistan. Students will learn to write and critique editorials, op-eds, blog posts, and strategic communications'' plans driven by social media messaging, while scrutinizing the shared interests and deep tensions between journalism and public relations, publicity and marketing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1056,2022,1433,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-215','<div class="desc"> <p>This course examines the history of sexuality in America from the early colonial era to the present. Along with theoretical readings, the course will consider primary and secondary sources addressing issues including: reproductive politics, socio-sexual control of Native populations, the rise of urban erotic subcultures, the sexual politics of slavery, American sexology, sex work, gender in private and public spheres, sex panics, feminism and gay liberation, and intersectional erotic cultural production.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1057,2020,1434,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/300/amst-346','<div class="desc"> <p>This course thinks through current debates over the relationship between literary aesthetics and harmony in American democracy. Do aesthetics foster a more harmonious or disharmonious national culture? Do aesthetics create more peaceful cities and craft a common culture? Should its subject matter be legal resolutions to conflict and representations of peaceful communities? Or, is disharmony ever important to progress? How does literature represent protests for social change that are often only possible outside the law, like the many freedmen and freedwomen escaping slavery and demanding the destruction of that system? How does this alter our understandings of what it means to be a fugitive? How can the fugitive fighting for freedom be distinguished from the unprincipled outlaw? From another perspective, we will consider how the complications of American society have altered certain traditional literary forms. While recent scholarship has addressed these questions in regards to early to mid 20th century literature, this course will look back further, starting from the early 19th century to the very beginning of the 20th. Will complement the literature by reading relevant historical materials from the abolitionist movement, labor movements, government debates over Emancipation and Reconstruction, etc. The course will include literature from Frederick Douglass, Sojourner Truth, Walt Whitman, Ida B. Wells, and Charles Chesnutt, amongst others, and will cover several genres, including: oratory, autobiography, political pamphlets, and short fiction. Open to juniors and seniors.</p> </div>','Any 100 or 200-level American Studies or English course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1058,2017,1435,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ARTH-Art-History-Visual-Art-Art-History/300/ARTH-340','<div class="desc"> <p>Two of the most explosively important geo-political events of modernity were World War I and the Russian Revolution(s) of 1917. This course investigates the theories and practice of the Russian Avant-Garde in the visual arts literature industrial design and architecture in relation to parallel international developments during the Revolutionary period through the rise of Stalin in the early 1930s. Topics include: fragmentation and shifts in artistic perception of time space and reality; responses to advances in science technology and industry; constructivist design architecture and theater; montage and cinema; consumerism and materiality; artist collectives manifesti and the relationship of theory and ideology; cultural imports from Europe and America. Same as RUSN 340.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1059,2022,1436,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-392','<div class="desc"> <p>The history, purpose, and varied practices of museums are examined cross-culturally in this introductory course designed as a community-based practicum. Core concepts of museology, such as: collections management, educational outreach and programming, standards and ethics, curation, exhibition strategies, and disciplinary standards are examined in case study scenarios supported by academic readings and collections-based inquiry. Students will work collaboratively with others in team-based learning and problem solving, while demonstrating critical thinking in written essays and oral debates. The class will make use of the resources of the Autry National Center of the American West.</p> </div>','One 200-level Art History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1060,2020,1437,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/bio-biology/200/bio-238','<div class="desc"> <p>This course is designed to introduce the basic concepts, principles, and methods of epidemiologic research. In our pursuit to understand the interplay of risk factors and patterns of human disease and health, we will cover the history of epidemiology, the principles of epidemiologic thinking and of causal inference, the basic measures of disease frequency and of association, and how to compute them. We will also learn about the major types of epidemiologic study designs and explore the major fields of epidemiologic investigation (such as global health, infectious diseases outbreaks, occupational and environmental epidemiology). To better understand the practical application of study methods used in epidemiology, the class has a laboratory component (BIO 238L). The laboratory component will provide students exposure to public health related organizations here in Los Angeles County, as well as current local public health issues.</p> </div>','Introductory Biology ( BIO 105 , BIO 106 , BIO 110 , BIO 115 , or BIO 130 ) and Statistics ( BIO 268 , COMP 146 , MATH 146, or MATH 150 ) ','BIO 238L ',NULL);
INSERT INTO course_descriptions VALUES(1061,2022,1438,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/300/chem-315','<div class="desc"> <p>An introduction to the study of kinetic molecular theory and chemical kinetics.</p> </div>','MATH 120 and PHYS 120; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1062,2017,1439,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CLAS-Classical-Studies/200/CLAS-202','<div class="desc"> <p>The object of this course (as the three- or four-fold pun of its title implies) is not only to celebrate Ancient Literature on the occasion of its supposed passing but also to highlight the ways in which Ancient Literature has informed the creation of-- and might yet continue to re- inform our understanding of--many subsequent forms of literary expression. The course will begin therefore with the close textual analysisof one or more ancient literary works and proceed with a comparative study of a text (or texts) drawn from later literary traditions most particularly modern and contemporary treatments (the manifold ways for instance that Joyce draws upon Homer Derrida upon Plato).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1063,2017,1440,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CLAS-Classical-Studies/300/CLAS-303','<div class="desc"> <p>This course examines the meanings effects social contexts and historic development of one of the major Classical genres: epic lyric tragedy comedy (to name but a few). In 2014-2015 the course will focus on the explosion of new literary genres (romantic comedy in particular but also biography the anecdote and philosophic dialogue) that followed in the wake of Alexander the Great''s conquest of Greece and the subsequent demise of the autonomous Greek city state. Attention will also be given to the long term effects of these new "Hellenistic" genres on subsequent European literary and cultural history as it was primarily the Hellenistic sensibility (not the Archaic or Classical) that for the next 2000 years that was understood to be representative of the "Ancient Greek" perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1064,2022,1441,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-292','<div class="desc"> <p>Mechanisms of brain development, growth, neurogenesis, maturation, and changes that occur during life. Emphasis will be placed on current literature and studies done in non-human animals and humans. We will also talk about what it takes to maintain a healthy brain.</p> </div>','COGS 101, COGS 104, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1065,2022,1442,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-312','<div class="desc"> <p>This course combines theory and practice in the study of language and literacy across cultures and institutions. It will introduce students to competing theories of language and literacy development and the politics that undergird those theories. The course will also explore topics such as: gender, race, culture, and ethnicity as they intersect and shape language learning. Students will learn about language acquisition, heritage languages, language variation, dialects, and bilingualism. The course will also explore controversies surrounding multimodal literacies involving speech, writing, drawing, pictures, video, and music. Junior standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1066,2022,1443,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-390','<div class="desc"> <p>The CTSJ Junior Seminar is designed to develop students'' methodological sophistication and theoretical skills in anticipation of the Senior Comprehensive Project. Students will be required to acquire an applicable understanding of the range of archives and the complex interdisciplinary methodological strategies used in Critical Theory and Social Justice. They are also required to develop an understanding of the meaning of the CTSJ Senior Comprehensive Project as an "intervention." Open only to juniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1067,2022,1444,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-152','<div class="desc"> <p>This course will introduce social enterprise practices and theory while allowing students to work directly on a social enterprise project with global impact. This course will build on the 25-year foundation of collective knowledge in the field of Social Entrepreneurship through case studies and life challenges that continue to face the international community. We will look at how value creation and sustainability are key elements in the development of successful social enterprises, with emphasis on water, food, and housing/urban design. Our focus will be on how, through innovation and entrepreneurial approaches, we can access sustainable solutions to the world''s most pressing problems.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1068,2022,1445,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-253','<div class="desc"> <p>China''s return (as opposed to rise) to its proportional place in the global economy has arguably caused a pivot towards Asia by the United States. While America''s hegemonic status in terms of hard (military) power remains undisputed, China''s gross domestic product may surpass that of the United States as soon as 2017. This course is a seminar on Asian security, covering military security, non-traditional security, and economic and political security, among other dimensions. The course surveys the Asian region, with particular emphasis on Southeast Asia (the ASEAN countries, particularly Cambodia Burma/Myanmar, Thailand, and Singapore) and Northeast Asia (China, Japan, South Korea, and Taiwan). The material is divided into three parts. The first provides an overall introduction and overview of Asian security and focuses on the foundations of what was thought to be the Asian Miracle (created in part from a U.S. security umbrella), just as the Washington Consensus rose to prominence. It takes students through the Asian Financial Crisis and its aftermath. Part two of the class focuses on Japan, South Korea, China, and Taiwan. It describes their development trajectories and security arrangements. Part three uses China as a platform to examine other parts of Asia not already covered, such as: China''s relationship with Southeast Asia, and the political economy of non-traditional security, in particular the region''s experience with Highly Pathogenic Avian Influenza.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1069,2022,1446,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-335','<div class="desc"> <p>African theorists have historically integrated theoretical critiques with revolutionary practices. This class will focus on theories pertaining to opposition to colonialism in Africa, as well as in the Caribbean and the United States. Theorists such as Franz Fanon, Steve Biko, Kwame Nkrumah, Eric Williams, and Marcus Garvey will be studied. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1070,2022,1447,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-302','<div class="desc"> <p>A study of firms and industries in the United States economy. Topics include: the acquisition and use of market power by firms, strategic behavior of firms in oligopoly markets, and antitrust policy. The course will approach topics from both theoretical and applied perspectives.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1071,2022,1448,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-331','<div class="desc"> <p>An introduction to the history of radical philosophical alternatives to neoclassical and Keynesian Economics. A critique of these mainstream schools is followed by the development of competing radical alternatives with the analytical focus on concepts of economic surplus and social class, exploitation, alienation, and theories of capitalist development crisis and transformation. Ethnographic case studies provide examples of archaic and contemporary alternative economic practices. Special attention is paid to philosophies of human nature, the labor process, problems of racism and sexism, imperialism, current U.S. economic problems, and socialist alternatives.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1072,2022,1449,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-281','<div class="desc"> <p>This class provides students with the ability to develop a conceptual and practical understanding of research and evaluation in Education and the Social Sciences. Course topics include: basic statistics, survey design, data analysis, article critique, and data interpretation. The course will allow students to demonstrate a proficient knowledge of basic statistics (ranging from basic descriptive statistics to inferential statistics), research design, and analysis. Students will advance from being consumers of knowledge to being critical when reading previous literature. Students will be introduced to the following concepts: descriptive statistics (including cross-tabulation); correlation, reliability, and validity; one and two sample statistical tests; ANOVAs; and simple and multiple regression.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1073,2022,1451,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-332','<div class="desc"> <p>The class will examine British literature from the novels of Richardson, Fielding, and Sterne to the poetry of Blake, Wordsworth, and Coleridge.</p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>','One 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1074,2022,1452,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-346','<div class="desc"> <p>This course explores literary representations of slavery, civil war, social reconstruction, and political backlash in 19<sup>th</sup> century America. Along the way, students will address several questions: How does literature represent demands for social change that transgress the law, like the freed persons escaping slavery? How to distinguish fugitives fighting for freedom from unprincipled outlaws? Is emancipation a single act, legal declaration or a more complicated process? And for whom? Finally, how do we grapple with the backlash to political change? By focusing on the 19th century, we can rethink how African Americans found political agency generations before the most familiar events from the Civil Rights era. Most of all, this course allows students to read literature alongside historical documents, so they can see firsthand how debates over freedom evolved in the 19<sup>th</sup> century. </p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1075,2022,1453,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-351','<div class="desc"> <p>In this class we will examine fiction by British modernist writers such as Joseph Conrad, James Joyce, Virginia Woolf, Katherine Mansfield, D. H. Lawrence, and E. M. Forster. We will read their work critically, with attention to the ways in which it approached and reflected (or obscured) its historical context: changing gender roles, a fragile and distended empire, global reassessments of power, class, and race. We will also explore some representative later responses in British fiction to these central concerns of modernism.</p> <p><strong>Major Requirement Met</strong>: Group III</p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1076,2022,1455,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. Major requirement met: Group III or Group IV. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1077,2022,1456,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-372','<div class="desc"> <p>Beginning with a history of French cinema and an introduction to film criticism, this course examines narrative techniques in film and fiction, with an emphasis on post-1968 film production in France, and on fiction that explores, among other themes, gender and desire. Films and novels to include: <em>Madame Bovary</em> (Flaubert), <em>L''Amant </em>(Duras), <em>Les Misérables</em> (Hugo), <em>Un Amour de Swann</em> (Proust), and <em>L’Armée du Salut</em> (Taïa).</p> </div>','FREN 202; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1078,2022,1457,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/100/geo-106','<div class="desc"> <p>Nature and humanity interact with and impact one another in complex and significant ways. Human health, safety, and economic well-being are significantly impacted by natural processes, providing both opportunities and constraints on sustainability. This course focuses on these interactions as studied by earth scientists. Topics include: Earth surface properties and processes, air quality, mineral and energy resources/reserves for industrialized society, water resources, hazardous earth processes, and development and degradation of soils and climate. Labs will include using problem-solving skills and case studies. <em>Includes one two-hour laboratory per week and a one-day field trip.</em></p> </div>',NULL,'GEO 106L ',NULL);
INSERT INTO course_descriptions VALUES(1079,2017,1458,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/GEO-Geology/100/GEO-106L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1080,2022,1459,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-252','<div class="desc"> <p>This course offers a broad survey of Mexican religion from pre-Columbian times to the present. The course begins with the study of Nahua ("Aztec") spirituality and ritual and continues with an examination of major developments of the colonial period as indigenous European and African peoples came together with their many different beliefs and practices. We will study indigenous strategies of both resistance and accommodation to the imposition of Catholicism, the origins of the devotion to the Virgin of Guadalupe, the Mexican Inquisition, millenarian movements, missions, and women in the church in the colonial period. Our study concludes with the anti-clerical reforms of the late nineteenth- and early twentieth-centuries, the Cristero Rebellion, increasing influence of Protestantism, and the persistence of local religions in modern Mexico. Students will analyze historical documents, religious dramas, confessional manuals, Inquisition records, paintings, sculptures, and films in their examination of the history of religion and spirituality in Mexico.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1081,2017,1460,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/HIST-History/Comparative-Transnational/300/HIST-353','<div class="desc"> <p>This seminar explores the cultural and social history of progressive Catholic activism throughout the Americas in the twentieth century in order to understand Catholicism''s contributions to the development of a robust public sphere and faith based counterculture. Through transnational and interdisciplinary approaches we will examine the role that lay Catholics and rebel priests and nuns have played in the struggle for economic justice human rights and world peace. Topics will include the Catholic Worker Movement; liberation theology; the Marycrest and Solentiname experiments; Base Ecclesial Communities; death penalty abolition; peace networks; Catholics for Choice; New Ways Ministry; and the Sanctuary Movement. Los Angeles as a field of study will occupy a significant place in our exploration with site visits to the El Salvador Community Corridor Catholic Worker communities and Homeboy Industries.</p> </div>','HIST 102 or HIST 151 or LLAS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1082,2022,1461,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/300/math-396','<div class="desc"> <p>This is a 2-unit seminar course which will cover various topics in applied mathematics. This course may be repeated once for credit.</p> <p><strong>Industrial Mathematics</strong><br/> This course is a project-oriented introduction to industrial mathematics. Students will be grouped into teams and tasked with creating solutions to actual real-world problems provided by external partners from business, industry and government. Familiarity with a programming language is highly desirable but not required. The goal of this course is to provide students with an experience of what it is like to work as a mathematician in a professional setting.</p> <p><strong>Mathematical Modeling</strong><br/> This course is a project-oriented seminar in mathematical modeling. Concepts from calculus, linear algebra, differential equations and other areas of mathematics will be used to derive, describe and solve mathematical models from the life, physical, and social sciences. Familiarity with a programming language is desirable but not required. The goal of this course is to provide students with multiple examples of how mathematics can be used to explain various phenomena, to describe real-world situations and to make (more quantitatively) informed decisions.</p> <p><strong>Applied Mathematics</strong><br/> This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1083,2022,1462,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-284','<div class="desc"> <p class="sc-BodyText">Although they have often been marginalized within official histories of North American music-making Latino/a musicians have contributed to the production and development of every major genre of music in the United States. In this course we will review the history of Latino/a music in the United States focusing on regional musical movements in Texas California New York and Florida. In addition to exploring Spanish-language genres including cumbia salsa merengue conjunto banda and reggaeton which have been shaped by musical innovators in the United States we will trace the influence of Latino/a musicians on rock n’ roll punk jazz hip hop and country. In particular we will be interested in exploring how music has helped to shape emerging patterns of racial ethnic class and gender identification while fanning the flames of social protest movements from the Chicano Movement of the 60s and 70s to the pro-immigrant rights movement of the past two decades. Finally we will consider the emerging soundscape of U.S.-based protests on behalf of the 43 students massacred in Iguala Mexico. In addition to written assignments students will also collaboratively develop a digital project incorporating maps storytelling and data visualizations. <em>No prior study of music or digital humanities is required.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1084,2022,1484,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/400/phys-491','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1085,2022,1485,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-221','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century with a focus on contemporary democratic politics. The course will discuss the historical institutional and social forces that have both accelerated and opposed democratization and will cover topics of current concern to the region including economic development security and the rule of law the design of political institutions human rights and social movements.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1086,2022,1486,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-260','<div class="desc"> <p>The goal of the Community Law Internship is to provide students with an experiential understanding of the practice of public interest law and community lawyering. The Community Law Internship must be taken simultaneously with POLS 340 which establishes the theoretical foundation for the co-requisite courses through the exploration of scholarship in the areas of: progressive legal practice community collaboration critical reflection social justice activism and community organizing. The Community Law Internship allows students to learn through direct experience about the practice of public interest law in Los Angeles as well as examine how social structures and related identity categories such as gender, race, ability, sexual orientation, and class interact on multiple levels to create social inequality. All students enrolled in the Community Law Internship work with a community-based legal organization engaged in public interest law practice a minimum of 15 hours each week. The unique approach of integrating POLS 340 and POLS 260 takes advantage of Occidental faculty expertise and the wide-range of community-based educational opportunities available in Los Angeles. Permission of instructor required.</p> </div>',NULL,'POLS 340',NULL);
INSERT INTO course_descriptions VALUES(1087,2022,1487,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-340','<div class="desc"> <p>Pursuing effective change particularly in today''s complex world requires creative collaborative efforts to identify and implement solutions to achieve a more radically participatory democracy. Rebellious Lawyering considers the related theories of legal scholars who have reconceptualized legal practice to transform systems through both legal and community knowledge. This scholarship has been defined as rebellious lawyering third-dimensional lawyering collaborative lawyering democratic lawyering and community lawyering. All of these theories impart a common vision of lawyering for social change in stark contrast to the traditional or regnant model. The praxis of Rebellious Lawyering (POLS 340) and Community Law Internship (POLS 260) creates a balanced context from which students develop critical consciousness question assumptions of power privilege and identity learn to respect community decision-making capacities expand their understanding of the importance of relationships in the pursuit of social change and remain open to learning from the lived-experiences" of the community. The unique co-requisite course design allows students to engage in a weekly seminar (POLS 340) work as law clerks in community-based public interest legal service organizations (POLS 260) and interact with Los Angeles activists and lawyers as part of a speaker series. Instructor permission required. Can be repeated once for credit.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,'POLS 260 ',NULL);
INSERT INTO course_descriptions VALUES(1088,2020,1488,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/political-theory/pols-354','<div class="desc"> <p>This course will look at theories of tyranny offered by Plato Aristotle Tacitus Machiavelli Tocqueville Marx Weber Freud Arendt and Marcuse. The course requires a major research paper in which the student will use one or more of these theories to analyze a modern tyranny of his or her choice. <em>Not open to frosh.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1089,2022,1489,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-400','<div class="desc"> <p>This capstonecourse will help senior psychology majors to integrate across subdisciplines in psychology consolidate their experiences in the psychology major through review and discussion of primary coursework in psychology and connect their studies in psychology to the roles that psychology plays in society and the professional world. <em>Open only to students with senior standing in psychology (i.e. intended for graduating seniors).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1090,2017,1490,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/RUSN-Russian/300/RUSN-340','<div class="desc"> <p>Two of the most explosively important geo-political events of modernity were World War I and the Russian Revolution(s) of 1917. This course investigates the theories and practice of the Russian Avant-Garde in the visual arts literature industrial design and architecture in relation to parallel international developments during the Revolutionary period through the rise of Stalin in the early 1930s. Topics include: fragmentation and shifts in artistic perception of time space and reality; responses to advances in science technology and industry; constructivist design architecture and theater; montage and cinema; consumerism and materiality; artist collectives manifesti and the relationship of theory and ideology; cultural imports from Europe and America. Same as ARTH 340</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1091,2022,1491,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-200','<div class="desc"> <p>This course introduces the discipline''s formative schools of thought. The course is structured according to sociology''s classic paradigms. Marxist Weberian and Durkheimian theories are the classical models. They founded the field of Sociology and continue to influence contemporary thought about social relations. In the course we first examine the fundamental presuppositions of their grand theories. Then we critically evaluate the particularities of their more concrete propositions about capitalist development or modernization the state and social change. A special emphasis of the course is on critical analysis.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1092,2022,1492,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) Presidents either failed to act in accordance with the transitional justice movements sweeping Latin America or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently as compared to South American countries human rights violations in Mexico have increased rather than decreased since its transition to democracy. This class will document why this is the case as well as look into the various movements thathave mobilized since the 1970s to the present to demand human rights in Mexico.</p> </div>','SOC 101, POLS 101, or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1093,2022,1493,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-310','<div class="desc"> <p>This course introduces the theory and methods of sociological and urban field research. We consider positivist interpretive and critical paradigms. We compare the traditions of anthropological as well as sociological ethnography. We explore the ethics of participant observation with respect to issues such as role authority and power. We learn interview protocols how to write field notes how to analyze data and techniques of storytelling in ethnographic writing. We explore principles of participatory action research and oral history. We will also learn quantitative methods through the analysis of local statistical data from the U.S. Census of Population and Housing. Students will conduct their own ethnographic or field-based study.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1094,2022,1494,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-309','<div class="desc"> <p>Many Latin American writers have chosen to live in Spain during the twentieth century. This course introduces students to the Latin American tradition of the writer acting as public intellectual or diplomat as well as to instances of the Latin American writer in political exile. Poets Pablo Neruda and CÃ©sar Vallejo chose to live in or near Madrid during the period of the Spanish Civil War whereas a later generation of fiction writers (Gabriel Garcia Marquez Cristina Peri Rossi and Roberto BolaÃ±o) lived in Barcelona after the 1970''s. The fiction writers include their own vision of Catalan nationalism and Catalan national identity in various short stories. The course concludes with a three-week stay in Spain that will provide a deeper understanding of the Latin American writers'' representation of the coutry. On-site lectures by historians and art-historians will enhance the student''s understanding of GarcÃ­a MÃ¡rquez''s Peri Rossi''s and BolaÃ±o''s incorporation of Catalan politics landscapes and cityscapes in their fiction.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1095,2022,1495,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-141','<div class="desc"> <p>We study and practice some of the most popular dance forms of the twentieth century. Through theater film and television many of these dances have expressed the spirit and the style and particularly the romantic temper of their times: from the quick steps of the Fred Astaire films to the swing dancing in <em>Malcolm X</em> and <em>A League of Their Own</em> and the tango of <em>The Scent of a Woman</em>. The dances taught include fox trot waltz swing and tango. We strongly recommend this class for our student actors. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1096,2022,1496,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/thea-303','<div class="desc"> <p>The focus of this course is on the history literature and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works while play attendance will keep our focus on these plays as performance. <em>There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1097,2020,1497,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-249','<div class="desc"> <p>This course explores core concepts in global public health the development of human rights instruments and mechanisms and the intersecting of these fields in global public health and human rights advocacy. Specifically we will review public health analysis to human rights problems and vice versa examining how a rights-based approach to health can inform more critical and more productive approaches to issues such as gender-based violence HIV/AIDS and other sexual and reproductive health concerns. Finally this course examines how global public health issues have generated dramatically different responses across and within regions countries and communities and launched myriad human rights movements at the international and local levels.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1098,2022,1498,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/100/amst-101','<div class="desc"> <p>This course introduces the major topics and perspectives of the interdisciplinary field of American Studies. Students will explore the diversity of United States culture, critically, in: its official and unofficial histories, its self-representations in the arts, its complicated intersections of ideals and realities. The class is required for American Studies majors and minors, and recommended for anyone wanting to better understand the relations between culture and identity in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1099,2020,1499,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/300/amst-310','<div class="desc"> <p>This interdisciplinary seminar examines representations of the American South in literature and film, as well as material and popular culture from Aunt Jemima collectibles, D.W. Griffith''s <em>Birth of a Nation</em>, to CNN''s 2005 coverage of Hurricane Katrina. We will also discuss the impact of Asian and Latino immigration on a region traditionally characterized as "black and white."</p> </div>','One American Studies or American History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1100,2022,1500,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/300/amst-320','<div class="desc"> This course will study the 20th century evolution of word-and-image texts from their origins in early superhero comics to their contemporary emergence as recognized literary works. The texts will be primarily from the United States, but some attention will be given to foreign works in translation. </div>','Any prior American Studies course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1101,2022,1501,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/100/arab-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1102,2022,1502,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-259','<div class="desc"> <p>A thematic course on the history, theory, and practice of Modern Architecture in Europe and the United States, from the 1780''s to the later 20th century. Themes we''ll explore include the following: architectural theory and design as social planning, competing notions of public and private space, modernist architectural theory and urban development, rural and urban ideologies in American architecture, the changing image of the architect in the 19th and 20th centuries, architecture and urbanism in Southern California. Coursework will include a required half-day field trip.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1103,2022,1503,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-250','<div class="desc"> <p></p> <p>African American, Latinx, Asian, Feminist, GLBT, and transnational artists catapulted by liberationist desires and responding to questions of social transformation are the focus of this hybrid art making, history, and theory class. The course will focus on Los Angeles-based 20th and 21st century artist led efforts that critically engage issues of race, gender, ethnicity, and class both historically and within the present. The course will begin with an investigation of questions related to historiography and memory as they relate to politically engaged art practices through critical texts, a site visit to the Southern California Library, an independent archive of local Los Angeles movement history in South Los Angeles, and a workshop that will share research methodologies employed by my own collaborative artistic project, the Pochx Research Society of Erased and Invisible Histories to contest dominant historical and artistic canons. Through a workshop format, local contemporary artists such as Dewey Tafoya, Shruti Purkayastha, will provide students with tools to develop projects that respond to dominant cultural narratives through graphic, performative, and interventionist strategies. Finally, students will learn how artists shake the foundations of various established institutional worlds and the definitions of art itself by moving away from these very institutions and spheres of practice and by creating their own structures for critical thought and praxis: building collectives, artist led spaces and in the case of School of Echoes, becoming community organizers.</p> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1104,2022,1504,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-201','<div class="desc"> <p>This course provides students with a foundation to think critically about research in Cognitive Science and lays the groundwork for the original research that will be done in the senior year. We will examine primary literature, carefully considering the processes involved in moving from a general idea to a specific research question. We will consider the strengths and weaknesses of a range of approaches to studying cognition, with a focus on experimental design. The course will culminate in an original research proposal.</p> <p><br/> </p> </div>','COGS 101 ','COGS 201L ',NULL);
INSERT INTO course_descriptions VALUES(1105,2017,1505,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/COGS-Cognitive-Science/200/COGS-201L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1106,2019,1506,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/COGS-Cognitive-Science/200/COGS-290','<div class="desc"> This course introduces students conducting directed research with a faculty member in the Cognitive Science Department to the practice of "open notebook science," intended to make the research process (hypothesis generation, data collection, dissemination) transparent and accessible to anyone, researchers and public alike. Students will use the Open Science Framework either to undertake new research or to replicate a recent experiment within the cognitive sciences using the Open Science Framework. Students are expected to commit to a minimum of eight hours of course-work each week including a 1.5 hour course meeting, assigned group work, readings, and independent research. May be repeated once for credit. </div>','COGS 101, COGS 201 (currently 310), and permission of instructor.',NULL,NULL);
INSERT INTO course_descriptions VALUES(1107,2022,1507,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-109','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables, and riddles, to anecdotes, jokes, short stories, and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include: Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin, and Twitter. All readings and discussion in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1108,2022,1508,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-132','<div class="desc"> <p>Many of Russia’s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements, while at the same time creating some of the most memorable texts of the 20th century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin. The course will introduce students to modern Russian literature, while, at the same time, will examine how Russian writers used science fiction in a completely different manner than Western writers. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1109,2022,1509,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-182','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell, and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1110,2022,1510,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-241','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. Students who have completed Latin 102 or the equivalent can take this language intensive version of CSLC 241/CLAS 241 where we will read selections from Seneca’s <em>Epistulae ad Lucilium,</em> as well as Horace’s <em>Satires</em>.</p> </div>','LATN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1111,2022,1511,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-131','<div class="desc"> <p>Computer Science is about the organization of information and the design of processes that use it. This course teaches students to think computationally - how to break down processes into components that can then be fully described - and to acquire other habits necessary for a computer scientist. Students should come out of the course able to write simple, but complete, programs of their choosing, and should also be able to diagnose problems in unfamiliar programs.</p> </div>',NULL,'COMP 131L ',NULL);
INSERT INTO course_descriptions VALUES(1112,2017,1512,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/COMP-Computer-Science/100/COMP-131L','<div class="desc"> <p>Laboratory for Fundamentals of Computer Science</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1113,2022,1513,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-394','<div class="desc"> <p><em>Critical Theory and Social Justice Journal of Undergraduate Research</em> (<em>CTSJ</em>) is the leading undergraduate publication in its field, nationally. A primary goal of this course is to develop student''s preparedness and capacity to critically evaluate submissions to the <em>CTSJ Journal</em>. To that end, there are two sets of readings. All students are required to read the primary text, J.M. Balkin''s <em>Cultural Software</em>. Other readings are assigned to reflect the themes and topics of the submissions under review. In addition, this course affords students the opportunity to work closely with<em> CTSJ''''</em>s Lead Faculty Editor to understand the mechanisms of working for and advancing a research publication in the Humanities field, and produce content that is consistent with the goals of <em>CTSJ</em>. May be repeated three times for credit.<em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1114,2022,1514,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-286','<div class="desc"> <p>This course will look at the use of public diplomacy in the United States since the end of the 19th century. The concentration will be on U.S. public diplomacy towards Latin America and the Caribbean, Latin America-China relations, and Latin America''s relations with the rest of the world.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1115,2022,1515,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-290','<div class="desc"> <p>This class looks at global issues - including energy development, climate change, satellite imaging, and forms of communication - that have technical aspects. We then take these topics and place them in the cultural, political, and economic international context: how are states, non-state actors, international organizations, and non-governmental organization handling these issues?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1116,2022,1516,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-351','<div class="desc"> <p>This junior seminar will focus on advanced scholarship on global sustainability/sustainable development. Since the Brundtland Commission''s Report in 1992, these issues have become central to world affairs and diplomacy, all the more so as the scientific and policy consensus around climate change has grown over the subsequent two decades. Most recently, in September 2015, 193-member states of the United Nations agreed to a set of bold Sustainable Development Goals. The course will provide students with knowledge about the genesis, characteristics, dynamics, and consequences in the area of global sustainability/sustainable development. It is also a course focused on research and writing in International Affairs, preparing students to write their Senior Comprehensives. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1117,2022,1517,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/100/engl-155','<div class="desc"> <p>The pandemic of 2020 has revealed the surprising number and diversity of fantasies, fears, and anxieties surrounding the notion of science. While some of these reactions are relatively new (particularly those grounded in historically specific conspiracy theories), most emerged over the course of several centuries. Literary works, particularly novels, often explore these fears and anxieties in far greater detail than may be found in the direct attacks on or defenses of science. Texts like Mary Shelley''s <em>Frankenstein</em> or Bram Stoker''s <em>Dracula</em> both draw on scientific theories and articulate fears of the possible consequences of these theories that still resonate with readers today. We will read literary texts to determine what exactly those who reject science fear, and what is at stake in their rejection of science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1118,2022,1518,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-281','<div class="desc"> <p>This course introduces students to the fundamentals of poetry writing. Students will learn how to craft and revise poems, and will workshop their poetry in class with their peers. Outside readings will also be required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1119,2022,1519,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-311','<div class="desc"> <p>Before the modern novel, we had romance: the literature of error and erring, stories of characters who set out on a quest and lose their way due to madness, obsession, lack of faith, or the difficulty of knowing the truth about themselves or their quests. Romance was one of the most important genres of imaginative literature in medieval and Renaissance Europe, and yet it was also the one that provoked the most profound moral and aesthetic concern. Hugely popular, romance was often condemned for its endless attention to pleasure, pain, error, and forgetting, for its perverse magical stories of exploration and complicity, for its unseemly analysis of chivalric duty and obsession--and even for its capacity to corrupt its readers beyond repair. (Famously, Don Quixote was driven mad by reading romances!) Whether viewed as a genre of utopian dreaming or of lurid and dangerous narrative failure, romance is a vexed concept. By examining pre-modern and modern genre theory, this class will explore the formation of the category of romance across medieval and Renaissance England (with some attention paid to France, Italy, and Spain), thus giving students an opportunity to consider how genre can enable and constrain understanding of particular works of literature. Texts may include Virgil''s <em>Aeneid</em>, Chrétien de Troyes Arthurian tales, Geoffrey Chaucer''s <em>Troilus and Crisyede</em>, the anonymous Pearl-Poet’s <em>Sir Gawain and the Green Knight</em>, Miguel de Cervantes''s <em>Don Quixote</em>, Philip Sidney’s <em>Arcadia</em>, Edmund Spenser''s <em>The Faerie Queene</em>, William Shakespeare’s <em>Cymbeline</em>, and Mary Wroth’s <em>Urania</em>. At the end of the semester, we may turn to more recent works (such as Samuel R. Delany''s speculative fictions or Caroline Bergvall''s poetics of error) to get a sense of how pre-modern romance remains an archive for some of the most exciting literary production today.</p> <p><strong>Major Requirement Met: </strong>Group I</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1120,2022,1520,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-345','<div class="desc"> <p>This course examines the increasing centrality of the theme of "tyranny" to American literature before 1900. Most people know the founders justified the American Revolution as a response to Britain''s tyranny during the colonial period. Fewer know that "tyranny" became a watchword for national debates over race, gender, and class conflicts. What happens to the idea of "tyranny" when it refers to threats within a nation rather than outside forces? What happens when the calls for revolution that founded the nation are asserted once again, to save the nation from its worst self? The political and ethical political implications of this 18th and 19th century conflict reverberate today. Only a multi-genre approach, incorporating a wide range of authors, could do justice to these questions. For these reasons, we will examine revolutionary pamphlets, speeches, essays, freed-persons narratives, and poetry from authors as diverse as Joseph Warren, Phillis Wheatley, Phillip Freneau, Harriet Jacobs, Ralph Waldo Emerson, Walt Whitman, and Emily Dickinson. Finally, this course listens to voices too often obscured by our focus on well-known characters in American history: the unofficial soldiers of the American Revolution, the freed-persons who emancipated themselves from slavery, the conflicted Civil War Veterans, and the working-class Americans trying to find their place in Reconstruction-era America. <br/> <br/> <strong>Major Requirement Met</strong>: Group II</p> </div>','One 100-level or 200-level English course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1121,2017,1521,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/ENGL-English/900/ENGL-999','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1122,2022,1522,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-395','<div class="desc"> <p>Research under guidance of faculty member on jointly selected project. May be taken four times for credit. Permission of instructor required.</p> </div>','GEO 105 and GEO 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1123,2022,1523,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-309','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables and riddles to anecdotes, jokes, short stories and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin and Twitter. This course will meet three times a week, twice with CSLC 109, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1124,2022,1524,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-382','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>','Greek 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1125,2022,1525,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-230','<div class="desc"> <p>This course is a critical survey of some great ideas that have shaped Western civilization. We will consider, among others, Homer, Sophocles, the Pre-Socratic philosophers, Plato, Aristotle, Cato, Marcus Aurelius, the Hebrew Bible and the New Testament, the Scholastics, Machiavelli, Luther, Copernicus, Galileo, Bacon, Locke, Voltaire, Rousseau, Condorcet, Mary Wollstonecraft and Mary Shelley, Marx, Darwin, Nietzsche, Virginia Woolf, and Simone de Beauvoir.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1126,2020,1526,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-236','<div class="desc"> <p>This course covers the ruptures and changes which characterized Jewish life in Europe for over two thousand years. However, we will focus on the social, political, religious, and economic encounters between Jews and other European peoples in the modern period. To this end, the course will encompass topics such as: early migrations under the Roman Empire, Medieval scholarship and persecution, efflorescence in the Muslim Iberian period, the birth of Ashkenaz, the Spanish Inquisition, shtetl life, Jewish Enlightenment, urbanization, secularism and the rise of nationalisms, Hasidism, the Holocaust, and postwar Jewish life up to today. Readings will consist of primary and secondary material.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1127,2022,1527,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/200/kine-299','<div class="desc"> <p>This course will explore the impact of sports participation on female experiences, specifically considering multilevel psychological and socio-cultural women’s empowerment measures, such as self-esteem, self-efficacy, and solidarity. Focusing primarily on soccer, we will consider the possibility that the very act of training the body through sports contributes to a greater sense of ownership of one’s body – a critical psychological state for women’s health, personal security, and, ultimately, empowerment. Through the framework of social cognitive theory of gender development, we will also examine the relationship between physicality, psychology, and gender identity development. Finally, over the course of the semester, we will vet sports participation as an intervention to address gender inequality, including the impact of relevant policy, such as Title IX. Through a community-based learning component, students will have the chance to engage in qualitative inquiry on the effect of sports on health and self-concept. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1128,2022,1528,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-341','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. In this language intensive course we will read selections from Seneca''s <em>Epistulae ad Lucilium </em>as well as Horace''s <em>Satires</em>.</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1129,2019,1529,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/MAC-Media-Arts-and-Culture/100/MAC-110','<div class="desc"> This 2-unit course focuses on the fundamental processes and tools involved in digital design for the media arts: color, resolution, image manipulation, compositing, typography, vector graphics, basic Web design, project workflow, and output/finishing formats. Students will become familiar with the interfaces of essential software platforms including Photoshop, Illustrator, and Dreamweaver and will apply concepts and techniques to various assignments. This course satisfies the Introduction to Digital Design prerequisite required for many courses at Art Center College of Design. </div>','Open only to MAC majors and minors. Instructor permission required',NULL,NULL);
INSERT INTO course_descriptions VALUES(1130,2020,1530,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/mac-media-arts-and-culture/100/mac-143','<div class="desc"> <p>This 100-level gateway course introduces students to key concepts and methodologies for the critical analysis and interpretation of a broad range of media forms across the visual field - including film, television, social media, photography, games, advertising, etc. - and the cultural, historical, and ideological forces that govern them. Drawing from select case studies in media and visual culture, the course emphasizes critical reading, discussion, and writing, with forays into digital scholarship. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1131,2020,1531,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/mac-media-arts-and-culture/100/mac-146','<div class="desc"> <p>This 100-level gateway course breaks down the aesthetic components of film and examines each element''s function in the production of meaning in a text. The course underscores the fact that cinema''s aesthetic language is not solely generated by Hollywood. It is a fluid system, highly contingent upon cultural, temporal, technological, and economic considerations. Selected international and alternative cinema movements will be examined for their enduring influences upon the global audiovisual aesthetic lexicon. Students will learn to connect formal analysis to cultural criticism and will engage with key disciplinary theories and writing methodologies. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1132,2022,1532,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-220','<div class="desc"> <p>This course focuses on theory, form, and practice of audiovisual, time-based storytelling for screens. Through a series of screenings, critical readings, creative writing exercises, and the crafting of short screenplays, students will become versed in the critical, political, and creative potentials of writing for screen cultures, including manipulation of time, space, and point of view, character development, and narrative theory. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1133,2022,1533,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-240','<div class="desc"> <p>This course builds upon the critical and historical grounding of MAC 100-level gateway courses, providing students with foundational media production skills and exposure to the wide-ranging creative possibilities of time-based media practices. Students will conceptually and practically explore historical and contemporary approaches to fictional, documentary, and experimental media through a series of production projects, each supplemented by a range of readings, exercises, technical workshops, guests, screenings, and critiques. Permission of instructor required. Not open to seniors.</p> </div>','MAC 143, MAC 145, or MAC 146 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1134,2022,1534,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-244','<div class="desc"> <p>This intermediate topical course of varying emphases focuses on representations of difference, while underscoring the connections between race, class, gender, and sexual identity. Through screenings, and key texts from film and media studies, cultural studies, gender studies, and visual culture studies, students will learn critical methodologies for analyzing a range of media forms and the complex relationship between authors and spectators. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>The Female in Japanese Film and Media </strong></p> <p>The course will consider the role of the female in Japanese film in front of and behind the camera. In the current climate of the #metoo and #timesup campaigns and revelations of sexual harassment in the Hollywood film industry, where does the Japanese film industry stand? This course will look at Japanese cinematic history whose roots are embedded in the studio system in Kyoto and consider how the role of women in film has been shaped by a changing society’s values and norms. The contributions from Japanese female film directors such as the pioneers Sakane Tazuko and actress-director Tanaka Kinuyo to their contemporary counterparts such as award-winning Kawase Naomi, the pink films of Hamano Sachi, relationship driven films of Mishima Yukiko, to the fashionable flair of Ninagawa Mika. We will look at emerging female filmmakers such as Oda Kaori, Endo Maiko, and media artist Sputniko! who are using the format of the moving image to engage Japanese audiences in global issues. In addition to looking closely at works from female film directors, the course will examine tropes and representations of iconic actresses within Japanese cinematic history to appropriation of Japanese culture in pop music videos. <em>Additional Core Requirement Met: Regional Focus.</em></p> <p><strong>Cultures of Protest</strong></p> <p>The English word <em>protest</em>– “to declare publicly” – derives from a Latin verb meaning “to testify, give witness.” In this course we will explore a variety of films from different geopolitical regions and of different genres and different historical contexts that might be interpreted as speaking to all kinds of modalities of protest: protests against nationalisms, against ethnic cleansings, against xenophobia, racism, and homophobia, against national violence and against gender purity. We will engage with different understandings of the concept of protest and focus on its relation to migration, foreignness, national identity, racial, gender, and sexual politics, border politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations.</p> <p><strong>From Cyborgs to Siri: Gender, Technology and Media</strong></p> <p>In this course, we will examine the fembots, cyborgs, and female AIs imagined in film, television, and advertising, as well as the dialogue between these fictional creations and their real-life counterparts, from historical automata to the current development of robotic and virtual companions. How does techno-fantasy inform scientific reality, and vice versa, in the construction of these figures? What roles do we ask them to play in both realms? What might they reveal about our cultural hopes and fears around love, sex, and relationships? What social, cultural and historical conditions give rise to, and shape, their appearance? Why are they, simultaneously, so disturbing and fascinating for us? In answering these questions, we will examine issues around gender, sexuality, and race, while drawing from a wide range of critical discourses, including cyborg feminism, post-humanism, and afrofuturism. Screenings will include Metropolis (1927), Stepford Wives (1927), Ghost in the Shell (2003), Her (2013), and Ex Machina (2015).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1135,2022,1535,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-248','<div class="desc"> <p>A survey course on the global language of film and media. Screenings and readings will cover a range of national contexts, examining questions of national identity, national cinema, alternative cinema, Third cinema, experimental ethnography, diaspora, postcoloniality, globalization, and transnationality. The course will take advantage of the international and intercultural makeup of Los Angeles, as a means of exploring media and accessing practitioners who are working across national boundaries. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics fulfill distinct Core requirements. </strong></em></p> <p></p> <p><strong>Foreigners and Cinematic Border Crossings</strong></p> <p>What does it mean to be-placed-into-foreignness? To be marked as foreign? To inhabit this category and feel its weight? We know that certain bodies, or regions, are labeled as foreign, but also texts and images. “Foreign” is a sticky term – it sticks to the body of a human, or to a particular image or sound – and it marks it as something else, as something other than me, alien, some form of alterity. How do transnational cinema and media approach representations of foreignness? How do they engage questions of aesthetics, politics, and ethics? We will explore these questions while focusing on films and media that privilege transcultural encounters and border crossings in various global locations. <em>Additional Core Requirement Met: Global Connections.</em><br/> <br/> <strong>Transnational Cinemas: Borders, Walls, Difference</strong></p> <p>In film studies, the term “transnational” has opened up new ways of thinking about cinema, its production contexts, spectatorship, and ideological investments. We will explore different understandings of the concept of transnationality and focus on its relation to migration, foreignness, national identity, racial politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). We will screen a number of fascinating films and videos from multiple regions of the world. The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>African Film and Media</strong></p> <p>Africa has one of the largest film industries in the world. This course surveys significant film and media traditions within Africa along with their aesthetic, political, and cultural contexts. We will explore African film and video across a broad array of traditions, mediums, and historical periods including the griot, Yoruba theatre, colonial visual culture, independence and liberation films, counter-ethnography, the Négritude movement, Third Cinema, post-independence Francophone Art films, sub-Saharan Black African cinema, FESPACO, Anglophone Nollywood and Ghana popular video, and African new media. The goal is to focus on distinctly African film and film scholarship by critically examining the various conflicting traditions and methodologies of cross-cultural African film studies. This course will involve seminar-style discussions, presentations, extensive screenings (in and outside of class), guest lectures by African filmmakers and scholars, and critical writing. <em>Additional Core Requirement Met: Regional Focus</em>.</p> <p><strong>Transpacific Social Justice</strong></p> <p>This course will explore a variety of contemporary film and multimedia productions, with a focus on social justice issues across the transpacific. Topics discussed may include, but are not limited to: race, gender, and sexuality in a networked world; war and its aftermaths; labor rights; and digital media advocacy. What are the implications of multimedia technologies for social justice and democracy, especially in marginalized communities across the Pacific and their diasporas? Students will learn about emerging art and activist movements in Asia and the Pacific through a variety of screenings, readings and lectures. There will be a particular focus on materials coming from social justice movements such as documentary film, independent film, and activist art. We will review and analyze different perspectives, for example, a rising intersectional feminist movement in South Asia, sexual politics in East Asia, participatory videos created from migrants in Southeast Asia, to the student uprisings of Taiwan’s Sunflower Occupation and Hong Kong’s Umbrella Revolution and current protests. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1136,2022,1536,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-250','<div class="desc"> <p>This hybrid media theory and practice course directly engages the interrelationship between discursive and creative production. Classes will include screenings, lectures, discussion, and hands-on experiences in producing and collaborating on digital media projects. Topics courses may be repeated with a different topic for credit.</p> <p><strong>Media Activism through Participatory Video</strong></p> <p>This is a combined theory and practice course that will engage students in looking critically at what participation means when working with members of a community. In participatory video, who holds the camera often determines who holds the power. By gaining an understanding of documentary film and ethics, we will question the relationship between filmmaker and subject. Students will learn about working with community, developing relationships and trust, and how to collaborate using participatory methods. Through readings, screenings, and guest lectures, the course will explore the potential of using digital media tools to engage communities in media activism. Students will be introduced to a variety of methodologies that will lead up to a final collaborative project that will engage a local community in participatory video. This final project will result in a series of public workshops, screenings, and exhibition.</p> <p><strong>Visual Design and Composition for Media</strong></p> <p>This theory/practice course introduces and deepens student fluency in design methods for communicating concepts and stories visually using cinematic and emerging media formats. Students will closely examine current and historical examples of how formal visual design components communicate non-verbal content and information - composition, color, value, line, shape, depth, visual rhythm, camera movement, and more. In addition to critical reflection, students will integrate and demonstrate their learning through the creation of still photographic images, short cinematic sketches, and visual ideation for emerging media. The course also considers how to research, design, and communicate an overall visual structure plan for a project, and how the visual structure relates to and supports other narrative or non-narrative structures. Finally, students will consider how these principles are engaged, extended, and challenged through emerging media forms.</p> <p><strong>The Video Essay</strong></p> <p>In this theory/practice course, we will explore what it means to “think and write with video” about film, media, and popular culture. Readings, screenings, and class discussions will engage the history of the video essay, including its filmic precursor, “the essay film”; debates about what makes a video essay scholarly; and a variety of formal, aesthetic, and rhetorical strategies for communicating ideas through moving image and sound. Student work will involve a series of hands-on assignments building towards a scholarly video essay that can be submitted to an on-line journal.</p> <p><strong>Game Design Workshop</strong></p> <p>This course will introduce students to the foundational concepts of game design through the practice of creating video games. Video games are products of culture, and this course approaches video games as media artifacts worthy of analysis, critical design, and purpose-focused production. In this course, students will learn digital tools for video game creation, such as an introductory-level game engine, basic programming skills, and audiovisual design. Students will also question and critique theories and foundational practices of game design. Readings, lectures, and in-class exercises will explore the expressive and political possibilities of games as cultural productions. No previous programming or game design experience is required.</p> <p><strong>Reimagining Social Media Practice</strong></p> <p>This course seeks to dismantle conceptions of the internet and social media as distribution platforms and instead critically and creatively reimagines them as a production medium, one capable of producing unprecedented media content, communities, and cultural interventions. Students will engage with theories of social media and online communities by engaging with projects that explore these issues from a practical hands-on perspective. Students will become social media and online content creators to accomplish three main goals: become literate in the social media content creation process, understand current research and theories on social media and online communities, and transgressively examine the implications of a culture imbued with social media and online content. Topics to be explored in the class include influencer culture, cyberbullying, the Alt Right, strategy, public crises, identity communities, election hacking, fake news, and psychological and social implications of social media use.</p> <p><strong>Digital Tools for Radical Change</strong></p> <p>This theory and practice course takes a critical look at the use of media communications and social media in resisting oppression and organizing for social change. Readings, class discussions, and creative assignments will engage a variety of case studies in which digital and social media were used to shape debates, advance causes, build networks, and encourage civic participation, including #BlackLivesMatter, @realdonaldtrump, and the ACLU''s Mobile Justice app. Throughout, emphasis will be placed on the art of communication as the single most important aspect of effective community organizing, activism, and advocacy. Students will put theory into practice by conceptualizing, executing, and evaluating a digital advocacy campaign via social media. Their work will be supported by skills-based workshops and class visits with Los Angeles media activists and social media influencers, which will help equip them with practical tools and insight into digital and creative practices for achieving specific goals. This course is being linked to a Cinematheque series and will include a few mandatory screenings on Thursday nights. </p> <p><strong>Remix Media and Culture Jamming</strong></p> <p><em>What is Remix media?</em> Remixing, reusing, and reworking separate media elements from different sources to produce an entirely new work with a different meaning. <em>What is Culture Jamming? </em>Coined by Oxy alum ''82 Marc Dery, "culture jamming" is an anti-consumerist tactic used to disrupt or subvert dominant media culture, including (but not limited to) corporate advertising. This theory/practice course takes a critical look at the history of remix culture—from Dada to Machinima—along with the gamut of aesthetic, political, and social concerns addressed by remix artists and musicians and the reception (and even appropriation) of their work by the corporate entertainment industry. Students will put theory into practice by producing their own remix projects including a <em>subvertisement </em>and remix video. We will also explore issues around copyright and fair use in the sampling of both commercial and independently-produced works.</p> <p><strong>Public Media and Alternative Exhibition Strategies </strong></p> <p>For over 25 years Anne Bray and her Los Angeles organization FREEWAVES have created public media art events that bring diverse audiences and independent media artists together in dialogue on current issues in nontraditional, community-focused exhibition contexts. This hands-on course will engage students in theoretically and practically exploring past precedents and future possibilities for innovative and people centered media curation and exhibition. Students will work with Bray to conceptualize and realize alternative public media programming interventions on campus, in Los Angeles, and online, examining critical questions of space/venue, audience/community, and outcome/social engagement.</p> <p><strong>Mockumentary</strong></p> <p>This hybrid course blends theory, history, and practice to introduce students to the hands-on technical skills in mockumentary film production. Simultaneous to crafting your own video works, students will investigate the longstanding transnational and political history of mockumentary ranging from Buñuel to Borat. This analysis of mockumentary also proves invaluable in revealing, denaturalizing, and inspiring many of the conventions of documentary realism. Far from being polemical against documentary, this course not only examines how mockumentary can expose the lies and fakery already at work in claims to objectivity but also highlights the authenticity of film artifice.</p> <p><strong>Media &amp; Social Movements in Los Angeles</strong></p> <p>This theory/practice course focuses on the relationship between media and social justice struggles in the greater Los Angeles region. Readings, class discussions, and creative assignments will address the use of media tools as a form of local and global resistance against various forms of economic, racial, sexual and gender oppression. Students will learn about the theoretical and material tensions between the global political economy and local grassroots media movements, ranging from Asian American video collectives of the 1970s to the Los Angeles School of Black Filmmakers (a.k.a. L.A. Rebellion film movement) of the 1980s. In the latter half of the semester, we will examine contemporary sites of media activism online, including but not limited to #blacklivesmatter, QWOCMAP, and the Asian American Oral History project. Weekly labs will provide opportunities to explore various media forms and strategies in order to critically analyze why certain platforms have emerged within different movements and what political possibilities still resonate. While labs will focus on audiovisual production and social media, there will be room to experiment with other forms of media resistance including ‘zine-making, comic books, and musical performance (e.g. critical karaoke, flash mobs, etc.). We will be joined throughout the semester by media activists and local community organizers, who will share their perspectives on contemporary struggles and, at times, lead skills-based workshops. The course will culminate in a final project in which students conceptualize and begin to execute a media campaign with a Los Angeles-based community organization. <em>Additional Core Requirement Met: United States Diversity</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1137,2017,1537,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MAC-Media-Arts-and-Culture/200/MAC-258','<div class="desc"> This course introduces students to the art of film scoring and provides an in-depth exploration of the field. We will discuss functions of film music and analyze preexisting scores that demonstrate varying dramatic situations, while also investigating the aesthetic relationship between film and music. Students will be required to write music for preexisting scenes throughout the course, as well as score student short films (senior comps) from Media Production majors. This course may be repeated one time for credit. </div>','Music 100 or permission of instructor (basic experience using Logic, Ableton Live, or other DAW (Digital Audio Workstation)) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1138,2022,1538,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-490','<div class="desc"> <p></p> <p>Advanced year-long pro-seminar (seniors enroll for 4 units in the fall, and again for 2 units in the spring) designed to provide guidance and intellectual community around the completion of a Critical Media comprehensives project. This class is only open to senior MAC majors in the Critical Media Concentration.</p> <p></p> </div>','MAC 390 and two courses from MAC 241, MAC 244, MAC 246, MAC 248, MAC 250, MAC 252, MAC 260, MAC 295 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1139,2022,1539,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-491','<div class="desc"> <p>Advanced fall-semester course (4 units) designed for the collaborative development and photography of Media Production comprehensive projects. Media Production seniors will then enroll in the spring-semester MAC 492 Advanced Editing class (2 units) to scaffold post-production. This class is only open to senior MAC majors in the Media Production Concentration.</p> </div>','MAC 355, MAC 390, and if making a fiction project MAC 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1140,2020,1540,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/100/musc-100','<div class="desc"> An introduction to the use of the Occidental electronic music studio and the creation of electronic music with synthesizers, computer and digital recorders. May be repeated once for credit. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1141,2022,1541,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-350','<div class="desc"> This course approaches musical form and genre from a stylistic point of view. Intense focus on details at both the surface and background levels of musical activity -- melodic, harmonic, rhythmic, and sonic (texture, density, articulation, dynamics, timbre) -- will yield a broad understanding of the ways in which all aspects of musical language influence musical form and style. Readings will reinforce the connection between culture and style, yielding discussion of issues around links between intellectual history and musical genre. For example, why did the fugue evolve and flourish during the Enlightenment and the Scientific Revolution? What happened to opera''s da capo aria after the 18th century, and why? Repertoire will be chosen in conjunction with students, and may include works from the Renaissance to the 21st century. The final project will be an analytic paper and a classroom presentation based on this work. </div>','MUSC 250 and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1142,2022,1542,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-233','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing/singing, and strengthening of improvisation skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1143,2022,1543,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-234','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of improvisation skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
