INSERT INTO course_descriptions VALUES(1153,2022,1553,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/100/pols-150','<div class="desc"> <p>This course is an introduction to the study of politics and political theory through prominent Western political theorists from the Ancient Greeks to the 20th Century. Course themes include theories of human nature the origins of law and government the rise and development of different political institutions and citizen relationships with the state.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1154,2022,1554,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-282','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on environmental law and public policy. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(1155,2022,1555,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-283','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on public health policy in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286).</p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(1156,2022,1556,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-284','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on women''s leadership in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(1157,2022,1557,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-302','<div class="desc"> <p>This course examines the institution and practices of the American presidency. More specifically it encourages students to analyze the role and structure of this office as well as different ideas about presidential power and influence. Particular attention is paid to the presidency and policy making media coverage checks and balances the Constitution and public opinion.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1158,2019,1558,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PSYC-Psychology/Information-Processing-Domain/PSYC-436','<div class="desc"> <p>This course concerns cognition broadly defined across diverse taxa of nonhuman species. Processes including perception memory spatial navigation associative learning social cognition and reasoning will be examined. Comparison to humans will be considered. Theory and empirical research will be examined in depth including detailed consideration of methodological issues that arise when one species studies another. Students will have significant responsibility for discussion and individual inquiry.</p> </div>','PSYC 301 PSYC 302 PSYC 306 or PSYC 336 .',NULL,NULL);
INSERT INTO course_descriptions VALUES(1159,2022,1559,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-110','<div class="desc"> <p>A survey of historical and contemporary Native American religious traditions, attending especially to how they have developed amid colonization and resistance. Students will study the broad variety of ways that Native American traditions imagine land, community, and the sacred, and study the range of practices, ceremonies, and cultural institutions related thereto. Students will also investigate how these religious traditions have been contested or negotiated when they came in contact with Christian missionaries, in contemporary treaty rights, and in intertribal new religious movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1160,2022,1560,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-230','<div class="desc"> In United States history, law has regularly been used to subordinate racial and religious minorities, while law has also been used as a tool in these groups'' struggles for liberation. This course approaches law as a feature of culture, as both a product of cultural (including religious) context and a mechanism to effect cultural change. Students will study cases where religious freedom arguments served to oppress the Queer community, the Disabled community, and Women, as well as cases of struggles for religious liberty among Indigenous, Black, and Mixed communities in the US. By analyzing legal discourse from the lenses of Postcolonial, Feminist, and Critical Race Studies, students will come to understand that law is not neutral or objective and students will better discern how both religion and law operate at multiple, overlapping levels in society, contesting and constructing meaning. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1161,2022,1561,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-332','<div class="desc"> Many of Russia''s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements while at the same time creating some of the most memorable texts of the twentieth century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin, using original Russian texts to examine the use of language in the creation of science fiction and fantasy texts. Additionally, film adaptations will be shown, including the avant garde film Aelita the Queen of Mars and Andrei Tarkovsky''s masterpiece, Stalker. The course only introduce students to modern Russian literature while at the same time examine how Russian writers used science fiction to criticize society and government. </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1162,2022,1562,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-215','<div class="desc"> Who are you? Why are you? How do you know? Surely you have heard the phrase "nature vs. nurture." It is about the ongoing quest to figure out how much of a human is genetic, biological, and chromosomal (nature), and how much is a product of socialization (nurture). To what extent are you your society? To even consider that question, we must examine the society itself, the individuals that produce it, and how the two are connected. The society and selves we will be examining are our own -- in particular, the society and selves of young Americans. How does the world you''re facing today make you who you are? How do the technology and media through which you learn about your world permeate, shape, and structure your everyday experience of self and society? Who do you want to be, who will you end up being, and what kind of world will you create? </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1163,2022,1563,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-306','<div class="desc"> <p>This course introduces qualitative research methods from a social science perspective. We will cover systematic qualitative research design data collection and analysis. Techniques will include interviewing focus groups ethnography and/or qualitative content analysis. By the end of the course you will have mastered basic concepts and techniques and be able to carry out basic qualitative research.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1164,2022,1564,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-340','<div class="desc"> China''s Environmental Challenges: A Sociological Perspective This course examines China’s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China’s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. Cross-listed with East Asian Studies and Urban and Environmental Policy. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1165,2020,1565,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-299','<div class="desc"> This course will explore the impact of sports participation on female experiences, specifically considering multilevel psychological and socio-cultural women''s empowerment measures, such as self-esteem, self-efficacy, and solidarity. Focusing primarily on soccer, we will consider the possibility that the very act of training the body through sports contributes to a greater sense of ownership of one''s body -- a critical psychological state for women''s health, personal security, and ultimately empowerment. Through the framework of social cognitive theory of gender development, we will also examine the relationship between, physicality, psychology, and gender identity development. Finally, over the course of the semester, we will vet sports participation as an intervention to address gender inequality, including the impact of relevant policy, such as Title IX. Through a community-based learning component, students will have the chance to engage in qualitative inquiry on the effect of sports on health and self-concept. Same as Kinesiology 299. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1166,2022,1566,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305a','<div class="desc"> Weekly laboratory for Urban Data Analysis where students will directly manipulate, analyze, and visualize real-world data related to urban problems and policy concerns, such as poverty, wages and low-wage work, housing affordability and quality, transportation equity, air quality, water safety, green space, food access, and crime and public safety. We will focus on identifying and communicating patterns of urban inequality. Students will become familiar with Excel and be introduced to Stata, a statistical software package. Students will learn to manage data, produce basic charts and graphs, generate descriptive statistics, and test hypotheses. </div>',NULL,'UEP 305',NULL);
INSERT INTO course_descriptions VALUES(1167,2022,1567,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-340','<div class="desc"> This course examines China''s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China''s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1168,2022,1568,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-256','<div class="desc"> <p>This course examines memory and forgetting in the context of the post-World War II period. It will consider how massive physical destruction necessitated the reconstruction of urban landscapes in Germany, France, England, Japan, and the United States. We will study urban redevelopment, in addition to architectural structures such as museums, memorials, and monuments, in order to discern how governments, societies, and individuals attempt to come to terms with the historical past. We will ask the following questions: What role do museums, memorials, and monuments play in the architectural landscape of a city? What design restrictions are posed by these types of institutions? How are abstract and representational forms employed in the memorialization process? Through an examination of these questions, students will gain an understanding of diverse built environments within an era marked by fundamental shifts in (post)modernism, technology, and aesthetics. To this end, emphasis will be placed on the ways in which memory and place are conceived within particular cultural and intellectual circumstances.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1169,2022,1569,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-257','<div class="desc"> <p>This course will interrogate 20th and 21st century architecture of the Asia Pacific. By concentrating on specific episodes of architectural production and urban development in the region, this course seeks to examine varying notions of the modern as it shifts across space and time. Considering theoretical and concrete modes by which modern societies and built environments have operated in tandem to create aesthetic, socio-political, economic, and technological networks will serve to frame the ways by which the Asia Pacific has come to be regarded as the crossroads for dynamic and experimental approaches to contemporary architecture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1170,2022,1570,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-209','<div class="desc"> <p>This course is a conceptual art class that takes photography as its subject. Using a wide range of photographs and photographic practices, the class will consider how photographs are instrumental in forming our notions of self, family, work, and nation. We will also grapple with the difference between analogue and digital photography and photography''s relation to the physical world. The class will read key photography essays that will challenge students to think critically about the role of photography in contemporary culture and modernity, historiography, and science. We will use a broad range of art techniques like drawing, painting, printmaking, sculpture, digital alteration, and even craft techniques to remake and rework photographs to reveal hidden truths or create new meanings. Unlike some classes where you learn art techniques first, here you will be expected to adopt techniques and generate art from a set of ideas that arise from our readings, discussions, experiments, and field trips.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1171,2022,1571,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-280','<div class="desc"> <p>A team-taught course pairing an Occidental and an Art Center College of Design faculty member in project-based work integrating the history, theory, and practice of the visual arts. Not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1172,2022,1572,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/chem-chemistry/200/chem-201','<div class="desc"> <p>Intensive study of the modern laboratory methods of analysis, with applications to biochemical and environmental systems.</p> </div>','CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1173,2017,1573,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CLAS-Classical-Studies/200/CLAS-223','<div class="desc"> <p>This course will focus on ancient heroes in Greek and Roman myth such as Hercules Theseus Jason and those featured in the Trojan War. Ancient heroes partake of both the divine and mortal realms and as such help us appreciate the ways in which myths were used in order to interpret the world. We will consider the nature of the heroic through the depictions of ancient writers and artists and consider modern heroic ideals in relation to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1174,2022,1574,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-340','<div class="desc"> <p>This course focuses on the process and technology behind making intuitive and useful websites and the techniques for determining the effectiveness of the products, including prototyping and user testing. Students will also explore how principles of attention, perception and cognition guide relate to user experiences. </p> </div>','COMP 131 or COGS 101, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1175,2022,1575,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-200','<div class="desc"> <p>Drawing upon literatures and language traditions from across the world, the immediate object of this course will be to help students develop a lively appreciation for, and analytic facility with, each of the major kinds of literary production (lyric, narrative, and drama), all of which we shall try to examine in their “traditional” forms, as well as in some of their more familiar contemporary ones (not only the lyric poem and the prose novel, but the popular song, the graphic novel, and the television series, too, will fall within the special compass of our inquiry). Beyond these immediate goals of familiarity and competence, however, the wider ambition of this course will be to develop students’ understanding of the crucial role that literary (and literature-based) forms play in the constitution of the cultures we inhabit and the various "subject-positions" we might occupy within them. To this end, we shall make ourselves familiar with some of the most important thinkers in recent literary and cultural theory (Foucault, Derrida, Kristeva, Sianne, and Ngai, to name but a few). Given the course’s broad international range, guest lecturers will be brought in throughout the semester to discuss the effect of reading works in the original language and to explore, more generally, the effect that the specific features of a language can exert over that delicate interplay of “literature, culture, and self” that forms the central subject matter of this class. This course serves as the Proseminar for CSLC, and is required for the major but is open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1176,2022,1576,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-220','<div class="desc"> <p>This course is concerned with the cultural politics of memory and trauma after 1945. We will start with basic questions, such as: whose memories are sought, believed, and commemorated in the public sphere? What problems do traumatic events present for those attempting to represent them? Is trauma a useful cultural concept? What are the differences between individual and collective memory? We will then identify the recent fascination, especially in European and American culture, with the phenomena of trauma, suffering, and victimhood, and focus on the impact on Jewish identity (in various countries), as well as the collective memory of Germans, after 1945.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1177,2022,1577,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-233','<div class="desc"> <p>Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939, when the Soviet Union was busily partitioning Poland with Nazi Germany by secret agreement. This course examines the cultural history of Russia and the Soviet Union, in specific regard to its evolving theories of language, literature, and cultural phenomena during the early 20th century. Particular attention is paid to Russian formalism, poetics, and semiotics, as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence, mutual East-West suspicion, social repression, and exertions of state power through propaganda and censorship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1178,2022,1578,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-280','<div class="desc"> <p>In this course, we shall attempt to come to terms with three of the most important - and provocative - philosophers of the last two hundred years, philosophers without whom the great majority of contemporary literary and cultural theory (and much art and literature, as well) would, essentially, be unthinkable. Significantly, all three of these philosophers habitually turned to ancient Greek tragedy in the formulation, articulation, and further elaboration of their thought. In this class, we shall therefore attempt to use the experience of Greek tragedy, in all its ecstatic strangeness, as a powerful point of entry into the difficult yet crucial works these philosophers have bequeathed to us. Major texts to be covered include: the plays of Aeschylus and Sophocles, <em>The Phenomenology of Spirit,</em> <em>The Birth of Tragedy,</em> <em>Thus Spoke Zarathustra,</em> <em>Being and Time,</em> and <em>Introduction to Metaphysics</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1179,2022,1579,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1180,2017,1580,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CSLC-Comparative-Studies-in-Literature-and-Culture/900/CSLC-999','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1181,2022,1581,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-197','<div class="desc"> <p>Directed individual study. Permission of instructor and department chair required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1182,2022,1582,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-222','<div class="desc"> <p>The course offers an interdisciplinary analysis of gender, power, and the body. The theoretical center of the course will be Foucault''s work on biopower, including <em>Discipline and Punish</em> and <em>Foucault 2.0</em>. Topics include: class and the body (Atwood''s <em>Bodily Harm</em> and Larsen''s <em>Passing</em>); law and the female body (Wendy Williams and Mary Poovey); science and gender (Emily Martin and Thomas Laqueur); pornography (Catherine McKinnon and Laura Kipnis); race, body, and gender (Morrison''s <em>Beloved</em>; Lauren Berlant and Judith Butler); multiculturalism and cross-race identifications (John Stahl''s <em>Imitation of Life </em>and Wyatt''s <em>The Hazards of ldealization</em>); and Latin American perspectives on gender, torture, and memory. Open to students with sophomore standing or higher.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1183,2020,1583,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-234','<div class="desc"> <p>Is there such a thing as a "woman''s condition" and can that condition be explained by examining the economic dimensions of women''s history? Is the violence that people are disproportionately exposed to, based on gender, race, sex, and sexuality, only a tool in the production and reproduction of economic classes, or do these identities and experiences require an analytic framework that transcends economic relations? In this course, we will consider a particular intellectual tradition that engages these questions: materialist feminism. We will begin our readings by considering texts by Marx and Engels that form the backbone of this tradition. We will then consider texts from American, British, and Italian traditions of thought and activism that include feminists working in national and transnational women of color traditions. Readings will include: Michèle Barrett, Hazel Carby, Carolyn J. Eichner, Silvia Federici, Combahee River Collective, Mariarosa Dalla Costa and Selma James, Angela Davis, Friedrich Engels, Rosa Luxemberg, Karl Marx, Heidi Hartmann, and Denise Riley.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1184,2020,1584,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and criticism as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations, power, knowledge, and identities are constituted through private and public rhetorical acts. Through our readings, we will engage a wide range of contributions to a rhetorical critical history by women who, either as practitioners or theorists, advanced their visions of social change and acted to implement them. Course readings will begin in antiquity to provide a foundation for our study, though much of our material will focus on texts from the 19th century to the present, to examine the intersections of gender and rhetoric. Through this work, we will challenge the seeming erasure of women from this critical history, and interrogate the notion of "feminist rhetoric" as merely a corollary to a masculinist tradition. Assignments will include critical essays and a visual rhetoric project on representations of women in the media and popular culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1185,2019,1585,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/CTSJ-Critical-TheorySocial-Justice/300/CTSJ-352','<div class="desc"> <p>This course will examine space place and geographies as matters of social justice. Students will read theoretical materials on the spatiality of justice. We will look at themes of shifting and overlapping communities; histories that shape present conditions of neighborhoods; intersections of race gender sexuality class and their impact on meanings of place; and issues surrounding gentrification and displacement in Los Angeles neighborhoods. The course will center on a community-based research component with a community partner doing work in Los Angeles around gentrification and displacement. Students will learn to use digital technologies as tools for researching analyzing and contributing to community efforts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1186,2017,1586,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/DWA-Diplomacy-and-World-Affairs/200/DWA-223','<div class="desc"> <p>This course examines how globalization affects the lives of workers across the globe. The course analyzes the impact of changes in the global political economy over the last fifty years on workers'' rights working conditions and living standards. It evaluates strategies adopted by worker organizations and advocates in response to these changes. Students will gain a working knowledge of major changes in the global economy by examining the geographic relocation of jobs and workers the changing roles of firms and states public debates over sweatshops and other human rights abuses and the emergence of new legal regimes governing worker rights. Case studies are drawn from across the globe including the U.S. focusing on commodity chains (e.g. apparel) regions (e.g. China) or specific populations (e.g. migrant workers). Students will explore different strategies for change - linking worker rights to trade agreements corporate social responsibility transnational legal strategies corporate campaigns and consumer boycotts - in order to better understand the possibilities and limitations for redressing the inequalities of globalization and shoring up of workers'' rights. Same as UEP 223</p> </div>','UEP 101 POLS 101 DWA 101 ECON 101 or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1187,2022,1587,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-224','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century, with a focus on contemporary democratic politics. The course will discuss the historical, institutional, and social forces that have both accelerated and opposed democratization, and will cover topics of current concern to the region, including: economic development, security and the rule of law, the design of political institutions, human rights, and social movements.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1188,2020,1588,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1189,2022,1589,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-236','<div class="desc"> <p>This course examines the theoretical roots, ideological expressions, and political manifestations of these tumultuous phenomena. Focusing mostly on the European experience of the late 19th through the 20th century, we will read primary texts and historical accounts pertaining to the rise and development of nationalism, communism, and fascism. Readings will cover both the national and international aspects of these movements, and explore their political, cultural, and economic programs. What will also be of particular interest is how these often competing and clashing political programs sprang from similar and, at times, common roots. Ultimately, this course will ask students to consider what the study of such ideologies has to offer for the analysis of contemporary extremism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1190,2022,1590,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-245','<div class="desc"> <p>This course will look at the relationship China has had to the world over the last 600 years. The course will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Third-Worldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the interaction between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the rise of the West, just as we will call into question the contemporary discourse on the "rise of China."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1191,2022,1591,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-352','<div class="desc"> <p>Firm-level studies are now at the forefront of international trade research. In this course, we look at firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. We use modern trade theory to analyze firm decision-making; we start with a discussion of the firm''s decision to engage in international commerce and then examine how firms choose between various types of foreign direct investment. Throughout the course, we learn from empirical studies and business case studies how firms engage in international commerce.</p> </div>','ECON 250 and ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1192,2022,1592,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-241','<div class="desc"> <p>This course looks at representations of "deviance" in 19th- and early 20th-century literature. Underlying our examination will be an investigation of what constitutes the "normal" and the ways in which normativity polices its boundaries. Focusing primarily on literary and filmic representations of the sexual, racial, legal, and economic "taboo," in works including Charles Dickens''<em> Great Expectations,</em> E.M. Forester''s <em>Passage to India, </em>and Djuna Barnes'' <em>Nightwood</em>, we will seek to uncover the terms of normativity, against which the figure of the deviant emerges into representation. We will supplement our analysis of literature with readings from a range of theoretical methodologies, from psychoanalysis, legal theory, Marxist/economic theory, to postcolonial and critical race studies. </p> <p><strong><strong>Major Requirement Met:</strong> </strong>Group II/IV</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1193,2020,1593,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/engl-english/200/engl-280','<div class="desc"> <p>This creative writing workshop will focus on fiction. Students will be required to read and write extensively, to write reports on assigned reading, to attend author readings on campus, and to participate in class examination of student work. A final portfolio is due at the end of the semester. We will examine ways of heightening imagination through both memory and perception. The course is limited to first and second year students.</p> </div>','A CSP seminar, WRD 201, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1194,2022,1594,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-322','<div class="desc"> <p>The Renaissance and Reformation in England witnessed the rise of imperial projects and the emergence of more centralized institutions to police sin and illegality in society; both were intended to enhance the sovereignty of the British state. This class explores the literary responses to such shifts in the culture of punishment and the project of state-building, asking why some of the most innovative works of drama, poetry, and prose in this period struggle with the purpose and effects of imprisonment, trial, penance, and slavery. Four main topics will organize the course: punishment and colonialism; the economic, theological, rhetorical, and theatrical underpinnings of legal trial; martyrdom; and the rise of the transatlantic slave trade. Each section of the course is divided into a series of sub-topics (ranging from questions of genre and psychology, to the humanist culture of teaching) to be explored through examination of a literary text and related historical and theoretical materials. Authors will include: John Foxe, Elizabeth I, Edmund Spenser, Michel de Montaigne, William Shakespeare, John Milton, Thomas Hobbes, John Locke, and Aphra Behn, among others.</p> <p><strong>Major Requirement Met</strong>: Group I</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1195,2022,1595,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-347','<div class="desc"> <p>This course will examine 19th century British and Indian novels in dialogue with their 20th century Bollywood adaptations. A product of the largest film industry in the world, Indian cinema is consumed globally. Questions of globalism were also central to 19th century novels that were written during the height of colonial rule. We will examine the films and novels, paying particular attention to representations of cultural subject formation, gender and racial norms, and nationalist sentiment in the era of empire and the postcolonial moment. </p> <p><strong>Major Requirement Met</strong>: Group II/IV</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1196,2022,1596,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-372','<div class="desc"> <p><strong>Faulkner, Hemingway, and Morrison</strong></p> <p>Discussion of the major novels of William Faulkner, Ernest Hemingway, and Toni Morrison, with an emphasis on race and gender in American culture. Major requirement met: Group III.</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1197,2022,1597,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1198,2022,1598,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/400/engl-499','<div class="desc"> <p>Research, writing, and defense of the Honors thesis in English. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1199,2022,1599,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-321','<div class="desc"> <p>This course is concerned with the cultural politics of memory and trauma after 1945. We will start with basic questions such as: whose memories are sought, believed, and commemorated in the public sphere? What problems do traumatic events present for those attempting to represent them? Is trauma a useful cultural concept? What are the differences between individual and collective memory? We will then identify the recent fascination, especially in European and American culture, with the phenomenon of trauma, suffering, and victimhood, and focus on the impact on Jewish identity (in various countries), as well as the collective memory of Germans, after 1945.</p> </div>','GERM 202 or GERM 232 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1200,2022,1600,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-380','<div class="desc"> <p>This course will meet at the same time as CSLC 280, and for an additional weekly meeting in which we shall translate one tragedy by Sophocles and one by Aeschylus from the original Greek. In this course, we shall attempt to come to terms with three of the most important - and provocative - philosophers of the last two hundred years, philosophers without whom the great majority of contemporary literary and cultural theory (and much art and literature, itself) would, essentially, be unthinkable. Significantly, all three of these philosophers habitually turned to ancient Greek tragedy in the formulation, articulation, and further elaboration of their thought. In this course, we shall therefore attempt to use the experience of Greek tragedy, in all its ecstatic strangeness, as a powerful point of entry into the difficult, yet crucial, works these philosophers have bequeathed to us. Major texts to be covered include: the plays of Aeschylus and Sophocles, <em>The Phenomenology of Spirit, The Birth of Tragedy, Thus Spoke Zarathustra, Being and Time, and Introduction to Metaphysics.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1201,2022,1601,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-210','<div class="desc"> <p>Oranges, palm trees, earthquakes - California is so easily summarized by a few vivid images. Yet, the history of the Golden State is even more active and vibrant than these iconic symbols suggest. In this course, we will witness the clash of colonial empires and the effects on the people caught in the crossfire; we will trace the modernization and urbanization of the state revolving around the dizzying rise of bawdy and wild San Francisco on the spoils of the Gold Rush; we will observe repeated clashes over resources and political will, following the paths of the utopians who wished to remake the society on the Pacific; we will visit the changing landscape of dreams and fantasy, from Hollywood to Disneyland; and we will, ourselves, engage with contemporary battles over public space, racial identity, and suburban sprawl. And yes, there will indeed be oranges, palm trees, and earthquakes playing their roles in this complex and varied story, as well. This survey course covers the entire sweep of the history of California, although it places particular emphasis on the past hundred years, and on urban Southern California, in particular.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1202,2022,1602,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-213','<div class="desc"> <p>This course explores free Black political organizing, from the American revolutionary era through Reconstruction. Students will conduct original research into African American activism that stretched from New York to California before and after the U.S. Civil War. We will explore the social networks and political institutions that 19th-century African Americans built to fight for civil rights, economic justice, and an end to chattel slavery. At the heart of the course is a digital humanities component that will involve students in researching the lives and ideas of individual Black activists. At the end of the course, we will contribute our collective research to the national website, Colored Conventions. While engaged in original historical research, students will also be reading exciting scholarship on the rise of free Black communities in the U.S. and the emergence of African American institutions (churches, schools, press, political organizations). We will delve into questions such as: how did free African Americans, from leadership to grassroots levels, organize for racial equality, abolition, and community empowerment? How did class structures and gender ideology shape the dynamics of Black organizing? What transnational relationships and diasporic identities did Black activists build in the protracted struggles for abolition and citizenship?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1203,2022,1603,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-245','<div class="desc"> <p>This course will look at the relationship of China to the world over the last 600 years. It will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Thirdworldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the level of interactions between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the "rise of the West," just as we will call into question the contemporary discourse on the "rise of China."</p> <p><strong>Survey Requirement Met:</strong> Asia</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1204,2022,1604,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or POLS 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1205,2022,1605,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-245','<div class="desc"> <p>In this course, students learn how to execute the fundamental aspects of creating a successful music project within the music entertainment industry. Students will work in groups to create artist profiles and business plans, which they will then execute online, by way of digital service providers such as Bandcamp and Spotify, and offline, through methods such as networking, live performance, and industry events. By fashioning distinctive artist identities, students will learn how to formulate an artist brand, including name, style, biography, and intent. They will learn how to market these projects and conduct cost-benefit analyses as they develop business plans which may include frameworks for radio, publicity, distribution, licensing, and synching. The goal of the course is to have students acquire the tools to advance their own careers along their chosen music industry path.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1206,2022,1606,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-268','<div class="desc"> <p class="sc-BodyText">This multidisciplinary course takes the crucible that was fin-de-siècle Vienna as its object of study beginning with the city’s 1890-92 expansion to include the suburbs south of the Danube to the beginning of World War I which brought an end to the Hapsburg dynasty and Austria-Hungary. Our approach to studying Vienna will be prismatic: each week will consist of one seminar on its music (principally the music of Gustav Mahler and Arnold Schoenberg) and one guest lecture on one of the following aspects of the city at this time: urban planning economics political history architecture art dance psychology medicine science and religion. The last three weeks on campus will be devoted to German language instruction and individual research projects. The on-campus component of the course will culminate in transforming Bird Studio into a Viennese coffee house which will welcome the campus community and during which students must impersonate through knowledgeable conversation a contemporaneous Viennese figure central to their field of research. This immersive on-campus study will crescendo to the downbeat of the course: the week after Commencement you will board a flight for Vienna for three weeks of intensive study there convening as a class each day attending lectures classes (including a cooking class!) and concerts and visiting the historical cultural and musical sites we studied on campus. We will take three three-hour guided walking tours of architectural monuments of historical (including music-historical) monuments and of Viennese coffee houses. Arriving during the cultural festival Vienna Festival Weeks we will attend as many of its offerings as time permits. Students must apply and participate in an interview for this course whose enrollment will be limited to sixteen students. Frosh may not apply for this course.</p> </div>','Sophomore standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1207,2019,1616,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-275','<div class="desc"> <p>This is a second course in logic. It will introduce topics in modal logic inductive logic and non-classical logic building on the foundation provided by Philosophy 225. The course will have a significant CBL component involving teaching logic and critical thinking to local high school students. As part of the CBL component of the course students will design curriculum read some philosophy of education keep a journal and write a reflection piece on their experience in the classroom.</p> </div>','PHIL 225 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1208,2022,1617,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-117','<div class="desc"> <p>An introduction to the physics of waves with examples from optics acoustics and modern physics. Also an introduction to thermodynamics including the first and second law of thermodynamics kinetic theory heat transport and phase transitions. Includes one three-hour lab per week.</p> </div>','PHYS 110 or PHYS 115; and Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1209,2017,1618,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/PHYS-Physics/Introductory-Physics-Courses/PHYS-117L','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1210,2022,1619,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-268','<div class="desc"> <p>An introduction to the physics of materials used in a wide range of engineering applications. As time permits topics will include the mechanical, elastic, thermal, electrical, magnetic, and environmental properties of metals, polymers, ceramics, glasses, composites, and "green" materials.</p> </div>','PHYS 240 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1211,2022,1620,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-223','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal" "populist" and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems including the United States; and the challenges democracies are facing in integrating formerly marginalized populations including women poor and the indigenous. It will examine the US policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1212,2022,1621,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-250','<div class="desc"> <p>American intelligence has often been at the center of the major national security controversies since the 1945. This course will survey the history of those controversies as they involved the US intelligence community, the outbreak of the Cold War and the US-Soviet competition but also the post-Cold War crises in Europe Asia Middle East and elsewhere. The basic question is: How does intelligence influence foreign policy and strategic decisions? This course provides an overview of the theory and practice of U.S. intelligence. It details the sources and methods used by collectors the nature of intelligence analysis and the complex and often difficult relationship between intelligence agencies and policymakers. It also contains a short history of the U.S. intelligence community and evaluates the ongoing efforts to reform it in an era of greater transparency. <em>Not open to first year students.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1213,2020,1622,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/pols-politics/american-politics-and-public-policy/pols-303','<div class="desc"> <p>This course examines how gender roles influence social position political engagement and allocation of power and resources in American society. Students will investigate why masculinity is often an attribute of those in power and why "femaleness" correlates with disadvantages in affluence value in society and public policies. Students will also determine what changes in the conditions of men''s and women''s lives might change the gender dynamics of politics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1214,2022,1623,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-321','<div class="desc"> <p>This course will explore the role of women in politics throughout the globe with an emphasis on case studies from the developing world. Students will examine the development of policy changes that advance gender equality paying attention to how the international system domestic institutions and social movements play in this process. Students will also study how women attain and wield power in local and national politics. The course will further emphasize how gender politics intersects with other forms of identity politics including race ethnicity and sexuality. The course is grounded in the study of comparative politics and will draw primarily on examples from Latin America Africa the Middle East and Asia.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101, POLS 120, or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1215,2022,1624,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-147','<div class="desc"> <p>In the recent history of the Americas, many groups have founded intentional communities shaped by the ideals of what a faithful, utopian society ought to look like. Some aspiring utopias, like that of the People''s Temple in Jonestown, Guyana, ended in dramatic displays of violence and death. Others, like the Mormons in Salt Lake City, have succeeded in the face of sustained adversity. But most land somewhere in between, sustaining themselves through partial integration with dominant society. In this course, we will study different intentional religious communities - often called "cults" or "sects" by outsiders - throughout the Americas. As we study the Oneidan "free love" community, an ayahuasca church in Brazil, an early Rastafari group in Jamaica, we''ll ask questions like: Why have religious people sought to separate themselves from society? How have they appealed to scripture or revelation to justify their separation? What challenges - such as external political pressure or internal strife - have they faced? What groups have been "successful," and what are the measures of success? And what do these attempts at establishing utopias tell us about what it means to be religious?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1216,2019,1625,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/RELS-Religious-Studies/100/RELS-195','<div class="desc"> <p>This course provides an introduction to Shamanism and Spirit Possession. We will use case studies from Native American and African traditions-in their homeland and in the diaspora-to investigate the historical use and scholarly conceptions of these categories. We will also explore how the use of these terms relates to the construction of Otherness and new forms of religious innovation paying particular attention to why one term (shamanism) has been used to refer to indigenous peoples of Asia and the Western hemisphere while another term (spirit possession) has been used to refer to those of African descent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1217,2022,1626,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-261','<div class="desc"> <p>Buddhism is found worldwide today and is cited as an influence in a wide variety of settings, including psychology, self-motivation movements, education, statecraft, art, music, and science. However, its historical beginnings as a religious movement 2,500 years ago in India are often left out of these discussions. Buddhism is instead commonly presented as it has been reimagined by different agents as “more of a philosophy than a religion” and compatible with Western Enlightenment ideals, such as rationalism, empiricism and science. This course will provide a critical perspective on the process through which Buddhism has been constructed by various intellectual and political agents as it has developed in the modern era. Rather than attributing these characteristics of the tradition to inherent elements in some timeless ahistorical Buddhism, the course will instead encourage critical reflection on the broader cultural, political and economic processes that have influenced the development of modern Buddhism, including global networks of trade and technological exchange, colonialism (and anti-colonialism), cosmopolitanism, nationalism, the rise of secularism, and globalization between India, China, Japan, Sri Lanka, Tibet, Britain and America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1218,2022,1627,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-333','<div class="desc"> <p>Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939 when the Soviet Union was busily partitioning Poland by secret agreement with Nazi Germany. This course examines the cultural history of Russia and the Soviet Union in specific regard to its evolving theories of language literature and cultural phenomena during the early 20th Century. Particular attention is paid to Russian formalism poetics and semiotics as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence mutual East-West suspicion social repression and exertions of state power through propaganda and censorship.</p> </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1219,2022,1628,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-225','<div class="desc"> <p>This course examines the construction and reproduction of masculinities primarily in the United States. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1220,2022,1629,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-235','<div class="desc"> Are feelings innate and universal or are they socially created and historically and culturally determined? Emotions are generally seen as individually and privately experienced, but are actually deeply social. They are embedded in, constitutive of, and created by social interactions, social structures and institutions. This course will examine the relatively new field of the Sociology of Emotions from a constructionist and interactionist perspective. Our explorations will focus on contemporary American society, but will use examples from other times and cultures to illustrate the socially constructed, experienced, and expressed nature of emotions. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1221,2022,1630,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-385','<div class="desc"> Psychology and psychiatry identify the causes of sadness, madness, anxiety, and trouble (SMAT) as originating within the "mind" or, increasingly, the brain. The sociology of mental illness, by contrast, focuses on processes in the social and cultural context, and argues that social structure, relationships, and culture are significant factors in the genesis of SMAT. The sociology of mental illness is also concerned with how the very concepts of mental illness, abnormal or crazy are constructed and used. The second half of the course focuses on the response to SMAT: how family, friends, troubled persons, and professionals interpret, define, and respond to SMAT, and the processes shaping the policies and practices of the mental health enterprise. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1222,2022,1631,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-390','<div class="desc"> <p>This course offers a survey of sociological approaches to the study of religious beliefs practices and organizations in the United States in public and private life. Exceptionally devout among developed nations the U.S. is a nation of remarkable religious diversity. We will examine the relationship between religion politics and civic life; recent trends in American religion (the "new atheism" problems of pluralism secularization and declines in religious participation the rise of evangelicalism and fundamentalisms religious conflicts); as well as theoretical arguments both classical and contemporary about the role of religion in scientifically advanced modern societies. Whereas much public debate frames religion as either a unambiguously beneficial public good or else as a font of irrationality and sectarian division we will move beyond this dichotomy toward a more empirically informed consideration of just what religion is and does in the contemporary United States.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1223,2022,1632,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-370','<div class="desc"> <p>In this course we will look at the jungle as a space where western civilizations desires and fears come into tension with the imagined "other" so that sometimes the jungle can be beautiful and desirable like the Garden of Eden and other times savage and dark like hell. Readings will include Latin American works of fiction (by Jose Eustasio Rivera Romulo Gallegos Horacio Quiroga and William Ospina) excerpts from the anthropological discourse of Wade Davis narcotraffic narratives testimonial literature (by Ingrid Betancourt and Clara Rojas) as well as environmental discourse and film in order to analyze the particular forces of history that intersect in each narrative. Topics to be discussed will include: exploitation and subjugation vs. autonomy and self determination; the search for ethnobotanical knowledge and the hallucinogenic journey; the playground and hidden operational spaces of drug traffickers; the imprisonment of the kidnapped victims from the guerrilla war against the state and paramilitary forces; the environmental movement and the concept of ecotourism. We will frame our analysis in contemporary critical theories relevant to the topics being discussed. Upon completion of this course students will be able to critically understand the value and complexity of the jungle in the geography and imagination of the Latin-American modern landscape and identity.</p> </div>','One Spanish 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1224,2017,1633,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/UEP-Urban-Environmental-Policy/200/UEP-223','<div class="desc"> <p>This course examines how globalization affects the lives of workers across the globe. The course analyzes the impact of changes in the global political economy over the last fifty years on workers'' rights, working conditions, and living standards. It evaluates strategies adopted by worker organizations and advocates in response to these changes. Students will gain a working knowledge of major changes in the global economy by examining the geographic relocation of jobs and workers, the changing roles of firms and states, public debates over sweatshops and other human rights abuses, and the emergence of new legal regimes governing worker rights. Case studies are drawn from across the globe, including the United States, focusing on commodity chains (e.g., apparel), regions (e.g., China), or specific populations (e.g., migrant workers). Students will explore different strategies for change -- linking worker rights to trade agreements, corporate social responsibility, transnational legal strategies, corporate campaigns, and consumer boycotts -- in order to better understand the possibilities and limitations for redressing the inequalities of globalization and shoring up of workers'' rights. Same as DWA 223.</p> </div>','UEP 101, DWA 101, ECON 101, or POLS 101',NULL,NULL);
INSERT INTO course_descriptions VALUES(1225,2022,1634,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1226,2022,1635,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-235','<div class="desc"> <p>Visual Rhetoric: Communication through Pictures and/or Words. This course will examine the forms and uses of visual images to inform argue and inspire--in order to analyze their effectiveness expressing ideas across the millennia from ancient civilizations through the present digital age. We will examine codices illuminated manuscripts stained glass panels and maps; combinations of words and pictures from scientists poets printers and graphic novelists; as well as digital images such as memes information graphics data visualizations and multimedia arguments. Both the theory of visual rhetoric and the making of images in some of these media will complement our exploration of these genres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1227,2022,1636,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and criticism as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations power knowledge and identities are constituted through private and public rhetorical acts. Through our readings we will engage a wide range of contributions to a rhetorical critical history by women who either as practitioners or theorists advanced their visions of social change and acted to implement them. Course readings will begin in antiquity to provide a foundation for our study though much of our material will focus on texts from the nineteenth-century to the present to examine the intersections of gender and rhetoric. Through this work we will challenge the seeming erasure of women from this critical history and interrogate the notion of "feminist rhetoric" as merely a corollary to a masculinist tradition. Assignments will include critical essays and a visual rhetoric project on representations of women in the media and popular culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1228,2022,1637,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1229,2022,1638,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1230,2020,1639,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/300/amst-325','<div class="desc"> <p>Though best known as a novelist, Toni Morrison has worked in several different capacities - as an editor, essayist, children''s book author, teacher, patron, and librettist. Her interventions in all of the fields are marked by a canny awareness of the persona she has established and the authority attached to that identity. This course examines Morrison''s multiple roles, in terms of performance and language, and connects these to a long tradition of African-American self-fashioning. Through a study of her written, editorial, and other work, we will examine the author''s transformation from "Chloe Wofford" (her birth name) to "Toni Morrison," Nobel Laureate. We will think critically about the connection between form and content, and between utterance and identity. Open to juniors and seniors and to those who have successfully completed AMST 290.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1231,2022,1640,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/100/arth-150','<div class="desc"> This introductory course examines how cities, suburbs, and metropolitan areas are designed and developed. We will explore historical episodes and actors that have influenced urban planning so that we may then consider the ways in which contemporary architects, developers, and institutions approach urban concerns related to land development, the environment, housing, and transportation. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1232,2022,1641,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-265','<div class="desc"> <p>Art - be it visual, music, dance, or literature - is an extraordinarily powerful practice, driving much of our behaviors and engaging us physically, emotionally, and cognitively. This seminar will explore the various creative arts through the perspectives of Psychology, Neuroscience, and Philosophy. Topics will range from aesthetic foundations, historical dialogues between psychology and art, as well as the biological and evolutionary bases underlying aspects of creativity and art appreciation.</p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1233,2022,1642,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-131','<div class="desc"> <p>The worldview and beliefs of the early Slavs, particularly the Eastern Slavs, were a complex synthesis of influences: Indo-European mythology, Central Asian shamanism, Scythian animal worship, and, ultimately, a "paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600, in order to understand how these people viewed the world, and how this affected their lives and the development of Slavic culture. Communal village life, legends, folk genres and mythology, their sources, and their legacies, are examined. There is a close study of the phenomenon of the vampire, following its evolution from the Iron Age into 18th century Serbia, as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined, as well. In addition to analytical and historical texts, readings include tales of supernatural beings and phenomena, as well as testimony concerning encounters with the supernatural.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1234,2022,1643,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-140','<div class="desc"> Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near-death experiences throughout the Mediterranean. While immensely entertaining and, at times, ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in post-Â­classical literature, art, and film. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1235,2022,1644,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-210','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-78) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with major figures such as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as the unprecedented boom in popularity of physiognomy around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. Concluding with the rise of Nazism and Nazi attacks on modern art as “degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. All readings and discussion will be in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1236,2022,1645,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensable for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1237,2022,1646,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-286','<div class="desc"> <p>In this class, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth’s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home" at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1238,2022,1648,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/400/cslc-490','<div class="desc"> <p>This course will guide students through the research and drafting of the Senior Comprehensive Project, and will provide students with feedback on work in progress. Open only to senior CSLC majors. Students must enroll in CSLC 490 both fall and spring for a total of 4 units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1239,2022,1649,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/200/comp-229','<div class="desc"> <p>We begin with topics found in advanced programming. In particular, topics from object-oriented programming and how this differs from procedural programming. We then move on to the study of dynamic data structures, such as linked lists, stacks, queues, trees, heaps, graphs, hash tables, sets and more. Completion of this course opens up the remainder of the Computer Science classes and is required for minors. Common themes that run throughout this course are: (1) implementation of the abstract data types, and (2) spatial and memory consideration and analysis.</p> </div>','COMP 127, COMP 131, COMP 211, a score of 4 or 5 on the AP Computer Science A examination, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1240,2020,1650,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/comp-computer-science/300/comp-317','<div class="desc"> <p>We study algorithms from the point of view of efficiency and complexity. Having studied data structures, we now see how to apply algorithms to these structures to optimize their effectiveness. We examine algorithms in terms of time and memory allocation considerations. We will apply this background to a subset of the most important algorithms used in the sciences, various media, and business. We will study effective algorithm design, and give a brief introduction to computational complexity and computability, as well as parallel processing. Selected topics and applications from graph theory, linear algebra, numerical analysis, data compression, encryption, and large scale problems from Mathematics and the sciences.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 229 and either COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1241,2022,1651,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-337','<div class="desc"> There are hundreds of programming languages in use, many with unique features. This course is a survey of different programming languages and their similarities and differences. As part of this study, students will be additionally be introduced to topics such as type systems, parsing, and the theory of formal languages.<br/> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1242,2020,1652,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-260','<div class="desc"> <p>This class examines the politics of human rights and histories of stateÂ­-sponsored violence in contemporary Latin America. By focusing on the Americas as a specific geopolitical site for our discussions, we will gain a better understanding of the main cultural, political, and philosophical debates over universal human rights. The class will also examine how culture and art can serve as a form of resistance to legacies of oppression and violence in the Americas. We will refer to critical human rights and feminist theory in order to assist our understandings of the experiences of those affected by Latin American state violence and the formation of Latinx diasporic communities in the United States. Students taking this course will gain an understanding of the histories of the region, the relationship between universal human rights, nationalism, political violence, and contemporary gender issues. The class will also refer to the limits and possibilities of human rights in the pursuit of attaining justice for stateÂ­-sponsored crimes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1243,2020,1653,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-261','<div class="desc"> This course critically examines representations of gender, race, class, and sexuality in popular culture and mass media. We will discuss how race and gender are represented and produced in the media; how media production is raced, gendered, and sexed; and how to effectively analyze the relationship between identity, difference, and media. Students will critically assess theories of representation and cultural studies in our examination of race, gender, and other categories in media texts such as news and journalism, television, film, radio, internet, and social media. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1244,2022,1654,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-360','<div class="desc"> <p>This seminar introduces students to the theory and practice of research in feminist and sexuality studies. The course provides an introduction to the key terms and debates in feminist theory about how knowledge is produced and the relationship between knowledge and power in processes of knowledge production. We will give particular attention to the interdisciplinary focus of feminist research and its intersection with other methodologies such as queer theory, transnational feminisms, and critical race theory. Students will also consider how feminist research and social justice/community activism are related, and will assess the critical intersection of feminist theory and praxis.</p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1245,2022,1655,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-102','<div class="desc"> <p>A survey of the role of international organizations in global politics. The focus will be on an in-depth study of the three themes by which the United Nations has defined itself: security, human rights, and development. Within the rubric of those three themes we will look at activities by the U.N. family of agencies, other international organizations, and NGOs, on issues that include the management of violent conflict, human rights, and how these issues have been mainstreamed into the work of international organizations and approaches to economic underdevelopment that seek to alleviate both poverty and insecurity.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1246,2022,1656,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-239','<div class="desc"> <p>This course aims to introduce students to the history, politics, and economics of the European region from 1945 to present day. We will start by looking at the development of European states and political institutions in the post-WWII period, primarily those of Germany, France, the United Kingdom, and the Benelux countries. Our goal is to gain understanding of why European states have taken different political paths (including countries in Eastern Europe, the Nordic states, and Turkey), while also exploring the context of regional integration in which European states are embedded. The European Union (formerly the European Community) and its 28-member states are thus also central to this subject, as it encapsulates the development of key political institutions, civil society, representation, and economics on the continent. We will thus explore what has been accomplished by European integration (e.g., maintaining peace, increasing mobility, granting human rights, enhancing multilateralism, and strengthening democracy), as well as the considerable challenges that lie ahead (e.g., "Brexit", eastern enlargement, the stability of the Euro, the integration of refugees, and the rise of populist parties). In sum, the course is designed to introduce students to central topics in both past and contemporary Europe politics through the lens of political science and theories of regional integration. Situated at the intersection of comparative and international politics, these theories will help us to understand the complex interactions between national governments, supranational institutions, and the everyday lives of European citizens that define Europe today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1247,2022,1657,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/100/engl-178','<div class="desc"> <p>This class introduces you to some of Shakespeare’s most challenging and rewarding plays, with a focus on both their historical moment and film adaptations that have reanimated them across the second half of the 20th and 21st centuries. Our main topic will be Shakespeare’s evolving exploration of the predicament of tragedy in an era of major social, religious, and political transformation for Europe (England especially), and the ways that filmmakers have adapted Shakespearean tragedy for the big screen in different times and places. We will study Shakespeare''s explorations of dramatic form, poetic style, characterization, and ideology, and examine how the choices made in filming Shakespeare allow us to think in new ways about the plays themselves, and about the historical context in which the films were made. This course will introduce you to foundational concepts in literary studies and film studies, help you learn how to engage with Shakespeare''s plays more deeply, and enable you to analyze how film adaptations bring to life or transform the complex, unruly energies that characterize Shakespearean tragedy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1248,2022,1658,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-310','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-1778) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with such major figures as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as its unprecedented boom in popularity around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. In concluding with the rise of Nazism and their attacks on modern art as "degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. This course will meet three times a week, twice with CSLC 210, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1249,2022,1659,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-386','<div class="desc"> <p>In this course, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth''s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-Â­sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home," at all. This course will be offered in conjunction with CSLC 286, but will meet for an additional 90 minutes per week to read Homer''s <em>Odyssey </em>in the original Greek.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1250,2022,1660,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensable for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1251,2019,1661,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/HIST-History/Europe/HIST-335','<div class="desc"> <p>The dictatorships of Benito Mussolini and Adolf Hitler remain the among the most terrifying memories of the 20th century. This History course studies the rise, function, and fall of Mussolini''s Italy and Hitler''s Germany, between 1922 and 1945. In the period between World War I and World War II, new and alternative models for the relationship between state and society challenged the existing political and social order, as many Europeans abandoned democracy as the ideal political system. Many turned to nationalist authoritarianism as the answer to the political, economic, and social crises shaking Europe. Italy, under the National Fascist Party, and Germany, ruled by the National Socialists, were the nations in which this flight from democracy became a full-fledged descent into dictatorship and one­party rule. This course examines authoritarianism and dictatorship in interwar Europe and its characteristics in the two nations that experienced fascist rule. We assess how the elevation of the state and the nation, promoted by these regimes, impacted the societies involved. We study the political, social, economic, and cultural characteristics of Fascism and Nazism, and the ramifications - war and genocide - of the embrace of fascist dictatorship.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1252,2022,1662,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-340','<div class="desc"> <p>Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near-death experiences throughout the Mediterranean. While immensely entertaining and, at times ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in postÂ­classical literature, art, and film. Course meets with CSLC 140.</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1253,2022,1663,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America, from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds, and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1254,2022,1664,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-206','<div class="desc"> <p>Analysis of the English language development of listening speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public-school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction sheltered/SDAIE approaches English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1255,2022,1665,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-303','<div class="desc"> <p>The focus of this course is on the history, literature, and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works, as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works, while play attendance will keep our focus on these plays as performance. There is a ticket fee of $50 for the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1256,2020,1666,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/mac-media-arts-and-culture/100/mac-145','<div class="desc"> <p><em>Born Digital</em>, <em>Growing Up Digital</em>, <em>Teaching Digital Natives</em>, <em>Understanding the Digital Generation</em> ... these are just some of the titles in a veritable explosion of guidebooks on how thinking, learning, and doing have changed in a world transformed by digital, networked, and social media. In this 100-level gateway course, we take a critical look at the theories and prophesies on the "Net Gen"; we explore and assess new digital possibilities for communicating, teaching, and learning; and we think critically, contextually, and historically about the ways in which new media forms and practices shape identity, community, sociality, creativity, privacy, civic engagement, and everyday life. Class projects will enable students to experiment with, and gain, practical experience applying a range of media 2.0 technologies to their own academic work. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1257,2022,1667,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-210','<div class="desc"> <p>Motion graphics and motion design are becoming increasingly vital, creative, and technical capacities for digital media production. This two unit course focuses on the fundamental concepts, processes, and tools involved in motion design for the media arts: keyframe editing and interpolation, masking, effects, character rigging, camera movements, and titling. Students will become familiar with the interface of Adobe After Effects while exploring concepts of rhythm, space, and time, and will apply concepts and techniques to various assignments.</p> </div>','MAC 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1258,2022,1668,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-148','<div class="desc"> <p>This course explores tools and techniques for musicians developing their engineering and production skills through the use of the Digital Audio Workstation (DAW) Ableton Live. Students will expand their knowledge of MIDI, VSTs, sound design and mixing, audio recording, analog and digital synthesis, sampling, and beat making to enhance their working vocabulary of the fundamentals of production practice. Students will learn how to record and edit audio, manipulate MIDI data, and utilize digital effects processing through the fundamental science behind sound manipulation. Individual creative projects will work to further students’ critical engagement with recording techniques to establish a student''s facility with digital audio technology. Students intending to major in Music with a music production concentration must earn a B-minus or higher in this course to declare the Music major.</p> </div>','MUSC 151 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1259,2022,1670,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/100/pols-120','<div class="desc"> <p>Introduction to the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1260,2022,1671,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-320','<div class="desc"> <p>Critical examination of the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1261,2022,1672,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-355','<div class="desc"> <p>Franz Fanon, one of the most influential thinkers of the twentieth century, is a canonical figure in critical theory, broadly, and Black studies, postcolonial theory, political theory, critical race theory, continental philosophy and Africana philosophy, specifically. A francophone scholar, Fanon identified as black and was concerned with articulating the modern problem of white supremacy and the conditions for liberation for all people.</p> <p>This course is organized around a single book he wrote, <em>Black Skin, White Masks</em>. To understand what Fanon is up to in this text, we will also consider this book’s relationship to the philosophical traditions of psychoanalysis and phenomenology. To this end, we will read texts by Sigmund Freud, Anna Freud, Maurice Merleau-Ponty, Simone de Beauvoir, Jean-Paul Sartre, Jacques Lacan, and Georg Wilhelm Friedrich Hegel. Throughout the course we will switch between two distinct but related enterprises. On the one hand, we will try to understand how Fanon uses the specific set of psychic problems black people face and his articulation of the lived experience of the black in a white world to articulate his account of white supremacy and liberation. And on the other hand, we will seek to understand what his psychoanalytic and phenomenological counterparts are up to in their text to discern the significance of Fanon’s work in relation to the concerns within these philosophical traditions.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1262,2022,1673,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-160','<div class="desc"> <p>A large part of the success of Buddhism has been in its ability to travel and adapt to local cultural traditions, providing communities with a rubric for living a meaningful life. This course will provide an introduction to these traditions by looking specifically at Buddhist concepts and practices within human life and life cycles. We will ask: What do ritual and textual traditions about human life in various cultures tell us about Buddhist values and concepts of how to deal with suffering and thereby to life and die well? Are there differences between classical textual ideas about these topics and Buddhism as it is lived through ritual and community practice? How do both textual and ritual traditions maintain human life?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1263,2022,1674,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-276','<div class="desc"> Mainstream historical accounts of empire tend to focus on political and economic reasons for state expansion, leaving students with little insight into the experience of colonialism and imperialism "on the ground" for both the colonizers and the colonized. This course will offer methodological tools that encourage an understanding of everyday, non-elite voices into the study of empire in Asia and the Pacific by focusing on religious experience. Studying religion -- which was used as both a tool for colonial domination, as well as for resistance -- complicates ideas of empire as straightforward and as a mono-directional process. Case studies in this course will explore the interaction between empire and religion across a range of regions and historical moments. Students will then embark on their own research project related to a place and theme of their choice. In the end, the course will give students an insight into how Asian and Pacific societies variously responded to imperialism while also influencing the societies of the colonizer. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1264,2019,1675,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/RELS-Religious-Studies/200/RELS-282','<div class="desc"> This course will survey a variety of early Christian texts that define and regulate issues of sexuality, such as the function and purpose of sexual intercourse, same-gender intercourse, contraceptive practices, abortion, polygamy, monogamy, celibacy, and the normative "Christian family." We will analyze how opinions on such topics were as profoundly social, political, and economic as they were religio-ethical. From this analysis, we will better understand how modern (religious and secular) attitudes have been shaped by -- as well as diverge from -- the Christian sexual ethics of antiquity. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1265,2020,1676,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/rels-religious-studies/200/rels-296','<div class="desc"> Students in this course will examine the writings of 20thÂ­21st century Islamic political thinkers in the broader socioÂ­historical context in which their work was and is produced. The course will focus on different regions or countries where these ideas are being articulated -- for instance, Iran, Egypt, Pakistan, and India, or South East Asia. Beginning with a study of key concepts in Islamic theory and political philosophy, students will then analyze the complex and specific relationship between political religious and economic ideas and forces that inform the work of the authors we study. Special attention will be paid to the ways in which Western and modern ideas and practices, as well as Western imperialism or colonialism, are taken up in these thinkers. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1266,2022,1677,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-331','<div class="desc"> The worldview and beliefs of the early Slavs particularly the Eastern Slavs were a complex synthesis of influences: Indo-European mythology Central Asian shamanism Scythian animal worship and ultimately a paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600 in order to understand how these people viewed the world and how this affected their lives and the development of Slavic culture. Communal village life legends folk genres and mythology their sources and their legacies are examined. There is a close study of the phenomenon of the vampire following its evolution from the Iron Age into eighteenth century Serbia as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined as well. In addition to analytical and historical texts readings include tales of supernatural beings and phenomena as well as testimony concerning encounters with the supernatural." This section will deal with both texts in English and with texts in the original Russian. Texts include the "Tale of Warlord Dracula," "Olga''s Revenge on the Drevlians" and other early Russian stories. </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1267,2017,1678,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/AMST-American-Studies/200/AMST-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with what is known as the "LA Rebellion," a moment of a radical reconceptualization of filmmaking fostered by black students during their studies at the UCLA film school and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasion devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include Selma, Fruitvale Station, Daughters of the Dust, Lemonade, Pariah, Bush Mama, Do the Right Thing, and An Oversimplification of Her Beauty.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1268,2022,1679,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-260','<div class="desc"> <p></p><p>This course will explore how Latinos have creatively represented their individual and collective experience in the United States. Literature will be the primary creative medium we look at, but some supplemental attention may be given to film and music. To reflect the variety and complexity of the U.S. Latino experience we will look at representative work from the Chicano (Mexican American), Puerto Rican, Dominican, Cuban, and Salvadoran or Guatemalan communities.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1269,2022,1680,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1270,2020,1681,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/amst-american-studies/200/amst-296','<div class="desc"> <p>In this interdisciplinary course, we will interrogate the critical engagement of Black radical thinkers from the United States and Caribbean, with notions of collective liberation, with the peoples of Palestine, Algeria, and Iran, by close reading literary works, historical documents, films, music, and photographic representations. Starting with the discourse between Frantz Fanon and Ali Shariati, we will examine how the collaborations between this Black radical thinker and his counterpart in Iran led to the 1979 Islamic Revolution. We will also look to the relationship between the Black Panther Party and Palestine, as well as the liberation movements in Algeria, to better understand the philosophy, methodology, and consequences of internationalism, anti-colonialism, and the need for collective liberation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1271,2022,1682,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arab-arabic/100/arab-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on a Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1272,2022,1683,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/300/arts-301','<div class="desc"> <p>Audre Lorde famously wrote that the master’s tools will never dismantle the master’s house. What possibilities open up when we use language - a common currency of our everyday lives, too often the foundation that props up structures of confinement and limitation - on our own terms, in forms of our own invention and modes we imagine autonomously? How can we use writing to support and expand the work we do as artists? Is language a “master’s tool” or is it a tool we can use to “dismantle the master’s house”? In this class, we will explore creative forms such as artistic manifestos, statements of poetics/aesthetics, and reviews as invitations to better understand and articulate the parameters of our own art practice, and as powerful opportunities for collective enunciation. We will do close readings of primary texts from European, Latin American, and U.S. American avant-garde and art-activist movements, both historical and present-day. We will consider essays, reviews, manifestos, poems, blog posts, and tweets. Students will write individual and collaborative art statements as a way to clarify their own work, and think through larger issues in aesthetics and the social/political potential of art. Assignment exercises will encompass research and practice in collective and individual art writing, focusing both on student work and the work of other artists.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1273,2022,1684,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/100/cogs-111','<div class="desc"> <p>The average adult possesses over 50,000 concepts, ranging from physical concepts like "force" and "density," to biological concepts like "growth" and "reproduction," to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich, revise, and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive, developmental, and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1274,2022,1685,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-120','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus, begins Ovid''s <em>Metamorphoses, </em>whose programmatic opening stanza links the birth of the world, from formlessness and chaos, to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotica; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1275,2022,1686,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-134','<div class="desc"> <p>How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist one century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun," and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency, known otherwise as the Russian Avant-garde. Topics include: poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1276,2017,1687,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/CSLC-Comparative-Studies-in-Literature-and-Culture/100/CSLC-185','<div class="desc"> The course surveys the varied, historical dialogue between Islam and the West. The course traces the transformational influence Islam and the West have had on each other from the expansion of the Islamic Empire into Europe, to the eruption of Western modernity and European colonialism and imperialism, and through the reactions in Islamicate cultures to the pressures of Western economic, cultural, and political forces. The course will also examine the way Muslim migration to the West has affected not just Western culture and politics, but has also led to the transformation of Islamic ideas, practices, and identity by "Western" Muslims. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1277,2022,1688,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-283','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all-important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1278,2022,1689,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-395','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>Computational Science Fundamentals</strong></p> <p>This course covers tools and techniques to collect, prepare, analyze and visualize data in the process of research or investigative inquiry. Students will learn how to collect and organize data, and subsequently learn statistical techniques to prepare/clean it for analysis, such as imputation and dealing with outliers. In the process of data exploration, students will describe data, identify relationships between variables, and understand the structure of datasets. Visual representations of data will be used to discover patterns, and convey findings. The psychology underpinning understanding and reading visualizations will also be covered using a grammar of graphics approach.</p> <p>Prerequisites: COMP 131, COMP 181, or COMP 229</p> <p><strong>High Performance Computing</strong></p> <p>This course covers high-performance computing, which refers to techniques, hardware, and software used to further speed up processing beyond a typical CPU desktop configuration. Students will learn to write code optimized for multi-core processors, employing parallelization strategies for hardware using OpenMP and MPI. Students will learn how to access and use Oxy''s HPC cluster, as well as explore cloud platform solutions, tools, and programming languages used in both academic and industry environments.</p> <p>Prerequisites: COMP 229</p> <p><strong>Category Theory</strong></p> <p>Category theory is often regarded as the “mathematics of mathematics” and provides a natural context to discuss types of objects, their internal structure, and their relationships to other objects of the same or different contexts. Categorical descriptions naturally imbue systems with intrinsically algebraic structures, leading to a flexible descriptive framework for systems across many disciplines. Although the theory has its origins in pure mathematics (originally as the outgrowth of algebraic topology), applied scientists, engineers, and computer scientists have looked more and more towards category theory for modern approaches to solving and framing problems in technology and organization. This course will cover the basics of category theory, it''s applications to Boolean logic, to databases and to the Haskell programming language.</p> <p>Prerequisites: COMP 149 or MATH 210, and COMP 229</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1279,2022,1690,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-107','<div class="desc"> <p>This course will introduce students to major concepts, theories, and intellectual inquiries in the area of postcolonial studies. Students will engage with broad questions around knowledge production, representation, and subjectivities through the examination of topics such as: decolonization, migrations, transnationalism, diaspora, cultural productions, and practices of resistance. The course will look at relationships between postcolonial studies and critical race, feminist, and queer theories.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1280,2022,1691,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-211','<div class="desc"> <p>Critical pedagogy aims to develop collective critical consciousness for the purpose of transforming oppressive socio-political conditions. In this course, students will study critical pedagogy from historical, political, and sociological perspectives. Students in the course will consider traditional student/teacher relationships, pedagogical approaches, as well as hierarchies of knowledge promulgated by schools and textbook publishers. Students will analyze and critique theories of the Frankfurt School and the emancipatory works of Paolo Freire, the most renowned critical pedagogist. Additionally, contemporary readings from Henry Giroux, bell hooks, and Peter McLaren will focus on critical pedagogy in relation to social structures, globalization, media, and race.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1281,2022,1692,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-310','<div class="desc"> <p>This course is designed to introduce students to the methods and approaches used in qualitative interviewing. In addition to structured interviews, students learn about semi-structured biographical and narrative interviewing methods. The course also explores the ethical dilemmas and research challenges inherent during interviewing, as well as the details of conducting qualitative interviews. By the end of the semester, each student will have constructed, modified, conducted, analyzed, and written up an interview study.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1282,2022,1693,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-399','<div class="desc"> <p>Students in this advanced methods course will join the professor in conducting research in the specialty areas of the instructor. This course will fulfill a methods requirement and will necessitate that the student participate with the professor and other students in a collaborative manner to meet the goals of the research project. Research methods may include: critical discourse, oral histories, archival work, ethnography, and cultural studies, quantitative analysis, interview methods. Research projects may include topics such as: (1) youth and incarceration; (2) the discourse of "war"; (3) Europe''s discourse on migrant people; and (4) literacy, language, and children, to name a few. Open to juniors and seniors only. Permission of instructor required. May be repeated once for credit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1283,2022,1694,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-256','<div class="desc"> <p>This course analyses terrorism not only from a state security perspective, but also from one informed by political ethics, in which we seek to come to terms with the demands of justice in an age of violence resulting in large numbers of civilian deaths by both state and non-state actors. Broad questions include: what is terrorism? What are its causes? What are its consequences? Do terrorists operate from internally consistent and intelligible (even if horrific) frameworks? Must we sacrifice some of our cherished civil liberties in order to protect others? And what international, moral, and legal principles should guide us in an age of cyber warfare, drone strikes, and targeted assassinations?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1284,2020,1695,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-287','<div class="desc"> <p>In this interdisciplinary course, we will interrogate the critical engagement of black radical thinkers from the United States and Caribbean, with notions of collective liberation, with the peoples of Palestine, Algeria, and Iran, by close reading literary works, historical documents, films, music, and photographic representations. Starting with the discourse between Frantz Fanon and Ali Shariati, we will examine how the collaborations between this black radical thinker and his counterpart in Iran led to the 1979 Islamic Revolution. We will also look to the relationship between the Black Panther Party and Palestine, as well as the liberation movements in Algeria, to better understand the philosophy, methodology, and consequences of internationalism, anticolonialism, and the need for collective liberation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1285,2022,1696,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-288','<div class="desc"> <p>This course examines the major challenges of our environment and its relationship to politics and policy issues. We will cover topics addressing the normal functioning of the Earth, including the water cycle, carbon cycle, and the atmosphere. We will concentrate on the behavior of humans that affect these processes. We will tackle issues of state development, particularly industrialization and its consequences (including the increased use of fossil fuels, pollution of water, widespread deforestation, climate change, etc.), and their effects on the environment in which we live. We will discuss these problems and consider solutions at the international, national, local, and personal level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1286,2022,1697,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-332','<div class="desc"> <p>A digital exploration using mapping techniques to study the movement and political engagement of over 1.3 million Indians who were indentured from India to various British colonies between 1833 and 1920. They currently constitute either large majorities or strong minorities in these former colonies. Some of the countries that will be studied include Fiji, Trinidad, Mauritius, and South Africa.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1287,2022,1698,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/100/engl-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1288,2022,1699,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-273','<div class="desc"> <p>American poetry has resurged in cultural and political significance in the 21st century. Poets have reframed the nation''s controversies and recovered its forgotten histories. Notably, poets have shifted American consciousness without losing sight of artistic experimentation. Poetic genres, in this course, are more than familiar literary conventions. They are ways of thinking and feeling. Poets experiment with literary form in hopes of staying true to the nation''s complexities. Fragmentation, intertextuality, ekphrasis, and erasure are all crucial techniques for exploring beauty, mental health and disability, immigration and war. This course will examine several award-winning poets, including Kevin Young, Molly McCully Brown, Robin Coste Lewis, Solmaz Sharif, and Philip Metres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1289,2022,1700,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-274','<div class="desc"> <p>This course will focus on the intersections among race, gender, sexuality and culture in 19<sup>th</sup>, 20<sup>th</sup> and 21<sup>st</sup> century novels within three different cultural traditions: African American, Anglo American, and Native American. African American women writers include Harriet Jacobs, Nella Larsen, Zora Neale Hurston, and Toni Morrison. Native American women writers include Louise Erdrich and Leslie Marmon Silko. Anglo American women writers include George Eliot, Kate Chopin, and Virginia Woolf.</p> <p><strong><span>Major Requirement Met: </span></strong><span>Group III/IV</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1290,2022,1701,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-383','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all-important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all. The Greek section of this course will be devoted to translation of <em>The Iliad</em> from the original, paying particular attention to the ways in which the Homeric epic has been received in the almost three millennia since its original appearanceÍ¾ this will give our investigation into the history of style in the West (and its possible metaphysical grounds) a carefully delimited focal point.</p> </div>','Greek 102; or permission of instructor (proficiency in Ancient Greek) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1291,2020,1702,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-216','<div class="desc"> <p>This course begins in the Colonial period and focuses on the unprecedented growth of the American Jewish community throughout the modern era. Historically, Jews have sought refuge and greater prospects in the United States from Spanish, Portuguese, Germanic, and Dutch lands, as well as from Eastern Europe, North Africa, and the Middle East. By using a diverse framework of analysis, we will cover topics such as: the early settlers, Jews and the American Revolution, the German migration, the influx of Jews from Poland and Russia, New York City and the rise of the Jewish Lower East Side, the Jewish labor movement and politicization, Yiddish culture, suburbanization, the plight of Soviet Jews, the growth of insular ultra-religious communities, and disenchantment and hipster Jewish life today. Readings will consist of primary and secondary material.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1292,2022,1703,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-344','<div class="desc"> <p>One of the fastest growing economies in the world and most rapidly urbanizing society, China has risen to a central role in the world today. Yet, this rise has been fraught with problems and tensions that threaten its continued development. This course looks at the social, political, cultural, environmental, and economic development of contemporary China (from the 1970''s to the present), and asks us: how do we know contemporary China? This is a hands-on research course in which students will learn how to find, evaluate, and use sources to understand present-day China from an interdisciplinary perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1293,2022,1704,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/kine-kinesiology/200/kine-210','<div class="desc"> Introduction to the science of nutrition. Students will learn how macronutrients and micronutrients are assimilated into the human body from both dietary and supplement sources. A significant portion of the course will focus on understanding the science behind the USDA dietary guidelines and how to prepare meals for optimal health depending on age, sex, and physical activity levels. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1294,2022,1705,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-320','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis -- the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. LATN 320 is the five-unit course attached to CSLC 120. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1295,2022,1706,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-250','<div class="desc"> <p>This highly interactive seminar brings students from different identity groups together for informed, sustained, and respectful dialogue about “hot topics” in the lives of Latinxs in the U.S. There are three components to the course. Part 1 focuses on Dialogic Skill Building; Part 2 focuses on Power, Privilege, and Group Membership; and Part 3 focuses on specific Hot Issues (see below for specific topics). Course goals include a deeper intellectual and personal understanding of the structural implications of Latinx/Latin American identity in the U.S., honed ability to communicate across difference, and development of intergroup alliances. Seminars are co-facilitated by a faculty member and trained peers representing intersectional identities within Latinx culture. A semi-structured curriculum integrates readings, experiential activities, dialogue, and reflective writing. Next year’s topics include: Identity -- Who is Latinx? (phenotype, class, language, authenticity); (in)visibility and Representational Challenges (Beyond the Black-White binary, Media, ); Politics of Intersectionality and Simultaneity Across Contexts and Generations (Assimilation, Enculturation, Gender, Sexuality, and Religion); Educational Options for Self or Community (Curricular marginalization, Counterspaces or Balkinization); Political Resistance and Coalition Possibilities (Ideological tensions, Rebellious Lawyering, Work). Student demand will determine whether an Intragroup (all Latinx) Dialogue or an Intergroup (mixed race) Dialogue option will be offered.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1296,2022,1707,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-242','<div class="desc"> <p>In our dynamic digital moment, the question, "What is a documentary?" can be answered with ever-increasing complexity. Works professing truth claims about our historical and present "realities" are just as much constructs as any fiction film, a realization that presents both creative opportunities and ethical responsibilities for documentary practitioners. This hands-on course will explore and develop a poetics of documentary, underscoring that the politics and meaning of documentary works come not simply through their content but through their aesthetic strategies and processes of production and distribution. A series of media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1297,2022,1708,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-246','<div class="desc"> <p class="MsoNormal" style="margin-left:0cm; margin-right:0cm">Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p class="MsoNormal" style="margin-left:0cm; margin-right:0cm"><strong>New Waves of East Asian Cinema</strong></p> <p class="MsoNormal" style="margin-left:0cm; margin-right:0cm">The history of cinema is marked by New Waves reflecting both artistic and cultural movements and shifts in cinematic practice. This survey course focuses on the New Waves of East Asian Cinema, engaging their sociocultural history alongside aesthetic and technological developments. Topics include: Japan’s <em>NÅ«beru bÄgu</em>in the 1950s, which borrowed its name from the inaugural movement of the French <em>Nouvelle Vague</em><em>;</em> the waves in Hong Kong cinema, which were thematically linked to the impending expiration date of the 1997 handover to China; and the developments in Taiwanese art and film that were spurred by the ending of martial law in 1982. We will examine the historical events of resistance underlying these cinematic movements and their long-lasting impacts on society and culture. Students will engage with the material critically through projects and presentations alongside weekly screenings, readings, and discussions. Additional Requirement Met: Regional Focus.</p> <p class="MsoNormal" style="margin-left:0cm; margin-right:0cm"><strong>Modernity and the Rise of Cinematic Visuality</strong></p> <p>Many have argued that the history of modernity has been, above all, a history of visualization, changing the way we see. In this course, we will examine a diverse range of nineteenth and early twentieth century visual practices, technologies, and experiences including train rides, panoramas, shopping arcades, assembly lines, and amusement parks that helped shape the "modern observer" by altering both the perception and understanding of time and space, public and private, work and leisure, the normal and deviant, and the individual and collective. Through a combination of critical readings, screenings, and field trips, we will ask how such practices of looking not only influenced early cinematic form and content, but also how they continue to inflect postmodern media culture, from television to the internet. The course culminates in a 3D screening of HUGO (2011, Scorsese).</p> <p><strong>The Philosophy of Classical Hollywood Cinema</strong></p> <p>This course will attempt a survey of current philosophical approaches to classical Hollywood film, beginning with Stanley Cavell’s The World Viewed: Reflections on the Ontology of Cinema (1971). This work initiated a new and flourishing sub-discipline within contemporary academic philosophy called film-philosophy. The central assumption within this body of inquiry is that film is (or can be) “philosophy in action.” In this course we will be returning to the source of this idea to read Cavell’s original work, as well as selections from his two subsequent books: Pursuits of Happiness: the Hollywood Comedy of Remarriage (1981) and Contesting Tears: The Hollywood Melodrama of the Unknown Woman (1996). We will then extend our inquiry to other writers inspired by Cavell (and reflections on later developments within Hollywood), such as Robert Pippin (writing on Film Noir), Stephen Mulhall (writing on the Alien series and other sci-fi), and William Rothman (writing on Hitchcock). Weekly screenings and discussions will be part of the course, as well as one or two field trips to Los Angeles archives.Cross-listed as PHIL 317.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1298,2022,1709,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with what is known as the "LA Rebellion," a moment of a radical reconceptualization of filmmaking, fostered by black students during their studies at the UCLA film school, and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasion devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include <em>Selma, Fruitvale Station, Daughters of the Dust, Lemonade, Pariah, Bush Mama, Do the Right Thing, and An Oversimplification of Her Beauty.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1299,2022,1710,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-320','<div class="desc"> This course emphasizes the advanced design and writing of long-form narratives for various audiovisual time-based media forms. Through a combination of screenings, critical readings, and creative exercises, students will develop a treatment for a long-form narrative screen work and commence writing scenes for its first act. </div>','MAC 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1300,2022,1711,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-355','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors in the Media Production Concentration. It provides advanced study and hands-on experience in the ideation and production of digital media projects across a range of fictional, documentary, and experimental modes. Students engage in a combination of readings, screenings, technical workshops, and collaborative media production projects to prepare them for the Media Production Senior Comprehensives experience. This class is only open to junior MAC majors in the Media Production Concentration.<br/> </p> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1301,2022,1712,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-390','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors. Fulfilling the College’s Second-Stage Writing Requirement, this is a research-driven course which brings together all junior majors, regardless of the intended form of their senior comprehensives project, to read, watch, write, debate, and produce self-directed research, laying the groundwork for their senior year comprehensives projects. This class is only open to junior MAC majors. </p> </div>','Two gateway classes (from MAC 143, MAC 145, MAC 146) must be completed with grades of C+ or better ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1302,2022,1713,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-492','<div class="desc"> <p>This course provides technical training to Media Production comprehensives seniors on a range of post-production software platforms, best practices in sound and picture editing, and skills in post-production finishing/project delivery workflow. Course assignments and deadlines scaffold the completion of Media Production senior comprehensives projects. The course also provides professionalization tools, training students in development and production of media portfolio materials. This class is only open to senior MAC majors in the Media Production Concentration.</p> </div>','MAC 491 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1303,2017,1714,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/MAC-Media-Arts-and-Culture/900/MAC-999','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1304,2022,1715,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-113','<div class="desc"> <p>Composing, improvising, listening, and performing all embody aspects of music-making. This course examines compositional methods of contemporary composers. We will focus on hands-on composing in a broad range of styles. Additionally, students will learn about all of the instruments of the orchestra (range, characteristics, timbre, etc.). In-class listening will supplement bi-weekly listening assignments covering orchestral music from the Baroque to the present. Students will learn to develop musical ideas through notational methods that can effectively be realized by performers. Basic music theory will be taught in class in order to learn about transposing instruments, notation methods, and how to read music in different clefs, such as alto and tenor clefs. </p> </div>','MUSC 101 or the equivalent, or permission of instructor. First-year and transfer students must take the Music Theory Placement test (administered during Orientation) to determine eligibility for the course. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1305,2022,1716,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-283','<div class="desc"> In this course we will examine the diverse musical cultures (historical and contemporary) of Los Angeles, paying particular attention to the ways music negotiates intercultural encounters. As we survey the musical cultures of Native American, European, Asian, African, and Middle Eastern descendants in the Los Angeles area, we will think about how musical styles, repertoires, instrumentation, and texts are transformed by urban dwellers as they respond to the changing political, economic, and social landscapes of the city. Students will undertake both individual research projects on the Los Angeles-area musical culture of their choice and a digital group project on the local Spanish-language ska scene. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1306,2022,1717,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-351','<div class="desc"> <p>Together with its co-requisite applied musicianship component, this modular course will explore extensions of chromatic harmonic practice, larger formal models, survey compositional and analytic techniques developed in the 20th and 21st Centuries, and examine music which extends beyond the 12-note equal-tempered scale. The instructor chooses the music studied and additional topics in collaboration with students and Music Department colleagues.</p> </div>','MUSC 251 or permission of instructor. ','MUSC 351A ',NULL);
INSERT INTO course_descriptions VALUES(1307,2022,1718,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-215','<div class="desc"> <p>A detailed examination of some central philosophical texts from history of Western philosophy. Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p><strong>Medieval and Early Modern Philosophical Theology</strong></p> <p>In pursuit of wisdom, most philosophers throughout history thoughtfully engaged in a project of philosophical theology. Differing from religion, theology – the study (<em>logos</em>) of god (<em>theos</em>) – critically examines the existence, features, powers, and effects of deities. Some of the most sophisticated approaches to these issues were proposed by medieval and early modern philosophers living between about 1000 and 1800 CE. In this class, we''ll try to understand the theological views of a variety of philosophers of this period. Topics will include arguments for the existence of a god in the Latin and Arabic traditions, philosophical mysticism in medieval women philosophers, and the metaphysics and logic of the sacrament of the eucharist. <em>Core Requirements Met: Pre-1800 and Global Connections.</em></p> <p><strong>The Myth of Dualism</strong></p> <p>There are bodies and minds, and the two are fundamentally distinct. Bodies are spatial, publicly observable, and subject to mechanical laws. Minds are spectral, private, and, when things go right, observant of the rules of good reasoning and purposeful action. People are unions of the two— ghost-piloted machines whose constituents, once separated by bodily death, have very different fates: the abandoned vessel decays, while the captain somehow survives. Or so says the myth of dualism, attributed to the 17th-century French philosopher René Descartes by the 20th-century British philosopher Gilbert Ryle, who argues extensively against the "official doctrine" of Cartesian Dualism. But Descartes, ingenious as he was, didn''t think in a vacuum. He absorbed and perpetuated an intellectual tradition stretching from Classical Greece, to the Golden Age of Islam, to the European Middle Ages, and into Modernity—crude labels for internally diverse and complexly interrelated periods of philosophical history. In the first part of this course, we''ll try to locate and trace the myth throughout this roughly two-thousand-year stretch. Our approach will be chronological, and we''ll study the views of numerous philosophers, including Plato, Aristotle, Al-FÄrÄbÄ«, Ibn SÄ«nÄ, Thomas Aquinas, Teresa of Ávila, Descartes, Pierre Gassendi, Elisabeth of Bohemia, Baruch Spinoza, and Anton Wilhelm Amo. In the second part of the course, we''ll consider several approaches to rejecting the paradigm. Forsaking chronology, we''ll first attend to Ryle''s alternative to dualism—logical behaviorism—before reflecting on an assortment of challenges, raised by Ludwig Wittgenstein, W.E.B. Du Bois, Michel de Montaigne, and NÄgÄrjuna, to the very idea of an identifiable, unified, or non-illusory self. <em>Core Requirements Met: Pre-1800 and Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1308,2019,1719,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-335','<div class="desc"> If aspiring to make money and to win a game is constitutive of running a business and playing a sport, respectively, what is the place for ethics in each of these endeavors? In this comparative course we will explore some of the most influential theories that have been offered to respond to this question, theories that range from those that deny any place for morality in business or sports to those that insist that morality is at their heart. The many parallels between business and sports will allow us to use understand better what a business and a sport is, and to use the insights we gain by reflecting on one of these activities to think critically and creatively about the other.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1309,2022,1720,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/100/phac-147','<div class="desc"> Participate in weekly Club Sports Men''s Ultimate Frisbee practices and competitive intercollegiate club opportunities.Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1310,2022,1721,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-208','<div class="desc"> Participation in women''s intercollegiate water polo. </div>','Permission of head women''s water polo coach ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1311,2022,1722,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-211','<div class="desc"> Participation in Intercollegiate Baseball.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1312,2022,1723,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-212','<div class="desc"> Participation in Intercollegiate Basketball (Women).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1313,2022,1724,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-213','<div class="desc"> <p>Participation in Intercollegiate Basketball (Men).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1314,2022,1725,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-214','<div class="desc"> Participation in Intercollegiate Golf (Women).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1315,2022,1726,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-215','<div class="desc"> Participation in Intercollegiate Golf (Men).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1316,2022,1727,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-216','<div class="desc"> Participation in Intercollegiate Lacrosse (Women).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1317,2022,1728,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-217','<div class="desc"> Participation in Intercollegiate Swimming and Diving (Men). </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1318,2022,1729,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-218','<div class="desc"> Participation in Intercollegiate Softball.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1319,2022,1730,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-219','<div class="desc"> Participation in Intercollegiate Tennis (Men).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1320,2022,1731,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-220','<div class="desc"> <p>Intercollegiate Swimming and Diving (Women).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1321,2022,1732,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-221','<div class="desc"> Participation in Intercollegiate Track and Field (Men).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1322,2022,1733,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-222','<div class="desc"> Participation in Intercollegiate Tennis (Women).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1323,2022,1734,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phac-physical-activities/200/phac-224','<div class="desc"> Participation in Intercollegiate Track and Field (Women).<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1324,2022,1735,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-346','<div class="desc"> <p>An advanced course in constitutional law and theory with a specific focus on civil rights and civil liberties. Course topics may include, civil rights under the Fourteenth Amendment, and civil liberties including privacy, marriage, speech, reproductive autonomy, voting or freedom of expression. The goal of the course is to critically engage students in understanding how the Supreme Court has deemed certain rights and liberties as fundamental to society. The course approaches Supreme Court decisions as reflective of a larger social narrative of rights and justice.Throughout the course students will consider the role of the law in creating political boundaries within society.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1325,2022,1736,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-311','<div class="desc"> This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance and level of participation of an individual or group. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1326,2022,1737,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-155','<div class="desc"> The course surveys the varied, historical dialogue between Islam and the West. The course traces the transformational influence Islam and the West have had on each other from the expansion of the Islamic Empire into Europe, to the eruption of Western modernity and European colonialism and imperialism, and through the reactions in Islamicate cultures to the pressures of Western economic, cultural, and political forces. The course will also examine the way Muslim migration to the West has affected not just Western culture and politics, but has also led to the transformation of Islamic ideas, practices, and identity by "Western" Muslims. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1327,2022,1738,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-206','<div class="desc"> This course will survey the cultural history of Jerusalem over three millennia, primarily as the symbolic focus of three faiths: Judaism, Christianity, and Islam. Students will examine the transformation of sacred space as reflected by literary and archaeological evidence (studying artifacts, architectural monuments, and iconography in relation to written sources). Students will also examine the creation of mythic Jerusalem through event and experience. By the end of the course, students will better understand the historical roots of modern political and religious conflict in Jerusalem and Israel<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1328,2017,1739,'http://smartcatalog.co/en/Catalogs/Occidental-College/2016-2017/Catalog/Courses/RELS-Religious-Studies/200/RELS-216','<div class="desc"> Catholicism was a cornerstone ideology behind the colonization of the Americas. Its tenets and teachings have structured all aspects of Latin American society, including gender relations. This course will explore the gendered aspects of religious experience throughout Latin American history. It will begin with the Conquest of the Americas and lead up to the present day. In the colonial period, we will explore topics such as nuns, the Inquisition, sexuality and religion, and witchcraft. Students will be asked to consider how varying religious identities--nuns, sodomites, witches--could simultaneously oppress and carve out space for men and women across colonial Latin America. In modern Latin America, we will look at the role religion and gender played in the consolidation of post-colonial states, sexuality and reproduction, and the gendered rise of evangelicalism in the twentieth and twenty-first centuries. We will pay close attention to how religious authorities used gender ideologies to reshape their societal roles in the modern period. The course readings will include both primary, historical materials, as well as and secondary scholarship. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1329,2022,1740,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-334','<div class="desc"> How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist a century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun" and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency known otherwise as the Russian Avant-garde. Topics include poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi. </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1330,2022,1741,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-290','<div class="desc"> This course is an introduction to sociological analyses of the economy, economic processes, and economic institutions. The central focus is to understand how beliefs, norms, cultures, social relations, and institutions shape our economic lives. We will also explore how the theoretical and methodological approaches of sociology differ from those orienting the discipline of economics, as well as what is at stake in these differences. By the end of the course, you will be familiar with the key approaches in economic sociology, and will be able to use a sociological lens to examine the economy. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1331,2022,1742,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-143','<div class="desc"> <p>Students explore the rich traditions of Latin Dance from its origins in the African diaspora found in Cuba, Caribbean and Latin American nations as well as the influence and effect of these dances throughout popular Western culture. Students embrace through performance various dance forms developed in Mexico and throughout Central and Latin America and study the place and importance of the dances in Latin cultures.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1332,2022,1743,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-230','<div class="desc"> This course will cover the problem of climate change and the history and evolution of the climate justice movement. It will examine the organizing and policy tools used by advocates to advance climate justice. The course will begin with an exploration of climate change, the environmental and political factors that cause the climate to change, and why the issue matters to communities across the globe. The course will then look at the history and foundational concepts of climate justice with particular focus on how issues of race and class impact climate justice. Finally, the course will look at how the traditional environmental movement, the labor movement, and global movements advocate for climate justice and what priorities they advance. Key topics to be covered are: the intersection between race and the environment, the relationship between traditional environmental movements and the environmental justice movements, labor movements and the green economy, global solidarity movements. </div>','UEP 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1333,2022,2321,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-272','<div class="desc"> <p>An investigation of the art and architecture of ancient Greece and Rome from the Helladic era (c. 1500 BCE) to the appearance of Christianity in late Roman antiquity. Sculpture, metalwork, mural painting, vase painting, and architecture will be considered, with particular interest in how these forms are reflective of the fundamental political, spiritual, and philosophical developments during this era - as well as how these artistic forms serve as the foundational elements for European Art History.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1334,2022,2322,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-372','<div class="desc"> <p>This course examines the development of Venetian painting in the 15th and 16th centuries. Among the artists considered will be Carpaccio, Giovanni Bellini, Titian, Tintoretto, and Paolo Veronese. This course will focus on the unique geographic and historical context of Venice, "the most serene republic" (La Serenissima), and its (WHAT IS "IT") extraordinary influence on the history of European painting.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1335,2022,2323,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-373','<div class="desc"> <p>This course is an opportunity for students to learn more advanced methodologies in computational biology. By examining a variety of biological questions that are often addressed with computational pipelines, modeling, or simulation, students will get in-depth experience with important computational concepts (including: abstraction, algorithms, automation, logic, and problem solving). This includes the study of complex biological systems, such as projecting biological responses to climate or ecosystem change, quantifying spatial biodiversity hotspots, evaluating time series data for populations, and computing evolutionary parameters from genomic datasets. Students will also get experience with computer programming in the R statistical language and Python. Additional biological topics may include: spatial ecology, including species distribution modeling, community assemblage and dissimilarity matrices, population simulations, classification with machine learning, and bioinformatics with genomic data. Course includes laboratory workshops sessions.<strong></strong></p> </div>','BIO 268, COMP 131, MATH 150, COGS 255, GEO 255, PSYC 201, or permission of instructor ','BIO 373L ',NULL);
INSERT INTO course_descriptions VALUES(1336,2019,2324,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/BIO-Biology/300/BIO-373A','<div class="desc"> <p>Laboratory workshops for Computational Biology (BIO 373). Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 373',NULL);
INSERT INTO course_descriptions VALUES(1337,2022,2325,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-220','<div class="desc"> <p>Are earthworms capable of making decisions? How do ants navigate their environment? Do dogs have an understanding of fairness? Questions about the mental states and processes possessed by non-human animals present particular problems of study: how do we determine whether, and to what extent, animals possess such abilities? This course will study the evidence for cognitive states and processes in non-human animals, focusing on careful and critical attention to the methods and techniques used to gather that evidence and on the considerations that go into interpreting that evidence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1338,2022,2327,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-232','<div class="desc"> <p>This course focuses on Mikhail Bakhtin''s theory of language and the novel. Bakhtin''s writings are a synthesis of diverse theoretical approaches, including NeoÂ­Kantian philosophy, structuralist linguistics, the theory of novelistic discourse as a polyphonic medium, and the notion of carnival as a subversive cultural force. Furthermore, Bakhtin''s approach to the text reveals prose fiction, and, to some degree, nonÂ­fiction, as a unique medium through which language explores human consciousness in both time and space. In this course, Bakhtin''s theories are studied in order to understand more deeply the significance of the novel, and novels are studied in order to better understand Bakhtin''s theories. Works as diverse as Fyodor Dostoevsky''s <em>Crime and Punishment</em>, Venedikt Yerofeev''s <em>Moscow to the End of the Line</em>, Umberto Eco''s <em>Foucault’s Pendulum</em>, and Manuel Puig''s <em>Kiss of the Spider Woman</em>, are examined through the Bakhtinian lens in order to broaden the students'' understanding of the text as a polyphonic phenomenon. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1340,2022,2329,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-367','<div class="desc"> <p>The largest programming projects are completed by multiple computer scientists working together. Clients across Eagle Rock and the Oxy community will propose problems with computational solutions, which we will complete in teams as a semester long-project. Using standard tools, such as version control, we will apply the principles of user-centered design to software: understanding the needs of the client, developing software, and testing the product with the user, before repeating the cycle. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 127 or COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1341,2022,2330,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-160','<div class="desc"> <p>This course introduces students to contemporary feminist thought and histories of feminist activism. Students will learn about the intersectionality of race, gender, class, sexuality, and nation in a variety of feminist scholarship, and will examine key issues in feminist theory, such as: the debates between Western feminism and women of color feminism, transnational feminism, queer theory, the social construction of sex and gender, reproductive justice, gender-based violence, and the political economy of gender. This course will center on the strong link between feminist theory, social justice, and activism, and will explore how these can be mutually informing projects that can effect social change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1342,2022,2331,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-250','<div class="desc"> <p>This course will examine the relationship between resistance movements and the law through several historical and contemporary United States and Latin American case studies. We will begin the semester by exploring theoretical representations of resistance movements within critical legal theory and social movement theory. We will look at different conceptualizations of power and consciousness in our analysis of resistance, and the role of each in instigating resistance movements. We will then turn to an analysis of the law as a tool of collective struggle by studying and comparing the implicated rights and site-specific needs, objectives, strategies, and outcomes of each case study. We will look at the different ways these resistance movements may use the law to mobilize followers, to frame and address collective grievance, to advance and develop legal protections for marginalized groups, and to connect their localized struggles with global ones by redefining and reimagining concepts of dignity and freedom. Each case study will also provide us with an opportunity to explore the relationship between the law, state-sponsored violence, and repression of resistance movements. We will also examine the role and influence of legal advocacy organizations in contemporary resistance movements, and evaluate the current limitations of the law in contributing to social change. How do rights-based claims (e.g. indigenous rights, water rights) obscure the relationship between law and power, injustice, and structures of oppression? Can the law be a useful catalyst for change, and/or is it necessarily a supplement to grassroots organizing and mobilizing efforts? To examine these concepts and tensions, we will look at legislation and legal practices, landmark court cases, and critical scholarship related to our case studies. Among the resistance movements we will likely study are: Brazil''s Landless Rural Workers Movement; indigenous resistance movements in North and South America, including resistance to the Dakota Access Pipeline and the Agua Zarca Hydroelectric Dam in Honduras; and different phases in the movement for black civil rights in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1343,2022,2332,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-361','<div class="desc"> <p>This course centers on representations of gender, race, class, nationality, and sexuality in Latinx and Latin American film. We will examine the economic, racial, and gendered inequalities that stem from histories of colonization and neocolonialism in Latin America and in the diasporic Latinx communities that have formed in the United States. Using a transnational lens, students will assess the limits and possibilities of film in documenting histories of oppression and social inequalities facing Latin Americans and Latinx communities in the U.S. We will turn to feminist film theory, critical film theory, cultural studies, and Latin American history and politics in order to facilitate our analysis and class discussions of these films.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1344,2022,2333,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected what was historically the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean that has developed into proper noun: the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological, and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the 20th century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-1939 Palestinian Revolt, the 1948 war for Palestine and its aftermath, Israeli-Arab relations in the 1950''s, the Suez War, the implications of gendering the nation, the 1967 war and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1345,2022,2334,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-226','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal," "populist," and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems, including the United States; and the challenges democracies are facing in integrating formerly marginalized populations, including women, poor, and the indigenous. It will examine the United States policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1346,2022,2335,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-228','<div class="desc"> <p>This course explores efforts to conceptualize democracy, and to generate and test theories of democratization and the endurance of democracy. After considering the concept of democracy, we start by considering some of the classics, published in the second half of the 20th century. These are key works that have shaped the field and have largely set the terms of the debate. Then, we turn to the literature published after 2000 and consider how this literature has revised and built on ideas from the classics. We conclude with an overall assessment of knowledge about democratization and the endurance of democracy. In all, we will discuss explanations that put an emphasis on the economy and culture, as well as on politics itself. Much of what we will read reflects the focus of this literature on Europe, Latin America, and post-Soviet Eurasia. However, some African and Asian cases will be discussed and several global analyses will be considered. Emphasis will be put on the core theoretical and methodological aspects of this literature.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1347,2020,2336,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/engl-english/100/engl-159','<div class="desc"> <p>A study of the popular American "Western" in various forms (fiction, film, television) in the first half of the 20th century. We will pay particular attention to the genre''s elaborate, sometimes ambivalent, presentation of ideas of "manliness," and to the historical and social contexts in which that presentation developed. We will also spend some time discussing associated issues of race and power. Toward the end of the class, we will examine a few of the Western''s transformations in the late 20th and 21st centuries.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1348,2022,2337,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-248','<div class="desc"> <p>This course will focus on novels by major British nineteenth-century authors, with particular attention to the production of gender roles and the influence of economic forces on character and language. Read in relation to the historical context of rapid change from a land-based to a money-based economic system in the United Kingdom, the novels reveal how the introduction of capitalist practices affected men and women differently. The novels dramatize the ways that capitalism influences the feelings and thought processes of individuals. The class will also pay close attention to the novels’ style and wording, with an eye to seeing how language itself is infiltrated by market practices and values.</p> <p><strong><span>Major Requirement Met: </span></strong><span>Group II</span></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1349,2022,2338,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-353','<div class="desc"> <p>Since the 2008 Crash, politicians, scholars, and journalists have compared America''s current economic challenges to the Great Depression. This frequent comparison does not exhaust the significance of the Great Depression for the U.S. or the rest of the world. The 1930s is such an intriguing decade because the global economic collapse spawned new, or renewed older, political and artistic movements. In the global 1930''s, people considered art central to rethinking political allegiances and the overarching meaning of politics itself. The 1930s helps to clarify the following question in our present-day: what cultural rebuilding remains to be done and how does art contribute to such processes? Writers of the 1930''s took up this question in several different forms: through the trope of the document and its archival drive, the unconscious and the search for the Marvelous, the raised fist of labor movements or anti­racist activism. This course will look at several literary (and related art) movements in, and cutting across, America, the Caribbean, and Europe. Texts will include (but are not limited to) documentary writing from Muriel Rukeyser, Richard Wright, and Langston Hughes; Surrealist writing from Europe and the Caribbean, including Aime Cesaire and Georges Bataille; and other forms of art like the photography of Cathy Cahun.</p> <p><strong>Major Requirement Met</strong>: Group III</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1350,2022,2340,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected, what was historically, the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean, which has become known as the proper noun, the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the twentieth Century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-39 Palestinian Revolt, the 1948 War for Palestine and its aftermath, Israeli-Arab relations in the 1950s, the Suez War, the implications of gendering the nation, the 1967 War and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1351,2022,2341,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-205','<div class="desc"> <p>According to Thomas Jefferson, America was to be an "agrarian Republic" - a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones, as well. Indeed, for many early migrants, America was itself a "city on the hill" - an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing, in the second half, specifically on Los Angeles, where new forms of decentralized urbanism took form in the 20th century. We will not only explore suburbia and freeways, Disneyland, and other quasiÂ­urban outposts, but also the changing character of the inner city in the mid-20th century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today - multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism - the changing character of public space, the turn to privatism, the neglect of public transport infrastructures, and challenges to democracy and equality - are ultimately compatible with the American dream of the "city on the hill" for the 21st century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1352,2022,2342,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-346','<div class="desc"> <p>China is now undergoing one of the fastest rates of urbanization in world history. Just thirty years ago, about 80% of the Chinese population lived in the countryside, mostly working in agriculture. Today, China''s population is over half urban, and the CCP has announced a new plan to speed up the urbanization process so that by 2020, 60% will be urban. Furthermore, well over 100 million migrants travel back and forth between the countryside and the city each year. While these numbers are impressive in and of themselves, it can be hard to understand what they mean for individuals, for particular social groups, and for the changing rural and urban landscapes. Nonetheless, this shift from a predominantly rural population to an urban focused society is both ambitious and fraught with problems. This class aims to give an in-depth and upÂ­-close look at this amazing social transformation through readings, class lectures, film, research projects, and, most importantly, in-country experience. This course begins with a short semester on campus at Occidental and continues with a threeÂ­-week trip to China, including a homeÂ­stay with a rural household. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1353,2022,2343,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-151','<div class="desc"> <p>This course offers a survey of postcolonial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the nineteenth and twentieth centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the nineteenth century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race and the development of export agriculture. The second section introduces themes of the twentieth century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources including scholarly works, films, and primary sources to engage these topics and issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1354,2022,2344,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States, and to assess how these communities seek political empowerment, as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life, such as the economy, the state, and the cultural system, on the one hand, and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications, based on race, class, gender, national origin, and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1355,2022,2345,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) presidents either failed to act in accordance with the transitional justice movements sweeping Latin America or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased, rather than decreased, since its transition to democracy. This class will document why this is the case, as well as look into the various movements that have mobilized since the 1970''s to the present to demand human rights in Mexico.</p> </div>','DWA 101, POLS 101, or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1356,2022,2346,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1357,2022,2347,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-385','<div class="desc"> <p style="margin-left:0in; margin-right:0in">The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101, SOC 101, HIST 102, AMST 101, or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1358,2022,2348,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-260','<div class="desc"> <p>This intermediate topical course addresses new and evolving issues around digital technologies and networked publics, examining their social, cultural, political, and global ramifications both on- and off-line. Coursework will engage digital media theory and scholarship. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>Critical Game Studies: Aesthetics and Politics </strong></p> <p>Are video games addictive? Does video game violence affect people in RL (real life)? Are video games art? Can video games change the world? Even as video games have emerged as a multi-billion dollar media industry, how we discuss them remains contentious. Critics disagree over their status as a “serious” mode of artistic expression, along with their place in the “culture wars” that have shaped the political life of the United States and the world. This course provides students with the intellectual framework and critical vocabulary to examine video games as media texts via aesthetics: the value of gameplay experiences and how we fit them into our lives. How do we play, and why? The course will also address questions of politics: how can games shape, and how are they shaped by, the current of public life? Who gets to play, particularly along the lines of race, gender, sexuality, and class? Live and recorded gameplay demonstrations will provide students with the material for criticism and inquiry, alongside contemporary critical games writing, which will serve as models for student writing projects. Participants do not need previous experience with games or computers, but only a willingness to engage with games and gameplay within a critical context.</p> <p><strong>Women Making Moves - Women’s Migration and Media </strong></p> <p>The course will apply a theoretical and practical framework to facilitate an understanding of gendered migration patterns within Asia with a focus on Japan, Hong Kong, Taiwan and the Asian diaspora. This course will be designed to encourage students to critically engage in understanding global migration flows and trends, but to also look closer at more personal narratives of migration. We will discuss forced and voluntary migration, issues of sex work and the emotional labor industry, the crossing of borders, and what it means to belong. The thematic focus will be on the feminization of migration, the monetization of the migrant worker’s body, and looking at how feminist activism is perceived within an Asian context. Students will collaborate on a visual research project that examines themes of migration and how it impacts their daily lives. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>The Art and Politics of Virtual Reality</strong></p> <p>Recent years have seen an explosion in consumer-grade virtual reality (VR) technologies — devices like the HTC Vive, PlayStation VR, Oculus Rift, and Samsung Gear VR have brought a wealth of new experiences to audiences and users, both inside and outside their homes. The new wave of VR content and hardware may feel unprecedented; in fact, the history of VR begins over a century ago. This course will examine “reality” and the “virtual”, two long-contested terms, through the lenses of history, culture, embodiment, and space. Students will walk the boundaries of “virtual reality” through readings, screenings, workshops, and VR experiences. Through this work, students will enter the discourse surrounding VR, where they will struggle with the complicated political questions that surround VR as an art form: Who gets to define what is ‘real’ and what is not? How (and for whom) is something ‘virtual’? What kinds of rules, procedures, laws, and people should govern these strange spaces and places we call “virtual reality”? And how can VR be used not simply as a vehicle for entertainment or escape, but also a space for cultural questioning, activism, and social change? This course is connected to the Oxy Cinematheque Series that will occur during select evening course sessions.</p> <p><strong>Introduction to Game Studies and Culture</strong></p> <p>Games are changing how we create, mediate, and understand our world. This course introduces students to the interdisciplinary field of game studies with a media studies and design focus. Students will read research, play games, analyze games, and think through game design. Students will also examine issues facing gaming culture. A survey of subjects will describe the foundational theories of the field, identities and game culture, and implications/effects of gameplay. Topics to be explored include disability, education and games, cheating, sexuality and games, narratives, addiction, news games, and violence.</p> <p><strong>Who Owns the Internet?</strong></p> <p>This course takes a historical, critical, and experiential approach to the competing sets of interests that have struggled over control of the internet since its inception. These players - military, academic, corporate, activist, regulatory, user, etc. - will be explored through sets of readings, screenings, field trips, and hands-on workshops. Central to our inquiry will be questions of infrastructure, surveillance, and resistance, as they mark out the terrain, on which digital culture thrives, and, through which, major actors exert their influence. Students will have the opportunity to both learn about digital cultures and work in digital modes in this course, with hands on components emphasizing geo-spatial analysis, multimedia presentation, social media engagement, and webmaking.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1359,2022,2349,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-108','<div class="desc"> <p class="sc-BodyText">This course will survey the development of folk and popular music in Europe, including the music of the Balkans, the Baltic States, the Celtic region, the Iberian Peninsula, and the Mediterranean. We will examine how this music has served nationalist agendas, and how media and marketing have shaped the ways in which this music is understood. As most of this music involves dance, the study of dance will be an integral part of this course. Students must be prepared for intensive listening assignments, in and out of class. Prior musical experience or knowledge not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1360,2019,2350,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/MUSC-Music/200/MUSC-248','<div class="desc"> <p>Music producers have at their disposal a set of powerful tools that enable them to create, shape, and refine their sounds in their home studios. In this course, we will use Ableton Live and Logic Pro X for a hands-on approach to composition and sound design. We will address topics such as synthesis and sampling, and we will create and shape pads, basses, and drums by using virtual instruments and third-party plugins. Students compose more advanced creative projects, and will learn the preliminary mixing techniques and related important skill sets required by today''s music industry. </p> </div>','MUSC 148',NULL,NULL);
INSERT INTO course_descriptions VALUES(1361,2022,2351,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-266','<div class="desc"> <p>In this course we study French culture from the reign of "Good King Henry, the Green Gallant," Henry IV (1589Â­-1610) and his invigoration of the arts and French cuisine, to the July Monarchy (1830-Â­1848) and the novels of Balzac, the photographic process of Daguerre, and the music of Chopin. We will also pay particular attention to painting (from Poussin''s classical landscapes to Corot''s Romantic ones), dance (from the codification of couples dancing in the court of Louis XIV to the emergence of classical ballet in 1830s Paris), philosophy (from Descartes''s dualism to Cousin''s eclecticism), theater (from Molière''s The Bourgeois Gentleman to Dumas fils''s The Lady of the Camellias), fashion (from Louis XIV''s introduction of huge wigs of curled hair to the Empire style under Napoléon), and food (from the start of haute cuisine to the invention of the restaurant and gastronomy). Throughout, we will concern ourselves with the interplay of these cultural productions, and how the everÂ­evolving city of Paris served as their crucible.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1362,2019,2353,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-245','<div class="desc"> This course will address fundamental philosophical questions that concern religious belief and experience. Course topics may include the existence of God; the nature, value, and justification of faith; the possibility and desirability of surviving bodily death; and the meaning of human life. The course will focus on classic and contemporary philosophical, literary, and religious texts. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1363,2022,2354,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-350','<div class="desc"> <p>Connects the microscopic properties of the physical world with its macroscopic properties using classical and quantum statistics. Topics include partition functions classical and quantum ideal gasses classical thermodynamics phase transitions and kinetic theory. Includes one ninety minute laboratory per week.</p> </div>','PHYS 240 and PHYS 310 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1364,2022,2355,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-243','<div class="desc"> <p>An introductory examination of the values, principles, and practices of restorative justice. The course will draw on examples of restorative justice from the United States and internationally. Topics in the course will include competing theories of justice, informal and formal approaches to restorative justice, truth telling, reconciliation, and process of reintegration. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1366,2022,2357,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-266','<div class="desc"> This course examines selected topics related to gender and sexuality as they have been negotiated in different global manifestations of the Buddhist tradition. Spanning over 2,500 years and multiple civilizations, Buddhism as a philosophy and Buddhist communities have constructed concepts of gender, sexuality, and the body in multiple, often conflicting, ways. Seen as androcentric and misogynist by some and liberating and non-judgmental by others, Buddhism and Buddhist institutional attitudes related to these key themes have been constructed through complex interactions between ancient traditions and the different societies in which Buddhism has developed. The course will be anchored in theoretical considerations of sexuality and gender, which we will explore through different case studies from India, China, Tibet, Thailand, Japan, and Korea. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1367,2022,2358,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-277','<div class="desc"> <p>This course will survey ancient Mediterranean views about the catastrophic end of the world. We will study how ancient folks--Greeks, Romans, Jews, and Christians--interpreted disease, natural disasters (fires, floods, food shortage), political upheavals, and social unrest as signs of the end of the world. We will study how they altered their behaviors to anticipate the near end. And we will study their visions and fantasies of the utopian societies they hoped would emerge after the devastation. At the end of the course, students will conduct a staged research project on a topic of their choice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1369,2022,2360,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/200/soc-270','<div class="desc"> <p>What are the effects of urbanism on human psychology and civic life? How does urbanization structure social and economic relations as well as signifying identities and cultural meanings? Is there a common "human ecology" of cities in "natural areas" such as the CBD skid row the "Tenderloin" or the "zone-in-transition"? We examine the urban underclass through case studies of the African American ghetto and Spanish Harlem with attention to public policy perspectives on urban poverty. Urban futures are considered through gentrification growth machine boosterism (sports and convention centers) and urban theme parking.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1370,2022,2361,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-323','<div class="desc"> This course explores the sociological analysis of law, focused on the legal construction of social "groups," the moral regulation of social action, and the formal legitimization of state practices. The course is divided into two sections. The first half of the course examines theoretical approaches to the sociology of law drawing on the works of Max Weber, Niklas Luhmann, Jürgen Habermas, and Pierre Bourdieu, as well as perspectives rooted in Marxism, feminism, and critical race theory. The second half of the course focuses on contemporary legal controversies in the United States, including racial disparities in criminal justice, undocumented immigration, the regulation of sexuality, and the criminalization of political dissent and protest. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1371,2022,2362,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-205','<div class="desc"> This course addresses the fluid boundary between law and performance. We will think through how performances of law influence legal practice and vice versa. We will also interrogate how theater provides an alternative site for the performance of justice, one that may satisfy needs that go unmet in state and federal courts. We will study trial transcripts as legal and cultural documents, and we will look at their dramatizations, putting these plays into conversation with contemporary theater, performance, and legal criticism while also thinking about how our own needs and impressions of justice have been, or can be, staged in and through performance. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1375,2022,2366,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-283','<div class="desc"> <p>This course examines the development of Italian Renaissance architecture, from about 1300 to about 1550. It will consider buildings in the civic and ecclesiastic context, both sacred and secular. The evolution of this tradition will be studied in relationship to issues of function and structure; contemporary writing; and religious, political, and economic influences.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1379,2022,2370,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-228','<div class="desc"> <p>Book Arts: The Handprinted Book is a hybrid book making, research, writing and collaborative art making course. Students will advance their knowledge of letterpress printing by researching, planning, designing, and producing a handprinted artist book. The course will address narrative sequencing, page layout and design, type as graphic innovative and/or image-making, methods for the Vandercook Press, and the structure of the book. Each course iteration will address a theme, integrating book making techniques with theoretical readings, collaborations with faculty and departments from across the College, and primary research in Special Collection the Moore Zoology Lab and other campus collections. The course is will also examine the current state of the book in the context of 20th and 21st century artist book design and production.</p> </div>','ARTS 227 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1384,2022,2375,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-390','<div class="desc"> <p>This seminar course will teach students skills needed to read and critically analyze original journal articles. Some lectures will be given, but the bulk of the course will consist of student-led discussions and analysis of scientific papers. Students will improve their communication skills by discussing papers and leading discussions, by writing a research paper and peer-editing, and by preparing PowerPoint presentations as an aid for leading discussions. May be taken more than once for credit as the topics will differ each semester, but can only be used to fulfill one of the requirements for the Biology major. Cannot be used to fill the Biology requirement of the Biochemistry major.</p> <p><strong>The Broader Impacts of Biology</strong></p> <p>This seminar course will explore the broader societal impacts of the biological sciences. Science is an endeavor that aims to categorically build knowledge about the universe in an objective manner. But our science not only informs society, it is also shaped by the needs and structure of our society. In this class, students will explore the potential societal impacts and determinants of their scientific interests through careful exploration of the literature. Through this exploration, students will learn to lead discussions about the intersections between science and society, critically evaluate the role of science in society, and develop skills in both oral and written scientific communication. Students will work with the professor to lead a discussion on a topic of their choice and will learn to write a “broader impacts” section of a scientific grant, detailing how the science extends beyond the boundaries of the specific scientific endeavor to affect society. Each week we will explore a research topic in the scientific literature and accompanying literature on the societal impacts/determinants of that research. Example topics: Climate Justice and Global Change Biology, Environmental Justice and Urban Ecology, Biological Property Rights and Cancer Research, Anti-Racism in the Biological Sciences, Indigenous Rights and Ethnobiology, Social Equity in Human Health, and Microbiology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1407,2022,2398,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/200/cogs-255','<div class="desc"> <p>The primary goal of this course is twofold: (1) to provide students, from a wide range of disciplines, with hands-on training to analyze a variety of data-sets relevant to their course of study, and (2) to provide them with the tools to understand the rhetorical form and function of different types of data visualizations. Students will consider how questions can be answered using data; learn how to analyze data appropriately; learn to design and present graphs that tell an easy-to-understand visual story, have high impact and are memorable, and critically consider the assumptions underlying accurate interpretation of analyses and visualizations. Students from any major are welcome.</p> </div>',NULL,'COGS 255L ',NULL);
INSERT INTO course_descriptions VALUES(1432,2022,2425,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-222','<div class="desc"> <p>This course introduces students to the political economy of Latin America. The first section of the course looks at the rise of dependency theory and import substitution industrialization (ISI) as the region''s predominant development strategy. We will study the motivations behind ISI, its initial success in terms of economic growth, and the challenges associated with such strategies of development. We will focus on the origins of the 1980''s debt crisis, the abolishing of the ISI model, and the subsequent turn to neoliberal development strategies. The course aims to provide students with a deeper understanding of the transition to neoliberalism, the so-called Washington Consensus, and the broader political and economic implications of the reform processes that have unfolded since the early 1980''s. We will study the interaction between democratization and economic reform and aim to understand how these simultaneous transitions have affected the policy-making process and the formation of public policy in the region. Latin America is a diverse region; therefore, this course will emphasize its economic and political diversity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1433,2020,2426,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-240','<div class="desc"> <p>This course will examine why, how, and when voices of dissent turn into a full-scale revolutionary movement. We will analyze how revolutionary practice has gone beyond the Leninist model to the mass model that came to be known as civil society. What was civil society and how did it contribute to political change? What was the role of religion in this process? This course will examine the different expressions of civil society and how it brought together secular and faith communities in different social, political, and cultural contexts. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1441,2022,2434,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-344','<div class="desc"> <p>Post-conflict reconstruction in the wake of war and state-building have been prominent activities in international security. The international community now addresses non-state conflict with vigorous programs of state-building. Former President George W. Bush writes in his biography “Afghanistan was the ultimate nation-building mission.” The prevailing post-conflict reconstruction paradigm emphasizes building indigenous capacity – security, governance, judicial, social and economic – so that peace can be sustained without outside intervention. The agents of transition from war to peace are varied in type: internal and external; military and civilian; governmental, intergovernmental, non-governmental and private sector. Military personnel, for example, have long performed many services in the chaos of war and its aftermath: providing emergency medical treatment, food and shelter for dislocated civilians; patching infrastructure, running town meetings, building schools, patrolling streets and training security forces. Aid workers braved great danger to relieve human suffering. A broad array of peace builders today attempts ambitious agendas for human security, effective participatory governance, economic liberalization, and rule of law. The common goal of these activities is to build a basis for political and economic development. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1446,2022,2439,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-307','<div class="desc"> <p>Using, interpreting, and understanding data is increasingly important for understanding the magnitude, determinants, and solutions to social issues. This course provides an introduction to economic data analysis, discussing how economists quantify key concepts, test theories using empirical data, and evaluate policy effectiveness. Students will learn basic statistical methods and data analysis techniques, including how to clean, visualize, and analyze data using statistical programming packages. The course will also present an intuition-based introduction to regressions and causal inference. We will develop these skills discussing data and models from a range of topics, including poverty and inequality, macroeconomic growth, health, and education.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1450,2022,2443,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fren-french/300/fren-370','<div class="desc"> <p>This course explores the history and development of one literary genre (fiction, poetry, theater, or cinema) across different periods and in different French-speaking communities. Content varies from year to year.</p> <p style="margin-left:0in; margin-right:0in"><strong>Francophone voices of Africa and the Caribbean</strong></p> <p style="margin-left:0in; margin-right:0in">This course traces the development of literature in French by writers living in or originating from France’s former colonies, primarily the Caribbean and Sub-Saharan Africa. Through short stories, novels, and the <em>bande dessinée</em>, we will examine key intellectual, political, and social movements that have shaped, and continue to shape, Francophone postcolonial identities. We will consider themes such as decolonization, Negritude, tradition vs modernity, immigration and exile, and hybrid/Afroeuropean identities. Texts will include works by Aimé Césaire, Edouard Glissant, Maryse Condé, Mariama Bâ, and Alain Mabanckou. Additional Core Requirement Met: Global Connections.</p> </div>','FREN 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1455,2020,2448,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-253','<div class="desc"> <p>This interdisciplinary course will survey the urban geography and cultural history of Mexico City from the late nineteenth century to the present. Through a range of sources including photographs, literature, film, art, architecture, and public spaces we will chart the growth of the oldest capital in the Americas as it developed into the world''s original mega city and what journalist David Lida argues is the capital of the 21st century. The lectures and discussions will center on a series of overlapping questions: How did Mexico City take shape culturally and physically in the modern era? What traces remain of the colonial city? How should we conceptualize and theorize the city? How have different social groups and individuals negotiated and appropriated urban spaces? What have been the political and environmental consequences of the city''s explosive growth? Through writing assignments and digital mapping we will develop sensitivity to historical contingency in the development of urban space and skills for cultural and visual analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1461,2022,2454,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-241','<div class="desc"> <p>In a digital moment where both the democratizing and totalitarian possibilities of media are unprecedented, the need to analyze and understand both the politics and <em>poetics</em> (the distinct audiovisual rhetorical strategies) of documentary media has never been more vital. This class combines readings, screenings, discussions, group exercises, and distinct forms of critical and professional writing to explore the evolving histories, theories, ethical questions, and creative modes of documentary. Together we will examine how documentary media can effect social change, expand the diversity of voices and stories that are seen and heard, and challenge each us to reimagine our fundamental conceptions of "truth" and "reality." </p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1462,2022,2455,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-255','<div class="desc"> <p>This course examines the history, theory, and practice of integrating time-based media into three-dimensional space. This is a theory/practice course: students will study the history of video and audio installation and attendant theories around interactivity, virtuality, and site specificity, while experimenting with different methods of troubling the passive relationship of viewer to screen in traditional cinema. Through hands-on exercises, students will develop sensitivity to three-dimensional space, explore the relationship of the human body to aural and visual environments, and create a series of linear and non-linear narratives that take into account viewers in motion. The class will culminate in the production of a media object, and/or installation, that demonstrates a careful consideration of form and content in relation to space.</p> </div>','MAC 140 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1463,2022,2456,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-295','<div class="desc"> <p>The study of film and media has involved disciplinary and interdisciplinary approaches for about half a century. This intermediate topical course of varying emphases studies the key critical terms, issues, and debates in popular media cultural study, including genre study, in relation to specific topics. Readings of film and media examples illustrate how different theories or perspectives can be applied to contemporary pop culture.</p> <p><strong>Audiences and Spectators</strong></p> <p>Media is not only enjoyed by solitary viewers, but also by communities of people who come together to celebrate their love of culture. Across the 20th and 21st centuries, media fans have formed clubs, written amateur publications, altered their appearances, and made parodies of their favorite movies and TV shows as ways to express their fandom. This course will explore how audiences have taken pleasure in film, television, and contemporary digital media. Students will examine moving images in a variety of technological formats and exhibition contexts to study how communities of viewers have developed vibrant fan cultures around popular media. Students will also learn how media spectatorship has been structured by racial segregation, class-based accessibility, and other vectors of social inequity. Course screenings will include: <em>The Last Picture Show</em>; <em>Goodbye, Dragon Inn</em>; <em>The Watermelon Woman</em>; and <em>Dawson City: Frozen Time;</em> in addition to user-generated content on platforms such as YouTube, Vine, and TikTok.</p> <p><strong>Media and Your Body</strong></p> <p>Media forms require us to be spectators, audiences, and increasingly, users and participants, in ways that distinctly implicate and impact our bodies and identities. The course examines the nature of bodies, spaces, and materiality in media, specifically examining prominent theories and analyses that illuminate the nature of media as it exists off of the screen. The course will survey how we interact with media in different spaces and how our bodies form a part of the media experience. Specific topics include mobile games, humor and riffing with movies, participatory media, materialism, haptics, television spaces in the home and beyond, disability media studies, performing sexuality, and mental illness and video games. Assignments will engage students in practicing the theories they learn in class.</p> <p><strong>Genre in Contemporary Film, TV, and Digital Media</strong></p> <p>Genre films were part of Classic Hollywood, but genres started changing in interesting ways as media industries evolved after World War II, with the introduction of television, new technologies that enabled shooting on location or new opportunities with color film, the rise of drive-in movie theaters, and indie or exploitation filmmaking. We will study the shift from classic genre films and theory to hybrid genres and genre revisionism in film/media movements spearheaded by people of color, feminists, and LGBT communities, as well as studios. The focus in the class is on genre theory studied through historical and technological shifts in media production. Screenings will introduce a range of genres, from classic films like the Western and noir to more recent genres like road films, television melodramas, and war video games.</p> <p><strong>Imagining War: Genre on Screen and Battlefield</strong></p> <p>The war film has arguably been one of the most consistent and popular elements of cinema''s history. It was a component of film from its beginnings and is now a regular mainstay amongst Hollywood blockbusters. It has also undergone several political revisions and technological shifts in media production, distribution and exhibition, making it ideally suited to study the theory and history of genre. Importantly, this course will not only look at how war figures in film, but how film also profoundly effects and configures war. Entertainment and war are the United States'' primary exports. Militarism and the Hollywood studio system have had a long and deadly interdependence. By conceiving of the viewing screen as an extension of the battlefield (and vice versa), this course will look at the profound social and political implications of the classic genre system. We will do this by examining such films as <em>Apocalypse Now, The Deer Hunter, Hiroshima Mon Amour, Battle of Algiers, Black Hawk Down, Kandahar, Night and Fog, The Hurt Locker. Das Boot, Saving Private Ryan, All Quiet on the Western Front, Dr. Strangelove, Inglourious Basterds, Birth of a Nation, Rambo, MASH</em>, as well as a host of television shows, websites, and video games</p> <p><strong>The Western: From Colonialism to Gaming</strong></p> <p>This course will primarily explore the classic Hollywood genre system through a detailed look at "The Western." However, before looking at how genre operates within cinema, we take a broad historical and theoretical examination of genre within literary studies, critical theory, Wild West shows, philosophy, travel literature, ethnographic photography, and cultural studies. The aim is to critically examine a wide array of generic conventions within "The Western" film, while simultaneously situating these conventions within the broader historical and ideological context of European colonization of North America. Particular attention will be placed on the role of racial and gender performances within "The Western" genre as both a founding American myth and a component of the Hollywood film system. We will analyze both the classic Western as well as revisionist films. Additionally, we will investigate how the genre transforms as it moves into other media, including fine art, television, gaming, and other digital contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1470,2022,2463,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-299','<div class="desc"> <p>This course is centered around understanding, and engaging deeply, with applied ethics cases developed for the Intercollegiate Ethics Bowl. These cases typically deal with a broad array of contemporary issues, such as immigration rights, the ethics of self-driving cars, gun control, race/gender on college campuses, etc. In the course, students will research realistic ethical cases, work in teams to develop thoughtful ethical analysis of these cases, and articulate these analyses both verbally and in writing. Throughout the semester, students will prepare for the regional Ethics Bowl competition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1479,2022,2472,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-269','<div class="desc"> <p>Special topics in physics selected largely by student interest and requiring no more than introductory physics courses. Possible topics include: variational methods celestial mechanics chaos nonlinear systems. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1483,2022,2476,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/300/phys-366','<div class="desc"> <p>Review of special relativity. Introduction to the fundamentals of general relativity and gravitation with applications to cosmology. Topics include the big bang theory primordial nucleo-synthesis the dark matter problem gravitational red shift and the expansion of the universe stellar evolution and black holes.</p> </div>','PHYS 310 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1487,2022,2480,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-201','<div class="desc"> <p>This course examines how the mass media affects democratic politics in the United States. In the U.S., the media is comprised of various news sources, including mainstream news outlets (e.g., ABC, CBS, NBC, The Washington Post, The New York Times), cable news shows (e.g., CNN, Fox News, MSNBC), online blogs, talk radio, online video platforms, and satirical political comedy shows. In the growing Internet age, news is also delivered via social media (e.g., Facebook, Twitter, Snapchat), giving individuals a vast array of diverse political information. In this course, we aim to understand how information is delivered to citizens, what impact it has on them, and how the media may affect public policy. In general, in this class we work toward a better understanding of the media’s role in American politics.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1491,2022,2484,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/300/pols-351','<div class="desc"> <p>Alexis de Tocqueville, John Stuart Mill, and Friedrich Nietzsche are three of the most influential theorists to grapple with the tradition of liberal political thought. The first two are friendly critics who seek to fortify liberalism against what they see as its latent pathologies, while Nietzsche is a not-so-friendly critic who wants to overturn it entirely. Given that liberalism is under attack today from both the right and the left, there is much to gain from serious study of their reflections. In this course, we will compare the strengths and weaknesses of their diagnoses of the present and visions for the future. Guiding questions for the course will include the following: Does liberal democracy uplift human beings, or degrade them? How should the competing demands of individual independence and community solidarity be balanced? How can we best counter modern society’s tendency to engender stifling conformity? What is the significance of Christianity for the cultural heritage of Western society? What role, if any, should religion play in societies of the future? Finally, what does human flourishing consist of, and what kind of sociopolitical conditions best facilitate it? The culminating assignment of for the course will be a substantial research paper on one or more of these thinkers.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 150 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1498,2022,2491,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-309','<div class="desc"> Ontogentetic approach to human movement behavior and physical growth from conception to adulthood with emphasis on maturational and environmental factors. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1499,2020,2492,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/psyc-psychology/300/psyc-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological mechanical and cognitive bases of motor skill acquisition. <em>Includes one three-hour laboratory per week. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1500,2022,2493,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'PSYC 310L',NULL);
INSERT INTO course_descriptions VALUES(1504,2022,2497,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-257','<div class="desc"> <p>A systematic examination of the history of anti-Semitism, beginning with the emergence of anti-Judaism in late antiquity, its transformation into theological anti-Semitism in the Middle Ages, and a racialized anti-Semitism in the modern world. In each period, students will investigate the socio-political contexts that gave rise to the fear of, hatred toward, and attacks on Jewish individuals and communities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1510,2022,2503,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/100/musa-106','<div class="desc"> <p>Basic ukulele technique at the beginning through lower intermediate level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1511,2022,2504,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-279','<div class="desc"> <p>Private, one-on-one weekly lessons. Advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1512,2022,2505,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-280','<div class="desc"> <p>Private, one-on-one weekly lessons. Advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1513,2022,2506,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-347','<div class="desc"> <p>Many recent advances in artificial intelligence are not in symbolic systems, but in statistical machine learning and data science. This course offers a balance between the theory and practice of data science, from collecting and understanding the data, to developing supervised and unsupervised models (such as linear regression, support vector machines, K-means and Gaussian mixture clustering, principle component analysis, neural networks), and finally interpreting the predictions and their limitations.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 and either COMP 149 and MATH 146/ COMP 146; or MATH 150, MATH 210, and MATH 214; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1514,2022,2508,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-149','<div class="desc"> <p>This course provides the mathematical theory which underpins Computer Science, including: number systems; variable types and formats; logic; set theory; graph theory; linear algebra; and important numbers, functions, and relations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1515,2022,2509,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/200/comp-239','<div class="desc"> <p>This course covers the basics of how a computer works, focusing especially on the hardware-software interface. Students will learn about the limitations of the physical computer, and that it may not be possible to ignore the lower-level hardware when designing efficient software. Students will learn to implement programs in Assembly language and C/C++. They will investigate the main components of the computer and it''s processor and master the binary language of computers. They will learn important design concepts such as memory hierarchy and parallel computing, and have a brief encounter with principles of digital logic. This is a required course for the Computer Science major. Includes one 1.5-hour lab period per week.</p> </div>','COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1516,2022,2510,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-390','<div class="desc"> <p>This course focuses on responsible conduct of Computer Science. Students will explore the effects of technology on the modern world, including issues of electronic voting, personal security and privacy, intellectual property, and others. This course will culminate in a research paper on one of these topics, examining the technical background, as well as the social forces that contextualize the issue. Students should have a decent understanding of the challenges of writing software, and why certain questions are computationally difficult (that is, require significant time/memory). </p> </div>','COMP 229 and one 300-level COMP course ','A second 300-level COMP course',NULL);
INSERT INTO course_descriptions VALUES(1517,2022,2511,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/100/educ-142','<div class="desc"> <p>In this course, Occidental students who are Spanish speakers will support students and teachers in Dual Language Programs in the local schools. Support will consist of Spanish language development and language enrichment activities that will create an engaging and critically conceptual environment for elementary and middle school students. <strong>Occidental students will meet with the professor several times throughout the semester and will work with elementary and middle school students in their classroom two hours a week during the school day</strong>. Transportation to the schools will be provided for those who need it. Graded on a Credit/No Credit basis. May be repeated for credit. For further information, email the professor.</p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1518,2019,2512,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/300/PHIL-317','<div class="desc"> <p>This course will attempt a survey of current philosophical approaches to classical Hollywood film, beginning with Stanley Cavell’s <em>The World Viewed: Reflections on the Ontology of Cinema</em> (1971). This work initiated a new and flourishing sub-discipline within contemporary academic philosophy called film-philosophy. The central assumption within this body of inquiry is that film is (or can be) “philosophy in action.” In this course we will be returning to the source of this idea to read Cavell’s original work, as well as selections from his two subsequent books: <em>Pursuits of Happiness: the Hollywood Comedy of Remarriage </em>(1981) and <em>Contesting Tears: The Hollywood Melodrama of the Unknown Woman (</em>1996). We will then extend our inquiry to other writers inspired by Cavell (and reflections on later developments within Hollywood), such as Robert Pippin (writing on <em>Film Noir</em>), Stephen Mulhall (writing on the <em>Alien</em> series and other sci-fi), and William Rothman (writing on Hitchcock). Weekly screenings and discussions will be part of the course, as well as one or two field trips to Los Angeles archives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1519,2022,2513,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/psyc-351','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','PSYC 101, COGS 101, LING 301, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1520,2022,2514,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-181','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women, such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1521,2022,2515,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-381','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage. This course meets with CSLC 181 and is for students who will be reading texts in the original Greek.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1522,2022,2516,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-145','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we''ll also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1523,2022,2517,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-345','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we will also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic. In this 5-unit course we will be reading Lucretius in the original Latin, and will address the ways in which his poem''s semantic content, syntax, and literary form work with (or against) one another to produce that texture of Roman cultural significance that is the <em>de Rerum.</em></p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1524,2022,2518,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-365','<div class="desc"> This course examines the role of gender in the production and reception of visual images in Japan from the twelfth through the twenty-first centuries. Closely engaging with a variety of images, literary texts, and performances, we will investigate topics such as Buddhist conceptions of the feminine, same-sex sexuality and gender reversals in the medieval imagination, beauty prints and the politics of the gaze, changing conceptions of art and women in modern Japan, masquerades of masculinity, and the place of male-male sexuality in contemporary girl culture. Ultimately, this course will provide students with an understanding of how art and gender have been conceptualized in Japan, as well as tools to think beyond that understanding.<p></p> </div>','Any art history course, Japanese studies course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1525,2022,2534,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-215','<div class="desc"> <p>This seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1526,2022,2537,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-246','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1527,2022,2538,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/easn-east-asian-studies/200/easn-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1528,2022,2539,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/200/comp-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1529,2022,2540,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/400/comp-490','<div class="desc"> <p>This course will support senior Computer Science majors as they conduct projects as part of their Senior Comprehensive requirement. Students must have senior standing to enroll.</p> </div>','COMP 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1531,2022,2542,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. Open to sophomores, juniors, and seniors only.</p> </div>','POLS 101, BLST 110, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1532,2022,2543,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/400/blst-490','<div class="desc"> <p>During the spring semester, students will complete a 25-page research paper on a topic relevant to Black Studies. The project will be based on original analysis of primary sources and grounded in the scholarly literature on the subject. Seminar meetings will be devoted to discussion of selected texts on research methods in Black Studies and ongoing review of students’ work-in-progress. The seminar will conclude with student presentations that will be open to the entire campus community. </p> </div>','BLST 110 and the BLST Second-Stage Writing Requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1533,2022,2544,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems, make decisions, draw inferences, attend to their environment, communicate, remember, and learn. Much of the material is applied to real-life settings.</p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1534,2022,2545,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/400/cogs-495','<div class="desc"> <p>Students with substantial directed research experience will conduct an independent research project of their own design, with guidance from a faculty mentor. Students are expected to devote a minimum of 6 hours per week to their project, and will present their results in a colloquium open to the campus community. Open only to seniors and by permission of the instructor.</p> </div>','COGS 201, COGS 290, or COGS 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1535,2022,2546,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-108','<div class="desc"> <p>Taught in English. This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1536,2022,2547,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-340','<div class="desc"> <p>This course focuses on the process and technology behind making intuitive and useful websites and the techniques for determining the effectiveness of the products, including prototyping and user testing. Students will also explore how principles of attention, perception and cognition relate to user experiences.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131, COGS 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1537,2022,2548,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-398','<div class="desc"> <p>Working with a CTSJ faculty member, students will select an internship site whose mission is to address matters of inequality and social justice. The Department has a list of organizations where students can inquire about internships. Students who would like to intern at an organization will have to petition the department with a letter of support from the organization. The practicum experience will be evaluated by their field supervisor, the faculty liaison, and by the completion of the Social Justice Practicum Handbook. In addition to the internship responsibilities, students will participate in regular meetings with the instructor and attend class meetings. Additionally, they will complete a social justice practicum handbook, which requires deep reflection that brings the internship experiences in dialogue with critical theories related to matters of social justice. Students may participate in internships as individuals, pairs, or small groups, depending on the needs of the organizations. Open only to Critical Theory &amp; Social Justice majors with sophomore standing or above.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1538,2022,2549,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-103','<div class="desc"> <p>This course is an undergraduate survey of the field of Global Political Economy (GPE), required to major in Diplomacy and World Affairs. It is intended as an introduction for students who already have some background in the field of International Relations (DWA 101) and Economics (Economics 101) and are interested in exploring global political economy theories, relations and issues. The course covers major theoretical, empirical and policy perspectives. The first part of the course will cover basic concepts and theoretical foundations of political economy: liberalism, Marxism, realism, feminism, etc. The focus will be on core theoretical principles and approaches. The goal is to understand how theory is framed and how it "works"; the potential inferences of theories, and their practical import. The second part of the course delves into globalization as a field of study and set of empirical dynamics, building on the theoretical foundations of the first part of the course. The third part of the course explores emerging topics in global political economy such as global finance, the informal economy, the underground economy, the green economy/sharing economy/circular economy, gender and the global economy, corporate citizenship and responsibility, social enterprises, the sustainable development goals, social/economic rights and more. Open only to DWA majors; for non-majors, special permission of instructor required.</p> </div>','DWA 101 and ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1539,2022,2550,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/easn-east-asian-studies/200/easn-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Cultural Appreciation and/or Appropriation through the Lens of Asian Cinema</strong></p> <p>At its core, this course is an attempt to investigate, analyze, and ultimately comprehend the concept of cultural appropriation, in particular through an East Asian context. With a history of imperialism, be it Western or Japanese, in the 19th and 20th centuries, the topic of cultural appropriation is controversial and complicated, whether it is Katy Perry performing wearing a kimono at the American Music Awards or Chinese-Taiwanese-American chef Eddie Huang and his embrace (appropriation?) of African-American black culture. Prior to the actual viewing and analyzing of films, a comprehensive, albeit limited, survey of theoretical works will be conducted; works including but not limited to Richard Rogers’ “From Cultural Exchange to Transculturation: A Review and Reconceptualization of Cultural Appropriation,” Baris Buyukokutan’s “Toward a Theory of Cultural Appropriation,” and Lisa Nakamura’s concept of “identity tourism.” Some of the pairings to be analyzed are: William Shakespeare’s <em>King Lear</em> and Akira Kurosawa’s <em>Ran</em>; Clint Eastwood’s <em>Unforgiven </em>(1992) and Lee Sang-il’s Japanese Western <em>Yuzusazarumono </em>(2013).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1540,2022,2551,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/400/geo-491','<div class="desc"> <p>This seminar focuses on analysis, discussion, and presentation of current issues in geological research. These topics will be explored through the geologic literature and the class will include a formal presentation to the Geology Department. Students will also learn about graduate school and career options in the Earth Sciences. Open only to senior Geology majors.</p> </div>','GEO 391 or GEO 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1541,2022,2552,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-308','<div class="desc"> <p>This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling. </p> <p>This course will meet three times a week, twice with CSLC 108 with lectures and discussion in English, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','Must have completed the German language sequence (GERM 101, 102, 201, 202) or placed out of Elementary and Intermediate German ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1542,2020,2553,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-214','<div class="desc"> <p>This course, covering the period roughly from 1850 to 1877, examines the origins of the Civil War, the war itself, and the period of Reconstruction. The class meetings and readings will focus on the transformation wrought by the war, analyzing in particular the impact of the war on society, politics, and culture. Although there will be some discussion of military events and the military experience of some of the participants, this is not a course in military history. We will pay special attention to the following themes: the imperfections in the republic that led to war; the centrality of slavery and emancipation before and during the war; the war as a revolutionary experience for individuals and institutions; and the meanings and legacies of reunion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1543,2022,2554,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-258','<div class="desc"> <p>This course seeks to engage you in the fundamental problems of twentieth century Mexican history and introduce analytical frameworks for studying cultural politics. The central theme will be how the state and grassroots society negotiated the course of the nation and its political culture since 1875. We will critically examine the production of the dominant historical narrative and develop alternative ones that can help us understand the differences in the historical experiences of subaltern groups, including women, indigenous people, and <em>campesinos </em>within the Porfirian, revolutionary, and post-revolutionary periods. We will examine what is cultural about politics and what is political about culture through an interdisciplinary format, perspective and organization drawing upon the fields of history, anthropology, literature, and visual studies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1544,2022,2555,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or POLS 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1545,2022,2556,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/math-mathematics/400/math-401','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Cryptology</strong></p> <p>Cryptology is the study of sending secret messages over insecure communication channels. Cryptographic capabilities are important to politics and foreign affairs, and underlie the functioning of a great deal of the modern economy. In this course we will study the mathematical theories and techniques that make cryptography function, and also those that break it. We will learn how these mathematical tools influence the use of cryptographic systems, and practice explaining these implications to people without developed mathematical backgrounds.</p> <p><strong>Applications of Linear Algebra</strong></p> <p>We will use the book Thirty-three Miniatures: Mathematical and Algorithmic Applications of Linear Algebra, by JiÅì Matoušek. We will concentrate mostly on the mathematical applications (as opposed to the algorithmic applications). In the first two class meetings we will learn about (generalized) vector spaces, as preparation for the remainder of the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1546,2020,2557,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-230','<div class="desc"> <p>This course explores the emerging fields of narrative design and worldbuilding. These fields apply storytelling techniques to design problems that span traditional and cutting-edge media forms — from filmmaking, theater, and architecture, to mobile apps, video games, and virtual reality. As a result, narrative designers and worldbuilders are becoming increasingly valued by a diverse set of industries. Using both analog and digital tools, students will create short projects that investigate interactivity, non-linear storytelling, user interface and experience design, transmedia, the poetics of space, and other relevant topics. Students will have the freedom to create projects that relate to their specific skills, goals, and experiences, while readings and short screenings will contextualize their hands-on work within larger political and cultural contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1547,2022,2558,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-107','<div class="desc"> <p>This course involves in-depth exploration, practice, and application of vocal techniques for the more experienced singer plus an emphasis on advanced aspects of performance. Students will learn and perform three solo songs during the course of the semester. Culminates in a final recital. Recommended as a supplement to private lessons. Graded on a Credit/No Credit basis only. May be repeated three times for credit. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1548,2020,2559,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/musc-music/100/musc-110','<div class="desc"> <p>Fundamentals of orchestral strings technique: tone production, left-hand development, repertoire, and musicianship. Recommended as preparation for private lessons. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1549,2022,2560,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-348','<div class="desc"> <p>Students learn the art and craft of mixing and mastering music, as it applies to the many creative and technical considerations involved in creating a professional music mix. Using Pro Tools as our main Digital Audio Workstation, all aspects of mixing and mastering will be covered, including in-depth explorations of built-in and third-party plug-ins. By the end of the course, students will have completed weekly assignments using existing pre-existing audio and midi stems and will have produced an original work that is mixed and mastered to industry standards. Must be taken before one''s senior year.Instructor permission required.</p> </div>','MUSC 247, Pro Tools Fundamentals. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1550,2022,2561,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/100/phil-199','<div class="desc"> <p>This course will be an introduction to case-based reasoning in practical ethics and political philosophy. Students will learn basic philosophical tools for analyzing the moral or ethical dimensions of practical problems, with an emphasis on medical or health related cases and policy. Heavy emphasis will be placed on speaking and critical thinking. May be repeated once for credit. Graded on a CR/NC basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1551,2019,2562,'http://smartcatalog.co/en/Catalogs/Occidental-College/2018-2019/Catalog/Courses/PHIL-Philosophy/200/PHIL-200','<div class="desc"> <p>In this course, we will draw on philosophy, literature, psychology, and film in order to consider the significance of death for the way we live our lives. We will address three main sets of questions: (1) Is death bad for the person who dies? Does the fact that we will die undermine the meaning of our lives or render our lives absurd? (2) Does the character or duration of our grief over the deaths of people who are close to us, for example, our children or our spouses, help determine the significance of our relationships with those people? If so, how? (3) How, if at all, are our values shaped by the assumption that others will live on after we die? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1552,2022,2563,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/200/psyc-224','<div class="desc"> <p>This course provides students with an intellectual and practical foundation in dialogue<em> facilitation</em>. Participants will <em>apply</em> intergroup relations theory and knowledge about culturally diverse populations as they learn about and attend to group dynamics, conflict management, and intergroup relations pedagogy. Specific attention will focus on multicultural dialogues devoted to Sexual Orientation, Social Class, Race, Gender, and Ability. Training videos and exercises, in addition to small group co-facilitations form the foundation of the course. Group work, including pedagogical development meetings, are required outside of class as preparation for facilitation. </p> <p>Applications due by March 23, 2018. Contact the Professor Rodriguez (jackir@oxy.edu) for application information.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 223 (may be taken concurrently) and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1553,2022,2564,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-205','<div class="desc"> <p>What makes a thing, a place or a person sacred? This course focuses on the tangible elements of religion: the materials, objects, spaces, art, blood and guts that inspire belief and community. We will explore the way "things" interact with humans in their processes of creation, interpretation and the (re)definition of the religious, the sacred, the natural and supernatural, the holy, the profane, the secular, the immaterial, and transcendent, grounding our exploration in case studies. Our work will raise our awareness of the significance of materiality in religion and raise questions of authenticity, replication, and commodification. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1554,2022,2565,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-247','<div class="desc"> <p>Mythical journeys to otherworldly places are common in Mediterranean cultures, and represent important points of intersection between ancient Near East and Classical cultures. These mythical journeys—which articulated both the divisions and connections between the realms of the living and of the dead—served various objectives: describing heroic actions of central characters (divine or human), symbolizing the quest for secret knowledge, explaining the mysteries of life and death, and/or endorsing a political or economic system through divine precedent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1555,2020,2566,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/rels-religious-studies/300/rels-300','<div class="desc"> <p>This seminar will investigate the meanings and traditions behind the popular American claim "I''m spiritual but not religious." What is spirituality in the American context? How and why does spirituality overtake religion in appeal and status? What historical features of American culture and society promote contemporary issues of spirituality?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1556,2022,2567,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-290','<div class="desc"> <p>This topics course provides opportunities to work on performance outside of traditional naturalistic traditions. Topics change annually. First-year students may only take this course with permission of instructor. May be repeated once for credit when taken as a different topic. <em>Note: Different topics may satisfy different Core requirements</em>.</p> <p><strong>Creating Community Engaged Theater</strong></p> <p>Under the guidance of members of the world renowned and community engaged Cornerstone Theater Company, this course will introduce students to the Cornerstone method of creating original theater work that addresses local concerns through community collaboration. During the course, students will help with The Highland Park Community Project—Cornerstone’s community engaged project in rehearsal and performance in Fall 2020. This production will provide the experiential aspects of the course, some of which will take place off-campus in the Highland Park Community. In regularly scheduled class meetings, students will study the Cornerstone methodology, especially intention and engagement, and through discussion, lectures, and research, be introduced to existing approaches to community based theater. Topics will include how community engagement informs acting, directing and design. <em><em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></em></p> <p><strong>Reframe the Game: Strategies for a More Inclusive American Theater</strong></p> <p>Reframe the Game is a deep dive into Equity, Diversity and Inclusion (EDI) principles, as they apply to working in the theater, as well as in interpersonal communication practices. Through hands-on activities, discussions, research and interactions with guest practitioners, the course will address why this work is vital to our field, and how EDI lays the foundation for more creative and imaginative artistic workspaces and practices. The course will be organized into three parts. Part One will focus on Vocabulary and Power Structures: The cohort will focus on establishing a shared vocabulary as a foundation for conversation about social identity, privilege, historical and institutional inequities, and ally-ship, as a means to develop skills to better identify and dismantle inequity when we see it. We will look inward to examine where we as individuals fit into the social landscape of America, and how our identities affect how we move through the world. Part Two will focus Research and Examination: Students will research EDI initiatives and strategies at US regional theaters as case studies to examine how stated EDI principles may (or may not) align with programming and institutional culture. In addition, local guest artists and practitioners whose work strongly aligns with social equity will visit the class for deep dive conversations about the work that they do, the challenges they face, and where they see the future of our field. Part Three will focus on Final Projects and the question What Now?: In small groups, students will apply what they have learned over the course of the semester to create an original exercise, workshop or governing policy that addresses a specific EDI concern in their community (institutional, local, national or international) to present to their classmates and invited faculty in the final weeks of the semester. Prerequisite: THEA 101, THEA 210, or by instructor permission. <em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></p> <p><strong>Generating Independent Theater</strong></p> <p>This interdisciplinary course will provide an opportunity for students to define their interests as performers/writers/producers and to develop original material, an artistic vision, and producing expertise that will lead to a realized performance. Individual skill sets and interests including storytelling, dance, character-work, visual art and music may each provide a jumping off point for this work. At the beginning of the course, a series of improvisational exercises, mini-performances and character studies, supported by readings on contemporary solo, immersive, experimental and environmental theater, will guide students to land on personal solo or two-person projects. In the second half of the semester, students will craft these pieces utilizing their peers as a think-tank. This generative, collaborative process will emphasize the importance of ensemble both onstage and behind the scenes during the creative and production process. To culminate their work, the class will be responsible for the production aspects necessary to present their pieces in a public performance on-campus. Prerequisite: THEA 210, THEA 330, THEA 380, or permission of instructor. </p> <p><strong>Autobiographical Performance: Laughing At Ourselves</strong></p> <p>In this course, participants will learn how to create compelling and humorous personal nonfiction narratives for the stage, studying classic narrative structure and paying close attention to theme &amp; detail. There is a long history of performers whose autobiographical solo work, like Crabb’s, simultaneously finds comedy in the tragedies of their lives while infusing the mundane with drama. To learn how to do this, students will study seminal storytellers and theater makers, (such as Spalding Gray, John Leguizamo, Whoopi Goldberg, Julia Sweeney, and others) who use their lives and experiences as templates for performance. Students will also review Moth-style storytelling to help find their own voice through a close examination of identity, self, and how we perform in the world. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1557,2022,2568,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-300','<div class="desc"> <p>This course analyzes the legal and policy framework for environmental protection and environmental justice. The course covers the major environmental statutes, applicable civil rights laws, and the next wave of climate change litigation. This course will also place environmental law and policy within the larger conversation around environmental protection and climate change.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1558,2022,2569,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-245','<div class="desc"> <p>This course focuses on the rhetoric of Black protest and social movements as we examine Black rhetorics as modes of resistance to racist, colonialist, patriarchal, and other forms of oppressive discourse and action. We will consider a range of rhetorical forms including abolitionist rhetoric and the Black Jeremiad in American culture; Civil Rights era rhetorics and the Black Panther Movement; anti-imperialist Black proletariat rhetorics of protest in the West Indies and Caribbean societies; and rhetorics of resistance in the contemporary Black Lives Matter movement. This course will provide a rhetorical understanding of the approaches and strategies emerging from and responding to systems of cultural and social oppression, and thus will offer a counterpoint to Eurocentric rhetorical traditions. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1559,2022,2570,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-246','<div class="desc"> <p>This interdisciplinary course introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. Taught in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1560,2022,2571,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-346','<div class="desc"> <p>This interdisciplinary course, featuring ancient Roman texts in the original Latin, introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. These topics will be examined through close readings in the original Latin drawn from Cato the Elder, Cicero, Livy, Vitruvius, and others.</p> </div>','LATN 201 (or equivalent) and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1561,2022,2582,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-268','<div class="desc"> <p>This course examines the Japanese woodblock print from its emergence in the mid-seventeenth century to the modern era. We will investigate topics such as technological innovations, changing habits of looking, censorship and resistance in the creation of popular culture, the role of prints as a medium of reportage and propaganda, Japonisme and the construction of Japanese art, and global exchanges of materials and ideas. By tracing the historical development of Japanese prints, we will examine how woodblock prints were reconceptualized from a popular medium of visual culture to a quintessential embodiment of Japanese aesthetic tradition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1562,2020,2583,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/blst-black-studies/100/blst-110','<div class="desc"> <p>This course introduces students to the history and methods of the discipline known as Black Studies. Readings will focus on the origins and institutionalization of Black Studies as a field of academic inquiry. Students will learn about movements that resulted in the field of Black Studies in the present, including the foundational academic work of W.E.B. DuBois, the San Francisco State student revolt of 1968, Mellon and Ford Foundation funding of programs and departments, and the recent student demands at University of Missouri and elsewhere. International movements, such as the Birmingham [UK] school of cultural studies and African independence movements, will also be considered.</p> </div>','n/a ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1563,2022,2584,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with, what is known as, the "LA Rebellion," a moment of a radical reconceptualization of filmmaking fostered by black students during their studies at the UCLA film school, and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasional devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include: <em>Selma</em>, <em>Fruitvale Station</em>, <em>Daughters of the Dust</em>, <em>Lemonade</em>, <em>Pariah</em>, <em>Bush Mama</em>, <em>Do the Right Thing</em>, and <em>An Oversimplification of Her Beauty.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1564,2022,2585,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-303','<div class="desc"> <p>This seminar course will look at a topic in neuroscience from a multidisciplinary perspective. The course will focus on critical analysis of research studies and methodologies. May be taken more than once for credit as the topics will differ each semester.</p> <p><strong>Deep Learning</strong></p> <p>This course will cover current topics at the intersection of cognitive neuroscience and deep learning. Recent successes in deep learning and AI have hinted that networks of simple units can produce surprisingly complex behaviors, and these models often even mirror the coding properties observed in the human brain. However, unlike artificial agents, humans excel at thinking creatively and reasoning about cause and effect, allowing us to behave flexibly in novel and ambiguous environments. What neural mechanisms support these behaviors? Which of these mechanisms are necessary for producing analogous capabilities in artificial agents? We will gain insight into these questions by reading primary literature and algorithm development exercises. Previous experience in cognitive science, computer science, psychology, logic, mathematics, or biology is required for success in this course.</p> </div>','COGS 201, BIO 268, PSYC 200, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1565,2022,2586,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-308','<div class="desc"> <p>In the second half of the 20th century, the new field of cognitive science came into existence. This course explores the developments in the history of philosophy, mathematics, biology, psychology, and computer science that culminated in this new science of the mind, including the theory of computation, from the work of Leibniz in the 17th century, the pioneering work on computing and programming by Charles Babbage and Ada Lovelace in the late 19th century, to Turing''s work in the early 20th century. We will explore how developments in both theoretical and applied computer science and logic led to the field of artificial intelligence and computational neuroscience, and we''ll explore the philosophical questions about the possibility and scope of machine intelligence. One prior course in cognitive science, philosophy, or mathematics is recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1566,2022,2587,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-186','<div class="desc"> <p>The course will explore the unique sense of tragedy and the tragic in Iranian literature and culture, tracing this fundamental attunement to the world from its Ancient Iranian roots to Ferdowsi’s 11th CE defining national epic — the Book of Kings — through the poetic and intellectual foundations of contemporary Iranian culture — the 13th-14th CE poetic work of Sa’adi and Hafez — and through to modern Iranian music and literature. The course will analyze the specific characteristics of Iranian tragic culture, closely attending to the developing expressions of that tradition in each of the works and eras covered by the course. The course will also take up the long, contested cultural and political history between Iran and, broadly, the West, focusing on the complex and mutually defining interactions between Iran and, first, Ancient Greece and, then, Europe and the US— both before and in the wake of Western imperialism. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1567,2022,2588,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-373','<div class="desc"> <p>Any large amount of data, such as that stored by Google or Facebook, requires specialized algorithms to ensure consistency and efficient access. From relational models and SQL to newer graph databases, students will understand how to represent entities a domain with rows in a database, culminating in a project that uses this knowledge in a real-world setting. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1568,2022,2589,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-258','<div class="desc"> <p>In many countries, the subject of LGBT (lesbian, gay, bisexual and transgender) rights has entered the political discourse with unprecedented speed and suddenness. For an issue that was most often relegated to the private sphere, the rapid global expansion of LGBT rights, as well as changes in public opinion toward LGBT people, has been nothing short of remarkable. This course is designed to gain leverage on the processes that explain such changes by surveying an eclectic literature on comparative and transnational LGBT politics: from social movements to normative change in international relations. For these fields of study, the changes addressed above pose several important questions. It is no coincidence, for example, that dozens of countries now grant some form of same-sex unions, and understanding transnational politics helps us understand why. Specially, we will ask: What factors have facilitated the mobilization of LGBT people? Why and how have public opinion and state laws towards LGBT people changed differently across various countries?</p> <p>To find answers to these questions, we will analyze the political history of a movement that has captured the world’s attention, and one that has moved a marginalized group from the political periphery to the center of public debate and contestation. We will take an in-depth empirical look at movements representing LGBT people and their successes/losses—as well as those of their opposition—across time and place. The first portion of the course will begin with the organized movement’s earliest roots in early 1900s Europe, followed by suppression during WWII, and then the homophile movement of the post-war period. The remainder of the course explores the public manifestation of LGBT identities that grew out of the Stonewall’s gay liberation politics, mobilization around the HIV crisis, and the domestic and international politics surrounding the spread of LGBT rights and recognition in contemporary times. An analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts offered by social movements and international relations scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1569,2022,2591,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-330','<div class="desc"> <p>A survey of poetry, prose, and drama from 1660-1730. Authors to be studied include Aphra Behn, Lady Mary Wortley Montagu, Daniel Defoe, and Jonathan Swift.</p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>','One 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1570,2022,2592,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-125','<div class="desc"> <p>In this course focused on European cultures, students will consider the Renaissance and Reformation, Science and Baroque Splendor, Enlightenment Reason and Revolution, Romanticism and Individualism, Industrial Revolution and New Social Thought, Modernism in Literature and the Arts, Global Influences, Cultural Pluralism, and Postmodern Culture. Students experience and critically evaluate texts and images from both historical and contemporary points of view.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1571,2022,2593,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-211','<div class="desc"> <p>From the Cold War to the War on Terror this course will examine the United States’ involvement in Afghanistan, Iraq and the Middle East since 1980. Among other things we will look at the connections between the events of 9/11 and the Iraq and Afghanistan wars. This class is an inquiry into the historical implications of these and other protracted US engagements from North Africa to Syria and from Somalia to Pakistan. Ultimately, we will use these events as a lens to pose a series of questions about empire, nation and national identity both in the US and in the Middle East.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1572,2022,2594,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-212','<div class="desc"> <p>With its capital in Europe since 1363 and spanning Europe, Asia and Africa for nearly five centuries the Ottoman Empire was perhaps the most successful and longest enduring experiment in multiculturalism the world has ever known. Multi-lingual, multi-ethnic and multi-religious Ottoman society and culture were comprised of Muslim, Byzantine Christian, Turkish, Greek, Persian, Mongol, Slavic, Armenian, Arab, African and Jewish cultural elements. Edicts from the Ottoman state were regularly issued in nine languages. One reason for its longevity was its willingness to draw on the diversity of this rich historical and cultural tableau. In this course, we will examine the complex social, cultural and political transformations occurring in the Ottoman Empire from its inception as a small principality in western Anatolia until it reached its zenith when it stretched into modern-day Austria.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1573,2020,2595,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-215','<div class="desc"> <p>This course examines the relationship between American law and American history from the European settlement of North America to the beginning of the 21st century. Examining legal institutions, legal processes, and legal culture over a long time span, the course offers insight into the changing relationship between power and the people in the United States. Because one semester is too brief a time to cover every subject in American legal and constitutional history, this course examines specific issues or episodes that demonstrate particularly well the close relationship between law and history. These include such topics as early witch trials, the laws of slavery, Native American dispossession, the evolution of marriage law, economic regulation, and the emergence of the right to privacy.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1575,2022,2597,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-348','<div class="desc"> <p>This course will look at the long 1960s in China and their relationship to and influence on the global 1960s. Beginning with the rise of Third-Worldism in the mid-1950s and ending in the 1970s, this period of radicalism reached its height with the tumultuous Cultural Revolution in China (1966-1969). Through memoirs, primary source material from the time, film, and secondary sources we will investigate why after years of political and economic consolidation the People’s Republic of China underwent such a dramatic and chaotic political upsurge. We will end the course by looking at the influence of China’s Cultural Revolution on the radical 1960s movements of the world, in particular in the United States and France and peasant movements in the third world.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1576,2022,2598,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-260','<div class="desc"> Through analyses of literature, film, music, and graphic art we will explore how Latinos have represented their individual and collective experiences in the United States. In order to allow some depth of comparison, primary attention will be given to the creative works of Chicanos in Los Angeles and Puerto Ricans in New York. However, other national origin communities (such as Dominican, Salvadoran, Guatemalan, and Cuban) will be selectively incorporated in the course. </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1577,2022,2599,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. To a lesser degree we will also examine Central American immigration from an international relations perspective.</p> </div>','LLAS 101, SOC 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1578,2022,2600,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-249','<div class="desc"> <p>This course explores techniques used for recording music in a studio and in live environments. Topics include commonly encountered acoustical problems and the equipment and techniques used to overcome them. Students develop knowledge of signal flow, mixing board operation, microphone choice and placement, preparing and managing recording sessions both in the studio and on-site (e.g., Herrick Chapel, Bird Studio, etc.), and delivering assets for the mix. Semi-weekly hands-on, guided set-up and operation of recording sessions of various sizes and ensembles help illustrate concepts and allow students to learn through experience. These experiences include recording single instrumentalists, vocalists, acoustic and electronic instruments, and on-campus student recitals and concerts. Instructor permission required.</p> </div>','MUSC 148 and MUSC 247 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1579,2022,2601,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/300/musc-358','<div class="desc"> <p>This course focuses on the technical and aesthetic aspects of composing and recording music for picture that use various synchronization methods (MIDI sequence, click track, SMPTE timecode). Students will compose and record up to three projects, combined with live players, and score short films created by Media Arts &amp; Culture majors for their Senior Comprehensive. May be repeated one time for credit.</p> </div>','MUSC 258 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1581,2022,2604,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-256','<div class="desc"> <p>Tibetan Buddhism is a globally recognized religion, with the Dalai Lama, red-robed monks, prayer flags, and prayer beads occupying a unique position in the popular imagination. These images, though, flatten the diversity and historical complexities both of the Buddhist traditions of Tibet and the spread of these traditions into surrounding regions of the Himalayas. This course will provide an overview of these traditions, exploring their trajectories of development and interactions with diverse communities, while also considering local differences and agency.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1582,2022,2605,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. We will also examine Central American immigration from an international relations perspective.</p> </div>','SOC 101 , SOC 102 , LLAS 101 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1583,2022,2606,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/span-spanish/300/span-325','<div class="desc"> <p>In this interdisciplinary course we will examine representative works of art and literature that are centered on the city of Madrid as a cultural, social, historical and intellectual space. We will discuss artistic and philosophical issues including, among others, the conception of space revolution in Diego Velázquez, the tensions of Enlightenment and Romanticism in Francisco de Goya, and the existential representation of life after the Spanish Civil War in Camilo José Cela. We will explore the interconnection of selected artistic and literary works with the purpose of approaching an understanding of the multilayered and fluid creation of the city’s identity.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1585,2022,2608,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/300/amst-376','<div class="desc"> <p>This interdisciplinary seminar will explore the contentious history of the public memory and representation of slavery, the Old South, and emancipation in the United States. Drawing upon a range of sources – including fiction, film, advertisements, tourist sites, and public monuments – we will examine the various ways that Americans have sought to commemorate, critique, and capitalize on the history of the nation’s “peculiar institution” from the late-nineteenth century to the present day. Throughout the semester, we will interrogate the contested politics of these popular representations, and we will assess the ways that African American writers, filmmakers, preservationists, and artists have sought to challenge and reframe longstanding Jim Crow-era representations of slavery, replacing them with new narratives informed both by historiographical paradigm shifts and the politics of the ongoing black freedom struggle. </p> </div>','One HIST course, or one BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1586,2020,2609,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/blst-black-studies/200/blst-240','<div class="desc"> <p>In the 1970''s, African-American women writers dominated the literary market. The novels and memoirs of Toni Morrison, Maya Angelou, and Alice Walker were read and praised widely. Though the 1970''s saw a surge in their popularity, African-American women had been writing since the nation''s inception, as exemplified by Phillis Wheatley''s 1773 volume of poems. Throughout its literary history, African-American women''s writing has reflected upon, and often challenged, assumptions about American identity and experience, racial justice, and gender and sexual norms. This course surveys the long history of this literature and focuses, especially, on texts that supply world views inflected by the particular experience of living as American, black, and female. Authors under consideration include those mentioned above, as well as June Jordan, Audre Lorde, Toni Cade Bambara, Sojourner Truth, Sonia Sanchez, Octavia Butler, and Evie Shockley.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1588,2022,2611,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1590,2022,2613,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1592,2022,2615,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-376','<div class="desc"> <p>This interdisciplinary seminar will explore the contentious history of the public memory and representation of slavery, the Old South, and emancipation in the United States. Drawing upon a range of sources – including fiction, film, advertisements, tourist sites, and public monuments – we will examine the various ways that Americans have sought to commemorate, critique, and capitalize on the history of the nation’s “peculiar institution” from the late-nineteenth century to the present day. Throughout the semester, we will interrogate the contested politics of these popular representations, and we will assess the ways that African American writers, filmmakers, preservationists, and artists have sought to challenge and reframe longstanding Jim Crow-era representations of slavery, replacing them with new narratives informed both by historiographical paradigm shifts and the politics of the ongoing black freedom struggle. </p> </div>','One HIST course, or one BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1595,2022,2618,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-313','<div class="desc"> <p>The key to the animation and videogame industries is the ability to display simulated worlds in real time. Starting with representing 3D space, this course will teach students the data structures and algorithms, such as quadtrees, texture mapping, and ray tracing, to create photorealistic images.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1600,2022,2623,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-257','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? When and how to movements spread and diffusion their ideas globally? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention in various moments of time, while developing the conceptual skills that provide an introduction to social movement theory. In doing so, we will take an in-depth empirical look at movements for civil rights, women’s rights, LGBT (lesbian, gay, bisexual and transgender) rights, and immigrant rights. An analysis of these movements across multiple domestic and transnational contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1603,2022,2626,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-321','<div class="desc"> <p>This course provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1604,2022,2627,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/geo-391','<div class="desc"> <p>This class serves as preparation for Senior Comprehensives in Geology. Topics include comps options, analysis and presentation of scientific data, literature searches and attribution of previous work. Students will develop a formal plan to complete their senior comprehensive requirement. Open only to junior Geology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1606,2022,2629,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-311','<div class="desc"> <p>Americans have long idealized the frontier as an untrammeled backcountry, a mythologized landscape of “cowboys and Indians”, prairie and homesteaders, ranchers and sodbusters. In this course, we will draw on colonial and postcolonial theory to reinterpret these stories in the historical context of a set of encounters involving the Americas and the Americans - native and immigrant, from Europe, Asia, and Africa - with the rest of the world, contacts that began in 1492 and are still going on today. In the process, we will explore a diverse array of borderlands between people, environments, mythologies, and histories - spaces of interaction and reinvention. But these borderland spaces are fragile; contact zones devolve, again and again, into conquest, domination, genocide, and empire. Although this is a transnational phenomenon, this course is primarily concerned with the frontier in North America and particularly in the American West and in California. Along the way, we will also be doing our own original archival research, so students will have a chance to make their own mark upon the long history of the American frontier experience. </p> </div>','HIST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1607,2022,2630,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-316','<div class="desc"> <p>When we think of the World War II era and its aftermath in Southern California, images of freeways, airy tract homes, and classic Hollywood glamour often jump to mind. If we look a bit deeper, the Zoot Suit Riots, the scandal of Chavez Ravine, the destruction of public transit, and other more complex, and often "noir" images might emerge. Yet beneath both sets of images lie a set of crucial social, demographic, and political changes that marked Los Angeles''s emergence as an industrial, as well as cultural, center - changes that put the city on the front lines of many struggles revolving around Civil Rights, housing, and the future of American urbanism itself. In this class, we will explore the sunshine and the noir of mid-twentieth century LA, focusing on the ways cultural forms (such as the Central Avenue Jazz Renaissance, film noir, and modern architecture) crystallize crucial postwar social and political battles within this complex modern metropolis.</p> <p>Basic knowledge of twentieth century U.S. History is strongly suggested, but may be waived in exceptional circumstances.</p> </div>','HIST 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1609,2022,2632,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-102','<div class="desc"> <p class="sc-BodyText">This course will examine the diverse forms and social contexts of Latin American and Caribbean music, while exploring the ways that musical performance has been used to negotiate power relations in the social, political, and economic spheres since the Conquest. Focusing on musical genres and movements from Argentina, Brazil, Cuba, Haiti, Mexico, Peru, and Trinidad students will learn to recognize the techniques and instruments used in a wide array of traditional and contemporary styles, particularly those which have grown out of the hybridization of African, Middle Eastern, European, Asian, and Native American performance strategies. While knowledge of music theory and performance skills are not necessary, it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1610,2022,2633,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1616,2022,2639,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing, especially, on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization; art forms; social structure; and religion in the colonial and modern periods; and considers native responses to contemporary issues, such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1619,2022,2642,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-252','<div class="desc"> <p>An introduction to the fundamentals of songwriting. In this course, students analyze the form, melody, and harmony of successful songs to determine what makes them effective, and apply this knowledge to the composing of their own songs. Most classes will consist of performing and work-shopping student work in the spirit of open critique.</p> </div>','MUSC 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1620,2022,2643,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-320','<div class="desc"> <p>Contemporary health issues often raise deep ethical and theoretical concerns. In this course, we seek to connect philosophical and theoretical work on social justice with contemporary issues in health, such as abortion, trans* health, disability rights, domestic violence, international inequities, and health disparities. As a key component of this course, students will partner with a community organization for a semester-long research project, identifying an issue of practical importance to that community and offering an original, theoretical analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1624,2022,2648,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/100/comp-146','<div class="desc"> <p>Comprehensive study of measures of central tendency, variation, probability, the normal distribution, sampling, estimation, confidence intervals, and hypothesis testing. Introduction to use of technology in statistics. Real-life problems are used to illustrate methods. Weekly lab. Not open to students who have completed or are currently enrolled in PSYC 201, BIO 368, MATH 150, or any Mathematics course above 200.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1625,2022,2649,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-213','<div class="desc"> <p>The course interrogates the assumptions underlying paid and unpaid labor with respect to "women''s work" as it intersects with race, class, sex, gender, and sexuality. Drawing on a socio-critical perspective, we examine the inequalities associated with reproductive labor, child care, housework, sex work, and the ''feminization'' of certain professions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1626,2022,2650,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-219','<div class="desc"> <p>This course examines the scope and impact of Title IX in educational settings from its passing in 1972 to the present day. Students will explore two main areas of sex-based violations: 1) sports and discrimination and 2) sexual harassment and sexual assault. Drawing on critical theory, students will research and interpret case studies involving Title IX violations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1627,2022,2651,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-352','<div class="desc"> <p>The logical foundation of the notion of a computable function underlying the workings of modern computers. Representation of the informal mathematical idea of calculability by canonical proxies: general recursive functions, Turing computable functions. Discussion of Church''s Thesis, which asserts the adequacy of these representations. Survey of decidable and undecidable problems. </p> <p>Sub-field: <strong>THEORY</strong></p> </div>','Math 210, COMP 149, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1628,2022,2652,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-187','<div class="desc"> <p>“The origins of the myth of Prometheus,” it has been said, “are unclear; even in antiquity the story is never told in full.” Right from the very beginning, then—so it would seem--Prometheus arrives on the scene of literature in a torn, dismembered condition, his story diffracted from the outset into a multiplicity of incoherent elements and perspectives: is he a mighty Titan, or merely a trickster? a divine benefactor, or a threat to cosmic peace? an embodiment of the power of thought, or a figure of its eternal helplessness and misery? The primary object of this course will be to survey some of the more impressive and surprising ways in which literature, art, and philosophy have engaged with, and contributed to, the prismatic strangeness of this myth of Prometheus--from the ancient songs of Hesiod and Aeschylus, to the Romantic soundings of Goethe, Shelley and Herman Melville’s <em>Moby Dick</em>; from its intellectual appropriation by Marx, Nietzsche, Heidegger and Freud, to its “plastic” rendering in the murals of Orozco, the statuary of Paul Manship, and the contemporary films of Ridley Scott and Alex Garland (director of <em>Ex Machina</em>). More tentatively, the larger goal of the class will be to consider whether the Prometheus myth in its entirety might not be guided by the reflection that absolute assertions of authority and power always imply their own undoing, and that sovereignty will forever be linked to suffering and to sorrow.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1629,2022,2653,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-107','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though very different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1630,2022,2654,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-307','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison. This course will meet three times a week. Twice with CSLC 107 with discussion conducted in English, and a third weekly meeting in which all readings and discussions will be conducted in German.</p> </div>','GERM 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1631,2022,2655,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-233','<div class="desc"> <p>The turn to authoritarianism and rise of fascism in Europe between the First and Second World Wars represented a profound turning point in European politics and society, as nations from Italy to Hungary, Germany, to Greece became home to fascist regimes or movements. This History course studies the rise, function, and fall of fascism , especially as it existed in Mussolini''s Italy and Hitler''s Germany, between 1922 and 1945. In the period between World War I and World War II, new and alternative models for the relationship between state and society challenged the existing political and social order, as many Europeans abandoned democracy as the ideal political system. Many turned to nationalist authoritarianism as the answer to the political, economic, and social crises shaking Europe. Italy, under the National Fascist Party, and Germany, ruled by the National Socialists, were the nations in which this flight from democracy became a full-fledged descent into dictatorship and one-Â­party rule. This course examines authoritarianism and dictatorship in interwar Europe and we assess how the elevation of the state and the nation, promoted by these regimes and parties, impacted the societies involved.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1632,2022,2670,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1633,2022,2671,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-360','<div class="desc"> <p>This course explores the relationship between art and women in East Asia from ancient times to the present. We will study the various ways in which women have been engaging with art—as producers, as patrons, and as objects or subjects of the gaze. At the same time, we will examine how women and gender have been conceived and contested in East Asia. Over the course of the semester, we will investigate topics such as women artists and patrons; Buddhist conceptions of the feminine and women’s devotional practices; performing “women” in theater; shifting ideals of beauty and the alteration of women’s bodies; and the representation of gender in contemporary popular culture. Ultimately, students will develop critical tools for examining how women have been represented in visual culture and how they have exerted their own artistic agency in East Asia. </p> </div>','Any Art History course, East Asian Studies course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1634,2022,2672,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-373l','<div class="desc"> <p>Laboratory workshops for Computational Biology (BIO 373). Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 373 ',NULL);
INSERT INTO course_descriptions VALUES(1635,2022,2674,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cogs-cognitive-science/300/cogs-390','<div class="desc"> <p>A recent replication crisis in the sciences has led to large-scale questioning centered on scientific integrity. Scientific integrity refers to 1) honesty while conducting and interpreting research, and 2) to developing conclusions that are unbiased and valid. Contemporary practices in research design and statistical analysis (e.g. p-hacking), lack of transparency, and political bias are all threats to scientific integrity. This course introduces and engages students conducting directed research with a faculty member in the Cognitive Science Department in best practices and ethical concerns in scientific research through evaluating primary research and commentaries within cognitive science and statistics, as well as by evaluating and critiquing the literature in their area of research focus. Students are expected to commit to a minimum of 8 hours of course-work each week including a course meeting, assigned group work, readings, and independent research.</p> </div>','COGS 101, COGS 201, and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1636,2022,2675,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-295','<div class="desc"> <p>Topics vary semester to semester. The object of any of the courses in the series entitled “Hear Now” is to introduce students to the transformative effect that contemporary artists and thinkers can have on the way we think about our world-- its past, its present its future. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Hear Now: Jean Luc Nancy and the Aesthetics of Community</strong></p> <p>In this class, we shall be examining the work of one the world’s most important living philosophers, Jean Luc Nancy. Special emphasis will be placed on the close relation Nancy seeks to draw between our so-called “private” aesthetic experiences—the painting that arrests us, the bar of melody that makes us tremble, the line of poetry that haunts us—and our sense of “being in community” (the sense, that is, that our supposedly singular existence is always already plural, is always already shared out with others). Beyond the reading of Nancy’s own works, we shall also be looking at the work of some of his most important predecessors on the question of art’s relation to the community (Kant, Hegel, Benjamin, Adorno), as well as the works of those thinkers who have engaged most directly with his ideas (Derrida, Agamben, Esposito), and those who have explicitly sought to oppose him (Ranciere, Badiou, and others). </p> </div>','CSLC 200, or CSLC 283, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1637,2022,2676,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-306','<div class="desc"> <p>This course builds on ECON 272 to cover advanced topics in econometrics including: panel data, binary response models and causal inference. Theoretical models of regression and empirical coding will both be emphasized. </p> </div>','ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1638,2022,2677,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-191','<div class="desc"> <p style="margin-left:0in; margin-right:0in">This course traces the theory and practice of revolution in modern history. The course begins with a brief overview of revolutionary theories and transformations within a global historical context. We then turn to the Scientific Revolution and the Enlightenment as the paradigm shifts which brought a revolution in thought and subjectivity in Europe. From there we focus on the French Revolution, following its legacy and impact through the revolutions of the 19<sup>th</sup> century, the rise of Socialism and Communism, the Russian Revolution, the Chinese Revolution, decolonization and revolutions in Africa, and the Cuban Revolution. The course looks closely at how these revolutions in thought and politics changed the way people understood their relationship to state and society. In the search for global connectivity, we review revolutionary movements beyond the western European and United States to include cultures and civilizations of Asia, the Middle East, Africa and the Americas. We will ask a number of questions related to revolutionary change, including: what causes revolutions? Who makes a revolution? What leads to success or failure in a revolutionary situation?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1639,2022,2678,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-245','<div class="desc"> <p>This practice based course focuses on a specific topic in media production. Students will explore the propensities and challenges of a particular production approach, model, technology, or aesthetic practice through the creation of a series of media projects. Classes will include screenings, readings, and discussion that situate these practices conceptually, ethically, and culturally but the emphasis is on hands-on project creation as a means of understanding the production topic at hand.</p> <p><strong>Documentary Animation</strong></p> <p>A hands-on course in the fundamentals of animated media production examined through the lens of the history, techniques, and methods of documentary animation. What realities might be uniquely explored or represented using varying modes of animation, either as part of a larger documentary project or as the entire project itself? Students will explore creative strategies for designing form and content across experimental, abstract, and character based approaches. A series of collaborative, hands-on media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops. Recommended (though not required): MAC 110 and MAC 210.</p> <p><strong>Process-Based Mediamaking</strong></p> <p>A hands-on media production course in which the final result of each project is, to some extent, outside of the creator’s control. The vast majority of traditional film and television is intentionally scripted or planned in advance and the production/filmmaking process is focused on capturing images and sound that perfectly execute that script or plan. Process-Based Mediamaking is an alternative to this system. It is rooted in the idea of developing a process, methodology, or set of rules ahead of time and then letting that open-ended, exploratory, and in some cases even random, approach generate media art. This course will consider historical and current examples of Process-Based mediamaking but the main emphasis of the course is the creation of this kind of media. No prior mediamaking experience is required.</p> <p><strong>Exploring 360º Video and Immersive Installations</strong></p> <p>Do 360 video cameras, VR headsets, and immersive screen installations represent a paradigmatic change in production, artistic conception, and audience experience? This course will introduce students to the foundational methods, technology, aesthetic approaches, and cultural and ethical considerations of live-action immersive media creation for both VR headsets and video installations. Students will work in a collaborative environment to conceive and execute a series of projects using 360 video cameras and traditional digital video cameras. Projects will include narrative, documentary, and experimental approaches. Students will be encouraged to investigate how live-action 360 video and immersive installations differ from, and are aligned with, traditional screen-based media. No previous filmmaking experience is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1640,2022,2679,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/100/phil-150','<div class="desc"> <p>This course introduces students to symbolic models of the structure of arguments, and to tools for representing those structures and evaluating them as patterns of good or bad arguments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1641,2022,2680,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-222','<div class="desc"> <p>This course will explore the relation between knowledge and power, focusing on epistemic dimensions of racial and gender oppression. The course will address the following questions: (1) How does propaganda operate, and what sort of threat does it pose to equality in the United States? (2) How do ideologies entrench privilege and injustice, and how can we counteract false beliefs that persist in the face of strong opposing evidence? (3) Is there a distinctively epistemic form of injustice, and, if so, what does this form of injustice look like? The authors that will be discussed may include Michel Foucault, Miranda Fricker, Sally Haslanger, José Medina, Tommie Shelby, and Jason Stanley.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1642,2022,2681,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-344','<div class="desc"> <p>What is a language? And what is it to know, to speak, or to understand a language? This class will investigate the project of developing a systematic and comprehensive theory of linguistic meaning: what resources such a theory requires, what kinds of claims it makes, and what consequences it has. We will proceed by examining philosophical questions about the role translation between languages plays in a theory of meaning, about the nature of linguistic reference to the world, and about whether the notions of language and meaning are ultimately coherent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1643,2022,2682,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-361','<div class="desc"> <p>Philosophical wondering begins in childhood: Where do words come from? Can trees think? What is love? At the heart of this course, Occidental students will have the opportunity to teach philosophy to elementary students at a local school. Doing so provides both an opportunity to serve the local community, an opportunity to reconnect with our own philosophical impulses, and a chance to reflect deeply on a variety of philosophical topics (such as friendship, courage, minds, justice). Occidental students will develop and teach their own lesson plans. In order to do so, students will select a children’s picture book, identify a philosophical question raised by the book, review and selectively incorporate academic philosophical texts. In addition, the class will discuss philosophical views on young children, the nature of philosophical wonder/inquiry, and the value of a (philosophical) education, e.g. Rousseau''s Emile, excerpts from Plato, Marx, and contemporary philosophers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1648,2022,2689,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-190','<div class="desc"> <p>This course will take a historical look at the emergence and development of capitalism from the 16<sup>th</sup> century to the present. The course stresses capitalism’s global spread and interaction with other historical forces such as commercialization, urbanization, colonialism and imperialism, environmental and climate change, inequality, and social and economic instability. We will look at the emergence of various schools of thought on capitalism, such as Keynesianism, Marxism, liberalism, the Austrian School and its offshoots, and neoliberalism. We will end with a discussion on the future of capitalism, considering globalization, the rise of China, economic crisis, and the rise of nationalist and populist responses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1649,2022,2690,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/300/hist-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1651,2022,2692,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1652,2022,2693,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-211','<div class="desc"> <p>This course will explore how central figures in the history of moral philosophy grapple with fundamental questions, such as: What is the best life for a human being? Should I be good? Can I be good? What are our obligations to others, both friends and strangers? Philosophers covered will include Plato, Aristotle, Kant, Mill, and Nietzsche.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1653,2022,2695,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-233','<div class="desc"> <p>This course is an introduction to the methods of ethics developed for addressing moral issues in the practice of health care and research. Methods addressed will include: professional ethics (practice standards and professional norms), casuistry, the principles of biomedical ethics, applied normative theory, feminist bioethics, and narrative ethics. We will use these methods to address a host of topics of concern to those participating in health care institutions either (directly) as providers or (somewhat less directly) as policy makers. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1654,2022,2696,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-243','<div class="desc"> <p>This course will explore the relationships between the ways we describe the world and the nature of the world we describe. We will explore such questions as: Do different languages describe the world differently? Do different descriptions of the world correspond to different conceptions of it? Is the world a different place for those with different understandings of it? Could the world be other than it is, and how do we talk about these alternative possibilities? Are there limits to what we can express, and how do those limits correspond to the limits of what there is?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1655,2022,2697,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-342','<div class="desc"> <p>This course will examine: (1) the theories of knowledge of such philosophers as Price Russell and Chisholm ("Foundationalists"), (2) some of their critics such as Sellars and Quine, and (3) recent work in naturalized epistemology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1656,2022,2698,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Philosophy of Food </strong></p> <p>The aim of this course is to demonstrate that food is worthy of philosophy inquiry. We will start with the deceptively simple question, what is food and why is it important? We will quickly move on to specific questions concerning the aesthetic value of food (can food be a work of art?), the nature of food criticism (who am I to tell you what you should like to eat?), a cluster of ethical questions concerning the production and consumption of food (e.g., what exactly is wrong with GMO?, what’s the connection between patriarchy and eating meat?, isn’t ethics fundamentally a question about hospitality?), and broad questions about food and cultural identity (what exactly does “authentic Mexican” mean?). Like any good philosophy course, the point is not to flatter your taste, but to change it, which we will do by cooking together and talking to a number of local food writers and philosophers.</p> <p><em>This course will count towards the Experiential Learning</em> <em>requirement for the Philosophy major.</em></p> </div>','One course in philosophy. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1657,2022,2699,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-259','<div class="desc"> <p>Students will use the United States and Brazil as sites of comparison through which to understand the various relationships between religion and race in the Americas. In both places we will ask: Where can we find African religion in the Americas? How have religious practitioners, scholars, and even entertainers decided what is "authentically African," and to what ends? And how has religion - and the social scientific study of it - served as an arena for negotiating racial and ethnic difference? By the end of the class, students will emerge with an understanding of different black religious traditions across the Americas - ranging from black Islam and Christianity in the U.S., to transnational Santeria, to Brazilian Candomble and Umbanda- as well as what is at stake in defining a category like "black religion." Students will understand how scholars have studied these traditions over time and how practitioners and scholars'' notions notions of black religion have shaped contemporary understandings of race and ethnicity in the Americas. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1658,2022,2700,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/100/soc-102','<div class="desc"> <p>This course adopts a global perspective to introduce students to sociology, the scientific study of societies. It will examine the self, socialization, social ties, social interaction, social institutions, and social change, considering both conformity and deviance. Students will leave with a "sociological imagination," the ability to see their own lives and the lives of others in the context of their wider societies and an increasingly interconnected world. Open only to frosh and sophomores, or by permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1659,2022,2701,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-112','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes from the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1660,2022,2702,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-150','<div class="desc"> <p><em>The Literary Mind and the Carving of Dragons</em> is a highly influential work on Chinese literary aesthetics, and its title also suggests two important constituents of the literary composition process by pre-modern Chinese authors: ideas and craftsmanship. By providing an introduction to classical Chinese literature through readings in translation, this course will integrate aesthetic appreciations and cultural understandings of the classical Chinese literature, and help students grasp the conceptions, styles and creative skills of different Chinese authors. The time range will cover the period from <em>The Classic of Poetry (Shijing) </em>through the Qing dynasty. Throughout the course, students will have a basic historical knowledge of the Chinese literary tradition, as well as a sense of how to go about interpreting Chinese literary texts. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1661,2022,2703,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-375','<div class="desc"> <p>This course focuses on key themes and topics of Indigenous Feminisms. In particular, we will discuss how gender, sexuality, land, and sovereignty intersect in different Native communities. We ask: How do female, queer, two-spirit, gender non-conforming, and feminist Indigenous peoples persist, resist, and thrive in the face of ongoing colonial violence and erasure? How does settler colonialism intersect with heteropatriarchy, necessitating an intersectional decolonial analysis and response? In what ways does the protection/empowerment of Native women correspond to the preservation/respect of Native land? How can an Indigenous feminist epistemology change our conceptualizations of land, water, and spatiality? What does an Indigenous queer critique contribute to analyses of militarism, imperialism, and settler colonialism? </p> <p>Case studies and examples are drawn from Turtle Island (North American continent), the Pacific Islands, and Palestine. Authors to be discussed include Mishuana Goeman, Audra Simpson, Haunani-Kay Trask, and Kim TallBear.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1662,2022,2704,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-376','<div class="desc"> <p>This course will engage major concepts, theories, and intellectual inquiries in the area of settler colonial studies. We will ask: what makes settler colonialism distinct from other forms of colonialism? How does settler colonialism intersect with other systems of oppression, such as heteropatriarchy, chattel slavery, and racial capitalism? We begin by defining settler colonialism as the systematic dispossession and elimination of Native peoples via genocide, land appropriation, settler immigration, and/or cultural assimilation. We will then explore the relationships between settler colonial studies and queer theory, Afro-pessimism, and Asian diasporic studies. Authors to be discussed include Patrick Wolfe, Lorenzo Veracini, Jodi Byrd, Mark Rifkin, Jared Sexton, Frank B. Wilderson III, Ikuko Asaka, Iyko Day, Dean Saranillio, and Manu Karuka. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1663,2022,2705,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-312','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes From the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor. In addition to the English section, this course will meet for an additional session per week to read the and discuss the German language and other supplementary texts in their original. Readings will occur in German and will serve as an introduction to the major developments of the German language from Middle High German to the advent of High German in the writings of Martin Luther to its modern iterations in Hermann Hesse. Authors will include among others, Meister Eckhart, Martin Luther, Franz Kafka, and Hermann Hesse while discussion will occur in English and German and focus on the intricacies of the original language text and developing arguments out of it. </p> </div>','German 202 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1664,2022,2706,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-382','<div class="desc"> <p>In this course we will trace one historic trajectory of what we today call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the Gospels of Christianity, the troubled Confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the Divine Comedy. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring and frustrating complexity.</p> <p>Taught in conjunction with CSLC 182, but meeting for an additional section, Latin 382 will allow students to encounter a number of Roman poets (Catullus, Horace, Tibullus, Ovid, Propertius) and writers (St. Augustine in particular) in their original language forms.</p> </div>','Latin 201, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1665,2022,2707,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-109','<div class="desc"> <p>Basic keyboard technique at the beginning through lower intermediate level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1666,2022,2708,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-264','<div class="desc"> <p>While attempts to theorize a coming-together of all of the arts to create a unified artwork date to the eighteenth century, it is in the nineteenth century that the notion of a total artwork—in German, a <em>Gesamtkunstwerk</em>—gathers steam, famously in the writings of Richard Wagner, who sees in the total artwork the “artwork of the future” (the title of one of his most famous essays). This course examines the evolution of this concept within and beyond the Wagnerian context, from its prehistory in eighteenth-century theories of beauty and taste, to sound film and music videos, to contemporary Los Angeles dining experiences (such as at Craig Thornton’s Wolvesmouth and Jordan Kahn’s Vespertine) that pick up where Wagner’s theories left off. To chart this history will require us to consider theater, music, dance, painting, architecture, philosophy, film, and gastronomy. Throughout we will investigate the roles that attentiveness and perception play in these multi-sensory events, and consider how European thought and practices migrate and get translated to a contemporary, North American context. Guest lectures by artists and restaurateurs will be supplemented by field trips to Los Angeles arts and dining venues. No previous musical experience required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1668,2022,2711,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-331','<div class="desc"> <p>The wealth of textual information online and elsewhere makes the ability for computers to understand and generate text particularly valuable. This course will explore both the traditional, linguistic approach to understanding language, as well as modern information retrieval and statistical big data approaches. Topics include information retrieval, search engines, parsing, Markov models, and knowledge representation.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1669,2020,2712,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/comp-computer-science/300/comp-371','<div class="desc"> <p>Smartphone apps, in their limited computational power and radically different form factor, impose new constraints and challenges different from the development of other software. In this class, students will be introduced to mobile architecture and related concepts such as monetization, privacy, analytics, and cross-platform development.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 and COMP 229, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1670,2022,2713,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-389','<div class="desc"> <p>Security on the internet is fundamentally based on the mathematical properties of the algorithms we use to encrypt our data. This course teaches students the theory behind these algorithms and how future advances such as quantum computing may affect current standards of security and privacy. Topics include ciphers and frequency analysis, private and public key cryptography, randomness, and quantum cryptography.</p> <p>Sub-field: <strong>SECURITY</strong></p> </div>','COMP 149 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1671,2020,2722,'https://oxy.smartcatalogiq.com/en/2019-2020/catalog/course-descriptions/hist-history/200/hist-257','<div class="desc"> <p>A systematic examination of the history of anti-Semitism, beginning with the emergence of anti-Judaism in late antiquity, its transformation into theological anti-Semitism in the Middle Ages, and a racialized anti-Semitism in the modern world. In each period, students will investigate the socio-political contexts that gave rise to the fear of, hatred toward, and attacks on Jewish individuals and communities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1672,2022,2723,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/core-core-program/courses/core-98','<div class="desc"> <p></p> <p>This course is designed to expose students to some of the many cultures of Los Angeles, a vibrant microcosm of the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one semester unit of credit for participating in eight off-campus "field experiences.” Students will select these from a list of destinations provided by the course instructor and are responsible for documenting each field experiences using Moodle. Students will be required to submit at least two short response papers related to their field experiences.</p> <p>This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> <p>Students may take this course twice, for a maximum of two units being applied toward the degree.</p> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1673,2022,2724,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/core-core-program/courses/core-99','<div class="desc"> <p>This course is designed to expose students to the diverse array of artistic events that are held each semester on the Occidental campus—from musical and theatrical performances to art openings and film screenings and more. To receive credit, students must engage with at least eight (8) arts events during the course of the semester and complete two short reflection papers. Students will select these events from a list available on the course’s Moodle page. This course is graded CR/NC and does not fulfill any major, minor, or Core requirements. Students may take this course twice, for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1674,2022,2725,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-215','<div class="desc"> <p>This course critically examines the history of the education of Africans in the United States, beginning at the Middle Passage, through Reconstruction and the post-bellum South, to contemporary post-industrial urban contexts. Emphasizing the sociohistorical and political-economic dimensions of schooling African Americans, the course explores the role of key factors in shaping the academic "success" and "failure" of Black students historically and in current K-16 contexts. Analysis of case law policy and practice will inform our understanding of African American experiences in schools nationally and locally. Further, we consider the implications these experiences hold for democratic participation and the overall life chances of African American citizens.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1675,2022,2726,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-259','<div class="desc"> <p>Students will use the United States and Brazil as sites of comparison through which to understand the various relationships between religion and race in the Americas. In both places we will ask: Where can we find African religion in the Americas? How have religious practitioners, scholars, and even entertainers decided what is "authentically African," and to what ends? And how has religion - and the social scientific study of it - served as an arena for negotiating racial and ethnic difference? By the end of the class, students will emerge with an understanding of different black religious traditions across the Americas - ranging from black Islam and Christianity in the U.S., to transnational Santeria, to Brazilian Candomble and Umbanda- as well as what is at stake in defining a category like "black religion." Students will understand how scholars have studied these traditions over time and how practitioners and scholars'' notions notions of black religion have shaped contemporary understandings of race and ethnicity in the Americas. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1676,2022,2727,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-312','<div class="desc"> <p>The circulation of labor goods people and cultures between Africa Europe and the Americas created an Atlantic World whose history transcends continental and national boundaries. This course examines the relationship between race rights and revolution during the Atlantic Age of Revolution that stretched from roughly the mid-eighteen to mid-nineteenth centuries. In particular we will explore how Revolutions in British North America France and Haiti influenced the movement to end the slave trade and slavery in the Americas and galvanized slave revolts and other movements for Black liberation and human rights around the Atlantic World. A variety of readings including autobiography social and political history and ethnography will illuminate not only the history of the Atlantic World but new forms of scholarly writing that break the mold of national historical narratives. Themes include: slavery slave revolt the discourse of human rights resistance religion labor and shifting ideologies of difference in particular gender class and race.</p> </div>','One History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1677,2022,2728,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/core-core-program/courses/core-96','<div class="desc"> <p>This course is designed to expose students to mathematics and science to broaden their awareness of the research questions asked in these disciplines and to introduce skills and ideas scientifically shown to improve persistence in college especially in science and math majors. Students may acquire one semester unit of credit for attending eight on-campus events during a semester. Certain seminars and class meetings will be mandatory; students will select additional events from a list of events provided each year by the instructor. A short two-page paper is due on the last day of class. This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1678,2022,2729,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/100/arts-100','<div class="desc"> <p>The Oxy Arts Collaborate Workshop will bring a teaching artist, Oxy students, and youth from the neighboring Highland Park school district together in creative collaboration. <em>Permission of Director of Oxy Arts required.</em></p> <p><strong>Middle School</strong></p> <p>During the first six weeks of the semester, Oxy students will learn core arts education and public engagement pedagogy. They will work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop curriculum for an original after school art workshop. In the following 6 weeks of the semester, Oxy students will collaboratively their workshops for local middle school youth, culminating in a final public presentation. This course is an eligibility requirement to apply for a paid position through Oxy Arts to lead after school art classes on-site at local Highland Park elementary schools starting in the Spring semester. You are required to submit an application to register for this class. Applications are due at noon on Friday, March 26th. You will be notified if you''re accepted into the course before registration week. </p> <p>Apply here: https://forms.gle/vPRUgzRbCNZhc8kk6</p> <p><strong>Elementary School</strong></p> <p>During the first six weeks of the semester, Oxy students will learn core arts education and public engagement pedagogy. They will work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop curriculum for an original after school art workshop. In the following 6 weeks of the semester, Oxy students will collaboratively their workshops for local 4+5th graders, culminating in a final public presentation. This course is an eligibility requirement to apply for a paid position through Oxy Arts to lead after school art classes on-site at local Highland Park elementary schools starting in the Spring semester. You are required to submit an application to register for this class. Applications are due at noon on Friday, March 26th. You will be notified if you''re accepted into the course before registration week.</p> <p>Apply here: https://forms.gle/vPRUgzRbCNZhc8kk6</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1679,2022,2730,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bosp-barack-obama-scholars-program/200/bosp-200','<div class="desc"> <p>The aim of the Obama Scholars Program Seminar is to help Obama Scholars and Fellow develop and pursue their own conception of the public good, with the guidance of a faculty mentor and the support of members of their cohort. Participation in the seminar involves discussing selected texts and films; attending public lectures and other events; meeting with people at Oxy and beyond who serve the public good in various ways; and, in some cases, participating in community engagement projects. Permission of instructor required.</p> <p>This seminar is open only to Scholars and Fellows in the Obama Scholars Program. Students may repeat the seminar for credit, as long as they remain Obama Scholars or Fellows. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1680,2022,2731,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1681,2020,2732,'http://oxy.smartcatalogiq.com/en/2019-2020/Catalog/Course-Descriptions/BLST-Black-Studies/100/BLST-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1682,2022,2733,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-277','<div class="desc"> <p>This course explores the history of women as promoters of community health in the nineteenth- and twentieth-century United States. Although women have not traditionally held power in mainstream biomedical occupations and institutions, women have nevertheless been critical to health and healing in local communities as caregivers, activists, and practitioners. At times, working class women and women of color have also been demonized as carriers of contagion or even romanticized as repositories of traditional wisdom. Furthermore, women’s roles in community health have been heavily shaped by gendered and racial constructions of the body, disease, and wellbeing. Thus, while the focus of the course is on the social history of women’s health and healing, the theoretical framework of the course also aims to explore how ideologies of gender, race, class, and sexuality shape women’s relationship to community health as both caregivers and health-seekers. The course is organized by a set of common themes that cut across time, space, and racial/ethnic boundaries in U.S. History. Themes include: spirituality and healing; work and health; sexuality and reproduction; activism for health justice. An important goal of this course is to make connections between historical studies of women and health and present-day community health activism. Much of the course and especially the community partnership component focuses on the leadership of women of color in shaping agendas for community well-being. In the past, course participants have worked with the organizations Black Women for Wellness, California Latinas for Reproductive Justice, Visión y Compromiso, and Promesa Boyle Heights. We will continue to work this year with women’s health organizations and the Southern California Library on a Reproductive Justice community partnership. In addition, we will welcome several community health activists &amp; scholars to the class as guest speakers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1683,2022,2734,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-320','<div class="desc"> <p>Critical Race Theory (CRT) is a historic movement among legal scholars of color in the U.S. that has enjoyed widespread application in a number of disciplines, including Education. This course introduces students to CRT through a close reading of the key writings that formed the movement. We will examine the application of CRT in education, research, theory, and practice, contextualized in a variety of settings, including schools, community-based organizations, and other relevant spaces. Specific attention will be paid to the CRT methodology of counter-storytelling and its utility in centering the experiential knowledge of people of color in education.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1684,2022,2735,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-115','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus, by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1685,2022,2736,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-247','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1686,2022,2737,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/200/comp-277','<div class="desc"> <p>Video games are one of the newest forms of media, and offer tremendous promise for both entertainment, storytelling, and education. Starting from the text-based adventures of the 1970s to the billion-dollar industry today, students will learn how to use psychology and game mechanics to create compelling narratives, as well as gaining a glimpse into large-scale software development.</p> </div>','COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1687,2022,2738,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-100','<div class="desc"> <p>This course introduces critical theory in the context of the problem of social justice. Introductions will be made to psychoanalytic, Marxist, feminist, structuralist, deconstructive, and postcolonial criticism. Reader-responses; New criticism; lesbian, gay, and queer criticism, will also be surveyed. There will be close readings of the work of Louis Althusser, Georges Bataille, Michel Foucault, and Jacques Derrida, as well as in depth readings of essays by Guy Hocquenghem, Julia Kristeva, and Trinh T. Minh-ha.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1688,2022,2739,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-345','<div class="desc"> <p>This course will examine the transformation of states, nations, and identity in the contemporary period. Special focus will be given to how transnational developments (in politics, economics, and culture) are redefining modern societies, particularly as the number of democracies has increased worldwide over the last thirty years. The course will also grapple with the challenges and dilemmas of current states. Democratization does not mean democracies are here to stay—as such the course will discuss de-democratization, democratic backsliding, illiberalism, and populism to understand how everyday individuals are affected. In doing so, the class reflects on the experiences of formerly marginalized populations—including women, poor, and the indigenous—by considering the role of states and international organizations in the lives of everyday individuals. Only open to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1689,2022,2740,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-329','<div class="desc"> <p>Despite a widespread desire to provide equality of opportunity to all people in the United States, family background has an enormous effect on the way children grow up and the opportunities available to them in adulthood. Family income can explain more than a third of a child’s future adult income, and all aspects of family background can explain half to two thirds of a child’s future income, education, and wealth. In this class, we will explore economic theories and evidence explaining the inheritance of advantage, with a particular emphasis on understanding the role of the family, the role of neighborhoods and communities, and the role of discrimination. We will also discuss the role of public policy in increasing intergenerational mobility and reducing social and economic disadvantages, both in the United States and around the world.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1690,2022,2741,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/educ-education/200/educ-220','<div class="desc"> <p>The United States has the highest incarceration rate in the world. Schools, despite their role in nurturing the academic growth and development of students, are increasingly becoming sites of criminalization for marginalized children and youth. This raises fundamental questions about the relationship between schools and the carceral state, as well as about the complicity of schools and their officials in the production of prisoners. In this course, students will explore the social, historical and political-economic factors that have contributed to the development, growth and sustenance of the "school-to-prison pipeline." Through an examination of a wide range of texts and sources that sit at the intersection of K-12 schooling, criminal justice, social welfare, and community-based organizing and activism, students will be prepared to critically interrogate educational policies, practices and other structures of schooling that buttress and deconstruct this phenomenon. Sophomore standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1691,2022,2742,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/100/engl-140','<div class="desc"> <p>This class will examine the literature and culture of the Victorian period, from the 1830s to the turn of the twentieth century. We will read classic Victorian novels such as<em> Silas Marner</em>, <em>Great Expectations</em>, and <em>Jane Eyre</em> alongside more contemporary literary and cinematic interlocutors including <em>Wide Sargasso Sea</em>, <em>Thugs of Hindostan</em>, and <em>Victoria and Abdul</em>. In thinking about the period’s lasting impact on our own society, we will consider the broader historical context of imperialism, urbanization, and industrialization, all of which expanded dramatically during the Victorian era. We will also examine the shifting social and legal structures of the era, addressing issues of class, sexuality, and race.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1692,2022,2743,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-246','<div class="desc"> <p>This course applies acoustics, electronics, and digital audio theory in the assembly and operation of Public Address (PA) systems for live concerts. We cover the practice of live sound engineering in different contexts, with a focus on skill building in the technical aspects of live music. Students will assemble PA systems and operate a front of house mixing console for a host of music events both on and off campus. Students will also learn how to set up microphones, use a graphic equalizer to tune a PA system, and run individualized monitor mixes during live performances. Lessons about the theory and practice of live sound will be presented alongside practicum exercises in live engineering, culminating with running tech for several concert-length live performances. Live recording in a DAW-based multi-track session will also be a component in the later portion of the semester.</p> </div>','MUSC 148 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1693,2022,2744,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1694,2022,2745,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-243','<div class="desc"> <p>The confluence of three religious faiths in one land—Christian, Jewish, and Muslim communities in the Iberian Peninsula—was a unique situation in Western Europe during the Middle Ages (415-1492 CE). In this course, we will pay special attention to the interaction of these religious communities, their conflict and their cooperation. Students will develop a sophisticated understanding of the cultural and religious settings that gave rise to religious pluralism, and students will become familiar with some of the most important debates about religion – especially ideologies of tolerance and persecution – that have continued to fuel inter-faith relations into the twenty-first century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1695,2022,2746,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-253','<div class="desc"> <p>Comets, earthquakes, volcanic eruptions. In the early modern world, natural phenomena like these were read as portents or omens, exhibiting sympathies between the natural and supernatural. Set within a period of war, famine, and political instability, these natural disasters generated intense scholarly investigation—by philosophers, religious scholars, and scientists—contributing to the early development of the natural sciences. In this course, we will examine the scientific and religious debates about the causes of these natural phenomena, as well as the range of cultural responses to dealing with natural traumas. We will assess the role of the “natural” in the history of religion and understand the development of scientific authority for interpreting natural phenomena in early modern Europe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1696,2022,2747,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers: Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1697,2022,2748,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-252','<div class="desc"> <p>This course will focus on two foundational texts of Chinese civilization: The <em>Analects </em>and the <em>Zhuangzi</em>. The <em>Analects</em> is an ancient Chinese book composed of a collection of sayings attributed to Confucius and his disciples, and is traditionally regarded as one of the central texts of Confucianism. <em>Zhuangzi</em>, named for its traditional author, “Master Zhuang” (Zhuangzi), is one of the most important Daoist writings. When the <em>Analects</em> emphasizes that people should reconcile their desires via rituals, and fulfill moral and personal duties in order to ensure the welfare of the society, <em>Zhuangzi</em> promotes carefree wandering and following one’s own nature. By reading and comparing these two texts, this course will help students understand and grasp their central concerns, philosophies, and substantial influences on Chinese and East Asian thought and values throughout history. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1698,2022,2749,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-270','<div class="desc"> <p>This course will explore the psychology and biopolitics of sexual behavior in literature and film. The first unit, the couch, focuses on psychological theories of sexuality based on works by Freud, Foucault, Lacan, and Derrida. The second unit, the court, explores the biopolitical demands and legal consequences of acting out our sexual impulses. This unit, with texts by Agamben and Esposito, traces the dehumanization, exploitation, and control of the body in authoritarian regimes. The third unit, the confessional, discusses the reproductive bias of spiritual or religious systems and the prohibition of sexual expression. This unit presents films with scenes or plots illustrating the struggle between body and mind. The three units together will ask how sexual impulses disrupt a given socio-political order. Students will evaluate the solutions to disruption offered by psychology (compromise), the court (crime and punishment according to a given society''s laws), and religion (confessing sex acts to a religious official who will condemn them, impose penance, and absolve the transgressor). </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1699,2022,2750,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-300','<div class="desc"> <p>In this seminar-style course, CSLC majors (acting under the guidance of the course instructor) will be asked to research, and then report to one another, on contemporary trends in literature and literary theory. It is hoped that the skills developed in this course, as well as the content mastered within it, will help CSLC majors in the eventual formulation (and successful completion) of their Senior Comps. Only open to CSLC majors with junior standing, or by instructor permission.</p> </div>','CSLC 200 and two additional courses in CSLC ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1700,2022,2751,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-315','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> <p>This section will meet once a week extra to discuss these texts as read in the original German. Reading, but not speaking knowledge of German is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1701,2022,2752,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/200/rusn-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers:Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ).</p> <p>This course meets twice a week with CSLC 236, and for one additional 85 minute session per week, to develop Russian students'' intermediate language skills, specifically by reading and discussing works under consideration in the course taught in translation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1702,2022,2753,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-230','<div class="desc"> <p>This course invites students with previous art experience from across the College, including visual arts, music, theater, creative writing, MAC, etc., to explore genre-crossing art. The course will focus on the specialty of the faculty member, including video installation, sound art, performance art, site-specific art, collaborative projects, community based projects and social practice art. The class meets twice per week for technical demonstrations, in-class art making, visiting artists, and critical feedback, along with out of class visits to contemporary art and performance venues. Permission of instructor required.</p> <p><strong>Visualizing Sound</strong></p> <p>Sound Arts takes a cross-disciplinary approach to utilizing sound as a stand-alone installation or integrated within other media. Many contemporary artists are interested in incorporating sound into their projects but may not know how to approach and accomplish that integration. Because sound is ephemeral it can be used in an infinite number of ways to infer complex relationships. The challenge of using sound is that of translating ideas into the sonic medium and then reproducing that medium back into physical space. In this class students will learn about sound and discover ways to apply sound to express a deeper theoretical practice. Practical sound related techniques will be explored, as will their application through skills like deep listening, recording techniques for best capture practices, basics of the Digital Audio Workstation, and the use of sound reproducing systems. Students will collaborate on a project over the course of the semester with an exhibition in the OXY Arts Space at the end of the semester with an opportunity for performance.</p> <p><strong>Pollinator Drones, Wish Factories, and Robotic Dogs: ‘What-if’ Scenarios as Drivers of Creative Production and Imagination</strong></p> <p>As humankind stares down a number of unprecedented global challenges, the need for creative, radical thinking is imperative. In this interdisciplinary studio, students will develop a series of detailed and speculative projects inspired by boundary-pushing artistic and technological practices. The course will examine precedents from contemporary art, media, engineering, performance, design, and technology that offer responses to a wide range of “what-if” scenarios. The primary goal of the class will be to guide students as they develop a methodology for making creative and responsive work—one that relies on provocation and imagination as driving forces. Class projects will be designed to develop critical thinking and research skills, art-making and visual communication capabilities, and will call for speculative, even fantastical, responses to complex sites and situations. Technological and data-driven approaches, including data analysis, modeling, and scenario planning, will be integrated into the class assignments, encouraging cross-disciplinary collaborations between computer science and media arts students. Instructional assignments will explore a range of materials, scales, and research methods, and will encourage students to develop their abilities to hone and express innovative responses to complex societal and relational questions. The final series of class projects will address the uncertainty of climate change as a contextual framework, and final proposals may range from site-specific art installations to new applications for robotics; from creating futuristic soundscapes to designing experiences in VR. Site visits and guest lecturers will extend students’ connections with selected Los Angeles sites and their contexts, the understanding of a broad set of perspectives and values, and real-world examples of collaborative, cross-disciplinary projects. Cross-listed as: COMP 230.</p> </div>','Permission of Instructor. Not open to First Year Students. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1703,2022,2775,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-347','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> <p><span style="background-color: #ffffff; color: #212021;">Taught in conjunction with </span>CSLC 247<span style="background-color: #ffffff; color: #212021;">, but meeting for an additional section.</span></p> </div>','LATN 201 or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1704,2022,2776,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-233','<div class="desc"> <p>This course introduces students to literary questions of queerness, canonization, and nation, in the context of the United States'' 20th century discourses about homosexuality. Students will analyze the production of ideas about the nation through literature and examine the limits and capacities of the novel genre for cultural expressions of LGBTQ life in America. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1706,2022,2778,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/100/blst-104','<div class="desc"> <p>This course surveys the musical styles and genres of the African continent and the Middle Eastern world. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1708,2022,2780,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-234','<div class="desc"> <p>This course examines the political dynamics of apartheid and post-apartheid South Africa. Particular emphasis is placed on the development of black political opposition since the 1970''s, including both militant action against the state, as well as inter-ethnic political action and violence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1710,2022,2782,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. Major requirement met: Group III/IV.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1712,2022,2784,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COGS 101, four units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1713,2022,2785,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-349','<div class="desc"> <p>Robotics offers one of the most integrating domains for computer science. Creating a working, human-facing robot brings together hardware and software, artificial intelligence and human-computer interaction. Topics include Simultaneous Localization and Mapping (SLAM), path planning, object recognition, basic mechanics, and social robotics.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1714,2022,2786,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-357','<div class="desc"> <p>Much of the power of computers is that they are not individual machines, but units on a network that can exchange information. This course starts with the transmitting binary electrical signals, then builds up to the TCP/IP stack and the algorithms involved, and finally current research questions in the field.</p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1715,2022,2787,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-379','<div class="desc"> <p>An operating system ties together the hardware and software components of a computer. For interested students, this will likely be the final step to completely understanding what happens when code is executed. Topics include virtual memory, file systems, process management, parallel computing, and others. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1719,2022,2791,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-212','<div class="desc"> <p>Using critical theory and film analysis, students in this course will interrogate Disney Corporation’s feature-length animated motion pictures. Analysis will include themes and explorations related to gender, race, class, nation, and empire. In this class, these films will be approached as both a textual, cultural, and historical practice. As such, students will develop and hone "close reading" skills in relation to the cultural impacts of texts on children. Additionally, we will focus on the American values and beliefs as they are presented in the films, endeavoring to make the f"strange familiar and the familiar strange" (Spiro, 1990). Along the way, we will discuss some of the most influential and productive critical schools of thought informing film analysis today, including realism, auteurism, feminism, postmodernism, and others. Screenings are mandatory.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1724,2022,2796,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-342','<div class="desc"> <p>This course offers students the opportunity to read, in the original Latin and in translation, texts by or about non-elite people in the Roman world. In so doing, it attempts to recover the largely forgotten perspectives, experiences, interests, voices, and cultures of non-elite people in the Roman world, that is, the entire Mediterranean from 133 B.C.E. to 476 C.E. Today, we usually see Roman history and culture from the perspective of Rome’s elites, because the bulk of the surviving texts were written by or for elites. We shall steer a different course, examining texts and material artifacts produced by, for, or about ordinary people. Topics include Roman childhood and the Roman family, kinship relations, mothering and motherhood, child-rearing practices, children’s experience, the death of kin and commemorative practices; the economic circumstances of ordinary Romans, the nature of work, the terms of lending and borrowing, the experiences and cultures of slave-holding and of enslavement; women’s roles as girl (<em>puella</em>), girlfriend (<em>amica</em>), wife (<em>matrona</em>), prostitute (<em>meretrix</em>), and witch (<em>venefica</em>); sex, sexuality, and dirty songs; the people’s entertainments, such as theater, games, gladiator shows, and popular literature; popular politics and the role of the crowd and common person in public life; the culture of soldiering and the experience of peoples at the borders of empire; popular religious phenomena and the appeal of prophets, priests, and holy men in such movements as Isis worship, Mithraism, and Christianity. The goal of the course is for students to emerge with a holistic understanding of the details of and scholarly theories about non-elite culture in the Roman world, and hence with a heightened ability to identify and critically analyze contemporary discourses about “low” versus “high” culture, which most often remain entirely implicit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1725,2022,2797,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-301','<div class="desc"> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.</p> <p> <br/> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written.</p> <p><br/> </p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1727,2022,2799,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-212','<div class="desc"> <p>Existentialist philosophy is primarily concerned with questions of authenticity, value choice, and freedom: What does it mean to live an authentic human life? Are we free to choose the kinds of people we are and the values we embrace? And what do such possibilities mean for our obligations to other people? In this class we will discuss the problems raised and solutions proposed by existentialist philosophers such as Kierkegaard, Nietzsche, Heidegger, Sartre, Camus, and Beauvoir, through critical examination of their major writings. Our aims will be to understand the intellectual motivations for existentialist thinking and the relevance of their arguments and positions for contemporary philosophy and contemporary life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1728,2022,2800,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-220','<div class="desc"> <p>This course will philosophically examine the concept of race and the way race informs identity. Topics include the reality of race, the origins and nature of the concept, and the extent to which race does and should impact our social and personal identities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1730,2022,2802,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-231','<div class="desc"> <p>This course will examine the ethical dimensions of our relationship to non-human animals and the environment, including a special emphasis on climate justice as the site of interconnected and global moral, political, and scientific concerns. Some of the questions we will address include: What is the relation between the environment and human health and well-being? Are there reasons other than human health and well-being for protecting the environment? Do nonhuman animals have rights? Do trees? Are we morally permitted to eat/experiment on/keep in zoos/hunt nonhuman animals? How do we compare environmental values against other values in making reasonable decisions?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1731,2022,2803,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-232','<div class="desc"> <p>This course will draw on philosophy, literature, and film in order to address some of the central topics in philosophy of religion. The questions that the course will address include: Does God exist? What is faith, and when, if ever, is it rational? Do we survive our bodily deaths, and if not, should we fear death? The course will also consider implications of answers to these questions for the meaning and value of our lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1732,2022,2804,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-241','<div class="desc"> <p>Paradoxes and their resolution have played a significant role in the development of philosophy; they still have an influence on philosophy today. While Zeno''s paradoxes of motion where first posed about 2000 years ago there is still not a consensus about what to say about them. Semantic paradoxes such as the liar paradox and the paradoxes of vagueness reveal problems with everyday concepts such as truth and implication. Supertasks reveal problems with our understanding of infinity. What to say about these problems what they show us about how to understand space, time, infinity, truth, and reasoning are some of the issues we will discuss in this class. We will examine various paradoxes, puzzles, and purported paradoxes and discuss different proposed resolutions to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1733,2022,2805,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/200/phil-242','<div class="desc"> <p>An introduction to the study of the mind and its relation to the body, the nature of human agency action, and personal identity. Questions to be investigated include: Is the mind identical to the brain, or is it something separate and immaterial? Is it possible for computers to think, to have consciousness, and to engage in actions that can be assessed as right or wrong? What makes someone the same person at two different times? Could you continue to exist after the death of your brain with a prosthetic brain, carbon or silicon based, into which your beliefs, desires, and memories have been infused?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1735,2022,2807,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-311','<div class="desc"> <p>Ludwig Wittgenstein (1889-1951) is a central figure in the two most important philosophical traditions of the twentieth century: First the attempt early in the century to characterize language thought and the world in terms of the newly available formalism of modern logic and second the attempt to show that any such formalization will fail to do justice to the rich complexity of language as a form of life a form inseparable from the social and historical context from which it springs. We will examine two principal works the <em>Tractatus Logico-Philosophicus </em>and the <em>Philosophical Investigations</em>. There will also be some treatment of the historical and philosophical context of Wittgenstein''s work and life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1736,2022,2808,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-313','<div class="desc"> <p>Fyodor Dostoevsky’s <em>The Brothers Karamazov</em> is a gripping story of murder and romantic rivalries, a wonderfully inventive literary work, and one of the finest philosophical novels ever written. We will read all of <em>The Brothers Karamazov</em> and discuss some of the main philosophical issues that it addresses. Furthermore, we will consider these issues in light of 19th-century Russian culture, and society. Course topics will include: (1) the conflict between faith and reason, and the role – if any – that faith occupies in a good life (2) the nature of love, and the meaning and significance of the command to “love your neighbor” (3) what it means for human beings to flourish, and what sort of community makes flourishing possible. We will also discuss more recent philosophical work and film on related topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1737,2022,2809,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-321','<div class="desc"> <p>James Baldwin explored, with extraordinary sensitivity and insight, issues of race, poverty, and sexual difference in America. In this course, we will engage with Baldwin’s essays, novels, and plays, together with related philosophical work and film, in order to explore the some of the main philosophical themes in Baldwin’s work. We will focus on the roles that love, truth-telling, and self-knowledge play in living a morally good life and in creating a just society.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1743,2022,2815,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/300/rels-302','<div class="desc"> <p>In this course, students will explore mediumship and exorcism practices in the Atlantic World from the early modern period to today. Through case studies—including Haitian Vodou in Brooklyn, Brazilian Umbanda and Candomblé, Cuban Palo Monte, Santería in Chicago, Yorùbá and Igbo traditions in West Africa, North American Spiritualism, and Catholic Exorcism in France—we will take a broad look at the different ritual practices that fall under the academic category of “spirit possession.” We will consider why practitioners channel the spirits of the dead and what it means to be possessed. We will read scholarly studies that analyze what spirit possession has to do with race, gender, and sexuality. Finally, we will interrogate contemporary western scholarship itself, asking: Why have outsiders commonly described the spirits’ presence in terms of “possession”—a term rarely used by practitioners themselves—and how does the trope of the possessed person serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1745,2022,2817,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-281','<div class="desc"> <p>Beginning to advanced instruction in drum set performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive zero units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1746,2022,2818,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musa-music-applied-study/200/musa-282','<div class="desc"> <p>Beginning to advanced instruction in drum set performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive zero units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1747,2022,2819,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/amst-american-studies/200/amst-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and theory as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations, power, knowledge, and identities are constituted through private and public rhetorical acts, mainly in the nineteenth-century to the present.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1748,2022,2821,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-116','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and fallibility. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in-depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1749,2022,2822,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-136','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. Authors may include: Tolstoy, Dostoevsky, Turgnev, Gogol, Goncharov, Bulgakov, Pushkin, and many, many others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1750,2022,2823,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-201','<div class="desc"> <p>The words of literature, unlike soda cans, bits of data, or the modular classroom furniture of Johnson Hall, do not come to us in easily separable pieces; the words of literature, rather, always present themselves to us as parts of a greater whole, as participants in this or that literaryFORM: a poem, a play, a novel, a song... In this class, we shall set aside the usual preoccupation with the meaning of the words of literature, to investigate instead the various effects that different literary forms exert upon us. What, for instance, do narrative forms --from Babylonian epic to the experimental prose of David Foster Wallace and Karl Ove Knausgaard--tell us about the kinds of worlds that are ours to inhabit in our daily lives? How do the poetic forms of (say) the ballad, the haiku, the sonnet or pop song inflect the manner in which we every day take up our existence? How does drama--from Ancient Greek tragedy to Japanese <em>noh</em> to the theatres of the avant-garde, the cruel and the absurd--open up for us the experience of all those "others" with whom we share this life? By the end of this class, it is hoped that students will have developed not only a feeling for literature in its many forms, but reciprocally, an appreciation for the richness of experience such forms of feeling can bestow upon us.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1751,2022,2824,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-248','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 BCE sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 BCE when he brought his army across the Rubicon river into Italy from Gaul. </p> <p>Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as <em>On the Republic</em> and <em>On the Laws</em>, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators seeking to restore the old order assassinated Caesar in 44 BCE. They were in turn destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.</p> <p>Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise <em>Discourses on Livy</em>, and John Adams (the “American Cicero”), whose 1787 work <em>Defence of the Constitutions of the United States of America</em> owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1752,2022,2825,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-285','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1753,2022,2826,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-227','<div class="desc"> <p>Thirty years after Francis Fukuyama proclaimed the "End of History," political authoritarianism remains viable while democracy is increasingly under threat around the world. Many dictators have embraced hypermobility of capital, free trade, and modern information technology. At the same time, deepening globalization has also challenged long-established democratic systems, producing anti-democratic political movements. We will investigate some of the following questions produced by the clash between global capitalism and local politics: How do authoritarian leaders react to the challenges of globalization in the 21st century? Does globalization undermine or enhance their hold on power? Will authoritarianism or democracy survive a long-term engagement with global markets?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1754,2022,2827,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/300/econ-322','<div class="desc"> <p>Are goals of economic development and sustainability at odds with one another? What kinds of policy instruments could help us effectively reduce emissions, and why is international cooperation so difficult to achieve? This course offers a critical examination of sustainable development from the economics perspective. Beginning with conflicting views of sustainable development, the course proceeds to study how economists approach challenges such as climate change, management of common property resources, growth and poverty, measurement of well-being, and global health.</p> </div>','ECON 250, or ECON 102 and MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1755,2022,2829,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/300/engl-314','<div class="desc"> <p>This course examines the poetry and poetics of the English Renaissance, emphasizing the relationship between formal developments in poetic techniques and questions of religious belief, gender, labor, race, education, and politics. Readings include classical and humanist poetic and rhetorical theory (from Plato to Puttenham) and a wide range of poets, including Thomas Wyatt, Anne Locke, Philip Sidney, Edmund Spenser, William Shakespeare, John Donne, John Milton, Andrew Marvell, Mary Wroth, and Katherine Philips, as well as some consideration of the influence Renaissance verse has had on modern poets (such as T.S. Eliot, Frank O''Hara, and Marilyn Nelson).</p> <p><strong>Major Requirement Met: </strong>Group I</p> </div>','One 200-level English class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1756,2022,2830,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-348','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 B.C.E sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 B.C.E when he brought his army across the Rubicon river into Italy from Gaul. With Pompey gone, the republic was lost.<br/> <br/> Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as On the Republic and On the Laws, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators who sought to restore the old order assassinated Caesar in 44 B.C.E. They were, in turn, destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.<br/> <br/> Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise Discourses on Livy, and John Adams (the “American Cicero”), whose 1787 work Defence of the Constitutions of the United States of America owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>','Students must have taken LATN 201 or have permission of the instructor to enroll. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1757,2022,2831,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ling-linguistics/300/ling-351','<div class="desc"> <p>This course aims to equip students with the understanding of how speech sounds in the world’s languages are produced via an introduction to <em>articulatory</em> and <em>acoustic phonetics</em>. Building on the basics learned in Ling 301, you will learn how speech sounds are articulated; how to describe, compare, and contrast speech sounds in different languages and dialects on the basis of articulatory and acoustic measures; and finally, why knowledge about speech sounds is important to a variety of careers and professions, from speech pathology to language teaching to voice-to-text technology.</p> </div>','LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1758,2022,2832,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-270','<div class="desc"> <p>This course explores emerging methods of narrative design in relationship to worldbuilding. Worldbuilding refers to designing a complex integrated system with many moving parts such as characters, settings, myths, rules, artifacts – often a whole system of a society and culture. These design methods are used throughout media forms ranging from narrative writing, filmmaking, theater, architecture, mobile apps, video games, and virtual reality, to the integrated use of multiple forms using transmedia storytelling. Students will create short projects that investigate relationships between the design of a world and the storytelling possibilities that emerge from and are embedded within it, using both analog and digital methods. Students will experiment with methods and concepts such as non-linear storytelling, interactivity, experience design, transmedia, the poetics of space, and other relevant topics. Readings and short screenings will contextualize hands-on-work within larger historical and cultural contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1759,2022,2834,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/musc-247','<div class="desc"> <p>Pro Tools is, worldwide, the standard digital audio workstation for audio recording, editing, and mixing in studios and music production facilities. Understanding its operation, features, and workflows is required for the production of all music genres today, from the small studio to the largest scoring stage. This course will take students with no experience in Pro Tools and equip them with the knowledge and hands-on training to prepare them for the Avid Certified User for Pro Tools exam by covering all the material in Avid’s Pro Tools Fundamentals I (PT101) and Pro Tools Fundamentals II (PT110) curricula. The PT101 course introduces fundamental Pro Tools concepts and principles, covering everything one needs to know to complete a basic Pro Tools project, from initial setup to final mixdown. The PT110 course builds on PT101 by introducing the core concepts and techniques students need to become competent in operating a Pro Tools system for mid-sized recording sessions. Both this course and MUSC 249, Recording Techniques, are required to run recording sessions in the Booth first-floor recording studio. Instructor permission required.</p> </div>','MUSC 148 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1760,2022,2835,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/200/phys-230','<div class="desc"> <p>Introduction to electricity and magnetism electronic circuits electromagnetic induction and Maxwell''s Equations. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1761,2022,2837,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pols-politics/200/pols-287','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1762,2022,2838,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pubh-public-health/200/pubh-203','<div class="desc"> <p>This course explores the nation''s public health challenges and the ways that public health functions as a combination of science and politics. The course examines the various social, political, and demographic factors that impact population health. Students are introduced to public health concepts and learn to analyze health problems, considering the influence and intersection of race, status, gender, income, education and sexuality. Using data, evidence, and health behavior theory, students evaluate strategies and solutions to address health inequity and improve population health.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1763,2022,2839,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pubh-public-health/200/pubh-248','<div class="desc"> <p>The course will examine major global public health problems and the range of responses from international organizations transnational networks and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as HIV/AIDS malaria unsafe food and water tobacco use and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health including morbidity mortality demography epidemiology and the political social and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political economic social and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1764,2022,2840,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pubh-public-health/300/pubh-301','<div class="desc"> <p>This course provides an examination of women''s health across the life cycle, with special emphasis on the structural and societal factors that influence health outcomes among women. It introduces students to public health frameworks for assessing women’s health issues within various contexts. This course uses these frameworks as a basis for examining the relationship between social and cultural factors and women’s health. It provides an overview of the emerging and on-going issues in women''s health, including sexual and reproductive health, contraception, gender-based violence, mental health and substance abuse, in order to understand and address health inequities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1765,2022,2841,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pubh-public-health/300/pubh-307','<div class="desc"> <p>The community health internship course is designed to provide students with real-world experiences to develop new skills and enhance insights into myriad community health issues and solutions. Under supervision of the course instructor and in collaboration with a community proctor/partner students will intern for 8-hours a week at a health focused non-profit organization community clinic or government agency. Through the internship and course work, students explore and analyze the social, cultural, and systematic barriers to health in Los Angeles and the U.S. Students reflect on and discuss the complexities of keeping communities healthy, considering the impact of policy, identity, power, urban planning and culture. Before registering students should check to make sure that they are available during the preset internship hours. Internship hours and activities can be viewed at the Community Health Engagement website: http://bit.ly/1sDCTeJ</p> </div>','PUBH 203 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1766,2022,2842,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-167','<div class="desc"> The Zen school of Buddhism has long claimed itself as a tradition "beyond words and letters," or as a body of teachings that can be transmitted only through ineffable experience. And yet, Zen Buddhists have been some of the most productive writers and orators, producing volumes of biographical narratives, religious legends, and apologetic scholarship. In this course we will study Zen sources as a way to understand the social, institutional, and pedagogical power of the Zen school as it grew in Japan from the 12th century. We will seek to understand how Zen Buddhists in Japan balanced their own religious obligations with broader societal responsibilities, as well as how the Zen tradition reconciled its religious ideals with its practical concerns. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1767,2022,2843,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-254','<div class="desc"> <p>A course on gender and health in the history of Islam. The course begins with a study of the various dimensions, expressions, and status of what it has meant--and what it can mean--to be gendered a Muslim "man," "woman," or non-binary person: from the ideas found in scriptural sources, in later legal interpretations, through to historical transformations. Students will then study how legacies from the past are implicated in contemporary discourses and practices related to health and medical care. Students will explore issues related to bridging Muslim understandings of gender with best practices in health care, as well as the ethical reasoning behind gendered healthcare. Finally, students will explore a number of case studies on complicated and controversial issues such as abortion, sex reassignment surgeries, female genital mutilation, and sex positive movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1768,2022,2844,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/blst-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of forced African migrants to North America to the black quest for freedom in the twentieth century United States. With our focus on significant demographic, institutional, cultural, and political developments within African American communities, we will explore key themes and watershed moments in the African American experience: from slavery to emancipation, from rural to urban, and from the civil rights and black power movements of the twentieth century to the ongoing struggle for social justice. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of black Americans and the history of the United States. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1769,2022,2845,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-102','<div class="desc"> <p>Meaningful social and political change requires not only critical and thoughtful engagement with our grounding ideas, dominant theories and our existing positions. It also demands that we learn the concrete, practical skills necessary to make our ideals real, to exercise our rights, to fulfill our duties to one another, and to transform the actual mechanisms and institutions that shape our lives. This course — unique at either the undergraduate or graduate level — will provide students with an intensive and full-spectrum introduction to the most important, most effective and newest techniques, tools and technologies used in political and activist campaigns from the highest levels of electoral politics to non-profit, non-governmental and community campaigns. </p> <p>The course curriculum is organized in three dimensions, training students with the core skills necessary to participate in existing political and activist work, but also empowering them to, when necessary, imagine and carry out their own innovative and transformative campaigns. To this end, students will learn not just tactical skills, but also strategic planning and management approaches that will help them invent, implement, and improve the campaigns to which they commit themselves.</p> <p>This course will include instruction and workshops that bring the best practices and lessons from top businesses and campaigns, refined by political practitioners and distilled for students. It will also include tactical skills training-- media messaging and communication strategies, polling literacy, database management, budgeting and campaign finance, Get Out the Vote (GOTV) efforts, and lobbying basics. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1770,2022,2846,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-120','<div class="desc"> <p>This course introduces students to theories of power from multiple disciplines, and applies these theories to analysis of how power operates in formal and informal politics. Students will be introduced to the basic operation of politics and public policy in the U.S., as well power operating in economic and social systems. It will analyze contemporary public policy, political campaigns and elections, social movements, hashtag activism, and other aspects of the struggle for power in the U.S. context. This class is open to frosh and sophomore students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1771,2022,2847,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-204','<div class="desc"> <p>The abuse of Iraqi prisoners at the US military’s Abu Ghraib Prison and the terrible photographs that circulated giving testimony to that abuse brought torture into our public discourse and became a point of intense political engagement in the US and around the world. This course will examine the so-called “enhanced interrogation techniques” used during the War on Terror as well as the legal and policy justifications that supported them. We will place these practices and justifications within the broader context of colonial power, looking at the ways torture and sexual violence were deployed by other nations. Beyond its use as a punishment or deterrent, we will trace the use of torture back through Western history, to its use in religious and political conversions and finally back to the origins of Western metaphysics in the Ancient Greek use of violence and dehumanization in the formulation of our conception of truth itself.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1772,2022,2848,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-221','<div class="desc"> <p>This interdisciplinary course is designed for students considering the law as a potential career path and who are interested in developing an understanding of the relationship between inequity, the law and critical theory. Our materials will include federal and California statutes and case law, government-issued reports, and legal journal articles related to education; housing justice; police practices; consumer protection; immigrants'' rights; and other topics. This course will teach students the methods of law and policy analysis. The two main questions that will guide our critical thinking are: what is the impact of the law on inequity and what is the impact of inequity on the law? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1773,2022,2849,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-300','<div class="desc"> <p>This course is an introduction to the process of conducting social science research. Students will learn to execute a research project from start to finish—including the formulation of a research question, selecting the best method(s) for addressing the question, statistical analysis in a lab setting, and research report writing. Students will also learn to critically analyze the production of knowledge and unmask the power dynamics of “scientific” inquiry, “objectivity,” and “authority.”</p> </div>','CTSJ 100 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1774,2022,2850,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-210','<div class="desc"> <p>This course introduces students to the history, politics, and international context of Russia and other countries of the former Soviet Union. The course focuses on the political and economic transformation in post-communist Eurasia after the fall of the Soviet Union in 1991. We investigate the nature of domestic political systems of post-Soviet state, state-society relations, ethnic conflict, politics of economic reform, and the underpinnings of foreign policy-making in these countries. Students will learn about the region using the comparative method by engaging in reading and writing assignments that will require comparing outcomes of student’s choice both cross-nationally or temporally.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1775,2022,2851,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of forced African migrants to North America to the black quest for freedom in the twentieth century United States. With our focus on significant demographic, institutional, cultural, and political developments within African American communities, we will explore key themes and watershed moments in the African American experience: from slavery to emancipation, from rural to urban, and from the civil rights and black power movements of the twentieth century to the ongoing struggle for social justice. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of black Americans and the history of the United States.</p> <p><strong>Survey Requirement Met:</strong> United States</p> </div>','n/a ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1776,2022,2853,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/grk-greek/300/grk-385','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. In addition to attending the 3 hours of lecture required of students in CSLC 285, students in Greek 385 are required to attend an additional 90 minutes of class per week to read and discuss texts in the original language. Students in this course are required to complete a 10-12-page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1777,2022,2854,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-336','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. In this five unit version of CSLC 136, we will be reading excerpts in the original language from Goncharov’s Oblomov, Turgenev’s Fathers and Sons, Dostoevsky’s Idiot. Students in this course will be asked to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1778,2022,2856,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/musc-106','<div class="desc"> <p>This course teaches the fundamentals of singing: voice production, breathing, range, song selection, and performance. Students will learn and perform three solo songs during the course of the semester. Recommended as preparation for private lessons. Graded on a Credit/No Credit basis only. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1779,2022,2857,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-398','<div class="desc"> <p> Students engage with open problems in an active area of faculty research. May be repeated once for credit.</p> </div>','COMP 127, COMP 131, COMP 211, or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1780,2022,2858,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-319','<div class="desc"> <p>Knowledge Representation and Reasoning is the area of Artificial Intelligence concerned with how knowledge can be represented and how automated systems can reason about that knowledge. In this course, we will learn how to use symbolic notations to represent knowledge, including how to represent objects, events, time, space, and language. We will also learn how to use automated reasoning systems to manipulate these representations and derive new knowledge. This will be a hands-on course in which we apply concepts from philosophy, psychology, and cognitive science to build systems that can reason about real-world problems.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1781,2022,2859,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/comp-355','<div class="desc"> <p>This course will teach students both front-end and back-end techniques necessary to build web applications. Students will learn how to make interactive websites, how to structure and manage content for websites in databases, and how to create data-driven web applications.</p> <p>Sub-field: <strong>SOFTWARE</strong></p> </div>','COMP 229 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1782,2022,2860,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-200','<div class="desc"> <p>This course provides opportunities for students to engage in community-based work with arts organizations. Each student will work with a community-based partner or artist for approximately 6-7 hours each week. This in-the-field experience will be paired with reflective exercises and relevant readings, and will be facilitated by a faculty member in the department.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1783,2022,2861,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-270','<div class="desc"> <p>Art, Ethics and Medicine: The PPE Portrait Project is a four-credit class focused on the tenets of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care at USC-Keck Hospital, Stanford Medical School, UMASS, Mass General and advising nearly a dozen other hospitals across the US and beyond. At the heart of the PPE Portrait Project is the centrality of the image, and the role of the face in generating empathy, compassion and ethical behavior. </p> <p>The PPE Portrait Project Semester will combine theory, research and practice together with the community engagement (ARTS 275) intrinsic to this social practice art project. Students will learn how artists act as innovators and catalysts of change; the art history and visual studies of representing the face, including portraiture, photography, and discredited attempts to read intellect or morals in the appearance of a face. Students will also learn about the connections between visual culture (like portraits) and science, including the developmental concepts of facial recognition, and representation recognition in infants and others; the neuroscience of mirror neurons and the biological basis of intersubjectivity as the foundation of ethical behavior; the philosophy of bioethics and notions of patient self-determination and agency; and the biology and physiology of social and cultural actions. Students will learn how looking at images has the power to physically change a person''s body. Through this project, students will deepen their understanding of the structures and processes of privilege, exclusion, and marginalization that shape healthcare in the United States.</p> </div>',NULL,'ARTS 275 ',NULL);
INSERT INTO course_descriptions VALUES(1784,2022,2862,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/200/arts-275','<div class="desc"> <p>In this course, students will activate their own project site of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care across the US and beyond. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Students will be encouraged to implement the project in a group with whom they have a meaningful connection, including schools, community groups; any group who would benefit from an enhanced human connection at a time of masked distancing, anonymity and faceless interaction. </p> <p>At the heart of the PPE Portrait Project is the centrality of the image, and the role of images of the face in generating empathy, compassion and ethical behavior. With widespread facemask use on our horizon for the foreseeable future, the need to address the isolation and alienation caused by faceless person-to-person exchange is expanding beyond the urgent need of hospitals. Precipitated by social media before the pandemic, and now exacerbated by the coronavirus, we are experiencing an "epidemic of facelessness." </p> <p>Students will use community based learning methods to ethically engage with a group, and innovate with the PPE Portrait Project tenets and materials to best meet the needs of the community partner. </p> </div>',NULL,'ARTS 270 ',NULL);
INSERT INTO course_descriptions VALUES(1785,2022,2863,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-393','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>The Biology and Epidemiology of COVID-19</strong></p> <p>How did COVID-19 come to ravage the world and bring it to its knees in just a few months? What is happening now, and what will happen next? As of mid-July, 2020, there were over 13 million cases of COVID-19 worldwide, and 570,000 deaths (World Health Organization). Over 3.2 million of those cases and 135,000 deaths were in the United States. All of these numbers are increasing. Students in this class have the unique opportunity to study this pandemic as it is happening. Topics will include the biology of the SARS-CoV-2 virus, the COVID-19 disease, and factors that affect the outcome of the disease. Testing and vaccine development will be covered. The epidemiology of the disease will be discussed, including the disproportionate effects of the disease in people of color. </p> </div>','BIO 221, BIO 224, BIO 226, BIO 322, or Bio 349. Statistics course preferred but not required. ','BIO 393L ',NULL);
INSERT INTO course_descriptions VALUES(1786,2022,2864,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-393l','<div class="desc"> <p>Topics vary semester by semester. </p> <p><strong>The Biology and Epidemiology of COVID-19 Laboratory</strong></p> <p>The lab portion of the class will include learning techniques involved in COVID-19 diagnosis and screening, plus projects on topics such as data analysis of anonymous patient test results, vaccine development, and therapeutic approaches.</p> </div>',NULL,'BIO 393 ',NULL);
INSERT INTO course_descriptions VALUES(1787,2022,2865,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-316','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and fallibility. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in-depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> <p>In addition to the English section, this course will meet for an additional session per week to read the texts in their original German and discuss the nuance and difference in meaning as it is transmitted through the original language. Reading the text in the original German is particularly important in the case of Heidegger, whose philosophical program cannot be separated from his thinking about language and the intricate relationship between language and meaning. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second-Stage Writing Requirement. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1788,2022,2866,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/100/thea-195','<div class="desc"> <p>What does performance do? Why perform? What is the essence of the “live” and what is the impact of being in the same time and (virtual) space? We will unpack these questions through analysis and performance, looking closely at seminal pieces that speak to this moment and calling on experts in design, technical theater, comedy and solo performance to give behind-the-scenes insight into the making of live performance. Bracketed around questions of liveness, social action, and impact, students will take specialized workshops with theater faculty who will address these questions through their areas of expertise, providing students opportunities to experiment with an array of performance practices.</p> </div>',NULL,'ARTS 250 ',NULL);
INSERT INTO course_descriptions VALUES(1789,2022,2867,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/core-core-program/courses/core-95','<div class="desc"> <p>The goal of this course is to provide students with academic, social and personal skills including reading and study strategies, procrastination and time management, and more, to aid in students'' academic success and integration in their first year of college. </p> <p>Through workshops and guest lectures, students will learn how to access campus resources and opportunities, to help them build social capital and community within the Oxy campus. This course emphasizes student development and provides specific support for first-generation students. </p> </div>','None ','None',NULL);
INSERT INTO course_descriptions VALUES(1790,2022,2868,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/100/bio-198','<div class="desc"> <p>Complementing their Oxy Immersive Semester coursework for the California Environment and Conservation Corps, students in the program will engage in service-learning. Students will be matched with Southern California environmental organizations. The hours spent in service (which will be completed virtually) would be scaffolded with reflective reading and writing centered around concepts of environmental stewardship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1791,2022,2869,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/200/comp-295','<div class="desc"> <p><strong>Computing in Real Life Internship</strong></p> <p>Students will work with LA-based non-profits such as STEAM:CODERS, a Pasadena-based organization that teaches local middle and high school students to program, or the Association for Women in Mathematics, a national organization that promotes women in computation. Students will complete weekly reflection papers and a final presentation describing what they’ve learned about computation IRL. <em>Open only to students enrolled in the Computing IRL semester.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1792,2022,2870,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-345','<div class="desc"> <p>This course will survey the diversity among major classes of viruses in genomic material, replication, and host cell interaction. We will discuss aspects of antiviral strategies by the host immune response as well as ongoing research in medical antiviral therapies. In addition, we will cover various ways that viruses have been harnessed as useful tools in the laboratory as sources of unique enzymes, vectors for introducing exogenous material into cells, and in various other applications such as phage display.</p> </div>','Bio 130 and either BIO 221, BIO 224, or BIO 226 ','BIO345L ',NULL);
INSERT INTO course_descriptions VALUES(1793,2022,2871,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/bio-345l','<div class="desc"> Laboratory techniques in virology. Graded on a Credit/No Credit basis only. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1794,2022,2872,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/100/blst-101','<div class="desc"> <p>This course introduces students to the history and methods of the discipline known as Black Studies. Readings will focus on the origins and institutionalization of Black Studies as a field of academic inquiry. Students will learn about the philosophical and political debates that laid the intellectual foundation for Black Studies and examine the social movements that resulted in the field of Black Studies in the present. Topics include the foundational academic work of W.E.B. DuBois, the San Francisco State student revolt of 1968, Mellon and Ford Foundation funding of programs and departments, and the recent student demands at University of Missouri and elsewhere. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1795,2022,2873,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-302','<div class="desc"> <p>In this course, students will explore mediumship and exorcism practices in the Atlantic World from the early modern period to today. Through case studies—including Haitian Vodou in Brooklyn, Brazilian Umbanda and Candomblé, Cuban Palo Monte, Santería in Chicago, Yorùbá and Igbo traditions in West Africa, North American Spiritualism, and Catholic Exorcism in France—we will take a broad look at the different ritual practices that fall under the academic category of “spirit possession.” We will consider why practitioners channel the spirits of the dead and what it means to be possessed. We will read scholarly studies that analyze what spirit possession has to do with race, gender, and sexuality. Finally, we will interrogate contemporary western scholarship itself, asking: Why have outsiders commonly described the spirits’ presence in terms of “possession”—a term rarely used by practitioners themselves—and how does the trope of the possessed person serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1796,2022,2874,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-309','<div class="desc"> <p>This course examines the southern region of the United States as a “slave society,” that is, a society in which: 1) a system of enslaved labor and human commodification drove the region’s economy and 2) a powerful slaveholding minority held the reigns of political power. How did this minority white ruling class maintain their power over a large enslaved population (1 in 3 southerners by 1860) and a majority of non-slaveholding whites (3 out of 4 white southerners by 1860)? How did enslaved women and men create community, build solidarity, chart insurgent geographies, and establish a political tradition of resistance in the face of arbitrary and institutionalized violence? We will examine the rise of chattel slavery, its importance in American capitalism, and its impact on southern households, political institutions, religion, and cultural practices. Our readings will explore how a white supremacist system of transgenerational human property shaped the social relations and lived experiences of enslaved African Americans, common whites, slaveholding planters, and Indigenous nations of the South. How did these groups of southerners use religion, violence, and ideologies of sex, gender, race, and class either to challenge or reinforce existing power relations? How was the US nation as a whole complicit in the perpetuation of chattel slavery? Finally, how does the US as a nation continue to reckon with the legacies of chattel slavery in contemporary social movements, law, and culture? Course materials include primary documents, first-person narratives, film, music, and groundbreaking historical scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1797,2022,2875,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/300/blst-346','<div class="desc"> <p>This course thinks through current debates over the relationship between literary aesthetics and harmony in American democracy. Do aesthetics foster a more harmonious or disharmonious national culture? Is disharmony ever important to progress? How does literature represent protests for social change that are often only possible outside the law, like the many freedmen and freedwomen escaping slavery and demanding the destruction of that system? How does this alter our understandings of what it means to be a fugitive? How can the fugitive fighting for freedom be distinguished from the unprincipled outlaw? From another perspective, we will consider how the complications of American society have altered certain traditional literary forms. While recent scholarship has addressed these questions in regards to early- to mid-20th century literature, this course will look back further, starting from the early 19th century to the very beginning of the 20th. We will complement the literature by reading relevant historical materials from the abolitionist movement, labor movements, government debates over Emancipation and Reconstruction, etc. The course will include literature from Frederick Douglass, Sojourner Truth, Walt Whitman, Ida B Wells, and Charles Chesnutt, amongst others, and will cover several genres, including: oratory, autobiography, political pamphlets, and short fiction.</p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1798,2022,2877,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-115','<div class="desc"> <p>This course will examine the highly ambivalent effects of the adoption of Western digital, networked technologies (with their underlying modes of understanding the world and human life) in the modern Middle East and North Africa. In particular, in the context of the Middle East, the course will seek to identify and understand both (1) the new forms of popular liberatory action — revolt, protest, social organizing — that are made possible or impossible by the widespread adoption of new technological modes of life, and (2) the new forms of state and para-state, surveillance, control, suppression, and disinformation that this technology makes available or encourages by its very structure and embedded premises. Beginning with an analysis of the inner logic and possibilities of modern digital communication technologies as these have been formed in their Western conditions of emergence, the course will then set out to understand how the reception of these new Western technologies in the Middle East (1) give rise to new possibilities for liberatory action via a digital public sphere (for example, the events of the 2009 Iranian uprising and the on-going political movements associated with the 2011 Arab Spring); (2) foster and globally spread new modes of dangerous reactionary politics that include violent, socially destructive forms (for example, ISIS, violent sectarianism and anti-Semitism); and (3) give authoritarian and repressive Middle Eastern regimes new tools and strategies for the surveillance, suppression and social control of their populations (for example, Turkish, Egyptian responses to social movements, and the Iranian governments access to Western mobile phone companies'' location information of its citizens to round up protestors, to the use of wide-spread facial recognition technologies and the capacity to quickly spread disinformation or control elections results). The course will bring together a study of critical theoretical work from both Western and Middle Eastern thinkers (for example, of Foucault, Tufekci and Deleuze, Soroush, and Sardar) with the scholarly and vocational writing of technologists in both the West and the Middle East, the accessible operating documents of digital information companies who have played important roles in both making possible and repressing political and social liberation movements in the regions, and the legal and policy documents that both structure and deploy these technologies for and against us.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1799,2022,2878,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-220','<div class="desc"> <p>This class introduces students to the concept of intersectionality— how different identities (e.g., gender, race, ability, sexuality) overlap to create interdependent systems of oppression. Students will learn how these systems of power operate and function, and will analyze how these systems intersect and morph to maintain existing power structures. Students will grapple with critical race theory, feminist theory, queer theory, and readings from disability studies as well as quantitative studies documenting how different identities intersect. This course has an applied component. Students will perform research with The Intersectionality Project (TIP), the first research project to map the contours of intersectionality in the U.S. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1800,2022,2879,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-330','<div class="desc"> <p>This course interrogates the proliferation of ballroom culture in 20th and 21st century America. Students will examine the historical formation of ballroom and black queer culture in mid-20th century Harlem, New Orleans, and Chicago and its contemporary formations as sites of objection, life, and black queer radical praxis within black/Latino neighborhoods, while also interrogating the commodification of ballroom within popular culture. Students will consider how ballroom has been circumscribed within the ethnographic (Paris is Burning, the Aggressives, Kiki, &amp; Check It) and the consumptive (Pose, RuPaul’s Drag Race, Real Housewives of Atlanta, and Madonna’s Vogue), while also tracing how ballroom’s reconfigurations of normative gendering, it’s embodied response to quotidian antiblack violence, and it’s repertoire of classed, raced, and sexualized critique exist in excess of how it is spectacularized and consumed. The course offers students a complex site through which to consider how race, gender, class, and sexuality intersect and to interrogate how black queerness and transness have become central to what we know as “popular culture.”</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1801,2022,2880,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-350','<div class="desc"> <p>The course will study the transformation of postcolonial theory and practice by contemporary writers and activists in the Middle East, North Africa and South Asia in response both to their new social, cultural, political, and economic conditions, as well as to their experience of the limits of earlier forms of postcolonial thought. The course will track the problems posed by the emergent concepts of identity and authenticity and the way that the modalities of melancholia and <em>ressentiment </em>can affect or undermine the postcolonial as a project of liberation. As part of this re-examination, students will explore the complex ways in which Western modes of thinking and politics — including modernism, anti-modernism, Traditionalism and resurgent authoritarian and ethno-racial political forms — shape and are resisted by postcolonial thinkers and activists. The course will advance student understanding of postcolonial theory and practice by pairing (1) a careful examination of foundational works of postcolonial thought within their historical and political contexts, with (2) an exploration of the work of contemporary scholars and activists whose projects transform and reimagine the very idea of the postcolonial.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1802,2022,2881,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-355','<div class="desc"> <p>Economic and social rights include the right to an adequate standard of living, the rights to food, water, housing, and education, as well as the right to work and for basic income guarantees for those unable to work. The course examines the legal and philosophical foundations of economic and social rights, as well as challenges to the legality and legitimacy of these rights. We will examine the status of economic and social rights in the global human rights regime, and we will explore provisions for economic rights at the national level. We will discuss the connection between socio-economic rights and poverty, development, and globalization. Students will explore issues of measurement and policy implementation through a range of case studies and cross-regional comparisons. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1803,2022,2882,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/engl-220','<div class="desc"> <p>In this course we will study the relationship between literature and science during the Scientific Revolution of the seventeenth-century in England. Though today we usually consider science and literature to inhabit different spheres, in the era when “modern science” began there was no clear division between the two. We’ll explore the shared questions about the earth, human nature, the cosmos, and the divine that motivated new conceptions of scientific experiment and innovations in literary writing. We''ll also examine how the institutionalization of experimental science, especially with the founding of the Royal Society, transformed English literature as well as England''s orientation to Continental Europe and the "New World." Readings will be drawn from the work of scientists, fiction-writers, essayists, and poets, including William Shakespeare, Francis Bacon, Galileo Galilei, René Descartes, John Donne, Ben Jonson, Thomas Browne, Blaise Pascal, Robert Boyle, Anne Conway, Robert Hooke, Margaret Cavendish, John Milton, Thomas Hobbes, Lucy Hutchinson, and Isaac Newton.</p> <p><strong>Major Requirement Met:</strong> Group I</p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1804,2022,2883,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/200/geo-220','<div class="desc"> <p>The fundamentals of rock formation are explored through study of common rock-forming minerals and major rock types. Understanding of these processes is based on the physical, optical, chemical, and textural properties of minerals and rocks. The course includes a field trip to investigate rocks and minerals in some of California''s most interesting natural settings. <em>One three-hour laboratory per week and field trip.</em></p> </div>','GEO 105 or GEO 106 ','GEO 220L ',NULL);
INSERT INTO course_descriptions VALUES(1805,2022,2885,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/100/hist-192','<div class="desc"> <p>The course explores gender as a malleable category of historical analysis that intersects fluidly with other categories such as race, class, and sexuality. Course materials interweave global historical studies from the 16<sup>th</sup> to the 20<sup>th</sup> centuries with theoretical work on themes including the following: gender as performance, gendered divisions of labor, gender and science studies, the politics of gender, as well as gender, space, and material culture. By continually historicizing the construction of masculinities, femininities, and gender-fluid identities, this course examines how societies over time have expressed, policed, invented, and reproduced gender as a category of human experience and a shaper of social relations of power. The geographic range of the course is oriented primarily toward the Atlantic World: North America, South America, the Caribbean, West and West Central Africa, and Europe.</p> <p>This survey course is one of the History’s department’s gateway 190s-series that takes a transnational and thematic approach to key concepts in historical studies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1806,2022,2886,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pubh-public-health/200/pubh-238','<div class="desc"> <p>This course is designed to introduce the basic concepts, principles, and methods of epidemiologic research. In our pursuit to understand the interplay of risk factors and patterns of human disease and health, we will cover the history of epidemiology, the principles of epidemiologic thinking and of causal inference, the basic measures of disease frequency and of association, and how to compute them. We will also learn about the major types of epidemiologic study designs and explore the major fields of epidemiologic investigation. To better understand the practical application of study methods used in epidemiology, the class has a laboratory component (PUBH 238L). The laboratory component will provide students with the opportunity to apply the concepts from lecture and develop an epidemiological research proposal. Students will work through the research process, moving from developing a health related research question to operationalizing the idea into a research plan.</p> </div>','Statistics (BIO 268, COMP 146, MATH 150, PSYC 201, or UEP 305) and PUBH 203 ','PUBH 238L ',NULL);
INSERT INTO course_descriptions VALUES(1807,2022,2888,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/100/rels-168','<div class="desc"> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1808,2022,2889,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-244','<div class="desc"> <p>This class explores the Islamophobic ramifications of racialized Islam and Muslim identities. We will consider “blackness,” “brownness,” and “whiteness” as experienced through Muslim life, as well as how minoritized race and religion combine in ways that lead to fear, opposition, and violence. We will study Islamophobia through a number of American and Global cases, including the issue of iconoclasm (such as the Danish cartoon controversy), the racial and religious coding of various groups (such as Sikhs or Iranians in North America), perceptions of different sects of Islam (including Nation of Islam or the Ahmadiyya), and the political ramifications of these identities (such as recent US elections and the 2020 census). In addition to traditional readings, course materials will include a variety of media, such as longform journalism, memoirs, ethnography, music, and film.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1809,2022,2890,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/soc-sociology/300/soc-361','<div class="desc"> <p>This advanced seminar builds on the foundational understandings of race/ethnicity to further explore Whiteness in the U.S. and globally. Whiteness is a framework that organizes social structures and can be systemically upheld regardless of one''s race. This course explores how constructions of Whiteness change through shifting racial boundaries and across global contexts; how it shapes privilege, racism, and racial oppression across social institutions; how it intersects with other axes of power to shape inequality; and how it informs scientific knowledge from theorizing to data analysis.</p> </div>','SOC 101, SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1810,2022,2891,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-200','<div class="desc"> <p><strong>Immersive Visual Environments with Commonplace Technology</strong></p> <p>Contemporary theater—especially as performed on Broadway—has become a high tech multimedia production with budgets in the millions. How can emerging theater artists compete with this level of spectacle and/or create new work that is equally compelling? In this course students will learn how to check the boxes of the newest innovations in big budget theater and performance without the financial demands. We will level the playing field by creating forms of high spectacle through economical means. Students will learn to devise spectacular visual stories using commonplace objects. Throughout this project based course, students will study the fundamentals of visual storytelling both through playing with lights and shadow led by cutting-edge artist Christine Marie and through developing story with performance artist and professional storyteller David Crabb. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1811,2022,2892,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arts-studio-art/300/arts-303','<div class="desc"> <p>Advanced study in sculpture, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year.</p> </div>','ARTS 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1812,2022,2893,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-118','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process-oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1813,2022,2894,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-237','<div class="desc"> <p>Marcel Proust’s <em>In Search of Lost Time </em>is considered to be one of the greatest novels ever written. Two 20th century thinkers—an Eastern European philosopher Merab Mamardashvili and a French thinker Gilles Deleuze —argued that Proust’s novel is a philosophical machine: an artificial organ that allows one to gather and re-construct the self. Mamardashvili was the only Soviet philosopher to study Proust’s novel and respond to its Western European interpretations from the perspective of Eastern Europe. He also used the novel to expose and explain the more obscure aspects of the Soviet and Russian worldviews. This course puts to the test Deleuze’s and Mamardashvili’s interpretations of this novel by considering them in conjunction with significant portions of <em>In Search of Lost Time. </em>All of the readings and discussions will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1814,2022,2895,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/200/econ-201','<div class="desc"> <p>This class will introduce students to a variety of frameworks for understanding, measuring, and assessing sustainability. Students will have the opportunity to work on hands-on projects using case studies and/or data. Occidental College will be our laboratory and students may also work with community partners or local firms. Topics vary by semester and could include: waste management, sustainable building, carbon budget, circular economy, corporate social responsibility, ESG, and more.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1815,2022,2896,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/germ-318','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness.?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process-oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. <em></em></p> <p>The course will consist of two parts. First, the Tuesday-Thursday lecture in English (shared with CSLC 118) and second, a German language section in which we read the texts in which we read the texts in the original and discuss the nuances of the text as it reads in the original language. Discussion will be in English. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second Stage Writing requirement.</p> </div>','German 202 or advanced reading knowledge of German. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1816,2022,2897,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/hist-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1817,2022,2898,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-304','<div class="desc"> <p style="margin-top: 10px;">Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. </p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(1818,2022,2900,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/thea-206','<div class="desc"> <p>In this energetic and creatively maddening class, students will explore Shakespeare’s <em>Richard III </em>and several adaptations in a unique and highly charged manner. By yanking the Bard off his high horse, and identifying universal themes and structural innovations inherent in Elizabethan poetic meter, course participants will gain newfound understanding and appreciation for the work and legacy of Shakespeare. Instead of looking at classic works as an untouchable, or “holier than thou,” canon instead we will investigate how playwrights have been inspired by, deconstructed and reconstructed them. In addition to Shakespeare’s <em>Richard III</em>, students will explore several bold adaptations such as Carlyle Brown’s <em>The African Company Presents "Richard III,"</em> <em>Teenage Dick </em>by Mike Lew, as well as Will Power’s own <em>Seize the King</em>. Perhaps most importantly, students will have the opportunity to learn iambic pentameter, construct their own post-modern, Shakespearean mash-up scenes, and learn the very-latest contemporary methods of verse-based performance. In this performance seminar, we will compare and contrast Shakespeare’s metric language with other heightened language forms, from ancient Greek poetry to hip hop lyrics. Filled with rhythm, poetry, and both an appreciation and utter disdain for anything old and crusty, this course promises to be a ridiculously crazy, wild ride for the ages. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1819,2022,2901,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1820,2022,2902,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1821,2022,2903,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/core-core-program/courses/core-97','<div class="desc"> <p>This course is designed to expose students to some of the many cultures of the world, to prepare students for a future in the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one semester unit of credit for participating in eight "field experiences" in their local area. Students will select these from a list of destinations provided by the course instructor and are responsible documenting each field experiences using Moodle. Students will also be required to submit two short response papers related to their field experiences.</p> <p>This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> <p>Students may take this course twice, for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1822,2022,2904,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/pubh-public-health/200/pubh-206','<div class="desc"> <p>Students will conduct a hands-on internship in Los Angeles County, supervised by the course instructor and in collaboration with a community partner, government agency, community clinic, or public health focused non-profit organization. The internship requires 8-hours each week. The topic of the course is flexible and to be determined by the course instructor. It may be repeated once for credit and does not fulfill a Public Health minor elective requirement. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(1823,2022,2905,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/400/psyc-420','<div class="desc"> <p>Introduction to the psychosocial and neurobiological basis of addiction. Substance abuse and behavioral compulsions, including drugs, gambling, eating, and sexual addictions are examined. Additional focus on diversity in addicted populations, the business and politics of drugs, and prevention. Consequences of addictions will be studied at the individual, family, community and societal levels. This course will draw on current research and controversies in the field of addictions. </p> </div>','PSYC 200 , and one of the following: PSYC 322, PSYC 330, or PSYC 334 ',NULL,NULL);
