INSERT INTO course_descriptions VALUES(5406,2023,2922,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phac-physical-activities/200/phac-270','<div class="desc"> <p>This course will teach the techniques of conditioning, leadership and strategy for intercollegiate competition in women''s swimming and diving. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5407,2023,2924,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phac-physical-activities/200/phac-272','<div class="desc"> <p>This course will teach techniques of conditioning, leadership and strategy for intercollegiate competition in women''s tennis. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5408,2023,2925,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phac-physical-activities/200/phac-274','<div class="desc"> <p>This course will teach techniques of conditioning, leadership and strategy for intercollegiate competition in women''s track and field. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5410,2023,294,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/100/phil-101','<div class="desc"> <p>This course introduces students to the central philosophical skills of critical thinking, careful reading, and analytical writing. Students will engage with a range of both historical and contemporary philosophical texts, from multiple regions and time periods, and with a range of philosophical questions that reflect the four content areas that structure our curriculum: (1) History of Philosophy, (2) Diversity in Philosophy, (3) Self &amp; Community, and (4) Mind &amp; World.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5411,2023,2679,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/100/phil-150','<div class="desc"> <p>This course introduces students to symbolic models of the structure of arguments, and to tools for representing those structures and evaluating them as patterns of good or bad arguments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5413,2023,2561,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/100/phil-199','<div class="desc"> <p>This course will be an introduction to case-based reasoning in practical ethics and political philosophy. Students will learn basic philosophical tools for analyzing the moral or ethical dimensions of practical problems, with an emphasis on medical or health related cases and policy. Heavy emphasis will be placed on speaking and critical thinking. May be repeated once for credit. Graded on a CR/NC basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5414,2023,864,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-210','<div class="desc"> <p>We will address some of the fundamental issues in epistemology and metaphysics while reading selections from the works of some important philosophers from the modern period (1600-1800). Among the issues addressed will be the existence of the external world, the relation between the mental and the physical, and the foundation of our knowledge of the future. Philosophers covered will include Descartes, Leibniz, Locke, Berkeley, Hume, and Kant.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5415,2023,2693,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-211','<div class="desc"> <p>This course will explore how central figures in the history of moral philosophy grapple with fundamental questions, such as: What is the best life for a human being? Should I be good? Can I be good? What are our obligations to others, both friends and strangers? Philosophers covered will include Plato, Aristotle, Kant, Mill, and Nietzsche.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5416,2023,2799,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-212','<div class="desc"> <p>Existentialist philosophy is primarily concerned with questions of authenticity, value choice, and freedom: What does it mean to live an authentic human life? Are we free to choose the kinds of people we are and the values we embrace? And what do such possibilities mean for our obligations to other people? In this class we will discuss the problems raised and solutions proposed by existentialist philosophers such as Kierkegaard, Nietzsche, Heidegger, Sartre, Camus, and Beauvoir, through critical examination of their major writings. Our aims will be to understand the intellectual motivations for existentialist thinking and the relevance of their arguments and positions for contemporary philosophy and contemporary life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5417,2023,1718,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-215','<div class="desc"> <p>A detailed examination of some central philosophical texts from history of Western philosophy. Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p><strong>Ockham''s Manifesto: Language and Ontology in the <em>Summary of Logic</em></strong></p> <p>The <em>Summary of Logic</em> by William of Ockham (ca. 1287–1347) has been called "a manifesto masquerading as a textbook." In addition to teaching a revamped system of Aristotelian logic based on the semantic properties of signification and supposition, Ockham''s <em>Summary</em> also outlines a metaphysical program that revolutionized late medieval philosophy. This program came to be known as ''nominalism'', with ''realism'' being its adversary. Ockham''s own brand of nominalism recognizes only particulars – as opposed to universals – belonging to the Aristotelian categories of substance and quality. So among the things that exist are Kiki the cat and the grayness of her fur, but not any general felinity or gray color in virtue of which she''s a gray cat. This ontological reduction is grounded in an innovative linguistic analysis involving the semantics of connotation and the theory of mental language: ''cat'' signifies particular cats, not catness-in-general, and ''gray'' signifies particular gray things while connoting the particular graynesses that they have. In this class, we''ll investigate this doctrine along with the overall relationship between language and ontology in Ockham''s <em>Summary</em>, reading much of Book I along with supplementary material from Ockham''s other works and from other philosophers in Ockham''s context. </p> <p><strong>Medieval and Early Modern Philosophical Theology</strong></p> <p>In pursuit of wisdom, most philosophers throughout history thoughtfully engaged in a project of philosophical theology. Differing from religion, theology – the study (<em>logos</em>) of god (<em>theos</em>) – critically examines the existence, features, powers, and effects of deities. Some of the most sophisticated approaches to these issues were proposed by medieval and early modern philosophers living between about 1000 and 1800 CE. In this class, we''ll try to understand the theological views of a variety of philosophers of this period. Topics will include arguments for the existence of a god in the Latin and Arabic traditions, philosophical mysticism in medieval women philosophers, and the metaphysics and logic of the sacrament of the eucharist. <em>Additional </em><em>Core Requirements Met: Global Connections.</em></p> <p><strong>The Myth of Dualism</strong></p> <p>There are bodies and minds, and the two are fundamentally distinct. Bodies are spatial, publicly observable, and subject to mechanical laws. Minds are spectral, private, and, when things go right, observant of the rules of good reasoning and purposeful action. People are unions of the two— ghost-piloted machines whose constituents, once separated by bodily death, have very different fates: the abandoned vessel decays, while the captain somehow survives. Or so says the myth of dualism, attributed to the 17th-century French philosopher René Descartes by the 20th-century British philosopher Gilbert Ryle, who argues extensively against the "official doctrine" of Cartesian Dualism. But Descartes, ingenious as he was, didn''t think in a vacuum. He absorbed and perpetuated an intellectual tradition stretching from Classical Greece, to the Golden Age of Islam, to the European Middle Ages, and into Modernity—crude labels for internally diverse and complexly interrelated periods of philosophical history. In the first part of this course, we''ll try to locate and trace the myth throughout this roughly two-thousand-year stretch. Our approach will be chronological, and we''ll study the views of numerous philosophers, including Plato, Aristotle, Al-FÄrÄbÄ«, Ibn SÄ«nÄ, Thomas Aquinas, Teresa of Ávila, Descartes, Pierre Gassendi, Elisabeth of Bohemia, Baruch Spinoza, and Anton Wilhelm Amo. In the second part of the course, we''ll consider several approaches to rejecting the paradigm. Forsaking chronology, we''ll first attend to Ryle''s alternative to dualism—logical behaviorism—before reflecting on an assortment of challenges, raised by Ludwig Wittgenstein, W.E.B. Du Bois, Michel de Montaigne, and NÄgÄrjuna, to the very idea of an identifiable, unified, or non-illusory self. <em>Additional </em><em>Core Requirements Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5418,2023,2800,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-220','<div class="desc"> <p>This course will philosophically examine the concept of race and the way race informs identity. Topics include the reality of race, the origins and nature of the concept, and the extent to which race does and should impact our social and personal identities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5420,2023,2680,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-222','<div class="desc"> <p>This course will explore the relation between knowledge and power, focusing on epistemic dimensions of racial and gender oppression. The course will address the following questions: (1) How does propaganda operate, and what sort of threat does it pose to equality in the United States? (2) How do ideologies entrench privilege and injustice, and how can we counteract false beliefs that persist in the face of strong opposing evidence? (3) Is there a distinctively epistemic form of injustice, and, if so, what does this form of injustice look like? The authors that will be discussed may include Michel Foucault, Miranda Fricker, Sally Haslanger, José Medina, Tommie Shelby, and Jason Stanley.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5421,2023,3012,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-223','<div class="desc"> <p>This course is an introduction to Mexican philosophy, and indirectly to Latin American philosophy. We will discuss Mexican contributions to universal questions (such as the nature of art, democracy, humanity, and racial, sexual, and ethnic identity), and we will raise the question of Mexican philosophy (what is it, how is it different from Western philosophy) by situating it in the context of other cultural expressions of Mexican identity, such as Mexican food, literature, and Mexican muralism. Thus, this course is also an introduction to comparative philosophy more generally, since it aims to challenge Eurocentrism by demonstrating that philosophy is grounded in or is an expression of cultural identity. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5422,2023,296,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-230','<div class="desc"> <p>Philosophical thinkers have asked a series of related questions about how to live: What is happiness? What kinds of human activities give our lives meaning? More generally, how must a person live to have lived well? This course will examine a variety of answers to these questions. As a significant component of the course, students will practice living within one of the traditions we study, and reflect upon that experience.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5423,2023,2802,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-231','<div class="desc"> <p>This course will examine the ethical dimensions of our relationship to non-human animals and the environment, including a special emphasis on climate justice as the site of interconnected and global moral, political, and scientific concerns. Some of the questions we will address include: What is the relation between the environment and human health and well-being? Are there reasons other than human health and well-being for protecting the environment? Do nonhuman animals have rights? Do trees? Are we morally permitted to eat/experiment on/keep in zoos/hunt nonhuman animals? How do we compare environmental values against other values in making reasonable decisions?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5424,2023,2803,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-232','<div class="desc"> <p>This course will draw on philosophy, literature, and film in order to address some of the central topics in philosophy of religion. The questions that the course will address include: Does God exist? What is faith, and when, if ever, is it rational? Do we survive our bodily deaths, and if not, should we fear death? The course will also consider implications of answers to these questions for the meaning and value of our lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5425,2023,2695,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-233','<div class="desc"> <p>This course is an introduction to the methods of ethics developed for addressing moral issues in the practice of health care and research. Methods addressed will include: professional ethics (practice standards and professional norms), casuistry, the principles of biomedical ethics, applied normative theory, feminist bioethics, and narrative ethics. We will use these methods to address a host of topics of concern to those participating in health care institutions either (directly) as providers or (somewhat less directly) as policy makers. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5426,2023,3270,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-239','<div class="desc"> <p>We all want to build a socially just community and we believe that our health, as well as that of our family, friends, and neighbors, is a vital component of such a community. At the same time, we also recognize that what justice requires is complex and contested. This interdisciplinary course will first help students conceptualize what justice looks like within the realm of health and medicine through a series of case studies from the ancient Mediterranean and the United States contexts. Through these case studies—which will include a focus on public health, the patient-provider relationship, reproductive health, and end-of-life care—we will scrutinize the conceptual framing of health justice in the past, as well as the health justice foundations of contemporary practices, policies, and institutions. At the end of the semester, we will also give students the opportunity to envision a better way forward, and to begin to enact their vision. Students will design their own social justice final project on a topic of their choice. </p> <p>This course is part of the Humanities for Just Communities Immersive semester. Students wishing to enter into careers in the health professions—whether as physicians, researchers, or policy experts—are especially encouraged to enroll. Co-requisite: FYS 2.</p> </div>',NULL,'FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(5427,2023,2804,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-241','<div class="desc"> <p>Paradoxes and their resolution have played a significant role in the development of philosophy; they still have an influence on philosophy today. While Zeno''s paradoxes of motion where first posed about 2000 years ago there is still not a consensus about what to say about them. Semantic paradoxes such as the liar paradox and the paradoxes of vagueness reveal problems with everyday concepts such as truth and implication. Supertasks reveal problems with our understanding of infinity. What to say about these problems what they show us about how to understand space, time, infinity, truth, and reasoning are some of the issues we will discuss in this class. We will examine various paradoxes, puzzles, and purported paradoxes and discuss different proposed resolutions to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5428,2023,2805,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-242','<div class="desc"> <p>An introduction to the study of the mind and its relation to the body, the nature of human agency action, and personal identity. Questions to be investigated include: Is the mind identical to the brain, or is it something separate and immaterial? Is it possible for computers to think, to have consciousness, and to engage in actions that can be assessed as right or wrong? What makes someone the same person at two different times? Could you continue to exist after the death of your brain with a prosthetic brain, carbon or silicon based, into which your beliefs, desires, and memories have been infused?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5429,2023,2696,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-243','<div class="desc"> <p>This course will explore the relationships between the ways we describe the world and the nature of the world we describe. We will explore such questions as: Do different languages describe the world differently? Do different descriptions of the world correspond to different conceptions of it? Is the world a different place for those with different understandings of it? Could the world be other than it is, and how do we talk about these alternative possibilities? Are there limits to what we can express, and how do those limits correspond to the limits of what there is?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5430,2023,3283,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-246','<div class="desc"> <p>Often referred to as “Critical Thinking”, this course focuses on identifying, reconstructing, and evaluating the kind of reasoning we encounter everyday. It explores the internal relationship between evidence and explanation, as modeled by science and investigation (i.e., diagnostic reasoning), and exercises the skills involved in analytical reading and effective communication by articulating the structure of informal reasoning (i.e., where the truth of the premises does not guarantee the truth of conclusion). Examples of the kind of argument to be considered are those based on correlation, testimony, sampling, enumeration, prediction, and recommendation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5435,2023,2463,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/200/phil-299','<div class="desc"> <p>This course is centered around understanding, and engaging deeply, with applied ethics cases developed for the Intercollegiate Ethics Bowl. These cases typically deal with a broad array of contemporary issues, such as immigration rights, the ethics of self-driving cars, gun control, race/gender on college campuses, etc. In the course, students will research realistic ethical cases, work in teams to develop thoughtful ethical analysis of these cases, and articulate these analyses both verbally and in writing. Throughout the semester, students will prepare for the regional Ethics Bowl competition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5436,2023,298,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-310','<div class="desc"> <p>A detailed examination of some central philosophical texts from the 17th and 18th centuries. Topics vary by semester.</p> <p><strong>Kant''s <em>Critique of Pure Reason</em></strong></p> <p>This course will consist in a detailed study of selected parts of Immanuel Kant''s <em>Critique of Pure Reason</em> – the most important and influential 18<sup>th</sup>-century work on philosophical issues about the relationship between mind and world, and an attempt to synthesize and build upon the rationalist and empiricist approaches to those questions. We will also read selections from some of the central figures in the traditions to which Kant is responding (including Rene Descartes as an exemplar of the rationalist tradition, and David Hume as an exemplar of the empiricist tradition), in order to contextualize the motivations for Kant''s project, and to frame the issues with which the <em>Critique of Pure Reason</em> is engaged.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5437,2023,2807,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-311','<div class="desc"> <p>Ludwig Wittgenstein (1889-1951) is a central figure in the two most important philosophical traditions of the twentieth century: First the attempt early in the century to characterize language thought and the world in terms of the newly available formalism of modern logic and second the attempt to show that any such formalization will fail to do justice to the rich complexity of language as a form of life a form inseparable from the social and historical context from which it springs. We will examine two principal works the <em>Tractatus Logico-Philosophicus </em>and the <em>Philosophical Investigations</em>. There will also be some treatment of the historical and philosophical context of Wittgenstein''s work and life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5438,2023,959,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-312','<div class="desc"> <p>Søren Kierkegaard (1813-1855), sometimes referred to as “the father of existentialism”, was a sharp critic of modern philosophy, institutionalized religion, and what he called “the present age”. For Kierkegaard, the fundamental problem of philosophy was to describe what it means and what it takes to become human—suggesting, ironically, that it is possible for a human being not to be human. The primary purpose of this course is to read Kierkegaard’s most influential texts closely, situate them in their historical and philosophical context (namely, early 19th Century Western Europe), and draw out their contemporary relevance, paying particular attention to the concepts of irony, anxiety, despair, love, and faith. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5439,2023,2808,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-313','<div class="desc"> <p>Fyodor Dostoevsky’s <em>The Brothers Karamazov</em> is a gripping story of murder and romantic rivalries, a wonderfully inventive literary work, and one of the finest philosophical novels ever written. We will read all of <em>The Brothers Karamazov</em> and discuss some of the main philosophical issues that it addresses. Furthermore, we will consider these issues in light of 19th-century Russian culture, and society. Course topics will include: (1) the conflict between faith and reason, and the role – if any – that faith occupies in a good life (2) the nature of love, and the meaning and significance of the command to “love your neighbor” (3) what it means for human beings to flourish, and what sort of community makes flourishing possible. We will also discuss more recent philosophical work and film on related topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5440,2023,2643,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-320','<div class="desc"> <p>Contemporary health issues often raise deep ethical and theoretical concerns. In this course, we seek to connect philosophical and theoretical work on social justice with contemporary issues in health, such as abortion, trans* health, disability rights, domestic violence, international inequities, and health disparities. As a key component of this course, students will partner with a community organization for a semester-long research project, identifying an issue of practical importance to that community and offering an original, theoretical analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5441,2023,2809,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-321','<div class="desc"> <p>James Baldwin explored, with extraordinary sensitivity and insight, issues of race, poverty, and sexual difference in America. In this course, we will engage with Baldwin’s essays, novels, and plays, together with related philosophical work and film, in order to explore the some of the main philosophical themes in Baldwin’s work. We will focus on the roles that love, truth-telling, and self-knowledge play in living a morally good life and in creating a just society.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5442,2023,2935,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-322','<div class="desc"> <p>This course examines philosophical reflections on the Latinx experience, focusing on the contributions of US philosophers of Latin American decent. A sample of questions to be considered: What does it mean to be authenticallyLatinx? Is Latinx identity a racial, ethnic, or political identity? What are some of the overarching lessons of Latina feminist philosophy? Are Latinxs, particularly immigrants, a threat to “American” values, as some argue? What is the meaning of “Latinx” and why is the “x” important? Is Latinx philosophy unique, distinctive, valuable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5443,2023,3221,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-323','<div class="desc"> <p>What is language, and where does it come from? What is it to know something, and how can we achieve knowledge? What is the nature of reasoning, and how should we discern good argumentation from bad? Philosophers of the medieval Arabic-Islamic tradition, such as al-FÄrÄbÄ«, Ibn SÄ«nÄ, and Ibn Rushd, proposed detailed answers to these and other related questions, grounding their proposals in powerful arguments. By adopting a broadly Aristotelian framework, but going well beyond its confines, these figures paved the way for later European Latin philosophy, which borrows heavily from their insights. We''ll study those insights and their reception in this class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5444,2023,685,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-330','<div class="desc"> <p>This course is an examination of the relationship between law and morality. It is organized around three questions: (1) What is law, and what is the relationship between law, morality, and democracy?, (2) Is there a moral obligation to obey the law?, (3) Can we morally enforce the law, that is, is punishment morally justifiable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5446,2023,3284,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-332','<div class="desc"> <p>Ethical issues arise in all aspects of public health. Some questions we may explore are: what are health disparities and what makes them unjust? Should individuals be held responsible for areas of public health concern, such as smoking and obesity? When should the state mandate vaccines? How can and should public health norms impact areas of our lives, such as sexual behavior and birth control? Is public health ableist? <em>This course satisfies the Philosophy Department Experiential Learning Requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5448,2023,2697,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-342','<div class="desc"> <p>This course will examine: (1) the theories of knowledge of such philosophers as Price Russell and Chisholm ("Foundationalists"), (2) some of their critics such as Sellars and Quine, and (3) recent work in naturalized epistemology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5449,2023,2681,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-344','<div class="desc"> <p>What is a language? And what is it to know, to speak, or to understand a language? This class will investigate the project of developing a systematic and comprehensive theory of linguistic meaning: what resources such a theory requires, what kinds of claims it makes, and what consequences it has. We will proceed by examining philosophical questions about the role translation between languages plays in a theory of meaning, about the nature of linguistic reference to the world, and about whether the notions of language and meaning are ultimately coherent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5450,2023,961,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-345','<div class="desc"> <p>How is it possible to study the mind scientifically? This class will explore philosophical issues about the application of scientific methods to cognitive phenomena, including questions such as the appropriate architecture of cognition, the possibility of artificial intelligence, the relation between commonsense psychology and theories in cognitive science, and the possibility of a scientific understanding of consciousness.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5452,2023,2936,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-347','<div class="desc"> <p>Imagination plays important and varied roles in human life, from understanding what someone else is thinking, to creating works of art, to deciding among different potential courses of action. This course will explore philosophical questions about the nature of imagination, including its relationship to belief, desire, perception, and memory, as well as those about its proper use and value, especially in aesthetics and moral/political life. Readings will be drawn from the work of both historical and contemporary philosophers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5453,2023,686,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-350','<div class="desc"> <p>This course surveys results in the metatheory of first order logic including consistency, completeness, decidability, and undecidability.</p> </div>','PHIL 150 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5454,2023,301,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-360','<div class="desc"> <p>What makes something, someone, or some place beautiful? Why do we value beauty? These questions will be explored across multiple domains, including: art, the natural world, the built environment, and human practices, including norms for human bodies. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5455,2023,2682,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-361','<div class="desc"> <p>Philosophical wondering begins in childhood: Where do words come from? Can trees think? What is love? At the heart of this course, Occidental students will have the opportunity to teach philosophy to elementary students at a local school. Doing so provides both an opportunity to serve the local community, an opportunity to reconnect with our own philosophical impulses, and a chance to reflect deeply on a variety of philosophical topics (such as friendship, courage, minds, justice). Occidental students will develop and teach their own lesson plans. In order to do so, students will select a children’s picture book, identify a philosophical question raised by the book, review and selectively incorporate academic philosophical texts. In addition, the class will discuss philosophical views on young children, the nature of philosophical wonder/inquiry, and the value of a (philosophical) education, e.g. Rousseau''s Emile, excerpts from Plato, Marx, and contemporary philosophers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5457,2023,2698,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/300/phil-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements and different Philosophy major requirements.</p> <p><strong>When Race is “Other”: In-Between and Outside of U.S. Race Categories</strong></p> <p>About 1 in 10 Americans identifies as more than one race. This group includes those who have parents of two or more races (e.g., one parent who is Black and one who is White, one parent who is Asian and one who is Pacific Islander, etc.), as well as some Latinx Americans. In this course, we will ask: what can be learned by centering the experiences of those who live “in between” race? Can one have racial privilege in some respects, but not others? Can one identify with a race, even if one ‘passes’ as something else? Why do so many American discussions of race proceed as if this group does not exist? Our course will draw on texts in philosophy, sociology, and literature, as well as the knowledge of guest speakers from Los Angeles and beyond.</p> <p><em>This topic will count towards the </em>Self &amp; Community<em>requirement for the Philosophy major. This topic will satisfy the Core Program U.S. Diversity requirement.</em></p> <p><strong>Philosophy of Food </strong></p> <p>The aim of this course is to demonstrate that food is worthy of philosophy inquiry. We will start with the deceptively simple question, what is food and why is it important? We will quickly move on to specific questions concerning the aesthetic value of food (can food be a work of art?), the nature of food criticism (who am I to tell you what you should like to eat?), a cluster of ethical questions concerning the production and consumption of food (e.g., what exactly is wrong with GMO?, what’s the connection between patriarchy and eating meat?, isn’t ethics fundamentally a question about hospitality?), and broad questions about food and cultural identity (what exactly does “authentic Mexican” mean?). Like any good philosophy course, the point is not to flatter your taste, but to change it, which we will do by cooking together and talking to a number of local food writers and philosophers.</p> <p><em>This topic will count towards the</em> Experiential Learning <em>requirement for the Philosophy major.</em></p> </div>','One course in philosophy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5458,2023,302,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phil-philosophy/400/phil-490','<div class="desc"> <p>Open only to students with senior standing in philosophy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5460,2023,694,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/100/phys-110','<div class="desc"> <p>Covers classical mechanics including kinematics and dynamics of particles and rigid bodies conservation laws and examination of specific force laws. <em>Includes one three-hour laboratory per week.</em></p> </div>','Calculus 1 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5461,2023,318,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/100/phys-115','<div class="desc"> <p>The first of a two-course introduction to physics designed for life science and premedical students. Topics include Newton''s laws of motion gravitation work and energy conservation laws. Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</p> </div>','Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5462,2023,1617,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/100/phys-117','<div class="desc"> <p>An introduction to the physics of waves with examples from optics acoustics and modern physics. Also an introduction to thermodynamics including the first and second law of thermodynamics kinetic theory heat transport and phase transitions. Includes one three-hour lab per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5463,2023,696,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/100/phys-125','<div class="desc"> <p>The second of a two-course introduction to physics designed for life science and premedical students. Topics include electrostatics and electromagnetism electric circuits geometrical and physical optics. <em>Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</em></p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5464,2023,322,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/100/phys-162','<div class="desc"> <p>A survey of the solar system, stars and stellar evolution, galaxies and cosmology. Students are expected to have a strong understanding of algebra and trigonometry. <span style="background-color: #ffffff; color: #222222;">Physics majors cannot take this course for credit toward the Physics major.</span></p> <p><span style="background-color: #ffffff; color: #222222;">Students are expected to have a strong understanding of high school Algebra.</span><s></s></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5467,2023,2835,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-230','<div class="desc"> <p>Introduction to electricity and magnetism electronic circuits electromagnetic induction and Maxwell''s Equations. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5468,2023,699,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-240','<div class="desc"> <p>Introduction to the physics revolution of the twentieth century, emphasizing special relativity and elementary quantum mechanics. Includes the breakdown of classical concepts; light quanta and matter waves; Schrödinger equation and solutions in 1 and 3 dimensions; hydrogen atom, exclusion principle and the periodic table. Other topics include a selection from atomic nuclear particle and condensed-matter physics. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 , PHYS 117 , and PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5470,2023,323,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-261','<div class="desc"> <p>An introduction to the numerical solutions of problems in physics. Applications are drawn from classical dynamics electrostatics magnetostatics relativistic dynamics and chaotic systems.</p> </div>','PHYS 110 or PHYS 115 , PHYS 125 or PHYS 230 , and COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5471,2023,964,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-262','<div class="desc"> <p>Theoretical and experimental electronics fundamental to modern research. Includes one three-hour laboratory per week.</p> </div>','PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5475,2023,868,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-266','<div class="desc"> <p>An introduction to the theory of relativity. The first half of the course focusing on special relativity includes discussions of the relationship between space and time; mass and energy; and cause and effect. The second half of the course presents the fundamentals of the general theory of relativity with an emphasis on the physics of black holes.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5476,2023,1128,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-267','<div class="desc"> <p>An introduction to the field of engineering. Students who have completed either of the introductory sequences in physics are well prepared to apply that knowledge to a wide variety of subjects. Applications covered include static equilibrium elastic properties of materials vibrations thermodynamics thermal properties of matter fluids waves and sound DC circuits and AC circuits.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5477,2023,1619,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-268','<div class="desc"> <p>An introduction to the physics of materials used in a wide range of engineering applications. As time permits topics will include the mechanical, elastic, thermal, electrical, magnetic, and environmental properties of metals, polymers, ceramics, glasses, composites, and "green" materials.</p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5478,2023,2472,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/200/phys-269','<div class="desc"> <p>Special topics in physics selected largely by student interest and requiring no more than introductory physics courses. Possible topics include: variational methods celestial mechanics chaos nonlinear systems. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5482,2023,324,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-310','<div class="desc"> <p>Survey of the elements of advanced mathematical ideas and techniques typically used in physics. Physical examples and intuition will be emphasized throughout. Topics covered will include Div Grad and Curl; matrices tensors and groups; complex analysis Fourier series and integrals; boundary and initial value problems; and special topics as time permits. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 117 and PHYS 230 ; and MATH 214 (may be taken concurrently with permission of instructor) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5483,2023,325,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-315','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques, including literature search, analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5484,2023,702,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-316','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques including literature search analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5485,2023,326,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-320','<div class="desc"> <p>Motion of particles systems of particles and rigid bodies. conservation laws; coordinate transformations both stationary and moving; Hamilton''s and Lagrange''s equations. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 117 , PHYS 230 , and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5486,2023,703,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-330','<div class="desc"> <p>Electro- and magneto-statics Maxwell''s equations electrodynamics boundary value problems radiation. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5487,2023,705,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-340','<div class="desc"> <p>The foundations of the theory of quantum mechanics with applications to physical systems. Formal development of the postulates of quantum mechanics representation of states angular momentum spin and perturbation theory. Applications include the harmonic oscillator hydrogen atom and Zeeman effect. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 240 or CHEM 305 , and PHYS 310 or PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5488,2023,2354,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-350','<div class="desc"> <p>Connects the microscopic properties of the physical world with its macroscopic properties using classical and quantum statistics. Topics include partition functions classical and quantum ideal gasses classical thermodynamics phase transitions and kinetic theory. Includes one ninety minute laboratory per week.</p> </div>','PHYS 240 and PHYS 310 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5489,2023,1300,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-362','<div class="desc"> <p>At the turn of the century a series of discoveries transformed the ancient study of cosmology into a rigorous and well-tested theory of the universe. After a brief introduction to general relativity the equations governing the evolution of the universe will be developed and explored. Evidence in support of this standard model of cosmology and consequences will then be presented including supernovae standard candles the cosmic microwave background big bang nucleosynthesis dark matter and early-universe physics. The course will conclude with a presentation of recent topical subjects in this exciting field of study.</p> </div>','PHYS 117 and PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5492,2023,2476,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-366','<div class="desc"> <p>Review of special relativity. Introduction to the fundamentals of general relativity and gravitation with applications to cosmology. Topics include the big bang theory primordial nucleo-synthesis the dark matter problem gravitational red shift and the expansion of the universe stellar evolution and black holes.</p> </div>','PHYS 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5494,2023,1187,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-369','<div class="desc"> <p>Special topics in physics selected largely by student interest. Prerequisites vary with subject area. Possible topics include: group theory in physics applications of quantum mechanics in atomic nuclear and particle physics introduction to relativistic quantum mechanics nonlinear pattern forming systems hydrodynamic instabilities superfluidity and superconductivity methods of material science. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5495,2023,2937,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-370','<div class="desc"> <p>This course will provide students with a comprehensive and practical view of energy by investigating physical concepts related the way we use energy, energy sources, and connections between energy and broader systems like climate. Topics will include an overview of energy from a physics perspective with a focus on renewable energy including nuclear, solar, and wind power, fossil fuels, energy storage, and energy conservation.</p> </div>','PHYS 110 , PHYS 117 , PHYS 230 , PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5497,2023,328,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-395','<div class="desc"> <p>Research supervised by a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5499,2023,709,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/300/phys-397','<div class="desc"> <p>Supervised investigation by properly qualified students. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5500,2023,1301,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/400/phys-490','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5501,2023,1484,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/400/phys-491','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5503,2023,710,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/phys-physics/400/phys-499','<div class="desc"> <p>Supervised investigation by students admitted by the department to the Honors Program. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5504,2023,330,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/100/pols-101','<div class="desc"> <p>This course introduces students to the study of politics the discipline of political science and the development of public policy. Politics involves the study of power influence and ideas in public and private life at the personal local state national and international levels. Accordingly our exploration will examine how power operates in a variety of settings and will include readings in political theory American politics and law comparative politics research methods and international relations. Open to frosh and sophomores.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5505,2023,1670,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/100/pols-120','<div class="desc"> <p>Introduction to the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5507,2023,1423,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/100/pols-140','<div class="desc"> <p>Law shapes the day to day experiences and functioning of individuals, communities, and institutions in multiple ways. This introductory course examines the diverse connections and relationships of law and society. The course will draw on theoretical and empirical perspectives from a diverse range of disciplines (such as legal studies, sociology, anthropology, and political science) to explore law and law’s role within the United States and internationally. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5508,2023,1553,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/100/pols-150','<div class="desc"> <p>This course is an introduction to the study of politics and political theory through prominent Western political theorists from the Ancient Greeks to the 20th Century. Course themes include theories of human nature the origins of law and government the rise and development of different political institutions and citizen relationships with the state.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5510,2023,712,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/100/pols-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5511,2023,2744,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5512,2023,2480,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-201','<div class="desc"> <p>This course examines how the mass media affects democratic politics in the United States. In the U.S., the media is comprised of various news sources, including mainstream news outlets (e.g., ABC, CBS, NBC, The Washington Post, The New York Times), cable news shows (e.g., CNN, Fox News, MSNBC), online blogs, talk radio, online video platforms, and satirical political comedy shows. In the growing Internet age, news is also delivered via social media (e.g., Facebook, Twitter, Snapchat), giving individuals a vast array of diverse political information. In this course, we aim to understand how information is delivered to citizens, what impact it has on them, and how the media may affect public policy. In general, in this class we work toward a better understanding of the media’s role in American politics.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5513,2023,1302,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-202','<div class="desc"> <p>This course examines how gender influences who participates in the American political process, from voting to campaigning and holding elected office. The course also examines how public policies are gendered in their design, implementation, and outcomes. The course adopts an intersectional approach, asking how gender interacts with other identities, including race, class, ethnicity, sexual, and disability, to fully understand how ideas about masculinity and femininity shapes access to political power in American society.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5514,2023,331,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-203','<div class="desc"> <p>The goal of the Campaign 2020 Internship class is to provide students with an experiential understanding of the practice of electoral campaigns. This course must be taken in conjunction with the POLS 204, Campaigns and Elections. Together, the two courses allow students to gain a deep understanding of the theory and practice of electoral politics in the United States. For Fall 2020, students will actively participate in an internship with a campaign of their choosing in their hometown or the Los Angeles County District Attorney’s race, which the <em>New York Times</em> has called the most important DA race in the country because of growing concern about the problems within our criminal justice system, including racism, policing, and incarceration. The internships will be done remotely, so it doesn’t matter whether students are living at home or on campus. Students will be expected to participate in their internship at least 8 hours per week during the fall semester. Students will schedule their internships for times that are mutually convenient to themselves and their campaign supervisor. Paired with the exploration of scholarship of Campaigns and Elections in POLS 204, students will connect the concepts learned in the classroom to their experiences in the campaign internships. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 204',NULL);
INSERT INTO course_descriptions VALUES(5515,2023,1303,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-204','<div class="desc"> <p>Students in this course will analyze historical and contemporary election campaigns in the United States, exploring such issues as the role of money, media, public opinion, voter registration laws, voter suppression, campaign strategy, staffing, and other topics. They will also examine the role of identity, alternative electoral systems and campaign reform options. The course will offer a particular focus on the most current election season, including campaigns for president, Congress, governor positions, and others. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 203 ',NULL);
INSERT INTO course_descriptions VALUES(5516,2023,1424,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States and to assess how these communities seek political empowerment as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life such as the economy the state and the cultural system on the one hand and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States.; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications based on race class gender national origin and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5517,2023,332,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-206','<div class="desc"> <p>This course is an exploration of the historical and continuing significance of race in the American political system. The relevance and role of race in shaping political institutions public opinion political behavior and public policy will be examined. Special attention will be given to theoretical debates surrounding the meaning of race and how this changes depending on political context.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5518,2023,966,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-207','<div class="desc"> <p>This is a course about urban politics that takes Los Angeles as its case study. Because of the pattern of growth in the area Los Angeles is broadly defined to encompass the city the county and the region. Since politics is the study of power we will examine power in the context of the city; who has it who seeks it how has it shifted over time and what consequences result from it being exercised? Significant attention will be paid to the agency of those who have at various times had the least power in the city; how are they represented or not represented how can they influence the exercise of power? Many look to Los Angeles as a paradigmatic city. We will query the appropriateness of this observation as we identify key concepts in urban politics apply them to Los Angeles and then consider how much Los Angeles sets follows or deviates from trends.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5519,2023,1029,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-208','<div class="desc"> <p>Examination of the impact that social protest movements have had on our society -and lessons that can apply to the current period. Case studies of the agrarian revolt (the Populists) the labor movement the women''s movement the civil rights movement the peace movement the student movement the environmental movement and the consumer/neighborhood movement. Topics include: What factors lead people to participate in social movements and political protest? Why do certain historical periods seem to feature large-scale protest and upheaval while others do not? How are social and political movements related to mainstream politics such as elections political parties voting and lobbying? What is the role of leaders activists and organizers? What strategies and tactics do movements employ? What does "success" mean for a protest movement? Do protest movements make a difference in achieving more social justice and changing public policy? In addition to classroom discussion attendance at a weekly film series is required.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5520,2023,3237,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-220','<div class="desc"> <p>From extreme weather events to insurrections, crisis seems to consume politics in the United States and the globe. This course examines political leadership, public policymaking, and public opinion during crisis, identifying how crisis transforms politics-as-usual and what these transformations mean for democratic stability, human rights, and citizen wellbeing. The course will focus especially on the politics and policy of the COVID-19 pandemic, exploring to what extent the coronavirus both is and is not a “regular” type of crisis. Topics include: the concentration of policymaking in the executive branch, with consequences for democratic governance; how crisis shapes citizens’ tendencies towards extremism, polarization, and violence; and how crises differentially affect marginalized social groups—and when governments do and do not consider marginality and intersectionality in crisis response and recovery. Throughout, the United States’ pandemic experience will be compared with that of other countries and world regions. </p> <p>Sub-field: <strong>AMERICAN POLITICS or COMPARATIVE POLITICS </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5521,2023,1485,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-221','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century with a focus on contemporary democratic politics. The course will discuss the historical institutional and social forces that have both accelerated and opposed democratization and will cover topics of current concern to the region including economic development security and the rule of law the design of political institutions human rights and social movements.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5522,2023,1620,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-223','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal" "populist" and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems including the United States; and the challenges democracies are facing in integrating formerly marginalized populations including women poor and the indigenous. It will examine the US policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5523,2023,715,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-226','<div class="desc"> <p>This course is an introduction to 20th Century Chinese politics. The course will explore the historical background to the current Chinese situation. Students will also examine the politics of China under Mao and during the subsequent reform period including the role of China in global politics.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5524,2023,1305,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-227','<div class="desc"> <p>A comparative analysis of the history culture and contemporary politics of the four countries in the dynamic East Asian region: China Japan Korea and Taiwan. This course will also cover the political economy of the East Asian industrialism.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5525,2023,1031,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-233','<div class="desc"> <p>This course is an introduction to international security and strategic studies. This field is fundamentally about both the use of force by and violent conflict among states and non-state actors. The course will be guided by general theoretical questions regarding security: How does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: How do states and non-state actors use force to persuade their enemies to take (coercion) or refrain from taking (deterrence) a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure the intensity duration and consequences of military action? We will have a particular focus on emerging transnational security issues intra-state security and the relationship among security development and state failure. Pursuing answers to these questions will require an approach that integrates theory history and current events.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5526,2023,1082,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-235','<div class="desc"> <p>This course focuses on the evolution of U.S. foreign policy in recent Administrations with special emphasis on the post-Cold War period. Attention is paid to American policy toward "emerging issues" for example the global environment development policy in the North/South dialogue ethnic violence and nationalist civil wars human rights and humanitarian relief. It explores how policy is formulated and implemented and analyzes the relationship of foreign policy to American economic and defense policies. It examines U.S. policy toward major regional power configurations-in Europe the Far East Latin America the Middle East South Asia and Africa.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5527,2023,2355,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-243','<div class="desc"> <p>An introductory examination of the values, principles, and practices of restorative justice. The course will draw on examples of restorative justice from the United States and internationally. Topics in the course will include competing theories of justice, informal and formal approaches to restorative justice, truth telling, reconciliation, and process of reintegration. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5528,2023,335,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-244','<div class="desc"> <p>This course provides an introduction to constitutional law and constitutional theory examining the ways in which the Constitution distributes power among the branches government in the American political system and limits the exercise of those powers. The course will also consider the role of the judiciary in creating legal and political boundaries for society. Throughout the semester this course will focus not only on legal doctrine but also on the broader intellectual and political context in which it evolves. Using constitutional law cases and moot courts the course will explore the role of the United States Supreme Court as a civil liberties policymaker and the process through which decisions are reached. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5529,2023,719,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-245','<div class="desc"> <p>An intermediate course in constitutional law and theory with a focus on how the Constitution protects individual rights while accommodating the often-competing claims of state, groups and communities. Much of the course will be dedicated to the jurisprudence surrounding the 14th Amendment and the rights it has been found to protect. Specific rights and liberties covered may include racial equality, reproductive autonomy, freedom of expression, and freedom of religion. Students will be assessed primarily through mock judicial opinions and analytical essays analyzing controversies in constitutional interpretation. Disputes over rights and liberties will be treated not solely as legal questions, but as entry points into enduring questions about the character of the American system of government. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 or POLS 140 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5532,2023,1621,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-250','<div class="desc"> <p>American intelligence has often been at the center of the major national security controversies since the 1945. This course will survey the history of those controversies as they involved the US intelligence community, the outbreak of the Cold War and the US-Soviet competition but also the post-Cold War crises in Europe Asia Middle East and elsewhere. The basic question is: How does intelligence influence foreign policy and strategic decisions? This course provides an overview of the theory and practice of U.S. intelligence. It details the sources and methods used by collectors the nature of intelligence analysis and the complex and often difficult relationship between intelligence agencies and policymakers. It also contains a short history of the U.S. intelligence community and evaluates the ongoing efforts to reform it in an era of greater transparency. <em>Not open to first year students.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5533,2023,1032,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-254','<div class="desc"> <p>This course will examine American political thought as it sets out and responds to the founding of the country. Specifically, we will read the Federalist papers, consider the impact of the American Revolution on the French Revolution, and explore how thinkers have reckoned with the American founding into the 21st century.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5534,2023,1306,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-256','<div class="desc"> <p>This course will introduce students to several core analytical approaches in moral and political philosophy including consequentialism utilitarianism distributive justice freedom autonomy and an ethics of care. Students will apply these approaches to case studies in ethical decision-making in politics and policy and students will weigh arguments in favor or against specific courses of action. As such this course bridges readings in moral and political philosophy with "real world" problems confronted by policymakers and leaders. In evaluating resolutions to these problems students will sharpen their critical-thinking and decision-making skills. This is a course in applied ethics with material drawn both from philosophy and from policy.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5535,2023,969,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-257','<div class="desc"> <p>This seminar surveys the historical roots of modern conservative and libertarian political ideas with particular attention to the persistent tension between tradition and innovation. The purpose of the seminar is to enable students to recognize recurring themes that have shaped political thought and action over several thousand years. Students will be graded on weekly essays and seminar participation.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5536,2023,720,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-258','<div class="desc"> <p>Is “racism” the appropriate concept to describe our contemporary racial problems? Many scholars have rejected the idea that the persistence of a number of racial ills – like racial inequality, racial discrimination and racial segregation – in the contemporary moment is evidence that racism also persists as a problem in the twenty-first century. “Racism,” these scholars argue, more accurately describes the Jim Crow South and the people in that era who consciously held explicit beliefs about white superiority over all other races. Though acknowledging changes in racial climate and the terrain of acceptable speech with regards to race, other scholars think that unequal racial outcomes, institutional practices and ideological beliefs connect our contemporary racial problems to racial problems that occurred in the 1960s and earlier. This course is an introduction to the scholarship on racism and has as a central aim to get us to judge together whether “racism” is the appropriate concept to describe and provide a frame through which to understand our contemporary problems concerning race. If it is, which accounts of racism are the most compelling to shed light on our current racial circumstances? What about these accounts are particularly pertinent? What can’t the accounts of racism addressed in class explain? If racism is not the right concept to capture our current struggles with race (or all aspects of it), what concepts if any do a better job and why? To facilitate a critical interrogation of the concept racism, this course will cover sociological, historical, social psychological, philosophical and political accounts of racism and related concepts like racial injustice, racial prejudice, race relations, and racial inequality.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5537,2023,1486,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-260','<div class="desc"> <p>The goal of the Community Law Internship is to provide students with an experiential understanding of the practice of public interest law and community lawyering. The Community Law Internship must be taken simultaneously with POLS 340 which establishes the theoretical foundation for the co-requisite courses through the exploration of scholarship in the areas of: progressive legal practice community collaboration critical reflection social justice activism and community organizing. The Community Law Internship allows students to learn through direct experience about the practice of public interest law in Los Angeles as well as examine how social structures and related identity categories such as gender, race, ability, sexual orientation, and class interact on multiple levels to create social inequality. All students enrolled in the Community Law Internship work with a community-based legal organization engaged in public interest law practice a minimum of 15 hours each week. The unique approach of integrating POLS 340 and POLS 260 takes advantage of Occidental faculty expertise and the wide-range of community-based educational opportunities available in Los Angeles. Permission of instructor required.</p> </div>',NULL,'POLS 340',NULL);
INSERT INTO course_descriptions VALUES(5538,2023,722,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5540,2023,1307,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-270','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, POLS 272) simultaneously. Students will participate in the daily activities of a campaign for United States President or United States Senate in a key "battleground" state. Students will gain experience in the highest level of politics and gain an understanding of how a national presidential campaign or a statewide United States Senate campaign is operated. Students will learn about political strategy voter contact and turnout messaging and polling communications volunteer recruitment and team-building fundraising and other key aspects of campaigns. The internship will involve working full-time (a minimum of 40 hours a week) from the first day of class until Election Day. Following that ten-week campaign fieldwork internship students will return to campus and participate in two seminars as part of Campaign Semester. Campaigns involve long hard days. The staff that students will work with will typically be working at least 14-16 hour days. Although students are required to work at least 8 hours a day they are likely to work more. As part of the Campaign Fieldwork Internship students will be required to read three books-biographies of each major party candidate and a book describing previous presidential campaigns. Students will be required to maintain an internship journal that will be handed in at the end of the 10-week internship. The journal will describe their activities (including the projects they work on campaign meetings and events relationship of the campaign to the media and to constituency groups) the internal dynamics and work of the campaign the different roles and tasks of staff and volunteers in the campaigns the way the media reports on the campaign the students'' reflections on these matters and at the end a summary of the campaign outcome. Students will be required to email the supervising Occidental faculty member at least once a week about their activities and reflections. The students will be supervised in the field by a campaign staff member. Students will participate through teleconferencing in a two-hour course meeting with other students and faculty three times during the semester. Students who will be working in different parts of the country will stay in touch with each other as well as with the faculty through Moodle a web-based course management system. The system allows faculty members to post readings facilitate discussions give and receive assignments etc. Students in various parts of the country will thus form a virtual classroom and on-line learning community. Some students may wish to document their experiences on the campaign trail observe events and interview staff and volunteers by making videos. If so these should be posted to the faculty and other students via the internet. Enrollment limited to students participating in the Campaign Semester Program. </p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5541,2023,1308,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-271','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. In this course which will take place during the last five weeks of the semester students explore theoretical and applied concepts pertaining to United States political campaigns. Students will examine the role of money media candidates interest groups leadership gender race and political parties in terms of who wins and loses elections. Learning will take place through assigned readings professor lectures guest lectures from campaign experts and candidates and peer dialogues. Student learning will be assessed by their contribution to the classroom experience (discussion dialogue) discussion of assigned readings and examinations. Enrollment limited to students participating in the Campaign Semester Program. The program is open to all Oxy students regardless of major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5542,2023,1309,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-272','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. This course entails production of a 25-page research essay addressing a major question pertaining to campaigns in American politics. Each student will work with a professor to craft a high-quality research paper that enters the academic debate on their selected topic incorporates extensive secondary data and existing research and presents original analysis based on the student''s campaign fieldwork. Enrollment limited to students participating in the Campaign Semester Program. Satisfies the Second-Stage Writing Requirement.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> <p>Subfield: American Politics</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5543,2023,1343,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-280','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics credits for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> will work four full days per week in an internship in a political office non-profit corporation or for-profit company engaged in political or policy work. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5544,2023,1344,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-281','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course develops leadership skills through the themes of public speaking professional writing networking interviewing and giving and receiving feedback. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirements for the major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 280 and POLS 281 and either POLS 282 POLS 283 POLS 284 POLS 285 or POLS 286) simultaneously. </p> <p>Students enrolled in the Washington Internship Institute in D.C. are required to take a political leadership seminar that explores how active global citizenship can advance career goals. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5545,2023,1554,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-282','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on environmental law and public policy. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(5546,2023,1555,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-283','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on public health policy in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286).</p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(5547,2023,1556,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-284','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on women''s leadership in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(5548,2023,1345,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-285','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on politics and public policy in the Washington D.C. context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(5549,2023,1346,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-286','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on international relations. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills International Relations requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281 and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously.</p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C</strong>. are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(5550,2023,2837,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-287','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> <p>Subfield:<strong> American Politics</strong> or <strong>Comparative Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5552,2023,338,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-295','<div class="desc"> <p> Topics in Politics. Can be repeated once for credit if topics differ.<em>NOTE: Different topics may satisfy different Core Program requirements</em>.</p> <p><strong>Classical Quest for Justice</strong></p> <p>The questions at the heart of classical political philosophy are very simple, even if the treatments of them by the ancient philosophers are extremely complex. What is justice? What does it ask of us as individuals? What does it demand of political communities with respect to their internal structure and in their interactions with other communities, especially in times of war? Finally, to what extent are the demands of political life compatible with the radical questioning of philosophy? In this course we will engage with these questions via careful study of some of the greatest works of Ancient Greece, focusing principally on Plato’s <em>Republic </em>and Thucydides’ history of the Peloponnesian War. These texts will be approached not only as crucial documents for our understanding of another culture, but also as works that address enduring questions of moral and political life. <em>Core Requirement Met: Pre-1800 (CPPE)</em></p> <p>Subfield: <strong>Political Theory</strong></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start;"><strong>Mass Incarceration, Race, and Health Justice</strong></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start;">This course analyzes the contemporary United States carceral system and social-structural pathways (e.g., poverty, housing, education, and policing) of mass incarceration through a health justice framework. As a legal framework aimed at addressing health disparities, health justice elevates how racism, social control, bias, privilege, as well as the political and legal systems in which they are embedded, influence the social determinants of health. The course will pay close attention to the evolving antiracist health equity movement and how structural discrimination, in particular racism, operates as a root cause of health inequities before, during, and post incarceration. The capstone project of the course follows a research-to-practice model, in which students will present upstream legal and policy interventions to address the racialized and health-harming nature of mass incarceration. <em>Core Requirement Met: United States Diversity</em>.</p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start;"><strong>Comparing Colonial Legacies</strong></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start;">A comparative analysis of colonial governing practices, processes and modes of decolonization, and their long-term effects on the states and societies of the postcolonial world. Critical questions focused on in this course will include the relative political legacies of different types of colonialism (i.e. settler, exploitative, internal) and different colonial powers, the effects of colonial policies regarding ethnic boundary-making, and the implications of enduring ties of various kinds between the post-colonial states and the former metropole. The geographical scope of this course will be broad, including, but not limited to, Latin America, the former Soviet Union, Sub-Saharan Africa, South Asia.<em> Core Requirement Met: Global Connections.</em></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start;"><strong>Politics of Development</strong></p> <p class="MsoNormal" style="margin-left:0px; margin-right:0px; text-align:start;">A comparative analysis of the politics and economics of states in the “developing world”, including an introduction to theories that link variation in political systems to levels of economic development. This course will also analyze questions such as the relationship of natural resource dependency to political regime characteristics, the determinants of foreign aid allocations, and the origins and roles of international development organizations. The geographical focus of the course includes Africa, Asia, Latin America, the Middle East, and the former Soviet Union. <em>Core Requirement Met: Global Connections</em>.</p> <p><strong>Politics of Immigration</strong></p> <p>Immigration is one of the most hotly contested issues in American politics, and has been for some time. Much of the debate about how to craft immigration policies has come from politicians at the national level in the U.S. Congress, which has the responsibility to create policy, but important voices in the debate also come from state legislatures and community organizations. In this class, we will learn about the central issues regarding immigration that have emerged in both the body politic and in scholarly discourse. Topics addressed will include: why people migrate, why anti-immigrant sentiment is prevalent, the politics of immigration control policies, demographic trends, and notions of exclusion and inclusion. Our goal in the class is to come to a better understanding of the political process regarding immigration and why it matters. <em>Core Requirement Met: United States Diversity</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5553,2023,340,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/200/pols-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,'POLS 295',NULL);
INSERT INTO course_descriptions VALUES(5554,2023,1310,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-300','<div class="desc"> <p>This course is an introduction to the process of conducting political science research including the formulation of research problems research design collection of data and statistical analysis and interpretation. Participants will learn to analyze political science data using statistical packages in a lab setting.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5555,2023,1347,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty housing transportation crime and violence pollution racial segregation and neighborhood change. It also examines how power is exercised by different groups including business citizens'' groups community organizations unions the media mayors and other government officials. The course will also examine the role of city planning and planners conflict and cooperation between cities and suburbs problems of urban sprawl loss of open space water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe Canada and the developing world. Public policies to solve urban problems.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5556,2023,1557,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-302','<div class="desc"> <p>This course examines the institution and practices of the American presidency. More specifically it encourages students to analyze the role and structure of this office as well as different ideas about presidential power and influence. Particular attention is paid to the presidency and policy making media coverage checks and balances the Constitution and public opinion.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5557,2023,1671,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-320','<div class="desc"> <p>Critical examination of the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5558,2023,1623,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-321','<div class="desc"> <p>This course will explore the role of women in politics throughout the globe with an emphasis on case studies from the developing world. Students will examine the development of policy changes that advance gender equality paying attention to how the international system domestic institutions and social movements play in this process. Students will also study how women attain and wield power in local and national politics. The course will further emphasize how gender politics intersects with other forms of identity politics including race ethnicity and sexuality. The course is grounded in the study of comparative politics and will draw primarily on examples from Latin America Africa the Middle East and Asia.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 , POLS 120 , or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5559,2023,341,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-336','<div class="desc"> <p>This course is an examination of how American national security policy is conducted and explores the principles practices and problems related to contemporary American foreign policy making. The course will touch on the basic historical patterns of American foreign policy; however it will focus on current practices and operation of the foreign policy machinery in Washington as well as examine some contemporary cases to demonstrate how the system works. Close attention will be paid to the structures of national security decision-making involving the Presidency and the National Security Council the Congress the Departments of State and Defense as well as the Intelligence Community and other new national security agencies. For Politics, UEP, and DWA majors only.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5560,2023,1487,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-340','<div class="desc"> <p>Pursuing effective change particularly in today''s complex world requires creative collaborative efforts to identify and implement solutions to achieve a more radically participatory democracy. Lawyering for Social Justice considers the related theories of legal scholars who have reconceptualized legal practice to transform systems through both legal and community knowledge. These include theories of community lawyering, lawyering for social justice, rebellious lawyering, democratic lawyering, and collaborative lawyering. All of these theories impart a common vision of lawyering for social change in stark contrast to the traditional or regnant model. The praxis of Lawyering for Social Justice (POLS 340) and Community Law Internship (POLS 260) creates a balanced context from which students develop critical consciousness question assumptions of power privilege and identity learn to respect community decision-making capacities expand their understanding of the importance of relationships in the pursuit of social change and remain open to learning from the lived-experiences" of the community. The unique co-requisite course design allows students to engage in a weekly seminar (POLS 340) and work as interns in community-based public interest legal service organizations (POLS 260). Students also interact with Los Angeles activists and lawyers as part of a speaker series. Instructor permission required. Can be repeated once for credit.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,'POLS 260 ',NULL);
INSERT INTO course_descriptions VALUES(5563,2023,1311,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-345','<div class="desc"> <p>This course examines constitutional criminal procedure through an analysis of Fourth Amendment constitutional restraints on activities during the investigatory stage of the criminal process. Exploring Supreme Court decisions through doctrinal analysis and simulations the course questions the Supreme Court as a policymaker seeking to balance privacy rights with governmental intrusions.<em> Not open to first year students.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5564,2023,2484,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-351','<div class="desc"> <p>Alexis de Tocqueville, John Stuart Mill, and Friedrich Nietzsche are three of the most influential theorists to grapple with the tradition of liberal political thought. The first two are friendly critics who seek to fortify liberalism against what they see as its latent pathologies, while Nietzsche is a not-so-friendly critic who wants to overturn it entirely. Given that liberalism is under attack today from both the right and the left, there is much to gain from serious study of their reflections. In this course, we will compare the strengths and weaknesses of their diagnoses of the present and visions for the future. Guiding questions for the course will include the following: Does liberal democracy uplift human beings, or degrade them? How should the competing demands of individual independence and community solidarity be balanced? How can we best counter modern society’s tendency to engender stifling conformity? What is the significance of Christianity for the cultural heritage of Western society? What role, if any, should religion play in societies of the future? Finally, what does human flourishing consist of, and what kind of sociopolitical conditions best facilitate it? The culminating assignment of for the course will be a substantial research paper on one or more of these thinkers.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5565,2023,1312,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or BLST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5566,2023,1672,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-355','<div class="desc"> <p>Franz Fanon, one of the most influential thinkers of the twentieth century, is a canonical figure in critical theory, broadly, and Black studies, postcolonial theory, political theory, critical race theory, continental philosophy and Africana philosophy, specifically. A francophone scholar, Fanon identified as black and was concerned with articulating the modern problem of white supremacy and the conditions for liberation for all people.</p> <p>This course is organized around a single book he wrote, <em>Black Skin, White Masks</em>. To understand what Fanon is up to in this text, we will also consider this book’s relationship to the philosophical traditions of psychoanalysis and phenomenology. To this end, we will read texts by Sigmund Freud, Anna Freud, Maurice Merleau-Ponty, Simone de Beauvoir, Jean-Paul Sartre, Jacques Lacan, and Georg Wilhelm Friedrich Hegel. Throughout the course we will switch between two distinct but related enterprises. On the one hand, we will try to understand how Fanon uses the specific set of psychic problems black people face and his articulation of the lived experience of the black in a white world to articulate his account of white supremacy and liberation. And on the other hand, we will seek to understand what his psychoanalytic and phenomenological counterparts are up to in their text to discern the significance of Fanon’s work in relation to the concerns within these philosophical traditions.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5568,2023,3157,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5569,2023,725,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/300/pols-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5570,2023,726,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pols-politics/400/pols-495','<div class="desc"> <p>Politics majors are required to take Politics 495 in fulfillment of their senior comprehensive obligation. They therefore should have met or be in the process of meeting all requirements for the major. The Seminar meets in the spring semester but students will be expected to submit proposals for their research papers in the fall semester prior to the actual meeting of the Seminar. The Seminar itself will engage all students in an analytical review of a wide range of materials from various aspects of the discipline and will require that students write a major research paper in one particular sub-discipline of the field. Students qualifying for College Honors will be given an opportunity to write research papers that will be evaluated by the department for honors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5572,2023,1130,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/100/psyc-101','<div class="desc"> <p>Introduction to the primary subject matter areas assumptions and methods of psychology as the science of behavior. Topics include: physiology, learning, perception, motivation, development, emotion, cognition, social processes, personality, and psychopathology. <em>This course is a prerequisite for all upper division coursework. Open only to frosh and sophomores. Core Credit only when taken at Occidental. Students with a 4 or 5 on the AP Psychology exam or a 6 or 7 on the IB Psychology exam are not eligible for Psych 101 but may take 200- or 300-level classes.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5573,2023,1190,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/100/psyc-111','<div class="desc"> <p>The average adult possesses over 50000 concepts ranging from physical concepts like "force" and "density" to biological concepts like "growth" and "reproduction" to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich revise and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive developmental and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5576,2023,344,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/200/psyc-200','<div class="desc"> <p>Introduces scientific methodology in the context of psychological research. Basic concepts in scientific inquiry and specific observational correlational and experimental techniques are covered. Includes an introduction to descriptive statistics. This course is a prerequisite to many 300-level courses in Psychology.</p> </div>','PSYC 101 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5577,2023,345,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/200/psyc-201','<div class="desc"> <p>Introduces parametric and nonparametric inferential statistics used in psychological science through analyses of variance appropriate to complex experimental designs. Includes a review of research methods and descriptive statistics and work with statistics software.</p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5578,2023,346,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/200/psyc-223','<div class="desc"> <p>This highly interactive seminar draws on theoretical, empirical, and narrative essays as well as structured in-class activities to provide students with an intellectual, applied, and personal understanding of contemporary intergroup relations. Course topics include: social identity development and implications; prejudice, stereotyping, and group differentiation; privilege, power, and oppression dynamics; conflict negotiation and resolution; and communication and group facilitation skills. Social justice issues are framed for gender, race, class, sexuality, and ability. Effective dialogue seminars are inclusive and enhanced by the participation of diverse identities, multiple disciplines, and a range of political perspectives. Placement form can be found at this link: https://oxy.qualtrics.com/jfe/form/SV_d4pBn2ZnPXYoC8Z Students must complete the placement form prior to advising week.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 , completion of placement form prior to beginning of advising week, and permission of instructor. Students with a background in any introductory social science course are encouraged to consider the seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5579,2023,2563,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/200/psyc-224','<div class="desc"> <p>This course provides students with an intellectual and practical foundation in dialogue<em> facilitation</em>. Participants will <em>apply</em> intergroup relations theory and knowledge about culturally diverse populations as they learn about and attend to group dynamics, conflict management, and intergroup relations pedagogy. Specific attention will focus on multicultural dialogues devoted to Sexual Orientation, Social Class, Race, Gender, and Ability. Training videos and exercises, in addition to small group co-facilitations form the foundation of the course. Group work, including pedagogical development meetings, are required outside of class as preparation for facilitation. </p> <p>Applications due by March 23, 2018. Contact the Professor Rodriguez (jackir@oxy.edu) for application information.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 223 (may be taken concurrently) and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5581,2023,347,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/200/psyc-295','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. Instructor permission required. <em>Graded on a Credit/No Credit basis only. PSYC 101 or PSYC 102 or relevant introductory course in another department and permission of instructor. May be repeated once for credit if the second project is different from the first. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5583,2023,731,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-301','<div class="desc"> <p>This course will introduce general concepts of learning in humans and other animals that will be rooted in the principles of learning developed from nonhuman animal research. Explores fundamental concepts phenomena and principles of learning such as reinforcement Pavlovian conditioning and retention/forgetting. Issues addressed are traditional views of learning biological and cognitive constraints the role of nonhuman animal models and the utility of learning theory.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5584,2023,971,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-302','<div class="desc"> <p>This course focuses on how sensory systems function, with emphasis on quantitative methodologies, neurophysiological mechanisms, structure/function relationships, and ecological contexts. How humans perceive the world is situated in a comparative landscape -- that is, human are assumed to be creatures with much in common with other creatures and yet different in some crucial ways tied to their evolutionary history and habitats. Attention is paid to phenomenology and philosophical issues, such as the relationship between perception and "reality." This course is distinguished from cognitive or social psychology approaches to perception, by virtue of its focus on evolutionarily old, fully embodied, and sensuous experience.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5585,2023,871,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems make decisions draw inferences attend to their environment communicate remember and learn. Much of the material is applied to real-life settings.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5586,2023,2491,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-309','<div class="desc"> Ontogentetic approach to human movement behavior and physical growth from conception to adulthood with emphasis on maturational and environmental factors. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5587,2023,2493,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'PSYC 310L',NULL);
INSERT INTO course_descriptions VALUES(5588,2023,1736,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-311','<div class="desc"> This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance and level of participation of an individual or group. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5589,2023,348,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-321','<div class="desc"> <p>The study of continuity and change across development. Emphasis on application of research methods to issues related to cognitive emotional personality and social development. The course will focus primarily on these issues in infancy and childhood.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5590,2023,349,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-322','<div class="desc"> <p>The study of neural glandular and metabolic processes mediating behavior thought and feelings. This course is identical to PSYC 312 except that students who enroll in PSYC 322 may enroll concurrently or subsequently in the laboratory (PSYC 322L). Core Laboratory Science credit will only be awarded for students completing both PSYC 322 and PSYC 322L. Students who have received credit for PSYC 312 may not enroll.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 <div id="offered"></div>',NULL,NULL);
INSERT INTO course_descriptions VALUES(5591,2023,350,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-322l','<div class="desc"> May be taken concurrently with Psychology 322. </div>','PSYC 200 (Students must earn a grade of C- or better) and PSYC 322 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5592,2023,351,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-323','<div class="desc"> <p>Behavior of individuals and groups in and across social contexts. Topics include self social cognition attitudes and persuasion liking and loving prejudice aggression and social conflict group identity consciousness and social action.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5593,2023,352,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-330','<div class="desc"> <p>The study of psychopathology including diagnosis and classification core dysfunctions and physiological and psychosocial causative factors. Intervention treatment and preventative strategies will also be discussed.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5594,2023,736,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-334','<div class="desc"> <p>Consideration of psychological influences on health and illness including health-and illness-promoting behavior and lifestyles cognitive and emotional processes and social and institutional practices.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 (Student must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5595,2023,972,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-336','<div class="desc"> <p>This course surveys the emerging field of Evolutionary Psychology. It begins with the historical social and political context of evolutionary theory reviews tenets of modern evolutionary theory explores the relationship between evolution and other change processes and applies evolutionary reasoning to psychological phenomena and contemporary social issues.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5596,2023,353,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-340','<div class="desc"> <p>Introduction to the study of theories and applications of psychology in profit and not-for-profit organizations. Representative topics include understanding how ability personality perception motivation leadership and group dynamics affect productivity and worker satisfaction. Issues of fairness and accuracy of assessment will also be discussed. Emphasis is on practical and personal learning of the dynamics of the work environment.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5597,2023,354,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-350','<div class="desc"> <p>The course will survey diverse psychological perspectives on gender and its personal and cultural implications. Will explore: meanings of gender evolutionary physiological developmental and sociocultural roots of gender difference; the relation of gender to cognition personality sexuality health interpersonal relationships and political power; the commensurability of various theoretical approaches to gender.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5598,2023,2513,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-351','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','PSYC 101 , COGS 101 , LING 301 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5599,2023,872,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-385','<div class="desc"> <p style="margin-left:0in; margin-right:0in">The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101 , SOC 101 , HIST 102 , AMST 101 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5601,2023,355,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-395','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required.<em>Graded on a Credit/No Credit basis only.</em></p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5602,2023,738,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/psyc-397','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5603,2023,2492,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/300/pysc-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','PSYC 310L ',NULL);
INSERT INTO course_descriptions VALUES(5604,2023,1489,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-400','<div class="desc"> <p>This capstonecourse will help senior psychology majors to integrate across subdisciplines in psychology consolidate their experiences in the psychology major through review and discussion of primary coursework in psychology and connect their studies in psychology to the roles that psychology plays in society and the professional world. <em>Open only to students with senior standing in psychology (i.e. intended for graduating seniors).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5606,2023,2905,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-420','<div class="desc"> <p>Introduction to the psychosocial and neurobiological basis of addiction. Substance abuse and behavioral compulsions, including drugs, gambling, eating, and sexual addictions are examined. Additional focus on diversity in addicted populations, the business and politics of drugs, and prevention. Consequences of addictions will be studied at the individual, family, community and societal levels. This course will draw on current research and controversies in the field of addictions. </p> </div>','PSYC 200 , and either PSYC 322 , PSYC 330 , or PSYC 334 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5607,2023,873,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-428','<div class="desc"> <p>The study of social cognitive physical and psychological development during adolescence and emerging adulthood. Topics include sexual development and the social consequences of being sexually active the function of family support the increasingly important role of peer relationships drug abuse and antisocial behavior and school adjustment.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5608,2023,357,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-431','<div class="desc"> <p>Introduction to the techniques and processes of clinical psychology and psychotherapy. Topics include major schools of thought and approaches, specific techniques of assessment and treatment, relevant research, assessment of effectiveness, and issues of gender and culture. <em>Open only to seniors or by permission of instructor.</em></p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 and PSYC 330 (Students must earn a grade of C- or better in both) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5609,2023,1349,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-444','<div class="desc"> <p>This course will examine contemporary research on higher-order cognition. Topics will include inductive reasoning deductive reasoning causal reasoning moral reasoning concept acquisition belief formation and analogical inference. Students will read empirical papers representing a variety of experimental methods and a variety of theoretical perspectives.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 200 and PSYC 301 , PSYC 302 , or PSYC 306 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5610,2023,973,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-448','<div class="desc"> <p>Introduction to and evaluation and application of classic and contemporary theories of personality including psychoanalytic humanistic behavioral cognitive and object relations models. Primary sources autobiographies and case studies will supplement traditional texts.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 and PSYC 321 , PSYC 323 , or PSYC 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5611,2023,974,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-460','<div class="desc"> <p>Psychological assessment involves the measurement and evaluation of psychological characteristics including cognitive ability personality traits motivation and more. A blend of theory-driven research and practical analysis techniques will be covered to explain how common and experimental instruments work and to examine whether certain methods are valid in academic organizational criminal and mental health contexts.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 201 ; and PSYC 321 or PSYC 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5612,2023,358,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-490','<div class="desc"> <p>PSYC 490 seminars taught by Dr. Dess, Dr. Chapman or Dr. Schell can be applied to the Neuroscience minor. </p> <p><strong>Psychology and Law</strong></p> <p>Intersection of social science theory and data with law and legal procedure: Topics may include: normative and psychological theories of justice; eyewitness memory, deception detection, investigative interviewing and interrogations; jury selection and jury decision-making; forensic psychology and assessment; corrections and sentencing.</p> <p>Prerequisite: PSYC 200</p> <p><strong>Eating: From Cells to Society</strong></p> <p>Eating is fundamental to life more so than drinking or sex. It infuses the thoughts feelings and behavior of humans and other animals and thus serves as a model system for psychological inquiry. It is also for better and for worse intensely personal and thus serves as a model system for inquiry into the self. This course will explore eating from cellular to cultural levels of analysis. </p> <p>Prerequisites: PSYC 200 and one of the following: PSYC 302, PSYC 323, PSYC 321, or PSYC 336.</p> <p><strong>Teamwork Within Diverse Environments</strong></p> <p>Examination of how individual and group differences influence the performance of workgroups. The course focuses on theoretical and practical concerns related to the key topics of teamwork and leadership as they are performed within the context of a diverse work environment. Some related issues of fairness in managing diversity will also be introduced. </p> <p>Prerequisites: PSYC 201 and either PSYC 340 or PSYC 323. </p> <p><strong>Trauma</strong></p> <p>This course focuses on the experience of and responses to trauma in its many forms - natural disaster war and genocide child abuse assault and violence. The impact of trauma for both the individual and society at large are examined in the context of a stress coping resilience framework. Prevention and intervention strategies will be explored. </p> <p>Prerequisites: PSYC 330.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5614,2023,874,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-498','<div class="desc"> <p>This course involves applied psychological work in a variety of community settings. Students will assist professionals in mental health educational social services business or not-for-profit settings. <em>Instructor permission is required.</em></p> <p>Prerequisites: PSYC 200 and either PSYC 201 or three courses from the Fundamental Domains. For Practicum in Clinical Psychology one course must be PSYC 321 or PSYC 330. For Practicum in Organizational Psychology one course must be PSYC 340. A minimum grade of C- in all prerequisite course and a B average in Psychology courses are required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5615,2023,739,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/psyc-psychology/400/psyc-499','<div class="desc"> <p>Data collection analysis and write-up of Honors thesis. Depending on the structure and timeline of the proposed project a student may take 4 credits in one semester or 2 credits for two semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5618,2023,2838,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/200/pubh-203','<div class="desc"> <p>This course explores the nation''s public health challenges and the ways that public health functions as a combination of science and politics. The course examines the various social, political, and demographic factors that impact population health. Students are introduced to public health concepts and learn to analyze health problems, considering the influence and intersection of race, status, gender, income, education and sexuality. Using data, evidence, and health behavior theory, students evaluate strategies and solutions to address health inequity and improve population health.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5619,2023,2904,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/200/pubh-206','<div class="desc"> <p>Students will conduct a hands-on internship in Los Angeles County, supervised by the course instructor and in collaboration with a community partner, government agency, community clinic, or public health focused non-profit organization. The internship requires 8-hours each week. The topic of the course is flexible and to be determined by the course instructor. It may be repeated once for credit and does not fulfill a Public Health minor elective requirement. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5620,2023,2938,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/200/pubh-209','<div class="desc"> <p>Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5621,2023,2886,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/200/pubh-238','<div class="desc"> <p>This course is designed to introduce the basic concepts, principles, and methods of epidemiologic research. In our pursuit to understand the interplay of risk factors and patterns of human disease and health, we will cover the history of epidemiology, the principles of epidemiologic thinking and of causal inference, the basic measures of disease frequency and of association, and how to compute them. We will also learn about the major types of epidemiologic study designs and explore the major fields of epidemiologic investigation. To better understand the practical application of study methods used in epidemiology, the class has a laboratory component (PUBH 238L). The laboratory component will provide students with the opportunity to apply the concepts from lecture and develop an epidemiological research proposal. Students will work through the research process, moving from developing a health related research question to operationalizing the idea into a research plan.</p> </div>','Statistics ( BIO 268 , COMP 146 , MATH 150 , PSYC 201 , or UEP 305 ) and PUBH 203 ','PUBH 238L ',NULL);
INSERT INTO course_descriptions VALUES(5622,2023,2839,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/200/pubh-248','<div class="desc"> <p>The course will examine major global public health problems and the range of responses from international organizations transnational networks and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as HIV/AIDS malaria unsafe food and water tobacco use and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health including morbidity mortality demography epidemiology and the political social and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political economic social and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5627,2023,2840,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/300/pubh-301','<div class="desc"> <p>This course provides an examination of women''s health across the life cycle, with special emphasis on the structural and societal factors that influence health outcomes among women. It introduces students to public health frameworks for assessing women’s health issues within various contexts. This course uses these frameworks as a basis for examining the relationship between social and cultural factors and women’s health. It provides an overview of the emerging and on-going issues in women''s health, including sexual and reproductive health, contraception, gender-based violence, mental health and substance abuse, in order to understand and address health inequities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5628,2023,2841,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/pubh-public-health/300/pubh-307','<div class="desc"> <p>The community health internship course is designed to provide students with real-world experiences to develop new skills and enhance insights into myriad community health issues and solutions. Under supervision of the course instructor and in collaboration with a community proctor/partner students will intern for 8-hours a week at a health focused non-profit organization community clinic or government agency. Through the internship and course work, students explore and analyze the social, cultural, and systematic barriers to health in Los Angeles and the U.S. Students reflect on and discuss the complexities of keeping communities healthy, considering the impact of policy, identity, power, urban planning and culture. Before registering students should check to make sure that they are available during the preset internship hours. Internship hours and activities can be viewed at the Community Health Engagement website: http://bit.ly/1sDCTeJ</p> </div>','PUBH 203 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5633,2023,1559,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-110','<div class="desc"> <p>A survey of historical and contemporary Native American religious traditions, attending especially to how they have developed amid colonization and resistance. Students will study the broad variety of ways that Native American traditions imagine land, community, and the sacred, and study the range of practices, ceremonies, and cultural institutions related thereto. Students will also investigate how these religious traditions have been contested or negotiated when they came in contact with Christian missionaries, in contemporary treaty rights, and in intertribal new religious movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5634,2023,741,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-120','<div class="desc"> <p>This course is centered around the question: How can we be "well" when the world is beset by the existential issue of climate change? To answer this question, students will study cosmological systems that conceive of human health as fundamentally connected with ecological health, and consider how these systems are responding to the challenges of climatic variability. Specifically, cosmologies from the Asia-Pacific region – where climate change have already fundamentally altered daily life in the form of receding glaciers and flooding islands – will provide students with an insight into how religions and cultural traditions conceptualize health and multispecies flourishing in the face of impacts from climate change that threaten multiple species across ecosystems. The course will be organized around case studies related to land, ocean, mountains, and space, with examples from multiple religious and cultural communities from the Pacific Coast of the United States, to Hawai’i, Tuvalu, Aotearoa New Zealand, Thailand, India, China, and Bhutan. And these case studies will cover examples from multiple moments of the Anthropocene, from the Little Ice Age that began in the fourteenth century CE to the present, as well as incorporate interdisciplinary research from the environmental Humanities, such as anthropology, environmental ethics, political ecology, and religious studies. This course will allow students to see how different cosmologies – both Indigenous and imported – provide people with holistic notions of health, explanations to understand the enormous changes brought by the Anthropocene, and to explore and develop resources for enacting measures that will bring about justice that can benefit human communities and the environment.</p> <p>This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5635,2023,360,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-130','<div class="desc"> <p>This course will explore the history of Jews, Judaism, and Jewish life from the Middle Ages to the present day. In doing so, we will use the widest geographical lens possible by examining Jewish communities stretching from Baghdad to Berlin to Buenos Aires and beyond. In order to illustrate important ideas, frequent use will be made of various primary source materials including literature, film, religious texts, and more. Throughout our study of the past 500-odd years of Jewish history, particular emphasis will be placed on cultural transformation as an index of broader historical processes such as changes in intra-communal authority, European colonialism, relationships with the state, and the development of Jewish secularism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5636,2023,1035,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-145','<div class="desc"> <p>This introductory course uses two themes- experience and authority- to orient and guide students through an historical survey of religion in the United States. We will ask how people have made appeals to religious experience to establish, reinforce, and challenge political and religious authority. In addition to dominant forms of Protestant Christianity, we will learn about the rise of new religions like Spiritualism and Mormonism, Catholic and Jewish immigration in the late nineteenth century, and the growth of religions like Buddhism and Islam in the twentieth. Throughout the course, we will pay special attention to race and ethnicity, gender, and sexuality, asking how religion has alternately served as a vehicle for liberation and venue of oppression, and how religious debates dovetailed with the pressing social issues of the day.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5637,2023,1624,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-147','<div class="desc"> <p>In the recent history of the Americas, many groups have founded intentional communities shaped by the ideals of what a faithful, utopian society ought to look like. Some aspiring utopias, like that of the People''s Temple in Jonestown, Guyana, ended in dramatic displays of violence and death. Others, like the Mormons in Salt Lake City, have succeeded in the face of sustained adversity. But most land somewhere in between, sustaining themselves through partial integration with dominant society. In this course, we will study different intentional religious communities - often called "cults" or "sects" by outsiders - throughout the Americas. As we study the Oneidan "free love" community, an ayahuasca church in Brazil, an early Rastafari group in Jamaica, we''ll ask questions like: Why have religious people sought to separate themselves from society? How have they appealed to scripture or revelation to justify their separation? What challenges - such as external political pressure or internal strife - have they faced? What groups have been "successful," and what are the measures of success? And what do these attempts at establishing utopias tell us about what it means to be religious?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5638,2023,742,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-150','<div class="desc"> <p>This course will introduce students to some of the major themes, issues, people, places, sights, and sounds of Islam past and present. This course is intended to highlight the manifold expressions of Muslim life through diverse historical, cultural, and geographical contexts. Its two broad aims are: 1) to provide students with basic knowledge of Islamic history, belief, and ritual life; and 2) to equip students with knowledge for critically and actively analyzing discussions of Islam in media and contemporary world events.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5639,2023,1673,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-160','<div class="desc"> <p>A large part of the success of Buddhism has been in its ability to travel and adapt to local cultural traditions, providing communities with a rubric for living a meaningful life. This course will provide an introduction to these traditions by looking specifically at Buddhist concepts and practices within human life and life cycles. We will ask: What do ritual and textual traditions about human life in various cultures tell us about Buddhist values and concepts of how to deal with suffering and thereby to life and die well? Are there differences between classical textual ideas about these topics and Buddhism as it is lived through ritual and community practice? How do both textual and ritual traditions maintain human life?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5640,2023,2842,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-167','<div class="desc"> The Zen school of Buddhism has long claimed itself as a tradition "beyond words and letters," or as a body of teachings that can be transmitted only through ineffable experience. And yet, Zen Buddhists have been some of the most productive writers and orators, producing volumes of biographical narratives, religious legends, and apologetic scholarship. In this course we will study Zen sources as a way to understand the social, institutional, and pedagogical power of the Zen school as it grew in Japan from the 12th century. We will seek to understand how Zen Buddhists in Japan balanced their own religious obligations with broader societal responsibilities, as well as how the Zen tradition reconciled its religious ideals with its practical concerns. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5641,2023,975,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-190','<div class="desc"> <p>From the 1st-6th centuries CE, early Christian communities throughout the Mediterranean had different ideas about who Jesus was, what kind of movement he inspired, and what it meant to be or to act like a Christian. In this course, students will investigate the variety of early Christian communities that structured their movements around the figure of Jesus by studying their primary sources: stories, letters, sermons, theological treatises, art, artifacts and architecture. Students will explore the practices and ethics that dictated the daily lives of early Christians, how they interacted with their Jewish and “pagan” neighbors, the theological issues debated among early Christian communities, including charges of "heresy" and the development of orthodoxy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5643,2023,743,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/100/rels-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5644,2023,1036,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-200','<div class="desc"> <p>We are currently in the midst of a "psychedelic renaissance." Over the past two decades, university-backed research institutes, non-profit organizations, and capitalist entrepreneurs around the world have celebrated drugs like psilocybin and LSD as powerful therapeutic tools capable of helping people work through trauma and improve well-being. And according to some prominent researchers, the "mystical experience"--or a feeling of union with the divine--produced from these drugs is key to their therapeutic efficacy. But is this claim valid? And why would scientists make such a claim in the first place? In this course, we will answer these and related questions by exploring the global cultural history of psychedelics from the early twentieth century to the present. With special attention to the relationship between psychedelics and religion, we will examine everything from these substances'' ritual consumption in indigenous communities and in pre-modern Europe, to scholars'' and researchers'' use of religious texts to explain psychedelic experiences, to legal issues surrounding psychedelic use and religious freedom.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5646,2023,3233,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-204','<div class="desc"> <p>The project of queer theory is invested in destabilizing essentialist identity constructions, especially the links between gender, sexuality, and desire. Religious discourses have historically been a powerful force in buttressing such essentialist constructions of identity and thus have, in many instances, undermined the project of queer theory. Yet, a number of scholars have found queer theory, queer experiences, and/or queer identity useful lenses through which to engage with religious texts, practices, and communities. With course materials including scholarly readings, as well as films, documentaries, music, podcasts, comedy and visual images, we will pay particular attention to the lived aspects of queer engagements with religion. For instance, we will cover topics such as Judeo-Christian reinterpretations of Genesis to make room for same-sex marriage; conceptions of transgenderism in the time of the Prophet Muhammad; gender fluidity in iconography of the Buddhist boddhisatva, Kuan-yin; gender role mixing in Tantric Hindu ritual; and, Native American postcolonial approaches to HIV within the “two-spirit” community. Through these and other case studies, we will analyze how the intersection of religion and sexuality is inevitably entwined with questions of race, class, embodiment, nation, and post/coloniality.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5647,2023,2564,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-205','<div class="desc"> <p>What makes a thing, a place or a person sacred? This course focuses on the tangible elements of religion: the materials, objects, spaces, art, blood and guts that inspire belief and community. We will explore the way "things" interact with humans in their processes of creation, interpretation and the (re)definition of the religious, the sacred, the natural and supernatural, the holy, the profane, the secular, the immaterial, and transcendent, grounding our exploration in case studies. Our work will raise our awareness of the significance of materiality in religion and raise questions of authenticity, replication, and commodification. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5648,2023,1738,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-206','<div class="desc"> This course will survey the cultural history of Jerusalem over three millennia, primarily as the symbolic focus of three faiths: Judaism, Christianity, and Islam. Students will examine the transformation of sacred space as reflected by literary and archaeological evidence (studying artifacts, architectural monuments, and iconography in relation to written sources). Students will also examine the creation of mythic Jerusalem through event and experience. By the end of the course, students will better understand the historical roots of modern political and religious conflict in Jerusalem and Israel<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5650,2023,1191,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-215','<div class="desc"> <p>This course explores the dynamic religious and cultural landscape of East Asia, providing an overview of religion as it has been constructed in the states that are today known as China, Japan and Korea. In addition to learning about Confucianism, Daoism, Shintoism, and Buddhism, students will also learn about shamanistic and folk traditions, as well as practices that span across traditions, in order to provide students with tools to resist simplistic understandings of religious identity. Furthermore, taking both a chronological and comparative approach, the course leads students through the development of different traditions by situating them in their broader socio-political contexts. Finally, the course engages with multiple themes and perspectives, including the relationship between religion and the state, the development of institutions, literary and artistic expression, and gendered experiences of religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5651,2023,1351,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-228','<div class="desc"> <p>Latino/a religious social movements around the world have pursued liberation from oppressive forces and sought to move toward just and equitable futures. In this course, we will examine the ways various Latin American social movements from the late nineteenth century to the present day have defined and practiced liberation, paying special attention to the distinctive role of religion in these movements. We will ask: How can religion provide a foundation for liberation? More specifically, how can religion foster visions of life honoring justice and prosperity? In what ways have religious communities lead organized resistances? And even when mobilizing for liberation, to what extent can religion continue to solidify forms of oppression? We will seek to answer these questions through a series of case studies including: 1) a unique form of “muscular” evangelical Christianity across Latin America after the Spanish-American War (1898) that sought to combat the oppressive powers that limited their sovereignty; 2) liberation theology and spiritual praxis within the Mexican American Civil Rights Movement of the 1960s; and 3) Latino/a global missionary efforts through various evangelical organizations. At the end of the class, students will have the opportunity to apply what they have learned to a Latin American social movement of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5652,2023,1087,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-232','<div class="desc"> <p>A study of the development of the religion of ancient Israel and its expression in the Hebrew Bible. Special emphasis will be placed on the emergence of the central ideas of Biblical religion which formed the foundation for early Judaism and in time of Christianity and Islam. In addition to close reading of selected Biblical texts in translation attention will be paid to the historical context in which ancient Israel lived and to the findings of modern critical scholarship and archeology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5653,2023,3271,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-239','<div class="desc"> <p>We all want to build a socially just community and we believe that our health, as well as that of our family, friends, and neighbors, is a vital component of such a community. At the same time, we also recognize that what justice requires is complex and contested. This interdisciplinary course will first help students conceptualize what justice looks like within the realm of health and medicine through a series of case studies from the ancient Mediterranean and the United States contexts. Through these case studies—which will include a focus on public health, the patient-provider relationship, reproductive health, and end-of-life care—we will scrutinize the conceptual framing of health justice in the past, as well as the health justice foundations of contemporary practices, policies, and institutions. At the end of the semester, we will also give students the opportunity to envision a better way forward, and to begin to enact their vision. Students will design their own social justice final project on a topic of their choice. </p> <p>This course is part of the Humanities for Just Communities Immersive semester. Students wishing to enter into careers in the health professions—whether as physicians, researchers, or policy experts—are especially encouraged to enroll. </p> </div>',NULL,'FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(5654,2023,746,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-242','<div class="desc"> <p>An exploration of the relationship between religion and environmental ethics. How do various world religions view the natural world and what role do they propose for human beings in nature? What is the history of environmental ethics and how does religion figure in that history? How are religious traditions such as Buddhism Christianity Hinduism Islam Judaism Native American Spirituality and Taoism rethinking their environmental views especially in light of ecofeminism perspectives?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5655,2023,2889,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-244','<div class="desc"> <p>This class explores the Islamophobic ramifications of racialized Islam and Muslim identities. We will consider “blackness,” “brownness,” and “whiteness” as experienced through Muslim life, as well as how minoritized race and religion combine in ways that lead to fear, opposition, and violence. We will study Islamophobia through a number of American and Global cases, including the issue of iconoclasm (such as the Danish cartoon controversy), the racial and religious coding of various groups (such as Sikhs or Iranians in North America), perceptions of different sects of Islam (including Nation of Islam or the Ahmadiyya), and the political ramifications of these identities (such as recent US elections and the 2020 census). In addition to traditional readings, course materials will include a variety of media, such as longform journalism, memoirs, ethnography, music, and film.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5657,2023,976,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-250','<div class="desc"> <p>What is Religious Studies? Students in this course will answer this question first by tracing the historical formation of the academic study of religion (from monasteries to the university), and across various disciplines (sociology, psychology, anthropology, history, economics, etc.). We will then engage more deeply with the various theoretical and methodological tools available to scholars of religion by reading a range of scholarly works that illustrate these approaches and by giving students the opportunity to practice some of these approaches. In the end, students will become familiar with the landscape of the academic study of religion, will be able to assess the value and limitations of different scholarly approaches to the study of religion, and will have cultivated skills necessary to participate in conversations in the field. Required for Religious Studies majors and minors, recommended in the Sophomore or Junior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5658,2023,2843,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-254','<div class="desc"> <p>A course on gender and health in the history of Islam. The course begins with a study of the various dimensions, expressions, and status of what it has meant--and what it can mean--to be gendered a Muslim "man," "woman," or non-binary person: from the ideas found in scriptural sources, in later legal interpretations, through to historical transformations. Students will then study how legacies from the past are implicated in contemporary discourses and practices related to health and medical care. Students will explore issues related to bridging Muslim understandings of gender with best practices in health care, as well as the ethical reasoning behind gendered healthcare. Finally, students will explore a number of case studies on complicated and controversial issues such as abortion, sex reassignment surgeries, female genital mutilation, and sex positive movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5659,2023,2604,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-256','<div class="desc"> <p>Tibetan Buddhism is a globally recognized religion, with the Dalai Lama, red-robed monks, prayer flags, and prayer beads occupying a unique position in the popular imagination. These images, though, flatten the diversity and historical complexities both of the Buddhist traditions of Tibet and the spread of these traditions into surrounding regions of the Himalayas. This course will provide an overview of these traditions, exploring their trajectories of development and interactions with diverse communities, while also considering local differences and agency.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5660,2023,2497,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-257','<div class="desc"> <p>A systematic examination of the history of antisemitism, beginning with the emergence of anti-Judaism in late antiquity, its transformation into theological antisemitism in the Middle Ages, and a racialized antisemitism in the modern world. In each period, students will investigate the socio- political contexts that gave rise to the fear of, hatred toward, and attacks on Jewish individuals and communities</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5662,2023,2699,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-259','<div class="desc"> <p>Stories of child sacrifice. Rumors of necromancy. Images of “voodoo dolls.” In this class, students will survey a variety of magical practices throughout the Americas to ask: what is magic, and what makes it “black?” Using a series of case studies set throughout the Americas, we’ll trace the shifting boundaries between magic, religion, and reason from the colonial period to today. Students will engage sources like inquisition records, legal statutes, newspaper records, and films and fiction, to see how depictions of witchcraft and sorcery have been used to stigmatize certain traditions and people, ranging from Catholics in the United States to practitioners of African-inspired religions in Cuba and Brazil. And in doing so, we’ll learn how magic has been a key site for negotiating questions of race, progress, and citizenship in modernity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5663,2023,1626,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-261','<div class="desc"> <p>Buddhism is found worldwide today and is cited as an influence in a wide variety of settings, including psychology, self-motivation movements, education, statecraft, art, music, and science. However, its historical beginnings as a religious movement 2,500 years ago in India are often left out of these discussions. Buddhism is instead commonly presented as it has been reimagined by different agents as “more of a philosophy than a religion” and compatible with Western Enlightenment ideals, such as rationalism, empiricism and science. This course will provide a critical perspective on the process through which Buddhism has been constructed by various intellectual and political agents as it has developed in the modern era. Rather than attributing these characteristics of the tradition to inherent elements in some timeless ahistorical Buddhism, the course will instead encourage critical reflection on the broader cultural, political and economic processes that have influenced the development of modern Buddhism, including global networks of trade and technological exchange, colonialism (and anti-colonialism), cosmopolitanism, nationalism, the rise of secularism, and globalization between India, China, Japan, Sri Lanka, Tibet, Britain and America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5664,2023,2357,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-266','<div class="desc"> This course examines selected topics related to gender and sexuality as they have been negotiated in different global manifestations of the Buddhist tradition. Spanning over 2,500 years and multiple civilizations, Buddhism as a philosophy and Buddhist communities have constructed concepts of gender, sexuality, and the body in multiple, often conflicting, ways. Seen as androcentric and misogynist by some and liberating and non-judgmental by others, Buddhism and Buddhist institutional attitudes related to these key themes have been constructed through complex interactions between ancient traditions and the different societies in which Buddhism has developed. The course will be anchored in theoretical considerations of sexuality and gender, which we will explore through different case studies from India, China, Tibet, Thailand, Japan, and Korea. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5665,2023,1674,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-276','<div class="desc"> Mainstream historical accounts of empire tend to focus on political and economic reasons for state expansion, leaving students with little insight into the experience of colonialism and imperialism "on the ground" for both the colonizers and the colonized. This course will offer methodological tools that encourage an understanding of everyday, non-elite voices into the study of empire in Asia and the Pacific by focusing on religious experience. Studying religion -- which was used as both a tool for colonial domination, as well as for resistance -- complicates ideas of empire as straightforward and as a mono-directional process. Case studies in this course will explore the interaction between empire and religion across a range of regions and historical moments. Students will then embark on their own research project related to a place and theme of their choice. In the end, the course will give students an insight into how Asian and Pacific societies variously responded to imperialism while also influencing the societies of the colonizer. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5666,2023,2358,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-277','<div class="desc"> <p>This course will survey ancient Mediterranean views about the catastrophic end of the world. We will study how ancient folks--Greeks, Romans, Jews, and Christians--interpreted disease, natural disasters (fires, floods, food shortage), political upheavals, and social unrest as signs of the end of the world. We will study how they altered their behaviors to anticipate the near end. And we will study their visions and fantasies of the utopian societies they hoped would emerge after the devastation. At the end of the course, students will conduct a staged research project on a topic of their choice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5667,2023,2939,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-278','<div class="desc"> <p>An exploration of art, architecture, and visual culture created within the context of Muslim-majority or Muslim-ruled societies within Western Asia, North Africa, and Europe from the 7th to the 21st centuries. Students will study sacred and secular architecture and architectural decoration, sculpture, painting, manuscripts, textiles, and metalwork, including objects in Los Angeles area collections. We will consider theoretical framings of the field, such as what is “Islamic” about Islamic art. We will also consider how Islamic art circulates globally and the emergence of modern Islamic art, including the visual cultures of protest in contemporary Muslim-majority countries. Readings will include primary sources, exhibition catalogs, and scholarly articles; and, in possible, students will visit museums and a mosque. By the end of the course, students will be able to demonstrate knowledge of the diversity of Muslim arts historically and geographically.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5668,2023,1192,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/rels-281','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5672,2023,361,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/200/resl-245','<div class="desc"> <p>A study of the religious traditions of the African diaspora in North America. We shall investigate the role of religion in Black culture and chart the development of the mainline Black Church. Islam religious traditions from the Caribbean Islands and new religions among African Americans will also be studied.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5673,2023,2815,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/300/rels-302','<div class="desc"> <p>In this course, students will explore mediumship and exorcism practices in the Atlantic World from the early modern period to today. Through case studies—including Haitian Vodou in Brooklyn, Brazilian Umbanda and Candomblé, Cuban Palo Monte, Santería in Chicago, Yorùbá and Igbo traditions in West Africa, North American Spiritualism, and Catholic Exorcism in France—we will take a broad look at the different ritual practices that fall under the academic category of “spirit possession.” We will consider why practitioners channel the spirits of the dead and what it means to be possessed. We will read scholarly studies that analyze what spirit possession has to do with race, gender, and sexuality. Finally, we will interrogate contemporary western scholarship itself, asking: Why have outsiders commonly described the spirits’ presence in terms of “possession”—a term rarely used by practitioners themselves—and how does the trope of the possessed person serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5675,2023,1090,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/300/rels-351','<div class="desc"> <p>Folks in the ancient Mediterranean world were deeply invested in forms of sexuality that served the interests of Empire, of elite households, and of men. In the first unit of the course, we will investigate how these specific forms of sexuality were prioritized, incentivized, and regulated in society--namely, how art, medicine, law, and religion worked together to make them appear natural and normal. But when Christians came on the scene, they advocated a significant deviation from the dominant sexual ethics of the time. In the second unit of the course, we will study early Christians'' novel ascetic movement that understood sexless (even genderless) people to embody the ideal spiritual state, positioned at the pinnacle of humanity. In these next unit, students will be given the freedom to set the direction of the course. They will conduct a research project on a topic of ancient sexuality of their choice, presenting their findings to classmates. In the final unit, we will consider how sexual ethics of antiquity are still exerting influence on us, shaping contemporary sexual taboos, values, and regulative mechanisms. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5677,2023,365,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/300/rels-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5678,2023,750,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/300/rels-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5679,2023,366,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/400/rels-490','<div class="desc"> <p>This seminar is offered in conjunction with Religious Studies majors'' ongoing research for the senior comprehensive project. Seminar meetings will be devoted to instruction on research and writing in the discipline of Religious Studies as well as discussion and critique of individual students'' work in progress. Open only to senior Religious Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5681,2023,751,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rels-religious-studies/400/rels-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5682,2023,368,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/100/rusn-101','<div class="desc"> <p>Introduction to the structure of the Russian language with an emphasis on reading and verbal communication. Films and laboratory assignments complement in-class work. May not be taken for credit by those with more than one year of high school study (grades 10 11 12) or one semester of college study of Russian.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5683,2023,752,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/100/rusn-102','<div class="desc"> <p>Continuation of RUSN 101; emphasis on reading and conversation.</p> </div>','RUSN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5686,2023,369,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/200/rusn-201','<div class="desc"> <p>Development of reading skills through the use of original texts by Bulgakov Chekhov Pushkin and others; improvement of conversation skills accompanied by a review and expansion of grammar. Films and laboratory assignments complement in-class work.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5687,2023,753,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/200/rusn-202','<div class="desc"> <p>Continuation of RUSN 201 with emphasis on reading skills; readings by Gogol Chukovsky Shukshin and others.</p> </div>','RUSN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5689,2023,2752,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/200/rusn-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers:Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ).</p> <p>This course meets twice a week with CSLC 236, and for one additional 85 minute session per week, to develop Russian students'' intermediate language skills, specifically by reading and discussing works under consideration in the course taught in translation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5693,2023,1677,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-331','<div class="desc"> The worldview and beliefs of the early Slavs particularly the Eastern Slavs were a complex synthesis of influences: Indo-European mythology Central Asian shamanism Scythian animal worship and ultimately a paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600 in order to understand how these people viewed the world and how this affected their lives and the development of Slavic culture. Communal village life legends folk genres and mythology their sources and their legacies are examined. There is a close study of the phenomenon of the vampire following its evolution from the Iron Age into eighteenth century Serbia as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined as well. In addition to analytical and historical texts readings include tales of supernatural beings and phenomena as well as testimony concerning encounters with the supernatural." This section will deal with both texts in English and with texts in the original Russian. Texts include the "Tale of Warlord Dracula," "Olga''s Revenge on the Drevlians" and other early Russian stories. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5694,2023,1561,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-332','<div class="desc"> Many of Russia''s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements while at the same time creating some of the most memorable texts of the twentieth century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin, using original Russian texts to examine the use of language in the creation of science fiction and fantasy texts. Additionally, film adaptations will be shown, including the avant garde film Aelita the Queen of Mars and Andrei Tarkovsky''s masterpiece, Stalker. The course only introduce students to modern Russian literature while at the same time examine how Russian writers used science fiction to criticize society and government. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5695,2023,1627,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-333','<div class="desc"> <p>Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939 when the Soviet Union was busily partitioning Poland by secret agreement with Nazi Germany. This course examines the cultural history of Russia and the Soviet Union in specific regard to its evolving theories of language literature and cultural phenomena during the early 20th Century. Particular attention is paid to Russian formalism poetics and semiotics as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence mutual East-West suspicion social repression and exertions of state power through propaganda and censorship.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5696,2023,1740,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-334','<div class="desc"> How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist a century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun" and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency known otherwise as the Russian Avant-garde. Topics include poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5698,2023,2854,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-336','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. In this five unit version of CSLC 136, we will be reading excerpts in the original language from Goncharov’s Oblomov, Turgenev’s Fathers and Sons, Dostoevsky’s Idiot. Students in this course will be asked to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5699,2023,2946,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-338','<div class="desc"> <p>Should you abandon yourself to the sensual beauty of the world? Or should you embrace a life of asceticism and simplicity? Is there an even more attractive path in between? Is it also a more difficult one? Major works by Russian writers—including Pushkin, Tolstoy, and Chekhov—will guide our discussions of these questions. This course will meet twice a week with CSLC 138, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from texts by Russian writers, especially Pushkin, Tolstoy, and Chekhov. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement. </p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5700,2023,3217,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-339','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>This class will meet simultaneously with CSLC 139 twice a week, and then meet for an additional 90 minute session to read selections of the above works in the original. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5703,2023,3179,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>To be: Ukranian</strong></p> <p>Ukraine’s rich poetic and revolutionary culture helps one trace routes of escape from oppressive imperial structures. Philosophical and literary texts written by and about Ukrainians will allow us to gain an understanding of this culture, and the works by contemporary historians will help us develop an understanding of Ukraine’s tumultuous history. Philosophers, writers, and historians could include Svetlana Alexievich, Anne Appelbaum, Ivan Kotlyarevsky, Alexander Potebnja, Mykola Riabchuk, Timothy Snyder, Lesia Ukrainka, Oksana Zabuzhko, Serhiy Zhadan, and others. No previous knowledge of the Ukrainian language or literature is required. Russian 330 will meet twice a week with CSLC 130, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from literary and philosophical texts in the original Russian. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement. Core Requirement Met: Regional Focus.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5704,2023,754,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/rusn-russian/300/rusn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5706,2023,371,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/100/soc-101','<div class="desc"> <p>This course introduces students to the "sociological imagination"-a way of viewing events relationships and social phenomena which form the fabric of our lives and much of our history. We will examine the ways in which people are shaped influenced and controlled by their society and vice versa. In addition students will be encouraged to think about how sociology helps us understand and interpret the nature of social order and disorder. <em>Open only to frosh and sophomores or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5707,2023,2700,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/100/soc-102','<div class="desc"> <p>This course adopts a global perspective to introduce students to sociology, the scientific study of societies. It will examine the self, socialization, social ties, social interaction, social institutions, and social change, considering both conformity and deviance. Students will leave with a "sociological imagination," the ability to see their own lives and the lives of others in the context of their wider societies and an increasingly interconnected world. Open only to frosh and sophomores, or by permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5708,2023,879,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/100/soc-105','<div class="desc"> <p>This course examines the role of youth cultures in the identity formation of immigrant adolescent youth residing in the Southwest region of the United States. Particular attention is paid to: (1) theories of acculturation and assimilation used to analyze the experiences of immigrant youth; (2) the impact of geographical location social class gender race sexuality popular culture mass media and technology; and (3) the intersection of youth cultures home cultures and mainstream society.</p> <p><span style="background-color: #ffffff; color: #222222;">This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CTSJ 105, DWA 282, and SOC 105.</span></p> </div>','SOC 101 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5710,2023,755,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/100/soc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5711,2023,1491,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-200','<div class="desc"> <p>This course introduces the discipline''s formative schools of thought. The course is structured according to sociology''s classic paradigms. Marxist Weberian and Durkheimian theories are the classical models. They founded the field of Sociology and continue to influence contemporary thought about social relations. In the course we first examine the fundamental presuppositions of their grand theories. Then we critically evaluate the particularities of their more concrete propositions about capitalist development or modernization the state and social change. A special emphasis of the course is on critical analysis.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5712,2023,372,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-205','<div class="desc"> <p>This course introduces the most influential paradigms of the 20th century. These include the American structural-functionalist paradigm the rational choice model the elite school various neo-Marxist arguments (including the theory of the world system as well as the culturalist Frankfurt school) and the symbolic interactionist paradigm. We conclude the course with an introduction to postmodernist theory. The course emphasizes critical analysis.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5713,2023,1492,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) Presidents either failed to act in accordance with the transitional justice movements sweeping Latin America, or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased rather than decreased since its transition to democracy. This class will document why this is the case as well as look into the various movements that have mobilized since the 1970s to the present to demand human rights in Mexico. This class will also look at the violence committed by transnational criminal organizations as well as how ordinary people attempt to create security for their communities.</p> </div>','DWA 101 , LLAS 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5714,2023,3234,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-211','<div class="desc"> <p>Cultural production is central to the struggle for human rights. As cultural artifacts both conceptualize and memorialize social-political trauma, our class will take a close look at the way that Mexican film, literature and music represents both criminal and state violence. For comparative purposes, we will also look at some documentaries or film about the current violent situation in Central America. As this is a 2-unit course, you should expect to spend at least six (6) hours a week (including in-class time) on this course.</p> <p><strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico (as well as Central America) through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5715,2023,1562,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-215','<div class="desc"> <p>Who are you? Why are you? How do you know? Surely you have heard the phrase "nature vs. nurture." It is about the ongoing quest to figure out how much of a human is genetic, biological, and chromosomal (nature), and how much is a product of socialization (nurture). To what extent are you your society? To even consider that question, we must examine the society itself, the individuals that produce it, and how the two are connected. The society and selves we will be examining are our own -- in particular, the society and selves of young Americans. How does the world you''re facing today make you who you are? How do the technology and media through which you learn about your world permeate, shape, and structure your everyday experience of self and society? Who do you want to be, who will you end up being, and what kind of world will you create?</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5716,2023,3307,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-218','<div class="desc"> <p>Over fifty years ago, the first person in the U.S. hired to coordinate a Black Studies program, Nathan Hare (1970), published an essay titled, ‘‘Black Ecology,’’ in which he argued that it was imperative that we come to ‘‘understand how both the physical and social environments of blacks and whites have increasingly evolved as contrast.’’ Since then, many scholars from across the social sciences and humanities have contributed to this endeavor. This emergent field of Black ecological thought is important because it provides insight about race and the environment from the perspective of Black study. In this survey course, we will study a range of black ecological thinkers and the concepts that they offer for understanding contemporary environmental issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5717,2023,1628,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-225','<div class="desc"> <p>This course examines the construction and reproduction of masculinities primarily in the United States. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5718,2023,1316,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-230','<div class="desc"> <p>This course examines the family as a social institution in the United States. The course emphasizes sociological and demographic perspectives on the family family change historically and contemporarily and the intersection of the family with social categories such as race and ethnicity sexual orientation gender and class. The course will highlight contemporary changes in marriage divorce and non-marital cohabitation in the United States but will also expose students to sociological thinking about family systems around the world.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5719,2023,756,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-240','<div class="desc"> <p>This course examines the social relations surrounding the production distribution preparation and consumption of food. In doing so we will try to understand how the issues and problems of daily life reflect larger social forces and how our understanding and actions shape the social world. This means that we will treat several major questions facing sociology today including inequalities and identities based on national racial/ethnic class and gender positions; work and family; the environment; globalization; and cultural change. By the end of the course you will be able to critically examine and evaluate the connections between food culture and society.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5720,2023,373,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-245','<div class="desc"> <p>This course examines the individual cultural and structural explanations for the presence and persistence of income and wealth inequality in the U.S. The impact of inequality on social groups and the social policies developed to curtail poverty are also considered.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5721,2023,979,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-250','<div class="desc"> <p>This course provides a basic sociological understanding of relations among racial and ethnic groups in the United States. A sociological approach includes considering race and ethnicity as social constructs that permeate all social life are entrenched in social structures and institutions and shift and mutate over time and place. Such a perspective suggests that (1) race and racism are not merely the ''problems'' of/for subordinate racial and ethnic groups but are reflective of society-wide power relationships that deeply affect all of us on a daily basis (2) that racial and ethnic categories - including ''white'' - can be viewed usefully as the result of historical struggles over economic resources political access and cultural identity rather than as objective measures of biological difference and (3) the institutional forms of racism indelibly etched into this nation''s past did not end with civil rights legislation of the 1960s but continue to shape social institutions today.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5722,2023,1092,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-260','<div class="desc"> <p>In this course we will focus on sociological theories of deviance with an emphasis on how behaviors and identities are socially constructed as deviant (both today and historically). We will then turn our attention to major forms of deviance as typically defined in Western societies: criminal deviance "victimless crimes" and individuals with stigmatized identities. Throughout the course we will work to understand the complex relationship between social actors and audiences in defining deviance; the nature of social control in responding to deviance; and the experiences of "deviant" individuals.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5723,2023,3344,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-263','<div class="desc"> <p>W.E.B. (William Edward Burghardt) Du Bois, was a prolific scholar, writer, and social/political analyst and organizer. Over the course of his lifetime, Du Bois wrote over 2000 bibliographical entries, across a range of genres, including: research monographs, plays, pamphlets, autobiography and biography, history, novels, poems, and popular press articles. At the same time, Du Bois utilized multiple methods, forms of data and evidence, and literary styles within and across texts. Nevertheless, in the domain of social science, and sociology more specifically, his work was intentionally marginalized. Yet while Du Bois was made a minor figure in American social science, he was a primary progenitor of the transdisciplinary field of Black, African American, or Africana studies and thus played a foundational role in circumventing the racial-colonial order of knowledge by attending to Black life and sociality. In this course, we will study the social theory of Du Bois by reading texts from across his vast corpus—from his more formally social scientific writing and data visualizations to his creative projects like poetry and short stories. For the final project of the course, students will deploy a Du Boisian approach to social theory and analysis using more expressive forms (such as illustration, painting, film and video, poetry, music, photography, data visualization, short stories, or lyrical essays).</p> <p>*This course cannot substitute for the theory requirement (SOC 200 or SOC 205) for Sociology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5724,2023,374,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-265','<div class="desc"> <p>In this course we will critically examine the ways gender informs the social world in which we live. Our goals for this course will be 1) to reveal the "common-sense" world of gender around you; 2) to consider how we learn to "do" gender; 3) to expose the workings of the institutions that shape our gendered lives; and 4) to come to an understanding of the relationship between gender and the social structure.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5725,2023,2360,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-270','<div class="desc"> <p>What are the effects of urbanism on human psychology and civic life? How does urbanization structure social and economic relations as well as signifying identities and cultural meanings? Is there a common "human ecology" of cities in "natural areas" such as the CBD skid row the "Tenderloin" or the "zone-in-transition"? We examine the urban underclass through case studies of the African American ghetto and Spanish Harlem with attention to public policy perspectives on urban poverty. Urban futures are considered through gentrification growth machine boosterism (sports and convention centers) and urban theme parking.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5726,2023,3259,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-275','<div class="desc"> <p>People in the U.S. struggle every day to get the care they need. Why, in such a wealthy country, do so many go without healthcare, eldercare, childcare, food, housing, and more? This course surveys, from a comparative-historical perspective, social welfare provision in the United States. We dissect debates about the value of welfare and explore the implications of various arrangements between civil society, the market, and the state. In so doing, we consider critical race, Marxist, and feminist theories of social welfare as a tool of racial, economic, and gender power. Students use theoretical lenses developed in class to assess contemporary welfare policy interventions.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5727,2023,3235,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-281','<div class="desc"> <p>This course introduces the field of criminology. The course is designed to provide a broad understanding of the etiology of crime (i.e. what causes crime?) the measurement of crime and theories of criminal punishment. We will also discuss a wide range of criminal behaviors with a focus on violent crime and property crime (e.g. homicide sexual assault shoplifting white collar crime etc.). The final component of the course focuses on the American criminal justice system. This course emphasizes a sociological approach to understanding crime criminal behavior and criminal justice.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5728,2023,1093,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-285','<div class="desc"> <p>The relationship between humans and the non-human environment is complex and problematic. We are part of and dependent upon the natural environment even while altering that environment for our own needs and purposes. As a way of broadly thinking about these interactions we will address the social causes consequences and responses to environmental disruption. By the end of the course you will be more adept at understanding how societal characteristics -- including cultures traditions beliefs values institutions and the like -- combine with environmental conditions to shape the impact that people have on their environments.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5729,2023,1741,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-290','<div class="desc"> <p>This course is an introduction to sociological analyses of the economy, economic processes, and economic institutions. The central focus is to understand how beliefs, norms, cultures, social relations, and institutions shape our economic lives. We will also explore how the theoretical and methodological approaches of sociology differ from those orienting the discipline of economics, as well as what is at stake in these differences. By the end of the course, you will be familiar with the key approaches in economic sociology, and will be able to use a sociological lens to examine the economy.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5731,2023,1194,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/200/soc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5733,2023,375,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-304','<div class="desc"> <p>This course looks at the ways sociologists collect information about social phenomena with a special emphasis on what can be done to yield information that is trustworthy and useful for our theoretical understanding of social life. It assumes no background in research methods or statistics. We will talk about the scientific method the complexities of applying methods to social research ethics and bias and research design. You will be given an overview of major "quantitative" and "qualitative" methodologies including surveys interviews ethnography experiments participant observation or content analysis.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5734,2023,757,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-305','<div class="desc"> <p>This course introduces quantitative research methods and statistical analysis from a social science perspective. We will address the major components of the research process and will stress the importance of critical thinking in all matters numerical. We will cover measures of central tendency the normal curve probability frequency distributions correlation and regression. We will also talk about statistics and statistical reasoning in the media. By the end of the course you will have mastered basic statistical concepts and techniques and will be able to critically examine and evaluate the (mis)use of these concepts.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5735,2023,1563,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-306','<div class="desc"> <p>This course introduces qualitative research methods from a social science perspective. We will cover systematic qualitative research design data collection and analysis. Techniques will include interviewing focus groups ethnography and/or qualitative content analysis. By the end of the course you will have mastered basic concepts and techniques and be able to carry out basic qualitative research.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5736,2023,1094,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-315','<div class="desc"> <p>This course uses different sociological perspectives to examine social aspects of schooling and educational institutions in the U.S. Specifically the course focuses on factors that may impede and/or facilitate learning such as social class gender race and ethnicity teacher and parental expectations and peers. Additionally the role of education in the acculturation and assimilation process is considered as are the ways in which schools ameliorate and/or replicate social inequalities.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5737,2023,1353,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-320','<div class="desc"> <p>This course surveys sociological theories of health illness and medicine. Rather than focusing on the individual body as the site of disease the course examines the role of social context in shaping health and access to the healthcare system across population groups. The course focuses especially on medical intervention and the medicalization of disease social disparities in health and contemporary healthcare changes and challenges in the United States.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5738,2023,2605,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. We will also examine Central American immigration from an international relations perspective.</p> </div>','SOC 101 , SOC 102 , SOC 105 , LLAS 101 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5739,2023,2361,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-323','<div class="desc"> <p>This course explores the sociological analysis of law, focused on the legal construction of social "groups," the moral regulation of social action, and the formal legitimization of state practices. The course is divided into two sections. The first half of the course examines theoretical approaches to the sociology of law drawing on the works of Max Weber, Niklas Luhmann, Jürgen Habermas, and Pierre Bourdieu, as well as perspectives rooted in Marxism, feminism, and critical race theory. The second half of the course focuses on contemporary legal controversies in the United States, including racial disparities in criminal justice, undocumented immigration, the regulation of sexuality, and the criminalization of political dissent and protest.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5740,2023,3260,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-326','<div class="desc"> <p>Why does the United States incarcerate more of its population than any other nation in the world? Why does death by injection seem kinder and gentler-and thus more acceptable-than public hangings of the past? What are the consequences for justice and democracy in an era of unprecedented confinement and correctional supervision? Using various historical, legal, and sociological perspectives we will focus on questions such as these with an emphasis on: the cultural life of punishment and crime control as a political issue, the racial and class dynamics of punishment, and inequality and contemporary issues surrounding modern penal sanctioning (e.g. mass incarceration) and its consequences. </p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5741,2023,377,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-330','<div class="desc"> <p>This course will focus on classical and contemporary theories of power and authority; theories of the state and various forms of state power the state and government the nature of democracy and political elites in modern society (especially the United States) as well as the social bases of political parties and voting behavior.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5742,2023,1564,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-340','<div class="desc"> <p>China''s Environmental Challenges: A Sociological Perspective This course examines China’s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China’s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. Cross-listed with East Asian Studies and Urban and Environmental Policy.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5743,2023,758,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-350','<div class="desc"> <p>This course examines why people protest for social change. We will examine the theoretical debates about the determinants of insurgency by focusing on the following models: the collective behavior the resource mobilization the political process as well as the cultural approach. We will also examine the theoretical debates on the extent to which social movements can be credited with political change. Your study of these theories will expose you to several case studies of real social movements in the United States Europe and Latin America. This is however a theory (not a history) course.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5744,2023,759,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-355','<div class="desc"> <p>This course will consider the role that sexuality plays in the American imagination especially the way that sexuality is constructed and serves as a mechanism of social control. In doing so special attention will be paid to the ways in which human sexuality intertwines with axes of power in contemporary America such as race ethnicity gender class and sexual orientation.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5745,2023,2890,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-361','<div class="desc"> <p>This advanced seminar builds on the foundational understandings of race/ethnicity to further explore Whiteness in the U.S. and globally. Whiteness is a framework that organizes social structures and can be systemically upheld regardless of one''s race. This course explores how constructions of Whiteness change through shifting racial boundaries and across global contexts; how it shapes privilege, racism, and racial oppression across social institutions; how it intersects with other axes of power to shape inequality; and how it informs scientific knowledge from theorizing to data analysis.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5746,2023,761,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-365','<div class="desc"> <p>The course will examine how mass communication systems such as radio television cinema and the Internet are produced and what they signify and represent of the social world and public life. We consider the relationship of the mass media to big business and the structure of capitalism. The ideological influences of the mass media are interrogated through concepts such as "mass culture" and "subculture". We examine how contemporary culture and everyday life are increasingly commodified through the systems and spectacles of consumption capitalism. How has globalization affected consumerism and the social construction of the contemporary self?</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5747,2023,1354,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-370','<div class="desc"> <p>This course examines the social phenomenon of human violence. We first consider classical and contemporary sociological theories on violence and violent conflicts and the main sociological definitions of violence used over the last century. We then turn to empirical studies that explore the social processes and societal structures that give rise to the various forms of violence-intrapersonal interpersonal familial collective and political-and nonviolent movements presently observed throughout the world.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5748,2023,762,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-375','<div class="desc"> <p>This course examines the political economic and cultural changes that occur as societies shift from the traditional to the modern. Why are some nations mired in debt and dependency while others have become successful "newly-industrializing countries?" We consider leading intergovernmental organizations of the global economy such as the IMF World Bank and WTO. We investigate scenarios in cultural globalization including Americanization hybridization and fundamentalism. We consider intersectional social dynamics that disenfranchise the most powerless including women children indigenous and stateless peoples.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5749,2023,1426,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-380','<div class="desc"> <p>This course examines disaster as a social phenomenon and broader trends in managing calculating and responding to a variety of threats and catastrophes. We will focus on the history of disaster response and policy in the U.S. theories of reflexive modernity risk and trauma and cultural responses to calamity in California and in the U.S.more broadly. Case studies include Hurricane Katrina the BP Deepwater Horizon oil spill Fukushima and outbreaks of whooping cough and Ebola.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5750,2023,1631,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-390','<div class="desc"> <p>This course offers a survey of sociological approaches to the study of religious beliefs practices and organizations in the United States in public and private life. Exceptionally devout among developed nations the U.S. is a nation of remarkable religious diversity. We will examine the relationship between religion politics and civic life; recent trends in American religion (the "new atheism" problems of pluralism secularization and declines in religious participation the rise of evangelicalism and fundamentalisms religious conflicts); as well as theoretical arguments both classical and contemporary about the role of religion in scientifically advanced modern societies. Whereas much public debate frames religion as either a unambiguously beneficial public good or else as a font of irrationality and sectarian division we will move beyond this dichotomy toward a more empirically informed consideration of just what religion is and does in the contemporary United States.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5752,2023,1040,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-395','<div class="desc"> <p>This course will function as an advanced seminar focusing on the research interests of the Sociology Department''s faculty. Topics vary.</p> <p><strong>Science, Technology, &amp; Justice: The Making of “Modern” Families</strong></p> <p>Does reproductive justice include a right to bear children using technological means? What about using 3<sup>rd</sup> parties like egg and sperm donors? Are reproductive technologies expanding definitions of family or reinforcing race, class, and gender inequalities? This upper-division seminar will examine reproduction from a social justice perspective, with particular attention to how the politics of reproduction are shaped by the intersecting inequalities of gender, race, class, dis/ability, and sexuality. Reproduction is not only a biological process; it is a battleground of social and political struggle. The course will familiarize students with foundational academic and activist approaches to reproduction. Students will learn about the history of and differences between reproductive rights and reproductive justice movements. We will then look at the new questions and challenges reproductive technologies raise for social justice. Cross Listed as UEP 395.</p> <p><strong>Policing, Power, and Violence</strong></p> <p>In this course, we will examine policing in the United States from the repression of Indigenous and enslaved peoples in the 18th century to the militarization of policing on the streets and the U.S.-Mexico border today. Using sociological understandings of power, we will analyze the judicial and extrajudicial violence that law enforcement agents engage in and how such violence serves to maintain the unjust and unequal social order. The course will close with us considering arguments for and against the abolition of police forces and prisons.</p> <p><strong>Sociology of the Southern U.S.</strong></p> <p>What, and where, is the South? Who is a southerner? What do they do down there, and why do they do what they do? Are the South and southerners still distinctive? By looking at all aspects of Southern life this course will unravel the enigma of the region while pondering a more inclusive and nuanced appreciation of "many Souths" and "southern cultures" including senses of regional identity and allegiance, and in representations of, and cultural stereotypes from and about, the South. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> <p><strong>Visualizing Gentrification: Bridging Land Use Data and Ethnography</strong></p> <p>Students are challenged with the myths and realities of gentrification in an immersive discussion. The proposed course weaves urban planning, mapping and data research with qualitative analysis to recognize gentrification drivers, examine the pending experiential trauma of displacement and the community''s aspirations and resistance. The course examines the communities of Northeast Los Angeles as they face three colossal planning projects that utilize gentrification as a catalyst and justification for their development.</p> <p>In a holistic examination of the landscape, course participants will embed with community and other partners to explore the social networks and their relationship to research data. Course discussions will include developing metrics from an activist and documentary perspective to establish the observable community. Students will operate in small teams in developing data and fostering outcomes that reveal the human narrative. They can be visual in nature from ethnographic studies to data visualization, but also critical analysis and policy recommendations of the conditions on the ground. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5753,2023,763,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/300/soc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5754,2023,378,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/400/soc-490','<div class="desc"> <p>Seminar is offered in conjunction with sociology majors'' ongoing library research for the senior thesis. Seminar meetings will be devoted to discussion and critique of work in progress. We strongly encourage students to have taken Classic or Contemporary Theory Sociological Inquiry and Qualitative Quantitative or Field Methods before taking the senior seminar (always taught in the Fall). <em>Open only to senior Sociology majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5756,2023,764,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/soc-sociology/400/soc-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5757,2023,380,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/100/span-101','<div class="desc"> <p>Introduction to Spanish through a variety of communicative approaches. Emphasis is placed on speaking and listening as well as grammar and writing. <em>Students who have had more than one year of Spanish in high school or more than one quarter in college may not take this course for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5758,2023,381,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/100/span-102','<div class="desc"> <p>This course is a continuation of SPAN 101. Students are introduced to the culture of the Spanish-speaking world through readings and discussions.</p> </div>','SPAN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5759,2023,880,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/100/span-105','<div class="desc"> <p>This course offers students the opportunity to analyze narrative stories films and other cultural artifacts that document a history of immigration and migration to Los Angeles from Mexico and Central America during the twentieth and twenty-first centuries.Many of the narratives films and other cultural works studied treat significant contemporary issues (e.g. the representation of history questions of identity and alterity questions of race and ethnicity globalization authority the construction of class and gender in society) that Los Angeles faces as an emblematic socio-cultural space that continuously shifts as consequence of new arrivals to the city. Emphasis will be placed on studying narratives and films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically this course presents a critical view of the representation of migrations to Los Angeles in order to understand how these migration stories function as a socio-cultural medium that document and occupy many geographical spaces that establish Los Angeles as a heterogeneous cultural place and space.</p> </div>',NULL,'CTSJ 105 , FYS 1 , SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(5760,2023,382,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/100/span-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only. </em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5761,2023,765,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/100/span-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit.<em> Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5763,2023,766,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/100/span-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5764,2023,383,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/200/span-201','<div class="desc"> <p>This course focuses on the development of speaking and writing skills. Students read and discuss cultural and literary texts from a variety of Spanish-speaking countries. The fundamentals of Spanish grammar are reviewed.</p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5765,2023,384,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/200/span-202','<div class="desc"> <p>This course is intended to further develop language skills while introducing students to the fundamentals of literary analysis through a study of Mexican South American and Spanish literary texts. Particular emphasis is placed on oral communication and writing. <em>This course parallels SPAN 211 and is designed for non-native speakers of Spanish. Students may not take both for credit.</em></p> </div>','SPAN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5766,2023,385,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/200/span-211','<div class="desc"> <p>This course is designed for students who have spoken some Spanish in the home and are able to understand spoken Spanish well. It aims to develop and improve students'' conceptual understanding of the grammatical structures of the Spanish language. Coursework emphasizes the practice of formal written and oral Spanish as well as the improvement of vocabulary with the goal of strengthening students’ fluency in academic and professional contexts. Principal readings consist of literary texts (e.g. short stories, literary essays, and drama) in order to prepare students for reading and writing in upper-level Spanish courses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5767,2023,386,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/200/span-251','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5768,2023,767,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/200/span-252','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5772,2023,1095,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-301','<div class="desc"> <p>General survey of Pre-Columbian civilizations and literature of Meso and South America the impact of the Discovery the Conquest the Colonial Period and the processes leading to the Independence and the formation of the new Republics. Literary and historical readings compositions and short essays and presentations will be used to continue developing language skills.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5773,2023,984,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-302','<div class="desc"> <p>An introduction to Spanish Peninsular literature and culture from the Middle Ages to the 18<sup>th</sup> century. This course examines the cross-cultural elements (Arab, Jewish, French, Italian, Trans-Atlantic and others) that have influence Spanish literature across the centuries. Readings include Mozarabic poetry, the <em>Cantar de Mio Cid</em>, Medieval narratives, <em>La Celestina</em>, Renaissance poetry, selections of <em>Don Quijote</em>, and Golden Age dramas. The class also incorporates representative examples of art and films.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5774,2023,387,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-303','<div class="desc"> <p>An introduction to major twentieth-century works of literary fiction and cinema in Latin America, with attention to the interplay of fiction and history, read in the original Spanish: Gabriel García Márquez''s <em>One Hundred Years of Solitude</em>, Isabel Allende''s <em>The House of the Spirits</em>, and stories by Jorge Luis Borges, Julio Cortázar and Roberto Bolaño. Film screenings include Cuban director Tomás Gutiérrez Alea''s <em>Memories of Underdevelopment,</em> Chilean director Patricio Guzmán''s <em>Salvador Allende</em>, and Argentine director Lucrecia Martel''s <em>La ciénaga</em>.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5775,2023,768,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-304','<div class="desc"> <p>This course surveys Spanish Peninsular literature and culture from the late 18<sup>th</sup>-century through the early 21<sup>st</sup>-century. Students engage with various intellectual and literary movements, including Neoclassicism, Romanticism, Naturalism, Surrealism, and Postmodernism. Special attention is given to the development of democratic traditions in Spain, the clash of political ideologies during the Second Spanish Republic and the Spanish Civil War, the trauma and legacy of dictatorship, and the changes in Spanish society resulting from the assertion of the distinct languages and cultures of the Iberian Peninsula and from globalization and immigration. Authors read include Leandro Fernández de Moratín, Ángel de Saavedra, Emilia Pardo Bazán, Jacinto Benavente, Ramón Sender, Antonio Buero Vallejo, and Juan José Millás. Significant examples of modern Spanish art, architecture, and music are also studied.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5776,2023,1494,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-309','<div class="desc"> <p>Many Latin American writers have chosen to live in Spain during the twentieth century. This course introduces students to the Latin American tradition of the writer acting as public intellectual or diplomat as well as to instances of the Latin American writer in political exile. Poets Pablo Neruda and CÃ©sar Vallejo chose to live in or near Madrid during the period of the Spanish Civil War whereas a later generation of fiction writers (Gabriel Garcia Marquez Cristina Peri Rossi and Roberto BolaÃ±o) lived in Barcelona after the 1970''s. The fiction writers include their own vision of Catalan nationalism and Catalan national identity in various short stories. The course concludes with a three-week stay in Spain that will provide a deeper understanding of the Latin American writers'' representation of the coutry. On-site lectures by historians and art-historians will enhance the student''s understanding of GarcÃ­a MÃ¡rquez''s Peri Rossi''s and BolaÃ±o''s incorporation of Catalan politics landscapes and cityscapes in their fiction.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5777,2023,1096,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-312','<div class="desc"> <p>This course surveys the history of Spanish film from its inception to the present. The course introduces students to basic concepts of film studies including cinematography mise-en-scÃ¨ne sound narrative and style but emphasizes representation and in particular depictions of gender sexuality and national identity in the context of dictatorship and democracy. The course further introduces students to the auteurist tradition in Spanish cinema. The films studied vary from year to year but the course typically highlights the cinematic production of Luis BuÃ±uel Carlos Saura and Pedro AlmodÃ³var.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5778,2023,1196,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-313','<div class="desc"> <p>This course offers students the opportunity to analyze films that have emerged in Latin America (e.g. Argentina, Brazil, Colombia, Cuba, Mexico, and Peru) as well as in the United States in the 20th and 21st Centuries. Many of the visual works studied treat significant contemporary issues in Latin America, such as the representation of history, questions of identity and alterity, questions of race and ethnicity, globalization, authority, the construction of class and gender in society. Emphasis will be placed on studying films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically, this course is a critical survey of the representation of Latin America with representative examples from different historical periods (beginning with the pre-Columbian and Colonial periods followed by the 19th and 20th Centuries). The goals of the course are to understand how film as a medium has functioned historically and aesthetically in its representations of different sectors of society.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5779,2023,881,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-314','<div class="desc"> <p>How do Latin American women writers and film-makers use language and sound? This course analyzes questions of social critique and the use of language in the short stories of Uruguayan writer Cristina Peri Rossi PuertoRican writer Rosario FerrÃ© and Brazilian writer Clarice Lispector as well as the use of voice music and mise-en-scÃ©ne in films by Latin American directors Gabriela David Maria Luisa Bemberg and Susana Amaral.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5781,2023,388,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-320','<div class="desc"> <p>An analysis of the relationship between literature and film, focusing on texts from the Spanish Golden Age and their film adaptations. Issues to be discussed include film adaptation as a cultural construct; narrative voice in literature and film; the transformation of the written word to the visual image; and the relationship between politics, literature, and film. This course includes a digital liberal arts laboratory in which students engage digitized and physical materials and develop necessary skills and critical frameworks for audiovisual and web-based course projects.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5782,2023,3240,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-321','<div class="desc"> <p>This course will examine culture and society in Spain under the dictatorship of Francisco Franco (1939-1975) and the effects of Francoism that continue to pervade present day Spanish society. We will focus on cultural productions (literature, film, television, propaganda posters, etc.) that illustrate socio-historical, political, and economic experiences during the most important chapter of 20<sup>th</sup> century Spain. In addition, we will examine cultural products created in the 20<sup>th</sup>and 21st centuries that represent the Francoist dictatorship to enable us to analyze the legacy of the historical trauma of Francoism in present day Spain. Topics to be discussed will include: ideological struggles, censorship, the oppression of women and other minority groups, the experience of exile, and the controversial process of historical/collective memory in contemporary Spain. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5783,2023,2606,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-325','<div class="desc"> <p>In this interdisciplinary course we will examine representative works of art and literature that are centered on the city of Madrid as a cultural, social, historical and intellectual space. We will discuss artistic and philosophical issues including, among others, the conception of space revolution in Diego Velázquez, the tensions of Enlightenment and Romanticism in Francisco de Goya, and the existential representation of life after the Spanish Civil War in Camilo José Cela. We will explore the interconnection of selected artistic and literary works with the purpose of approaching an understanding of the multilayered and fluid creation of the city’s identity.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5784,2023,769,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-340','<div class="desc"> <p>This course serves as a general introduction to the study of the Spanish sound system. The objectives of this course include strengthening students'' Spanish pronunciation in the direction of a more native-like normative pronunciation and introducing them to phonetics and phonology. Students will be introduced to theoretical means of analyzing the sound system of a language. They will also examine contrasts between American English and Spanish and apply these concepts in exercises of both written transcription and oral production as well as with a linguistic analysis of spoken Spanish. Finally students will also be acquainted with phonological differences among the dialects of the Spanish language.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5785,2023,1097,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-341','<div class="desc"> <p>This course consists of an introduction to historical Hispanic linguistics. Students learn about the major phonological morphosyntactic and lexical changes that have occurred in the language from the time of the arrival of the Roman armies into the Iberian Peninsula until the present. Foreign influences on the evolution of the Spanish language are discussed briefly. The primary focus of this course is the internal history of the language from Vulgar Latin to Modern Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5786,2023,1134,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-342','<div class="desc"> <p>This course consists of an introduction to the Spanish language and Spanish-speaking communities in the United States, home to the second-largest Spanish-speaking population in the world. We will focus on questions like: who are the principal groups of Spanish speakers in the U.S.? Where do they live, and how and when did they arrive to the U.S.? What are the principal linguistic features of their Spanish? In the U.S., who uses Spanish, and in what contexts, and for what purposes? What is the role of Spanish in public services, the media, and schools? In this course, we will also confront social issues such as language attitudes, bilingualism, and the interaction between language and identity. This course will be conducted in Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5787,2023,1427,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-343','<div class="desc"> <p>Language use symbolically represents fundamental dimensions of human behavior and social interaction. For instance, what can you immediately infer about a Spanish speaker who uses the word “zumo” to describe the orange beverage commonly drunk at breakfast? Most likely, they are from Spain, otherwise they might describe this beverage as "jugo."</p> <p>This course introduces the basic concepts of sociolinguistics, using Spanish as our tool of exploration and description. Sociolinguistics focuses on the symbolic value of language as an expression of group identity based on region, gender, ethnicity, socioeconomic class, age, or other ways of defining group affiliation. In this course, we describe key notions of sociolinguistics such as the speech community, the sociolinguistic variable, and field methods. The core goal of the course is to identify phonological and morphosyntactic variation throughout Spain, Latin America, and the US, and identify what this variation tells us about language change and development as well as about the social characteristics and identities of the speakers themselves. The course also surveys other related topics such as language contact, bilingualism, Spanish as a heritage language, language attitudes and language identity in the U.S. and elsewhere, language and law, language and age, and language and gender. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5788,2023,1355,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-351','<div class="desc"> <p>A study of Cervantes'' narrative and drama in the context of certain literary trends of the European Renaissance. The course will focus on the Novelas Ejemplares selected parts of Don Quijote and Entremeses and it will explore Cervantes'' treatment of the genres and currents which influenced his art.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5789,2023,986,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-362','<div class="desc"> <p>This course will focus on the theater of Federico García Lorca and the cinema of Luis Buñuel and Pedro Almodóvar. Students will engage in an in-depth study of García Lorca''s plays examining his theatrical representation of surrealism, gender, and sexuality in conjunction with key films of Buñuel and Almodóvar.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5790,2023,1098,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-363','<div class="desc"> <p>This course will apply current theories of autobiographical discourse to Spanish Latin American and U.S. Latino life-writing. Students will examine the relation of personal identity to dominant ideologies of gender race class and politics and will explore the role of memory and fantasy in literary self-expression. Authors studied will vary from year to year but will typically include Gloria AnzaldÃºa Reinaldo Arenas Juan Francisco Manzno Carmen MartÃ­n Gaite Rigoberta Menchu Constancia de la Mora and Mario Vargas Llosa. Students will have the opportunity to write their own autobiographies.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5791,2023,3261,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-365','<div class="desc"> <p>This course examines discourses of gender and sexuality and their intersections with race, politics, religion, and national identity in Spain from Francoism to the present. By reading a selection of literary works and watching representative films and TV shows through a feminist lens, we will explore cultural artefacts that subvert, perpetuate, and construct notions of gender and sexuality in 20<sup>th</sup> and 21st century Spanish society. Some of the topics to be discussed are: Women’s oppression and resistance during the Francoist dictatorship, the (de)construction of the Spanish <em>macho</em>, the post-Francoist experiences of LGBTQ+-identifying lives, gender violence, processes of exoticization and marginalization, and queer and feminist re-writing of Spanish history in the 21<sup>st</sup> century. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5792,2023,1632,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-370','<div class="desc"> <p>In this course we will look at the jungle as a space where western civilizations desires and fears come into tension with the imagined "other" so that sometimes the jungle can be beautiful and desirable like the Garden of Eden and other times savage and dark like hell. Readings will include Latin American works of fiction (by Jose Eustasio Rivera Romulo Gallegos Horacio Quiroga and William Ospina) excerpts from the anthropological discourse of Wade Davis narcotraffic narratives testimonial literature (by Ingrid Betancourt and Clara Rojas) as well as environmental discourse and film in order to analyze the particular forces of history that intersect in each narrative. Topics to be discussed will include: exploitation and subjugation vs. autonomy and self determination; the search for ethnobotanical knowledge and the hallucinogenic journey; the playground and hidden operational spaces of drug traffickers; the imprisonment of the kidnapped victims from the guerrilla war against the state and paramilitary forces; the environmental movement and the concept of ecotourism. We will frame our analysis in contemporary critical theories relevant to the topics being discussed. Upon completion of this course students will be able to critically understand the value and complexity of the jungle in the geography and imagination of the Latin-American modern landscape and identity.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5793,2023,3213,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-371','<div class="desc"> <p>This class examines the politics of human rights and histories of state­-sponsored violence in contemporary Latin America. By focusing on the Americas as a specific geopolitical site for our discussions, we will gain a better understanding of the main cultural, political, and philosophical debates over universal human rights. The class will also examine how culture and art can serve as a form of resistance to legacies of oppression and violence in the Americas. We will refer to critical human rights and feminist theory in order to assist our understandings of the experiences of those affected by Latin American state violence and the formation of Latinx diasporic communities in the United States. Students taking this course will gain an understanding of the histories of the region, the relationship between universal human rights, nationalism, political violence, and contemporary gender issues. The class will also refer to the limits and possibilities of human rights in the pursuit of attaining justice for state­-sponsored crimes. This course is taught in Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5796,2023,771,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-382','<div class="desc"> <p>This course analyzes the narrative development of the contemporary Mexican novel from the Mexican Revolution to the present. Principal novelists studied in this seminar are Mariano Azuela Juan Rulfo Carlos Fuentes Gustavo Sainz Elena Poniatowska Angeles Mastretta and Laura Esquivel. This course combines textual analysis with the application of contemporary literary theory.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5797,2023,389,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-383','<div class="desc"> <p>This course offers a representative overview of Chicano literary production covering five genres: poetry theater novel short story and essay. An historical framework is outlined to establish the different periods of Chicano creativity from its origins to contemporary times using a series of works and authors to illustrate their respective social context.</p> </div>','SPAN 301 , SPAN 302 , SPAN 303 , or SPAN 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5800,2023,772,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-397','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5801,2023,1428,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/300/span-398','<div class="desc"> <p>The goal of the Community Translation Internship is to provide students with an experiential understanding of the practice of translation. The Community Translation Internship allows students to learn through direct experience the different steps in the translation process as well as examine the challenges that bilingual professionals face in their efforts to reach out to underserved populations such as the Spanish-speaking communities. All students enrolled in the Community Translation Internship work with a community-based organization for an average of eight hours a week.</p> </div>','SPAN 340 or above and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5802,2023,390,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/400/span-490','<div class="desc"> <p>This course will provide an in-depth analysis of one or more of the following genres: drama poetry essay novel short story and film with an introduction to contemporary literary film and cultural studies theory. Texts will be drawn from Spain and Latin America. Open only to Spanish majors in their senior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5804,2023,773,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/span-spanish/400/span-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5805,2023,3188,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-100','<div class="desc"> <p>This course will look at the pivotal beginnings of the performance studies field, its roots in various disciplines, and will explore its evolution over the past 50 years. We will begin by asking, “What is performance studies?” and "How does it connect with theater studies?" Each week we will look at different answers to this question as we read and discuss the work of various artists and theorists to see how their work illuminates the question. These readings will be complimented by viewings of performances so that we can engage the questions on both a practical and theoretical level and demonstrate the critical entanglement between performance theory and practice. As scholars and practitioners we too will experiment with praxis by activating each section with our own performance experiments. As much as this class is a historical survey of the field, it is also a laboratory where we will explore how we can perform in order to understand theory and how we can use theory to understand performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5806,2023,392,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-101','<div class="desc"> <p>The ability to read a play with insight and imagination is foundational to studying and making theater. Because playscripts are meant for the stage and not the page, the techniques we use to read them are uniquely challenging. In this course, we study scripts by a variety of contemporary American playwrights, investigating the elusive relationship between the text and its ultimate destination - the live stage. By focusing on the essential elements of dramatic writing (including character, structure, language, and thematics), and placing scripts in their social, cultural and political contexts, we work to unlock each narrative’s full performative potential. Our understanding is enhanced by creative research projects and viewing key productions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5807,2023,393,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-110','<div class="desc"> <p>This course is the foundation of our acting program. In it our students explore how an actor gives life to words and moves from a script to active performance. Students work with Shakespeare''s sonnets as well as contemporary pieces to develop physical and verbal facility as well as interpretive skill. The course is seven weeks in duration, allowing two sections to be offered each semester -- one in the first seven weeks of the semester and the other in the last seven weeks of the semester. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5808,2023,394,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-120','<div class="desc"> <p>In this course we introduce students to many of the different areas of theater production with a primary focus on scenic construction, also including drafting, lighting equipment, rigging practices and special effects. <em>The course includes a laboratory through which techniques taught in class are applied. The laboratory averages 36 hours over the semester with laboratory schedules to be arranged with the instructor. Students are required to purchase some materials for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5809,2023,395,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-121','<div class="desc"> <p>Our production laboratories are applied courses for student designers, technicians and managers who are on crews of productions directed, designed or directly supervised by faculty members in the department. In order to complete a theater minor or major, students are required to complete production laboratories in two separate areas, one of which must be a running crew for a department production. The course may be repeated for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5810,2023,396,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-122','<div class="desc"> <p>These laboratories are designed for our student designers technicians and managers who are given primary responsibility on production crews directly supervised by faculty members in the department. In the laboratories students pursue additional research and practical applications beyond the requirements of THEA 121 and may use this course to meet one of the THEA 121 requirements for a major or minor. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5811,2023,397,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-130','<div class="desc"> <p>In this course students study the theory and apply the methodology of the Jose Limón Technique. Developed from the principles of fall and recovery the Limón Technique is built upon motion through succession suspension alignment and opposition. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5812,2023,774,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-131','<div class="desc"> <p>In this course students learn the fundamentals of jazz and tap dance with an emphasis on body alignment strength flexibility rhythm and coordination. During the semester we experiment with lyrical and contemporary jazz combinations as well as tap variations designed to develop musicality self-expression and performance skills. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5813,2023,398,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-133','<div class="desc"> <p>Tai Chi Chuan is the study and practice of slow controlled movement, breathing, and realignment of the body. Sometimes referred to as standing yoga, Tai Chi Chuan has been practiced for centuries for its many benefits, including stress management, disease prevention, and increase in energy. Our focus in this class is on relaxation, gentle movement, and meditation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5814,2023,399,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-134','<div class="desc"> <p>In <em>Beginning Ballet</em> we study the principles and execute the techniques of ballet based on the Vaganova method. Students are taught the fundamentals and elementary vocabulary of ballet through <em>barre</em> center and traveling combinations and exercises. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5816,2023,1041,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-136','<div class="desc"> <p>What is Bollywood? A fun, expressive dance form that originates from the popular movie musicals out of the Indian film industry. A commercial dance style that has entered popular culture in both India and the US, Bollywood is a fusion dance style that incorporates elements from Indian Classical, Indian folk, Western styles of Hip Hop and Jazz, and world dance forms such as Salsa and African. It is a high-energy, cardio dance style that oozes style, expression, and grace. Students will learn the basics: <em>mudras</em>, foot work, and expressions to equip them in any Bollywood class or audition. They will also learn an array of choreography that covers the Bollywood landscape.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5817,2023,400,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-137','<div class="desc"> <p>This is an introduction to a study of choreography based on the Nikolais/Mettler methods of creating dances. Our tools include the manipulation of motion through space time shape and energy volumes within the context of the body and its surroundings; and our work culminates with studio performances of pieces choreographed by the students in the class. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5818,2023,401,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-139','<div class="desc"> <p>Exploring the richness of African dance and music traditions from four African regions, this course is devoted to the study of authentic dances, songs and drumming from Africa, as well as their historical and cultural contexts. Students may choose to focus on either dance or percussion. Percussion students will learn traditional rhythms for djembe and talking drum as they inform and interact with dance movements. Dancers begin with exercises to condition our bodies for the rigor of the African Dance forms -- developing strength, stamina, coordination, flexibility, and rhythmic awareness, and move to the informed and joyous practice of the dances. <em>Graded on a Credit/No Credit basis only. May be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5819,2023,1495,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-141','<div class="desc"> <p>We study and practice some of the most popular dance forms of the twentieth century. Through theater film and television many of these dances have expressed the spirit and the style and particularly the romantic temper of their times: from the quick steps of the Fred Astaire films to the swing dancing in <em>Malcolm X</em> and <em>A League of Their Own</em> and the tango of <em>The Scent of a Woman</em>. The dances taught include fox trot waltz swing and tango. We strongly recommend this class for our student actors. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5820,2023,403,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-142','<div class="desc"> <p>In this course students study folk and historical dances drawn from Eastern and Western Europe along with folk dances of the United States derived from those traditions. Performance opportunities may include Viennese waltz and dance-based children''s theater. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5821,2023,1742,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-143','<div class="desc"> <p>Students explore the rich traditions of Latin Dance from its origins in the African diaspora found in Cuba, Caribbean and Latin American nations as well as the influence and effect of these dances throughout popular Western culture. Students embrace through performance various dance forms developed in Mexico and throughout Central and Latin America and study the place and importance of the dances in Latin cultures.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5822,2023,775,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-175','<div class="desc"> <p>This introductory design course grounds students in aesthetics as they relate to design for performance and the role of design in the collaborative process of production. Those students interested in becoming designers receive a foundational experience for specializations offered in subsequent classes. Students explore elements of design and the principles of composition as they can apply to theater and film. Over the semester students come to understand and acquire the skills to develop visual expressions of the meaning of play and film scripts. Through individual and group design projects, students learn to incorporate script analysis, design research, and visual presentation techniques. This course is intended for first and second year students. Juniors and seniors may enroll with the permission of the instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5823,2023,1135,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-190','<div class="desc"> <p>Theater Now takes students off campus and in to local performance venues to see the work of diverse artists making theater from a broad base of inspirations. A wide sample of local theater is represented – thematically, geographically, culturally. Friday evening field trips take students to a variety of Los Angeles’ artistic outlets, while Monday afternoon sessions with guest artists put class members in direct contact with the actors, writers, and directors whose plays and performance pieces they have seen. Our work offers a comprehensive introduction to active theater-going, L.A.''s performance community, the creative habits of working artists and the social, political and aesthetic ideas behind their work. T<em>here is a ticket fee not to exceed $75 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5825,2023,2866,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-195','<div class="desc"> <p>What does performance do? Why perform? What is the essence of the “live” and what is the impact of being in the same time and (virtual) space? We will unpack these questions through analysis and performance, looking closely at seminal pieces that speak to this moment and calling on experts in design, technical theater, comedy and solo performance to give behind-the-scenes insight into the making of live performance. Bracketed around questions of liveness, social action, and impact, students will take specialized workshops with theater faculty who will address these questions through their areas of expertise, providing students opportunities to experiment with an array of performance practices.</p> </div>',NULL,'ARTS 250 ',NULL);
INSERT INTO course_descriptions VALUES(5826,2023,776,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/100/thea-197','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5827,2023,990,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/copy-of-thea-245','<div class="desc"> <p>Students in <em>Stage Makeup</em> learn the fundamentals of makeup design for the theater. We cover a number of makeup techniques including basic three-dimensional corrective, glamour, character and old-age makeups with some special effects makeup. During the semester, students put theory into practice as they create a variety of practical and creative makeup designs. <em>There is a materials fee for this course, not to exceed $75.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5828,2023,2891,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-200','<div class="desc"> <p><strong>Immersive Visual Environments with Commonplace Technology</strong></p> <p>Contemporary theater—especially as performed on Broadway—has become a high tech multimedia production with budgets in the millions. How can emerging theater artists compete with this level of spectacle and/or create new work that is equally compelling? In this course students will learn how to check the boxes of the newest innovations in big budget theater and performance without the financial demands. We will level the playing field by creating forms of high spectacle through economical means. Students will learn to devise spectacular visual stories using commonplace objects. Throughout this project based course, students will study the fundamentals of visual storytelling both through playing with lights and shadow led by cutting-edge artist Christine Marie and through developing story with performance artist and professional storyteller David Crabb. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5829,2023,988,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-201','<div class="desc"> <p>We study the artistry of contemporary theatrical movements as well as American writers from divergent cultural and aesthetic backgrounds. By looking at movements and artists in their cultural and social contexts we explore the sources the aims and the artistic strategies of their works while developing an understanding of important new voices in American Theater. The focus of the class will vary from year to year. May be repeated for credit one time with a different topic.</p> <p><strong>Looking for August: A Critical Exploration into the Art, Life, and Legacy of August Wilson</strong></p> <p>African-American playwright August Wilson is perhaps the greatest American dramatist of the 20th Century. His unmatched “Century Cycle” chronicles the African-American experience, and unearths deep-rooted dysfunctions of racism and socio-economic oppression, while at the same time celebrating the joy and resilience at the heart of African-American culture. Wilson was also an arts theorist, bringing to the fore front several explosive and controversial concepts concerning the American theater industry, particularly race-based vs. multicultural based casting. In this engaging course, we will explore Wilson’s epic, ever evolving career. Course participants will collaboratively engage with some of his most iconic characters, in the attempt to re-discover what makes them so impactful and electrifying. We will discuss Wilson’s life trajectory, his roots in Pittsburgh and griot approaches to playwriting, and peer deeply into some of his most iconic works, including Fences, A Piano Lesson, and the often misunderstood Joe Turner’s Come and Gone. We will also examine Wilson’s massive impact on 21st Century playwrights of all nationalities, and attempt to come to some comprehension of Wilson’s almost limitless influence on theater and global culture. </p> <p><strong>The Black Arts Movement Explored and Deconstructed</strong></p> <p>An in-depth, intellectually stimulating exploration into the complex and impactful Black Arts Movement of the 1960s and 1970s. Through reading and analyzing the poems, plays and criticism of the time, as well as lectures and small group discussions and “on your feet” performance activities, students will gain insights into the people, the places, and the critical junctures that emerged during this profoundly explosive era of art and culture. Artists explored include Amiri Baraka, Sonia Sanchez, Nikki Giovanni, Henry Dumas, Audre Lorde, Ed Bullins, Ntozake Shange, and others. Themes/concepts include black identity, the connection between black arts and black power, the rejection of integration as an ideal, LGBTQ and Black Arts, the assassination of Malcolm X, John Coltrane and Sun Ra, black radical thought, the African-American male as a Christ figure, male chauvinism in Black Arts and Black Power, and “future directions,” i.e. the influence of the Black Arts Movement on other cultural movements and American aesthetics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5830,2023,404,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-202','<div class="desc"> <p>Looking at a small number of Shakespeare''s scripts from the vantages of actor director and playwright we examine the unique and complex relationship between Shakespeare''s literary constructions and their possible performances. We analyze how through language and structure he develops characters of psychological complexity; how he develops stories from extra-theatrical material; and how in style and subject matter his scripts relate to one another. This course offers students a bridge between literary study and theatrical enactment: looking closely at Shakespeare''s designs from the perspective of the theater practitioner-from in most ways Shakespeare''s own perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5831,2023,1136,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-203','<div class="desc"> <p>In this course we investigate a variety of 20th and 21st century theatrical productions across the globe staged during times of conflict and crisis: from online performances to amateur stages in restaurant back rooms in workers'' clubs and cafes to professional and Broadway theaters. From the 1920''s agitation trials (<em>Agitsudy</em>), mass spectacles and agitprop theater during the Russian Revolution to contemporary theater''s responses to COVID 19, anti-blackness, and other forms of racism and social oppression, we will examine how artists and activists use theater to respond to social and political unrest: sometimes as a tool to fight oppression and at other times as a tool to encourage obedience and propagate national political ideals. From performances staged in Sarajevo to Rio de Janeiro, from Mexico City to New Orleans, and from the streets of Moscow to the streets of New York City and beyond, the class thinks through art as activism and activism as art, examining how theatrical tactics transcend the boundaries of traditional performance spaces. We examine the performance theories and strategies emerging from these theatrical moments as we study seminal plays from these periods. For the final project, students in the class will develop performance projects in response to a contemporary crisis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5832,2023,1317,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-204','<div class="desc"> <p>In this course, we introduce students to the ways comedy can influence and transform society. We will study scripted as well as unscripted forms of performance, including stand-up, physical comedy, sketch, Teatro Campesino style <em>actos</em>, and faux news shows. Students learn the formal structure of the different comic forms through extensive writing and revision both individually and in collaboration with other students. Students develop an understanding of the role comedy plays in socio-political critique through research of issues about which they are passionate and in the subsequent creation of solo and group work illuminating those issues for their peers in a final cabaret performance. Not open to frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5833,2023,2362,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-205','<div class="desc"> This course addresses the fluid boundary between law and performance. We will think through how performances of law influence legal practice and vice versa. We will also interrogate how theater provides an alternative site for the performance of justice, one that may satisfy needs that go unmet in state and federal courts. We will study trial transcripts as legal and cultural documents, and we will look at their dramatizations, putting these plays into conversation with contemporary theater, performance, and legal criticism while also thinking about how our own needs and impressions of justice have been, or can be, staged in and through performance. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5834,2023,2900,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-206','<div class="desc"> <p>In this energetic and creatively maddening class, students will explore Shakespeare’s <em>Richard III </em>and several adaptations in a unique and highly charged manner. By yanking the Bard off his high horse, and identifying universal themes and structural innovations inherent in Elizabethan poetic meter, course participants will gain newfound understanding and appreciation for the work and legacy of Shakespeare. Instead of looking at classic works as an untouchable, or “holier than thou,” canon instead we will investigate how playwrights have been inspired by, deconstructed and reconstructed them. In addition to Shakespeare’s <em>Richard III</em>, students will explore several bold adaptations such as Carlyle Brown’s <em>The African Company Presents "Richard III,"</em> <em>Teenage Dick </em>by Mike Lew, as well as Will Power’s own <em>Seize the King</em>. Perhaps most importantly, students will have the opportunity to learn iambic pentameter, construct their own post-modern, Shakespearean mash-up scenes, and learn the very-latest contemporary methods of verse-based performance. In this performance seminar, we will compare and contrast Shakespeare’s metric language with other heightened language forms, from ancient Greek poetry to hip hop lyrics. Filled with rhythm, poetry, and both an appreciation and utter disdain for anything old and crusty, this course promises to be a ridiculously crazy, wild ride for the ages. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5835,2023,405,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-210','<div class="desc"> <p>In this course students develop a deeper sense of physical expression, kinesthetic response, ensemble work, creativity, and imagination. Students apply this training in solo and scene work both in the studio and on camera. At the end of the semester, students apply the preparation and techniques learned throughout the semester in final scene projects using script analysis, character work, object work, and physical expression in both classical and contemporary texts. <em>There is a ticket fee not to exceed $50 for this course.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5836,2023,406,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-211','<div class="desc"> <p>Our Performance Laboratory is offered as an applied acting course based upon roles played in our professionally directed Keck Theater productions. This course is offered only for grades of Credit/No Credit and may be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5837,2023,777,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-212','<div class="desc"> <p>In this course student actors will continue to develop audition techniques introduced in <em>Introduction to Performance</em> and <em>Acting 1</em> applying them to the standard "general audition" format. In addition our students learn about the audition and casting process in professional theater through a guest speaker series of casting directors and professional film and stage actors. Not open to frosh. <em>Graded on a Credit/No Credit basis only. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5838,2023,778,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-215','<div class="desc"> <p>Working with selected scripts from the best of recent and contemporary screenplays our students develop techniques for working in front of a camera as a specific application of the work of both <em>Acting 1</em> and <em>Acting 2</em>. <em>There is a materials fee of $60 for this course. THEA 310 is strongly recommended as preparation.</em></p> </div>','THEA 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5839,2023,408,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-234','<div class="desc"> <p>Students develop and refine ballet technique based on the Vaganova Method. This course is offered only for grades of Credit/No Credit and may be repeated for credit.</p> </div>','Two semesters of THEA 134 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5840,2023,782,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-237','<div class="desc"> <p>Building upon the work from <em>Beginning Choreography</em> students develop more sophisticated choreographic strategies language and techniques with an emphasis on group choreography including site-specific work and studio performances. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','THEA 137 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5841,2023,411,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-244','<div class="desc"> <p>Our stage management course introduces students to the art and techniques of stage management helping them acquire the theoretical knowledge and the practical skills to manage theatrical productions from casting through performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5842,2023,883,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-246','<div class="desc"> <p>In <em>Costume Construction</em> students acquire the skills necessary to construct basic garments for the stage. At the end of the course each student will build a costume piece.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5843,2023,1042,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-248','<div class="desc"> <p>We introduce students to the theory and application of sound and music as elements of design for theater dance and other collaborative multimedia dramatic forms. Throughout the semester we address fundamental issues of sound design: including script analysis conceptual approaches to sound music underscoring working with audio equipment and sound editing. Over the semester our students learn how to work within a creative team of designers coordinating the many design elements of various dramatic forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5844,2023,1102,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-250','<div class="desc"> <p>Period style can be characterized as the aesthetic traits common to a particular historic or cultural moment. For recorded media and live performance, writers, directors and designers set their storytelling in a framework of time and place. In this class, we explore examples of shifting styles across select non-Western and Western cultures and through time and seek to discern their influence on other cultures or historical periods. Through this exploration, we begin to understand how architecture, interior design, fashion history and the act of dressing evolved throughout the centuries and across cultures because of technological advancements, changes in economic and social class structures, in political climates and through appropriation of cultural aesthetics. Why was there a kimono specialist in the costume department of <em>Westworld</em>? How did Ruth E. Carter develop her Afrofuturist vision for <em>Black Panther</em>? Where would you find visual and dramaturgical resources for <em>Vietgone</em>, or <em>Hair</em>, or <em>Cambodian Rock Band</em>, the action of each set in a similar historical period but whose stories are told from very different cultural perspectives?We will investigate these and other questions through reading, and critical analysis of visual records, plays and films, in-class discussions, and presentations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5845,2023,412,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-260','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take 260 and 261 in either order. In four intensive sessions, students learn five workshops geared to the third grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited.</p> </div>','THEA 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5846,2023,783,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-261','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take THEA 260 and THEA 261 in either order. In four intensive sessions students learn five workshops geared to the fifth grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited. Graded on a CR/NC basis only.</p> </div>','THEA 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5847,2023,413,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-275','<div class="desc"> <p>Our course in scenic design provides intermediate training in technique and exploration of theory specifically aimed at designing scenery for the theater. Our students learn several methods for developing and communicating their design ideas including basic drawing and drafting concepts CAD drafting using <em>VectorWorks</em> and both physical and digital model-making. <em>There is a materials fee of $60 for this course.</em></p> </div>','THEA 120 or THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5848,2023,2567,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-290','<div class="desc"> <p>This topics course provides opportunities to work on performance outside of traditional naturalistic traditions. Topics change annually. First-year students may only take this course with permission of instructor. May be repeated once for credit when taken as a different topic. <em>Note: Different topics may satisfy different Core requirements</em>.</p> <p><strong>Creating Community Engaged Theater</strong></p> <p>Under the guidance of members of the world renowned and community engaged Cornerstone Theater Company, this course will introduce students to the Cornerstone method of creating original theater work that addresses local concerns through community collaboration. During the course, students will help with The Highland Park Community Project—Cornerstone’s community engaged project in rehearsal and performance in the fall semester. This production will provide the experiential aspects of the course, some of which will take place off-campus in the Highland Park Community. In regularly scheduled class meetings, students will study the Cornerstone methodology, especially intention and engagement, and through discussion, lectures, and research, be introduced to existing approaches to community based theater. Topics will include how community engagement informs acting, directing and design. <em><em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></em></p> <p><strong>Reframe the Game: Strategies for a More Inclusive American Theater</strong></p> <p>Reframe the Game is a deep dive into Equity, Diversity and Inclusion (EDI) principles, as they apply to working in the theater, as well as in interpersonal communication practices. Through hands-on activities, discussions, research and interactions with guest practitioners, the course will address why this work is vital to our field, and how EDI lays the foundation for more creative and imaginative artistic workspaces and practices. The course will be organized into three parts. Part One will focus on Vocabulary and Power Structures: The cohort will focus on establishing a shared vocabulary as a foundation for conversation about social identity, privilege, historical and institutional inequities, and ally-ship, as a means to develop skills to better identify and dismantle inequity when we see it. We will look inward to examine where we as individuals fit into the social landscape of America, and how our identities affect how we move through the world. Part Two will focus Research and Examination: Students will research EDI initiatives and strategies at US regional theaters as case studies to examine how stated EDI principles may (or may not) align with programming and institutional culture. In addition, local guest artists and practitioners whose work strongly aligns with social equity will visit the class for deep dive conversations about the work that they do, the challenges they face, and where they see the future of our field. Part Three will focus on Final Projects and the question What Now?: In small groups, students will apply what they have learned over the course of the semester to create an original exercise, workshop or governing policy that addresses a specific EDI concern in their community (institutional, local, national or international) to present to their classmates and invited faculty in the final weeks of the semester. Prerequisite: THEA 101, THEA 210, or by instructor permission. <em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></p> <p><strong>Generating Independent Theater</strong></p> <p>This interdisciplinary course will provide an opportunity for students to define their interests as performers/writers/producers and to develop original material, an artistic vision, and producing expertise that will lead to a realized performance. Individual skill sets and interests including storytelling, dance, character-work, visual art and music may each provide a jumping off point for this work. At the beginning of the course, a series of improvisational exercises, mini-performances and character studies, supported by readings on contemporary solo, immersive, experimental and environmental theater, will guide students to land on personal solo or two-person projects. In the second half of the semester, students will craft these pieces utilizing their peers as a think-tank. This generative, collaborative process will emphasize the importance of ensemble both onstage and behind the scenes during the creative and production process. To culminate their work, the class will be responsible for the production aspects necessary to present their pieces in a public performance on-campus. </p> <p><strong>Autobiographical Performance: Laughing At Ourselves</strong></p> <p>In this course, participants will learn how to create compelling and humorous personal nonfiction narratives for the stage, studying classic narrative structure and paying close attention to theme &amp; detail. There is a long history of performers whose autobiographical solo work, like Crabb’s, simultaneously finds comedy in the tragedies of their lives while infusing the mundane with drama. To learn how to do this, students will study seminal storytellers and theater makers, (such as Spalding Gray, John Leguizamo, Whoopi Goldberg, Julia Sweeney, and others) who use their lives and experiences as templates for performance. Students will also review Moth-style storytelling to help find their own voice through a close examination of identity, self, and how we perform in the world. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5850,2023,991,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/200/thea-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5852,2023,1356,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/copy-of-thea-315','<div class="desc"> <p>In this course, designed for the novice performer as well as the advanced actor or singer, we focus on introducing students to the art of acting a song. We examine the literary and musical elements of scripts to reveal character and narrative, only here we do this while singing. Performers prepare and present musical selections from the Broadway canon, exploring how the elements of healthy singing (including breath control, phrasing, and placement) help convey character and story. Through freeing our musical voices to best express persona and narrative, we we examine the intersection of singing, acting, and audience connection. All experience levels welcome. A ticket fee, not to exceed $50, is associated with this course. Prerequisite: at least sophomore standing or permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5853,2023,993,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/copy-of-thea-320','<div class="desc"> <p>Building on the foundation of Introduction to Technical Theater, the students in this course learn advanced construction techniques, metal working and welding, furniture construction and repair. Students in the class will also act as crew chiefs for Theater Department productions.</p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5854,2023,414,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-301','<div class="desc"> <p>As artists and scholars, we will discuss and study several key moments in theater history from Greek Drama to Medieval religious performances to modern and experimental theater. Throughout the semester we will examine theater-in-context, attending to the circumstances (political, social, historical, and artistic) surrounding the performance event. We will engage with drama theory to deepen our analysis of dramatic texts and the performances of them. With an emphasis on close readings, critical thinking, and creative engagement with the materials, we will interrogate the boundaries between performers and audience and the ways theater makers have used performance to challenge or affirm the status quo. <em>There is a ticket fee of $75 for this course.</em></p> </div>','THEA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5855,2023,992,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-302','<div class="desc"> <p>During the semester we study the works of various twentieth century playwrights. Different years will feature different playwrights: so one semester might look at farceurs another semester political pioneers and another European iconoclasts. In addition to reading several scripts by each playwright our students also attend live performances prepare research projects and create performance projects in response to the semester''s writers. Students may use this course to fulfill the Junior Writing Requirement for the Theater Major.<em> There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5856,2023,1496,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-303','<div class="desc"> <p>The focus of this course is on the history literature and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works while play attendance will keep our focus on these plays as performance. <em>There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5857,2023,415,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-310','<div class="desc"> <p>Acting 2 advances the techniques and skills introduced in Acting 1. Students will continue to explore character development and scene work through an array of texts and styles. Students will also explore acting methods that will help them become more flexible, daring, collaborative, and creative performers. An emphasis will be put on Solo-Performance techniques. Students will actively create a self-sustaining piece of solo theater from conception to creation and finally to the stage. Course participants will also discover and evaluate texts and performance practices of previous solo-theater practitioners. In the process, students will learn how to act with increased freedom and to create characters with genuine psychological complexity, accumulating tools and skills applicable to working both on stage and on screen.</p> </div>','THEA 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5858,2023,417,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-311','<div class="desc"> <p>Our upper-division applied acting course is available for students performing significant roles in professionally directed Theater Department productions. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit. It is available only with permission of the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5859,2023,784,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-316','<div class="desc"> <p>In this culmination of the Theater Department''s acting sequence our students explore through practice the demands Shakespeare''s scripts make upon actors. During the semester students in the class work with five to six of Shakespeare''s scripts from various genres in order to develop facility with Shakespeare''s verse and prose in performance.</p> </div>','THEA 202 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5860,2023,994,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-325','<div class="desc"> <p>Studying the theories the psychological foundations and techniques of lighting design for the theater our students develop in this course an intellectual and practical foundation of this significant and accessible area of theater design. During the semester we guide students in the class through bothindividual and group design projects. <em>There is a material/tickets fee of $60 for this course which includes one two-hour laboratory session each week.</em></p> </div>','THEA 120 or THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5861,2023,785,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-330','<div class="desc"> <p>Students in this course analyze the various requirements for producing live performance events. In developing solutions to the many difficulties presented by live events we examine in particular the artistic, legal and financial responsibilities of the producer. Through projects, case studies, and research, our students look at the creative and practical aspects of live presentations as they come to understand the myriad considerations required to successfully produce live performances for theater music and other cultural events. Not open to first year students.</p> </div>','THEA 120 and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5862,2023,418,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-370','<div class="desc"> <p>This course develops a deeper understanding of the process of costume design for theater and film. Students will develop individual costume processes by learning to research, conceptualize, and design. In addition to creative aspects of design, students will develop the ability to break down scripts for both the stage and screen, learn to budget for shows, and develop a language within the industry. Prior art experience is not mandatory. Free hand drawing, digital rendering, and collage will be explored and developed in projects for the course.</p> </div>','THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5863,2023,419,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-380','<div class="desc"> <p>We engage our students in Playwriting with the art of writing for the live stage. Through reading scripts by established authors and generating original writing, students develop their dramatic skills and theatrical imaginations. Creative assignments focus on crafting well-developed characters, sound story structures and compelling dialogue. As a final project, each student writes and rewrites a short play. Sophomore standing or permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5864,2023,420,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-390','<div class="desc"> <p>For advanced theater students we offer an applied course for significant work undertaken in performance design technical theater or management in faculty-supervised projects. A student enrolled in this course works directly with a faculty mentor in the design and execution of the individual project. </p> <p>Section 1 - Advanced Projects in Theater: Story/Voice/Community </p> <p>Section 2 - On-campus projects</p> <p>Permission of instructor required. Course may be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5867,2023,787,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/300/thea-397','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5868,2023,788,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/400/thea-410','<div class="desc"> <p>We introduce students to the art of directing. Our students explore the directing processes of script analysis casting working with actors manipulation of space use of sound and images developing designs and mounting productions for theater. During the semester students in the class stage two performance sequences: one in a classroom format the other produced on the Keck stage. THEA 316 is strongly recommended for preparation. This course may be repeated for credit. Permission of instructor required.</p> </div>','THEA 120 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5869,2023,421,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/thea-theater/400/thea-490','<div class="desc"> <p>This is a course for students engaged in senior comprehensive projects in Theater. <em>Only open to senior Theater majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5871,2023,423,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-101','<div class="desc"> <p>This is an introductory course on environment and society designed for students with an interest in urban and environmental issues who might want to pursue further studies in Urban and Environmental Policy. It is also offered for those who are interested in the topic even though they will be pursuing another major. The course will include lectures and presentations in several different topical areas; films and speakers that provide insight into the environmental problems and alternative solutions including those based here in Los Angeles; and class discussions and presentation sessions on the readings and topics. The course provides an broad introduction into core topics in urban and environmental policy such as: water issues (where our water comes from); wastes and hazards issues (sources and impacts of pollution); climate change transportation and land use issues (where we work and live and commute); nature in the city (the urban environment); and food system issues (where our food comes from and how it is manufactured and sold) the intersection of science and policy and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5873,2023,1357,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-201','<div class="desc"> <p>This course is designed to provide students with an understanding of the environmental factors impacting human and ecological health including consequences of natural and human-made hazards. Environmental health is a rapidly growing and interdisciplinary field that involves both science and public policy. It is integrated into numerous aspects of our lives both directly and indirectly. Topics to be covered include food safety water access and equality pesticides air quality the identification of environmental hazards the assessment of various risks (including exposure to dangerous chemicals used in toys food workplaces and other activities) and the social and biological causes of disease (epidemiology) Students will gain an understanding of environmental health analytical and scientific methods. We will also explore ways that communities and policy-makers seek to address environmental health challenges. A common thread running through the course will be an examination of how exposure to environmental and health risks vary among different population groups in the Los Angeles area in the United States and around the world and the ways that scientific issues become embedded in and inseparable from issues of policy regulation and justice. We will also explore the role of science in environmental policy-making the enforcement of regulations and the efforts of community groups to influence public policy. (Students are encouraged to enroll in Geology 150 a laboratory science that in parallel explores the spatial and geographic dimensions of environmental health.</p> <p>Not open to frosh without permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5874,2023,424,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-205','<div class="desc"> According to Thomas Jefferson, America was to be an "agrarian Republic" -- a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones as well. Indeed, for many early migrants, America was itself a "city on the hill" -- an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing in the second half specifically on Los Angeles, where new forms of decentralized urbanism took form in the twentieth century. We will explore not only suburbia and freeways, Disneyland and other quasiÂ­urban outposts, but also the changing character of the inner city in the midÂ­twentieth century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today -- multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism -- the changing character of public space, the turn to privatism, and the neglect of public transport infrastructures, challenges to democracy and equality -- are ultimately compatible with the American dream of the "city on the hill" for the twentyÂ­first century. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5875,2023,1198,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-209','<div class="desc"> Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5876,2023,884,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-210','<div class="desc"> <p>Los Angeles is a city often known for its traffic, air pollution, auto-centric land use patterns, and car culture. However, Los Angeles is also a place of transportation innovations and a public commitment to changing the way people move to and through Los Angeles in equitable and environmentally sustainable ways. This class provides an overview of urban transportation issues and systems, focusing on the impacts of mobility policies, systems and infrastructure on cities and on Los Angeles in particular. Through lectures, guest speakers, class exercises and projects, students will explore the history of transportation in the US as well as comparatively with other countries and understand the role of policy in shaping and defining transportation systems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5877,2023,1103,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-214','<div class="desc"> <p style="margin-left:0px; margin-right:0px">The struggle for control of our public education system in Los Angeles has become one of the most high profile conflicts facing the city and its residents. The stakes couldn’t be higher. The lives of children and the hopes and dreams their parents literally hang in the balance. In UEPI 214, Professor Steve Zimmer, a long-time teacher and the former President of the Los Angeles Unified School District Board of Education, will guide students through a journey in understanding the role of public education in our society and tensions over different visions and goals for public schools, including its mission to promote equality, equity, and mobility. The course will also explore how public policy can help or hinder public school’s equity mission. The class will examine the effects of expanding racial and economic segregation, increased standardized testing, and toxic stress have on students trying to pursue their dreams and the teachers trying to make those dreams come true. The class will also assess the impact of teacher tenure reform, the expansion of charter schools, the community schools movement and other policy based debates that could influence the future of teaching and learning. Through guest lectures, panels, films, and readings, students will understand the role that policy and collective action can play in pursuing a collaborative agenda. The final project will involve actually writing policies to be presented to the Board of Education and/or other policy makers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5878,2023,1743,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-230','<div class="desc"> This course will cover the problem of climate change and the history and evolution of the climate justice movement. It will examine the organizing and policy tools used by advocates to advance climate justice. The course will begin with an exploration of climate change, the environmental and political factors that cause the climate to change, and why the issue matters to communities across the globe. The course will then look at the history and foundational concepts of climate justice with particular focus on how issues of race and class impact climate justice. Finally, the course will look at how the traditional environmental movement, the labor movement, and global movements advocate for climate justice and what priorities they advance. Key topics to be covered are: the intersection between race and the environment, the relationship between traditional environmental movements and the environmental justice movements, labor movements and the green economy, global solidarity movements. </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5879,2023,425,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-246','<div class="desc"> <p>This course is designed to assess and develop recommendations regarding environmental issues related to the Occidental campus with attention to sustainability as encompassing urban environments and issues of equity, justice, and community. Students will evaluate the College''s current practices such as energy and water use, transportation and parking, building construction and maintenance, landscape and grounds maintenance, hazardous and solid waste generation and management, educational and outreach strategies and how the College''s environmental issues relate to the larger Northeast Los Angeles community. Students will develop proposals and programs to reduce resource use and the College''s overall ecological footprint while also seeking to identify how the College can itself play a positive role in increasing the environmental sustainability of its neighboring community. The course is designed to develop project management and environmental leadership skills with the campus as the arena for change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5880,2023,789,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-247','<div class="desc"> <p>This class is a collaboration between the Urban and Environmental Policy Institute (UEPI) and the FEAST (Food, Education, and Sustainability Team) student service to enhance student capacity to lead and engage with food and gardening projects both on campus and in the community. Through the implementation of projects in campus garden spaces, participation in community service learning projects, and field trips to innovative food programs in Los Angeles, students will gain hands-on understanding of food issues and will complete the course with the ability to help in the design, creation, and maintenance of a garden-based food or sustainability project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5881,2023,1430,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5883,2023,1138,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-295','<div class="desc"> Topics vary semester to semester. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5884,2023,1634,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5885,2023,2568,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-300','<div class="desc"> <p>This course analyzes the legal and policy framework for environmental protection and environmental justice. The course covers the major environmental statutes, applicable civil rights laws, and the next wave of climate change litigation. This course will also place environmental law and policy within the larger conversation around environmental protection and climate change.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5886,2023,790,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty, housing, transportation, crime and violence, pollution, racial segregation and gentrification. It also examines how power is exercised by different groups including business, citizens'' groups, community organizations, unions, the media, mayors and other government officials. The course will also examine the role of city planning and planners, conflict and cooperation between cities and suburbs, problems of urban sprawl, loss of open space, water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe, Canada, and the developing world. Public policies to solve urban problems.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5887,2023,996,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-302','<div class="desc"> <p>This course examines how societies provide people with shelter - through market forces government policy and self-help efforts. The course will focus on the United States but will also look at other societies to help understand the strengths and weaknesses of the U.S. approach. Students will examine such housing problems as homelessness slums (substandard housing) the shortage of affordable housing racial segregation foreclosures and other topics. It will examine the pros and cons and different forms of rental housing and homeownership. It will look at the connection between housing issues and the environment public health education transportation suburbanization and sprawl poverty and inequality and racism. Students will explore housing as an aspect of our culture such as homeownership as the "American dream" and housing as a "haven." The course will explore the history of housing problems and housing policy including zoning racial discrimination finance public housing different government subsidies for housing and taxes. We will debate whether decent housing is a "right". We will look at housing problems and policies at the local state and national levels. Students will explore the politics of housing in terms of the various interest groups - including developers banks tenants community organizations landlords contractors unions and others -- involved in shaping housing policy. Students will also learn about housing as part of the "built environment" architecture land use urban design as a component of urban planning and as a part of "livable" cities. They will also examine housing as a component of real estate development and explore what housing developments - whether for-profit or non-profit - do.</p> </div>','UEP 101 , ECON 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5888,2023,791,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-303','<div class="desc"> <p>This course examines sustainable development from a social economic and environmental perspective. The course focuses on development strategies and approaches led by community-based labor and nonprofit organizations in a context of traditional public and private-sector economic development approaches. Through lectures field trips discussion guest speakers and class exercises students will examine the history and evolution of community and economic development strategies in urban neighborhoods and communities and link these approaches to the field of sustainable development. The course focuses on the historic and contemporary debates and issues in sustainable development and delves into the challenges and opportunities of sustainable development in Los Angeles by drawing on case examples from other urban regions across the country. Through the course students will: 1) understand the historical theoretical and policy context of community development; 2) understand community and economic decline and development processes; 3) examine the key strategies of community development and related field of community economic development; 4) explore the growing intersection of community development and sustainable development including the greening of jobs buildings and urban design.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5889,2023,427,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305','<div class="desc"> In this course, students will learn how to document and analyze urban and environmental problems and public policies using quantitative data. Quantitative data provide a compelling means by which we can understand the magnitude of urban problems and who is impacted by these problems across demographic groups, neighborhoods, cities, and countries. Quantitative data can also help identify solutions, including public policies, and then evaluate the effectiveness of those solutions. Ultimately, our task is to develop quantitative reasoning skills in order to mobilize facts in the pursuit of a more just and equitable urban society. In the words of urban geographer Elvin Wyly: "Get mad. Get data. Get to work." Or, as Daniel Patrick Moynihan once said: "You can''t solve a problem until you first learn how to measure it." An important aspect of the course is how to make relevant and meaningful comparisons. How can we understand the size and significance of an urban problem such as low-wage work, or housing discrimination, racial profiling by police, or air pollution? We understand these issues best in relation to other outcomes: good jobs, nondiscriminatory housing and police practices, and clean air. We need to measure these outcomes in ways that we can compare them. Toward that goal, students will learn basic mathematical calculations and concepts such as percentages, rates, normalization, baselines, distributions, and probability. We will learn to read and interpret quantitative information presented in various formats, such as tables, graphs, geometric figures, or in text. Students will learn to assess numeric arguments and "answers" for reasonableness, as well as to recognize the limits of quantitative methods. Lastly, students will learn to evaluate how quantitative data is used, and sometimes misused, in the news media and public debates about social, economic, and environmental problems. Students will also engage basic questions of research: What data do we need to answer relevant policy questions? How can we devise a research project that would generate these data? Students will explore basic research methods using quantitative data, such as specifying a research question, research design, sampling, measurement, and validity. </div>',NULL,'UEP 305A ',NULL);
INSERT INTO course_descriptions VALUES(5890,2023,1566,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305a','<div class="desc"> Weekly laboratory for Urban Data Analysis where students will directly manipulate, analyze, and visualize real-world data related to urban problems and policy concerns, such as poverty, wages and low-wage work, housing affordability and quality, transportation equity, air quality, water safety, green space, food access, and crime and public safety. We will focus on identifying and communicating patterns of urban inequality. Students will become familiar with Excel and be introduced to Stata, a statistical software package. Students will learn to manage data, produce basic charts and graphs, generate descriptive statistics, and test hypotheses. </div>',NULL,'UEP 305',NULL);
INSERT INTO course_descriptions VALUES(5891,2023,792,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-306','<div class="desc"> <p>This community based learning course explores a range food systems issues from a food justice lens. The course examines how our food system has been restructured over the last century to benefit large-scale agriculture interests, creating a global food system that emphasizes convenience and fast-food solutions for consumers, often to the detriment of low-income people and communities of color. Through in-depth class discussions, on-site field trips, and in-class speakers, the class will delve into the environmental, economic, health, cultural, and social impacts of to how food is grown, processed, manufactured, distributed, sold, and consumed in the U.S. The community based learning component of this course will involve project work with UEPI’s food programs as well as other Los Angeles-based nonprofit partners and food policy experts. Please note, the first half of the semester will be based in the classroom (T/Th 1:30-2:55pm). During the second half of the semester, class will be held only one time per week (from 11:45am-2:55pm) to accommodate field trips.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5892,2023,428,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-310','<div class="desc"> <p>This seminar focuses the techniques of grassroots empowerment particularly in urban settings. This includes the following topics: developing leadership skills for citizen participation and problem solving using the media building coalitions choosing issues doing action-oriented research understanding the relations of power mobilizing constituencies developing a community oriented public policy agenda the history of community organizing in the U.S. and comparison between community development social work and direct action organizing approaches. <em>Must be taken simultaneously with UEP 311.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5893,2023,429,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-311','<div class="desc"> <p>This course provides opportunities for applying and learning through direct experience about the practice of community organization and leadership. Each student will work with a community-based organization engaged in influencing public policy for approximately 12-15 hours each week. Students will be supervised jointly by the faculty member and a staff person for the community organization. <em>Must be taken simultaneously with UEP 310.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5894,2023,1567,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-340','<div class="desc"> This course examines China''s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China''s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5896,2023,997,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-395','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>Science, Technology, &amp; Justice: The Making of “Modern” Families</strong></p> <p>Does reproductive justice include a right to bear children using technological means? What about using 3<sup>rd</sup> parties like egg and sperm donors? Are reproductive technologies expanding definitions of family or reinforcing race, class, and gender inequalities? This upper-division seminar will examine reproduction from a social justice perspective, with particular attention to how the politics of reproduction are shaped by the intersecting inequalities of gender, race, class, dis/ability, and sexuality. Reproduction is not only a biological process; it is a battleground of social and political struggle. The course will familiarize students with foundational academic and activist approaches to reproduction. Students will learn about the history of and differences between reproductive rights and reproductive justice movements. We will then look at the new questions and challenges reproductive technologies raise for social justice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5897,2023,793,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-397','<div class="desc"> <p>Tutorial and Internship for junior or senior majors in Urban and Environmental Policy and other related disciplines under arrangement with faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5898,2023,430,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-410','<div class="desc"> <p>Intensive study of the making of national and local public policy in the U.S. including the political environment in which policy debates take place. Extensive use will be made of case studies on a variety of domestic and international issues. Students will participate in the development of a major research project related to their senior comprehensive project on an individual or group basis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5899,2023,794,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-411','<div class="desc"> <p>Seminar to organize and complete a senior project demonstrating competence in applied public policy. The form and format of each student''s project will vary. All students will make a presentation of their project and will critique each other''s project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5901,2023,1431,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/100/wrd-135','<div class="desc"> <p>The Occidental Weekly practicum is for those who want to become section editors at the Occidental Weekly or simply want a further understanding of how daily journalism works. We will learn about ethics, management, editing and planning functions; we will not specifically study writing. Class assignments include three sets of story pitches and two news memos. The goal is for you to be ready to walk into a newsroom with an understanding of the language, disciplines, and best standards and practices. We will have occasional guest speakers on nuts-and-bolts topics, such as the use of language and the difference between news presentation in digital and in print. This is a graded course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5903,2023,1140,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-201','<div class="desc"> <p>This course provides students with opportunities to develop and practice the skills and habits that are foundational to academic writing and with knowledge of how to adapt these skills and habits for the varied writing demands students will encounter in college. This course fulfills (when passed with a grade of "C" or better) the college''s First Stage Writing Proficiency Requirement (and in some cases, the Second Stage Writing Proficiency Requirement), and it is also appropriate for students in various disciplines seeking to develop their writing, argument, analytic, and communication skills. All sections of this course focus on developing complex writing, analytical, and research skills for various audiences, disciplines, and genres. May be repeated to fulfill both the First- and Second-Stage Writing Requirements.</p> <p><strong>Rhetoric and the Fine Arts</strong></p> <p>This course is designed to provide intensive, guided training in college-level writing through the study of the fine arts—including but not limited to painting, music, film, and poetry—with an emphasis on recent work, exhibitions, and scholarship. Students will enter the current cultural conversation by writing their own critical essays, employing a variety of rhetorical techniques. Our focus will ultimately be on all the core elements of successful academic writing, including thesis statements, the use of evidence, source integration, developing and expanding ideas, and matters of form, clarity, and style.</p> <p><strong>Writing in Class, Whiteness, and Conflict </strong></p> <p>The readings and assignments in this course are designed to help students understand the social constructions of class hierarchies and the emerging theories about white identity politics, whiteness, and how race informs class analysis. We will engage in critical analysis and written argument to explore white identity, white supremacy, and the intersections of race, class and geography.</p> <p><strong>Writing, Rhetoric, and Formal Poetry</strong></p> <p>This section will focus on the relationship between poetry and rhetoric--more specifically, how form shapes understanding and is used to construct different types of rhetorical argument. We will study a variety of texts including poems, critical essays, biography, and literary and rhetorical theory.</p> <p><strong>Writing and the Rhetoric of Independent Film</strong></p> <p>This section will explore American independent film as an important art movement and alternative to traditional Hollywood filmmaking. We will study a select group of mostly recent works (2006-present) including those by the most noteworthy "mumblecore" writers/directors. </p> <p><strong>Writing, Gender, and Sexuality</strong></p> <p>This section will explore gender and sexuality in our contemporary American context. Drawing on readings from pop culture, critical theory, current events, and literature, we will examine how gender and sexuality are constructed, theorized, and represented, and how they intersect with other areas of identity including race and class.</p> <p><strong>Wanderlust Writing and Rhetoric</strong><br/> This section will explore the writing and rhetoric of wandering and adventure, from premodern adventure stories to the present-day #wanderlust as a synonym for free-spiritedness and Instagram humblebrags; our texts will be drawn primarily from literature, pop culture, and critical theory.</p> <p><strong>Protest Writing and Rhetoric</strong></p> <p>This section will examine the rhetoric, ideology, and context of protest genres, including social movements, speeches, literature, and visual texts, as we consider how writers, artists, and activists protest issues relating to race- and class-based oppression, gender inequity, ableism, colonialism, homophobia and heterosexism, and other concerns.</p> <p><strong>Writing on Travel</strong></p> <p>This section will examine travelers'' tales ranging from pilgrimages, the Grand Tour, island vacations, luxury cruises, and scientific expeditions, analyzing them from anthropological and post-modern critical perspectives, all while exploring images and texts from the 1700''s to the present.</p> </div>','Not open to first-year students ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5904,2023,2534,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-215','<div class="desc"> <p>This seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5905,2023,1635,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-235','<div class="desc"> <p>Visual Rhetoric: Communication through Pictures and/or Words. This course will examine the forms and uses of visual images to inform argue and inspire--in order to analyze their effectiveness expressing ideas across the millennia from ancient civilizations through the present digital age. We will examine codices illuminated manuscripts stained glass panels and maps; combinations of words and pictures from scientists poets printers and graphic novelists; as well as digital images such as memes information graphics data visualizations and multimedia arguments. Both the theory of visual rhetoric and the making of images in some of these media will complement our exploration of these genres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5906,2023,2569,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-245','<div class="desc"> <p>This course focuses on the rhetoric of Black protest and social movements as we examine Black rhetorics as modes of resistance to racist, colonialist, patriarchal, and other forms of oppressive discourse and action. We will consider a range of rhetorical forms including abolitionist rhetoric and the Black Jeremiad in American culture; Civil Rights era rhetorics and the Black Panther Movement; anti-imperialist Black proletariat rhetorics of protest in the West Indies and Caribbean societies; and rhetorics of resistance in the contemporary Black Lives Matter movement. This course will provide a rhetorical understanding of the approaches and strategies emerging from and responding to systems of cultural and social oppression, and thus will offer a counterpoint to Eurocentric rhetorical traditions. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5907,2023,1359,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-250','<div class="desc"> <p>Writing in the Community may take many forms. Specific topics will vary. Students may repeat once for credit if taken as different topics. Current topics listed below:</p> <p><strong>Writing and the Los Angeles Experience</strong></p> <p>A combination writing workshop and community-based learning course, Writing and the Los Angeles Experience examines how Los Angeles shapes and is shaped by those who write about the city. Readings, class discussions, and writing assignments will engage the work of local writers whose work revolves around the city—such as Paul Beatty, Francesca Lia Block, Luis Rodriguez, and Brando Skyhorse—and the parts of Los Angeles that are central to their experience. Guest speakers and field trips to visit different areas of the city and attend live events will help us explore the way the city influences those who write about it, and the cultural, social, and political forces that make it tick. The work of this course is both critical and creative: students will write about our readings using conventional tools of academic writing and rhetoric, and respond to their own experiences of the city in reflections, stories, or other creative projects. Core Requirement Met: US Diversity and Fine Arts.</p> <p><strong>Professional Writing on Social Issues</strong></p> <p>This course encourages an engaged and dynamic approach to writing studies as it places writing in real-world contexts by partnering Oxy students with nonprofit community organizations in greater Los Angeles. Through these partnerships, students will identify local cultural and social concerns on topics such as homelessness/housing insecurity, poverty, immigration, education, and social activism, which represent the interests of our particular community groups. In this class we will explore a wide range of research and writing strategies common to both academic environments and the professional situations of our community partners, including primary or field research and both individual and collaborative writing projects in professional genres. This course will allow students to see community nonprofit organizations -- plus the cultural social and political issues and rhetoric surrounding them -- from the inside out. The work of this class is thus both scholarly and practical, motivating student learning by enlivening and enriching students'' approaches to writing studies. Core Requirement Met: Global Connections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5908,2023,1636,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and criticism as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations power knowledge and identities are constituted through private and public rhetorical acts. Through our readings we will engage a wide range of contributions to a rhetorical critical history by women who either as practitioners or theorists advanced their visions of social change and acted to implement them. Course readings will begin in antiquity to provide a foundation for our study though much of our material will focus on texts from the nineteenth-century to the present to examine the intersections of gender and rhetoric. Through this work we will challenge the seeming erasure of women from this critical history and interrogate the notion of "feminist rhetoric" as merely a corollary to a masculinist tradition. Assignments will include critical essays and a visual rhetoric project on representations of women in the media and popular culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5909,2023,1360,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-275','<div class="desc"> <p>This course is designed to give students the chance to combine skills in critical analysis and writing with their interests or training in the sciences. Students do not need to have a science background or be majoring in a science field to be successful in this class, but they do need to have an interest in science in order to write about it in compelling ways. The central goal of this course is to develop and refine skills in presenting scientific topics to popular audiences comprised mainly of non-scientists. Course readings and assignments will span a range of scientific fields, including environment and ecology, cognitive science, psychology, medicine and health, and life sciences. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5910,2023,1141,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-285','<div class="desc"> <p>This course is an intensive introduction to the theories and practices of a trade that is protected by the 1st Amendment of the U.S. Constitution, essential to democracy, and yet increasingly under threat. Taught by a Pulitzer Prize-winning report, editor, columnist, and author who bolsters his teaching with distinguished guest speakers, this class introduces students to the core values and nuts-and-bolts skills demanding by the rapidly changing field of journalism, while teaching critical thinking skills that are key to global citizenship. Students will learn to research, report, interview, and then write with rhetorical force in the concise, clear newswriting style that remains the foundation of journalism in its myriad, multi-media forms. This course focuses on media influences across a range of geographical locations including Europe, Asia, Central and South America, as well as the U.S. The course will focus on regions and nations that are most in the news at the moment of the course semester. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5911,2023,1361,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-286','<div class="desc"> <p>In this course students will learn to combine the reporter''s craft with creative writing skills to produce compelling nonfiction. The class teaches students how accurate, factual stories can more fully convey insight into contemporary issues and the human condition by tapping the power of fictional techniques such as character development, use of dramatic tension, dialogue, and narrative structure. The course develops students'' research, reporting, and interviewing techniques, while focusing on the craft of writing. Using the spectrum of rhetorical devices, students will strive to create well-told stories about who we are, how we live, and the forces that shape our existence. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5912,2023,1432,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-287','<div class="desc"> <p>The 21st century has seen an abrupt escalation of government, corporate, and nonprofit institutions'' use of technology-sharpened rhetorical tools to disseminate information and, increasingly, disinformation to individuals and the public. Journalism, one of democracy''s most important forces for distinguishing truth from propaganda, has simultaneously been decimated by technological and economic change. This course offers an insider''s perspective on the theory and practice of rhetorical persuasion. This course will examine the forces that shape public opinion about recent history''s most significant issues, including climate disruption, education, immigration, and war. With a focus on opinion journalism, this course examines historical and current practices globally in examples such as Nazi and Stalinist propaganda in WWII, to international discourse on Vietnam, Iraq, and Afghanistan. Students will learn to write and critique editorials, op-eds, blog posts, and strategic communications'' plans driven by social media messaging, while scrutinizing the shared interests and deep tensions between journalism and public relations, publicity and marketing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5913,2023,1142,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-295','<div class="desc"> <p>This class will engage the historical theoretical and cultural dimensions of rhetoric in a range of disciplines in the arts literature politics and philosophy. In readings from Aristotle to poststructuralist theory we will examine all aspects of the rhetorical situation (exigence audience and rhetor) and the contexts in which rhetorical acts occur. We will examine how language practices intersect with culture and identity including class race sexuality gender and nation as we consider how arguments are constructed and how writing and narrative transform culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5915,2023,1362,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-301','<div class="desc"> <p>This advanced composition workshop explores creative nonfiction, a term that encompasses many genres, including memoir, profile writing, personal essay, humor, nature and travel writing, criticism, and narrative journalism, among others. This course will focus on 3-4 genres of creative nonfiction over the course of the semester. Each unit will pair a writing assignment in a particular genre with popular readings from that genre, by authors such as Paula Gunn Allen, Truman Capote, Ta-Nehisi Coates, Junot Díaz, Joan Didion, Audre Lorde, Adrienne Rich, Zadie Smith, and David Foster Wallace. The course will encourage experimentation while also paying close attention to audience, genre conventions, and other principles of successful writing. The workshop format relies on extensive peer review and revision, and each student will produce a capstone piece at the end of the semester after revision based on peer and instructor feedback. Prerequisite: student must have passed the first-year writing requirement and/or WRD 201.</p> </div>','Student must have passed the Core Writing Requirement or taken WRD 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(5916,2023,1143,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-395','<div class="desc"> <p>An exploration of the theory and practice of writing instruction, this class emphasizes rhetorical strategies, audience expectations, and forms of academic discourse. This course also provides new advisers with an introduction to tutoring practices and strategies through Writing Center scholarship. Permission of instructor required.<em>This class is only for Peer Writing Advisers working in Writing Center. </em><em>May be repeated once for credit. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5917,2023,1637,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5958,2024,3416,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/asn-asian-studies/200/asn-253','<div class="desc"> <p>The Tangand Song dynasties (618-1279) are known as Golden Ages in Chinese history, and also generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry. This course introduces the major literary genres and authors of the Tang and Song Dynasties, as well as literati culture emerging during this era. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. Students will discover the key role that literature played in Chinese court politics, empire building, and institutionalized learning; as well as how it shed light on gender and women’s status, war and knight-errantry, Daoist and Buddhist traditions, and more. The primary texts are translated in English, so knowledge of Chinese is not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5959,2024,3417,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/asn-asian-studies/200/asn-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5969,2024,3427,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/bio-biology/100/bio-193','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5977,2024,3435,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/blst-black-studies/100/blst-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(5988,2024,3446,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/blst-black-studies/300/blst-343','<div class="desc"> <p>In this project-based course, we will focus on Black ecological or environmental experiences and perspectives in Los Angeles and beyond. We will explore the theoretical and methodological tools and big ideas of the nascent field of Black Ecology through reading and discussing key texts. However, our ultimate aim is to share what we learn with as wide an audience we can muster using various digital technologies. Thus, this course is designed as a collaborative, interdisciplinary research collaboratory rooted in the tradition of W.E.B. Du Bois who operated a sociological research lab focused on Black life in America when he was a professor at Atlanta University between 1895-1924. Each iteration of this course will focus on a different project related to Black ecologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6015,2024,3473,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/cogs-cognitive-science/200/cogs-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6031,2024,3489,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/copy-of-hist-history/100/hist-193','<div class="desc"> <p class="MsoNormal">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6048,2024,3506,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-190','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the beautiful yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6065,2024,3523,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6071,2024,3529,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-214','<div class="desc"> <p>Students interested in engaging in social justice work will develop critical skills through case simulations. Through several writing assignments, students will learn what persuasive legal writing is in the United States, how it differs from other forms of writing, and how to write to serve clients’ varying needs through writing that appears objective but subjectively persuades. Students will also learn how to develop oral advocacy skills through mock intake, client rapport-building, and negotiation exercises. Through oral argument “moot” exercises, students will regularly present before a panel of two to three peers, handling questions from “the bench.” Throughout the semester, students will work collaboratively and independently.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6076,2024,3534,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6093,2024,3551,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/econ-economics/200/econ-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6107,2024,3565,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/educ-education/400/educ-410','<div class="desc"> <p>Participatory Action Research (PAR) is an ‘action research’ methodology in which researchers and community partners collaborate to conduct critical research. PAR projects typically involve (a) the collective investigation of a problem, that (b) relies on indigenous and/or community knowledges to guide/inform that research, towards the end of (c) individual and/or collective action to address that problem. This course introduces students to the research methodology through guided study. Students will understand basic study design, various methods of qualitative data collection &amp; analysis, as well as dissemination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6115,2024,3573,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/engl-english/200/engl-267','<div class="desc"> <p>Most students are aware of Andre Breton''s Parisian circle of surrealists, who have become synonymous with intellectual and artistic experimentation, combined with political engagement. Fewer realized that surrealist aesthetic techniques were being practiced at the exact same time within the Black Diaspora, among its Francophone, Anglophone, and Hispanophone speakers. Surrealism attracted artists, intellectuals, and activists from so many different cultures because it surpassed previous avant-garde art movements in linking creativity to a critique of colonialism. It is not surprising that surrealism found a special expression in the African Diaspora.</p> <p>However, the sheer breath of African Diaspora artists taking up surrealist techniques and themes is staggering. This course serves as an exploration of Afrosurrealist expression. The course begins in the early 20th century with the first generation of writers to embrace the term surrealism, then moves to the mid-20th century. But the majority of the course looks at 21st century literature, music, and visual art. European artists who took anti-racism seriously will also be included along the way. Students will encounter the work of Aime and Suzanne Cesaire, Romare Bearden, Claude Cahun, David Hammons, Senga Nengudi, Wangechi Mutu, D.S. Marriott, Terrance Nance, and Tierra Whack, among others. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6144,2024,3602,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/germ-german/300/germ-393','<div class="desc"> Research in an area not otherwise included in the departmental curriculum. Permission of instructor required. </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6153,2024,3611,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/grk-greek/300/grk-390','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the magnificent yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> <p>This course will be offered in conjunction with CSLC 190, but will meet for an additional 90 minutes per week to read the Homeric texts covered in class in their original Greek form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6203,2024,3661,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-393','<div class="desc"> Research in an area not otherwise included in the departmental curriculum. Permission of instructor required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6217,2024,3675,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/musc-music/200/musc-293','<div class="desc"> <p><span style="color: #282b2c;">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6219,2024,3677,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/musc-music/300/musc-393','<div class="desc"> <p><span style="color: #282b2c;">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6229,2024,3687,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/phil-philosophy/300/phil-331','<div class="desc"> <p>This course focuses on some issues in moral philosophy that arise for us as reflective and responsible citizens in a multicultural world. Topics for discussion will include: to what extent am I free and to what extent am I the product of circumstances beyond my control? What is the nature of moral agency and moral responsibility? How can I live authentically and establish my own identity? How ought I to relate to the majority and minority cultures that surround me and of which I may be a part?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6232,2024,3690,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/phil-philosophy/300/phil-393','<div class="desc"> <p><span style="color: #282b2c;">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6234,2024,3692,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/phys-physics/100/phys-165','<div class="desc"> <p>An introduction to optics and modern physics for both science and non-science majors. Topics include geometrical optics physical optics waves special relativity wave-particle duality atomic and nuclear physics. Includes one three-hour laboratory per week.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 125, or PHYS 230; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6293,2024,3751,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/rusn-russian/300/rusn-335','<div class="desc"> <p>In this Russian language version partnered with CSLC 135, in addition to reading Tolstoy''s novel, <em>War and Peace</em>, in English, students will read Book Ten in Russian. Students will submit weekly reports that deal with multiple aspects of the Russian text, including Tolstoy’s use of syntax to achieve textual defamiliarization, his idiosyncratic vocabulary that challenges translation, and his fusion of time and space through grammatical and syntactical devices. Students will also present weekly translations of selected passages along with issues they encounter in attempting to create an accurate yet artistically appealing translation. As a final project, each student will also select a passage from another Book of <em>War and Peace</em> and provide an annotated translation.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6311,2024,3769,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/span-spanish/300/span-393','<div class="desc"> <p><span style="color: #282b2c;">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6315,2024,3773,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/thea-theater/100/thea-193','<div class="desc"> <p><span style="color: #282b2c;">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6318,2024,3776,'https://oxy.smartcatalogiq.com/en/2023-2024/catalog/course-descriptions/thea-theater/300/thea-393','<div class="desc"> <p><span style="color: #282b2c;">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6368,2023,3416,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/asn-asian-studies/200/asn-253','<div class="desc"> <p>The Tangand Song dynasties (618-1279) are known as Golden Ages in Chinese history, and also generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry. This course introduces the major literary genres and authors of the Tang and Song Dynasties, as well as literati culture emerging during this era. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. Students will discover the key role that literature played in Chinese court politics, empire building, and institutionalized learning; as well as how it shed light on gender and women’s status, war and knight-errantry, Daoist and Buddhist traditions, and more. The primary texts are translated in English, so knowledge of Chinese is not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6369,2023,3417,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/asn-asian-studies/200/asn-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6379,2023,3427,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/bio-biology/100/bio-193','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6387,2023,3435,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/blst-black-studies/100/blst-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6398,2023,3446,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/blst-black-studies/300/blst-343','<div class="desc"> <p>In this project-based course, we will focus on Black ecological or environmental experiences and perspectives in Los Angeles and beyond. We will explore the theoretical and methodological tools and big ideas of the nascent field of Black Ecology through reading and discussing key texts. However, our ultimate aim is to share what we learn with as wide an audience we can muster using various digital technologies. Thus, this course is designed as a collaborative, interdisciplinary research collaboratory rooted in the tradition of W.E.B. Du Bois who operated a sociological research lab focused on Black life in America when he was a professor at Atlanta University between 1895-1924. Each iteration of this course will focus on a different project related to Black ecologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6425,2023,3473,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/cogs-cognitive-science/200/cogs-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6441,2023,3489,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/copy-of-hist-history/100/hist-193','<div class="desc"> <p class="MsoNormal">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6458,2023,3506,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-190','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the beautiful yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6475,2023,3523,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6485,2023,3534,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6502,2023,3551,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/econ-economics/200/econ-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6516,2023,3565,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/educ-education/400/educ-410','<div class="desc"> <p>Participatory Action Research (PAR) is an ‘action research’ methodology in which researchers and community partners collaborate to conduct critical research. PAR projects typically involve (a) the collective investigation of a problem, that (b) relies on indigenous and/or community knowledges to guide/inform that research, towards the end of (c) individual and/or collective action to address that problem. This course introduces students to the research methodology through guided study. Students will understand basic study design, various methods of qualitative data collection &amp; analysis, as well as dissemination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6524,2023,3573,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/engl-english/200/engl-267','<div class="desc"> <p>Most students are aware of Andre Breton''s Parisian circle of surrealists, who have become synonymous with intellectual and artistic experimentation, combined with political engagement. Fewer realized that surrealist aesthetic techniques were being practiced at the exact same time within the Black Diaspora, among its Francophone, Anglophone, and Hispanophone speakers. Surrealism attracted artists, intellectuals, and activists from so many different cultures because it surpassed previous avant-garde art movements in linking creativity to a critique of colonialism. It is not surprising that surrealism found a special expression in the African Diaspora.</p> <p>However, the sheer breath of African Diaspora artists taking up surrealist techniques and themes is staggering. This course serves as an exploration of Afrosurrealist expression. The course begins in the early 20th century with the first generation of writers to embrace the term surrealism, then moves to the mid-20th century. But the majority of the course looks at 21st century literature, music, and visual art. European artists who took anti-racism seriously will also be included along the way. Students will encounter the work of Aime and Suzanne Cesaire, Romare Bearden, Claude Cahun, David Hammons, Senga Nengudi, Wangechi Mutu, D.S. Marriott, Terrance Nance, and Tierra Whack, among others. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6553,2023,3602,'https://oxy.smartcatalogiq.com/en/2022-2023/catalog/course-descriptions/germ-german/300/germ-393','<div class="desc"> Research in an area not otherwise included in the departmental curriculum. Permission of instructor required. </div>','GERM 202 or by instructor permission ',NULL,NULL);
