INSERT INTO course_descriptions VALUES(6746,2022,3210,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/200/arth-273','<div class="desc"> <p class="MsoNormal" style="margin-left:0in; margin-right:0in">Each week, the class will travel the world to discover artists from different parts of the Spanish Empire, moving across the Iberian peninsula to Flanders, Southern Italy, the Philippines, Mexico, Peru and many more sites. This course explores the arts of the Spanish Monarchy from the plurality of perspectives and voices that composed this global empire ruled by the Habsburg dynasty (1516-1700). This will mainly concentrate on the arts of painting and sculpture, two crucial cultural traditions of this period. We will explore what “painting” and “sculpture” meant in different parts of the Empire, and how it also could integrate a broad range of decorative materials like feathers, gold, shell and ivory. Themes like religious visions, portraits, and still life will all receive attention. Famous artists and objects like Velazquez’ <em>Las Meninas </em>will come into conversation with the lesser-known and even anonymous makers of indigenous, creole and African descent, which all contributed to the history of sculpture and painting under the Spanish monarchy. Representations of power and artistic identity will intersect with issues of race, gender and class that structured societies under Spanish colonial and monarchic hegemony. Ultimately, students will come away with a much broader understanding of what well-known artistic traditions like painting and sculpture can mean in a globalizing and more culturally-heterogeneous world. Visits to nearby museums will also be included.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6749,2022,3211,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/arth-art-history/300/arth-375','<div class="desc"> <p class="MsoNormal" style="margin-left:0in; margin-right:0in">Pilgrimage is the journey to a revered site, often accomplished for spiritual purposes. Whether it is the Catholic Way of Saint James in Santiago de Compostela in Spain to the millions of Muslims who travel each year to Mecca for the Hajj, pilgrimage speaks to widespread narratives of human movement, monumentality, and memory.</p> <p>Encompassing the medieval and early modern periods, this class will explore the art and architecture of different religious shrines throughout the Global Mediterranean world (including the Americas). We will examine pilgrimage sites as the confluences of multi-media art forms, melding architectural space and fine arts with the cultural expression of everyday people: this includes graffiti, votive arts, and other folkloric practices. Students will explore themes like migration, displacement, colonialism, and connections with contemporary parallels.</p> </div>','ArtH 170 or permission of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6763,2022,1106,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/bio-biology/300/copy-of-bio-326','<div class="desc"> <p>This course focuses on how to build the tree of life from DNA data, from how DNA evolves to how DNA mutations are analyzed to create phylogenies. Topics covered include the theory behind molecular evolution and various analytical methods, as well as its application to creating evolutionary histories of genes and organisms. </p> </div>','BIO 280 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6768,2022,2852,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/100/copy-of-blst-105','<div class="desc"> <p>This course surveys music of African Americans with an emphasis on 20th century classical and vernacular genres. We will examine this musical web in three units: Classical Jazz &amp; Blues and Rock &amp; Contemporary Vernaculars. Featured artists include William Grant, Still Marian Anderson, Margaret Bonds, Duke Ellington, Fats Waller, Big Mama Thornton, Sam Cooke, The Five Blind Boys of Alabama, Motown Stax Records and Atlantic Records, Jimi Hendrix, Sweet Honey in the Rock, and Mos Def. Through extensive listening reading and group dialogue this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6769,2022,2732,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/100/copy-of-blst-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6777,2022,2685,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/blst-black-studies/200/copy-of-blst-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6807,2022,1650,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-317','<div class="desc"> <p>We study algorithms from the point of view of efficiency and complexity. Having studied data structures, we now see how to apply algorithms to these structures to optimize their effectiveness. We examine algorithms in terms of time and memory allocation considerations. We will apply this background to a subset of the most important algorithms used in the sciences, various media, and business. We will study effective algorithm design, and give a brief introduction to computational complexity and computability, as well as parallel processing. Selected topics and applications from graph theory, linear algebra, numerical analysis, data compression, encryption, and large-scale problems from Mathematics and the sciences.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 229 and either COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6808,2022,2712,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-371','<div class="desc"> <p>Smartphone apps, in their limited computational power and radically different form factor, impose new constraints and challenges different from the development of other software. In this class, students will be introduced to mobile architecture and related concepts such as monetization, privacy, analytics, and cross-platform development.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 and COMP 229, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6813,2022,943,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/copy-of-hist-history/200/copy-of-hist-243','<div class="desc"> <p>Chinese history from about 1600 to the present: the growth of the domestic economy, the rise of the Manchus and territorial expansion, encounter with the West, internal decline, rebellions, imperialism, nationalism, and revolution. Gender and national identity are key lenses through which to understand transformations during the modern period, including Modernization efforts, ideological struggles, and the cultural and economic transformations under the People''s Republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6825,2022,3214,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-139','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>No previous knowledge of either the Russian language or Russian literature is required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6829,2022,2326,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/copy-of-cslc-211','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different "scenes of writing," from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature''s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience and knowledge are produced, articulated and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6837,2022,3215,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-250','<div class="desc"> <p>This course investigates select African American engagements with the literatures produced by ancient Greeks and Romans. It is motivated by the conviction that we do interpretive justice to the accomplishments of African American writers when we attempt to understand the tradition(s) they conceive their work to be intervening in.</p> <p>African American literature was born with the publication of Phillis Wheatley’s <em>Poems on Various Subjects, Religious and Moral,</em> in 1773. The book evinces a deep knowledge of Latin and Latin literature, which it turns to its own emancipatory end. Indeed, Wheatley secured her freedom on the strength of the book.</p> <p>Engagement with classical texts offered Wheatley and other African American writers of every era an opportunity to access, deploy, and transform a widely shared treasury of meanings, ideas, images, tropes, genres, and styles in order to create unique works of great artistic power, capable of opening up newly imagined ways of being for themselves and their readers. In addition to Wheatley, we shall explore the classical interactions of poets such as James M. Bell, Mary Livermore, Frances Ellen Watkins, and Robert Hayden and prose writers such as David Walker, William Sanders Scarborough, and W. E. B. Du Bois.</p> <p>To experience the artistic power of these works as their authors intended, we must understand the aesthetic and literary contexts and tradition(s) in which they worked, for context and tradition are the foundation of a work’s meaning. To this end, we shall read alongside African American literary creations some of the Greek and Roman literary works to which they respond. For when we see clearly how a poem by, for example, Phillis Wheatley, responds to an ode by the Roman poet Horace—himself the son of a freedman—we grasp more fully the unique aesthetic, moral, and intellectual power of her poem. To see how Horace’s poetry could communicate to Wheatley is to see how Wheatley’s poetry can communicate its emancipatory power and promise to us in our own time. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6843,2022,3523,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6848,2022,3529,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-214','<div class="desc"> <p>This course explores the subject formation of girls in various societies throughout the world. Both theoretically and conceptually, the course will interrogate who counts as a “girl” and the coherence of girls as a social construction in various contexts. Through an examination of ideologies, policies, media, religion, institutional practices, schooling, and the social practices of girls themselves, the course will situate girls within complex sociocultural worlds. The course will ask questions of global girl power in relation to their social positionalities and material lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6849,2022,3219,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-227','<div class="desc"> <p>This course considers decolonial theories of education in relation to action- and land-based knowledge. Focusing on a variety of spaces and multidisciplinary texts, this course will explore differing ways of understanding education through Native American and Indigenous approaches to knowledge and knowing, land and place, as well as social and familial relations. Students should already have a working knowledge of theories of coloniality, intersectionality, and race. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6850,2022,1652,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-260','<div class="desc"> <p>This class examines the politics of human rights and histories of state­-sponsored violence in contemporary Latin America. By focusing on the Americas as a specific geopolitical site for our discussions, we will gain a better understanding of the main cultural, political, and philosophical debates over universal human rights. The class will also examine how culture and art can serve as a form of resistance to legacies of oppression and violence in the Americas. We will refer to critical human rights and feminist theory in order to assist our understandings of the experiences of those affected by Latin American state violence and the formation of Latinx diasporic communities in the United States. Students taking this course will gain an understanding of the histories of the region, the relationship between universal human rights, nationalism, political violence, and contemporary gender issues. The class will also refer to the limits and possibilities of human rights in the pursuit of attaining justice for state­-sponsored crimes. This course is taught in Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6855,2022,1588,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6856,2022,123,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-235','<div class="desc"> <p>This course will explore nationalism and ethnicity from both a theoretical and an empirical perspective. Nationalist and ethnic discourses have been central to political movements, rebellions, and revolutions. The passions and commitment of individual members in these movements often lead to political ideologies and war tactics that are violent, and which encompass entire communities. The class will concentrate on two theoretical perspectives; mainly the debates between primordialism and constructivism. Two cases from South/Southeast Asia and Sub-Saharan Africa will be analyzed.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6873,2022,136,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/200/copy-of-econ-272','<div class="desc"> <p>The use of regression and correlation to test economic hypotheses. Emphasis will be on the use and interpretation of single equation regression techniques rather than on their derivation. Familiarity with computers required.</p> </div>','ECON 102; at least Calculus 1 and COMP 146 (or equivalents); one additional ECON course above ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6876,2022,142,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/econ-economics/400/copy-of-econ-495','<div class="desc"> <p>An intensive application of economic analysis to issues chosen by the instructor in consultation with students during the course. The course emphasizes the development of analytical writing, team-work, and presentation skills, and is meant to be an opportunity for students to apply their economic training to specific topics. Complete descriptions of the seminars offered in a given year will be mailed out to students prior to the Spring registration. Senior status is required for this course. Students who will be off campus in the Fall of their senior year must contact the department chair by the end of their junior year to arrange a substitute senior seminar. </p> <p><strong>Firm-Level International Trade and Investment</strong></p> <p>This seminar studies firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. Topics discussed include the decision to export, foreign direct investment, outsourcing/offshoring, GATT/WTO and various trade agreements. We use modern trade theory to analyze firm decision-making and also learn how firms engage in international commerce from empirical studies and business case studies. Not open to students who have taken ECON 352.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250. </p> <p><strong>Industrial Organization</strong></p> <p>This course introduces the field of Industrial Organization, which is the study of firms in markets. We will analyze the acquisition and use of market power, strategic interactions among firms, and the role of government competition policy. Our approach will blend two alternative, but complementary, methodologies: theoretical modeling of strategic firm behavior and industry equilibrium, and the factual detail found in case studies of specific industries. Not open to students who have taken ECON 302.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250. </p> <p><strong><strong>Macroeconomic Policy since the Great Depression</strong></strong></p> <p>In the current economic climate, what should macroeconomic policymakers do to help the United States economy? This course analyzes the current macroeconomic policy challenges facing the United States from the vantage point of modern Macroeconomics and economic history. Students will read state-of-the-art empirical research in Macroeconomics and develop a sense for how macroeconomists conduct research and make policy recommendations. Special emphasis will be placed on exposing students to the major developments of United States monetary and fiscal policy since the Great Depression, and on the role of history in guiding contemporary macroeconomic policy decisions and debates. Not open to students who have taken Economics 351.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><br/> </p> <p><strong>Open Economy Macroeconomics</strong></p> <p>The course provides an overview of models, methods, research, and current issues in Open Economy Macroeconomics. Today, an international perspective to study Macroeconomics is perhaps more important than ever before. Countries do not operate in isolation, but events in one country affect people around the world. Why do some countries grow faster than others? What are the effects of monetary and fiscal policy, domestically and abroad? Why do some countries run trade deficits and others trade surpluses? Does it matter? And why do some countries encounter financial crises and what can we do about them? In trying to answer these questions, the first part of the semester will be devoted to asset-based models of exchange rates and price level determination, and the second to open economy models of the short and medium run.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong><strong>Health Economics</strong></strong></p> <p>This seminar provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries.</p> <p>Prerequisite: ECON 250 and ECON 272 (may be taken concurrently).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6888,2022,1593,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/engl-english/200/copy-of-engl-280','<div class="desc"> <p>The focus of this course is writing, and developing a relationship with, short fiction, with the aim of making it a fluid manifestation of the way we process and transform memory and experience. We will play into and take seriously Toni Morrison’s conception of memory as <em>a form of willed creation</em>, in an ongoing attempt to reanimate forgotten or unrealized aspects of our histories and ourselves. Students will generate new work constantly—in sketchbooks, exercises, and story drafts—paying attention to the honing of various craft elements (description, dialogue, character and plot development), and in correspondence with texts by a variety of exemplary practitioners of fiction and prose writing (Venita Blackburn, K-Ming Chang, Fleur Jaeggy, Jamaica Kincaid, Maxine Hong Kingston, Li-Young Lee, Clarice Lispector, Scholastique Mukasonga, Nhã Thuyên, among others). Students will share and discuss their work in a workshop format, the orientation of which will be based, in part, on each student’s specific intentions. The discussions will be supportive, inquisitive, and constructive, and will be oriented towards helping to introduce each other—and ourselves—to what is most compelling and imperative about what we are doing, what it is that we want to be doing, and how we might get there. Open to first- and second-year students. May be repeated once for credit.</p> </div>','One First Year Seminar, WRD 201, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6899,2022,2958,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-1','<div class="desc"> For the programmers who built the first video games, controlling computers meant controlling miniature worlds, having the power to shape both fantasy and reality. Yet if computers are tools of transformation, how have they been used so far? We are sold the fantasy of technology companies as progressive and utopian disrupters of a repressive status quo, while these companies’ products often deepen and reinforce oppressive systems of rules such as racism, sexism, binary cis gender, colonialism, and capitalism. If you had the chance to make your own world using technology, what would you do differently? In the hands of a new generation of programmers, could the process of designing virtual worlds with their own systems of rules help reimagine technology, building what Ruha Benjamin calls an “emancipatory approach”? Through this class, students will use science fiction, video games, movies, and works of history and theory as inspiration to artistically and technologically transform real-world practices such as game design, AI ethics, virtual reality, disability and accessibility, and environmental science. Students will also leave prepared to build strong thesis-driven written arguments and exercise their critical thinking skills throughout their time at Occidental College. This seminar will be part of the Computer Science Oxy Immersive Semester.<br/> </div>','Open only to first year frosh ','CTSJ 105 , DWA 282 , and SOC 105',NULL);
INSERT INTO course_descriptions VALUES(6900,2022,2966,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-10','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;">Historically, Blackness has been bounded within degraded space, uprooted, and threatened with erasure. Yet, Black people resist, persist, and make places for themselves. Grounded in the study of Black Geography, this course will examine the relationship between race and space, exploring when, why, and how Black people are spatially marginalized, how they move and are moved through space and time, and how they create a sense of place. We will explore topics such as the transatlantic slave trade, marronage, gentrification, migration, environmental racism, and social movements like the Movement for Black Lives. Our texts will include articles, films, maps, monographs, music, and novels.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6901,2022,2967,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-11','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;">This seminar will explore critical theories of education, particularly within critical race studies and a focus on Asian Pacific Americans students in the U.S. Students will reflect on their own identity formation within the context of their learning, conduct close-readings of educational narratives, and engage with the scholarship in critical race studies and education. Some questions our class will explore through reading and writing informal writing assignments and argumentative-driven essays include: What factors contribute to historically marginalized Asian Pacific American students'' educational achievement? How can critical race theory be used as a lens to assess inequities in education? How can critical pedagogy be used as a lens to rethink traditional models of education?</span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6902,2022,2968,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-12','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;">This course explores the vibrant religious and social currents shaping Iran from the 16th century onwards. It takes students beyond the Iranian Revolution, to Iran’s rich philosophical heritage, its spectacular art and architecture, its cinematic traditions, its mystical and messianic movements, its cultures of protest, and its intellectual and religious diversity. We will also examine aspects of Persian culture present in Los Angeles.</span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6903,2022,2969,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-13','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;">In “The American Scholar,” Ralph Waldo Emerson urged the spirit of a young nation to pour its novelty into its cultural production, so as “to look from under its iron lids, and fill the postponed expectation of the world with something better than the exertions of mechanical skill.” In the half century following this invocation, American literature more than fulfilled the charge, establishing itself as a unique and prosperous field through meditations on Emerson’s notion of individuality. This course will look at this first great explosion of American letters as it unfolds in the context of Emerson’s call to arms, from the Romantic movement that Emerson founded, through realism and regionalism, to the birth of modernism. Beginning with the foundation of individualism, it will consider other crucial downstream themes, such as the education of women, the problem of slavery, and the growing modernization of the nation, in the context of writers such as Edgar Allan Poe, Frederick Douglass, Kate Chopin and Emily Dickinson.</span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6904,2022,3265,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-14','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;">This course will examine various texts from different genres including popular literature, digital media, and scholarly essays, which seek to theorize the importance of standpoint and location as a way of forming political alliances along the intersections of gender, race and class. Long established arguments in support of identity and intersectionality have advanced critical examination of the varying systemic inequities marginalized groups experience, however, in 2020 we see a new identity politics rooted in whiteness and seemingly fueled by notions of white supremacy. Questions will be asked about the changing face of identity politics. Are we in a post-identity politics age? Or as some scholars contend does identity politics distract us from issues such as the growing income gap between the rich and everyone else? Has intersectionality been redefined to the point of irrelevance? What identity groups should be encouraged or discouraged, and what actions based on identity can aid or impede democratic justice? Students will engage in discussion, critical reading, and written analysis introducing vigorous academic discourse as essential to the first-year college experience.</span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6905,2022,2971,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-15','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;">To what extent did Atlantic African environmental, medical, and scientific knowledge shape the physical landscapes and intellectual worlds of the Americas between the period of early colonialism until the Age of Revolution? This course follows the mobile lives of people including West Central African banganga in Mexico, Temne-speaking women in South Carolina, and Kimbundu-speaking physicians in Brazil whose technical skill and knowledge proved invaluable for the empires and nations they found themselves within after surviving the middle passage. Millions of people speaking diverse languages and hailing from cultures from the Senegal River to Angola quite literally laid the environmental, economic, and intellectual foundations of American nations including the United States. As a community our goal will be to understand the role of the African diaspora in transforming the environments of the Western Hemisphere, and the ideas and knowledge that Africans in the diaspora developed through enslavement, fugitivity, and emancipation. Our course will ask how rice and sugar plantations, and other industrial spaces, are the products of Atlantic African technology forged through diaspora between Africa, South America and North America. Human trafficking involving captives provided the groundwork of scientific sensibilities as West Central Africans developed empirical sciences in Latin America and the Caribbean. Finally, we will take a look at the rich medical traditions of diverse peoples ranging from herbalists in Brazil to people of multiethnic ancestry like Afro-Yucatecan healers. This is an interdisciplinary seminar that will combine methods and readings from history, anthropology, ethnobotany, and environmental studies. Writing assignments throughout the course will enable participants to develop skill in expository writing, research with primary and secondary sources, and methods for historical analysis.</span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6906,2022,2972,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-16','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;">Norman Mailer described Los Angeles as a “constellation of plastic.” John Fante called it a “sad flower in the sand.” Is Los Angeles really just “72 suburbs in search of a city,” as Dorothy Parker claimed, or is there something else brewing beneath the beautiful, sunny skies? We’ll explore (through art, films, and books) 20th and 21st century Los Angeles as both a real and imagined location. Through the completion of four short papers (including one with a research component), you’ll craft your own conceptual “map” of the place. Required texts will likely include Writing Los Angeles: A Literary Anthology (David Ulin), Their Dogs Came with Them (Helena Maria Viramontes), and an assortment of short readings (both fiction and non-fiction/historical). Health and safety permitting, there might also be an optional field trip or two. Please note that some of the texts for this course may be disturbing. Please contact the instructor if you have any questions.</span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6907,2022,2973,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-19','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;">This course considers the role that piracy and the transatlantic slave trade played in the foundations of Atlantic empires. Discussions will focus on interactions between pirates (male and female), sailors, captives, privateers, corsairs, chartered companies, and European colonizers. Through historical accounts, fiction, and film we will examine life on the high seas, the local and global in the movement of people, goods and ideas, and the regulatory role of the state. We will be attentive to the position of pirates as an emerging social group, as well as addressing themes such as capitalism, citizenship, masculinity, revolt, the Middle Passage, and profit vs. morality. In addition, we will analyze representations of captives and pirates in popular culture.<br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6908,2022,2974,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-20','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-82d60796-7fff-651f-56dc-2a1c2efcd6d2" style="color: #000000;">In this course students will study the relationship between poetry and rhetoric -- more specifically, how meter, rhyme, and stanzaic arrangement have historically worked together to create meaning and construct different types of argument. We will read poems, commentaries, analyses, and other critical material to explore the role of form in shaping and enriching consciousness. This course will also provide intensive training in academic writing at the college level, with assignments designed to build critical reading and writing skills over the course of the semester.</span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6909,2022,2976,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-22','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-82d60796-7fff-651f-56dc-2a1c2efcd6d2" style="color: #000000;"><span id="docs-internal-guid-336866c2-7fff-773e-bf6b-ab571b76d084" style="color: #000000;">Eastern Europe was constructed during the Enlightenment to bring into relief the “superior” Western European culture. Since then Eastern Europe has been considered an obscure, ambiguous, and paradoxical place. Yet, it offers an epistemological advantage to those who decide to linger in its strange and fascinating lands. We will read and watch several key philosophical and cinematic works from Ukraine, Slovenia, Russia, and other nearby countries to elucidate the privileged vantage point of Eastern Europe. The philosophers and film directors could include Tarkovsky, Bakhtin, Florensky, Paradjanov, Vertov, Å½iÅ¾ek, Mamardashvili, and others. If circumstances allow, students will have the opportunity to visit several cultural venues in Los Angeles, including the Wende Museum of the Cold War, and the Museum of Jurassic Technology.</span></span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6910,2022,2977,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-23','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-82d60796-7fff-651f-56dc-2a1c2efcd6d2" style="color: #000000;"><span id="docs-internal-guid-336866c2-7fff-773e-bf6b-ab571b76d084" style="color: #000000;">Sometime in the year 399 BCE, the Athenian philosopher Socrates, convicted of impiety and corrupting the youth, fulfilled his death sentence by calmly draining a cup of poison hemlock, lifted to his mouth by his own hand. On June 1, 1310 CE, the French philosopher Marguerite Porete, deemed a heretic by a council of theologians, stood, according to one onlooker, "noble and devout" in the Place de Grève in Paris, moments before enduring the horror of being burned alive. Both refused numerous opportunities to avoid their fate. Socrates''s rich friends repeatedly offered to buy his way out of trouble. Porete was afforded multiple opportunities to disown her writings and recant her views. Knowing full well the dangers they faced, both chose instead to sacrifice themselves for their convictions. Underlying their practice, the philosophical teachings of Socrates and Porete express theoretical viewpoints on the themes involved in their own fatal acts—the nature of the soul, justice, wisdom, nobility, and devotion—as well as on the very idea of self-sacrifice. In this seminar, we''ll consider these two episodes, and how they relate, from both historical/practical and philosophical/theoretical vantage points. In the first part, we''ll read the "first tetralogy" of Plato''s dialogues—Euthyphro, Apology, Crito, and Phaedo—which recounts Socrates''s final days and also serves as one of the finest introductions to philosophical inquiry available. In the second part, we''ll read Porete''s condemned Mirror of Simple Souls, a dazzlingly surreal work of apophatic mysticism that reports a conversation between personifications of Love, Reason, Soul, and other interlocutors. Throughout, we''ll supplement this primary reading with selections from other thinkers in related contexts, as well as secondary literature from modern philosophers and historians.</span></span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6911,2022,2979,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-26','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="color: #000000;">Sport is a central feature of American life, and relatively few institutions in the United States have been as enduring as that of baseball. From its pastoral origins in the 19 th Century U.S. to its current global status, baseball as an institution offers an opportunity to critically examine the ways in which “America’s pastime” has been shaped by the society around it, as well as how baseball has itself shaped the communities and nations in which it is played. The course will touch on immigration, labor issues, race, gender, collective identity, municipal politics, and will use baseball as a lens to understand broader social processes of modernization, rationalization, and globalization. Far from the commonsense assumption that baseball is “just a game”, this course will teach students to think critically about the relationship between sport and society.</span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6912,2022,2980,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-27','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="background-color: #ffffff; color: #282b2c;">This course will explore various historical struggles of Native peoples in North America in their quest for sovereignty and agency. Sovereignty, in legal terms, has defined the boundaries of possibility for Native peoples, acting as both an opportunity to secure and protect rights, while also as an imposed structure allowing for continued marginalization. Students will interrogate structures of oppression, exploring the “nested”-nature of settler colonial configurations of nationhood and sovereignty. There will be a strong emphasis on writing and critical analysis throughout the course.</span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6913,2022,2981,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-28','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="color: #000000;">Narratives of dis/ability tell stories of health, illness, impairment, addiction, affliction, and survival. Using theories and histories from disability studies, we will explore how cultures of care and cure in the U.S. advance ability or able-bodiedness as a norm. In this course, we will consider histories of medical discrimination, health activisms and disability justice, and care interventions offered by harm reduction and mutual aid approaches. To think more deeply about drugs, care, and cure, we will examine legislation, media representations, the War on Drugs, the medical-industrial complex, the pharmaceutical industry, and modes of activist resistance pertaining to disability, addiction, and illness in the U.S.<br/> </span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6914,2022,2983,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-29','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="color: #000000;">The sea increasingly linked coastal cultures across the early modern world as European colonial, mercantile, and missionary projects rapidly gathered steam. Activities like commercial trade and religious conversion gave rise to art forms that redefined notions of “people” and “place.” How do these shores, coastlines, horizons, and vast open waters challenge traditional histories of the border-bound mainland? This course will examine the early modern artworks that arose from contact and conflict among maritime communities. It will explore the waterborne incursions of seafaring imperial powers like Venice, Portugal, Spain, England, and the Netherlands into Asia, Africa and the Americas. Our own location in coastal California also invites particular attention to Pacific art histories (both indigenous and colonial). Materials include maps and marine art, prints, portable objects, and the vast material culture of port cities arising from artistic exchange and innovation. The sea’s promise of economic fortune and new discovery occurred in conjunction with violent colonial conquest, displacement, and enslavement. Readings and artworks will engage those narratives along with the themes of portability, trade, exile and migration, and concepts of “local” versus “global” culture. </span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6915,2022,2959,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-3','<div class="desc"> This course deals with the significance of travel as a persistent motif in United States literature and popular film. It is not a survey of “travel literature” in any promotional or touristic sense. Instead, we will consider what sorts of individual or social circumstances compel people to move through the landscapes of the nation. What are they fleeing from or searching for? How are they transformed, for better or worse, in their journeys? <br/> <br/> To answer these questions, we will reflect on themes of exploration and escape, discovery and displacement. The course texts will relate such experiences as the traumatic dislocations of slave transit, the ecstatic wanderings of beat writers, the forced exodus of Dust Bowl refugees, the quest for personal redemption or renewal, and the inexorable circuity of migrant labor.<br/> <br/> This is a humanities course in content, topic and method. You will be asked to read books and watch films with care and critical focus. Your understanding of these texts will be exercised in regular seminar discussion and in a series of informal and formal interpretive essays. Some evening film screenings may be required.<br/> </div>','Open only to first year frosh ','CTSJ 105 , DWA 282 , and SOC 105',NULL);
INSERT INTO course_descriptions VALUES(6916,2022,2982,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-30','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="color: #000000;">Even though we do it every day, recognizing a face isn’t as easy as it seems. Different hairstyles or a sideways angle fooled our best algorithms for decades. But now, sufficiently large neural networks learn to recognize faces at timescales that starkly contrast the millennia evolution took in sculpting our brains. Indeed, deep learning has demonstrated that many sophisticated behaviors and neural codes actually emerge naturally from a limited set of principles. Students in this course will uncover these principles through reading literature and example code, and draw on them to generate hypotheses about optimizing learning in humans. No experience is required to succeed in this course but a strong interest in cognitive science, computer science, mathematics and/or statistics will be beneficial.</span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6917,2022,2984,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-31','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="background-color: #ffffff; color: #282b2c;">In this course students will develop a sophisticated understanding of the nature and process of scientific inquiry and communication, tracing the development of scientific information from original measurements to online broadcasts. Students will hone the skills necessary to evaluate and utilize scientific information reported in both peer-reviewed journals and popular media sources. Practice in reading primary scientific articles for comprehension, writing clearly about scientific topics for a broad audience, and delivering engaging scientific presentations will be a major focus of this course. Overall, students will gain perspective on how scientific knowledge is established and communicated to inform the actions we take as a society and in our personal lives.</span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6918,2022,2960,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-4','<div class="desc"> <span id="docs-internal-guid-03cbd3ad-7fff-deed-a64b-4ca7262a02ab" style="color: #000000;">In 2011, the French Minister of the Interior affirmed the importance of diversity to France, but also stated that diversity in France should not lead to the adoption of multiculturalism. This course will help students acquire a better understanding of diversity in France by examining the challenges faced by minorities and disenfranchised youth as well as the rise of the extreme right. Discussions will focus on the ways cinematic, theoretical and fictional works represent race, minorities, and the disadvantaged suburbs. The course will provide students with intellectual and interpretative tools to think critically about citizenship, fictive ethnicity, Frenchness, and colonial legacy.</span><br/> </div>','Open only to first year frosh ','CTSJ 105 , DWA 282 , and SOC 105',NULL);
INSERT INTO course_descriptions VALUES(6919,2022,2961,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-5','<div class="desc"> <span id="docs-internal-guid-a0074f6d-7fff-29ed-4627-cf132688e4c3" style="color: #000000;">This course interrogates the relationship between religion and violence. Through a survey of the scholarship on religion and violence and a series of focused studies on topics like the "revolutionary suicide" at Jonestown, the Cristero Rebellion in Mexico, and 9/11, this course will offer a broad overview of religion and violence in the Americas. Using these case studies, we will ask a series of analytical questions: Can religion motivate violence, or do they merely sanctify it? What are the sources of religious authority (such as leaders, scripture, tradition, and ritual practice) that can militate for or against violence? And what kinds of speech and action are properly understood as violent?</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6920,2022,2988,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-51','<div class="desc"> <p class="sc-BodyText">Students will investigate the causes of and possible solutions to real-world challenges such as the disparate impacts of climate change in urban areas and how this correlates with population, the crossover to humans of animal-borne diseases, and the impact of big pharma on people’s lives--balancing life-saving treatments with the inherent trust needed to use such drugs. You will investigate these challenges by developing research plans that consider the broader societal impacts of both the solutions you might suggest and the methods you might employ in doing your research.<br/> <br/> This course will involve extensive collaborative work, bringing together team members with different academic interests, and all three sections will frequently meet together. You will gain experience in scientific thinking, reading, and writing as well as insight into how science can be used (or misused) in addressing contemporary problems. Open only to first year frosh.</p> <p class="sc-BodyText"><strong>This course is recommended for students who are interested in majoring in the sciences</strong>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(6921,2022,2989,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-52','<div class="desc"> <span id="docs-internal-guid-8dc92c53-7fff-d6c3-876c-a90a8f1a9942" style="color: #000000;">This course introduces four theoretical perspectives on sexuality: biological (sexuality is a matter of sexual bodies and chemistry), psychological (sexuality is a matter of mental states and processes), social constructionist (sexuality is a cultural and historical product), and conflict (sexuality is a contested arena in which different groups vie for power). With these perspectives in mind, we explore four broad questions: How should we regulate sexual behavior? What is sexual consent? Who is responsible for the fact that sex makes babies? And, what is good sex? </span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6922,2022,2990,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-55','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-1568095f-7fff-6d45-2930-372fa05f502f" style="background-color: #ffffff; color: #282b2c;"><span id="docs-internal-guid-859249d5-7fff-ade3-d5da-b8b55a337411" style="color: #000000;"><span id="docs-internal-guid-4075866f-7fff-ad05-79ec-ee446a9d47e8" style="color: #000000;">Since the appearance of popular detective fiction in the 1840s, no genre has been more widely produced and consumed. From the continuing relevance of Sherlock Holmes to the super abundance of investigative dramas in television and film, the genre -- both consciously and not -- has come to define what it means to use the rational mind to break down and make sense of our world. This course will look critically at these stories of detection, from their emergence in the early stages of modernization to their enduring popularity today, so as to ask what the detective figure can tell us about our evolution into the present: from what it means to be a professional problem solver in the first place to what problem solving can do when confronted with the shifting grounds that seem to undermine the simple rationality to which investigation first appealed.</span></span></span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6923,2022,2991,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-54','<div class="desc"> This course will explore philosophical arguments about the justification (or lack thereof) for state institutions of punishment, with a special focus on Angela Davis''s prison abolitionism. Students will apply these arguments in their research projects to contemporary activist movements, including those to defund the police, to abolish ICE, to eliminate bail, and to reform parole. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6924,2022,2993,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-57','<div class="desc"> <p>While the term “romance novel” today often calls to mind tawdry love stories featuring heaving bosoms and uncontrollable passions, the genre of romance is much more complex than these stereotypes would make it seem. Early examples of romance are sprawling adventure narratives of chivalry, crusades, the supernatural, and yes, occasionally even love. Today, these tales’ descendants include not only the love stories we associate with the genre of romance, but also fantasy novels, Westerns, superhero narratives, and more. In this course we will explore the genealogy of romance from the Middle Ages through modern day, asking not only what constitutes a romance, but also what the continuously popular genre can teach us about readers’ desires and discontents across history. </p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6925,2022,2994,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-58','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;"><span id="docs-internal-guid-601224df-7fff-24bc-b400-c503249e3249" style="color: #000000;"><span id="docs-internal-guid-fadddcd0-7fff-377e-a177-5d7816caf4ef" style="color: #000000;"><span id="docs-internal-guid-981f6af0-7fff-7e3d-cd4f-fb849dc12362" style="color: #000000;"><span id="docs-internal-guid-6281cbb1-7fff-085b-8013-4572a12e9655" style="color: #000000;"><span id="docs-internal-guid-d6e0d542-7fff-73d9-b48c-a2c605442ee3" style="color: #000000;">How did healing knowledge moving between cultures lead to the rising authority and power of medicine in global history? This course takes a global approach to the history of medicine and biomedical science to offer a new narrative of the emergence of modern medicine. Familiar stories of medicine often focus on the progress of European physicians and the diffusion of knowledge from the "West" across the globe in the early modern period. By contrast, this course seeks to understand how medical knowledge has always involved cross-cultural exchanges, networks, and translation. Medicine is frequently the result of trade and travel, empire-building and colonialism, slavery and migration. Our course begins in the Islamic world, and will turn to how physicians in the Abbasid Caliphate engaged tibb yunani, or Hellenistic medicine, and Ayurvedic traditions from South Asia through institutions like the Bayt al-Hikma, or House of Wisdom in Baghdad. From here we will begin our world tour of medical cultures. Topics for the course include the social and cultural roles of Maya ah-men and Nahua ticitl in Central America, the production of encyclopedias and pharmacological compendia in Ming and Qing-dynasty China, the interaction of Rangaku and Shingaku in Tokugawa Japan, Atlantic African Mohanes in Latin America, and Ayurveda in Mughal India. We will question how no single path to "medical modernity" existed, but rather how medicine and medical authority emerged out of complex interactions between very diverse cultures. Writing assignments throughout the course will enable participants to develop skill in expository writing, research with primary and secondary sources, and historical analysis.</span><br/> </span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6926,2022,2995,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-59','<div class="desc"> <span id="docs-internal-guid-fb731a67-7fff-8fdb-ca0a-ff18aca96659" style="color: #000000;">This course offers an in-depth examination of the Dead Sea Scrolls (in English translation) and the archaeological remains of Qumran in the complicated context of Judaism in the Second Temple Period and the emergence of Christianity.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6927,2022,2962,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-6','<div class="desc"> <span id="docs-internal-guid-8d4a86f9-7fff-8287-a2bb-866d35487f24" style="color: #000000;">Just how predictable is our universe? In this seminar, we will learn how the mathematics of chaos helps us to better understand science, economics, psychology, and our environment. Students will also learn about the butterfly effect, period doubling, fractal dimensions, and strange attractors.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6928,2022,2996,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-60','<div class="desc"> <span id="docs-internal-guid-fb731a67-7fff-8fdb-ca0a-ff18aca96659" style="color: #000000;"><span id="docs-internal-guid-cd291cf9-7fff-7a36-abf9-41a0ae0760eb" style="color: #000000;">During the first part of the 20th century Paris was an international hub of intellectual and creative activity. For black Americans, in particular, Paris held the promise of "liberty, equality, and (interracial) fraternity". There they established connections with African and Caribbean thinkers resulting in an explosion of cultural production that would influence French culture and transform the future of people of African descent. This course will examine black internationalism as experienced in Paris during the Interwar period and the decade following World War II, focusing on themes such as Pan-Africanism, the Harlem Renaissance New Negro, the Jazz Age, and Negritude. Readings will include works by and/or about figures such as W.E.B. Du Bois, Langston Hughes, Josephine Baker, James Baldwin, Aime Cesaire, and Leopold Senghor.</span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6929,2022,3280,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-61','<div class="desc"> <span id="docs-internal-guid-fb731a67-7fff-8fdb-ca0a-ff18aca96659" style="color: #000000;"><span id="docs-internal-guid-cd291cf9-7fff-7a36-abf9-41a0ae0760eb" style="color: #000000;"><span id="docs-internal-guid-294ac6a4-7fff-d857-36e6-628779bd8962" style="color: #000000;">This course examines the relationship between music, sound and the environment. In the first part of this course we will review evolutionary theories of music-making among early homo sapiens and of acoustic communication among birds and mammals. Later, we will explore case studies of musical traditions from around the world that mediate relationships between humans and their surroundings. Finally, we will consider how music production in the Anthropocene relates to environmental sustainability. Here we will focus on the environmental footprint of human sound production as well as the role of music in contemporary environmental protest movements.</span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6930,2022,2998,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-62','<div class="desc"> <span id="docs-internal-guid-fb731a67-7fff-8fdb-ca0a-ff18aca96659" style="color: #000000;"><span id="docs-internal-guid-cd291cf9-7fff-7a36-abf9-41a0ae0760eb" style="color: #000000;"><span id="docs-internal-guid-294ac6a4-7fff-d857-36e6-628779bd8962" style="color: #000000;"><span id="docs-internal-guid-fecc27c6-7fff-d2c5-fb37-cb4b9ed99ba2" style="color: #000000;">Societies are shaped by experiences of chaos and revolution. It was Thomas Jefferson who once said "the tree of liberty must be refreshed from time to time with the blood of patriots and tyrants." Yet, modern conceptions of chaos and revolution are seen as weakening societies. This course will explore the many examples of how chaos brings about reform, revolution, and re-imagined forms of societal structures. We will explore examples of post-war, post-pandemic, and post-disaster scenarios as understood by historians, scientists and sociologists. Final projects will conclude with a modern application of theories and examples from class and discussion that explore ways that chaos can be transformed to help build a better world.</span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6931,2022,2999,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-63','<div class="desc"> <span id="docs-internal-guid-fb731a67-7fff-8fdb-ca0a-ff18aca96659" style="color: #000000;"><span id="docs-internal-guid-cd291cf9-7fff-7a36-abf9-41a0ae0760eb" style="color: #000000;"><span id="docs-internal-guid-294ac6a4-7fff-d857-36e6-628779bd8962" style="color: #000000;"><span id="docs-internal-guid-fecc27c6-7fff-d2c5-fb37-cb4b9ed99ba2" style="color: #000000;"><span id="docs-internal-guid-e3996c7d-7fff-d008-6b71-85d8ec84168d" style="color: #000000;">Many people associate the Middle East with Islam, or Islam as the primary religion of the Middle East. However, the contemporary Middle East is far more diverse in terms of religious practices within Islam as well as engagement and growth with and alongside many other religious traditions. We will begin the course by considering what’s at stake when we centralize the study of religious practices as a method of engaging with and studying a place, then considering the complex networks of politics, nationalism, and ethnicity as understood through ethnographic research in the region. Ethnographic research can involve what is commonly labeled “fieldwork,” but can be far more capacious to consider an analysis of practices rooted in the perspective of the social context in which they were produced. Ethnographies are not only related to a researcher’s physical presence in terms of the practices studied, but can include a variety of virtual, digital, or other material products. Our ethnographic examples will be drawn from a variety of religious practices in the Middle East, including Sunni and Shi’a Islam, the Baha’i faith, Judaism, and a variety of Christian groups. As we work through our examples, we will consider the disciplinary questions of area studies approaches (for example, studying “the Middle East”).</span></span></span></span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6932,2022,3000,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-64','<div class="desc"> Events such as the January 6th insurrection at the US Capitol, the efforts by local school districts to prohibit teaching America’s history of systemic oppression and the growing political divide today can be understood by critical inquiry into the study of white identities. This seminar, through the lens of whiteness studies will examine and analyze a series of texts, including essays, articles, digital media, and more to consider how writers, artists and public intellectuals ask difficult questions and present ideas to engage in critical conversation regarding these topics. The real work of this course is strengthening students’ ability to analyze, evaluate, and produce arguments. Students will engage in essay writing with an emphasis on constructing logical arguments and developing persuasive analysis utilizing primary and secondary evidence to support ideas in preparation for writing an academic research paper. Works from scholars such as David Roediger, Ashley Jardina, George Lipsitz, Peggy McIntosh, and numerous others will be examined. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6933,2022,3281,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-65','<div class="desc"> Experience the European Renaissance and Enlightenment through its artistic and scientific innovation, religious reform, and multi-varied personalities. Consider the relationship of our contemporary "individuality" to the characteristics of men and women of early modern times. A source reader will provide practice in analyzing texts, as well as objects of material culture, in an age of encounters between cultures. A student may focus on a particular field such as politics/diplomacy, court life, sexuality/gender, crafts and the arts, classical revival, reformation, scientific experiment, mapping the globe, philosophical inquiry, protest literature and salons, or travel and global encounters. Learning collaboratively and discussing two films, students examine the lives of a diversity of men and women and the controversies that their lives provoked. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6934,2022,3002,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-66','<div class="desc"> <span id="docs-internal-guid-48348ac0-7fff-70f2-fb06-a0db52148227" style="color: #000000;">Why do certain houses, places, and robots make us feel uneasy? Sigmund Freud might tip his hat to their “uncanny” effect – their “unheimlich” or “unhomely” qualities. But what does that mean? Freud spent many hours and pages digging into this slippery concept of the “familiar” but “strange,” never quite pinpointing it with definitional certainty. We’ll pursue this puzzle by looking at art, literature, film, history, music, technology, and sociological practices through an uncanny lens. In the process, we’ll explore related concepts, such as “the sublime,” “the eerie,” “the abject,” “the gothic,” and “the weird.” Horror and sci-fi fans, psychology enthusiasts, and buffs of the unusual – get ready to rumble with Stanley Kubrick, Robert Wiene, Toni Morrison, Kazuo Ishiguro, E.T.A. Hoffmann, Stephen King, Octavia Butler, Edogawa Rampo, the Brothers Quay, Ridley Scott, Mary Shelley, and many, many more. Assignments include weekly readings and films, short written responses, a brief presentation, and three papers. Needless to say, we will haunt the library with our interdisciplinary research. There might even be a field trip into the uncanny landscape of Los Angeles. Please note that some of the texts for this course may be disturbing. Feel free to contact the instructor if you have any questions.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6935,2022,3003,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-67','<div class="desc"> <span id="docs-internal-guid-48348ac0-7fff-70f2-fb06-a0db52148227" style="color: #000000;">Residents and observers of the Southern United States have long maintained that the region is unique, possessed of a distinctive culture and identity that differs from the wider U.S. society. As the only region of the country to secede from the union and the stronghold of slavery into the middle of the 19th Century, the South has certainly been posed in opposition to the dominant professed values of American democracy. At the same time, racism, poverty, political corruption, and high degrees of religiosity are not exclusively Southern propositions, and the Southern U.S. has been subject to many of the same pressures of late capitalism and individualization as have the other states in the union. Consequently, in this course, we will ask – and attempt to answer – the question “How distinctive is the South”? In doing so, we will survey a broad sampling of both classical and contemporary sociological research and theorizing on the U.S. South. We will also explore the culture of the South – its food, music, art, religious practices, and politics.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6936,2022,3004,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-69','<div class="desc"> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6937,2022,2963,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-7','<div class="desc"> <span id="docs-internal-guid-9290e262-7fff-f597-517c-edf10bb4bdbd" style="color: #000000;">Three decades after Francis Fukuyama famously proclaimed the "End of History," global capitalism is in crisis, political authoritarianism remains viable, and democracy is increasingly under threat around the world. Publics in established democracies are rejecting globalization and supporting authoritarian populism, while many dictators have embraced the hyper-mobility of capital, free trade, and modern information technology. These developments raise a number of questions, which we will explore in the course. What is the relationship between globalization and authoritarianism? How do authoritarian regimes navigate today’s highly globalized world economy? How should we understand the rise of populist movements in the rich world? The major goal of the seminar is to encourage first-year students to develop writing and research skills while reflecting on these important questions in the context of the latest research in the social sciences. </span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6938,2022,3005,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-70','<div class="desc"> <span id="docs-internal-guid-48348ac0-7fff-70f2-fb06-a0db52148227" style="color: #000000;"><span id="docs-internal-guid-5be89556-7fff-4c5f-ea63-c931c78a2475" style="color: #000000;">Utilizing Lamar’s classic 2015 album, “To Pimp a Butterfly,” the course will evaluate this classic hip hop recording as a basis to explore empathy, urban poeticism, dramatic conflict, and racial and identity politics in post-modern America. Course participants will have the opportunity to engage Lamar’s lyrics as the foundation for their own expository as well as narrative writing, and extract Lamar’s themes and beats to spark personal convictions that lead to potent writing samples and intellectually stimulating class discussions. Students will create and participate in prompts based on the beats, themes, and overall lyrical content of the album, and engage in both traditional and non-traditional writing exercises, from critical theory essays to rap poetry. Come get your mind blown, your heart opened, and your writing pen sharpened!</span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6939,2022,3198,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-71','<div class="desc"> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6940,2022,3199,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-72','<div class="desc"> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6941,2022,3200,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-73','<div class="desc"> <span id="docs-internal-guid-0b511438-7fff-b3b2-11aa-d3af06b91095" style="color: #000000;">Is it possible to see capitalism? How can something that is simultaneously so totalizing and abstract while also enmeshed in our everyday environment and activities be represented? How have artists, writers, and filmmakers attempted to provide a picture of the complex economic system that imperceptibly links our daily lives with the entire world? This course will focus on the various strategies contemporary artists, theorists, and other cultural practitioners have explored to make capitalism visible and intelligible in the era of globalization.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6942,2022,3201,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-74','<div class="desc"> <span id="docs-internal-guid-0b511438-7fff-b3b2-11aa-d3af06b91095" style="color: #000000;"><span id="docs-internal-guid-33ac7dd1-7fff-6c0f-aa3a-c31b2f362fad" style="color: #000000;">This course uses a feminist lens to analyze transnational documentary and feature films. We will examine the politics of gender in films produced in the West and the Global South and we will assess the flows between "first world" and "third world" cinematic traditions. Students will gain the necessary skills to analyze representations of gender, race, class, nationality, and sexuality in transnational film. The course considers how film can be a powerful tool that operates in the perpetuation of "third" and "first world" hierarchies and the economic, racial, and gendered inequalities that stem from histories of colonization. We will also consider how film can offer a critique of these dominant ideologies and inequalities that reflects postcolonial relations between "first" and "third" worlds. We will turn to feminist film theory, documentary film theory, cultural studies and postcolonial feminist theory in order to facilitate our analysis and class discussions of these films.</span></span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6943,2022,3006,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-75','<div class="desc"> This course will trace the complex dialogue between Disneyland Park and its urban environment of greater Los Angeles, with a particular emphasis on the 1955-1967 period, carefully analyzing urban and social history, film, and literature to discover what Disneyland can teach us about the strange, sprawling geography and culture of the megalopolis around it. Along the way, we will become familiar with the increasingly robust interdisciplinary scholarly discourse about Disney culture. Finally, we will explore the ways contemporary critical theoretical concepts apply to Disneyland and how our understanding of this specific place might revise our broader theoretical conceptions of urbanism, history, and modern society. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6944,2022,3202,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-76','<div class="desc"> Graphic narratives have emerged in recent decades as a prominent medium for memoirs. Through the interplay of art and words, creators give form to not only their past experiences but also to events and places they have only imaged or witnessed second-hand. In this course, we will explore the messy interplay between self and other, our memories of things we have experienced, and our memories of things we have heard about second hand. Graphic memoirs illuminate the ways in which our memories are indelibly marked by ourselves, and we will consider the way that drawings and writing reflect the experiences, fears and desires of their creators. We will also examine the ways in which the comics medium, which invites readers to imagine themselves in the panels, has the potential to alter our understanding of ourselves and the worlds we inhabit. Readings may include Maus, Persepolis, Fun Home, Onwards Towards Our Noble Deaths, and Town of Evening Calm, Country of Cherry Blossoms. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6945,2022,3203,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-77','<div class="desc"> The mobility of humans both within and across international borders is a critical and contested issue around the globe. This course will examine many of the core dilemmas in the study of migration and citizenship from a social scientific perspective. While a significant portion of the course will be devoted to analysis of these questions from the vantage of the United States, we will also be examining these questions through a comparative lens. We will attempt to gain traction on a number of important questions. How are international borders constructed, both physically and psychologically? What is the relationship between conceptions of national identity and immigration policy? And, perhaps most crucially, does the “rich world” have a moral obligation to maintain relatively open borders and provide assistance to labor migrants and/or asylum seekers? </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6946,2022,3209,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-78','<div class="desc"> This course introduces students to the politics of water from the local to the global levels. Students will learn how increasing scarcity of water is related to factors such as climate change, urbanization, population growth, and tensions between uses (e.g. agriculture, manufacturing, energy generation, etc.). Local case studies include lessons from Flint, Michigan and local Los Angeles water issues. International cases will examine the impact of large dams in India, water wars over municipal water services in Latin America, mining and other extractive industries worldwide, and the privatization and commodification of water, including the business of bottling water. Global water governance will be examined as well, including the campaigns to legalize a human right to water within the United Nations, and the place of water in the 2030 Sustainable Development Goals. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6947,2022,2964,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-8','<div class="desc"> More than simply a "god of wine," Dionysus was for the Ancient Greeks a god of ecstatic self-abandon, of gushing fertility, of violent dismemberment and unexpected rebirth. In myth he was attended by raving Maenads and mischievous Satyrs; amongst humans he was worshipped with festive dances, communal shouts, ritual obscenities, and (perhaps most importantly) with poetry -- with the literary genres of ode, comedy and tragedy that were invented specifically to honor him. What could be farther, we might ask, from the cool, reasonable practice of philosophy than this wild, uncanny, irrational god? And yet, as we shall see in this class, this reckless god of madness and poetry stands at the foundation of some of the most important ideas in modern philosophy -- Hegel''s phenomenology of spirit, Nietzsche''s will to power, Heidegger''s philosophy of Existenz, Bataille''s notion of excess, and Derrida''s "non-concept" of differance. Beginning with an exploration of Dionysian poetics in Ancient Greece, this course will attempt to show what thinkers like these found so inspiring in this ancient god, and what the writers and thinkers of our own time might yet find in him still. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6948,2022,2965,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/fys-first-year-seminar/fys-9','<div class="desc"> <span id="docs-internal-guid-f284ee12-7fff-370c-f0c7-c0d85c094e9f" style="color: #000000;">This seminar explores the many ways in which women in East Asia have engaged with art—as producers, as patrons, and as objects or subjects of the gaze. At the same time, we will study how gender and womanhood have been conceived and contested in China, Japan, and Korea. We will investigate topics such as the construction of desire; the politics of the gaze; shifting ideals of femininity; and representations of gender in anime. Readings and discussions will be supplemented with hands-on activities, including ink painting, pottery making, and the tea ceremony. Ultimately, we will develop critical tools for examining how women have been represented in East Asian visual culture and how they have exerted their own forms of artistic agency.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6952,2022,1071,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/geo-geology/300/copy-of-geo-390l','<div class="desc"> <p>Weekly three-hour laboratory in conjunction with GEO 390 Special Topics in Geology.</p> </div>',NULL,'GEO 390',NULL);
INSERT INTO course_descriptions VALUES(6959,2022,2339,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/germ-german/300/copy-of-germ-311','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different “scenes of writing,” from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature’s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience, and knowledge are produced, articulated, and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler. Taught in German.</p> </div>','GERM 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6984,2022,3216,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/latn-latin/300/latn-350','<div class="desc"> <p>This course investigates select African American engagements with the literatures produced by ancient Greeks and Romans. It is motivated by the conviction that we do interpretive justice to the accomplishments of African American writers when we attempt to understand the tradition(s) they conceive their work to be intervening in.</p> <p>African American literature was born with the publication of Phillis Wheatley’s <em>Poems on Various Subjects, Religious and Moral,</em> in 1773. The book evinces a deep knowledge of Latin and Latin literature, which it turns to its own emancipatory end. Indeed, Wheatley secured her freedom on the strength of the book.</p> <p>Engagement with classical texts offered Wheatley and other African American writers of every era an opportunity to access, deploy, and transform a widely shared treasury of meanings, ideas, images, tropes, genres, and styles in order to create unique works of great artistic power, capable of opening up newly imagined ways of being for themselves and their readers. In addition to Wheatley, we shall explore the classical interactions of poets such as James M. Bell, Mary Livermore, Frances Ellen Watkins, and Robert Hayden and prose writers such as David Walker, William Sanders Scarborough, and W. E. B. Du Bois.</p> <p>To experience the artistic power of these works as their authors intended, we must understand the aesthetic and literary contexts and tradition(s) in which they worked, for context and tradition are the foundation of a work’s meaning. To this end, we shall read alongside African American literary creations some of the Greek and Roman literary works to which they respond. For when we see clearly how a poem by, for example, Phillis Wheatley, responds to an ode by the Roman poet Horace—himself the son of a freedman—we grasp more fully the unique aesthetic, moral, and intellectual power of her poem. To see how Horace’s poetry could communicate to Wheatley is to see how Wheatley’s poetry can communicate its emancipatory power and promise to us in our own time. </p> </div>','LATN 201 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(6993,2022,3220,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-256','<div class="desc"> <p>Since the fall of the Mexica (Aztecs) to the Spaniards in August of 1521, writers and artists have represented the dramatic events leading to the conquest of Mexico. Major figures of the conquest, such as Hernando Cortés, Malinche, Moteuczoma, and Cuahtemoc, have been memorialized, mythologized, and in some cases villainized. This course examines representations of the conquest and the leading figures of the period from a variety of perspectives. We will consider how changing political and cultural contexts have shaped remembrances of the war and the consequences of colonial rule. In this course, students will analyze a variety of sources, including Spanish and indigenous accounts, pictorial writings, paintings and artworks, operas and films. In addition, we will examine contemporary artistic projects, museum exhibitions, and archival programs that have been organized to commemorate the 500-year anniversary since the fall of the Aztec Empire.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7002,2022,1529,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-110','<div class="desc"> <p>This 2-unit course focuses on the fundamental processes and tools involved in digital design for the media arts: color, resolution, image manipulation, compositing, typography, vector graphics, web/app design principles, project workflow, and output/finishing formats. Students will become familiar with the interfaces of essential software platforms, including Adobe Photoshop and Illustrator, and will apply concepts and techniques to various assignments. Open only to MAC majors and minors. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7003,2022,1530,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-143','<div class="desc"> <p>This 100-level gateway course introduces students to key concepts and methodologies for the critical analysis and interpretation of a broad range of media forms across the visual field - including film, television, social media, photography, games, advertising, etc. - and the cultural, historical, and ideological forces that govern them. Drawing from select case studies in media and visual culture, the course emphasizes critical reading, discussion, and writing, with forays into digital scholarship. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7004,2022,1666,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-145','<div class="desc"> <p><em>Born Digital</em>, <em>Growing Up Digital</em>, <em>Teaching Digital Natives</em>, <em>Understanding the Digital Generation</em> ... these are just some of the titles in a veritable explosion of guidebooks on how thinking, learning, and doing have changed in a world transformed by digital, networked, and social media. In this 100-level gateway course, we take a critical look at the theories and prophesies on the "Net Gen"; we explore and assess new digital possibilities for communicating, teaching, and learning; and we think critically, contextually, and historically about the ways in which new media forms and practices shape identity, community, sociality, creativity, privacy, civic engagement, and everyday life. Class projects will enable students to experiment with, and gain, practical experience applying a range of media 2.0 technologies to their own academic work. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7005,2022,1531,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-146','<div class="desc"> <p>This 100-level gateway course breaks down the aesthetic components of film and examines each element''s function in the production of meaning in a text. The course underscores the fact that cinema''s aesthetic language is not solely generated by Hollywood. It is a fluid system, highly contingent upon cultural, temporal, technological, and economic considerations. Selected international and alternative cinema movements will be examined for their enduring influences upon the global audiovisual aesthetic lexicon. Students will learn to connect formal analysis to cultural criticism and will engage with key disciplinary theories and writing methodologies. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7007,2022,3212,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-247','<div class="desc"> <p> A hands-on course in the fundamentals of animated media and visual effects production examined alongside their history, techniques, form, and methods. Students will explore creative and technical strategies for designing form and content across experimental, abstract, character based, hybrid, and live-action composited approaches. A series of individual and collaborative, hands-on media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct Core requirements.</strong></em></p> <p><strong>Animation Fundamentals</strong></p> <p>A hands-on course in the fundamentals of animated media production with special emphasis on integrations between analog and digital techniques. Students will explore creative strategies for designing form and content across experimental, abstract, and character-based approaches, with special emphasis on investigations with analog materiality. We will experiment with a range of lens-based stop-motion animation techniques (2D down-shooter, pixilation), and digital methods (composting &amp; keyframing in After Effects). Throughout, the emphasis will be on learning and practicing the fundamentals of animation timing, audio-visual design compositional principles, and pre-production methods for developing concepts and stories especially geared to animation. A series of collaborative, practical animated media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7017,2022,652,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/copy-of-musc-105','<div class="desc"> <p>This course surveys music of African Americans with an emphasis on 20th century classical and vernacular genres. We will examine this musical web in three units: Classical Jazz &amp; Blues and Rock &amp; Contemporary Vernaculars. Featured artists include William Grant, Still Marian Anderson, Margaret Bonds, Duke Ellington, Fats Waller, Big Mama Thornton, Sam Cooke, The Five Blind Boys of Alabama, Motown Stax Records and Atlantic Records, Jimi Hendrix, Sweet Honey in the Rock, and Mos Def. Through extensive listening reading and group dialogue this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7018,2022,653,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/100/copy-of-musc-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7020,2022,2350,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/musc-music/200/copy-of-musc-248','<div class="desc"> <p>Music producers have at their disposal a set of powerful tools that enable them to create, shape, and refine their sounds in their studios. In this course, we will use Kontakt and Reaktor for a hands-on approach to building virtual instruments and synths. We will address topics such as synthesis and sampling, and we will create and shape pads, basses, and drums by using virtual instruments and third-party plugins. Students compose more advanced creative projects using the instruments they create.</p> </div>','MUSC 148 with a grade of B- or higher and permission of instructor ','MUSC 151 (may be taken concurrently)',NULL);
INSERT INTO course_descriptions VALUES(7032,2022,3221,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-323','<div class="desc"> <p>What is language, and where does it come from? What is it to know something, and how can we achieve knowledge? What is the nature of reasoning, and how should we discern good argumentation from bad? Philosophers of the medieval Arabic-Islamic tradition, such as al-FÄrÄbÄ«, Ibn SÄ«nÄ, and Ibn Rushd, proposed detailed answers to these and other related questions, grounding their proposals in powerful arguments. By adopting a broadly Aristotelian framework, but going well beyond its confines, these figures paved the way for later European Latin philosophy, which borrows heavily from their insights. We''ll study those insights and their reception in this class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7033,2022,3687,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-331','<div class="desc"> <p>This course focuses on some issues in moral philosophy that arise for us as reflective and responsible citizens in a multicultural world. Topics for discussion will include: to what extent am I free and to what extent am I the product of circumstances beyond my control? What is the nature of moral agency and moral responsibility? How can I live authentically and establish my own identity? How ought I to relate to the majority and minority cultures that surround me and of which I may be a part?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7035,2022,3817,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phil-philosophy/300/phil-343','<div class="desc"> <p>In the second half of the 20th century, the new field of cognitive science came into existence. This course explores the developments in the history of philosophy, mathematics, biology, psychology, and computer science that culminated in this new science of the mind, including the theory of computation, from the work of Leibniz in the 17th century, the pioneering work on computing and programming by Charles Babbage and Ada Lovelace in the late 19th century, to Turing''s work in the early 20th century. We will explore how developments in both theoretical and applied computer science and logic led to the field of artificial intelligence and computational neuroscience, and we''ll explore the philosophical questions about the possibility and scope of machine intelligence. One prior course in cognitive science, philosophy, or mathematics is recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7039,2022,3692,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/phys-physics/100/phys-165','<div class="desc"> <p>An introduction to optics and modern physics for both science and non-science majors. Topics include geometrical optics physical optics waves special relativity wave-particle duality atomic and nuclear physics. Includes one three-hour laboratory per week.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7065,2022,2492,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/psyc-psychology/300/pysc-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','PSYC 310L ',NULL);
INSERT INTO course_descriptions VALUES(7077,2022,3823,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-235','<div class="desc"> An introduction to the gods and goddesses of the Hindu pantheon. Students will study the mythology, iconography, narrative, and pilgrimage traditions, as well as the various movements -- ascetic, devotional, and Tantric -- associated with Hindu deities. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7079,2022,3824,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rels-religious-studies/200/rels-255','<div class="desc"> <p>This course will explore ethically and morally questionable stories of the Hebrew Bible that early Jewish and Christian interpreters had difficulty receiving as scripture. In the interpretive tradition, many of these stories are whitewashed, rewritten, or spiritualized in dramatic ways in an effort to find righteous heroes in countless examples of selfishness, faithlessness, deception, and violence. We will study the various kinds of interpretive strategies employed by early Jewish and Christian communities in the Ancient Near East, as well as dynamic methods of interpretation that allow the biblical text to stand on its own in all its beautiful and messy ambiguity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7090,2022,3751,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-335','<div class="desc"> <p>In this Russian language version partnered with CSLC 135, in addition to reading Tolstoy''s novel, <em>War and Peace</em>, in English, students will read Book Ten in Russian. Students will submit weekly reports that deal with multiple aspects of the Russian text, including Tolstoy’s use of syntax to achieve textual defamiliarization, his idiosyncratic vocabulary that challenges translation, and his fusion of time and space through grammatical and syntactical devices. Students will also present weekly translations of selected passages along with issues they encounter in attempting to create an accurate yet artistically appealing translation. As a final project, each student will also select a passage from another Book of <em>War and Peace</em> and provide an annotated translation.</p> </div>','RUSN 201 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7091,2022,3217,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/rusn-russian/300/rusn-339','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>This class will meet simultaneously with CSLC 139 twice a week, and then meet for an additional 90 minute session to read selections of the above works in the original. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','RUSN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7105,2022,990,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/200/copy-of-thea-245','<div class="desc"> <p>Students in <em>Stage Makeup</em> learn the fundamentals of makeup design for the theater. We cover a number of makeup techniques including basic three-dimensional corrective, glamour, character and old-age makeups with some special effects makeup. During the semester, students put theory into practice as they create a variety of practical and creative makeup designs. <em>There is a materials fee for this course, not to exceed $75.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7107,2022,1356,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/copy-of-thea-315','<div class="desc"> <p>In this course, designed for the novice performer as well as the advanced actor or singer, we focus on introducing students to the art of acting a song. We examine the literary and musical elements of scripts to reveal character and narrative, only here we do this while singing. Performers prepare and present musical selections from the Broadway canon, exploring how the elements of healthy singing (including breath control, phrasing, and placement) help convey character and story. Through freeing our musical voices to best express persona and narrative, we we examine the intersection of singing, acting, and audience connection. All experience levels welcome. A ticket fee, not to exceed $50, is associated with this course. Prerequisite: at least sophomore standing or permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7108,2022,993,'https://oxy.smartcatalogiq.com/en/2021-2022/catalog/course-descriptions/thea-theater/300/copy-of-thea-320','<div class="desc"> <p>Building on the foundation of Introduction to Technical Theater, the students in this course learn advanced construction techniques, metal working and welding, furniture construction and repair. Students in the class will also act as crew chiefs for Theater Department productions.</p> </div>','THEA 120; and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7118,2021,1498,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/100/amst-101','<div class="desc"> <p>This course introduces the major topics and perspectives of the interdisciplinary field of American Studies. Students will explore the diversity of United States culture, critically, in: its official and unofficial histories, its self-representations in the arts, its complicated intersections of ideals and realities. The class is required for American Studies majors and minors, and recommended for anyone wanting to better understand the relations between culture and identity in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7119,2021,797,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/100/amst-111','<div class="desc"> <h3>Environment, Health, Resilience, and Justice in the United States (2 units, Summer 2020)</h3> <p>Straddling the lines between history, politics, geography, science, and critical theory, this course examines the relationships between environment and health to highlight how environmental factors and health outcomes are inextricably linked while being spatially and racially determined. These issues have come to the fore vividly through the current COVID-19 crisis. The four unit course is divided into three integrated components throughout the academic year: a 2-unit summer online course, a 1-unit community dialogue in the fall, and a 1-unit community-based project in the spring.</p> <p>At the core, students will interrogate the sources of socioeconomic and racial health disparities through four key questions:</p> <p> â What role have issues of class, gender, and race played in the inequitable distribution of toxics and pollution? </p> <p>â How does living in toxic environments alter experiences of identity, health, and place? </p> <p>â How have communities combatted environmental hazards of the city, field, and workplace? </p> <p>â How do social movement efforts to address toxic exposures to their communities get translated into scientific and regulatory structures?</p> <h3>Engaged Reflection on Social Justice(1 unit, Fall 2020)</h3> <p><span style="color: #000000;">The ERSJ component links MSI’s academic content to diversity dialogue frameworks to help students cultivate the knowledge, skills, and attitudes associated with effective classroom engagement, socially responsible leadership, community and cohort development, and conflict resolution while also promoting practices of self and community care. The ERSJs will serve as an important foundation for students to understand power and their relationship to the systems that undergird environmental injustice and disparate health outcomes we studied in the summer class. The ERSJ sessions will help students build awareness around a range of issues related to Environmental Justice such as environmental racism, anti-blackness, anti-indigeneity, social and economic disparities, and redressing existing inequities. The ERSJs will also help students process the emotional work of learning about spatial and temporal dislocations and health inequities. Grade on a CR/NC basis only.</span></p> <h3>Practicum (1 unit, Spring 2021)</h3> <p><span style="color: #000000;">Building upon the learning and experience gained through the </span><em style="color: #000000;">Race and Community Exposures </em><span style="color: #000000;">summer course</span><em style="color: #000000;"></em><span style="color: #000000;">and fall Engaged Reflection on Social Justice (ERSJ) sessions and working in concert with their Multicultural Summer Institute (MSI) mentors, students will form teams and collaborate on equity-based, transformational projects that actively engage the campus community and perhaps extend to the broader community as well. The shape and form (e.g., art installations or performances, podcasts, protests, resource guides, webinars, wellness retreats, etc) will emerge organically through the collaborative process. Students will meet regularly (time TBD) to plan and execute the projects. In shaping the projects, students are expected to be collaborative, participate equitably, and to produce projects that uplift equity, justice, self and community care, and that aim to have a sustainable impact. Graded on a CR/NC basis only.</span></p> <p><span style="caret-color: #000000; color: #000000;">Students must earn credit in each of the three components to satisfy U.S. Diversity Core Requirement.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7121,2021,432,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/100/amst-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7122,2021,2731,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7123,2021,2670,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One CSP course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7124,2021,1433,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-215','<div class="desc"> <p>This course examines the history of sexuality in America from the early colonial era to the present. Along with theoretical readings, the course will consider primary and secondary sources addressing issues including: reproductive politics, socio-sexual control of Native populations, the rise of urban erotic subcultures, the sexual politics of slavery, American sexology, sex work, gender in private and public spheres, sex panics, feminism and gay liberation, and intersectional erotic cultural production.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7125,2021,2776,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-233','<div class="desc"> <p>This course introduces students to literary questions of queerness, canonization, and nation, in the context of the United States'' 20th century discourses about homosexuality. Students will analyze the production of ideas about the nation through literature and examine the limits and capacities of the novel genre for cultural expressions of LGBTQ life in America. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7126,2021,1,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-242','<div class="desc"> <p>This interdisciplinary course examines the migration of six million African Americans who left the rural South to move to cities in the North, Midwest and West in the first half of the twentieth century. Beginning with the “First Great Migration” of 1910-1930 and continuing through the “Second Great Migration” of the 1940s through the 1960s, we will explore the ways that this unprecedented demographic shift laid the groundwork for new forms of American popular culture as well as the emerging political campaigns and social movements of the long civil rights era.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7127,2021,1199,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-246','<div class="desc"> <p>A socio-historical analysis of narratives and novels by African American writers. The course will examine the intellectual, political, and cultural influences on writers such as Frederick Douglass, Harriet Jacobs, Charles Chesnutt, Nella Larsen, Zora Neale Hurston, Ann Petry, James Baldwin, Toni Morrison, and Charles Johnson.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7128,2021,1638,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7129,2021,1679,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-260','<div class="desc"> <p></p><p>This course will explore how Latinos have creatively represented their individual and collective experience in the United States. Literature will be the primary creative medium we look at, but some supplemental attention may be given to film and music. To reflect the variety and complexity of the U.S. Latino experience we will look at representative work from the Chicano (Mexican American), Puerto Rican, Dominican, Cuban, and Salvadoran or Guatemalan communities.</p><p></p> </div>','Fall CSP Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7130,2021,2819,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and theory as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations, power, knowledge, and identities are constituted through private and public rhetorical acts, mainly in the nineteenth-century to the present.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7131,2021,1680,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7132,2021,2,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-270','<div class="desc"> <p>This course analyzes the social experience and cultural heritage of Asian Americans through their writing, and places them in a broader comparative context of multi-racial/ethnic American society. We will examine the development of Asian American literature, its social implications and historical context, and the diversity of subject matter that the literary scene of Asian American communities has consisted of since the mid-19th century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7133,2021,434,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7134,2021,806,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-280','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7135,2021,4,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/200/amst-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Origins of the New Right</strong></p> <p>This course studies the twentieth century origins and myriad manifestation of the “New Right” in U. S. politics and culture. Starting in the 1920s with the rise of the second Ku Klux Klan and Christian Fundamentalism and homing in on the New Right’s various stages of development from the Cold War to the present, we will examine film, news media, television, critical theory, and historical analyses.</p> <p><strong>Latino/a Experience</strong></p> <p>This course will explore the history and experience of Latino/a immigrants in the United States, paying particular attention to how race, ethnicity, identity, politics, class, and gender influence the lives of Latino/a immigrants. We will also examine how they have influenced historical developments in different regions of the country, especially in terms of U.S. demographics. </p> <p><strong>Black Literary History and the Archive </strong></p> <p>How do we resurrect the lives of people who were considered unimportant, those whose contributions were dismissed and buried? What does the existing historical archive tell us about what is considered valuable and about what constitutes "memory"? This class examines the lives of two of the most important 19-century Black women writers, Harriet Jacobs and Harriet Wilson, as a means to develop the tools of literary recovery. As we expand the contours of the historical canon, we will also reflect on our own sense of the scope and shape of African American historical memory and the ways in which we organize history. How do we interpret religion, resistance, and labor activities that that fall "outside" of the most recognized narratives about African American experience? This class will take on these larger questions as we also engage in archival work in newspapers, census records, and beyond. </p> <p><strong>African American Literature: Race/Gender/Sexuality </strong></p> <p>This course is designed as a survey of African American literature. We will examine a multitude of genres, including: oral forms (spirituals, ballads, work songs), poetry, fiction, drama, and essays by authors such as: Phillis Wheatley, David Walker, Sojourner Truth, Frederick Douglass, Booker T. Washington, Ida B. Wells, W.E.B. DuBois, Langston Hughes, Nella Larson, Zora Neale Hurston, Jean Toomer, Jessie R. Faucet, Claude McKay, Richard Wright, Ralph Ellison, James Baldwin, Ann Petry, and Gwendolyn Brooks. Beyond strictly a "greatest hits" or "major authors" course, this class will also consider the ways African American writers interrogate complex categories of personal identity, which requires an in-depth investigation into the intersections of race, gender, sexuality, and socioeconomic class. Through lectures, class discussions, and student presentations, we will highlight the critical impact of African American literature on American culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7137,2021,1500,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/300/amst-320','<div class="desc"> This course will study the 20th century evolution of word-and-image texts from their origins in early superhero comics to their contemporary emergence as recognized literary works. The texts will be primarily from the United States, but some attention will be given to foreign works in translation. </div>','Any prior American Studies course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7138,2021,3017,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/300/amst-332','<div class="desc"> <p>Sigmund Freud''s intervention in personal sexual life often overshadows how psychoanalysis uniquely theorized violence in the context of two world wars. This course will consider how historical and contemporary violence in the U.S. might be informed by psychoanalytic concepts, including: aggressivity, group identification, neighbor relations, the death drive, and altruism. Readings include Freud’s work and texts by contemporary theorists grappling with the ongoing problems of war, racism, class conflict, and sexual violence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7139,2021,2608,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/300/amst-376','<div class="desc"> <p>This interdisciplinary seminar will explore the contentious history of the public memory and representation of slavery, the Old South, and emancipation in the United States. Drawing upon a range of sources – including fiction, film, advertisements, tourist sites, and public monuments – we will examine the various ways that Americans have sought to commemorate, critique, and capitalize on the history of the nation’s “peculiar institution” from the late-nineteenth century to the present day. Throughout the semester, we will interrogate the contested politics of these popular representations, and we will assess the ways that African American writers, filmmakers, preservationists, and artists have sought to challenge and reframe longstanding Jim Crow-era representations of slavery, replacing them with new narratives informed both by historiographical paradigm shifts and the politics of the ongoing black freedom struggle. </p> </div>','One HIST course, or one BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7140,2021,435,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/300/amst-390','<div class="desc"> <p>This course engages students in the history, practice, and research methods in American Studies by focusing on the significance of place, identity, and rights.While we will focus on the territory known as the United States, our readings and research will trouble the security of that designation. By examining the origins of settler colonialism in the Americas, focusing upon national borders and internal boundaries, and exploring the United States'' global reach, we will study and develop different ways of understanding "America" as a product of civic rights that are extended and denied. Students will apply American Studies theoretical methods in a research project of their choosing, and majors will develop this work into their senior comprehensives project. Offered only in spring semester. Majors are encouraged to study abroad in the fall semester to align this requirement with their progress toward the major. </p> </div>','AMST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7142,2021,436,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/300/amst-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7143,2021,437,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/400/amst-490','<div class="desc"> <p>This course is designed to assist students with the completion of research papers on topics that reflect selected areas of emphasis in American Studies. It will provide an opportunity for seniors to synthesize their area of specialization with an analysis of critical issues in the study of American culture and society. Offered only in fall semester (following AMST 390 in the spring). </p> </div>','AMST 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7145,2021,438,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/amst-american-studies/400/amst-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7146,2021,5,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/100/arab-101','<div class="desc"> <p>Introduction to Modern Standard Arabic and pronunciation, alphabet, simple oral communication, reading simple prose, and other basic language skills. Instruction in the fundamentals of Arabic grammar. May not be taken for credit by those with more than one year of previous high school study (grades 10, 11, 12) in Arabic or one semester of college study in Arabic. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7147,2021,440,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/100/arab-102','<div class="desc"> <p>Continuation of ARAB 101.</p> </div>','ARAB 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7148,2021,1501,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/100/arab-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7149,2021,1682,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/100/arab-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on a Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7151,2021,6,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/200/arab-201','<div class="desc"> <p>This course focuses on the development of communicative skills via reading, speaking, listening, and writing activities, while grammatical points are drilled intensively. Students begin to read and discuss cultural and literary texts, as well as simple media materials.</p> </div>','ARAB 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7152,2021,888,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/200/arab-202','<div class="desc"> <p>Continuation of ARAB 201.</p> </div>','ARAB 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7153,2021,1145,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/200/arab-275','<div class="desc"> <p>A selection of literary works and films from the Arab world will be analyzed in the context of historical, cultural, social, and political developments from the last decades of the 20th century. The texts, in various genres - short story, novel, memoir, poetry - will highlight the heterogeneity and complexity of Arab countries, such as: Morocco, Tunisia, Egypt, Lebanon, Iraq, and Saudi Arabia. Some of the main themes that we will cover include: tradition versus religion, challenges of modernity, gender relations, social (im)mobility, and generational gap. The course will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7156,2021,807,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/300/arab-301','<div class="desc"> An advanced Arabic course intended for students who have taken Intermediate II. It introduces the language of the newspapers, magazines, and internet news sites. Students will gain access to different sources from the Arab world. </div>','ARAB 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7157,2021,1043,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/300/arab-302','<div class="desc"> <p>This is a continuation of Arabic in the Media I.</p> </div>','ARAB 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7159,2021,441,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arab-arabic/300/arab-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7161,2021,1640,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/100/arth-150','<div class="desc"> This introductory course examines how cities, suburbs, and metropolitan areas are designed and developed. We will explore historical episodes and actors that have influenced urban planning so that we may then consider the ways in which contemporary architects, developers, and institutions approach urban concerns related to land development, the environment, housing, and transportation. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7162,2021,7,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/100/arth-160','<div class="desc"> <p>This course is an introduction to the rich traditions of East Asian art and architecture from ancient times to the present. The course is loosely framed in chronological order and each week will engage in an in-depth analysis of a different type of object and monument that addresses a particular concept and/or question. The themes to be covered include burial art for afterlives, the narrativity of handscroll paintings, state Buddhism, social and metaphorical uses of ink and calligraphy, ideology around ceramics, and gender and politics of contemporary performance art. We will also pay attention to the ways in which arts and monuments came to acquire enduring value and relevance through museum display and cultural preservation practices of our times. We plan to schedule at least one field trip to a museum/archive. Furthermore, the course helps students gain skills and methods crucial to art historical research and writing, such as close looking, critical thinking, and self-reflective writing.<br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7163,2021,8,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/100/arth-170','<div class="desc"> <p>European painting, sculpture, and architecture, from the Prehistoric Aegean to Renaissance Italy. Although the course will proceed chronologically, its goals are to introduce the student to a range of art historical skills and issues, including: stylistic analysis, iconography, the relationship between image and the artist''s biography, and the relationship between the image and its historical context. Museum visits required. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7164,2021,9,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/100/arth-180','<div class="desc"> <p>A selective survey of European and American painting and sculpture from the Renaissance to the mid-20th century. Coursework introduces students to the fundamental art historical practices of visual description and visual analysis. Readings, lectures, discussions and writing assignments focus on key artistic and visual conventions of the Euro-American tradition, from the invention of one-point perspective and illusionist models of art, to modernist critiques of those models in the 19th and 20th centuries. Major themes of the course will include changing approaches to visual narrative and description; the shifting status of the artist in Euro-American cultures; patronage, audience, art criticism and exhibition culture; issues of race, gender, identity and power in visual representation; abstraction and the rise of the avant-garde. Museum visit required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7166,2021,2860,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-200','<div class="desc"> <p>This course provides opportunities for students to engage in community-based work with arts organizations. Each student will work with a community-based partner or artist for approximately 6-7 hours each week. This in-the-field experience will be paired with reflective exercises and relevant readings, and will be facilitated by a faculty member in the department.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7167,2021,1568,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-256','<div class="desc"> <p>This course examines memory and forgetting in the context of the post-World War II period. It will consider how massive physical destruction necessitated the reconstruction of urban landscapes in Germany, France, England, Japan, and the United States. We will study urban redevelopment, in addition to architectural structures such as museums, memorials, and monuments, in order to discern how governments, societies, and individuals attempt to come to terms with the historical past. We will ask the following questions: What role do museums, memorials, and monuments play in the architectural landscape of a city? What design restrictions are posed by these types of institutions? How are abstract and representational forms employed in the memorialization process? Through an examination of these questions, students will gain an understanding of diverse built environments within an era marked by fundamental shifts in (post)modernism, technology, and aesthetics. To this end, emphasis will be placed on the ways in which memory and place are conceived within particular cultural and intellectual circumstances.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7168,2021,1569,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-257','<div class="desc"> <p>This course will interrogate 20th and 21st century architecture of the Asia Pacific. By concentrating on specific episodes of architectural production and urban development in the region, this course seeks to examine varying notions of the modern as it shifts across space and time. Considering theoretical and concrete modes by which modern societies and built environments have operated in tandem to create aesthetic, socio-political, economic, and technological networks will serve to frame the ways by which the Asia Pacific has come to be regarded as the crossroads for dynamic and experimental approaches to contemporary architecture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7170,2021,1502,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-259','<div class="desc"> <p>A thematic course on the history, theory, and practice of Modern Architecture in Europe and the United States, from the 1780''s to the later 20th century. Themes we''ll explore include the following: architectural theory and design as social planning, competing notions of public and private space, modernist architectural theory and urban development, rural and urban ideologies in American architecture, the changing image of the architect in the 19th and 20th centuries, architecture and urbanism in Southern California. Coursework will include a required half-day field trip.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7171,2021,1146,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-266','<div class="desc"> <p>An introduction to Japanese painting, sculpture, and architecture, from antiquity through the Tokugawa Period. Emphasis will be placed on the formation of an indigenous artistic tradition and its transformation under Chinese influence. The arts produced for patrons in Shinto, Buddhist, Zen courtly and samurai contexts will be examined. Museum visits required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7172,2021,2582,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-268','<div class="desc"> <p>This course examines the Japanese woodblock print from its emergence in the mid-seventeenth century to the modern era. We will investigate topics such as technological innovations, changing habits of looking, censorship and resistance in the creation of popular culture, the role of prints as a medium of reportage and propaganda, Japonisme and the construction of Japanese art, and global exchanges of materials and ideas. By tracing the historical development of Japanese prints, we will examine how woodblock prints were reconceptualized from a popular medium of visual culture to a quintessential embodiment of Japanese aesthetic tradition.</p> </div>','none. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7173,2021,2321,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-272','<div class="desc"> <p>An investigation of the art and architecture of ancient Greece and Rome from the Helladic era (c. 1500 BCE) to the appearance of Christianity in late Roman antiquity. Sculpture, metalwork, mural painting, vase painting, and architecture will be considered, with particular interest in how these forms are reflective of the fundamental political, spiritual, and philosophical developments during this era - as well as how these artistic forms serve as the foundational elements for European Art History.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7174,2021,10,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-275','<div class="desc"> <p>An introduction to the major works and issues of the period through an examination of key moments in Europe and the Mediterranean basin, from c. 300 CE to 1500 CE. A study of the forms, language, and uses of medieval visual culture will be related to the circumstances associated with the demise of the Roman Empire, migrations of Northern European peoples, the increasing power of secular rulers, the development of monasticism, and the theological perspective of the Roman Christian Church. Art and architecture associated with contemporary monotheistic religions (Judaism, Islam) will also be considered.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7175,2021,1044,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-278','<div class="desc"> <p>A chronological survey of the visual art and architecture created within, and for, the Islamic cultures of Western Asia, North Africa, and Europe, c. 630-1630, from Spain to India. Covers sacred and secular architecture and architectural decoration, sculpture, painting, manuscripts, textiles, and metalwork, including objects in area collections. Readings will include primary sources, exhibition catalogs, and scholarly articles; visits to museums and a mosque are anticipated.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7176,2021,2366,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-283','<div class="desc"> <p>This course examines the development of Italian Renaissance architecture, from about 1300 to about 1550. It will consider buildings in the civic and ecclesiastic context, both sacred and secular. The evolution of this tradition will be studied in relationship to issues of function and structure; contemporary writing; and religious, political, and economic influences.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7177,2021,998,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-285','<div class="desc"> <p>This course will explore artistic practices in the U.S., North America, and Europe, during the long 19th century, from roughly 1789 to 1900. Lectures, discussions, and readings are designed to provide a thematically-driven, chronological overview of the period. Yet, the course will not be a traditional "survey," rather, it will focus on some of the key changes in ideas about artistic culture; art practice; and practices of regional, national, and transnational identity formation as expressed in visual art. This course will explore the role of art in social and political revolution, as well as its formative status as an engine of cultural imperialism in the 19th century, and, in addition will explore some of the more traditional approaches to studying the status of art, such as the role of the artist and the transformation of the art "market" in the wake of the industrial revolution. Key debates within the field of Art History will be explored, as well. Museum visits required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7178,2021,445,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-287','<div class="desc"> <p>What is a photograph? Is it a "document" or a "work of art"? Who makes a photograph and for whom does s/he make it? How and where do photographs circulate? What effect does the context in which a photograph is viewed have on its meaning? Designed as a selective history of photography in the 19th and 20th centuries, this course revolves around questions like these about the nature and function of photography in modern culture. Through varied course readings, in-class discussion, thematic lectures, and hands-on research, students will explore the medium of photography from multiple perspectives. In addition to learning about the different photographic genres - exploration and travel photography, studio and portrait work, medical and legal documentation, fine art prints, photojournalism - this class will push students to investigate photography''s position within a broader cultural field: the medium''s role in advertising and consumer culture; the production and circulation of ideas about race, gender, and national identity; and photography''s role in producing history itself. Readings will include primary source materials and theories of photographic meaning; students will be asked to grasp not only the medium''s technological and rhetorical functions, but also to develop their own critical perspectives on photography''s shifting relations to intellectual, social, and political ideologies. Coursework will include some community-based research, and a museum visit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7180,2021,11,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-289','<div class="desc"> <p>This course will focus on modernist artistic practices in the United States and Europe between 1900 and 1950. We''ll look carefully at a wide range of practices, including painting, sculpture, photography, film and architecture. Coursework will include readings, discussions, and lectures about modernism, the rise of the avant-garde, and the role of exhibitions in the transformation of modern art. We will engage issues of gender, sexuality, race, class, and ethnicity, and the scholarship we read will encompass diverse approaches to analyzing and interpreting modern art.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7181,2021,1319,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/200/arth-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Japanese Art and Visual Culture in the Americas</strong></p> <p>In 2001, respected art historian Yoshiaki Shimizu contributed an article entitled “Japan in the American Museums: But Which Japan?” (<em>Art Bulletin</em>, 83:1 [March 2001], 123-134). The article questions what defines Japan and Japanese art by examining exhibitions of Japanese art at American museums as well as concordances and contradictions over the art of Japan among agents and players of art. The questions that the article posed are invigorating and valid nearly twenty years after its publication, but they deserve some updates. Inspired by Shimizu’s thematic approach, this course will consider Japanese art and visual representations of Japan in the Americas and expand the scope of the art of this day. The class looks at Japanese art and artists in Mexico, engages more actively with Japanese and Japanese American art in Los Angeles, and critically embraces popular culture and subculture. Other topics to be examined include Japonisme, new and creative woodblock prints, folk craft and modern design, abstract painting and performance, and women artists in New York as well as dealers, collections, and collectors of Japanese art in Los Angeles. <em>Additional </em><em>Core Requirements Met: Regional Focus (CPRF).</em></p> <p><strong>Materials and Materiality in Japanese Design</strong><br/> This course explores key materials and materiality in Japanese art and design. Each class is structured around a different type of material or a combination of materials, such as rock, paper, wood, metal, earth, silk, and food. We will look at these materials or uses of them cross-historically rather than chronologically—as an embodiment of spiritual/religious practice, representation of social class, identity of local community and environment, and/or artistic methodology, in addition to examining them simply as mediums and respective production techniques. <em>Additional </em><em>Core Requirements Met: Regional Focus (CPRF).</em></p> <p><strong>Art and Nuclear Technology, Destruction, and Contamination</strong></p> <p style="margin-left:0px; margin-right:0px">This course explores art and its relationship to nuclear technology, destruction, and contamination. The primary focus will be on postwar Japan but we will also investigate Disneyland and its link to the Atoms for Peace campaign, visual projects regarding nuclear accidents at Chernobyl and Fukushima in addition to the impacts of unclear technology, test sites, and nuclear waste isolation sites on image-making. Themes to be examined include Cold War culture and politics, art and disaster, trauma and memory studies, documentary art and art of witness, censorship, invisibility, activism, and dark tourism. Over the course of the semester, we will look at a variety of artistic genres and mediums, such as paintings, sculptures, photographs, installations, performances, animations and films, comics and picture books, designs, and public monuments as well as exhibitions and world expositions. <em>Additional </em><em>Core Requirements Met: Regional Focus (CPRF).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7183,2021,2671,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-360','<div class="desc"> <p>This course explores the relationship between art and women in East Asia from ancient times to the present. We will study the various ways in which women have been engaging with art—as producers, as patrons, and as objects or subjects of the gaze. At the same time, we will examine how women and gender have been conceived and contested in East Asia. Over the course of the semester, we will investigate topics such as women artists and patrons; Buddhist conceptions of the feminine and women’s devotional practices; performing “women” in theater; shifting ideals of beauty and the alteration of women’s bodies; and the representation of gender in contemporary popular culture. Ultimately, students will develop critical tools for examining how women have been represented in visual culture and how they have exerted their own artistic agency in East Asia. </p> </div>','Any Art History course, East Asian Studies course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7184,2021,2518,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-365','<div class="desc"> <p>This course examines the role of gender in the production and reception of visual images in Japan from the twelfth through the twenty-first centuries. Closely engaging with a variety of images, literary texts, and performances, we will investigate topics such as Buddhist conceptions of the feminine, same-sex sexuality and gender reversals in the medieval imagination, beauty prints and the politics of the gaze, changing conceptions of art and women in modern Japan, masquerades of masculinity, and the place of male-male sexuality in contemporary girl culture. Ultimately, this course will provide students with an understanding of how art and gender have been conceptualized in Japan, as well as tools to think beyond that understanding.</p> </div>','Any art history course, Japanese studies course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7185,2021,2322,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-372','<div class="desc"> <p>This course examines the development of Venetian painting in the 15th and 16th centuries. Among the artists considered will be Carpaccio, Giovanni Bellini, Titian, Tintoretto, and Paolo Veronese. This course will focus on the unique geographic and historical context of Venice, "the most serene republic" (La Serenissima), and its (WHAT IS "IT") extraordinary influence on the history of European painting.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7186,2021,1105,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-373','<div class="desc"> <p>Painting, sculpture, architecture, and urban planning of Michelangelo Buonarroti. This course considers the development of the artist, from his apprenticeship in the shop of Domenico Ghirlandaio, through his late paintings in Rome. All works are considered for their stylistic, iconographic, and social context. Particular attention will be paid to the urban and specific patronage context of each work, which is critical in order to develop a more complete understanding of Michelangelo''s art and intellectual development. This course requires travel to Italy during the winter break.</p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7187,2021,12,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-374','<div class="desc"> <p>A survey of the painting, sculpture, and architecture of Italy, from about 1300 to 1500. All major figures, including Giotto, Ghiberti, Donatello, and Botticelli, will be considered. Works will be examined in terms of setting, patronage, and cultural context, in addition to questions of style and meaning.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7188,2021,1045,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-376','<div class="desc"> <p>High Renaissance and Mannerism. Among the artists considered are Leonardo da Vinci, Michelangelo, Titian, and Raphael. Of special consideration is the nature of the Papacy, as a patron of art, and the city of Rome, as a context for artistic activity. The course will also consider the reasons for the dissolution of the classical tradition during this time by artists such as Pontormo, Parmigianino, and Giulio Romano.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7189,2021,1147,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-378','<div class="desc"> <p>An examination of the artistic traditions of Northern Europe from c. 1400 to 1600 CE. Points of consideration include significant artistic personalities and individual works, the relationship between patron and image, territorial distinctions, in addition to the connection between Northern and Southern (Italian) visual developments during this period.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7190,2021,13,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-389','<div class="desc"> <p>This course will explore the diverse forms of visual culture - painting, sculpture, photography, installation, performance, and video - produced after 1945. Through clusters of thematic and monographic lectures, we will investigate questions about artistic identity, the status and function of art in the post-World War II period, and the changing nature of avant-garde (and neo avant-garde) practices in the wake of the social cultural and economic changes of the 1960''s and 1970''s. Post-industrial society new movements advocating civil rights, feminism, and environmentalism will form the cultural backdrop of our work, as will more focused investigations of postmodernism critical theory''s increasingly central role in artistic culture and a burgeoning global network of artistic and cultural exchange and contestation. In addition to presenting a selective history of visual culture after 1945, this course will explore how changing ideas about race, ethnicity, gender, sexuality, and cultural identity have impacted the art and criticism of the period under consideration. At least one field trip to a gallery or museum will be required.</p> </div>','ARTH 180 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7191,2021,14,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-390','<div class="desc"> <p>A research intensive course on a topic within the history of art; coursework will include the process of researching and writing a scholarly essay and a focus on the methodologies of art historical scholarship. Required for Art History majors to fulfill the Second-Stage Writing Proficiency requirement. </p> <p><strong>Building the ‘American Pacific’</strong></p> <p>This course examines modern and contemporary architecture of the ‘American Pacific.’ Students will investigate the historical, social, cultural, political, climactic, and technological factors that have influenced the development of architecture in Hawai‘i, American SÄmoa, and Guam. Theoretical examinations about U.S. empire, race, and sovereignty allow us to challenge the very notion of an ‘American Pacific’ and frame our study of architecture as a complex interplay of evolving beliefs and meanings. An examination of Pacific Island spaces/places and their relationship to artistic endeavors by artists and architects reveal the ways in which indigenous and foreign identities influence the built environment. Students will engage with interdisciplinary and intersectional scholarship as we consider the architectural legacy of American expansion in the Pacific. Additional Core Requirement Met: Regional Focus.</p> <p><strong>Colonial Urbanism </strong></p> <p>In this course, we will examine the spatial legacy of colonial cities. The focus is on colonial urban spaces and architectural projects that were manifestations of the political, economic, and social relationships between the colonizers and the colonized. In relation, the role of imperialism - as it transpired in both the colonies and colonizing societies of Europe and the United States - will reveal the ways in which the imperial imagination was visible in physical form. Through a range of case studies, including sites in former European and American colonies of Asia and the Pacific, as well as former imperial centers, such as London and Washington D.C., students will develop a theoretical toolkit for the critical study of urban colonial environments. </p> <p><strong>Giotto di Bondone (1266/7-1337)</strong></p> <p>He is arguably the most influential painter of the 14th century. A true revolutionary, his art changed the direction of European painting and is the fulcrum between the late Middle Ages and the Renaissance. This course is an intensive study of his career, both as a panel painter and as a muralist (Florence, Padua, and possibly Assisi). Students will be responsible for in-class presentations of individual works and will research a term paper engaging a scholarly controversy regarding one aspect of Giotto''s art. Additional Core Requirement Met: Regional Focus.</p> <p><strong>Gender and Sexuality in 20th Century Art</strong></p> <p>This seminar will explore the how issues of gender and sexuality have shaped the practices of visual artists in the US and Europe in the 20th century. We will investigate how artists have engaged directly with these issues in their art, and we will also consider how the field of Art History itself has been impacted by practices and stereotypes about gender and sexuality. Additional Core Requirement Met: Global Connections.</p> </div>','Any 100- or 200-level Art History course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7192,2021,1436,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-392','<div class="desc"> <p>The history, purpose, and varied practices of museums are examined cross-culturally in this introductory course designed as a community-based practicum. Core concepts of museology, such as: collections management, educational outreach and programming, standards and ethics, curation, exhibition strategies, and disciplinary standards are examined in case study scenarios supported by academic readings and collections-based inquiry. Students will work collaboratively with others in team-based learning and problem solving, while demonstrating critical thinking in written essays and oral debates. The class will make use of the resources of the Autry National Center of the American West.</p> </div>','One 200-level Art History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7193,2021,1320,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Imag(in)ing</strong><strong> War and Disaster in Modern and Contemporary Japan</strong></p> <p>This course explores how practitioners of art and visual culture have responded to physical and psychological damages that were caused by wars and disasters in modern and contemporary Japan. The course loosely follows a chronological order and a thematic framework. We will look at expansive materials, including colorful and playful woodblock prints (<em>ukiyo-</em>e) of natural disasters; prints and memorabilia of the Russo-Japanese war (1904-05); topography and the building of the Yasukuni Shrine and its exhibitions; the birth of the avant-garde and its relation to the Great Kanto Earthquake (1923); war documentary paintings and propaganda during WWII; atomic bomb photographs and memorials; reportage painting of the 1950s; anti-art and non-art movements of the expanded 1960s; <em>kawaii </em>(cuteness) and monstrosity in manga and animation; and socially engaged art about Fukushima. The course aims to enable students to analyze how politically inspired or socially engaged art developed in modern and contemporary Japan. <em>Additional Core Requirements Met: Regional Focus (CPRF).</em></p> <p><strong>Who Owns Art? </strong></p> <p>As art objects - especially those from antiquity - have become increasingly valuable, as both commodities and as national treasures, questions as to who owns art and who is best to care for these objects are essential to museum curators, academics, and politicians. There are several debates over who owns art of ancient civilizations like Greece and India. Do treasures like the Parthenon sculptures at the British Museum belong to Greece and should they be returned? Or should they remain in the museum where more people have access to them? This seminar will introduce students to laws enacted by UNESCO (United Nations Educational Scientific and Cultural Organization) to protect world, cultural, and national heritage, as well as to the examination of museum collecting policies in America. Specific cultural patrimony cases will also be examined and discussed. This seminar is for students who are interested in learning more about cultural patrimony, art law, and museums.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7194,2021,446,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/arth-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7195,2021,1202,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/300/copy-of-arth-391','<div class="desc"> <p>A seminar focusing on a topic in the history of art taught by a practicing curator at a Los Angeles cultural institution. Course topic(s) change annually and will include off-campus hands-on work within the context of curatorial and exhibition practices. Course may be repeated for credit with a different topic.</p> <p><strong>East Asian Gardens: China, Japan, Korea—and California?</strong> <strong>(4 units)</strong></p> <p>What kinds of gardens have existed in East Asia, and what sorts of functions have they fulfilled? How have they engaged with broader visions of the cosmos, and how have they expressed such understandings? What happens to such gardens when they are translated into a cultural context very different from that in which they emerged? To answer these questions, this course, taught by a curator at the Huntington Library, will take a broad view of the history of East Asian garden-making, examining images, texts, films, and gardens from the 2nd century BCE to the present. We will investigate hunting parks constructed as microcosms of empires, holey rocks that inspired dream-journeys to immortal realms, Buddhist paradises accessible in this-worldly estates, and textual fantasies of gardens of the mind. Taking advantage of the Chinese and Japanese Gardens at the Huntington, this course will also explore how such concepts have been put into practice in the physical spaces of these gardens, where the course will be held each week. Moreover, we shall trace the very different histories of these two gardens in order to gain insights into California''s shifting relationship to East Asia over the course of the twentieth and twenty-first centuries. In taking this course, students will ultimately gain an understanding of the diversity of garden forms in East Asia; familiarity with key concepts used in garden-making; practice with the skills of visual and spatial analysis, as well as cultural and historical contextualization, necessary to discuss gardens meaningfully; and experience with curatorial strategies for making East Asian gardens accessible to diverse audiences. The final project will involve developing an interpretive program for one section of the Huntington’s gardens. <strong>This course meets on Friday, at the Huntington Library, Art Collections and Botanical Gardens</strong>. <em>Additional Core Requirement Met: Regional Focus and Pre-1800.</em></p> <p><strong>TRUE GRIT: American Prints from 1900 to 1950 (2 units)</strong></p> <p>This seminar engages the exhibition and the J. Paul Getty Museum:"True Grit: American Prints from 1900 to 1950" which opens on October 15, 2019. This exhibition, drawn from local museums and a private collection in Los Angeles, provides a vibrant survey of early twentieth-century American printmaking. Compelling depictions by Peggy Bacon, George Bellows, Mabel Dwight, Edward Hopper, Martin Lewis, Kyra Markham, and John Sloan convey a broad view of American culture that include dance halls and boxing rings, skyscrapers and subways, parks and tenement apartments. Using innovative printmaking techniques, these American artists captured the gritty world around them and came to terms with modern life. This seminar will examine the nature of American printmaking in the early twentieth century. In addition to working with the Getty curator in planning the installation of the exhibition itself, topics will include evolving printmaking techniques and the evolution of a uniquely American subject matter. <em>Additional Core Requirement Met: </em><em>Fine Arts (partial).</em></p> </div>','Any 100- or 200-level Art History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7196,2021,447,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/400/arth-490','<div class="desc"> <p>Open only to senior Art &amp; Art History majors with an emphasis in History of Art. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7199,2021,448,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arth-art-history-visual-art-art-history/400/arth-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7200,2021,2729,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/100/arts-100','<div class="desc"> <p>The Oxy Arts Collaborate Workshop will bring a teaching artist, Oxy students, and youth from the neighboring Highland Park school district together in creative collaboration. During the first six weeks of the semester, Oxy students will learn core arts education and public engagement pedagogy. They will work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop curriculum for a Visual + Performing Arts course or Creative Writing course. In the following six weeks of the semester, Oxy students will collaboratively lead an after school art workshop for local middle school youth, culminating in a final public presentation. This course is an eligibility requirement to apply for a paid position through Oxy Arts to lead after school art classes on-site at local Highland Park elementary schools starting in the Spring semester. <em>Permission of Director of Oxy Arts required.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7201,2021,15,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/100/arts-101','<div class="desc"> <p>Working with a variety of drawing materials - charcoal, pencil, ink, gouache, and acrylic paint - students investigate a fundamental aesthetic and visual vocabulary. Beginning with exercises in mark-making, then working through a formal study of basic visual elements and simple subject matter, students develop a working understanding of two-dimensional composition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7202,2021,16,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/100/arts-102','<div class="desc"> <p>Beginning with a familiarization of paint gesture and mark, then working through a formal study of basic visual elements (line, shape, form, light, space, and color) and simple subject matter (still life, landscape, the figure, abstraction), students develop a basic understanding of image construction and two-dimensional composition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7203,2021,17,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/100/arts-103','<div class="desc"> <p>The aim of this course is to introduce the conceptual, technical, and critical tools central to contemporary sculpture practices. The class consists of a combination of technical seminars, in-class fabrication, critiques, field trips, informal lectures in contemporary art history, readings, and a series of short papers. Emphasis will be placed on the student''s ability to make, understand, discuss, and write about sculpture in a substantive way.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7204,2021,18,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/100/arts-105','<div class="desc"> <p>Printmaking Fundamentals is an introduction to the technical and conceptual properties of relief and intaglio printmaking. Through a series of projects, critique sessions, and written assignments, the course will introduce students to debates in contemporary printmaking, and the larger historical and cultural contexts that inform their work. The class will also feature visiting printmakers, field trips and other activities linking the coursework to the larger Los Angeles community.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7205,2021,999,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/100/arts-107','<div class="desc"> <p>The aim of the Digital Photography course is to develop the conceptual, technical, and historical tools to develop a critical photography practice. The course will consist of a combination of technical seminars, critiques, class readings, field trips, lab time, and lectures in photographic history and contemporary art practice. The course will provide a technical introduction to the fundamentals of digital photography, including: camera operation, file management, image processing, Photoshop, printing techniques, and image presentation. Additionally, students will develop the critical skills needed to discuss photographs productively, participate in critiques, and generally situate their photographic production within a larger cultural and historical construct. Emphasis will be placed on student''s ability to make, understand, and discuss photographs in a substantive way. Lectures, critiques, and personal consultations will stress the interdependent concerns of technique and content. Underscoring the course''s outcomes of visual literacy are the centrality of photography to the historical development of modernity and the crucial role of digital photography in our image-centric globalized world. Throughout the course, students will be encouraged to integrate the breadth of their liberal arts studies in their image making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7207,2021,892,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-203','<div class="desc"> <p>Intermediate study in sculpture, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year.</p> </div>','ARTS 103 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7208,2021,1570,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-209','<div class="desc"> <p>This course is a conceptual art class that takes photography as its subject. Using a wide range of photographs and photographic practices, the class will consider how photographs are instrumental in forming our notions of self, family, work, and nation. We will also grapple with the difference between analogue and digital photography and photography''s relation to the physical world. The class will read key photography essays that will challenge students to think critically about the role of photography in contemporary culture and modernity, historiography, and science. We will use a broad range of art techniques like drawing, painting, printmaking, sculpture, digital alteration, and even craft techniques to remake and rework photographs to reveal hidden truths or create new meanings. Unlike some classes where you learn art techniques first, here you will be expected to adopt techniques and generate art from a set of ideas that arise from our readings, discussions, experiments, and field trips.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7209,2021,450,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-210','<div class="desc"> <p>Intermediate study in painting, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year.</p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7210,2021,20,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-215','<div class="desc"> <p>This is an introduction to the fine art of silkscreen printmaking. Students learn the historical, theoretical, and critical understanding of the process, with an emphasis on developing their artistic voice by completing specific assignments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7211,2021,811,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-216','<div class="desc"> <p>An introduction to the process of lithography, a technique of printing from a drawn image on limestone. Course emphasis will be on the drawing and how the medium allows for evolving the visual image over time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7212,2021,451,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-217','<div class="desc"> <p>An introduction to new combined photo and drawing processes in printmaking, including: photo-sensitive emulsion on copper plates, solar etching, and paper plate lithography. This course will explore how photography can influence the many approaches to contemporary printmaking. Students should have an interest in creating photo images and some familiarity with Photoshop software.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7213,2021,1366,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-227','<div class="desc"> <p>This class is an introduction to the historical art of letterpress printing using design elements with text and image. Students will complete a collaborative artist book with hand binding and original imagery using typographic design, hand typesetting, and letterpress printing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7214,2021,2370,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-228','<div class="desc"> <p>Book Arts: The Handprinted Book is a hybrid book making, research, writing and collaborative art making course. Students will advance their knowledge of letterpress printing by researching, planning, designing, and producing a handprinted artist book. The course will address narrative sequencing, page layout and design, type as graphic innovative and/or image-making, methods for the Vandercook Press, and the structure of the book. Each course iteration will address a theme, integrating book making techniques with theoretical readings, collaborations with faculty and departments from across the College, and primary research in Special Collection the Moore Zoology Lab and other campus collections. The course is will also examine the current state of the book in the context of 20th and 21st century artist book design and production.</p> </div>','ARTS 227 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7215,2021,2753,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-230','<div class="desc"> <p>This course invites students with previous art experience from across the College, including visual arts, music, theater, creative writing, MAC, etc., to explore genre-crossing art. The course will focus on the specialty of the faculty member, including video installation, sound art, performance art, site-specific art, collaborative projects, community based projects and social practice art. The class meets twice per week for technical demonstrations, in-class art making, visiting artists, and critical feedback, along with out of class visits to contemporary art and performance venues. Permission of instructor required.</p> <p><strong>Visualizing Sound</strong></p> <p>Sound Arts takes a cross-disciplinary approach to utilizing sound as a stand-alone installation or integrated within other media. Many contemporary artists are interested in incorporating sound into their projects but may not know how to approach and accomplish that integration. Because sound is ephemeral it can be used in an infinite number of ways to infer complex relationships. The challenge of using sound is that of translating ideas into the sonic medium and then reproducing that medium back into physical space. In this class students will learn about sound and discover ways to apply sound to express a deeper theoretical practice. Practical sound related techniques will be explored, as will their application through skills like deep listening, recording techniques for best capture practices, basics of the Digital Audio Workstation, and the use of sound reproducing systems. Students will collaborate on a project over the course of the semester with an exhibition in the OXY Arts Space at the end of the semester with an opportunity for performance.</p> </div>','Any two Art History, Studio Art, Media Arts &amp; Culture, Music, Theater, or Creative Writing courses ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7216,2021,1503,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-250','<div class="desc"> <p></p><p>African American, Latinx, Asian, Feminist, GLBT, and transnational artists catapulted by liberationist desires and responding to questions of social transformation are the focus of this hybrid art making, history, and theory class. The course will focus on Los Angeles-based 20th and 21st century artist led efforts that critically engage issues of race, gender, ethnicity, and class both historically and within the present. The course will begin with an investigation of questions related to historiography and memory as they relate to politically engaged art practices through critical texts, a site visit to the Southern California Library, an independent archive of local Los Angeles movement history in South Los Angeles, and a workshop that will share research methodologies employed by my own collaborative artistic project, the Pochx Research Society of Erased and Invisible Histories to contest dominant historical and artistic canons. Through a workshop format, local contemporary artists such as Dewey Tafoya, Shruti Purkayastha, will provide students with tools to develop projects that respond to dominant cultural narratives through graphic, performative, and interventionist strategies. Finally, students will learn how artists shake the foundations of various established institutional worlds and the definitions of art itself by moving away from these very institutions and spheres of practice and by creating their own structures for critical thought and praxis: building collectives, artist led spaces and in the case of School of Echoes, becoming community organizers.</p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7217,2021,2861,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-270','<div class="desc"> <p>Art, Ethics and Medicine: The PPE Portrait Project is a four credit class focused on the tenets of the the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care at USC-Keck Hospital, Stanford Medical School, UMASS, Mass General and advising nearly a dozen other hospitals across the US and beyond. At the heart of the PPE Portrait Project is the centrality of the image, and the role of the face in generating empathy, compassion and ethical behavior. </p> <p>The PPE Portrait Project Semester will combine theory, research and practice together with the community engagement (ARTS 275) intrinsic to this social practice art project. Students will learn how artists act as innovators and catalysts of change; the art history and visual studies of representing the face, including portraiture, photography, and discredited attempts to read intellect or morals in the appearance of a face. Students will also learn about the connections between visual culture (like portraits) and science, including the developmental concepts of facial recognition, and representation recognition in infants and others; the neuroscience of mirror neurons and the biological basis of intersubjectivity as the foundation of ethical behavior; the philosophy of bioethics and notions of patient self-determination and agency; and the biology and physiology of social and cultural actions. Students will learn how looking at images has the power to physically change a person''s body. Through this project, students will deepen their understanding of the structures and processes of privilege, exclusion, and marginalization that shape healthcare in the United States.</p> </div>',NULL,'ARTS 275 and CSP 28 ',NULL);
INSERT INTO course_descriptions VALUES(7218,2021,2862,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-275','<div class="desc"> <p>In this course, students will activate their own project site of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care across the US and beyond. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Students will be encouraged to implement the project in a group with whom they have a meaningful connection, including schools, community groups; any group who would benefit from an enhanced human connection at a time of masked distancing, anonymity and faceless interaction. </p> <p>At the heart of the PPE Portrait Project is the centrality of the image, and the role of images of the face in generating empathy, compassion and ethical behavior. With widespread facemask use on our horizon for the foreseeable future, the need to address the isolation and alienation caused by faceless person-to-person exchange is expanding beyond the urgent need of hospitals. Precipitated by social media before the pandemic, and now exacerbated by the coronavirus, we are experiencing an "epidemic of facelessness." </p> <p>Students will use community based learning methods to ethically engage with a group, and innovate with the PPE Portrait Project tenets and materials to best meet the needs of the community partner. </p> </div>',NULL,'ARTS 270 and CSP 28 ',NULL);
INSERT INTO course_descriptions VALUES(7219,2021,1571,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-280','<div class="desc"> <p>A team-taught course pairing an Occidental and an Art Center College of Design faculty member in project-based work integrating the history, theory, and practice of the visual arts. Topic for Spring <span style="text-decoration: underline;">2016 (out of date?)</span>: Maker Communities: From Arts and Crafts to DIY along the Arroyo Seco. In the early 20th century, a cultural blossoming, that came to be known as the "Arroyo Culture," emerged along the Arroyo Seco river, from the Hahamong''na Watershed above Pasadena, through Eagle Rock, Highland Park, and the diverse communities of Northeast Los Angeles, down to the Confluence with the LA River in Cypress Park. This Arroyo Culture sprung from the international Arts and Crafts Movement''s emphasis on the handmade, seeking to fuse the material and the spiritual and thereby make everyday objects and architecture the expression of individuality and artistic purpose. This course, a collaboration between Occidental College and the Art Center College of Design, will trace this rich and innovative Arroyo Culture through the community''s many demographic and cultural transformations, particularly the revolutionary reinvention of the tradition by Latino artists and intellectuals, up through today''s resurgent "maker" culture. In the process, students from the two institutions will engage with both the rich cultural and geographical history of the area and the work of present day designers and artists. That engagement will culminate in a final project and presentation reflecting (either at students'' individual option through research-driven writing or in physical form through a work of art/design) the cultural production flourishing along the watershed of the Arroyo Seco. Not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7220,2021,1203,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/200/arts-290','<div class="desc"> <p><strong>A Sustained Environment: Understanding and Caring for Bio-Cultural Diversity.</strong></p> <p>This course coincides with the unprecedented environmental and pandemic challenges of our time, bringing a new urgency to understanding the complex and dynamic interrelations between human culture and the natural environment. Using embodied pedagogy to incorporate our bodies into the learning process, as well as indigenous, ecofeminist, and intersectional frameworks, we will analyze pressing ecological issues including climate change, nature rights, green capitalism, extractive economies, and environmental justice. We will reach to other environmentally focused resources on campus; host guest lectures and artist led workshops; conduct research and fieldwork in archives, libraries, and outdoor locations; and visit local initiatives that intersect art, science and environmental practices. Utilizing a range of contemporary aesthetic strategies, we will develop a research-based project to study and present environmental problematics around Occidental campus. Projects are expected to have a multidisciplinary approach, and can be developed individually or in collaboration. This course is open to all majors.</p> <p>Previous Wanlass Artists-in-Residence include: Lucky Dragons, CamLab, Rafa Esparza and Kenyatta A.C. Hinkle.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7223,2021,1683,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-301','<div class="desc"> <p>Audre Lorde famously wrote that the master’s tools will never dismantle the master’s house. What possibilities open up when we use language - a common currency of our everyday lives, too often the foundation that props up structures of confinement and limitation - on our own terms, in forms of our own invention and modes we imagine autonomously? How can we use writing to support and expand the work we do as artists? Is language a “master’s tool” or is it a tool we can use to “dismantle the master’s house”? In this class, we will explore creative forms such as artistic manifestos, statements of poetics/aesthetics, and reviews as invitations to better understand and articulate the parameters of our own art practice, and as powerful opportunities for collective enunciation. We will do close readings of primary texts from European, Latin American, and U.S. American avant-garde and art-activist movements, both historical and present-day. We will consider essays, reviews, manifestos, poems, blog posts, and tweets. Students will write individual and collaborative art statements as a way to clarify their own work, and think through larger issues in aesthetics and the social/political potential of art. Assignment exercises will encompass research and practice in collective and individual art writing, focusing both on student work and the work of other artists.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7224,2021,2892,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-303','<div class="desc"> <p>Advanced study in sculpture, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year.</p> </div>','ARTS 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7225,2021,21,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-310','<div class="desc"> <p>Advanced study in painting and drawing, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year.</p> </div>','ARTS 102 and ARTS 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7226,2021,1048,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-330','<div class="desc"> <p>Advanced study in printmaking including developing a theoretical, historical, and critical understanding of photo-based materials and media, including images on pronto plates and monotypes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7228,2021,454,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-390','<div class="desc"> <p>Art in LA will explore the shifting roles of the contemporary artist, art writer, and curator in today''s diverse and globalized art world. Students will put theory into practice by engaging in art making, curating and writing about contemporary art in Los Angeles with the goal of creating an expansive critical space for their thoughts to flourish. The course will ask, "What are exhibitions?” investigating conventional and alternative curatorial practices that question the cultural, political, economic, regional, and social contexts shaping the exhibition of contemporary art. Students will collaborate to mount an exhibition of their own design, and will be encouraged to question the boundaries of the "white cube gallery," pushing art into surprising public and private spaces. <br/> <br/> Art in LA will feature behind the scenes visits to Los Angeles area exhibition venues and artists'' studios, enabling students to learn about the range of art practices and the practical exigencies of bringing art and its exhibition to fruition. This course will serve as the required advanced exhibition methods course for junior studio art majors, modeling the myriad of ways it means to be an artist in the world, and readying rising seniors for a robust comprehensive experience. Scheduled at the same time as the Studio Art Senior Seminar, the course is designed to facilitate collaboration between junior and senior art majors. Students in ARTS390 will participate in the ARTS490 senior comps critiques, provide feedback to senior''s artist statement drafts, and collaborate with the senior art majors in the installation of their comprehensive exhibition. </p> </div>','One 200-level ARTS course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7230,2021,455,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/300/arts-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7231,2021,23,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/400/arts-490','<div class="desc"> <p>Group critiques of individual projects in student''s choice of medium. Discussion of techniques, exhibition problems, self-evaluation, and current art movements, in the context of the history of art. May earn up to a total of four units.</p> </div>','At least junior standing and ARTS 102, ARTS 103, ARTS 105, ARTS 203, and ARTS 210; OR ARTS 216; OR ARTS 217 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7233,2021,456,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/arts-art-history-visual-arts-studio-art/400/arts-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7236,2021,24,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bich-biochemistry/400/bich-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Biochemistry majors; to be taken both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7237,2021,457,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bich-biochemistry/400/bich-499','<div class="desc"> <p>Independent study under the supervision of a faculty member. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7238,2021,25,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-103','<div class="desc"> <p><strong>Urban Ecology</strong></p> <p>Los Angeles is an urban ecosystem where people, nature, and the built environment interact. We will consider L.A., the second largest city in the U.S., as a case study of how organisms and the environment influence each other. Through reading, discussion, writing, gathering data, and exploration we will ask, what physical features define the Los Angeles environment? How have these changed over time, and what changes are likely to happen in the near future? What species of organisms (beyond palm trees, pets, rats, and cockroaches) inhabit this city? How does the physical environment affect urban species, and how do they, in turn, affect their environment? Students will develop proficiency in skills needed for the practice of biology, quantitative reasoning, and critical evaluation of scientific ideas and results. This course is an inquiry-based introduction to biological science in a format that includes both classroom activities and fieldwork. Field trips will occur during class time, with one required day-long field trip to be scheduled at the start of the semester.</p> <p><strong>Ecological Enhancement and Restoration</strong></p> <p>Biological, ecological, and social views regarding need, methods, and effects of restoration and enhancement of ecosystems. Recent events from California and the rest of the world are discussed, focusing on marine and terrestrial ecosystems, invasive species, over-harvesting, industrial impacts on the environment, and methods of mitigating or repairing damages. Examples of discussions include: methods of combating over-harvesting in the Pacific Ocean; natural and anthropogenic methods of recovering from forest fires; oil platforms functioning as artificial reefs to help endangered species thrive; also, how does a nuclear generating station affect a giant kelp forest, and what can be done to mitigate those damages?</p> <p><strong>Public Health Biology</strong></p> <p>This introductory course will offer an integrative biological perspective on public health issues, highlighting specific diseases of viral, bacterial, and environmental origin, as well as the influence of social and economic disparity. We will explore specific examples, such as rising antibiotic resistance, cholera and hepatitis outbreaks, cancer, and diabetes, to illustrate biological principles required to understand infectious and non-infectious diseases of public health importance.</p> <p><strong>Topics in Cancer Biology</strong></p> <p>This course will introduce students to the fundamentals of cancer biology. Topics will range from the biological origins of cancer to recent advances in diagnostics and therapeutics. Students will also be given a historical perspective of the bioethics surrounding cancer research and treatment. This course will highlight cutting edge research, with a focus on the detection and treatment of cancer in the age of personalized medicine.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7240,2021,26,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-105','<div class="desc"> <p>This course will be an introductory survey of marine organisms and their environment. It will cover fishes, invertebrates, mammals, reptiles, and algae. Included will be an investigation of behavior, ecology, adaptations, and environmental relationships to humans. An emphasis will be placed on forms common to California. <em>Includes one three-hour lab period per week; field trips will be included during the laboratory period. (Labs may take longer than the scheduled laboratory period to accommodate field trips.)</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7241,2021,28,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-106','<div class="desc"> <p>A component of the California Environmental Science Semester. Enrollment limited to first-year students enrolled in the California Environmental Science Semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7242,2021,30,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-110','<div class="desc"> <p>Principles and concepts of organismal structure and function, diversity, evolution, and ecology examined through case studies of organisms and their interactions with their environments. Emphasis will be placed on how organisms, from distinct biological groups, meet environmental challenges, such as: obtaining energy and nutrients, maintaining water and osmotic balances, reproducing, and finding a place to live. Students will learn to recognize and frame hypotheses about biological organisms and phenomena that can be tested (or falsified) by acquiring and analyzing appropriate evidence. Students will learn to acquire, analyze, and evaluate biological data through observation and experimentation in the laboratory and in the field. This course is designed for science majors and pre-health students; seniors may enroll by permission of instructor only. <em>Includes one three-hour laboratory per week.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7243,2021,32,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-115','<div class="desc"> <p>An introduction to the diversity, comparative anatomy, and physiology of animals. Emphasis is placed on the classification of animals, how animals are adapted to the environment, and the evolutionary relationships between the phyla. This class is designed for science majors. <em>Includes one three-hour laboratory per week.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7244,2021,34,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-130','<div class="desc"> <p>A concept-driven survey course designed to provide broad introduction to the biochemistry, physiology, and molecular biology of prokaryotic and eukaryotic cells. Topics include: structure/function; relationships of biological macromolecules; the roles of such molecules in cellular metabolism and membrane biology; molecular biology of DNA, RNA, and protein synthesis; the cell cycle; elementary genetics; and cellular communication. <em>Includes one three-hour laboratory per week. </em>Prerequisites may be taken concurrently with this course.</p> </div>','CHEM 120, CHEM 130 or permission of instructor ','BIO 130L ',NULL);
INSERT INTO course_descriptions VALUES(7245,2021,459,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-197','<div class="desc"> <p>Research in biology for students who do not have advanced competence in biology (see BIO 397). </p> </div>','Permission of instructor and department chair ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7246,2021,2868,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/100/bio-198','<div class="desc"> <p>Complementing their Oxy Immersive Semester coursework for the California Environment and Conservation Corps, students in the program will engage in service-learning. Students will be matched with Southern California environmental organizations. The hours spent in service (which will be completed virtually) would be scaffolded with reflective reading and writing centered around concepts of environmental stewardship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7247,2021,460,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-221','<div class="desc"> <p>This course focuses on understanding the processes in a cell, at a molecular level, that transfer information from genetic information through the expression of functional proteins. Topics include: basic structure of DNA, RNA, and proteins; gene structure; chromosomal organization; genomic structure and organization; DNA replication; transcription, translation, and processing of gene products; molecular regulation of gene expression, mechanisms in prokaryotes and eukaryotes; regulatory and catalytic RNA, including siRNA and miRNA; and the techniques to study these processes. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 and CHEM 220; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7248,2021,36,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-224','<div class="desc"> <p>Intensive concept-driven exploration of genetic information transfer between generations. Topics include: Mendelian principles, allelic and genetic interactions at the phenotypic level, complex traits, genetic mapping, DNA repair and genome maintenance, epigenetics, and principles of gene regulation. <em>Includes one three-hour laboratory session per week, plus 1-2 hours arranged.</em></p> </div>','CHEM 120; or CHEM 130 and BIO 130; or permission of instructor ','BIO 224L ',NULL);
INSERT INTO course_descriptions VALUES(7249,2021,1149,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-226','<div class="desc"> <p>A course designed to provide a thorough understanding of the intracellular processes of eukaryotic cells. The course will discuss topics including the molecular basis of cellular organization, structure, and function; cell motility; organelle biogenesis and function; cellular communication and signaling; and intracellular processes such as apoptosis and autophagy. <em>Includes one three-hour laboratory session per week, plus two hours arranged.</em></p> </div>','BIO 130 ','BIO 226L ',NULL);
INSERT INTO course_descriptions VALUES(7250,2021,813,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-240','<div class="desc"> <p>Physical and metabolic activities of cells and tissues, properties of the cellular environment, regulatory and homeostatic functions of organ systems. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 plus any other 100-level Biology course (except BIO 103) or permission of instructor (BIO 130 may be taken concurrently) ','BIO 240L ',NULL);
INSERT INTO course_descriptions VALUES(7251,2021,462,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-250','<div class="desc"> <p>This course is a comprehensive introduction to the plant kingdom, emphasizing the ways in which organismal form and structure are shaped through evolutionary and ecological processes. The primary goal of the course is for students to learn how a major life form has adapted to physical factors, such as light and water, and to biological factors, such as fungi, insects, and vertebrates. Labs involve experimental analysis of fundamental processes, such as: water uptake, photosynthesis, and hormonal regulation, as well as hands-on investigation of the vegetative and reproductive adaptations of the plant kingdom. Independent lab projects and field trips are also key components of the course. <em>Includes one three hour laboratory session per week.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 250L ',NULL);
INSERT INTO course_descriptions VALUES(7252,2021,38,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-260','<div class="desc"> <p>The goal of this course is to introduce marine ecosystems and the physical and biological attributes contributing to their organization. The course will focus on the nearshore marine environment of the Southern California Bight, referencing examples from comparable ecosystems. It will introduce basic physical attributes and the organisms of these dynamic ecosystems. Students will learn how to collect data, in both field and laboratory settings, database management, advanced database queries, conduct basic statistical analyses, test hypotheses, produce graphics, and write scientific papers. This course will serve to prepare students for focused upper division courses and independent research. Labs may take longer than the scheduled lab period to accommodate field trips. <em>Includes one three-hour laboratory session per week.</em></p> </div>','BIO 105, BIO 106, BIO 110, or BIO 115; or permission of instructor ','BIO 260L ',NULL);
INSERT INTO course_descriptions VALUES(7253,2021,1049,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-268','<div class="desc"> <p>The application of statistical methods to the solution of biological problems. Focus will be on applied statistics (as opposed to mathematical statistics) to study variation in nature. This course will survey descriptive statistics, probability and probability distributions, and methods of hypothesis testing (e.g. analysis of variance, regression correlation, goodness of fit, as well as selected nonparametric procedures). <em>Course includes laboratory workshops sessions.</em></p> </div>','BIO 130 and BIO 105, BIO 106, BIO 110 or BIO 115; or permission of instructor ','BIO 268L ',NULL);
INSERT INTO course_descriptions VALUES(7254,2021,464,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-270','<div class="desc"> <p>Ecology explores the interactions between organisms and their biotic and abiotic environments at a variety of spatial and temporal scales. Topics include: factors affecting organisms at the population, community, and ecosystem levels and the effect of human actions on natural systems. Practical aspects of studying ecology involve work in the laboratory, computer simulations and modeling, and field work. This course emphasizes the fundamentals of study, design sampling, field techniques, data analysis, and written and oral presentation of results. <em>Includes one three-hour laboratory per week and weekend field trips to be arranged.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 270L ',NULL);
INSERT INTO course_descriptions VALUES(7255,2021,1050,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-275','<div class="desc"> <p>Identification and classification of plants found in the various vegetational communities of Southern California, with emphasis on understanding their ecological and evolutionary affinities. Current methods of field sampling and systematic analysis will be employed. <em>Includes one three-hour laboratory per week and other field trips to be arranged.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 275L ',NULL);
INSERT INTO course_descriptions VALUES(7257,2021,40,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-280','<div class="desc"> <p>A detailed analysis of the causes and consequences of biological evolution. The focus, here, is on understanding basic evolutionary mechanisms with plant and animal examples used to illustrate and clarify the fundamentals of the evolutionary process. Classical and recent contributions to our understanding of evolutionary biology are examined, including: population genetics, theoretical models, geographical variation, speciation, biogeography, phylogeny, reconstruction, molecular evolution, macroevolution, and the evolution of Homo sapiens.</p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7258,2021,1002,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-290','<div class="desc"> <p>This two-unit course will offer students the opportunity to learn techniques of contemporary biology that are used in the laboratory and in the field. These may include: culture and handling of biological specimens, observational methods, imaging use of instrumentation to gather data, methods of data analysis, and identification of organisms. By the end of the semester, students will have been exposed to and gained practice in a diversity of techniques relevant to the practice of biological science. Graded on a credit/no credit basis only. May be repeated once for credit.</p> </div>',NULL,'CSP 14, BIO 103 (Urban Ecology), BIO 198 ',NULL);
INSERT INTO course_descriptions VALUES(7259,2021,3034,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/200/bio-295','<div class="desc"> <p>This one-unit course offers students the opportunity to learn about current research in the biological sciences. Students enrolled in the course will attend the weekly 1-hour seminar hosted by the Biology Department, which covers a broad range of biological research topics. Past speaker topics have included conservation biology and ecosystem restoration, climate change effects on marine ecosystems, evolution of social symbiosis, novel therapeutic approaches for drug resistant bacterial infections, evolution of flight, bioillustration, and scientific communication and education. Invited speakers from different institutions present their scientific work to students on a diversity of topics, techniques, and data analyses relevant to current biology research. This course provides students with an opportunity to observe how professional scientists communicate and translate their findings from biological studies to broad audiences.</p> <p>Graded on a CR/NC basis only. Course may be repeated once for credit. Open to sophomores and juniors only.</p> </div>','BIO 105/110/115 and BIO 130 (may be taken concurrently). ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7261,2021,41,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-310','<div class="desc"> <p>Introduction to the principles and practice of museology and the functioning of a research natural history museum. Emphasis will be on the development of the "museum conscience" and attendant curatorial skills, through extensive training as a curatorial assistant. Students will make use of the bird, mammal, and fish collections of the Moore Laboratory of Zoology (the world''s largest collections of Mexican birds and Southern California Rocky Reef fishes) and the Cosman Shell Collection at Occidental College. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7262,2021,893,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-320','<div class="desc"> <p>Animal development, with an emphasis on the molecular mechanisms that regulate cell fate, cell adhesion and motility, and the formation of different tissue types. Cell signaling pathways and gene regulatory mechanisms that control development, and are relevant to adult stem cell biology and cancer biology, are stressed throughout the course. The laboratory focuses on major invertebrate and vertebrate model organisms and both classical and molecular genetic approaches used to study animal development. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 and BIO 221, BIO 224, or BIO 226 ','BIO 320L ',NULL);
INSERT INTO course_descriptions VALUES(7263,2021,894,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-320l','<div class="desc"> <p>An introduction to classical and molecular methodologies used to study animal development. The laboratory focuses on early embryonic development of major invertebrate and vertebrate model organisms: sea urchins, C. elegans, zebrafish, and chick. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 320 ',NULL);
INSERT INTO course_descriptions VALUES(7264,2021,42,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-322','<div class="desc"> <p>Survey of the basic principles that power biological processes in all living organisms. Includes introduction to biochemical techniques, enzyme structure and function, intermediary metabolism, synthesis and degradation of biological macromolecules, information transfer, and a concept-driven integration of these subjects into a biological context. This course meets the Biochemistry requirements for most graduate and professional schools. <em>Includes one three-hour laboratory per week. </em>Not open to students who have successfully completed Biology 349.</p> </div>','Biology 130 and Chemistry 220, or permission of instructor ','BIO 322L ',NULL);
INSERT INTO course_descriptions VALUES(7265,2021,43,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-322l','<div class="desc"> <p>The application of techniques to study protein structure and function, including protein purification, column chromatography, enzyme kinetics, crystallography, and computer-aided structural analysis.</p> </div>',NULL,'BIO 322 ',NULL);
INSERT INTO course_descriptions VALUES(7266,2021,466,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-323','<div class="desc"> <p>An introduction to histology. Lectures present the structure and function of cells, tissues, and organs in healthy and diseased conditions. The laboratory introduces students to preparation of tissue for paraffin, plastic, and cryostat sectioning and examination by light and electron microscopy. Students work on projects of their own choice. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 and BIO 105 or BIO 115 ','BIO 323L ',NULL);
INSERT INTO course_descriptions VALUES(7267,2021,467,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-323l','<div class="desc"> <p>Laboratory techniques in histology. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 323 ',NULL);
INSERT INTO course_descriptions VALUES(7268,2021,468,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-325','<div class="desc"> <p>An introduction to the world of microbes, including viruses, archaea and bacteria, and their role in shaping and sustaining life on Earth. Emphases will be placed on structure, metabolism and bioenergetics, physiological and biochemical adaptations to unusual environments, phylogenetic analysis, biotechnology, microbial ecology, and biological interactions, including plant and animal symbioses. Laboratory exercises will include an exploration of microscopy, cultivation, biochemical techniques, and molecular tools for studying microorganisms. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 221, BIO 222, BIO 224 , BIO 270, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7269,2021,469,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-325l','<div class="desc"> <p>Students will examine microbial growth, form, and function, and will select familiar environments from which to investigate microbial life. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 325 ',NULL);
INSERT INTO course_descriptions VALUES(7270,2021,1107,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-326l','<div class="desc"> <p>Laboratory sessions will involve hands-on generation of DNA data in the molecular lab as well as its analysis via a broad suite of modern software. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7271,2021,44,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-330','<div class="desc"> <p>Introduction to current concepts of immunology, including immunoglobulin structure and function, T cells and B cells, cell-cell cooperation in the immune response, and the role of the major histocompatibility complex. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221, BIO 224, BIO 226, or permission of instructor ','BIO 330L',NULL);
INSERT INTO course_descriptions VALUES(7272,2021,45,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-330l','<div class="desc"> <p>Introduction to essential immunological techniques, including immunization and immunoassay, such as ELISA; generation of hybridomas and screening and characterizing monoclonal antibodies; and introduction to other techniques, such as FACS. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 330 ',NULL);
INSERT INTO course_descriptions VALUES(7273,2021,815,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-333','<div class="desc"> <p>Emphasis on cell biology and phsyiology of neurons. Development and plasticity of the nervous system in invertebrates and vertebrates. Overview of selected central nervous system structures and their function and the cellular and molecular basis of selected nervous system diseases and disorders. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130; and BIO 240 or BIO 226 ','BIO 333L',NULL);
INSERT INTO course_descriptions VALUES(7274,2021,816,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-333l','<div class="desc"> <p>Laboratory techniques in neurobiology. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 333 ',NULL);
INSERT INTO course_descriptions VALUES(7275,2021,1367,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-336','<div class="desc"> <p>This course will examine interactions between the human host and infectious microbial pathogens, including bacteria, parasites, viruses, and fungi. Emphases will be placed on mechanisms of microbial defense (virulence factors), immune evasion and adaptation strategies, as well as the molecular and cellular mechanisms of the innate (immediate) response of the host in both immune and non-immune cells. Laboratory includes techniques used in clinical microbiology labs, including culture and identification techniques, as well as cell biology techniques. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221, BIO 224, BIO 226, or permission of instructor ','BIO 336 ',NULL);
INSERT INTO course_descriptions VALUES(7276,2021,1368,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-336l','<div class="desc"> <p>Laboratory includes techniques used in clinical microbiology labs, including culture and identification techniques, as well as cell biology techniques. Graded on a Credit/No Credit basis.</p> </div>',NULL,'BIO 336',NULL);
INSERT INTO course_descriptions VALUES(7277,2021,470,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-340','<div class="desc"> <p>Dynamic physiological properties will be examined in single cells, tissues, and whole organisms. Emphasis will be placed on sensory physiology and neuroethology (study of the neural basis of natural animal behaviors). Laboratories will utilize advanced recording techniques, including microelectrodes, isometric tension measurements, semi-intact preparations, and modern electronics.</p> </div>','One of the following: BIO 226, BIO 240, BIO 333, CHEM 301, COGS 250, PSYC 312, PSYC 322, PSYC 403; or permission of instructor ','BIO 340L',NULL);
INSERT INTO course_descriptions VALUES(7278,2021,471,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-340l','<div class="desc"> <p>Fundamental physiological processes will be investigated using advanced recording techniques, including microelectrodes, isometric tension measurements, semi-intact preparations, and modern electronics. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 340 ',NULL);
INSERT INTO course_descriptions VALUES(7279,2021,1052,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-344','<div class="desc"> <p>The structure and functional organization of animal-like protists and invertebrates are examined as adaptations to life in specific habitats. The current use of these organisms in applied systems, such as aquaculture, and as models to study basic biological processes is discussed. Marine organisms and parasites are emphasized. The phylogenetic relationships between taxa are also debated. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130; and BIO 105 or BIO 115; or permission of instructor ','BIO 344L ',NULL);
INSERT INTO course_descriptions VALUES(7280,2021,1053,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-344l','<div class="desc"> <p>Field and laboratory exercises designed to: (1) further expose students to invertebrate diversity; (2) examine and experiment with physiological processes such as locomotion, nutrient allocation, excretion, sensory function, and reproduction; (3) introduce parasite life cycles and parasite-host interactions; and (4) understand animal relationships based on morphological and molecular evidence. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 344 ',NULL);
INSERT INTO course_descriptions VALUES(7281,2021,2870,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-345','<div class="desc"> <p>This course will survey the diversity among major classes of viruses in genomic material, replication, and host cell interaction. We will discuss aspects of antiviral strategies by the host immune response as well as ongoing research in medical antiviral therapies. In addition we will cover various ways that viruses have been harnessed as useful tools in the laboratory as sources of unique enzymes, vectors for introducing exogenous material into cells, and in various other applications such as phage display.</p> </div>','Bio 130 and either BIO 221, BIO 224, or BIO 226 ','BIO345L ',NULL);
INSERT INTO course_descriptions VALUES(7282,2021,2871,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-345l','<div class="desc"> Laboratory techniques in virology. Graded on a Credit/No Credit basis only. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7283,2021,1003,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-349','<div class="desc"> <p>This course explores the roles of the essential biological macromolecules, focusing on proteins, while covering lipids, carbohydrates, and nucleic acids. Topics include the structure and function of these macromolecules, as well as an investigation of the biochemical methods used to study them. Also included are topics covering proteomics, DNA-based information technologies, biosignaling, and an introduction to enzyme kinetics. This course is the first in a two-semester sequence of Biochemistry classes (with CHEM 350) that is required for Biochemistry majors. For a one semester Biochemistry class, see BIO 322.</p> </div>','BIO 130 and CHEM 220; or permission of instructor. Not open to students who have successfully completed BIO 322. ','BIO 349L ',NULL);
INSERT INTO course_descriptions VALUES(7284,2021,1004,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-349l','<div class="desc"> <p>The application of techniques to study protein structure and function, including protein purification, column chromatography, enzyme kinetics, crystallography, and computer-aided structural analysis.</p> </div>',NULL,'BIO 349',NULL);
INSERT INTO course_descriptions VALUES(7285,2021,895,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-350','<div class="desc"> <p>Symbioses are intimate associations involving two or more species. Symbiotic associations are widespread in nature and we can expect to find them in every type of ecological niche. This course will cover the diversity of symbiotic interactions that exist between both microbes and fungi and various eukaryotic hosts, including plants, animals, and protists, as well as other microorganisms. Topics in both lecture and lab will range from molecular to ecological, including the specific molecular communication between partners, the evolution of unusual host structures, novel physiological and biochemical capabilities, and the unique ecological advantages that many symbioses confer. This course will also include writing, presenting, and reviewing published work on various symbioses.</p> </div>','BIO 130 and BIO 105, BIO 106, BIO 110, or BIO 115; or permission of instructor ','BIO 350L ',NULL);
INSERT INTO course_descriptions VALUES(7286,2021,896,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-350l','<div class="desc"> <p>Students will investigate the presence of bacterial symbionts within animals, plants, and protists using molecular and microscopic techniques. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 350',NULL);
INSERT INTO course_descriptions VALUES(7287,2021,897,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-356','<div class="desc"> <p>The biology of marine fishes begins with a study of the phylogenetic evolution of fishes. Within this context, it discusses the physiology, ecology, and behavior of marine fishes, utilizing examples from our local fauna. Advanced methods of studying marine fishes will be covered, with an emphasis on field research in which the class will visit various marine habitats throughout Southern California. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 240, BIO 250, BIO 260, BIO 268, BIO 270, BIO 275, or BIO 280; or permission of instructor ','BIO 356L ',NULL);
INSERT INTO course_descriptions VALUES(7288,2021,898,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-356l','<div class="desc"> <p>Laboratory techniques in marine fishes. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 356 ',NULL);
INSERT INTO course_descriptions VALUES(7289,2021,1054,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-360','<div class="desc"> <p>Avian Biology is the study of birds, with particular emphasis on identification, natural history, and evolution of birds local to Southern California.</p> </div>','BIO 130 and BIO 105, BIO 106, BIO 110, or BIO 115 ','BIO 360L ',NULL);
INSERT INTO course_descriptions VALUES(7290,2021,1055,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-360l','<div class="desc"> <p>Laboratory techniques in Avian Biology. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 360',NULL);
INSERT INTO course_descriptions VALUES(7291,2021,472,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-369','<div class="desc"> <p>Biological oceanography will focus on the biology of the open ocean, with emphasis placed on relating parameters of the physical-chemical ocean to the distribution and abundance of marine organisms. We will focus on understanding the physical and biological processes of the Southern California marine area using field and laboratory techniques. Using examples from our local ecosystem, students will explore the intricacies of macro-scale oceanographic processes. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 260, BIO 270, or permission of instructor ','BIO 369L ',NULL);
INSERT INTO course_descriptions VALUES(7292,2021,473,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-369l','<div class="desc"> <p>Laboratory techniques in Oceanography. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 369 ',NULL);
INSERT INTO course_descriptions VALUES(7293,2021,1322,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-370','<div class="desc"> <p>This course addresses contemporary approaches to ecology and conservation, with emphasis on ecological fieldwork in diverse locations. The course will have a regional focus, with the possibility of emphasis on desert, mountain, coastal, or tropical ecosystems. Students will conduct field research, including the design, implementation, data analysis, and presentation of research projects. Emphasis will be placed on the impacts of anthropogenic change on native ecosystems. </p> <p>This class has been designed to allow for meaningful field study in the region. Each section of this class meets for one full day per week to allow for fieldwork. The course will include overnight field trips, including several extended trips on weekends and outside of class hours. Two extended field trips will occur over fall and January breaks.</p> </div>','BIO 260, BIO 270, GEO 225, or permission of instructor ','BIO 370L ',NULL);
INSERT INTO course_descriptions VALUES(7294,2021,1323,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-370l','<div class="desc"> <p>The goal of the lab portion of this course is to enable students to conduct immersive field research on the ecology of natural systems. Contemporary techniques and tools will be used to monitor and assess biodiversity of natural communities and the extent of anthropogenic impact on these systems. Field trips will be conducted outside of assigned class times. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 370',NULL);
INSERT INTO course_descriptions VALUES(7295,2021,2323,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-373','<div class="desc"> <p>This course is an opportunity for students to learn more advanced methodologies in computational biology. By examining a variety of biological questions that are often addressed with computational pipelines, modeling, or simulation, students will get in-depth experience with important computational concepts (including: abstraction, algorithms, automation, logic, and problem solving). This includes the study of complex biological systems, such as projecting biological responses to climate or ecosystem change, quantifying spatial biodiversity hotspots, evaluating time series data for populations, and computing evolutionary parameters from genomic datasets. Students will also get experience with computer programming in the R statistical language and Python. Additional biological topics may include: spatial ecology, including species distribution modeling, community assemblage and dissimilarity matrices, population simulations, classification with machine learning, and bioinformatics with genomic data. Course includes laboratory workshops sessions.<strong></strong></p> </div>','BIO 268, COMP 131, MATH 150, COGS 255, GEO 255, PSYC 201, or permission of instructor ','BIO 373L ',NULL);
INSERT INTO course_descriptions VALUES(7296,2021,2672,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-373l','<div class="desc"> <p>Laboratory workshops for Computational Biology (BIO 373). Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 373 ',NULL);
INSERT INTO course_descriptions VALUES(7297,2021,46,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-378','<div class="desc"> <p>Emphasizes the evolutionary approach to the study of animal behavior, drawing broadly from the various disciplines within biology concerned with the factors that determine which organisms survive and reproduce. The course material will be divided into four broad categories: sensory capabilities, feeding patterns, spacing patterns, and reproduction. For each topic, theory and application will be presented. Students will analyze research papers and lead discussions on an aspect of each major topic. The laboratory portion of the course will focus on observational and experimental approaches to studying animal behavior in the lab and in the field. We will make use of local resources, such as zoos, aquaria, wildlife conservation areas, veterinarians, and animal rehabilitation facilities. An independent research project is required. This course is designed for Biology majors, although it would be appropriate for students from other majors. <em>Includes one three-hour laboratory per week and weekend field trips to be announced.</em></p> </div>','Any 100-level Biology course (except BIO 103) or permission of instructor ','BIO 378L ',NULL);
INSERT INTO course_descriptions VALUES(7298,2021,47,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-378l','<div class="desc"> <p>Laboratory techniques in Animal Behavior. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 378 ',NULL);
INSERT INTO course_descriptions VALUES(7299,2021,899,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-380','<div class="desc"> <p>An investigation of physiological processes in plants, including photosynthesis; nutrient uptake and water relations and how they are affected by environmental conditions; and interactions with other organisms, including insects, vertebrates, and fungi. The emphasis will be on how to quantify and predict plant physiological responses to the particular ecological pressures of Southern California. Classroom discussions and presentations will focus on papers from the current scientific literature. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 250 or permission of instructor ','BIO 380L ',NULL);
INSERT INTO course_descriptions VALUES(7300,2021,900,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-380l','<div class="desc"> <p>Instruction in contemporary physiological and environmental diagnostic instrumentation and analytical methods will be followed by independent investigations in the laboratory and field. Day-long and overnight field trips will be scheduled. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'BIO 380 ',NULL);
INSERT INTO course_descriptions VALUES(7301,2021,2375,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-390','<div class="desc"> <p>This seminar course will teach students skills needed to read and critically analyze original journal articles. Some lectures will be given, but the bulk of the course will consist of student-led discussions and analysis of scientific papers. Students will improve their communication skills by discussing papers and leading discussions, by writing a research paper and peer-editing, and by preparing PowerPoint presentations as an aid for leading discussions. May be taken more than once for credit as the topics will differ each semester, but can only be used to fulfill one of the requirements for the Biology major. Cannot be used to fill the Biology requirement of the Biochemistry major.</p> <p><strong>The Broader Impacts of Biology</strong></p> <p>This seminar course will explore the broader societal impacts of the biological sciences. Science is an endeavor that aims to categorically build knowledge about the universe in an objective manner. But our science not only informs society, it is also shaped by the needs and structure of our society. In this class, students will explore the potential societal impacts and determinants of their scientific interests through careful exploration of the literature. Through this exploration, students will learn to lead discussions about the intersections between science and society, critically evaluate the role of science in society, and develop skills in both oral and written scientific communication. Students will work with the professor to lead a discussion on a topic of their choice and will learn to write a “broader impacts” section of a scientific grant, detailing how the science extends beyond the boundaries of the specific scientific endeavor to affect society. Each week we will explore a research topic in the scientific literature and accompanying literature on the societal impacts/determinants of that research. Example topics: Climate Justice and Global Change Biology, Environmental Justice and Urban Ecology, Biological Property Rights and Cancer Research, Anti-Racism in the Biological Sciences, Indigenous Rights and Ethnobiology, Social Equity in Human Health, and Microbiology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7302,2021,2863,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-393','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>The Biology and Epidemiology of COVID-19</strong></p> <p>How did COVID-19 come to ravage the world and bring it to its knees in just a few months? What is happening now, and what will happen next? As of mid July, 2020, there were over 13 million cases of COVID-19 worldwide, and 570,000 deaths (World Health Organization). Over 3.2 million of those cases and 135,000 deaths were in the United States. All of these numbers are increasing. Students in this class have the unique opportunity to study this pandemic as it is happening. Topics will include the biology of the SARS-CoV-2 virus, the COVID-19 disease, and factors that affect the outcome of the disease. Testing and vaccine development will be covered. The epidemiology of the disease will be discussed, including the disproportionate effects of the disease in people of color. </p> </div>','BIO 221, BIO 224, BIO 226, BIO 322, or Bio 349. Statistics course preferred but not required. ','BIO 393L ',NULL);
INSERT INTO course_descriptions VALUES(7303,2021,2864,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-393l','<div class="desc"> <p>Topics vary semester by semester. </p> <p><strong>The Biology and Epidemiology of COVID-19 Laboratory</strong></p> <p>The lab portion of the class will include learning techniques involved in COVID-19 diagnosis and screening, plus projects on topics such as data analysis of anonymous patient test results, vaccine development, and therapeutic approaches.</p> </div>',NULL,'BIO 393 ',NULL);
INSERT INTO course_descriptions VALUES(7304,2021,48,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-395','<div class="desc"> <p>Research for approximately five hours per week for students to study in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7305,2021,474,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/bio-397','<div class="desc"> <p>Directed research with individual faculty members for students with advanced competency to study in an area not otherwise included in the departmental curriculum. In addition to topics that may be studied on the Occidental campus, courses offered at the marine station of the Wrigley Institute for Environmental Studies may be taken for credit under this course number. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7306,2021,1106,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/300/copy-of-bio-326','<div class="desc"> <p>This course focuses on how to build the tree of life from DNA data, from how DNA evolves to how DNA mutations are analyzed to create phylogenies. Topics covered include the theory behind molecular evolution and various analytical methods, as well as its application to creating evolutionary histories of genes and organisms. </p> </div>','BIO 280 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7307,2021,49,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/400/bio-490','<div class="desc"> <p>Topics of these seminars will be announced at Spring pre-registration. Each senior must pass one seminar for the Comprehensive requirement. Each seminar meets two hours per week with extensive reading, discussion, and a major oral presentation by each student.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7309,2021,475,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/400/bio-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7310,2021,476,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/500/bio-501','<div class="desc"> <p>Supervised investigation by properly qualified graduate students working toward a Master''s degree. Students may not register for more than two courses of Research during any semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7311,2021,50,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/500/bio-590','<div class="desc"> <p>Preparation of the Master''s thesis in consultation with the advisor and committee members. Department approval required.</p> </div>','At least two courses of BIO 501 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7314,2021,479,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bio-biology/500/bio-599','<div class="desc"> <p>Continuing work on Master''s thesis. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7315,2021,2872,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/100/blst-101','<div class="desc"> <p>This course introduces students to the history and methods of the discipline known as Black Studies. Readings will focus on the origins and institutionalization of Black Studies as a field of academic inquiry. Students will learn about the philosophical and political debates that laid the intellectual foundation for Black Studies and examine the social movements that resulted in the field of Black Studies in the present. Topics include the foundational academic work of W.E.B. DuBois, the San Francisco State student revolt of 1968, Mellon and Ford Foundation funding of programs and departments, and the recent student demands at University of Missouri and elsewhere. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7316,2021,2778,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/100/blst-104','<div class="desc"> <p>This course surveys the musical styles and genres of the African continent and the Middle Eastern world. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7318,2021,2852,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/100/copy-of-blst-105','<div class="desc"> <p>This course surveys music of African Americans with an emphasis on 20th century classical and vernacular genres. We will examine this musical web in three units: Classical Jazz &amp; Blues and Rock &amp; Contemporary Vernaculars. Featured artists include William Grant, Still Marian Anderson, Margaret Bonds, Duke Ellington, Fats Waller, Big Mama Thornton, Sam Cooke, The Five Blind Boys of Alabama, Motown Stax Records and Atlantic Records, Jimi Hendrix, Sweet Honey in the Rock, and Mos Def. Through extensive listening reading and group dialogue this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7319,2021,2732,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/100/copy-of-blst-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7321,2021,2844,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of forced African migrants to North America to the black quest for freedom in the twentieth century United States. With our focus on significant demographic, institutional, cultural, and political developments within African American communities, we will explore key themes and watershed moments in the African American experience: from slavery to emancipation, from rural to urban, and from the civil rights and black power movements of the twentieth century to the ongoing struggle for social justice. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of black Americans and the history of the United States. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7322,2021,2725,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-215','<div class="desc"> <p>This course critically examines the history of the education of Africans in the United States, beginning at the Middle Passage, through Reconstruction and the post-bellum South, to contemporary post-industrial urban contexts. Emphasizing the sociohistorical and political-economic dimensions of schooling African Americans, the course explores the role of key factors in shaping the academic "success" and "failure" of Black students historically and in current K-16 contexts. Analysis of case law policy and practice will inform our understanding of African American experiences in schools nationally and locally. Further, we consider the implications these experiences hold for democratic participation and the overall life chances of African American citizens.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7323,2021,2780,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-234','<div class="desc"> <p>This course examines the political dynamics of apartheid and post-apartheid South Africa. Particular emphasis is placed on the development of black political opposition since the 1970''s, including both militant action against the state, as well as inter-ethnic political action and violence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7326,2021,2584,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with, what is known as, the "LA Rebellion," a moment of a radical reconceptualization of filmmaking fostered by black students during their studies at the UCLA film school, and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasional devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include: <em>Selma</em>, <em>Fruitvale Station</em>, <em>Daughters of the Dust</em>, <em>Lemonade</em>, <em>Pariah</em>, <em>Bush Mama</em>, <em>Do the Right Thing</em>, and <em>An Oversimplification of Her Beauty.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7328,2021,2611,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7330,2021,2726,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-259','<div class="desc"> <p>Students will use the United States and Brazil as sites of comparison through which to understand the various relationships between religion and race in the Americas. In both places we will ask: Where can we find African religion in the Americas? How have religious practitioners, scholars, and even entertainers decided what is "authentically African," and to what ends? And how has religion - and the social scientific study of it - served as an arena for negotiating racial and ethnic difference? By the end of the class, students will emerge with an understanding of different black religious traditions across the Americas - ranging from black Islam and Christianity in the U.S., to transnational Santeria, to Brazilian Candomble and Umbanda- as well as what is at stake in defining a category like "black religion." Students will understand how scholars have studied these traditions over time and how practitioners and scholars'' notions notions of black religion have shaped contemporary understandings of race and ethnicity in the Americas.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7331,2021,2613,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7332,2021,2733,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/blst-277','<div class="desc"> <p>This course explores the history of women as promoters of community health in the nineteenth- and twentieth-century United States. Although women have not traditionally held power in mainstream biomedical occupations and institutions, women have nevertheless been critical to health and healing in local communities as caregivers, activists, and practitioners. At times, working class women and women of color have also been demonized as carriers of contagion or even romanticized as repositories of traditional wisdom. Furthermore, women’s roles in community health have been heavily shaped by gendered and racial constructions of the body, disease, and wellbeing. Thus, while the focus of the course is on the social history of women’s health and healing, the theoretical framework of the course also aims to explore how ideologies of gender, race, class, and sexuality shape women’s relationship to community health as both caregivers and health-seekers. The course is organized by a set of common themes that cut across time, space, and racial/ethnic boundaries in U.S. History. Themes include: spirituality and healing; work and health; sexuality and reproduction; activism for health justice. An important goal of this course is to make connections between historical studies of women and health and present day community health activism. Much of the course and especially the community partnership component focuses on the leadership of women of color in shaping agendas for community well-being. In the past, course participants have worked with the organizations Black Women for Wellness, California Latinas for Reproductive Justice, Visión y Compromiso, and Promesa Boyle Heights. We will continue to work this year with women’s health organizations and the Southern California Library on a Reproductive Justice community partnership. In addition, we will welcome several community health activists &amp; scholars to the class as guest speakers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7335,2021,2685,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/200/copy-of-blst-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7336,2021,2873,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-302','<div class="desc"> <p>In this course, students will explore mediumship and exorcism practices in the Atlantic World from the early modern period to today. Through case studies—including Haitian Vodou in Brooklyn, Brazilian Umbanda and Candomblé, Cuban Palo Monte, Santería in Chicago, Yorùbá and Igbo traditions in West Africa, North American Spiritualism, and Catholic Exorcism in France—we will take a broad look at the different ritual practices that fall under the academic category of “spirit possession.” We will consider why practitioners channel the spirits of the dead and what it means to be possessed. We will read scholarly studies that analyze what spirit possession has to do with race, gender, and sexuality. Finally, we will interrogate contemporary western scholarship itself, asking: Why have outsiders commonly described the spirits’ presence in terms of “possession”—a term rarely used by practitioners themselves—and how does the trope of the possessed person serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7337,2021,2874,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-309','<div class="desc"> <p>This course examines the southern region of the antebellum United States as a "slave society," that is, a society in which slavery was central to the region''s economy, and in which a powerful slaveholding minority held the reigns of political power. We will examine the rise of a "peculiar" institution of Southern slavery, and the impact of chattel slavery on southern households, political institutions, and cultural practices. How did the institution of slavery shape the lives of Southerners differently, depending on race, class, gender, and geography? In what ways did the centrality of an institutionalized system of human property shape the social relations and lived experiences of enslaved African Americans, common whites, slaveholding planters, and Native Americans of the South? How did these groups of Southerners draw upon religion, violence, and ideologies of sex and race both to challenge and reinforce the Southern social order? Finally, what did the South, as a region, come to mean to other antebellum Americans as sectional conflicts heightened in the 1850''s? Students will explore the social and cultural history of the antebellum South through primary documents, first-person narratives, film, fiction, music, and extensive secondary scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7338,2021,2727,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-312','<div class="desc"> <p>The circulation of labor goods people and cultures between Africa Europe and the Americas created an Atlantic World whose history transcends continental and national boundaries. This course examines the relationship between race rights and revolution during the Atlantic Age of Revolution that stretched from roughly the mid-eighteen to mid-nineteenth centuries. In particular we will explore how Revolutions in British North America France and Haiti influenced the movement to end the slave trade and slavery in the Americas and galvanized slave revolts and other movements for Black liberation and human rights around the Atlantic World. A variety of readings including autobiography social and political history and ethnography will illuminate not only the history of the Atlantic World but new forms of scholarly writing that break the mold of national historical narratives. Themes include: slavery slave revolt the discourse of human rights resistance religion labor and shifting ideologies of difference in particular gender class and race.</p> </div>','One History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7339,2021,2734,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-320','<div class="desc"> <p>Critical Race Theory (CRT) is a historic movement among legal scholars of color in the U.S. that has enjoyed widespread application in a number of disciplines, including Education. This course introduces students to CRT through a close reading of the key writings that formed the movement. We will examine the application of CRT in education, research, theory, and practice, contextualized in a variety of settings, including schools, community-based organizations, and other relevant spaces. Specific attention will be paid to the CRT methodology of counter-storytelling and its utility in centering the experiential knowledge of people of color in education.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7340,2021,2875,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-346','<div class="desc"> <p>This course thinks through current debates over the relationship between literary aesthetics and harmony in American democracy. Do aesthetics foster a more harmonious or disharmonious national culture? Is disharmony ever important to progress? How does literature represent protests for social change that are often only possible outside the law, like the many freedmen and freedwomen escaping slavery and demanding the destruction of that system? How does this alter our understandings of what it means to be a fugitive? How can the fugitive fighting for freedom be distinguished from the unprincipled outlaw? From another perspective, we will consider how the complications of American society have altered certain traditional literary forms. While recent scholarship has addressed these questions in regards to early- to mid-20th century literature, this course will look back further, starting from the early 19th century to the very beginning of the 20th. We will complement the literature by reading relevant historical materials from the abolitionist movement, labor movements, government debates over Emancipation and Reconstruction, etc. The course will include literature from Frederick Douglass, Sojourner Truth, Walt Whitman, Ida B Wells, and Charles Chesnutt, amongst others, and will cover several genres, including: oratory, autobiography, political pamphlets, and short fiction. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7341,2021,2542,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. Open to sophomores, juniors, and seniors only.</p> </div>','POLS 101, BLST 110, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7344,2021,2615,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-376','<div class="desc"> <p>This interdisciplinary seminar will explore the contentious history of the public memory and representation of slavery, the Old South, and emancipation in the United States. Drawing upon a range of sources – including fiction, film, advertisements, tourist sites, and public monuments – we will examine the various ways that Americans have sought to commemorate, critique, and capitalize on the history of the nation’s “peculiar institution” from the late-nineteenth century to the present day. Throughout the semester, we will interrogate the contested politics of these popular representations, and we will assess the ways that African American writers, filmmakers, preservationists, and artists have sought to challenge and reframe longstanding Jim Crow-era representations of slavery, replacing them with new narratives informed both by historiographical paradigm shifts and the politics of the ongoing black freedom struggle. </p> </div>','One HIST course, or one BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7345,2021,2782,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/300/blst-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. Major requirement met: Group III/IV.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7348,2021,2543,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/blst-black-studies/400/blst-490','<div class="desc"> <p>During the spring semester, students will complete a 25-page research paper on a topic relevant to Black Studies. The project will be based on original analysis of primary sources and grounded in the scholarly literature on the subject. Seminar meetings will be devoted to discussion of selected texts on research methods in Black Studies and ongoing review of students’ work-in-progress. The seminar will conclude with student presentations that will be open to the entire campus community. </p> </div>','BLST 110 and the BLST Second-Stage Writing Requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7350,2021,2730,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/bosp-barack-obama-scholars-program/200/bosp-200','<div class="desc"> <p>The aim of the Obama Scholars Program Seminar is to help Obama Scholars and Fellow develop and pursue their own conception of the public good, with the guidance of a faculty mentor and the support of members of their cohort. Participation in the seminar involves discussing selected texts and films; attending public lectures and other events; meeting with people at Oxy and beyond who serve the public good in various ways; and, in some cases, participating in community engagement projects. Permission of instructor required.</p> <p>This seminar is open only to Scholars and Fellows in the Obama Scholars Program. Students may repeat the seminar for credit, as long as they remain Obama Scholars or Fellows. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7351,2021,51,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/100/chem-100','<div class="desc"> <p>Develop the skills necessary for a satisfactory introduction to general chemistry.</p> </div>','Open only for first year frosh with successful completion of a placement examination. Others only with permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7352,2021,52,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/100/chem-104','<div class="desc"> <p>This is a course suitable for non-majors and covers the chemical bases of life. The course will be structured around the chemistry of the fundamental building blocks of life - nucleic acids, proteins, polysaccharides, etc. - and how they interact to support the cellular life. Examples of the specific topics include the evolution of the human genome.</p> </div>','One high school science course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7353,2021,53,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/100/chem-120','<div class="desc"> <p>An introduction to the primary chemical concepts of atomic structure and quantum theory, periodic trends, molecular structure, chemical kinetics, equilibrium thermodynamics, and acids and bases. <em>Includes one three-hour laboratory per week.</em></p> </div>','Satisfactory performance on the Chemistry Placement Examination, or completion of Fall CSP, or permission of instructor ','CHEM 120L ',NULL);
INSERT INTO course_descriptions VALUES(7354,2021,55,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/100/chem-130','<div class="desc"> <p>An advanced presentation of topics in atomic structure, periodic trends, molecular structure, molecular symmetry, and vibrational spectroscopy. <em>Includes one three-hour laboratory per week.</em></p> </div>','AP Chemistry score of 4 or 5; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7355,2021,901,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/100/chem-150','<div class="desc"> <p>Symmetry is a fundamental unifying aspect of nature and is found in many human creations, from art, music, and architecture, to mathematics and science. In chemistry, symmetry is central to understanding the interplay of molecular architecture and function. This course provides the student with a qualitative and formal conceptual framework for categorizing molecular structures.</p> </div>','CHEM 100, CHEM 120, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7356,2021,57,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/100/chem-195','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7358,2021,1572,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/200/chem-201','<div class="desc"> <p>Intensive study of the modern laboratory methods of analysis, with applications to biochemical and environmental systems.</p> </div>','CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7360,2021,58,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/200/chem-220','<div class="desc"> <p>Introduction to the fundamental concepts of organic chemistry. The course explores the properties and structures of carbon-based molecules, and focuses on how these factors influence their reactivity. Special emphasis is placed on biologically relevant organic transformations, as well as the prevalence of organic chemistry in everyday lives. Includes one three-hour laboratory that focuses on the practical techniques employed when conducting reactions and purifying organic molecules.</p> </div>','CHEM 120, CHEM 130, or permission of instructor ','CHEM 220L ',NULL);
INSERT INTO course_descriptions VALUES(7361,2021,60,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/200/chem-221','<div class="desc"> <p></p><p>Continuation of Organic Chemistry I. The course focuses on the reactivity of organic molecules, including molecules and reactions with biological relevance. Special emphasis is placed on mechanism and employing chemical reactions to develop strategies for multistep synthesis. Includes one three-hour laboratory that applies the techniques of organic chemistry to the synthesis of interesting organic molecules.</p><p></p> </div>','CHEM 220 ','CHEM 221L ',NULL);
INSERT INTO course_descriptions VALUES(7362,2021,481,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/200/chem-240','<div class="desc"> <p>Building on concepts developed in prerequisite classes, fundamental concepts in thermodynamics are developed from first principles, with subsequent application in chemical equilibrium and kinetics. Applications to biological systems and technology are emphasized. The substantive laboratory component focuses on developing analytical skills.</p> </div>','CHEM 120 or CHEM 130 ','CHEM 240L ',NULL);
INSERT INTO course_descriptions VALUES(7363,2021,483,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/200/chem-280','<div class="desc"> <p>The course will explore the application of 1H, 13C, and two-dimensional NMR spectroscopy to the organic laboratory, as well as the important separation protocols such as: column chromatography, gas chromatography, and chiral HPLC. <em>Includes one three hour laboratory per week.</em></p> </div>','CHEM 221 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7364,2021,62,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/200/chem-295','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7366,2021,63,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-300','<div class="desc"> <p>An introduction to the principles of chemical thermodynamics and kinetics and their application to chemical systems.</p> </div>','Calculus 2, and PHYS 120 or PHYS 125; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7367,2021,64,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-300l','<div class="desc"> <p>Applications of chemical thermodynamics and kinetics. <em>One three-hour laboratory per week.</em></p> </div>','CHEM 300 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7368,2021,1369,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-301','<div class="desc"> <p>An introduction to the principles of chemical thermodynamics, kinetics, and spectroscopy, with a focus on applications to biochemical systems.</p> </div>','CHEM 221, Calculus 2, and PHYS 115 (or equivalents) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7369,2021,902,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-305','<div class="desc"> <p>An introduction to quantum mechanics, atomic and molecular structure, spectroscopy, statistical thermodynamics, kinetic molecular theory, and chemical applications of group theory.</p> </div>','CHEM 130 or CHEM 150, Calculus 2, and PHYS 120 or PHYS 125; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7370,2021,903,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-305l','<div class="desc"> <p>Atomic and molecular spectroscopy and modern techniques in physical chemistry. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 305 ',NULL);
INSERT INTO course_descriptions VALUES(7371,2021,1438,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-315','<div class="desc"> <p>An introduction to the study of kinetic molecular theory and chemical kinetics.</p> </div>','MATH 120 and PHYS 120; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7373,2021,904,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-332','<div class="desc"> <p>Modern analytical instrumentation provides scientists and engineers with an impressive array of powerful tools for studying the composition and structure of matter, from the first electronic pH meter, to advanced three-dimensional MRI imaging spectrometers, to portable detectors explosive compounds. This course examines the statistical, electronic, physical, and chemical requirements for the construction and operation of modern analytical instruments.</p> </div>','CHEM 300 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7375,2021,65,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-340','<div class="desc"> <p>Application of modern theories of physics and chemistry to the synthesis, bonding, and reactivity patterns of inorganic compounds. Special emphasis on the role of metal ions in biological systems.</p> </div>','CHEM 130 or CHEM 150; and CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7376,2021,66,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-340l','<div class="desc"> <p>Inorganic synthesis and structure confirmation. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 340 ',NULL);
INSERT INTO course_descriptions VALUES(7377,2021,485,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-350','<div class="desc"> <p>Biochemistry of macromolecules, with an emphasis on protein structure and function.</p> </div>','CHEM 221 and CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7378,2021,486,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-350l','<div class="desc"> <p>Laboratory techniques in Biochemistry. <em>One three-hour laboratory per week.</em></p> </div>','CHEM 221 and CHEM 240 ','CHEM 350 ',NULL);
INSERT INTO course_descriptions VALUES(7379,2021,67,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-355','<div class="desc"> <p>The main focus of this course is utilizing biological and chemical databases for research. The course will investigate: (1) tools that are used to extract and analyze data on small molecule drugs and biological sequences from these databases; (2) algorithms and scoring schemes used in sequence alignment and homology searches; (3) the significance of this information in modern chemical and molecular biology medicine, pharmaceutical development, protein engineering and drug design, genetics, and molecular evolution.</p> </div>','CHEM 221 and BIO 130 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7380,2021,487,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-360','<div class="desc"> <p>An introduction to the study of physical organic chemistry, with special emphasis on bioorganic chemistry, bio-macromolecular structure, and biological sequence analysis.</p> </div>','CHEM 221 and CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7381,2021,68,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-370','<div class="desc"> <p>A continuation of CHEM 340, focusing on the interface between organic and inorganic chemistry.</p> </div>','CHEM 300, CHEM 340, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7382,2021,1056,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-380','<div class="desc"> <p>An introduction to the study of organic synthesis.</p> </div>','CHEM 300 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7383,2021,69,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-395','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7384,2021,488,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/300/chem-397','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7385,2021,70,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/400/chem-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Chemistry majors.To be repeated both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7387,2021,489,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chem-chemistry/400/chem-499','<div class="desc"> <p>Independent study leading to an honors project. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7388,2021,71,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/100/chin-101','<div class="desc"> <p>Introduction to spoken standard Chinese (Mandarin), the pinyin romanization system, and the reading and writing of Chinese characters. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Chinese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7389,2021,491,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/100/chin-102','<div class="desc"> <p>Continuation of Chinese I. Conversation, reading, elementary composition; completion of basic grammar.</p> </div>','CHIN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7391,2021,72,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/200/chin-201','<div class="desc"> <p>A review of basic grammar. Reading and discussion of texts dealing with contemporary Chinese society and culture. Viewing and discussion of video programs. Composition writing and oral presentations.</p> </div>','CHIN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7392,2021,492,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/200/chin-202','<div class="desc"> <p>Continuation of CHIN 201.</p> </div>','CHIN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7393,2021,73,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/200/chin-272','<div class="desc"> <p>This seminar course will examine the rise of the martial arts novel (wuxia xiaoshuo) in the context of its historical and literary roots. We will focus on how the figure and chivalric code of the martial hero and heroine have persisted in the historical, literary, and popular imagination - through such works as Sima Qian''s historical biographies, <em>The Romance of the Three Kingdoms Outlaws of the Marsh</em>; Tang dynasty classical tales; Ming dynasty court-case fiction in the vernacular language; and Pu Songling''s classical strange tales written in the Qing period. We will also explore how the 20th century master of the martial arts novel, Jin Yong (Louis Cha), a journalist writing in exile in colonial Hong Kong, has captured the imagination of Chinese diasporic communities throughout the world and contributed to the rise of the transnational Chinese martial arts film. All readings and discussions will be in English. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7395,2021,817,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/200/chin-274','<div class="desc"> <p>This seminar course will explore ghosts and other disembodied beings in the Chinese literary tradition, from the earliest historical documents, philosophical texts, and Buddhist tales, to the Six Dynasties zhiguai records of the strange, the Tang chuanqi tales of the marvelous, and Ming dynasty vernacular fiction. We will focus on recurring motifs and archetypes which weave the supernatural into love stories, especially as manifested in two Qing dynasty masterpieces: Pu Songling''s <em>Strange Tales</em> and Cao Xueqin''s <em>The Story of the Stone</em>. Modern stories and film will also be examined for their adaptations of traditional motifs and archetypes. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7396,2021,1005,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/200/chin-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7398,2021,74,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/300/chin-301','<div class="desc"> <p>Reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Introduction to the use of literary style Chinese and idioms in public discourse. Developing advanced level oral-aural and essay writing skills.</p> </div>','CHIN 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7399,2021,1057,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/300/chin-310','<div class="desc"> <p>Advanced reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Oral presentations, academic style discussions, and writing of essays and narratives.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7400,2021,1058,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/300/chin-330','<div class="desc"> <p>A survey of representative works of short fiction and film by 20th century and contemporary Chinese writers and film makers. Topic and content of the course will vary from year to year according to three areas of focus: mainland China, Taiwan/Hong Kong, and transnational Chinese. Students will read and view original works and practice oral and written summaries, commentaries, discussion, and analyses in Chinese. Students will also read essays on literature and film in Chinese, with some readings in English. This course may be taken three times.</p> <p><strong>Female Who Writes and Who is Written</strong></p> <p>This course will examine the relationship between culture and society in China by focusing on the images of women represented in modern and contemporary cultural production, including literary and cinematic texts. By investigating the images of women in both literature and cinema from the twentieth century onward, this course will explore the development and transformation of the status of women in different sociohistorical periods of China, and discuss the ways in which cinema and literature feature women to address issues of gender, family, society, national identity, cultural memory, and so forth. In addition to representative literary texts, students will develop skills to interpret and analyze audiovisual media by watching the film adaptations of the assigned literary texts, and discuss how literary texts and cinematic media have both been used to construct and shape the cultural scene in Chinese society</p> </div>','CHIN 301 (or above) or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7401,2021,495,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/300/chin-350','<div class="desc"> <p>Readings in short classical Chinese texts, from pre-Qin historical, philosophical, and literary works that are the sources of sayings still common in modern vernacular Chinese. Students will learn the grammar, structure, and vocabulary of classical Chinese (wenyan) and gain advanced proficiency in modern spoken (baihua) and literary (shumianyu) Chinese, through exercises in oral and written discussion and analysis of the use of classical Chinese thought and sayings in contemporary Chinese language and culture. Course offered every four years.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7403,2021,496,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/300/chin-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7404,2021,1205,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/chin-chinese-studies/400/chin-460','<div class="desc"> <p>This advanced level course will introduce students to the art, practice, and intercultural contexts of translating Chinese into English. The class will discuss the content, linguistic form, and cultural contexts of a variety of authentic examples of written Chinese, followed by practice in producing readable English translations. Original Chinese texts will include short stories, essays, and media. This course is open to both non-native and native speakers of Chinese who wish to develop their bilingual skills and intercultural literacy. Class discussion will be conducted in Mandarin, Chinese, and English. May be repeated once for credit.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7407,2021,76,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/100/cogs-101','<div class="desc"> <p>An interdisciplinary introduction to the discovery of the mind through philosophical texts, psychological experiments, artificial intelligence, the study of nerve cells and neural networks, and investigations into language. The purpose of the course is to foster an appreciation of the wonder and complexity of minds and brains, both human and otherwise. Not open to seniors in Spring semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7408,2021,77,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/100/cogs-104','<div class="desc"> <p>This course provides a basic introduction to the nervous system. The course will include an introduction to how nerve and glial cells contribute to different brain functions. This course will also cover brain structures and systems and how they act to produce sensory experience, thought, emotion, and memory. Other topics might include: factors that affect embryonic development of the nervous system, and the effect of drugs, environment, stress, education, and age on the brain. This course is not open to students who have taken BIO 333, COGS 320, KINE 301, or PSYC 322.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7409,2021,1684,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/100/cogs-111','<div class="desc"> <p>The average adult possesses over 50,000 concepts, ranging from physical concepts like "force" and "density," to biological concepts like "growth" and "reproduction," to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich, revise, and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive, developmental, and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7411,2021,1504,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-201','<div class="desc"> <p>This course provides students with a foundation to think critically about research in Cognitive Science and lays the groundwork for the original research that will be done in the senior year. We will examine primary literature, carefully considering the processes involved in moving from a general idea to a specific research question. We will consider the strengths and weaknesses of a range of approaches to studying cognition, with a focus on experimental design. The course will culminate in an original research proposal.</p> <p>*For Fall 2020, this course will be conducted remotely in a “tutorial”-like format: we will have asynchronous mini-lectures, synchronous discussions, and small-group activities. Our discussions will be foundational and contemporary, focusing on the consequences the global pandemic has had on experimental research. Fall 2020 labs will be cancelled, but students can expect to be engaging in several lab-like activities throughout the semester. Students will not be required to take the lab at a future time, but may optionally enroll in the stand-alone lab or in a class focused on data processing, visualization, and analysis in a future in-person semester.* </p> <p><br/> </p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7412,2021,498,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-210','<div class="desc"> <p>Can one create intelligent machines? Machines capable of posing and solving problems and capable of interacting effectively with a complex and dynamic environment? If so, how? And what insights into natural cognition do we gain through efforts to create artificial intelligence? Fundamental principles, architectures, and algorithms for machine perception, control, and problem-solving will be addressed. We will also look, in detail, at strategies for developing intelligent machines, including traditional Artificial Intelligence and the more recent perspectives of situated and embodied cognition. The laboratory component of the course will involve computing and simple robotic devices.</p> </div>','COGS 101, 4 units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7413,2021,2325,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-220','<div class="desc"> <p>Are earthworms capable of making decisions? How do ants navigate their environment? Do dogs have an understanding of fairness? Questions about the mental states and processes possessed by non-human animals present particular problems of study: how do we determine whether, and to what extent, animals possess such abilities? This course will study the evidence for cognitive states and processes in non-human animals, focusing on careful and critical attention to the methods and techniques used to gather that evidence and on the considerations that go into interpreting that evidence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7414,2021,1006,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-230','<div class="desc"> <p>This course addresses the question: how can we understand the mind scientifically? We will explore answers to this question via a critical survey of neural and behavioral evidence bearing on the nature of core cognitive capacities, including perception, memory, emotion, decision-making, rationality, and consciousness. We will explore these sources of evidence in a comparative perspective, drawing on evidence of both human and (non-human) animal cognition, to more adequately characterize the general nature of cognition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7415,2021,1153,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-241','<div class="desc"> <p>As part of human cognition, our perception, production, and understanding of music has elicited many questions: what is music in relation to "sound"? Is music an evolutionary adaptation? What is the relationship of music and emotions or memory? Can music influence perception in other modalities? What is the meaning of music? Can music make us smarter? Is music a language? What is biological and what is cultural in the esthetics of music? This course will reframe many of these questions from the interdisciplinary standpoint of cognitive science, acoustics, music theory, and semiotics, to explore music as a cognitive process. Topics will include: the perception of pitch, timbre, rhythm, and localization; music and the brain; the cognitive aspect of the esthetics of music; the relationship between music and language in terms of their structures and neurological processing; music and memory; music and emotions; and music and meaning. We will also discuss the role music plays in cross-modal interactions, either in the real world or in films and multimedia art works.</p> </div>','Any Cognitive Science or Music class; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7416,2021,906,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-242','<div class="desc"> <p>Computational modeling provides important insights into how the mind/brain may work. We will examine three different approaches that have been used to provide insights into cognition: symbolic methods, connectionism, and probabilistic methods. We will use computer software to explore how these approaches work in practice. Specific applications, such as perception, language, and memory will be covered. The assumptions and limitations of each approach, as well as the metaphor of mind/brain as a computer, will be critically considered. This course has a mandatory laboratory component which will include both experimentation and computer programming. No previous programming background is required.</p> </div>','COGS 101, PHIL 225, MATH 186, MATH 210, MATH 214, MATH 252, COMP 157, COMP 161, COMP 165, or COMP 211; or permission of instructor ','COGS 101 (can be taken concurrently) ',NULL);
INSERT INTO course_descriptions VALUES(7418,2021,2398,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-255','<div class="desc"> <p>The primary goal of this course is twofold: (1) to provide students, from a wide range of disciplines, with hands-on training to analyze a variety of data-sets relevant to their course of study, and (2) to provide them with the tools to understand the rhetorical form and function of different types of data visualizations. Students will consider how questions can be answered using data; learn how to analyze data appropriately;learn to design and present graphs that tell an easy-to-understand visual story, have high impact and are memorable, and critically consider the assumptions underlying accurate interpretation of analyses and visualizations. Students from any major are welcome.</p> </div>',NULL,'COGS 255L ',NULL);
INSERT INTO course_descriptions VALUES(7420,2021,1641,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-265','<div class="desc"> <p>Art - be it visual, music, dance, or literature - is an extraordinarily powerful practice, driving much of our behaviors and engaging us physically, emotionally, and cognitively. This seminar will explore the various creative arts through the perspectives of Psychology, Neuroscience, and Philosophy. Topics will range from aesthetic foundations, historical dialogues between psychology and art, as well as the biological and evolutionary bases underlying aspects of creativity and art appreciation.</p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7421,2021,1441,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-292','<div class="desc"> <p>Mechanisms of brain development, growth, neurogenesis, maturation, and changes that occur during life. Emphasis will be placed on current literature and studies done in non-human animals and humans. We will also talk about what it takes to maintain a healthy brain.</p> </div>','COGS 101, COGS 104, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7422,2021,819,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/200/cogs-295','<div class="desc"> <p>This course explores a topic within the field of cognitive science. Topics vary by semester; past topics have included Intelligent Agents and Concepts. See the Department Chair for further information.</p> </div>','Any COGS course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7424,2021,78,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-301','<div class="desc"> <p>This course will address current cognitive science research as applied to learning and education. The concept of multiple intelligences, as well as strengths and weaknesses of individuals in acquisition of information, will be emphasized. We will also cover specific learning disabilities/differences and cognitive styles.</p> </div>','COGS 101, declared minor in Education, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7425,2021,2585,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-303','<div class="desc"> This seminar course will look at a topic in neuroscience from a multidisciplinary perspective. The course will focus on critical analysis of research studies and methodologies. May be taken more than once for credit as the topics will differ each semester. </div>','COGS 201, BIO 268, PSYC 200, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7426,2021,2544,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems, make decisions, draw inferences, attend to their environment, communicate, remember, and learn. Much of the material is applied to real-life settings.</p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7427,2021,2586,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-308','<div class="desc"> <p>In the second half of the 20th century, the new field of cognitive science came into existence. This course explores the developments in the history of philosophy, mathematics, biology, psychology, and computer science that culminated in this new science of the mind, including the theory of computation, from the work of Leibniz in the 17th century, the pioneering work on computing and programming by Charles Babbage and Ada Lovelace in the late 19th century, to Turing''s work in the early 20th century. We will explore how developments in both theoretical and applied computer science and logic led to the field of artificial intelligence and computational neuroscience, and we''ll explore the philosophical questions about the possibility and scope of machine intelligence. One prior course in cognitive science, philosophy, or mathematics is recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7428,2021,500,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320','<div class="desc"> <p>This course will introduce students to the biology of the mind. It will provide an overview of neuroanatomy and characterize the neural mechanisms supporting complex cognitive processes including vision, attention, consciousness, language, memory, learning, emotion, and action. We will also emphasize the importance of converging methodologies in studying the link between the mind, brain, and behavior. Methodologies we consider include: behavioral measures of cognition, neuropsychology, electrophysiology, anatomical and functional neuroimaging, single-cell recordings, and computational modeling. Laboratory sessions will allow students to obtain hands-on experience with these methodologies, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>','COGS 201, PSYC 200, BIO 268, or permission of instructor ','COGS 320L ',NULL);
INSERT INTO course_descriptions VALUES(7429,2021,820,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320l','<div class="desc"> <p>Laboratory sessions will allow students to get hands-on experience, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>',NULL,'COGS 320',NULL);
INSERT INTO course_descriptions VALUES(7430,2021,1371,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> </div>','COGS 101, four units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7431,2021,1059,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-330','<div class="desc"> <p>Language and cognition are intimately related. For this reason, Linguistics has had an extremely strong influence on Cognitive Science. This course studies language and linguistics in the context of Cognitive Science. We will address such questions as: how are language and thought related? How is language represented in the brain? How do we process language? To what extent is the human capacity for language innate? Is there a language of thought? What are the best ways to model language acquisition and language processing? We will cover some topics in traditional Linguistics and we will look at current research on connectionist and traditional artificial intelligence approaches to modeling language. Reading will include work by Chomsky, Pinker, McClelland, Rumelhart, Fodor, and Elman.</p> </div>','COGS 101 or LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7432,2021,1574,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-340','<div class="desc"> <p>This course focuses on the process and technology behind making intuitive and useful websites and the techniques for determining the effectiveness of the products, including prototyping and user testing. Students will also explore how principles of attention, perception and cognition guide relate to user experiences. </p> </div>','COMP 131 or COGS 101, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7436,2021,2674,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-390','<div class="desc"> <p>A recent replication crisis in the sciences has led to large-scale questioning centered on scientific integrity. Scientific integrity refers to 1) honesty while conducting and interpreting research, and 2) to developing conclusions that are unbiased and valid. Contemporary practices in research design and statistical analysis (e.g. p-hacking), lack of transparency, and political bias are all threats to scientific integrity. This course introduces and engages students conducting directed research with a faculty member in the Cognitive Science Department in best practices and ethical concerns in scientific research through evaluating primary research and commentaries within cognitive science and statistics, as well as by evaluating and critiquing the literature in their area of research focus. Students are expected to commit to a minimum of 8 hours of course-work each week including a course meeting, assigned group work, readings, and independent research.</p> </div>','COGS 101, COGS 201, and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7437,2021,821,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-395','<div class="desc"> <p>Directed research with a faculty member.</p> </div>','COGS 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7438,2021,501,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/300/cogs-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7439,2021,80,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/400/cogs-490','<div class="desc"> <p>This course will support senior Cognitive Science majors as they conduct original research as part of their Senior Comprehensive requirement. </p> </div>','COGS 101 and senior standing in Cognitive Science; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7440,2021,2545,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cogs-cognitive-science/400/cogs-495','<div class="desc"> <p>Students with substantial directed research experience will conduct an independent research project of their own design, with guidance from a faculty mentor. Students are expected to devote a minimum of 6 hours per week to their project, and will present their results in a colloquium open to the campus community. Open only to seniors and by permission of the instructor.</p> </div>','COGS 201, COGS 290, or COGS 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7444,2021,1511,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-131','<div class="desc"> <p>Computer Science is about the organization of information and the design of processes that use it. This course teaches students to think computationally - how to break down processes into components that can then be fully described - and to acquire other habits necessary for a computer scientist. Students should come out of the course able to write simple, but complete, programs of their choosing, and should also be able to diagnose problems in unfamiliar programs.</p> </div>',NULL,'COMP 131L ',NULL);
INSERT INTO course_descriptions VALUES(7445,2021,2648,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-146','<div class="desc"> <p>Comprehensive study of measures of central tendency, variation, probability, the normal distribution, sampling, estimation, confidence intervals, and hypothesis testing. Introduction to use of technology in statistics. Real-life problems are used to illustrate methods. Weekly lab. Not open to students who have completed or are currently enrolled in PSYC 201, BIO 368, MATH 150, or any Mathematics course above 200.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7446,2021,2508,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-149','<div class="desc"> <p>This course provides the mathematical theory which underpins Computer Science, including: number systems; variable types and formats; logic; set theory; graph theory; linear algebra; and important numbers, functions, and relations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7447,2021,81,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-155','<div class="desc"> <p>Principles of web design. Tools and techniques of elementary web programming, including: HTML, XHTML, CSS, Javascript, HTTP, SSL, XML, and SQL. Introduction to network architecture and programming.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7448,2021,908,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-157','<div class="desc"> <p>Programming in C++, including: procedures; functions; control structures; files; structs; and elementary uses of pointers, objects, and classes. Does not assume any prior knowledge of C. Course offered in alternate years. Not offered every year. Not open to students who have taken, or are taking, COMP 161.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7449,2021,82,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-161','<div class="desc"> <p>Introduction to computers and fundamentals of programming in Java. Classes, objects, and methods; variables and data types; decisions and iteration; arrays and array lists; Java, API, and important classes, such as String Math Graphics; simple algorithms; and programming techniques. This course serves as either a self-contained introduction to Java Programming, or the first step in the sequence of courses leading to the Computer Science minor. Not open to students who have taken, or are taking, COMP 157<em>.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7450,2021,503,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-165','<div class="desc"> <p>Introduction to using Mathematica for mathematical calculation and programming.</p> </div>','Prior programming experience in any language OR any of the following Math courses: MATH 109, MATH 110, MATH 114, MATH 120, MATH 128, MATH 210, MATH 212, or MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7452,2021,1581,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/100/comp-197','<div class="desc"> <p>Directed individual study. Permission of instructor and department chair required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7453,2021,504,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/200/comp-211','<div class="desc"> <p>Programming with linked data structures, including stacks, queues, trees, and linked lists. Object-oriented programming. Programming methodology. Computer systems. Ethics in computing. Weekly laboratory.<em></em></p> </div>','COMP 161 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7454,2021,1649,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/200/comp-229','<div class="desc"> <p>We begin with topics found in advanced programming. In particular, topics from object-oriented programming and how this differs from procedural programming. We then move on to the study of dynamic data structures, such as linked lists, stacks, queues, trees, heaps, graphs, hash tables, sets and more. Completion of this course opens up the remainder of the Computer Science classes and is required for minors. Common themes that run throughout this course are: (1) implementation of the abstract data types, and (2) spatial and memory consideration and analysis.</p> </div>','COMP 127, COMP 131, COMP 211, a score of 4 or 5 on the AP Computer Science A examination, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7455,2021,2509,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/200/comp-239','<div class="desc"> <p>This course covers the basics of how a computer works, focusing especially on the hardware-software interface. Students will learn about the limitations of the physical computer, and that it may not be possible to ignore the lower-level hardware when designing efficient software. Students will learn to implement programs in Assembly language and C/C++. They will investigate the main components of the computer and it''s processor and master the binary language of computers. They will learn important design concepts such as memory hierarchy and parallel computing, and have a brief encounter with principles of digital logic. This is a required course for the Computer Science major. Includes one 1.5 hour lab period per week. </p> </div>','COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7456,2021,2539,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/200/comp-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7457,2021,2737,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/200/comp-277','<div class="desc"> <p>Video games are one of the newest forms of media, and offer tremendous promise for both entertainment, storytelling, and education. Starting from the text-based adventures of the 1970s to the billion-dollar industry today, students will learn how to use psychology and game mechanics to create compelling narratives, as well as gaining a glimpse into large-scale software development.</p> </div>','COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7458,2021,2869,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/200/comp-295','<div class="desc"> <p><strong>Computing In Real Life Internship</strong></p> <p>Students will work with LA-based non-profits such as STEAM:CODERS, a Pasadena-based organization that teaches local middle and high school students to program, or the Association for Women in Mathematics, a national organization that promotes women in computation. Students will complete weekly reflection papers and a final presentation describing what they’ve learned about computation IRL. <em>Open only to students enrolled in the Computing IRL semester.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7460,2021,822,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-311','<div class="desc"> <p>Comparative data structures and analysis of algorithms. Abstract data types. "Big O" notation, run time and memory allocation considerations, introduction to computational complexity. Selected topics and applications from graph theory, linear algebra, numerical analysis, and data compression. <em>Weekly lab.</em></p> </div>','COMP 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7461,2021,2618,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-313','<div class="desc"> <p>The key to the animation and videogame industries is the ability to display simulated worlds in real time. Starting with representing 3D space, this course will teach students the data structures and algorithms, such as quadtrees, texture mapping, and ray tracing, to create photorealistic images.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7462,2021,2858,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-319','<div class="desc"> <p>Knowledge Representation and Reasoning is the area of Artificial Intelligence concerned with how knowledge can be represented and how automated systems can reason about that knowledge. In this course, we will learn how to use symbolic notations to represent knowledge, including how to represent objects, events, time, space, and language. We will also learn how to use automated reasoning systems to manipulate these representations and derive new knowledge. This will be a hands-on course in which we apply concepts from philosophy, psychology, and cognitive science to build systems that can reason about real-world problems.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7463,2021,2784,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COGS 101, four units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7464,2021,2711,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-331','<div class="desc"> <p>The wealth of textual information online and elsewhere makes the ability for computers to understand and generate text particularly valuable. This course will explore both the traditional, linguistic approach to understanding language, as well as modern information retrieval and statistical big data approaches. Topics include information retrieval, search engines, parsing, Markov models, and knowledge representation.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7465,2021,1651,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-337','<div class="desc"> There are hundreds of programming languages in use, many with unique features. This course is a survey of different programming languages and their similarities and differences. As part of this study, students will be additionally be introduced to topics such as type systems, parsing, and the theory of formal languages.<br/> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7466,2021,2547,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-340','<div class="desc"> <p>This course focuses on the process and technology behind making intuitive and useful websites and the techniques for determining the effectiveness of the products, including prototyping and user testing. Students will also explore how principles of attention, perception and cognition relate to user experiences.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131, COGS 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7467,2021,2506,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-347','<div class="desc"> <p>Many recent advances in artificial intelligence are not in symbolic systems, but in statistical machine learning and data science. This course offers a balance between the theory and practice of data science, from collecting and understanding the data, to developing supervised and unsupervised models (such as linear regression, support vector machines, K-means and Gaussian mixture clustering, principle component analysis, neural networks), and finally interpreting the predictions and their limitations.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 and either COMP 149 and MATH 146/ COMP 146; or MATH 150, MATH 210, and MATH 214; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7468,2021,2785,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-349','<div class="desc"> <p>Robotics offers one of the most integrating domains for computer science. Creating a working, human-facing robot brings together hardware and software, artificial intelligence and human-computer interaction. Topics include Simultaneous Localization and Mapping (SLAM), path planning, object recognition, basic mechanics, and social robotics.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7469,2021,2651,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-352','<div class="desc"> <p>The logical foundation of the notion of a computable function underlying the workings of modern computers. Representation of the informal mathematical idea of calculability by canonical proxies: general recursive functions, Turing computable functions. Discussion of Church''s Thesis, which asserts the adequacy of these representations. Survey of decidable and undecidable problems. </p> <p>Sub-field: <strong>THEORY</strong></p> </div>','Math 210, COMP 149, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7470,2021,1324,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-353','<div class="desc"> <p>An introduction to information theory that will focus on: (1) data: transmission, storage, lossless data compression (such as ZIP and LZW), lossy data compression (found in JPG or MP3 formats), channel capacity; (2) coding: optimal codes, error correcting codes, the several coding theorems of Claude Shannon; (3) measures of information: entropy, relative entropy, relation between entropy and information content; and (4) application topics that vary from year to year and might include: signal processing, image processing, pattern recognition, cryptography and data security, quantum computing, data analysis, and more.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','MATH 210 and MATH 214 or COMP 149; recommended MATH 146 or MATH 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7471,2021,2859,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-355','<div class="desc"> <p>This course will teach students both front-end and back-end techniques necessary to build web applications. Students will learn how to make interactive websites, how to structure and manage content for websites in databases, and how to create data-driven web applications.</p> <p>Sub-field: <strong>SOFTWARE</strong></p> </div>','COMP 229 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7472,2021,2786,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-357','<div class="desc"> <p>Much of the power of computers is that they are not individual machines, but units on a network that can exchange information. This course starts with the transmitting binary electrical signals, then builds up to the TCP/IP stack and the algorithms involved, and finally current research questions in the field.</p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7473,2021,2329,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-367','<div class="desc"> <p>The largest programming projects are completed by multiple computer scientists working together. Clients across Eagle Rock and the Oxy community will propose problems with computational solutions, which we will complete in teams as a semester long-project. Using standard tools, such as version control, we will apply the principles of user-centered design to software: understanding the needs of the client, developing software, and testing the product with the user, before repeating the cycle. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 127 or COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7474,2021,2588,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-373','<div class="desc"> <p>Any large amount of data, such as that stored by Google or Facebook, requires specialized algorithms to ensure consistency and efficient access. From relational models and SQL to newer graph databases, students will understand how to represent entities a domain with rows in a database, culminating in a project that uses this knowledge in a real-world setting. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7475,2021,2787,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-379','<div class="desc"> <p>An operating system ties together the hardware and software components of a computer. For interested students, this will likely be the final step to completely understanding what happens when code is executed. Topics include virtual memory, file systems, process management, parallel computing, and others. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7477,2021,2713,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-389','<div class="desc"> <p>Security on the internet is fundamentally based on the mathematical properties of the algorithms we use to encrypt our data. This course teaches students the theory behind these algorithms and how future advances such as quantum computing may affect current standards of security and privacy. Topics include ciphers and frequency analysis, private and public key cryptography, randomness, and quantum cryptography.</p> <p>Sub-field: <strong>SECURITY</strong></p> </div>','COMP 149 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7478,2021,2510,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-390','<div class="desc"> <p>This course focuses on responsible conduct of Computer Science. Students will explore the effects of technology on the modern world, including issues of electronic voting, personal security and privacy, intellectual property, and others. This course will culminate in a research paper on one of these topics, examining the technical background, as well as the social forces that contextualize the issue. Students should have an decent understanding of the challenges of writing software, and why certain questions are computationally difficult (that is, require significant time/memory). </p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7479,2021,1689,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-395','<div class="desc"> <p>Topics vary semester to semester.</p> </div>','COMP 127, COMP 131, COMP 211, or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7480,2021,506,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7481,2021,2857,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/comp-398','<div class="desc"> <p> Students engage with open problems in an active area of faculty research. May be repeated once for credit.</p> </div>','COMP 127, COMP 131, COMP 211, or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7482,2021,1650,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-317','<div class="desc"> <p>We study algorithms from the point of view of efficiency and complexity. Having studied data structures, we now see how to apply algorithms to these structures to optimize their effectiveness. We examine algorithms in terms of time and memory allocation considerations. We will apply this background to a subset of the most important algorithms used in the sciences, various media, and business. We will study effective algorithm design, and give a brief introduction to computational complexity and computability, as well as parallel processing. Selected topics and applications from graph theory, linear algebra, numerical analysis, data compression, encryption, and large scale problems from Mathematics and the sciences.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 229 and either COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7483,2021,2712,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-371','<div class="desc"> <p>Smartphone apps, in their limited computational power and radically different form factor, impose new constraints and challenges different from the development of other software. In this class, students will be introduced to mobile architecture and related concepts such as monetization, privacy, analytics, and cross-platform development.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 and COMP 229, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7485,2021,2540,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/comp-computer-science/400/comp-490','<div class="desc"> <p>This course will support senior Computer Science majors as they conduct projects as part of their Senior Comprehensive requirement. Students must have senior standing to enroll.</p> </div>','COMP 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7488,2021,188,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-101','<div class="desc"> <p>This course is an introduction to early North American/U.S. history, reaching from colonization to the Civil War. Of particular interest in this course will be the theme of cross-cultural interactions in the midst of transforming economies, an expanding nation, and unequal power relations. We will combine a broad introduction to early American history with an in-depth look at five case studies of individuals and communities encountering each other across borders of nation, religion, race, gender, ethnicity, and class. Each case study offers a unique perspective on the question of how broad economic structures of colonization, slavery, and the market revolution shaped human encounters between natives and newcomers, captives and captors, slaves and slaveholders, Northerners and Southerners. Ultimately, these case studies encourage a critical rethinking of concepts of liberty, equality, and democracy, which have formed the bedrock of master narratives in United States history. Within the context of these broad, sweeping themes, we will look closely at primary historical documents, produced by men and women of their time period, and we will carefully read the arguments of historians in our own time. The class will emphasize history as a process of critical interpretation.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7489,2021,609,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-102','<div class="desc"> <p>This course provides an introduction to United States history from the Civil War to the early 21st century. Readings and lectures are structured around the core theme of American pluralism. They emphasize the changing demographics of the American population and consider the different strategies that Americans have used to negotiate this growing diversity over time. Topics covered include: Reconstruction, westward expansion and overseas imperialism, Industrialization and the Gilded Age, the Progressive Era, World War I, the Great Depression and New Deal, World War II and the rise of internationalism, the Cold War and third world decolonization, immigration reform and comparative civil rights movements, the Vietnam War and the rise of global dissent, conservatism and the "Reagan Revolution," America''s border wars, and the post-9/11 War on Terror. We will give particular attention to issues of race, ethnicity, gender, religion, sexuality, region, and class in the shaping of modern America. Other important themes include: the expansion of federal power and the government''s role in people''s lives, contests over national citizenship and identity, America''s changing role in the world and engagement with foreign peoples, and the demographic transformations wrought by international migration and conflicts.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7490,2021,942,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-121','<div class="desc"> <p>A survey of multiple Western civilizations and their interrelationships. Among ancients, we shall study Mesopotamians, Egyptians, Hebrews, Persians, Greeks, and Romans. In medieval times, we shall examine Catholic Europe, Greek Orthodox Byzantium, Islamic Civilization, and their interrelationships. We shall consider the treatment of women and of minorities, and shall highlight travelers between civilizations. We shall conclude with the European Renaissance and Reformation, Turkish hegemony in the Eastern Mediterranean, and the shift in trade from the Mediterranean to the Atlantic Ocean, as modern science and enlightenment challenge traditional civilizations.</p> <p><strong>Survey Requirement Met:</strong> Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7491,2021,610,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-122','<div class="desc"> <p>The course focuses on the rise, fall, and re-emergence of Europe as a global political, economic, and cultural force in the modern age. We begin with the Enlightenment in the 18th century and the dissemination of European power in the 19th century through capitalism, the industrial revolution, nationalism, and imperialism. We then turn to Europe’s crisis in the 20th century with attention to World War I, Fascism and Nazism, and the Holocaust, to be followed by rebirth in the form of reconstruction and European unity. Specific topics addressed include the French Revolution, the birth of capitalism, the rise of the nation-state, colonialism and decolonization, liberalism, socialism, communism, changes in family structure and gender relations, and the movements for women''s, workers’, and minority rights.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7492,2021,2592,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-125','<div class="desc"> <p>In this course focused on European cultures, students will consider the Renaissance and Reformation, Science and Baroque Splendor, Enlightenment Reason and Revolution, Romanticism and Individualism, Industrial Revolution and New Social Thought, Modernism in Literature and the Arts, Global Influences, Cultural Pluralism, and Postmodern Culture. Students experience and critically evaluate texts and images from both historical and contemporary points of view.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7493,2021,189,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-141','<div class="desc"> <p>A survey of Chinese, Japanese, and Korean societies from the emergence of states to the present. Several themes explored include: the development of strong, centralized states; the emergence of a shared elite culture; the spread of popular religions; the continuing interaction between East Asian and other societies; contrasting roads taken by each society in order to meet the challenges of modernity; conflicts over imperialism, nationalism, and revolution; cultural debates over gender and generational issues. Finally, a review of the post-WWII era: opposing alignments in the Cold War; socialist state building and experimentations; military rule; democracy; mass culture; successive economic "miracles," and China''s re-emergence as a global power.</p> <p><strong>Survey Requirement Met:</strong> Asia</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7494,2021,190,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7495,2021,611,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-151','<div class="desc"> <p>This course offers a survey of postcoloial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the 19th and 20th centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the 19th century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race; and the development of export agriculture. The second section introduces themes of the 20th century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources, including scholarly works, films, and primary sources to engage these topics and issues.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7496,2021,848,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-182','<div class="desc"> <p>This is a survey course in which we will explore the cultural and social historical experience of the Middle East from the 19th century to the present. Our goal in this class is to develop a sense of how people in the region view themselves and their history. We consider the currents of social change wrought by political and economic transformation, focusing particularly on the rise of new social movements and cultural currents. Here we will focus on issues of gender, religion, new social categories, and notions of personhood, and new forms of collective and individual identity. Finally, we look at the emergence of modern nation-states and their attendant juridical notions of citizenship and minority status.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7497,2021,1072,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-183','<div class="desc"> <p>This is a survey course in which we will explore the political and socio-economic history of the Middle East from the beginning of the Ottoman reforms of the 1830s until the present. Our aim is to provide a comprehensive overview and analysis of the events of the past two centuries. In addition to the Ottoman reform period, we will look at the rise of Mehmet Ali in Egypt, the incorporation of the region into the world economy, WWI and its continuing legacies in the region the development of the Arab/Israeli question, the revolutions of the 1950''s and the populist regimes they brought to power, the crisis in Lebanon, the Iranian Revolution, the war between Iran and Iraq, and the Iraqi invasion of Kuwait. We will also consider some of the principal features of the economy of the region: agriculture and land reform, oil and state, and labor migration from poor states to richer ones.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7498,2021,2689,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-190','<div class="desc"> <p>This course will take a historical look at the emergence and development of capitalism from the 16<sup>th</sup> century to the present. The course stresses capitalism’s global spread and interaction with other historical forces such as commercialization, urbanization, colonialism and imperialism, environmental and climate change, inequality, and social and economic instability. We will look at the emergence of various schools of thought on capitalism, such as Keynesianism, Marxism, liberalism, the Austrian School and its offshoots, and neoliberalism. We will end with a discussion on the future of capitalism, considering globalization, the rise of China, economic crisis, and the rise of nationalist and populist responses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7499,2021,2677,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-191','<div class="desc"> <p style="margin-left:0in; margin-right:0in">This course traces the theory and practice of revolution in modern history. The course begins with a brief overview of revolutionary theories and transformations within a global historical context. We then turn to the Scientific Revolution and the Enlightenment as the paradigm shifts which brought a revolution in thought and subjectivity in Europe. From there we focus on the French Revolution, following its legacy and impact through the revolutions of the 19<sup>th</sup> century, the rise of Socialism and Communism, the Russian Revolution, the Chinese Revolution, decolonization and revolutions in Africa, and the Cuban Revolution. The course looks closely at how these revolutions in thought and politics changed the way people understood their relationship to state and society. In the search for global connectivity, we review revolutionary movements beyond the western European and United States to include cultures and civilizations of Asia, the Middle East, Africa and the Americas. We will ask a number of questions related to revolutionary change, including: what causes revolutions? Who makes a revolution? What leads to success or failure in a revolutionary situation?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7500,2021,2885,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/100/hist-192','<div class="desc"> <p>The course explores gender as a malleable category of historical analysis that intersects fluidly with other categories such as race, class, and sexuality. Course materials interweave global historical studies from the 16<sup>th</sup> to the 20<sup>th</sup> centuries with theoretical work on themes including the following: gender as performance, gendered divisions of labor, gender and science studies, the politics of gender, as well as gender, space, and material culture. By continually historicizing the construction of masculinities, femininities, and gender-fluid identities, this course examines how societies over time have expressed, policed, invented, and reproduced gender as a category of human experience and a shaper of social relations of power. The geographic range of the course is oriented primarily toward the Atlantic World: North America, South America, the Caribbean, West and West Central Africa, and Europe.</p> <p>This survey course is one of the History’s department’s gateway 190s-series that takes a transnational and thematic approach to key concepts in historical studies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7502,2021,943,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/copy-of-hist-243','<div class="desc"> <p>Chinese history from about 1600 to the present: the growth of the domestic economy, the rise of the Manchus and territorial expansion, encounter with the West, internal decline, rebellions, imperialism, nationalism, and revolution. Gender and national identity are key lenses through which to understand transformations during the modern period, including Modernization efforts, ideological struggles, and the cultural and economic transformations under the People''s Republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7503,2021,2340,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected, what was historically, the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean, which has become known as the proper noun, the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the twentieth Century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-39 Palestinian Revolt, the 1948 War for Palestine and its aftermath, Israeli-Arab relations in the 1950s, the Suez War, the implications of gendering the nation, the 1967 War and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7504,2021,2341,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-205','<div class="desc"> <p>According to Thomas Jefferson, America was to be an "agrarian Republic" - a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones, as well. Indeed, for many early migrants, America was itself a "city on the hill" - an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing, in the second half, specifically on Los Angeles, where new forms of decentralized urbanism took form in the 20th century. We will not only explore suburbia and freeways, Disneyland, and other quasiÂ­urban outposts, but also the changing character of the inner city in the mid-20th century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today - multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism - the changing character of public space, the turn to privatism, the neglect of public transport infrastructures, and challenges to democracy and equality - are ultimately compatible with the American dream of the "city on the hill" for the 21st century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7505,2021,191,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-206','<div class="desc"> <p>This course will examine the variety of female experiences in 19th and 20th century America by looking at the class, racial, and ethnic dimensions that shaped women''s lives. A second major concern will be to study women in the context of the historical developments of their time; reform movements, westward migration, industrialization, and urbanization will be examined in light of their impact on women''s experiences and values. The course will also consider a number of themes, including: popular images of women, women and sexuality, women and the family, women and work, women as consumers, and women as reformers.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7506,2021,2851,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of forced African migrants to North America to the black quest for freedom in the twentieth century United States. With our focus on significant demographic, institutional, cultural, and political developments within African American communities, we will explore key themes and watershed moments in the African American experience: from slavery to emancipation, from rural to urban, and from the civil rights and black power movements of the twentieth century to the ongoing struggle for social justice. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of black Americans and the history of the United States.</p> <p><strong>Survey Requirement Met:</strong> United States</p> </div>','n/a ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7507,2021,1233,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-208','<div class="desc"> <p>What does it mean to say that America is a "nation of immigrants?" This course explores the creation of America through the arrival of diverse peoples from five continents over several centuries. Topics include: the legal and political foundations of U.S. citizenship; the creation of the U.S.-Mexico border; the origins of illegal immigration; ethnic and diasporic identities; state power and resistance; popular culture; social movements; and the importance of race, as well as gender and sexuality, in shaping immigration policy and its enforcement. Special attention will also be given to exploring the diversity of immigrants'' experiences in America over time.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7508,2021,1382,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-209','<div class="desc"> <p>This course traces the United States'' rise to global superpower over the first half of the 20th century; its engagement with, and interventions in, a decolonizing Cold War world; and, finally, its transition to its contemporary role as part of an increasingly multilateral and internationalist world order. Our investigation of U.S. engagement with the wider world rests on the understanding that as America''s influence on the world grew, so did the world''s influence on America. Lectures and readings will cover America''s political and military dealings with other powers - that is, U.S. diplomatic history as traditionally understood - but will also address Americans'' cultural, social, economic, and intellectual interactions with foreign peoples, both at home and abroad. Specific topics include: U.S. overseas imperialism, the U.S. role in both World Wars and the Cold War, the heightened significance of Asia and the Pacific World after 1940, internationalism and the creation of the United Nations, the emergence of the Third World and Washington''s ambivalent relationship to global decolonization, Americans'' involvement in the global revolutions of the 1960''s, the economic upheavals of the 1970''s, the end of the Cold War, and the politics of a post-Cold War and post-9/11 world.</p> <p><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7509,2021,1601,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-210','<div class="desc"> <p>Oranges, palm trees, earthquakes - California is so easily summarized by a few vivid images. Yet, the history of the Golden State is even more active and vibrant than these iconic symbols suggest. In this course, we will witness the clash of colonial empires and the effects on the people caught in the crossfire; we will trace the modernization and urbanization of the state revolving around the dizzying rise of bawdy and wild San Francisco on the spoils of the Gold Rush; we will observe repeated clashes over resources and political will, following the paths of the utopians who wished to remake the society on the Pacific; we will visit the changing landscape of dreams and fantasy, from Hollywood to Disneyland; and we will, ourselves, engage with contemporary battles over public space, racial identity, and suburban sprawl. And yes, there will indeed be oranges, palm trees, and earthquakes playing their roles in this complex and varied story, as well. This survey course covers the entire sweep of the history of California, although it places particular emphasis on the past hundred years, and on urban Southern California, in particular.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7510,2021,2593,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-211','<div class="desc"> <p>From the Cold War to the War on Terror this course will examine the United States’ involvement in Afghanistan, Iraq and the Middle East since 1980. Among other things we will look at the connections between the events of 9/11 and the Iraq and Afghanistan wars. This class is an inquiry into the historical implications of these and other protracted US engagements from North Africa to Syria and from Somalia to Pakistan. Ultimately, we will use these events as a lens to pose a series of questions about empire, nation and national identity both in the US and in the Middle East.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7511,2021,2594,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-212','<div class="desc"> <p>With its capital in Europe since 1363 and spanning Europe, Asia and Africa for nearly five centuries the Ottoman Empire was perhaps the most successful and longest enduring experiment in multiculturalism the world has ever known. Multi-lingual, multi-ethnic and multi-religious Ottoman society and culture were comprised of Muslim, Byzantine Christian, Turkish, Greek, Persian, Mongol, Slavic, Armenian, Arab, African and Jewish cultural elements. Edicts from the Ottoman state were regularly issued in nine languages. One reason for its longevity was its willingness to draw on the diversity of this rich historical and cultural tableau. In this course, we will examine the complex social, cultural and political transformations occurring in the Ottoman Empire from its inception as a small principality in western Anatolia until it reached its zenith when it stretched into modern-day Austria.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7512,2021,1602,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-213','<div class="desc"> <p>This course explores free Black political organizing, from the American revolutionary era through Reconstruction. Students will conduct original research into African American activism that stretched from New York to California before and after the U.S. Civil War. We will explore the social networks and political institutions that 19th-century African Americans built to fight for civil rights, economic justice, and an end to chattel slavery. At the heart of the course is a digital humanities component that will involve students in researching the lives and ideas of individual Black activists. At the end of the course, we will contribute our collective research to the national website, Colored Conventions. While engaged in original historical research, students will also be reading exciting scholarship on the rise of free Black communities in the U.S. and the emergence of African American institutions (churches, schools, press, political organizations). We will delve into questions such as: how did free African Americans, from leadership to grassroots levels, organize for racial equality, abolition, and community empowerment? How did class structures and gender ideology shape the dynamics of Black organizing? What transnational relationships and diasporic identities did Black activists build in the protracted struggles for abolition and citizenship?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7513,2021,2553,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-214','<div class="desc"> <p style="margin-left:0in; margin-right:0in;">This course, covering the period roughly from 1850 to 1877, examines the origins of the Civil War, the war itself, and the period of Reconstruction. The class meetings and readings will focus on the transformation wrought by the war, analyzing in particular the impact of the war on society, politics, and culture. Although there will be some discussion of military events and the military experience of some of the participants, this is not a course in military history. We will pay special attention to the following themes: the imperfections in the republic that led to war; the centrality of slavery and emancipation before and during the war; the war as a revolutionary experience for individuals and institutions; and the meanings and legacies of reunion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7514,2021,2595,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-215','<div class="desc"> <p style="margin-left:0in; margin-right:0in;">This course examines the relationship between American law and American history from the European settlement of North America to the beginning of the 21st century. Examining legal institutions, legal processes, and legal culture over a long time span, the course offers insight into the changing relationship between power and the people in the United States. Because one semester is too brief a time to cover every subject in American legal and constitutional history, this course examines specific issues or episodes that demonstrate particularly well the close relationship between law and history. These include such topics as early witch trials, the laws of slavery, Native American dispossession, the evolution of marriage law, economic regulation, and the emergence of the right to privacy.</p> <p style="margin-left:0in; margin-right:0in;"><strong>Survey Requirement Met: </strong>United States</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7515,2021,1702,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-216','<div class="desc"> <p>This course begins in the Colonial period and focuses on the unprecedented growth of the American Jewish community throughout the modern era. Historically, Jews have sought refuge and greater prospects in the United States from Spanish, Portuguese, Germanic, and Dutch lands, as well as from Eastern Europe, North Africa, and the Middle East. By using a diverse framework of analysis, we will cover topics such as: the early settlers, Jews and the American Revolution, the German migration, the influx of Jews from Poland and Russia, New York City and the rise of the Jewish Lower East Side, the Jewish labor movement and politicization, Yiddish culture, suburbanization, the plight of Soviet Jews, the growth of insular ultra-religious communities, and disenchantment and hipster Jewish life today. Readings will consist of primary and secondary material.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7516,2021,1020,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-220','<div class="desc"> <p>This course provides an opportunity to vicariously "live" in historical cities considered to be creators of democratic or representative forms of government, as well as of great literature and art. Historian Thucydides, comic Aristophanes, and philosopher Plato draw us into Athenian gender/class socialization, politics, and culture; likewise, Boccaccio, the Medici family, and Machiavelli inform us of Florentine gender/class socialization, politics, and culture. Monumental architecture and gendered sculpture continue to serve to decorate and sustain the individuality of each city. By examining documents of daily life (including court cases concerning sexual acts) and the luxury products of the diverse crafts, we increase our knowledge of the controversial behavior and productivity of a wide spectrum of women and men. By focusing on two cities in their "golden age," the class will emphasize the shared positive, as well as negative, characteristics of ages historians have designated as "golden." History majors may petition for 300-level credit for this class with the completion of additional work arranged with the instructor. (May be taken as History 397 by writing a research paper in place of one class paper).</p> <p> <em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7517,2021,1172,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-224','<div class="desc"> <p>This course offers a chance to come to know a variety of individuals who lived in and travelled from the Italian peninsula in the 1300''s, 1400''s, and 1500''s. We shall journey to the Far East with Marco Polo; meet peoples of the Mediterranean; and "visit" the republics of Venice and Florence, the papal court of Rome, and the ducal courts of Urbino and Mantua. We shall enjoy distinctive creations in literature, education, philosophy, and the arts, and read letters about South American peoples from Amerigo Vespucci. Diplomat Machiavelli witnessed independent Italian city-states fall to French and Habsburg conquests and described such realistic politics; courtesan Veronica Franco successfully practiced her sexual trade while writing poems celebrating her true love, as well as her mercantile city-state. Students may petition for 300-Level credit for this class with the completion of additional work arranged with the instructor.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7518,2021,1173,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-226','<div class="desc"> <p>A history survey of the 14th-18th centuries: Renaissance, reformation, scientific advance, global encounters in Spanish and English empires, the Enlightenment, and revolutions (English, American, French). The luxury of European palaces was based upon the exploitation of European peasants and global indigenous peoples. Students seeking origins of the concept of human rights will consider protest pamphlets, utopian fiction, and enlightenment stories (some with film versions), which created empathy for others.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe<em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7519,2021,1525,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-230','<div class="desc"> <p>This course is a critical survey of some great ideas that have shaped Western civilization. We will consider, among others, Homer, Sophocles, the Presocratic philosophers, Plato, Aristotle, Cato, Marcus Aurelius, the Hebrew Bible and the New Testament, the Scholastics, Machiavelli, Luther, Copernicus, Galileo, Bacon, Locke, Voltaire, Rousseau, Condorcet, Mary Wollstonecraft and Mary Shelley, Marx, Darwin, Nietzsche, Virginia Woolf, and Simone de Beauvoir.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7520,2021,2655,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-233','<div class="desc"> <p>The turn to authoritarianism and rise of fascism in Europe between the First and Second World Wars represented a profound turning point in European politics and society, as nations from Italy to Hungary, Germany, to Greece became home to fascist regimes or movements. This History course studies the rise, function, and fall of fascism , especially as it existed in Mussolini''s Italy and Hitler''s Germany, between 1922 and 1945. In the period between World War I and World War II, new and alternative models for the relationship between state and society challenged the existing political and social order, as many Europeans abandoned democracy as the ideal political system. Many turned to nationalist authoritarianism as the answer to the political, economic, and social crises shaking Europe. Italy, under the National Fascist Party, and Germany, ruled by the National Socialists, were the nations in which this flight from democracy became a full-fledged descent into dictatorship and one-Â­party rule. This course examines authoritarianism and dictatorship in interwar Europe and we assess how the elevation of the state and the nation, promoted by these regimes and parties, impacted the societies involved.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7521,2021,193,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-234','<div class="desc"> <p>The class examines the political, social, and economic crises that shook the nations of Europe in the two decades following the First World War. In particular, we address the character of the crisis; the varied European responses to it; and the challenges represented by the end of the First World War, Depression, Fascism, the Second World War, and the Holocaust. While assessing the nature of the social, political, and economic crisis of interwar Europe, we will also pay close attention to historiographic debates on the rise and nature of Fascism and the origins of the Second World War. We focus strongly on primary sources such as the novels, film, and art of the era. Topics include: the "Lost Generation," the Weimar Republic, the Spanish Civil War, and the Popular Front in France.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7522,2021,1073,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-235','<div class="desc"> <p>This course examines the history of modern Europe with a focus on popular and state-supported ideologies of exclusion and violence in the long 20th century (spanning 1890-2011). Central to this course is a focus on the discursive boundaries of civil society based on race and class. Throughout the course, we situate European developments in a world-historical framework as a way to understand the increasingly interdependent political, social, and economic relationships between Europe and the colonial periphery. We begin in fin de siècle Europe, and trace the polarization of national politics and the development of the contending state ideologies of fascism and communism. We explore the consequences of various programs of decolonization, as well as the popular revolts against cultural diversity and post-colonial immigration to the metropole. The course also investigates the origins and consequences of the neo-liberal "revolution" of the 1980''s, the ethnic violence stemming from the disintegration of the Soviet Union and eastern bloc nations, and the return of the radical right throughout Europe in the 1990''s. Our course readings combine secondary and primary sources, literature, as well as a wide range of cinematic and musical sources, in order to understand the evolution of European notions of race, national belonging, and political violence.</p> <p><strong><strong>Survey Requirement Met:</strong> </strong>Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7523,2021,1526,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-236','<div class="desc"> <p>This course covers the ruptures and changes which characterized Jewish life in Europe for over two thousand years. However, we will focus on the social, political, religious, and economic encounters between Jews and other European peoples in the modern period. To this end, the course will encompass topics such as: early migrations under the Roman Empire, Medieval scholarship and persecution, efflorescence in the Muslim Iberian period, the birth of Ashkenaz, the Spanish Inquisition, shtetl life, Jewish Enlightenment, urbanization, secularism and the rise of nationalisms, Hasidism, the Holocaust, and postwar Jewish life up to today. Readings will consist of primary and secondary material.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7524,2021,613,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-237','<div class="desc"> <p>In early modern times, popular conceptualizations of the intersection of gender and sexuality, ethnicity/race, and rank/class divided women from each other. Activist advocacy for women emerged from a debate on women''s nature to a debate on opportunities for women: to be educated, to write, to speak out, to preach, to express one''s individuality in dress and demeanor, or to work in one''s chosen occupation. For the transformation in political theory from Lockean family representation to Suffragette individual representation in the state, we shall explore the literature on "rights" from Wollstonecraft to United Nations declarations on global Women''s Rights &amp; current revival of American movement for Equal Rights Amendment. We shall experience together a diversity of films as students discuss the intersectionality of race, gender, class, religion, and sexualities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7525,2021,194,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-242','<div class="desc"> <p>A chronological and thematic survey of the Chinese civilization from neolithic times to about 1600. Major themes will include: the nature of the Chinese world order, family and lineage, gender issues, philosophical and religious transitions, political authority and its ideological underpinnings, dynastic cycles and broader patterns in socio-political movements, interactions with other civilizations, and the impact of technological and demographic changes over time. We shall use the comparative approach on specific themes to illuminate contrasts and similiarities between Chinese and Western societies, and take note of recent archeological finds and new scholarly interpretations to better understand China''s dynamic past and rapidly changing present.</p> <p><strong>Survey Requirement Met:</strong> Asia</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7526,2021,1603,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-245','<div class="desc"> <p>This course will look at the relationship of China to the world over the last 600 years. It will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Thirdworldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the level of interactions between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the "rise of the West," just as we will call into question the contemporary discourse on the "rise of China."</p> <p><strong>Survey Requirement Met:</strong> Asia</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7527,2021,1074,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-246','<div class="desc"> <p>According to legend, the Korean people were born from the union of the son of the "Lord of Heaven" and a bear-woman, with a good measure of garlic and mugwort aiding the process. From these mythic origins, tracing roughly 2,000 years of Korean history, we will end with the forced opening of the Korean peninsula and people in the mid-19th century. The main objective of this class is to impart an understanding of the major social, cultural, political, and intellectual developments that occurred along the way.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7528,2021,195,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-247','<div class="desc"> <p>This survey will examine Japanese history from the emergence of the samurai class in the 12th century, to the Mejii Restoration of 1868. We will begin by considering the origins, and rise to power, of warriors as a discrete social group. Next, we will look at the balance of power between the Kyoto court, the new warrior government in Kamakura, and the powerful Buddhist institutions that defined the culture of the Medieval period. We will then examine the disintegration of central authority under the rule of the Ashikaga shoguns, leagues, and other local attempts to organize independently, and the concomitant cultural efflorescence of the 15th and 16th centuries. The course will conclude by examining the political structures, popular culture, and social stratification of the early modern (Edo or Tokugawa) period.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7529,2021,944,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-248','<div class="desc"> <p>This course covers the history of Japan from the 1868 Mejii Restoration to the present, with particular focus on the emergence of modernity, the Pacific War, and popular culture. The first section of the course will examine Japan''s modern revolution in the Mejii Restoration, industrialization and modernization in the Mejii Period, and the development of Japanese colonialism. The second section of the course will focus on the Pacific War, the bombing of Hiroshima and Nagasaki, and the American occupation, with particular focus on the politics of gender and race. The third section of the course will look at Japan''s explosive postwar economic recovery and the consumer and popular culture it produced.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7530,2021,196,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-249','<div class="desc"> <p>Korea is unique, or so say the Koreans. In many ways, it is. Politically, of the democratic nations in the world, South Korea is one of the precious few to have achieved democracy through the blood and sacrifice of its everyday citizens, that is, from the bottom up. Economically, after the Korean War, Korea was one of the poorest nations in the world, ranking below sub-Saharan countries in terms of GDP; now it is a member of the G20. This survey will begin with the forced opening of the "Hermit Kingdom" in 1872, and conclude with the 21st century international phenomenon of K-pop.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7531,2021,1660,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensible for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7532,2021,1459,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-252','<div class="desc"> <p>This course offers a broad survey of Mexican religion from pre-Columbian times to the present. The course begins with the study of Nahua ("Aztec") spirituality and ritual and continues with an examination of major developments of the colonial period as indigenous European and African peoples came together with their many different beliefs and practices. We will study indigenous strategies of both resistance and accommodation to the imposition of Catholicism, the origins of the devotion to the Virgin of Guadalupe, the Mexican Inquisition, millenarian movements, missions, and women in the church in the colonial period. Our study concludes with the anti-clerical reforms of the late nineteenth- and early twentieth-centuries, the Cristero Rebellion, increasing influence of Protestantism, and the persistence of local religions in modern Mexico. Students will analyze historical documents, religious dramas, confessional manuals, Inquisition records, paintings, sculptures, and films in their examination of the history of religion and spirituality in Mexico.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7533,2021,2897,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7534,2021,2722,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-257','<div class="desc"> <p>A systematic examination of the history of anti-Semitism, beginning with the emergence of anti-Judaism in late antiquity, its transformation into theological anti-Semitism in the Middle Ages, and a racialized anti-Semitism in the modern world. In each period, students will investigate the socio-political contexts that gave rise to the fear of, hatred toward, and attacks on Jewish individuals and communities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7535,2021,197,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-258','<div class="desc"> <p>This course seeks to engage you in the fundamental problems of twentieth century Mexican history and introduce analytical frameworks for studying cultural politics. The central theme will be how the state and grassroots society negotiated the course of the nation and its political culture since 1875. We will critically examine the production of the dominant historical narrative and develop alternative ones that can help us understand the differences in the historical experiences of subaltern groups, including women, indigenous people, and <em>campesinos </em>within the Porfirian, revolutionary, and post-revolutionary periods. We will examine what is cultural about politics and what is political about culture through an interdisciplinary format, perspective and organization drawing upon the fields of history, anthropology, literature, and visual studies.</p> <p><strong>Survey Requirement Met:</strong> Latin America</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7537,2021,945,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-274','<div class="desc"> <p>A study of three aspects of the history of medicine: theory and practice from ancient times to the present; great doctors and healers, both male and female, examined in their social contexts; the effects of epidemics, such as the Black Death on the course of Western civilization. We will end with some historically-based speculations about the medical future.</p> <p><strong>Survey Requirement Met:</strong> Europe</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7538,2021,198,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-277','<div class="desc"> <p>This course explores the history of women as promoters of community health in the nineteenth- and twentieth-century United States. Although women have not traditionally held power in mainstream biomedical occupations and institutions, women have nevertheless been critical to health and healing in local communities as caregivers, activists, and practitioners. At times, working class women and women of color have also been demonized as carriers of contagion or even romanticized as repositories of traditional wisdom. Furthermore, women’s roles in community health have been heavily shaped by gendered and racial constructions of the body, disease, and wellbeing. Thus, while the focus of the course is on the social history of women’s health and healing, the theoretical framework of the course also aims to explore how ideologies of gender, race, class, and sexuality shape women’s relationship to community health as both caregivers and health-seekers. The course is organized by a set of common themes that cut across time, space, and racial/ethnic boundaries in U.S. History. Themes include: spirituality and healing; work and health; sexuality and reproduction; activism for health justice. An important goal of this course is to make connections between historical studies of women and health and present day community health activism. Much of the course and especially the community partnership component focuses on the leadership of women of color in shaping agendas for community well-being. In the past, course participants have worked with the organizations Black Women for Wellness, California Latinas for Reproductive Justice, Visión y Compromiso, and Promesa Boyle Heights. We will continue to work this year with women’s health organizations and the Southern California Library on a Reproductive Justice community partnership. In addition, we will welcome several community health activists &amp; scholars to the class as guest speakers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7540,2021,199,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-282','<div class="desc"> <p>The term "Muslim World" is often criticized as imprecise. After all, Muslims constitute a fifth of humanity and live on six different continents. Nevertheless, Muslims often describe themselves as constituting a single community with shared sets of concerns. This class engages these differing views through an examination of the lives of Muslims over the past two centuries of globalization, colonialism, post-colonialism, nationalism, and ever-changing technologies of transportation and communication. Our inquiry will concentrate on how Muslims were caught up in, and reacted to, and, in turn, influenced the Great Transformation that reshaped the entire world over the past two centuries. Dealing with issues from state building to women''s rights to radical militancy, this class considers the various features of what we might call Muslim Modernity.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7541,2021,849,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-283','<div class="desc"> <p>This course examines the role of peasants and tribal formations in the process of nation and state building in the modern Middle East. In addition to looking at some of the empirical and theoretical problems inherent in defining and writing about "peasants" and "tribes," we will also consider how nationalism complicates these issues even more. We will investigate the ways that rural populations were incorporated into, or excluded from, the processes of state-formation. Finally, we will look at how representations of peasant/tribe, in ideologies of state-building and nationalism, shaped social and political relations within some of the region''s nation-states. While we will discuss the region as a whole, we will focus most of our attention on two empirical cases: Iraq and Egypt.</p> <p><strong>Survey Requirement Met:</strong> Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7542,2021,200,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/200/hist-295','<div class="desc"> <p><strong>The Contested Ballot in American History</strong></p> <p>Voting is fundamental to American democracy. It is, one nineteenth-century reformer argued, “like breathing.” And yet across the nineteenth and twentieth centuries, vast numbers of Americans (at times even a majority of Americans) have been denied access to this fundamental democratic practice. This class investigates the curious and contested history of the ballot throughout American history. We will focus on both the formal rules governing the right to vote (state constitutions and federal interventions via constitutional amendment, SCOTUS decisions, and legislation) as well as the culture and practice of voting (ballot design, the timing of elections, and procedures around registration. The class will culminate with an examination of the state of voting in America in 2020 (the specifics to be determined as the election unfolds). </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7544,2021,201,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-300','<div class="desc"> <p>This course introduces students to the practice and writing of history through topical approaches. Students will explore methodological approaches to historical inquiry, conduct research projects, and improve their writing skills. Open to majors and minors only or by permission of instructor. Topics include:</p> <p><strong>Mexico-U.S. Borderlands</strong></p> <p>Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. Cross-Listed as: LLAS 304.</p> <p><strong>Christianity and Politics in America since 1945</strong></p> <p>Evangelicals and the Christian Right have become hot topics, but religion has long played an important role in the U.S. political arena. This junior historiography seminar will survey how historians have written about the relationship between Christianity and politics in America since the end of World War II. Much of the course will focus on histories of the Religious or Christian Right and its 1970s marriage with the Republican Party, which remains one of the most successful political partnerships in American history. But we will also trace the roots of this relationship in earlier histories about the role of the Protestant church in public life, Billy Graham''s rise to fame, and the work of Christians and other religious leaders in shaping U.S. engagement with the world during the Cold War.</p> <p><strong>The Fascist Revolution: Politics Culture and Society</strong></p> <p>This seminar closely studies the period known as Fascist Italy (1922 to 1945). Through a close analysis of the politics, culture, and society of Italy under Fascist dictatorship, we study the causes, character, and ramification of the Italian abandonment of democracy in the wake of World War I. Because it is a historiographic seminar, we examine the central debates of the field, such as whether Mussolini ruled primarily through coercion or consent, the extent of Fascist race ideology, and whether the regime was "modern" or "backward-looking." Other major themes include: Fascist cultural modernism, gender and Fascism, and the Italian road to empire and World War II. This course uses primary sources such as translated documents, memoirs, and diaries, as well as contemporary historical analyses. </p> <p><strong>Gender and Sexuality in Colonial Latin America</strong></p> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.<br/> <br/> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written. Cross-Listed as: LLAS 301.</p> <p><strong>Histories of the French and Haitian Revolutions</strong></p> <p>Many histories have been, and continue to be, written about these revolutions and they differ from each other substantially. This course examines this scholarly literature, taking into account the choices historians make as they compose their narratives. We will examine the roles of race, class, and gender in these accounts, why different events and social groups are featured centrally in some but not others. And we will consider such controversial criteria as "accuracy," "truth," "evidence," and even "fact" all of which are interpreted in numerous ways within the historian''s craft. </p> <p><strong>Histories of U.S. Empire</strong></p> <p>Was/Is the United States an empire, and if so, what kind of empire was/is it? This upper-level colloquium will familiarize history majors and other advanced students with scholarly debates over the history of U.S. imperialism and engagement in the world. Course readings draw from the writings of U.S. historians from the early twentieth century through the present. Particular attention will be given to the impact of the Cold War and the influence of the "cultural" and "transnational" turns on how historians have approached empire.</p> <p><strong>Interpreting Civil War, Emancipation, and Reconstruction</strong></p> <p>This junior colloquium will address major debates and approaches within the historiography of the United States Civil War, Emancipation, and Reconstruction. Students will explore how American racial politics and new scholarly approaches have shaped major debates over the causes and consequences of civil war and national reconstruction. The class will take both a chronological and topical approach to historiographic analysis. We will begin by reading work from the Dunning School and critical challenges to Dunning from historians on the Left, such as W. E. B. Du Bois in his 1935 study Black Reconstruction. To understand the impact of new methods and sources, we will examine the multi-decade collaboration of social historians called the Freedmen and Southern Society Project. In the second half of the course, we will explore more recent trends in scholarship, including economic history and cultural history, as well as gender and sexuality studies and critical race theory. Finally, the class will conclude by considering historical interpretations of Civil War and Reconstruction in U.S. popular culture, through film, fiction, and drama. Students will write their own historiographic analysis on a chosen topic within Civil War, Emancipation, and Reconstruction scholarship. </p> <p><strong>The Mexican Revolution</strong></p> <p>Studies of the Mexican Revolution have been at the forefront in the development of modern Latin American social, political, and cultural history. The studies have also contributed to comparative discussions in world history about the meanings of revolutionary experience in the twentieth century. However, historians and other social scientists have reached no consensus about the Mexican Revolution from its periodization to its actual existence. This seminar will examine the competing set of interpretations, alongside primary sources, to analyze the origins, course, and legacy of the Mexican Revolution. Prominent historiographical themes for the course include: conflict between elite liberalism and mass mobilization; agrarian reform and unionization within a capitalist project of development; corporate representation of social interests; the institutionalization of revolution; race, gender, and class in nationalist rhetoric; and the role of art, education, and science/technology in state formation. Cross-Listed as: LLAS 302.</p> <p><strong>Re-Assessing European Global Encounters </strong></p> <p>The twentieth century national movements of liberation, from modern European colonialism, initiated new histories of the previous early modern age of exploration (1300-1800), from the point of view of the enslaved, the conquered, the exploited, and the newly liberated. Each student will be writing a historiographical essay revealing changing interpretations of one distinctive global encounter. Historians are re-assessing, on the Mediterranean, both the Crusades and piracy and kidnapping. Scholars specializing in trade or colonialism of a particular nation-state, such as Portugal, Spain, Netherlands, England, and France are re-considering specific settlements and trading ports on the Atlantic and Pacific Rims. Class work will enhance student skills: we shall be discussing exemplary recent historical films and histories and we shall learn how to efficiently find diverse viewpoints through online and printed sources.</p> <p><strong>Reel History </strong></p> <p>This course will examine some of the ways that the history of France has been represented in films. Joan of Arc, The Return of Martin Guerre, Ridicule, The Rise to Power of Louis XIV, Danton La Nuit de Varennes, Abel Gance''s Napoleon, and Night and Fog are among the great movie classics to be analyzed. We will also deal with recent theoretical work on "historical" cinema. Are images as valid as written text when making meaningful connections with the past?</p> <p><strong>Writing the History of the Middle East </strong></p> <p>This course is a junior seminar on recent developments in the research and writing of history as practiced by professional historians of the modern Middle East. We will look at the history of historical writing about the region and the transformative developments in the field over the last thirty years or so. The objective is to cultivate your awareness of historiography and historical criticism. Historiography can be defined as the history of historical interpretation. Historical criticism refers to how we understand history as an object of study. To appreciate various modes of inquiry in the field, we will read exemplary texts embodying established traditions and new departures as well as critical works on the ideological roots of particular fields of history.</p> <p><strong>Writing World History</strong></p> <p>This junior seminar investigates various approaches to writing world history. The course is designed to help history majors understand historiography and historical criticism. By studying recent approaches to world history, students will learn how historical debate shapes the writing of history, how historians approach and critique each other''s work, and how different styles of historical research and writing have developed over time.</p> </div>','Unless otherwise noted, one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7546,2021,1174,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-309','<div class="desc"> <p>This course examines the southern region of the antebellum United States as a "slave society," that is, a society in which slavery was central to the region''s economy, and in which a powerful slaveholding minority held the reigns of political power. We will examine the rise of a "peculiar" institution of Southern slavery, and the impact of chattel slavery on southern households, political institutions, and cultural practices. How did the institution of slavery shape the lives of Southerners differently, depending on race, class, gender, and geography? In what ways did the centrality of an institutionalized system of human property shape the social relations and lived experiences of enslaved African Americans, common whites, slaveholding planters, and Native Americans of the South? How did these groups of Southerners draw upon religion, violence, and ideologies of sex and race both to challenge and reinforce the Southern social order? Finally, what did the South, as a region, come to mean to other antebellum Americans as sectional conflicts heightened in the 1850''s? Students will explore the social and cultural history of the antebellum South through primary documents, first-person narratives, film, fiction, music, and extensive secondary scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7547,2021,2629,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-311','<div class="desc"> <p>Americans have long idealized the frontier as an untrammeled backcountry, a mythologized landscape of “cowboys and Indians”, prairie and homesteaders, ranchers and sodbusters. In this course, we will draw on colonial and postcolonial theory to reinterpret these stories in the historical context of a set of encounters involving the Americas and the Americans - native and immigrant, from Europe, Asia, and Africa - with the rest of the world, contacts that began in 1492 and are still going on today. In the process, we will explore a diverse array of borderlands between people, environments, mythologies, and histories - spaces of interaction and reinvention. But these borderland spaces are fragile; contact zones devolve, again and again, into conquest, domination, genocide, and empire. Although this is a transnational phenomenon, this course is primarily concerned with the frontier in North America and particularly in the American West and in California. Along the way, we will also be doing our own original archival research, so students will have a chance to make their own mark upon the long history of the American frontier experience. </p> </div>','HIST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7548,2021,615,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-312','<div class="desc"> <p>The circulation of labor goods people and cultures between Africa, Europe and the Americas created an Atlantic World whose history transcends continental and national boundaries. This course examines the relationship between race rights and revolution during the Atlantic Age of Revolution that stretched from roughly the mid-eighteen to mid-nineteenth centuries. In particular we will explore how Revolutions in British North America, France and Haiti influenced the movement to end the slave trade and slavery in the Americas and galvanized slave revolts and other movements for Black liberation and human rights around the Atlantic World. A variety of readings including autobiography social and political history and ethnography will illuminate not only the history of the Atlantic World but new forms of scholarly writing that break the mold of national historical narratives. Themes include: slavery slave revolt the discourse of human rights resistance religion labor and shifting ideologies of difference in particular gender class and race.</p> </div>','One History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7549,2021,2630,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-316','<div class="desc"> <p>When we think of the World War II era and its aftermath in Southern California, images of freeways, airy tract homes, and classic Hollywood glamour often jump to mind. If we look a bit deeper, the Zoot Suit Riots, the scandal of Chavez Ravine, the destruction of public transit, and other more complex, and often "noir" images might emerge. Yet beneath both sets of images lie a set of crucial social, demographic, and political changes that marked Los Angeles''s emergence as an industrial, as well as cultural, center - changes that put the city on the front lines of many struggles revolving around Civil Rights, housing, and the future of American urbanism itself. In this class, we will explore the sunshine and the noir of mid-twentieth century LA, focusing on the ways cultural forms (such as the Central Avenue Jazz Renaissance, film noir, and modern architecture) crystallize crucial postwar social and political battles within this complex modern metropolis.</p> <p>Basic knowledge of twentieth century U.S. History is strongly suggested, but may be waived in exceptional circumstances.</p> </div>','HIST 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7550,2021,1021,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-328','<div class="desc"> <p>Ideas, politics, and society in 18th century Europe, especially France, where challenges to authority and tradition boosted confidence in reason and progress and eventually exploded the Old Regime. Particular attention will be given to the "republic of letters," of the philosophes whose mission was to bring about reform by "changing the common way of thinking." The role of women in this "salon" society will be examined, as will such controversial works as <em>Dangerous Liaisons</em> and the writings of the Marquis de Sade.</p> </div>','Satisfactory completion of at least one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7551,2021,851,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-330','<div class="desc"> <p>The Storming of the Bastille, the Great Fear, the Women''s March, War with the rest of Europe, the September Massacres, the King''s trial and execution, Robespierre''s Republic of Virtue, the Reign of Terror, the Thermidorian reaction, the rise and fall of Napoleon, the impact of the rhetoric of revolution overseas, the end of slavery in France''s colonies, the transformation of French colonial Saint Domingue from slave colony into the new nation of Haiti, and the meaning of "liberty, equality, fraternity" for our own time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7552,2021,204,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-336','<div class="desc"> <p>This course traces the creation and development of the modern Italian nation state from an idea in the early 19th century through its creation in the middle 19th century to its turn to fascism in the 20th century. We will study the challenges faced by Italian politics and society as Italy moved from a disparate group of separate states toward a unified government and culture. We take an interdisciplinary approach to history and look at films, novels, and art to understand the character of modern Italian culture society, and politics. Starting in the late 18th century, the course covers themes such as: the character and legacy of Italian unification, the Southern Question, Fascism, the Mafia and postwar parliamentary democracy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7554,2021,1703,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-344','<div class="desc"> <p>One of the fastest growing economies in the world and most rapidly urbanizing society, China has risen to a central role in the world today. Yet, this rise has been fraught with problems and tensions that threaten its continued development. This course looks at the social, political, cultural, environmental, and economic development of contemporary China (from the 1970''s to the present), and asks us: how do we know contemporary China? This is a hands-on research course in which students will learn how to find, evaluate, and use sources to understand present-day China from an interdisciplinary perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7555,2021,1022,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-345','<div class="desc"> <p>This course will be a research seminar that confronts the history of the Holocaust through in-depth investigations into survivor testimonies and commemoration and memorialization. The course will examine the genocide of the European Jews by the National Socialist regime, introduce students to the history of Europe from 1919 to 1945, and raise questions about the moral and ethical legacies of the Holocaust. During the semester, we will use a variety of visual and written sources to document and analyze the systematic and bureaucratic murder of European Jews by the Nazis. Using the survivor testimonies archived at the USC Shoah Foundation Visual History Archive and the museum installation at the Museum of Tolerance, we will interrogate the emerging fields of witnessing and testimony in relationship to the memory of the Holocaust and the phenomenon of Holocaust commemoration and memorialization. We will ask questions about how individuals and society assimilated to the experience of genocide: what narrative choices, what linguistic choices, and what visual choices did survivors and the larger culture make when remembering and commemorating the Holocaust? In this way, the course will be interdisciplinary, combining the methods and sources of History, Jewish Studies, Cultural Studies, and Art History.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7556,2021,2342,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-346','<div class="desc"> <p>China is now undergoing one of the fastest rates of urbanization in world history. Just thirty years ago, about 80% of the Chinese population lived in the countryside, mostly working in agriculture. Today, China''s population is over half urban, and the CCP has announced a new plan to speed up the urbanization process so that by 2020, 60% will be urban. Furthermore, well over 100 million migrants travel back and forth between the countryside and the city each year. While these numbers are impressive in and of themselves, it can be hard to understand what they mean for individuals, for particular social groups, and for the changing rural and urban landscapes. Nonetheless, this shift from a predominantly rural population to an urban focused society is both ambitious and fraught with problems. This class aims to give an in-depth and upÂ­-close look at this amazing social transformation through readings, class lectures, film, research projects, and, most importantly, in-country experience. This course begins with a short semester on campus at Occidental and continues with a threeÂ­-week trip to China, including a homeÂ­stay with a rural household. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7557,2021,2597,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-348','<div class="desc"> <p>This course will look at the long 1960s in China and their relationship to and influence on the global 1960s. Beginning with the rise of thirdworldism in the mid-1950s and ending in the 1970s, this period of radicalism reached its height with the tumultuous Cultural Revolution in China (1966-1969). Through memoirs, primary source material from the time, film, and secondary sources we will investigate why after years of political and economic consolidation the People’s Republic of China underwent such a dramatic and chaotic political upsurge. We will end the course by looking at the influence of China’s Cultural Revolution on the radical 1960s movements of the world, in particular in the United States and France and peasant movements in the third world.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7558,2021,852,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing especially on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization, art forms, social structure, and religion in the colonial and modern periods and considers native responses to contemporary issues such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7559,2021,1604,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or POLS 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7560,2021,2690,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7561,2021,1234,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-359','<div class="desc"> <p>This course traces the history of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire to provinces of northern Mexico and finally to the southwest region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, and nationalism. With particular attention to issues of race, gender, place, and power we will examine the Mexico-U.S. borderlands through Chicana/o history, Mexican history, and U.S. Western history as well as through fiction and art that explores the themes of boundaries, the body, and space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7563,2021,618,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-385','<div class="desc"> <p>This course explores histories of the Middle East and North Africa over the last century and a half through an examination of identity formation. In the simplest terms, this means we will study the ways that people in the region came to understand themselves and their place in the world. Specifically, we will consider the intersections of religion, nationalism, colonialism, economic and "minority" status, and gender/sexuality in the emergent nation-states of the region.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7564,2021,205,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-390','<div class="desc"> <p><strong></strong></p> <p> Research topics vary semester to semester.</p> </div>','Satisfactory completion of at least one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7565,2021,206,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-395','<div class="desc"> <p><strong>American History According to Hollywood</strong></p> <p>This class investigates the way movies have shaped Americans’ understanding of their history. Surveying major developments across the twentieth century and into our own, we will examine films as imaginative primary sources that reveal the attitudes and anxieties of past eras (e.g. concerns about race and ethnicity, global power, gender and sexuality). The last third of the class will turn to a more intensive focus on the way movies have functioned as secondary sources, offering powerful (if partial) interpretations of earlier eras. Here students will focus on a select number of topics or events (e.g. the immigrant experience, WWII, “the West”) and trace the changing historical interpretations the films present. Ultimately, we will evaluate how “cinematic history” compares to “written history” and by what interpretive or evidentiary standards or criteria we should evaluate it.</p> <p><strong>Disneyland and Los Angeles</strong></p> <p>In the summer of 1955, amidst the orange groves of Southern California and next to a brand-new freeway, Disneyland Park appeared. Broadcast across the country through a hit television program that premiered the previous year, the new theme park became an instant national media sensation, drawing on a long and varied tradition of American popular amusements. But, it was also an institution with deep roots in the specific culture and history of greater Los Angeles itself. In this course, we will trace the complex dialogue between the iconic amusement park and its urban environment in Southern California over the last half of the 20th century, carefully analyzing urban and social history, film, and literature to discover what Disneyland can teach us about the history, built environment, and culture of the strange, sprawling megalopolis that surrounds it. </p> <p>Core Requirement Met: United States Diversity</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7566,2021,619,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/300/hist-397','<div class="desc"> <p>Reading tutorials, off-campus internships, and research projects are among options available. Permission of instructor and department chair required.</p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7567,2021,620,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/400/hist-490','<div class="desc"> <p>In this fall semester seminar, students will write a major paper that involves research and analysis of primary and secondary documents. Papers may concentrate on a geographical area or take a topical approach, such as History of Science and Medicine, Women''s History, or Revolutions. In addition, the seminar participants will read works by historians reflecting on their craft. The seminar culminates with individual oral presentations on the thesis research to the Department and campus community. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7568,2021,1175,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/copy-of-hist-history/400/hist-495','<div class="desc"> <p>The honors seminar is designed for history majors who have completed the HIST 490 Senior Seminar and have been approved by the HIST 490 instructors to continue on as candidates for Honors designation. Over the course of the semester each honors thesis writer will work with the seminar instructor on advanced methodologies and multiples drafts to expand his/her original research and revise the thesis from a 25-page paper to a 40-page (or more) paper. The seminar will culminate with a program of oral presentations in which each student will share his/her work with the Department and the campus community.</p> </div>','HIST 490 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7571,2021,2867,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/core-core-program/courses/core-95','<div class="desc"> <p>The goal of this course is to provide students with knowledge, skills, resources, and opportunities that will support their academic success. Course content will include strategies and opportunities to: enhance academic reading and study skills, build campus social and resource capital for first year, transfer and first generation students; develop comfort with Oxy campus and college life; and facilitate social and academic integration. Through guest lectures and workshops, students will be introduced to campus resources and opportunities and offered academic techniques and strategies for successful learning. Open only to frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7572,2021,2728,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/core-core-program/courses/core-96','<div class="desc"> <p>This course is designed to expose students to mathematics and science to broaden their awareness ofthe research questions asked in those disciplines and to introduce skills and ideas scientifically shown to improve persistence in college especially in science and math majors. Students may acquire one semester unit of credit for attending eight on-campus events during a semester. Certain seminars and class meetings will be mandatory; students will select additional events from a list of events provided each year by the instructor. A short two-page paper is due on the last day of class. This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements. </p> <p>Students may take this course twice for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7573,2021,2903,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/core-core-program/courses/core-97','<div class="desc"> <p>This course is designed to expose students to some of the many cultures of the world, to prepare students for a future in the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one semester unit of credit for participating in eight "field experiences" in their local area. Students will select these from a list of destinations provided by the course instructor and are responsible documenting each field experiences using Moodle. Students will also be required to submit two short response papers related to their field experiences.</p> <p>This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> <p>Students may take this course twice, for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7574,2021,2723,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/core-core-program/courses/core-98','<div class="desc"> <p></p><p>This course is designed to expose students to some of the many cultures of Los Angeles, a vibrant microcosm of the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one semester unit of credit for participating in eight off-campus "field experiences.” Students will select these from a list of destinations provided by the course instructor and are responsible documenting each field experiences using Moodle. Students will also be required to submit two short response papers related to their field experiences.</p><p>This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p><p>Students may take this course twice, for a maximum of two units being applied toward graduation.</p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7575,2021,2724,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/core-core-program/courses/core-99','<div class="desc"> <p>This course is designed to expose students to the arts, to broaden their cultural horizons, and to instill in them a desire to expand their knowledge of and attention to the arts. In addition, the course is designed to prepare students for life-long learning, for engaging in their communities, and for having the basis for further exploration in the field of the arts. Students may acquire one semester unit of credit for attending eight on-campus events during a semester. Students will select these events from a list of events compiled each year by the Arts Committee; at least two of the events attended must combine an arts presentation with a lecture or discussion by the artist or a faculty member. A short two-page paper is due on the last day of class. This course is graded Credit/No Credit only and will not meet specific Major/Minor or Core requirements. Students may take this course twice, for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7576,2021,2653,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-107','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though very different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7577,2021,2546,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-108','<div class="desc"> <p>Taught in English. This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7578,2021,1507,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-109','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables, and riddles, to anecdotes, jokes, short stories, and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include: Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin, and Twitter. All readings and discussion in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7579,2021,2701,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-112','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes From the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7581,2021,2735,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-115','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7582,2021,2821,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-116','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and falliabiltiy. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7583,2021,2893,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-118','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7584,2021,1685,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-120','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses, </em>whose programmatic opening stanza links the the birth of the world, from formlessness and chaos, to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7585,2021,1642,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-131','<div class="desc"> <p>The worldview and beliefs of the early Slavs, particularly the Eastern Slavs, were a complex synthesis of influences: Indo-European mythology, Central Asian shamanism, Scythian animal worship, and, ultimately, a "paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600, in order to understand how these people viewed the world, and how this affected their lives and the development of Slavic culture. Communal village life, legends, folk genres and mythology, their sources, and their legacies, are examined. There is a close study of the phenomenon of the vampire, following its evolution from the Iron Age into 18th century Serbia, as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined, as well. In addition to analytical and historical texts, readings include tales of supernatural beings and phenomena, as well as testimony concerning encounters with the supernatural.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7586,2021,1508,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-132','<div class="desc"> <p>Many of Russia’s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements, while at the same time creating some of the most memorable texts of the 20th century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin. The course will introduce students to modern Russian literature, while, at the same time, will examine how Russian writers used science fiction in a completely different manner than Western writers. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7587,2021,1686,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-134','<div class="desc"> <p>How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist one century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun," and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency, known otherwise as the Russian Avant-garde. Topics include: poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7589,2021,2822,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-136','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. Authors may include: Tolstoy, Dostoevsky, Turgnev, Gogol, Goncharov, Bulgakov, Pushkin, and many, many others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7590,2021,1643,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-140','<div class="desc"> Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near death experiences throughout the Mediterranean. While immensely entertaining and, at times, ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in post-Â­classical literature, art, and film. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7592,2021,2516,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-145','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we''ll also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7593,2021,2702,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-150','<div class="desc"> <p><em>The Literary Mind and the Carving of Dragons</em> is a highly influential work on Chinese literary aesthetics, and its title also suggests two important constituents of the literary composition process by pre-modern Chinese authors: ideas and craftsmanship. By providing an introduction to classical Chinese literature through readings in translation, this course will integrate aesthetic appreciations and cultural understandings of the classical Chinese literature, and help students grasp the conceptions, styles and creative skills of different Chinese authors. The time range will cover the period from <em>The Classic of Poetry (Shijing) </em>through the Qing dynasty. Throughout the course, students will have a basic historical knowledge of the Chinese literary tradition, as well as a sense of how to go about interpreting Chinese literary texts. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7594,2021,2514,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-181','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women, such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7595,2021,1509,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-182','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell, and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7596,2021,2587,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-186','<div class="desc"> <p>The course will explore the unique sense of tragedy and the tragic in Iranian literature and culture, tracing this fundamental attunement to the world from its Ancient Iranian roots to Ferdowsi’s 11th CE defining national epic — the Book of Kings — through the poetic and intellectual foundations of contemporary Iranian culture — the 13th-14th CE poetic work of Sa’adi and Hafez — and through to modern Iranian music and literature. The course will analyze the specific characteristics of Iranian tragic culture, closely attending to the developing expressions of that tradition in each of the works and eras covered by the course. The course will also take up the long, contested cultural and political history between Iran and, broadly, the West, focusing on the complex and mutually defining interactions between Iran and, first, Ancient Greece and, then, Europe and the US— both before and in the wake of Western imperialism. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7597,2021,2652,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-187','<div class="desc"> <p>“The origins of the myth of Prometheus,” it has been said, “are unclear; even in antiquity the story is never told in full.” Right from the very beginning, then—so it would seem--Prometheus arrives on the scene of literature in a torn, dismembered condition, his story diffracted from the outset into a multiplicity of incoherent elements and perspectives: is he a mighty Titan, or merely a trickster? a divine benefactor, or a threat to cosmic peace? an embodiment of the power of thought, or a figure of its eternal helplessness and misery? The primary object of this course will be to survey some of the more impressive and surprising ways in which literature, art, and philosophy have engaged with, and contributed to, the prismatic strangeness of this myth of Prometheus--from the ancient songs of Hesiod and Aeschylus, to the Romantic soundings of Goethe, Shelley and Herman Melville’s <em>Moby Dick</em>; from its intellectual appropriation by Marx, Nietzsche, Heidegger and Freud, to its “plastic” rendering in the murals of Orozco, the statuary of Paul Manship, and the contemporary films of Ridley Scott and Alex Garland (director of <em>Ex Machina</em>). More tentatively, the larger goal of the class will be to consider whether the Prometheus myth in its entirety might not be guided by the reflection that absolute assertions of authority and power always imply their own undoing, and that sovereignty will forever be linked to suffering and to sorrow.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7600,2021,2326,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/copy-of-cslc-211','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different "scenes of writing," from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature''s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience and knowledge are produced, articulated and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7601,2021,1575,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-200','<div class="desc"> <p>Drawing upon literatures and language traditions from across the world, the immediate object of this course will be to help students develop a lively appreciation for, and analytic facility with, each of the major kinds of literary production (lyric, narrative, and drama), all of which we shall try to examine in their “traditional” forms, as well as in some of their more familiar contemporary ones (not only the lyric poem and the prose novel, but the popular song, the graphic novel, and the television series, too, will fall within the special compass of our inquiry). Beyond these immediate goals of familiarity and competence, however, the wider ambition of this course will be to develop students’ understanding of the crucial role that literary (and literature-based) forms play in the constitution of the cultures we inhabit and the various "subject-positions" we might occupy within them. To this end, we shall make ourselves familiar with some of the most important thinkers in recent literary and cultural theory (Foucault, Derrida, Kristeva, Sianne, and Ngai, to name but a few). Given the course’s broad international range, guest lecturers will be brought in throughout the semester to discuss the effect of reading works in the original language and to explore, more generally, the effect that the specific features of a language can exert over that delicate interplay of “literature, culture, and self” that forms the central subject matter of this class. This course serves as the Proseminar for CSLC, and is required for the major but is open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7602,2021,2823,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-201','<div class="desc"> <p>The words of literature, unlike soda cans, bits of data, or the modular classroom furniture of Johnson Hall, do not come to us in easily separable pieces; the words of literature, rather, always present themselves to us as parts of a greater whole, as participants in this or that literaryFORM: a poem, a play, a novel, a song... In this class, we shall set aside the usual preoccupation with the meaning of the words of literature, to investigate instead the various effects that different literary forms exert upon us. What, for instance, do narrative forms --from Babylonian epic to the experimental prose of David Foster Wallace and Karl Ove Knausgaard--tell us about the kinds of worlds that are ours to inhabit in our daily lives? How do the poetic forms of (say) the ballad, the haiku, the sonnet or pop song inflect the manner in which we every day take up our existence? How does drama--from Ancient Greek tragedy to Japanese <em>noh</em> to the theatres of the avant-garde, the cruel and the absurd--open up for us the experience of all those "others" with whom we share this life? By the end of this class, it is hoped that students will have developed not only a feeling for literature in its many forms, but reciprocally, an appreciation for the richness of experience such forms of feeling can bestow upon us.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7606,2021,1644,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-210','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-78) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with major figures such as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as the unprecedented boom in popularity of physiognomy around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. Concluding with the rise of Nazism and Nazi attacks on modern art as “degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. All readings and discussion will be in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7607,2021,1576,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-220','<div class="desc"> <p>This course is concerned with the cultural politics of memory and trauma after 1945. We will start with basic questions, such as: whose memories are sought, believed, and commemorated in the public sphere? What problems do traumatic events present for those attempting to represent them? Is trauma a useful cultural concept? What are the differences between individual and collective memory? We will then identify the recent fascination, especially in European and American culture, with the phenomena of trauma, suffering, and victimhood, and focus on the impact on Jewish identity (in various countries), as well as the collective memory of Germans, after 1945.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7612,2021,2327,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-232','<div class="desc"> <p>This course focuses on Mikhail Bakhtin''s theory of language and the novel. Bakhtin''s writings are a synthesis of diverse theoretical approaches, including NeoÂ­Kantian philosophy, structuralist linguistics, the theory of novelistic discourse as a polyphonic medium, and the notion of carnival as a subversive cultural force. Furthermore, Bakhtin''s approach to the text reveals prose fiction, and, to some degree, nonÂ­fiction, as a unique medium through which language explores human consciousness in both time and space. In this course, Bakhtin''s theories are studied in order to understand more deeply the significance of the novel, and novels are studied in order to better understand Bakhtin''s theories. Works as diverse as Fyodor Dostoevsky''s <em>Crime and Punishment</em>, Venedikt Yerofeev''s <em>Moscow to the End of the Line</em>, Umberto Eco''s <em>Foucault’s Pendulum</em>, and Manuel Puig''s <em>Kiss of the Spider Woman</em>, are examined through the Bakhtinian lens in order to broaden the students'' understanding of the text as a polyphonic phenomenon. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7613,2021,1577,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-233','<div class="desc"> <p>Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939, when the Soviet Union was busily partitioning Poland with Nazi Germany by secret agreement. This course examines the cultural history of Russia and the Soviet Union, in specific regard to its evolving theories of language, literature, and cultural phenomena during the early 20th century. Particular attention is paid to Russian formalism, poetics, and semiotics, as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence, mutual East-West suspicion, social repression, and exertions of state power through propaganda and censorship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7614,2021,2747,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers: Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7615,2021,2894,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-237','<div class="desc"> <p>Marcel Proust’s <em>In Search of Lost Time </em>is considered to be one of the greatest novels ever written. Two 20th century thinkers—an Eastern European philosopher Merab Mamardashvili and a French thinker Gilles Deleuze —argued that Proust’s novel is a philosophical machine: an artificial organ that allows one to gather and re-construct the self. Mamardashvili was the only Soviet philosopher to study Proust’s novel and respond to its Western European interpretations from the perspective of Eastern Europe. He also used the novel to expose and explain the more obscure aspects of the Soviet and Russian worldviews. This course puts to the test Deleuze’s and Mamardashvili’s interpretations of this novel by considering them in conjunction with significant portions of <em>In Search of Lost Time. </em>All of the readings and discussions will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7616,2021,1510,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-241','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. Students who have completed Latin 102 or the equivalent can take this language intensive version of CSLC 241/CLAS 241 where we will read selections from Seneca’s <em>Epistulae ad Lucilium,</em> as well as Horace’s <em>Satires</em>.</p> </div>','LATN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7617,2021,2570,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-246','<div class="desc"> <p>This interdisciplinary course introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. Taught in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7618,2021,2736,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-247','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7619,2021,2824,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-248','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 BCE sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 BCE when he brought his army across the Rubicon river into Italy from Gaul. </p> <p>Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as <em>On the Republic</em> and <em>On the Laws</em>, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators seeking to restore the old order assassinated Caesar in 44 BCE. They were in turn destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.</p> <p>Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise <em>Discourses on Livy</em>, and John Adams (the “American Cicero”), whose 1787 work <em>Defence of the Constitutions of the United States of America</em> owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7620,2021,1645,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensible for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7621,2021,2748,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-252','<div class="desc"> <p>This course will focus on two foundational texts of Chinese civilization: The <em>Analects </em>and the <em>Zhuangzi</em>. The <em>Analects</em> is an ancient Chinese book composed of a collection of sayings attributed to Confucius and his disciples, and is traditionally regarded as one of the central texts of Confucianism. <em>Zhuangzi</em>, named for its traditional author, “Master Zhuang” (Zhuangzi), is one of the most important Daoist writings. When the <em>Analects</em> emphasizes that people should reconcile their desires via rituals, and fulfill moral and personal duties in order to ensure the welfare of the society, <em>Zhuangzi</em> promotes carefree wandering and following one’s own nature. By reading and comparing these two texts, this course will help students understand and grasp their central concerns, philosophies, and substantial influences on Chinese and East Asian thought and values throughout history. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7622,2021,2749,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-270','<div class="desc"> <p>This course will explore the psychology and biopolitics of sexual behavior in literature and film. The first unit, the couch, focuses on psychological theories of sexuality based on works by Freud, Foucault, Lacan, and Derrida. The second unit, the court, explores the biopolitical demands and legal consequences of acting out our sexual impulses. This unit, with texts by Agamben and Esposito, traces the dehumanization, exploitation, and control of the body in authoritarian regimes. The third unit, the confessional, discusses the reproductive bias of spiritual or religious systems and the prohibition of sexual expression. This unit presents films with scenes or plots illustrating the struggle between body and mind. The three units together will ask how sexual impulses disrupt a given socio-political order. Students will evaluate the solutions to disruption offered by psychology (compromise), the court (crime and punishment according to a given society''s laws), and religion (confessing sex acts to a religious official who will condemn them, impose penance, and absolve the transgressor). </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7623,2021,1578,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-280','<div class="desc"> <p>In this course, we shall attempt to come to terms with three of the most important - and provocative - philosophers of the last two hundred years, philosophers without whom the great majority of contemporary literary and cultural theory (and much art and literature, as well) would, essentially, be unthinkable. Significantly, all three of these philosophers habitually turned to ancient Greek tragedy in the formulation, articulation, and further elaboration of their thought. In this class, we shall therefore attempt to use the experience of Greek tragedy, in all its ecstatic strangeness, as a powerful point of entry into the difficult yet crucial works these philosophers have bequeathed to us. Major texts to be covered include: the plays of Aeschylus and Sophocles, <em>The Phenomenology of Spirit,</em> <em>The Birth of Tragedy,</em> <em>Thus Spoke Zarathustra,</em> <em>Being and Time,</em> and <em>Introduction to Metaphysics</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7625,2021,1688,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-283','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7627,2021,2825,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-285','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7628,2021,1646,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-286','<div class="desc"> <p>In this class, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth’s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home" at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7630,2021,2675,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-295','<div class="desc"> <p>Topics vary semester to semester. The object of any of the courses in the series entitled “Hear Now” is to introduce students to the transformative effect that contemporary artists and thinkers can have on the way we think about our world-- its past, its present its future. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Hear Now: Jean Luc Nancy and the Aesthetics of Community</strong></p> <p>In this class, we shall be examining the work of one the world’s most important living philosophers, Jean Luc Nancy. Special emphasis will be placed on the close relation Nancy seeks to draw between our so-called “private” aesthetic experiences—the painting that arrests us, the bar of melody that makes us tremble, the line of poetry that haunts us—and our sense of “being in community” (the sense, that is, that our supposedly singular existence is always already plural, is always already shared out with others). Beyond the reading of Nancy’s own works, we shall also be looking at the work of some of his most important predecessors on the question of art’s relation to the community (Kant, Hegel, Benjamin, Adorno), as well as the works of those thinkers who have engaged most directly with his ideas (Derrida, Agamben, Esposito), and those who have explicitly sought to oppose him (Ranciere, Badiou, and others). </p> </div>','CSLC 200, or CSLC 283, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7632,2021,2750,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-300','<div class="desc"> <p>In this seminar-style course, CSLC majors (acting under the guidance of the course instructor) will be asked to research, and then report to one another, on contemporary trends in literature and literary theory. It is hoped that the skills developed in this course, as well as the content mastered within it, will help CSLC majors in the eventual formulation (and successful completion) of their Senior Comps. Only open to CSLC majors with junior standing, or by instructor permission.</p> </div>','CSLC 200 and two additional courses in CSLC ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7634,2021,3523,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7635,2021,1579,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7636,2021,1648,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/400/cslc-490','<div class="desc"> <p>This course will guide students through the research and drafting of the Senior Comprehensive Project, and will provide students with feedback on work in progress. Open only to senior CSLC majors. Students must enroll in CSLC 490 both fall and spring for a total of 4 units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7639,2021,91,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-1','<div class="desc"> <p><span style="color: #282b2c;">This course offers students the opportunity to analyze the sociohistoric, legal, and cultural tensions surrounding various (im)migrant communities in California. Students will explore the various waves of (im)migration across time to understand the diverse communities of California. Students will also build critical and interpretive capacities through the examination of state policies, statistics, and various historical and empirical studies. Additionally, through the construction and revision of several expository, research-based writings on immigration, students will hone their writing, argumentation, and presentation skills.</span></p> <p><span style="color: #282b2c;">This course is part of the </span>California Immigration Semester<span style="color: #282b2c;">, and is open only to first-year students simultaneously enrolled in CSP 1, CTSJ 105, DWA 282 and SOC 105.</span></p> <br/> </div>','Open only to first year frosh ','CTSJ 105 , DWA 282 , and SOC 105',NULL);
INSERT INTO course_descriptions VALUES(7640,2021,92,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-10','<div class="desc"> From The Freshmen (1925) to Rocky (1976) to Bull Durham (1988) to Remember the Titans (2000) to Blue Crush (2002) to Bend It Like Beckham (2002) to The Fighter (2010) sport has been a central theme in film for close to a century. This course will explore such topics as race and class, gender, sexual orientation as depicted in sport film. Students will explore additional topics including motivation, personality, friendship, competition and group dynamics through film (an additional two hours per week is spent viewing films).<br/> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7641,2021,93,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-11','<div class="desc"> <p>Energy made the modern world, and we depend on it for the future we want. It drives many of the great challenges to human society and our future. During your lifetime, we have experienced continual upheavals in the Middle East that are largely driven by global petroleum markets, the near meltdown of the Fukushima Daaichi nuclear facility, two of the three largest oil spills in history, the controversy of climate change, and many other geopolitical and environmental impacts associated with the extraction, transformation, transport and consumption of different forms of energy. This course is an introduction to a deep understanding of the science behind the headlines, and its importance to governing, economic sustainability and growth, and to our collective future, so that we can make informed, responsible decisions.</p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7642,2021,94,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-12','<div class="desc"> Comic books were once viewed as the lowest form of mass culture, and even considered an intellectual and moral threat to young people. Today, "graphic literature" is a celebrated medium supported by a mainstream apparatus of publication and criticism. We will study the history of this hybrid medium, from its origins as disposable children''s fare to its current array of serious adult genres (novels and short stories,memoir, documentary journalism, and biography). The emphasis will be on American comix, but some attention may be given to international works in translation. This course may be particularly attractive to students interested in the creative arts and humanities,but the variety of course texts and contents should appeal to students with broad topical interests in 20th century history and culture. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7643,2021,95,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-13','<div class="desc"> Community is something we largely take for granted. It is a notion around which we organize our lives, as we all belong to and participate in various communities—from our neighborhoods, to our interest groups, to our nations—yet, at the same time, it is a notion we often struggle to understand or explain. What is a community, exactly; how and when do we belong to one, and what does such belonging mean to our sense of personal and social self? Literature has long meditated on these questions, from essays on the meaning and nature of community to stories about different communities, and their struggles to articulate and develop their shared sense of purpose. This course will read through a selection of these efforts, from essays by Raymond Williams and W.E.B. Du Bois to novels by Thomas Hardy and Karen Rei Yamashita, with the goal to understand better how different communities come into being, what they aim to accomplish, and how or why they succeed and fail. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7644,2021,96,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-14','<div class="desc"> In this course students will study the writing and rhetoric of nature and wanderlust, with particular emphasis on California as a place of exceptional natural beauty and a locus of adventure in the cultural imagination. We will read literature, critical theory, scientific texts, and culture writing in order to explore nature from the inside out--in other words, from individual affective and psychological relationships to nature to the broader effects of nature on culture and identity. In keeping with our theme, we will not only study these ideas inside our virtual classroom; we will also incorporate our own individual adventures in nature, in California or elsewhere. Hand-in-hand with the study of nature, this course will provide intensive training in writing at the college level, with assignments designed to deepen your understanding of our course topics while focusing on specific elements of successful academic writing. This CSP is part of the California Environment &amp; Conservation Corps Oxy Immersive Semester. All seats will be reserved for students who followed the enrollment instructions on the Oxy Immersive Semester page. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7645,2021,97,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-15','<div class="desc"> <p>More than simply a "god of wine," Dionysus was for the Ancient Greeks a god of ecstatic self-abandon, of gushing fertility, of violent dismemberment and unexpected rebirth. In myth he was attended by raving Maenads and mischievous Satyrs; amongst humans he was worshipped with festive dances, communal shouts, ritual obscenities, and (perhaps most importantly) with poetry -- with the literary genres of ode, comedy and tragedy that were invented specifically to honor him. What could be farther, we might ask, from the cool, reasonable practice of philosophy than this wild, uncanny, irrational god? And yet, as we shall see in this class, this reckless god of madness and poetry stands at the foundation of some of the most important ideas in modern philosophy -- Hegel''s phenomenology of spirit, Nietzsche''s will to power, Heidegger''s philosophy of Existenz, Bataille''s notion of excess, and Derrida''s "non-concept" of differance. Beginning with an exploration of Dionysian poetics in Ancient Greece, this course will attempt to show what thinkers like these found so inspiring in this ancient god, and what the writers and thinkers of our own time might yet find in him still.</p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7646,2021,98,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-16','<div class="desc"> In this course students will develop a sophisticated understanding of the nature and process of scientific inquiry and communication, tracing the development of scientific information from original measurements to online broadcasts. Students will hone the skills necessary to evaluate and utilize scientific information reported in both peer-reviewed journals and popular media sources. Practice in reading primary scientific articles for comprehension, writing clearly about scientific topics for a broad audience, and delivering engaging scientific presentations will be a major focus of this course. Overall, students will gain perspective on how scientific knowledge is established and communicated to inform the actions we take as a society and in our personal lives. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7647,2021,99,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-17','<div class="desc"> This course will introduce key concepts and topics of Slavic folklore and mythology, and consider their philosophical ramifications. We will focus primarily on the historical accounts, legends, customs, and fairy tales of Eastern Slavs (present-day Russia, Ukraine, and Belarus), but will also discuss Central Asian shamanism and Scythian female warrior culture. We will analyze representations and adaptations of these myths and rituals in literature, film, and art. No background knowledge required. All readings and discussions are in English. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7648,2021,101,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-19','<div class="desc"> According to G.A. Smith in his Historical Geography of the Holy Land, Jerusalem “stands aloof, waterless, [and] on the road to nowhere.” Yet, despite its geographic, agricultural, and economic limitations, Jerusalem has been transformed into a city of tremendous religious significance. This course will examine the cultural history of Jerusalem over three millennia, primarily as the symbolic focus of three faiths: Judaism, Christianity, and Islam. By examining the artifacts, architectural monuments, and iconography of Jerusalem in relation to written sources, students will explore the dynamic relationship between the real and the mythic Jerusalem. Students will compose papers involving close readings of primary sacred literature; cross-disciplinary engagements with texts, lived traditions, and archaeology; and implications of the historical evolution of the city of Jerusalem on the middle east crisis and political situations of modern Israel. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7649,2021,102,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-2','<div class="desc"> This is a course designed to immediately confront incoming Occidental students with the urgency of the contemporary global crisis embodied by forced migration, refugee flows, and statelessness. The essential conundrum students will be forced to face is how denial of basic rights produces such expulsions and, thus, how we must collectively think about how broader struggles for freedom, equality, and democratic representation are essential to counteracting the forces that impel expulsions at the global and local levels. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7650,2021,103,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-20','<div class="desc"> <p class="sc-BodyText">In this course we will explore the connections between race/ethnicity and American politics, with particular attention to current events and issues. The course will begin by examining the social construction of race/ethnicity, and the role that American political institutions have played in its construction. Then, drawing on cutting-edge research in Political Science and Sociology, we will learn about how and why race has become a central fault line in American electoral politics. We will also think critically about the extent to which the U.S. is a “democracy,” given the persistence of racial inequalities, and the potential to make a more equal and just society.</p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7651,2021,105,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-22','<div class="desc"> <span style="background-color: #ffffff; color: #222222;">This course will examine various texts from different genres including popular literature, digital media, and scholarly essays, which seek to theorize the importance of standpoint and location as a way of forming political alliances along the intersections of gender, race and class. Long established arguments in support of identity and intersectionality have advanced critical examination of the varying systemic inequities marginalized groups experience, however, in 2020 we see a new identity politics rooted in whiteness and seemingly fueled by notions of white supremacy. Questions will be asked about the changing face of identity politics. Are we in a post-identity politics age? Or as some scholars contend does identity politics distract us from issues such as the growing income gap between the rich and everyone else? Has intersectionality been redefined to the point of irrelevance? What identity groups should be encouraged or discouraged, and what actions based on identity can aid or impede democratic justice? Students will engage in discussion, critical reading, and written analysis introducing vigorous academic discourse as essential to the first-year college experience.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7652,2021,107,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-24','<div class="desc"> Norman Mailer described Los Angeles as a “constellation of plastic.” John Fante called it a “sad flower in the sand.” Is Los Angeles really just “72 suburbs in search of a city,” as Dorothy Parker claimed, or is there something else brewing beneath the beautiful, sunny skies? We’ll explore (through art, films, and books) 20 th and 21 st century Los Angeles as both a real and imagined location. Through the completion of five short papers and one research paper, you’ll craft your own conceptual “map” of the place. If all goes well, there may even be an extra credit field trip or two. Required texts will include Walter Mosley’s Devil in a Blue Dress, Joan Didion’s Play It As It Lays, Nathaniel West’s The Day of the Locust, Evelyn Waugh’s The Loved One, Helena Maria Viramontes’s Their Dogs Came With Them, Kate Turabian’s Student’s Guide to Writing Research Papers (5th edition), and an assortment of short readings (both fiction and non-fiction/historical). </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7653,2021,108,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-25','<div class="desc"> <span style="color: #333333;">The utopian instinct â the desire to imagine a perfect society without war, violence, suffering, or injustice â is a fundamental human impulse. Images of political perfection can be found throughout cultures and across history. Yet, since the middle of the twentieth centuries, dystopian nightmares seem to occupy the political imagination far more frequently. Are utopias naÃ¯ve acts of wishful thinking at best and totalitarian blueprints at worst? Or do contemporary political challenges, from economic inequality to climate change, demand new forms of utopian thinking? Looking at utopias and dystopias in both political philosophy and literature, this course will explore these themes, with the goals of understanding not only the particular utopian dreams and dystopian nightmares, but also the broader functions and goals of politics and political theory. Reading selections from Plato, Thomas More, Margaret Cavendish, Karl Marx and Friedrich Engels, Aldous Huxley, Octavia Butler, as well as studying actual utopian movements and communities, this course will also critically examine cornerstone political values, including, freedom, equality, community, hope, and justice.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7654,2021,110,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-27','<div class="desc"> <span style="background-color: #ffffff; color: #282b2c;">This course will explore the diverse forms of visual culture and artistic practice since 1945, with a special focus on LA and Southern California. We will investigate questions about artistic identity, the status and function of art, and the changing nature of artistic practices in the wake of the social, cultural and economic changes from the 1960s to today. We’ll focus on new forms of art practice, and ways artists and cultural practitioners engage with and shape movements advocating for civil and human rights, environmental and social justice, and art world politics. engagement with contemporary movements advocating for civil and human rights, the environment, and the politics of the art world. Co-requisite: This CSP is part of the Arts in Los Angeles Oxy Immersive Semester. All seats will be reserved for students who followed the enrollment instructions on the Oxy Immersive Semester page.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7655,2021,111,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-28','<div class="desc"> <span style="background-color: #ffffff; color: #282b2c;">In this course students will consider the moral dimensions and nature of our relationships to one another, paying special attention to the relationship between healthcare workers and their patients. Readings will be drawn from both historical and contemporary philosophical accounts of what we owe to one another as people, and the responsibility to and value of being “with” one another. Co-requisite: This CSP seminar is part of the PPE Portrait Project Oxy Immersive Semester. All seats are reserved for students who followed the enrollment instructions on the Oxy Immersive Semester page.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7656,2021,1210,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-29','<div class="desc"> <span style="background-color: #ffffff; color: #282b2c;">Societies and individuals are shaped by experiences of chaos and suffering. Yet, modern conceptions of suffering and chaos are seen as weakening people or societies. This course will explore the many examples of how chaos brings about reform, revolution, and re-imagined forms of resiliency. We will explore examples of post-war and post-disaster scenarios as understood by historians, scientists and psychologists, and consider the ways in which suffering transforms individuals and can generate healthy and adapted systems. Final projects will conclude with a modern application of theories and examples from class and discussion, either personal or societal, that explore ways that chaos and suffering can be transformed to help build a better you or a better world.</span> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7657,2021,1008,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-2s','<div class="desc"> Seminar portion of CSP 2: Expulsions: Un/documented Migrants, Refugees, and the Stateless. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7658,2021,112,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-3','<div class="desc"> We often think of popular culture as a kind of distraction; we watch films or read novels to escape the real world and its problems. If this were the case, there would be no point in studying monsters in literature and film. This course will begin by rejecting these assumptions. When we examine the history of the idea of the monster and look closely at particular modern monsters, such as Frankenstein''s monster and Dracula, we can see that the horror they inspire concerns certain social and political anxieties: 1) anxieties about the purity and impurity of race, nation, and culture; 2) anxieties about who, within a community, belongs and doesn''t belong (and how this belonging is defined); 3) anxieties about those who appear unable or unwilling to assimilate and are defined as a threat to the body in which they have no place. Novels and film dramatize these anxieties in ways that allow us to understand both how they arise and the terrible consequences to which they have often led. Finally, we will ask why race is foregrounded in the contemporary zombie film (a genre that has its origins in the former slave colony of Haiti) and what reality is captured in one its most important conventions, the "necessary" killing of children. We may discover that these forms of popular culture reveal what is most disturbing and dangerous about the societies that produce them, not least our own. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7659,2021,113,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-4','<div class="desc"> <p>The Roman emperor Nero reigned from 54 to 68 CE. According to ancient accounts, he was a madman. He murdered his own mother, assassinated opponents, burned down sections of the city of Rome, and executed Christians. He was also a poet and a singer, performing to packed theaters. Most people, unaware of his dark side, loved him for his extravagant and popular style. But those closer to him feared and hated him. A group of them conspired to assassinate him, including the philosopher Seneca, and the poet Lucan, who was a friend of Nero''s from youth. We shall read works by these and other authors in order to try to see Nero and Neronian culture through the eyes of ancient historians, such as the senator Tacitus and the Jewish general Josephus, biographers, such as Suetonius, philosophers and tragic playwrights, such as Seneca, satirists, such as Persius, and comic novelists, such as Petronius.These ancient works will open up a variety of questions relevant to us now,such as: What is the role of the arts in a time of tyranny? How do contemporary concerns color the work of historians writing both during and decades after the period they are describing? How should philosophers and other "intellectuals" respond to a tyrant?</p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7660,2021,114,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-5','<div class="desc"> <p style="margin-right: 0in; margin-left: 0in;"><span style="background-color: #ffffff; color: #000000;">From social media to high-frequency trading, from self-driving cars to recidivism prediction, computers have pretty much taken over our world. While technology has given us Netflix and Tinder, it has also brought new problems to society. Computational gerrymandering and the subversion of democracy through targeted social media campaigns continuously make headlines. Algorithms that know you are pregnant before you tell your parents, or that discriminate against people of color in beauty contests, are no longer science fiction but reality. How did we come to create our new computer overlords? And more importantly, what do we do now? Reading broadly from scientific and news articles as well as research and personal blogs, students will complete the course with an understanding of the societal problems that algorithms try (and often fail) to solve, and gain a healthy skepticism for purely technological solutions to complex issues.</span></p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7661,2021,115,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-6','<div class="desc"> Disease prevalence, severity, and treatment varies across sociodemographic groups. Understanding why health disparities occur is key to determining how inequalities might be alleviated. Central to detangling health disparities are psychological, socio-cultural, cognitive processes, and behaviors that are related to ethnic, cultural, and gender identity experiences. The focus of this course is on research that a) describes health disparities, b) investigates factors that explain differences, and c) proposes interventions to treat at-risk populations. This course will emphasize the theme of equity in health across multicultural groups.Disease prevalence, severity, and treatment varies across sociodemographic groups. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7662,2021,116,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-7','<div class="desc"> What is Bohemia? Variously construed as a space, a style, a phase, and a form of subculture, the concept of Bohemianism captures images of rebellion, artistic production, urbanity, youth, altered states, and sexual experimentation. This course tracks the history of Bohemia and bohemians from their origins in nineteenth-century Paris, London, and Berlin to the twentieth-century United States. Tracking a cast of characters including hipsters, hippies, outcasts, queers, punks, pachuchas, starving artists, and beatniks, we will analyze historical writings, literature, music, and film while asking if the twenty-first century still has the time and place for bohemia. </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7663,2021,117,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-8','<div class="desc"> This course interrogates the relationship between religion and violence. Through a survey of the scholarship on religion and violence and a series of focused studies on topics like the "revolutionary suicide" at Jonestown, the Cristero Rebellion in Mexico, and 911, this course will offer a broad overview of religion and violence in the Americas. Using these case studies, we will ask a series of analytical questions: Can religion motivate violence, or do they merely sanctify it? What are the sources of religious authority (such as leaders, scripture, tradition, and ritual practice) that can militate for or against violence? And what kinds of speech and action are properly understood as violent? </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7664,2021,118,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/fall-writing-seminars/csp-9','<div class="desc"> <p style="background: white;">In this course, students will explore writing as a practice that is socially constructed by people across time and space and within specific cultural contexts. To do this, students will learn to analyze writing beyond the more familiar approaches of textual analysis, which is to interpret and critique. In these familiar cases, writing is understood as a final published product with a single or small group of authors. Drawing from theoretical frameworks that position writing as a social practice, we will explore the larger inquiry: How have Asian/American communities used writing and rhetoric to respond to social injustices? Students will read qualitative studies that demonstrate how methods of textual analysis (e.g. discourse analysis, textual analysis, narrative analysis, rhetorical analysis) can be used as analytical lenses to trace the diverse texts and literacy practices of various communities. We will also discuss the limitations of these methods by exploring the scholarship in cultural rhetoric that critique traditional ideas of what counts as writing and rhetorics of resistance. Using these tools and analytical framework, we will take up the following inquiries throughout the semester: What literacy practices and texts have Asian/American communities developed historically to respond to social inequity? What are contemporary modes of digital writing or hybrid genres of writing that Asian/American communities have used to respond to social injustices affecting their communities? How can archives be used to explore how Asian/American communities in the U.S. have used writing to enact social change? How have Asian/American communities used writing to respond to social injustices on a personal and political level? What role has gender and race played in reading what is defined as writing and rhetorics of resistance?</p> </div>','Open only to first year frosh ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7665,2021,522,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-51','<div class="desc"> <p style="margin: 12pt 0in; line-height: 115%; background: white none repeat scroll 0% 0%;">We will learn how the mathematics of chaos helps us to better understand science, economics, psychology, and our environment. Open only to first year frosh.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7666,2021,524,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-52','<div class="desc"> <p class="sc-BodyText">This course examines the relationship between music, sound and the environment. In the first part of this course we will review evolutionary theories of music-making among early homo sapiens and of acoustic communication among birds and mammals. Later, we will explore case studies of musical traditions from around the world that mediate relationships between humans and their surroundings. Finally, we will consider how music production in the Anthropocene relates to environmental sustainability. Here we will focus on the environmental footprint of human sound production as well as the role of music in contemporary environmental protest movements.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7667,2021,525,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-53','<div class="desc"> <span style="background-color: #ffffff; color: #222222;">This seminar is designed to explore how teaching and learning has been framed not only in popular culture, but also in U.S. educational policy and teaching best practices. We will begin the class reading educational narratives in genres such as memoir, essay, novel, and case study. Some authors we will read include Mike Rose, bell hooks, and Richard Rodriguez. To expand our understanding on how students learn and how one''s identity informs learning, will read </span><span style="background-color: inherit; color: #222222;">educational research and theories of student learning and identity. Some </span><span style="background-color: inherit; color: #222222;">questions our class will explore include: </span><span style="background-color: inherit; color: #222222;">What are popular narratives of teaching and learning in the U.S.? How have these narratives shaped students'' and their identity? As we explore these questions, students will be guided through the reading, research, and writing process. By the end of the semester, students will have gained a stronger understanding of the research and writing process. Students who seek to learn more about their own learning experiences or are thinking of pursuing teaching may find this course of particular interest.</span> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7668,2021,526,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-54','<div class="desc"> <span style="color: #000000;">This course studies China''s cultural, political and social development in a global setting from the early 19th century to the present. It delves briefly into China''s historical background prior to its opening to the Western world forced by Britain in the Opium Wars, before exploring the profound changes brought by globalization. Western influences in China, from Christianity to Marxism, will be examined with a focus on key events such as the Taiping Rebellion, Boxer Rebellion, Xinhai Revolution, May 4th Movement, Communist Revolution, and China''s recent rise as a global power. Students will gain a unique perspective from which to understand the consequences and impact of globalization on our rapidly changing world.</span> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7669,2021,527,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-55','<div class="desc"> This course provides an introductory overview of the psychological factors that influence individuals in sport settings. We will explore theory, critique research, and assess methodological approaches related to a variety of topics such as energy management, goal setting, confidence, concentration, and imagery. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7670,2021,528,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-56','<div class="desc"> <p>During the first part of the 20th century Paris was an international hub of intellectual and creative activity. For black Americans, in particular, Paris held the promise of "liberty, equality, and (interracial) fraternity." There they established connections with African and Caribbean thinkers resulting in an explosion of cultural production that would influence French culture and transform the future of people of African descent. This course will examine black internationalism as experienced in Paris during the Interwar period and the decade following World War II, focusing on themes such as Pan-Africanism, the Harlem Renaissance New Negro, the Jazz Age, and Negritude. Readings will include works by and/or about figures such as W.E.B. Du Bois, Langston Hughes, Josephine Baker, James Baldwin, Aime Cesaire, and Leopold Senghor. </p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7671,2021,529,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-57','<div class="desc"> <p style="margin-right: 0in; margin-left: 0in; background: white none repeat scroll 0% 0%;">Many people associate the Middle East with Islam, or Islam as the primary religion of the Middle East. However, the contemporary Middle East is far more diverse in terms of religious practices within Islam as well as engagement and growth with and alongside many other religious traditions. We will begin the course by considering what''s at stake when we centralize the study of religious practices as a method of engaging with and studying a place, then considering the complex networks of politics, nationalism, and ethnicity as understood through ethnographic research in the region. Ethnographic research can involve what is commonly labeled "fieldwork," but can be far more capacious to consider an analysis of practices rooted in the perspective of the social context in which they were produced. Ethnographies are not only related to a researcher''s physical presence in terms of the practices studied, but can include a variety of virtual, digital, or other material products. Our ethnographic examples will be drawn from a variety of religious practices in the Middle East, including Sunni and Shi''a Islam, the Baha''i faith, Judaism, and a variety of Christian groups. As we work through our examples, we will consider the disciplinary questions of area studies approaches (for example, studying "the Middle East"). As a first-year seminar, this course is intended to introduce you to the critical thinking, writing, and research skills that will be expected of you throughout your career at Oxy. We will focus on a geographic region ("Middle East") in a particular frame ("Ethnography") but the skills you learn in this course should also translate to your other courses and, most especially, to critical thinking, writing, and research activities beyond the Academy. You will learn to read and interpret various textual forms, analyze primary sources according to historical-cultural context, evaluate historical and cultural arguments, and articulate your own in interesting, sophisticated, and clear ways.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7672,2021,530,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-58','<div class="desc"> <p class="sc-BodyText">From a Wellesley prof''s poem that became "America, the Beautiful" to Woody Guthrie''s radical "This Land is Your Land," to Childish Gambino''s response to gun violence, "This Is America," we have many US anthems. Inspired by National Public Radio''s series "American Anthems," this course will research and analyze such songs and their history, considering their use for our nation, as well as those claimed by various groups, cultures, subcultures, and/or individuals. After examining some anthems with a religious and national focus, students will investigate one of their own choosing (in any genre), justifying its status as an anthem. </p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7673,2021,531,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-59','<div class="desc"> <p class="sc-BodyText">In this course we will look at the jungle as a space where western civilization''s desires and fears come into tension with the imagined "other". Usually represented as primitive and wild, the jungle is imagined as a place outside history, culture and civilization. In the readings, which include chronicles of the Spanish conquest, Latin American works of fiction, excerpts from anthropological and botanical texts, and narco-traffic narratives and film, we will explore the particular relations of power that intersect each narrative, in order to rethink the Latin American jungle as a cultural space with a history of resistance and resilience.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7674,2021,532,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-60','<div class="desc"> <p class="sc-BodyText">In this course, we will examine theories of race, racism, and racial identity, with a particular focus on Black-White multiracial identities, as well as other racial identities which straddle America''s racial divide. We will read philosophical treatments of mono-racial and multi-racial existence, examine autobiographical accounts of multiracial experience, and consider sociological findings on multiracial identity. </p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7675,2021,533,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-61','<div class="desc"> <p class="sc-BodyText">Societies are shaped by experiences of chaos and revolution. It was Thomas Jefferson who once said "the tree of liberty must be refreshed from time to time with the blood of patriots and tyrants." Yet, modern conceptions of chaos and revolution are seen as weakening societies. This course will explore the many examples of how chaos brings about reform, revolution, and re-imagined forms of societal structures. We will explore examples of post-war, post-pandemic, and post-disaster scenarios as understood by historians, scientists and sociologists. to can generate healthy and adapted systems. Final projects will conclude with a modern application of theories and examples from class and discussion that explore ways that chaos can be transformed to help build better a world.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7676,2021,534,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-62','<div class="desc"> <p class="sc-BodyText">Since the appearance of popular detective fiction in the 1840s, no genre has been more widely produced and consumed. From the continuing relevance of Sherlock Holmes to the super abundance of investigation dramas in television and film, the genre -- both consciously and not -- has come to define what it means to use the rational mind to break down and make sense of our world. This course will look critically at these stories of detection, from their emergence in the early stages of modernization to their enduring popularity today, so as to ask what the detective figure can tell us about our evolution into the present: from what it means to be a professional problem solver in the first place to what problem solving can do when confronted with the shifting grounds that seem to undermine the simple rationality to which investigation first appealed.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7677,2021,535,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-63','<div class="desc"> <p class="sc-BodyText">US Congressperson Alexandria Ocasio-Cortez set off a political firestorm after describing detention camps at the US-Mexico border as "concentration camps." Many objected to the term because of the comparisons it suggests between state violence at the US-Mexico border and state violence in the Third Reich. Was the Nazi extermination of European Jewry and persecution of Communists, homosexuals, Roma/Sinti, and the disabled a singular, unique, and unprecedented event in world history? What kind of relationship does the Holocaust have with forms of violence and subjugation that precede, coincide, and follow it? In this seminar, we will explore what is at stake in debates on comparing the Holocaust and we will investigate a handful of case studies that put the Holocaust in comparative perspective. These case studies will vary in form, from historical analysis to literature and film, and may address topics such as race legislation, eugenic science, fascism, concentration camps, forced labor, and genocide.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7678,2021,536,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-64','<div class="desc"> This course will examine texts of fiction, poetry, essay, music, film and graphic arts that have as their subject the problems and promise of urban life in major world-cities of the 19th and 20th centuries. Among the cities we may explore through their creative representation are London, Paris, New York, Los Angeles, Tokyo, and Mexico City. Field study in Los Angeles may be incorporated as pertinent events or opportunities come up. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7679,2021,537,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-65','<div class="desc"> <p class="sc-BodyText">This course examines the culture and structure of American society through sociological and critical perspectives. Topics include beliefs, key institutions, community patterns, and systems of inequality. Contemporary topics include mass incarceration, mass shootings, COVID, and police brutality.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7680,2021,538,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-66','<div class="desc"> Experience the European Renaissance and Enlightenment through its artistic and scientific innovation, religious reform, and multi-varied personalities. Consider the relationship of our contemporary "individuality" to the characteristics of men and women of early modern times. A source reader will provide practice in analyzing texts, as well as objects of material culture, in an age of encounters between cultures. A student may focus on a particular field such as politics/diplomacy, court life, sexuality/gender, crafts and the arts, classical revival, reformation, scientific experiment, mapping the globe, philosophical inquiry, protest literature and salons, or travel and global encounters. Learning collaboratively and discussing two films, students examine the lives of a diversity of men and women and the controversies that their lives provoked. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7681,2021,539,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-67','<div class="desc"> <p class="sc-BodyText">This interdisciplinary seminar examines the significance of medicine and health to racialized historical processes of colonization, state formation, and migration in the U.S.-Mexico borderlands over the last 250 years. Subjects range from community health cultures to health care systems and topics include curanderismo, epidemics, carceral healthcare, military medicine, migrant and farmworker health, reproductive justice, environmental health, and grassroots health collectives and movements. We will engage primary documents as well as works in the fields of Native American Studies, Chicanx Studies, anthropology, history, fiction, and film.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7682,2021,540,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-68','<div class="desc"> <p class="sc-BodyText">This course examines the art of revolution and resistance in Mexico, from the Mexican Revolution to the present. We will focus on the ways in which artists, writers, and intellectuals participated in the social and cultural programs of the Mexican Revolution, and how those practices were translated, reframed and engaged by artists, writers, and intellectuals across the course of the twentieth century. Special attention will be paid to transnational artistic collaborations and dialogues among Mexican and American artists, writers, and critics who sought (and seek) to create a more equitable world. We will also examine the legacy of Mexican artists on Los Angeles art and artists. Among the artists that we will study are Diego Rivera, David Siqueiros, Jose Orozco, Frida Kahlo, Tina Modotti, Manuel Alvarez Bravo, Lola Alvarez Bravo Yolanda Andrade, Ana Victoria Jimenez, Damian Ortega, and Minerva Cuevas. Students will use a variety of written texts and visual sources as the basis of their essays, including historical documents, writings of artists and intellectuals, photography, murals, paintings, sculpture, performance, and installation.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7683,2021,541,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-69','<div class="desc"> <p class="sc-BodyText">By studying responses to "natural disasters," this course helps students understand the politics of environmental change. We will explore the religious, economic, and social contexts for individual and institutional responses to natural and catastrophic events, such as volcanoes, hurricanes, earthquakes, floods, and fires. The course will develop a conceptual vocabulary drawn from the interdisciplinary field of "disaster studies" to consider the social geography of risk, the politics of disaster response, and the ability of communities to be resilient and adapt. We will also consider how disasters are woven into the historical memories of various communities and used as reference points to understand both the past and the future.</p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7684,2021,912,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-70','<div class="desc"> How did healing knowledge moving between cultures lead to the rising authority and power of medicine in global history? This course takes a global approach to the history of medicine and biomedical science to offer a new narrative of the emergence of modern medicine. Familiar stories of medicine often focus on the progress of European physicians and the diffusion of knowledge from the "West" across the globe in the early modern period. By contrast, this course seeks to understand how medical knowledge has always involved cross-cultural exchanges, networks, and translation. Medicine is frequently the result of trade and travel, empire-building and colonialism, slavery and migration. Our course begins in the Islamic world, and will turn to how physicians in the Abbasid Caliphate engaged tibb yunani, or Hellenistic medicine, and Ayurvedic traditions from South Asia through institutions like the Bayt al-Hikma, or House of Wisdom in Baghdad. From here we will begin our world tour of medical cultures. Topics for the course include the social and cultural roles of Maya ah-men and Nahua ticitl in Central America, the production of encyclopedias and pharmacological compendia in Ming and Qing-dynasty China, the interaction of Rangaku and Shingaku in Tokugawa Japan, European physicians and colonialism in the Americas, diasporic Atlantic African odunsinni and nganga mbuki in Brazil, and Ayurveda in Mughal India. We will question how no single path to "medical modernity" existed, but rather how medicine and medical authority emerged out of complex interactions between very diverse cultures. Writing assignments throughout the course will enable participants to develop skill in expository writing, research with primary and secondary sources, and historical analysis. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7685,2021,542,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-71','<div class="desc"> <p class="sc-BodyText">Arguably the most significant literary and archaeological find of the twentieth century, the Dead Sea Scrolls have forever changed our understanding of the Bible, ancient Judaism, and early Christianity. But what are they? Who wrote them? Why have they been so controversial? Do they contain secrets to unlock the Bible or accurately predict the apocalyptic end of history? This course offers an in-depth examination of the Dead Sea Scrolls (in English translation) and the archaeological remains of Qumran alongside the complicated context of Judaism in the Second Temple Period and the emergence of Christianity. Student research papers and oral presentations will engage with significant questions regarding the history of biblical interpretation, messianic and apocalyptic expectation, and the formation of early Judaism and Christianity. </p> </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7686,2021,543,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-72','<div class="desc"> Social protest and activism play a crucial role in society; they call attention to important issues and work to bring about necessary change. Social movements are an essential part of a flourishing democracy. While Black women activists have often been ignored or erased by narratives within liberation movements that privileged the contributions of men, the role Black women have played in social movements has been significant. When Alicia Garza, Patrice Cullers and Opal Tometi founded Black Lives Matter in 2013, they followed numerous Black women throughout history fighting for justice, equality and human dignity. Sojourner Truth, Ida B. Wells, Fannie Lou Hamer, Ella Baker, Marsha P. Johnson and Angela Davis are just a few of the many Black women activists that led the way. This course will examine various texts from different genres including fiction, poetry, digital media, and scholarly essays in order to critically discuss what impact Black women have had on social movements, protests, and political activism and what lies ahead for Black women activists and systemic change. Students will engage in discussion, critical reading, and written analysis in preparation for writing an academic research paper. Texts will include works from Angela Davis, Audre Lorde, Janet Mock, Linda E. McMurry, Kimberly Springer, and others. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7687,2021,544,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-73','<div class="desc"> It''s second nature to post, to "like," and to comment. But should it be? You be the judge. In this course, we''ll explore a range of issues related to the "digital me": citizenship, personal representation/presentation, politics, consumerism, and privacy. Readings will range from theoretical works to popular culture criticism and fiction. Participants will bring their individual knowledge, interests and talents to the collective table in order to analyze and propose solutions to real world problems. The goal of the final research paper is to improve or illuminate a small corner of the digital landscape. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7688,2021,545,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-74','<div class="desc"> How do we know ourselves, in relation to others? And what is the role of language in helping us bridge that gap? This Media Studies focused course will explore answers to those time-honored questions using a distinctly modern (and red hot) lens: identity. Over the course of the semester, students will read original works by writers, artists and politicians grappling with various class, race, and gender identities in America and then contextualize those conversations within the larger cultural, rhetorical, and place-based frameworks that produced them. In doing so, students will learn how to perform a linguistic analysis of the Culture Wars, exploring how written self expression shapes our political imaginations, in real time. We will also produce our own multimodal texts in critical dialogue with those works. By comparing and contrasting the speech patterns of different writing styles and learning how to trace subjecthood on the sentence, paragraph, and essay level, students will be introduced to foundational concepts in composition and writing studies while improving their analytical, close reading, and communications skills. This course will culminate in a research assignment analyzing how select rhetorics around identity surface after the presidential inauguration. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7689,2021,546,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/csp-cultural-studies-program/spring-2016-courses/csp-75','<div class="desc"> Try to imagine what it would have been like to arrive on the shores of the Americas in 1492 and genuinely wonder, ''Are these dark, two-legged creatures really human, or are they sophisticated animals that only resemble human beings?'' Looking back, it''s impossible not to be offended by the suggestion that the indigenous peoples of the Americas were not human beings, or not fully human, but as we''ll learn, the history of dehumanization is subtle, powerful, and alive today. It is the story of race and racism, genocide and slavery, "civilization" and barbarism, conquest and colonialism, citizenship, slavery, prisons, and police brutality. And it is an American story. Focusing on the Latin American case, we will study the origins of this story, look closely at the so-called "Indian problem", test theories about what it means to be human before condemning them, and see whether we can say something meaningful about what''s special about being human without implying that some humans are superior and others inferior. </div>','Open only to first year frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7690,2021,2738,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-100','<div class="desc"> <p>This course introduces critical theory in the context of the problem of social justice. Introductions will be made to psychoanalytic, Marxist, feminist, structuralist, deconstructive, and postcolonial criticism. Reader-responses; New criticism; lesbian, gay, and queer criticism, will also be surveyed. There will be close readings of the work of Louis Althusser, Georges Bataille, Michel Foucault, and Jacques Derrida, as well as in depth readings of essays by Guy Hocquenghem, Julia Kristeva, and Trinh T. Minh-ha.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7691,2021,2845,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-102','<div class="desc"> <p>Meaningful social and political change requires not only critical and thoughtful engagement with our grounding ideas, dominant theories and our existing positions. It also demands that we learn the concrete, practical skills necessary to make our ideals real, to exercise our rights, to fulfill our duties to one another, and to transform the actual mechanisms and institutions that shape our lives. This course — unique at either the undergraduate or graduate level — will provide students with an intensive and full-spectrum introduction to the most important, most effective and newest techniques, tools and technologies used in political and activist campaigns from the highest levels of electoral politics to non-profit, non-governmental and community campaigns. </p> <p>The course curriculum is organized in three dimensions, training students with the core skills necessary to participate in existing political and activist work, but also empowering them to, when necessary, imagine and carry out their own innovative and transformative campaigns. To this end, students will learn not just tactical skills, but also strategic planning and management approaches that will help them invent, implement, and improve the campaigns to which they commit themselves.</p> <p>This course will include instruction and workshops that bring the best practices and lessons from top businesses and campaigns, refined by political practitioners and distilled for students. It will also include tactical skills training-- media messaging and communication strategies, polling literacy, database management, budgeting and campaign finance, Get Out the Vote (GOTV) efforts, and lobbying basics. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7692,2021,2929,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-104','<div class="desc"> <p>This seminar will explore the emergence of new expressions and practices of gender and sexuality by contemporary Arab and Iranian intellectuals, artists, activists and leaders. Rooted in a study of the historical conditions for the emergence of this new set of discourses and practices â from pre-Islamic cultural practices to Western colonialism â the course will examine the novel and transformative forms of expression of gender and sexuality that are being invented in the Middle East and North Africa in dialogue with and in resistance to pre-existing narratives, policies and practices. From resistance to the idea of “gay identity” as a colonial-era trap and backlash against emergent gay rights movements, to the strategic complexities of appropriating the state laws supporting gender-reassignment surgery in Iran, the new generation of queer activists and intellectuals are navigating both their own histories and the limits of postcolonial discourse as they seek a liberatory art and politics. The course will dedicate significant time to studying the current work of these activists â taking up their writing, art, interviews, videos, and political tactics. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7693,2021,823,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-105','<div class="desc"> <p>This course will locate the topics of immigration and education within historical, legislative, and cultural debates on what it means to be an American and who has the right to an education. Students will explore and debate precedent-setting Supreme Court cases, such as Mendez v. Westminster, which challenged the segregation of Mexican children into separate schools, and Lau v. Nichols, which fought hard for non-English speaking students to have linguistic access to the public school curricula. In addition, students will research the historical antecedents to the recent anti-immigrant movements in California, Arizona, and Colorado, which target the use of languages other than English in school settings, and have all but abolished bilingual public schools. Against this historical and legislative backdrop, students will examine ethnographic research detailing the persistent challenges that immigrant children face in schooling, including migrant children, and the ways in which they, their parents, and communities experience those challenges.</p> <p>This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CSP 1, CTSJ 105, DWA 282 and SOC 105.</p> </div>',NULL,'CSP 1, DWA 282, and SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(7694,2021,1690,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-107','<div class="desc"> <p>This course will introduce students to major concepts, theories, and intellectual inquiries in the area of postcolonial studies. Students will engage with broad questions around knowledge production, representation, and subjectivities through the examination of topics such as: decolonization, migrations, transnationalism, diaspora, cultural productions, and practices of resistance. The course will look at relationships between postcolonial studies and critical race, feminist, and queer theories.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7695,2021,2985,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-108','<div class="desc"> <p>Through the year 2020 we have seen the rise of reactionary, ethno-nationalist politics across the world. It is likely that this rising authoritarian movement will intensify as climate change creates massive population movements among people in vulnerable economic situations and most susceptible to displacement. This course will critically examine the nature and interrelation between resurgent racist, ethnno-nationalist ideologies, tracing their historical and conceptual roots. It will also take up recent studies of the looming consequences of climate change for population displacement while examining the viability of public policy frameworks and legal instruments for addressing these exigent problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7696,2021,2877,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-115','<div class="desc"> <p>This course will examine the highly ambivalent effects of the adoption of Western digital, networked technologies (with their underlying modes of understanding the world and human life) in the modern Middle East and North Africa. In particular, in the context of the Middle East, the course will seek to identify and understand both (1) the new forms of popular liberatory action — revolt, protest, social organizing — that are made possible or impossible by the widespread adoption of new technological modes of life, and (2) the new forms of state and para-state, surveillance, control, suppression, and disinformation that this technology makes available or encourages by its very structure and embedded premises. Beginning with an analysis of the inner logic and possibilities of modern digital communication technologies as these have been formed in their Western conditions of emergence, the course will then set out to understand how the reception of these new Western technologies in the Middle East (1) give rise to new possibilities for liberatory action via a digital public sphere (for example, the events of the 2009 Iranian uprising and the on-going political movements associated with the 2011 Arab Spring); (2) foster and globally spread new modes of dangerous reactionary politics that include violent, socially destructive forms (for example, ISIS, violent sectarianism and anti-Semitism); and (3) give authoritarian and repressive Middle Eastern regimes new tools and strategies for the surveillance, suppression and social control of their populations (for example, Turkish, Egyptian responses to social movements, and the Iranian governments access to Western mobile phone companies'' location information of its citizens to round up protestors, to the use of wide-spread facial recognition technologies and the capacity to quickly spread disinformation or control elections results). The course will bring together a study of critical theoretical work from both Western and Middle Eastern thinkers (for example, of Foucault, Tufekci and Deleuze, Soroush, and Sardar) with the scholarly and vocational writing of technologists in both the West and the Middle East, the accessible operating documents of digital information companies who have played important roles in both making possible and repressing political and social liberation movements in the regions, and the legal and policy documents that both structure and deploy these technologies for and against us.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7697,2021,2846,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-120','<div class="desc"> <p>This course introduces students to theories of power from multiple disciplines, and applies these theories to analysis of how power operates in formal and informal politics. Students will be introduced to the basic operation of politics and public policy in the U.S., as well power operating in economic and social systems. It will analyze contemporary public policy, political campaigns and elections, social movements, hashtag activism, and other aspects of the struggle for power in the U.S. context. This class is open to frosh and sophomore students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7698,2021,824,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-140','<div class="desc"> <p>This course introduces students to critical theories concerning human sexuality. We read feminist, Marxist, psychoanalytic, structuralist, and poststructuralist theories of sexuality, and discuss what makes each of these theories "critical." Topics include: the political economy of marriage, the relationship between sexuality and procreation, uses of the erotic, homosociality, and the incitement to discourse. The authors we read include Engels, Freud, de Beauvoir, Levi-Strauss, Gayle Rubin, Andrea Dworkin, Foucault, and Judith Butler.</p> <h1 class="a-size-large a-spacing-none" id="title"></h1> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7699,2021,2330,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-160','<div class="desc"> <p>This course introduces students to contemporary feminist thought and histories of feminist activism. Students will learn about the intersectionality of race, gender, class, sexuality, and nation in a variety of feminist scholarship, and will examine key issues in feminist theory, such as: the debates between Western feminism and women of color feminism, transnational feminism, queer theory, the social construction of sex and gender, reproductive justice, gender based violence, and the political economy of gender. This course will center on the strong link between feminist theory, social justice, and activism, and will explore how these can be mutually informing projects that can effect social change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7700,2021,1060,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-180','<div class="desc"> <p>Stupidity is neither ignorance nor organicity, but rather, a corollary of knowing and an element of normalcy, the double of intelligence, rather than its opposite. It is an artifact of our nature as finite beings, and one of the most powerful determinants of human destiny. Stupidity is always the name of the Other, and it is the sign of the feminine. This course in critical psychology follows the work of Friedrich Nietzsche, Gilles Deleuze, and most recently, Avital Ronell, in a philosophical examination of those operations and technologies that we conduct in order to render ourselves uncomprehending. Stupidity, which has been evicted from the philosophical premises and dumbed down by psychometric psychology, has returned in the postmodern discourse against nation, self, and truth, and makes itself felt in political life, ranging from the presidency to Beavis and Butt-head. This course examines stupidity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7701,2021,1061,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> <p><strong>Axes to Praxis: Music as Activism</strong></p> <p>This course aims to provide students with an understanding of the role of music in creating social change. Students will listen to the structure and content of songs and discuss how they can spark critical thought and become a catalyst for political action. The students will also explore how live musical experiences contribute to community building. Traditional, as well as contemporary musical styles, will be examined with an emphasis on the music of women, the LGBTQA community and people of color. We will learn about the contribution of artists and activists whose ideas have propelled society forward.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7703,2021,508,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-201','<div class="desc"> <p>This course examines intersectional gender representations in film, television, literature, memes, and other forms of contemporary popular culture. Students will learn theories of media influence and analyze the impact of pop culture in shaping cultural values and norms, primarily in the United States. Students will also examine how different identity groups are portrayed, and the effect of media under-representations, stereotypes, tropes, and other miss-representations on their social value and lived experiences.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7705,2021,2847,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-204','<div class="desc"> <p>The abuse of Iraqi prisoners at the US military’s Abu Ghraib Prison and the terrible photographs that circulated giving testimony to that abuse brought torture into our public discourse and became a point of intense political engagement in the US and around the world. This course will examine the so-called “enhanced interrogation techniques” used during the War on Terror as well as the legal and policy justifications that supported them. We will place these practices and justifications within the broader context of colonial power, looking at the ways torture and sexual violence were deployed by other nations. Beyond its use as a punishment or deterrent, we will trace the use of torture back through Western history, to its use in religious and political conversions and finally back to the origins of Western metaphysics in the Ancient Greek use of violence and dehumanization in the formulation of our conception of truth itself.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7706,2021,3066,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-205','<div class="desc"> <p>In the wake of the democratic protest movements across North Africa and the Middle East in 2011 and the violent suppression of the 2009 pro-democracy revolt in Iran, we have seen the strident reassertion of authoritarian politics in both religious and secular forms and, in some places, a collapse into war. This course takes up a series of questions seeking to understand the aspirations of the activists and intellectuals who drove those promising movements. What did they mean by democracy, by empowerment, and by liberation? What political conditions did they find intolerable such that they risked their lives to change them? What political future did they envision? How do they assess the political outcomes of their various and distinct movements? What can we learn from the outcomes of those movements about the limits of protest and internet-era technology as a tool for political mobilization? What is the next generation of democracy activists doing to build the capacities, habits, and institutions necessary to bring positive liberatory change to their societies?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7707,2021,1111,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-210','<div class="desc"> <p>Why did the London Bridge fall down? Is Rub-a-Dub-Dub really about bath time? Why didn''t an old man live in a shoe? Who is more imperialist Babar or Peter Pan? Is Tinky Winky gay? Is South Park a children''s show? Is Harry Potter a Hero? How tired was Rosa Parks? Using different critical approaches this course will examine children''s poetry, picture books, novels, cartoons, feature films, and music videos. Analysis will include topics related to gender, race, culture, and nation as they play out in the aesthetics, images, and poetics of children''s texts. Emphasis topic: Critical Race Theory.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7708,2021,1691,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-211','<div class="desc"> <p>Critical pedagogy aims to develop collective critical consciousness for the purpose of transforming oppressive socio-political conditions. In this course, students will study critical pedagogy from historical, political, and sociological perspectives. Students in the course will consider traditional student/teacher relationships, pedagogical approaches, as well as hierarchies of knowledge promulgated by schools and textbook publishers. Students will analyze and critique theories of the Frankfurt School and the emancipatory works of Paolo Freire, the most renowned critical pedagogist. Additionally, contemporary readings from Henry Giroux, bell hooks, and Peter McLaren will focus on critical pedagogy in relation to social structures, globalization, media, and race.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7709,2021,2791,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-212','<div class="desc"> <p>Using critical theory and film analysis, students in this course will interrogate Disney Corporation’s feature-length animated motion pictures. Analysis will include themes and explorations related to gender, race, class, nation, and empire. In this class, these films will be approached as both a textual, cultural, and historical practice. As such, students will develop and hone "close reading" skills in relation to the cultural impacts of texts on children. Additionally, we will focus on the American values and beliefs as they are presented in the films, endeavoring to make the f"strange familiar and the familiar strange" (Spiro, 1990). Along the way, we will discuss some of the most influential and productive critical schools of thought informing film analysis today, including realism, auteurism, feminism, postmodernism, and others. Screenings are mandatory.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7710,2021,2649,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-213','<div class="desc"> <p>The course interrogates the assumptions underlying paid and unpaid labor with respect to "women''s work" as it intersects with race, class, sex, gender, and sexuality. Drawing on a socio-critical perspective, we examine the inequalities associated with reproductive labor, child care, housework, sex work, and the ''feminization'' of certain professions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7711,2021,3529,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-214','<div class="desc"> <p>This course explores the subject formation of girls in various societies throughout the world. Both theoretically and conceptually, the course will interrogate who counts as a “girl” and the coherence of girls as a social construction in various contexts. Through an examination of ideologies, policies, media, religion, institutional practices, schooling, and the social practices of girls themselves, the course will situate girls within complex sociocultural worlds. The course will ask questions of global girl power in relation to their social positionalities and material lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7712,2021,1112,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-215','<div class="desc"> <p>This methods seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7713,2021,2650,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-219','<div class="desc"> <p>This course examines the scope and impact of Title IX in educational settings from its passing in 1972 to the present day. Students will explore two main areas of sex-based violations: 1) sports and discrimination and 2) sexual harassment and sexual assault. Drawing on critical theory, students will research and interpret case studies involving Title IX violations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7714,2021,2878,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-220','<div class="desc"> <p>This class introduces students to the concept of intersectionality— how different identities (e.g., gender, race, ability, sexuality) overlap to create interdependent systems of oppression. Students will learn how these systems of power operate and function, and will analyze how these systems intersect and morph to maintain existing power structures. Students will grapple with critical race theory, feminist theory, queer theory, and readings from disability studies as well as quantitative studies documenting how different identities intersect. This course has an applied component. Students will perform research with The Intersectionality Project (TIP), the first research project to map the contours of intersectionality in the U.S. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7715,2021,2848,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-221','<div class="desc"> <p>This interdisciplinary course is designed for students considering the law as a potential career path and who are interested in developing an understanding of the relationship between inequity, the law and critical theory. Our materials will include federal and California statutes and case law, government-issued reports, and legal journal articles related to education; housing justice; police practices; consumer protection; immigrants'' rights; and other topics. This course will teach students the methods of law and policy analysis. The two main questions that will guide our critical thinking are: what is the impact of the law on inequity and what is the impact of inequity on the law? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7716,2021,1582,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-222','<div class="desc"> <p>The course offers an interdisciplinary analysis of gender, power, and the body. The theoretical center of the course will be Foucault''s work on biopower, including <em>Discipline and Punish</em> and <em>Foucault 2.0</em>. Topics include: class and the body (Atwood''s <em>Bodily Harm</em> and Larsen''s <em>Passing</em>); law and the female body (Wendy Williams and Mary Poovey); science and gender (Emily Martin and Thomas Laqueur); pornography (Catherine McKinnon and Laura Kipnis); race, body, and gender (Morrison''s <em>Beloved</em>; Lauren Berlant and Judith Butler); multiculturalism and cross-race identifications (John Stahl''s <em>Imitation of Life </em>and Wyatt''s <em>The Hazards of ldealization</em>); and Latin American perspectives on gender, torture, and memory. Open to students with sophomore standing or higher.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7717,2021,2331,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-250','<div class="desc"> <p>This course will examine the relationship between resistance movements and the law through several historical and contemporary United States and Latin American case studies. We will begin the semester by exploring theoretical representations of resistance movements within critical legal theory and social movement theory. We will look at different conceptualizations of power and consciousness in our analysis of resistance, and the role of each in instigating resistance movements. We will then turn to an analysis of the law as a tool of collective struggle by studying and comparing the implicated rights and site-specific needs, objectives, strategies, and outcomes of each case study. We will look at the different ways these resistance movements may use the law to mobilize followers, to frame and address collective grievance, to advance and develop legal protections for marginalized groups, and to connect their localized struggles with global ones by redefining and reimagining concepts of dignity and freedom. Each case study will also provide us with an opportunity to explore the relationship between the law, state-sponsored violence, and repression of resistance movements. We will also examine the role and influence of legal advocacy organizations in contemporary resistance movements, and evaluate the current limitations of the law in contributing to social change. How do rights-based claims (e.g. indigenous rights, water rights) obscure the relationship between law and power, injustice, and structures of oppression? Can the law be a useful catalyst for change, and/or is it necessarily a supplement to grassroots organizing and mobilizing efforts? To examine these concepts and tensions, we will look at legislation and legal practices, landmark court cases, and critical scholarship related to our case studies. Among the resistance movements we will likely study are: Brazil''s Landless Rural Workers Movement; indigenous resistance movements in North and South America, including resistance to the Dakota Access Pipeline and the Agua Zarca Hydroelectric Dam in Honduras; and different phases in the movement for black civil rights in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7718,2021,1372,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-255','<div class="desc"> <p>This course will examine intersecting and overlapping categories of "difference" by focusing on the lives of women of color. By looking at conditions that shape race, sexuality, gender, class, and cultural differences, this class will critically examine multiple discourses surrounding feminism, anti-racism, heteronormativity, and critiques of imperialism. We will consider contexts of individual and collective work for social change. Using personal essays, stories, scholarly writings, artistic works, music, film, and other media, the course will look at sources that women of color draw from to ground themselves and their activist work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7719,2021,510,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-257','<div class="desc"> <p>This course will take place at the Barry J. Nidorf Juvenile Hall with both Occidental College students and incarcerated students from the BJN Juvenile Hall. It will focus on the uses of the visual and performing arts, spoken word, and hip hop, as tools for positive social change, specifically examining the Prison Industrial Complex (PIC). Artists and activists have made use of artistic expression in efforts to educate about the PIC. By examining movements such as the Black Arts Movement, Theatre of the Oppressed, and Hip Hop Theatre, students will gain an understanding of tangible ways in which artists have shaped and addressed social issues. Through collaboration with each other, students will create artistic and dialogical spaces for critical thinking. Students will create art-based workshops which they will then present to classmates. Students do not need to be artists to participate in the course, however, creative building will be an integral part of the curriculum. At the end of the course there will be a closing ceremony in which components of the workshops will be presented to the community, including the Warden and other officials. Readings include work by Augusto Boal, Paolo Friere, Christian Parenti, and Manning Marable.</p> </div>','Sophomore standing and over the age of 18 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7720,2021,1062,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-259','<div class="desc"> <p>This course examines movements of bodies through political, legal, economic, and social exchanges. Drawing from a variety of materials (theory, literature, film), the course examines practices such as: human trafficking, organ transplantation, transnational adoption, and surrogacy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7721,2021,910,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-270','<div class="desc"> <p>This course looks cross-culturally at children and childhood and uses ethnographic case studies as a basis for examining the ways in which the very young participate in the social lives of their communities. The focus is on those between the ages of 5-12 and the primary topics include: children''s play, socialization, learning, political action, and productive work. We will explore the lives of children in horticultural, pastoral, rural, and urban societies in Africa, Asia, Polynesia, and the contemporary United States.</p> </div>','Any 100-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7722,2021,85,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-280','<div class="desc"> <p>This course will examine the character of postcolonial theory in the Afro-Caribbean. Particular attention will be paid to the work of C.L.R. James, Walter Rodney, Franz Fanon, Marcus Garvey, Aimé Césaire, Eric Williams, Kamau Brathwaite, and Bob Marley. The course will also examine Rastafari as a religio-political protest movement. We will chart the musicological development of reggae and dub poetry as distinctive expressions of Rasta.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7723,2021,86,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-285','<div class="desc"> <p>This course will cover the early writings of Michel Foucault, paying particular attention to his psychological writings. We will conduct a close reading of <em>Madness and Civilization</em>.</p> </div>','Any 100-level CTSJ class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7724,2021,1007,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-295','<div class="desc"> <p>This seminar will engage important topics and issues in Critical Theory and Social Justice. All CTSJ faculty will participate in order to facilitate an interdisciplinary engagement with complexities and nuances of these topics. Students from other CTSJ courses will be invited to participate in the construction of discourse around the topics. May be repeated for credit when offered with a different topic. Different topics may fulfill different Core Requirements.</p> <p><strong>Black Popular Culture // The Black Digital Age </strong></p> <p>This class is part of a series that takes up black popular culture as a social formation structured by both the shifting conditions of antiblackness and black objection in the 20th and 21st centuries. Rather than engage black popular culture as a representational form, the course queries the peculiarity of blackness’ cultural popularity within a society where black people remain disproportionately available to gratuitous violence and early death. As such, the course interrogates the ways in which the mainstream US popular culture economy is sustained by a deeply contradictory fascination with black bodies, black sociality, and black repertoires of performance within an antiblack society and argues that consumption of black life and black expressions is a modality of the ways in which blackness is put to use under white supremacy. The course is particularly concerned with how the audio-visual is a poignant site at which visual fixations on and pathologizations of blackness collide with black peoples’ expressions of objection, self-articulation, activism, and the forging of social space. In this light, this iteration of the course, queries the possibility of the “Black Digital Age” as the proliferation of black expressions within the 2010 to present moment in the audio-visual (TV, film, and videography, including Scandal, Moonlight, Insecure, Queen &amp; Slim, Native Son, Lemonade, When I Get Home, When They See Us, Fences, Random Acts of Flyness, and countless others) and social media (Youtube, Twitter, and Instagram) realms. We ask, what political, social, and historical developments in this moment have facilitated such a proliferation of black productions within the audio-visual; what is the social, political, and historical impact of these black productions; how have black artists reconfigured black visuality as a site of desire, pleasure, restitution, and power in the face of antiblack racism as visual degregation of blackness; and how might our social criticism and genuine engagement with these texts extend the project of black life, objection, and self-articulation in the face of ongoing antiblackness? Core Requirement Met: United States Diversity.</p> <p><strong>Social Movements/Representational Forms</strong></p> <p>In this course, we will examine the competing advocacy within social movements for documentary, fiction, journalism, lyric, abstraction, and other representational forms. For each social movement or political issue that we cover, students will compare multiple modes of representation, considering why they emerged, what their strengths and weaknesses were at each specific conjuncture, and what significance they have for future struggles. We will begin with some theoretical grounding and then proceed via a set of case studies. These may include: debates about realism vs. modernism in the Frankfurt school; testimonies in Latin America; confession vs. experimentation in feminist literature; reportage vs. the essay in journalism; and slogans, songs, and posters in queer activism.</p> <p><strong>Blackness, Gender, and Sexuality</strong></p> <p>In this course, students will deconstruct, critique, and reconsider our notions of “gender” and “sexuality” by thinking deeply, creatively, and rigorously about the ways in which blackness has been both central to modern conceptions of gender and sexuality and marked as the standard of sexual and gendered deviance. Students will consider “gender” and “sexuality” as historical, socially produced, and mutable categories that are co-constituted by structures of power including race, capitalism, and chattel slavery. Importantly, the course will focus on identifying the historical conditions and structures of power that have differently gendered black bodies in the Americas. By considering the particularities of black gendering, the course will identify how notions of gendered and sexual deviance and availability to antiblack violence have been central to producing black people as a population. Through concepts such as flesh, ungendering, availability, and queerness, students be able to unpack how black bodies are gendered in terms and social relations that are in excess of a binary and are not analogous to other racialized bodies. Finally, by looking at popular and cultural objects, the class will analyze how contemporary raced and gendered structures of power affect black people and communities. Core Requirement Met: United States Diversity.</p> <p><strong>Critical Theory and Psychopathology</strong></p> <p>This experimental interdisciplinary course considers the intersection of Critical Theory and psychopathology. The goal is to examine the ways in which central insights in Critical Theory might reorient our perspective on, and interventions against, mental disorders. By way of contemporary case studies, we will examine the directive to "care for the self" (Michel Foucault), the mandate "you must change your life" (Peter Solterdijk), the problems of death (Jacques Derrida), the work of forgiveness (Derrida), and the anguish of perversions (Georges Bataille). We will also re-read chronic pain (Friedrich Nietzsche), Generalized Anxiety Disorder (Sianne Ngai), Gender Dysphoria (Judith Butler), and Intermittent Explosive Disorder (Slavoj Zizek). We anticipate the emergence of a broader more powerful view of madness. Core Requirement Met: Global Connections.</p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7726,2021,2849,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-300','<div class="desc"> <p>This course is an introduction to the process of conducting social science research. Students will learn to execute a research project from start to finish—including the formulation of a research question, selecting the best method(s) for addressing the question, statistical analysis in a lab setting, and research report writing. Students will also learn to critically analyze the production of knowledge and unmask the power dynamics of “scientific” inquiry, “objectivity,” and “authority.”</p> </div>','CTSJ 100 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7727,2021,1692,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-310','<div class="desc"> <p>This course is designed to introduce students to the methods and approaches used in qualitative interviewing. In addition to structured interviews, students learn about semi-structured biographical and narrative interviewing methods. The course also explores the ethical dilemmas and research challenges inherent during interviewing, as well as the details of conducting qualitative interviews. By the end of the semester, each student will have constructed, modified, conducted, analyzed, and written up an interview study.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7728,2021,1155,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-311','<div class="desc"> <p>In this course, students examine contemporary child poverty, both in the United States and abroad. Topics include: how poverty is defined, both locally and globally; the numbers and distribution of poor children; as well as the causes of child poverty. Readings explore poverty in relation to education, economics, homelessness, child labor, family, gender, and race. Students analyze historical anti-poverty policies, such as: the New Deal, the War on Poverty, and the United Nations Convention on the rights of the child, as well as contemporary proposals to reduce child poverty, such as: childcare, welfare, job training, job creation, and tax policy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7729,2021,1442,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-312','<div class="desc"> <p>This course combines theory and practice in the study of language and literacy across cultures and institutions. It will introduce students to competing theories of language and literacy development and the politics that undergird those theories. The course will also explore topics such as: gender, race, culture, and ethnicity as they intersect and shape language learning. Students will learn about language acquisition, heritage languages, language variation, dialects, and bilingualism. The course will also explore controversies surrounding multimodal literacies involving speech, writing, drawing, pictures, video, and music. Junior standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7730,2021,2879,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-330','<div class="desc"> <p>This course interrogates the proliferation of ballroom culture in 20th and 21st century America. Students will examine the historical formation of ballroom and black queer culture in mid 20th century Harlem, New Orleans, and Chicago and its contemporary formations as sites of objection, life, and black queer radical praxis within black/latino neighborhoods, while also interrogating the commodification of ballroom within popular culture. Students will consider how ballroom has been circumscribed within the ethnographic (Paris is Burning, the Aggressives, Kiki, &amp; Check It) and the consumptive (Pose, RuPaul’s Drag Race, Real Housewives of Atlanta, and Madonna’s Vogue), while also tracing how ballroom’s reconfigurations of normative gendering, it’s embodied response to quotidian antiblack violence, and it’s repertoire of classed, raced, and sexualized critique exist in excess of how it is spectacularized and consumed. The course offers students a complex site through which to consider how race, gender, class, and sexuality intersect and to interrogate how black queerness and transness have become central to what we know as “popular culture.”</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7731,2021,1326,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-340','<div class="desc"> <p>In this course, students learn how to do ethnographic research and writing by conducting exercises in participant-observation on or near campus. We review the history of the ethnographic method and its relation to anthropology and the colonial encounter. We also discuss what makes an ethnography critical, and the tensions between ethnography, sympathy, and critical theory. Authors we read include Malinowski Geertz, Delmos Jones, Dorinne Kondo, Renato Rosaldo, Ruth Behar, Jim Thomas, and Kamala Visweswaran.</p> </div>','Any 200-level CTSJ class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7732,2021,2880,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-350','<div class="desc"> <p>The course will study the transformation of postcolonial theory and practice by contemporary writers and activists in the Middle East, North Africa and South Asia in response both to their new social, cultural, political, and economic conditions, as well as to their experience of the limits of earlier forms of postcolonial thought. The course will track the problems posed by the emergent concepts of identity and authenticity and the way that the modalities of melancholia and <em>ressentiment </em>can affect or undermine the postcolonial as a project of liberation. As part of this re-examination, students will explore the complex ways in which Western modes of thinking and politics — including modernism, anti-modernism, Traditionalism and resurgent authoritarian and ethno-racial political forms — shape and are resisted by postcolonial thinkers and activists. The course will advance student understanding of postcolonial theory and practice by pairing (1) a careful examination of foundational works of postcolonial thought within their historical and political contexts, with (2) an exploration of the work of contemporary scholars and activists whose projects transform and reimagine the very idea of the postcolonial.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7733,2021,88,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-357','<div class="desc"> <p>This course employs interpretive tactics from critical legal theory and critical race theory in order to examine the use of law to justify and sustain U.S. colonial/imperial projects. We will look at how these projects are connected to the control of domestic populations (especially indigenous and racialized groups) and the expanding desire for territory. We will look at questions about nation, state, and sovereignty; law and hegemony; and relationships between "change" and maintenance of the same in legal discourse. The course will also investigate relationships between globalization, international legal regimes, and new forms of empire. We will consider specific topics that raise questions about ongoing operations of and resistances to imperialism, including: trafficking in persons, sovereignty and indigenous people''s rights, the legal status of territories and protectorates and the selective use of the U.S. Constitution in those locations, and issues rising from the "war on terror."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7734,2021,1654,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-360','<div class="desc"> <p>This seminar introduces students to the theory and practice of research in feminist and sexuality studies. The course provides an introduction to the key terms and debates in feminist theory about how knowledge is produced and the relationship between knowledge and power in processes of knowledge production. We will give particular attention to the interdisciplinary focus of feminist research and its intersection with other methodologies such as queer theory, transnational feminisms, and critical race theory. Students will also consider how feminist research and social justice/community activism are related, and will assess the critical intersection of feminist theory and praxis.</p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7735,2021,2332,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-361','<div class="desc"> <p>This course centers on representations of gender, race, class, nationality, and sexuality in Latinx and Latin American film. We will examine the economic, racial, and gendered inequalities that stem from histories of colonization and neocolonialism in Latin America and in the diasporic Latinx communities that have formed in the United States. Using a transnational lens, students will assess the limits and possibilities of film in documenting histories of oppression and social inequalities facing Latin Americans and Latinx communities in the U.S. We will turn to feminist film theory, critical film theory, cultural studies, and Latin American history and politics in order to facilitate our analysis and class discussions of these films.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7736,2021,89,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-369','<div class="desc"> <p>The Clinical Psychology Laboratory (CPL) provides experiential opportunities for students interested in graduate study in Psychology, Law, or Social Justice. Students are given the opportunity to participate in the data analysis of clinical psychological assessments. Students will also participate in research on a Human Studies Committee approved project with the goal for an early exposure to the field, and with the objective to yield research data for presentation or publication. In some projects, students may have limited opportunities to observe and participate in forensic psychological assessments as prescribed in the respective protocols. Instructor interview and approval required. May be repeated three times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7737,2021,2703,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-375','<div class="desc"> <p>This course focuses on key themes and topics of Indigenous Feminisms. In particular, we will discuss how gender, sexuality, land, and sovereignty intersect in different Native communities. We ask: How do female, queer, two-spirit, gender non-conforming, and feminist Indigenous peoples persist, resist, and thrive in the face of ongoing colonial violence and erasure? How does settler colonialism intersect with heteropatriarchy, necessitating an intersectional decolonial analysis and response? In what ways does the protection/empowerment of Native women correspond to the preservation/respect of Native land? How can an Indigenous feminist epistemology change our conceptualizations of land, water, and spatiality? What does an Indigenous queer critique contribute to analyses of militarism, imperialism, and settler colonialism? </p> <p>Case studies and examples are drawn from Turtle Island (North American continent), the Pacific Islands, and Palestine. Authors to be discussed include Mishuana Goeman, Audra Simpson, Haunani-Kay Trask, and Kim TallBear.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7738,2021,2704,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-376','<div class="desc"> <p>This course will engage major concepts, theories, and intellectual inquiries in the area of settler colonial studies. We will ask: what makes settler colonialism distinct from other forms of colonialism? How does settler colonialism intersect with other systems of oppression, such as heteropatriarchy, chattel slavery, and racial capitalism? We begin by defining settler colonialism as the systematic dispossession and elimination of Native peoples via genocide, land appropriation, settler immigration, and/or cultural assimilation. We will then explore the relationships between settler colonial studies and queer theory, Afro-pessimism, and Asian diasporic studies. Authors to be discussed include Patrick Wolfe, Lorenzo Veracini, Jodi Byrd, Mark Rifkin, Jared Sexton, Frank B. Wilderson III, Ikuko Asaka, Iyko Day, Dean Saranillio, and Manu Karuka. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7739,2021,514,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-384','<div class="desc"> <p>A close reading of the works of Georges Bataille, including: <em>The Impossible, The Unfinished System of Nonknowledge, The Accursed Share, On Nietzsche, Story of the Eye, The Dead Man, </em>and <em>Collected Poems. </em>First year students are not permitted to enroll in this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7741,2021,1443,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-390','<div class="desc"> <p>The CTSJ Junior Seminar is designed to develop students'' methodological sophistication and theoretical skills in anticipation of the Senior Comprehensive Project. Students will be required to acquire an applicable understanding of the range of archives and the complex interdisciplinary methodological strategies used in Critical Theory and Social Justice. They are also required to develop an understanding of the meaning of the CTSJ Senior Comprehensive Project as an "intervention." Open only to juniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7742,2021,1513,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-394','<div class="desc"> <p><em>Critical Theory and Social Justice Journal of Undergraduate Research</em> (<em>CTSJ</em>) is the leading undergraduate publication in its field, nationally. A primary goal of this course is to develop student''s preparedness and capacity to critically evaluate submissions to the <em>CTSJ Journal</em>. To that end, there are two sets of readings. All students are required to read the primary text, J.M. Balkin''s <em>Cultural Software</em>. Other readings are assigned to reflect the themes and topics of the submissions under review. In addition, this course affords students the opportunity to work closely with<em> CTSJ''''</em>s Lead Faculty Editor to understand the mechanisms of working for and advancing a research publication in the Humanities field, and produce content that is consistent with the goals of <em>CTSJ</em>. May be repeated three times for credit.<em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7743,2021,1064,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-395','<div class="desc"> <p>An advanced seminar in Critical Theory and Social Justice. May be repeated for credit with a different topic. <em>Different topics may meet different requirements.</em></p> <p><strong>Indigenous Literature as Decolonial Praxis</strong></p> <p>This course will examine Indigenous literature as a form of political cultural production. Using settler colonialism as a context, the texts under examination will be understood as assertions of Indigenous sovereignty. As a result, readers'' will come to understand Indigeneity and Indigenous peoples more broadly. By examining primarily 20th and 21st century texts, a contemporary view of Indigenous epistemologies, including ideas of belonging, kinship networks, violence, etc., and social justice struggles will emerge as relevant to current decolonial efforts. <em>This class counts as a methods class for the CTSJ major.</em></p> <p><strong>White Queer Theory</strong></p> <p>This course critiques the ways in which queer theory and politics of the late 20th and 21st century have been a profound site through which whiteness has been able to reproduce and proliferate in the context of the neoliberal incorporation of raced, sexed, gendered difference into structures of capitalism and the US nation-state. As such, students will engage both the so-called critical texts of white American queer theory and texts from queer indigenous studies, black queer studies, women of color feminisms, and queer of color critique along with the burgeoning fields of black trans studies and trans of color critique that have rigorously critiqued the limits of the so-called critical texts to think [critically] about their reproduction of whiteness and the ways in with their thinking of queerness does not encapsulate the ways in which indigeneity, blackness, and other racialized formations are marked as sexually deviant, non-heteronormative, and queer, both as sexual identities and as populations. In order to thoroughly interrogate these proliferations students will engage a variety of texts that include theory, history, political movements, and popular culture — texts include the work of Foucault, Judith Butler, Glee, Paris is Burning, #ItGetsBetter, the phenomenon of Milo Yannopoulos (aka Milo Hanrahan), Christine Jorgensen, and the white queer antiblack backlash against the simultaneous passing of prop 8 in California and the election of Barack Obama as the first president; and the work Cathy Cohen, Qwo-Li Driskill, Jasbir Puar, Scott Morgensen, C. Riley Snorton, Roderick Ferguson, and other scholars who have reframed questions of queerness and its intersections with whiteness, settler colonialism, and racial capitalism through frameworks such as homonationalism, settler homonationalism, trans necropolitics, and the queerness of blackness. <em>This class counts as a methods class for the CTSJ major. </em>Core Requirement Met: United States Diversity.</p> <p><strong>Whiteness</strong></p> <p>This course seeks to engage the emergent body of scholarship known as Critical White Studies (CWS). This scholarship is designed to deconstruct the racial category “white.” We will examine the historical, legal, economic, gender, and aesthetic constructions of whiteness. Particular attention will be paid to the problem of blackface. We will also critically examine CWS. Core Requirement Met: United States Diversity.</p> <p><strong>Chattel Slavery and Its Afterlives</strong></p> <p>This course introduces students to the key theoretical and historical frameworks that elucidate the particularities of chattel slavery in the Americas both in its “pre-emancipation” manifestations and as, Saidiya Hartman notes, the ongoing machinations of captivity, domination, and dispossession by which antiblackness continues to structure and suture the world. In this course, the particularity of chattel slavery emphasizes how the economic and social function of the enslaved as laborer and commodity, the centrality of blackness as a fungible and immutuable category of the enslaveable (non)human, and the massive global function of chattel slavery as the foundation of capitalism distinguishes this formation from other historical or regional structures of slavery, labor exploitation, trafficking, and racialiezd domination. Furthermore, students will be challenged to confront the ways in which the de jure abolition of chattel slavery (in 1865 in the US and across the Americas in the 19th century) has been a historical, legal, and structural misnomer that does not encapture the ways in which societies, economies, and legal structures adapted to sustain rather than eradicate the global dependence on black subjection. Students will engage the prison industrial complex, abandonment &amp; deindustrialization, policing, geographic containment, the consumption of blackness as popular culture, formations of neoliberalism, and antiblack state and state-sanctioned terror as contemporary formations of chattel slavery’s afterlives. The course engages the geographic contexts of the US, Jamaica, Haiti, and other parts of the Caribbean. Cross-listed as BLST 375. <em>This class counts as a methods class for the CTSJ major. </em></p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7744,2021,515,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7745,2021,2548,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-398','<div class="desc"> <p>Working with a CTSJ faculty member, students will select an internship site whose mission is to address matters of inequality and social justice. The Department has a list of organizations where students can inquire about internships. Students who would like to intern at an organization will have to petition the department with a letter of support from the organization. The practicum experience will be evaluated by their field supervisor, the faculty liaison, and by the completion of the Social Justice Practicum Handbook. In addition to the internship responsibilities, students will participate in regular meetings with the instructor and attend class meetings. Additionally, they will complete a social justice practicum handbook, which requires deep reflection that brings the internship experiences in dialogue with critical theories related to matters of social justice. Students may participate in internships as individuals, pairs, or small groups, depending on the needs of the organizations. Open only to Critical Theory &amp; Social Justice majors with sophomore standing or above.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7746,2021,1693,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-399','<div class="desc"> <p>Students in this advanced methods course will join the professor in conducting research in the specialty areas of the instructor. This course will fulfill a methods requirement and will necessitate that the student participate with the professor and other students in a collaborative manner to meet the goals of the research project. Research methods may include: critical discourse, oral histories, archival work, ethnography, and cultural studies, quantitative analysis, interview methods. Research projects may include topics such as: (1) youth and incarceration; (2) the discourse of "war"; (3) Europe''s discourse on migrant people; and (4) literacy, language, and children, to name a few. Open to juniors and seniors only. Permission of instructor required. May be repeated once for credit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7747,2021,90,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-490','<div class="desc"> <p>This course is offered in conjunction with CTSJ majors'' ongoing research for the Senior Comprehensive Project. Seminar meetings will be devoted to discussion and critique of students'' work in progress, and to close readings of a select few texts in Critical Theory and Social Justice. Only open to senior CTSJ majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7749,2021,516,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7750,2021,120,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-101','<div class="desc"> <p>The purposes of this course are: (1) to introduce fundamental tools and perspectives on the study of world politics, including major theories and analytical approaches to international relations, (2) to understand the historical evolution of the contemporary international system, with special emphasis on the post-World War II era, and (3) to apply theoretical and conceptual understandings of international relations to current issues in world politics. Emphasis is placed on the state and trans-state foundations of contemporary international relations. We will study this in the context of such key issues as economic development, "security," human rights, state-building, international organizations, terrorism, and the intersection of social relations with world politics. Open to first years and sophomores. Permission of instructor required for junior and senior enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7751,2021,1655,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-102','<div class="desc"> <p>A survey of the role of international organizations in global politics. The focus will be on an in-depth study of the three themes by which the United Nations has defined itself: security, human rights, and development. Within the rubric of those three themes we will look at activities by the U.N. family of agencies, other international organizations, and NGOs, on issues that include the management of violent conflict, human rights, and how these issues have been mainstreamed into the work of international organizations and approaches to economic underdevelopment that seek to alleviate both poverty and insecurity.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7752,2021,2549,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-103','<div class="desc"> <p>This course is an undergraduate survey of the field of Global Political Economy (GPE), required to major in Diplomacy and World Affairs. It is intended as an introduction for students who already have some background in the field of International Relations (DWA 101) and Economics (Economics 101) and are interested in exploring global political economy theories, relations and issues. The course covers major theoretical, empirical and policy perspectives. The first part of the course will cover basic concepts and theoretical foundations of political economy: liberalism, marxism, realism, feminism, etc. The focus will be on core theoretical principles and approaches. The goal is to understand how theory is framed and how it "works"; the potential inferences of theories, and their practical import. The second part of the course delves into globalization as a field of study and set of empirical dynamics, building on the theoretical foundations of the first part of the course. The third part of the course explores emerging topics in global political economy such as global finance, the informal economy, the underground economy, the green economy/sharing economy/circular economy, gender and the global economy, corporate citizenship and responsibility, social enterprises, the sustainable development goals, social/economic rights and more. Open only to DWA majors; for non-majors, special permission of instructor required.</p> </div>','DWA 101 and ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7753,2021,1444,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-152','<div class="desc"> <p>This course will introduce social enterprise practices and theory while allowing students to work directly on a social enterprise project with global impact. This course will build on the 25 year foundation of collective knowledge in the field of Social Entrepreneurship through case studies and life challenges that continue to face the international community. We will look at how value creation and sustainability are key elements in the development of successful social enterprises, with emphasis on water, food, and housing/urban design. Our focus will be on how, through innovation and entrepreneurial approaches, we can access sustainable solutions to the world''s most pressing problems.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7755,2021,1588,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7756,2021,123,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-235','<div class="desc"> <p>This course will explore nationalism and ethnicity from both a theoretical and an empirical perspective. Nationalist and ethnic discourses have been central to political movements, rebellions, and revolutions. The passions and commitment of individual members in these movements often lead to political ideologies and war tactics that are violent, and which encompass entire communities. The class will concentrate on two theoretical perspectives; mainly the debates between primordialism and constructivism. Two cases from South/Southeast Asia and Sub-Saharan Africa will be analyzed.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7757,2021,2333,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected what was historically the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean that has developed into proper noun: the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological, and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the 20th century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-1939 Palestinian Revolt, the 1948 war for Palestine and its aftermath, Israeli-Arab relations in the 1950''s, the Suez War, the implications of gendering the nation, the 1967 war and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7758,2021,2850,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-210','<div class="desc"> <p>This course introduces students to the history, politics, and international context of Russia and other countries of the former Soviet Union. The course focuses on the political and economic transformation in post-communist Eurasia after the fall of the Soviet Union in 1991. We investigate the nature of domestic political systems of post-Soviet state, state-society relations, ethnic conflict, politics of economic reform, and the underpinnings of foreign policy-making in these countries. Students will learn about the region using the comparative method by engaging in reading and writing assignments that will require comparing outcomes of student’s choice both cross-nationally or temporally.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7759,2021,827,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-221','<div class="desc"> <p>Against the backdrop of 840 million persons worldwide suffering from malnourishment, and nearly 1.3 billion people living on less than a dollar per day, this course surveys the fields of international development, wealth creation, and global welfare, from a historical, global, and comparative perspective. The course will introduce students to the field''s academic contours, building from the historic role of economics in pioneering and undergirding the field, to a broad understanding of the now interdisciplinary field that has emerged. The multi-disciplinary and interdisciplinary perspective of this introductory survey course is in keeping with an emerging global consensus that measures of poverty go beyond income and consumption, and that poverty reduction requires bridging disciplines (Economics, Political Science, History, Anthropology, Geography) and methods (quantitative and qualitative, observational and participatory). The course will be divided into two parts. During the first part of the course, students will be introduced to the main theoretical ideas on social, economic, and political development that have informed the field''s evolution. This will familiarize students with fundamental thinking on development, as well as the frontiers of research. The second part of the course will explore some of the current debates about development. Students will analyze such debates in a rigorously multi-dimensional and interdisciplinary manner.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7760,2021,2425,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-222','<div class="desc"> <p>This course introduces students to the political economy of Latin America. The first section of the course looks at the rise of dependency theory and import substitution industrialization (ISI) as the region''s predominant development strategy. We will study the motivations behind ISI, its initial success in terms of economic growth, and the challenges associated with such strategies of development. We will focus on the origins of the 1980''s debt crisis, the abolishing of the ISI model, and the subsequent turn to neoliberal development strategies. The course aims to provide students with a deeper understanding of the transition to neoliberalism, the so-called Washington Consensus, and the broader political and economic implications of the reform processes that have unfolded since the early 1980''s. We will study the interaction between democratization and economic reform and aim to understand how these simultaneous transitions have affected the policy-making process and the formation of public policy in the region. Latin America is a diverse region, therefore this course will emphasize its economic and political diversity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7761,2021,1587,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-224','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century, with a focus on contemporary democratic politics. The course will discuss the historical, institutional, and social forces that have both accelerated and opposed democratization, and will cover topics of current concern to the region, including: economic development, security and the rule of law, the design of political institutions, human rights, and social movements.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7762,2021,1213,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-225','<div class="desc"> <p>This course offers students an interdisciplinary introduction to the historical and philosophical foundations of human rights, the creation of the international human rights regime in the mid-20th century, the impact of social movements on the evolution of international human rights laws and norms, and the impediments to the realization of human rights in practice. Through exploring thematic concerns such as women''s rights, LGBT rights, torture, capital punishment, international responses to genocide, and corporate responsibility, we will engage contemporary debates surrounding the universality of human rights, the relationship between human rights and inter/national security, the duty-holders of human rights law, and the gap between human rights ideals and enforcement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7763,2021,2334,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-226','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal," "populist," and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems, including the United States; and the challenges democracies are facing in integrating formerly marginalized populations, including women, poor, and the indigenous. It will examine the United States policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7764,2021,2826,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-227','<div class="desc"> <p>Thirty years after Francis Fukuyama proclaimed the "End of History," political authoritarianism remains viable while democracy is increasingly under threat around the world. Many dictators have embraced hypermobility of capital, free trade, and modern information technology. At the same time, deepening globalization has also challenged long-established democratic systems, producing anti-democratic political movements. We will investigate some of the following questions produced by the clash between global capitalism and local politics: How do authoritarian leaders react to the challenges of globalization in the 21st century? Does globalization undermine or enhance their hold on power? Will authoritarianism or democracy survive a long-term engagement with global markets?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7765,2021,2335,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-228','<div class="desc"> <p>This course explores efforts to conceptualize democracy, and to generate and test theories of democratization and the endurance of democracy. After considering the concept of democracy, we start by considering some of the classics, published in the second half of the 20th century. These are key works that have shaped the field and have largely set the terms of the debate. Then, we turn to the literature published after 2000 and consider how this literature has revised and built on ideas from the classics. We conclude with an overall assessment of knowledge about democratization and the endurance of democracy. In all, we will discuss explanations that put an emphasis on the economy and culture, as well as on politics itself. Much of what we will read reflects the focus of this literature on Europe, Latin America, and post-Soviet Eurasia. However, some African and Asian cases will be discussed and several global analyses will be considered. Emphasis will be put on the core theoretical and methodological aspects of this literature.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7766,2021,1327,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-229','<div class="desc"> <p>After a review of the historical, legal, and conceptual underpinnings of the international protection of human rights, students in this course will learn about human rights and mechanisms for their protection within the context of the United States and Latin America. Students will discuss key situations from the last half century involving challenges to human rights, including the phenomenon of disappearances common in Argentina and Chile in the 1970''s, violations of human rights during leading up to and during civil conflicts in Central America, and the impact of neoliberal economic reforms on human rights in the region. Students will explore the application of the death penalty in the United States, United States foreign policy on human rights in the Americas during the Cold War, and the claims of human rights abuse by the United States during the War on Terror. They will also have a chance to examine the United States from a double perspective: on the one hand as a key country with a major interest and impact on human rights conditions in Latin America, and, on the other, as a country with its own policy areas of struggle and progress.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7767,2021,548,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-230','<div class="desc"> <p>This course will explore the evolution of women''s rights as human rights; the struggle of women''s movements to place gender-specific concerns on the international human rights agenda; and the relationship of the UN and its agencies to the broad feminist goal of advancing the political, economic, social, and cultural status of women. While "women" are, of necessity, central to the concerns of this course, the study of human rights will be approached from a gender perspective, recognizing that gender relations is key to understanding the nature, occurrence, and prevention of rights violations. Key themes to be covered in the course include: the relationship between the "crisis of masculinity" and women''s human rights, gender and economic rights, gender-based violence, and health and human rights.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7768,2021,1115,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-231','<div class="desc"> <p>This course explores how assumptions of masculinity and femininity have informed foundational concepts and theories in the field of International Relations, the determination of what is considered to be worthy of investigation and what qualifies as appropriate methods of investigation, and who is (and is not) recognized as a subject of international politics. This course applies a gender lens to practical concerns in the field, including: political and economic development, human rights, and international security. It also engages the tensions associated with theorizing gender and IR, given the fluidity and intersectionality of identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7769,2021,549,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-234','<div class="desc"> <p>Revolutionary transformations and democratic transitions in Southern Africa have occurred under the conditions of the Cold War and within the framework of heightened globalization. Currently, direct foreign political interventions have been scaled back, but economic interventions by international organizations and foreign states have increased. Even though liberal democracy is winning favor the structural basis of inequality remains with increasing unemployment, poor education, weak health services, inadequate housing, soaring food and utility prices, and increasing levels of poverty. Opposition movements demand changes ranging from subsidized basic foodstuff to free education. This has contributed to political tensions as states scramble to suppress resistance while still trying to maintain the conditions required by global economic institutions. This course will examine some of the states in this region including South Africa, Mozambique, and Zimbabwe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7770,2021,1589,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-236','<div class="desc"> <p>This course examines the theoretical roots, ideological expressions, and political manifestations of these tumultuous phenomena. Focusing mostly on the European experience of the late 19th through the 20th century, we will read primary texts and historical accounts pertaining to the rise and development of nationalism, communism, and fascism. Readings will cover both the national and international aspects of these movements, and explore their political, cultural, and economic programs. What will also be of particular interest is how these often competing and clashing political programs sprang from similar and, at times, common roots. Ultimately, this course will ask students to consider what the study of such ideologies has to offer for the analysis of contemporary extremism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7771,2021,917,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-237','<div class="desc"> <p>The course will examine some of the communist countries that have survived the collapse of the Soviet Union, specifically: Cuba, Vietnam, and China. We will discuss the political and social life within each country, their relationship to the United States, and the prospects for political change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7772,2021,124,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-238','<div class="desc"> <p>This class will focus on South Asians who were indentured to British colonies from 1860, immediately following the abolition of slavery. Over one million Indians were indentured to Mauritius, South Africa, Guyana, Trinidad, and Fiji. South Asians currently constitute a substantial proportion of the population in each of these countries, and they are in the majority in Mauritius and Trinidad. We will conduct a comparative study based on theoretical perspectives related to the diaspora''s globalization, trans-state identities, and analytical themes associated with identity and citizenship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7773,2021,1656,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-239','<div class="desc"> <p>This course aims to introduce students to the history, politics, and economics of the European region from 1945 to present day. We will start by looking at the development of European states and political institutions in the post-WWII period, primarily those of Germany, France, the United Kingdom, and the Benelux countries. Our goal is to gain understanding of why European states have taken different political paths (including countries in Eastern Europe, the Nordic states, and Turkey), while also exploring the context of regional integration in which European states are embedded. The European Union (formerly the European Community) and its 28 member states are thus also central to this subject, as it encapsulates the development of key political institutions, civil society, representation, and economics on the continent. We will thus explore what has been accomplished by European integration (e.g., maintaining peace, increasing mobility, granting human rights, enhancing multilateralism, and strengthening democracy), as well as the considerable challenges that lie ahead (e.g., "Brexit", eastern enlargement, the stability of the Euro, the integration of refugees, and the rise of populist parties). In sum, the course is designed to introduce students to central topics in both past and contemporary Europe politics through the lens of political science and theories of regional integration. Situated at the intersection of comparative and international politics, these theories will help us to understand the complex interactions between national governments, supranational institutions, and the everyday lives of European citizens that define Europe today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7774,2021,125,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-241','<div class="desc"> <p>A study of Middle-Eastern international relations in the context of three themes that structure the region''s modern political history: (1) colonialism: how the reaction against colonialism continued to define and limit Middle-Eastern politics, both internally and in its relations with outside powers, (2) religion: in particular, political Islam (or "fundamentalism") is a key variable in the region''s contemporary politics, but by no means all-defining, and (3) nationalism(s): a source of political identity and mobilization. How religious, national, linguistic, and ethnic nationalisms inform conflict and cooperation within the region. </p> <p>In the context of these three themes, we will explore the following regional issues with global implications: (1) the Arab-Israeli conflict - the flash point of conflict in the Middle-East, the Arab-Israeli conflict can only be understood on the basis of an informed appreciation of its historical and ideological underpinnings, (2) Iran - the Iranian revolution had an enormous impact on regional and international affairs. Current unrest within Iran is perhaps a harbinger of yet another radical shift in Iranian politics, and (3) domestic upheaval in the region, as seen in the Arab uprisings of 2011-2012.</p> <p>Despite this being an "IR" class, on-the-ground social and political movements ("domestic," yet transnationally informed) have an enormous impact on the region''s politics. This is particularly true in the shadow of the recent Arab uprisings, upon which we will place particular attention.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7777,2021,1159,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-244','<div class="desc"> <p>This course is a survey of Iranian politics and society, from the establishment of the Qajar dynasty in the late 19th century to the present. The aims of the course are twofold: (1) to introduce students to major events shaping Iranian politics over the last century. Among the topics covered are: the rise and demise of the Qajar dynasty, the Persian Constitutional Revolution, the rise and fall of the Pahlavi dynasty, the role of Western imperialism, the geopolitics of oil, the 1979 Iranian Revolution, the Iran-Iraq War, the crisis of theocracy, etc.; and (2) to expose students to a set of theoretical and analytical issues underlying Iran''s political development, such as: the causes and consequences of revolutions, state-society relations, secularism and modernization, fundamentalism and reform, pluralism and democracy, autocracy and clientelism, corruption and the rentier state. Above all, this course is design to help students think, talk, and write in an informed and critical manner about politics in modern Iran.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7778,2021,1590,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-245','<div class="desc"> <p>This course will look at the relationship China has had to the world over the last 600 years. The course will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Thirdworldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the interaction between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the rise of the West, just as we will call into question the contemporary discourse on the "rise of China."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7779,2021,2537,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-246','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7780,2021,1377,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-248','<div class="desc"> <p>This course will examine major global public health problems and the range of responses from international organizations, transnational networks, and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century, the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as: HIV/AIDS, malaria, unsafe food and water, tobacco use, and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health, including morbidity; mortality; demography; epidemiology; and the political, social, and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political, economic, social, and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health, and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7781,2021,828,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-250','<div class="desc"> <p>This course is an introduction to International Security and Strategic Studies. This field is, fundamentally, about both the use of force by, and violent conflict among, states and non-state actors. The course will be guided by general theoretical questions regarding security: how does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: how do states and non-state actors use force to persuade their enemies to take (coercion), or refrain from taking (deterrence), a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure and the intensity, duration, and consequences of military action? We will have a particular focus on emerging transnational security issues, intra-state security, and the relationship between security development and state failure. Pursuing answers to these questions will require an approach that integrates theory, history, and current events. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7782,2021,1445,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-253','<div class="desc"> <p>China''s return (as opposed to rise) to its proportional place in the global economy has arguably caused a pivot towards Asia by the United States. While America''s hegemonic status in terms of hard (military) power remains undisputed, China''s gross domestic product may surpass that of the United States as soon as 2017. This course is a seminar on Asian security, covering military security, non-traditional security, and economic and political security, among other dimensions. The course surveys the Asian region, with particular emphasis on Southeast Asia (the ASEAN countries, particularly Cambodia Burma/Myanmar, Thailand, and Singapore) and Northeast Asia (China, Japan, South Korea, and Taiwan). The material is divided into three parts. The first provides an overall introduction and overview of Asian security and focuses on the foundations of what was thought to be the Asian Miracle (created in part from a U.S. security umbrella), just as the Washington Consensus rose to prominence. It takes students through the Asian Financial Crisis and its aftermath. Part two of the class focuses on Japan, South Korea, China, and Taiwan. It describes their development trajectories and security arrangements. Part three uses China as a platform to examine other parts of Asia not already covered, such as: China''s relationship with Southeast Asia, and the political economy of non-traditional security, in particular the region''s experience with Highly Pathogenic Avian Influenza.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7783,2021,1694,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-256','<div class="desc"> <p>This course analyses terrorism not only from a state security perspective, but also from one informed by political ethics, in which we seek to come to terms with the demands of justice in an age of violence resulting in large numbers of civilian deaths by both state and non-state actors. Broad questions include: what is terrorism? What are its causes? What are its consequences? Do terrorists operate from internally consistent and intelligible (even if horrific) frameworks? Must we sacrifice some of our cherished civil liberties in order to protect others? And what international, moral, and legal principles should guide us in an age of cyber warfare, drone strikes, and targeted assassinations?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7784,2021,2623,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-257','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? When and how to movements spread and diffusion their ideas globally? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention in various moments of time, while developing the conceptual skills that provide an introduction to social movement theory. In doing so, we will take an in-depth empirical look at movements for civil rights, women’s rights, LGBT (lesbian, gay, bisexual and transgender) rights, and immigrant rights. An analysis of these movements across multiple domestic and transnational contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7785,2021,2589,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-258','<div class="desc"> <p>In many countries, the subject of LGBT (lesbian, gay, bisexual and transgender) rights has entered the political discourse with unprecedented speed and suddenness. For an issue that was most often relegated to the private sphere, the rapid global expansion of LGBT rights, as well as changes in public opinion toward LGBT people, has been nothing short of remarkable. This course is designed to gain leverage on the processes that explain such changes by surveying an eclectic literature on comparative and transnational LGBT politics: from social movements to normative change in international relations. For these fields of study, the changes addressed above pose several important questions. It is no coincidence, for example, that dozens of countries now grant some form of same-sex unions, and understanding transnational politics helps us understand why. Specially, we will ask: What factors have facilitated the mobilization of LGBT people? Why and how have public opinion and state laws towards LGBT people changed differently across various countries?</p> <p>To find answers to these questions, we will analyze the political history of a movement that has captured the world’s attention, and one that has moved a marginalized group from the political periphery to the center of public debate and contestation. We will take an in-depth empirical look at movements representing LGBT people and their successes/losses—as well as those of their opposition—across time and place. The first portion of the course will begin with the organized movement’s earliest roots in early 1900s Europe, followed by suppression during WWII, and then the homophile movement of the post-war period. The remainder of the course explores the public manifestation of LGBT identities that grew out of the Stonewall’s gay liberation politics, mobilization around the HIV crisis, and the domestic and international politics surrounding the spread of LGBT rights and recognition in contemporary times. An analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts offered by social movements and international relations scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7787,2021,551,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-260','<div class="desc"> <p>Research, discussion, and analysis of important issues in International Relations in preparation for a three day college conference in early April. Student delegates role play as ambassadors for countries and present views negotiating with other representatives and arguing for possible resolutions in a simulation of the United Nations. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7788,2021,829,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-280','<div class="desc"> <p>This course explores the various facets of the globalization process and the politics of development. The first part of the course examines globalization, its causes and wide-ranging consequences, and its implications for U.S. domestic and foreign policy as well as for global governance. Has globalization benefited East Asia, Africa, and Latin America? What have been the differing impacts on those regions? Questions that will be addressed include: what are<br/> conceptual perspectives on globalization? What are the economic, cultural, and political dimensions of globalization? What are policy responses to the challenges globalization presents? The second part of the course examines the politics of various approaches to development and poverty reduction. This will include exploring how globalization is related to development, understanding current debates over foreign aid, and evaluating new and innovative strategies aimed at poverty alleviation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7789,2021,1214,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-281','<div class="desc"> <p>This course will explore the past, present, and future role of media in shaping global change, and guide students in the development of a global media campaign. The campaign will be the culmination of an inquiry around media as a tool for social change. From pivotal news events of the last twenty years, to the rise of reality television, social media, and declining influence of print and broadcast journalism, this course will use media literacy case studies and comparative analysis of news coverage and critical analysis of cinema trends in art and culture to explore media''s impact on social norms and cultural-narratives. Specifically, we will examine the role of media in various revolutions worldwide - the recent role of social media in the overthrow and transition of the Egyptian government (the Square), the role of song in South Africa''s struggle for freedom, and international news coverage of the Feminist Movement and the Black Panther party. How is it that movements are organized using media as a tool for social change? Professional writers, media executives, and branding experts will be guest speakers for viewing-salons that will be scheduled throughout the semester. Students will learn media literacy skills and develop critical thinking by engaging with the role media plays in major historical, cultural, and social issues; become active learners as they gain proficiency to approach their own personal inquiries with creativity and scholarly rigor; gain expression through visual storytelling, data visualization, and social media, as they create their own global media campaign and present it at a final salon for the course; and participate in the shaping of the narrative around global social change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7790,2021,830,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-282','<div class="desc"> <p>A critical examination of greater Los Angeles and it''s economic, political, social, and cultural ties to the world economy and other countries--all the ways in which Los Angeles is an integral part of the post-Cold War global society. How does this globalization affect the life of Los Angeles and in what ways does Los Angeles contribute to globalization? What are the positive and negative impacts and the implications for United States foreign, economic, and social policies of Los Angeles as a Global City? </p> <p>This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CSP 1, CTSJ 105, and SOC 105.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7791,2021,1215,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-283','<div class="desc"> <p>This course will study how the concept of soft power - first developed by Harvard professor Joe Nye - applies to interactions among nations in the 21st century. Soft power lies in the ability to attract and persuade, whereas hard power - the ability to coerce - grows out of a country''s military or economic might, especially in an imperial/colonial period. Students will analyze how trade, culture (music, food, sports, language, education), environment, and political institutions (democracy, corruption, human rights, etc.) contribute to a country''s soft power and make up its global brand. Students will analyze the current state of soft power in key nations and consider how countries and their citizens can affect the attractiveness of a country''s culture, ideas, and institutions in order to raise its soft power. The course will introduce students to the idea of global sustainable diplomacy, which pursues global goals using soft, not hard, power.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7792,2021,1066,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-284','<div class="desc"> <p>A critical examination of the political and economic role that sports play in the globalized world - the diplomatic, political, and economic effects of the Olympics, the World Cup, other international sporting events, and the increased globalization of professional sports leagues across national boundaries. A look at case studies of ping-pong diplomacy, rugby reconciliation in South Africa, and soccer wars in Latin America, as well as an analysis of the impact of foreign players on national economies and societies, from American baseball players in Japan, to Russian ice hockey players in the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7793,2021,1330,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-285','<div class="desc"> <p>This course aims to introduce students to both analytic and normative approaches to the study and practice of diplomacy in international politics. In the first part of the course, we will chart the evolution of diplomacy from a tool of statecraft in the modern states system, to a practice of mediating disputes and estrangement in international society. The second part of the course is devoted to examining a series of historical case studies illustrative of the successes and failures of modern diplomacy. The last part of the course considers the utility and limitations of contemporary diplomatic practices for major international trends and developments, such as: globalization, militarism, financial crises, extremism, and environmental degradation. This course is, above all, designed to help students think, talk, and write in an informed and critical manner about complex and seemingly intractable global issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7794,2021,1514,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-286','<div class="desc"> <p>This course will look at the use of public diplomacy in the United States since the end of the 19th century. The concentration will be on U.S. public diplomacy towards Latin America and the Caribbean, Latin America-China relations, and Latin America''s relations with the rest of the world.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7795,2021,1696,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-288','<div class="desc"> <p>This course examines the major challenges of our environment and its relationship to politics and policy issues. We will cover topics addressing the normal functioning of the Earth, including the water cycle, carbon cycle, and the atmosphere. We will concentrate on the behavior of humans that affect these processes. We will tackle issues of state development, particularly industrialization and its consequences (including the increased use of fossil fuels, pollution of water, widespread deforestation, climate change, etc.), and their effects on the environment in which we live. We will discuss these problems and consider solutions at the international, national, local, and personal level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7796,2021,1515,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-290','<div class="desc"> <p>This class looks at global issues - including energy development, climate change, satellite imaging, and forms of communication - that have technical aspects. We then take these topics and place them in the cultural, political, and economic international context: how are states, non-state actors, international organizations, and non-governmental organization handling these issues?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7797,2021,127,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-295','<div class="desc"> <p>Topics vary semester to semester. </p> <p><strong>Trump Foreign Policy</strong></p> <p>Donald Trump campaigned on a platform of America First nationalism and anti-globalization. He expressed views out of the mainstream of bi-partisan United States foreign policy since World War II. Has President Trump made good on his promises to change dramatically America''s global role or has he had to adjust to the reality of the current international system and long standing US policies and alliances? This course will survey all aspects of Trump foreign policy in order to try to understand continuity and change in America''s role in the world. Students will be asked to examine what Trump has and has not accomplished in the international arena, and to access the costs and benefits of his policies for America and for the global community.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7800,2021,831,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-299','<div class="desc"> <p>The goal of this course is to provide students with some of the tools to embark on systematic inquiry in Political Science. It will introduce students to qualitative methods in Political Science; ethical issues in qualitative research, proposal writing, and interviewing techniques; and finally, the essential components of a research paper (a proper research question, thesis, literature review, and case selection). Guidance through the Institutional Review Board process will be provided. This course is geared towards students preparing grant applications, preparing to conduct research abroad, and/or preparing for their Senior Comprehensive thesis since they will be expected to apply the methods they learn to their own research topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7801,2021,1010,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-310','<div class="desc"> <p>As of late, religion has re-emerged on the political stage, offering different perspectives regarding political norms, values, and behavior. In this course, we will explore the various ways in which religion has been conceptualized and utilized in different political and cultural settings. Some of the questions that we will seek to answer are: in what ways can religion be separated from politics? What are the roles of religion and religious institutions in political life? How do religions and religious institutions respond to the challenges of a pluralist and secular modern world? Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7802,2021,2931,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-320','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature (from various disciplines) on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention across various moments in time, while developing the conceptual skills that provide an introduction to social movement theory in international relations. A comparative and transnational analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work. </p> <p>This course is also intended to improve your writing and research design skills. In academic scholarship, engaging an interesting topic—in our case, social movements—combined with a tool kit of well-developed methodological and writing skills is essential for articulating ideas to a wider audience. Most social science disciplines necessitate the ability to present evidence pertaining to an issue, engage with counter evidence, and ultimately present a convincing argument for a particular position on that issue. Under the rubric of writing broadly for multiple academic disciplines and popular audiences, we will engage several stages of the writing process, which include: (1) note taking and careful analysis of relevant texts; (2) proper use of secondary and primary sources, as well as citation style; (3) drafting texts; (4) revising and peer review (both in class and individually with the instructor); and (5) presenting a polished final research design paper that uses effective grammar, punctuation, and style. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7803,2021,1067,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-329','<div class="desc"> <p>Trafficking in persons - the use of force, coercion, fraud, or deception for purposes of exploitation - is the third most profitable form of illicit activity, globally, following the traffic in drugs and arms. In this course, we will explore the different forms of trafficking, including domestic servitude, sweatshop labor, migrant agricultural work, and child soldiering, although the course will focus most closely on the topic of trafficking for purposes of sexual exploitation. Throughout the class, the causes, consequences, and responses to trafficking will be analyzed through a human rights lens. We will study the processes behind the construction of gender identities in order to gain insight into why particular populations are especially vulnerable to trafficking, and why certain constraints exist to prevent and respond to trafficking at both the domestic and international levels. We will study the relationship between trafficking and militarism, including the legacy of the United States'' military presence in Asia for sex tourism, and trafficking in the region today. And we will engage the debate over whether trafficking is a "discourse" that perpetuates relationships of dominance and subordination between the global North and South. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7804,2021,1697,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-332','<div class="desc"> <p>A digital exploration using mapping techniques to study the movement and political engagement of over 1.3 million Indians who were indentured from India to various British colonies between 1833 and 1920. They currently constitute either large majorities or strong minorities in these former colonies. Some of the countries that will be studied include Fiji, Trinidad, Mauritius, and South Africa.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7806,2021,1446,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-335','<div class="desc"> <p>African theorists have historically integrated theoretical critiques with revolutionary practices. This class will focus on theories pertaining to opposition to colonialism in Africa, as well as in the Caribbean and the United States. Theorists such as Franz Fanon, Steve Biko, Kwame Nkruma, Eric Williams, and Marcus Garvey will be studied. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7807,2021,919,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-337','<div class="desc"> <p>This course takes a more in-depth look at the theories and approaches of international relations.The goal of the course is to provide students with an appreciation of how theory is able to achieve three things: 1) explain, 2) critique, and 3) guide the actions of individuals, institutions, and states in the international arena. Theorizing, therefore, is not simply an abstract exercise but can have real world implications. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7808,2021,1068,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-338','<div class="desc"> <p>The place of human rights in the transnational Muslim world in comparative and theoretical perspective. The focus will be on 20th century political and ideological events in the Muslim world broadly defined to include its diverse formations. There will be particular attention paid to movements for the integration of human rights into domestic, international, and transnational politics, and attendant theoretical questions. The course will be reading-intensive and we will focus class discussions around each week''s readings. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7809,2021,129,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-340','<div class="desc"> <p>International law has taken an increasingly central, and often controversial, place in contemporary international relations. This junior writing seminar will explore the foundations of international law, human rights law, and humanitarian law. It will do so in the context of their intersections with topical issues that range from international criminal law, torture, non-state transnational actors, humanitarian interventions, and sexuality, and will have a particular focus on the theoretical foundations for human rights. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7810,2021,552,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-342','<div class="desc"> <p>This class will explore the various aspects of transnational identities, focusing on ways in which they challenge state borders and state nationalisms. The various aspects of transnational identities, like questions of citizenship, ethnicity, religion, gender, and generation will be analyzed. Special attention will be given to the ways in which Islamic beliefs have transcended state boundaries and the impact this has had on notions of citizenship. The class will also focus on a few case studies to highlight the various aspects of transnational identity. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7812,2021,2434,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-344','<div class="desc"> <p>Post-conflict reconstruction in the wake of war and state-building have been prominent activities in international security. The international community now addresses non-state conflict with vigorous programs of state-building. Former President George W. Bush writes in his biography “Afghanistan was the ultimate nation-building mission.” The prevailing post-conflict reconstruction paradigm emphasizes building indigenous capacity – security, governance, judicial, social and economic – so that peace can be sustained without outside intervention. The agents of transition from war to peace are varied in type: internal and external; military and civilian; governmental, intergovernmental, non-governmental and private sector. Military personnel, for example, have long performed many services in the chaos of war and its aftermath: providing emergency medical treatment, food and shelter for dislocated civilians; patching infrastructure, running town meetings, building schools, patrolling streets and training security forces. Aid workers braved great danger to relieve human suffering. A broad array of peace builders today attempt ambitious agendas for human security, effective participatory governance, economic liberalization, and rule of law. The common goal of these activities is to build a basis for political and economic development. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7813,2021,2739,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-345','<div class="desc"> <p>This course will examine the transformation of states, nations, and identity in the contemporary period. Special focus will be given to how transnational developments (in politics, economics, and culture) are redefining modern societies, particularly as the number of democracies has increased worldwide over the last thirty years. The course will also grapple with the challenges and dilemmas of current states. Democratization does not mean democracies are here to stay—as such the course will discuss de-democratization, democratic backsliding, illiberalism, and populism to understand how everyday individuals are affected. In doing so, the class reflects on the experiences of formerly marginalized populations—including women, poor, and the indigenous—by considering the role of states and international organizations in the lives of everyday individuals. Only open to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7814,2021,1162,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-350','<div class="desc"> <p>Each year this course will focus on some sub-set of contemporary issues in the global political economy. This could include topics such as: the state of the global economy and global economic crises, multinational corporations and corporate social responsibility, global production and supply chains, emerging forms of regulation in the global economy, transparency and accountability, and global inequality, among others. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7815,2021,1516,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-351','<div class="desc"> <p>This junior seminar will focus on advanced scholarship on global sustainability/sustainable development. Since the Bruntland Commission''s Report in 1992, these issues have become central to world affairs and diplomacy, all the more so as the scientific and policy consensus around climate change has grown over the subsequent two decades. Most recently, in September 2015, 193 member states of the United Nations agreed to a set of bold Sustainable Development Goals. The course will provide students with knowledge about the genesis, characteristics, dynamics, and consequences in the area of global sustainability/sustainable development. It is also a course focused on research and writing in International Affairs, preparing students to write their Senior Comprehensives. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7817,2021,2881,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-355','<div class="desc"> <p>Economic and social rights include the right to an adequate standard of living, the rights to food, water, housing, and education, as well as the right to work and for basic income guarantees for those unable to work. The course examines the legal and philosophical foundations of economic and social rights, as well as challenges to the legality and legitimacy of these rights. We will examine the status of economic and social rights in the global human rights regime, and we will explore provisions for economic rights at the national level. We will discuss the connection between socio-economic rights and poverty, development, and globalization. Students will explore issues of measurement and policy implementation through a range of case studies and cross-regional comparisons. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7818,2021,1163,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-368','<div class="desc"> <p>America is the most powerful nation in the post-Cold War world but has not, as yet, forged a national consensus on post-Cold War foreign policy. The country and the world have repudiated the neo-Con Unilateralist approach of the Bush administration, but there is no agreed upon substitute. Various authors are proposing strategies from "ethical realism," to "liberal interventionism," to "neo-isolationism," and on. The course will critically examine proposals for a new American Grand Strategy from leading foreign policy thinkers and from groups such as the Princeton project. We will try to agree on what a workable Grand Strategy might be and analyze whether it might have widespread bi-partisan support at home and ample international support abroad. Open only to DWA or Politics majors with junior or senior standing.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7820,2021,553,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7821,2021,1118,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-401','<div class="desc"> <p>The topic of this course will change from year to year at the discretion of the Director of the Oxy at the UN Program. Topics may coincide with the annual theme of the United Nations.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7822,2021,1119,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-402','<div class="desc"> <p>The importance of conflict prevention and conflict resolution policies has long been recognized at the United Nations. The debate was originally focused on the effectiveness of peace-keeping operations and traditional diplomatic measures. Its parameters have been broadened considerably and now encompass longer term efforts to assist developing countries in enhancing durable structures conducive to peace and democratic stability and the targeted use of development cooperation. Combining theoretical/conceptual and practical concerns, and drawing from case studies of recent conflicts, the ultimate objective of the course is to identify feasible short term and long term conflict prevention strategies and tools and to develop practical suggestions to move from a culture of reaction to a culture of prevention. More specifically, the course will deal with: (1) the evolving meaning of prevention as it was understood in the Charter of the United Nations and subsequently shaped by the changing causes and nature of conflicts; (2) the main actors in conflict prevention against the backdrop of UN institutions; (3) the tools and practice of "operational" prevention (i.e. early warning, mediation, sanctions, peace operations, peace enforcement, and the role of regional organizations); (4) the tools and practice of "structural" prevention (good governance and democracy, mainstreaming human rights and gender, meeting post conflict reconstruction, and addressing the root causes of conflict); and (5) the significance of the emerging norm of the "responsibility to protect".</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7823,2021,1120,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-403','<div class="desc"> <p>This course will provide students with practical hands-on experience through an internship with a UN agency or a member state mission. This will be a professional undertaking, requiring intensive engagement with high-level responsibilities. The internship will be complemented throughout the semester, with the following three elements: (1) a bi-weekly seminar to fully process the learning and practical experiences of the internships; (2) a guest speaker series for dialogue with UN leaders; and (3) a bi-weekly analytic notebook that will provide an opportunity for students to critically analyze internship experiences, guest lectures, and assigned reading materials.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7824,2021,1012,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-410','<div class="desc"> <p>The abilities to locate, compile, synthesize, evaluate, and compellingly present complex and up-to-date knowledge on rapidly changing global issues - and to do so in a team - are highly valued across public, private, and civil society sectors. This course helps students learn and practice how to research, write, and present an extended policy-/practice-oriented report for a real-world client on a contemporary and exciting topic in World Affairs and practice being part of a high-functioning team. The topic and, thus, client will be unique each time the course is taught. The skills acquired and applied in Task Force help students stand out as they venture into the world and towards the jobs and activities they are passionate about in Diplomacy and World Affairs. This course may be repeated one time with permission of instructor.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7826,2021,554,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-490','<div class="desc"> <p>Preparation, research, writing, and discussion of senior thesis projects in fulfillment of the Senior Comprehensive requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7829,2021,2538,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/easn-east-asian-studies/200/easn-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7830,2021,2550,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/easn-east-asian-studies/200/easn-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Cultural Appreciation and/or Appropriation through the Lens of Asian Cinema</strong></p> <p>At its core, this course is an attempt to investigate, analyze, and ultimately comprehend the concept of cultural appropriation, in particular through an East Asian context. With a history of imperialism, be it Western or Japanese, in the 19th and 20th centuries, the topic of cultural appropriation is controversial and complicated, whether it is Katy Perry performing wearing a kimono at the American Music Awards or Chinese-Taiwanese-American chef Eddie Huang and his embrace (appropriation?) of African-American black culture. Prior to the actual viewing and analysing of films, a comprehensive, albeit limited, survey of theoretical works will be conducted; works including but not limited to Richard Rogers’ “From Cultural Exchange to Transculturation: A Review and Reconceptualization of Cultural Appropriation,” Baris Buyukokutan’s “Toward a Theory of Cultural Appropriation,” and Lisa Nakamura’s concept of “identity tourism.” Some of the pairings to be analyzed are: William Shakespeare’s <em>King Lear</em> and Akira Kurosawa’s <em>Ran</em>; Clint Eastwood’s <em>Unforgiven </em>(1992) and Lee Sang-il’s Japanese Western <em>Yuzusazarumono </em>(2013).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7836,2021,131,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/100/econ-101','<div class="desc"> <p>An introduction to the economic way of thinking that includes both micro- and macroeconomic topics. We begin with an analysis of how market supply and demand help allocate resources and discuss market power, market failures, and the role of government regulation. We explore the determination of gross domestic product, the problems of unemployment and inflation, and macroeconomic policy making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7837,2021,132,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/100/econ-102','<div class="desc"> <p>A continuation of ECON 101 that completes the coverage of economic principles by incorporating the development of more sophisticated analytical tools. Microeconomic topics include: production costs, the behavior of firms under different market structures (competition, monopoly, and oligopoly), taxation and income distribution, and input markets. Macroeconomic topics include: the Keynesian model of output determination, the monetary system, and the effects of fiscal and monetary policies.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7838,2021,1121,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/100/econ-151','<div class="desc"> <p>The 21st century has witnessed an explosion of practical interest, research, and teaching on entrepreneurship and leadership across sectors of economic, social, and political life. Entrepreneurial leadership connects critical thinking to creative problem-solving and solution seeking. The range of models includes: technology innovators, social entrepreneurs, policy innovators, non-profit leaders, responsible business managers, among others. This course will provide students with a synthetic and multi-disciplinary overview to entrepreneurial leadership at the individual, organizational, and societal levels. Students will engage with the latest thinking, practical case-studies, and guest-entrepreneurs from the social, economic, cultural, and political spheres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7839,2021,555,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/100/econ-197','<div class="desc"> <p>Internship in a business or management setting. Permission of instructor required. Course may not be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7840,2021,136,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/200/copy-of-econ-272','<div class="desc"> <p>The use of regression and correlation to test economic hypotheses. Emphasis will be on the use and interpretation of single equation regression techniques rather than on their derivation. Familiarity with computers required.</p> </div>','ECON 102; at least Calculus 1 and COMP 146 (or equivalents); one additional ECON course above ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7841,2021,2895,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/200/econ-201','<div class="desc"> <p>This class will introduce students to a variety of different frameworks for measuring, tracking, assessing, and rating sustainability using Occidental College as our laboratory. The class will work with sustainability data used for sustainability initiatives like: the Real Food Challenge, The Association for the Advancement of Sustainability in Higher Education’s (AASHE) STARS framework, and the Second Nature Internal Carbon Pricing Higher Education Toolkit. During the class students will have the opportunity to become a U.S. Green Building Council certified LEED Associate.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7843,2021,133,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/200/econ-233','<div class="desc"> <p>Accounting principles and practices. Recording financial data assets, liabilities, owner equity income, and expenses; preparing and analyzing financial statements. Permission of instructor required for first year student enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7844,2021,134,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/200/econ-250','<div class="desc"> <p>Foundations of microeconomic theory. Topics include: the analysis of consumer theory and decision making; the theory of the firm under perfect competition, general equilibrium, and market inefficiency arising from monopolistic/oligopolistic/strategic behavior; incomplete information; externalities; and public goods. Should be completed before the end of the sophomore year. May be taken before or after ECON 251. Should not be taken in the same semester as ECON 251.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7845,2021,135,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/200/econ-251','<div class="desc"> <p>A study of the factors that influence and are involved with the national economy. Aggregate analysis as applied to problems of national income, accounting and determination, inflation, unemployment, modern economic growth, and the influence of the money supply. May be taken before or after ECON 250. Should not be taken in the same semester as ECON 250.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7847,2021,556,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/200/econ-297','<div class="desc"> <p>Application of modern research methods to current problems in Economics and related fields. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7848,2021,557,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-301','<div class="desc"> <p>The purpose of this course is to illustrate the role that economics can play in creating and improving environmental policy. We will apply the theories of economic efficiency, cost-benefit analysis, market failure, and property rights to environmental policy and regulation. We will cover the principles of market-based environmental policies and their applications in the world today. We will touch on all aspects of the economy''s interaction with the environment, including air and water pollution, global warming, environmental health, non-market valuation, and resource extraction.</p> </div>','ECON 101 or ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7849,2021,1447,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-302','<div class="desc"> <p>A study of firms and industries in the United States economy. Topics include: the acquisition and use of market power by firms, strategic behavior of firms in oligopoly markets, and antitrust policy. The course will approach topics from both theoretical and applied perspectives.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7850,2021,921,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-305','<div class="desc"> <p>This course is an introduction to the study of strategic interaction using the tools of game theory. The focus of the course is on developing a set of analytical techniques with the goal of understanding and using game theoretical models in economics. The first part of the course introduces the basic framework and tools of game theory. The second part of the course covers a number of economic (and some non-economic) applications of game theory; specific topics may include: auctions, bargaining, voting, and market competition.</p> </div>','ECON 250 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7851,2021,2676,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-306','<div class="desc"> <p>This course builds on ECON 272 to cover advanced topics in econometrics including: panel data, binary response models and causal inference. Theoretical models of regression and empirical coding will both be emphasized. </p> </div>','ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7852,2021,558,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-308','<div class="desc"> <p>This course studies the government''s role in a market economy, particularly policies that work through government spending and taxation. There are two primary motivations for government intervention: to correct a market failure or to mitigate poverty and inequality through redistribution. The course is organized around these two rationales, with attention to topics that include climate change, public education, health insurance, Social Security, welfare policy, and the taxation of goods, labor, and capital. We study how such government policies impact behavior and, as a consequence, how they should be designed to maximize welfare. This course also introduces students to the modern methodological approach in public economics that tightly connects economic theory with credible empirical evidence to generate policy insights.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7853,2021,832,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-309','<div class="desc"> <p><strong></strong></p> <p> The Austrian School of Economics, so-named because of the national origin of its founders, is an alternative approach to Economics that emphasizes methodological individualism and subjectivism. The Austrian School of Economics traces its roots back to the works of the Spanish Scholastics of the 16th century and stresses the importance of the individual, private property, limited government, and the organizing power of the free-market. Students will read from authors such as Menger, Mises, Hayek, Kirzner, Rothbard, and Hoppe, and evaluate various properties of a state-planned economy versus a decentralized free market economy.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7854,2021,138,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-311','<div class="desc"> <p>Economic activity in a global context. The first part of the course covers the causes and consequences of international trade, with a consideration of both national welfare and income distribution issues. Coverage then turns to trade policy in theory and practice, with a focus on the current global trading environment under the World Trade Organization. The course finishes by examining international investment and debt issues, including the role played by the International Monetary Fund during global financial crises. May not be taken for credit by students who have taken DWA 220/POL 232.</p> </div>','ECON 102 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7855,2021,1069,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-314','<div class="desc"> <p>This course examines the historical development and the role of institutions underlying market economies. It discusses the many forms which institutions (i.e. social norms, laws, and regulations) affect economic behavior and performance. Based on examples from United States and European economic history, topics will include: contract enforcement; trading institutions; political institutions; financial institutions; property rights in land and environmental resources; regulation of labor and capital markets; and the origin and development of one of the most important economic institutions, the firm. We will pay particular attention to institutions that emerged in response to market failures and to the changing nature of economic institutions over time.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7856,2021,923,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-315','<div class="desc"> <p>An empirical and analytical study of financial markets. Topics covered will include: net present value calculations, the capital asset pricing model, financial derivatives, the efficient market theory, the term structure of interest rates, and banking.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7857,2021,1217,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-319','<div class="desc"> <p>This course examines the application of economics to the law. Studies of actual cases reveal how economics can be applied to address such questions as: (1) whether an action violates the law, (2) who experiences economic harm as a result of that action, and (3) what the legally prescribed consequence is. Specific applications include: property rights related to technical innovation, competition in concentrated industries, and the extent of corporate liability. The primary context is the United States, but other legal systems provide some specific comparisons.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7858,2021,559,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-320','<div class="desc"> <p>Theoretical and empirical analysis of the process of economic development in less developed countries. After examining several theories of growth and development, we will discuss inequality and poverty, the effects of population growth and rural-urban migration, saving and financial markets, international trade, foreign aid and foreign borrowing, agriculture, and the role of the government. Case studies will be drawn from the development experiences of Asian, Latin American, and African economies.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7859,2021,2626,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-321','<div class="desc"> <p>This course provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7860,2021,2827,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-322','<div class="desc"> <p>Are goals of economic development and sustainability at odds with one another? What kinds of policy instruments could help us effectively reduce emissions, and why is international cooperation so difficult to achieve? This course offers a critical examination of sustainable development from the economics perspective. Beginning with conflicting views of sustainable development, the course proceeds to study how economists approach challenges such as climate change, management of common property resources, growth and poverty, measurement of well-being, and global health.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7861,2021,1013,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-324','<div class="desc"> <p>This course examines the economic causes and consequences of immigration. The focus of the course will be on the United States'' experience. However, we will also examine aspects of other international migrations. The course will focus on the economic reasons that motivate people to migrate to other parts of the world, the labor market and fiscal impacts of immigration on sending and receiving countries, and the economic consequences of U.S. immigration policy choices.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7862,2021,833,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-325','<div class="desc"> <p>The goal of Labor Economics is to enable you to use economic analysis and reasoning to understand wage and employment determination in U.S. labor markets. This course will expose you to current theoretical and empirical debates within the discipline. We will cover such topics as: labor force participation, labor demand, unemployment, labor mobility, wage structure, labor unions, human capital investments (education and training), internal labor markets, and labor market discrimination. Relevant public policy issues such as the minimum wage, living wage ordinances, compensating wage differentials, immigration policy, affirmative action, income inequality, and welfare programs will also be addressed in this course.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7863,2021,924,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-326','<div class="desc"> <p>An application of economic analysis to various topics in personnel economics, including: compensation and incentives, hiring, training, downsizing/buyouts, stock options, pensions, and teams, among many others. In order to add realism to, and applications for, the analysis, students will discuss and evaluate numerous real-world mini-cases and more formal case studies. Students will be evaluated on the quality of their written work, problem sets, examinations, and discussion; a variety of class formats will be used. Note: Students who take this course may not take Professor Moore''s section of ECON 495.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7864,2021,1331,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-327','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women in the United States, this course is designed as an overview of major theories, trends, and debates on the topic of gender in the labor market. We will examine gender differences in economic outcomes through the use of economic models, including feminist extensions and critiques of such models. Topics include: the family as an economic unit; gender differences in education, work, training, and income; and the economics of marriage, divorce, and fertility. Permission of instructor required for students who have successfully completed ECON 328 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7865,2021,139,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-328','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women and minorities. Topics include: the economics of slavery, racial and sexual discrimination, labor market segmentation, wage differentials, labor force participation, red-lining, and income inequality. Relevant public policy issues such as affirmative action and welfare will also be addressed. Permission of instructor required for students who have successfully completed ECON 327 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7866,2021,2740,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-329','<div class="desc"> <p>Despite a widespread desire to provide equality of opportunity to all people in the United States, family background has an enormous effect on the way children grow up and the opportunities available to them in adulthood. Family income can explain more than a third of a child’s future adult income, and all aspects of family background can explain half to two thirds of a child’s future income, education, and wealth. In this class, we will explore economic theories and evidence explaining the inheritance of advantage, with a particular emphasis on understanding the role of the family, the role of neighborhoods and communities, and the role of discrimination. We will also discuss the role of public policy in increasing intergenerational mobility and reducing social and economic disadvantages, both in the United States and around the world.</p> </div>','Econ 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7867,2021,1448,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-331','<div class="desc"> <p>An introduction to the history of radical philosophical alternatives to neoclassical and Keynesian Economics. A critique of these mainstream schools is followed by the development of competing radical alternatives with the analytical focus on concepts of economic surplus and social class, exploitation, alienation, and theories of capitalist development crisis and transformation. Ethnographic case studies provide examples of archaic and contemporary alternative economic practices. Special attention is paid to philosophies of human nature, the labor process, problems of racism and sexism, imperialism, current U.S. economic problems, and socialist alternatives.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7868,2021,834,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-340','<div class="desc"> <p>This course will provide an introduction to the relatively new field of Behavioral Economics. Standard models of economic theory provide a useful, but not always realistic, way to characterize how individuals make decisions. In this course, we will investigate the evidence showing how people may behave in ways that are not predicted by this standard theory. Individuals may exhibit nonstandard preferences, nonstandard beliefs, or nonstandard decision-making. We will look at each of these in turn, with applications that may include saving, finance, labor supply, gift-giving, voting, and addiction. The methodology of the course will not itself deviate from the standard way of doing economics; we will state clear assumptions, build models, determine their logical conclusions, and think about how to empirically test both the assumptions and implications of such models.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7869,2021,140,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-350','<div class="desc"> <p>The application of economic theory and analytical tools to business and management decision making. Topics to be covered will include examples from a variety of fields, including: pricing, ethics, entrepreneurial startups, strategy, new products, acquisitions, marketing, human resources, and production. The course will include a large number of case studies with required student presentations.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7870,2021,1166,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-351','<div class="desc"> <p>In the current economic climate, what should macroeconomic policymakers do to help the U.S. economy? This course analyzes the current macroeconomic policy challenges facing the United States from the vantage point of modern macroeconomics and economic history. Students will read state-of-the-art empirical research in macroeconomics and develop a sense for how macroeconomists conduct research and make policy recommendations. Special emphasis will be placed on exposing students to the major developments of U.S. monetary and fiscal policy since the Great Depression and on the role of history in guiding contemporary macroeconomic policy decisions and debates.</p> </div>','ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7871,2021,1591,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-352','<div class="desc"> <p>Firm-level studies are now at the forefront of international trade research. In this course, we look at firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. We use modern trade theory to analyze firm decision-making; we start with a discussion of the firm''s decision to engage in international commerce and then examine how firms choose between various types of foreign direct investment. Throughout the course, we learn from empirical studies and business case studies how firms engage in international commerce.</p> </div>','ECON 250 and ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7872,2021,561,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-395','<div class="desc"> <p>Topics vary semester to semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7873,2021,562,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/300/econ-397','<div class="desc"> <p>Advanced independent research in Economics. For example, Advanced Econometrics can be taken on an independent study basis. Permission of instructor and department chair required.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7874,2021,142,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/400/copy-of-econ-495','<div class="desc"> <p>An intensive application of economic analysis to issues chosen by the instructor in consultation with students during the course. The course emphasizes the development of analytical writing, team-work, and presentation skills, and is meant to be an opportunity for students to apply their economic training to specific topics. Complete descriptions of the seminars offered in a given year will be mailed out to students prior to the Spring registration. Senior status is required for this course. Students who will be off campus in the Fall of their senior year must contact the department chair by the end of their junior year to arrange a substitute senior seminar. </p> <p><strong>Firm-Level International Trade and Investment</strong></p> <p>This seminar studies firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. Topics discussed include the decision to export, foreign direct investment, outsourcing/offshoring, GATT/WTO and various trade agreements. We use modern trade theory to analyze firm decision-making and also learn how firms engage in international commerce from empirical studies and business case studies. Not open to students who have taken ECON 352.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250. </p> <p><strong>Industrial Organization</strong></p> <p>This course introduces the field of Industrial Organization, which is the study of firms in markets. We will analyze the acquisition and use of market power, strategic interactions among firms, and the role of government competition policy. Our approach will blend two alternative, but complementary, methodologies: theoretical modeling of strategic firm behavior and industry equilibrium, and the factual detail found in case studies of specific industries. Not open to students who have taken ECON 302.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250. </p> <p><strong><strong>Macroeconomic Policy since the Great Depression</strong></strong></p> <p>In the current economic climate, what should macroeconomic policymakers do to help the United States economy? This course analyzes the current macroeconomic policy challenges facing the United States from the vantage point of modern Macroeconomics and economic history. Students will read state-of-the-art empirical research in Macroeconomics and develop a sense for how macroeconomists conduct research and make policy recommendations. Special emphasis will be placed on exposing students to the major developments of United States monetary and fiscal policy since the Great Depression, and on the role of history in guiding contemporary macroeconomic policy decisions and debates. Not open to students who have taken Economics 351.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><br/> </p> <p><strong>Open Economy Macroeconomics</strong></p> <p>The course provides an overview of models, methods, research, and current issues in Open Economy Macroeconomics. Today, an international perspective to study Macroeconomics is perhaps more important than ever before. Countries do not operate in isolation, but events in one country affect people around the world. Why do some countries grow faster than others? What are the effects of monetary and fiscal policy, domestically and abroad? Why do some countries run trade deficits and others trade surpluses? Does it matter? And why do some countries encounter financial crises and what can we do about them? In trying to answer these questions, the first part of the semester will be devoted to asset-based models of exchange rates and price level determination, and the second to open economy models of the short and medium run.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong><strong>Health Economics</strong></strong></p> <p>This seminar provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries.</p> <p>Prerequisite: ECON 250 and ECON 272 (may be taken concurrently).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7877,2021,143,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/econ-economics/400/econ-498','<div class="desc"> <p>Independent research with one-on-one faculty mentoring. After a brief introduction to economic research methods, students will develop a topic and then write and present a senior thesis. Only open to seniors. Permission of instructor and department chair required.</p> </div>','ECON 250, ECON 251, and ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7878,2021,1218,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/100/educ-101','<div class="desc"> <p>In every major urban center across the United States, children and youth attend public schools managed by highly-bureaucratized administrative entities called ''school districts''. This course provides a historical survey of the evolution of U.S. urban schooling, tracing its development from the earliest community-based, one-room schoolhouses, to modern major urban unified school districts. We explore the roles that industrialization and immigration have played in the urbanization of communities, and the ways in which schools have adapted in order to provide for the socialization of the urban worker. We examine shifts in the politics of public education as it pertains to control over schools and schooling and the various stakeholders involved. We conclude with a look at the evolving roles of the teacher, school counselor, and the administrator - as well as a glimpse into what the future holds for both traditional and alternative forms of public schooling in urban school communities across the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7879,2021,145,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/100/educ-140','<div class="desc"> <p>Occidental students work in the Academic Commons one-on-one with children from the community. While incorporating arts and integrating technology, students will engage their child with a variety of Language Arts activities in order to reconnect their child with the joy of reading and writing for pleasure. Students will build on their child''s strengths, skills, and interests by using culturally relevant pedagogy and critical literacy explorations. Students become part of a high-warmth, low-criticism community. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7880,2021,835,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/100/educ-141','<div class="desc"> <p>Students work one-one with middle school students for extensive explorations in writing. Occidental students will collaborate and coach writing activities which will include narrative, expository, and analytical prompts. This course focuses on authentic, engaging writing and integrates the arts, technology, and critical literacy. Students work closely with the Critical Making Studio. This course is designed to deepen the critical and creative abilities of both groups of students while connecting written explorations to the California Common Core Standards. This course takes place on campus in the Academic Commons. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7881,2021,2511,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/100/educ-142','<div class="desc"> <p>In this course, Occidental students who are Spanish speakers will support students and teachers in Dual Language Programs in the local schools. Support will consist of Spanish language development and language enrichment activities that will create an engaging and critically conceptual environment for elementary and middle school students. <strong>Occidental students will meet with the professor several times throughout the semester and will work with elementary and middle school students in their classroom two hours a week during the school day</strong>. Transportation to the schools will be provided for those who need it. Graded on a Credit/No Credit basis. May be repeated for credit. For further information, email the professor.</p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7882,2021,1014,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/100/educ-145','<div class="desc"> <p>In this course, students will systematically examine the causes, challenges, and effects of several innovations in schools, such as: charter schools, magnet schools, dual-immersion/bilingual programs, high-tech high schools, and online high school programs. The course will help students develop a historical perspective of the schooling system and to understand how current and future innovations can impact educational processes. As part of the course, the students will have an opportunity to interact with invited speakers (CEOs from charter schools, school district superintendents, and board members, as well as administrators who are Oxy graduates). Students will read research-based studies and articles focusing on the different educational innovations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7884,2021,146,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-201','<div class="desc"> <p>In this introductory course, students study, as a community of learners, the historical, philosophical, political, sociological, economic, and psychological foundations of U.S. education in the public school. Using a variety of analytical lenses, students will critically engage with key texts to examine factors that influence power, control, and the quality of schooling for urban communities. Throughout the semester, we will focus our analysis on the possibility and potential of achieving "socially-just" relationships in urban school communities through teacher practice, educational leadership, and community-based activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7885,2021,147,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-205','<div class="desc"> <p>Analysis of the English language development of listening, speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction, sheltered/SDAIE approaches, English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7886,2021,148,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-207','<div class="desc"> <p>How are the American values of equity and opportunity evident in the history and structure of the nation''s public school system? This course examines key U.S. Supreme Court decisions and the following areas of policy debate and conflict, with particular emphasis on the Constitution: bilingual education funding/expenditures, immigrant education, desegregation, special education, affirmative action, and equal resources.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7887,2021,925,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States: Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students, and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7888,2021,149,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-215','<div class="desc"> <p>This course critically examines the history of the education of Africans in the United States, beginning at the Middle Passage, through Reconstruction and the post-bellum South, to contemporary post-industrial urban contexts. Emphasizing the sociohistorical and political-economic dimensions of schooling African Americans, the course explores the role of key factors in shaping the academic "success" and "failure" of Black students historically and in current K-16 contexts. Analysis of case law policy and practice will inform our understanding of African American experiences in schools nationally and locally. Further, we consider the implications these experiences hold for democratic participation and the overall life chances of African American citizens.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7889,2021,1378,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-217','<div class="desc"> <p>National reform efforts (e.g. Nation at Risk, No Child Left Behind, Race to the Top) have permeated the educational establishment for decades, yet the achievement gap between rich and poor and white and non-white students has shown no appreciable progress. This course will analyze current and past policies in education intended to improve the educational experience of all students and address this achievement gap. Students will receive an understanding of policy formation, the effect of applied research relative to educational policy, and then select a reform policy (e.g. value-added teacher pay, class size, charter schools, etc.) to further investigate as a project field assignment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7890,2021,1015,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-219','<div class="desc"> <p>This course will analyze the educational infrastructure PK-16 pipeline to examine the nature of inequality. The following three areas will be examined: (1) theories of educational inequality, (2) research on inequality, and (3) policies of inequality. Students will gain a basic understanding of the theories of educational inequality as they relate to genetic, cultural, school, and societal perspectives, using critical theoretical lenses. Students will also examine the research addressing educational inequality, paying attention to designs, methods, and samples covered. And finally, students will analyze educational policies that either reproduce or eliminate inequalities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7891,2021,2741,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-220','<div class="desc"> <p>The United States has the highest incarceration rate in the world. Schools, despite their role in nurturing the academic growth and development of students, are increasingly becoming sites of criminalization for marginalized children and youth. This raises fundamental questions about the relationship between schools and the carceral state, as well as about the complicity of schools and their officials in the production of prisoners. In this course, students will explore the social, historical and political-economic factors that have contributed to the development, growth and sustenance of the "school-to-prison pipeline." Through an examination of a wide range of texts and sources that sit at the intersection of K-12 schooling, criminal justice, social welfare, and community-based organizing and activism, students will be prepared to critically interrogate educational policies, practices and other structures of schooling that buttress and deconstruct this phenomenon. Sophomore standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7892,2021,1449,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/200/educ-281','<div class="desc"> <p>This class provides students with the ability to develop a conceptual and practical understanding of research and evaluation in Education and the Social Sciences. Course topics include: basic statistics, survey design, data analysis, article critique, and data interpretation. The course will allow students to demonstrate a proficient knowledge of basic statistics (ranging from basic descriptive statistics to inferential statistics), research design, and analysis. Students will advance from being consumers of knowledge to being critical when reading previous literature. Students will be introduced to the following concepts: descriptive statistics (including cross-tabulation); correlation, reliability, and validity; one and two sample statistical tests; ANOVAs; and simple and multiple regression.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7895,2021,150,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/300/educ-300','<div class="desc"> <p>This seminar will provide students with an opportunity to gain field experiences in an educational setting in urban Los Angeles. Students will select either a public school, a community-based organization, or a policy-making group as a site in which to develop a field-based research project. Regular meetings of this seminar will guide students as they spend the semester in a carefully crafted and mutually agreed upon "internship/fieldwork" experience that will culminate in a semester-end project report that addresses an educational issue of import to the fieldwork site. May be repeated for credit.</p> </div>','EDUC 201 and EDUC 207; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7896,2021,151,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/300/educ-314','<div class="desc"> <p>Principles and techniques for creating teacher-student-text interactions, vocabulary development, and comprehension and study skills in all school subjects for all students (including English language learners) at the junior high and senior high levels. Topics include: diagnostic procedures; activating background schemata; English language development; different instructional models; and constructivist-based instructional materials, skills, development, standards-based and high-stakes assessment, reading for English language learners/speakers, and procedures for improving students'' reading habits and interests.</p> </div>','EDUC 201 and EDUC 205 (may be taken concurrently); or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7898,2021,566,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/300/educ-320','<div class="desc"> <p>Critical Race Theory (CRT) is a historic movement among legal scholars of color in the U.S. that has enjoyed widespread application in a number of disciplines, including Education. This course introduces students to CRT through a close reading of the key writings that formed the movement. We will examine the application of CRT in education, research, theory, and practice, contextualized in a variety of settings, including schools, community-based organizations, and other relevant spaces. Specific attention will be paid to the CRT methodology of counter-storytelling and its utility in centering the experiential knowledge of people of color in education.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7899,2021,1168,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/300/educ-350','<div class="desc"> <p>"How can the oppressed as divided unauthentic beings participate in developing the pedagogy of their liberation?" This course focuses on Freire''s theoretical, pedagogical, and practical contributions to contemporary movements in critical pedagogy, critical literacy, and educating for "social justice". Beginning with Franz Fanon''s influences on Freirean thinking about revolution and decolonization, we will analyze the construction of the "Pedagogy of the Oppressed". We pay particular attention to the role of the Hegelian dialectic as a driving philosophical method, as well as the significance of Freirean themes in understanding contemporary schooling, education, community activism, and vocation in general. Students will analyze, critique, and reflect upon their own framing philosophies for personal engagement with oppressed peoples and communities - towards the broader goal of defining an individual role in the development of a pedagogy of the oppressed that both negotiates and is informed by students'' multiple identities.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7901,2021,568,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/educ-education/300/educ-397','<div class="desc"> <p>Interested students must obtain <em>Guidelines for Independent Study</em> from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7904,2021,2742,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-140','<div class="desc"> <p>This class will examine the literature and culture of the Victorian period, from the 1830s to the turn of the twentieth century. We will read classic Victorian novels such as<em> Silas Marner</em>, <em>Great Expectations</em>, and <em>Jane Eyre</em> alongside more contemporary literary and cinematic interlocutors including <em>Wide Sargasso Sea</em>, <em>Thugs of Hindostan</em>, and <em>Victoria and Abdul</em>. In thinking about the period’s lasting impact on our own society, we will consider the broader historical context of imperialism, urbanization, and industrialization, all of which expanded dramatically during the Victorian era. We will also examine the shifting social and legal structures of the era, addressing issues of class, sexuality, and race.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7905,2021,1698,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7906,2021,1517,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-155','<div class="desc"> <p>The pandemic of 2020 has revealed the surprising number and diversity of fantasies, fears, and anxieties surrounding the notion of science. While some of these reactions are relatively new (particularly those grounded in historically specific conspiracy theories), most emerged over the course of several centuries. Literary works, particularly novels, often explore these fears and anxieties in far greater detail than may be found in the direct attacks on or defenses of science. Texts like Mary Shelley''s <em>Frankenstein</em> or Bram Stoker''s <em>Dracula</em> both draw on scientific theories and articulate fears of the possible consequences of these theories that still resonate with readers today. We will read literary texts to determine what exactly those who reject science fear, and what is at stake in their rejection of science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7907,2021,2336,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-159','<div class="desc"> <p>A study of the popular American "Western" in various forms (fiction, film, television) in the first half of the 20th century. We will pay particular attention to the genre''s elaborate, sometimes ambivalent, presentation of ideas of "manliness," and to the historical and social contexts in which that presentation developed. We will also spend some time discussing associated issues of race and power. Toward the end of the class, we will examine a few of the Western''s transformations in the late 20th and 21st centuries.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7908,2021,2986,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-165','<div class="desc"> <p>This class will read examples of queer Anglophone fiction across a broad range of historical periods and geographical regions. Beginning with Kate Chopin’s <em>The Awakening</em>, through Nella Larsen’s <em>Passing</em>, Djuna Barnes’s <em>Nightwood</em>, and E.M. Forster’s <em>Maurice</em>, we will explore the intersection between sexuality and other social structures such as race and class. We will build on this intersectional foundation to examine the legacies of colonialism, gender-policing, and marital normativity in contemporary global queer novels such as Shani Mootoo’s <em>Cereus Blooms at Night</em>, Akwaeke Emezi’s<em> Pet</em>, Chinelo Okparanta’s <em>Under the Udala Tree</em>, and Shyam Selvadurai’s <em>Funny Boy</em>. Over the course of the semester we will supplement our readings of novels with various theoretical texts that address the social and political contours of queer literature and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7909,2021,1657,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-178','<div class="desc"> <p>This class introduces you to some of Shakespeare’s most challenging and rewarding plays, with a focus on both their historical moment and film adaptations that have reanimated them across the second half of the 20th and 21st centuries. Our main topic will be Shakespeare’s evolving exploration of the predicament of tragedy in an era of major social, religious, and political transformation for Europe (England especially), and the ways that filmmakers have adapted Shakespearean tragedy for the big screen in different times and places. We will study Shakespeare''s explorations of dramatic form, poetic style, characterization, and ideology, and examine how the choices made in filming Shakespeare allow us to think in new ways about the plays themselves, and about the historical context in which the films were made. This course will introduce you to foundational concepts in literary studies and film studies, help you learn how to engage with Shakespeare''s plays more deeply, and enable you to analyze how film adaptations bring to life or transform the complex, unruly energies that characterize Shakespearean tragedy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7910,2021,1220,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/100/engl-189','<div class="desc"> <p>A historical survey of the major literary genres from the colonial to the contemporary period emphasizing the persistent thematics of the American experience from a cross-cultural perspective. This class is particularly suited for students interested in the ways in which well-known American authors are in conversation with African Americans, Native Americans, Asian Americans, Latinos/as, and white women, who, until recently, had been left out of the literary canon. Open only to first year students. ENGL 189 satisfies an equivalent requirement to ENGL 289 within the English major. Students may not receive credit for both ENGL 189 and ENGL 289.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7912,2021,2882,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-220','<div class="desc"> <p>In this course we will study the relationship between literature and science during the Scientific Revolution of the seventeenth-century in England. Though today we usually consider science and literature to inhabit different spheres, in the era when “modern science” began there was no clear division between the two. We’ll explore the shared questions about the earth, human nature, the cosmos, and the divine that motivated new conceptions of scientific experiment and innovations in literary writing. We''ll also examine how the institutionalization of experimental science, especially with the founding of the Royal Society, transformed English literature as well as England''s orientation to Continental Europe and the "New World." Readings will be drawn from the work of scientists, fiction-writers, essayists, and poets, including William Shakespeare, Francis Bacon, Galileo Galilei, René Descartes, John Donne, Ben Jonson, Thomas Browne, Blaise Pascal, Robert Boyle, Anne Conway, Robert Hooke, Margaret Cavendish, John Milton, Thomas Hobbes, Lucy Hutchinson, and Isaac Newton.</p> <p><strong>Major Requirement Met:</strong> Group I</p> </div>','Fall semester CSP seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7913,2021,1592,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-241','<div class="desc"> <p>This course looks at representations of "deviance" in 19th- and early 20th-century literature. Underlying our examination will be an investigation of what constitutes the "normal" and the ways in which normativity polices its boundaries. Focusing primarily on literary and filmic representations of the sexual, racial, legal, and economic "taboo," in works including Charles Dickens''<em> Great Expectations,</em> E.M. Forester''s <em>Passage to India, </em>and Djuna Barnes'' <em>Nightwood</em>, we will seek to uncover the terms of normativity, against which the figure of the deviant emerges into representation. We will supplement our analysis of literature with readings from a range of theoretical methodologies, from psychoanalysis, legal theory, Marxist/economic theory, to postcolonial and critical race studies. </p> <p><strong><strong>Major Requirement Met:</strong> </strong>Group II/IV</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7914,2021,2337,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-248','<div class="desc"> <p>The course will bring together 19th century texts on political economy, such as those by Karl Marx and John Stuart Mill, and novels of 19th-century England and America, such as Edith Wharton''s <em>House of Mirth</em>, Elizabeth Gaskell''s <em>North and South</em>, and Charles Dickens''s <em>Little Dorrit</em>. This interdisciplinary perspective will enable us to think through the shifts in values, ethics, and material conditions that accompanied changes such as the Industrial Revolution and the spread of the British Empire in the 19th century. A focus on gender will enable us to track how economic changes affected the positions and work lives of women and men differently. An interdisciplinary perspective (Economics and Literature) will enable us to ground changes in characters'' values and perceptions in historical perspective and to take note of the way that market practices and values infiltrate the language of the novels.</p> </div>','A CSP Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7915,2021,1699,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-273','<div class="desc"> <p>American poetry has resurged in cultural and political significance in the 21st century. Poets have reframed the nation''s controversies and recovered its forgotten histories. Notably, poets have shifted American consciousness without losing sight of artistic experimentation. Poetic genres, in this course, are more than familiar literary conventions. They are ways of thinking and feeling. Poets experiment with literary form in hopes of staying true to the nation''s complexities. Fragmentation, intertextuality, ekphrasis, and erasure are all crucial techniques for exploring beauty, mental health and disability, immigration and war. This course will examine several award winning poets, including Kevin Young, Molly McCully Brown, Robin Coste Lewis, Solmaz Sharif, and Philip Metres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7916,2021,1700,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-274','<div class="desc"> <p>We will study novels by Anglo American, African American, and Native American women writers of the 19th and 20th centuries. Among the authors we will read are George Eliot, Kate Chopin, and Virginia Woolf; Harriet Jacobs, Nella Larsen, Zora Neale Hurston, and Alice Walker; Louise Erdrich and Leslie Marmon Silko. In addition to doing close readings of the novels, we will strive to understand the historical context and the cultural values in which the works are embedded, and to which they respond.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7917,2021,1593,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-280','<div class="desc"> <p>The focus of this course is writing, and developing a relationship with, short fiction, with the aim of making it a fluid manifestation of the way we process and transform memory and experience. We will play into and take seriously Toni Morrison’s conception of memory as <em>a form of willed creation</em>, in an ongoing attempt to reanimate forgotten or unrealized aspects of our histories and ourselves. Students will generate new work constantly—in sketchbooks, exercises, and story drafts—paying attention to the honing of various craft elements (description, dialogue, character and plot development), and in correspondence with texts by a variety of exemplary practitioners of fiction and prose writing (Venita Blackburn, K-Ming Chang, Fleur Jaeggy, Jamaica Kincaid, Maxine Hong Kingston, Li-Young Lee, Clarice Lispector, Scholastique Mukasonga, Nhã Thuyên, among others). Students will share and discuss their work in a workshop format, the orientation of which will be based, in part, on each student’s specific intentions.The discussions will be supportive, inquisitive, and constructive, and will be oriented towards helping to introduce each other—and ourselves—to what is most compelling and imperative about what we are doing, what it is that we want to be doing, and how we might get there. Open to first and second year students.</p> </div>','A CSP seminar, WRD 201, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7918,2021,1518,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-281','<div class="desc"> <p>This course introduces students to the fundamentals of poetry writing. Students will learn how to craft and revise poems, and will workshop their poetry in class with their peers. Outside readings will also be required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7919,2021,1221,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-287','<div class="desc"> <p>We might think that older literature by the likes of Chaucer, Shakespeare, and Milton is dustily conventional, a cultural tradition that we''re obliged to read (or compelled to disavow) but that has little relevance to our lives today. The goal of this class will be to persuade you, to the contrary, that the literature written during the period beginning with Chaucer''s Canterbury Tales in the late 14th century and ending with Milton''s Paradise Lost in the 17th century constitutes one of the most exciting and experimental moments in literary history, one that offers uniquely relevant lessons for contemporary thinking about community and storytelling, narrative and memory, truth and perception, race and power, as well as gender and sexuality. At the same time, we will explore what is productively strange, challenging, and even alienating about these texts from the past, measuring how their distance from us provides unique opportunities for thinking. We will also examine how authors such as Chaucer, Shakespeare, Spenser, and Milton came to constitute the foundation of the English literary canon, and how this canon has been used to advance (or to critique) English national and colonial ideologies. Together we’ll explore a set of analytic concepts and strategies for interpreting their unique texts that will make you a more sensitive, precise, and persuasive reader and writer.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7920,2021,1222,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-288','<div class="desc"> <p>Monsters and Monstrosity: literature is rife with portraits of monsters and monstrosity. From Homer''s <em>The Odyssey</em> and Grimm''s fairytales, to Mary Shelley''s <em>Frankenstein </em>and Salman Rushdie''s <em>Shame, </em>monsters challenge our everyday ideas about normality. Situated between the animal and the human, monstrous creatures are ciphers for difference that force us to consider what we regard as culturally abject or grotesque, as well as alluring. That these mythical figures continue to fascinate even as they frighten, is suggestive of their symbolic power in embodying both our latent desires and prohibitions. This course will explore the emergence of the monstrous aesthetic across several genres (epic, drama, novel, poetry, film) and periods (Renaissance to contemporary) to probe the shifting terrains of sexual, racial, and cultural otherness that monsters represent. Along the way, we will ask critical questions that arise from the study of monstrosity. What, for instance, separates monsters from humans? How does monstrosity define our notions about beauty and ugliness, desire and disgust? Does the monster appear each time under a different guise? If so, to what extent does it reshape our sensibility about what is socially abnormal? What can monsters teach us about the hopes and apprehensions of the cultures and times to which they belong? Ultimately, we will seek to understand how and why these ferocious figures also elicit sympathy in us toward those markedly unlike ourselves. Our reading list includes works by: Alfred Tennyson, William Blake, R.L. Stevenson, Mary Shelley, Patricia Highsmith, among others.</p> </div>','A CSP seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7921,2021,1223,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-289','<div class="desc"> <p>This survey grapples with the centrality of war to American literature--indeed, to American life. The course moves chronologically through Early American and the American Revolutionary Wars and ends with the War on Terror. We will examine the strengths and limits of depicting war through lyric poetry, short epic poetry, political pamphleteering, oratory, autobiography, and the novel. In addition to considering literary forms, this course considers what understudied voices have to say about what leads to war, the experience of war, and its aftermath. Our readings will include Phillis Wheatley, Timothy Dwight, Philip Freneau, Walt Whitman, Ernest Hemingway, Zora Neale Hurston, Philip Metres, and Solmaz Sharif, among others. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7922,2021,1224,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-290','<div class="desc"> <p>This course will introduce students to contemporary critical methodologies in literary studies. Students will engage a wide range of critical approaches to help ground their subsequent study of literature across the English department curriculum. By studying influential works of theory and criticism, students will become familiar with the historical genesis of literary studies, with special attention to the political, social, and other institutional factors informing the rise of particular methodologies in the academe. We will trace these critical genealogies so as to recognize and participate in the fullness of literary studies.</p> </div>','A CSP seminar, WRD 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7923,2021,2949,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/200/engl-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7925,2021,1379,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-310','<div class="desc"> <p>Examining death in the imaginative and meditative culture of the 14th and early 15th centuries, this seminar will introduce advanced students to a wide range of Middle English literature. No prior knowledge of Middle English or medieval literature required. We will contextualize our work by looking at religious, philosophical, and medical texts about death, yet our focus will be on scenes of death, burial, mourning, and memorial in literary texts by Chaucer, the Pearl Poet, Julian of Norwich, and others. Asking how we can construe the ethical and political imagination of the medieval English literary world, we will also consider larger issues related to the literary awareness of death: the representability of death; the political and generic function of consolation, tragedy, and elegy; death''s relations to the sacred and the sovereign; the economics of death in the age of the plague; war and martyrdom; mourning and rebellion; dreams and the afterlife; gender, living, death, and anchoritism.</p> <p><strong>Major Requirement Met</strong>: Group I</p> </div>','Any 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7926,2021,1519,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-311','<div class="desc"> <p>Akin to the novel in modernity, romance was one of the most important genres of imaginative literature in medieval and early modern England (and Europe, more generally), and yet it was also the one that provoked the most profound moral and aesthetic concern. Hugely popular, romance was often condemned for its endless attention to pleasure, pain, and error, for its perverse magical stories of quest and exploration, for its unseemly analysis of chivalric duty and obsession - and even for its capacity to corrupt its readers beyond repair. Whether viewed as a genre of utopian dreaming or of lurid and dangerous narrative failure, romance is a vexed concept. By examining pre-modern and modern genre theory, this class will explore the formation of the category of romance across medieval and Renaissance England (with some attention paid to France, Italy, and Spain), thus giving students an opportunity to consider how genre can enable and constrain understanding of particular works of literature. We will focus the majority of our attention on two of the most anomalous expressions of the genre: Geoffrey Chaucer''s <em>Troilus and Crisyede</em> and several books of Edmund Spenser''s <em>The Faerie Queene</em>. These poems relentlessly reflect on their own status as romances; their examinations of story-telling and power, gender and sexuality, spectacle and violence are acute. At the end of the semester, we may turn to more recent speculative fictions (such as Samuel R. Delany''s <em>Nova</em>) to get a sense of how pre-modern romance remains an archive for some of the most exciting cultural production today.</p> <p><strong>Major Requirement Met</strong>: Group I</p> </div>','Any 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7927,2021,2829,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-314','<div class="desc"> <p>This course examines the poetry and poetics of the English Renaissance, emphasizing the relationship between formal developments in poetic techniques and questions of religious belief, gender, labor, race, education, and politics. Readings include classical and humanist poetic and rhetorical theory (from Plato to Puttenham) and a wide range of poets, including Thomas Wyatt, Anne Locke, Philip Sidney, Edmund Spenser, William Shakespeare, John Donne, John Milton, Andrew Marvell, Mary Wroth, and Katherine Philips, as well as some consideration of the influence Renaissance verse has had on modern poets (such as T.S. Eliot, Frank O''Hara, and Marilyn Nelson).</p> <p><strong>Major Requirement Met: </strong>Group I</p> </div>','One 200-level English class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7930,2021,1594,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-322','<div class="desc"> <p>The Renaissance and Reformation in England witnessed the rise of imperial projects and the emergence of more centralized institutions to police sin and illegality in society; both were intended to enhance the sovereignty of the British state. This class explores the literary responses to such shifts in the culture of punishment and the project of state-building, asking why some of the most innovative works of drama, poetry, and prose in this period struggle with the purpose and effects of imprisonment, trial, penance, and slavery. Four main topics will organize the course: punishment and colonialism; the economic, theological, rhetorical, and theatrical underpinnings of legal trial; martyrdom; and the rise of the transatlantic slave trade. Each section of the course is divided into a series of sub-topics (ranging from questions of genre and psychology, to the humanist culture of teaching) to be explored through examination of a literary text and related historical and theoretical materials. Authors will include: John Foxe, Elizabeth I, Edmund Spenser, Michel de Montaigne, William Shakespeare, John Milton, Thomas Hobbes, John Locke, and Aphra Behn, among others.</p> <p><strong>Major Requirement Met</strong>: Group I</p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7931,2021,2591,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-330','<div class="desc"> <p>A survey of poetry, prose, and drama from 1660-1730. Authors to be studied include Aphra Behn, Lady Mary Wortley Montagu, Daniel Defoe, and Jonathan Swift.</p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>','Any 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7932,2021,1451,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-332','<div class="desc"> <p>The class will examine British literature from the novels of Richardson, Fielding, and Sterne to the poetry of Blake, Wordsworth, and Coleridge.</p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>','Any 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7933,2021,1226,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-341','<div class="desc"> <p>This course interrogates the crucial role of the law in British imperial governance by reading colonial legislation and court proceedings alongside works of 19th and early 20th century literature. Doing this allows us to examine how dominant legal paradigms were disseminated in the era''s cultural production and, in turn, how cultural ideals reflected in literature were materially implemented through the law. In addition, we will look at how literature often provided a viable means of contesting the normative terms of the law. </p> <p><strong>Major Requirement Met</strong>: Group II or Group IV</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7934,2021,1520,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-345','<div class="desc"> <p>The subject of this course varies year to year. <strong>Major Requirement Met</strong>: Group II</p> <p><strong>Dickinson and Her Circle</strong></p> <p>Emily Dickinson is one of the most distinctive, original, and provocative poets ever produced by the United States. Her short lyrics present the reader with challenges of concept and comprehension rarely matched. This course will attempt to meet these challenges with extremely focused readings of a fairly small number of her poems placed within the context of those other American authors who were her creative companions. In addition to this central endeavor, the class will address those philosophical and linguistic issues that are explicit or implicit in her literary performances.</p> <p><strong>The American Renaissance</strong></p> <p>The tumultuous pre-Civil War period from 1850 to 1855 saw the creation of a number of works that were and are thought by many to be among the most brilliant, important, and influential for American and global culture. Such an assessment, while it must be, itself, constantly weighed and re-evaluated in regard to broader historical developments and criteria, suggests the desirability of critically encountering these works in the attempt to understand the complex evolution of our national self-image. This class will study both the radical shifts in literary practice engendered at the time, and the intersection of these presentational innovations, with a growing emphasis on issues of race, class, sexual orientation, environmentalism, and the concept of the self. In addition to the authors traditionally associated with this period - Emerson, Hawthorne, Melville, Thoreau, and Whitman - this class will consider a slight precursor, Edgar Allan Poe, and a trailing figure, Emily Dickinson.</p> <p><strong>The Literature of Non-Representation</strong></p> <p>The Literature of Non-Representation: In the Greek and Judeo-Christian traditions literature is usually understood as an untrue copy of the "real." As such it has often been devalued as morally suspect and materially empty. However this perspective was itself inverted by some American literature of the 18th and 19th centuries. In this contrarian view literature is the activity of realization itself and the literal and scientific modalities are fictions lost in their habitual misunderstandings. For these opposing writers the poetic process constitutes the reader''s dissolving emersion in the real without need of conceptual replica. This class will try to understand this non-representational view with primary concentration on the poems of Whitman and Dickinson bracketed by the previous practices of Bradstreet Wheatley Emerson and Poe.</p> </div>','Successful completion of one 100-level or 200-level English course or junior or senior standing is required for these courses. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7935,2021,1452,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-346','<div class="desc"> <p>This course thinks through current debates over the relationship between literary aesthetics and harmony in American democracy. Do aesthetics foster a more harmonious or disharmonious national culture? Is disharmony ever important to progress? How does literature represent protests for social change that are often only possible outside the law, like the many freedmen and freedwomen escaping slavery and demanding the destruction of that system? How does this alter our understandings of what it means to be a fugitive? How can the fugitive fighting for freedom be distinguished from the unprincipled outlaw? From another perspective, we will consider how the complications of American society have altered certain traditional literary forms. While recent scholarship has addressed these questions in regards to early- to mid-20th century literature, this course will look back further, starting from the early 19th century to the very beginning of the 20th. We will complement the literature by reading relevant historical materials from the abolitionist movement, labor movements, government debates over Emancipation and Reconstruction, etc. The course will include literature from Frederick Douglass, Sojourner Truth, Walt Whitman, Ida B Wells, and Charles Chesnutt, amongst others, and will cover several genres, including: oratory, autobiography, political pamphlets, and short fiction.</p> <p><strong>Major Requirement Met</strong>: Group II</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7936,2021,1595,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-347','<div class="desc"> <p>This course will examine 19th century British and Indian novels in dialogue with their 20th century Bollywood adaptations. A product of the largest film industry in the world, Indian cinema is consumed globally. Questions of globalism were also central to 19th century novels that were written during the height of colonial rule. We will examine the films and novels, paying particular attention to representations of cultural subject formation, gender and racial norms, and nationalist sentiment in the era of empire and the postcolonial moment. </p> <p><strong>Major Requirement Met</strong>: Group II or Group IV</p> </div>','Any 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7937,2021,1453,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-351','<div class="desc"> <p>In this class we will examine fiction by British modernist writers such as Joseph Conrad, James Joyce, Virginia Woolf, Katherine Mansfield, D. H. Lawrence, and E. M. Forster. We will read their work critically, with attention to the ways in which it approached and reflected (or obscured) its historical context: changing gender roles, a fragile and distended empire, global reassessments of power, class, and race. We will also explore some representative later responses in British fiction to these central concerns of modernism.</p> <p><strong>Major Requirement Met</strong>: Group III</p> </div>','A CSP seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7938,2021,2338,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-353','<div class="desc"> <p>Frequently, United States politicians, including President Obama, say that the Great Depression of the 1930''s is the only economic crisis that surpasses the world''s current economic travails. This frequent comparison does not exhaust the significance of the Great Depression for the U.S. or around the world. What makes the 1930''s so intriguing is that, all over the world, the economic collapse spawned new, or renewed older, political and artistic movements. Most importantly, in the global 1930''s, thinkers and artists all over the world not only rethought their political identities, they also pondered the very meaning of the political for the past, present, and the future, and felt that art and philosophy were central to their investigations. This is important for Humanities scholarship because even if we are currently exiting the "Second Great Depression" in terms of economic productivity, the question remains: what cultural rebuilding remains to be done and how does art contribute to such processes? Writers of the 1930''s took up this question in several different forms: through the trope of the document and its archival drive, the unconscious and the search for the Marvelous, the raised fist of labor movements or antiÂ­racist activism. Simply put, what can the First Great Depression of the 1930''s teach us about cultural reconstruction in the Second Great Depression of the early 2000''s? This course will look at several literary (and related art) movements in, and cutting across, America, the Caribbean, and Europe. Texts will include (but are not limited to) literature from Richard Wright, Langston Hughes, and Muriel Rukeyser; from Surrealist writers in Europe and the Caribbean like Andre Breton, Aime and Suzanne Cesaire; and political readings from figures like Antonia Gramsci. Although this is a literary course, it will also be informative to students in Art, History, Philosophy and Politics.</p> <p><strong>Major Requirement Met</strong>: Group III</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7939,2021,1380,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-365','<div class="desc"> <p>Topics may vary semester to semester.</p> <p><strong>The Global Novel</strong></p> <p>This course will focus on literature and theory produced in the aftermath of the British Empire. By 1914 the British Empire had colonized almost 25% of the world, bringing diverse cultural traditions under the encyclopedic gaze of Western modernity. If part of the aim of the colonial apparatus was to collect knowledge of the world in ways that bodies, cultures, and landscapes could be understood and ordered by the West, contemporary societies are now negotiating their own means of self-representation in the often violent space of postcolonial rupture. Throughout the term, we will work with texts and visual images produced out of, and in response to, the history of the colonial encounter. Drawing on a broad range of literary, filmic, and theoretical materials we will develop strategies for understanding the production and consumption of postcolonial representation, in both local and global contexts. As consumers of these cultural products within the space of the Western academy, we will be attentive to the function of the stereotype as we consider representations of gender and sexuality, violence and terrorism, class structures, and migration. Major requirement met: Group III.</p> <p><strong>Violence and Representation</strong></p> <p>This course will interrogate Fanon''s assertions that the colonized find their freedom only through violence, and that decolonization is always a violent process, by considering the structuring dialectics between violence, the body, and postcolonial narratives of insurgency. If, for Fanon, decolonization is both literally and linguistically an adopted violence, so that militancy against colonialism is an answer back in the imported language of destruction that the colonizer best understands, our goal will be to investigate the complex and shifting relations to violence/violation that postcolonial texts elaborate when they represent insurgent anticolonial practices. By looking closely at how postcolonial narratives represent insurgencies against power and their attendant violence, we will arrive at an analytic for addressing the technologies of pain, trauma, brutality, torture, and repression that conditioned regimes of colonial discipline and control. We will also consider the extent to which postcolonial texts appropriate an apparatus of violence in representing bodies in rebellion, while also articulating alternative visions of resistance and social change that specifically refuse the ethics of extremism. Our inquiry will draw from a critical discourse on corporeality (Foucault, Scarry), the nation (Fanon, Anderson), and gender (Butler, Spivak) to illuminate the peculiar charge in narratives of insurgency between the embodied politics of militancy and the body politic. Finally, the texts that we will be reading, deal, in some way, with the problematic of form (how to represent the urgency of politicized violence as a condition of modernity), and, in so doing, reach beyond realist conventions to reflect aspects of the surreal, the grotesque, the spectacular, and the magically real. We will assess the efficacy of these forms and their overwrought symbolism in managing the economy between the public and the private victims and perpetrators, masculinity and femininity, and whites and blacks, which structured the play of colonial violence itself. Over the course of the term, we will be reading writers as diverse as Roy, Coetzee, Al-Shaykh, Djebar, Salih, and viewing films such as <em>The Terrorist, Bandit Queen, and The Battle of Algiers</em>. Major requirement met: Group III or Group IV.</p> </div>','Any 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7940,2021,1229,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-370','<div class="desc"> <p>After a short introduction to Aristotle, this course will present the works of Marx, Freud, and Saussure as the basis for later 20th century theory. We will then explore the structuralist and post-structuralist movements. This class is recommended to those contemplating graduate study in the Humanities, and it is required for students pursuing Honors in English.</p> </div>','Any 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7941,2021,1596,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-372','<div class="desc"> <p><strong>Faulkner, Hemingway, and Morrison</strong></p> <p>Discussion of the major novels of William Faulkner, Ernest Hemingway, and Toni Morrison, with an emphasis on race and gender in American culture. Major requirement met: Group III.</p> </div>','Any 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7942,2021,1455,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-377','<div class="desc"> <p>Topics vary.</p> <p><strong>On Afrofuturism</strong></p> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. Major requirement met: Group III or Group IV. Cross-listed as Black Studies 377.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7943,2021,1381,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-380','<div class="desc"> <p>Our primary focus will be on fiction. Students will be required to respond thoughtfully and critically to assigned readings and to one another''s work. We will attend to general issues of craft, as well as to broader questions about the writing of fiction. Open only to juniors and seniors. May be repeated for credit.</p> </div>','ENGL 280 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7944,2021,1230,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-382','<div class="desc"> <p>The focus of this course is the writing of short fiction, though also where fiction might overlap with—and necessitate elements of—nonfiction, documentary, poetry. Students will build upon the foundations they established in prior writing workshops, while continuing to test the boundaries of their practice. Students will generate new work constantly— in sketchbooks, exercises, and story drafts—based on and inspired by readings, and especially their own preoccupations, curiosities, and experiences. We will read and discuss texts that both illuminate and complicate various formal possibilities, including by Etel Adnan, Jenny Boully, John Keene, Malika Mokeddem, Scholastique Mukasonga, Juan Rulfo, Sophia Terazawa, Jackie Wang, among others. And we will share and discuss our work in a workshop format. The discussions will be oriented towards asking questions, problem-solving, developing a generative relationship to revision, and towards challenging each other to go deeper into particular, perhaps unexpected, areas and aspects of our writing. Open to third- and fourth-year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7945,2021,1231,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-390','<div class="desc"> <p>The Junior Seminar is a small, discussion-oriented seminar required of all English majors, emphasizing advanced critical approaches to a literary topic. Enrollment is restricted to English majors who will pass the college''s Second-Stage Writing Requirement by satisfactory completion of the course writing requirements. Topics may vary year to year.</p> <p><strong>The Animal</strong></p> <p>This seminar will examine literary, filmic, and theoretical representations of the animal. Questions about the human as animal, and at the limit of animality, will be implicit in our discussion. Over the course of the semester, we will evaluate how the animal has been theorized and represented from the nineteenth century to the present. We will also consider the ways in which the animal has served as a cypher for exploring the category of the human. While the figure of the animal has provided a counterpoint to visions of humanity for centuries, emerging technologies and ideas about human consciousness have inflected the conversation in new and important ways. In what ways, for example, does contemporary technology compel us to reevaluate the distinctions between animal and human, on the one hand, and animal and object, on the other? The course will consider works such as Han Kang’s The Vegetarian, Werner Herzog’s Grizzly Man, Indra Sinha’s Animal’s People, and H.G. Wells The Island of Doctor Moreau.</p> <p><strong>Laughter and Non-Representation</strong></p> <p>While Aristotle is reputed to have written a treatise on comedy to match his famous discourse on tragedy, <em>The Poetics</em>, this is hard to believe as, in all his works, he shows almost no sense of humor. This first absence does not seem to have been filled in the many centuries that have followed. Both in number and quality, modern treatments of laughter seem inadequate. This weakness is perhaps because the funny is constitutively unavailable to rational representation. This class will explore laughter as exactly the embodied symptom that arises out of the intrinsic inadequacies of representation. After a quick critique of traditional theories of mimesis, we will explore the generation of laughter through various contemporary theories and attempt to understand its function for the liberation of the unrepresented in works thought funny, from Laurence Sterne to Ishmael Reed. Open only to junior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7947,2021,1597,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/300/engl-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7948,2021,1232,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/400/engl-490','<div class="desc"> <p>In this course, seniors will design and carry out advanced research projects in areas of their own interests. Seminar meetings will be devoted to discussion of a core group of theoretical and/or historical texts (varying from year to year), and to practical issues of sophisticated literary critical work. The course will result in a substantial critical paper, a version of which will be presented at the Spring Senior Symposium, in satisfaction of Occidental''s Comprehensive requirement. Open only to senior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7950,2021,1598,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/engl-english/400/engl-499','<div class="desc"> <p>Research, writing, and defense of the Honors thesis in English. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7951,2021,165,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/100/fren-101','<div class="desc"> <p>Introduction to French through a variety of communicative approaches. Emphasis is placed on speaking and listening, as well as grammar and writing. Students who have had more than one year of French in high school, or more than one quarter in college, may not take this course for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7952,2021,166,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/100/fren-102','<div class="desc"> <p>This course is a continuation of FREN 101. Students are introduced to the culture of the French-speaking world through readings and discussions.</p> </div>','FREN 101; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7953,2021,167,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/100/fren-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7954,2021,580,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/100/fren-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7955,2021,581,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/100/fren-197','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7956,2021,168,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/200/fren-201','<div class="desc"> <p>Oral work and composition based on the study of 20th century cultural history and contemporary issues of the French-speaking world. Integrated language laboratory program for aural comprehension and pronunciation. Advanced grammar.</p> </div>','FREN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7957,2021,582,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/200/fren-202','<div class="desc"> <p>The methods and vocabulary of textual analysis introduced through close reading, discussion, and written commentary of selected poems, plays, and prose texts, from the Renaissance to the present. The techniques of French critical writing, oral explication de texte, and commentaire composé will be stressed. Includes study of general linguistic problems pertaining to the structure of modern French (vocabulary, phonetics, grammar style). This course is required of all French majors and minors and for students wishing to study in France.</p> </div>','FREN 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7958,2021,169,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/200/fren-251','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7959,2021,583,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/200/fren-252','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7962,2021,842,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-301','<div class="desc"> <p>An introduction to late 20th-century Francophone literary works (short stories, a novel, poetry) and films, from the Levant (Lebanon, Syria) and North Africa (Egypt, Tunisia, Algeria, and Morocco). The course underlines the diversity of this part of the world, the various ways in which French is used, and its relation to the native tongue-Arabic. The Arab Spring and questions of cultural/national identity are also examined. Among authors studied are Tahar Ben Jelloun (Morocco) and Lamia Ziadé.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7963,2021,843,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-350','<div class="desc"> <p>An introduction to the theory and practice of translation from English to French ("thème"), and French to English ("version"), as both a craft and an art, with its codes and principles. Although emphasis is placed on practice, the course examines important theoretical questions, such as translation as both a product and as a process. With some attention to the difference between "literal" and "free" translation, the course explores the lexical and semantic strategies that translators employ. The course begins with the smallest "unit of translation," and progresses to consider a wide variety of texts: fiction; poetry (song lyrics); advertisements, televisual and filmic. Students may choose to translate a business, technical, legal, medical, or literary text as part of their final project.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7965,2021,170,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-355','<div class="desc"> <p>Readings and discussion in the French novel and philosophical texts, including works by Prévost, Diderot, Rousseau, Bernardin, de Saint-Pierre, Balzac, Stendhal, Flaubert, and Zola.</p> </div>','FREN 202; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7966,2021,1070,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-363','<div class="desc"> <p>The course is an exploration of various literary and cinematic representations of the French colonial history and its impact on the peoples of the Maghreb and West Africa. It examines narratives of war, dominion, racism, and collaboration. Films and literary texts examined include: <em>Les Indigènes </em>(Rachid Bouchareb); <em>Le Camp de Thiaroye</em> (Ousmene Sembene); <em>Le Vieux Nègre et la Médaille </em>(Ferdinand Oyono); and <em>Meursault, contre-enquête</em> (Kamel Daoud).</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7967,2021,1016,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-365','<div class="desc"> <p>Psychological and political views of the "disruptive" female presence in literature, and in the critical theory of Derrida and Lacan. Works will range from 17th century fiction, to feminist writers including Beauvoir, Irigaray, and Cixous, as well as examples of women''s self writing in the Francophone world. Taught in French and English. Counts for the French major and minor and for CSLC.</p> </div>','FREN 202; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7968,2021,2443,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-370','<div class="desc"> <p>This course explores the history and development of one literary genre (fiction, poetry, theater, or cinema) across different periods and in different French-speaking communities. Content varies from year to year.</p> <p style="margin-left:0in; margin-right:0in"><strong>Francophone voices of Africa and the Caribbean</strong></p> <p style="margin-left:0in; margin-right:0in">This course traces the development of literature in French by writers living in or originating from France’s former colonies, primarily the Caribbean and Sub-Saharan Africa. Through short stories, novels, and the <em>bande dessinée</em>, we will examine key intellectual, political, and social movements that have shaped, and continue to shape, Francophone postcolonial identities. We will consider themes such as decolonization, Negritude, tradition vs modernity, immigration and exile, and hybrid/Afroeuropean identities. Texts will include works by Aimé Césaire, Edouard Glissant, Maryse Condé, Mariama Bâ, and Alain Mabanckou. Additional Core Requirement Met: Global Connections.</p> </div>','FREN 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7969,2021,1456,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-372','<div class="desc"> <p>Beginning with a history of French cinema and an introduction to film criticism, this course examines narrative techniques in film and fiction, with an emphasis on post-1968 film production in France, and on fiction that explores, among other themes, gender and desire. Films and novels to include: <em>Madame Bovary</em> (Flaubert), <em>L''Amant </em>(Duras), <em>Les Misérables</em> (Hugo), <em>Un Amour de Swann</em> (Proust), and <em>L’Armée du Salut</em> (Taïa).</p> </div>','FREN 202; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7971,2021,585,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/300/fren-397','<div class="desc"> <p>Individual study of a major author, movement, or genre; or the teaching of French. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7972,2021,586,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/400/fren-490','<div class="desc"> <p>The seminar will focus on the close reading and informed discussion of texts from the major reading list (from Chanson de Roland and the Middle Ages to post-colonialism) within the context of literary theory (from Sainte-Beuve to Derrida), and it will focus on writing workshops designed to perfect analytical writing (techniques of the commentaire composé and the dissertation littéraire). Although open to all students, the seminar is intended, principally, to facilitate the completion of the Comprehensive examination in French. The seminar, readings, and activities will be tailored to meet individual student interests and needs. This course may be repeated for a total of 8 credits toward graduation, only 4 of which may count for the major.</p> </div>','FREN 350 or above ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7974,2021,587,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/fren-french/400/fren-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(7975,2021,171,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/100/geo-105','<div class="desc"> <p>Introduction to Geology with emphasis on the physical processes that shape the environment on the Earth''s surface. The course will cover the fundamentals of plate tectonics, rocks, minerals, geologic time, surface processes, and Earth''s interior. Special attention will be paid to geologic hazards (such as earthquakes, volcanoes, floods, and landslides), the history and future of global climate change, and the human impact on the environment. <em>Includes one two-hour laboratory per week and a one- or two-day field trip.</em> Students who have completed a substantive introductory Geology course are encouraged to seek permission of the instructor to enroll in any of the 200-level Geology courses.Open only to first and second year students.</p> </div>',NULL,'GEO 105L ',NULL);
INSERT INTO course_descriptions VALUES(7976,2021,1457,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/100/geo-106','<div class="desc"> <p>Nature and humanity interact with and impact one another in complex and significant ways. Human health, safety, and economic well-being are significantly impacted by natural processes, providing both opportunities and constraints on sustainability. This course focuses on these interactions as studied by earth scientists. Topics include: Earth surface properties and processes, air quality, mineral and energy resources/reserves for industrialized society, water resources, hazardous earth processes, and development and degradation of soils and climate. Labs will include using problem-solving skills and case studies. <em>Includes one two-hour laboratory per week and a one-day field trip.</em></p> </div>',NULL,'GEO 106L ',NULL);
INSERT INTO course_descriptions VALUES(7977,2021,589,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/100/geo-150','<div class="desc"> <p>This course focuses on teaching students how to access, integrate, and quantitatively evaluate many types of spatial information using different methods of analysis. Students use GIS software to understand, explore, and analyze information from a variety of sources, with an emphasis on understanding the geography of environmental health and the relationships between multiple determining factors. Students will learn fundamentals of geography and cartography, GIS techniques in quantitative spatial analysis, and introductory spatial statistics as applied to vector-based data. The tools and skills used in this course, and the analytical problem-solving projects used in laboratory and project assignments, will provide them with a means to better understand the environmental health risk and epidemiology, and enhance their ability to make informed and quantitative comparisons. (Students are encouraged to enroll in UEP 201, a course that explores how environmental factors impact human and ecological health).</p> </div>',NULL,'GEO 150L ',NULL);
INSERT INTO course_descriptions VALUES(7979,2021,591,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-215','<div class="desc"> <p>The history of the Earth and life upon it, from the origin of the planet 4.6 billion years ago to the present. The course focuses on the chemical, physical, and biological processes that have affected the planet''s interior and surface, including atmosphere, hydrosphere, and lithosphere, through time. <em>Includes one three-hour laboratory per week and field trips.</em></p> </div>','GEO 105 or GEO 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7980,2021,2883,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-220','<div class="desc"> <p>The fundamentals of rock formation are explored through study of common rock-forming minerals and major rock types. Understanding of these processes is based on the physical, optical, chemical, and textural properties of minerals and rocks. The course includes a field trip to investigate rocks and minerals in some of California''s most interesting natural settings. <em>One three-hour laboratory per week and field trip.</em></p> </div>','GEO 105 or GEO 106 ','GEO 305L - to be changed to 220L ',NULL);
INSERT INTO course_descriptions VALUES(7981,2021,173,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-225','<div class="desc"> <p>Collection and interpretation of geologic data form the core of the course, with seven days devoted to field work. Basic rock identification, analysis of ancient environments, and structural geology are discussed and applied during field work. Scientific writing skills are emphasized. The techniques learned in this course are widely applicable so the course is open to majors of any specialty. Field trips replace weekly laboratory work.</p> </div>','GEO 105 or GEO 106 ','GEO 225L ',NULL);
INSERT INTO course_descriptions VALUES(7982,2021,593,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-235','<div class="desc"> <p>An introduction to plate tectonics and the geology of plate boundaries. Topics include: techniques for describing plate motions, earthquakes and seismology reversals of the earth''s magnetic field, the nature of the seafloor, and the geology of mountain belts. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 or GEO 106, or permission of instructor ','GEO 235L ',NULL);
INSERT INTO course_descriptions VALUES(7983,2021,1332,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-240','<div class="desc"> <p>This course will examine the physical and chemical process associated with geologic events that occur on the human time scale and harm society: earthquakes, volcanism, and mass wasting. Focusing on events from California, the course will include in-field examinations of local geological examples, as well as quantitative and qualitative evaluation of geophysical and geochemical datasets associated with well-documented case studies. <em>Includes one three-hour laboratory per week and required field trips.</em></p> </div>','GEO 105 or GEO 106 ','GEO 240 ',NULL);
INSERT INTO course_descriptions VALUES(7984,2021,844,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-245','<div class="desc"> <p>An introduction to Earth''s climate system and the geological record of its change. Topics covered include: Earth''s radiative balance and the role of greenhouse gases, poleward transport of heat by the atmosphere and ocean, climate change on the plate tectonic timescale, the Cenozoic cooling, astronomical control of Pleistocene glacial cycles, rapid millennial-scale climate change, and the future of Earth''s climate. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 or GEO 106, or permission of instructor ','GEO 245L ',NULL);
INSERT INTO course_descriptions VALUES(7985,2021,595,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/200/geo-255','<div class="desc"> <p>An introduction to concepts of Geographic Information Science and spatial analysis using GIS; designed for natural science majors. Emphasis on spatial analysis, both vector and raster data, including: aerial photos, satellite imagery, and introductory terrain analysis. Course also includes introduction to GIS data acquisition and Global Positioning Systems receivers, individual and group projects, and presentation of results. It is expected that students are experienced using the MS Windows operating system and Microsoft Excel software. <em>One three-hour laboratory per week.</em></p> </div>','GEO 105, GEO 106, GEO 150, or permission of instructor ','GEO 255 ',NULL);
INSERT INTO course_descriptions VALUES(7988,2021,1071,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/copy-of-geo-390l','<div class="desc"> <p>Weekly three-hour laboratory in conjunction with GEO 390 Special Topics in Geology.</p> </div>',NULL,'GEO 390',NULL);
INSERT INTO course_descriptions VALUES(7989,2021,1334,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-315','<div class="desc"> <p>Study of the processes of sedimentation, the properties of sedimentary rocks, and the use of stratified sedimentary sequences for correlation, dating, and interpretation of depositional environments and geologic history. Course includes field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>','GEO 225; and GEO 105 or GEO 106 ','GEO 315L ',NULL);
INSERT INTO course_descriptions VALUES(7990,2021,1335,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-315l','<div class="desc"> <p>Field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'GEO 315',NULL);
INSERT INTO course_descriptions VALUES(7991,2021,1336,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-324','<div class="desc"> <p>Building on material learned in GEO 225 and GEO 305, this course involves the mapping of more complex areas. Fieldwork is the heart of this course and full participation in the 4-6 days of fieldwork is required. May be taken twice for credit.</p> </div>','GEO 225 and GEO 305 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7992,2021,597,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-325','<div class="desc"> <p>Study of the deformation of rocks and the structures produced. Rock mechanics are introduced and the nature and origin of folds, faults, and other structures are discussed, along with the relation of structures to tectonic settings. Course includes interpretation of areas displaying complex geological relations that illustrate structural principles. <em>Includes field trips and one three-hour laboratory per week.</em></p> </div>','GEO 225 ','GEO 325L ',NULL);
INSERT INTO course_descriptions VALUES(7993,2021,598,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-325l','<div class="desc"> <em>Three-hour per week laboratory.</em> </div>',NULL,'GEO 325',NULL);
INSERT INTO course_descriptions VALUES(7994,2021,938,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-342','<div class="desc"> <p>Landforms and their interpretation in terms of tectonic and climatic processes will be presented. The focus will be on landforms such as: mountain belts, faults, and landslides caused by active tectonic processes. Methods of dating and quantifying geologic events will be introduced. Scientific writing skills will be emphasized. <em>Includes one three-hour laboratory per week and field trip.</em></p> </div>','GEO 225 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(7995,2021,1170,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-342l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 342',NULL);
INSERT INTO course_descriptions VALUES(7996,2021,939,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-345','<div class="desc"> <p>Petrology is the study of the origin, tectonic occurrence, geochemical evolution, and classification of igneous and metamorphic rocks. Students will address questions related to the origin of the Earth''s crust through examination of the textures, mineral assemblages, field relations, and compositional characteristics of igneous and metamorphic rocks. Laboratory work will engage students in the study of rocks in hand specimen and microscope, as well as the analysis and interpretation of experimental and geochemical datasets. <em>Includes one three-hour laboratory per week and multiple field trips.</em></p> </div>','GEO 305 ','GEO 345L ',NULL);
INSERT INTO course_descriptions VALUES(7997,2021,940,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-345l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 345',NULL);
INSERT INTO course_descriptions VALUES(7998,2021,1017,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-355','<div class="desc"> <p>This course is an introduction to the Earth''s ancient magnetic field and the magnetic properties of rocks. Students will learn how rocks acquire a magnetic signal and will explore how those signals relate to the structure of the geomagnetic field. Special emphasis is placed on collection of samples in the field and with special emphasis on laboratory techniques and applications. Strongly recommended for students considering research projects with Professors Bogue and Cromwell. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 or GEO 106 ','GEO 355L ',NULL);
INSERT INTO course_descriptions VALUES(7999,2021,1018,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-355l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 355',NULL);
INSERT INTO course_descriptions VALUES(8000,2021,599,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-390','<div class="desc"> <p>Two- or four-credit advanced courses on specialized topics in Geology. May be taken more than once with department approval as topics vary. </p> <p><strong>Paleontology: The Record of Life, Landscapes, and Changing Climate</strong></p> <p>This course will use the fossil record as a tool to explore the geologic controls on the evolution and extinction of life on earth. From Snowball Earth to the Great American Biotic Interchange, plate tectonics and climate change drive the distribution of life through time. We will examine paleontological and modern ecosystems through classes, labs, and field trips. Students should have completed GEO105 and at least one 200-level course in biology or geology.</p> <p style="color: #212021; margin-bottom: 10px; padding: 0px;"><strong style="margin: 0px; padding: 0px;">Geochemistry</strong></p> <p style="color: #212021; margin-top: 0px; padding: 0px;">This course will explore the geochemical principles controlling fundamental geologic systems, from the "weathering engine," to the igneous-metamorphic-hydrothermal systems that form and shape planets. This overview of Geochemistry will focus on thermodynamics and kinetics, which allow us to assess these systems with regards to temperature, pressure, and time. Quantitative evaluation of earth processes through geochemical modeling will be conducted using the programs SUPCRT, Visual Minteq, and Geochemist''s Workbench (industry standards). Laboratories, workshops, and fieldtrip(s) will reinforce and expand on many of the topics covered in class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8001,2021,2627,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-391','<div class="desc"> <p>This class serves as preparation for Senior Comprehensives in Geology. Topics include comps options, analysis and presentation of scientific data, literature searches and attribution of previous work. Students will develop a formal plan to complete their senior comprehensive requirement. Open only to junior Geology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8002,2021,1522,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-395','<div class="desc"> <p>Research under guidance of faculty member on jointly selected project. May be taken four times for credit. Permission of instructor required.</p> </div>','GEO 105 and GEO 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8003,2021,179,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/300/geo-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8004,2021,2551,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/400/geo-491','<div class="desc"> <p>This seminar focuses on analysis, discussion, and presentation of current issues in geological research. These topics will be explored through the geologic literature and the class will include a formal presentation to the Geology Department. Students will also learn about graduate school and career options in the Earth Sciences. Open only to senior Geology majors.</p> </div>','GEO 391 or GEO 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8006,2021,600,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/geo-geology/400/geo-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8007,2021,181,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/100/germ-101','<div class="desc"> <p>Introduces basic language skills, grammar, pronunciation, oral communication, and reading simple prose. Culture taught through readings, videos, and discussions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8008,2021,602,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/100/germ-102','<div class="desc"> <p>Continuation of GERM 101.</p> </div>','GERM 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8009,2021,182,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/100/germ-151','<div class="desc"> <p>Oral practice based on articles in current periodicals and other subjects of general interest. Taught by a German language assistant from the University of the Saarland, under the supervision of a German instructor. Designed primarily for students who have completed GERM 102. Graded on Credit/No Credit basis; attendance is mandatory. Approximately two hours of work outside of class time required each week. May be repeated for credit.</p> </div>','GERM 102; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8010,2021,603,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/100/germ-152','<div class="desc"> <p>Continuation of GERM 151. Designed primarily for students who have completed GERM 102. Graded on Credit/No Credit basis; attendance is mandatory. Approximately two hours of work outside of class required each week. May be repeated for credit.</p> </div>','GERM 102, GERM 151, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8012,2021,183,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-201','<div class="desc"> <p>An advanced course to build up comprehension, as well as oral and writing skills. Reading and discussion of literary and cultural texts supplemented with video films and T.V. news on current events in Germany. Practice in essay writing.</p> </div>','GERM 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8013,2021,604,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-202','<div class="desc"> <p>Continuation of GERM 201 at an advanced level. Review of advanced German grammar, and exercises in stylistics and essay writing.</p> </div>','GERM 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8014,2021,941,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-232','<div class="desc"> <p>This course covers major trends and developments in the cultural history of postwar Germany. Topics include: the reconstruction of culture after 1945, the makeup of cultural institutions, the mass media, popular culture vs. traditional culture, the counter culture of the 60''s and early 70''s, and the problems of unification after 1989. Taught in German, with emphasis on oral presentations and essay writing. Readings include: literary texts, documentary material, newspaper, and magazine articles.</p> </div>','GERM 201; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8015,2021,184,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-251','<div class="desc"> <p>Open to all qualified students, but designed primarily for students preparing for Occidental-in-Germany program. May be repeated for credit.</p> </div>','GERM 152; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8016,2021,605,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-252','<div class="desc"> <p>Continuation of GERM 251. May be repeated for credit.</p> </div>','GERM 251; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8018,2021,1337,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-280','<div class="desc"> <p>The onset of industrialization in the 19th century created the modern metropolis and the angst and attraction of the lifestyle that went with it. In this course, we will examine how writers and intellectuals of the late-19th and early-20th century described their experience of this new urban environment - analyzing their discoveries and discontents. In addition to fiction by Rainer M. Rilke, Emile Zola, Irmgard Keun, Alfred Döblin, Walter Benjamin, and others, we will also discuss seminal texts by architects, urban planners, and theorists, and look at how visual artists and filmmakers depicted the emerging streetscape of modernity. Students will have the opportunity to explore the impact of modern urbanization in a contemporary and global context through field trips and class projects. The course is taught in English. This course is not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8019,2021,1123,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/200/germ-282','<div class="desc"> <p>The rise and fall of National Socialism is one of the most intensively studied topics in European history. Over six decades after its collapse, Nazi Germany continues to fascinate the general public, and with good reason. Although the fascist state lasted only for twelve years, it started history''s most destructive war, while committing crimes of unprecedented proportions. For the most part, it did so with the acquiescence of the German public. This class will investigate the rise of National Socialism as a political, social, and cultural phenomenon. The central focus will be on the decisive role of film and the visual arts as the most popular means of mass manipulation. This course is not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8023,2021,2339,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/copy-of-germ-311','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different “scenes of writing,” from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature’s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience, and knowledge are produced, articulated, and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler. Taught in German.</p> </div>','GERM 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8024,2021,2654,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-307','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison. This course will meet three times a week. Twice with CSLC 107 with discussion conducted in English, and a third weekly meeting in which all readings and discussions will be conducted in German.</p> </div>','GERM 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8025,2021,2552,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-308','<div class="desc"> <p>This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling. </p> <p>This course will meet three times a week, twice with CSLC 108 with lectures and discussion in English, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','Must have completed the German language sequence (GERM 101, 102, 201, 202) or placed out of Elementary and Intermediate German ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8026,2021,1523,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-309','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables and riddles to anecdotes, jokes, short stories and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin and Twitter. This course will meet three times a week, twice with CSLC 109, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8027,2021,1658,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-310','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-1778) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with such major figures as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as its unprecedented boom in popularity around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. In concluding with the rise of Nazism and their attacks on modern art as "degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. This course will meet three times a week, twice with CSLC 210, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8028,2021,2705,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-312','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes From the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor. In addition to the English section, this course will meet for an additional session per week to read the and discuss the German language and other supplementary texts in their original. Readings will occur in German and will serve as an introduction to the major developments of the German language from Middle High German to the advent of High German in the writings of Martin Luther to its modern iterations in Hermann Hesse. Authors will include among others, Meister Eckhart, Martin Luther, Franz Kafka, and Hermann Hesse while discussion will occur in English and German and focus on the intricacies of the original language text and developing arguments out of it. </p> </div>','German 202 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8029,2021,2751,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-315','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> <p>This section will meet once a week extra to discuss these texts as read in the original German. Reading, but not speaking knowledge of German is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8030,2021,2865,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-316','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and falliabiltiy. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> <p>In addition to the English section, this course will meet for an additional session per week to read the texts in their original German and discuss the nuance and difference in meaning as it it transmitted through the original language. Reading the text in the original German is particularly important in the case of Heidegger, whose philosophical program cannot be separated from his thinking about language and the intricate relationship between language and meaning. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the second year writing requirement. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8031,2021,2896,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-318','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness.?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. </p> <p>The course will consist of two parts. First, the Tuesday-Thursday lecture in English (shared with CSLC 118) and second, a German language section in which we read the texts in which we read the texts in the original and discuss the nuances of the text as it reads in the original language. Discussion will be in English. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second Stage Writing requirement.</p> </div>','German 202 or advanced reading knowledge of German. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8032,2021,1019,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-320','<div class="desc"> <br/> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into "new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the Humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. This course will meet three times a week, twice with CSLC 120, and a third weekly meeting in which all readings and discussion will be conducted in German. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8033,2021,1599,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-321','<div class="desc"> <p>This course is concerned with the cultural politics of memory and trauma after 1945. We will start with basic questions such as: whose memories are sought, believed, and commemorated in the public sphere? What problems do traumatic events present for those attempting to represent them? Is trauma a useful cultural concept? What are the differences between individual and collective memory? We will then identify the recent fascination, especially in European and American culture, with the phenomenon of trauma, suffering, and victimhood, and focus on the impact on Jewish identity (in various countries), as well as the collective memory of Germans, after 1945.</p> </div>','GERM 202 or GERM 232 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8034,2021,1124,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-325','<div class="desc"> <p>The European project - i.e. the gradual unification of the continent - which had been successful for decades, seems to undergo a fundamental crisis at present. This crisis has different aspects. Primarily, it has to do with the economic inequities within the European Union which became tangible in the aftermath of the world economic crisis of 2008. In its wake, the "weaker" economies, mostly at the periphery, were more affected than the stronger ones. But, there are also other problems, such as the lack of democratic structures, as well as strong leadership, the weight of a centralized bureaucracy, and the lack of a European public sphere. The course will take a look at the achievements of the European Union, the multiple reasons for its current crisis, and the various attempts to overcome it. Open only to juniors and seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8035,2021,185,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-370','<div class="desc"> <p><strong>Bertolt Brecht and the Twenties</strong></p> <p>Bertolt Brecht is one of the most influential playwrights and aesthetic thinkers of the 20th century. In order to understand the scope and dimension of his work and its world wide influence, this course will focus on the artistic development of young Bertolt Brecht who, in the early 20''s, moved to Berlin, the capital of newly founded democratic Weimar Republic, and one of the most important cultural centers of the 20th century, and participated in practically all innovative tendencies and art forms of the time, from Expressionism and Dadaism to New Objectivity, from experimental theatre to radio and film. Some of his great early works, such as the <em>Three Penny Opera, </em>will be seen in the context of the time, especially the very turbulent last years of the Weimar Republic before Hitler''s rise to power. We will also look at Brecht''s legendary film<em> Kuhle Wampe,</em> and visit at least one contemporary production of a Brecht play staged at a theatre in Los Angeles. </p> <p><strong>Bertolt Brecht: The Great Plays</strong></p> <p>Brecht''s great plays changed the stage of world theatre. In order to understand and appreciate their powerful and long lasting influence, all major plays written during Brecht''s exile - i.e. in the years between 1933, when he was driven out of Germany, and 1948, when he returned to Switzerland and, ultimately, Berlin - will be discussed. Aside from detailed analyses of plays such as<em> Mother Courage, The Good Woman of Sezuan, The Caucasian Chalk Circle, </em>or <em>Life of Galilei,</em> Brecht''s developing theory of epic theatre, and the general conditions and dilemmas of exile, will be discussed. We will also look at Brecht''s role in Hollywood, his collaboration on the film <em>Hangmen Also Die</em>, and his successful attempts to direct his own plays on German and European stages after 1950. Students minoring in German or majoring in Group Languages or IPS will read most of the texts in the original language. </p> <p>Prerequisite for German minor and Group Language majors: GERM 202 or GERM 232. Open to all other non-first year students. The course is taught in English; no knowledge of German is required. </p> <p><strong>Memory, Trauma, and Victim Culture</strong></p> <p>This course is concerned with the cultural politics of memory and trauma after the catastrophic events of the Holocaust and World War II. We will start with basic questions such as: whose memories are sought and commemorated in the public sphere? What problems do traumatic events present for those attempting to represent them? Is trauma a useful cultural concept? What are the differences between individual and collective memory? The first part of the course analyzes memory and trauma on both the individual level and the collective level, and turns, then, to the specific processes that occur when traumatic events are remembered by survivors, as well as the collective processes involved when memories of traumatic events, such as the Holocaust, are shared with an audience who has no first-hand experience of them. The second part of the course aims to identify the recent fascination, especially in European and American culture, with the phenomenon of trauma, suffering, and victimhood. We will study the cultural politics of trauma and memory in relation to two events - the Holocaust and German suffering during World War II. The unit "Holocaust, Victimhood, and American-Jewish identity" explores how the kitsch nature of popular culture representations of the Holocaust (from the Anne Frank movie, to the very successful TV-series <em>Holocaust, </em>to the Hollywood movie <em>Schindler''s List</em>) created the paradigm for trauma culture at large. The unit "Germans in Collective Memory Between Perpetrators and Victims" discusses contemporary German memory discourse, which primarily focuses on the experience of German suffering as a consequence of the war and the Third Reich. However, to recast Germans as victim is highly problematic since the position of victim is already occupied by those people who were persecuted and murdered by the Germans/Nazis. Memory, trauma, and victimhood are crucial aspects of the experiences of Jews and Germans after 1945. A systematic exploration of these aspects (as manifested in a broad variety of cultural forms) promises important insights into recent history and culture. </p> <p><strong>Nazi Culture</strong></p> <p>After the Nazis came to power in 1933, they took over control of all aspects of German life. One of the first tasks the new government undertook, upon their ascension to power, was a synchronization of all professional and social organizations with Nazi ideology and policy. Joseph Goebbels, Nazi Minister for Popular Enlightenment and Propaganda, began an effort to bring German arts and culture in line with Nazi goals. The government purged cultural organizations of Jewish persons and other officials alleged to be politically suspect, or who performed or created art works that Nazi ideologues labeled "degenerate." Some 650 works, by such renowned artists as Max Beckmann, Marc Chagall, Otto Dix, Wassily Kandinsky, and Paul Klee, were declared "degenerate art" and removed from German museums. The Nazi "cultivation of art" also extended to the modern field of cinema, theater, music, architecture, youth education, and even to the lower levels of popular culture. Throughout the duration of the Nazi regime, "culture," in all its manifestations, played a crucial role. Political rallies, military parades, sports events, open air festivals, and other skillfully organized events were used, from the beginning, to suggest a "national awakening" and the "revolutionary spirit" of the new regime. The efforts of the Nazis to regulate German culture corresponded to what historian George Mosse calls an effort "toward a total culture" - i.e. an effort to influence, at the most basic level, the lives and actions of all Germans. This course will explore the various forms of culture during this time and will raise the question as to what extent "Nazi culture," or culture under Nazi domination, was capable of stabilizing the regime until its very end in 1945. Students minoring in German or majoring in Group Languages will read some of the course material in its original German. </p> <p>Prerequisite for German minor and Group Language majors: GERM 202 or GERM 232.</p> <p><strong>Marx Freud and the Frankfurt School</strong></p> <p>This seminar will explore the origins of the world famous Frankfurt School, a group of German social philosophers and theoreticians, which emerged at the Institute for Social Research of the University of Frankfurt am Main in the 1920''s. The group wanted: (1) to analyze the conditions of modern capitalism and its impact on society in general, on family and social structures, value systems, and mass culture; (2) critically review the theories of Karl Marx, Sigmund Freud, and Max Weber; and (3) to establish the principles and foundations of a "critical theory." We will read and discuss major works by Max Horkheimer, Theodor W. Adorno, Walter Benjamin, Herbert Marcuse, Erich Fromm, Siegfried Kracauer, Leo Loewenthal, and others. The seminar will focus on the "first phase" of the Frankfurt School, its beginnings and its work and development during the 30''s and 40''s - when the school relocated to New York and many of its collaborators lived in other American cities or abroad - and the immediate post WWII period. (A second seminar will follow next year and explore the school''s development and its world wide impact in the 60''s and 70''s.) The course is taught in English. Students minoring or majoring in German will read some of the original texts (especially Marx, Freud, Benjamin, and Kracauer,) that are written in German. Open only juniors and seniors.</p> <p>Cross-Listed as: CTSJ 370.</p> <p><strong>The Frankfurt School 1945 to the Present</strong></p> <p>Social analysis, cultural theory, and political action. This seminar will explore the history of the Frankfurt School after World War II when it was re-established in Frankfurt and began to play a crucial role in the development of a "critical theory" of society and culture during the West German "economical miracle;" afterwards, with the onset of the German (and international) student movement of the mid-60''s, it gained international reputation and impacted social, political, and cultural discourses in countries like France, Great Britain, Italy, and the United States. We will study, primarily, some of the major writings of Theodor W. Adorno (especially on art, music, cultural theory, and the lessons of Fascism), Herbert Marcuse (whose writings on social theory and aesthetics, "repressive tolerance," and "liberation" exerted a strong influence on the student movement), and of Jurgen Habermas, who became one of the most influential European intellectuals in the decades after 1970. This seminar is the continuation of an earlier class on the beginnings of the Frankfurt School and its history until 1945; participation in that earlier seminar is not required. The course is taught in English. Students minoring in German or majoring in Group Language or IPS will read some of the original texts in German.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8037,2021,606,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/germ-german/300/germ-397','<div class="desc"> <p>Individual study of a major author, movement, genre, or translation technique. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8039,2021,186,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/100/grk-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Ancient Greece. Students will engage, from the beginning, with original texts from Homer, Sophocles, Plato and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Greeks, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8040,2021,607,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/100/grk-102','<div class="desc"> <p>Continuation of GRK 101 and reading of adapted Greek texts.</p> </div>','GRK 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8042,2021,187,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/200/grk-201','<div class="desc"> <p>Homer''s epics feature some of the best known, and varied, heroes of antiquity, like Achilles, Hector, Odysseus, and Penelope. In this class, we will read selections from the <em>Odyssey </em>and <em>Iliad </em>as a way to examine ancient conceptions of heroism. For students studying ancient Greek, this will primarily be a translation course and will serve as an introduction to epic poetry. Students without Greek are also welcome and can expect to approach the topics of the class by reading translated texts and modern scholarship.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8045,2021,1600,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-380','<div class="desc"> <p>This course will meet at the same time as CSLC 280, and for an additional weekly meeting in which we shall translate one tragedy by Sophocles and one by Aeschylus from the original Greek. In this course, we shall attempt to come to terms with three of the most important - and provocative - philosophers of the last two hundred years, philosophers without whom the great majority of contemporary literary and cultural theory (and much art and literature, itself) would, essentially, be unthinkable. Significantly, all three of these philosophers habitually turned to ancient Greek tragedy in the formulation, articulation, and further elaboration of their thought. In this course, we shall therefore attempt to use the experience of Greek tragedy, in all its ecstatic strangeness, as a powerful point of entry into the difficult, yet crucial, works these philosophers have bequeathed to us. Major texts to be covered include: the plays of Aeschylus and Sophocles, <em>The Phenomenology of Spirit, The Birth of Tragedy, Thus Spoke Zarathustra, Being and Time, and Introduction to Metaphysics.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8046,2021,2515,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-381','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage. This course meets with CSLC 181 and is for students who will be reading texts in the original Greek.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8047,2021,1524,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-382','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>','Greek 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8048,2021,1701,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-383','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all. The Greek section of this course will be devoted to translation of<em>The Iliad</em> from the original, paying particular attention to the ways in which the Homeric epic has been received in the almost three millennia since its original appearanceÍ¾ this will give our investigation into the history of style in the West (and its possible metaphysical grounds) a carefully delimited focal point.</p> </div>','Greek 102; or permission of instructor (proficiency in Ancient Greek) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8049,2021,2853,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-385','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. In addition to attending the 3 hours of lecture required of students in CSLC 285, students in Greek 385 are required to attend an additional 90 minutes of class per week to read and discuss texts in the original language. Students in this course are required to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8050,2021,1659,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-386','<div class="desc"> <p>In this course, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth''s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-Â­sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home," at all. This course will be offered in conjunction with CSLC 286, but will meet for an additional 90 minutes per week to read Homer''s <em>Odyssey </em>in the original Greek.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8052,2021,3109,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8053,2021,608,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/grk-greek/300/grk-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8057,2021,209,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/100/japn-101','<div class="desc"> <p>Introduction to the language in all its aspects, basics of grammar and oral communication and the reading and writing of hiragana &amp; katakana through intensive drills and exercises. Introduction to formal and casual speech styles. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Japanese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8058,2021,623,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/100/japn-102','<div class="desc"> <p>Continuation of JAPN 101. Further development of communication skills, both oral and written. Mastery of the basic conjugated forms of verbs and adjectives in the past-nonpast and positive-negative paradigms in both the polite -masu and plain forms. Students will learn to decode the speaker''s assumptions or attitudes as they are integrated into certain grammatical forms. Introduction to kanji (approximately 50 characters and their multiple readings).</p> </div>','JAPN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8060,2021,210,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/200/japn-201','<div class="desc"> <p>While consolidating their knowledge of grammar basics, students will learn the keigo (honorific forms) system and a variety of additional verb forms, both inflectional and paraphrastic. Increased emphasis on conversational skills, as well as training in composing texts with coherence and accuracy. Introduction of additional kanji and their multiple readings (approximately 200 characters over the two semesters of the intermediate level).</p> </div>','JAPN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8061,2021,624,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/200/japn-202','<div class="desc"> <p>Continuation of JAPN 201. Further development of all four skills. Students will deepen their understanding of the speaker''s attitudes, as well as the spatial and temporal concepts integrated in grammatical forms. Mastery of at least 250 kanji, with their multiple readings, by the end of this level.</p> </div>','JAPN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8062,2021,854,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/200/japn-271','<div class="desc"> <p>This course examines the art of storytelling via selected works of prose, fiction, and film, which were originally written/produced in the Japanese language in the early modern, through contemporary, periods. Through close reading of texts and visual images, the student will identify and analyze specific issues that are relevant to the critical messages and the development of the narrative. The course is given in English but those whose language proficiency permits may choose to read the texts in the original Japanese. Offered in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8063,2021,211,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/200/japn-273','<div class="desc"> <p>This course introduces literary traditions and aspects of Japanese popular culture under the Tokugawa <em>shogunate</em> (17th through mid-19th centuries), when education spread far beyond the elite samurai class and the people’s literacy rate rose to an unprecedented level thanks to long-lasting peace and economic development. We will primarily explore the rise of <em>haikai</em> (precursor to <em>haiku</em>), travel diaries, humorous oral narratives, and visual arts such as <em>ukiyo-e</em>, and examine how literary traditions practiced since ancient times are represented, transformed, and reinterpreted in those works. The course is given in English. Offered in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8064,2021,3009,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/200/japn-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8066,2021,212,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/300/japn-301','<div class="desc"> <p>Further development of the four skills. Mastery of certain grammatical forms with increasing emphasis on the speaker''s attitudes or assumptions regarding the situation. Introduction of the humble form in the keigo system. Introduction of additional kanji (approximately 250) and their multiple readings over the two semesters of the advanced level.</p> </div>','JAPN 202 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8067,2021,625,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/300/japn-302','<div class="desc"> <p>Continuation of JAPN 301. While completing the essentials of the structure of Japanese, students will prepare for a higher level of learning with intensive training in reading and writing, in particular. Students are expected to master 500 kanji, and their multiple readings, in total by the end of this course.</p> </div>','JAPN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8068,2021,855,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/300/japn-340','<div class="desc"> <p>This course focuses on current trends in Japanese language and society. By reading newspaper articles; listening to TV/radio news; and intensively studying vocabulary related to world affairs, social issues, and government, the student will be trained to grasp the critical information conveyed by these sources and to report accurately various facts, events, and thoughts orally and in writing. The student will also be introduced to the common practice of unorthodox usage of the language in advertisement, copy, and comic strips to develop, further, their comprehensive language skills. Given in alternate years.</p> </div>','JAPN 302 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8069,2021,626,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/300/japn-350','<div class="desc"> <p>In this course, the student will study various tales of the supernatural, including folk tales, myths, and ghost stories created in the ancient, through early modern periods, both aurally (from CD) and in writing. All the kanji in the text are presented with furigana attached so that a substantial quantity of reading may be accomplished time-efficiently. While reading and interpreting the text, the student will attempt creative writing of his/her original stories following the specific narrative styles. The student will also be introduced to the rakugo, humorous story-telling, performed in the traditional Japanese variety theater called yose.</p> </div>','JAPN 302 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8071,2021,627,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/300/japn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8072,2021,1383,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/japn-japanese-studies/400/japn-460','<div class="desc"> <p>This advanced level course will develop the student''s skill in reading Japanese through the practice of translation. The class will read a number of excerpts from authentic texts of different genres and discuss the issues that are critical for accurate comprehension of the source text, by applying theories of general linguistics, socio-linguistics, and translation; then they try translating the Japanese texts into readable English. Through the process of identifying, articulating, and solving challenges to Japanese-English translations, the students will further improve not only their language skills but cultural literacy as well.</p> </div>','JAPN 302 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8075,2021,214,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/100/kine-104','<div class="desc"> <p>Survey of kinesiology subdisciplines: human anatomy, exercise physiology, nutrition, motor learning, and sport and exercise psychology. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8076,2021,215,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/100/kine-196','<div class="desc"> <p>Supervised participation in the work of a nutrition exercise, or other health related company or agency. Permission of instructor required. Graded on a credit/no credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8077,2021,628,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/100/kine-197','<div class="desc"> <p>Research in a subdiscipline of kinesiology for students who do not have advanced competence in kinesiology (see KINE 397). Permission of instructor required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8078,2021,1178,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/200/kine-201','<div class="desc"> <p>This course examines the social and cultural factors that influence sport and physical activity. The positive and negative consequences of the way sport is organized in American society will be discussed. We will explore the unifying power of sport, as well as how sport serves to reproduce many of the inequalities present in our society. Topics include: violence, substance abuse, media, gender, race/ethnicity, and social class, and their roles within sport and physical activity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8079,2021,1704,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/200/kine-210','<div class="desc"> Introduction to the science of nutrition. Students will learn how macronutrients and micronutrients are assimilated into the human body from both dietary and supplement sources. A significant portion of the course will focus on understanding the science behind the USDA dietary guidelines and how to prepare meals for optimal health depending on age, sex, and physical activity levels. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8082,2021,216,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/200/kine-295','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8084,2021,1236,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/200/kine-298','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Prior to enrollment, students are expected to have a basic background in Kinesiology and/or public health (e.g. KINE 104). No previous research experience required. Students are permitted to repeat KINE 298 for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8085,2021,1527,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/200/kine-299','<div class="desc"> <p>This course will explore the impact of sports participation on female experiences, specifically considering multilevel psychological and socio-cultural women’s empowerment measures, such as self-esteem, self-efficacy, and solidarity. Focusing primarily on soccer, we will consider the possibility that the very act of training the body through sports contributes to a greater sense of ownership of one’s body – a critical psychological state for women’s health, personal security, and, ultimately, empowerment. Through the framework of social cognitive theory of gender development, we will also examine the relationship between physicality, psychology, and gender identity development. Finally, over the course of the semester, we will vet sports participation as an intervention to address gender inequality, including the impact of relevant policy, such as Title IX. Through a community-based learning component, students will have the chance to engage in qualitative inquiry on the effect of sports on health and self-concept. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8086,2021,217,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-300','<div class="desc"> <p>This first semester covers musculoskeletal anatomy and provides an in depth study of bone composition and development; joint morphology; muscle structure, function, mechanics, and movement analysis. Includes one three-hour laboratory per week. Not open to frosh.</p> </div>',NULL,'KINE 300L ',NULL);
INSERT INTO course_descriptions VALUES(8087,2021,218,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-300l','<div class="desc"> <p>Three hour per week Human Anatomy laboratory.</p> </div>',NULL,'KINE 300 ',NULL);
INSERT INTO course_descriptions VALUES(8088,2021,219,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-301','<div class="desc"> <p>A structural survey of the human body covering the nervous, endocrine, cardiovascular, lymphatic, respiratory, digestive, urinary, reproductive, and integumentary systems. Lecture will also include the special senses of vision, hearing, and olfaction. Includes one three-hour laboratory per week. Not open to frosh.</p> </div>',NULL,'KINE 301 ',NULL);
INSERT INTO course_descriptions VALUES(8089,2021,220,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-301l','<div class="desc"> <p>Three hour per week Human Anatomy II laboratory.</p> </div>',NULL,'KINE 301 ',NULL);
INSERT INTO course_descriptions VALUES(8090,2021,629,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-302','<div class="desc"> <p>The application of muscle mechanics and Newtonian mechanics to the documentation and analysis of human movement. Lecture will also focus on the application of static and dynamic problem solving to human performance. Laboratory work will be integrated with the lecture material and will emphasize the use of electromyography and video analysis to document and study human performance. Includes one three-hour laboratory per week.</p> </div>','KINE 300 ','KINE 302L ',NULL);
INSERT INTO course_descriptions VALUES(8091,2021,630,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-302l','<div class="desc"> <p>Three hour per week Biomechanics laboratory.</p> </div>',NULL,'KINE 302',NULL);
INSERT INTO course_descriptions VALUES(8092,2021,1384,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-304','<div class="desc"> <p>Introduction of principles of human physiology with special emphasis on a systems approach. Presentation of an integrative approach to basic physiology of major organs and organ systems, covering aspects of cell function, including membrane transport, excitability, metabolism, and functions of organs from the nervous muscular, respiratory, cardiovascular, gastrointestinal, renal, endocrine, and reproductive systems. Includes one three-hour laboratory per week.</p> </div>','KINE 301 or BIO 115 ','KINE 304L ',NULL);
INSERT INTO course_descriptions VALUES(8093,2021,1385,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-304l','<div class="desc"> <p>Three hour per week laboratory for Human Physiology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8094,2021,631,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-305','<div class="desc"> <p>The study of human functions and their physiological adaptation to, and specification for, the stress of exercise. Cardiovascular and respiratory responses to exercise; use of calorimetry to study metabolism during exercise; effects of environmental stress on exercise performance; body composition; ergogenic aids and nutritional factors in exercise performance.</p> </div>','KINE 304 and CHEM 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8095,2021,221,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-306','<div class="desc"> <p>Energy sources for human movement; substrate and energy metabolism during exercise; liver, skeletal, and cardiac muscle adaptations to acute and chronic exercise training.</p> </div>','CHEM 120 and KINE 307 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8097,2021,946,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-309','<div class="desc"> Developmental perspective of factors contributing to acquisition of motor control from infancy through adolescence. Emphasis placed on maturational and environmental factors. </div>','PSYC 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8098,2021,224,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to Juniors and Seniors only.</p> </div>','PSYC 101 ','KINE 310L ',NULL);
INSERT INTO course_descriptions VALUES(8099,2021,225,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'KINE 310',NULL);
INSERT INTO course_descriptions VALUES(8100,2021,632,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-311','<div class="desc"> <p>This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance, and level of participation of an individual or group.</p> </div>','PSYC 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8101,2021,226,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-395','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8102,2021,227,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-396','<div class="desc"> <p>Supervised participation in the work of a nutrition exercise or other health related company or agency. Graded on a Credit/No Credit basis only. May be taken for up to a maximum of 4 units of credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8103,2021,634,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-397','<div class="desc"> <p>Individual study for students with advanced competence. Extensive study of a specialized topic or broad study of an area not otherwise included in the curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8104,2021,1237,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/300/kine-398','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Enrolled students will assume leadership responsibilities in course projects (e.g. become course liaison with community partners, develop research proposals, manage course mini-projects etc.). Can be repeated for credit.</p> </div>','KINE 298, KINE 307, and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8105,2021,635,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/400/kine-490','<div class="desc"> <p>This seminar course examines a selected area of current topics in Kinesiology. It is the intent of this course to utilize an integrative approach to the advanced study of Kinesiology. Students will develop and write a comprehensive research paper in a subdiscipline of Kinesiology. Open to senior kinesiology majors with permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8107,2021,636,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/kine-kinesiology/400/kine-499','<div class="desc"> <p>Data collection, analysis write-up, and presentation of Honors thesis. May be repeated both semesters of senior year.</p> </div>','Permission of department ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8108,2021,228,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/100/latn-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Latin. Students will engage, from the beginning, with original texts from Virgil, Horace, Caesar, Cicero and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Romans, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8109,2021,639,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/100/latn-102','<div class="desc"> <p>Continuation of LATN 101 and reading and interpretation of an original text.</p> </div>','LATN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8111,2021,856,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/200/latn-201','<div class="desc"> <p>Advanced readings in Latin literature and/or philology in coordination with a classics course in ECLS (or another department affiliated with the classics program).</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8114,2021,1338,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-300','<div class="desc"> <p>The Romans, to a large extent, adopted the literary genres of the Greeks before them. In Roman hands, however, the genres of epic and tragedy evolved to reflect contemporary literary tastes and the emergence of Rome as the dominant power in the Mediterranean. In this course, we will consider the themes of war, love, and sacrifice in Latin literature by reading Vergil''s <em>Aeneid,</em> the little <em>Iliad</em> in Ovid''s <em>Metamorphoses,</em> and Seneca''s <em>Trojan Women</em>. Students will explore the differences between "Golden and Silver Age," Latin epic, and round out their examination of the course''s themes in the context of the tragic genre. No knowledge of Latin is needed (but is certainly welcome).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8115,2021,1705,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-320','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis -- the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. LATN 320 is the five unit course attached to CSLC 120. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8116,2021,1662,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-340','<div class="desc"> <p>Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near death experiences throughout the Mediterranean. While immensely entertaining and, at times ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in postÂ­classical literature, art, and film. Course meets with CSLC 140.</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8117,2021,1528,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-341','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. In this language intensive course we will read selections from Seneca''s <em>Epistulae ad Lucilium </em>as well as Horace''s <em>Satires</em>.</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8118,2021,2796,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-342','<div class="desc"> <p>This course offers students the opportunity to read, in the original Latin and in translation, texts by or about non-elite people in the Roman world. In so doing, it attempts to recover the largely forgotten perspectives, experiences, interests, voices, and cultures of non-elite people in the Roman world, that is, the entire Mediterranean from 133 B.C.E. to 476 C.E. Today, we usually see Roman history and culture from the perspective of Rome’s elites, because the bulk of the surviving texts were written by or for elites. We shall steer a different course, examining texts and material artifacts produced by, for, or about ordinary people. Topics include Roman childhood and the Roman family, kinship relations, mothering and motherhood, child-rearing practices, children’s experience, the death of kin and commemorative practices; the economic circumstances of ordinary Romans, the nature of work, the terms of lending and borrowing, the experiences and cultures of slave-holding and of enslavement; women’s roles as girl (<em>puella</em>), girlfriend (<em>amica</em>), wife (<em>matrona</em>), prostitute (<em>meretrix</em>), and witch (<em>venefica</em>); sex, sexuality, and dirty songs; the people’s entertainments, such as theater, games, gladiator shows, and popular literature; popular politics and the role of the crowd and common person in public life; the culture of soldiering and the experience of peoples at the borders of empire; popular religious phenomena and the appeal of prophets, priests, and holy men in such movements as Isis worship, Mithraism, and Christianity. The goal of the course is for students to emerge with a holistic understanding of the details of and scholarly theories about non-elite culture in the Roman world, and hence with a heightened ability to identify and critically analyze contemporary discourses about “low” versus “high” culture, which most often remain entirely implicit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8119,2021,2517,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-345','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we will also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic. In this 5-unit course we will be reading Lucretius in the original Latin, and will address the ways in which his poem''s semantic content, syntax, and literary form work with (or against) one another to produce that texture of Roman cultural significance that is the <em>de Rerum.</em></p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8120,2021,2571,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-346','<div class="desc"> <p>This interdisciplinary course, featuring ancient Roman texts in the original Latin, introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. These topics will be examined through close readings in the original Latin drawn from Cato the Elder, Cicero, Livy, Vitruvius, and others.</p> </div>','LATN 201 (or equivalent) and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8121,2021,2775,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-347','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> <p><span style="background-color: #ffffff; color: #212021;">Taught in conjunction with </span>CSLC 247<span style="background-color: #ffffff; color: #212021;">, but meeting for an additional section.</span></p> </div>','LATN 201 or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8122,2021,2830,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-348','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 B.C.E sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 B.C.E when he brought his army across the Rubicon river into Italy from Gaul. With Pompey gone, the republic was lost.<br/> <br/> Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as On the Republic and On the Laws, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators who sought to restore the old order assassinated Caesar in 44 B.C.E. They were, in turn, destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.<br/> <br/> Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise Discourses on Livy, and John Adams (the “American Cicero”), whose 1787 work Defence of the Constitutions of the United States of America owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>','Students must have taken LATN 201 or have permission of the instructor to enroll. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8123,2021,2706,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-382','<div class="desc"> <p>In this course we will trace one historic trajectory of what we today call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the Gospels of Christianity, the troubled Confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the Divine Comedy. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring and frustrating complexity.</p> <p>Taught in conjunction with CSLC 182, but meeting for an additional section, Latin 382 will allow students to encounter a number of Roman poets (Catullus, Horace, Tibullus, Ovid, Propertius) and writers (St. Augustine in particular) in their original language forms.</p> </div>','Latin 201, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8125,2021,640,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/latn-latin/300/latn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8130,2021,857,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ling-linguistics/300/ling-301','<div class="desc"> <p>This course is designed as a solid introduction to and overview of the field of linguistics. Students will explore a number of topics that are at the core of linguistics. We begin with a theoretical background in subfields such as syntax, morphology, phonology, and phonetics. Then we move to broader issues such as sociolinguistics, language acquisition, psycho/neurolinguistics, and historical linguistics. Not normally open to first-year students.</p> </div>','One year of a modern language or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8131,2021,1180,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ling-linguistics/300/ling-350','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','LING 301, COGS 101, PSYC 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8132,2021,2831,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ling-linguistics/300/ling-351','<div class="desc"> <p>This course aims to equip students with the understanding of how speech sounds in the world’s languages are produced via an introduction to <em>articulatory</em> and <em>acoustic phonetics</em>. Building on the basics learned in Ling 301, you will learn how speech sounds are articulated; how to describe, compare, and contrast speech sounds in different languages and dialects on the basis of articulatory and acoustic measures; and finally, why knowledge about speech sounds is important to a variety of careers and professions, from speech pathology to language teaching to voice-to-text technology.</p> </div>','LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8133,2021,1238,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ling-linguistics/300/ling-355','<div class="desc"> <p>This course provides an overview of the field of sociolinguistics. We will discuss language in its social context, and will examine how social and contextual factors influence language choice. Both quantitative methods, as well as qualitative methods, will be discussed.</p> </div>','LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8135,2021,1387,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ling-linguistics/300/ling-397','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8136,2021,3131,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/ling-linguistics/400/ling-497','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8137,2021,1179,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-101','<div class="desc"> <p>This interdisciplinary course will introduce students to sources, methods, and approaches in the transnational study of Latin American and US Latino communities. We will focus on the social and cultural interaction of indigenous European, African, and Asian peoples from the colonial period to the present using a variety of primary and secondary materials including films, literature, historical documents, visual arts material, culture, music, scholarly books, and essays. Field experiences in Los Angeles will supplement the course materials. Specific course topics will vary by instructor but may include: migration, mestizaje, indigenism, imperialism, dependency, nationalism, urbanization, popular culture, and social movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8138,2021,2632,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-102','<div class="desc"> <p class="sc-BodyText">This course will examine the diverse forms and social contexts of Latin American and Caribbean music, while exploring the ways that musical performance has been used to negotiate power relations in the social, political, and economic spheres since the Conquest. Focusing on musical genres and movements from Argentina, Brazil, Cuba, Haiti, Mexico, Peru, and Trinidad students will learn to recognize the techniques and instruments used in a wide array of traditional and contemporary styles, particularly those which have grown out of the hybridization of African, Middle Eastern, European, Asian, and Native American performance strategies. While knowledge of music theory and performance skills are not necessary, it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8139,2021,1663,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America, from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds, and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8140,2021,2343,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-151','<div class="desc"> <p>This course offers a survey of postcoloial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the nineteenth and twentieth centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the nineteenth century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race and the development of export agriculture. The second section introduces themes of the twentieth century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources including scholarly works, films, and primary sources to engage these topics and issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8142,2021,2633,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One CSP course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8143,2021,2344,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States, and to assess how these communities seek political empowerment, as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life, such as the economy, the state, and the cultural system, on the one hand, and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications, based on race, class, gender, national origin, and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8144,2021,1664,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-206','<div class="desc"> <p>Analysis of the English language development of listening speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction sheltered/SDAIE approaches English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8145,2021,2345,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) presidents either failed to act in accordance with the transitional justice movements sweeping Latin America or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased, rather than decreased, since its transition to democracy. This class will document why this is the case, as well as look into the various movements that have mobilized since the 1970''s to the present to demand human rights in Mexico.</p> </div>','DWA 101, POLS 101, or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8146,2021,2346,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8147,2021,1706,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-250','<div class="desc"> <p>This highly interactive seminar brings students from different identity groups together for informed, sustained, and respectful dialogue about “hot topics” in the lives of Latinxs in the U.S. There are three components to the course. Part 1 focuses on Dialogic Skill Building; Part 2 focuses on Power, Privilege, and Group Membership; and Part 3 focuses on specific Hot Issues (see below for specific topics). Course goals include a deeper intellectual and personal understanding of the structural implications of Latinx/Latin American identity in the U.S., honed ability to communicate across difference, and development of intergroup alliances. Seminars are co-facilitated by a faculty member and trained peers representing intersectional identities within Latinx culture. A semi-structured curriculum integrates readings, experiential activities, dialogue, and reflective writing. Next year’s topics include: Identity -- Who is Latinx? (phenotype, class, language, authenticity); (in)visibility and Representational Challenges (Beyond the Black-White binary, Media, ); Politics of Intersectionality and Simultaneity Across Contexts and Generations (Assimilation, Enculturation, Gender, Sexuality, and Religion); Educational Options for Self or Community (Curricular marginalization, Counterspaces or Balkinization); Political Resistance and Coalition Possibilities (Ideological tensions, Rebellious Lawyering, Work). Student demand will determine whether an Intragroup (all Latinx) Dialogue or an Intergroup (mixed race) Dialogue option will be offered.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8149,2021,2901,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8150,2021,2554,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-258','<div class="desc"> <p>This course seeks to engage you in the fundamental problems of twentieth century Mexican history and introduce analytical frameworks for studying cultural politics. The central theme will be how the state and grassroots society negotiated the course of the nation and its political culture since 1875. We will critically examine the production of the dominant historical narrative and develop alternative ones that can help us understand the differences in the historical experiences of subaltern groups, including women, indigenous people, and <em>campesinos </em>within the Porfirian, revolutionary, and post-revolutionary periods. We will examine what is cultural about politics and what is political about culture through an interdisciplinary format, perspective and organization drawing upon the fields of history, anthropology, literature, and visual studies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8151,2021,2598,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-260','<div class="desc"> Through analyses of literature, film, music, and graphic art we will explore how Latinos have represented their individual and collective experiences in the United States. In order to allow some depth of comparison, primary attention will be given to the creative works of Chicanos in Los Angeles and Puerto Ricans in New York. However, other national origin communities (such as Dominican, Salvadoran, Guatemalan, and Cuban) will be selectively incorporated in the course. </div>','Fall CSP Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8155,2021,2797,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-301','<div class="desc"> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.</p> <p> <br/> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written.</p> <p><br/> </p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8157,2021,1665,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-303','<div class="desc"> <p>The focus of this course is on the history, literature, and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works, as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works, while play attendance will keep our focus on these plays as performance. There is a ticket fee of $50 for the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8158,2021,2898,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-304','<div class="desc"> <p style="margin-top: 10px;">Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. </p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8159,2021,2599,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. To a lesser degree we will also examine Central American immigration from an international relations perspective.</p> </div>','LLAS 101, SOC 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8161,2021,2639,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing, especially, on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization; art forms; social structure; and religion in the colonial and modern periods; and considers native responses to contemporary issues, such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8162,2021,2555,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or POLS 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8163,2021,2692,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150, HIST 151, LLAS 101, UEP 101, or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8165,2021,2347,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-385','<div class="desc"> <p style="margin-left:0in; margin-right:0in">The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101, SOC 101, HIST 102, AMST 101, or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8167,2021,1386,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8168,2021,1125,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/llas-latino-a-latin-american-studies/400/llas-490','<div class="desc"> <p>In this course, students will write their senior theses on Latin America or Latino communities. Seminar meetings will focus on issues concerning research methods and will guide students through the steps of writing a substantial essay. Students will present their findings in a public forum at the end of the course. Open only to LLAS majors.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8170,2021,1529,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-110','<div class="desc"> <p>This 2-unit course focuses on the fundamental processes and tools involved in digital design for the media arts: color, resolution, image manipulation, compositing, typography, vector graphics, web/app design principles, project workflow, and output/finishing formats. Students will become familiar with the interfaces of essential software platforms, including Adobe Photoshop and Illustrator, and will apply concepts and techniques to various assignments. Open only to MAC majors and minors. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8171,2021,1530,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-143','<div class="desc"> <p>This 100-level gateway course introduces students to key concepts and methodologies for the critical analysis and interpretation of a broad range of media forms across the visual field - including film, television, social media, photography, games, advertising, etc. - and the cultural, historical, and ideological forces that govern them. Drawing from select case studies in media and visual culture, the course emphasizes critical reading, discussion, and writing, with forays into digital scholarship. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8172,2021,1666,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-145','<div class="desc"> <p><em>Born Digital</em>, <em>Growing Up Digital</em>, <em>Teaching Digital Natives</em>, <em>Understanding the Digital Generation</em> ... these are just some of the titles in a veritable explosion of guidebooks on how thinking, learning, and doing have changed in a world transformed by digital, networked, and social media. In this 100-level gateway course, we take a critical look at the theories and prophesies on the "Net Gen"; we explore and assess new digital possibilities for communicating, teaching, and learning; and we think critically, contextually, and historically about the ways in which new media forms and practices shape identity, community, sociality, creativity, privacy, civic engagement, and everyday life. Class projects will enable students to experiment with, and gain, practical experience applying a range of media 2.0 technologies to their own academic work. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8173,2021,1531,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-146','<div class="desc"> <p>This 100-level gateway course breaks down the aesthetic components of film and examines each element''s function in the production of meaning in a text. The course underscores the fact that cinema''s aesthetic language is not solely generated by Hollywood. It is a fluid system, highly contingent upon cultural, temporal, technological, and economic considerations. Selected international and alternative cinema movements will be examined for their enduring influences upon the global audiovisual aesthetic lexicon. Students will learn to connect formal analysis to cultural criticism and will engage with key disciplinary theories and writing methodologies. <strong>Students intending to major in Media Arts &amp; Culture must complete two gateway courses by the end of the sophomore year, with grades of C+ or better. Gateway courses are not required for the MAC minor. This course is not open to Juniors or Seniors. </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8175,2021,1667,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-210','<div class="desc"> <p>Motion graphics and motion design are becoming increasingly vital, creative, and technical capacities for digital media production. This two unit course focuses on the fundamental concepts, processes, and tools involved in motion design for the media arts: keyframe editing and interpolation, masking, effects, character rigging, camera movements, and titling. Students will become familiar with the interface of Adobe After Effects while exploring concepts of rhythm, space, and time, and will apply concepts and techniques to various assignments.</p> </div>','MAC 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8176,2021,1532,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-220','<div class="desc"> <p>This course focuses on theory, form, and practice of audiovisual, time-based storytelling for screens. Through a series of screenings, critical readings, creative writing exercises, and the crafting of short screenplays, students will become versed in the critical, political, and creative potentials of writing for screen cultures, including manipulation of time, space, and point of view, character development, and narrative theory. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8177,2021,1533,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-240','<div class="desc"> <p>This course builds upon the critical and historical grounding of MAC 100-level gateway courses, providing students with foundational media production skills and exposure to the wide-ranging creative possibilities of time-based media practices. Students will conceptually and practically explore historical and contemporary approaches to fictional, documentary, and experimental media through a series of production projects, each supplemented by a range of readings, exercises, technical workshops, guests, screenings, and critiques. Permission of instructor required. Not open to seniors.</p> </div>','MAC 143, MAC 145, or MAC 146 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8178,2021,2454,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-241','<div class="desc"> <p>In a digital moment where both the democratizing and totalitarian possibilities of media are unprecedented, the need to analyze and understand both the politics and <em>poetics</em> (the distinct audiovisual rhetorical strategies) of documentary media has never been more vital. This class combines readings, screenings, discussions, group exercises, and distinct forms of critical and professional writing to explore the evolving histories, theories, ethical questions, and creative modes of documentary. Together we will examine how documentary media can effect social change, expand the diversity of voices and stories that are seen and heard, and challenge each us to reimagine our fundamental conceptions of "truth" and "reality." </p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8179,2021,1707,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-242','<div class="desc"> <p>In our dynamic digital moment, the question, "What is a documentary?" can be answered with ever-increasing complexity. Works professing truth claims about our historical and present "realities" are just as much constructs as any fiction film, a realization that presents both creative opportunities and ethical responsibilities for documentary practitioners. This hands-on course will explore and develop a poetics of documentary, underscoring that the politics and meaning of documentary works come not simply through their content but through their aesthetic strategies and processes of production and distribution. A series of media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8180,2021,1534,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-244','<div class="desc"> <p>This intermediate topical course of varying emphases focuses on representations of difference, while underscoring the connections between race, class, gender, and sexual identity. Through screenings, and key texts from film and media studies, cultural studies, gender studies, and visual culture studies, students will learn critical methodologies for analyzing a range of media forms and the complex relationship between authors and spectators. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>The Female in Japanese Film and Media </strong></p> <p>The course will consider the role of the female in Japanese film in front of and behind the camera. In the current climate of the #metoo and #timesup campaigns and revelations of sexual harassment in the Hollywood film industry, where does the Japanese film industry stand? This course will look at Japanese cinematic history whose roots are embedded in the studio system in Kyoto and consider how the role of women in film has been shaped by a changing society’s values and norms. The contributions from Japanese female film directors such as the pioneers Sakane Tazuko and actress-director Tanaka Kinuyo to their contemporary counterparts such as award-winning Kawase Naomi, the pink films of Hamano Sachi, relationship driven films of Mishima Yukiko, to the fashionable flair of Ninagawa Mika. We will look at emerging female filmmakers such as Oda Kaori, Endo Maiko, and media artist Sputniko! who are using the format of the moving image to engage Japanese audiences in global issues. In addition to looking closely at works from female film directors, the course will examine tropes and representations of iconic actresses within Japanese cinematic history to appropriation of Japanese culture in pop music videos. <em>Additional Core Requirement Met: Regional Focus.</em></p> <p><strong>Cultures of Protest</strong></p> <p>The English word <em>protest</em>– “to declare publicly” – derives from a Latin verb meaning “to testify, give witness.” In this course we will explore a variety of films from different geopolitical regions and of different genres and different historical contexts that might be interpreted as speaking to all kinds of modalities of protest: protests against nationalisms, against ethnic cleansings, against xenophobia, racism, and homophobia, against national violence and against gender purity. We will engage with different understandings of the concept of protest and focus on its relation to migration, foreignness, national identity, racial, gender, and sexual politics, border politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations.</p> <p><strong>From Cyborgs to Siri: Gender, Technology and Media</strong></p> <p>In this course, we will examine the fembots, cyborgs, and female AIs imagined in film, television, and advertising, as well as the dialogue between these fictional creations and their real-life counterparts, from historical automata to the current development of robotic and virtual companions. How does techno-fantasy inform scientific reality, and vice versa, in the construction of these figures? What roles do we ask them to play in both realms? What might they reveal about our cultural hopes and fears around love, sex, and relationships? What social, cultural and historical conditions give rise to, and shape, their appearance? Why are they, simultaneously, so disturbing and fascinating for us? In answering these questions, we will examine issues around gender, sexuality, and race, while drawing from a wide range of critical discourses, including cyborg feminism, post-humanism, and afrofuturism. Screenings will include Metropolis (1927), Stepford Wives (1927), Ghost in the Shell (2003), Her (2013), and Ex Machina (2015).</p> </div>','None. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8181,2021,2678,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-245','<div class="desc"> <p>This practice based course focuses on a specific topic in media production. Students will explore the propensities and challenges of a particular production approach, model, technology, or aesthetic practice through the creation of a series of media projects. Classes will include screenings, readings, and discussion that situate these practices conceptually, ethically, and culturally but the emphasis is on hands-on project creation as a means of understanding the production topic at hand.</p> <p><strong>Exploring 360º Video and Immersive Installations</strong></p> <p>Do 360 video cameras, VR headsets, and immersive screen installations represent a paradigmatic change in production, artistic conception, and audience experience? This course will introduce students to the foundational methods, technology, aesthetic approaches, and cultural and ethical considerations of live-action immersive media creation for both VR headsets and video installations. Students will work in a collaborative environment to conceive and execute a series of projects using 360 video cameras and traditional digital video cameras. Projects will include narrative, documentary, and experimental approaches. Students will be encouraged to investigate how live-action 360 video and immersive installations differ from, and are aligned with, traditional screen-based media. No previous filmmaking experience is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8182,2021,1708,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-246','<div class="desc"> <strong>American Cinema (1970''s to the Present).</strong> A survey course on American independent cinema and Hollywood studio productions from the late 1970''s to the present. Topics include: the response of independent and experimental cinemas to Hollywood''s hegemony; the cultural significance of American cinema; the global success of American films and their impact upon production, stardom, distribution, and exhibition; the aesthetics of film image, sound, and narration; and the effects of new digital technologies on spectacle, and spectatorship. The course will draw upon Occidental''s location in Los Angeles as a source of research, screening, and programming opportunities. <br/> <br/> <strong>Classical and Post-Classical American Cinema (1930''s to 1960''s).</strong> A survey course on American independent cinema and Hollywood studio productions, from the emergence of sound cinema and the fortification of business models and generic conventions in the studio system, up through the social, political, and civil rumblings of the early 1960''s. Topics include: genre theory, gender, race, and class in American cinema and society, independent and experimental counter-cinemas operating outside the Hollywood model, censorship, and the evolution of film genres. The course will draw upon Occidental''s location in Los Angeles as a source of research, screening, and programming opportunities.<br/> <strong><br/> Modernity and the Rise of Cinematic Visuality.</strong> Many have argued that the history of modernity has been, above all, a history of visualization, changing the way we see. In this course, we will examine a diverse range of nineteenth and early twentieth century visual practices, technologies, and experiences including train rides, panoramas, shopping arcades, assembly lines, and amusement parks that helped shape the "modern observer" by altering both the perception and understanding of time and space, public and private, work and leisure, the normal and deviant, and the individual and collective. Through a combination of critical readings, screenings, and field trips, we will ask how such practices of looking not only influenced early cinematic form and content, but also how they continue to inflect postmodern media culture, from television to the internet. The course culminates in a 3D screening of HUGO (2011, Scorsese).<br/> <strong><br/> The Philosophy of Classical Hollywood Cinema.</strong> <p> This course will attempt a survey of current philosophical approaches to classical Hollywood film, beginning with Stanley Cavell’s The World Viewed: Reflections on the Ontology of Cinema (1971). This work initiated a new and flourishing sub-discipline within contemporary academic philosophy called film-philosophy. The central assumption within this body of inquiry is that film is (or can be) “philosophy in action.” In this course we will be returning to the source of this idea to read Cavell’s original work, as well as selections from his two subsequent books: Pursuits of Happiness: the Hollywood Comedy of Remarriage (1981) and Contesting Tears: The Hollywood Melodrama of the Unknown Woman (1996). We will then extend our inquiry to other writers inspired by Cavell (and reflections on later developments within Hollywood), such as Robert Pippin (writing on Film Noir), Stephen Mulhall (writing on the Alien series and other sci-fi), and William Rothman (writing on Hitchcock). Weekly screenings and discussions will be part of the course, as well as one or two field trips to Los Angeles archives. Cross-listed as PHIL 317.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8183,2021,1535,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-248','<div class="desc"> <p>A survey course on the global language of film and media. Screenings and readings will cover a range of national contexts, examining questions of national identity, national cinema, alternative cinema, Third cinema, experimental ethnography, diaspora, postcoloniality, globalization, and transnationality. The course will take advantage of the international and intercultural makeup of Los Angeles, as a means of exploring media and accessing practitioners who are working across national boundaries. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics fulfill distinct Core requirements. </strong></em></p> <p></p> <p><strong>Foreigners and Cinematic Border Crossings</strong></p> <p>What does it mean to be-placed-into-foreignness? To be marked as foreign? To inhabit this category and feel its weight? We know that certain bodies, or regions, are labeled as foreign, but also texts and images. “Foreign” is a sticky term – it sticks to the body of a human, or to a particular image or sound – and it marks it as something else, as something other than me, alien, some form of alterity. How do transnational cinema and media approach representations of foreignness? How do they engage questions of aesthetics, politics, and ethics? We will explore these questions while focusing on films and media that privilege transcultural encounters and border crossings in various global locations. <em>Additional Core Requirement Met: Global Connections.</em><br/> <br/> <strong>Transnational Cinemas: Borders, Walls, Difference</strong></p> <p>In film studies, the term “transnational” has opened up new ways of thinking about cinema, its production contexts, spectatorship, and ideological investments. We will explore different understandings of the concept of transnationality and focus on its relation to migration, foreignness, national identity, racial politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). We will screen a number of fascinating films and videos from multiple regions of the world. The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>African Film and Media</strong></p> <p>Africa has one of the largest film industries in the world. This course surveys significant film and media traditions within Africa along with their aesthetic, political, and cultural contexts. We will explore African film and video across a broad array of traditions, mediums, and historical periods including the griot, Yoruba theatre, colonial visual culture, independence and liberation films, counter-ethnography, the Négritude movement, Third Cinema, post-independence Francophone Art films, sub-Saharan Black African cinema, FESPACO, Anglophone Nollywood and Ghana popular video, and African new media. The goal is to focus on distinctly African film and film scholarship by critically examining the various conflicting traditions and methodologies of cross-cultural African film studies. This course will involve seminar-style discussions, presentations, extensive screenings (in and outside of class), guest lectures by African filmmakers and scholars, and critical writing. <em>Additional Core Requirement Met: Regional Focus</em>.</p> <p><strong>Transpacific Social Justice</strong></p> <p>This course will explore a variety of contemporary film and multimedia productions, with a focus on social justice issues across the transpacific. Topics discussed may include, but are not limited to: race, gender, and sexuality in a networked world; war and its aftermaths; labor rights; and digital media advocacy. What are the implications of multimedia technologies for social justice and democracy, especially in marginalized communities across the Pacific and their diasporas? Students will learn about emerging art and activist movements in Asia and the Pacific through a variety of screenings, readings and lectures. There will be a particular focus on materials coming from social justice movements such as documentary film, independent film, and activist art. We will review and analyze different perspectives, for example, a rising intersectional feminist movement in South Asia, sexual politics in East Asia, participatory videos created from migrants in Southeast Asia, to the student uprisings of Taiwan’s Sunflower Occupation and Hong Kong’s Umbrella Revolution and current protests. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8184,2021,1536,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-250','<div class="desc"> <p>This hybrid media theory and practice course directly engages the interrelationship between discursive and creative production. Classes will include screenings, lectures, discussion, and hands-on experiences in producing and collaborating on digital media projects. Topics courses may be repeated with a different topic for credit.</p> <p><strong>Media Activism through Participatory Video</strong></p> <p>This is a combined theory and practice course that will engage students in looking critically at what participation means when working with members of a community. In participatory video, who holds the camera often determines who holds the power. By gaining an understanding of documentary film and ethics, we will question the relationship between filmmaker and subject. Students will learn about working with community, developing relationships and trust, and how to collaborate using participatory methods. Through readings, screenings, and guest lectures, the course will explore the potential of using digital media tools to engage communities in media activism. Students will be introduced to a variety of methodologies that will lead up to a final collaborative project that will engage a local community in participatory video. This final project will result in a series of public workshops, screenings, and exhibition.</p> <p><strong>Visual Design and Composition for Media</strong></p> <p>This theory/practice course introduces and deepens student fluency in design methods for communicating concepts and stories visually using cinematic and emerging media formats. Students will closely examine current and historical examples of how formal visual design components communicate non-verbal content and information - composition, color, value, line, shape, depth, visual rhythm, camera movement, and more. In addition to critical reflection, students will integrate and demonstrate their learning through the creation of still photographic images, short cinematic sketches, and visual ideation for emerging media. The course also considers how to research, design, and communicate an overall visual structure plan for a project, and how the visual structure relates to and supports other narrative or non-narrative structures. Finally, students will consider how these principles are engaged, extended, and challenged through emerging media forms.</p> <p><strong>The Video Essay</strong></p> <p>In this theory/practice course, we will explore what it means to “think and write with video” about film, media, and popular culture. Readings, screenings, and class discussions will engage the history of the video essay, including its filmic precursor, “the essay film”; debates about what makes a video essay scholarly; and a variety of formal, aesthetic, and rhetorical strategies for communicating ideas through moving image and sound. Student work will involve a series of hands-on assignments building towards a scholarly video essay that can be submitted to an on-line journal.</p> <p><strong>Game Design Workshop</strong></p> <p>This course will introduce students to the foundational concepts of game design through the practice of creating video games. Video games are products of culture, and this course approaches video games as media artifacts worthy of analysis, critical design, and purpose-focused production. In this course, students will learn digital tools for video game creation, such as an introductory-level game engine, basic programming skills, and audiovisual design. Students will also question and critique theories and foundational practices of game design. Readings, lectures, and in-class exercises will explore the expressive and political possibilities of games as cultural productions. No previous programming or game design experience is required.</p> <p><strong>Reimagining Social Media Practice</strong></p> <p>This course seeks to dismantle conceptions of the internet and social media as distribution platforms and instead critically and creatively reimagines them as a production medium, one capable of producing unprecedented media content, communities, and cultural interventions. Students will engage with theories of social media and online communities by engaging with projects that explore these issues from a practical hands-on perspective. Students will become social media and online content creators to accomplish three main goals: become literate in the social media content creation process, understand current research and theories on social media and online communities, and transgressively examine the implications of a culture imbued with social media and online content. Topics to be explored in the class include influencer culture, cyberbullying, the Alt Right, strategy, public crises, identity communities, election hacking, fake news, and psychological and social implications of social media use.</p> <p><strong>Digital Tools for Radical Change</strong></p> <p>This theory and practice course takes a critical look at the use of media communications and social media in resisting oppression and organizing for social change. Readings, class discussions, and creative assignments will engage a variety of case studies in which digital and social media were used to shape debates, advance causes, build networks, and encourage civic participation, including #BlackLivesMatter, @realdonaldtrump, and the ACLU''s Mobile Justice app. Throughout, emphasis will be placed on the art of communication as the single most important aspect of effective community organizing, activism, and advocacy. Students will put theory into practice by conceptualizing, executing, and evaluating a digital advocacy campaign via social media. Their work will be supported by skills-based workshops and class visits with Los Angeles media activists and social media influencers, which will help equip them with practical tools and insight into digital and creative practices for achieving specific goals. This course is being linked to a Cinematheque series and will include a few mandatory screenings on Thursday nights. </p> <p><strong>Remix Media and Culture Jamming</strong></p> <p><em>What is Remix media?</em> Remixing, reusing, and reworking separate media elements from different sources to produce an entirely new work with a different meaning. <em>What is Culture Jamming? </em>Coined by Oxy alum ''82 Marc Dery, "culture jamming" is an anti-consumerist tactic used to disrupt or subvert dominant media culture, including (but not limited to) corporate advertising. This theory/practice course takes a critical look at the history of remix culture—from Dada to Machinima—along with the gamut of aesthetic, political, and social concerns addressed by remix artists and musicians and the reception (and even appropriation) of their work by the corporate entertainment industry. Students will put theory into practice by producing their own remix projects including a <em>subvertisement </em>and remix video. We will also explore issues around copyright and fair use in the sampling of both commercial and independently-produced works.</p> <p><strong>Public Media and Alternative Exhibition Strategies </strong></p> <p>For over 25 years Anne Bray and her Los Angeles organization FREEWAVES have created public media art events that bring diverse audiences and independent media artists together in dialogue on current issues in nontraditional, community-focused exhibition contexts. This hands-on course will engage students in theoretically and practically exploring past precedents and future possibilities for innovative and people centered media curation and exhibition. Students will work with Bray to conceptualize and realize alternative public media programming interventions on campus, in Los Angeles, and online, examining critical questions of space/venue, audience/community, and outcome/social engagement.</p> <p><strong>Mockumentary</strong></p> <p>This hybrid course blends theory, history, and practice to introduce students to the hands-on technical skills in mockumentary film production. Simultaneous to crafting your own video works, students will investigate the longstanding transnational and political history of mockumentary ranging from Buñuel to Borat. This analysis of mockumentary also proves invaluable in revealing, denaturalizing, and inspiring many of the conventions of documentary realism. Far from being polemical against documentary, this course not only examines how mockumentary can expose the lies and fakery already at work in claims to objectivity but also highlights the authenticity of film artifice.</p> <p><strong>Media &amp; Social Movements in Los Angeles</strong></p> <p>This theory/practice course focuses on the relationship between media and social justice struggles in the greater Los Angeles region. Readings, class discussions, and creative assignments will address the use of media tools as a form of local and global resistance against various forms of economic, racial, sexual and gender oppression. Students will learn about the theoretical and material tensions between the global political economy and local grassroots media movements, ranging from Asian American video collectives of the 1970s to the Los Angeles School of Black Filmmakers (a.k.a. L.A. Rebellion film movement) of the 1980s. In the latter half of the semester, we will examine contemporary sites of media activism online, including but not limited to #blacklivesmatter, QWOCMAP, and the Asian American Oral History project. Weekly labs will provide opportunities to explore various media forms and strategies in order to critically analyze why certain platforms have emerged within different movements and what political possibilities still resonate. While labs will focus on audiovisual production and social media, there will be room to experiment with other forms of media resistance including ‘zine-making, comic books, and musical performance (e.g. critical karaoke, flash mobs, etc.). We will be joined throughout the semester by media activists and local community organizers, who will share their perspectives on contemporary struggles and, at times, lead skills-based workshops. The course will culminate in a final project in which students conceptualize and begin to execute a media campaign with a Los Angeles-based community organization. <em>Additional Core Requirement Met: United States Diversity</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8185,2021,1709,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with what is known as the "LA Rebellion," a moment of a radical reconceptualization of filmmaking, fostered by black students during their studies at the UCLA film school, and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasion devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include <em>Selma, Fruitvale Station, Daughters of the Dust, Lemonade, Pariah, Bush Mama, Do the Right Thing, and An Oversimplification of Her Beauty.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8186,2021,2455,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-255','<div class="desc"> <p>This course examines the history, theory, and practice of integrating time-based media into three-dimensional space. This is a theory/practice course: students will study the history of video and audio installation and attendant theories around interactivity, virtuality, and site specificity, while experimenting with different methods of troubling the passive relationship of viewer to screen in traditional cinema. Through hands-on exercises, students will develop sensitivity to three-dimensional space, explore the relationship of the human body to aural and visual environments, and create a series of linear and non-linear narratives that take into account viewers in motion. The class will culminate in the production of a media object, and/or installation, that demonstrates a careful consideration of form and content in relation to space.</p> </div>','MAC 140 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8187,2021,2348,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-260','<div class="desc"> <p>This intermediate topical course addresses new and evolving issues around digital technologies and networked publics, examining their social, cultural, political, and global ramifications both on- and off-line. Coursework will engage digital media theory and scholarship. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>Critical Game Studies: Aesthetics and Politics </strong></p> <p>Are video games addictive? Does video game violence affect people in RL (real life)? Are video games art? Can video games change the world? Even as video games have emerged as a multi-billion dollar media industry, how we discuss them remains contentious. Critics disagree over their status as a “serious” mode of artistic expression, along with their place in the “culture wars” that have shaped the political life of the United States and the world. This course provides students with the intellectual framework and critical vocabulary to examine video games as media texts via aesthetics: the value of gameplay experiences and how we fit them into our lives. How do we play, and why? The course will also address questions of politics: how can games shape, and how are they shaped by, the current of public life? Who gets to play, particularly along the lines of race, gender, sexuality, and class? Live and recorded gameplay demonstrations will provide students with the material for criticism and inquiry, alongside contemporary critical games writing, which will serve as models for student writing projects. Participants do not need previous experience with games or computers, but only a willingness to engage with games and gameplay within a critical context.</p> <p><strong>Women Making Moves - Women’s Migration and Media </strong></p> <p>The course will apply a theoretical and practical framework to facilitate an understanding of gendered migration patterns within Asia with a focus on Japan, Hong Kong, Taiwan and the Asian diaspora. This course will be designed to encourage students to critically engage in understanding global migration flows and trends, but to also look closer at more personal narratives of migration. We will discuss forced and voluntary migration, issues of sex work and the emotional labor industry, the crossing of borders, and what it means to belong. The thematic focus will be on the feminization of migration, the monetization of the migrant worker’s body, and looking at how feminist activism is perceived within an Asian context. Students will collaborate on a visual research project that examines themes of migration and how it impacts their daily lives. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>The Art and Politics of Virtual Reality</strong></p> <p>Recent years have seen an explosion in consumer-grade virtual reality (VR) technologies — devices like the HTC Vive, PlayStation VR, Oculus Rift, and Samsung Gear VR have brought a wealth of new experiences to audiences and users, both inside and outside their homes. The new wave of VR content and hardware may feel unprecedented; in fact, the history of VR begins over a century ago. This course will examine “reality” and the “virtual”, two long-contested terms, through the lenses of history, culture, embodiment, and space. Students will walk the boundaries of “virtual reality” through readings, screenings, workshops, and VR experiences. Through this work, students will enter the discourse surrounding VR, where they will struggle with the complicated political questions that surround VR as an art form: Who gets to define what is ‘real’ and what is not? How (and for whom) is something ‘virtual’? What kinds of rules, procedures, laws, and people should govern these strange spaces and places we call “virtual reality”? And how can VR be used not simply as a vehicle for entertainment or escape, but also a space for cultural questioning, activism, and social change? This course is connected to the Oxy Cinematheque Series that will occur during select evening course sessions.</p> <p><strong>Introduction to Game Studies and Culture</strong></p> <p>Games are changing how we create, mediate, and understand our world. This course introduces students to the interdisciplinary field of game studies with a media studies and design focus. Students will read research, play games, analyze games, and think through game design. Students will also examine issues facing gaming culture. A survey of subjects will describe the foundational theories of the field, identities and game culture, and implications/effects of gameplay. Topics to be explored include disability, education and games, cheating, sexuality and games, narratives, addiction, news games, and violence.</p> <p><strong>Who Owns the Internet?</strong></p> <p>This course takes a historical, critical, and experiential approach to the competing sets of interests that have struggled over control of the internet since its inception. These players - military, academic, corporate, activist, regulatory, user, etc. - will be explored through sets of readings, screenings, field trips, and hands-on workshops. Central to our inquiry will be questions of infrastructure, surveillance, and resistance, as they mark out the terrain, on which digital culture thrives, and, through which, major actors exert their influence. Students will have the opportunity to both learn about digital cultures and work in digital modes in this course, with hands on components emphasizing geo-spatial analysis, multimedia presentation, social media engagement, and webmaking.</p> </div>','none ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8188,2021,2832,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-270','<div class="desc"> <p>This course explores emerging methods of narrative design in relationship to worldbuilding. Worldbuilding refers to designing a complex integrated system with many moving parts such as characters, settings, myths, rules, artifacts – often a whole system of a society and culture. These design methods are used throughout media forms ranging from narrative writing, filmmaking, theater, architecture, mobile apps, video games, and virtual reality, to the integrated use of multiple forms using transmedia storytelling. Students will create short projects that investigate relationships between the design of a world and the storytelling possibilities that emerge from and are embedded within it, using both analog and digital methods. Students will experiment with methods and concepts such as non-linear storytelling, interactivity, experience design, transmedia, the poetics of space, and other relevant topics. Readings and short screenings will contextualize hands-on-work within larger historical and cultural contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8189,2021,2902,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8190,2021,2456,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-295','<div class="desc"> <p>The study of film and media has involved disciplinary and interdisciplinary approaches for about half a century. This intermediate topical course of varying emphases studies the key critical terms, issues, and debates in popular media cultural study, including genre study, in relation to specific topics. Readings of film and media examples illustrate how different theories or perspectives can be applied to contemporary pop culture.</p> <p><strong>Audiences and Spectators</strong></p> <p>Media is not only enjoyed by solitary viewers, but also by communities of people who come together to celebrate their love of culture. Across the 20th and 21st centuries, media fans have formed clubs, written amateur publications, altered their appearances, and made parodies of their favorite movies and TV shows as ways to express their fandom. This course will explore how audiences have taken pleasure in film, television, and contemporary digital media. Students will examine moving images in a variety of technological formats and exhibition contexts to study how communities of viewers have developed vibrant fan cultures around popular media. Students will also learn how media spectatorship has been structured by racial segregation, class-based accessibility, and other vectors of social inequity. Course screenings will include: <em>The Last Picture Show</em>; <em>Goodbye, Dragon Inn</em>; <em>The Watermelon Woman</em>; and <em>Dawson City: Frozen Time;</em> in addition to user-generated content on platforms such as YouTube, Vine, and TikTok.</p> <p><strong>Media and Your Body</strong></p> <p>Media forms require us to be spectators, audiences, and increasingly, users and participants, in ways that distinctly implicate and impact our bodies and identities. The course examines the nature of bodies, spaces, and materiality in media, specifically examining prominent theories and analyses that illuminate the nature of media as it exists off of the screen. The course will survey how we interact with media in different spaces and how our bodies form a part of the media experience. Specific topics include mobile games, humor and riffing with movies, participatory media, materialism, haptics, television spaces in the home and beyond, disability media studies, performing sexuality, and mental illness and video games. Assignments will engage students in practicing the theories they learn in class.</p> <p><strong>Genre in Contemporary Film, TV, and Digital Media</strong></p> <p>Genre films were part of Classic Hollywood, but genres started changing in interesting ways as media industries evolved after World War II, with the introduction of television, new technologies that enabled shooting on location or new opportunities with color film, the rise of drive-in movie theaters, and indie or exploitation filmmaking. We will study the shift from classic genre films and theory to hybrid genres and genre revisionism in film/media movements spearheaded by people of color, feminists, and LGBT communities, as well as studios. The focus in the class is on genre theory studied through historical and technological shifts in media production. Screenings will introduce a range of genres, from classic films like the Western and noir to more recent genres like road films, television melodramas, and war video games.</p> <p><strong>Imagining War: Genre on Screen and Battlefield</strong></p> <p>The war film has arguably been one of the most consistent and popular elements of cinema''s history. It was a component of film from its beginnings and is now a regular mainstay amongst Hollywood blockbusters. It has also undergone several political revisions and technological shifts in media production, distribution and exhibition, making it ideally suited to study the theory and history of genre. Importantly, this course will not only look at how war figures in film, but how film also profoundly effects and configures war. Entertainment and war are the United States'' primary exports. Militarism and the Hollywood studio system have had a long and deadly interdependence. By conceiving of the viewing screen as an extension of the battlefield (and vice versa), this course will look at the profound social and political implications of the classic genre system. We will do this by examining such films as <em>Apocalypse Now, The Deer Hunter, Hiroshima Mon Amour, Battle of Algiers, Black Hawk Down, Kandahar, Night and Fog, The Hurt Locker. Das Boot, Saving Private Ryan, All Quiet on the Western Front, Dr. Strangelove, Inglourious Basterds, Birth of a Nation, Rambo, MASH</em>, as well as a host of television shows, websites, and video games</p> <p><strong>The Western: From Colonialism to Gaming</strong></p> <p>This course will primarily explore the classic Hollywood genre system through a detailed look at "The Western." However, before looking at how genre operates within cinema, we take a broad historical and theoretical examination of genre within literary studies, critical theory, Wild West shows, philosophy, travel literature, ethnographic photography, and cultural studies. The aim is to critically examine a wide array of generic conventions within "The Western" film, while simultaneously situating these conventions within the broader historical and ideological context of European colonization of North America. Particular attention will be placed on the role of racial and gender performances within "The Western" genre as both a founding American myth and a component of the Hollywood film system. We will analyze both the classic Western as well as revisionist films. Additionally, we will investigate how the genre transforms as it moves into other media, including fine art, television, gaming, and other digital contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8192,2021,1710,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-320','<div class="desc"> This course emphasizes the advanced design and writing of long-form narratives for various audiovisual time-based media forms. Through a combination of screenings, critical readings, and creative exercises, students will develop a treatment for a long-form narrative screen work and commence writing scenes for its first act. </div>','MAC 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8193,2021,1711,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-355','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors in the Media Production Concentration. It provides advanced study and hands-on experience in the ideation and production of digital media projects across a range of fictional, documentary, and experimental modes. Students engage in a combination of readings, screenings, technical workshops, and collaborative media production projects to prepare them for the Media Production Senior Comprehensives experience. This class is only open to junior MAC majors in the Media Production Concentration.<br/> </p> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8194,2021,1712,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-390','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors. Fulfilling the College’s Second-Stage Writing Requirement, this is a research-driven course which brings together all junior majors, regardless of the intended form of their senior comprehensives project, to read, watch, write, debate, and produce self-directed research, laying the groundwork for their senior year comprehensives projects. This class is only open to junior MAC majors. </p> </div>','Two gateway classes (from MAC 143, MAC 145, MAC 146) must be completed with grades of C+ or better. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8197,2021,1538,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-490','<div class="desc"> <p></p> <p>Advanced year-long pro-seminar (seniors enroll for 2 units in the fall, and again for 2 units in the spring) designed to provide guidance and intellectual community around the completion of a Critical Media comprehensives project. This class is only open to senior MAC majors in the Critical Media Concentration.</p> <p></p> </div>','MAC 390 and two courses from MAC 241, 244, 246, 248, 250, 252, 260, 295 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8198,2021,1539,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-491','<div class="desc"> <p>Advanced fall-semester course (4 units) designed for the collaborative development and photography of Media Production comprehensive projects. Media Production seniors will then enroll in the spring-semester MAC 492 Advanced Editing class (2 units) to scaffold post-production. This class is only open to senior MAC majors in the Media Production Concentration.</p> </div>','MAC 355, MAC 390, and if making a fiction project MAC 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8199,2021,1713,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-492','<div class="desc"> <p>This course provides technical training to Media Production comprehensives seniors on a range of post-production software platforms, best practices in sound and picture editing, and skills in post-production finishing/project delivery workflow. Course assignments and deadlines scaffold the completion of Media Production senior comprehensives projects. The course also provides professionalization tools, training students in development and production of media portfolio materials. This class is only open to senior MAC majors in the Media Production Concentration.</p> </div>','MAC 491 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8202,2021,229,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-105','<div class="desc"> <p>This is a topics course for students who would like to take a mathematics course that does not require taking any prior course in college-level mathematics. <em>Not open to seniors.</em><br/> <br/> <strong>Digital Security</strong></p> <p>In this course we will explore the world of digital security and the math that goes into keeping your information safe. Topics will include cryptography, hash functions, blockchain, and bitcoin.</p> <p><strong>Mathematical Thinking</strong></p> <p>Introduction to mathematical thinking. Investigation of mathematical patterns in counting, reasoning, motion and change, shape, symmetry, and position.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8203,2021,230,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-108','<div class="desc"> <p>The first of a two course sequence enriching the material in Calculus 1 with additional study of elementary functions, algebra, trigonometry, graphing, and mathematical expression. Weekly lab.</p> </div>','Calculus Placement Exam ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8204,2021,642,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-109','<div class="desc"> <p>Continuation of MATH 108. This course satisfies Calculus 1 prerequisites for subsequent courses. Weekly lab.</p> </div>','MATH 108 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8205,2021,232,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-110','<div class="desc"> <p>This course is a traditional first course in calculus covering basic differential calculus. Topics include limits, continuity, differentiation, differentiation rules, as well as applications to the natural and social sciences including optimization. Click here for a more detailed topics list. Weekly lab required.</p> </div>','Calculus Placement Exam ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8206,2021,234,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-114','<div class="desc"> <p>This course is a more in-depth version of Mathematics 110. Intended for students interested in more mathematical rigor; recommended for students who expect to take mathematics courses beyond Calculus. It satisfies Calculus 1 prerequisites for subsequent courses. Weekly lab.<br/> <em></em></p> </div>','Math Placement Examination ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8207,2021,236,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-120','<div class="desc"> <p>This is a standard second-semester calculus course. The topics will include integration, methods of evaluating integrals, sequences, series, and Taylor series. Applications to the natural and social sciences will be included. Weekly lab required.</p> </div>','MATH 109, MATH 110, or MATH 114 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8208,2021,238,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-128','<div class="desc"> <p>A one-semester course focusing on infinite sequences and series including power series and Taylor series. More advanced topics will be chosen by the professor which may include: techniques for solving differential equations mathematical modeling, Fourier Series, the Laplace Transform, and the Fourier Transform. The course assumes mastery of the basic skills, particularly integration techniques and differentiation rules from the successful completion of Advanced Placement (AB) Calculus. This course satisfies Calculus 1 and Calculus 2 prerequisites for subsequent courses. Weekly lab.</p> </div>','Permission of instructor or AP Calculus AB score of 4 or 5 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8209,2021,242,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-150','<div class="desc"> <p>An introductory course in statistics, emphasizing modern techniques of data analysis. Exploratory data analysis and graphical methods; random variables, statistical distributions, and linear models; classical, robust, and nonparametric methods for estimation and hypothesis testing; introduction to modern multivariate methods. Students will make significant use of a computer application specifically designed for data exploration. The course is strongly recommended for students who are going to use graphical techniques and statistics for research in their fields. Weekly lab.</p> </div>','A Calculus 1 course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8210,2021,243,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-160','<div class="desc"> <p>Formal and informal techniques for problem-solving developed by working on an intriguing collection of puzzles and problems which go beyond those encountered in the usual curriculum. These include problems which can be posed in elementary, mathematical, or logical terms, but which require strategy and ingenuity to solve.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8211,2021,948,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-186','<div class="desc"> <p>This course treats network and graphical models arising especially in biological and cognitive sciences. Methods include networks, graphs, and matrices; probability, conditional probability, and Markov chains; discrete-time dynamics and recurrent neural networks; Bayesian statistical inference on graphical models; and optimization on graphs, including dynamic programming. In the computing laboratory component (a separately-scheduled 1.5 hour session), students will learn to use MATLAB to build and analyze models. Students will complete projects in each major area of the course. Calculus is not a pre-requisite. While open to all students this course is intended as an alternative to calculus as a first course in college-level mathematics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8212,2021,858,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/100/math-195','<div class="desc"> <p>Intensive study in an area of mathematics of the student''s choosing under the direct supervision of a member of the faculty.</p> </div>','Permission of the supervising instructor. May be repeated once for credit ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8214,2021,244,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/200/math-201','<div class="desc"> <p>This seminar course is a writing-intensive Community Based Learning course designed to expose students to the complicated ways in which mathematics affects the community. The CBL component of this course involves tutoring and mathematics assistance at Franklin High School in nearby Highland Park. The seminar component involves meeting weekly with processing discussions and discussion of readings. Topics will include the teaching and learning of mathematics, as well as the role of mathematics in individuals'' lives and their community. May be taken twice for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8215,2021,245,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/200/math-210','<div class="desc"> <p>The language of sets and logic, including propositional and predicate calculus. Formal and informal proofs using truth tables, formal rules of inference, and mathematical induction. Congruences and modular arithmetic. Elementary counting techniques. Abstract relations including equivalence relations and orders.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8216,2021,246,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/200/math-212','<div class="desc"> <p>Calculus of functions of several variables, parametric curves and surfaces, and vector fields in 2- and 3-space with applications. Vectors, graphs, contour plots. Differentiation with application to optimization. Lagrange multipliers. Multiple and iterated integrals change of variable, and the Jacobian. Line and surface integrals. Vector analysis, Green''s, Gauss'', and Stokes'' Theorems. Applications to physics economics chemistry and mathematics.</p> </div>','A Calculus 2 course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8217,2021,247,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/200/math-214','<div class="desc"> <p>Introduction to basic concepts of linear algebra through the study of linear algebraic systems and matrix algebra. Topics include: an introduction to planes and lines, vector operations, subspaces, Gaussian elimination, linear independence, invertibility of matrices, orthogonality matrix operations, eigenvalues, and eigenspaces. The course stresses definitions and mathematical proof.</p> </div>','A Calculus 2 course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8218,2021,1181,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/200/math-295','<div class="desc"> <p>Topics in mathematics selected largely by student interest and faculty agreement.</p> </div>','A Calculus 2 course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8220,2021,644,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-300','<div class="desc"> <p>This course is designed for mathematics majors to satisfy college-wide degree requirements and to demonstrate readiness for advancement in the major. The course includes preparation for and implementation of the Comprehensive Examination as well as completion of the Second Stage Writing Requirement. It emphasizes problem-solving, clear written expression, and oral communication in mathematics. <strong>Restricted to mathematics majors with at least junior standing.</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8221,2021,248,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-310','<div class="desc"> <p>A beginning course in advanced calculus and real analysis. Properties of the real number system, sequences and series of real numbers, the Heine-Borel and Bolzano-Weierstrass Theorems, continuity and uniform continuity sequences, and series of functions.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8222,2021,645,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-312','<div class="desc"> <p>The differential and integral calculus of complex-valued functions of a complex variable, emphasizing geometry and applications. The complex number system, analytic functions and the Cauchy-Riemann equations, elementary functions and conformal mappings, contour integration, Taylor and Laurent series, function theory. Applications to physics, engineering, and real analysis.</p> </div>','MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8223,2021,949,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-320','<div class="desc"> <p>A first course in abstract algebra. Topics will be chosen from group theory (basic axioms and theorems concerning subgroups, cosets, normal subgroups, group homomorphisms), ring theory (basic axioms and theorems concerning subrings, ideals, ring homomorphisms, quotient rings), and field theory.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8224,2021,646,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-322','<div class="desc"> <p>Classical theory of numbers from ancient to modern. Prime numbers and factorization. Divisors, arithmetic functions, linear and quadratic congruences. Diophantine problems including the Fermat conjecture. Factoring methods.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8225,2021,249,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-330','<div class="desc"> <p>Standard methods of calculus are used to study probability: sample spaces, random variables, distribution theory, estimating unknown parameters of distributions. Various applications to real life problems will be discussed. Moment-generating functions and other techniques to calculate moments and characterize distributions. Probabilistic inequalities and the central limit theorem. Point estimators and unbiasedness.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8226,2021,647,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-332','<div class="desc"> <p>Theory and applications of statistical inference. Both Bayesian and classical parametric methods are considered. Point and interval estimation, hypothesis testing. Limit theorems and their use in approximation, maximum likelihood estimation, and the generalized likelihood ratio test. Introduction to linear models, nonparametric methods, and decision theory.</p> </div>','MATH 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8227,2021,1388,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-340','<div class="desc"> <p>This course will focus on theoretical qualitative and quantitative analyses of ordinary differential equations, from a modern perspective, using analytical, graphical, and numerical points of view. Topics can include: first-order linear and nonlinear differential equations, first order linear systems, second-order linear differential equations, autonomous differential equations and their bifurcations boundary value, problems solutions using infinite series, Laplace transforms, and various numerical approximation techniques.</p> </div>','MATH 212 and MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8228,2021,648,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-342','<div class="desc"> <p>An introduction to the study of partial differential equations. This course will include the study of Fourier series; the separation of variables methods; and specifically, the wave, heat, and Laplace''s equations, as well as other elementary topics is PDEs. Numerical approximation techniques and applications to specific topics such as traffic flow, dispersive waves, or other areas may be included. Given in alternate years.</p> </div>','MATH 212, MATH 214, and MATH 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8230,2021,1023,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-352','<div class="desc"> <p>The logical foundation of the notion of a computable function underlying the workings of modern computers. Representation of the informal mathematical idea of calculability by canonical proxies: "general recursive functions," "Turing computable functions." Discussion of Church''s Thesis ,which asserts the adequacy of these representations. Survey of decidable and undecidable problems.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8231,2021,950,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-354','<div class="desc"> <p>Cantor''s naïve theory of sets and equinumerosity. Paradoxes and axiomatic set theory. Finite and infinite cardinal numbers, fixed point theory, applications to computer science. Well orderings, transfinite induction and recursion, the Axiom of Choice and its consequences, ordinal numbers, and the cumulative hierarchy of sets. Discussion of the Continuum Hypothesis and its relation to models of set theory.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8232,2021,1182,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-360','<div class="desc"> <p>Axiomatic development of Euclidian and non-Euclidian geometries, including neutral and hyperbolic geometries, and possibly brief introductions to elliptic and projective geometries. The course will emphasize a rigorous and axiomatic approach to geometry and consequences of Euclid''s Parallel Postulate and its negations.</p> </div>','MATH 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8233,2021,859,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-362','<div class="desc"> <p>General topology studies those properties (such as connectedness and compactness) which are preserved by continuous mappings. A disk and a solid square are topologically equivalent; so are a doughnut and a coffee cup; but a disk is different from a doughnut. This course enables you to construct your own proofs and counterexamples while getting to know the basic concepts behind modern mathematics.</p> </div>','MATH 210 and MATH 212 or MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8234,2021,251,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-370','<div class="desc"> <p>This is a first course in studying numerical techniques in solving a variety of problems in mathematics using computer algorithms. Topics can include: methods for approximating solutions to algebraic equations, iterative methods for linear and nonlinear systems, interpolation and approximation, theory numerical integration, explicit and implicit methods for solving initial value problems, and boundary value problems. Error, estimation, stability, and performance are themes throughout. Students will be expected to be able to execute standard algorithms using a computer programming language by the end of the course.</p> </div>','MATH 212 and MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8235,2021,951,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-372','<div class="desc"> <p>Optimal decision-making and modeling of deterministic and stochastic systems. Different systems of constraints lead to different methods. Linear integer dynamic programming and combinatorial algorithms. Practical problems from economics and game theory. Inventory strategies and stochastic models are analyzed by queuing theory.</p> </div>','MATH 210 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8236,2021,952,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-380','<div class="desc"> <p>Investigation of the existence and classification of arrangements. Topics to include: principles of enumeration, inclusion-exclusion, the pigeon-hole principle, Ramsey theory, generating functions, special counting sequences, and introductory graph theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8237,2021,1075,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-382','<div class="desc"> <p>Graph Theory is a beautiful area of mathematics with many applications. It is used in computer science, biology, urban planning, and many other contexts. Like other areas of discrete mathematics, Graph Theory has the property that the problems are often quite approachable and understandable. Sometimes the solutions to Graph Theory problems can be complex and often require clever arguments, thus the subject is quite pleasing to study. This class will build a solid foundation in Graph Theory for the students. Possible topics are: graph isomorphisms, coverings, and colorings; independence number, clique number, connectivity, network flows, and matching theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8238,2021,1340,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-392','<div class="desc"> <p>This course is intended to introduce students to common models used in biology. A variety of models, in terms of both biology and mathematics, will be covered. Biological topics include: action potential, generation genetic spread, cell motion, and pattern formation and circulation. These topics span a range of mathematical models, as well as including finite difference equations, and differential equations both linear and non-linear. The focus will be on model analysis and the translation between the mathematical language and the biological meaning. Such analysis will be done both quantitatively and qualitatively. Towards this end, topics seen in previous mathematical courses such as eigenvalues, phase portraits, and stability will be revisited. Relevant biology will be presented with each model. The course will be project based.</p> </div>','MATH 212 and MATH 214 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8239,2021,252,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-395','<div class="desc"> <p>Special topics in advanced mathematics selected largely by student interest and faculty agreement. May be repeated for credit. </p> <p style="color: #000000;"><strong>Real Analysis II</strong></p> <p style="color: #000000;">This is a second course in real analysis, further developing the concepts presented in MATH 310. Topics may include basic measure theory, the Lebesgue measure and Lebesgue''s theory of integration, normed linear spaces, and a rigorous treatment of limits and calculus in multidimensional spaces.</p> <p style="color: #000000;">Prerequisite: MATH 214 and MATH 310 or permission of instructor.</p> <p><strong>Advanced Differential Equations </strong></p> <p>The course will consist of advanced topics in differential equations not usually seen in either ordinary differential equations or partial differential equations, such as: delay differential equations and stochastic differential equations. Boundary value problems, numerical methods, and infinite series solutions. </p> <p> Prerequisite: MATH 340 or MATH 342 or permission of instructor. </p> <p><strong>Knot Theory</strong></p> <p>How knots are described mathematically, how one can distinguish different knots, create new knots, classify knots. Topics include: Reidemeister moves, links, knot colorings, alternating knots, braids, knots and graphs, knot invariants, mirror images, unknotting, number crossing, number applications to biology and chemistry.</p> <p>Prerequisite: MATH 210, MATH 212, or MATH 214 or permission of instructor</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8240,2021,1461,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-396','<div class="desc"> <p>This is a 2-unit seminar course which will cover various topics in applied mathematics. This course may be repeated once for credit.</p> <p><strong>Industrial Mathematics</strong><br/> This course is a project-oriented introduction to industrial mathematics. Students will be grouped into teams and tasked with creating solutions to actual real-world problems provided by external partners from business, industry and government. Familiarity with a programming language is highly desirable but not required. The goal of this course is to provide students with an experience of what it is like to work as a mathematician in a professional setting.</p> <p><strong>Mathematical Modeling</strong><br/> This course is a project-oriented seminar in mathematical modeling. Concepts from calculus, linear algebra, differential equations and other areas of mathematics will be used to derive, describe and solve mathematical models from the life, physical, and social sciences. Familiarity with a programming language is desirable but not required. The goal of this course is to provide students with multiple examples of how mathematics can be used to explain various phenomena, to describe real-world situations and to make (more quantitatively) informed decisions.</p> <p><strong>Applied Mathematics</strong><br/> This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8241,2021,649,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/300/math-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8242,2021,253,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/400/math-400','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Applied Mathematics</strong></p> <p>This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> <p><strong>Euler to Uhlenbeck (History of Mathematics)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Spring semester seminar will cover Euler to Mirzhakani and Uhlenbeck. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>Euclid to Newton (History of Mathematics)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Fall semester seminar will (roughly) cover Euclid to Leibnitz and Newton. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>Introductory Algebraic Number Theory</strong> </p> <p>One of the most basic facts in all of mathematics is the Fundamental Theorem of Arithmetic: given a positive integer <img alt="n" class="CToWUd" id="m_-717388230643633685l0.4701107051873412" src="https://ci4.googleusercontent.com/proxy/YC8nj2e8yBmjCq6iHNmwmKCdjEMLA1Rkg9GJ3zrI5rgl2Dm25s_TOAvkaywNnYQr_JYl-kfbaPoAk1awVJYg5EjXQffL2dYqAGm_NHlLgSa3Z5T7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09n" style="display:inline; height:7px; width:9px" title="n"/>, it has a unique (up to ordering) factorization into primes. The integers are not the only interesting set of numbers to work with though. For instance, suppose you are interested in solutions to the equation <img alt="x^2 + 1 = 0" class="CToWUd" id="m_-717388230643633685l0.27052074324938746" src="https://ci3.googleusercontent.com/proxy/xqcvy1KFxXc8K883M_1PDukXqcmZPm-5tB-iSAMkGkvFeFHMSOafhQR0uUvfixvpkuFdBXvok_lC_7waFw7tk0gW8wv3vqRPSjX-COISgNGMetOSfY0ffCmyU0Zq4BpjNPGK2YwXlx6nsA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091%09=%090" style="display:inline; height:15px; vertical-align:-1.1px; width:74px" title="x^2 + 1 = 0"/>. This naturally leads us to consider the number <img alt="i = \sqrt{-1}" class="CToWUd" id="m_-717388230643633685l0.3047216474584953" src="https://ci3.googleusercontent.com/proxy/jI9lkel1Wbpr5NOwIn5DWDtYBZ60cpzFgOtDWow484Xkd2YpuW52catXmqkkijXBDPPEeH2fk6x4MQ2-2yTaorDx5u-_pGbv5ks_d4E5C_t_scHGQDLxG6KnpH3R96QWXdRQq6ktp-8Xuw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09i%09=%09%5Csqrt%7B-1%7D" style="display:inline; height:16px; vertical-align:-2.934px; width:63px" title="i = \sqrt{-1}"/> as well. We can then define a new collection of numbers called the Gaussian integers <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.3979931267566288" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> which consist of elements of the form <img alt="a + b i" class="CToWUd" id="m_-717388230643633685l0.015155930074882695" src="https://ci3.googleusercontent.com/proxy/d6zGMURoQy94P-DoTtLy93G4MB8MbHK1GInDLAorcYJkCCWM4cFLTvHUWm7k9TPC45AYf_oh-vjDQfyz97qQtaBGFVOXHEw4i7gio3uVenCYoZ148Hq_WkbUWIOPw4ef6hw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a%09%2B%09b%09i" style="display:inline; height:12px; vertical-align:-1.1px; width:41px" title="a + b i"/> for <img alt="a,b \in \mathbb{Z}" class="CToWUd" id="m_-717388230643633685l0.3730528622472029" src="https://ci6.googleusercontent.com/proxy/T4yrmOhXbiVysYHo65u2ng0ifI58f9fbFBHbM7FJE00vaWEiH8RIEZJB72bFauQ0qwa34Xj0I6JsGgN8seXxxvnTVCRsFaCrfX6W98sTyi-vFckX0fl8aA-HQ5IAVRdlAuYbUGWfrJKGR2lSl0LKQaM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a,b%09%5Cin%09%5Cmathbb%7BZ%7D" style="display:inline; height:14px; vertical-align:-2.934px; width:53px" title="a,b \in \mathbb{Z}"/>. Given a prime <img alt="p \in \mathbb{Z}" class="CToWUd" id="m_-717388230643633685l0.6716878374913045" src="https://ci5.googleusercontent.com/proxy/I91pxfAy3o71ANU93zluf4FRJbNEGbX_SHuVKVPdohW_2Wwsw-Lgsztq4vsguB5AYJHfxGA4B3-lF8Z3Wf9vpwU6hcWFTZv3BO1mgkV4qOww6Cb2ajJ35ZUq_egaIzCfFdLLVUYR8f2pL09aP6pQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D" style="display:inline; height:14px; vertical-align:-2.934px; width:39px" title="p \in \mathbb{Z}"/>, we also have <img alt="p \in \mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.35769983375498393" src="https://ci3.googleusercontent.com/proxy/_X0boZvQHsr_aQSiVPqR6BIXlVDDGHiT4bYg4-VFaYiwAj2SRz9etcwOW-PHVF8NfxpBUeuJ2KgV1badjYAa0udYsnrsUF2BFfVyBBE3UMF1Rj8vNowRbWa4SiiuEuh9j8IcgeojBr0PlNAdaxl5cAy7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:53px" title="p \in \mathbb{Z}[i]"/>. Is <img alt="p" class="CToWUd" id="m_-717388230643633685l0.1517664126518219" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/> still prime in <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.5476717335800629" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/>? It turns out that sometimes, but not always! For instance, in <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.4503683865279826" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> we have <img alt="2 = (1 + i)(1 - i )" class="CToWUd" id="m_-717388230643633685l0.8909417025380852" src="https://ci4.googleusercontent.com/proxy/XvwjjHBgKnD2a36lesGEq1IkFArJpjXtTykglqE2EaWNBlM9_xg03JuwnNtjGawD0g8n7QvoWgwh0pmM6lceriWU9WXg1sBmtIfdlM6JSu5uMmM_t6F4oOAy0L7mm1LgnpxILKTxKFp-G3huy6k9DSkKdcdKLQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%092%09=%09(1%09%2B%09i)(1%09-%09i%09)" style="display:inline; height:16px; vertical-align:-3.667px; width:123px" title="2 = (1 + i)(1 - i )"/> and <img alt="5 = (2 + i) (2 - i)" class="CToWUd" id="m_-717388230643633685l0.9367616738022781" src="https://ci4.googleusercontent.com/proxy/FyVZr4VzL5yrRbSosqkqGx04BmK6zUcoqlCLddJPUxekXPW72sf-MpLR9B9lbMIdAqpHod1zFvoBVn0d4FaWXAABuCsa8KVM2RwNcTEFBrWHh230o_Yk-l_LQEcrvyNOIfwOXU53fdiRTvUTLUTe5B3slXa1sA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%095%09=%09(2%09%2B%09i)%09(2%09-%09i)" style="display:inline; height:16px; vertical-align:-3.667px; width:123px" title="5 = (2 + i) (2 - i)"/>, but <img alt="3" class="CToWUd" id="m_-717388230643633685l0.6355056826217114" src="https://ci6.googleusercontent.com/proxy/Er5UHWmuvViTqmbNTtg07Zo3TDld1PrKGZFpM1g1IYsbUxVg42LXa42yahDQowN9d1uGeAObmZqSYE6hywCYmc-qr5momXJ3Q9fqmsmt7t2msGmt=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%093" style="display:inline; height:11px; width:7px" title="3"/> is still prime! This fact is related to writing <img alt="p" class="CToWUd" id="m_-717388230643633685l0.7053141998565537" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/> as a sum of two squares as well as how the polynomial <img alt="x^2 + 1" class="CToWUd" id="m_-717388230643633685l0.2533482662405988" src="https://ci5.googleusercontent.com/proxy/O9U18DGHuRvAsqi0RA0hDNN3XN_cNoMh5A0X7XL4tEHMlZY45-T6w2Qf07anETTar4klaWwUOHcUdnWp5LQ2J3bAjhXiPRgi-45NwXEBc5Z2C7CwaVEmfvjIspVx6wcFjiM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091" style="display:inline; height:15px; vertical-align:-1.1px; width:43px" title="x^2 + 1"/> factors when considered modulo <img alt="p" class="CToWUd" id="m_-717388230643633685l0.41962974130248254" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/>. The study of how primes factor when considered in larger rings is referred to as algebraic number theory. In this course we will study algebraic number theory for the simplest cases of <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.719894371208375" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> and possibly other rings of the form <img alt="\mathbb{Z}[\sqrt{d}]" class="CToWUd" id="m_-717388230643633685l0.9347271008519611" src="https://ci3.googleusercontent.com/proxy/fykrb_Z6FYHa1OHSUz6l_6Ccl38TddheOZ5XqwFQDiTJtyJBJ2qrWG0-ZBvP45qpMtA0PEp7ENHRM7_NY_hSV-uPy-AwOGApOXctS2cmUXG322diPJNjCmvCdBrHDWjgJVN5jBXvfgSUS6PS8y57cGrr6A=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[%5Csqrt%7Bd%7D]" style="display:inline; height:18px; vertical-align:-3.667px; width:40px" title="\mathbb{Z}[\sqrt{d}]"/> to see the underpinnings of the overall vast theory. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8243,2021,2556,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/400/math-401','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Cryptology</strong></p> <p>Cryptology is the study of sending secret messages over insecure communication channels. Cryptographic capabilities are important to politics and foreign affairs, and underlie the functioning of a great deal of the modern economy. In this course we will study the mathematical theories and techniques that make cryptography function, and also those that break it. We will learn how these mathematical tools influence the use of cryptographic systems, and practice explaining these implications to people without developed mathematical backgrounds.</p> <p><strong>Applications of Linear Algebra</strong></p> <p>We will use the book Thirty-three Miniatures: Mathematical and Algorithmic Applications of Linear Algebra, by JiÅì Matoušek. We will concentrate mostly on the mathematical applications (as opposed to the algorithmic applications). In the first two class meetings we will learn about (generalized) vector spaces, as preparation for the remainder of the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8245,2021,650,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/math-mathematics/400/math-499','<div class="desc"> <p>Students who have been accepted by the Department to do honors should register for MATH 499, in lieu of MATH 400. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8246,2021,1241,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/100/musa-100','<div class="desc"> An introduction to the use of the Occidental electronic music studio and the creation of electronic music with synthesizers, computer and digital recorders. Graded on a Credit/No Credit basis only. May be repeated for credit. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8247,2021,1243,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/100/musa-103','<div class="desc"> <p>An introduction to classical guitar including, basic technique and musicianship. The traditional repertoire as well as 20th century and flamenco will be explored. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8248,2021,1244,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/100/musa-104','<div class="desc"> <p>A further exploration of classical guitar, with emphasis on a thorough treatment of musicianship, technique, and expansion of the repertoire for the guitar soloist.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8249,2021,1245,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/100/musa-105','<div class="desc"> <p>The Alexander Technique helps students move naturally. They learn to prevent excess tension and replace it with a more effectively balanced movement pattern throughout the body. Does not satisfy Music Major applied music requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8250,2021,2503,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/100/musa-106','<div class="desc"> <p>Basic ukulele technique at the beginning through lower intermediate level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8251,2021,1246,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-201','<div class="desc"> <p>Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive zero units. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8252,2021,1247,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-202','<div class="desc"> <p>Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive zero units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8253,2021,1248,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-203','<div class="desc"> <p>Beginning to advanced instruction in improvisation, contemporary harmony, and reading lead sheets. Recommended for aspiring producers, composers, arrangers, and jazz or commercial keyboardists as a follow-up to MUSC 109. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive zero units. </p> </div>',NULL,NULL,NULL);
