INSERT INTO course_descriptions VALUES(8305,2021,2504,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-279','<div class="desc"> <p>Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive 0 units. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8306,2021,2505,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-280','<div class="desc"> <p>Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive 0 units. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8307,2021,2817,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-281','<div class="desc"> <p>Beginning to advanced instruction in drum set performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive 0 units. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8308,2021,2818,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musa-music-applied-study/200/musa-282','<div class="desc"> <p>Beginning to advanced instruction in drum set performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), excepting cases where students are receiving an ensemble scholarship, whereupon they receive 0 units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8309,2021,652,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/copy-of-musc-105','<div class="desc"> <p>This course surveys music of African Americans with an emphasis on 20th century classical and vernacular genres. We will examine this musical web in three units: Classical Jazz &amp; Blues and Rock &amp; Contemporary Vernaculars. Featured artists include William Grant, Still Marian Anderson, Margaret Bonds, Duke Ellington, Fats Waller, Big Mama Thornton, Sam Cooke, The Five Blind Boys of Alabama, Motown Stax Records and Atlantic Records, Jimi Hendrix, Sweet Honey in the Rock, and Mos Def. Through extensive listening reading and group dialogue this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8310,2021,653,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/copy-of-musc-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8311,2021,259,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-120','<div class="desc"> <p>Study and performance of choral music. Development of singing ability and sight-reading skills through the preparation and performance of works for full chorus. The chorus rehearses one evening each week and performs on-campus each semester. Students may enroll for one or both semesters.</p> </div>','Ensemble membership is open to all students. Students new to the ensemble should meet with the instructor during the first week of the semester. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8312,2021,260,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-121','<div class="desc"> <p class="sc-BodyText">Advanced study and performance of choral music. Emphasis is placed on the more difficult traditional choral repertoire, but the study of world music and popular music is included. Includes many performances with Men''s Glee Club, both on and off campus. Enrollment is for the full year and is by audition during the first week of the fall semester. Two hours rehearsal per week plus two and a half hours rehearsal per week with Men''s Glee Club. Sight reading ability and previous musical experience highly recommended. May be repeated seven times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8313,2021,261,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-122','<div class="desc"> <p class="sc-BodyText"></p> Advanced study and performance of choral music. Emphasis is placed on the more difficult traditional choral repertoire, but the study of world music and popular music is included. Includes many performances with the Women''s Glee Club, both on and off campus. Enrollment is for the full year and is by audition during the first week of the fall semester. Two hours rehearsal per week plus two and a half hours rehearsal per week with Women''s Glee Club. Sight reading ability and previous musical experience highly recommended. May be repeated seven times for credit. <p class="sc-BodyText"></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8314,2021,262,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-123','<div class="desc"> <p class="sc-BodyText"></p> <p>Semester-long instruction with music tradition-bearers allows students to develop the technique and language to approach musical styles from outside the Western art music canon, while exposing them to alternative modes of musical pedagogy. In addition to practicing secular rumba drumming, students will study the sacred rhythms of Santeria and learn to sing the songs of the Orishas in the Yoruba dialect of Lucumi. In addition to weekly rehearsals with the ensemble, students will be expected to practice on their own and to participate in a public performance at the end of the semester. No prior music experience is required.</p> <p class="sc-BodyText"></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8315,2021,955,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-124','<div class="desc"> <p class="sc-BodyText"></p> Son Jarocho Ensemble introduces students to the songs and instrumental techniques of son jarocho, a musical genre from Veracruz, Mexico that mixes indigenous Mexican, African, Spanish, and Arabic sounds. The course will be taught by a master musician who brings over twenty years of musical experience to his classes. Students will learn to play jarana, the eight-stringed guitar that provides the harmonic scaffold for son jarocho. In addition to weekly rehearsals with the ensemble, students will be expected to practice on their own and to participate in a public performance at the end of the semester. No prior music experience is required. <p class="sc-BodyText"></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8316,2021,264,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-126','<div class="desc"> <p>A symphonic wind ensemble for qualified instrumentalists from the college communities of Occidental and the California Institute of Technology (students, faculty, staff, and their families). The Orchestra presents concerts on both campuses during the year. Graded Credit/No Credit and may be repeated for up to eight units of credit. Ensemble membership is open to all students of the college by audition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8317,2021,265,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-127','<div class="desc"> <p class="sc-BodyText">The Occidental Jazz Ensemble consists of instrumentalists from Occidental who are interested in performing jazz of various styles. Charts and styles are determined according to the instrumentalists in the ensemble and their particular jazz interests. The Jazz Ensemble presents several concerts during the academic year. <em>Enrollment is by audition with the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8318,2021,1239,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-128','<div class="desc"> <p class="sc-BodyText">This course will serve as an intensive laboratory component to the Occidental jazz program by having students learn the fundamentals of jazz theory including the following: extensions of common practice tonality; modes; form; notational practice and reading from charts; basic arranging and instrumentation; and transcription. Weekly written theory and listening assignments will be supplemented by performance assignments. In class students as well as instructor will critique one another''s performances. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8319,2021,266,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-129','<div class="desc"> <p>Study and performance of chamber music for diverse combinations of instruments and voices. Students audition during the first week of the semester for our Director, who selects repertoire and form appropriate groups of student players. Students perform both music of the past (including the recent past) as well as new music composed for them by our music composition students, culminating in world premieres at the end-of-semester concert. Prerequisite: audition and permission of instructor. This course does not fulfill the ensemble requirement for scholarship recipients and Music majors. Only advanced pianists may use this course to fulfill the ensemble requirement for scholarship recipients and Music majors. May be repeated seven times for credit. Audition during the first week of the semester. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8320,2021,267,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/ensembles/musc-130','<div class="desc"> <p>The Occidental Symphony Orchestra is an orchestral ensemble that plays music from the Baroque era through today. Through its collaboration with Oxy''s music composition program, the Orchestra will perform and record new music, including film scores written for MAC student films. The Orchestra will frequently partner with the Occidental Glee Club to perform a large choral work with orchestral accompaniment. Enrollment is by audition during the first week of each semester. Instructor permission required. As the community orchestra for Northeast Los Angeles, the Orchestra is not only open to all students but also alumni and community members. May be repeated seven times for credit. Enrollment is by audition during the first week of each semester. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8321,2021,255,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-101','<div class="desc"> <p class="sc-BodyText">An introductory course in the techniques of music for the student who has little or no previous musical training. Topics will include notation, modes, intervals, melody, harmony, rhythm, and structural elements of music.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8322,2021,256,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-102','<div class="desc"> <p class="sc-BodyText">This course will examine the diverse forms and social contexts of Latin American and Caribbean music while exploring the ways that musical performance has been used to negotiate power relations in the social political and economic spheres since the Conquest. Focusing on musical genres and movements from Argentina Brazil Cuba Haiti Mexico Peru and Trinidad students will learn to recognize the techniques and instruments used in a wide array of traditional and contemporary styles particularly those which have grown out of the hybridization of African Middle Eastern European Asian and Native American performance strategies. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8323,2021,257,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-103','<div class="desc"> <p class="sc-BodyText">This course surveys the musical styles and genres of Asia from India through the southeastern part of the continent and includes the countries and islands of the Pacific. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. Where appropriate distinctions will be made between classical and folk genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8324,2021,953,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-104','<div class="desc"> <p class="sc-BodyText">This course surveys the musical styles and genres of the African continent and the Middle Eastern world. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8325,2021,2856,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-106','<div class="desc"> <p>Fundamentals of singing: voice production, diction, repertoire, and musicianship. Recommended as preparation for private lessons. Graded on a Credit/No Credit basis only. May be repeated once for credit.<br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8326,2021,2558,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-107','<div class="desc"> <p>In-depth exploration, practice, and application of vocal techniques for the more experienced singer plus an emphasis on advanced aspects of performance. Culminates in a final recital. May be repeated three times for credit. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8327,2021,2349,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-108','<div class="desc"> <p class="sc-BodyText">This course will survey the development of folk and popular music in Europe, including the music of the Balkans, the Baltic States, the Celtic region, the Iberian Peninsula, and the Mediterranean. We will examine how this music has served nationalist agendas, and how media and marketing have shaped the ways in which this music is understood. As most of this music involves dance, the study of dance will be an integral part of this course. Students must be prepared for intensive listening assignments, in and out of class. Prior musical experience or knowledge not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8328,2021,2707,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-109','<div class="desc"> <p>Basic keyboard technique at the beginning through lower intermediate level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8329,2021,1183,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-112','<div class="desc"> <p class="sc-BodyText">Pop music blogs online social networks home recording studios and mashup/remix communities are emerging musical spaces in the digital era. In this course we will study music-cultures that are enabled and generated by digital media and technology. We ask how digital media shape the mode of production transmission and reception of contemporary popular music. Using principles of ethnomusicology we will examine how music as a "digital vernacular" creates a sense of place and self in the increasingly globalized world; how social media and technological institutions organize 21-century music participation at the grassroots independent level.<strong> A laptop computer is required.</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8330,2021,1715,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-113','<div class="desc"> <p>Composing, improvising, listening, and performing all embody aspects of music-making. This course examines compositional methods of contemporary composers. We will focus on hands-on composing in a broad range of styles. Additionally, students will learn about all of the instruments of the orchestra (range, characteristics, timbre, etc.). In-class listening will supplement bi-weekly listening assignments covering orchestral music from the Baroque to the present. Students will learn to develop musical ideas through notational methods that can effectively be realized by performers. Basic music theory will be taught in class in order to learn about transposing instruments, notation methods, and how to read music in different clefs, such as alto and tenor clefs. </p> </div>','MUSC 101 or the equivalent, or permission of instructor. First-year and transfer students must take the Music Theory Placement test (administered during Orientation) to determine eligibility for the course. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8331,2021,954,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-114','<div class="desc"> <p class="sc-BodyText">This class introduces students to the world of the orchestra beginning with its historical development and followed by an in-depth exploration of its instruments. Each class will focus on a different instrument its history and its fundamental properties (range characteristics timbre etc.). Performance faculty and proficient student instrumentalists will provide routine in-class demonstrations of the instruments we study. In-class listening will supplement weekly listening assignments covering orchestral music from the Baroque to the present. The course will emphasize the relationships between instruments (e.g. what does an oboe and trumpet sound like when playing the same line simultaneously) and how these relationships inform a composer’s decision-making process when writing for an orchestra. No music theory background is required only an ability to read music notation at a basic level (treble clef bass clef scales etc.). This course will serve as a prerequisite to MUSC 258 (Introduction to Film Scoring) starting Fall 2016.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8332,2021,258,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-115','<div class="desc"> <p>A historical and cultural survey course of a select genre of vocal music, such as opera, song, musical theater, and choral music. Topics vary by semester.</p> <p><strong>Opera</strong></p> <p>Since its beginnings in late 16th-century Florence opera has occupied the most diverse of minds: whether lovers of authority (from Louis XIV to Rudy Giuliani) or lovers of the folk (from Jean-Jacques Rousseau to Rufus Wainwright); whether masters of horror (from Edgar Allen Poe to William Friedkin) or masters of the humane (from Søren Kierkegaard to Toni Morrison); whether purveyors of the scholarly (from Friedrich Nietzsche to Kwame Anthony Appiah) or purveyors of the popular (from Scott Joplin and George Gershwin to Beyoncé Knowles and Woody Allen). In this historical survey course we will examine this diversity of responses to and in opera by studying 1) the precise musical forms and styles of the most famous operas and 2) the primary source documents written as responses to individual operas and opera writ large. We will thus study individual operas in their political philosophical and cultural contexts. Required listening and reading will be supplemented by required trips to the Los Angeles Opera for rehearsals of operas by Mozart Verdi and Puccini. No prior musical experience is required. Additional Core Requirement: Regional Focus.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8333,2021,1076,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-117','<div class="desc"> <p class="sc-BodyText">This course will survey film music from its silent film era origins to the present focusing on its many functions through in-class viewing analysis and critique of film clips. The works of many prominent film composers as well as some lesserknown figures will be examined in terms of style and approach as well as their own views on the film-scoring process. Fundamental information on music film and psychology of music will be introduced and the role of music in other media (such as TV and experimental video) will be explored.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8334,2021,654,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-119','<div class="desc"> <p>This course provides a general introduction to the elements and history of Western music over the last millennium. Students will focus on learning how to listen to music with an emphasis of identifying musical forms genres and styles. This focus will serve the larger goal of the course which is to show how understanding music can not only lead to our greater enjoyment of it but also help us to better understand history and culture. Students with no musical experience are especially welcome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8336,2021,1668,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-148','<div class="desc"> <p>Logic Pro X and Ableton Live are professional music production programs (known as DAW''s) that combine composition, notation, and audio production facilities. Relevant to composers, songwriters, music producers, and audio engineers, this course introduces students to the primary features and basic user interface of Logic Pro X and Ableton Live. Students will learn the process for creating an actual song, from recording live players, producing beats, editing audio, and recording/editing/arranging MIDI sequences, to digital effects processing using virtual plugins, automation, and mixing. Instructor permission required.</p> </div>','Permission of instructor, plus MUSC 101 or the equivalent. First-year and transfer students must take the Music Theory Placement test (administered during Orientation) to determine eligibility for the course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8337,2021,657,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-151','<div class="desc"> <p>This course presents the basic principles of musical form and analysis including simple counterpoint and diatonic harmonic practice. Students will engage in analytic and compositional projects in consultation with Music History faculty. Corequisite: MUSC 151A.</p> </div>','MUSC 101 or passing out of MUSC 101 with a sufficient score on the department''s Music Theory Placement Examination ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8338,2021,659,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/100/musc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8339,2021,2350,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/copy-of-musc-248','<div class="desc"> <p>Music producers have at their disposal a set of powerful tools that enable them to create, shape, and refine their sounds in their studios. In this course, we will use Kontakt and Reaktor for a hands-on approach to building virtual instruments and synths. We will address topics such as synthesis and sampling, and we will create and shape pads, basses, and drums by using virtual instruments and third-party plugins. Students compose more advanced creative projects using the instruments they create.</p> </div>','MUSC 148 with a grade of B- or higher and permission of instructor ','MUSC 151 (may be taken concurrently)',NULL);
INSERT INTO course_descriptions VALUES(8340,2021,3010,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-201','<div class="desc"> <p>In this class, we examine sampling, the capture and redeployment of audio sound artifacts, as both a means of music production and an epistemology for constructing knowledge. After reviewing the rich history and theory of hip hop sampling, we will relate this model of musical production to other theories of cultural repetition including cut-and-paste, pastiche, index, simulacrum, collage, citation, signifying(g) and performative repetition. Finally, we will examine the ethics of sampling in the context of neoliberal economic and legal imperatives (including international copyright laws) which have been uneven in their protection of artists and producers. This course satisfies the Second-Stage Writing Requirement within the Music major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8341,2021,1240,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-215','<div class="desc"> <p class="sc-BodyText">The history of opera is a history of the continuous reinvention of a genre in order it to accommodate the time place and tastes of its audiences; as such opera provides a lens for studying cultural intellectual political and economic history. With now even non-operatic companies like the Los Angeles Philharmonic staging operas in Disney Hall opera has in the past three decades especially become a terrific lens for studying Los Angeles.This course will study opera as delimited by its production and reception in Los Angeles over the past century. We will research what operas were first produced in Los Angeles where and for what audiences and how the production and reception of opera and later zarzuela evolved over the course of the twentieth century and into the new millennium as Hollywood directors such as Woody Allen and William Friedkin have turned to directing opera. Students will attend operas principally at LA Opera our community partner but also at Long Beach Opera the Los Angeles Philharmonic and other SoCal venue.</p> </div>','Sophomore standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8342,2021,284,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-232','<div class="desc"> Prepares music majors to demonstrate competence in a broad range of keyboard skills: basic keyboard technique, sight reading, elementary repertoire, harmonization of melodies, transposition, and accompaniment. Satisfactory performance on the final exam is required to satisfy the Music major piano proficiency requirement. Graded on a Credit/No Credit basis only. </div>','MUSC 132 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8343,2021,1184,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-241','<div class="desc"> <p>As part of human cognition, our perception, production, and understanding of music has elicited many questions: What is music in relation to "sound"? Is music an evolutionary adaptation? What is the relationship of music and emotions, or memory? Can music influence perception in other modalities? What is the meaning of music? Can music make us smarter? Is music a language? What is biological and what is cultural in the esthetics of music? This course will reframe many of these questions from the interdisciplinary standpoint of cognitive science, acoustics, music theory, and semiotics to explore music as a cognitive process. Topics will include the perception of pitch, timbre, rhythm, and localization; music and the brain; cognitive aspect of the esthetics of music; the relationship between music and language in terms of their structures and neurological processing; music and memory; music and emotions; music and meaning. We will also discuss the role music plays in cross-modal interactions, either in the real world, or in films and multimedia art works.</p> </div>','Any course in Music or Cognitive Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8344,2021,1605,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-245','<div class="desc"> <p>In this course, students learn how to execute the fundamental aspects of creating a successful music project within the music entertainment industry. Students will work in groups to create artist profiles and business plans, which they will then execute online, by way of digital service providers such as Bandcamp and Spotify, and offline, through methods such as networking, live performance, and industry events. By fashioning distinctive artist identities, students will learn how to formulate an artist brand, including name, style, biography, and intent. They will learn how to market these projects and conduct cost-benefit analyses as they develop business plans which may include frameworks for radio, publicity, distribution, licensing, and synching. The goal of the course is to have students acquire the tools to advance their own careers along their chosen music industry path.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8345,2021,2743,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-246','<div class="desc"> <p>This course applies acoustics, electronics, and digital audio theory in the assembly and operation of Public Address (PA) systems for live concerts. We cover the practice of live sound engineering in different contexts, with a focus on skill building in the technical aspects of live music. Students will assemble PA systems and operate a front of house mixing console for a host of music events both on and off campus. Students will also learn how to set up microphones, use a graphic equalizer to tune a PA system, and run individualized monitor mixes during live performances. Lessons about the theory and practice of live sound will be presented alongside practicum exercises in live engineering, culminating with running tech for several concert-length live performances. Live recording in a DAW-based multi-track session will also be a component in the later portion of the semester.</p> </div>','MUSC 148 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8346,2021,2834,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-247','<div class="desc"> <p>Pro Tools is, worldwide, the standard digital audio workstation for audio recording, editing, and mixing in studios and music production facilities. Understanding its operation, features, and workflows is required for the production of all music genres today, from the small studio to the largest scoring stage. This course will take students with no experience in Pro Tools and equip them with the knowledge and hands-on training to prepare them for the Avid Certified User for Pro Tools exam by covering all the material in Avid’s Pro Tools Fundamentals I (PT101) and Pro Tools Fundamentals II (PT110) curricula. The PT101 course introduces fundamental Pro Tools concepts and principles, covering everything one needs to know to complete a basic Pro Tools project, from initial setup to final mixdown. The PT110 course builds on PT101 by introducing the core concepts and techniques students need to become competent in operating a Pro Tools system for mid-sized recording sessions. Both this course and MUSC 249, Recording Techniques, are required to run recording sessions in the Booth first-floor recording studio. Instructor permission required.</p> </div>','MUSC 148 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8347,2021,2600,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-249','<div class="desc"> <p>This course explores techniques used for recording music in a studio and in live environments. Topics include commonly encountered acoustical problems and the equipment and techniques used to overcome them. Students develop knowledge of signal flow, mixing board operation, microphone choice and placement, preparing and managing recording sessions both in the studio and on-site (e.g., Herrick Chapel, Bird Studio, etc.), and delivering assets for the mix. Semi-weekly hands-on, guided set-up and operation of recording sessions of various sizes and ensembles help illustrate concepts and allow students to learn through experience. These experiences include recording single instrumentalists, vocalists, acoustic and electronic instruments, and on-campus student recitals and concerts. Instructor permission required.</p> </div>','MUSC 148 and MUSC 247 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8348,2021,1024,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-250','<div class="desc"> <p class="sc-BodyText">This course deepens students'' exposure to techniques for analysis and composition in the style of eighteenth-nineteenth century common practice. We will study imitative genres and sectional forms (ternary, sonata, rondo), exploring chromatic extensions of diatonic practice. Students will engage in analytic and compositional projects in consultation with Music History faculty. Includes continued training in tonal sight singing, listening, and keyboard skills: introduction to chromaticism, related key modulations, modes, seventh chords; continued study of chord progressions and rhythmic studies.</p> </div>','MUSC 151/151A. Requires concurrent enrollment in MUSC 250A ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8349,2021,2642,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-252','<div class="desc"> <p>An introduction to the fundamentals of songwriting. In this course, students analyze the form, melody, and harmony of successful songs to determine what makes them effective, and apply this knowledge to the composing of their own songs. Most classes will consist of performing and work-shopping student work in the spirit of open critique.</p> </div>','MUSC 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8350,2021,285,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-257','<div class="desc"> <p>Writing exercises to develop technical facility; study of characteristics of instruments; exercises in scoring for various vocal and instrumental combinations. Permission of instructor required. <em>This course may be repeated five times for credit.</em></p> </div>','MUSC 113 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8351,2021,1390,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-258','<div class="desc"> <p>This course introduces students to the art of film scoring and provides an in-depth exploration of the field. We will discuss functions of film music and analyze preexisting scores that demonstrate varying dramatic situations, while also investigating the aesthetic relationship between film and music. Students will be required to write music for preexisting scenes throughout the course, as well as score student short films (senior comps) from Media Production majors. </p> </div>','Music 148 or permission of instructor (basic experience using Logic, Ableton Live, or other Digital Audio Workstation) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8352,2021,286,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-261','<div class="desc"> <p>This course surveys the two-plus centuries that gave rise to European art music''s most enduring legacies: opera, instrumental art music, and, especially, the major-minor tonal system, which, as the system that informs most music today, is arguably Europe''s greatest-ever cultural export. The emergence of this tonal system enables instrumental music to sustain a listener''s attention through dramatic forms and without the aid of words; comprehending how these forms behave is one of the central tasks of this course. In turn, the cultivation of instrumental genres will fuel the operatic accomplishments of Classical composers, notably Mozart. Our study of vocal and instrumental music proceeds chronologically and focuses on individual cities, starting with Florence at the end of the Renaissance and ending with Vienna, the music of Beethoven and Schubert, and the emergence of musical Romanticism. This course may be used by Music majors to fulfill the Second-Stage Writing Requirement. Not open to first-year students.</p> </div>','MUSC 101 or the equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8353,2021,862,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-262','<div class="desc"> <p class="sc-BodyText">This interdisciplinary course will survey the music of the long 19th century from the French Revolution to the beginning of World War I. We will commence by considering Beethoven''s response to Napoleon the Eroica Symphony in the context of post-Revolution European geo-politics and end with the musical cultures of turn-of-the-century Vienna Paris and New York City. Topics to be explored include the following: the Industrial Revolution and emergent technologies (including photography); landscape painting and poetry; nationalism (including "folk" music); aesthetics and philosophy; science and medicine; the expansion of tonal and formal musical language and the essaying of new musical forms; the public concert and music for home performance; and Richard Wagner and artistic responses to his music and writings.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8354,2021,956,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-263','<div class="desc"> <p>This course picks up where MUSC 261 leaves off, with the emergence of musical Romanticism and, with it, an understanding of music, composer, and audience that still informs listening practices today. After surveying the music of the first generation of Romantic composers (with special attention to the music of Fryderyk Chopin), we turn to Richard Wagner’s music and writings and how they shaped the rise of modernism in music, with its new forms, genres, styles, and pitch systems. We then take up jazz, the radical experimentation of the 1920s ultra-modernists, and music under fascism. Thereafter, we study all subsequent major musical developments, through to post-minimalism and hip hop. Throughout, we will be alert to the political, philosophical, and cultural forces shaping the music at issue. This course may be used by Music majors to fulfill the College-wide Second-Stage Writing Requirement.</p> </div>','MUSC 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8355,2021,2708,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-264','<div class="desc"> <p>While attempts to theorize a coming-together of all of the arts to create a unified artwork date to the eighteenth century, it is in the nineteenth century that the notion of a total artwork—in German, a <em>Gesamtkunstwerk</em>—gathers steam, famously in the writings of Richard Wagner, who sees in the total artwork the “artwork of the future” (the title of one of his most famous essays). This course examines the evolution of this concept within and beyond the Wagnerian context, from its prehistory in eighteenth-century theories of beauty and taste, to sound film and music videos, to contemporary Los Angeles dining experiences (such as at Craig Thornton’s Wolvesmouth and Jordan Kahn’s Vespertine) that pick up where Wagner’s theories left off. To chart this history will require us to consider theater, music, dance, painting, architecture, philosophy, film, and gastronomy. Throughout we will investigate the roles that attentiveness and perception play in these multi-sensory events, and consider how European thought and practices migrate and get translated to a contemporary, North American context. Guest lectures by artists and restaurateurs will be supplemented by field trips to Los Angeles arts and dining venues. No previous musical experience required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8356,2021,2351,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-266','<div class="desc"> <p>In this course we study French culture from the reign of "Good King Henry, the Green Gallant," Henry IV (1589Â­-1610) and his invigoration of the arts and French cuisine, to the July Monarchy (1830-Â­1848) and the novels of Balzac, the photographic process of Daguerre, and the music of Chopin. We will also pay particular attention to painting (from Poussin''s classical landscapes to Corot''s Romantic ones), dance (from the codification of couples dancing in the court of Louis XIV to the emergence of classical ballet in 1830s Paris), philosophy (from Descartes''s dualism to Cousin''s eclecticism), theater (from Molière''s The Bourgeois Gentleman to Dumas fils''s The Lady of the Camellias), fashion (from Louis XIV''s introduction of huge wigs of curled hair to the Empire style under Napoléon), and food (from the start of haute cuisine to the invention of the restaurant and gastronomy). Throughout, we will concern ourselves with the interplay of these cultural productions, and how the everÂ­evolving city of Paris served as their crucible.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8357,2021,1606,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-268','<div class="desc"> <p class="sc-BodyText">This multidisciplinary course takes the crucible that was fin-de-siècle Vienna as its object of study beginning with the city’s 1890-92 expansion to include the suburbs south of the Danube to the beginning of World War I which brought an end to the Hapsburg dynasty and Austria-Hungary. Our approach to studying Vienna will be prismatic: each week will consist of one seminar on its music (principally the music of Gustav Mahler and Arnold Schoenberg) and one guest lecture on one of the following aspects of the city at this time: urban planning economics political history architecture art dance psychology medicine science and religion. The last three weeks on campus will be devoted to German language instruction and individual research projects. The on-campus component of the course will culminate in transforming Bird Studio into a Viennese coffee house which will welcome the campus community and during which students must impersonate through knowledgeable conversation a contemporaneous Viennese figure central to their field of research. This immersive on-campus study will crescendo to the downbeat of the course: the week after Commencement you will board a flight for Vienna for three weeks of intensive study there convening as a class each day attending lectures classes (including a cooking class!) and concerts and visiting the historical cultural and musical sites we studied on campus. We will take three three-hour guided walking tours of architectural monuments of historical (including music-historical) monuments and of Viennese coffee houses. Arriving during the cultural festival Vienna Festival Weeks we will attend as many of its offerings as time permits. Students must apply and participate in an interview for this course whose enrollment will be limited to sixteen students. Frosh may not apply for this course.</p> </div>','Sophomore standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8358,2021,287,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-272','<div class="desc"> <p class="sc-BodyText">Basic principles and gestures of instrumental conducting in a variety of genres: symphony concerto opera. We will also discuss the "business" of conducting and running rehearsals.</p> </div>','MUSC 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8359,2021,863,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-273','<div class="desc"> <p class="sc-BodyText">Introduction to conducting technique from a choral perspective. Students will learn to develop musical interpretation through score study analysis and a clear gestural vocabulary.</p> </div>','MUSC 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8360,2021,288,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-280','<div class="desc"> <p>This course offers an introduction to the principal concepts and methodologies of the field of ethnomusicology as well as the style and practices of selected world musical traditions. This course may be used by Music Majors to fulfill the college-wide Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8361,2021,1391,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-282','<div class="desc"> <p class="sc-BodyText">North Indian (Hindustani) Classical Music is one of the most complete systems of musical expression found in the world today. Hindustani music is a vibrant contemporary art form that draws from an ancient historical tradition and rigorous theoretical structure to create performances that combine spontaneous creativity with virtuosic musicianship. In this course students will explore the musical and cultural aspects of this system through historical analysis and hands-on practice. Beginning with those elements of structure that Hindustani music shares with Western music (including the major scale) students will integrate theory practice and musicianship as part of a comprehensive introduction to North Indian music. The ability to read Western staff notation is highly recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8362,2021,1716,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-283','<div class="desc"> In this course we will examine the diverse musical cultures (historical and contemporary) of Los Angeles, paying particular attention to the ways music negotiates intercultural encounters. As we survey the musical cultures of Native American, European, Asian, African, and Middle Eastern descendants in the Los Angeles area, we will think about how musical styles, repertoires, instrumentation, and texts are transformed by urban dwellers as they respond to the changing political, economic, and social landscapes of the city. Students will undertake both individual research projects on the Los Angeles-area musical culture of their choice and a digital group project on the local Spanish-language ska scene. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8363,2021,1462,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-284','<div class="desc"> <p class="sc-BodyText">Although they have often been marginalized within official histories of North American music-making Latino/a musicians have contributed to the production and development of every major genre of music in the United States. In this course we will review the history of Latino/a music in the United States focusing on regional musical movements in Texas California New York and Florida. In addition to exploring Spanish-language genres including cumbia salsa merengue conjunto banda and reggaeton which have been shaped by musical innovators in the United States we will trace the influence of Latino/a musicians on rock n’ roll punk jazz hip hop and country. In particular we will be interested in exploring how music has helped to shape emerging patterns of racial ethnic class and gender identification while fanning the flames of social protest movements from the Chicano Movement of the 60s and 70s to the pro-immigrant rights movement of the past two decades. Finally we will consider the emerging soundscape of U.S.-based protests on behalf of the 43 students massacred in Iguala Mexico. In addition to written assignments students will also collaboratively develop a digital project incorporating maps storytelling and data visualizations. <em>No prior study of music or digital humanities is required.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8364,2021,289,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-285','<div class="desc"> <p>Various topics are offered. Each may be used by Music Majors to fulfill the College-wide Second-Stage Writing Requirement.</p> <p><strong>From Instagram to Digital Music Archive: Popular music and public memory in Latinx Los Angeles</strong></p> <p>In this class you will explore the role of social media in archiving popular music. In particular, you will work with an Instagram-based archive that documents several decades of Latinx rock n’ roll in Los Angeles. Questions you will consider include:</p> <p> · In the post-digital age, how does one “read” ephemera such as flyers and photographs posted on social media? How can they be re-articulated in scholarly contexts?</p> <p>· How are community and/or social media archives different from institutional archives and what role can they play in supporting and sustaining local communities, particularly Latinx communities in Los Angeles?</p> <p>· What are the specific challenges associated with archiving in Latinx and settler colonial contexts? </p> <p>Participating in this hybrid, arts and technology course that will combine both conceptual and practical methods, you will develop production skills in digital liberal arts as you interrogate social networks as scholarly and activist texts. Specifically, you will learn to create and access databases, and to develop archive-oriented websites using HTML, CSS, and the web-centered programming language, PHP. While no previous knowledge of computer coding or web design is required, students with specialized knowledge in these areas will be offered opportunities for more advanced project work. <em>Additional Core Requirement Met: U.S. Diversity.</em></p> <p><strong>Music and Social Protest</strong> </p> <p>Over the past century, music has played a central role in political and social movements that seek to shift the balance of power in local, national, and transnational contexts. From the songs of the African American freedom struggle to the music of the <em>nueva cancion</em> movement in Chile, from the live performance practice of the Occupy and immigrant rights movements to the raucous sounds of Russia''s Pussy Riot, music has been an important mode of circulating alternative political messages and inspiring rebellion against the status quo. How can music be used to convey political messages and extend the reach of social movements? Why does music enhance cohesion and solidarity among movement participants and/or sway or destabilize oppositional forces? Are there differences between mass-mediated modes of political protest and live, grassroots political performances? When voices raised in song become powerful, what protocols are established to censor and repress them? We will examine these questions in the context of social movements which have inspired mass participation, comparing and contrasting case studies from Europe, Asia, Africa, and the Americas. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8367,2021,663,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/200/musc-295','<div class="desc"> <p>An interdisciplinary course that investigates the music and life of individual composers. Topics vary by semester. Core designations will vary by composer.</p> <p><strong>Fryderyk Chopin</strong></p> <p>We will engage in an interdisciplinary study the music and life of the Polish pianist-composer Fryderyk Chopin (1810-1849), who lived in Paris his entire adult life. To understand Chopin’s music one must understand not only piano repertoire, manufacture, pedagogy, and technique, but also Paris--its art, literature, history, music, theater, science, politics, and medicine. And one must understand what it means to live in exile. In that spirit, students will study these diverse aspects of Paris as well as Chopin''s music. Students from all disciplines are welcome in this course that requires only a reading knowledge of music and invites students to explore Chopin and his music from a wide range of disciplinary perspectives. Individual semester-long projects will be tailored to each student''s particular interest in Chopin, and may include, to name a few examples, piano performance, socio-cultural and historical analysis, or the XML encoding of Chopin''s music based on the standards of the Music Encoding Initiative. Additional Core Requirement Met: Regional Focus.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8369,2021,2560,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-348','<div class="desc"> <p>Students learn the art and craft of mixing and mastering music, as it applies to the many creative and technical considerations involved in creating a professional music mix. Using Pro Tools as our main Digital Audio Workstation, all aspects of mixing and mastering will be covered, including in-depth explorations of built-in and third-party plug-ins. By the end of the course, students will have completed weekly assignments using existing pre-existing audio and midi stems and will have produced an original work that is mixed and mastered to industry standards.</p> </div>','MUSC 247, Pro Tools Fundamentals ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8370,2021,1541,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-350','<div class="desc"> This course approaches musical form and genre from a stylistic point of view. Intense focus on details at both the surface and background levels of musical activity -- melodic, harmonic, rhythmic, and sonic (texture, density, articulation, dynamics, timbre) -- will yield a broad understanding of the ways in which all aspects of musical language influence musical form and style. Readings will reinforce the connection between culture and style, yielding discussion of issues around links between intellectual history and musical genre. For example, why did the fugue evolve and flourish during the Enlightenment and the Scientific Revolution? What happened to opera''s da capo aria after the 18th century, and why? Repertoire will be chosen in conjunction with students, and may include works from the Renaissance to the 21st century. The final project will be an analytic paper and a classroom presentation based on this work. </div>','MUSC 250 and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8371,2021,1717,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-351','<div class="desc"> <p class="sc-BodyText">This modular course, together with its corequisite applied musicianship component, will explore extensions of chromatic harmonic practice through the turn of the 20th century, the musical language of iconic 20th-century composers (Schoenberg, Stravinsky, Debussy, Bartok), and additional topics chosen by the instructor in collaboration with students and Music Department colleagues.</p> </div>','MUSC 250 or permission of instructor. Requires concurrent enrollment in MUSC 250A ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8372,2021,2601,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-358','<div class="desc"> <p>This course focuses on the technical and aesthetic aspects of composing and recording music for picture that use various synchronization methods (MIDI sequence, click track, SMPTE timecode). Students will compose and record up to three projects, combined with live players, and score short films created by Media Arts &amp; Culture majors for their Senior Comprehensive. May be repeated one time for credit.</p> </div>','Music 258 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8373,2021,290,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-374','<div class="desc"> <p class="sc-BodyText">Preparation for junior recital. Requirements include more extensive practice expectations as well as research and preparation of program notes. Approval of the department required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8374,2021,957,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-385','<div class="desc"> <p>Topics vary by semester.</p> <p><strong>Bach’s Cycles: Bach, Musical Systems, and the Enlightenment. </strong>This seminar will explore stylistic and structural issues in several monumental works of Bach. Two points of view will be taken: analytic, and musico-sociological. Works to be studied include the Goldberg Variations, the unaccompanied sonatas and partitas for violin, the unaccompanied suites for cello, the Well-Tempered Clavier, the Art of Fugue, and the Musical Offering. Topics for papers and presentations will be developed with attention to seminar participants’ particular interests. A course grade of B- or better, and satisfactory completion of a minimum of 15 pages of written work will satisfy the College’s second-stage writing requirement as implemented by the Music Department. Prerequisite: MUSC 250 (may be taken concurrently). </p> <p><strong>Music and Food.</strong> This interdisciplinary research seminar will examine the relationship between music and food and thus hearing and taste in Europe and the United States beginning with the 16th-century category of musical composition called “table music” and culminating in the present-day gastropub. Along the way we will explore topics such as the 18th-century emergence of aesthetics as a branch of philosophy the rise of the restaurant and gastronomy Dandyism and Decadent literature and “fine dining” in the United States. We will read scholarly literature from the fields of philosophy history cognitive science sociology literature and music. Students will carve out an area of research early on and develop it over the course of the semester culminating in a research presentation and final argument-driven research paper. The course will conclude with the recreation of a historical banquet.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8377,2021,666,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/300/musc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8378,2021,292,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/400/musc-474','<div class="desc"> <p class="sc-BodyText">This course provides individual coaching and advisement to students preparing to present their senior comprehensive project. May be repeated once for credit</p> </div>','Junior Standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8379,2021,293,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/musc-music/400/musc-490','<div class="desc"> <p class="sc-BodyText">In this fall semester seminar students will work through a staged process to complete a draft of their senior comprehensive paper. In this critical persuasive essay students will engage recent scholarship in the fields of musicology ethnomusicology and/or music theory in order to develop and support an original thesis. Students undertaking research and/or fieldwork for their senior comprehensive projects will produce a complete draft of their twenty-five page (6250 word) critical essay. Students undertaking composition conducting instrumental or vocal recitals for their student comprehensive project will write a thesis-driven ten-page (2500 word) paper that explores a musical topic related to the materials they will present. Recitalists will also research and produce a draft of their recital program with program notes while composers will complete their recital portfolio and begin work on their recital program. Over the course of the semester students will discuss and share their work as well as analyze and discuss exemplary academic papers program notes liner notes and music reviews in order to develop their ability to write about music for academic and non-academic audiences in compelling ways.</p> </div>','Junior Standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8381,2021,689,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-104','<div class="desc"> <p>This particular section is for serious trainers who want to concentrate on the development of the physique through a strenuous strength and plyometric program. We will execute specific exercises designed to develop explosive muscle mass and definition.</p> </div>','Prior powerlifting experience is required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8382,2021,304,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-121','<div class="desc"> <p>Instruction in regularly scheduled practices with competitive intercollegiate club opportunities. Open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8383,2021,305,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-123','<div class="desc"> <p>Instruction in regularly scheduled practices with competitive intercollegiate club opportunities. Open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8384,2021,306,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-124','<div class="desc"> <p>Participate in weekly Club Sports Women''s Rugby practices and competitive intercollegiate club opportunities. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8385,2021,307,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-125','<div class="desc"> <p>Includes performing at athletics games, spirit rallies and other onj-campus events. Off-campus competition/s vary by year. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical. Auditions will be held during the Fall Semester. Full year commitment required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8386,2021,308,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-126','<div class="desc"> <p>Includes performing at athletic events, spirit rallies and other on-campus events. Off-campus competition/s vary by year. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical. Auditions will be held during the Fall Semester. Full year commitment required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8387,2021,309,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-127','<div class="desc"> <p>The United States Tennis Association (USTA) promotes cardio tennis as a group activity featuring a circuit of drills that consistently elevate the heart rate into the aerobic training zone. Short cycles of high intensity work-outs and periods of rest similar to interval training. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8388,2021,310,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-128','<div class="desc"> <p>Spin I is an introductory course designed to expose students to the terminology and movements of cycling while preparing them for the advanced rides of Spin II. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8389,2021,311,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-129','<div class="desc"> <p>Students will learn the fundamentals of hip hop dance and will gain experience in learning hip hop choreography. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8390,2021,691,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-130','<div class="desc"> <p>General fitness activities consisting of strength, agility and stretching exercises. The goal of this class will be to provide opportunities for participants to improve their overall fitness through class participation and increased knowledge to be applied once the class concludes. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8391,2021,692,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-131','<div class="desc"> <p>Spin II is an advanced cycling course for students who have completed Spin I or who can demonstrate proficient knowledge of terms and riding ability. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8392,2021,312,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-133','<div class="desc"> <p>Class concentrates on improving overall fitness through the use of an aerobic weight training program. Circuit training is a combination of high-intensity aerobic and resistance training primarily through the use of weight machines. It is idealto help control body weight tone muscles and improve cardiovascular fitness. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8393,2021,313,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-134','<div class="desc"> <p>Learn the fundamentals and history of the practice of Yoga. Over the course of the semester the practice will become more and more challenging and in depth; making gains in strength flexibility and the mental aspects of Yoga. Focuses will include: breathing techniques proper posturing different styles of Yoga the physiological side mental side and meditation side of Yoga. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8394,2021,866,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-135','<div class="desc"> <p>This intensive course focuses on sport-specific training injury prevention strength-building conditioning and fitness programming. The class is designed for the advanced athlete and includes strength training plyometrics and aerobic conditioning with specific application to athletic performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8395,2021,1720,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-147','<div class="desc"> Participate in weekly Club Sports Men''s Ultimate Frisbee practices and competitive intercollegiate club opportunities.Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8396,2021,314,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-148','<div class="desc"> Participate in weekly Club Sports Women''s Ultimate Frisbee practices and competitive intercollegiate club opportunities. Open to all current full-time students in good standing holding a grade point average of 2.0 or above. Membership dues may apply. Completion of the Club Sports Clearance process is required including a sports physical. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8397,2021,315,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-149','<div class="desc"> <p>Analysis of basic offensive and defensive techniques used in Karate including time speed and knowledge of body leverage. Cognitive knowledge of defense methods and their employment are also learned. Special emphasis on Shotokan Karate. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8398,2021,1127,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/100/phac-150','<div class="desc"> Zumba is a high-energy fusion of Latin and International music with unique dance moves that sculpt and tone the body. The aerobic routines feature fast and slow rhythms to maximize caloric output and fat burning. Even if you have never danced or tried group exercise, Zumba is a perfect introduction to dancing for health. The movements are basic enough that anyone can follow, yet challenging enough that you never get bored. Course fee $125. </div>',NULL,NULL,NULL);
