INSERT INTO course_descriptions VALUES(8439,2021,2925,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phac-physical-activities/200/phac-274','<div class="desc"> <p>This course will teach techniques of conditioning, leadership and strategy for intercollegiate competition in women''s track and field. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8440,2021,294,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/100/phil-101','<div class="desc"> <p>This course introduces students to the central philosophical skills of critical thinking, careful reading, and analytical writing. Students will engage with a range of both historical and contemporary philosophical texts, from multiple regions and time periods, and with a range of philosophical questions that reflect the four content areas that structure our curriculum: (1) History of Philosophy, (2) Diversity in Philosophy, (3) Self &amp; Community, and (4) Mind &amp; World.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8441,2021,2679,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/100/phil-150','<div class="desc"> <p>This course introduces students to symbolic models of the structure of arguments, and to tools for representing those structures and evaluating them as patterns of good or bad arguments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8443,2021,2561,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/100/phil-199','<div class="desc"> <p>This course will be an introduction to case-based reasoning in practical ethics and political philosophy. Students will learn basic philosophical tools for analyzing the moral or ethical dimensions of practical problems, with an emphasis on medical or health related cases and policy. Heavy emphasis will be placed on speaking and critical thinking. May be repeated once for credit. Graded on a CR/NC basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8444,2021,864,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-210','<div class="desc"> <p>We will address some of the fundamental issues in epistemology and metaphysics while reading selections from the works of some important philosophers from the modern period (1600-1800). Among the issues addressed will be the existence of the external world, the relation between the mental and the physical, and the foundation of our knowledge of the future. Philosophers covered will include Descartes, Leibniz, Locke, Berkeley, Hume, and Kant.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8445,2021,2693,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-211','<div class="desc"> <p>This course will explore how central figures in the history of moral philosophy grapple with fundamental questions, such as: What is the best life for a human being? Should I be good? Can I be good? What are our obligations to others, both friends and strangers? Philosophers covered will include Plato, Aristotle, Kant, Mill, and Nietzsche.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8446,2021,2799,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-212','<div class="desc"> <p>Existentialist philosophy is primarily concerned with questions of authenticity, value choice, and freedom: What does it mean to live an authentic human life? Are we free to choose the kinds of people we are and the values we embrace? And what do such possibilities mean for our obligations to other people? In this class we will discuss the problems raised and solutions proposed by existentialist philosophers such as Kierkegaard, Nietzsche, Heidegger, Sartre, Camus, and Beauvoir, through critical examination of their major writings. Our aims will be to understand the intellectual motivations for existentialist thinking and the relevance of their arguments and positions for contemporary philosophy and contemporary life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8447,2021,2800,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-220','<div class="desc"> <p>This course will philosophically examine the concept of race and the way race informs identity. Topics include the reality of race, the origins and nature of the concept, and the extent to which race does and should impact our social and personal identities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8449,2021,2680,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-222','<div class="desc"> <p>This course will explore the relation between knowledge and power, focusing on epistemic dimensions of racial and gender oppression. The course will address the following questions: (1) How does propaganda operate, and what sort of threat does it pose to equality in the United States? (2) How do ideologies entrench privilege and injustice, and how can we counteract false beliefs that persist in the face of strong opposing evidence? (3) Is there a distinctively epistemic form of injustice, and, if so, what does this form of injustice look like? The authors that will be discussed may include Michel Foucault, Miranda Fricker, Sally Haslanger, José Medina, Tommie Shelby, and Jason Stanley.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8450,2021,3012,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-223','<div class="desc"> <p>This course is an introduction to Mexican philosophy, and indirectly to Latin American philosophy. We will discuss Mexican contributions to universal questions (such as the nature of art, democracy, humanity, and racial, sexual, and ethnic identity), and we will raise the question of Mexican philosophy (what is it, how is it different from Western philosophy) by situating it in the context of other cultural expressions of Mexican identity, such as Mexican food, literature, and Mexican muralism. Thus, this course is also an introduction to comparative philosophy more generally, since it aims to challenge Eurocentrism by demonstrating that philosophy is grounded in or is an expression of cultural identity. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8451,2021,296,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-230','<div class="desc"> <p>Philosophical thinkers have asked a series of related questions about how to live: What is happiness? What kinds of human activities give our lives meaning? More generally, how must a person live to have lived well? This course will examine a variety of answers to these questions. As a significant component of the course, students will practice living within one of the traditions we study, and reflect upon that experience.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8452,2021,2802,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-231','<div class="desc"> <p>This course will examine the ethical dimensions of our relationship to non-human animals and the environment, including a special emphasis on climate justice as the site of interconnected and global moral, political, and scientific concerns. Some of the questions we will address include: What is the relation between the environment and human health and well-being? Are there reasons other than human health and well-being for protecting the environment? Do nonhuman animals have rights? Do trees? Are we morally permitted to eat/experiment on/keep in zoos/hunt nonhuman animals? How do we compare environmental values against other values in making reasonable decisions?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8453,2021,2803,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-232','<div class="desc"> <p>This course will draw on philosophy, literature, and film in order to address some of the central topics in philosophy of religion. The questions that the course will address include: Does God exist? What is faith, and when, if ever, is it rational? Do we survive our bodily deaths, and if not, should we fear death? The course will also consider implications of answers to these questions for the meaning and value of our lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8454,2021,2695,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-233','<div class="desc"> <p>This course is an introduction to the methods of ethics developed for addressing moral issues in the practice of health care and research. Methods addressed will include: professional ethics (practice standards and professional norms), casuistry, the principles of biomedical ethics, applied normative theory, feminist bioethics, and narrative ethics. We will use these methods to address a host of topics of concern to those participating in health care institutions either (directly) as providers or (somewhat less directly) as policy makers. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8455,2021,2804,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-241','<div class="desc"> <p>Paradoxes and their resolution have played a significant role in the development of philosophy; they still have an influence on philosophy today. While Zeno''s paradoxes of motion where first posed about 2000 years ago there is still not a consensus about what to say about them. Semantic paradoxes such as the liar paradox and the paradoxes of vagueness reveal problems with everyday concepts such as truth and implication. Supertasks reveal problems with our understanding of infinity. What to say about these problems what they show us about how to understand space, time, infinity, truth, and reasoning are some of the issues we will discuss in this class. We will examine various paradoxes, puzzles, and purported paradoxes and discuss different proposed resolutions to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8456,2021,2805,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-242','<div class="desc"> <p>An introduction to the study of the mind and its relation to the body, the nature of human agency action, and personal identity. Questions to be investigated include: Is the mind identical to the brain, or is it something separate and immaterial? Is it possible for computers to think, to have consciousness, and to engage in actions that can be assessed as right or wrong? What makes someone the same person at two different times? Could you continue to exist after the death of your brain with a prosthetic brain, carbon or silicon based, into which your beliefs, desires, and memories have been infused?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8457,2021,2696,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-243','<div class="desc"> <p>This course will explore the relationships between the ways we describe the world and the nature of the world we describe. We will explore such questions as: Do different languages describe the world differently? Do different descriptions of the world correspond to different conceptions of it? Is the world a different place for those with different understandings of it? Could the world be other than it is, and how do we talk about these alternative possibilities? Are there limits to what we can express, and how do those limits correspond to the limits of what there is?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8461,2021,2463,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/200/phil-299','<div class="desc"> <p>This course is centered around understanding, and engaging deeply, with applied ethics cases developed for the Intercollegiate Ethics Bowl. These cases typically deal with a broad array of contemporary issues, such as immigration rights, the ethics of self-driving cars, gun control, race/gender on college campuses, etc. In the course, students will research realistic ethical cases, work in teams to develop thoughtful ethical analysis of these cases, and articulate these analyses both verbally and in writing. Throughout the semester, students will prepare for the regional Ethics Bowl competition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8462,2021,298,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-310','<div class="desc"> <p>A detailed examination of some central philosophical texts from the 17th and 18th centuries. Topics vary by semester.</p> <p><strong>Kant''s <em>Critique of Pure Reason</em></strong></p> <p>This course will consist in a detailed study of selected parts of Immanuel Kant''s <em>Critique of Pure Reason</em> – the most important and influential 18<sup>th</sup>-century work on philosophical issues about the relationship between mind and world, and an attempt to synthesize and build upon the rationalist and empiricist approaches to those questions. We will also read selections from some of the central figures in the traditions to which Kant is responding (including Rene Descartes as an exemplar of the rationalist tradition, and David Hume as an exemplar of the empiricist tradition), in order to contextualize the motivations for Kant''s project, and to frame the issues with which the <em>Critique of Pure Reason</em> is engaged.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8463,2021,2807,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-311','<div class="desc"> <p>Ludwig Wittgenstein (1889-1951) is a central figure in the two most important philosophical traditions of the twentieth century: First the attempt early in the century to characterize language thought and the world in terms of the newly available formalism of modern logic and second the attempt to show that any such formalization will fail to do justice to the rich complexity of language as a form of life a form inseparable from the social and historical context from which it springs. We will examine two principal works the <em>Tractatus Logico-Philosophicus </em>and the <em>Philosophical Investigations</em>. There will also be some treatment of the historical and philosophical context of Wittgenstein''s work and life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8464,2021,959,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-312','<div class="desc"> <p>Søren Kierkegaard (1813-1855), sometimes referred to as “the father of existentialism”, was a sharp critic of modern philosophy, institutionalized religion, and what he called “the present age”. For Kierkegaard, the fundamental problem of philosophy was to describe what it means and what it takes to become human—suggesting, ironically, that it is possible for a human being not to be human. The primary purpose of this course is to read Kierkegaard’s most influential texts closely, situate them in their historical and philosophical context (namely, early 19th Century Western Europe), and draw out their contemporary relevance, paying particular attention to the concepts of irony, anxiety, despair, love, and faith. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8465,2021,2808,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-313','<div class="desc"> <p>Fyodor Dostoevsky’s <em>The Brothers Karamazov</em> is a gripping story of murder and romantic rivalries, a wonderfully inventive literary work, and one of the finest philosophical novels ever written. We will read all of <em>The Brothers Karamazov</em> and discuss some of the main philosophical issues that it addresses. Furthermore, we will consider these issues in light of 19th-century Russian culture, and society. Course topics will include: (1) the conflict between faith and reason, and the role – if any – that faith occupies in a good life (2) the nature of love, and the meaning and significance of the command to “love your neighbor” (3) what it means for human beings to flourish, and what sort of community makes flourishing possible. We will also discuss more recent philosophical work and film on related topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8466,2021,2643,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-320','<div class="desc"> <p>Contemporary health issues often raise deep ethical and theoretical concerns. In this course, we seek to connect philosophical and theoretical work on social justice with contemporary issues in health, such as abortion, trans* health, disability rights, domestic violence, international inequities, and health disparities. As a key component of this course, students will partner with a community organization for a semester-long research project, identifying an issue of practical importance to that community and offering an original, theoretical analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8467,2021,2809,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-321','<div class="desc"> <p>James Baldwin explored, with extraordinary sensitivity and insight, issues of race, poverty, and sexual difference in America. In this course, we will engage with Baldwin’s essays, novels, and plays, together with related philosophical work and film, in order to explore the some of the main philosophical themes in Baldwin’s work. We will focus on the roles that love, truth-telling, and self-knowledge play in living a morally good life and in creating a just society.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8468,2021,2935,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-322','<div class="desc"> <p>This course examines philosophical reflections on the Latinx experience, focusing on the contributions of US philosophers of Latin American decent. A sample of questions to be considered: What does it mean to be authenticallyLatinx? Is Latinx identity a racial, ethnic, or political identity? What are some of the overarching lessons of Latina feminist philosophy? Are Latinxs, particularly immigrants, a threat to “American” values, as some argue? What is the meaning of “Latinx” and why is the “x” important? Is Latinx philosophy unique, distinctive, valuable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8469,2021,685,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-330','<div class="desc"> <p>This course is an examination of the relationship between law and morality. It is organized around three questions: (1) What is law, and what is the relationship between law, morality, and democracy?, (2) Is there a moral obligation to obey the law?, (3) Can we morally enforce the law, that is, is punishment morally justifiable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8470,2021,3687,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-331','<div class="desc"> <p>This course focuses on some issues in moral philosophy that arise for us as reflective and responsible citizens in a multicultural world. Topics for discussion will include: to what extent am I free and to what extent am I the product of circumstances beyond my control? What is the nature of moral agency and moral responsibility? How can I live authentically and establish my own identity? How ought I to relate to the majority and minority cultures that surround me and of which I may be a part?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8471,2021,299,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-340','<div class="desc"> <p>This course examines what science is and how science works. That we have clear and determinate answers to questions about the nature of evidence, reasoning and truth is assumed by the scientific enterprise, while philosophical examination shows these assumptions to be far from justified. By exploring the concept of evidence, the concept of truth, and the practices of reasoning in science, the course will analyze under just which conditions scientific claims are justified and what this means about the relation between scientific theorizing and truth.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8473,2021,2697,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-342','<div class="desc"> <p>This course will examine: (1) the theories of knowledge of such philosophers as Price Russell and Chisholm ("Foundationalists"), (2) some of their critics such as Sellars and Quine, and (3) recent work in naturalized epistemology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8474,2021,3817,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-343','<div class="desc"> <p>In the second half of the 20th century, the new field of cognitive science came into existence. This course explores the developments in the history of philosophy, mathematics, biology, psychology, and computer science that culminated in this new science of the mind, including the theory of computation, from the work of Leibniz in the 17th century, the pioneering work on computing and programming by Charles Babbage and Ada Lovelace in the late 19th century, to Turing''s work in the early 20th century. We will explore how developments in both theoretical and applied computer science and logic led to the field of artificial intelligence and computational neuroscience, and we''ll explore the philosophical questions about the possibility and scope of machine intelligence. One prior course in cognitive science, philosophy, or mathematics is recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8475,2021,2681,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-344','<div class="desc"> <p>What is a language? And what is it to know, to speak, or to understand a language? This class will investigate the project of developing a systematic and comprehensive theory of linguistic meaning: what resources such a theory requires, what kinds of claims it makes, and what consequences it has. We will proceed by examining philosophical questions about the role translation between languages plays in a theory of meaning, about the nature of linguistic reference to the world, and about whether the notions of language and meaning are ultimately coherent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8476,2021,961,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-345','<div class="desc"> <p>How is it possible to study the mind scientifically? This class will explore philosophical issues about the application of scientific methods to cognitive phenomena, including questions such as the appropriate architecture of cognition, the possibility of artificial intelligence, the relation between commonsense psychology and theories in cognitive science, and the possibility of a scientific understanding of consciousness.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8478,2021,686,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-350','<div class="desc"> <p>This course surveys results in the metatheory of first order logic including consistency, completeness, decidability, and undecidability.</p> </div>','PHIL 150 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8479,2021,301,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-360','<div class="desc"> <p>What makes something, someone, or some place beautiful? Why do we value beauty? These questions will be explored across multiple domains, including: art, the natural world, the built environment, and human practices, including norms for human bodies. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8480,2021,2682,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-361','<div class="desc"> <p>Philosophical wondering begins in childhood: Where do words come from? Can trees think? What is love? At the heart of this course, Occidental students will have the opportunity to teach philosophy to elementary students at a local school. Doing so provides both an opportunity to serve the local community, an opportunity to reconnect with our own philosophical impulses, and a chance to reflect deeply on a variety of philosophical topics (such as friendship, courage, minds, justice). Occidental students will develop and teach their own lesson plans. In order to do so, students will select a children’s picture book, identify a philosophical question raised by the book, review and selectively incorporate academic philosophical texts. In addition, the class will discuss philosophical views on young children, the nature of philosophical wonder/inquiry, and the value of a (philosophical) education, e.g. Rousseau''s Emile, excerpts from Plato, Marx, and contemporary philosophers.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8481,2021,2698,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/300/phil-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8482,2021,302,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phil-philosophy/400/phil-490','<div class="desc"> <p>Open only to students with senior standing in philosophy.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8484,2021,694,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-110','<div class="desc"> <p>Covers classical mechanics including kinematics and dynamics of particles and rigid bodies conservation laws and examination of specific force laws. <em>Includes one three-hour laboratory per week.</em></p> </div>','Calculus I (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8485,2021,318,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-115','<div class="desc"> <p>The first of a two-course introduction to physics designed for life science and premedical students. Topics include Newton''s laws of motion gravitation work and energy conservation laws. Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</p> </div>','Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8486,2021,1617,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-117','<div class="desc"> <p>An introduction to the physics of waves with examples from optics acoustics and modern physics. Also an introduction to thermodynamics including the first and second law of thermodynamics kinetic theory heat transport and phase transitions. Includes one three-hour lab per week.</p> </div>','PHYS 110 or PHYS 115; and Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8487,2021,696,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-125','<div class="desc"> <p>The second of a two-course introduction to physics designed for life science and premedical students. Topics include electrostatics and electromagnetism electric circuits geometrical and physical optics. <em>Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</em></p> </div>','PHYS 110 or PHYS 115; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8488,2021,867,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-161','<div class="desc"> <p>Exploration of physical laws and processes through simple and geeky-cool devices and demonstrations many of which students will build themselves and keep. The toys will illuminate topics from across physics including classical mechanics thermodynamics electricity and magnetism. Course Fee: $125.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8489,2021,322,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-162','<div class="desc"> <p>A survey of the solar system, stars and stellar evolution, galaxies and cosmology. Students are expected to have a strong understanding of algebra and trigonometry. Physics majors cannot take this course for credit.<s></s></p> </div>','Passage of the equivalent of High School Algebra is required ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8491,2021,1081,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-164','<div class="desc"> <p>Identical in all respects to PHYS 165 except that there is no lab component. Students attend regularly scheduled lectures for PHYS 165, do the homework, and take the PHYS 165 exams.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8492,2021,3692,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-165','<div class="desc"> <p>An introduction to optics and modern physics for both science and non-science majors. Topics include geometrical optics physical optics waves special relativity wave-particle duality atomic and nuclear physics. Includes one three-hour laboratory per week.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8493,2021,1186,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-166','<div class="desc"> <p>An introduction to the theory of special relativity for both science and non-science majors. Topics include Einstein''s postulates the geometry of relativity the Lorentz transformations and the structure of spacetime.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 120, or PHYS 125; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8495,2021,698,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/100/phys-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8496,2021,2835,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-230','<div class="desc"> <p>Introduction to electricity and magnetism electronic circuits electromagnetic induction and Maxwell''s Equations. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8497,2021,699,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-240','<div class="desc"> <p>Introduction to the physics of the twentieth century emphasizing special relativity and elementary quantum mechanics. Includes the breakdown of classical concepts; light quanta and matter waves; Schrödinger equation and solutions in 1 and 3 dimensions; hydrogen atom exclusion principle and the periodic table. Other topics include a selection from atomic nuclear particle and condensed-matter physics. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115, PHYS 117, and PHYS 120; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8499,2021,323,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-261','<div class="desc"> <p>An introduction to the numerical solutions of problems in physics. Applications are drawn from classical dynamics electrostatics magnetostatics relativistic dynamics and chaotic systems.</p> </div>','PHYS 110 or PHYS 115, PHYS 120 or PHYS 125, and COMP 131; or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8500,2021,964,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-262','<div class="desc"> <p>Theoretical and experimental electronics fundamental to modern research. Includes one three-hour laboratory per week.</p> </div>','PHYS 120 or PHYS 125; or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8504,2021,868,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-266','<div class="desc"> <p>An introduction to the theory of relativity. The first half of the course focusing on special relativity includes discussions of the relationship between space and time; mass and energy; and cause and effect. The second half of the course presents the fundamentals of the general theory of relativity with an emphasis on the physics of black holes.</p> </div>','PHYS 110 or PHYS 115; and PHYS 120 or PHYS 125; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8505,2021,1128,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-267','<div class="desc"> <p>An introduction to the field of engineering. Students who have completed either of the introductory sequences in physics are well prepared to apply that knowledge to a wide variety of subjects. Applications covered include static equilibrium elastic properties of materials vibrations thermodynamics thermal properties of matter fluids waves and sound DC circuits and AC circuits.</p> </div>','PHYS 110 or PHYS 115; and PHYS 120 or PHYS 125 (may be taken concurrently); or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8506,2021,1619,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-268','<div class="desc"> <p>An introduction to the physics of materials used in a wide range of engineering applications. As time permits topics will include the mechanical, elastic, thermal, electrical, magnetic, and environmental properties of metals, polymers, ceramics, glasses, composites, and "green" materials.</p> </div>','PHYS 240 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8507,2021,2472,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/200/phys-269','<div class="desc"> <p>Special topics in physics selected largely by student interest and requiring no more than introductory physics courses. Possible topics include: variational methods celestial mechanics chaos nonlinear systems. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8510,2021,324,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-310','<div class="desc"> <p>Survey of the elements of advanced mathematical ideas and techniques typically used in physics. Physical examples and intuition will be emphasized throughout. Topics covered will include Div Grad and Curl; matrices tensors and groups; complex analysis Fourier series and integrals; boundary and initial value problems; and special topics as time permits. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 117 and PHYS 120; and MATH 214 (may be taken concurrently with permission of instructor); or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8511,2021,325,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-315','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques, including literature search, analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8512,2021,702,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-316','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques including literature search analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8513,2021,326,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-320','<div class="desc"> <p>Motion of particles systems of particles and rigid bodies. conservation laws; coordinate transformations both stationary and moving; Hamilton''s and Lagrange''s equations. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 117, PHYS 120, and MATH 214; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8514,2021,703,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-330','<div class="desc"> <p>Electro- and magneto-statics Maxwell''s equations electrodynamics boundary value problems radiation. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 310 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8515,2021,705,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-340','<div class="desc"> <p>The foundations of the theory of quantum mechanics with applications to physical systems. Formal development of the postulates of quantum mechanics representation of states angular momentum spin and perturbation theory. Applications include the harmonic oscillator hydrogen atom and Zeeman effect. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 240 or CHEM 305, and PHYS 310, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8516,2021,2354,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-350','<div class="desc"> <p>Connects the microscopic properties of the physical world with its macroscopic properties using classical and quantum statistics. Topics include partition functions classical and quantum ideal gasses classical thermodynamics phase transitions and kinetic theory. Includes one ninety minute laboratory per week.</p> </div>','PHYS 240 and PHYS 310 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8518,2021,1300,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-362','<div class="desc"> <p>At the turn of the century a series of discoveries transformed the ancient study of cosmology into a rigorous and well-tested theory of the universe. After a brief introduction to general relativity the equations governing the evolution of the universe will be developed and explored. Evidence in support of this standard model of cosmology and consequences will then be presented including supernovae standard candles the cosmic microwave background big bang nucleosynthesis dark matter and early-universe physics. The course will conclude with a presentation of recent topical subjects in this exciting field of study.</p> </div>','PHYS 117 and PHYS 240, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8521,2021,707,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-365','<div class="desc"> <p>Survey of the contemporary status of the quantum physics of subatomic particles and atomic nuclei. Emphasis is given to discussing and examining the fundamental constituents of matter (quarks and leptons) and the fundamental forces of nature (electromagnetism the strong nuclear force and the weak nuclear force). Topics include the classification and relationships among particles properties of nuclei and nuclear interactions (such as fission and fusion) electroweak and quantum chromodynamic interactions and the unification of the fundamental forces of nature. Applications to and insights derived from astrophysics and cosmology will also be included. Specific topics covered will be selected by the instructor.</p> </div>','PHYS 310 and PHYS 320 (may be taken concurrently); or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8522,2021,2476,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-366','<div class="desc"> <p>Review of special relativity. Introduction to the fundamentals of general relativity and gravitation with applications to cosmology. Topics include the big bang theory primordial nucleo-synthesis the dark matter problem gravitational red shift and the expansion of the universe stellar evolution and black holes.</p> </div>','PHYS 310 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8525,2021,1187,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-369','<div class="desc"> <p>Special topics in physics selected largely by student interest. Prerequisites vary with subject area. Possible topics include: group theory in physics applications of quantum mechanics in atomic nuclear and particle physics introduction to relativistic quantum mechanics nonlinear pattern forming systems hydrodynamic instabilities superfluidity and superconductivity methods of material science. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8526,2021,328,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-395','<div class="desc"> <p>Research supervised by a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8528,2021,709,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/300/phys-397','<div class="desc"> <p>Supervised investigation by properly qualified students. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8530,2021,1301,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/400/phys-490','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8531,2021,1484,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/400/phys-491','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8533,2021,710,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/phys-physics/400/phys-499','<div class="desc"> <p>Supervised investigation by students admitted by the department to the Honors Program. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8534,2021,330,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/100/pols-101','<div class="desc"> <p>This course introduces students to the study of politics the discipline of political science and the development of public policy. Politics involves the study of power influence and ideas in public and private life at the personal local state national and international levels. Accordingly our exploration will examine how power operates in a variety of settings and will include readings in political theory American politics and law comparative politics research methods and international relations. Open to frosh and sophomores.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8535,2021,1670,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/100/pols-120','<div class="desc"> <p>Introduction to the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8537,2021,1423,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/100/pols-140','<div class="desc"> <p>Law shapes the day to day experiences and functioning of individuals, communities, and institutions in multiple ways. This introductory course examines the diverse connections and relationships of law and society. The course will draw on theoretical and empirical perspectives from a diverse range of disciplines (such as legal studies, sociology, anthropology, and political science) to explore law and law’s role within the United States and internationally. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8538,2021,1553,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/100/pols-150','<div class="desc"> <p>This course is an introduction to the study of politics and political theory through prominent Western political theorists from the Ancient Greeks to the 20th Century. Course themes include theories of human nature the origins of law and government the rise and development of different political institutions and citizen relationships with the state.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8539,2021,712,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/100/pols-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8540,2021,338,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/copy-of-pols-295','<div class="desc"> <p>Topics in Politics. Can be repeated once for credit if topics differ.<em>NOTE: Different topics may satisfy different Core Program requirements</em>.</p> <p><strong>Climate Change and Global Justice</strong></p> <p>Many activists and advocates have argued in recent years that climate change is not only an environmental problem, but a problem for global justice. How might theories of global justice help us understand climate change? How does treating it as a question of global justice change the way we understand and respond to climate change? Who is responsible for global climate change? This course explores these questions by studying debates over the ethics of global climate change.</p> <p>Our study will be organized into two main sections. We will begin by asking the question, is climate change a question of global justice? To answer this question, we will begin by studying theories of justice, or different accounts of what counts as an injustice. Then, we will turn to climate change to analyze climate change through the lenses of both intergenerational and international justice. We will also discuss the question of responsibility: who should bear the burden of responding to climate change? The third section of the course will focus on applying the ethical principles of justice and responsibility to the questions of designing institutions and policies that can effectively respond to climate change. We will close with a discussion of our responsibilities as citizens for climate justice. Core Requirement Met: Global Connections.</p> <p><strong>Politics of Immigration</strong></p> <p>Immigration is one of the most hotly contested issues in American politics, and has been for some time. Much of the debate about how to craft immigration policies has come from politicians at the national level in the U.S. Congress, which has the responsibility to create policy, but important voices in the debate also come from state legislatures and community organizations. In this class, we will learn about the central issues regarding immigration that have emerged in both the body politic and in scholarly discourse. Topics addressed will include: why people migrate, why anti-immigrant sentiment is prevalent, the politics of immigration control policies, demographic trends, and notions of exclusion and inclusion. Our goal in the class is to come to a better understanding of the political process regarding immigration and why it matters. Core Requirement Met: United States Diversity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8541,2021,2744,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8542,2021,2480,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-201','<div class="desc"> <p>This course examines how the mass media affects democratic politics in the United States. In the U.S., the media is comprised of various news sources, including mainstream news outlets (e.g., ABC, CBS, NBC, The Washington Post, The New York Times), cable news shows (e.g., CNN, Fox News, MSNBC), online blogs, talk radio, online video platforms, and satirical political comedy shows. In the growing Internet age, news is also delivered via social media (e.g., Facebook, Twitter, Snapchat), giving individuals a vast array of diverse political information. In this course, we aim to understand how information is delivered to citizens, what impact it has on them, and how the media may affect public policy. In general, in this class we work toward a better understanding of the media’s role in American politics.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8543,2021,331,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-203','<div class="desc"> <p>The goal of the Campaign 2020 Internship class is to provide students with an experiential understanding of the practice of electoral campaigns. This course must be taken in conjunction with the POLS 204, Campaigns and Elections. Together, the two courses allow students to gain a deep understanding of the theory and practice of electoral politics in the United States. For Fall 2020, students will actively participate in an internship with a campaign of their choosing in their hometown or the Los Angeles County District Attorney’s race, which the <em>New York Times</em> has called the most important DA race in the country because of growing concern about the problems within our criminal justice system, including racism, policing, and incarceration. The internships will be done remotely, so it doesn’t matter whether students are living at home or on campus. Students will be expected to participate in their internship at least 8 hours per week during the fall semester. Students will schedule their internships for times that are mutually convenient to themselves and their campaign supervisor. Paired with the exploration of scholarship of Campaigns and Elections in POLS 204, students will connect the concepts learned in the classroom to their experiences in the campaign internships. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 204',NULL);
INSERT INTO course_descriptions VALUES(8544,2021,1303,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-204','<div class="desc"> <p>Students in this course will analyze historical and contemporary election campaigns in the United States, exploring such issues as the role of money, media, public opinion, voter registration laws, voter suppression, campaign strategy, staffing, and other topics. They will also examine the role of identity, alternative electoral systems and campaign reform options. The course will offer a particular focus on the most current election season, including campaigns for president, Congress, governor positions, and others. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 203 ',NULL);
INSERT INTO course_descriptions VALUES(8545,2021,1424,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States and to assess how these communities seek political empowerment as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life such as the economy the state and the cultural system on the one hand and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States.; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications based on race class gender national origin and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8546,2021,332,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-206','<div class="desc"> <p>This course is an exploration of the historical and continuing significance of race in the American political system. The relevance and role of race in shaping political institutions public opinion political behavior and public policy will be examined. Special attention will be given to theoretical debates surrounding the meaning of race and how this changes depending on political context.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8547,2021,966,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-207','<div class="desc"> <p>This is a course about urban politics that takes Los Angeles as its case study. Because of the pattern of growth in the area Los Angeles is broadly defined to encompass the city the county and the region. Since politics is the study of power we will examine power in the context of the city; who has it who seeks it how has it shifted over time and what consequences result from it being exercised? Significant attention will be paid to the agency of those who have at various times had the least power in the city; how are they represented or not represented how can they influence the exercise of power? Many look to Los Angeles as a paradigmatic city. We will query the appropriateness of this observation as we identify key concepts in urban politics apply them to Los Angeles and then consider how much Los Angeles sets follows or deviates from trends.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8548,2021,1029,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-208','<div class="desc"> <p>Examination of the impact that social protest movements have had on our society -and lessons that can apply to the current period. Case studies of the agrarian revolt (the Populists) the labor movement the women''s movement the civil rights movement the peace movement the student movement the environmental movement and the consumer/neighborhood movement. Topics include: What factors lead people to participate in social movements and political protest? Why do certain historical periods seem to feature large-scale protest and upheaval while others do not? How are social and political movements related to mainstream politics such as elections political parties voting and lobbying? What is the role of leaders activists and organizers? What strategies and tactics do movements employ? What does "success" mean for a protest movement? Do protest movements make a difference in achieving more social justice and changing public policy? In addition to classroom discussion attendance at a weekly film series is required.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8549,2021,1304,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-212','<div class="desc"> <p>This community-based learning course introduces advanced undergraduates (sophomores juniors and seniors) to the study of voter mobilization via an ethnographic research project in Los Angeles. As part of the Fall congressional elections students will partner with community organizations in Los Angeles that are developing non-partisan Get Out the Vote (GOTV) initiatives. These organizations are based primarily in Latino/a and Asian-American communities. Students will study and evaluate these GOTV initiatives with the goal of analyzing assessing and reporting back on best practices in GOTV initiatives especially in ethnic minority communities. Course time will be divided between the classroom and the field. Students will receive training in and learn to critically evaluate field research methods-especially in the area of qualitative ethnographic research (interviews and observations). Students will also learn about the strategies practices and pitfalls of voter mobilization practices in urban communities. Offered Fall semester in even-years to coincide with the national elections. <em>Open to sophomores juniors and seniors with permission of the instructor only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8550,2021,1485,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-221','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century with a focus on contemporary democratic politics. The course will discuss the historical institutional and social forces that have both accelerated and opposed democratization and will cover topics of current concern to the region including economic development security and the rule of law the design of political institutions human rights and social movements.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8551,2021,1620,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-223','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal" "populist" and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems including the United States; and the challenges democracies are facing in integrating formerly marginalized populations including women poor and the indigenous. It will examine the US policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8552,2021,715,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-226','<div class="desc"> <p>This course is an introduction to 20th Century Chinese politics. The course will explore the historical background to the current Chinese situation. Students will also examine the politics of China under Mao and during the subsequent reform period including the role of China in global politics.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8553,2021,1305,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-227','<div class="desc"> <p>A comparative analysis of the history culture and contemporary politics of the four countries in the dynamic East Asian region: China Japan Korea and Taiwan. This course will also cover the political economy of the East Asian industrialism.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8554,2021,1030,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-232','<div class="desc"> <p>This course is an undergraduate survey of the field of international political economy (IPE). It is intended as an introduction for students who already have some background in the field of international relations and are interested in exploring international economic relations at a deeper level. The course covers major theoretical empirical and policy perspectives. The theme to be explored in this course is "National Interest vs. Global Governance?" - that is we will explore the theory and history of international political economy as an extension of national interest and an arena for the development of global governance and the question of whether or not these two dimensions of international political economy are compatible or competitive with each other. The first part of the course will cover the basic concepts and theoretical foundations of IPE. The focus is on core theoretical principles and approaches. The goal is to understand how theory is framed and "works" the potential inferences of this theory and the issues of contention within the field. The second part of the course draws on the theoretical foundations to examine a set of specific international economic issue arenas including international trade finance and economic development.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8555,2021,1031,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-233','<div class="desc"> <p>This course is an introduction to international security and strategic studies. This field is fundamentally about both the use of force by and violent conflict among states and non-state actors. The course will be guided by general theoretical questions regarding security: How does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: How do states and non-state actors use force to persuade their enemies to take (coercion) or refrain from taking (deterrence) a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure the intensity duration and consequences of military action? We will have a particular focus on emerging transnational security issues intra-state security and the relationship among security development and state failure. Pursuing answers to these questions will require an approach that integrates theory history and current events.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8556,2021,1082,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-235','<div class="desc"> <p>This course focuses on the evolution of U.S. foreign policy in recent Administrations with special emphasis on the post-Cold War period. Attention is paid to American policy toward "emerging issues" for example the global environment development policy in the North/South dialogue ethnic violence and nationalist civil wars human rights and humanitarian relief. It explores how policy is formulated and implemented and analyzes the relationship of foreign policy to American economic and defense policies. It examines U.S. policy toward major regional power configurations-in Europe the Far East Latin America the Middle East South Asia and Africa.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8557,2021,2355,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-243','<div class="desc"> <p>Politics 243 provides an introductory examination of the values, principles, and practices of restorative justice. The course will draw on examples of restorative justice from the United States and internationally. Topics in the course will include competing theories of justice, informal and formal approaches to restorative justice, truth telling, reconciliation, and process of reintegration. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8558,2021,335,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-244','<div class="desc"> <p>This course provides an introduction to constitutional law and constitutional theory examining the ways in which the Constitution distributes power among the branches government in the American political system and limits the exercise of those powers. The course will also consider the role of the judiciary in creating legal and political boundaries for society. Throughout the semester this course will focus not only on legal doctrine but also on the broader intellectual and political context in which it evolves. Using constitutional law cases and moot courts the course will explore the role of the United States Supreme Court as a civil liberties policymaker and the process through which decisions are reached. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8561,2021,1621,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-250','<div class="desc"> <p>American intelligence has often been at the center of the major national security controversies since the 1945. This course will survey the history of those controversies as they involved the US intelligence community, the outbreak of the Cold War and the US-Soviet competition but also the post-Cold War crises in Europe Asia Middle East and elsewhere. The basic question is: How does intelligence influence foreign policy and strategic decisions? This course provides an overview of the theory and practice of U.S. intelligence. It details the sources and methods used by collectors the nature of intelligence analysis and the complex and often difficult relationship between intelligence agencies and policymakers. It also contains a short history of the U.S. intelligence community and evaluates the ongoing efforts to reform it in an era of greater transparency. <em>Not open to first year students.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8562,2021,1032,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-254','<div class="desc"> <p>This course will examine American political thought as it sets out and responds to the founding of the country. Specifically, we will read the Federalist papers, consider the impact of the American Revolution on the French Revolution, and explore how thinkers have reckoned with the American founding into the 21st century.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8563,2021,1306,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-256','<div class="desc"> <p>This course will introduce students to several core analytical approaches in moral and political philosophy including consequentialism utilitarianism distributive justice freedom autonomy and an ethics of care. Students will apply these approaches to case studies in ethical decision-making in politics and policy and students will weigh arguments in favor or against specific courses of action. As such this course bridges readings in moral and political philosophy with "real world" problems confronted by policymakers and leaders. In evaluating resolutions to these problems students will sharpen their critical-thinking and decision-making skills. This is a course in applied ethics with material drawn both from philosophy and from policy.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8564,2021,969,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-257','<div class="desc"> <p>This seminar surveys the historical roots of modern conservative and libertarian political ideas with particular attention to the persistent tension between tradition and innovation. The purpose of the seminar is to enable students to recognize recurring themes that have shaped political thought and action over several thousand years. Students will be graded on weekly essays and seminar participation.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8565,2021,720,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-258','<div class="desc"> <p>Is “racism” the appropriate concept to describe our contemporary racial problems? Many scholars have rejected the idea that the persistence of a number of racial ills – like racial inequality, racial discrimination and racial segregation – in the contemporary moment is evidence that racism also persists as a problem in the twenty-first century. “Racism,” these scholars argue, more accurately describes the Jim Crow South and the people in that era who consciously held explicit beliefs about white superiority over all other races. Though acknowledging changes in racial climate and the terrain of acceptable speech with regards to race, other scholars think that unequal racial outcomes, institutional practices and ideological beliefs connect our contemporary racial problems to racial problems that occurred in the 1960s and earlier. This course is an introduction to the scholarship on racism and has as a central aim to get us to judge together whether “racism” is the appropriate concept to describe and provide a frame through which to understand our contemporary problems concerning race. If it is, which accounts of racism are the most compelling to shed light on our current racial circumstances? What about these accounts are particularly pertinent? What can’t the accounts of racism addressed in class explain? If racism is not the right concept to capture our current struggles with race (or all aspects of it), what concepts if any do a better job and why? To facilitate a critical interrogation of the concept racism, this course will cover sociological, historical, social psychological, philosophical and political accounts of racism and related concepts like racial injustice, racial prejudice, race relations, and racial inequality.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8566,2021,1486,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-260','<div class="desc"> <p>The goal of the Community Law Internship is to provide students with an experiential understanding of the practice of public interest law and community lawyering. The Community Law Internship must be taken simultaneously with Politics 241which establishes the theoretical foundation for the co-requisite courses through the exploration of scholarship in the areas of: progressive legal practice community collaboration critical reflection social justice activism and community organizing. The Community Law Internship allows students to learn through direct experience about the practice of public interest law in Los Angeles as well as examine how social structures and related identity categories such as gender race ability sexual orientation and class interact on multiple levels to create social inequality. All students enrolled in the Community Law Internship work with a community-based legal organization engaged in public interest law practice a minimum of 12 hours each week. The unique approach of integrating Politics 240 and Politics 241 takes advantage of Occidental faculty expertise and the wide-range of community-based educational opportunities available in Los Angeles. Permission of instructor required.</p> </div>',NULL,'POLS 340',NULL);
INSERT INTO course_descriptions VALUES(8567,2021,721,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-264','<div class="desc"> <p>This course is a "hands-on" experience requiring students to live in New Orleans for most of January working to rebuild and restore the city while studying the politics of disasters disaster recovery federalism local politics grassroots politics activism race and public policy. <em>Permission of instructor required.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8568,2021,722,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8570,2021,1307,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-270','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, POLS 272) simultaneously. Students will participate in the daily activities of a campaign for United States President or United States Senate in a key "battleground" state. Students will gain experience in the highest level of politics and gain an understanding of how a national presidential campaign or a statewide United States Senate campaign is operated. Students will learn about political strategy voter contact and turnout messaging and polling communications volunteer recruitment and team-building fundraising and other key aspects of campaigns. The internship will involve working full-time (a minimum of 40 hours a week) from the first day of class until Election Day. Following that ten-week campaign fieldwork internship students will return to campus and participate in two seminars as part of Campaign Semester. Campaigns involve long hard days. The staff that students will work with will typically be working at least 14-16 hour days. Although students are required to work at least 8 hours a day they are likely to work more. As part of the Campaign Fieldwork Internship students will be required to read three books-biographies of each major party candidate and a book describing previous presidential campaigns. Students will be required to maintain an internship journal that will be handed in at the end of the 10-week internship. The journal will describe their activities (including the projects they work on campaign meetings and events relationship of the campaign to the media and to constituency groups) the internal dynamics and work of the campaign the different roles and tasks of staff and volunteers in the campaigns the way the media reports on the campaign the students'' reflections on these matters and at the end a summary of the campaign outcome. Students will be required to email the supervising Occidental faculty member at least once a week about their activities and reflections. The students will be supervised in the field by a campaign staff member. Students will participate through teleconferencing in a two-hour course meeting with other students and faculty three times during the semester. Students who will be working in different parts of the country will stay in touch with each other as well as with the faculty through Moodle a web-based course management system. The system allows faculty members to post readings facilitate discussions give and receive assignments etc. Students in various parts of the country will thus form a virtual classroom and on-line learning community. Some students may wish to document their experiences on the campaign trail observe events and interview staff and volunteers by making videos. If so these should be posted to the faculty and other students via the internet. Enrollment limited to students participating in the Campaign Semester Program.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8571,2021,1308,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-271','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. In this course which will take place during the last five weeks of the semester students explore theoretical and applied concepts pertaining to United States political campaigns. Students will examine the role of money media candidates interest groups leadership gender race and political parties in terms of who wins and loses elections. Learning will take place through assigned readings professor lectures guest lectures from campaign experts and candidates and peer dialogues. Student learning will be assessed by their contribution to the classroom experience (discussion dialogue) discussion of assigned readings and examinations. Enrollment limited to students participating in the Campaign Semester Program. The program is open to all Oxy students regardless of major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8572,2021,1309,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-272','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. This course entails production of a 25-page research essay addressing a major question pertaining to campaigns in American politics. Each student will work with a professor to craft a high-quality research paper that enters the academic debate on their selected topic incorporates extensive secondary data and existing research and presents original analysis based on the student''s campaign fieldwork. Enrollment limited to students participating in the Campaign Semester Program. Satisfies Junior Writing Requirement.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8573,2021,1343,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-280','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics credits for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> will work four full days per week in an internship in a political office non-profit corporation or for-profit company engaged in political or policy work. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8574,2021,1344,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-281','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course develops leadership skills through the themes of public speaking professional writing networking interviewing and giving and receiving feedback. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirements for the major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 280 and POLS 281 and either POLS 282 POLS 283 POLS 284 POLS 285 or POLS 286) simultaneously. </p> <p>Students enrolled in the Washington Internship Institute in D.C. are required to take a political leadership seminar that explores how active global citizenship can advance career goals. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8575,2021,1554,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-282','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on environmental law and public policy. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(8576,2021,1555,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-283','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on public health policy in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286).</p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(8577,2021,1556,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-284','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on women''s leadership in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(8578,2021,1345,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-285','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on politics and public policy in the Washington D.C. context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(8579,2021,1346,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-286','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on international relations. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills International Relations requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281 and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously.</p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C</strong>. are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(8580,2021,2837,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-287','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8581,2021,340,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/200/pols-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,'POLS 295',NULL);
INSERT INTO course_descriptions VALUES(8582,2021,1310,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-300','<div class="desc"> <p>This course is an introduction to the process of conducting political science research including the formulation of research problems research design collection of data and statistical analysis and interpretation. Participants will learn to analyze political science data using statistical packages in a lab setting.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8583,2021,1347,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty housing transportation crime and violence pollution racial segregation and neighborhood change. It also examines how power is exercised by different groups including business citizens'' groups community organizations unions the media mayors and other government officials. The course will also examine the role of city planning and planners conflict and cooperation between cities and suburbs problems of urban sprawl loss of open space water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe Canada and the developing world. Public policies to solve urban problems.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8584,2021,1557,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-302','<div class="desc"> <p>This course examines the institution and practices of the American presidency. More specifically it encourages students to analyze the role and structure of this office as well as different ideas about presidential power and influence. Particular attention is paid to the presidency and policy making media coverage checks and balances the Constitution and public opinion.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8585,2021,1622,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-303','<div class="desc"> <p>This course examines how gender roles influence social position political engagement and allocation of power and resources in American society. Students will investigate why masculinity is often an attribute of those in power and why "femaleness" correlates with disadvantages in affluence value in society and public policies. Students will also determine what changes in the conditions of men''s and women''s lives might change the gender dynamics of politics.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8586,2021,1671,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-320','<div class="desc"> <p>Critical examination of the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8587,2021,1623,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-321','<div class="desc"> <p>This course will explore the role of women in politics throughout the globe with an emphasis on case studies from the developing world. Students will examine the development of policy changes that advance gender equality paying attention to how the international system domestic institutions and social movements play in this process. Students will also study how women attain and wield power in local and national politics. The course will further emphasize how gender politics intersects with other forms of identity politics including race ethnicity and sexuality. The course is grounded in the study of comparative politics and will draw primarily on examples from Latin America Africa the Middle East and Asia.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101, POLS 120, or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8588,2021,341,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-336','<div class="desc"> <p>This course is an examination of how American national security policy is conducted and explores the principles practices and problems related to contemporary American foreign policy making. The course will touch on the basic historical patterns of American foreign policy; however it will focus on current practices and operation of the foreign policy machinery in Washington as well as examine some contemporary cases to demonstrate how the system works. Close attention will be paid to the structures of national security decision-making involving the Presidency and the National Security Council the Congress the Departments of State and Defense as well as the Intelligence Community and other new national security agencies. For Politics, UEP, and DWA majors only.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8589,2021,1487,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-340','<div class="desc"> <p>Pursuing effective change particularly in today''s complex world requires creative collaborative efforts to identify and implement solutions to achieve a more radically participatory democracy. Rebellious Lawyering considers the related theories of legal scholars who have reconceptualized legal practice to transform systems through both legal and community knowledge. This scholarship has been defined as rebellious lawyering third-dimensional lawyering collaborative lawyering democratic lawyering and community lawyering. All of these theories impart a common vision of lawyering for social change in stark contrast to the traditional or regnant model. The praxis of Rebellious Lawyering (POLS 340) and Community Law Internship (POLS 260) creates a balanced context from which students develop critical consciousness question assumptions of power privilege and identity learn to respect community decision-making capacities expand their understanding of the importance of relationships in the pursuit of social change and remain open to learning from the lived-experiences" of the community. The unique co-requisite course design allows students to engage in a weekly seminar (POLS 340) work as law clerks in community-based public interest legal service organizations (POLS 260) and interact with Los Angeles activists and lawyers as part of a speaker series. Instructor permission required. Can be repeated once for credit.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,'POLS 260 ',NULL);
INSERT INTO course_descriptions VALUES(8592,2021,1311,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-345','<div class="desc"> <p>This course examines constitutional criminal procedure through an analysis of Fourth Amendment constitutional restraints on activities during the investigatory stage of the criminal process. Exploring Supreme Court decisions through doctrinal analysis and simulations the course questions the Supreme Court as a policymaker seeking to balance privacy rights with governmental intrusions.<em> Not open to first year students.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or instructor permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8593,2021,1735,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-346','<div class="desc"> <p>An advanced course in constitutional law and theory with a specific focus on civil rights and civil liberties. Course topics may include, civil rights under the Fourteenth Amendment, and civil liberties including privacy, marriage, speech, reproductive autonomy, voting or freedom of expression. The goal of the course is to critically engage students in understanding how the Supreme Court has deemed certain rights and liberties as fundamental to society. The course approaches Supreme Court decisions as reflective of a larger social narrative of rights and justice.Throughout the course students will consider the role of the law in creating political boundaries within society.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8594,2021,1084,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-347','<div class="desc"> <p>Understanding how the law has defined race is of critical significance to the study of politics and the experience and history of race and race relations in America. The course examines definitions of race within legal precedent and how the law has created racial identities. The course considers the relationship between race and law in many different manifestations from the colonial period to the present day to understand theses complex intersections.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8595,2021,2484,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-351','<div class="desc"> <p>Alexis de Tocqueville, John Stuart Mill, and Friedrich Nietzsche are three of the most influential theorists to grapple with the tradition of liberal political thought. The first two are friendly critics who seek to fortify liberalism against what they see as its latent pathologies, while Nietzsche is a not-so-friendly critic who wants to overturn it entirely. Given that liberalism is under attack today from both the right and the left, there is much to gain from serious study of their reflections. In this course, we will compare the strengths and weaknesses of their diagnoses of the present and visions for the future. Guiding questions for the course will include the following: Does liberal democracy uplift human beings, or degrade them? How should the competing demands of individual independence and community solidarity be balanced? How can we best counter modern society’s tendency to engender stifling conformity? What is the significance of Christianity for the cultural heritage of Western society? What role, if any, should religion play in societies of the future? Finally, what does human flourishing consist of, and what kind of sociopolitical conditions best facilitate it? The culminating assignment of for the course will be a substantial research paper on one or more of these thinkers.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 150 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8596,2021,1312,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101, BLST 110, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8597,2021,1672,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-355','<div class="desc"> <p>Franz Fanon, one of the most influential thinkers of the twentieth century, is a canonical figure in critical theory, broadly, and Black studies, postcolonial theory, political theory, critical race theory, continental philosophy and Africana philosophy, specifically. A francophone scholar, Fanon identified as black and was concerned with articulating the modern problem of white supremacy and the conditions for liberation for all people.</p> <p>This course is organized around a single book he wrote, <em>Black Skin, White Masks</em>. To understand what Fanon is up to in this text, we will also consider this book’s relationship to the philosophical traditions of psychoanalysis and phenomenology. To this end, we will read texts by Sigmund Freud, Anna Freud, Maurice Merleau-Ponty, Simone de Beauvoir, Jean-Paul Sartre, Jacques Lacan, and Georg Wilhelm Friedrich Hegel. Throughout the course we will switch between two distinct but related enterprises. On the one hand, we will try to understand how Fanon uses the specific set of psychic problems black people face and his articulation of the lived experience of the black in a white world to articulate his account of white supremacy and liberation. And on the other hand, we will seek to understand what his psychoanalytic and phenomenological counterparts are up to in their text to discern the significance of Fanon’s work in relation to the concerns within these philosophical traditions.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8598,2021,3157,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8599,2021,725,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/300/pols-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8600,2021,726,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pols-politics/400/pols-495','<div class="desc"> <p>Politics majors are required to take Politics 495 in fulfillment of their senior comprehensive obligation. They therefore should have met or be in the process of meeting all requirements for the major. The Seminar meets in the spring semester but students will be expected to submit proposals for their research papers in the fall semester prior to the actual meeting of the Seminar. The Seminar itself will engage all students in an analytical review of a wide range of materials from various aspects of the discipline and will require that students write a major research paper in one particular sub-discipline of the field. Students qualifying for College Honors will be given an opportunity to write research papers that will be evaluated by the department for honors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8602,2021,1130,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/100/psyc-101','<div class="desc"> <p>Introduction to the primary subject matter areas assumptions and methods of psychology as the science of behavior. Topics include: physiology, learning, perception, motivation, development, emotion, cognition, social processes, personality, and psychopathology. <em>This course is a prerequisite for all upper division coursework. Open only to frosh and sophomores. Core Credit only when taken at Occidental. Students with a 4 or 5 on the AP Psychology exam or a 6 or 7 on the IB Psychology exam are not eligible for Psych 101 but may take 200- or 300-level classes.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8603,2021,1190,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/100/psyc-111','<div class="desc"> <p>The average adult possesses over 50000 concepts ranging from physical concepts like "force" and "density" to biological concepts like "growth" and "reproduction" to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich revise and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive developmental and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8605,2021,344,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/200/psyc-200','<div class="desc"> <p>Introduces scientific methodology in the context of psychological research. Basic concepts in scientific inquiry and specific observational correlational and experimental techniques are covered. Includes an introduction to descriptive statistics. This course is a prerequisite to many 300-level courses in Psychology.</p> </div>','PSYC 101 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8606,2021,345,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/200/psyc-201','<div class="desc"> <p>Introduces parametric and nonparametric inferential statistics used in psychological science through analyses of variance appropriate to complex experimental designs. Includes a review of research methods and descriptive statistics and work with the SPSS computer statistics package.</p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8607,2021,346,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/200/psyc-223','<div class="desc"> <p>This highly interactive seminar draws on theoretical, empirical, and narrative essays as well as structured in-class activities to provide students with an intellectual, applied, and personal understanding of contemporary intergroup relations. Course topics include: social identity development and implications; prejudice, stereotyping, and group differentiation; privilege, power, and oppression dynamics; conflict negotiation and resolution; and communication and group facilitation skills. Social justice issues are framed for gender, race, class, sexuality, and ability. Effective dialogue seminars are inclusive and enhanced by the participation of diverse identities, multiple disciplines, and a range of political perspectives. Placement form can be found at this link: https://oxy.qualtrics.com/jfe/form/SV_d4pBn2ZnPXYoC8Z Students must complete the placement form prior to advising week.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101, completion of placement form prior to beginning of advising week, and permission of instructor. Students with a background in any introductory social science course are encouraged to consider the seminar. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8608,2021,2563,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/200/psyc-224','<div class="desc"> <p>This course provides students with an intellectual and practical foundation in dialogue<em> facilitation</em>. Participants will <em>apply</em> intergroup relations theory and knowledge about culturally diverse populations as they learn about and attend to group dynamics, conflict management, and intergroup relations pedagogy. Specific attention will focus on multicultural dialogues devoted to Sexual Orientation, Social Class, Race, Gender, and Ability. Training videos and exercises, in addition to small group co-facilitations form the foundation of the course. Group work, including pedagogical development meetings, are required outside of class as preparation for facilitation. </p> <p>Applications due by March 23, 2018. Contact the Professor Rodriguez (jackir@oxy.edu) for application information.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 223 (may be taken concurrently) and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8609,2021,347,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/200/psyc-295','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. Instructor permission required. <em>Graded on a Credit/No Credit basis only. PSYC 101 or PSYC 102 or relevant introductory course in another department and permission of instructor. May be repeated once for credit if the second project is different from the first. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8611,2021,731,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-301','<div class="desc"> <p>This course will introduce general concepts of learning in humans and other animals that will be rooted in the principles of learning developed from nonhuman animal research. Explores fundamental concepts phenomena and principles of learning such as reinforcement Pavlovian conditioning and retention/forgetting. Issues addressed are traditional views of learning biological and cognitive constraints the role of nonhuman animal models and the utility of learning theory.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8612,2021,971,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-302','<div class="desc"> <p>This course focuses on how sensory systems function, with emphasis on quantitative methodologies, neurophysiological mechanisms, structure/function relationships, and ecological contexts. How humans perceive the world is situated in a comparative landscape -- that is, human are assumed to be creatures with much in common with other creatures and yet different in some crucial ways tied to their evolutionary history and habitats. Attention is paid to phenomenology and philosophical issues, such as the relationship between perception and "reality." This course is distinguished from cognitive or social psychology approaches to perception, by virtue of its focus on evolutionarily old, fully embodied, and sensuous experience.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8613,2021,871,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems make decisions draw inferences attend to their environment communicate remember and learn. Much of the material is applied to real-life settings.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8614,2021,2491,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-309','<div class="desc"> Ontogentetic approach to human movement behavior and physical growth from conception to adulthood with emphasis on maturational and environmental factors. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8615,2021,2492,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological mechanical and cognitive bases of motor skill acquisition. <em>Includes one three-hour laboratory per week. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8616,2021,2493,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'PSYC 310L',NULL);
INSERT INTO course_descriptions VALUES(8617,2021,1736,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-311','<div class="desc"> This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance and level of participation of an individual or group. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8619,2021,348,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-321','<div class="desc"> <p>The study of continuity and change across development. Emphasis on application of research methods to issues related to cognitive emotional personality and social development. The course will focus primarily on these issues in infancy and childhood.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8620,2021,349,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-322','<div class="desc"> <p>The study of neural glandular and metabolic processes mediating behavior thought and feelings. This course is identical to PSYC 312 except that students who enroll in PSYC 322 may enroll concurrently or subsequently in the laboratory (PSYC 322L). Core Laboratory Science credit will only be awarded for students completing both PSYC 322 and PSYC 322L. Students who have received credit for PSYC 312 may not enroll.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 <div id="offered"></div>',NULL,NULL);
INSERT INTO course_descriptions VALUES(8621,2021,350,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-322l','<div class="desc"> May be taken concurrently with Psychology 322. </div>','PSYC 200 (Students must earn a grade of C- or better) and PSYC 322 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8622,2021,351,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-323','<div class="desc"> <p>Behavior of individuals and groups in and across social contexts. Topics include self social cognition attitudes and persuasion liking and loving prejudice aggression and social conflict group identity consciousness and social action.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8623,2021,352,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-330','<div class="desc"> <p>The study of psychopathology including diagnosis and classification core dysfunctions and physiological and psychosocial causative factors. Intervention treatment and preventative strategies will also be discussed.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8624,2021,736,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-334','<div class="desc"> <p>Consideration of psychological influences on health and illness including health-and illness-promoting behavior and lifestyles cognitive and emotional processes and social and institutional practices.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 (Student must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8625,2021,972,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-336','<div class="desc"> <p>This course surveys the emerging field of Evolutionary Psychology. It begins with the historical social and political context of evolutionary theory reviews tenets of modern evolutionary theory explores the relationship between evolution and other change processes and applies evolutionary reasoning to psychological phenomena and contemporary social issues.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8626,2021,353,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-340','<div class="desc"> <p>Introduction to the study of theories and applications of psychology in profit and not-for-profit organizations. Representative topics include understanding how ability personality perception motivation leadership and group dynamics affect productivity and worker satisfaction. Issues of fairness and accuracy of assessment will also be discussed. Emphasis is on practical and personal learning of the dynamics of the work environment.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8627,2021,354,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-350','<div class="desc"> <p>The course will survey diverse psychological perspectives on gender and its personal and cultural implications. Will explore: meanings of gender evolutionary physiological developmental and sociocultural roots of gender difference; the relation of gender to cognition personality sexuality health interpersonal relationships and political power; the commensurability of various theoretical approaches to gender.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8628,2021,2513,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-351','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','PSYC 101, COGS 101, LING 301, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8629,2021,872,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-385','<div class="desc"> <p style="margin-left:0in; margin-right:0in">The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101, SOC 101, HIST 102, AMST 101, or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8630,2021,355,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-395','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required.<em>Graded on a Credit/No Credit basis only.</em></p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8632,2021,738,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/300/psyc-397','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8633,2021,1489,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-400','<div class="desc"> <p>This capstonecourse will help senior psychology majors to integrate across subdisciplines in psychology consolidate their experiences in the psychology major through review and discussion of primary coursework in psychology and connect their studies in psychology to the roles that psychology plays in society and the professional world. <em>Open only to students with senior standing in psychology (i.e. intended for graduating seniors).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8635,2021,1086,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-403','<div class="desc"> <p>A study of the relation between psychological states and processes (cognition learning emotion psychopathology) and physiological response processes (autonomic nervous system responses covert muscle activity EEG FMRI). <em>Includes six three-hour laboratories per semester.</em></p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 200 or COGS310; and PSYC 322, PSYC 306, PSYC 330, PSYC 301, PSYC 448 or permission of instructor ','PSYC 403A <div id="offered"></div>',NULL);
INSERT INTO course_descriptions VALUES(8636,2021,1348,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-403a','<div class="desc"> Additional meeting time for Psychophysiology. </div>',NULL,'PSYC 403',NULL);
INSERT INTO course_descriptions VALUES(8637,2021,2905,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-420','<div class="desc"> <p>Introduction to the psychosocial and neurobiological basis of addiction. Substance abuse and behavioral compulsions, including drugs, gambling, eating, and sexual addictions are examined. Additional focus on diversity in addicted populations, the business and politics of drugs, and prevention. Consequences of addictions will be studied at the individual, family, community and societal levels. This course will draw on current research and controversies in the field of addictions. </p> </div>','PSYC 200 , and one of the following: PSYC 322, PSYC 330, or PSYC 334. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8638,2021,873,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-428','<div class="desc"> <p>The study of social cognitive physical and psychological development during adolescence and emerging adulthood. Topics include sexual development and the social consequences of being sexually active the function of family support the increasingly important role of peer relationships drug abuse and antisocial behavior and school adjustment.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8639,2021,357,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-431','<div class="desc"> <p>Introduction to the techniques and processes of clinical psychology and psychotherapy. Topics include major schools of thought and approaches, specific techniques of assessment and treatment, relevant research, assessment of effectiveness, and issues of gender and culture. <em>Open only to seniors or by permission of instructor.</em></p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 and PSYC 330 (Students must earn a grade of C- or better in both) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8640,2021,1349,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-444','<div class="desc"> <p>This course will examine contemporary research on higher-order cognition. Topics will include inductive reasoning deductive reasoning causal reasoning moral reasoning concept acquisition belief formation and analogical inference. Students will read empirical papers representing a variety of experimental methods and a variety of theoretical perspectives.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 200 and PSYC 301, PSYC 302, or PSYC 306 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8641,2021,973,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-448','<div class="desc"> <p>Introduction to and evaluation and application of classic and contemporary theories of personality including psychoanalytic humanistic behavioral cognitive and object relations models. Primary sources autobiographies and case studies will supplement traditional texts.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 and PSYC 321, PSYC 323, or PSYC 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8642,2021,974,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-460','<div class="desc"> <p>Psychological assessment involves the measurement and evaluation of psychological characteristics including cognitive ability personality traits motivation and more. A blend of theory-driven research and practical analysis techniques will be covered to explain how common and experimental instruments work and to examine whether certain methods are valid in academic organizational criminal and mental health contexts.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 201; and PSYC 321 or PSYC 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8643,2021,358,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-490','<div class="desc"> <p>PSYC 490 seminars taught by Dr. Dess Dr. Chapman or Dr. Schell can be applied to the Neuroscience minor. </p> <p><strong>Eating: From Cells to Society</strong></p> <p>Eating is fundamental to life more so than drinking or sex. It infuses the thoughts feelings and behavior of humans and other animals and thus serves as a model system for psychological inquiry. It is also for better and for worse intensely personal and thus serves as a model system for inquiry into the self. This course will explore eating from cellular to cultural levels of analysis. </p> <p>Prerequisites: PSYC 200 and one of the following: PSYC 302, PSYC 323, PSYC 321, or PSYC 336.</p> <p><strong>Teamwork Within Diverse Environments</strong></p> <p>Examination of how individual and group differences influence the performance of workgroups. The course focuses on theoretical and practical concerns related to the key topics of teamwork and leadership as they are performed within the context of a diverse work environment. Some related issues of fairness in managing diversity will also be introduced. </p> <p>Prerequisites: PSYC 201 and either PSYC 340 or PSYC 323. </p> <p><strong>Trauma</strong></p> <p>This course focuses on the experience of and responses to trauma in its many forms - natural disaster war and genocide child abuse assault and violence. The impact of trauma for both the individual and society at large are examined in the context of a stress coping resilience framework. Prevention and intervention strategies will be explored. </p> <p>Prerequisites: PSYC 330.</p> <p><strong>Visions of Love and Community</strong></p> <p>This seminar examines love as an interpersonal intergroup and structural experience. We draw from social evolutionary and personality psychology to explore theories of love relationship formation satisfaction and dissolution; the biological bases of attraction; common challenges in relationships (jealousy conflict violence) and critical challenges to "love" within individualistic capitalistic patriarchal and heterosexist societies. Students will better understand how familial interpersonal and institutional relationships shape one''s sense of identification with and communal responsibility for others.</p> <p>Prerequisites: PSYC 200, PSYC 323, and either PSYC 321 or PSYC 448.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8645,2021,874,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-498','<div class="desc"> <p>This course involves applied psychological work in a variety of community settings. Students will assist professionals in mental health educational social services business or not-for-profit settings. <em>Instructor permission is required.</em></p> <p>Prerequisites: PSYC 200 and either PSYC 201 or three courses from the Fundamental Domains. For Practicum in Clinical Psychology one course must be PSYC 321 or PSYC 330. For Practicum in Organizational Psychology one course must be PSYC 340. A minimum grade of C- in all prerequisite course and a B average in Psychology courses are required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8646,2021,739,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/psyc-psychology/400/psyc-499','<div class="desc"> <p>Data collection analysis and write-up of Honors thesis. Depending on the structure and timeline of the proposed project a student may take 4 credits in one semester or 2 credits for two semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8648,2021,2838,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/200/pubh-203','<div class="desc"> <p>This course explores the nation''s public health challenges and the ways that public health functions as a combination of science and politics. The course examines the various social, political, and demographic factors that impact population health. Students are introduced to public health concepts and learn to analyze health problems, considering the influence and intersection of race, status, gender, income, education and sexuality. Using data, evidence, and health behavior theory, students evaluate strategies and solutions to address health inequity and improve population health.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8649,2021,2904,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/200/pubh-206','<div class="desc"> <p>Students will conduct a hands-on internship in Los Angeles County, supervised by the course instructor and in collaboration with a community partner, government agency, community clinic, or public health focused non-profit organization. The internship requires 8-hours each week. The topic of the course is flexible and to be determined by the course instructor. It may be repeated once for credit and does not fulfill a Public Health minor elective requirement. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8650,2021,2938,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/200/pubh-209','<div class="desc"> <p>Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8651,2021,2886,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/200/pubh-238','<div class="desc"> <p>This course is designed to introduce the basic concepts, principles, and methods of epidemiologic research. In our pursuit to understand the interplay of risk factors and patterns of human disease and health, we will cover the history of epidemiology, the principles of epidemiologic thinking and of causal inference, the basic measures of disease frequency and of association, and how to compute them. We will also learn about the major types of epidemiologic study designs and explore the major fields of epidemiologic investigation (such as global health, infectious diseases outbreaks, occupational and environmental epidemiology). To better understand the practical application of study methods used in epidemiology, the class has a laboratory component (PUBH 238L). The laboratory component will provide students exposure to public health related organizations here in Los Angeles County, as well as current local public health issues.</p> </div>','Introductory Biology (BIO 105, BIO 106, BIO 110, BIO 115, or BIO 130) and Statistics (BIO 268, COMP 146, UEP 305, MATH 146, or MATH 150) ','PUBH 238L ',NULL);
INSERT INTO course_descriptions VALUES(8652,2021,2839,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/200/pubh-248','<div class="desc"> <p>The course will examine major global public health problems and the range of responses from international organizations transnational networks and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as HIV/AIDS malaria unsafe food and water tobacco use and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health including morbidity mortality demography epidemiology and the political social and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political economic social and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8656,2021,2840,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/300/pubh-301','<div class="desc"> <p>This course provides an examination of women''s health across the life cycle, with special emphasis on the structural and societal factors that influence health outcomes among women. It introduces students to public health frameworks for assessing women’s health issues within various contexts. This course uses these frameworks as a basis for examining the relationship between social and cultural factors and women’s health. It provides an overview of the emerging and on-going issues in women''s health, including sexual and reproductive health, contraception, gender-based violence, mental health and substance abuse, in order to understand and address health inequities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8657,2021,2841,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/pubh-public-health/300/pubh-307','<div class="desc"> <p>The community health internship course is designed to provide students with real-world experiences to develop new skills and enhance insights into myriad community health issues and solutions. Under supervision of the course instructor and in collaboration with a community proctor/partner students will intern for 8-hours a week at a health focused non-profit organization community clinic or government agency. Through the internship and course work, students explore and analyze the social, cultural, and systematic barriers to health in Los Angeles and the U.S. Students reflect on and discuss the complexities of keeping communities healthy, considering the impact of policy, identity, power, urban planning and culture. Before registering students should check to make sure that they are available during the preset internship hours. Internship hours and activities can be viewed at the Community Health Engagement website: http://bit.ly/1sDCTeJ</p> </div>','PUBH 203 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8661,2021,1559,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-110','<div class="desc"> <p>A survey of historical and contemporary Native American religious traditions, attending especially to how they have developed amid colonization and resistance. Students will study the broad variety of ways that Native American traditions imagine land, community, and the sacred, and study the range of practices, ceremonies, and cultural institutions related thereto. Students will also investigate how these religious traditions have been contested or negotiated when they came in contact with Christian missionaries, in contemporary treaty rights, and in intertribal new religious movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8662,2021,360,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-130','<div class="desc"> <p>This course is a survey of Jewish communities in antiquity from the late Babylonian exile to the emergence of Jewish Academies in the Diaspora. The first half of the course will focus on the formation of Jewish identity and the rise of competing Jewish factions and movements. We will study the central religious beliefs, texts, practices, and institutions that were held in common, yet simultaneously the source of deep division between sects. We will also study how sectarian movements -such as apocalypticism and messianism- were formed in response to Empire (Greek and Roman). In the second half we will consider issues of orthodoxy and heresy, as well as categories of insiders and outsiders. Finally, we will study the crystallization of orthodoxy in the rabbinic movement, considering issues of conversion, inter-religious polemic, conflict, and persecution.</p> <p>Throughout the course, students will engage with questions regarding Jewish identity and the evolving role of Jewish Scripture, its component parts, its interpretation, and its authority. Moreover, students will examine various models of religious leadership and practice, and various conclusions about the nature of God, the afterlife, the Messiah, and non-Jewish peoples.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8663,2021,1035,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-145','<div class="desc"> <p>This introductory course uses two themes- experience and authority- to orient and guide students through an historical survey of religion in the United States. We will ask how people have made appeals to religious experience to establish, reinforce, and challenge political and religious authority. In addition to dominant forms of Protestant Christianity, we will learn about the rise of new religions like Spiritualism and Mormonism, Catholic and Jewish immigration in the late nineteenth century, and the growth of religions like Buddhism and Islam in the twentieth. Throughout the course, we will pay special attention to race and ethnicity, gender, and sexuality, asking how religion has alternately served as a vehicle for liberation and venue of oppression, and how religious debates dovetailed with the pressing social issues of the day.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(8664,2021,1624,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-147','<div class="desc"> <p>In the recent history of the Americas, many groups have founded intentional communities shaped by the ideals of what a faithful, utopian society ought to look like. Some aspiring utopias, like that of the People''s Temple in Jonestown, Guyana, ended in dramatic displays of violence and death. Others, like the Mormons in Salt Lake City, have succeeded in the face of sustained adversity. But most land somewhere in between, sustaining themselves through partial integration with dominant society. In this course, we will study different intentional religious communities - often called "cults" or "sects" by outsiders - throughout the Americas. As we study the Oneidan "free love" community, an ayahuasca church in Brazil, an early Rastafari group in Jamaica, we''ll ask questions like: Why have religious people sought to separate themselves from society? How have they appealed to scripture or revelation to justify their separation? What challenges - such as external political pressure or internal strife - have they faced? What groups have been "successful," and what are the measures of success? And what do these attempts at establishing utopias tell us about what it means to be religious?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8665,2021,742,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-150','<div class="desc"> <p>This course will introduce students to some of the major themes, issues, people, places, sights, and sounds of Islam past and present. This course is intended to highlight the manifold expressions of Muslim life through diverse historical, cultural, and geographical contexts. Its two broad aims are: 1) to provide students with basic knowledge of Islamic history, belief, and ritual life; and 2) to equip students with knowledge for critically and actively analyzing discussions of Islam in media and contemporary world events.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8666,2021,1737,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-155','<div class="desc"> The course surveys the varied, historical dialogue between Islam and the West. The course traces the transformational influence Islam and the West have had on each other from the expansion of the Islamic Empire into Europe, to the eruption of Western modernity and European colonialism and imperialism, and through the reactions in Islamicate cultures to the pressures of Western economic, cultural, and political forces. The course will also examine the way Muslim migration to the West has affected not just Western culture and politics, but has also led to the transformation of Islamic ideas, practices, and identity by "Western" Muslims. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8667,2021,1673,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-160','<div class="desc"> <p>A large part of the success of Buddhism has been in its ability to travel and adapt to local cultural traditions, providing communities with a rubric for living a meaningful life. This course will provide an introduction to these traditions by looking specifically at Buddhist concepts and practices within human life and life cycles. We will ask: What do ritual and textual traditions about human life in various cultures tell us about Buddhist values and concepts of how to deal with suffering and thereby to life and die well? Are there differences between classical textual ideas about these topics and Buddhism as it is lived through ritual and community practice? How do both textual and ritual traditions maintain human life?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8668,2021,2842,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-167','<div class="desc"> The Zen school of Buddhism has long claimed itself as a tradition “beyond words and letters,” or as a body of teachings that can be transmitted only through ineffable experience. And yet, Zen Buddhists have been some of the most productive writers and orators, producing volumes of biographical narratives, religious legends, and apologetic scholarship. In this course we will study Zen sources as a way to understand the social, institutional, and pedagogical power of the Zen school as it grew in Japan from the 12th century. We will seek to understand how Zen Buddhists in Japan balanced their own religious obligations with broader societal responsibilities, as well as how the Zen tradition reconciled its religious ideals with its practical concerns. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8669,2021,2888,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-168','<div class="desc"> This course focuses on the variability and plurality of Buddhism by tracing the development of the tradition across the Silk Road. From the 1st c. CE, Buddhism traveled from India into several other regions and cultures by way of this network of overland routes stretching from North Africa to East Asia. As such this roadway became the channel through which regionally and culturally diverse systems of Buddhist thought, ethics, practices, and concerns were transmitted, adapted, and enculturated. The ultimate goal of this course is to introduce students to the Buddhist tradition in a way that widens the scope of represented practices and doctrines, and to emphasize the critical role that diverse representations must play in the study of non-Western religions generally. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8670,2021,975,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-190','<div class="desc"> <p>From the 1st-6th centuries CE, early Christian communities throughout the Mediterranean had different ideas about who Jesus was, what kind of movement he inspired, and what it meant to be or to act like a Christian. In this course, students will investigate the variety of early Christian communities that structured their movements around the figure of Jesus by studying their primary sources: stories, letters, sermons, theological treatises, art, artifacts and architecture. Students will explore the practices and ethics that dictated the daily lives of early Christians, how they interacted with their Jewish and “pagan” neighbors, the theological issues debated among early Christian communities, including charges of "heresy" and the development of orthodoxy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8671,2021,743,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/100/rels-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8672,2021,2564,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-205','<div class="desc"> <p>What makes a thing, a place or a person sacred? This course focuses on the tangible elements of religion: the materials, objects, spaces, art, blood and guts that inspire belief and community. We will explore the way "things" interact with humans in their processes of creation, interpretation and the (re)definition of the religious, the sacred, the natural and supernatural, the holy, the profane, the secular, the immaterial, and transcendent, grounding our exploration in case studies. Our work will raise our awareness of the significance of materiality in religion and raise questions of authenticity, replication, and commodification. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8673,2021,1738,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-206','<div class="desc"> This course will survey the cultural history of Jerusalem over three millennia, primarily as the symbolic focus of three faiths: Judaism, Christianity, and Islam. Students will examine the transformation of sacred space as reflected by literary and archaeological evidence (studying artifacts, architectural monuments, and iconography in relation to written sources). Students will also examine the creation of mythic Jerusalem through event and experience. By the end of the course, students will better understand the historical roots of modern political and religious conflict in Jerusalem and Israel<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8674,2021,1191,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-215','<div class="desc"> <p>This course explores the dynamic religious and cultural landscape of East Asia, providing an overview of religion as it has been constructed in the states that are today known as China, Japan and Korea. In addition to learning about Confucianism, Daoism, Shintoism, and Buddhism, students will also learn about shamanistic and folk traditions, as well as practices that span across traditions, in order to provide students with tools to resist simplistic understandings of religious identity. Furthermore, taking both a chronological and comparative approach, the course leads students through the development of different traditions by situating them in their broader socio-political contexts. Finally, the course engages with multiple themes and perspectives, including the relationship between religion and the state, the development of institutions, literary and artistic expression, and gendered experiences of religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8675,2021,1037,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-225','<div class="desc"> <p>This course provides an in-depth introduction to the traditions of Islamic mysticism. Students will explore the core teachings and practices of Sufism through the literary artistic and philosophical expressions of the great saints and masters of the tradition including figures like Rumi ibn Arabi Sohrawardi Mulla Sadra and al-Attar. We will situate Sufi thought and practice within broader Islamic thought and practice while attending to the unique modes in which Islamic mysticism has been institutionalized and transmitted.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8676,2021,1351,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-228','<div class="desc"> <p>In this course students will interrogate several overlapping categories of human identity. First we will seek to define the term Chican@ situating our understanding within the historical particularities in which it emerged as well as studying its economic political social and religious implications for U.S. Latin-Americans who identify as such. Second we will investigate the ways in which contemporary Chican@s understand Chican@ and religious identity to be interrelated specifically as a hybridization of Catholic Christianity along with the spiritual traditions of Africa Asia and the indigenous people of the Americas. We will also consider the ways in which Chican@s have looked to their spirituality and religious practices in order to construct narratives of identity belonging community and resistance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8677,2021,1560,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-230','<div class="desc"> In United States history, law has regularly been used to subordinate racial and religious minorities, while law has also been used as a tool in these groups'' struggles for liberation. This course approaches law as a feature of culture, as both a product of cultural (including religious) context and a mechanism to effect cultural change. Students will study cases where religious freedom arguments served to oppress the Queer community, the Disabled community, and Women, as well as cases of struggles for religious liberty among Indigenous, Black, and Mixed communities in the US. By analyzing legal discourse from the lenses of Postcolonial, Feminist, and Critical Race Studies, students will come to understand that law is not neutral or objective and students will better discern how both religion and law operate at multiple, overlapping levels in society, contesting and constructing meaning. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8678,2021,1087,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-232','<div class="desc"> <p>A study of the development of the religion of ancient Israel and its expression in the Hebrew Bible. Special emphasis will be placed on the emergence of the central ideas of Biblical religion which formed the foundation for early Judaism and in time of Christianity and Islam. In addition to close reading of selected Biblical texts in translation attention will be paid to the historical context in which ancient Israel lived and to the findings of modern critical scholarship and archeology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8679,2021,3823,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-235','<div class="desc"> An introduction to the gods and goddesses of the Hindu pantheon. Students will study the mythology, iconography, narrative, and pilgrimage traditions, as well as the various movements -- ascetic, devotional, and Tantric -- associated with Hindu deities. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8680,2021,1088,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-240','<div class="desc"> <p>In this course we will explore the relationship between religion and revolution through a series of case studies from across the Americas. In 1907, a wealthy Mexican landowner named Francisco Madero regularly channeled the spirits of the dead. They instructed him to write a book advocating for democratic reform, which helped ignite the Mexican Revolution of 1910 that led to Madero''s being elected president. In 1930s Jamaica, the Rastafari movement emerged as a potent political force that raised black consciousness and challenged colonial British rule. And in the mid-century United States, a spiritually awake counterculture challenged the status quo and redefined the cultural trajectory of postwar America. Using these case studies, we will ask how religions - through prophesy, apocalypticism, and messianism - can unsettle even seemingly secure polities, as well as how religion can function to maintain the status quo.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8681,2021,746,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-242','<div class="desc"> <p>An exploration of the relationship between religion and environmental ethics. How do various world religions view the natural world and what role do they propose for human beings in nature? What is the history of environmental ethics and how does religion figure in that history? How are religious traditions such as Buddhism Christianity Hinduism Islam Judaism Native American Spirituality and Taoism rethinking their environmental views especially in light of ecofeminism perspectives?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8682,2021,2745,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-243','<div class="desc"> <p>The confluence of three religious faiths in one land—Christian, Jewish, and Muslim communities in the Iberian Peninsula—was a unique situation in Western Europe during the Middle Ages (415-1492 CE). In this course, we will pay special attention to the interaction of these religious communities, their conflict and their cooperation. Students will develop a sophisticated understanding of the cultural and religious settings that gave rise to religious pluralism, and students will become familiar with some of the most important debates about religion – especially ideologies of tolerance and persecution – that have continued to fuel inter-faith relations into the twenty-first century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8683,2021,2889,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-244','<div class="desc"> <p>This class explores the Islamophobic ramifications of racialized Islam and Muslim identities. We will consider “blackness,” “brownness,” and “whiteness” as experienced through Muslim life, as well as how minoritized race and religion combine in ways that lead to fear, opposition, and violence. We will study Islamophobia through a number of American and Global cases, including the issue of iconoclasm (such as the Danish cartoon controversy), the racial and religious coding of various groups (such as Sikhs or Iranians in North America), perceptions of different sects of Islam (including Nation of Islam or the Ahmadiyya), and the political ramifications of these identities (such as recent US elections and the 2020 census). In addition to traditional readings, course materials will include a variety of media, such as longform journalism, memoirs, ethnography, music, and film.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8684,2021,2565,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-247','<div class="desc"> <p>Mythical journeys to otherworldly places are common in Mediterranean cultures, and represent important points of intersection between ancient Near East and Classical cultures. These mythical journeys—which articulated both the divisions and connections between the realms of the living and of the dead—served various objectives: describing heroic actions of central characters (divine or human), symbolizing the quest for secret knowledge, explaining the mysteries of life and death, and/or endorsing a political or economic system through divine precedent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8686,2021,976,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-250','<div class="desc"> <p>What is Religious Studies? Students in this course will answer this question first by tracing the historical formation of the academic study of religion (from monasteries to the university), and across various disciplines (sociology, psychology, anthropology, history, economics, etc.). We will then engage more deeply with the various theoretical and methodological tools available to scholars of religion by reading a range of scholarly works that illustrate these approaches and by giving students the opportunity to practice some of these approaches. In the end, students will become familiar with the landscape of the academic study of religion, will be able to assess the value and limitations of different scholarly approaches to the study of religion, and will have cultivated skills necessary to participate in conversations in the field. Required for Religious Studies majors and minors, recommended in the Sophomore or Junior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8687,2021,2746,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-253','<div class="desc"> <p>Comets, earthquakes, volcanic eruptions. In the early modern world, natural phenomena like these were read as portents or omens, exhibiting sympathies between the natural and supernatural. Set within a period of war, famine, and political instability, these natural disasters generated intense scholarly investigation—by philosophers, religious scholars, and scientists—contributing to the early development of the natural sciences. In this course, we will examine the scientific and religious debates about the causes of these natural phenomena, as well as the range of cultural responses to dealing with natural traumas. We will assess the role of the “natural” in the history of religion and understand the development of scientific authority for interpreting natural phenomena in early modern Europe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8688,2021,2843,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-254','<div class="desc"> <p>A course on gender and health in the history of Islam. The course begins with a study of the various dimensions, expressions, and status of what it has meant--and what it can mean--to be gendered a Muslim "man," "woman," or non-binary person: from the ideas found in scriptural sources, in later legal interpretations, through to historical transformations. Students will then study how legacies from the past are implicated in contemporary discourses and practices related to health and medical care. Students will explore issues related to bridging Muslim understandings of gender with best practices in health care, as well as the ethical reasoning behind gendered healthcare. Finally, students will explore a number of case studies on complicated and controversial issues such as abortion, sex reassignment surgeries, female genital mutilation, and sex positive movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8689,2021,3824,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-255','<div class="desc"> <p>This course will explore ethically and morally questionable stories of the Hebrew Bible that early Jewish and Christian interpreters had difficulty receiving as scripture. In the interpretive tradition, many of these stories are whitewashed, rewritten, or spiritualized in dramatic ways in an effort to find righteous heroes in countless examples of selfishness, faithlessness, deception, and violence. We will study the various kinds of interpretive strategies employed by early Jewish and Christian communities in the Ancient Near East, as well as dynamic methods of interpretation that allow the biblical text to stand on its own in all its beautiful and messy ambiguity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8690,2021,2604,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-256','<div class="desc"> <p>Tibetan Buddhism is a globally recognized religion, with the Dalai Lama, red-robed monks, prayer flags, and prayer beads occupying a unique position in the popular imagination. These images, though, flatten the diversity and historical complexities both of the Buddhist traditions of Tibet and the spread of these traditions into surrounding regions of the Himalayas. This course will provide an overview of these traditions, exploring their trajectories of development and interactions with diverse communities, while also considering local differences and agency.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8691,2021,2497,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-257','<div class="desc"> <p>A systematic examination of the history of anti-Semitism, beginning with the emergence of anti-Judaism in late antiquity, its transformation into theological anti-Semitism in the Middle Ages, and a racialized anti-Semitism in the modern world. In each period, students will investigate the socio-political contexts that gave rise to the fear of, hatred toward, and attacks on Jewish individuals and communities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8693,2021,2699,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-259','<div class="desc"> <p>Students will use the United States and Brazil as sites of comparison through which to understand the various relationships between religion and race in the Americas. In both places we will ask: Where can we find African religion in the Americas? How have religious practitioners, scholars, and even entertainers decided what is "authentically African," and to what ends? And how has religion - and the social scientific study of it - served as an arena for negotiating racial and ethnic difference? By the end of the class, students will emerge with an understanding of different black religious traditions across the Americas - ranging from black Islam and Christianity in the U.S., to transnational Santeria, to Brazilian Candomble and Umbanda- as well as what is at stake in defining a category like "black religion." Students will understand how scholars have studied these traditions over time and how practitioners and scholars'' notions of black religion have shaped contemporary understandings of race and ethnicity in the Americas.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8694,2021,1626,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-261','<div class="desc"> <p>Buddhism is found worldwide today and is cited as an influence in a wide variety of settings, including psychology, self-motivation movements, education, statecraft, art, music, and science. However, its historical beginnings as a religious movement 2,500 years ago in India are often left out of these discussions. Buddhism is instead commonly presented as it has been reimagined by different agents as “more of a philosophy than a religion” and compatible with Western Enlightenment ideals, such as rationalism, empiricism and science. This course will provide a critical perspective on the process through which Buddhism has been constructed by various intellectual and political agents as it has developed in the modern era. Rather than attributing these characteristics of the tradition to inherent elements in some timeless ahistorical Buddhism, the course will instead encourage critical reflection on the broader cultural, political and economic processes that have influenced the development of modern Buddhism, including global networks of trade and technological exchange, colonialism (and anti-colonialism), cosmopolitanism, nationalism, the rise of secularism, and globalization between India, China, Japan, Sri Lanka, Tibet, Britain and America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8696,2021,2357,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-266','<div class="desc"> This course examines selected topics related to gender and sexuality as they have been negotiated in different global manifestations of the Buddhist tradition. Spanning over 2,500 years and multiple civilizations, Buddhism as a philosophy and Buddhist communities have constructed concepts of gender, sexuality, and the body in multiple, often conflicting, ways. Seen as androcentric and misogynist by some and liberating and non-judgmental by others, Buddhism and Buddhist institutional attitudes related to these key themes have been constructed through complex interactions between ancient traditions and the different societies in which Buddhism has developed. The course will be anchored in theoretical considerations of sexuality and gender, which we will explore through different case studies from India, China, Tibet, Thailand, Japan, and Korea. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8697,2021,876,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-270','<div class="desc"> <p>The course examines the relationship between the theological and ethical principles of Islam and political thought. After introducing the emergence and articulation of Islamic law (Shari''ah) and the Caliphate in the Islamic Empire we will study key scholars of Islamic jurisprudence. We will pay attention to the ways in which revelation and reason the individual and the state freedom and obedience are taken up in Islamic political philosophy as well as how these ideas have been in dialogue with the West (from engagement with ancient Greek philosophy to engagement with Western economic cultural and political modernity from the 18th century on). Finally studying the work of both modernizing and reactionary anti-modern Islamic thinkers the course will culminate in an examination of the ways in which contemporary Islamic legal and political thought addresses the relationship of religion and the state and the Western concept of "the secular".</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8698,2021,1674,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-276','<div class="desc"> Mainstream historical accounts of empire tend to focus on political and economic reasons for state expansion, leaving students with little insight into the experience of colonialism and imperialism "on the ground" for both the colonizers and the colonized. This course will offer methodological tools that encourage an understanding of everyday, non-elite voices into the study of empire in Asia and the Pacific by focusing on religious experience. Studying religion -- which was used as both a tool for colonial domination, as well as for resistance -- complicates ideas of empire as straightforward and as a mono-directional process. Case studies in this course will explore the interaction between empire and religion across a range of regions and historical moments. Students will then embark on their own research project related to a place and theme of their choice. In the end, the course will give students an insight into how Asian and Pacific societies variously responded to imperialism while also influencing the societies of the colonizer. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8699,2021,2358,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-277','<div class="desc"> <p>This course will survey ancient Mediterranean views about the catastrophic end of the world. We will study how ancient folks--Greeks, Romans, Jews, and Christians--interpreted disease, natural disasters (fires, floods, food shortage), political upheavals, and social unrest as signs of the end of the world. We will study how they altered their behaviors to anticipate the near end. And we will study their visions and fantasies of the utopian societies they hoped would emerge after the devastation. At the end of the course, students will conduct a staged research project on a topic of their choice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8700,2021,1192,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-281','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8701,2021,1089,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/rels-290','<div class="desc"> <p>The modern-day New Testament contains only a portion of the literature (i.e. gospels acts epistles and apocalypses) written by early Christians. This course will provide students the opportunity to study many of the texts that were not included in the Christian canon: the so-called apocrypha." We will investigate the process by which the Christian canon was formed how and why some texts that were beloved by many ordinary Christians were excluded from the canon by church officials and how the ideological and theological positions found in the rejected texts give us a lens into some of the most heated debates in early Christian communities. In addition to surveying apocryphal texts and their early Christian contexts the major assignment of the course will be to collaborate with Prof. Upson-Saia on her current research project: a study of how ideas found in the New Testament Apocrypha persist in Catholic tradition-specifically in Catholic doctrine art and liturgy-even though the texts themselves were excluded from the Christian Bible." <em>Open to Juniors and Seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8704,2021,361,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/200/resl-245','<div class="desc"> <p>A study of the religious traditions of the African diaspora in North America. We shall investigate the role of religion in Black culture and chart the development of the mainline Black Church. Islam religious traditions from the Caribbean Islands and new religions among African Americans will also be studied.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8705,2021,2815,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/300/rels-302','<div class="desc"> <p>In this course, students will explore mediumship and exorcism practices in the Atlantic World from the early modern period to today. Through case studies—including Haitian Vodou in Brooklyn, Brazilian Umbanda and Candomblé, Cuban Palo Monte, Santería in Chicago, Yorùbá and Igbo traditions in West Africa, North American Spiritualism, and Catholic Exorcism in France—we will take a broad look at the different ritual practices that fall under the academic category of “spirit possession.” We will consider why practitioners channel the spirits of the dead and what it means to be possessed. We will read scholarly studies that analyze what spirit possession has to do with race, gender, and sexuality. Finally, we will interrogate contemporary western scholarship itself, asking: Why have outsiders commonly described the spirits’ presence in terms of “possession”—a term rarely used by practitioners themselves—and how does the trope of the possessed person serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8707,2021,1090,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/300/rels-351','<div class="desc"> <p>This course will survey the variety of ways early Christians defined and regulated sexuality, such as the function and purpose of sexual intercourse, same-gender intercourse, contraceptive practices, abortion, polygamy, monogamy, celibacy, and the normative "Christian family." We will analyze how opinions on such topics were as profoundly social, political, and economic as they were religio-ethical. From this analysis, we will better understand how modern (religious and secular) attitudes have been shaped by -- as well as diverge from -- the Christian sexual ethics of antiquity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8708,2021,365,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/300/rels-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8709,2021,750,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/300/rels-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8710,2021,366,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/400/rels-490','<div class="desc"> <p>This seminar is offered in conjunction with Religious Studies majors'' ongoing research for the senior comprehensive project. Seminar meetings will be devoted to instruction on research and writing in the discipline of Religious Studies as well as discussion and critique of individual students'' work in progress. Open only to senior Religious Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8712,2021,751,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rels-religious-studies/400/rels-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8713,2021,368,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/100/rusn-101','<div class="desc"> <p>Introduction to the structure of the Russian language with an emphasis on reading and verbal communication. Films and laboratory assignments complement in-class work. May not be taken for credit by those with more than one year of high school study (grades 10 11 12) or one semester of college study of Russian.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8714,2021,752,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/100/rusn-102','<div class="desc"> <p>Continuation of RUSN 101; emphasis on reading and conversation.</p> </div>','RUSN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8716,2021,369,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/200/rusn-201','<div class="desc"> <p>Development of reading skills through the use of original texts by Bulgakov Chekhov Pushkin and others; improvement of conversation skills accompanied by a review and expansion of grammar. Films and laboratory assignments complement in-class work.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8717,2021,753,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/200/rusn-202','<div class="desc"> <p>Continuation of RUSN 201 with emphasis on reading skills; readings by Gogol Chukovsky Shukshin and others.</p> </div>','RUSN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8719,2021,2752,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/200/rusn-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers:Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ).</p> <p>This course meets twice a week with CSLC 236, and for one additional 85 minute session per week, to develop Russian students'' intermediate language skills, specifically by reading and discussing works under consideration in the course taught in translation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8720,2021,370,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/200/rusn-274','<div class="desc"> <p>Focusing on Russian literature''s greatest depictions of war this course follows the evolution of war literature in Russia as it transforms from the folk epic to the Romantic tale of adventure to the bloody scenes of Tolstoy''s War and Peace into the Modernist portrayal of moral ambiguity in Isaac Babel''s Red Cavalry.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8721,2021,1133,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/200/rusn-278','<div class="desc"> <p>Stalin was arguably the first totalitarian dictator who created the model for similar regimes in the twentieth century. This course describes the changes Stalin brought to Soviet society the terrible consequences of his dictatorship and the reaction of cultural figures criticized as they rebelled against the system. This course examines those movements through popular culture film literature and first-hand testimony. The everyday life of Soviet citizens will be studied by looking at both permitted and forbidden forms of entertainment. The dissident movement that erupted in the 1960s and 1970s will be examined through the Sotsart artistic movement as well as short stories that circulated underground throughout the late Soviet period. Finally the course will look at Stalin''s legacy in Putin''s authoritarian Russia of the twenty-first century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8722,2021,878,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/200/rusn-284','<div class="desc"> <p>An examination of the phenomenon of madness in Russian culture through literature and film. The main focus will be on the psychological literature of the 19th Century including the the murder novels of Dostoevsky as well as studies of madness by Lermontov Gogol Chekhov and others. This trend in Russian literature will be related to pathological features of Russian history (Tsarism Totalitarianism) to find underlying reasons why these features are so prevalent in the Russian arts. Films will include Tsar concerning Ivan the Terrible and Burnt By the Sun a chronicle of the Stalinist terror.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8725,2021,1677,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-331','<div class="desc"> The worldview and beliefs of the early Slavs particularly the Eastern Slavs were a complex synthesis of influences: Indo-European mythology Central Asian shamanism Scythian animal worship and ultimately a paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600 in order to understand how these people viewed the world and how this affected their lives and the development of Slavic culture. Communal village life legends folk genres and mythology their sources and their legacies are examined. There is a close study of the phenomenon of the vampire following its evolution from the Iron Age into eighteenth century Serbia as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined as well. In addition to analytical and historical texts readings include tales of supernatural beings and phenomena as well as testimony concerning encounters with the supernatural." This section will deal with both texts in English and with texts in the original Russian. Texts include the "Tale of Warlord Dracula," "Olga''s Revenge on the Drevlians" and other early Russian stories. </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8726,2021,1561,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-332','<div class="desc"> Many of Russia''s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements while at the same time creating some of the most memorable texts of the twentieth century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin, using original Russian texts to examine the use of language in the creation of science fiction and fantasy texts. Additionally, film adaptations will be shown, including the avant garde film Aelita the Queen of Mars and Andrei Tarkovsky''s masterpiece, Stalker. The course only introduce students to modern Russian literature while at the same time examine how Russian writers used science fiction to criticize society and government. </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8727,2021,1627,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-333','<div class="desc"> <p>(Note: this course is identical to CSLC 233 with additional class period for Russian-language materials). Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939 when the Soviet Union was busily partitioning Poland by secret agreement with Nazi Germany. This course examines the cultural history of Russia and the Soviet Union in specific regard to its evolving theories of language literature and cultural phenomena during the early 20th Century. Particular attention is paid to Russian formalism poetics and semiotics as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence mutual East-West suspicion social repression and exertions of state power through propaganda and censorship.</p> </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8728,2021,1740,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-334','<div class="desc"> How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist a century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun" and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency known otherwise as the Russian Avant-garde. Topics include poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi. </div>','RUSN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8729,2021,3751,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-335','<div class="desc"> <p>In this Russian language version partnered with CSLC 135, in addition to reading Tolstoy''s novel, <em>War and Peace</em>, in English, students will read Book Ten in Russian. Students will submit weekly reports that deal with multiple aspects of the Russian text, including Tolstoy’s use of syntax to achieve textual defamiliarization, his idiosyncratic vocabulary that challenges translation, and his fusion of time and space through grammatical and syntactical devices. Students will also present weekly translations of selected passages along with issues they encounter in attempting to create an accurate yet artistically appealing translation. As a final project, each student will also select a passage from another Book of <em>War and Peace</em> and provide an annotated translation.</p> </div>','RUSN 201 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8730,2021,2854,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-336','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. In this five unit version of CSLC 136, we will be reading excerpts in the original language from Goncharov’s Oblomov, Turgenev’s Fathers and Sons, Dostoevsky’s Idiot. Students in this course will be asked to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8731,2021,2899,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-337','<div class="desc"> <p>This course will meet twice a week with CSLC 237, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from Mamardashvili’s <em>Lectures on Proust</em> in the original Russian. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> <p>The associated CSLC 237 course description is as follows: Marcel Proust’s <em>In Search of Lost Time </em>is considered to be one of the greatest novels ever written. Two 20th century thinkers—an Eastern European philosopher Merab Mamardashvili and a French thinker Gilles Deleuze —argued that Proust’s novel is a philosophical machine: an artificial organ that allows one to gather and re-construct the self. This course puts to the test Deleuze’s and Mamardashvili’s interpretations of this novel by considering them in conjunction with significant portions of <em>In Search of Lost Time. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8733,2021,3179,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8734,2021,754,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/rusn-russian/300/rusn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8736,2021,371,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/100/soc-101','<div class="desc"> <p>This course introduces students to the "sociological imagination"-a way of viewing events relationships and social phenomena which form the fabric of our lives and much of our history. We will examine the ways in which people are shaped influenced and controlled by their society and vice versa. In addition students will be encouraged to think about how sociology helps us understand and interpret the nature of social order and disorder. <em>Open only to frosh and sophomores or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8737,2021,2700,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/100/soc-102','<div class="desc"> <p>This course adopts a global perspective to introduce students to sociology, the scientific study of societies. It will examine the self, socialization, social ties, social interaction, social institutions, and social change, considering both conformity and deviance. Students will leave with a "sociological imagination," the ability to see their own lives and the lives of others in the context of their wider societies and an increasingly interconnected world. Open only to frosh and sophomores, or by permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8738,2021,879,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/100/soc-105','<div class="desc"> <p>This course examines the role of youth cultures in the identity formation of immigrant adolescent youth residing in the Southwest region of the United States. Particular attention is paid to: (1) theories of acculturation and assimilation used to analyze the experiences of immigrant youth; (2) the impact of geographical location social class gender race sexuality popular culture mass media and technology; and (3) the intersection of youth cultures home cultures and mainstream society.</p> <p><span style="background-color: #ffffff; color: #222222;">This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CSP 1, CTSJ 105, DWA 282 and SOC 105.</span></p> </div>','SOC 101 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8739,2021,755,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/100/soc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8740,2021,1491,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-200','<div class="desc"> <p>This course introduces the discipline''s formative schools of thought. The course is structured according to sociology''s classic paradigms. Marxist Weberian and Durkheimian theories are the classical models. They founded the field of Sociology and continue to influence contemporary thought about social relations. In the course we first examine the fundamental presuppositions of their grand theories. Then we critically evaluate the particularities of their more concrete propositions about capitalist development or modernization the state and social change. A special emphasis of the course is on critical analysis.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8741,2021,372,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-205','<div class="desc"> <p>This course introduces the most influential paradigms of the 20th century. These include the American structural-functionalist paradigm the rational choice model the elite school various neo-Marxist arguments (including the theory of the world system as well as the culturalist Frankfurt school) and the symbolic interactionist paradigm. We conclude the course with an introduction to postmodernist theory. The course emphasizes critical analysis.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8742,2021,1492,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) Presidents either failed to act in accordance with the transitional justice movements sweeping Latin America or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently as compared to South American countries human rights violations in Mexico have increased rather than decreased since its transition to democracy. This class will document why this is the case as well as look into the various movements thathave mobilized since the 1970s to the present to demand human rights in Mexico.</p> </div>','SOC 101, POLS 101, or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8743,2021,1562,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-215','<div class="desc"> Who are you? Why are you? How do you know? Surely you have heard the phrase "nature vs. nurture." It is about the ongoing quest to figure out how much of a human is genetic, biological, and chromosomal (nature), and how much is a product of socialization (nurture). To what extent are you your society? To even consider that question, we must examine the society itself, the individuals that produce it, and how the two are connected. The society and selves we will be examining are our own -- in particular, the society and selves of young Americans. How does the world you''re facing today make you who you are? How do the technology and media through which you learn about your world permeate, shape, and structure your everyday experience of self and society? Who do you want to be, who will you end up being, and what kind of world will you create? </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8744,2021,1628,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-225','<div class="desc"> <p>This course examines the construction and reproduction of masculinities primarily in the United States. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity race class age sexual orientation and gender and the role of social institutions and inequities in the social construction of masculinities.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8745,2021,1316,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-230','<div class="desc"> <p>This course examines the family as a social institution in the United States. The course emphasizes sociological and demographic perspectives on the family family change historically and contemporarily and the intersection of the family with social categories such as race and ethnicity sexual orientation gender and class. The course will highlight contemporary changes in marriage divorce and non-marital cohabitation in the United States but will also expose students to sociological thinking about family systems around the world.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8746,2021,1629,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-235','<div class="desc"> Are feelings innate and universal or are they socially created and historically and culturally determined? Emotions are generally seen as individually and privately experienced, but are actually deeply social. They are embedded in, constitutive of, and created by social interactions, social structures and institutions. This course will examine the relatively new field of the Sociology of Emotions from a constructionist and interactionist perspective. Our explorations will focus on contemporary American society, but will use examples from other times and cultures to illustrate the socially constructed, experienced, and expressed nature of emotions. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8747,2021,756,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-240','<div class="desc"> <p>This course examines the social relations surrounding the production distribution preparation and consumption of food. In doing so we will try to understand how the issues and problems of daily life reflect larger social forces and how our understanding and actions shape the social world. This means that we will treat several major questions facing sociology today including inequalities and identities based on national racial/ethnic class and gender positions; work and family; the environment; globalization; and cultural change. By the end of the course you will be able to critically examine and evaluate the connections between food culture and society.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8748,2021,373,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-245','<div class="desc"> <p>This course examines the individual cultural and structural explanations for the presence and persistence of income and wealth inequality in the U.S. The impact of inequality on social groups and the social policies developed to curtail poverty are also considered.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8749,2021,979,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-250','<div class="desc"> <p>This course provides a basic sociological understanding of relations among racial and ethnic groups in the United States. A sociological approach includes considering race and ethnicity as social constructs that permeate all social life are entrenched in social structures and institutions and shift and mutate over time and place. Such a perspective suggests that (1) race and racism are not merely the ''problems'' of/for subordinate racial and ethnic groups but are reflective of society-wide power relationships that deeply affect all of us on a daily basis (2) that racial and ethnic categories - including ''white'' - can be viewed usefully as the result of historical struggles over economic resources political access and cultural identity rather than as objective measures of biological difference and (3) the institutional forms of racism indelibly etched into this nation''s past did not end with civil rights legislation of the 1960s but continue to shape social institutions today.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8750,2021,980,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-255','<div class="desc"> <p>This course examines the role of youth cultures in the identity formation of adolescents residing throughout the United States. Particular attention is paid to 1) the impact of geographical location social class gender race sexuality popular culture mass media and technology; (2) the intersection of youth cultures and mainstream society; and (3) the contention that some youth cultures are "deviant".</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8751,2021,1092,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-260','<div class="desc"> <p>In this course we will focus on sociological theories of deviance with an emphasis on how behaviors and identities are socially constructed as deviant (both today and historically). We will then turn our attention to major forms of deviance as typically defined in Western societies: criminal deviance "victimless crimes" and individuals with stigmatized identities. Throughout the course we will work to understand the complex relationship between social actors and audiences in defining deviance; the nature of social control in responding to deviance; and the experiences of "deviant" individuals.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8752,2021,374,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-265','<div class="desc"> <p>In this course we will critically examine the ways gender informs the social world in which we live. Our goals for this course will be 1) to reveal the "common-sense" world of gender around you; 2) to consider how we learn to "do" gender; 3) to expose the workings of the institutions that shape our gendered lives; and 4) to come to an understanding of the relationship between gender and the social structure.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8753,2021,2360,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-270','<div class="desc"> <p>What are the effects of urbanism on human psychology and civic life? How does urbanization structure social and economic relations as well as signifying identities and cultural meanings? Is there a common "human ecology" of cities in "natural areas" such as the CBD skid row the "Tenderloin" or the "zone-in-transition"? We examine the urban underclass through case studies of the African American ghetto and Spanish Harlem with attention to public policy perspectives on urban poverty. Urban futures are considered through gentrification growth machine boosterism (sports and convention centers) and urban theme parking.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8754,2021,981,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-280','<div class="desc"> <p>Why does the United States incarcerate more of its population than any other nation in the world? Why does death by injection seem kinder and gentler-and thus more acceptable-than public hangings of the past? What are the consequences for justice and democracy in an era of unprecedented confinement and correctional supervision? Using various historical legal and sociological perspectives we will focus on questions such as these with an emphasis on: the cultural life of punishment crime control as a political issue the racial and class dynamics of punishment and inequality and contemporary issues surrounding modern penal sanctioning (e.g. mass incarceration) and its consequences. <em>This course is repeatable once for credit.</em></p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8755,2021,1093,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-285','<div class="desc"> <p>The relationship between humans and the non-human environment is complex and problematic. We are part of and dependent upon the natural environment even while altering that environment for our own needs and purposes. As a way of broadly thinking about these interactions we will address the social causes consequences and responses to environmental disruption. By the end of the course you will be more adept at understanding how societal characteristics -- including cultures traditions beliefs values institutions and the like -- combine with environmental conditions to shape the impact that people have on their environments.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8756,2021,1741,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-290','<div class="desc"> This course is an introduction to sociological analyses of the economy, economic processes, and economic institutions. The central focus is to understand how beliefs, norms, cultures, social relations, and institutions shape our economic lives. We will also explore how the theoretical and methodological approaches of sociology differ from those orienting the discipline of economics, as well as what is at stake in these differences. By the end of the course, you will be familiar with the key approaches in economic sociology, and will be able to use a sociological lens to examine the economy. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8757,2021,1194,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/200/soc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8759,2021,375,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-304','<div class="desc"> <p>This course looks at the ways sociologists collect information about social phenomena with a special emphasis on what can be done to yield information that is trustworthy and useful for our theoretical understanding of social life. It assumes no background in research methods or statistics. We will talk about the scientific method the complexities of applying methods to social research ethics and bias and research design. You will be given an overview of major "quantitative" and "qualitative" methodologies including surveys interviews ethnography experiments participant observation or content analysis.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8760,2021,757,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-305','<div class="desc"> <p>This course introduces quantitative research methods and statistical analysis from a social science perspective. We will address the major components of the research process and will stress the importance of critical thinking in all matters numerical. We will cover measures of central tendency the normal curve probability frequency distributions correlation and regression. We will also talk about statistics and statistical reasoning in the media. By the end of the course you will have mastered basic statistical concepts and techniques and will be able to critically examine and evaluate the (mis)use of these concepts.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8761,2021,1563,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-306','<div class="desc"> <p>This course introduces qualitative research methods from a social science perspective. We will cover systematic qualitative research design data collection and analysis. Techniques will include interviewing focus groups ethnography and/or qualitative content analysis. By the end of the course you will have mastered basic concepts and techniques and be able to carry out basic qualitative research.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8762,2021,1493,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-310','<div class="desc"> <p>This course introduces the theory and methods of sociological and urban field research. We consider positivist interpretive and critical paradigms. We compare the traditions of anthropological as well as sociological ethnography. We explore the ethics of participant observation with respect to issues such as role authority and power. We learn interview protocols how to write field notes how to analyze data and techniques of storytelling in ethnographic writing. We explore principles of participatory action research and oral history. We will also learn quantitative methods through the analysis of local statistical data from the U.S. Census of Population and Housing. Students will conduct their own ethnographic or field-based study.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8763,2021,1094,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-315','<div class="desc"> <p>This course uses different sociological perspectives to examine social aspects of schooling and educational institutions in the U.S. Specifically the course focuses on factors that may impede and/or facilitate learning such as social class gender race and ethnicity teacher and parental expectations and peers. Additionally the role of education in the acculturation and assimilation process is considered as are the ways in which schools ameliorate and/or replicate social inequalities.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8764,2021,1353,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-320','<div class="desc"> <p>This course surveys sociological theories of health illness and medicine. Rather than focusing on the individual body as the site of disease the course examines the role of social context in shaping health and access to the healthcare system across population groups. The course focuses especially on medical intervention and the medicalization of disease social disparities in health and contemporary healthcare changes and challenges in the United States.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8765,2021,2605,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. To a lesser degree we will also examine Central American immigration from an international relations perspective.</p> </div>','SOC 101, LLAS 101, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8766,2021,2361,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-323','<div class="desc"> This course explores the sociological analysis of law, focused on the legal construction of social "groups," the moral regulation of social action, and the formal legitimization of state practices. The course is divided into two sections. The first half of the course examines theoretical approaches to the sociology of law drawing on the works of Max Weber, Niklas Luhmann, Jürgen Habermas, and Pierre Bourdieu, as well as perspectives rooted in Marxism, feminism, and critical race theory. The second half of the course focuses on contemporary legal controversies in the United States, including racial disparities in criminal justice, undocumented immigration, the regulation of sexuality, and the criminalization of political dissent and protest. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8767,2021,376,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-325','<div class="desc"> <p>This course introduces the field of criminology. The course is designed to provide a broad understanding of the etiology of crime (i.e. what causes crime?) the measurement of crime and theories of criminal punishment. We will also discuss a wide range of criminal behaviors with a focus on violent crime and property crime (e.g. homicide sexual assault shoplifting white collar crime etc.). The final component of the course focuses on the American criminal justice system. This course emphasizes a sociological approach to understanding crime criminal behavior and criminal justice.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8768,2021,377,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-330','<div class="desc"> <p>This course will focus on classical and contemporary theories of power and authority; theories of the state and various forms of state power the state and government the nature of democracy and political elites in modern society (especially the United States) as well as the social bases of political parties and voting behavior.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8769,2021,1195,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-335','<div class="desc"> <p>This course will focus on the changing dynamics of state power in Latin America from the 1960s through the present. We will compare Latin America''s hard-dictatorships (dictaduras) to various versions of soft(er)-authoritarianisms (dictablandas) before such states transitioned to electoral democracy. Beyond looking at the changing dynamics between states and their civil societies over time we will explore legacies of civil wars revolution military coups and dirty wars. We will not only look at how ordinary people fought back by struggling for political human and cultural rights but how their movements contributed to the recent democratic transitions characterized as "third-wave" democratization".</p> </div>','SOC 101, POLS 101, DWA 101, HIST 258, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8770,2021,1564,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-340','<div class="desc"> China''s Environmental Challenges: A Sociological Perspective This course examines China’s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China’s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. Cross-listed with East Asian Studies and Urban and Environmental Policy. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8772,2021,758,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-350','<div class="desc"> <p>This course examines why people protest for social change. We will examine the theoretical debates about the determinants of insurgency by focusing on the following models: the collective behavior the resource mobilization the political process as well as the cultural approach. We will also examine the theoretical debates on the extent to which social movements can be credited with political change. Your study of these theories will expose you to several case studies of real social movements in the United States Europe and Latin America. This is however a theory (not a history) course.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8773,2021,759,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-355','<div class="desc"> <p>This course will consider the role that sexuality plays in the American imagination especially the way that sexuality is constructed and serves as a mechanism of social control. In doing so special attention will be paid to the ways in which human sexuality intertwines with axes of power in contemporary America such as race ethnicity gender class and sexual orientation.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8774,2021,2890,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-361','<div class="desc"> <p>This advanced seminar builds on the foundational understandings of race/ethnicity to further explore Whiteness in the U.S. and globally. Whiteness is a framework that organizes social structures and can be systemically upheld regardless of one''s race. This course explores how constructions of Whiteness change through shifting racial boundaries and across global contexts; how it shapes privilege, racism, and racial oppression across social institutions; how it intersects with other axes of power to shape inequality; and how it informs scientific knowledge from theorizing to data analysis.</p> </div>','SOC 101 or SOC 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8775,2021,761,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-365','<div class="desc"> <p>The course will examine how mass communication systems such as radio television cinema and the Internet are produced and what they signify and represent of the social world and public life. We consider the relationship of the mass media to big business and the structure of capitalism. The ideological influences of the mass media are interrogated through concepts such as "mass culture" and "subculture". We examine how contemporary culture and everyday life are increasingly commodified through the systems and spectacles of consumption capitalism. How has globalization affected consumerism and the social construction of the contemporary self?</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8776,2021,1354,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-370','<div class="desc"> <p>This course examines the social phenomenon of human violence. We first consider classical and contemporary sociological theories on violence and violent conflicts and the main sociological definitions of violence used over the last century. We then turn to empirical studies that explore the social processes and societal structures that give rise to the various forms of violence-intrapersonal interpersonal familial collective and political-and nonviolent movements presently observed throughout the world.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8777,2021,762,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-375','<div class="desc"> <p>This course examines the political economic and cultural changes that occur as societies shift from the traditional to the modern. Why are some nations mired in debt and dependency while others have become successful "newly-industrializing countries?" We consider leading intergovernmental organizations of the global economy such as the IMF World Bank and WTO. We investigate scenarios in cultural globalization including Americanization hybridization and fundamentalism. We consider intersectional social dynamics that disenfranchise the most powerless including women children indigenous and stateless peoples.</p> </div>','SOC 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8778,2021,1426,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-380','<div class="desc"> <p>This course examines disaster as a social phenomenon and broader trends in managing calculating and responding to a variety of threats and catastrophes. We will focus on the history of disaster response and policy in the U.S. theories of reflexive modernity risk and trauma and cultural responses to calamity in California and in the U.S.more broadly. Case studies include Hurricane Katrina the BP Deepwater Horizon oil spill Fukushima and outbreaks of whooping cough and Ebola.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8779,2021,1630,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-385','<div class="desc"> Psychology and psychiatry identify the causes of sadness, madness, anxiety, and trouble (SMAT) as originating within the "mind" or, increasingly, the brain. The sociology of mental illness, by contrast, focuses on processes in the social and cultural context, and argues that social structure, relationships, and culture are significant factors in the genesis of SMAT. The sociology of mental illness is also concerned with how the very concepts of mental illness, abnormal or crazy are constructed and used. The second half of the course focuses on the response to SMAT: how family, friends, troubled persons, and professionals interpret, define, and respond to SMAT, and the processes shaping the policies and practices of the mental health enterprise. </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8780,2021,1631,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-390','<div class="desc"> <p>This course offers a survey of sociological approaches to the study of religious beliefs practices and organizations in the United States in public and private life. Exceptionally devout among developed nations the U.S. is a nation of remarkable religious diversity. We will examine the relationship between religion politics and civic life; recent trends in American religion (the "new atheism" problems of pluralism secularization and declines in religious participation the rise of evangelicalism and fundamentalisms religious conflicts); as well as theoretical arguments both classical and contemporary about the role of religion in scientifically advanced modern societies. Whereas much public debate frames religion as either a unambiguously beneficial public good or else as a font of irrationality and sectarian division we will move beyond this dichotomy toward a more empirically informed consideration of just what religion is and does in the contemporary United States.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8781,2021,1040,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-395','<div class="desc"> <p>This course will function as an advanced seminar focusing on the research interests of the Sociology Department''s faculty. Topics vary.</p> <p><strong>Policing, Power, and Violence</strong></p> <p>In this course, we will examine policing in the United States from the repression of Indigenous and enslaved peoples in the 18th century to the militarization of policing on the streets and the U.S.-Mexico border today. Using sociological understandings of power, we will analyze the judicial and extrajudicial violence that law enforcement agents engage in and how such violence serves to maintain the unjust and unequal social order. The course will close with us considering arguments for and against the abolition of police forces and prisons.</p> <p><strong>Sociology of the Southern U.S.</strong></p> <p>What, and where, is the South? Who is a southerner? What do they do down there, and why do they do what they do? Are the South and southerners still distinctive? By looking at all aspects of Southern life this course will unravel the enigma of the region while pondering a more inclusive and nuanced appreciation of "many Souths" and "southern cultures" including senses of regional identity and allegiance, and in representations of, and cultural stereotypes from and about, the South. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> <p><strong>Visualizing Gentrification: Bridging Land Use Data and Ethnography</strong></p> <p>Students are challenged with the myths and realities of gentrification in an immersive discussion. The proposed course weaves urban planning, mapping and data research with qualitative analysis to recognize gentrification drivers, examine the pending experiential trauma of displacement and the community''s aspirations and resistance. The course examines the communities of Northeast Los Angeles as they face three colossal planning projects that utilize gentrification as a catalyst and justification for their development.</p> <p>In a holistic examination of the landscape, course participants will embed with community and other partners to explore the social networks and their relationship to research data. Course discussions will include developing metrics from an activist and documentary perspective to establish the observable community. Students will operate in small teams in developing data and fostering outcomes that reveal the human narrative. They can be visual in nature from ethnographic studies to data visualization, but also critical analysis and policy recommendations of the conditions on the ground. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> </div>','SOC 101 or SOC 102 are prerequisites ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8782,2021,763,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/300/soc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8783,2021,378,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/400/soc-490','<div class="desc"> <p>Seminar is offered in conjunction with sociology majors'' ongoing library research for the senior thesis. Seminar meetings will be devoted to discussion and critique of work in progress. We strongly encourage students to have taken Classic or Contemporary Theory Sociological Inquiry and Qualitative Quantitative or Field Methods before taking the senior seminar (always taught in the Fall). <em>Open only to senior Sociology majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8785,2021,764,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/soc-sociology/400/soc-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> <p><br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8786,2021,380,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/100/span-101','<div class="desc"> <p>Introduction to Spanish through a variety of communicative approaches. Emphasis is placed on speaking and listening as well as grammar and writing. <em>Students who have had more than one year of Spanish in high school or more than one quarter in college may not take this course for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8787,2021,381,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/100/span-102','<div class="desc"> <p>This course is a continuation of SPAN 101. Students are introduced to the culture of the Spanish-speaking world through readings and discussions.</p> </div>','SPAN 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8788,2021,382,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/100/span-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only. </em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8789,2021,765,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/100/span-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit.<em> Graded on Credit/No Credit basis only.</em></p> </div>','Spanish 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8790,2021,766,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/100/span-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8791,2021,383,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/200/span-201','<div class="desc"> <p>This course focuses on the development of speaking and writing skills. Students read and discuss cultural and literary texts from a variety of Spanish-speaking countries. The fundamentals of Spanish grammar are reviewed.</p> </div>','SPAN 102 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8792,2021,384,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/200/span-202','<div class="desc"> <p>This course is intended to further develop language skills while introducing students to the fundamentals of literary analysis through a study of Mexican South American and Spanish literary texts. Particular emphasis is placed on oral communication and writing. <em>This course parallels SPAN 211 and is designed for non-native speakers of Spanish. Students may not take both for credit.</em></p> </div>','SPAN 201 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8793,2021,385,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/200/span-211','<div class="desc"> <p>This course is designed for students who have spoken some Spanish in the home and are able to understand spoken Spanish well. It aims to develop and improve students'' conceptual understanding of the grammatical structures of the Spanish language. Coursework emphasizes the practice of formal written and oral Spanish as well as the improvement of vocabulary with the goal of strengthening students’ fluency in academic and professional contexts. Principal readings consist of literary texts (e.g. short stories, literary essays, and drama) in order to prepare students for reading and writing in upper-level Spanish courses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8794,2021,386,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/200/span-251','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','Spanish 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8795,2021,767,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/200/span-252','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','Spanish 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8798,2021,1095,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-301','<div class="desc"> <p>General survey of Pre-Columbian civilizations and literature of Meso and South America the impact of the Discovery the Conquest the Colonial Period and the processes leading to the Independence and the formation of the new Republics. Literary and historical readings compositions and short essays and presentations will be used to continue developing language skills.</p> </div>','SPAN 202, SPAN 211, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8799,2021,984,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-302','<div class="desc"> <p>An introduction to Spanish Peninsular literature and culture from the Middle Ages to the 18<sup>th</sup> century. This course examines the cross-cultural elements (Arab, Jewish, French, Italian, Trans-Atlantic and others) that have influence Spanish literature across the centuries. Readings include Mozarabic poetry, the <em>Cantar de Mio Cid</em>, Medieval narratives, <em>La Celestina</em>, Renaissance poetry, selections of <em>Don Quijote</em>, and Golden Age dramas. The class also incorporates representative examples of art and films.</p> </div>','SPAN 202, SPAN 211, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8800,2021,387,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-303','<div class="desc"> <p>An introduction to major twentieth-century works of literary fiction and cinema in Latin America, with attention to the interplay of fiction and history, read in the original Spanish: Gabriel García Márquez''s <em>One Hundred Years of Solitude</em>, Isabel Allende''s <em>The House of the Spirits</em>, and stories by Jorge Luis Borges, Julio Cortázar and Roberto Bolaño. Film screenings include Cuban director Tomás Gutiérrez Alea''s <em>Memories of Underdevelopment,</em> Chilean director Patricio Guzmán''s <em>Salvador Allende</em>, and Argentine director Lucrecia Martel''s <em>La ciénaga</em>.</p> </div>','SPAN 202, SPAN 211, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8801,2021,768,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-304','<div class="desc"> <p>This course surveys Spanish Peninsular literature and culture from the late 18<sup>th</sup>-century through the early 21<sup>st</sup>-century. Students engage with various intellectual and literary movements, including Neoclassicism, Romanticism, Naturalism, Surrealism, and Postmodernism. Special attention is given to the development of democratic traditions in Spain, the clash of political ideologies during the Second Spanish Republic and the Spanish Civil War, the trauma and legacy of dictatorship, and the changes in Spanish society resulting from the assertion of the distinct languages and cultures of the Iberian Peninsula and from globalization and immigration. Authors read include Leandro Fernández de Moratín, Ángel de Saavedra, Emilia Pardo Bazán, Jacinto Benavente, Ramón Sender, Antonio Buero Vallejo, and Juan José Millás. Significant examples of modern Spanish art, architecture, and music are also studied.</p> </div>','SPAN 202, SPAN 211, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8802,2021,1494,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-309','<div class="desc"> <p>Many Latin American writers have chosen to live in Spain during the twentieth century. This course introduces students to the Latin American tradition of the writer acting as public intellectual or diplomat as well as to instances of the Latin American writer in political exile. Poets Pablo Neruda and CÃ©sar Vallejo chose to live in or near Madrid during the period of the Spanish Civil War whereas a later generation of fiction writers (Gabriel Garcia Marquez Cristina Peri Rossi and Roberto BolaÃ±o) lived in Barcelona after the 1970''s. The fiction writers include their own vision of Catalan nationalism and Catalan national identity in various short stories. The course concludes with a three-week stay in Spain that will provide a deeper understanding of the Latin American writers'' representation of the coutry. On-site lectures by historians and art-historians will enhance the student''s understanding of GarcÃ­a MÃ¡rquez''s Peri Rossi''s and BolaÃ±o''s incorporation of Catalan politics landscapes and cityscapes in their fiction.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8803,2021,1096,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-312','<div class="desc"> <p>This course surveys the history of Spanish film from its inception to the present. The course introduces students to basic concepts of film studies including cinematography mise-en-scÃ¨ne sound narrative and style but emphasizes representation and in particular depictions of gender sexuality and national identity in the context of dictatorship and democracy. The course further introduces students to the auteurist tradition in Spanish cinema. The films studied vary from year to year but the course typically highlights the cinematic production of Luis BuÃ±uel Carlos Saura and Pedro AlmodÃ³var.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8804,2021,1196,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-313','<div class="desc"> <p>This course offers students the opportunity to analyze films that have emerged in Latin America (e.g. Argentina, Brazil, Colombia, Cuba, Mexico, and Peru) as well as in the United States in the 20th and 21st Centuries. Many of the visual works studied treat significant contemporary issues in Latin America, such as the representation of history, questions of identity and alterity, questions of race and ethnicity, globalization, authority, the construction of class and gender in society. Emphasis will be placed on studying films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically, this course is a critical survey of the representation of Latin America with representative examples from different historical periods (beginning with the pre-Columbian and Colonial periods followed by the 19th and 20th Centuries). The goals of the course are to understand how film as a medium has functioned historically and aesthetically in its representations of different sectors of society.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8805,2021,881,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-314','<div class="desc"> <p>How do Latin American women writers and film-makers use language and sound? This course analyzes questions of social critique and the use of language in the short stories of Uruguayan writer Cristina Peri Rossi PuertoRican writer Rosario FerrÃ© and Brazilian writer Clarice Lispector as well as the use of voice music and mise-en-scÃ©ne in films by Latin American directors Gabriela David Maria Luisa Bemberg and Susana Amaral.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8807,2021,388,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-320','<div class="desc"> <p>An analysis of the relationship between literature and film, focusing on texts from the Spanish Golden Age and their film adaptations. Issues to be discussed include film adaptation as a cultural construct; narrative voice in literature and film; the transformation of the written word to the visual image; and the relationship between politics, literature, and film. This course includes a digital liberal arts laboratory in which students engage digitized and physical materials and develop necessary skills and critical frameworks for audiovisual and web-based course projects.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8808,2021,2606,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-325','<div class="desc"> <p>In this interdisciplinary course we will examine representative works of art and literature that are centered on the city of Madrid as a cultural, social, historical and intellectual space. We will discuss artistic and philosophical issues including, among others, the conception of space revolution in Diego Velázquez, the tensions of Enlightenment and Romanticism in Francisco de Goya, and the existential representation of life after the Spanish Civil War in Camilo José Cela. We will explore the interconnection of selected artistic and literary works with the purpose of approaching an understanding of the multilayered and fluid creation of the city’s identity.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8809,2021,769,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-340','<div class="desc"> <p>This course serves as a general introduction to the study of the Spanish sound system. The objectives of this course include strengthening students'' Spanish pronunciation in the direction of a more native-like normative pronunciation and introducing them to phonetics and phonology. Students will be introduced to theoretical means of analyzing the sound system of a language. They will also examine contrasts between American English and Spanish and apply these concepts in exercises of both written transcription and oral production as well as with a linguistic analysis of spoken Spanish. Finally students will also be acquainted with phonological differences among the dialects of the Spanish language.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8810,2021,1097,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-341','<div class="desc"> <p>This course consists of an introduction to historical Hispanic linguistics. Students learn about the major phonological morphosyntactic and lexical changes that have occurred in the language from the time of the arrival of the Roman armies into the Iberian Peninsula until the present. Foreign influences on the evolution of the Spanish language are discussed briefly. The primary focus of this course is the internal history of the language from Vulgar Latin to Modern Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8811,2021,1134,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-342','<div class="desc"> <p>This course consists of an introduction to the Spanish language and Spanish-speaking communities in the United States, home to the second-largest Spanish-speaking population in the world. We will focus on questions like: who are the principal groups of Spanish speakers in the U.S.? Where do they live, and how and when did they arrive to the U.S.? What are the principal linguistic features of their Spanish? In the U.S., who uses Spanish, and in what contexts, and for what purposes? What is the role of Spanish in public services, the media, and schools? In this course, we will also confront social issues such as language attitudes, bilingualism, and the interaction between language and identity. This course will be conducted in Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8812,2021,1427,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-343','<div class="desc"> <p>Language use symbolically represents fundamental dimensions of human behavior and social interaction. For instance, what can you immediately infer about a Spanish speaker who uses the word “zumo” to describe the orange beverage commonly drunk at breakfast? Most likely, they are from Spain, otherwise they might describe this beverage as "jugo."</p> <p>This course introduces the basic concepts of sociolinguistics, using Spanish as our tool of exploration and description. Sociolinguistics focuses on the symbolic value of language as an expression of group identity based on region, gender, ethnicity, socioeconomic class, age, or other ways of defining group affiliation. In this course, we describe key notions of sociolinguistics such as the speech community, the sociolinguistic variable, and field methods. The core goal of the course is to identify phonological and morphosyntactic variation throughout Spain, Latin America, and the US, and identify what this variation tells us about language change and development as well as about the social characteristics and identities of the speakers themselves. The course also surveys other related topics such as language contact, bilingualism, Spanish as a heritage language, language attitudes and language identity in the U.S. and elsewhere, language and law, language and age, and language and gender. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8813,2021,1355,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-351','<div class="desc"> <p>A study of Cervantes'' narrative and drama in the context of certain literary trends of the European Renaissance. The course will focus on the Novelas Ejemplares selected parts of Don Quijote and Entremeses and it will explore Cervantes'' treatment of the genres and currents which influenced his art.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8814,2021,985,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-353','<div class="desc"> <p>This course analyzes both pictorial and literary images of sacred and profane love in Medieval and Golden Spain. Through a comparative approach the course will explore the differences and similarities in the treatment of secular and religious love by painters (Velazquez Murillo Rivera etc) and writers (Garcilaso San Juan de la Cruz Gongora etc). Topics such as courtly love mystical experience and social conventions will be studied. At least two field trips to local museums will be scheduled.</p> </div>','SPAN 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8815,2021,986,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-362','<div class="desc"> <p>This course will focus on the theater of Federico García Lorca and the cinema of Luis Buñuel and Pedro Almodóvar. Students will engage in an in-depth study of García Lorca''s plays examining his theatrical representation of surrealism, gender, and sexuality in conjunction with key films of Buñuel and Almodóvar.</p> </div>','One Spanish 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8816,2021,1098,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-363','<div class="desc"> <p>This course will apply current theories of autobiographical discourse to Spanish Latin American and U.S. Latino life-writing. Students will examine the relation of personal identity to dominant ideologies of gender race class and politics and will explore the role of memory and fantasy in literary self-expression. Authors studied will vary from year to year but will typically include Gloria AnzaldÃºa Reinaldo Arenas Juan Francisco Manzno Carmen MartÃ­n Gaite Rigoberta Menchu Constancia de la Mora and Mario Vargas Llosa. Students will have the opportunity to write their own autobiographies.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8817,2021,1632,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-370','<div class="desc"> <p>In this course we will look at the jungle as a space where western civilizations desires and fears come into tension with the imagined "other" so that sometimes the jungle can be beautiful and desirable like the Garden of Eden and other times savage and dark like hell. Readings will include Latin American works of fiction (by Jose Eustasio Rivera Romulo Gallegos Horacio Quiroga and William Ospina) excerpts from the anthropological discourse of Wade Davis narcotraffic narratives testimonial literature (by Ingrid Betancourt and Clara Rojas) as well as environmental discourse and film in order to analyze the particular forces of history that intersect in each narrative. Topics to be discussed will include: exploitation and subjugation vs. autonomy and self determination; the search for ethnobotanical knowledge and the hallucinogenic journey; the playground and hidden operational spaces of drug traffickers; the imprisonment of the kidnapped victims from the guerrilla war against the state and paramilitary forces; the environmental movement and the concept of ecotourism. We will frame our analysis in contemporary critical theories relevant to the topics being discussed. Upon completion of this course students will be able to critically understand the value and complexity of the jungle in the geography and imagination of the Latin-American modern landscape and identity.</p> </div>','One Spanish 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8819,2021,770,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-377','<div class="desc"> <p>Although magical realism remains a difficult term to define there is some consensus that Miguel Angel Asturias (from Guatemala) Alejo Carpentier (Cuba) Gabriel García Márquez (Colombia) and Isabel Allende (from Chile) are the most renowned practitioners of this literary genre. Pre-Columbian mythology peasant folklore popular Catholicism European surrealism the genealogical novel and an ethical pressure on Latin American writers to represent their national cultures all play a part in the development of magical realism in Latin America. The course explores why <em>Men of Maize</em> (Asturias) <em>The Kingdom of This World</em> (Carpentier) <em>One Hundred Years of Solitude</em> (García Márquez) and <em>The House of the Spirits</em> (Allende) are considered paradigmatic works of magical realism. Throughout the course students will be asked to reflect upon the contested meanings and history of the term "magical realism" as the term is applied to different works of Latin American fiction.</p> </div>','One 300-level Spanish course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8820,2021,987,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-378','<div class="desc"> The course adopts a multidisciplinary approach to the question of how place and landscape (Buenos Aires and the pampas) influence literary and filmic imagination. Buenos Aires is one of the great cities of Latin America. Readings for the course include nineteenth-century essays and stories which document the harnessing of the agricultural resources of Argentina into a meat-exporting economic machine; turn-of-the-century fiction and essays also document the transformation of Buenos Aires by new European immigration (often non-Spanish), the impact of European anarchist thought, and the architectural boom at the end of the nineteenth century. Mid-twentieth-century writers such as Borges, Cortázar and Sábato will be discussed in the context of their references to specific Buenos Aires neighborhoods (e.g. Chacarita, Belgrano, San Telmo, and Retiro). Through documentaries and narrative films, the second half of the Spring course introduces students to the rise of the Argentine Armed Forces, the enduring influence of Peronism, the trauma of the dictatorship years, and the economic and political contradictions of contemporary Argentina. </div>','SPAN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8822,2021,771,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-382','<div class="desc"> <p>This course analyzes the narrative development of the contemporary Mexican novel from the Mexican Revolution to the present. Principal novelists studied in this seminar are Mariano Azuela Juan Rulfo Carlos Fuentes Gustavo Sainz Elena Poniatowska Angeles Mastretta and Laura Esquivel. This course combines textual analysis with the application of contemporary literary theory.</p> </div>','One Spanish 300 level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8823,2021,389,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-383','<div class="desc"> <p>This course offers a representative overview of Chicano literary production covering five genres: poetry theater novel short story and essay. An historical framework is outlined to establish the different periods of Chicano creativity from its origins to contemporary times using a series of works and authors to illustrate their respective social context.</p> </div>','SPAN 301, SPAN 302, SPAN 303, or SPAN 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8825,2021,772,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-397','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8826,2021,1428,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/300/span-398','<div class="desc"> <p>The goal of the Community Translation Internship is to provide students with an experiential understanding of the practice of translation. The Community Translation Internship allows students to learn through direct experience the different steps in the translation process as well as examine the challenges that bilingual professionals face in their efforts to reach out to underserved populations such as the Spanish-speaking communities. All students enrolled in the Community Translation Internship work with a community-based organization for an average of eight hours a week.</p> </div>','SPAN 340 or above and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8827,2021,390,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/400/span-490','<div class="desc"> <p>This course will provide an in-depth analysis of one or more of the following genres: drama poetry essay novel short story and film with an introduction to contemporary literary film and cultural studies theory. Texts will be drawn from Spain and Latin America. Open only to Spanish majors in their senior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8829,2021,773,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/span-spanish/400/span-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8830,2021,392,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-101','<div class="desc"> <p>The ability to read a play with insight and imagination is foundational to studying and making theater. Because playscripts are meant for the stage and not the page, the techniques we use to read them are uniquely challenging. In this course, we study scripts by a variety of contemporary American playwrights, investigating the elusive relationship between the text and its ultimate destination - the live stage. By focusing on the essential elements of dramatic writing (including character, structure, language, and thematics), and placing scripts in their social, cultural and political contexts, we work to unlock each narrative’s full performative potential. Our understanding is enhanced by creative research projects and viewing key productions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8831,2021,393,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-110','<div class="desc"> <p>This course is the foundation of our acting program. In it our students explore how an actor gives life to words and moves from a script to active performance. Students work with Shakespeare''s sonnets as well as contemporary pieces to develop physical and verbal facility as well as interpretive skill.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8832,2021,394,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-120','<div class="desc"> <p>In this course we introduce students to many of the different areas of theater production with a primary focus on scenic construction, also including drafting, lighting equipment, rigging practices and special effects. <em>The course includes a laboratory through which techniques taught in class are applied. The laboratory averages 36 hours over the semester with laboratory schedules to be arranged with the instructor. Students are required to purchase some materials for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8833,2021,395,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-121','<div class="desc"> <p>Our production laboratories are applied courses for student designers, technicians and managers who are on crews of productions directed, designed or directly supervised by faculty members in the department. In order to complete a theater minor or major, students are required to complete production laboratories in two separate areas, one of which must be a running crew for a department production. The course may be repeated for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','THEA 120 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8834,2021,396,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-122','<div class="desc"> <p>These laboratories are designed for our student designers technicians and managers who are given primary responsibility on production crews directly supervised by faculty members in the department. In the laboratories students pursue additional research and practical applications beyond the requirements of THEA 121 and may use this course to meet one of the THEA 121 requirements for a major or minor. </p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8835,2021,397,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-130','<div class="desc"> <p>In this course students study the theory and apply the methodology of the Jose Limón Technique. Developed from the principles of fall and recovery the Limón Technique is built upon motion through succession suspension alignment and opposition. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8836,2021,774,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-131','<div class="desc"> <p>In this course students learn the fundamentals of jazz and tap dance with an emphasis on body alignment strength flexibility rhythm and coordination. During the semester we experiment with lyrical and contemporary jazz combinations as well as tap variations designed to develop musicality self-expression and performance skills. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8837,2021,398,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-133','<div class="desc"> <p>Tai Chi Chuan is the study and practice of slow controlled movement, breathing, and realignment of the body. Sometimes referred to as standing yoga, Tai Chi Chuan has been practiced for centuries for its many benefits, including stress management, disease prevention, and increase in energy. Our focus in this class is on relaxation, gentle movement, and meditation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8838,2021,399,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-134','<div class="desc"> <p>In <em>Beginning Ballet</em> we study the principles and execute the techniques of ballet based on the Vaganova method. Students are taught the fundamentals and elementary vocabulary of ballet through <em>barre</em> center and traveling combinations and exercises. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8839,2021,400,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-137','<div class="desc"> <p>This is an introduction to a study of choreography based on the Nikolais/Mettler methods of creating dances. Our tools include the manipulation of motion through space time shape and energy volumes within the context of the body and its surroundings; and our work culminates with studio performances of pieces choreographed by the students in the class. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8840,2021,401,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-139','<div class="desc"> <p>Exploring the richness of African dance and music traditions from four African regions, this course is devoted to the study of authentic dances, songs and drumming from Africa, as well as their historical and cultural contexts. Students may choose to focus on either dance or percussion. Percussion students will learn traditional rhythms for djembe and talking drum as they inform and interact with dance movements. Dancers begin with exercises to condition our bodies for the rigor of the African Dance forms -- developing strength, stamina, coordination, flexibility, and rhythmic awareness, and move to the informed and joyous practice of the dances. <em>Graded on a Credit/No Credit basis only. May be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8841,2021,1495,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-141','<div class="desc"> <p>We study and practice some of the most popular dance forms of the twentieth century. Through theater film and television many of these dances have expressed the spirit and the style and particularly the romantic temper of their times: from the quick steps of the Fred Astaire films to the swing dancing in <em>Malcolm X</em> and <em>A League of Their Own</em> and the tango of <em>The Scent of a Woman</em>. The dances taught include fox trot waltz swing and tango. We strongly recommend this class for our student actors. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8842,2021,403,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-142','<div class="desc"> <p>In this course students study folk and historical dances drawn from Eastern and Western Europe along with folk dances of the United States derived from those traditions. Performance opportunities may include Viennese waltz and dance-based children''s theater. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8843,2021,1742,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-143','<div class="desc"> <p>Students explore the rich traditions of Latin Dance from its origins in the African diaspora found in Cuba, Caribbean and Latin American nations as well as the influence and effect of these dances throughout popular Western culture. Students embrace through performance various dance forms developed in Mexico and throughout Central and Latin America and study the place and importance of the dances in Latin cultures.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8844,2021,775,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-175','<div class="desc"> <p>This introductory design course grounds students in aesthetics as they relate to design for performance and the role of design in the collaborative process of production. Those students interested in becoming designers receive a foundational experience for specializations offered in subsequent classes. Students explore elements of design and the principles of composition as they can apply to theater and film. Over the semester students come to understand and acquire the skills to develop visual expressions of the meaning of play and film scripts. Through individual and group design projects, students learn to incorporate script analysis, design research, and visual presentation techniques. This course is intended for first and second year students. Juniors and seniors may enroll with the permission of the instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8845,2021,1135,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-190','<div class="desc"> <p>Theater Now takes students off campus and in to local performance venues to see the work of diverse artists making theater from a broad base of inspirations. A wide sample of local theater is represented – thematically, geographically, culturally. Friday evening field trips take students to a variety of Los Angeles’ artistic outlets, while Monday afternoon sessions with guest artists put class members in direct contact with the actors, writers, and directors whose plays and performance pieces they have seen. Our work offers a comprehensive introduction to active theater-going, L.A.''s performance community, the creative habits of working artists and the social, political and aesthetic ideas behind their work. T<em>here is a ticket fee not to exceed $75 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8846,2021,2866,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-195','<div class="desc"> <p>What does performance do? Why perform? What is the essence of the “live” and what is the impact of being in the same time and (virtual) space? We will unpack these questions through analysis and performance, looking closely at seminal pieces that speak to this moment and calling on experts in design, technical theater, comedy and solo performance to give behind-the-scenes insight into the making of live performance. Bracketed around questions of liveness, social action, and impact, students will take specialized workshops with theater faculty who will address these questions through their areas of expertise, providing students opportunities to experiment with an array of performance practices.</p> </div>',NULL,'CSP 27 and ARTS 250 ',NULL);
INSERT INTO course_descriptions VALUES(8847,2021,776,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/100/thea-197','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8848,2021,990,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/copy-of-thea-245','<div class="desc"> <p>Students in <em>Stage Makeup</em> learn the fundamentals of makeup design for the theater. We cover a number of makeup techniques including basic three-dimensional corrective, glamour, character and old-age makeups with some special effects makeup. During the semester, students put theory into practice as they create a variety of practical and creative makeup designs. <em>There is a materials fee for this course, not to exceed $75.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8849,2021,2891,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-200','<div class="desc"> <p><strong>Immersive Visual Environments with Commonplace Technology</strong></p> <p>Contemporary theater—especially as performed on Broadway—has become a high tech multimedia production with budgets in the millions. How can emerging theater artists compete with this level of spectacle and/or create new work that is equally compelling? In this course students will learn how to check the boxes of the newest innovations in big budget theater and performance without the financial demands. We will level the playing field by creating forms of high spectacle through economical means. Students will learn to devise spectacular visual stories using commonplace objects. Throughout this project based course, students will study the fundamentals of visual storytelling both through playing with lights and shadow led by cutting-edge artist Christine Marie and through developing story with performance artist and professional storyteller David Crabb. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8850,2021,988,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-201','<div class="desc"> <p>We study the artistry of contemporary theatrical movements as well as American writers from divergent cultural and aesthetic backgrounds. By looking at movements and artists in their cultural and social contexts we explore the sources the aims and the artistic strategies of their works while developing an understanding of important new voices in American Theater. The focus of the class will vary from year to year. May be repeated for credit one time with a different topic.</p> <p><strong>The Black Arts Movement Explored and Deconstructed</strong></p> <p>An in-depth, intellectually stimulating exploration into the complex and impactful Black Arts Movement of the 1960s and 1970s. Through reading and analyzing the poems, plays and criticism of the time, as well as lectures and small group discussions and “on your feet” performance activities, students will gain insights into the people, the places, and the critical junctures that emerged during this profoundly explosive era of art and culture. Artists explored include Amiri Baraka, Sonia Sanchez, Nikki Giovanni, Henry Dumas, Audre Lorde, Ed Bullins, Ntozake Shange, and others. Themes/concepts include black identity, the connection between black arts and black power, the rejection of integration as an ideal, LGBTQ and Black Arts, the assassination of Malcolm X, John Coltrane and Sun Ra, black radical thought, the African-American male as a Christ figure, male chauvinism in Black Arts and Black Power, and “future directions,” i.e. the influence of the Black Arts Movement on other cultural movements and American aesthetics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8851,2021,404,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-202','<div class="desc"> <p>Looking at a small number of Shakespeare''s scripts from the vantages of actor director and playwright we examine the unique and complex relationship between Shakespeare''s literary constructions and their possible performances. We analyze how through language and structure he develops characters of psychological complexity; how he develops stories from extra-theatrical material; and how in style and subject matter his scripts relate to one another. This course offers students a bridge between literary study and theatrical enactment: looking closely at Shakespeare''s designs from the perspective of the theater practitioner-from in most ways Shakespeare''s own perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8852,2021,1136,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-203','<div class="desc"> <p>In this course we investigate a variety of 20th and 21st century theatrical productions across the globe staged during times of conflict and crisis: from online performances to amateur stages in restaurant back rooms in workers'' clubs and cafes to professional and Broadway theaters. From the 1920''s agitation trials (<em>Agitsudy</em>), mass spectacles and agitprop theater during the Russian Revolution to contemporary theater''s responses to COVID 19, anti-blackness, and other forms of racism and social oppression, we will examine how artists and activists use theater to respond to social and political unrest: sometimes as a tool to fight oppression and at other times as a tool to encourage obedience and propagate national political ideals. From performances staged in Sarajevo to Rio de Janeiro, from Mexico City to New Orleans, and from the streets of Moscow to the streets of New York City and beyond, the class thinks through art as activism and activism as art, examining how theatrical tactics transcend the boundaries of traditional performance spaces. We examine the performance theories and strategies emerging from these theatrical moments as we study seminal plays from these periods. For the final project, students in the class will develop performance projects in response to a contemporary crisis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8853,2021,1317,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-204','<div class="desc"> <p>In this course, we introduce students to the ways comedy can influence and transform society. We will study scripted as well as unscripted forms of performance, including stand-up, physical comedy, sketch, Teatro Campesino style <em>actos</em>, and faux news shows. Students develop an understanding of the role comedy plays in socio-political critique through research of issues about which they are passionate and in the subsequent creation of solo and group work illuminating those issues for their peers in a final cabaret performance. Not open to frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8854,2021,2362,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-205','<div class="desc"> This course addresses the fluid boundary between law and performance. We will think through how performances of law influence legal practice and vice versa. We will also interrogate how theater provides an alternative site for the performance of justice, one that may satisfy needs that go unmet in state and federal courts. We will study trial transcripts as legal and cultural documents, and we will look at their dramatizations, putting these plays into conversation with contemporary theater, performance, and legal criticism while also thinking about how our own needs and impressions of justice have been, or can be, staged in and through performance. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8855,2021,2900,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-206','<div class="desc"> <p>In this energetic and creatively maddening class, students will explore Shakespeare’s <em>Richard III </em>and several adaptations in a unique and highly charged manner. By yanking the Bard off his high horse, and identifying universal themes and structural innovations inherent in Elizabethan poetic meter, course participants will gain newfound understanding and appreciation for the work and legacy of Shakespeare. Instead of looking at classic works as an untouchable, or “holier than thou,” canon instead we will investigate how playwrights have been inspired by, deconstructed and reconstructed them. In addition to Shakespeare’s <em>Richard III</em>, students will explore several bold adaptations such as Carlyle Brown’s <em>The African Company Presents "Richard III,"</em> <em>Teenage Dick </em>by Mike Lew, as well as Will Power’s own <em>Seize the King</em>. Perhaps most importantly, students will have the opportunity to learn iambic pentameter, construct their own post-modern, Shakespearean mash-up scenes, and learn the very-latest contemporary methods of verse-based performance. In this performance seminar, we will compare and contrast Shakespeare’s metric language with other heightened language forms, from ancient Greek poetry to hip hop lyrics. Filled with rhythm, poetry, and both an appreciation and utter disdain for anything old and crusty, this course promises to be a ridiculously crazy, wild ride for the ages. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8856,2021,405,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-210','<div class="desc"> <p>In this course students develop a deeper sense of physical expression, kinesthetic response, ensemble work, creativity, and imagination. Students apply this training in solo and scene work both in the studio and on camera. At the end of the semester, students apply the preparation and techniques learned throughout the semester in final scene projects using script analysis, character work, object work, and physical expression in both classical and contemporary texts. <em>There is a ticket fee not to exceed $50 for this course.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8857,2021,406,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-211','<div class="desc"> <p>Our Performance Laboratory is offered as an applied acting course based upon roles played in our professionally directed Keck Theater productions. This course is offered only for grades of Credit/No Credit and may be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8858,2021,777,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-212','<div class="desc"> <p>In this course student actors will continue to develop audition techniques introduced in <em>Introduction to Performance</em> and <em>Acting 1</em> applying them to the standard "general audition" format. In addition our students learn about the audition and casting process in professional theater through a guest speaker series of casting directors and professional film and stage actors. Not open to frosh. <em>Graded on a Credit/No Credit basis only. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8859,2021,778,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-215','<div class="desc"> <p>Working with selected scripts from the best of recent and contemporary screenplays our students develop techniques for working in front of a camera as a specific application of the work of both <em>Acting 1</em> and <em>Acting 2</em>. <em>There is a materials fee of $60 for this course. THEA 310 is strongly recommended as preparation.</em></p> </div>','THEA 210 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8860,2021,779,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-225','<div class="desc"> <p>In this course we introduce students to a variety of scenic techniques and materials employed in theatrical scene painting with aesthetic theory and period styles serving as the foundation of the work. Special materials are purchased for the students of the course. <em>There is a materials fee of $65 for this course.</em></p> </div>','THEA 120, THEA 175, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8861,2021,408,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-234','<div class="desc"> <p>Students develop and refine ballet technique based on the Vaganova Method. This course is offered only for grades of Credit/No Credit and may be repeated for credit.</p> </div>','Two semesters of THEA 134, by or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8862,2021,782,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-237','<div class="desc"> <p>Building upon the work from <em>Beginning Choreography</em> students develop more sophisticated choreographic strategies language and techniques with an emphasis on group choreography including site-specific work and studio performances. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','THEA 137 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8863,2021,411,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-244','<div class="desc"> <p>Our stage management course introduces students to the art and techniques of stage management helping them acquire the theoretical knowledge and the practical skills to manage theatrical productions from casting through performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8864,2021,883,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-246','<div class="desc"> <p>In <em>Costume Construction</em> students acquire the skills necessary to construct basic garments for the stage. At the end of the course each student will build a costume piece.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8865,2021,1042,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-248','<div class="desc"> <p>We introduce students to the theory and application of sound and music as elements of design for theater dance and other collaborative multimedia dramatic forms. Throughout the semester we address fundamental issues of sound design: including script analysis conceptual approaches to sound music underscoring working with audio equipment and sound editing. Over the semester our students learn how to work within a creative team of designers coordinating the many design elements of various dramatic forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8866,2021,1102,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-250','<div class="desc"> <p>Period style can be characterized as the aesthetic traits common to a particular historic or cultural moment. For recorded media and live performance, writers, directors and designers set their storytelling in a framework of time and place. In this class, we explore examples of shifting styles across select non-Western and Western cultures and through time and seek to discern their influence on other cultures or historical periods. Through this exploration, we begin to understand how architecture, interior design, fashion history and the act of dressing evolved throughout the centuries and across cultures because of technological advancements, changes in economic and social class structures, in political climates and through appropriation of cultural aesthetics. Why was there a kimono specialist in the costume department of <em>Westworld</em>? How did Ruth E. Carter develop her Afrofuturist vision for <em>Black Panther</em>? Where would you find visual and dramaturgical resources for <em>Vietgone</em>, or <em>Hair</em>, or <em>Cambodian Rock Band</em>, the action of each set in a similar historical period but whose stories are told from very different cultural perspectives?We will investigate these and other questions through reading, and critical analysis of visual records, plays and films, in-class discussions, and presentations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8867,2021,412,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-260','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take 260 and 261 in either order. In four intensive sessions, students learn five workshops geared to the third grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited.</p> </div>','THEA 110 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8868,2021,783,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-261','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take THEA 260 and THEA 261 in either order. In four intensive sessions students learn five workshops geared to the fifth grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited. Graded on a CR/NC basis only.</p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8869,2021,413,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-275','<div class="desc"> <p>Our course in scenic design provides intermediate training in technique and exploration of theory specifically aimed at designing scenery for the theater. Our students learn several methods for developing and communicating their design ideas including basic drawing and drafting concepts CAD drafting using <em>VectorWorks</em> and both physical and digital model-making. <em>There is a materials fee of $60 for this course.</em></p> </div>','THEA 120, THEA 175, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8870,2021,2567,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-290','<div class="desc"> <p>This topics course provides opportunities to work on performance outside of traditional naturalistic traditions. Topics change annually. First-year students may only take this course with permission of instructor. May be repeated once for credit when taken as a different topic. <em>Note: Different topics may satisfy different Core requirements</em>.</p> <p><strong>Creating Community Engaged Theater</strong></p> <p>Under the guidance of members of the world renowned and community engaged Cornerstone Theater Company, this course will introduce students to the Cornerstone method of creating original theater work that addresses local concerns through community collaboration. During the course, students will help with The Highland Park Community Project—Cornerstone’s community engaged project in rehearsal and performance in Fall 2020. This production will provide the experiential aspects of the course, some of which will take place off-campus in the Highland Park Community. In regularly scheduled class meetings, students will study the Cornerstone methodology, especially intention and engagement, and through discussion, lectures, and research, be introduced to existing approaches to community based theater. Topics will include how community engagement informs acting, directing and design. <em>Core Program requirements met: Fine Arts and U.S. Diversity</em>.</p> <p><strong>Reframe the Game: Strategies for a More Inclusive American Theater</strong></p> <p>Reframe the Game is a deep dive into Equity, Diversity and Inclusion (EDI) principles, as they apply to working in the theater, as well as in interpersonal communication practices. Through hands-on activities, discussions, research and interactions with guest practitioners, the course will address why this work is vital to our field, and how EDI lays the foundation for more creative and imaginative artistic workspaces and practices. The course will be organized into three parts. Part One will focus on Vocabulary and Power Structures: The cohort will focus on establishing a shared vocabulary as a foundation for conversation about social identity, privilege, historical and institutional inequities, and ally-ship, as a means to develop skills to better identify and dismantle inequity when we see it. We will look inward to examine where we as individuals fit into the social landscape of America, and how our identities affect how we move through the world. Part Two will focus Research and Examination: Students will research EDI initiatives and strategies at US regional theaters as case studies to examine how stated EDI principles may (or may not) align with programming and institutional culture. In addition, local guest artists and practitioners whose work strongly aligns with social equity will visit the class for deep dive conversations about the work that they do, the challenges they face, and where they see the future of our field. Part Three will focus on Final Projects and the question What Now?: In small groups, students will apply what they have learned over the course of the semester to create an original exercise, workshop or governing policy that addresses a specific EDI concern in their community (institutional, local, national or international) to present to their classmates and invited faculty in the final weeks of the semester. Prerequisite: THEA 101, THEA 210, or by instructor permission. <em>Core Program requirement met: Fine Arts and U.S. Diversity.</em></p> <p><strong>Generating Independent Theater</strong></p> <p>This interdisciplinary course will provide an opportunity for students to define their interests as performers/writers/producers and to develop original material, an artistic vision, and producing expertise that will lead to a realized performance. Individual skill sets and interests including storytelling, dance, character-work, visual art and music may each provide a jumping off point for this work. At the beginning of the course, a series of improvisational exercises, mini-performances and character studies, supported by readings on contemporary solo, immersive, experimental and environmental theater, will guide students to land on personal solo or two-person projects. In the second half of the semester, students will craft these pieces utilizing their peers as a think-tank. This generative, collaborative process will emphasize the importance of ensemble both onstage and behind the scenes during the creative and production process. To culminate their work, the class will be responsible for the production aspects necessary to present their pieces in a public performance on-campus. Prerequisite: THEA 210, THEA 330, THEA 380, or permission of instructor. <em>Core Program Requirement Met: Fine Arts.</em></p> <p><strong>Autobiographical Performance: Laughing At Ourselves</strong></p> <p>In this course, participants will learn how to create compelling and humorous personal nonfiction narratives for the stage, studying classic narrative structure and paying close attention to theme &amp; detail. There is a long history of performers whose autobiographical solo work, like Crabb’s, simultaneously finds comedy in the tragedies of their lives while infusing the mundane with drama. To learn how to do this, students will study seminal storytellers and theater makers, (such as Spalding Gray, John Leguizamo, Whoopi Goldberg, Julia Sweeney, and others) who use their lives and experiences as templates for performance. Students will also review Moth-style storytelling to help find their own voice through a close examination of identity, self, and how we perform in the world. <em>Core Program Requirement Met: Fine Arts.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8871,2021,991,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/200/thea-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8873,2021,1356,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/copy-of-thea-315','<div class="desc"> <p>In this course, designed for the novice performer as well as the advanced actor or singer, we focus on introducing students to the art of acting a song. We examine the literary and musical elements of scripts to reveal character and narrative, only here we do this while singing. Performers prepare and present musical selections from the Broadway canon, exploring how the elements of healthy singing (including breath control, phrasing, and placement) help convey character and story. Through freeing our musical voices to best express persona and narrative, we we examine the intersection of singing, acting, and audience connection. All experience levels welcome. A ticket fee, not to exceed $50, is associated with this course. Prerequisite: at least sophomore standing or permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8874,2021,993,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/copy-of-thea-320','<div class="desc"> <p>Building on the foundation of Introduction to Technical Theater, the students in this course learn advanced construction techniques, metal working and welding, furniture construction and repair. Students in the class will also act as crew chiefs for Theater Department productions.</p> </div>','THEA 120; and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8875,2021,414,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-301','<div class="desc"> <p>As artists and scholars, we will discuss and study several key moments in theater history from Greek Drama to Medieval religious performances to modern and experimental theater. Throughout the semester we will examine theater-in-context, attending to the circumstances (political, social, historical, and artistic) surrounding the performance event. We will engage with drama theory to deepen our analysis of dramatic texts and the performances of them. With an emphasis on close readings, critical thinking, and creative engagement with the materials, we will interrogate the boundaries between performers and audience and the ways theater makers have used performance to challenge or affirm the status quo. <em>There is a ticket fee of $75 for this course.</em></p> </div>','THEA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8876,2021,992,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-302','<div class="desc"> <p>During the semester we study the works of various twentieth century playwrights. Different years will feature different playwrights: so one semester might look at farceurs another semester political pioneers and another European iconoclasts. In addition to reading several scripts by each playwright our students also attend live performances prepare research projects and create performance projects in response to the semester''s writers. Students may use this course to fulfill the Junior Writing Requirement for the Theater Major.<em> There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8877,2021,1496,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-303','<div class="desc"> <p>The focus of this course is on the history literature and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works while play attendance will keep our focus on these plays as performance. <em>There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8878,2021,415,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-310','<div class="desc"> <p>Acting 2 advances the techniques and skills introduced in Acting 1. Students will continue to explore character development and scene work through an array of texts and styles. Students will also explore acting methods that will help them become more flexible, daring, collaborative, and creative performers. An emphasis will be put on Solo-Performance techniques. Students will actively create a self-sustaining piece of solo theater from conception to creation and finally to the stage. Course participants will also discover and evaluate texts and performance practices of previous solo-theater practitioners. In the process, students will learn how to act with increased freedom and to create characters with genuine psychological complexity, accumulating tools and skills applicable to working both on stage and on screen.</p> </div>','THEA 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8879,2021,417,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-311','<div class="desc"> <p>Our upper-division applied acting course is available for students performing significant roles in professionally directed Theater Department productions. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit. It is available only with permission of the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8880,2021,784,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-316','<div class="desc"> <p>In this culmination of the Theater Department''s acting sequence our students explore through practice the demands Shakespeare''s scripts make upon actors. During the semester students in the class work with five to six of Shakespeare''s scripts from various genres in order to develop facility with Shakespeare''s verse and prose in performance.</p> </div>','THEA 202 and THEA 310; or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8881,2021,994,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-325','<div class="desc"> <p>Studying the theories the psychological foundations and techniques of lighting design for the theater our students develop in this course an intellectual and practical foundation of this significant and accessible area of theater design. During the semester we guide students in the class through bothindividual and group design projects. <em>There is a material/tickets fee of $60 for this course which includes one two-hour laboratory session each week.</em></p> </div>','THEA 120, THEA 175, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8882,2021,785,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-330','<div class="desc"> <p>Students in this course analyze the various requirements for producing live performance events. In developing solutions to the many difficulties presented by live events we examine in particular the artistic, legal and financial responsibilities of the producer. Through projects, case studies, and research, our students look at the creative and practical aspects of live presentations as they come to understand the myriad considerations required to successfully produce live performances for theater music and other cultural events. Not open to first year students.</p> </div>','THEA 120 and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8883,2021,418,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-370','<div class="desc"> <p>This course develops a deeper understanding of the process of costume design for theater and film. Students will develop individual costume processes by learning to research, conceptualize, and design. In addition to creative aspects of design, students will develop the ability to break down scripts for both the stage and screen, learn to budget for shows, and develop a language within the industry. Prior art experience is not mandatory. Free hand drawing, digital rendering, and collage will be explored and developed in projects for the course.</p> </div>','THEA 175 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8885,2021,419,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-380','<div class="desc"> <p>We engage our students in Playwriting with the art of writing for the live stage. Through reading scripts by established authors and generating original writing, students develop their dramatic skills and theatrical imaginations. Creative assignments focus on crafting well-developed characters, sound story structures and compelling dialogue. As a final project, each student writes and rewrites a short play. Sophomore standing or permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8886,2021,420,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-390','<div class="desc"> <p>For advanced theater students we offer an applied course for significant work undertaken in performance design technical theater or management in faculty-supervised projects. A student enrolled in this course works directly with a faculty mentor in the design and execution of the individual project. </p> <p>Section 1 - Advanced Projects in Theater: Story/Voice/Community </p> <p>Section 2 - On-campus projects</p> <p>Permission of instructor required. Course may be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8888,2021,787,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/300/thea-397','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8889,2021,788,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/400/thea-410','<div class="desc"> <p>We introduce students to the art of directing. Our students explore the directing processes of script analysis casting working with actors manipulation of space use of sound and images developing designs and mounting productions for theater. During the semester students in the class stage two performance sequences: one in a classroom format the other produced on the Keck stage. THEA 316 is strongly recommended for preparation. This course may be repeated for credit. Permission of instructor required.</p> </div>','THEA 120 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8890,2021,421,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/thea-theater/400/thea-490','<div class="desc"> <p>This is a course for students engaged in senior comprehensive projects in Theater. <em>Only open to senior Theater majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8892,2021,423,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-101','<div class="desc"> <p>This is an introductory course on environment and society designed for students with an interest in urban and environmental issues who might want to pursue further studies in Urban and Environmental Policy. It is also offered for those who are interested in the topic even though they will be pursuing another major. The course will include lectures and presentations in several different topical areas; films and speakers that provide insight into the environmental problems and alternative solutions including those based here in Los Angeles; and class discussions and presentation sessions on the readings and topics. The course provides an broad introduction into core topics in urban and environmental policy such as: water issues (where our water comes from); wastes and hazards issues (sources and impacts of pollution); climate change transportation and land use issues (where we work and live and commute); nature in the city (the urban environment); and food system issues (where our food comes from and how it is manufactured and sold) the intersection of science and policy and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8894,2021,1357,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-201','<div class="desc"> <p>This course is designed to provide students with an understanding of the environmental factors impacting human and ecological health including consequences of natural and human-made hazards. Environmental health is a rapidly growing and interdisciplinary field that involves both science and public policy. It is integrated into numerous aspects of our lives both directly and indirectly. Topics to be covered include food safety water access and equality pesticides air quality the identification of environmental hazards the assessment of various risks (including exposure to dangerous chemicals used in toys food workplaces and other activities) and the social and biological causes of disease (epidemiology) Students will gain an understanding of environmental health analytical and scientific methods. We will also explore ways that communities and policy-makers seek to address environmental health challenges. A common thread running through the course will be an examination of how exposure to environmental and health risks vary among different population groups in the Los Angeles area in the United States and around the world and the ways that scientific issues become embedded in and inseparable from issues of policy regulation and justice. We will also explore the role of science in environmental policy-making the enforcement of regulations and the efforts of community groups to influence public policy. (Students are encouraged to enroll in Geology 150 a laboratory science that in parallel explores the spatial and geographic dimensions of environmental health.</p> <p>Not open to frosh without permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8895,2021,995,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-204','<div class="desc"> <p>The course presents a broad view of the roots of environmentalism including the relationship of environmentalism with respect to issues of class race gender and ethnicity. It situates the history present day circumstances and future direction of the environmental movement within the broader study of environmental topics and methods. It also provides the background to understand better the significance of this crucial social movement and how it has addressed the complex relationships between urban industrial and natural environments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8896,2021,424,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-205','<div class="desc"> According to Thomas Jefferson, America was to be an "agrarian Republic" -- a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones as well. Indeed, for many early migrants, America was itself a "city on the hill" -- an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing in the second half specifically on Los Angeles, where new forms of decentralized urbanism took form in the twentieth century. We will explore not only suburbia and freeways, Disneyland and other quasiÂ­urban outposts, but also the changing character of the inner city in the midÂ­twentieth century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today -- multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism -- the changing character of public space, the turn to privatism, and the neglect of public transport infrastructures, challenges to democracy and equality -- are ultimately compatible with the American dream of the "city on the hill" for the twentyÂ­first century. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8897,2021,1198,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-209','<div class="desc"> Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8898,2021,884,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-210','<div class="desc"> <p>Los Angeles is a city often known for its traffic, air pollution, auto-centric land use patterns, and car culture. However, Los Angeles is also a place of transportation innovations and a public commitment to changing the way people move to and through Los Angeles in equitable and environmentally sustainable ways. This class provides an overview of urban transportation issues and systems, focusing on the impacts of mobility policies, systems and infrastructure on cities and on Los Angeles in particular. Through lectures, guest speakers, class exercises and projects, students will explore the history of transportation in the US as well as comparatively with other countries and understand the role of policy in shaping and defining transportation systems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8899,2021,886,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-212','<div class="desc"> <p>This course UEP 212 Policy Debates and Controversies in Education will be taught by L.A. School Board member Steve Zimmer. The course will consist of a series of high profile panel discussions about some of the major issues in Education today. These include "The Future of the Urban School District" "The Crisis in Public Education Funding" "Charter Schools and Public Education" and "The Future of Education Reform in Los Angeles and Beyond" among several topics to be developed. Board member Zimmer will then engage with students in a seminar discussion in the subsequent course UEP213 about the issues and debates and research opportunities that follow from the panel discussions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8900,2021,887,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-213','<div class="desc"> <p>This course UEP 213 Policy Debates and Controversies in Education will be taught by L.A. School Board member Steve Zimmer. Students taking the course will be required to enroll in UEP 212 and attend a series of high profile panel discussions about some of the major issues in Education today. These include "The Future of the Urban School District" "The Crisis in Public Education Funding" "Charter Schools and Public Education" and "The Future of Education Reform in Los Angeles and Beyond" among several topics to be developed. The seminar will then engage in discussions about the topics explored in the Panel discussions on the major controversies in Education and identify research topics related to the current policy debates within LAUSD as well as some of the broader debates within Education policy.</p> </div>',NULL,'UEP 212 ',NULL);
INSERT INTO course_descriptions VALUES(8901,2021,1103,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-214','<div class="desc"> <p style="margin-left:0px; margin-right:0px">The struggle for control of our public education system in Los Angeles has become one of the most high profile conflicts facing the city and its residents. The stakes couldn’t be higher. The lives of children and the hopes and dreams their parents literally hang in the balance. In UEPI 214, Professor Steve Zimmer, a long-time teacher and the former President of the Los Angeles Unified School District Board of Education, will guide students through a journey in understanding the role of public education in our society and tensions over different visions and goals for public schools, including its mission to promote equality, equity, and mobility. The course will also explore how public policy can help or hinder public school’s equity mission. The class will examine the effects of expanding racial and economic segregation, increased standardized testing, and toxic stress have on students trying to pursue their dreams and the teachers trying to make those dreams come true. The class will also assess the impact of teacher tenure reform, the expansion of charter schools, the community schools movement and other policy based debates that could influence the future of teaching and learning. Through guest lectures, panels, films, and readings, students will understand the role that policy and collective action can play in pursuing a collaborative agenda. The final project will involve actually writing policies to be presented to the Board of Education and/or other policy makers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8902,2021,1743,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-230','<div class="desc"> This course will cover the problem of climate change and the history and evolution of the climate justice movement. It will examine the organizing and policy tools used by advocates to advance climate justice. The course will begin with an exploration of climate change, the environmental and political factors that cause the climate to change, and why the issue matters to communities across the globe. The course will then look at the history and foundational concepts of climate justice with particular focus on how issues of race and class impact climate justice. Finally, the course will look at how the traditional environmental movement, the labor movement, and global movements advocate for climate justice and what priorities they advance. Key topics to be covered are: the intersection between race and the environment, the relationship between traditional environmental movements and the environmental justice movements, labor movements and the green economy, global solidarity movements. </div>','UEP 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8903,2021,425,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-246','<div class="desc"> <p>This course will give students applied project management experience in sustainability and urban climate resilience. Students will work on projects with partner organizations in Los Angeles addressing issues such as organic waste management, food recovery, urban forestry, food supply chains, ecological restoration and more. This course will engage students in the larger movement for sustainability in Los Angeles as well as on campus. Note: this course will require students to travel independently off-campus. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8904,2021,789,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-247','<div class="desc"> <p>This class is a collaboration between the Urban and Environmental Policy Institute (UEPI) and the FEAST (Food, Education, and Sustainability Team) student service to enhance student capacity to lead and engage with food and gardening projects both on campus and in the community. Through the implementation of projects in campus garden spaces, participation in community service learning projects, and field trips to innovative food programs in Los Angeles, students will gain hands-on understanding of food issues and will complete the course with the ability to help in the design, creation, and maintenance of a garden-based food or sustainability project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8906,2021,1138,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-295','<div class="desc"> Topics vary semester to semester. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8907,2021,1634,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8908,2021,1565,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-299','<div class="desc"> This course will explore the impact of sports participation on female experiences, specifically considering multilevel psychological and socio-cultural women''s empowerment measures, such as self-esteem, self-efficacy, and solidarity. Focusing primarily on soccer, we will consider the possibility that the very act of training the body through sports contributes to a greater sense of ownership of one''s body -- a critical psychological state for women''s health, personal security, and ultimately empowerment. Through the framework of social cognitive theory of gender development, we will also examine the relationship between, physicality, psychology, and gender identity development. Finally, over the course of the semester, we will vet sports participation as an intervention to address gender inequality, including the impact of relevant policy, such as Title IX. Through a community-based learning component, students will have the chance to engage in qualitative inquiry on the effect of sports on health and self-concept. Same as Kinesiology 299. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8909,2021,2568,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-300','<div class="desc"> <p>This course analyzes the legal and policy framework for environmental protection and environmental justice. The course covers the major environmental statutes, applicable civil rights laws, and the next wave of climate change litigation. This course will also place environmental law and policy within the larger conversation around environmental protection and climate change.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8910,2021,790,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty, housing, transportation, crime and violence, pollution, racial segregation and gentrification. It also examines how power is exercised by different groups including business, citizens'' groups, community organizations, unions, the media, mayors and other government officials. The course will also examine the role of city planning and planners, conflict and cooperation between cities and suburbs, problems of urban sprawl, loss of open space, water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe, Canada, and the developing world. Public policies to solve urban problems.</p> </div>','UEP 101, POLS 101, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8911,2021,996,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-302','<div class="desc"> <p>This course examines how societies provide people with shelter - through market forces government policy and self-help efforts. The course will focus on the United States but will also look at other societies to help understand the strengths and weaknesses of the U.S. approach. Students will examine such housing problems as homelessness slums (substandard housing) the shortage of affordable housing racial segregation foreclosures and other topics. It will examine the pros and cons and different forms of rental housing and homeownership. It will look at the connection between housing issues and the environment public health education transportation suburbanization and sprawl poverty and inequality and racism. Students will explore housing as an aspect of our culture such as homeownership as the "American dream" and housing as a "haven." The course will explore the history of housing problems and housing policy including zoning racial discrimination finance public housing different government subsidies for housing and taxes. We will debate whether decent housing is a "right". We will look at housing problems and policies at the local state and national levels. Students will explore the politics of housing in terms of the various interest groups - including developers banks tenants community organizations landlords contractors unions and others -- involved in shaping housing policy. Students will also learn about housing as part of the "built environment" architecture land use urban design as a component of urban planning and as a part of "livable" cities. They will also examine housing as a component of real estate development and explore what housing developments - whether for-profit or non-profit - do.</p> </div>','UEP 101, ECON 101, POLS 101, SOC 101, UEP 106, or POLS 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8912,2021,791,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-303','<div class="desc"> <p>This course examines sustainable development from a social economic and environmental perspective. The course focuses on development strategies and approaches led by community-based labor and nonprofit organizations in a context of traditional public and private-sector economic development approaches. Through lectures field trips discussion guest speakers and class exercises students will examine the history and evolution of community and economic development strategies in urban neighborhoods and communities and link these approaches to the field of sustainable development. The course focuses on the historic and contemporary debates and issues in sustainable development and delves into the challenges and opportunities of sustainable development in Los Angeles by drawing on case examples from other urban regions across the country. Through the course students will: 1) understand the historical theoretical and policy context of community development; 2) understand community and economic decline and development processes; 3) examine the key strategies of community development and related field of community economic development; 4) explore the growing intersection of community development and sustainable development including the greening of jobs buildings and urban design.</p> </div>','UEP 101, UEP 106, POLS 106, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8913,2021,426,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-304','<div class="desc"> <p>This course trains students in research methods and analysis to understand environmental economic social and political issues relevant to urban planning environmental studies and related policy areas. Students will learn quantitative and qualitative methods with a particular emphasis on community based research methods. Through class lectures discussions field work and group presentations students learn and apply the most commonly used strategies for collecting analyzing and presenting data used in urban and environmental policy research and analysis. Students will work with commonly used data sets such as the Census data sources for health property ownership toxic releases campaign contributions and other information used in urban planning environmental and public policy research. Students will also learn qualitative and basic quantitative research methods including survey construction and analysis participant observation case studies methodologyinterview techniques and basic data analysis using excel.The course will also address ethical challenges raised during collaborative research alongside community-based partners and advocacy groups. The course provides the research fundamentals for the comprehensive research projects in the UEP major.</p> </div>','UEP 101, UEP 106, POLS 106, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8914,2021,427,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305','<div class="desc"> In this course, students will learn how to document and analyze urban and environmental problems and public policies using quantitative data. Quantitative data provide a compelling means by which we can understand the magnitude of urban problems and who is impacted by these problems across demographic groups, neighborhoods, cities, and countries. Quantitative data can also help identify solutions, including public policies, and then evaluate the effectiveness of those solutions. Ultimately, our task is to develop quantitative reasoning skills in order to mobilize facts in the pursuit of a more just and equitable urban society. In the words of urban geographer Elvin Wyly: "Get mad. Get data. Get to work." Or, as Daniel Patrick Moynihan once said: "You can''t solve a problem until you first learn how to measure it." An important aspect of the course is how to make relevant and meaningful comparisons. How can we understand the size and significance of an urban problem such as low-wage work, or housing discrimination, racial profiling by police, or air pollution? We understand these issues best in relation to other outcomes: good jobs, nondiscriminatory housing and police practices, and clean air. We need to measure these outcomes in ways that we can compare them. Toward that goal, students will learn basic mathematical calculations and concepts such as percentages, rates, normalization, baselines, distributions, and probability. We will learn to read and interpret quantitative information presented in various formats, such as tables, graphs, geometric figures, or in text. Students will learn to assess numeric arguments and "answers" for reasonableness, as well as to recognize the limits of quantitative methods. Lastly, students will learn to evaluate how quantitative data is used, and sometimes misused, in the news media and public debates about social, economic, and environmental problems. Students will also engage basic questions of research: What data do we need to answer relevant policy questions? How can we devise a research project that would generate these data? Students will explore basic research methods using quantitative data, such as specifying a research question, research design, sampling, measurement, and validity. </div>',NULL,'UEP 305A ',NULL);
INSERT INTO course_descriptions VALUES(8915,2021,1566,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305a','<div class="desc"> Weekly laboratory for Urban Data Analysis where students will directly manipulate, analyze, and visualize real-world data related to urban problems and policy concerns, such as poverty, wages and low-wage work, housing affordability and quality, transportation equity, air quality, water safety, green space, food access, and crime and public safety. We will focus on identifying and communicating patterns of urban inequality. Students will become familiar with Excel and be introduced to Stata, a statistical software package. Students will learn to manage data, produce basic charts and graphs, generate descriptive statistics, and test hypotheses. </div>',NULL,'UEP 305',NULL);
INSERT INTO course_descriptions VALUES(8916,2021,792,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-306','<div class="desc"> <p>This community based learning course explores a range food systems issues from a food justice lens. The course examines how our food system has been restructured over the last century to benefit large-scale agriculture interests, creating a global food system that emphasizes convenience and fast-food solutions for consumers, often to the detriment of low-income people and communities of color. Through in-depth class discussions, on-site field trips, and in-class speakers, the class will delve into the environmental, economic, health, cultural, and social impacts of to how food is grown, processed, manufactured, distributed, sold, and consumed in the U.S. The community based learning component of this course will involve project work with UEPI’s food programs as well as other Los Angeles-based nonprofit partners and food policy experts. Please note, the first half of the semester will be based in the classroom (T/Th 1:30-2:55pm). During the second half of the semester, class will be held only one time per week (from 11:45am-2:55pm) to accommodate field trips.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8917,2021,1358,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-308','<div class="desc"> <p> At the city and county level, Los Angeles is investing in new infrastructure, transit lines, housing, open space, and civic architecture to a degree rarely seen and arguably unprecedented in American urban history. The total public monies already earmarked through ballot and bond measures and other means is approaching $200 billion all told over the next several decades -- with a significant portion to be spent before 2028, when L.A. will play host to the Summer Olympics for a third time. What will these investments mean for the urban fabric, architectural character, and civic identity of Los Angeles? How can they be made in a coordinated, complementary, and efficient manner? How can they promote innovation while also guarding against displacement and the loss of affordable housing and/or the erasure of neighborhood culture and history? The course will be led by Christopher Hawthorne, professor of the practice at Occidental, who after spending 13 years as the architecture critic at the Los Angeles Times was appointed in 2018 by Los Angeles Mayor Eric Garcetti as the city''s first Chief Design Officer. Along with reading deeply into the urban and architectural history of Southern California, students will meet regularly with Hawthorne''s colleagues in city government and hear from key figures involved in shaping L.A.''s built environment and civic future at this pivotal, transitional moment.</p> </div>','UEP 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8918,2021,428,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-310','<div class="desc"> <p>This seminar focuses the techniques of grassroots empowerment particularly in urban settings. This includes the following topics: developing leadership skills for citizen participation and problem solving using the media building coalitions choosing issues doing action-oriented research understanding the relations of power mobilizing constituencies developing a community oriented public policy agenda the history of community organizing in the U.S. and comparison between community development social work and direct action organizing approaches. <em>Must be taken simultaneously with UEP 311.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8919,2021,429,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-311','<div class="desc"> <p>This course provides opportunities for applying and learning through direct experience about the practice of community organization and leadership. Each student will work with a community-based organization engaged in influencing public policy for approximately 12-15 hours each week. Students will be supervised jointly by the faculty member and a staff person for the community organization. <em>Must be taken simultaneously with UEP 310.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8920,2021,1567,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-340','<div class="desc"> This course examines China''s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China''s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8921,2021,997,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-395','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>Visualizing Gentrification: Bridging Land Use Data and Ethnography</strong></p> <p>Students are challenged with the myths and realities of gentrification in an immersive discussion. The proposed course weaves urban planning, mapping and data research with qualitative analysis to recognize gentrification drivers, examine the pending experiential trauma of displacement and the community''s aspirations and resistance. The course examines the communities of Northeast Los Angeles as they face three colossal planning projects that utilize gentrification as a catalyst and justification for their development.</p> <p>In a holistic examination of the landscape, course participants will embed with community and other partners to explore the social networks and their relationship to research data. Course discussions will include developing metrics from an activist and documentary perspective to establish the observable community. Students will operate in small teams in developing data and fostering outcomes that reveal the human narrative. They can be visual in nature from ethnographic studies to data visualization, but also critical analysis and policy recommendations of the conditions on the ground. Same as SOC 395.</p> <p>CORE REQUIREMENT MET: United States Diversity (CPUD). Prerequisite: SOC 101.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8922,2021,793,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-397','<div class="desc"> <p>Tutorial and Internship for junior or senior majors in Urban and Environmental Policy and other related disciplines under arrangement with faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8923,2021,430,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-410','<div class="desc"> <p>Intensive study of the making of national and local public policy in the U.S. including the political environment in which policy debates take place. Extensive use will be made of case studies on a variety of domestic and international issues. Students will participate in the development of a major research project related to their senior comprehensive project on an individual or group basis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8924,2021,794,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-411','<div class="desc"> <p>Seminar to organize and complete a senior project demonstrating competence in applied public policy. The form and format of each student''s project will vary. All students will make a presentation of their project and will critique each other''s project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8926,2021,1431,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/100/wrd-135','<div class="desc"> <p>WRD 135 – Occidental Weekly Practicum (1 unit) The Occidental Weekly practicum is for those who want to become section editors at the Occidental Weekly or simply want a further understanding of how daily journalism works. We will learn about ethics, management, editing and planning functions; we will not specifically study writing. Class assignments include three sets of story pitches and two news memos. The goal is for you to be ready to walk into a newsroom with an understanding of the language, disciplines, and best standards and practices. We will have occasional guest speakers on nuts-and-bolts topics, such as the use of language and the difference between news presentation in digital and in print. This is a graded course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8928,2021,1140,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-201','<div class="desc"> <p>This course provides students with opportunities to develop and practice the skills and habits that are foundational to academic writing and with knowledge of how to adapt these skills and habits for the varied writing demands students will encounter in college. This course fulfills (when passed with a grade of "C" or better) the college''s First Stage Writing Proficiency Requirement (and in some cases, the Second Stage Writing Proficiency Requirement), and it is also appropriate for students in various disciplines seeking to develop their writing, argument, analytic, and communication skills. All sections of this course focus on developing complex writing, analytical, and research skills for various audiences, disciplines, and genres. May be repeated to fulfill both the First and Second Stage Writing Requirements.</p> <p><strong>Writing, Rhetoric, and Formal Poetry</strong></p> <p>This section will focus on the relationship between poetry and rhetoric--more specifically, how form shapes understanding and is used to construct different types of rhetorical argument. We will study a variety of texts including poems, critical essays, biography, and literary and rhetorical theory.</p> <p><br/> </p> <p><strong>Writing and the Rhetoric of Independent Film</strong></p> <p>This section will explore American independent film as an important art movement and alternative to traditional Hollywood filmmaking. We will study a select group of mostly recent works (2006-present) including those by the most noteworthy "mumblecore" writers/directors. </p> <p><br/> </p> <p><strong>Writing, Gender, and Sexuality</strong></p> <p>This section will explore gender and sexuality in our contemporary American context. Drawing on readings from pop culture, critical theory, current events, and literature, we will examine how gender and sexuality are constructed, theorized, and represented, and how they intersect with other areas of identity including race and class.</p> <p><strong>Wanderlust Writing and Rhetoric</strong><br/> This section will explore the writing and rhetoric of wandering and adventure, from premodern adventure stories to the present-day #wanderlust as a synonym for free-spiritedness and Instagram humblebrags; our texts will be drawn primarily from literature, pop culture, and critical theory.</p> <p><br/> </p> <p><strong>Protest Writing and Rhetoric</strong></p> <p>This section will examine the rhetoric, ideology, and context of protest genres, including social movements, speeches, literature, and visual texts, as we consider how writers, artists, and activists protest issues relating to race- and class-based oppression, gender inequity, ableism, colonialism, homophobia and heterosexism, and other concerns.</p> <p><br/> </p> <p><strong>Writing on Travel</strong></p> <p>This section will examine travelers'' tales ranging from pilgrimages, the Grand Tour, island vacations, luxury cruises, and scientific expeditions, analyzing them from anthropological and post-modern critical perspectives, all while exploring images and texts from the 1700''s to the present.</p> </div>','Not open to first-year students ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8929,2021,2534,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-215','<div class="desc"> <p>This seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8930,2021,1635,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-235','<div class="desc"> <p>Visual Rhetoric: Communication through Pictures and/or Words. This course will examine the forms and uses of visual images to inform argue and inspire--in order to analyze their effectiveness expressing ideas across the millennia from ancient civilizations through the present digital age. We will examine codices illuminated manuscripts stained glass panels and maps; combinations of words and pictures from scientists poets printers and graphic novelists; as well as digital images such as memes information graphics data visualizations and multimedia arguments. Both the theory of visual rhetoric and the making of images in some of these media will complement our exploration of these genres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8931,2021,2569,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-245','<div class="desc"> <p>This course focuses on the rhetoric of Black protest and social movements as we examine Black rhetorics as modes of resistance to racist, colonialist, patriarchal, and other forms of oppressive discourse and action. We will consider a range of rhetorical forms including abolitionist rhetoric and the Black Jeremiad in American culture; Civil Rights era rhetorics and the Black Panther Movement; anti-imperialist Black proletariat rhetorics of protest in the West Indies and Caribbean societies; and rhetorics of resistance in the contemporary Black Lives Matter movement. This course will provide a rhetorical understanding of the approaches and strategies emerging from and responding to systems of cultural and social oppression, and thus will offer a counterpoint to Eurocentric rhetorical traditions. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8932,2021,1359,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-250','<div class="desc"> <p>Writing in the Community may take many forms. Specific topics will vary. Students may repeat once for credit if taken as different topics. Current topics listed below:</p> <p><strong>WRITING AND THE LOS ANGELES EXPERIENCE</strong></p> <p>A combination writing workshop and community-based learning course, Writing and the Los Angeles Experience examines how Los Angeles shapes and is shaped by those who write about the city. Readings, class discussions, and writing assignments will engage the work of local writers whose work revolves around the city—such as Paul Beatty, Francesca Lia Block, Luis Rodriguez, and Brando Skyhorse—and the parts of Los Angeles that are central to their experience. Guest speakers and field trips to visit different areas of the city and attend live events will help us explore the way the city influences those who write about it, and the cultural, social, and political forces that make it tick. The work of this course is both critical and creative: students will write about our readings using conventional tools of academic writing and rhetoric, and respond to their own experiences of the city in reflections, stories, or other creative projects. Core Requirement Met: US Diversity and Fine Arts.</p> <p><strong>PROFESSIONAL WRITING ON SOCIAL ISSUES</strong></p> <p>This course encourages an engaged and dynamic approach to writing studies as it places writing in real-world contexts by partnering Oxy students with nonprofit community organizations in greater Los Angeles. Through these partnerships, students will identify local cultural and social concerns on topics such as homelessness/housing insecurity, poverty, immigration, education, and social activism, which represent the interests of our particular community groups. In this class we will explore a wide range of research and writing strategies common to both academic environments and the professional situations of our community partners, including primary or field research and both individual and collaborative writing projects in professional genres. This course will allow students to see community nonprofit organizations -- plus the cultural social and political issues and rhetoric surrounding them -- from the inside out. The work of this class is thus both scholarly and practical, motivating student learning by enlivening and enriching students'' approaches to writing studies. Core Requirement Met: Global Connections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8933,2021,1636,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and criticism as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations power knowledge and identities are constituted through private and public rhetorical acts. Through our readings we will engage a wide range of contributions to a rhetorical critical history by women who either as practitioners or theorists advanced their visions of social change and acted to implement them. Course readings will begin in antiquity to provide a foundation for our study though much of our material will focus on texts from the nineteenth-century to the present to examine the intersections of gender and rhetoric. Through this work we will challenge the seeming erasure of women from this critical history and interrogate the notion of "feminist rhetoric" as merely a corollary to a masculinist tradition. Assignments will include critical essays and a visual rhetoric project on representations of women in the media and popular culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8934,2021,1141,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-285','<div class="desc"> <p>This course is an intensive introduction to the theories and practices of a trade that is protected by the 1st Amendment of the U.S. Constitution, essential to democracy, and yet increasingly under threat. Taught by a Pulitzer Prize-winning report, editor, columnist, and author who bolsters his teaching with distinguished guest speakers, this class introduces students to the core values and nuts-and-bolts skills demanding by the rapidly changing field of journalism, while teaching critical thinking skills that are key to global citizenship. Students will learn to research, report, interview, and then write with rhetorical force in the concise, clear newswriting style that remains the foundation of journalism in its myriad, multi-media forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8935,2021,1361,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-286','<div class="desc"> <p>In this course students will learn to combine the reporter''s craft with creative writing skills to produce compelling nonfiction. The class teaches students how accurate, factual stories can more fully convey insight into contemporary issues and the human condition by tapping the power of fictional techniques such as character development, use of dramatic tension, dialogue, and narrative structure. The course develops students'' research, reporting, and interviewing techniques, while focusing on the craft of writing. Using the spectrum of rhetorical devices, students will strive to create well-told stories about who we are, how we live, and the forces that shape our existence. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8936,2021,1432,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-287','<div class="desc"> <p>The 21st century has seen an abrupt escalation of government, corporate, and nonprofit institutions'' use of technology-sharpened rhetorical tools to disseminate information and, increasingly, disinformation to individuals and the public. Journalism, one of democracy''s most important forces for distinguishing truth from propaganda, has simultaneously been decimated by technological and economic change. This course offers an insider''s perspective on the theory and practice of rhetorical persuasion. This course will examine the forces that shape public opinion about recent history''s most significant issues, including climate disruption, education, immigration, and war. Students will learn to write and critique editorials, op-eds, blog posts, and strategic communications'' plans driven by social media messaging, while scrutinizing the shared interests and deep tensions between journalism and public relations, publicity and marketing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8937,2021,1142,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/200/wrd-295','<div class="desc"> <p>This class will engage the historical theoretical and cultural dimensions of rhetoric in a range of disciplines in the arts literature politics and philosophy. In readings from Aristotle to poststructuralist theory we will examine all aspects of the rhetorical situation (exigence audience and rhetor) and the contexts in which rhetorical acts occur. We will examine how language practices intersect with culture and identity including class race sexuality gender and nation as we consider how arguments are constructed and how writing and narrative transform culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8939,2021,1362,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-301','<div class="desc"> <p>This advanced composition workshop explores creative nonfiction, a term that encompasses many genres, including memoir, profile writing, personal essay, humor, nature and travel writing, criticism, and narrative journalism, among others. This course will focus on 3-4 genres of creative nonfiction over the course of the semester. Each unit will pair a writing assignment in a particular genre with popular readings from that genre, by authors such as Paula Gunn Allen, Truman Capote, Ta-Nehisi Coates, Junot Díaz, Joan Didion, Audre Lorde, Adrienne Rich, Zadie Smith, and David Foster Wallace. The course will encourage experimentation while also paying close attention to audience, genre conventions, and other principles of successful writing. The workshop format relies on extensive peer review and revision, and each student will produce a capstone piece at the end of the semester after revision based on peer and instructor feedback. Prerequisite: student must have passed the first-year writing requirement and/or WRD 201.</p> </div>','Student must have passed the Core Writing Requirement or taken WRD 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8940,2021,1143,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-395','<div class="desc"> <p>An exploration of the theory and practice of writing instruction, this class emphasizes rhetorical strategies, audience expectations, and forms of academic discourse. This course also provides new advisers with an introduction to tutoring practices and strategies through Writing Center scholarship. Permission of instructor required.<em>This class is only for Peer Writing Advisers working in Writing Center. </em><em>May be repeated once for credit. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8941,2021,1637,'https://oxy.smartcatalogiq.com/en/2020-2021/catalog/course-descriptions/wrd-writing-rhetoric/300/wrd-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8943,2025,1498,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/100/amst-101','<div class="desc"> <p>This course introduces the major topics and perspectives of the interdisciplinary field of American Studies. Students will explore the diversity of United States culture, critically, in: its official and unofficial histories, its self-representations in the arts, its complicated intersections of ideals and realities. The class is required for American Studies majors and minors, and recommended for anyone wanting to better understand the relations between culture and identity in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8944,2025,3225,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/100/amst-130','<div class="desc"> <p>This course provides an introduction to American Studies through a critical engagement with theories and cultural histories of “debility” and “capacity” in the U.S.’s mythos of “exceptionalism.” We will discover how various cultural iterations of “disability” have intersected with social constructions of race, gender, class, and sexuality in the U.S., from the colonial period to the present. In doing so, we will ask/trace/analyze how specific national renderings of disability/different-abledness came to be constituted as an affirmative identity category. We will examine how disability activism joined other 1960/70s freedom movements to yield recent academic critical-theory formations in the U.S., including Dis/ability Studies, DisCrit (Dis/ability Critical Race Studies), and Crip/Queer Critique.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8948,2025,432,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/100/amst-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8949,2025,2731,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8950,2025,2670,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8951,2025,1433,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-215','<div class="desc"> <p>This course examines the history of sexuality in America from the early colonial era to the present. Along with theoretical readings, the course will consider primary and secondary sources addressing issues including: reproductive politics, socio-sexual control of Native populations, the rise of urban erotic subcultures, the sexual politics of slavery, American sexology, sex work, gender in private and public spheres, sex panics, feminism and gay liberation, and intersectional erotic cultural production.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8952,2025,2926,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-220','<div class="desc"> <p>This course introduces students to the theoretical and analytical frameworks necessary to critically understand representations of race, gender, and sexuality (among other topics in American culture) in contemporary American film and media. Using critical theory, historical analyses, and theories of analyzing film and media, we will explore central concepts in American studies such as race, gender, sexuality, class, family and nation, and private and public space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8954,2025,3275,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-242','<div class="desc"> <p>This interdisciplinary course examines the migration of six million African Americans who left the rural South to move to cities in the North, Midwest and West in the first half of the twentieth century. Beginning with the “First Great Migration” of 1910-1930 and continuing through the “Second Great Migration” of the 1940s through the 1960s, we will explore the ways that this unprecedented demographic shift laid the groundwork for the civil rights movement, the quest for Black power, and the ongoing quest for social justice. Throughout the course, we will remain attentive to the way that Black migrants created and nurtured the new forms of music, art, and ways of being that ultimately transformed American culture. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of Black Americans and the culture and politics of the United States. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8955,2025,1638,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8956,2025,1679,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-260','<div class="desc"> <p></p><p>This course will explore how Latinos have creatively represented their individual and collective experience in the United States. Literature will be the primary creative medium we look at, but some supplemental attention may be given to film and music. To reflect the variety and complexity of the U.S. Latino experience we will look at representative work from the Chicano (Mexican American), Puerto Rican, Dominican, Cuban, and Salvadoran or Guatemalan communities.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8957,2025,2819,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and theory as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations, power, knowledge, and identities are constituted through private and public rhetorical acts, mainly in the nineteenth-century to the present.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8958,2025,1680,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8959,2025,2,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-270','<div class="desc"> <p>This course analyzes the social experience and cultural heritage of Asian Americans through their writing, and places them in a broader comparative context of multi-racial/ethnic American society. We will examine the development of Asian American literature, its social implications and historical context, and the diversity of subject matter that the literary scene of Asian American communities has consisted of since the mid-19th century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8960,2025,434,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8961,2025,806,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-280','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8963,2025,4,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/200/amst-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Transpacific Empire and Anticolonial Solidarities</strong></p> <p>This course examines how U.S. imperialism, militarism, and racial capitalism have shaped our vision of the Pacific. We will explore the intersection of Indigenous sovereignty and environmental justice in the context of Hawai‘i, Guåhan, and other Pacific Islands that continue to negotiate the slow and structural violence of U.S. empire—colonized landscapes, polluted waters, and militarized airspace. By reading case studies alongside critical theory, we will situate the transpacific—a term that speaks to the conflict and exchange of Asian, Pacific Island, and American cultures across the region—as both an imperial fantasy of resource development and a contact zone for potential coalition-building. And, in following these currents, we will “unsettle” the union of Asian Americans and Pacific Islanders under the umbrella term “AAPI.” Core Fulfilled: Regional Focus</p> <p><strong>Settler and Native Ecologies of Power in North America</strong></p> <p>This course examines how settler colonial dis/possession, resource extraction, and spatial domination have generated ecological catastrophes in North America while at the same time shaping discourses of environmental protection and preservation. Reading the work of historians, anthropologists, critical theorists, knowledge-keepers, and activists, and examining sites such as national parks and infrastructure projects from the 19th century to the present, we will learn how efforts to define, manage, regulate, and exploit natural resources occur simultaneously with assaults on Native nations'' sovereignty. We will explore how Indigenous peoples have cared for and defended their lands and human and nonhuman relatives despite continuous settler state violence and violations. We bring these discussions to current environmental issues in California, such as wildfire management and tribal nations'' salmon restoration efforts. </p> <p><strong>Latino/a Experience</strong></p> <p>This course will explore the history and experience of Latino/a immigrants in the United States, paying particular attention to how race, ethnicity, identity, politics, class, and gender influence the lives of Latino/a immigrants. We will also examine how they have influenced historical developments in different regions of the country, especially in terms of U.S. demographics. </p> <p><strong>Black Literary History and the Archive </strong></p> <p>How do we resurrect the lives of people who were considered unimportant, those whose contributions were dismissed and buried? What does the existing historical archive tell us about what is considered valuable and about what constitutes "memory"? This class examines the lives of two of the most important 19-century Black women writers, Harriet Jacobs and Harriet Wilson, as a means to develop the tools of literary recovery. As we expand the contours of the historical canon, we will also reflect on our own sense of the scope and shape of African American historical memory and the ways in which we organize history. How do we interpret religion, resistance, and labor activities that that fall "outside" of the most recognized narratives about African American experience? This class will take on these larger questions as we also engage in archival work in newspapers, census records, and beyond. </p> <p><strong>African American Literature: Race/Gender/Sexuality </strong></p> <p>This course is designed as a survey of African American literature. We will examine a multitude of genres, including: oral forms (spirituals, ballads, work songs), poetry, fiction, drama, and essays by authors such as: Phillis Wheatley, David Walker, Sojourner Truth, Frederick Douglass, Booker T. Washington, Ida B. Wells, W.E.B. DuBois, Langston Hughes, Nella Larson, Zora Neale Hurston, Jean Toomer, Jessie R. Faucet, Claude McKay, Richard Wright, Ralph Ellison, James Baldwin, Ann Petry, and Gwendolyn Brooks. Beyond strictly a "greatest hits" or "major authors" course, this class will also consider the ways African American writers interrogate complex categories of personal identity, which requires an in-depth investigation into the intersections of race, gender, sexuality, and socioeconomic class. Through lectures, class discussions, and student presentations, we will highlight the critical impact of African American literature on American culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8965,2025,3883,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-305','<div class="desc"> <p>This course examines forms of unfreedom from the American colonial era to the present and traces connections and divergences between early and contemporary abolitionism in the U.S. Through literature, film and media, and critical theory, we will investigate the ambition of racial, gender, and other forms of justice and abolition democracy. The main premise of this course is that abolition encompasses long and varied processes that continue to occur in the U.S. With this guiding premise, we consider abolition in the context of policing, of the prison, and of punishment more broadly.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8966,2025,1500,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-320','<div class="desc"> <p>This course will study the 20th century evolution of word-and-image texts from their origins in early superhero comics to their contemporary emergence as recognized literary works. The texts will be primarily from the United States, but some attention will be given to foreign works in translation. Frosh may not enroll in this course except by instructor permission.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8967,2025,3308,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-329','<div class="desc"> <p>Black queer thought are the knowledges, embodied and otherwise, that both enact critique of and imagine possibilities against the demands of heteronormativity, white supremacy, patriarchy and capitalism. In this course, we will engage with the multiple forms of text produced by those who may – or may uncomfortably – identify as Black and queer. By doing so, we will explore how the cultural producers in question complicate and elaborate upon the sometimes static and often U.S.-centered definitions we hold for “Black” and “queer,” challenging us to instead conceptualize these as dynamic and shifting positions rather than stable identity categories. Texts will be drawn from the works of James Baldwin, Ashon Crawley, Jackie Kay, Kara Keeling and others. This class thus situates students to join in on ongoing critical conversations within Black Studies, Queer of Color Critique, Performance Studies and American Studies. Assignments will include both informal and formal written components, and students will be asked to produce a final research paper. This class fulfills the second-stage writing requirement for the Black Studies major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8968,2025,3017,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-332','<div class="desc"> <p>Sigmund Freud''s intervention in personal sexual life often overshadows how psychoanalysis uniquely theorized violence in the context of two world wars. This course will consider how historical and contemporary violence in the U.S. might be informed by psychoanalytic concepts, including: aggressivity, group identification, neighbor relations, the death drive, and altruism. Readings include Freud’s work and texts by contemporary theorists grappling with the ongoing problems of war, racism, class conflict, and sexual violence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8969,2025,3295,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-333','<div class="desc"> <p>This course introduces students to literary questions of queerness, canonization, and nation, in the context of the United States'' 20th century discourses about homosexuality. Students will analyze the production of ideas about the nation through literature and examine the limits and capacities of the novel genre for cultural expressions of LGBTQ life in America. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8970,2025,2927,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-335','<div class="desc"> <p>This course examines the emergent field of queer of color critique. Combining woman of color feminism with queer theory, queer of color critique analyzes intersections of race, gender, sexuality, and class through interdisciplinary methodologies. This course will examine themes of settler colonialism, interracial love, gender performance, anti-blackness, orientalism, and bilingual resistance through critical theory, literature, film, and television</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8971,2025,3246,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-337','<div class="desc"> <p>The course takes an interdisciplinary approach to the last decade’s increasing attention to Los Angeles as a historical origin point of United States’ LGBTQ+ history. Students are encouraged to “queer” the very concept of the archive by considering how minority voices and experiences register themselves across time through both traditional archives and less formal communities of readership and historiography wrought through alternative archives like pulp novels, comics, films, and even gossip. The class will spend time with primary sources in the ONE National Gay and Lesbian Archives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8972,2025,2608,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-376','<div class="desc"> <p>This interdisciplinary seminar will explore the contentious history of the public memory and representation of slavery, the Old South, and emancipation in the United States. Drawing upon a range of sources – including fiction, film, advertisements, tourist sites, and public monuments – we will examine the various ways that Americans have sought to commemorate, critique, and capitalize on the history of the nation’s “peculiar institution” from the late-nineteenth century to the present day. Throughout the semester, we will interrogate the contested politics of these popular representations, and we will assess the ways that African American writers, filmmakers, preservationists, and artists have sought to challenge and reframe longstanding Jim Crow-era representations of slavery, replacing them with new narratives informed both by historiographical paradigm shifts and the politics of the ongoing black freedom struggle. </p> </div>','One HIST course, or one BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8973,2025,435,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-390','<div class="desc"> <p>This course engages students in the history, practice, and research methods in American Studies by focusing on the significance of place, identity, and rights.While we will focus on the territory known as the United States, our readings and research will trouble the security of that designation. By examining the origins of settler colonialism in the Americas, focusing upon national borders and internal boundaries, and exploring the United States'' global reach, we will study and develop different ways of understanding "America" as a product of civic rights that are extended and denied. Students will apply American Studies theoretical methods in a research project of their choosing, and majors will develop this work into their senior comprehensives project. Offered only in spring semester. Majors are encouraged to study abroad in the fall semester to align this requirement with their progress toward the major. </p> </div>','AMST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8976,2025,436,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/300/amst-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8977,2025,437,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/400/amst-490','<div class="desc"> <p>This course is designed to assist students with the completion of research papers on topics that reflect selected areas of emphasis in American Studies. It will provide an opportunity for seniors to synthesize their area of specialization with an analysis of critical issues in the study of American culture and society. Offered only in fall semester (following AMST 390 in the spring). </p> </div>','AMST 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8979,2025,438,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/amst-american-studies/400/amst-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8980,2025,5,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/100/arab-101','<div class="desc"> <p>Introduction to Modern Standard Arabic and pronunciation, alphabet, simple oral communication, reading simple prose, and other basic language skills. Instruction in the fundamentals of Arabic grammar. May not be taken for credit by those with more than one year of previous high school study (grades 10, 11, 12) in Arabic or one semester of college study in Arabic. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8981,2025,440,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/100/arab-102','<div class="desc"> <p>Continuation of ARAB 101.</p> </div>','ARAB 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8982,2025,1501,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/100/arab-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8983,2025,1682,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/100/arab-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on a Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8987,2025,6,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/200/arab-201','<div class="desc"> <p>This course focuses on the development of communicative skills via reading, speaking, listening, and writing activities, while grammatical points are drilled intensively. Students begin to read and discuss cultural and literary texts, as well as simple media materials.</p> </div>','ARAB 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8988,2025,888,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/200/arab-202','<div class="desc"> <p>Continuation of ARAB 201.</p> </div>','ARAB 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8989,2025,1145,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/200/arab-275','<div class="desc"> <p>A selection of literary works and films from the Arab world will be analyzed in the context of historical, cultural, social, and political developments from the last decades of the 20th century. The texts, in various genres - short story, novel, memoir, poetry - will highlight the heterogeneity and complexity of Arab countries, such as: Morocco, Tunisia, Egypt, Lebanon, Iraq, and Saudi Arabia. Some of the main themes that we will cover include: tradition versus religion, challenges of modernity, gender relations, social (im)mobility, and generational gap. The course will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8993,2025,807,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/300/arab-301','<div class="desc"> An advanced Arabic course intended for students who have taken Intermediate II. It introduces the language of the newspapers, magazines, and internet news sites. Students will gain access to different sources from the Arab world. </div>','ARAB 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8994,2025,1043,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/300/arab-302','<div class="desc"> <p>This is a continuation of Arabic in the Media I.</p> </div>','ARAB 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(8997,2025,441,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arab-arabic/300/arab-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(8999,2025,1640,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/100/arth-150','<div class="desc"> This introductory course examines how cities, suburbs, and metropolitan areas are designed and developed. We will explore historical episodes and actors that have influenced urban planning so that we may then consider the ways in which contemporary architects, developers, and institutions approach urban concerns related to land development, the environment, housing, and transportation. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9000,2025,7,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/100/arth-160','<div class="desc"> <p>This course introduces East Asian art from ancient times to the present. Although the framework of the course is loosely chronological, each week will focus on in-depth analysis of a different type of object that addresses a particular problem or concept. We will explore topics such as metaphorical uses of amorphous ink in calligraphy and painting, the deconstruction of artistic hierarchies in the tea ceremony, and gender and the politics of contemporary performance art. In addition to developing the foundational skills of close looking, critical thinking, and self-reflective writing, students will ultimately gain an understanding of the diversity, complexity, and conceptual excitement of East Asian art. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9001,2025,8,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/100/arth-170','<div class="desc"> <p>What makes art “European”? This fundamental question accompanies our survey of the different artistic traditions that emerged around the Mediterranean for more than 40,000 years of history, from prehistoric times through antiquity to the end of the medieval era. Rather than looking at art as the product of different monolithic “civilizations,” progressing through time in isolation from another, we will consider how a diversity of artistic cultures emerged through constant exchange and borrowing from one another. Readings, lectures, assignments and discussion will encompass artworks from the realm of painting, sculpture, architecture and material culture from a “Europe” with constantly fluid and shifting borders. The course will develop skills of visual analysis in style, iconography and technique. Issues of gender, race, colonization and trade in the art of the ancient and medieval eras will also be addressed. In addition, we will explore how the art of the past has constantly been reimagined to fulfill more recent artistic and political ideologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9002,2025,9,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/100/arth-180','<div class="desc"> <p>The term “Modernism” has traditionally referred to certain developments in so-called Western art from roughly the late 19th century to the 1960s. Through readings, lectures, discussions and writing assignments, this course will pose the question of whether the concept of Modernism can be used to understand cultural practices from other parts of the world as well. Or does the consideration of art from all six inhabited continents over this period render the concept of Modernism inoperable? What commonalities and differences can we discern between art made in vastly different contexts in response to the experiences of colonialism, industrialization, urbanization, nationalism, and revolution? What sorts of continuities, tensions, or ruptures have arisen between indigenous traditions and metropolitan practices? Finally, how has a globalized contemporary art world arisen out of numerous local ones? To answer these questions, and others, students will be introduced to the fundamental art historical practices of visual description and visual analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9006,2025,2860,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-200','<div class="desc"> <p>This course provides opportunities for students to engage in community-based work with arts organizations. Each student will work with a community-based partner or artist for approximately 6-7 hours each week. This in-the-field experience will be paired with reflective exercises and relevant readings, and will be facilitated by a faculty member in the department.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9007,2025,3242,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-201','<div class="desc"> <p>This course will enable students to learn the methods of visual and cultural analysis, critical practices of looking, varied modes of making, and the historical and theoretical frameworks that form the foundation for deeper study of visual arts, architecture, and material culture. Guest lectures from faculty in the studio art and art history program will enhance the interdisciplinary and transcultural nature of the course, and student work will include opportunities to conduct research, write about, and create visual images and objects as a means putting these foundational concepts into practice. Classes will focus on the analysis of specific objects (paintings, photographs, prints, sculptures, buildings, and other objects of visual interest) and also the materials and techniques used to make those images and objects. By the end of this course, students will be equipped with the methods of analysis, research, and interpretation essential to looking at and making visual art in the twenty-first century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9008,2025,3247,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-240','<div class="desc"> <p>Trade, economic migration, and violent displacement caused an unprecedented number of people and things to travel across the early modern globe. This seminar explores the portable objects that were created within, and impacted by, the global mercantilismes and colonialism’s of the Spanish and Portuguese empires. We will follow a series of moving items that defy the traditional categories of singular authors or cultures. Their travels span distant points in the colonial maritime world, such as Goa, Manila, Mexico City, Nagasaki, Antwerp, Lisbon, and Potosi. Each class will center around 1-2 select “Objects in Focus.” Ranging from the high-end to the everyday, these works will include ivories, feather mosaics, silver work, lacquer, ceramics, paintings, prints, textiles, and more. They will intersect with a series of discussions on appropriation, reuse, display intent, theft, copying, gifting, erasure, fashion, labor and race. The paths of things past offer a more nuanced view of our own current systems of globalized capitalism and its reflection in artistic production and display to this day.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9010,2025,1502,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-259','<div class="desc"> <p>A thematic course on the history, theory, and practice of Modern Architecture in Europe and the United States, from the 1780''s to the later 20th century. Themes we''ll explore include the following: architectural theory and design as social planning, competing notions of public and private space, modernist architectural theory and urban development, rural and urban ideologies in American architecture, the changing image of the architect in the 19th and 20th centuries, architecture and urbanism in Southern California. Coursework will include a required half-day field trip.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9011,2025,2582,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-268','<div class="desc"> <p>This course examines the Japanese woodblock print from its emergence in the mid-seventeenth century to the modern era. We will investigate topics such as technological innovations, changing habits of looking, censorship and resistance in the creation of popular culture, the role of prints as a medium of reportage and propaganda, Japonisme and the construction of Japanese art, and global exchanges of materials and ideas. By tracing the historical development of Japanese prints, we will examine how woodblock prints were reconceptualized from a popular medium of visual culture to a quintessential embodiment of Japanese aesthetic tradition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9012,2025,2321,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-272','<div class="desc"> <p>An investigation of the art and architecture of ancient Greece and Rome from the Helladic era (c. 1500 BCE) to the appearance of Christianity in late Roman antiquity. Sculpture, metalwork, mural painting, vase painting, and architecture will be considered, with particular interest in how these forms are reflective of the fundamental political, spiritual, and philosophical developments during this era - as well as how these artistic forms serve as the foundational elements for European Art History.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9013,2025,3210,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-273','<div class="desc"> <p>Each week, the class will travel the world to discover artists from different parts of the Spanish Empire, moving across the Iberian peninsula to Flanders, Southern Italy, the Philippines, Mexico, Peru and many more sites. This course explores the arts of the Spanish Monarchy from the plurality of perspectives and voices that composed this global empire ruled by the Habsburg dynasty (1516-1700). This will mainly concentrate on the arts of painting and sculpture, two crucial cultural traditions of this period. We will explore what “painting” and “sculpture” meant in different parts of the Empire, and how it also could integrate a broad range of decorative materials like feathers, gold, shell and ivory. Themes like religious visions, portraits, and still life will all receive attention. Famous artists and objects like Velazquez’ <em>Las Meninas </em>will come into conversation with the lesser-known and even anonymous makers of indigenous, creole and African descent, which all contributed to the history of sculpture and painting under the Spanish monarchy. Representations of power and artistic identity will intersect with issues of race, gender and class that structured societies under Spanish colonial and monarchic hegemony. Ultimately, students will come away with a much broader understanding of what well-known artistic traditions like painting and sculpture can mean in a globalizing and more culturally-heterogeneous world. Visits to nearby museums will also be included.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9014,2025,1044,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-278','<div class="desc"> <p>An exploration of art, architecture, and visual culture created within the context of Muslim-majority or Muslim-ruled societies within Western Asia, North Africa, and Europe from the 7th to the 21st centuries. Covers sacred and secular architecture and architectural decoration, sculpture, painting, manuscripts, textiles, and metalwork, including objects in Los Angeles area collections. The course also considers theoretical framings of the field, such as what is “Islamic” about Islamic art. We will also consider the circulation of Islamic art globally and the emergence of modern Islamic art, as well as the visual cultures of protest in contemporary Muslim-majority countries. Readings will include primary sources, exhibition catalogs, and scholarly articles; visits to museums and a mosque is anticipated. By the end of the course, students will be able to demonstrate knowledge of the diversity of Muslim arts historically and geographically. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9015,2025,998,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-285','<div class="desc"> <p>This course will explore artistic practices in the U.S., North America, and Europe, during the long 19th century, from roughly 1789 to 1900. Lectures, discussions, and readings are designed to provide a thematically-driven, chronological overview of the period. Yet, the course will not be a traditional "survey," rather, it will focus on some of the key changes in ideas about artistic culture; art practice; and practices of regional, national, and transnational identity formation as expressed in visual art. This course will explore the role of art in social and political revolution, as well as its formative status as an engine of cultural imperialism in the 19th century, and, in addition will explore some of the more traditional approaches to studying the status of art, such as the role of the artist and the transformation of the art "market" in the wake of the industrial revolution. Key debates within the field of Art History will be explored, as well. Museum visits required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9016,2025,445,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-287','<div class="desc"> <p>Photographs today are ubiquitous. Yet they are incredibly diverse in their functions, circulation, meaning, and relationship to institutions, personal and collective identities, scientific knowledge, and artistic cultural practices. As a realist medium, photography has the potential to shape the way we think about ourselves, our communities, our national cultures, and our engagements with a transcultural world. This course is designed to explore the technological, cultural, economic and ideological power that photographs have to shape our collective understanding of the world we live in. This course will also introduce students to key tools necessary for developing visual literacy in our image-saturated culture. Together we will learn about different photographic genres - exploration and travel photography, portraiture and family photographs, medical and legal documentation, fine art prints and mass cultural forms - and we will explore photography''s power to represent personal and collective identities, social and political ideologies, and history itself. Photography, after all, was created in the early 19th century, at a time of rampant Euro-American colonialism. The course will explore photography by, for, and of makers and collectives working in and across local, indigenous, and global cultures in North and Central America, East and Southeast Asia, Africa and the African Diaspora. Readings will include primary source materials, theories of photographic meaning, and research-based analyses of particular photographic practices within both local and global contexts. Students will be asked to grasp both the medium''s technological and rhetorical functions, but also to develop their own critical perspective on photography''s shifting relations to global visual culture. Coursework will include a hands-on photography project and a museum or gallery visit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9017,2025,11,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-289','<div class="desc"> <p>This course will focus on modernist artistic practices in the United States and Europe between 1900 and 1950. We''ll look carefully at a wide range of practices, including painting, sculpture, photography, film and architecture. Coursework will include readings, discussions, and lectures about modernism, the rise of the avant-garde, and the role of exhibitions in the transformation of modern art. We will engage issues of gender, sexuality, race, class, and ethnicity, and the scholarship we read will encompass diverse approaches to analyzing and interpreting modern art.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9018,2025,889,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-290','<div class="desc"> <p>This course will explore the diverse forms of visual culture - painting, sculpture, photography, installation, performance, and interdisciplinary arts created in the years after 1950. We will investigate shifting ideas about artistic identity, the status and function of art in the wake of the social, cultural and economic changes in post-industrial society of the 1960s and 1970s. Broad cultural and social movements advocating for civil rights, feminism, environmentalism, global capital and migration in the later 20th century will form the cultural backdrop of our work. We will also consider how critical theory has impacted artistic cultures and the burgeoning networks of artistic and cultural exchange. Our work will engage directly with changing ideas about race, ethnicity, gender, sexuality, and cultural identity as they impact artistic identity and arts institutions. At least one field trip to a gallery or museum will be required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9019,2025,3248,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-292','<div class="desc"> <p>What is a "site"? As the world has become more urbanized and globally interconnected, our daily lives increasingly digitized and virtual, and social ties looser and less place-bound, our conception of a “site” as a specific physical location has been complicated. This course examines the various ways artists have examined the meaning of a “site” and an artwork’s relationship to it. Emerging from developments within sculpture in American art of the 1960s, the notion of “site-specific art” has been adapted in various ways by artists around the world over the past several decades. We will focus on such works and theories that address issues including colonialism, gentrification, community, public art, monuments, digital media, globalization, environmentalism, surveillance, and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9021,2025,1319,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-295','<div class="desc"> <div><div><div><strong>Art &amp; Money</strong></div><div><span>Artâs relationship to money has long been fraught. On the one hand, art supposedly places individual expression above the profit motive, yet on the other hand, artworks circulate as expensive luxury commodities. How can artworks be unique, non-fungible cultural objects yet also vehicles for collateralized debt, money laundering, tax evasion, speculative investment, and real estate development? Has art simply become money? Can money be art? This course examines these, and other contradictions, about the long and complicated entanglement of art and money in modernity with particular attention on the period since the 1960s. We will address theories of value, trace the history of the art market, interrogate the politics of arts funding, explore the so-called financialization of art, look at ways artists have represented, exploited, or challenged the connections between art and money, and consider artâs role within the broader economic system. </span></div><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9022,2025,3829,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-296','<div class="desc"> <p><strong>Topic for Fall 2024: Subversive Art and Media.</strong></p> <p>An 8-unit course on the ways visual artists challenge and critique dominant systems of power, and catalyze movements of social change . We will explore how photography, film, visual and media arts play powerful roles in shaping liberatory and empowering narratives in the present, as well as reimagining, reconstructing, and reclaiming histories of the past. Through readings, discussions, writing, and art practice, students will center questions of power, belonging, exclusion, visibility and invisibility among others. Students will also engage in collaborative projects and studio visits with artists, filmmakers, curators, historians, and media makers in LA/the US, South/Southeast Asia, Mexico, and Europe. Finally, students will create a final visual media social justice project. By the end of the immersive, students will have gained critical skills in discussion, research, and writing alongside creative skills in visual media making. This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,'First-Year Seminar: FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(9024,2025,3014,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/200/arth-298','<div class="desc"> <p>This course actively engages students in the diverse array of programming - exhibitions, lectures, studio visits, student and community-based projects - that are fundamental to the history, theory and practice of the visual arts on campus at Oxy Arts, and in the city of Los Angeles. Students will meet regularly with the course faculty mentor to discuss related readings and their experiences of these arts activities; students will also have the opportunity to respond creatively to programming and events through writing, image-making, and collaborative projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9025,2025,3249,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-330','<div class="desc"> <p>Some say that the word “Baroque” derives from a Portuguese term denoting a misshapen pearl: a treasure that is asymmetrical, beautiful, and enchantingly strange. The Baroque style that prevailed in the European empires during the seventeenth and eighteenth centuries fostered an aesthetic of irregular forms, highly emotional and dramatic effects, and stark contrasts of light and dark. The troubled painter Caravaggio, the Mexican nun-poetess and mystic Sor Juana Ines de la Cruz, and the German Jesuit polymath Athananasius Kircher all encapsulate this crucial cultural moment. This course will examine the arts of the Baroque period from a global perspective: each week we will travel to different locations around the world to examine its shifting contours. From Mexico City to Rome, we will explore the different iterations of this distinctive style via painting, sculpture, architecture, poetry, fashion, music, optical instruments, and even stage design. These histories will lead us to examine the Baroque’s continued impact on twentieth and twenty-first century scholars, artists and filmmakers.</p> </div>','Any 100- or 200- level art history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9026,2025,2671,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-360','<div class="desc"> <p>This course explores the relationship between art and women in East Asia from ancient times to the present. We will study the various ways in which women have been engaging with art—as producers, as patrons, and as objects or subjects of the gaze. At the same time, we will examine how women and gender have been conceived and contested in East Asia. Over the course of the semester, we will investigate topics such as women artists and patrons; Buddhist conceptions of the feminine and women’s devotional practices; performing “women” in theater; shifting ideals of beauty and the alteration of women’s bodies; and the representation of gender in contemporary popular culture. Ultimately, students will develop critical tools for examining how women have been represented in visual culture and how they have exerted their own artistic agency in East Asia. </p> </div>','Any Art History course, East Asian Studies course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9027,2025,2518,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-365','<div class="desc"> <p>This course examines the role of gender in the production and reception of visual images in Japan from the twelfth through the twenty-first centuries. Closely engaging with a variety of images, literary texts, and performances, we will investigate topics such as Buddhist conceptions of the feminine, same-sex sexuality and gender reversals in the medieval imagination, beauty prints and the politics of the gaze, changing conceptions of art and women in modern Japan, masquerades of masculinity, and the place of male-male sexuality in contemporary girl culture. Ultimately, this course will provide students with an understanding of how art and gender have been conceptualized in Japan, as well as tools to think beyond that understanding.</p> </div>','Any art history course, Japanese studies course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9028,2025,3211,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-375','<div class="desc"> <p>Pilgrimage is the journey to a revered site, often accomplished for spiritual purposes. Whether it is the Catholic Way of Saint James in Santiago de Compostela in Spain to the millions of Muslims who travel each year to Mecca for the Hajj, pilgrimage speaks to widespread narratives of human movement, monumentality, and memory.</p> <p>Encompassing the medieval and early modern periods, this class will explore the art and architecture of different religious shrines throughout the Global Mediterranean world (including the Americas). We will examine pilgrimage sites as the confluences of multi-media art forms, melding architectural space and fine arts with the cultural expression of everyday people: this includes graffiti, votive arts, and other folkloric practices. Students will explore themes like migration, displacement, colonialism, and connections with contemporary parallels.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9030,2025,14,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-390','<div class="desc"> <p>A research-intensive course on a topic within the history of art; coursework will include the process of researching and writing a scholarly essay and a focus on the methodologies of art historical scholarship. Required for Art History majors to fulfill the Second-Stage Writing Proficiency requirement.</p> <p><strong>Thinking about Art </strong></p> <p>How do we study a work of art? What kinds of approaches have art historians taken when interpreting artworks? How can we make use of different theories and methods? We will seek to answer these questions as we read groundbreaking texts from the history of art history and visual culture. We will investigate approaches including formalism, social history, feminism, queer studies, critical race theory, and network theory. We will consider possible ways of applying these conceptual frameworks to interpreting media ranging from painting and sculpture to film and performance. Ultimately, students will produce a research paper on a topic of their choice that engages with some of the methods, theories, and approaches explored in the course.</p> <p><strong>Approaches to Art History and Visual Culture </strong></p> <p>How do we study a work of art? What kinds of approaches have art historians taken when interpreting artworks? How can we make use of different theories and methods? We will seek to answer these questions as we read groundbreaking texts from the history of art history and cultural studies and consider possible ways of applying their conceptual frameworks to interpreting media ranging from painting and sculpture to film and performance. We will investigate approaches including formalism, social history, thing theory, feminism, and network theory. Ultimately, students will produce a research paper on a topic of their choice that engages with some of the methods, theories, and approaches discussed in the course.</p> <p><strong>Performance, Embodiment and the Dematerialization of Contemporary Art</strong></p> <p>When many people think of âArtâ they envision a painting, a sculpture, a photograph, a lithograph or woodcut, or even an artistâs handmade book. Yet in the later years of the 20<sup>th</sup> century, artists drew on the disruptive works of the historical avant-gardes like Dada and Surrealism, as well as new ideas about the artistâs place in the world, to create work that looked and behaved very differently than traditional media. In the years after 1960, artists questioned the definition of art (is it a thing or is it an action or an event?). In turn, artists grew invested in making work that disrupted the more traditionally passive relationship between viewer and work; instead, the spatial, temporal and cultural contexts of art works became part of the work itself. Coupled with the desire by many artists to displace art from the traditional confines of the commercial gallery system, as well as to call into question the realities of individual and collective embodiment and identities, the effect of these new approaches was to expand the definitions of art to include performance, body art, installation, and institutional critique. Thus, artists transformed, and often dematerialized the âwork of artâ in favor of an art that could provoke action, communication, collaboration, and cultural critique. This seminar will enable us to explore these new modes of artistic practice in North America and Europe through provocative art historical and theoretical readings; student research projects; and activities and exhibitions at Oxy Arts and across Los Angeles.</p> <p><strong>Building the âAmerican Pacificâ</strong></p> <p>This course examines modern and contemporary architecture of the âAmerican Pacific.â Students will investigate the historical, social, cultural, political, climactic, and technological factors that have influenced the development of architecture in Hawaiâi, American SÄmoa, and Guam. Theoretical examinations about U.S. empire, race, and sovereignty allow us to challenge the very notion of an âAmerican Pacificâ and frame our study of architecture as a complex interplay of evolving beliefs and meanings. An examination of Pacific Island spaces/places and their relationship to artistic endeavors by artists and architects reveal the ways in which indigenous and foreign identities influence the built environment. Students will engage with interdisciplinary and intersectional scholarship as we consider the architectural legacy of American expansion in the Pacific. Additional Core Requirement Met: Regional Focus.</p> <p><strong>Colonial Urbanism </strong></p> <p>In this course, we will examine the spatial legacy of colonial cities. The focus is on colonial urban spaces and architectural projects that were manifestations of the political, economic, and social relationships between the colonizers and the colonized. In relation, the role of imperialism - as it transpired in both the colonies and colonizing societies of Europe and the United States - will reveal the ways in which the imperial imagination was visible in physical form. Through a range of case studies, including sites in former European and American colonies of Asia and the Pacific, as well as former imperial centers, such as London and Washington D.C., students will develop a theoretical toolkit for the critical study of urban colonial environments.</p> <p><strong>Gender and Sexuality in 20th Century Art</strong></p> <p>This seminar will explore the how issues of gender and sexuality have shaped the practices of visual artists in the US and Europe in the 20th century. We will investigate how artists have engaged directly with these issues in their art, and we will also consider how the field of Art History itself has been impacted by practices and stereotypes about gender and sexuality. Additional Core Requirement Met: Global Connections.</p> </div>','Any 100- or 200-level Art History course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9031,2025,1202,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-391','<div class="desc"> <div><div><p>A seminar focusing on a topic in the history of art taught by a practicing curator at a Los Angeles cultural institution. Course topic(s) change annually and will include off-campus hands-on work within the context of curatorial and exhibition practices. Course may be repeated for credit with a different topic.</p><p><br/></p><div><strong>Contemporary Art Museums: Learning, Engagement, Artists, Community (4 units)</strong><br/><div>What is the role of the art museum in the 21st century? How does it sustain its relevance in an increasingly complex world of information and stimuli? This class provides theoretical insights and practical knowledge about public programming, special projects with artists, and informal learning practices in contemporary art museums on local, national, and international levels. The course will be taught by Asuka Hisa, Director of Learning and Engagement at the Institute of Contemporary Art, Los Angeles (ICA LA), and currently a 2023-2024 Smithsonian Fellow in Museum Practice. The course begins with an overview of the museum fieldâexamining interpretive methods of teaching with artworks and in partnership with artistsâand continues with an analysis of the evolving nature of the field and its growing inclusion of multi-disciplinary curatorial approaches. The class explores how greater societal contexts influence and inform programming work through an investigation of case studies, experimental and conceptual projects, and expansions in museum theory. Discussions center on the social practice role of the contemporary art museum today. The class provides readings, hands-on exercises, and assignments to develop skills associated with inclusive project design.</div></div><p><br/></p><p><strong>Introduction to Curatorial Practice (4 units)</strong></p><p>This seminar explores the conceptual and practical aspects of making exhibitions. Students will investigate curatorial strategies through readings, class discussions, and trips to local galleries and museums. Seminar discussions will emphasize the ethics and social impact of curatorsâ work. These concerns include accessibility, repatriation, the care and display of indigenous objects, exhibiting Blackness, power and labor dynamics.</p><p>This course uses exhibitions as case studies and examines the strategies of curators including David Driskell, Okwui Enwezor, Thelma Golden, Wanda Nanibush, and Marcia Tucker. It also investigates the structure and influence of international art fairs like Documenta, DakâArt, and the Whitney Biennial. Students will also have an opportunity to respond to the professorâs current curatorial projects.</p><p>Students will conceive an exhibition for their final project. They will compile a list of artworks, write a project description, and write select exhibition texts. By the end of the semester, students will have critically examined a variety of curatorial strategies and assessed their intended and unintended outcomes. Students will gain knowledge about the practice of conceiving and organizing exhibitions.</p><p><br/></p><p><strong>Collecting Value: Photography Archives of Los Angeles (4 units)</strong></p><p>This course examines photography collections and archives of Los Angeles. Rather than looking at a single artist, time period, or approach to the photographic medium, we will look at the dynamics of photo collections held by institutions and individuals: how they are formed, what they contain, and which histories and narratives they uphold, counter, or exceed.</p><p>Each week, the class will visit a different collection across the city, exploringvenues such as museums, libraries, galleries, and historical archives. We will also meet with contemporary artists who use and collect vernacular images in their practice. With each module, we will explore and complicate histories of the medium and set out to understand how institutions use photography collections to produce and reinforce cultural, historical, and economic value.</p><p>The class will also correspond to the organizing of a forthcoming exhibition of Chinese photography from the 1980s and 90s, recently acquired by the Hammer Museum. The course will teach methodologies of curatorial practice with a focus on archival research, material preservation, and museum writing.</p><p><br/></p><p><strong>Drawing from Life and the Imagination: 17<sup>th</sup>-century Dutch Drawings at the Getty Museum (4 units)</strong></p><p>Taught in the study room of the J. Paul Getty Museum by the Curator of Drawings at the J. Paul Getty Museum, this course examines 17<sup>th</sup>-century Dutch drawings. Using Getty drawings made by Rembrandt van Rijn and his contemporaries, this class offers students a unique opportunity to study Dutch works on paper firsthand. Classes will be structured around a thematic selection of drawings and discussion topics include natural history illustration, landscape, figure studies and portraiture, religion, and travel by land and sea. Students will gain a better understanding of various drawing media and techniques as well as obtain a detailed overview of the function of Dutch drawings from the 1600s. Students will read primary sources (in English) about art theoretical debates of the time. Particularly important is the debate about whether artists should draw from life or from their imagination. This two-pronged approach to draftsmanship accounts for the meticulously rendered, vibrant 17<sup>th</sup>-century Dutch drawings that continue to delight and provoke us today.</p><p><br/></p><p><strong>East Asian Gardens: China, Japan, Koreaâand California?</strong> <strong>(4 units)</strong></p><p>What kinds of gardens have existed in East Asia, and what sorts of functions have they fulfilled? How have they engaged with broader visions of the cosmos, and how have they expressed such understandings? What happens to such gardens when they are translated into a cultural context very different from that in which they emerged? To answer these questions, this course, taught by a curator at the Huntington Library, will take a broad view of the history of East Asian garden-making, examining images, texts, films, and gardens from the 2nd century BCE to the present. We will investigate hunting parks constructed as microcosms of empires, holey rocks that inspired dream-journeys to immortal realms, Buddhist paradises accessible in this-worldly estates, and textual fantasies of gardens of the mind. Taking advantage of the Chinese and Japanese Gardens at the Huntington, this course will also explore how such concepts have been put into practice in the physical spaces of these gardens, where the course will be held each week. Moreover, we shall trace the very different histories of these two gardens in order to gain insights into California''s shifting relationship to East Asia over the course of the twentieth and twenty-first centuries. In taking this course, students will ultimately gain an understanding of the diversity of garden forms in East Asia; familiarity with key concepts used in garden-making; practice with the skills of visual and spatial analysis, as well as cultural and historical contextualization, necessary to discuss gardens meaningfully; and experience with curatorial strategies for making East Asian gardens accessible to diverse audiences. The final project will involve developing an interpretive program for one section of the Huntingtonâs gardens. <strong>This course meets at the Huntington Library, Art Collections and Botanical Gardens</strong>. <em>Additional Core Requirement Met: Regional Focus and Pre-1800.</em></p><p><br/></p><p><br/></p></div></div> </div>','Any 100- or 200-level Art History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9033,2025,1320,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Imag(in)ing</strong><strong> War and Disaster in Modern and Contemporary Japan</strong></p> <p>This course explores how practitioners of art and visual culture have responded to physical and psychological damages that were caused by wars and disasters in modern and contemporary Japan. The course loosely follows a chronological order and a thematic framework. We will look at expansive materials, including colorful and playful woodblock prints (<em>ukiyo-</em>e) of natural disasters; prints and memorabilia of the Russo-Japanese war (1904-05); topography and the building of the Yasukuni Shrine and its exhibitions; the birth of the avant-garde and its relation to the Great Kanto Earthquake (1923); war documentary paintings and propaganda during WWII; atomic bomb photographs and memorials; reportage painting of the 1950s; anti-art and non-art movements of the expanded 1960s; <em>kawaii </em>(cuteness) and monstrosity in manga and animation; and socially engaged art about Fukushima. The course aims to enable students to analyze how politically inspired or socially engaged art developed in modern and contemporary Japan. <em>Additional Core Requirements Met: Regional Focus (CPRF).</em></p> <p><strong>Who Owns Art? </strong></p> <p>As art objects - especially those from antiquity - have become increasingly valuable, as both commodities and as national treasures, questions as to who owns art and who is best to care for these objects are essential to museum curators, academics, and politicians. There are several debates over who owns art of ancient civilizations like Greece and India. Do treasures like the Parthenon sculptures at the British Museum belong to Greece and should they be returned? Or should they remain in the museum where more people have access to them? This seminar will introduce students to laws enacted by UNESCO (United Nations Educational Scientific and Cultural Organization) to protect world, cultural, and national heritage, as well as to the examination of museum collecting policies in America. Specific cultural patrimony cases will also be examined and discussed. This seminar is for students who are interested in learning more about cultural patrimony, art law, and museums.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9034,2025,446,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/300/arth-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9035,2025,447,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/400/arth-490','<div class="desc"> <p>Open only to senior Art &amp; Art History majors with an emphasis in History of Art. May be repeated once for a total of four units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9037,2025,448,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arth-art-history/400/arth-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9038,2025,2729,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/100/arts-100','<div class="desc"> <p>This is an interdisciplinary course providing an introductory overview of public engagement through the lens of art. Students will learn basic methodologies of public engagement; how to create an inquiry-based lesson plan with an emphasis on creative expression; and how to lead a group of elementary or middle school students, with priority placed on collaboration and art-making. During the first six weeks of the semester, students will research, plan and work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop lesson plans for an original after school art workshop for local youth. In the following 6 weeks of the semester, Oxy students will collaboratively lead their workshops for local elementary or middle school youth, culminating in a final public presentation at the Oxy Arts gallery. This course is an eligibility requirement to apply for a paid student work position through Oxy Arts to lead after school art classes on-site at local Highland Park elementary schools.</p> <p>Cross-Listed as: EDUC 143.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9039,2025,15,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/100/arts-101','<div class="desc"> <p>Working with a variety of drawing materials - charcoal, pencil, ink, gouache, and acrylic paint - students investigate a fundamental aesthetic and visual vocabulary. Beginning with exercises in mark-making, then working through a formal study of basic visual elements and simple subject matter, students develop a working understanding of two-dimensional composition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9040,2025,16,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/100/arts-102','<div class="desc"> <p>This course is an introduction to painting from a global perspective. Throughout history all cultures have developed techniques to depict their realities and ideas through paint. Painting from a global perspective will introduce students to European formalism (line, shape, form, light, space, and color) as one set of tools among many found around the world. We will consider how varying cultures have historically and contemporarily utilized paint to think through experiences on earth.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9041,2025,17,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/100/arts-103','<div class="desc"> <p>The aim of this course is to introduce the conceptual, technical, and critical tools central to contemporary sculpture practices. The class consists of a combination of technical seminars, in-class fabrication, critiques, field trips, informal lectures in contemporary art history, readings, and a series of short papers. Emphasis will be placed on the student''s ability to make, understand, discuss, and write about sculpture in a substantive way.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9042,2025,18,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/100/arts-105','<div class="desc"> <p>Printmaking Fundamentals is an introduction to the technical and conceptual properties of relief and intaglio printmaking. Through a series of projects, critique sessions, and written assignments, the course will introduce students to debates in contemporary printmaking, and the larger historical and cultural contexts that inform their work. The class will also feature visiting printmakers, field trips and other activities linking the coursework to the larger Los Angeles community.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9043,2025,999,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/100/arts-107','<div class="desc"> <p>The aim of the Photography Fundamentals course is to develop the conceptual, technical, and historical tools to develop a critical photography practice. The course will consist of a combination of technical seminars, critiques, class readings, field trips, lab time, and lectures in photographic history and contemporary art practice. The course will provide a technical introduction to the fundamentals of digital photography, including: camera operation, file management, image processing, Photoshop, printing techniques, and image presentation. Additionally, students will develop the critical skills needed to discuss photographs productively, participate in critiques, and generally situate their photographic production within a larger cultural and historical construct. Emphasis will be placed on student''s ability to make, understand, and discuss photographs in a substantive way. Lectures, critiques, and personal consultations will stress the interdependent concerns of technique and content. Underscoring the course''s outcomes of visual literacy are the centrality of photography to the historical development of modernity and the crucial role of digital photography in our image-centric globalized world. Throughout the course, students will be encouraged to integrate the breadth of their liberal arts studies in their image making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9047,2025,892,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-203','<div class="desc"> <p>Intermediate study in sculpture, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year.</p> </div>','ARTS 103 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9048,2025,1570,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-209','<div class="desc"> <p>This course is a conceptual art class that takes photography as its subject. Using a wide range of photographs and photographic practices, the class will consider how photographs are instrumental in forming our notions of self, family, work, and nation. We will also grapple with the difference between analogue and digital photography and photography''s relation to the physical world. The class will read key photography essays that will challenge students to think critically about the role of photography in contemporary culture and modernity, historiography, and science. We will use a broad range of art techniques like drawing, painting, printmaking, sculpture, digital alteration, and even craft techniques to remake and rework photographs to reveal hidden truths or create new meanings. Unlike some classes where you learn art techniques first, here you will be expected to adopt techniques and generate art from a set of ideas that arise from our readings, discussions, experiments, and field trips.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9049,2025,450,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-210','<div class="desc"> <p>Intermediate study in painting, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year.</p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9051,2025,3331,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-212','<div class="desc"> <p>How can a painting or paintings influence individual or group identities? What does historical context, technique and aesthetic have to do with identity? This course will explore these questions and more. We will examine varying cultural moments throughout history where some form of painting was utilized to produce or reproduce national or group identities. We’ll also look at how individual artists used painting to subvert efforts to homogenize national identities. Additionally, students will be introduced to a variety of painting techniques, locating their historical usage relating to the course theme, and uncovering their potential contemporary value. </p> <p>Alongside course lectures, technical demonstrations, and visiting speakers students create five distinct paintings. Through these exercises students will gain an understanding of the historical context for painting practices and how they may be used today in popular and social media. Students will further their media literacy skills by developing a tool-set for navigating contemporary imagery, specifically relating to painting. </p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9052,2025,20,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-215','<div class="desc"> <p>This is an introduction to the fine art of silkscreen printmaking. Students learn the historical, theoretical, and critical understanding of the process, with an emphasis on developing their artistic voice by completing specific assignments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9053,2025,811,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-216','<div class="desc"> <p>An introduction to the process of lithography, a technique of printing from a drawn image on limestone. Course emphasis will be on the drawing and how the medium allows for evolving the visual image over time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9054,2025,451,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-217','<div class="desc"> <p>An introduction to new combined photo and drawing processes in printmaking, including: photo-sensitive emulsion on copper plates, solar etching, and paper plate lithography. This course will explore how photography can influence the many approaches to contemporary printmaking. Students should have an interest in creating photo images and some familiarity with Photoshop software.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9055,2025,1366,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-227','<div class="desc"> <p>This class is an introduction to the historical art of letterpress printing using design elements with text and image. Students will complete a collaborative artist book with hand binding and original imagery using typographic design, hand typesetting, and letterpress printing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9056,2025,2370,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-228','<div class="desc"> <p>Book Arts: The Handprinted Book is a hybrid book making, research, writing and collaborative art making course. Students will advance their knowledge of letterpress printing by researching, planning, designing, and producing a handprinted artist book. The course will address narrative sequencing, page layout and design, type as graphic innovative and/or image-making, methods for the Vandercook Press, and the structure of the book. Each course iteration will address a theme, integrating book making techniques with theoretical readings, collaborations with faculty and departments from across the College, and primary research in Special Collection the Moore Zoology Lab and other campus collections. The course is will also examine the current state of the book in the context of 20th and 21st century artist book design and production.</p> </div>','ARTS 227 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9057,2025,2753,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-230','<div class="desc"> <p>This course invites students with previous art experience from across the College, including visual arts, music, theater, creative writing, MAC, etc., to explore genre-crossing art. The course will focus on the specialty of the faculty member, including video installation, sound art, performance art, site-specific art, collaborative projects, community based projects and social practice art. The class meets twice per week for technical demonstrations, in-class art making, visiting artists, and critical feedback, along with out of class visits to contemporary art and performance venues. Permission of instructor required. Not open to First Year Students.</p> <p><strong>Sonic Materiality: Intersecting Music and Visual Art</strong></p> <p>At the intersection of music and visual art, this collaborative course will explore the ways meaning is made in creative work and is open to all students with an interest in interdisciplinary art practices. Over the semester we will study leading artists whose work straddles sound and visual forms. Students will work with their peers to unpack how they assign meaning and infuse strong concepts and narratives in their art. Through this course, students will experiment with various strategies and tools to express their ideas and will develop a heightened appreciation for the creative process.<br/> <br/> Each week concepts will be presented through the lens of music and visual art and will be structured to alternate between in-depth study and hands-on class exercises. Such experiments will foster student-led discussions, and lead to projects that challenge students to emulate and ultimately reimagine these ideas through their artistic work. We begin with artists like Jason Moran, a renowned pianist and multimedia artist, whose piece Ringing My Phone perfectly demonstrates the innovative way in which he intersects music and language. The conceptual work of Charles Gaines will guide our exploration of systems that produce sensory experiences. In addition to Gaines, we will look at musicians who integrate the historical archive, like Jon Batisteâs piano arrangement of the Star Spangled Banner, alongside visual artists like Bethany Collins whose physical interventions on the musical notions of other national hymns demonstrate how meaning shifts over time. Non-traditional composers such as John Cage and Wadada Smith will prompt a conversation about the nature and forms of sound.<br/> <br/> A significant objective of the course will be to expose the ways we take meaning for granted in our sensory experiences. We will question how language facilitates the categorization of various creative practices and consider the value of blurring such distinctions. Students will be asked to engage in a range of strategies to create individual and collaborative work that integrates multiple art mediums, design systems, and methods to support these creations. They will also consider how context impacts meaning/narratives in their work. Prompts throughout the semester will encourage students to answer questions about how one can create with unconventional sounds/tools from their environment and culminate in a final project resulting in a collaborative performance or presentation.<br/> <br/> The class will emphasize the rich history and resources of LA and will include visiting artists and guest lecturers, as well as field trips to some of LAâs artistic hubs, such as Art &amp; Practice in Leimert Park, The Red Cat, LACMA, Array studios, and relative exhibits. This class aims to enrich studentâs education by exposing them to varying thoughts and approaches to creating and appreciating art. Ultimately we will encourage students to think more broadly about pushing past the traditional boundaries and barriers surrounding art and to create in a way that is authentic to their individual story. Cross-listed as: MUSC 233.</p> <p><strong>Sound Systems as Sculpture</strong></p> <p>Sound Systems as Sculpture is a hands-on, interdisciplinary exploration of the aesthetics, culture and history of sound and its various amplification systems. Taking place in the sculpture studio at Oxy, students will learn aspects of sound system design theory and construction while exploring the origins of sound system culture. Emerging from Jamaica in the 1950s, sound system culture expressed the revolutionary voices of Jamaicans seeking to escape the bonds of colonialism. This critical approach impacted sound system cultures in the UK and the US, particularly during the formative years of electronic music and hip hop. Communities whose voices were suppressed created new forms that amplified their stories, struggles and dreams. Sound Systems as Sculpture will examine the cultural, political and aesthetic impact of this work. Using sculptural practices to design and fabricate sound systems, students will generate new works that develop the art of sonic sculpture and amplify their own voices and sonic imagination.</p> <p><strong>Visualizing Sound</strong></p> <p>Sound Arts takes a cross-disciplinary approach to utilizing sound as a stand-alone installation or integrated within other media. Many contemporary artists are interested in incorporating sound into their projects but may not know how to approach and accomplish that integration. Because sound is ephemeral it can be used in an infinite number of ways to infer complex relationships. The challenge of using sound is that of translating ideas into the sonic medium and then reproducing that medium back into physical space. In this class students will learn about sound and discover ways to apply sound to express a deeper theoretical practice. Practical sound related techniques will be explored, as will their application through skills like deep listening, recording techniques for best capture practices, basics of the Digital Audio Workstation, and the use of sound reproducing systems. Students will collaborate on a project over the course of the semester with an exhibition in the OXY Arts Space at the end of the semester with an opportunity for performance.</p> <p><strong>Pollinator Drones, Wish Factories, and Robotic Dogs: âWhat-ifâ Scenarios as Drivers of Creative Production and Imagination</strong></p> <p>As humankind stares down a number of unprecedented global challenges, the need for creative, radical thinking is imperative. In this interdisciplinary studio, students will develop a series of detailed and speculative projects inspired by boundary-pushing artistic and technological practices. The course will examine precedents from contemporary art, media, engineering, performance, design, and technology that offer responses to a wide range of âwhat-ifâ scenarios. The primary goal of the class will be to guide students as they develop a methodology for making creative and responsive workâone that relies on provocation and imagination as driving forces. Class projects will be designed to develop critical thinking and research skills, art-making and visual communication capabilities, and will call for speculative, even fantastical, responses to complex sites and situations. Technological and data-driven approaches, including data analysis, modeling, and scenario planning, will be integrated into the class assignments, encouraging cross-disciplinary collaborations between computer science and media arts students. Instructional assignments will explore a range of materials, scales, and research methods, and will encourage students to develop their abilities to hone and express innovative responses to complex societal and relational questions. The final series of class projects will address the uncertainty of climate change as a contextual framework, and final proposals may range from site-specific art installations to new applications for robotics; from creating futuristic soundscapes to designing experiences in VR. Site visits and guest lecturers will extend studentsâ connections with selected Los Angeles sites and their contexts, the understanding of a broad set of perspectives and values, and real-world examples of collaborative, cross-disciplinary projects. Cross-listed as: COMP 230.</p> </div>','One ARTS, MUSC, THEA classes. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9058,2025,1503,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-250','<div class="desc"> <p></p> <p>African American, Latinx, Asian, Feminist, GLBT, and transnational artists catapulted by liberationist desires and responding to questions of social transformation are the focus of this hybrid art making, history, and theory class. The course will focus on Los Angeles-based 20th and 21st century artist led efforts that critically engage issues of race, gender, ethnicity, and class both historically and within the present. The course will begin with an investigation of questions related to historiography and memory as they relate to politically engaged art practices through critical texts, a site visit to the Southern California Library, an independent archive of local Los Angeles movement history in South Los Angeles, and a workshop that will share research methodologies employed by my own collaborative artistic project, the Pochx Research Society of Erased and Invisible Histories to contest dominant historical and artistic canons. Through a workshop format, local contemporary artists such as Dewey Tafoya, Shruti Purkayastha, will provide students with tools to develop projects that respond to dominant cultural narratives through graphic, performative, and interventionist strategies. Finally, students will learn how artists shake the foundations of various established institutional worlds and the definitions of art itself by moving away from these very institutions and spheres of practice and by creating their own structures for critical thought and praxis: building collectives, artist led spaces and in the case of School of Echoes, becoming community organizers.</p> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9059,2025,2861,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-270','<div class="desc"> <p>Art, Ethics and Medicine: The PPE Portrait Project is a four-credit class focused on the tenets of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care at USC-Keck Hospital, Stanford Medical School, UMASS, Mass General and advising nearly a dozen other hospitals across the US and beyond. At the heart of the PPE Portrait Project is the centrality of the image, and the role of the face in generating empathy, compassion and ethical behavior. </p> <p>The PPE Portrait Project Semester will combine theory, research and practice together with the community engagement (ARTS 275) intrinsic to this social practice art project. Students will learn how artists act as innovators and catalysts of change; the art history and visual studies of representing the face, including portraiture, photography, and discredited attempts to read intellect or morals in the appearance of a face. Students will also learn about the connections between visual culture (like portraits) and science, including the developmental concepts of facial recognition, and representation recognition in infants and others; the neuroscience of mirror neurons and the biological basis of intersubjectivity as the foundation of ethical behavior; the philosophy of bioethics and notions of patient self-determination and agency; and the biology and physiology of social and cultural actions. Students will learn how looking at images has the power to physically change a person''s body. Through this project, students will deepen their understanding of the structures and processes of privilege, exclusion, and marginalization that shape healthcare in the United States.</p> </div>',NULL,'ARTS 275 ',NULL);
INSERT INTO course_descriptions VALUES(9060,2025,2862,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-275','<div class="desc"> <p>In this course, students will activate their own project site of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care across the US and beyond. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Students will be encouraged to implement the project in a group with whom they have a meaningful connection, including schools, community groups; any group who would benefit from an enhanced human connection at a time of masked distancing, anonymity and faceless interaction. </p> <p>At the heart of the PPE Portrait Project is the centrality of the image, and the role of images of the face in generating empathy, compassion and ethical behavior. With widespread facemask use on our horizon for the foreseeable future, the need to address the isolation and alienation caused by faceless person-to-person exchange is expanding beyond the urgent need of hospitals. Precipitated by social media before the pandemic, and now exacerbated by the coronavirus, we are experiencing an "epidemic of facelessness." </p> <p>Students will use community based learning methods to ethically engage with a group, and innovate with the PPE Portrait Project tenets and materials to best meet the needs of the community partner. </p> </div>',NULL,'ARTS 270 ',NULL);
INSERT INTO course_descriptions VALUES(9061,2025,1571,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-280','<div class="desc"> <p>A team-taught course pairing an Occidental and an Art Center College of Design faculty member in project-based work integrating the history, theory, and practice of the visual arts. Not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9062,2025,3274,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-281','<div class="desc"> <p>A studio course about the use of the self in photography. Students will produce new photo-based projects which may include self portraits (What counts as a portrait? What constitutes the self?) as well as loose or alternative interpretations of the theme, such as work that explores the self through family history. The special focus on the notion of "self" offers a way to engage not only with individual "self-representation," but also with the ways a "self" might emerge from, and shape, other modes of identity: family, community, nation, transcultural. Thus, the course is not only a fine arts course, but also a course that expressly engages with issues of Diversity, Equity, and Inclusion as explored through the experiences, histories, and contemporary lives of students, faculty and the larger communities that an individual may imagine themselves to be a part of. Discussion topics will include gesture and expression, the gaze, beauty, identity, narcissism (actual and perceived), memory and time, and self portrait methodology. Lectures will offer an overview of the history of self-portraiture in photography, from the medium’s early days though contemporary social media.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9063,2025,3285,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-282','<div class="desc"> <p>This studio course will focus on the study of place in photography, with a particular focus on Los Angeles County. As both a global center of the film industry and the city of choice for many artists, LA occupies a unique position in visual culture and the collective imagination. Students will spend the semester working on a photographic project that explores a particular aspect of life in LA–such as a unique community, culture, or subculture, history, climate, geography, or architecture–in depth. Discussion and lecture topics will include photographing communities as both an outsider and an insider, what defines a place, the nuances of photographic genre (journalism, fine art, etc.), and the rich cultural topography of Los Angeles. We will also explore events and policies that have shaped our experience of the region, such as the construction of the freeways, redlining, and restrictive covenants. Special emphasis will be placed on guest lectures from photographers who explore place in their own work and writers who engage with the history of Los Angeles.</p> <p>Students must enter this course with a foundation in digital photography. They should either have taken ARTS 107 (Digital Photography), or should be able to provide instructor with a narrative about their experience in photography.</p> </div>','ARTS 107 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9064,2025,3332,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-283','<div class="desc"> <p>A course that celebrates the physical production of photographs. For the first century and a half of photographic history, a photograph was typically an object to be held in one''s hand or hung on a wall. Today, it is not uncommon for a photograph to exist only in digital form; the entire life cycle of an image may take place on a series of screens. In this course, students will focus on producing tangible photographic objects. Each student will conceive of a photographic project in which a final, physical form (such as an artist book or photo-based sculpture) is central to the concept. The first part of the semester will be devoted to lectures, research, technical demonstrations, and exercises to help students decide on a direction and form for their final projects. Next, students will work intensively to produce a new series of photographs (digitally or on film) that will be refined through group critiques; editing and sequencing will be important topics of discussion at this stage. Finally, students will focus on producing their object(s), taking concepts and skills from the first part of the semester and applying them to their new images. Students will have the opportunity to print in the black and white darkroom and/or with a large-format digital printer.</p> </div>','ARTS 107 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9065,2025,3243,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-287','<div class="desc"> <p>In this course, we will examine historical and contemporary approaches to social documentary photography—visual anthropology, citizen journalism, and agitprop, among other forms—and consider the efficacy of photographic images in both garnering awareness and persuading actors to enact sociopolitical change. We will draw consensus on our understandings of “the real" in contemporary art and the broader media landscape—in tandem to and opposition with staged, scripted, and/or verisimilar depiction modes—while examining the ethics of capturing another''s likeness. Over the course of the semester, we will delve into critical writings and works by documentarians/collectives that bring the (neo-)liberal humanist documentary model into complex new territories. Students will focus on a community, situation, or environment of their own choosing, using pictures and words to examine the unique situations unfolding in front of their cameras. Together, we will confront our role as image-makers, our ethical relationship to our subjects, and ruminate on the civic value of the social documentary form today.</p> <p>The social documents experienced and discussed in class will be used to interrogate systems of differentiation and exclusion that are instrumentalized to preserve patriarchy and racial capitalism. Examining the codification of gender, race, and class through photographic likeness, we will trace a line of resistance in documentary works that offer a response to status quo representations. Our investigations will be grounded in the American Experience—gender queering in the American city, depictions <em>of</em> and <em>by </em>Native Peoples, the foregrounding of white suffering in times of common strife, and lived Black experiences seen from within and without, among other themes.</p> </div>','ARTS 107 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9066,2025,1203,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/200/arts-290','<div class="desc"> <div> <p dir="ltr"><strong>Opera Unbound<br/> </strong><br/> This course explores contemporary opera writ large: where it comes from, what it carries and how it might yet transform.<br/> Led by the core creative team of The Industry (Ash Fure, Malik Gaines, and Yuval Sharon), LA''s foremost experimental opera company and this year''s Wanlass Artists-in-Residence, students will engage up close and personally with a host of LA-based creatives asking questions about how we sound, why we gather, and where we turn to grapple with the pressing questions of our time.<br/> Coursework will involve listening, reading, and discussion as well as hands-on collaborative experiments in operatic design. Site visits to specific locations of past and present Industry productions as well as class trips to live performances across LA will punctuate the term. Class will culminate in a day of public site-specific performances staged at unexpected locations across the Occidental campus.<br/> <br/> <br/> <br/> <br/> <br/> <br/> <br/> </p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9070,2025,1683,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-301','<div class="desc"> <p>Audre Lorde famously wrote that the masterâs tools will never dismantle the masterâs house. What possibilities open up when we use language - a common currency of our everyday lives, too often the foundation that props up structures of confinement and limitation - on our own terms, in forms of our own invention and modes we imagine autonomously? How can we use writing to support and expand the work we do as artists? Is language a âmasterâs toolâ or is it a tool we can use to âdismantle the masterâs houseâ? In this class, we will explore creative forms such as artistic manifestos, statements of poetics/aesthetics, and reviews as invitations to better understand and articulate the parameters of our own art practice, and as powerful opportunities for collective enunciation. We will do close readings of primary texts from European, Latin American, and U.S. American avant-garde and art-activist movements, both historical and present-day. We will consider essays, reviews, manifestos, poems, blog posts, and tweets. Students will write individual and collaborative art statements as a way to clarify their own work, and think through larger issues in aesthetics and the social/political potential of art. Assignment exercises will encompass research and practice in collective and individual art writing, focusing both on student work and the work of other artists.</p> <p>This course fulfills the second stage writing requirement. This course does not fulfill a 300-level studio art elective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9071,2025,2892,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-303','<div class="desc"> <p>Advanced study in sculpture, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year.</p> </div>','ARTS 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9072,2025,3884,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-307','<div class="desc"> <p>Advanced study in photography, including developing a theoretical, historical and critical understanding of materials and media. In this studio course, students will produce complex photographic projects in a genre and photographic medium of their choosing. Students will be expected to refine technical and conceptual skills developed in lower-division photography courses and produce projects that express concepts in a sustained manner. Much emphasis will be placed on critiques, where students will be expected to analyze peer work and provide substantive feedback. Lecture and discussion topics will include editing and sequencing, studio lighting, fine art print production, and exhibition techniques.</p> </div>','Students must have taken ARTS 107 , the introductory-level photography course, as well as one of the three intermediate photography courses (ARTS 281, ARTS 282, or ARTS 283), or have instructor permission. Students who have not taken the prerequisite courses and are seeking instructor permission must be able to detail significant experience in the medium of photography. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9073,2025,21,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-310','<div class="desc"> <p>Advanced study in painting and drawing, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year.</p> </div>','ARTS 102 and ARTS 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9074,2025,1048,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-330','<div class="desc"> <p>Advanced study in printmaking including developing a theoretical, historical, and critical understanding of photo-based materials and media, including images on pronto plates and monotypes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9075,2025,454,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-390','<div class="desc"> <p>Art in LA will explore the shifting roles of the contemporary artist, art writer, and curator in today''s diverse and globalized art world. Students will put theory into practice by engaging in art making, curating and writing about contemporary art in Los Angeles with the goal of creating an expansive critical space for their thoughts to flourish. The course will ask, "What are exhibitions?” investigating conventional and alternative curatorial practices that question the cultural, political, economic, regional, and social contexts shaping the exhibition of contemporary art. Students will collaborate to mount an exhibition of their own design, and will be encouraged to question the boundaries of the "white cube gallery," pushing art into surprising public and private spaces. <br/> <br/> Art in LA will feature behind the scenes visits to Los Angeles area exhibition venues and artists'' studios, enabling students to learn about the range of art practices and the practical exigencies of bringing art and its exhibition to fruition. This course will serve as the required advanced exhibition methods course for junior studio art majors, modeling the myriad of ways it means to be an artist in the world, and readying rising seniors for a robust comprehensive experience. Scheduled at the same time as the Studio Art Senior Seminar, the course is designed to facilitate collaboration between junior and senior art majors. Students in ARTS390 will participate in the ARTS490 senior comps critiques, provide feedback to senior''s artist statement drafts, and collaborate with the senior art majors in the installation of their comprehensive exhibition. </p> </div>','One 200-level ARTS course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9078,2025,455,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/300/arts-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9079,2025,23,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/400/arts-490','<div class="desc"> <p>Group critiques of individual projects in student''s choice of medium. Discussion of techniques, exhibition problems, self-evaluation, and current art movements, in the context of the history of art. May be repeated once for a total of four units.</p> </div>','At least junior standing and ARTS 102 , ARTS 103 , ARTS 105 , ARTS 203 , and ARTS 210 ; OR ARTS 216 ; OR ARTS 217 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9081,2025,456,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/arts-studio-art/400/arts-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9082,2025,3830,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/100/asn-130','<div class="desc"> <p>We will explore key events that shaped modern and contemporary Korean society and culture. We will explore the racial and gendered formation of Korean culture and national identity from the early 1900s to the twenty-first century. Some of the key historical events we will address throughout the semester include Japanese colonialism, the Korean War, the US military presence in South Korea in the aftermath of the Korean War, contemporary global sporting events such as the 1988 Seoul Olympics and 2018 Pyeongchang Olympics, transnational popularity of South Korean popular culture, and the feminist and queer activist movements. The objective of the class is for us to answer the questions: How have these historical events influenced Korea and its inhabitantsâ conception of the nation and its positionality in the world? How has Korean culture evolved over time through transnational encounters? Alongside academic books and articles, we will be viewing and discussing visual media, including documentaries, fictional films, and music videos. All of the course instruction and assigned materials will be in English or have English subtitles.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(9083,2025,3356,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/100/asn-131','<div class="desc"> <p>In this course, we will examine various forms of Korean popular culture. We will examine how Korean popular culture not only reflects, but also influences Korean cultural conceptions of gender, race, sexuality, and class. Each week, we will analyze Korean popular culture through the frameworks provided by relevant academic articles and book chapters. The academic texts we will discuss in class will focus on topics including disability, queer activism, neoliberalism, militarism and masculinity, feminism and anti-feminism, and multiculturalism. The types of popular culture we will examine in class will include films, television programs, and K-pop music videos. All reading materials will be in English and all of the popular culture contents will have subtitles. Therefore, no prior knowledge of Korean language is necessary to take this class.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(9084,2025,3297,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/100/asn-150','<div class="desc"> <p><em>The Literary Mind and the Carving of Dragons</em> is a highly influential work on Chinese literary aesthetics, and its title also suggests two important constituents of the literary composition process by pre-modern Chinese authors: ideas and craftsmanship. By providing an introduction to classical Chinese literature through readings in translation, this course will integrate aesthetic appreciations and cultural understandings of the classical Chinese literature, and help students grasp the conceptions, styles and creative skills of different Chinese authors. The time range will cover the period from <em>The Classic of Poetry (Shijing) </em>through the Qing dynasty. Throughout the course, students will have a basic historical knowledge of the Chinese literary tradition, as well as a sense of how to go about interpreting Chinese literary texts. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9089,2025,3885,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/200/asn-221','<div class="desc"> <p>In this course, we will examine the rich history of feminist theory and activism in Asia and investigate the various issues that Asian feminists have worked on throughout history and leading up to the contemporary era. In particular, we will focus on how feminists from different parts of Asia have contended with issues of colonialism, war, marriage, motherhood, queer rights, and, more recently, sexual consent and the #MeToo movement. We will expand our discussion of these issues into a larger debate about whether and how feminists from different parts of Asia can collaborate with each other in their feminist activism. More broadly, we will discuss how feminists from Asia and beyond can work together without perpetuating colonialist, racist, and neoliberal structures of hierarchy. Alongside academic books and articles, we will be viewing and discussing visual media, including documentaries and fictional films. All of the course instruction and assigned materials will be in English or have English subtitles.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(9091,2025,3416,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/200/asn-253','<div class="desc"> <p>The Tangand Song dynasties (618-1279) are known as Golden Ages in Chinese history, and also generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry. This course introduces the major literary genres and authors of the Tang and Song Dynasties, as well as literati culture emerging during this era. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. Students will discover the key role that literature played in Chinese court politics, empire building, and institutionalized learning; as well as how it shed light on gender and women’s status, war and knight-errantry, Daoist and Buddhist traditions, and more. The primary texts are translated in English, so knowledge of Chinese is not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9092,2025,3886,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/200/asn-260','<div class="desc"> <p>This course offers a survey of Japanese textual and visual culture from Japanâs early modern times (16<sup>th</sup> through late 19<sup>th</sup> centuries). We will learn about early modern Japanâs education systems, print history, and book culture, as well as forms of literacy that shaped Japanâs cultural and national identity. Through a wide range of popular literary and visual materials, we will analyze the modes of knowledge and information transmission and the roles they played in everyday life. To gain an intuitive experience of Japanese literary culture, we will carry out several hands-on activities such as rare books workshops and museum visits. Finally, we will turn to new forms of media that rose after the Meiji Restoration in 1868 and how they influenced modern Japanâs cultural identity. The course is given in English and offered in alternate years. No prior knowledge of East Asian languages is required to take this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9093,2025,3251,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/200/asn-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9094,2025,3417,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/200/asn-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9095,2025,3252,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/200/asn-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Inscribed Landscape: Nature and Travel in Chinese Literature</strong></p> <p>This course will lead students into the world of the Chinese cultural landscape through the lens of literature. We are going to conduct virtual travel to the mountains and waters in China by reading the masterpieces of Chinese landscape and travel writings. We will study the symbolic language that Chinese writers employed to describe their experiences of the natural landscape and their constructions of the cultural landscape. In a broader sense, the focus of this course stems from the interest in cultural geography in the Chinese context. The majority of the course content is on the pre-1800 period. In addition to analyzing literary texts through close reading, this course will introduce students to the ArcGIS system, a digital tool widely used in geohumanities research to view, edit, and analyze geographic data. Students will enjoy the opportunity to create a project using StoryMaps to illustrate their vision of a cultural place. Classes follow a lecture-discussion format. Students are expected to finish assigned readings in advance and actively participate in class discussions. No knowledge of the Chinese language or history is required (or assumed) for this literature-in-translation course.</p> <p><strong>Cultural Appreciation and/or Appropriation through the Lens of Asian Cinema</strong></p> <p>At its core, this course is an attempt to investigate, analyze, and ultimately comprehend the concept of cultural appropriation, in particular through an East Asian context. With a history of imperialism, be it Western or Japanese, in the 19th and 20th centuries, the topic of cultural appropriation is controversial and complicated, whether it is Katy Perry performing wearing a kimono at the American Music Awards or Chinese-Taiwanese-American chef Eddie Huang and his embrace (appropriation?) of African-American black culture. Prior to the actual viewing and analyzing of films, a comprehensive, albeit limited, survey of theoretical works will be conducted; works including but not limited to Richard Rogers’ “From Cultural Exchange to Transculturation: A Review and Reconceptualization of Cultural Appropriation,” Baris Buyukokutan’s “Toward a Theory of Cultural Appropriation,” and Lisa Nakamura’s concept of “identity tourism.” Some of the pairings to be analyzed are: William Shakespeare’s <em>King Lear</em> and Akira Kurosawa’s <em>Ran</em>; Clint Eastwood’s <em>Unforgiven </em>(1992) and Lee Sang-il’s Japanese Western <em>Yuzusazarumono </em>(2013).</p> <p><strong>Hear Now: Jean Luc Nancy and the Aesthetics of Community</strong></p> <p>In this class, we shall be examining the work of one the world’s most important living philosophers, Jean Luc Nancy. Special emphasis will be placed on the close relation Nancy seeks to draw between our so-called “private” aesthetic experiences—the painting that arrests us, the bar of melody that makes us tremble, the line of poetry that haunts us—and our sense of “being in community” (the sense, that is, that our supposedly singular existence is always already plural, is always already shared out with others). Beyond the reading of Nancy’s own works, we shall also be looking at the work of some of his most important predecessors on the question of art’s relation to the community (Kant, Hegel, Benjamin, Adorno), as well as the works of those thinkers who have engaged most directly with his ideas (Derrida, Agamben, Esposito), and those who have explicitly sought to oppose him (Ranciere, Badiou, and others). <em>Prerequisite: CSLC 200 and CSLC 283.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9100,2025,3875,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/asn-asian-studies/400/asn-493','<div class="desc"> <p>"East Asian Society and History": Directed research for senior comps research paper.</p> <p>"Asian Societies and Cultures": Directed research for senior comps research paper.</p> <p>"East Asian Culture": Directed research for senior comps research paper.</p> <p>"Chinese language, literature, and culture": Directed research for senior comps research paper.</p> <p>"East Asian Art and Visual Culture": Directed research for senior comps research paper.</p> <p>"Asian American History and Literature": Directed research for senior comps research paper.</p> </div>','Instructor permission required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9106,2025,24,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bich-biochemistry/400/bich-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Biochemistry majors; to be taken both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9107,2025,457,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bich-biochemistry/400/bich-499','<div class="desc"> <p>Independent study under the supervision of a faculty member. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9108,2025,25,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-103','<div class="desc"> <p><strong>Urban Ecology</strong></p> <p>Los Angeles is an urban ecosystem where people, nature, and the built environment interact. We will consider L.A., the second largest city in the U.S., as a case study of how organisms and the environment influence each other. Through reading, discussion, writing, gathering data, and exploration we will ask, what physical features define the Los Angeles environment? How have these changed over time, and what changes are likely to happen in the near future? What species of organisms (beyond palm trees, pets, rats, and cockroaches) inhabit this city? How does the physical environment affect urban species, and how do they, in turn, affect their environment? Students will develop proficiency in skills needed for the practice of biology, quantitative reasoning, and critical evaluation of scientific ideas and results. This course is an inquiry-based introduction to biological science in a format that includes both classroom activities and fieldwork. Field trips will occur during class time, with one required day-long field trip to be scheduled at the start of the semester.</p> <p><strong>Ecological Enhancement and Restoration</strong></p> <p>Biological, ecological, and social views regarding need, methods, and effects of restoration and enhancement of ecosystems. Recent events from California and the rest of the world are discussed, focusing on marine and terrestrial ecosystems, invasive species, over-harvesting, industrial impacts on the environment, and methods of mitigating or repairing damages. Examples of discussions include: methods of combating over-harvesting in the Pacific Ocean; natural and anthropogenic methods of recovering from forest fires; oil platforms functioning as artificial reefs to help endangered species thrive; also, how does a nuclear generating station affect a giant kelp forest, and what can be done to mitigate those damages?</p> <p><strong>Public Health Biology</strong></p> <p>This introductory course will offer an integrative biological perspective on public health issues, highlighting specific diseases of viral, bacterial, and environmental origin, as well as the influence of social and economic disparity. We will explore specific examples, such as rising antibiotic resistance, cholera and hepatitis outbreaks, cancer, and diabetes, to illustrate biological principles required to understand infectious and non-infectious diseases of public health importance.</p> <p><strong>Topics in Cancer Biology</strong></p> <p>This course will introduce students to the fundamentals of cancer biology. Topics will range from the biological origins of cancer to recent advances in diagnostics and therapeutics. Students will also be given a historical perspective of the bioethics surrounding cancer research and treatment. This course will highlight cutting edge research, with a focus on the detection and treatment of cancer in the age of personalized medicine.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9109,2025,26,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-105','<div class="desc"> <p>This course is designed for non-majors and will be an introductory survey of marine organisms and their environment. It will cover fishes, invertebrates, mammals, reptiles, and algae. Included will be an investigation of behavior, ecology, adaptations, and environmental relationships to humans. An emphasis will be placed on forms common to California. <em>Includes one three-hour lab period per week; field trips will be included during the laboratory period. (Labs may take longer than the scheduled laboratory period to accommodate field trips.)</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9110,2025,30,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-110','<div class="desc"> <div><p>Intro Bio: Ecology, Evolution, and the Environment will explore the diversity of life on Earth and interactions between organisms from evolutionary and ecological perspectives with a focus on the interconnectedness of systems. These concepts will be studied at the level of the individual, population, ecosystem, and biome, and emphasis will be placed on how organisms, from distinct biological groups, meet environmental challenges such as: obtaining energy and nutrients, maintaining water and osmotic balances, reproducing, and adaptations for a changing climate. You will learn to recognize and frame hypotheses about biological organisms and phenomena that can be tested by acquiring and analyzing appropriate evidence; you will gain the ability to recognize bias and insufficient evidence. You will also learn to acquire, analyze, and evaluate biological data through observation and experimentation in the laboratory and in the field. Some of the topics we will cover include: biological diversity, biological classification schemes, the species concept, forces of evolution, adaptation, the relationship between biological structure and function, ecological niches and communities, global change and biological conservation, and extinction.</p></div> </div>',NULL,'BIO 110L Introductory Biology: Biodiversity, Ecology, and Evolution Lab ',NULL);
INSERT INTO course_descriptions VALUES(9111,2025,34,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-130','<div class="desc"> <p>A concept-driven survey course designed to provide broad introduction to the biochemistry, physiology, and molecular biology of prokaryotic and eukaryotic cells. Topics include: structure/function; relationships of biological macromolecules; the roles of such molecules in cellular metabolism and membrane biology; molecular biology of DNA, RNA, and protein synthesis; the cell cycle; elementary genetics; and cellular communication. <em>Includes one three-hour laboratory per week. </em>Prerequisites may be taken concurrently with this course.</p> </div>','CHEM 120 , CHEM 130 or permission of instructor ','BIO 130L ',NULL);
INSERT INTO course_descriptions VALUES(9112,2025,3427,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-193','<div class="desc"> <div><p>Research in an area not otherwise included in the departmental curriculum. Students will be trained in methods of biological research. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9113,2025,459,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-197','<div class="desc"> <p>Research in biology for students who do not have advanced competence in biology (see BIO 397). Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9114,2025,2868,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/100/bio-198','<div class="desc"> <p>Complementing their Oxy Immersive Semester coursework for the California Environment and Conservation Corps, students in the program will engage in service-learning. Students will be matched with Southern California environmental organizations. The hours spent in service (which will be completed virtually) would be scaffolded with reflective reading and writing centered around concepts of environmental stewardship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9116,2025,460,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-221','<div class="desc"> <p>This course focuses on understanding the processes in a cell, at a molecular level, that transfer information from genetic information through the expression of functional proteins. Topics include: basic structure of DNA, RNA, and proteins; gene structure; chromosomal organization; genomic structure and organization; DNA replication; transcription, translation, and processing of gene products; molecular regulation of gene expression, mechanisms in prokaryotes and eukaryotes; regulatory and catalytic RNA, including siRNA and miRNA; and the techniques to study these processes. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 and CHEM 220 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9117,2025,36,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-224','<div class="desc"> <p>Intensive concept-driven exploration of genetic information transfer between generations. Topics include: Mendelian principles, allelic and genetic interactions at the phenotypic level, complex traits, genetic mapping, DNA repair and genome maintenance, epigenetics, and principles of gene regulation. <em>Includes one three-hour laboratory session per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 ; and CHEM 120 or CHEM130; or permission of instructor ','BIO 224L ',NULL);
INSERT INTO course_descriptions VALUES(9118,2025,1149,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-226','<div class="desc"> <p>A course designed to provide a thorough understanding of the intracellular processes of eukaryotic cells. The course will discuss topics including the molecular basis of cellular organization, structure, and function; cell motility; organelle biogenesis and function; cellular communication and signaling; and intracellular processes such as apoptosis and autophagy. <em>Includes one three-hour laboratory session per week, plus two hours arranged.</em></p> </div>','BIO 130 ','BIO 226L ',NULL);
INSERT INTO course_descriptions VALUES(9119,2025,813,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-240','<div class="desc"> <p>Physical and metabolic activities of cells and tissues, properties of the cellular environment, regulatory and homeostatic functions of organ systems. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 (may be taken concurrently) and BIO 105 , BIO 110 , or BIO 115 ','BIO 240L ',NULL);
INSERT INTO course_descriptions VALUES(9120,2025,462,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-250','<div class="desc"> <p>This course is a comprehensive introduction to the plant kingdom, emphasizing the ways in which organismal form and structure are shaped through evolutionary and ecological processes. The primary goal of the course is for students to learn how a major life form has adapted to physical factors, such as light and water, and to biological factors, such as fungi, insects, and vertebrates. Labs involve experimental analysis of fundamental processes, such as: water uptake, photosynthesis, and hormonal regulation, as well as hands-on investigation of the vegetative and reproductive adaptations of the plant kingdom. Independent lab projects and field trips are also key components of the course. <em>Includes one three hour laboratory session per week.</em></p> </div>','BIO 105 , BIO 110 , BIO 115 ','BIO 250L ',NULL);
INSERT INTO course_descriptions VALUES(9121,2025,38,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-260','<div class="desc"> <p>The goal of this course is to introduce marine ecosystems and the physical and biological attributes contributing to their organization. The course will focus on the nearshore marine environment of the Southern California Bight, referencing examples from comparable ecosystems. It will introduce basic physical attributes and the organisms of these dynamic ecosystems. Students will learn how to collect data, in both field and laboratory settings, database management, advanced database queries, conduct basic statistical analyses, test hypotheses, produce graphics, and write scientific papers. This course will serve to prepare students for focused upper division courses and independent research. Labs may take longer than the scheduled lab period to accommodate field trips. <em>Includes one three-hour laboratory session per week.</em></p> </div>','BIO 105 , BIO 110 , or BIO 115 ','BIO 260L ',NULL);
INSERT INTO course_descriptions VALUES(9122,2025,1049,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-268','<div class="desc"> <p>The application of statistical methods to the solution of biological problems. Focus will be on applied statistics (as opposed to mathematical statistics) to study variation in nature. This course will survey descriptive statistics, probability and probability distributions, and methods of hypothesis testing (e.g. analysis of variance, regression correlation, goodness of fit, as well as selected nonparametric procedures). <em>Course includes laboratory workshops sessions.</em></p> </div>','BIO 130 and BIO 105 , BIO 110 or BIO 115 ','BIO 268L ',NULL);
INSERT INTO course_descriptions VALUES(9123,2025,464,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-270','<div class="desc"> <p>Ecology explores the interactions between organisms and their biotic and abiotic environments at a variety of spatial and temporal scales. Topics include: factors affecting organisms at the population, community, and ecosystem levels and the effect of human actions on natural systems. Practical aspects of studying ecology involve work in the laboratory, computer simulations and modeling, and field work. This course emphasizes the fundamentals of study, design sampling, field techniques, data analysis, and written and oral presentation of results. <em>Includes one three-hour laboratory per week and weekend field trips to be arranged.</em></p> </div>','BIO 105 , BIO 110 , or BIO 115 ','BIO 270L ',NULL);
INSERT INTO course_descriptions VALUES(9124,2025,1050,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-275','<div class="desc"> <p>Identification and classification of plants found in the various vegetational communities of Southern California, with emphasis on understanding their ecological and evolutionary affinities. Current methods of field sampling and systematic analysis will be employed. <em>Includes one three-hour laboratory per week and other field trips to be arranged.</em></p> </div>','BIO 105 , BIO 110 , or BIO 115 ','BIO 275L ',NULL);
INSERT INTO course_descriptions VALUES(9126,2025,40,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-280','<div class="desc"> <p>A detailed analysis of the causes and consequences of biological evolution. The focus, here, is on understanding basic evolutionary mechanisms with plant and animal examples used to illustrate and clarify the fundamentals of the evolutionary process. Classical and recent contributions to our understanding of evolutionary biology are examined, including: population genetics, theoretical models, geographical variation, speciation, biogeography, phylogeny, reconstruction, molecular evolution, macroevolution, and the evolution of Homo sapiens.</p> </div>','BIO 105 , BIO 110 , or BIO 115 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9127,2025,1002,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-290','<div class="desc"> <p>This two-unit course will offer students the opportunity to learn techniques of contemporary biology that are used in the laboratory and in the field. These may include: culture and handling of biological specimens, observational methods, imaging use of instrumentation to gather data, methods of data analysis, and identification of organisms. By the end of the semester, students will have been exposed to and gained practice in a diversity of techniques relevant to the practice of biological science. Graded on a credit/no credit basis only. May be repeated once for credit.</p> </div>',NULL,'BIO 103 (Urban Ecology) and BIO 198 ',NULL);
INSERT INTO course_descriptions VALUES(9129,2025,3034,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-295','<div class="desc"> <p>This one-unit course offers students the opportunity to learn about current research in the biological sciences. Students enrolled in the course will attend the weekly 1-hour seminar hosted by the Biology Department, which covers a broad range of biological research topics. Past speaker topics have included conservation biology and ecosystem restoration, climate change effects on marine ecosystems, evolution of social symbiosis, novel therapeutic approaches for drug resistant bacterial infections, evolution of flight, bioillustration, and scientific communication and education. Invited speakers from different institutions present their scientific work to students on a diversity of topics, techniques, and data analyses relevant to current biology research. This course provides students with an opportunity to observe how professional scientists communicate and translate their findings from biological studies to broad audiences.</p> <p>Graded on a CR/NC basis only. Course may be repeated once for credit. Open to sophomores and juniors only.</p> </div>','BIO 130 (may be taken concurrently) and BIO 105 , BIO 110 , or BIO 115 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9131,2025,3328,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/200/bio-298','<div class="desc"> <p>The Huntington-Occidental Pre-med Program (HOPP) is a course that teaches pre-med students how physicians interact with and evaluate clinical populations by introducing students to medical interviewing and differential diagnoses and sharing real patient cases. It empowers students to reflect on the process of becoming a doctor by interacting with medical students, residents, and attending physicians, allowing students to make informed career decisions. Course includes supervised participation in the work of a hospital or other health-related clinic.</p> <p>Students must apply with the Office of Pre-Health Advising before enrolling in the course. Students also must complete Huntington Hospital training and OXY-HIPPA training once enrolled. Instructor permission required.</p> </div>','BIO 130 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9132,2025,41,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-310','<div class="desc"> <p>Introduction to the principles and practice of museology and the functioning of a research natural history museum. Emphasis will be on the development of the "museum conscience" and attendant curatorial skills, through extensive training as a curatorial assistant. Students will make use of the bird, mammal, and fish collections of the Moore Laboratory of Zoology (the world''s largest collections of Mexican birds and Southern California Rocky Reef fishes) and the Cosman Shell Collection at Occidental College. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9133,2025,893,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-320','<div class="desc"> <p>Animal development, with an emphasis on the molecular mechanisms that regulate cell fate, cell adhesion and motility, and the formation of different tissue types. Cell signaling pathways and gene regulatory mechanisms that control development, and are relevant to adult stem cell biology and cancer biology, are stressed throughout the course. The laboratory focuses on major invertebrate and vertebrate model organisms and both classical and molecular genetic approaches used to study animal development. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 and BIO 221 , BIO 224 , or BIO 226 ','BIO 320L ',NULL);
INSERT INTO course_descriptions VALUES(9134,2025,42,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-322','<div class="desc"> <p>Survey of the basic principles that power biological processes in all living organisms. Includes introduction to biochemical techniques, enzyme structure and function, intermediary metabolism, synthesis and degradation of biological macromolecules, information transfer, and a concept-driven integration of these subjects into a biological context. This course meets the Biochemistry requirements for most graduate and professional schools. <em>Includes one three-hour laboratory per week. </em>Not open to students who have successfully completed Biology 349.</p> </div>','BIO 130 and CHEM 220 ','BIO 322L ',NULL);
INSERT INTO course_descriptions VALUES(9135,2025,466,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-323','<div class="desc"> <p>An introduction to histology. Lectures present the structure and function of cells, tissues, and organs in healthy and diseased conditions. The laboratory introduces students to preparation of tissue for paraffin, plastic, and cryostat sectioning and examination by light and electron microscopy. Students work on projects of their own choice. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 , and BIO 105 or BIO 115 ','BIO 323L ',NULL);
INSERT INTO course_descriptions VALUES(9136,2025,468,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-325','<div class="desc"> <p>An introduction to the world of microbes, including viruses, archaea and bacteria, and their role in shaping and sustaining life on Earth. Emphases will be placed on structure, metabolism and bioenergetics, physiological and biochemical adaptations to unusual environments, phylogenetic analysis, biotechnology, microbial ecology, and biological interactions, including plant and animal symbioses. Laboratory exercises will include an exploration of microscopy, cultivation, biochemical techniques, and molecular tools for studying microorganisms. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 221 , BIO 224 , or BIO 270 ','BIO 325L ',NULL);
INSERT INTO course_descriptions VALUES(9137,2025,44,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-330','<div class="desc"> <p>Introduction to current concepts of immunology, including immunoglobulin structure and function, T cells and B cells, cell-cell cooperation in the immune response, and the role of the major histocompatibility complex. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221 , BIO 224 , BIO 226 ','BIO 330L',NULL);
INSERT INTO course_descriptions VALUES(9138,2025,815,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-333','<div class="desc"> <p>Emphasis on cell biology and physiology of neurons. Development and plasticity of the nervous system in invertebrates and vertebrates. Overview of selected central nervous system structures and their function and the cellular and molecular basis of selected nervous system diseases and disorders. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 ; and BIO 226 or BIO 240 ','BIO 333L',NULL);
INSERT INTO course_descriptions VALUES(9139,2025,1367,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-336','<div class="desc"> <p>This course will examine interactions between the human host and infectious microbial pathogens, including bacteria, parasites, viruses, and fungi. Emphases will be placed on mechanisms of microbial defense (virulence factors), immune evasion and adaptation strategies, as well as the molecular and cellular mechanisms of the innate (immediate) response of the host in both immune and non-immune cells. Laboratory includes techniques used in clinical microbiology labs, including culture and identification techniques, as well as cell biology techniques. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221 , BIO 224 , BIO 226 ','BIO 336L ',NULL);
INSERT INTO course_descriptions VALUES(9140,2025,470,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-340','<div class="desc"> <p>Dynamic physiological properties will be examined in single cells, tissues, and whole organisms. Emphasis will be placed on sensory physiology and neuroethology (study of the neural basis of natural animal behaviors). Laboratories will utilize advanced recording techniques, including microelectrodes, isometric tension measurements, semi-intact preparations, and modern electronics.</p> </div>','BIO 226 , BIO 240 , BIO 333 , CHEM 301 , COGS 250 , or PSYC 322 ','BIO 340L',NULL);
INSERT INTO course_descriptions VALUES(9141,2025,1052,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-344','<div class="desc"> <p>The structure and functional organization of animal-like protists and invertebrates are examined as adaptations to life in specific habitats. The current use of these organisms in applied systems, such as aquaculture, and as models to study basic biological processes is discussed. Marine organisms and parasites are emphasized. The phylogenetic relationships between taxa are also debated. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 ; and BIO 105 or BIO 115 ','BIO 344L ',NULL);
INSERT INTO course_descriptions VALUES(9142,2025,2870,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-345','<div class="desc"> <p>This course will survey the diversity among major classes of viruses in genomic material, replication, and host cell interaction. We will discuss aspects of antiviral strategies by the host immune response as well as ongoing research in medical antiviral therapies. In addition, we will cover various ways that viruses have been harnessed as useful tools in the laboratory as sources of unique enzymes, vectors for introducing exogenous material into cells, and in various other applications such as phage display.</p> </div>','BIO 130 , and BIO 221 , BIO 224 , or BIO 226 ','BIO345L ',NULL);
INSERT INTO course_descriptions VALUES(9143,2025,1003,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-349','<div class="desc"> <p>This course explores the roles of the essential biological macromolecules, focusing on proteins, while covering lipids, carbohydrates, and nucleic acids. Topics include the structure and function of these macromolecules, as well as an investigation of the biochemical methods used to study them. Also included are topics covering proteomics, DNA-based information technologies, biosignaling, and an introduction to enzyme kinetics. This course is the first in a two-semester sequence of Biochemistry classes (with CHEM 350) that is required for Biochemistry majors. For a one semester Biochemistry class, see BIO 322. Not open to students who have successfully completed BIO 322.</p> </div>','BIO 130 and CHEM 220 ','BIO 349L ',NULL);
INSERT INTO course_descriptions VALUES(9144,2025,895,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-350','<div class="desc"> <p>Symbioses are intimate associations involving two or more species. Symbiotic associations are widespread in nature and we can expect to find them in every type of ecological niche. This course will cover the diversity of symbiotic interactions that exist between both microbes and fungi and various eukaryotic hosts, including plants, animals, and protists, as well as other microorganisms. Topics in both lecture and lab will range from molecular to ecological, including the specific molecular communication between partners, the evolution of unusual host structures, novel physiological and biochemical capabilities, and the unique ecological advantages that many symbioses confer. This course will also include writing, presenting, and reviewing published work on various symbioses.</p> </div>','BIO 130 , and BIO 105 , BIO 110 , or BIO 115 ','BIO 350L ',NULL);
INSERT INTO course_descriptions VALUES(9145,2025,897,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-356','<div class="desc"> <p>The biology of marine fishes begins with a study of the phylogenetic evolution of fishes. Within this context, it discusses the physiology, ecology, and behavior of marine fishes, utilizing examples from our local fauna. Advanced methods of studying marine fishes will be covered, with an emphasis on field research in which the class will visit various marine habitats throughout Southern California. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 240 , BIO 250 , BIO 260 , BIO 268 , BIO 270 , BIO 275 , or BIO 280 ','BIO 356L ',NULL);
INSERT INTO course_descriptions VALUES(9146,2025,1054,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-360','<div class="desc"> <p>Avian Biology is the study of birds, with particular emphasis on identification, natural history, and evolution of birds local to Southern California.</p> </div>','BIO 130 , and BIO 105 , BIO 110 , or BIO 115 ','BIO 360L ',NULL);
INSERT INTO course_descriptions VALUES(9147,2025,472,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-369','<div class="desc"> <p>Biological oceanography will focus on the biology of the open ocean, with emphasis placed on relating parameters of the physical-chemical ocean to the distribution and abundance of marine organisms. We will focus on understanding the physical and biological processes of the Southern California marine area using field and laboratory techniques. Using examples from our local ecosystem, students will explore the intricacies of macro-scale oceanographic processes. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 260 or BIO 270 ','BIO 369L ',NULL);
INSERT INTO course_descriptions VALUES(9148,2025,1322,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-370','<div class="desc"> <p>This course addresses contemporary approaches to ecology and conservation, with emphasis on ecological fieldwork in diverse locations. The course will have a regional focus, with the possibility of emphasis on desert, mountain, coastal, or tropical ecosystems. Students will conduct field research, including the design, implementation, data analysis, and presentation of research projects. Emphasis will be placed on the impacts of anthropogenic change on native ecosystems. </p> <p>This class has been designed to allow for meaningful field study in the region. Each section of this class meets for one full day per week to allow for fieldwork. The course will include overnight field trips, including several extended trips on weekends and outside of class hours, potentially during fall break.</p> <p>If one of the lab sections does not fill to capacity, that section may be closed and students asked to enroll in the other lab section.</p> </div>','BIO 260 , BIO 270 , or GEO 225 ','BIO 370L ',NULL);
INSERT INTO course_descriptions VALUES(9149,2025,3357,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-372','<div class="desc"> <div><div><p>This course explores the causes of global change and the consequences for organisms, ecosystems, and the Earth. We will examine past, present, and projected future trends and give special attention to the role of human activity in global change. Topics will include land use, energy use, climate change, biodiversity loss, biotic interchange, and pollution, as well as responses, hurdles, and solutions.</p></div></div> </div>','Any 100-level Biology course except Biology 103, or permission of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9150,2025,2323,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-373','<div class="desc"> <p>This course is an opportunity for students to learn more advanced methodologies in computational biology. By examining a variety of biological questions that are often addressed with computational pipelines, modeling, or simulation, students will get in-depth experience with important computational concepts (including: abstraction, algorithms, automation, logic, and problem solving). This includes the study of complex biological systems, such as projecting biological responses to climate or ecosystem change, quantifying spatial biodiversity hotspots, evaluating time series data for populations, and computing evolutionary parameters from genomic datasets. Students will also get experience with computer programming in the R statistical language and Python. Additional biological topics may include: spatial ecology, including species distribution modeling, community assemblage and dissimilarity matrices, population simulations, classification with machine learning, and bioinformatics with genomic data. Course includes laboratory workshops sessions.<strong></strong></p> </div>','BIO 268 , COGS 255 , COMP 131 , GEO 255 , MATH 150 , or PSYC 201 ','BIO 373L ',NULL);
INSERT INTO course_descriptions VALUES(9151,2025,46,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-378','<div class="desc"> <p>Emphasizes the evolutionary approach to the study of animal behavior, drawing broadly from the various disciplines within biology concerned with the factors that determine which organisms survive and reproduce. The course material will be divided into four broad categories: sensory capabilities, feeding patterns, spacing patterns, and reproduction. For each topic, theory and application will be presented. Students will analyze research papers and lead discussions on an aspect of each major topic. The laboratory portion of the course will focus on observational and experimental approaches to studying animal behavior in the lab and in the field. We will make use of local resources, such as zoos, aquaria, wildlife conservation areas, veterinarians, and animal rehabilitation facilities. An independent research project is required. This course is designed for Biology majors, although it would be appropriate for students from other majors. <em>Includes one three-hour laboratory per week and weekend field trips to be announced.</em></p> </div>','BIO 105 , BIO 110 , BIO 115, or BIO 130 ','BIO 378L ',NULL);
INSERT INTO course_descriptions VALUES(9152,2025,899,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-380','<div class="desc"> <p>An investigation of physiological processes in plants, including photosynthesis; nutrient uptake and water relations and how they are affected by environmental conditions; and interactions with other organisms, including insects, vertebrates, and fungi. The emphasis will be on how to quantify and predict plant physiological responses to the particular ecological pressures of Southern California. Classroom discussions and presentations will focus on papers from the current scientific literature. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 250 ','BIO 380L ',NULL);
INSERT INTO course_descriptions VALUES(9153,2025,2375,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-390','<div class="desc"> <p>This seminar course will teach students skills needed to read and critically analyze original journal articles. Some lectures will be given, but the bulk of the course will consist of student-led discussions and analysis of scientific papers. Students will improve their communication skills by discussing papers and leading discussions, by writing a research paper and peer-editing, and by preparing PowerPoint presentations as an aid for leading discussions. May be taken more than once for credit as the topics will differ each semester, but can only be used to fulfill one of the requirements for the Biology major. Cannot be used to fill the Biology requirement of the Biochemistry major.</p> <p><strong>The Broader Impacts of Biology</strong></p> <p>This seminar course will explore the broader societal impacts of the biological sciences. Science is an endeavor that aims to categorically build knowledge about the universe in an objective manner. But our science not only informs society, it is also shaped by the needs and structure of our society. In this class, students will explore the potential societal impacts and determinants of their scientific interests through careful exploration of the literature. Through this exploration, students will learn to lead discussions about the intersections between science and society, critically evaluate the role of science in society, and develop skills in both oral and written scientific communication. Students will work with the professor to lead a discussion on a topic of their choice and will learn to write a “broader impacts” section of a scientific grant, detailing how the science extends beyond the boundaries of the specific scientific endeavor to affect society. Each week we will explore a research topic in the scientific literature and accompanying literature on the societal impacts/determinants of that research. Example topics: Climate Justice and Global Change Biology, Environmental Justice and Urban Ecology, Biological Property Rights and Cancer Research, Anti-Racism in the Biological Sciences, Indigenous Rights and Ethnobiology, Social Equity in Human Health, and Microbiology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9154,2025,2863,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-393','<div class="desc"> <p>Topics vary semester to semester. A prior Statistics course is preferred but not required.</p> <p><strong>The Biology and Epidemiology of COVID-19</strong></p> <p>How did COVID-19 come to ravage the world and bring it to its knees in just a few months? What is happening now, and what will happen next? As of mid-July, 2020, there were over 13 million cases of COVID-19 worldwide, and 570,000 deaths (World Health Organization). Over 3.2 million of those cases and 135,000 deaths were in the United States. All of these numbers are increasing. Students in this class have the unique opportunity to study this pandemic as it is happening. Topics will include the biology of the SARS-CoV-2 virus, the COVID-19 disease, and factors that affect the outcome of the disease. Testing and vaccine development will be covered. The epidemiology of the disease will be discussed, including the disproportionate effects of the disease in people of color. </p> </div>','BIO 221 , BIO 224 , BIO 226 , BIO 322 , or BIO 349 ','BIO 393L ',NULL);
INSERT INTO course_descriptions VALUES(9155,2025,48,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-395','<div class="desc"> <p>Research for approximately five hours per week for students to study in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9156,2025,474,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/bio-397','<div class="desc"> <p>Directed research with individual faculty members for students with advanced competency to study in an area not otherwise included in the departmental curriculum. In addition to topics that may be studied on the Occidental campus, courses offered at the marine station of the Wrigley Institute for Environmental Studies may be taken for credit under this course number. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9157,2025,1106,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/300/copy-of-bio-326','<div class="desc"> <p>This course focuses on how to build the tree of life from DNA data, from how DNA evolves to how DNA mutations are analyzed to create phylogenies. Topics covered include the theory behind molecular evolution and various analytical methods, as well as its application to creating evolutionary histories of genes and organisms. </p> </div>','BIO 280 ','BIO 326L',NULL);
INSERT INTO course_descriptions VALUES(9158,2025,49,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/400/bio-490','<div class="desc"> <p>Topics of these seminars will be announced at Spring pre-registration. Each senior must pass one seminar for the Comprehensive requirement. Each seminar meets two hours per week with extensive reading, discussion, and a major oral presentation by each student. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9160,2025,475,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/400/bio-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9161,2025,476,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/500/bio-501','<div class="desc"> <p>Supervised investigation by properly qualified graduate students working toward a Master''s degree. Students may not register for more than two courses of Research during any semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9162,2025,50,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/500/bio-590','<div class="desc"> <p>Preparation of the Master''s thesis in consultation with the advisor and committee members. Department approval required.</p> </div>','At least two courses of BIO 501 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9165,2025,479,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bio-biology/500/bio-599','<div class="desc"> <p>Continuing work on Master''s thesis. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9166,2025,2872,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/100/blst-101','<div class="desc"> <p>This course introduces students to the history and methods of the discipline known as Black Studies. Readings will focus on the origins and institutionalization of Black Studies as a field of academic inquiry. Students will learn about the philosophical and political debates that laid the intellectual foundation for Black Studies and examine the social movements that resulted in the field of Black Studies in the present. Topics include the foundational academic work of W.E.B. DuBois, the San Francisco State student revolt of 1968, Mellon and Ford Foundation funding of programs and departments, and the recent student demands at University of Missouri and elsewhere. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9167,2025,3435,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/100/blst-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9172,2025,2844,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of Africans in North America, to the quest for abolition and freedom in the nineteenth century, to the modern freedom struggle of the mid-twentieth century. With our focus on pivotal demographic, cultural, and political developments within Black American communities across the United States, we will explore key themes and watershed moments in the African American experience. By analyzing the dynamics of African American history in this way, we will see how deeply Black freedom fighters, cultural innovators and institution-builders shaped the culture and politics of the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9173,2025,3276,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-208','<div class="desc"> <p>This interdisciplinary course examines the migration of six million African Americans who left the rural South to move to cities in the North, Midwest and West in the first half of the twentieth century. Beginning with the “First Great Migration” of 1910-1930 and continuing through the “Second Great Migration” of the 1940s through the 1960s, we will explore the ways that this unprecedented demographic shift laid the groundwork for the civil rights movement, the quest for Black power, and the ongoing quest for social justice. Throughout the course, we will remain attentive to the way that Black migrants created and nurtured the new forms of music, art, and ways of being that ultimately transformed American culture. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of Black Americans and the culture and politics of the United States. </p> <p>This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9174,2025,3263,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-218','<div class="desc"> <p>Over fifty years ago, the first person in the U.S. hired to coordinate a Black Studies program, Nathan Hare (1970), published an essay titled, ‘‘Black Ecology,’’ in which he argued that it was imperative that we come to ‘‘understand how both the physical and social environments of blacks and whites have increasingly evolved as contrast.’’ Since then, many scholars from across the social sciences and humanities have contributed to this endeavor. This emergent field of Black ecological thought is important because it provides insight about race and the environment from the perspective of Black study. In this survey course, we will study a range of black ecological thinkers and the concepts that they offer for understanding contemporary environmental issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9175,2025,3333,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-230','<div class="desc"> <p>In this course, we will read and study the creative, intellectual and political offerings of those who identify as Black British cultural producers. In doing so, we will consider how Black British peoples simultaneously struggled to belong to what we call Great Britain while also challenging the ongoing structures of empire and colonialism that are embedded within British histories and institutions. We will explore works by Jay Bernard, Leonora Brito, Isaac Julien, Steve McQueen, Zadie Smith, Luke Sutherland and others. Students will be asked to think critically about the overlapping and at times contradictory experiences of Black peoples in Scotland, England and Wales and their historical and contemporary arguments on topics ranging from abolition to multiculturalism. In doing so, we undertake the serious work of thinking through and theorizing blackness, Black sociality and Black life outside of solely U.S.-centered perspectives. Assignments will include both informal and formal written components.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9176,2025,2609,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-240','<div class="desc"> <p>From demanding change to pushing for revolution, Black women have long been at the forefront of protesting for social justice. At the same time, however, their intellectual and political contributions and frameworks have often been ignored or co-opted by others. In this course, we will engage with the myriad ways in which Black women write toward a different kind of world, including creative writing, academic essays and talks, films and performances. Through exploring cultural producers who write from various national/international/translational positions and identities, we will locate African American history and literature within a larger Black diasporic history and literature to understand the global nature of Black womenâs writing. Topics will include, but are not limited to, violence against women, access to education and reproductive justice, the linkages between racism and capitalism, self-representation and abolition politics. By taking seriously the contributions of Black women cultural producers, we will also undertake the work of figuring out the definitions behind the words that make up the title of our course: how do our cultural producers define Black? How do they define the identity position of âwomenâ? What is the importance of writing, of text? And finally, how do they conceptualize and define social justice? Students will be asked to produce both informal and formal writing for the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9177,2025,2611,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9178,2025,3334,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-263','<div class="desc"> <p>W.E.B. (William Edward Burghardt) Du Bois, was a prolific scholar, writer, and social/political analyst and organizer. Over the course of his lifetime, Du Bois wrote over 2000 bibliographical entries, across a range of genres, including: research monographs, plays, pamphlets, autobiography and biography, history, novels, poems, and popular press articles. At the same time, Du Bois utilized multiple methods, forms of data and evidence, and literary styles within and across texts. Nevertheless, in the domain of social science, and sociology more specifically, his work was intentionally marginalized. Yet while Du Bois was made a minor figure in American social science, he was a primary progenitor of the transdisciplinary field of Black, African American, or Africana studies and thus played a foundational role in circumventing the racial-colonial order of knowledge by attending to Black life and sociality. In this course, we will study the social theory of Du Bois by reading texts from across his vast corpus—from his more formally social scientific writing and data visualizations to his creative projects like poetry and short stories. For the final project of the course, students will deploy a Du Boisian approach to social theory and analysis using more expressive forms (such as illustration, painting, film and video, poetry, music, photography, data visualization, short stories, or lyrical essays).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9179,2025,2613,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/200/blst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9183,2025,3277,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-315','<div class="desc"> <p>Black Feminist Movements is an upper-division course wherein we interrogate our conceptualizations of “Black,” “feminist,” “Black feminist” and “movements.” What, or who, do we mean when we say “Black,” “feminist” and “Black feminist”? What do we mean when we invoke “movements”? Why is movement – literal and figurative – central to our understanding of blackness? What might it mean for blackness – Black peoples, Black communities, Black intellectual, political and cultural traditions – to move across land and sea, through space and time and on page, stage and screen? By reading expansively across disciplines, our course affirms that Black feminists have long been at the forefront of revolutionary practices of radically re-imagining what our world can be. We will engage with cultural producers from the Black diaspora (including, but not limited to: the United States, the Caribbean and the United Kingdom) working within critical ethnic studies, literary analysis, queer of color critique and performance studies, among others, and take seriously what they share in regards to prison abolition, the linkages between racism and capitalism, Black trans activism and other critical issues that demand our attention and action. We will locate these intersectional conversations within Black diasporic contexts – the literary, theoretical, political and cultural – as we seek potential answers to the questions posed above. Students will be asked to complete a research paper at the end of the term.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9184,2025,3278,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-318','<div class="desc"> <p>Saidiya Hartman (2019) conveys the social significance of waywardness for Black life: “Waywardness is an ongoing exploration of <em>what might be;</em> it is an improvisation with the terms of social existence, when the terms have already been dictated, when there is little room to breathe, when you have been sentenced to a life of servitude, when the house of bondage looms in whatever direction you move.” In this course, we will study waywardness, fugitivity, and the anarchism of Blackness as integral concepts for understanding how Black people have navigated the treacherous terrain of slavery and its afterlife. Through historical and contemporary case studies, discussion, and engagement with a range of thinkers, including, but not limited to, Saidiya Hartman, Lucy Parsons, Zoé Samudzi, William C. Anderson, Lorenzo Kom’boa Ervin, and Fred Moten, students will explore how anarchism (broadly defined) is a critical resource for Black life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9185,2025,3314,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-329','<div class="desc"> <p>Black queer thought are the knowledges, embodied and otherwise, that both enact critique of and imagine possibilities against the demands of heteronormativity, white supremacy, patriarchy and capitalism. In this course, we will engage with the multiple forms of text produced by those who may – or may uncomfortably – identify as Black and queer. By doing so, we will explore how the cultural producers in question complicate and elaborate upon the sometimes static and often U.S.-centered definitions we hold for “Black” and “queer,” challenging us to instead conceptualize these as dynamic and shifting positions rather than stable identity categories. Texts will be drawn from the works of James Baldwin, Ashon Crawley, Jackie Kay, Kara Keeling and others. This class thus situates students to join in on ongoing critical conversations within Black Studies, Queer of Color Critique, Performance Studies and American Studies. Assignments will include both informal and formal written components, and students will be asked to produce a final research paper. This class fulfills the second-stage writing requirement for the Black Studies major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9186,2025,3446,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-343','<div class="desc"> <p>In this project-based course, we will focus on Black ecological or environmental experiences and perspectives in Los Angeles and beyond. We will explore the theoretical and methodological tools and big ideas of the nascent field of Black Ecology through reading and discussing key texts. However, our ultimate aim is to share what we learn with as wide an audience we can muster using various digital technologies. Thus, this course is designed as a collaborative, interdisciplinary research collaboratory rooted in the tradition of W.E.B. Du Bois who operated a sociological research lab focused on Black life in America when he was a professor at Atlanta University between 1895-1924. Each iteration of this course will focus on a different project related to Black ecologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9187,2025,2875,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-346','<div class="desc"> <p>This course thinks through current debates over the relationship between literary aesthetics and harmony in American democracy. Do aesthetics foster a more harmonious or disharmonious national culture? Is disharmony ever important to progress? How does literature represent protests for social change that are often only possible outside the law, like the many freedmen and freedwomen escaping slavery and demanding the destruction of that system? How does this alter our understandings of what it means to be a fugitive? How can the fugitive fighting for freedom be distinguished from the unprincipled outlaw? From another perspective, we will consider how the complications of American society have altered certain traditional literary forms. While recent scholarship has addressed these questions in regards to early- to mid-20th century literature, this course will look back further, starting from the early 19th century to the very beginning of the 20th. We will complement the literature by reading relevant historical materials from the abolitionist movement, labor movements, government debates over Emancipation and Reconstruction, etc. The course will include literature from Frederick Douglass, Sojourner Truth, Walt Whitman, Ida B Wells, and Charles Chesnutt, amongst others, and will cover several genres, including: oratory, autobiography, political pamphlets, and short fiction. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9188,2025,3322,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-360','<div class="desc"> <p>In her 1993 lecture for accepting the Nobel Prize in Literature, Toni Morrison says, “[s]he is convinced that when language dies, out of carelessness, disuse, indifference and absence of esteem, or killed by fiat, not only she herself, but all users and makers are accountable for its demise.” How does language die? What does it mean to be careless with language, to not use it, to be indifferent to it and rob it of its esteem? What does it mean to kill or stifle language by official decree? In our seminar on Toni Morrison, we will engage with the writings of one of the most preeminent writers and critical thinkers in literature (US-based and otherwise) in order to examine the powerful and provocative ways in which she asked and answered these questions before her passing on 05 August, 2019. We will situate her as a cultural critic, one who produced novels, short stories, essays and speeches and in doing so, informed the frameworks of American Literature, Black Feminist Theory, American Studies and Critical Race Studies, among other fields. Thus, we will collectively unpack the ways in which Morrison’s writings have guided, contested and informed American cultural and literary production in the 20th and 21st centuries. Students will be asked to complete a research paper at the end of the term. This course meets the second-stage writing requirement for Black Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9189,2025,2615,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-376','<div class="desc"> <p>This interdisciplinary seminar explores the modern uses and abuses of African American history by focusing on the public memory of slavery and emancipation in the United States. Analyzing a range of fiction, film, advertisements, tourist sites, and public monuments, we will interrogate and assess the ways that popular representations of slavery, the Civil War, and Reconstruction were shaped by (and in turn, shaped) several of the key cultural developments and social and political movements of the 20th and 21st centuries. During the second half of the semester, students will complete a research paper on a topic related to the themes of the course. This course satisfies the second-stage writing requirement for the Black Studies major.</p> </div>','One BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9190,2025,2782,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/300/blst-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. Major requirement met: Group III/IV.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9194,2025,2543,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/blst-black-studies/400/blst-490','<div class="desc"> <p>During the spring semester, students will complete a 25-page research paper on a topic relevant to Black Studies. The project will be based on original analysis of primary sources and grounded in the scholarly literature on the subject. Seminar meetings will be devoted to discussion of selected texts on research methods in Black Studies and ongoing review of students’ work-in-progress. The seminar will conclude with student presentations that will be open to the entire campus community. </p> </div>','BLST 101 and the BLST Second-Stage Writing Requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9196,2025,2730,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/bosp-barack-obama-scholars-program/200/bosp-200','<div class="desc"> <p>The aim of the Obama Scholars Program Seminar is to help Obama Scholars and Fellow develop and pursue their own conception of the public good, with the guidance of a faculty mentor and the support of members of their cohort. Participation in the seminar involves discussing selected texts and films; attending public lectures and other events; meeting with people at Oxy and beyond who serve the public good in various ways; and, in some cases, participating in community engagement projects. Permission of instructor required.</p> <p>This seminar is open only to Obama Scholars. Students may repeat the seminar for credit, as long as they remain Obama Scholars.</p> </div>','N/A ','N/A',NULL);
INSERT INTO course_descriptions VALUES(9197,2025,51,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/100/chem-100','<div class="desc"> <p>Develop the skills necessary for a satisfactory introduction to general chemistry.</p> </div>','Open only for first year frosh with successful completion of a placement examination. Others only with permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9198,2025,52,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/100/chem-104','<div class="desc"> <p>This is a course suitable for non-majors and covers the chemical bases of life. The course will be structured around the chemistry of the fundamental building blocks of life - nucleic acids, proteins, polysaccharides, etc. - and how they interact to support the cellular life. Examples of the specific topics include the evolution of the human genome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9199,2025,53,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/100/chem-120','<div class="desc"> <p>An introduction to the primary chemical concepts of atomic structure and quantum theory, periodic trends, molecular structure, chemical kinetics, equilibrium thermodynamics, and acids and bases. <em>Includes one three-hour laboratory per week.</em></p> </div>','Satisfactory performance on the Chemistry Placement Examination, completion of one First Year Seminar or CWP 201 (formerly WRD 201), or permission of instructor ','CHEM 120L ',NULL);
INSERT INTO course_descriptions VALUES(9200,2025,55,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/100/chem-130','<div class="desc"> <p>An advanced presentation of topics in atomic structure, periodic trends, molecular structure, molecular symmetry, and vibrational spectroscopy. <em>Includes one three-hour laboratory per week.</em></p> </div>','AP Chemistry score of 4 or 5 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9201,2025,901,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/100/chem-150','<div class="desc"> <p>Symmetry is a fundamental unifying aspect of nature and is found in many human creations, from art, music, and architecture, to mathematics and science. In chemistry, symmetry is central to understanding the interplay of molecular architecture and function. This course provides the student with a qualitative and formal conceptual framework for categorizing molecular structures.</p> </div>','CHEM 100 , CHEM 120 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9202,2025,57,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/100/chem-195','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9204,2025,1572,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/200/chem-201','<div class="desc"> <p>Intensive study of the modern laboratory methods of analysis, with applications to environmental systems.</p> </div>','CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9206,2025,58,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/200/chem-220','<div class="desc"> <p>Introduction to the fundamental concepts of organic chemistry. The course explores the properties and structures of carbon-based molecules, and focuses on how these factors influence their reactivity. Special emphasis is placed on biologically relevant organic transformations, as well as the prevalence of organic chemistry in everyday lives. Includes one three-hour laboratory that focuses on the practical techniques employed when conducting reactions and purifying organic molecules.</p> </div>','CHEM 120 or CHEM 130 ','CHEM 220L ',NULL);
INSERT INTO course_descriptions VALUES(9207,2025,60,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/200/chem-221','<div class="desc"> <p></p><p>Continuation of Organic Chemistry I. The course focuses on the reactivity of organic molecules, including molecules and reactions with biological relevance. Special emphasis is placed on mechanism and employing chemical reactions to develop strategies for multistep synthesis. Includes one three-hour laboratory that applies the techniques of organic chemistry to the synthesis of interesting organic molecules.</p><p></p> </div>','CHEM 220 ','CHEM 221L ',NULL);
INSERT INTO course_descriptions VALUES(9208,2025,481,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/200/chem-240','<div class="desc"> <p>Building on concepts developed in prerequisite classes, fundamental concepts in thermodynamics are developed from first principles, with subsequent application in chemical equilibrium and kinetics. Applications to biological systems and technology are emphasized. The substantive laboratory component focuses on developing analytical skills.</p> </div>','CHEM 120 or CHEM 130 ','CHEM 240L ',NULL);
INSERT INTO course_descriptions VALUES(9209,2025,483,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/200/chem-280','<div class="desc"> <p>The course will explore the application of 1H, 13C, and two-dimensional NMR spectroscopy to the organic laboratory, as well as the important separation protocols such as: column chromatography, gas chromatography, and chiral HPLC. <em>Includes one-three hour laboratory per week.</em></p> </div>','CHEM 221 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9210,2025,62,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/200/chem-295','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9212,2025,63,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-300','<div class="desc"> <p>An introduction to the principles of thermodynamics and kinetics and their application to chemical systems.</p> </div>','CHEM 240 , Calculus 2 , and PHYS 125 or PHYS 230 ','CHEM 300L',NULL);
INSERT INTO course_descriptions VALUES(9213,2025,64,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-300l','<div class="desc"> <p>Applications of chemical thermodynamics and kinetics. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 300',NULL);
INSERT INTO course_descriptions VALUES(9214,2025,1369,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-301','<div class="desc"> <p>An introduction to the principles of chemical thermodynamics, kinetics, and spectroscopy, with a focus on applications to biochemical systems.</p> </div>','CHEM 221 , Calculus 2 , and PHYS 115 or PHYS 125 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9215,2025,902,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-305','<div class="desc"> <p>An introduction to quantum mechanics, atomic and molecular structure, spectroscopy, statistical thermodynamics, kinetic molecular theory, and chemical applications of group theory.</p> </div>','CHEM 130 or CHEM 150 , Calculus 2 , and PHYS 125 or PHYS 230 ; or permission of instructor ','CHEM 305L ',NULL);
INSERT INTO course_descriptions VALUES(9216,2025,903,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-305l','<div class="desc"> <p>Atomic and molecular spectroscopy and modern techniques in physical chemistry. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 305 ',NULL);
INSERT INTO course_descriptions VALUES(9217,2025,1438,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-315','<div class="desc"> <p>An introduction to the study of kinetic molecular theory and chemical kinetics.</p> </div>','MATH 120 and PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9219,2025,65,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-340','<div class="desc"> <p>Application of modern theories of physics and chemistry to the synthesis, bonding, and reactivity patterns of inorganic compounds. Special emphasis on the role of metal ions in biological systems.</p> </div>','CHEM 120 and CHEM 150 ; or CHEM 130 ; and CHEM 220 , CHEM 221 , CHEM 240 , CHEM 300 , and CHEM 305 . ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9220,2025,66,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-340l','<div class="desc"> <p>Inorganic synthesis and structure confirmation. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 340 ',NULL);
INSERT INTO course_descriptions VALUES(9221,2025,485,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-350','<div class="desc"> <p>Biochemistry of macromolecules, with an emphasis on protein structure and function.</p> </div>','CHEM 221 and CHEM 240 ','CHEM 350L',NULL);
INSERT INTO course_descriptions VALUES(9222,2025,486,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-350l','<div class="desc"> <p>Laboratory techniques in Biochemistry. <em>One three-hour laboratory per week.</em></p> </div>','CHEM 221 and CHEM 240 ','CHEM 350 ',NULL);
INSERT INTO course_descriptions VALUES(9223,2025,67,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-355','<div class="desc"> <p>The main focus of this course is utilizing biological and chemical databases for research. The course will investigate: (1) tools that are used to extract and analyze data on small molecule drugs and biological sequences from these databases; (2) algorithms and scoring schemes used in sequence alignment and homology searches; (3) the significance of this information in modern chemical and molecular biology medicine, pharmaceutical development, protein engineering and drug design, genetics, and molecular evolution.</p> </div>','BIO 130 and CHEM 221 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9224,2025,487,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-360','<div class="desc"> <p>An introduction to the study of physical organic chemistry, with special emphasis on bioorganic chemistry, bio-macromolecular structure, and biological sequence analysis.</p> </div>','CHEM 221 and CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9225,2025,68,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-370','<div class="desc"> <p>A continuation of CHEM 340, focusing on the interface between organic and inorganic chemistry.</p> </div>','CHEM 340 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9226,2025,1056,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-380','<div class="desc"> <p>An introduction to the study of organic synthesis.</p> </div>','CHEM 300 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9227,2025,69,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-395','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9228,2025,488,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/300/chem-397','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9229,2025,70,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/400/chem-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Chemistry majors.To be repeated both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9231,2025,489,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chem-chemistry/400/chem-499','<div class="desc"> <p>Independent study leading to an honors project. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9232,2025,71,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/100/chin-101','<div class="desc"> <p>Introduction to spoken standard Chinese (Mandarin), the pinyin romanization system, and the reading and writing of Chinese characters. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Chinese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9233,2025,491,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/100/chin-102','<div class="desc"> <p>Continuation of Chinese I. Conversation, reading, elementary composition; completion of basic grammar.</p> </div>','CHIN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9236,2025,72,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/200/chin-201','<div class="desc"> <p>A review of basic grammar. Reading and discussion of texts dealing with contemporary Chinese society and culture. Viewing and discussion of video programs. Composition writing and oral presentations.</p> </div>','CHIN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9237,2025,492,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/200/chin-202','<div class="desc"> <p>Continuation of CHIN 201.</p> </div>','CHIN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9238,2025,73,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/200/chin-272','<div class="desc"> <p>This seminar course will examine the rise of the martial arts novel (wuxia xiaoshuo) in the context of its historical and literary roots. We will focus on how the figure and chivalric code of the martial hero and heroine have persisted in the historical, literary, and popular imagination - through such works as Sima Qian''s historical biographies, <em>The Romance of the Three Kingdoms Outlaws of the Marsh</em>; Tang dynasty classical tales; Ming dynasty court-case fiction in the vernacular language; and Pu Songling''s classical strange tales written in the Qing period. We will also explore how the 20th century master of the martial arts novel, Jin Yong (Louis Cha), a journalist writing in exile in colonial Hong Kong, has captured the imagination of Chinese diasporic communities throughout the world and contributed to the rise of the transnational Chinese martial arts film. All readings and discussions will be in English. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9240,2025,817,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/200/chin-274','<div class="desc"> <p>This seminar course will explore ghosts and other disembodied beings in the Chinese literary tradition, from the earliest historical documents, philosophical texts, and Buddhist tales, to the Six Dynasties zhiguai records of the strange, the Tang chuanqi tales of the marvelous, and Ming dynasty vernacular fiction. We will focus on recurring motifs and archetypes which weave the supernatural into love stories, especially as manifested in two Qing dynasty masterpieces: Pu Songling''s <em>Strange Tales</em> and Cao Xueqin''s <em>The Story of the Stone</em>. Modern stories and film will also be examined for their adaptations of traditional motifs and archetypes. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9242,2025,1005,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/200/chin-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9244,2025,74,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/300/chin-301','<div class="desc"> <p>Reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Introduction to the use of literary style Chinese and idioms in public discourse. Developing advanced level oral-aural and essay writing skills.</p> </div>','CHIN 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9245,2025,1057,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/300/chin-310','<div class="desc"> <p>Advanced reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Oral presentations, academic style discussions, and writing of essays and narratives.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9246,2025,1058,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/300/chin-330','<div class="desc"> <p>A survey of representative works of short fiction and film by 20th century and contemporary Chinese writers and film makers. Topic and content of the course will vary from year to year according to three areas of focus: mainland China, Taiwan/Hong Kong, and transnational Chinese. Students will read and view original works and practice oral and written summaries, commentaries, discussion, and analyses in Chinese. Students will also read essays on literature and film in Chinese, with some readings in English. This course may be taken three times.</p> <p><strong>Female Who Writes and Who is Written</strong></p> <p>This course will examine the relationship between culture and society in China by focusing on the images of women represented in modern and contemporary cultural production, including literary and cinematic texts. By investigating the images of women in both literature and cinema from the twentieth century onward, this course will explore the development and transformation of the status of women in different sociohistorical periods of China, and discuss the ways in which cinema and literature feature women to address issues of gender, family, society, national identity, cultural memory, and so forth. In addition to representative literary texts, students will develop skills to interpret and analyze audiovisual media by watching the film adaptations of the assigned literary texts, and discuss how literary texts and cinematic media have both been used to construct and shape the cultural scene in Chinese society. <em>Core Requirement Met: Regional Focus</em></p> </div>','CHIN 301 (or above) or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9247,2025,2940,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/300/chin-338','<div class="desc"> <p>This course introduces the major genres and authors of the Tang and Song Dynasty (618-1279), generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry and the emergence of literati culture. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. This class will meet with CSLC 253 twice a week, and meet for an additional 85-minute session weekly to discuss the material in the Chinese original. Primary texts are in Classical Chinese, so proficiency in reading Chinese is required. Students completing the paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement. </p> </div>','CHIN 202 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9248,2025,495,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/300/chin-350','<div class="desc"> <p>Readings in short classical Chinese texts, from pre-Qin historical, philosophical, and literary works that are the sources of sayings still common in modern vernacular Chinese. Students will learn the grammar, structure, and vocabulary of classical Chinese (wenyan) and gain advanced proficiency in modern spoken (baihua) and literary (shumianyu) Chinese, through exercises in oral and written discussion and analysis of the use of classical Chinese thought and sayings in contemporary Chinese language and culture. Course offered every four years.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9251,2025,496,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/300/chin-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9252,2025,1205,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/400/chin-460','<div class="desc"> <p>This advanced level course will introduce students to the art, practice, and intercultural contexts of translating Chinese into English. The class will discuss the content, linguistic form, and cultural contexts of a variety of authentic examples of written Chinese, followed by practice in producing readable English translations. Original Chinese texts will include short stories, essays, and media. This course is open to both non-native and native speakers of Chinese who wish to develop their bilingual skills and intercultural literacy. Class discussion will be conducted in Mandarin, Chinese, and English. May be repeated once for credit.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9253,2025,3876,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/chin-chinese-studies/400/chin-493','<div class="desc"> <p>"Chinese language, literature, and culture": Senior comps directed research in Chinese Studies.</p> </div>','Instructor permission required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9257,2025,76,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/100/cogs-101','<div class="desc"> <p>An interdisciplinary introduction to the discovery of the mind through philosophical texts, psychological experiments, artificial intelligence, the study of nerve cells and neural networks, and investigations into language. The purpose of the course is to foster an appreciation of the wonder and complexity of minds and brains, both human and otherwise. Not open to seniors in Spring semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9258,2025,77,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/100/cogs-104','<div class="desc"> <p>This course provides a basic introduction to the nervous system. The course will include an introduction to how nerve and glial cells contribute to different brain functions. This course will also cover brain structures and systems and how they act to produce sensory experience, thought, emotion, and memory. Other topics might include: factors that affect embryonic development of the nervous system, and the effect of drugs, environment, stress, education, and age on the brain.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9259,2025,1684,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/100/cogs-111','<div class="desc"> <p>The average adult possesses over 50,000 concepts, ranging from physical concepts like "force" and "density," to biological concepts like "growth" and "reproduction," to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich, revise, and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive, developmental, and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9262,2025,1504,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-201','<div class="desc"> <p>This course provides students with a foundation to think critically about research in Cognitive Science and lays the groundwork for the original research that will be done in the senior year. We will examine primary literature, carefully considering the processes involved in moving from a general idea to a specific research question. We will consider the strengths and weaknesses of a range of approaches to studying cognition, with a focus on experimental design. The course will culminate in an original research proposal.</p> <p><br/> </p> </div>','COGS 101 ','COGS 201L ',NULL);
INSERT INTO course_descriptions VALUES(9263,2025,2325,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-220','<div class="desc"> <p>Are earthworms capable of making decisions? How do ants navigate their environment? Do dogs have an understanding of fairness? Questions about the mental states and processes possessed by non-human animals present particular problems of study: how do we determine whether, and to what extent, animals possess such abilities? This course will study the evidence for cognitive states and processes in non-human animals, focusing on careful and critical attention to the methods and techniques used to gather that evidence and on the considerations that go into interpreting that evidence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9264,2025,1006,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-230','<div class="desc"> <p>This course addresses the question: how can we understand the mind scientifically? We will explore answers to this question via a critical survey of neural and behavioral evidence bearing on the nature of core cognitive capacities, including perception, memory, emotion, decision-making, rationality, and consciousness. We will explore these sources of evidence in a comparative perspective, drawing on evidence of both human and (non-human) animal cognition, to more adequately characterize the general nature of cognition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9265,2025,1153,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-241','<div class="desc"> <p>As part of human cognition, our perception, production, and understanding of music has elicited many questions: what is music in relation to "sound"? Is music an evolutionary adaptation? What is the relationship of music and emotions or memory? Can music influence perception in other modalities? What is the meaning of music? Can music make us smarter? Is music a language? What is biological and what is cultural in the esthetics of music? This course will reframe many of these questions from the interdisciplinary standpoint of cognitive science, acoustics, music theory, and semiotics, to explore music as a cognitive process. Topics will include: the perception of pitch, timbre, rhythm, and localization; music and the brain; the cognitive aspect of the esthetics of music; the relationship between music and language in terms of their structures and neurological processing; music and memory; music and emotions; and music and meaning. We will also discuss the role music plays in cross-modal interactions, either in the real world or in films and multimedia art works.</p> </div>','Any Cognitive Science or Music class; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9266,2025,906,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-242','<div class="desc"> <p>Computational modeling provides important insights into how the mind/brain may work. We will examine three different approaches that have been used to provide insights into cognition: symbolic methods, connectionism, and probabilistic methods. We will use computer software to explore how these approaches work in practice. Specific applications, such as perception, language, and memory will be covered. The assumptions and limitations of each approach, as well as the metaphor of mind/brain as a computer, will be critically considered. This course has a mandatory laboratory component which will include both experimentation and computer programming. No previous programming background is required.</p> </div>','COGS 101 (may be taken concurrently), MATH 210 , MATH 214 , or PHIL 225 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9268,2025,2398,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-255','<div class="desc"> <p>The primary goal of this course is twofold: (1) to provide students, from a wide range of disciplines, with hands-on training to analyze a variety of data-sets relevant to their course of study, and (2) to provide them with the tools to understand the rhetorical form and function of different types of data visualizations. Students will consider how questions can be answered using data; learn how to analyze data appropriately; learn to design and present graphs that tell an easy-to-understand visual story, have high impact and are memorable, and critically consider the assumptions underlying accurate interpretation of analyses and visualizations. Students from any major are welcome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9270,2025,3874,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-260','<div class="desc"> <p>This class is an introduction todeaf communities and sign languages around the globe, with a focus on the analysis of American Sign Language (ASL). We will make an overview of the fundamental concepts of sign language linguisticsandinvestigate how sign languages parallel with spoken languages at different levels of the structure because they all draw on the same linguistic and cognitive capacities. We will also explore the differences in sign languages because they are signed and seen. This course will also touch on the disability as diversity and discuss recent development in the disability studies through the lens of deaf communities, including deaf identity, deaf history, and deaf culture as an important contribution to the diversity in the US.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9271,2025,3051,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-262','<div class="desc"> <p>This course will examine the multifaceted relationship between culture and cognition. How do our cultural and environmental contexts shape our perceptions, knowledge, and behaviors? How do specific aspects of a culture change the ways in which people acquire, store, and process information? What is the relationship between our culture experiences and our social identities? To what extent are our beliefs and knowledge structures culturally relative or universal? In this course, students will explore these questions and more using the tools of cognitive science. Topics will include conceptual development, knowledge organization, causal reasoning, cultural transmission, morality, trust, and cooperation.</p> </div>','COGS 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9272,2025,1641,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-265','<div class="desc"> <p>Art - be it visual, music, dance, or literature - is an extraordinarily powerful practice, driving much of our behaviors and engaging us physically, emotionally, and cognitively. This seminar will explore the various creative arts through the perspectives of Psychology, Neuroscience, and Philosophy. Topics will range from aesthetic foundations, historical dialogues between psychology and art, as well as the biological and evolutionary bases underlying aspects of creativity and art appreciation.</p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9273,2025,3255,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-270','<div class="desc"> <p>This course will cover key concepts in nervous system structure and function through the lens of the sensory and affective experience of pain. Students will gain a basic understanding of nervous system organization, evolutionary adaptation, neuronal mechanism of action, sensation and perception, plasticity, and top down processing through the examination of the neuroscience of pain and the clinical experience of pain and its treatment, including coverage of disparate pain treatment on the basis of race and gender. This course will also take an interdisciplinary perspective to pain, considering how it has been represented in literature and philosophy. Although there are no specific prerequisites, the course will include (optional) materials appropriate for students with a deeper background in psychology, biology, neuroscience, and/or cognitive science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9274,2025,3888,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-280','<div class="desc"> <p>This course will explore the neurological mechanisms that control eating &amp; hunger, drug addiction, sexual behavior, and the intersection of all of these topics. Each of these topics has direct impact to everyday life. However, the specific ways in which the brain controls each of these things tends to be underrepresented in neuroscience instruction. In particular, a key point is how all of these processes utilize highly overlapping brain circuits. In order to explore these behavioral phenomenon, this course will investigate brain reward and homeostatic pathways. In addition to lecture, students will acquire knowledge about these topics as well as neuroscience techniques used to explore them through student-led (and instructor-guided) discussion of primary literature. Some prior student experience with the brain via a cognitive science, psychology, or neurobiology course is warranted when taking this course.</p> </div>','Prior experience with the brain, through psychology, cog sci, or biology, would be helpful for keeping up sufficiently with this course''s materials. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9275,2025,1441,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-292','<div class="desc"> <p>Mechanisms of brain development, growth, neurogenesis, maturation, and changes that occur during life. Emphasis will be placed on current literature and studies done in non-human animals and humans. We will also talk about what it takes to maintain a healthy brain.</p> </div>','COGS 101 or COGS 104 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9276,2025,3473,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9277,2025,819,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-295','<div class="desc"> <p>This course explores a topic within the field of cognitive science. Topics vary by semester; past topics have included Intelligent Agents and Concepts. See the Department Chair for further information.</p> </div>','Any COGS course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9279,2025,3298,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/cogs-298','<div class="desc"> <p>COGS 298 introduces students to the basics of electroencephalography (EEG) methodology for cognitive neuroscience research. This is a project-based lab course in which students will learn to conduct an experiment using EEG from start to finish. Students will attain a conceptual and theoretical understanding of EEG as a neuroimaging technique, will learn to design and program an original EEG experiment, participate in EEG data collection, will learn to analyze and visualize EEG data, and will present their work in both oral and written form. Students will gain skills in experimental design, computer programming, data analysis, scientific writing and presenting scientific results. No prior experience with EEG or coding is necessary to succeed in this course. </p> </div>','BIO 130 , COGS 101 , COGS 104 , COMP 113 , PSYC 101 , or instructor permission No prior experience with research, EEG, or computer programming is necessary. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9280,2025,3253,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/200/copy-of-cogs-243','<div class="desc"> <p>Recognizing a face regardless of the angle, recalling the details of a birthday party years ago; we take for granted the complexity of the problems our brains solve on a daily basis. Do models used by cognitive scientists perform similar algorithms to those implemented in neural circuits honed over millennia of evolution? Students in this course will use disciplinary-specific scientific tools and strategies in a laboratory setting to observe cognitive phenomena. We will do this by designing experiments and collecting primary data, and students can expect to gain technical skills in problem solving, experimental design, and programming. Students will also analyze data to produce graphs, charts, or summary tables, as well as learn to break jargon down for communication to public audiences. Additionally, the course will include critical reflections on the scope, limitations, and broader impacts of computational and neuroscientific approaches to cognition.</p> </div>','COGS 101 (may be taken concurrently) or COGS 104 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9281,2025,78,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-301','<div class="desc"> <p>This course will address current cognitive science research as applied to learning and education. The concept of multiple intelligences, as well as strengths and weaknesses of individuals in acquisition of information, will be emphasized. We will also cover specific learning disabilities/differences and cognitive styles. Education minors only.</p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9282,2025,2585,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-303','<div class="desc"> <p>This seminar course will look at a topic in neuroscience from a multidisciplinary perspective. The course will focus on critical analysis of research studies and methodologies. May be taken more than once for credit as the topics will differ each semester.</p> <p><strong>Deep Learning</strong></p> <p>This course will cover current topics at the intersection of cognitive neuroscience and deep learning. Recent successes in deep learning and AI have hinted that networks of simple units can produce surprisingly complex behaviors, and these models often even mirror the coding properties observed in the human brain. However, unlike artificial agents, humans excel at thinking creatively and reasoning about cause and effect, allowing us to behave flexibly in novel and ambiguous environments. What neural mechanisms support these behaviors? Which of these mechanisms are necessary for producing analogous capabilities in artificial agents? We will gain insight into these questions by reading primary literature and algorithm development exercises. Previous experience in cognitive science, computer science, psychology, logic, mathematics, or biology is required for success in this course.</p> </div>','COGS 201 , BIO 268 , PSYC 200 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9283,2025,2544,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems, make decisions, draw inferences, attend to their environment, communicate, remember, and learn. Much of the material is applied to real-life settings.</p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9284,2025,2586,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-308','<div class="desc"> <p>In the second half of the 20th century, the new field of cognitive science came into existence. This course explores the developments in the history of philosophy, mathematics, biology, psychology, and computer science that culminated in this new science of the mind, including the theory of computation, from the work of Leibniz in the 17th century, the pioneering work on computing and programming by Charles Babbage and Ada Lovelace in the late 19th century, to Turing''s work in the early 20th century. We will explore how developments in both theoretical and applied computer science and logic led to the field of artificial intelligence and computational neuroscience, and we''ll explore the philosophical questions about the possibility and scope of machine intelligence. One prior course in cognitive science, philosophy, or mathematics is recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9285,2025,500,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320','<div class="desc"> <p>This course will introduce students to the biology of the mind. It will provide an overview of neuroanatomy and characterize the neural mechanisms supporting complex cognitive processes including vision, attention, consciousness, language, memory, learning, emotion, and action. We will also emphasize the importance of converging methodologies in studying the link between the mind, brain, and behavior. Methodologies we consider include: behavioral measures of cognition, neuropsychology, electrophysiology, anatomical and functional neuroimaging, single-cell recordings, and computational modeling. Laboratory sessions will allow students to obtain hands-on experience with these methodologies, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>','BIO 268 , COGS 201 , PSYC 200 , or permission of instructor ','COGS 320L ',NULL);
INSERT INTO course_descriptions VALUES(9286,2025,820,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320l','<div class="desc"> <p>Laboratory sessions will allow students to get hands-on experience, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>',NULL,'COGS 320',NULL);
INSERT INTO course_descriptions VALUES(9287,2025,1371,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> </div>','COGS 101 , four units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9288,2025,1059,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-330','<div class="desc"> <p>Language and cognition are intimately related. For this reason, Linguistics has had an extremely strong influence on Cognitive Science. This course studies language and linguistics in the context of Cognitive Science. We will address such questions as: how are language and thought related? How is language represented in the brain? How do we process language? To what extent is the human capacity for language innate? Is there a language of thought? What are the best ways to model language acquisition and language processing? We will cover some topics in traditional Linguistics and we will look at current research on connectionist and traditional artificial intelligence approaches to modeling language. Reading will include work by Chomsky, Pinker, McClelland, Rumelhart, Fodor, and Elman.</p> </div>','COGS 101 or LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9289,2025,3889,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-338','<div class="desc"> <p>This class provides an investigation of the cognitive bases of language acquisition, informed by state-of-the-art research in psychology and linguistics in the study of first language acquisition. We will concentrate on the development of linguistic structure, including phonological, lexical, morphological, syntactic, and pragmatic development. Universal aspects of development will be discussed, as well as a variety of cross-linguistic phenomena. Other topics include theories of language learning (parameter-setting, maturation), learnability, atypical language development, and bilingualism.</p> </div>','Prerequisite: COGS 330 or LING 301 or PSYC/LING 351 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9292,2025,3890,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-346','<div class="desc"> <p>This course will cover current topics at the intersection of cognitive neuroscience and deep learning. Recent successes in deep learning and AI have hinted that networks of simple units can produce surprisingly complex behaviors, and these models often even mirror the coding properties observed in the human brain. However, unlike artificial agents, humans excel at thinking creatively and reasoning about cause and effect, allowing us to behave flexibly in novel and ambiguous environments. What neural mechanisms support these behaviors? Which of these mechanisms are necessary for producing analogous capabilities in artificial agents? We will gain insight into these questions by reading primary literature and algorithm development exercises.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9294,2025,2674,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-390','<div class="desc"> <p>A recent replication crisis in the sciences has led to large-scale questioning centered on scientific integrity. Scientific integrity refers to 1) honesty while conducting and interpreting research, and 2) to developing conclusions that are unbiased and valid. Contemporary practices in research design and statistical analysis (e.g. p-hacking), lack of transparency, and political bias are all threats to scientific integrity. This course introduces and engages students conducting directed research with a faculty member in the Cognitive Science Department in best practices and ethical concerns in scientific research through evaluating primary research and commentaries within cognitive science and statistics, as well as by evaluating and critiquing the literature in their area of research focus. Students are expected to commit to a minimum of 8 hours of course-work each week including a course meeting, assigned group work, readings, and independent research. This course is graded CR/NC only.</p> </div>','COGS 101 , COGS 201 , and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9295,2025,821,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-395','<div class="desc"> <p>Directed research with a faculty member.</p> </div>','COGS 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9296,2025,501,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/300/cogs-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9297,2025,80,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/400/cogs-490','<div class="desc"> <p>This course will support senior Cognitive Science majors as they conduct original research as part of their Senior Comprehensive requirement. Open to Cognitive Science majors and seniors only.</p> </div>','COGS 101 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9298,2025,2545,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cogs-cognitive-science/400/cogs-495','<div class="desc"> <p>Students with substantial directed research experience will conduct an independent research project of their own design, with guidance from a faculty mentor. Students are expected to devote a minimum of 6 hours per week to their project, and will present their results in a colloquium open to the campus community. Open only to seniors and by permission of the instructor.</p> </div>','COGS 201 or COGS 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9300,2025,2947,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-101','<div class="desc"> <p>Throughout their careers, students in Computer Science will have the opportunity to affect society through the technologies that they create. Yet technology is not created in a vacuum, but rather is a product of the ingrained assumptions of its creators, and the societies that structure these assumptions. When working with the tools of Computer Science, students will face traces of the field’s racist, sexist, homophobic, and imperialist history, and will have to decide how to work with or challenge these parts of the field. This course prepares students to work for justice and equity in technology and society by facilitating conversations about the sometimes-oppressive history and impact of Computer Science, and by uplifting voices that have historically been marginalized within the field. By the end of the course, students will be able to analyze and discuss technology within its broader context, and be able to use the tools of Computer Science to subvert the unjust structures the field has inherited.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9302,2025,1511,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-131','<div class="desc"> <p>Computer Science is about the organization of information and the design of processes that use it. This course teaches students to think computationally - how to break down processes into components that can then be fully described - and to acquire other habits necessary for a computer scientist. Students should come out of the course able to write simple, but complete, programs of their choosing, and should also be able to diagnose problems in unfamiliar programs.</p> </div>',NULL,'COMP 131L ',NULL);
INSERT INTO course_descriptions VALUES(9303,2025,2648,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-146','<div class="desc"> <p>Comprehensive study of measures of central tendency, variation, probability, the normal distribution, sampling, estimation, confidence intervals, and hypothesis testing. Introduction to use of technology in statistics. Real-life problems are used to illustrate methods. Weekly lab. Not open to students who have completed or are currently enrolled in PSYC 201, BIO 268, MATH 150, or any Mathematics course above 200.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9304,2025,2508,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-149','<div class="desc"> <p>This course provides the mathematical theory which underpins Computer Science, including: number systems; variable types and formats; logic; set theory; graph theory; linear algebra; and important numbers, functions, and relations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9305,2025,81,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-155','<div class="desc"> <p>Principles of web design. Tools and techniques of elementary web programming, including: HTML, XHTML, CSS, JavaScript, HTTP, SSL, XML, and SQL. Introduction to network architecture and programming.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9306,2025,2948,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-181','<div class="desc"> <p>In this course, students will gain additional experience in object-oriented programming in Java. Students will work in pairs and small groups on multiple programming projects. Topics will include test-driven development, debugging, and source code management, but focus will be on writing maintainable and efficient code. This course is intended to prepare students with some programming experience (COMP 131 or equivalent) for more advanced programming courses.</p> </div>','COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9309,2025,1581,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/100/comp-197','<div class="desc"> <p>Directed individual study. Permission of instructor and department chair required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9310,2025,1649,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-229','<div class="desc"> <p>We begin with topics found in advanced programming. In particular, topics from object-oriented programming and how this differs from procedural programming. We then move on to the study of dynamic data structures, such as linked lists, stacks, queues, trees, heaps, graphs, hash tables, sets and more. Completion of this course opens up the remainder of the Computer Science classes and is required for minors. Common themes that run throughout this course are: (1) implementation of the abstract data types, and (2) spatial and memory consideration and analysis.</p> </div>','COMP 131 or COMP 181 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9311,2025,2957,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-230','<div class="desc"> <p>As humankind stares down a number of unprecedented global challenges, the need for creative, radical thinking is imperative. In this interdisciplinary studio, students will develop a series of detailed and speculative projects inspired by boundary-pushing artistic and technological practices. The course will examine precedents from contemporary art, media, engineering, performance, design, and technology that offer responses to a wide range of “what-if” scenarios. The primary goal of the class will be to guide students as they develop a methodology for making creative and responsive work—one that relies on provocation and imagination as driving forces. Class projects will be designed to develop critical thinking and research skills, art-making and visual communication capabilities, and will call for speculative, even fantastical, responses to complex sites and situations. Technological and data-driven approaches, including data analysis, modeling, and scenario planning, will be integrated into the class assignments, encouraging cross-disciplinary collaborations between computer science and media arts students. Instructional assignments will explore a range of materials, scales, and research methods, and will encourage students to develop their abilities to hone and express innovative responses to complex societal and relational questions. The final series of class projects will address the uncertainty of climate change as a contextual framework, and final proposals may range from site-specific art installations to new applications for robotics; from creating futuristic soundscapes to designing experiences in VR. Site visits and guest lecturers will extend students’ connections with selected Los Angeles sites and their contexts, the understanding of a broad set of perspectives and values, and real-world examples of collaborative, cross-disciplinary projects. Not open to First Year Students. Permission of instructor required.</p> <p>Sub-field: INTERFACES</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9312,2025,2509,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-239','<div class="desc"> <p>This course covers the basics of how a computer works, focusing especially on the hardware-software interface. Students will learn about the limitations of the physical computer, and that it may not be possible to ignore the lower-level hardware when designing efficient software. Students will learn to implement programs in Assembly language and C/C++. They will investigate the main components of the computer and it''s processor and master the binary language of computers. They will learn important design concepts such as memory hierarchy and parallel computing, and have a brief encounter with principles of digital logic. This is a required course for the Computer Science major. Includes one 1.5-hour lab period per week.</p> </div>','COMP 131 , COMP 181 , or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9313,2025,2956,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-242','<div class="desc"> <p>This course is a survey and a series of hands-on workshops exploring the critical, speculative, and also practical ways of applying machine learning to working with sound and musical composition. In particular, we will be focusing on using Machine Learning models that learn from input data to optimize towards a certain task. In this class, we will look at the uses of ML as a way to deepen our relationship with sound and music production by focusing on machine and human collaboration rather than ML models as solely an open "toolbox" for new sound techniques. This class will learn how to organize and work with large sound datasets, generate new raw audio with neural networks, work with existing plug-ins that have machine learning capabilities, as well as generate midi and compositional structure by training our own AI models. No prior programming experience is necessary.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9314,2025,2539,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition.</p> <p><span>Sub-field: </span><strong>INTERFACES</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9315,2025,2737,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-277','<div class="desc"> <p>Video games are one of the newest forms of media, and offer tremendous promise for both entertainment, storytelling, and education. Starting from the text-based adventures of the 1970s to the billion-dollar industry today, students will learn how to use psychology and game mechanics to create compelling narratives, as well as gaining a glimpse into large-scale software development.</p> <p>Sub-field: INTERFACES</p> </div>','COMP 131 , COMP 181 , or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9317,2025,2869,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/200/comp-295','<div class="desc"> <p><strong>Automation: Politics and Aesthetics</strong></p> <p>In the course âAutomation: Politics and Aestheticsâ students will examine âautomationâ in capacious historical, geographical, and conceptual senses. In dominant United States-based discussions of these today automation is described as something that is produced by Silicon Valley, or happens to âAmericanâ workers, or takes place in direct interfaces between a âuserâ and a âcomputer.â The course will instead meet Occidentalâs Global Connectionsrequirement that students âdevelop a global, transnational and/or comparative understandingâ by asking them to reconsider both the geographies of automation as well as the artists and theorists who have put automation at the center of their work. One of the courseâs guides for this will be Kate Crawford who in the book <em>Atlas of AI </em>and the art work <em>Anatomy of AI</em> (with Vladan Joler) shows how immediate AI interfaces actually mobilize global infrastructures. We will also look at work by, for example, Louis Chude-Sokei about how 19<sup>th</sup> popular culture compared early automatons and enslaved African Diasporic peoples, as well as how contemporary artists like the Raqs Media Collective, or filmmakers Saul Williams and Anisia Uzeyman and their movie <em>Neptune Frost, </em>look at how automation involves contemporary factory workers in South Asia as well as coltan miners and computer programers in East Africa. Alongside this, the course will look at how automation has been the focus of work by U.S.-based artists and theorists of the 1960s and today like Robert Morris and Anika Yi, and Shulamith Firestone, Neda Atanasoski, and Kalindi Vora, andin doing so ask students to make connections between the local and the global and the present and the past, and to consider how âautomationâ is always connected to questions of social difference and economics.<em>Additional Core Requirement met: Global Connections. Same as ARTH 295 with the same subtitle.</em></p> <p><strong>Computing in Real Life Internship</strong></p> <p>Students will work with LA-based non-profits such as STEAM:CODERS, a Pasadena-based organization that teaches local middle and high school students to program, or the Association for Women in Mathematics, a national organization that promotes women in computation. Students will complete weekly reflection papers and a final presentation describing what they have learned about computation IRL. <em>Open only to students enrolled in the Computing IRL semester.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9319,2025,2618,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-313','<div class="desc"> <p>The key to the animation and videogame industries is the ability to display simulated worlds in real time. Starting with representing 3D space, this course will teach students the data structures and algorithms, such as quadtrees, texture mapping, and ray tracing, to create photorealistic images.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9320,2025,2858,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-319','<div class="desc"> <p>Knowledge Representation and Reasoning is the area of Artificial Intelligence concerned with how knowledge can be represented and how automated systems can reason about that knowledge. In this course, we will learn how to use symbolic notations to represent knowledge, including how to represent objects, events, time, space, and language. We will also learn how to use automated reasoning systems to manipulate these representations and derive new knowledge. This will be a hands-on course in which we apply concepts from philosophy, psychology, and cognitive science to build systems that can reason about real-world problems.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 or COGS 242 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9321,2025,2784,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 131 , COMP 181 , COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9322,2025,2711,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-331','<div class="desc"> <p>The wealth of textual information online and elsewhere makes the ability for computers to understand and generate text particularly valuable. This course will explore both the traditional, linguistic approach to understanding language, as well as modern information retrieval and statistical big data approaches. Topics include information retrieval, search engines, parsing, Markov models, and knowledge representation.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9323,2025,1651,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-337','<div class="desc"> <p>Most other computer science courses use programming languages as a tool for expressing algorithms; this course will examine the programming languages themselves and their implementation. Over the semester, students in this course will build an interpreter for a new language, and in the process be introduced to topics such as parsing, closures, type systems, and lambda calculus.</p> <p><span>Sub-field: SOFTWARE</span></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9324,2025,2547,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-340','<div class="desc"> <p>This course focuses on the process and technology behind making intuitive and useful websites and the techniques for determining the effectiveness of the products, including prototyping and user testing. Students will also explore how principles of attention, perception and cognition relate to user experiences.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 , COMP 181 , COMP 229 , or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9325,2025,2506,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-347','<div class="desc"> <p>Many recent advances in artificial intelligence are not in symbolic systems, but in statistical machine learning and data science. This course offers a balance between the theory and practice of data science, from collecting and understanding the data, to developing supervised and unsupervised models (such as linear regression, support vector machines, K-means and Gaussian mixture clustering, principle component analysis, neural networks), and finally interpreting the predictions and their limitations. Discussion of potential bias in the real-world applications and implementation of machine learning algorithms will be included.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 and ( MATH 210 and MATH 214 , or COMP 149 ) and ( COMP 146 or MATH 150 ) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9326,2025,2785,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-349','<div class="desc"> <p>Robotics offers one of the most integrating domains for computer science. Creating a working, human-facing robot brings together hardware and software, artificial intelligence and human-computer interaction. Topics include Simultaneous Localization and Mapping (SLAM), path planning, object recognition, basic mechanics, and social robotics.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9327,2025,2651,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-352','<div class="desc"> <p>This course discusses the theoretical foundations of computing and the limits to computation itself. Topics include state machines and automata, general recursive functions, and their relationship to the Church-Turing thesis. The course may also survey decidable and undecidable problems, as well as “hard” (NP-complete) problems and what makes them hard.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9328,2025,1324,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-353','<div class="desc"> <p>An introduction to information theory that will focus on: (1) data: transmission, storage, lossless data compression (such as ZIP and LZW), lossy data compression (found in JPG or MP3 formats), channel capacity; (2) coding: optimal codes, error correcting codes, the several coding theorems of Claude Shannon; (3) measures of information: entropy, relative entropy, relation between entropy and information content; and (4) application topics that vary from year to year and might include: signal processing, image processing, pattern recognition, cryptography and data security, quantum computing, data analysis, and more.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 149 , or MATH 210 and MATH 214 ; COMP 146 or MATH 150 recommended ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9329,2025,2859,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-355','<div class="desc"> <p>This course will teach students both front-end and back-end techniques necessary to build web applications. Students will learn how to make interactive websites, how to structure and manage content for websites in databases, and how to create data-driven web applications.</p> <p>Sub-field: <strong>SOFTWARE</strong></p> </div>','COMP 229 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9330,2025,2786,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-357','<div class="desc"> <p>Much of the power of computers is that they are not individual machines, but units on a network that can exchange information. This course starts with the transmitting binary electrical signals, then builds up to the TCP/IP stack and the algorithms involved, and finally current research questions in the field.</p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9331,2025,2329,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-367','<div class="desc"> <p>The largest programming projects are completed by multiple computer scientists working together. Clients across Eagle Rock and the Oxy community will propose problems with computational solutions, which we will complete in teams as a semester long-project. Using standard tools, such as version control, we will apply the principles of user-centered design to software: understanding the needs of the client, developing software, and testing the product with the user, before repeating the cycle. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 131 , COMP 181 , or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9332,2025,2588,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-373','<div class="desc"> <p>Any large amount of data, such as that stored by Google or Facebook, requires specialized algorithms to ensure consistency and efficient access. From relational models and SQL to newer graph databases, students will understand how to represent entities a domain with rows in a database, culminating in a project that uses this knowledge in a real-world setting. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9333,2025,2787,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-379','<div class="desc"> <p>An operating system ties together the hardware and software components of a computer. For interested students, this will likely be the final step to completely understanding what happens when code is executed. Topics include virtual memory, file systems, process management, parallel computing, and others. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9335,2025,2713,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-389','<div class="desc"> <p>Security on the internet is fundamentally based on the mathematical properties of the algorithms we use to encrypt our data. This course teaches students the theory behind these algorithms and how future advances such as quantum computing may affect current standards of security and privacy. Topics include ciphers and frequency analysis, private and public key cryptography, randomness, and quantum cryptography.</p> <p>Sub-field: <strong>SECURITY</strong></p> </div>','COMP 149 , or MATH 210 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9336,2025,2510,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-390','<div class="desc"> <p>This course focuses on responsible conduct of Computer Science. Students will explore the effects of technology on the modern world, including issues of electronic voting, personal security and privacy, intellectual property, and others. This course will culminate in a research paper on one of these topics, examining the technical background, as well as the social forces that contextualize the issue. Students should have an understanding of the challenges of writing software, and why certain questions are computationally difficult (that is, require significant time/memory). </p> </div>','COMP 101 , COMP 229 , and one 300-level or above COMP course ','A second 300-level or above COMP course',NULL);
INSERT INTO course_descriptions VALUES(9337,2025,3272,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-393','<div class="desc"> <p> Students engage with open problems in an active area of faculty research. May be repeated once for credit. Instructor permission required.</p> </div>','COMP 131 or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9338,2025,1689,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-395','<div class="desc"> <div><p>Topics vary semester to semester.</p><p><strong>Interactive Systems for Enhancing Movement</strong></p><p>This class applies computer science in the context of interactive systems to enhance human activities that involve movement, such as dance or sports. The course will go through examples of how sensors are used in diverse physical activities, including how to get movement signals through user-studies, how to evaluate the results, how to process the signals, and how to classify and determine if a movement is "correct" or "incorrect". Students finish the class by designing and evaluating their own projects in an activity that they are passionate or curious about.</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p>Prerequisite: COMP 131</p><p><strong>Modeling and Simulation</strong></p><p>A computer model is a hypothesis, formulated with a specific purpose in mind and represented as a computer program, about some aspect of concrete or imagined reality. A model can be "brought to life" through computer simulation. Computer models play an important role in business and policy as well as in engineering and the social and natural sciences, and we interact with them on a daily basis whether we realize it or not. These models, the nature of the "knowledge" they provide, and the implications of their use are the subjects of this course. An introductory familiarity with computer science is enough to build and work with simple computer models, valuable in themselves, that can also form the building blocks of more complex models. Focusing on these simple models, this hands-on course will address model-building, model fitting and validation using data, and model simulation for prediction and decision-making. At each of these stages we will also study questions of approximation and bias, and their implications. Examples will be drawn from a wide range of phenomena but will not require prior expert knowledge.</p><p>Sub-field: SOFTWARE</p><p>Prerequisites: COMP 131</p><p><strong>Data Mining</strong></p><p>This course covers computational approaches to uncovering information and patterns in data. Students will learn techniques for visualization of numeric and non-numeric data, data preprocessing, pattern extraction, clustering, and text mining. These techniques will be linked to human perception and other methods for evaluation.</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p><strong>Abolish Silicon Valley?</strong></p><p>The tech industry is known for well-paying jobs that offer the opportunity to work at companies making bold claims about their contribution to social betterment. Yet, those job benefits are only available to certain workers and "tech" is increasingly associated with income inequality, automated job loss, algorithmic bias, surveillance, the commodification of everyday life, and ecological damage. This course borrows its title from Wendy Lui''s recent book on her experience as a tech worker and will ask students to (re)consider the politics of tech today, their own potential place in the tech industry, and alternatives to the current organization of techno-capitalism.</p><p><strong>Computer Architecture</strong></p><p>This course is intended to provide a foundation in performance programming and computer architecture. Students will better understand how software interacts with hardware and how trends in technology, applications, and economics drive changes in computer architecture. The course will cover the following topics: caches, virtual memory, memory system, parallelism, pipelining, superscalar, speculative out-of-order execution, vector, VLIW, simultaneous multithreading, graphics processing units, chip multi-processors, and domain specific accelerators. Students will read research papers on the topics described above. We will use processor simulators to explore design choices relevant to each of these topics. The objective is for you to understand all major concepts used in modern CPUs at the end of the class.</p><p>Sub-field: SOFTWARE</p><p>Prerequisites: COMP 239</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9339,2025,506,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/comp-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9340,2025,1650,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-317','<div class="desc"> <p>We study algorithms from the point of view of efficiency and complexity. Having studied data structures, we now see how to apply algorithms to these structures to optimize their effectiveness. We examine algorithms in terms of time and memory allocation considerations. We will apply this background to a subset of the most important algorithms used in the sciences, various media, and business. We will study effective algorithm design, and give a brief introduction to computational complexity and computability, as well as parallel processing. Selected topics and applications from graph theory, linear algebra, numerical analysis, data compression, encryption, and large-scale problems from Mathematics and the sciences.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 229 , and COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9341,2025,2712,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-371','<div class="desc"> <p>Smartphone apps, in their limited computational power and radically different form factor, impose new constraints and challenges different from the development of other software. In this class, students will be introduced to mobile architecture and related concepts such as monetization, privacy, analytics, and cross-platform development.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 and COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9343,2025,2540,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/comp-computer-science/400/comp-490','<div class="desc"> <p>This course will support senior Computer Science majors as they conduct projects as part of their Senior Comprehensive requirement. Students must have senior standing to enroll.</p> </div>','COMP 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9347,2025,3013,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-111','<div class="desc"> <p>This topics course is a component of the Multicultural Summer Institute (MSI). Different topics may satisfy different Core requirements. Open only to incoming first year students accepted into the MSI program.</p> <p><strong>(Im)migrant Communities of California</strong></p> <p>This course offers students the opportunity to analyze the sociohistorical, legal, and cultural tensions surrounding various (im)migrant communities in California. Students will explore the various waves of (im)migration across time to understand the diverse communities of California. Students will also build critical and interpretive capacities through the examination of state policies, statistics, and various historical and empirical studies. Additionally, through the construction and revision of several expository, research-based writings on immigration, students will hone their writing, argumentation, critical thinking, and presentation skills. <em>Core Program Requirement Met: United States Diversity (CPUD).</em></p> <p><strong>Imagining The Future</strong></p> <p>This course on Anglophone literature, postcolonialism, and the African diaspora proposes to critically investigate the concept of time. In particular, we will examine how time provides a crucial framework for how we imagine the future. We will take the seemingly self-evident concept of time and critically examine its intellectual history to consider how time serves a crucial function as a means of ordering our cultural, economic, and political ideas as well as our individual lives. Frameworks of history, modernity, and futurity rely on concepts of development and progress that are related to broader ideas of race and sexuality. In what ways do historical representations of time, development, and progress structure how we imagine the future? On whose behalf is progress being imagined? Where is progress located? What are the ideals of the future? Whose pasts are connected to the futures that we privilege? In considering these questions, we will examine a range of novels, films, empirical studies, and cultural theory that provide a complex portrait of how the future is imagined, especially from the perspective of those scripted out of its dominant narrative. We will engage with critical and literary approaches including Afrofuturism, queer futurity, the developmental novel, economic models, and science fiction.</p> <p><strong>Mutual Aid: Literary Representations of Relief and Collective Care</strong></p> <p>This course considers how literature deepens our understanding of "mutual aid," one of the most pressing themes in today''s political, popular, and academic conversations. The course asks, is mutual aid merely a short-term practice during mass emergencies or does it provide an alternate viewpoint for communal self-reflection and structural transformation? Can we think about using the principles of mutual aid to make lasting changes in social relationships and political structures? </p> <p>In this class we will use the concept of mutual aid to break down traditional binaries between surviving and thriving or pragmatism and idealism. We will think through the utopian ideal of mutual aid as a possibility for real political and social intervention. The literary works we will read allow us to imagine how the seemingly impossible becomes possible through the mundane uses of mutual aid. In addition to reading memorable works of literature in the historical contexts of Black and Brown and queer communities, this course will devote consistent attention to the mechanics of writing persuasive thesis-driven essays, an essential skill for succeeding at Occidental. Readings will include Richard Wright’s short fiction “Down by the Riverside,” William Still’s compilation <em>The Underground Railroad</em>, and Shani Mootoo’s <em>Cereus Blooms at Night</em>. <em>Core Program Requirement Met: Global Connections (CPGC).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9348,2025,3057,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-112','<div class="desc"> <p>The Engaged Reflections on Social Justice (ERSJ) required component of the MSI program links academic content to diversity dialogue frameworks to help students cultivate the knowledge, skills, and attitudes associated with effective classroom engagement, socially responsible leadership, community and cohort development, and conflict resolution while also promoting practices of self and community care. The ERSJs serve as an important foundation for students to understand power and their relationship to the systemsthat undergird injustice and disparate outcomes. Self-awareness, awareness of others, and defining leadership for social change are the three primary themes that will connect the various topics we will cover in the seminar. Only open to first-year students.</p> </div>','CORE 111 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9349,2025,3852,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/copy-of-core-117','<div class="desc"> <div><p>This course examines the role of entrepreneurs in generating replacements for the status quo. Throughout this course, we''ll focus on entrepreneurshipâs intersection with citizenship in the context of Los Angelesâa city filled with diversity and innovation.</p><p><br/></p><p>Weâll take a multidisciplinary approach to understanding entrepreneurship across domains, including commerce, culture, and society. We''ll examine how entrepreneurs navigate change differently, their motivations to start new ventures, the impact of policies and norms on founders, the dynamics of entrepreneurial ecosystems, and the entrepreneurial potential of urban environments. Through interaction and collaboration, you''ll gain knowledge and analytical skills for understanding entrepreneurial activity.</p><p><br/></p><p>We''ll also examine emerging ventures poised to shape Los Angeles in the coming years. By developing an informed perspective on these loci of transformation, you''ll become better equipped to take an authentic position on relevant debates. Through these case studies, you''ll be empowered to contribute meaningfully to the entrepreneurial landscape as participants in a new venture or as a stakeholder in their ends.</p><p><br/></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9353,2025,3316,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-227','<div class="desc"> <p>This class is an introduction to the historical art of letterpress printing using design elements with text and image. Students will complete a collaborative artist book with hand binding and original imagery using typographic design, hand typesetting, and letterpress printing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9355,2025,2867,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-95','<div class="desc"> <p>The goal of this course is to provide students with academic, social and personal skills including reading and study strategies, procrastination and time management, and more, to aid in students'' academic success and integration in their first year of college. </p> <p>Through workshops and guest lectures, students will learn how to access campus resources and opportunities, to help them build social capital and community within the Oxy campus. This course emphasizes student development and provides specific support for first-generation students. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9356,2025,2728,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-96','<div class="desc"> <p>This course is designed to expose students to mathematics and science to broaden their awareness of the research questions asked in these disciplines and to introduce skills and ideas scientifically shown to improve persistence in college especially in science and math majors. Students may acquire one semester unit of credit for attending eight on-campus events during a semester. Certain seminars and class meetings will be mandatory; students will select additional events from a list of events provided each year by the instructor. A short two-page paper is due on the last day of class. This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9357,2025,2903,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-97','<div class="desc"> <p>This course is designed to expose students to some of the many cultures of the world, to prepare students for a future in the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one semester unit of credit for participating in eight "field experiences" in their local area. Students will select these from a list of destinations provided by the course instructor and are responsible documenting each field experiences using Moodle. Students will also be required to submit two short response papers related to their field experiences.</p> <p>This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> <p>Students may take this course twice, for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9358,2025,2723,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/core-98','<div class="desc"> <div><div><p>This course is designed to expose students to some of the many cultures of Los Angeles, a vibrant microcosm of the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one unit of credit for participating in eight off-campus "field experiences.â Students will select these from a list of destinations provided by the course instructor and are responsible for documenting each field experience using Canvas. Students will be required to submit at least two short response papers related to their field experiences. This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements. Students may take this course twice, for a maximum of two units being applied toward the degree.</p><p><br/></p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9359,2025,2724,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/core-core-program/courses/copy-of-core-99','<div class="desc"> <div><p>This course is designed to expose students to the diverse array of artistic events that are held each semester on the Occidental campusâfrom musical and theatrical performances to art openings and film screenings and more. To receive credit, students must engage with at least eight arts events during the course of the semester and complete two short reflection papers. Students will select these events from a list available on the courseâs Canvas page. This course is graded CR/NC and does not fulfill any major, minor, or Core requirements. Students may take this course twice, for a maximum of two units being applied toward graduation.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9360,2025,2653,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-107','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though very different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9361,2025,2546,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-108','<div class="desc"> <p>Taught in English. This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9362,2025,1507,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-109','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables, and riddles, to anecdotes, jokes, short stories, and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include: Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin, and Twitter. All readings and discussion in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9363,2025,2701,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-112','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes from the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9364,2025,3335,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-113','<div class="desc"> <p>Although the first volume of the Grimms’ Children Stories and Household Tales was published more than 200 years ago, their fairy tales continue to enchant contemporary readers. In this course we will not only study the Grimms’ fairy tales themselves and rediscover their enduring magic, but also take a look at their origins and their social, ideological, and political contexts in 19th-century Europe. We will work with fairy tale theory (narrative, psychoanalytic, historical) and discuss the function of the tales for adult communities as well as their status as children’s literature. Alongside the “original” Grimms’ tales—a concept that we will discuss—a major portion of the course will engage t he legacy of the fairy tales and the way they have been<br/> appropriated by others, particularly from a critical, feminist perspective.</p> <p><br/> Points of emphasis will include: how writers in the first half of the 20th century politicized the tales in the battle for societal change during the time of the Weimar Republic and Nazi Germany; how the tales were reinterpreted in different national traditions and historical periods; how the fairy tale becomes a mass culture icon in Disney’s film versions; and how contemporary writers like Margaret Atwood continue to employ fairy tales to question the construction of gender and carve out new possibilities for relating to one another.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9366,2025,2735,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-115','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus, by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9367,2025,2821,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-116','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and fallibility. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in-depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9368,2025,2893,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-118','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process-oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9369,2025,1685,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-120','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus, begins Ovid''s <em>Metamorphoses, </em>whose programmatic opening stanza links the birth of the world, from formlessness and chaos, to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotica; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9370,2025,3058,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-122','<div class="desc"> <p>After the end of WWII, the generation of what would become known as the 68ers found themselves in a precarious position. They came into adulthood to realize that their parent’s generation were if not perpetrators then at least accomplices to one of the gravest genocides in human history, that they had enthusiastically endorsed a fascistic maniac, that the country they inhabited stood in ruins, bombed to the ground morally and physically, and that they now stood at the epicenter of the cold war, half capitalist, half communist. From the perspective of the 68ers, the worst of all was that there had been no cultural reckoning. With the conclusion of the Nuremberg trials and the prosecution of the elite Nazi administration, the majority of the population seemed content to simply to forget. For the 68ers that was not an option. Rather than view the WWII and the Holocaust as an aberration and horrific exception to German culture, the youth of the 68er generation demanded a revolutionary reevaluation of everything German. They asked: What factors, economic, social, cultural, and historical, led to this catastrophe? How can we come to terms with this past? And what vision of a transformed future could replace the old? The answer to these questions involved a three-step approach. A radical critique of the past and the structures of nationalism, patriarchy, heteronormativity, racism, and capitalism, which they believed were the foundational underpinnings of German fascism. Active political dissent that demanded change and culminated in the domestic bombings of the left-wing group the Red Army Faction. And a total re-conception of the norms of society, sexuality, and selfhood perhaps best represented in the Love Parade and the drugs, sex, and radical experimentation that fueled the raves and Berlin techno scene after the fall of the Berlin Wall.</p> <p>This course will investigate the transformations of postwar German society in the literature, philosophy, film, photography, and art of the time. We will focus on the social critiques of the Frankfurt School of Critical Theory, political resistance in both the communist East and capitalist West Germany as well as the life in and relationship between the two, and the utopic visions of the postwar German left as well as the success and failures of this radical political movement. Readings and figures may include: Adorno, Horkheimer, Marcuse, Deleuze, Foucault, Crista Wolf, Max Frisch, The Baader-Meinhof Complex, Rainald Goetz, Anselm Kiefer, Helene Hegemann, and Felix Denk.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9371,2025,3315,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-130','<div class="desc"> <p>Do we live in the era of post-truth? Is everything just another piece of propaganda? Whom do we trust and why? </p> <p>Postmodern theory offers us powerful resources to criticize and take down the houses of totalizing ideologies, but many of its most important conceptual tools have been co-opted and are now used to oppress. Postmodern propaganda corrodes the relationships of trust that connect us, and makes us feel isolated and powerless. It taps into our fears and phobias to destroy not only the reality around us, but also our humanity. The organized lies of the 21st century aim to confuse and disorient, but also (and this is where the greatest danger lies) make us cynical. Several philosophers and writers from Eastern and Central Europe, who had first-hand experience of Western European “demi-Orientalism,” Russia’s imperialism, and Soviet totalitarianism, offer an antidote to this postmodern condition. </p> <p>In this course we will read French theorists such as Deleuze and Derrida and their counterparts from Eastern and Central Europe: Havel, MiÅosz, Mamardashvili, Venclova, and others. Several other philosophers and writers—such as Plato, Arendt, Kundera, Orwell, Klemperer, and Platonov—will help us think about truth, trust, and propaganda.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9372,2025,1642,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-131','<div class="desc"> <p>The worldview and beliefs of the early Slavs, particularly the Eastern Slavs, were a complex synthesis of influences: Indo-European mythology, Central Asian shamanism, Scythian animal worship, and, ultimately, a "paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600, in order to understand how these people viewed the world, and how this affected their lives and the development of Slavic culture. Communal village life, legends, folk genres and mythology, their sources, and their legacies, are examined. There is a close study of the phenomenon of the vampire, following its evolution from the Iron Age into 18th century Serbia, as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined, as well. In addition to analytical and historical texts, readings include tales of supernatural beings and phenomena, as well as testimony concerning encounters with the supernatural.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9373,2025,1508,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-132','<div class="desc"> <p>Many of Russia’s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements, while at the same time creating some of the most memorable texts of the 20th century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin. The course will introduce students to modern Russian literature, while, at the same time, will examine how Russian writers used science fiction in a completely different manner than Western writers. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9374,2025,3837,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-133','<div class="desc"> <p>There are two fundamental philosophical positions that try to describe our relation to others. The one posits that I am different from you. The other assumes the fundamental unity of human and other beings. Both of these positions lead to serious difficulties. If I am fundamentally different from you, I run the risk of alienation, and confront the impossibility of knowledge. If I begin with the assumption of oneness, I encounter the difficulty of distinguishing myself from you, and the impossibility of agency.</p> <p>Is there a third way that avoids these problems? Could we re-imagine relationships among humans and other beings in a way that preserves a sense of individual selfhood situated within community? Eastern European folklore and mythology give us tools to rethink this contemporary dilemma.</p> <p>We will focus on myths and folk tales from East Central Europe. We will ground our discussion in the historical context of Scythian female warrior culture and some pre-Indo-European beliefs and practices. These cultural phenomena survive in the myths and epics of the Slavs. We will analyze representations and adaptations of these myths and practices in contemporary literature, film, and art from former Yugoslavia, Romania, Ukraine, and other Eastern European countries.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> <p>This course meets the Core Program Pre-1800s Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9375,2025,1686,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-134','<div class="desc"> <p>How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist one century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun," and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency, known otherwise as the Russian Avant-garde. Topics include: poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9377,2025,2822,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-136','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. Authors may include: Tolstoy, Dostoevsky, Turgnev, Gogol, Goncharov, Bulgakov, Pushkin, and many, many others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9378,2025,2941,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-138','<div class="desc"> <p>Should you abandon yourself to the sensual beauty of the world? Or should you embrace a life of asceticism and simplicity? Is there an even more attractive path in between? Is it also a more difficult one? Major works by Russian writers—including Pushkin, Tolstoy, and Chekhov—across a number of literary genres will guide our discussions of these important questions. Knowledge of Russian not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9379,2025,3214,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-139','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>No previous knowledge of either the Russian language or Russian literature is required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9380,2025,1643,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-140','<div class="desc"> Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near-death experiences throughout the Mediterranean. While immensely entertaining and, at times, ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in post-Â­classical literature, art, and film. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9382,2025,2516,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-145','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we''ll also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9383,2025,2702,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-150','<div class="desc"> <p><em>The Literary Mind and the Carving of Dragons</em> is a highly influential work on Chinese literary aesthetics, and its title also suggests two important constituents of the literary composition process by pre-modern Chinese authors: ideas and craftsmanship. By providing an introduction to classical Chinese literature through readings in translation, this course will integrate aesthetic appreciations and cultural understandings of the classical Chinese literature, and help students grasp the conceptions, styles and creative skills of different Chinese authors. The time range will cover the period from <em>The Classic of Poetry (Shijing) </em>through the Qing dynasty. Throughout the course, students will have a basic historical knowledge of the Chinese literary tradition, as well as a sense of how to go about interpreting Chinese literary texts. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9385,2025,2514,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-181','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women, such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9386,2025,1509,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-182','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell, and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9387,2025,2587,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-186','<div class="desc"> <p>The course will explore the unique sense of tragedy and the tragic in Iranian literature and culture, tracing this fundamental attunement to the world from its Ancient Iranian roots to Ferdowsi’s 11th CE defining national epic — the Book of Kings — through the poetic and intellectual foundations of contemporary Iranian culture — the 13th-14th CE poetic work of Sa’adi and Hafez — and through to modern Iranian music and literature. The course will analyze the specific characteristics of Iranian tragic culture, closely attending to the developing expressions of that tradition in each of the works and eras covered by the course. The course will also take up the long, contested cultural and political history between Iran and, broadly, the West, focusing on the complex and mutually defining interactions between Iran and, first, Ancient Greece and, then, Europe and the US— both before and in the wake of Western imperialism. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9388,2025,2652,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-187','<div class="desc"> <p>“The origins of the myth of Prometheus,” it has been said, “are unclear; even in antiquity the story is never told in full.” Right from the very beginning, then—so it would seem--Prometheus arrives on the scene of literature in a torn, dismembered condition, his story diffracted from the outset into a multiplicity of incoherent elements and perspectives: is he a mighty Titan, or merely a trickster? a divine benefactor, or a threat to cosmic peace? an embodiment of the power of thought, or a figure of its eternal helplessness and misery? The primary object of this course will be to survey some of the more impressive and surprising ways in which literature, art, and philosophy have engaged with, and contributed to, the prismatic strangeness of this myth of Prometheus--from the ancient songs of Hesiod and Aeschylus, to the Romantic soundings of Goethe, Shelley and Herman Melville’s <em>Moby Dick</em>; from its intellectual appropriation by Marx, Nietzsche, Heidegger and Freud, to its “plastic” rendering in the murals of Orozco, the statuary of Paul Manship, and the contemporary films of Ridley Scott and Alex Garland (director of <em>Ex Machina</em>). More tentatively, the larger goal of the class will be to consider whether the Prometheus myth in its entirety might not be guided by the reflection that absolute assertions of authority and power always imply their own undoing, and that sovereignty will forever be linked to suffering and to sorrow.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9390,2025,3506,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-190','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the beautiful yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9392,2025,3239,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> <p><strong>To be: Ukranian</strong></p> <p>Ukraine’s rich poetic and revolutionary culture helps one trace routes of escape from oppressive imperial structures. Philosophical and literary texts written by and about Ukrainians will allow us to gain an understanding of this culture, and the works by contemporary historians will help us develop an understanding of Ukraine’s tumultuous history. Philosophers, writers, and historians could include Svetlana Alexievich, Anne Appelbaum, Ivan Kotlyarevsky, Alexander Potebnja, Mykola Riabchuk, Timothy Snyder, Lesia Ukrainka, Oksana Zabuzhko, Serhiy Zhadan, and others. No previous knowledge of Ukrainian history, language or literature is required. Core Requirement Met: Regional Focus.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9394,2025,2326,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/copy-of-cslc-211','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different "scenes of writing," from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature''s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience and knowledge are produced, articulated and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9395,2025,1575,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-200','<div class="desc"> <p>Drawing upon literatures and language traditions from across the world, the immediate object of this course will be to help students develop a lively appreciation for, and analytic facility with, each of the major kinds of literary production (lyric, narrative, and drama), all of which we shall try to examine in their “traditional” forms, as well as in some of their more familiar contemporary ones (not only the lyric poem and the prose novel, but the popular song, the graphic novel, and the television series, too, will fall within the special compass of our inquiry). Beyond these immediate goals of familiarity and competence, however, the wider ambition of this course will be to develop students’ understanding of the crucial role that literary (and literature-based) forms play in the constitution of the cultures we inhabit and the various "subject-positions" we might occupy within them. To this end, we shall make ourselves familiar with some of the most important thinkers in recent literary and cultural theory (Foucault, Derrida, Kristeva, Sianne, and Ngai, to name but a few). Given the course’s broad international range, guest lecturers will be brought in throughout the semester to discuss the effect of reading works in the original language and to explore, more generally, the effect that the specific features of a language can exert over that delicate interplay of “literature, culture, and self” that forms the central subject matter of this class. This course serves as the Proseminar for CSLC, and is required for the major but is open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9396,2025,2823,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-201','<div class="desc"> <p>The words of literature, unlike soda cans, bits of data, or the modular classroom furniture of Johnson Hall, do not come to us in easily separable pieces; the words of literature, rather, always present themselves to us as parts of a greater whole, as participants in this or that literaryFORM: a poem, a play, a novel, a song... In this class, we shall set aside the usual preoccupation with the meaning of the words of literature, to investigate instead the various effects that different literary forms exert upon us. What, for instance, do narrative forms --from Babylonian epic to the experimental prose of David Foster Wallace and Karl Ove Knausgaard--tell us about the kinds of worlds that are ours to inhabit in our daily lives? How do the poetic forms of (say) the ballad, the haiku, the sonnet or pop song inflect the manner in which we every day take up our existence? How does drama--from Ancient Greek tragedy to Japanese <em>noh</em> to the theatres of the avant-garde, the cruel and the absurd--open up for us the experience of all those "others" with whom we share this life? By the end of this class, it is hoped that students will have developed not only a feeling for literature in its many forms, but reciprocally, an appreciation for the richness of experience such forms of feeling can bestow upon us.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9398,2025,3300,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-203','<div class="desc"> <p>It is impossible, the philosopher Martin Heidegger once declared, for any human being ever to be truly alone; to exist as a human at all, he argued, is always already to be acting and thinking and feeling in relation to other humans, to be interpreting our own being in relation to those who likewise, and reciprocally, must interpret their being in relation to ours. In this class, we shall examine the ways in which various philosophers and theorists over the last several centuries have conceived this mutually entangled condition of togetherness, this common existential condition of Being-With. We shall inquire, for example, into the ways this condition of shared being has been interpreted politically (in terms of entities such as city-state and nation-state), sociologically (through notions such as community and society), economically (through concepts such as markets and labor), and anthropologically (through the concepts of kinship group, family, and tribe). What shall distinguish this class from those to be found in any number of social science departments, however, is the close attention we shall be paying to the crucial role of culture, the role of literature in particular, in the making (and unmaking, and remaking) of all these ways of relating ourselves to one another. Or to put it somewhat more pithily (and alliteratively): how exactly do poetics relate to politics, and politics to poetics, in the shaping of a shared human existence? This course shall survey some of the most important ways of answering this question in the modern era. Students can therefore expect to study a wide array of social and cultural theorists from the 17th century forward, including (but not limited to) figures such as Hobbes and Vico, Rousseau, and Smith; Hegel and Marx, Malthus and Mill; Durkheim and Weber, de Beauvoir and Adorno; Fanon and Bourdieu, Turner and Geertz: Habermas and Rorty, Nussbaum and Butler; Nancy and Agamben, Appiah and al-Gharbi.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9401,2025,1644,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-210','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-78) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with major figures such as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as the unprecedented boom in popularity of physiognomy around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. Concluding with the rise of Nazism and Nazi attacks on modern art as “degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. All readings and discussion will be in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9406,2025,2327,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-232','<div class="desc"> <p>This course focuses on Mikhail Bakhtin''s theory of language and the novel. Bakhtin''s writings are a synthesis of diverse theoretical approaches, including NeoÂ­Kantian philosophy, structuralist linguistics, the theory of novelistic discourse as a polyphonic medium, and the notion of carnival as a subversive cultural force. Furthermore, Bakhtin''s approach to the text reveals prose fiction, and, to some degree, nonÂ­fiction, as a unique medium through which language explores human consciousness in both time and space. In this course, Bakhtin''s theories are studied in order to understand more deeply the significance of the novel, and novels are studied in order to better understand Bakhtin''s theories. Works as diverse as Fyodor Dostoevsky''s <em>Crime and Punishment</em>, Venedikt Yerofeev''s <em>Moscow to the End of the Line</em>, Umberto Eco''s <em>Foucault’s Pendulum</em>, and Manuel Puig''s <em>Kiss of the Spider Woman</em>, are examined through the Bakhtinian lens in order to broaden the students'' understanding of the text as a polyphonic phenomenon. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9407,2025,1577,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-233','<div class="desc"> <p>Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939, when the Soviet Union was busily partitioning Poland with Nazi Germany by secret agreement. This course examines the cultural history of Russia and the Soviet Union, in specific regard to its evolving theories of language, literature, and cultural phenomena during the early 20th century. Particular attention is paid to Russian formalism, poetics, and semiotics, as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence, mutual East-West suspicion, social repression, and exertions of state power through propaganda and censorship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9408,2025,3891,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-235','<div class="desc"> <p>Plato thought that all we need is a philosopher-king. What if he was only partially right, and what we actually need is a philosopher-buffoon? Jokes aside, what if critical thinking needs to be accompanied by laughter? And not just any laughter, but the kind that, following Mikhail Bakhtin, one would call carnivalesque.</p> <p>Carnival laughter exposes the grotesque aspect of human bodiesâeverything that is âugly, monstrous, hideous from the point of view of âclassicâ aestheticsâ of the ready-made and the completed. It liberates an individual body by revealing the ways it is open to the world around itâby emphasizing a bodyâs orifices and protruding parts. This laughter also revives and refreshes thinking by ridiculingâwithout destroyingâthe strict laws of rationality. Carnivalesque laughter is irreverent; it crosses the lines of what is socially, politically, and morally acceptable, and in so doing reveals the connections between myself and other beings.</p> <p>Bakhtin will provide the main theoretical framework for the course that will bring together literature and philosophy of Eastern Europeâthe works of Gogol, Zizek, Andrukhovych, and othersâto explore (and pervert?) the claims made above.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9409,2025,2747,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers: Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9410,2025,2894,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-237','<div class="desc"> <p>Marcel Proust’s <em>In Search of Lost Time </em>is considered to be one of the greatest novels ever written. Two 20th century thinkers—an Eastern European philosopher Merab Mamardashvili and a French thinker Gilles Deleuze —argued that Proust’s novel is a philosophical machine: an artificial organ that allows one to gather and re-construct the self. Mamardashvili was the only Soviet philosopher to study Proust’s novel and respond to its Western European interpretations from the perspective of Eastern Europe. He also used the novel to expose and explain the more obscure aspects of the Soviet and Russian worldviews. This course puts to the test Deleuze’s and Mamardashvili’s interpretations of this novel by considering them in conjunction with significant portions of <em>In Search of Lost Time. </em>All of the readings and discussions will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9411,2025,1510,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-241','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. </p> <p>Students who have completed LATN 102 can take the language intensive version of CSLC 241, LATN 341, where we will read selections from Seneca’s <em>Epistulae ad Lucilium,</em> as well as Horace’s <em>Satires</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9412,2025,3309,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-242','<div class="desc"> <p>In this course, students and professor will collaborate in a close reading of Umberto Eco’s 1980 novel, <em>The Name of the Rose</em> (originally published in Italian as <em>Il nome della rosa</em>). The novel is many things at once. It is a murder mystery/detective novel, a coming-of-age story, a dramatization of debates within Medieval philosophy that resonate to this day, a book about books, and a fantasy about recovering lost works from antiquity, most importantly, Aristotle’s lost book on comedy. We will read the novel slowly and deeply over the course of the semester and together we will explore its themes—such as the nature of words, names, and other signs, the meaning of laughter, and the value of tolerance in a world of dogmatic certainties—and its rich literary allusions—to Sherlock Holmes, Jorge Luis Borges, Alexandre Dumas, and to numerous Medieval and ancient authors. We will track down the novel’s literary references (by reading secondary resources, such as scholarly articles), seek to understand the rich world of philosophical and theological thought its characters inhabit (by reading primary texts of Medieval philosophy, theology, and poetry), and wallow in the sheer beauty of Eco’s writing and the sheer thrill of the story he is telling, all with the goal of interpreting the novel as deeply as possible, as one of the most significant postmodern works of fiction.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9413,2025,2570,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-246','<div class="desc"> <p>This interdisciplinary course introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. Taught in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9414,2025,2736,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-247','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9415,2025,2824,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-248','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 BCE sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 BCE when he brought his army across the Rubicon river into Italy from Gaul. </p> <p>Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as <em>On the Republic</em> and <em>On the Laws</em>, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators seeking to restore the old order assassinated Caesar in 44 BCE. They were in turn destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.</p> <p>Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise <em>Discourses on Livy</em>, and John Adams (the “American Cicero”), whose 1787 work <em>Defence of the Constitutions of the United States of America</em> owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9416,2025,3286,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-249','<div class="desc"> <p>This course explores some historical examples of ways of confronting the sort of ressentiment—“a generalized feeling of resentment and oftenhostility harbored by one individual or group against another”—that pervades our cultural discourse, wracks our political life, and makes us miserable as individuals. We shall engage in close examination of the ancient Roman authors Cicero (106 – 43 BCE), Seneca (4 BCE – 65 CE), Epictetus (c.50 – 135), and Marcus Aurelius (121 – 180 CE) and the classically-influenced American cultural critic Albert Murray (1916-2013). We shall interrogate both the strengths and weaknesses of the programs and techniques that these authors—all of whom lived through times of social and personal turmoil—proposed for remaining centered in a sense of their own dignity and in a feeling of gratitude for the blessings that were intermingled with their tribulations. In the case of Murray, we shall assess the adequacy of his theory about the African-American Blues tradition and compare it to that of some scholars who had preceded him. We shall attempt to determine the limitations and strengths of his perception that the Blues idiom represented not “the anguished outcry of a victim” but “an exercise in heroic action” through which the individual makes “an affirmative and hence exemplary and heroic response” to both the suffering particular to historically conditioned forms of oppression as well as to the absurdity of the human condition. Topics covered include the theory of ressentiment, the emotions in ancient Roman thought, Roman techniques for cultivating positive, empowering affective responses not only to “microaggressions,” but to even themost horrific events, and Albert Murray’s theory of the “Blues idiom” as “survival technique [and] esthetic equipment for living.” </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9417,2025,3215,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-250','<div class="desc"> <p>This course investigates select African American engagements with the literatures produced by ancient Greeks and Romans. It is motivated by the conviction that we do interpretive justice to the accomplishments of African American writers when we attempt to understand the tradition(s) they conceive their work to be intervening in.</p> <p>African American literature was born with the publication of Phillis Wheatley’s <em>Poems on Various Subjects, Religious and Moral,</em> in 1773. The book evinces a deep knowledge of Latin and Latin literature, which it turns to its own emancipatory end. Indeed, Wheatley secured her freedom on the strength of the book.</p> <p>Engagement with classical texts offered Wheatley and other African American writers of every era an opportunity to access, deploy, and transform a widely shared treasury of meanings, ideas, images, tropes, genres, and styles in order to create unique works of great artistic power, capable of opening up newly imagined ways of being for themselves and their readers. In addition to Wheatley, we shall explore the classical interactions of poets such as James M. Bell, Mary Livermore, Frances Ellen Watkins, and Robert Hayden and prose writers such as David Walker, William Sanders Scarborough, and W. E. B. Du Bois.</p> <p>To experience the artistic power of these works as their authors intended, we must understand the aesthetic and literary contexts and tradition(s) in which they worked, for context and tradition are the foundation of a work’s meaning. To this end, we shall read alongside African American literary creations some of the Greek and Roman literary works to which they respond. For when we see clearly how a poem by, for example, Phillis Wheatley, responds to an ode by the Roman poet Horace—himself the son of a freedman—we grasp more fully the unique aesthetic, moral, and intellectual power of her poem. To see how Horace’s poetry could communicate to Wheatley is to see how Wheatley’s poetry can communicate its emancipatory power and promise to us in our own time. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9418,2025,1645,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensable for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9419,2025,2748,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-252','<div class="desc"> <p>This course will focus on two foundational texts of Chinese civilization: The <em>Analects </em>and the <em>Zhuangzi</em>. The <em>Analects</em> is an ancient Chinese book composed of a collection of sayings attributed to Confucius and his disciples, and is traditionally regarded as one of the central texts of Confucianism. <em>Zhuangzi</em>, named for its traditional author, “Master Zhuang” (Zhuangzi), is one of the most important Daoist writings. When the <em>Analects</em> emphasizes that people should reconcile their desires via rituals, and fulfill moral and personal duties in order to ensure the welfare of the society, <em>Zhuangzi</em> promotes carefree wandering and following one’s own nature. By reading and comparing these two texts, this course will help students understand and grasp their central concerns, philosophies, and substantial influences on Chinese and East Asian thought and values throughout history. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9420,2025,2942,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-253','<div class="desc"> <p>The Tangand Song dynasties (618-1279) are known as Golden Ages in Chinese history, and also generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry. This course introduces the major literary genres and authors of the Tang and Song Dynasties, as well as literati culture emerging during this era. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. Students will discover the key role that literature played in Chinese court politics, empire building, and institutionalized learning; as well as how it shed light on gender and women’s status, war and knight-errantry, Daoist and Buddhist traditions, and more. The primary texts are translated in English, so knowledge of Chinese is not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9421,2025,3892,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-260','<div class="desc"> <p>This course offers a survey of Japanese textual and visual culture from Japanâs early modern times (16<sup>th</sup> through late 19<sup>th</sup> centuries). We will learn about early modern Japanâs education systems, print history, and book culture, as well as forms of literacy that shaped Japanâs cultural and national identity. Through a wide range of popular literary and visual materials, we will analyze the modes of knowledge and information transmission and the roles they played in everyday life. To gain an intuitive experience of Japanese literary culture, we will carry out several hands-on activities such as rare books workshops and museum visits. Finally, we will turn to new forms of media that rose after the Meiji Restoration in 1868 and how they influenced modern Japanâs cultural identity. The course is given in English and offered in alternate years. No prior knowledge of East Asian languages is required to take this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9422,2025,2749,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-270','<div class="desc"> <p>This course will explore the psychology and biopolitics of sexual behavior in literature and film. The first unit, the couch, focuses on psychological theories of sexuality based on works by Freud, Foucault, Lacan, and Derrida. The second unit, the court, explores the biopolitical demands and legal consequences of acting out our sexual impulses. This unit, with texts by Agamben and Esposito, traces the dehumanization, exploitation, and control of the body in authoritarian regimes. The third unit, the confessional, discusses the reproductive bias of spiritual or religious systems and the prohibition of sexual expression. This unit presents films with scenes or plots illustrating the struggle between body and mind. The three units together will ask how sexual impulses disrupt a given socio-political order. Students will evaluate the solutions to disruption offered by psychology (compromise), the court (crime and punishment according to a given society''s laws), and religion (confessing sex acts to a religious official who will condemn them, impose penance, and absolve the transgressor). </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9423,2025,1578,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-280','<div class="desc"> <p>In this course, we shall attempt to come to terms with three of the most important - and provocative - philosophers of the last two hundred years, philosophers without whom the great majority of contemporary literary and cultural theory (and much art and literature, as well) would, essentially, be unthinkable. Significantly, all three of these philosophers habitually turned to ancient Greek tragedy in the formulation, articulation, and further elaboration of their thought. In this class, we shall therefore attempt to use the experience of Greek tragedy, in all its ecstatic strangeness, as a powerful point of entry into the difficult yet crucial works these philosophers have bequeathed to us. Major texts to be covered include: the plays of Aeschylus and Sophocles, <em>The Phenomenology of Spirit,</em> <em>The Birth of Tragedy,</em> <em>Thus Spoke Zarathustra,</em> <em>Being and Time,</em> and <em>Introduction to Metaphysics</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9425,2025,1688,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-283','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all-important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9427,2025,2825,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-285','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9428,2025,1646,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-286','<div class="desc"> <p>In this class, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth’s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home" at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9429,2025,2943,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-288','<div class="desc"> <p>In the 6th century BCE, certain Greek thinkers (who have since come to be known as "philosophers") put in motion a conceptual distinction decisive for the cultural and intellectual history of the West: the division of the soul (<em>psyche</em>) from the body (<em>soma</em>), and more generally, from the "flesh" (<em>sarx</em>). By the 4th century BCE, Plato seems to have concluded that philosophy must eschew any interest in the flesh, inasmuch as flesh (whatever it may be) cannot yield to precise, philosophical investigation. Perhaps even more crucially, Plato stipulated that flesh cannot and should not be the basis of a politics, as it is only philosophical insight, in its disciplined refusal of the lure of the flesh, that could serve as the ground of genuine political communion. From here it was but a short step to conclude that poetry (and of course, "art in general"), entangled as it was with the body, could have little meaning or import for the practice of either politics or philosophy.</p> <p>Influential as these weighty pronouncements have been on the development of Western thought, resistance to them, it should be noted, was almost immediate--beginning perhaps with the work of Plato himself! In this course, we shall examine the ways in which literature and art, as a "poetics of the flesh," offers us a practice as rigorous, and productive, as any philosophy focused on abstract forms. We shall then consider what such a poetics of the flesh might be able to offer philosophy itself as an intellectual discipline. Finally, we shall engage with recent theories concerning the way in which authentic political community might rest not on the eschewal of the flesh, but on its deliberate and thoughtful "incorporation" (pun intended).</p> <p>The first half of the class will focus on older material (certain Ancient Greek and Roman poets, Plato, Aristotle, the Old and New Testament, as well as some medieval writers and thinkers); the second half of the class, however, will turn to the work of more recent poets and theorists of the flesh, with a particular emphasis on the investigations of Jean-Luc Nancy into the significance of the arts for what he calls the "sense of sense."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9432,2025,2675,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Inscribed Landscape: Nature and Travel in Chinese Literature</strong></p> <p>This course will lead students into the world of the Chinese cultural landscape through the lens of literature. We are going to conduct virtual travel to the mountains and waters in China by reading the masterpieces of Chinese landscape and travel writings. We will study the symbolic language that Chinese writers employed to describe their experiences of the natural landscape and their constructions of the cultural landscape. In a broader sense, the focus of this course stems from the interest in cultural geography in the Chinese context. The majority of the course content is on the pre-1800 period. In addition to analyzing literary texts through close reading, this course will introduce students to the ArcGIS system, a digital tool widely used in geohumanities research to view, edit, and analyze geographic data. Students will enjoy the opportunity to create a project using StoryMaps to illustrate their vision of a cultural place. Classes follow a lecture-discussion format. Students are expected to finish assigned readings in advance and actively participate in class discussions. No knowledge of the Chinese language or history is required (or assumed) for this literature-in-translation course.</p> <p><strong>Cultural Appreciation and/or Appropriation through the Lens of Asian Cinema</strong></p> <p>At its core, this course is an attempt to investigate, analyze, and ultimately comprehend the concept of cultural appropriation, in particular through an East Asian context. With a history of imperialism, be it Western or Japanese, in the 19th and 20th centuries, the topic of cultural appropriation is controversial and complicated, whether it is Katy Perry performing wearing a kimono at the American Music Awards or Chinese-Taiwanese-American chef Eddie Huang and his embrace (appropriation?) of African-American black culture. Prior to the actual viewing and analyzing of films, a comprehensive, albeit limited, survey of theoretical works will be conducted; works including but not limited to Richard Rogers’ “From Cultural Exchange to Transculturation: A Review and Reconceptualization of Cultural Appropriation,” Baris Buyukokutan’s “Toward a Theory of Cultural Appropriation,” and Lisa Nakamura’s concept of “identity tourism.” Some of the pairings to be analyzed are: William Shakespeare’s <em>King Lear</em> and Akira Kurosawa’s <em>Ran</em>; Clint Eastwood’s <em>Unforgiven </em>(1992) and Lee Sang-il’s Japanese Western <em>Yuzusazarumono </em>(2013).</p> <p><strong>Hear Now: Jean Luc Nancy and the Aesthetics of Community</strong></p> <p>In this class, we shall be examining the work of one the world’s most important living philosophers, Jean Luc Nancy. Special emphasis will be placed on the close relation Nancy seeks to draw between our so-called “private” aesthetic experiences—the painting that arrests us, the bar of melody that makes us tremble, the line of poetry that haunts us—and our sense of “being in community” (the sense, that is, that our supposedly singular existence is always already plural, is always already shared out with others). Beyond the reading of Nancy’s own works, we shall also be looking at the work of some of his most important predecessors on the question of art’s relation to the community (Kant, Hegel, Benjamin, Adorno), as well as the works of those thinkers who have engaged most directly with his ideas (Derrida, Agamben, Esposito), and those who have explicitly sought to oppose him (Ranciere, Badiou, and others). <em>Prerequisite: CSLC 200 and CSLC 283.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9434,2025,2750,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-300','<div class="desc"> <p>In this seminar-style course, CSLC majors (acting under the guidance of the course instructor) will be asked to research, and then report to one another, on contemporary trends in literature and literary theory. It is hoped that the skills developed in this course, as well as the content mastered within it, will help CSLC majors in the eventual formulation (and successful completion) of their Senior Comps. Only open to CSLC majors with junior standing, or by instructor permission.</p> </div>','CSLC 200 and two additional courses in CSLC ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9436,2025,3310,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-315','<div class="desc"> <p>This course will focus on an in depth investigation into the philosophy of nature, culture, and theory of subjectivity developed by the often overlooked late 18th century thinker Johann Gottfried Herder (. First student and later arch-enemy of Immanuel Kant, Herder developed a theory of nature, culture, and human subjectivity that stood in stark contrast to the universalist, mechanistic, and teleological theories of nature and culture so characteristic of the period we know as the Enlightenment. Herder, by contrast, utilized cutting edge discoveries in the emerging field of biology to develop a cosmological theory that saw both nature and human culture as wrapped up in the process of dynamic transformation. The consequence, for Herder, was that nothing that exists carried with it a singular essence but rather, that the very nature of being was change and that all things, therefore, came be what they are in and through the dynamic interaction with a natural, historical, and cultural environment. This ontological principle allowed Herder to develop a number of radical theories, which we will examine in turn. First, a proto-evolutionary theory of nature that proved highly influential on Charles Darwin (through Alexander von Humboldt) and which viewed organisms and environments as historically contingent and wrapped up in a process of co-adaptation. Second, Herder''s theory of subjectivity, which viewed human thought not as strictly universal but as grounded in language and culture and hence, as necessarily diverse as the manifestations of human language and culture itself. And finally, after investigating both of these concepts, we will investigate impact of Herder''s philosophy both historically, as a forerunner of existentialism, as well as its possibilities for contemporary theory. For it seems to follow from Herder''s supposition that the essence of being is transformation that we should not hold on to any form of essentialism. Rather, Herder seems to suggest that we should affirm, in Nietzsche''s language, the diverse manifestations of existence as well as their historical transformation both subjectively in ourselves and objectively in the cultures in which we live. </p> <p>The course will have the following structure: I: An investigation into the context of the natural sciences (mechanism vs vitalism) out of which Herder''s theory emerges. II: Herder''s response this crisis of the mechanistic sciences (vs Kant''s) and the development of Herder''s philosophy of nature and subjectivity. III: The influence of Herder''s theories on his contemporaries J.W. von Goethe and Alexander von Humboldt. IV: Contemporary theory and Herder.</p> <p>Second-stage writing requirement: Students may satisfy the Second-Stage Writing Requirement by submitting a substantial (12-15 page) writing assignment that addresses a subset of the primary texts studied in this course. Students satisfy the Second Stage Writing Requirement by obtaining a grade of "C" or higher on this paper. </p> </div>','At least one course in CSLC or Philosophy, or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9438,2025,3523,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-395','<div class="desc"> <div><p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. In Spring 2025, the course will be: </p><p><br/></p><p dir="ltr"><span>Trivial Comedies for Serious People: New Comedy from Ancient Greece to Modern Ireland </span></p><p><br/></p><p><span>Sleepless in Seattleâ¦How to Lose a Guy in Ten Daysâ¦James Joyceâs </span><span>Ulyssesâ¦</span><span>Samuel Beckettâs </span><span>Happy Days. </span><span>What do these widely diverse artistic creations share in common? They all emerge, or so this course will contend, in response to the ancient dramatic form known as New Comedy, an artistic genre that was to succeed both Greek Tragedy and Greek Old Comedy, and more commonly known as Romantic Comedy. Thus, where many critics today seek to understand the masterpieces of Irish Literature from within Ireland itself, that is, from the largely immanent perspectives of power, politics, and culture native to the island, this class will consider the possibility that the great comic achievements of Irish authors such as Wilde, Synge, Joyce, Beckett, and McDonagh also developed in response to a genre that emerged far beyond Irelandâs national borders. In the first part of this course, we will interrogate the genre of New Comedy as it develops in the classical tradition through Euripides, Menander, Plautus, and Terence. In the second part, we will see how this legacy unfolds in the works of Dante, Shakespeare, and Restoration Comedy, in a tradition that carries over even into our own Netflix specials. In the third part, we will explore the complex, and often perverse, ways in which the genre manifests in the modern Irish tradition. Special attention will be paid throughout the course to the central role that female characters play in the unfolding history of this popular dramatic genre, from ancient to modern times. This course is for advanced CSLC majors:</span><span> students should have junior or senior standing; must have taken CSLC 200, 201, and at least two other 100, 200 or 300 level CSLC courses; or have obtained the written permission of the instructor. Students who receive a grade of C or above on their final paper will pass their second-stage writing requirement. </span></p><p><br/></p><p><br/></p></div> </div>','This course is for advanced CSLC majors: students should have junior or senior standing; must have taken CSLC 200, 201, and at least two other 100, 200 or 300 level CSLC courses; or have obtained the written permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9439,2025,1579,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9440,2025,1648,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/400/cslc-490','<div class="desc"> <p>This course will guide students through the research and drafting of the Senior Comprehensive Project, and will provide students with feedback on work in progress. Open only to senior CSLC majors. Students must enroll in CSLC 490 both fall and spring for a total of 4 units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9443,2025,2738,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-100','<div class="desc"> <p>This course introduces critical theory in the context of the problem of social justice. Introductions will be made to psychoanalytic, Marxist, feminist, structuralist, deconstructive, and postcolonial criticism. Reader-responses; New criticism; lesbian, gay, and queer criticism, will also be surveyed. There will be close readings of the work of Louis Althusser, Georges Bataille, Michel Foucault, and Jacques Derrida, as well as in depth readings of essays by Guy Hocquenghem, Julia Kristeva, and Trinh T. Minh-ha.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9444,2025,1110,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-101','<div class="desc"> <p>Meaningful social and political change requires not only critical and thoughtful engagement with our grounding ideas, dominant theories and our existing positions. It also demands that we learn the concrete, practical skills necessary to make our ideals real, to exercise our rights, to fulfill our duties to one another, and to transform the actual mechanisms and institutions that shape our lives. This course â unique at either the undergraduate or graduate level â will provide students with an intensive and full-spectrum introduction to the most important, most effective and newest techniques, tools and technologies used in political and activist campaigns from the highest levels of electoral politics to non-profit, non-governmental and community campaigns.</p> <p>The course curriculum is organized in three dimensions, training students with the core skills necessary to participate in existing political and activist work, but also empowering them to, when necessary, imagine and carry out their own innovative and transformative campaigns. To this end, students will learn not just tactical skills, but also strategic planning and management approaches that will help them invent, implement, and improve the campaigns to which they commit themselves.</p> <p>This course will include instruction and workshops that bring the best practices and lessons from top businesses and campaigns, refined by political practitioners and distilled for students. It will also include tactical skills training-- media messaging and communication strategies, polling literacy, database management, budgeting and campaign finance, Get Out the Vote (GOTV) efforts, and lobbying basics.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(9445,2025,3351,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-103','<div class="desc"> <p>This course engages students in critical analysis of classic theories of justice and their connection to more contemporary theories and enactments at the global level. Theoretical explorations will include readings from Pre-1800 theorists on justice and punishment include: Plato, Aristotle, Manu, Al-Farabi, Al-Mawardi, Thucydides, John Lock, Immanuel Kant, Jeanne-Jacques Rousseau, Thomas Aquinas, and John Rawls. The course will build on these early theories of justice to explore justice from the Enlightenment through the current moment through themes such as: utilitarianism, deontology, concepts of fairness, libertarianism, and communitarianism. Themes related to social justice will explore gender justice, racial justice, economic justice, and liberatory practices in the context of global capitalism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9446,2025,2929,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-104','<div class="desc"> <p>This seminar will explore the emergence of new expressions and practices of gender and sexuality by contemporary Arab and Iranian intellectuals, artists, activists and leaders. Rooted in a study of the historical conditions for the emergence of this new set of discourses and practices â from pre-Islamic cultural practices to Western colonialism â the course will examine the novel and transformative forms of expression of gender and sexuality that are being invented in the Middle East and North Africa in dialogue with and in resistance to pre-existing narratives, policies and practices. From resistance to the idea of “gay identity” as a colonial-era trap and backlash against emergent gay rights movements, to the strategic complexities of appropriating the state laws supporting gender-reassignment surgery in Iran, the new generation of queer activists and intellectuals are navigating both their own histories and the limits of postcolonial discourse as they seek a liberatory art and politics. The course will dedicate significant time to studying the current work of these activists â taking up their writing, art, interviews, videos, and political tactics. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9447,2025,823,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-105','<div class="desc"> <p>This course will locate the topics of immigration and education within historical, legislative, and cultural debates on what it means to be an American and who has the right to an education. Students will explore and debate precedent-setting Supreme Court cases, such as Mendez v. Westminster, which challenged the segregation of Mexican children into separate schools, and Lau v. Nichols, which fought hard for non-English speaking students to have linguistic access to the public-school curricula. In addition, students will research the historical antecedents to the recent anti-immigrant movements in California, Arizona, and Colorado, which target the use of languages other than English in school settings, and have all but abolished bilingual public schools. Against this historical and legislative backdrop, students will examine ethnographic research detailing the persistent challenges that immigrant children face in schooling, including migrant children, and the ways in which they, their parents, and communities experience those challenges.</p> <p>This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CTSJ 105, DWA 282, and SOC 105.</p> </div>',NULL,'DWA 282 and SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(9448,2025,1154,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-106','<div class="desc"> <p>In the United States, roughly 80% of the population lives in urban regions (2000 U.S. Census), while according to United Nations figures, about 52% of people are urban-dwellers worldwide. This course will examine various representations of the modern metropolis through film, literature, and cultural theory. The city, as we experience it today, is the product of multiple historical, cultural, and social forces. Over the course of the semester, we will consider how cities have been shaped by these forces, as well as how they, in turn, shape our own experience and understanding of culture, history, and social practices. In an era of increasing globalization and mobility, the role of the metropolis continues to evolve and expand. As we consider representations of the city in a variety of films and novels from around the world, including some from our own city of Los Angeles, we will interrogate the ways in which the city has played a formative role in how we imagine life in the contemporary moment. In what ways has the city become a vehicle for the production of culture? How does life in the city serve to normativize certain notions of what it means to live in the modern world? How does life in rural spaces complicate representations of modernity that take the city as their norm? Does the city promote accessibility, or, alternatively, does it rigidify codes of exclusivity? These are some of the many questions we will address as we consume a spectrum of world cinema and literature. As we work our way through the material, we will strive to develop a complex understanding of how cities shape our cultural imagination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9449,2025,1690,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-107','<div class="desc"> <p>This course will introduce students to major concepts, theories, and intellectual inquiries in the area of postcolonial studies. Students will engage with broad questions around knowledge production, representation, and subjectivities through the examination of topics such as: decolonization, migrations, transnationalism, diaspora, cultural productions, and practices of resistance. The course will look at relationships between postcolonial studies and critical race, feminist, and queer theories.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9450,2025,2985,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-108','<div class="desc"> <p>Through the year 2020 we have seen the rise of reactionary, ethno-nationalist politics across the world. It is likely that this rising authoritarian movement will intensify as climate change creates massive population movements among people in vulnerable economic situations and most susceptible to displacement. This course will critically examine the nature and interrelation between resurgent racist, ethnno-nationalist ideologies, tracing their historical and conceptual roots. It will also take up recent studies of the looming consequences of climate change for population displacement while examining the viability of public policy frameworks and legal instruments for addressing these exigent problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9451,2025,2877,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-115','<div class="desc"> <p>This course will examine the ambivalent effects of digital, networked technologies from social media to AI (with their underlying modes of understanding oneself and the world) in the modern Middle East and North Africa. In particular, in the context of the Middle East, the course will seek to identify and understand both (1) the new forms of popular liberatory action â for example, protest, organizing, revolt, sabotage, warfare, and the weaponization of AIâ that are made possible or impossible by the widespread adoption of new technological modes of life, and (2) the new forms of state and para-state, surveillance, control, suppression, and disinformation that this technology makes available or encourages by its very structure and embedded premises. The course will bring together a study of critical theoretical work from both Western and Middle Eastern thinkers, the scholarly and vocational writing of technologists in both the West and the Middle East, as well as the manifestos, radical speculative projects and strategic documents of resistance groups. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9452,2025,2846,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-120','<div class="desc"> <p>This course introduces students to theories of power from multiple disciplines, and applies these theories to analysis of how power operates in formal and informal politics. Students will be introduced to the basic operation of politics and public policy in the U.S., as well power operating in economic and social systems. It will analyze contemporary public policy, political campaigns and elections, social movements, hashtag activism, and other aspects of the struggle for power in the U.S. context. This class is open to frosh and sophomore students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9453,2025,3867,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-128','<div class="desc"> <p>This class interrogates significant theoretical approaches to conceptualizing and critiquing antisemitism. While the neologism âantisemitismâ refers most directly to reactionary political movements mobilized in Germany and France in the late nineteenth century, scholars and critics have long debated if and how antisemitism changes across time and place, antisemitismâs relationship to other forms of racial exclusion and gendered hierarchy, and the persistence (or displacement) of theological anti-Judaism in Western modernity. We will begin with a brief examination of the history of Jewish emancipation in Europe and ensuing debates about the âJewish Questionâ before surveying how antisemitism has been understood from various historical, theological, political, psychoanalytic, Marxist, and postcolonial perspectives. Some of the theorists we may engage include Hannah Arendt, Sigmund Freud, Jean-Paul Sartre, Theodor Adorno &amp; Max Horkheimer, Frantz Fanon, and Shulamit Volkov.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9454,2025,824,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/copy-of-ctsj-140','<div class="desc"> <div><p>This course introduces students to critical theories concerning human sexuality. We read feminist, Marxist, psychoanalytic, structuralist, and poststructuralist theories of sexuality, and discuss what makes each of these theories "critical." Topics include: the political economy of marriage, the relationship between sexuality and procreation, uses of the erotic, homosociality, and the incitement to discourse. </p><h1><br/></h1></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9455,2025,3853,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-158','<div class="desc"> <div><p>This course serves as an introduction to the field of cultural memory studies with particular attention to Holocaust memory and memorialization. After surveying theoretical approaches to individual and collective memory, we will explore how local and national contexts shape Holocaust memory, the function of Holocaust memory in postwar political discourses of the Cold War and decolonization, and the ambivalent globalization of Holocaust memory in the last few decades. We will consider Holocaust memorialization as a site of contestation and interrogate ensuing dilemmas of political responsibility, post-traumatic representation and reconciliation, and historical uniqueness. Throughout, we will reflect on and debate the political possibilities and limits of collective memory for confronting historical atrocities, enacting reparative justice, and preventing ongoing violence. </p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9456,2025,2330,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-160','<div class="desc"> <p>This course introduces students to contemporary feminist thought and histories of feminist activism. Students will learn about the intersectionality of race, gender, class, sexuality, and nation in a variety of feminist scholarship, and will examine key issues in feminist theory, such as: the debates between Western feminism and women of color feminism, transnational feminism, queer theory, the social construction of sex and gender, reproductive justice, gender-based violence, and the political economy of gender. This course will center on the strong link between feminist theory, social justice, and activism, and will explore how these can be mutually informing projects that can effect social change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9457,2025,1060,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-180','<div class="desc"> <p>Stupidity is neither ignorance nor organicity, but rather, a corollary of knowing and an element of normalcy, the double of intelligence, rather than its opposite. It is an artifact of our nature as finite beings, and one of the most powerful determinants of human destiny. Stupidity is always the name of the Other, and it is the sign of the feminine. This course in critical psychology follows the work of Friedrich Nietzsche, Gilles Deleuze, and most recently, Avital Ronell, in a philosophical examination of those operations and technologies that we conduct in order to render ourselves uncomprehending. Stupidity, which has been evicted from the philosophical premises and dumbed down by psychometric psychology, has returned in the postmodern discourse against nation, self, and truth, and makes itself felt in political life, ranging from the presidency to Beavis and Butt-head. This course examines stupidity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9458,2025,3336,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-190','<div class="desc"> <p>‘Socialism’ and ‘Marxism’ have become subversive buzzwords in the political atmosphere today, but how did activists inspired by Marxist thought actually conceptualize and organize movements for social change? This course will provide a basic introduction to Marxist theories of organization, with an emphasis on how different Marxists have built political groups and movements to challenge political power in the US. We will begin by reading primary texts in early socialist movements, from the Erfurt Programme to Eugene Debs’ speeches. The rest of the course will cover other historical and contemporary applications of Marxist organizational theories, from the US Communist Party’s organizing with Black communities in the 1930s to recent queer and feminist campaigns to call for abolishing work and the nuclear family.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9460,2025,1061,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> <p><strong>Axes to Praxis: Music as Activism</strong></p> <p>This course aims to provide students with an understanding of the role of music in creating social change. Students will listen to the structure and content of songs and discuss how they can spark critical thought and become a catalyst for political action. The students will also explore how live musical experiences contribute to community building. Traditional, as well as contemporary musical styles, will be examined with an emphasis on the music of women, the LGBTQA community and people of color. We will learn about the contribution of artists and activists whose ideas have propelled society forward.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9462,2025,508,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-201','<div class="desc"> <p>Environmental Justice means ensuring equal access to environmental benefits and preventing the disproportionate impacts of environmental harm for all communities—regardless of gender, class, race, ethnicity or other social positions. This introductory course examines legal theories, and key US case studies of environmental justice, with an emphasis on the ways race, class, and gender have shaped environmental battles still being fought today. Students will also learn about traditional and emerging justice topics, and innovative methods lawyers are using to address systemic environmental inequalities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9464,2025,2847,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-204','<div class="desc"> <p>The abuse of Iraqi prisoners at the US military’s Abu Ghraib Prison and the terrible photographs that circulated giving testimony to that abuse brought torture into our public discourse and became a point of intense political engagement in the US and around the world. This course will examine the so-called “enhanced interrogation techniques” used during the War on Terror as well as the legal and policy justifications that supported them. We will place these practices and justifications within the broader context of colonial power, looking at the ways torture and sexual violence were deployed by other nations. Beyond its use as a punishment or deterrent, we will trace the use of torture back through Western history, to its use in religious and political conversions and finally back to the origins of Western metaphysics in the Ancient Greek use of violence and dehumanization in the formulation of our conception of truth itself.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9465,2025,3066,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-205','<div class="desc"> <p>Whether discussing government plots, medical malfeasance, the moon landing, or the existence of<br/> birds, conspiracy theories have been the target of many moral panics in North America over the last<br/> century, and largely with good reason. However, conspiracy theory critics have often ignored<br/> imbricating socio-historical factors that contribute to belief in conspiracy theories, thereby<br/> homogenizing them and the power structures they call attention to. This course will supply students<br/> the critical tools to differentiate conspiracy theories that contribute to legacies of systemic<br/> oppression from those that call attention to such oppression. The point is not to avow all conspiracy<br/> theories, but to instead grapple with their complicated histories and the different forces they align<br/> with and challenge. Drawing upon feminist, critical race, Indigenous, and post-structuralist theories,<br/> this course will explore topics of historical oppression, legacies of colonial expansion, bio-medical<br/> interventions, corporate malfeasance, and the monopolization of decision-making power to grapple<br/> with the complex histories of conspiracy theories and what they mean for us today. Conspiracy theories work ideologically and use neoliberal globalist ideologies to traverse national borders. Examples may include "The New World Order", "The War on Christianity," and the 9-11 Tragedy. While the specific conspiracy theories covered in the course will vary, they will be examined through socio-historical contexts that cross geographic, political, and religious boundaries.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9466,2025,3279,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-206','<div class="desc"> <p>The events of 9/11 led the US to two decades of newly intensified war, occupation, and corporate engagement in the Middle East and North Africa (MENA). This changed the trajectory of politics and culture in the region, leading to the rise and fall of regimes, mass death, economic turmoil, democratic protest movements, and authoritarian political backlash. This course will analyze the modern ethical and legal grounding for war, and in particular, the Global War on Terror (GWOT). It will track the lasting-effects of decades of US and European war in the Arab World on the possibilities for thinking and living -- on the political imaginary -- of the places and people affected by those wars. How did the GWOT affect the democratic uprisings of the 2011 Arab Spring? What role did the US and the West play in fostering those uprisings and in suppressing them by supporting authoritarian regimes? And why did it make those choices? What might democracy and liberation in the MENA look like in those conditions of emergence. And finally, what is the next generation of anti-authoritarian activists doing to build the capacities, habits, and institutions necessary to bring positive liberatory change to their societies?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9467,2025,1111,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-210','<div class="desc"> <p>Why did the London Bridge fall down? Is Rub-a-Dub-Dub really about bath time? Why didn''t an old man live in a shoe? Who is more imperialist Babar or Peter Pan? Is Tinky Winky gay? Is South Park a children''s show? Is Harry Potter a Hero? How tired was Rosa Parks? Using different critical approaches this course will examine children''s poetry, picture books, novels, cartoons, feature films, and music videos. Analysis will include topics related to gender, race, culture, and nation as they play out in the aesthetics, images, and poetics of children''s texts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9468,2025,2791,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-212','<div class="desc"> <p>Students in the course will study the legal frameworks and politics of slavery, race, citizenship, and “discovery” in relation to U.S. territorial expansion and foreign intervention. Students in the course will critically examine laws, treaties, court cases, and policies used to establish racial hierarchies between “American” peoples, as well as to justify the dispossession and subordination of one or more of these peoples in order to protect slavery, property rights, and/or financial interests. Students will study the fifteenth-century Doctrine of Discovery as the basis of U.S. jurisdiction, settler colonialism, and trade in lands; the landmark case <em>Johnson v. M’Intosh</em> and its influence on the rights of Indigenous Nations and Peoples domestically and abroad; the lasting effects of the Treaty of Guadalupe Hidalgo, which doubled the territory of the United States; and the Insular Cases and U.S. imposition of second-class citizen status on inhabited island territories in both the Atlantic and Pacific Oceans, including Guam and Puerto Rico. Contemporary examples of laws and court cases, such as <em>U.S. v. Vaello-Madero</em>, will also illustrate the legacies of the U.S. imperial project’s racial violence, and will further deepen our understanding of what American property is today and how it has been constructed and legitimized by law.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9469,2025,2649,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-213','<div class="desc"> <p>The course interrogates the assumptions underlying paid and unpaid labor with respect to "women''s work" as it intersects with race, class, sex, gender, and sexuality. Drawing on a socio-critical perspective, we examine the inequalities associated with reproductive labor, child care, housework, sex work, and the ''feminization'' of certain professions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9470,2025,3529,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-214','<div class="desc"> <p>Students interested in engaging in social justice work will develop critical skills through case simulations. Through several writing assignments, students will learn what persuasive legal writing is in the United States, how it differs from other forms of writing, and how to write to serve clients’ varying needs through writing that appears objective but subjectively persuades. Students will also learn how to develop oral advocacy skills through mock intake, client rapport-building, and negotiation exercises. Through oral argument “moot” exercises, students will regularly present before a panel of two to three peers, handling questions from “the bench.” Throughout the semester, students will work collaboratively and independently.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9471,2025,1112,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-215','<div class="desc"> <p>This methods seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9472,2025,2650,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-219','<div class="desc"> <p>This course examines the scope and impact of Title IX in educational settings from its passing in 1972 to the present day. Students will explore two main areas of sex-based violations: 1) sports and discrimination and 2) sexual harassment and sexual assault. Drawing on critical theory, students will research and interpret case studies involving Title IX violations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9473,2025,2878,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-220','<div class="desc"> <p>This class explores both the concept and practical application of intersectional analysis as developed in critical race theory and critical legal theory. Intersectionality addresses the complex and shifting ways in which the discourses and practices of, for example, race, gender, sexuality, class and ability can intertwine and overlap, leading to specific modes of discrimination and oppression. Students will analyze these complex formations and the ways in which they are embedded in practices, structures and institutions of power. Reading in the course will include critical race theory, critical legal theory, feminist theory, queer theory, and readings from disability studies as well as other methodological approaches important for understanding and addressing overlapping and intersecting forms of discrimination and oppression. Students will also explore concrete ways in which intersectional analysis can be brought to bear on specific social and political problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9474,2025,2848,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-221','<div class="desc"> <p>This interdisciplinary course is designed for students considering the law as a potential career path and who are interested in developing an understanding of the relationship between inequity, the law and critical theory. Our materials will include federal and California statutes and case law, government-issued reports, and legal journal articles related to education; housing justice; police practices; consumer protection; immigrants'' rights; and other topics. This course will teach students the methods of law and policy analysis. The two main questions that will guide our critical thinking are: what is the impact of the law on inequity and what is the impact of inequity on the law? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9475,2025,3219,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-227','<div class="desc"> <p>This course considers decolonial theories of education in relation to action- and land-based knowledge. Focusing on a variety of spaces and multidisciplinary texts, this course will explore differing ways of understanding education through Native American and Indigenous approaches to knowledge and knowing, land and place, as well as social and familial relations. Students should already have a working knowledge of theories of coloniality, intersectionality, and race. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9476,2025,3838,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-235','<div class="desc"> <p>This undergraduate course in Critical Race Theory delves deep into the intricate relationship between the legal system, race, power, and social justice. Drawing from interdisciplinary perspectives within critical theory, this course examines how race has been constructed and maintained within the legal framework of the United States. By critically analyzing key legal cases, texts, and critical race theorists, students will gain a nuanced understanding of the role of law in maintaining racial hierarchies and how legal activism can contribute to dismantling them. This course aims to equip students with the analytical tools and critical perspectives needed to address the complex issues of race, law, and justice in contemporary society, fostering a deeper understanding of the challenges and possibilities for social change</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9477,2025,2331,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-250','<div class="desc"> <p>This course will examine the relationship between resistance movements and the law through several historical and contemporary United States and Latin American case studies. We will begin the semester by exploring theoretical representations of resistance movements within critical legal theory and social movement theory. We will look at different conceptualizations of power and consciousness in our analysis of resistance, and the role of each in instigating resistance movements. We will then turn to an analysis of the law as a tool of collective struggle by studying and comparing the implicated rights and site-specific needs, objectives, strategies, and outcomes of each case study. We will look at the different ways these resistance movements may use the law to mobilize followers, to frame and address collective grievance, to advance and develop legal protections for marginalized groups, and to connect their localized struggles with global ones by redefining and reimagining concepts of dignity and freedom. Each case study will also provide us with an opportunity to explore the relationship between the law, state-sponsored violence, and repression of resistance movements. We will also examine the role and influence of legal advocacy organizations in contemporary resistance movements, and evaluate the current limitations of the law in contributing to social change. How do rights-based claims (e.g. indigenous rights, water rights) obscure the relationship between law and power, injustice, and structures of oppression? Can the law be a useful catalyst for change, and/or is it necessarily a supplement to grassroots organizing and mobilizing efforts? To examine these concepts and tensions, we will look at legislation and legal practices, landmark court cases, and critical scholarship related to our case studies. Among the resistance movements we will likely study are: Brazil''s Landless Rural Workers Movement; indigenous resistance movements in North and South America, including resistance to the Dakota Access Pipeline and the Agua Zarca Hydroelectric Dam in Honduras; and different phases in the movement for black civil rights in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9478,2025,1372,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-255','<div class="desc"> <p>This course will examine intersecting and overlapping categories of "difference" by focusing on the lives of women of color. By looking at conditions that shape race, sexuality, gender, class, and cultural differences, this class will critically examine multiple discourses surrounding feminism, anti-racism, heteronormativity, and critiques of imperialism. We will consider contexts of individual and collective work for social change. Using personal essays, stories, scholarly writings, artistic works, music, film, and other media, the course will look at sources that women of color draw from to ground themselves and their activist work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9479,2025,1062,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-259','<div class="desc"> <p>This course examines movements of bodies through political, legal, economic, and social exchanges. Drawing from a variety of materials (theory, literature, film), the course examines practices such as: human trafficking, organ transplantation, transnational adoption, and surrogacy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9480,2025,1652,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-260','<div class="desc"> <p>This class examines the politics of human rights and histories of state­-sponsored violence in contemporary Latin America. By focusing on the Americas as a specific geopolitical site for our discussions, we will gain a better understanding of the main cultural, political, and philosophical debates over universal human rights. The class will also examine how culture and art can serve as a form of resistance to legacies of oppression and violence in the Americas. We will refer to critical human rights and feminist theory in order to assist our understandings of the experiences of those affected by Latin American state violence and the formation of Latinx diasporic communities in the United States. Students taking this course will gain an understanding of the histories of the region, the relationship between universal human rights, nationalism, political violence, and contemporary gender issues. The class will also refer to the limits and possibilities of human rights in the pursuit of attaining justice for state­-sponsored crimes. This course is taught in Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9481,2025,910,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-270','<div class="desc"> <p>This course looks cross-culturally at children and childhood and uses ethnographic case studies as a basis for examining the ways in which the very young participate in the social lives of their communities. The focus is on those between the ages of 5-12 and the primary topics include: children''s play, socialization, learning, political action, and productive work. We will explore the lives of children in horticultural, pastoral, rural, and urban societies in Africa, Asia, Polynesia, and the contemporary United States.</p> </div>','Any 100-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9483,2025,85,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-280','<div class="desc"> <p>This course will examine the character of postcolonial theory in the Afro-Caribbean. Particular attention will be paid to the work of C.L.R. James, Walter Rodney, Franz Fanon, Marcus Garvey, Aimé Césaire, Eric Williams, Kamau Brathwaite, and Bob Marley. The course will also examine Rastafari as a religio-political protest movement. We will chart the musicological development of reggae and dub poetry as distinctive expressions of Rasta.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9484,2025,86,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-285','<div class="desc"> <div><div><div><div><div>This course will provide an in-depth study of Foucault''s work and activism with attention to both his analyses of specific problems as well as the innovative methods he developed to address them (e.g., archaeology, discourse analysis, genealogy). His writing focuses on tracing, exposing and resisting the discourses and practices of categorization, exclusion, and control that emerged in Europe beginning in the Medieval period, through the Classical period and into the 19th CE. The course will bring these analyses to bear on contemporary problems.. Possible texts include History of Madness, Birth of the Clinic, Archealogy of Knowledge, Discipline and Punish, History of Sexuality, as well as his writings on power, art and literature. This course satisfies the Pre-1800 and Regional Focus core requirements. <div><span><br/></span></div><br/></div></div></div></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9485,2025,3301,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-290','<div class="desc"> <p>As the fastest-growing racial group in the US, Asian Americans are becoming increasingly important in the political sphere. But the rubric of ‘Asian America’ encompasses cultural identities as diverse as its political ones. This course will explore these fissures from the viewpoint of the past and present of Asian American participation in radical politics. How has the struggle for radical systemic change generated dividing lines within not only Asian American politics more broadly, but also within Asian American radical movements? How have different generations of Asian Americans developed counter-institutional spaces to advance their political initiatives? Many of the course’s readings will center on independent and ephemeral publications created by these activists, from Marxist periodicals to online feminist zines. We will touch on some key issues that have concerned these communities, including but not limited to anti-Asian racism, Chinatowns, sex work, incarceration, and internationalism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9487,2025,1007,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-295','<div class="desc"> <p>This seminar will engage important topics and issues in Critical Theory and Social Justice. All CTSJ faculty will participate in order to facilitate an interdisciplinary engagement with complexities and nuances of these topics. Students from other CTSJ courses will be invited to participate in the construction of discourse around the topics. May be repeated for credit when offered with a different topic. Different topics may fulfill different Core Requirements.</p> <p><strong>Black Popular Culture // The Black Digital Age </strong></p> <p>This class is part of a series that takes up black popular culture as a social formation structured by both the shifting conditions of antiblackness and black objection in the 20th and 21st centuries. Rather than engage black popular culture as a representational form, the course queries the peculiarity of blackness’ cultural popularity within a society where black people remain disproportionately available to gratuitous violence and early death. As such, the course interrogates the ways in which the mainstream US popular culture economy is sustained by a deeply contradictory fascination with black bodies, black sociality, and black repertoires of performance within an antiblack society and argues that consumption of black life and black expressions is a modality of the ways in which blackness is put to use under white supremacy. The course is particularly concerned with how the audio-visual is a poignant site at which visual fixations on and pathologizations of blackness collide with black peoples’ expressions of objection, self-articulation, activism, and the forging of social space. In this light, this iteration of the course, queries the possibility of the “Black Digital Age” as the proliferation of black expressions within the 2010 to present moment in the audio-visual (TV, film, and videography, including Scandal, Moonlight, Insecure, Queen &amp; Slim, Native Son, Lemonade, When I Get Home, When They See Us, Fences, Random Acts of Flyness, and countless others) and social media (Youtube, Twitter, and Instagram) realms. We ask, what political, social, and historical developments in this moment have facilitated such a proliferation of black productions within the audio-visual; what is the social, political, and historical impact of these black productions; how have black artists reconfigured black visuality as a site of desire, pleasure, restitution, and power in the face of antiblack racism as visual degregation of blackness; and how might our social criticism and genuine engagement with these texts extend the project of black life, objection, and self-articulation in the face of ongoing antiblackness? Core Requirement Met: United States Diversity.</p> <p><strong>Social Movements/Representational Forms</strong></p> <p>In this course, we will examine the competing advocacy within social movements for documentary, fiction, journalism, lyric, abstraction, and other representational forms. For each social movement or political issue that we cover, students will compare multiple modes of representation, considering why they emerged, what their strengths and weaknesses were at each specific conjuncture, and what significance they have for future struggles. We will begin with some theoretical grounding and then proceed via a set of case studies. These may include: debates about realism vs. modernism in the Frankfurt school; testimonies in Latin America; confession vs. experimentation in feminist literature; reportage vs. the essay in journalism; and slogans, songs, and posters in queer activism.</p> <p><strong>Blackness, Gender, and Sexuality</strong></p> <p>In this course, students will deconstruct, critique, and reconsider our notions of “gender” and “sexuality” by thinking deeply, creatively, and rigorously about the ways in which blackness has been both central to modern conceptions of gender and sexuality and marked as the standard of sexual and gendered deviance. Students will consider “gender” and “sexuality” as historical, socially produced, and mutable categories that are co-constituted by structures of power including race, capitalism, and chattel slavery. Importantly, the course will focus on identifying the historical conditions and structures of power that have differently gendered black bodies in the Americas. By considering the particularities of black gendering, the course will identify how notions of gendered and sexual deviance and availability to antiblack violence have been central to producing black people as a population. Through concepts such as flesh, ungendering, availability, and queerness, students be able to unpack how black bodies are gendered in terms and social relations that are in excess of a binary and are not analogous to other racialized bodies. Finally, by looking at popular and cultural objects, the class will analyze how contemporary raced and gendered structures of power affect black people and communities. Core Requirement Met: United States Diversity.</p> <p><strong>Critical Theory and Psychopathology</strong></p> <p>This experimental interdisciplinary course considers the intersection of Critical Theory and psychopathology. The goal is to examine the ways in which central insights in Critical Theory might reorient our perspective on, and interventions against, mental disorders. By way of contemporary case studies, we will examine the directive to "care for the self" (Michel Foucault), the mandate "you must change your life" (Peter Solterdijk), the problems of death (Jacques Derrida), the work of forgiveness (Derrida), and the anguish of perversions (Georges Bataille). We will also re-read chronic pain (Friedrich Nietzsche), Generalized Anxiety Disorder (Sianne Ngai), Gender Dysphoria (Judith Butler), and Intermittent Explosive Disorder (Slavoj Zizek). We anticipate the emergence of a broader more powerful view of madness. Core Requirement Met: Global Connections.</p> </div>','Any 100-level CTSJ course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9489,2025,2849,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-301','<div class="desc"> <div><p>This course provides an introduction to a broad range of approaches and methodologies used in</p><p>the interdisciplinary fields of Gender and Ethnic Studies. These methods include (but are not</p><p>limited to) archival and historical research, textual analysis, fieldwork, action research and visual</p><p>analysis. We will learn about these methodological approaches along with the foundational goals</p><p>and theoretical discussions of fields such as Latina/o Studies, Sociology, Cultural Studies and</p><p>Gender Studies to conceptualize and locate our research projects within the different disciplinary</p><p>fields that inform our scholarship. The course also considers what constitutes interdisciplinary</p><p>research and how we can implement it in our own practice. Throughout the semester students</p><p>will develop an original research proposal and conduct preliminary research by creating a corpus</p><p>of textual and visual data.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9490,2025,1155,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-311','<div class="desc"> <p>In this course, students examine contemporary child poverty, both in the United States and abroad. Topics include: how poverty is defined, both locally and globally; the numbers and distribution of poor children; as well as the causes of child poverty. Readings explore poverty in relation to education, economics, homelessness, child labor, family, gender, and race. Students analyze historical anti-poverty policies, such as: The New Deal, the War on Poverty, and the United Nations Convention on the rights of the child, as well as contemporary proposals to reduce child poverty, such as: childcare, welfare, job training, job creation, and tax policy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9491,2025,2930,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-315','<div class="desc"> <p>This course will explore the experiences of marginalized peoples in relation to race, space, and segregation, with a particular focus on Native American experiences. The racialization of space in the United States illumines various technologies of oppression and the historical creation of the so-called “Other.” Students will be required to interrogate the geographic spaces and land we inhabit and how space is socially created to serve dominant settler and white supremacist narratives. This course will explore institutional racism, segregation, and the creation of difference through discourses, policies, and laws, as well as the politics of space and sight. We will also be discussing boarding schools, the creation of reservations, Native (and POC) criminality and prisons, as well as Native histories of Southern California. There will be a strong emphasis on learning in action throughout the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9492,2025,1326,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-340','<div class="desc"> <p>In this course, students learn how to do ethnographic research and writing by conducting exercises in participant-observation on or near campus. We review the history of the ethnographic method and its relation to anthropology and the colonial encounter. We also discuss what makes an ethnography critical, and the tensions between ethnography, sympathy, and critical theory. Authors we read include Malinowski Geertz, Delmos Jones, Dorinne Kondo, Renato Rosaldo, Ruth Behar, Jim Thomas, and Kamala Visweswaran.</p> </div>','Any 200-level CTSJ class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9493,2025,3256,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-342','<div class="desc"> <p>This course examines the historical context of anti-fatness and contemporary implications of this system of bias in the US. Students will examine socially constructed meanings of body size throughout global history and contemporary meanings assigned to bodies in the US compared to other countries. Students will learn about sizeism, fatphobia, fat-hatred, and other ways in which fatness is policed in contemporary societies. Students will also study fat acceptance campaigns, fat activism, and other body size social movements through an intersectional lens. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9494,2025,2880,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-350','<div class="desc"> <p>The course will study the transformation of postcolonial theory and practice by contemporary writers and activists in the Middle East, North Africa and South Asia in response both to their new social, cultural, political, and economic conditions, as well as to their experience of the limits of earlier forms of postcolonial thought. The course will track the problems posed by the emergent concepts of identity and authenticity and the way that the modalities of melancholia and <em>ressentiment </em>can affect or undermine the postcolonial as a project of liberation. As part of this re-examination, students will explore the complex ways in which Western modes of thinking and politics — including modernism, anti-modernism, Traditionalism and resurgent authoritarian and ethno-racial political forms — shape and are resisted by postcolonial thinkers and activists. The course will advance student understanding of postcolonial theory and practice by pairing (1) a careful examination of foundational works of postcolonial thought within their historical and political contexts, with (2) an exploration of the work of contemporary scholars and activists whose projects transform and reimagine the very idea of the postcolonial.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9495,2025,2332,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-361','<div class="desc"> <p>This course centers on representations of gender, race, class, nationality, and sexuality in Latinx and Latin American film. We will examine the economic, racial, and gendered inequalities that stem from histories of colonization and neocolonialism in Latin America and in the diasporic Latinx communities that have formed in the United States. Using a transnational lens, students will assess the limits and possibilities of film in documenting histories of oppression and social inequalities facing Latin Americans and Latinx communities in the U.S. We will turn to feminist film theory, critical film theory, cultural studies, and Latin American history and politics in order to facilitate our analysis and class discussions of these films.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9496,2025,89,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-369','<div class="desc"> <p>The Clinical Psychology Laboratory (CPL) provides experiential opportunities for students interested in graduate study in Psychology, Law, or Social Justice. Students are given the opportunity to participate in the data analysis of clinical psychological assessments. Students will also participate in research on a Human Studies Committee approved project with the goal for an early exposure to the field, and with the objective to yield research data for presentation or publication. In some projects, students may have limited opportunities to observe and participate in forensic psychological assessments as prescribed in the respective protocols. Instructor interview and approval required. May be repeated three times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9497,2025,2703,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-375','<div class="desc"> <p>This course focuses on key themes and topics of Indigenous Feminisms. In particular, we will discuss how gender, sexuality, land, and sovereignty intersect in different Native communities. We ask: How do female, queer, two-spirit, gender non-conforming, and feminist Indigenous peoples persist, resist, and thrive in the face of ongoing colonial violence and erasure? How does settler colonialism intersect with heteropatriarchy, necessitating an intersectional decolonial analysis and response? In what ways does the protection/empowerment of Native women correspond to the preservation/respect of Native land? How can an Indigenous feminist epistemology change our conceptualizations of land, water, and spatiality? What does an Indigenous queer critique contribute to analyses of militarism, imperialism, and settler colonialism? </p> <p>Case studies and examples are drawn from Turtle Island (North American continent), the Pacific Islands, and Palestine. Authors to be discussed include Mishuana Goeman, Audra Simpson, Haunani-Kay Trask, and Kim TallBear.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9498,2025,2704,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-376','<div class="desc"> <p>This course will engage major concepts, theories, and intellectual inquiries in the area of settler colonial studies. We will ask: what makes settler colonialism distinct from other forms of colonialism? How does settler colonialism intersect with other systems of oppression, such as heteropatriarchy, chattel slavery, and racial capitalism? We begin by defining settler colonialism as the systematic dispossession and elimination of Native peoples via genocide, land appropriation, settler immigration, and/or cultural assimilation. We will then explore the relationships between settler colonial studies and queer theory, Afro-pessimism, and Asian diasporic studies. Authors to be discussed include Patrick Wolfe, Lorenzo Veracini, Jodi Byrd, Mark Rifkin, Jared Sexton, Frank B. Wilderson III, Ikuko Asaka, Iyko Day, Dean Saranillio, and Manu Karuka.</p> </div>','Open to frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9499,2025,514,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-384','<div class="desc"> <p>A close reading of the works of Georges Bataille, including: <em>The Impossible, The Unfinished System of Nonknowledge, The Accursed Share, On Nietzsche, Story of the Eye, The Dead Man, </em>and <em>Collected Poems. </em>First year students are not permitted to enroll in this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9501,2025,1443,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-390','<div class="desc"> <p>The Junior Seminar offers CTSJ majors a semester-long, careful and rigorous reading of a small number of important and groundbreaking texts in critical theory. Texts and themes will vary year to year. Students will work with the professor and their peers in exploring the ideas, implications, methods, modes of writing, and styles of argumentation of these texts in depth. Students will work together to create thoughtful and creative readings of these texts over the course of the semester, bringing to bear their previous work in the department and their experience and research regarding practical political and social problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9502,2025,3534,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-393','<div class="desc"> <div><div><div><span>Advanced, independent study and research in an area of critical theory and social justice initiated and guided by a faculty member. Students will work in topics and areas that are un- or under explored, or toward transforming methods or paradigms in the existing discourses or practices. Final projects will take the forms appropriate for the research (e.g., essay, policy proposal, qualitative or quantitative research) May be taken for 2 or 4 credits. Permission of instructor is required. </span></div><br/><p><br/></p><p><br/></p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9503,2025,1513,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-394','<div class="desc"> <p><em>Critical Theory and Social Justice Journal of Undergraduate Research</em> (<em>CTSJ</em>) is the leading undergraduate publication in its field, nationally. A primary goal of this course is to develop student''s preparedness and capacity to critically evaluate submissions to the <em>CTSJ Journal</em>. To that end, there are two sets of readings. All students are required to read the primary text, J.M. Balkin''s <em>Cultural Software</em>. Other readings are assigned to reflect the themes and topics of the submissions under review. In addition, this course affords students the opportunity to work closely with<em> CTSJ''''</em>s Lead Faculty Editor to understand the mechanisms of working for and advancing a research publication in the Humanities field, and produce content that is consistent with the goals of <em>CTSJ</em>. May be repeated three times for credit.<em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9504,2025,1064,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-395','<div class="desc"> <p>An advanced seminar in Critical Theory and Social Justice. May be repeated for credit with a different topic. <em>Different topics may meet different requirements.</em></p> <p><strong>White Queer Theory</strong></p> <p>This course critiques the ways in which queer theory and politics of the late 20th and 21st century have been a profound site through which whiteness has been able to reproduce and proliferate in the context of the neoliberal incorporation of raced, sexed, gendered difference into structures of capitalism and the US nation-state. As such, students will engage both the so-called critical texts of white American queer theory and texts from queer indigenous studies, black queer studies, women of color feminisms, and queer of color critique along with the burgeoning fields of black trans studies and trans of color critique that have rigorously critiqued the limits of the so-called critical texts to think [critically] about their reproduction of whiteness and the ways in with their thinking of queerness does not encapsulate the ways in which indigeneity, blackness, and other racialized formations are marked as sexually deviant, non-heteronormative, and queer, both as sexual identities and as populations. In order to thoroughly interrogate these proliferations students will engage a variety of texts that include theory, history, political movements, and popular culture — texts include the work of Foucault, Judith Butler, Glee, Paris is Burning, #ItGetsBetter, the phenomenon of Milo Yannopoulos (aka Milo Hanrahan), Christine Jorgensen, and the white queer antiblack backlash against the simultaneous passing of prop 8 in California and the election of Barack Obama as the first president; and the work Cathy Cohen, Qwo-Li Driskill, Jasbir Puar, Scott Morgensen, C. Riley Snorton, Roderick Ferguson, and other scholars who have reframed questions of queerness and its intersections with whiteness, settler colonialism, and racial capitalism through frameworks such as homonationalism, settler homonationalism, trans necropolitics, and the queerness of blackness. <em>This class counts as a methods class for the CTSJ major. Core Requirement Met: United States Diversity.</em></p> <p><strong>Whiteness</strong></p> <p>This course seeks to engage the emergent body of scholarship known as Critical White Studies (CWS). This scholarship is designed to deconstruct the racial category “white.” We will examine the historical, legal, economic, gender, and aesthetic constructions of whiteness. Particular attention will be paid to the problem of blackface. We will also critically examine CWS. <em>Core Requirement Met: United States Diversity.</em></p> <p><strong>Chattel Slavery and Its Afterlives</strong></p> <p>This course introduces students to the key theoretical and historical frameworks that elucidate the particularities of chattel slavery in the Americas both in its “pre-emancipation” manifestations and as, Saidiya Hartman notes, the ongoing machinations of captivity, domination, and dispossession by which antiblackness continues to structure and suture the world. In this course, the particularity of chattel slavery emphasizes how the economic and social function of the enslaved as laborer and commodity, the centrality of blackness as a fungible and immutable category of the enslaveable (non)human, and the massive global function of chattel slavery as the foundation of capitalism distinguishes this formation from other historical or regional structures of slavery, labor exploitation, trafficking, and racialized domination. Furthermore, students will be challenged to confront the ways in which the de jure abolition of chattel slavery (in 1865 in the US and across the Americas in the 19th century) has been a historical, legal, and structural misnomer that does not capture the ways in which societies, economies, and legal structures adapted to sustain rather than eradicate the global dependence on black subjection. Students will engage the prison industrial complex, abandonment &amp; deindustrialization, policing, geographic containment, the consumption of blackness as popular culture, formations of neoliberalism, and antiblack state and state-sanctioned terror as contemporary formations of chattel slavery’s afterlives. The course engages the geographic contexts of the US, Jamaica, Haiti, and other parts of the Caribbean. Cross-listed as BLST 375. <em>Core Requirement Met: United States Diversity.</em></p> <p><strong>Racial Capitalism</strong></p> <p>This course examines the concept of racial capitalism, or the relationship between racialist ideologies and the uneven development of global capitalism. To do this, we will explore several phases in this process of development, starting with the colonization of the Americas and the development of intra-European nationalism, then looking at the colonization of South and/or East Asia, followed by the abolition of slavery in the U.S., and finally the post World War II decolonziation and/or neocolonization of Africa. Through this, we will investigate how the capitalist world system produces ideological heterogeneity rather than universalist homogeneity. Authors to be read include Cedric Robinson, Oliver C. Cox, Immanuel Wallerstein, Walter D. Mignolo, Maria Lugones, Lisa Lowe, Ranajit Guha, W.E.B. Du Bois, Kwame Nkrumah, and Frantz Fanon. <em>Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9505,2025,515,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9506,2025,2548,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-398','<div class="desc"> <p>Working with a CTSJ faculty member, students will select an internship site whose mission is to address matters of inequality and social justice. The Department has a list of organizations where students can inquire about internships. Students who would like to intern at an organization will have to petition the department with a letter of support from the organization. The practicum experience will be evaluated by their field supervisor, the faculty liaison, and by the completion of the Social Justice Practicum Handbook. In addition to the internship responsibilities, students will participate in regular meetings with the instructor and attend class meetings. Additionally, they will complete a social justice practicum handbook, which requires deep reflection that brings the internship experiences in dialogue with critical theories related to matters of social justice. Students may participate in internships as individuals, pairs, or small groups, depending on the needs of the organizations. Open only to Critical Theory &amp; Social Justice majors with sophomore standing or above.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9507,2025,1693,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-399','<div class="desc"> <p>Students in this advanced methods course will join the professor in conducting research in the specialty areas of the instructor. This course will fulfill a methods requirement and will necessitate that the student participate with the professor and other students in a collaborative manner to meet the goals of the research project. Research methods may include: critical discourse, oral histories, archival work, ethnography, and cultural studies, quantitative analysis, interview methods. Research projects may include topics such as: (1) youth and incarceration; (2) the discourse of "war"; (3) Europe''s discourse on migrant people; and (4) literacy, language, and children, to name a few. Open to juniors and seniors only. Permission of instructor required. May be repeated once for credit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9508,2025,90,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-490','<div class="desc"> <p>Each year, the senior class in CTSJ will undertake a shared project addressing a specific and concrete political or social problem identified by the department faculty in advance of the seminar. Students will collaborate to address the problem, bringing to bear a variety of intervention modalities, including: theoretical, clinical, qualitative, critical-legal and quantitative research approaches as well as activist techniques and practices. In some years, the senior seminar may partner with a specific organization that is focused on addressing the problem taken up by the seminar. When this is the case, students will have the opportunity to work with the partner organization as volunteers. The individual student contributions to the seminar project will serve as the senior comprehensive project for the major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9510,2025,3860,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/100/cwp-135','<div class="desc"> <p>The Occidental Weekly practicum is for those who want to become section editors at the Occidental Weekly or simply want a further understanding of how daily journalism works. We will learn about ethics, management, editing and planning functions; we will not specifically study writing. Class assignments include three sets of story pitches and two news memos. The goal is for you to be ready to walk into a newsroom with an understanding of the language, disciplines, and best standards and practices. We will have occasional guest speakers on nuts-and-bolts topics, such as the use of language and the difference between news presentation in digital and in print. This is a graded course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9512,2025,3831,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/200/cwp-201','<div class="desc"> <p>This course provides students with opportunities to develop and practice the skills and habits that are foundational to academic writing and with knowledge of how to adapt these skills and habits for the varied writing demands students will encounter in college. This course fulfills (when passed with a grade of "C" or better) the college''s First Stage Writing Proficiency Requirement (and in some cases, the Second Stage Writing Proficiency Requirement), and it is also appropriate for students in various disciplines seeking to develop their writing, argument, analytic, and communication skills. All sections of this course focus on developing complex writing, analytical, and research skills for various audiences, disciplines, and genres. May be repeated to fulfill both the First- and Second-Stage Writing Requirements.</p> <p><strong>Art House Cinema</strong></p> <p>In this course, we will explore a selection of “art house” films and consider the important technical and imaginative differences between them and those made within the traditional Hollywood studio system. Selections range from low-budget, DIY independents to international masterpieces. Film analysis will be complemented by a variety of readings from some of the sharpest and most insightful critics of not only cinema but also painting, theater, music, and other fine arts.</p> <p><strong>The Body Politic: Writing in the Politics of Pleasure </strong></p> <p>This course will examine the politics of sexuality in the U.S. It aims to consider intersectional identities and cultures drawing on social considerations with respect to race, gender, and sexuality. The regulation of sexuality by the state, and the commodifying of sex will be studied as well as power and the body. Readings from Audre Lorde, Michael Foucault, and others will be explored.</p> <p><strong>Writing About Independent Film</strong></p> <p>This section will explore independent film as an important art movement and alternative to the commercial mainstream. We will focus on a small number of personal, low-budget films made outside the studio system and consider the important ways they break from Hollywood, both stylistically and imaginatively.</p> <p><strong>Rhetoric and the Fine Arts</strong></p> <p>This course is designed to provide intensive, guided training in college-level writing through the study of the fine arts—including but not limited to painting, music, film, and poetry—with an emphasis on recent work, exhibitions, and scholarship. Students will enter the current cultural conversation by writing their own critical essays, employing a variety of rhetorical techniques. Our focus will ultimately be on all the core elements of successful academic writing, including thesis statements, the use of evidence, source integration, developing and expanding ideas, and matters of form, clarity, and style.</p> <p><strong>Writing in Class, Whiteness, and Conflict </strong></p> <p>The readings and assignments in this course are designed to help students understand the social constructions of class hierarchies and the emerging theories about white identity politics, whiteness, and how race informs class analysis. We will engage in critical analysis and written argument to explore white identity, white supremacy, and the intersections of race, class and geography.</p> <p><strong>Writing, Rhetoric, and Formal Poetry</strong></p> <p>This section will focus on the relationship between poetry and rhetoric--more specifically, how form shapes understanding and is used to construct different types of rhetorical argument. We will study a variety of texts including poems, critical essays, biography, and literary and rhetorical theory.</p> <p><strong>Writing, Gender, and Sexuality</strong></p> <p>This section will explore gender and sexuality in our contemporary American context. Drawing on readings from pop culture, critical theory, current events, and literature, we will examine how gender and sexuality are constructed, theorized, and represented, and how they intersect with other areas of identity including race and class.</p> <p><strong>Wanderlust Writing and Rhetoric</strong><br/> This section will explore the writing and rhetoric of wandering and adventure, from premodern adventure stories to the present-day #wanderlust as a synonym for free-spiritedness and Instagram humblebrags; our texts will be drawn primarily from literature, pop culture, and critical theory.</p> <p><strong>Protest Writing and Rhetoric</strong></p> <p>This section will examine the rhetoric, ideology, and context of protest genres, including social movements, speeches, literature, and visual texts, as we consider how writers, artists, and activists protest issues relating to race- and class-based oppression, gender inequity, ableism, colonialism, homophobia and heterosexism, and other concerns.</p> <p><strong>Writing on Travel</strong></p> <p>This section will examine travelers'' tales ranging from pilgrimages, the Grand Tour, island vacations, luxury cruises, and scientific expeditions, analyzing them from anthropological and post-modern critical perspectives, all while exploring images and texts from the 1700''s to the present.</p> </div>','Not open to first-year students ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9516,2025,3832,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/200/cwp-275','<div class="desc"> <p>This course is designed to give students the chance to combine skills in critical analysis and writing with their interests or training in the sciences. Students do not need to have a science background or be majoring in a science field to be successful in this class, but they do need to have an interest in science in order to write about it in compelling ways. The central goal of this course is to help students develop and refine skills in presenting scientific topics to popular audiences and presenting themselves as strong candidates for graduate programs, jobs, and internships in the sciences. Course readings and assignments will span a range of scientific fields, including environment and ecology, cognitive science, psychology, medicine and health, and life sciences.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9517,2025,3833,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/200/cwp-285','<div class="desc"> <p>This course is an intensive introduction to the theories and practices of a trade that is protected by the 1st Amendment of the U.S. Constitution, essential to democracy, and yet increasingly under threat. Taught by a Pulitzer Prize-winning report, editor, columnist, and author who bolsters his teaching with distinguished guest speakers, this class introduces students to the core values and nuts-and-bolts skills demanding by the rapidly changing field of journalism, while teaching critical thinking skills that are key to global citizenship. Students will learn to research, report, interview, and then write with rhetorical force in the concise, clear newswriting style that remains the foundation of journalism in its myriad, multi-media forms. This course focuses on media influences across a range of geographical locations including Europe, Asia, Central and South America, as well as the U.S. The course will focus on regions and nations that are most in the news at the moment of the course semester. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9518,2025,3897,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/200/cwp-286','<div class="desc"> <p>In this course students will learn to combine the reporter''s craft with creative writing skills to produce compelling nonfiction. The class teaches students how accurate, factual stories can more fully convey insight into contemporary issues and the human condition by tapping the power of fictional techniques such as character development, use of dramatic tension, dialogue, and narrative structure. The course develops students'' research, reporting, and interviewing techniques, while focusing on the craft of writing. Using the spectrum of rhetorical devices, students will strive to create well-told stories about who we are, how we live, and the forces that shape our existence. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9519,2025,3834,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/200/cwp-287','<div class="desc"> <p>The 21st century has seen an abrupt escalation of government, corporate, and nonprofit institutions'' use of technology-sharpened rhetorical tools to disseminate information and, increasingly, disinformation to individuals and the public. Journalism, one of democracy''s most important forces for distinguishing truth from propaganda, has simultaneously been decimated by technological and economic change. This course offers an insider''s perspective on the theory and practice of rhetorical persuasion. This course will examine the forces that shape public opinion about recent history''s most significant issues, including climate disruption, education, immigration, and war. With a focus on opinion journalism, this course examines historical and current practices globally in examples such as Nazi and Stalinist propaganda in WWII, to international discourse on Vietnam, Iraq, and Afghanistan. Students will learn to write and critique editorials, op-eds, blog posts, and strategic communications'' plans driven by social media messaging, while scrutinizing the shared interests and deep tensions between journalism and public relations, publicity and marketing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9520,2025,3835,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/200/cwp-295','<div class="desc"> <p>This class will engage the historical theoretical and cultural dimensions of rhetoric in a range of disciplines in the arts literature politics and philosophy. In readings from Aristotle to poststructuralist theory we will examine all aspects of the rhetorical situation (exigence audience and rhetor) and the contexts in which rhetorical acts occur. We will examine how language practices intersect with culture and identity including class race sexuality gender and nation as we consider how arguments are constructed and how writing and narrative transform culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9522,2025,3899,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/300/cwp-301','<div class="desc"> <p>This advanced composition workshop explores creative nonfiction, a term that encompasses many genres, including memoir, profile writing, personal essay, humor, nature and travel writing, criticism, and narrative journalism, among others. This course will focus on 3-4 genres of creative nonfiction over the course of the semester. Each unit will pair a writing assignment in a particular genre with popular readings from that genre, by authors such as Paula Gunn Allen, Truman Capote, Ta-Nehisi Coates, Junot Díaz, Joan Didion, Audre Lorde, Adrienne Rich, Zadie Smith, and David Foster Wallace. The course will encourage experimentation while also paying close attention to audience, genre conventions, and other principles of successful writing. The workshop format relies on extensive peer review and revision, and each student will produce a capstone piece at the end of the semester after revision based on peer and instructor feedback. </p> </div>','Student must have passed the first-year writing requirement and/or CWP 201 (formerly WRD 201). ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9524,2025,3836,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/cwp-college-writing-program/300/cwp-395','<div class="desc"> <p>An exploration of the theory and practice of writing instruction, this class emphasizes rhetorical strategies, audience expectations, and forms of academic discourse. This course also provides new advisers with an introduction to tutoring practices and strategies through Writing Center scholarship. Permission of instructor required.<em>This class is only for Peer Writing Advisers working in Writing Center. </em><em>May be repeated once for credit. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9526,2025,120,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-101','<div class="desc"> <p>The purposes of this course are: (1) to introduce fundamental tools and perspectives on the study of world politics, including major theories and analytical approaches to international relations, (2) to understand the historical evolution of the contemporary international system, with special emphasis on the post-World War II era, and (3) to apply theoretical and conceptual understandings of international relations to current issues in world politics. Emphasis is placed on the state and trans-state foundations of contemporary international relations. We will study this in the context of such key issues as economic development, "security," human rights, state-building, international organizations, terrorism, and the intersection of social relations with world politics. Open to first years and sophomores. Permission of instructor required for junior and senior enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9527,2025,1655,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-102','<div class="desc"> <p>A survey of the role of international organizations in global politics. The focus will be on an in-depth study of the three themes by which the United Nations has defined itself: security, human rights, and development. Within the rubric of those three themes we will look at activities by the U.N. family of agencies, other international organizations, and NGOs, on issues that include the management of violent conflict, human rights, and how these issues have been mainstreamed into the work of international organizations and approaches to economic underdevelopment that seek to alleviate both poverty and insecurity.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9528,2025,2549,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-103','<div class="desc"> <p>This course is an undergraduate survey of the field of Global Political Economy (GPE), required to major in Diplomacy and World Affairs. It is intended as an introduction for students who already have some background in the field of International Relations (DWA 101) and are interested in exploring global political economy theories, relations and issues. The course covers major theoretical, empirical and policy perspectives. The first part of the course will cover basic concepts and theoretical foundations of political economy: liberalism, Marxism, realism, feminism, etc. The focus will be on core theoretical principles and approaches. The goal is to understand how theory is framed and how it "works"; the potential inferences of theories, and their practical import. The second part of the course delves into globalization as a field of study and set of empirical dynamics, building on the theoretical foundations of the first part of the course. The third part of the course explores emerging topics in global political economy such as global finance, the informal economy, the underground economy, the green economy/sharing economy/circular economy, gender and the global economy, corporate citizenship and responsibility, social enterprises, the sustainable development goals, social/economic rights and more. Open only to DWA majors; for non-majors, special permission of instructor required.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9529,2025,1444,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-152','<div class="desc"> <p>This course will introduce social enterprise practices and theory while allowing students to work directly on a social enterprise project with global impact. This course will build on the 25-year foundation of collective knowledge in the field of Social Entrepreneurship through case studies and life challenges that continue to face the international community. We will look at how value creation and sustainability are key elements in the development of successful social enterprises, with emphasis on water, food, and housing/urban design. Our focus will be on how, through innovation and entrepreneurial approaches, we can access sustainable solutions to the world''s most pressing problems.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9533,2025,1588,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9534,2025,2333,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected what was historically the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean that has developed into proper noun: the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological, and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the 20th century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-1939 Palestinian Revolt, the 1948 war for Palestine and its aftermath, Israeli-Arab relations in the 1950''s, the Suez War, the implications of gendering the nation, the 1967 war and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9535,2025,2850,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-210','<div class="desc"> <p>This course introduces students to the history, politics, and international context of Russia and other countries of the former Soviet Union. The course focuses on the political and economic transformation in post-communist Eurasia after the fall of the Soviet Union in 1991. We investigate the nature of domestic political systems of post-Soviet state, state-society relations, ethnic conflict, politics of economic reform, and the underpinnings of foreign policy-making in these countries. Students will learn about the region using the comparative method by engaging in reading and writing assignments that will require comparing outcomes of student’s choice both cross-nationally or temporally.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9536,2025,3902,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-219','<div class="desc"> <p>South Asia is a region with a rich political history, offering recent examples of independence movements, secular democracies, absolute monarchies, and military dictatorships. Bound by the Himalayas to the north and the Indian Ocean to the south, the region comprises eight developing and emerging nations â Afghanistan, Bangladesh, Bhutan, India, the Maldives, Nepal, Pakistan, and Sri Lanka. Each of these eight countries has a unique political trajectory that continues to be deeply informed by the political reality of its neighbors. This course offers a comprehensive introduction to the comparative politics of the region, with a focus on four key characteristics: the colonial legacy in shaping South Asian political institutions, the intraregional relationships including those that have escalated to violent conflict and war, the political economy of development, micropolitical processes that shape democratic outcomes and the future of democracy in the region.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9537,2025,827,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-221','<div class="desc"> <p>Against the backdrop of 840 million persons worldwide suffering from malnourishment, and nearly 1.3 billion people living on less than a dollar per day, this course surveys the fields of international development, wealth creation, and global welfare, from a historical, global, and comparative perspective. The course will introduce students to the field''s academic contours, building from the historic role of economics in pioneering and undergirding the field, to a broad understanding of the now interdisciplinary field that has emerged. The multi-disciplinary and interdisciplinary perspective of this introductory survey course is in keeping with an emerging global consensus that measures of poverty go beyond income and consumption, and that poverty reduction requires bridging disciplines (Economics, Political Science, History, Anthropology, Geography) and methods (quantitative and qualitative, observational and participatory). The course will be divided into two parts. During the first part of the course, students will be introduced to the main theoretical ideas on social, economic, and political development that have informed the field''s evolution. This will familiarize students with fundamental thinking on development, as well as the frontiers of research. The second part of the course will explore some of the current debates about development. Students will analyze such debates in a rigorously multi-dimensional and interdisciplinary manner.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9538,2025,2425,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-222','<div class="desc"> <p>This course introduces students to the political economy of Latin America. The first section of the course looks at the rise of dependency theory and import substitution industrialization (ISI) as the region''s predominant development strategy. We will study the motivations behind ISI, its initial success in terms of economic growth, and the challenges associated with such strategies of development. We will focus on the origins of the 1980''s debt crisis, the abolishing of the ISI model, and the subsequent turn to neoliberal development strategies. The course aims to provide students with a deeper understanding of the transition to neoliberalism, the so-called Washington Consensus, and the broader political and economic implications of the reform processes that have unfolded since the early 1980''s. We will study the interaction between democratization and economic reform and aim to understand how these simultaneous transitions have affected the policy-making process and the formation of public policy in the region. Latin America is a diverse region; therefore, this course will emphasize its economic and political diversity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9539,2025,1587,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-224','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century, with a focus on contemporary democratic politics. The course will discuss the historical, institutional, and social forces that have both accelerated and opposed democratization, and will cover topics of current concern to the region, including: economic development, security and the rule of law, the design of political institutions, human rights, and social movements.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9540,2025,1213,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-225','<div class="desc"> <p>This course offers students an interdisciplinary introduction to the historical and philosophical foundations of human rights, the creation of the international human rights regime in the mid-20th century, the impact of social movements on the evolution of international human rights laws and norms, and the impediments to the realization of human rights in practice. Through exploring thematic concerns such as women''s rights, LGBT rights, torture, capital punishment, international responses to genocide, and corporate responsibility, we will engage contemporary debates surrounding the universality of human rights, the relationship between human rights and inter/national security, the duty-holders of human rights law, and the gap between human rights ideals and enforcement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9541,2025,2334,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-226','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal," "populist," and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems, including the United States; and the challenges democracies are facing in integrating formerly marginalized populations, including women, poor, and the indigenous. It will examine the United States policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9542,2025,2826,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-227','<div class="desc"> <p>Thirty years after Francis Fukuyama proclaimed the "End of History," political authoritarianism remains viable while democracy is increasingly under threat around the world. Many dictators have embraced hypermobility of capital, free trade, and modern information technology. At the same time, deepening globalization has also challenged long-established democratic systems, producing anti-democratic political movements. We will investigate some of the following questions produced by the clash between global capitalism and local politics: How do authoritarian leaders react to the challenges of globalization in the 21st century? Does globalization undermine or enhance their hold on power? Will authoritarianism or democracy survive a long-term engagement with global markets?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9543,2025,2335,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-228','<div class="desc"> <p>This course explores efforts to conceptualize democracy, and to generate and test theories of democratization and the endurance of democracy. After considering the concept of democracy, we start by considering some of the classics, published in the second half of the 20th century. These are key works that have shaped the field and have largely set the terms of the debate. Then, we turn to the literature published after 2000 and consider how this literature has revised and built on ideas from the classics. We conclude with an overall assessment of knowledge about democratization and the endurance of democracy. In all, we will discuss explanations that put an emphasis on the economy and culture, as well as on politics itself. Much of what we will read reflects the focus of this literature on Europe, Latin America, and post-Soviet Eurasia. However, some African and Asian cases will be discussed and several global analyses will be considered. Emphasis will be put on the core theoretical and methodological aspects of this literature.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9544,2025,1327,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-229','<div class="desc"> <p>After a review of the historical, legal, and conceptual underpinnings of the international protection of human rights, students in this course will learn about human rights and mechanisms for their protection within the context of the United States and Latin America. Students will discuss key situations from the last half century involving challenges to human rights, including the phenomenon of disappearances common in Argentina and Chile in the 1970''s, violations of human rights during leading up to and during civil conflicts in Central America, and the impact of neoliberal economic reforms on human rights in the region. Students will explore the application of the death penalty in the United States, United States foreign policy on human rights in the Americas during the Cold War, and the claims of human rights abuse by the United States during the War on Terror. They will also have a chance to examine the United States from a double perspective: on the one hand as a key country with a major interest and impact on human rights conditions in Latin America, and, on the other, as a country with its own policy areas of struggle and progress.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9545,2025,548,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-230','<div class="desc"> <p>This course will explore the evolution of women''s rights as human rights; the struggle of women''s movements to place gender-specific concerns on the international human rights agenda; and the relationship of the UN and its agencies to the broad feminist goal of advancing the political, economic, social, and cultural status of women. While "women" are, of necessity, central to the concerns of this course, the study of human rights will be approached from a gender perspective, recognizing that gender relations are key to understanding the nature, occurrence, and prevention of rights violations. Key themes to be covered in the course include: the relationship between the "crisis of masculinity" and women''s human rights, gender and economic rights, gender-based violence, and health and human rights.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9546,2025,1115,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-231','<div class="desc"> <p>This course explores how assumptions of masculinity and femininity have informed foundational concepts and theories in the field of International Relations, the determination of what is considered to be worthy of investigation and what qualifies as appropriate methods of investigation, and who is (and is not) recognized as a subject of international politics. This course applies a gender lens to practical concerns in the field, including: political and economic development, human rights, and international security. It also engages the tensions associated with theorizing gender and IR, given the fluidity and intersectionality of identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9547,2025,1328,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-232','<div class="desc"> <p>Topics may vary semester to semester. </p> <p><strong>Transnational Social Movements</strong></p> <p>This course focuses on contemporary social movements with particular attention to transnational information flows. Concentrating on strategies, methods, and approaches to oppositional action, the course will study the global rise in the civilian mobilization against leaders and states perceived as corrupt and or unrepresentative. For example, organizations like <em>Black Lives Matter</em> have influenced and were influenced by <em>Rhodes Must Fall</em> in South Africa. Similar movements in Serbia, Egypt, China, Czechoslovakia, and Iran where unarmed people opposed powerful states encouraged the student protest movements in Hong Kong. Writers like Gene Sharpe, Erica Chenoweth, and others who have written extensively about non-violent means of protests, have influenced many of these contemporary organizations. Academic perspectives on social movements and revolutions will frame the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9548,2025,549,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-234','<div class="desc"> <p>Revolutionary transformations and democratic transitions in Southern Africa have occurred under the conditions of the Cold War and within the framework of heightened globalization. Currently, direct foreign political interventions have been scaled back, but economic interventions by international organizations and foreign states have increased. Even though liberal democracy is winning favor the structural basis of inequality remains with increasing unemployment, poor education, weak health services, inadequate housing, soaring food and utility prices, and increasing levels of poverty. Opposition movements demand changes ranging from subsidized basic foodstuff to free education. This has contributed to political tensions as states scramble to suppress resistance while still trying to maintain the conditions required by global economic institutions. This course will examine some of the states in this region including South Africa, Mozambique, and Zimbabwe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9549,2025,123,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-235','<div class="desc"> <p>This course will explore nationalism and ethnicity from both a theoretical and an empirical perspective. Nationalist and ethnic discourses have been central to political movements, rebellions, and revolutions. The passions and commitment of individual members in these movements often lead to political ideologies and war tactics that are violent, and which encompass entire communities. The class will concentrate on two theoretical perspectives; mainly the debates between primordialism and constructivism. Two cases from South/Southeast Asia and Sub-Saharan Africa will be analyzed.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9550,2025,1589,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-236','<div class="desc"> <p>This course examines the theoretical roots, ideological expressions, and political manifestations of these tumultuous phenomena. Focusing mostly on the European experience of the late 19th through the 20th century, we will read primary texts and historical accounts pertaining to the rise and development of nationalism, communism, and fascism. Readings will cover both the national and international aspects of these movements, and explore their political, cultural, and economic programs. What will also be of particular interest is how these often competing and clashing political programs sprang from similar and, at times, common roots. Ultimately, this course will ask students to consider what the study of such ideologies has to offer for the analysis of contemporary extremism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9551,2025,917,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-237','<div class="desc"> <p>The course will examine some of the communist countries that have survived the collapse of the Soviet Union, specifically: Cuba, Vietnam, and China. We will discuss the political and social life within each country, their relationship to the United States, and the prospects for political change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9552,2025,124,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-238','<div class="desc"> <p>This class will focus on South Asians who were indentured to British colonies from 1860, immediately following the abolition of slavery. Over one million Indians were indentured to Mauritius, South Africa, Guyana, Trinidad, and Fiji. South Asians currently constitute a substantial proportion of the population in each of these countries, and they are in the majority in Mauritius and Trinidad. We will conduct a comparative study based on theoretical perspectives related to the diaspora''s globalization, trans-state identities, and analytical themes associated with identity and citizenship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9553,2025,1656,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-239','<div class="desc"> <p>This course aims to introduce students to the history, politics, and economics of the European region from 1945 to present day. We will start by looking at the development of European states and political institutions in the post-WWII period, primarily those of Germany, France, the United Kingdom, and the Benelux countries. Our goal is to gain understanding of why European states have taken different political paths (including countries in Eastern Europe, the Nordic states, and Turkey), while also exploring the context of regional integration in which European states are embedded. The European Union (formerly the European Community) and its 28-member states are thus also central to this subject, as it encapsulates the development of key political institutions, civil society, representation, and economics on the continent. We will thus explore what has been accomplished by European integration (e.g., maintaining peace, increasing mobility, granting human rights, enhancing multilateralism, and strengthening democracy), as well as the considerable challenges that lie ahead (e.g., "Brexit", eastern enlargement, the stability of the Euro, the integration of refugees, and the rise of populist parties). In sum, the course is designed to introduce students to central topics in both past and contemporary Europe politics through the lens of political science and theories of regional integration. Situated at the intersection of comparative and international politics, these theories will help us to understand the complex interactions between national governments, supranational institutions, and the everyday lives of European citizens that define Europe today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9554,2025,2426,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-240','<div class="desc"> <div><p>Colombiaâs 2016 peace accord formally brought an end to a half-century of that countryâs civil wars. The accordâs implementation, however, has been troubled. This raises issues relevant to Colombia and to other locales putatively transitioning out of violent conflicts. This course will address those issues in a Colombian context and by comparative reference to examples from other countries in the Americas and around the globe. Specifically, what is transitional justice and how might it inform peace-making in a country such as Colombia? Are human rights relevant to more effective transitional justice processes? More specifically, can they inform a truth-telling processes that takes into account the distinct context of a country such as Colombia and helps it establish the basis of a more pluralistic social contract that engages all of its remarkable diversity, including identities (ethnic, gender, sexual) that have long been marginalized? The course uses Colombia as a focal point, but will draw from other comparative cases both from Latin America and the globe.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9555,2025,125,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-241','<div class="desc"> <p>A study of Middle-Eastern international relations in the context of three themes that structure the region''s modern political history: (1) colonialism: how the reaction against colonialism continued to define and limit Middle-Eastern politics, both internally and in its relations with outside powers, (2) religion: in particular, political Islam (or "fundamentalism") is a key variable in the region''s contemporary politics, but by no means all-defining, and (3) nationalism(s): a source of political identity and mobilization. How religious, national, linguistic, and ethnic nationalisms inform conflict and cooperation within the region. </p> <p>In the context of these three themes, we will explore the following regional issues with global implications: (1) the Arab-Israeli conflict - the flash point of conflict in the Middle-East, the Arab-Israeli conflict can only be understood on the basis of an informed appreciation of its historical and ideological underpinnings, (2) Iran - the Iranian revolution had an enormous impact on regional and international affairs. Current unrest within Iran is perhaps a harbinger of yet another radical shift in Iranian politics, and (3) domestic upheaval in the region, as seen in the Arab uprisings of 2011-2012.</p> <p>Despite this being an "IR" class, on-the-ground social and political movements ("domestic," yet transnationally informed) have an enormous impact on the region''s politics. This is particularly true in the shadow of the recent Arab uprisings, upon which we will place particular attention.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9556,2025,1590,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-245','<div class="desc"> <p>This course will look at the relationship China has had to the world over the last 600 years. The course will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Third-Worldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the interaction between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the rise of the West, just as we will call into question the contemporary discourse on the "rise of China."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9557,2025,2537,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-246','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9558,2025,1377,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-248','<div class="desc"> <p>This course will examine major global public health problems and the range of responses from international organizations, transnational networks, and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century, the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as: HIV/AIDS, malaria, unsafe food and water, tobacco use, and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health, including morbidity; mortality; demography; epidemiology; and the political, social, and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political, economic, social, and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health, and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9559,2025,828,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-250','<div class="desc"> <p>This course is an introduction to International Security and Strategic Studies. This field is, fundamentally, about both the use of force by, and violent conflict among, states and non-state actors. The course will be guided by general theoretical questions regarding security: how does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: how do states and non-state actors use force to persuade their enemies to take (coercion), or refrain from taking (deterrence), a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure and the intensity, duration, and consequences of military action? We will have a particular focus on emerging transnational security issues, intra-state security, and the relationship between security development and state failure. Pursuing answers to these questions will require an approach that integrates theory, history, and current events. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9560,2025,1445,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-253','<div class="desc"> <p>China''s return (as opposed to rise) to its proportional place in the global economy has arguably caused a pivot towards Asia by the United States. While America''s hegemonic status in terms of hard (military) power remains undisputed, China''s gross domestic product may surpass that of the United States as soon as 2017. This course is a seminar on Asian security, covering military security, non-traditional security, and economic and political security, among other dimensions. The course surveys the Asian region, with particular emphasis on Southeast Asia (the ASEAN countries, particularly Cambodia Burma/Myanmar, Thailand, and Singapore) and Northeast Asia (China, Japan, South Korea, and Taiwan). The material is divided into three parts. The first provides an overall introduction and overview of Asian security and focuses on the foundations of what was thought to be the Asian Miracle (created in part from a U.S. security umbrella), just as the Washington Consensus rose to prominence. It takes students through the Asian Financial Crisis and its aftermath. Part two of the class focuses on Japan, South Korea, China, and Taiwan. It describes their development trajectories and security arrangements. Part three uses China as a platform to examine other parts of Asia not already covered, such as: China''s relationship with Southeast Asia, and the political economy of non-traditional security, in particular the region''s experience with Highly Pathogenic Avian Influenza.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9561,2025,1694,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-256','<div class="desc"> <p>This course analyses terrorism not only from a state security perspective, but also from one informed by political ethics, in which we seek to come to terms with the demands of justice in an age of violence resulting in large numbers of civilian deaths by both state and non-state actors. Broad questions include: what is terrorism? What are its causes? What are its consequences? Do terrorists operate from internally consistent and intelligible (even if horrific) frameworks? Must we sacrifice some of our cherished civil liberties in order to protect others? And what international, moral, and legal principles should guide us in an age of cyber warfare, drone strikes, and targeted assassinations?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9562,2025,2623,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-257','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? When and how to movements spread and diffusion their ideas globally? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention in various moments of time, while developing the conceptual skills that provide an introduction to social movement theory. In doing so, we will take an in-depth empirical look at movements for civil rights, women’s rights, LGBT (lesbian, gay, bisexual and transgender) rights, and immigrant rights. An analysis of these movements across multiple domestic and transnational contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9563,2025,2589,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-258','<div class="desc"> <p>In many countries, the subject of LGBT (lesbian, gay, bisexual and transgender) rights has entered the political discourse with unprecedented speed and suddenness. For an issue that was most often relegated to the private sphere, the rapid global expansion of LGBT rights, as well as changes in public opinion toward LGBT people, has been nothing short of remarkable. This course is designed to gain leverage on the processes that explain such changes by surveying an eclectic literature on comparative and transnational LGBT politics: from social movements to normative change in international relations. For these fields of study, the changes addressed above pose several important questions. It is no coincidence, for example, that dozens of countries now grant some form of same-sex unions, and understanding transnational politics helps us understand why. Specially, we will ask: What factors have facilitated the mobilization of LGBT people? Why and how have public opinion and state laws towards LGBT people changed differently across various countries?</p> <p>To find answers to these questions, we will analyze the political history of a movement that has captured the world’s attention, and one that has moved a marginalized group from the political periphery to the center of public debate and contestation. We will take an in-depth empirical look at movements representing LGBT people and their successes/losses—as well as those of their opposition—across time and place. The first portion of the course will begin with the organized movement’s earliest roots in early 1900s Europe, followed by suppression during WWII, and then the homophile movement of the post-war period. The remainder of the course explores the public manifestation of LGBT identities that grew out of the Stonewall’s gay liberation politics, mobilization around the HIV crisis, and the domestic and international politics surrounding the spread of LGBT rights and recognition in contemporary times. An analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts offered by social movements and international relations scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9565,2025,551,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-260','<div class="desc"> <p>Research, discussion, and analysis of important issues in International Relations in preparation for a three-day college conference in early April. Student delegates role play as ambassadors for countries and present views negotiating with other representatives and arguing for possible resolutions in a simulation of the United Nations. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9566,2025,3312,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-270','<div class="desc"> <p>Effectively tackling global challenges such as climate change, pandemics, nuclear proliferation, and the decline of democracy and trade liberalization, to name just a few examples, is not reducible to the interests and preferences of the United States. Indeed, most outcomes in global politics never are and have never been. Other countries have interests and preferences of their own, and those influence international outcomes as well. Why, for instance, does it make sense for North Korea to have a nuclear arsenal despite US interests to the contrary? And for China to try to become a hegemonic power in East Asia despite the US decades long presence in the region? Why is Putin''s Russia pushing so hard against NATO’s eastward expansion? And Latin America against U.S. influence in the Western Hemisphere? International affairs look fundamentally different when assessed from a non U.S.-centered perspective. And, history shows, U.S. interests are best served when they, at the very least, take into consideration other actors'' interests and preferences and where these may come from. This course will provide students with the analytical tools necessary to start unpacking any country''s interests and foreign policies, as a first step towards recognizing that satisfactory answers to current and future global challenges require the active acknowledgment of all actors'' preferences with stakes on the matter, no matter how "powerful" the United States might be.</p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9567,2025,829,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-280','<div class="desc"> <p>This course explores the various facets of the globalization process and the politics of development. The first part of the course examines globalization, its causes and wide-ranging consequences, and its implications for U.S. domestic and foreign policy as well as for global governance. Has globalization benefited East Asia, Africa, and Latin America? What have been the differing impacts on those regions? Questions that will be addressed include: what are<br/> conceptual perspectives on globalization? What are the economic, cultural, and political dimensions of globalization? What are policy responses to the challenges globalization presents? The second part of the course examines the politics of various approaches to development and poverty reduction. This will include exploring how globalization is related to development, understanding current debates over foreign aid, and evaluating new and innovative strategies aimed at poverty alleviation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9568,2025,830,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-282','<div class="desc"> <p>A critical examination of greater Los Angeles and its economic, political, social, and cultural ties to the world economy and other countries--all the ways in which Los Angeles is an integral part of the post-Cold War global society. How does this globalization affect the life of Los Angeles and in what ways does Los Angeles contribute to globalization? What are the positive and negative impacts and the implications for United States foreign, economic, and social policies of Los Angeles as a Global City?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9569,2025,1215,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-283','<div class="desc"> <p>This course will study how the concept of soft power - first developed by Harvard professor Joe Nye - applies to interactions among nations in the 21st century. Soft power lies in the ability to attract and persuade, whereas hard power - the ability to coerce - grows out of a country''s military or economic might, especially in an imperial/colonial period. Students will analyze how trade, culture (music, food, sports, language, education), environment, and political institutions (democracy, corruption, human rights, etc.) contribute to a country''s soft power and make up its global brand. Students will analyze the current state of soft power in key nations and consider how countries and their citizens can affect the attractiveness of a country''s culture, ideas, and institutions in order to raise its soft power. The course will introduce students to the idea of global sustainable diplomacy, which pursues global goals using soft, not hard, power.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9570,2025,1066,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-284','<div class="desc"> <p>A critical examination of the political and economic role that sports play in the globalized world - the diplomatic, political, and economic effects of the Olympics, the World Cup, other international sporting events, and the increased globalization of professional sports leagues across national boundaries. A look at case studies of ping-pong diplomacy, rugby reconciliation in South Africa, and soccer wars in Latin America, as well as an analysis of the impact of foreign players on national economies and societies, from American baseball players in Japan, to Russian ice hockey players in the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9571,2025,1330,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-285','<div class="desc"> <p>This course aims to introduce students to both analytic and normative approaches to the study and practice of diplomacy in international politics. In the first part of the course, we will chart the evolution of diplomacy from a tool of statecraft in the modern states system, to a practice of mediating disputes and estrangement in international society. The second part of the course is devoted to examining a series of historical case studies illustrative of the successes and failures of modern diplomacy. The last part of the course considers the utility and limitations of contemporary diplomatic practices for major international trends and developments, such as: globalization, militarism, financial crises, extremism, and environmental degradation. This course is, above all, designed to help students think, talk, and write in an informed and critical manner about complex and seemingly intractable global issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9572,2025,1514,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-286','<div class="desc"> <p>This course will look at the use of public diplomacy in the United States since the end of the 19th century. The concentration will be on U.S. public diplomacy towards Latin America and the Caribbean, Latin America-China relations, and Latin America''s relations with the rest of the world.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9573,2025,1696,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-288','<div class="desc"> <p>This course examines the major challenges of our environment and its relationship to politics and policy issues. We will cover topics addressing the normal functioning of the Earth, including the water cycle, carbon cycle, and the atmosphere. We will concentrate on the behavior of humans that affect these processes. We will tackle issues of state development, particularly industrialization and its consequences (including the increased use of fossil fuels, pollution of water, widespread deforestation, climate change, etc.), and their effects on the environment in which we live. We will discuss these problems and consider solutions at the international, national, local, and personal level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9574,2025,1515,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-290','<div class="desc"> <p>This class looks at global issues - including energy development, climate change, satellite imaging, and forms of communication - that have technical aspects. We then take these topics and place them in the cultural, political, and economic international context: how are states, non-state actors, international organizations, and non-governmental organization handling these issues?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9576,2025,127,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-295','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>A World Without War</strong></p> <p>The seminar will begin by examining various theories and explanations for the<br/> reasons of war. Are wars inevitable? What are the basic differences between<br/> wars in pre-modern and in modern times? Are rising powers or rivals destined to<br/> clash at some point, with devastating consequences for both sides and beyond?<br/> How can one minimize the chances that wars âbreak outâ? Can diplomacy help to<br/> prevent wars? What is the role of mediators or supra-national organizations?<br/> What characterizes good, effective peace negotiations? In order to answer these<br/> questions or at least shed significant light on them, we will look at some major<br/> junctions in world history and study the concepts which have been developed to<br/> secure peace.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9579,2025,831,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-299','<div class="desc"> <p>The goal of this course is to provide students with some of the tools to embark on systematic inquiry in Political Science. It will introduce students to qualitative methods in Political Science; ethical issues in qualitative research, proposal writing, and interviewing techniques; and finally, the essential components of a research paper (a proper research question, thesis, literature review, and case selection). Guidance through the Institutional Review Board process will be provided. This course is geared towards students preparing grant applications, preparing to conduct research abroad, and/or preparing for their Senior Comprehensive thesis since they will be expected to apply the methods they learn to their own research topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9580,2025,1010,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-310','<div class="desc"> <p>As of late, religion has re-emerged on the political stage, offering different perspectives regarding political norms, values, and behavior. In this course, we will explore the various ways in which religion has been conceptualized and utilized in different political and cultural settings. Some of the questions that we will seek to answer are: in what ways can religion be separated from politics? What are the roles of religion and religious institutions in political life? How do religions and religious institutions respond to the challenges of a pluralist and secular modern world? Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9581,2025,2931,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-320','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature (from various disciplines) on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention across various moments in time, while developing the conceptual skills that provide an introduction to social movement theory in international relations. A comparative and transnational analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work. </p> <p>This course is also intended to improve your writing and research design skills. In academic scholarship, engaging an interesting topic—in our case, social movements—combined with a tool kit of well-developed methodological and writing skills is essential for articulating ideas to a wider audience. Most social science disciplines necessitate the ability to present evidence pertaining to an issue, engage with counter evidence, and ultimately present a convincing argument for a particular position on that issue. Under the rubric of writing broadly for multiple academic disciplines and popular audiences, we will engage several stages of the writing process, which include: (1) note taking and careful analysis of relevant texts; (2) proper use of secondary and primary sources, as well as citation style; (3) drafting texts; (4) revising and peer review (both in class and individually with the instructor); and (5) presenting a polished final research design paper that uses effective grammar, punctuation, and style. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9582,2025,1067,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-329','<div class="desc"> <p>Trafficking in persons - the use of force, coercion, fraud, or deception for purposes of exploitation - is the third most profitable form of illicit activity, globally, following the traffic in drugs and arms. In this course, we will explore the different forms of trafficking, including domestic servitude, sweatshop labor, migrant agricultural work, and child soldiering, although the course will focus most closely on the topic of trafficking for purposes of sexual exploitation. Throughout the class, the causes, consequences, and responses to trafficking will be analyzed through a human rights lens. We will study the processes behind the construction of gender identities in order to gain insight into why particular populations are especially vulnerable to trafficking, and why certain constraints exist to prevent and respond to trafficking at both the domestic and international levels. We will study the relationship between trafficking and militarism, including the legacy of the United States'' military presence in Asia for sex tourism, and trafficking in the region today. And we will engage the debate over whether trafficking is a "discourse" that perpetuates relationships of dominance and subordination between the global North and South. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9583,2025,1697,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-332','<div class="desc"> <p>A digital exploration using mapping techniques to study the movement and political engagement of over 1.3 million Indians who were indentured from India to various British colonies between 1833 and 1920. They currently constitute either large majorities or strong minorities in these former colonies. Some of the countries that will be studied include Fiji, Trinidad, Mauritius, and South Africa.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9584,2025,1446,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-335','<div class="desc"> <p>African theorists have historically integrated theoretical critiques with revolutionary practices. This class will focus on theories pertaining to opposition to colonialism in Africa, as well as in the Caribbean and the United States. Theorists such as Franz Fanon, Steve Biko, Kwame Nkrumah, Eric Williams, and Marcus Garvey will be studied. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9585,2025,919,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-337','<div class="desc"> <p>The purpose of this course is to explore international relations theory in depth. Students will be asked to engage with the canonical writings on IR theory and their critics. They will evaluate and reflect on how different theoretical perspectives can explain, critique, and even guide the actions of individuals, institutions, and states in the international arena. The ultimate objective is to understand how the assumptions and priorities of different theoretical traditions have real-world implications for diplomacy and foreign policy-making. <strong>The course will be run as a seminar, so extensive writing, reading, and participation from students are expected</strong>. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9586,2025,129,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-340','<div class="desc"> <p>International law has taken an increasingly central, and often controversial, place in contemporary international relations. This junior writing seminar will explore the foundations of international law, human rights law, and humanitarian law. It will do so in the context of their intersections with topical issues that range from international criminal law, torture, non-state transnational actors, humanitarian interventions, and sexuality, and will have a particular focus on the theoretical foundations for human rights. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9587,2025,552,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-342','<div class="desc"> <p>This class will explore the various aspects of transnational identities, focusing on ways in which they challenge state borders and state nationalisms. The various aspects of transnational identities, like questions of citizenship, ethnicity, religion, gender, and generation will be analyzed. Special attention will be given to the ways in which Islamic beliefs have transcended state boundaries and the impact this has had on notions of citizenship. The class will also focus on a few case studies to highlight the various aspects of transnational identity. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9588,2025,2434,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-344','<div class="desc"> <p>Post-conflict reconstruction in the wake of war and state-building have been prominent activities in international security. The international community now addresses non-state conflict with vigorous programs of state-building. Former President George W. Bush writes in his biography “Afghanistan was the ultimate nation-building mission.” The prevailing post-conflict reconstruction paradigm emphasizes building indigenous capacity – security, governance, judicial, social and economic – so that peace can be sustained without outside intervention. The agents of transition from war to peace are varied in type: internal and external; military and civilian; governmental, intergovernmental, non-governmental and private sector. Military personnel, for example, have long performed many services in the chaos of war and its aftermath: providing emergency medical treatment, food and shelter for dislocated civilians; patching infrastructure, running town meetings, building schools, patrolling streets and training security forces. Aid workers braved great danger to relieve human suffering. A broad array of peace builders today attempts ambitious agendas for human security, effective participatory governance, economic liberalization, and rule of law. The common goal of these activities is to build a basis for political and economic development. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9589,2025,2739,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-345','<div class="desc"> <p>This course will examine the transformation of states, nations, and identity in the contemporary period. Special focus will be given to how transnational developments (in politics, economics, and culture) are redefining modern societies, particularly as the number of democracies has increased worldwide over the last thirty years. The course will also grapple with the challenges and dilemmas of current states. Democratization does not mean democracies are here to stay—as such the course will discuss de-democratization, democratic backsliding, illiberalism, and populism to understand how everyday individuals are affected. In doing so, the class reflects on the experiences of formerly marginalized populations—including women, poor, and the indigenous—by considering the role of states and international organizations in the lives of everyday individuals. Only open to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9590,2025,1516,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-351','<div class="desc"> <div><p>This junior seminar will focus on advanced scholarship on global sustainability and sustainable development, exploring the evolving challenges and opportunities in these fields. Central to the course are themes of energy transition and the geopolitical competition surrounding it, as countries navigate the shift to renewable energy sources. In addition to these dynamics, students will engage with broader issues of international cooperation on sustainability, examining the political, economic, and environmental implications. The course will provide students with a comprehensive understanding of the genesis, characteristics, and consequences of global sustainability efforts. It also emphasizes research and writing in International Relations, preparing students for their Senior Comprehensives. Open only to DWA majors with junior or senior standing. </p></div> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9593,2025,2881,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-355','<div class="desc"> <p>Economic and social rights include the right to an adequate standard of living, the rights to food, water, housing, and education, as well as the right to work and for basic income guarantees for those unable to work. The course examines the legal and philosophical foundations of economic and social rights, as well as challenges to the legality and legitimacy of these rights. We will examine the status of economic and social rights in the global human rights regime, and we will explore provisions for economic rights at the national level. We will discuss the connection between socio-economic rights and poverty, development, and globalization. Students will explore issues of measurement and policy implementation through a range of case studies and cross-regional comparisons. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9594,2025,3359,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-360','<div class="desc"> <p>This course provides an overview of existing scholarship on international development with a focus on two sets of actors: policy-makers and the targets of development policies. It familiarizes students with the traditional theories of development and more recent critiques emerging from scholars of the global south. It also provides a historical contextualization of what precipitated trends in the development world, leading from theories to implementable policies. It addresses the many challenges that the global community faces in its efforts to reduce poverty in an equitable and sustainable manner. Finally, it promotes a multifaceted understanding of development that moves beyond economic poverty to focusing on health and education outcomes while also understanding how existing inequities can obstruct the efficient implementation of development policies. </p> </div>','Only Junior and Senior students may enroll in this class. Only Diplomacy and World Affairs majors may enroll in this class. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9597,2025,553,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9598,2025,1118,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-401','<div class="desc"> <p>The topic of this course will change from year to year at the discretion of the Director of the Oxy at the UN Program. Topics may coincide with the annual theme of the United Nations. Instructor permission required.</p> <p>This course is part of the Oxy-at-the-UN program.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9599,2025,1119,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-402','<div class="desc"> <p>The importance of conflict prevention and conflict resolution policies has long been recognized at the United Nations. The debate was originally focused on the effectiveness of peace-keeping operations and traditional diplomatic measures. Its parameters have been broadened considerably and now encompass longer term efforts to assist developing countries in enhancing durable structures conducive to peace and democratic stability and the targeted use of development cooperation. Combining theoretical/conceptual and practical concerns, and drawing from case studies of recent conflicts, the ultimate objective of the course is to identify feasible short-term and long-term conflict prevention strategies and tools and to develop practical suggestions to move from a culture of reaction to a culture of prevention. More specifically, the course will deal with: (1) the evolving meaning of prevention as it was understood in the Charter of the United Nations and subsequently shaped by the changing causes and nature of conflicts; (2) the main actors in conflict prevention against the backdrop of UN institutions; (3) the tools and practice of "operational" prevention (i.e. early warning, mediation, sanctions, peace operations, peace enforcement, and the role of regional organizations); (4) the tools and practice of "structural" prevention (good governance and democracy, mainstreaming human rights and gender, meeting post conflict reconstruction, and addressing the root causes of conflict); and (5) the significance of the emerging norm of the "responsibility to protect". Instructor permission required.</p> <p>This course is part of the Oxy-at-the-UN program.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9600,2025,1120,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-403','<div class="desc"> <p>This course will provide students with practical hands-on experience through an internship with a UN agency or a member state mission. This will be a professional undertaking, requiring intensive engagement with high-level responsibilities. The internship will be complemented throughout the semester, with the following three elements: (1) a bi-weekly seminar to fully process the learning and practical experiences of the internships; (2) a guest speaker series for dialogue with UN leaders; and (3) a bi-weekly analytic notebook that will provide an opportunity for students to critically analyze internship experiences, guest lectures, and assigned reading materials. Instructor permission required.</p> <p>This course is part of the Oxy-at-the-UN Program.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9601,2025,1012,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-410','<div class="desc"> <p>The abilities to locate, compile, synthesize, evaluate, and compellingly present complex and up-to-date knowledge on rapidly changing global issues - and to do so in a team - are highly valued across public, private, and civil society sectors. Task Force courses help students learn and practice how to research, write, and present an extended policy/practice oriented report for a real-world client on an urgent topic in global/local affairs. This gives intense practice on independent team research with significant real-world impacts. Each semester''s research focus and client will vary, so this class can be repeated for credit. You can learn more about past Task Forces here: https://www.oxy.edu/academics/global-engagement/young-initiative/research-partnerships-task-forces.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9603,2025,554,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-490','<div class="desc"> <p>Preparation, research, writing, and discussion of senior thesis projects in fulfillment of the Senior Comprehensive requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9605,2025,131,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/100/econ-101','<div class="desc"> <p>An introduction to the economic way of thinking that includes both micro- and macroeconomic topics. We begin with an analysis of how market supply and demand help allocate resources and discuss market power, market failures, and the role of government regulation. We explore the determination of gross domestic product, the problems of unemployment and inflation, and macroeconomic policy making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9606,2025,132,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/100/econ-102','<div class="desc"> <p>A continuation of ECON 101 that completes the coverage of economic principles by incorporating the development of more sophisticated analytical tools. Microeconomic topics include: production costs, the behavior of firms under different market structures (competition, monopoly, and oligopoly), taxation and income distribution, and input markets. Macroeconomic topics include: the Keynesian model of output determination, the monetary system, and the effects of fiscal and monetary policies.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9609,2025,555,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/100/econ-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9610,2025,136,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-272','<div class="desc"> <p>The use of regression and correlation to test economic hypotheses. Emphasis will be on the use and interpretation of single equation regression techniques rather than on their derivation. Familiarity with computers required.</p> </div>','Economics 102; Calculus 1; one additional Economics course above Economics 102; and introductory statistics. Introductory statistics prerequisite can be met with any of: CS 146, Math 150, PSYC 201, BIO 268, an AP Stats score of 4 or 5, an IB exam score of 6 or 7, or an equivalent course (with instructor permission). ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9611,2025,2895,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-201','<div class="desc"> <p>This class will introduce students to a variety of frameworks for understanding, measuring, and assessing sustainability. Students will have the opportunity to work on hands-on projects using case studies and/or data. Occidental College will be our laboratory and students may also work with community partners or local firms. Topics vary by semester and could include: waste management, sustainable building, carbon budget, circular economy, corporate social responsibility, ESG, and more. <span>Graded on a Credit/No Credit basis only.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9613,2025,133,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-233','<div class="desc"> <p>Accounting principles and practices. Recording financial data assets, liabilities, owner equity income, and expenses; preparing and analyzing financial statements. Permission of instructor required for first year student enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9614,2025,134,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-250','<div class="desc"> <p>Foundations of microeconomic theory. Topics include: the analysis of consumer theory and decision making; the theory of the firm under perfect competition, general equilibrium, and market inefficiency arising from monopolistic/oligopolistic/strategic behavior; incomplete information; externalities; and public goods. Should be completed before the end of the sophomore year. May be taken before or after ECON 251. Should not be taken in the same semester as ECON 251.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9615,2025,135,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-251','<div class="desc"> <p>A study of the factors that influence and are involved with the national economy. Aggregate analysis as applied to problems of national income, accounting and determination, inflation, unemployment, modern economic growth, and the influence of the money supply. May be taken before or after ECON 250. Should not be taken in the same semester as ECON 250.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9616,2025,3551,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-293','<div class="desc"> <div><p><span>Students will work on a faculty-directed research project. Responsibilities may include data collection and cleaning, coding and statistical analysis, hypothesis formulation and testing, writing and literature review, and conceptualization of future research. Graded on a Credit/No Credit basis only. Prerequisites: Econ 102 (may be taken concurrently) and permission of instructor. May be repeated for credit.</span></p></div> </div>','Econ 101 and permission of instructor Econ 102 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9618,2025,556,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/200/econ-297','<div class="desc"> <p>Application of modern research methods to current problems in Economics and related fields. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9619,2025,2827,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/copy-of-econ-322','<div class="desc"> <p>Are goals of economic development and sustainability at odds with one another? What kinds of policy instruments could help us effectively reduce emissions, and why is international cooperation so difficult to achieve? This course offers a critical examination of sustainable development from the economics perspective. Beginning with conflicting views of sustainable development, the course proceeds to study how economists approach challenges such as climate change, management of common property resources, growth and poverty, measurement of well-being, and global health.</p> </div>','ECON 250 , or ECON 102 and MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9620,2025,557,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-301','<div class="desc"> <p>The purpose of this course is to illustrate the role that economics can play in creating and improving environmental policy. We will apply the theories of economic efficiency, cost-benefit analysis, market failure, and property rights to environmental policy and regulation. We will cover the principles of market-based environmental policies and their applications in the world today. We will touch on all aspects of the economy''s interaction with the environment, including air and water pollution, global warming, environmental health, non-market valuation, and resource extraction.</p> </div>','ECON 101 or ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9621,2025,1447,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-302','<div class="desc"> <p>This course introduces the field of industrial organization, which studies how firms make strategic decisions. We will analyze a wide range of issues such as market entry, product positioning, market leadership, and mergers and acquisitions. We will also examine the role of competition law. Our approach blends two alternative but complementary methodologies: theoretical modeling of strategic firm behavior and industry equilibrium, and the factual detail found in case studies of specific industries.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9622,2025,137,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-303','<div class="desc"> <p>This course explores the economics of the internet, which is the study of the online behavior of firms and consumers. We will analyze competition and firm strategies in internet marketplaces. Topics will include online platforms, internet auctions, copyright and innovation, advertising, and consumer search. Our approach will combine theoretical modeling and statistical tools with factual detail from the case studies of firms and industries.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9623,2025,921,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-305','<div class="desc"> <p>This course is an introduction to the study of strategic interaction using the tools of game theory. The focus of the course is on developing a set of analytical techniques with the goal of understanding and using game theoretical models in economics. The first part of the course introduces the basic framework and tools of game theory. The second part of the course covers a number of economic (and some non-economic) applications of game theory; specific topics may include: auctions, bargaining, voting, and market competition.</p> </div>','ECON 250 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9624,2025,2676,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-306','<div class="desc"> <p>This course builds on ECON 272 to cover advanced topics in econometrics including: panel data, binary response models and causal inference. Theoretical models of regression and empirical coding will both be emphasized. </p> </div>','ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9625,2025,2439,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-307','<div class="desc"> <p>Using, interpreting, and understanding data is increasingly important for understanding the magnitude, determinants, and solutions to social issues. This course provides an introduction to economic data analysis, discussing how economists quantify key concepts, test theories using empirical data, and evaluate policy effectiveness. Students will learn basic statistical methods and data analysis techniques, including how to clean, visualize, and analyze data using statistical programming packages. The course will also present an intuition-based introduction to regressions and causal inference. We will develop these skills discussing data and models from a range of topics, including poverty and inequality, macroeconomic growth, health, and education.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9626,2025,558,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-308','<div class="desc"> <p>This course studies the government''s role in a market economy, particularly policies that work through government spending and taxation. There are two primary motivations for government intervention: to correct a market failure or to mitigate poverty and inequality through redistribution. The course is organized around these two rationales, with attention to topics that include climate change, public education, health insurance, Social Security, welfare policy, and the taxation of goods, labor, and capital. We study how such government policies impact behavior and, as a consequence, how they should be designed to maximize welfare. This course also introduces students to the modern methodological approach in public economics that tightly connects economic theory with credible empirical evidence to generate policy insights.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9627,2025,832,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-309','<div class="desc"> <p><strong></strong></p> <p> The Austrian School of Economics, so-named because of the national origin of its founders, is an alternative approach to Economics that emphasizes methodological individualism and subjectivism. The Austrian School of Economics traces its roots back to the works of the Spanish Scholastics of the 16th century and stresses the importance of the individual, private property, limited government, and the organizing power of the free-market. Students will read from authors such as Menger, Mises, Hayek, Kirzner, Rothbard, and Hoppe, and evaluate various properties of a state-planned economy versus a decentralized free market economy.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9628,2025,138,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-311','<div class="desc"> <p>Economic activity in a global context. The first part of the course covers the causes and consequences of international trade, with a consideration of both national welfare and income distribution issues. Coverage then turns to trade policy in theory and practice, with a focus on the current global trading environment under the World Trade Organization. The course finishes by examining international investment and debt issues, including the role played by the International Monetary Fund during global financial crises. May not be taken for credit by students who have taken DWA 220/POL 232.</p> </div>','ECON 102 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9629,2025,922,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-312','<div class="desc"> <p>Germany has emerged as a leader in sustainability and innovation. With the Federal Elections in 2021, would an increasingly popular Green Party help accelerate sustainable development in Germany? In this course, we study the political economy of Germany and how various political and economic forces shape sustainable development in Germany. The course begins with a module on the history, politics, and economy of Germany. We study the key events and institutions that helped shape Germany to become a leader in sustainability, though not without challenges. Concepts and theories in political economy will be introduced, alongside a review of key economic concepts. The course then proceeds to an environment-focused module and applies political economy frameworks to understand environmental issues confronting Germany. This bridges into case studies focused on several cities that have led sustainability debates. We then shift the focus to economic and social sustainability topics, including digital and innovation economy, east-west inequalities, migration, identity and integration, and nationalism. The course meets first as an on-campus seminar to introduce the political and economic structures as well as the major environmental and sustainability debates in Germany. We then spend three weeks traveling across Germany to learn on the field, including a visit to the German Parliament (Bundestag). This is a Faculty-led Course Abroad and the three-week field study in Germany is required. Application is required. </p> </div>','ECON 102 and instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9630,2025,1069,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-314','<div class="desc"> <p>This course examines the historical development and the role of institutions underlying market economies. It discusses the many forms which institutions (i.e. social norms, laws, and regulations) affect economic behavior and performance. Based on examples from United States and European economic history, topics will include: contract enforcement; trading institutions; political institutions; financial institutions; property rights in land and environmental resources; regulation of labor and capital markets; and the origin and development of one of the most important economic institutions, the firm. We will pay particular attention to institutions that emerged in response to market failures and to the changing nature of economic institutions over time.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9631,2025,1217,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-319','<div class="desc"> <p>This course examines the application of economics to the law. Studies of actual cases reveal how economics can be applied to address such questions as: (1) whether an action violates the law, (2) who experiences economic harm as a result of that action, and (3) what the legally prescribed consequence is. Specific applications include: property rights related to technical innovation, competition in concentrated industries, and the extent of corporate liability. The primary context is the United States, but other legal systems provide some specific comparisons.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9632,2025,559,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-320','<div class="desc"> <p>Theoretical and empirical analysis of the process of economic development in less developed countries. After examining several theories of growth and development, we will discuss inequality and poverty, the effects of population growth and rural-urban migration, saving and financial markets, international trade, foreign aid and foreign borrowing, agriculture, and the role of the government. Case studies will be drawn from the development experiences of Asian, Latin American, and African economies.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9633,2025,2626,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-321','<div class="desc"> <p>This course provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9634,2025,2932,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-323','<div class="desc"> <p>Cities are great places where populations gather, interact, and create new ideas. At the same time, cities represent problems such as traffic, crime, and economic inequality. Why do cities exist in the first place? How do we explain the land use patterns and housing prices? Does building infrastructure relieve congestion or create pollution? Does gentrification help revitalize inner cities? This course offers a rigorous survey of urban and spatial economics. Core theories in urban economics will be introduced, as well as ideas in economic geography, spatial econometrics, and sustainable development. Basic skills in data analysis and visualization will be developed.</p> </div>','ECON 102 and either COMP 146 or UEP 305 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9635,2025,1013,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-324','<div class="desc"> <p>This course examines the economic causes and consequences of immigration. The focus of the course will be on the United States'' experience. However, we will also examine aspects of other international migrations. The course will focus on the economic reasons that motivate people to migrate to other parts of the world, the labor market and fiscal impacts of immigration on sending and receiving countries, and the economic consequences of U.S. immigration policy choices.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9636,2025,833,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-325','<div class="desc"> <p>The goal of Labor Economics is to enable you to use economic analysis and reasoning to understand wage and employment determination in U.S. labor markets. This course will expose you to current theoretical and empirical debates within the discipline. We will cover such topics as: labor force participation, labor demand, unemployment, labor mobility, wage structure, labor unions, human capital investments (education and training), internal labor markets, and labor market discrimination. Relevant public policy issues such as the minimum wage, living wage ordinances, compensating wage differentials, immigration policy, affirmative action, income inequality, and welfare programs will also be addressed in this course.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9637,2025,924,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-326','<div class="desc"> <p>An application of economic analysis to various topics in personnel economics, including: compensation and incentives, hiring, training, downsizing/buyouts, stock options, pensions, and teams, among many others. In order to add realism to, and applications for, the analysis, students will discuss and evaluate numerous real-world mini-cases and more formal case studies. Students will be evaluated on the quality of their written work, problem sets, examinations, and discussion; a variety of class formats will be used. Note: Students who take this course may not take Professor Moore''s section of ECON 495.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9638,2025,1331,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-327','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women in the United States, this course is designed as an overview of major theories, trends, and debates on the topic of gender in the labor market. We will examine gender differences in economic outcomes through the use of economic models, including feminist extensions and critiques of such models. Topics include: the family as an economic unit; gender differences in education, work, training, and income; and the economics of marriage, divorce, and fertility. Permission of instructor required for students who have successfully completed ECON 328 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9639,2025,139,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-328','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women and minorities. Topics include: the economics of slavery, racial and sexual discrimination, labor market segmentation, wage differentials, labor force participation, red-lining, and income inequality. Relevant public policy issues such as affirmative action and welfare will also be addressed. Permission of instructor required for students who have successfully completed ECON 327 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9640,2025,2740,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-329','<div class="desc"> <p>Despite a widespread desire to provide equality of opportunity to all people in the United States, family background has an enormous effect on the way children grow up and the opportunities available to them in adulthood. Family income can explain more than a third of a child’s future adult income, and all aspects of family background can explain half to two thirds of a child’s future income, education, and wealth. In this class, we will explore economic theories and evidence explaining the inheritance of advantage, with a particular emphasis on understanding the role of the family, the role of neighborhoods and communities, and the role of discrimination. We will also discuss the role of public policy in increasing intergenerational mobility and reducing social and economic disadvantages, both in the United States and around the world.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9641,2025,3337,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-330','<div class="desc"> <p>This course uses an economic lens to study educational systems, human capital acquisition, and education policy. It considers the education system at large, ranging from early childhood education, through secondary and post-secondary education. The course develops a theoretical framework for why and how education levels differ across individuals, considering both signaling and productivity margins. It covers the basics of public education financing and examines how the way that education is financed determines educational quality. The course will discuss various public policy topics surrounding education topics which may include include: the value of early childhood education, the importance of quality instruction, peer effects, high-stakes testing, major-choice, and more. The course will build on foundational economic concepts and ask students to connect economic theory and empirical research towards understanding our system of education. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9642,2025,1448,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-331','<div class="desc"> <p>An introduction to the history of radical philosophical alternatives to neoclassical and Keynesian Economics. A critique of these mainstream schools is followed by the development of competing radical alternatives with the analytical focus on concepts of economic surplus and social class, exploitation, alienation, and theories of capitalist development crisis and transformation. Ethnographic case studies provide examples of archaic and contemporary alternative economic practices. Special attention is paid to philosophies of human nature, the labor process, problems of racism and sexism, imperialism, current U.S. economic problems, and socialist alternatives.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9643,2025,834,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-340','<div class="desc"> <p>This course will provide an introduction to the relatively new field of Behavioral Economics. Standard models of economic theory provide a useful, but not always realistic, way to characterize how individuals make decisions. In this course, we will investigate the evidence showing how people may behave in ways that are not predicted by this standard theory. Individuals may exhibit nonstandard preferences, nonstandard beliefs, or nonstandard decision-making. We will look at each of these in turn, with applications that may include saving, finance, labor supply, gift-giving, voting, and addiction. The methodology of the course will not itself deviate from the standard way of doing economics; we will state clear assumptions, build models, determine their logical conclusions, and think about how to empirically test both the assumptions and implications of such models.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9644,2025,140,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-350','<div class="desc"> <div><p>This course covers the application of economic theory and analytical tools to business and management decision making. Topics to be covered will include examples from a variety of fields, including: pricing, ethics, entrepreneurial startups, strategy, new products, acquisitions, marketing, human resources, and leadership. </p></div> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9645,2025,1166,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-351','<div class="desc"> <div><div><p>This course examines the interaction between monetary policy and financial markets. Key topics include business cycles, stock and bond markets, and banking panics. Students will learn how to analyze the financial market implications of Federal Reserve policy. The course incorporates insights from economic history to understand the monetary policy challenges facing the U.S. macroeconomy today.</p></div></div> </div>','ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9646,2025,1591,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-352','<div class="desc"> <p>Firm-level studies are now at the forefront of international trade research. In this course, we look at firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. We use modern trade theory to analyze firm decision-making; we start with a discussion of the firm''s decision to engage in international commerce and then examine how firms choose between various types of foreign direct investment. Throughout the course, we learn from empirical studies and individual case studies how firms engage in international commerce.</p> </div>','ECON 250 and ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9647,2025,3273,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9648,2025,561,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-395','<div class="desc"> <p>Topics vary semester to semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9649,2025,562,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/300/econ-397','<div class="desc"> <p>Advanced independent research in Economics. For example, Advanced Econometrics can be taken on an independent study basis. Permission of instructor and department chair required.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9651,2025,142,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/400/econ-495','<div class="desc"> <div> <p>An intensive application of economic analysis to issues chosen by the instructor in consultation with students during the course. The course emphasizes the development of analytical writing, team-work, and presentation skills, and is meant to be an opportunity for students to apply their economic training to specific topics. Complete descriptions of the seminars offered in a given year will be mailed out to students prior to the Spring registration. Senior status is required for this course. Students who will be off campus in the Fall of their senior year must contact the department chair by the end of their junior year to arrange a substitute senior seminar.</p> <p><strong>Economics of Education</strong></p> <p>This course uses an economic lens to study educational systems, human capital acquisition, and education policy. It considers the education system at large, ranging from early childhood education, through secondary and post-secondary education. The course develops a theoretical framework for why and how education levels differ across individuals, considering both signaling and productivity margins. It covers the basics of public education financing and examines how the way that education is financed determines educational quality. The course will discuss various public policy topics surrounding education topics which may include: the value of early childhood education, the importance of quality instruction, peer effects, high-stakes testing, major-choice, and more. The course will build on foundational economic concepts and ask students to connect economic theory and empirical research towards understanding our system of education. Not open to students who have taken ECON 330.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong>Firm-Level International Trade </strong></p> <p>This seminar studies firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. Topics discussed include the decision to export, foreign direct investment, outsourcing/offshoring, GATT/WTO and various trade agreements. We use modern trade theory to analyze firm decision-making and also learn how firms engage in international commerce from empirical studies and case studies. Not open to students who have taken ECON 352.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250.</p> <p><strong>Industrial Organization</strong></p> <p>This course introduces the field of industrial organization, which studies how firms make strategic decisions. We will analyze a wide range of issues such as market entry, product positioning, market leadership, and mergers and acquisitions. We will also examine the role of competition law. Our approach blends two alternative but complementary methodologies: theoretical modeling of strategic firm behavior and industry equilibrium, and the factual detail found in case studies of specific industries. Not open to students who have taken ECON 302.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250.</p> <p><strong><strong>Monetary Policy and Financial Markets</strong></strong></p> <p>This course examines the interaction between monetary policy and financial markets. Key topics include business cycles, stock and bond markets, and banking panics. Students will learn how to analyze the financial market implications of Federal Reserve policy. The course incorporates insights from economic history to understand the monetary policy challenges facing the U.S. macroeconomy today. Not open to students who have taken ECON 351.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong>Open Economy Macroeconomics</strong></p> <p>The course provides an overview of models, methods, research, and current issues in Open Economy Macroeconomics. Today, an international perspective to study Macroeconomics is perhaps more important than ever before. Countries do not operate in isolation, but events in one country affect people around the world. Why do some countries grow faster than others? What are the effects of monetary and fiscal policy, domestically and abroad? Why do some countries run trade deficits and others trade surpluses? Does it matter? And why do some countries encounter financial crises and what can we do about them? In trying to answer these questions, the first part of the semester will be devoted to asset-based models of exchange rates and price level determination, and the second to open economy models of the short and medium run.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong><strong>Health Economics</strong></strong></p> <p>This seminar provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. Not open to students who have taken ECON 321.</p> <p>Prerequisite: ECON 250 and ECON 272 (may be taken concurrently).</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9653,2025,143,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/econ-economics/400/econ-498','<div class="desc"> <p>Independent research with one-on-one faculty mentoring. After a brief introduction to economic research methods, students will develop a topic and then write and present a senior thesis. Only open to seniors. Permission of instructor and department chair required.</p> </div>','ECON 250 , ECON 251 , and ECON 272 ; and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9654,2025,1218,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/100/educ-101','<div class="desc"> <p>In every major urban center across the United States, children and youth attend public schools managed by highly-bureaucratized administrative entities called ''school districts''. This course provides a historical survey of the evolution of U.S. urban schooling, tracing its development from the earliest community-based, one-room schoolhouses, to modern major urban unified school districts. We explore the roles that industrialization and immigration have played in the urbanization of communities, and the ways in which schools have adapted in order to provide for the socialization of the urban worker. We examine shifts in the politics of public education as it pertains to control over schools and schooling and the various stakeholders involved. We conclude with a look at the evolving roles of the teacher, school counselor, and the administrator - as well as a glimpse into what the future holds for both traditional and alternative forms of public schooling in urban school communities across the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9655,2025,145,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/100/educ-140','<div class="desc"> <p>Occidental students work in the Academic Commons one-on-one with children from the community. While incorporating arts and integrating technology, students will engage their child with a variety of Language Arts activities in order to reconnect their child with the joy of reading and writing for pleasure. Students will build on their child''s strengths, skills, and interests by using culturally relevant pedagogy and critical literacy explorations. Students become part of a high-warmth, low-criticism community. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9656,2025,835,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/100/educ-141','<div class="desc"> <p>Students work one-one with middle school students for extensive explorations in writing. Occidental students will collaborate and coach writing activities which will include narrative, expository, and analytical prompts. This course focuses on authentic, engaging writing and integrates the arts, technology, and critical literacy. Students work closely with the Critical Making Studio. This course is designed to deepen the critical and creative abilities of both groups of students while connecting written explorations to the California Common Core Standards. This course takes place on campus in the Academic Commons. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9657,2025,2511,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/100/educ-142','<div class="desc"> <p>In this course, Occidental students who are Spanish or Mandarin speakers will offer elementary and middle school students, who come on the Oxy campus, Spanish/Mandarin language development and language enrichment activities. Graded on a Credit/No Credit basis. May be repeated once for credit. For further information, email the professor.</p> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9658,2025,3262,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/100/educ-143','<div class="desc"> <p>This an interdisciplinary course providing an introductory overview of public engagement through the lens of art. Students will learn basic methodologies of public engagement; how to create an inquiry-based lesson plan with an emphasis on creative expression; and how to lead a group of elementary or middle school students, with priority placed on collaboration and art-making.</p> <p> During the first six weeks of the semester, students will research, plan and work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop lesson plans for an original after school art workshop for local youth. In the following 6 weeks of the semester, Oxy students will collaboratively lead their workshops for local elementary or middle school youth, culminating in a final public presentation at the Oxy Arts gallery. This course is an eligibility requirement to apply for a paid student work position through Oxy Arts to lead after school art classes on-site at local Highland Park elementary schools. You are required to submit an application to register for this class. You will be notified if you''re accepted into the course before registration week. Permission of Oxy Arts Director Required.</p> <p>Apply here: https://forms.gle/xtgXkX2PeBpmo9Zp6 </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9659,2025,1014,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/100/educ-145','<div class="desc"> <p>In this course, students will systematically examine the causes, challenges, and effects of several educational innovations in various school systems, from K-12 to higher education. The course will help students develop historical perspectives of schooling, critically examine the role and purpose of progress and innovation in our educational landscape in the United States, and understand how past, present, and future innovations impact our collective educational processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9663,2025,146,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-201','<div class="desc"> <p>In this introductory course, students study, as a community of learners, the historical, philosophical, political, sociological, economic, and psychological foundations of U.S. education in the public school. Using a variety of analytical lenses, students will critically engage with key texts to examine factors that influence power, control, and the quality of schooling for urban communities. Throughout the semester, we will focus our analysis on the possibility and potential of achieving "socially-just" relationships in urban school communities through teacher practice, educational leadership, and community-based activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9664,2025,147,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-205','<div class="desc"> <p>Analysis of the English language development of listening, speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public-school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction, sheltered/SDAIE approaches, English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9665,2025,148,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-207','<div class="desc"> <p>How are the American values of equity and opportunity evident in the history and structure of the nation''s public-school system? This course examines key U.S. Supreme Court decisions and the following areas of policy debate and conflict, with particular emphasis on the Constitution: bilingual education funding/expenditures, immigrant education, desegregation, special education, affirmative action, and equal resources.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9666,2025,3338,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-211','<div class="desc"> <p>This course prepares students to understand and apply principles of educational equity &amp; diversity to the study of the schooling experiences of Asian American students in K-12 and higher education contexts. With attention to the broader context of anti-Asian racism in the U.S., the course provides theoretical frameworks to ground students’ understandings of the histories, cultures, and ethnic experiences within specific groups, as well as preparing students to engage comparative analyses of Asian American education towards the ultimate goal of critically interrogating the curricular, instructional and assessment practices that have come to shape the schooling of Asian American students in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9667,2025,925,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States: Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students, and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9668,2025,149,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-215','<div class="desc"> <p>This course critically examines the history of the education of Africans in the United States, beginning at the Middle Passage, through Reconstruction and the post-bellum South, to contemporary post-industrial urban contexts. Emphasizing the sociohistorical and political-economic dimensions of schooling African Americans, the course explores the role of key factors in shaping the academic "success" and "failure" of Black students historically and in current K-16 contexts. Analysis of case law policy and practice will inform our understanding of African American experiences in schools nationally and locally. Further, we consider the implications these experiences hold for democratic participation and the overall life chances of African American citizens.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9669,2025,1378,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-217','<div class="desc"> <p>National reform efforts (e.g. Nation at Risk, No Child Left Behind, Race to the Top) have permeated the educational establishment for decades, yet the achievement gap between rich and poor and white and non-white students has shown no appreciable progress. This course will analyze current and past policies in education intended to improve the educational experience of all students and address this achievement gap. Students will receive an understanding of policy formation, the effect of applied research relative to educational policy, and then select a reform policy (e.g. value-added teacher pay, class size, charter schools, etc.) to further investigate as a project field assignment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9671,2025,1015,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-219','<div class="desc"> <p>This course will analyze the educational infrastructure PK-16 pipeline to examine the nature of inequality. The following three areas will be examined: (1) theories of educational inequality, (2) research on inequality, and (3) policies of inequality. Students will gain a basic understanding of the theories of educational inequality as they relate to genetic, cultural, school, and societal perspectives, using critical theoretical lenses. Students will also examine the research addressing educational inequality, paying attention to designs, methods, and samples covered. And finally, students will analyze educational policies that either reproduce or eliminate inequalities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9672,2025,2741,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-220','<div class="desc"> <p>The United States has the highest incarceration rate in the world. Schools, despite their role in nurturing the academic growth and development of students, are increasingly becoming sites of criminalization for marginalized children and youth. This raises fundamental questions about the relationship between schools and the carceral state, as well as about the complicity of schools and their officials in the production of prisoners. In this course, students will explore the social, historical and political-economic factors that have contributed to the development, growth and sustenance of the "school-to-prison pipeline." Through an examination of a wide range of texts and sources that sit at the intersection of K-12 schooling, criminal justice, social welfare, and community-based organizing and activism, students will be prepared to critically interrogate educational policies, practices and other structures of schooling that buttress and deconstruct this phenomenon. Sophomore standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9673,2025,1449,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/200/educ-281','<div class="desc"> <p>This class provides students with the ability to develop a conceptual and practical understanding of research and evaluation in Education and the Social Sciences. Course topics include: basic statistics, survey design, data analysis, article critique, and data interpretation. The course will allow students to demonstrate a proficient knowledge of basic statistics (ranging from basic descriptive statistics to inferential statistics), research design, and analysis. Students will advance from being consumers of knowledge to being critical when reading previous literature. Students will be introduced to the following concepts: descriptive statistics (including cross-tabulation); correlation, reliability, and validity; one and two sample statistical tests; ANOVAs; and simple and multiple regression.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9677,2025,150,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/300/educ-300','<div class="desc"> <p>This seminar will provide students with an opportunity to gain field experiences in an educational setting in urban Los Angeles. Students will select either a public school, a community-based organization, or a policy-making group as a site in which to develop a field-based research project. Regular meetings of this seminar will guide students as they spend the semester in a carefully crafted and mutually agreed upon "internship/fieldwork" experience that will culminate in a semester-end project report that addresses an educational issue of import to the fieldwork site. May be repeated once for credit.</p> </div>','EDUC 201 and EDUC 207 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9679,2025,566,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/300/educ-320','<div class="desc"> <p>Critical Race Theory (CRT) is a historic movement among legal scholars of color in the U.S. that has enjoyed widespread application in a number of disciplines, including Education. This course introduces students to CRT through a close reading of the key writings that formed the movement. We will examine the application of CRT in education, research, theory, and practice, contextualized in a variety of settings, including schools, community-based organizations, and other relevant spaces. Specific attention will be paid to the CRT methodology of counter-storytelling and its utility in centering the experiential knowledge of people of color in education.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9680,2025,1168,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/300/educ-350','<div class="desc"> <p>"How can the oppressed as divided unauthentic beings participate in developing the pedagogy of their liberation?" This course focuses on Freire''s theoretical, pedagogical, and practical contributions to contemporary movements in critical pedagogy, critical literacy, and educating for "social justice". Beginning with Franz Fanon''s influences on Freirean thinking about revolution and decolonization, we will analyze the construction of the "Pedagogy of the Oppressed". We pay particular attention to the role of the Hegelian dialectic as a driving philosophical method, as well as the significance of Freirean themes in understanding contemporary schooling, education, community activism, and vocation in general. Students will analyze, critique, and reflect upon their own framing philosophies for personal engagement with oppressed peoples and communities - towards the broader goal of defining an individual role in the development of a pedagogy of the oppressed that both negotiates and is informed by students'' multiple identities.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9683,2025,568,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/300/educ-397','<div class="desc"> <p>Interested students must obtain <em>Guidelines for Independent Study</em> from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9684,2025,3565,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/educ-education/400/educ-410','<div class="desc"> <p>Participatory Action Research (PAR) is an ‘action research’ methodology in which researchers and community partners collaborate to conduct critical research. PAR projects typically involve (a) the collective investigation of a problem, that (b) relies on indigenous and/or community knowledges to guide/inform that research, towards the end of (c) individual and/or collective action to address that problem. This course introduces students to the research methodology through guided study. Students will understand basic study design, various methods of qualitative data collection &amp; analysis, as well as dissemination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9687,2025,2742,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/100/engl-140','<div class="desc"> <p>This class will examine the literature and culture of the Victorian period, from the 1830s to the turn of the twentieth century. We will read classic Victorian novels such as<em> Silas Marner</em>, <em>Great Expectations</em>, and <em>Jane Eyre</em> alongside more contemporary literary and cinematic interlocutors including <em>Wide Sargasso Sea</em>, <em>Thugs of Hindostan</em>, and <em>Victoria and Abdul</em>. In thinking about the period’s lasting impact on our own society, we will consider the broader historical context of imperialism, urbanization, and industrialization, all of which expanded dramatically during the Victorian era. We will also examine the shifting social and legal structures of the era, addressing issues of class, sexuality, and race.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9688,2025,1698,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/100/engl-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9690,2025,3903,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/100/engl-147','<div class="desc"> <p>This course will examine 19th-century British and Indian novels in dialogue with their 20th- and 21st-century Bollywood film adaptations, both of which are full of innovative approaches to narrative and cinematography. A product of the largest film industry in the world, Indian cinema is consumed globally. Questions of globalism were also central to 19th-century novels that were written during the height of British colonial rule. Students will learn how to interpret and write about both literature and film in this course, paying particular attention to representations of globality and cultural difference, subject formation, gender and racial norms, and nationalist sentiment in the era of empire and the postcolonial moment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9691,2025,1517,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/100/engl-155','<div class="desc"> <p>The pandemic of 2020 has revealed the surprising number and diversity of fantasies, fears, and anxieties surrounding the notion of science. While some of these reactions are relatively new (particularly those grounded in historically specific conspiracy theories), most emerged over the course of several centuries. Literary works, particularly novels, often explore these fears and anxieties in far greater detail than may be found in the direct attacks on or defenses of science. Texts like Mary Shelley''s <em>Frankenstein</em> or Bram Stoker''s <em>Dracula</em> both draw on scientific theories and articulate fears of the possible consequences of these theories that still resonate with readers today. We will read literary texts to determine what exactly those who reject science fear, and what is at stake in their rejection of science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9692,2025,2986,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/100/engl-165','<div class="desc"> <p>This class will read examples of queer Anglophone fiction across a broad range of historical periods and geographical regions. Beginning with Kate Chopin’s <em>The Awakening</em>, through Nella Larsen’s <em>Passing</em>, Djuna Barnes’s <em>Nightwood</em>, and E.M. Forster’s <em>Maurice</em>, we will explore the intersection between sexuality and other social structures such as race and class. We will build on this intersectional foundation to examine the legacies of colonialism, gender-policing, and marital normativity in contemporary global queer novels such as Shani Mootoo’s <em>Cereus Blooms at Night</em>, Akwaeke Emezi’s<em> Pet</em>, Chinelo Okparanta’s <em>Under the Udala Tree</em>, and Shyam Selvadurai’s <em>Funny Boy</em>. Over the course of the semester we will supplement our readings of novels with various theoretical texts that address the social and political contours of queer literature and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9693,2025,1657,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/100/engl-178','<div class="desc"> <p>This class introduces you to some of Shakespeare’s most challenging and rewarding plays, with a focus on both their historical moment and film adaptations that have reanimated them across the second half of the 20th and 21st centuries. Our main topic will be Shakespeare’s evolving exploration of the predicament of tragedy in an era of major social, religious, and political transformation for Europe (England especially), and the ways that filmmakers have adapted Shakespearean tragedy for the big screen in different times and places. We will study Shakespeare''s explorations of dramatic form, poetic style, characterization, and ideology, and examine how the choices made in filming Shakespeare allow us to think in new ways about the plays themselves, and about the historical context in which the films were made. This course will introduce you to foundational concepts in literary studies and film studies, help you learn how to engage with Shakespeare''s plays more deeply, and enable you to analyze how film adaptations bring to life or transform the complex, unruly energies that characterize Shakespearean tragedy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9697,2025,2882,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-220','<div class="desc"> <p>In this course we will study the relationship between literature and science during the Scientific Revolution of the seventeenth-century in England. Though today we usually consider science and literature to inhabit different spheres, in the era when “modern science” began there was no clear division between the two. We’ll explore the shared questions about the earth, human nature, the cosmos, and the divine that motivated new conceptions of scientific experiment and innovations in literary writing. We''ll also examine how the institutionalization of experimental science, especially with the founding of the Royal Society, transformed English literature as well as England''s orientation to Continental Europe and the "New World." Readings will be drawn from the work of scientists, fiction-writers, essayists, and poets, including William Shakespeare, Francis Bacon, Galileo Galilei, René Descartes, John Donne, Ben Jonson, Thomas Browne, Blaise Pascal, Robert Boyle, Anne Conway, Robert Hooke, Margaret Cavendish, John Milton, Thomas Hobbes, Lucy Hutchinson, and Isaac Newton.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9698,2025,2987,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-222','<div class="desc"> <p>What, if any, is the relationship between revenge and justice? This course will pose that question primarily through a careful study of English Renaissance revenge tragedy (Kyd, Marlowe, Shakespeare, Webster, Middleton) and its dialogue with ancient models of the genre (Aeschylus, Seneca). We will also read Renaissance romances about the challenges of tempering the desire for revenge (Cervantes, Spenser). Our study of these literary works will enable us to understand key developments in the legal and religious thinking of Renaissance Europe (especially England), and the relevance of these innovations to the complex role revenge plays in our current moment. We will likewise survey some influential philosophers of revenge from antiquity to the present, and if time allows, we’ll examine the importance of revenge to contemporary fiction and film. Some questions we’ll ask include: How have artists imagined the desire for and consequences of revenge? What cultural and legal structures have been constructed to produce, mediate, temper, or sublimate vengefulness? How have modern conceptions of justice relied on, or occluded, revenge? When does revenge uphold structures of oppression and when can it aid in resisting or abolishing them? This class will give you tools to analyze the long history of revenge and its ramifications for literature and law in Renaissance England, and enable you to think more critically about the role of revenge in our own legal, political, and cultural worlds today.</p> <p><span>Major Requirement Met:</span><span> <strong>Group I</strong></span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9700,2025,1592,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-241','<div class="desc"> <p>This course looks at representations of "deviance" in 19th- and early 20th-century literature. Underlying our examination will be an investigation of what constitutes the "normal" and the ways in which normativity polices its boundaries. Focusing primarily on literary and filmic representations of the sexual, racial, legal, and economic "taboo," in works including Charles Dickens''<em> Great Expectations,</em> E.M. Forester''s <em>Passage to India, </em>and Djuna Barnes'' <em>Nightwood</em>, we will seek to uncover the terms of normativity, against which the figure of the deviant emerges into representation. We will supplement our analysis of literature with readings from a range of theoretical methodologies, from psychoanalysis, legal theory, Marxist/economic theory, to postcolonial and critical race studies. </p> <p>Major Requirement Met: <strong>Group II/IV</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9701,2025,2337,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-248','<div class="desc"> <p>This course will focus on novels by major British nineteenth-century authors, with particular attention to the production of gender roles and the influence of economic forces on character and language. Read in relation to the historical context of rapid change from a land-based to a money-based economic system in the United Kingdom, the novels reveal how the introduction of capitalist practices affected men and women differently. The novels dramatize the ways that capitalism influences the feelings and thought processes of individuals. The class will also pay close attention to the novels’ style and wording, with an eye to seeing how language itself is infiltrated by market practices and values.</p> <p><span>Major Requirement Met: </span><span><strong>Group II</strong></span></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9702,2025,3839,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-265','<div class="desc"> <p>This course examines the historical construction of the âwhite womanâ and her non-white counterparts through American literature, visual art, and film. Combining literary analysis with tools from scholars of gender and sexuality, we will trace how notions of womanhood in the US have been formed through social and institutional associations of race and sexuality. We will follow these notions as they develop in a set of linked narratives that depict womenâs self-indigenizing within a settler colonial context, southern anxieties over endangered white womanhood, and cross-racial identification as a (haphazard) strategy for solidarity. In our final unit, we will examine works of contemporary writing and film that propose the possibility of a âwhite girlâ who is not necessarily a girl and not necessarily white. The syllabus includes texts by Zitkala-Sa, Sojourner Truth, Harriet Jacobs, Edith Wharton, Nella Larsen, Flannery OâConnor, Cherrie Moraga, Hilton Als, Sigrid Nunez, and Alexander Chee, along with visual art (Nikki S. Lee, Adrian Piper) &amp; film (Kill Bill). Major requirement met: Group III or Group IV</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9703,2025,3573,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-267','<div class="desc"> <p>Most students are aware of Andre Breton''s Parisian circle of surrealists, who have become synonymous with intellectual and artistic experimentation, combined with political engagement. Fewer realized that surrealist aesthetic techniques were being practiced at the exact same time within the Black Diaspora, among its Francophone, Anglophone, and Hispanophone speakers. Surrealism attracted artists, intellectuals, and activists from so many different cultures because it surpassed previous avant-garde art movements in linking creativity to a critique of colonialism. It is not surprising that surrealism found a special expression in the African Diaspora.</p> <p>However, the sheer breath of African Diaspora artists taking up surrealist techniques and themes is staggering. This course serves as an exploration of Afrosurrealist expression. The course begins in the early 20th century with the first generation of writers to embrace the term surrealism, then moves to the mid-20th century. But the majority of the course looks at 21st century literature, music, and visual art. European artists who took anti-racism seriously will also be included along the way. Students will encounter the work of Aime and Suzanne Cesaire, Romare Bearden, Claude Cahun, David Hammons, Senga Nengudi, Wangechi Mutu, D.S. Marriott, Terrance Nance, and Tierra Whack, among others. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9704,2025,3323,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-270','<div class="desc"> <p>This course analyzes the social experience and cultural heritage of Asian Americans through their writing, and places them in a broader comparative context of multi-racial/ethnic American society. We will examine the development of Asian American literature, its social implications and historical context, and the diversity of subject matter that the literary scene of Asian American communities has consisted of since the mid-19th century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9705,2025,1699,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-273','<div class="desc"> <p>American poetry has resurged in cultural and political significance in the 21st century. Poets have reframed the nation''s controversies and recovered its forgotten histories. Notably, poets have shifted American consciousness without losing sight of artistic experimentation. Poetic genres, in this course, are more than familiar literary conventions. They are ways of thinking and feeling. Poets experiment with literary form in hopes of staying true to the nation''s complexities. Fragmentation, intertextuality, ekphrasis, and erasure are all crucial techniques for exploring beauty, mental health and disability, immigration and war. This course will examine several award-winning poets, including Kevin Young, Molly McCully Brown, Robin Coste Lewis, Solmaz Sharif, and Philip Metres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9706,2025,1700,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-274','<div class="desc"> <p>This course will focus on the intersections among race, gender, sexuality and culture in 19<sup>th</sup>, 20<sup>th</sup> and 21<sup>st</sup> century novels within three different cultural traditions: African American, Anglo American, and Native American. African American women writers include Harriet Jacobs, Nella Larsen, Zora Neale Hurston, and Toni Morrison. Native American women writers include Louise Erdrich and Leslie Marmon Silko. Anglo American women writers include George Eliot, Kate Chopin, and Virginia Woolf.</p> <p><span>Major Requirement Met: </span><span><strong>Group III/IV</strong></span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9707,2025,1593,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-280','<div class="desc"> <p>The focus of this course is writing, and developing a relationship with, short fiction, with the aim of making it a fluid manifestation of the way we process and transform memory and experience. We will play into and take seriously Toni Morrison’s conception of memory as <em>a form of willed creation</em>, in an ongoing attempt to reanimate forgotten or unrealized aspects of our histories and ourselves. Students will generate new work constantly—in sketchbooks, exercises, and story drafts—paying attention to the honing of various craft elements (description, dialogue, character and plot development), and in correspondence with texts by a variety of exemplary practitioners of fiction and prose writing (Venita Blackburn, K-Ming Chang, Fleur Jaeggy, Jamaica Kincaid, Maxine Hong Kingston, Li-Young Lee, Clarice Lispector, Scholastique Mukasonga, Nhã Thuyên, among others). Students will share and discuss their work in a workshop format, the orientation of which will be based, in part, on each student’s specific intentions. The discussions will be supportive, inquisitive, and constructive, and will be oriented towards helping to introduce each other—and ourselves—to what is most compelling and imperative about what we are doing, what it is that we want to be doing, and how we might get there. Open to first- and second-year students. May be repeated once for credit.</p> </div>','One First Year Seminar, CWP 201 (formerly WRD 201), or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9708,2025,1518,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-281','<div class="desc"> <p>This course introduces students to the fundamentals of poetry writing. Students will learn how to craft and revise poems, and will workshop their poetry in class with their peers. Outside readings will also be required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9709,2025,1221,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-287','<div class="desc"> <p>We might think that older literature by the likes of Chaucer, Shakespeare, and Milton is dustily conventional, a cultural tradition that we''re obliged to read (or compelled to disavow) but that has little relevance to our lives today. The goal of this class will be to persuade you, to the contrary, that the literature written during the period beginning with Chaucer''s Canterbury Tales in the late 14th century and ending with Milton''s Paradise Lost in the 17th century constitutes one of the most exciting and experimental moments in literary history, one that offers uniquely relevant lessons for contemporary thinking about community and storytelling, narrative and memory, truth and perception, race and power, as well as gender and sexuality. At the same time, we will explore what is productively strange, challenging, and even alienating about these texts from the past, measuring how their distance from us provides unique opportunities for thinking. We will also examine how authors such as Chaucer, Shakespeare, Spenser, and Milton came to constitute the foundation of the English literary canon, and how this canon has been used to advance (or to critique) English national and colonial ideologies. Together we’ll explore a set of analytic concepts and strategies for interpreting their unique texts that will make you a more sensitive, precise, and persuasive reader and writer.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9710,2025,1222,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-288','<div class="desc"> <div><p><span>A survey of modern British and Anglophone literature, this course ranges across the rise of the novel in the 18th century, the birth of Romanticism, the varieties of realism (and its others) in Victorian-era fiction and poetry written in England and across its empire, and modernismâs diverse experiments; it concludes with some more contemporary British and Anglophone writers that reflect on Britainâs past and present from different geographical standpoints. The survey is meant to help students explore, discuss, and write perceptively about the literary innovations in these different periods of British literature, and to situate the literary works studied in the historical contexts they were shaped by and responded to (including the Restoration, industrialization, the expansion of the British Empire, the World Wars, decolonization). Students will gain a broad understanding of modern British literary history and the spread of Anglophone literature across the globe during the 19th-21st centuries, cultivate their capacities for interpreting challenging poetry and fictional prose, and grow as analytic writers. </span></p></div> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9711,2025,1223,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-289','<div class="desc"> <p>Course topic when Professor Grossman is the instructor:</p> <p>This course surveys the history of US literature in relation to feelings. Beginning in the settler colonial period and working our way to the present, we will look at how a literary tradition forms its âAmericannessâ around the idea of shared, public, or collective emotions. Reading across fiction and poetry, weâll examine the emergence of genres like the captivity narrative, the Southern Gothic, and the presidential inauguration poem. Some of these works attempt to distill a national perspective--revolutionary resentment or liberal optimism, for instance--into the individual feelings of a character or poetic speaker. Others aim to implicate the reader in feeling and thinking across difference. We will pay particular attention to connections between discourses of race and antiracism as they consolidate in and around literary thinking. Throughout our discussions, we will consult a range of essays grappling with the limits of literature-induced sympathies, and consider how contemporary writers respond to the enduring legacy of âsentimentalâ imperatives. Our authors will include Mary Rowlandson, Phillis Wheatley, Nathaniel Hawthorne, Herman Melville, Emily Dickinson, Harriet Beecher Stowe, Zitkla-Sa, Sui Sin Far, Charlotte Perkins Gilman, Pauline Hopkins, Henry James, Langston Hughes, William Faulkner, Younghill Kang, Carlos Bulosan, Rodolfo âCorkyâ Gonzales, James Baldwin, Karen Tei Yamashita, N. Scott Momaday, Jhumpa Lahiri, and Elaine Castillo, among others.</p> <p>Course topic when Professor Ford is the instructor:</p> <p>This survey grapples with the centrality of war to American literature--indeed, to American life. The course moves chronologically through Early American and the American Revolutionary Wars and ends with the War on Terror. We will examine the strengths and limits of depicting war through lyric poetry, short epic poetry, political pamphleteering, oratory, autobiography, and the novel. In addition to considering literary forms, this course considers what understudied voices have to say about what leads to war, the experience of war, and its aftermath. Our readings will include Phillis Wheatley, Timothy Dwight, Philip Freneau, Walt Whitman, Ernest Hemingway, Zora Neale Hurston, Philip Metres, and Solmaz Sharif, among others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9712,2025,1224,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-290','<div class="desc"> <p>This course will introduce students to contemporary critical methodologies in literary studies. Students will engage a wide range of critical approaches to help ground their subsequent study of literature across the English department curriculum. By studying influential works of theory and criticism, students will become familiar with the historical genesis of literary studies, with special attention to the political, social, and other institutional factors informing the rise of particular methodologies in the academe. We will trace these critical genealogies so as to recognize and participate in the fullness of literary studies.</p> </div>','One First Year Seminar, CWP 201 (formerly WRD 201), or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9713,2025,2949,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/200/engl-295','<div class="desc"> <p>Topics vary. Different topics may satisfy different Core requirements.</p> <p><strong>The Dystopian Novel</strong></p> <p>This course explores the emergence of dystopia as a genre for the modern novel, reading the most salient works of the genre. We seek to understand what elements cohere the genre of dystopian fiction, what elements are borrowed from other forms and what invented anew. And finally, we also consider what is peculiar to dystopia as a genre all its own. </p> <p>Alongside such classics as Wells’ <em>The Island of Dr. Moreau</em>, Huxley’s <em>Brave New World</em>, Orwell’s <em>Nineteen Eighty-Four, </em>and Atwood’s <em>A Handmaid’s Tale, </em>we will also read work by Octavia Butler<em>, </em>Kazuo Ishiguro, Ling Ma, M.R. Carey and others. The syllabus will include brief philosophical and critical readings on utopia, science, satire, feminism, race, capitalism, and modernity and a few films (<em>Blade Runner; Babadook; Thing</em>). Core Requirement Met: Global Connections. Major Requirement Met: Group II.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9715,2025,1519,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-311','<div class="desc"> <p>Before the modern novel, we had romance: the literature of error and erring, stories of characters who set out on a quest and lose their way due to madness, obsession, lack of faith, or the difficulty of knowing the truth about themselves or their quests. Romance was one of the most important genres of imaginative literature in medieval and Renaissance Europe, and yet it was also the one that provoked the most profound moral and aesthetic concern. Hugely popular, romance was often condemned for its endless attention to pleasure, pain, error, and forgetting, for its perverse magical stories of exploration and complicity, for its unseemly analysis of chivalric duty and obsession--and even for its capacity to corrupt its readers beyond repair. (Famously, Don Quixote was driven mad by reading romances!) Whether viewed as a genre of utopian dreaming or of lurid and dangerous narrative failure, romance is a vexed concept. By examining pre-modern and modern genre theory, this class will explore the formation of the category of romance across medieval and Renaissance England (with some attention paid to France, Italy, and Spain), thus giving students an opportunity to consider how genre can enable and constrain understanding of particular works of literature. Texts may include Virgil''s <em>Aeneid</em>, Chrétien de Troyes Arthurian tales, Geoffrey Chaucer''s <em>Troilus and Crisyede</em>, the anonymous Pearl-Poet’s <em>Sir Gawain and the Green Knight</em>, Miguel de Cervantes''s <em>Don Quixote</em>, Philip Sidney’s <em>Arcadia</em>, Edmund Spenser''s <em>The Faerie Queene</em>, William Shakespeare’s <em>Cymbeline</em>, and Mary Wroth’s <em>Urania</em>. At the end of the semester, we may turn to more recent works (such as Samuel R. Delany''s speculative fictions or Caroline Bergvall''s poetics of error) to get a sense of how pre-modern romance remains an archive for some of the most exciting literary production today.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9716,2025,2829,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-314','<div class="desc"> <p>This course examines the poetry and poetics of the English Renaissance, emphasizing the relationship between formal developments in poetic techniques and questions of religious belief, gender, labor, race, education, and politics. Readings include classical and humanist poetic and rhetorical theory (from Plato to Puttenham) and a wide range of poets, including Thomas Wyatt, Anne Locke, Philip Sidney, Edmund Spenser, William Shakespeare, John Donne, John Milton, Andrew Marvell, Mary Wroth, and Katherine Philips, as well as some consideration of the influence Renaissance verse has had on modern poets (such as T.S. Eliot, Frank O''Hara, and Marilyn Nelson).</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 200-level English class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9719,2025,1594,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-322','<div class="desc"> <p>The Renaissance and Reformation in England witnessed the rise of imperial projects and the emergence of more centralized institutions to police sin and illegality in society; both were intended to enhance the sovereignty of the British state. This class explores the literary responses to such shifts in the culture of punishment and the project of state-building, asking why some of the most innovative works of drama, poetry, and prose in this period struggle with the purpose and effects of imprisonment, trial, penance, and slavery. Four main topics will organize the course: punishment and colonialism; the economic, theological, rhetorical, and theatrical underpinnings of legal trial; martyrdom; and the rise of the transatlantic slave trade. Each section of the course is divided into a series of sub-topics (ranging from questions of genre and psychology, to the humanist culture of teaching) to be explored through examination of a literary text and related historical and theoretical materials. Authors will include: John Foxe, Elizabeth I, Edmund Spenser, Michel de Montaigne, William Shakespeare, John Milton, Thomas Hobbes, John Locke, and Aphra Behn, among others.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9720,2025,2591,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-330','<div class="desc"> <p>We will examine both literary and philosophical texts to determine how notions of the human both conditioned and were conditioned by the diverse experiences with populations deemed colonizable by various European powers, with a particular focus on England. Philosophers such as Thomas Hobbes, John Locke, and Jean-Jacques Rousseau drew on travellers'' reports concerning Africa, South Asia and the Americas to support their arguments about whether there was something like human nature, and, if so, what its characteristics were. 18th-century British literary texts such as Aphra Behn''s <em>Oroonoko</em>, John Dryden''s <em>Aurung-Zebe</em>, Daniel Defoe''s <em>Robinson Crusoe</em>, and Alexander Pope''s "Windsor Forest," among others, work to develop or bring to life the images and ideas found in both the reports of travellers and the philosophical texts of the time, and in doing so expose the unacknowledged assumptions they contain.</p> <p><img src="https://ssl.gstatic.com/ui/v1/icons/mail/images/cleardot.gif"/></p> <p>Major Requirement Met: <strong>Group 2</strong></p> </div>','One 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9721,2025,1451,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-332','<div class="desc"> <p>The class will examine British literature from the novels of Richardson, Fielding, and Sterne to the poetry of Blake, Wordsworth, and Coleridge.</p> <p>Major Requirement Met: <strong>Group II</strong></p> </div>','One 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9722,2025,1226,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-341','<div class="desc"> <p>This course interrogates the crucial role of the law in British imperial governance by reading colonial legislation and court proceedings alongside works of 19th and early 20th century literature. Doing this allows us to examine how dominant legal paradigms were disseminated in the era''s cultural production and, in turn, how cultural ideals reflected in literature were materially implemented through the law. In addition, we will look at how literature often provided a viable means of contesting the normative terms of the law. </p> <p>Major Requirement Met: <strong>Group II/IV</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9723,2025,1520,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-345','<div class="desc"> <p>This course examines the increasing centrality of the theme of "tyranny" to American literature before 1900. Most people know the founders justified the American Revolution as a response to Britain''s tyranny during the colonial period. Fewer know that "tyranny" became a watchword for national debates over race, gender, and class conflicts. What happens to the idea of "tyranny" when it refers to threats within a nation rather than outside forces? What happens when the calls for revolution that founded the nation are asserted once again, to save the nation from its worst self? The political and ethical political implications of this 18th and 19th century conflict reverberate today. Only a multi-genre approach, incorporating a wide range of authors, could do justice to these questions. For these reasons, we will examine revolutionary pamphlets, speeches, essays, freed-persons narratives, and poetry from authors as diverse as Joseph Warren, Phillis Wheatley, Phillip Freneau, Harriet Jacobs, Ralph Waldo Emerson, Walt Whitman, and Emily Dickinson. Finally, this course listens to voices too often obscured by our focus on well-known characters in American history: the unofficial soldiers of the American Revolution, the freed-persons who emancipated themselves from slavery, the conflicted Civil War Veterans, and the working-class Americans trying to find their place in Reconstruction-era America. <br/> <br/> Major Requirement Met: <strong>Group II</strong></p> </div>','One 100-level or 200-level English course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9724,2025,1452,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-346','<div class="desc"> <p>This course explores literary representations of slavery, civil war, social reconstruction, and political backlash in 19<sup>th</sup> century America. Along the way, students will address several questions: How does literature represent demands for social change that transgress the law, like the freed persons escaping slavery? How to distinguish fugitives fighting for freedom from unprincipled outlaws? Is emancipation a single act, legal declaration or a more complicated process? And for whom? Finally, how do we grapple with the backlash to political change? By focusing on the 19th century, we can rethink how African Americans found political agency generations before the most familiar events from the Civil Rights era. Most of all, this course allows students to read literature alongside historical documents, so they can see firsthand how debates over freedom evolved in the 19<sup>th</sup> century. </p> <p>Major Requirement Met: <strong>Group II</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9725,2025,1453,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-351','<div class="desc"> <p>In this class we will examine fiction by British modernist writers such as Joseph Conrad, James Joyce, Virginia Woolf, Katherine Mansfield, D. H. Lawrence, and E. M. Forster. We will read their work critically, with attention to the ways in which it approached and reflected (or obscured) its historical context: changing gender roles, a fragile and distended empire, global reassessments of power, class, and race. We will also explore some representative later responses in British fiction to these central concerns of modernism.</p> <p>Major Requirement Met: <strong>Group III</strong></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9726,2025,2338,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-353','<div class="desc"> <p>Since the 2008 Crash, politicians, scholars, and journalists have compared America''s current economic challenges to the Great Depression. This frequent comparison does not exhaust the significance of the Great Depression for the U.S. or the rest of the world. The 1930s is such an intriguing decade because the global economic collapse spawned new, or renewed older, political and artistic movements. In the global 1930''s, people considered art central to rethinking political allegiances and the overarching meaning of politics itself. The 1930s helps to clarify the following question in our present-day: what cultural rebuilding remains to be done and how does art contribute to such processes? Writers of the 1930''s took up this question in several different forms: through the trope of the document and its archival drive, the unconscious and the search for the Marvelous, the raised fist of labor movements or antiÂ­racist activism. This course will look at several literary (and related art) movements in, and cutting across, America, the Caribbean, and Europe. Texts will include (but are not limited to) documentary writing from Muriel Rukeyser, Richard Wright, and Langston Hughes; Surrealist writing from Europe and the Caribbean, including Aime Cesaire and Georges Bataille; and other forms of art like the photography of Cathy Cahun.</p> <p>Major Requirement Met: <strong>Group III</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9727,2025,3324,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-360','<div class="desc"> <p>In her 1993 lecture for accepting the Nobel Prize in Literature, Toni Morrison says, “[s]he is convinced that when language dies, out of carelessness, disuse, indifference and absence of esteem, or killed by fiat, not only she herself, but all users and makers are accountable for its demise.” How does language die? What does it mean to be careless with language, to not use it, to be indifferent to it and rob it of its esteem? What does it mean to kill or stifle language by official decree? In our seminar on Toni Morrison, we will engage with the writings of one of the most preeminent writers and critical thinkers in literature (US-based and otherwise) in order to examine the powerful and provocative ways in which she asked and answered these questions before her passing on 05 August, 2019. We will situate her as a cultural critic, one who produced novels, short stories, essays and speeches and in doing so, informed the frameworks of American Literature, Black Feminist Theory, American Studies and Critical Race Studies, among other fields. Thus, we will collectively unpack the ways in which Morrison’s writings have guided, contested and informed American cultural and literary production in the 20th and 21st centuries. Students will be asked to complete a research paper at the end of the term. This course meets the second-stage writing requirement for Black Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9728,2025,1380,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-365','<div class="desc"> <p>Topics may vary semester to semester.</p> <p><strong>The Refugee</strong></p> <p>This seminar will explore how refugees have portrayed themselves and have been portrayed in literature, memoir, testimony, film, and art. Our goal will be to appraise whether and how aesthetic attempts to capture the condition of refugees respond to and at times revise political discourses about those in exile. Among others, we will engage with the work of Hannah Arendt, Primo Levi, Giorgio Agamben, Edward Said, Gloria Anzaldua, W.G. Sebald, Mahmoud Darwish, Caryl Phillips, Ghassan Kanafani, and Viet Nguyen.</p> <p>Major Requirement Met: <strong>Group III/ IV</strong></p> <p><strong>The Global Novel</strong></p> <p>This course will focus on literature and theory produced in the aftermath of the British Empire. By 1914 the British Empire had colonized almost 25% of the world, bringing diverse cultural traditions under the encyclopedic gaze of Western modernity. If part of the aim of the colonial apparatus was to collect knowledge of the world in ways that bodies, cultures, and landscapes could be understood and ordered by the West, contemporary societies are now negotiating their own means of self-representation in the often-violent space of postcolonial rupture. Throughout the term, we will work with texts and visual images produced out of, and in response to, the history of the colonial encounter. Drawing on a broad range of literary, filmic, and theoretical materials we will develop strategies for understanding the production and consumption of postcolonial representation, in both local and global contexts. As consumers of these cultural products within the space of the Western academy, we will be attentive to the function of the stereotype as we consider representations of gender and sexuality, violence and terrorism, class structures, and migration.</p> <p>Major Requirement Met: <strong>Group III</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9729,2025,1229,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-370','<div class="desc"> <p>Topics vary. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Trauma and Literature</strong></p> <p>How is trauma narrated? Can literature convey intense personal and collective suffering? Is our understanding of pain cultural? This course considers psychoanalytic ideas of historical and personal trauma reflected in literary works of the modern period. Our study will be interdisciplinary, considering how powerful concepts in the hermeneutic of psychoanalysis (repression; repetition compulsion; abjection; misrecognition; lack; affect etc.) have been generated by literary works, as well as challenged and absorbed into them. Insofar as traumatic experience produces a subjective breach, we will think about how certain forms and styles of literature are more or less suited to reflect the rupture. </p> <p>We will read formative texts of psychoanalysis (Freud; Lacan; Kristeva; Foucault and others) and trauma theory (Caruth; Silverman; Fanon; Nandy). Our survey of literary works includes texts by Jean Rhys, Toni Morrison, Han Kang, Teju Cole, among others. Core Requirement: Global Connections.</p> <p>Major Requirement Met: <strong>Group III/IV</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9730,2025,1455,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. </p> <p>Major requirement met: <strong>Group III or Group IV</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9731,2025,1381,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-380','<div class="desc"> <p>Our primary focus will be on fiction. Students will be required to respond thoughtfully and critically to assigned readings and to one another''s work. We will attend to general issues of craft, as well as to broader questions about the writing of fiction. Open only to juniors and seniors. May be repeated for credit.</p> </div>','ENGL 280 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9732,2025,1230,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-382','<div class="desc"> <p>The focus of this course is the writing of short fiction, though also where fiction might overlap with—and necessitate elements of—nonfiction, documentary, poetry. Students will build upon the foundations they established in prior writing workshops, while continuing to test the boundaries of their practice. Students will generate new work constantly— in sketchbooks, exercises, and story drafts—based on and inspired by readings, and especially their own preoccupations, curiosities, and experiences. We will read and discuss texts that both illuminate and complicate various formal possibilities, including by Etel Adnan, Jenny Boully, John Keene, Malika Mokeddem, Scholastique Mukasonga, Juan Rulfo, Sophia Terazawa, Jackie Wang, among others. And we will share and discuss our work in a workshop format. The discussions will be oriented towards asking questions, problem-solving, developing a generative relationship to revision, and towards challenging each other to go deeper into particular, perhaps unexpected, areas and aspects of our writing. Open to third- and fourth-year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9733,2025,1231,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-390','<div class="desc"> <p>The Junior Seminar is a small, discussion-oriented seminar required of all English majors, emphasizing advanced critical approaches to a literary topic. Enrollment is restricted to English majors who will pass the college''s Second-Stage Writing Requirement by satisfactory completion of the course writing requirements. Topics may vary year to year.</p> <p><strong>The Animal</strong></p> <p>This seminar will examine literary, filmic, and theoretical representations of the animal. Questions about the human as animal, and at the limit of animality, will be implicit in our discussion. Over the course of the semester, we will evaluate how the animal has been theorized and represented from the nineteenth century to the present. We will also consider the ways in which the animal has served as a cypher for exploring the category of the human. While the figure of the animal has provided a counterpoint to visions of humanity for centuries, emerging technologies and ideas about human consciousness have inflected the conversation in new and important ways. In what ways, for example, does contemporary technology compel us to reevaluate the distinctions between animal and human, on the one hand, and animal and object, on the other? The course will consider works such as Han Kang’s The Vegetarian, Werner Herzog’s Grizzly Man, Indra Sinha’s Animal’s People, and H.G. Wells The Island of Doctor Moreau.</p> <p><strong>Laughter and Non-Representation</strong></p> <p>While Aristotle is reputed to have written a treatise on comedy to match his famous discourse on tragedy, <em>The Poetics</em>, this is hard to believe as, in all his works, he shows almost no sense of humor. This first absence does not seem to have been filled in the many centuries that have followed. Both in number and quality, modern treatments of laughter seem inadequate. This weakness is perhaps because the funny is constitutively unavailable to rational representation. This class will explore laughter as exactly the embodied symptom that arises out of the intrinsic inadequacies of representation. After a quick critique of traditional theories of mimesis, we will explore the generation of laughter through various contemporary theories and attempt to understand its function for the liberation of the unrepresented in works thought funny, from Laurence Sterne to Ishmael Reed. Open only to junior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9736,2025,1597,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/300/engl-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9737,2025,1232,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/400/engl-490','<div class="desc"> <p>In this course, seniors will design and carry out advanced research projects in areas of their own interests. Seminar meetings will be devoted to discussion of a core group of theoretical and/or historical texts (varying from year to year), and to practical issues of sophisticated literary critical work. The course will result in a substantial critical paper, a version of which will be presented at the Spring Senior Symposium, in satisfaction of Occidental''s Comprehensive requirement. Open only to senior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9739,2025,1598,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/engl-english/400/engl-499','<div class="desc"> <p>Research, writing, and defense of the Honors thesis in English. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9740,2025,165,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/100/fren-101','<div class="desc"> <p>Introduction to French through a variety of communicative approaches. Emphasis is placed on speaking and listening, as well as grammar and writing. Students who have had more than one year of French in high school, or more than one quarter in college, may not take this course for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9741,2025,166,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/100/fren-102','<div class="desc"> <p>This course is a continuation of FREN 101. Students are introduced to the culture of the French-speaking world through readings and discussions.</p> </div>','FREN 101 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9742,2025,167,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/100/fren-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9743,2025,580,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/100/fren-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9746,2025,581,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/100/fren-197','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9747,2025,168,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/200/fren-201','<div class="desc"> <p>This course develops students'' speaking, listening, and writing skills in French, with a focus on intermediate grammar. Students read texts and are exposed to artistic work through a transnational lens to interpret 20th-century cultural history and contemporary literary, artistic, and social issues in various French-speaking regions of the world. Students are strongly encouraged also to enroll in FREN 151 / FREN 152 Intermediate Conversation.</p> </div>','FREN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9748,2025,582,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/200/fren-202','<div class="desc"> <p>The methods and vocabulary of textual analysis introduced through close reading, discussion, and written commentary of selected poems, plays, and prose texts, from the Renaissance to the present. The techniques of French critical writing, oral explication de texte, and commentaire composÃ© will be stressed. Includes study of general linguistic problems pertaining to the structure of modern French (vocabulary, phonetics, grammar style). This course is required of all French majors and minors and for students wishing to study abroad in the French-speaking world. Students are strongly encouraged also to enroll in FREN 251 / FREN 252 Advanced Conversation.</p> </div>','FREN 201 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9749,2025,169,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/200/fren-251','<div class="desc"> <div><div><p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. Graded on Credit/No Credit basis only.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9750,2025,583,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/200/fren-252','<div class="desc"> <div><p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. Graded on Credit/No Credit basis only.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9754,2025,842,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-301','<div class="desc"> <p>An introduction to late 20th-century Francophone literary works (short stories, a novel, poetry) and films, from the Levant (Lebanon, Syria) and North Africa (Egypt, Tunisia, Algeria, and Morocco). The course underlines the diversity of this part of the world, the various ways in which French is used, and its relation to the native tongue-Arabic. The Arab Spring and questions of cultural/national identity are also examined. Among authors studied are Tahar Ben Jelloun (Morocco) and Lamia Ziadé.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9755,2025,843,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-350','<div class="desc"> <p>An introduction to the theory and practice of translation from English to French ("thème"), and French to English ("version"), as both a craft and an art, with its codes and principles. Although emphasis is placed on practice, the course examines important theoretical questions, such as translation as both a product and as a process. With some attention to the difference between "literal" and "free" translation, the course explores the lexical and semantic strategies that translators employ. The course begins with the smallest "unit of translation," and progresses to consider a wide variety of texts: fiction; poetry (song lyrics); advertisements, televisual and filmic. Students may choose to translate a business, technical, legal, medical, or literary text as part of their final project.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9756,2025,170,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-355','<div class="desc"> <p>Readings and discussion in the French novel and philosophical texts, including works by Prévost, Diderot, Rousseau, Bernardin, de Saint-Pierre, Balzac, Stendhal, Flaubert, and Zola.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9757,2025,1070,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-363','<div class="desc"> <p>The course is an exploration of various literary and cinematic representations of the French colonial history and its impact on the peoples of the Maghreb and West Africa. It examines narratives of war, dominion, racism, and collaboration. Films and literary texts examined include: <em>Les Indigènes </em>(Rachid Bouchareb); <em>Le Camp de Thiaroye</em> (Ousmene Sembene); <em>Le Vieux Nègre et la Médaille </em>(Ferdinand Oyono); and <em>Meursault, contre-enquête</em> (Kamel Daoud).</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9758,2025,1016,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-365','<div class="desc"> <p><strong>French Feminism</strong></p> <p>Psychological and political views of the "disruptive" female presence in literature, and in the critical theory of Derrida and Lacan. Works will range from 17th century fiction, to feminist writers including Beauvoir, Irigaray, and Cixous, as well as examples of women''s self-writing in the Francophone world. Taught in French and English.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9759,2025,2443,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-370','<div class="desc"> <p>This course explores the history and development of one literary genre (fiction, poetry, theater, or cinema) across different periods and in different French-speaking communities. Content varies from year to year.</p> <p><strong>Francophone voices of Africa and the Caribbean</strong></p> <p>This course traces the development of literature in French by writers living in or originating from France’s former colonies, primarily the Caribbean and Sub-Saharan Africa. Through short stories, novels, and the <em>bande dessinée</em>, we will examine key intellectual, political, and social movements that have shaped, and continue to shape, Francophone postcolonial identities. We will consider themes such as decolonization, Negritude, tradition vs modernity, immigration and exile, and hybrid/Afroeuropean identities. Texts will include works by Aimé Césaire, Edouard Glissant, Maryse Condé, Mariama Bâ, and Alain Mabanckou. Additional Core Requirement Met: Global Connections.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9762,2025,585,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/300/fren-397','<div class="desc"> <p>Individual study of a major author, movement, or genre; or the teaching of French. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9764,2025,587,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fren-french/400/fren-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9765,2025,2958,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-1','<div class="desc"> <p>Are we ready for the Big One? How have water issues shaped the growth of California? Where has our energy come from and where will we get it from in the future? And can we move towards a more sustainable future? In this seminar, we will explore societally-relevant issues. Topics will include earthquakes, water, and issues related to energy and climate. These topics will then be expanded upon with scientific focus in the Geology 105 course.Open only to first-year frosh.</p> </div>',NULL,'GEO 105',NULL);
INSERT INTO course_descriptions VALUES(9766,2025,2966,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-10','<div class="desc"> <span>Norman Mailer described Los Angeles as a "constellation of plastic." John Fante called it a "sad flower in the sand." Is Los Angeles really just "72 suburbs in search of a city," as Dorothy Parker claimed, or is there something else brewing beneath the beautiful, sunny skies? We’ll explore (primarily through films and literary texts) 20th and 21st century Los Angeles as both a real and imagined location. Through the completion of three papers (including one with a research component), a self-directed field trip and other activities, you’ll craft your own conceptual “map” of the place. Please note that some of the literary and film texts for this course may be disturbing. Contact the instructor if you have any questions. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9767,2025,2967,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-11','<div class="desc"> <span>"Technology" is often thought of as being neutral and at its best providing solutions to problems without human bias. Despite this, contemporary developments in predictive policing and algorithmic racism, to give only two prominent examples, suggest that this is not the case. In Social Difference and the Politics of Technology we will discuss contemporary issues like AI, automation, and environmental technologies, and a longer history of technology dating to plantation slavery and European colonialism. The course will ask students to think about the ways that technological development has never been neutral and has always been connected to histories of race, gender, sexuality, and hierarchical conceptions of what it means to be human, as well as economics and labor, and ecological issues. In doing so we will look at a wide array of texts and media to examine these histories, to imagine worlds otherwise to them, and as a foundation for developing writing skills in order to ethically engage with technological change on an increasingly unequal and unstable planet. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9768,2025,2968,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-12','<div class="desc"> <span>From our pets to the animals that we see in popular media, nonhuman animals represent a central component of the human experience. The prevalence of animals in our daily lives invites questions surrounding how animals think and reason about the world around them. This course will provide an overview of the many perspectives on animal intelligence and the scientific frameworks used to explore how animals think. Our discussions of animal intelligence will feature species traditionally thought to be highly intelligent, such as dolphins and whales, as well species whose intelligence is often overlooked, such as ants and bees. We will also explore the intersection between research on animal intelligence and debates surrounding animal ethics. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9769,2025,2969,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-13','<div class="desc"> <span>Disease prevalence, severity, and treatment varies across sociodemographic groups. Understanding why health disparities occur is key to determining how inequalities might be alleviated. Central to detangling health disparities are psychological, socio-cultural, cognitive processes, and behaviors that are related to ethnic, cultural, and gender identity experiences. The focus of this course is on research that a) describes health disparities, b) investigates factors that explain differences, and c) proposes interventions to treat at-risk populations. This course will emphasize the theme of equity in health across multicultural groups. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9770,2025,3265,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-14','<div class="desc"> <p><span>For several decades, scholars and activists have documented, analyzed, and organized against the myriad ways that race shapes the quality of environments in which human life unfolds. Their work has consistently revealed that environmental burdens, such as air pollution, toxic contamination, and urban heat island effects (to name a few), are distributed unequally across the color line,â and that both nonwhite and low-income populations are most vulnerable when it comes to dealing with "natural" disasters and their aftermath.â People of color also often lack adequate access to environmental amenities and necessities like tree canopy cover and green space,â in addition to having inadequate access to healthy and affordable foods.â This scholarship points to different facets of we might call racialized socioecological relations, or those relations and dynamics between humans, nonhumans, and ecosystems, that are mediated by racial hierarchy and difference. In this course, we will study racialized socioecological relations at various scales, from the neighborhood to the globe, with the underlying aim of rethinking “race,” “the environment,” and their complex relationship. Open only to first-year frosh.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9771,2025,2971,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-15','<div class="desc"> <p><span>More than simply a "god of wine," Dionysus was for the Ancient Greeks a god of ecstatic self-abandon, of gushing fertility, of violent dismemberment and unexpected rebirth. In myth he was attended by raving Maenads and mischievous Satyrs; amongst humans he was worshiped with festive dances, communal shouts, ritual obscenities, and (perhaps most importantly) with poetry—with the literary genres of ode, comedy and tragedy that were invented specifically to honor him. What could be farther, we might ask, from the cool, reasonable practice of philosophy than this wild, uncanny, irrational god? And yet, as we shall see in this class, this reckless god of madness and poetry stands at the foundation of some of the most important ideas in modern philosophy—Hegel''s phenomenology of spirit, Nietzsche''s will to power, Heidegger''s philosophy of Existenz, Bataille''s notion of excess, and Derrida''s "non-concept" of différance. Beginning with an exploration of Dionysian poetics in Ancient Greece, this course will attempt to show what thinkers like these found so inspiring in this ancient god, and what the writers and thinkers of our own time might yet find in him still. Open only to first-year frosh.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9772,2025,2972,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-16','<div class="desc"> <span>In this seminar, we will learn how the mathematics of chaos helps us to better understand science, economics, psychology, and our environment. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9773,2025,3266,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-17','<div class="desc"> <p>While poetry often gets framed as a path for individual expression, poetry has proven especially effective for questioning the terms of cultural belonging, political agency, and collective memory. This seminar will examine poets from several different cultural traditions. Poetic form is constantly changing along with our rapidly changing world, in order to address the gaps and contradictions that narrative cannot always fill. For that reason, this course is interested in the centrality of experiment to poetic creation.</p> <p>Close readings of poetry from Phillis Wheatley, Derek Walcott, Solmaz Shariff, Marlene Nourbese Philip, Philip Metres, and Kevin Young will provide test cases for improving our skills in writing thesis-driven and argumentative essays. Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9774,2025,3267,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-18','<div class="desc"> <p>How do racial categories get constructed in the United States? Who and what decides which groups get lumped together and which should be classified separately? This seminar will explore the history of the AAPI (Asian American and Pacific Islander) racial category. Asian Americans and Pacific Islanders share histories shaped by US wars and militarism, racialized exclusion, and community activism of resistance. But settler colonialism, which has led to Indigenous movements to reclaim land and political control, shaped Pacific Islander (PI) histories in ways Asian Americans typically have not experienced. Many Pacific Islanders "became American" through annexation and/or colonization by the United States, not through im/migration. In this way, PI history has as much or more in common with Native American and indigenous histories as it does with Asian American history. These differences have had implications for the possibilities of solidarity both historically and in the present. Such complications will be the basis for an exploration in this seminar of different sites of racial construction, including law and policy, popular culture, community and grassroots activism, and academic scholarship. Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9775,2025,2973,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-19','<div class="desc"> <span>This seminar explores the relationship between food, race, and migration for Latinx populations in historical and contemporary U.S. contexts. The course is organized thematically with a fundamental consideration of how and why food has shaped Latinx migrant communities and collective identities. Through Ethnic Studies and Gender Studies frames and topics such as cultural memory, labor, agriculture, authenticity, gentrification, and health, we will examine debates about the role of food in assimilation and transculturation as well as the interplay between production, distribution and consumption of food. California as a subject of study will play a prominent role in our studies. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9776,2025,3264,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-2','<div class="desc"> <p>Modules in this course will center reading, discussion, writing, and art practice around questions of power, belonging, exclusion, visibility and invisibility among others. Issues of race, gender and sexuality will also inform our work together. Collaborative projects with locally and globally diverse communities and individuals will further shape this course, as will studio visits with artists, filmmakers, curators, historians, and media makers in LA/the US, South/Southeast Asia, Mexico, and Europe. By the end of the immersive, students will have gained critical skills in discussion, research, and writing alongside creative skills in visual media making to independently produce a visual media project. Open only to first year frosh.</p> <p>This immersive program will center on visual artistic practices that challenge and critique dominant systems of power by manipulating historical and contemporary media to reimagine, reconstruct, and reclaim history and narratives. We will explore how photography, film, visual and media arts play powerful roles in the shaping of histories, both those we think of as “back in time” and those of our present day world. </p> <p>The program consists of two linked courses</p> <ul> <li>FYS 2: Subversive Art and Media: Reimagining History and Narrative (4 units)</li> <li>ARTH 296/MAC 296: Subversive Art and Media (4 units)</li> </ul> <p>By participating in this program, you will fulfill your Fall FYS, Core Global Connections, and Core Fine Arts requirements. </p> </div>',NULL,'Linked with ARTH 296 / MAC 296',NULL);
INSERT INTO course_descriptions VALUES(9777,2025,2974,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-20','<div class="desc"> <span>The emancipation of four million enslaved people during the US Civil War marked the largest scale abolition of slavery in the Western Hemisphere. This unprecedented social and political revolution was accomplished not only by elite politicians and generals but also by millions of emancipated African Americans. Historian Barbara Jeanne Fields wrote, “freedom was no fixed condition but a constantly moving target.” Building on traditions of resistance established under chattel slavery, freedpeople struggled to make freedom a reality along many dimensions, including bodily sovereignty, land, labor, intimate relations, family integrity, education, and citizenship. In this class, we will immerse ourselves in primary historical documents—including letters, military reports, petitions, and newspapers—seeking to understand how African Americans pursued their vision of freedom from wartime through Reconstruction. We will also take the “long view,” as the poet Langston Hughes put it, to examine the legacies of emancipation as seen from our contested present. At the end of the course, students will participate in a social justice project. This course is part of the Humanities for Just Communities curriculum. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9778,2025,2975,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-21','<div class="desc"> <span>Can young lawbreakers be rehabilitated, or should they be removed from society to prevent them endangering others? Since the 1820s, reformers, philanthropists, and state officials throughout the Western world have wrestled with the question of how to reduce juvenile crime and turn delinquents into good citizens. The institutions and policies they created reflected their conceptions of young criminals, their backgrounds and families, their gender and their race. How did experts develop a body of knowledge about at-risk youth, what practices did they put into place, and what spaces did they build to house and contain the children? How have the children themselves responded, developing a sense of their own identity through compliance with or resistance to reformers'' intent? Reformers and policymakers adapted their solutions to national and local contexts, but they also participated in an international network of experts from Europe and North America that debated ideas and offered new models for responding to juvenile delinquency. We will explore ideas, practices, and institutions created to save juvenile delinquents, presented in reports and studies as well as fiction and film. Students will encounter a variety of primary and secondary sources from Britain, France, the USSR, and the USA from the early nineteenth century to the present day. Note that the course will sometimes address difficult or distressing subject matter. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9779,2025,2976,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-22','<div class="desc"> <p><span>Beginning in England over 150 years ago, association football, commonly known as soccer in the United States, has evolved from a working-class tradition to a multi-billion dollar global industry. Argentina''s World Cup final victory over France in 2022 had a global audience of roughly 1.5 billion people, making it a far larger event than the 2022 NFL Super Bowl''s audience of roughly 115 million. Passion for the game connects fans in the legendary arenas of Wembley Stadium (England), Estadio Azteca (Mexico), and Maracanã Stadium (Brazil) among others, to the suburban fields of the United States, and makeshift pitches across the globe. Given its ubiquity, with possibilities to watch the game on television 24/7, not to mention on the small screen of everyone’s smartphone, one wonders, how can soccer be used as a prism for learning about society? <span>Open only to first-year frosh.</span></span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9780,2025,2977,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-23','<div class="desc"> <span>In this seminar we will explore recent debates about originality, authenticity, imitation, sampling, and appropriation, within the context of the American judicial system, copyright law, and the history of the American popular music industry. We begin with the earliest forms of American popular music in the 1800s and work up to the present, examining how copyright laws and music industry practices have changed to keep up with evolving technology. Assigned readings span a rich and interdisciplinary mix of scholarly research, newspaper articles, interviews with artists, blog posts, album reviews, legal proceedings, and (of course) music recordings themselves. The culmination of the course will be a research paper in which students examine the stakes and outcome of a recent act of musical larceny. Knowledge of music is not required. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9781,2025,3268,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-24','<div class="desc"> <span>Mariame Kaba, an anti-violence activist and advocate of abolishing prisons and policing, has said, “As a society, we have been so indoctrinated with the idea that we solve problems by policing and caging people that many cannot imagine anything other than prisons and the police as solutions to violence and harm.” This course revolves around Kaba’s insight. To imagine a freer and more just world, we begin by discussing concepts of freedom. Then we use these concepts to discuss the many ways that those in the prison system are denied freedom, as well as the ways that people are manipulated toward complicity in an unjust status quo, even sometimes in our own oppression. Then we will examine how certain social movements have developed practices to resist social and political coercion, with special focus on how their work enables us to discuss and imagine more freely. At the end of the course, students will engage in a social justice project that will give them the opportunity to envision and work towards a more just world. This course is part of the Humanities for Just Communities curriculum. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9782,2025,3269,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-25','<div class="desc"> <span>In this course, we will examine historical and contemporary approaches to social documentary photography—visual anthropology, citizen journalism, and agitprop, among other forms. We will consider the efficacy of photographic images in garnering awareness and persuading actors to enact sociopolitical change. We will draw consensus on our understandings of “the real," both in tandem to and opposition with staged, scripted, and/or verisimilar depiction modes, while examining the ethics of capturing another''s likeness. Over the course of the semester, we will delve into critical writings and works by documentarians/collectives that either bring the liberal humanist documentary model into complex new territories or refute its criteria entirely. Together, we will confront our role as image-makers, our ethical relationship to our subjects, and ruminate on the civic value of the social documentary form today. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9783,2025,2979,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-26','<div class="desc"> <span>In "The American Scholar," Ralph Waldo Emerson urged the spirit of a young nation to take control of its literary destiny, so as "to look from under its iron lids, and fill the postponed expectation of the world with something better than the exertions of mechanical skill." Following Emerson’s invocation, American literature more than fulfilled this charge, establishing itself as a unique and prosperous field through meditations on his notion of individuality. This course will look at the development of American letters as it unfolds in the context of Emerson’s call to arms, reading genre’s of romanticism, realism and regionalism, modernism, and more. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9784,2025,2980,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-27','<div class="desc"> <p><span>This seminar examines the generative relationship between urban experience and creative expression in major metropoli—such as London, Paris, New York, Berlin and Los Angeles—in the 19th and 20th century. We will consider how the material and social aspects of urban life have informed works of literature, painting, photography and film. Open only to first-year frosh.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9785,2025,2981,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-28','<div class="desc"> <span>This seminar is essentially a course in cultural anthropology. Cultural anthropology emerged within the past two centuries as a means of coming to grips with the diversity of ways of being human. While cultural anthropology’s history has been tainted by collusion with racist and imperialist programs, it remains the single loudest academic voice on behalf of indigenous peoples around the world—not only in terms of advocacy for such folks, but also in terms of fomenting understanding of people who are not like us. In this course, we will look at a part of the world—New Ireland, Papua New Guinea—that is different, in many respects, from the WEIRD (Western, Educated, Industrialized, Rich, Democratic) societies from which most, if not all, of the students in this class come. In so doing, we will discover that non-WEIRD societies have a logic to their ways of being and relating, and that sometimes, WEIRD ways of doing things are, well, weird. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9786,2025,2983,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-29','<div class="desc"> <span>This course introduces three theoretical perspectives on sexuality: biological, psychological, and social construction. With these perspectives in mind, we address pressing topics involving sex—prostitution/sex work, abortion, pornography, and sexual violence. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9787,2025,2959,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-3','<div class="desc"> <p><span>Given the desperate situation of our world—environmental crises, racial injustice, reactionary politics, out of control AI—it can be hard not to devolve into dystopianism and despair. Yet, in this course, we will focus on religious communities who, faced with similar societal challenges, imagined a hopeful future: utopia. We will see that utopian thinking tends to flourish during times of precarity and unrest, when the fracturing of the old social order opens up new spaces of possibility. The course starts with a brief genealogy of utopian socialism-inspired intentional communities and political reform across the Atlantic world, with special attention on its religious and philosophical roots. From there, we will study the utopian visions of a range of communities from the late-nineteenth century to the present, including the Oneidan community’s vision of sexual liberation, the early Rastafari commune at Pinnacle, and the communist community at Marinaleda in Spain. We’ll explore how their utopian visions inspired political change and consider what lessons these communities might offer us today. Students will get firsthand experience with both the promise and challenges of living in alternative societies through site visits to historic and contemporary intentional communities in Los Angeles. Students will also engage in a social justice project so they can themselves envision and work toward a more utopian future. This course is part of the Humanities for Just Communities curriculum.</span> </p> <p>Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9788,2025,2982,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-30','<div class="desc"> <span>This seminar considers how Asian and Asian American artists, filmmakers, and writers have responded to Western fantasies and fears of Asia—its cultural influence, its economic might, and its military ascendance—through the conventions of speculative fiction. We will examine how representations of Asian bodies and landscapes in alternate realities, possible futures, or revisionist histories negotiate what scholars call techno-Orientalism—problematic visions of Asia as simultaneously hypo- and hyper-technological. By exploring contemporary literary (novel, short story, poetry) and cultural production (film, music video, artwork), we will work toward answers to the following questions: why do futuristic visions of North American cityscapes resemble Hong Kong, Seoul, Tokyo, and other Asian megacities? How does techno-Orientalism explain the contradictory origins of COVID-19 in both Chinese wet markets and laboratories? And, how has our understanding of humanity been reoriented amidst the onslaught of aliens, cyborgs, and other nonhuman entities? Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9789,2025,2984,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-31','<div class="desc"> <span>This course offers a survey of German film from the origins of cinema to the present day. We will focus on questions pertaining to how one can interpret or "read" a film, as well as the relation of German film to contemporaneous developments in art, literature and politics. How is the authoritarianism of the early 20th century depicted and/or confronted in film? What do horror films tell us about the anxieties and prejudices of the societies that produced and consumed them? Throughout the course, we will investigate the ways in which the dilemmas and aspirations of the modern world became legible in film, and continually ask to what extent film is a medium uniquely suited for depicting and attempting to understand modernity''s paradoxes. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9790,2025,2960,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-4','<div class="desc"> <p><span>While the term "romance novel" today often calls to mind tawdry love stories featuring heaving bosoms and uncontrollable passions, the genre of romance is much more complex than these stereotypes would make it seem. Early examples of romance are sprawling adventure narratives of chivalry, crusades, the supernatural, and yes, occasionally even love. Today, these tales have evolved into the modern day romance novel - a genre known for celebrating love, but which also often questions gender, sexuality, family and friend relationships, and professional success. In this course we will explore the genealogy of romance, asking not only what constitutes a romance, but also what the continuously popular genre can teach us about readers'' desires and discontents across history. </span>Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9791,2025,2961,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-5','<div class="desc"> <span>This course will examine the diverse ways that Asians conceptualize and engage in romantic and sexual relationships in ways that complicate the hegemonic Western stereotype of Asian men as emasculated and Asian women as hypersexualized. For example, we will examine the sex tourism and sex work industry in different parts of Asia. We will comparatively examine the stories of Asian marriage migrants. Furthermore, we will examine how queer Asians conceptualize their queerness in relation to the hegemonic white Western queer identities. In addition to academic journal articles and books, materials we will cover throughout the course will include various forms of popular cultural contents ranging from magazine articles, photographs, and films, to music videos, and social media posts. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9792,2025,2988,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-51','<div class="desc"> <span></span> <div> While the term "romance novel" today often calls to mind tawdry love stories featuring heaving bosoms and uncontrollable passions, the genre of romance is much more complex than these stereotypes would make it seem. Early examples of romance are sprawling adventure narratives of chivalry, crusades, the supernatural, and yes, occasionally even love. Today, these tales have evolved into the modern day romance novel - a genre known for celebrating love, but which also often questions gender, sexuality, family and friend relationships, and professional success. In this course we will explore the genealogy of romance, asking not only what constitutes a romance, but also what the continuously popular genre can teach us about readers'' desires and discontents across history. The course will include two mandatory field trips: one to visit The Ripped Bodice, a romance-focused bookstore in Culver City, on a Friday afternoon to be determined; and the other to the Los Angeles Festival of Books, Saturday April 26-Sunday April 27, exact day and time TBD. <span>Open only to first-year frosh.</span></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9793,2025,2989,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-52','<div class="desc"> <span></span> <div> <div><span>Asian/American women have always used writing, speaking, and other modes of cultural production to address oppression that cuts across gender, race, and citizenship. In this class, we will read writings by Asian/American women and analyze them using an Asian/American feminist transnational rhetorical lens. To understand the impact using a specific Asian/American feminist rhetorical lens, we will begin by reading the work of activist-scholars who have made visible the powerful work of Asian/American women in addressing forms of oppression. For example, we will read Mira Shimabukuro who analyzes archives of writing by Japanese and Japanese American women incarcerated in internment camps during WWII. We will also read work by Eileen Lagman who explores the literacy development of overseas Filipina workers in the Filipina Diaspora. Our engagement with these scholars will serve as a starting point to introduce students to Asian/American Rhetoric’s methods of analysis (rhetorical analysis, visual rhetorical analysis, content analysis, historiography), but also the often ignored rhetorical work by Asian/American women. Additionally, a panel discussion will be scheduled during the semester, where we will learn how local Asian/American activists who focus on issues that Asian women in the diaspora face address transnational issues through cultural production of written and visual texts. Students will also be expected to participate in several field trips to learn more about the community organizing work that Asian/American women are doing in the Los Angeles community. </span>Open only to first year frosh.</div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9794,2025,2990,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-53','<div class="desc"> <span></span> <div> <div>Explores the various ways in which certain persons are granted sexual pleasure, like straight<br/> men, HIV-negative persons, abled persons, and certain races, while others are not. Policies<br/> aimed at controlling sexuality and body autonomy will also be considered. The course will<br/> examine feminist approaches, media representation, and particularly the unrealistic,<br/> harmful norms and imagery in advertising, music, film, and television contributing to<br/> potential harm to young women and girls. One mandatory field trip. Open to first-year frosh<br/> only.</div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9795,2025,2991,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-54','<div class="desc"> <span></span> <div> This course explores the complex interplay between politics, economics, and the energy sector as nations and regions transition toward sustainable and renewable power sources. We will examine the history and evolution of global energy systems; the role of states and markets in shaping energy policy; technological innovations driving energy transitions; the geopolitics of energy; and the environmental and social implications of these transitions. To complement our theoretical studies, we will engage in mandatory field trips to Power Plant One, the Los Angeles Cleantech Incubator, and the Port of Los Angeles, offering firsthand insights into how these local entities contribute to and are impacted by global energy trends. Open to first-year frosh only. </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9796,2025,2992,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-55','<div class="desc"> <span></span> <div> <div><span>This course uses a feminist lens to analyze transnational documentary and feature films. We will examine the politics of gender in films produced in the West and the Global South and we will assess the flows between "first world" and "third world" cinematic traditions. Students will gain the necessary skills to analyze representations of gender, race, class, nationality, and sexuality in transnational film. The course considers how film can be a powerful tool that operates in the perpetuation of "third" and "first world" hierarchies and the economic, racial, and gendered inequalities that stem from histories of colonization. We will also consider how film can offer a critique of these dominant ideologies and inequalities that reflects postcolonial relations between "first" and "third" worlds. We will turn to feminist film theory, documentary film theory, cultural studies and postcolonial feminist theory in order to facilitate our analysis and class discussions of these films. Open only to first year frosh.</span></div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9797,2025,2993,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-57','<div class="desc"> <span></span> <div> <div><span>Are you sick of happy endings, sunny skies, and “likeable” characters? Then enter into a world that celebrates dark clouds, shady people, and a trail of physical and psychic casualties. Welcome to film and literary noir. In this class, you’ll watch a slew of films, old and new, that paint a less than wholesome picture of Los Angeles. You’ll read stories that feature dead-end alleys, nihilistic detectives, and dangerous love interests. Then you and your (assigned) team will make a short film of your own, from which you’ll build a thoroughly researched case for your place in the noir canon. An optional field trip to troubled downtown destinations will likely also be on offer. <br/> <br/> Note: This class features literature and films that are violent and/or disturbing. Email the instructor at elamj@oxy.edu if you’re concerned about the content. </span></div> <div><span>Open only to first year frosh.</span></div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9798,2025,2994,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-58','<div class="desc"> <span></span> <div> <div><span>More often than not "sustainability" "green technologies" and "green growth" are the main responses to the multiple crises which are today usually collected under the name "climate change." Yet, what is being sustained in these discussions? And is a continued high consumption, high energy, GDP growth-oriented future possible or feasible, even if actual renewable energy is developed? In the course students will examine an array of alternatives to high tech futures including composting, work about metabolism and ecological rift, the right to repair movement, degrowth political economies, as well as writing about environmental racism and community land trusts, among other topics. In doing so we will examine a wide variety of text and media and use them as the foundation for both developing academic writings skills and for engaging in with these issues beyond the university. <span>Open only to first-year frosh.</span></span></div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9799,2025,2995,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-59','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span>This course is essentially a course in cultural anthropology. Cultural anthropology emerged within the past two centuries as a means of coming to grips with the diversity of ways of being human. While cultural anthropology''s history has been tainted by collusion with racist and imperialist programs, it remains the single loudest academic voice on behalf of indigenous peoples around the world-not only in terms of advocacy for such folks, but also in terms of fomenting understanding of people who are not like us. In this course, we will look at a part of the world?New Ireland, Papua New Guinea-that is different, in many respects, from the WEIRD (Western, Educated, Industrialized, Rich, Democratic) societies from which most, if not all, of the students in this class come. In so doing, we will discover that non-WEIRD societies have a logic to their ways of being and relating, and that sometimes, WEIRD ways of doing things are, well, weird. This is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</span><span>Open only to first-year frosh.</span></div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9800,2025,2962,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-6','<div class="desc"> <p><span>Why are the senses important? They are our means of experiencing the physical world. We are born to see, hear, touch, taste, and smell, through which we perceive, experience, and make sense of our surroundings. This course explores the vital role of the senses in human experience and their representation in Chinese literature. Through various genres and historical periods, we will examine how sight, hearing, touch, taste, and smell are depicted in literary works. By analyzing these sensory descriptions, we will uncover how authors'' philosophical views, aesthetic preferences, and personal interests influence their ways of writing about sensory experiences. The course emphasizes that our sensory experiences are both collective and individual, highlighting the diverse ways in which we perceive and interpret the world around us. </span>Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9801,2025,2996,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-60','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span>One of the unique characteristics of modernity is the belief that the meaning of our lives is not given to us, pre-determined by race, class, gender or familial inheritance, but something that each individual must determine for themselves. To be a self in modernity, in other words, is to be a living project, a project in which we each determine the meaning of our lives by virtue of the paths we take, the passions we pursue, and the actions we choose. This idea, however, is neither acultural nor atemporal, but largely the historical inheritance of the ground breaking philosophical, literary, and artistic movement that occured in Germany around 1800 known as German Romanticism. Within European history, it was this Romantic movement which first developed the idea that became so central to modernity that each human being is thrown out onto a path, on a search for meaning in a world in which no absolute meaning can be given. This course will investigate this problem by engaging with some of the central works of German Romanticism as well as the artistic and intellectual movements that it inspired such as American Transcendentalism and Existentialism. We will investigate these themes in an interdisciplinary way by reading works of literature, philosophy, and music as well as looking at works of art and film both historical and contemporary. Reading may include: Novalis, Beethoven, Nietzsche, Van Gogh, Ralph Waldo Emerson, Hermann Hesse, Carl Gustav Jung, Albert Camus, Sartre, J.D. Salinger, Jackson Pollock, Jack Kerouac, Sylvia Plath and James Baldwin. </span><span>Open only to first-year frosh.</span></div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9802,2025,3280,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-61','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> The works of philosophy, literature, and cinema from East Europe open the ways of knowing and being that help us notice and sometimes escape authoritarian institutions and ideologies. A novel by a Ukrainian writer, Mykhailo Kotsiubynsky and a film by an Armenian director, Segei Paradjanov will allow us to understand some of the pagan beliefs of the Hutsul people from the Carpathian mountains. These beliefs that survived under a thin veneer of Christianity until last century reveal a distinct ontology that challenges some of the core principles of our own times. Philosophical Letters of Petr Chaadaev and Sergei Eisenstein’s film Ivan the Terrible will allow us to reflect on the importance of memory and perversity of tyrants. A Georgian philosopher, Merab Mamardashvili will help bring into relief the significance of civil society and personal responsibility.<br/> <br/> Students will be expected to participate in a workshop and attend a field trip. <span>Open only to first-year frosh.</span></div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9803,2025,2998,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-62','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div>In this course, we will examine how chemistry intersects with other areas of science and, more broadly, with society. Topics may be chosen by students according to their areas of strongest interest, from social justice-related issues pertaining to manufacturing, pollution and safety; to environmental-related issues such as how climate change has impacted chemical systems in the natural world and what solutions chemistry may offer; to health-related issues including the discovery of and access to medicines and understanding of diseases; to any number of other interdisciplinary areas of chemistry. There will be mandatory on- and/or off-campus field trips to tour modern chemical research labs in various areas of study. <span>Open only to first-year frosh.</span></div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9804,2025,2999,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-63','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span>Socrates famously said that the unexamined life is not worth living. Even with his example in front of us it is not entirely clear what it would mean to live an examined life. Is an examined life necessarily a good life or a happy one? And what does an examined life demand of us? In this course we will read the autobiographies of monks, bohemians, artists, and obsessives, as well as the reflections of libertines and the politically committed--all in an effort to come to terms with what it means to live thoughtfully and with purpose. In the process we will explore the nature of autonomy, authenticity, freedom, vocation, commitment and happiness in a bid to launch you on your own pursuit of these very questions. </span><span>Open only to first-year frosh.</span></div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9805,2025,3000,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-64','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span>First year seminar. Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9806,2025,3281,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-65','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span><span>More than half the world''s population is now urban. The vast amount of wealth created and exchanged in cities is unequally distributed, and since the advent of modern industrial production, every large and prosperous city has had at least one neighborhood in which working-class or marginalized people live in poverty. This course will examine these neighborhoods from a variety of perspectives, from the early nineteenth century to the present day, in Europe, Africa, and the USA. We will read accounts of slum residents and their strategies for surviving and building identity and community, as well as evaluating various efforts to reform, purify, or eliminate these neighborhoods through urban planning, philanthropy, social control, or revolution. We''ll also read the work of environmental, social, and cultural historians of cities. How have race, class, and gender shaped urban built environments and the lives of their residents? What role has empire played? What approaches have been most successful?</span> Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9807,2025,3002,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-66','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> This course will explore the historical and contemporary significance of land, spatial relations, place making, and identity for Black communities. There is a powerful tradition of resourcefulness and regeneration that ties Black people to land and there is also a history of trauma and injustice. As they encounter theft, displacement, and erasure, how do Black communities resist, repair, remember, restore, and imagine futures for themselves? We will research different tools and models used in these efforts and students will work on projects using these tools and models. Topics and themes will include black geography, colonialism, enslavement, indigeneity, property, gentrification, marronage, historic preservation, memorialization, and reparations among others. This course will include a few field visits outside of normal class time. Open only to first year frosh.</div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9808,2025,3003,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-67','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div>Using, interpreting, and understanding data is increasingly important for understanding the world. This course provides an introduction to data analysis, discussing how social scientists quantify key concepts, test theories using empirical data, and evaluate policy effectiveness. Students will learn basic statistical methods and data analysis techniques, including how to clean, visualize, and analyze data using Google Sheets. The course will also focus on interpreting data and communicating about it effectively to various audiences. We will develop these skills by discussing a range of topics, such as poverty and inequality, macroeconomic growth, health, and education. Open only to first year frosh.</div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9809,2025,3004,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-68','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span><span>In 2015, a photograph of a dress circulated all over social media. The illusion became a sensation overnight: people disagreed as to whether the dress was blue and black or white and gold. Some people felt locked into a specific visual experience, whereas others were able to see both blue/black and white/gold. What accounts for such individual variability? How do our eyes and brains generate our perceptual experience? This course will explore the science underlying a wide array of perceptual illusions spanning the various senses (visual, auditory, tactile, vestibular, and multisensory). In addition to understanding the underlying science, we will also focus on the role that illusion has played and continues to play in the arts. We will ask how and why artists use illusion, and experiment with illusions through drawing and digital design. This course will also bring in guest artists to lead various workshops.</span> Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9810,2025,3354,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-69','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span><span>This course traces the natural and cultural history of the Arroyo Seco tributary of the Los Angeles River and the dramatic transformation of its original indigenous landscape by cycles of urban development since the late 19th century. We explore the succession of bohemian scenes from the "Arroyo Culture" of the Arts and Crafts architecture and design movement, to the efflorescence of Latina/o arts that activated the community after mid-20th century trends of freeway construction, disinvestment and white flight. We examine new challenges confronting the region including gentrification, displacement and race and class transition. We also explore strategies to promote the arts, community gardening, and housing justice. This class will feature field trips and engagement with neighborhood partners involved with regional place-keeping and community- building and will involve students in project-based initiatives including data mapping and/or oral histories.</span> Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9811,2025,2963,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-7','<div class="desc"> <span>Broadway musicals are paradoxical. For all their quality, popularity, and variety, musicals have been historically disparaged as escapist entertainment: romantic and/or comedic romps that are, for the most part, thematically light and spectacle-oriented. And then Hamilton, right? Not so fast. Singing and dancing theater artists have dramatized hard-hitting social dynamics throughout the history of the form. This course will explore the development of the distinctly “political” stage musical. Offerings will track its rise throughout the 20th century (in shows such as Showboat, Cradle Will Rock and Hair), to contemporary productions that tackle a variety of issues through a decidedly intersectional lens (like Caroline, Or Change and Passing Strange). Our inquiries will also address representation and access. For all of the evolution of the genre, musicals are out of reach for many, on stage and off. How can an essentially elite art form have meaningful resonance and impact? Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9812,2025,3005,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-70','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> The Los Angeles River is a 51-mile long waterway that has defined and contributed to the development of Los Angeles as a major global city. It has functioned as a water source for LA’s earliest peoples, a major piece of urban infrastructure designed to control flooding, a recreation area, a site for Hollywood car chases, a home for the houseless, a sacred place, and more. This course examines narratives and worldviews of the Los Angeles River as a case study of land and place and how power, policy, and planning reflect and inform these worldviews. The course will explore community-based research approaches and methods that facilitate emergent worldviews and strategies for just and sustainable urban development. The course will include guest speakers and require field trips outside of regular class times. Open only to first year frosh.</div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9813,2025,3198,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-71','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span>First year seminar. Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9814,2025,3199,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-72','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span><span>This course studies China''s cultural, political and social development in a global setting from the early 19th century to the present. It delves briefly into China''s historical background prior to its opening to the Western world forced by Britain in the first Opium War (1839-42) before exploring the profound changes brought by globalization. Western influences in China, from Christianity to Marxism, will be examined with a focus on key events such as the Taiping Uprising (1850-64), Boxer Rebellion (1899-1901), Republican (Xinhai) Revolution (1911), May 4th Movement (1919), Communist Revolution (1921-49), the Great Proletarian Cultural Revolution (1966-76), and China''s recent rise as a global power. Students will gain a unique perspective from which to understand the consequences and impacts of globalization on our rapidly changing world. </span>Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9815,2025,3200,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-73','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> What is Traditional Environmental Knowledge and how is it transmitted? How is it similar or different from Western science? What can it teach us about resource management and environmental regeneration and sustainability? In this course we will examine key theories, concepts, and case studies from the fields of Traditional Environmental Knowledge and Decolonial Studies, focusing on such technologies as controlled burning; fish, shellfish and seaweed cultivation and enhancement; medicinal plants; and agricultural methods utilized by Indigenous communities in the Americas. In addition, we will explore how TEK informs Indigenous sovereignty, environmental justice, and cultural movements, as well as debates surrounding its relevance for contemporary, sustainable resource management. There will be two required weekday field trips between 3:00 pm and 6:00 pm as well as a weekend camping trip in April. If you are unable to attend these field trips you should register for a different FYS.Open only to first year frosh.</div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9816,2025,3201,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-74','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div>This course will focus on case studies in applied ethics. Our case studies for 2025 include: Should schools ban cell phones? Should Elon Musk’s medical device company, Neuralink, use animals in testing its products? Should cops be allowed to use fragments of our DNA to solve crimes, even when they don’t have a warrant? Students will debate these cases in class, and each student will develop a research project based on the case. Our approach will be interdisciplinary, meaning students will explore both empirical and theoretical issues. Open only to first year frosh.</div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9817,2025,3006,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-75','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div>Environmental justice is a normative concept that emerged through grassroots struggles against environmental racism, specifically, and environmental inequality, more broadly. However, when incorporated into the state apparatus, the radical foundations of environmental justice are overlooked in favor of palatable policy proclamations and a narrow understanding of what environmental justice entails. In this course, we will learn about the history of environmental justice as a response to environmental inequality, in addition to studying what scholar-activists call critical environmental justice. Importantly, this critical approach to environmental justice study and action leads us to topics not traditionally covered in EJ scholarship. As such, we will focus on homelessness/unhousedness as an environmental justice issue. Note: this course might require a few field visits. Open only to first year frosh.</div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9818,2025,3202,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-76','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span><span><span>We will examine the gradual process by which the application of the legal and political definition of death has expanded beyond its medical meaning. What does it mean to categorize a population or group as "already dead" even when the individuals of which it is composed exhibit the characteristics of living human beings? What qualifies them as already dead: an epidemic that has reached a certain demographic threshold, a famine or drought that has placed a certain percentage of the population beyond any possibility of recovery, even cultural characteristics that mark a group as no longer human? Further, what are the political, ethical and legal consequences of such declarations for the populations in question? What actions can or must be taken with regard to them? We will trace these questions as they are posed in works by Bram Stoker, Franz Kafka, Joseph Conrad, Thomas Hobbes, John Locke, Giorgio Agamben and in the films </span><em>Night of the Living Dead</em><span> (1968) and </span><em>28 Days Later</em><span> (2002).</span> </span>Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9819,2025,3203,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-77','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span><span>This course examines intersectional representations in all forms of media. Over the course of the semester, we will grapple with critical race theory, feminist theory, queer theory, disability theory, ageism research, and fat studies. </span>Open only to first year frosh.</span></div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9820,2025,3209,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-78','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span>This First Year Seminar examines the causes of the rise of authoritarianism and dictatorship in interwar Europe and its characteristics in the two nations which experienced extended fascist rule, as well focusing on their legacy in modern politics. We assess how the elevation of the state and the nation promoted by these regimes impacted the societies involved. We study the political, social, economic, and cultural aspects of Fascism and Nazism and the ramifications -- war and genocide -- of the embrace of fascist dictatorship. We also study the less-emphasized Fascist and nationalist regimes in Hungary, Poland, Romania, Greece, Spain, and Portugal. We will also analyze the contemporary far right in Europe and the United States and ask what these movements and parties have borrowed from their predecessors in the 1920s to 1940s. Class meetings focus on intensive discussion of assigned readings of secondary sources and primary sources, including texts, images, and films. Lectures will supplement the readings and discussions, but class discussion and student presentations are central to the class. Open to first year frosh only.</span></div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9821,2025,3904,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-79','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div>From 1942 to 1946, the US government incarcerated approximately 120,000 people of Japanese descent—the majority of whom were American citizens—in ten concentration camps across the American West. Although government officials framed this forced removal as a “military necessity” during WWII, activists and scholars have challenged this narrative by linking Japanese American incarceration to xenophobic policies aimed at curtailing the economic and social mobility of immigrant populations. This course will introduce students to Japanese American incarceration and its aftermath through archival materials, literary and cultural production, as well as major historical scholarship. We will not only explore the experiences of Japanese Americans during WWII but also consider how Japanese American incarceration has reverberated across Southern California, informing ongoing struggles for community control and self-determination in ethnic enclaves like Little Tokyo. The following questions will shape the trajectory of the course: how does Japanese American incarceration bring into focus the unequal and differentiated citizenship of racial and ethnic minorities? What lessons can we learn from Japanese American incarceration to negotiate ongoing and emergent acts of social and environmental injustice? Please note that course requirements will include 1-2 field trips and at least 1 visit to Oxy’s Special Collections. <span>Open to first year frosh only.</span></div> </div> </div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9822,2025,2964,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-8','<div class="desc"> <span>This course uses a feminist lens to analyze transnational documentary and feature films. We will examine the politics of gender in films produced in the West and the Global South and we will assess the flows between "first world" and "third world" cinematic traditions. Students will gain the necessary skills to analyze representations of gender, race, class, nationality, and sexuality in transnational film. The course considers how film can be a powerful tool that operates in the perpetuation of "third" and "first world" hierarchies and the economic, racial, and gendered inequalities that stem from histories of colonization. We will also consider how film can offer a critique of these dominant ideologies and inequalities that reflects postcolonial relations between "first" and "third" worlds. We will turn to feminist film theory, documentary film theory, cultural studies and postcolonial feminist theory in order to facilitate our analysis and class discussions of these films. Open only to first year frosh. </span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9823,2025,3905,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-80','<div class="desc"> <span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> <div><span></span> <div> In this course, students will learn how ideologies are coded, perpetuated and contested in everyday language. We will raise awareness about how seemingly neutral linguistic choices construct ideological meanings focusing on the discourse of sexual violence. Have you ever wondered how using the passive or active voice can allocate or obscure responsibility? In this class, students will learn how to expose and analyze those covert messages. The class will introduce the basics of multidisciplinary Critical Discourse Analysis methodologies with a hands-on approach. Using a wide range of media (written press, network news, social media, literature, graphic novels, and more) students will develop a critical toolbox to uncover the ideologies behind common-sense stances and practices around sexual violence and gendered power dynamics more generally. Open to first year frosh only.</div> </div> </div> </div> </div> </div> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9824,2025,2965,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/fys-first-year-seminar/fys-9','<div class="desc"> <span>Los Angeles is one of the most linguistically diverse cities in the world. At the same time, it is also known as a linguistic graveyard, absorbing immigrants by the millions and extinguishing their home languages within a few generations. The loss of home languages is due in part to ideologies associating the English language with whiteness, power, and "American" identity. It is within this context, acknowledging the socio-political and institutional barriers to speaking a non-English language in the United States, that students in this course will explore how maintaining a home (or heritage) language, and indeed, speaking any non-English language in the United States is an act of political resistance. This course will focus on the speakers of non-English languages who are attempting to resist the barriers described above and maintain their languages at the individual, community, and institutional levels. We will focus on the linguistic resilience and cultural practices of speakers of Spanish, Mandarin, and indigenous American languages in Los Angeles and throughout the country, via scholarly readings, documentaries, and case studies, as well as through field trips and guest lectures with members of these communities. This course will ask students to pose questions about the connection between one''s identity and the language one speaks. We will examine our experiences with our own language(s), confront our own beliefs, and aim to understand the beliefs and experiences of others. Please note that there will be 1-3 field trips in this course, usually on Saturday mornings. Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9825,2025,171,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/100/geo-105','<div class="desc"> <p>Introduction to Geology with emphasis on the physical processes that shape the environment on the Earth''s surface. The course will cover the fundamentals of plate tectonics, rocks, minerals, geologic time, surface processes, and Earth''s interior. Special attention will be paid to geologic hazards (such as earthquakes, volcanoes, floods, and landslides), the history and future of global climate change, and the human impact on the environment. <em>Includes one two-hour laboratory per week and a one- or two-day field trip.</em> Students who have completed a substantive introductory Geology course are encouraged to seek permission of the instructor to enroll in any of the 200-level Geology courses.Open only to first- and second-year students.</p> </div>',NULL,'GEO 105L ',NULL);
INSERT INTO course_descriptions VALUES(9826,2025,1457,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/100/geo-106','<div class="desc"> <p>Nature and humanity interact with and impact one another in complex and significant ways. Human health, safety, and economic well-being are significantly impacted by natural processes, providing both opportunities and constraints on sustainability. This course focuses on these interactions as studied by earth scientists. Topics include: Earth surface properties and processes, air quality, mineral and energy resources/reserves for industrialized society, water resources, hazardous earth processes, and development and degradation of soils and climate. Labs will include using problem-solving skills and case studies. <em>Includes one two-hour laboratory per week and a one-day field trip.</em></p> </div>',NULL,'GEO 106L ',NULL);
INSERT INTO course_descriptions VALUES(9827,2025,3007,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/100/geo-160','<div class="desc"> <p>An introduction to techniques of spatial analysis using GIS. You will study the fundamentals of geography and data science that guide you to valid approaches to practical problem-solving and investigate timely environmental questions that matter using real-world data: vector and raster geospatial datasets, aerial photos, satellite imagery, LiDAR. The course also includes a project combining GIS data acquisition and analysis to solve a practical question on the Oxy campus. This course will help you learn a valuable job skill that can apply to many different careers and interests. You should feel comfortable using the MS Windows operating system and Microsoft Excel software. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9830,2025,3360,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-210','<div class="desc"> <p><strong>This course will explore the physical principles, processes, and dynamics of the water cycle, including how and where water is transformed and transported around the planet. Topics will include the distribution of water on Earth, the main components of the hydrologic cycle (e.g. the storage and exchange of water phases between ocean, land, and atmosphere), and extreme weather and climate phenomena such as atmospheric rivers, floods, monsoons, hurricanes, and drought. The profound impacts of climate change and a growing human population on the hydrologic cycle and water resources on global and regional scales, especially in California, will be emphasized.</strong></p> </div>','GEO 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9831,2025,591,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-215','<div class="desc"> <p>The history of the Earth and life upon it, from the origin of the planet 4.6 billion years ago to the present. The course focuses on the chemical, physical, and biological processes that have affected the planet''s interior and surface, including atmosphere, hydrosphere, and lithosphere, through time. <em>Includes one three-hour laboratory per week and field trips.</em></p> </div>','GEO 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9832,2025,2883,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-220','<div class="desc"> <p>The fundamentals of rock formation are explored through study of common rock-forming minerals and major rock types. Understanding of these processes is based on the physical, optical, chemical, and textural properties of minerals and rocks. The course includes a field trip to investigate rocks and minerals in some of California''s most interesting natural settings. <em>One three-hour laboratory per week and field trip.</em></p> </div>','GEO 105 or GEO 106 ','GEO 220L ',NULL);
INSERT INTO course_descriptions VALUES(9833,2025,173,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-225','<div class="desc"> <p>Southern California’s spectacular geology is the natural laboratory for this project-based course. Working collaboratively, students will investigate geologic questions through fieldwork in the nearby deserts and mountains. The course will expand upon geologic knowledge from introductory geology classes and introduce students to the scientific processes and techniques geologists employ to understand the Earth and other planets. Special emphasis will be placed upon systematic field data collection using mobile GIS-based systems and communication of scientific results. The course will provide students from any major the opportunity to explore our local natural setting and actively participate in scientific inquiry. No experience beyond GEO 105 is expected of participants and all equipment will be provided. </p> </div>','GEO 105 ','GEO 225L ',NULL);
INSERT INTO course_descriptions VALUES(9834,2025,3879,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-230','<div class="desc"> <p>This course will examine the physical and chemical process associated with geologic hazards such as volcanism, earthquakes, and floods that have profoundly impacted civilizations globally and throughout human history. Southern California offers many excellent examples of geologic hazards that will inform our study. The course will include in-field examinations of local examples as well as evaluation of datasets associated with well-documented case studies of geologic hazards locally, in the western US, and around the world. Prerequisite: Geology 105</p> </div>','Geology 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9835,2025,593,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-235','<div class="desc"> <p>An introduction to plate tectonics and the geology of plate boundaries. Topics include: techniques for describing plate motions, earthquakes and seismology reversals of the earth''s magnetic field, the nature of the seafloor, and the geology of mountain belts. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 ','GEO 235L ',NULL);
INSERT INTO course_descriptions VALUES(9836,2025,844,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-245','<div class="desc"> <p>An introduction to Earth''s climate system and the geological record of its change. Topics covered include: Earth''s radiative balance and the role of greenhouse gases, poleward transport of heat by the atmosphere and ocean, climate change on the plate tectonic timescale, the Cenozoic cooling, astronomical control of Pleistocene glacial cycles, rapid millennial-scale climate change, and the future of Earth''s climate. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 ','GEO 245L ',NULL);
INSERT INTO course_descriptions VALUES(9837,2025,595,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/200/geo-255','<div class="desc"> <p>This project-based course will delve into scientific questions in earth, environmental, and ecological sciences using digital data on a variety of scales, from our backyard to the globe. By investigating problems such as the timing of earthquakes on the San Andreas fault, sources of contaminants in steam water, geologic controls on plant growth, and potential effects of volcanic eruptions, students will deepen their knowledge of geologic processes and develop analytical abilities that are a foundation of scientific inquiry. Course material will focus on topics to be investigated in laboratory projects using digital tools such as geographic information systems, Excel, and Google Earth. </p> </div>','GEO 105 or GEO 106 ','GEO 255L ',NULL);
INSERT INTO course_descriptions VALUES(9842,2025,1334,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/copy-of-geo-315','<div class="desc"> <p>Study of the processes of sedimentation, the properties of sedimentary rocks, and the use of stratified sedimentary sequences for correlation, dating, and interpretation of depositional environments and geologic history. Course includes field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>','GEO 105, GEO 225 and one additional 200-level Geology course ','GEO 315L ',NULL);
INSERT INTO course_descriptions VALUES(9843,2025,1335,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-315l','<div class="desc"> <p>Field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'GEO 315',NULL);
INSERT INTO course_descriptions VALUES(9844,2025,1336,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/copy-of-geo-324','<div class="desc"> <p>Building on material learned in GEO 220 and GEO 225, this course involves the mapping of more complex areas. Fieldwork is the heart of this course and full participation in the 4-6 days of fieldwork is required. May be taken twice for credit.</p> </div>','GEO 225 and one additional 200-level Geology course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9845,2025,597,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-325','<div class="desc"> <p>Study of the deformation of rocks and the structures produced. Rock mechanics are introduced and the nature and origin of folds, faults, and other structures are discussed, along with the relation of structures to tectonic settings. Course includes interpretation of areas displaying complex geological relations that illustrate structural principles. <em>Includes field trips and one three-hour laboratory per week.</em></p> </div>','GEO 225 and one additional 200-level Geology course ','GEO 325L ',NULL);
INSERT INTO course_descriptions VALUES(9846,2025,598,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-325l','<div class="desc"> <em>Three-hour per week laboratory.</em> </div>',NULL,'GEO 325',NULL);
INSERT INTO course_descriptions VALUES(9847,2025,938,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-342','<div class="desc"> <p>Landforms and their interpretation in terms of tectonic and climatic processes will be presented. The focus will be on landforms such as: mountain belts, faults, and landslides caused by active tectonic processes. Methods of dating and quantifying geologic events will be introduced. Scientific writing skills will be emphasized. <em>Includes one three-hour laboratory per week and field trip.</em></p> </div>','GEO 225 and one additional 200-level Geology course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9848,2025,1170,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-342l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 342',NULL);
INSERT INTO course_descriptions VALUES(9849,2025,939,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-345','<div class="desc"> <p>This course is a systematic exploration of the important minerals and rocks that comprise the solid earth. Course work will focus on the materials and processes involved in the formation of igneous and metamorphic rocks globally and seen in spectacular local examples. Students will engage in the study of rocks and minerals through analysis of specimens, microscopy, experimental and geochemical datasets, and fieldwork.</p> </div>','GEO 225 and one additional 200-level Geology course ','GEO 345L - Mineralogy and Petrology ',NULL);
INSERT INTO course_descriptions VALUES(9850,2025,940,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-345l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>','Co-enrollment in GEO 345 ','GEO 345 ',NULL);
INSERT INTO course_descriptions VALUES(9851,2025,3840,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-380','<div class="desc"> <p>Integrative topics in geology is a rotating suite of courses in which geologic concepts are examined primarily through application of geochemistry, data structures, or geophysics. The course may count toward the major as a supplemental course OR an upper division elective. If taken more than once, the second course will count as an upper-division elective in Geology.</p> <p><strong>Environmental Geochemistry</strong></p> <p>Low-temperature geochemical techniques are used to understand the global and local circulation of water from the atmosphere through rocks and into groundwater. In this course we will learn how stable isotope and trace elements help define the transport of water, metals, and carbon under changing climate and land-use conditions. Labs will give students an opportunity to apply geochemical tools to a variety of real world settings, using data from the Rocky Mountain headwater catchments to the karst aquifers in central Texas. A final collaborative class project will provide students the unique opportunity to sample, prepare, analyze, and interpret their own stable isotope data using a Picarro instrument in Dr. Sekhonâs laboratory</p> </div>','GEO105, GEO 245 and one additional 200-level Geology course ','Must also enroll in GEO 380L ',NULL);
INSERT INTO course_descriptions VALUES(9852,2025,599,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-390','<div class="desc"> <p>Two- or four-credit advanced courses on specialized topics in Geology. May be taken more than once with department approval as topics vary. </p> <p><strong>Biogeochemistry of Marine Systems, Past and Present</strong></p> <p>This course explores the interactions between the physical, biological, geological, and chemical processes that characterize marine ecosystems and ultimately shape the functioning of our planet. Using a combination of modern analogues and examples from the geologic past, we will study a range of topics from nutrient distribution, ocean acidification, redox reactions to climate change and global biogeochemical cycling. This interdisciplinary course will introduce concepts from chemical oceanography, marine geology and biogeochemistry, borrowing fundamental concepts of each to examine ancient and modern biotic events. Through this course, students will develop a greater understanding of Earth systems and how they have changed through time. Introductory geology, chemistry and/or biology is recommended.</p> <p><strong>Science of Soils</strong></p> <p>The physical, chemical, and biological processes within soil systems are assessed. Emphasis is on factors governing the physical properties, nutrient availability, and plant growth and production within soils. How to classify soils and to assess nutrient cycling and contaminant fate will be covered. Recommended: introductory geology, chemistry and/or biology.</p> <p><strong>Paleontology: The Record of Life, Landscapes, and Changing Climate</strong></p> <p>This course will use the fossil record as a tool to explore the geologic controls on the evolution and extinction of life on earth. From Snowball Earth to the Great American Biotic Interchange, plate tectonics and climate change drive the distribution of life through time. We will examine paleontological and modern ecosystems through classes, labs, and field trips. Students should have completed GEO105 and at least one 200-level course in biology or geology.</p> <p><strong>Geochemistry</strong></p> <p>This course will explore the geochemical principles controlling fundamental geologic systems, from the "weathering engine," to the igneous-metamorphic-hydrothermal systems that form and shape planets. This overview of Geochemistry will focus on thermodynamics and kinetics, which allow us to assess these systems with regards to temperature, pressure, and time. Quantitative evaluation of earth processes through geochemical modeling will be conducted using the programs SUPCRT, Visual Minteq, and Geochemist''s Workbench (industry standards). Laboratories, workshops, and fieldtrip(s) will reinforce and expand on many of the topics covered in class.</p> </div>','Two 200-level Geology courses ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9853,2025,1071,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-390l','<div class="desc"> <p>Weekly three-hour laboratory in conjunction with GEO 390 Special Topics in Geology.</p> </div>',NULL,'GEO 390',NULL);
INSERT INTO course_descriptions VALUES(9854,2025,2627,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-391','<div class="desc"> <p>This class serves as preparation for Senior Comprehensives in Geology. Topics include comps options, analysis and presentation of scientific data, literature searches and attribution of previous work. Students will develop a formal plan to complete their senior comprehensive requirement. Open only to junior Geology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9855,2025,1522,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-395','<div class="desc"> <p>Research under guidance of faculty member on jointly selected project. May be taken four times for credit. Permission of instructor required.</p> </div>','GEO 105 and GEO 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9856,2025,179,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/300/geo-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9857,2025,2551,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/400/geo-491','<div class="desc"> <p>This seminar focuses on analysis, discussion, and presentation of current issues in geological research. These topics will be explored through the geologic literature and the class will include a formal presentation to the Geology Department. Students will also learn about graduate school and career options in the Earth Sciences. Open only to senior Geology majors.</p> </div>','GEO 391 or GEO 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9859,2025,600,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/geo-geology/400/geo-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9860,2025,181,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/100/germ-101','<div class="desc"> <p>Introduces basic language skills, grammar, pronunciation, oral communication, and reading simple prose. Culture taught through readings, videos, and discussions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9861,2025,602,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/100/germ-102','<div class="desc"> <p>Continuation of GERM 101.</p> </div>','GERM 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9862,2025,182,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/100/germ-151','<div class="desc"> <p>Oral practice based on articles in current periodicals and other subjects of general interest. Taught by a German language assistant from the University of the Saarland, under the supervision of a German instructor. Designed primarily for students who have completed GERM 102. Graded on Credit/No Credit basis; attendance is mandatory. Approximately two hours of work outside of class time required each week. May be repeated for credit.</p> </div>','GERM 102 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9865,2025,183,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/200/germ-201','<div class="desc"> <p>An advanced course to build up comprehension, as well as oral and writing skills. Reading and discussion of literary and cultural texts supplemented with video films and T.V. news on current events in Germany. Practice in essay writing.</p> </div>','GERM 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9866,2025,604,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/200/germ-202','<div class="desc"> <p>Continuation of GERM 201 at an advanced level. Review of advanced German grammar, and exercises in stylistics and essay writing.</p> </div>','GERM 201 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9867,2025,941,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/200/germ-232','<div class="desc"> <p>This course covers major trends and developments in the cultural history of postwar Germany. Topics include: the reconstruction of culture after 1945, the makeup of cultural institutions, the mass media, popular culture vs. traditional culture, the counter culture of the 60''s and early 70''s, and the problems of unification after 1989. Taught in German, with emphasis on oral presentations and essay writing. Readings include: literary texts, documentary material, newspaper, and magazine articles.</p> </div>','GERM 201 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9868,2025,184,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/200/germ-251','<div class="desc"> <p>Open to all qualified students, but designed primarily for students preparing for Occidental-in-Germany program. May be repeated for credit.</p> </div>','GERM 152; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9869,2025,1337,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/200/germ-280','<div class="desc"> <p>The onset of industrialization in the 19th century created the modern metropolis and the angst and attraction of the lifestyle that went with it. In this course, we will examine how writers and intellectuals of the late-19th and early-20th century described their experience of this new urban environment - analyzing their discoveries and discontents. In addition to fiction by Rainer M. Rilke, Emile Zola, Irmgard Keun, Alfred Döblin, Walter Benjamin, and others, we will also discuss seminal texts by architects, urban planners, and theorists, and look at how visual artists and filmmakers depicted the emerging streetscape of modernity. Students will have the opportunity to explore the impact of modern urbanization in a contemporary and global context through field trips and class projects. The course is taught in English. This course is not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9874,2025,2339,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/copy-of-germ-311','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different “scenes of writing,” from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature’s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience, and knowledge are produced, articulated, and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler. Taught in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9875,2025,2944,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-301','<div class="desc"> <p>This course is designed for advanced level German students and will develop their linguistic skills with an aim towards increased fluency in speaking, reading, writing, and listening comprehension. The course will accomplish these goals by reading and discussing texts in German literature or philosophy. The texts and topics can change from year to year and may range from a novel, to a series of short stories, to a topic-based analysis of literary and philosophical texts. Student input on topics and texts is welcome. Discussion and readings will be in German. </p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9876,2025,2654,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-307','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison. This course will meet three times a week. Twice with CSLC 107 with discussion conducted in English, and a third weekly meeting in which all readings and discussions will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9877,2025,2552,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-308','<div class="desc"> <p>This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling. </p> <p>This course will meet three times a week, twice with CSLC 108 with lectures and discussion in English, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9878,2025,1523,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-309','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables and riddles to anecdotes, jokes, short stories and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin and Twitter. This course will meet three times a week, twice with CSLC 109, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9879,2025,1658,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-310','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-1778) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with such major figures as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as its unprecedented boom in popularity around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. In concluding with the rise of Nazism and their attacks on modern art as "degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. This course will meet three times a week, twice with CSLC 210, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9880,2025,2705,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-312','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes From the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor. In addition to the English section, this course will meet for an additional session per week to read the and discuss the German language and other supplementary texts in their original. Readings will occur in German and will serve as an introduction to the major developments of the German language from Middle High German to the advent of High German in the writings of Martin Luther to its modern iterations in Hermann Hesse. Authors will include among others, Meister Eckhart, Martin Luther, Franz Kafka, and Hermann Hesse while discussion will occur in English and German and focus on the intricacies of the original language text and developing arguments out of it. </p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9881,2025,3339,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-313','<div class="desc"> <p>Although the first volume of the Grimms’ Children Stories and Household Tales was published more than 200 years ago, their fairy tales continue to enchant contemporary readers. In this course we will not only study the Grimms’ fairy tales themselves and rediscover their enduring magic, but also take a look at their origins and their social, ideological, and political contexts in 19th-century Europe. We will work with fairy tale theory (narrative, psychoanalytic, historical) and discuss the function of the tales for adult communities as well as their status as children’s literature. Alongside the “original” Grimms’ tales—a concept that we will discuss—a major portion of the course will engage the legacy of the fairy tales and the way they have been appropriated by others, particularly from a critical, feminist perspective. Points of emphasis will include: how writers in the first half of the 20th century politicized the tales in the battle for societal change during the time of the Weimar Republic and Nazi Germany; how the tales were reinterpreted in different national traditions and historical periods; how the fairy tale becomes a mass culture icon in Disney’s film versions; and how contemporary writers like Margaret Atwood continue to employ fairy tales to question the construction of gender and carve out new possibilities for relating to one another. </p> <p>This course will meet twice a week with CSLC 113, and for one additional 85 minute session per week to develop German students’ language skills. Students will have an opportunity to translate and discuss selections from texts in the original German.</p> <p>Students in this course are required to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second Stage writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9882,2025,2751,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-315','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> <p>This section will meet once a week extra to discuss these texts as read in the original German. Reading, but not speaking knowledge of German is required.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9883,2025,2865,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-316','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and fallibility. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in-depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> <p>In addition to the English section, this course will meet for an additional session per week to read the texts in their original German and discuss the nuance and difference in meaning as it is transmitted through the original language. Reading the text in the original German is particularly important in the case of Heidegger, whose philosophical program cannot be separated from his thinking about language and the intricate relationship between language and meaning. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second-Stage Writing Requirement. </p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9884,2025,2896,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-318','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness.?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process-oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. <em></em></p> <p>The course will consist of two parts. First, the Tuesday-Thursday lecture in English (shared with CSLC 118) and second, a German language section in which we read the texts in which we read the texts in the original and discuss the nuances of the text as it reads in the original language. Discussion will be in English. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second Stage Writing requirement.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9885,2025,1019,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-320','<div class="desc"> <br/> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into "new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the Humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. This course will meet three times a week, twice with CSLC 120, and a third weekly meeting in which all readings and discussion will be conducted in German. </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9887,2025,3602,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/copy-of-germ-393','<div class="desc"> <div><p dir="ltr"><span>Intensive study in an area of German literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9889,2025,606,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/germ-german/300/germ-397','<div class="desc"> <p>Individual study of a major author, movement, genre, or translation technique. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9891,2025,186,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/100/grk-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Ancient Greece. Students will engage, from the beginning, with original texts from Homer, Sophocles, Plato and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Greeks, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9892,2025,607,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/100/grk-102','<div class="desc"> <p>Continuation of GRK 101 and reading of adapted Greek texts.</p> </div>','GRK 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9895,2025,187,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/200/grk-201','<div class="desc"> <p>Homer''s epics feature some of the best known, and varied, heroes of antiquity, like Achilles, Hector, Odysseus, and Penelope. In this class, we will read selections from the <em>Odyssey </em>and <em>Iliad </em>as a way to examine ancient conceptions of heroism. For students studying ancient Greek, this will primarily be a translation course and will serve as an introduction to epic poetry. Students without Greek are also welcome and can expect to approach the topics of the class by reading translated texts and modern scholarship.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9899,2025,3327,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-303','<div class="desc"> <p>It is impossible, the philosopher Martin Heidegger once declared, for any human being ever to be truly alone; to exist as a human at all, he argued, is always already to be acting and thinking and feeling in relation to other humans, to be interpreting our own being in relation to those who likewise, and reciprocally, must interpret their being in relation to ours. In this class, we shall examine the ways in which various philosophers and theorists have conceived this mutually entangled condition of togetherness, this existential condition of Being-With. We shall inquire, for example, into the ways this condition of shared being has been interpreted politically (in terms of entities such as city-state and nation-state), sociologically (through notions such as community and society), economically (through concepts such as markets and labor), and anthropologically (through the concepts of kinship group, family, and tribe). What shall distinguish this class from those to be found in any number of social science departments, however, is the close attention we shall be paying to the crucial role of culture, the role of literature in particular, in the making (and unmaking, and remaking) of all these ways of relating ourselves to one another. To put it somewhat more pithily (and alliteratively): how exactly do poetics relate to politics, and politics to poetics, in the shaping of our shared human existence? This course shall survey some of the most important ways of answering this question in the modern era, and then apply these modern theories to the translation and interpretation of select Ancient Greek texts that also attempt to deal with the question of community: the works of Greek tragedians and comedians, the historians Herodotus and Thucydides, and philosophers such as Heraclitus, Democritus, Aristotle and Plato. </p> <p>This course will be taught in conjunction with CSLC 203, with an extra weekly session devoted to the study of Ancient Greek texts. Beyond the examination of ancient texts in the original, therefore, students will also be expected to study a wide array of social and cultural theorists from the 17th century to today, including (but not limited to) figures such as Hobbes and Vico, Rousseau, and Smith; Hegel and Marx, Malthus and Mill; Durkheim and Weber, de Beauvoir and Adorno; Fanon and Bourdieu, Turner and Geertz: Habermas and Rorty, Nussbaum and Butler; Nancy and Agamben, Appiah and al-Gharbi. </p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','CSLC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9900,2025,2515,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-381','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage. This course meets with CSLC 181 and is for students who will be reading texts in the original Greek.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9901,2025,1524,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-382','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9902,2025,1701,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-383','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all-important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all. The Greek section of this course will be devoted to translation of <em>The Iliad</em> from the original, paying particular attention to the ways in which the Homeric epic has been received in the almost three millennia since its original appearanceÍ¾ this will give our investigation into the history of style in the West (and its possible metaphysical grounds) a carefully delimited focal point.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9903,2025,2853,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-385','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. In addition to attending the 3 hours of lecture required of students in CSLC 285, students in Greek 385 are required to attend an additional 90 minutes of class per week to read and discuss texts in the original language. Students in this course are required to complete a 10-12-page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9904,2025,1659,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-386','<div class="desc"> <p>In this course, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth''s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-Â­sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home," at all. This course will be offered in conjunction with CSLC 286, but will meet for an additional 90 minutes per week to read Homer''s <em>Odyssey </em>in the original Greek.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9905,2025,3294,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-387','<div class="desc"> <p>“The origins of the myth of Prometheus,” it has been said, “are unclear; even in antiquity the story is never told in full.” Right from the beginning, it would seem, Prometheus arrives on the scene of literature in a torn, dismembered condition, his story diffracted from the outset into a multiplicity of incoherent elements and perspectives: is he a mighty Titan, or merely a trickster? a divine benefactor, or a threat to cosmic peace? an embodiment of the power of thought, or a figure of its eternal helplessness and misery? The primary object of this course, which will be taught in conjunction with CSLC 187, will be to survey some of the more impressive and surprising ways in which literature, art, and philosophy have engaged with, and contributed to, the strangeness of this myth of Prometheus--a figure who, as we shall discover, is as much a source of agony to the Absolute, as he is agonized by it. </p> <p>While reading the later receptions of the Prometheus myth along with their counterparts in CSLC 187 (in the works of Goethe, Shelley, Melville, Marx, Nietzsche, Heidegger, and others), this five-unit, Ancient Greek section of the class will additionally read the ancient texts covered in class (Prometheus Bound, as well as selected excerpts from Hesiod and Plato) in their original Greek form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9907,2025,2945,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-389','<div class="desc"> <p>In the 6th century BCE, certain Greek thinkers (who have since come to be known as "philosophers") put in motion a conceptual distinction decisive for the cultural and intellectual history of the West: the division of the soul (<em>psyche</em>) from the body (<em>soma</em>), and more generally, from the "flesh" (<em>sarx</em>). By the 4th century BCE, Plato seems to have concluded that philosophy must eschew any interest in the flesh, inasmuch as flesh (whatever it may be) cannot yield to precise, philosophical investigation. Perhaps even more crucially, Plato stipulated that flesh cannot and should not be the basis of a politics, as it is only philosophical insight, in its disciplined refusal of the lure of the flesh, that could serve as the ground of genuine political communion. From here it was but a short step to conclude that poetry (and of course, "art in general"), entangled as it was with the body, could have little meaning or import for the practice of either politics or philosophy.</p> <p>Influential as these weighty pronouncements surely have been on the history and development of Western thought, resistance to them, it should be noted, was almost immediate--beginning perhaps with the work of Plato himself! In this course, we shall examine the ways in which literature and art, as a "poetics of the flesh," offers us a practice as rigorous, and productive, as any purported philosophy of abstract, spiritual forms. We shall then consider what such a poetics of the flesh might be able to offer philosophy itself as an intellectual discipline. Finally, we shall engage with recent theories concerning the way in which authentic political community might rest not on the eschewal of the flesh, but its deliberate and thoughtful "incorporation" (pun intended).</p> <p>The first half of the class will focus on older material (certain Ancient Greek and Roman poets, Plato, Aristotle, the New Testament, as well as some medieval writers and thinkers); the second half of the class, however, will turn to the work of more recent poets and theorists of the flesh, with a particular emphasis on the investigations of Jean-Luc Nancy into the significance of the arts, and what he calls the "sense of sense." </p> <p>This course will share lecture time with CSLC 288, but will meet for an additional 90 minutes per week to translate and read selections from Plato''s Republic and Ion, Aristotle''s Poetics, Physics, and Rhetoric, and the New Testament, in the original Greek. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9908,2025,3611,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-390','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the magnificent yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> <p>This course will be offered in conjunction with CSLC 190, but will meet for an additional 90 minutes per week to read the Homeric texts covered in class in their original Greek form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9910,2025,3109,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.<br/> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9911,2025,608,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/grk-greek/300/grk-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9914,2025,188,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-101','<div class="desc"> <p>This course is an introduction to early North American/U.S. history, reaching from colonization to the Civil War. Of particular interest in this course will be the theme of cross-cultural interactions in the midst of transforming economies, an expanding nation, and unequal power relations. We will combine a broad introduction to early American history with an in-depth look at five case studies of individuals and communities encountering each other across borders of nation, religion, race, gender, ethnicity, and class. Each case study offers a unique perspective on the question of how broad economic structures of colonization, slavery, and the market revolution shaped human encounters between natives and newcomers, captives and captors, slaves and slaveholders, Northerners and Southerners. Ultimately, these case studies encourage a critical rethinking of concepts of liberty, equality, and democracy, which have formed the bedrock of master narratives in United States history. Within the context of these broad, sweeping themes, we will look closely at primary historical documents, produced by men and women of their time period, and we will carefully read the arguments of historians in our own time. The class will emphasize history as a process of critical interpretation.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9915,2025,609,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-102','<div class="desc"> <p>This course provides an introduction to United States history from the Civil War to the early 21st century. Readings and lectures are structured around the core theme of American pluralism. They emphasize the changing demographics of the American population and consider the different strategies that Americans have used to negotiate this growing diversity over time. Topics covered include: Reconstruction, westward expansion and overseas imperialism, Industrialization and the Gilded Age, the Progressive Era, World War I, the Great Depression and New Deal, World War II and the rise of internationalism, the Cold War and third world decolonization, immigration reform and comparative civil rights movements, the Vietnam War and the rise of global dissent, conservatism and the "Reagan Revolution," America''s border wars, and the post-9/11 War on Terror. We will give particular attention to issues of race, ethnicity, gender, religion, sexuality, region, and class in the shaping of modern America. Other important themes include: the expansion of federal power and the government''s role in people''s lives, contests over national citizenship and identity, America''s changing role in the world and engagement with foreign peoples, and the demographic transformations wrought by international migration and conflicts.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9916,2025,3841,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-103','<div class="desc"> <p>This course takes place under the shadow of an unprecedented threat to our democracy. That threat starts with an attempted coup sanctioned by one of the country''s major political parties--undermining the peaceful transfer of power that has been the hallmark of American democracy for over two centuries. But the threat does not end there. The country is experiencing growing disparities between rich and poor, a radical loss of faith in its institutions, as well as the erosion of civil society with its democracy-sustaining ethics of reciprocity, humility and compromise.</p> <p><br/> This course seeks to address this ominous state of affairs (however modestly) by recovering the history of democratic debate and practice. We will explore the history of ideas that have contributed to the thickening of democratic practice in thinkers such as Aristotle, Montaigne, Locke, Rousseau, Wollstonecraft, Tocqueville, Mill, and C.L.R. James. We will supplement their contributions with four âcase studies'''' of democratic experiments. After examining the raucous, participatory democracy of Ancient Greece (with its limited suffrage and election by lottery), we will turn to the Levellers/Diggers in 17th century England, the Haitian interpretation of the French Revolution in the 18th century, and the efforts of Utopian communities to reimagine democracy in 19th Century America. Our goal throughout this course is to develop a clear-eyed understanding of the history of democratic ideas and practices in the hope of recovering the resources your generation will need in the struggles to come.</p> </div>','None ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9917,2025,3313,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-105','<div class="desc"> <p>From the Vietnam Memorial in Washington to the removal of Confederate statues throughout the American South, public history has become a flashpoint for controversy. That is largely because how we remember the past can have a large impact on the way in which we shape the future. We will begin by looking at the benefits and problems associated with traditional strategies of historic preservation; and then proceed to examine the ways in which public monuments, museums, and related exhibition strategies have sought to redress significant deficiencies in our historical self-understanding. The course will conclude with two case studies where debates over the past have led to significant controversies and public misunderstandings: The Smithsonian exhibition featuring the Enola Gay (the plane which carried the nuclear weapon that some say "ended the war" with Japan); and the 1619 Project, which has become controversial for its attempts to re-conceptualize the role of race in American history and serve as a spur for rethinking the curricula of our nation''s schools.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9919,2025,942,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-121','<div class="desc"> <p>A survey of multiple Western civilizations and their interrelationships. Among ancients, we shall study Mesopotamians, Egyptians, Hebrews, Persians, Greeks, and Romans. In medieval times, we shall examine Catholic Europe, Greek Orthodox Byzantium, Islamic Civilization, and their interrelationships. We shall consider the treatment of women and of minorities, and shall highlight travelers between civilizations. We shall conclude with the European Renaissance and Reformation, Turkish hegemony in the Eastern Mediterranean, and the shift in trade from the Mediterranean to the Atlantic Ocean, as modern science and enlightenment challenge traditional civilizations.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9920,2025,610,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-122','<div class="desc"> <p>The course focuses on the rise, fall, and re-emergence of Europe as a global political, economic, and cultural force in the contemporary world. We begin with the Enlightenment in the 18th century and the dissemination of European power in the 19th century through capitalism, the industrial revolution, nationalism, and imperialism. We then turn to Europe’s crisis in the 20th century with attention to World War I, Fascism and Nazism, World War II and the Holocaust, and colonial wars of independence, to be followed by European rebirth in the form of reconstruction and European unity. The period 1990s to 2020s welcomed several former states of the USSR into the European Union, and witnessed UNESCO’s restoration of historic sites. Specific topics include the French Revolution, transformations in capitalism, the rise of the nation-state, colonialism and decolonization, liberalism, socialism, communism, changes in family structure and gender relations, and the movements for women''s, workers’, gay and lesbian and other minority rights.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9921,2025,2592,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-125','<div class="desc"> <p>In this course focused on European cultures, students will consider the Renaissance and Reformation, Science and Baroque Splendor, Enlightenment Reason and Revolution, Romanticism and Individualism, Industrial Revolution and New Social Thought, Modernism in Literature and the Arts, Global Influences, Cultural Pluralism, and Postmodern Culture. Students experience and critically evaluate texts and images from both historical and contemporary points of view.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9922,2025,189,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-141','<div class="desc"> <p>A survey of Chinese, Japanese, and Korean societies from the emergence of states to the present. Several themes explored include: the development of strong, centralized states; the emergence of a shared elite culture; the spread of popular religions; the continuing interaction between East Asian and other societies; contrasting roads taken by each society in order to meet the challenges of modernity; conflicts over imperialism, nationalism, and revolution; cultural debates over gender and generational issues. Finally, a review of the post-WWII era: opposing alignments in the Cold War; socialist state building and experimentations; military rule; democracy; mass culture; successive economic "miracles," and China''s re-emergence as a global power.</p> <p>Survey Requirement Met: <strong>Asia</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9923,2025,190,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9924,2025,611,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-151','<div class="desc"> <p>This course offers a survey of postcolonial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the 19th and 20th centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the 19th century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race; and the development of export agriculture. The second section introduces themes of the 20th century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources, including scholarly works, films, and primary sources to engage these topics and issues.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9925,2025,3303,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-169','<div class="desc"> <p>Imperial violence and capitalist economic restructuring historically drove Asians to migrate to the United States. Once here, people of Asian descent engaged in transformative political activism and constructed new cultural identities and alliances to meet the challenges of diasporic and immigrant life. This course will examine the cultural and political geographies of trans-Pacific migration and identities from the 19th century to the present. From Har Dayal, Sun Yatsen, and Qiu Jin in the early 20th century to the 1960s Third World Liberation Front, the I Wo Kuen Red Guards in San Francisco working with the Black Panthers, and beyond, political activists have been crisscrossing the Pacific, building and rebuilding networks of resistance to colonialism, marginalization, and exploitation. The course draws heavily on the rich history and cultural diversity of Los Angeles and Southern California, which has been a center of Asian and Asian American movements—migratory, political, and cultural—for over a century. Students will examine a variety of primary sources, including literature, political manifestos, and films, and engage deeply with the cultural and spatial geographies of these histories. Field trips to local religious sites and neighborhoods, paired with visits from local scholars, journalists, and filmmakers, will bring these histories to life and illustrate their legacies shaping the present. Along with regular writing assignments, students will collaborate on a final project mapping transpacific migration histories and social justice alliances in LA.</p> <p>This course is part of the Humanities for Just Communities Immersive semester.</p> </div>',NULL,'FYS 1 ',NULL);
INSERT INTO course_descriptions VALUES(9926,2025,848,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-182','<div class="desc"> <p>This is a survey course in which we will explore the cultural and social historical experience of the Middle East from the 19th century to the present. Our goal in this class is to develop a sense of how people in the region view themselves and their history. We consider the currents of social change wrought by political and economic transformation, focusing particularly on the rise of new social movements and cultural currents. Here we will focus on issues of gender, religion, new social categories, and notions of personhood, and new forms of collective and individual identity. Finally, we look at the emergence of modern nation-states and their attendant juridical notions of citizenship and minority status.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9927,2025,2689,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-190','<div class="desc"> <p>This course will take a historical look at the emergence and development of capitalism from the 16<sup>th</sup> century to the present. The course stresses capitalism’s global spread and interaction with other historical forces such as commercialization, urbanization, colonialism and imperialism, environmental and climate change, inequality, and social and economic instability. We will look at the emergence of various schools of thought on capitalism, such as Keynesianism, Marxism, liberalism, the Austrian School and its offshoots, and neoliberalism. We will end with a discussion on the future of capitalism, considering globalization, the rise of China, economic crisis, and the rise of nationalist and populist responses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9928,2025,2677,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-191','<div class="desc"> <p>This course traces the theory and practice of revolution in modern history. The course begins with a brief overview of revolutionary theories and transformations within a global historical context. We then turn to the Scientific Revolution and the Enlightenment as the paradigm shifts which brought a revolution in thought and subjectivity in Europe. From there we focus on the French Revolution, following its legacy and impact through the revolutions of the 19<sup>th</sup> century, the rise of Socialism and Communism, the Russian Revolution, the Chinese Revolution, decolonization and revolutions in Africa, and the Cuban Revolution. The course looks closely at how these revolutions in thought and politics changed the way people understood their relationship to state and society. In the search for global connectivity, we review revolutionary movements beyond the western European and United States to include cultures and civilizations of Asia, the Middle East, Africa and the Americas. We will ask a number of questions related to revolutionary change, including: what causes revolutions? Who makes a revolution? What leads to success or failure in a revolutionary situation?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9929,2025,2885,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-192','<div class="desc"> <p>The course explores gender as a malleable category of historical analysis that intersects fluidly with other categories such as race, class, and sexuality. Course materials interweave global historical studies from the 16<sup>th</sup> to the 20<sup>th</sup> centuries with theoretical work on themes including the following: gender as performance, gendered divisions of labor, gender and science studies, the politics of gender, as well as gender, space, and material culture. By continually historicizing the construction of masculinities, femininities, and gender-fluid identities, this course examines how societies over time have expressed, policed, invented, and reproduced gender as a category of human experience and a shaper of social relations of power. The geographic range of the course is oriented primarily toward the Atlantic World: North America, South America, the Caribbean, West and West Central Africa, and Europe. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9930,2025,3489,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-193','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> <p><strong>Directed Research: Marxism</strong></p> <p>This Directed Research course introduces Marxism as a form of social and historical research. Through reading, discussion, and short writing, students will learn: the basic categories of Marxism; the open questions in the field of Marxist research; and, how to use Marxist theory to develop and conduct social and historical research. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9931,2025,3340,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/100/hist-194','<div class="desc"> <p>The class explores a range of historical experiences of imperialism from the Americas to Central, South and East Asia to the Middle East and Africa. We introduce students to major concepts, theories, and intellectual inquiries in imperialism and postcoloniality. Students will examine the historical emergence of theories and practices of imperialism in order to interrogate notions of human rights, imperial and colonial capitalism and post-coloniality. The class engages with questions concerning knowledge production, representation, and subjectivities produced by the colonial encounter and its historical legacies such as racial capitalism and uneven development. We will necessarily consider the ways that imperialism produces difference as a technique of power.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9934,2025,943,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/copy-of-hist-243','<div class="desc"> <p>Chinese history from about 1600 to the present: the growth of the domestic economy, the rise of the Manchus and territorial expansion, encounter with the West, internal decline, rebellions, imperialism, nationalism, and revolution. Gender and national identity are key lenses through which to understand transformations during the modern period, including Modernization efforts, ideological struggles, and the cultural and economic transformations under the People''s Republic.</p> <p>Survey Requirement Met: <strong>Asia<br/> </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9936,2025,2340,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected, what was historically, the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean, which has become known as the proper noun, the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the twentieth Century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-39 Palestinian Revolt, the 1948 War for Palestine and its aftermath, Israeli-Arab relations in the 1950s, the Suez War, the implications of gendering the nation, the 1967 War and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9937,2025,2341,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-205','<div class="desc"> <p>According to Thomas Jefferson, America was to be an "agrarian Republic" - a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones, as well. Indeed, for many early migrants, America was itself a "city on the hill" - an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing, in the second half, specifically on Los Angeles, where new forms of decentralized urbanism took form in the 20th century. We will not only explore suburbia and freeways, Disneyland, and other quasiÂ­urban outposts, but also the changing character of the inner city in the mid-20th century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today - multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism - the changing character of public space, the turn to privatism, the neglect of public transport infrastructures, and challenges to democracy and equality - are ultimately compatible with the American dream of the "city on the hill" for the 21st century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9938,2025,191,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-206','<div class="desc"> <p>This course will examine the variety of female experiences in 19th and 20th century America by looking at the class, racial, and ethnic dimensions that shaped women''s lives. A second major concern will be to study women in the context of the historical developments of their time; reform movements, westward migration, industrialization, and urbanization will be examined in light of their impact on women''s experiences and values. The course will also consider a number of themes, including: popular images of women, women and sexuality, women and the family, women and work, women as consumers, and women as reformers.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9939,2025,2851,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of forced African migrants to North America to the quest for abolition and freedom in the United States. With our focus on significant demographic, institutional, cultural, and political developments within Black American communities, we will explore key themes and watershed moments in the African American experience from the early seventeenth through the nineteenth centuries. By analyzing the dynamics of African American history in this way, we will better understand how enslaved Black Americans, Black abolitionists, and freedom fighters shaped the culture and politics of the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9940,2025,1233,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-208','<div class="desc"> <p>What does it mean to say that America is a "nation of immigrants?" This course explores the creation of America through the arrival of diverse peoples from five continents over several centuries. Topics include: the legal and political foundations of U.S. citizenship; the creation of the U.S.-Mexico border; the origins of illegal immigration; ethnic and diasporic identities; state power and resistance; popular culture; social movements; and the importance of race, as well as gender and sexuality, in shaping immigration policy and its enforcement. Special attention will also be given to exploring the diversity of immigrants'' experiences in America over time.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9941,2025,1382,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-209','<div class="desc"> <p>This course traces the United States'' rise to global superpower over the first half of the 20th century; its engagement with, and interventions in, a decolonizing Cold War world; and, finally, its transition to its contemporary role as part of an increasingly multilateral and internationalist world order. Our investigation of U.S. engagement with the wider world rests on the understanding that as America''s influence on the world grew, so did the world''s influence on America. Lectures and readings will cover America''s political and military dealings with other powers - that is, U.S. diplomatic history as traditionally understood - but will also address Americans'' cultural, social, economic, and intellectual interactions with foreign peoples, both at home and abroad. Specific topics include: U.S. overseas imperialism, the U.S. role in both World Wars and the Cold War, the heightened significance of Asia and the Pacific World after 1940, internationalism and the creation of the United Nations, the emergence of the Third World and Washington''s ambivalent relationship to global decolonization, Americans'' involvement in the global revolutions of the 1960''s, the economic upheavals of the 1970''s, the end of the Cold War, and the politics of a post-Cold War and post-9/11 world.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9942,2025,2593,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-211','<div class="desc"> <p>From the Cold War to the War on Terror this course will examine the United States’ involvement in Afghanistan, Iraq and the Middle East since 1980. Among other things we will look at the connections between the events of 9/11 and the Iraq and Afghanistan wars. This class is an inquiry into the historical implications of these and other protracted US engagements from North Africa to Syria and from Somalia to Pakistan. Ultimately, we will use these events as a lens to pose a series of questions about empire, nation and national identity both in the US and in the Middle East.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9943,2025,2594,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-212','<div class="desc"> <p>With its capital in Europe since 1363 and spanning Europe, Asia and Africa for nearly five centuries the Ottoman Empire was perhaps the most successful and longest enduring experiment in multiculturalism the world has ever known. Multi-lingual, multi-ethnic and multi-religious Ottoman society and culture were comprised of Muslim, Byzantine Christian, Turkish, Greek, Persian, Mongol, Slavic, Armenian, Arab, African and Jewish cultural elements. Edicts from the Ottoman state were regularly issued in nine languages. One reason for its longevity was its willingness to draw on the diversity of this rich historical and cultural tableau. In this course, we will examine the complex social, cultural and political transformations occurring in the Ottoman Empire from its inception as a small principality in western Anatolia until it reached its zenith when it stretched into modern-day Austria.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9944,2025,1602,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-213','<div class="desc"> <p>This course explores free Black political organizing, from the American revolutionary era through Reconstruction. Students will conduct original research into African American activism that stretched from New York to California before and after the U.S. Civil War. We will explore the social networks and political institutions that 19th-century African Americans built to fight for civil rights, economic justice, and an end to chattel slavery. At the heart of the course is a digital humanities component that will involve students in researching the lives and ideas of individual Black activists. At the end of the course, we will contribute our collective research to the national website, Colored Conventions. While engaged in original historical research, students will also be reading exciting scholarship on the rise of free Black communities in the U.S. and the emergence of African American institutions (churches, schools, press, political organizations). We will delve into questions such as: how did free African Americans, from leadership to grassroots levels, organize for racial equality, abolition, and community empowerment? How did class structures and gender ideology shape the dynamics of Black organizing? What transnational relationships and diasporic identities did Black activists build in the protracted struggles for abolition and citizenship?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9945,2025,1702,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-216','<div class="desc"> <p>The "Great Books" have been seen by many as the defining element within the tradition of Western Civilization--a claim that has been the subject of fierce contemporary debate. In fact, the controversy has a long history which goes back at least as the "Quarrel between the Ancients and the Moderns" at the end of the 17th Century and extends to Matthew Arnold''s Victorian-era debate with T.H. Huxley over whether science has eclipsed the need for humanities<em>. </em>In the United States there has been an ongoing skirmish over what to read in our universities that stretches from President Eliot''s decision to abandon the core curriculum at Harvard for an open, elective system in the 1880s, to the furor that erupted with the publication of Allan Bloom''s <em>The Closing of the American Mind</em> a century later. More recently Dan-el Padilla Peralta--a professor of Roman History at Princeton--has advocated for abolishing the founding discipline of Classics altogether because of its entanglement with the origin story of white supremacy. At the bottom of the debate over the canon is the assumption that what we teach and read defines the culture as a whole, what we value, and who we are. It is a debate over the tradition''s exclusivity and chauvinism. But it is also a debate over the relevance of the humanities in a world dominated by science and the rigorous demands of pre-professional training--which is to say that it is a debate over modernity itself. Finally--and perhaps most controversially--it is debate over a putative ideal of "greatness" and "civilization," along with the role of the University in perpetuating that ideal, even as it plays the largely unexamined role of selecting leadership within a democracy. Clearly, much is at stake. This course will examine the many sides of this longstanding controversy among canon''s advocates, critics and reformers. We will also examine the attempt to institutionalize various curricular models such as the Great Books program at Columbia University and the Athens-America program at University of Wisconsin (both in the 1920s), as well as the Experimental College at Berkeley in the 1960s. We will analyze their educational goals, read some of the books they assigned, and explore the viability of the Western Tradition as a usable past.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9947,2025,3257,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-218','<div class="desc"> <p>No region of the country has been as saturated by mythology as the American West. It has been variously conceived as "empty," a "frontier," a "garden of the world," the divine realization of the nation''s "manifest destiny" (emblazoned in Occidental''s motto). That expansionist mythology not only ignored the environmental limits to what John Wesley Powell memorably described as an "impoverished landscape," it ran roughshod over the claims of indigenous peoples who lived there. This course will examine the various ways in which mapmakers, historians, writers and artists have tried to challenge that mythology by reimagining a different account (and future) of the American West. We will begin with reports from those on the scene like Hinmatoowyalahqit (Chief Joseph) and Powell, turn to the historiography of the region (from Turner to Limerick); and examine the efforts of photographers (Curtis, R. Adams, Misrach); artists (Heizer, Turrell, Martinez and Luna); writers (Muir, Solnit, Erdrich) and filmmakers (Zhao). Our investigation will linger on special regions and topics such as the efforts to map the West through early government surveys, the foundations of our national parks, the Nevada Test Site and the Cold War West, the damming of the Colorado River and Hetch-Hetchy, and the efforts by indigenous writers to rethink some of the West''s most infamous episodes (Welch, Vizener). We will also devote some time to examining the approach taken to public history by nearby institutions like La Purisima Mission, the Autry Museum of the American West, and the very different Center for Land Use Interpretation. Our goal throughout will be to follow the strategies by which these activists, historians, writers and artists attempt to transform a mythological <em>space </em>of "heroic individualism" and boundless appetite, into a <em>place </em>with a distinctive history, tradition, community--a place, that is, with claims on us of stewardship and accountability.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9948,2025,2934,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-219','<div class="desc"> <p>This is a topics course consisting of specialized courses that will focus on California, and particularly the Southern California region. <em>Different topics may satisfy different Core requirements.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9949,2025,1020,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-220','<div class="desc"> <p>This course provides an opportunity to vicariously "live" in historical cities considered to be creators of democratic or representative forms of government, as well as of great literature and art. Historian Thucydides, comic Aristophanes, and philosopher Plato draw us into Athenian gender/class socialization, politics, and culture; likewise, Boccaccio, the Medici family, and Machiavelli inform us of Florentine gender/class socialization, politics, and culture. Monumental architecture and gendered sculpture continue to serve to decorate and sustain the individuality of each city. By examining documents of daily life (including court cases concerning sexual acts) and the luxury products of the diverse crafts, we increase our knowledge of the controversial behavior and productivity of a wide spectrum of women and men. By focusing on two cities in their "golden age," the class will emphasize the shared positive, as well as negative, characteristics of ages historians have designated as "golden." </p> <p> <em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9950,2025,1172,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-224','<div class="desc"> <p>This course offers a chance to come to know a variety of individuals who lived in and travelled from the Italian peninsula in the 1300''s, 1400''s, and 1500''s. We shall journey to the Far East with Marco Polo; meet peoples of the Mediterranean; and "visit" the republics of Venice and Florence, the papal court of Rome, and the ducal courts of Urbino and Mantua. We shall enjoy distinctive creations in literature, education, philosophy, and the arts, and read letters about South American peoples from Amerigo Vespucci. Diplomat Machiavelli witnessed independent Italian city-states fall to French and Habsburg conquests and described such realistic politics; courtesan Veronica Franco successfully practiced her sexual trade while writing poems celebrating her true love, as well as her mercantile city-state. Students may petition for 300-Level credit for this class with the completion of additional work arranged with the instructor.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9951,2025,1173,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-226','<div class="desc"> <p>A history survey of the 14th-18th centuries: Renaissance, scientific advance, global encounters in Spanish and English empires, the Enlightenment, and revolutions (English, American, French). The luxury of European palaces and curiosity cabinets was based upon the exploitation of European peasants and global indigenous peoples. Students seeking origins of feminist and natural rights arguments will consider protest pamphlets, women''s writings, utopian fiction, and enlightenment stories (some with film versions), which created empathy for others.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9952,2025,1525,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-230','<div class="desc"> <p>This course is a critical survey of some great ideas that have shaped Western civilization. We will consider, among others, Homer, Sophocles, the Pre-Socratic philosophers, Plato, Aristotle, Cato, Marcus Aurelius, the Hebrew Bible and the New Testament, the Scholastics, Machiavelli, Luther, Copernicus, Galileo, Bacon, Locke, Voltaire, Rousseau, Condorcet, Mary Wollstonecraft and Mary Shelley, Marx, Darwin, Nietzsche, Virginia Woolf, and Simone de Beauvoir.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9953,2025,2655,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-233','<div class="desc"> <p>The turn to authoritarianism and rise of fascism in Europe between the First and Second World Wars represented a profound turning point in European politics and society, as nations from Italy to Hungary, Germany, to Greece became home to fascist regimes or movements. This History course studies the rise, function, and fall of fascism , especially as it existed in Mussolini''s Italy and Hitler''s Germany, between 1922 and 1945. In the period between World War I and World War II, new and alternative models for the relationship between state and society challenged the existing political and social order, as many Europeans abandoned democracy as the ideal political system. Many turned to nationalist authoritarianism as the answer to the political, economic, and social crises shaking Europe. Italy, under the National Fascist Party, and Germany, ruled by the National Socialists, were the nations in which this flight from democracy became a full-fledged descent into dictatorship and one-Â­party rule. This course examines authoritarianism and dictatorship in interwar Europe and we assess how the elevation of the state and the nation, promoted by these regimes and parties, impacted the societies involved.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9954,2025,193,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-234','<div class="desc"> <p>The class examines the political, social, and economic crises that shook the nations of Europe in the two decades following the First World War. In particular, we address the character of the crisis; the varied European responses to it; and the challenges represented by the end of the First World War, Depression, Fascism, the Second World War, and the Holocaust. While assessing the nature of the social, political, and economic crisis of interwar Europe, we will also pay close attention to historiographic debates on the rise and nature of Fascism and the origins of the Second World War. We focus strongly on primary sources such as the novels, film, and art of the era. Topics include: the "Lost Generation," the Weimar Republic, the Spanish Civil War, and the Popular Front in France.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9955,2025,1073,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-235','<div class="desc"> <p>This course examines the history of modern Europe with a focus on popular and state-supported ideologies of exclusion and violence in the long 20th century (spanning 1890-2011). Central to this course is a focus on the discursive boundaries of civil society based on race and class. Throughout the course, we situate European developments in a world-historical framework as a way to understand the increasingly interdependent political, social, and economic relationships between Europe and the colonial periphery. We begin in fin de siècle Europe, and trace the polarization of national politics and the development of the contending state ideologies of fascism and communism. We explore the consequences of various programs of decolonization, as well as the popular revolts against cultural diversity and post-colonial immigration to the metropole. The course also investigates the origins and consequences of the neo-liberal "revolution" of the 1980''s, the ethnic violence stemming from the disintegration of the Soviet Union and eastern bloc nations, and the return of the radical right throughout Europe in the 1990''s. Our course readings combine secondary and primary sources, literature, as well as a wide range of cinematic and musical sources, in order to understand the evolution of European notions of race, national belonging, and political violence.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9956,2025,613,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-237','<div class="desc"> <p>In early modern times, popular conceptualizations of the intersection of gender and sexuality, ethnicity/race, and rank/class divided women from each other. Activist advocacy for women emerged from a debate on women''s nature to a debate on opportunities for women: to be educated, to write, to speak out, to preach, to express one''s individuality in dress and demeanor, or to work in one''s chosen occupation. For the transformation in political theory from Lockean family representation to Suffragette individual representation in the state, we shall explore the literature on "rights" from Wollstonecraft to United Nations declarations on global Women''s Rights &amp; current revival of American movement for Equal Rights Amendment. We shall experience together a diversity of films as students discuss the intersectionality of race, gender, class, religion, and sexualities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9957,2025,194,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-242','<div class="desc"> <p>A chronological and thematic survey of the Chinese civilization from Neolithic times to about 1600. Major themes will include: the nature of the Chinese world order, family and lineage, gender issues, philosophical and religious transitions, political authority and its ideological underpinnings, dynastic cycles and broader patterns in socio-political movements, interactions with other civilizations, and the impact of technological and demographic changes over time. We shall use the comparative approach on specific themes to illuminate contrasts and similarities between Chinese and Western societies, and take note of recent archeological finds and new scholarly interpretations to better understand China''s dynamic past and rapidly changing present.</p> <p>Survey Requirement Met: <strong>Asia</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9958,2025,1603,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-245','<div class="desc"> <p>This course will look at the relationship of China to the world over the last 600 years. It will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Thirdworldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the level of interactions between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the "rise of the West," just as we will call into question the contemporary discourse on the "rise of China."</p> <p>Survey Requirement Met: <strong>Asia</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9959,2025,944,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-248','<div class="desc"> <p>This course covers the history of Japan from the 1868 Mejii Restoration to the present, with particular focus on the emergence of modernity, the Pacific War, and popular culture. The first section of the course will examine Japan''s modern revolution in the Mejii Restoration, industrialization and modernization in the Mejii Period, and the development of Japanese colonialism. The second section of the course will focus on the Pacific War, the bombing of Hiroshima and Nagasaki, and the American occupation, with particular focus on the politics of gender and race. The third section of the course will look at Japan''s explosive postwar economic recovery and the consumer and popular culture it produced.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9960,2025,196,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-249','<div class="desc"> <p>Korea is unique, or so say the Koreans. In many ways, it is. Politically, of the democratic nations in the world, South Korea is one of the precious few to have achieved democracy through the blood and sacrifice of its everyday citizens, that is, from the bottom up. Economically, after the Korean War, Korea was one of the poorest nations in the world, ranking below sub-Saharan countries in terms of GDP; now it is a member of the G20. This survey will begin with the forced opening of the "Hermit Kingdom" in 1872, and conclude with the 21st century international phenomenon of K-pop.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9961,2025,1660,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensable for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9962,2025,1459,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-252','<div class="desc"> <p>This course offers a broad survey of Mexican religion from pre-Columbian times to the present. The course begins with the study of Nahua ("Aztec") spirituality and ritual and continues with an examination of major developments of the colonial period as indigenous European and African peoples came together with their many different beliefs and practices. We will study indigenous strategies of both resistance and accommodation to the imposition of Catholicism, the origins of the devotion to the Virgin of Guadalupe, the Mexican Inquisition, millenarian movements, missions, and women in the church in the colonial period. Our study concludes with the anti-clerical reforms of the late nineteenth- and early twentieth-centuries, the Cristero Rebellion, increasing influence of Protestantism, and the persistence of local religions in modern Mexico. Students will analyze historical documents, religious dramas, confessional manuals, Inquisition records, paintings, sculptures, and films in their examination of the history of religion and spirituality in Mexico.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9963,2025,2897,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9964,2025,3112,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-256','<div class="desc"> <p>Since the fall of the Mexica (Aztecs) to the Spaniards in August of 1521, writers and artists have represented the dramatic events leading to the conquest of Mexico. Major figures of the conquest, such as Hernando Cortés, Malinche, Moteuczoma, and Cuahtemoc, have been memorialized, mythologized, and in some cases villainized. This course examines representations of the conquest and the leading figures of the period from a variety of perspectives. We will consider how changing political and cultural contexts have shaped remembrances of the war and the consequences of colonial rule. In this course, students will analyze a variety of sources, including Spanish and indigenous accounts, pictorial writings, paintings and artworks, operas and films. In addition, we will examine contemporary artistic projects, museum exhibitions, and archival programs that have been organized to commemorate the 500-year anniversary since the fall of the Aztec Empire.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9965,2025,197,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-258','<div class="desc"> <p>A complex web of historical ties has fundamentally shaped the political, economic and cultural development of both Mexico and the United States. Our aim will be to understand the roots and development of deep interdependency despite two centuries of relations marked by antagonism, exploitation and unilateralism. We will examine how five key historical episodes in Mexico-U.S. relations, including the U.S.-Mexico War, the Mexican Revolution, the Interwar Years, the Bracero Program, and the Cold War, shaped conflict and cooperation and impacted the everyday lives of Mexican and U.S. citizens. In the last third of the course, we will focus on three contemporary issues - immigration, trade and the environment â to understand how the past has shaped the present.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>','No prerequisites. ','No co-requisites. ',NULL);
INSERT INTO course_descriptions VALUES(9966,2025,3227,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-259','<div class="desc"> <p>This course traces the intersection of U.S. migration and health histories from the late nineteenth century to the present. The course will be organized around historical case studies including medical inspection and quarantine of Southern and Eastern European and Asian immigrants at Ellis and Angel Islands and Mexicans at the U.S. border in the 1890s-1930s; race and epidemics in early twentieth century cities; mental health of European and Latin American political refugees in the post-World War II era; farm worker health and environmental justice movements since the 1960s; forced deportation of Caribbean migrants for HIV-positive status during the AIDS pandemic; maternal and reproductive health in post-1990s detention centers; and mutual aid during the COVID-19 crisis, among others. Taken together, students will discern how migration serves as a determinant of health, and also learn about migrant resilience despite structural violence. The themes of medical racism and scapegoating, contagion narratives, occupational health, health movements, cross-cultural health communication, and medical citizenship will anchor course units. With particular attention to the analytical categories of race, ethnicity, gender, sexuality, and class, the course posits that history can make a critical contribution to our understanding of health inequities and to the development of migrant health justice. Students will gain skills in archival research, oral history methodologies, and digital storytelling, and they will be given the opportunity to participate in community-based engagement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9967,2025,945,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-274','<div class="desc"> <p>From its earliest written records in ancient Mesopotamia and Egypt, medicine flourished through Greece and Rome, was then kept alive during the medieval golden age of Islamic science, then reawakened during the Renaissance, Scientific Revolution and Enlightenment in Europe, and then crossed the Atlantic to America where indigenous wisdom already thrived. This course traces the history of medicine through these different times, cultures and regions: theory and practice; great doctors and healers, both male and female; and the effects of epidemics, such as the Black Death, on the course of Western civilization. We will end with some historically based speculations about the medical future.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9968,2025,198,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-277','<div class="desc"> <p>This course explores reproductive politics and reproductive health in North America/U.S. from the 17th to the 21st century using the lens of Reproductive Justice (RJ). RJ is a practice, a theory, and a movement conceptualized by women of colorâand particularly Black womenâin the 1990s. Its tenets include three interrelated values: the right <em>not</em> to have children, the right to <em>have</em> children, and the right to <em>parent</em> children âin safe and healthy environments.â (Loretta J. Ross, 2017). The course centers the intellectual and organizing work of women of color who have led the struggle for reproductive justice and community wellbeing. Using an intersectional RJ framework, the course examines histories of midwifery, abortion, contraception, and sterilization as well as social movements for reproductive rights and community health. Through historical documents, first-person accounts, films, and interdisciplinary scholarship, we will analyze how colonialism, enslavement, and constructions of racial and gender inequality shaped lived experiences of reproductive injustice in contexts of environmental and institutional precarity. One important goal of this course is to make connections between historical studies of reproductive health and present-day RJ activism through involvement in a community based collective research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9969,2025,199,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-282','<div class="desc"> <p>The term "Muslim World" is often criticized as imprecise. After all, Muslims constitute a fifth of humanity and live on six different continents. Nevertheless, Muslims often describe themselves as constituting a single community with shared sets of concerns. This class engages these differing views through an examination of the lives of Muslims over the past two centuries of globalization, colonialism, post-colonialism, nationalism, and ever-changing technologies of transportation and communication. Our inquiry will concentrate on how Muslims were caught up in, and reacted to, and, in turn, influenced the Great Transformation that reshaped the entire world over the past two centuries. Dealing with issues from state building to women''s rights to radical militancy, this class considers the various features of what we might call Muslim Modernity.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9970,2025,849,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-283','<div class="desc"> <p>This course examines the role of peasants and tribal formations in the process of nation and state building in the modern Middle East. In addition to looking at some of the empirical and theoretical problems inherent in defining and writing about "peasants" and "tribes," we will also consider how nationalism complicates these issues even more. We will investigate the ways that rural populations were incorporated into, or excluded from, the processes of state-formation. Finally, we will look at how representations of peasant/tribe, in ideologies of state-building and nationalism, shaped social and political relations within some of the region''s nation-states. While we will discuss the region as a whole, we will focus most of our attention on two empirical cases: Iraq and Egypt.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9971,2025,200,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/200/hist-295','<div class="desc"> <p>Specific topics may satisfy different Core Program requirements.</p> <p><strong>City of Lights: A Global and Spatial Urban History of Paris</strong></p> <p>What if we understood the times people lived through by exploring the sites and spaces that they have lived in? This course moves through selected sites in Paris â as well as global sites connected to the city â to understand how built and natural urban environments reveal connections to a multiplicity of pasts that shape how urban residents understand their place in their community. We will consider landmark buildings, but also streets, slums, domestic spaces, as well as ephemeral, temporary, or imagined structures. In this way, students will reflect on how urban spaces can reflect and reinforce power structures, how marginalized people have resisted those structures by transforming spaces, as well as how national and local histories should be preserved in urban public spaces. At the same time, students will become familiar with key events in the history of France and the world from antiquity to the present day. As well as written assignments and discussions, students will create maps and timelines that engage with the course themes. <em>This topic meets the Regional Focus (CPRF) and pre-1800 (CPPE) requirements</em>.</p> <p><strong>Crime and Punishment in Russian History</strong></p> <p>Crime and punishment constitute not only the title of a classic Russian novel, but an enduring theme in Russian history. Russian art and literature are rich in scenes of exile and incarceration, and the history of a modernizing stateâs efforts to control both crime and dissent through judicial systems reveals the shifting boundaries of its power over its people. At a moment when Americans are increasingly questioning policing and mass incarceration in their own country, this course offers students a way to understand how crime and punishment have been constructed in a different historical context.</p> <p>Russian and Soviet practices of punishment have often embodied acute clashes of values between different social, national, and ideological groups. Actions deemed criminal by one group may be seen as justified, even admirable, by another. The course will deepen studentsâ understanding of those values as well as familiarizing them with the lived experiences of people whose circumstances or convictions led them to courts, exile, and incarceration. Using novels, poetry, memoirs, film, archival and visual materials, we will consider such questions as: How did peasants avoid or invoke the Tsarist state to order their communal lives? How did revolutionaries use the jury trial to propagate their ideas? Why did Marxists believe that a socialist state would have no need for a legal system? How did prisoners in the Gulag make sense of their experiences? How have crime and corruption shaped post-Soviet society? Assessment will include participation in class discussion, short written assignments, and a final project. <em>This topic meets the Regional Focus (CPRF) requirement. </em></p> <p><strong>Russian and Soviet History Since the Nineteenth Century</strong></p> <p>This course covers an epic set of events in Russian history from the emancipation of the serfs in 1861 to the rise of Vladimir Putin in the 21<sup>st</sup> century. Spanning a century and a half of upheaval and transformation, it examines what happened when workers and peasants tried to create a new society built on social justice and economic equality. The course surveys the revolutions in 1917, the ruthless power struggles of the 1920s, the triumph of Stalin, the costly industrialization and collectivization drives, the âGreat Terror,â and the battle against fascism in World War II. It then examines the Cold War, the Soviet Unionâs efforts to reform itself, the economic chaos of the 1990s, and resurgent nationalism and authoritarianism in the information age. Weâll reflect not only on high politics and power struggles, but also on how everyday life and culture developed in times of unprecedented change. <em>This topic meets the Regional Focus (CPRF) requirement.</em></p> <p><strong>United States Presidents and First Ladies</strong></p> <p>This course provides an overview of the origin and subsequent development of the position of U.S. President and that of First Lady from the eighteenth century to the present. The class meetings center around significant U.S. Presidents: George Washington, Thomas Jefferson, Andrew Jackson, Abraham Lincoln, Theodore Roosevelt, Franklin D. Roosevelt, John F. Kennedy, and Ronald Reagan. In addition, we will consider historically important First Ladies: Martha Washington, Dolley Madison, and Eleanor Roosevelt among them. Special attention will be paid to how the offices of the U.S. President and First Lady have evolved over time; when U.S. Presidents and First Ladies have provided leadership in moments of national crisis; and what Americans have come to expect of their leaders.</p> <p><strong>A History of Native California </strong></p> <p>We are in the middle of a dramatic resurgence in popular attention to Native American issues. While it may seem sudden, this moment is best understood as the culmination of a long, and often forgotten, history of persistent Native resistance and activism. This course explores that history by focusing on the place we now call California. It tracks the early Native history of the region, and the development of Indigenous cultures deeply embedded in the unique California landscape, the coming of European settlers, and the establishment of the Franciscan mission system and its eventual collapse. It directly addresses the violence perpetrated against California Natives in the mid-nineteenth centuryâthe clearest case of genocide in American history and something every American must confront. It carries the story into the twentieth century emphasizing the ways in which Native People survived and built the foundations for the resurgence that we see today. The course uses the greater Los Angeles area as one of its texts. We will be engaged in individual guided walkabout exercises, as well as occasional class site visits. Our focus in each will be the various ways in which the city continues to reflect its settler colonial past.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9973,2025,201,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-300','<div class="desc"> <p>This course introduces students to the practice and writing of history through topical approaches. Students will explore methodological approaches to historical inquiry, conduct research projects, and improve their writing skills. Open to majors and minors only or by permission of instructor. Topics include:</p> <p><strong>U.S. Immigration History</strong></p> <p>What does it mean to say that the United States is a ânation of immigrants?â This course explores how historians have written about migration to and im/migrants in the United States, including what it means to understand migrants as settlers participating in Native American dispossession and removal. Topics include migrants and settler colonialism, the legal and political foundations of U.S. citizenship, the creation of the U.S.-Mexico border, the origins of illegal immigration, ethnic and racial identity, state power and resistance, popular culture, social movements, and the importance of race as well as gender and sexuality in shaping immigration policy and its enforcement. Special attention will also be given to involuntary migrations, including those of enslaved migrants, refugees, and displaced persons.</p> <p><strong>Christianity and Politics in America since 1945</strong></p> <p>Evangelical voters and white Christian nationalism have become hot topics, but religion has long played an important role in the U.S. political arena. This junior historiography seminar will survey how historians have written about the relationship between Christianity and politics in America since the end of World War II. We will explore the role of the Protestant church in public life, Billy Graham''s rise to fame, and the work of Christians and other religious leaders in shaping U.S. Cold War policy and engagement with the world. We will also give attention to different histories of the Religious or Christian Right and its 1970s marriage with the Republican Party, which has become one of the most successful political partnerships in American history. Finally, we will consider histories charting Christians'' role in national debates over civil rights, immigration and refugee policy, LGBTQ+ movements, and environmental justice.</p> <p><strong>Native American and Indigenous Histories</strong></p> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that scholars use to write Native American and Indigenous histories. The course highlights the field of ethnohistory, the interdisciplinary study of indigenous societies and cultures that draws from history, anthropology, archaeology, linguistics, and art history. The readings address the histories of First Nations peoples of North America, Central America, and South America, and explore a variety of topics, including native governance, sovereignty and resistance, lands and removals, wars, indigenous slavery, relations with the environment, gender and sexuality, and reproductive rights. The course is organized to illustrate major trends in ethnohistorical scholarship, and highlight shifts in themes, methods, and narrative frameworks over the last five decades.</p> <p><strong>Mexico-U.S. Borderlands</strong></p> <p>Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. Cross-Listed as: LLAS 304.</p> <p><strong>The Fascist Revolution: Politics Culture and Society</strong></p> <p>This seminar closely studies the period known as Fascist Italy (1922 to 1945). Through a close analysis of the politics, culture, and society of Italy under Fascist dictatorship, we study the causes, character, and ramification of the Italian abandonment of democracy in the wake of World War I. Because it is a historiographic seminar, we examine the central debates of the field, such as whether Mussolini ruled primarily through coercion or consent, the extent of Fascist race ideology, and whether the regime was "modern" or "backward-looking." Other major themes include: Fascist cultural modernism, gender and Fascism, and the Italian road to empire and World War II. This course uses primary sources such as translated documents, memoirs, and diaries, as well as contemporary historical analyses.</p> <p><strong>Gender and Sexuality in Colonial Latin America</strong></p> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.<br/> <br/> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written. Cross-Listed as: LLAS 301.</p> <p><strong>Histories of the French and Haitian Revolutions</strong></p> <p>Many histories have been, and continue to be, written about these revolutions and they differ from each other substantially. This course examines this scholarly literature, taking into account the choices historians make as they compose their narratives. We will examine the roles of race, class, and gender in these accounts, why different events and social groups are featured centrally in some but not others. And we will consider such controversial criteria as "accuracy," "truth," "evidence," and even "fact" all of which are interpreted in numerous ways within the historian''s craft.</p> <p><strong>Histories of U.S. Empire</strong></p> <p>Was/Is the United States an empire, and if so, what kind of empire was/is it? This upper-level colloquium will familiarize history majors and other advanced students with scholarly debates over the history of U.S. imperialism and engagement in the world. Course readings draw from the writings of U.S. historians from the early twentieth century through the present. Particular attention will be given to the impact of the Cold War and the influence of the "cultural" and "transnational" turns on how historians have approached empire.</p> <p><strong>Interpreting Civil War, Emancipation, and Reconstruction</strong></p> <p>This junior colloquium will address major debates and approaches within the historiography of the United States Civil War, Emancipation, and Reconstruction. Students will explore how American racial politics and new scholarly approaches have shaped major debates over the causes and consequences of civil war and national reconstruction. The class will take both a chronological and topical approach to historiographic analysis. We will begin by reading work from the Dunning School and critical challenges to Dunning from historians on the Left, such as W. E. B. Du Bois in his 1935 study Black Reconstruction. To understand the impact of new methods and sources, we will examine the multi-decade collaboration of social historians called the Freedmen and Southern Society Project. In the second half of the course, we will explore more recent trends in scholarship, including economic history and cultural history, as well as gender and sexuality studies and critical race theory. Finally, the class will conclude by considering historical interpretations of Civil War and Reconstruction in U.S. popular culture, through film, fiction, and drama. Students will write their own historiographic analysis on a chosen topic within Civil War, Emancipation, and Reconstruction scholarship.</p> <p><strong>The Mexican Revolution</strong></p> <p>Studies of the Mexican Revolution have been at the forefront in the development of modern Latin American social, political, and cultural history. The studies have also contributed to comparative discussions in world history about the meanings of revolutionary experience in the twentieth century. However, historians and other social scientists have reached no consensus about the Mexican Revolution from its periodization to its actual existence. This seminar will examine the competing set of interpretations, alongside primary sources, to analyze the origins, course, and legacy of the Mexican Revolution. Prominent historiographical themes for the course include: conflict between elite liberalism and mass mobilization; agrarian reform and unionization within a capitalist project of development; corporate representation of social interests; the institutionalization of revolution; race, gender, and class in nationalist rhetoric; and the role of art, education, and science/technology in state formation. Cross-Listed as: LLAS 302.</p> <p><strong>Re-Assessing European Global Encounters </strong></p> <p>The twentieth century national movements of liberation, from modern European colonialism, initiated new histories of the previous early modern age of exploration (1300-1800), from the point of view of the enslaved, the conquered, the exploited, and the newly liberated. Each student will be writing a historiographical essay revealing changing interpretations of one distinctive global encounter. Historians are re-assessing, on the Mediterranean, both the Crusades and piracy and kidnapping. Scholars specializing in trade or colonialism of a particular nation-state, such as Portugal, Spain, Netherlands, England, and France are re-considering specific settlements and trading ports on the Atlantic and Pacific Rims. Class work will enhance student skills: we shall be discussing exemplary recent historical films and histories and we shall learn how to efficiently find diverse viewpoints through online and printed sources.</p> <p><strong>Reel History </strong></p> <p>This course will examine some of the ways that the history of France has been represented in films. Joan of Arc, The Return of Martin Guerre, Ridicule, The Rise to Power of Louis XIV, Danton La Nuit de Varennes, Abel Gance''s Napoleon, and Night and Fog are among the great movie classics to be analyzed. We will also deal with recent theoretical work on "historical" cinema. Are images as valid as written text when making meaningful connections with the past?</p> <p><strong>Writing the History of the Middle East </strong></p> <p>This course is a junior seminar on recent developments in the research and writing of history as practiced by professional historians of the modern Middle East. We will look at the history of historical writing about the region and the transformative developments in the field over the last thirty years or so. The objective is to cultivate your awareness of historiography and historical criticism. Historiography can be defined as the history of historical interpretation. Historical criticism refers to how we understand history as an object of study. To appreciate various modes of inquiry in the field, we will read exemplary texts embodying established traditions and new departures as well as critical works on the ideological roots of particular fields of history.</p> <p><strong>Writing World History</strong></p> <p>This junior seminar investigates various approaches to writing world history. The course is designed to help history majors understand historiography and historical criticism. By studying recent approaches to world history, students will learn how historical debate shapes the writing of history, how historians approach and critique each other''s work, and how different styles of historical research and writing have developed over time.</p> </div>','Unless otherwise noted, one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9974,2025,1174,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-309','<div class="desc"> <p>This course examines the southern region of the United States as a “slave society,” that is, a society in which: 1) a system of enslaved labor and human commodification drove the region’s economy and 2) a powerful slaveholding minority held the reigns of political power. How did this minority white ruling class maintain their power over a large enslaved population (1 in 3 southerners by 1860) and a majority of non-slaveholding whites (3 out of 4 white southerners by 1860)? How did enslaved women and men create community, build solidarity, chart insurgent geographies, and establish a political tradition of resistance in the face of arbitrary and institutionalized violence? We will examine the rise of chattel slavery, its importance in American capitalism, and its impact on southern households, political institutions, religion, and cultural practices. Our readings will explore how a white supremacist system of transgenerational human property shaped the social relations and lived experiences of enslaved African Americans, common whites, slaveholding planters, and Indigenous nations of the South. How did these groups of southerners use religion, violence, and ideologies of sex, gender, race, and class either to challenge or reinforce existing power relations? How was the US nation as a whole complicit in the perpetuation of chattel slavery? Finally, how does the US as a nation continue to reckon with the legacies of chattel slavery in contemporary social movements, law, and culture? Course materials include primary documents, first-person narratives, film, music, and groundbreaking historical scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9975,2025,2629,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-311','<div class="desc"> <p>Americans have long idealized the frontier as an untrammeled backcountry, a mythologized landscape of “cowboys and Indians”, prairie and homesteaders, ranchers and sodbusters. In this course, we will draw on colonial and postcolonial theory to reinterpret these stories in the historical context of a set of encounters involving the Americas and the Americans - native and immigrant, from Europe, Asia, and Africa - with the rest of the world, contacts that began in 1492 and are still going on today. In the process, we will explore a diverse array of borderlands between people, environments, mythologies, and histories - spaces of interaction and reinvention. But these borderland spaces are fragile; contact zones devolve, again and again, into conquest, domination, genocide, and empire. Although this is a transnational phenomenon, this course is primarily concerned with the frontier in North America and particularly in the American West and in California. Along the way, we will also be doing our own original archival research, so students will have a chance to make their own mark upon the long history of the American frontier experience.</p> </div>','HIST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9976,2025,615,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-312','<div class="desc"> <p>The circulation of labor goods people and cultures between Africa, Europe and the Americas created an Atlantic World whose history transcends continental and national boundaries. This course examines the relationship between race rights and revolution during the Atlantic Age of Revolution that stretched from roughly the mid-eighteen to mid-nineteenth centuries. In particular we will explore how Revolutions in British North America, France and Haiti influenced the movement to end the slave trade and slavery in the Americas and galvanized slave revolts and other movements for Black liberation and human rights around the Atlantic World. A variety of readings including autobiography social and political history and ethnography will illuminate not only the history of the Atlantic World but new forms of scholarly writing that break the mold of national historical narratives. Themes include: slavery slave revolt the discourse of human rights resistance religion labor and shifting ideologies of difference in particular gender class and race.</p> </div>','One History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9977,2025,2630,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-316','<div class="desc"> <p>When we think of the World War II era and its aftermath in Southern California, images of freeways, airy tract homes, and classic Hollywood glamour often jump to mind. If we look a bit deeper, the Zoot Suit Riots, the scandal of Chavez Ravine, the destruction of public transit, and other more complex, and often "noir" images might emerge. Yet beneath both sets of images lie a set of crucial social, demographic, and political changes that marked Los Angeles''s emergence as an industrial, as well as cultural, center - changes that put the city on the front lines of many struggles revolving around Civil Rights, housing, and the future of American urbanism itself. In this class, we will explore the sunshine and the noir of mid-twentieth century LA, focusing on the ways cultural forms (such as the Central Avenue Jazz Renaissance, film noir, and modern architecture) crystallize crucial postwar social and political battles within this complex modern metropolis.</p> <p>Basic knowledge of twentieth century U.S. History is strongly suggested, but may be waived in exceptional circumstances.</p> </div>','HIST 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9978,2025,851,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-330','<div class="desc"> <p>The Storming of the Bastille, the Great Fear, the Women''s March, War with the rest of Europe, the September Massacres, the King''s trial and execution, Robespierre''s Republic of Virtue, the Reign of Terror, the Thermidorian reaction, the rise and fall of Napoleon, the impact of the rhetoric of revolution overseas, the end of slavery in France''s colonies, the transformation of French colonial Saint Domingue from slave colony into the new nation of Haiti, and the meaning of "liberty, equality, fraternity" for our own time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9979,2025,204,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-336','<div class="desc"> <p>This course traces the creation and development of the modern Italian nation state from an idea in the early 19th century through its creation in the middle 19th century to its turn to fascism in the 20th century. We will study the challenges faced by Italian politics and society as Italy moved from a disparate group of separate states toward a unified government and culture. We take an interdisciplinary approach to history and look at films, novels, and art to understand the character of modern Italian culture society, and politics. Starting in the late 18th century, the course covers themes such as: the character and legacy of Italian unification, the Southern Question, Fascism, the Mafia and postwar parliamentary democracy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9981,2025,1703,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-344','<div class="desc"> <p>One of the fastest growing economies in the world and most rapidly urbanizing society, China has risen to a central role in the world today. Yet, this rise has been fraught with problems and tensions that threaten its continued development. This course looks at the social, political, cultural, environmental, and economic development of contemporary China (from the 1970''s to the present), and asks us: how do we know contemporary China? This is a hands-on research course in which students will learn how to find, evaluate, and use sources to understand present-day China from an interdisciplinary perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9982,2025,1022,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-345','<div class="desc"> <p>This course will be a research seminar that confronts the history of the Holocaust through in-depth investigations into survivor testimonies and commemoration and memorialization. The course will examine the genocide of the European Jews by the National Socialist regime, introduce students to the history of Europe from 1919 to 1945, and raise questions about the moral and ethical legacies of the Holocaust. During the semester, we will use a variety of visual and written sources to document and analyze the systematic and bureaucratic murder of European Jews by the Nazis. Using the survivor testimonies archived at the USC Shoah Foundation Visual History Archive and the museum installation at the Museum of Tolerance, we will interrogate the emerging fields of witnessing and testimony in relationship to the memory of the Holocaust and the phenomenon of Holocaust commemoration and memorialization. We will ask questions about how individuals and society assimilated to the experience of genocide: what narrative choices, what linguistic choices, and what visual choices did survivors and the larger culture make when remembering and commemorating the Holocaust? In this way, the course will be interdisciplinary, combining the methods and sources of History, Jewish Studies, Cultural Studies, and Art History.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9983,2025,2342,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-346','<div class="desc"> <p>China is now undergoing one of the fastest rates of urbanization in world history. Just thirty years ago, about 80% of the Chinese population lived in the countryside, mostly working in agriculture. Today, China''s population is over half urban, and the CCP has announced a new plan to speed up the urbanization process so that by 2020, 60% will be urban. Furthermore, well over 100 million migrants travel back and forth between the countryside and the city each year. While these numbers are impressive in and of themselves, it can be hard to understand what they mean for individuals, for particular social groups, and for the changing rural and urban landscapes. Nonetheless, this shift from a predominantly rural population to an urban focused society is both ambitious and fraught with problems. This class aims to give an in-depth and upÂ­-close look at this amazing social transformation through readings, class lectures, film, research projects, and, most importantly, in-country experience. This course begins with a short semester on campus at Occidental and continues with a threeÂ­-week trip to China, including a homeÂ­stay with a rural household. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9984,2025,2597,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-348','<div class="desc"> <p>This course will look at the long 1960s in China and their relationship to and influence on the global 1960s. Beginning with the rise of Third-Worldism in the mid-1950s and ending in the 1970s, this period of radicalism reached its height with the tumultuous Cultural Revolution in China (1966-1969). Through memoirs, primary source material from the time, film, and secondary sources we will investigate why after years of political and economic consolidation the People’s Republic of China underwent such a dramatic and chaotic political upsurge. We will end the course by looking at the influence of China’s Cultural Revolution on the radical 1960s movements of the world, in particular in the United States and France and peasant movements in the third world.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9985,2025,852,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing especially on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization, art forms, social structure, and religion in the colonial and modern periods and considers native responses to contemporary issues such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9986,2025,1604,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , or UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9987,2025,2690,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , UEP 101 , or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9988,2025,618,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-385','<div class="desc"> <p>One of the most consistent “commonsense truths” about the Middle East and North Africa (MENA) region one encounters is that tensions generated by mutually antagonistic sectarian identities produce eruptions of political violence and civil strife. According to this view sectarian (and ethnic) identities are static and consist of an unchanging essential core not only independent of historical, political and economic developments, but indeed even <em>generative</em> of them. For some, the Lebanese Civil War of 1975-1990 seemed to confirm the “sectarian thesis” about the Middle East. Indeed, the war-torn Lebanese capital, Beirut (divided as it was between an eastern “Christian” enclave and a western “Muslim” enclave), became a metonym for sectarian conflict. Using the Lebanese Civil War as a case study, this class will test the “sectarian thesis” of identity formation in the MENA region.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9989,2025,205,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-390','<div class="desc"> <p><strong></strong></p> <p> Research topics vary semester to semester.</p> </div>','Satisfactory completion of at least one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9991,2025,206,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-395','<div class="desc"> <div><p><strong>The Democrats, Jefferson to Biden </strong></p><p>This course proceeds from the assumption that the history of a political party still matters to the course of the United States of America in the 2020s. As such, we will investigate the key lives, events, and movements that have shaped the Democratic Party, from its founding in the 1790s through the present day. At the same time, given the Democratic Partyâs troubled legacy on questions of race, gender, sexuality, and class, the usefulness of the party as a vehicle for societal change must be questioned. The course will attend to these concerns by studying the partyâs most important leaders, conventions, elections, and movements. Together we will learn how a history of a political partyâand especially of who is included and who is excludedâreveals the contours of American democracy itself.</p><p>Core Requirement Met: United States Diversity</p><p><strong>American History According to Hollywood</strong></p><p>This class investigates the way movies have shaped Americansâ understanding of their history. Surveying major developments across the twentieth century and into our own, we will examine films as imaginative primary sources that reveal the attitudes and anxieties of past eras (e.g. concerns about race and ethnicity, global power, gender and sexuality). The last third of the class will turn to a more intensive focus on the way movies have functioned as secondary sources, offering powerful (if partial) interpretations of earlier eras. Here students will focus on a select number of topics or events (e.g. the immigrant experience, WWII, âthe Westâ) and trace the changing historical interpretations the films present. Ultimately, we will evaluate how âcinematic historyâ compares to âwritten historyâ and by what interpretive or evidentiary standards or criteria we should evaluate it.</p><p>Core Requirement Met: United States Diversity</p><p><strong>Disneyland and Los Angeles</strong></p><p>In the summer of 1955, amidst the orange groves of Southern California and next to a brand-new freeway, Disneyland Park appeared. Broadcast across the country through a hit television program that premiered the previous year, the new theme park became an instant national media sensation, drawing on a long and varied tradition of American popular amusements. But, it was also an institution with deep roots in the specific culture and history of greater Los Angeles itself. In this course, we will trace the complex dialogue between the iconic amusement park and its urban environment in Southern California over the last half of the 20th century, carefully analyzing urban and social history, film, and literature to discover what Disneyland can teach us about the history, built environment, and culture of the strange, sprawling megalopolis that surrounds it. </p><p>Core Requirement Met: United States Diversity</p><div><p><br/></p><div dir="auto"><strong>National Parks/Native Land</strong><br/>This course examines a fundamental paradox in American society: That every National Park, National Forest, National Monument, or other form of federally protected land is Native land, and in almost all of those cases, it was acquired by the United States government through less than fully legal means, if not outright theft. At the same time, the National Park System is a national treasure. Perhaps both can be true, but certainly not without problematizing the claim made by Ken Burns that the park system was âAmericaâs Greatest Idea.â To do this, we will explore the origins of the National Park system in nineteenth-century conservation and wilderness preservation movements, which were themselves deeply embedded in the ongoing dispossession and erasure of Native People endemic to settler colonial societies. We will also look at the various ways the NPS has struggled to honor its original mandate: âto conserve the scenery and the natural and historic objects and wildlife... and to provide for the enjoyment of the same in such manner and by such means as will leave them unimpaired for the enjoyment of future generations.â Providing access to parks, while conserving them in a manufactured state of ânatureâ is both challenging and false. These spaces were not empty, but emptied. Some have now become crowded again with tourists, creating additional difficulties for the NPS. Course readings will highlight a few of the efforts to address this tension. Additionally, our readings will highlight ways in which Native activists, allies, and the federal government itself have begun to challenge that erasure. </div></div><p><br/></p><p><br/></p><p><br/></p><p><br/></p></div> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9992,2025,619,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/300/hist-397','<div class="desc"> <p>Reading tutorials, off-campus internships, and research projects are among options available. Permission of instructor and department chair required.</p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(9993,2025,620,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/hist-history/400/hist-490','<div class="desc"> <p>In this fall semester seminar, students will write a major paper that involves research and analysis of primary and secondary documents. Papers may concentrate on a geographical area or take a topical approach, such as History of Science and Medicine, Women''s History, or Revolutions. In addition, the seminar participants will read works by historians reflecting on their craft. The seminar culminates with individual oral presentations on the thesis research to the Department and campus community. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9998,2025,209,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/100/japn-101','<div class="desc"> <p>Introduction to the language in all its aspects, basics of grammar and oral communication and the reading and writing of hiragana &amp; katakana through intensive drills and exercises. Introduction to formal and casual speech styles. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Japanese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(9999,2025,623,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/100/japn-102','<div class="desc"> <p>Continuation of JAPN 101. Further development of communication skills, both oral and written. Mastery of the basic conjugated forms of verbs and adjectives in the past-nonpast and positive-negative paradigms in both the polite -masu and plain forms. Students will learn to decode the speaker''s assumptions or attitudes as they are integrated into certain grammatical forms. Introduction to kanji (approximately 50 characters and their multiple readings).</p> </div>','JAPN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10003,2025,210,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/200/japn-201','<div class="desc"> <p>While consolidating their knowledge of grammar basics, students will learn the keigo (honorific forms) system and a variety of additional verb forms, both inflectional and paraphrastic. Increased emphasis on conversational skills, as well as training in composing texts with coherence and accuracy. Introduction of additional kanji and their multiple readings (approximately 200 characters over the two semesters of the intermediate level).</p> </div>','JAPN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10004,2025,624,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/200/japn-202','<div class="desc"> <p>Continuation of JAPN 201. Further development of all four skills. Students will deepen their understanding of the speaker''s attitudes, as well as the spatial and temporal concepts integrated in grammatical forms. Mastery of at least 250 kanji, with their multiple readings, by the end of this level.</p> </div>','JAPN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10005,2025,854,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/200/japn-271','<div class="desc"> <p>This course examines the art of storytelling via selected works of prose, fiction, and film, which were originally written/produced in the Japanese language in the early modern, through contemporary, periods. Through close reading of texts and visual images, the student will identify and analyze specific issues that are relevant to the critical messages and the development of the narrative. The course is given in English but those whose language proficiency permits may choose to read the texts in the original Japanese. Offered in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10007,2025,3009,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/200/japn-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Modern Japanese Literature</strong><br/> This course introduces students to key literary texts from Japan’s modern era (1868-present). During this period, Japanese literature and the Japanese written language were reinvented alongside rapid socioeconomic, political, and cultural changes. As Japan experienced the industrialization, economic success, wars, natural disasters, and technological breakthroughs that characterize this period, literature played a key role in forming the national consciousness. Authors examined in this course may include Higuchi IchiyÅ, Natsume SÅseki, Kawabata Yasunari, Tanizaki Jun''ichirÅ, Åe KenzaburÅ, Tawada YÅko, and Murakami Haruki. We will consider works of Japanese literature within their linguistic, cultural, and historical contexts. Through essays, reading responses, and class discussions, students will explore how literature transforms the human experience into words and in doing so transforms the human experience. The course is given in English, but those whose language proficiency permits may choose to reference the texts in the original Japanese. <em>Core Requirement Met: Regional Focus.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10009,2025,212,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/300/japn-301','<div class="desc"> <p>Further development of the four skills. Mastery of certain grammatical forms with increasing emphasis on the speaker''s attitudes or assumptions regarding the situation. Introduction of the humble form in the keigo system. Introduction of additional kanji (approximately 250) and their multiple readings over the two semesters of the advanced level.</p> </div>','JAPN 202 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10010,2025,625,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/300/japn-302','<div class="desc"> <p>Continuation of JAPN 301. While completing the essentials of the structure of Japanese, students will prepare for a higher level of learning with intensive training in reading and writing, in particular. Students are expected to master 500 kanji, and their multiple readings, in total by the end of this course.</p> </div>','JAPN 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10011,2025,3245,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/300/japn-303','<div class="desc"> <p>This course is designed for advanced-level Japanese students and will develop their linguistic skills with an aim towards increased fluency in speaking, reading, writing, and listening comprehension. The course will accomplish these goals by reading and discussing texts in Japanese. Texts may include short stories, excerpts from novels, news articles, and scholarly books, among other materials. The texts and topics can change from year to year. Student input on topics and texts is welcome. Discussion and readings will be in Japanese. May be repeated once for credit. </p> </div>','JAPN 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10012,2025,855,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/300/japn-340','<div class="desc"> <p>This course focuses on current trends in Japanese language and society. By reading newspaper articles; listening to TV/radio news; and intensively studying vocabulary related to world affairs, social issues, and government, the student will be trained to grasp the critical information conveyed by these sources and to report accurately various facts, events, and thoughts orally and in writing. The student will also be introduced to the common practice of unorthodox usage of the language in advertisement, copy, and comic strips to develop, further, their comprehensive language skills. Given in alternate years.</p> </div>','JAPN 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10013,2025,626,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/300/japn-350','<div class="desc"> <p>In this course, the student will study various tales of the supernatural, including folk tales, myths, and ghost stories created in the ancient, through early modern periods, both aurally (from CD) and in writing. All the kanji in the text are presented with furigana attached so that a substantial quantity of reading may be accomplished time-efficiently. While reading and interpreting the text, the student will attempt creative writing of his/her original stories following the specific narrative styles. The student will also be introduced to the rakugo, humorous story-telling, performed in the traditional Japanese variety theater called yose.</p> </div>','JAPN 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10016,2025,627,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/300/japn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10017,2025,1383,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/japn-japanese-studies/400/japn-460','<div class="desc"> <p>This advanced level course will develop the student''s skill in reading Japanese through the practice of translation. The class will read a number of excerpts from authentic texts of different genres and discuss the issues that are critical for accurate comprehension of the source text, by applying theories of general linguistics, socio-linguistics, and translation; then they try translating the Japanese texts into readable English. Through the process of identifying, articulating, and solving challenges to Japanese-English translations, the students will further improve not only their language skills but cultural literacy as well.</p> </div>','JAPN 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10021,2025,214,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/100/kine-104','<div class="desc"> <p>Survey of kinesiology subdisciplines: human anatomy, exercise physiology, nutrition, motor learning, and sport and exercise psychology. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10023,2025,628,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/100/kine-197','<div class="desc"> <p>Research in a subdiscipline of kinesiology for students who do not have advanced competence in kinesiology (see KINE 397). Permission of instructor required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10024,2025,1178,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/200/kine-201','<div class="desc"> <p>This course examines the social and cultural factors that influence sport and physical activity. The positive and negative consequences of the way sport is organized in American society will be discussed. We will explore the unifying power of sport, as well as how sport serves to reproduce many of the inequalities present in our society. Topics include: violence, substance abuse, media, gender, race/ethnicity, and social class, and their roles within sport and physical activity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10025,2025,1704,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/200/kine-210','<div class="desc"> Introduction to the science of nutrition. Students will learn how macronutrients and micronutrients are assimilated into the human body from both dietary and supplement sources. A significant portion of the course will focus on understanding the science behind the USDA dietary guidelines and how to prepare meals for optimal health depending on age, sex, and physical activity levels. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10028,2025,216,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/200/kine-295','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10030,2025,1236,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/200/kine-298','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Prior to enrollment, students are expected to have a basic background in Kinesiology and/or public health (e.g. KINE 104). No previous research experience required. Students are permitted to repeat KINE 298 for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10031,2025,1527,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/200/kine-299','<div class="desc"> <p>This course will explore the impact of sports participation on female experiences, specifically considering multilevel psychological and socio-cultural women’s empowerment measures, such as self-esteem, self-efficacy, and solidarity. Focusing primarily on soccer, we will consider the possibility that the very act of training the body through sports contributes to a greater sense of ownership of one’s body – a critical psychological state for women’s health, personal security, and, ultimately, empowerment. Through the framework of social cognitive theory of gender development, we will also examine the relationship between physicality, psychology, and gender identity development. Finally, over the course of the semester, we will vet sports participation as an intervention to address gender inequality, including the impact of relevant policy, such as Title IX. Through a community-based learning component, students will have the chance to engage in qualitative inquiry on the effect of sports on health and self-concept. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10032,2025,217,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-300','<div class="desc"> <p>This first semester covers musculoskeletal anatomy and provides an in-depth study of bone composition and development; joint morphology; muscle structure, function, mechanics, and movement analysis. Includes one three-hour laboratory per week. Not open to frosh.</p> </div>',NULL,'KINE 300L ',NULL);
INSERT INTO course_descriptions VALUES(10033,2025,218,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-300l','<div class="desc"> <p>Three hour per week Human Anatomy laboratory.</p> </div>',NULL,'KINE 300 ',NULL);
INSERT INTO course_descriptions VALUES(10034,2025,219,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-301','<div class="desc"> <p>A structural survey of the human body covering the nervous, endocrine, cardiovascular, lymphatic, respiratory, digestive, urinary, reproductive, and integumentary systems. Lecture will also include the special senses of vision, hearing, and olfaction. Includes one three-hour laboratory per week. Not open to frosh.</p> </div>',NULL,'KINE 301L ',NULL);
INSERT INTO course_descriptions VALUES(10035,2025,220,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-301l','<div class="desc"> <p>Three hour per week Human Anatomy II laboratory.</p> </div>',NULL,'KINE 301 ',NULL);
INSERT INTO course_descriptions VALUES(10036,2025,629,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-302','<div class="desc"> <p>The application of muscle mechanics and Newtonian mechanics to the documentation and analysis of human movement. Lecture will also focus on the application of static and dynamic problem solving to human performance. Laboratory work will be integrated with the lecture material and will emphasize the use of electromyography and video analysis to document and study human performance. Includes one three-hour laboratory per week.</p> </div>','KINE 300 ','KINE 302L ',NULL);
INSERT INTO course_descriptions VALUES(10037,2025,630,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-302l','<div class="desc"> <p>Three hour per week Biomechanics laboratory.</p> </div>',NULL,'KINE 302',NULL);
INSERT INTO course_descriptions VALUES(10038,2025,1384,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-304','<div class="desc"> <p>Introduction of principles of human physiology with special emphasis on a systems approach. Presentation of an integrative approach to basic physiology of major organs and organ systems, covering aspects of cell function, including membrane transport, excitability, metabolism, and functions of organs from the nervous muscular, respiratory, cardiovascular, gastrointestinal, renal, endocrine, and reproductive systems. Includes one three-hour laboratory per week.</p> </div>','KINE 301 or BIO 115 ','KINE 304L ',NULL);
INSERT INTO course_descriptions VALUES(10039,2025,1385,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-304l','<div class="desc"> <p>Three hour per week laboratory for Human Physiology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10040,2025,631,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-305','<div class="desc"> <p>The study of human functions and their physiological adaptation to, and specification for, the stress of exercise. Cardiovascular and respiratory responses to exercise; use of calorimetry to study metabolism during exercise; effects of environmental stress on exercise performance; body composition; ergogenic aids and nutritional factors in exercise performance.</p> </div>','KINE 304 and CHEM 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10041,2025,221,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-306','<div class="desc"> <p>Energy sources for human movement; substrate and energy metabolism during exercise; liver, skeletal, and cardiac muscle adaptations to acute and chronic exercise training.</p> </div>','CHEM 120 and KINE 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10043,2025,946,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-309','<div class="desc"> Developmental perspective of factors contributing to acquisition of motor control from infancy through adolescence. Emphasis placed on maturational and environmental factors. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10044,2025,224,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','KINE 310L ',NULL);
INSERT INTO course_descriptions VALUES(10045,2025,225,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'KINE 310',NULL);
INSERT INTO course_descriptions VALUES(10046,2025,632,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-311','<div class="desc"> <p>This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance, and level of participation of an individual or group.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10047,2025,226,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-395','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10048,2025,227,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-396','<div class="desc"> <p>Supervised participation in the work of a nutrition exercise or other health related company or agency. Graded on a Credit/No Credit basis only. May be taken for up to a maximum of 4 units of credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10049,2025,634,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-397','<div class="desc"> <p>Individual study for students with advanced competence. Extensive study of a specialized topic or broad study of an area not otherwise included in the curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10050,2025,1237,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/300/kine-398','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Enrolled students will assume leadership responsibilities in course projects (e.g. become course liaison with community partners, develop research proposals, manage course mini-projects etc.). Can be repeated for credit. Permission of instructor required.</p> </div>','KINE 298 and KINE 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10051,2025,635,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/400/kine-490','<div class="desc"> <p>This seminar course examines a selected area of current topics in Kinesiology. It is the intent of this course to utilize an integrative approach to the advanced study of Kinesiology. Students will develop and write a comprehensive research paper in a subdiscipline of Kinesiology. Open to senior kinesiology majors with permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10053,2025,636,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/kine-kinesiology/400/kine-499','<div class="desc"> <p>Data collection, analysis write-up, and presentation of Honors thesis. May be repeated both semesters of senior year.</p> </div>','Permission of department ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10054,2025,228,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/100/latn-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Latin. Students will engage, from the beginning, with original texts from Virgil, Horace, Caesar, Cicero and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Romans, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10055,2025,639,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/100/latn-102','<div class="desc"> <p>Continuation of LATN 101 and reading and interpretation of an original text.</p> </div>','LATN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10061,2025,1705,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-320','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis -- the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. LATN 320 is the five-unit course attached to CSLC 120. </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10062,2025,1662,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-340','<div class="desc"> <p>Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near-death experiences throughout the Mediterranean. While immensely entertaining and, at times ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in postÂ­classical literature, art, and film. Course meets with CSLC 140.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10063,2025,1528,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-341','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. In this language intensive course we will read selections from Seneca''s <em>Epistulae ad Lucilium </em>as well as Horace''s <em>Satires</em>.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10064,2025,2796,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-342','<div class="desc"> <p>In this course, students and professor will collaborate in a close reading of Umberto Eco’s 1980 novel, <em>The Name of the Rose</em> (originally published in Italian as <em>Il nome della rosa</em>). The novel is many things at once. It is a murder mystery/detective novel, a coming-of-age story, a dramatization of debates within Medieval philosophy that resonate to this day, a book about books, and a fantasy about recovering lost works from antiquity, most importantly, Aristotle’s lost book on comedy. We will read the novel slowly and deeply over the course of the semester and together we will explore its themes—such as the nature of words, names, and other signs, the meaning of laughter, and the value of tolerance in a world of dogmatic certainties—and its rich literary allusions—to Sherlock Holmes, Jorge Luis Borges, Alexandre Dumas, and to numerous Medieval and ancient authors. We will track down the novel’s literary references (by reading secondary resources, such as scholarly articles), seek to understand the rich world of philosophical and theological thought its characters inhabit (by reading primary texts of Medieval philosophy, theology, and poetry), and wallow in the sheer beauty of Eco’s writing and the sheer thrill of the story he is telling, all with the goal of interpreting the novel as deeply as possible, as one of the most significant postmodern works of fiction.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10065,2025,2517,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-345','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we will also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic. In this 5-unit course we will be reading Lucretius in the original Latin, and will address the ways in which his poem''s semantic content, syntax, and literary form work with (or against) one another to produce that texture of Roman cultural significance that is the <em>de Rerum. </em>Permission of instructor required.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10066,2025,2571,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-346','<div class="desc"> <p>This interdisciplinary course, featuring ancient Roman texts in the original Latin, introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. These topics will be examined through close readings in the original Latin drawn from Cato the Elder, Cicero, Livy, Vitruvius, and others. Permission of instructor required.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10067,2025,2775,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-347','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> <p><span>Taught in conjunction with </span>CSLC 247<span>, but meeting for an additional section.</span></p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10068,2025,2830,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-348','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 B.C.E sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 B.C.E when he brought his army across the Rubicon river into Italy from Gaul. With Pompey gone, the republic was lost.<br/> <br/> Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as On the Republic and On the Laws, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators who sought to restore the old order assassinated Caesar in 44 B.C.E. They were, in turn, destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.<br/> <br/> Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise Discourses on Livy, and John Adams (the “American Cicero”), whose 1787 work Defence of the Constitutions of the United States of America owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10069,2025,3287,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-349','<div class="desc"> <p>This course explores some historical examples of ways of confronting the sort of ressentiment—“a generalized feeling of resentment and oftenhostility harbored by one individual or group against another”—that pervades our cultural discourse, wracks our political life, and makes us miserable as individuals. We shall engage in close examination of the ancient Roman authors Cicero (106 – 43 BCE), Seneca (4 BCE – 65 CE), Epictetus (c.50 – 135), and Marcus Aurelius (121 – 180 CE) and the classically-influenced American cultural critic Albert Murray (1916-2013). We shall interrogate both the strengths and weaknesses of the programs and techniques that these authors—all of whom lived through times of social and personal turmoil—proposed for remaining centered in a sense of their own dignity and in a feeling of gratitude for the blessings that were intermingled with their tribulations. In the case of Murray, we shall assess the adequacy of his theory about the African-American Blues tradition and compare it to that of some scholars who had preceded him. We shall attempt to determine the limitations and strengths of his perception that the Blues idiom represented not “the anguished outcry of a victim” but “an exercise in heroic action” through which the individual makes “an affirmative and hence exemplary and heroic response” to both the suffering particular to historically conditioned forms of oppression as well as to the absurdity of the human condition. Topics covered include the theory of ressentiment, the emotions in ancient Roman thought, Roman techniques for cultivating positive, empowering affective responses not only to “microaggressions,” but to even themost horrific events, and Albert Murray’s theory of the “Blues idiom” as “survival technique [and] esthetic equipment for living.” </p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement.</p> </div>','Latin 201 or approval of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10070,2025,3216,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-350','<div class="desc"> <p>This course investigates select African American engagements with the literatures produced by ancient Greeks and Romans. It is motivated by the conviction that we do interpretive justice to the accomplishments of African American writers when we attempt to understand the tradition(s) they conceive their work to be intervening in.</p> <p>African American literature was born with the publication of Phillis Wheatley’s <em>Poems on Various Subjects, Religious and Moral,</em> in 1773. The book evinces a deep knowledge of Latin and Latin literature, which it turns to its own emancipatory end. Indeed, Wheatley secured her freedom on the strength of the book.</p> <p>Engagement with classical texts offered Wheatley and other African American writers of every era an opportunity to access, deploy, and transform a widely shared treasury of meanings, ideas, images, tropes, genres, and styles in order to create unique works of great artistic power, capable of opening up newly imagined ways of being for themselves and their readers. In addition to Wheatley, we shall explore the classical interactions of poets such as James M. Bell, Mary Livermore, Frances Ellen Watkins, and Robert Hayden and prose writers such as David Walker, William Sanders Scarborough, and W. E. B. Du Bois.</p> <p>To experience the artistic power of these works as their authors intended, we must understand the aesthetic and literary contexts and tradition(s) in which they worked, for context and tradition are the foundation of a work’s meaning. To this end, we shall read alongside African American literary creations some of the Greek and Roman literary works to which they respond. For when we see clearly how a poem by, for example, Phillis Wheatley, responds to an ode by the Roman poet Horace—himself the son of a freedman—we grasp more fully the unique aesthetic, moral, and intellectual power of her poem. To see how Horace’s poetry could communicate to Wheatley is to see how Wheatley’s poetry can communicate its emancipatory power and promise to us in our own time. </p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10071,2025,2706,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-382','<div class="desc"> <p>In this course we will trace one historic trajectory of what we today call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the Gospels of Christianity, the troubled Confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the Divine Comedy. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring and frustrating complexity.</p> <p>Taught in conjunction with CSLC 182, but meeting for an additional section, Latin 382 will allow students to encounter a number of Roman poets (Catullus, Horace, Tibullus, Ovid, Propertius) and writers (St. Augustine in particular) in their original language forms.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10072,2025,3846,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-390','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the magnificent yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them.</p> <p>This course will be offered in conjunction with CSLC 190, but will meet for an additional 90 minutes per week to read the Latin texts covered in class in their original Latin form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10075,2025,640,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/latn-latin/300/latn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10082,2025,857,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ling-linguistics/300/ling-301','<div class="desc"> <p>This course is designed as a solid introduction to and overview of the field of linguistics. Students will explore a number of topics that are at the core of linguistics. We begin with a theoretical background in subfields such as syntax, morphology, phonology, and phonetics. Then we move to broader issues such as sociolinguistics, language acquisition, psycho/neurolinguistics, and historical linguistics. Not normally open to first-year students.</p> </div>','One year of a modern language or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10083,2025,1180,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ling-linguistics/300/ling-350','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','LING 301 , COGS 101 , or PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10084,2025,2831,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ling-linguistics/300/ling-351','<div class="desc"> <p>This course aims to equip students with the understanding of how speech sounds in the world’s languages are produced via an introduction to <em>articulatory</em> and <em>acoustic phonetics</em>. Building on the basics learned in Ling 301, you will learn how speech sounds are articulated; how to describe, compare, and contrast speech sounds in different languages and dialects on the basis of articulatory and acoustic measures; and finally, why knowledge about speech sounds is important to a variety of careers and professions, from speech pathology to language teaching to voice-to-text technology.</p> </div>','LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10087,2025,1387,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ling-linguistics/300/ling-397','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10088,2025,3131,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/ling-linguistics/400/ling-497','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10089,2025,1179,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-101','<div class="desc"> <p>This interdisciplinary course will introduce students to sources, methods, and approaches in the transnational study of Latin American and US Latino communities. We will focus on the social and cultural interaction of indigenous European, African, and Asian peoples from the colonial period to the present using a variety of primary and secondary materials including films, literature, historical documents, visual arts material, culture, music, scholarly books, and essays. Field experiences in Los Angeles will supplement the course materials. Specific course topics will vary by instructor but may include: migration, mestizaje, indigenism, imperialism, dependency, nationalism, urbanization, popular culture, and social movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10090,2025,2632,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-102','<div class="desc"> <p>This course will examine the diverse forms and social contexts of Latin American and Caribbean music, while exploring the ways that musical performance has been used to negotiate power relations in the social, political, and economic spheres since the Conquest. Focusing on musical genres and movements from Argentina, Brazil, Cuba, Haiti, Mexico, Peru, and Trinidad students will learn to recognize the techniques and instruments used in a wide array of traditional and contemporary styles, particularly those which have grown out of the hybridization of African, Middle Eastern, European, Asian, and Native American performance strategies. While knowledge of music theory and performance skills are not necessary, it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10091,2025,1663,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America, from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds, and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10092,2025,2343,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-151','<div class="desc"> <p>This course offers a survey of postcolonial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the nineteenth and twentieth centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the nineteenth century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race and the development of export agriculture. The second section introduces themes of the twentieth century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources including scholarly works, films, and primary sources to engage these topics and issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10095,2025,2633,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10096,2025,2344,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States, and to assess how these communities seek political empowerment, as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life, such as the economy, the state, and the cultural system, on the one hand, and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications, based on race, class, gender, national origin, and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10097,2025,1664,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-206','<div class="desc"> <p>Analysis of the English language development of listening speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public-school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction sheltered/SDAIE approaches English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10098,2025,3870,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-207','<div class="desc"> <p>This course will examine contemporary economic, political and social conditions of women workers across the Americas. We will analyze the ways in which US-Latina and Latin American women navigate and resist hierarchical power relations in the globalized labor market. How processes of globalization, transnationalism, work, and family shape womenâs lives are integral to this course. This course will expand the field of labor inquiry to include both productive and reproductive labors. This includes the unpaid âcaringâ work of childcare, housekeeping, and the maintenance of critical community networks. We will consider both the consequences of the sexual division of labor between those considered women and those classified as men but also focus on race, class, sexuality, nationality/citizenship, and other markers of differences. In these contexts, we will explore issues such as development, im/migration and construction of the woman worker to illuminate the gender of political economy and the political economy of gender. Finally, we will analyze struggles for <em>pan con dignidad </em>(dignity and daily bread), the place of affect in organizing, and the prospects for social justice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10099,2025,2345,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) presidents either failed to act in accordance with the transitional justice movements sweeping Latin America or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased, rather than decreased, since its transition to democracy. This class will document why this is the case, as well as look into the various movements that have mobilized since the 1970''s to the present to demand human rights in Mexico.</p> </div>','DWA 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10100,2025,3228,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-211','<div class="desc"> <p>Cultural production is central to the struggle for human rights. As cultural artifacts both conceptualize and memorialize social-political trauma, our class will take a close look at the way that Mexican film, literature and music represents both criminal and state violence. For comparative purposes, we will also look at some documentaries or film about the current violent situation in Central America. As this is a 4-unit course, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> <p><strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico (as well as Central America) through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10101,2025,2346,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10102,2025,3361,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-221','<div class="desc"> <p>Between the 1960s and the 1980s, as feminist theologians of Latin America actively confronted the Vatican’s and liberation theology’s insufficiencies in leading the marginalized out of cycles of socio-economic oppression, such theologians were commonly deemed “indecent.” In this course, we will examine how various Latin American women and social movements embraced and practiced indecent liberation, starting with the Mexican Revolutionary period and concluding with global understandings of indecent liberation in relation to religion and feminism. We will ask: How has “indecency” been constructed as a site of hegemonic power, particularly at the intersections of religion, race, gender, class, and/or able-bodiedness? In what ways is indecent liberation a form of empowerment and (how) does it relate to identity-formation? Is indecency merely a tool for liberation or a place of generative knowledge and ways of being? We will answer these questions through three main case studies, starting with “muscular” Christian women of the Mexican Revolution, continuing with indecent liberation theology during the mid- to late- twentieth century, and concluding with contemporary chicana epistemologies and ecofeminism. At the end of the class, students will apply course content to a case study of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10104,2025,3229,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-228','<div class="desc"> <p>Latino/a religious social movements around the world have pursued liberation from oppressive forces and sought to move toward just and equitable futures. In this course, we will examine the ways various Latin American social movements from the late nineteenth century to the present day have defined and practiced liberation, paying special attention to the distinctive role of religion in these movements. We will ask: How can religion provide a foundation for liberation? More specifically, how can religion foster visions of life honoring justice and prosperity? In what ways have religious communities lead organized resistances? And even when mobilizing for liberation, to what extent can religion continue to solidify forms of oppression? We will seek to answer these questions through a series of case studies including: 1) a unique form of “muscular” evangelical Christianity across Latin America after the Spanish-American War (1898) that sought to combat the oppressive powers that limited their sovereignty; 2) liberation theology and spiritual praxis within the Mexican American Civil Rights Movement of the 1960s; and 3) Latino/a global missionary efforts through various evangelical organizations. At the end of the class, students will have the opportunity to apply what they have learned to a Latin American social movement of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10105,2025,3133,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-229','<div class="desc"> <p>After a review of the historical, legal, and conceptual underpinnings of the international protection of human rights, students in this course will learn about human rights and mechanisms for their protection within the context of the United States and Latin America. Students will discuss key situations from the last half century involving challenges to human rights, including the phenomenon of disappearances common in Argentina and Chile in the 1970''s, violations of human rights during leading up to and during civil conflicts in Central America, and the impact of neoliberal economic reforms on human rights in the region. Students will explore the application of the death penalty in the United States, United States foreign policy on human rights in the Americas during the Cold War, and the claims of human rights abuse by the United States during the War on Terror. They will also have a chance to examine the United States from a double perspective: on the one hand as a key country with a major interest and impact on human rights conditions in Latin America, and, on the other, as a country with its own policy areas of struggle and progress.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10106,2025,1706,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-250','<div class="desc"> <p>This highly interactive seminar brings students from different identity groups together for informed, sustained, and respectful dialogue about “hot topics” in the lives of Latinxs in the U.S. There are three components to the course. Part 1 focuses on Dialogic Skill Building; Part 2 focuses on Power, Privilege, and Group Membership; and Part 3 focuses on specific Hot Issues (see below for specific topics). Course goals include a deeper intellectual and personal understanding of the structural implications of Latinx/Latin American identity in the U.S., honed ability to communicate across difference, and development of intergroup alliances. Seminars are co-facilitated by a faculty member and trained peers representing intersectional identities within Latinx culture. A semi-structured curriculum integrates readings, experiential activities, dialogue, and reflective writing. Next year’s topics include: Identity -- Who is Latinx? (phenotype, class, language, authenticity); (in)visibility and Representational Challenges (Beyond the Black-White binary, Media, ); Politics of Intersectionality and Simultaneity Across Contexts and Generations (Assimilation, Enculturation, Gender, Sexuality, and Religion); Educational Options for Self or Community (Curricular marginalization, Counterspaces or Balkinization); Political Resistance and Coalition Possibilities (Ideological tensions, Rebellious Lawyering, Work). Student demand will determine whether an Intragroup (all Latinx) Dialogue or an Intergroup (mixed race) Dialogue option will be offered.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10108,2025,2901,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10109,2025,3220,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-256','<div class="desc"> <p>Since the fall of the Mexica (Aztecs) to the Spaniards in August of 1521, writers and artists have represented the dramatic events leading to the conquest of Mexico. Major figures of the conquest, such as Hernando Cortés, Malinche, Moteuczoma, and Cuahtemoc, have been memorialized, mythologized, and in some cases villainized. This course examines representations of the conquest and the leading figures of the period from a variety of perspectives. We will consider how changing political and cultural contexts have shaped remembrances of the war and the consequences of colonial rule. In this course, students will analyze a variety of sources, including Spanish and indigenous accounts, pictorial writings, paintings and artworks, operas and films. In addition, we will examine contemporary artistic projects, museum exhibitions, and archival programs that have been organized to commemorate the 500-year anniversary since the fall of the Aztec Empire.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10110,2025,2554,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-258','<div class="desc"> <p>This course seeks to engage you in the fundamental problems of twentieth century Mexican history and introduce analytical frameworks for studying cultural politics. The central theme will be how the state and grassroots society negotiated the course of the nation and its political culture since 1875. We will critically examine the production of the dominant historical narrative and develop alternative ones that can help us understand the differences in the historical experiences of subaltern groups, including women, indigenous people, and <em>campesinos </em>within the Porfirian, revolutionary, and post-revolutionary periods. We will examine what is cultural about politics and what is political about culture through an interdisciplinary format, perspective and organization drawing upon the fields of history, anthropology, literature, and visual studies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10111,2025,2598,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-260','<div class="desc"> Through analyses of literature, film, music, and graphic art we will explore how Latinos have represented their individual and collective experiences in the United States. In order to allow some depth of comparison, primary attention will be given to the creative works of Chicanos in Los Angeles and Puerto Ricans in New York. However, other national origin communities (such as Dominican, Salvadoran, Guatemalan, and Cuban) will be selectively incorporated in the course. </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10112,2025,3238,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-261','<div class="desc"> <p>Colombia’s 2016 peace accord formally brought an end to a half-century of that country’s civil wars. The accord’s implementation, however, has been troubled. This raises issues relevant to Colombia and to other locales putatively transitioning out of violent conflicts. This course will address those issues in a Colombian context and by comparative reference to examples from other countries in the Americas and around the globe. Specifically, what is transitional justice and how might it inform peace-making in a country such as Colombia? Are human rights relevant to more effective transitional justice processes? More specifically, can they inform a truth-telling processes that takes into account the distinct context of a country such as Colombia and helps it establish the basis of a more pluralistic social contract that engages all of its remarkable diversity, including identities (ethnic, gender, sexual) that have long been marginalized? The course uses Colombia as a focal point, but will draw from other comparative cases both from Latin America and the globe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10116,2025,2797,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-301','<div class="desc"> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.</p> <p> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10118,2025,1665,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-303','<div class="desc"> <p>The focus of this course is on the history, literature, and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works, as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works, while play attendance will keep our focus on these plays as performance. There is a ticket fee of $50 for the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10119,2025,2898,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-304','<div class="desc"> <p>Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. </p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10120,2025,2599,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. To a lesser degree we will also examine Central American immigration from an international relations perspective.</p> </div>','LLAS 101 or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10121,2025,3871,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-322','<div class="desc"> <p>Central American feminisms have been an integral dimension to struggles against imperialism, dictatorship, and globalization across the Isthmus. This course will examine the development of Central American feminisms beginning with the revolutionary period of the 1970s and 80s up to the present. We will explore feminist epistemologies and cultures of resistance, looking at how feminists make interventions through artistic practices. We will examine the transnational dimension of feminist organizing in the region, looking at how shared histories and dialogues shape how Central American women theorize about feminism through their lived experiences. To do so, we will study critical texts written by feminist writers and collectives, historical testimonios as well as feminist cultural productions such as music and art. We will also explore how global discourses touch down and shape Central American womenâs political claims as well as how Central American feminists influence international organizations and global conceptions of human rights. Topics we will explore include contemporary regional histories and womenâs roles in social change, gendered violence and femicide, reproductive rights, memory and artivism, and motherhood as a political identity.</p> </div>','LLAS 101 or SOC 101 or HIST 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10123,2025,2639,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing, especially, on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization; art forms; social structure; and religion in the colonial and modern periods; and considers native responses to contemporary issues, such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10124,2025,2555,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , or UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10125,2025,2692,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , UEP 101 , or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10126,2025,2347,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-385','<div class="desc"> <p>The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101 , SOC 101 , HIST 102 , AMST 101 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10127,2025,3861,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-390','<div class="desc"> <p>This course examines the political ecology/economy of food, agriculture, and hunger in Los Angeles with an emphasis on Latin American-Caribbean relations. Students will explore these themes through readings, lectures, and a class-based research project in the city where students will gain practical experience in research design and apply techniques such as qualitative interviews and surveys, oral histories, ethnography, participant observation, and utilize archival material and visual and audio documentation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10130,2025,1386,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10131,2025,1125,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/llas-latino-a-latin-american-studies/400/llas-490','<div class="desc"> <p>In this course, students will write their senior theses on Latin America or Latino communities. Seminar meetings will focus on issues concerning research methods and will guide students through the steps of writing a substantial essay. Students will present their findings in a public forum at the end of the course. Open only to LLAS majors.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10133,2025,1530,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-143','<div class="desc"> <p>This 100-level gateway course introduces students to key concepts and methodologies for the critical analysis and interpretation of a broad range of media forms across the visual field - including film, television, social media, photography, games, advertising, etc. - and the cultural, historical, and ideological forces that govern them. Drawing from select case studies in media and visual culture, the course emphasizes critical reading, discussion, and writing, with forays into digital scholarship.This course is not open to Juniors or Seniors. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10134,2025,1666,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-145','<div class="desc"> <p><em>Born Digital</em>, <em>Growing Up Digital</em>, <em>Teaching Digital Natives</em>, <em>Understanding the Digital Generation</em> ... these are just some of the titles in a veritable explosion of guidebooks on how thinking, learning, and doing have changed in a world transformed by digital, networked, and social media. In this 100-level gateway course, we take a critical look at the theories and prophesies on the "Net Gen"; we explore and assess new digital possibilities for communicating, teaching, and learning; and we think critically, contextually, and historically about the ways in which new media forms and practices shape identity, community, sociality, creativity, privacy, civic engagement, and everyday life. Class projects will enable students to experiment with, and gain, practical experience applying a range of media 2.0 technologies to their own academic work. This course is not open to Juniors or Seniors. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10135,2025,1531,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-146','<div class="desc"> <p>This 100-level gateway course breaks down the aesthetic components of film and examines each element''s function in the production of meaning in a text. The course underscores the fact that cinema''s aesthetic language is not solely generated by Hollywood. It is a fluid system, highly contingent upon cultural, temporal, technological, and economic considerations. Selected international and alternative cinema movements will be examined for their enduring influences upon the global audiovisual aesthetic lexicon. Students will learn to connect formal analysis to cultural criticism and will engage with key disciplinary theories and writing methodologies. This course is not open to Juniors or Seniors. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10136,2025,1529,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/100/mac-110','<div class="desc"> <p>This course focuses on the fundamental processes and tools involved in digital design for the media arts: color, resolution, image manipulation, compositing, typography, vector graphics, web/app design principles, project workflow, and output/finishing formats. Students will become familiar with the interfaces of essential software platforms, including Adobe Photoshop and Illustrator, and will apply concepts and techniques to various assignments. Open only to MAC majors and minors. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10138,2025,1667,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-210','<div class="desc"> <p>Motion graphics and motion design are becoming increasingly vital, creative, and technical capacities for digital media production. This course focuses on the fundamental concepts, processes, and tools involved in motion design for the media arts: keyframe editing and interpolation, masking, effects, character rigging, camera movements, and titling. Students will become familiar with the interface of Adobe After Effects while exploring concepts of rhythm, space, and time, and will apply concepts and techniques to various assignments.</p> </div>','MAC 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10139,2025,1532,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-220','<div class="desc"> <p>This course focuses on the fundamentals of screenwriting and on the theory, form, and practice of audiovisual, time-based storytelling for screens. Through a series of screenings, critical readings, creative writing exercises, and the crafting of a short screenplay, students will become versed in the critical, political, and creative potentials of writing for screen cultures, including manipulation of time, space, and point of view, character development, and narrative theory. Registration is by instructor permission only. Before the end of advising week each semester, interested students must add their name to the consideration list here: https://bit.ly/MAC220</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10140,2025,3236,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-222','<div class="desc"> <p>This creative writing workshop will focus on fictional episodic and serialized series, also known as television shows or streaming series. Students will be required to develop their own original fiction series concept. The emphasis will be on developing a professional and impactful series pitch. This will involve extensive writing and verbal pitching. Developing a concept for a pilot episode will be part of the course but a pilot script will not be written. Students will also analyze existing series and will engage in thoughtful critique of their own work and the work of their peers. Screenings, readings, and discussions will also explore the influence that changing distribution and viewing patterns have on modes of storytelling and diversity/inclusion. This course is focused on live-action single camera dramas, live-action single-camera comedies, and, to a lesser extent, animated series. No sitcom/multi-camera comedy ideas will be considered or created.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10141,2025,1533,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-240','<div class="desc"> <p>This course builds upon the critical and historical grounding of MAC 100-level gateway courses, providing students with foundational media production skills and exposure to the wide-ranging creative possibilities of time-based media practices. Students will conceptually and practically explore historical and contemporary approaches to fictional, documentary, and experimental media through a series of production projects, each supplemented by a range of readings, exercises, technical workshops, guests, screenings, and critiques. Permission of instructor required. Not open to seniors.</p> </div>','MAC 143 , MAC 145 , or MAC 146 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10142,2025,2454,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-241','<div class="desc"> <p>In a digital moment where both the democratizing and totalitarian possibilities of media are unprecedented, the need to analyze and understand both the politics and <em>poetics</em> (the distinct audiovisual rhetorical strategies) of documentary media has never been more vital. This class combines readings, screenings, discussions, group exercises, and distinct forms of critical and professional writing to explore the evolving histories, theories, ethical questions, and creative modes of documentary. Together we will examine how documentary media can effect social change, expand the diversity of voices and stories that are seen and heard, and challenge each us to reimagine our fundamental conceptions of "truth" and "reality." </p><p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10143,2025,1707,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-242','<div class="desc"> <p>In our dynamic digital moment, the question, "What is a documentary?" can be answered with ever-increasing complexity. Works professing truth claims about our historical and present "realities" are just as much constructs as any fiction film, a realization that presents both creative opportunities and ethical responsibilities for documentary practitioners. This hands-on course will explore and develop a poetics of documentary, underscoring that the politics and meaning of documentary works come not simply through their content but through their aesthetic strategies and processes of production and distribution. A series of media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10144,2025,3304,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-243','<div class="desc"> <p>This course introduces students to the theoretical and analytical frameworks necessary to critically understand representations of race, gender, and sexuality (among other topics in American culture) in contemporary American film and media. Using critical theory, historical analyses, and theories of analyzing film and media, we will explore issues relevant to American studies, including race, gender, sexuality, class, family and nation, and private and public space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10145,2025,1534,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-244','<div class="desc"> <p>This intermediate topical course of varying emphases focuses on representations of difference, while underscoring the connections between race, class, gender, and sexual identity. Through screenings, and key texts from film and media studies, cultural studies, gender studies, and visual culture studies, students will learn critical methodologies for analyzing a range of media forms and the complex relationship between authors and spectators. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>Female Filmmakers Producing, Performing, and Screening Racial Identity </strong></p> <p>From early cinema to modern motion pictures, film’s shifting landscape has offered a place for crafting, obscuring, reflecting, and subverting ideas of race and ethnicity. Drawing on perspectives from cultural studies and critical race theory, this course will examine race and ethnicity, along with intersecting issues of gender and sexuality, from the positions of the filmmaker, film, and spectator, as well as the ways that film language and behavior construct racial and ethnic identities. Our course screenings will be drawn from a global film catalogue focusing on works written, produced, and/or directed by female filmmakers, including Jane Campion’s <em>The Piano</em> (1993), Gurinder Chadha’s <em>Bend It Like Beckham</em> (2002), Julie Dash’s <em>Daughters of the Dust</em> (1991), Claire Denis’s <em>35 Rhums</em> (2008), and Marjane Satrapi’s <em>Persepolis</em> (2007), and our readings will incorporate texts and excerpts from such theorists as Richard Dyer, Ed Guerrero, Linda Williams, and Lola Young. Through screenings, readings, and class discussions, we will produce rhetorical analyses, visual and oral presentations, and analytical critiques to help us engage dialectics of race and ethnicity in film.</p> <p><strong>The Female in Japanese Film and Media </strong></p> <p>The course will consider the role of the female in Japanese film in front of and behind the camera. In the current climate of the #metoo and #timesup campaigns and revelations of sexual harassment in the Hollywood film industry, where does the Japanese film industry stand? This course will look at Japanese cinematic history whose roots are embedded in the studio system in Kyoto and consider how the role of women in film has been shaped by a changing society’s values and norms. The contributions from Japanese female film directors such as the pioneers Sakane Tazuko and actress-director Tanaka Kinuyo to their contemporary counterparts such as award-winning Kawase Naomi, the pink films of Hamano Sachi, relationship driven films of Mishima Yukiko, to the fashionable flair of Ninagawa Mika. We will look at emerging female filmmakers such as Oda Kaori, Endo Maiko, and media artist Sputniko! who are using the format of the moving image to engage Japanese audiences in global issues. In addition to looking closely at works from female film directors, the course will examine tropes and representations of iconic actresses within Japanese cinematic history to appropriation of Japanese culture in pop music videos. <em>Additional Core Requirement Met: Regional Focus.</em> </p> <p><strong>Cultures of Protest</strong></p> <p>The English word <em>protest</em>– “to declare publicly” – derives from a Latin verb meaning “to testify, give witness.” In this course we will explore a variety of films from different geopolitical regions and of different genres and different historical contexts that might be interpreted as speaking to all kinds of modalities of protest: protests against nationalisms, against ethnic cleansings, against xenophobia, racism, and homophobia, against national violence and against gender purity. We will engage with different understandings of the concept of protest and focus on its relation to migration, foreignness, national identity, racial, gender, and sexual politics, border politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations.<em>Additional Core Requirement Met: Global Connections</em></p> <p><strong>From Cyborgs to Siri: Gender, Technology and Media</strong></p> <p>In this course, we will examine the humanoid robots, cyborgs, and AIs imagined in film, television, and advertising, as well as the dialogue between these fictional creations and their real-life counterparts, from historical automata to the current development of robotic and virtual assistants and companions. How does techno-fantasy inform material reality, and vice versa, in the construction of these figures? What roles do we ask them to play in both realms? What social, cultural and historical conditions give rise to, and shape, their appearance? What cultural hopes and fears do they reveal? In answering these questions, we will examine issues around gender, sexuality, and race, while drawing from a wide range of critical discourses, including technoculture studies, cyborg feminism, post-humanism, and afrofuturism.</p> <p><strong>Feminist Provocations: Migrant Justice in the US Cinema</strong></p> <p>In this course, students will be introduced to diverse representations of fights for migrant justice and migrant rights through an exploration of contemporary feminist transnational cinema in the United States. Taking an intersectional, historical, and multidimensional theoretical approach, we will engage films highlighting a variety of communities such as African, African American, Arab, Asian, and Latinx, allowing us to develop nuanced perspectives. The select case studies -- including, <em>Amreeka</em>, <em>Dirt</em>, <em>Entre Nos</em>, <em>Daughters of the Dust</em>, <em>Maid in America</em>, <em>Mississippi Masala</em>, <em>Nanny</em> -- will push us to consider complex questions around citizenship, belonging, national legitimacy, and what I call ‘alienhood’ – discursive modes of stigmatizing those who are deemed ‘foreign.’ Yet, we will also analyze diverse representations of provocation in cinema: calls for subverting various systems of oppression that perpetuate patriarchal domination, xenophobia, and national exclusion while studying theories of transnationality, feminist visuality, film theory, queer theory, and theories of difference. In a historical moment when border walls and refugee camps are once again proliferating, ethnonationalism and white supremacy are on the rise, and women’s rights, queer rights, and immigrant rights are being violated, such feminist provocations can serve as a guide for our own social justice interventions. Complementing course work, students will engage in creative projects, take field trips to local immigration museums, learn from filmmakers, and collaborate with local organizations. This course is part of the Humanities for Just Communities curriculum. <em>Additional Core Requirement Met: US Diversity.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10146,2025,2678,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-245','<div class="desc"> <p>This practice based course focuses on a specific topic in media production. Students will explore the propensities and challenges of a particular production approach, model, technology, or aesthetic practice through the creation of a series of media projects. Classes will include screenings, readings, and discussion that situate these practices conceptually, ethically, and culturally but the emphasis is on hands-on project creation as a means of understanding the production topic at hand.</p> <p><strong>Documentary Animation</strong></p> <p>A hands-on course in the fundamentals of animated media production examined through the lens of the history, techniques, and methods of documentary animation. What realities might be uniquely explored or represented using varying modes of animation, either as part of a larger documentary project or as the entire project itself? Students will explore creative strategies for designing form and content across experimental, abstract, and character based approaches. A series of collaborative, hands-on media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops. Recommended (though not required): MAC 110 and MAC 210.</p> <p><strong>Process-Based Mediamaking</strong></p> <p>A hands-on media production course in which the final result of each project is, to some extent, outside of the creator’s control. The vast majority of traditional film and television is intentionally scripted or planned in advance and the production/filmmaking process is focused on capturing images and sound that perfectly execute that script or plan. Process-Based Mediamaking is an alternative to this system. It is rooted in the idea of developing a process, methodology, or set of rules ahead of time and then letting that open-ended, exploratory, and in some cases even random, approach generate media art. This course will consider historical and current examples of Process-Based mediamaking but the main emphasis of the course is the creation of this kind of media. No prior mediamaking experience is required.</p> <p><strong>Exploring 360º Video and Immersive Installations</strong></p> <p>Do 360 video cameras, VR headsets, and immersive screen installations represent a paradigmatic change in production, artistic conception, and audience experience? This course will introduce students to the foundational methods, technology, aesthetic approaches, and cultural and ethical considerations of live-action immersive media creation for both VR headsets and video installations. Students will work in a collaborative environment to conceive and execute a series of projects using 360 video cameras and traditional digital video cameras. Projects will include narrative, documentary, and experimental approaches. Students will be encouraged to investigate how live-action 360 video and immersive installations differ from, and are aligned with, traditional screen-based media. No previous filmmaking experience is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10147,2025,1708,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-246','<div class="desc"> <p>Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p><strong>Obsolete Media: Analog Technology, Blackness, and Sex</strong><br/> Analog technologyâwhether it is 16 or 8 millimeter film, consumer home videos, cassette tapes, or xerography for zine-makingâ requires a certain type of touch. Steenbeck flatbed editing consoles, for example, required physically splicing, rewinding, and penciling on the film. This course invites students to both experience and theorize around the sensorial implications of audiovisual, sonic, and print analog technologies. Shifting from the recent association of the analog with hipster aesthetics, this course draws on black queer, feminist, and trans uses of the analog between the 1970s and 2000s to consider the sensorial entanglement of blackness and technology in the United States. Case studies include Kathleen Collinsâ 1982 film <em>Losing Ground </em>(originally filmed on 16mm), Matt Wolfâs 2019 documentary <em>Recorder: The Marion Stokes Project</em>, black queer zines, and Ella Fitzgeraldâs television advertisements for Memorex cassette tapes. This community-based learning course will include field trips to a local film archive and guest speakers (i.e., zinesters) during class, as well as attendance at Oxy Cinemathequeâs programming on the âBlack Analog.â Example assignments include possibly making a zine and mixtape. Additional Requirement Met: US Diversity.</p> <p><strong>New Waves of East Asian Cinema</strong></p> <p>The history of cinema is marked by New Waves reflecting both artistic and cultural movements and shifts in cinematic practice. This survey course focuses on the New Waves of East Asian Cinema, engaging their sociocultural history alongside aesthetic and technological developments. Topics include: Japanâs <em>NÅ«beru bÄgu</em>in the 1950s, which borrowed its name from the inaugural movement of the French <em>Nouvelle Vague</em><em>;</em> the waves in Hong Kong cinema, which were thematically linked to the impending expiration date of the 1997 handover to China; and the developments in Taiwanese art and film that were spurred by the ending of martial law in 1982. We will examine the historical events of resistance underlying these cinematic movements and their long-lasting impacts on society and culture. Students will engage with the material critically through projects and presentations alongside weekly screenings, readings, and discussions. Additional Requirement Met: Regional Focus.</p> <p><br/> <strong>Modernity and the Rise of Cinematic Visuality</strong></p> <p>Many have argued that the history of modernity has been, above all, a history of visualization, changing the way we see. In this course, we will examine a diverse range of nineteenth and early twentieth century visual practices, technologies, and experiences including train rides, panoramas, shopping arcades, assembly lines, and amusement parks that helped shape the "modern observer" by altering both the perception and understanding of time and space, public and private, work and leisure, the normal and deviant, and the individual and collective. Through a combination of critical readings, screenings, and field trips, we will ask how such practices of looking not only influenced early cinematic form and content, but also how they continue to inflect postmodern media culture, from television to the internet. The course culminates in a 3D screening of HUGO (2011, Scorsese).</p> <p><strong>The Philosophy of Classical Hollywood Cinema</strong></p> <p>This course will attempt a survey of current philosophical approaches to classical Hollywood film, beginning with Stanley Cavellâs The World Viewed: Reflections on the Ontology of Cinema (1971). This work initiated a new and flourishing sub-discipline within contemporary academic philosophy called film-philosophy. The central assumption within this body of inquiry is that film is (or can be) âphilosophy in action.â In this course we will be returning to the source of this idea to read Cavellâs original work, as well as selections from his two subsequent books: Pursuits of Happiness: the Hollywood Comedy of Remarriage (1981) and Contesting Tears: The Hollywood Melodrama of the Unknown Woman (1996). We will then extend our inquiry to other writers inspired by Cavell (and reflections on later developments within Hollywood), such as Robert Pippin (writing on Film Noir), Stephen Mulhall (writing on the Alien series and other sci-fi), and William Rothman (writing on Hitchcock). Weekly screenings and discussions will be part of the course, as well as one or two field trips to Los Angeles archives.Cross-listed as PHIL 317.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10148,2025,3212,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-247','<div class="desc"> <p>A hands-on course in animated media and visual effects production examined alongside historical and critical animation studies. Students will explore creative and technical strategies for designing form and content across experimental, abstract, character based, hybrid, and live-action composited approaches. A series of individual and collaborative, hands-on media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct Core requirements.</strong></em></p> <p><strong>3D Design &amp; Animation Fundamentals</strong></p> <p>A hands-on course in 3D animated media production using Cinema 4D. A series of practical workshops will introduce students to fundamental principles and practices of modeling, lighting, animation, rendering, and concept design alongside studying existing and historical works, and critical animation studies frameworks. Students will engage in conceptual, creative, and technical exercises, screenings, reading, writing, discussion, and the development of a series of short animated projects. No prior art, animation, or design experience necessary.</p> <p><strong>Representing Health, Illness, &amp; Well-being Through Storytelling</strong></p> <p>Whose stories are being told and shared, and whose are left out? How might we use animated storytelling to voice and share new stories of health, illness, and well-being?</p> <p>Students will engage with theoretical readings, screenings, discussion, and writing to examine how marginalized communities are often mis-represented or absent within conversations about health, illness, and well-being. As these topics are explored theoretically, students will develop their creative voice through journaling, sketching, creative research, and hands on experimentation with a variety of animated storytelling techniques, forms, and methods across experimental, abstract, and character based forms. Students will engage with writing, storyboarding, creating animatics, working with voice-over acting, sound design, and creating animation using analog and digital techniques.</p> <p>Special emphasis will be placed on documentary animation’s unique ability to represent varying facets of health and illness with sensitivity and layered meaning. Throughout, students will work in groups to develop short animated films around chosen health, illness, and well-being topics explored throughout the semester, and we will develop distribution plans for how these projects might be best shared online within a larger outreach framework and context. <em>This course is part of the Humanities for Just Communities curriculum.</em></p> <p><strong>Animation Fundamentals </strong></p> <p>A hands-on course in the fundamentals of animated media production with special emphasis on integrations between analog and digital techniques. Students will explore creative strategies for designing form and content across experimental, abstract, and character-based approaches, with special emphasis on investigations with analog materiality. We will experiment with a range of lens-based stop-motion animation techniques (2D down-shooter, pixilation), and digital methods (composting &amp; keyframing in After Effects). Throughout, the emphasis will be on learning and practicing the fundamentals of animation timing, audio-visual design compositional principles, and pre-production methods for developing concepts and stories especially geared to animation. A series of collaborative, practical animated media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10149,2025,1535,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-248','<div class="desc"> <p>A survey course on the global language of film and media. Screenings and readings will cover a range of national contexts, examining questions of national identity, national cinema, alternative cinema, Third cinema, experimental ethnography, diaspora, postcoloniality, globalization, and transnationality. The course will take advantage of the international and intercultural makeup of Los Angeles, as a means of exploring media and accessing practitioners who are working across national boundaries. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics fulfill distinct Core requirements. </strong></em></p> <p></p> <p><strong>Speculative Othering through Worldly Frames in Television and Media</strong></p> <p>Imagined worlds, both past and present, have served as alternative prospects for audience realities. This course will use global perspectives from multicultural voices in television and media to investigate diverse cultural, social, and political contexts informing speculative fiction following Judith Merril’s definition of the term: "stories whose objective is to explore, to discover, to learn, by means of projection, extrapolation, analogue, hypothesis-and-paper-experimentation, something about the nature of the universe, of man, of ‘reality’.” Course screenings will include tv series from Brazil,<em> 3%</em> (2016-2020); Australia, <em>Cleverman</em> (2016-2017); Japan, <em>Alice in Borderland</em> (2020- ); South Africa, <em>Shadow</em> (2019); the United Kingdom, <em>Timewasters</em> (2017-2019); and the United States, <em>The Sandman</em> (2022- ). Through screenings, critical readings, observations, hypotheses, and experimentation, we will examine key terms of modern speculative fiction, including reason and technology, alien visitation, transhumanism, and utopias and dystopias, to help us draft and answer questions about identities, worlds, and existences. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>Foreigners and Cinematic Border Crossings</strong></p> <p>What does it mean to be-placed-into-foreignness? To be marked as foreign? To inhabit this category and feel its weight? We know that certain bodies, or regions, are labeled as foreign, but also texts and images. “Foreign” is a sticky term – it sticks to the body of a human, or to a particular image or sound – and it marks it as something else, as something other than me, alien, some form of alterity. How do transnational cinema and media approach representations of foreignness? How do they engage questions of aesthetics, politics, and ethics? We will explore these questions while focusing on films and media that privilege transcultural encounters and border crossings in various global locations. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>Transnational Cinemas: Borders, Walls, Difference</strong></p> <p>In film studies, the term “transnational” has opened up new ways of thinking about cinema, its production contexts, spectatorship, and ideological investments. We will explore different understandings of the concept of transnationality and focus on its relation to migration, foreignness, national identity, racial politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). We will screen a number of fascinating films and videos from multiple regions of the world. The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>African Film and Media</strong></p> <p>Africa has one of the largest film industries in the world. This course surveys significant film and media traditions within Africa along with their aesthetic, political, and cultural contexts. We will explore African film and video across a broad array of traditions, mediums, and historical periods including the griot, Yoruba theatre, colonial visual culture, independence and liberation films, counter-ethnography, the Négritude movement, Third Cinema, post-independence Francophone Art films, sub-Saharan Black African cinema, FESPACO, Anglophone Nollywood and Ghana popular video, and African new media. The goal is to focus on distinctly African film and film scholarship by critically examining the various conflicting traditions and methodologies of cross-cultural African film studies. This course will involve seminar-style discussions, presentations, extensive screenings (in and outside of class), guest lectures by African filmmakers and scholars, and critical writing. <em>Additional Core Requirement Met: Regional Focus</em>.</p> <p><strong>Transpacific Social Justice</strong></p> <p>This course will explore a variety of contemporary film and multimedia productions, with a focus on social justice issues across the transpacific. Topics discussed may include, but are not limited to: race, gender, and sexuality in a networked world; war and its aftermaths; labor rights; and digital media advocacy. What are the implications of multimedia technologies for social justice and democracy, especially in marginalized communities across the Pacific and their diasporas? Students will learn about emerging art and activist movements in Asia and the Pacific through a variety of screenings, readings and lectures. There will be a particular focus on materials coming from social justice movements such as documentary film, independent film, and activist art. We will review and analyze different perspectives, for example, a rising intersectional feminist movement in South Asia, sexual politics in East Asia, participatory videos created from migrants in Southeast Asia, to the student uprisings of Taiwan’s Sunflower Occupation and Hong Kong’s Umbrella Revolution and current protests. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10150,2025,3355,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-249','<div class="desc"> <p>It is impossible to talk about the City of Angels without talking about its movie business. The history of American cinema is so intertwined with Los Angeles that the term “Hollywood” is used interchangeably with “American film” worldwide. Through screenings, readings, and discussions, we will look at the history of Los Angeles cinema and the complex relationship that American film has had with its host city. We will look at the mythical allure of the region that enticed film pioneers to leave the East Coast for the land of sunshine, as well as the dark visions of L.A. film noir that challenged this mythology. We will consider the ways that Los Angeles is depicted by native “Angelenos” and by outsiders. This course will also look at the diverse L.A. Rebellion School, the city’s penchant for destroying itself on film, and how the late 70s/early 80s Los Angeles music scene fueled a punk aesthetic in independent films. Lastly, we will explore Los Angeles neo-realist cinema – a cinema of marginalized voices that contrasts sharply with the glittering image of the city in mainstream American film and television.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10151,2025,1536,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-250','<div class="desc"> <p>This hybrid media theory and practice course directly engages the interrelationship between discursive and creative production. Classes will include screenings, lectures, discussion, and hands-on experiences in producing and collaborating on digital media projects. Topics courses may be repeated with a different topic for credit.</p> <p><strong>Experimental Gamemaking</strong></p> <p>In this hybrid theory/practice course, students will view, play, and make video games that follow the lineage of contemporary experimental and avant-garde game makers. In addition to practicing the fundamentals of game engines, game programming, and introductory 2D/3D asset making, we will trace the history of transmedia storytelling through experimental game making, from Colossal Cave Adventure to Disco Elysium. In the process, students will learn about the pitfalls and bottlenecks of modern game production, while being introduced to alternative aesthetic, sociopolitical, and creative discourses around gaming, and the innovative strategies deployed to challenge and change the video games industry. Throughout the course, students will conduct a series of experiments ranging from short prototypes for visual novels to Machinima, and they will expand one or remix multiple prototypes into a larger game. No previous experience with games or programming necessary.</p> <p><strong>Media Activism through Participatory Video</strong></p> <p>This is a combined theory and practice course that will engage students in looking critically at what participation means when working with members of a community. In participatory video, who holds the camera often determines who holds the power. By gaining an understanding of documentary film and ethics, we will question the relationship between filmmaker and subject. Students will learn about working with community, developing relationships and trust, and how to collaborate using participatory methods. Through readings, screenings, and guest lectures, the course will explore the potential of using digital media tools to engage communities in media activism. Students will be introduced to a variety of methodologies that will lead up to a final collaborative project that will engage a local community in participatory video. This final project will result in a series of public workshops, screenings, and exhibition.</p> <p><strong>Visual Design and Composition for Media</strong></p> <p>This theory/practice course focuses on better understanding and intentionally designing visual structure within cinematic media. Students will critically reflect on how visual components communicate meaning across narrative and non-narrative forms alongside designing their own image systems through a series of photographic exercises, video sketches, pre-production visualization, and concept design look books and research for larger cinematic projects. It is an opportunity to spend more time exploring cinematography, production design, and overall compositional design elements such as color, value, line, shape, depth, visual rhythm, and more. The course will examine the varied roles that contribute to designing a projectâs visual style and story across film and varied cinematic media forms. Students will also consider how these principles and methods are engaged, extended, and challenged through emerging media forms.</p> <p><strong>The Video Essay</strong></p> <p>In this theory/practice course, we will explore what it means to âthink and write with videoâ about film, media, and popular culture. Readings, screenings, and class discussions will engage the history of the video essay, including its filmic precursor, âthe essay filmâ; debates about what makes a video essay scholarly; and a variety of formal, aesthetic, and rhetorical strategies for communicating ideas through moving image and sound. Student work will involve a series of hands-on assignments building towards a scholarly video essay that can be submitted to an on-line journal.</p> <p><strong>Game Design Workshop</strong></p> <p>This course will introduce students to the foundational concepts of game design through the practice of creating video games. Video games are products of culture, and this course approaches video games as media artifacts worthy of analysis, critical design, and purpose-focused production. In this course, students will learn digital tools for video game creation, such as an introductory-level game engine, basic programming skills, and audiovisual design. Students will also question and critique theories and foundational practices of game design. Readings, lectures, and in-class exercises will explore the expressive and political possibilities of games as cultural productions. No previous programming or game design experience is required.</p> <p><strong>Reimagining Social Media Practice</strong></p> <p>This course seeks to dismantle conceptions of the internet and social media as distribution platforms and instead critically and creatively reimagines them as a production medium, one capable of producing unprecedented media content, communities, and cultural interventions. Students will engage with theories of social media and online communities by engaging with projects that explore these issues from a practical hands-on perspective. Students will become social media and online content creators to accomplish three main goals: become literate in the social media content creation process, understand current research and theories on social media and online communities, and transgressively examine the implications of a culture imbued with social media and online content. Topics to be explored in the class include influencer culture, cyberbullying, the Alt Right, strategy, public crises, identity communities, election hacking, fake news, and psychological and social implications of social media use.</p> <p><strong>Digital Tools for Radical Change</strong></p> <p>This theory and practice course takes a critical look at the use of media communications and social media in resisting oppression and organizing for social change. Readings, class discussions, and creative assignments will engage a variety of case studies in which digital and social media were used to shape debates, advance causes, build networks, and encourage civic participation, including #BlackLivesMatter, @realdonaldtrump, and the ACLU''s Mobile Justice app. Throughout, emphasis will be placed on the art of communication as the single most important aspect of effective community organizing, activism, and advocacy. Students will put theory into practice by conceptualizing, executing, and evaluating a digital advocacy campaign via social media. Their work will be supported by skills-based workshops and class visits with Los Angeles media activists and social media influencers, which will help equip them with practical tools and insight into digital and creative practices for achieving specific goals. This course is being linked to a Cinematheque series and will include a few mandatory screenings on Thursday nights.</p> <p><strong>Remix Media and Culture Jamming</strong></p> <p><em>What is Remix media?</em> Remixing, reusing, and reworking separate media elements from different sources to produce an entirely new work with a different meaning. <em>What is Culture Jamming? </em>Coined by Oxy alum ''82 Marc Dery, "culture jamming" is an anti-consumerist tactic used to disrupt or subvert dominant media culture, including (but not limited to) corporate advertising. This theory/practice course takes a critical look at the history of remix cultureâfrom Dada to Machinimaâalong with the gamut of aesthetic, political, and social concerns addressed by remix artists and musicians and the reception (and even appropriation) of their work by the corporate entertainment industry. Students will put theory into practice by producing their own remix projects including a <em>subvertisement </em>and remix video. We will also explore issues around copyright and fair use in the sampling of both commercial and independently-produced works.</p> <p><strong>Public Media and Alternative Exhibition Strategies </strong></p> <p>For over 25 years Anne Bray and her Los Angeles organization FREEWAVES have created public media art events that bring diverse audiences and independent media artists together in dialogue on current issues in nontraditional, community-focused exhibition contexts. This hands-on course will engage students in theoretically and practically exploring past precedents and future possibilities for innovative and people centered media curation and exhibition. Students will work with Bray to conceptualize and realize alternative public media programming interventions on campus, in Los Angeles, and online, examining critical questions of space/venue, audience/community, and outcome/social engagement.</p> <p><strong>Media &amp; Social Movements in Los Angeles</strong></p> <p>This theory/practice course focuses on the relationship between media and social justice struggles in the greater Los Angeles region. Readings, class discussions, and creative assignments will address the use of media tools as a form of local and global resistance against various forms of economic, racial, sexual and gender oppression. Students will learn about the theoretical and material tensions between the global political economy and local grassroots media movements, ranging from Asian American video collectives of the 1970s to the Los Angeles School of Black Filmmakers (a.k.a. L.A. Rebellion film movement) of the 1980s. In the latter half of the semester, we will examine contemporary sites of media activism online, including but not limited to #blacklivesmatter, QWOCMAP, and the Asian American Oral History project. Weekly labs will provide opportunities to explore various media forms and strategies in order to critically analyze why certain platforms have emerged within different movements and what political possibilities still resonate. While labs will focus on audiovisual production and social media, there will be room to experiment with other forms of media resistance including âzine-making, comic books, and musical performance (e.g. critical karaoke, flash mobs, etc.). We will be joined throughout the semester by media activists and local community organizers, who will share their perspectives on contemporary struggles and, at times, lead skills-based workshops. The course will culminate in a final project in which students conceptualize and begin to execute a media campaign with a Los Angeles-based community organization. <em>Additional Core Requirement Met: United States Diversity</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10152,2025,1709,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with what is known as the "LA Rebellion," a moment of a radical reconceptualization of filmmaking, fostered by black students during their studies at the UCLA film school, and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasion devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include <em>Selma, Fruitvale Station, Daughters of the Dust, Lemonade, Pariah, Bush Mama, Do the Right Thing, and An Oversimplification of Her Beauty.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10153,2025,2455,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-255','<div class="desc"> <p>This course examines the history, theory, and practice of integrating time-based media into three-dimensional space. This is a theory/practice course: students will study the history of video and audio installation and attendant theories around interactivity, virtuality, and site specificity, while experimenting with different methods of troubling the passive relationship of viewer to screen in traditional cinema. Through hands-on exercises, students will develop sensitivity to three-dimensional space, explore the relationship of the human body to aural and visual environments, and create a series of linear and non-linear narratives that take into account viewers in motion. The class will culminate in the production of a media object and/or installation that demonstrates a careful consideration of form and content in relation to space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10154,2025,2348,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-260','<div class="desc"> <p>This intermediate topical course addresses new and evolving issues around digital technologies and networked publics, examining their social, cultural, political, and global ramifications both on- and off-line. Coursework will engage digital media theory and scholarship. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>Critical Game Studies: Aesthetics and Politics </strong></p> <p>Are video games addictive? Does video game violence affect people in RL (real life)? Are video games art? Can video games change the world? Even as video games have emerged as a multi-billion dollar media industry, how we discuss them remains contentious. Critics disagree over their status as a “serious” mode of artistic expression, along with their place in the “culture wars” that have shaped the political life of the United States and the world. This course provides students with the intellectual framework and critical vocabulary to examine video games as media texts via aesthetics: the value of gameplay experiences and how we fit them into our lives. How do we play, and why? The course will also address questions of politics: how can games shape, and how are they shaped by, the current of public life? Who gets to play, particularly along the lines of race, gender, sexuality, and class? Live and recorded gameplay demonstrations will provide students with the material for criticism and inquiry, alongside contemporary critical games writing, which will serve as models for student writing projects. Participants do not need previous experience with games or computers, but only a willingness to engage with games and gameplay within a critical context.</p> <p><strong>Women Making Moves - Women’s Migration and Media </strong></p> <p>The course will apply a theoretical and practical framework to facilitate an understanding of gendered migration patterns within Asia with a focus on Japan, Hong Kong, Taiwan and the Asian diaspora. This course will be designed to encourage students to critically engage in understanding global migration flows and trends, but to also look closer at more personal narratives of migration. We will discuss forced and voluntary migration, issues of sex work and the emotional labor industry, the crossing of borders, and what it means to belong. The thematic focus will be on the feminization of migration, the monetization of the migrant worker’s body, and looking at how feminist activism is perceived within an Asian context. Students will collaborate on a visual research project that examines themes of migration and how it impacts their daily lives. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>The Art and Politics of Virtual Reality</strong></p> <p>Recent years have seen an explosion in consumer-grade virtual reality (VR) technologies — devices like the HTC Vive, PlayStation VR, Oculus Rift, and Samsung Gear VR have brought a wealth of new experiences to audiences and users, both inside and outside their homes. The new wave of VR content and hardware may feel unprecedented; in fact, the history of VR begins over a century ago. This course will examine “reality” and the “virtual”, two long-contested terms, through the lenses of history, culture, embodiment, and space. Students will walk the boundaries of “virtual reality” through readings, screenings, workshops, and VR experiences. Through this work, students will enter the discourse surrounding VR, where they will struggle with the complicated political questions that surround VR as an art form: Who gets to define what is ‘real’ and what is not? How (and for whom) is something ‘virtual’? What kinds of rules, procedures, laws, and people should govern these strange spaces and places we call “virtual reality”? And how can VR be used not simply as a vehicle for entertainment or escape, but also a space for cultural questioning, activism, and social change? This course is connected to the Oxy Cinematheque Series that will occur during select evening course sessions.</p> <p><strong>Introduction to Game Studies and Culture</strong></p> <p>Games are changing how we create, mediate, and understand our world. This course introduces students to the interdisciplinary field of game studies with a media studies and design focus. Students will read research, play games, analyze games, and think through game design. Students will also examine issues facing gaming culture. A survey of subjects will describe the foundational theories of the field, identities and game culture, and implications/effects of gameplay. Topics to be explored include disability, education and games, cheating, sexuality and games, narratives, addiction, news games, and violence.</p> <p><strong>Who Owns the Internet?</strong></p> <p>This course takes a historical, critical, and experiential approach to the competing sets of interests that have struggled over control of the internet since its inception. These players - military, academic, corporate, activist, regulatory, user, etc. - will be explored through sets of readings, screenings, field trips, and hands-on workshops. Central to our inquiry will be questions of infrastructure, surveillance, and resistance, as they mark out the terrain, on which digital culture thrives, and, through which, major actors exert their influence. Students will have the opportunity to both learn about digital cultures and work in digital modes in this course, with hands on components emphasizing geo-spatial analysis, multimedia presentation, social media engagement, and webmaking.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10155,2025,2832,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-270','<div class="desc"> <p>Theoretical and practical investigations into processes, methods, frameworks, and considerations involved with both creating and distributing emerging cinematic media. These courses examine developing concepts, methods, and works that engage with the wide-ranging creative possibilities of emerging cinematic media practices. Topics courses may be repeated with a different topic for credit.</p> <p><strong>Virtual Worlds</strong></p> <p>A critical design course that explores emerging methods for creating 3D virtual worlds alongside examining virtual production from critical, historical, and speculative lenses. Students will learn how to conceptualize, design, and prototype simple worlds in a 3D game engine environment, and experiment with methods for layering the virtual with the real (photogrammetry capture, augmented reality). They will consider how theorists and practitioners have contended with cultural and conceptual questions raised by these practices. They can expect to engage with critical reflection, and 3D digital world-building design and virtual production processes that are introductory to intermediate, depending on their prior skill level and interest. Though game engine, 3D, or animation experience would be useful, no prior experience is necessary.</p> <p><strong>Speculative Design</strong></p> <p>A critical media design course that explores how cinematic arts practices are used to imagine alternative futures and presents. Students will be introduced to methods from the field of future studies for analyzing possible futures based on real-world trends. Their analysis will inform the creation of a series of cinematic arts projects to visualize these imagined futures and to engage viewers in conversations about them. Students will be introduced to critical design prototyping practices using digital collage, illustration, and video. Special emphasis will be placed on studying and creating fictions that speculate on futures that are heavily impacted by both climate and media technology change (generative AI, mixed reality). Collaborative worldbuilding methods will be used to imagine multiple facets of these futures from interdisciplinary lenses (health and well-being, politics and social structures, physical/virtual private and public space, communications, aging, etc.). No prior media or art experience is required or expected.</p> <p><strong>Worldbuilding Design</strong></p> <p>This course explores emerging methods of narrative design in relationship to worldbuilding. Worldbuilding refers to designing a complex integrated system with many moving parts such as characters, settings, myths, rules, artifacts â often a whole system of a society and culture. These design methods are used throughout media forms ranging from narrative writing, filmmaking, theater, architecture, mobile apps, video games, and virtual reality, to the integrated use of multiple forms using transmedia storytelling. Students will create short projects that investigate relationships between the design of a world and the storytelling possibilities that emerge from and are embedded within it, using both analog and digital methods. Students will experiment with methods and concepts such as non-linear storytelling, interactivity, experience design, transmedia, the poetics of space, and other relevant topics. Readings and short screenings will contextualize hands-on-work within larger historical and cultural contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10156,2025,2902,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10157,2025,2456,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-295','<div class="desc"> <p>The study of film and media has involved disciplinary and interdisciplinary approaches for about half a century. This intermediate topical course of varying emphases studies the key critical terms, issues, and debates in popular media cultural study, including genre study, in relation to specific topics. Readings of film and media examples illustrate how different theories or perspectives can be applied to contemporary pop culture.</p> <p><strong>It Ainât Simply a Song and Dance: Reflections of Hollywood Musicals</strong></p> <p>Hollywood musicals can bring stage to screen and serve as a platform to explore historical, cultural, and social contexts through song and dance. The narrative and spectacle in the musical genre provide a space to examine multiple aspects of film theory that include representations of race, gender, class, and sexuality. This course will explore the film musical genre emergence in American cinema with considerations from global musicals. Our screenings will include musical films from Hollywood â <em>Show Boat</em> (1936), <em>West Side Story</em> (1961), <em>Cabaret</em> (1972), <em>School Daze</em> (1988) â to Brazil, <em>Black Orpheus</em> (1959); India, <em>Dharamputra</em> (1961); France, <em>Umbrellas of Cherbourg</em> (1964); and Senegal, <em>Karmen GeÃ¯</em> (2001). We will consult theories from Richard Dyer, Jane Feuer, Theodor Adorno and Hanna Eisler, and Rick Altman to complement our close examinations of the genre. Through weekly readings, screenings, and discussions, we will critically examine how film musicals use story, music, song, and dance to reflect complex perceptions of people(s) and societies. This course fulfills the Core Program Arts (CPFA) and Global Connections (CPGC) requirements.</p> <p><strong>Audiences and Spectators</strong></p> <p>Media is not only enjoyed by solitary viewers, but also by communities of people who come together to celebrate their love of culture. Across the 20th and 21st centuries, media fans have formed clubs, written amateur publications, altered their appearances, and made parodies of their favorite movies and TV shows as ways to express their fandom. This course will explore how audiences have taken pleasure in film, television, and contemporary digital media. Students will examine moving images in a variety of technological formats and exhibition contexts to study how communities of viewers have developed vibrant fan cultures around popular media. Students will also learn how media spectatorship has been structured by racial segregation, class-based accessibility, and other vectors of social inequity. Course screenings will include: <em>The Last Picture Show</em>; <em>Goodbye, Dragon Inn</em>; <em>The Watermelon Woman</em>; and <em>Dawson City: Frozen Time;</em> in addition to user-generated content on platforms such as YouTube, Vine, and TikTok.</p> <p><strong>Media and Your Body</strong></p> <p>Media forms require us to be spectators, audiences, and increasingly, users and participants, in ways that distinctly implicate and impact our bodies and identities. The course examines the nature of bodies, spaces, and materiality in media, specifically examining prominent theories and analyses that illuminate the nature of media as it exists off of the screen. The course will survey how we interact with media in different spaces and how our bodies form a part of the media experience. Specific topics include mobile games, humor and riffing with movies, participatory media, materialism, haptics, television spaces in the home and beyond, disability media studies, performing sexuality, and mental illness and video games. Assignments will engage students in practicing the theories they learn in class.</p> <p><strong>Genre in Contemporary Film, TV, and Digital Media</strong></p> <p>Genre films were part of Classic Hollywood, but genres started changing in interesting ways as media industries evolved after World War II, with the introduction of television, new technologies that enabled shooting on location or new opportunities with color film, the rise of drive-in movie theaters, and indie or exploitation filmmaking. We will study the shift from classic genre films and theory to hybrid genres and genre revisionism in film/media movements spearheaded by people of color, feminists, and LGBT communities, as well as studios. The focus in the class is on genre theory studied through historical and technological shifts in media production. Screenings will introduce a range of genres, from classic films like the Western and noir to more recent genres like road films, television melodramas, and war video games.</p> <p><strong>Imagining War: Genre on Screen and Battlefield</strong></p> <p>The war film has arguably been one of the most consistent and popular elements of cinema''s history. It was a component of film from its beginnings and is now a regular mainstay amongst Hollywood blockbusters. It has also undergone several political revisions and technological shifts in media production, distribution and exhibition, making it ideally suited to study the theory and history of genre. Importantly, this course will not only look at how war figures in film, but how film also profoundly effects and configures war. Entertainment and war are the United States'' primary exports. Militarism and the Hollywood studio system have had a long and deadly interdependence. By conceiving of the viewing screen as an extension of the battlefield (and vice versa), this course will look at the profound social and political implications of the classic genre system. We will do this by examining such films as <em>Apocalypse Now, The Deer Hunter, Hiroshima Mon Amour, Battle of Algiers, Black Hawk Down, Kandahar, Night and Fog, The Hurt Locker. Das Boot, Saving Private Ryan, All Quiet on the Western Front, Dr. Strangelove, Inglourious Basterds, Birth of a Nation, Rambo, MASH</em>, as well as a host of television shows, websites, and video games</p> <p><strong>The Western: From Colonialism to Gaming</strong></p> <p>This course will primarily explore the classic Hollywood genre system through a detailed look at "The Western." However, before looking at how genre operates within cinema, we take a broad historical and theoretical examination of genre within literary studies, critical theory, Wild West shows, philosophy, travel literature, ethnographic photography, and cultural studies. The aim is to critically examine a wide array of generic conventions within "The Western" film, while simultaneously situating these conventions within the broader historical and ideological context of European colonization of North America. Particular attention will be placed on the role of racial and gender performances within "The Western" genre as both a founding American myth and a component of the Hollywood film system. We will analyze both the classic Western as well as revisionist films. Additionally, we will investigate how the genre transforms as it moves into other media, including fine art, television, gaming, and other digital contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10158,2025,3842,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-296','<div class="desc"> <p><strong>Topic for Fall 2024: Subversive Art and Media</strong></p> <p>An 8-unit course on the ways visual artists challenge and critique dominant systems of power, and catalyze movements of social change . We will explore how photography, film, visual and media arts play powerful roles in shaping liberatory and empowering narratives in the present, as well as reimagining, reconstructing, and reclaiming histories of the past. Through readings, discussions, writing, and art practice, students will center questions of power, belonging, exclusion, visibility and invisibility among others. Students will also engage in collaborative projects and studio visits with artists, filmmakers, curators, historians, and media makers in LA/the US, South/Southeast Asia, Mexico, and Europe. Finally, students will create a final visual media social justice project. By the end of the immersive, students will have gained critical skills in discussion, research, and writing alongside creative skills in visual media making. This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,'First-Year Seminar: FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(10160,2025,1710,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-320','<div class="desc"> <p>This course emphasizes the advanced design and writing of screenplays and long-form narratives for film and other audiovisual time-based media forms. Through a combination of screenings, critical readings, and creative exercises, students will develop a treatment for a long-form narrative screen work and commence writing scenes for its first act. May repeated once for credit.</p> </div>','MAC 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10161,2025,1711,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-355','<div class="desc"> <div><p>This is a required course for all MAC juniors in the Media Production Concentration. It provides advanced study and hands-on experience in the ideation and production of digital media projects across a range of fictional, documentary, and experimental modes. Students engage in a combination of readings, screenings, technical workshops, and collaborative media production projects to prepare them for the Media Production Senior Comprehensives experience. This class is not open to Frosh or Sophomore MAC majors even if they have taken the MAC 240 pre-requisite.<br/> </p></div> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10162,2025,1712,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-390','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors. Fulfilling the College’s Second-Stage Writing Requirement, this is a research-driven course which brings together all junior majors, regardless of the intended form of their senior comprehensives project, to read, watch, write, debate, and produce self-directed research, laying the groundwork for their senior year comprehensives projects. This class is only open to junior MAC majors. </p> </div>','Two gateway classes (from MAC 143 , MAC 145 , MAC 146 ) must be completed with grades of C+ or better ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10163,2025,3661,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-393','<div class="desc"> <div><div><p>Advanced-level, faculty-supervised research project in the discipline. Permission of instructor and department chair required, and will be provided only after approval via this departmental MAC 393 Directed Research Contract.</p><p><br/></p><p>May be taken as 2 or 4 units, and must be taken for a letter grade. A maximum of 8 MAC 393 Directed Research Units may be applied to student''s academic record without a petition.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10166,2025,1538,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-490','<div class="desc"> <p></p> <p>Advanced fall-semester course designed to provide guidance and intellectual community around the development and advancement of a Critical Media comprehensives project.</p> <p></p> </div>','MAC 390 and two courses from MAC 241 , MAC 244 , MAC 246 , MAC 248 , MAC 250 , MAC 252 , MAC 260 , MAC 295 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10167,2025,1539,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-491','<div class="desc"> <p>Advanced fall-semester course designed for the collaborative development and photography of Media Production comprehensive projects. Permission of instructor required.</p> </div>','MAC 355 , MAC 390 , and if making a fiction project MAC 220. Permission of instructor required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10168,2025,1713,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-492','<div class="desc"> <p>This course provides technical training in a range of post-production software platforms, best practices in sound and picture editing, and skills in post-production finishing/project delivery workflow. The course also provides professionalization tools, training students in development and production of media portfolio materials.</p> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10169,2025,3282,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-493','<div class="desc"> <p>Students conduct and or complete faculty supervised research for eventual presentation, whether a paper, formal publication, demonstration/performance, or screening. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10172,2025,229,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/copy-of-math-105','<div class="desc"> <p>This is a topics course for students who would like to take a mathematics course that does not require taking any prior course in college-level mathematics. Topics may be chosen from the selection below.</p> <p> <strong>Digital Security</strong></p> <p>In this course we will explore the world of digital security and the math that goes into keeping your information safe. Topics will include cryptography, hash functions, blockchain, and bitcoin.</p> <p><strong>Mathematical Thinking</strong></p> <p>Introduction to mathematical thinking. Investigation of mathematical patterns in counting, reasoning, motion and change, shape, symmetry, and position.</p> <p><strong>The Science Of Patterns</strong></p> <p>This course is a whirlwind tour of some of the greatest hits in mathematics: number, geometry, logic, algebra, symmetry, calculus, infinity, and more. This course endeavors to instill in students an appreciation for mathematics as "the science of patterns."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10173,2025,230,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-108','<div class="desc"> <p>The first of a two course sequence enriching the material in Calculus 1 with additional study of elementary functions, algebra, trigonometry, graphing, and mathematical expression. Weekly lab.</p> </div>','Calculus Placement Exam ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10174,2025,642,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-109','<div class="desc"> <p>Continuation of MATH 108. This course satisfies Calculus 1 prerequisites for subsequent courses. Weekly lab.</p> </div>','MATH 108 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10175,2025,232,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-110','<div class="desc"> <p>This is a first-semester course in calculus covering single-variable differential calculus. Topics include limits, continuity, differentiation, differentiation rules, as well as applications to the natural and social sciences, including optimization. Click here for a more detailed topics list. Weekly lab required.</p> </div>','Calculus Placement Exam ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10176,2025,234,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-114','<div class="desc"> <p>This course is a more in-depth version of Mathematics 110. Intended for students interested in more mathematical rigor; recommended for students who expect to take mathematics courses beyond Calculus. It satisfies Calculus 1 prerequisites for subsequent courses. Weekly lab.<br/> <em></em></p> </div>','Math Placement Examination ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10177,2025,236,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-120','<div class="desc"> <p>This is a second-semester Calculus course in integral calculus and infinite series. The topics will include integration, methods of evaluating integrals, sequences, series, and Taylor series. Applications to the natural and social sciences will be included. Click here for a more detailed topics list. Weekly lab required.</p> </div>','MATH 109 , MATH 110 , or MATH 114 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10178,2025,238,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-128','<div class="desc"> <p>A one-semester course focusing on infinite sequences and series including power series and Taylor series. More advanced topics will be chosen by the professor which may include: techniques for solving differential equations mathematical modeling, Fourier Series, the Laplace Transform, and the Fourier Transform. The course assumes mastery of the basic skills, particularly integration techniques and differentiation rules from the successful completion of Advanced Placement (AB) Calculus. This course satisfies Calculus 1 and Calculus 2 prerequisites for subsequent courses. Weekly lab.</p> </div>','Permission of instructor or AP Calculus AB score of 4 or 5 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10179,2025,242,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-150','<div class="desc"> <p>An introductory course in statistics, emphasizing modern techniques of data analysis. Exploratory data analysis and graphical methods; random variables, statistical distributions, and linear models; classical, robust, and nonparametric methods for estimation and hypothesis testing; introduction to modern multivariate methods. Students will make significant use of a computer application specifically designed for data exploration. The course is strongly recommended for students who are going to use graphical techniques and statistics for research in their fields. Weekly lab.</p> </div>','Calculus 1 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10180,2025,243,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-160','<div class="desc"> <p>Formal and informal techniques for problem-solving developed by working on an intriguing collection of puzzles and problems which go beyond those encountered in the usual curriculum. These include problems which can be posed in elementary, mathematical, or logical terms, but which require strategy and ingenuity to solve.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10182,2025,858,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/100/math-195','<div class="desc"> <p>Topics in mathematics selected largely by student interest and faculty agreement. Instructor permission required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10184,2025,244,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/200/math-201','<div class="desc"> <p>This seminar course is a writing-intensive Community Based Learning course designed to expose students to the complicated ways in which mathematics affects the community. The CBL component of this course involves tutoring and mathematics assistance at Franklin High School in nearby Highland Park. The seminar component involves meeting weekly with processing discussions and discussion of readings. Topics will include the teaching and learning of mathematics, as well as the role of mathematics in individuals'' lives and their community. May be taken twice for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10185,2025,245,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/200/math-210','<div class="desc"> <p>This course is an introduction to proofs course centered around discrete mathematics. Topics include: The language of sets and logic, including propositional and predicate calculus, formal and informal proofs using truth tables, formal rules of inference, and mathematical induction; Congruences and modular arithmetic; Elementary counting techniques; and Abstract relations, including equivalence relations. Click here for a more detailed topics list.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10186,2025,3241,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/200/math-211','<div class="desc"> <p>This course will cover the main topics of MATH 210 Discrete Mathematics (logic, proofs, functions, sets, modular arithmetic, basic combinatorics, etc.), but through the lens of cryptography. The topics will be presented under the umbrella of learning about cryptography. We will cover topics such as affine ciphers, Enigma, RSA encryption, elliptic curve cryptography, etc.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10187,2025,246,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/200/math-212','<div class="desc"> <p>This is a third-semester Calculus course in multiple variables. The topics in this course include: calculus of functions of several variables, parametric curves and surfaces; vector fields in 2- and 3-space with applications; contour plots; applications to optimization and Lagrange multipliers; multiple and iterated integrals; line integrals; gradient, divergence, curl; and Green''s Theorem. Applications to physics, economics, chemistry and mathematics are included. Click here for a more detailed topics list. </p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10188,2025,247,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/200/math-214','<div class="desc"> <p>Introduction to basic concepts of linear algebra through the study of linear algebraic systems and matrix algebra. Topics include: an introduction to planes and lines, vector operations, subspaces, Gaussian elimination, linear independence, invertibility of matrices, orthogonality, matrix operations, eigenvalues, and eigenspaces. Click here for a more detailed topics list.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10191,2025,1181,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/200/math-295','<div class="desc"> <p>Topics in mathematics selected largely by student interest and faculty agreement.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10193,2025,644,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-300','<div class="desc"> <p>This course is designed for mathematics majors to satisfy the college-wide Second Stage Writing Requirement and to demonstrate readiness for advancement in the major. The course emphasizes clearly written expression and oral communication in mathematics. Restricted to mathematics majors. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10194,2025,248,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-310','<div class="desc"> <p>A beginning course in advanced calculus and real analysis. Properties of the real number system, sequences and series of real numbers, the Heine-Borel and Bolzano-Weierstrass Theorems, continuity and uniform continuity sequences, and series of functions.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10195,2025,645,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-312','<div class="desc"> <p>The differential and integral calculus of complex-valued functions of a complex variable, emphasizing geometry and applications. The complex number system, analytic functions and the Cauchy-Riemann equations, elementary functions and conformal mappings, contour integration, Taylor and Laurent series, function theory. Applications to physics, engineering, and real analysis.</p> </div>','MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10196,2025,949,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-320','<div class="desc"> <p>A first course in abstract algebra. Topics will be chosen from group theory (basic axioms and theorems concerning subgroups, cosets, normal subgroups, group homomorphisms), ring theory (basic axioms and theorems concerning subrings, ideals, ring homomorphisms, quotient rings), and field theory. Applications to areas such as chemistry, coding theory, and cryptography may be included. </p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10197,2025,646,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-322','<div class="desc"> <p>Introductory course in elementary number theory. Prime numbers, modular arithmetic, linear congruences, primitive roots, quadratic reciprocity, continued fractions and Pell''s equation, and applications to cryptography. Open problems in number theory will also be introduced.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10198,2025,249,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-330','<div class="desc"> <p>Standard methods of calculus are used to study probability: sample spaces, random variables, distribution theory, estimating unknown parameters of distributions. Various applications to real life problems will be discussed. Moment-generating functions and other techniques to calculate moments and characterize distributions. Probabilistic inequalities and the central limit theorem. Point estimators and unbiasedness.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10199,2025,647,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-332','<div class="desc"> <p>Theory and applications of statistical inference. Both Bayesian and classical parametric methods are considered. Point and interval estimation, hypothesis testing. Limit theorems and their use in approximation, maximum likelihood estimation, and the generalized likelihood ratio test. Introduction to linear models, nonparametric methods, and decision theory.</p> </div>','MATH 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10200,2025,1388,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-340','<div class="desc"> <p>This course will focus on theoretical qualitative and quantitative analyses of ordinary differential equations, from a modern perspective, using analytical, graphical, and numerical points of view. Topics can include: first-order linear and nonlinear differential equations, first order linear systems, second-order linear differential equations, autonomous differential equations and their bifurcations boundary value, problems solutions using infinite series, Laplace transforms, and various numerical approximation techniques.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10201,2025,648,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-342','<div class="desc"> <p>An introduction to the study of partial differential equations. This course will include the study of Fourier series; the separation of variables methods; and specifically, the wave, heat, and Laplace''s equations, as well as other elementary topics is PDEs. Numerical approximation techniques and applications to specific topics such as traffic flow, dispersive waves, or other areas may be included. Given in alternate years.</p> </div>','MATH 212 , MATH 214 , and MATH 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10203,2025,950,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-354','<div class="desc"> <p>Cantor''s naïve theory of sets and equinumerosity. Paradoxes and axiomatic set theory. Finite and infinite cardinal numbers, fixed point theory, applications to computer science. Well orderings, transfinite induction and recursion, the Axiom of Choice and its consequences, ordinal numbers, and the cumulative hierarchy of sets. Discussion of the Continuum Hypothesis and its relation to models of set theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10204,2025,1182,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-360','<div class="desc"> <p>Axiomatic development of Euclidian and non-Euclidian geometries, including neutral and hyperbolic geometries, and possibly brief introductions to elliptic and projective geometries. The course will emphasize a rigorous and axiomatic approach to geometry and consequences of Euclid''s Parallel Postulate and its negations.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10205,2025,859,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-362','<div class="desc"> <p>General topology studies those properties (such as connectedness and compactness) which are preserved by continuous mappings. A disk and a solid square are topologically equivalent; so are a doughnut and a coffee cup; but a disk is different from a doughnut. This course enables you to construct your own proofs and counterexamples while getting to know the basic concepts behind modern mathematics.</p> </div>','MATH 210 , and MATH 212 or MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10206,2025,251,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-370','<div class="desc"> <p>This is a first course in studying numerical techniques in solving a variety of problems in mathematics using computer algorithms. Topics can include: methods for approximating solutions to algebraic equations, iterative methods for linear and nonlinear systems, interpolation and approximation, theory numerical integration, explicit and implicit methods for solving initial value problems, and boundary value problems. Error, estimation, stability, and performance are themes throughout. Students will be expected to be able to execute standard algorithms using a computer programming language by the end of the course.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10207,2025,951,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-372','<div class="desc"> <p>Optimal decision-making and modeling of deterministic and stochastic systems. Different systems of constraints lead to different methods. Linear integer dynamic programming and combinatorial algorithms. Practical problems from economics and game theory. Inventory strategies and stochastic models are analyzed by queuing theory.</p> </div>','MATH 210 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10208,2025,3910,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-374','<div class="desc"> <p>This is a topics course designed to provide depth in a variety of areas of computational mathematics. We will investigate complex mathematical problems, models and simulations, combined with related computer algorithms and advanced tools, used to generate solutions for these problems. Such problems come from a variety of areas in mathematics such as stochastic forecasting, large scale data problems, advanced numerical methods for ordinary and partial differential equations, matrix analysis as well as from other disciplines such as Biology, Economics, Physics, etc. Prerequisite: Math 274</p> <p>May be repeated for up to four units of credit.</p> </div>','Math 274 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10209,2025,952,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-380','<div class="desc"> <p>Investigation of the existence and classification of arrangements. Topics to include: principles of enumeration, inclusion-exclusion, the pigeon-hole principle, Ramsey theory, generating functions, special counting sequences, and introductory graph theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10210,2025,1075,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-382','<div class="desc"> <p>Graph Theory is a beautiful area of mathematics with many applications. It is used in computer science, biology, urban planning, and many other contexts. Like other areas of discrete mathematics, Graph Theory has the property that the problems are often quite approachable and understandable. Sometimes the solutions to Graph Theory problems can be complex and often require clever arguments, thus the subject is quite pleasing to study. This class will build a solid foundation in Graph Theory for the students. Possible topics are: graph isomorphisms, coverings, and colorings; independence number, clique number, connectivity, network flows, and matching theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10212,2025,252,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-395','<div class="desc"> <p>Special topics in advanced mathematics selected largely by student interest and faculty agreement. May be repeated for credit. </p> <p><strong>Advanced Differential Equations </strong></p> <p>The course will consist of advanced topics in differential equations not usually seen in either ordinary differential equations or partial differential equations, such as: delay differential equations and stochastic differential equations. Boundary value problems, numerical methods, and infinite series solutions. <em>Prerequisite: MATH 340 or MATH 342 or permission of instructor. </em></p> <p><strong>Galois Theory</strong></p> <p>One learns in a first course in algebra that given an equation of the form ax^2 + bx + c = 0, one can always find solutions using the quadratic formula. It is considerably harder to find comparable formulas to solve equations of this form if one allows degree 3 or degree 4 polynomials, but mathematicians found formulas for these in the 16th century. It remained a mystery if one could solve an equation of the form f(x) = 0 if f(x) is a degree 5 polynomial until the work of a young mathematician named Evariste Galois in the early 19th century. Unfortunately, Galois died in a duel at 21 years old without anyone accepting or understanding his work. Galois proved that there is no formula to solve (in radicals) an equation of the form f(x) =0 for f(x) a general polynomial of degree 5 or higher. The ultimate goal of this course will be to prove this result, but along the way it is necessary to develop the theory of rings, fields, and the connection between groups and field extensions known as Galois Theory. It is possible to take this course concurrently with Math 320.</p> <p><strong>History of Mathematics </strong></p> <p>This seminar course is a survey of selected topics from the history of mathematics. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the development and developers of mathematics in the past and present. The primary objective of the course is for students to synthesize various mathematical ideas from fundamental and advanced mathematics courses as a capstone experience for the major. Students will complete a project about an advanced mathematical topic with presentations in written and oral form at the end of the course. <em>This course satisfies the Core Program Requirement: Pre-1800 (CPPE).</em> <em>Prerequisite: Any 300-level Mathematics course (may be taken concurrently) or permission of instructor.</em></p> <p><strong>Knot Theory</strong></p> <p>How knots are described mathematically, how one can distinguish different knots, create new knots, classify knots. Topics include: Reidemeister moves, links, knot colorings, alternating knots, braids, knots and graphs, knot invariants, mirror images, unknotting, number crossing, number applications to biology and chemistry. <em>Prerequisite: MATH 210, MATH 212, or MATH 214 or permission of instructor.</em></p> <p><strong>Real Analysis II (Metric spaces and Lebesgueâs measure theory)</strong></p> <p>This course serves as a sequel to MATH 310 Real Analysis. The first part of this course will cover the main topics surrounding the topology, theory, and applications of metric spaces and their morphisms. In particular we will study certain function spaces that arise as normed vector spaces. Completeness, separability, compactness, and connectedness are some of the themes that will appear throughout the course. Fundamental results in Analysis such as the Heine-Borel Theorem, the Baire Category Theorem, the Bernstein Approximation Theorem, the Stone-Weierstrass Theorem, and the Arzela-Ascoli Theorem will be proved and applied. The second part of this class will be devoted to developing the Lebesgue measure on the real line and the Lebesgue integral along with powerful convergence theorems. Time permitting we will study some Fourier series. <em>Prerequisite: MATH 310 or permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10213,2025,1461,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-396','<div class="desc"> <p>This course which will cover various topics in applied mathematics. This course may be repeated once for credit.</p> <p><strong>Computational Mathematics (4 units)</strong></p> <p>This course investigates the enhanced problem solving techniques realized by the incorporation of the computer and well designed algorithms. We note that in the real world, mathematicians are asked to solve problems vastly more complex than those found in a homework set or final exam. The types of such problems are numerous: problems which are non-linear in nature, large systems of many equations rather than a few, problems which attempt to identify an infinite number of solutions, problems for which only approximate solutions are possible, and much more. We start by noting the basics of how the computer processes data and the fundamentals of decision making, iteration, and memory. We apply this to problems in various areas of mathematics and science. Often, we''ll make substantial headway, but run into some limitations only to find that some obscure mathematical property comes to the rescue and allows us to "upgrade" our process to obtain dramatically more or better solutions. Our overall course philosophy favors neither mathematics or computational tools, but the way in which these tools work together to produce amazing results!</p> <p><strong>Industrial Mathematics (2 units)</strong><br/> This course is a project-oriented introduction to industrial mathematics. Students will be grouped into teams and tasked with creating solutions to actual real-world problems provided by external partners from business, industry and government. Familiarity with a programming language is highly desirable but not required. The goal of this course is to provide students with an experience of what it is like to work as a mathematician in a professional setting.</p> <p><strong>Mathematical Modeling (2 units)</strong><br/> This course is a project-oriented seminar in mathematical modeling. Concepts from calculus, linear algebra, differential equations and other areas of mathematics will be used to derive, describe and solve mathematical models from the life, physical, and social sciences. Familiarity with a programming language is desirable but not required. The goal of this course is to provide students with multiple examples of how mathematics can be used to explain various phenomena, to describe real-world situations and to make (more quantitatively) informed decisions.</p> <p><strong>Applied Mathematics (2 units)</strong><br/> This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10214,2025,649,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/300/math-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10215,2025,253,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/400/math-400','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Applications of Graph Theory</strong></p> <p>We will learn a selection of interesting results in graph theory, together with their wide-ranging applications. Prior familiarity with graph theory is helpful but not required; necessary concepts and definitions from graph theory will be covered.</p> <p><strong>Applied Mathematics</strong></p> <p>This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> <p><strong>Cryptology</strong></p> <p>Cryptology is the study of sending secret messages over insecure communication channels. Cryptographic capabilities are important to politics and foreign affairs, and underlie the functioning of a great deal of the modern economy. In this course we will study the mathematical theories and techniques that make cryptography function, and also those that break it. We will learn how these mathematical tools influence the use of cryptographic systems, and practice explaining these implications to people without developed mathematical backgrounds.</p> <p><strong>History of Mathematics (Euler to Uhlenbeck)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Spring semester seminar will cover Euler to Mirzhakani and Uhlenbeck. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>History of Mathematics (Euclid to Newton)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Fall semester seminar will (roughly) cover Euclid to Leibnitz and Newton. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>Introduction to Knot Theory</strong></p> <p>We learn how mathematics is used to understand knots and links, covering topics such as prime and composite knots, knot colorability and other invariants, and links in graphs.</p> <p><strong>Introductory Algebraic Number Theory</strong> </p> <p>One of the most basic facts in all of mathematics is the Fundamental Theorem of Arithmetic: given a positive integer <img alt="n" src="https://ci4.googleusercontent.com/proxy/YC8nj2e8yBmjCq6iHNmwmKCdjEMLA1Rkg9GJ3zrI5rgl2Dm25s_TOAvkaywNnYQr_JYl-kfbaPoAk1awVJYg5EjXQffL2dYqAGm_NHlLgSa3Z5T7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09n" title="n"/>, it has a unique (up to ordering) factorization into primes. The integers are not the only interesting set of numbers to work with though. For instance, suppose you are interested in solutions to the equation <img alt="x^2 + 1 = 0" src="https://ci3.googleusercontent.com/proxy/xqcvy1KFxXc8K883M_1PDukXqcmZPm-5tB-iSAMkGkvFeFHMSOafhQR0uUvfixvpkuFdBXvok_lC_7waFw7tk0gW8wv3vqRPSjX-COISgNGMetOSfY0ffCmyU0Zq4BpjNPGK2YwXlx6nsA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091%09=%090" title="x^2 + 1 = 0"/>. This naturally leads us to consider the number <img alt="i = \sqrt{-1}" src="https://ci3.googleusercontent.com/proxy/jI9lkel1Wbpr5NOwIn5DWDtYBZ60cpzFgOtDWow484Xkd2YpuW52catXmqkkijXBDPPEeH2fk6x4MQ2-2yTaorDx5u-_pGbv5ks_d4E5C_t_scHGQDLxG6KnpH3R96QWXdRQq6ktp-8Xuw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09i%09=%09%5Csqrt%7B-1%7D" title="i = \sqrt{-1}"/> as well. We can then define a new collection of numbers called the Gaussian integers <img alt="\mathbb{Z}[i]" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" title="\mathbb{Z}[i]"/> which consist of elements of the form <img alt="a + b i" src="https://ci3.googleusercontent.com/proxy/d6zGMURoQy94P-DoTtLy93G4MB8MbHK1GInDLAorcYJkCCWM4cFLTvHUWm7k9TPC45AYf_oh-vjDQfyz97qQtaBGFVOXHEw4i7gio3uVenCYoZ148Hq_WkbUWIOPw4ef6hw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a%09%2B%09b%09i" title="a + b i"/> for <img alt="a,b \in \mathbb{Z}" src="https://ci6.googleusercontent.com/proxy/T4yrmOhXbiVysYHo65u2ng0ifI58f9fbFBHbM7FJE00vaWEiH8RIEZJB72bFauQ0qwa34Xj0I6JsGgN8seXxxvnTVCRsFaCrfX6W98sTyi-vFckX0fl8aA-HQ5IAVRdlAuYbUGWfrJKGR2lSl0LKQaM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a,b%09%5Cin%09%5Cmathbb%7BZ%7D" title="a,b \in \mathbb{Z}"/>. Given a prime <img alt="p \in \mathbb{Z}" src="https://ci5.googleusercontent.com/proxy/I91pxfAy3o71ANU93zluf4FRJbNEGbX_SHuVKVPdohW_2Wwsw-Lgsztq4vsguB5AYJHfxGA4B3-lF8Z3Wf9vpwU6hcWFTZv3BO1mgkV4qOww6Cb2ajJ35ZUq_egaIzCfFdLLVUYR8f2pL09aP6pQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D" title="p \in \mathbb{Z}"/>, we also have <img alt="p \in \mathbb{Z}[i]" src="https://ci3.googleusercontent.com/proxy/_X0boZvQHsr_aQSiVPqR6BIXlVDDGHiT4bYg4-VFaYiwAj2SRz9etcwOW-PHVF8NfxpBUeuJ2KgV1badjYAa0udYsnrsUF2BFfVyBBE3UMF1Rj8vNowRbWa4SiiuEuh9j8IcgeojBr0PlNAdaxl5cAy7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D[i]" title="p \in \mathbb{Z}[i]"/>. Is <img alt="p" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" title="p"/> still prime in <img alt="\mathbb{Z}[i]" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" title="\mathbb{Z}[i]"/>? It turns out that sometimes, but not always! For instance, in <img alt="\mathbb{Z}[i]" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" title="\mathbb{Z}[i]"/> we have <img alt="2 = (1 + i)(1 - i )" src="https://ci4.googleusercontent.com/proxy/XvwjjHBgKnD2a36lesGEq1IkFArJpjXtTykglqE2EaWNBlM9_xg03JuwnNtjGawD0g8n7QvoWgwh0pmM6lceriWU9WXg1sBmtIfdlM6JSu5uMmM_t6F4oOAy0L7mm1LgnpxILKTxKFp-G3huy6k9DSkKdcdKLQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%092%09=%09(1%09%2B%09i)(1%09-%09i%09)" title="2 = (1 + i)(1 - i )"/> and <img alt="5 = (2 + i) (2 - i)" src="https://ci4.googleusercontent.com/proxy/FyVZr4VzL5yrRbSosqkqGx04BmK6zUcoqlCLddJPUxekXPW72sf-MpLR9B9lbMIdAqpHod1zFvoBVn0d4FaWXAABuCsa8KVM2RwNcTEFBrWHh230o_Yk-l_LQEcrvyNOIfwOXU53fdiRTvUTLUTe5B3slXa1sA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%095%09=%09(2%09%2B%09i)%09(2%09-%09i)" title="5 = (2 + i) (2 - i)"/>, but <img alt="3" src="https://ci6.googleusercontent.com/proxy/Er5UHWmuvViTqmbNTtg07Zo3TDld1PrKGZFpM1g1IYsbUxVg42LXa42yahDQowN9d1uGeAObmZqSYE6hywCYmc-qr5momXJ3Q9fqmsmt7t2msGmt=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%093" title="3"/> is still prime! This fact is related to writing <img alt="p" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" title="p"/> as a sum of two squares as well as how the polynomial <img alt="x^2 + 1" src="https://ci5.googleusercontent.com/proxy/O9U18DGHuRvAsqi0RA0hDNN3XN_cNoMh5A0X7XL4tEHMlZY45-T6w2Qf07anETTar4klaWwUOHcUdnWp5LQ2J3bAjhXiPRgi-45NwXEBc5Z2C7CwaVEmfvjIspVx6wcFjiM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091" title="x^2 + 1"/> factors when considered modulo <img alt="p" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" title="p"/>. The study of how primes factor when considered in larger rings is referred to as algebraic number theory. In this course we will study algebraic number theory for the simplest cases of <img alt="\mathbb{Z}[i]" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" title="\mathbb{Z}[i]"/> and possibly other rings of the form <img alt="\mathbb{Z}[\sqrt{d}]" src="https://ci3.googleusercontent.com/proxy/fykrb_Z6FYHa1OHSUz6l_6Ccl38TddheOZ5XqwFQDiTJtyJBJ2qrWG0-ZBvP45qpMtA0PEp7ENHRM7_NY_hSV-uPy-AwOGApOXctS2cmUXG322diPJNjCmvCdBrHDWjgJVN5jBXvfgSUS6PS8y57cGrr6A=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[%5Csqrt%7Bd%7D]" title="\mathbb{Z}[\sqrt{d}]"/> to see the underpinnings of the overall vast theory. </p> <p><strong>Mathematical Applications of Linear Algebra</strong></p> <p>We will use the book Thirty-three Miniatures: Mathematical and Algorithmic Applications of Linear Algebra, by JiÅì Matoušek. We will concentrate mostly on the mathematical applications (as opposed to the algorithmic applications). In the first two class meetings we will learn about (generalized) vector spaces, as preparation for the remainder of the course.</p> <p><strong>Mathematical and Scientific Computing</strong></p> <p>This course is an introduction to the field of Mathematical and Scientific Computing. As such, we will investigate complex mathematical problems, models and simulations, combined with related computer algorithms and advanced tools, used to generate solutions for these problems. Such problems come from a variety of areas in mathematics, as well as from Biology, Economics, and more. Topics include very large and very precise numbers, measures of algorithmic efficiency, a variety of programming languages and platforms, memory – speed tradeoffs, and more.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10216,2025,2556,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/400/math-401','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Cryptology</strong></p> <p>Cryptology is the study of sending secret messages over insecure communication channels. Cryptographic capabilities are important to politics and foreign affairs, and underlie the functioning of a great deal of the modern economy. In this course we will study the mathematical theories and techniques that make cryptography function, and also those that break it. We will learn how these mathematical tools influence the use of cryptographic systems, and practice explaining these implications to people without developed mathematical backgrounds.</p> <p><strong>Applications of Linear Algebra</strong></p> <p>We will use the book Thirty-three Miniatures: Mathematical and Algorithmic Applications of Linear Algebra, by JiÅì Matoušek. We will concentrate mostly on the mathematical applications (as opposed to the algorithmic applications). In the first two class meetings we will learn about (generalized) vector spaces, as preparation for the remainder of the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10218,2025,650,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/math-mathematics/400/math-499','<div class="desc"> <p>Students who have been accepted by the Department to do honors should register for MATH 499, in lieu of MATH 400. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10219,2025,1243,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/100/musa-103','<div class="desc"> <p>An introduction to classical guitar including, basic technique and musicianship. The traditional repertoire as well as 20th century and flamenco will be explored. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10220,2025,1244,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/100/musa-104','<div class="desc"> <p>A further exploration of classical guitar, with emphasis on a thorough treatment of musicianship, technique, and expansion of the repertoire for the guitar soloist.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10221,2025,1245,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/100/musa-105','<div class="desc"> <p>The Alexander Technique helps students move naturally. They learn to prevent excess tension and replace it with a more effectively balanced movement pattern throughout the body. Does not satisfy Music Major applied music requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10222,2025,2503,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/100/musa-106','<div class="desc"> <p>Basic ukulele technique at the beginning through lower intermediate level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10223,2025,1246,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-201','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing/singing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
