INSERT INTO course_descriptions VALUES(10276,2025,1545,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-278','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique and awareness of and proficiency in different styles of playing. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10277,2025,2504,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-279','<div class="desc"> <p>Private, one-on-one weekly lessons. Advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10278,2025,2505,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-280','<div class="desc"> <p>Private, one-on-one weekly lessons. Advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10279,2025,2817,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-281','<div class="desc"> <p>Beginning to advanced instruction in drum set performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10280,2025,2818,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-282','<div class="desc"> <p>Beginning to advanced instruction in drum set performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10281,2025,3288,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-283','<div class="desc"> <p>One-on-one lessons geared toward the individual student. Classic pop and rock material will be used for learning fundamental music skills, including the following: performance technique, chords, scales and modes, fretboard awareness, improvisation, theory and reading. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10282,2025,3289,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musa-music-applied-study/200/musa-284','<div class="desc"> <p>One-on-one lessons geared toward the individual student. Classic pop and rock material will be used for learning fundamental music skills, including the following: performance technique, chords, scales and modes, fretboard awareness, improvisation, theory and reading. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10283,2025,652,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/copy-of-musc-105','<div class="desc"> <p>Topics vary semester by semester. No prior musical experience required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10284,2025,653,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/copy-of-musc-111','<div class="desc"> <p>This course will survey the evolution of jazz from its roots to the present. We will analyze the influence of peoples of various cultures on repertoire, jazz techniques, and styles. Special attention will be paid to some of the more important and influential performers. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10285,2025,255,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-101','<div class="desc"> <p>This course begins the music theory sequence by covering the basic techniques of music, and is designed for both students with no previous musical training and students with substantial performance experience. Topics will include notation, melody, harmony, rhythm, meter, key, scales, modes, intervals, triads, seventh chords, and structural elements of music. Introductory exercises in composition of popular, jazz, and classical genres will be explored. The music studied will be chosen in collaboration with students and Music Department colleagues. This course includes both a lecture and a lab section, which focuses on developing listening and musicianship skills. Successful completion of the Music Theory Placement Exam may allow students to pass directly into MUSC 151 Music Theory II.</p> </div>',NULL,'Students enrolled in MUSC 101 must be co-enrolled in a section of MUSC 101A. ',NULL);
INSERT INTO course_descriptions VALUES(10286,2025,257,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-103','<div class="desc"> <p>This course surveys the musical styles and genres of Asia from India through the southeastern part of the continent and includes the countries and islands of the Pacific. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. Where appropriate distinctions will be made between classical and folk genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10287,2025,953,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-104','<div class="desc"> <p>This course surveys the musical styles and genres of the African continent and the Middle Eastern world. Within an ethno-historical framework established at the beginning of the course emphasis is placed on 1) the region''s important musical genres their social function and musical characteristics and 2) the instruments used in performing these musical genres. While knowledge of music theory and performance skills are not necessary it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10288,2025,2856,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-106','<div class="desc"> <p>This course teaches the fundamentals of singing: voice production, breathing, range, song selection, and performance. Students will learn and perform three solo songs during the course of the semester. Recommended as preparation for private lessons. Graded on a Credit/No Credit basis only. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10289,2025,2558,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-107','<div class="desc"> <p>This course involves in-depth exploration, practice, and application of vocal techniques for the more experienced singer plus an emphasis on advanced aspects of performance. Students will learn and perform three solo songs during the course of the semester. Culminates in a final recital. Recommended as a supplement to private lessons. May be repeated three times for credit. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10290,2025,2349,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-108','<div class="desc"> <p>This course will survey the development of folk and popular music in Europe, including the music of the Balkans, the Baltic States, the Celtic region, the Iberian Peninsula, and the Mediterranean. We will examine how this music has served nationalist agendas, and how media and marketing have shaped the ways in which this music is understood. As most of this music involves dance, the study of dance will be an integral part of this course. Students must be prepared for intensive listening assignments, in and out of class. Prior musical experience or knowledge not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10291,2025,2707,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-109','<div class="desc"> <p>The goal of this course is to introduce students to the piano and help them develop basic performance skills, teaching them how to play introductory-level pieces in a variety of classical and popular styles. Along the way, students will learn to read sheet music, and develop a command of other music fundamentals including note names, scales, counting beats, efficient physical motion, and basic ideas about phrasing and flow. Piano Class is intended for non-majors without previous piano training; Music majors should take MUSC 101, MUSC 231, or MUSC 232, or individual piano lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10292,2025,1715,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-113','<div class="desc"> <p>Composing, improvising, listening, and performing all embody aspects of music-making. This course examines compositional methods of contemporary composers. We will focus on hands-on composing in a broad range of styles. Additionally, students will learn about all of the instruments of the orchestra (range, characteristics, timbre, etc.). In-class listening will supplement bi-weekly listening assignments covering orchestral music from the Baroque to the present. Students will learn to develop musical ideas through notational methods that can effectively be realized by performers. Basic music theory will be taught in class in order to learn about transposing instruments, notation methods, and how to read music in different clefs, such as alto and tenor clefs. </p> </div>','MUSC 101 or the equivalent, or permission of instructor. First-year and transfer students must take the Music Theory Placement test (administered during Orientation) to determine eligibility for the course. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10293,2025,258,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-115','<div class="desc"> <p>A historical and cultural survey course of a select genre of vocal music, such as opera, song, musical theater, and choral music. Topics vary by semester and may satisfy different Core requirements.</p> <p><strong>Opera</strong></p> <p>Since its inception in late 16th-century Florence as a humanistic reimagining of Greek tragedy, opera has served as a catalyst for social and political change. The opera-loving agents advocating for this change have been diverse: philosophers (Jean-Jacques Rousseau, Friedrich Nietzsche, Kwame Anthony Appiah), writers (Walt Whitman, Langston Hughes, Toni Morrison), and activists (Theodor Herzl, W. E. B. Dubois, Martin Luther King), among many others, including the late jurist Ruth Bader Ginsburg, whose legal career was dedicated to advocating for gender equality and women''s rights. This iteration of this history-of-opera course will focus on the five operas that Justice Ginsburg wanted people to know: Mozart''s <em>Marriage of Figaro</em> and <em>Don Giovanni</em>, Verdi''s <em>Otello</em>, Puccini''s <em>The Girl of the Golden West</em>, and Strauss''s <em>Der Rosenkavalier</em>. In the first half of the course we will survey the history of opera in Europe, up to and including the two Mozart operas, which premiered in 1786 and 1787. We will study all five operas with attention to their plots'' legal and gender relations. Students will learn opera''s forms and styles and read primary documents written as responses to individual operas and opera writ large, all with the goal of understanding these operas'' political, philosophical, and cultural contexts as well as their messages for us today. No prior musical experience is required. <em>Additional Core Requirements: Pre-1800 and Regional Focus (note: only two Core requirements may be satisfied by successful completion of this course topic).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10294,2025,3341,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-116','<div class="desc"> <p>This course surveys music of African Americans, with an emphasis on 20th century classical and vernacular genres. We will examine this musical web in six units: classical, spirituals, gospel, blues, music of the civil rights movement, and rock &amp; other contemporary vernacular musics. Among the featured artists and record labels covered are William Grant Still, Marian Anderson, Margaret Bonds, Duke Ellington, Fats Waller, Big Mama Thornton, Sam Cooke, Jimi Hendrix, The Staples Singers, Mos Def, Motown, Stax, and Atlantic Records. Through extensive listening and reading, this class will explore how the paradigms of African American cultural experience are deeply interwoven within the musical narratives of the U.S. and its cultural satellites. No prior musical training is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10295,2025,1076,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-117','<div class="desc"> <p>This course studies how ideas about musical copyright, originality, authenticity, property, imitation, appropriation, and theft have evolved over the history of the American popular music industry. We begin with the earliest forms of popular music in the 1800s and work up to the present, examining how legal definitions of musical copyright have changed to keep up with changes in technology, and how changes in cultural attitudes about originality, authenticity, and cultural ownership (especially with respect to race) have affected music industry practices (and vice versa). We will also study how these changing paradigms affect forensic musicology, the legal and philosophical tradition of how we judge the difference between imitation and theft. Assigned readings span a rich and interdisciplinary mix of scholarly research, newspaper articles, interviews with artists, blog posts, album reviews, legal proceedings, and (of course) music recordings themselves. The culmination of the course will be a research paper in which students examine the stakes and outcome of an act of musical larceny of their choosing. Music expertise is not required. This is not a practical music industry course; students interested in preparing for music industry careers should take MUSC 245.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10296,2025,654,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-119','<div class="desc"> <p>This course provides a general introduction to the elements and history of Western art ("classical") music over the last millennium, with a principal focus on Europe. Late in the course we will turn to art music of the Americas, concluding the course with a week on jazz. Students will focus on learning how to listen to music with an emphasis on identifying musical forms, genres, and styles. This focus will serve the larger goal of the course which is to show how understanding music can lead to not only our greater enjoyment of it but also a better understanding of history and culture. Students with no musical experience are especially welcome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10297,2025,259,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-120','<div class="desc"> <p>This course involves the study and performance of a wide variety of choral music, including Western classical genres, world music and folk songs, and pop songs. Students will improve their singing ability and sight-reading skills through this preparation and performance. The ensemble rehearses one evening each week and performs once each semester. Students may enroll for one or both semesters. Ensemble membership is open to all students. Students new to the ensemble should meet with the instructor during the first week of the semester. Graded Credit/No Credit only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10298,2025,260,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-121','<div class="desc"> <p>This course involves the study and performance of advanced choral music. Emphasis is placed on challenging, traditional choral repertoire as well as on world &amp; folk music and popular music. Includes many performances both on and off campus. Enrollment is for the full year and is by audition only during the first week of the fall semester. Sight reading ability and previous musical experience highly recommended. May be repeated seven times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10299,2025,261,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-122','<div class="desc"> <p>This course involves the study and performance of advanced choral music. Emphasis is placed on the challenging, traditional choral repertoire as well as on world &amp; folk music and popular music. Includes many performances<s>,</s> both on and off campus. Enrollment is for the full year and is by audition only during the first week of the fall semester. Sight reading ability and previous musical experience highly recommended. May be repeated seven times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10300,2025,262,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-123','<div class="desc"> <p>Semester-long instruction with music tradition-bearers allows students to develop the technique and language to approach musical styles from outside the Western art music canon, while exposing them to alternative modes of musical pedagogy. In addition to practicing secular rumba drumming, students will study the sacred rhythms of Santeria and learn to sing the songs of the Orishas in the Yoruba dialect of Lucumi. In addition to weekly rehearsals with the ensemble, students will be expected to practice on their own and to participate in a public performance at the end of the semester. No prior music experience is required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10301,2025,955,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-124','<div class="desc"> Son Jarocho Ensemble introduces students to the songs and instrumental techniques of son jarocho, a musical genre from Veracruz, Mexico that mixes indigenous Mexican, African, Spanish, and Arabic sounds. The course will be taught by a master musician who brings over twenty years of musical experience to his classes. Students will learn to play jarana, the eight-stringed guitar that provides the harmonic scaffold for son jarocho. In addition to weekly rehearsals with the ensemble, students will be expected to practice on their own and to participate in a public performance at the end of the semester. No prior music experience is required. Graded Credit/No Credit only. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10302,2025,265,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-127','<div class="desc"> <p>The Occidental Jazz Ensemble consists of instrumentalists from Occidental who are interested in performing jazz of various styles. Charts and styles are determined according to the instrumentalists in the ensemble and their particular jazz interests. The Jazz Ensemble presents several concerts during the academic year. <em>Enrollment is by audition and then, if successful, permission of the instructor. </em>Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10303,2025,1239,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-128','<div class="desc"> <p>This course will serve as an intensive laboratory component to the Occidental jazz program by having students learn the fundamentals of jazz theory including the following: extensions of common practice tonality; modes; form; notational practice and reading from charts; basic arranging and instrumentation; and transcription. The focus will be on chamber jazz performance, supplemented by transcription and listening assignments. In class students as well as instructor will critique one another''s performances. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10304,2025,266,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-129','<div class="desc"> <p>Study and performance of chamber music for diverse combinations of instruments and voices. Students audition during the first week of the semester for our Director, who selects repertoire and form appropriate groups of student players. Students perform both music of the past (including the recent past) as well as new music composed for them by our music composition students, culminating in world premieres at the end-of-semester concert. Prerequisite: audition and permission of instructor. This course does not fulfill the ensemble requirement for scholarship recipients and Music majors. Only advanced pianists may use this course to fulfill the ensemble requirement for scholarship recipients and Music majors. May be repeated seven times for credit. Audition during the first week of the semester. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10305,2025,267,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-130','<div class="desc"> <p>The Occidental Symphony Orchestra is an orchestral ensemble that plays music from the Baroque era through today. Through its collaboration with Oxy''s music composition program, the Orchestra will perform and record new music, including film scores written for MAC student films. The Orchestra will frequently partner with the Occidental Glee Club to perform a large choral work with orchestral accompaniment. Enrollment is by audition during the first week of each semester. Instructor permission required. As the community orchestra for Northeast Los Angeles, the Orchestra is not only open to all students but also alumni and community members. May be repeated seven times for credit. Enrollment is by audition during the first week of each semester. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10306,2025,268,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-131','<div class="desc"> <p>Improvisation is an essential part of music-making, not only central to composing and arranging but also a means to understanding and collaborating with a wide range of musicians and cultures. In this course, students will analyze the improvisational practices of a diverse array of musical artists, such as Miles Davis, Ornette Coleman, Prince, Jimi Hendrix, Julius Eastman, John Zorn, Bjork, Jason Moran, among others. Through this study, students will learn how to replicate specific techniques and apply them to their own music-making. Regular in-class performance will challenge students to bring clarity and intention to their musical choices. Prerequisites are an ability to read music and proficiency in an instrument or voice. May be repeated once for credit. Prerequisite: Ability to read music and proficiency in an instrument or voice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10307,2025,1668,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-148','<div class="desc"> <p>This course explores tools and techniques for musicians developing their engineering and production skills through the use of the Digital Audio Workstation (DAW) Ableton Live. Students will expand their knowledge of MIDI, VSTs, sound design and mixing, audio recording, analog and digital synthesis, sampling, and beat making to enhance their working vocabulary of the fundamentals of production practice. Students will learn how to record and edit audio, manipulate MIDI data, and utilize digital effects processing through the fundamental science behind sound manipulation. Individual creative projects will work to further studentsâ critical engagement with recording techniques to establish a student''s facility with digital audio technology. Students intending to major in Music with a music production concentration must earn a B-minus or higher in this course to declare the Music major.</p> </div>','MUSC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10308,2025,657,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-151','<div class="desc"> <p>This course introduces students to classical theories of musical form and analysis, including simple counterpoint and diatonic harmonic practice with a focus on traditional four-part harmony in choral and keyboard styles. Students will engage in analytic and compositional projects guided by their musical interests. The music studied will be chosen in collaboration with students and Music Department colleagues with an eye towards diversity and inclusion. Includes both a lecture, and a musicianship lab section which focuses on tonal sight singing, listening, and keyboard skills.</p> </div>','MUSC 101 or passing out of MUSC 101 with a sufficient score on the department''s Music Theory Placement Examination ','MUSC 151A ',NULL);
INSERT INTO course_descriptions VALUES(10310,2025,659,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/100/musc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10311,2025,3231,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-200','<div class="desc"> <p>In this course, we will study the relationship between music, sound, and disease, with a special focus on tuberculosis, HIV/AIDS, and COVID-19 in Europe and the United States. We will study how the disabling effects of disease affect musical performance (singing and playing), and how composers and performers have responded to and represented disease. Throughout, we will be alert to how differences in these responses are occasioned by historical time, geographical place, culture, race, sex, and class. We will begin in the early nineteenth century with the invention of the stethoscope, which turned close listening to the body as the principal means of detecting tuberculosis. The second unit of the course will study the disabling effects of TB on the composer-pianist Fryderyk Chopin, how he developed a piano method to accommodate that disability, and how the public perceived his music because of his illness. The third unit will study nineteenth- and early-twentieth-century musical stage representations of tuberculosis—the operas <em>La Traviata</em>, <em>The Tales of Hoffmann</em>, <em>La Bohème</em>, and <em>The Fall of the House of Usher</em>—and consider them in terms of gender, class, health care, and moral codes. The fourth unit will address the HIV/AIDS epidemic. Here we will focus on Diamanda Galas’s Plague Mass, the AIDS Quilt Songbook, and Jonathan Larson''s <em>Rent </em>as political, cultural, and moral arguments. The fifth and final unit will study the musical responses to COVID-19, including the effects of COVID-19 on musicians and music-making, especially singing, and the wide range of public music performed by everyday citizens to honor frontline workers. By ending the course with frontline workers, we will examine the societal inequities that pandemics underscore and how music can give voice to those marginalized and disproportionately affected by a pandemic. Throughout the course, we will chart the vexed understanding of the relationship between mental and physical health, particularly in the presence of debilitating chronic disease.</p> <p>This course is part of the Mellon Humanities for Just Communities initiative.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10312,2025,3010,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-201','<div class="desc"> <p>In this class, we examine sampling, the capture and redeployment of audio sound artifacts, as both a means of music production and an epistemology for constructing knowledge. After reviewing the rich history and theory of hip hop sampling, we will relate this model of musical production to other theories of cultural repetition including cut-and-paste, pastiche, index, simulacrum, collage, citation, signifying(g) and performative repetition. Finally, we will examine the ethics of sampling in the context of neoliberal economic and legal imperatives (including international copyright laws) which have been uneven in their protection of artists and producers. This course satisfies the Second-Stage Writing Requirement within the Music major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10313,2025,3232,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-231','<div class="desc"> <p>In this course, students learn to use the piano as a tool to explore musical structure, access new repertoire, and internalize music theory concepts. Students learn a broad range of keyboard skills: basic keyboard technique, sight reading, harmonization of melodies and basses, transposition, and accompanying. Students apply these skills to a wide variety of musical styles, including classical, jazz, and popular music. MUSC 231 is required of all Music majors and is intended to parallel the content of MUSC 151.</p> </div>','MUSC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10314,2025,284,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-232','<div class="desc"> <p>In this course, students build on the skills they began working on in MUSC 231, applied to more complex keys, more chromatic harmonies, and more remote transpositions. Students learn a broad range of keyboard skills: basic keyboard technique, sight reading, harmonization of melodies and basses, transposition, and accompanying. Students apply these skills to a wide variety of musical styles, including classical, jazz, and popular music. MUSC 232 is required of all music majors and is intended to parallel the content of MUSC 251. Prerequisite: MUSC 231.</p> </div>','MUSC 231 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10315,2025,3868,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-233','<div class="desc"> <p>At the intersection of music and visual art, this collaborative course will explore the ways meaning is made in creative work and is open to all students with an interest in interdisciplinary art practices. Over the semester we will study leading artists whose work straddles sound and visual forms. Students will work with their peers to unpack how they assign meaning and infuse strong concepts and narratives in their art. Through this course, students will experiment with various strategies and tools to express their ideas and will develop a heightened appreciation for the creative process.</p> <p>Each week concepts will be presented through the lens of music and visual art and will be structured to alternate between in-depth study and hands-on class exercises. Such experiments will foster student-led discussions, and lead to projects that challenge students to emulate and ultimately reimagine these ideas through their artistic work. We begin with artists like Jason Moran, a renowned pianist and multimedia artist, whose piece Ringing My Phone perfectly demonstrates the innovative way in which he intersects music and language. The conceptual work of Charles Gaines will guide our exploration of systems that produce sensory experiences. In addition to Gaines, we will look at musicians who integrate the historical archive, like Jon Batisteâs piano arrangement of the Star Spangled Banner, alongside visual artists like Bethany Collins whose physical interventions on the musical notions of other national hymns demonstrate how meaning shifts over time. Non-traditional composers such as John Cage and Wadada Smith will prompt a conversation about the nature and forms of sound.</p> <p>A significant objective of the course will be to expose the ways we take meaning for granted in our sensory experiences. We will question how language facilitates the categorization of various creative practices and consider the value of blurring such distinctions. Students will be asked to engage in a range of strategies to create individual and collaborative work that integrates multiple art mediums, design systems, and methods to support these creations. They will also consider how context impacts meaning/narratives in their work. Prompts throughout the semester will encourage students to answer questions about how one can create with unconventional sounds/tools from their environment and culminate in a final project resulting in a collaborative performance or presentation.</p> <p>The class will emphasize the rich history and resources of LA and will include visiting artists and guest lecturers, as well as field trips to some of LAâs artistic hubs, such as Art &amp; Practice in Leimert Park, The Red Cat, LACMA, Array studios, and relative exhibits. This class aims to enrich studentâs education by exposing them to varying thoughts and approaches to creating and appreciating art. Ultimately we will encourage students to think more broadly about pushing past the traditional boundaries and barriers surrounding art and to create in a way that is authentic to their individual story.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10316,2025,1184,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-241','<div class="desc"> <p>This course offers an interdisciplinary exploration of music and sound cognition and perception, with a focus on human-computer interaction and the significance of artificial intelligence in the field. Topics covered include musical acoustics, psychoacoustics, the auditory brain and ear, and the emotional influence of music. We will delve into cutting-edge technological advancements, such as large language models like GPT, and examine their relevance and implications. Complementary discussions will address concepts of meaning, subjectivity, society, creativity, cross-modality, and their interconnectedness. You will be provided with writing assignments to expand these discussions, enhance your writing skills, and develop critical thinking as you grow into an independent learner.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10317,2025,3011,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-242','<div class="desc"> <p>This course is a survey and a series of hands-on workshops exploring the critical, speculative, and also practical ways of applying machine learning to working with sound and musical composition. In particular, we will be focusing on using Machine Learning models that learn from input data to optimize towards a certain task. In this class, we will look at the uses of ML as a way to deepen our relationship with sound and music production by focusing on machine and human collaboration rather than ML models as solely an open "toolbox" for new sound techniques. This class will learn how to organize and work with large sound datasets, generate new raw audio with neural networks, work with existing plug-ins that have machine learning capabilities, as well as generate midi and compositional structure by training our own AI models. No prior programming experience is necessary.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10318,2025,1605,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-245','<div class="desc"> <p>In this course, students learn how to execute the fundamental aspects of creating a successful music project within the music entertainment industry. Students will work in groups to create artist profiles and business plans, which they will then execute online, by way of digital service providers such as Bandcamp and Spotify, and offline, through methods such as networking, live performance, and industry events. By fashioning distinctive artist identities, students will learn how to formulate an artist brand, including name, style, biography, and intent. They will learn how to market these projects and conduct cost-benefit analyses as they develop business plans which may include frameworks for radio, publicity, distribution, licensing, and synching. The goal of the course is to have students acquire the tools to advance their own careers along their chosen music industry path.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10319,2025,2743,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-246','<div class="desc"> <p>This course applies acoustics, electronics, and digital audio theory in the assembly and operation of Public Address (PA) systems for live concerts. We cover the practice of live sound engineering in different contexts, with a focus on skill building in the technical aspects of live music. Students will assemble PA systems and operate a front of house mixing console for a host of music events both on and off campus. Students will also learn how to set up microphones, use a graphic equalizer to tune a PA system, and run individualized monitor mixes during live performances. Lessons about the theory and practice of live sound will be presented alongside practicum exercises in live engineering, culminating with running tech for several concert-length live performances. Live recording in a DAW-based multi-track session will also be a component in the later portion of the semester.</p> </div>','MUSC 148 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10320,2025,2834,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-247','<div class="desc"> <p>Pro Tools is, worldwide, the standard digital audio workstation for audio recording, editing, and mixing in studios and music production facilities. Understanding its operation, features, and workflows is required for the production of all music genres today, from the small studio to the largest scoring stage. This course will take students with no experience in Pro Tools and equip them with the knowledge and hands-on training to prepare them for the Avid Certified User for Pro Tools exam by covering all the material in Avid’s Pro Tools Fundamentals I (PT101) and Pro Tools Fundamentals II (PT110) curricula. The PT101 course introduces fundamental Pro Tools concepts and principles, covering everything one needs to know to complete a basic Pro Tools project, from initial setup to final mixdown. The PT110 course builds on PT101 by introducing the core concepts and techniques students need to become competent in operating a Pro Tools system for mid-sized recording sessions. Both this course and MUSC 249, Recording Techniques, are required to run recording sessions in the Booth first-floor recording studio. Instructor permission required.</p> </div>','MUSC 148 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10321,2025,2350,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-248','<div class="desc"> <p>Music producers have at their disposal a set of powerful tools that enable them to create, shape, and refine their sounds in their studios. In this course, we will use Max/MSP and Ableton Live for a hands-on approach to building virtual instruments and synths. We will address topics such as synthesis and sampling, and we will create and shape pads, basses, and drums by using virtual instruments and third-party plugins. Students compose more advanced creative projects using the instruments they create.</p> </div>','MUSC 148 and MUSC 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10322,2025,2600,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-249','<div class="desc"> <p>This course explores techniques used for recording music in a studio and in live environments. Topics include commonly encountered acoustical problems and the equipment and techniques used to overcome them. Students develop knowledge of signal flow, mixing board operation, microphone choice and placement, preparing and managing recording sessions in the Choi Family Music Production recording studio, and delivering assets for the mix. Semi-weekly hands-on, guided set-up and operation of recording sessions of various sizes and ensembles help illustrate concepts and allow students to learn through experience. These experiences include recording single instrumentalists, vocalists, acoustic and electronic instruments, and on-campus student recitals and concerts.</p> <p>Must be taken in one''s junior year. Permission of instructor required.</p> </div>','MUSC 148 and MUSC 247 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10323,2025,660,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-251','<div class="desc"> <p>This course deepens students'' understanding of harmony, focusing on chromatic extensions beyond traditional major and minor scales. We also study techniques for analysis and composition of popular and classical song genres, studying how composers'' and songwriters'' expressive choices of harmony intersect with rhythm, form, and lyrics. Students will learn to think critically about many perspectives on what a theory of harmony is and should be, including classical theories of voice-leading, 20th-century theories of 12-tone music and pitch class sets, representations of emotions and atmospheres in cinematic harmony, and jazz theory practices of chord alteration and substitution. Each of these perspectives is studied in historical and social context. Students will continue developing their skills in the writing of scholarly analysis and engage in compositional projects. Includes both a lecture section, and a musicianship lab section focusing on more advanced tonal sight-singing, dictation, and listening.</p> </div>','MUSC 151 ','MUSC 251A ',NULL);
INSERT INTO course_descriptions VALUES(10324,2025,2642,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-252','<div class="desc"> <p>An introduction to the fundamentals of songwriting. In this course, students analyze the form, melody, and harmony of successful songs to determine what makes them effective, and apply this knowledge to the composing of their own songs. Most classes will consist of performing and work-shopping student work in the spirit of open critique.</p> </div>','MUSC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10325,2025,285,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-257','<div class="desc"> <p>Writing exercises to develop technical facility; study of characteristics of instruments; exercises in scoring for various vocal and instrumental combinations. Permission of instructor required. <em>This course may be repeated five times for credit.</em></p> </div>','MUSC 113 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10326,2025,1390,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-258','<div class="desc"> <p>This course introduces students to the art of film scoring and provides an in-depth exploration of the field. We will discuss functions of film music and analyze preexisting scores that demonstrate varying dramatic situations, while also investigating the aesthetic relationship between film and music. Students will be required to write music for preexisting scenes throughout the course, as well as score student short films (senior comps) from Media Production majors. </p> </div>','MUSC 148 or permission of instructor (basic experience using Logic, Ableton Live, or other Digital Audio Workstation) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10327,2025,286,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-261','<div class="desc"> <p>This course surveys the two-plus centuries that gave rise to European art music''s most enduring legacies: opera, instrumental art music, and, especially, the major-minor tonal system, which, as the system that informs most music today, is arguably Europe''s greatest-ever cultural export. The emergence of this tonal system enables instrumental music to sustain a listener''s attention through dramatic forms and without the aid of words; comprehending how these forms behave is one of the central tasks of this course. In turn, the cultivation of instrumental genres will fuel the operatic accomplishments of Classical composers, notably Mozart. Our study of vocal and instrumental music proceeds chronologically and focuses on individual cities, starting with Florence at the end of the Renaissance and ending with Vienna, the music of Beethoven and Schubert, and the emergence of musical Romanticism. This course may be used by Music majors to fulfill the Second-Stage Writing Requirement. Not open to first-year students.</p> </div>','MUSC 101 or the equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10328,2025,956,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-263','<div class="desc"> <p>This course picks up where MUSC 251 leaves off, with the emergence of musical Romanticism and, with it, an understanding of music, composer, and audience that still informs listening practices today. After surveying the music of the first generation of Romantic composers (with special attention to the music of Fryderyk Chopin), we turn to Richard Wagner’s music and writings and how they shaped the rise of modernism in music, with its new forms, genres, styles, and pitch systems. We then take up jazz, the radical experimentation of the 1920s ultra-modernists, and music under fascism. Thereafter, we study all subsequent major musical developments, through to post-minimalism and hip hop. Throughout, we will be alert to the political, philosophical, and cultural forces shaping the music at issue. This course may be used by Music majors to fulfill the College-wide Second-Stage Writing Requirement. Prerequisite: MUSC 101 and MUSC 251 or permission of instructor.</p> </div>','MUSC 101 and 251 or permission of instructor ','MUSC 351 ',NULL);
INSERT INTO course_descriptions VALUES(10329,2025,2708,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-264','<div class="desc"> <p>While attempts to theorize a coming-together of all of the arts to create a unified artwork date to the eighteenth century, it is in the nineteenth century that the notion of a total artwork—in German, a <em>Gesamtkunstwerk</em>—gathers steam, famously in the writings of Richard Wagner, who sees in the total artwork the “artwork of the future” (the title of one of his most famous essays). This course examines the evolution of this concept within and beyond the Wagnerian context, from its prehistory in eighteenth-century theories of beauty and taste, to sound film and music videos, to contemporary Los Angeles dining experiences (such as at Craig Thornton’s Wolvesmouth and Jordan Kahn’s Vespertine) that pick up where Wagner’s theories left off. To chart this history will require us to consider theater, music, dance, painting, architecture, philosophy, film, and gastronomy. Throughout we will investigate the roles that attentiveness and perception play in these multi-sensory events, and consider how European thought and practices migrate and get translated to a contemporary, North American context. Guest lectures by artists and restaurateurs will be supplemented by field trips to Los Angeles arts and dining venues. No previous musical experience required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10330,2025,2351,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-266','<div class="desc"> <p>In this course we study French culture from the reign of "Good King Henry, the Green Gallant," Henry IV (1589Â­-1610) and his invigoration of the arts and French cuisine, to the July Monarchy (1830-Â­1848) and the novels of Balzac, the photographic process of Daguerre, and the music of Chopin. We will also pay particular attention to painting (from Poussin''s classical landscapes to Corot''s Romantic ones), dance (from the codification of couples dancing in the court of Louis XIV to the emergence of classical ballet in 1830s Paris), philosophy (from Descartes''s dualism to Cousin''s eclecticism), theater (from Molière''s The Bourgeois Gentleman to Dumas fils''s The Lady of the Camellias), fashion (from Louis XIV''s introduction of huge wigs of curled hair to the Empire style under Napoléon), and food (from the start of haute cuisine to the invention of the restaurant and gastronomy). Throughout, we will concern ourselves with the interplay of these cultural productions, and how the everÂ­evolving city of Paris served as their crucible.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10331,2025,662,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-270','<div class="desc"> <p>Music has been linked to the podcasting movement since the latterâs emergence in the early 2000s, with early podcastsâor âaudioblogsââdedicated to publishing playlists of favorite music tracks. Though podcasting has grown to encapsulate a wide array of categories and foci, music podcasts have continued to flourish and now specialize in such topics as new music, iconic bands, classic songs, music production, and the music industry among others. Part of podcastingâs resilience is its use of technology to manage free and paid subscriptions and benefit from the diverse voices that contribute to podcastingâs proliferating forms. In this course, we will ideate on podcasts as a popular, user-generated medium that is the latest in a long history of sound objects that circulate and reflect upon popular music. Students will work together to produce a music podcast that is ready for publication through standard podcasting channels. With the course planned for multiple semesters, the podcast can continue for multiple semesters, creating a viable, practice-based platform for the study of music, criticism, and distribution.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10333,2025,287,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-272','<div class="desc"> <p>In this course, students learn the basic principles and gestures of conducting for a variety of instrumental and vocal genres. Students learn aspects of score study, rehearsal preparation and delivery, visual/aural discrimination skills, and alternative movement approaches, while reinforcing essential musicianship. Students study expressive gestures, critical listening, and effective rehearsal techniques; analyze the technique of professional conductors; and workshop and critique the conducting technique of their classmates. The course also addresses the business aspects of conducting and the logistics of running an arts organization. </p> </div>','MUSC 151 and MUSC 271 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10334,2025,288,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-280','<div class="desc"> <p>This course offers an introduction to the principal concepts and methodologies of the field of ethnomusicology as well as the style and practices of selected world musical traditions. This course may be used by Music Majors to fulfill the college-wide Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10335,2025,1716,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-283','<div class="desc"> In this course we will examine the diverse musical cultures (historical and contemporary) of Los Angeles, paying particular attention to the ways music negotiates intercultural encounters. As we survey the musical cultures of Native American, European, Asian, African, and Middle Eastern descendants in the Los Angeles area, we will think about how musical styles, repertoires, instrumentation, and texts are transformed by urban dwellers as they respond to the changing political, economic, and social landscapes of the city. Students will undertake both individual research projects on the Los Angeles-area musical culture of their choice and a digital group project on the local Spanish-language ska scene. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10336,2025,289,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-285','<div class="desc"> <div> <p>Various topics are offered. These courses introduce students to the critical study of popular and non-Western music. Students will learn to locate musical genres and styles in relation to the historical, social, and cultural context that engender them, while learning new approaches to formal analysis. Each fulfills the College-wide Second-Stage Writing Requirement</p> <p>Topic for Spring 2025: <span><strong>Music and Gender</strong></span></p> <p><span>This course will address the ways in which gender is expressed through music and sound, and relatedly, will examine music’s capacity to shape gender discourse. Through a mapping across genres of popular music, such as hyperpop, riot grrrl, rap, and neoperreo, we will explore the role of gender embedded in the relationships between performers and listeners, specifically by highlighting the </span><span>intersectional identities and power dynamics at play in musical practice.</span></p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10338,2025,3342,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-287','<div class="desc"> <p>Over the past century, music has played a central role in political and social movements that seek to shift the balance of power in local, national, and transnational contexts. From the songs of the African American freedom struggle to the music of the <em>nueva cancion</em> movement in Chile, from the live performance practice of the Occupy and immigrant rights movements to the sounds of Black Lives Matter, music has been an important mode of circulating alternative political messages and inspiring rebellion against the status quo. How can music be used to convey political messages and extend the reach of social movements? Why does music enhance cohesion and solidarity among movement participants and/or sway or destabilize oppositional forces? Are there differences between mass-mediated modes of political protest and live, grassroots political performances? When voices raised in song become powerful, what protocols are established to censor and repress them? We will examine these questions in the context of social movements which have inspired mass participation, comparing and contrasting case studies from Europe, Asia, Africa, and the Americas. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10339,2025,3675,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-293','<div class="desc"> <div><p>Students will conduct directed research into a musician or a musical technology, writing a ten page paper on the topic, undertake a significant creative work that builds on the lessons of this close study, or participate a community-based project that culminates in a public presentation of a collaborative project.</p></div> </div>','Not available to first year students. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10340,2025,663,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/200/musc-295','<div class="desc"> <p>An interdisciplinary course that investigates the music and life of individual composers. Topics vary by semester. Different topics may satisfy different Core Program requirements.</p> <p><strong>Fryderyk Chopin</strong></p> <p>With little formal piano training and sick most of his life, the Polish composer-pianist Fryderyk Chopin (1810-1849) wrote music for the piano that revolutionized piano playing, piano music, and music in general, and has influenced composers and pianists since, including throughout jazz history. In this course, students will study Chopin''s music in context, focusing on his adult years in Paris. To do so, we must study not only piano repertoire, manufacture, pedagogy, and technique, but also Paris--its art, literature, history, music, theater, science, politics, and medicine--and living there in exile. With the only prerequisite being a reading knowledge of music, students from all disciplines are welcome and encouraged to explore Chopin''s music from their disciplinary perspective, especially in their individual semester-long projects. <em>Additional Core Requirement Met: Regional Focus</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10342,2025,2560,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-348','<div class="desc"> <p>Students learn the art and craft of mixing and mastering music, as it applies to the many creative and technical considerations involved in creating a professional music mix. Using Pro Tools as our main Digital Audio Workstation, all aspects of mixing and mastering will be covered, including in-depth explorations of built-in and third-party plug-ins. By the end of the course, students will have completed weekly assignments using existing pre-existing audio and midi stems and will have produced an original work that is mixed and mastered to industry standards. Must be taken before one''s senior year.Instructor permission required.</p> </div>','MUSC 247 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10343,2025,1541,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-350','<div class="desc"> <p>This variable-topic course offers a deep dive into a single musical style or genre from a musician’s perspective. We will study the emergence and development of the style with an intense focus on details at both the surface and background levels of musical activity — melody, harmony, rhythm, texture, density, articulation, dynamics, timbre, instrumentation, and form. This course will also explore “colloquial” or “emic” musical concepts as described or practiced by practitioners of this genre or tradition. The aim is to develop a broad understanding of the ways in which all aspects of musical language and aesthetics influence musical form and style within the chosen genre or tradition. Readings will reinforce the connection between culture and style, yielding discussion of links between intellectual, social, and musical history. The final project will be an analytic paper and a classroom presentation based on this work. </p> </div>','MUSC 251 or permission or instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10344,2025,1717,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-351','<div class="desc"> <p>This course invites students to use their growing knowledge of harmony and musicianship to study large-scale form and how it is built out of small-scale parts. Students will compare musical form in several traditions, viewing form types as genres deeply intertwined with those traditions’ conceptions of time and pitch space as well as with social and cultural meanings. Traditions studied include: large-scale form in electronic dance music genres, built out of beats, layers, and loops, which fosters utopian, ecstatic dance spaces; sonata form in Western classical music and the “tonal drama” of key pairings; Raag and Taal in Hindustani Classical Music as the building blocks for improvised forms which invoke particular moods or <em>rasa </em>in listeners; and experimental compositional and analytic techniques of 20th and 21st century art music, especially extending beyond the 12-note equal-tempered scale. The culmination of the sequence includes a substantial scholarly analytical paper. Includes both a lecture section, and a musicianship lab section focusing on continued training in tonal and atonal sight-singing, dictation, and listening.</p> </div>','MUSC 251 or permission of instructor ','MUSC 351A ',NULL);
INSERT INTO course_descriptions VALUES(10345,2025,2601,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-358','<div class="desc"> <p>This course focuses on the technical and aesthetic aspects of composing and recording music for picture that use various synchronization methods (MIDI sequence, click track, SMPTE timecode). Students will compose and record up to three projects, combined with live players, and score short films created by Media Arts &amp; Culture majors for their Senior Comprehensive. May be completed four times for credit.</p> </div>','MUSC 258 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10346,2025,290,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-374','<div class="desc"> <p>This course seeks to strengthen the connection between music theory and music history instruction and performance instruction by bringing the former to bear on the latter: how can our knowledge of music theory and history be mobilized to analyze the pieces we perform and lead to more intentional, informed performances? The course will be divided into three units. The first unit will have students analyze selected instrumental and vocal pieces and then study several different recordings of each piece to assess how these recordings align with their analyses. In the second unit, students will choose a piece that they are preparing for performance, analyze that piece, and then workshop their analysis-informed performance of that piece in class. In the third and final unit, students will write about the pieces they are performing. For Music majors with a performance concentration, this will consist of learning the genre of the program note and writing program notes. For all other students, this will consist of writing a performance-informed analysis essay. All students are required to perform in class, regardless of ability level. Prerequisite: MUSC 151/151A. May be repeated once for credit.</p> </div>','MUSC 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10347,2025,957,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-385','<div class="desc"> <p>Topics vary by semester.</p> <p><strong>Bach’s Cycles: Bach, Musical Systems, and the Enlightenment</strong></p> <p>This seminar will explore stylistic and structural issues in several monumental works of Bach. Two points of view will be taken: analytic, and musico-sociological. Works to be studied include the Goldberg Variations, the unaccompanied sonatas and partitas for violin, the unaccompanied suites for cello, the Well-Tempered Clavier, the Art of Fugue, and the Musical Offering. Topics for papers and presentations will be developed with attention to seminar participants’ particular interests. A course grade of B- or better, and satisfactory completion of a minimum of 15 pages of written work will satisfy the College’s second-stage writing requirement as implemented by the Music Department. Prerequisite: MUSC 250 (may be taken concurrently). </p> <p><strong>Music and Food</strong></p> <p><strong></strong>This interdisciplinary research seminar will examine the relationship between music and food and thus hearing and taste in Europe and the United States beginning with the 16th-century category of musical composition called “table music” and culminating in the present-day gastropub. Along the way we will explore topics such as the 18th-century emergence of aesthetics as a branch of philosophy the rise of the restaurant and gastronomy Dandyism and Decadent literature and “fine dining” in the United States. We will read scholarly literature from the fields of philosophy history cognitive science sociology literature and music. Students will carve out an area of research early on and develop it over the course of the semester culminating in a research presentation and final argument-driven research paper. The course will conclude with the recreation of a historical banquet.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10348,2025,3677,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/copy-of-musc-393','<div class="desc"> <div><div><p>Students will conduct directed research into a single musical style or genre using methods from ethnomusicology, theory, and/or historical musicology as appropriate. Permission of instructor required. </p></div></div> </div>','Not available to first year students. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10350,2025,666,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/300/musc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10351,2025,291,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/400/musc-473','<div class="desc"> <p>This course convenes senior Music majors with Instrumental Performance, Vocal Performance, and Composition Concentrations to design, workshop, share, and critique work that will become part of the senior recitals that will fulfill, in part, the Senior Comprehensive requirement. The course is also open to Juniors and Seniors with Production and other concentrations who are interested in performing their work in live environments. The focus of the course will be learning the craft of designing and promoting dynamic performances that expertly make use of space, stage design, costuming, personnel, microphone techniques, DJ gear, and audience participation as appropriate. Each student in the course will be responsible for designing one or two performances that will be staged during the semester. The course may be repeated once for credit. Junior or Senior standing is required. Permission of Instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10352,2025,292,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/400/musc-474','<div class="desc"> <p>This course convenes senior Music majors with a Music Production concentration to workshop, share, and critique the work that will become part of the music portfolio they will submit in partial fulfillment of the Senior Comprehensive requirement. May be repeated once for credit. Junior or Senior standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10353,2025,293,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/musc-music/400/musc-490','<div class="desc"> <p>In this seminar, students work through a staged process to complete their senior comprehensive paper—an argument-driven academic essay that engages with and contributes to recent and relevant scholarship in the fields of musicology, ethnomusicology, sound studies, and/or music theory. Students with a musicology, ethnomusicology, or music theory &amp; analysis concentration will produce a complete draft of their 6,250-word essay. Students with a composition, production, instrumental performance, or vocal performance concentration (all of whom give a senior recitals or presentation) will produce a 2,500-word essay on music on their recital (for performers), on the music of a composer who has influenced their own approach to composition (for composers), or on music or a music technology that has influenced their approach to production (for producers); students in these four concentrations will also research and produce a draft of their recital program notes or, for producers, liner notes. Over the course of the semester students will discuss and share their work, as well as analyze and discuss exemplary academic papers, program notes, liner notes, and music reviews in order to develop their ability to write about music for academic and non-academic audiences in compelling ways. Open only to juniors and seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10355,2025,689,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-104','<div class="desc"> <p>This particular section is for serious trainers who want to concentrate on the development of the physique through a strenuous strength and plyometric program. We will execute specific exercises designed to develop explosive muscle mass and definition.</p> </div>','Prior powerlifting experience is required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(10356,2025,309,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-127','<div class="desc"> <p>The United States Tennis Association (USTA) promotes cardio tennis as a group activity featuring a circuit of drills that consistently elevate the heart rate into the aerobic training zone. Short cycles of high intensity work-outs and periods of rest similar to interval training. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10357,2025,310,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-128','<div class="desc"> <p>Spin I is an introductory course designed to expose students to the terminology and movements of cycling while preparing them for the advanced rides of Spin II. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10358,2025,311,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-129','<div class="desc"> <p>Students will learn the fundamentals of hip hop dance and will gain experience in learning hip hop choreography. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10359,2025,691,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-130','<div class="desc"> <p>General fitness activities consisting of strength, agility and stretching exercises. The goal of this class will be to provide opportunities for participants to improve their overall fitness through class participation and increased knowledge to be applied once the class concludes. Course Fee $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10360,2025,312,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-133','<div class="desc"> <p>Class concentrates on improving overall fitness through the use of an aerobic weight training program. Circuit training is a combination of high-intensity aerobic and resistance training primarily through the use of weight machines. It is idealto help control body weight tone muscles and improve cardiovascular fitness. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10361,2025,313,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-134','<div class="desc"> <p>Learn the fundamentals and history of the practice of Yoga. Over the course of the semester the practice will become more and more challenging and in depth; making gains in strength flexibility and the mental aspects of Yoga. Focuses will include: breathing techniques proper posturing different styles of Yoga the physiological side mental side and meditation side of Yoga. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10362,2025,866,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-135','<div class="desc"> <p>This intensive course focuses on sport-specific training injury prevention strength-building conditioning and fitness programming. The class is designed for the advanced athlete and includes strength training plyometrics and aerobic conditioning with specific application to athletic performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10363,2025,315,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-149','<div class="desc"> <p>Analysis of basic offensive and defensive techniques used in Karate including time speed and knowledge of body leverage. Cognitive knowledge of defense methods and their employment are also learned. Special emphasis on Shotokan Karate. Course Fee: $125.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(10364,2025,1127,'https://oxy.smartcatalogiq.com/en/2024-2025/catalog/course-descriptions/phac-physical-activities/100/phac-150','<div class="desc"> Zumba is a high-energy fusion of Latin and International music with unique dance moves that sculpt and tone the body. The aerobic routines feature fast and slow rhythms to maximize caloric output and fat burning. Even if you have never danced or tried group exercise, Zumba is a perfect introduction to dancing for health. The movements are basic enough that anyone can follow, yet challenging enough that you never get bored. Course fee $125. </div>',NULL,NULL,NULL);
