INSERT INTO course_descriptions VALUES(13638,2026,4282,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/ling-linguistics/100/copy-of-ling-193','<div class="desc"> <div><p>Intensive study in an area of linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
