INSERT INTO course_descriptions VALUES(13977,2026,4320,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phac-physical-activities/200/phac-275','<div class="desc"> <p>For individuals who are interested in recreational or competitive weightlifting and powerlifting. Participants will learn techniques of Olympic style weightlifting and power lifting. Through strength and conditioning workouts, they will enhance their strength and power. Participants are expected to have prior experience with Olympic style lifting, and/or power lifting.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13978,2026,294,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/100/phil-101','<div class="desc"> <p>This course introduces students to the central philosophical skills of critical thinking, careful reading, and analytical writing. Students will engage with a range of both historical and contemporary philosophical texts, from multiple regions and time periods, and with a range of philosophical questions that reflect the four content areas that structure our curriculum: (1) History of Philosophy, (2) Diversity in Philosophy, (3) Self &amp; Community, and (4) Mind &amp; World.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13979,2026,2679,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/100/phil-150','<div class="desc"> <p>This course introduces students to symbolic models of the structure of arguments, and to tools for representing those structures and evaluating them as patterns of good or bad arguments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13980,2026,4321,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/100/phil-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13981,2026,2561,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/100/phil-199','<div class="desc"> <p>This course will be an introduction to case-based reasoning in practical ethics and political philosophy. Students will learn basic philosophical tools for analyzing the moral or ethical dimensions of practical problems, with an emphasis on medical or health related cases and policy. Heavy emphasis will be placed on speaking and critical thinking. May be repeated once for credit. Graded on a CR/NC basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13982,2026,3912,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/copy-of-phil-214','<div class="desc"> <div><p><strong>The Hundred Schools: Rebellion and Responsibility in Early China</strong></p><p><br/></p><p>Although human concerns have been similar through historyâlike âWhat is important for humans to thrive?â or âHow do we know what we know?ââanswers are sometimes very different in different historical periods. Of course, in any period there will be disagreement, so this course will focus not only on some general differences between thinking in early China versus the present day, but also on disagreements within early China itself. For example, many thinkers in early China take us to have substantial responsibilities to each other, so we will discuss whether this thinking provides a viable alternative to the contemporary U.S., where a marginalized person must often depend largely on themselves for support. We discuss Confucian views of political legitimacy and rebellion. We will also discuss disagreements between Chinese thinkers from this period, including what constitutes human nature and whether rituals (including funerals) contribute to a good life or are simply a waste of resources. We also discuss different thinkersâ understanding of the Dao (or the Way), our relation to nature, and how to engage in the highest form of action, non-action (wu wei). This course focuses primarily on the vibrant Warring States period, roughly 475-221 BC, which includes the beginnings of Confucianism and Daoism, as well as Mohism, âLegalismâ, and the School of Names or logicians.</p><p><br/></p><p>This course satisfies the History of Philosophy distribution requirement for the Philosophy Major.</p><p>This course satisfies the Pre-1800 and Regional Focus Core Requirements.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13983,2026,3996,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-201','<div class="desc"> <div><p>A hands-on introduction to philosophy. As students bake and break bread together, they will explore a variety of philosophical topics, including the aesthetics of taste, the morality of food practices, the metaphysics of producing and consuming food, and other culinary provocations. A course in experiential learning, students will learn how to perfect the sourdough loaf while discussing the value of imperfection. </p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13984,2026,3997,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-202','<div class="desc"> <div><p>This course offers an in-depth exploration of Socrates, the enigmatic figure at the heart of Western philosophy. Often regarded as the father of moral philosophy, Socrates left no writings of his own, yet his ideas profoundly shaped the intellectual landscape of ancient Greece and beyond. This course aims to reconstruct the historical Socrates by examining a variety of sources, including the early dialogues of his student Plato, the writings of Xenophon, and the plays of Aristophanes, alongside modern scholarly interpretations. We will investigate the philosophical method attributed to Socrates, the nature of Socratic ignorance, and the legacy of Socratic irony. Additionally, the course will aim to understand how Socratesâ life and thought clashed with the democratic society that ultimately condemned him to death.</p><p><br/></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13985,2026,864,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-210','<div class="desc"> <p>We will address some of the fundamental issues in epistemology and metaphysics while reading selections from the works of some important philosophers from the modern period (1600-1800). Among the issues addressed will be the existence of the external world, the relation between the mental and the physical, and the foundation of our knowledge of the future. Philosophers covered will include Descartes, Leibniz, Locke, Berkeley, Hume, and Kant.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13986,2026,2693,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-211','<div class="desc"> <p>This course will explore how central figures in the history of moral philosophy grapple with fundamental questions, such as: What is the best life for a human being? Should I be good? Can I be good? What are our obligations to others, both friends and strangers? Philosophers covered will include Plato, Aristotle, Kant, Mill, and Nietzsche.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13987,2026,2799,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-212','<div class="desc"> <p>Existentialist philosophy is primarily concerned with questions of authenticity, value choice, and freedom: What does it mean to live an authentic human life? Are we free to choose the kinds of people we are and the values we embrace? And what do such possibilities mean for our obligations to other people? In this class we will discuss the problems raised and solutions proposed by existentialist philosophers such as Kierkegaard, Nietzsche, Heidegger, Sartre, Camus, and Beauvoir, through critical examination of their major writings. Our aims will be to understand the intellectual motivations for existentialist thinking and the relevance of their arguments and positions for contemporary philosophy and contemporary life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13988,2026,3363,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-213','<div class="desc"> <p>Philosophers of the medieval Arabic-Islamic tradition, such as al-FÄrÄbÄ«, Ibn SÄ«nÄ, and Ibn Rushd, proposed detailed answers to numerous philosophical questions, grounding their proposals in powerful arguments. Some of these questions include: What is the nature of reality? What is the soul, and how is it related to the body? What is it to know something, and how can we achieve knowledge? What is language, and where does it come from? How should we discern good reasoning from bad? Is there a God? If so, what is God like? What is religion, and what is its role in society? By adopting a broadly Aristotelian framework, but going well beyond its confines, medieval Arabic-Islamic philosophy paved the way for later European Latin philosophy, which borrows heavily from the earlier tradition''s insights. We will study those insights in this class.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(13989,2026,1718,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-215','<div class="desc"> <p>A detailed examination of some central philosophical texts from history of Western philosophy. Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p><strong>Ockham''s Manifesto: Language and Ontology in the <em>Summary of Logic</em></strong></p> <p>The <em>Summary of Logic</em> by William of Ockham (ca. 1287–1347) has been called "a manifesto masquerading as a textbook." In addition to teaching a revamped system of Aristotelian logic based on the semantic properties of signification and supposition, Ockham''s <em>Summary</em> also outlines a metaphysical program that revolutionized late medieval philosophy. This program came to be known as ''nominalism'', with ''realism'' being its adversary. Ockham''s own brand of nominalism recognizes only particulars – as opposed to universals – belonging to the Aristotelian categories of substance and quality. So among the things that exist are Kiki the cat and the grayness of her fur, but not any general felinity or gray color in virtue of which she''s a gray cat. This ontological reduction is grounded in an innovative linguistic analysis involving the semantics of connotation and the theory of mental language: ''cat'' signifies particular cats, not catness-in-general, and ''gray'' signifies particular gray things while connoting the particular graynesses that they have. In this class, we''ll investigate this doctrine along with the overall relationship between language and ontology in Ockham''s <em>Summary</em>, reading much of Book I along with supplementary material from Ockham''s other works and from other philosophers in Ockham''s context. </p> <p><strong>Medieval and Early Modern Philosophical Theology</strong></p> <p>In pursuit of wisdom, most philosophers throughout history thoughtfully engaged in a project of philosophical theology. Differing from religion, theology – the study (<em>logos</em>) of god (<em>theos</em>) – critically examines the existence, features, powers, and effects of deities. Some of the most sophisticated approaches to these issues were proposed by medieval and early modern philosophers living between about 1000 and 1800 CE. In this class, we''ll try to understand the theological views of a variety of philosophers of this period. Topics will include arguments for the existence of a god in the Latin and Arabic traditions, philosophical mysticism in medieval women philosophers, and the metaphysics and logic of the sacrament of the eucharist. <em>Additional </em><em>Core Requirements Met: Global Connections.</em></p> <p><strong>The Myth of Dualism</strong></p> <p>There are bodies and minds, and the two are fundamentally distinct. Bodies are spatial, publicly observable, and subject to mechanical laws. Minds are spectral, private, and, when things go right, observant of the rules of good reasoning and purposeful action. People are unions of the two— ghost-piloted machines whose constituents, once separated by bodily death, have very different fates: the abandoned vessel decays, while the captain somehow survives. Or so says the myth of dualism, attributed to the 17th-century French philosopher René Descartes by the 20th-century British philosopher Gilbert Ryle, who argues extensively against the "official doctrine" of Cartesian Dualism. But Descartes, ingenious as he was, didn''t think in a vacuum. He absorbed and perpetuated an intellectual tradition stretching from Classical Greece, to the Golden Age of Islam, to the European Middle Ages, and into Modernity—crude labels for internally diverse and complexly interrelated periods of philosophical history. In the first part of this course, we''ll try to locate and trace the myth throughout this roughly two-thousand-year stretch. Our approach will be chronological, and we''ll study the views of numerous philosophers, including Plato, Aristotle, Al-FÄrÄbÄ«, Ibn SÄ«nÄ, Thomas Aquinas, Teresa of Ávila, Descartes, Pierre Gassendi, Elisabeth of Bohemia, Baruch Spinoza, and Anton Wilhelm Amo. In the second part of the course, we''ll consider several approaches to rejecting the paradigm. Forsaking chronology, we''ll first attend to Ryle''s alternative to dualism—logical behaviorism—before reflecting on an assortment of challenges, raised by Ludwig Wittgenstein, W.E.B. Du Bois, Michel de Montaigne, and NÄgÄrjuna, to the very idea of an identifiable, unified, or non-illusory self. <em>Additional </em><em>Core Requirements Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13990,2026,2800,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-220','<div class="desc"> <p>This course will philosophically examine the concept of race and the way race informs identity. Topics include the reality of race, the origins and nature of the concept, and the extent to which race does and should impact our social and personal identities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13991,2026,4322,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-221','<div class="desc"> <p>What is feminism? How have classic and contemporary authors understood gender differences, the unequal treatment of women, and the role of gender in an ideal society? What contemporary issues face women today, and how have feminists deepened our understanding of these issues? This course will offer an introduction to theories of feminism, gender, and intersectionality. After laying a theoretical groundwork, the course will turn to applied issues, which may include sexual assault/violence against women, transsexual lives, pay inequity for women, work-life balance and the "second shift," pornography, reproductive rights, and impossible ideals for the feminine body.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13992,2026,2680,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-222','<div class="desc"> <p>This course will explore the relationship between knowledge and social and political power, focusing on epistemic dimensions of racial and gender oppression. The course will address several of the following questions: (1) How do stereotypes and propaganda operate, and what sort of threat do they pose to equality in the United States? (2) How do ideologies entrench privilege and injustice, and how can we counteract the effects of bias and false beliefs that persist in the face of strong opposing evidence? (3) Is there a distinctively epistemic form of injustice, and, if so, what does this form of injustice look like? (4) To what extent does epistemic injustice affect our ability to know ourselves, and how can we counteract its effects on our self-understanding? The authors that will be discussed may include Michel Foucault, Charles Mills, Kristie Dotson, Sally Haslanger, JosÃ© Medina, Tommie Shelby, Jason Stanley, Patricia Hill Collins, and Miranda Fricker.</p> <p>This course has an experiential learning component.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13993,2026,3012,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-223','<div class="desc"> <p>This course is an introduction to Mexican philosophy, and indirectly to Latin American philosophy. We will discuss Mexican contributions to universal questions (such as the nature of art, democracy, humanity, and racial, sexual, and ethnic identity), and we will raise the question of Mexican philosophy (what is it, how is it different from Western philosophy) by situating it in the context of other cultural expressions of Mexican identity, such as Mexican food, literature, and Mexican muralism. Thus, this course is also an introduction to comparative philosophy more generally, since it aims to challenge Eurocentrism by demonstrating that philosophy is grounded in or is an expression of cultural identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13994,2026,3364,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-224','<div class="desc"> <p>This course explores some central topics in Philosophy of Religion, primarily through an examination of African American religious life from slavery and emancipation through the present. Drawing on philosophy, theology, film, and music, we will address the following sets of questions: (1) What is the religious outlook? What is faith, and is faith rational? What roles does faith occupy in social change? (2) Can we reconcile the existence and goodness of God with the existence of oppression, injustice, and other evils? (3) Can grace and other forms of love redeem us or transform our character? What roles do grace and other forms of love play in helping us resist oppression and create a more just society? Throughout the course, we will consider how religious thought and practice might help us live, and even flourish, in a broken world. The authors we will discuss may include Marilyn McCord Adams, James Baldwin, Patricia Hill Collins, James H. Cone, Henry Louis Gates, Jr., Evelyn Brooks Higginbotham, Martin Luther King, Jr. Howard Thurman, and Cornel West.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(13995,2026,296,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-230','<div class="desc"> <p>Philosophical thinkers have asked a series of related questions about how to live: What is happiness? What kinds of human activities give our lives meaning? More generally, how must a person live to have lived well? This course will examine a variety of answers to these questions. As a significant component of the course, students will practice living within one of the traditions we study, and reflect upon that experience.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13996,2026,2802,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-231','<div class="desc"> <p>This course will examine the ethical dimensions of our relationship to non-human animals and the environment, including a special emphasis on climate justice as the site of interconnected and global moral, political, and scientific concerns. Some of the questions we will address include: What is the relation between the environment and human health and well-being? Are there reasons other than human health and well-being for protecting the environment? Do nonhuman animals have rights? Do trees? Are we morally permitted to eat/experiment on/keep in zoos/hunt nonhuman animals? How do we compare environmental values against other values in making reasonable decisions?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13997,2026,2803,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-232','<div class="desc"> <p>This course will draw on philosophy, literature, and film in order to address some of the central topics in philosophy of religion. The questions that the course will address include: Does God exist? What is faith, and when, if ever, is it rational? Do we survive our bodily deaths, and if not, should we fear death? The course will also consider implications of answers to these questions for the meaning and value of our lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13998,2026,2695,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-233','<div class="desc"> <p>This course will introduce students to fundamental normative and ethical questions that arise in health care and the biological sciences, emphasizing those questions which raise issues of social justice within healthcare. Questions may include the following (among others): Will emerging technologies, particularly genetic technologies, promote or widen equity gaps in healthcare? Is it ableist to "treat" disabilities, such as deafness? How can doctors best communicate across race and class? Do fetuses have a right to life, and how does abortion access impact different groups across the United States? Is there a right to die? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(13999,2026,3270,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-239','<div class="desc"> <p>We all want to build a socially just community and we believe that our health, as well as that of our family, friends, and neighbors, is a vital component of such a community. At the same time, we also recognize that what justice requires is complex and contested. This interdisciplinary course will first help students conceptualize what justice looks like within the realm of health and medicine through a series of case studies from the ancient Mediterranean and the United States contexts. Through these case studies—which will include a focus on public health, the patient-provider relationship, reproductive health, and end-of-life care—we will scrutinize the conceptual framing of health justice in the past, as well as the health justice foundations of contemporary practices, policies, and institutions. At the end of the semester, we will also give students the opportunity to envision a better way forward, and to begin to enact their vision. Students will design their own social justice final project on a topic of their choice. </p> <p>This course is part of the Humanities for Just Communities Immersive semester. Students wishing to enter into careers in the health professions—whether as physicians, researchers, or policy experts—are especially encouraged to enroll. Co-requisite: FYS 2.</p> </div>',NULL,'FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(14000,2026,2804,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-241','<div class="desc"> <p>Paradoxes and their resolution have played a significant role in the development of philosophy; they still have an influence on philosophy today. While Zeno''s paradoxes of motion where first posed about 2000 years ago there is still not a consensus about what to say about them. Semantic paradoxes such as the liar paradox and the paradoxes of vagueness reveal problems with everyday concepts such as truth and implication. Supertasks reveal problems with our understanding of infinity. What to say about these problems what they show us about how to understand space, time, infinity, truth, and reasoning are some of the issues we will discuss in this class. We will examine various paradoxes, puzzles, and purported paradoxes and discuss different proposed resolutions to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14001,2026,2805,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-242','<div class="desc"> <p>An introduction to the study of the mind and its relation to the body, the nature of human agency action, and personal identity. Questions to be investigated include: Is the mind identical to the brain, or is it something separate and immaterial? Is it possible for computers to think, to have consciousness, and to engage in actions that can be assessed as right or wrong? What makes someone the same person at two different times? Could you continue to exist after the death of your brain with a prosthetic brain, carbon or silicon based, into which your beliefs, desires, and memories have been infused?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14002,2026,2696,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-243','<div class="desc"> <p>This course will explore the relationships between the ways we describe the world and the nature of the world we describe. We will explore such questions as: Do different languages describe the world differently? Do different descriptions of the world correspond to different conceptions of it? Is the world a different place for those with different understandings of it? Could the world be other than it is, and how do we talk about these alternative possibilities? Are there limits to what we can express, and how do those limits correspond to the limits of what there is?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14003,2026,3283,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-246','<div class="desc"> <p>Often referred to as “Critical Thinking”, this course focuses on identifying, reconstructing, and evaluating the kind of reasoning we encounter everyday. It explores the internal relationship between evidence and explanation, as modeled by science and investigation (i.e., diagnostic reasoning), and exercises the skills involved in analytical reading and effective communication by articulating the structure of informal reasoning (i.e., where the truth of the premises does not guarantee the truth of conclusion). Examples of the kind of argument to be considered are those based on correlation, testimony, sampling, enumeration, prediction, and recommendation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14004,2026,4323,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-251','<div class="desc"> <p>This is a second course in logic. It will introduce topics in modal logic inductive logic and non-classical logic building on the foundation provided by PHIL 150. The course will have a significant CBL component involving teaching logic and critical thinking to local high school students. As part of the CBL component of the course students will design curriculum read some philosophy of education, keep a journal and write a reflection piece on their experience in the classroom.</p> </div>','PHIL 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14005,2026,3365,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-252','<div class="desc"> <p>This course is a continuation of PHIL 150: Formal Logic. It introduces polyadic predicate logic, along with identity, functions, and definite descriptions. Topics may also include some logical metatheory and an introduction to non-classical, modal, or other systems of logic.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(14006,2026,4041,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-260','<div class="desc"> <div><p>This course will explore foundational questions in the philosophy of art: What is art? Is there a quality, or feature, or function that all works of art share? How does art get its meaning? Does the artist or the viewer (or both, or neither) determine the meaning of an artwork? (Why) do we value the authenticity or originality of an artwork? What determines whether something is a good work of art? Can art make us better (or worse) people? Can good works of art have morally bad properties? How can we be moved by fictions (that is, how can we fear the monsters of horror films)?</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14007,2026,4324,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14008,2026,4325,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14009,2026,2463,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/200/phil-299','<div class="desc"> <p>This course is centered around understanding, and engaging deeply, with applied ethics cases developed for the Intercollegiate Ethics Bowl. These cases typically deal with a broad array of contemporary issues, such as immigration rights, the ethics of self-driving cars, gun control, race/gender on college campuses, etc. In the course, students will research realistic ethical cases, work in teams to develop thoughtful ethical analysis of these cases, and articulate these analyses both verbally and in writing. Throughout the semester, students will prepare for the regional Ethics Bowl competition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14010,2026,298,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-310','<div class="desc"> <p>A detailed examination of some central philosophical texts from the 17th and 18th centuries. Topics vary by semester.</p> <p><strong>Kant''s <em>Critique of Pure Reason</em></strong></p> <p>This course will consist in a detailed study of selected parts of Immanuel Kant''s <em>Critique of Pure Reason</em> – the most important and influential 18<sup>th</sup>-century work on philosophical issues about the relationship between mind and world, and an attempt to synthesize and build upon the rationalist and empiricist approaches to those questions. We will also read selections from some of the central figures in the traditions to which Kant is responding (including Rene Descartes as an exemplar of the rationalist tradition, and David Hume as an exemplar of the empiricist tradition), in order to contextualize the motivations for Kant''s project, and to frame the issues with which the <em>Critique of Pure Reason</em> is engaged.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14011,2026,2807,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-311','<div class="desc"> <p>Ludwig Wittgenstein (1889-1951) is a central figure in the two most important philosophical traditions of the twentieth century: First the attempt early in the century to characterize language thought and the world in terms of the newly available formalism of modern logic and second the attempt to show that any such formalization will fail to do justice to the rich complexity of language as a form of life a form inseparable from the social and historical context from which it springs. We will examine two principal works the <em>Tractatus Logico-Philosophicus </em>and the <em>Philosophical Investigations</em>. There will also be some treatment of the historical and philosophical context of Wittgenstein''s work and life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14012,2026,959,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-312','<div class="desc"> <p>Søren Kierkegaard (1813-1855), sometimes referred to as “the father of existentialism”, was a sharp critic of modern philosophy, institutionalized religion, and what he called “the present age”. For Kierkegaard, the fundamental problem of philosophy was to describe what it means and what it takes to become human—suggesting, ironically, that it is possible for a human being not to be human. The primary purpose of this course is to read Kierkegaard’s most influential texts closely, situate them in their historical and philosophical context (namely, early 19th Century Western Europe), and draw out their contemporary relevance, paying particular attention to the concepts of irony, anxiety, despair, love, and faith. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14013,2026,2808,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-313','<div class="desc"> <p>Fyodor Dostoevsky’s <em>The Brothers Karamazov</em> is a gripping story of murder and romantic rivalries, a wonderfully inventive literary work, and one of the finest philosophical novels ever written. We will read all of <em>The Brothers Karamazov</em> and discuss some of the main philosophical issues that it addresses. Furthermore, we will consider these issues in light of 19th-century Russian culture, and society. Course topics will include: (1) the conflict between faith and reason, and the role – if any – that faith occupies in a good life (2) the nature of love, and the meaning and significance of the command to “love your neighbor” (3) what it means for human beings to flourish, and what sort of community makes flourishing possible. We will also discuss more recent philosophical work and film on related topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14014,2026,2643,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-320','<div class="desc"> <p>Contemporary health issues often raise deep ethical and theoretical concerns. In this course, we seek to connect philosophical and theoretical work on social justice with contemporary issues in health, such as abortion, trans* health, disability rights, domestic violence, international inequities, and health disparities. As a key component of this course, students will partner with a community organization for a semester-long research project, identifying an issue of practical importance to that community and offering an original, theoretical analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14015,2026,2809,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-321','<div class="desc"> <p>James Baldwin explored, with extraordinary sensitivity and insight, issues of race, poverty, and sexual difference in America. In this course, we will engage with Baldwin’s essays, novels, and plays, together with related philosophical work and film, in order to explore the some of the main philosophical themes in Baldwin’s work. We will focus on the roles that love, truth-telling, and self-knowledge play in living a morally good life and in creating a just society.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14016,2026,2935,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-322','<div class="desc"> <p>This course examines philosophical reflections on the Latinx experience, focusing on the contributions of US philosophers of Latin American decent. A sample of questions to be considered: What does it mean to be authenticallyLatinx? Is Latinx identity a racial, ethnic, or political identity? How do Latinx philosophers fit into the "canon"? What are some of the overarching lessons of Latina feminist philosophy? Are Latinxs, particularly immigrants, a threat to âAmericanâ values, as some argue? What is the meaning of âLatinxâ and why is the âxâ important? Is Latinx philosophy unique, distinctive, valuable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14017,2026,3221,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-323','<div class="desc"> <p>What is language, and where does it come from? What is it to know something, and how can we achieve knowledge? What is the nature of reasoning, and how should we discern good argumentation from bad? Philosophers of the medieval Arabic-Islamic tradition, such as al-FÄrÄbÄ«, Ibn SÄ«nÄ, and Ibn Rushd, proposed detailed answers to these and other related questions, grounding their proposals in powerful arguments. By adopting a broadly Aristotelian framework, but going well beyond its confines, these figures paved the way for later European Latin philosophy, which borrows heavily from their insights. We''ll study those insights and their reception in this class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14018,2026,4042,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-324','<div class="desc"> <div><p dir="ltr">The philosophical texts of Daoism prize simplicity and naturalness, as exhibited in the metaphor of the unhewn block. This course will explore philosophical themes in Daoism, including transformation and the cycles of nature, the distinctions between humans and nature, how the Daoist ruler governs, and the limits of knowledge and language. The course will also discuss Daoist religious movements that build on these foundational texts and ideas.</p></div> </div>','At least one other philosophy course. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14019,2026,685,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-330','<div class="desc"> <p>This course is an examination of the relationship between law and morality. It is organized around three questions: (1) What is law, and what is the relationship between law, morality, and democracy?, (2) Is there a moral obligation to obey the law?, (3) Can we morally enforce the law, that is, is punishment morally justifiable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14020,2026,3687,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-331','<div class="desc"> <p>Technology is rapidly progressing, raising new and difficult ethical problems. Should a self-driving car kill its driver to save a pedestrian? At what point does a system like ChatGPT exhibit sentience, and are we nearing that point? Is it possible to design algorithms which treat all people fairly, including facial recognition software used by police? Are we comfortable with the emergence of autonomous weapons, e.g. drones which bomb their target without a human pulling the triggers? In this course, we will explore and engage with a variety of ethical issues raised by new technologies, using this as a chance to explore substantive philosophical questions about ourselves, our society, and our relationship with our future robot overlords.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14021,2026,3284,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-332','<div class="desc"> <p>Ethical issues arise in all aspects of public health. Some questions we may explore are: what are health disparities and what makes them unjust? Should individuals be held responsible for areas of public health concern, such as smoking and obesity? When should the state mandate vaccines? How can and should public health norms impact areas of our lives, such as sexual behavior and birth control? Is public health ableist? <em>This course satisfies the Philosophy Department Experiential Learning Requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14022,2026,4326,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-341','<div class="desc"> <p>The course will cover such topics as whether space and time exist, how we know what the geometry of space and time is, whether any sense can be made of the claim that time has a direction, and the "paradoxes" of time travel. We will examine these questions in the context of both pre-relativistic and relativistic theories. The readings will range from historical figures such as Newton, Leibniz and Mach to contemporary work by both philosophers and physicists including Hawking, Feynman, Thorne and Sklar. This course does not require previous exposure to Special or General Relativity and will not require as a prerequisite technical skills that go beyond high school mathematics and physics, but students are expected to be comfortable with algebraic and geometric reasoning.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14023,2026,2697,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-342','<div class="desc"> <div><p dir="ltr" style="line-height: 1.2; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">We care about knowledge because it helps us get around in the world, and because we are social creatures who rely on other people, and we want to allow them to rely on usâand so we need to be able to discuss our reasons for doing and believing as we do. This course examines the individual and environmental conditions necessary for a person to have knowledge, addressing themes of justification and responsibility, processes of belief formation, types of beliefs (beliefs based on inference, perception, and testimony), and social conditions on the creation of both knowledge and ignorance. It will address questions like: Are there some beliefs that count as knowledge simply because they seem clearly true to us? Should we trust our perceptionâis it responsible to do so? Is it responsible to trust others by default? Can we have knowledge simply by being responsible, if our beliefs are true? How does membership in cultural groups facilitate or impair our having true beliefs, and should that lead us to challenge and complicate individualistic conceptions of knowledge? Answers to these questions will illuminate facts about our lives as social beings, including the impact of our social positions on what we know and believe. </span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14024,2026,3817,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-343','<div class="desc"> <p>Human beings are (as far as we know) the only species that uses language, and (as far as we can tell) the only species that engages in at least certain kinds of thinking. But how are the ability to think and the ability to use language related to each other? This class will examine the relationship between language and thought from a number of different perspectives. How does language affect thought? Are there kinds of thinking that are aided or made possible only by language? Does the language you speak affect how you think, or what you can think about? What can the tools and techniques that we use to study language tell us about the structure of thinking (and vice versa)?</p> <p>This course fills the Mind and World distribution requirement for the Philosophy Major.<br/> This course fills the Philosophy Distribution Requirement for the Cognitive Science Major.</p> </div>','N/A ','N/A',NULL);
INSERT INTO course_descriptions VALUES(14025,2026,2681,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-344','<div class="desc"> <p>What is a language? And what is it to know, to speak, or to understand a language? This class will investigate the project of developing a systematic and comprehensive theory of linguistic meaning: what resources such a theory requires, what kinds of claims it makes, and what consequences it has. We will proceed by examining philosophical questions about the role translation between languages plays in a theory of meaning, about the nature of linguistic reference to the world, and about whether the notions of language and meaning are ultimately coherent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14026,2026,961,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-345','<div class="desc"> <p>How is it possible to study the mind scientifically? This class will explore philosophical issues about the application of scientific methods to cognitive phenomena, including questions such as the appropriate architecture of cognition, the possibility of artificial intelligence, the relation between commonsense psychology and theories in cognitive science, and the possibility of a scientific understanding of consciousness.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14027,2026,4327,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-346','<div class="desc"> <p>The course will focus on contemporary readings that raise some of the most fundamental questions about the nature of our conceptions of reality. The following questions are among those that will be addressed: Can we make sense of the idea that we are free agents? Can we understand the concept of causation? Is there a compelling argument for the existence of God? Is there any sense to be made of the claim that some claims are true by necessity while others are only contingently true? Are there true mathematical claims?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14028,2026,2936,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-347','<div class="desc"> <p>Imagination plays important and varied roles in human life, from understanding what someone else is thinking, to creating works of art, to deciding among different potential courses of action. This course will explore philosophical questions about the nature of imagination, including its relationship to belief, desire, perception, and memory, as well as those about its proper use and value, especially in aesthetics and moral/political life. Readings will be drawn from the work of both historical and contemporary philosophers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14029,2026,686,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-350','<div class="desc"> <p>This course surveys results in the metatheory of first order logic including consistency, completeness, decidability, and undecidability.</p> </div>','PHIL 150 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14030,2026,301,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-360','<div class="desc"> <p>What makes something, someone, or some place beautiful? Why do we value beauty? These questions will be explored across multiple domains, including: art, the natural world, the built environment, and human practices, including norms for human bodies. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14031,2026,2682,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-361','<div class="desc"> <p>Philosophical curiosity begins in childhood: Where do words come from? Can trees think? What is love? At the heart of this course, Occidental students will have the opportunity to teach philosophy to elementary students at a local school. Doing so provides both an opportunity to serve the local community, an opportunity to reconnect with our own philosophical impulses, and a chance to reflect deeply on a variety of philosophical topics (such as friendship, courage, minds, justice). Occidental students will develop and teach their own lesson plans. Students in the class will also gain familiarity with philosophical views on young children and the nature of education, e.g. What status should children have in our society? Should children always be subservient to adults? How might our educational practices develop or stifle our creative natures? This course satisfies the Experiential Learning requirement for the philosophy major. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14032,2026,2698,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/300/phil-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements and different Philosophy major requirements.</p> <p><strong>Disagreement, Arrogance, and Ending Oppression</strong></p> <p>This course investigates personal attitudes towards disagreement; it examines how these attitudes can fuel race-, gender-, disability-, or sexuality-based prejudice and associated forms of oppression; and it thus considers means of eradicating these social ills. A portion of the course focuses on epistemic vices like arrogance, which tend to make it difficult for people to credit the value of opposing views. Then we turn to examine whether a person can, through the recognition of disagreement alone, come to identify their vices and ameliorate them, and if not, what other approaches might be effective. We will also meet with scholars currently working on related issues in order to learn about and discuss their work.</p> <p><em>This topic will count toward the Mind and World requirement for the Philosophy major. <em>This topic will satisfy the Core Program U.S. Diversity requirement.</em><br/> </em></p> <p><strong>Metaphor and Figurative Language</strong></p> <p>Metaphorical and other figurative uses of language are a pervasive part of our linguistic life. However, most systematic philosophical study of language has focused primarily on the literal meanings of linguistic expressions, with metaphor occupying a peripheral place. But what is the difference between literal and figurative uses of language? How do we produce, interpret, and understand metaphors? And is metaphor a primarily linguistic phenomenon, or does it extend into other areas of cognition as well? In this seminar we will discuss historical and current approaches to metaphor in philosophy and related disciplines, and we will meet with scholars currently working on these issues to learn about and discuss their work.<br/> <br/> <em>This topic will count toward the Mind and World requirement for the Philosophy major.</em></p> <p><strong>When Race is “Other”: In-Between and Outside of U.S. Race Categories</strong></p> <p>About 1 in 10 Americans identifies as more than one race. This group includes those who have parents of two or more races (e.g., one parent who is Black and one who is White, one parent who is Asian and one who is Pacific Islander, etc.), as well as some Latinx Americans. In this course, we will ask: what can be learned by centering the experiences of those who live “in between” race? Can one have racial privilege in some respects, but not others? Can one identify with a race, even if one ‘passes’ as something else? Why do so many American discussions of race proceed as if this group does not exist? Our course will draw on texts in philosophy, sociology, and literature, as well as the knowledge of guest speakers from Los Angeles and beyond.</p> <p><em>This topic will count towards the </em>Self &amp; Community<em>requirement for the Philosophy major. This topic will satisfy the Core Program U.S. Diversity requirement.</em></p> <p><strong>Philosophy of Food </strong></p> <p>The aim of this course is to demonstrate that food is worthy of philosophy inquiry. We will start with the deceptively simple question, what is food and why is it important? We will quickly move on to specific questions concerning the aesthetic value of food (can food be a work of art?), the nature of food criticism (who am I to tell you what you should like to eat?), a cluster of ethical questions concerning the production and consumption of food (e.g., what exactly is wrong with GMO?, what’s the connection between patriarchy and eating meat?, isn’t ethics fundamentally a question about hospitality?), and broad questions about food and cultural identity (what exactly does “authentic Mexican” mean?). Like any good philosophy course, the point is not to flatter your taste, but to change it, which we will do by cooking together and talking to a number of local food writers and philosophers.</p> <p><em>This topic will count towards the</em> Experiential Learning <em>requirement for the Philosophy major.</em></p> </div>','One course in philosophy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14033,2026,302,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/400/phil-490','<div class="desc"> <p>Open only to students with senior standing in philosophy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14034,2026,4328,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phil-philosophy/400/phil-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14035,2026,4329,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-101','<div class="desc"> <p>Exploration of physical laws and processes through simple and geeky-cool devices and demonstrations many of which students will build themselves and keep. The toys will illuminate topics from across physics including classical mechanics thermodynamics electricity and magnetism. Course Fee: $125.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 125, or PHYS 230; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14036,2026,4003,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-102','<div class="desc"> <p>A survey of the solar system, stars and stellar evolution, galaxies and cosmology. Students are expected to have a strong understanding of algebra and trigonometry. <span style="background-color: #ffffff; color: #222222;">Physics majors cannot take this course for credit toward the Physics major.</span></p> <p><span style="background-color: #ffffff; color: #222222;">Students are expected to have a strong understanding of high school Algebra.</span><s></s></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14037,2026,4004,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-104','<div class="desc"> <div> <p>A concept-based course on the fascinating subject of light designed for non-science majors. Topics include optics, waves, polarization and the modern view of light. In addition, applications</p> <p>will cover optical instruments, photography, color and the human eye. Identical in all respects to PHYS 105 except that there is no lab component. </p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14038,2026,4005,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-105','<div class="desc"> <div><p>A concept-based course on the fascinating subject of light designed for non-science majors. Topics include optics, waves, polarization and the modern view of light. In addition, applications </p><p>will cover optical instruments, photography, color and the human eye. Includes a three-hour laboratory per week.</p></div> </div>',NULL,'PHYS 105L ',NULL);
INSERT INTO course_descriptions VALUES(14039,2026,316,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-106','<div class="desc"> <p>Our view of the physical world changed radically with the advent and development of relativity and quantum mechanics. This course is an introduction to the scientific and epistemological revolutions of 20th century physics, together with some of the discoveries and technologies which resulted. Specific topics may include: the physical structure of space and time; time dilation and length contraction; the global positioning system; fundamentals of quantum mechanics; quantum entanglement and teleportation; nuclear physics; quarks and leptons; big bang cosmology and the early universe. Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 125, or PHYS 230; or equivalent.</p> </div>','This is not a calculus-based course. The needed math background extends merely to algebra and trig. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14040,2026,4330,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-108','<div class="desc"> <p>This course introduces the physics of energy and energy conversions. The goal of this course is to provide students with the tools to recognize and quantify the various energy conversion processes important to society. Fundamental concepts of conservation of energy efficiency work and heat will be introduced during the first half of the course. These concepts will provide a framework for topical information on global energy resources (renewable and nonrenewable) energy generation systems and societal energy demands.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14041,2026,694,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-110','<div class="desc"> <p>Covers classical mechanics including kinematics and dynamics of particles and rigid bodies conservation laws and examination of specific force laws. <em>Includes one three-hour laboratory per week.</em></p> </div>','Calculus 1 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14042,2026,318,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-115','<div class="desc"> <p>The first of a two-course introduction to physics designed for life science and premedical students. Topics include Newton''s laws of motion gravitation work and energy conservation laws. Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</p> </div>','Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14043,2026,1617,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-117','<div class="desc"> <p>An introduction to the physics of waves with examples from optics acoustics and modern physics. Also an introduction to thermodynamics including the first and second law of thermodynamics kinetic theory heat transport and phase transitions. Includes one three-hour lab per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14044,2026,696,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/100/phys-125','<div class="desc"> <p>The second of a two-course introduction to physics designed for life science and premedical students. Topics include electrostatics and electromagnetism electric circuits geometrical and physical optics. <em>Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</em></p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14045,2026,4331,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-200','<div class="desc"> <p>An introduction to fundamental concepts in astrophysics. Topics include the fusion of elements in stars, stellar remnants (white dwarfs, pulsars and black holes), supernova, the Milky Way, other galaxies, and dark matter. This course will revisit the principles of physics needed to interpret astronomical observations. </p> </div>','PHYS 110 and PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14046,2026,4332,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-201','<div class="desc"> <p>An introduction to the numerical solutions of problems in physics. Applications are drawn from classical dynamics electrostatics magnetostatics relativistic dynamics and chaotic systems.</p> </div>','PHYS 110 or PHYS 115 , PHYS 125 or PHYS 230 , and COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14047,2026,4333,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-202','<div class="desc"> <p>Theoretical and experimental electronics fundamental to modern research. Includes one three-hour laboratory per week.</p> </div>','PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14048,2026,4334,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-203','<div class="desc"> <p>A laboratory based course covering the C programming language the LabWindows CVI programming environment and the use of D/A and A/D converters.</p> </div>','PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14049,2026,4043,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-204','<div class="desc"> <div><p>Topics include: Fundamentals of discrete-state quantum mechanics; Bits vs qubits; the no-cloning theorem; entanglement and EPR states; teleportation; quantum encryption; Bellâs inequality and non-local correlations; interpretations of quantum mechanics; quantum logic gates; and quantum algorithms.</p></div> </div>','MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14050,2026,4335,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-205','<div class="desc"> <p>An introduction to the fundamental constituents of matter and their interactions. Topics include quarks and leptons; symmetries and conservations laws; special relativity; the fundamental forces and their relationship; and the early universe.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14051,2026,4336,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-206','<div class="desc"> <p>An introduction to the theory of relativity. The first half of the course focusing on special relativity includes discussions of the relationship between space and time; mass and energy; and cause and effect. The second half of the course presents the fundamentals of the general theory of relativity with an emphasis on the physics of black holes.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14052,2026,4337,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-207','<div class="desc"> <p>An introduction to the field of engineering. Students who have completed either of the introductory sequences in physics are well prepared to apply that knowledge to a wide variety of subjects. Applications covered include static equilibrium elastic properties of materials vibrations thermodynamics thermal properties of matter fluids waves and sound DC circuits and AC circuits.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14053,2026,4338,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-208','<div class="desc"> <p>An introduction to the physics of materials used in a wide range of engineering applications. As time permits topics will include the mechanical, elastic, thermal, electrical, magnetic, and environmental properties of metals, polymers, ceramics, glasses, composites, and "green" materials.</p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14054,2026,4339,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-209','<div class="desc"> <p>Special topics in physics selected largely by student interest and requiring no more than introductory physics courses. Possible topics include: variational methods celestial mechanics chaos nonlinear systems. May be repeated for credit. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14055,2026,2835,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-230','<div class="desc"> <p>Introduction to electricity and magnetism electronic circuits electromagnetic induction and Maxwell''s Equations. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14056,2026,699,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-240','<div class="desc"> <p>Introduction to the physics revolution of the twentieth century, emphasizing special relativity and elementary quantum mechanics. Includes the breakdown of classical concepts; light quanta and matter waves; Schrödinger equation and solutions in 1 and 3 dimensions; hydrogen atom, exclusion principle and the periodic table. Other topics include a selection from atomic nuclear particle and condensed-matter physics. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 , PHYS 117 , and PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14057,2026,4340,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14058,2026,4341,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/200/phys-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14059,2026,4342,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-302','<div class="desc"> <p>At the turn of the century a series of discoveries transformed the ancient study of cosmology into a rigorous and well-tested theory of the universe. After a brief introduction to general relativity the equations governing the evolution of the universe will be developed and explored. Evidence in support of this standard model of cosmology and consequences will then be presented including supernovae standard candles the cosmic microwave background big bang nucleosynthesis dark matter and early-universe physics. The course will conclude with a presentation of recent topical subjects in this exciting field of study.</p> </div>','PHYS 117 and PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14060,2026,4343,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-303','<div class="desc"> <p>An introduction to the physics of solids. Topics include free electrons crystal structure lattice vibrations energy bands and the electrical magnetic and optical properties of solids.</p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14061,2026,4344,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-304','<div class="desc"> <p>An introduction to the physics of plasma including charged particle motion in electromagnetic fields plasma waves plasma confinement and non-linear effects. These ideas will be used to understand space and ionospheric phenomena laser-plasma interactions containment of matter and anti-matter and energy generation by controlled nuclear fusion.</p> </div>','PHYS 230 , PHYS 310 , and MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14062,2026,4345,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-306','<div class="desc"> <p>Review of special relativity. Introduction to the fundamentals of general relativity and gravitation with applications to cosmology. Topics include the big bang theory primordial nucleo-synthesis the dark matter problem gravitational red shift and the expansion of the universe stellar evolution and black holes.</p> </div>','PHYS 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14063,2026,4346,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-308','<div class="desc"> <p>A critical analysis of the literature of nanoscience and nanotechnology. This course will examine the chemical and physical properties of quantum dots carbon nanotubes metal and semiconductor nanowires and biomolecules and other nanometer scale structures useful in molecular electronics chemical biology and in building macroscopic structures with tailored properties from nanoscale components. Includes introductory instruction to scanning tunneling microscopy.</p> </div>','PHYS 240 or CHEM 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14064,2026,4347,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-309','<div class="desc"> <p>Special topics in physics selected largely by student interest. Prerequisites vary with subject area. Possible topics include: group theory in physics applications of quantum mechanics in atomic nuclear and particle physics introduction to relativistic quantum mechanics nonlinear pattern forming systems hydrodynamic instabilities superfluidity and superconductivity methods of material science. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14065,2026,324,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-310','<div class="desc"> <p>Survey of the elements of advanced mathematical ideas and techniques typically used in physics. Physical examples and intuition will be emphasized throughout. Topics covered will include Div Grad and Curl; matrices tensors and groups; complex analysis Fourier series and integrals; boundary and initial value problems; and special topics as time permits. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 117 and PHYS 230 ; and MATH 214 (may be taken concurrently with permission of instructor) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14066,2026,325,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-315','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques, including literature search, analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14067,2026,702,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-316','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques including literature search analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14068,2026,326,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-320','<div class="desc"> <p>Motion of particles systems of particles and rigid bodies. conservation laws; coordinate transformations both stationary and moving; Hamilton''s and Lagrange''s equations. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 117 , PHYS 230 , and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14069,2026,703,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-330','<div class="desc"> <p>Electro- and magneto-statics Maxwell''s equations electrodynamics boundary value problems radiation. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14070,2026,705,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-340','<div class="desc"> <p>The foundations of the theory of quantum mechanics with applications to physical systems. Formal development of the postulates of quantum mechanics representation of states angular momentum spin and perturbation theory. Applications include the harmonic oscillator hydrogen atom and Zeeman effect. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 240 or CHEM 305 , and PHYS 310 or PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14071,2026,2354,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-350','<div class="desc"> <p>Connects the microscopic properties of the physical world with its macroscopic properties using classical and quantum statistics. Topics include partition functions classical and quantum ideal gasses classical thermodynamics phase transitions and kinetic theory. Includes one ninety minute laboratory per week.</p> </div>','PHYS 240 and PHYS 310 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14072,2026,2937,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-370','<div class="desc"> <p>This course will provide students with a comprehensive and practical view of energy by investigating physical concepts related the way we use energy, energy sources, and connections between energy and broader systems like climate. Topics will include an overview of energy from a physics perspective with a focus on renewable energy including nuclear, solar, and wind power, fossil fuels, energy storage, and energy conservation.</p> </div>','PHYS 110 , PHYS 117 , PHYS 230 , PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14073,2026,328,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-395','<div class="desc"> <p>Research supervised by a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14074,2026,4348,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-396','<div class="desc"> <p>Off-campus participation (up to full time) in the work of a major laboratory engaged in research and development that involves pure or applied physics. The student will take part in the ongoing technical work of the laboratory under joint supervision by a member of the laboratory''s professional technical staff and Occidental physics faculty. Normally formal application to the laboratory is required and admission may be competitive. Approval of department supervising instructor and the laboratory.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14075,2026,709,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/300/phys-397','<div class="desc"> <p>Supervised investigation by properly qualified students. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14076,2026,1301,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/400/phys-490','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14077,2026,1484,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/400/phys-491','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14078,2026,4349,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/400/phys-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14079,2026,710,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/phys-physics/400/phys-499','<div class="desc"> <p>Supervised investigation by students admitted by the department to the Honors Program. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14080,2026,330,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/100/pols-101','<div class="desc"> <p>This course introduces students to the study of politics the discipline of political science and the development of public policy. Politics involves the study of power influence and ideas in public and private life at the personal local state national and international levels. Accordingly our exploration will examine how power operates in a variety of settings and will include readings in political theory American politics and law comparative politics research methods and international relations. Open to frosh and sophomores.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14081,2026,1670,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/100/pols-120','<div class="desc"> <p>Introduction to the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14082,2026,4350,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/100/pols-130','<div class="desc"> <p>This course is an introduction to the theories and practices of international relations with a focus on the United States and its relations with other state actors. This course will visit all of the important IR theories that help us understand and predict state behavior. These theories will be applied to real-world IR events in order to test their utility.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14083,2026,1423,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/100/pols-140','<div class="desc"> <p>Law shapes the day to day experiences and functioning of individuals, communities, and institutions in multiple ways. This introductory course examines the diverse connections and relationships of law and society. The course will draw on theoretical and empirical perspectives from a diverse range of disciplines (such as legal studies, sociology, anthropology, and political science) to explore law and law’s role within the United States and internationally. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14084,2026,1553,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/100/pols-150','<div class="desc"> <p>âThis is what democracy looks like!â But what exactly<em> should</em> democracy look like? This course introduces students to political theory through historical and contemporary debates over democratic visions and challenges. By engaging with political thinkers across space and time, students will not only learn to study politics with interpretive, normative, and critical approaches, but in that process also rethink and expand on their repertoire of democratic practices.</p><p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14085,2026,712,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/100/pols-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14086,2026,2744,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14087,2026,2480,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-201','<div class="desc"> <p>This course provides an overview of main themes in the development of California state government and the political institutions, social and demographic trends, and public policies that give shape to its politics. We will focus on political theories that help us understand: 1) the major problems facing California and its communities, 2) the economic, social and political forces that have shaped California’s development, 3) the structure and role of government in addressing the state’s problems, and 4) the major participants and stakes in California politics.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 American Politics and Public Policy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14088,2026,1302,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-202','<div class="desc"> <p>This course examines how gender influences who participates in the American political process, from voting to campaigning and holding elected office. The course also examines how public policies are gendered in their design, implementation, and outcomes. The course adopts an intersectional approach, asking how gender interacts with other identities, including race, class, ethnicity, sexual, and disability, to fully understand how ideas about masculinity and femininity shapes access to political power in American society.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14089,2026,1303,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-204','<div class="desc"> <p>Students in this course will analyze historical and contemporary election campaigns in the United States, exploring such issues as the role of money, media, public opinion, voter registration laws, voter suppression, campaign strategy, staffing, and other topics. They will also examine the role of identity, alternative electoral systems and campaign reform options. The course will offer a particular focus on the most current election season, including campaigns for president, Congress, governor positions, and others. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 203 ',NULL);
INSERT INTO course_descriptions VALUES(14090,2026,1424,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States and to assess how these communities seek political empowerment as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life such as the economy the state and the cultural system on the one hand and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States.; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications based on race class gender national origin and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14091,2026,332,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-206','<div class="desc"> <p>This course is an exploration of the historical and continuing significance of race in the American political system. The relevance and role of race in shaping political institutions public opinion political behavior and public policy will be examined. Special attention will be given to theoretical debates surrounding the meaning of race and how this changes depending on political context.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14092,2026,966,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-207','<div class="desc"> <p>This is a course about urban politics that takes Los Angeles as its case study. Because of the pattern of growth in the area Los Angeles is broadly defined to encompass the city the county and the region. Since politics is the study of power we will examine power in the context of the city; who has it who seeks it how has it shifted over time and what consequences result from it being exercised? Significant attention will be paid to the agency of those who have at various times had the least power in the city; how are they represented or not represented how can they influence the exercise of power? Many look to Los Angeles as a paradigmatic city. We will query the appropriateness of this observation as we identify key concepts in urban politics apply them to Los Angeles and then consider how much Los Angeles sets follows or deviates from trends.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14093,2026,1029,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-208','<div class="desc"> <p>Examination of the impact that social protest movements have had on our society -and lessons that can apply to the current period. Case studies of the agrarian revolt (the Populists) the labor movement the women''s movement the civil rights movement the peace movement the student movement the environmental movement and the consumer/neighborhood movement. Topics include: What factors lead people to participate in social movements and political protest? Why do certain historical periods seem to feature large-scale protest and upheaval while others do not? How are social and political movements related to mainstream politics such as elections political parties voting and lobbying? What is the role of leaders activists and organizers? What strategies and tactics do movements employ? What does "success" mean for a protest movement? Do protest movements make a difference in achieving more social justice and changing public policy? In addition to classroom discussion attendance at a weekly film series is required.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14094,2026,713,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-210','<div class="desc"> <p>When we paint a picture in our minds about what American politics looks like, we often think in terms of groups rather than individuals. This is no coincidence– the relevance of an issue, interest, or perspective in any democracy is a function of numbers. And bigger is better.</p> <p>But how, and why? And when, for that matter? </p> <p>How do groups seek to influence American policymakers, and why do policymakers listen? When do policymakers ignore groups, even when they’re big? How do groups form, gain power and momentum, and seek to influence politics and policy? Are interest groups good or bad for American democracy and representation?</p> <p>This course will explore interest group politics in the US through the lens of institutions, Madisonian ideals, and the logic of political action. It will apply new understandings of interest group activity and impact to contentious political issues such as gun control, abortion, civil rights, environmental policy, and income inequality. It will do so at the federal, state, and even local level of political institutions and policymaking. 12 hours of involvement per week; 180 total hours</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14095,2026,714,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-211','<div class="desc"> <p>This course is about the U.S. Congress, arguably the world’s most powerful legislative body and the engine of the American political system. Students will learn about elections, legislative procedure, the committee system, the role of parties, and the health of the U.S. political system. Ultimately, the course will examine how Congress behaves as a collective institution, the incentives that drive the behavior of individual legislators, and the quality of representation voters receive in Congress.</p> </div>','POLS 101 American Politics and Public Policy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14096,2026,3237,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-220','<div class="desc"> <p>From extreme weather events to insurrections, crisis seems to consume politics in the United States and the globe. This course examines political leadership, public policymaking, and public opinion during crisis, identifying how crisis transforms politics-as-usual and what these transformations mean for democratic stability, human rights, and citizen wellbeing. The course will focus especially on the politics and policy of the COVID-19 pandemic, exploring to what extent the coronavirus both is and is not a “regular” type of crisis. Topics include: the concentration of policymaking in the executive branch, with consequences for democratic governance; how crisis shapes citizens’ tendencies towards extremism, polarization, and violence; and how crises differentially affect marginalized social groups—and when governments do and do not consider marginality and intersectionality in crisis response and recovery. Throughout, the United States’ pandemic experience will be compared with that of other countries and world regions. </p> <p>Sub-field: <strong>AMERICAN POLITICS or COMPARATIVE POLITICS </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14097,2026,1485,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-221','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century with a focus on contemporary democratic politics. The course will discuss the historical institutional and social forces that have both accelerated and opposed democratization and will cover topics of current concern to the region including economic development security and the rule of law the design of political institutions human rights and social movements.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14098,2026,3317,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-222','<div class="desc"> <p>Did you know that the party that won a majority of seats in the US House was not always the party that got the most votes? The "simple" electoral system used in most US House elections is the primary cause! This course will explore the role of electoral systems in shaping governance, policymaking, party systems, and election outcomes. Students will primarily focus on comparative legislative elections, meaning comparing the design of election systems across the globe, though presidential elections and sub-national United States elections will also be considered. In this course, students complete a series of in-class exercises, problem sets, and a final paper where they examine election results and calculate several mathematical quantities of interest. These include the Gallagher Disproportionality Index, the effective number of vote-winning/seat-winning parties, logical expectations about the country''s party system based on mathematical models, the allocation of assembly seats at the district level based on election results using proportional allocation formulas, and the allocation of seats to parties under complex electoral systems such as the single transferable vote and mixed member proportional representation. This course counts for the Comparative Politics subfield in the Politics major and satisfies the CMPS requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14099,2026,1620,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-223','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal" "populist" and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems including the United States; and the challenges democracies are facing in integrating formerly marginalized populations including women poor and the indigenous. It will examine the US policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14100,2026,3929,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-225','<div class="desc"> Beginning in the late 1970s, revolutionary movements would shake Central American societies and shape U.S. foreign policy with direct military and covert intervention in the region. Often framed as the final battleground of the so-called Cold War between the U.S. and the Soviet Union, scholars of Central America prefer to emphasize the complexity of internal social and political forces and the U.S.’s continual efforts to undermine national sovereignties and control anti-capitalist and anti-authoritarian movements in its “back yard.” This course will allow students to examine the historical formation of three distinct militarized and antidemocratic states, Guatemala, Nicaragua, and El Salvador, and the revolutionary movements that sought to radically engage in social transformations between the 1970s and 1990s. Principal themes of the course include: capitalist development and structural inequalities; revolutionary ideologies; organizational development and objectives of Central American revolutions; US interventions; social transformation and change; and lasting impacts of revolutions. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14101,2026,715,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-226','<div class="desc"> <p>This course is an introduction to 20th Century Chinese politics. The course will explore the historical background to the current Chinese situation. Students will also examine the politics of China under Mao and during the subsequent reform period including the role of China in global politics.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14102,2026,1305,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-227','<div class="desc"> <p>A comparative analysis of the history culture and contemporary politics of the four countries in the dynamic East Asian region: China Japan Korea and Taiwan. This course will also cover the political economy of the East Asian industrialism.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14103,2026,1031,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-233','<div class="desc"> <p>This course is an introduction to international security and strategic studies. This field is fundamentally about both the use of force by and violent conflict among states and non-state actors. The course will be guided by general theoretical questions regarding security: How does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: How do states and non-state actors use force to persuade their enemies to take (coercion) or refrain from taking (deterrence) a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure the intensity duration and consequences of military action? We will have a particular focus on emerging transnational security issues intra-state security and the relationship among security development and state failure. Pursuing answers to these questions will require an approach that integrates theory history and current events.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14104,2026,1082,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-235','<div class="desc"> <p>This course focuses on the evolution of U.S. foreign policy in recent Administrations with special emphasis on the post-Cold War period. Attention is paid to American policy toward "emerging issues" for example the global environment development policy in the North/South dialogue ethnic violence and nationalist civil wars human rights and humanitarian relief. It explores how policy is formulated and implemented and analyzes the relationship of foreign policy to American economic and defense policies. It examines U.S. policy toward major regional power configurations-in Europe the Far East Latin America the Middle East South Asia and Africa.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14105,2026,3318,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-236','<div class="desc"> <p>Effectively tackling global challenges such as climate change, pandemics, nuclear proliferation, and the decline of democracy and trade liberalization, to name just a few examples, is not reducible to the interests and preferences of the United States. Indeed, most outcomes in global politics never are and have never been. Other countries have interests and preferences of their own, and those influence international outcomes as well. Why, for instance, does it make sense for North Korea to have a nuclear arsenal despite US interests to the contrary? And for China to try to become a hegemonic power in East Asia despite the US decades long presence in the region? Why is Putin''s Russia pushing so hard against NATO’s eastward expansion? And Latin America against U.S. influence in the Western Hemisphere? International affairs look fundamentally different when assessed from a non U.S.-centered perspective. And, history shows, U.S. interests are best served when, at the very least, take into consideration other actors'' interests and preferences and where these may come from. This course will provide students with the analytical tools necessary to start unpacking any country''s interests and foreign policies, as a first step towards recognizing that satisfactory answers to current and future global challenges require the active acknowledgment of all actors'' preferences with stakes on the matter, no matter how "powerful" the United States might be.</p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14106,2026,716,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-241','<div class="desc"> <p>This course provides a multi-disciplinary insight into various aspects of migration and immigration law and politics. Students read and analyze important legal precedent through the study of case law as well as explore historical trends in migration to the United States. This course approaches the issue of immigration from three major standpoints: the legal, the political, and the historical. Topics include but are not limited to immigration from Latin America, asylum, temporary protected status and citizenship. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14107,2026,2355,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-243','<div class="desc"> <p>An introductory examination of the values, principles, and practices of restorative justice. The course will draw on examples of restorative justice from the United States and internationally. Topics in the course will include competing theories of justice, informal and formal approaches to restorative justice, truth telling, reconciliation, and process of reintegration. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14108,2026,335,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-244','<div class="desc"> <p>This course provides an introduction to constitutional law and constitutional theory examining the ways in which the Constitution distributes power among the branches government in the American political system and limits the exercise of those powers. The course will also consider the role of the judiciary in creating legal and political boundaries for society. Throughout the semester this course will focus not only on legal doctrine but also on the broader intellectual and political context in which it evolves. Using constitutional law cases and moot courts the course will explore the role of the United States Supreme Court as a civil liberties policymaker and the process through which decisions are reached. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14109,2026,719,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-245','<div class="desc"> <p>An intermediate course in constitutional law and theory with a focus on how the Constitution protects individual rights while accommodating the often-competing claims of state, groups and communities. Much of the course will be dedicated to the jurisprudence surrounding the 14th Amendment and the rights it has been found to protect. Specific rights and liberties covered may include racial equality, reproductive autonomy, freedom of expression, and freedom of religion. Students will be assessed primarily through mock judicial opinions and analytical essays analyzing controversies in constitutional interpretation. Disputes over rights and liberties will be treated not solely as legal questions, but as entry points into enduring questions about the character of the American system of government. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 or POLS 140 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14110,2026,4351,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-247','<div class="desc"> <p>This course engages students in critical examination current term United States Supreme Court cases. The course places questions of doctrine and theory in historic social and political contexts. Student are required to co-lead class sessions and have the option with permission of instructor of selecting readings the mode of analysis for the session. In addition to co-leading a class session students are required to write a series of short analytic papers of the cases discussed and a final research paper. <em>Open to sophomores, juniors, and seniors only.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14111,2026,4352,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-248','<div class="desc"> <p>This course introduces students to the art of oral argument using legal theory and Supreme Court precedent. Students will work with a teammate to prepare oral arguments and also develop skills for debating constitutional issues in a competitive environment based on a yearly prompt issued by the American Moot Court Association and its pre-defined set of Supreme Court cases. This class will ask students to prepare arguments on both sides of an issue and also to learn strategies and techniques to succeed in sparring rounds with classmates and at regional and national tournaments. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14112,2026,4353,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-249','<div class="desc"> <p>This course examines United States social and political movements (e.g.,civil rights, feminist, labor, LGBT rights, domestic human rights, and conservative movement for religious liberty, economic freedom, and property)to understand their diverse influences on the construction and interpretation of law. The course pays particular attention to role of lawyers within social movements, including advocacy strategies defined under the theories of critical lawyering, movement lawyering; law and organizing; demosprudence; and cause lawyering. The course will examine the manner in which movement lawyers and the movements they support aim to alter power in a democracy and generate new normative frameworks within the United States. For example, students will interrogate how law and lawmaking is an expression of political values, identities, and institutions.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14113,2026,1621,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-250','<div class="desc"> <p>American intelligence has often been at the center of the major national security controversies since the 1945. This course will survey the history of those controversies as they involved the US intelligence community, the outbreak of the Cold War and the US-Soviet competition but also the post-Cold War crises in Europe Asia Middle East and elsewhere. The basic question is: How does intelligence influence foreign policy and strategic decisions? This course provides an overview of the theory and practice of U.S. intelligence. It details the sources and methods used by collectors the nature of intelligence analysis and the complex and often difficult relationship between intelligence agencies and policymakers. It also contains a short history of the U.S. intelligence community and evaluates the ongoing efforts to reform it in an era of greater transparency. <em>Not open to first year students.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14114,2026,1032,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-254','<div class="desc"> <p>This course will examine American political thought as it sets out and responds to the founding of the country. Specifically, we will read the Federalist papers, consider the impact of the American Revolution on the French Revolution, and explore how thinkers have reckoned with the American founding into the 21st century.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14115,2026,1306,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-256','<div class="desc"> <p>This course will introduce students to several core analytical approaches in moral and political philosophy including consequentialism utilitarianism distributive justice freedom autonomy and an ethics of care. Students will apply these approaches to case studies in ethical decision-making in politics and policy and students will weigh arguments in favor or against specific courses of action. As such this course bridges readings in moral and political philosophy with "real world" problems confronted by policymakers and leaders. In evaluating resolutions to these problems students will sharpen their critical-thinking and decision-making skills. This is a course in applied ethics with material drawn both from philosophy and from policy.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14116,2026,969,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-257','<div class="desc"> <p>This seminar surveys the historical roots of modern conservative and libertarian political ideas with particular attention to the persistent tension between tradition and innovation. The purpose of the seminar is to enable students to recognize recurring themes that have shaped political thought and action over several thousand years. Students will be graded on weekly essays and seminar participation.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14117,2026,1486,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-260','<div class="desc"> <p>The Community Law Internship provides students with an experiential understanding of the practice of âcommunityâ or âmovementâ lawyering. The Community Law Internship must be taken simultaneously with POLS 340, where students explore the theoretical foundation of community lawyering by: (1) considering how lawyers and legal strategies have historically contributed to and impeded movements for social justice in the past; (2) exploring concepts and theories of legal liberalism, rebellious lawyering, community organizing, and law and social movements; (3) assessing contemporary case studies of community/movement lawyering practices in Los Angeles; and (4) learning core skills and tactics to align legal strategies with community power-building goals. The Community Law Internship allows students to put this theory to practice. All students enrolled in the Community Law Internship work with a community-based legal organization for a minimum of 12 hours each week, working under the supervision of and learning from practicing community lawyers. The unique approach of integrating POLS 340 and POLS 260 exposes students to the law school clinic model and takes advantage of Occidental faculty expertise and the wide-range of community-based educational opportunities available in Los Angeles. Through this integrated examination of the theory and practice of community lawyering, students will build skills and identify strategies to enhance collaboration and strengthen social justice movements in L.A. and beyond. Permission of instructor required.</p> </div>',NULL,'POLS 340',NULL);
INSERT INTO course_descriptions VALUES(14118,2026,722,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14119,2026,4354,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-266','<div class="desc"> <p>This course examines the techniques and strategies used by both professional lobbyists and community based advocates to influence elected and appointed government decision makers. The course will explore the impacts lobbyists and community activists have on decision makers as they consider policy voices. The course will include discussions with elected and appointed government officials well as with professional lobbyists and community advocates. In addition to readings and speakers the course will include case studies in order illustrate the concepts and provide students with real world examples viewed from multiple perspectives. Students will engage in role-plays in order to prepare and present a strategic plan to win support or oppose a community based project or citywide policy.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 or UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14120,2026,1307,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-270','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, POLS 272) simultaneously. Students will participate in the daily activities of a campaign for United States President or United States Senate in a key "battleground" state. Students will gain experience in the highest level of politics and gain an understanding of how a national presidential campaign or a statewide United States Senate campaign is operated. Students will learn about political strategy voter contact and turnout messaging and polling communications volunteer recruitment and team-building fundraising and other key aspects of campaigns. The internship will involve working full-time (a minimum of 40 hours a week) from the first day of class until Election Day. Following that ten-week campaign fieldwork internship students will return to campus and participate in two seminars as part of Campaign Semester. Campaigns involve long hard days. The staff that students will work with will typically be working at least 14-16 hour days. Although students are required to work at least 8 hours a day they are likely to work more. As part of the Campaign Fieldwork Internship students will be required to read three books-biographies of each major party candidate and a book describing previous presidential campaigns. Students will be required to maintain an internship journal that will be handed in at the end of the 10-week internship. The journal will describe their activities (including the projects they work on campaign meetings and events relationship of the campaign to the media and to constituency groups) the internal dynamics and work of the campaign the different roles and tasks of staff and volunteers in the campaigns the way the media reports on the campaign the students'' reflections on these matters and at the end a summary of the campaign outcome. Students will be required to email the supervising Occidental faculty member at least once a week about their activities and reflections. The students will be supervised in the field by a campaign staff member. Students will participate through teleconferencing in a two-hour course meeting with other students and faculty three times during the semester. Students who will be working in different parts of the country will stay in touch with each other as well as with the faculty through Moodle a web-based course management system. The system allows faculty members to post readings facilitate discussions give and receive assignments etc. Students in various parts of the country will thus form a virtual classroom and on-line learning community. Some students may wish to document their experiences on the campaign trail observe events and interview staff and volunteers by making videos. If so these should be posted to the faculty and other students via the internet. Enrollment limited to students participating in the Campaign Semester Program. </p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14121,2026,1308,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-271','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. In this course which will take place during the last five weeks of the semester students explore theoretical and applied concepts pertaining to United States political campaigns. Students will examine the role of money media candidates interest groups leadership gender race and political parties in terms of who wins and loses elections. Learning will take place through assigned readings professor lectures guest lectures from campaign experts and candidates and peer dialogues. Student learning will be assessed by their contribution to the classroom experience (discussion dialogue) discussion of assigned readings and examinations. Enrollment limited to students participating in the Campaign Semester Program. The program is open to all Oxy students regardless of major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14122,2026,1309,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-272','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. This course entails production of a 25-page research essay addressing a major question pertaining to campaigns in American politics. Each student will work with a professor to craft a high-quality research paper that enters the academic debate on their selected topic incorporates extensive secondary data and existing research and presents original analysis based on the student''s campaign fieldwork. Enrollment limited to students participating in the Campaign Semester Program. Satisfies the Second-Stage Writing Requirement.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> <p>Subfield: American Politics</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14123,2026,1343,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-280','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics credits for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> will work four full days per week in an internship in a political office non-profit corporation or for-profit company engaged in political or policy work. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14124,2026,1344,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-281','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course develops leadership skills through the themes of public speaking professional writing networking interviewing and giving and receiving feedback. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirements for the major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 280 and POLS 281 and either POLS 282 POLS 283 POLS 284 POLS 285 or POLS 286) simultaneously. </p> <p>Students enrolled in the Washington Internship Institute in D.C. are required to take a political leadership seminar that explores how active global citizenship can advance career goals. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14125,2026,1554,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-282','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on environmental law and public policy. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(14126,2026,1555,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-283','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on public health policy in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286).</p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(14127,2026,1556,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-284','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on women''s leadership in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(14128,2026,1345,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-285','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on politics and public policy in the Washington D.C. context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(14129,2026,1346,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-286','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on international relations. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills International Relations requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281 and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously.</p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C</strong>. are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(14130,2026,2837,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-287','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> <p>Subfield:<strong> American Politics</strong> or <strong>Comparative Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14131,2026,338,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-295','<div class="desc"> <p>Topics in Politics. Can be repeated once for credit if topics differ.<em>NOTE: Different topics may satisfy different Core Program requirements</em>.</p> <p><strong>The Politics of Climate Change</strong></p> <p>This course will explore the politics around climate change and climate policy, with a particular focus on the energy transition in the U.S. We will analyze the history of U.S. climate and energy policy, and explore how this policy response is shaped by public opinion, executive orders, the courts, federalism, and interest groups. We will also explore more recent climate policies such as the Inflation Reduction Act in depth, and compare U.S. climate policy to approaches in other countries. Finally, we will explore climate politics in the Trump administration, including legislation repealing climate investments and executive orders weakening climate regulations. We will discuss responses from companies and the international community and the decline of climate as a central issue in political discourse. The framework of climate justice will be applied throughout the course, and we will analyze how climate justice can best be implemented through the U.S. political system. Students will study U.S. climate and energy policy to inform class mini-conferences, policy memos, and other assignments. </p> <p><strong><span style="font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: normal; background-color: #ffffff; text-decoration-style: initial; text-decoration-color: initial;">Subfield: </span></strong><span style="font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: normal; background-color: #ffffff; text-decoration-style: initial; text-decoration-color: initial;"><strong>American Politics</strong></span></p> <p><strong>Institutions in Flux: American Politics in the Trump Era</strong></p> <p>This course examines the historical forces that have shaped American political institutions, their role in maintaining the rule of law and informal norms, and contemporary challenges now confronting governing. Topics may include the role of increased partisanship and polarization, legislative stalemate, politicization of the courts, an expanded executive branch, and growing public distrust.</p> <p>Subfield: <strong>American Politics</strong></p> <p><strong>Classical Quest for Justice</strong></p> <p>The questions at the heart of classical political philosophy are very simple, even if the treatments of them by the ancient philosophers are extremely complex. What is justice? What does it ask of us as individuals? What does it demand of political communities with respect to their internal structure and in their interactions with other communities, especially in times of war? Finally, to what extent are the demands of political life compatible with the radical questioning of philosophy? In this course we will engage with these questions via careful study of some of the greatest works of Ancient Greece, focusing principally on Plato’s <em>Republic </em>and Thucydides’ history of the Peloponnesian War. These texts will be approached not only as crucial documents for our understanding of another culture, but also as works that address enduring questions of moral and political life. <em>Core Requirement Met: Pre-1800 (CPPE)</em></p> <p>Subfield: <strong>Political Theory</strong></p> <p style="margin-left: 0; margin-right: 0;"><strong>Comparing Colonial Legacies</strong></p> <p style="margin-left: 0; margin-right: 0;">A comparative analysis of colonial governing practices, processes and modes of decolonization, and their long-term effects on the states and societies of the postcolonial world. Critical questions focused on in this course will include the relative political legacies of different types of colonialism (i.e. settler, exploitative, internal) and different colonial powers, the effects of colonial policies regarding ethnic boundary-making, and the implications of enduring ties of various kinds between the post-colonial states and the former metropole. The geographical scope of this course will be broad, including, but not limited to, Latin America, the former Soviet Union, Sub-Saharan Africa, South Asia.<em> Core Requirement Met: Global Connections.</em></p> <p style="margin-left: 0; margin-right: 0;"><strong>Politics of Development</strong></p> <p style="margin-left: 0; margin-right: 0;">A comparative analysis of the politics and economics of states in the “developing world”, including an introduction to theories that link variation in political systems to levels of economic development. This course will also analyze questions such as the relationship of natural resource dependency to political regime characteristics, the determinants of foreign aid allocations, and the origins and roles of international development organizations. The geographical focus of the course includes Africa, Asia, Latin America, the Middle East, and the former Soviet Union. <em>Core Requirement Met: Global Connections</em>.</p> <p><strong>Reimagining Public Safety: Debates Over Policing and Criminal Justice</strong></p> <p>In the years following the murder of George Floyd by Minneapolis Police, massive demonstrations took place around the nation, demanding an end to police violence and systematic racism. During that moment, many said it was finally time to "reimagine public safety" - a wide-ranging term that encompassed perspectives as varied as police abolition and more robust community policing. It coincided with the rise of a new wave of progressive prosecutors determined to end the "carceral state" and "promote restorative justice."</p> <p>Cities that promised reimagined public safety have experienced what Black Lives Matter co-founder Patrisse Cullors refers to as "The Great Regression," a pro-police, pro-law and order backlash that has seen an increase in police budgets and targeting of progressive prosecutors.</p> <p>How did this happen? What forces shape these policy discussions and political decisions? What is the future of public safety and criminal justice in urban centers? This course will examine these questions, with an emphasis on Los Angeles, with frequent guest lectures, including policymakers, police officials and prosecutors, and community organizers.</p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14132,2026,340,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,'POLS 295',NULL);
INSERT INTO course_descriptions VALUES(14133,2026,968,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/200/pols-353','<div class="desc"> Increasingly people are on the move, but not on equal terms. In this class, we will approach contemporary regimes of movement normatively and critically. While our investigations are anchored in political theory, we will draw from other social sciences and read studies ranging from that of ancient Greeks to those about contemporary Tibetans.<br/> <br/> The first half of the course centers on questions of membership. We will examine the meaning of citizenship, probe into the various membership categories beyond that of citizenship, interrogate the acquisition rules of these membership categories, and question how rights and obligations are distributed across these categories. We will also explore the possibilities of going beyond the nation state, as promised by the idea of cosmopolitan citizenship.<br/> <br/> The second half of the course turns to migration. We will study the debates over whether people should be allowed to migrate across state borders and, relatedly, on what grounds could the state justify their control over borders. We will then attend to the meanings and politics of the categorization of migrants (refugees, asylum seekers, illegal immigrants, economic migrants etc.). Finally, we will ask what rights and obligations migrants have in relation to their home, host, and diasporic communities.<br/> <br/> <br/> This course fulfills the Theory Subfield for the Politics major and minor requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14134,2026,1310,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-300','<div class="desc"> <p>This course is an introduction to the process of conducting political science research including the formulation of research problems research design collection of data and statistical analysis and interpretation. Participants will learn to analyze political science data using statistical packages in a lab setting.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14135,2026,1347,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty housing transportation crime and violence pollution racial segregation and neighborhood change. It also examines how power is exercised by different groups including business citizens'' groups community organizations unions the media mayors and other government officials. The course will also examine the role of city planning and planners conflict and cooperation between cities and suburbs problems of urban sprawl loss of open space water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe Canada and the developing world. Public policies to solve urban problems.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14136,2026,1557,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-302','<div class="desc"> <p>This course examines the institution and practices of the American presidency. More specifically it encourages students to analyze the role and structure of this office as well as different ideas about presidential power and influence. Particular attention is paid to the presidency and policy making media coverage checks and balances the Constitution and public opinion.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14137,2026,3343,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-305','<div class="desc"> <p>Students are introduced to foundational theories of public policy, gaining valuable insight into "who gets what, when, and how" in the political process. Applying theory to case studies, current events, and policy alternatives, students are asked to critically evaluate policy problems and solutions, draft policy briefs, and pen opinion pieces to advocate their policy positions.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14138,2026,1671,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-320','<div class="desc"> <p>Critical examination of the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14139,2026,1623,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-321','<div class="desc"> <p>This course will explore the role of women in politics throughout the globe with an emphasis on case studies from the developing world. Students will examine the development of policy changes that advance gender equality paying attention to how the international system domestic institutions and social movements play in this process. Students will also study how women attain and wield power in local and national politics. The course will further emphasize how gender politics intersects with other forms of identity politics including race ethnicity and sexuality. The course is grounded in the study of comparative politics and will draw primarily on examples from Latin America Africa the Middle East and Asia.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 , POLS 120 , or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14140,2026,1129,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-324','<div class="desc"> <p>This course explores the complex history and development of populist regimes in Latin America from the early 20th century to the present. Through a combination of historical analysis, theoretical frameworks, and case studies, we will examine how populist and nationalist ideologies have shaped and transformed political, economic, and social structures across the region. Key topics include the rise of charismatic leaders, ideological constructions of “us” vs “them,” rhetorical strategies, and the relationship between populism, nationalism, and authoritarianism. We will start with the region’s most well-known populist figures of the 20th century: Brazil’s Getulio Vargas and Argentina’s Juan and Eva Perón. We will then examine more recent figures like Peru’s Alberto Fujimori and Pink Tide figures like Venezuela’s Hugo Chávez, and Bolivia’s Evo Morales. Finally, we will turn to contemporary figures like Brazil’s Jair Bolsonaro, Nicaragua’s Daniel Ortega, and El Salvador’s Nayib Bukele.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14141,2026,4355,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-341','<div class="desc"> <p>Justice Lab is an advanced course for students seeking to examine contemporary justice issues. The course will provide a challenging and intellectually rigorous environment in which students ask not only what are pressing justice questions, but also develop practical tools to address these issues. Students in the course will work in collaborative teams to select issues for the "lab" to address, research all aspects of the issue selected, and coordinate and participate in drafting a series of policy papers and other "tools" for change. The course aims to create an an environment similar to that of a think tank allowing students to refine research, analysis, problem-solving, presentation, and writing skills.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14142,2026,2484,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-351','<div class="desc"> <p>Alexis de Tocqueville, John Stuart Mill, and Friedrich Nietzsche are three of the most influential theorists to grapple with the tradition of liberal political thought. The first two are friendly critics who seek to fortify liberalism against what they see as its latent pathologies, while Nietzsche is a not-so-friendly critic who wants to overturn it entirely. Given that liberalism is under attack today from both the right and the left, there is much to gain from serious study of their reflections. In this course, we will compare the strengths and weaknesses of their diagnoses of the present and visions for the future. Guiding questions for the course will include the following: Does liberal democracy uplift human beings, or degrade them? How should the competing demands of individual independence and community solidarity be balanced? How can we best counter modern society’s tendency to engender stifling conformity? What is the significance of Christianity for the cultural heritage of Western society? What role, if any, should religion play in societies of the future? Finally, what does human flourishing consist of, and what kind of sociopolitical conditions best facilitate it? The culminating assignment of for the course will be a substantial research paper on one or more of these thinkers.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14143,2026,1312,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or BLST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14144,2026,3157,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Climate Policy and U.S. Politics</strong></p> <p>This course will explore the politics around climate change and climate policy, with a specific focus on the U.S. We will analyze the history of U.S. climate and energy policy, and explore how this policy response is shaped by public opinion and polarization, executive orders, the courts, federalism and state actions, and interest group political spending. We will also explore recent climate policies such as the Inflation Reduction Act in depth, and compare them to policy approaches in other countries. The framework of climate justice will be applied throughout the course, and we will analyze how climate justice can best be implemented through the U.S. political system. Students will conduct research on U.S. climate policy to inform policy memos and other writing assignments. This course fulfills the second-stage writing requirement for the Politics major.</p> </div>','Graduate students may not enroll in this class. Frosh students may not enroll in this class. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14145,2026,725,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/300/pols-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14146,2026,726,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/400/pols-495','<div class="desc"> <p>Politics majors are required to take Politics 495 in fulfillment of their senior comprehensive obligation. They therefore should have met or be in the process of meeting all requirements for the major. The Seminar meets in the spring semester but students will be expected to submit proposals for their research papers in the fall semester prior to the actual meeting of the Seminar. The Seminar itself will engage all students in an analytical review of a wide range of materials from various aspects of the discipline and will require that students write a major research paper in one particular sub-discipline of the field. Students qualifying for College Honors will be given an opportunity to write research papers that will be evaluated by the department for honors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14147,2026,4356,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pols-politics/400/pols-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14148,2026,1130,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/100/psyc-101','<div class="desc"> <div><p>Introduction to psychology as the science of behavior. Topics include: physiology, learning, perception, motivation, development, emotion, cognition, social processes, personality, and psychopathology. <em>This course is a prerequisite for all upper division coursework. Core Credit only when taken at Occidental. Students with a 4 or 5 on the AP Psychology exam or a 6 or 7 on the IB Psychology exam are not eligible for Psych 101 but may take 200- or 300-level classes.</em></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14149,2026,1190,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/100/psyc-111','<div class="desc"> <p>The average adult possesses over 50000 concepts ranging from physical concepts like "force" and "density" to biological concepts like "growth" and "reproduction" to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich revise and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive developmental and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14150,2026,4357,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/100/psyc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14151,2026,344,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/200/psyc-200','<div class="desc"> <p>Introduces scientific methodology in the context of psychological research. Basic concepts in scientific inquiry and specific observational correlational and experimental techniques are covered. Includes an introduction to descriptive statistics. This course is a prerequisite to many 300-level courses in Psychology.</p> </div>','PSYC 101 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14152,2026,345,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/200/psyc-201','<div class="desc"> <p>Introduces parametric and nonparametric inferential statistics used in psychological science through analyses of variance appropriate to complex experimental designs. Includes a review of research methods and descriptive statistics and work with statistics software.</p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14153,2026,4358,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/200/psyc-270','<div class="desc"> <p>This course will cover key concepts in nervous system structure and function through the lens of the sensory and affective experience of pain. Students will gain a basic understanding of nervous system organization, evolutionary adaptation, neuronal mechanism of action, sensation and perception, plasticity, and top down processing through the examination of the neuroscience of pain and the clinical experience of pain and its treatment, including coverage of disparate pain treatment on the basis of race and gender. This course will also take an interdisciplinary perspective to pain, considering how it has been represented in literature and philosophy. Although there are no specific prerequisites, the course will include (optional) materials appropriate for students with a deeper background in psychology, biology, neuroscience, and/or cognitive science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14154,2026,347,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/200/psyc-295','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. Instructor permission required. <em>Graded on a Credit/No Credit basis only. PSYC 101 or PSYC 102 or relevant introductory course in another department and permission of instructor. May be repeated once for credit if the second project is different from the first. Instructor permission required.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14155,2026,4359,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/200/psyc-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14156,2026,348,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-321','<div class="desc"> <p>The study of continuity and change across development. Emphasis on application of research methods to issues related to cognitive emotional personality and social development. The course will focus primarily on these issues in infancy and childhood.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14157,2026,350,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-322l','<div class="desc"> <div><p>Must be taken concurrently with Psychology 322.</p></div> </div>','PSYC 101 ','PSYC 322',NULL);
INSERT INTO course_descriptions VALUES(14158,2026,351,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-323','<div class="desc"> <p>Behavior of individuals and groups in and across social contexts. Topics include self social cognition attitudes and persuasion liking and loving prejudice aggression and social conflict group identity consciousness and social action.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14159,2026,352,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-330','<div class="desc"> <p>The study of psychopathology including diagnosis and classification core dysfunctions and physiological and psychosocial causative factors. Intervention treatment and preventative strategies will also be discussed.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14160,2026,736,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-334','<div class="desc"> <p>Consideration of psychological influences on health and illness including health-and illness-promoting behavior and lifestyles cognitive and emotional processes and social and institutional practices.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14161,2026,4360,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-339','<div class="desc"> <p>This course explores the psychological phenomena that surround the optimal functioning of individuals, groups, and systems with an emphasis on scientifically-validated strategies for living a more satisfying life. Topics include gratitude, charitable giving, exercise, breath and mindfulness, habit formation, and other key tenents of positive psychology research. This course will also emphasize applications of positive psychology research to improve our own lives as well as our communities and the planet.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14162,2026,353,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-340','<div class="desc"> <p>Introduction to the study of theories and applications of psychology in profit and not-for-profit organizations. Representative topics include understanding how ability personality perception motivation leadership and group dynamics affect productivity and worker satisfaction. Issues of fairness and accuracy of assessment will also be discussed. Emphasis is on practical and personal learning of the dynamics of the work environment.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14163,2026,354,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-350','<div class="desc"> <p>The course will survey diverse psychological perspectives on gender and its personal and cultural implications. Will explore: meanings of gender evolutionary physiological developmental and sociocultural roots of gender difference; the relation of gender to cognition personality sexuality health interpersonal relationships and political power; the commensurability of various theoretical approaches to gender.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14164,2026,731,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-301','<div class="desc"> <p>This course will introduce general concepts of learning in humans and other animals that will be rooted in the principles of learning developed from nonhuman animal research. Explores fundamental concepts phenomena and principles of learning such as reinforcement Pavlovian conditioning and retention/forgetting. Issues addressed are traditional views of learning biological and cognitive constraints the role of nonhuman animal models and the utility of learning theory.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14165,2026,971,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-302','<div class="desc"> <p>This course focuses on how sensory systems function, with emphasis on quantitative methodologies, neurophysiological mechanisms, structure/function relationships, and ecological contexts. How humans perceive the world is situated in a comparative landscape -- that is, human are assumed to be creatures with much in common with other creatures and yet different in some crucial ways tied to their evolutionary history and habitats. Attention is paid to phenomenology and philosophical issues, such as the relationship between perception and "reality." This course is distinguished from cognitive or social psychology approaches to perception, by virtue of its focus on evolutionarily old, fully embodied, and sensuous experience.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14166,2026,871,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems make decisions draw inferences attend to their environment communicate remember and learn. Much of the material is applied to real-life settings.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14167,2026,2491,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-309','<div class="desc"> Ontogentetic approach to human movement behavior and physical growth from conception to adulthood with emphasis on maturational and environmental factors. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14168,2026,2493,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'PSYC 310L',NULL);
INSERT INTO course_descriptions VALUES(14169,2026,1736,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-311','<div class="desc"> This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance and level of participation of an individual or group. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14170,2026,349,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-322','<div class="desc"> <p>Because the brain and central nervous system are to some degree responsible for all behavior, thoughts, and emotions that humans experience, psychology can be thought of as a biological science. This class is an introduction to that perspective and an exploration of what it means for the study of the mind. Students who enroll in PSYC 322 must enroll concurrently in the accompanying weekly 3 hour laboratory (PSYC 322L). Core Laboratory Science credit will be awarded for students completing both PSYC 322 and PSYC 322L. </p><p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ','PSYC 322L ',NULL);
INSERT INTO course_descriptions VALUES(14171,2026,972,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-336','<div class="desc"> <p>This course surveys the emerging field of Evolutionary Psychology. It begins with the historical social and political context of evolutionary theory reviews tenets of modern evolutionary theory explores the relationship between evolution and other change processes and applies evolutionary reasoning to psychological phenomena and contemporary social issues.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14172,2026,2513,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-351','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','PSYC 101 , COGS 101 , LING 301 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14173,2026,355,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-395','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required.<em>Graded on a Credit/No Credit basis only.</em></p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14174,2026,738,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/psyc-397','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14175,2026,2492,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/300/pysc-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','PSYC 310L ',NULL);
INSERT INTO course_descriptions VALUES(14176,2026,2905,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-420','<div class="desc"> <p>Introduction to the psychosocial and neurobiological basis of addiction. Substance abuse and behavioral compulsions, including drugs, gambling, eating, and sexual addictions are examined. Additional focus on diversity in addicted populations, the business and politics of drugs, and prevention. Consequences of addictions will be studied at the individual, family, community and societal levels. This course will draw on current research and controversies in the field of addictions. </p> </div>','PSYC 200 , and either PSYC 322 , PSYC 330 , or PSYC 334 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14177,2026,873,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-428','<div class="desc"> <p>The study of social cognitive physical and psychological development during adolescence and emerging adulthood. Topics include sexual development and the social consequences of being sexually active the function of family support the increasingly important role of peer relationships drug abuse and antisocial behavior and school adjustment.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14178,2026,357,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-431','<div class="desc"> <p>Introduction to the techniques and processes of clinical psychology and psychotherapy. Topics include major schools of thought and approaches, specific techniques of assessment and treatment, relevant research, assessment of effectiveness, and issues of gender and culture. <em>Open only to seniors or by permission of instructor.</em></p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 and PSYC 330 (Students must earn a grade of C- or better in both) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14179,2026,1349,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-444','<div class="desc"> <p>This course will examine contemporary research on higher-order cognition. Topics will include inductive reasoning deductive reasoning causal reasoning moral reasoning concept acquisition belief formation and analogical inference. Students will read empirical papers representing a variety of experimental methods and a variety of theoretical perspectives.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 200 or COGS 201 and PSYC 301 , PSYC 302 , or PSYC 306 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14180,2026,3914,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-447','<div class="desc"> <p>This course serves as an exploration of the emerging field of canine cognition, the study of thinking and reasoning in domestic dogs. Topics include social reasoning, problem solving, cooperation, communication, and other current focal points of canine cognition research. Additional emphasis will be placed on the role of domestication in shaping modern dogs, effective research methodologies and practices for canine research, implications of canine research for working dogs and responsible pet caretaking, and the future of canine cognition. This course will draw on both foundational and current research in the field of canine cognition.</p> </div>','PSYC 200 and PSYC 336 or PSYC 322 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14181,2026,973,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-448','<div class="desc"> <p>Introduction to and evaluation and application of classic and contemporary theories of personality including psychoanalytic humanistic behavioral cognitive and object relations models. Primary sources autobiographies and case studies will supplement traditional texts.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 , PSYC 323 , or PSYC 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14182,2026,358,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-490','<div class="desc"> <div><p><strong>Psychology of Prejudice</strong></p><p>This course focuses on how we can use social psychological theories and methods to understand prejudice, stereotyping, and discrimination. We will examine how prejudice and stereotypes differ across social groups, why prejudice is prevalent, and what are the origins of prejudice. This course will also examine the ways psychology as a field has contributed to prejudice and how it can be used to combat prejudice.</p><p>Prerequisites: PSYC 200</p><p><br/></p><p><strong>Psychology and Law</strong></p><p>Intersection of social science theory and data with law and legal procedure: Topics may include: normative and psychological theories of justice; eyewitness memory, deception detection, investigative interviewing and interrogations; jury selection and jury decision-making; forensic psychology and assessment; corrections and sentencing.</p><p>Prerequisite: PSYC 200</p><p><br/></p><p><strong>Trauma</strong></p><p>This course focuses on the experience of and responses to trauma in its many forms - natural disaster war and genocide child abuse assault and violence. The impact of trauma for both the individual and society at large are examined in the context of a stress coping resilience framework. Prevention and intervention strategies will be explored.</p><p>Prerequisites: PSYC 330.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14183,2026,3878,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-495','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required. Graded on a Credit/No Credit basis only</p> </div>','PSYC 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14184,2026,3999,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/psyc-401','<div class="desc"> <div><p>This course will support senior Psychology majors as they conduct original research to fulfill their senior comprehensive requirement. Open only to senior Psychology majors.</p></div> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14185,2026,974,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/psyc-460','<div class="desc"> <p>Psychological assessment involves the measurement and evaluation of psychological characteristics including cognitive ability personality traits motivation and more. A blend of theory-driven research and practical analysis techniques will be covered to explain how common and experimental instruments work and to examine whether certain methods are valid in academic organizational criminal and mental health contexts.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 201 ; and PSYC 321 or PSYC 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14186,2026,4361,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/psyc-psychology/400/psyc-497','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14187,2026,4362,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/100/pubh-197','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14188,2026,2838,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-203','<div class="desc"> <p>This course explores the nation''s public health challenges and the ways that public health functions as a combination of science and politics. The course examines the various social, political, and demographic factors that impact population health. Students are introduced to public health concepts and learn to analyze health problems, considering the influence and intersection of race, status, gender, income, education and sexuality. Using data, evidence, and health behavior theory, students evaluate strategies and solutions to address health inequity and improve population health.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14189,2026,2904,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-206','<div class="desc"> <p>Students will conduct a hands-on internship in Los Angeles County, supervised by the course instructor and in collaboration with a community partner, government agency, community clinic, or public health focused non-profit organization. The internship requires 8-hours each week. The topic of the course is flexible and to be determined by the course instructor. It may be repeated once for credit and does not fulfill a Public Health minor elective requirement. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14190,2026,2938,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-209','<div class="desc"> <p>Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14191,2026,3844,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-220','<div class="desc"> <p>Public Health Nutrition involves the application of food and nutrition knowledge, policy, and research to improve the nutritional status and health of populations. This course will examine the role of nutrition as a means of promoting, maintaining, and improving the health and wellness of community populations using evidence-based approaches. Students will explore the relationship between nutrition and the bodyâs systems, including the effects of obesity, diabetes, allergies, and autoimmune diseases. This course will include a brief overview of the causes and treatment of eating disorders and food addiction. At the conclusion of the course, students will understand how to analyze and evaluate nutrition information. The course will integrate skills obtained through practice and experience with external evidence from systematic research regarding nutrition education.</p> </div>','PUBH 203 Introduction to Public Health ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14192,2026,2886,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-238','<div class="desc"> <p>This course is designed to introduce the basic concepts, principles, and methods of epidemiologic research. In our pursuit to understand the interplay of risk factors and patterns of human disease and health, we will cover the history of epidemiology, the principles of epidemiologic thinking and of causal inference, the basic measures of disease frequency and of association, and how to compute them. We will also learn about the major types of epidemiologic study designs and explore the major fields of epidemiologic investigation. To better understand the practical application of study methods used in epidemiology, the class has a laboratory component (PUBH 238L). The laboratory component will provide students with the opportunity to apply the concepts from lecture and develop an epidemiological research proposal. Students will work through the research process, moving from developing a health related research question to operationalizing the idea into a research plan.</p> </div>','Statistics ( BIO 268 , COMP 146 , MATH 150 , PSYC 201 , or UEP 305 ) and PUBH 203 ','PUBH 238L ',NULL);
INSERT INTO course_descriptions VALUES(14193,2026,2839,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-248','<div class="desc"> <p>The course will examine major global public health problems and the range of responses from international organizations transnational networks and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as HIV/AIDS malaria unsafe food and water tobacco use and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health including morbidity mortality demography epidemiology and the political social and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political economic social and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14194,2026,4363,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-249','<div class="desc"> <p>This course explores core concepts in global public health, the development of human rights'' instruments, and how these two fields have increasingly intersected in global and local public health work. Specifically, we will review public health methods of measurement and analysis - spanning epidemiological, economic, and political approaches - to understand if, and how, a rights-based approach to health can inform more critical and more productive approaches to issues such as HIV/AIDS and other sexual and reproductive health concerns. Finally, this course examines how global public health issues have generated dramatically different responses across and within regions, countries, and communities. We will focus, particularly, on the experience of Brazil, given its changing role in the global economy and its progressive public health approach.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14195,2026,4364,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14196,2026,4365,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/200/pubh-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14197,2026,2840,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/300/pubh-301','<div class="desc"> <p>This course provides an examination of women''s health across the life cycle, with special emphasis on the structural and societal factors that influence health outcomes among women. It introduces students to public health frameworks for assessing women’s health issues within various contexts. This course uses these frameworks as a basis for examining the relationship between social and cultural factors and women’s health. It provides an overview of the emerging and on-going issues in women''s health, including sexual and reproductive health, contraception, gender-based violence, mental health and substance abuse, in order to understand and address health inequities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14198,2026,3325,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/300/pubh-303','<div class="desc"> <p>This course introduces students to the unique health challenges faced by sexual minority populations, a group that includes lesbian, gay, bisexual, transgender, and queer individuals. As a public health class, there will be a specific focus on factors that impact health outcomes at the community and population level, paying due attention to the distinct subgroups that make up sexual minorities. Drawing from current and historical examples and case studies, we will examine how cultural, social, and political forces contribute to health disparities in these groups. Through a public health lens, we will discuss the dynamics among behavior, identity, life stage, setting, and environment, and think through implications for health outcomes. Students will assess various determinants of health and consider a range of strategies that could be used to improve health and reduce health disparities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14199,2026,2841,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/300/pubh-307','<div class="desc"> The community health internship course is designed to provide students with real-world experiences to develop new skills and enhance insights into myriad community health issues and solutions. Under supervision of the course instructor and in collaboration with a community proctor/partner students will intern for two, 4-hour days a week at a health focused non-profit organization community clinic or government agency. Through the internship and course work, students explore and analyze the social, cultural, and systematic barriers to health in Los Angeles and the U.S. Students reflect on and discuss the complexities of keeping communities healthy, considering the impact of policy, identity, power, urban planning and culture. Before registering students must check with the course instructor to review their semester schedule and determine how the internship will fit into their school week. Students are encouraged to register early for this course in order to identify partner sites that can support their learning goals. Prerequisite: PUBH 203 or UEP 203 (may be taken concurrently). </div>','PUBH 203 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14200,2026,4366,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/300/pubh-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14201,2026,4367,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/300/pubh-397','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14202,2026,4368,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/pubh-public-health/400/pubh-497','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14203,2026,3319,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/copy-of-rels-121','<div class="desc"> <p>In this course, we will study the various ways in which the devil has been depicted in societies of the Americas since colonialism to the contemporary moment. Considering the devil as both a figure of systemic domination and resistance, we will ask: how is the devil, heathen and demon a pillar of colonial and imperialist legacies? In what ways have these figures been at the hands of the marginalized, not merely as sites of empowerment, but as an active forging of decolonial existences and knowledges? We will seek to answer these questions by closely examining important themes in conjunction with their social(/historical) time periods, including: the âNew Worldâ (colonization and Indigenous resistance of the âheathenâ), the formation of Religious Studies as an academic discipline (Christianity as the dominant religious tradition), feminism (brujerÃ­a (witchcraft)), and popular culture (horror film and television). As major parts of their course assessment, students will have the opportunity to apply what they learned through creative projects such as zine-making and short-story writing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14204,2026,1559,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-110','<div class="desc"> <p>A survey of historical and contemporary Native American religious traditions, attending especially to how they have developed amid colonization and resistance. Students will study the broad variety of ways that Native American traditions imagine land, community, and the sacred, and study the range of practices, ceremonies, and cultural institutions related thereto. Students will also investigate how these religious traditions have been contested or negotiated when they came in contact with Christian missionaries, in contemporary treaty rights, and in intertribal new religious movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14205,2026,3305,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-111','<div class="desc"> <p>This course focuses on displacement as a defining feature of Mediterranean history from antiquity to the present. In the first half of the course, we will study a series of case studies on displaced peoples from antiquity: those who were forced from their homelands because of religious or political exile (including, Judeans, political criminals, sexual deviants, and heretics), because of natural disaster (including, those stranded by shipwreck or relocated by earthquakes, drought, or famine), or because of war (including, prisoners of war, and refugees). Through these case studies, we will attend to how ancient folks described their experiences of displacement, their expressions of grief and longing for home, their unique vulnerabilities in new communities, as well as the care and hospitality extended to them. In the second half of the course, we will move forward in time to see how more modern displacements across the globe have been figured in terms of ancient precedents (such as, an odyssey or exodus), and we will query the conceptual resources such precedents provide in coping with and navigating displacement. Finally, we will study the acceleration of displacements in the Mediterranean region within the last decade, and students will engage in a social justice project related thereto. This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14206,2026,3847,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-113','<div class="desc"> From <em>The Golem</em> to <em>The Exorcist</em> to <em>Raaz</em> to <em>A Girl Walks Home Alone at Night</em> to <em>Midsommar</em>, the horror genre has engaged religious traditions'' notions of the supernatural, the monstrous, the evil, and the terrifying. Studying horror films, music videos, comics, and short stories, this class will historically contextualize examples of ''religious horror'' so we better understand how different religious communities conceptualize the horrifying, the supernatural, and the monstrous. Throughout our study, we will engage the relationship between religion and horror through four major categories: religion in horror (how are religious communities, myths, rituals, monsters, fears, and ideas interpreted within the horror genre?), horror in religion (where does the ‘horrific’ appear in religion? What monsters and utmost evil appear within religious communities? How are otherworldly / supernatural beings depicted in ways that are understood as different / nonhuman?), horror as religion (how do horror narratives spawn their own religious communities?), and religion &amp; horror in dialogue (How do religion and horror speak to each other to form one another? How is this a reiterative process of creation and remaking with respect to ghost hunting, possession narratives, and cryptozoology?). Through these categories, we will investigate how horror leverages the monster as a practice of dehumanization and marginalization (religious stereotypes often entwined with features of race, class, gender, sexuality, nation, and post/coloniality). In focusing primarily on mostly U.S.-made films, this course will ultimately interrogate how the themes of religion and horror reflect larger structures of U.S. culture and power and the inevitable existential anxieties that accompany them. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14207,2026,741,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-120','<div class="desc"> <p>This course is centered around the question: How can we be "well" when the world is beset by the existential issue of climate change? To answer this question, students will study cosmological systems that conceive of human health as fundamentally connected with ecological health, and consider how these systems are responding to the challenges of climatic variability. Specifically, cosmologies from the Asia-Pacific region – where climate change have already fundamentally altered daily life in the form of receding glaciers and flooding islands – will provide students with an insight into how religions and cultural traditions conceptualize health and multispecies flourishing in the face of impacts from climate change that threaten multiple species across ecosystems. The course will be organized around case studies related to land, ocean, mountains, and space, with examples from multiple religious and cultural communities from the Pacific Coast of the United States, to Hawai’i, Tuvalu, Aotearoa New Zealand, Thailand, India, China, and Bhutan. And these case studies will cover examples from multiple moments of the Anthropocene, from the Little Ice Age that began in the fourteenth century CE to the present, as well as incorporate interdisciplinary research from the environmental Humanities, such as anthropology, environmental ethics, political ecology, and religious studies. This course will allow students to see how different cosmologies – both Indigenous and imported – provide people with holistic notions of health, explanations to understand the enormous changes brought by the Anthropocene, and to explore and develop resources for enacting measures that will bring about justice that can benefit human communities and the environment.</p> <p>This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14208,2026,360,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-130','<div class="desc"> <p>A truism in Jewish Studies says: if you want to study Jews, you have to study the world. While this course does not require knowledge of the entire world, it will offer you the exciting and challenging invitation to study Jews as an often minority population with international impact and significance. Within such an expansive aperture we will focus on the narrativesâboth ancient and contemporaryâthat have proven themselves most resonant and subject to discourse for Jews. Joining this discourse ourselves we will not merely learn dominant Jewish narratives which respect to, for example, the Hebrew Bible, exile, and the history of Jews of European origin (Ashkenazi Jews). We will also consistently complicate and subvert these narratives with the help of Jewish feminist and queer voices as well as perspectives and histories from Jews who have not gained dominant privilege from an afforded proximity to whiteness, mainly Jews with origins in the Middle East-North Africa (Mizrahi Jews) and Spain (Sephardi Jews). By the end of the course students will be more adaptable thinkers who are able to be inspired by the wide aperture of Jewish experience and identities in order to further expand the diversity and dynamism of Jewish narratives rather than limit them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14209,2026,1035,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-145','<div class="desc"> <p>For this introductory course, we will utilize the themes of myth and ritual to guide us through a historical survey of religion in America. Focusing on the United States with some broader geographical considerations, we will ask: how have people come to understand religious/spiritual narratives and practices, especially in regard to (re-)enforcing and/or challenging social authority? Why does religion remain an enduring human phenomena, especially in the American context? We will seek to answer these questions by closely examining important themes in conjunction with their social(/historical) time periods, including but not limited to: Indigenous spiritualities and epistemologies, the rise of Protestant Christianity as the dominant religious tradition, and growth of new religious movements. Throughout the course, we will consider how religion intersects with various social constructs including race, gender and class in order to learn how religion continues as a site of liberation and oppression. As major parts of their course assessment, students will have the opportunity to apply what they learned through zine-making that illustrates an original research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14210,2026,1624,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-147','<div class="desc"> <p>In the recent history of the Americas, many groups have founded intentional communities shaped by the ideals of what a faithful, utopian society ought to look like. Some aspiring utopias, like that of the People''s Temple in Jonestown, Guyana, ended in dramatic displays of violence and death. Others, like the Mormons in Salt Lake City, have succeeded in the face of sustained adversity. But most land somewhere in between, sustaining themselves through partial integration with dominant society. In this course, we will study different intentional religious communities - often called "cults" or "sects" by outsiders - throughout the Americas. As we study the Oneidan "free love" community, an ayahuasca church in Brazil, an early Rastafari group in Jamaica, we''ll ask questions like: Why have religious people sought to separate themselves from society? How have they appealed to scripture or revelation to justify their separation? What challenges - such as external political pressure or internal strife - have they faced? What groups have been "successful," and what are the measures of success? And what do these attempts at establishing utopias tell us about what it means to be religious?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14211,2026,742,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-150','<div class="desc"> <p>This course will introduce students to some of the major themes, issues, people, places, sights, and sounds of Islam past and present. This course is intended to highlight the manifold expressions of Muslim life through diverse historical, cultural, and geographical contexts. Its two broad aims are: 1) to provide students with basic knowledge of Islamic history, belief, and ritual life; and 2) to equip students with knowledge for critically and actively analyzing discussions of Islam in media and contemporary world events.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14212,2026,1673,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-160','<div class="desc"> <p>A large part of the success of Buddhism has been in its ability to travel and adapt to local cultural traditions, providing communities with a rubric for living a meaningful life. This course will provide an introduction to these traditions by looking specifically at Buddhist concepts and practices within human life and life cycles. We will ask: What do ritual and textual traditions about human life in various cultures tell us about Buddhist values and concepts of how to deal with suffering and thereby to life and die well? Are there differences between classical textual ideas about these topics and Buddhism as it is lived through ritual and community practice? How do both textual and ritual traditions maintain human life?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14213,2026,3306,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-169','<div class="desc"> <p>Imperial violence and capitalist economic restructuring historically drove Asians to migrate to the United States. Once here, people of Asian descent engaged in transformative political activism and constructed new cultural identities and alliances to meet the challenges of diasporic and immigrant life. This course will examine the cultural and political geographies of trans-Pacific migration and identities from the 19th century to the present. From Har Dayal, Sun Yatsen, and Qiu Jin in the early 20th century to the 1960s Third World Liberation Front, the I Wo Kuen Red Guards in San Francisco working with the Black Panthers, and beyond, political activists have been crisscrossing the Pacific, building and rebuilding networks of resistance to colonialism, marginalization, and exploitation. The course draws heavily on the rich history and cultural diversity of Los Angeles and Southern California, which has been a center of Asian and Asian American movements—migratory, political, and cultural—for over a century. Students will examine a variety of primary sources, including literature, political manifestos, and films, and engage deeply with the cultural and spatial geographies of these histories. Field trips to local religious sites and neighborhoods, paired with visits from local scholars, journalists, and filmmakers, will bring these histories to life and illustrate their legacies shaping the present. Along with regular writing assignments, students will collaborate on a final project mapping transpacific migration histories and social justice alliances in LA.</p> <p>This course is part of the Humanities for Just Communities Immersive semester.</p> </div>',NULL,'This course will be run alongside an FYS with the same title. ',NULL);
INSERT INTO course_descriptions VALUES(14214,2026,975,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-190','<div class="desc"> <p>From the 1st-6th centuries CE, early Christian communities throughout the Mediterranean had different ideas about who Jesus was, what kind of movement he inspired, and what it meant to be or to act like a Christian. In this course, students will investigate the variety of early Christian communities that structured their movements around the figure of Jesus by studying their primary sources: stories, letters, sermons, theological treatises, art, artifacts and architecture. Students will explore the practices and ethics that dictated the daily lives of early Christians, how they interacted with their Jewish and “pagan” neighbors, the theological issues debated among early Christian communities, including charges of "heresy" and the development of orthodoxy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14215,2026,743,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/100/rels-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14216,2026,3352,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/copy-of-rels-221','<div class="desc"> <p>Between the 1960s and the 1980s, as feminist theologians of Latin America actively confronted the Vatican’s and liberation theology’s insufficiencies in leading the marginalized out of cycles of socio-economic oppression, such theologians were commonly deemed “indecent.” In this course, we will examine how various Latin American women and social movements embraced and practiced indecent liberation, starting with the Mexican Revolutionary period and concluding with global understandings of indecent liberation in relation to religion and feminism. We will ask: How has “indecency” been constructed as a site of hegemonic power, particularly at the intersections of religion, race, gender, class, and/or able-bodiedness? In what ways is indecent liberation a form of empowerment and (how) does it relate to identity-formation? Is indecency merely a tool for liberation or a place of generative knowledge and ways of being? We will answer these questions through three main case studies, starting with “muscular” Christian women of the Mexican Revolution, continuing with indecent liberation theology during the mid- to late- twentieth century, and concluding with contemporary chicana epistemologies and ecofeminism. At the end of the class, students will apply course content to a case study of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14217,2026,3823,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/copy-of-rels-235','<div class="desc"> <p>This course centers gender as it examines the Jews of Southwest Asia and North Africa (SWANA)—a region typically defined as stretching from Morocco to Afghanistan. Our exploration will include delving into life prior to the 19th century in places like medieval Egypt and late 1700s Morocco before colonialisms supported by western imperialism narrowed expressions of Jewish identities and histories. With a focus on correcting the negative effects of eurocentrism and colonialism, the course will uncover the potential pasts possible in SWANA where gendered Jews have been integral. Sources and topics will include fictional accounts such as <em>Ninette of Sin Street</em> exploring Jews and gender in early 20th century North Africa; speeches from early women’s rights activists throughout Egypt and the Levant such as those from Esther Moyal; biographies and music from Jewish women of culture such as artists Layla Murad in Egypt and Salima Pasha in Iraq; autobiographical accounts; and films such as <em>Dimona Twist </em>which discusses SWANA Jewish women’s racist discrimination in Israel/Palestine. By the end of the course, students will feel empowered to make more speculative assertions as a challenge to imperialist violence and possess a more varied and dynamic picture of Jewish communities and Jewish people.</p> <p>This is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14218,2026,2497,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/copy-of-rels-257','<div class="desc"> Our course will examine the history of antisemitism from late antiquity to the present. We will investigate the historical differences and continuities between anti-Judaism and antisemitism, and problematize their ahistorical conflation with anti-Zionism. Leaning on this long history, we will examine the conditions under which various historical actors articulate, proclaim, and contest claims of antisemitism, rather than assuming its universal definition. We will also take an intersectional approach to understanding the ways in which antisemitism connects with racism and Islamophobia. By the end of the course, students will be able to open up conversations about antisemitism, understand it relationally with other forms of hatred, and identify how it might be instrumentalized in contemporary political discourses. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14219,2026,1036,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-200','<div class="desc"> <p>We are currently in the midst of a "psychedelic renaissance." Over the past two decades, university-backed research institutes, non-profit organizations, and capitalist entrepreneurs around the world have celebrated drugs like psilocybin and LSD as powerful therapeutic tools capable of helping people work through trauma and improve well-being. And according to some prominent researchers, the "mystical experience"--or a feeling of union with the divine--produced from these drugs is key to their therapeutic efficacy. But is this claim valid? And why would scientists make such a claim in the first place? In this course, we will answer these and related questions by exploring the global cultural history of psychedelics from the early twentieth century to the present. With special attention to the relationship between psychedelics and religion, we will examine everything from these substances'' ritual consumption in indigenous communities and in pre-modern Europe, to scholars'' and researchers'' use of religious texts to explain psychedelic experiences, to legal issues surrounding psychedelic use and religious freedom.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14220,2026,4369,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-203','<div class="desc"> <p>Food practices are fundamentally rooted in religious beliefs and systems of morality, whether through offerings to deities, dietary taboos, or food hospitality. Moreover, eating is an act that can define who belongs in a religious community, or also define the savage Other who eats the wrong thing the wrong way. In this class we will examine a central question: how have religious traditions used food and food symbolism to construct relationships between individuals, the community, and nonhuman beings (animals, deities, ancestors, etc.)? To answer this question, we will employ critical anthropological and historical methods to consider the influence of hunting and farming on religious practices beginning in ancient Mesopotamia, the role of dietary restrictions in the spread of major world religions during the classical age (including guidelines for kosher, halal or vegan consumption), and debates around ritual sacrifice and cannibalism that surfaced in Christian missions in a global early modern world. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14221,2026,3233,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-204','<div class="desc"> <p>The project of queer theory is invested in destabilizing essentialist identity constructions, especially the links between gender, sexuality, and desire. Religious discourses have historically been a powerful force in buttressing such essentialist constructions of identity and thus have, in many instances, undermined the project of queer theory. Yet, a number of scholars have found queer theory, queer experiences, and/or queer identity useful lenses through which to engage with religious texts, practices, and communities. With course materials including scholarly readings, as well as films, documentaries, music, podcasts, comedy and visual images, we will pay particular attention to the lived aspects of queer engagements with religion. For instance, we will cover topics such as Judeo-Christian reinterpretations of Genesis to make room for same-sex marriage; conceptions of transgenderism in the time of the Prophet Muhammad; gender fluidity in iconography of the Buddhist boddhisatva, Kuan-yin; gender role mixing in Tantric Hindu ritual; and, Native American postcolonial approaches to HIV within the “two-spirit” community. Through these and other case studies, we will analyze how the intersection of religion and sexuality is inevitably entwined with questions of race, class, embodiment, nation, and post/coloniality.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14222,2026,2564,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-205','<div class="desc"> <p>How do we relate to the nonhuman world, the "holy sh*t!", that makes up the world around us? What are our responsibilities to “stuff” when we consider objects to be more than objects, and explore cosmologies that acknowledge agency beyond the human, in material objects including places, plants, bodily adornments, texts, and physical representations of all of these? This course considers how human communities across time and space have created, lived with, and destroyed powerful belongings by thinking about these material belongings in and out of context. These contexts include traditional settings, as well as the role of colonialism, the marketplace, and museum in the remaking of relationships. By the end of the course, we will have a variety of lenses for understanding the power of materiality in our lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14223,2026,3320,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-207','<div class="desc"> <p>This course is an introduction to the major trends of Jewish mysticism from late antiquity to the present day. Major texts like the <em>Zohar</em> and the <em>Tanya,</em> and mystical movements like Rhineland pietism and Hasidism, will be explored chronologically to trace the development of these traditions and discern what is continuous and discontinuous within each one. Major themes such as mystical union, hermeneutics, asceticism and embodiment, esotericism, as well as meditative practices and paths will also be highlighted. What is it like to be a Jewish mystic? What is the texture of their mystical experiences and how are they woven into the mystic’s personal and communal life? Jewish mysticism will also be explored in relation to both exoteric expressions of Judaism as well as forms of mysticism found in other religions. We will conclude the course with an in-depth examination of Kabbalistic traditions still found and practiced today, from the secluded worlds of the ultra-orthodox to the universal formulations of the Kabbalah center.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14224,2026,3848,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-208','<div class="desc"> <p>In 1965, Rabbi Abraham Joshua Heschel marched with Reverend Martin Luther King Jr. and in 2014, Jews in Massachusetts protested police violence during Hanukkah under a banner that read “Jews Say #BlackLivesMatter,” two instances that illustrate the joint struggle for freedom shared by Jews and Black Americans. However, this relationship, like nearly all relationships, was not without its variances. For example, in the 1950s, civil rights activist Malcolm X criticized the Israeli occupation of Palestine and Black Americans and Palestinians found mutual recognition during the Ferguson-Gaza moment of 2014. In this course we will study multifaceted Black-Jewish partnerships, as well as Black-Jewish-Palestinian interactions. We will learn that the occupation of Palestine did not necessarily spell the breakdown of Black-Jewish interactions because these relationships have always been complex. Reading op-eds, academic articles, novels, memoirs, and films, we will explore a range of topics such as: anti-Black racism; antisemitism; Afro-Jews; mistreatment of Mizrahi (Middle Eastern Jews) at the hands of Ashkenazi (Jews of European origin); Palestinian activism and solidarity activism with Palestinians; Black Internationalism; intersectionality; and much more. By the end of the course, students will be able to identify and appreciate a much more sophisticated history of Black-Jewish-Palestinian solidarity, as well as understand both the erudition and emotional lives of committed liberation activists whether they be Ashkenazi Jews, Afro-Jews, Black folks, Palestinians, or Mizrahi Jews.</p> <p>This a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14225,2026,744,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-210','<div class="desc"> <p>Scholars and cultural critics often talk about the commodification, marketization, and commercialization of religion. What do these expressions mean, and what kinds of processes and transformations do they refer to? How do they help us problematize the role of religion in economic life, the relationship between the religious and the secular, and the demarcation of “religion” and “economy” into separate realms of the sacred and the profane? This course will equip students with historical knowledge and an interdisciplinary toolkit to understand the complex material, ideological, cultural, and ethical entanglements between religious and economic life. The course is divided into two parts. In Part 1, we will survey classic debates about whether capitalism forces a progressive decline in religion or whether capitalist modernity itself is a continuation of Christianity in a secularized form. We will also question Eurocentric assumptions about capitalism’s Christian origins that inform histories of capitalist expansion from the West to the global South. Moving from theory to practice, we will then examine religious and economic interactions in everyday life: including religiously-imbued practices of symbolic exchange, market transactions, money-making, gift-giving, indebtedness, and workplace discipline from the bazaar to Wall Street. Part 2 will leverage these concepts and apply them to concrete case studies. In particular, we will investigate the emergence of strategic alliances between conservative religious movements and global neoliberal capitalism, as witnessed through examples of Evangelical Christianity in the US, Hindutva in South Asia, and the rise of Islamic banking in the Middle East. Through these cases, we will discern how religion acts as a means of resistance against capitalist exploitation but also gets co-opted and assimilated into capitalist projects.</p> <p>This course is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14226,2026,3849,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-212','<div class="desc"> <p>“The Palestinian flag was fluttering…over the Dome of the Rock. Jerusalem had finally become Al-Quds again” (Emad El-Din Aysha, <em>Palestine+100</em>). As we will discuss in this class, the key to understanding such a passionately transformative statement is to recognize that Jerusalem is both historically renowned as a major sacred site of Judaism, Islam, and Christianity and futuristically imagined as a site of (shared) belonging. Inspired by speculative works such as <em>Palestine +100 </em>and <em>East Jerusalem Noir </em>as well as poetic claims from artists such as Naomi Shihab Nye, Mahmoud Darwish, and Mohammed el-Kurd this course will show how belonging to Jerusalem has been established for over three millennia from different standpoints. Our study of poetic, fictional and futuristic works, will be buttressed by historical, archeological, ritual, and autobiographical sources. By the end of the class, students will understand how Jerusalem has been sanctified as a holy city, the various idioms used to establish belonging to Jerusalem, as well as how and why peace is still aspired to within the presence of Israel’s occupation.</p> <p>This a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14227,2026,4370,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-214','<div class="desc"> <p>This course orients students to the fields of medicine, magic, and miracle in the ancient Mediterranean (5<sup>th</sup> century BCE- 5<sup>th</sup> century CE). We will start by studying the ways people experienced, understood, and responded to illness and suffering. Then we will explore the options available to them as they sought help in the “healthcare marketplace”: physicians, “midwives,” druggists, ritual experts (aka "magicians"), or religious healers. Consulting a range of sources—such as medical treatises, folk remedies, religious texts, “magical” recipes and spells, and archaeological evidence—we will seek to understand their distinctive views about the cause and treatments of illness, as well as the bitter competition between healers. We will see that ancient rhetorical strategies to malign competitors—strategies that mobilized already well-defined social differences along political, gendered, classed, religious, and ethnic lines—created impressions of and hierarchies between medicine, religion, and magic that persist still today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14228,2026,1191,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-215','<div class="desc"> <p>This course explores the dynamic religious and cultural landscape of East Asia, providing an overview of religion as it has been constructed in the states that are today known as China, Japan and Korea. In addition to learning about Confucianism, Daoism, Shintoism, and Buddhism, students will also learn about shamanistic and folk traditions, as well as practices that span across traditions, in order to provide students with tools to resist simplistic understandings of religious identity. Furthermore, taking both a chronological and comparative approach, the course leads students through the development of different traditions by situating them in their broader socio-political contexts. Finally, the course engages with multiple themes and perspectives, including the relationship between religion and the state, the development of institutions, literary and artistic expression, and gendered experiences of religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14229,2026,4371,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-222','<div class="desc"> <p>Islam and capitalism are often viewed as two systems belonging to separate spheres of religious and economic life, yet in this course we will explore their historical, conceptual, and material entanglements. We will examine how interactions between Islamic law and commerce shaped Muslim societies during watershed moments in the history of capitalism, including the rise of trade networks in the Mediterranean and Indian Ocean; the birth of the joint-stock company and the corporation; colonialism and industrialization; and most recently, the ascendancy of neoliberal financial capitalism. In addition to developing a broad understanding of the economic history of Muslim societies from West Africa to Southeast Asia, students will ask analytical questions like: Are religion and economics mutually exclusive or overlapping domains of life? In what ways is a commitment to capitalism and a faith in free markets akin to religious beliefs? Has religion contributed to the great economic divergence between Euro-American and Muslim societies? Can modern Islamic experiments in global finance inspire efforts to combat racial capitalism and climate change?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14230,2026,1351,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-228','<div class="desc"> <p>Latino/a religious social movements around the world have pursued liberation from oppressive forces and sought to move toward just and equitable futures. In this course, we will examine the ways various Latin American social movements from the late nineteenth century to the present day have defined and practiced liberation, paying special attention to the distinctive role of religion in these movements. We will ask: How can religion provide a foundation for liberation? More specifically, how can religion foster visions of life honoring justice and prosperity? In what ways have religious communities lead organized resistances? And even when mobilizing for liberation, to what extent can religion continue to solidify forms of oppression? We will seek to answer these questions through a series of case studies including: 1) a unique form of “muscular” evangelical Christianity across Latin America after the Spanish-American War (1898) that sought to combat the oppressive powers that limited their sovereignty; 2) liberation theology and spiritual praxis within the Mexican American Civil Rights Movement of the 1960s; and 3) Latino/a global missionary efforts through various evangelical organizations. At the end of the class, students will have the opportunity to apply what they have learned to a Latin American social movement of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14231,2026,1087,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-232','<div class="desc"> <p>A study of the development of the religion of ancient Israel and its expression in the Hebrew Bible. Special emphasis will be placed on the emergence of the central ideas of Biblical religion which formed the foundation for early Judaism and in time of Christianity and Islam. In addition to close reading of selected Biblical texts in translation attention will be paid to the historical context in which ancient Israel lived and to the findings of modern critical scholarship and archeology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14232,2026,746,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-242','<div class="desc"> <p>An exploration of the relationship between religion and environmental ethics. How do various world religions view the natural world and what role do they propose for human beings in nature? What is the history of environmental ethics and how does religion figure in that history? How are religious traditions such as Buddhism Christianity Hinduism Islam Judaism Native American Spirituality and Taoism rethinking their environmental views especially in light of ecofeminism perspectives?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14233,2026,4372,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-246','<div class="desc"> <p>This course explores modern Muslim engagements with, and resistance to, the violence of Islamophobia, colonial racial capitalism, and the carceral state. Our examination will unfold through a series of historical case studies from the Muslim abolitionist movement against the Transatlantic slave trade in colonial West Africa to the Nation of Islam’s Civil Rights Era struggle against policing and incarceration and, more recently, the astonishing rise of a capitalist-friendly American Muslim neo-conservatism that promotes a color-blind allegiance to the carceral state. Throughout the course, students will learn about different strategies of power used to discipline and regulate populations—from biopolitical and carceral technologies to new forms of surveillance capitalism—and Muslim responses to their proliferation—from strategic accommodation to decolonial critique and social justice activism. Students will be able to observe and compare Muslim approaches to prison reform and abolition through the work of organizations such as the Tayba Foundation, the Council for American Islamic Relations (CAIR), and Believers Bail Out. Finally, in addition to familiarizing students with Euro-American scholarship on race and power, the course will also introduce them to indigenous Muslim theorizations of black suffering, liberation theology, and social justice in the field of critical Muslim studies.</p> <p>This is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14234,2026,4373,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-248','<div class="desc"> <p>This course will introduce students to the diverse religious history of the Los Angeles Basin, with special attention to the themes of borderlands and <em>mestizaje</em>. By studying primary source documents, visiting museums, and conducting ethnographic research, students will learn about the variety of religious traditions and religious communities that have flourished in the region—ranging from indigenous religions, to colonial Catholicism, to immigrant religions like Taiwanese Buddhism and Christianity—and we will learn about how these religious communities reflect Los Angeles’s place on the horizons of the Atlantic and Pacific Worlds. After an introductory section of the course that provides historical context for the colonial past that shaped the city’s cultural geography, we will turn to a focus on lived religion in contemporary Los Angeles. We will study distinct religious traditions, as well as practices that cut across religions and thus complicate the border between religion and culture. Finally, with an eye toward religious contact, conflict, and exchange, we will ask how religion in Los Angeles both reflects and challenges narratives of American religion more broadly.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14235,2026,976,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-250','<div class="desc"> <p>What is Religious Studies? Students in this course will answer this question first by tracing the historical formation of the academic study of religion (from monasteries to the university), and across various disciplines (sociology, psychology, anthropology, history, economics, etc.). We will then engage more deeply with the various theoretical and methodological tools available to scholars of religion by reading a range of scholarly works that illustrate these approaches and by giving students the opportunity to practice some of these approaches. In the end, students will become familiar with the landscape of the academic study of religion, will be able to assess the value and limitations of different scholarly approaches to the study of religion, and will have cultivated skills necessary to participate in conversations in the field. Required for Religious Studies majors and minors, recommended in the Sophomore or Junior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14236,2026,3824,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-255','<div class="desc"> <p>Discussions of the SharÄ«âa (Islamic law) in American public discourse conjure images of veiled women, girls barred from attending school, and public spectacles of flogging and stoning to death. Such a caricature of the SharÄ«âa as a medieval and draconian penal code elicits public fear and state suspicion. In the West, this caricature induces legislative measures to curb the SharÄ«âaâs perceived threat to security, democracy, and human rights. On the other hand, Islamists seek to harness the SharÄ«âa as an instrument of political legitimacy and authoritarian rule, using it to curb individual freedoms and stamp down on womenâs rights. Both uses of the SharÄ«âa reify it in ways that erode its rich history, cosmopolitan diversity, interpretive complexity, and lived realities across the Muslim world. This course offers an in-depth introduction to the SharÄ«âa, examining its sources, people, institutions, and their historical evolution from 7th century Arabia to the present. Students will gain a holistic understanding of the SharÄ«âaâs major doctrines and practices, ranging from laws of worship and ritual purity to institutions of marriage, slavery, war, and economic welfare. We will examine the pre-modern historical and societal contexts in which Islamic legal schools evolved, as well as challenges to their orthodoxy and patriarchal structures by Muslim modernists and feminists. Students will also study the significance of colonial modernity in transforming the SharÄ«âa from a socially embedded and pluralistic legal tradition into a codified and bureaucratic legal system. Finally, we will examine the SharÄ«âaâs vexed relationship with liberal democracy in Muslim-majority countries and its vilification in Euro-American contexts in the form of anti-Muslim racism, surveillance, and Islamophobia.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14237,2026,2604,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-256','<div class="desc"> <p>Tibetan Buddhism is a globally recognized religion, with the Dalai Lama, red-robed monks, prayer flags, and prayer beads occupying a unique position in the popular imagination. These images, though, flatten the diversity and historical complexities both of the Buddhist traditions of Tibet and the spread of these traditions into surrounding regions of the Himalayas. This course will provide an overview of these traditions, exploring their trajectories of development and interactions with diverse communities, while also considering local differences and agency.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14238,2026,4374,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-258','<div class="desc"> <p>This course explores the role of religion in contemporary Chinese society and culture. The last century has seen extraordinary changes in China, with the fall of the imperial system in 1911 and the beginning of a series of experiments with modernity that included the rise of the Communist Party, the turmoil of the Cultural Revolution, and the liberalization and openness of the Reform Period which has led China to become one of the most economically and politically powerful nations on earth. This course will provide students with the opportunity to think about a myriad of questions related to the relationship between religion, modernity, and secularism, as well as the functions of religion in one of the world’s largest, most diverse, and misunderstood nations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14239,2026,2699,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-259','<div class="desc"> <p>Stories of child sacrifice. Rumors of necromancy. Images of “voodoo dolls.” In this class, students will survey a variety of magical practices throughout the Americas to ask: what is magic, and what makes it “black?” Using a series of case studies set throughout the Americas, we’ll trace the shifting boundaries between magic, religion, and reason from the colonial period to today. Students will engage sources like inquisition records, legal statutes, newspaper records, and films and fiction, to see how depictions of witchcraft and sorcery have been used to stigmatize certain traditions and people, ranging from Catholics in the United States to practitioners of African-inspired religions in Cuba and Brazil. And in doing so, we’ll learn how magic has been a key site for negotiating questions of race, progress, and citizenship in modernity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14240,2026,1626,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-261','<div class="desc"> <p>Buddhism is found worldwide today and is cited as an influence in a wide variety of settings, including psychology, self-motivation movements, education, statecraft, art, music, and science. However, its historical beginnings as a religious movement 2,500 years ago in India are often left out of these discussions. Buddhism is instead commonly presented as it has been reimagined by different agents as “more of a philosophy than a religion” and compatible with Western Enlightenment ideals, such as rationalism, empiricism and science. This course will provide a critical perspective on the process through which Buddhism has been constructed by various intellectual and political agents as it has developed in the modern era. Rather than attributing these characteristics of the tradition to inherent elements in some timeless ahistorical Buddhism, the course will instead encourage critical reflection on the broader cultural, political and economic processes that have influenced the development of modern Buddhism, including global networks of trade and technological exchange, colonialism (and anti-colonialism), cosmopolitanism, nationalism, the rise of secularism, and globalization between India, China, Japan, Sri Lanka, Tibet, Britain and America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14241,2026,2357,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-266','<div class="desc"> This course examines selected topics related to gender and sexuality as they have been negotiated in different global manifestations of the Buddhist tradition. Spanning over 2,500 years and multiple civilizations, Buddhism as a philosophy and Buddhist communities have constructed concepts of gender, sexuality, and the body in multiple, often conflicting, ways. Seen as androcentric and misogynist by some and liberating and non-judgmental by others, Buddhism and Buddhist institutional attitudes related to these key themes have been constructed through complex interactions between ancient traditions and the different societies in which Buddhism has developed. The course will be anchored in theoretical considerations of sexuality and gender, which we will explore through different case studies from India, China, Tibet, Thailand, Japan, and Korea. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14242,2026,1674,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-276','<div class="desc"> Mainstream historical accounts of empire tend to focus on political and economic reasons for state expansion, leaving students with little insight into the experience of colonialism and imperialism "on the ground" for both the colonizers and the colonized. This course will offer methodological tools that encourage an understanding of everyday, non-elite voices into the study of empire in Asia and the Pacific by focusing on religious experience. Studying religion -- which was used as both a tool for colonial domination, as well as for resistance -- complicates ideas of empire as straightforward and as a mono-directional process. Case studies in this course will explore the interaction between empire and religion across a range of regions and historical moments. Students will then embark on their own research project related to a place and theme of their choice. In the end, the course will give students an insight into how Asian and Pacific societies variously responded to imperialism while also influencing the societies of the colonizer. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14243,2026,2358,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-277','<div class="desc"> <p>This course will survey ancient Mediterranean views about the catastrophic end of the world. We will study how ancient folks--Greeks, Romans, Jews, and Christians--interpreted disease, natural disasters (fires, floods, food shortage), political upheavals, and social unrest as signs of the end of the world. We will study how they altered their behaviors to anticipate the near end. And we will study their visions and fantasies of the utopian societies they hoped would emerge after the devastation. At the end of the course, students will conduct a staged research project on a topic of their choice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14244,2026,1192,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-281','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14245,2026,4375,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14246,2026,4376,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/rels-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14247,2026,361,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/200/resl-245','<div class="desc"> <p>A study of the religious traditions of the African diaspora in North America. We shall investigate the role of religion in Black culture and chart the development of the mainline Black Church. Islam religious traditions from the Caribbean Islands and new religions among African Americans will also be studied.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14248,2026,2815,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/300/rels-302','<div class="desc"> <p>This course asks: what is the ghost, and when does it take hold of the world? Through a series of case studies focusing especially on Latin America and North America—ranging from classical scholarship on Haitian vodou and Brazilian Candomblé to contemporary work on alien abductions and Cuban Santería—this course examines the category of spirit possession. In it we will take a look at the ways in which spirits are understood to possess people, haunt places, and inhabit objects. We will consider different scholarly interpretations of spirit’s saturation of matter, asking how these phenomena relate to the historical traumas inflicted by chattel slavery, colonialism, and economic inequality. Finally, we will interrogate the category of “spirit possession” itself, asking how the category might relate to regimes of property ownership and serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14249,2026,4377,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/300/rels-335','<div class="desc"> <p>This course will use advanced methodological techniques to orient students to the relationship between media and religion in Asia. Historically, many Asian religions developed in close concert with forms of mediated and textual culture, from palm leaf manuscripts to enormous stone carvings of deities. Students will be introduced to pre-1800 manuscripts, statues, songs, paintings and other objects before they consider contemporary manifestations of these media. This course will consider how these historical media have developed into a considerable variation in the contemporary forms of media used to represent, promulgate, and critique religious traditions in Asia, as well as how the circulation of this media continues to create both community and division. Case studies will include Bollywood films from India that feature deities as lead characters, television shows that promote Confucian values from China, and online networks that promote connections between global Muslim communities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14250,2026,1090,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/300/rels-351','<div class="desc"> <p>Folks in the ancient Mediterranean world were deeply invested in forms of sexuality that served the interests of Empire, of elite households, and of men. In the first unit of the course, we will investigate how these specific forms of sexuality were prioritized, incentivized, and regulated in society--namely, how art, medicine, law, and religion worked together to make them appear natural and normal. But when Christians came on the scene, they advocated a significant deviation from the dominant sexual ethics of the time. In the second unit of the course, we will study early Christians'' novel ascetic movement that understood sexless (even genderless) people to embody the ideal spiritual state, positioned at the pinnacle of humanity. In these next unit, students will be given the freedom to set the direction of the course. They will conduct a research project on a topic of ancient sexuality of their choice, presenting their findings to classmates. In the final unit, we will consider how sexual ethics of antiquity are still exerting influence on us, shaping contemporary sexual taboos, values, and regulative mechanisms. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14251,2026,3972,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/300/rels-393','<div class="desc"> <p>Research in an area that contributes new knowledge to the field of Religious Studies. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14252,2026,365,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/300/rels-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14253,2026,750,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/300/rels-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14254,2026,366,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/400/rels-490','<div class="desc"> <p>This seminar is offered in conjunction with Religious Studies majors'' ongoing research for the senior comprehensive project. Seminar meetings will be devoted to instruction on research and writing in the discipline of Religious Studies as well as discussion and critique of individual students'' work in progress. Open only to senior Religious Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14255,2026,4378,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/400/rels-493','<div class="desc"> <p>Research in an area that contributes new knowledge to the field of Religious Studies at an advanced level. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14256,2026,4379,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/400/rels-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14257,2026,751,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rels-religious-studies/400/rels-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14258,2026,368,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/100/rusn-101','<div class="desc"> <p>Introduction to the structure of the Russian language with an emphasis on reading and verbal communication. Films and laboratory assignments complement in-class work. May not be taken for credit by those with more than one year of high school study (grades 10 11 12) or one semester of college study of Russian.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14259,2026,752,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/100/rusn-102','<div class="desc"> <p>Continuation of RUSN 101; emphasis on reading and conversation.</p> </div>','RUSN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14260,2026,4380,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/100/rusn-197','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14261,2026,369,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-201','<div class="desc"> <p>Development of reading skills through the use of original texts by Bulgakov Chekhov Pushkin and others; improvement of conversation skills accompanied by a review and expansion of grammar. Films and laboratory assignments complement in-class work.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14262,2026,753,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-202','<div class="desc"> <p>Continuation of RUSN 201 with emphasis on reading skills; readings by Gogol Chukovsky Shukshin and others.</p> </div>','RUSN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14263,2026,4000,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-203','<div class="desc"> <p>This course builds reading knowledge of literary Russian. The prerequisite is RUSN 102. This course complements and can be taken before or after the traditional RUSN 201 and 202 sequence. The specific objective of this course is reading and translating sophisticated literary and philosophical texts in Russian.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14264,2026,4381,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-234','<div class="desc"> <p>Between 1800 and 1900 Russia went from a society without any real literature theater or art to a world leader in all three areas. This course follows the rapid evolution of Russian artistic output by examing the poetry of Pushkin the short stories of Gogol the novels of Dostoevsky and Tolstoy and the great plays of Chekhov. Russia''s evolution in visual art will also be examined through the masterpieces of Repin and others. Course taught in English; no knowledge of Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14265,2026,2752,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers:Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ).</p> <p>This course meets twice a week with CSLC 236, and for one additional 85 minute session per week, to develop Russian students'' intermediate language skills, specifically by reading and discussing works under consideration in the course taught in translation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14266,2026,4382,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14267,2026,4383,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/200/rusn-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14268,2026,3326,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-330','<div class="desc"> <p>Do we live in the era of post-truth? Is everything just another piece of propaganda? Whom do we trust and why? </p> <p>Postmodern theory offers us powerful resources to criticize and take down the houses of totalizing ideologies, but many of its most important conceptual tools have been co-opted and are now used to oppress. Postmodern propaganda corrodes the relationships of trust that connect us, and makes us feel isolated and powerless. It taps into our fears and phobias to destroy not only the reality around us, but also our humanity. The organized lies of the 21st century aim to confuse and disorient, but also (and this is where the greatest danger lies) make us cynical. Several philosophers and writers from Eastern and Central Europe, who had first-hand experience of Western European “demi-Orientalism,” Russia’s imperialism, and Soviet totalitarianism, offer an antidote to this postmodern condition. </p> <p>In this course we will read French theorists, such as Deleuze and Derrida, and their counterparts from Eastern and Central Europe: Havel, MiÅosz, Mamardashvili, Venclova, and others. Several other philosophers and writers—such as Plato, Arendt, Kundera, Orwell, Klemperer, and Platonov—will help us think about truth, trust, and propaganda.</p> <p>This course will meet twice a week with CSLC 130, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from texts in the original Russian, such as Mamardashvili’s essays and Platonov’s stories.</p> <p>Students in this course are required to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second Stage writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14269,2026,1677,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-331','<div class="desc"> The worldview and beliefs of the early Slavs particularly the Eastern Slavs were a complex synthesis of influences: Indo-European mythology Central Asian shamanism Scythian animal worship and ultimately a paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600 in order to understand how these people viewed the world and how this affected their lives and the development of Slavic culture. Communal village life legends folk genres and mythology their sources and their legacies are examined. There is a close study of the phenomenon of the vampire following its evolution from the Iron Age into eighteenth century Serbia as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined as well. In addition to analytical and historical texts readings include tales of supernatural beings and phenomena as well as testimony concerning encounters with the supernatural." This section will deal with both texts in English and with texts in the original Russian. Texts include the "Tale of Warlord Dracula," "Olga''s Revenge on the Drevlians" and other early Russian stories. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14270,2026,1561,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-332','<div class="desc"> Many of Russia''s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements while at the same time creating some of the most memorable texts of the twentieth century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin, using original Russian texts to examine the use of language in the creation of science fiction and fantasy texts. Additionally, film adaptations will be shown, including the avant garde film Aelita the Queen of Mars and Andrei Tarkovsky''s masterpiece, Stalker. The course only introduce students to modern Russian literature while at the same time examine how Russian writers used science fiction to criticize society and government. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14271,2026,1627,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-333','<div class="desc"> <p>There are two fundamental philosophical positions that try to describe our relation to others. The one posits that I am different from you. The other assumes the fundamental unity of human and other beings. Both of these positions lead to serious difficulties. If I am fundamentally different from you, I run the risk of alienation, and confront the impossibility of knowledge. If I begin with the assumption of oneness, I encounter the difficulty of distinguishing myself from you, and the impossibility of agency.</p> <p>Is there a third way that avoids both of these extremes? Could we re-imagine relationships between humans and nature in a way that preserves a sense of selfhood within a community of other beings? Eastern European folklore and mythology might help us in this task.</p> <p>In the course of the semester we will focus on the myths and folk tales from Eastern Europe. We will ground our discussion in the historical context of Scythian female warrior culture and some pre-Indo-European beliefs and practices. These cultural phenomena survive in the myths and epics of the Slavs. We will analyze representations and adaptations of these myths and practices in contemporary literature, film, and art from former Yugoslavia, Romania, Ukraine, and other Eastern European countries.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> <p>This course meets the Core Program Pre-1800s Requirement.</p> <p>Second-stage writing requirement: Students may satisfy the Second-Stage Writing Requirement by submitting a substantial (12-15 page) writing assignment that addresses a subset of the primary texts studied in this course. Students satisfy the Second Stage Writing Requirement by obtaining a grade of "C" or higher on this paper.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14272,2026,1740,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-334','<div class="desc"> How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist a century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun" and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency known otherwise as the Russian Avant-garde. Topics include poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14273,2026,3751,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-335','<div class="desc"> <p>Plato thought that all we need is a philosopher-king. What if he was only partially right, and what we actually need is a philosopher-buffoon? Jokes aside, what if critical thinking needs to be accompanied by laughter? And not just any laughter, but the kind that, following Mikhail Bakhtin, one would call carnivalesque.</p> <p>Carnival laughter exposes the grotesque aspect of human bodiesâeverything that is âugly, monstrous, hideous from the point of view of âclassicâ aestheticsâ of the ready-made and the completed. It liberates an individual body by revealing the ways it is open to the world around itâby emphasizing a bodyâs orifices and protruding parts. This laughter also revives and refreshes thinking by ridiculingâwithout destroyingâthe strict laws of rationality. Carnivalesque laughter is irreverent; it crosses the lines of what is socially, politically, and morally acceptable, and in so doing reveals the connections between myself and other beings.</p> <p>Bakhtin will provide the main theoretical framework for the course that will bring together literature and philosophy of Eastern Europeâthe works of Gogol, Zizek, Andrukhovych, and othersâto explore (and pervert?) the claims made above.</p> <p>This course will meet twice a week with CSLC 235, and for one additional 85 minute session per week to develop Russian studentsâ language skills. Students will have an opportunity to translate and discuss selections from texts in the original Russian, such as Bakhtinâs essays and Gogolâs stories.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14274,2026,2854,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-336','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. This course can be repeated for credit when taken as different topics.</p> <p><strong>Idiots, Atheists, and Nihilists</strong></p> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. In this five unit version of CSLC 136, we will be reading excerpts in the original language from Goncharov’s Oblomov, Turgenev’s Fathers and Sons, Dostoevsky’s Idiot. Students in this course will be asked to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14275,2026,2946,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-338','<div class="desc"> <p>Should you abandon yourself to the sensual beauty of the world? Or should you embrace a life of asceticism and simplicity? Is there an even more attractive path in between? Is it also a more difficult one? Major works by Russian writers—including Pushkin, Tolstoy, and Chekhov—will guide our discussions of these questions. This course will meet twice a week with CSLC 138, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from texts by Russian writers, especially Pushkin, Tolstoy, and Chekhov. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement. </p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14276,2026,3217,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-339','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>This class will meet simultaneously with CSLC 139 twice a week, and then meet for an additional 90 minute session to read selections of the above works in the original. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14277,2026,1490,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-340','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">The course will critically examine philosophical ideas about humans, animals, and machines. We will think about the current stage of technological developmentâthe ways in which contemporary technologies both expand and interrupt what it means to be human. We will focus on several key concepts of Gilles Deleuze and FÃ©lix Guattari (including becoming-animal, lines of flight, and reterritorialization). Our discussions will situate these concepts in the context of past and ongoing posthumanist debates, placing them alongside the contributions of contemporary philosophers, such as Bernard Stiegler and Catherine Malabou. The plays and short stories of Anton Chekhov will help chart outânot so much the lines of flight, as footpaths for slower becomings and futures. </span></p><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course will meet twice a week with CSLC 230, and for one additional 85 minute session per week to develop Russian studentsâ language skills. Students will have an opportunity to translate and discuss selections from Anton Chekhovâs stories and plays in the original Russian. </span>Students who complete the final paper for this course, with a grade of C or higher, can use this work to satisfy the second-stage writing requirement.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14278,2026,4384,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-375','<div class="desc"> <p>Two intimately related schools of literary analysis from the early 20th Century Russian Formalism and Prague Structuralism staked out fundamentally new theoretical terrain by isolating the functional elements of verbal artistry as discrete objects of rigorous inquiry. Their works merit close inspection as representative of a big bang in theory and cultures of binary encoding that continues to expand and proliferate to thisday subsuming the visual arts music cinema broadcast media digital computation the cognitive sciences and espionage. This course traces lines and shifts in the intellectual history of this brief moment through close reading of selected works and situates theory in the biographies and broader social cultural and political contexts of its key figures.Course taught in English; no knowledge of Russian required.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14279,2026,3179,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>To be: Ukranian</strong></p> <p>Ukraine’s rich poetic and revolutionary culture helps one trace routes of escape from oppressive imperial structures. Philosophical and literary texts written by and about Ukrainians will allow us to gain an understanding of this culture, and the works by contemporary historians will help us develop an understanding of Ukraine’s tumultuous history. Philosophers, writers, and historians could include Svetlana Alexievich, Anne Appelbaum, Ivan Kotlyarevsky, Alexander Potebnja, Mykola Riabchuk, Timothy Snyder, Lesia Ukrainka, Oksana Zabuzhko, Serhiy Zhadan, and others. No previous knowledge of the Ukrainian language or literature is required. Russian 330 will meet twice a week with CSLC 130, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from literary and philosophical texts in the original Russian. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement. Core Requirement Met: Regional Focus.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14280,2026,754,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/300/rusn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14281,2026,4385,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/rusn-russian/400/rusn-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14282,2026,371,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/100/soc-101','<div class="desc"> <p>This course introduces students to the sociological imaginationâa way of understanding events, relationships, and social phenomena that shape our lives and history. Through a critical evaluation of the theoretical propositions of thinkers in the field, we will explore how people are shaped by society and, in turn, shape it. Students will write papers that articulate an original thesis with supporting evidence, deepening their grasp of how sociology helps us interpret the dynamics of social order and disorder. <em>Open only to frosh and sophomores, or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14283,2026,2700,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/100/soc-102','<div class="desc"> <p>This course adopts a global perspective to introduce students to sociology, the scientific study of societies. It will examine the self, socialization, social ties, social interaction, social institutions, and social change, considering both conformity and deviance. Students will leave with a "sociological imagination," the ability to see their own lives and the lives of others in the context of their wider societies and an increasingly interconnected world. Through a critical evaluation of the theoretical propositions of thinkers in the field, we will explore how people are shaped by society and, in turn, shape it. Students will write papers that articulate an original thesis with supporting evidence, deepening their grasp of how sociology helps us interpret the dynamics of social order and disorder. <em>Open only to frosh and sophomores, or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14284,2026,879,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/100/soc-105','<div class="desc"> Through a critical evaluation of the theoretical propositions of thinkers in the field, we examine the role of youth cultures in the identity formation of immigrant adolescent youth residing in the Southwest region of the United States. Particular attention is paid to: (1) theories of acculturation and assimilation used to analyze the experiences of immigrant youth; (2) the impact of geographical location, social class, gender, race, sexuality, popular culture, mass media, and technology; and (3) the intersection of youth cultures, home cultures, and mainstream society. Students will write papers that articulate an original thesis with supporting evidence. This course is part of the California Immigration Semester, and enrollment is open only to first-year students. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14285,2026,755,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/100/soc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14286,2026,3234,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/copy-of-soc-211','<div class="desc"> <p>Cultural production is central to the struggle for human rights. As cultural artifacts both conceptualize and memorialize social-political trauma, our class will take a close look at the way that Mexican film, literature and music represents both criminal and state violence. For comparative purposes, we will also look at some documentaries or film about the current violent situation in Central America. As this is a 4-unit course, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course. </p> <p><strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico (as well as Central America) through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14287,2026,1491,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-200','<div class="desc"> <p>The course is on sociologyâs formative schools of thought. Karl Marx, Max Weber and Emile Durkheim not only founded the field of Sociology in the 19th century, their theories continue to influence contemporary thought about social relations. Through lecture and discussion we examine their general theories before we critically evaluate their concrete claims about capitalist development or âmodernization,â the state, social science and social change. Learning Outcomes: Students will learn to critically evaluate the theoretical propositions of thinkers in the field. They will also write papers that articulate an original thesis with supporting evidence.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14288,2026,372,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-205','<div class="desc"> <p>This course introduces the most influential sociological paradigms of the 20<sup>th</sup> and 21<sup>st</sup> century. These include the structural-functionalist paradigm, rational choice theory, various neo-Marxist theories (for example âworld systems,â âglobalizationâ or the âFrankfurt schoolâs critical theoryâ), as well as the symbolic interactionist paradigm. I will introduce postmodernist theory, as well as works from Giorgio Agamben and Achille Mbemebe. <strong><em>Learning Outcomes:</em></strong> Students will learn to critically evaluate the theoretical propositions of thinkers in the field. They will also write papers that articulate an original thesis with supporting evidence.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14289,2026,3872,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-207','<div class="desc"> <p>This course will examine contemporary economic, political and social conditions of women workers across the Americas. We will analyze the ways in which US-Latina and Latin American women navigate and resist hierarchical power relations in the globalized labor market. How processes of globalization, transnationalism, work, and family shape womenâs lives are integral to this course. This course will expand the field of labor inquiry to include both productive and reproductive labors. This includes the unpaid âcaringâ work of childcare, housekeeping, and the maintenance of critical community networks. We will consider both the consequences of the sexual division of labor between those considered women and those classified as men but also focus on race, class, sexuality, nationality/citizenship, and other markers of differences. In these contexts, we will explore issues such as development, im/migration and construction of the woman worker to illuminate the gender of political economy and the political economy of gender. Finally, we will analyze struggles for <em>pan con dignidad </em>(dignity and daily bread), the place of affect in organizing, and the prospects for social justice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14290,2026,1492,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) Presidents either failed to act in accordance with the transitional justice movements sweeping Latin America, or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased rather than decreased since its transition to democracy. This class will document why this is the case as well as look into the various movements that have mobilized since the 1970s to the present to demand human rights in Mexico. This class will also look at the violence committed by transnational criminal organizations as well as how ordinary people attempt to create security for their communities.</p> </div>','DWA 101 , LLAS 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14291,2026,1562,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-215','<div class="desc"> <p>Who are you? Why are you? How do you know? Surely you have heard the phrase "nature vs. nurture." It is about the ongoing quest to figure out how much of a human is genetic, biological, and chromosomal (nature), and how much is a product of socialization (nurture). To what extent are you your society? To even consider that question, we must examine the society itself, the individuals that produce it, and how the two are connected. The society and selves we will be examining are our own -- in particular, the society and selves of young Americans. How does the world you''re facing today make you who you are? How do the technology and media through which you learn about your world permeate, shape, and structure your everyday experience of self and society? Who do you want to be, who will you end up being, and what kind of world will you create?</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14292,2026,3307,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-218','<div class="desc"> <p>Over fifty years ago, the first person in the U.S. hired to coordinate a Black Studies program, Nathan Hare (1970), published an essay titled, ‘‘Black Ecology,’’ in which he argued that it was imperative that we come to ‘‘understand how both the physical and social environments of blacks and whites have increasingly evolved as contrast.’’ Since then, many scholars from across the social sciences and humanities have contributed to this endeavor. This emergent field of Black ecological thought is important because it provides insight about race and the environment from the perspective of Black study. In this survey course, we will study a range of black ecological thinkers and the concepts that they offer for understanding contemporary environmental issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14293,2026,4044,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-220','<div class="desc"> <p>This course examines the social, economic, and political factors that contribute to unequal health outcomes across different populations. Through a sociological lens, students will explore how race, class, gender, geography, and other social determinants shape access to healthcare, health behaviors, and overall well-being. The course will analyze structural inequalities, such as systemic racism and economic inequality, as well as policies and practices that perpetuate health disparities. Case studies and contemporary examples, including the COVID-19 pandemic, will be used to understand how power and privilege influence health outcomes globally and locally. Students will engage in critical discussions on potential solutions, emphasizing equity-focused interventions and public health strategies. By the end of the course, students will be equipped to analyze health disparities and advocate for more just and inclusive health systems.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14294,2026,4386,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-221','<div class="desc"> <p>This 2-unit course focuses on how emigration/migration from Mexico and Central America is represented in film. Before each in-class film showing, students will have read sociological analyses on the socio-economic and political conditions leading to emigration, or to the urgent exodus, from these countries beginning in the 1980s. We will also study film and sociological readings on the reception of Mexicans and Central Americans in the United States. For comparative purposes, we will examine some works on the U.S. reception of immigrants from Latin America, including Spanish-speaking caribeÃ±os. The value of learning about the socio-economic and political processes involved in the mass displacement of people through film is that students will learn about such human experiences and their contexts (that is, multiple interacting variables through time and space) in three-dimensional ways. As this is a 2-unit course, students should expect to invest at least six hours a week (including in-class time). <strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico and Central America through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14295,2026,1628,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-225','<div class="desc"> <p>This course examines the construction and reproduction of masculinities primarily in the United States. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14296,2026,4387,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-226','<div class="desc"> <div><div><p>This course examines the construction and reproduction of masculinities primarily in Latina/o and Latin American communities. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p></div></div> </div>','SOC 101 or SOC 102 or SOC 105 or LLAS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14297,2026,1316,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-230','<div class="desc"> <p>This course examines the family as a social institution in the United States. The course emphasizes sociological and demographic perspectives on the family family change historically and contemporarily and the intersection of the family with social categories such as race and ethnicity sexual orientation gender and class. The course will highlight contemporary changes in marriage divorce and non-marital cohabitation in the United States but will also expose students to sociological thinking about family systems around the world.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14298,2026,756,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-240','<div class="desc"> <p>This course examines the social relations surrounding the production distribution preparation and consumption of food. In doing so we will try to understand how the issues and problems of daily life reflect larger social forces and how our understanding and actions shape the social world. This means that we will treat several major questions facing sociology today including inequalities and identities based on national racial/ethnic class and gender positions; work and family; the environment; globalization; and cultural change. By the end of the course you will be able to critically examine and evaluate the connections between food culture and society.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14299,2026,373,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-245','<div class="desc"> <p>This course examines the individual cultural and structural explanations for the presence and persistence of income and wealth inequality in the U.S. The impact of inequality on social groups and the social policies developed to curtail poverty are also considered.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14300,2026,979,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-250','<div class="desc"> <p>This course provides a basic sociological understanding of relations among racial and ethnic groups in the United States. A sociological approach includes considering race and ethnicity as social constructs that permeate all social life are entrenched in social structures and institutions and shift and mutate over time and place. Such a perspective suggests that (1) race and racism are not merely the ''problems'' of/for subordinate racial and ethnic groups but are reflective of society-wide power relationships that deeply affect all of us on a daily basis (2) that racial and ethnic categories - including ''white'' - can be viewed usefully as the result of historical struggles over economic resources political access and cultural identity rather than as objective measures of biological difference and (3) the institutional forms of racism indelibly etched into this nation''s past did not end with civil rights legislation of the 1960s but continue to shape social institutions today.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14301,2026,4388,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-257','<div class="desc"> <div><div><p>This course uses a sociological perspective to examine how youth in societies throughout the world draw on their social contexts and local resources to make globalized youth cultures their own. Among the local youth cultures studied are street skateboarding, hip hop, and punk.</p></div></div> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14302,2026,1092,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-260','<div class="desc"> <p>In this course we will focus on sociological theories of deviance with an emphasis on how behaviors and identities are socially constructed as deviant (both today and historically). We will then turn our attention to major forms of deviance as typically defined in Western societies: criminal deviance "victimless crimes" and individuals with stigmatized identities. Throughout the course we will work to understand the complex relationship between social actors and audiences in defining deviance; the nature of social control in responding to deviance; and the experiences of "deviant" individuals.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14303,2026,3344,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-263','<div class="desc"> <p>W.E.B. (William Edward Burghardt) Du Bois, was a prolific scholar, writer, and social/political analyst and organizer. Over the course of his lifetime, Du Bois wrote over 2000 bibliographical entries, across a range of genres, including: research monographs, plays, pamphlets, autobiography and biography, history, novels, poems, and popular press articles. At the same time, Du Bois utilized multiple methods, forms of data and evidence, and literary styles within and across texts. Nevertheless, in the domain of social science, and sociology more specifically, his work was intentionally marginalized. Yet while Du Bois was made a minor figure in American social science, he was a primary progenitor of the transdisciplinary field of Black, African American, or Africana studies and thus played a foundational role in circumventing the racial-colonial order of knowledge by attending to Black life and sociality. In this course, we will study the social theory of Du Bois by reading texts from across his vast corpus—from his more formally social scientific writing and data visualizations to his creative projects like poetry and short stories. For the final project of the course, students will deploy a Du Boisian approach to social theory and analysis using more expressive forms (such as illustration, painting, film and video, poetry, music, photography, data visualization, short stories, or lyrical essays).</p> <p>*This course cannot substitute for the theory requirement (SOC 200 or SOC 205) for Sociology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14304,2026,374,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-265','<div class="desc"> <p>In this course we will critically examine the ways gender informs the social world in which we live. Our goals for this course will be 1) to reveal the "common-sense" world of gender around you; 2) to consider how we learn to "do" gender; 3) to expose the workings of the institutions that shape our gendered lives; and 4) to come to an understanding of the relationship between gender and the social structure.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14305,2026,2360,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-270','<div class="desc"> <p>What are the effects of urbanism on human psychology and civic life? How does urbanization structure social and economic relations as well as signifying identities and cultural meanings? Is there a common "human ecology" of cities in "natural areas" such as the CBD skid row the "Tenderloin" or the "zone-in-transition"? We examine the urban underclass through case studies of the African American ghetto and Spanish Harlem with attention to public policy perspectives on urban poverty. Urban futures are considered through gentrification growth machine boosterism (sports and convention centers) and urban theme parking.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14306,2026,3259,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-275','<div class="desc"> <p>People in the U.S. struggle every day to get the care they need. Why, in such a wealthy country, do so many go without healthcare, eldercare, childcare, food, housing, and more? This course surveys, from a comparative-historical perspective, social welfare provision in the United States. We dissect debates about the value of welfare and explore the implications of various arrangements between civil society, the market, and the state. In so doing, we consider critical race, Marxist, and feminist theories of social welfare as a tool of racial, economic, and gender power. Students use theoretical lenses developed in class to assess contemporary welfare policy interventions.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14307,2026,3235,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-281','<div class="desc"> <p>This course introduces the field of criminology. The course is designed to provide a broad understanding of the etiology of crime (i.e. what causes crime?) the measurement of crime and theories of criminal punishment. We will also discuss a wide range of criminal behaviors with a focus on violent crime and property crime (e.g. homicide sexual assault shoplifting white collar crime etc.). The final component of the course focuses on the American criminal justice system. This course emphasizes a sociological approach to understanding crime criminal behavior and criminal justice.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14308,2026,1093,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-285','<div class="desc"> <p>The relationship between humans and the non-human environment is complex and problematic. We are part of and dependent upon the natural environment even while altering that environment for our own needs and purposes. As a way of broadly thinking about these interactions we will address the social causes consequences and responses to environmental disruption. By the end of the course you will be more adept at understanding how societal characteristics -- including cultures traditions beliefs values institutions and the like -- combine with environmental conditions to shape the impact that people have on their environments.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14309,2026,1741,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-290','<div class="desc"> <p>This course is an introduction to sociological analyses of the economy, economic processes, and economic institutions. The central focus is to understand how beliefs, norms, cultures, social relations, and institutions shape our economic lives. We will also explore how the theoretical and methodological approaches of sociology differ from those orienting the discipline of economics, as well as what is at stake in these differences. By the end of the course, you will be familiar with the key approaches in economic sociology, and will be able to use a sociological lens to examine the economy.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14310,2026,1194,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Poverty and Inequality in America</strong><br/> <br/> This course will examine why the U.S. has more poverty and more inequality than any other wealthy nation -- and what we can do about it. The course will include class discussion, readings, and films. Among the topics we''ll discuss are: Who benefits and who suffers from America''s high of poverty and inequality? Should our society try to significantly reduce poverty and inequality? If so, what can we do? Who is poor in America? Who is super-wealthy? Who is middle class? What are the major stereotypes about the lives of the poor and the super-wealthy? How have issues of race, gender, and immigration influenced the level of poverty? Why are poor, middle class, and wealthy people in America concentrated in certain locations - more so than in other wealthy societies? Has government policy made poverty and inequality better or worse? What political movements and policy reforms have made a difference in improving the lives, and reducing the number, of America''s poor? How can poor Americans and their allies influence politics and policy?<br/> <br/> Students who want to get a head start on the readings should read Barbara Ehrenreich''s book, "Nickel and Dimed: On (Not) Getting By in America."<br/> <br/> This topic is cross listed with UEP 295.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14311,2026,4389,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/200/soc-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14312,2026,375,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-304','<div class="desc"> <p>This course looks at the ways sociologists collect information about social phenomena with a special emphasis on what can be done to yield information that is trustworthy and useful for our theoretical understanding of social life. It assumes no background in research methods or statistics. We will talk about the scientific method the complexities of applying methods to social research ethics and bias and research design. You will be given an overview of major "quantitative" and "qualitative" methodologies including surveys interviews ethnography experiments participant observation or content analysis.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14313,2026,757,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-305','<div class="desc"> <p>This course introduces quantitative research methods and statistical analysis from a social science perspective. We will address the major components of the research process and will stress the importance of critical thinking in all matters numerical. We will cover measures of central tendency the normal curve probability frequency distributions correlation and regression. We will also talk about statistics and statistical reasoning in the media. By the end of the course you will have mastered basic statistical concepts and techniques and will be able to critically examine and evaluate the (mis)use of these concepts.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14314,2026,1563,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-306','<div class="desc"> <p>This course introduces qualitative research methods from a social science perspective. We will cover systematic qualitative research design, data collection and analysis. Techniques will include interviewing, focus groups, ethnography, and/or qualitative content analysis. By the end of the course you will have mastered basic concepts and techniques and be able to carry out basic qualitative research, resulting in a paper that uses your data as evidence to support and articulate an original thesis.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14315,2026,1493,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-310','<div class="desc"> <p>On the surface, music can appear to be a non-consequential element of life and/or an individualized phenomenon. In fact, the production and consumption of music is a social process and thus plays an imperative role in the social world. Music shapes and structures how we interact as groups and individuals, who we are intimately connected to, and reflects and reinforces many of our core social institutionsâlike religion and politicsâas well as meaningful social distinctions â like race, class, and gender.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14316,2026,1094,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-315','<div class="desc"> <p>This course uses different sociological perspectives to examine social aspects of schooling and educational institutions in the U.S. Specifically the course focuses on factors that may impede and/or facilitate learning such as social class gender race and ethnicity teacher and parental expectations and peers. Additionally the role of education in the acculturation and assimilation process is considered as are the ways in which schools ameliorate and/or replicate social inequalities.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14317,2026,1353,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-320','<div class="desc"> <p>This course surveys sociological theories of health illness and medicine. Rather than focusing on the individual body as the site of disease the course examines the role of social context in shaping health and access to the healthcare system across population groups. The course focuses especially on medical intervention and the medicalization of disease social disparities in health and contemporary healthcare changes and challenges in the United States.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14318,2026,2605,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. We will also examine Central American immigration from an international relations perspective.</p> </div>','SOC 101 , SOC 102 , SOC 105 , LLAS 101 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14319,2026,3873,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-322','<div class="desc"> <p>Central American feminisms have been an integral dimension to struggles against imperialism, dictatorship, and globalization across the Isthmus. This course will examine the development of Central American feminisms beginning with the revolutionary period of the 1970s and 80s up to the present. We will explore feminist epistemologies and cultures of resistance, looking at how feminists make interventions through artistic practices. We will examine the transnational dimension of feminist organizing in the region, looking at how shared histories and dialogues shape how Central American women theorize about feminism through their lived experiences. To do so, we will study critical texts written by feminist writers and collectives, historical testimonios as well as feminist cultural productions such as music and art. We will also explore how global discourses touch down and shape Central American womenâs political claims as well as how Central American feminists influence international organizations and global conceptions of human rights. Topics we will explore include contemporary regional histories and womenâs roles in social change, gendered violence and femicide, reproductive rights, memory and artivism, and motherhood as a political identity.</p> </div>','LLAS 101 or SOC 101 or HIST 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14320,2026,2361,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-323','<div class="desc"> <p>This course explores the sociological analysis of law, focused on the legal construction of social "groups," the moral regulation of social action, and the formal legitimization of state practices. The course is divided into two sections. The first half of the course examines theoretical approaches to the sociology of law drawing on the works of Max Weber, Niklas Luhmann, Jürgen Habermas, and Pierre Bourdieu, as well as perspectives rooted in Marxism, feminism, and critical race theory. The second half of the course focuses on contemporary legal controversies in the United States, including racial disparities in criminal justice, undocumented immigration, the regulation of sexuality, and the criminalization of political dissent and protest.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14321,2026,3260,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-326','<div class="desc"> <p>Why does the United States incarcerate more of its population than any other nation in the world? Why does death by injection seem kinder and gentler-and thus more acceptable-than public hangings of the past? What are the consequences for justice and democracy in an era of unprecedented confinement and correctional supervision? Using various historical, legal, and sociological perspectives we will focus on questions such as these with an emphasis on: the cultural life of punishment and crime control as a political issue, the racial and class dynamics of punishment, and inequality and contemporary issues surrounding modern penal sanctioning (e.g. mass incarceration) and its consequences. </p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14322,2026,377,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-330','<div class="desc"> <p>This course will focus on classical and contemporary theories of power and authority; theories of the state and various forms of state power the state and government the nature of democracy and political elites in modern society (especially the United States) as well as the social bases of political parties and voting behavior.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14323,2026,4390,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-334','<div class="desc"> <p>This course critically examines technology as a social phenomenon rather than a neutral tool. We will approach technology through three guiding questions: 1) What counts as technology, and what forms of agency do technologies have (or lack)?; 2) How does technology reflect and shape identity, social interaction, social structures, and systems of inequality?; And 3) What role does technology play in sustaining or transforming institutions and social change? Drawing on sociological theories of technology, inequality, and culture, we will analyze how technologies are designed, adopted, and contested across different contexts. By the end of the course, you will be equipped to interrogate the sociologically complex and multifaceted relationship between humans and technology.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14324,2026,1564,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-340','<div class="desc"> <p>China''s Environmental Challenges: A Sociological Perspective This course examines China’s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China’s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. Cross-listed with East Asian Studies and Urban and Environmental Policy.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14325,2026,4391,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-345','<div class="desc"> <p>This course examines reproduction as a social process that is not only tied to biology, but also to the value placed on different bodies in society. It introduces students to empirical research and theory on a range of reproductive experiences, elucidating the social forces that fundamentally shape understandings and outcomes in each domain.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14326,2026,758,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-350','<div class="desc"> <p>This course examines why people protest for social change. We will examine the theoretical debates about the determinants of insurgency by focusing on the following models: the collective behavior the resource mobilization the political process as well as the cultural approach. We will also examine the theoretical debates on the extent to which social movements can be credited with political change. Your study of these theories will expose you to several case studies of real social movements in the United States Europe and Latin America. This is however a theory (not a history) course.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14327,2026,759,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-355','<div class="desc"> <p>This course will consider the role that sexuality plays in the American imagination especially the way that sexuality is constructed and serves as a mechanism of social control. In doing so special attention will be paid to the ways in which human sexuality intertwines with axes of power in contemporary America such as race ethnicity gender class and sexual orientation.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14328,2026,2890,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-361','<div class="desc"> <p>This class examines racism in the U.S. and globally through the lens of power. We will explore how whiteness shapes institutions, politics, pop culture, social media, technology, and identity as well as how it intersects with other systems like gender, class, and citizenship. We will also consider what it looks like to dismantle these systems for a more just and equitable society.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14329,2026,761,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-365','<div class="desc"> <p>The course will examine how mass communication systems such as radio television cinema and the Internet are produced and what they signify and represent of the social world and public life. We consider the relationship of the mass media to big business and the structure of capitalism. The ideological influences of the mass media are interrogated through concepts such as "mass culture" and "subculture". We examine how contemporary culture and everyday life are increasingly commodified through the systems and spectacles of consumption capitalism. How has globalization affected consumerism and the social construction of the contemporary self?</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14330,2026,1354,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-370','<div class="desc"> <p>This course examines the social phenomenon of human violence. We first consider classical and contemporary sociological theories on violence and violent conflicts and the main sociological definitions of violence used over the last century. We then turn to empirical studies that explore the social processes and societal structures that give rise to the various forms of violence-intrapersonal interpersonal familial collective and political-and nonviolent movements presently observed throughout the world.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14331,2026,762,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-375','<div class="desc"> <p>This course examines the political economic and cultural changes that occur as societies shift from the traditional to the modern. Why are some nations mired in debt and dependency while others have become successful "newly-industrializing countries?" We consider leading intergovernmental organizations of the global economy such as the IMF World Bank and WTO. We investigate scenarios in cultural globalization including Americanization hybridization and fundamentalism. We consider intersectional social dynamics that disenfranchise the most powerless including women children indigenous and stateless peoples.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14332,2026,1426,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-380','<div class="desc"> <p>This course examines disaster as a social phenomenon and broader trends in managing calculating and responding to a variety of threats and catastrophes. We will focus on the history of disaster response and policy in the U.S. theories of reflexive modernity risk and trauma and cultural responses to calamity in California and in the U.S.more broadly. Case studies include Hurricane Katrina the BP Deepwater Horizon oil spill Fukushima and outbreaks of whooping cough and Ebola.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14333,2026,1631,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-390','<div class="desc"> <p>This course offers a survey of sociological approaches to the study of religious beliefs practices and organizations in the United States in public and private life. Exceptionally devout among developed nations the U.S. is a nation of remarkable religious diversity. We will examine the relationship between religion politics and civic life; recent trends in American religion (the "new atheism" problems of pluralism secularization and declines in religious participation the rise of evangelicalism and fundamentalisms religious conflicts); as well as theoretical arguments both classical and contemporary about the role of religion in scientifically advanced modern societies. Whereas much public debate frames religion as either a unambiguously beneficial public good or else as a font of irrationality and sectarian division we will move beyond this dichotomy toward a more empirically informed consideration of just what religion is and does in the contemporary United States.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14334,2026,1040,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-395','<div class="desc"> <p>This course will function as an advanced seminar focusing on the research interests of the Sociology Department''s faculty. Topics vary.</p> <p><strong>Science, Technology, &amp; Justice: The Making of “Modern” Families</strong></p> <p>Does reproductive justice include a right to bear children using technological means? What about using 3<sup>rd</sup> parties like egg and sperm donors? Are reproductive technologies expanding definitions of family or reinforcing race, class, and gender inequalities? This upper-division seminar will examine reproduction from a social justice perspective, with particular attention to how the politics of reproduction are shaped by the intersecting inequalities of gender, race, class, dis/ability, and sexuality. Reproduction is not only a biological process; it is a battleground of social and political struggle. The course will familiarize students with foundational academic and activist approaches to reproduction. Students will learn about the history of and differences between reproductive rights and reproductive justice movements. We will then look at the new questions and challenges reproductive technologies raise for social justice. Cross Listed as UEP 395.</p> <p><strong>Policing, Power, and Violence</strong></p> <p>In this course, we will examine policing in the United States from the repression of Indigenous and enslaved peoples in the 18th century to the militarization of policing on the streets and the U.S.-Mexico border today. Using sociological understandings of power, we will analyze the judicial and extrajudicial violence that law enforcement agents engage in and how such violence serves to maintain the unjust and unequal social order. The course will close with us considering arguments for and against the abolition of police forces and prisons.</p> <p><strong>Sociology of the Southern U.S.</strong></p> <p>What, and where, is the South? Who is a southerner? What do they do down there, and why do they do what they do? Are the South and southerners still distinctive? By looking at all aspects of Southern life this course will unravel the enigma of the region while pondering a more inclusive and nuanced appreciation of "many Souths" and "southern cultures" including senses of regional identity and allegiance, and in representations of, and cultural stereotypes from and about, the South. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> <p><strong>Visualizing Gentrification: Bridging Land Use Data and Ethnography</strong></p> <p>Students are challenged with the myths and realities of gentrification in an immersive discussion. The proposed course weaves urban planning, mapping and data research with qualitative analysis to recognize gentrification drivers, examine the pending experiential trauma of displacement and the community''s aspirations and resistance. The course examines the communities of Northeast Los Angeles as they face three colossal planning projects that utilize gentrification as a catalyst and justification for their development.</p> <p>In a holistic examination of the landscape, course participants will embed with community and other partners to explore the social networks and their relationship to research data. Course discussions will include developing metrics from an activist and documentary perspective to establish the observable community. Students will operate in small teams in developing data and fostering outcomes that reveal the human narrative. They can be visual in nature from ethnographic studies to data visualization, but also critical analysis and policy recommendations of the conditions on the ground. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14335,2026,763,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/300/soc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14336,2026,378,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/400/soc-490','<div class="desc"> <p>Seminar is offered in conjunction with sociology majors'' ongoing library research for the senior thesis. Seminar meetings will be devoted to discussion and critique of work in progress. We strongly encourage students to have taken Classic or Contemporary Theory Sociological Inquiry and Qualitative Quantitative or Field Methods before taking the senior seminar (always taught in the Fall). <em>Open only to senior Sociology majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14337,2026,4392,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/400/soc-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14338,2026,764,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/soc-sociology/400/soc-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14339,2026,4393,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/copy-of-span-193','<div class="desc"> <div><p>Intensive study in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14340,2026,380,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/span-101','<div class="desc"> <p>A communicative approach to the Spanish language. Emphasis is placed on the four skills of speaking, listening, reading, and writing, as well as grammar, with a particular focus on the cultures of the Spanish-speaking world. <em>Students who have had more than one year of Spanish in high school or more than one quarter in college may not take this course for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14341,2026,381,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/span-102','<div class="desc"> <p>This course is a continuation of SPAN 101, a communicative approach to the Spanish language, and expands on the four skills of speaking, listening, reading, and writing, as well as grammar, with a particular focus on the cultures of the Spanish-speaking world.</p> </div>','SPAN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14342,2026,880,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/span-105','<div class="desc"> <p>This course offers students the opportunity to analyze narrative stories films and other cultural artifacts that document a history of immigration and migration to Los Angeles from Mexico and Central America during the twentieth and twenty-first centuries.Many of the narratives films and other cultural works studied treat significant contemporary issues (e.g. the representation of history questions of identity and alterity questions of race and ethnicity globalization authority the construction of class and gender in society) that Los Angeles faces as an emblematic socio-cultural space that continuously shifts as consequence of new arrivals to the city. Emphasis will be placed on studying narratives and films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically this course presents a critical view of the representation of migrations to Los Angeles in order to understand how these migration stories function as a socio-cultural medium that document and occupy many geographical spaces that establish Los Angeles as a heterogeneous cultural place and space.</p> </div>',NULL,'CTSJ 105 , FYS 1 , SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(14343,2026,382,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/span-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only. </em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14344,2026,765,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/span-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit.<em> Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14345,2026,766,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/100/span-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14346,2026,386,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/copy-of-span-251','<div class="desc"> <div><p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. <em>Graded on Credit/No Credit basis only.</em></p></div> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14347,2026,767,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/copy-of-span-252','<div class="desc"> <div><p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. <em>Graded on Credit/No Credit basis only.</em></p></div> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14348,2026,4394,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/copy-of-span-293','<div class="desc"> <div><p>Intensive study in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14349,2026,383,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/span-201','<div class="desc"> <p>This course focuses on the development of speaking and writing skills. Students read and discuss cultural and literary texts from a variety of Spanish-speaking countries. The fundamentals of Spanish grammar are reviewed. Students are strongly encouraged also to enroll in SPAN 151 / SPAN 152 Intermediate Conversation.</p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14350,2026,384,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/span-202','<div class="desc"> <p>This course is intended to further develop language skills while introducing students to the fundamentals of literary and cultural analysis through the study of Latin American and Spanish texts. Particular emphasis is placed on oral communication and writing. Students are strongly encouraged also to enroll in SPAN 251 / SPAN 252 Advanced Conversation. <em>This course parallels SPAN 211 and is designed for non-native speakers of Spanish. Students may not take both SPAN 202 and SPAN 211 for credit.</em></p> </div>','SPAN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14351,2026,385,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/span-211','<div class="desc"> <p>This course is designed for students who have spoken some Spanish in the home and are able to understand spoken Spanish well. It aims to develop and improve students'' conceptual understanding of the grammatical structures of the Spanish language. Coursework emphasizes the practice of formal written and oral Spanish as well as the improvement of vocabulary with the goal of strengthening studentsâ fluency in academic and professional contexts. Principal readings consist of literary texts (e.g. short stories, literary essays, and drama) in order to prepare students for reading and writing in upper-level Spanish courses.</p> </div>','SPAN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14352,2026,4395,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/span-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14353,2026,4396,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/200/span-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14354,2026,1134,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/copy-of-span-342','<div class="desc"> <div> <p>This course consists of an introduction to the Spanish language and Spanish-speaking communities in the United States, home to the second-largest Spanish-speaking population in the world. We will focus on questions like: who are the principal groups of Spanish speakers in the U.S.? What are the principal linguistic features of their Spanish? In the U.S., who uses Spanish, and in what contexts, and for what purposes? What is the role of Spanish in public services, the media, and schools? In this course, we will also confront social issues such as language attitudes, bilingualism, and the interaction between language and identity. The course will include guest speakers and require field trips and potentially other engagements outside of regular class times. This course will be conducted in Spanish.</p> </div> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14355,2026,3769,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/copy-of-span-393','<div class="desc"> <div><p>Intensive study in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14356,2026,1095,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-301','<div class="desc"> <p>General survey of Pre-Columbian civilizations and literature of Meso and South America the impact of the Discovery the Conquest the Colonial Period and the processes leading to the Independence and the formation of the new Republics. Literary and historical readings compositions and short essays and presentations will be used to continue developing language skills.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14357,2026,984,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-302','<div class="desc"> <p>An introduction to Spanish Peninsular literature and culture from the Middle Ages to the 18<sup>th</sup> century. This course examines the cross-cultural elements (Arab, Jewish, French, Italian, Trans-Atlantic and others) that have influence Spanish literature across the centuries. Readings include Mozarabic poetry, the <em>Cantar de Mio Cid</em>, Medieval narratives, <em>La Celestina</em>, Renaissance poetry, selections of <em>Don Quijote</em>, and Golden Age dramas. The class also incorporates representative examples of art and films.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14358,2026,387,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-303','<div class="desc"> <p>An introduction to major twentieth-century works of literary fiction and cinema in Latin America, with attention to the interplay of fiction and history, read in the original Spanish: Gabriel García Márquez''s <em>One Hundred Years of Solitude</em>, Isabel Allende''s <em>The House of the Spirits</em>, and stories by Jorge Luis Borges, Julio Cortázar and Roberto Bolaño. Film screenings include Cuban director Tomás Gutiérrez Alea''s <em>Memories of Underdevelopment,</em> Chilean director Patricio Guzmán''s <em>Salvador Allende</em>, and Argentine director Lucrecia Martel''s <em>La ciénaga</em>.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14359,2026,768,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-304','<div class="desc"> <p>This course surveys Spanish Peninsular literature and culture from the late 18<sup>th</sup>-century through the early 21<sup>st</sup>-century. Students engage with various intellectual and literary movements, including Neoclassicism, Romanticism, Naturalism, Surrealism, and Postmodernism. Special attention is given to the development of democratic traditions in Spain, the clash of political ideologies during the Second Spanish Republic and the Spanish Civil War, the trauma and legacy of dictatorship, and the changes in Spanish society resulting from the assertion of the distinct languages and cultures of the Iberian Peninsula and from globalization and immigration. Authors read include Leandro Fernández de Moratín, Ángel de Saavedra, Emilia Pardo Bazán, Jacinto Benavente, Ramón Sender, Antonio Buero Vallejo, and Juan José Millás. Significant examples of modern Spanish art, architecture, and music are also studied.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14360,2026,1494,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-309','<div class="desc"> <p>Many Latin American writers have chosen to live in Spain during the twentieth century. This course introduces students to the Latin American tradition of the writer acting as public intellectual or diplomat as well as to instances of the Latin American writer in political exile. Poets Pablo Neruda and CÃ©sar Vallejo chose to live in or near Madrid during the period of the Spanish Civil War whereas a later generation of fiction writers (Gabriel Garcia Marquez Cristina Peri Rossi and Roberto BolaÃ±o) lived in Barcelona after the 1970''s. The fiction writers include their own vision of Catalan nationalism and Catalan national identity in various short stories. The course concludes with a three-week stay in Spain that will provide a deeper understanding of the Latin American writers'' representation of the coutry. On-site lectures by historians and art-historians will enhance the student''s understanding of GarcÃ­a MÃ¡rquez''s Peri Rossi''s and BolaÃ±o''s incorporation of Catalan politics landscapes and cityscapes in their fiction.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14361,2026,1096,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-312','<div class="desc"> <p>This course surveys the history of Spanish film from its inception to the present. The course introduces students to basic concepts of film studies including cinematography mise-en-scÃ¨ne sound narrative and style but emphasizes representation and in particular depictions of gender sexuality and national identity in the context of dictatorship and democracy. The course further introduces students to the auteurist tradition in Spanish cinema. The films studied vary from year to year but the course typically highlights the cinematic production of Luis BuÃ±uel Carlos Saura and Pedro AlmodÃ³var.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14362,2026,1196,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-313','<div class="desc"> <p>This course offers students the opportunity to analyze films that have emerged in Latin America (e.g. Argentina, Brazil, Colombia, Cuba, Mexico, and Peru) as well as in the United States in the 20th and 21st Centuries. Many of the visual works studied treat significant contemporary issues in Latin America, such as the representation of history, questions of identity and alterity, questions of race and ethnicity, globalization, authority, the construction of class and gender in society. Emphasis will be placed on studying films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically, this course is a critical survey of the representation of Latin America with representative examples from different historical periods (beginning with the pre-Columbian and Colonial periods followed by the 19th and 20th Centuries). The goals of the course are to understand how film as a medium has functioned historically and aesthetically in its representations of different sectors of society.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14363,2026,881,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-314','<div class="desc"> <p>How do Latin American women writers and film-makers use language and sound? This course analyzes questions of social critique and the use of language in the short stories of Uruguayan writer Cristina Peri Rossi PuertoRican writer Rosario FerrÃ© and Brazilian writer Clarice Lispector as well as the use of voice music and mise-en-scÃ©ne in films by Latin American directors Gabriela David Maria Luisa Bemberg and Susana Amaral.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14364,2026,4397,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-316','<div class="desc"> <p>Violence is a tragic reality in Latin America and film-makers and novelists from Latin America include representations of violence in novels films and short-stories that also depict the history of Marxist insurgency groups right-wing dictatorships paramilitary activity ongoing rural and urban poverty and the vicissitudes of the drug-trade. Key spaces and moments in Latin America''s recent histories of violence include Peru''s Shining Path guerrilla movement Chile''s jails under Pinochet the rise of the Colombian drug cartels the mammoth Brazilian favelas (slums) and the bloodshed of the wars in Central America. Through a study of Nobel-Prize winning author Mario Vargas Llosa popular novelist Isabel Allende critically acclaimed Brazilian cinema novo Colombian novelist Fernando Vallejo and cinematic adaptations of his work and selected passages from The Autobiography of Rigoberta Menchu this course will examine questions regarding the ethical strategic and po! litical uses of violence in literature and film.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14365,2026,388,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-320','<div class="desc"> <p>An analysis of the relationship between literature and film, focusing on texts from the Spanish Golden Age and their film adaptations. Issues to be discussed include film adaptation as a cultural construct; narrative voice in literature and film; the transformation of the written word to the visual image; and the relationship between politics, literature, and film. This course includes a digital liberal arts laboratory in which students engage digitized and physical materials and develop necessary skills and critical frameworks for audiovisual and web-based course projects.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14366,2026,3240,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-321','<div class="desc"> <p>This course will examine culture and society in Spain under the dictatorship of Francisco Franco (1939-1975) and the effects of Francoism that continue to pervade present day Spanish society. We will focus on cultural productions (literature, film, television, propaganda posters, etc.) that illustrate socio-historical, political, and economic experiences during the most important chapter of 20<sup>th</sup> century Spain. In addition, we will examine cultural products created in the 20<sup>th</sup>and 21st centuries that represent the Francoist dictatorship to enable us to analyze the legacy of the historical trauma of Francoism in present day Spain. Topics to be discussed will include: ideological struggles, censorship, the oppression of women and other minority groups, the experience of exile, and the controversial process of historical/collective memory in contemporary Spain. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14367,2026,2606,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-325','<div class="desc"> <p>In this interdisciplinary course we will examine representative works of art and literature that are centered on the city of Madrid as a cultural, social, historical and intellectual space. We will discuss artistic and philosophical issues including, among others, the conception of space revolution in Diego Velázquez, the tensions of Enlightenment and Romanticism in Francisco de Goya, and the existential representation of life after the Spanish Civil War in Camilo José Cela. We will explore the interconnection of selected artistic and literary works with the purpose of approaching an understanding of the multilayered and fluid creation of the city’s identity.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14368,2026,769,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-340','<div class="desc"> <p>This course serves as a general introduction to the study of the Spanish sound system. The objectives of this course include strengthening students'' Spanish pronunciation in the direction of a more native-like normative pronunciation and introducing them to phonetics and phonology. Students will be introduced to theoretical means of analyzing the sound system of a language. They will also examine contrasts between American English and Spanish and apply these concepts in exercises of both written transcription and oral production as well as with a linguistic analysis of spoken Spanish. Finally students will also be acquainted with phonological differences among the dialects of the Spanish language.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14369,2026,1097,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-341','<div class="desc"> <p>This course consists of an introduction to historical Hispanic linguistics. Students learn about the major phonological morphosyntactic and lexical changes that have occurred in the language from the time of the arrival of the Roman armies into the Iberian Peninsula until the present. Foreign influences on the evolution of the Spanish language are discussed briefly. The primary focus of this course is the internal history of the language from Vulgar Latin to Modern Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14370,2026,1427,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-343','<div class="desc"> <p>Language use symbolically represents fundamental dimensions of human behavior and social interaction. For instance, what can you immediately infer about a Spanish speaker who uses the word “zumo” to describe the orange beverage commonly drunk at breakfast? Most likely, they are from Spain, otherwise they might describe this beverage as "jugo."</p> <p>This course introduces the basic concepts of sociolinguistics, using Spanish as our tool of exploration and description. Sociolinguistics focuses on the symbolic value of language as an expression of group identity based on region, gender, ethnicity, socioeconomic class, age, or other ways of defining group affiliation. In this course, we describe key notions of sociolinguistics such as the speech community, the sociolinguistic variable, and field methods. The core goal of the course is to identify phonological and morphosyntactic variation throughout Spain, Latin America, and the US, and identify what this variation tells us about language change and development as well as about the social characteristics and identities of the speakers themselves. The course also surveys other related topics such as language contact, bilingualism, Spanish as a heritage language, language attitudes and language identity in the U.S. and elsewhere, language and law, language and age, and language and gender. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14371,2026,1355,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-351','<div class="desc"> <p>A study of Cervantes'' narrative and drama in the context of certain literary trends of the European Renaissance. The course will focus on the Novelas Ejemplares selected parts of Don Quijote and Entremeses and it will explore Cervantes'' treatment of the genres and currents which influenced his art.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14372,2026,986,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-362','<div class="desc"> <p>This course will focus on the theater of Federico García Lorca and the cinema of Luis Buñuel and Pedro Almodóvar. Students will engage in an in-depth study of García Lorca''s plays examining his theatrical representation of surrealism, gender, and sexuality in conjunction with key films of Buñuel and Almodóvar.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14373,2026,1098,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-363','<div class="desc"> <p>This course will apply current theories of autobiographical discourse to Spanish Latin American and U.S. Latino life-writing. Students will examine the relation of personal identity to dominant ideologies of gender race class and politics and will explore the role of memory and fantasy in literary self-expression. Authors studied will vary from year to year but will typically include Gloria AnzaldÃºa Reinaldo Arenas Juan Francisco Manzno Carmen MartÃ­n Gaite Rigoberta Menchu Constancia de la Mora and Mario Vargas Llosa. Students will have the opportunity to write their own autobiographies.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14374,2026,3261,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-365','<div class="desc"> <p>This course examines discourses of gender and sexuality and their intersections with race, politics, religion, and national identity in Spain from Francoism to the present. By reading a selection of literary works and watching representative films and TV shows through a feminist lens, we will explore cultural artefacts that subvert, perpetuate, and construct notions of gender and sexuality in 20<sup>th</sup> and 21st century Spanish society. Some of the topics to be discussed are: Women’s oppression and resistance during the Francoist dictatorship, the (de)construction of the Spanish <em>macho</em>, the post-Francoist experiences of LGBTQ+-identifying lives, gender violence, processes of exoticization and marginalization, and queer and feminist re-writing of Spanish history in the 21<sup>st</sup> century. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14375,2026,1632,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-370','<div class="desc"> <p>In this course we will look at the jungle as a space where western civilizations desires and fears come into tension with the imagined "other" so that sometimes the jungle can be beautiful and desirable like the Garden of Eden and other times savage and dark like hell. Readings will include Latin American works of fiction (by Jose Eustasio Rivera Romulo Gallegos Horacio Quiroga and William Ospina) excerpts from the anthropological discourse of Wade Davis narcotraffic narratives testimonial literature (by Ingrid Betancourt and Clara Rojas) as well as environmental discourse and film in order to analyze the particular forces of history that intersect in each narrative. Topics to be discussed will include: exploitation and subjugation vs. autonomy and self determination; the search for ethnobotanical knowledge and the hallucinogenic journey; the playground and hidden operational spaces of drug traffickers; the imprisonment of the kidnapped victims from the guerrilla war against the state and paramilitary forces; the environmental movement and the concept of ecotourism. We will frame our analysis in contemporary critical theories relevant to the topics being discussed. Upon completion of this course students will be able to critically understand the value and complexity of the jungle in the geography and imagination of the Latin-American modern landscape and identity.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14376,2026,3345,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-372','<div class="desc"> <p>This course includes the study of Latin American fiction dealing with representations of port cities (Callao, Valparaíso, Guayaquil, Buenaventura, etc.) and topics that range from labor movements, migration and economic struggles, gender, and ethnic tensions from the twentieth century. The narratives reflect the forces at play resulting in human exploitation, ecological devastation, and social stagnation present since the republican era. The course will explore modes of illustrating resistance, survival, and adaptation.</p> </div>','Span 202 or 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14377,2026,3926,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-373','<div class="desc"> <div> <p>This course traces the evolution of poetry in the Spanish-speaking world and includes the study of representative works of poetry produced in Spain and the Americas from the Middle Ages to the twenty-first century. The works reflect the major movements and artistic trends that characterize the context of their production, and they illustrate the richness and diversity of the Spanish-speaking world.</p> <p>This is a 4-unit course. It is expected that students in this class devote on average at least twelve (12) hours a week (including in-class time) to the course.</p> </div> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14378,2026,4007,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-374','<div class="desc"> <p>How do people from a country come to see each other as co-nationals, that is, as part of the same nation? What is the role of imagination in the formation of a national identity? And, what happens when national imagination fails to account for the variety of experiences in a country? In this course we will explore these questions by engaging with literature and film from Argentina such as short stories by Jorge Luis Borges and Mariana Enriquez, poems, films like Santiago Mitre''s <em>Argentina</em>, <em>1985</em>, graphic novels, and short novels. Through themes such as labyrinths, infinite libraries, metafiction, and philosophical paradoxes, students will engage in critical analysis, creative responses, and multimedia storytelling.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14379,2026,4045,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-375','<div class="desc"> <p><span style="font-size: 12pt">This course investigates how Latin American literature represents imprisonment, political repression, and strategies of resistance with an emphasis on 20</span><span style="font-size: 12pt"><span style="font-size: 0.6em; vertical-align: super">th</span></span><span style="font-size: 12pt"> and 21</span><span style="font-size: 12pt"><span style="font-size: 0.6em; vertical-align: super">st</span></span><span style="font-size: 12pt"> century works. We will focus on representations of confinement by engaging with a wide range of genres â including fiction, poetry, plays, literary testimonies â alongside film and critical essays, to analyze the relationship between literature, history, and human rights.</span></p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14380,2026,4398,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-376','<div class="desc"> <p>Beginning with a close reading of the Quiché Maya myth of the <em>Popol Vuh</em> and its influence on Nobel-Prize winning Guatemalan author Miguel A. Asturias, this course discusses canonical Central American works of the nineteenth and twentieth century, with attention to the literary portrayal of war and violence by Nicaraguan and Salvadorean writers Ernesto Cardenal, Gioconda Belli, Claribel Alegría, Roque Dalton, and Manlio Argueta. The course includes some discussion of Central American film. </p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14381,2026,4399,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-379','<div class="desc"> <p>In <em>One Hundred Years of Solitude</em>, <em>Of Love and Other Demons</em> and <em>The General in His Labyrinth</em>, the Nobel-Prize winning Colombian author contextualizes Latin American, Colombian, and Caribbean history in differing ways. The course will discuss the allegorical, satirical, and realist uses of history in those three novels by García Márquez, with particular attention to the presentation of colonialism, nineteenth-century independence movements, slavery, and race relations. </p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14382,2026,3346,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-380','<div class="desc"> <p>This course examines the intersection of immigration, race, gender, sexuality, and nationality in contemporary Latinx cultural production in the US. Turning to cultural narratives of migration, we will explore the historical, political, and sociocultural processes that have led to the formation of Latinx diasporic communities in the U.S. and how these contexts have shaped the Latinx experience in the U.S. We will discuss questions of Latinx identity, migration, alterity, and belonging in cultural texts produced by different Latinx communities in the U.S. (such as Mexico, Colombia, The Dominican Republic, El Salvador, and Guatemala). By centering on a variety of cultural texts (including memoirs, novels, essays, poetry, short fiction, and film), this course examines the role culture plays in documenting the heterogeneity of Latinx identities, along with its intersections with other categories of difference (such as race, gender, sexuality, class, status, nationality). Some of the topics we will cover include: undocumented storytelling; coming-of-age Latinx narratives; narratives of migration and literatures of the borderlands; queer Latinx storytelling; Afro-Latinx narratives and erasures; and state violence, masculinities, and Latinx intergenerational trauma.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14383,2026,771,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-382','<div class="desc"> <p>This course analyzes the narrative development of the contemporary Mexican novel from the Mexican Revolution to the present. Principal novelists studied in this seminar are Mariano Azuela Juan Rulfo Carlos Fuentes Gustavo Sainz Elena Poniatowska Angeles Mastretta and Laura Esquivel. This course combines textual analysis with the application of contemporary literary theory.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14384,2026,389,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-383','<div class="desc"> <p>This course offers a representative overview of Chicano literary production covering five genres: poetry theater novel short story and essay. An historical framework is outlined to establish the different periods of Chicano creativity from its origins to contemporary times using a series of works and authors to illustrate their respective social context.</p> </div>','SPAN 301 , SPAN 302 , SPAN 303 , or SPAN 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14385,2026,4001,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14386,2026,772,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-397','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14387,2026,1428,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/300/span-398','<div class="desc"> <p>The goal of the Community Translation Internship is to provide students with an experiential understanding of the practice of translation. The Community Translation Internship allows students to learn through direct experience the different steps in the translation process as well as examine the challenges that bilingual professionals face in their efforts to reach out to underserved populations such as the Spanish-speaking communities. All students enrolled in the Community Translation Internship work with a community-based organization for an average of eight hours a week.</p> </div>','SPAN 340 or above and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14388,2026,390,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/400/span-490','<div class="desc"> <p>This course will provide an in-depth analysis of one or more of the following genres: drama poetry essay novel short story and film with an introduction to contemporary literary film and cultural studies theory. Texts will be drawn from Spain and Latin America. Open only to Spanish majors in their senior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14389,2026,3917,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/400/span-493','<div class="desc"> <p>Comprehensive-level work in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>When taken as a 4-unit course, you should expect to spend at least twelve (12) hours a week on this course. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14390,2026,4400,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/400/span-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14391,2026,773,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/span-spanish/400/span-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14392,2026,3188,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-100','<div class="desc"> <p>This course will look at the pivotal beginnings of the performance studies field, its roots in various disciplines, and will explore its evolution over the past 50 years. We will begin by asking, âWhat is performance studies?â and "How does it connect with theater studies?" Each week we will look at different answers to this question as we read and discuss the work of various artists and theorists from across the globe to see how their work illuminates the question. These readings will be complimented by viewings of performances so that we can engage the questions on both a practical and theoretical level and demonstrate the critical entanglement between performance theory and practice. As scholars and practitioners we too will experiment with praxis by activating each section with our own performance experiments. As much as this class is a historical survey of the field, it is also a laboratory where we will explore how we can perform in order to understand theory and how we can use theory to understand performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14393,2026,392,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-101','<div class="desc"> <p>In this course, students engage with the art of reading and writing theatrical scripts. By exploring the essentials of drama - characters in conflict, compelling language, resonant thematics, and bold theatricality - we investigate the elusive relationship between a play''s text and its ultimate destination: the live stage. The class begins by analyzing established scripts and ends with students creating their own. Along the way, we''ll discover the rule and rule-breaking techniques playwrights use, helping us to unlock the performative potential of their work and ours. The semester culminates with each student writing an original short play.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14394,2026,393,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-110','<div class="desc"> <p>This course is the foundation of our acting program and is 7 weeks in duration, allowing two sections to be offered each semester -- one in the first seven weeks of the semester and the other in the last seven weeks of the semester. This class is intended for students with a range of acting and performance experience - from the first time actor to the seasoned performer. Through group and individual exercises and projects, students will develop a stronger public presence, connection to and interpretation of text, as well as flexibility, concentration, and ways to live truthfully in imaginary circumstances. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14395,2026,394,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-120','<div class="desc"> <p>In this course we introduce students to many of the different areas of theater production with a primary focus on scenic construction, also including drafting, lighting equipment, rigging practices and special effects. <em>The course includes a laboratory through which techniques taught in class are applied. The laboratory averages 36 hours over the semester with laboratory schedules to be arranged with the instructor. Students are required to purchase some materials for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14396,2026,395,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-121','<div class="desc"> <p>Our production laboratories are applied courses for student designers, technicians and managers who are on crews of productions directed, designed or directly supervised by faculty members in the department. In order to complete a theater minor or major, students are required to complete production laboratories in two separate areas, one of which must be a running crew for a department production. The course may be repeated for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14397,2026,396,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-122','<div class="desc"> <p>These laboratories are designed for our student designers technicians and managers who are given primary responsibility on production crews directly supervised by faculty members in the department. In the laboratories students pursue additional research and practical applications beyond the requirements of THEA 121 and may use this course to meet one of the THEA 121 requirements for a major or minor. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14398,2026,3859,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-123','<div class="desc"> <p>While 2 121s are required for the major, students might work on other productions for credit. This course can be used for students who Assistant Direct, produce the NWF, and for other mentored production opportunities with approval from the Chair.</p> <p>This can be taken for 1 or 2 units depending on the project.</p> <p><em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14399,2026,397,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-130','<div class="desc"> <p>In this course students study the theory and apply the methodology of the Jose Limón Technique. Developed from the principles of fall and recovery the Limón Technique is built upon motion through succession suspension alignment and opposition. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14400,2026,774,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-131','<div class="desc"> <p>In this course students learn the fundamentals of jazz and tap dance with an emphasis on body alignment strength flexibility rhythm and coordination. During the semester we experiment with lyrical and contemporary jazz combinations as well as tap variations designed to develop musicality self-expression and performance skills. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14401,2026,398,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-133','<div class="desc"> <p>Tai Chi Chuan is the study and practice of slow controlled movement, breathing, and realignment of the body. Sometimes referred to as standing yoga, Tai Chi Chuan has been practiced for centuries for its many benefits, including stress management, disease prevention, and increase in energy. Our focus in this class is on relaxation, gentle movement, and meditation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14402,2026,399,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-134','<div class="desc"> <p>In <em>Beginning Ballet</em> we study the principles and execute the techniques of ballet based on the Vaganova method. Students are taught the fundamentals and elementary vocabulary of ballet through <em>barre</em> center and traveling combinations and exercises. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14403,2026,4401,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-135','<div class="desc"> <p>Classical Dance in India is a form of yoga, dance, and theater. Learn the foundational basics of two of the most popular and ancient Indian classical dance styles: <em>Bharata Natyam</em> and <em>Kathak</em>. Our semester will explore the elements of Indian dance including fast rhythms, moving<br/> expressions, and engaging story-telling. We will learn vocabulary and introductory dances in the classical forms, understand their relationship to dance in our current society and to western dance forms, and explore contemporary dance in India that is rooted to and in reaction to Indian classical forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14404,2026,1041,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-136','<div class="desc"> <p>What is Bollywood? A fun, expressive dance form that originates from the popular movie musicals out of the Indian film industry. A commercial dance style that has entered popular culture in both India and the US, Bollywood is a fusion dance style that incorporates elements from Indian Classical, Indian folk, Western styles of Hip Hop and Jazz, and world dance forms such as Salsa and African. It is a high-energy, cardio dance style that oozes style, expression, and grace. Students will learn the basics: <em>mudras</em>, foot work, and expressions to equip them in any Bollywood class or audition. They will also learn an array of choreography that covers the Bollywood landscape.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14405,2026,400,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-137','<div class="desc"> <p>This is an introduction to a study of choreography based on the Nikolais/Mettler methods of creating dances. Our tools include the manipulation of motion through space time shape and energy volumes within the context of the body and its surroundings; and our work culminates with studio performances of pieces choreographed by the students in the class. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14406,2026,401,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-139','<div class="desc"> <p>Exploring the richness of African dance and music traditions from four African regions, this course is devoted to the study of authentic dances, songs and drumming from Africa, as well as their historical and cultural contexts. Students may choose to focus on either dance or percussion. Percussion students will learn traditional rhythms for djembe and talking drum as they inform and interact with dance movements. Dancers begin with exercises to condition our bodies for the rigor of the African Dance forms -- developing strength, stamina, coordination, flexibility, and rhythmic awareness, and move to the informed and joyous practice of the dances. <em>Graded on a Credit/No Credit basis only. May be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14407,2026,1495,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-141','<div class="desc"> <p>We study and practice some of the most popular dance forms of the twentieth century. Through theater film and television many of these dances have expressed the spirit and the style and particularly the romantic temper of their times: from the quick steps of the Fred Astaire films to the swing dancing in <em>Malcolm X</em> and <em>A League of Their Own</em> and the tango of <em>The Scent of a Woman</em>. The dances taught include fox trot waltz swing and tango. We strongly recommend this class for our student actors. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14408,2026,403,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-142','<div class="desc"> <p>In this course students study folk and historical dances drawn from Eastern and Western Europe along with folk dances of the United States derived from those traditions. Performance opportunities may include Viennese waltz and dance-based children''s theater. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14409,2026,1742,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-143','<div class="desc"> <p>Students explore the rich traditions of Latin Dance from its origins in the African diaspora found in Cuba, Caribbean and Latin American nations as well as the influence and effect of these dances throughout popular Western culture. Students embrace through performance various dance forms developed in Mexico and throughout Central and Latin America and study the place and importance of the dances in Latin cultures.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14410,2026,775,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-175','<div class="desc"> <p>This introductory design course grounds students in aesthetics as they relate to design for performance and the role of design in the collaborative process of production. Those students interested in becoming designers receive a foundational experience for specializations offered in subsequent classes. Students explore elements of design and the principles of composition as they can apply to theater and film. Over the semester students come to understand and acquire the skills to develop visual expressions of the meaning of play and film scripts. Through individual and group design projects, students learn to incorporate script analysis, design research, and visual presentation techniques. This course is intended for first and second year students. Juniors and seniors may enroll with the permission of the instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14411,2026,1135,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-190','<div class="desc"> <p>Theater Now takes students off campus and in to local performance venues to see the work of diverse artists making theater from a broad base of inspirations. A wide sample of local theater is represented – thematically, geographically, culturally. Friday evening field trips take students to a variety of Los Angeles’ artistic outlets, while Monday afternoon sessions with guest artists put class members in direct contact with the actors, writers, and directors whose plays and performance pieces they have seen. Our work offers a comprehensive introduction to active theater-going, L.A.''s performance community, the creative habits of working artists and the social, political and aesthetic ideas behind their work. T<em>here is a ticket fee not to exceed $75 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14412,2026,3773,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-193','<div class="desc"> <p>Research in an area of theater &amp; performance studies that can include performances, producing, design, etc. Permission of instructor required.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14413,2026,2866,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-195','<div class="desc"> <p>What does performance do? Why perform? What is the essence of the “live” and what is the impact of being in the same time and (virtual) space? We will unpack these questions through analysis and performance, looking closely at seminal pieces that speak to this moment and calling on experts in design, technical theater, comedy and solo performance to give behind-the-scenes insight into the making of live performance. Bracketed around questions of liveness, social action, and impact, students will take specialized workshops with theater faculty who will address these questions through their areas of expertise, providing students opportunities to experiment with an array of performance practices.</p> </div>',NULL,'ARTS 250 ',NULL);
INSERT INTO course_descriptions VALUES(14414,2026,776,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/100/thea-197','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14415,2026,990,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/copy-of-thea-245','<div class="desc"> <p>Students in <em>Stage Makeup</em> learn the fundamentals of makeup design for the theater. We cover a number of makeup techniques including basic three-dimensional corrective, glamour, character and old-age makeups with some special effects makeup. During the semester, students put theory into practice as they create a variety of practical and creative makeup designs. <em>There is a materials fee for this course, not to exceed $75.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14416,2026,2567,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/copy-of-thea-290','<div class="desc"> <p>This topics course provides opportunities to work on performance outside of traditional naturalistic traditions. Topics change annually. First-year students may only take this course with permission of instructor. May be repeated once for credit when taken as a different topic. <em>Note: Different topics may satisfy different Core requirements</em>.</p> <p><strong>Autobiographical Performance: Laughing At Ourselves</strong></p> <p>In this course, participants will learn how to create compelling and humorous personal nonfiction narratives for the stage, studying classic narrative structure and paying close attention to theme &amp; detail. There is a long history of performers whose autobiographical solo work, like Crabb’s, simultaneously finds comedy in the tragedies of their lives while infusing the mundane with drama. To learn how to do this, students will study seminal storytellers and theater makers, (such as Spalding Gray, John Leguizamo, Whoopi Goldberg, Julia Sweeney, and others) who use their lives and experiences as templates for performance. Students will also review Moth-style storytelling to help find their own voice through a close examination of identity, self, and how we perform in the world.</p> <p dir="ltr" style="margin-top: 10px;"><strong>Clown and Comedy Class with Cirque du Soleil Clown and Wanlass Visiting Artist Daniel Passer</strong></p> <p dir="ltr">In this class, we dive into an exploration of the state of play through a series of exercises generated over many years as a clown and comedy conceiver for Cirque du Soleil, Dragone Entertainment and Saturday Night Live. The tools to guide the student on this journey to discover their unique, vulnerable point of view are: improvisation, status exercises, physical games, Commedia archetypes (Arlecchino, Pantalone, Doctore and others) and comedy routines. In this class, we explore the daring and vulnerability of the clown through embodying your passion, rediscovering a sense of play, and leading with joy. The pure, honest response to others (onstage and in the audience) provides a point of entry to incorporating a sense of fearlessness and authenticity into your work as a whole. As much a life philosophy as an acting technique, the performer is sure to come of class with a heightened innocence and curiosity feeding their moment-to-moment discoveries</p> <p><strong>Creating Community Engaged Theater</strong></p> <p>Under the guidance of members of the world renowned and community engaged Cornerstone Theater Company, this course will introduce students to the Cornerstone method of creating original theater work that addresses local concerns through community collaboration. During the course, students will help with The Highland Park Community Project—Cornerstone’s community engaged project in rehearsal and performance in the fall semester. This production will provide the experiential aspects of the course, some of which will take place off-campus in the Highland Park Community. In regularly scheduled class meetings, students will study the Cornerstone methodology, especially intention and engagement, and through discussion, lectures, and research, be introduced to existing approaches to community based theater. Topics will include how community engagement informs acting, directing and design. <em><em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></em></p> <p><strong>Extended Reality</strong></p> <p>For the spring of 2024, this course will be taught by Wanlass Visiting Artist Dawn Monique Williams. Through the semester we will explore hybrid performance techniques using digital/mixed/multi-media to expand the boundaries of live performance. No previous experience necessary.</p> <p><strong>Generating Independent Theater</strong></p> <p>This interdisciplinary course will provide an opportunity for students to define their interests as performers/writers/producers and to develop original material, an artistic vision, and producing expertise that will lead to a realized performance. Individual skill sets and interests including storytelling, dance, character-work, visual art and music may each provide a jumping off point for this work. At the beginning of the course, a series of improvisational exercises, mini-performances and character studies, supported by readings on contemporary solo, immersive, experimental and environmental theater, will guide students to land on personal solo or two-person projects. In the second half of the semester, students will craft these pieces utilizing their peers as a think-tank. This generative, collaborative process will emphasize the importance of ensemble both onstage and behind the scenes during the creative and production process. To culminate their work, the class will be responsible for the production aspects necessary to present their pieces in a public performance on-campus.</p> <p><strong>Reframe the Game: Strategies for a More Inclusive American Theater</strong></p> <p>Reframe the Game is a deep dive into Equity, Diversity and Inclusion (EDI) principles, as they apply to working in the theater, as well as in interpersonal communication practices. Through hands-on activities, discussions, research and interactions with guest practitioners, the course will address why this work is vital to our field, and how EDI lays the foundation for more creative and imaginative artistic workspaces and practices. The course will be organized into three parts. Part One will focus on Vocabulary and Power Structures: The cohort will focus on establishing a shared vocabulary as a foundation for conversation about social identity, privilege, historical and institutional inequities, and ally-ship, as a means to develop skills to better identify and dismantle inequity when we see it. We will look inward to examine where we as individuals fit into the social landscape of America, and how our identities affect how we move through the world. Part Two will focus Research and Examination: Students will research EDI initiatives and strategies at US regional theaters as case studies to examine how stated EDI principles may (or may not) align with programming and institutional culture. In addition, local guest artists and practitioners whose work strongly aligns with social equity will visit the class for deep dive conversations about the work that they do, the challenges they face, and where they see the future of our field. Part Three will focus on Final Projects and the question What Now?: In small groups, students will apply what they have learned over the course of the semester to create an original exercise, workshop or governing policy that addresses a specific EDI concern in their community (institutional, local, national or international) to present to their classmates and invited faculty in the final weeks of the semester. Prerequisite: THEA 101, THEA 210, or by instructor permission. <em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14417,2026,2891,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-200','<div class="desc"> <p><strong>Immersive Visual Environments with Commonplace Technology</strong></p> <p>Contemporary theater—especially as performed on Broadway—has become a high tech multimedia production with budgets in the millions. How can emerging theater artists compete with this level of spectacle and/or create new work that is equally compelling? In this course students will learn how to check the boxes of the newest innovations in big budget theater and performance without the financial demands. We will level the playing field by creating forms of high spectacle through economical means. Students will learn to devise spectacular visual stories using commonplace objects. Throughout this project based course, students will study the fundamentals of visual storytelling both through playing with lights and shadow led by cutting-edge artist Christine Marie and through developing story with performance artist and professional storyteller David Crabb. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14418,2026,988,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-201','<div class="desc"> <p>We study the artistry of contemporary theatrical movements as well as American writers from divergent cultural and aesthetic backgrounds. By looking at movements and artists in their cultural and social contexts we explore the sources the aims and the artistic strategies of their works while developing an understanding of important new voices in American Theater. The focus of the class will vary from year to year. May be repeated for credit one time with a different topic.</p> <p><strong>Looking for August: A Critical Exploration into the Art, Life, and Legacy of August Wilson</strong></p> <p>African-American playwright August Wilson is perhaps the greatest American dramatist of the 20th Century. His unmatched “Century Cycle” chronicles the African-American experience, and unearths deep-rooted dysfunctions of racism and socio-economic oppression, while at the same time celebrating the joy and resilience at the heart of African-American culture. Wilson was also an arts theorist, bringing to the fore front several explosive and controversial concepts concerning the American theater industry, particularly race-based vs. multicultural based casting. In this engaging course, we will explore Wilson’s epic, ever evolving career. Course participants will collaboratively engage with some of his most iconic characters, in the attempt to re-discover what makes them so impactful and electrifying. We will discuss Wilson’s life trajectory, his roots in Pittsburgh and griot approaches to playwriting, and peer deeply into some of his most iconic works, including Fences, A Piano Lesson, and the often misunderstood Joe Turner’s Come and Gone. We will also examine Wilson’s massive impact on 21st Century playwrights of all nationalities, and attempt to come to some comprehension of Wilson’s almost limitless influence on theater and global culture. </p> <p><strong>The Black Arts Movement Explored and Deconstructed</strong></p> <p>An in-depth, intellectually stimulating exploration into the complex and impactful Black Arts Movement of the 1960s and 1970s. Through reading and analyzing the poems, plays and criticism of the time, as well as lectures and small group discussions and “on your feet” performance activities, students will gain insights into the people, the places, and the critical junctures that emerged during this profoundly explosive era of art and culture. Artists explored include Amiri Baraka, Sonia Sanchez, Nikki Giovanni, Henry Dumas, Audre Lorde, Ed Bullins, Ntozake Shange, and others. Themes/concepts include black identity, the connection between black arts and black power, the rejection of integration as an ideal, LGBTQ and Black Arts, the assassination of Malcolm X, John Coltrane and Sun Ra, black radical thought, the African-American male as a Christ figure, male chauvinism in Black Arts and Black Power, and “future directions,” i.e. the influence of the Black Arts Movement on other cultural movements and American aesthetics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14419,2026,404,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-202','<div class="desc"> <p>Looking at a small number of Shakespeare''s scripts from the vantages of actor director and playwright we examine the unique and complex relationship between Shakespeare''s literary constructions and their possible performances. We analyze how through language and structure he develops characters of psychological complexity; how he develops stories from extra-theatrical material; and how in style and subject matter his scripts relate to one another. This course offers students a bridge between literary study and theatrical enactment: looking closely at Shakespeare''s designs from the perspective of the theater practitioner-from in most ways Shakespeare''s own perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14420,2026,1136,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-203','<div class="desc"> <p>In this course we investigate a variety of 20th and 21st century theatrical productions across the globe staged during times of conflict and crisis: from online performances to amateur stages in restaurant back rooms in workers'' clubs and cafes to professional and Broadway theaters. From the 1920''s agitation trials (<em>Agitsudy</em>), mass spectacles and agitprop theater during the Russian Revolution to contemporary theater''s responses to COVID 19, anti-blackness, and other forms of racism and social oppression, we will examine how artists and activists use theater to respond to social and political unrest: sometimes as a tool to fight oppression and at other times as a tool to encourage obedience and propagate national political ideals. From performances staged in Sarajevo to Rio de Janeiro, from Mexico City to New Orleans, and from the streets of Moscow to the streets of New York City and beyond, the class thinks through art as activism and activism as art, examining how theatrical tactics transcend the boundaries of traditional performance spaces. We examine the performance theories and strategies emerging from these theatrical moments as we study seminal plays from these periods. For the final project, students in the class will develop performance projects in response to a contemporary crisis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14421,2026,1317,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-204','<div class="desc"> <p>In this course, we introduce students to the ways comedy can influence and transform society. We will study scripted as well as unscripted forms of performance, including stand-up, physical comedy, sketch, Teatro Campesino style <em>actos</em>, and faux news shows. Students learn the formal structure of the different comic forms through extensive writing and revision both individually and in collaboration with other students. Students develop an understanding of the role comedy plays in socio-political critique through research of issues about which they are passionate and in the subsequent creation of solo and group work illuminating those issues for their peers in a final cabaret performance. Not open to frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14422,2026,2362,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-205','<div class="desc"> This course addresses the fluid boundary between law and performance. We will think through how performances of law influence legal practice and vice versa. We will also interrogate how theater provides an alternative site for the performance of justice, one that may satisfy needs that go unmet in state and federal courts. We will study trial transcripts as legal and cultural documents, and we will look at their dramatizations, putting these plays into conversation with contemporary theater, performance, and legal criticism while also thinking about how our own needs and impressions of justice have been, or can be, staged in and through performance. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14423,2026,2900,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-206','<div class="desc"> <p>In this energetic and creatively maddening class, students will explore Shakespeare’s <em>Richard III </em>and several adaptations in a unique and highly charged manner. By yanking the Bard off his high horse, and identifying universal themes and structural innovations inherent in Elizabethan poetic meter, course participants will gain newfound understanding and appreciation for the work and legacy of Shakespeare. Instead of looking at classic works as an untouchable, or “holier than thou,” canon instead we will investigate how playwrights have been inspired by, deconstructed and reconstructed them. In addition to Shakespeare’s <em>Richard III</em>, students will explore several bold adaptations such as Carlyle Brown’s <em>The African Company Presents "Richard III,"</em> <em>Teenage Dick </em>by Mike Lew, as well as Will Power’s own <em>Seize the King</em>. Perhaps most importantly, students will have the opportunity to learn iambic pentameter, construct their own post-modern, Shakespearean mash-up scenes, and learn the very-latest contemporary methods of verse-based performance. In this performance seminar, we will compare and contrast Shakespeare’s metric language with other heightened language forms, from ancient Greek poetry to hip hop lyrics. Filled with rhythm, poetry, and both an appreciation and utter disdain for anything old and crusty, this course promises to be a ridiculously crazy, wild ride for the ages. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14424,2026,405,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-210','<div class="desc"> <p>In this course students develop a deeper sense of physical expression, kinesthetic response, ensemble work, creativity, and imagination. Students apply this training in solo and scene work both in the studio and on camera. At the end of the semester, students apply the preparation and techniques learned throughout the semester in final scene projects using script analysis, character work, object work, and physical expression in both classical and contemporary texts. <em>There is a ticket fee not to exceed $50 for this course.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14425,2026,406,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-211','<div class="desc"> <p>Our Performance Laboratory is offered as an applied acting course based upon roles played in our professionally directed Keck Theater productions. This course is offered only for grades of Credit/No Credit and may be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14426,2026,777,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-212','<div class="desc"> <p>In this course student actors will continue to develop audition techniques introduced in <em>Introduction to Performance</em> and <em>Acting 1</em> applying them to the standard "general audition" format. In addition our students learn about the audition and casting process in professional theater through a guest speaker series of casting directors and professional film and stage actors. Not open to frosh. <em>Graded on a Credit/No Credit basis only. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14427,2026,778,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-215','<div class="desc"> <p>Working with selected scripts from the best of recent and contemporary screenplays our students develop techniques for working in front of a camera as a specific application of the work of both <em>Acting 1</em> and <em>Acting 2</em>. <em>There is a materials fee of $60 for this course. THEA 310 is strongly recommended as preparation.</em></p> </div>','THEA 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14428,2026,408,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-234','<div class="desc"> <p>Students develop and refine ballet technique based on the Vaganova Method. This course is offered only for grades of Credit/No Credit and may be repeated for credit.</p> </div>','Two semesters of THEA 134 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14429,2026,782,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-237','<div class="desc"> <p>Building upon the work from <em>Beginning Choreography</em> students develop more sophisticated choreographic strategies language and techniques with an emphasis on group choreography including site-specific work and studio performances. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','Permission of instructor required ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14430,2026,411,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-244','<div class="desc"> <p>Our stage management course introduces students to the art and techniques of stage management helping them acquire the theoretical knowledge and the practical skills to manage theatrical productions from casting through performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14431,2026,883,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-246','<div class="desc"> <p>In <em>Costume Construction</em> students acquire the skills necessary to construct basic garments for the stage. At the end of the course each student will build a costume piece.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14432,2026,4402,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-247','<div class="desc"> <p>This course applies acoustics, electronics, and digital audio theory in the assembly and operation of Public Address (PA) systems for live concerts. We cover the practice of live sound engineering in different contexts, with a focus on skill building in the technical aspects of live music. Students will assemble PA systems and operate a front of house mixing console for a host of music events both on and off campus. Students will also learn how to set up microphones, use a graphic equalizer to tune a PA system, and run individualized monitor mixes during live performances. Lessons about the theory and practice of live sound will be presented alongside practicum exercises in live engineering, culminating with running tech for several concert-length live performances. Live recording in a DAW-based multi-track session will also be a component in the later portion of the semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14433,2026,1042,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-248','<div class="desc"> <p>We introduce students to the theory and application of sound and music as elements of design for theater dance and other collaborative multimedia dramatic forms. Throughout the semester we address fundamental issues of sound design: including script analysis conceptual approaches to sound music underscoring working with audio equipment and sound editing. Over the semester our students learn how to work within a creative team of designers coordinating the many design elements of various dramatic forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14434,2026,1102,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-250','<div class="desc"> <p>Period style can be characterized as the aesthetic traits common to a particular historic or cultural moment. For recorded media and live performance, writers, directors and designers set their storytelling in a framework of time and place. In this class, we explore examples of shifting styles across select non-Western and Western cultures and through time and seek to discern their influence on other cultures or historical periods. Through this exploration, we begin to understand how architecture, interior design, fashion history and the act of dressing evolved throughout the centuries and across cultures because of technological advancements, changes in economic and social class structures, in political climates and through appropriation of cultural aesthetics. Why was there a kimono specialist in the costume department of <em>Westworld</em>? How did Ruth E. Carter develop her Afrofuturist vision for <em>Black Panther</em>? Where would you find visual and dramaturgical resources for <em>Vietgone</em>, or <em>Hair</em>, or <em>Cambodian Rock Band</em>, the action of each set in a similar historical period but whose stories are told from very different cultural perspectives?We will investigate these and other questions through reading, and critical analysis of visual records, plays and films, in-class discussions, and presentations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14435,2026,412,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-260','<div class="desc"> <p>This course is a community engaged course - One of two separate applied workshops in teaching theater and performance in public schools that focus on classroom management and education with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take 260 and 261 in either order. In four intensive sessions, students learn five workshops geared to the third grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Preferably, the students in the course will have taken at least THEA110 because part of teaching theater to students is to co-create and perform with them, using one''s artistic tools and techniques to teach the students how to embrace their creativity. Students will develop proficiency in being a teaching artist, which in itself is a creative practice that fuses pedagogy with performance. Students will develop their voices as teaching artists, a skill they can apply in their own creative practice and is translatable into other areas. Enrollment is limited.</p> </div>','THEA 110 and/or Permission of Instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14436,2026,783,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-261','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take THEA 260 and THEA 261 in either order. In four intensive sessions students learn five workshops geared to the fifth grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited. Graded on a CR/NC basis only.</p> </div>','THEA 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14437,2026,413,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-275','<div class="desc"> <p>The Scenic Design Studio course offers an immersive exploration into the artistry and techniques behind creating captivating and functional stage environments. Through hands-on model-building projects in a studio format, we will delve into the multifaceted world of scenic design, equipping students with the foundational skills necessary for crafting compelling theatrical spaces.</p> <p>Throughout the semester, we will investigate the historical evolution of scenic design, analyzing key movements, influential designers, and the impact of technological advancements on stagecraft. Emphasis will be placed on understanding the relationship between visual storytelling, dramatic narrative, and spatial design.</p> <p>The course will cover fundamental principles, including:</p> <ol> <li><strong>Design Process</strong>: We will learn to conceptualize, develop, and communicate their ideas effectively through sketches, models, and drafting techniques.</li> <li><strong>Set Construction and Materials</strong>: An exploration of materials, construction methods, and practical considerations essential for bringing designs to life on stage.</li> <li><strong>Script Analysis</strong>: Analyzing scripts to extract thematic elements, mood, and atmosphere, and translating these into visual design concepts.</li> <li><strong>Historical and Contemporary Perspectives</strong>: Studying the evolution of scenic design from traditional theatre to modern and experimental forms.</li> </ol> <p>In addition to theoretical discussions, we will engage in hands-on projects, culminating in the creation of their own scenic designs for selected plays. Students will have the opportunity to execute the designs through scaled models, drawings, or digital representations, honing creative skills and practical application of design theories.</p> <p>This course encourages critical thinking, creativity, and problem-solving within the realm of scenic design, preparing students for further exploration in the field of theatre production or related artistic endeavors.</p> </div>','None. However, a strong interest in theatre, design, or visual arts is recommended. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14438,2026,991,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-295','<div class="desc"> <p>Topics vary from semester to semester. Specific topics may satisfy different Core Program requirements. This may be repeated twice for a maximum of eight units.</p> <p><strong>Hip Hop Performance</strong></p> <p>What are the intricate, performative aspects of hip hop culture? How is the performance of hip hop culture powerful, revealing, potent and contradictory, all at the same time? This course examines Hip Hop as performance, and exposes both the sacred ritual of “rockin’ the mic,” as well as the various modes of complex expressions that the culture has developed and delivered to the world. Together we will wrestle with the various performative practices of legendary rappers such as Jay Z, J Cole, Cardi B, Travis Scott, and Nicki Minaj. We will imagine hip hop performance as what occurs both on the stage through lyrics, music, and stage techniques, as well as how hip hop manifests as performance off the stage, through the crafting of image and the manipulation of (or being manipulated by) social and mass media. Course participants will comprehend various performative trajectories in hip hop couture, including the layered performance of women in hip hop, as well as hip hop as expressed in the LGBTQ+ communities, and how these diverse reflections compare, contrast, and ultimately merge to create a definitive, yet sometimes elusive statement about what it means to perform hip hop artistry in the 21<sup>st</sup> century. And finally, students will get the opportunity to learn hip hop performance techniques, and experiment with these techniques in a safe, non-pressurized environment. <em>Additional Core Requirement Met: United States Diversity.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14439,2026,4403,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/200/thea-297','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14440,2026,1356,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/copy-of-thea-315','<div class="desc"> <p>In this course, designed for the novice performer as well as the advanced actor or singer, we focus on introducing students to the art of acting a song. We examine the literary and musical elements of scripts to reveal character and narrative, only here we do this while singing. Performers prepare and present musical selections from the Broadway canon, exploring how the elements of healthy singing (including breath control, phrasing, and placement) help convey character and story. Through freeing our musical voices to best express persona and narrative, we we examine the intersection of singing, acting, and audience connection. All experience levels welcome. A ticket fee, not to exceed $50, is associated with this course. Prerequisite: at least sophomore standing or permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14441,2026,993,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/copy-of-thea-320','<div class="desc"> <p>Building on the foundation of Introduction to Technical Theater, the students in this course learn advanced construction techniques, metal working and welding, furniture construction and repair. Students in the class will also act as crew chiefs for Theater Department productions.</p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14442,2026,414,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-301','<div class="desc"> <p><span style="background-color: #ffffff; color: #222222;">Topics vary semester to semester.</span><strong></strong></p> <p><strong>Survey</strong></p> <p>As artists and scholars, we will discuss and study several key moments in theater history from Greek Drama to Medieval religious performances to modern and experimental theater. Throughout the semester we will examine theater-in-context, attending to the circumstances (political, social, historical, and artistic) surrounding the performance event. We will engage with drama theory to deepen our analysis of dramatic texts and the performances of them. With an emphasis on close readings, critical thinking, and creative engagement with the materials, we will interrogate the boundaries between performers and audience and the ways theater makers have used performance to challenge or affirm the status quo. Topics will vary. <em>There is a $25 ticket fee for this course.</em></p> <p><strong>History of Indian Performing Arts</strong></p> <p>This class will delve into the rich and vast history of Indian performing arts and its present forms. Starting at the roots, students will study Indian theater which was an all-encompassing art form that included dance and music as integral elements. The class will include the following: A look at the Naytashastra in its comparison to Aristotle''s Poetics; a study of the different forms of theatre (classical and folk) and thereafter the branching out of classical dance; to present day work being done in India in contemporary theater, dance, and Indian cinema (independent vs commercial Bollywood) and its relationship to its roots and how it carries on a performance legacy.</p> </div>','THEA 100 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14443,2026,992,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-302','<div class="desc"> <p>During the semester we study the works of various twentieth century playwrights. Different years will feature different playwrights: so one semester might look at farceurs another semester political pioneers and another European iconoclasts. In addition to reading several scripts by each playwright our students also attend live performances prepare research projects and create performance projects in response to the semester''s writers. Students may use this course to fulfill the Junior Writing Requirement for the Theater Major.<em> There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14444,2026,1496,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-303','<div class="desc"> <p>The focus of this course is on the history literature and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works while play attendance will keep our focus on these plays as performance. <em>There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14445,2026,415,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-310','<div class="desc"> <span>Topics vary by semester.</span><span><br/> </span><br/> <span><strong><span style="text-decoration: underline;">Scene Study</span></strong></span><br/> <span>This advanced scene study course focuses on the works of seminal American playwrights. Through intensive text analysis and performance, students will explore the themes, characters, and cultural contexts that define these playwrights’ contributions to the American theatre canon.</span><br/> <br/> <span>Students will develop a deeper understanding of the playwrights'' distinctive voices. Emphasis will be placed on honing acting techniques, deepening emotional authenticity, and refining character development to bring these complex works to life. By the end of the course, students will have the skills necessary to tackle rich, challenging texts and will gain insights into the historical, social, and cultural underpinnings of these masterpieces. Designed for actors who have taken 210 &amp; 110, this course requires a strong foundation in acting techniques and a commitment to rigorous creative work.</span><br/> <span><br/> </span><strong><span style="text-decoration: underline;"><br/> Solo Performance</span></strong><br/> <span>Advanced Acting builds on the techniques and skills introduced in Acting 1. Students will continue to explore character development and scene work through an array of texts and styles. Students will also explore acting methods that will help them become more flexible, daring, collaborative, and creative performers. An emphasis will be put on Solo-Performance techniques. Students will actively create a self-sustaining piece of solo theater from conception to creation and finally to the stage. Course participants will also discover and evaluate texts and performance practices of previous solo-theater practitioners. In the process, students will learn how to act with increased freedom and to create characters with genuine psychological complexity, accumulating tools and skills applicable to working both on stage and on screen.</span> </div>','THEA 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14446,2026,417,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-311','<div class="desc"> <p>Our upper-division applied acting course is available for students performing significant roles in professionally directed Theater Department productions. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit. It is available only with permission of the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14447,2026,784,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-316','<div class="desc"> <p>In this culmination of the Theater Department''s acting sequence our students explore through practice the demands Shakespeare''s scripts make upon actors. During the semester students in the class work with five to six of Shakespeare''s scripts from various genres in order to develop facility with Shakespeare''s verse and prose in performance.</p> </div>','THEA 202 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14448,2026,994,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-325','<div class="desc"> <p>Studying the theories the psychological foundations and techniques of lighting design for the theater our students develop in this course an intellectual and practical foundation of this significant and accessible area of theater design. During the semester we guide students in the class through bothindividual and group design projects. <em>There is a material/tickets fee of $60 for this course which includes one two-hour laboratory session each week.</em></p> </div>','THEA 120 or THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14449,2026,785,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-330','<div class="desc"> <p>Students in this course analyze the various requirements for producing live performance events. In developing solutions to the many difficulties presented by live events we examine in particular the artistic, legal and financial responsibilities of the producer. Through projects, case studies, and research, our students look at the creative and practical aspects of live presentations as they come to understand the myriad considerations required to successfully produce live performances for theater music and other cultural events. Not open to first year students.</p> </div>','THEA 120 and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14450,2026,418,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-370','<div class="desc"> <p>This course concentrates on the skills needed to conceptualize and draw costumes for the stage and screen. In addition to drawing skills, students will learn how to break down scripts to understand and interpret a character’s world and maintain continuity in design. Costume Design is for students with wide-ranging drawing skills, including beginners. Students will learn to draw a variety of fabrics–including sheer fabrics, sequins, feathers, and patterned fabric. Live figure drawing and shorthand sketching techniques provide a foundation for sharing your creative vision. Artistic mediums covered include freehand drawing, digital rendering, and collage. A portion of the course focuses on budgeting and hidden costs in costuming for film and theater.</p> </div>','THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14451,2026,419,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-380','<div class="desc"> <p>We engage our students in Playwriting with the art of writing for the live stage. Through reading scripts by established authors and generating original writing, students develop their dramatic skills and theatrical imaginations. Creative assignments focus on crafting well-developed characters, sound story structures and compelling dialogue. As a final project, each student writes and rewrites a short play. THEA 101 is a pre-requisite.</p> </div>','THEA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14452,2026,420,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-390','<div class="desc"> <p>For advanced theater students we offer an applied course for significant work undertaken in performance design technical theater or management in faculty-supervised projects. A student enrolled in this course works directly with a faculty mentor in the design and execution of the individual project. </p> <p>Section 1 - Advanced Projects in Theater: Story/Voice/Community </p> <p>Section 2 - On-campus projects</p> <p>Permission of instructor required. Course may be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14453,2026,3776,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-393','<div class="desc"> <p>Students doing directed research at the 300 level will have completed substantial coursework in the TPS major. Students are expected to be proficient in the areas of work involved in the project and should be able to work more independently, to mentor novice students, and to begin to propose new areas of inquiry. </p> <p>The directed research could take the form of directing a performance, devising an original performance, playwriting, original research for a paper, designing scenic, lighting, or costume elements, technical directing, stage managing, and all the dramaturgical analysis that goes into such a project and that it is under the mentorship of a faculty member. The learning goals of directed research is for the students to:</p> <ul style="margin-top: 0in; list-style-type: disc;"> <li>apply and develop proficiency in the skills and tools they have learned in earlier courses and experiences </li> <li>work independently to lead a team (if applicable), collaboratively, and in line with their design/directorial/technical vision</li> <li>conduct and execute original work</li> <li>incubate new ideas and use this opportunity as an incubator for future work </li> </ul> <p>Permission of instructor is required. </p> </div>','Permission of the instructor and a B- or higher in an advanced course in the area of the student''s research ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14454,2026,4404,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14455,2026,787,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/300/thea-397','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14456,2026,788,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/400/thea-410','<div class="desc"> <p>We introduce students to the art of directing. Our students explore the directing processes of script analysis casting working with actors manipulation of space use of sound and images developing designs and mounting productions for theater. During the semester students in the class stage two performance sequences: one in a classroom format the other produced on the Keck stage. THEA 316 is strongly recommended for preparation. This course may be repeated for credit. Permission of instructor required.</p> </div>','THEA 120 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14457,2026,421,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/400/thea-490','<div class="desc"> <p>This is a course for students engaged in senior comprehensive projects in Theater. <em>Only open to senior Theater majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14458,2026,4405,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/thea-theater/400/thea-497','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14459,2026,423,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-101','<div class="desc"> <p>This is an introductory course on environment and society designed for students with an interest in urban and environmental issues who might want to pursue further studies in Urban and Environmental Policy. It is also offered for those who are interested in the topic even though they will be pursuing another major. The course will include lectures and presentations in several different topical areas; films and speakers that provide insight into the environmental problems and alternative solutions including those based here in Los Angeles; and class discussions and presentation sessions on the readings and topics. The course provides an broad introduction into core topics in urban and environmental policy such as: water issues (where our water comes from); wastes and hazards issues (sources and impacts of pollution); climate change transportation and land use issues (where we work and live and commute); nature in the city (the urban environment); and food system issues (where our food comes from and how it is manufactured and sold) the intersection of science and policy and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14460,2026,3350,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-120','<div class="desc"> <p>The FEAST Garden Practicum is a hands-on introductory class designed for students with an interest in learning about and applying sustainable agriculture techniques. Students will gain a deeper understanding of agricultural management and small-scale farming. With leadership provided by the FEAST Faculty Advisor and FEAST Student Managers, students will engage in seasonal farming activities with a focus on edible and medicinal plants, native habitat and pollinator gardens, resource and water management, chicken stewardship, the basics of soil health and compost, as well as how to organize and host community events. Graded on a Credit/No Credit basis only.</p> <p>Note: This class will not count towards a UEP major or minor elective</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14461,2026,3916,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-150','<div class="desc"> <p>This course focuses on teaching students how to access, integrate, and quantitatively evaluate many types of spatial information using different methods of analysis. Students use GIS software to understand, explore, and analyze information from a variety of sources, with an emphasis on understanding the geography of environmental health and the relationships between multiple determining factors. Students will learn fundamentals of geography and cartography, GIS techniques in quantitative spatial analysis, and introductory spatial statistics as applied to vector-based data. The tools and skills used in this course, and the analytical problem-solving projects used in laboratory and project assignments, will provide them with a means to better understand the environmental health risk and epidemiology, and enhance their ability to make informed and quantitative comparisons. (Students are encouraged to enroll in UEP 201, a course that explores how environmental factors impact human and ecological health).</p> </div>',NULL,'UEP 150L ',NULL);
INSERT INTO course_descriptions VALUES(14462,2026,4046,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-160','<div class="desc"> <p>An introduction to techniques of spatial analysis using GIS. You will study the fundamentals of geography and data science that guide you to valid approaches to practical problem-solving and investigate timely environmental questions that matter using real-world data: vector and raster geospatial datasets, aerial photos, satellite imagery, LiDAR. The course also includes a project combining GIS data acquisition and analysis to solve a practical question on the Oxy campus. This course will help you learn a valuable job skill that can apply to many different careers and interests. You should feel comfortable using the MS Windows operating system and Microsoft Excel software. Includes one three-hour laboratory per week. </p> </div>','UEP 150 , UEP 305 , or instructor permission ','UEP 160L ',NULL);
INSERT INTO course_descriptions VALUES(14463,2026,4406,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14464,2026,1357,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-201','<div class="desc"> <p>This course is designed to provide students with an understanding of the environmental factors impacting human and ecological health including consequences of natural and human-made hazards. Environmental health is a rapidly growing and interdisciplinary field that involves both science and public policy. It is integrated into numerous aspects of our lives both directly and indirectly. Topics to be covered include food safety water access and equality pesticides air quality the identification of environmental hazards the assessment of various risks (including exposure to dangerous chemicals used in toys food workplaces and other activities) and the social and biological causes of disease (epidemiology) Students will gain an understanding of environmental health analytical and scientific methods. We will also explore ways that communities and policy-makers seek to address environmental health challenges. A common thread running through the course will be an examination of how exposure to environmental and health risks vary among different population groups in the Los Angeles area in the United States and around the world and the ways that scientific issues become embedded in and inseparable from issues of policy regulation and justice. We will also explore the role of science in environmental policy-making the enforcement of regulations and the efforts of community groups to influence public policy. (Students are encouraged to enroll in Geology 150 a laboratory science that in parallel explores the spatial and geographic dimensions of environmental health.</p> <p>Not open to frosh without permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14465,2026,424,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-205','<div class="desc"> According to Thomas Jefferson, America was to be an "agrarian Republic" -- a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones as well. Indeed, for many early migrants, America was itself a "city on the hill" -- an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing in the second half specifically on Los Angeles, where new forms of decentralized urbanism took form in the twentieth century. We will explore not only suburbia and freeways, Disneyland and other quasiÂ­urban outposts, but also the changing character of the inner city in the midÂ­twentieth century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today -- multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism -- the changing character of public space, the turn to privatism, and the neglect of public transport infrastructures, challenges to democracy and equality -- are ultimately compatible with the American dream of the "city on the hill" for the twentyÂ­first century. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14466,2026,1198,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-209','<div class="desc"> Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14467,2026,884,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-210','<div class="desc"> <p>Los Angeles is a city often known for its traffic, air pollution, auto-centric land use patterns, and car culture. However, Los Angeles is also a place of transportation innovations and a public commitment to changing the way people move to and through Los Angeles in equitable and environmentally sustainable ways. This class provides an overview of urban transportation issues and systems, focusing on the impacts of mobility policies, systems and infrastructure on cities and on Los Angeles in particular. Through lectures, guest speakers, class exercises and projects, students will explore the history of transportation in the US as well as comparatively with other countries and understand the role of policy in shaping and defining transportation systems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14468,2026,1103,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-214','<div class="desc"> <p style="margin-left:0px; margin-right:0px">The struggle for control of our public education system in Los Angeles has become one of the most high profile conflicts facing the city and its residents. The stakes couldn’t be higher. The lives of children and the hopes and dreams their parents literally hang in the balance. In UEPI 214, Professor Steve Zimmer, a long-time teacher and the former President of the Los Angeles Unified School District Board of Education, will guide students through a journey in understanding the role of public education in our society and tensions over different visions and goals for public schools, including its mission to promote equality, equity, and mobility. The course will also explore how public policy can help or hinder public school’s equity mission. The class will examine the effects of expanding racial and economic segregation, increased standardized testing, and toxic stress have on students trying to pursue their dreams and the teachers trying to make those dreams come true. The class will also assess the impact of teacher tenure reform, the expansion of charter schools, the community schools movement and other policy based debates that could influence the future of teaching and learning. Through guest lectures, panels, films, and readings, students will understand the role that policy and collective action can play in pursuing a collaborative agenda. The final project will involve actually writing policies to be presented to the Board of Education and/or other policy makers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14469,2026,1743,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-230','<div class="desc"> This course will cover the problem of climate change and the history and evolution of the climate justice movement. It will examine the organizing and policy tools used by advocates to advance climate justice. The course will begin with an exploration of climate change, the environmental and political factors that cause the climate to change, and why the issue matters to communities across the globe. The course will then look at the history and foundational concepts of climate justice with particular focus on how issues of race and class impact climate justice. Finally, the course will look at how the traditional environmental movement, the labor movement, and global movements advocate for climate justice and what priorities they advance. Key topics to be covered are: the intersection between race and the environment, the relationship between traditional environmental movements and the environmental justice movements, labor movements and the green economy, global solidarity movements. </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14470,2026,3828,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-240','<div class="desc"> <p>An in-depth class on backyard poultry and its connection to regenerative agriculture with a focus on an holistic and sustainable approach that prioritizes the health and well-being of animals, the environment, and the people involved in the process.<br/> <br/> Topics include: understanding animal welfare, legal aspects; California vs. US humane laws, overview of breeds, chicken and duck facts and behaviors, setting up proper biosecurity and how to maintain it, creating your own feed and cost effective tricks, store bought vs. pasture raised, environmental enrichment, first aid / natural and holistic solutions, health management and overview of common illnesses, troubleshooting, how to spot and diagnose sick chickens, coop management and soil and composting.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14471,2026,425,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-246','<div class="desc"> <p>This course is designed to assess and develop recommendations regarding environmental issues related to the Occidental campus with attention to sustainability as encompassing urban environments and issues of equity, justice, and community. Students will evaluate the College''s current practices such as energy and water use, transportation and parking, building construction and maintenance, landscape and grounds maintenance, hazardous and solid waste generation and management, educational and outreach strategies and how the College''s environmental issues relate to the larger Northeast Los Angeles community. Students will develop proposals and programs to reduce resource use and the College''s overall ecological footprint while also seeking to identify how the College can itself play a positive role in increasing the environmental sustainability of its neighboring community. The course is designed to develop project management and environmental leadership skills with the campus as the arena for change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14472,2026,789,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-247','<div class="desc"> <p>This class is a collaboration between the Urban and Environmental Policy Institute (UEPI) and the FEAST (Food, Education, and Sustainability Team) student service to enhance student capacity to lead and engage with food and gardening projects both on campus and in the community. Through the implementation of projects in campus garden spaces, participation in community service learning projects, and field trips to innovative food programs in Los Angeles, students will gain hands-on understanding of food issues and will complete the course with the ability to help in the design, creation, and maintenance of a garden-based food or sustainability project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14473,2026,1430,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14474,2026,3850,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-270','<div class="desc"> <p>Labor unions are the largest membership-based organizations in North American cities: they play a vital role in mobilizing urban residents, shaping urban conflict, and crafting policies that transform urban space. This course investigates the practical realities of union involvement in urban politics. It focuses on a variety of economic and government sectors (education, film, hospitality, green energy, child care, and healthcare) and explores how workers in each of these industries orient themselves toward city life; how they imagine more just and sustainable urban futures; and how they organize to make these visions real. It also considers the dilemmas that unions weigh as they make decisions about which political campaigns to take on vs. which to set aside, and how much time to dedicate to existing union members vs. the non-union workers who make up the majority of urban residents. Finally, this course invites students out of the classroom and into the field to explore the L.A. labor movement in-action. Students will be invited to to observe, interview, and speak with union members about how they understand their role in city politics; the kinds of collective actions that move the policy needle; the aspirational claims that workers make on urban futures; and how to confront the rapidly changing nature of work in fast-paced, technology-driven urban industries.</p> </div>','This course requires a basic understanding of both unions and cities, which the prerequisites below provide. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14475,2026,1138,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-295','<div class="desc"> <p>Topics vary semester to semester.</p><p><strong>Poverty and Inequality in America</strong></p><p>This course will examine why the U.S. has more poverty and more inequality than any other wealthy nation -- and what we can do about it. The course will include class discussion, readings, and films. Among the topics we''ll discuss are: Who benefits and who suffers from America''s high of poverty and inequality? Should our society try to significantly reduce poverty and inequality? If so, what can we do? Who is poor in America? Who is super-wealthy? Who is middle class? What are the major stereotypes about the lives of the poor and the super-wealthy? How have issues of race, gender, and immigration influenced the level of poverty? Why are poor, middle class, and wealthy people in America concentrated in certain locations - more so than in other wealthy societies? Has government policy made poverty and inequality better or worse? What political movements and policy reforms have made a difference in improving the lives, and reducing the number, of America''s poor? How can poor Americans and their allies influence politics and policy?<br/><br/>Students who want to get a head start on the readings should read Barbara Ehrenreich''s book, "Nickel and Dimed: On (Not) Getting By in America."</p><p>This topic is cross listed with SOC 295.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14476,2026,1634,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14477,2026,2568,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-300','<div class="desc"> <p>This course analyzes the legal and policy framework for environmental protection and environmental justice. The course covers the major environmental statutes, applicable civil rights laws, and the next wave of climate change litigation. This course will also place environmental law and policy within the larger conversation around environmental protection and climate change.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14478,2026,790,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty, housing, transportation, crime and violence, pollution, racial segregation and gentrification. It also examines how power is exercised by different groups including business, citizens'' groups, community organizations, unions, the media, mayors and other government officials. The course will also examine the role of city planning and planners, conflict and cooperation between cities and suburbs, problems of urban sprawl, loss of open space, water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe, Canada, and the developing world. Public policies to solve urban problems.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14479,2026,996,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-302','<div class="desc"> <p>This course examines how societies provide people with shelter - through market forces government policy and self-help efforts. The course will focus on the United States but will also look at other societies to help understand the strengths and weaknesses of the U.S. approach. Students will examine such housing problems as homelessness slums (substandard housing) the shortage of affordable housing racial segregation foreclosures and other topics. It will examine the pros and cons and different forms of rental housing and homeownership. It will look at the connection between housing issues and the environment public health education transportation suburbanization and sprawl poverty and inequality and racism. Students will explore housing as an aspect of our culture such as homeownership as the "American dream" and housing as a "haven." The course will explore the history of housing problems and housing policy including zoning racial discrimination finance public housing different government subsidies for housing and taxes. We will debate whether decent housing is a "right". We will look at housing problems and policies at the local state and national levels. Students will explore the politics of housing in terms of the various interest groups - including developers banks tenants community organizations landlords contractors unions and others -- involved in shaping housing policy. Students will also learn about housing as part of the "built environment" architecture land use urban design as a component of urban planning and as a part of "livable" cities. They will also examine housing as a component of real estate development and explore what housing developments - whether for-profit or non-profit - do.</p> </div>','UEP 101 , ECON 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14480,2026,791,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-303','<div class="desc"> <p>This course examines sustainable development from a social economic and environmental perspective. The course focuses on development strategies and approaches led by community-based labor and nonprofit organizations in a context of traditional public and private-sector economic development approaches. Through lectures field trips discussion guest speakers and class exercises students will examine the history and evolution of community and economic development strategies in urban neighborhoods and communities and link these approaches to the field of sustainable development. The course focuses on the historic and contemporary debates and issues in sustainable development and delves into the challenges and opportunities of sustainable development in Los Angeles by drawing on case examples from other urban regions across the country. Through the course students will: 1) understand the historical theoretical and policy context of community development; 2) understand community and economic decline and development processes; 3) examine the key strategies of community development and related field of community economic development; 4) explore the growing intersection of community development and sustainable development including the greening of jobs buildings and urban design.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14481,2026,427,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305','<div class="desc"> In this course, students will learn how to document and analyze urban and environmental problems and public policies using quantitative data. Quantitative data provide a compelling means by which we can understand the magnitude of urban problems and who is impacted by these problems across demographic groups, neighborhoods, cities, and countries. Quantitative data can also help identify solutions, including public policies, and then evaluate the effectiveness of those solutions. Ultimately, our task is to develop quantitative reasoning skills in order to mobilize facts in the pursuit of a more just and equitable urban society. In the words of urban geographer Elvin Wyly: "Get mad. Get data. Get to work." Or, as Daniel Patrick Moynihan once said: "You can''t solve a problem until you first learn how to measure it." An important aspect of the course is how to make relevant and meaningful comparisons. How can we understand the size and significance of an urban problem such as low-wage work, or housing discrimination, racial profiling by police, or air pollution? We understand these issues best in relation to other outcomes: good jobs, nondiscriminatory housing and police practices, and clean air. We need to measure these outcomes in ways that we can compare them. Toward that goal, students will learn basic mathematical calculations and concepts such as percentages, rates, normalization, baselines, distributions, and probability. We will learn to read and interpret quantitative information presented in various formats, such as tables, graphs, geometric figures, or in text. Students will learn to assess numeric arguments and "answers" for reasonableness, as well as to recognize the limits of quantitative methods. Lastly, students will learn to evaluate how quantitative data is used, and sometimes misused, in the news media and public debates about social, economic, and environmental problems. Students will also engage basic questions of research: What data do we need to answer relevant policy questions? How can we devise a research project that would generate these data? Students will explore basic research methods using quantitative data, such as specifying a research question, research design, sampling, measurement, and validity. </div>',NULL,'UEP 305A ',NULL);
INSERT INTO course_descriptions VALUES(14482,2026,1566,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305a','<div class="desc"> Weekly laboratory for Urban Data Analysis where students will directly manipulate, analyze, and visualize real-world data related to urban problems and policy concerns, such as poverty, wages and low-wage work, housing affordability and quality, transportation equity, air quality, water safety, green space, food access, and crime and public safety. We will focus on identifying and communicating patterns of urban inequality. Students will become familiar with Excel and be introduced to Stata, a statistical software package. Students will learn to manage data, produce basic charts and graphs, generate descriptive statistics, and test hypotheses. </div>',NULL,'UEP 305',NULL);
INSERT INTO course_descriptions VALUES(14483,2026,792,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-306','<div class="desc"> <p>This community based learning course explores a range food systems issues from a food justice lens. The course examines how our food system has been restructured over the last century to benefit large-scale agriculture interests, creating a global food system that emphasizes convenience and fast-food solutions for consumers, often to the detriment of low-income people and communities of color. Through in-depth class discussions, on-site field trips, and in-class speakers, the class will delve into the environmental, economic, health, cultural, and social impacts of to how food is grown, processed, manufactured, distributed, sold, and consumed in the U.S. The community based learning component of this course will involve project work with UEPI’s food programs as well as other Los Angeles-based nonprofit partners and food policy experts. Please note, the first half of the semester will be based in the classroom (T/Th 1:30-2:55pm). During the second half of the semester, class will be held only one time per week (from 11:45am-2:55pm) to accommodate field trips.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14484,2026,428,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-310','<div class="desc"> <p>This seminar focuses the techniques of grassroots empowerment particularly in urban settings. This includes the following topics: developing leadership skills for citizen participation and problem solving using the media building coalitions choosing issues doing action-oriented research understanding the relations of power mobilizing constituencies developing a community oriented public policy agenda the history of community organizing in the U.S. and comparison between community development social work and direct action organizing approaches. <em>Must be taken simultaneously with UEP 311.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14485,2026,429,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-311','<div class="desc"> <p>This course provides opportunities for applying and learning through direct experience about the practice of community organization and leadership. Each student will work with a community-based organization engaged in influencing public policy for approximately 12-15 hours each week. Students will be supervised jointly by the faculty member and a staff person for the community organization. <em>Must be taken simultaneously with UEP 310.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14486,2026,3851,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-390','<div class="desc"> <p>This course examines the political ecology/economy of food, agriculture, and hunger in Los Angeles with an emphasis on Latin American-Caribbean relations. Students will explore these themes through readings, lectures, and a class-based research project in the city where students will gain practical experience in research design and apply techniques such as qualitative interviews and surveys, oral histories, ethnography, participant observation, and utilize archival material and visual and audio documentation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14487,2026,997,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-395','<div class="desc"> <p>Topics vary semester to semester. Students are encouraged to have completed UEP 101 or other relevant UEP courses prior to enrolling in this course.</p> <p style="margin-top: 10px;"><strong>Climate Policy and U.S. Politics</strong></p> <p>This course will explore the politics around climate change and climate policy, with a specific focus on the U.S. We will analyze the history of U.S. climate and energy policy, and explore how this policy response is shaped by public opinion and polarization, executive orders, the courts, federalism and state actions, and interest group political spending. We will also explore recent climate policies such as the Inflation Reduction Act in depth, and compare them to policy approaches in other countries. The framework of climate justice will be applied throughout the course, and we will analyze how climate justice can best be implemented through the U.S. political system. Students will conduct research on U.S. climate policy to inform policy memos and other writing assignments. </p> <p><strong></strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14488,2026,793,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-397','<div class="desc"> <p>Tutorial and Internship for junior or senior majors in Urban and Environmental Policy and other related disciplines under arrangement with faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14489,2026,430,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-410','<div class="desc"> <p>Intensive study of the making of national and local public policy in the U.S. including the political environment in which policy debates take place. Extensive use will be made of case studies on a variety of domestic and international issues. Students will participate in the development of a major research project related to their senior comprehensive project on an individual or group basis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14490,2026,794,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-411','<div class="desc"> <p>Seminar to organize and complete a senior project demonstrating competence in applied public policy. The form and format of each student''s project will vary. All students will make a presentation of their project and will critique each other''s project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14491,2026,4048,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-493','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 0">UEP 493 enrolls seniors who seek to continue their research from UEP 410 into a second semester as directed research. The Directed Research allows seniors to continue to build from their research proposal and analysis that was completed during the senior comprehensive seminar (UEP 410) during the Fall semester. In the Spring, they will have the option to carry out and apply the research methods described in UEP 410, conduct independent and applied research, write up their Results, Analysis, Discussion, and Conclusion of their project.</p></div> </div>','UEP 410 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14492,2026,4407,'https://oxy.smartcatalogiq.com/en/2025-2026/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14493,2027,1498,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/100/amst-101','<div class="desc"> <p>This course introduces the major topics and perspectives of the interdisciplinary field of American Studies. Students will explore the diversity of United States culture, critically, in: its official and unofficial histories, its self-representations in the arts, its complicated intersections of ideals and realities. The class is required for American Studies majors and minors, and recommended for anyone wanting to better understand the relations between culture and identity in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14494,2027,3919,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/100/amst-120','<div class="desc"> This course serves as an introduction to Asian American studies by surveying the cultural, economic, political, and social issues that shape the lived experiences and needs of contemporary Asian American communities in the US. We will examine the origins of Asian American identity -- who is included in the category, why the category was formed, and how definitions have evolved -- before reviewing key theories and frameworks that provide the critical vocabulary needed to describe, explain, and understand the diversity of Asian America. By applying these theories and frameworks to Asian American literature, pop culture, and other media, we will consider how the Asian American experience reveals the complexity of race relations in the US as well as broader histories of US imperialism, militarism, and settler colonialism. Topics may include interethnic relations, media representation, the model minority stereotype, and anti-Asian violence. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14495,2027,3225,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/100/amst-130','<div class="desc"> <p>This course provides an introduction to American Studies through a critical engagement with theories and cultural histories of “debility” and “capacity” in the U.S.’s mythos of “exceptionalism.” We will discover how various cultural iterations of “disability” have intersected with social constructions of race, gender, class, and sexuality in the U.S., from the colonial period to the present. In doing so, we will ask/trace/analyze how specific national renderings of disability/different-abledness came to be constituted as an affirmative identity category. We will examine how disability activism joined other 1960/70s freedom movements to yield recent academic critical-theory formations in the U.S., including Dis/ability Studies, DisCrit (Dis/ability Critical Race Studies), and Crip/Queer Critique.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14496,2027,4054,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/100/amst-165','<div class="desc"> <p>This course is an examination of feminist rhetorical history, theory, and criticism. We will study the way women (a gendered term we will complicate) have been represented through language, and how social, historical, and cultural circumstances have shaped the ways women speak, write, and communicate more broadly. We will examine how social relations, power, knowledge, and identities are constituted through rhetorical acts such as speeches, literature, film and media, and music. Through these materials, we will discern how gender abolitionists and activists advanced a vision of social change, acted to implement such change, and contributed to rhetorical history in the process. Throughout the course, we will interrogate and challenge the seeming erasure of women and "gender outlaws" from white patriarchal rhetorical history, or what bell hooks termed âwhite-supremacist capitalist patriarchy.â</p> <p>We examine feminist rhetorics focused on topics of abolition, rights, and reform movements from the U.S. 19th century to the present including:</p> <ul> <li> <p>Anti-slavery and emancipation</p> </li> <li> <p>Womenâs rights</p> </li> <li> <p>Indigenous and anti-colonial sovereignty</p> </li> <li> <p>Civil rights</p> </li> <li> <p>LGBTQ liberation</p> </li> <li> <p>Disability rights</p> </li> </ul> <p>At the end of the course, students will create a social justice project that will allow them to put their own âfemrhetâ into action and envision a more just world. This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14497,2027,4055,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/100/amst-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14498,2027,432,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/100/amst-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14499,2027,2731,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14500,2027,2670,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-202','<div class="desc"> <p></p><p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14501,2027,1433,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-215','<div class="desc"> <p>This course examines the history of sexuality in America from the early colonial era to the present. Along with theoretical readings, the course will consider primary and secondary sources addressing issues including: reproductive politics, socio-sexual control of Native populations, the rise of urban erotic subcultures, the sexual politics of slavery, American sexology, sex work, gender in private and public spheres, sex panics, feminism and gay liberation, and intersectional erotic cultural production.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14502,2027,2926,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-220','<div class="desc"> <p>This course introduces students to the theoretical and analytical frameworks necessary to critically understand representations of race, gender, and sexuality (among other topics in American culture) in contemporary American film and media. Using critical theory, historical analyses, and theories of analyzing film and media, we will explore central concepts in American studies such as race, gender, sexuality, class, family and nation, and private and public space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14503,2027,4056,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-232','<div class="desc"> <p>This course studies the twentieth century origins and myriad manifestation of the âNew Rightâ in U. S. politics and culture. Starting in the 1920s with the rise of the second Ku Klux Klan and Christian Fundamentalism and homing in on the New Rightâs various stages of development from the Cold War to the present, we will examine film, news media, television, critical theory, and historical analyses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14504,2027,3275,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-242','<div class="desc"> <p>This interdisciplinary course examines the migration of six million African Americans who left the rural South to move to cities in the North, Midwest and West in the first half of the twentieth century. Beginning with the “First Great Migration” of 1910-1930 and continuing through the “Second Great Migration” of the 1940s through the 1960s, we will explore the ways that this unprecedented demographic shift laid the groundwork for the civil rights movement, the quest for Black power, and the ongoing quest for social justice. Throughout the course, we will remain attentive to the way that Black migrants created and nurtured the new forms of music, art, and ways of being that ultimately transformed American culture. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of Black Americans and the culture and politics of the United States. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14505,2027,1638,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14506,2027,1679,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-260','<div class="desc"> <p></p><p>This course will explore how Latinos have creatively represented their individual and collective experience in the United States. Literature will be the primary creative medium we look at, but some supplemental attention may be given to film and music. To reflect the variety and complexity of the U.S. Latino experience we will look at representative work from the Chicano (Mexican American), Puerto Rican, Dominican, Cuban, and Salvadoran or Guatemalan communities.</p><p></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14507,2027,2819,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and theory as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations, power, knowledge, and identities are constituted through private and public rhetorical acts, mainly in the nineteenth-century to the present.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14508,2027,1680,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14509,2027,434,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14510,2027,806,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-280','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14511,2027,4,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-295','<div class="desc"> <p><strong>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</strong></p> <p><strong>Automation and the Civil Rights/Cybercultural Era</strong></p> <p>Like today, the 1960s was a period in which there was a great deal of discussion about automation. This was especially true for those involved in the Civil Rights and Black Power movements. Martin Luther King Jr., activists James and Grace Lee Boggs, and the Black Panthers all put automation at the center of their politics and calls for racial equality and a more just economy. In this course we will examine how debates about integration, Black Power, domestic colonialism, and the welfare state were connected to the politics of automation. We will also put those debates into dialogue with cybernetics, federal politics, the counterculture, and avant-garde art, among other topics. Ultimately, the course will ask students to understand not only the period itself and the focus on questions of rights and identity, but also how the often forgotten prominence of automation discourse during the Civil Rights Era prefigures, and helps us better understand, the politics of automation now. Core fulfilled: U.S. Diversity</p> <p><strong>Transpacific Empire and Anticolonial Solidarities</strong></p> <p>This course examines how U.S. imperialism, militarism, and racial capitalism have shaped our vision of the Pacific. We will explore the intersection of Indigenous sovereignty and environmental justice in the context of Hawai‘i, Guåhan, and other Pacific Islands that continue to negotiate the slow and structural violence of U.S. empire—colonized landscapes, polluted waters, and militarized airspace. By reading case studies alongside critical theory, we will situate the transpacific—a term that speaks to the conflict and exchange of Asian, Pacific Island, and American cultures across the region—as both an imperial fantasy of resource development and a contact zone for potential coalition-building. And, in following these currents, we will “unsettle” the union of Asian Americans and Pacific Islanders under the umbrella term “AAPI.” Core fulfilled: Regional Focus</p> <p><strong>Settler and Native Ecologies of Power in North America</strong></p> <p>This course examines how settler colonial dis/possession, resource extraction, and spatial domination have generated ecological catastrophes in North America while at the same time shaping discourses of environmental protection and preservation. Reading the work of historians, anthropologists, critical theorists, knowledge-keepers, and activists, and examining sites such as national parks and infrastructure projects from the 19th century to the present, we will learn how efforts to define, manage, regulate, and exploit natural resources occur simultaneously with assaults on Native nations'' sovereignty. We will explore how Indigenous peoples have cared for and defended their lands and human and nonhuman relatives despite continuous settler state violence and violations. We bring these discussions to current environmental issues in California, such as wildfire management and tribal nations'' salmon restoration efforts. Core fulfilled: U.S. Diversity</p> <p><strong>Latino/a Experience</strong></p> <p>This course will explore the history and experience of Latino/a immigrants in the United States, paying particular attention to how race, ethnicity, identity, politics, class, and gender influence the lives of Latino/a immigrants. We will also examine how they have influenced historical developments in different regions of the country, especially in terms of U.S. demographics. Core fulfilled: U.S. Diversity</p> <p><strong>African American Literature: Race/Gender/Sexuality </strong></p> <p>This course is designed as a survey of African American literature. We will examine a multitude of genres, including: oral forms (spirituals, ballads, work songs), poetry, fiction, drama, and essays by authors such as: Phillis Wheatley, David Walker, Sojourner Truth, Frederick Douglass, Booker T. Washington, Ida B. Wells, W.E.B. DuBois, Langston Hughes, Nella Larson, Zora Neale Hurston, Jean Toomer, Jessie R. Faucet, Claude McKay, Richard Wright, Ralph Ellison, James Baldwin, Ann Petry, and Gwendolyn Brooks. Beyond strictly a "greatest hits" or "major authors" course, this class will also consider the ways African American writers interrogate complex categories of personal identity, which requires an in-depth investigation into the intersections of race, gender, sexuality, and socioeconomic class. Through lectures, class discussions, and student presentations, we will highlight the critical impact of African American literature on American culture. Core fulfilled: U.S. Diversity</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14512,2027,4057,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/amst-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14513,2027,2,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/200/copy-of-amst-270','<div class="desc"> <p>This course analyzes the social experience and cultural heritage of Asian Americans through their writing, and places them in a broader comparative context of multi-racial/ethnic American society. We will examine the development of Asian American literature, its social implications and historical context, and the diversity of subject matter that the literary scene of Asian American communities has consisted of since the mid-19th century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14514,2027,3883,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-305','<div class="desc"> <p>This course examines forms of unfreedom from the American colonial era to the present and traces connections and divergences between early and contemporary abolitionism in the U.S. Through literature, film and media, and critical theory, we will investigate the ambition of racial, gender, and other forms of justice and abolition democracy. The main premise of this course is that abolition encompasses long and varied processes that continue to occur in the U.S. With this guiding premise, we consider abolition in the context of policing, of the prison, and of punishment more broadly.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14515,2027,1500,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-320','<div class="desc"> <p>This course will study the 20th century evolution of word-and-image texts from their origins in early superhero comics to their contemporary emergence as recognized literary works. The texts will be primarily from the United States, but some attention will be given to foreign works in translation. Frosh may not enroll in this course except by instructor permission.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14516,2027,3308,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-329','<div class="desc"> <p>Black queer thought are the knowledges, embodied and otherwise, that both enact critique of and imagine possibilities against the demands of heteronormativity, white supremacy, patriarchy and capitalism. In this course, we will engage with the multiple forms of text produced by those who may – or may uncomfortably – identify as Black and queer. By doing so, we will explore how the cultural producers in question complicate and elaborate upon the sometimes static and often U.S.-centered definitions we hold for “Black” and “queer,” challenging us to instead conceptualize these as dynamic and shifting positions rather than stable identity categories. Texts will be drawn from the works of James Baldwin, Ashon Crawley, Jackie Kay, Kara Keeling and others. This class thus situates students to join in on ongoing critical conversations within Black Studies, Queer of Color Critique, Performance Studies and American Studies. Assignments will include both informal and formal written components, and students will be asked to produce a final research paper. This class fulfills the second-stage writing requirement for the Black Studies major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14517,2027,3017,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-332','<div class="desc"> <p>Sigmund Freud''s intervention in personal sexual life often overshadows how psychoanalysis uniquely theorized violence in the context of two world wars. This course will consider how historical and contemporary violence in the U.S. might be informed by psychoanalytic concepts, including: aggressivity, group identification, neighbor relations, the death drive, and altruism. Readings include Freud’s work and texts by contemporary theorists grappling with the ongoing problems of war, racism, class conflict, and sexual violence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14518,2027,3295,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-333','<div class="desc"> <p>This course introduces students to literary questions of queerness, canonization, and nation, in the context of the United States'' 20th century discourses about homosexuality. Students will analyze the production of ideas about the nation through literature and examine the limits and capacities of the novel genre for cultural expressions of LGBTQ life in America. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14519,2027,2927,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-335','<div class="desc"> <p>This course examines the emergent field of queer of color critique. Combining woman of color feminism with queer theory, queer of color critique analyzes intersections of race, gender, sexuality, and class through interdisciplinary methodologies. This course will examine themes of settler colonialism, interracial love, gender performance, anti-blackness, orientalism, and bilingual resistance through critical theory, literature, film, and television</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14520,2027,3246,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-337','<div class="desc"> <p>The course takes an interdisciplinary approach to the last decade’s increasing attention to Los Angeles as a historical origin point of United States’ LGBTQ+ history. Students are encouraged to “queer” the very concept of the archive by considering how minority voices and experiences register themselves across time through both traditional archives and less formal communities of readership and historiography wrought through alternative archives like pulp novels, comics, films, and even gossip. The class will spend time with primary sources in the ONE National Gay and Lesbian Archives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14521,2027,2608,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-376','<div class="desc"> <p>This interdisciplinary seminar will explore the contentious history of the public memory and representation of slavery, the Old South, and emancipation in the United States. Drawing upon a range of sources – including fiction, film, advertisements, tourist sites, and public monuments – we will examine the various ways that Americans have sought to commemorate, critique, and capitalize on the history of the nation’s “peculiar institution” from the late-nineteenth century to the present day. Throughout the semester, we will interrogate the contested politics of these popular representations, and we will assess the ways that African American writers, filmmakers, preservationists, and artists have sought to challenge and reframe longstanding Jim Crow-era representations of slavery, replacing them with new narratives informed both by historiographical paradigm shifts and the politics of the ongoing black freedom struggle. </p> </div>','One HIST course, or one BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14522,2027,435,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-390','<div class="desc"> <p>This course engages students in the history, practice, and research methods in American Studies by focusing on the significance of place, identity, and rights.While we will focus on the territory known as the United States, our readings and research will trouble the security of that designation. By examining the origins of settler colonialism in the Americas, focusing upon national borders and internal boundaries, and exploring the United States'' global reach, we will study and develop different ways of understanding "America" as a product of civic rights that are extended and denied. Students will apply American Studies theoretical methods in a research project of their choosing, and majors will develop this work into their senior comprehensives project. Offered only in spring semester. Majors are encouraged to study abroad in the fall semester to align this requirement with their progress toward the major. </p> </div>','AMST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14523,2027,4058,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14524,2027,436,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/amst-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14525,2027,4059,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/300/copy-of-amst-393','<div class="desc"> <div><p>Directed Research allows students to conduct research either in a topic not offered (regularly) in the department curriculum, or to engage a specific topic in more depth than typically covered in department courses. Permission of instructor required. </p></div> </div>','AMST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14526,2027,437,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/400/amst-490','<div class="desc"> <p>This course is designed to assist students with the completion of research papers on topics that reflect selected areas of emphasis in American Studies. It will provide an opportunity for seniors to synthesize their area of specialization with an analysis of critical issues in the study of American culture and society. Offered only in fall semester (following AMST 390 in the spring). </p> </div>','AMST 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14527,2027,4060,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/400/amst-493','<div class="desc"> <p>This advanced directed research course is designed for American Studies majors who are completing an approved research project in their senior year (and after completion of the Second-Stage Writing requirement). Over the course of the semester, the student will work with a research adviser/mentor on multiple drafts and revision of a 25-page essay that meets the same criteria as a senior comprehensives essay. The seminar will culminate in a presentation of the research at the end of the semester. Instructor permission required.</p> </div>','Student must be a senior AMST major and have completed the AMST second-stage writing requirement. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14528,2027,4061,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/400/amst-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14529,2027,3973,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/400/amst-498','<div class="desc"> <p>Directed Research completion of an Honors Project in American Studies. Permission of instructor and department chair required, and will be provided only after: (1) receiving Distinction on the Senior Comprehensives, and (2) initial Honors Proposal approval.</p> </div>','Successful completion of AMST 490 with a grade of A- or higher. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14530,2027,438,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/amst-american-studies/400/amst-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14531,2027,5,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/100/arab-101','<div class="desc"> <p>Introduction to Modern Standard Arabic and pronunciation, alphabet, simple oral communication, reading simple prose, and other basic language skills. Instruction in the fundamentals of Arabic grammar. May not be taken for credit by those with more than one year of previous high school study (grades 10, 11, 12) in Arabic or one semester of college study in Arabic. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14532,2027,440,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/100/arab-102','<div class="desc"> <p>Continuation of ARAB 101.</p> </div>','ARAB 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14533,2027,1501,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/100/arab-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14534,2027,1682,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/100/arab-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of an Arabic feature film. Attendance is mandatory. Only four absences are allowed for this class, after which, credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on a Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14535,2027,4062,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/100/arab-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14536,2027,4063,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/100/arab-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14537,2027,6,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/200/arab-201','<div class="desc"> <p>This course focuses on the development of communicative skills via reading, speaking, listening, and writing activities, while grammatical points are drilled intensively. Students begin to read and discuss cultural and literary texts, as well as simple media materials.</p> </div>','ARAB 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14538,2027,888,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/200/arab-202','<div class="desc"> <p>Continuation of ARAB 201.</p> </div>','ARAB 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14539,2027,1145,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/200/arab-275','<div class="desc"> <p>A selection of literary works and films from the Arab world will be analyzed in the context of historical, cultural, social, and political developments from the last decades of the 20th century. The texts, in various genres - short story, novel, memoir, poetry - will highlight the heterogeneity and complexity of Arab countries, such as: Morocco, Tunisia, Egypt, Lebanon, Iraq, and Saudi Arabia. Some of the main themes that we will cover include: tradition versus religion, challenges of modernity, gender relations, social (im)mobility, and generational gap. The course will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14540,2027,4013,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/200/arab-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14541,2027,4064,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/200/arab-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14542,2027,807,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/300/arab-301','<div class="desc"> An advanced Arabic course intended for students who have taken Intermediate II. It introduces the language of the newspapers, magazines, and internet news sites. Students will gain access to different sources from the Arab world. </div>','ARAB 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14543,2027,1043,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/300/arab-302','<div class="desc"> <p>This is a continuation of Arabic in the Media I.</p> </div>','ARAB 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14544,2027,4065,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/300/arab-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14545,2027,4066,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/300/arab-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14546,2027,441,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/300/arab-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14547,2027,4067,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arab-arabic/400/arab-497','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14548,2027,1640,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/100/arth-150','<div class="desc"> This introductory course examines how cities, suburbs, and metropolitan areas are designed and developed. We will explore historical episodes and actors that have influenced urban planning so that we may then consider the ways in which contemporary architects, developers, and institutions approach urban concerns related to land development, the environment, housing, and transportation. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14549,2027,7,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/100/arth-160','<div class="desc"> <p>This course introduces East Asian art from ancient times to the present. Although the framework of the course is loosely chronological, each week will focus on in-depth analysis of a different type of object that addresses a particular problem or concept. We will explore topics such as metaphorical uses of amorphous ink in calligraphy and painting, the deconstruction of artistic hierarchies in the tea ceremony, and gender and the politics of contemporary performance art. In addition to developing the foundational skills of close looking, critical thinking, and self-reflective writing, students will ultimately gain an understanding of the diversity, complexity, and conceptual excitement of East Asian art. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14550,2027,8,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/100/arth-170','<div class="desc"> <p>What makes art “European”? This fundamental question accompanies our survey of the different artistic traditions that emerged around the Mediterranean for more than 40,000 years of history, from prehistoric times through antiquity to the end of the medieval era. Rather than looking at art as the product of different monolithic “civilizations,” progressing through time in isolation from another, we will consider how a diversity of artistic cultures emerged through constant exchange and borrowing from one another. Readings, lectures, assignments and discussion will encompass artworks from the realm of painting, sculpture, architecture and material culture from a “Europe” with constantly fluid and shifting borders. The course will develop skills of visual analysis in style, iconography and technique. Issues of gender, race, colonization and trade in the art of the ancient and medieval eras will also be addressed. In addition, we will explore how the art of the past has constantly been reimagined to fulfill more recent artistic and political ideologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14551,2027,9,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/100/arth-180','<div class="desc"> <p>The term “Modernism” has traditionally referred to certain developments in so-called Western art from roughly the late 19th century to the 1960s. Through readings, lectures, discussions and writing assignments, this course will pose the question of whether the concept of Modernism can be used to understand cultural practices from other parts of the world as well. Or does the consideration of art from all six inhabited continents over this period render the concept of Modernism inoperable? What commonalities and differences can we discern between art made in vastly different contexts in response to the experiences of colonialism, industrialization, urbanization, nationalism, and revolution? What sorts of continuities, tensions, or ruptures have arisen between indigenous traditions and metropolitan practices? Finally, how has a globalized contemporary art world arisen out of numerous local ones? To answer these questions, and others, students will be introduced to the fundamental art historical practices of visual description and visual analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14552,2027,4018,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/100/arth-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14553,2027,4068,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/100/arth-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14554,2027,2860,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-200','<div class="desc"> <p>This course provides opportunities for students to engage in community-based work with arts organizations. Each student will work with a community-based partner or artist for approximately 6-7 hours each week. This in-the-field experience will be paired with reflective exercises and relevant readings, and will be facilitated by a faculty member in the department.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14555,2027,3242,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-201','<div class="desc"> <p>This course will enable students to learn the methods of visual and cultural analysis, critical practices of looking, varied modes of making, and the historical and theoretical frameworks that form the foundation for deeper study of visual arts, architecture, and material culture. Guest lectures from faculty in the studio art and art history program will enhance the interdisciplinary and transcultural nature of the course, and student work will include opportunities to conduct research, write about, and create visual images and objects as a means putting these foundational concepts into practice. Classes will focus on the analysis of specific objects (paintings, photographs, prints, sculptures, buildings, and other objects of visual interest) and also the materials and techniques used to make those images and objects. By the end of this course, students will be equipped with the methods of analysis, research, and interpretation essential to looking at and making visual art in the twenty-first century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14556,2027,3247,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-240','<div class="desc"> <p>Trade, economic migration, and violent displacement caused an unprecedented number of people and things to travel across the early modern globe. This seminar explores the portable objects that were created within, and impacted by, the global mercantilismes and colonialism’s of the Spanish and Portuguese empires. We will follow a series of moving items that defy the traditional categories of singular authors or cultures. Their travels span distant points in the colonial maritime world, such as Goa, Manila, Mexico City, Nagasaki, Antwerp, Lisbon, and Potosi. Each class will center around 1-2 select “Objects in Focus.” Ranging from the high-end to the everyday, these works will include ivories, feather mosaics, silver work, lacquer, ceramics, paintings, prints, textiles, and more. They will intersect with a series of discussions on appropriation, reuse, display intent, theft, copying, gifting, erasure, fashion, labor and race. The paths of things past offer a more nuanced view of our own current systems of globalized capitalism and its reflection in artistic production and display to this day.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14557,2027,4069,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-247','<div class="desc"> <p>Death: the final frontier. Concern for the universal fact of death—and what might lie beyond it— has inspired art all over the world since the dawn of recorded time. In premodern societies, tombs, sanctuaries, and monuments, created a tangible and ever-changing link between this life and the next. This course proposes an in-depth exploration of the topic of death during a period of significant cultural change: the medieval and early modern periods (1000-1800). Taking up a wide geographical lens, this class will be organized thematically to engage with topics like relics, the macabre, visions of the last judgment, and even early scientific anatomy. We will also explore how variegated cultural practices related to death interacted during a period of European global expansion and colonization. Historical inquiries will also open up to present-day debates around displaying burial arts and human remains in today’s museums and relating to European imperialist practices of looting, theft, and displacement. Readings, discussions, lectures, assignments, and visits will investigate objects, sites, and practices to develop visual and material literacy and question the complex relationships between art and death in the premodern world. Students will come away with a sense of just how much great eternal can actually change over time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14558,2027,1502,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-259','<div class="desc"> <p>A thematic course on the history, theory, and practice of Modern Architecture in Europe and the United States, from the 1780''s to the later 20th century. Themes we''ll explore include the following: architectural theory and design as social planning, competing notions of public and private space, modernist architectural theory and urban development, rural and urban ideologies in American architecture, the changing image of the architect in the 19th and 20th centuries, architecture and urbanism in Southern California. Coursework will include a required half-day field trip.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14559,2027,2582,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-268','<div class="desc"> <p>This course examines the Japanese woodblock print from its emergence in the mid-seventeenth century to the modern era. We will investigate topics such as technological innovations, changing habits of looking, censorship and resistance in the creation of popular culture, the role of prints as a medium of reportage and propaganda, Japonisme and the construction of Japanese art, and global exchanges of materials and ideas. By tracing the historical development of Japanese prints, we will examine how woodblock prints were reconceptualized from a popular medium of visual culture to a quintessential embodiment of Japanese aesthetic tradition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14560,2027,2321,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-272','<div class="desc"> <p>An investigation of the art and architecture of ancient Greece and Rome from the Helladic era (c. 1500 BCE) to the appearance of Christianity in late Roman antiquity. Sculpture, metalwork, mural painting, vase painting, and architecture will be considered, with particular interest in how these forms are reflective of the fundamental political, spiritual, and philosophical developments during this era - as well as how these artistic forms serve as the foundational elements for European Art History.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14561,2027,3210,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-273','<div class="desc"> <p>Each week, the class will travel the world to discover artists from different parts of the Spanish Empire, moving across the Iberian peninsula to Flanders, Southern Italy, the Philippines, Mexico, Peru and many more sites. This course explores the arts of the Spanish Monarchy from the plurality of perspectives and voices that composed this global empire ruled by the Habsburg dynasty (1516-1700). This will mainly concentrate on the arts of painting and sculpture, two crucial cultural traditions of this period. We will explore what “painting” and “sculpture” meant in different parts of the Empire, and how it also could integrate a broad range of decorative materials like feathers, gold, shell and ivory. Themes like religious visions, portraits, and still life will all receive attention. Famous artists and objects like Velazquez’ <em>Las Meninas </em>will come into conversation with the lesser-known and even anonymous makers of indigenous, creole and African descent, which all contributed to the history of sculpture and painting under the Spanish monarchy. Representations of power and artistic identity will intersect with issues of race, gender and class that structured societies under Spanish colonial and monarchic hegemony. Ultimately, students will come away with a much broader understanding of what well-known artistic traditions like painting and sculpture can mean in a globalizing and more culturally-heterogeneous world. Visits to nearby museums will also be included.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14562,2027,1044,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-278','<div class="desc"> <p>An exploration of art, architecture, and visual culture created within the context of Muslim-majority or Muslim-ruled societies within Western Asia, North Africa, and Europe from the 7th to the 21st centuries. Covers sacred and secular architecture and architectural decoration, sculpture, painting, manuscripts, textiles, and metalwork, including objects in Los Angeles area collections. The course also considers theoretical framings of the field, such as what is “Islamic” about Islamic art. We will also consider the circulation of Islamic art globally and the emergence of modern Islamic art, as well as the visual cultures of protest in contemporary Muslim-majority countries. Readings will include primary sources, exhibition catalogs, and scholarly articles; visits to museums and a mosque is anticipated. By the end of the course, students will be able to demonstrate knowledge of the diversity of Muslim arts historically and geographically. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14563,2027,998,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-285','<div class="desc"> <p>This course will explore artistic practices in the U.S., North America, and Europe, during the long 19th century, from roughly 1789 to 1900. Lectures, discussions, and readings are designed to provide a thematically-driven, chronological overview of the period. Yet, the course will not be a traditional "survey," rather, it will focus on some of the key changes in ideas about artistic culture; art practice; and practices of regional, national, and transnational identity formation as expressed in visual art. This course will explore the role of art in social and political revolution, as well as its formative status as an engine of cultural imperialism in the 19th century, and, in addition will explore some of the more traditional approaches to studying the status of art, such as the role of the artist and the transformation of the art "market" in the wake of the industrial revolution. Key debates within the field of Art History will be explored, as well. Museum visits required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14564,2027,445,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-287','<div class="desc"> <p>Photographs today are ubiquitous. Yet they are incredibly diverse in their functions, circulation, meaning, and relationship to institutions, personal and collective identities, scientific knowledge, and artistic cultural practices. Photography has the capacity to shape the way we think about ourselves, our communities, our national cultures, and our engagements with a transcultural world. This course is designed to explore the technological, cultural, economic and ideological power that photographs have to shape our collective understanding of our world. This course will also introduce students to key tools necessary for developing visual literacy in our image-saturated culture. Together, we will learn about different photographic genres - exploration and travel photography, portraiture and family photographs, medical and legal documentation, fine art prints and mass cultural forms - and we will explore photography''s power to represent personal and collective identities, social and political ideologies, and history itself. Photography, after all, was created in the early 19th century amid rampant Euro-American colonialism and imperialism. The course will explore photography by, for, and of makers and collectives working in and across local, indigenous, and global cultures in North and Central America, Western Asia and Asian-Pacific, Africa and the African Diaspora. Readings will include primary source materials, theories of photographic meaning, and research-based analyses of particular photographic practices within local and global contexts. Students will be asked to grasp both the medium''s technological and rhetorical functions, but also to develop their own critical perspective on photography''s shifting relations to global visual culture. Coursework will include a hands-on photography project and a museum or gallery visit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14565,2027,11,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-289','<div class="desc"> <p>This course will focus on modernist artistic practices in the United States and Europe between 1900 and 1950. We''ll look carefully at a wide range of practices, including painting, sculpture, photography, film and architecture. Coursework will include readings, discussions, and lectures about modernism, the rise of the avant-garde, and the role of exhibitions in the transformation of modern art. We will engage issues of gender, sexuality, race, class, and ethnicity, and the scholarship we read will encompass diverse approaches to analyzing and interpreting modern art.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14566,2027,889,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-290','<div class="desc"> <p>This course will explore the diverse forms of visual culture - painting, sculpture, photography, installation, performance, and interdisciplinary arts created in the years after 1950. We will investigate shifting ideas about artistic identity, the status and function of art in the wake of the social, cultural and economic changes in post-industrial society of the 1960s and 1970s. By scrutinizing art created across geographic contexts, we will examine the centrality of migration and immigration in U.S. modern and contemporary movements. Broad cultural and social movements advocating for civil rights, feminism, environmentalism, global capital and migration in the later 20th century will form the cultural backdrop of our work. We will also consider how critical theory has impacted artistic cultures and the burgeoning networks of artistic and cultural exchange. Our work will engage directly with changing ideas about race, ethnicity, gender, sexuality, and cultural identity as they impact artistic identity and arts institutions. At least one field trip to a gallery, museum, or artist studio will be required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14567,2027,3248,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-292','<div class="desc"> <p>What is a "site"? As the world has become more urbanized and globally interconnected, our daily lives increasingly digitized and virtual, and social ties looser and less place-bound, our conception of a “site” as a specific physical location has been complicated. This course examines the various ways artists have examined the meaning of a “site” and an artwork’s relationship to it. Emerging from developments within sculpture in American art of the 1960s, the notion of “site-specific art” has been adapted in various ways by artists around the world over the past several decades. We will focus on such works and theories that address issues including colonialism, gentrification, community, public art, monuments, digital media, globalization, environmentalism, surveillance, and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14568,2027,1319,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-295','<div class="desc"> <p><strong>Art &amp; Money</strong></p> <p>Art’s relationship to money has long been fraught. On the one hand, art supposedly places individual expression above the profit motive, yet on the other hand, artworks circulate as expensive luxury commodities. How can artworks be unique, non-fungible cultural objects yet also vehicles for collateralized debt, money laundering, tax evasion, speculative investment, and real estate development? Has art simply become money? Can money be art? This course examines these, and other contradictions, about the long and complicated entanglement of art and money in modernity with particular attention on the period since the 1960s. We will address theories of value, trace the history of the art market, interrogate the politics of arts funding, explore the so-called financialization of art, look at ways artists have represented, exploited, or challenged the connections between art and money, and consider art’s role within the broader economic system. This topic is cross listed with ECON 216.</p> <p><strong>Making Black Ecologies</strong></p> <p>In this seminar, students will draw directly from The Flesh of the Forest exhibition, which will be on view at OXY ARTS in the fall of 2025, to think about the place of the emergent field of Black ecologies within art history and museum studies. Though the study of the Oxy Arts exhibition itself and in conversation with the artists featured and other artists whose work dovetails with the curatorial vision for The Flesh of the Forest, students will consider how art and its histories connect with issues of modernism, Surrealism, the environment, climate catastrophe, land sovereignty, and other related issues using a Black Studies lens. As a culminating exercise, students will engage with the practice of exhibition making themselves as a way to transmute abstract concepts and theory into material outcomes that illuminate their everyday lives and world.</p> <p><strong>Surrealism and Women</strong></p> <p>This course will explore the artistic and literary movement of Surrealism that emerged in Europe during the 1920s and 1930s. Born in the years just after World War I, Surrealism aimed to destroy conventional modes of artistic and literary representation through what they called a Surrealist “revolution.” The Surrealists read the works of Freud, Marx, Sade and Lautréamont; they aimed to destroy bourgeois cultural traditions including the family, the state, and organized religion. And although many of the Surrealists were men, women artists and writers were deeply connected to Surrealism. In this course, we will focus on the work of these women artists and the specific ways they created work that explored notions of female power, desire, embodiment, and political activism. Although we will primarily focus on artists of the 1930s-1970s, we will explore how contemporary artists continue to mine Surrealist artistic strategies to disrupt dominant cultural, social and artistic paradigms to challenge ideas about how “women” might be represented.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14569,2027,3829,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-296','<div class="desc"> <p><strong>Topic for Fall 2024: Subversive Art and Media.</strong></p> <p>An 8-unit course on the ways visual artists challenge and critique dominant systems of power, and catalyze movements of social change . We will explore how photography, film, visual and media arts play powerful roles in shaping liberatory and empowering narratives in the present, as well as reimagining, reconstructing, and reclaiming histories of the past. Through readings, discussions, writing, and art practice, students will center questions of power, belonging, exclusion, visibility and invisibility among others. Students will also engage in collaborative projects and studio visits with artists, filmmakers, curators, historians, and media makers in LA/the US, South/Southeast Asia, Mexico, and Europe. Finally, students will create a final visual media social justice project. By the end of the immersive, students will have gained critical skills in discussion, research, and writing alongside creative skills in visual media making. This course is part of the Humanities for Just Communities curriculum.</p> <p>Class will meet 4-5 hours/week, depending on the class schedule as it is both an art history course and a visual art and media practice course which includes hands on, project-based work</p> </div>',NULL,'First-Year Seminar: FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(14570,2027,4070,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14571,2027,3014,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/200/arth-298','<div class="desc"> <p>This course actively engages students in the diverse array of programming - exhibitions, lectures, studio visits, student and community-based projects - that are fundamental to the history, theory and practice of the visual arts on campus at Oxy Arts, and in the city of Los Angeles. Students will meet regularly with the course faculty mentor to discuss related readings and their experiences of these arts activities; students will also have the opportunity to respond creatively to programming and events through writing, image-making, and collaborative projects. May be repeated once for credit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14572,2027,3249,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-330','<div class="desc"> <p>Some say that the word “Baroque” derives from a Portuguese term denoting a misshapen pearl: a treasure that is asymmetrical, beautiful, and enchantingly strange. The Baroque style that prevailed in the European empires during the seventeenth and eighteenth centuries fostered an aesthetic of irregular forms, highly emotional and dramatic effects, and stark contrasts of light and dark. The troubled painter Caravaggio, the Mexican nun-poetess and mystic Sor Juana Ines de la Cruz, and the German Jesuit polymath Athananasius Kircher all encapsulate this crucial cultural moment. This course will examine the arts of the Baroque period from a global perspective: each week we will travel to different locations around the world to examine its shifting contours. From Mexico City to Rome, we will explore the different iterations of this distinctive style via painting, sculpture, architecture, poetry, fashion, music, optical instruments, and even stage design. These histories will lead us to examine the Baroque’s continued impact on twentieth and twenty-first century scholars, artists and filmmakers.</p> </div>','Any 100- or 200- level art history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14573,2027,4428,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-345','<div class="desc"> <p dir="ltr">Since its invention, photography has functioned as a tool for liberation movements and the theories surrounding them. As many individuals and communities have sought to reclaim active agency over their lives and narratives, a photograph can be understood as an act of resistance. The multivalent nature of photography and liberation is often employed to reject stereotypes, create archives documenting marginalized communities, and visualize unbelievable realities. As much as photography can reinforce subjugation, it can inspire and spark liberatory action. Defining and exploring âliberationâ in distinctive contexts permits us to ask: Can we see liberation? Is it solely physical? Is it psychic? And what are the limitations of photography? More than simply examining images from liberation movements, this class will explore how photography has been exploited in the name of self-actualization, autonomy, secrecy, and more. In the seminar, we will focus on the United Statesâ longstanding relationship between visual culture and political organizing. By examining a range of subjects, geographies, and periods, we will create a genealogical view of how photography has manifested in the pursuit of liberation. </p> </div>','200-level ARTH, CTSJ, or BLST course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14574,2027,2671,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-360','<div class="desc"> <p>This course explores the relationship between art and women in East Asia from ancient times to the present. We will study the various ways in which women have been engaging with art—as producers, as patrons, and as objects or subjects of the gaze. At the same time, we will examine how women and gender have been conceived and contested in East Asia. Over the course of the semester, we will investigate topics such as women artists and patrons; Buddhist conceptions of the feminine and women’s devotional practices; performing “women” in theater; shifting ideals of beauty and the alteration of women’s bodies; and the representation of gender in contemporary popular culture. Ultimately, students will develop critical tools for examining how women have been represented in visual culture and how they have exerted their own artistic agency in East Asia. </p> </div>','Any Art History course, East Asian Studies course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14575,2027,2518,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-365','<div class="desc"> <p>This course examines the role of gender in the production and reception of visual images in Japan from the twelfth through the twenty-first centuries. Closely engaging with a variety of images, literary texts, and performances, we will investigate topics such as Buddhist conceptions of the feminine, same-sex sexuality and gender reversals in the medieval imagination, beauty prints and the politics of the gaze, changing conceptions of art and women in modern Japan, masquerades of masculinity, and the place of male-male sexuality in contemporary girl culture. Ultimately, this course will provide students with an understanding of how art and gender have been conceptualized in Japan, as well as tools to think beyond that understanding.</p> </div>','Any art history course, Japanese studies course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14576,2027,3211,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-375','<div class="desc"> <p class="MsoNormal" style="margin-left:0in; margin-right:0in">Pilgrimage is the journey to a revered site, often accomplished for spiritual purposes. Whether it is the Catholic Way of Saint James in Santiago de Compostela in Spain to the millions of Muslims who travel each year to Mecca for the Hajj, pilgrimage speaks to widespread narratives of human movement, monumentality, and memory.</p> <p>Encompassing the medieval and early modern periods, this class will explore the art and architecture of different religious shrines throughout the Global Mediterranean world (including the Americas). We will examine pilgrimage sites as the confluences of multi-media art forms, melding architectural space and fine arts with the cultural expression of everyday people: this includes graffiti, votive arts, and other folkloric practices. Students will explore themes like migration, displacement, colonialism, and connections with contemporary parallels.</p> </div>','ARTH 170 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14577,2027,4071,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-380','<div class="desc"> <p>Art has long had a contradictory relationship to work. On the one hand, the artist is the consummate worker – passionately investing their full self in what they create. On the other hand, the artist is the supreme non-worker, the dreamer who refuses to compromise their vision for the sake of efficiency, profit, utility, or other external pressures. Since the 1960s this contradiction has become internalized into the very themes, processes, forms, and value of art itself. While the definition of an artwork has expanded far beyond traditional media like paintings and sculptures, the definition of work has likewise expanded to encompass a bewildering array of activities, capacities, and sites. This course will examine the intersections between art and work in different parts of the world since the 1960s and address questions such as: how have artists intentionally blurred the distinction between art and labor? How have processes such as automation and globalization impacted artistic production across local, regional and national boundaries? How have artists made visible the changing class, racial, and gender relations of work? What new forms of power or resistance have the increasing overlaps between art and work enabled? Close discussion of assigned readings and the writing of a research paper will form the basis of the course.</p> <p>Students will meet 3 hours / week with the faculty member, plus conduct research and writing and work outside the course for at least 12 hours of work.</p> </div>','ARTH 290 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14578,2027,14,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-390','<div class="desc"> <p>A research-intensive course on a topic within the history of art; coursework will include the process of researching and writing a scholarly essay and a focus on the methodologies of art historical scholarship. Required for Art History majors to fulfill the Second-Stage Writing Proficiency requirement.</p><p><br/></p><p style="margin-left: 0; margin-right: 0"><strong>Art and Environment in East Asia</strong></p><p style="margin-left: 0; margin-right: 0"><br/></p><p style="margin-left: 0; margin-right: 0">This course explores relationships between art and environment in East Asia from ancient times to the present. We will cultivate habits of deep questioning and critical thinking by engaging with multiple disciplines, including art history, history, philosophy, literature, and environmental studies. We will investigate topics such as reuse and recycling in Buddhist art; sustainable building and dwelling in early modern farmhouses; practices of ecological sensibility in performance art; and the pursuit of ecophilosophy in anime and manga. Ultimately, students will produce a research paper on a topic of their choice that engages with some of the methods, theories, and approaches explored in the course. Additional Core Requirement Met: Regional Focus, Pre-1800.</p><p><br/></p><p><strong>The Sovereign Image: Art &amp; Authority from Antiquity to Present</strong></p><p><br/></p><p>In an increasingly authoritarian age, rethinking the dynamics of art and power has never been more urgent. This seminar explores how sovereign power across time and place is often expressed through visual and material forms. From the monuments of early Mesopotamian city-states and the royal garments of Incan rulers to the portraits of European absolutist monarchs and the digital technologies of modern corporations and governments, we will examine how diverse media construct power relations and assert dominion over territories, temporalities, and bodiesâintersecting with issues of gender, race, class, and sexuality.</p><p><br/></p><p>Conversely, we will investigate how different groups have co-opted and subverted these artistic forms in their struggles for self-determination. Drawing on both traditional and contemporary theories from art history and beyond, this seminar challenges simplistic binaries of authority, offering a nuanced exploration of power systems that are coercive, concealed, and paradoxical.</p><p><br/></p><p><strong>Thinking about Art</strong></p><p><br/></p><p>How do we study a work of art? What kinds of approaches have art historians taken when interpreting artworks? How can we make use of different theories and methods? We will seek to answer these questions as we read groundbreaking texts from the history of art history and visual culture. We will investigate approaches including formalism, social history, feminism, queer studies, critical race theory, and network theory. We will consider possible ways of applying these conceptual frameworks to interpreting media ranging from painting and sculpture to film and performance. Ultimately, students will produce a research paper on a topic of their choice that engages with some of the methods, theories, and approaches explored in the course.</p><p><br/></p><p><strong>Approaches to Art History and Visual Culture</strong></p><p><br/></p><p>How do we study a work of art? What kinds of approaches have art historians taken when interpreting artworks? How can we make use of different theories and methods? We will seek to answer these questions as we read groundbreaking texts from the history of art history and cultural studies and consider possible ways of applying their conceptual frameworks to interpreting media ranging from painting and sculpture to film and performance. We will investigate approaches including formalism, social history, thing theory, feminism, and network theory. Ultimately, students will produce a research paper on a topic of their choice that engages with some of the methods, theories, and approaches discussed in the course.</p><p><br/></p><p><strong>Performance, Embodiment and the Dematerialization of Contemporary Art</strong></p><p><br/></p><p>When many people think of âArtâ they envision a painting, a sculpture, a photograph, a lithograph or woodcut, or even an artistâs handmade book. Yet in the later years of the 20th century, artists drew on the disruptive works of the historical avant-gardes like Dada and Surrealism, as well as new ideas about the artistâs place in the world, to create work that looked and behaved very differently than traditional media. In the years after 1960, artists questioned the definition of art (is it a thing or is it an action or an event?). In turn, artists grew invested in making work that disrupted the more traditionally passive relationship between viewer and work; instead, the spatial, temporal and cultural contexts of art works became part of the work itself. Coupled with the desire by many artists to displace art from the traditional confines of the commercial gallery system, as well as to call into question the realities of individual and collective embodiment and identities, the effect of these new approaches was to expand the definitions of art to include performance, body art, installation, and institutional critique. Thus, artists transformed, and often dematerialized the âwork of artâ in favor of an art that could provoke action, communication, collaboration, and cultural critique. This seminar will enable us to explore these new modes of artistic practice in North America and Europe through provocative art historical and theoretical readings; student research projects; and activities and exhibitions at Oxy Arts and across Los Angeles.</p><p><br/></p><p><strong>Building the âAmerican Pacificâ</strong></p><p><br/></p><p>This course examines modern and contemporary architecture of the âAmerican Pacific.â Students will investigate the historical, social, cultural, political, climactic, and technological factors that have influenced the development of architecture in Hawaiâi, American SÄmoa, and Guam. Theoretical examinations about U.S. empire, race, and sovereignty allow us to challenge the very notion of an âAmerican Pacificâ and frame our study of architecture as a complex interplay of evolving beliefs and meanings. An examination of Pacific Island spaces/places and their relationship to artistic endeavors by artists and architects reveal the ways in which indigenous and foreign identities influence the built environment. Students will engage with interdisciplinary and intersectional scholarship as we consider the architectural legacy of American expansion in the Pacific. Additional Core Requirement Met: Regional Focus.</p><p><br/></p><p><strong>Colonial Urbanism</strong></p><p><br/></p><p>In this course, we will examine the spatial legacy of colonial cities. The focus is on colonial urban spaces and architectural projects that were manifestations of the political, economic, and social relationships between the colonizers and the colonized. In relation, the role of imperialism - as it transpired in both the colonies and colonizing societies of Europe and the United States - will reveal the ways in which the imperial imagination was visible in physical form. Through a range of case studies, including sites in former European and American colonies of Asia and the Pacific, as well as former imperial centers, such as London and Washington D.C., students will develop a theoretical toolkit for the critical study of urban colonial environments.</p><p><br/></p><p><strong>Gender and Sexuality in 20th Century Art</strong></p><p><br/></p><p>This seminar will explore the how issues of gender and sexuality have shaped the practices of visual artists in the US and Europe in the 20th century. We will investigate how artists have engaged directly with these issues in their art, and we will also consider how the field of Art History itself has been impacted by practices and stereotypes about gender and sexuality. Additional Core Requirement Met: Global Connections.</p> </div>','Any 100- or 200-level Art History course, or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14579,2027,1202,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-391','<div class="desc"> <p>A seminar focusing on a topic in the history of art taught by a practicing curator at a Los Angeles cultural institution. Course topic(s) change annually and will include off-campus hands-on work within the context of curatorial and exhibition practices. Course may be repeated for credit with a different topic.<br/> <br/> <strong>Curating Trans History: Archives, Art, and Politics (4 units) </strong><br/> This course explores the erased or undocumented cultural and artistic practices of transgender and gender-diverse people. Paired with “Hold Each Other’s Hands”, an Oxy Arts exhibition on trans mutuality and mutual aid curated by the course instructor, this course will offer opportunities for students to interact with the exhibition materials, featured artists, programming, and to create oral histories related to the exhibit’s themes. This theory-and-praxis-based course investigates issues and strategies related to curating and representing a history that has been under-preserved and misrepresented by institutions. We will consider curation as a reparative practice to remediate the violence of exclusion and omission and to build the foundation toward collective futures. Examining historical documentation and archival modalities from institutional collections to grassroots archives and oral history projects, and contemporary media and art practices, we will discuss how politics shape historical production and explore strategies for safeguarding histories and storytelling in an era under legislative attack on trans lives. </p> <p>Together we will explore trans history with the following guiding questions: Where can we locate often unsearchable documents and cultural production related to trans and gender-diverse people? How do we make sense of the violence of the archive such as archival omissions or repressive police records? What conceptual and storytelling framing can we use to understand what we know, and speculate what we could not know? What reparative strategies can we employ to fabulate memories for the future?<br/> <br/> <strong>Making a Road Concert: a Public Art Happening in Los Angeles (4 units)</strong><br/> This course gives students the opportunity to learn experientially by working directly with an artist-curator on a large-scale public art event. Stephen van Dyck founded and curates the LA Road Concerts, in which over 300 artists have installed or performed multidisciplinary works in unused public spaces along one road for just one day. Students will work directly with the curator to conceptualize the project, review artist submissions, meet with local organizations, promote and produce the event, and assist 20+ artists with picking sites and installing their work along York Boulevard. How can our public spaces serve as a forum or square for artists to skirt around the limits of the institutionalized art world and to democratize art? How has the decentralized nature of Los Angeles encouraged artists to rethink venue, audience, and public space? The hands-on component of the class will be matched with readings and discussions as we look at works by Asco, Allan Kaprow, Senga Nengudi, Fallen Fruit, Machine Project, Fritz Haeg, the Woman''s Building, and the IKEA Residency to answer these questions and explore themes of site-specificity, the artist as curator, the guerrilla happening, and more.<br/> <br/> <strong>Contemporary Art Museums: Learning, Engagement, Artists, Community (4 units)</strong><br/> What is the role of the art museum in the 21st century? How does it sustain its relevance in an increasingly complex world of information and stimuli? This class provides theoretical insights and practical knowledge about public programming, special projects with artists, and informal learning practices in contemporary art museums on local, national, and international levels. The course will be taught by Asuka Hisa, Director of Learning and Engagement at the Institute of Contemporary Art, Los Angeles (ICA LA), and currently a 2023-2024 Smithsonian Fellow in Museum Practice. The course begins with an overview of the museum field—examining interpretive methods of teaching with artworks and in partnership with artists—and continues with an analysis of the evolving nature of the field and its growing inclusion of multi-disciplinary curatorial approaches. The class explores how greater societal contexts influence and inform programming work through an investigation of case studies, experimental and conceptual projects, and expansions in museum theory. Discussions center on the social practice role of the contemporary art museum today. The class provides readings, hands-on exercises, and assignments to develop skills associated with inclusive project design.<br/> <br/> <strong>Introduction to Curatorial Practice (4 units)</strong><br/> This seminar explores the conceptual and practical aspects of making exhibitions. Students will investigate curatorial strategies through readings, class discussions, and trips to local galleries and museums. Seminar discussions will emphasize the ethics and social impact of curators’ work. These concerns include accessibility, repatriation, the care and display of indigenous objects, exhibiting Blackness, power and labor dynamics.<br/> <br/> This course uses exhibitions as case studies and examines the strategies of curators including David Driskell, Okwui Enwezor, Thelma Golden, Wanda Nanibush, and Marcia Tucker. It also investigates the structure and influence of international art fairs like Documenta, Dak’Art, and the Whitney Biennial. Students will also have an opportunity to respond to the professor’s current curatorial projects.<br/> <br/> Students will conceive an exhibition for their final project. They will compile a list of artworks, write a project description, and write select exhibition texts. By the end of the semester, students will have critically examined a variety of curatorial strategies and assessed their intended and unintended outcomes. Students will gain knowledge about the practice of conceiving and organizing exhibitions.<br/> <br/> <strong>Collecting Value: Photography Archives of Los Angeles (4 units)</strong><br/> This course examines photography collections and archives of Los Angeles. Rather than looking at a single artist, time period, or approach to the photographic medium, we will look at the dynamics of photo collections held by institutions and individuals: how they are formed, what they contain, and which histories and narratives they uphold, counter, or exceed.<br/> <br/> Each week, the class will visit a different collection across the city, exploring venues such as museums, libraries, galleries, and historical archives. We will also meet with contemporary artists who use and collect vernacular images in their practice. With each module, we will explore and complicate histories of the medium and set out to understand how institutions use photography collections to produce and reinforce cultural, historical, and economic value.<br/> <br/> The class will also correspond to the organizing of a forthcoming exhibition of Chinese photography from the 1980s and 90s, recently acquired by the Hammer Museum. The course will teach methodologies of curatorial practice with a focus on archival research, material preservation, and museum writing.<br/> <br/> <strong>Drawing from Life and the Imagination: 17th-century Dutch Drawings at the Getty Museum (4 units)</strong><br/> Taught in the study room of the J. Paul Getty Museum by the Curator of Drawings at the J. Paul Getty Museum, this course examines 17th-century Dutch drawings. Using Getty drawings made by Rembrandt van Rijn and his contemporaries, this class offers students a unique opportunity to study Dutch works on paper firsthand. Classes will be structured around a thematic selection of drawings and discussion topics include natural history illustration, landscape, figure studies and portraiture, religion, and travel by land and sea. Students will gain a better understanding of various drawing media and techniques as well as obtain a detailed overview of the function of Dutch drawings from the 1600s. Students will read primary sources (in English) about art theoretical debates of the time. Particularly important is the debate about whether artists should draw from life or from their imagination. This two-pronged approach to draftsmanship accounts for the meticulously rendered, vibrant 17th-century Dutch drawings that continue to delight and provoke us today.<br/> <br/> <strong>East Asian Gardens: China, Japan, Korea—and California? (4 units)</strong><br/> What kinds of gardens have existed in East Asia, and what sorts of functions have they fulfilled? How have they engaged with broader visions of the cosmos, and how have they expressed such understandings? What happens to such gardens when they are translated into a cultural context very different from that in which they emerged? To answer these questions, this course, taught by a curator at the Huntington Library, will take a broad view of the history of East Asian garden-making, examining images, texts, films, and gardens from the 2nd century BCE to the present. We will investigate hunting parks constructed as microcosms of empires, holey rocks that inspired dream-journeys to immortal realms, Buddhist paradises accessible in this-worldly estates, and textual fantasies of gardens of the mind. Taking advantage of the Chinese and Japanese Gardens at the Huntington, this course will also explore how such concepts have been put into practice in the physical spaces of these gardens, where the course will be held each week. Moreover, we shall trace the very different histories of these two gardens in order to gain insights into California''s shifting relationship to East Asia over the course of the twentieth and twenty-first centuries. In taking this course, students will ultimately gain an understanding of the diversity of garden forms in East Asia; familiarity with key concepts used in garden-making; practice with the skills of visual and spatial analysis, as well as cultural and historical contextualization, necessary to discuss gardens meaningfully; and experience with curatorial strategies for making East Asian gardens accessible to diverse audiences. The final project will involve developing an interpretive program for one section of the Huntington’s gardens. <strong>This course meets at the Huntington Library, Art Collections and Botanical Gardens.</strong> <em>Additional Core Requirement Met: Regional Focus and Pre-1800.</em></p> </div>','Any 100- or 200-level Art History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14580,2027,1320,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Imag(in)ing</strong><strong> War and Disaster in Modern and Contemporary Japan</strong></p> <p>This course explores how practitioners of art and visual culture have responded to physical and psychological damages that were caused by wars and disasters in modern and contemporary Japan. The course loosely follows a chronological order and a thematic framework. We will look at expansive materials, including colorful and playful woodblock prints (<em>ukiyo-</em>e) of natural disasters; prints and memorabilia of the Russo-Japanese war (1904-05); topography and the building of the Yasukuni Shrine and its exhibitions; the birth of the avant-garde and its relation to the Great Kanto Earthquake (1923); war documentary paintings and propaganda during WWII; atomic bomb photographs and memorials; reportage painting of the 1950s; anti-art and non-art movements of the expanded 1960s; <em>kawaii </em>(cuteness) and monstrosity in manga and animation; and socially engaged art about Fukushima. The course aims to enable students to analyze how politically inspired or socially engaged art developed in modern and contemporary Japan. <em>Additional Core Requirements Met: Regional Focus (CPRF).</em></p> <p><strong>Who Owns Art? </strong></p> <p>As art objects - especially those from antiquity - have become increasingly valuable, as both commodities and as national treasures, questions as to who owns art and who is best to care for these objects are essential to museum curators, academics, and politicians. There are several debates over who owns art of ancient civilizations like Greece and India. Do treasures like the Parthenon sculptures at the British Museum belong to Greece and should they be returned? Or should they remain in the museum where more people have access to them? This seminar will introduce students to laws enacted by UNESCO (United Nations Educational Scientific and Cultural Organization) to protect world, cultural, and national heritage, as well as to the examination of museum collecting policies in America. Specific cultural patrimony cases will also be examined and discussed. This seminar is for students who are interested in learning more about cultural patrimony, art law, and museums.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14581,2027,446,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/300/arth-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14582,2027,447,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/400/arth-490','<div class="desc"> <p>Open only to senior Art &amp; Art History majors with an emphasis in History of Art. May be repeated once for a total of four units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14583,2027,4072,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/400/arth-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14584,2027,448,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arth-art-history/400/arth-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14585,2027,2729,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-100','<div class="desc"> <p>This is an interdisciplinary course providing an introductory overview of public engagement through the lens of art. Students will learn basic methodologies of public engagement; how to create an inquiry-based lesson plan with an emphasis on creative expression; and how to lead a group of elementary or middle school students, with priority placed on collaboration and art-making. During the first six weeks of the semester, students will research, plan and work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop lesson plans for an original after school art workshop for local youth. In the following 6 weeks of the semester, Oxy students will collaboratively lead their workshops for local elementary or middle school youth, culminating in a final public presentation at the Oxy Arts gallery. </p><p>Cross-Listed as: EDUC 143.</p><p><br/></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14586,2027,15,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-101','<div class="desc"> <p>Working with a variety of drawing materials - charcoal, pencil, ink, gouache, and acrylic paint - students investigate a fundamental aesthetic and visual vocabulary. Beginning with exercises in mark-making, then working through a formal study of basic visual elements and simple subject matter, students develop a working understanding of two-dimensional composition. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14587,2027,16,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-102','<div class="desc"> <p>This course is an introduction to painting from a global perspective. Throughout history all cultures have developed techniques to depict their realities and ideas through paint. Painting from a global perspective will introduce students to European formalism (line, shape, form, light, space, and color) as one set of tools among many found around the world. We will consider how varying cultures have historically and contemporarily utilized paint to think through experiences on earth. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14588,2027,17,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-103','<div class="desc"> <p>The aim of this course is to introduce the conceptual, technical, and critical tools central to contemporary sculpture practices. The class consists of a combination of technical seminars, in-class fabrication, critiques, field trips, informal lectures in contemporary art history, readings, and a series of short papers. Emphasis will be placed on the student''s ability to make, understand, discuss, and write about sculpture in a substantive way. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/. Students will also be responsible for purchasing a materials kit including PPE at the Oxy bookstore.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14589,2027,18,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-105','<div class="desc"> <p>Printmaking Fundamentals is an introduction to the technical and conceptual properties of relief and intaglio printmaking. Through a series of projects, critique sessions, and written assignments, the course will introduce students to debates in contemporary printmaking, and the larger historical and cultural contexts that inform their work. The class will also feature visiting printmakers, field trips and other activities linking the coursework to the larger Los Angeles community. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/. Students will also be responsible for sourcing a small amount of other art materials.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14590,2027,4429,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-106','<div class="desc"> <p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 12pt"><span style="font-size: 10pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">This course introduces students to the technical and conceptual foundations of ceramics. Through sculptural projects, visiting artist lectures, readings, and group discussions, students will learn core hand-building techniques and progressively expand their skills through assignments that increase in both engineering and conceptual complexity.</span></p><p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 10pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">The semester begins with functional forms that teach fundamental clay-working processes. Assignments will expand in complexity with sculptural works, interactive pieces, and installation-based projects. The course also covers essential ceramic chemistry, including clay and glaze composition and the transformations that occur within the kiln.</span></p><p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 10pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">By the end of the course, students will know how to create ceramic objects, articulate and critique artistic intentions, and participate meaningfully in broader cultural conversations surrounding contemporary ceramic art making and objects.</span></p><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 10pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14591,2027,999,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-107','<div class="desc"> <p>The aim of the Photography Fundamentals course is to develop the conceptual, technical, and historical tools to develop a critical photography practice. The course will consist of a combination of technical seminars, critiques, class readings, field trips, lab time, and lectures in photographic history and contemporary art practice. The course will provide a technical introduction to the fundamentals of digital photography, including: camera operation, file management, image processing, Photoshop, printing techniques, and image presentation. Additionally, students will develop the critical skills needed to discuss photographs productively, participate in critiques, and generally situate their photographic production within a larger cultural and historical construct. Emphasis will be placed on student''s ability to make, understand, and discuss photographs in a substantive way. Lectures, critiques, and personal consultations will stress the interdependent concerns of technique and content. Underscoring the course''s outcomes of visual literacy are the centrality of photography to the historical development of modernity and the crucial role of digital photography in our image-centric globalized world. Throughout the course, students will be encouraged to integrate the breadth of their liberal arts studies in their image making. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14592,2027,4073,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14593,2027,4074,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/100/arts-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14594,2027,892,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-203','<div class="desc"> <p>Intermediate study in sculpture, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 103 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14595,2027,1570,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-209','<div class="desc"> <p>This course is a conceptual art class that takes photography as its subject. Using a wide range of photographs and photographic practices, the class will consider how photographs are instrumental in forming our notions of self, family, work, and nation. We will also grapple with the difference between analogue and digital photography and photography''s relation to the physical world. The class will read key photography essays that will challenge students to think critically about the role of photography in contemporary culture and modernity, historiography, and science. We will use a broad range of art techniques like drawing, painting, printmaking, sculpture, digital alteration, and even craft techniques to remake and rework photographs to reveal hidden truths or create new meanings. Unlike some classes where you learn art techniques first, here you will be expected to adopt techniques and generate art from a set of ideas that arise from our readings, discussions, experiments, and field trips. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14596,2027,450,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-210','<div class="desc"> <p>Intermediate study in painting, including developing theoretical, historical, and critical understanding of materials and media. Emphasis may change from year to year. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14597,2027,4075,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-211','<div class="desc"> <p>This course will be an exploration of historical and contemporary usage of portraits, focusing specifically on painting and drawing. Countering the universal tendencies of a Eurocentric modernity within the arts, Contextualizing Portraits will explore portraiture through a global lens. This means decentering European formal techniques as a universal standard of creative expression. </p> <p>Students will be introduced to painting practices and techniques found throughout the Americas (e.g. Mayan murals, codices, weavings, etc), India (e.g. Padmapani painting in Ajanta cave), China (e.g. Zhou Jichang second half of 12th century), Egypt (e.g. Egyptian tomb of Huy), and more. This course material will require a sensitive investigation of our aesthetics biases, navigating appropriation, developing our epistemic demeanor, and broadening our tool sets within painting and drawing. </p> <p>Thematically, we will consider how portraits can be used today to critically investigate contemporary issues found in our society today. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14598,2027,3331,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-212','<div class="desc"> <p>How can a painting or paintings influence individual or group identities? What does historical context, technique and aesthetic have to do with identity? This course will explore these questions and more. We will examine varying cultural moments throughout history where some form of painting was utilized to produce or reproduce national or group identities. We’ll also look at how individual artists used painting to subvert efforts to homogenize national identities. Additionally, students will be introduced to a variety of painting techniques, locating their historical usage relating to the course theme, and uncovering their potential contemporary value. </p> <p>Alongside course lectures, technical demonstrations, and visiting speakers students create five distinct paintings. Through these exercises students will gain an understanding of the historical context for painting practices and how they may be used today in popular and social media. Students will further their media literacy skills by developing a tool-set for navigating contemporary imagery, specifically relating to painting. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14599,2027,20,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-215','<div class="desc"> <p>This is an introduction to the fine art of silkscreen printmaking. Students learn the historical, theoretical, and critical understanding of the process, with an emphasis on developing their artistic voice by completing specific assignments. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/. Students will also be responsible for sourcing a small amount of other art materials. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14600,2027,811,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-216','<div class="desc"> <p>An introduction to the process of lithography, a technique of printing from a drawn image on limestone. Course emphasis will be on the drawing and how the medium allows for evolving the visual image over time. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14601,2027,451,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-217','<div class="desc"> <p>An introduction to new combined photo and drawing processes in printmaking, including: photo-sensitive emulsion on copper plates, solar etching, and paper plate lithography. This course will explore how photography can influence the many approaches to contemporary printmaking. Students should have an interest in creating photo images and some familiarity with Photoshop software. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14602,2027,4019,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-218','<div class="desc"> <div> In three projects and a print exchange, students will make artwork that is experimental and experiential: exploring printmaking as it relates to their own body, and utilizing printmaking in ways that are performative, interactive, and large scale. Students will engage with academic readings, guest artists, and each other''s artwork. You will work in monotype, etching, and woodcut relating each assignment to your physical presence, or your and the viewer''s physical interaction with the process and the print. This course will expand your understanding of what is considered a print, cultivate insight into your own art making process and your intellectual understanding of art as a means of communication. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/ </div> </div>','ARTS 105 or ARTS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14603,2027,2370,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-228','<div class="desc"> <p>Book Arts: The Handprinted Book is a hybrid book making, research, writing and collaborative art making course. Students will advance their knowledge of letterpress printing by researching, planning, designing, and producing a handprinted artist book. The course will address narrative sequencing, page layout and design, type as graphic innovative and/or image-making, methods for the Vandercook Press, and the structure of the book. Each course iteration will address a theme, integrating book making techniques with theoretical readings, collaborations with faculty and departments from across the College, and primary research in Special Collection the Moore Zoology Lab and other campus collections. The course is will also examine the current state of the book in the context of 20th and 21st century artist book design and production. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 227 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14604,2027,2753,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-230','<div class="desc"> <p>This course invites students with previous art experience from across the College, including visual arts, music, theater, creative writing, MAC, etc., to explore genre-crossing art. The course will focus on the specialty of the faculty member, including video installation, sound art, performance art, site-specific art, collaborative projects, community based projects and social practice art. The class meets twice per week for technical demonstrations, in-class art making, visiting artists, and critical feedback, along with out of class visits to contemporary art and performance venues. Permission of instructor required. Not open to First Year Students.</p> <p><strong>Sonic Materiality: Intersecting Music and Visual Art</strong></p> <p>At the intersection of music and visual art, this collaborative course will explore the ways meaning is made in creative work and is open to all students with an interest in interdisciplinary art practices. Over the semester we will study leading artists whose work straddles sound and visual forms. Students will work with their peers to unpack how they assign meaning and infuse strong concepts and narratives in their art. Through this course, students will experiment with various strategies and tools to express their ideas and will develop a heightened appreciation for the creative process.<br/> <br/> Each week concepts will be presented through the lens of music and visual art and will be structured to alternate between in-depth study and hands-on class exercises. Such experiments will foster student-led discussions, and lead to projects that challenge students to emulate and ultimately reimagine these ideas through their artistic work. We begin with artists like Jason Moran, a renowned pianist and multimedia artist, whose piece Ringing My Phone perfectly demonstrates the innovative way in which he intersects music and language. The conceptual work of Charles Gaines will guide our exploration of systems that produce sensory experiences. In addition to Gaines, we will look at musicians who integrate the historical archive, like Jon Batisteâs piano arrangement of the Star Spangled Banner, alongside visual artists like Bethany Collins whose physical interventions on the musical notions of other national hymns demonstrate how meaning shifts over time. Non-traditional composers such as John Cage and Wadada Smith will prompt a conversation about the nature and forms of sound.<br/> <br/> A significant objective of the course will be to expose the ways we take meaning for granted in our sensory experiences. We will question how language facilitates the categorization of various creative practices and consider the value of blurring such distinctions. Students will be asked to engage in a range of strategies to create individual and collaborative work that integrates multiple art mediums, design systems, and methods to support these creations. They will also consider how context impacts meaning/narratives in their work. Prompts throughout the semester will encourage students to answer questions about how one can create with unconventional sounds/tools from their environment and culminate in a final project resulting in a collaborative performance or presentation.<br/> <br/> The class will emphasize the rich history and resources of LA and will include visiting artists and guest lecturers, as well as field trips to some of LAâs artistic hubs, such as Art &amp; Practice in Leimert Park, The Red Cat, LACMA, Array studios, and relative exhibits. This class aims to enrich studentâs education by exposing them to varying thoughts and approaches to creating and appreciating art. Ultimately we will encourage students to think more broadly about pushing past the traditional boundaries and barriers surrounding art and to create in a way that is authentic to their individual story. Cross-listed as: MUSC 233.</p> <p><strong>Sound Systems as Sculpture</strong></p> <p>Sound Systems as Sculpture is a hands-on, interdisciplinary exploration of the aesthetics, culture and history of sound and its various amplification systems. Taking place in the sculpture studio at Oxy, students will learn aspects of sound system design theory and construction while exploring the origins of sound system culture. Emerging from Jamaica in the 1950s, sound system culture expressed the revolutionary voices of Jamaicans seeking to escape the bonds of colonialism. This critical approach impacted sound system cultures in the UK and the US, particularly during the formative years of electronic music and hip hop. Communities whose voices were suppressed created new forms that amplified their stories, struggles and dreams. Sound Systems as Sculpture will examine the cultural, political and aesthetic impact of this work. Using sculptural practices to design and fabricate sound systems, students will generate new works that develop the art of sonic sculpture and amplify their own voices and sonic imagination.</p> <p><strong>Visualizing Sound</strong></p> <p>Sound Arts takes a cross-disciplinary approach to utilizing sound as a stand-alone installation or integrated within other media. Many contemporary artists are interested in incorporating sound into their projects but may not know how to approach and accomplish that integration. Because sound is ephemeral it can be used in an infinite number of ways to infer complex relationships. The challenge of using sound is that of translating ideas into the sonic medium and then reproducing that medium back into physical space. In this class students will learn about sound and discover ways to apply sound to express a deeper theoretical practice. Practical sound related techniques will be explored, as will their application through skills like deep listening, recording techniques for best capture practices, basics of the Digital Audio Workstation, and the use of sound reproducing systems. Students will collaborate on a project over the course of the semester with an exhibition in the OXY Arts Space at the end of the semester with an opportunity for performance.</p> <p><strong>Pollinator Drones, Wish Factories, and Robotic Dogs: âWhat-ifâ Scenarios as Drivers of Creative Production and Imagination</strong></p> <p>As humankind stares down a number of unprecedented global challenges, the need for creative, radical thinking is imperative. In this interdisciplinary studio, students will develop a series of detailed and speculative projects inspired by boundary-pushing artistic and technological practices. The course will examine precedents from contemporary art, media, engineering, performance, design, and technology that offer responses to a wide range of âwhat-ifâ scenarios. The primary goal of the class will be to guide students as they develop a methodology for making creative and responsive workâone that relies on provocation and imagination as driving forces. Class projects will be designed to develop critical thinking and research skills, art-making and visual communication capabilities, and will call for speculative, even fantastical, responses to complex sites and situations. Technological and data-driven approaches, including data analysis, modeling, and scenario planning, will be integrated into the class assignments, encouraging cross-disciplinary collaborations between computer science and media arts students. Instructional assignments will explore a range of materials, scales, and research methods, and will encourage students to develop their abilities to hone and express innovative responses to complex societal and relational questions. The final series of class projects will address the uncertainty of climate change as a contextual framework, and final proposals may range from site-specific art installations to new applications for robotics; from creating futuristic soundscapes to designing experiences in VR. Site visits and guest lecturers will extend studentsâ connections with selected Los Angeles sites and their contexts, the understanding of a broad set of perspectives and values, and real-world examples of collaborative, cross-disciplinary projects. Cross-listed as: COMP 230.</p> </div>','One ARTS, MUSC, THEA classes. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14605,2027,1503,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-250','<div class="desc"> <p></p> <p>African American, Latinx, Asian, Feminist, GLBT, and transnational artists catapulted by liberationist desires and responding to questions of social transformation are the focus of this hybrid art making, history, and theory class. The course will focus on Los Angeles-based 20th and 21st century artist led efforts that critically engage issues of race, gender, ethnicity, and class both historically and within the present. The course will begin with an investigation of questions related to historiography and memory as they relate to politically engaged art practices through critical texts, a site visit to the Southern California Library, an independent archive of local Los Angeles movement history in South Los Angeles, and a workshop that will share research methodologies employed by my own collaborative artistic project, the Pochx Research Society of Erased and Invisible Histories to contest dominant historical and artistic canons. Through a workshop format, local contemporary artists such as Dewey Tafoya, Shruti Purkayastha, will provide students with tools to develop projects that respond to dominant cultural narratives through graphic, performative, and interventionist strategies. Finally, students will learn how artists shake the foundations of various established institutional worlds and the definitions of art itself by moving away from these very institutions and spheres of practice and by creating their own structures for critical thought and praxis: building collectives, artist led spaces and in the case of School of Echoes, becoming community organizers. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14606,2027,2861,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-270','<div class="desc"> <p>Art, Ethics and Medicine: The PPE Portrait Project is a four-credit class focused on the tenets of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care at USC-Keck Hospital, Stanford Medical School, UMASS, Mass General and advising nearly a dozen other hospitals across the US and beyond. At the heart of the PPE Portrait Project is the centrality of the image, and the role of the face in generating empathy, compassion and ethical behavior. </p> <p>The PPE Portrait Project Semester will combine theory, research and practice together with the community engagement (ARTS 275) intrinsic to this social practice art project. Students will learn how artists act as innovators and catalysts of change; the art history and visual studies of representing the face, including portraiture, photography, and discredited attempts to read intellect or morals in the appearance of a face. Students will also learn about the connections between visual culture (like portraits) and science, including the developmental concepts of facial recognition, and representation recognition in infants and others; the neuroscience of mirror neurons and the biological basis of intersubjectivity as the foundation of ethical behavior; the philosophy of bioethics and notions of patient self-determination and agency; and the biology and physiology of social and cultural actions. Students will learn how looking at images has the power to physically change a person''s body. Through this project, students will deepen their understanding of the structures and processes of privilege, exclusion, and marginalization that shape healthcare in the United States. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,'ARTS 275 ',NULL);
INSERT INTO course_descriptions VALUES(14607,2027,2862,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-275','<div class="desc"> <p>In this course, students will activate their own project site of the PPE Portrait Project. The PPE Portrait Project is an interdisciplinary social practice art project that is transforming best medical practice. Created in 2014 by Occidental College professor Mary Beth Heffernan in response to the Ebola epidemic, the PPE Portrait Project is now supporting COVID care across the US and beyond. The project humanizes anonymous masked healthcare workers with wearable portraits affixed to the outside of their hazmat suits. Students will be encouraged to implement the project in a group with whom they have a meaningful connection, including schools, community groups; any group who would benefit from an enhanced human connection at a time of masked distancing, anonymity and faceless interaction. </p> <p>At the heart of the PPE Portrait Project is the centrality of the image, and the role of images of the face in generating empathy, compassion and ethical behavior. With widespread facemask use on our horizon for the foreseeable future, the need to address the isolation and alienation caused by faceless person-to-person exchange is expanding beyond the urgent need of hospitals. Precipitated by social media before the pandemic, and now exacerbated by the coronavirus, we are experiencing an "epidemic of facelessness." </p> <p>Students will use community based learning methods to ethically engage with a group, and innovate with the PPE Portrait Project tenets and materials to best meet the needs of the community partner. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,'ARTS 270 ',NULL);
INSERT INTO course_descriptions VALUES(14608,2027,1571,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-280','<div class="desc"> <p>A team-taught course pairing an Occidental and an Art Center College of Design faculty member in project-based work integrating the history, theory, and practice of the visual arts. Not open to first year students. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14609,2027,3274,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-281','<div class="desc"> <p>A studio course about the use of the self in photography. Students will produce new photo-based projects which may include self portraits (What counts as a portrait? What constitutes the self?) as well as loose or alternative interpretations of the theme, such as work that explores the self through family history. The special focus on the notion of "self" offers a way to engage not only with individual "self-representation," but also with the ways a "self" might emerge from, and shape, other modes of identity: family, community, nation, transcultural. Thus, the course is not only a fine arts course, but also a course that expressly engages with issues of Diversity, Equity, and Inclusion as explored through the experiences, histories, and contemporary lives of students, faculty and the larger communities that an individual may imagine themselves to be a part of. Discussion topics will include gesture and expression, the gaze, beauty, identity, narcissism (actual and perceived), memory and time, and self portrait methodology. Lectures will offer an overview of the history of self-portraiture in photography, from the medium’s early days though contemporary social media. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14610,2027,3332,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-283','<div class="desc"> <p>A course that celebrates the physical production of photographs. For the first century and a half of photographic history, a photograph was typically an object to be held in one''s hand or hung on a wall. Today, it is not uncommon for a photograph to exist only in digital form; the entire life cycle of an image may take place on a series of screens. In this course, students will focus on producing tangible photographic objects. Each student will conceive of a photographic project in which a final, physical form (such as an artist book or photo-based sculpture) is central to the concept. The first part of the semester will be devoted to lectures, research, technical demonstrations, and exercises to help students decide on a direction and form for their final projects. Next, students will work intensively to produce a new series of photographs (digitally or on film) that will be refined through group critiques; editing and sequencing will be important topics of discussion at this stage. Finally, students will focus on producing their object(s), taking concepts and skills from the first part of the semester and applying them to their new images. Students will have the opportunity to print in the black and white darkroom and/or with a large-format digital printer. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 107 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14611,2027,3243,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-287','<div class="desc"> <p class="MsoNormal">In this course, we will examine historical and contemporary approaches to social documentary photography—visual anthropology, citizen journalism, and agitprop, among other forms—and consider the efficacy of photographic images in both garnering awareness and persuading actors to enact sociopolitical change. We will draw consensus on our understandings of “the real" in contemporary art and the broader media landscape—in tandem to and opposition with staged, scripted, and/or verisimilar depiction modes—while examining the ethics of capturing another''s likeness. Over the course of the semester, we will delve into critical writings and works by documentarians/collectives that bring the (neo-)liberal humanist documentary model into complex new territories. Students will focus on a community, situation, or environment of their own choosing, using pictures and words to examine the unique situations unfolding in front of their cameras. Together, we will confront our role as image-makers, our ethical relationship to our subjects, and ruminate on the civic value of the social documentary form today.</p> <p class="MsoNormal">The social documents experienced and discussed in class will be used to interrogate systems of differentiation and exclusion that are instrumentalized to preserve patriarchy and racial capitalism. Examining the codification of gender, race, and class through photographic likeness, we will trace a line of resistance in documentary works that offer a response to status quo representations. Our investigations will be grounded in the American Experience—gender queering in the American city, depictions <em>of</em> and <em>by </em>Native Peoples, the foregrounding of white suffering in times of common strife, and lived Black experiences seen from within and without, among other themes. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 107 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14612,2027,1203,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-290','<div class="desc"> <p dir="ltr" style="color: rgba(34, 34, 34, 1); font-family: Arial, Helvetica, sans-serif; font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0; text-transform: none; widows: 2; word-spacing: 0; white-space: normal; background-color: rgba(255, 255, 255, 1); text-decoration-style: initial; text-decoration-color: initial; line-height: 1.38; margin-top: 0; margin-bottom: 0;"><strong>Art Outside the Bounds: Fiber Art + Community Studio Art Class</strong><br/> In this hands-on studio class centered around textile and fiber processes, students will explore the different ways that they can use textile arts in solidarity with social justice movements. Using macrame, felting, and other fiber arts techniques, the course will delve into and expand on visiting Wanlass artist Tanya Aguiniga''s Community Engagement Methodologies which include working with traditional craft materials to create sculptures, installations, performances, and community-based art projects. Students will also engage with and collaborate with local community organizers. At the end of the course, students will develop a new set of skills and new material vocabulary to create a collective toolkit of best practices in working with the community based on our semesters'' visits, research and individual material explorations. No prior fiber art experience is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14613,2027,4076,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-295','<div class="desc"> <div> <div> <p style="margin-top: 10px;">Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p style="margin: 20px 0 0; padding: 0;"><strong style="margin: 0; padding: 0; font-weight: bold;">In Praise of Shadows </strong></p> <p style="margin: 20px 0 0; padding: 0;">This interdisciplinary art course is about perception and takes its inspiration from Jun’ichiro Tanizaki’s classic text, which profoundly illuminates the significance of shadows in our sensory experiences, via Japanese aesthetics. The course works through the premise that shadows and darkness do not just produce conditions that hide/conceal/obscure, but also that they can reveal and illuminate. Using photography, printmaking and hybrid sculptural forms, we will experiment with various artistic strategies that explore the nature of the contingent relationship between shadow and light. Our experiments will extend to questions and explorations that help us unpack social and cultural conventions and hierarchies that exist. Additionally, visits to studios and workshops around LA will enhance our hands-on activities. We will not only approach the theme of shadows through artistic practices, but also through philosophy, physics, literature and anthropology, so students from all disciplines are encouraged to enroll to maximize a diversity of ideas and fields of knowledge in our explorations.</p> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14614,2027,4077,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/arts-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14615,2027,3285,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/200/copy-of-arts-282','<div class="desc"> <div><p>This studio course will focus on the study of place in photography, with a particular focus on Los Angeles County. As both a global center of the film industry and the city of choice for many artists, LA occupies a unique position in visual culture and the collective imagination. Students will spend the semester working on a photographic project that explores a particular aspect of life in LAâsuch as a unique community, culture, or subculture, history, climate, geography, or architectureâin depth. Discussion and lecture topics will include photographing communities as both an outsider and an insider, what defines a place, the nuances of photographic genre (journalism, fine art, etc.), and the rich cultural topography of Los Angeles. We will also explore events and policies that have shaped our experience of the region, such as the construction of the freeways, redlining, and restrictive covenants. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p><p><br/></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14616,2027,1683,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-301','<div class="desc"> <p>Audre Lorde famously wrote that the master’s tools will never dismantle the master’s house. What possibilities open up when we use language - a common currency of our everyday lives, too often the foundation that props up structures of confinement and limitation - on our own terms, in forms of our own invention and modes we imagine autonomously? How can we use writing to support and expand the work we do as artists? Is language a “master’s tool” or is it a tool we can use to “dismantle the master’s house”? In this class, we will explore creative forms such as artistic manifestos, statements of poetics/aesthetics, and reviews as invitations to better understand and articulate the parameters of our own art practice, and as powerful opportunities for collective enunciation. We will do close readings of primary texts from European, Latin American, and U.S. American avant-garde and art-activist movements, both historical and present-day. We will consider essays, reviews, manifestos, poems, blog posts, and tweets. Students will write individual and collaborative art statements as a way to clarify their own work, and think through larger issues in aesthetics and the social/political potential of art. Assignment exercises will encompass research and practice in collective and individual art writing, focusing both on student work and the work of other artists.</p> <p>This course fulfills the second stage writing requirement. This course does not fulfill a 300-level studio art elective. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14617,2027,2892,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-303','<div class="desc"> <p>Advanced study in sculpture, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14618,2027,3884,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-307','<div class="desc"> <p>Advanced study in photography, including developing a theoretical, historical and critical understanding of materials and media. In this studio course, students will produce complex photographic projects in a genre and photographic medium of their choosing. Students will be expected to refine technical and conceptual skills developed in lower-division photography courses and produce projects that express concepts in a sustained manner. Much emphasis will be placed on critiques, where students will be expected to analyze peer work and provide substantive feedback. Lecture and discussion topics will include editing and sequencing, studio lighting, fine art print production, and exhibition techniques. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','Students must have taken ARTS 107 , the introductory-level photography course, as well as one of the three intermediate photography courses (ARTS 281, ARTS 282, or ARTS 283), or have instructor permission. Students who have not taken the prerequisite courses and are seeking instructor permission must be able to detail significant experience in the medium of photography. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14619,2027,21,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-310','<div class="desc"> <p>Advanced study in painting and drawing, including developing a theoretical, historical, and critical understanding of materials and media. Specific focus may vary from year to year. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','ARTS 102 and ARTS 210 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14620,2027,1048,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-330','<div class="desc"> <p>Advanced study in printmaking including developing a theoretical, historical, and critical understanding of photo-based materials and media, including images on pronto plates and monotypes. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14621,2027,454,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-390','<div class="desc"> <p>Art in LA will explore the shifting roles of the contemporary artist, art writer, and curator in today''s diverse and globalized art world. Students will put theory into practice by engaging in art making, curating and writing about contemporary art in Los Angeles with the goal of creating an expansive critical space for their thoughts to flourish. The course will ask, "What are exhibitions?” investigating conventional and alternative curatorial practices that question the cultural, political, economic, regional, and social contexts shaping the exhibition of contemporary art. Students will collaborate to mount an exhibition of their own design, and will be encouraged to question the boundaries of the "white cube gallery," pushing art into surprising public and private spaces. <br/> <br/> Art in LA will feature behind the scenes visits to Los Angeles area exhibition venues and artists'' studios, enabling students to learn about the range of art practices and the practical exigencies of bringing art and its exhibition to fruition. This course will serve as the required advanced exhibition methods course for junior studio art majors, modeling the myriad of ways it means to be an artist in the world, and readying rising seniors for a robust comprehensive experience. Scheduled at the same time as the Studio Art Senior Seminar, the course is designed to facilitate collaboration between junior and senior art majors. Students in ARTS 390 will participate in the ARTS 490 senior comps critiques, provide feedback to senior''s artist statement drafts, and collaborate with the senior art majors in the installation of their comprehensive exhibition. A course materials fee will be charged to the student''s account. For the fee amount, please see the Special Fees section of the college catalog: https://oxy.smartcatalogiq.com/en/current/catalog/tuition-fees-and-expenses/special-fees/</p> </div>','One 200-level ARTS course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14622,2027,4078,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14623,2027,455,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/300/arts-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14624,2027,23,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/400/arts-490','<div class="desc"> <p>Group critiques of individual projects in student''s choice of medium. Discussion of techniques, exhibition problems, self-evaluation, and current art movements, in the context of the history of art. May be repeated once for a total of four units.</p> </div>','At least junior standing and ARTS 102 , ARTS 103 , ARTS 105 , ARTS 203 , and ARTS 210 ; OR ARTS 216 ; OR ARTS 217 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14625,2027,4079,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/400/arts-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14626,2027,456,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/arts-studio-art/400/arts-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14627,2027,3830,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-130','<div class="desc"> <p style="text-align: left">We will explore key events that shaped modern and contemporary Korean society and culture. We will explore the racial and gendered formation of Korean culture and national identity from the early 1900s to the twenty-first century. Some of the key historical events we will address throughout the semester include Japanese colonialism, the Korean War, the US military presence in South Korea in the aftermath of the Korean War, contemporary global sporting events such as the 1988 Seoul Olympics and 2018 Pyeongchang Olympics, transnational popularity of South Korean popular culture, and the feminist and queer activist movements. The objective of the class is for us to answer the questions: How have these historical events influenced Korea and its inhabitantsâ conception of the nation and its positionality in the world? How has Korean culture evolved over time through transnational encounters? Alongside academic books and articles, we will be viewing and discussing visual media, including documentaries, fictional films, and music videos. All of the course instruction and assigned materials will be in English or have English subtitles.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(14628,2027,3356,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-131','<div class="desc"> <p>In this course, we will examine various forms of Korean popular culture. We will examine how Korean popular culture not only reflects, but also influences Korean cultural conceptions of gender, race, sexuality, and class. Each week, we will analyze Korean popular culture through the frameworks provided by relevant academic articles and book chapters. The academic texts we will discuss in class will focus on topics including disability, queer activism, neoliberalism, militarism and masculinity, feminism and anti-feminism, and multiculturalism. The types of popular culture we will examine in class will include films, television programs, and K-pop music videos. All reading materials will be in English and all of the popular culture contents will have subtitles. Therefore, no prior knowledge of Korean language is necessary to take this class.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(14629,2027,3297,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-150','<div class="desc"> <p><em>The Literary Mind and the Carving of Dragons</em> is a highly influential work on Chinese literary aesthetics, and its title also suggests two important constituents of the literary composition process by pre-modern Chinese authors: ideas and craftsmanship. By providing an introduction to classical Chinese literature through readings in translation, this course will integrate aesthetic appreciations and cultural understandings of the classical Chinese literature, and help students grasp the conceptions, styles and creative skills of different Chinese authors. The time range will cover the period from <em>The Classic of Poetry (Shijing) </em>through the Qing dynasty. Throughout the course, students will have a basic historical knowledge of the Chinese literary tradition, as well as a sense of how to go about interpreting Chinese literary texts. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14630,2027,4080,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-161','<div class="desc"> <p class="MsoNormal">This course introduces students to key literary texts from Japan’s modern era (1868-present). During this period, Japanese literature and the Japanese written language were reinvented alongside rapid socioeconomic, political, and cultural changes. As Japan experienced the industrialization, economic success, wars, natural disasters, and technological breakthroughs that characterize this period, literature played a key role in forming the national consciousness. Authors examined in this course may include Higuchi IchiyÅ, Natsume SÅseki, Kawabata Yasunari, Tanizaki Jun''ichirÅ, Åe KenzaburÅ, Tawada YÅko, and Murakami Haruki. We will consider works of Japanese literature within their linguistic, cultural, and historical contexts. Through essays, reading responses, and class discussions, students will explore how literature transforms the human experience into words and in doing so transforms the human experience. The course is given in English, but those whose language proficiency permits may choose to reference the texts in the original Japanese.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14631,2027,3975,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-165','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course offers an introductory survey of Japanese culture from its earliest prehistory to the twenty-first century, covering key moments and themes that shaped Japanâs cultural and national identity in the context of local and global transformations. We will examine Japanâs social values, aesthetic expression, religion, and political institutions to understand Japanâs cultural heritage and contemporary society through its transformation from a âfeudal stateâ to a âmodernized nation.â Through secondary scholarship from a wide range of disciplines, we will explore meaningful ways of understanding historical and cultural contexts from diverse perspectives in critical analysis writings throughout the course while considering points of comparison and exchange that relate to our own experiences.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14632,2027,4081,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14633,2027,4082,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/asn-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14634,2027,4083,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/100/copy-of-asn-193','<div class="desc"> <p>Research with an Asian Studies faculty member in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14635,2027,3885,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-221','<div class="desc"> <p style="text-align: left">In this course, we will examine the rich history of feminist theory and activism in Asia and investigate the various issues that Asian feminists have worked on throughout history and leading up to the contemporary era. In particular, we will focus on how feminists from different parts of Asia have contended with issues of colonialism, war, marriage, motherhood, queer rights, and, more recently, sexual consent and the #MeToo movement. We will expand our discussion of these issues into a larger debate about whether and how feminists from different parts of Asia can collaborate with each other in their feminist activism. More broadly, we will discuss how feminists from Asia and beyond can work together without perpetuating colonialist, racist, and neoliberal structures of hierarchy. Alongside academic books and articles, we will be viewing and discussing visual media, including documentaries and fictional films. All of the course instruction and assigned materials will be in English or have English subtitles.</p> </div>','None ','None ',NULL);
INSERT INTO course_descriptions VALUES(14636,2027,4084,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-248','<div class="desc"> <p>This course covers the history of Japan from the 1868 Mejii Restoration to the present, with particular focus on the emergence of modernity, the Pacific War, and popular culture. The first section of the course will examine Japan''s modern revolution in the Mejii Restoration, industrialization and modernization in the Mejii Period, and the development of Japanese colonialism. The second section of the course will focus on the Pacific War, the bombing of Hiroshima and Nagasaki, and the American occupation, with particular focus on the politics of gender and race. The third section of the course will look at Japan''s explosive postwar economic recovery and the consumer and popular culture it produced.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14637,2027,4085,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-252','<div class="desc"> <p>This course will focus on two foundational texts of Chinese civilization: The <em>Analects </em>and the <em>Zhuangzi</em>. The <em>Analects</em> is an ancient Chinese book composed of a collection of sayings attributed to Confucius and his disciples, and is traditionally regarded as one of the central texts of Confucianism. <em>Zhuangzi</em>, named for its traditional author, “Master Zhuang” (Zhuangzi), is one of the most important Daoist writings. When the <em>Analects</em> emphasizes that people should reconcile their desires via rituals, and fulfill moral and personal duties in order to ensure the welfare of the society, <em>Zhuangzi</em> promotes carefree wandering and following one’s own nature. By reading and comparing these two texts, this course will help students understand and grasp their central concerns, philosophies, and substantial influences on Chinese and East Asian thought and values throughout history. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14638,2027,3416,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-253','<div class="desc"> <p>The Tangand Song dynasties (618-1279) are known as Golden Ages in Chinese history, and also generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry. This course introduces the major literary genres and authors of the Tang and Song Dynasties, as well as literati culture emerging during this era. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. Students will discover the key role that literature played in Chinese court politics, empire building, and institutionalized learning; as well as how it shed light on gender and women’s status, war and knight-errantry, Daoist and Buddhist traditions, and more. The primary texts are translated in English, so knowledge of Chinese is not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14639,2027,3886,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-260','<div class="desc"> <p style="margin-left: 0; margin-right: 0">This course offers a survey of Japanese textual and visual culture from Japanâs early modern times (16<sup>th</sup> through late 19<sup>th</sup> centuries). We will learn about early modern Japanâs education systems, print history, and book culture, as well as forms of literacy that shaped Japanâs cultural and national identity. Through a wide range of popular literary and visual materials, we will analyze the modes of knowledge and information transmission and the roles they played in everyday life. To gain an intuitive experience of Japanese literary culture, we will carry out several hands-on activities such as rare books workshops and museum visits. Finally, we will turn to new forms of media that rose after the Meiji Restoration in 1868 and how they influenced modern Japanâs cultural identity. The course is given in English and offered in alternate years. No prior knowledge of East Asian languages is required to take this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14640,2027,4020,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-262','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course offers an overview of Japanese literary history from the eighth to the early twentieth century. We will read a variety of translated works from premodern to modern Japan, the social and religious background that shaped Japanese literatureâs forms and aesthetics, as well as the role of Japanese literature in constructing world views and national identity towards modern times. We will also analyze the textual sources in comparison with visual materials and objects to further explore the themes that connected premodern and modern cultural lives. Through secondary scholarship that examines these texts from multiple disciplines, we will explore different ways of critically engagement with Japanese literature. At the end of the semester, students will produce a free-form media presentation that analyzes one of the literary works covered in this course. The source texts are translated into English and knowledge of the Japanese language is not required.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14641,2027,3251,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-272','<div class="desc"> <p>This course examines the experience of Asian immigrants and their American-born descendants in the United States, from the mid-19th century to the present. We shall explore the history and cultural heritage of Asians in America and place them in the broader comparative contexts of multi-racial U.S. society and transnational migration networks. Topics include: the “push” and “pull” factors that led Asian immigrants to North America; problems they faced as they adapted to their new environment; the emergence and development of pan-Asian American identity; the politics of race, gender, sexuality, and transnationalism in Asian American life; the impact of globalization and transnational community/migration networks on Asian America; and the influence of the U.S. involvement in Asia on the Asian American experience throughout history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14642,2027,3252,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Inscribed Landscape: Nature and Travel in Chinese Literature</strong></p> <p class="MsoNormal">This course will lead students into the world of the Chinese cultural landscape through the lens of literature. We are going to conduct virtual travel to the mountains and waters in China by reading the masterpieces of Chinese landscape and travel writings. We will study the symbolic language that Chinese writers employed to describe their experiences of the natural landscape and their constructions of the cultural landscape. In a broader sense, the focus of this course stems from the interest in cultural geography in the Chinese context. The majority of the course content is on the pre-1800 period. In addition to analyzing literary texts through close reading, this course will introduce students to the ArcGIS system, a digital tool widely used in geohumanities research to view, edit, and analyze geographic data. Students will enjoy the opportunity to create a project using StoryMaps to illustrate their vision of a cultural place. Classes follow a lecture-discussion format. Students are expected to finish assigned readings in advance and actively participate in class discussions. No knowledge of the Chinese language or history is required (or assumed) for this literature-in-translation course.</p> <p><strong>Cultural Appreciation and/or Appropriation through the Lens of Asian Cinema</strong></p> <p>At its core, this course is an attempt to investigate, analyze, and ultimately comprehend the concept of cultural appropriation, in particular through an East Asian context. With a history of imperialism, be it Western or Japanese, in the 19th and 20th centuries, the topic of cultural appropriation is controversial and complicated, whether it is Katy Perry performing wearing a kimono at the American Music Awards or Chinese-Taiwanese-American chef Eddie Huang and his embrace (appropriation?) of African-American black culture. Prior to the actual viewing and analyzing of films, a comprehensive, albeit limited, survey of theoretical works will be conducted; works including but not limited to Richard Rogers’ “From Cultural Exchange to Transculturation: A Review and Reconceptualization of Cultural Appropriation,” Baris Buyukokutan’s “Toward a Theory of Cultural Appropriation,” and Lisa Nakamura’s concept of “identity tourism.” Some of the pairings to be analyzed are: William Shakespeare’s <em>King Lear</em> and Akira Kurosawa’s <em>Ran</em>; Clint Eastwood’s <em>Unforgiven </em>(1992) and Lee Sang-il’s Japanese Western <em>Yuzusazarumono </em>(2013).</p> <p><strong>Hear Now: Jean Luc Nancy and the Aesthetics of Community</strong></p> <p>In this class, we shall be examining the work of one the world’s most important living philosophers, Jean Luc Nancy. Special emphasis will be placed on the close relation Nancy seeks to draw between our so-called “private” aesthetic experiences—the painting that arrests us, the bar of melody that makes us tremble, the line of poetry that haunts us—and our sense of “being in community” (the sense, that is, that our supposedly singular existence is always already plural, is always already shared out with others). Beyond the reading of Nancy’s own works, we shall also be looking at the work of some of his most important predecessors on the question of art’s relation to the community (Kant, Hegel, Benjamin, Adorno), as well as the works of those thinkers who have engaged most directly with his ideas (Derrida, Agamben, Esposito), and those who have explicitly sought to oppose him (Ranciere, Badiou, and others). <em>Prerequisite: CSLC 200 and CSLC 283.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14643,2027,4086,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/asn-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14644,2027,3417,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/200/copy-of-asn-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14645,2027,4087,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/300/asn-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14646,2027,4088,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/300/asn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14647,2027,4021,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/300/copy-of-asn-331','<div class="desc"> <div> <p style="text-align: left; line-height: normal;">Korean fictional works concurrently provide avenues for historical remembrance and reimagination. While some novels from the 1900s depict Korea during the Japanese colonial era through a gritty and realistic lens, some fictional films reimagine that period to impart vengeance on the colonizers—a feat Koreans could not achieve in real life. Likewise, in the contemporary era, fiction is often used as a method not only to highlight but also to reimagine social norms. This course will explore modern and contemporary Korea through notable fictional works. More specifically, we will cover over a hundred years of Korean fiction from the 1900s to the contemporary era. We will explore how Korean fictional works depict notable historical moments in Korea, such as the Japanese colonial period, the Korean War, military dictatorship, and contemporary issues of gender, race, and class. By engaging with different types of fiction, including novels, films, and television dramas, we will examine Korean fiction’s chronology and critically analyze modern and contemporary Korean history as depicted in those works of fiction. All course instruction and assigned materials will be in English or have English subtitles.</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14648,2027,4089,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/300/copy-of-asn-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14649,2027,3875,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/400/asn-493','<div class="desc"> <p>"East Asian Society and History": Directed research for senior comps research paper.</p> <p>"Asian Societies and Cultures": Directed research for senior comps research paper.</p> <p>"East Asian Culture": Directed research for senior comps research paper.</p> <p>"Chinese language, literature, and culture": Directed research for senior comps research paper.</p> <p>"East Asian Art and Visual Culture": Directed research for senior comps research paper.</p> <p>"Asian American History and Literature": Directed research for senior comps research paper.</p> </div>','Instructor permission required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14650,2027,4090,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/400/asn-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14651,2027,3971,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/asn-asian-studies/400/asn-498','<div class="desc"> <div><p>Honors directed research in Asian Studies. Prerequisite: permission of department and instructor.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14652,2027,4091,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bich-biochemistry/300/bich-395','<div class="desc"> Topics vary semester to semester. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14653,2027,4092,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bich-biochemistry/300/bich-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14654,2027,24,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bich-biochemistry/400/bich-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Biochemistry majors; to be taken both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14655,2027,457,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bich-biochemistry/400/bich-499','<div class="desc"> <p>Independent study under the supervision of a faculty member. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14656,2027,25,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/100/bio-103','<div class="desc"> <p>Plants and People on a Changing Planet</p> <p>This class will cover basic plant biology concepts and how plants have shaped and continue to play a central role in human lives and societies. We will discuss topics including solving the challenges of food insecurity, urbanization, climate change, and exploitation of biofuels. Through hands-on activities, we will also explore uses of plants for pigments, food plant diversity, wood production in trees, and California native plants. This course is an inquiry-based introduction to biological science in a format that includes both classroom activities and fieldwork. Field trips will occur during class time.</p> <p>Coral Reefs: Molecules to Ecosystems</p> <p>This course is designed to examine the structures and functions of coral reefs. The course will integrate topics ranging from molecular to ecological topics to gain an appreciation for how biology functions at different scales. This course will explore a series of basic biological concepts using coral reefs as the focal point. Coral reefs are an excellent case study of how organisms interact with each other at multiple levels, from a molecular to an ecosystem level. Through reading, discussion, writing, and student-led exploration we will address topics such as: How are coral reefs being impacted by a changing environment at different levels (molecular to organismal)? What biological processes are critical to maintaining healthy coral reef ecosystems? How did the complex relationships among inhabitants of a coral reef evolve? Students will develop proficiency in skills needed for the practice of biology, critical reasoning and evaluation of scientific ideas and results. This course is an inquiry-based introduction to biological science through the lens of coral reefs.</p> <p>Urban Ecology</p> <p>Los Angeles is an urban ecosystem where people, nature, and the built environment interact. We will consider L.A., the second largest city in the U.S., as a case study of how organisms and the environment influence each other. Through reading, discussion, writing, gathering data, and exploration we will ask, what physical features define the Los Angeles environment? How have these changed over time, and what changes are likely to happen in the near future? What species of organisms (beyond palm trees, pets, rats, and cockroaches) inhabit this city? How does the physical environment affect urban species, and how do they, in turn, affect their environment? Students will develop proficiency in skills needed for the practice of biology, quantitative reasoning, and critical evaluation of scientific ideas and results. This course is an inquiry-based introduction to biological science in a format that includes both classroom activities and fieldwork. Field trips will occur during class time, with one required day-long field trip to be scheduled at the start of the semester.</p> <p>Ecological Enhancement and Restoration</p> <p>Biological, ecological, and social views regarding need, methods, and effects of restoration and enhancement of ecosystems. Recent events from California and the rest of the world are discussed, focusing on marine and terrestrial ecosystems, invasive species, over-harvesting, industrial impacts on the environment, and methods of mitigating or repairing damages. Examples of discussions include: methods of combating over-harvesting in the Pacific Ocean; natural and anthropogenic methods of recovering from forest fires; oil platforms functioning as artificial reefs to help endangered species thrive; also, how does a nuclear generating station affect a giant kelp forest, and what can be done to mitigate those damages?</p> <p>Public Health Biology</p> <p>This introductory course will offer an integrative biological perspective on public health issues, highlighting specific diseases of viral, bacterial, and environmental origin, as well as the influence of social and economic disparity. We will explore specific examples, such as rising antibiotic resistance, cholera and hepatitis outbreaks, cancer, and diabetes, to illustrate biological principles required to understand infectious and non-infectious diseases of public health importance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14657,2027,26,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/100/bio-105','<div class="desc"> <p>This course is designed for non-majors and will be an introductory survey of marine organisms and their environment. It will cover fishes, invertebrates, mammals, reptiles, and algae. Included will be an investigation of behavior, ecology, adaptations, and environmental relationships to humans. An emphasis will be placed on forms common to California. <em>Includes one three-hour lab period per week; field trips will be included during the laboratory period. (Labs may take longer than the scheduled laboratory period to accommodate field trips.)</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14658,2027,30,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/100/bio-110','<div class="desc"> <div><p>Intro Bio: Biodiversity, Ecology, and Evolution will explore the diversity of life on Earth and interactions between organisms from evolutionary and ecological perspectives with a focus on the interconnectedness of systems. These concepts will be studied at the level of the individual, population, ecosystem, and biome, and emphasis will be placed on how organisms, from distinct biological groups, meet environmental challenges such as: obtaining energy and nutrients, maintaining water and osmotic balances, reproducing, and adaptations for a changing climate. You will learn to recognize and frame hypotheses about biological organisms and phenomena that can be tested by acquiring and analyzing appropriate evidence; you will gain the ability to recognize bias and insufficient evidence. You will also learn to acquire, analyze, and evaluate biological data through observation and experimentation in the laboratory and in the field. Some of the topics we will cover include: biological diversity, biological classification schemes, the species concept, forces of evolution, adaptation, the relationship between biological structure and function, ecological niches and communities, global change and biological conservation, and extinction.</p></div> </div>',NULL,'BIO 110L Introductory Biology: Biodiversity, Ecology, and Evolution Lab ',NULL);
INSERT INTO course_descriptions VALUES(14659,2027,34,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/100/bio-130','<div class="desc"> <p>A concept-driven survey course designed to provide broad introduction to the biochemistry, physiology, and molecular biology of prokaryotic and eukaryotic cells. Topics include: structure/function; relationships of biological macromolecules; the roles of such molecules in cellular metabolism and membrane biology; molecular biology of DNA, RNA, and protein synthesis; the cell cycle; elementary genetics; and cellular communication. <em>Includes one three-hour laboratory per week. </em>Prerequisites may be taken concurrently with this course.</p> </div>','CHEM 120 , CHEM 130 or permission of instructor ','BIO 130L ',NULL);
INSERT INTO course_descriptions VALUES(14660,2027,2868,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/100/bio-198','<div class="desc"> <p>Complementing their Oxy Immersive Semester coursework for the California Environment and Conservation Corps, students in the program will engage in service-learning. Students will be matched with Southern California environmental organizations. The hours spent in service (which will be completed virtually) would be scaffolded with reflective reading and writing centered around concepts of environmental stewardship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14661,2027,3427,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/100/copy-of-bio-193','<div class="desc"> <div><p>Research in an area not otherwise included in the departmental curriculum. Students will be trained in methods of biological research. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14662,2027,4093,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-215','<div class="desc"> <p>Consideration of the physiological responses and adaptations of invertebrates to their environments, including the underlying physiological and biochemical mechanisms. A comparative approach emphasizing aquatic invertebrates, parasites, and symbionts, as well as structural and functional features. Students will be exposed to primary research literature and experimental design in ecological physiology. <em>Includes one three-hour laboratory per week.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14663,2027,460,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-221','<div class="desc"> <p>This course focuses on understanding the processes in a cell, at a molecular level, that transfer information from genetic information through the expression of functional proteins. Topics include: basic structure of DNA, RNA, and proteins; gene structure; chromosomal organization; genomic structure and organization; DNA replication; transcription, translation, and processing of gene products; molecular regulation of gene expression, mechanisms in prokaryotes and eukaryotes; regulatory and catalytic RNA, including siRNA and miRNA; and the techniques to study these processes. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 and CHEM 220 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14664,2027,36,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-224','<div class="desc"> <p>Intensive, concept-driven exploration of genetic information transfer between generations. Topics include Mendelian principles, allelic and genetic interactions at the phenotypic level, complex traits, genetic mapping, DNA repair and genome maintenance, principles of gene regulation, epigenetics, gene therapies, genome editing and bioethics of genetic technologies. Includes one three-hour laboratory session per week, plus one hour arranged. </p> </div>','BIO 130 ; and CHEM 120 or CHEM 130 ; or permission of instructor ','BIO 224L ',NULL);
INSERT INTO course_descriptions VALUES(14665,2027,1149,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-226','<div class="desc"> <p>A course designed to provide a thorough understanding of the intracellular processes of eukaryotic cells. The course will discuss topics including the molecular basis of cellular organization, structure, and function; cell motility; organelle biogenesis and function; cellular communication and signaling; and intracellular processes such as apoptosis and autophagy. <em>Includes one three-hour laboratory session per week, plus two hours arranged.</em></p> </div>','BIO 130 ','BIO 226L ',NULL);
INSERT INTO course_descriptions VALUES(14666,2027,813,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-240','<div class="desc"> <p>Physical and metabolic activities of cells and tissues, properties of the cellular environment, regulatory and homeostatic functions of organ systems. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 (may be taken concurrently) and BIO 105 , BIO 110 , or BIO 115 ','BIO 240L ',NULL);
INSERT INTO course_descriptions VALUES(14667,2027,462,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-250','<div class="desc"> <p>This course is a comprehensive introduction to the plant kingdom, emphasizing the ways in which organismal form and structure are shaped through evolutionary and ecological processes. The primary goal of the course is for students to learn how a major life form has adapted to physical factors, such as light and water, and to biological factors, such as fungi, insects, and vertebrates. Labs involve experimental analysis of fundamental processes, such as: water uptake, photosynthesis, and hormonal regulation, as well as hands-on investigation of the vegetative and reproductive adaptations of the plant kingdom. Independent lab projects and field trips are also key components of the course. <em>Includes one three hour laboratory session per week.</em></p> </div>','BIO 105 , BIO 110 , BIO 115 ','BIO 250L ',NULL);
INSERT INTO course_descriptions VALUES(14668,2027,38,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-260','<div class="desc"> <p>The goal of this course is to introduce marine ecosystems and the physical and biological attributes contributing to their organization. The course will focus on the nearshore marine environment of the Southern California Bight, referencing examples from comparable ecosystems. It will introduce basic physical attributes and the organisms of these dynamic ecosystems. Students will learn how to collect data, in both field and laboratory settings, database management, advanced database queries, conduct basic statistical analyses, test hypotheses, produce graphics, and write scientific papers. This course will serve to prepare students for focused upper division courses and independent research. Labs may take longer than the scheduled lab period to accommodate field trips. <em>Includes one three-hour laboratory session per week.</em></p> </div>','BIO 105 , BIO 110 , or BIO 115 ','BIO 260L ',NULL);
INSERT INTO course_descriptions VALUES(14669,2027,1049,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-268','<div class="desc"> <p>The application of statistical methods to the solution of biological problems. Focus will be on applied statistics (as opposed to mathematical statistics) to study variation in nature. This course will survey descriptive statistics, probability and probability distributions, and methods of hypothesis testing (e.g. analysis of variance, regression correlation, goodness of fit, as well as selected nonparametric procedures). <em>Course includes laboratory workshops sessions.</em></p> </div>','BIO 130 and BIO 105 , BIO 110 , or BIO 215 ','BIO 268A ',NULL);
INSERT INTO course_descriptions VALUES(14670,2027,464,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-270','<div class="desc"> <p>Ecology explores the interactions between organisms and their biotic and abiotic environments at a variety of spatial and temporal scales. Topics include: factors affecting organisms at the population, community, and ecosystem levels and the effect of human actions on natural systems. Practical aspects of studying ecology involve work in the laboratory, computer simulations and modeling, and field work. This course emphasizes the fundamentals of study, design sampling, field techniques, data analysis, and written and oral presentation of results. <em>Includes one three-hour laboratory per week and weekend field trips to be arranged.</em></p> </div>','BIO 105 , BIO 110 , or BIO 115 ','BIO 270L ',NULL);
INSERT INTO course_descriptions VALUES(14671,2027,1050,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-275','<div class="desc"> <p>Identification and classification of plants found in the various vegetational communities of Southern California, with emphasis on understanding their ecological and evolutionary affinities. Current methods of field sampling and systematic analysis will be employed. <em>Includes one three-hour laboratory per week and other field trips to be arranged.</em></p> </div>','BIO 105 , BIO 110 , or BIO 115 ','BIO 275L ',NULL);
INSERT INTO course_descriptions VALUES(14672,2027,40,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-280','<div class="desc"> <p>A detailed analysis of the causes and consequences of biological evolution. The focus, here, is on understanding basic evolutionary mechanisms with plant and animal examples used to illustrate and clarify the fundamentals of the evolutionary process. Classical and recent contributions to our understanding of evolutionary biology are examined, including: population genetics, theoretical models, geographical variation, speciation, biogeography, phylogeny, reconstruction, molecular evolution, macroevolution, and the evolution of Homo sapiens.</p> </div>','BIO 105 , BIO 110 , or BIO 115 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14673,2027,1002,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-290','<div class="desc"> <p>This two-unit course will offer students the opportunity to learn techniques of contemporary biology that are used in the laboratory and in the field. These may include: culture and handling of biological specimens, observational methods, imaging use of instrumentation to gather data, methods of data analysis, and identification of organisms. By the end of the semester, students will have been exposed to and gained practice in a diversity of techniques relevant to the practice of biological science. Graded on a credit/no credit basis only. May be repeated once for credit.</p> </div>',NULL,'BIO 103 (Urban Ecology) and BIO 198 ',NULL);
INSERT INTO course_descriptions VALUES(14674,2027,3967,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14675,2027,3034,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-295','<div class="desc"> <p>This one-unit course offers students the opportunity to learn about current research in the biological sciences. Students enrolled in the course will attend the weekly 1-hour seminar hosted by the Biology Department, which covers a broad range of biological research topics. Past speaker topics have included conservation biology and ecosystem restoration, climate change effects on marine ecosystems, evolution of social symbiosis, novel therapeutic approaches for drug resistant bacterial infections, evolution of flight, bioillustration, and scientific communication and education. Invited speakers from different institutions present their scientific work to students on a diversity of topics, techniques, and data analyses relevant to current biology research. This course provides students with an opportunity to observe how professional scientists communicate and translate their findings from biological studies to broad audiences.</p> <p>Graded on a CR/NC basis only. Course may be repeated once for credit. Open to sophomores and juniors only.</p> </div>','BIO 130 (may be taken concurrently) and BIO 105 , BIO 110 , or BIO 115 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14676,2027,4094,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-297','<div class="desc"> <p>Research in biology for students who do not have advanced competence in biology (see BIO 397). Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14677,2027,3328,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/200/bio-298','<div class="desc"> <p>The Huntington-Occidental Pre-med Program (HOPP) is a course that teaches pre-med students how physicians interact with and evaluate clinical populations by introducing students to medical interviewing and differential diagnoses and sharing real patient cases. It empowers students to reflect on the process of becoming a doctor by interacting with medical students, residents, and attending physicians, allowing students to make informed career decisions. Course includes supervised participation in the work of a hospital or other health-related clinic.</p> <p>Students must apply with the Office of Pre-Health Advising before enrolling in the course. Students also must complete Huntington Hospital training and OXY-HIPPA training once enrolled. Instructor permission required.</p> </div>','BIO 130 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14678,2027,41,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-310','<div class="desc"> <p>Introduction to the principles and practice of museology and the functioning of a research natural history museum. Emphasis will be on the development of the "museum conscience" and attendant curatorial skills, through extensive training as a curatorial assistant. Students will make use of the bird, mammal, and fish collections of the Moore Laboratory of Zoology (the world''s largest collections of Mexican birds and Southern California Rocky Reef fishes) and the Cosman Shell Collection at Occidental College. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14679,2027,893,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-320','<div class="desc"> <p>Animal development, with an emphasis on the molecular mechanisms that regulate cell fate, cell adhesion and motility, and the formation of different tissue types. Cell signaling pathways and gene regulatory mechanisms that control development, and are relevant to adult stem cell biology and cancer biology, are stressed throughout the course. The laboratory focuses on major invertebrate and vertebrate model organisms and both classical and molecular genetic approaches used to study animal development. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 and BIO 221 , BIO 224 , or BIO 226 ','BIO 320L ',NULL);
INSERT INTO course_descriptions VALUES(14680,2027,42,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-322','<div class="desc"> <p>Survey of the basic principles that power biological processes in all living organisms. Includes introduction to biochemical techniques, enzyme structure and function, intermediary metabolism, synthesis and degradation of biological macromolecules, information transfer, and a concept-driven integration of these subjects into a biological context. This course meets the Biochemistry requirements for most graduate and professional schools. <em>Includes one three-hour laboratory per week. </em>Not open to students who have successfully completed Biology 349.</p> </div>','BIO 130 and CHEM 220 ','BIO 322L ',NULL);
INSERT INTO course_descriptions VALUES(14681,2027,466,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-323','<div class="desc"> <p>An introduction to histology. Lectures present the structure and function of cells, tissues, and organs in healthy and diseased conditions. The laboratory introduces students to preparation of tissue for paraffin, plastic, and cryostat sectioning and examination by light and electron microscopy. Students work on projects of their own choice. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 130 , and BIO 105 or BIO 115 ','BIO 323L ',NULL);
INSERT INTO course_descriptions VALUES(14682,2027,468,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-325','<div class="desc"> <p>An introduction to the world of microbes, including viruses, archaea and bacteria, and their role in shaping and sustaining life on Earth. Emphases will be placed on structure, metabolism and bioenergetics, physiological and biochemical adaptations to unusual environments, phylogenetic analysis, biotechnology, microbial ecology, and biological interactions, including plant and animal symbioses. Laboratory exercises will include an exploration of microscopy, cultivation, biochemical techniques, and molecular tools for studying microorganisms. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 221 , BIO 224 , BIO 226 , BIO 260 , BIO 270 or BIO 275 ','BIO 325L ',NULL);
INSERT INTO course_descriptions VALUES(14683,2027,44,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-330','<div class="desc"> <p>Introduction to current concepts of immunology, including immunoglobulin structure and function, T cells and B cells, cell-cell cooperation in the immune response, and the role of the major histocompatibility complex. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221 , BIO 224 , BIO 226 ','BIO 330L',NULL);
INSERT INTO course_descriptions VALUES(14684,2027,815,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-333','<div class="desc"> <p>Emphasis on cell biology and physiology of neurons. Development and plasticity of the nervous system in invertebrates and vertebrates. Overview of selected central nervous system structures and their function and the cellular and molecular basis of selected nervous system diseases and disorders. <em>Includes one three-hour laboratory per week, plus 1-2 hours arranged.</em></p> </div>','BIO 130 ; and BIO 226 or BIO 240 ','BIO 333L',NULL);
INSERT INTO course_descriptions VALUES(14685,2027,1367,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-336','<div class="desc"> <p>This course will examine interactions between the human host and infectious microbial pathogens, including bacteria, parasites, viruses, and fungi. Emphases will be placed on mechanisms of microbial defense (virulence factors), immune evasion and adaptation strategies, as well as the molecular and cellular mechanisms of the innate (immediate) response of the host in both immune and non-immune cells. Laboratory includes techniques used in clinical microbiology labs, including culture and identification techniques, as well as cell biology techniques. <em>Includes one three-hour laboratory per week, plus two hours arranged.</em></p> </div>','BIO 221 , BIO 224 , BIO 226 ','BIO 336L ',NULL);
INSERT INTO course_descriptions VALUES(14686,2027,470,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-340','<div class="desc"> <p>Dynamic physiological properties will be examined in single cells, tissues, and whole organisms. Emphasis will be placed on sensory physiology and neuroethology (study of the neural basis of natural animal behaviors). Laboratories will utilize advanced recording techniques, including microelectrodes, isometric tension measurements, semi-intact preparations, and modern electronics.</p> </div>','BIO 226 , BIO 240 , BIO 333 , CHEM 301 , COGS 250 , or PSYC 322 ','BIO 340L',NULL);
INSERT INTO course_descriptions VALUES(14687,2027,2870,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-345','<div class="desc"> <p>This course will survey the diversity among major classes of viruses in genomic material, replication, and host cell interaction. We will discuss aspects of antiviral strategies by the host immune response as well as ongoing research in medical antiviral therapies. In addition, we will cover various ways that viruses have been harnessed as useful tools in the laboratory as sources of unique enzymes, vectors for introducing exogenous material into cells, and in various other applications such as phage display.</p> </div>','BIO 130 , and BIO 221 , BIO 224 , or BIO 226 ','BIO345L ',NULL);
INSERT INTO course_descriptions VALUES(14688,2027,1003,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-349','<div class="desc"> <p>This course explores the roles of the essential biological macromolecules, focusing on proteins, while covering lipids, carbohydrates, and nucleic acids. Topics include the structure and function of these macromolecules, as well as an investigation of the biochemical methods used to study them. Also included are topics covering proteomics, DNA-based information technologies, biosignaling, and an introduction to enzyme kinetics. This course is the first in a two-semester sequence of Biochemistry classes (with CHEM 350) that is required for Biochemistry majors. For a one semester Biochemistry class, see BIO 322. Not open to students who have successfully completed BIO 322.</p> </div>','BIO 130 and CHEM 220 ','BIO 349L ',NULL);
INSERT INTO course_descriptions VALUES(14689,2027,895,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-350','<div class="desc"> <p>Symbioses are intimate associations involving two or more species. Symbiotic associations are widespread in nature and we can expect to find them in every type of ecological niche. This course will cover the diversity of symbiotic interactions that exist between both microbes and fungi and various eukaryotic hosts, including plants, animals, and protists, as well as other microorganisms. Topics will range from molecular to ecological, including the specific molecular communication between partners, the evolution of unusual host structures, novel physiological and biochemical capabilities, and the unique ecological advantages that many symbioses confer. This course will also include writing, presenting, and reviewing published work on various symbioses. Includes one three-hour laboratory per week.</p> </div>','BIO 130 , and BIO 105 , BIO 110 , or BIO 215 ','BIO 350L ',NULL);
INSERT INTO course_descriptions VALUES(14690,2027,897,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-356','<div class="desc"> <p>The biology of marine fishes begins with a study of the phylogenetic evolution of fishes. Within this context, it discusses the physiology, ecology, and behavior of marine fishes, utilizing examples from our local fauna. Advanced methods of studying marine fishes will be covered, with an emphasis on field research in which the class will visit various marine habitats throughout Southern California. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 240 , BIO 250 , BIO 260 , BIO 268 , BIO 270 , BIO 275 , or BIO 280 ','BIO 356L ',NULL);
INSERT INTO course_descriptions VALUES(14691,2027,1054,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-360','<div class="desc"> <p>Avian Biology is the study of birds, with particular emphasis on identification, natural history, and evolution of birds local to Southern California.</p> </div>','BIO 130 , and BIO 105 , BIO 110 , or BIO 115 ','BIO 360L ',NULL);
INSERT INTO course_descriptions VALUES(14692,2027,4095,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-363','<div class="desc"> <div><p>This course will cover the fundamentals of marine ecology, with a specific focus on the functional roles that organisms play in driving ecological processes within marine and estuarine ecosystems. Course content will focus on the ecological, biological, and environmental processes that drive patterns across marine populations, communities and ecosystems including productivity, behavior, population dynamics, nutrient cycling, and community structure. An emphasis will be placed on understanding how anthropogenic changes impact different levels of marine organization and ecosystem function. The course may include field trips or excursions outside of the regular class times to allow for experiential learning in the local marine environments.</p></div> </div>','Any 100-level Biology course (except BIO 103), AND either BIO 260 or BIO 270 . ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14693,2027,472,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-369','<div class="desc"> <p>Biological oceanography will focus on the biology of the open ocean, with emphasis placed on relating parameters of the physical-chemical ocean to the distribution and abundance of marine organisms. We will focus on understanding the physical and biological processes of the Southern California marine area using field and laboratory techniques. Using examples from our local ecosystem, students will explore the intricacies of macro-scale oceanographic processes. <em>Includes one three-hour laboratory per week. Labs may take longer than the scheduled laboratory period to accommodate field trips.</em></p> </div>','BIO 260 or BIO 270 ','BIO 369L ',NULL);
INSERT INTO course_descriptions VALUES(14694,2027,1322,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-370','<div class="desc"> <p>This course provides an overview of insect ecology from an evolutionary perspective focusing on factors influencing the diversity, distribution, and abundance of insects in natural and managed ecosystems. We will investigate fundamental mechanisms underlying interactions between insects and their abiotic and biotic environment at the molecular, cellular, organismal, population, community, and ecosystem levels. Current trends in research will be explored and the role of insects as model systems in the development of general ecological and evolutionary principles will be highlighted. Applications include lessons for/from pest management, biological control, vector control, and biodiversity management. In lab, students will conduct field and molecular ecology research, including the design, implementation, data analysis, and presentation of research projects. Includes one three-hour laboratory per week.</p> </div>','BIO 260 , BIO 270 , BIO 275 , or BIO 280 ','BIO 370L ',NULL);
INSERT INTO course_descriptions VALUES(14695,2027,3357,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-372','<div class="desc"> <div><div><p>This course explores the causes of global change and the consequences for organisms, ecosystems, and the Earth. We will examine past, present, and projected future trends and give special attention to the role of human activity in global change. Topics will include land use, energy use, climate change, biodiversity loss, biotic interchange, and pollution, as well as responses, hurdles, and solutions. Includes one three-hour laboratory per week.</p></div></div> </div>','BIO 250 , BIO 270 , or BIO 275 ','BIO 372L ',NULL);
INSERT INTO course_descriptions VALUES(14696,2027,2323,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-373','<div class="desc"> <p>This course is an opportunity for students to learn more advanced methodologies in computational biology. By examining a variety of biological questions that are often addressed with computational pipelines, modeling, or simulation, students will get in-depth experience with important computational concepts (including: abstraction, algorithms, automation, logic, and problem solving). This includes the study of complex biological systems, such as projecting biological responses to climate or ecosystem change, quantifying spatial biodiversity hotspots, evaluating time series data for populations, and computing evolutionary parameters from genomic datasets. Students will also get experience with computer programming in the R statistical language and Python. Additional biological topics may include: spatial ecology, including species distribution modeling, community assemblage and dissimilarity matrices, population simulations, classification with machine learning, and bioinformatics with genomic data. Course includes laboratory workshops sessions.<strong></strong></p> </div>','BIO 268 , COGS 255 , COMP 131 , GEO 255 , MATH 150 , or PSYC 201 ','BIO 373L ',NULL);
INSERT INTO course_descriptions VALUES(14697,2027,46,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-378','<div class="desc"> <p>Emphasizes the evolutionary approach to the study of animal behavior, drawing broadly from the various disciplines within biology concerned with the factors that determine which organisms survive and reproduce. The course material will be divided into four broad categories: sensory capabilities, feeding patterns, spacing patterns, and reproduction. For each topic, theory and application will be presented. Students will analyze research papers and lead discussions on an aspect of each major topic. The laboratory portion of the course will focus on observational and experimental approaches to studying animal behavior in the lab and in the field. We will make use of local resources, such as zoos, aquaria, wildlife conservation areas, veterinarians, and animal rehabilitation facilities. An independent research project is required. This course is designed for Biology majors, although it would be appropriate for students from other majors. <em>Includes one three-hour laboratory per week and weekend field trips to be announced.</em></p> </div>','BIO 105 , BIO 110 , BIO 115, or BIO 130 ','BIO 378L ',NULL);
INSERT INTO course_descriptions VALUES(14698,2027,899,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-380','<div class="desc"> <p>An investigation of physiological processes in plants, including photosynthesis; nutrient uptake and water relations and how they are affected by environmental conditions; and interactions with other organisms, including insects, vertebrates, and fungi. The emphasis will be on how to quantify and predict plant physiological responses to the particular ecological pressures of Southern California. Classroom discussions and presentations will focus on papers from the current scientific literature. <em>Includes one three-hour laboratory per week.</em></p> </div>','BIO 250 ','BIO 380L ',NULL);
INSERT INTO course_descriptions VALUES(14699,2027,2375,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-390','<div class="desc"> <p>This seminar course will teach students skills needed to read and critically analyze original journal articles. Some lectures will be given, but the bulk of the course will consist of student-led discussions and analysis of scientific papers. Students will improve their communication skills by discussing papers and leading discussions, by writing a research paper and peer-editing, and by preparing oral presentations as an aid for leading discussions. May be taken more than once for credit as the topics will differ each semester, but can only be used to fulfill one of the requirements for the Biology major. Cannot be used to fill the Biology requirement of the Biochemistry major.</p> <p><strong>Insect Ecology</strong></p> <p>This course provides an overview of insect ecology from an evolutionary perspective focusing on factors influencing the diversity, distribution, and abundance of insects in natural and managed ecosystems. We will investigate fundamental mechanisms underlying interactions between insects and their abiotic and biotic environment at the molecular, cellular, organismal, population, community, and ecosystem levels. Current trends in ecological entomology research will be explored and the role of insects as model systems in the development of general ecological and evolutionary principles will be highlighted. Applications include lessons for/from pest management, biological control, vector control, and biodiversity management.</p> </div>','One 200- or 300-level Biology course. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14700,2027,2863,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-393','<div class="desc"> <div><p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p></div> </div>','BIO 293 is the intermediate level for research ahead of this advanced research experience. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14701,2027,474,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/bio-397','<div class="desc"> <p>Directed research with individual faculty members for students with advanced competency to study in an area not otherwise included in the departmental curriculum. In addition to topics that may be studied on the Occidental campus, courses offered at the marine station of the Wrigley Institute for Environmental Studies may be taken for credit under this course number. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14702,2027,1106,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/300/copy-of-bio-326','<div class="desc"> <p>This course focuses on how to build the tree of life from DNA data, from how DNA evolves to how DNA mutations are analyzed to create phylogenies. Topics covered include the theory behind molecular evolution and various analytical methods, as well as its application to creating evolutionary histories of genes and organisms. </p> </div>','BIO 280 ','BIO 326L',NULL);
INSERT INTO course_descriptions VALUES(14703,2027,49,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/400/bio-490','<div class="desc"> <p>Topics of these seminars will be announced at Spring pre-registration. Each senior must pass one seminar for the Comprehensive requirement. Each seminar meets two hours per week with extensive reading, discussion, and a major oral presentation by each student. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14704,2027,4096,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/400/bio-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14705,2027,476,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/500/bio-501','<div class="desc"> <p>Supervised investigation by properly qualified graduate students working toward a Master''s degree. Students may not register for more than two courses of Research during any semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14706,2027,50,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/500/bio-590','<div class="desc"> <p>Preparation of the Master''s thesis in consultation with the advisor and committee members. Department approval required.</p> </div>','At least two courses of BIO 501 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14707,2027,4097,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/500/bio-595','<div class="desc"> <p>This special-topics seminar course will be offered as needed to graduate students in the Biology department. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14708,2027,4098,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/500/bio-597','<div class="desc"> <p>Directed research, with individual faculty members, for students with advanced competency to study in an area not otherwise included in the departmental curriculum. In addition to topics that may be studied on the Occidental campus, courses offered at the marine station of the Wrigley Institute for Environmental Studies may be taken for credit under this course number. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14709,2027,479,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bio-biology/500/bio-599','<div class="desc"> <p>Continuing work on Master''s thesis. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14710,2027,2872,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/100/blst-101','<div class="desc"> <p>This course introduces students to the history and methods of the discipline known as Black Studies. Readings will focus on the origins and institutionalization of Black Studies as a field of academic inquiry. Students will learn about the philosophical and political debates that laid the intellectual foundation for Black Studies and examine the social movements that resulted in the field of Black Studies in the present. Topics include the foundational academic work of W.E.B. DuBois, the San Francisco State student revolt of 1968, Mellon and Ford Foundation funding of programs and departments, and the recent student demands at University of Missouri and elsewhere. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14711,2027,3435,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/100/blst-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14712,2027,4099,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/100/blst-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14713,2027,4100,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/100/blst-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14714,2027,4049,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/100/copy-of-blst-180','<div class="desc"> <p>This course offers an introduction to the modern history of Africa from the 15th century to the end of the Cold War, engaging a particular focus on the vital role African societies have played in the making of the modern world. Rather than presenting Africa as peripheral to global history and conceptions of modernity, this course emphasizes the centrality of Africa and African societies in the major political, economic and social transformations which shape and define our modern world.</p> <p>Students will examine the evolving relationship between Africa and Europe within the broader context of the global rise of mercantile capitalism, the European imperial project of the 15th - 19th centuries and the geopolitical context of the Cold War struggle for influence and resources in Africa. The course is organized around four key historical periods: the rise of mercantile capitalism and the Trans-Atlantic Slave Trade; the 19th century colonial encounter inaugurated at the Berlin Conference of 1884-85; African resistance movements and solidarity with global anti-colonial struggles; and African independence and global decolonization.</p> <p>Students will explore major themes in African history including: sovereignty and dependency, development and underdevelopment, nationalism and resistance, and pan-Africanism and black internationalism. These will be analyzed within relation to broader global forces including neocolonialism, monopoly capitalism and globalization.</p> <p>By interrogating hegemonic narratives that portray Africa as a passive recipient of external forces, students will assess the diverse ways in which Africans have exercised agency and contributed to the global processes that define modernity. The course concludes with an assessment of Africa’s role in the emerging global order.</p> <p>History Department Survey Requirement Met: Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14715,2027,4101,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-201','<div class="desc"> <p>This course focuses on the rhetoric of Black protest and social movements as we examine Black rhetorics as modes of resistance to racist, colonialist, patriarchal, and other forms of oppressive discourse and action. We will consider a range of rhetorical forms including abolitionist rhetoric and the Black Jeremiad in American culture; Civil Rights era rhetorics and the Black Panther Movement; anti-imperialist Black proletariat rhetorics of protest in the West Indies and Caribbean societies; and rhetorics of resistance in the contemporary Black Lives Matter movement. This course will provide a rhetorical understanding of the approaches and strategies emerging from and responding to systems of cultural and social oppression, and thus will offer a counterpoint to Eurocentric rhetorical traditions. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14716,2027,2844,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of Africans in North America, to the quest for abolition and freedom in the nineteenth century, to the modern freedom struggle of the mid-twentieth century. With our focus on pivotal demographic, cultural, and political developments within Black American communities across the United States, we will explore key themes and watershed moments in the African American experience. By analyzing the dynamics of African American history in this way, we will see how deeply Black freedom fighters, cultural innovators and institution-builders shaped the culture and politics of the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14717,2027,3276,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-208','<div class="desc"> <p>This interdisciplinary course examines the migration of six million African Americans who left the rural South to move to cities in the North, Midwest and West in the first half of the twentieth century. Beginning with the âFirst Great Migrationâ of 1910-1930 and continuing through the âSecond Great Migrationâ of the 1940s through the 1960s, we will explore the ways that this unprecedented demographic shift laid the groundwork for the civil rights movement, the quest for Black power, and the ongoing quest for social justice. Throughout the course, we will remain attentive to the way that Black migrants created and nurtured the new forms of music, art, and ways of being that ultimately transformed American culture. By analyzing the dynamics of African American history in this way, we will better understand the relationship between the history and culture of Black Americans and the culture and politics of the United States. </p> <p>This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14718,2027,4430,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-210','<div class="desc"> This course introduces students to major issues in Black American history from the Reconstruction era and the rise of Jim Crow, to the Great Migration and the twentieth-century Black freedom struggle. Focusing on key demographic, cultural, and political developments within Black American communities, the course explores the activities and impact of the Black intellectuals, artists, activists, and trailblazers who transformed the culture and politics of the modern United States. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14719,2027,4002,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-212','<div class="desc"> From rubber to cobalt, the wealth of the Democratic Republic of the Congo (DRC) continues to power global industry. At the expense of the lives and dignity of millions of Congolese under the brutal rule of King Leopold, the Congo produced the rubber to power the First Industrial Revolution. Nearly five generations later, the violent extraction processes continue in order to fuel the Green Energy Revolution.<br/> <br/> Today, the Congo possesses an estimated $24 trillion dollars in coveted natural resources yet 75% percent of its population lives on less than $2 a day. Owing to its resource wealth, the country remains a perennial outpost of natural resource extraction to the western world, locked in the colonial logic of plunder that many suppose the world has left behind. The Congo (along with references to a few other countries in central Africa) will offer students a test case for a deep analysis of Africa''s pivotal role in the Green Energy Revolution. Through reading historical scholarship and viewing documentaries, this course aims to develop student awareness of how advancements in information technology, artificial intelligence and a renewable energy economy are driving the “New Scramble for Africa.” At the same time, this "scramble" complicates mainstream assumptions about the end of colonization, modern restrictions on forced labor, and technology'' role in expanding democracy. Students interested in environmentalism, the history of technology, political science, diplomacy and world affairs will especially benefit from this course. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14720,2027,3263,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-218','<div class="desc"> <p>Over fifty years ago, the first person in the U.S. hired to coordinate a Black Studies program, Nathan Hare (1970), published an essay titled, ‘‘Black Ecology,’’ in which he argued that it was imperative that we come to ‘‘understand how both the physical and social environments of blacks and whites have increasingly evolved as contrast.’’ Since then, many scholars from across the social sciences and humanities have contributed to this endeavor. This emergent field of Black ecological thought is important because it provides insight about race and the environment from the perspective of Black study. In this survey course, we will study a range of black ecological thinkers and the concepts that they offer for understanding contemporary environmental issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14721,2027,3333,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-230','<div class="desc"> <p>In this course, we will read and study the creative, intellectual and political offerings of those who identify as Black British cultural producers. In doing so, we will consider how Black British peoples simultaneously struggled to belong to what we call Great Britain while also challenging the ongoing structures of empire and colonialism that are embedded within British histories and institutions. We will explore works by Jay Bernard, Leonora Brito, Isaac Julien, Steve McQueen, Zadie Smith, Luke Sutherland and others. Students will be asked to think critically about the overlapping and at times contradictory experiences of Black peoples in Scotland, England and Wales and their historical and contemporary arguments on topics ranging from abolition to multiculturalism. In doing so, we undertake the serious work of thinking through and theorizing blackness, Black sociality and Black life outside of solely U.S.-centered perspectives. Assignments will include both informal and formal written components.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14722,2027,4102,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-247','<div class="desc"> Sport has played a profound role in Black American history. An important venue for leisure, entertainment, and cultural expression in local Black communities, the sporting world has also provided a platform for some athletes to publicize and further campaigns for freedom and justice. Subject to intense media scrutiny (especially when they have broken barriers or charted new territory in sports), Black athletes have often been discussed in terms that tell us as much about the political, gender, class, and racial dynamics of a given moment as they do about an individual athlete’s performance on the field or in the arena. With this in mind, this class reexamines twentieth-century African American history by placing the experiences of Black athletes at the center of the story. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14723,2027,2611,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-256','<div class="desc"> <p>This course is an interdisciplinary exploration of African American women''s protest culture. From iconic figures like Sojourner Truth and Ida B. Wells, to trailblazers like Maria Stewart and Shirley Chisholm, to countless anonymous enslaved women and labor activists, to the cofounders of #BlackLivesMatter, women of African descent have been instrumental to campaigns for freedom and justice in the United States. Using speeches, memoirs, interviews, biographies and scholarly monographs, this course will interrogate this legacy. By moving African American women from the margins to the center of our analysis of African American protest culture, we will gain a better understanding of black women''s varied roles as agents of change in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14724,2027,3334,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-263','<div class="desc"> <p>W.E.B. (William Edward Burghardt) Du Bois, was a prolific scholar, writer, and social/political analyst and organizer. Over the course of his lifetime, Du Bois wrote over 2000 bibliographical entries, across a range of genres, including: research monographs, plays, pamphlets, autobiography and biography, history, novels, poems, and popular press articles. At the same time, Du Bois utilized multiple methods, forms of data and evidence, and literary styles within and across texts. Nevertheless, in the domain of social science, and sociology more specifically, his work was intentionally marginalized. Yet while Du Bois was made a minor figure in American social science, he was a primary progenitor of the transdisciplinary field of Black, African American, or Africana studies and thus played a foundational role in circumventing the racial-colonial order of knowledge by attending to Black life and sociality. In this course, we will study the social theory of Du Bois by reading texts from across his vast corpus—from his more formally social scientific writing and data visualizations to his creative projects like poetry and short stories. For the final project of the course, students will deploy a Du Boisian approach to social theory and analysis using more expressive forms (such as illustration, painting, film and video, poetry, music, photography, data visualization, short stories, or lyrical essays).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14725,2027,2613,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-268','<div class="desc"> <p>This course uses notions about beauty and the female body to interrogate the complex relationship between gender ideals and the politics of race in the United States. Beginning in the 19th century and continuing to the present, we will examine the ways that advertisers, pageant directors, beauty culturists, activists, teenagers and entertainers have shaped and redefined standards of beauty for American women at key moments in U.S. history. We will analyze these ever-shifting racialized standards of beauty in relation to American demographic, economic, and political developments, such as the rise of Jim Crow, the emergence of the New Woman, and the black power movement. We will be particularly attentive to the ways that black women have challenged dominant beauty scripts by defining their own set of beauty ideals, developing oppositional viewing strategies, and using fashion and the beauty culture industry as a springboard for political activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14726,2027,3977,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-293','<div class="desc"> <div><p>Directed Research gives students a chance to research materials not otherwise covered in the Department''s curriculum.</p><p><br/>Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14727,2027,4103,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Race, Archive, Performance</strong></p> <p>What is the relationship between race, archive and performance? Why and how does the/an archive matter to racial formations, intimacies, kinships? Why and how does performance matter to the study of the/an archive? What do we mean, in fact, when we invoke the/an archive? When we invoke a performance? This course is an exploration of the intersections between Black Studies and Performance Studies as disciplines that are inextricably bound up in questions on the/an archive, and how, in turn, our understanding of the/an archive as singular and stagnant is disrupted by Black Studies and Performance Studies. Students will be asked to read an array of texts, including primary archival materials, dramatic plays, visual texts and performance art, and will be introduced to preliminary steps in archival methods.</p> <p>Final projects may entail collaboration with Occidental College Library and its Special Collections and College Archives.</p> <p>Fulfills Expressive Forms or Politics and Theory Requirement.</p> <br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14728,2027,4104,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/blst-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14729,2027,4105,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/copy-of-blst-224','<div class="desc"> <div><p>In this course, students will read both select works by James Baldwin and that of some of his nearest interlocutors, including, but not limited to, Richard Wright, Chester Himes, Lorraine Hansberry and Toni Morrison. While it is critical to consider the breadth of his creative output that spanned decades, it is also important to remember that Baldwin was always writing alongside, to and sometimes in conflict with his contemporaries. Too, our class will ask students to think with Baldwin as he complicates the definitions and positions of blackness as he travels to and from various locations in the United States and Europe. In putting Baldwin in conversation with fellow writers and cultural producers, in following him from New York City to Paris and beyond, in situating him as a writer, an intellectual, an activist and a holder of Black queer knowledges, our course will aim to appreciate the fullness of Baldwin''s interventions into the discourses on structural power, and why his work continues to resonate today. </p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14730,2027,2609,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/200/copy-of-blst-240','<div class="desc"> <p>From demanding change to pushing for revolution, Black women have long been at the forefront of protesting for social justice. At the same time, however, their intellectual and political contributions and frameworks have often been ignored or co-opted by others. In this course, we will engage with the myriad ways in which Black women write toward a different kind of world, including creative writing, academic essays and talks, films and performances. Through exploring cultural producers who write from various national/international/translational positions and identities, we will locate African American history and literature within a larger Black diasporic history and literature to understand the global nature of Black womenâs writing. Topics will include, but are not limited to, violence against women, access to education and reproductive justice, the linkages between racism and capitalism, self-representation and abolition politics. By taking seriously the contributions of Black women cultural producers, we will also undertake the work of figuring out the definitions behind the words that make up the title of our course: how do our cultural producers define Black? How do they define the identity position of âwomenâ? What is the importance of writing, of text? And finally, how do they conceptualize and define social justice? Students will be asked to produce both informal and formal writing for the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14731,2027,3277,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-315','<div class="desc"> <p>Black Feminist Movements is an upper-division course wherein we interrogate our conceptualizations of “Black,” “feminist,” “Black feminist” and “movements.” What, or who, do we mean when we say “Black,” “feminist” and “Black feminist”? What do we mean when we invoke “movements”? Why is movement – literal and figurative – central to our understanding of blackness? What might it mean for blackness – Black peoples, Black communities, Black intellectual, political and cultural traditions – to move across land and sea, through space and time and on page, stage and screen? By reading expansively across disciplines, our course affirms that Black feminists have long been at the forefront of revolutionary practices of radically re-imagining what our world can be. We will engage with cultural producers from the Black diaspora (including, but not limited to: the United States, the Caribbean and the United Kingdom) working within critical ethnic studies, literary analysis, queer of color critique and performance studies, among others, and take seriously what they share in regards to prison abolition, the linkages between racism and capitalism, Black trans activism and other critical issues that demand our attention and action. We will locate these intersectional conversations within Black diasporic contexts – the literary, theoretical, political and cultural – as we seek potential answers to the questions posed above. Students will be asked to complete a research paper at the end of the term.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14732,2027,3278,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-318','<div class="desc"> <p>Saidiya Hartman (2019) conveys the social significance of waywardness for Black life: “Waywardness is an ongoing exploration of <em>what might be;</em> it is an improvisation with the terms of social existence, when the terms have already been dictated, when there is little room to breathe, when you have been sentenced to a life of servitude, when the house of bondage looms in whatever direction you move.” In this course, we will study waywardness, fugitivity, and the anarchism of Blackness as integral concepts for understanding how Black people have navigated the treacherous terrain of slavery and its afterlife. Through historical and contemporary case studies, discussion, and engagement with a range of thinkers, including, but not limited to, Saidiya Hartman, Lucy Parsons, Zoé Samudzi, William C. Anderson, Lorenzo Kom’boa Ervin, and Fred Moten, students will explore how anarchism (broadly defined) is a critical resource for Black life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14733,2027,3314,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-329','<div class="desc"> <p>Black queer thought are the knowledges, embodied and otherwise, that both enact critique of and imagine possibilities against the demands of heteronormativity, white supremacy, patriarchy and capitalism. In this course, we will engage with the multiple forms of text produced by those who may – or may uncomfortably – identify as Black and queer. By doing so, we will explore how the cultural producers in question complicate and elaborate upon the sometimes static and often U.S.-centered definitions we hold for “Black” and “queer,” challenging us to instead conceptualize these as dynamic and shifting positions rather than stable identity categories. Texts will be drawn from the works of James Baldwin, Ashon Crawley, Jackie Kay, Kara Keeling and others. This class thus situates students to join in on ongoing critical conversations within Black Studies, Queer of Color Critique, Performance Studies and American Studies. Assignments will include both informal and formal written components, and students will be asked to produce a final research paper. This class fulfills the second-stage writing requirement for the Black Studies major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14734,2027,3446,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-343','<div class="desc"> <p>In this project-based course, we will focus on Black ecological or environmental experiences and perspectives in Los Angeles and beyond. We will explore the theoretical and methodological tools and big ideas of the nascent field of Black Ecology through reading and discussing key texts. However, our ultimate aim is to share what we learn with as wide an audience we can muster using various digital technologies. Thus, this course is designed as a collaborative, interdisciplinary research collaboratory rooted in the tradition of W.E.B. Du Bois who operated a sociological research lab focused on Black life in America when he was a professor at Atlanta University between 1895-1924. Each iteration of this course will focus on a different project related to Black ecologies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14735,2027,2875,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-346','<div class="desc"> This course explores literary representations of slavery, civil war, social reconstruction, and political backlash in 19th century America. Along the way, students will address several questions: How does literature represent demands for social change that transgress the law, like the freed persons escaping slavery? How to distinguish fugitives fighting for freedom from unprincipled outlaws? Is emancipation a single act, legal declaration or a more complicated process? And for whom? Finally, how do we grapple with the backlash to political change? By focusing on the 19th century, we can rethink how African Americans found political agency generations before the most familiar events from the Civil Rights era. Most of all, this course allows students to read literature alongside historical documents, so they can see firsthand how debates over freedom evolved in the 19th century. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14736,2027,3322,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-360','<div class="desc"> <p>In her 1993 lecture for accepting the Nobel Prize in Literature, Toni Morrison says, “[s]he is convinced that when language dies, out of carelessness, disuse, indifference and absence of esteem, or killed by fiat, not only she herself, but all users and makers are accountable for its demise.” How does language die? What does it mean to be careless with language, to not use it, to be indifferent to it and rob it of its esteem? What does it mean to kill or stifle language by official decree? In our seminar on Toni Morrison, we will engage with the writings of one of the most preeminent writers and critical thinkers in literature (US-based and otherwise) in order to examine the powerful and provocative ways in which she asked and answered these questions before her passing on 05 August, 2019. We will situate her as a cultural critic, one who produced novels, short stories, essays and speeches and in doing so, informed the frameworks of American Literature, Black Feminist Theory, American Studies and Critical Race Studies, among other fields. Thus, we will collectively unpack the ways in which Morrison’s writings have guided, contested and informed American cultural and literary production in the 20th and 21st centuries. Students will be asked to complete a research paper at the end of the term. This course meets the second-stage writing requirement for Black Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14737,2027,4106,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-367','<div class="desc"> The United States maintained a complicated and contradictory set of customs and laws prohibiting interracial sex and marriage until well into the twentieth century. This course illuminates this hidden history by examining the stories of those Americans who established relationships across the color line despite these proscriptions. Focusing on a series of case studies and groundbreaking court cases involving people of African descent (including the case of Elizabeth Key, Perez v. Sharp, and Loving v. Virginia), the class asks, what happens when private relationships become politicized? What roles have ideas about interracial intimacy played in defining and redefining the meaning of “race” in America? How have ordinary people used the law to advocate for their own relationships and families? Ultimately, we will see how these deeply personal and private histories helped to shape the culture of the nation. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14738,2027,2615,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-376','<div class="desc"> <p>This interdisciplinary seminar explores the modern uses and abuses of African American history by focusing on the public memory of slavery and emancipation in the United States. Analyzing a range of fiction, film, advertisements, tourist sites, and public monuments, we will interrogate and assess the ways that popular representations of slavery, the Civil War, and Reconstruction were shaped by (and in turn, shaped) several of the key cultural developments and social and political movements of the 20th and 21st centuries. During the second half of the semester, students will complete a research paper on a topic related to the themes of the course. This course satisfies the second-stage writing requirement for the Black Studies major.</p> </div>','One BLST course, or fulfillment of the US Diversity Core requirement ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14739,2027,2782,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. Major requirement met: Group III/IV.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14740,2027,3930,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-381','<div class="desc"> <div><p>The terms "racial capitalism," "Black Marxism" and "Black Radicalism/Black Radical Tradition" have found their ways into college classrooms, organizing spaces, community gatherings, online think pieces and elsewhere. In this seminar, students will engage in a slow reading of Cedric Robinson''s <em>Black Marxism: The Making of the Black Radical Tradition</em>, to explore the development of Robinson''s ideas over the course of his foundational text. We will practice a reading methodology that, as befitting Black Studies, allows room for us to ask questions, take detours and explore what are sure to be important overlaps and tensions. In doing so, students will develop a more nuanced understanding of these terms to grasp, complicate, struggle with and challenge how they are used in specific contexts over forty years after the initial publication of Robinson''s manuscript. As part of this methodology, students will also be asked to follow Robinson''s intellectual and political genealogies; in other words, we will also read who he read, thereby situating him alongside interlocutors in other fields and disciplines of study.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14741,2027,4431,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-388','<div class="desc"> This course explores Africa as a pivotal—though often marginalized theater—in the Cold War—the geopolitical struggle between the United States and the Soviet Union for absolute political, economic and military dominance. Moving beyond traditional narratives centered on superpower rivalry, this course reframes the conflict as a global struggle for decolonization and economic and political sovereignty waged by nations of the Global South against the imperial domination of the Global North. Foregrounding African agency, we examine how African states and movements challenged foreign intervention, economic dependency and Cold War realpolitik through radical projects of anti-colonial worldmaking, revolutionary socialism and radical pan-Africanism. We also investigate how states managed and contested control over Africa’s immense natural resource wealth—a central theme of the Cold War–and how they resisted, negotiated and redefined competing visions of the continent’s future. Ultimately, this course invites students to rethink the Cold War as a global history of liberatory struggle to reclaim political and economic autonomy and to remake the postcolonial world through revolutionary ideologies and transnational solidarity. </div>','BLST 180 or BLST 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14742,2027,4053,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-393','<div class="desc"> <div><p>This directed research course is for students in the spring semester of their junior year to do research preparation for their comps projects. Permission of instructor and department chair required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14743,2027,4107,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Black Feminist Movements</strong> </p> <p>This is an upper-division course wherein we interrogate our conceptualizations of “Black,” “feminist,” “Black feminist” and “movements.” What, or who, do we mean when we say “Black,” “feminist” and “Black feminist”? What do we mean when we invoke “movements”? Why is movement – literal and figurative – central to our understanding of blackness? What might it mean for blackness – Black peoples, Black communities, Black intellectual, political and cultural traditions – to move <em>across </em>land and sea, <em>through </em>space and time and <em>on </em>page, stage and screen? By reading expansively across disciplines, our course affirms that Black feminists have long been at the forefront of revolutionary practices of radically re-imagining what our world can be. We will engage with cultural producers from the Black diaspora (including, but not limited to: the United States, the Caribbean and the United Kingdom) working within critical ethnic studies, literary analysis, queer of color critique and performance studies, among others, and take seriously what they share in regards to prison abolition, the linkages between racism and capitalism, Black trans activism and other critical issues that demand our attention and action. We will locate these intersectional conversations within Black diasporic contexts – the literary, theoretical, political and cultural – as we seek potential answers to the questions posed above. Students will be asked to complete a research paper at the end of the term. <em>Core Program Requirement Met: Global Connections (CPGC)</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14744,2027,4108,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/300/blst-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14745,2027,2543,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/400/blst-490','<div class="desc"> <p>During the Fall semester, students will complete a thesis-driven 25-page research paper (their "comps") on a topic in Black Studies. The comps essay will offer an original analysis of primary sources grounded in relevant scholarship. Seminar meetings will focus on the collective experience of BLST majors writing their comps and preparing their presentations. The seminar will be followed up by student presentations in the Spring that will be open to the campus community. BLST 490 is a cohort-focused course that complements will BLST 493, "Senior Comps Directed Research," where students will focus on their individual research goals.</p> </div>','BLST 101 and the BLST Second-Stage Writing Requirement ','BLST 493',NULL);
INSERT INTO course_descriptions VALUES(14746,2027,4109,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/400/blst-493','<div class="desc"> <p>BLST 493 is a companion course to BLST 490. BLST 493 is directed research for students working on their comps. By working closely with a BLST faculty member of their choice, each student can effectively carry out their specific research project. BLST 493 helps each senior meet their individual research goals, while BSLT 490 provides the cohort experience for the graduating class. </p> </div>',NULL,'BLST 490',NULL);
INSERT INTO course_descriptions VALUES(14747,2027,4110,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/400/blst-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14748,2027,4111,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/blst-black-studies/400/blst-499','<div class="desc"> <p>Honors independent study project. Permission of instructor and department chair required.</p> </div>','Permission of instructor and department chair required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14749,2027,2730,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/bosp-barack-obama-scholars-program/200/bosp-200','<div class="desc"> <p>The aim of the Obama Scholars Program Seminar is to help Obama Scholars and Fellow develop and pursue their own conception of the public good, with the guidance of a faculty mentor and the support of members of their cohort. Participation in the seminar involves discussing selected texts and films; attending public lectures and other events; meeting with people at Oxy and beyond who serve the public good in various ways; and, in some cases, participating in community engagement projects. Permission of instructor required.</p> <p>This seminar is open only to Obama Scholars. Students may repeat the seminar for credit, as long as they remain Obama Scholars.</p> </div>','N/A ','N/A',NULL);
INSERT INTO course_descriptions VALUES(14750,2027,51,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-100','<div class="desc"> <p>Develop the skills necessary for a satisfactory introduction to general chemistry.</p> </div>','Open only for first year frosh with successful completion of a placement examination. Others only with permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14751,2027,52,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-104','<div class="desc"> <p>This is a course suitable for non-majors and covers the chemical bases of life. The course will be structured around the chemistry of the fundamental building blocks of life - nucleic acids, proteins, polysaccharides, etc. - and how they interact to support the cellular life. Examples of the specific topics include the evolution of the human genome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14752,2027,53,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-120','<div class="desc"> <p>An introduction to the primary chemical concepts of atomic structure and quantum theory, periodic trends, molecular structure, bonding theory, nomenclature, stoichiometry, solution chemistry, gases, intermolecular forces, and acids / bases. Includes one three-hour laboratory per week.</p> </div>','Satisfactory performance on the Chemistry Placement Examination, completion of one First Year Seminar or CWP 201 (formerly WRD 201), or permission of instructor ','CHEM 120L ',NULL);
INSERT INTO course_descriptions VALUES(14753,2027,55,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-130','<div class="desc"> <p>An advanced presentation of topics in atomic structure, periodic trends, molecular structure, molecular symmetry, and vibrational spectroscopy. <em>Includes one three-hour laboratory per week.</em></p> </div>','AP Chemistry score of 4 or 5 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14754,2027,901,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-150','<div class="desc"> <p>Symmetry is a fundamental unifying aspect of nature and is found in many human creations, from art, music, and architecture, to mathematics and science. In chemistry, symmetry is central to understanding the interplay of molecular architecture and function. This course provides the student with a qualitative and formal conceptual framework for categorizing molecular structures.</p> </div>','CHEM 100 , CHEM 120 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14755,2027,57,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-195','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14756,2027,4112,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/100/chem-197','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14757,2027,1572,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-201','<div class="desc"> <p>Intensive study of the modern laboratory methods of analysis, with applications to environmental systems.</p> </div>','CHEM 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14758,2027,4113,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-204','<div class="desc"> <p>In this course students will develop a sophisticated understanding of the nature and process of scientific inquiry and communication. Students will hone the skills necessary to evaluate and utilize scientific information from both popular media and peer-reviewed journal sources. Practice in reading primary scientific articles for comprehension, writing clearly about scientific topics for a broad audience, and delivering engaging scientific presentations will be a major focus of this course. Connecting our scientific view of the nanoscale to the world we experience on the macroscale, students will gain perspective on how scientific knowledge is established and communicated to inform the actions we take as a society and in our personal lives. </p> <p>Students in this course will practice and learn:</p> <ul> <li>To evaluate both primary and secondary articles about science critically and holistically, taking into account the full social and scientific context of the presented findings</li> <li>To recognize the effect of the language used in scientific writing on the message that is conveyed</li> <li>To access, dissect, and comprehend primary research articles with confidence, even in scientific subjects for which you may not have had formal coursework</li> <li>To describe how society influences and is influenced by scientific reports and the chosen direction of scientific research</li> <li>To communicate about science clearly and effectively through writing and presentations, with an emphasis on relevance and great sensitivity to audience understanding</li> </ul> <p>This course also fulfills the Second-Stage Writing Proficiency requirement when passed with a C. This course should be completed by the end of the junior year. If students do not pass the course with a C, they will need to take WRD 201 (The Art of Essay Writing) and pass it with a C to fulfill their Second-Stage Writing Proficiency requirement.</p> </div>','CHEM 100 , CHEM 120 , CHEM 130 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14759,2027,58,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-220','<div class="desc"> <p>Introduction to the fundamental concepts of organic chemistry. The course explores the properties and structures of carbon-based molecules, and focuses on how these factors influence their reactivity. Special emphasis is placed on biologically relevant organic transformations, as well as the prevalence of organic chemistry in everyday lives. Includes one three-hour laboratory that focuses on the practical techniques employed when conducting reactions and purifying organic molecules.</p> </div>','CHEM 120 or CHEM 130 ','CHEM 220L ',NULL);
INSERT INTO course_descriptions VALUES(14760,2027,60,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-221','<div class="desc"> <p></p><p>Continuation of Organic Chemistry I. The course focuses on the reactivity of organic molecules, including molecules and reactions with biological relevance. Special emphasis is placed on mechanism and employing chemical reactions to develop strategies for multistep synthesis. Includes one three-hour laboratory that applies the techniques of organic chemistry to the synthesis of interesting organic molecules.</p><p></p> </div>','CHEM 220 ','CHEM 221L ',NULL);
INSERT INTO course_descriptions VALUES(14761,2027,481,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-240','<div class="desc"> <span>Building on concepts developed in prerequisite classes, fundamental concepts in thermodynamics are developed from first principles, with subsequent application in chemical equilibrium and electrochemistry. Applications to biological systems and technology are emphasized. Includes one three-hour laboratory per week that focuses on developing analytical skills.</span> </div>','CHEM 120 or CHEM 130 ','CHEM 240L ',NULL);
INSERT INTO course_descriptions VALUES(14762,2027,483,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-280','<div class="desc"> <p>The course will explore the application of 1H, 13C, and two-dimensional NMR spectroscopy to the organic laboratory, as well as the important separation protocols such as: column chromatography, gas chromatography, and chiral HPLC. <em>Includes one-three hour laboratory per week.</em></p> </div>','CHEM 221 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14763,2027,62,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-295','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14764,2027,4114,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/200/chem-297','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14765,2027,63,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-300','<div class="desc"> <p>An introduction to the principles of thermodynamics and kinetics and their application to chemical systems.</p><p>Taking both CHEM 300 and CHEM 300L together can satisfy the Core Lab Science Requirement (CPLS). Taking just CHEM 300 can satisfy a Core Math/Science Requirement (CPMS). Please note that CHEM 300L is required for Chemistry majors.</p> </div>','CHEM 240 , Calculus 2 , and PHYS 110 or PHYS 115 ','CHEM 300L - Required only for Chem majors',NULL);
INSERT INTO course_descriptions VALUES(14766,2027,64,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-300l','<div class="desc"> <p>Applications of chemical thermodynamics and kinetics. <em>One three-hour laboratory per week.</em></p> <p>Taking both CHEM 300 and CHEM 300L together can satisfy the Core Lab Science Requirement (CPLS). Taking just CHEM 300 can satisfy a Core Math/Science Requirement (CPMS). Please note that CHEM 300L is required for Chemistry majors.</p> </div>',NULL,'CHEM 300',NULL);
INSERT INTO course_descriptions VALUES(14767,2027,1369,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-301','<div class="desc"> <p>An introduction to the principles of chemical thermodynamics, kinetics, and spectroscopy, with a focus on applications to biochemical systems.</p> </div>','CHEM 221 , Calculus 2 , and PHYS 115 or PHYS 125 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14768,2027,902,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-305','<div class="desc"> <p>An introduction to quantum mechanics, atomic and molecular structure, spectroscopy, statistical thermodynamics, kinetic molecular theory, and chemical applications of group theory.</p> </div>','CHEM 130 or CHEM 150 , Calculus 2 , and PHYS 125 or PHYS 230 ; or permission of instructor ','CHEM 305L ',NULL);
INSERT INTO course_descriptions VALUES(14769,2027,903,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-305l','<div class="desc"> <p>Atomic and molecular spectroscopy and modern techniques in physical chemistry. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 305 ',NULL);
INSERT INTO course_descriptions VALUES(14770,2027,1438,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-315','<div class="desc"> <p>An introduction to the study of kinetic molecular theory and chemical kinetics.</p> </div>','MATH 120 and PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14771,2027,4115,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-330','<div class="desc"> <p>While the revolutionary contributions of the chemical industry to society are undeniable, alternatives to traditional approaches in synthesis and catalysis are being demanded as concerns over pollution, toxicity, and sustainability are increasingly being recognized. As a result, chemists have turned to the biological world for "green" solutions to these problems. The course will explore how microbes and enzymes are being exploited by the chemical industry for myriad processes, including the synthesis of pharmaceutical compounds, water treatment and purification, and for the generation of hydrogen as a source of clean fuels. The first part of the course will examine several industrial processes that have been using enzymes for decades to produce the final commercial product. Emphasis will be placed on the technical challenges required for large-scale production of the compound. Course content will then shift to the academic arena, exploring current processes that the chemical industry wishes to replace with biologically-based systems. The challenges associated with scaling-up these processes will be emphasized, drawing on the foundation laid in the first part of the course. Finally, based on these lectures, students will be asked to take a "dirty" chemical process and propose a "green" solution, and identify the technical challenges that must be surmounted. An important aspect of the project will be exploring the economic feasibility, as well as potential obstacles related to governmental policies.</p> </div>','CHEM 300 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14772,2027,65,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-340','<div class="desc"> <p>Application of modern theories of physics and chemistry to the synthesis, bonding, and reactivity patterns of inorganic compounds. Special emphasis on the role of metal ions in biological systems.</p> </div>','CHEM 120 and CHEM 150 ; or CHEM 130 ; and CHEM 220 , CHEM 221 , CHEM 240 , CHEM 300 , and CHEM 305 . ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14773,2027,66,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-340l','<div class="desc"> <p>Inorganic synthesis and structure confirmation. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'CHEM 340 ',NULL);
INSERT INTO course_descriptions VALUES(14774,2027,485,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-350','<div class="desc"> <p>Biochemistry of macromolecules, with an emphasis on protein structure and function.</p> </div>','CHEM 221 and CHEM 240 ','CHEM 350L',NULL);
INSERT INTO course_descriptions VALUES(14775,2027,486,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-350l','<div class="desc"> <p>Laboratory techniques in Biochemistry. <em>One three-hour laboratory per week.</em></p> </div>','CHEM 221 and CHEM 240 ','CHEM 350 ',NULL);
INSERT INTO course_descriptions VALUES(14776,2027,67,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-355','<div class="desc"> <p>The main focus of this course is utilizing biological and chemical databases for research. The course will investigate: (1) tools that are used to extract and analyze data on small molecule drugs and biological sequences from these databases; (2) algorithms and scoring schemes used in sequence alignment and homology searches; (3) the significance of this information in modern chemical and molecular biology medicine, pharmaceutical development, protein engineering and drug design, genetics, and molecular evolution.</p> </div>','BIO 130 and CHEM 221 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14777,2027,487,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-360','<div class="desc"> Physical organic chemistry is the study of how small organic molecules interact. This course will provide a basic understanding of organic reaction mechanisms, frontier molecular orbital theory, and experimental design to support or disprove mechanistic proposals. </div>','CHEM 221 and CHEM 240 (May be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14778,2027,68,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-370','<div class="desc"> <div><p>Organometallic Chemistry focuses on the interface between organic and inorganic chemistry. This course covers the structure, bonding, reactivity, and applications of organometallic compounds, including their use in catalysis, industrial processes, and sustainable chemistry solutions.</p></div> </div>','CHEM 340 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14779,2027,1056,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-380','<div class="desc"> <p>An introduction to the study of organic synthesis.</p> </div>','CHEM 221 and CHEM 240 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14780,2027,69,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-395','<div class="desc"> <p>Intensive study in an area of Chemistry or Biochemistry of the student''s choosing, under the direct supervision of a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14781,2027,488,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/300/chem-397','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14782,2027,70,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/400/chem-490','<div class="desc"> <p>The preparation, presentation, and participation in a seminar series as a part of the Senior Comprehensive examination. Open only to senior Chemistry majors.To be repeated both semesters.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14783,2027,4116,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/400/chem-497','<div class="desc"> <p>Individual study of an area of special interest in a field of Chemistry of the student''s choosing, under the direct supervision of a member of the faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14784,2027,489,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chem-chemistry/400/chem-499','<div class="desc"> <p>Independent study leading to an honors project. May be repeated both semesters. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14785,2027,71,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/100/chin-101','<div class="desc"> <p>Introduction to spoken standard Chinese (Mandarin), the pinyin romanization system, and the reading and writing of Chinese characters. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Chinese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14786,2027,491,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/100/chin-102','<div class="desc"> <p>Continuation of Chinese I. Conversation, reading, elementary composition; completion of basic grammar.</p> </div>','CHIN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14787,2027,4117,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/100/chin-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14788,2027,4118,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/100/chin-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14789,2027,4119,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/100/copy-of-chin-193','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14790,2027,72,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-201','<div class="desc"> <p>A review of basic grammar. Reading and discussion of texts dealing with contemporary Chinese society and culture. Viewing and discussion of video programs. Composition writing and oral presentations.</p> </div>','CHIN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14791,2027,492,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-202','<div class="desc"> <p>Continuation of CHIN 201.</p> </div>','CHIN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14792,2027,73,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-272','<div class="desc"> <p>This seminar course will examine the rise of the martial arts novel (wuxia xiaoshuo) in the context of its historical and literary roots. We will focus on how the figure and chivalric code of the martial hero and heroine have persisted in the historical, literary, and popular imagination - through such works as Sima Qian''s historical biographies, <em>The Romance of the Three Kingdoms Outlaws of the Marsh</em>; Tang dynasty classical tales; Ming dynasty court-case fiction in the vernacular language; and Pu Songling''s classical strange tales written in the Qing period. We will also explore how the 20th century master of the martial arts novel, Jin Yong (Louis Cha), a journalist writing in exile in colonial Hong Kong, has captured the imagination of Chinese diasporic communities throughout the world and contributed to the rise of the transnational Chinese martial arts film. All readings and discussions will be in English. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14793,2027,4120,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-273','<div class="desc"> <p>This seminar examines contemporary Chinese fiction since the 1990''s, with a special focus on the growing number of works written in exile and in the author''s native or second language. We will explore the works of Nobel laureate Gao Xingjian, writing in Chinese as a French citizen; Dai Sijie, writing in French in France; and Ha Jin and Yiyun Li, writing in English in the U.S. What are the national, transnational, cultural, gendered, and aesthetic contexts and issues surrounding the writing and reading of fiction written "out-of-country" and "out-of-language"? How do the writers, in a variety of languages, genres, and political stances, return to memories of their homeland, in particular to national traumas, such as the Cultural Revolution, and re-write official versions of the nation and remember their selves? All readings and discussions will be in English. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14794,2027,817,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-274','<div class="desc"> <p>This seminar course will explore ghosts and other disembodied beings in the Chinese literary tradition, from the earliest historical documents, philosophical texts, and Buddhist tales, to the Six Dynasties zhiguai records of the strange, the Tang chuanqi tales of the marvelous, and Ming dynasty vernacular fiction. We will focus on recurring motifs and archetypes which weave the supernatural into love stories, especially as manifested in two Qing dynasty masterpieces: Pu Songling''s <em>Strange Tales</em> and Cao Xueqin''s <em>The Story of the Stone</em>. Modern stories and film will also be examined for their adaptations of traditional motifs and archetypes. Given in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14795,2027,1005,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14796,2027,4121,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/chin-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14797,2027,4122,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/200/copy-of-chin-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14798,2027,74,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-301','<div class="desc"> <p>Reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Introduction to the use of literary style Chinese and idioms in public discourse. Developing advanced level oral-aural and essay writing skills.</p> </div>','CHIN 202 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14799,2027,1057,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-310','<div class="desc"> <p>Advanced reading and discussion of expository essays and short narratives on Chinese society, culture, and current topics. Oral presentations, academic style discussions, and writing of essays and narratives.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14800,2027,1058,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-330','<div class="desc"> <p>A survey of representative works of short fiction and film by 20th century and contemporary Chinese writers and film makers. Topic and content of the course will vary from year to year according to three areas of focus: mainland China, Taiwan/Hong Kong, and transnational Chinese. Students will read and view original works and practice oral and written summaries, commentaries, discussion, and analyses in Chinese. Students will also read essays on literature and film in Chinese, with some readings in English. This course may be taken three times.</p> <p><strong>Female Who Writes and Who is Written</strong></p> <p>This course will examine the relationship between culture and society in China by focusing on the images of women represented in modern and contemporary cultural production, including literary and cinematic texts. By investigating the images of women in both literature and cinema from the twentieth century onward, this course will explore the development and transformation of the status of women in different sociohistorical periods of China, and discuss the ways in which cinema and literature feature women to address issues of gender, family, society, national identity, cultural memory, and so forth. In addition to representative literary texts, students will develop skills to interpret and analyze audiovisual media by watching the film adaptations of the assigned literary texts, and discuss how literary texts and cinematic media have both been used to construct and shape the cultural scene in Chinese society. <em>Core Requirement Met: Regional Focus</em></p> </div>','CHIN 301 (or above) or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14801,2027,2940,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-338','<div class="desc"> <p>This course introduces the major genres and authors of the Tang and Song Dynasty (618-1279), generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry and the emergence of literati culture. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. This class will meet with CSLC 253 twice a week, and meet for an additional 85-minute session weekly to discuss the material in the Chinese original. Primary texts are in Classical Chinese, so proficiency in reading Chinese is required. Students completing the paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement. </p> </div>','CHIN 202 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14802,2027,495,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-350','<div class="desc"> <p>Readings in short classical Chinese texts, from pre-Qin historical, philosophical, and literary works that are the sources of sayings still common in modern vernacular Chinese. Students will learn the grammar, structure, and vocabulary of classical Chinese (wenyan) and gain advanced proficiency in modern spoken (baihua) and literary (shumianyu) Chinese, through exercises in oral and written discussion and analysis of the use of classical Chinese thought and sayings in contemporary Chinese language and culture. Course offered every four years.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14803,2027,4123,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14804,2027,496,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/chin-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14805,2027,4124,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/300/copy-of-chin-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14806,2027,1205,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/400/chin-460','<div class="desc"> <p>This advanced level course will introduce students to the art, practice, and intercultural contexts of translating Chinese into English. The class will discuss the content, linguistic form, and cultural contexts of a variety of authentic examples of written Chinese, followed by practice in producing readable English translations. Original Chinese texts will include short stories, essays, and media. This course is open to both non-native and native speakers of Chinese who wish to develop their bilingual skills and intercultural literacy. Class discussion will be conducted in Mandarin, Chinese, and English. May be repeated once for credit.</p> </div>','CHIN 301 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14807,2027,3876,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/400/chin-493','<div class="desc"> <p>"Chinese language, literature, and culture": Senior comps directed research in Chinese Studies.</p> </div>','Instructor permission required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14808,2027,4125,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/400/chin-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14809,2027,3968,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/chin-chinese-studies/400/chin-498','<div class="desc"> <div><p>Honors directed research in Chinese. Prerequisite: Permission of the department and instructor.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14810,2027,4126,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/100/chin-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14811,2027,76,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/100/cogs-101','<div class="desc"> <p>An interdisciplinary introduction to the discovery of the mind through philosophical texts, psychological experiments, artificial intelligence, the study of nerve cells and neural networks, and investigations into language. The purpose of the course is to foster an appreciation of the wonder and complexity of minds and brains, both human and otherwise. Not open to seniors in Spring semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14812,2027,77,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/100/cogs-104','<div class="desc"> <p>This course provides a basic introduction to the nervous system. The course will include an introduction to how nerve and glial cells contribute to different brain functions. This course will also cover brain structures and systems and how they act to produce sensory experience, thought, emotion, and memory. Other topics might include: factors that affect embryonic development of the nervous system, and the effect of drugs, environment, stress, education, and age on the brain.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14813,2027,1684,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/100/cogs-111','<div class="desc"> <p>The average adult possesses over 50,000 concepts, ranging from physical concepts like "force" and "density," to biological concepts like "growth" and "reproduction," to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich, revise, and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive, developmental, and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14814,2027,4127,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/100/cogs-193','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14815,2027,4128,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/100/cogs-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14816,2027,1504,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-201','<div class="desc"> <p>This course provides students with a foundation to think critically about research in Cognitive Science and lays the groundwork for the original research that will be done in the senior year. We will examine primary literature, carefully considering the processes involved in moving from a general idea to a specific research question. We will consider the strengths and weaknesses of a range of approaches to studying cognition, with a focus on experimental design. The course will culminate in an original research proposal.</p> <p><br/> </p> </div>','COGS 101 ','COGS 201L ',NULL);
INSERT INTO course_descriptions VALUES(14817,2027,2325,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-220','<div class="desc"> <p>Are earthworms capable of making decisions? How do ants navigate their environment? Do dogs have an understanding of fairness? Questions about the mental states and processes possessed by non-human animals present particular problems of study: how do we determine whether, and to what extent, animals possess such abilities? This course will study the evidence for cognitive states and processes in non-human animals, focusing on careful and critical attention to the methods and techniques used to gather that evidence and on the considerations that go into interpreting that evidence.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14818,2027,4411,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-228','<div class="desc"> <p>Drawing from recent advances, this seminar explores the rapidly-advancing intersection between neuroscience and machine learning. This course will address theoretical, practical, and ethical considerations in contemporary cognitive science, including best practices in scientific research and the responsible development of AI systems. Students in this class will examine how intelligences - both natural and artificial - learn, organize knowledge, and make decisions through weekly readings, group discussions, and code demonstrations. Students will evaluate experimental methods, neural coding principles, and computational models in literature and commentaries at the forefront of cognitive and computer science. The course culminates in a student-led conference showcasing research projects in neuroscience and AI. </p> </div>','Any COGS class or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14819,2027,1006,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-230','<div class="desc"> <p>This course addresses the question: how can we understand the mind scientifically? We will explore answers to this question via a critical survey of neural and behavioral evidence bearing on the nature of core cognitive capacities, including perception, memory, emotion, decision-making, rationality, and consciousness. We will explore these sources of evidence in a comparative perspective, drawing on evidence of both human and (non-human) animal cognition, to more adequately characterize the general nature of cognition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14820,2027,1153,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-241','<div class="desc"> <p>As part of human cognition, our perception, production, and understanding of music has elicited many questions: what is music in relation to "sound"? Is music an evolutionary adaptation? What is the relationship of music and emotions or memory? Can music influence perception in other modalities? What is the meaning of music? Can music make us smarter? Is music a language? What is biological and what is cultural in the esthetics of music? This course will reframe many of these questions from the interdisciplinary standpoint of cognitive science, acoustics, music theory, and semiotics, to explore music as a cognitive process. Topics will include: the perception of pitch, timbre, rhythm, and localization; music and the brain; the cognitive aspect of the esthetics of music; the relationship between music and language in terms of their structures and neurological processing; music and memory; music and emotions; and music and meaning. We will also discuss the role music plays in cross-modal interactions, either in the real world or in films and multimedia art works.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14821,2027,906,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-242','<div class="desc"> <p>Computational modeling provides important insights into how the mind/brain may work. We will examine three different approaches that have been used to provide insights into cognition: symbolic methods, connectionism, and probabilistic methods. We will use computer software to explore how these approaches work in practice. Specific applications, such as perception, language, and memory will be covered. The assumptions and limitations of each approach, as well as the metaphor of mind/brain as a computer, will be critically considered. This course has a mandatory laboratory component which will include both experimentation and computer programming. No previous programming background is required.</p> </div>','COGS 101 (may be taken concurrently), MATH 210 , MATH 214 , or PHIL 225 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14822,2027,4432,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-248','<div class="desc"> <p>âArtificial Artificial Intelligenceâ is how Jeff Bezos once described the reliance of AI on extensive, and usually ignored, human labor. What goes into producing the sometimes bizarre and often mundane outputs of generative AI? This course will examine critical issues in AI in order to begin to answer this question. First, what are the histories of the AI present? For example, terms like artificial intelligence, neural network, automation, and grok, are not new. Where do they come from and how do they influence what our technologies look like? Second, alongside technical issues, weâll situate AI and machine learning in relation to gender, race, and sexuality, and cognition and consciousness. Weâll also discuss the ways that AI is not only a Silicon Valley technology, but a global one: geopolitically and how each moment of user interface mobilizes a planetary infrastructure and ecologies of labor and extraction. In doing so, students will deepen their understanding of âAI,â a term thatâs everywhere and whose meaning is elusive.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14823,2027,4129,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-250','<div class="desc"> <p>Traditionally, the senses have been thought to operate independently. However, there is increasing evidence that the brain is fundamentally multisensory. This course will explore how the brain encodes input from each of the senses, and how it integrates this information to create our perceptions of the world. We will consider converging evidence from methodologies such as psychophysics, neuroimaging, neural recording, and neurology. The laboratory component of the class will include experiments within individual senses, as well as those that explore integration of the senses.</p> </div>','COGS 101 , COGS 104 , or PSYC 302 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14824,2027,2398,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-255','<div class="desc"> <p>The primary goal of this course is twofold: (1) to provide students, from a wide range of disciplines, with hands-on training to analyze a variety of data-sets relevant to their course of study, and (2) to provide them with the tools to understand the rhetorical form and function of different types of data visualizations. Students will consider how questions can be answered using data; learn how to analyze data appropriately; learn to design and present graphs that tell an easy-to-understand visual story, have high impact and are memorable, and critically consider the assumptions underlying accurate interpretation of analyses and visualizations. Students from any major are welcome.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14825,2027,4130,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-255l','<div class="desc"> </div>',NULL,'COGS 255',NULL);
INSERT INTO course_descriptions VALUES(14826,2027,3874,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-260','<div class="desc"> <p>This class is an introduction todeaf communities and sign languages around the globe, with a focus on the analysis of American Sign Language (ASL). We will make an overview of the fundamental concepts of sign language linguisticsandinvestigate how sign languages parallel with spoken languages at different levels of the structure because they all draw on the same linguistic and cognitive capacities. We will also explore the differences in sign languages because they are signed and seen. This course will also touch on the disability as diversity and discuss recent development in the disability studies through the lens of deaf communities, including deaf identity, deaf history, and deaf culture as an important contribution to the diversity in the US. This class may contain a community-based learning component. The American Speech-Language-Hearing Association (ASHA) reported that in 2022, approximately 42% of speech-language pathologists (SLPs) regularly served deaf and hard-of-hearing children. This class is also recommended for students who are considering becoming an SLP.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14827,2027,3051,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-262','<div class="desc"> This course will examine the multifaceted relationship between culture and cognition. How do our cultural and environmental contexts shape our perceptions, knowledge, and behaviors? How do specific aspects of a culture change the ways in which people acquire, store, and process information? What is the relationship between culture, our experiences, and our social identities? To what extent do our beliefs and knowledge structures vary across populations? In this course, students will explore these questions and more using the tools of cognitive science. Topics will include conceptual development, knowledge organization, causal reasoning, cultural transmission, morality, trust, and cooperation. </div>','COGS 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14828,2027,1641,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-265','<div class="desc"> <p>Art - be it visual, music, dance, or literature - is an extraordinarily powerful practice, driving much of our behaviors and engaging us physically, emotionally, and cognitively. This seminar will explore the various creative arts through the perspectives of Psychology, Neuroscience, and Philosophy. Topics will range from aesthetic foundations, historical dialogues between psychology and art, as well as the biological and evolutionary bases underlying aspects of creativity and art appreciation.</p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14829,2027,4412,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-266','<div class="desc"> <p>How does engaging with the arts affect our health and wellbeing? A burgeoning interdisciplinary research program at the intersection of psychology, neuroscience, philosophy, arts education, and public health suggests that arts engagement – from reading, to music-making, to painting, to theater – have profound impacts on mental, socioemotional, and physical wellbeing. In this course, we will explore this research through a combination of theory, creative practice, and community engagement. We will examine various conceptions and models of wellbeing, and analyze the various strands of evidence showing the arts as expansive sources for wellbeing in our lives, that could impact our attention, emotion, meaning-making, identity, social connection, and physical health. Beyond theoretical analysis, students will engage in hands-on creative arts-making to personally investigate the psychological and physiological effects of the creative process. We will also consider methodological challenges, and analyze contemporary initiatives in healthcare, public health, and community arts settings. Assignments will include reflective journals, analytic essays, and an integrative project that connects theory, practice, and community engagement. This course will contain a community-based learning component. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14830,2027,3255,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-270','<div class="desc"> <p>This course will cover key concepts in nervous system structure and function through the lens of the sensory and affective experience of pain. Students will gain a basic understanding of nervous system organization, evolutionary adaptation, neuronal mechanism of action, sensation and perception, plasticity, and top down processing through the examination of the neuroscience of pain and the clinical experience of pain and its treatment, including coverage of disparate pain treatment on the basis of race and gender. This course will also take an interdisciplinary perspective to pain, considering how it has been represented in literature and philosophy. Although there are no specific prerequisites, the course will include (optional) materials appropriate for students with a deeper background in psychology, biology, neuroscience, and/or cognitive science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14831,2027,1441,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-292','<div class="desc"> <p>Mechanisms of brain development, growth, neurogenesis, maturation, and changes that occur during life. Emphasis will be placed on current literature and studies done in non-human animals and humans. We will also talk about what it takes to maintain a healthy brain.</p> </div>','COGS 101 or COGS 104 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14832,2027,3473,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14833,2027,819,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-295','<div class="desc"> <p>This course explores a topic within the field of cognitive science. Topics vary by semester; past topics have included Intelligent Agents and Concepts. See the Department Chair for further information.</p> </div>','Any COGS course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14834,2027,4131,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14835,2027,3298,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/cogs-298','<div class="desc"> <p>COGS 298 introduces students to the basics of electroencephalography (EEG) methodology for cognitive neuroscience research. This is a project-based lab course in which students will learn to conduct an experiment using EEG from start to finish. Students will attain a conceptual and theoretical understanding of EEG as a neuroimaging technique, will learn to design and program an original EEG experiment, participate in EEG data collection, will learn to analyze and visualize EEG data, and will present their work in both oral and written form. Students will gain skills in experimental design, computer programming, data analysis, scientific writing and presenting scientific results. No prior experience with EEG or coding is necessary to succeed in this course. Includes one three-hour laboratory per week.</p> </div>','BIO 130 , COGS 101 , COGS 104 , COMP 113 , PSYC 101 , or instructor permission No prior experience with research, EEG, or computer programming is necessary. ','COGS 298L ',NULL);
INSERT INTO course_descriptions VALUES(14836,2027,3253,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/copy-of-cogs-243','<div class="desc"> <p>Recognizing a face regardless of the angle, recalling the details of a birthday party years ago; we take for granted the complexity of the problems our brains solve on a daily basis. Do models used by cognitive scientists perform similar algorithms to those implemented in neural circuits honed over millennia of evolution? Students in this course will use disciplinary-specific scientific tools and strategies in a laboratory setting to observe cognitive phenomena. We will do this by designing experiments and collecting primary data, and students can expect to gain technical skills in problem solving, experimental design, and programming. Students will also analyze data to produce graphs, charts, or summary tables, as well as learn to break jargon down for communication to public audiences. Additionally, the course will include critical reflections on the scope, limitations, and broader impacts of computational and neuroscientific approaches to cognition.</p> </div>','COGS 101 (may be taken concurrently) or COGS 104 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14837,2027,3888,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/200/copy-of-cogs-280','<div class="desc"> <p>This course will explore the neurological mechanisms that control eating &amp; hunger, drug addiction, sexual behavior, and the intersection of all of these topics. Each of these topics has direct impact to everyday life. However, the specific ways in which the brain controls each of these things tends to be underrepresented in neuroscience instruction. In particular, a key point is how all of these processes utilize highly overlapping brain circuits. In order to explore these behavioral phenomenon, this course will investigate brain reward and homeostatic pathways. In addition to lecture, students will acquire knowledge about these topics as well as neuroscience techniques used to explore them through student-led (and instructor-guided) discussion of primary literature. Some prior student experience with the brain via a cognitive science, psychology, or neurobiology course is warranted when taking this course.</p> </div>','Prior experience with the brain, through psychology, cog sci, or biology, would be helpful for keeping up sufficiently with this course''s materials. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14838,2027,78,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-301','<div class="desc"> <p>This course will address current cognitive science research as applied to learning and education. The concept of multiple intelligences, as well as strengths and weaknesses of individuals in acquisition of information, will be emphasized. We will also cover specific learning disabilities/differences and cognitive styles. Education minors only.</p> </div>','COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14839,2027,2585,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-303','<div class="desc"> <p>This seminar course will look at a topic in neuroscience from a multidisciplinary perspective. The course will focus on critical analysis of research studies and methodologies. May be taken more than once for credit as the topics will differ each semester.</p> <p><strong>Deep Learning</strong></p> <p>This course will cover current topics at the intersection of cognitive neuroscience and deep learning. Recent successes in deep learning and AI have hinted that networks of simple units can produce surprisingly complex behaviors, and these models often even mirror the coding properties observed in the human brain. However, unlike artificial agents, humans excel at thinking creatively and reasoning about cause and effect, allowing us to behave flexibly in novel and ambiguous environments. What neural mechanisms support these behaviors? Which of these mechanisms are necessary for producing analogous capabilities in artificial agents? We will gain insight into these questions by reading primary literature and algorithm development exercises. Previous experience in cognitive science, computer science, psychology, logic, mathematics, or biology is required for success in this course.</p> </div>','COGS 201 , BIO 268 , PSYC 200 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14840,2027,2544,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems, make decisions, draw inferences, attend to their environment, communicate, remember, and learn. Much of the material is applied to real-life settings.</p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14841,2027,2586,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-308','<div class="desc"> <p>In the second half of the 20th century, the new field of cognitive science came into existence. This course explores the developments in the history of philosophy, mathematics, biology, psychology, and computer science that culminated in this new science of the mind, including the theory of computation, from the work of Leibniz in the 17th century, the pioneering work on computing and programming by Charles Babbage and Ada Lovelace in the late 19th century, to Turing''s work in the early 20th century. We will explore how developments in both theoretical and applied computer science and logic led to the field of artificial intelligence and computational neuroscience, and we''ll explore the philosophical questions about the possibility and scope of machine intelligence. One prior course in cognitive science, philosophy, or mathematics is recommended.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14842,2027,500,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320','<div class="desc"> <p>This course will introduce students to the biology of the mind. It will provide an overview of neuroanatomy and characterize the neural mechanisms supporting complex cognitive processes including vision, attention, consciousness, language, memory, learning, emotion, and action. We will also emphasize the importance of converging methodologies in studying the link between the mind, brain, and behavior. Methodologies we consider include: behavioral measures of cognition, neuropsychology, electrophysiology, anatomical and functional neuroimaging, single-cell recordings, and computational modeling. Laboratory sessions will allow students to obtain hands-on experience with these methodologies, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>','BIO 268 , COGS 201 , PSYC 200 , or permission of instructor ','COGS 320L ',NULL);
INSERT INTO course_descriptions VALUES(14843,2027,820,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-320l','<div class="desc"> <p>Laboratory sessions will allow students to get hands-on experience, as well as arm them with the tools to understand and evaluate primary research in Cognitive Neuroscience.</p> </div>',NULL,'COGS 320',NULL);
INSERT INTO course_descriptions VALUES(14844,2027,1371,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> </div>','COGS 101 , four units of Computer Science, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14845,2027,1059,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-330','<div class="desc"> <p>Linguistics is the study of language; cognitive science is the study of cognition. How can we combine their resources to help us understand the human cognitive ability to use language? In this class we will approach this question by asking how to think about language from the perspective of cognitive science: What conceptual frameworks are appropriate to use to understand language in this way? What can we distinctively learn about language, and about cognition, from this perspective? What theoretical assumptions are we making about language and cognition when we approach language from this perspective, and what is the rationale for those assumptions?</p> </div>','COGS 101 or LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14846,2027,3979,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-333','<div class="desc"> <p>Most people know at least one language. What can we expect in the structure of a language that we use on a daily basis? Going beyond that, what can we find in the structure of a language we are unfamiliar with? The class provides an overview of the world languages and language families. We will discuss the typological classifications of linguistic properties, investigate the mechanisms of language change and variation, and explore the unity and diversity of language systems. The lab sessions provide an introduction to the methods and hands-on training in analyzing linguistic data from a wide variety of languages in the world. Includes one three-hour laboratory per week. </p> </div>','COGS 101 , or LING 301 , or permission from the instructor ','COGS 333L ',NULL);
INSERT INTO course_descriptions VALUES(14847,2027,3980,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-333l','<div class="desc"> <p>Graded on a Credit/No Credit basis only.</p> </div>',NULL,'COGS 333',NULL);
INSERT INTO course_descriptions VALUES(14848,2027,4022,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-335','<div class="desc"> <p>Language allows us to communicate our thoughts and ideas to each other because linguistic expressions are meaningful. But what makes these expressions meaningful, and what does their meaning consist in? Contributions to answering these questions come from two areas of linguistics: semantics â the study of the meaning of linguistic expressions â and pragmatics â the study of how the context in which linguistic expressions are used contributes to what they convey. This class will survey the current state of research in semantics and pragmatics to provide students with a grounding in the central issues surrounding the study of linguistic meaning.</p> </div>','COGS 101 or LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14849,2027,3889,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-338','<div class="desc"> <p>This class provides an investigation of the cognitive bases of language acquisition, informed by state-of-the-art research in psychology and linguistics in the study of first language acquisition. We will concentrate on the development of linguistic structure, including phonological, lexical, morphological, syntactic, and pragmatic development. Universal aspects of development will be discussed, as well as a variety of cross-linguistic phenomena. Other topics include theories of language learning (parameter-setting, maturation), learnability, atypical language development, and bilingualism. This class is highly recommended for students who are considering becoming a speech-language pathologist (SLP). </p> </div>','COGS 330 or COGS 333 or LING 301 or PSYC 351 / LING 350 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14850,2027,4132,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-343','<div class="desc"> <p>Probabilistic models have increasingly been applied to understand how the mind works across domains such as: motor control, decision-making, and causal inference. We will learn how such models work, learning the mathematical tools necessary to implement them, such as Bayesian inference, graphical models, and Markov models. We will consider both how human cognition can inform machine learning and how computational approaches can lead to new ideas about cognition.</p> </div>','COGS 242 ','COGS 343L ',NULL);
INSERT INTO course_descriptions VALUES(14851,2027,4133,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-343l','<div class="desc"> <p>Three hour per week Probabilistic Models of Cognition laboratory. Graded on a Credit/No Credit basis only.</p> </div>',NULL,'COGS 343',NULL);
INSERT INTO course_descriptions VALUES(14852,2027,3890,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-346','<div class="desc"> <p>This course will cover current topics at the intersection of cognitive neuroscience and deep learning. Recent successes in deep learning and AI have hinted that networks of simple units can produce surprisingly complex behaviors, and these models often even mirror the coding properties observed in the human brain. However, unlike artificial agents, humans excel at thinking creatively and reasoning about cause and effect, allowing us to behave flexibly in novel and ambiguous environments. What neural mechanisms support these behaviors? Which of these mechanisms are necessary for producing analogous capabilities in artificial agents? We will gain insight into these questions by reading primary literature and algorithm development exercises.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14853,2027,4134,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-350','<div class="desc"> <p>Experimental philosophy is the process of using the methods of experimental psychology to inform questions of traditional philosophical concern, typically by using surveys or other instruments to evaluate whether philosophers'' intuitions and judgments accurately represent generally held beliefs. In this class, we will discuss the historical antecedents for contemporary practice of, and critical reactions to, the project of experimental philosophy via study and discussion of central works in the field. We will be concerned with questions such as: what do the tools of experimental philosophy reveal about the practice and content of traditional philosophy? To what extent are these tools valid for drawing conclusions about philosophical claims, arguments, and disputes? Can the methods of experimental philosophy supplement, or even potentially replace, traditional methods of doing Philosophy?</p> </div>','Any Cognitive Science or Philosophy course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14854,2027,2674,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-390','<div class="desc"> <p>A recent replication crisis in the sciences has led to large-scale questioning centered on scientific integrity. Scientific integrity refers to 1) honesty while conducting and interpreting research, and 2) to developing conclusions that are unbiased and valid. Contemporary practices in research design and statistical analysis (e.g. p-hacking), lack of transparency, and political bias are all threats to scientific integrity. This course introduces and engages students conducting directed research with a faculty member in the Cognitive Science Department in best practices and ethical concerns in scientific research through evaluating primary research and commentaries within cognitive science and statistics, as well as by evaluating and critiquing the literature in their area of research focus. Students are expected to commit to a minimum of 8 hours of course-work each week including a course meeting, assigned group work, readings, and independent research. This course is graded CR/NC only.</p> </div>','COGS 101 , COGS 201 , and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14855,2027,821,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-395','<div class="desc"> <p>Directed research with a faculty member.</p> </div>','COGS 101 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14856,2027,501,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/300/cogs-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14857,2027,80,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/400/cogs-490','<div class="desc"> <p>This course will support senior Cognitive Science majors as they conduct original research as part of their Senior Comprehensive requirement. Open to Cognitive Science majors and seniors only.</p> </div>','COGS 101 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14858,2027,2545,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/400/cogs-495','<div class="desc"> <p>Students with substantial directed research experience will conduct an independent research project of their own design, with guidance from a faculty mentor. Students are expected to devote a minimum of 6 hours per week to their project, and will present their results in a colloquium open to the campus community. Open only to seniors and by permission of the instructor.</p> </div>','COGS 201 or COGS 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14859,2027,4135,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cogs-cognitive-science/400/cogs-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14860,2027,2947,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-101','<div class="desc"> <p>Throughout their careers, students in Computer Science will have the opportunity to affect society through the technologies that they create. Yet technology is not created in a vacuum, but rather is a product of the ingrained assumptions of its creators, and the societies that structure these assumptions. When working with the tools of Computer Science, students will face traces of the fieldâs racist, sexist, homophobic, and imperialist history, and will have to decide how to work with or challenge these parts of the field. This course prepares students to work for justice and equity in technology and society by facilitating conversations about the sometimes-oppressive history and impact of Computer Science, and by uplifting voices that have historically been marginalized within the field. By the end of the course, students will be able to analyze and discuss technology within its broader context, and be able to use the tools of Computer Science to subvert the unjust structures the field has inherited.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14861,2027,4136,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-112','<div class="desc"> <div><div><p>This introduction to data science course is designed for all students, whether STEM students or not. It is an overview of topics popular in the quickly emerging field of data science. Topics include simple statistics, graphics and visualization, computer based tools designed for analysis and presentation of large data sets, introductory machine learning, and applications from a diverse array of fields.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14862,2027,4137,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-113','<div class="desc"> <p>This course is a computational introduction to data science. Students will use R to clean data, create models (regressions, clustering), and visualize and communicate the results. The course will include descriptive statistics and methods of hypothesis testing as students learn how to make arguments from data.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14863,2027,1511,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-131','<div class="desc"> <p>Computer Science is about the organization of information and the design of processes that use it. This course teaches students to think computationally - how to break down processes into components that can then be fully described - and to acquire other habits necessary for a computer scientist. Students should come out of the course able to write simple, but complete, programs of their choosing, and should also be able to diagnose problems in unfamiliar programs.</p> </div>',NULL,'COMP 131L ',NULL);
INSERT INTO course_descriptions VALUES(14864,2027,2648,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-146','<div class="desc"> <p>Comprehensive study of measures of central tendency, variation, probability, the normal distribution, sampling, estimation, confidence intervals, and hypothesis testing. Introduction to use of technology in statistics. Real-life problems are used to illustrate methods. Weekly lab. Not open to students who have completed or are currently enrolled in PSYC 201, BIO 268, MATH 150, or any Mathematics course above 200.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14865,2027,2508,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-149','<div class="desc"> <p>This course provides the mathematical theory which underpins Computer Science, including: number systems; variable types and formats; logic; set theory; graph theory; linear algebra; and important numbers, functions, and relations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14866,2027,81,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-155','<div class="desc"> <p>Principles of web design. Tools and techniques of elementary web programming, including: HTML, XHTML, CSS, JavaScript, HTTP, SSL, XML, and SQL. Introduction to network architecture and programming.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14867,2027,2948,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-181','<div class="desc"> <p>In this course, students will gain additional experience in object-oriented programming in Java. Students will work in pairs and small groups on multiple programming projects. Topics will include test-driven development, debugging, and source code management, but focus will be on writing maintainable and efficient code. This course is intended to prepare students with some programming experience (COMP 131 or equivalent) for more advanced programming courses.</p> </div>','COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14868,2027,4138,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-195','<div class="desc"> <p>Topics vary by semester. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14869,2027,1581,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/100/comp-197','<div class="desc"> <p>Directed individual study. Permission of instructor and department chair required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14870,2027,1649,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-229','<div class="desc"> <p>We begin with topics found in advanced programming. In particular, topics from object-oriented programming and how this differs from procedural programming. We then move on to the study of dynamic data structures, such as linked lists, stacks, queues, trees, heaps, graphs, hash tables, sets and more. Completion of this course opens up the remainder of the Computer Science classes and is required for minors. Common themes that run throughout this course are: (1) implementation of the abstract data types, and (2) spatial and memory consideration and analysis.</p> </div>','COMP 131 or COMP 181 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14871,2027,2957,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-230','<div class="desc"> <p>As humankind stares down a number of unprecedented global challenges, the need for creative, radical thinking is imperative. In this interdisciplinary studio, students will develop a series of detailed and speculative projects inspired by boundary-pushing artistic and technological practices. The course will examine precedents from contemporary art, media, engineering, performance, design, and technology that offer responses to a wide range of “what-if” scenarios. The primary goal of the class will be to guide students as they develop a methodology for making creative and responsive work—one that relies on provocation and imagination as driving forces. Class projects will be designed to develop critical thinking and research skills, art-making and visual communication capabilities, and will call for speculative, even fantastical, responses to complex sites and situations. Technological and data-driven approaches, including data analysis, modeling, and scenario planning, will be integrated into the class assignments, encouraging cross-disciplinary collaborations between computer science and media arts students. Instructional assignments will explore a range of materials, scales, and research methods, and will encourage students to develop their abilities to hone and express innovative responses to complex societal and relational questions. The final series of class projects will address the uncertainty of climate change as a contextual framework, and final proposals may range from site-specific art installations to new applications for robotics; from creating futuristic soundscapes to designing experiences in VR. Site visits and guest lecturers will extend students’ connections with selected Los Angeles sites and their contexts, the understanding of a broad set of perspectives and values, and real-world examples of collaborative, cross-disciplinary projects. Not open to First Year Students. Permission of instructor required.</p> <p>Sub-field: INTERFACES</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14872,2027,2509,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-239','<div class="desc"> <p>This course covers the basics of how a computer works, focusing especially on the hardware-software interface. Students will learn about the limitations of the physical computer, and that it may not be possible to ignore the lower-level hardware when designing efficient software. Students will learn to implement programs in Assembly language and C/C++. They will investigate the main components of the computer and it''s processor and master the binary language of computers. They will learn important design concepts such as memory hierarchy and parallel computing, and have a brief encounter with principles of digital logic. This is a required course for the Computer Science major. Includes one 1.5-hour lab period per week.</p> </div>','COMP 131 , COMP 181 , or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14873,2027,2956,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-242','<div class="desc"> <p>This course is a survey and a series of hands-on workshops exploring the critical, speculative, and also practical ways of applying machine learning to working with sound and musical composition. In particular, we will be focusing on using Machine Learning models that learn from input data to optimize towards a certain task. In this class, we will look at the uses of ML as a way to deepen our relationship with sound and music production by focusing on machine and human collaboration rather than ML models as solely an open "toolbox" for new sound techniques. This class will learn how to organize and work with large sound datasets, generate new raw audio with neural networks, work with existing plug-ins that have machine learning capabilities, as well as generate midi and compositional structure by training our own AI models. No prior programming experience is necessary.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14874,2027,2539,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition.</p> <p><span style="color: #282b2c;">Sub-field: </span><strong style="color: #282b2c; margin: 0px; padding: 0px;">INTERFACES</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14875,2027,2737,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-277','<div class="desc"> <p>Video games are one of the newest forms of media, and offer tremendous promise for both entertainment, storytelling, and education. Starting from the text-based adventures of the 1970s to the billion-dollar industry today, students will learn how to use psychology and game mechanics to create compelling narratives, as well as gaining a glimpse into large-scale software development.</p> <p>Sub-field: INTERFACES</p> </div>','COMP 131 , COMP 181 , or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14876,2027,2869,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-295','<div class="desc"> <p><strong>Automation: Politics and Aesthetics</strong></p> <p>In the course “Automation: Politics and Aesthetics” students will examine “automation” in capacious historical, geographical, and conceptual senses. In dominant United States-based discussions of these today automation is described as something that is produced by Silicon Valley, or happens to “American” workers, or takes place in direct interfaces between a “user” and a “computer.” The course will instead meet Occidental’s Global Connectionsrequirement that students “develop a global, transnational and/or comparative understanding” by asking them to reconsider both the geographies of automation as well as the artists and theorists who have put automation at the center of their work. One of the course’s guides for this will be Kate Crawford who in the book <em>Atlas of AI </em>and the art work <em>Anatomy of AI</em> (with Vladan Joler) shows how immediate AI interfaces actually mobilize global infrastructures. We will also look at work by, for example, Louis Chude-Sokei about how 19<sup>th</sup> popular culture compared early automatons and enslaved African Diasporic peoples, as well as how contemporary artists like the Raqs Media Collective, or filmmakers Saul Williams and Anisia Uzeyman and their movie <em>Neptune Frost, </em>look at how automation involves contemporary factory workers in South Asia as well as coltan miners and computer programers in East Africa. Alongside this, the course will look at how automation has been the focus of work by U.S.-based artists and theorists of the 1960s and today like Robert Morris and Anika Yi, and Shulamith Firestone, Neda Atanasoski, and Kalindi Vora, andin doing so ask students to make connections between the local and the global and the present and the past, and to consider how “automation” is always connected to questions of social difference and economics.</p> <p><em>Additional Core Requirement met: Global Connections. Same as ARTH 295 with the same subtitle.</em></p> <p><strong>Computing in Real Life Internship</strong></p> <p>Students will work with LA-based non-profits such as STEAM:CODERS, a Pasadena-based organization that teaches local middle and high school students to program, or the Association for Women in Mathematics, a national organization that promotes women in computation. Students will complete weekly reflection papers and a final presentation describing what they have learned about computation IRL. <em>Open only to students enrolled in the Computing IRL semester.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14877,2027,4139,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/200/comp-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14878,2027,2618,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-313','<div class="desc"> <p>The key to the animation and videogame industries is the ability to display simulated worlds in real time. Starting with representing 3D space, this course will teach students the data structures and algorithms, such as quadtrees, texture mapping, and ray tracing, to create photorealistic images.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14879,2027,1650,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-317','<div class="desc"> <p>This course introduces the principles of algorithm design and the theory of computation. Students learn how computational problems are expressed as precise, step-by-step procedures - algorithms - and how such procedures shape the practice of computer science. The course examines major design paradigms, including greedy methods, divide-and-conquer, dynamic programming, and algorithms for flows and cuts, along with the analytical tools used to evaluate their efficiency. Additionally, this course goes beyond algorithm design to consider the limits of computation: when certain problems cannot be solved efficiently, or at all. This exploration leads to the study of NP-completeness and the foundations of computability theory. Together, these perspectives reveal both the power and the boundaries of algorithmic thinking.</p><p><br/></p><p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 229 , and COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14880,2027,2858,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-319','<div class="desc"> <p>Knowledge Representation and Reasoning is the area of Artificial Intelligence concerned with how knowledge can be represented and how automated systems can reason about that knowledge. In this course, we will learn how to use symbolic notations to represent knowledge, including how to represent objects, events, time, space, and language. We will also learn how to use automated reasoning systems to manipulate these representations and derive new knowledge. This will be a hands-on course in which we apply concepts from philosophy, psychology, and cognitive science to build systems that can reason about real-world problems.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 or COGS 242 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14881,2027,2784,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-325','<div class="desc"> <p>This course covers select topics in artificial intelligence, including: reinforcement learning, Bayesian networks, and cognitive architectures.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 131 , COMP 181 , COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14882,2027,2711,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-331','<div class="desc"> <p>The wealth of textual information online and elsewhere makes the ability for computers to understand and generate text particularly valuable. This course will explore both the traditional, linguistic approach to understanding language, as well as modern information retrieval and statistical big data approaches. Topics include information retrieval, search engines, parsing, Markov models, and knowledge representation.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14883,2027,1651,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-337','<div class="desc"> <p>Most other computer science courses use programming languages as a tool for expressing algorithms; this course will examine the programming languages themselves and their implementation. Over the semester, students in this course will build an interpreter for a new language, and in the process be introduced to topics such as parsing, closures, type systems, and lambda calculus.</p> <p><span style="font-size:14px">Sub-field: SOFTWARE</span></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14884,2027,2547,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-340','<div class="desc"> <p>This course focuses on the process and technology behind making intuitive and useful websites and the techniques for determining the effectiveness of the products, including prototyping and user testing. Students will also explore how principles of attention, perception and cognition relate to user experiences.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 , COMP 181 , COMP 229 , or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14885,2027,2506,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-347','<div class="desc"> <p>Many recent advances in artificial intelligence are not in symbolic systems, but in statistical machine learning and data science. This course offers a balance between the theory and practice of data science, from collecting and understanding the data, to developing supervised and unsupervised models (such as linear regression, support vector machines, K-means and Gaussian mixture clustering, principle component analysis, neural networks), and finally interpreting the predictions and their limitations. Discussion of potential bias in the real-world applications and implementation of machine learning algorithms will be included.</p> <p>Sub-field: <strong>ARTIFICIAL INTELLIGENCE</strong></p> </div>','COMP 229 and ( MATH 210 and MATH 214 , or COMP 149 ) and ( COMP 146 or MATH 150 ) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14886,2027,2785,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-349','<div class="desc"> <p>Robotics offers one of the most integrating domains for computer science. Creating a working, human-facing robot brings together hardware and software, artificial intelligence and human-computer interaction. Topics include Simultaneous Localization and Mapping (SLAM), path planning, object recognition, basic mechanics, and social robotics.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14887,2027,2651,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-352','<div class="desc"> <p style="margin-left:0px; margin-right:0px;">This course discusses the theoretical foundations of computing and the limits to computation itself. Topics include state machines and automata, general recursive functions, and their relationship to the Church-Turing thesis. The course may also survey decidable and undecidable problems, as well as “hard” (NP-complete) problems and what makes them hard.</p> <p style="margin-left:0px; margin-right:0px;">Sub-field: <strong>THEORY</strong></p> </div>','COMP 149 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14888,2027,1324,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-353','<div class="desc"> <p>An introduction to information theory that will focus on: (1) data: transmission, storage, lossless data compression (such as ZIP and LZW), lossy data compression (found in JPG or MP3 formats), channel capacity; (2) coding: optimal codes, error correcting codes, the several coding theorems of Claude Shannon; (3) measures of information: entropy, relative entropy, relation between entropy and information content; and (4) application topics that vary from year to year and might include: signal processing, image processing, pattern recognition, cryptography and data security, quantum computing, data analysis, and more.</p> <p>Sub-field: <strong>THEORY</strong></p> </div>','COMP 149 , or MATH 210 and MATH 214 ; COMP 146 or MATH 150 recommended ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14889,2027,2859,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-355','<div class="desc"> <p>This course will teach students both front-end and back-end techniques necessary to build web applications. Students will learn how to make interactive websites, how to structure and manage content for websites in databases, and how to create data-driven web applications.</p> <p>Sub-field: <strong>SOFTWARE</strong></p> </div>','COMP 229 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14890,2027,2786,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-357','<div class="desc"> <p>Much of the power of computers is that they are not individual machines, but units on a network that can exchange information. This course starts with the transmitting binary electrical signals, then builds up to the TCP/IP stack and the algorithms involved, and finally current research questions in the field.</p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14891,2027,2329,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-367','<div class="desc"> <p>The largest programming projects are completed by multiple computer scientists working together. Clients across Eagle Rock and the Oxy community will propose problems with computational solutions, which we will complete in teams as a semester long-project. Using standard tools, such as version control, we will apply the principles of user-centered design to software: understanding the needs of the client, developing software, and testing the product with the user, before repeating the cycle. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 131 , COMP 181 , or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14892,2027,2588,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-373','<div class="desc"> <p>Any large amount of data, such as that stored by Google or Facebook, requires specialized algorithms to ensure consistency and efficient access. From relational models and SQL to newer graph databases, students will understand how to represent entities a domain with rows in a database, culminating in a project that uses this knowledge in a real-world setting. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14893,2027,2787,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-379','<div class="desc"> <p>An operating system ties together the hardware and software components of a computer. For interested students, this will likely be the final step to completely understanding what happens when code is executed. Topics include virtual memory, file systems, process management, parallel computing, and others. </p> <p>Sub-field: <strong>SYSTEMS</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14894,2027,4026,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-383','<div class="desc"> <p>The security of computer systems is a topic relevant at both the personal and the national levels. This course introduces students to the subject of computer security, teaching them the techniques an adversary might use to compromise a computer system, and what safeguards exist to prevent such unauthorized access. </p> <p>Sub-field: <strong>SECURITY</strong></p> </div>','COMP 229 and COMP 239 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14895,2027,2713,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-389','<div class="desc"> <p>Security on the internet is fundamentally based on the mathematical properties of the algorithms we use to encrypt our data. This course teaches students the theory behind these algorithms and how future advances such as quantum computing may affect current standards of security and privacy. Topics include ciphers and frequency analysis, private and public key cryptography, randomness, and quantum cryptography.</p> <p>Sub-field: <strong>SECURITY</strong></p> </div>','COMP 149 , or MATH 210 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14896,2027,2510,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-390','<div class="desc"> <p>This course focuses on responsible conduct of Computer Science. Students will explore the effects of technology on the modern world, including issues of electronic voting, personal security and privacy, intellectual property, and others. This course will culminate in a research paper on one of these topics, examining the technical background, as well as the social forces that contextualize the issue. Students should have an understanding of the challenges of writing software, and why certain questions are computationally difficult (that is, require significant time/memory). </p> </div>','COMP 101 , COMP 229 , and one 300-level or above COMP course ','A second 300-level or above COMP course',NULL);
INSERT INTO course_descriptions VALUES(14897,2027,3272,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-393','<div class="desc"> <p> Students engage with open problems in an active area of faculty research. May be repeated once for credit. Instructor permission required.</p> </div>','COMP 131 or COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14898,2027,1689,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-395','<div class="desc"> <p>Topics vary semester to semester.</p><p><strong>Deep Learning</strong></p><p>This course will begin with an exploration of the mathematics behind deep learning and how to build simple neural networks from Python mathematical primitives. The course will then pivot to exploring modern deep learning architectures and implementing systems using frameworks such as PyTorch, and experiment tracking tools such as MLFlow. Students will explore applications of deep learning such as computer vision, natural language processing, and neural networks for scientific applications. At the course''s conclusion, students will research deep learning applications for a domain of their choice. Some experience with Calculus (High School is fine) and proficiency with Python is required. Linear Algebra is helpful to know but not required.</p><p>Prerequisite: Calculus I and COMP 131</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p><strong>Artificial Intelligence and Learning Technologies</strong></p><p>This course will cover many topics relevant to the design of learning technologies. The beginning of the class will cover theories of knowledge and learning (i.e., behaviorism, constructivism, cognitivism) and their implications for the design of computer-assisted learning technologies. This will be accompanied by a survey of the history of attempts at teaching machines. The class will culminate in a project where multidisciplinary teams of students design and prototype new learning technologies.</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p><strong>Social Data Science</strong></p><p>This is a team-based course where students will develop a research project that applies data science methods to address a problem in social science or business contexts using social data from online platforms. We will cover key considerations in research design, data collection from digital platforms, and the applications of natural language processing, machine learning and statistical methods for social data mining and analysis. Students will read research papers that employ computational approaches to analyze social media data and participate in group discussions, hackathons, and project presentations. This course aims to offer perspectives in computational social science research and hands-on experience in designing and executing a data science project. It is open to students from both social science and computer science backgrounds who are interested in social data analytics and research.</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p>Prerequisite: COMP 131 or COMP 146</p><p><strong>Game Engine Development</strong></p><p>Video game engines are often overshadowed by the games built on top of them, but they are complex pieces of software in their own right. This course will explore the major components that make up a game engine, such as graphics rendering, audio, and networking systems; collision detection and handling; 2D and 3D object and world modeling structures; all the way to game AI and custom scripting programming interface. Over the semester, students in this course will build a usable game engine from scratch and demonstrate its functionality with a game using it.</p><p>Sub-field: SOFTWARE</p><p>Prerequisite: COMP 229 and COMP 239</p><p><strong>Interactive Systems for Enhancing Movement</strong></p><p>This class applies computer science in the context of interactive systems to enhance human activities that involve movement, such as dance or sports. The course will go through examples of how sensors are used in diverse physical activities, including how to get movement signals through user-studies, how to evaluate the results, how to process the signals, and how to classify and determine if a movement is "correct" or "incorrect". Students finish the class by designing and evaluating their own projects in an activity that they are passionate or curious about.</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p>Prerequisite: COMP 131</p><p><strong>Modeling and Simulation</strong></p><p>A computer model is a hypothesis, formulated with a specific purpose in mind and represented as a computer program, about some aspect of concrete or imagined reality. A model can be "brought to life" through computer simulation. Computer models play an important role in business and policy as well as in engineering and the social and natural sciences, and we interact with them on a daily basis whether we realize it or not. These models, the nature of the "knowledge" they provide, and the implications of their use are the subjects of this course. An introductory familiarity with computer science is enough to build and work with simple computer models, valuable in themselves, that can also form the building blocks of more complex models. Focusing on these simple models, this hands-on course will address model-building, model fitting and validation using data, and model simulation for prediction and decision-making. At each of these stages we will also study questions of approximation and bias, and their implications. Examples will be drawn from a wide range of phenomena but will not require prior expert knowledge.</p><p>Sub-field: SOFTWARE</p><p>Prerequisites: COMP 131</p><p><strong>Data Mining</strong></p><p>This course covers computational approaches to uncovering information and patterns in data. Students will learn techniques for visualization of numeric and non-numeric data, data preprocessing, pattern extraction, clustering, and text mining. These techniques will be linked to human perception and other methods for evaluation.</p><p>Sub-field: ARTIFICIAL INTELLIGENCE</p><p><strong>Abolish Silicon Valley?</strong></p><p>The tech industry is known for well-paying jobs that offer the opportunity to work at companies making bold claims about their contribution to social betterment. Yet, those job benefits are only available to certain workers and "tech" is increasingly associated with income inequality, automated job loss, algorithmic bias, surveillance, the commodification of everyday life, and ecological damage. This course borrows its title from Wendy Lui''s recent book on her experience as a tech worker and will ask students to (re)consider the politics of tech today, their own potential place in the tech industry, and alternatives to the current organization of techno-capitalism.</p><p><strong>Computer Architecture</strong></p><p>This course is intended to provide a foundation in performance programming and computer architecture. Students will better understand how software interacts with hardware and how trends in technology, applications, and economics drive changes in computer architecture. The course will cover the following topics: caches, virtual memory, memory system, parallelism, pipelining, superscalar, speculative out-of-order execution, vector, VLIW, simultaneous multithreading, graphics processing units, chip multi-processors, and domain specific accelerators. Students will read research papers on the topics described above. We will use processor simulators to explore design choices relevant to each of these topics. The objective is for you to understand all major concepts used in modern CPUs at the end of the class.</p><p>Sub-field: SOFTWARE</p><p>Prerequisites: COMP 239</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14899,2027,506,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/comp-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14900,2027,2712,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/300/copy-of-comp-371','<div class="desc"> <p>Smartphone apps, in their limited computational power and radically different form factor, impose new constraints and challenges different from the development of other software. In this class, students will be introduced to mobile architecture and related concepts such as monetization, privacy, analytics, and cross-platform development.</p> <p>Sub-field: <strong>INTERFACES</strong></p> </div>','COMP 131 and COMP 229 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14901,2027,4140,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/400/comp-467','<div class="desc"> <p>Many disciplines rely on large data collections to make informed disciplinary conclusions. At the same time, disciplinary knowledge is crucial to extracting the important information from the data. This project-based course will engage teams of students, at the junior level or above, from computer science and other disciplines to analyze real world data using techniques of data analysis, visualization, and interpretation. Topics will include data cleaning, feature selection, and techniques from statistical inference and machine learning, combined with domain-specific knowledge. The course will be team-taught by faculty in Computer Science and the discipline of the application. May be repeated once for credit when disciplinary combinations differ.</p> </div>','BIO 268 , COMP 146 , MATH 150 , or PSYC 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14902,2027,2540,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/400/comp-490','<div class="desc"> <p>This course will support senior Computer Science majors as they conduct projects as part of their Senior Comprehensive requirement. Students must have senior standing to enroll.</p> </div>','COMP 390 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14903,2027,4141,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/400/comp-497','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14904,2027,4142,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/comp-computer-science/400/comp-499','<div class="desc"> <p>Computer Science majors who wish to seek departmental honors must enroll in this course to extend their comprehensive project beyond what was accomplished in COMP 490. Credit for this course does not automatically confer honors.</p> </div>','COMP 490 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14905,2027,2723,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/copy-of-core-98','<div class="desc"> <div><div><p>This course is designed to expose students to some of the many cultures of Los Angeles, a vibrant microcosm of the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one unit of credit for participating in eight off-campus "field experiences.â Students will select these from a list of destinations provided by the course instructor and are responsible for documenting each field experience using Canvas. Students will be required to submit at least two short response papers related to their field experiences. This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements. Students may take this course twice, for a maximum of two units being applied toward the degree.</p><p><br/></p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14906,2027,4015,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-100','<div class="desc"> <p>A 1-unit course in which Oxy faculty guide students through the analysis of a current event or issue through the intellectual perspectives of one or more academic fields.</p> <p>3 hours per week for a full semester course. 6 hours per week for a half semester course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14907,2027,4143,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-101','<div class="desc"> <p>This summer virtual course is part of the Humanities for Just Communities (HJC) curriculum, which aims to demonstrate the power of the Humanities to address a different social justice issue each year. Open only to incoming first-year students. Graded on Credit/No Credit basis only.</p> <p><strong>Protest, Abolition, and Freedom Movements</strong></p> <p>In summer 2024, the HJC summer virtual course will introduce incoming Oxy students to the range of ways Humanities disciplines study protest, abolition, and freedom movements. For each module of the course, students will watch a recorded lecture and engage with assigned readings from faculty members across a range of fields, including American Studies, Art History, Black Studies, History, Media Arts &amp; Culture, Philosophy, and Religious Studies. Students will write their initial responses to these materials and then meet with classmates and the faculty member to discuss (two discussion sections each week). By the end of the course, students will have learned about a range of specific topics related to protest, abolition, and freedom movements, and they will be exposed to the various methodologies employed by Humanities disciplines. The summer course is also a great way to become familiar with college-level expectations and to meet classmates and faculty before arriving on campus in the Fall.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14908,2027,3013,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-111','<div class="desc"> <p>This topics course is a component of the Multicultural Summer Institute (MSI). Different topics may satisfy different Core requirements. Open only to incoming first year students accepted into the MSI program.</p> <p class="sc-BodyText"><strong>(Im)migrant Communities of California</strong></p> <p>This course offers students the opportunity to analyze the sociohistorical, legal, and cultural tensions surrounding various (im)migrant communities in California. Students will explore the various waves of (im)migration across time to understand the diverse communities of California. Students will also build critical and interpretive capacities through the examination of state policies, statistics, and various historical and empirical studies. Additionally, through the construction and revision of several expository, research-based writings on immigration, students will hone their writing, argumentation, critical thinking, and presentation skills. <em>Core Program Requirement Met: United States Diversity (CPUD).</em></p> <p><strong>Imagining The Future</strong></p> <p>This course on Anglophone literature, postcolonialism, and the African diaspora proposes to critically investigate the concept of time. In particular, we will examine how time provides a crucial framework for how we imagine the future. We will take the seemingly self-evident concept of time and critically examine its intellectual history to consider how time serves a crucial function as a means of ordering our cultural, economic, and political ideas as well as our individual lives. Frameworks of history, modernity, and futurity rely on concepts of development and progress that are related to broader ideas of race and sexuality. In what ways do historical representations of time, development, and progress structure how we imagine the future? On whose behalf is progress being imagined? Where is progress located? What are the ideals of the future? Whose pasts are connected to the futures that we privilege? In considering these questions, we will examine a range of novels, films, empirical studies, and cultural theory that provide a complex portrait of how the future is imagined, especially from the perspective of those scripted out of its dominant narrative. We will engage with critical and literary approaches including Afrofuturism, queer futurity, the developmental novel, economic models, and science fiction.</p> <p><strong>Mutual Aid: Literary Representations of Relief and Collective Care</strong></p> <p>This course considers how literature deepens our understanding of "mutual aid," one of the most pressing themes in today''s political, popular, and academic conversations. The course asks, is mutual aid merely a short-term practice during mass emergencies or does it provide an alternate viewpoint for communal self-reflection and structural transformation? Can we think about using the principles of mutual aid to make lasting changes in social relationships and political structures? </p> <p>In this class we will use the concept of mutual aid to break down traditional binaries between surviving and thriving or pragmatism and idealism. We will think through the utopian ideal of mutual aid as a possibility for real political and social intervention. The literary works we will read allow us to imagine how the seemingly impossible becomes possible through the mundane uses of mutual aid. In addition to reading memorable works of literature in the historical contexts of Black and Brown and queer communities, this course will devote consistent attention to the mechanics of writing persuasive thesis-driven essays, an essential skill for succeeding at Occidental. Readings will include Richard Wright’s short fiction “Down by the Riverside,” William Still’s compilation <em>The Underground Railroad</em>, and Shani Mootoo’s <em>Cereus Blooms at Night</em>. <em>Core Program Requirement Met: Global Connections (CPGC).</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14909,2027,3057,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-112','<div class="desc"> <p>The Engaged Reflections on Social Justice (ERSJ) required component of the MSI program links academic content to diversity dialogue frameworks to help students cultivate the knowledge, skills, and attitudes associated with effective classroom engagement, socially responsible leadership, community and cohort development, and conflict resolution while also promoting practices of self and community care. The ERSJs serve as an important foundation for students to understand power and their relationship to the systemsthat undergird injustice and disparate outcomes. Self-awareness, awareness of others, and defining leadership for social change are the three primary themes that will connect the various topics we will cover in the seminar. Only open to first-year students.</p> </div>','CORE 111 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(14910,2027,4027,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-115','<div class="desc"> <p>What does it take to be an entrepreneur? Entrepreneurship is about imagining a new venture and taking steps to implement that vision. This path can be difficult, complex, and risky, but also has the potential for substantial meaningful impact and rewards. In this course, we will explore the entrepreneurial process. You will learn how different types of business structures shape a companyâs foundation, what it takes to fundraise (if it is that kind of company), and the everyday concerns of running the company that evolve through the various stages of its development.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14911,2027,3852,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-117','<div class="desc"> <div><p>This course examines the role of entrepreneurs in generating replacements for the status quo. Throughout this course, we''ll focus on entrepreneurshipâs intersection with citizenship in the context of Los Angelesâa city filled with diversity and innovation.</p><p><br/></p><p>Weâll take a multidisciplinary approach to understanding entrepreneurship across domains, including commerce, culture, and society. We''ll examine how entrepreneurs navigate change differently, their motivations to start new ventures, the impact of policies and norms on founders, the dynamics of entrepreneurial ecosystems, and the entrepreneurial potential of urban environments. Through interaction and collaboration, you''ll gain knowledge and analytical skills for understanding entrepreneurial activity.</p><p><br/></p><p>We''ll also examine emerging ventures poised to shape Los Angeles in the coming years. By developing an informed perspective on these loci of transformation, you''ll become better equipped to take an authentic position on relevant debates. Through these case studies, you''ll be empowered to contribute meaningfully to the entrepreneurial landscape as participants in a new venture or as a stakeholder in their ends.</p><p><br/></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14912,2027,4144,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-120','<div class="desc"> <p>This course is designed to develop students'' ability to engage a wide, diverse audience in a better understanding of the goals, processes, and outcomes of scientific research. Coursework will involve attendance at science-oriented seminar talks at the College, reading and discussion of scientific papers, and oral and written presentations by the students of research proposals and research findings. Open only to juniors and seniors majoring in STEM departments or permission of instructor. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14913,2027,4145,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-127','<div class="desc"> <p>In October, 2023 war once again erupted between Hamas and the Israel; this was the latest â and perhaps most horrific â round of bloodshed in the more than century-long conflict between Palestinians and Jews in the strip of land between the Jordan River and the Mediterranean Sea. The horror reverberated far beyond Israel-Palestine. The world has been divided into opposing camps, with some describing the conflict as an existential war of survival, and others, as a genocide. College campuses, online communities, city councils, and even families in America and around the world found themselves divided over which side was right and which side wrong, who was the victim and who the oppressor.</p> <p>The course will begin with a historical introduction to the Israeli-Palestinian conflict. We will review the pre-1948 origins of the conflict, major events (including the 1948-49 Nakba/War of Israelâs independence, the Six Day War of 1967 and Israelâs subsequent occupation and settlement of the conquered territories, the 1973 war and the peace treaty between Egypt and Israel, Israelâs invasion of Lebanon in 1982, the intifada, the rise and fall of the Oslo Peace Process, the emergence of Hamas in Gaza, and more). We will examine the shifts in both Israeli and Palestinian politics over these decades, and the current political situation in Israel and Palestine today. We will look at the critical and controversial role of the United States in the Middle East, and at the changing state of US public opinion regarding Israel-Palestine. We will also review the often-conflicting narratives of connection to the land and claims of indigeneity of those involved. The course will include a particular focus on the efforts of those trying to bridge the divides not only between Palestinians and Israelis in the region, but also between their warring camps of supporters around the world.</p> <p>Throughout the class we will focus on the ways we talk â and donât talk - about the conflict. The course will examine why the issue of Israel-Palestine is so hard to discuss, let alone agree upon; why it invokes such strong passions and emotions in so many people, including those who understand very little about the conflict at all. We will seek to unpack, understand, and talk productively about some of the âhot buttonâ issues that tend to roil the discourse about Israel-Palestine (the meaning and role of Zionism, the Boycott Divestment and Sanction movement, the role of terrorism, Israelâs settlement enterprise in the West Bank, charges of apartheid and war crimes, etc.).</p> <p>The course will meet weekly, and will feature a number of guest lecturers, including activists, peace negotiators, and former combatants working to resolve the conflict, and those working to build bridges of understanding between Arabs, Jews, and others here at home. Readings will include material about the conflict and how it has impacted policy, politics and community relations in the United States, as well as materials from the fields of cognitive linguistics and political psychology that focus on how and why certain conversations are so difficult, and how best to address those challenges.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14914,2027,4146,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-200','<div class="desc"> <p>Intensive study under the direct supervision of a faculty member on an scholarly research or creative project developed by the student. Participation in Summer Research Program professional development and mentoring programming. Presentation of project at URC''s annual research conference. Enrollment is contingent upon acceptance to the URC''s summer research program either through award of the Summer Research Program, affiliated fellowship, or direct funding support from a faculty mentor. May be repeated twice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14915,2027,3316,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-227','<div class="desc"> <p>This class is an introduction to the historical art of letterpress printing using design elements with text and image. Students will complete a collaborative artist book with hand binding and original imagery using typographic design, hand typesetting, and letterpress printing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14916,2027,4147,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-397','<div class="desc"> <span style="color: #282b2c;">Independent study project. Permission of instructor and department chair required.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14917,2027,3951,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-94','<div class="desc"> In an increasingly complex, interdependent and pluralistic world, the ability to engage in conversations reflecting different perspectives is essential for fostering understanding and community. This course engages students in a diverse set of events designed to challenge perspectives, build empathy, and cultivate connections among individuals from varied backgrounds. To receive credit, students must engage with at least eight (8) designated events during the course of the semester and complete two short reflection papers. Students will select these events from a list available on the course’s Canvas page. This course is graded CR/NC and does not fulfill any major, minor, or Core requirements. Students may take this course twice, for a maximum of two units being applied toward graduation. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14918,2027,2867,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-95','<div class="desc"> <p>The goal of this course is to provide students with academic, social and personal skills including reading and study strategies, procrastination and time management, and more, to aid in students'' academic success and integration in their first year of college. </p> <p>Through workshops and guest lectures, students will learn how to access campus resources and opportunities, to help them build social capital and community within the Oxy campus. This course emphasizes student development and provides specific support for first-generation students. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14919,2027,2728,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-96','<div class="desc"> <p>This course is designed to expose students to mathematics and science to broaden their awareness of the research questions asked in these disciplines and to introduce skills and ideas scientifically shown to improve persistence in college especially in science and math majors. Students may acquire one semester unit of credit for attending eight on-campus events during a semester. Certain seminars and class meetings will be mandatory; students will select additional events from a list of events provided each year by the instructor. A short two-page paper is due on the last day of class. This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14920,2027,2903,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-97','<div class="desc"> <p>This course is designed to expose students to some of the many cultures of the world, to prepare students for a future in the "complex, interdependent, pluralistic world" of the 21st century described in Occidental College''s mission statement. Students may acquire one semester unit of credit for participating in eight "field experiences" in their local area. Students will select these from a list of destinations provided by the course instructor and are responsible documenting each field experiences using Moodle. Students will also be required to submit two short response papers related to their field experiences.</p> <p>This course is graded CR/NC only and will not meet specific Major/Minor or Core requirements.</p> <p>Students may take this course twice, for a maximum of two units being applied toward graduation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14921,2027,2724,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/core-core-program/courses/core-99','<div class="desc"> <div><p>This course is designed to expose students to the diverse array of artistic events that are held each semester on the Occidental campusâfrom musical and theatrical performances to art openings and film screenings and more. To receive credit, students must engage with at least eight arts events during the course of the semester and complete two short reflection papers. Students will select these events from a list available on the courseâs Canvas page. This course is graded CR/NC and does not fulfill any Core requirements. Students may take this course twice, for a maximum of two units being applied toward graduation.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14922,2027,4433,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-106','<div class="desc"> <p>Looking back on the momentous changes and shock experienced by his generation with the advent of the first world war, Walter Benjamin wrote: âA generation that had gone to school in horse-drawn streetcars found itself under open sky in a landscape in which only the clouds were unchanged and below themâ¦crossed by devastating currents and explosions, stood the tiny, fragile human body.â This course explores the sense of profound change described by the chroniclers of 20th century modernity, and connects it to modernism, that force which sought to disrupt literary and aesthetic tradition and unsettle long-held conceptions of the self, identity, justice, and political authority. Injunctions made to the literary form of the novel are examined through the humorous prose stylings of early modernist Robert Walser, while Brechtâs epic theater serves as a case study in the radical potentials of early 20th century drama. We will also focus on the poetry of Rilke, Bachmann, Celan and others. Finally, the legacy of the crises of modernity (modern warfare, fascism, ecological destruction) and modernismâs responses will be reflected on via a reading of W.G. Sebaldâs Austerlitz. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14923,2027,2653,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-107','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though very different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14924,2027,2546,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-108','<div class="desc"> <p>Taught in English. This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14925,2027,1507,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-109','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables, and riddles, to anecdotes, jokes, short stories, and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include: Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin, and Twitter. All readings and discussion in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14926,2027,2701,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-112','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes from the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14927,2027,3335,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-113','<div class="desc"> <p>Although the first volume of the Grimms’ Children Stories and Household Tales was published more than 200 years ago, their fairy tales continue to enchant contemporary readers. In this course we will not only study the Grimms’ fairy tales themselves and rediscover their enduring magic, but also take a look at their origins and their social, ideological, and political contexts in 19th-century Europe. We will work with fairy tale theory (narrative, psychoanalytic, historical) and discuss the function of the tales for adult communities as well as their status as children’s literature. Alongside the “original” Grimms’ tales—a concept that we will discuss—a major portion of the course will engage the legacy of the fairy tales and the way they have been appropriated by others, particularly from a critical, feminist perspective.</p> <p> Points of emphasis will include: how writers in the first half of the 20th century politicized the tales in the battle for societal change during the time of the Weimar Republic and Nazi Germany; how the tales were reinterpreted in different national traditions and historical periods; how the fairy tale becomes a mass culture icon in Disney’s film versions; and how contemporary writers like Margaret Atwood continue to employ fairy tales to question the construction of gender and carve out new possibilities for relating to one another.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14928,2027,4148,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-114','<div class="desc"> <p>Statesman, scientist, philosopher, poet, and in the words of Friedrich Nietzsche, “the last German before whom I felt reverence”, this course will examine the life and work of Johann Wolfgang von Goethe. Widely regarded as the Shakespeare of German literature, Goethe’s status as the major influence on the course of not only 19<sup>th</sup> century German but European literature was long simply assumed. Yet for a figure of this stature Goethe seems to embody a contradiction. No one quite knows what he stands for. Is Goethe the young Romantic of his youth; the aristocrat and politician of his middle period and founder of the coming of age novel, in which, as Hegel put it, “the hero loses his horns”; or is he the mad scientist of his later works which he canonically etches into literary history in form of <em>Faust</em>? We will investigate these transformations and contradictions by asking how Goethe’s almost obsessive quest for unity and form can be reconciled with the turmoil, change and disruption so emblematic of his life and work. We will do so by reading the canonical novels and dramas from his early, middle, and late periods, while also spending time with his scientific writings and the most beautiful poetry the German language has to offer. In short, we will examine Goethe not just as an author, but as a practitioner of the art of living. What does It mean to be young, mature, grow old and die? To fashion a self out of the turbulence and change that dominated not only Goethe’s age, but our times as well? We will seek guidance in these questions by examining the interrelationships between Goethe’s life, work and the age that came to be known as the <em>Goethezeit. </em>Reading and discussion will be held in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14929,2027,2735,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-115','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus, by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14930,2027,2821,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-116','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and fallibility. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in-depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14931,2027,2893,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-118','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process-oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14932,2027,1685,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-120','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus, begins Ovid''s <em>Metamorphoses, </em>whose programmatic opening stanza links the birth of the world, from formlessness and chaos, to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotica; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14933,2027,3058,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-122','<div class="desc"> <p>After the end of WWII, the generation of what would become known as the 68ers found themselves in a precarious position. They came into adulthood to realize that their parent’s generation were if not perpetrators then at least accomplices to one of the gravest genocides in human history, that they had enthusiastically endorsed a fascistic maniac, that the country they inhabited stood in ruins, bombed to the ground morally and physically, and that they now stood at the epicenter of the cold war, half capitalist, half communist. From the perspective of the 68ers, the worst of all was that there had been no cultural reckoning. With the conclusion of the Nuremberg trials and the prosecution of the elite Nazi administration, the majority of the population seemed content to simply to forget. For the 68ers that was not an option. Rather than view the WWII and the Holocaust as an aberration and horrific exception to German culture, the youth of the 68er generation demanded a revolutionary reevaluation of everything German. They asked: What factors, economic, social, cultural, and historical, led to this catastrophe? How can we come to terms with this past? And what vision of a transformed future could replace the old? The answer to these questions involved a three-step approach. A radical critique of the past and the structures of nationalism, patriarchy, heteronormativity, racism, and capitalism, which they believed were the foundational underpinnings of German fascism. Active political dissent that demanded change and culminated in the domestic bombings of the left-wing group the Red Army Faction. And a total re-conception of the norms of society, sexuality, and selfhood perhaps best represented in the Love Parade and the drugs, sex, and radical experimentation that fueled the raves and Berlin techno scene after the fall of the Berlin Wall.</p> <p>This course will investigate the transformations of postwar German society in the literature, philosophy, film, photography, and art of the time. We will focus on the social critiques of the Frankfurt School of Critical Theory, political resistance in both the communist East and capitalist West Germany as well as the life in and relationship between the two, and the utopic visions of the postwar German left as well as the success and failures of this radical political movement. Readings and figures may include: Adorno, Horkheimer, Marcuse, Deleuze, Foucault, Crista Wolf, Max Frisch, The Baader-Meinhof Complex, Rainald Goetz, Anselm Kiefer, Helene Hegemann, and Felix Denk.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14934,2027,3315,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-130','<div class="desc"> <p>Do we live in the era of post-truth? Is everything just another piece of propaganda? Whom do we trust and why? </p> <p>Postmodern theory offers us powerful resources to criticize and take down the houses of totalizing ideologies, but many of its most important conceptual tools have been co-opted and are now used to oppress. Postmodern propaganda corrodes the relationships of trust that connect us, and makes us feel isolated and powerless. It taps into our fears and phobias to destroy not only the reality around us, but also our humanity. The organized lies of the 21st century aim to confuse and disorient, but also (and this is where the greatest danger lies) make us cynical. Several philosophers and writers from Eastern and Central Europe, who had first-hand experience of Western European “demi-Orientalism,” Russia’s imperialism, and Soviet totalitarianism, offer an antidote to this postmodern condition. </p> <p>In this course we will read French theorists such as Deleuze and Derrida and their counterparts from Eastern and Central Europe: Havel, MiÅosz, Mamardashvili, Venclova, and others. Several other philosophers and writers—such as Plato, Arendt, Kundera, Orwell, Klemperer, and Platonov—will help us think about truth, trust, and propaganda.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14935,2027,1642,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-131','<div class="desc"> <p>The worldview and beliefs of the early Slavs, particularly the Eastern Slavs, were a complex synthesis of influences: Indo-European mythology, Central Asian shamanism, Scythian animal worship, and, ultimately, a "paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600, in order to understand how these people viewed the world, and how this affected their lives and the development of Slavic culture. Communal village life, legends, folk genres and mythology, their sources, and their legacies, are examined. There is a close study of the phenomenon of the vampire, following its evolution from the Iron Age into 18th century Serbia, as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined, as well. In addition to analytical and historical texts, readings include tales of supernatural beings and phenomena, as well as testimony concerning encounters with the supernatural.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14936,2027,1508,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-132','<div class="desc"> <p>Many of Russia’s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements, while at the same time creating some of the most memorable texts of the 20th century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin. The course will introduce students to modern Russian literature, while, at the same time, will examine how Russian writers used science fiction in a completely different manner than Western writers. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14937,2027,3837,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-133','<div class="desc"> <p>There are two fundamental philosophical positions that try to describe our relation to others. The one posits that I am different from you. The other assumes the fundamental unity of human and other beings. Both of these positions lead to serious difficulties. If I am fundamentally different from you, I run the risk of alienation, and confront the impossibility of knowledge. If I begin with the assumption of oneness, I encounter the difficulty of distinguishing myself from you, and the impossibility of agency.</p> <p>Is there a third way that avoids these problems? Could we re-imagine relationships among humans and other beings in a way that preserves a sense of individual selfhood situated within community? Eastern European folklore and mythology give us tools to rethink this contemporary dilemma.</p> <p>We will focus on myths and folk tales from East Central Europe. We will ground our discussion in the historical context of Scythian female warrior culture and some pre-Indo-European beliefs and practices. These cultural phenomena survive in the myths and epics of the Slavs. We will analyze representations and adaptations of these myths and practices in contemporary literature, film, and art from former Yugoslavia, Romania, Ukraine, and other Eastern European countries.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> <p>This course meets the Core Program Pre-1800s Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14938,2027,1686,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-134','<div class="desc"> <p>How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist one century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun," and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency, known otherwise as the Russian Avant-garde. Topics include: poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14939,2027,4149,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-135','<div class="desc"> <p>Leo Tolstoy''s masterpiece <em>War and Peace</em> chronicles the trials of two families living through Russia''s existential fight for survival against Napoleon''s Grande Army. In so doing, Tolstoy addresses questions of nationalism, religion, philosophy and free will as he chronicles in vivid detail Napoleon''s fatal invasion of Russia. Through papers, exams, and class participation, students will analyze the novel from multiple perspectives to fully appreciate the destructive forces behind military adventurism and national arrogance. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14940,2027,2822,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-136','<div class="desc"> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. Authors may include: Tolstoy, Dostoevsky, Turgnev, Gogol, Goncharov, Bulgakov, Pushkin, and many, many others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14941,2027,2941,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-138','<div class="desc"> <p>Should you abandon yourself to the sensual beauty of the world? Or should you embrace a life of asceticism and simplicity? Is there an even more attractive path in between? Is it also a more difficult one? Major works by Russian writers—including Pushkin, Tolstoy, and Chekhov—across a number of literary genres will guide our discussions of these important questions. Knowledge of Russian not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14942,2027,3214,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-139','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>No previous knowledge of either the Russian language or Russian literature is required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14943,2027,1643,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-140','<div class="desc"> Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near-death experiences throughout the Mediterranean. While immensely entertaining and, at times, ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in post-Â­classical literature, art, and film. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14944,2027,4150,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-142','<div class="desc"> <p>This course attempts to recover the largely forgotten perspectives, experiences, interests, voices, and cultures of non-elite people in the Roman world, that is, the entire Mediterranean from 133 B.C.E. to 476 C.E. Today, we usually see Roman history and culture from the perspective of Rome’s elites, because the bulk of the surviving texts were written by or for elites. We shall steer a different course, examining texts and material artifacts produced by, for, or about ordinary people. Topics include Roman childhood and the Roman family, kinship relations, mothering and motherhood, child-rearing practices, children’s experience, the death of kin and commemorative practices; the economic circumstances of ordinary Romans, the nature of work, the terms of lending and borrowing, the experiences and cultures of slave-holding and of enslavement; women’s roles as girl (<em>puella</em>), girlfriend (<em>amica</em>), wife (<em>matrona</em>), prostitute (<em>meretrix</em>), and witch (<em>venefica</em>); sex, sexuality, and dirty songs; the people’s entertainments, such as theater, games, gladiator shows, and popular literature; popular politics and the role of the crowd and common person in public life; the culture of soldiering and the experience of peoples at the borders of empire; popular religious phenomena and the appeal of prophets, priests, and holy men in such movements as Isis worship, Mithraism, and Christianity. The goal of the course is for students to emerge with a holistic understanding of the details of and scholarly theories about non-elite culture in the Roman world, and hence with a heightened ability to identify and critically analyze contemporary discourses about “low” versus “high” culture, which most often remain entirely implicit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14945,2027,2516,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-145','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we''ll also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14946,2027,3927,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-146','<div class="desc"> <div> <div> <p>Free speech was hardly invented by the First Amendment. In ancient democratic Athens, isegoria signified each (free, male) citizen''s "equal right of speech" in the public sphere. The Greeks had another, related but contrasting term, parrhesia, which signified "frankness of speech," or not holding anything back. Meanwhile, the Romans praised libertas, or "liberty of speaking," which citizens in a republic required in order to come together and deliberate about public policy. But these ideals were not always upheld. Indeed, the philosopher Socrates was put to death for his relentless exercise of parrhesia. His frank speech irritated the powerful so much that it cost him his life. The Romans, for their part, categorized some speech as licentia, or "license," because it went too far, violating social norms. When the Roman republic fell, replaced by autocracy and empire, free speech collapsed with it. The trials and tribulations of free speech in the ancient world made it, ironically, the subject of a great deal of speech. Philosophers theorized it, historians historized it, professional rhetoricians lamented attacks on it, and satirists asserted their own freedom of expression by making coded jokes about its suppression. In this course, we sample the literature of free speech in ancient Greece and Rome, trace its fate in the Middle Ages, when the expression of heretical ideas could lead to death, and read classic texts from its resurgence in the Renaissance and after, such as Milton''s Areopagitica. In the last part of the course, we look at how the troubled history of free speech informs the modern era, from John Stuart Mills''s On Liberty, to gradually expanding interpretations of the First Amendment, to the contemporary debates that continue to consume us even now.</p> <p>Satisfies CPPE and CPGC.</p> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14947,2027,4151,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-147','<div class="desc"> <p>In 48 CE, the Roman empress Agrippina - granddaughter of Augustus, daughter of the late and beloved general Germanicus - orchestrated her then-seventeen year old sonâs accession to the imperial throne, after the suspicious death of her husband (also, by the way, her uncle). This new emperor, Nero, would rule for the next fifteen years, and he would become known as one of the most infamous emperors of all of Roman history. In addition to political conspiracies and murders (Agrippina herself being a notable victim), Neronian Rome witnessed a flourishing of culture, with the production of some of the most remarkable works of literature, art, and architecture. This course will investigate the literature, history, and culture of Rome under Nero. We will thus explore a wide range of material, including literary and philosophical texts such as Lucanâs epic poem on the civil war between Julius Caesar and Pompey, the tragedies and philosophical works of Seneca, and Petroniusâ novel, the Satyricon, as well as the art and architecture of Neronian Rome, such as the Domus Aurea (Golden House), the massive palace in the center of Rome commissioned by Nero. Throughout, we will consider what ideological and aesthetic features are common to these works. This course will additionally focus upon the afterlives of Nero and Neronian Rome, beginning with Tacitusâ account of the period in his Annales. We will consider why certain emperors, above all Nero, are remembered in the ancient historiographical tradition as âbadâ. We will also explore the apocalyptic dimension of Neroâs afterlife, including his evolution into the antichrist in early Christian literature. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14948,2027,2702,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-150','<div class="desc"> <p><em>The Literary Mind and the Carving of Dragons</em> is a highly influential work on Chinese literary aesthetics, and its title also suggests two important constituents of the literary composition process by pre-modern Chinese authors: ideas and craftsmanship. By providing an introduction to classical Chinese literature through readings in translation, this course will integrate aesthetic appreciations and cultural understandings of the classical Chinese literature, and help students grasp the conceptions, styles and creative skills of different Chinese authors. The time range will cover the period from <em>The Classic of Poetry (Shijing) </em>through the Qing dynasty. Throughout the course, students will have a basic historical knowledge of the Chinese literary tradition, as well as a sense of how to go about interpreting Chinese literary texts. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14949,2027,4152,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-161','<div class="desc"> <p class="MsoNormal">This course introduces students to key literary texts from Japan’s modern era (1868-present). During this period, Japanese literature and the Japanese written language were reinvented alongside rapid socioeconomic, political, and cultural changes. As Japan experienced the industrialization, economic success, wars, natural disasters, and technological breakthroughs that characterize this period, literature played a key role in forming the national consciousness. Authors examined in this course may include Higuchi IchiyÅ, Natsume SÅseki, Kawabata Yasunari, Tanizaki Jun''ichirÅ, Åe KenzaburÅ, Tawada YÅko, and Murakami Haruki. We will consider works of Japanese literature within their linguistic, cultural, and historical contexts. Through essays, reading responses, and class discussions, students will explore how literature transforms the human experience into words and in doing so transforms the human experience. The course is given in English, but those whose language proficiency permits may choose to reference the texts in the original Japanese.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14950,2027,3982,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-165','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course offers an introductory survey of Japanese culture from its earliest prehistory to the twenty-first century, covering key moments and themes that shaped Japanâs cultural and national identity in the context of local and global transformations. We will examine Japanâs social values, aesthetic expression, religion, and political institutions to understand Japanâs cultural heritage and contemporary society through its transformation from a âfeudal stateâ to a âmodernized nation.â Through secondary scholarship from a wide range of disciplines, we will explore meaningful ways of understanding historical and cultural contexts from diverse perspectives in critical analysis writings throughout the course while considering points of comparison and exchange that relate to our own experiences.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14951,2027,2514,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-181','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women, such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14952,2027,1509,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-182','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell, and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14953,2027,2587,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-186','<div class="desc"> <p>The course will explore the unique sense of tragedy and the tragic in Iranian literature and culture, tracing this fundamental attunement to the world from its Ancient Iranian roots to Ferdowsi’s 11th CE defining national epic — the Book of Kings — through the poetic and intellectual foundations of contemporary Iranian culture — the 13th-14th CE poetic work of Sa’adi and Hafez — and through to modern Iranian music and literature. The course will analyze the specific characteristics of Iranian tragic culture, closely attending to the developing expressions of that tradition in each of the works and eras covered by the course. The course will also take up the long, contested cultural and political history between Iran and, broadly, the West, focusing on the complex and mutually defining interactions between Iran and, first, Ancient Greece and, then, Europe and the US— both before and in the wake of Western imperialism. <br/> </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14954,2027,2652,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-187','<div class="desc"> <p>“The origins of the myth of Prometheus,” it has been said, “are unclear; even in antiquity the story is never told in full.” Right from the very beginning, then—so it would seem--Prometheus arrives on the scene of literature in a torn, dismembered condition, his story diffracted from the outset into a multiplicity of incoherent elements and perspectives: is he a mighty Titan, or merely a trickster? a divine benefactor, or a threat to cosmic peace? an embodiment of the power of thought, or a figure of its eternal helplessness and misery? The primary object of this course will be to survey some of the more impressive and surprising ways in which literature, art, and philosophy have engaged with, and contributed to, the prismatic strangeness of this myth of Prometheus--from the ancient songs of Hesiod and Aeschylus, to the Romantic soundings of Goethe, Shelley and Herman Melville’s <em>Moby Dick</em>; from its intellectual appropriation by Marx, Nietzsche, Heidegger and Freud, to its “plastic” rendering in the murals of Orozco, the statuary of Paul Manship, and the contemporary films of Ridley Scott and Alex Garland (director of <em>Ex Machina</em>). More tentatively, the larger goal of the class will be to consider whether the Prometheus myth in its entirety might not be guided by the reflection that absolute assertions of authority and power always imply their own undoing, and that sovereignty will forever be linked to suffering and to sorrow.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14955,2027,4153,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-188','<div class="desc"> <p>This course will explore the specific and varied ways in which the traditional postcolonial responses to the ideas, practices and techniques of Western modernity and colonialism/imperialism are being reimagined and transformed by contemporary theorists, artists and activists from previously colonized places as they take up the possibilities and limits of their inherited colonial and postcolonial traditions.</p> <p>The theoretical curriculum of the course will pair a careful examination of core theoretical works in postcolonial thought with attention to Iranian contributions to and appropriations of them. The course will thereby give students both a deep and solid foundation in postcolonial theory that will serve them in studying other cultural traditions, while showing the ways in which those core theoretical texts, ideas and approaches can be and are transformed, adapted or rejected under the pressure of historical, political, economic, and social forces, including the literary and language traditions into which postcolonial theory is received. The theoretical curriculum of the course will then explore the ways in which Iranian scholars, activists and artists experience and describe the still-open possibilities as well as the limits of the dominant postcolonial theory in their own work, and the re-imaginations and transformations of those ideas and practices that they introduce or seek.</p> <p>Having established an understanding of the complex relationship between not only Western modernity and postcolonial cultural traditions, but also between various postcolonial cultural traditions, the course will then take up a detailed study of modern and contemporary Iranian and Persianate literature and art as they reimagine and transform these intersecting traditions, discourses and practices in their own artistic projects. Placing the work of contemporary artists, poets and novelists from Iran and the Iranian diasporaâ e.g., Filizadeh, Neshat, Farokhzad, Golshiri, Satrapi and Moshfegh â in the context of the long Persianate cultural history as well as within the discourse and counter-discourse of Western modernity will allow students to see postcolonial thought and practice at work while also gaining a sense of the specificity of cultural re-formulations, transformations and reimagining of them, helping students appreciate the diversity of and tension between postcolonial cultural projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14956,2027,3506,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-190','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the beautiful yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14957,2027,3239,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> <p><strong>To be: Ukranian</strong></p> <p>Ukraine’s rich poetic and revolutionary culture helps one trace routes of escape from oppressive imperial structures. Philosophical and literary texts written by and about Ukrainians will allow us to gain an understanding of this culture, and the works by contemporary historians will help us develop an understanding of Ukraine’s tumultuous history. Philosophers, writers, and historians could include Svetlana Alexievich, Anne Appelbaum, Ivan Kotlyarevsky, Alexander Potebnja, Mykola Riabchuk, Timothy Snyder, Lesia Ukrainka, Oksana Zabuzhko, Serhiy Zhadan, and others. No previous knowledge of Ukrainian history, language or literature is required. Core Requirement Met: Regional Focus.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14958,2027,4154,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/100/cslc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14959,2027,3983,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/copy-of-cslc-202','<div class="desc"> <div><p><span style="font-size: 12pt">The philosopher Martin Heidegger once famously observed that for human creatures such as ourselves, Being is always a matter of Being-</span><span style="font-size: 12pt">with</span><span style="font-size: 12pt">: that is to say, a truly human life is necessarily a life lived in constant relation and reference to other human beings. And yet as Heidegger further notes, this existential condition of sociality depends, fundamentally, on our speciesâ rich capacity for language. In this class, therefore, we shall examine the interplay of language and human social existence, or culture, from prehistoric times to the dawn of modernity itself (roughly, to the time of the Renaissance and the rise of the nation state). In reconstructing this relationship between language and culture, we shall draw on the work of a large array of thinkers, ancient and modern, spread out over a number of academic disciplines: biology, anthropology, history, linguistics, philosophy, sociology, political theory, to name but a few. Yet throughout the class special emphasis will be placed on the question of literature. How does this particularly complex use of language relate to the making, unmaking, and remaking of human cultures in the premodern period? How might it affect our sense of the relationship between language, literature, and culture, today? In pursuit of such questions, </span><span style="font-size: 12pt">the course will take us to regions as various as Mesopotamia and Ancient Egypt, Northern Africa and the Levant, Ancient Greece and Rome, India and Anatolia, Central Asia and Western Europe, and will draw upon written and oral texts as diverse as mythic theogonies and historical king-lists, philosophical disquisitions and religious incantations, publicly staged dramas and privately scrawled graffiti. Specific authors covered may include, but are not limited to, Hammurabi and Jeremiah, Herodotus and Thucydides, Plato and Aristotle, Cicero and Livy, Aurelius and Augustine, Ibn Sina and al-Farabi, Suleiman the Magnificent and Petrarch, Machiavelli and Luther. (Please note: although this course serves in many ways as a prequel to CSLC 203, the two courses can be taken in any order, or indeed quite independently of one another.)</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14960,2027,3300,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/copy-of-cslc-203','<div class="desc"> <p>It is impossible, the philosopher Martin Heidegger once declared, for any human being ever to be truly alone; to exist as a human at all, he argued, is always already to be acting and thinking and feeling in relation to other humans, to be interpreting our own being in relation to those who likewise, and reciprocally, must interpret their being in relation to ours. In this class, we shall examine the ways in which various philosophers and theorists over the last several centuries have conceived this mutually entangled condition of togetherness, this common existential condition of Being-With. We shall inquire, for example, into the ways this condition of shared being has been interpreted politically (in terms of entities such as city-state and nation-state), sociologically (through notions such as community and society), economically (through concepts such as markets and labor), and anthropologically (through the concepts of kinship group, family, and tribe). What shall distinguish this class from those to be found in any number of social science departments, however, is the close attention we shall be paying to the crucial role of culture, the role of literature in particular, in the making (and unmaking, and remaking) of all these ways of relating ourselves to one another. Or to put it somewhat more pithily (and alliteratively): how exactly do poetics relate to politics, and politics to poetics, in the shaping of a shared human existence? This course shall survey some of the most important ways of answering this question in the modern era. Students can therefore expect to study a wide array of social and cultural theorists from the 17th century forward, including (but not limited to) figures such as Hobbes and Vico, Rousseau, and Smith; Hegel and Marx, Malthus and Mill; Durkheim and Weber, de Beauvoir and Adorno; Fanon and Bourdieu, Turner and Geertz: Habermas and Rorty, Nussbaum and Butler; Nancy and Agamben, Appiah and al-Gharbi.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14961,2027,2326,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/copy-of-cslc-211','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different "scenes of writing," from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature''s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience and knowledge are produced, articulated and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14962,2027,1575,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-200','<div class="desc"> <p>Drawing upon literatures and language traditions from across the world, the immediate object of this course will be to help students develop a lively appreciation for, and analytic facility with, each of the major kinds of literary production (lyric, narrative, and drama), all of which we shall try to examine in their “traditional” forms, as well as in some of their more familiar contemporary ones (not only the lyric poem and the prose novel, but the popular song, the graphic novel, and the television series, too, will fall within the special compass of our inquiry). Beyond these immediate goals of familiarity and competence, however, the wider ambition of this course will be to develop students’ understanding of the crucial role that literary (and literature-based) forms play in the constitution of the cultures we inhabit and the various "subject-positions" we might occupy within them. To this end, we shall make ourselves familiar with some of the most important thinkers in recent literary and cultural theory (Foucault, Derrida, Kristeva, Sianne, and Ngai, to name but a few). Given the course’s broad international range, guest lecturers will be brought in throughout the semester to discuss the effect of reading works in the original language and to explore, more generally, the effect that the specific features of a language can exert over that delicate interplay of “literature, culture, and self” that forms the central subject matter of this class. This course serves as the Proseminar for CSLC, and is required for the major but is open to all students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14963,2027,2823,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-201','<div class="desc"> <p>The words of literature, unlike soda cans, bits of data, or the modular classroom furniture of Johnson Hall, do not come to us in easily separable pieces; the words of literature, rather, always present themselves to us as parts of a greater whole, as participants in this or that literaryFORM: a poem, a play, a novel, a song... In this class, we shall set aside the usual preoccupation with the meaning of the words of literature, to investigate instead the various effects that different literary forms exert upon us. What, for instance, do narrative forms --from Babylonian epic to the experimental prose of David Foster Wallace and Karl Ove Knausgaard--tell us about the kinds of worlds that are ours to inhabit in our daily lives? How do the poetic forms of (say) the ballad, the haiku, the sonnet or pop song inflect the manner in which we every day take up our existence? How does drama--from Ancient Greek tragedy to Japanese <em>noh</em> to the theatres of the avant-garde, the cruel and the absurd--open up for us the experience of all those "others" with whom we share this life? By the end of this class, it is hoped that students will have developed not only a feeling for literature in its many forms, but reciprocally, an appreciation for the richness of experience such forms of feeling can bestow upon us.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14964,2027,4155,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-204','<div class="desc"> <p>This course opens with a two-week survey of Roman, Republican, and Imperial history, and proceeds to survey Roman Literature, from Plautus to Seneca, with special emphasis on Roman writers’, orators’, and historians’ reflections on the operations of desire on both the physical body and the body politic.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14965,2027,4156,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-205','<div class="desc"> <p>From romantic comedy to science fiction, the Hellenistic Age of Ancient Greece - the time following the global conquests of Alexander the Great - saw the invention of many of the literary genres most familiar to us today. In this course, we shall examine the meaning of these genres, both for the societies that invented them and our own: from romantic comedy to science fiction, biography to anecdote, heart-wringing elegy to the zippy one-liner, among others. Due attention will be paid to the historic context of the literature (the life of Alexander the Great will feature largely in this class) and its intellectual backgrounds (especially as represented in the works of Plato, Aristotle, the Stoics, and Epicureans).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14966,2027,1644,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-210','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-78) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with major figures such as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as the unprecedented boom in popularity of physiognomy around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. Concluding with the rise of Nazism and Nazi attacks on modern art as “degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. All readings and discussion will be in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14967,2027,4157,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-222','<div class="desc"> <p>This course is a survey of Greco-Roman myth, with a particular focus on the representation, function, and meaning of the gods. Students will study these myths in their original socio-historic contexts, but a large portion of the course will be devoted to a historic survey of modern theories of myth. This approach will allow students to appreciate myth''s relation to the various ritual, philosophic, and artistic contexts in which they appear, both in the ancient world and beyond.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14968,2027,4158,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-223','<div class="desc"> <p>This course will focus on ancient heroes in Greek and Roman myth, such as Hercules, Theseus, Jason, and those featured in the Trojan War. Ancient heroes partake of both the divine and mortal realms, and, in doing so, help us appreciate the ways in which myths were used in order to interpret the world. We will consider the nature of the heroic through the depictions of ancient writers and artists and consider modern heroic ideals in relation to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14969,2027,4159,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-225','<div class="desc"> <p>The Holocaust has been positioned at the limits of representation - as the indescribable, the incomprehensible. The impossibility of adequately expressing the atrocities of the Holocaust stands in contrast to the need to transmit knowledge about this event to later generations. Attempts to represent the Holocaust, to describe and understand this event and its implications, are numerous and have occurred across a wide range of media forms (literature, film, photography, art, music, monuments, etc.) and genres (as in documentary, drama, comedy, science fiction). As the Holocaust recedes in time and the numbers of living historical witnesses and survivors decline, these representations increasingly shape our perception and understanding of the event. This course will investigate literary, filmic, and artistic representations of the Holocaust, focusing in particular on questions of ethics, aesthetics, and history.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14970,2027,4160,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-226','<div class="desc"> <p>We will outline the historical background of the Baader-Meinhof Gang, a violent, leftist collective with roots in the revolutionary student movement that swept Germany in the 1960''s. The group’s assassinations, kidnappings, and bombings of the German establishment left a legacy of terror - a legacy that has been argued over ever since. The literature and films about the Baader-Meinhof Gang, which illustrate the crushing effect of National Socialism on the generation of ''68, as well as their rebellion against the excesses of the capitalist consumer paradise, are controversial. Many have condemned the movies for their exciting, Bonnie-and-Clyde depiction of the gang members that gives the group’s leaders their cult status. We will discuss why German filmmakers tend to heroize a group that has terrorized a country for decades and analyze what effect this has on German collective memory.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14971,2027,4023,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-230','<div class="desc"> <div><p><span style="font-size: 12pt">The course will critically examine philosophical ideas about humans, animals, and machines. We will think about the current stage of technological developmentâthe ways in which contemporary technologies both expand and interrupt what it means to be human. We will focus on several key concepts of Gilles Deleuze and FÃ©lix Guattari (including becoming-animal, lines of flight, and reterritorialization). Our discussions will situate these concepts in the context of past and ongoing posthumanist debates, placing them alongside the contributions of contemporary philosophers, such as Bernard Stiegler and Catherine Malabou. The plays and short stories of Anton Chekhov will help chart outânot so much the lines of flight, as footpaths for slower becomings and futures.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14972,2027,2327,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-232','<div class="desc"> <p>This course focuses on Mikhail Bakhtin''s theory of language and the novel. Bakhtin''s writings are a synthesis of diverse theoretical approaches, including NeoÂ­Kantian philosophy, structuralist linguistics, the theory of novelistic discourse as a polyphonic medium, and the notion of carnival as a subversive cultural force. Furthermore, Bakhtin''s approach to the text reveals prose fiction, and, to some degree, nonÂ­fiction, as a unique medium through which language explores human consciousness in both time and space. In this course, Bakhtin''s theories are studied in order to understand more deeply the significance of the novel, and novels are studied in order to better understand Bakhtin''s theories. Works as diverse as Fyodor Dostoevsky''s <em>Crime and Punishment</em>, Venedikt Yerofeev''s <em>Moscow to the End of the Line</em>, Umberto Eco''s <em>Foucault’s Pendulum</em>, and Manuel Puig''s <em>Kiss of the Spider Woman</em>, are examined through the Bakhtinian lens in order to broaden the students'' understanding of the text as a polyphonic phenomenon. Taught in English; no Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14973,2027,1577,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-233','<div class="desc"> <p>Winston Churchill famously described Russia as "a riddle wrapped in a mystery inside an enigma." Enigmas were very much on Churchill''s mind that Fall of 1939, when the Soviet Union was busily partitioning Poland with Nazi Germany by secret agreement. This course examines the cultural history of Russia and the Soviet Union, in specific regard to its evolving theories of language, literature, and cultural phenomena during the early 20th century. Particular attention is paid to Russian formalism, poetics, and semiotics, as early radical experimentation in the substrates of verbal and non-verbal languages gave way to spasms of violence, mutual East-West suspicion, social repression, and exertions of state power through propaganda and censorship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14974,2027,3891,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-235','<div class="desc"> <p>Plato thought that all we need is a philosopher-king. What if he was only partially right, and what we actually need is a philosopher-buffoon? Jokes aside, what if critical thinking needs to be accompanied by laughter? And not just any laughter, but the kind that, following Mikhail Bakhtin, one would call carnivalesque.</p> <p>Carnival laughter exposes the grotesque aspect of human bodiesâeverything that is âugly, monstrous, hideous from the point of view of âclassicâ aestheticsâ of the ready-made and the completed. It liberates an individual body by revealing the ways it is open to the world around itâby emphasizing a bodyâs orifices and protruding parts. This laughter also revives and refreshes thinking by ridiculingâwithout destroyingâthe strict laws of rationality. Carnivalesque laughter is irreverent; it crosses the lines of what is socially, politically, and morally acceptable, and in so doing reveals the connections between myself and other beings.</p> <p>Bakhtin will provide the main theoretical framework for the course that will bring together literature and philosophy of Eastern Europeâthe works of Gogol, Zizek, Andrukhovych, and othersâto explore (and pervert?) the claims made above.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14975,2027,2747,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers: Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14976,2027,2894,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-237','<div class="desc"> <p>Marcel Proust’s <em>In Search of Lost Time </em>is considered to be one of the greatest novels ever written. Two 20th century thinkers—an Eastern European philosopher Merab Mamardashvili and a French thinker Gilles Deleuze —argued that Proust’s novel is a philosophical machine: an artificial organ that allows one to gather and re-construct the self. Mamardashvili was the only Soviet philosopher to study Proust’s novel and respond to its Western European interpretations from the perspective of Eastern Europe. He also used the novel to expose and explain the more obscure aspects of the Soviet and Russian worldviews. This course puts to the test Deleuze’s and Mamardashvili’s interpretations of this novel by considering them in conjunction with significant portions of <em>In Search of Lost Time. </em>All of the readings and discussions will be conducted in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14977,2027,1510,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-241','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. </p> <p>Students who have completed LATN 102 can take the language intensive version of CSLC 241, LATN 341, where we will read selections from Seneca’s <em>Epistulae ad Lucilium,</em> as well as Horace’s <em>Satires</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14978,2027,3309,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-242','<div class="desc"> <p>In this course, students and professor will collaborate in a close reading of Umberto Eco’s 1980 novel, <em>The Name of the Rose</em> (originally published in Italian as <em>Il nome della rosa</em>). The novel is many things at once. It is a murder mystery/detective novel, a coming-of-age story, a dramatization of debates within Medieval philosophy that resonate to this day, a book about books, and a fantasy about recovering lost works from antiquity, most importantly, Aristotle’s lost book on comedy. We will read the novel slowly and deeply over the course of the semester and together we will explore its themes—such as the nature of words, names, and other signs, the meaning of laughter, and the value of tolerance in a world of dogmatic certainties—and its rich literary allusions—to Sherlock Holmes, Jorge Luis Borges, Alexandre Dumas, and to numerous Medieval and ancient authors. We will track down the novel’s literary references (by reading secondary resources, such as scholarly articles), seek to understand the rich world of philosophical and theological thought its characters inhabit (by reading primary texts of Medieval philosophy, theology, and poetry), and wallow in the sheer beauty of Eco’s writing and the sheer thrill of the story he is telling, all with the goal of interpreting the novel as deeply as possible, as one of the most significant postmodern works of fiction.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14979,2027,2570,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-246','<div class="desc"> <p>This interdisciplinary course introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. Taught in English.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14980,2027,2736,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-247','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14981,2027,2824,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-248','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 BCE sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 BCE when he brought his army across the Rubicon river into Italy from Gaul. </p> <p>Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as <em>On the Republic</em> and <em>On the Laws</em>, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators seeking to restore the old order assassinated Caesar in 44 BCE. They were in turn destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.</p> <p>Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise <em>Discourses on Livy</em>, and John Adams (the “American Cicero”), whose 1787 work <em>Defence of the Constitutions of the United States of America</em> owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14982,2027,3286,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-249','<div class="desc"> <p>This course explores some historical examples of ways of confronting the sort of ressentiment—“a generalized feeling of resentment and oftenhostility harbored by one individual or group against another”—that pervades our cultural discourse, wracks our political life, and makes us miserable as individuals. We shall engage in close examination of the ancient Roman authors Cicero (106 – 43 BCE), Seneca (4 BCE – 65 CE), Epictetus (c.50 – 135), and Marcus Aurelius (121 – 180 CE) and the classically-influenced American cultural critic Albert Murray (1916-2013). We shall interrogate both the strengths and weaknesses of the programs and techniques that these authors—all of whom lived through times of social and personal turmoil—proposed for remaining centered in a sense of their own dignity and in a feeling of gratitude for the blessings that were intermingled with their tribulations. In the case of Murray, we shall assess the adequacy of his theory about the African-American Blues tradition and compare it to that of some scholars who had preceded him. We shall attempt to determine the limitations and strengths of his perception that the Blues idiom represented not “the anguished outcry of a victim” but “an exercise in heroic action” through which the individual makes “an affirmative and hence exemplary and heroic response” to both the suffering particular to historically conditioned forms of oppression as well as to the absurdity of the human condition. Topics covered include the theory of ressentiment, the emotions in ancient Roman thought, Roman techniques for cultivating positive, empowering affective responses not only to “microaggressions,” but to even themost horrific events, and Albert Murray’s theory of the “Blues idiom” as “survival technique [and] esthetic equipment for living.” </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14983,2027,3215,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-250','<div class="desc"> <p>This course investigates select African American engagements with the literatures produced by ancient Greeks and Romans. It is motivated by the conviction that we do interpretive justice to the accomplishments of African American writers when we attempt to understand the tradition(s) they conceive their work to be intervening in.</p> <p>African American literature was born with the publication of Phillis Wheatley’s <em>Poems on Various Subjects, Religious and Moral,</em> in 1773. The book evinces a deep knowledge of Latin and Latin literature, which it turns to its own emancipatory end. Indeed, Wheatley secured her freedom on the strength of the book.</p> <p>Engagement with classical texts offered Wheatley and other African American writers of every era an opportunity to access, deploy, and transform a widely shared treasury of meanings, ideas, images, tropes, genres, and styles in order to create unique works of great artistic power, capable of opening up newly imagined ways of being for themselves and their readers. In addition to Wheatley, we shall explore the classical interactions of poets such as James M. Bell, Mary Livermore, Frances Ellen Watkins, and Robert Hayden and prose writers such as David Walker, William Sanders Scarborough, and W. E. B. Du Bois.</p> <p>To experience the artistic power of these works as their authors intended, we must understand the aesthetic and literary contexts and tradition(s) in which they worked, for context and tradition are the foundation of a work’s meaning. To this end, we shall read alongside African American literary creations some of the Greek and Roman literary works to which they respond. For when we see clearly how a poem by, for example, Phillis Wheatley, responds to an ode by the Roman poet Horace—himself the son of a freedman—we grasp more fully the unique aesthetic, moral, and intellectual power of her poem. To see how Horace’s poetry could communicate to Wheatley is to see how Wheatley’s poetry can communicate its emancipatory power and promise to us in our own time. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14984,2027,1645,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensable for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14985,2027,2748,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-252','<div class="desc"> <p>This course will focus on two foundational texts of Chinese civilization: The <em>Analects </em>and the <em>Zhuangzi</em>. The <em>Analects</em> is an ancient Chinese book composed of a collection of sayings attributed to Confucius and his disciples, and is traditionally regarded as one of the central texts of Confucianism. <em>Zhuangzi</em>, named for its traditional author, “Master Zhuang” (Zhuangzi), is one of the most important Daoist writings. When the <em>Analects</em> emphasizes that people should reconcile their desires via rituals, and fulfill moral and personal duties in order to ensure the welfare of the society, <em>Zhuangzi</em> promotes carefree wandering and following one’s own nature. By reading and comparing these two texts, this course will help students understand and grasp their central concerns, philosophies, and substantial influences on Chinese and East Asian thought and values throughout history. Classes follow a lecture-discussion format, so students must finish all assigned readings in advance and prepare to actively participate in class discussion. No knowledge of the Chinese language or of Chinese history is required (or assumed).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14986,2027,2942,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-253','<div class="desc"> <p>The Tangand Song dynasties (618-1279) are known as Golden Ages in Chinese history, and also generally acknowledged to be the greatest ages of <em>shi</em> and <em>ci</em> poetry. This course introduces the major literary genres and authors of the Tang and Song Dynasties, as well as literati culture emerging during this era. It will focus primarily on the art of poetry, as well as some other cultural forms such as painting and calligraphy, with attention to relevant historical, biographical, and literary-historical contexts. Students will discover the key role that literature played in Chinese court politics, empire building, and institutionalized learning; as well as how it shed light on gender and women’s status, war and knight-errantry, Daoist and Buddhist traditions, and more. The primary texts are translated in English, so knowledge of Chinese is not required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14987,2027,3892,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-260','<div class="desc"> <p style="margin-left: 0; margin-right: 0">This course offers a survey of Japanese textual and visual culture from Japanâs early modern times (16<sup>th</sup> through late 19<sup>th</sup> centuries). We will learn about early modern Japanâs education systems, print history, and book culture, as well as forms of literacy that shaped Japanâs cultural and national identity. Through a wide range of popular literary and visual materials, we will analyze the modes of knowledge and information transmission and the roles they played in everyday life. To gain an intuitive experience of Japanese literary culture, we will carry out several hands-on activities such as rare books workshops and museum visits. Finally, we will turn to new forms of media that rose after the Meiji Restoration in 1868 and how they influenced modern Japanâs cultural identity. The course is given in English and offered in alternate years. No prior knowledge of East Asian languages is required to take this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14988,2027,4024,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-262','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course offers an overview of Japanese literary history from the eighth to the early twentieth century. We will read a variety of translated works from premodern to modern Japan, the social and religious background that shaped Japanese literatureâs forms and aesthetics, as well as the role of Japanese literature in constructing world views and national identity towards modern times. We will also analyze the textual sources in comparison with visual materials and objects to further explore the themes that connected premodern and modern cultural lives. Through secondary scholarship that examines these texts from multiple disciplines, we will explore different ways of critically engagement with Japanese literature. At the end of the semester, students will produce a free-form media presentation that analyzes one of the literary works covered in this course. The source texts are translated into English and knowledge of the Japanese language is not required.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14989,2027,2749,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-270','<div class="desc"> <p>This course will explore the psychology and biopolitics of sexual behavior in literature and film. The first unit, the couch, focuses on psychological theories of sexuality based on works by Freud, Foucault, Lacan, and Derrida. The second unit, the court, explores the biopolitical demands and legal consequences of acting out our sexual impulses. This unit, with texts by Agamben and Esposito, traces the dehumanization, exploitation, and control of the body in authoritarian regimes. The third unit, the confessional, discusses the reproductive bias of spiritual or religious systems and the prohibition of sexual expression. This unit presents films with scenes or plots illustrating the struggle between body and mind. The three units together will ask how sexual impulses disrupt a given socio-political order. Students will evaluate the solutions to disruption offered by psychology (compromise), the court (crime and punishment according to a given society''s laws), and religion (confessing sex acts to a religious official who will condemn them, impose penance, and absolve the transgressor). </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14990,2027,1578,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-280','<div class="desc"> <p>In this course, we shall attempt to come to terms with three of the most important - and provocative - philosophers of the last two hundred years, philosophers without whom the great majority of contemporary literary and cultural theory (and much art and literature, as well) would, essentially, be unthinkable. Significantly, all three of these philosophers habitually turned to ancient Greek tragedy in the formulation, articulation, and further elaboration of their thought. In this class, we shall therefore attempt to use the experience of Greek tragedy, in all its ecstatic strangeness, as a powerful point of entry into the difficult yet crucial works these philosophers have bequeathed to us. Major texts to be covered include: the plays of Aeschylus and Sophocles, <em>The Phenomenology of Spirit,</em> <em>The Birth of Tragedy,</em> <em>Thus Spoke Zarathustra,</em> <em>Being and Time,</em> and <em>Introduction to Metaphysics</em>.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14991,2027,4161,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-281','<div class="desc"> <p>Though we often tend to think of our Greek cultural inheritance as coming exclusively from classical Athens, it was, in fact, the Hellenistic Greeks - those peoples and empires arising after the fall of Athens, in the wake of the conquests of Alexander the Great - who gave world literature many of its most enduring, familiar (and contemporarily relevant) genres: romantic comedy, travel literature, science fiction, biography, the pastoral, and the self-help manual, to name only the most obvious. Our task in this course will be to try to understand why this vast array of literary types came to matter so much to the Greek-speaking empires of long ago, and why they still seem to matter so much to us today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14992,2027,1688,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-283','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all-important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14993,2027,4162,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-284','<div class="desc"> <p>This course will examine the experience of the body as articulated in the literature of exile, from ancient to modern times, and shall draw upon work being done in contemporary embodiment and affect theories, studies in cultural Geography, Sociology, and trauma and literary theory. Works might include: The Old Testament, the <em>Odyssey</em>, the <em>Aeneid</em>, Dante’s <em>Divine Comedy</em>, James Joyce’s <em>Ulysses</em>, Habibi’s <em>Pessoptimist</em>, and might also include works from film and television (from the high artistry of <em>The Intruder,</em> by French filmmaker Claire Denis, to the wildly popular <em>Walking Dead</em> series on AMC, both of which explore in intimate and violent ways the experience of the body in exile).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14994,2027,2825,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-285','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14995,2027,1646,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-286','<div class="desc"> <p>In this class, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth’s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home" at all.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14996,2027,2943,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-288','<div class="desc"> <p>In the 6th century BCE, certain Greek thinkers (who have since come to be known as "philosophers") put in motion a conceptual distinction decisive for the cultural and intellectual history of the West: the division of the soul (<em>psyche</em>) from the body (<em>soma</em>), and more generally, from the "flesh" (<em>sarx</em>). By the 4th century BCE, Plato seems to have concluded that philosophy must eschew any interest in the flesh, inasmuch as flesh (whatever it may be) cannot yield to precise, philosophical investigation. Perhaps even more crucially, Plato stipulated that flesh cannot and should not be the basis of a politics, as it is only philosophical insight, in its disciplined refusal of the lure of the flesh, that could serve as the ground of genuine political communion. From here it was but a short step to conclude that poetry (and of course, "art in general"), entangled as it was with the body, could have little meaning or import for the practice of either politics or philosophy.</p> <p>Influential as these weighty pronouncements have been on the development of Western thought, resistance to them, it should be noted, was almost immediate--beginning perhaps with the work of Plato himself! In this course, we shall examine the ways in which literature and art, as a "poetics of the flesh," offers us a practice as rigorous, and productive, as any philosophy focused on abstract forms. We shall then consider what such a poetics of the flesh might be able to offer philosophy itself as an intellectual discipline. Finally, we shall engage with recent theories concerning the way in which authentic political community might rest not on the eschewal of the flesh, but on its deliberate and thoughtful "incorporation" (pun intended).</p> <p>The first half of the class will focus on older material (certain Ancient Greek and Roman poets, Plato, Aristotle, the Old and New Testament, as well as some medieval writers and thinkers); the second half of the class, however, will turn to the work of more recent poets and theorists of the flesh, with a particular emphasis on the investigations of Jean-Luc Nancy into the significance of the arts for what he calls the "sense of sense."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14997,2027,4163,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-292','<div class="desc"> <p>In this course, we will trace the European history of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and ever-provoking concept: the lyrics of Sappho, the dialogues of Plato, the satirically erotic "technical manuals" of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante''s through heaven and hell in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern notions of love in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14998,2027,2675,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Inscribed Landscape: Nature and Travel in Chinese Literature</strong></p> <p class="MsoNormal">This course will lead students into the world of the Chinese cultural landscape through the lens of literature. We are going to conduct virtual travel to the mountains and waters in China by reading the masterpieces of Chinese landscape and travel writings. We will study the symbolic language that Chinese writers employed to describe their experiences of the natural landscape and their constructions of the cultural landscape. In a broader sense, the focus of this course stems from the interest in cultural geography in the Chinese context. The majority of the course content is on the pre-1800 period. In addition to analyzing literary texts through close reading, this course will introduce students to the ArcGIS system, a digital tool widely used in geohumanities research to view, edit, and analyze geographic data. Students will enjoy the opportunity to create a project using StoryMaps to illustrate their vision of a cultural place. Classes follow a lecture-discussion format. Students are expected to finish assigned readings in advance and actively participate in class discussions. No knowledge of the Chinese language or history is required (or assumed) for this literature-in-translation course.</p> <p><strong>Cultural Appreciation and/or Appropriation through the Lens of Asian Cinema</strong></p> <p>At its core, this course is an attempt to investigate, analyze, and ultimately comprehend the concept of cultural appropriation, in particular through an East Asian context. With a history of imperialism, be it Western or Japanese, in the 19th and 20th centuries, the topic of cultural appropriation is controversial and complicated, whether it is Katy Perry performing wearing a kimono at the American Music Awards or Chinese-Taiwanese-American chef Eddie Huang and his embrace (appropriation?) of African-American black culture. Prior to the actual viewing and analyzing of films, a comprehensive, albeit limited, survey of theoretical works will be conducted; works including but not limited to Richard Rogers’ “From Cultural Exchange to Transculturation: A Review and Reconceptualization of Cultural Appropriation,” Baris Buyukokutan’s “Toward a Theory of Cultural Appropriation,” and Lisa Nakamura’s concept of “identity tourism.” Some of the pairings to be analyzed are: William Shakespeare’s <em>King Lear</em> and Akira Kurosawa’s <em>Ran</em>; Clint Eastwood’s <em>Unforgiven </em>(1992) and Lee Sang-il’s Japanese Western <em>Yuzusazarumono </em>(2013).</p> <p><strong>Hear Now: Jean Luc Nancy and the Aesthetics of Community</strong></p> <p>In this class, we shall be examining the work of one the world’s most important living philosophers, Jean Luc Nancy. Special emphasis will be placed on the close relation Nancy seeks to draw between our so-called “private” aesthetic experiences—the painting that arrests us, the bar of melody that makes us tremble, the line of poetry that haunts us—and our sense of “being in community” (the sense, that is, that our supposedly singular existence is always already plural, is always already shared out with others). Beyond the reading of Nancy’s own works, we shall also be looking at the work of some of his most important predecessors on the question of art’s relation to the community (Kant, Hegel, Benjamin, Adorno), as well as the works of those thinkers who have engaged most directly with his ideas (Derrida, Agamben, Esposito), and those who have explicitly sought to oppose him (Ranciere, Badiou, and others). <em>Prerequisite: CSLC 200 and CSLC 283.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(14999,2027,4164,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/200/cslc-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15000,2027,3523,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/copy-of-cslc-395','<div class="desc"> <div> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> <p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0;"><strong>Trivial Comedies for Serious People: New Comedy from Ancient Greece to Modern Ireland</strong><br/> Sleepless in Seattle…How to Lose a Guy in Ten Days…James Joyce’s Ulysses…Samuel Beckett’s Happy Days. What do these widely diverse artistic creations share in common? They all emerge, or so this course will contend, in response to the ancient dramatic form known as New Comedy, an artistic genre that was to succeed both Greek Tragedy and Greek Old Comedy, and more commonly known as Romantic Comedy. Thus, where many critics today seek to understand the masterpieces of Irish Literature from within Ireland itself, that is, from the largely immanent perspectives of power, politics, and culture native to the island, this class will consider the possibility that the great comic achievements of Irish authors such as Wilde, Synge, Joyce, Beckett, and McDonagh also developed in response to a genre that emerged far beyond Ireland’s national borders. In the first part of this course, we will interrogate the genre of New Comedy as it develops in the classical tradition through Euripides, Menander, Plautus, and Terence. In the second part, we will see how this legacy unfolds in the works of Dante, Shakespeare, and Restoration Comedy, in a tradition that carries over even into our own Netflix specials. In the third part, we will explore the complex, and often perverse, ways in which the genre manifests in the modern Irish tradition. Special attention will be paid throughout the course to the central role that female characters play in the unfolding history of this popular dramatic genre, from ancient to modern times. This course is for advanced CSLC majors: students should have junior or senior standing; must have taken CSLC 200, 201, and at least two other 100, 200 or 300 level CSLC courses; or have obtained the written permission of the instructor. Students who receive a grade of C or above on their final paper will pass their second-stage writing requirement.<br/> <br/> </p> </div> </div>','This course is for advanced CSLC majors: students should have junior or senior standing; must have taken CSLC 200 , 201, and at least two other 100, 200 or 300 level CSLC courses; or have obtained the written permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15001,2027,2750,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-300','<div class="desc"> <p>In this seminar-style course, CSLC majors (acting under the guidance of the course instructor) will be asked to research, and then report to one another, on contemporary trends in literature and literary theory. It is hoped that the skills developed in this course, as well as the content mastered within it, will help CSLC majors in the eventual formulation (and successful completion) of their Senior Comps. Only open to CSLC majors with junior standing, or by instructor permission.</p> </div>','CSLC 200 and two additional courses in CSLC ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15002,2027,4165,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-303','<div class="desc"> <p>This course examines the meanings, effects, social contexts, and historic development of some of the major classical genres: epic, lyric, tragedy, comedy (to name but a few). The course will focus on the explosion of new literary genres (romantic comedy in particular, but also biography, the anecdote, and philosophic dialogue) that followed in the wake of Alexander the Great''s conquest of Greece and the subsequent demise of the autonomous Greek city state. Attention will also be given to the long-term effects of these new "Hellenistic" genres on subsequent European literary and cultural history as it was primarily the Hellenistic sensibility (not the archaic or classical) that, for the next 2000 years, was understood to be representative of the "ancient Greek" perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15003,2027,3310,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-315','<div class="desc"> <p>This course will focus on an in depth investigation into the philosophy of nature, culture, and theory of subjectivity developed by the often overlooked late 18th century thinker Johann Gottfried Herder (. First student and later arch-enemy of Immanuel Kant, Herder developed a theory of nature, culture, and human subjectivity that stood in stark contrast to the universalist, mechanistic, and teleological theories of nature and culture so characteristic of the period we know as the Enlightenment. Herder, by contrast, utilized cutting edge discoveries in the emerging field of biology to develop a cosmological theory that saw both nature and human culture as wrapped up in the process of dynamic transformation. The consequence, for Herder, was that nothing that exists carried with it a singular essence but rather, that the very nature of being was change and that all things, therefore, came be what they are in and through the dynamic interaction with a natural, historical, and cultural environment. This ontological principle allowed Herder to develop a number of radical theories, which we will examine in turn. First, a proto-evolutionary theory of nature that proved highly influential on Charles Darwin (through Alexander von Humboldt) and which viewed organisms and environments as historically contingent and wrapped up in a process of co-adaptation. Second, Herder''s theory of subjectivity, which viewed human thought not as strictly universal but as grounded in language and culture and hence, as necessarily diverse as the manifestations of human language and culture itself. And finally, after investigating both of these concepts, we will investigate impact of Herder''s philosophy both historically, as a forerunner of existentialism, as well as its possibilities for contemporary theory. For it seems to follow from Herder''s supposition that the essence of being is transformation that we should not hold on to any form of essentialism. Rather, Herder seems to suggest that we should affirm, in Nietzsche''s language, the diverse manifestations of existence as well as their historical transformation both subjectively in ourselves and objectively in the cultures in which we live. </p> <p>The course will have the following structure: I: An investigation into the context of the natural sciences (mechanism vs vitalism) out of which Herder''s theory emerges. II: Herder''s response this crisis of the mechanistic sciences (vs Kant''s) and the development of Herder''s philosophy of nature and subjectivity. III: The influence of Herder''s theories on his contemporaries J.W. von Goethe and Alexander von Humboldt. IV: Contemporary theory and Herder.</p> <p>Second-stage writing requirement: Students may satisfy the Second-Stage Writing Requirement by submitting a substantial (12-15 page) writing assignment that addresses a subset of the primary texts studied in this course. Students satisfy the Second Stage Writing Requirement by obtaining a grade of "C" or higher on this paper. </p> </div>','At least one course in CSLC or Philosophy, or permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15004,2027,4025,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-331','<div class="desc"> <div> <p style="text-align: left; line-height: normal;">Korean fictional works concurrently provide avenues for historical remembrance and reimagination. While some novels from the 1900s depict Korea during the Japanese colonial era through a gritty and realistic lens, some fictional films reimagine that period to impart vengeance on the colonizers—a feat Koreans could not achieve in real life. Likewise, in the contemporary era, fiction is often used as a method not only to highlight but also to reimagine social norms. This course will explore modern and contemporary Korea through notable fictional works. More specifically, we will cover over a hundred years of Korean fiction from the 1900s to the contemporary era. We will explore how Korean fictional works depict notable historical moments in Korea, such as the Japanese colonial period, the Korean War, military dictatorship, and contemporary issues of gender, race, and class. By engaging with different types of fiction, including novels, films, and television dramas, we will examine Korean fiction’s chronology and critically analyze modern and contemporary Korean history as depicted in those works of fiction. All course instruction and assigned materials will be in English or have English subtitles.</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15005,2027,1579,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/300/cslc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15006,2027,1648,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/400/cslc-490','<div class="desc"> <p>This course will guide students through the research and drafting of the Senior Comprehensive Project, and will provide students with feedback on work in progress. Open only to senior CSLC majors. Students must enroll in CSLC 490 both fall and spring for a total of 4 units.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15007,2027,4166,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/400/cslc-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15008,2027,4167,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cslc-comparative-studies-in-literature-and-culture/400/cslc-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15009,2027,2738,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-100','<div class="desc"> <p>This course introduces critical theory in the context of the problem of social justice. Introductions will be made to psychoanalytic, Marxist, feminist, structuralist, deconstructive, and postcolonial criticism. Reader-responses; New criticism; lesbian, gay, and queer criticism, will also be surveyed. There will be close readings of the work of Louis Althusser, Georges Bataille, Michel Foucault, and Jacques Derrida, as well as in depth readings of essays by Guy Hocquenghem, Julia Kristeva, and Trinh T. Minh-ha.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15010,2027,1110,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-101','<div class="desc"> <p>Meaningful social and political change requires not only critical and thoughtful engagement with our grounding ideas, dominant theories and our existing positions. It also demands that we learn the concrete, practical skills necessary to make our ideals real, to exercise our rights, to fulfill our duties to one another, and to transform the actual mechanisms and institutions that shape our lives. This course â unique at either the undergraduate or graduate level â will provide students with an intensive and full-spectrum introduction to the most important, most effective and newest techniques, tools and technologies used in political and activist campaigns from the highest levels of electoral politics to non-profit, non-governmental and community campaigns.</p> <p>The course curriculum is organized in three dimensions, training students with the core skills necessary to participate in existing political and activist work, but also empowering them to, when necessary, imagine and carry out their own innovative and transformative campaigns. To this end, students will learn not just tactical skills, but also strategic planning and management approaches that will help them invent, implement, and improve the campaigns to which they commit themselves.</p> <p>This course will include instruction and workshops that bring the best practices and lessons from top businesses and campaigns, refined by political practitioners and distilled for students. It will also include tactical skills training-- media messaging and communication strategies, polling literacy, database management, budgeting and campaign finance, Get Out the Vote (GOTV) efforts, and lobbying basics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15011,2027,3351,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-103','<div class="desc"> <p>This course engages students in critical analysis of classic theories of justice and their connection to more contemporary theories and enactments at the global level. Theoretical explorations will include readings from Pre-1800 theorists on justice and punishment include: Plato, Aristotle, Manu, Al-Farabi, Al-Mawardi, Thucydides, John Lock, Immanuel Kant, Jeanne-Jacques Rousseau, Thomas Aquinas, and John Rawls. The course will build on these early theories of justice to explore justice from the Enlightenment through the current moment through themes such as: utilitarianism, deontology, concepts of fairness, libertarianism, and communitarianism. Themes related to social justice will explore gender justice, racial justice, economic justice, and liberatory practices in the context of global capitalism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15012,2027,2929,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-104','<div class="desc"> <p>This seminar will explore the emergence of new expressions and practices of gender and sexuality by contemporary Arab and Iranian intellectuals, artists, activists and leaders. Rooted in a study of the historical conditions for the emergence of this new set of discourses and practices â from pre-Islamic cultural practices to Western colonialism â the course will examine the novel and transformative forms of expression of gender and sexuality that are being invented in the Middle East and North Africa in dialogue with and in resistance to pre-existing narratives, policies and practices. From resistance to the idea of “gay identity” as a colonial-era trap and backlash against emergent gay rights movements, to the strategic complexities of appropriating the state laws supporting gender-reassignment surgery in Iran, the new generation of queer activists and intellectuals are navigating both their own histories and the limits of postcolonial discourse as they seek a liberatory art and politics. The course will dedicate significant time to studying the current work of these activists â taking up their writing, art, interviews, videos, and political tactics. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15013,2027,823,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-105','<div class="desc"> <p>This course will locate the topics of immigration and education within historical, legislative, and cultural debates on what it means to be an American and who has the right to an education. Students will explore and debate precedent-setting Supreme Court cases, such as Mendez v. Westminster, which challenged the segregation of Mexican children into separate schools, and Lau v. Nichols, which fought hard for non-English speaking students to have linguistic access to the public-school curricula. In addition, students will research the historical antecedents to the recent anti-immigrant movements in California, Arizona, and Colorado, which target the use of languages other than English in school settings, and have all but abolished bilingual public schools. Against this historical and legislative backdrop, students will examine ethnographic research detailing the persistent challenges that immigrant children face in schooling, including migrant children, and the ways in which they, their parents, and communities experience those challenges.</p> <p>This course is part of the California Immigration Semester, and enrollment is open only to first-year students simultaneously enrolled in CTSJ 105, DWA 282, and SOC 105.</p> </div>',NULL,'DWA 282 and SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(15014,2027,1154,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-106','<div class="desc"> <p>In the United States, roughly 80% of the population lives in urban regions (2000 U.S. Census), while according to United Nations figures, about 52% of people are urban-dwellers worldwide. This course will examine various representations of the modern metropolis through film, literature, and cultural theory. The city, as we experience it today, is the product of multiple historical, cultural, and social forces. Over the course of the semester, we will consider how cities have been shaped by these forces, as well as how they, in turn, shape our own experience and understanding of culture, history, and social practices. In an era of increasing globalization and mobility, the role of the metropolis continues to evolve and expand. As we consider representations of the city in a variety of films and novels from around the world, including some from our own city of Los Angeles, we will interrogate the ways in which the city has played a formative role in how we imagine life in the contemporary moment. In what ways has the city become a vehicle for the production of culture? How does life in the city serve to normativize certain notions of what it means to live in the modern world? How does life in rural spaces complicate representations of modernity that take the city as their norm? Does the city promote accessibility, or, alternatively, does it rigidify codes of exclusivity? These are some of the many questions we will address as we consume a spectrum of world cinema and literature. As we work our way through the material, we will strive to develop a complex understanding of how cities shape our cultural imagination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15015,2027,1690,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-107','<div class="desc"> <p>This course will introduce students to major concepts, theories, and intellectual inquiries in the area of postcolonial studies. Students will engage with broad questions around knowledge production, representation, and subjectivities through the examination of topics such as: decolonization, migrations, transnationalism, diaspora, cultural productions, and practices of resistance. The course will look at relationships between postcolonial studies and critical race, feminist, and queer theories.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15016,2027,2985,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-108','<div class="desc"> <p>Through the year 2020 we have seen the rise of reactionary, ethno-nationalist politics across the world. It is likely that this rising authoritarian movement will intensify as climate change creates massive population movements among people in vulnerable economic situations and most susceptible to displacement. This course will critically examine the nature and interrelation between resurgent racist, ethnno-nationalist ideologies, tracing their historical and conceptual roots. It will also take up recent studies of the looming consequences of climate change for population displacement while examining the viability of public policy frameworks and legal instruments for addressing these exigent problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15017,2027,2877,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-115','<div class="desc"> <p>This course will examine the ambivalent effects of digital, networked technologies from social media to AI (with their underlying modes of understanding oneself and the world) in the modern Middle East and North Africa. In particular, in the context of the Middle East, the course will seek to identify and understand both (1) the new forms of popular liberatory action â for example, protest, organizing, revolt, sabotage, warfare, and the weaponization of AIâ that are made possible or impossible by the widespread adoption of new technological modes of life, and (2) the new forms of state and para-state, surveillance, control, suppression, and disinformation that this technology makes available or encourages by its very structure and embedded premises. The course will bring together a study of critical theoretical work from both Western and Middle Eastern thinkers, the scholarly and vocational writing of technologists in both the West and the Middle East, as well as the manifestos, radical speculative projects and strategic documents of resistance groups. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15018,2027,2846,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-120','<div class="desc"> <p>This course introduces students to theories of power from multiple disciplines, and applies these theories to analysis of how power operates in formal and informal politics. Students will be introduced to the basic operation of politics and public policy in the U.S., as well power operating in economic and social systems. It will analyze contemporary public policy, political campaigns and elections, social movements, hashtag activism, and other aspects of the struggle for power in the U.S. context. This class is open to frosh and sophomore students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15019,2027,3985,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-138','<div class="desc"> <span>During World War II, Polish Jewish refugee and lawyer Raphael Lemkin coined the term genocide to describe Nazi occupation policies and practices. In 1948, the United Nations codified this term in international law by adopting the Convention on the Prevention and Punishment of the Crime of Genocide. This course introduces students to the critical study of systematic mass murder and the possibilities and limitations of the genocide concept. Using a transdisciplinary approach that draws on history, philosophy, law, psychology, politics, anthropology, and cultural studies, students will survey the field of comparative genocide studies as it has developed in the last century World War II. Students will interrogate legal and political definitions of genocide, compare the origins, development, and forms of genocidal violence, and explore public debates about genocide representation and prevention. Students will consider dimensions such as colonialism and indigeneity, gender and sexuality, social psychology, and justice and will examine cases of systematic mass murder across the globe, including in New Spain, German South West Africa, the Ottoman Empire, the Third Reich, Indonesia, and Guatemala.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15020,2027,824,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-140','<div class="desc"> <div><p>This course introduces students to critical theories concerning human sexuality. We read feminist, Marxist, psychoanalytic, structuralist, and poststructuralist theories of sexuality, and discuss what makes each of these theories "critical." Topics include: the political economy of marriage, the relationship between sexuality and procreation, uses of the erotic, homosociality, and the incitement to discourse. </p><h1><br/></h1></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15021,2027,3853,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-158','<div class="desc"> This course serves as an introduction to the field of cultural memory studies, using Holocaust memory and memorialization as an in-depth case study. After surveying theoretical approaches to individual and collective memory, we explore how genre, politics, and national culture shaped the emergency of Holocaust memory, the potentials and pitfalls of witness testimony, as well as complex forms of transmission across generations. We consider how Holocaust memory has been institutionalized in museums and archives, its ambivalent globalization in recent decades, and ensuing dilemmas of political responsibility and post-traumatic representation. Students also have an opportunity to visit and interrogate public sites of memory in Los Angeles. Throughout, we engage the general theories and methods of cultural memory studies to reflect on the possibilities and limits of collective memory for understanding historical atrocities, enacting justice, and preventing ongoing violence. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15022,2027,2330,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-160','<div class="desc"> <p>This course introduces students to contemporary feminist thought and histories of feminist activism. Students will learn about the intersectionality of race, gender, class, sexuality, and nation in a variety of feminist scholarship, and will examine key issues in feminist theory, such as: the debates between Western feminism and women of color feminism, transnational feminism, queer theory, the social construction of sex and gender, reproductive justice, gender-based violence, and the political economy of gender. This course will center on the strong link between feminist theory, social justice, and activism, and will explore how these can be mutually informing projects that can effect social change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15023,2027,84,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-170','<div class="desc"> <p>This course explores cultural narratives of migration, identity, and (un)belonging in Los Angeles, focusing on underrepresented diasporic communities from the second half of twentieth century to the present. Through the study of film, literature, memoirs, and other cultural texts, students will examine how stories of immigration and displacement shape understandings of race, gender, sexuality, class, and nationality in a city defined by continual movement and transformation. Emphasizing close cultural, political, and historical analysis, the course investigates how representations of migration both document and challenge dominant narratives of Los Angeles as a heterogeneous and contested urban space. Topics include undocumented storytelling, borderland narratives, queer and intergenerational storytelling, and cultural responses to state violence. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15024,2027,1060,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-180','<div class="desc"> <p>Stupidity is neither ignorance nor organicity, but rather, a corollary of knowing and an element of normalcy, the double of intelligence, rather than its opposite. It is an artifact of our nature as finite beings, and one of the most powerful determinants of human destiny. Stupidity is always the name of the Other, and it is the sign of the feminine. This course in critical psychology follows the work of Friedrich Nietzsche, Gilles Deleuze, and most recently, Avital Ronell, in a philosophical examination of those operations and technologies that we conduct in order to render ourselves uncomprehending. Stupidity, which has been evicted from the philosophical premises and dumbed down by psychometric psychology, has returned in the postmodern discourse against nation, self, and truth, and makes itself felt in political life, ranging from the presidency to Beavis and Butt-head. This course examines stupidity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15025,2027,3336,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-190','<div class="desc"> <p>‘Socialism’ and ‘Marxism’ have become subversive buzzwords in the political atmosphere today, but how did activists inspired by Marxist thought actually conceptualize and organize movements for social change? This course will provide a basic introduction to Marxist theories of organization, with an emphasis on how different Marxists have built political groups and movements to challenge political power in the US. We will begin by reading primary texts in early socialist movements, from the Erfurt Programme to Eugene Debs’ speeches. The rest of the course will cover other historical and contemporary applications of Marxist organizational theories, from the US Communist Party’s organizing with Black communities in the 1930s to recent queer and feminist campaigns to call for abolishing work and the nuclear family.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15026,2027,1061,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> <p><strong>Axes to Praxis: Music as Activism</strong></p> <p>This course aims to provide students with an understanding of the role of music in creating social change. Students will listen to the structure and content of songs and discuss how they can spark critical thought and become a catalyst for political action. The students will also explore how live musical experiences contribute to community building. Traditional, as well as contemporary musical styles, will be examined with an emphasis on the music of women, the LGBTQA community and people of color. We will learn about the contribution of artists and activists whose ideas have propelled society forward.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15027,2027,4168,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/100/ctsj-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15028,2027,86,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/copy-of-ctsj-285','<div class="desc"> <p>This course will provide an in-depth study of Foucault''s work and activism with attention to both his analyses of specific problems as well as the innovative methods he developed to address them (e.g., archaeology, discourse analysis, genealogy). His writing focuses on tracing, exposing and resisting the discourses and practices of categorization, exclusion, and control that emerged in Europe beginning in the Medieval period, through the Classical period and into the 19th CE. The course will bring these analyses to bear on contemporary problems.. Possible texts include History of Madness, Birth of the Clinic, Archealogy of Knowledge, Discipline and Punish, History of Sexuality, as well as his writings on power, art and literature. This course satisfies the Pre-1800 and Regional Focus core requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15029,2027,3986,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/copy-of-ctsj-293','<div class="desc"> <p>Intermediate-level study and research in an area of critical theory and social justice initiated and guided by a faculty member. Students will work in topics and areas that are un- or under explored, or toward transforming methods or paradigms in the existing discourses or practices. Final projects will take the forms appropriate for the research (e.g., essay, policy proposal, qualitative or quantitative research) May be taken for 2 or 4 credits. Permission of instructor is required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15030,2027,4434,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-128','<div class="desc"> This course surveys major theoretical approaches to conceptualizing and critiquing antisemitism. We begin by situating the emergence of modern “antisemitic” political movements in the debates and transformations surrounding Jewish emancipation and the so-called “Jewish Question” in nineteenth-century Europe. From there, we examine antisemitism through religious, nationalist, Marxist, psychoanalytic, existentialist, historical, and anti-colonial perspectives, tracing how different frameworks have explained its causes, forms, and reproduction. Throughout, we will assess the possibilities and limits of these theories for understanding antisemitism’s transformations across time and its relationship to broader structures of race, religion, gender, empire, and politics. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15031,2027,508,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-201','<div class="desc"> <p>Environmental Justice means ensuring equal access to environmental benefits and preventing the disproportionate impacts of environmental harm for all communities—regardless of gender, class, race, ethnicity or other social positions. This introductory course examines legal theories, and key US case studies of environmental justice, with an emphasis on the ways race, class, and gender have shaped environmental battles still being fought today. Students will also learn about traditional and emerging justice topics, and innovative methods lawyers are using to address systemic environmental inequalities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15032,2027,4169,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-202','<div class="desc"> <p>When French postmodern philosopher and activist, Michel Foucault, arrived in Iran to report on the emerging 1979 Islamic revolution, he was full of praise and wonder at what he saw as a great liberatory and spiritual rejection of repressive Western forms of life. He saw it as the birth of a new spiritual politics. But his naiveté regarding the repressive forces at work in the revolution would soon become clear to everyone. Foucault’s misunderstanding of the situation in Iran is emblematic of the complex but foundational relationship between postcolonialism and postmodernism. This course will examine the ways in which the liberatory promise of postmodernism is rethought, rejected or shown to be untenable in the specific contexts of Iran and the broader Middle Eastern and North African postcolonial movements. While acknowledging the liberating power of the postmodern critiques of repressive concepts and structures, we will ask how postmodern thought can be translated into a sustainable and meaningful liberatory politics in places like Iran and the Middle East, and how postcolonial thought and practice are affected by the political and moral possibilities and limits of postmodernism?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15033,2027,4435,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-203','<div class="desc"> How do schools and sports construct, police, and sometimes liberate disabled embodiment? This course links disability justice and critical theory to examine the intertwined institutions of education and athletics. We trace histories of eugenics, special education, and “normalcy”; analyze IDEA/ADA compliance as both protection and surveillance; and study IEPs, testing regimes, and behavioral management through lenses of biopolitics, racial capitalism, and crip theory. In sport, we investigate the Paralympic movement, adaptive athletics, Title IX, NIL and commodification, prosthetics and tech, risk, injury, and the politics of “fairness” (classification, sex/gender categories, trans inclusion). Readings span Fanon to Kafer, Mbembe to Puar, along with case studies from K–12, NCAA, and community programs. Students will conduct a community-engaged project or policy brief critiquing access, accommodation, and equity in a local school or athletic context, and create a media analysis of disability representation in sports culture. The focus of this course is on policies and practices in the United States and the ways that diverse US communities experience (dis)ability. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15034,2027,2847,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-204','<div class="desc"> <p>The abuse of Iraqi prisoners at the US military’s Abu Ghraib Prison and the terrible photographs that circulated giving testimony to that abuse brought torture into our public discourse and became a point of intense political engagement in the US and around the world. This course will examine the so-called “enhanced interrogation techniques” used during the War on Terror as well as the legal and policy justifications that supported them. We will place these practices and justifications within the broader context of colonial power, looking at the ways torture and sexual violence were deployed by other nations. Beyond its use as a punishment or deterrent, we will trace the use of torture back through Western history, to its use in religious and political conversions and finally back to the origins of Western metaphysics in the Ancient Greek use of violence and dehumanization in the formulation of our conception of truth itself.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15035,2027,3066,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-205','<div class="desc"> <p>Whether discussing government plots, medical malfeasance, the moon landing, or the existence of birds, conspiracy theories have been the target of many moral panics in North America over the last century, and largely with good reason. However, conspiracy theory critics have often ignored imbricating socio-historical factors that contribute to belief in conspiracy theories, thereby homogenizing them and the power structures they call attention to. This course will supply students the critical tools to differentiate conspiracy theories that contribute to legacies of systemic oppression from those that call attention to such oppression. The point is not to avow all conspiracy theories, but to instead grapple with their complicated histories and the different forces they align with and challenge. Drawing upon feminist, critical race, Indigenous, and post-structuralist theories, this course will explore topics of historical oppression, legacies of colonial expansion, bio-medical interventions, corporate malfeasance, and the monopolization of decision-making power to grapple with the complex histories of conspiracy theories and what they mean for us today. Conspiracy theories work ideologically and use neoliberal globalist ideologies to traverse national borders. Examples may include "The New World Order", "The War on Christianity," and the 9-11 Tragedy. While the specific conspiracy theories covered in the course will vary, they will be examined through socio-historical contexts that cross geographic, political, and religious boundaries.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15036,2027,3279,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-206','<div class="desc"> <p>The events of 9/11 led the US to two decades of newly intensified war, occupation, and corporate engagement in the Middle East and North Africa (MENA). This changed the trajectory of politics and culture in the region, leading to the rise and fall of regimes, mass death, economic turmoil, democratic protest movements, and authoritarian political backlash. This course will analyze the modern ethical and legal grounding for war, and in particular, the Global War on Terror (GWOT). It will track the lasting-effects of decades of US and European war in the Arab World on the possibilities for thinking and living -- on the political imaginary -- of the places and people affected by those wars. How did the GWOT affect the democratic uprisings of the 2011 Arab Spring? What role did the US and the West play in fostering those uprisings and in suppressing them by supporting authoritarian regimes? And why did it make those choices? What might democracy and liberation in the MENA look like in those conditions of emergence. And finally, what is the next generation of anti-authoritarian activists doing to build the capacities, habits, and institutions necessary to bring positive liberatory change to their societies?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15037,2027,4028,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-207','<div class="desc"> <p>This course will follow and is inspired by the work of INCITE! National Radical Feminist Collective. It is a radical care space for student-professor active engagement in topics of abolition, transformative justice, care praxis, liberation, and decolonization. The class is student-centered, where students can propose reading materials, co-facilitate readings, and be involved in a community project with a community-based organization in Los Angeles. Acknowledging that we are in a privileged PWI institution, the course will center on a space for dialogue about our intersections and how we can co-create Care First classrooms at Occidental College. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15038,2027,1111,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-210','<div class="desc"> <p>Why did the London Bridge fall down? Is Rub-a-Dub-Dub really about bath time? Why didn''t an old man live in a shoe? Who is more imperialist Babar or Peter Pan? Is Tinky Winky gay? Is South Park a children''s show? Is Harry Potter a Hero? How tired was Rosa Parks? Using different critical approaches this course will examine children''s poetry, picture books, novels, cartoons, feature films, and music videos. Analysis will include topics related to gender, race, culture, and nation as they play out in the aesthetics, images, and poetics of children''s texts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15039,2027,2791,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-212','<div class="desc"> <p>Students in the course will study the legal frameworks and politics of slavery, race, citizenship, and “discovery” in relation to U.S. territorial expansion and foreign intervention. Students in the course will critically examine laws, treaties, court cases, and policies used to establish racial hierarchies between “American” peoples, as well as to justify the dispossession and subordination of one or more of these peoples in order to protect slavery, property rights, and/or financial interests. Students will study the fifteenth-century Doctrine of Discovery as the basis of U.S. jurisdiction, settler colonialism, and trade in lands; the landmark case <em>Johnson v. M’Intosh</em> and its influence on the rights of Indigenous Nations and Peoples domestically and abroad; the lasting effects of the Treaty of Guadalupe Hidalgo, which doubled the territory of the United States; and the Insular Cases and U.S. imposition of second-class citizen status on inhabited island territories in both the Atlantic and Pacific Oceans, including Guam and Puerto Rico. Contemporary examples of laws and court cases, such as <em>U.S. v. Vaello-Madero</em>, will also illustrate the legacies of the U.S. imperial project’s racial violence, and will further deepen our understanding of what American property is today and how it has been constructed and legitimized by law.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15040,2027,2649,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-213','<div class="desc"> <p>The course interrogates the assumptions underlying paid and unpaid labor with respect to "women''s work" as it intersects with race, class, sex, gender, and sexuality. Drawing on a socio-critical perspective, we examine the inequalities associated with reproductive labor, child care, housework, sex work, and the ''feminization'' of certain professions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15041,2027,3529,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-214','<div class="desc"> <p>Students interested in engaging in social justice work will develop critical skills through case simulations. Through several writing assignments, students will learn what persuasive legal writing is in the United States, how it differs from other forms of writing, and how to write to serve clients’ varying needs through writing that appears objective but subjectively persuades. Students will also learn how to develop oral advocacy skills through mock intake, client rapport-building, and negotiation exercises. Through oral argument “moot” exercises, students will regularly present before a panel of two to three peers, handling questions from “the bench.” Throughout the semester, students will work collaboratively and independently.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15042,2027,1112,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-215','<div class="desc"> <p>This methods seminar introduces students to discourse analysis as the ontological and epistemological deconstruction of everyday language and symbols and their relationship to power. Throughout the course, students develop techniques for gathering and analyzing multimodal transcripts of naturally occurring conversations, interviews, discourses in institutional settings, media discourses, and texts of historical materials. The course draws from systemic functional linguistics, genre/text studies, multi-modal semiotics, interactional sociolinguistics, and critical social theory to understand how linguistic features of texts constitute, and are constituted by, the social, cultural, and local relations, processes, and contexts in which they are embedded. Using a seminar format, students will engage the readings and apply discourse analysis strategies in order to develop their own independent qualitative research projects.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15043,2027,2650,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-219','<div class="desc"> <p>This course examines the scope and impact of Title IX in educational settings from its passing in 1972 to the present day. Students will explore two main areas of sex-based violations: 1) sports and discrimination and 2) sexual harassment and sexual assault. Drawing on critical theory, students will research and interpret case studies involving Title IX violations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15044,2027,2878,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-220','<div class="desc"> <p>This class explores both the concept and practical application of intersectional analysis as developed in critical race theory and critical legal theory. Intersectionality addresses the complex and shifting ways in which the discourses and practices of, for example, race, gender, sexuality, class and ability can intertwine and overlap, leading to specific modes of discrimination and oppression. Students will analyze these complex formations and the ways in which they are embedded in practices, structures and institutions of power. Reading in the course will include critical race theory, critical legal theory, feminist theory, queer theory, and readings from disability studies as well as other methodological approaches important for understanding and addressing overlapping and intersecting forms of discrimination and oppression. Students will also explore concrete ways in which intersectional analysis can be brought to bear on specific social and political problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15045,2027,2848,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-221','<div class="desc"> <p>This interdisciplinary course is designed for students considering the law as a potential career path and who are interested in developing an understanding of the relationship between inequity, the law and critical theory. Our materials will include federal and California statutes and case law, government-issued reports, and legal journal articles related to education; housing justice; police practices; consumer protection; immigrants'' rights; and other topics. This course will teach students the methods of law and policy analysis. The two main questions that will guide our critical thinking are: what is the impact of the law on inequity and what is the impact of inequity on the law? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15046,2027,3219,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-227','<div class="desc"> <p>This course considers decolonial theories of education in relation to action- and land-based knowledge. Focusing on a variety of spaces and multidisciplinary texts, this course will explore differing ways of understanding education through Native American and Indigenous approaches to knowledge and knowing, land and place, as well as social and familial relations. Students should already have a working knowledge of theories of coloniality, intersectionality, and race. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15047,2027,1325,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-232','<div class="desc"> This course examines the Holocaust as a historical event, as well as its continuing manifestations around memory, justice, and representation. We will trace the origins, implementation, and legacies of the persecution and mass murder of Jewish people by Nazi Germany and its allies and collaborators alongside the persecution and mass murder of Communists, Socialists, Sinti and Roma, disabled people, queer and trans people, Black people, Slavic peoples, and others in Nazi-occupied territories. Situating the Holocaust within the broader history of Europe and the world from 1919 to 1945, students will study the rise of fascism and the Nazi Party, the role of nationalism, antisemitism, and colonialism, the development of racist and eugenic policy, the context of war in enabling mass atrocity, and postwar processes of memory and justice. In addition to historical frameworks, this interdisciplinary course draws on methods and sources from Jewish Studies, Genocide Studies, Cultural Studies, Visual Studies, Memory Studies, and Critical Theory. Throughout, attention will be given to the potentials and pitfalls of documentary evidence, photography, and testimony; the politics of memorialization and representation; debates over uniqueness and comparison; and the roles played by gender, sexuality, race, religion, class, geography, and political ideology in shaping the experiences of both victims and perpetrators. Students will also have an opportunity to engage the landscape of Holocaust memory in Los Angeles, including institutions such as the USC Shoah Foundation, the Holocaust Museum Los Angeles, and the Museum of Tolerance. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15048,2027,3838,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-235','<div class="desc"> <p>This undergraduate course in Critical Race Theory delves deep into the intricate relationship between the legal system, race, power, and social justice. Drawing from interdisciplinary perspectives within critical theory, this course examines how race has been constructed and maintained within the legal framework of the United States. By critically analyzing key legal cases, texts, and critical race theorists, students will gain a nuanced understanding of the role of law in maintaining racial hierarchies and how legal activism can contribute to dismantling them. This course aims to equip students with the analytical tools and critical perspectives needed to address the complex issues of race, law, and justice in contemporary society, fostering a deeper understanding of the challenges and possibilities for social change</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15049,2027,4436,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-240','<div class="desc"> This course critically examines advertising as a powerful cultural technology that produces gender, race, sexuality, ability, desirability, and “the consumer self” within capitalist visual culture in the United States. Students explore how commercial media constructs norms, manufactures aspiration, and circulates inequality through narratives of so-called empowerment, diversity, and inclusion. Using semiotics, discourse analysis, feminist media studies, queer theory, intersectionality, critical disability studies, and cultural political economy, the course approaches advertising not as brand messaging but as a site of ideology, affect, and social control. To deepen applied understanding, students will complete the <em>SeeHer Gender Equity in Media Certification</em>, integrating it into the course as both an industry case study and an object of critical analysis. While earning the certificate, students interrogate its assumptions: What counts as gender equity when justice is measured by brand metrics? What forms of inclusion are rewarded, monetized, or overlooked? Can corporate visibility be liberatory, or does it risk becoming aspirational neoliberalism? This course is focused on the United States, and it''s focus on race and gender satisfies the requirements for the US Diversity Core requirement. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15050,2027,2331,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-250','<div class="desc"> <p>This course will examine the relationship between resistance movements and the law through several historical and contemporary United States and Latin American case studies. We will begin the semester by exploring theoretical representations of resistance movements within critical legal theory and social movement theory. We will look at different conceptualizations of power and consciousness in our analysis of resistance, and the role of each in instigating resistance movements. We will then turn to an analysis of the law as a tool of collective struggle by studying and comparing the implicated rights and site-specific needs, objectives, strategies, and outcomes of each case study. We will look at the different ways these resistance movements may use the law to mobilize followers, to frame and address collective grievance, to advance and develop legal protections for marginalized groups, and to connect their localized struggles with global ones by redefining and reimagining concepts of dignity and freedom. Each case study will also provide us with an opportunity to explore the relationship between the law, state-sponsored violence, and repression of resistance movements. We will also examine the role and influence of legal advocacy organizations in contemporary resistance movements, and evaluate the current limitations of the law in contributing to social change. How do rights-based claims (e.g. indigenous rights, water rights) obscure the relationship between law and power, injustice, and structures of oppression? Can the law be a useful catalyst for change, and/or is it necessarily a supplement to grassroots organizing and mobilizing efforts? To examine these concepts and tensions, we will look at legislation and legal practices, landmark court cases, and critical scholarship related to our case studies. Among the resistance movements we will likely study are: Brazil''s Landless Rural Workers Movement; indigenous resistance movements in North and South America, including resistance to the Dakota Access Pipeline and the Agua Zarca Hydroelectric Dam in Honduras; and different phases in the movement for black civil rights in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15051,2027,1372,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-255','<div class="desc"> <p>This course will examine intersecting and overlapping categories of "difference" by focusing on the lives of women of color. By looking at conditions that shape race, sexuality, gender, class, and cultural differences, this class will critically examine multiple discourses surrounding feminism, anti-racism, heteronormativity, and critiques of imperialism. We will consider contexts of individual and collective work for social change. Using personal essays, stories, scholarly writings, artistic works, music, film, and other media, the course will look at sources that women of color draw from to ground themselves and their activist work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15052,2027,1062,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-259','<div class="desc"> <p>This course examines movements of bodies through political, legal, economic, and social exchanges. Drawing from a variety of materials (theory, literature, film), the course examines practices such as: human trafficking, organ transplantation, transnational adoption, and surrogacy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15053,2027,1652,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-260','<div class="desc"> <p>This class examines the politics of human rights and histories of stateÂ­-sponsored violence in the contemporary Americas. By focusing on the Americas as a specific geopolitical site for our discussions, we will gain a better understanding of the main cultural, political, and philosophical debates over universal human rights. The class will also examine how culture and art can serve as a form of resistance to legacies of oppression and violence in the Americas. We will refer to critical human rights and feminist theory in order to assist our understandings of the experiences of those affected by Latin American state violence and the formation of Latinx diasporic communities in the United States. Students taking this course will gain an understanding of the histories of the region, the relationship between universal human rights, nationalism, political violence, and contemporary gender issues. The class will also refer to the limits and possibilities of human rights in the pursuit of attaining justice for stateÂ­-sponsored crimes. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15054,2027,910,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-270','<div class="desc"> <p>This course looks cross-culturally at children and childhood and uses ethnographic case studies as a basis for examining the ways in which the very young participate in the social lives of their communities. The focus is on those between the ages of 5-12 and the primary topics include: children''s play, socialization, learning, political action, and productive work. We will explore the lives of children in horticultural, pastoral, rural, and urban societies in Africa, Asia, Polynesia, and the contemporary United States.</p> </div>','Any 100-level CTSJ course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15055,2027,4170,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-271','<div class="desc"> <p>This interdisciplinary course explores the historical emergence of philosophical, sociological, and political theories of property in order to interrogate contemporary global nation-state problems related to human rights, imperial and colonial capitalism and decolonial possibilities. Topics of study will include the ways in which these emergent Western concepts of property and the exercise of power to secure property have shaped and continue to shape the ideas and practices of slavery, human trafficking, children’s rights, women’s rights, land and property rights, and the claims to possession and dispossession across time and continents. Students will learn about the history of property activism and contemporary efforts to advocate for new/old visions of property.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15056,2027,85,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-280','<div class="desc"> <p>This course will examine the character of postcolonial theory in the Afro-Caribbean. Particular attention will be paid to the work of C.L.R. James, Walter Rodney, Franz Fanon, Marcus Garvey, Aimé Césaire, Eric Williams, Kamau Brathwaite, and Bob Marley. The course will also examine Rastafari as a religio-political protest movement. We will chart the musicological development of reggae and dub poetry as distinctive expressions of Rasta.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15057,2027,3301,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-290','<div class="desc"> <p>As the fastest-growing racial group in the US, Asian Americans are becoming increasingly important in the political sphere. But the rubric of ‘Asian America’ encompasses cultural identities as diverse as its political ones. This course will explore these fissures from the viewpoint of the past and present of Asian American participation in radical politics. How has the struggle for radical systemic change generated dividing lines within not only Asian American politics more broadly, but also within Asian American radical movements? How have different generations of Asian Americans developed counter-institutional spaces to advance their political initiatives? Many of the course’s readings will center on independent and ephemeral publications created by these activists, from Marxist periodicals to online feminist zines. We will touch on some key issues that have concerned these communities, including but not limited to anti-Asian racism, Chinatowns, sex work, incarceration, and internationalism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15058,2027,1007,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-295','<div class="desc"> <p>This seminar will engage important topics and issues in Critical Theory and Social Justice. All CTSJ faculty will participate in order to facilitate an interdisciplinary engagement with complexities and nuances of these topics. Students from other CTSJ courses will be invited to participate in the construction of discourse around the topics. May be repeated for credit when offered with a different topic. Different topics may fulfill different Core Requirements.</p> <p><strong>Black Popular Culture // The Black Digital Age </strong></p> <p>This class is part of a series that takes up black popular culture as a social formation structured by both the shifting conditions of antiblackness and black objection in the 20th and 21st centuries. Rather than engage black popular culture as a representational form, the course queries the peculiarity of blackness’ cultural popularity within a society where black people remain disproportionately available to gratuitous violence and early death. As such, the course interrogates the ways in which the mainstream US popular culture economy is sustained by a deeply contradictory fascination with black bodies, black sociality, and black repertoires of performance within an antiblack society and argues that consumption of black life and black expressions is a modality of the ways in which blackness is put to use under white supremacy. The course is particularly concerned with how the audio-visual is a poignant site at which visual fixations on and pathologizations of blackness collide with black peoples’ expressions of objection, self-articulation, activism, and the forging of social space. In this light, this iteration of the course, queries the possibility of the “Black Digital Age” as the proliferation of black expressions within the 2010 to present moment in the audio-visual (TV, film, and videography, including Scandal, Moonlight, Insecure, Queen &amp; Slim, Native Son, Lemonade, When I Get Home, When They See Us, Fences, Random Acts of Flyness, and countless others) and social media (Youtube, Twitter, and Instagram) realms. We ask, what political, social, and historical developments in this moment have facilitated such a proliferation of black productions within the audio-visual; what is the social, political, and historical impact of these black productions; how have black artists reconfigured black visuality as a site of desire, pleasure, restitution, and power in the face of antiblack racism as visual degregation of blackness; and how might our social criticism and genuine engagement with these texts extend the project of black life, objection, and self-articulation in the face of ongoing antiblackness? Core Requirement Met: United States Diversity.</p> <p><strong>Social Movements/Representational Forms</strong></p> <p>In this course, we will examine the competing advocacy within social movements for documentary, fiction, journalism, lyric, abstraction, and other representational forms. For each social movement or political issue that we cover, students will compare multiple modes of representation, considering why they emerged, what their strengths and weaknesses were at each specific conjuncture, and what significance they have for future struggles. We will begin with some theoretical grounding and then proceed via a set of case studies. These may include: debates about realism vs. modernism in the Frankfurt school; testimonies in Latin America; confession vs. experimentation in feminist literature; reportage vs. the essay in journalism; and slogans, songs, and posters in queer activism.</p> <p><strong>Blackness, Gender, and Sexuality</strong></p> <p>In this course, students will deconstruct, critique, and reconsider our notions of “gender” and “sexuality” by thinking deeply, creatively, and rigorously about the ways in which blackness has been both central to modern conceptions of gender and sexuality and marked as the standard of sexual and gendered deviance. Students will consider “gender” and “sexuality” as historical, socially produced, and mutable categories that are co-constituted by structures of power including race, capitalism, and chattel slavery. Importantly, the course will focus on identifying the historical conditions and structures of power that have differently gendered black bodies in the Americas. By considering the particularities of black gendering, the course will identify how notions of gendered and sexual deviance and availability to antiblack violence have been central to producing black people as a population. Through concepts such as flesh, ungendering, availability, and queerness, students be able to unpack how black bodies are gendered in terms and social relations that are in excess of a binary and are not analogous to other racialized bodies. Finally, by looking at popular and cultural objects, the class will analyze how contemporary raced and gendered structures of power affect black people and communities. Core Requirement Met: United States Diversity.</p> <p><strong>Critical Theory and Psychopathology</strong></p> <p>This experimental interdisciplinary course considers the intersection of Critical Theory and psychopathology. The goal is to examine the ways in which central insights in Critical Theory might reorient our perspective on, and interventions against, mental disorders. By way of contemporary case studies, we will examine the directive to "care for the self" (Michel Foucault), the mandate "you must change your life" (Peter Solterdijk), the problems of death (Jacques Derrida), the work of forgiveness (Derrida), and the anguish of perversions (Georges Bataille). We will also re-read chronic pain (Friedrich Nietzsche), Generalized Anxiety Disorder (Sianne Ngai), Gender Dysphoria (Judith Butler), and Intermittent Explosive Disorder (Slavoj Zizek). We anticipate the emergence of a broader more powerful view of madness. Core Requirement Met: Global Connections.</p> <p><strong>Psychoanalysis, Psychiatry, and Liberation Movements</strong></p> <p>In this course, students will consider the intersection of the histories of psychoanalysis, psychiatry and liberation movements. Since the 90s, psychoanalysis is often characterized as a theory concerning sexuality and sexual difference divorced from political histories, accused of universalism and essentialist assumptions about difference. In recent years, there has been a return to psychoanalysis to examine the social unconscious and psychic manifestations of oppression. This class revisits the political potential of psychoanalysis and psychiatry movements. In addition to queer and feminist interventions into hegemonic discourses of psychoanalysis by Sigmund Freud and Jacques Lacan, we will explore how psychoanalysis might be repurposed to analyze problems of race and racial difference and investigate the material histories of the psychiatry in anti-colonial liberation movements. We will examine topics such as Frantz Fanon’s psychiatric practice during the Algerian Revolution, the relationship of the Institutional Psychiatry Movement and the Spanish Civil War, Abolitionist theories of deinstitutionalization, Queer and Trans interventions into psychopathologies, the psychoanalytic question of negativity in Black Studies, and clinical psychoanalytic practices under colonial occupation. Students can expect to read theorists and practitioners such as Jean Oury, François Tosquelles, Félix Guattari, Judith Butler, José Esteban Muñoz, Jaqueline Rose, Lauren Berlant, Liat Ben-Moshe, Patricia Gherovici, Avgi Saketopoulou, Hortense Spillers, Fred Moten, Lara Sheehi, Stephen Sheehi, and more. We will also connect theories of madness and gender deviance to make sense of the psychology of our contemporary political climate. Drawing on epistemological resistance from bodies of minoritarian knowledge, students will explore the psychic life of racism, sexism, transphobia, homophobia, and social injustice. Core Requirement Met: Global Connections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15059,2027,4171,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/200/ctsj-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15060,2027,2332,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/copy-of-ctsj-361','<div class="desc"> <p>This course centers on representations of gender, race, class, nationality, and sexuality in Latinx and Latin American film. We will examine the economic, racial, and gendered inequalities that stem from histories of colonization and neocolonialism in Latin America and in the diasporic Latinx communities that have formed in the United States. Using a transnational lens, students will assess the limits and possibilities of film in documenting histories of oppression and social inequalities facing Latin Americans and Latinx communities in the U.S. We will turn to feminist film theory, critical film theory, cultural studies, and Latin American history and politics in order to facilitate our analysis and class discussions of these films.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15061,2027,3534,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/copy-of-ctsj-393','<div class="desc"> <p>Advanced, independent study and research in an area of critical theory and social justice initiated and guided by a faculty member. Students will work in topics and areas that are un- or under explored, or toward transforming methods or paradigms in the existing discourses or practices. Final projects will take the forms appropriate for the research (e.g., essay, policy proposal, qualitative or quantitative research) May be taken for 2 or 4 credits. Permission of instructor is required. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15062,2027,2849,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-300','<div class="desc"> <p>This course is an introduction to the process of conducting social science research. Students will learn to execute a research project from start to finish—including the formulation of a research question, selecting the best method(s) for addressing the question, statistical analysis in a lab setting, and research report writing. Students will also learn to critically analyze the production of knowledge and unmask the power dynamics of “scientific” inquiry, “objectivity,” and “authority.”</p> </div>','CTSJ 100 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15063,2027,3931,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-301','<div class="desc"> <p>This course provides an introduction to a broad range of approaches and methodologies used in the interdisciplinary fields of Gender and Ethnic Studies. These methods include (but are not limited to) archival and historical research, textual analysis, fieldwork, action research and visual analysis. We will learn about these methodological approaches along with the foundational goals and theoretical discussions of fields such as Latina/o Studies, Sociology, Cultural Studies and Gender Studies to conceptualize and locate our research projects within the different disciplinary fields that inform our scholarship. The course also considers what constitutes interdisciplinary research and how we can implement it in our own practice. Throughout the semester students will develop an original research proposal and conduct preliminary research by creating a corpus of textual and visual data.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15064,2027,4413,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-305','<div class="desc"> This course examines how poetry, visual art, and cultural production both expose and resist the logics of the U.S. carceral state. Moving between prison writing, performance, film, and community-based creative work, we will explore how artists inside and outside prisons represent captivity, policing, surveillance, punishment, and the everyday practices of care and survival under conditions of unfreedom. Drawing from abolitionist feminist theory and praxis, Black studies, queer and trans studies, students will read works by writers, artists, and theorists engaging with the carceral state. Through close reading, collaborative analysis, and creative-critical experimentation, we will ask: How does art and poetry make the carceral visible and how does it make freedom imaginable? How do abolitionist aesthetics refuse representational norms? What new sensory, affective, and political practices emerge when those most impacted by the prison regime represent and theorize of their own lives? Students will analyze how carceral aesthetics are deployed in popular culture and public policy, and how abolitionist poetics imagine alternative social worlds beyond punishment.<br/> <br/> Readings include the writings of incarcerated poets and thinkers, including works by Assata Shakur, George Jackson, Ruth Wilson Gilmore, Joy James, Audre Lorde, Robin D.G. Kelley, Dylan Rodríguez, Gwendolyn Brooks, Terrace Hayes, Wanda Coleman, Nicole Fleetwood, and more. For these thinkers, the aesthetic realm is not a retreat from politics, but a potent (and fraught) strategy for perceiving, challenging, and reworking dominant forms of power. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15065,2027,1692,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-310','<div class="desc"> <p>This course will pursue an interdisciplinary, critical approach to the concept and politics of universal human rights and the critical debates that have emerged in response to egregious violations of human rights in the 20th century. We will interrogate the possibilities and limitations of human rights discourse and praxis as well as the politics involved in who defines and determines the universality of rights. Relying on cultural studies and feminist theory, the course will focus on key examples of historic traumas and human rights violations to contextualize our theoretical discussions. We begin by examining the evolution of human rights as a discourse and practice, and we will use a critical lens to interrogate the roles the state and civil society play in the violation and/or upholding of the human rights of citizens. We will study the imperialist aspect of the enforcement of human rights and the ways human rights discourse can serve to reproduce moral and power hierarchies between the Global North (the U.S., European nations) and the Global South (Latin America, Africa, etc.). We will also study various models of justice and repair in various cultural productions, and we will also explore the transitional justice models that have emerged in different historic-social and geopolitical contexts. We conclude the class by examining the possible futures of human rights and the key role survivors of human rights violations and memory projects play in shaping those futures. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15066,2027,1155,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-311','<div class="desc"> <p>In this course, students examine contemporary child poverty, both in the United States and abroad. Topics include: how poverty is defined, both locally and globally; the numbers and distribution of poor children; as well as the causes of child poverty. Readings explore poverty in relation to education, economics, homelessness, child labor, family, gender, and race. Students analyze historical anti-poverty policies, such as: The New Deal, the War on Poverty, and the United Nations Convention on the rights of the child, as well as contemporary proposals to reduce child poverty, such as: childcare, welfare, job training, job creation, and tax policy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15067,2027,2930,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-315','<div class="desc"> <p>This course will explore the experiences of marginalized peoples in relation to race, space, and segregation, with a particular focus on Native American experiences. The racialization of space in the United States illumines various technologies of oppression and the historical creation of the so-called “Other.” Students will be required to interrogate the geographic spaces and land we inhabit and how space is socially created to serve dominant settler and white supremacist narratives. This course will explore institutional racism, segregation, and the creation of difference through discourses, policies, and laws, as well as the politics of space and sight. We will also be discussing boarding schools, the creation of reservations, Native (and POC) criminality and prisons, as well as Native histories of Southern California. There will be a strong emphasis on learning in action throughout the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15068,2027,1326,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-340','<div class="desc"> <p>In this course, students learn how to do ethnographic research and writing by conducting exercises in participant-observation on or near campus. We review the history of the ethnographic method and its relation to anthropology and the colonial encounter. We also discuss what makes an ethnography critical, and the tensions between ethnography, sympathy, and critical theory. Authors we read include Malinowski Geertz, Delmos Jones, Dorinne Kondo, Renato Rosaldo, Ruth Behar, Jim Thomas, and Kamala Visweswaran.</p> </div>','Any 200-level CTSJ class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15069,2027,3256,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-342','<div class="desc"> <p>This course examines the historical context of anti-fatness and contemporary implications of this system of bias in the US. Students will examine socially constructed meanings of body size throughout global history and contemporary meanings assigned to bodies in the US compared to other countries. Students will learn about sizeism, fatphobia, fat-hatred, and other ways in which fatness is policed in contemporary societies. Students will also study fat acceptance campaigns, fat activism, and other body size social movements through an intersectional lens. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15070,2027,2880,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-350','<div class="desc"> <p>The course will study the transformation of postcolonial theory and practice by contemporary writers and activists in the Middle East, North Africa and South Asia in response both to their new social, cultural, political, and economic conditions, as well as to their experience of the limits of earlier forms of postcolonial thought. The course will track the problems posed by the emergent concepts of identity and authenticity and the way that the modalities of melancholia and <em>ressentiment </em>can affect or undermine the postcolonial as a project of liberation. As part of this re-examination, students will explore the complex ways in which Western modes of thinking and politics — including modernism, anti-modernism, Traditionalism and resurgent authoritarian and ethno-racial political forms — shape and are resisted by postcolonial thinkers and activists. The course will advance student understanding of postcolonial theory and practice by pairing (1) a careful examination of foundational works of postcolonial thought within their historical and political contexts, with (2) an exploration of the work of contemporary scholars and activists whose projects transform and reimagine the very idea of the postcolonial.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15071,2027,89,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-369','<div class="desc"> <p>The Clinical Psychology Laboratory (CPL) provides experiential opportunities for students interested in graduate study in Psychology, Law, or Social Justice. Students are given the opportunity to participate in the data analysis of clinical psychological assessments. Students will also participate in research on a Human Studies Committee approved project with the goal for an early exposure to the field, and with the objective to yield research data for presentation or publication. In some projects, students may have limited opportunities to observe and participate in forensic psychological assessments as prescribed in the respective protocols. Instructor interview and approval required. May be repeated three times for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15072,2027,1156,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-370','<div class="desc"> <p>This course examines the scholarly, cultural, and activist work of transnational feminists in the Global North and South. The course will discuss how the term âtransnationalâ has been employed by feminist theorists to critique the centrality of nations, nationalism, and the national scale in political life, including in feminist political imaginings. We will study the debates that erupted between âthird worldâ and âWesternâ feminisms, the latter signifying the globally dominant, liberal feminism of U.S. and European-based privileged women and of the aid and development establishments. The course will center on and be guided by the experiences of transnational feminist groups working in different geographies and social movements, as well as their efforts to create solidarity movements globally.</p><p><br/></p><p>Case studies and examples are drawn from Juarez, Mexico; Guatemala; South America; Asia; and Palestine. Authors to be discussed include Chandra Mohanty, Richa Nagar, Lorena Cabnal, and Katherine McKittrick. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15073,2027,2703,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-375','<div class="desc"> <div><p>Indigenous or Native feminism course will be guided by the relationship between body, mind, and spirit in and outside the classroom. In this course, we will learn from Indigenous feminism frameworks, from <em>reciprocity</em> to <em>body-territory</em> to <em>Buen Vivir</em> (Good Living). These frameworks share the ontological premise that humans are connected to Mother Earth, and we cannot separate the body and mind from the land. Inspired by Potawatomi botanist and author Robin Wall Kimmererâs book <em>Braiding Sweet Grass: Indigenous Wisdom, Scientific Knowledge, and the </em><em>Teachings</em><em> of Plants</em>, the class will also share a relationship with herbs, plants, and the spiritual world. Questions the class asks: How can a body, mind, and spirit epistemology in the classroom transform student and teacher relationships to center communal healing? How does an engaged pedagogy challenge Western education values of individualism and meritocracy?</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15074,2027,2704,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-376','<div class="desc"> <p>This course will engage major concepts, theories, and intellectual inquiries in the area of settler colonial studies. We will ask: what makes settler colonialism distinct from other forms of colonialism? How does settler colonialism intersect with other systems of oppression, such as heteropatriarchy, chattel slavery, and racial capitalism? We begin by defining settler colonialism as the systematic dispossession and elimination of Native peoples via genocide, land appropriation, settler immigration, and/or cultural assimilation. We will then explore the relationships between settler colonial studies and queer theory, Afro-pessimism, and Asian diasporic studies. Authors to be discussed include Patrick Wolfe, Lorenzo Veracini, Jodi Byrd, Mark Rifkin, Jared Sexton, Frank B. Wilderson III, Ikuko Asaka, Iyko Day, Dean Saranillio, and Manu Karuka.</p> </div>','Open to frosh. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15075,2027,514,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-384','<div class="desc"> <p>A close reading of the works of Georges Bataille, including: <em>The Impossible, The Unfinished System of Nonknowledge, The Accursed Share, On Nietzsche, Story of the Eye, The Dead Man, </em>and <em>Collected Poems. </em>First year students are not permitted to enroll in this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15076,2027,4172,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-386','<div class="desc"> <p>Critical race theorists have begun to describe a "new blackness," a "critical blackness," a "post-blackness," and an "unforgivable blackness." This emergent scholarship that describes a feminist New Black Man also seeks to "queer blackness," and to articulate a black sexual politics that addresses a "new racism." By calling us to examine the possibility of a black political solidarity that escapes the problems of identity politics, this scholarship provokes <em>We Who Are Dark</em> to imagine more complex and free identities. We will also consider the positionality of anti-blackness and it''s antecedents. This course invites all of us to engage this scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15077,2027,1443,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-390','<div class="desc"> <p>The Junior Seminar offers CTSJ majors a semester-long, careful and rigorous reading of a small number of important and groundbreaking texts in critical theory. Texts and themes will vary year to year. Students will work with the professor and their peers in exploring the ideas, implications, methods, modes of writing, and styles of argumentation of these texts in depth. Students will work together to create thoughtful and creative readings of these texts over the course of the semester, bringing to bear their previous work in the department and their experience and research regarding practical political and social problems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15078,2027,1513,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-394','<div class="desc"> <p><em>Critical Theory and Social Justice Journal of Undergraduate Research</em> (<em>CTSJ</em>) is the leading undergraduate publication in its field, nationally. A primary goal of this course is to develop student''s preparedness and capacity to critically evaluate submissions to the <em>CTSJ Journal</em>. To that end, there are two sets of readings. All students are required to read the primary text, J.M. Balkin''s <em>Cultural Software</em>. Other readings are assigned to reflect the themes and topics of the submissions under review. In addition, this course affords students the opportunity to work closely with<em> CTSJ''''</em>s Lead Faculty Editor to understand the mechanisms of working for and advancing a research publication in the Humanities field, and produce content that is consistent with the goals of <em>CTSJ</em>. May be repeated three times for credit.<em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15079,2027,1064,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-395','<div class="desc"> <p>An advanced seminar in Critical Theory and Social Justice. May be repeated for credit with a different topic. <em>Different topics may meet different requirements.</em></p> <p><strong>White Queer Theory</strong></p> <p>This course critiques the ways in which queer theory and politics of the late 20th and 21st century have been a profound site through which whiteness has been able to reproduce and proliferate in the context of the neoliberal incorporation of raced, sexed, gendered difference into structures of capitalism and the US nation-state. As such, students will engage both the so-called critical texts of white American queer theory and texts from queer indigenous studies, black queer studies, women of color feminisms, and queer of color critique along with the burgeoning fields of black trans studies and trans of color critique that have rigorously critiqued the limits of the so-called critical texts to think [critically] about their reproduction of whiteness and the ways in with their thinking of queerness does not encapsulate the ways in which indigeneity, blackness, and other racialized formations are marked as sexually deviant, non-heteronormative, and queer, both as sexual identities and as populations. In order to thoroughly interrogate these proliferations students will engage a variety of texts that include theory, history, political movements, and popular culture — texts include the work of Foucault, Judith Butler, Glee, Paris is Burning, #ItGetsBetter, the phenomenon of Milo Yannopoulos (aka Milo Hanrahan), Christine Jorgensen, and the white queer antiblack backlash against the simultaneous passing of prop 8 in California and the election of Barack Obama as the first president; and the work Cathy Cohen, Qwo-Li Driskill, Jasbir Puar, Scott Morgensen, C. Riley Snorton, Roderick Ferguson, and other scholars who have reframed questions of queerness and its intersections with whiteness, settler colonialism, and racial capitalism through frameworks such as homonationalism, settler homonationalism, trans necropolitics, and the queerness of blackness. <em>This class counts as a methods class for the CTSJ major. Core Requirement Met: United States Diversity.</em></p> <p><strong>Whiteness</strong></p> <p>This course seeks to engage the emergent body of scholarship known as Critical White Studies (CWS). This scholarship is designed to deconstruct the racial category “white.” We will examine the historical, legal, economic, gender, and aesthetic constructions of whiteness. Particular attention will be paid to the problem of blackface. We will also critically examine CWS. <em>Core Requirement Met: United States Diversity.</em></p> <p><strong>Chattel Slavery and Its Afterlives</strong></p> <p>This course introduces students to the key theoretical and historical frameworks that elucidate the particularities of chattel slavery in the Americas both in its “pre-emancipation” manifestations and as, Saidiya Hartman notes, the ongoing machinations of captivity, domination, and dispossession by which antiblackness continues to structure and suture the world. In this course, the particularity of chattel slavery emphasizes how the economic and social function of the enslaved as laborer and commodity, the centrality of blackness as a fungible and immutable category of the enslaveable (non)human, and the massive global function of chattel slavery as the foundation of capitalism distinguishes this formation from other historical or regional structures of slavery, labor exploitation, trafficking, and racialized domination. Furthermore, students will be challenged to confront the ways in which the de jure abolition of chattel slavery (in 1865 in the US and across the Americas in the 19th century) has been a historical, legal, and structural misnomer that does not capture the ways in which societies, economies, and legal structures adapted to sustain rather than eradicate the global dependence on black subjection. Students will engage the prison industrial complex, abandonment &amp; deindustrialization, policing, geographic containment, the consumption of blackness as popular culture, formations of neoliberalism, and antiblack state and state-sanctioned terror as contemporary formations of chattel slavery’s afterlives. The course engages the geographic contexts of the US, Jamaica, Haiti, and other parts of the Caribbean. Cross-listed as BLST 375. <em>Core Requirement Met: United States Diversity.</em></p> <p><strong>Racial Capitalism</strong></p> <p>This course examines the concept of racial capitalism, or the relationship between racialist ideologies and the uneven development of global capitalism. To do this, we will explore several phases in this process of development, starting with the colonization of the Americas and the development of intra-European nationalism, then looking at the colonization of South and/or East Asia, followed by the abolition of slavery in the U.S., and finally the post World War II decolonziation and/or neocolonization of Africa. Through this, we will investigate how the capitalist world system produces ideological heterogeneity rather than universalist homogeneity. Authors to be read include Cedric Robinson, Oliver C. Cox, Immanuel Wallerstein, Walter D. Mignolo, Maria Lugones, Lisa Lowe, Ranajit Guha, W.E.B. Du Bois, Kwame Nkrumah, and Frantz Fanon. <em>Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15080,2027,515,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15081,2027,2548,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-398','<div class="desc"> <p>Working with a CTSJ faculty member, students will select an internship site whose mission is to address matters of inequality and social justice. The Department has a list of organizations where students can inquire about internships. Students who would like to intern at an organization will have to petition the department with a letter of support from the organization. The practicum experience will be evaluated by their field supervisor, the faculty liaison, and by the completion of the Social Justice Practicum Handbook. In addition to the internship responsibilities, students will participate in regular meetings with the instructor and attend class meetings. Additionally, they will complete a social justice practicum handbook, which requires deep reflection that brings the internship experiences in dialogue with critical theories related to matters of social justice. Students may participate in internships as individuals, pairs, or small groups, depending on the needs of the organizations. Open only to Critical Theory &amp; Social Justice majors with sophomore standing or above.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15082,2027,1693,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/300/ctsj-399','<div class="desc"> <p>Students in this advanced methods course will join the professor in conducting research in the specialty areas of the instructor. This course will fulfill a methods requirement and will necessitate that the student participate with the professor and other students in a collaborative manner to meet the goals of the research project. Research methods may include: critical discourse, oral histories, archival work, ethnography, and cultural studies, quantitative analysis, interview methods. Research projects may include topics such as: (1) youth and incarceration; (2) the discourse of "war"; (3) Europe''s discourse on migrant people; and (4) literacy, language, and children, to name a few. Open to juniors and seniors only. Permission of instructor required. May be repeated once for credit. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15083,2027,90,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-490','<div class="desc"> <p>Each year, the senior class in CTSJ will undertake a shared project addressing a specific and concrete political or social problem identified by the department faculty in advance of the seminar. Students will collaborate to address the problem, bringing to bear a variety of intervention modalities, including: theoretical, clinical, qualitative, critical-legal and quantitative research approaches as well as activist techniques and practices. In some years, the senior seminar may partner with a specific organization that is focused on addressing the problem taken up by the seminar. When this is the case, students will have the opportunity to work with the partner organization as volunteers. The individual student contributions to the seminar project will serve as the senior comprehensive project for the major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15084,2027,4173,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ctsj-critical-theorysocial-justice/400/ctsj-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15085,2027,4437,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/100/cwp-100','<div class="desc"> Every year, Oxy students apply to and win a variety of fellowships to support research, language learning, teaching, community work, and other opportunities. Even if not awarded a fellowship, applicants develop skills through the application process that help them apply for graduate school or jobs in the future. In this course, students will learn how to search for fellowships that fit their values, academic interests, and professional goals. Through exercises and written assignments, students will practice reflective and persuasive writing explaining their motivations, achievements, character, and aspirations to different audiences. All students will complete a draft fellowship application and practice interview as a final project. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15086,2027,3860,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/100/cwp-135','<div class="desc"> <p>The Occidental Weekly practicum is for those who want to become section editors at the Occidental Weekly or simply want a further understanding of how daily journalism works. We will learn about ethics, management, editing and planning functions; we will not specifically study writing. Class assignments include three sets of story pitches and two news memos. The goal is for you to be ready to walk into a newsroom with an understanding of the language, disciplines, and best standards and practices. We will have occasional guest speakers on nuts-and-bolts topics, such as the use of language and the difference between news presentation in digital and in print. This is a graded course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15087,2027,4174,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/100/cwp-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15088,2027,3831,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-201','<div class="desc"> <p>This course provides students with opportunities to develop and practice the skills and habits that are foundational to academic writing and with knowledge of how to adapt these skills and habits for the varied writing demands students will encounter in college. This course fulfills (when passed with a grade of "C" or better) the college''s First Stage Writing Proficiency Requirement (and in some cases, the Second Stage Writing Proficiency Requirement), and it is also appropriate for students in various disciplines seeking to develop their writing, argument, analytic, and communication skills. All sections of this course focus on developing complex writing, analytical, and research skills for various audiences, disciplines, and genres. May be repeated to fulfill both the First- and Second-Stage Writing Requirements.</p> <p><strong>Art House Cinema</strong></p> <p>In this course, we will explore a selection of “art house” films and consider the important technical and imaginative differences between them and those made within the traditional Hollywood studio system. Selections range from low-budget, DIY independents to international masterpieces. Film analysis will be complemented by a variety of readings from some of the sharpest and most insightful critics of not only cinema but also painting, theater, music, and other fine arts.</p> <p><strong>The Body Politic: Writing in the Politics of Pleasure </strong></p> <p>This course will examine the politics of sexuality in the U.S. It aims to consider intersectional identities and cultures drawing on social considerations with respect to race, gender, and sexuality. The regulation of sexuality by the state, and the commodifying of sex will be studied as well as power and the body. Readings from Audre Lorde, Michael Foucault, and others will be explored.</p> <p><strong>Writing About Independent Film</strong></p> <p>This section will explore independent film as an important art movement and alternative to the commercial mainstream. We will focus on a small number of personal, low-budget films made outside the studio system and consider the important ways they break from Hollywood, both stylistically and imaginatively.</p> <p><strong>Rhetoric and the Fine Arts</strong></p> <p>This course is designed to provide intensive, guided training in college-level writing through the study of the fine arts—including but not limited to painting, music, film, and poetry—with an emphasis on recent work, exhibitions, and scholarship. Students will enter the current cultural conversation by writing their own critical essays, employing a variety of rhetorical techniques. Our focus will ultimately be on all the core elements of successful academic writing, including thesis statements, the use of evidence, source integration, developing and expanding ideas, and matters of form, clarity, and style.</p> <p><strong>Writing in Class, Whiteness, and Conflict </strong></p> <p>The readings and assignments in this course are designed to help students understand the social constructions of class hierarchies and the emerging theories about white identity politics, whiteness, and how race informs class analysis. We will engage in critical analysis and written argument to explore white identity, white supremacy, and the intersections of race, class and geography.</p> <p><strong>Writing, Rhetoric, and Formal Poetry</strong></p> <p>This section will focus on the relationship between poetry and rhetoric--more specifically, how form shapes understanding and is used to construct different types of rhetorical argument. We will study a variety of texts including poems, critical essays, biography, and literary and rhetorical theory.</p> <p><strong>Writing, Gender, and Sexuality</strong></p> <p>This section will explore gender and sexuality in our contemporary American context. Drawing on readings from pop culture, critical theory, current events, and literature, we will examine how gender and sexuality are constructed, theorized, and represented, and how they intersect with other areas of identity including race and class.</p> <p><strong>Wanderlust Writing and Rhetoric</strong><br/> This section will explore the writing and rhetoric of wandering and adventure, from premodern adventure stories to the present-day #wanderlust as a synonym for free-spiritedness and Instagram humblebrags; our texts will be drawn primarily from literature, pop culture, and critical theory.</p> <p><strong>Protest Writing and Rhetoric</strong></p> <p>This section will examine the rhetoric, ideology, and context of protest genres, including social movements, speeches, literature, and visual texts, as we consider how writers, artists, and activists protest issues relating to race- and class-based oppression, gender inequity, ableism, colonialism, homophobia and heterosexism, and other concerns.</p> <p><strong>Writing on Travel</strong></p> <p>This section will examine travelers'' tales ranging from pilgrimages, the Grand Tour, island vacations, luxury cruises, and scientific expeditions, analyzing them from anthropological and post-modern critical perspectives, all while exploring images and texts from the 1700''s to the present.</p> </div>','Not open to first-year students ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15089,2027,4175,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-235','<div class="desc"> <p>This course will examine the forms and uses of visual images to inform argue and inspire--in order to analyze their effectiveness expressing ideas across the millennia from ancient civilizations through the present digital age. We will examine codices illuminated manuscripts stained glass panels and maps; combinations of words and pictures from scientists poets printers and graphic novelists; as well as digital images such as memes information graphics data visualizations and multimedia arguments. Both the theory of visual rhetoric and the making of images in some of these media will complement our exploration of these genres. </p> <p><strong>Visual Rhetoric: The Power of Images</strong></p> <p>From prehistoric cave paintings to memes designed to reach millions of people, images have historically been used to shape our understanding of the world. The goal of this class is for students to recognize and critically respond to the different ways images shape meaning, focusing on the ways visuals have been historically used to persuade, influence, and inspire. Students will engage in scholarly criticism about visual arguments and analyze the power of images across a variety of media, including but not limited to architecture, film, graphic design, typography, painting, political cartoons and campaign material, advertisements, and commercial packaging. Ultimately, students will develop their visual literacy by writing scholarly critiques of visual media and creating rhetorical images of their own.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15090,2027,4176,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-250','<div class="desc"> <p>Writing in the Community may take many forms. Specific topics will vary. Students may repeat once for credit if taken as different topics. Current topics listed below:</p> <p><strong>Writing and the Los Angeles Experience</strong></p> <p>A combination writing workshop and community-based learning course, Writing and the Los Angeles Experience examines how Los Angeles shapes and is shaped by those who write about the city. Readings, class discussions, and writing assignments will engage the work of local writers whose work revolves around the city—such as Paul Beatty, Francesca Lia Block, Luis Rodriguez, and Brando Skyhorse—and the parts of Los Angeles that are central to their experience. Guest speakers and field trips to visit different areas of the city and attend live events will help us explore the way the city influences those who write about it, and the cultural, social, and political forces that make it tick. The work of this course is both critical and creative: students will write about our readings using conventional tools of academic writing and rhetoric, and respond to their own experiences of the city in reflections, stories, or other creative projects. Core Requirement Met: US Diversity and Fine Arts.</p> <p><strong>Professional Writing on Social Issues</strong></p> <p>This course encourages an engaged and dynamic approach to writing studies as it places writing in real-world contexts by partnering Oxy students with nonprofit community organizations in greater Los Angeles. Through these partnerships, students will identify local cultural and social concerns on topics such as homelessness/housing insecurity, poverty, immigration, education, and social activism, which represent the interests of our particular community groups. In this class we will explore a wide range of research and writing strategies common to both academic environments and the professional situations of our community partners, including primary or field research and both individual and collaborative writing projects in professional genres. This course will allow students to see community nonprofit organizations -- plus the cultural social and political issues and rhetoric surrounding them -- from the inside out. The work of this class is thus both scholarly and practical, motivating student learning by enlivening and enriching students'' approaches to writing studies. Core Requirement Met: Global Connections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15091,2027,4177,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-265','<div class="desc"> <p>This course is an introduction to feminist rhetorical history and criticism as it foregrounds the study of how women "stand and speak" using rhetorical strategies to address social and cultural issues that impact them. This class positions the study of feminist rhetorics within the larger study of language and discourse theories as we examine how social relations power knowledge and identities are constituted through private and public rhetorical acts. Through our readings we will engage a wide range of contributions to a rhetorical critical history by women who either as practitioners or theorists advanced their visions of social change and acted to implement them. Course readings will begin in antiquity to provide a foundation for our study though much of our material will focus on texts from the nineteenth-century to the present to examine the intersections of gender and rhetoric. Through this work we will challenge the seeming erasure of women from this critical history and interrogate the notion of "feminist rhetoric" as merely a corollary to a masculinist tradition. Assignments will include critical essays and a visual rhetoric project on representations of women in the media and popular culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15092,2027,3832,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-275','<div class="desc"> <p>This course is designed to give students the chance to combine skills in critical analysis and writing with their interests or training in the sciences. Students do not need to have a science background or be majoring in a science field to be successful in this class, but they do need to have an interest in science in order to write about it in compelling ways. The central goal of this course is to help students develop and refine skills in presenting scientific topics to popular audiences and presenting themselves as strong candidates for graduate programs, jobs, and internships in the sciences. Course readings and assignments will span a range of scientific fields, including environment and ecology, cognitive science, psychology, medicine and health, and life sciences.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15093,2027,3833,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-285','<div class="desc"> <p>This course is an intensive introduction to the theories and practices of a trade that is protected by the 1st Amendment of the U.S. Constitution, essential to democracy, and yet increasingly under threat. Taught by a Pulitzer Prize-winning report, editor, columnist, and author who bolsters his teaching with distinguished guest speakers, this class introduces students to the core values and nuts-and-bolts skills demanding by the rapidly changing field of journalism, while teaching critical thinking skills that are key to global citizenship. Students will learn to research, report, interview, and then write with rhetorical force in the concise, clear newswriting style that remains the foundation of journalism in its myriad, multi-media forms. This course focuses on media influences across a range of geographical locations including Europe, Asia, Central and South America, as well as the U.S. The course will focus on regions and nations that are most in the news at the moment of the course semester. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15094,2027,3897,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-286','<div class="desc"> <p>In this course students will learn to combine the reporter''s craft with creative writing skills to produce compelling nonfiction. The class teaches students how accurate, factual stories can more fully convey insight into contemporary issues and the human condition by tapping the power of fictional techniques such as character development, use of dramatic tension, dialogue, and narrative structure. The course develops students'' research, reporting, and interviewing techniques, while focusing on the craft of writing. Using the spectrum of rhetorical devices, students will strive to create well-told stories about who we are, how we live, and the forces that shape our existence. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15095,2027,3834,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-287','<div class="desc"> <p>The 21st century has seen an abrupt escalation of government, corporate, and nonprofit institutions'' use of technology-sharpened rhetorical tools to disseminate information and, increasingly, disinformation to individuals and the public. Journalism, one of democracy''s most important forces for distinguishing truth from propaganda, has simultaneously been decimated by technological and economic change. This course offers an insider''s perspective on the theory and practice of rhetorical persuasion. This course will examine the forces that shape public opinion about recent history''s most significant issues, including climate disruption, education, immigration, and war. With a focus on opinion journalism, this course examines historical and current practices globally in examples such as Nazi and Stalinist propaganda in WWII, to international discourse on Vietnam, Iraq, and Afghanistan. Students will learn to write and critique editorials, op-eds, blog posts, and strategic communications'' plans driven by social media messaging, while scrutinizing the shared interests and deep tensions between journalism and public relations, publicity and marketing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15096,2027,3835,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-295','<div class="desc"> <p>This class will engage the historical theoretical and cultural dimensions of rhetoric in a range of disciplines in the arts literature politics and philosophy. In readings from Aristotle to poststructuralist theory we will examine all aspects of the rhetorical situation (exigence audience and rhetor) and the contexts in which rhetorical acts occur. We will examine how language practices intersect with culture and identity including class race sexuality gender and nation as we consider how arguments are constructed and how writing and narrative transform culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15097,2027,4178,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/200/cwp-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15098,2027,3899,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/300/cwp-301','<div class="desc"> <p>This advanced composition workshop explores creative nonfiction, a term that encompasses many genres, including memoir, profile writing, personal essay, humor, nature and travel writing, criticism, and narrative journalism, among others. This course will focus on 3-4 genres of creative nonfiction over the course of the semester. Each unit will pair a writing assignment in a particular genre with popular readings from that genre, by authors such as Paula Gunn Allen, Truman Capote, Ta-Nehisi Coates, Junot Díaz, Joan Didion, Audre Lorde, Adrienne Rich, Zadie Smith, and David Foster Wallace. The course will encourage experimentation while also paying close attention to audience, genre conventions, and other principles of successful writing. The workshop format relies on extensive peer review and revision, and each student will produce a capstone piece at the end of the semester after revision based on peer and instructor feedback. </p> </div>','Student must have passed the first-year writing requirement and/or CWP 201 (formerly WRD 201). ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15099,2027,4179,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/300/cwp-393','<div class="desc"> <p>CWP 393: Directed Research is offered as a replacement to WRD 397: Independent Study. When approved by the faculty instructor and program chair, CWP 393 will allow students to pursue research in an area of writing and rhetorical studies. The specific topics of this research are dependent upon the student''s area of focus (which align with the instructor''s areas of expertise).</p> <p>Permission of Instructor Required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15100,2027,3836,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/300/cwp-395','<div class="desc"> <p>An exploration of the theory and practice of writing instruction, this class emphasizes rhetorical strategies, audience expectations, and forms of academic discourse. This course also provides new advisers with an introduction to tutoring practices and strategies through Writing Center scholarship. Permission of instructor required.<em>This class is only for Peer Writing Advisers working in Writing Center. </em><em>May be repeated once for credit. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15101,2027,3981,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/400/cwp-495','<div class="desc"> <p>The Writing Fellows Practicum is for current Writing Fellows working in the Writing Center as embedded tutors in selected FYS courses. In the practicum, Writing Fellows will gain knowledge of advanced writing pedagogy, how to design and implement writing curriculum, and enhance their training and skills in working with students in a classroom environment. Work will include weekly workshop reviews, discussion of assigned readings and other materials, and practical engagement in best practices in teaching writing and writing center work. Enrollment in this practicum requires permission of the Writing Center Director, hiring as a Writing Fellow, and completion of two semesters of CWP 395 (with grades of A- or higher). </p> </div>','Permission of the Writing Center Director (following hiring as a Writing Fellow by the Director and completion of two semesters of CWP 395 with grades of A- or higher). ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15102,2027,4180,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/cwp-college-writing-program/400/cwp-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15103,2027,120,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-101','<div class="desc"> <p>The purposes of this course are: (1) to introduce fundamental tools and perspectives on the study of world politics, including major theories and analytical approaches to international relations, (2) to understand the historical evolution of the contemporary international system, with special emphasis on the post-World War II era, and (3) to apply theoretical and conceptual understandings of international relations to current issues in world politics. Emphasis is placed on the state and trans-state foundations of contemporary international relations. We will study this in the context of such key issues as economic development, "security," human rights, state-building, international organizations, terrorism, and the intersection of social relations with world politics. Open to first years and sophomores. Permission of instructor required for junior and senior enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15104,2027,1655,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-102','<div class="desc"> <p>A survey of the role of international organizations in global politics. The focus will be on an in-depth study of the three themes by which the United Nations has defined itself: security, human rights, and development. Within the rubric of those three themes we will look at activities by the U.N. family of agencies, other international organizations, and NGOs, on issues that include the management of violent conflict, human rights, and how these issues have been mainstreamed into the work of international organizations and approaches to economic underdevelopment that seek to alleviate both poverty and insecurity.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15105,2027,2549,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-103','<div class="desc"> <p>This course is an undergraduate survey of the field of Global Political Economy (GPE), required to major in Diplomacy and World Affairs. It is intended as an introduction for students who already have some background in the field of International Relations (DWA 101) and are interested in exploring global political economy theories, relations and issues. The course covers major theoretical, empirical and policy perspectives. The first part of the course will cover basic concepts and theoretical foundations of political economy: liberalism, Marxism, realism, feminism, etc. The focus will be on core theoretical principles and approaches. The goal is to understand how theory is framed and how it "works"; the potential inferences of theories, and their practical import. The second part of the course delves into globalization as a field of study and set of empirical dynamics, building on the theoretical foundations of the first part of the course. The third part of the course explores emerging topics in global political economy such as global finance, the informal economy, the underground economy, the green economy/sharing economy/circular economy, gender and the global economy, corporate citizenship and responsibility, social enterprises, the sustainable development goals, social/economic rights and more. Open only to DWA majors; for non-majors, special permission of instructor required.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15106,2027,1444,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-152','<div class="desc"> <p>This course will introduce social enterprise practices and theory while allowing students to work directly on a social enterprise project with global impact. This course will build on the 25-year foundation of collective knowledge in the field of Social Entrepreneurship through case studies and life challenges that continue to face the international community. We will look at how value creation and sustainability are key elements in the development of successful social enterprises, with emphasis on water, food, and housing/urban design. Our focus will be on how, through innovation and entrepreneurial approaches, we can access sustainable solutions to the world''s most pressing problems.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15107,2027,4181,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15108,2027,4182,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/100/dwa-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15109,2027,1588,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-233','<div class="desc"> <p>The purpose of this course is to explore the themes, issues, and trends that shape politics in Africa across 54 countries with over one billion people. The course will cover broad issues such as the foundations of contemporary African politics, the characteristics, and consequences of leadership in Africa, the politics of identity, and economic and political change in Africa. You will be introduced to the continent through the perspectives of four critical African literary and political thinkers, each bringing a novel perspective to African political identity. These texts illustrate the nuances of a contested identity that is ascriptive and that derives meaning from local and indigenous roots. While each author writes about specific countries in Africa, they highlight themes of significance to the broader experiences of colonialism, revolution, and post-colonial systems. They also engage with the racism intrinsic to Whiteness/Eurocentrism that frames the parameters of this field.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15110,2027,2426,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/copy-of-dwa-240','<div class="desc"> <div><p>Colombiaâs 2016 peace accord formally brought an end to a half-century of that countryâs civil wars. The accordâs implementation, however, has been troubled. This raises issues relevant to Colombia and to other locales putatively transitioning out of violent conflicts. This course will address those issues in a Colombian context and by comparative reference to examples from other countries in the Americas and around the globe. Specifically, what is transitional justice and how might it inform peace-making in a country such as Colombia? Are human rights relevant to more effective transitional justice processes? More specifically, can they inform a truth-telling processes that takes into account the distinct context of a country such as Colombia and helps it establish the basis of a more pluralistic social contract that engages all of its remarkable diversity, including identities (ethnic, gender, sexual) that have long been marginalized? The course uses Colombia as a focal point, but will draw from other comparative cases both from Latin America and the globe.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15111,2027,2333,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected what was historically the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean that has developed into proper noun: the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological, and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the 20th century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-1939 Palestinian Revolt, the 1948 war for Palestine and its aftermath, Israeli-Arab relations in the 1950''s, the Suez War, the implications of gendering the nation, the 1967 war and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15112,2027,121,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-201','<div class="desc"> <span>During World War II, Polish Jewish refugee and lawyer Raphael Lemkin coined the term genocide to describe Nazi occupation policies and practices. In 1948, the United Nations codified this term in international law by adopting the Convention on the Prevention and Punishment of the Crime of Genocide. This course introduces students to the critical study of systematic mass murder and the possibilities and limitations of the genocide concept. Using a transdisciplinary approach that draws on history, philosophy, law, psychology, politics, anthropology, and cultural studies, students will survey the field of comparative genocide studies as it has developed in the last century World War II. Students will interrogate legal and political definitions of genocide, compare the origins, development, and forms of genocidal violence, and explore public debates about genocide representation and prevention. Students will consider dimensions such as colonialism and indigeneity, gender and sexuality, social psychology, and justice and will examine cases of systematic mass murder across the globe, including in New Spain, German South West Africa, the Ottoman Empire, the Third Reich, Indonesia, and Guatemala.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15113,2027,2850,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-210','<div class="desc"> <p>This course introduces students to the diverse politics, societies, and international relations of countries in Eastern Europe, Central Asia, the Caucasus, the Baltic states, and Russia, shaped by shared yet distinct state-socialist experiences. It examines post-communist political and economic transformations since 1991, exploring variations in governance, state-society relations, foreign policy and interstate conflict. Through comparative methods, students engage in assignments encouraging cross-national or temporal analyses of multiple states, fostering balanced regional understanding.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15114,2027,3902,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-219','<div class="desc"> <p>South Asia is a region with a rich political history, offering recent examples of independence movements, secular democracies, absolute monarchies, and military dictatorships. Bound by the Himalayas to the north and the Indian Ocean to the south, the region comprises eight developing and emerging nations â Afghanistan, Bangladesh, Bhutan, India, the Maldives, Nepal, Pakistan, and Sri Lanka. Each of these eight countries has a unique political trajectory that continues to be deeply informed by the political reality of its neighbors. This course offers a comprehensive introduction to the comparative politics of the region, with a focus on four key characteristics: the colonial legacy in shaping South Asian political institutions, the intraregional relationships including those that have escalated to violent conflict and war, the political economy of development, micropolitical processes that shape democratic outcomes and the future of democracy in the region.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15115,2027,827,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-221','<div class="desc"> <p>Against the backdrop of 840 million persons worldwide suffering from malnourishment, and nearly 1.3 billion people living on less than a dollar per day, this course surveys the fields of international development, wealth creation, and global welfare, from a historical, global, and comparative perspective. The course will introduce students to the field''s academic contours, building from the historic role of economics in pioneering and undergirding the field, to a broad understanding of the now interdisciplinary field that has emerged. The multi-disciplinary and interdisciplinary perspective of this introductory survey course is in keeping with an emerging global consensus that measures of poverty go beyond income and consumption, and that poverty reduction requires bridging disciplines (Economics, Political Science, History, Anthropology, Geography) and methods (quantitative and qualitative, observational and participatory). The course will be divided into two parts. During the first part of the course, students will be introduced to the main theoretical ideas on social, economic, and political development that have informed the field''s evolution. This will familiarize students with fundamental thinking on development, as well as the frontiers of research. The second part of the course will explore some of the current debates about development. Students will analyze such debates in a rigorously multi-dimensional and interdisciplinary manner.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15116,2027,2425,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-222','<div class="desc"> <p>This course introduces students to the political economy of Latin America. The first section of the course looks at the rise of dependency theory and import substitution industrialization (ISI) as the region''s predominant development strategy. We will study the motivations behind ISI, its initial success in terms of economic growth, and the challenges associated with such strategies of development. We will focus on the origins of the 1980''s debt crisis, the abolishing of the ISI model, and the subsequent turn to neoliberal development strategies. The course aims to provide students with a deeper understanding of the transition to neoliberalism, the so-called Washington Consensus, and the broader political and economic implications of the reform processes that have unfolded since the early 1980''s. We will study the interaction between democratization and economic reform and aim to understand how these simultaneous transitions have affected the policy-making process and the formation of public policy in the region. Latin America is a diverse region; therefore, this course will emphasize its economic and political diversity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15117,2027,1587,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-224','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century, with a focus on contemporary democratic politics. The course will discuss the historical, institutional, and social forces that have both accelerated and opposed democratization, and will cover topics of current concern to the region, including: economic development, security and the rule of law, the design of political institutions, human rights, and social movements.</p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15118,2027,1213,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-225','<div class="desc"> <p style="margin-top: 6pt">This interactive seminar offers a broad introduction to international human rights theory and practice through the lens of poetry, non-fiction, documentaries, and feature films, with a primary focus on rights debates within the global arena. The course will include case studies centering on the intersection of racial and environmental justice, gender and sexuality, genocide and crimes against humanity, and transitional justice, which allow for the consideration of questions relating to the universality or relativism of human rights, the duty-bearers of human rights, the politics of memory, and the relationship between justice and reconciliation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15119,2027,2334,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-226','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal," "populist," and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems, including the United States; and the challenges democracies are facing in integrating formerly marginalized populations, including women, poor, and the indigenous. It will examine the United States policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15120,2027,2826,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-227','<div class="desc"> <p>Thirty years after Francis Fukuyama proclaimed the "End of History," political authoritarianism remains viable while democracy is increasingly under threat around the world. Many dictators have embraced hypermobility of capital, free trade, and modern information technology. At the same time, deepening globalization has also challenged long-established democratic systems, producing anti-democratic political movements. We will investigate some of the following questions produced by the clash between global capitalism and local politics: How do authoritarian leaders react to the challenges of globalization in the 21st century? Does globalization undermine or enhance their hold on power? Will authoritarianism or democracy survive a long-term engagement with global markets?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15121,2027,2335,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-228','<div class="desc"> <p>This course explores efforts to conceptualize democracy, and to generate and test theories of democratization and the endurance of democracy. After considering the concept of democracy, we start by considering some of the classics, published in the second half of the 20th century. These are key works that have shaped the field and have largely set the terms of the debate. Then, we turn to the literature published after 2000 and consider how this literature has revised and built on ideas from the classics. We conclude with an overall assessment of knowledge about democratization and the endurance of democracy. In all, we will discuss explanations that put an emphasis on the economy and culture, as well as on politics itself. Much of what we will read reflects the focus of this literature on Europe, Latin America, and post-Soviet Eurasia. However, some African and Asian cases will be discussed and several global analyses will be considered. Emphasis will be put on the core theoretical and methodological aspects of this literature.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15122,2027,1327,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-229','<div class="desc"> <p>After a review of the historical, legal, and conceptual underpinnings of the international protection of human rights, students in this course will learn about human rights and mechanisms for their protection within the context of the United States and Latin America. Students will discuss key situations from the last half century involving challenges to human rights, including the phenomenon of disappearances common in Argentina and Chile in the 1970''s, violations of human rights during leading up to and during civil conflicts in Central America, and the impact of neoliberal economic reforms on human rights in the region. Students will explore the application of the death penalty in the United States, United States foreign policy on human rights in the Americas during the Cold War, and the claims of human rights abuse by the United States during the War on Terror. They will also have a chance to examine the United States from a double perspective: on the one hand as a key country with a major interest and impact on human rights conditions in Latin America, and, on the other, as a country with its own policy areas of struggle and progress.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15123,2027,548,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-230','<div class="desc"> <p>This course will explore the evolution of women''s rights as human rights; the struggle of women''s movements to place gender-specific concerns on the international human rights agenda; and the relationship of the UN and its agencies to the broad feminist goal of advancing the political, economic, social, and cultural status of women. While "women" are, of necessity, central to the concerns of this course, the study of human rights will be approached from a gender perspective, recognizing that gender relations are key to understanding the nature, occurrence, and prevention of rights violations. Key themes to be covered in the course include: the relationship between the "crisis of masculinity" and women''s human rights, gender and economic rights, gender-based violence, and health and human rights.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15124,2027,1115,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-231','<div class="desc"> <p>This course explores how assumptions of masculinity and femininity have informed foundational concepts and theories in the field of International Relations, the determination of what is considered to be worthy of investigation and what qualifies as appropriate methods of investigation, and who is (and is not) recognized as a subject of international politics. This course applies a gender lens to practical concerns in the field, including: political and economic development, human rights, and international security. It also engages the tensions associated with theorizing gender and IR, given the fluidity and intersectionality of identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15125,2027,1328,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-232','<div class="desc"> <p>Topics may vary semester to semester. </p> <p><strong>Transnational Social Movements</strong></p> <p>This course focuses on contemporary social movements with particular attention to transnational information flows. Concentrating on strategies, methods, and approaches to oppositional action, the course will study the global rise in the civilian mobilization against leaders and states perceived as corrupt and or unrepresentative. For example, organizations like <em>Black Lives Matter</em> have influenced and were influenced by <em>Rhodes Must Fall</em> in South Africa. Similar movements in Serbia, Egypt, China, Czechoslovakia, and Iran where unarmed people opposed powerful states encouraged the student protest movements in Hong Kong. Writers like Gene Sharpe, Erica Chenoweth, and others who have written extensively about non-violent means of protests, have influenced many of these contemporary organizations. Academic perspectives on social movements and revolutions will frame the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15126,2027,549,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-234','<div class="desc"> <p>Revolutionary transformations and democratic transitions in Southern Africa have occurred under the conditions of the Cold War and within the framework of heightened globalization. Currently, direct foreign political interventions have been scaled back, but economic interventions by international organizations and foreign states have increased. Even though liberal democracy is winning favor the structural basis of inequality remains with increasing unemployment, poor education, weak health services, inadequate housing, soaring food and utility prices, and increasing levels of poverty. Opposition movements demand changes ranging from subsidized basic foodstuff to free education. This has contributed to political tensions as states scramble to suppress resistance while still trying to maintain the conditions required by global economic institutions. This course will examine some of the states in this region including South Africa, Mozambique, and Zimbabwe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15127,2027,123,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-235','<div class="desc"> <p>This course will explore nationalism and ethnicity from both a theoretical and an empirical perspective. Nationalist and ethnic discourses have been central to political movements, rebellions, and revolutions. The passions and commitment of individual members in these movements often lead to political ideologies and war tactics that are violent, and which encompass entire communities. The class will concentrate on two theoretical perspectives; mainly the debates between primordialism and constructivism. Two cases from South/Southeast Asia and Sub-Saharan Africa will be analyzed.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15128,2027,1589,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-236','<div class="desc"> <p>This course examines the theoretical roots, ideological expressions, and political manifestations of these tumultuous phenomena. Focusing mostly on the European experience of the late 19th through the 20th century, we will read primary texts and historical accounts pertaining to the rise and development of nationalism, communism, and fascism. Readings will cover both the national and international aspects of these movements, and explore their political, cultural, and economic programs. What will also be of particular interest is how these often competing and clashing political programs sprang from similar and, at times, common roots. Ultimately, this course will ask students to consider what the study of such ideologies has to offer for the analysis of contemporary extremism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15129,2027,917,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-237','<div class="desc"> <p>The course will examine some of the communist countries that have survived the collapse of the Soviet Union, specifically: Cuba, Vietnam, and China. We will discuss the political and social life within each country, their relationship to the United States, and the prospects for political change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15130,2027,124,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-238','<div class="desc"> <p>This class will focus on South Asians who were indentured to British colonies from 1860, immediately following the abolition of slavery. Over one million Indians were indentured to Mauritius, South Africa, Guyana, Trinidad, and Fiji. South Asians currently constitute a substantial proportion of the population in each of these countries, and they are in the majority in Mauritius and Trinidad. We will conduct a comparative study based on theoretical perspectives related to the diaspora''s globalization, trans-state identities, and analytical themes associated with identity and citizenship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15131,2027,1656,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-239','<div class="desc"> <p>This course aims to introduce students to the history, politics, and economics of the European region from 1945 to present day. We will start by looking at the development of European states and political institutions in the post-WWII period, primarily those of Germany, France, the United Kingdom, and the Benelux countries. Our goal is to gain understanding of why European states have taken different political paths (including countries in Eastern Europe, the Nordic states, and Turkey), while also exploring the context of regional integration in which European states are embedded. The European Union (formerly the European Community) and its 28-member states are thus also central to this subject, as it encapsulates the development of key political institutions, civil society, representation, and economics on the continent. We will thus explore what has been accomplished by European integration (e.g., maintaining peace, increasing mobility, granting human rights, enhancing multilateralism, and strengthening democracy), as well as the considerable challenges that lie ahead (e.g., "Brexit", eastern enlargement, the stability of the Euro, the integration of refugees, and the rise of populist parties). In sum, the course is designed to introduce students to central topics in both past and contemporary Europe politics through the lens of political science and theories of regional integration. Situated at the intersection of comparative and international politics, these theories will help us to understand the complex interactions between national governments, supranational institutions, and the everyday lives of European citizens that define Europe today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15132,2027,125,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-241','<div class="desc"> <p>A study of Middle-Eastern international relations in the context of three themes that structure the region''s modern political history: (1) colonialism: how the reaction against colonialism continued to define and limit Middle-Eastern politics, both internally and in its relations with outside powers, (2) religion: in particular, political Islam (or "fundamentalism") is a key variable in the region''s contemporary politics, but by no means all-defining, and (3) nationalism(s): a source of political identity and mobilization. How religious, national, linguistic, and ethnic nationalisms inform conflict and cooperation within the region. </p> <p>In the context of these three themes, we will explore the following regional issues with global implications: (1) the Arab-Israeli conflict - the flash point of conflict in the Middle-East, the Arab-Israeli conflict can only be understood on the basis of an informed appreciation of its historical and ideological underpinnings, (2) Iran - the Iranian revolution had an enormous impact on regional and international affairs. Current unrest within Iran is perhaps a harbinger of yet another radical shift in Iranian politics, and (3) domestic upheaval in the region, as seen in the Arab uprisings of 2011-2012.</p> <p>Despite this being an "IR" class, on-the-ground social and political movements ("domestic," yet transnationally informed) have an enormous impact on the region''s politics. This is particularly true in the shadow of the recent Arab uprisings, upon which we will place particular attention.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15133,2027,1590,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-245','<div class="desc"> <p>This course will look at the relationship China has had to the world over the last 600 years. The course will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Third-Worldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the interaction between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the rise of the West, just as we will call into question the contemporary discourse on the "rise of China."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15134,2027,2537,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-246','<div class="desc"> <p>This course analyzes various types of interaction between the United States and East Asian countries from the late 18th century to the present. We shall examine the dynamics of cultural contact and conflict, the process of economic development in a trans-Pacific and international context, the changing roles of the United States in East Asian affairs, and power rivalries in the Pacific Rim.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15135,2027,1377,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-248','<div class="desc"> <p>This course will examine major global public health problems and the range of responses from international organizations, transnational networks, and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century, the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as: HIV/AIDS, malaria, unsafe food and water, tobacco use, and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health, including morbidity; mortality; demography; epidemiology; and the political, social, and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political, economic, social, and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health, and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15136,2027,828,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-250','<div class="desc"> <p>This course is an introduction to International Security and Strategic Studies. This field is, fundamentally, about both the use of force by, and violent conflict among, states and non-state actors. The course will be guided by general theoretical questions regarding security: how does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: how do states and non-state actors use force to persuade their enemies to take (coercion), or refrain from taking (deterrence), a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure and the intensity, duration, and consequences of military action? We will have a particular focus on emerging transnational security issues, intra-state security, and the relationship between security development and state failure. Pursuing answers to these questions will require an approach that integrates theory, history, and current events. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15137,2027,1445,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-253','<div class="desc"> <p>China''s return (as opposed to rise) to its proportional place in the global economy has arguably caused a pivot towards Asia by the United States. While America''s hegemonic status in terms of hard (military) power remains undisputed, China''s gross domestic product may surpass that of the United States as soon as 2017. This course is a seminar on Asian security, covering military security, non-traditional security, and economic and political security, among other dimensions. The course surveys the Asian region, with particular emphasis on Southeast Asia (the ASEAN countries, particularly Cambodia Burma/Myanmar, Thailand, and Singapore) and Northeast Asia (China, Japan, South Korea, and Taiwan). The material is divided into three parts. The first provides an overall introduction and overview of Asian security and focuses on the foundations of what was thought to be the Asian Miracle (created in part from a U.S. security umbrella), just as the Washington Consensus rose to prominence. It takes students through the Asian Financial Crisis and its aftermath. Part two of the class focuses on Japan, South Korea, China, and Taiwan. It describes their development trajectories and security arrangements. Part three uses China as a platform to examine other parts of Asia not already covered, such as: China''s relationship with Southeast Asia, and the political economy of non-traditional security, in particular the region''s experience with Highly Pathogenic Avian Influenza.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15138,2027,1694,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-256','<div class="desc"> <p>This course analyses terrorism not only from a state security perspective, but also from one informed by political ethics, in which we seek to come to terms with the demands of justice in an age of violence resulting in large numbers of civilian deaths by both state and non-state actors. Broad questions include: what is terrorism? What are its causes? What are its consequences? Do terrorists operate from internally consistent and intelligible (even if horrific) frameworks? Must we sacrifice some of our cherished civil liberties in order to protect others? And what international, moral, and legal principles should guide us in an age of cyber warfare, drone strikes, and targeted assassinations?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15139,2027,2623,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-257','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? When and how to movements spread and diffusion their ideas globally? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention in various moments of time, while developing the conceptual skills that provide an introduction to social movement theory. In doing so, we will take an in-depth empirical look at movements for civil rights, women’s rights, LGBT (lesbian, gay, bisexual and transgender) rights, and immigrant rights. An analysis of these movements across multiple domestic and transnational contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15140,2027,2589,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-258','<div class="desc"> <p>In many countries, the subject of LGBT (lesbian, gay, bisexual and transgender) rights has entered the political discourse with unprecedented speed and suddenness. For an issue that was most often relegated to the private sphere, the rapid global expansion of LGBT rights, as well as changes in public opinion toward LGBT people, has been nothing short of remarkable. This course is designed to gain leverage on the processes that explain such changes by surveying an eclectic literature on comparative and transnational LGBT politics: from social movements to normative change in international relations. For these fields of study, the changes addressed above pose several important questions. It is no coincidence, for example, that dozens of countries now grant some form of same-sex unions, and understanding transnational politics helps us understand why. Specially, we will ask: What factors have facilitated the mobilization of LGBT people? Why and how have public opinion and state laws towards LGBT people changed differently across various countries?</p> <p>To find answers to these questions, we will analyze the political history of a movement that has captured the world’s attention, and one that has moved a marginalized group from the political periphery to the center of public debate and contestation. We will take an in-depth empirical look at movements representing LGBT people and their successes/losses—as well as those of their opposition—across time and place. The first portion of the course will begin with the organized movement’s earliest roots in early 1900s Europe, followed by suppression during WWII, and then the homophile movement of the post-war period. The remainder of the course explores the public manifestation of LGBT identities that grew out of the Stonewall’s gay liberation politics, mobilization around the HIV crisis, and the domestic and international politics surrounding the spread of LGBT rights and recognition in contemporary times. An analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts offered by social movements and international relations scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15141,2027,4183,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-259','<div class="desc"> <p>This course will explore the theoretical political and economic origins of post-modernity and the global identities within it. Such identities will include conceptualizations of the post-modern world and the dilemmas pertaining to the construction of the self within it. We will examine liberalism, Marxism, and various manifestations of religion (in its radicalized and non-radicalized forms).</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15142,2027,551,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-260','<div class="desc"> <p>Research, discussion, and analysis of important issues in International Relations in preparation for a three-day college conference in early April. Student delegates role play as ambassadors for countries and present views negotiating with other representatives and arguing for possible resolutions in a simulation of the United Nations. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15143,2027,3312,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-270','<div class="desc"> <p>Effectively tackling global challenges such as climate change, pandemics, nuclear proliferation, and the decline of democracy and trade liberalization, to name just a few examples, is not reducible to the interests and preferences of the United States. Indeed, most outcomes in global politics never are and have never been. Other countries have interests and preferences of their own, and those influence international outcomes as well. Why, for instance, does it make sense for North Korea to have a nuclear arsenal despite US interests to the contrary? And for China to try to become a hegemonic power in East Asia despite the US decades long presence in the region? Why is Putin''s Russia pushing so hard against NATO’s eastward expansion? And Latin America against U.S. influence in the Western Hemisphere? International affairs look fundamentally different when assessed from a non U.S.-centered perspective. And, history shows, U.S. interests are best served when they, at the very least, take into consideration other actors'' interests and preferences and where these may come from. This course will provide students with the analytical tools necessary to start unpacking any country''s interests and foreign policies, as a first step towards recognizing that satisfactory answers to current and future global challenges require the active acknowledgment of all actors'' preferences with stakes on the matter, no matter how "powerful" the United States might be.</p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15144,2027,829,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-280','<div class="desc"> <p>This course explores the various facets of the globalization process and the politics of development. The first part of the course examines globalization, its causes and wide-ranging consequences, and its implications for U.S. domestic and foreign policy as well as for global governance. Has globalization benefited East Asia, Africa, and Latin America? What have been the differing impacts on those regions? Questions that will be addressed include: what are<br/> conceptual perspectives on globalization? What are the economic, cultural, and political dimensions of globalization? What are policy responses to the challenges globalization presents? The second part of the course examines the politics of various approaches to development and poverty reduction. This will include exploring how globalization is related to development, understanding current debates over foreign aid, and evaluating new and innovative strategies aimed at poverty alleviation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15145,2027,830,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-282','<div class="desc"> <p>A critical examination of greater Los Angeles and its economic, political, social, and cultural ties to the world economy and other countries--all the ways in which Los Angeles is an integral part of the post-Cold War global society. How does this globalization affect the life of Los Angeles and in what ways does Los Angeles contribute to globalization? What are the positive and negative impacts and the implications for United States foreign, economic, and social policies of Los Angeles as a Global City?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15146,2027,1215,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-283','<div class="desc"> <p>This course will study how the concept of soft power - first developed by Harvard professor Joe Nye - applies to interactions among nations in the 21st century. Soft power lies in the ability to attract and persuade, whereas hard power - the ability to coerce - grows out of a country''s military or economic might, especially in an imperial/colonial period. Students will analyze how trade, culture (music, food, sports, language, education), environment, and political institutions (democracy, corruption, human rights, etc.) contribute to a country''s soft power and make up its global brand. Students will analyze the current state of soft power in key nations and consider how countries and their citizens can affect the attractiveness of a country''s culture, ideas, and institutions in order to raise its soft power. The course will introduce students to the idea of global sustainable diplomacy, which pursues global goals using soft, not hard, power.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15147,2027,1066,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-284','<div class="desc"> <p>A critical examination of the political and economic role that sports play in the globalized world - the diplomatic, political, and economic effects of the Olympics, the World Cup, other international sporting events, and the increased globalization of professional sports leagues across national boundaries. A look at case studies of ping-pong diplomacy, rugby reconciliation in South Africa, and soccer wars in Latin America, as well as an analysis of the impact of foreign players on national economies and societies, from American baseball players in Japan, to Russian ice hockey players in the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15148,2027,1330,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-285','<div class="desc"> <p>This course aims to introduce students to both analytic and normative approaches to the study and practice of diplomacy in international politics. In the first part of the course, we will chart the evolution of diplomacy from a tool of statecraft in the modern states system, to a practice of mediating disputes and estrangement in international society. The second part of the course is devoted to examining a series of historical case studies illustrative of the successes and failures of modern diplomacy. The last part of the course considers the utility and limitations of contemporary diplomatic practices for major international trends and developments, such as: globalization, militarism, financial crises, extremism, and environmental degradation. This course is, above all, designed to help students think, talk, and write in an informed and critical manner about complex and seemingly intractable global issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15149,2027,1514,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-286','<div class="desc"> <p>This course will look at the use of public diplomacy in the United States since the end of the 19th century. The concentration will be on U.S. public diplomacy towards Latin America and the Caribbean, Latin America-China relations, and Latin America''s relations with the rest of the world.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15150,2027,1696,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-288','<div class="desc"> <p>This course analyzes how energy systems and climate policy shape power and inequality in world politics. We examine the political economy of the energy transition, e.g. fossil-fuel incumbency, clean-energy industrial policy, critical-mineral supply chains, grids and storage, and climate finance. Students evaluate the roles of states, firms, international organizations, and social movements; assess policy tools (regulation, taxation, emissions trading, standards, procurement, industrial strategy); and examine the implications of mitigation and adaptation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15151,2027,1515,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-290','<div class="desc"> <p>This class looks at global issues - including energy development, climate change, satellite imaging, and forms of communication - that have technical aspects. We then take these topics and place them in the cultural, political, and economic international context: how are states, non-state actors, international organizations, and non-governmental organization handling these issues?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15152,2027,4414,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-293','<div class="desc"> <p><span style="font-style: normal; font-variant-caps: normal; letter-spacing: normal; text-indent: 0; text-transform: none; white-space: normal; word-spacing: 0; text-decoration: none; caret-color: rgb(40, 43, 44); color: rgba(40, 43, 44, 1)">Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15153,2027,127,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-295','<div class="desc"> <p>Topics vary semester to semester.</p> <p><strong>A World Without War</strong></p> <p>The seminar will begin by examining various theories and explanations for the reasons of war. Are wars inevitable? What are the basic differences between wars in pre-modern and in modern times? Are rising powers or rivals destined to clash at some point, with devastating consequences for both sides and beyond? How can one minimize the chances that wars “break out”? Can diplomacy help to prevent wars? What is the role of mediators or supra-national organizations? What characterizes good, effective peace negotiations? In order to answer these questions or at least shed significant light on them, we will look at some major junctions in world history and study the concepts which have been developed to secure peace.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15154,2027,4184,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15155,2027,4185,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-298','<div class="desc"> <p>This course provides students with the basic tools to understand and produce research in the relevant subfields of DWA. The general objectives of the course are to make you more critical readers and thinkers and better writers and researchers. The course is designed to help you with your other DWA classes at Oxy, which require you to read and analyze large amounts of both primary and secondary material and write research papers. The course will also introduce students to basic elements of research design and methodology. By the end of the course, every student should be able to produce a well-designed and well-written research paper which will advance your junior seminar or senior comprehensive paper. </p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15156,2027,831,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/200/dwa-299','<div class="desc"> <p>The goal of this course is to provide students with some of the tools to embark on systematic inquiry in Political Science. It will introduce students to qualitative methods in Political Science; ethical issues in qualitative research, proposal writing, and interviewing techniques; and finally, the essential components of a research paper (a proper research question, thesis, literature review, and case selection). Guidance through the Institutional Review Board process will be provided. This course is geared towards students preparing grant applications, preparing to conduct research abroad, and/or preparing for their Senior Comprehensive thesis since they will be expected to apply the methods they learn to their own research topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15157,2027,1516,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/copy-of-dwa-351','<div class="desc"> <div><p>This junior seminar will focus on advanced scholarship on global sustainability and sustainable development, exploring the evolving challenges and opportunities in these fields. Central to the course are themes of energy transition and the geopolitical competition surrounding it, as countries navigate the shift to renewable energy sources. In addition to these dynamics, students will engage with broader issues of international cooperation on sustainability, examining the political, economic, and environmental implications. The course will provide students with a comprehensive understanding of the genesis, characteristics, and consequences of global sustainability efforts. It also emphasizes research and writing in International Relations, preparing students for their Senior Comprehensives. Open only to DWA majors with junior or senior standing. </p></div> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15158,2027,1010,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-310','<div class="desc"> <p>As of late, religion has re-emerged on the political stage, offering different perspectives regarding political norms, values, and behavior. In this course, we will explore the various ways in which religion has been conceptualized and utilized in different political and cultural settings. Some of the questions that we will seek to answer are: in what ways can religion be separated from politics? What are the roles of religion and religious institutions in political life? How do religions and religious institutions respond to the challenges of a pluralist and secular modern world? Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15159,2027,2931,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-320','<div class="desc"> <p>When and why do people mobilize to make demands against their states and societies? What contextual conditions enable such mobilization, and under what conditions does mobilization decline? Finally, do movements actually matter for bringing about change? This course is designed to gain leverage on these questions by surveying an eclectic literature (from various disciplines) on social movements. The goal of the course is to better understand a series of movements that have captured the world’s attention across various moments in time, while developing the conceptual skills that provide an introduction to social movement theory in international relations. A comparative and transnational analysis of these movements across multiple domestic contexts should give us an angle with which to critically assess the theoretical concepts we will engage. We will touch on a broad array of movements in our weekly current events seminars, and you are welcome to explore other movements that you find interesting in your written work. </p> <p>This course is also intended to improve your writing and research design skills. In academic scholarship, engaging an interesting topic—in our case, social movements—combined with a tool kit of well-developed methodological and writing skills is essential for articulating ideas to a wider audience. Most social science disciplines necessitate the ability to present evidence pertaining to an issue, engage with counter evidence, and ultimately present a convincing argument for a particular position on that issue. Under the rubric of writing broadly for multiple academic disciplines and popular audiences, we will engage several stages of the writing process, which include: (1) note taking and careful analysis of relevant texts; (2) proper use of secondary and primary sources, as well as citation style; (3) drafting texts; (4) revising and peer review (both in class and individually with the instructor); and (5) presenting a polished final research design paper that uses effective grammar, punctuation, and style. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15160,2027,1067,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-329','<div class="desc"> <p>Trafficking in persons - the use of force, coercion, fraud, or deception for purposes of exploitation - is the third most profitable form of illicit activity, globally, following the traffic in drugs and arms. In this course, we will explore the different forms of trafficking, including domestic servitude, sweatshop labor, migrant agricultural work, and child soldiering, although the course will focus most closely on the topic of trafficking for purposes of sexual exploitation. Throughout the class, the causes, consequences, and responses to trafficking will be analyzed through a human rights lens. We will study the processes behind the construction of gender identities in order to gain insight into why particular populations are especially vulnerable to trafficking, and why certain constraints exist to prevent and respond to trafficking at both the domestic and international levels. We will study the relationship between trafficking and militarism, including the legacy of the United States'' military presence in Asia for sex tourism, and trafficking in the region today. And we will engage the debate over whether trafficking is a "discourse" that perpetuates relationships of dominance and subordination between the global North and South. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15161,2027,1697,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-332','<div class="desc"> <p>A digital exploration using mapping techniques to study the movement and political engagement of over 1.3 million Indians who were indentured from India to various British colonies between 1833 and 1920. They currently constitute either large majorities or strong minorities in these former colonies. Some of the countries that will be studied include Fiji, Trinidad, Mauritius, and South Africa.</p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15162,2027,1446,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-335','<div class="desc"> <p>African theorists have historically integrated theoretical critiques with revolutionary practices. This class will focus on theories pertaining to opposition to colonialism in Africa, as well as in the Caribbean and the United States. Theorists such as Franz Fanon, Steve Biko, Kwame Nkrumah, Eric Williams, and Marcus Garvey will be studied. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15163,2027,919,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-337','<div class="desc"> <p>The purpose of this course is to explore international relations theory in depth. Students will be asked to engage with the canonical writings on IR theory and their critics. They will evaluate and reflect on how different theoretical perspectives can explain, critique, and even guide the actions of individuals, institutions, and states in the international arena. The ultimate objective is to understand how the assumptions and priorities of different theoretical traditions have real-world implications for diplomacy and foreign policy-making. <strong>The course will be run as a seminar, so extensive writing, reading, and participation from students are expected</strong>. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15164,2027,129,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-340','<div class="desc"> <p>International law has taken an increasingly central, and often controversial, place in contemporary international relations. This junior writing seminar will explore the foundations of international law, human rights law, and humanitarian law. It will do so in the context of their intersections with topical issues that range from international criminal law, torture, non-state transnational actors, humanitarian interventions, and sexuality, and will have a particular focus on the theoretical foundations for human rights. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15165,2027,552,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-342','<div class="desc"> <p>This class will explore the various aspects of transnational identities, focusing on ways in which they challenge state borders and state nationalisms. The various aspects of transnational identities, like questions of citizenship, ethnicity, religion, gender, and generation will be analyzed. Special attention will be given to the ways in which Islamic beliefs have transcended state boundaries and the impact this has had on notions of citizenship. The class will also focus on a few case studies to highlight the various aspects of transnational identity. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15166,2027,2434,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-344','<div class="desc"> <p>Post-conflict reconstruction in the wake of war and state-building have been prominent activities in international security. The international community now addresses non-state conflict with vigorous programs of state-building. Former President George W. Bush writes in his biography “Afghanistan was the ultimate nation-building mission.” The prevailing post-conflict reconstruction paradigm emphasizes building indigenous capacity – security, governance, judicial, social and economic – so that peace can be sustained without outside intervention. The agents of transition from war to peace are varied in type: internal and external; military and civilian; governmental, intergovernmental, non-governmental and private sector. Military personnel, for example, have long performed many services in the chaos of war and its aftermath: providing emergency medical treatment, food and shelter for dislocated civilians; patching infrastructure, running town meetings, building schools, patrolling streets and training security forces. Aid workers braved great danger to relieve human suffering. A broad array of peace builders today attempts ambitious agendas for human security, effective participatory governance, economic liberalization, and rule of law. The common goal of these activities is to build a basis for political and economic development. Open only to DWA and Politics majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15167,2027,2739,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-345','<div class="desc"> <p>This course will examine the transformation of states, nations, and identity in the contemporary period. Special focus will be given to how transnational developments (in politics, economics, and culture) are redefining modern societies, particularly as the number of democracies has increased worldwide over the last thirty years. The course will also grapple with the challenges and dilemmas of current states. Democratization does not mean democracies are here to stay—as such the course will discuss de-democratization, democratic backsliding, illiberalism, and populism to understand how everyday individuals are affected. In doing so, the class reflects on the experiences of formerly marginalized populations—including women, poor, and the indigenous—by considering the role of states and international organizations in the lives of everyday individuals. Only open to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15168,2027,4186,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-352','<div class="desc"> <p>Water is necessary for human survival and public health, economic prosperity, and environmental sustainability. Water is a spiritual value, a human right, an economic good, and a natural resource. One billion people on our planet do not have access to the water they need. Escalating human population growth, concomitant climate change, and other environmental changes, poor management and emerging/(re-)emerging diseases are compromising the availability and quality of water resources even for those who have access. Political controversies over water, of various kinds, are mounting; some argue future wars will be fought over water. This course examines current issues, conflicts, and prospects, with respect to water resources globally, and how this issue will influence the health of humans, societies, and the planet.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15169,2027,4187,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-353','<div class="desc"> <p>The course will investigate authoritarian regimes from a comparative perspective. We will first examine the conceptual foundations of the study of authoritarianism and democracy to establish how autocracies differ from democracies and among themselves. We will then examine a variety of topics in the study of comparative authoritarianism, including origins and durability of authoritarian rule, authoritarian institutions, and the varieties of resistance to autocratic rule. In addition, we will examine several aspects of the political economy of authoritarianism, such as corruption, redistribution, and the dynamics of integration into the global economy. The course will introduce students to scholarly debates concerning authoritarian regimes, and it will offer them a comparative view of contemporary global politics of authoritarianism. Only open to junior DWA majors.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15170,2027,2881,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-355','<div class="desc"> <p>Economic and social rights include the right to an adequate standard of living, the rights to food, water, housing, and education, as well as the right to work and for basic income guarantees for those unable to work. The course examines the legal and philosophical foundations of economic and social rights, as well as challenges to the legality and legitimacy of these rights. We will examine the status of economic and social rights in the global human rights regime, and we will explore provisions for economic rights at the national level. We will discuss the connection between socio-economic rights and poverty, development, and globalization. Students will explore issues of measurement and policy implementation through a range of case studies and cross-regional comparisons. Open only to DWA majors with junior or senior standing.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15171,2027,3359,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-360','<div class="desc"> <p>This course provides an overview of existing scholarship on international development with a focus on two sets of actors: policy-makers and the targets of development policies. It familiarizes students with the traditional theories of development and more recent critiques emerging from scholars of the global south. It also provides a historical contextualization of what precipitated trends in the development world, leading from theories to implementable policies. It addresses the many challenges that the global community faces in its efforts to reduce poverty in an equitable and sustainable manner. Finally, it promotes a multifaceted understanding of development that moves beyond economic poverty to focusing on health and education outcomes while also understanding how existing inequities can obstruct the efficient implementation of development policies. </p> </div>','Only Junior and Senior students may enroll in this class. Only Diplomacy and World Affairs majors may enroll in this class. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15172,2027,4188,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15173,2027,553,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/300/dwa-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15174,2027,1118,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-401','<div class="desc"> <p>The topic of this course will change from year to year at the discretion of the Director of the Oxy at the UN Program. Topics may coincide with the annual theme of the United Nations. Instructor permission required.</p> <p>This course is part of the Oxy-at-the-UN program.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15175,2027,1119,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-402','<div class="desc"> <p>The importance of conflict prevention and conflict resolution policies has long been recognized at the United Nations. The debate was originally focused on the effectiveness of peace-keeping operations and traditional diplomatic measures. Its parameters have been broadened considerably and now encompass longer term efforts to assist developing countries in enhancing durable structures conducive to peace and democratic stability and the targeted use of development cooperation. Combining theoretical/conceptual and practical concerns, and drawing from case studies of recent conflicts, the ultimate objective of the course is to identify feasible short-term and long-term conflict prevention strategies and tools and to develop practical suggestions to move from a culture of reaction to a culture of prevention. More specifically, the course will deal with: (1) the evolving meaning of prevention as it was understood in the Charter of the United Nations and subsequently shaped by the changing causes and nature of conflicts; (2) the main actors in conflict prevention against the backdrop of UN institutions; (3) the tools and practice of "operational" prevention (i.e. early warning, mediation, sanctions, peace operations, peace enforcement, and the role of regional organizations); (4) the tools and practice of "structural" prevention (good governance and democracy, mainstreaming human rights and gender, meeting post conflict reconstruction, and addressing the root causes of conflict); and (5) the significance of the emerging norm of the "responsibility to protect". Instructor permission required.</p> <p>This course is part of the Oxy-at-the-UN program.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15176,2027,1120,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-403','<div class="desc"> <p>This course will provide students with practical hands-on experience through an internship with a UN agency or a member state mission. This will be a professional undertaking, requiring intensive engagement with high-level responsibilities. The internship will be complemented throughout the semester, with the following three elements: (1) a bi-weekly seminar to fully process the learning and practical experiences of the internships; (2) a guest speaker series for dialogue with UN leaders; and (3) a bi-weekly analytic notebook that will provide an opportunity for students to critically analyze internship experiences, guest lectures, and assigned reading materials. Instructor permission required.</p> <p>This course is part of the Oxy-at-the-UN Program.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15177,2027,1012,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-410','<div class="desc"> <p>The abilities to locate, compile, synthesize, evaluate, and compellingly present complex and up-to-date knowledge on rapidly changing global issues - and to do so in a team - are highly valued across public, private, and civil society sectors. Task Force courses help students learn and practice how to research, write, and present an extended policy/practice oriented report for a real-world client on an urgent topic in global/local affairs. This gives intense practice on independent team research with significant real-world impacts. Each semester''s research focus and client will vary, so this class can be repeated for credit. You can learn more about past Task Forces here: https://www.oxy.edu/academics/global-engagement/young-initiative/research-partnerships-task-forces.</p> </div>','DWA 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15178,2027,4189,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-420','<div class="desc"> <p>This course will address enduring challenges in global politics in the political, economic, and social spheres. These challenges will be contextualized through three prisms: (1) evolving norms of international society and justice, (2) histories of peoples and states, (3) key intellectual works that have both been informed by and helped construct collective understandings of these norms and histories. The challenges of war, nationalism/ethnic conflict, economic underdevelopment, and international justice will be addressed through seminal texts, both classic and contemporary. In order to expand the scope of traditional international relations inquiry, these texts will extend into related intellectual traditions.</p> </div>','DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15179,2027,554,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-490','<div class="desc"> <div><p>Preparation, research, writing, and discussion of senior thesis projects in fulfillment of the Senior Comprehensive requirement. Students with December graduation dates who cannot take this course when offered during the Spring semester should contact the department chair for guidance about how to fulfill the Senior Comprehensive requirement.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15180,2027,3877,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-493','<div class="desc"> <p>Directed research project for DWA majors only. The course is a substitute for DWA 490 for students with December graduation dates. Permission of instructor and department chair required.</p> </div>','DWA 101 , DWA 102 , a DWA 300-level junior writing seminar must have been completed or is in progress. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15181,2027,4190,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/dwa-diplomacy-and-world-affairs/400/dwa-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15182,2027,131,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/100/econ-101','<div class="desc"> <p>An introduction to the economic way of thinking that includes both micro- and macroeconomic topics. We begin with an analysis of how market supply and demand help allocate resources and discuss market power, market failures, and the role of government regulation. We explore the determination of gross domestic product, the problems of unemployment and inflation, and macroeconomic policy making.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15183,2027,132,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/100/econ-102','<div class="desc"> <p>A continuation of ECON 101 that completes the coverage of economic principles by incorporating the development of more sophisticated analytical tools. Microeconomic topics include: production costs, the behavior of firms under different market structures (competition, monopoly, and oligopoly), taxation and income distribution, and input markets. Macroeconomic topics include: the Keynesian model of output determination, the monetary system, and the effects of fiscal and monetary policies.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15184,2027,4191,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/100/econ-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15185,2027,555,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/100/econ-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15186,2027,3551,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/copy-of-econ-293','<div class="desc"> <p>Students will work on a faculty-directed research project. Responsibilities may include data collection and cleaning, coding and statistical analysis, hypothesis formulation and testing, writing and literature review, and conceptualization of future research. Graded on a Credit/No Credit basis only. Prerequisites: Econ 102 (may be taken concurrently) and permission of instructor. May be repeated for credit.</p> </div>','Econ 101 and permission of instructor Econ 102 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15187,2027,2895,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-201','<div class="desc"> <p>This class will introduce students to a variety of frameworks for understanding, measuring, and assessing sustainability. Students will have the opportunity to work on hands-on projects using case studies and/or data. Occidental College will be our laboratory and students may also work with community partners or local firms. Topics vary by semester and could include: waste management, sustainable building, carbon budget, circular economy, corporate social responsibility, ESG, and more. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15188,2027,4192,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-215','<div class="desc"> <p>In this community-based learning course, students will be introduced to educational, economic, environmental, and public health perspectives related to urban green schoolyard design and implementation. The course includes off-campus visits to school sites and presentations by experts in landscape design, water conservation, and public education. Throughout the semester, students will learn how to use social science and life science research tools to evaluate the impact of green schoolyards. The semester will culminate in a green schoolyard project with community partners in the Northeast Los Angeles neighborhood. The course will include two 1.5-hour lecture meetings and one two-hour seminar meeting each week.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15189,2027,3932,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-216','<div class="desc"> <p><strong>Art &amp; Money</strong></p> <p>Art’s relationship to money has long been fraught. On the one hand, art supposedly places individual expression above the profit motive, yet on the other hand, artworks circulate as expensive luxury commodities. How can artworks be unique, non-fungible cultural objects yet also vehicles for collateralized debt, money laundering, tax evasion, speculative investment, and real estate development? Has art simply become money? Can money be art? This course examines these, and other contradictions, about the long and complicated entanglement of art and money in modernity with particular attention on the period since the 1960s. We will address theories of value, trace the history of the art market, interrogate the politics of arts funding, explore the so-called financialization of art, look at ways artists have represented, exploited, or challenged the connections between art and money, and consider art’s role within the broader economic system. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15190,2027,133,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-233','<div class="desc"> <p>Accounting principles and practices. Recording financial data assets, liabilities, owner equity income, and expenses; preparing and analyzing financial statements. Permission of instructor required for first year student enrollment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15191,2027,134,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-250','<div class="desc"> <p>Foundations of microeconomic theory. Topics include: the analysis of consumer theory and decision making; the theory of the firm under perfect competition, general equilibrium, and market inefficiency arising from monopolistic/oligopolistic/strategic behavior; incomplete information; externalities; and public goods. Should be completed before the end of the sophomore year. May be taken before or after ECON 251. Should not be taken in the same semester as ECON 251.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15192,2027,135,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-251','<div class="desc"> <p>A study of the factors that influence and are involved with the national economy. Aggregate analysis as applied to problems of national income, accounting and determination, inflation, unemployment, modern economic growth, and the influence of the money supply. May be taken before or after ECON 250. Should not be taken in the same semester as ECON 250.</p> </div>','ECON 102 and Calculus 1 or higher ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15193,2027,136,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-272','<div class="desc"> <p>The use of regression and correlation to test economic hypotheses. Emphasis will be on the use and interpretation of single equation regression techniques rather than on their derivation. Familiarity with computers required.</p> </div>','Economics 102; Calculus 1 ; one additional Economics course above Economics 102; and introductory statistics. Introductory statistics prerequisite can be met with any of: CS 146, Math 150, PSYC 201, BIO 268, an AP Stats score of 4 or 5, an IB exam score of 6 or 7, or an equivalent course (with instructor permission). ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15194,2027,4193,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-295','<div class="desc"> <p>Topics vary semester to semester.</p><p><br/></p><p>Modeling Business Decisions</p><p><br/></p><p>Managers usually find spreadsheets natural, intuitive and user-friendly platforms for organizing information and performing âwhat ifâ analyses. Spreadsheets have therefore become indispensable tools of modern business analysis. This course will focus on structuring, analyzing, and solving managerial decision problems on Excel spreadsheets. We will address problems of resource allocation (how to utilize available resources optimally), risk analysis (how to incorporate uncertainty in problem parameters), decision analysis (how to synthesize a sequence of decisions involving uncertainty), data analysis (how to summarize available data into useful information), and forecasting (how to extrapolate past data into the future). In each area, we will consider specific managerial decision problems, model them on Excel spreadsheets, analyze and solve the models using available Excel commands, functions, tools, and add-ins, and study economic interpretations of the solutions obtained.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15195,2027,556,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/200/econ-297','<div class="desc"> <p>Application of modern research methods to current problems in Economics and related fields. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15196,2027,2827,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/copy-of-econ-322','<div class="desc"> <p>Are goals of economic development and sustainability at odds with one another? What kinds of policy instruments could help us effectively reduce emissions, and why is international cooperation so difficult to achieve? This course offers a critical examination of sustainable development from the economics perspective. Beginning with conflicting views of sustainable development, the course proceeds to study how economists approach challenges such as climate change, management of common property resources, growth and poverty, measurement of well-being, and global health.</p> </div>','ECON 250 , or ECON 102 and MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15197,2027,140,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/copy-of-econ-350','<div class="desc"> <div><p>This course covers the application of economic theory and analytical tools to business and management decision making. Topics to be covered will include examples from a variety of fields, including: pricing, ethics, entrepreneurial startups, strategy, new products, acquisitions, marketing, human resources, and leadership. </p></div> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15198,2027,1166,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/copy-of-econ-351','<div class="desc"> <div><div><p>This course examines the interaction between monetary policy and financial markets. Key topics include business cycles, stock and bond markets, and banking panics. Students will learn how to analyze the financial market implications of Federal Reserve policy. The course incorporates insights from economic history to understand the monetary policy challenges facing the U.S. macroeconomy today.</p></div></div> </div>','ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15199,2027,557,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-301','<div class="desc"> <p>The purpose of this course is to illustrate the role that economics can play in creating and improving environmental policy. We will apply the theories of economic efficiency, cost-benefit analysis, market failure, and property rights to environmental policy and regulation. We will cover the principles of market-based environmental policies and their applications in the world today. We will touch on all aspects of the economy''s interaction with the environment, including air and water pollution, global warming, environmental health, non-market valuation, and resource extraction.</p> </div>','ECON 101 or ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15200,2027,1447,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-302','<div class="desc"> <p>This course introduces the field of industrial organization, which studies how firms make strategic decisions. We will analyze a wide range of issues such as market entry, product positioning, market leadership, and mergers and acquisitions. We will also examine the role of competition law. Our approach blends two alternative but complementary methodologies: theoretical modeling of strategic firm behavior and industry equilibrium, and the factual detail found in case studies of specific industries.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15201,2027,137,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-303','<div class="desc"> <p>This course explores the economics of the internet, which is the study of the online behavior of firms and consumers. We will analyze competition and firm strategies in internet marketplaces. Topics will include online platforms, internet auctions, copyright and innovation, advertising, and consumer search. Our approach will combine theoretical modeling and statistical tools with factual detail from the case studies of firms and industries.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15202,2027,1165,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-304','<div class="desc"> <p>This course uses an economic perspective to examine how human decisions affect natural resources and how natural resources affect humans. We will apply economic principles to questions of use and sustainable management of renewable and nonrenewable natural resources. Our discussion will center around scarcity, property rights, market failure, economic efficiency, resource allocation over time, sustainability, and public actions that could be taken to influence the rates at which natural resources are used. The course will cover the main resource issues including minerals, energy, forest management, marine resources, water resources, land management, wildlife, and biodiversity, showing how underlying economic principles provide the basis for specific natural resource policies.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15203,2027,921,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-305','<div class="desc"> <p>This course is an introduction to the study of strategic interaction using the tools of game theory. The focus of the course is on developing a set of analytical techniques with the goal of understanding and using game theoretical models in economics. The first part of the course introduces the basic framework and tools of game theory. The second part of the course covers a number of economic (and some non-economic) applications of game theory; specific topics may include: auctions, bargaining, voting, and market competition.</p> </div>','ECON 250 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15204,2027,2676,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-306','<div class="desc"> <p>This course builds on ECON 272 to cover advanced topics in econometrics including: panel data, binary response models and causal inference. Theoretical models of regression and empirical coding will both be emphasized. </p> </div>','ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15205,2027,2439,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-307','<div class="desc"> <p>Using, interpreting, and understanding data is increasingly important for understanding the magnitude, determinants, and solutions to social issues. This course provides an introduction to economic data analysis, discussing how economists quantify key concepts, test theories using empirical data, and evaluate policy effectiveness. Students will learn basic statistical methods and data analysis techniques, including how to clean, visualize, and analyze data using statistical programming packages. The course will also present an intuition-based introduction to regressions and causal inference. We will develop these skills discussing data and models from a range of topics, including poverty and inequality, macroeconomic growth, health, and education.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15206,2027,558,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-308','<div class="desc"> <p>This course studies the government''s role in a market economy, particularly policies that work through government spending and taxation. There are two primary motivations for government intervention: to correct a market failure or to mitigate poverty and inequality through redistribution. The course is organized around these two rationales, with attention to topics that include climate change, public education, health insurance, Social Security, welfare policy, and the taxation of goods, labor, and capital. We study how such government policies impact behavior and, as a consequence, how they should be designed to maximize welfare. This course also introduces students to the modern methodological approach in public economics that tightly connects economic theory with credible empirical evidence to generate policy insights.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15207,2027,832,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-309','<div class="desc"> <p><strong></strong></p> <p> The Austrian School of Economics, so-named because of the national origin of its founders, is an alternative approach to Economics that emphasizes methodological individualism and subjectivism. The Austrian School of Economics traces its roots back to the works of the Spanish Scholastics of the 16th century and stresses the importance of the individual, private property, limited government, and the organizing power of the free-market. Students will read from authors such as Menger, Mises, Hayek, Kirzner, Rothbard, and Hoppe, and evaluate various properties of a state-planned economy versus a decentralized free market economy.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15208,2027,138,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-311','<div class="desc"> <p>Economic activity in a global context. The first part of the course covers the causes and consequences of international trade, with a consideration of both national welfare and income distribution issues. Coverage then turns to trade policy in theory and practice, with a focus on the current global trading environment under the World Trade Organization. The course finishes by examining international investment and debt issues, including the role played by the International Monetary Fund during global financial crises. May not be taken for credit by students who have taken DWA 220/POL 232.</p> </div>','ECON 102 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15209,2027,922,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-312','<div class="desc"> <p>Germany has emerged as a leader in sustainability and innovation. With the Federal Elections in 2021, would an increasingly popular Green Party help accelerate sustainable development in Germany? In this course, we study the political economy of Germany and how various political and economic forces shape sustainable development in Germany. The course begins with a module on the history, politics, and economy of Germany. We study the key events and institutions that helped shape Germany to become a leader in sustainability, though not without challenges. Concepts and theories in political economy will be introduced, alongside a review of key economic concepts. The course then proceeds to an environment-focused module and applies political economy frameworks to understand environmental issues confronting Germany. This bridges into case studies focused on several cities that have led sustainability debates. We then shift the focus to economic and social sustainability topics, including digital and innovation economy, east-west inequalities, migration, identity and integration, and nationalism. The course meets first as an on-campus seminar to introduce the political and economic structures as well as the major environmental and sustainability debates in Germany. We then spend three weeks traveling across Germany to learn on the field, including a visit to the German Parliament (Bundestag). This is a Faculty-led Course Abroad and the three-week field study in Germany is required. Application is required. </p> </div>','ECON 102 and instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15210,2027,1069,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-314','<div class="desc"> <p>This course examines the historical development and the role of institutions underlying market economies. It discusses the many forms which institutions (i.e. social norms, laws, and regulations) affect economic behavior and performance. Based on examples from United States and European economic history, topics will include: contract enforcement; trading institutions; political institutions; financial institutions; property rights in land and environmental resources; regulation of labor and capital markets; and the origin and development of one of the most important economic institutions, the firm. We will pay particular attention to institutions that emerged in response to market failures and to the changing nature of economic institutions over time.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15211,2027,923,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-315','<div class="desc"> <p>This course will examine the role of finance and financial institutions in the process of economic growth and development. We will start with an overview of the various channels linking finance and economic growth, as well as the role of legal institutions and politics. Subsequently, the course will look at the evolution of finance in specific countries and the factors which might have facilitated (or served as a detriment to) the development of financial institutions. Next, the course will study the ability of various financial institutions to serve as efficient intermediaries and examine barriers to credit access faced by firms and households. The last part of the course will examine responses to financial crises and the aggregate effects of such crises.</p> </div>','ECON 102 and ECON 272 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15212,2027,3933,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-316','<div class="desc"> <div><p>This course examines the role of politics in influencing fiscal policy and assesses the latest empirical research on the effects of fiscal policy. We will use case studies of important episodes from U.S. macroeconomic history as a window for analysis. The course emphasizes current fiscal policy debates facing the U.S. Congress and President today.</p></div> </div>','Econ 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15213,2027,1217,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-319','<div class="desc"> <p>This course examines the application of economics to the law. Studies of actual cases reveal how economics can be applied to address such questions as: (1) whether an action violates the law, (2) who experiences economic harm as a result of that action, and (3) what the legally prescribed consequence is. Specific applications include: property rights related to technical innovation, competition in concentrated industries, and the extent of corporate liability. The primary context is the United States, but other legal systems provide some specific comparisons.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15214,2027,559,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-320','<div class="desc"> <p>Theoretical and empirical analysis of the process of economic development in less developed countries. After examining several theories of growth and development, we will discuss inequality and poverty, the effects of population growth and rural-urban migration, saving and financial markets, international trade, foreign aid and foreign borrowing, agriculture, and the role of the government. Case studies will be drawn from the development experiences of Asian, Latin American, and African economies.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15215,2027,2626,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-321','<div class="desc"> <p>This course provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15216,2027,2932,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-323','<div class="desc"> <p>Cities are great places to live where people gather, interact and generate new ideas. At the same time, this high concentration of people in one place gives rise to problems such as traffic, pollution and crime. In this course, we are going to apply principles of economics to understand how cities came to be and why some cities are bigger than others. We are going to debate whether cities'' high wage premium and nice amenities like parks and malls make up for the high living costs--especially of housing. We will delve into the challenges of providing good public education and transportation in highly dense areas and end by discussing potential reasons and solutions for observed spatial inequality.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15217,2027,1013,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-324','<div class="desc"> <p>This course examines the economic causes and consequences of immigration. The focus of the course will be on the United States'' experience. However, we will also examine aspects of other international migrations. The course will focus on the economic reasons that motivate people to migrate to other parts of the world, the labor market and fiscal impacts of immigration on sending and receiving countries, and the economic consequences of U.S. immigration policy choices.</p> </div>','ECON 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15218,2027,833,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-325','<div class="desc"> <p>The goal of Labor Economics is to enable you to use economic analysis and reasoning to understand wage and employment determination in U.S. labor markets. This course will expose you to current theoretical and empirical debates within the discipline. We will cover such topics as: labor force participation, labor demand, unemployment, labor mobility, wage structure, labor unions, human capital investments (education and training), internal labor markets, and labor market discrimination. Relevant public policy issues such as the minimum wage, living wage ordinances, compensating wage differentials, immigration policy, affirmative action, income inequality, and welfare programs will also be addressed in this course.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15219,2027,924,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-326','<div class="desc"> <p>An application of economic analysis to various topics in personnel economics, including: compensation and incentives, hiring, training, downsizing/buyouts, stock options, pensions, and teams, among many others. In order to add realism to, and applications for, the analysis, students will discuss and evaluate numerous real-world mini-cases and more formal case studies. Students will be evaluated on the quality of their written work, problem sets, examinations, and discussion; a variety of class formats will be used. Note: Students who take this course may not take Professor Moore''s section of ECON 495.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15220,2027,1331,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-327','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women in the United States, this course is designed as an overview of major theories, trends, and debates on the topic of gender in the labor market. We will examine gender differences in economic outcomes through the use of economic models, including feminist extensions and critiques of such models. Topics include: the family as an economic unit; gender differences in education, work, training, and income; and the economics of marriage, divorce, and fertility. Permission of instructor required for students who have successfully completed ECON 328 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15221,2027,139,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-328','<div class="desc"> <p>An examination of the historical and contemporary economic positions of women and minorities. Topics include: the economics of slavery, racial and sexual discrimination, labor market segmentation, wage differentials, labor force participation, red-lining, and income inequality. Relevant public policy issues such as affirmative action and welfare will also be addressed. Permission of instructor required for students who have successfully completed ECON 327 to enroll in this course.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15222,2027,2740,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-329','<div class="desc"> <p>Despite a widespread desire to provide equality of opportunity to all people in the United States, family background has an enormous effect on the way children grow up and the opportunities available to them in adulthood. Family income can explain more than a third of a child’s future adult income, and all aspects of family background can explain half to two thirds of a child’s future income, education, and wealth. In this class, we will explore economic theories and evidence explaining the inheritance of advantage, with a particular emphasis on understanding the role of the family, the role of neighborhoods and communities, and the role of discrimination. We will also discuss the role of public policy in increasing intergenerational mobility and reducing social and economic disadvantages, both in the United States and around the world.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15223,2027,3337,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-330','<div class="desc"> <p>This course uses an economic lens to study educational systems, human capital acquisition, and education policy. It considers the education system at large, ranging from early childhood education, through secondary and post-secondary education. The course develops a theoretical framework for why and how education levels differ across individuals, considering both signaling and productivity margins. It covers the basics of public education financing and examines how the way that education is financed determines educational quality. The course will discuss various public policy topics surrounding education topics which may include include: the value of early childhood education, the importance of quality instruction, peer effects, high-stakes testing, major-choice, and more. The course will build on foundational economic concepts and ask students to connect economic theory and empirical research towards understanding our system of education. </p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15224,2027,1448,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-331','<div class="desc"> <p>An introduction to the history of radical philosophical alternatives to neoclassical and Keynesian Economics. A critique of these mainstream schools is followed by the development of competing radical alternatives with the analytical focus on concepts of economic surplus and social class, exploitation, alienation, and theories of capitalist development crisis and transformation. Ethnographic case studies provide examples of archaic and contemporary alternative economic practices. Special attention is paid to philosophies of human nature, the labor process, problems of racism and sexism, imperialism, current U.S. economic problems, and socialist alternatives.</p> </div>','ECON 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15225,2027,834,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-340','<div class="desc"> <p>This course will provide an introduction to the relatively new field of Behavioral Economics. Standard models of economic theory provide a useful, but not always realistic, way to characterize how individuals make decisions. In this course, we will investigate the evidence showing how people may behave in ways that are not predicted by this standard theory. Individuals may exhibit nonstandard preferences, nonstandard beliefs, or nonstandard decision-making. We will look at each of these in turn, with applications that may include saving, finance, labor supply, gift-giving, voting, and addiction. The methodology of the course will not itself deviate from the standard way of doing economics; we will state clear assumptions, build models, determine their logical conclusions, and think about how to empirically test both the assumptions and implications of such models.</p> </div>','ECON 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15226,2027,1591,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-352','<div class="desc"> <p>Firm-level studies are now at the forefront of international trade research. In this course, we look at firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. We use modern trade theory to analyze firm decision-making; we start with a discussion of the firm''s decision to engage in international commerce and then examine how firms choose between various types of foreign direct investment. Throughout the course, we learn from empirical studies and individual case studies how firms engage in international commerce.</p> </div>','ECON 250 and ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15227,2027,3934,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-353','<div class="desc"> <div><p>This course discusses various empirical aspects of financial economics and financial risk management. Addresses both theoretical and applied issues in finance, risk management, and econometrics. Also discusses quantitative analysis, simulation methods, and case studies.</p></div> </div>','ECON 272 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15228,2027,561,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-395','<div class="desc"> <p>Topics vary semester to semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15229,2027,562,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/300/econ-397','<div class="desc"> <p>Advanced independent research in Economics. For example, Advanced Econometrics can be taken on an independent study basis. Permission of instructor and department chair required.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15230,2027,142,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/400/copy-of-econ-495','<div class="desc"> <div> <p>An intensive application of economic analysis to issues chosen by the instructor in consultation with students during the course. The course emphasizes the development of analytical writing, team-work, and presentation skills, and is meant to be an opportunity for students to apply their economic training to specific topics. Complete descriptions of the seminars offered in a given year will be mailed out to students prior to the Spring registration. Senior status is required for this course. Students who will be off campus in the Fall of their senior year must contact the department chair by the end of their junior year to arrange a substitute senior seminar.</p> <p><strong>Economics of Education</strong></p> <p>This course uses an economic lens to study educational systems, human capital acquisition, and education policy. It considers the education system at large, ranging from early childhood education, through secondary and post-secondary education. The course develops a theoretical framework for why and how education levels differ across individuals, considering both signaling and productivity margins. It covers the basics of public education financing and examines how the way that education is financed determines educational quality. The course will discuss various public policy topics surrounding education topics which may include: the value of early childhood education, the importance of quality instruction, peer effects, high-stakes testing, major-choice, and more. The course will build on foundational economic concepts and ask students to connect economic theory and empirical research towards understanding our system of education. Not open to students who have taken ECON 330.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong>Firm-Level International Trade </strong></p> <p>This seminar studies firm behavior in the international economy and how it is influenced by government regulations and international trade agreements. Topics discussed include the decision to export, foreign direct investment, outsourcing/offshoring, GATT/WTO and various trade agreements. We use modern trade theory to analyze firm decision-making and also learn how firms engage in international commerce from empirical studies and case studies. Not open to students who have taken ECON 352.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250.</p> <p><strong>Industrial Organization</strong></p> <p>This course introduces the field of industrial organization, which studies how firms make strategic decisions. We will analyze a wide range of issues such as market entry, product positioning, market leadership, and mergers and acquisitions. We will also examine the role of competition law. Our approach blends two alternative but complementary methodologies: theoretical modeling of strategic firm behavior and industry equilibrium, and the factual detail found in case studies of specific industries. Not open to students who have taken ECON 302.</p> <p>Prerequisite: ECON 272 (may be taken concurrently) and ECON 250.</p> <p><strong><strong>Monetary Policy and Financial Markets</strong></strong></p> <p>This course examines the interaction between monetary policy and financial markets. Key topics include business cycles, stock and bond markets, and banking panics. Students will learn how to analyze the financial market implications of Federal Reserve policy. The course incorporates insights from economic history to understand the monetary policy challenges facing the U.S. macroeconomy today. Not open to students who have taken ECON 351.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong>Open Economy Macroeconomics</strong></p> <p>The course provides an overview of models, methods, research, and current issues in Open Economy Macroeconomics. Today, an international perspective to study Macroeconomics is perhaps more important than ever before. Countries do not operate in isolation, but events in one country affect people around the world. Why do some countries grow faster than others? What are the effects of monetary and fiscal policy, domestically and abroad? Why do some countries run trade deficits and others trade surpluses? Does it matter? And why do some countries encounter financial crises and what can we do about them? In trying to answer these questions, the first part of the semester will be devoted to asset-based models of exchange rates and price level determination, and the second to open economy models of the short and medium run.</p> <p>Prerequisite: ECON 251 and ECON 272 (may be taken concurrently).</p> <p><strong><strong>Health Economics</strong></strong></p> <p>This seminar provides an overview of health economics, covering the demographic and socio-economic determinants of health and the design and implementation of health care systems in both domestic and global contexts. Students will apply economic theory to model demand for health and health care, cost-effective intervention choices, the value of a statistical life, and optimal health insurance. Using this grounding, students will read state-of-the-art empirical research on recent policies such as the Oregon Medicaid Experiments, the Affordable Care Act, and pay-for-performance programs in developing countries. Not open to students who have taken ECON 321.</p> <p>Prerequisite: ECON 250 and ECON 272 (may be taken concurrently).</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15231,2027,143,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/400/copy-of-econ-498','<div class="desc"> <p>Independent research with one-on-one faculty mentoring. After a brief introduction to economic research methods, students will develop a topic and then write and present a senior thesis. Only open to seniors. Permission of instructor and department chair required.</p> </div>','ECON 250 , ECON 251 , and ECON 272 ; and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15232,2027,4194,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/400/econ-420','<div class="desc"> <p>This seminar provides an intensive application of economic analysis to issues related to global political economy, pairing economic models with real world examples. Students will study state-of-the-art empirical research and develop a sense for how economists conceptualize and test models, conduct research, and make policy recommendations. Topics will vary each semester by instructor. Potential topics include global integration, international trade, governance, international labor markets, and international finance. These will be studied in relation to their effects on transnational issues such as the environment and migration, as well as on political-economic inclusion/exclusion, local economies, and multiple dimensions of human welfare, including poverty, work, health, education, and housing. This course may be repeated once for credit.</p> <p><strong>Working in a Global World: The Economics of Choosing a Career</strong></p> <p>This seminar examines questions related to what jobs Oxy students should pursue. Looking backward, what jobs (either domestic or international) have been best? Which jobs have had small recession risks and which have had large? Which jobs have been growing and which declining? Looking forward: What growth in the US economy can be expected for the next couple of decades compared to the rest of the world? How do the forces of immigration and technological change affect jobs in the US and abroad? How does globalization affect which jobs are more-or-less isolated from foreign competition, and which are constantly at risk of moving abroad? </p> </div>','ECON 250 or by instructor permission ','ECON 272',NULL);
INSERT INTO course_descriptions VALUES(15233,2027,4195,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/econ-economics/400/econ-497','<div class="desc"> <p>Advanced independent research in Economics. Permission of instructor and department chair required.</p> </div>','ECON 250 and ECON 251 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15234,2027,1218,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-101','<div class="desc"> <p>In every major urban center across the United States, children and youth attend public schools managed by highly-bureaucratized administrative entities called ''school districts''. This course provides a historical survey of the evolution of U.S. urban schooling, tracing its development from the earliest community-based, one-room schoolhouses, to modern major urban unified school districts. We explore the roles that industrialization and immigration have played in the urbanization of communities, and the ways in which schools have adapted in order to provide for the socialization of the urban worker. We examine shifts in the politics of public education as it pertains to control over schools and schooling and the various stakeholders involved. We conclude with a look at the evolving roles of the teacher, school counselor, and the administrator - as well as a glimpse into what the future holds for both traditional and alternative forms of public schooling in urban school communities across the U.S.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15235,2027,145,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-140','<div class="desc"> <p>Occidental students work in the Academic Commons one-on-one with children from the community. While incorporating arts and integrating technology, students will engage their child with a variety of Language Arts activities in order to reconnect their child with the joy of reading and writing for pleasure. Students will build on their child''s strengths, skills, and interests by using culturally relevant pedagogy and critical literacy explorations. Students become part of a high-warmth, low-criticism community. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15236,2027,835,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-141','<div class="desc"> <p>Students work one-one with middle school students for extensive explorations in writing. Occidental students will collaborate and coach writing activities which will include narrative, expository, and analytical prompts. This course focuses on authentic, engaging writing and integrates the arts, technology, and critical literacy. Students work closely with the Critical Making Studio. This course is designed to deepen the critical and creative abilities of both groups of students while connecting written explorations to the California Common Core Standards. This course takes place on campus in the Academic Commons. Graded on a Credit/No Credit basis only. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15237,2027,2511,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-142','<div class="desc"> <p>In this course, Occidental students who are Spanish or Mandarin speakers will offer elementary and middle school students, who come on the Oxy campus, Spanish/Mandarin language development and language enrichment activities. Graded on a Credit/No Credit basis. May be repeated once for credit. For further information, email the professor.</p> <p></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15238,2027,3262,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-143','<div class="desc"> <p class="sc-BodyText">This an interdisciplinary course providing an introductory overview of public engagement through the lens of art. Students will learn basic methodologies of public engagement; how to create an inquiry-based lesson plan with an emphasis on creative expression; and how to lead a group of elementary or middle school students, with priority placed on collaboration and art-making. During the first six weeks of the semester, students will research, plan and work with lead teaching artist Patricia Yossen and collaborate in teaching teams to develop lesson plans for an original after school art workshop for local youth. In the following 6 weeks of the semester, Oxy students will collaboratively lead their workshops for local elementary or middle school youth, culminating in a final public presentation at the Oxy Arts gallery. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15239,2027,1014,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-145','<div class="desc"> <p>In this course, students will systematically examine the causes, challenges, and effects of several educational innovations in various school systems, from K-12 to higher education. The course will help students develop historical perspectives of schooling, critically examine the role and purpose of progress and innovation in our educational landscape in the United States, and understand how past, present, and future innovations impact our collective educational processes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15240,2027,4196,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15241,2027,4197,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/100/educ-197','<div class="desc"> <p>Interested students must obtain <em>Guidelines for Independent Study</em> from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15242,2027,146,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-201','<div class="desc"> <p>In this introductory course, students study, as a community of learners, the historical, philosophical, political, sociological, economic, and psychological foundations of U.S. education in the public school. Using a variety of analytical lenses, students will critically engage with key texts to examine factors that influence power, control, and the quality of schooling for urban communities. Throughout the semester, we will focus our analysis on the possibility and potential of achieving "socially-just" relationships in urban school communities through teacher practice, educational leadership, and community-based activism.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15243,2027,147,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-205','<div class="desc"> <p>Analysis of the English language development of listening, speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public-school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction, sheltered/SDAIE approaches, English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15244,2027,148,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-207','<div class="desc"> <p>How are the American values of equity and opportunity evident in the history and structure of the nation''s public-school system? This course examines key U.S. Supreme Court decisions and the following areas of policy debate and conflict, with particular emphasis on the Constitution: bilingual education funding/expenditures, immigrant education, desegregation, special education, affirmative action, and equal resources.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15245,2027,3338,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-211','<div class="desc"> <p>This course prepares students to understand and apply principles of educational equity &amp; diversity to the study of the schooling experiences of Asian American students in K-12 and higher education contexts. With attention to the broader context of anti-Asian racism in the U.S., the course provides theoretical frameworks to ground students’ understandings of the histories, cultures, and ethnic experiences within specific groups, as well as preparing students to engage comparative analyses of Asian American education towards the ultimate goal of critically interrogating the curricular, instructional and assessment practices that have come to shape the schooling of Asian American students in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15246,2027,925,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States: Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students, and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15247,2027,149,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-215','<div class="desc"> <p>This course critically examines the history of the education of Africans in the United States, beginning at the Middle Passage, through Reconstruction and the post-bellum South, to contemporary post-industrial urban contexts. Emphasizing the sociohistorical and political-economic dimensions of schooling African Americans, the course explores the role of key factors in shaping the academic "success" and "failure" of Black students historically and in current K-16 contexts. Analysis of case law policy and practice will inform our understanding of African American experiences in schools nationally and locally. Further, we consider the implications these experiences hold for democratic participation and the overall life chances of African American citizens.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15248,2027,1378,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-217','<div class="desc"> <p>National reform efforts (e.g. Nation at Risk, No Child Left Behind, Race to the Top) have permeated the educational establishment for decades, yet the achievement gap between rich and poor and white and non-white students has shown no appreciable progress. This course will analyze current and past policies in education intended to improve the educational experience of all students and address this achievement gap. Students will receive an understanding of policy formation, the effect of applied research relative to educational policy, and then select a reform policy (e.g. value-added teacher pay, class size, charter schools, etc.) to further investigate as a project field assignment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15249,2027,4198,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-218','<div class="desc"> <p>In this course, the students will understand that unlike traditional perspectives of elementary education that claim to be neutral and apolitical, critical race pedagogy views all education theory as intimately linked to ideologies shaped by power, politics, history, and culture. Given this view, schooling functions as a terrain of ongoing struggle over what will be accepted as legitimate knowledge and culture. In accordance with this notion, critical pedagogy must seriously address the concept of cultural politics, both legitimizing and challenging cultural experiences that comprise the histories and social realities that, in turn, comprise the forms and boundaries that give meaning to student lives. This course specifically addresses youth, elementary age, and related school-based pedagogies that represent status quo content, and assessments and instructional practices that empower students rather than reinforce inequities.This course will provide an option for students to conduct 15 hours of fieldwork to analyze and evaluate the current state of urban education, as well as see transformational models that are possible, learning elementary pedagogical techniques with the participating neighborhood children who are elementary age.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15250,2027,1015,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-219','<div class="desc"> <p>This course will analyze the educational infrastructure PK-16 pipeline to examine the nature of inequality. The following three areas will be examined: (1) theories of educational inequality, (2) research on inequality, and (3) policies of inequality. Students will gain a basic understanding of the theories of educational inequality as they relate to genetic, cultural, school, and societal perspectives, using critical theoretical lenses. Students will also examine the research addressing educational inequality, paying attention to designs, methods, and samples covered. And finally, students will analyze educational policies that either reproduce or eliminate inequalities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15251,2027,2741,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-220','<div class="desc"> <p>The United States has the highest incarceration rate in the world. Schools, despite their role in nurturing the academic growth and development of students, are increasingly becoming sites of criminalization for marginalized children and youth. This raises fundamental questions about the relationship between schools and the carceral state, as well as about the complicity of schools and their officials in the production of prisoners. In this course, students will explore the social, historical and political-economic factors that have contributed to the development, growth and sustenance of the "school-to-prison pipeline." Through an examination of a wide range of texts and sources that sit at the intersection of K-12 schooling, criminal justice, social welfare, and community-based organizing and activism, students will be prepared to critically interrogate educational policies, practices and other structures of schooling that buttress and deconstruct this phenomenon. Sophomore standing required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15252,2027,1449,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-281','<div class="desc"> <p>This class provides students with the ability to develop a conceptual and practical understanding of research and evaluation in Education and the Social Sciences. Course topics include: basic statistics, survey design, data analysis, article critique, and data interpretation. The course will allow students to demonstrate a proficient knowledge of basic statistics (ranging from basic descriptive statistics to inferential statistics), research design, and analysis. Students will advance from being consumers of knowledge to being critical when reading previous literature. Students will be introduced to the following concepts: descriptive statistics (including cross-tabulation); correlation, reliability, and validity; one and two sample statistical tests; ANOVAs; and simple and multiple regression.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15253,2027,4199,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15254,2027,4200,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/200/educ-297','<div class="desc"> <p>Interested students must obtain <em>Guidelines for Independent Study</em> from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15255,2027,150,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/300/educ-300','<div class="desc"> <p>This seminar will provide students with an opportunity to gain field experiences in an educational setting in urban Los Angeles. Students will select either a public school, a community-based organization, or a policy-making group as a site in which to develop a field-based research project. Regular meetings of this seminar will guide students as they spend the semester in a carefully crafted and mutually agreed upon "internship/fieldwork" experience that will culminate in a semester-end project report that addresses an educational issue of import to the fieldwork site. May be repeated once for credit.</p> </div>','EDUC 201 and EDUC 207 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15256,2027,4201,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/300/educ-315','<div class="desc"> <p>In this course, the students will understand that unlike traditional perspectives of education that claim to be neutral and apolitical, critical pedagogy views all education theory as intimately linked to ideologies shaped by power, politics, history, and culture. Given this view, schooling functions as a terrain of ongoing struggle over what will be accepted as legitimate knowledge and culture. In accordance with this notion, critical pedagogy must seriously address the concept of cultural politics, both legitimizing and challenging cultural experiences that comprise the histories and social realities that, in turn, comprise the forms and boundaries that give meaning to student lives. This course will ask students to conduct 15 hours of fieldwork to analyze and evaluate the current state of urban education, as well as see transformational models that are possible.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15257,2027,566,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/300/educ-320','<div class="desc"> <p>Critical Race Theory (CRT) is a historic movement among legal scholars of color in the U.S. that has enjoyed widespread application in a number of disciplines, including Education. This course introduces students to CRT through a close reading of the key writings that formed the movement. We will examine the application of CRT in education, research, theory, and practice, contextualized in a variety of settings, including schools, community-based organizations, and other relevant spaces. Specific attention will be paid to the CRT methodology of counter-storytelling and its utility in centering the experiential knowledge of people of color in education.</p> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15258,2027,1168,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/300/educ-350','<div class="desc"> <div><p>"How can the Oppressed, as divided unauthentic beings, participate in developing the pedagogy of their (own) liberation?" This course focuses on Paulo Freire''s theoretical, pedagogical, and practical contributions to decolonial movements globally, as well as on the formation of critical pedagogy, critical literacy, and the rhetorics of "educating for social justice". Beginning with Franz Fanon''s influences on Freirean thinking about revolution and decolonization, we will closely analyze the construction of the "Pedagogy of the Oppressed". We pay particular attention to the role of the Hegelian dialectic as a driving philosophical method, as well as the significance of Freirean themes in understanding contemporary schooling, education, community activism, and vocation in general. Students will analyze, critique, and reflect upon their own framing philosophies for personal engagement with oppressed peoples and communities - towards the broader goal of defining an individual role in the development of a pedagogy of the oppressed that both negotiates and is informed by students'' multiple identities.</p></div> </div>','Any 200-level EDUC course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15259,2027,4202,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/300/educ-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15260,2027,568,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/300/educ-397','<div class="desc"> <p>Interested students must obtain <em>Guidelines for Independent Study</em> from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15261,2027,3565,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/400/educ-410','<div class="desc"> <p>Participatory Action Research (PAR) is an ‘action research’ methodology in which researchers and community partners collaborate to conduct critical research. PAR projects typically involve (a) the collective investigation of a problem, that (b) relies on indigenous and/or community knowledges to guide/inform that research, towards the end of (c) individual and/or collective action to address that problem. This course introduces students to the research methodology through guided study. Students will understand basic study design, various methods of qualitative data collection &amp; analysis, as well as dissemination.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15262,2027,4203,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/educ-education/400/educ-497','<div class="desc"> <p class="sc-BodyText">Interested students must obtain Guidelines for Independent Study from the department and complete the appropriate contract from the Registrar. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15263,2027,4204,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-100','<div class="desc"> <div><p><span style="font-size: 12pt">âI write entirely to find out what Iâm thinking, what Iâm looking at, what I see and what it means,â Joan Didion writes in âWhy I Write.â James Baldwin suggests in an interview: âWhen youâre writing, youâre trying to find out something which you donât know. The whole language of writing for me is finding out what you donât want to know, what you donât want to find out. But something forces you to anyway.â This course, exclusively for first-year students, aims to help students cultivate their creative writing skills as tools for finding out what they think, for undertaking adventures in self-examination, and for confronting the complexities of language and of the world. Students will read the works of writers composing in various genres and styles, and practice their own writing in those genres and styles too, ranging across fictional short stories, poetry, and personal essays. They will also learn how to participate in the workshopping of their own and other studentsâ writing, and thereby develop their captivates for offering attention, constructive feedback, and generous counsel to other emerging writers.</span></p></div> </div>','None. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15264,2027,4205,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-101','<div class="desc"> <p>What use is poetry in a time of climate emergency? This course will pose this question through an introductory study of the history of English-language poetry’s consideration of human relationships to the environment, with a particular focus on the US, UK, Caribbean, and Pacific Islands. Topics may include: the poetics of agricultural labor and natural disaster; poetic responses to the historical effects of industrialization, colonialism, and slavery on nature; Romantic, modernist, and Indigenous meditations on human alienation from our embeddedness in nature; and recent poetry about the human and environmental consequences of mining, oil and gas extraction, and climate change. Students new to and experienced with poetry are equally welcome to enroll. Participants in this class will learn to read, interpret, and write about poems carefully and persuasively, and study the specific forms of environmental thinking that poetry in English has developed in the modern world.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15265,2027,4206,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-105','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course focuses on film adaptations of literary fiction. We will analyze the differences between literary and cinematic works that tell the same story in order to better understand the artistic techniques of the two mediums; the possibilities, challenges, and limitations of adaptation from one medium to the other; and the use of one medium to reveal something we might not see about the other on its own. This course will give you an introduction to literary and film studies and help you build your capacities to read, view, interpret, discuss, and write about literature, film, and their overlaps and differences. Works may include a selection of the texts and film adaptations of William Shakespeareâs <em>Macbeth</em>, Jane Austenâs <em>Emma</em>, Mary Shelleyâs <em>Frankenstein</em>, Edgar Allan Poeâs <em>Fall of the House of Usher</em>, Pierre Boileauâs <em>Vertigo</em>, James Cainâs <em>Double Indemnity</em>, Margery Sharpâs <em>Cluny Brown</em>, Nella Larsenâs <em>Passing</em>, Alex Haleyâs <em>The Autobiography of Malcolm X</em>, Antonio di Benedettoâs <em>Zama</em>, Viet Thanh Nguyenâs <em>The Sympathizer</em>, Percival Everettâs <em>Erasure</em>, and Charles Yuâs <em>Interior Chinatown</em>. The course will also provide students with opportunities to make their own short film adaptations of literary texts, or alternatively, to write short literary adaptations of films. </span></p></div></div> </div>','None. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15266,2027,2742,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-140','<div class="desc"> <p>This class will examine the literature and culture of the Victorian period, from the 1830s to the turn of the twentieth century. We will read classic Victorian novels such as<em> Silas Marner</em>, <em>Great Expectations</em>, and <em>Jane Eyre</em> alongside more contemporary literary and cinematic interlocutors including <em>Wide Sargasso Sea</em>, <em>Thugs of Hindostan</em>, and <em>Victoria and Abdul</em>. In thinking about the period’s lasting impact on our own society, we will consider the broader historical context of imperialism, urbanization, and industrialization, all of which expanded dramatically during the Victorian era. We will also examine the shifting social and legal structures of the era, addressing issues of class, sexuality, and race.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15267,2027,1698,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-142','<div class="desc"> <p>Students will join scholars like Emily Lordi, Shana Redmond, and Brent Edwards, who look at how the literary and musical mutually inform one another in the Black Diaspora, how gender tensions can enrich literary and musical creation, how these creative influences often trespass (or help to change) national boundaries. In this course, blackness is not simply an identity on the census, but a site of contingency, translation, and formal experimentation. This course will look at several literary genres, including short fiction, poetry, novels, and political essays, as well as musical genres, including jazz, gospel, opera, labor movement anthems, and hip-hop. The syllabus will pair works of literature and music in relation to relevant scholarship. Readings will include (but are not limited to) W.E.B. Du Bois'' international political essays and their direct references to Wagner; Mahalia Jackson and the writings of Martin Luther King; Richard Wright and Bessie Smith; Kendrick Lamar and the pre- and post-prison writings of Nelson Mandela; and other fascinating encounters between literature and music in Black America and the Black Diaspora.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15268,2027,4207,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-145','<div class="desc"> <p>This course provides an introduction to film analysis with a focus on cinema exiles in early 20th-century Hollywood: a group of Jewish filmmakers driven from Europe by the rise of Nazism who settled in Los Angeles and forever changed cinema. We will study the films of Ernst Lubitsch, Billy Wilder, Fritz Lang, Robert Siodmak, Michael Curtiz, and Otto Preminger, paying particular attention to how they formulated key aspects of film noir and romantic comedy. While film noir paints a bleak picture of passion, violence, and desperation in American culture, the rom com structure promises pleasure and reconciliation, transgressive zaniness wedded to social order. But films in these two contrasting genres often tell different versions of the same story, or provide entangled perspectives on related American possibilities, and we will continually compare them in order to consider issues of cinematographic technique and style, plot and tone, agency and structure, capitalism and class, gender and sexuality, as well as race and power. Throughout the course, we’ll learn to think about how these filmmakers experienced exile, and how that experience made its way into their films. In addition to coming away with a basic grasp of film history and analysis, as well as the importance of genre in the evolution of American cinema, students will also learn about the early history of Hollywood and the complex relationship between Jewishness, antifascism, and whiteness in the first half of the 20th century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15269,2027,3903,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-147','<div class="desc"> <p>This course will examine 19th-century British and Indian novels in dialogue with their 20th- and 21st-century Bollywood film adaptations, both of which are full of innovative approaches to narrative and cinematography. A product of the largest film industry in the world, Indian cinema is consumed globally. Questions of globalism were also central to 19th-century novels that were written during the height of British colonial rule. Students will learn how to interpret and write about both literature and film in this course, paying particular attention to representations of globality and cultural difference, subject formation, gender and racial norms, and nationalist sentiment in the era of empire and the postcolonial moment.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15270,2027,1517,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-155','<div class="desc"> <p>The pandemic of 2020 has revealed the surprising number and diversity of fantasies, fears, and anxieties surrounding the notion of science. While some of these reactions are relatively new (particularly those grounded in historically specific conspiracy theories), most emerged over the course of several centuries. Literary works, particularly novels, often explore these fears and anxieties in far greater detail than may be found in the direct attacks on or defenses of science. Texts like Mary Shelley''s <em>Frankenstein</em> or Bram Stoker''s <em>Dracula</em> both draw on scientific theories and articulate fears of the possible consequences of these theories that still resonate with readers today. We will read literary texts to determine what exactly those who reject science fear, and what is at stake in their rejection of science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15271,2027,2986,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-165','<div class="desc"> <p>This class will read examples of queer Anglophone fiction across a broad range of historical periods and geographical regions. Beginning with Kate Chopin’s <em>The Awakening</em>, through Nella Larsen’s <em>Passing</em>, Djuna Barnes’s <em>Nightwood</em>, and E.M. Forster’s <em>Maurice</em>, we will explore the intersection between sexuality and other social structures such as race and class. We will build on this intersectional foundation to examine the legacies of colonialism, gender-policing, and marital normativity in contemporary global queer novels such as Shani Mootoo’s <em>Cereus Blooms at Night</em>, Akwaeke Emezi’s<em> Pet</em>, Chinelo Okparanta’s <em>Under the Udala Tree</em>, and Shyam Selvadurai’s <em>Funny Boy</em>. Over the course of the semester we will supplement our readings of novels with various theoretical texts that address the social and political contours of queer literature and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15272,2027,1657,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-178','<div class="desc"> <p>This class introduces you to some of Shakespeare’s most challenging and rewarding plays, with a focus on both their historical moment and film adaptations that have reanimated them across the second half of the 20th and 21st centuries. Our main topic will be Shakespeare’s evolving exploration of the predicament of tragedy in an era of major social, religious, and political transformation for Europe (England especially), and the ways that filmmakers have adapted Shakespearean tragedy for the big screen in different times and places. We will study Shakespeare''s explorations of dramatic form, poetic style, characterization, and ideology, and examine how the choices made in filming Shakespeare allow us to think in new ways about the plays themselves, and about the historical context in which the films were made. This course will introduce you to foundational concepts in literary studies and film studies, help you learn how to engage with Shakespeare''s plays more deeply, and enable you to analyze how film adaptations bring to life or transform the complex, unruly energies that characterize Shakespearean tragedy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15273,2027,4208,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-180','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">What exactly is a âgood immigrantâ? Where did we get the idea of âbad Asiansâ? With literature as our main object of study, this course will focus on the history and persistence of model minority myths in the US popular imagination. We will discuss the 19th-century precursors to this notion in seemingly antithetical âyellow perilâ immigration discourse. Moving into the 20th century, we will see how the positive stereotype of a model citizen and worker requires the erasing of distinctions within âAsian Americanâ and gives rise to harmful ideas about Black and Latinx Americans. We will follow these threads as they morph across periods of exclusion, internment, and global economic power. The later part of our semester will focus on literature and culture in the wake of the 1965 Immigration and Nationality Act, which ended national origins quotas and, through its tiered system for âskilledâ immigrants, profoundly reshaped public discourse on what it meant to be a racial exemplar. Readings may include Hisaye Yamamotoâs short stories, John Okadaâs</span><span style="font-size: 12pt"> <em>No-No Boy</em></span><span style="font-size: 12pt">, Chang-rae Leeâs </span><span style="font-size: 12pt"><em>Native Speaker</em></span><span style="font-size: 12pt">, Brian Ascalon Roleyâs </span><span style="font-size: 12pt"><em>American Son</em></span><span style="font-size: 12pt">, Elaine Castilloâs </span><span style="font-size: 12pt"><em>America is Not the Heart</em></span><span style="font-size: 12pt"><em>,</em> Weike Wangâs </span><span style="font-size: 12pt"><em>Chemistry</em></span><span style="font-size: 12pt">, Adrian Tomineâs </span><span style="font-size: 12pt"><em>Shortcomings</em></span><span style="font-size: 12pt">, and short fiction by Vanessa Hua, Tony Tulathimutte, and Jenny Bhatt. We will also look at the film </span><span style="font-size: 12pt"><em>Gran Torino</em></span><span style="font-size: 12pt"> and episodes of the TV show </span><span style="font-size: 12pt"><em>Ramy</em></span><span style="font-size: 12pt">. </span></p></div></div> </div>','None. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15274,2027,4209,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15275,2027,4210,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/100/engl-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15276,2027,2882,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-220','<div class="desc"> <p>In this course we will study the relationship between literature and science during the Scientific Revolution of the seventeenth-century in England. Though today we usually consider science and literature to inhabit different spheres, in the era when “modern science” began there was no clear division between the two. We’ll explore the shared questions about the earth, human nature, the cosmos, and the divine that motivated new conceptions of scientific experiment and innovations in literary writing. We''ll also examine how the institutionalization of experimental science, especially with the founding of the Royal Society, transformed English literature as well as England''s orientation to Continental Europe and the "New World." Readings will be drawn from the work of scientists, fiction-writers, essayists, and poets, including William Shakespeare, Francis Bacon, Galileo Galilei, René Descartes, John Donne, Ben Jonson, Thomas Browne, Blaise Pascal, Robert Boyle, Anne Conway, Robert Hooke, Margaret Cavendish, John Milton, Thomas Hobbes, Lucy Hutchinson, and Isaac Newton.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15277,2027,2987,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-222','<div class="desc"> <p>What, if any, is the relationship between revenge and justice? This course will pose that question primarily through a careful study of English Renaissance revenge tragedy (Kyd, Marlowe, Shakespeare, Webster, Middleton) and its dialogue with ancient models of the genre (Aeschylus, Seneca). We will also read Renaissance romances about the challenges of tempering the desire for revenge (Cervantes, Spenser). Our study of these literary works will enable us to understand key developments in the legal and religious thinking of Renaissance Europe (especially England), and the relevance of these innovations to the complex role revenge plays in our current moment. We will likewise survey some influential philosophers of revenge from antiquity to the present, and if time allows, we’ll examine the importance of revenge to contemporary fiction and film. Some questions we’ll ask include: How have artists imagined the desire for and consequences of revenge? What cultural and legal structures have been constructed to produce, mediate, temper, or sublimate vengefulness? How have modern conceptions of justice relied on, or occluded, revenge? When does revenge uphold structures of oppression and when can it aid in resisting or abolishing them? This class will give you tools to analyze the long history of revenge and its ramifications for literature and law in Renaissance England, and enable you to think more critically about the role of revenge in our own legal, political, and cultural worlds today.</p> <p class="sc-BodyText"><span>Major Requirement Met:</span><span> <strong>Group I</strong></span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15278,2027,4029,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-225','<div class="desc"> <p>A course about Shakespeare''s comedies and histories. What constitutes these plays as "nontragic"? In what sense are their endings happy? What gets left out of their visions of personal or political reconciliation? Primary emphasis in our study and in your writing will be on the language and structure of the plays, with some attention to performance, and to the relationship--sometimes the tension--between Shakespeare''s theatrical and poetic vocations. Some semesters may focus exclusively on history or on comedy, and topics vary but may include: chronicle, civil war, and national ideology; rebellion; law and criminality; race, religion, gender, and class; love, jealousy, marriage, and sexuality; the nature of literary/dramatic character; rhetoric and dialogue; time and timing; plot and plotting. Students in this class will learn how to read and interpret Shakespeare''s comedies and histories and to understand them in their historical context as reflections on England and its relationship to continental Europe and the colonial world. Students will develop a vocabulary for critically discussing these plays with precision and nuance and write sensitive literary criticism about the structure, language, and themes of the plays.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15279,2027,3922,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-240','<div class="desc"> Literature and the law share several fundamental elements. Both employ storytelling to create impressions of characters and represent events. Both serve a didactic and disciplinary function within society. And both involve complicated acts of interpretation to make sense of the narrative at hand. These are some of the reasons that scholars have been interested in the relationship between the two disciplines. At the same time, there are significant tensions between the two disciplines around claims to truth, authority, and voice that have posed problems to the task of thinking about law and literature together. This course examines the history of the interdiscipline, including its various forms: law in literature, law as literature, and law and literature. We will read foundational texts in the law and literature movement, as well as contemporary examples of the methodology, which we will apply to film and literature from the nineteenth century to the present. Texts we will consider include E.M. Forster’s A Passage to India, Mary Shelley’s Frankenstein, Robert Louis Stevenson’s Strange Case of Dr. Jekyll and Mr. Hyde, and Sara Collins’s The Confessions of Frannie Langton. ENGL 240 will introduce students to the relationships between law and literature in the UK, the US, and areas where these countries historically imposed imperial law. </div>','None. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15280,2027,1592,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-241','<div class="desc"> <p>This course looks at representations of "deviance" in 19th- and early 20th-century literature. Underlying our examination will be an investigation of what constitutes the "normal" and the ways in which normativity polices its boundaries. Focusing primarily on literary and filmic representations of the sexual, racial, legal, and economic "taboo," in works including Charles Dickens''<em> Great Expectations,</em> E.M. Forester''s <em>Passage to India, </em>and Djuna Barnes'' <em>Nightwood</em>, we will seek to uncover the terms of normativity, against which the figure of the deviant emerges into representation. We will supplement our analysis of literature with readings from a range of theoretical methodologies, from psychoanalysis, legal theory, Marxist/economic theory, to postcolonial and critical race studies. </p> <p>Major Requirement Met: <strong>Group II/IV</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15281,2027,4211,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-245','<div class="desc"> <div><p>What is real? How does the rise and evolution of the novel reflect or influence different understandings of reality and its relationship to fiction? This course studies the representation of reality in British and American novels written in the 18th, 19th, and early 20th centuries and also attends to elements in those novels that seem less than real, such as fantasies, dreams, impossible perceptions, and the paranormal. We will ask how the very different paths of the realist novel in the UK and US attempted to depict the realities of British and American communities in various local geographical contexts, and how those depictions of reality were shaped by unfolding historical events and the circulation of ideas across the Atlantic and across the British and American Empires. The course will teach you to read, discuss, interpret, and write about novels by authors like Daniel Defoe, Jane Austen, George Eliot, Nathaniel Hawthorne, Stephen Crane, Pauline Hopkins, Henry James, Virginia Woolf, Charles W. Chesnutt, and James Baldwin. Itâll get real.<br/><br/></p></div> </div>','None ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15282,2027,2337,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-248','<div class="desc"> <p>This course will focus on novels by major British nineteenth-century authors, with particular attention to the production of gender roles and the influence of economic forces on character and language. Read in relation to the historical context of rapid change from a land-based to a money-based economic system in the United Kingdom, the novels reveal how the introduction of capitalist practices affected men and women differently. The novels dramatize the ways that capitalism influences the feelings and thought processes of individuals. The class will also pay close attention to the novels’ style and wording, with an eye to seeing how language itself is infiltrated by market practices and values.</p> <p><span>Major Requirement Met: </span><span><strong>Group II</strong></span></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15283,2027,4212,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-250','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">Abstraction, fiction, character--these terms associated with literary and cultural expression are also useful, even necessary, for thinking about</span><span style="font-size: 12pt">capitalism. This class will consider two areas of overlap between US literature and the logic</span><span style="font-size: 12pt">of capital accumulation. We will look at outright depictions of what it is like to work, own, consume, and owe money against the backdrop of economic restructuring. Some writers on our syllabus attempt to capture the individual contours of experience through narratives about seasonal farming, office life, or restaurant service work. These works may dramatize collective experiences of class, or point to the emotions and judgments provoked by economic circumstances. But there are also authors who use formal inventions to illustrate capitalism as an economic system and social order. We will consult with writers and scholars who propose that the financial crisis has its own aesthetic, that unmarked racial character tells us something about the dynamics of global capitalism, and that strategies of lyric poetry reveal the âhidden abodeâ of domestic labor. Readings may include Hernan Diazâs </span><span style="font-size: 12pt"><em>Trust</em></span><span style="font-size: 12pt">, Helena MarÃ­a Viramontesâ </span><span style="font-size: 12pt"><em>Under the Feet of Jesus</em></span><span style="font-size: 12pt">, Ed Parkâs </span><span style="font-size: 12pt"><em>Personal Days</em></span><span style="font-size: 12pt">, Merritt Tierceâs </span><span style="font-size: 12pt"><em>Love Me Back</em></span><span style="font-size: 12pt">, Ling Maâs </span><span style="font-size: 12pt"><em>Severance</em></span><span style="font-size: 12pt">, Karen Tei Yamashitaâs </span><span style="font-size: 12pt"><em>Through the Arc of the Rainforest</em></span><span style="font-size: 12pt">, Julio Puente GarcÃ­aâs short fiction in translation; poetry by Bernadette Mayer, Janice Lobo Sapigao, and Stephanie Young; and the films </span><span style="font-size: 12pt"><em>Snowpiercer</em></span><span style="font-size: 12pt"> and </span><span style="font-size: 12pt"><em>Sorry to Bother You</em></span><span style="font-size: 12pt">.</span></p></div></div> </div>','None. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15284,2027,3839,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-265','<div class="desc"> <p>This course examines the historical construction of the âwhite womanâ and her non-white counterparts through American literature, visual art, and film. Combining literary analysis with tools from scholars of gender and sexuality, we will trace how notions of womanhood in the US have been formed through social and institutional associations of race and sexuality. We will follow these notions as they develop in a set of linked narratives that depict womenâs self-indigenizing within a settler colonial context, southern anxieties over endangered white womanhood, and cross-racial identification as a (haphazard) strategy for solidarity. In our final unit, we will examine works of contemporary writing and film that propose the possibility of a âwhite girlâ who is not necessarily a girl and not necessarily white. The syllabus includes texts by Zitkala-Sa, Sojourner Truth, Harriet Jacobs, Edith Wharton, Nella Larsen, Flannery OâConnor, Cherrie Moraga, Hilton Als, Sigrid Nunez, and Alexander Chee, along with visual art (Nikki S. Lee, Adrian Piper) &amp; film (Kill Bill). Major requirement met: Group III or Group IV</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15285,2027,3987,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-266','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">Idyllic natural expanses, obliging or menacing Native American characters, scenes of âtotem transferâ: these are signature features of the Western genre in the US. This set of recognizable tropes and scenes has historically consolidated ideas of settler innocence and white heroism. With a focus on literary fiction, this course will examine the Western as it is shaped by configurations of racial difference, nation, citizenship, settler colonialism, and gender. We will consider how the signature features of this genre aim to explain away, or neutralize, the violences of Indian Removal and settler claims to land. We will see how the negative portrayal of Indigenous people in Western narratives has been paired with the subtle Indigenizing of settler protagonists through stories of nativism and adoption fantasies. Our readings will examine how romanticized images of the Old West have also relied on stereotypes of Mexican, Chicano, Black, and Asian characters. For newer writers and filmmakers, the Western offers a set of parameters with which to question such racial assumptions. Readings for this course may include James Fenimore Cooper''s "The Prairie," excerpts from Johnston McCulleyâs Zorro novels, Ken Liu''s "All the Flavors," Claudia Craven''s*Lucky Red*</span><span style="font-size: 12pt">, Cormac McCarthy''s *All the Pretty Horses*</span><span style="font-size: 12pt">, C Pam Zhang''s *How Much of These Hills is Gold*</span><span style="font-size: 12pt">, </span><span style="font-size: 12pt">Tom Lin''s *The Thousand Crimes of Ming Su*</span><span style="font-size: 12pt">, Daniel Cooper AlarcÃ³nâs essay </span><span style="font-size: 12pt">"All the Pretty Mexicos," </span><span style="font-size: 12pt">and Chloe Zhaoâs film *The Rider.*</span></p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15286,2027,3573,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-267','<div class="desc"> <p>Most students are aware of Andre Breton''s Parisian circle of surrealists, who have become synonymous with intellectual and artistic experimentation, combined with political engagement. Fewer realized that surrealist aesthetic techniques were being practiced at the exact same time within the Black Diaspora, among its Francophone, Anglophone, and Hispanophone speakers. Surrealism attracted artists, intellectuals, and activists from so many different cultures because it surpassed previous avant-garde art movements in linking creativity to a critique of colonialism. It is not surprising that surrealism found a special expression in the African Diaspora.</p> <p>However, the sheer breath of African Diaspora artists taking up surrealist techniques and themes is staggering. This course serves as an exploration of Afrosurrealist expression. The course begins in the early 20th century with the first generation of writers to embrace the term surrealism, then moves to the mid-20th century. But the majority of the course looks at 21st century literature, music, and visual art. European artists who took anti-racism seriously will also be included along the way. Students will encounter the work of Aime and Suzanne Cesaire, Romare Bearden, Claude Cahun, David Hammons, Senga Nengudi, Wangechi Mutu, D.S. Marriott, Terrance Nance, and Tierra Whack, among others. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15287,2027,4415,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-271','<div class="desc"> <p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0;"><span style="font-size: 12pt;"></span><span style="font-size: 12pt;">The 1965 Immigration and Nationality Act eliminated racialized quotas and established a system for "skilled" immigrants to enter the country. This dramatic change meant new channels for migration--and new discourses about who should or shouldn''t come to the US. With a focus on American literature and film after 1965, this course examines narratives about people moving across borders and the narrative practices required to define, filter, grant rights to, or exclude those people. In stories of coming to America, protagonists break with their pasts, seek work or schooling, come of age, find new homes, argue with their families, joke, and wrestle with the immigration process itself. While genres like the coming-of-age realist novel are commonly associated with these experiences, we will look at how other narrative forms--sci-fi stories, absurdist comedies, experimental poems--take aim at the shifting ways in which the nation constructs borders, human "illegality," and racialized conceptions of citizenship. We will also look at the meta-commentary provided by writers who reflect on the clichés of "good immigrant novels" or filmmakers situating plotlines beyond intergenerational culture clash scenarios. We will read these works in tandem with scholars and activists interested in the political and legal histories of immigrants in the US and transnational migration more broadly. Although our focus is post-1965, we will spend time with the earlier history of what Mae Ngai calls the "impossible subject": a person whose inclusion in the nation is "at once a social reality and a legal impossibility." These critical accounts will deepen our approach to imaginative depictions of immigration and complicate our received ideas about what it means to seek belonging from a nation-state. The syllabus may include Julie Otsuka''s *The Buddha in the Attic*, Elaine Castillo''s *America is Not the Heart*, Julia Alvarez''s *How the Garcia Girls Lost Their Accents*, NoViolet Bulawayo''s *We Need New Names*, Hernán Diaz''s *In the Distance*, Gish Jen''s *Typical American*, and the films *Minari* (2020), *Problemaista* (2023), *Past Lives* (2023), and *Sin Nombre* (2009).</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15288,2027,4213,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-272','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course looks at how science fiction mediates a changing Asian subject, racialized notions of economic expansion, and lingering images of âthe Orientâ in the US literary and cultural imagination. Why are Asian characters represented as cyborgs across fiction and film? How do the tropes and narrative parameters of science fiction interact with âyellow perilâ fears and fantasies? What does science fictionality say about Asian immigrants in scientific and technical fields? Our readings will consider the Asian future anxiously conceived in wartime and other periods of renewed racist nationalism. We will follow the development of Asian American literary production as it responds to such attitudes by taking up science fiction as a critical framework. Possible texts include Eugene Limâs </span><span style="font-size: 12pt"><em>Dear Cyborgs</em></span><span style="font-size: 12pt">, Ling Maâs</span><span style="font-size: 12pt"> <em>Severance</em></span><span style="font-size: 12pt">, Larissa Laiâs </span><span style="font-size: 12pt"><em>Automaton Biographies</em></span><span style="font-size: 12pt">; short fiction by Jack London, Ken Liu, Charles Yu, Juliana Wang, and Ted Chiang; and the film </span><span style="font-size: 12pt"><em>Blade Runner</em></span><span style="font-size: 12pt"><em>.</em> </span></p></div></div> </div>','None ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15289,2027,1699,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-273','<div class="desc"> <p>American poetry has resurged in cultural and political significance in the 21st century. Poets have reframed the nation''s controversies and recovered its forgotten histories. Notably, poets have shifted American consciousness without losing sight of artistic experimentation. Poetic genres, in this course, are more than familiar literary conventions. They are ways of thinking and feeling. Poets experiment with literary form in hopes of staying true to the nation''s complexities. Fragmentation, intertextuality, ekphrasis, and erasure are all crucial techniques for exploring beauty, mental health and disability, immigration and war. This course will examine several award-winning poets, including Kevin Young, Molly McCully Brown, Robin Coste Lewis, Solmaz Sharif, and Philip Metres.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15290,2027,1700,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-274','<div class="desc"> <p>This course will focus on the intersections among race, gender, sexuality and culture in 19<sup>th</sup>, 20<sup>th</sup> and 21<sup>st</sup> century novels within three different cultural traditions: African American, Anglo American, and Native American. African American women writers include Harriet Jacobs, Nella Larsen, Zora Neale Hurston, and Toni Morrison. Native American women writers include Louise Erdrich and Leslie Marmon Silko. Anglo American women writers include George Eliot, Kate Chopin, and Virginia Woolf.</p> <p><span>Major Requirement Met: </span><span><strong>Group III/IV</strong></span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15291,2027,1593,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-280','<div class="desc"> <p>The focus of this course is writing, and developing a relationship with, short fiction, with the aim of making it a fluid manifestation of the way we process and transform memory and experience. We will play into and take seriously Toni Morrison’s conception of memory as <em>a form of willed creation</em>, in an ongoing attempt to reanimate forgotten or unrealized aspects of our histories and ourselves. Students will generate new work constantly—in sketchbooks, exercises, and story drafts—paying attention to the honing of various craft elements (description, dialogue, character and plot development), and in correspondence with texts by a variety of exemplary practitioners of fiction and prose writing (Venita Blackburn, K-Ming Chang, Fleur Jaeggy, Jamaica Kincaid, Maxine Hong Kingston, Li-Young Lee, Clarice Lispector, Scholastique Mukasonga, Nhã Thuyên, among others). Students will share and discuss their work in a workshop format, the orientation of which will be based, in part, on each student’s specific intentions. The discussions will be supportive, inquisitive, and constructive, and will be oriented towards helping to introduce each other—and ourselves—to what is most compelling and imperative about what we are doing, what it is that we want to be doing, and how we might get there. Open to first- and second-year students. May be repeated once for credit.</p> </div>','One First Year Seminar, CWP 201 (formerly WRD 201), or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15292,2027,1518,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-281','<div class="desc"> <p>This course introduces students to the fundamentals of poetry writing. Students will learn how to craft and revise poems, and will workshop their poetry in class with their peers. Outside readings will also be required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15293,2027,1221,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-287','<div class="desc"> <p>We might think that older literature by the likes of Chaucer, Shakespeare, and Milton is dustily conventional, a cultural tradition that we''re obliged to read (or compelled to disavow) but that has little relevance to our lives today. The goal of this class will be to persuade you, to the contrary, that the literature written during the period beginning with Chaucer''s Canterbury Tales in the late 14th century and ending with Milton''s Paradise Lost in the 17th century constitutes one of the most exciting and experimental moments in literary history, one that offers uniquely relevant lessons for contemporary thinking about community and storytelling, narrative and memory, truth and perception, race and power, as well as gender and sexuality. At the same time, we will explore what is productively strange, challenging, and even alienating about these texts from the past, measuring how their distance from us provides unique opportunities for thinking. We will also examine how authors such as Chaucer, Shakespeare, Spenser, and Milton came to constitute the foundation of the English literary canon, and how this canon has been used to advance (or to critique) English national and colonial ideologies. Together we’ll explore a set of analytic concepts and strategies for interpreting their unique texts that will make you a more sensitive, precise, and persuasive reader and writer.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15294,2027,1222,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-288','<div class="desc"> <p>A survey of modern British and Anglophone literature, this course ranges across the rise of the novel in the 18th century, the birth of Romanticism, the varieties of realism (and its others) in Victorian-era fiction and poetry written in England and across its empire, and modernismâs diverse experiments; it concludes with some more contemporary British and Anglophone writers that reflect on Britainâs past and present from different geographical standpoints. The survey is meant to help students explore, discuss, and write perceptively about the literary innovations in these different periods of British literature, and to situate the literary works studied in the historical contexts they were shaped by and responded to (including the Restoration, industrialization, the expansion of the British Empire, the World Wars, decolonization). Students will gain a broad understanding of modern British literary history and the spread of Anglophone literature across the globe during the 19th-21st centuries, cultivate their capacities for interpreting challenging poetry and fictional prose, and grow as analytic writers. </p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15295,2027,1223,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-289','<div class="desc"> <p>Course topic when Professor Grossman is the instructor:</p> <p>This course surveys the history of US literature in relation to feelings. Beginning in the settler colonial period and working our way to the present, we will look at how a literary tradition forms its âAmericannessâ around the idea of shared, public, or collective emotions. Reading across fiction and poetry, weâll examine the emergence of genres like the captivity narrative, the Southern Gothic, and the presidential inauguration poem. Some of these works attempt to distill a national perspective--revolutionary resentment or liberal optimism, for instance--into the individual feelings of a character or poetic speaker. Others aim to implicate the reader in feeling and thinking across difference. We will pay particular attention to connections between discourses of race and antiracism as they consolidate in and around literary thinking. Throughout our discussions, we will consult a range of essays grappling with the limits of literature-induced sympathies, and consider how contemporary writers respond to the enduring legacy of âsentimentalâ imperatives. Our authors will include Mary Rowlandson, Phillis Wheatley, Nathaniel Hawthorne, Herman Melville, Emily Dickinson, Harriet Beecher Stowe, Zitkla-Sa, Sui Sin Far, Charlotte Perkins Gilman, Pauline Hopkins, Henry James, Langston Hughes, William Faulkner, Younghill Kang, Carlos Bulosan, Rodolfo âCorkyâ Gonzales, James Baldwin, Karen Tei Yamashita, N. Scott Momaday, Jhumpa Lahiri, and Elaine Castillo, among others.</p> <p>Course topic when Professor Ford is the instructor:</p> <p>This survey grapples with the centrality of war to American literature--indeed, to American life. The course moves chronologically through Early American and the American Revolutionary Wars and ends with the War on Terror. We will examine the strengths and limits of depicting war through lyric poetry, short epic poetry, political pamphleteering, oratory, autobiography, and the novel. In addition to considering literary forms, this course considers what understudied voices have to say about what leads to war, the experience of war, and its aftermath. Our readings will include Phillis Wheatley, Timothy Dwight, Philip Freneau, Walt Whitman, Ernest Hemingway, Zora Neale Hurston, Philip Metres, and Solmaz Sharif, among others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15296,2027,1224,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-290','<div class="desc"> <p>This course will introduce students to contemporary critical methodologies in literary studies. Students will engage a wide range of critical approaches to help ground their subsequent study of literature across the English department curriculum. By studying influential works of theory and criticism, students will become familiar with the historical genesis of literary studies, with special attention to the political, social, and other institutional factors informing the rise of particular methodologies in the academe. We will trace these critical genealogies so as to recognize and participate in the fullness of literary studies.</p> </div>','One First Year Seminar, CWP 201 (formerly WRD 201), or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15297,2027,2949,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-295','<div class="desc"> <p>Topics vary. Different topics may satisfy different Core requirements.</p> <p><strong>The Dystopian Novel</strong></p> <p>This course explores the emergence of dystopia as a genre for the modern novel, reading the most salient works of the genre. We seek to understand what elements cohere the genre of dystopian fiction, what elements are borrowed from other forms and what invented anew. And finally, we also consider what is peculiar to dystopia as a genre all its own. </p> <p>Alongside such classics as Wells’ <em>The Island of Dr. Moreau</em>, Huxley’s <em>Brave New World</em>, Orwell’s <em>Nineteen Eighty-Four, </em>and Atwood’s <em>A Handmaid’s Tale, </em>we will also read work by Octavia Butler<em>, </em>Kazuo Ishiguro, Ling Ma, M.R. Carey and others. The syllabus will include brief philosophical and critical readings on utopia, science, satire, feminism, race, capitalism, and modernity and a few films (<em>Blade Runner; Babadook; Thing</em>). Core Requirement Met: Global Connections. Major Requirement Met: Group II.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15298,2027,4214,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/200/engl-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15299,2027,1519,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-311','<div class="desc"> <p>Before the modern novel, we had romance: the literature of error and erring, stories of characters who set out on a quest and lose their way due to madness, obsession, lack of faith, or the difficulty of knowing the truth about themselves or their quests. Romance was one of the most important genres of imaginative literature in medieval and Renaissance Europe, and yet it was also the one that provoked the most profound moral and aesthetic concern. Hugely popular, romance was often condemned for its endless attention to pleasure, pain, error, and forgetting, for its perverse magical stories of exploration and complicity, for its unseemly analysis of chivalric duty and obsession--and even for its capacity to corrupt its readers beyond repair. (Famously, Don Quixote was driven mad by reading romances!) Whether viewed as a genre of utopian dreaming or of lurid and dangerous narrative failure, romance is a vexed concept. By examining pre-modern and modern genre theory, this class will explore the formation of the category of romance across medieval and Renaissance England (with some attention paid to France, Italy, and Spain), thus giving students an opportunity to consider how genre can enable and constrain understanding of particular works of literature. Texts may include Virgil''s <em>Aeneid</em>, Chrétien de Troyes Arthurian tales, Geoffrey Chaucer''s <em>Troilus and Crisyede</em>, the anonymous Pearl-Poet’s <em>Sir Gawain and the Green Knight</em>, Miguel de Cervantes''s <em>Don Quixote</em>, Philip Sidney’s <em>Arcadia</em>, Edmund Spenser''s <em>The Faerie Queene</em>, William Shakespeare’s <em>Cymbeline</em>, and Mary Wroth’s <em>Urania</em>. At the end of the semester, we may turn to more recent works (such as Samuel R. Delany''s speculative fictions or Caroline Bergvall''s poetics of error) to get a sense of how pre-modern romance remains an archive for some of the most exciting literary production today.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15300,2027,2829,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-314','<div class="desc"> <p>This course examines the poetry and poetics of the English Renaissance, emphasizing the relationship between formal developments in poetic techniques and questions of religious belief, gender, labor, race, education, and politics. Readings include classical and humanist poetic and rhetorical theory (from Plato to Puttenham) and a wide range of poets, including Thomas Wyatt, Anne Locke, Philip Sidney, Edmund Spenser, William Shakespeare, John Donne, John Milton, Andrew Marvell, Mary Wroth, and Katherine Philips, as well as some consideration of the influence Renaissance verse has had on modern poets (such as T.S. Eliot, Frank O''Hara, and Marilyn Nelson).</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 200-level English class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15301,2027,4215,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-315','<div class="desc"> <p>This seminar will explore the development of lyric poetry and of theoretical reflections on lyric in Anglophone modernity, with a focus on the historical evolution of three poetic kinds since the Renaissance: the sonnet, the elegy, and environmental poetry (especially pastoral and georgic). Canvassing the ways “lyric” has functioned as a term for particular kinds of expression, thought, and classification, this class will provide students with a set of tools to read and write about an archive of short poetry from the sixteenth century to the contemporary moment. Even though it is ostensibly the most personal and hermetic of literary genres, lyric poetry is often produced by what the philosopher Theodor Adorno calls a “collective undercurrent”--a complex shuttling between individual voice and the social structures that shape the forms and possibilities of expression. We will attend to how lyric has crystalized different historically situated understandings of self and society, with an eye towards how the form of a short poem exposes aesthetic, philosophical, and political questions of great urgency. </p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 200-level English class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15302,2027,4216,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-316','<div class="desc"> <p>This course studies the relationship between late medieval and Renaissance literature and what Karl Marx called “primitive accumulation,” the production of a system for enhancing the emergent European capitalist economy by dispossessing vulnerable populations across the globe. From land enclosure and privatization to colonialism and slavery, primitive accumulation made--and continues to make--the world we live in. We will read key works in Marxist theory, along with literary and historical texts by authors such as Christopher Columbus, Thomas More, Bartolomé de las Casas, Edmund Spenser, and William Shakespeare, in order to study representations of race, economy, and environmental extraction in the fictions that some early modern Europeans told about their role in a new global society.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 200-level English class ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15303,2027,4217,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-318','<div class="desc"> <div><div><div><p>This course explores the relationship between literature and history. It takes Shakespeare''s plays about the history of England (especially the so-called Henriad) as its primary objects of study, but will also compare them with some other plays and epic poems written in the time of Shakespeare (by Christopher Marlowe, Edmund Spenser, Ben Jonson, and others). We will examine how these works participated in the construction of an official English national history sponsored by the monarchy, and also explore in what ways they were able to be critical of official (propagandistic) narratives of national history. In the final part of the course, we will study a more recent historical novel, historical short fiction collection, or documentary poetry volume (possibilities include George Eliot''s Romola, Hilary Mantel''s Wolf Hall, John Keene''s Counternarratives, and Muriel Rukeyser''s Book of the Dead) and some recent historical films (possibilities include Lucretia Martel''s Zama and Jonathan Glazer''s Zone of Interest). Motivating questions for the course include: How does literature represent history and historical experience? How does it offer readers a feeling of and for the past? What is the relationship between the development of realism in literature and the representation of historical events in various media--the play, the long poem, the novel, the short story, and film? How does the long history of representing history as fiction bear on our contemporary concerns with propaganda, documentary, and social media?</p></div></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15304,2027,1594,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-322','<div class="desc"> <p>The Renaissance and Reformation in England witnessed the rise of imperial projects and the emergence of more centralized institutions to police sin and illegality in society; both were intended to enhance the sovereignty of the British state. This class explores the literary responses to such shifts in the culture of punishment and the project of state-building, asking why some of the most innovative works of drama, poetry, and prose in this period struggle with the purpose and effects of imprisonment, trial, penance, and slavery. Four main topics will organize the course: punishment and colonialism; the economic, theological, rhetorical, and theatrical underpinnings of legal trial; martyrdom; and the rise of the transatlantic slave trade. Each section of the course is divided into a series of sub-topics (ranging from questions of genre and psychology, to the humanist culture of teaching) to be explored through examination of a literary text and related historical and theoretical materials. Authors will include: John Foxe, Elizabeth I, Edmund Spenser, Michel de Montaigne, William Shakespeare, John Milton, Thomas Hobbes, John Locke, and Aphra Behn, among others.</p> <p>Major Requirement Met: <strong>Group I</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15305,2027,2591,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-330','<div class="desc"> <p>We will examine both literary and philosophical texts to determine how notions of the human both conditioned and were conditioned by the diverse experiences with populations deemed colonizable by various European powers, with a particular focus on England. Philosophers such as Thomas Hobbes, John Locke, and Jean-Jacques Rousseau drew on travellers'' reports concerning Africa, South Asia and the Americas to support their arguments about whether there was something like human nature, and, if so, what its characteristics were. 18th-century British literary texts such as Aphra Behn''s <em>Oroonoko</em>, John Dryden''s <em>Aurung-Zebe</em>, Daniel Defoe''s <em>Robinson Crusoe</em>, and Alexander Pope''s "Windsor Forest," among others, work to develop or bring to life the images and ideas found in both the reports of travellers and the philosophical texts of the time, and in doing so expose the unacknowledged assumptions they contain.</p> <p><img src="https://ssl.gstatic.com/ui/v1/icons/mail/images/cleardot.gif"/></p> <p>Major Requirement Met: <strong>Group 2</strong></p> </div>','One 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15306,2027,1451,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-332','<div class="desc"> <p>The class will examine British literature from the novels of Richardson, Fielding, and Sterne to the poetry of Blake, Wordsworth, and Coleridge.</p> <p>Major Requirement Met: <strong>Group II</strong></p> </div>','One 100- or 200-level ENGL course or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15307,2027,1226,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-341','<div class="desc"> <p>This course interrogates the crucial role of the law in British imperial governance by reading colonial legislation and court proceedings alongside works of 19th and early 20th century literature. Doing this allows us to examine how dominant legal paradigms were disseminated in the era''s cultural production and, in turn, how cultural ideals reflected in literature were materially implemented through the law. In addition, we will look at how literature often provided a viable means of contesting the normative terms of the law. </p> <p>Major Requirement Met: <strong>Group II/IV</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15308,2027,1520,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-345','<div class="desc"> <p>This course examines the increasing centrality of the theme of "tyranny" to American literature before 1900. Most people know the founders justified the American Revolution as a response to Britain''s tyranny during the colonial period. Fewer know that "tyranny" became a watchword for national debates over race, gender, and class conflicts. What happens to the idea of "tyranny" when it refers to threats within a nation rather than outside forces? What happens when the calls for revolution that founded the nation are asserted once again, to save the nation from its worst self? The political and ethical political implications of this 18th and 19th century conflict reverberate today. Only a multi-genre approach, incorporating a wide range of authors, could do justice to these questions. For these reasons, we will examine revolutionary pamphlets, speeches, essays, freed-persons narratives, and poetry from authors as diverse as Joseph Warren, Phillis Wheatley, Phillip Freneau, Harriet Jacobs, Ralph Waldo Emerson, Walt Whitman, and Emily Dickinson. Finally, this course listens to voices too often obscured by our focus on well-known characters in American history: the unofficial soldiers of the American Revolution, the freed-persons who emancipated themselves from slavery, the conflicted Civil War Veterans, and the working-class Americans trying to find their place in Reconstruction-era America. <br/> <br/> Major Requirement Met: <strong>Group II</strong></p> </div>','One 100-level or 200-level English course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15309,2027,1452,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-346','<div class="desc"> <p>This course explores literary representations of slavery, civil war, social reconstruction, and political backlash in 19<sup>th</sup> century America. Along the way, students will address several questions: How does literature represent demands for social change that transgress the law, like the freed persons escaping slavery? How to distinguish fugitives fighting for freedom from unprincipled outlaws? Is emancipation a single act, legal declaration or a more complicated process? And for whom? Finally, how do we grapple with the backlash to political change? By focusing on the 19th century, we can rethink how African Americans found political agency generations before the most familiar events from the Civil Rights era. Most of all, this course allows students to read literature alongside historical documents, so they can see firsthand how debates over freedom evolved in the 19<sup>th</sup> century. </p> <p>Major Requirement Met: <strong>Group II</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15310,2027,1453,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-351','<div class="desc"> <p>In this class we will examine fiction by British modernist writers such as Joseph Conrad, James Joyce, Virginia Woolf, Katherine Mansfield, D. H. Lawrence, and E. M. Forster. We will read their work critically, with attention to the ways in which it approached and reflected (or obscured) its historical context: changing gender roles, a fragile and distended empire, global reassessments of power, class, and race. We will also explore some representative later responses in British fiction to these central concerns of modernism.</p> <p>Major Requirement Met: <strong>Group III</strong></p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15311,2027,2338,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-353','<div class="desc"> <p>Since the 2008 Crash, politicians, scholars, and journalists have compared America''s current economic challenges to the Great Depression. This frequent comparison does not exhaust the significance of the Great Depression for the U.S. or the rest of the world. The 1930s is such an intriguing decade because the global economic collapse spawned new, or renewed older, political and artistic movements. In the global 1930''s, people considered art central to rethinking political allegiances and the overarching meaning of politics itself. The 1930s helps to clarify the following question in our present-day: what cultural rebuilding remains to be done and how does art contribute to such processes? Writers of the 1930''s took up this question in several different forms: through the trope of the document and its archival drive, the unconscious and the search for the Marvelous, the raised fist of labor movements or antiÂ­racist activism. This course will look at several literary (and related art) movements in, and cutting across, America, the Caribbean, and Europe. Texts will include (but are not limited to) documentary writing from Muriel Rukeyser, Richard Wright, and Langston Hughes; Surrealist writing from Europe and the Caribbean, including Aime Cesaire and Georges Bataille; and other forms of art like the photography of Cathy Cahun.</p> <p>Major Requirement Met: <strong>Group III</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15312,2027,3324,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-360','<div class="desc"> <p>In her 1993 lecture for accepting the Nobel Prize in Literature, Toni Morrison says, “[s]he is convinced that when language dies, out of carelessness, disuse, indifference and absence of esteem, or killed by fiat, not only she herself, but all users and makers are accountable for its demise.” How does language die? What does it mean to be careless with language, to not use it, to be indifferent to it and rob it of its esteem? What does it mean to kill or stifle language by official decree? In our seminar on Toni Morrison, we will engage with the writings of one of the most preeminent writers and critical thinkers in literature (US-based and otherwise) in order to examine the powerful and provocative ways in which she asked and answered these questions before her passing on 05 August, 2019. We will situate her as a cultural critic, one who produced novels, short stories, essays and speeches and in doing so, informed the frameworks of American Literature, Black Feminist Theory, American Studies and Critical Race Studies, among other fields. Thus, we will collectively unpack the ways in which Morrison’s writings have guided, contested and informed American cultural and literary production in the 20th and 21st centuries. Students will be asked to complete a research paper at the end of the term. This course meets the second-stage writing requirement for Black Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15313,2027,4218,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-361','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">Scholars have defined genre as âa constellation of recognizable formsâ; âa set of constitutive conventions and codesâ; and âa loose affectively-invested zone of expectations about the narrative shape a situation will take.â A writer chooses a genre to engage with a fixed set of parameters--which, in turn, cues readers about what to expect. This course will examine the uses of genre</span><span style="font-size: 12pt">as a narrative mediator of racial experience in the US. Popular genres like mystery, adventure, horror, sci-fi, and romance may seem contrary to the grounded sensibilities of narrative realism. But genre has long offered a useful inroad for writers attempting to cut across difference, whether by working in genres associated with particular groups (the passing novel, the North American âIndian taleâ) or by using popular forms to relate what might otherwise seem remote. This course will introduce you to the history of genres in US literature with special attention to stories of racial difference or embedded racial logics. We will look at the recent mainstreaming of genre in prestigious literary fiction and debate the continued relevance of genre distinctions in the present. Primary readings may include Piri Thomasâs </span><span style="font-size: 12pt"><em>Down These Mean Streets</em></span><span style="font-size: 12pt">, Chang-Rae Leeâs </span><span style="font-size: 12pt"><em>Native Speaker</em></span><span style="font-size: 12pt">, Tom Linâs</span><span style="font-size: 12pt"> <em>The Thousand Crimes of Ming Tsu</em></span><span style="font-size: 12pt">, Stephen Graham Jonesâs </span><span style="font-size: 12pt"><em>The Only Good Indians</em></span><span style="font-size: 12pt">; and short stories by Pauline Hopkins, Hisaye Yamamoto, Ted Chiang, and Lindsay Wong. <span style="font-size: 12pt">The class will also introduce students to more in-depth readings on theoretical approaches to genre study and recent debates about the âgenre turn.â</span></span></p></div></div> </div>','None ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15314,2027,4219,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-362','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course examines how US literature has defined itself by rendering the so-called Orient as an object of representation. One sees the shape of this discourse in Jack Londonâs "yellow peril" imaginings, in Willa Cather''s racial codings of villainy, or in Ezra Pound''s route to Imagism through haiku and not-quite-translations of classical Chinese poetry. Such works show fondness, fear, condescension, mystification, or obsession around Asiatic forms. "The East" becomes exquisite, inscrutable. US empire-making and waves of immigration would alter and relocate the Other imagined by these writings--and, with the growth of Asian American literature, bring to light more nuanced understandings of non-Western cultures and subjectivities. </span></p><br/><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">When he published the influential *Orientalism*</span><span style="font-size: 12pt">in 1978, Edward Said largely had in mind the nineteenth-century British and French views of the Middle East, Arabs, and Islam. In more recent decades, scholars around Asian American studies have theorized specific examples of how such attitudes take shape across literary and cultural developments. We''ll read and think along with these theories as they foreground a set of questions: how did Orientalist attitudes give rise to both "yellow peril" fearmongering and the "model minority" myth? How did shifting US economic and political anxieties alter the forms of Orientalism, or entangle it with other discourses of racism? Where can we find new traces of this imaginary--and what do they tell us? The writers and artists on our syllabus have found orientalized aesthetic approaches both repressive and useful for exploring ideas of authenticity, sympathy, power, gender, and the very idea of a coherent "Asian American" subject. We''ll look, for instance, at how postwar fears of a dominant, mechanized Asia paved the way for present-day visions of cyborgs and experiments in "Techno-Orientalist" film and fiction. In our last few weeks, we will consider how "War on Terror" media and popular memoir fortified old Orientalist tropes and gave rise to new and unexpected ones. </span></p><br/><span style="font-size: 12pt">Readings will include short fiction by Jack London, Willa Cather, Ted Chiang, and Charles Yu; poetry by Walt Whitman, Edgar Allan Poe, Timothy Yu, </span><span style="font-size: 12pt">Larissa Lai, and Fatimah Asghar; and novels by Julie Otsuka and </span><span style="font-size: 12pt">Azar Nafisi. </span></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15315,2027,1380,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-365','<div class="desc"> <p>Topics may vary semester to semester.</p> <p><strong>The Refugee</strong></p> <p>This seminar will explore how refugees have portrayed themselves and have been portrayed in literature, memoir, testimony, film, and art. Our goal will be to appraise whether and how aesthetic attempts to capture the condition of refugees respond to and at times revise political discourses about those in exile. Among others, we will engage with the work of Hannah Arendt, Primo Levi, Giorgio Agamben, Edward Said, Gloria Anzaldua, W.G. Sebald, Mahmoud Darwish, Caryl Phillips, Ghassan Kanafani, and Viet Nguyen.</p> <p>Major Requirement Met: <strong>Group III/ IV</strong></p> <p><strong>The Global Novel</strong></p> <p>This course will focus on literature and theory produced in the aftermath of the British Empire. By 1914 the British Empire had colonized almost 25% of the world, bringing diverse cultural traditions under the encyclopedic gaze of Western modernity. If part of the aim of the colonial apparatus was to collect knowledge of the world in ways that bodies, cultures, and landscapes could be understood and ordered by the West, contemporary societies are now negotiating their own means of self-representation in the often-violent space of postcolonial rupture. Throughout the term, we will work with texts and visual images produced out of, and in response to, the history of the colonial encounter. Drawing on a broad range of literary, filmic, and theoretical materials we will develop strategies for understanding the production and consumption of postcolonial representation, in both local and global contexts. As consumers of these cultural products within the space of the Western academy, we will be attentive to the function of the stereotype as we consider representations of gender and sexuality, violence and terrorism, class structures, and migration.</p> <p>Major Requirement Met: <strong>Group III</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15316,2027,1229,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-370','<div class="desc"> <p>Topics vary. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Trauma and Literature</strong></p> <p>How is trauma narrated? Can literature convey intense personal and collective suffering? Is our understanding of pain cultural? This course considers psychoanalytic ideas of historical and personal trauma reflected in literary works of the modern period. Our study will be interdisciplinary, considering how powerful concepts in the hermeneutic of psychoanalysis (repression; repetition compulsion; abjection; misrecognition; lack; affect etc.) have been generated by literary works, as well as challenged and absorbed into them. Insofar as traumatic experience produces a subjective breach, we will think about how certain forms and styles of literature are more or less suited to reflect the rupture. </p> <p>We will read formative texts of psychoanalysis (Freud; Lacan; Kristeva; Foucault and others) and trauma theory (Caruth; Silverman; Fanon; Nandy). Our survey of literary works includes texts by Jean Rhys, Toni Morrison, Han Kang, Teju Cole, among others. Core Requirement: Global Connections.</p> <p>Major Requirement Met: <strong>Group III/IV</strong></p> </div>','One 100- or 200-level English course, or junior or senior standing ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15317,2027,1455,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-377','<div class="desc"> <p>This course interrogates the intellectual and artistic dimensions of the Afrofuturism movement. From the present day, going at least as far back as Phillis Wheatley''s poetry, one finds a robust exploration of black culture''s relationship to technology and futurity that diverges from Eurocentric standards of civilizational progress. The course will focus on literature and related genres, including music and film. Students will engage the work of Alondra Nelson, John Akomfrah, Sir Thomas More, Tracy K. Smith, Phillis Wheatley, Will Alexander, Evie Shockley, Sun Ra, Outkast, Octavia Butler, and others. </p> <p>Major requirement met: <strong>Group III or Group IV</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15318,2027,1381,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-380','<div class="desc"> <p>Our primary focus will be on fiction. Students will be required to respond thoughtfully and critically to assigned readings and to one another''s work. We will attend to general issues of craft, as well as to broader questions about the writing of fiction. Open only to juniors and seniors. May be repeated for credit.</p> </div>','ENGL 280 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15319,2027,3923,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-381','<div class="desc"> This course invites students to explore avant-garde and alternative prose practices to investigate the qualities of writing “without invention.” We will experiment with varied prose styles to tell stories that are activated by the recollections of our real lives. These new writings will emphasize journaling, lyric essay, hybrid memoir, autofiction, biomythography, and visual storytelling. We will encounter texts by contemporary writers who actively engage in personal and social worlds through the art of story, including Brontez Purnell, Eileen Myles, Anthony Veasna So, Audre Lorde, Alison Bechdel, Kayleb Rae Candrilli, and others. Students will have the opportunity to participate in author-focused workshops as part of developing their writing practices. </div>','One creative writing class. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15320,2027,1230,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-382','<div class="desc"> <p>The focus of this course is the writing of short fiction, though also where fiction might overlap with—and necessitate elements of—nonfiction, documentary, poetry. Students will build upon the foundations they established in prior writing workshops, while continuing to test the boundaries of their practice. Students will generate new work constantly— in sketchbooks, exercises, and story drafts—based on and inspired by readings, and especially their own preoccupations, curiosities, and experiences. We will read and discuss texts that both illuminate and complicate various formal possibilities, including by Etel Adnan, Jenny Boully, John Keene, Malika Mokeddem, Scholastique Mukasonga, Juan Rulfo, Sophia Terazawa, Jackie Wang, among others. And we will share and discuss our work in a workshop format. The discussions will be oriented towards asking questions, problem-solving, developing a generative relationship to revision, and towards challenging each other to go deeper into particular, perhaps unexpected, areas and aspects of our writing. Open to third- and fourth-year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15321,2027,1231,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-390','<div class="desc"> <p>The Junior Seminar is a small, discussion-oriented seminar required of all English majors, emphasizing advanced critical approaches to a literary topic. Enrollment is restricted to English majors who will pass the college''s Second-Stage Writing Requirement by satisfactory completion of the course writing requirements. Topics may vary year to year.</p> <p><strong>The Animal</strong></p> <p>This seminar will examine literary, filmic, and theoretical representations of the animal. Questions about the human as animal, and at the limit of animality, will be implicit in our discussion. Over the course of the semester, we will evaluate how the animal has been theorized and represented from the nineteenth century to the present. We will also consider the ways in which the animal has served as a cypher for exploring the category of the human. While the figure of the animal has provided a counterpoint to visions of humanity for centuries, emerging technologies and ideas about human consciousness have inflected the conversation in new and important ways. In what ways, for example, does contemporary technology compel us to reevaluate the distinctions between animal and human, on the one hand, and animal and object, on the other? The course will consider works such as Han Kang’s The Vegetarian, Werner Herzog’s Grizzly Man, Indra Sinha’s Animal’s People, and H.G. Wells The Island of Doctor Moreau.</p> <p><strong>Laughter and Non-Representation</strong></p> <p>While Aristotle is reputed to have written a treatise on comedy to match his famous discourse on tragedy, <em>The Poetics</em>, this is hard to believe as, in all his works, he shows almost no sense of humor. This first absence does not seem to have been filled in the many centuries that have followed. Both in number and quality, modern treatments of laughter seem inadequate. This weakness is perhaps because the funny is constitutively unavailable to rational representation. This class will explore laughter as exactly the embodied symptom that arises out of the intrinsic inadequacies of representation. After a quick critique of traditional theories of mimesis, we will explore the generation of laughter through various contemporary theories and attempt to understand its function for the liberation of the unrepresented in works thought funny, from Laurence Sterne to Ishmael Reed. Open only to junior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15322,2027,4014,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-393','<div class="desc"> <div> <p>Research in an area not otherwise included in the department curriculum. Permission of instructor required.</p> </div> </div>','Permission of the instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15323,2027,4220,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15324,2027,1597,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/300/engl-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15325,2027,1232,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/400/engl-490','<div class="desc"> <p>In this course, seniors will design and carry out advanced research projects in areas of their own interests. Seminar meetings will be devoted to discussion of a core group of theoretical and/or historical texts (varying from year to year), and to practical issues of sophisticated literary critical work. The course will result in a substantial critical paper, a version of which will be presented at the Spring Senior Symposium, in satisfaction of Occidental''s Comprehensive requirement. Open only to senior English majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15326,2027,4221,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/400/engl-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15327,2027,1598,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/engl-english/400/engl-499','<div class="desc"> <p>Research, writing, and defense of the Honors thesis in English. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15328,2027,4222,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/copy-of-fren-193','<div class="desc"> <div><p>Intensive study in an area of French/Francophone literary analysis and cultural studies under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15329,2027,165,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/fren-101','<div class="desc"> <p>Introduction to French through a variety of communicative approaches. Emphasis is placed on speaking and listening, as well as grammar and writing. Students who have had more than one year of French in high school, or more than one quarter in college, may not take this course for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15330,2027,166,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/fren-102','<div class="desc"> <p>This course is a continuation of FREN 101. Students are introduced to the culture of the French-speaking world through readings and discussions.</p> </div>','FREN 101 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15331,2027,167,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/fren-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15332,2027,580,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/fren-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. Graded on Credit/No Credit basis only. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15333,2027,4223,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/fren-195','<div class="desc"> <p>Topics vary semester to semester. May be repeated once for credit when taken with a different topic. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15334,2027,581,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/100/fren-197','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15335,2027,169,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/copy-of-fren-251','<div class="desc"> <div><div><p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. Graded on Credit/No Credit basis only.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15336,2027,583,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/copy-of-fren-252','<div class="desc"> <div><p>Oral practice in an informal setting; includes at least one viewing of a French feature film. Usually taught by a French language assistant from France, under the supervision of a French professor. Open to students who have completed FREN 102, as well as to those on a more advanced level. Students enroll in FREN 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. Graded on Credit/No Credit basis only.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15337,2027,4224,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/copy-of-fren-293','<div class="desc"> <div><p>Intensive study in an area of French/Francophone literary analysis and cultural studies under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15338,2027,168,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/fren-201','<div class="desc"> <p>This course develops students'' speaking, listening, and writing skills in French, with a focus on intermediate grammar. Students read texts and are exposed to artistic work through a transnational lens to interpret 20th-century cultural history and contemporary literary, artistic, and social issues in various French-speaking regions of the world. Students are strongly encouraged also to enroll in FREN 151 / FREN 152 Intermediate Conversation.</p> </div>','FREN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15339,2027,582,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/fren-202','<div class="desc"> <p>The methods and vocabulary of textual analysis introduced through close reading, discussion, and written commentary of selected poems, plays, and prose texts, from the Renaissance to the present. The techniques of French critical writing, oral explication de texte, and commentaire composÃ© will be stressed. Includes study of general linguistic problems pertaining to the structure of modern French (vocabulary, phonetics, grammar style). This course is required of all French majors and minors and for students wishing to study abroad in the French-speaking world. Students are strongly encouraged also to enroll in FREN 251 / FREN 252 Advanced Conversation.</p> </div>','FREN 201 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15340,2027,4225,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/fren-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15341,2027,4226,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/200/fren-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15342,2027,4008,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/copy-of-fren-393','<div class="desc"> <div><div><p>Intensive study in an area of French/Francophone literary analysis and cultural studies under the direct supervision of a member of the faculty. Permission of instructor required.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15343,2027,842,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-301','<div class="desc"> <p>An introduction to late 20th-century Francophone literary works (short stories, a novel, poetry) and films, from the Levant (Lebanon, Syria) and North Africa (Egypt, Tunisia, Algeria, and Morocco). The course underlines the diversity of this part of the world, the various ways in which French is used, and its relation to the native tongue-Arabic. The Arab Spring and questions of cultural/national identity are also examined. Among authors studied are Tahar Ben Jelloun (Morocco) and Lamia Ziadé.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15344,2027,843,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-350','<div class="desc"> <p>An introduction to the theory and practice of translation from English to French ("thème"), and French to English ("version"), as both a craft and an art, with its codes and principles. Although emphasis is placed on practice, the course examines important theoretical questions, such as translation as both a product and as a process. With some attention to the difference between "literal" and "free" translation, the course explores the lexical and semantic strategies that translators employ. The course begins with the smallest "unit of translation," and progresses to consider a wide variety of texts: fiction; poetry (song lyrics); advertisements, televisual and filmic. Students may choose to translate a business, technical, legal, medical, or literary text as part of their final project.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15345,2027,4030,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-354','<div class="desc"> <p>This course is an introduction to Renaissance and seventeenth-century French literature through the theme of âthe self that desires.â We will explore the expression of female desire in women Renaissance poets including Louise LabÃ© and Pernette du Guillet in the context of French Neoplatonism. We will consider MoliÃ¨reâs critiques of hypocritical desires of seventeenth-century French society. We will also analyze plays by Jean Racine, where the self with âinner conflictâ of desires is staged. Through these and other works, we will examine what shapes the âselfâ in this time period, what sorts of selves are expressed in the literature, and what selves are enacted through the desiring literary text.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15346,2027,170,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-355','<div class="desc"> <p>Readings and discussion in the French novel and philosophical texts, including works by Prévost, Diderot, Rousseau, Bernardin, de Saint-Pierre, Balzac, Stendhal, Flaubert, and Zola.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15347,2027,4416,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-356','<div class="desc"> <p><span style="color: rgba(34, 34, 34, 1); font-family: Arial, Helvetica, sans-serif; font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0; text-transform: none; widows: 2; word-spacing: 0; white-space: normal; background-color: rgba(255, 255, 255, 1); text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none">This course plays on the double meaning of the French word </span><i style="color: rgba(34, 34, 34, 1); font-family: Arial, Helvetica, sans-serif; font-size: small; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0; text-transform: none; widows: 2; word-spacing: 0; white-space: normal; background-color: rgba(255, 255, 255, 1); text-decoration-style: initial; text-decoration-color: initial">expÃ©rience</i><span style="color: rgba(34, 34, 34, 1); font-family: Arial, Helvetica, sans-serif; font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0; text-transform: none; widows: 2; word-spacing: 0; white-space: normal; background-color: rgba(255, 255, 255, 1); text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none"> to mean both âexperienceâ and âexperimentâ in English. We will analyze 20th century French and Francophone works that reimagine the experience of literary texts through their experimental form. We will examine how these literary texts create experiences/experiments that challenge ideas and ideals that developed in the 19th century, including consumerism, traditional bourgeois values, colonial and gender power dynamics, linguistic colonialism, and the very notion of reason and progress. We will read works by authors including Boris Vian, Georges Perec, Marguerite Duras, and AimÃ© CÃ©saire.</span></p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15348,2027,1070,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-363','<div class="desc"> <p>The course is an exploration of various literary and cinematic representations of the French colonial history and its impact on the peoples of the Maghreb and West Africa. It examines narratives of war, dominion, racism, and collaboration. Films and literary texts examined include: <em>Les Indigènes </em>(Rachid Bouchareb); <em>Le Camp de Thiaroye</em> (Ousmene Sembene); <em>Le Vieux Nègre et la Médaille </em>(Ferdinand Oyono); and <em>Meursault, contre-enquête</em> (Kamel Daoud).</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15349,2027,1016,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-365','<div class="desc"> <p><strong>French Feminism</strong></p> <p>Psychological and political views of the "disruptive" female presence in literature, and in the critical theory of Derrida and Lacan. Works will range from 17th century fiction, to feminist writers including Beauvoir, Irigaray, and Cixous, as well as examples of women''s self-writing in the Francophone world. Taught in French and English.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15350,2027,2443,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-370','<div class="desc"> <p>This course explores the history and development of one literary genre (fiction, poetry, theater, or cinema) across different periods and in different French-speaking communities. Content varies from year to year.</p> <p style="margin-left:0in; margin-right:0in"><strong>Francophone voices of Africa and the Caribbean</strong></p> <p style="margin-left:0in; margin-right:0in">This course traces the development of literature in French by writers living in or originating from France’s former colonies, primarily the Caribbean and Sub-Saharan Africa. Through short stories, novels, and the <em>bande dessinée</em>, we will examine key intellectual, political, and social movements that have shaped, and continue to shape, Francophone postcolonial identities. We will consider themes such as decolonization, Negritude, tradition vs modernity, immigration and exile, and hybrid/Afroeuropean identities. Texts will include works by Aimé Césaire, Edouard Glissant, Maryse Condé, Mariama Bâ, and Alain Mabanckou. Additional Core Requirement Met: Global Connections.</p> </div>','FREN 202 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15351,2027,4227,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15352,2027,585,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/300/fren-397','<div class="desc"> <p>Individual study of a major author, movement, or genre; or the teaching of French. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15353,2027,4009,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/400/fren-493','<div class="desc"> <p>Comprehensive-level work in an area of French/Francophone literary analysis and cultural studies under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>When taken as a 4-unit course, you should expect to spend at least twelve (12) hours a week on this course. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15354,2027,4228,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/400/fren-497','<div class="desc"> <p>Individual study of a major author, movement, or genre; or the teaching of French. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15355,2027,4438,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/400/fren-498','<div class="desc"> <p>Extended comprehensive-level work in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15356,2027,587,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fren-french/400/fren-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15357,2027,2958,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-1','<div class="desc"> <p>Are we ready for the Big One? How have water issues shaped the growth of California? Where has our energy come from and where will we get it from in the future? And can we move towards a more sustainable future? In this seminar, we will explore societally-relevant issues. Topics will include earthquakes, water, and issues related to energy and climate. These topics will then be expanded upon with scientific focus in the Geology 105 course. Open only to first-year frosh.</p> <p><em>Life on the Edge</em> is a special program that consists of two connected courses that will give students the opportunity to explore environmental and geological issues with a special focus on southern California. Students will get to go on a weekend-long trip to Joshua Tree National Park to get hands-on experience exploring the natural environment. </p> <p>Students who participate in this 8-unit program will take both a First Year Seminar and one of Oxy''s most in-demand science courses:</p> <ul> <li>FYS 1: Life on the Edge: How Geology Shapes Our Lives in Los Angeles and Its Environs (4 units)</li> <li>GEO 105: Earth Our Environment (4 units)</li> </ul> <p>By participating in this program, you''ll fulfill both your Fall FYS and also the Core Labs Science requirements. </p> </div>',NULL,'GEO 105',NULL);
INSERT INTO course_descriptions VALUES(15358,2027,2966,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-10','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">This course introduces three theoretical perspectives on sexuality: biological, psychological, and social construction. With these perspectives in mind, we address pressing topics involving sex-prostitution/sex work, abortion, pornography, and sexual violence.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15359,2027,2967,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-11','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Building on traditions of resistance established under chattel slavery, freedpeople struggled to make freedom a reality along many dimensions, including bodily sovereignty, land, labor, intimate relations, family integrity, education, legal rights, and citizenship. In this class, we will immerse ourselves in primary historical documents—including letters, military reports, petitions, and newspapers—seeking to understand how African Americans pursued their visions of freedom from wartime through Reconstruction.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15360,2027,2968,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-12','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Comic books were once considered an intellectual and moral threat to young people. Today, “graphic narrative" is a celebrated and lucrative medium supported by a mainstream apparatus of publication and criticism. We will study the history of this hybrid, word-and-picture medium, in the United States from its origins as disposable children''s fare to its current array of serious adult genres: novels and short stories, memoir, documentary journalism, and biography. For comparison, some attention may be given to foreign texts in translation. This course should be particularly attractive to students interested in the creative arts and humanities, but the variety of texts and topics should appeal to students with broad topical interests in 20th-century U.S. history and culture.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15361,2027,2969,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-13','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Mariame Kaba, an anti-violence activist and advocate of abolishing prisons and policing, has said, "As a society, we have been so indoctrinated with the idea that we solve problems by policing and caging people that many cannot imagine anything other than prisons and the police as solutions to violence and harm." This course revolves around Kaba''s insight. To imagine a freer and more just world, we begin by discussing concepts of freedom. Then we use these concepts to discuss the many ways that those in the prison system are denied freedom, as well as the ways that people are manipulated toward complicity in an unjust status quo, even sometimes in our own oppression. Then we will examine how certain social movements have developed practices to resist social and political coercion, with special focus on how their work enables us to discuss and imagine more freely. </span>Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15362,2027,3265,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-14','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">In this seminar, we will learn how the mathematics of chaos helps us to better understand science, economics, psychology, and our environment. </span>Open only to first-year frosh.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15363,2027,2971,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-15','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Arabs and Muslims are exceptional figures in the American imagination. A "bad" Muslim is exceptionally religious, violent, conservative, and anti-democratic. Conversely, a "good" Muslim can only be an exceptional one. This course will introduce students to approaches in religious studies, ethnic studies, and critical race theory toward a critical examination of Islamophobia and anti-Arab racism in the US. We will ask: How do race, religion, and ethnicity interact to produce exceptional stereotypes about Arabs and Muslims? How are non-Arab Muslims racialized as Arabs and non-Muslim Arabs as Muslims? How does such racialization foster a culture of suspicion and normalize practices of surveillance against Arabs and Muslims? How do efforts to combat Islamophobia as a form of religious prejudice end up obscuring anti-Muslim racism? Finally, how do we make sense of exceptions to free speech, international law, human rights, academic freedom, and diversity, equity, and inclusion (DEI) that undermine the rights and human dignity of Arabs and Muslims?</span> Open only to first-year frosh.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15364,2027,2972,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-16','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">This course interrogates the relationship between religion and violence. Through a survey of the scholarship on religion and violence and a series of focused studies on 9/11 and the "revolutionary suicide" at Jonestown, this course will offer an overview of religion and violence in the Americas. Using these case studies, we will ask a series of analytical questions: What is violence? Can religions motivate violence, or do they merely sanctify it? And what are the sources of religious authority (such as leaders, scripture, tradition, and ritual practice) that can militate for or against violence? And what kinds of speech and action are properly understood as "violent"?</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15365,2027,3266,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-17','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;">Beginning in England over 150 years ago, association football, commonly known as soccer in the United States, has evolved from a working-class tradition to a multi-billion dollar global industry. Argentina''s World Cup final victory over France in 2022 had a global audience of roughly 1.5 billion people, making it a far larger event than the 2022 NFL Super Bowl''s audience of roughly 115 million. Passion for the game connects fans in the legendary arenas of Wembley Stadium (England), Estadio Azteca (Mexico), and Maracana Stadium (Brazil) among others, to the suburban fields of the United States, and makeshift pitches across the globe. Given its ubiquity, with possibilities to watch the game on television 24/7, not to mention on the small screen of everyone''s smartphone, one wonders, how can soccer be used as a prism for learning about society? </span>Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15366,2027,3267,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-18','<div class="desc"> <p class="sc-BodyText"><span style="background-color: #ffffff; color: #0c0c0c;">Norman Mailer described Los Angeles as a “constellation of plastic.” John Fante called it a “sad flower in the sand.” Is Los Angeles really just “72 suburbs in search of a city,” as Dorothy Parker claimed, or is there something else brewing beneath the beautiful, sunny skies? We’ll explore (primarily through films and literary texts) 20 th and 21 st century Los Angeles as both a real and imagined location. Through the completion of three papers, a self-directed field trip and other activities, you’ll craft your own conceptual “map” of the place. Please note that some of the literary and film texts for this course may be disturbing. Contact the instructor if you have any questions.</span> Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15367,2027,2973,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-19','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">A foundational principle of the modern world is that, in large part, we make it for ourselves. This happens in a variety of ways that we usually consider within the confines of philosophy, politics, and law. But storytelling appears as an equally powerful force, with its unique ability to give complex insight on a given social moment, along with its persuasive ability to unsettle accepted norms and imagine radical alternatives. In this case, our seminar will look at a variety of ways in which narrative has emerged as a specific vehicle for social criticism, as it develops specialized techniques to challenge social arrangements and effectively imagine alternatives. This seminar will look closely at a variety of such efforts at criticism and reimagining, considering literary approaches to rationality, conflict, empathy, and perspective, and working through such diverse movements as romanticism, realism, modernism, and postmodernism.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15368,2027,3264,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-2','<div class="desc"> <p>"Technology" is often thought of as being neutral and at its best providing solutions to problems without human bias. Despite this, contemporary developments in predictive policing and algorithmic racism, to give only two prominent examples, suggest that this is not the case. In Social Difference and the Politics of Technology we will discuss contemporary issues like AI, automation, and environmental technologies, and a longer history of technology dating to plantation slavery and European colonialism. The course will ask students to think about the ways that technological development has never been neutral and has always been connected to histories of race, gender, sexuality, and hierarchical conceptions of what it means to be human, as well as economics and labor, and ecological issues. In doing so we will look at a wide array of texts and media to examine these histories, to imagine worlds otherwise to them, and as a foundation for developing writing skills in order to ethically engage with technological change on an increasingly unequal and unstable planet. Open only to first-year frosh.</p> <p>The Computing IRL ("In Real Life") immersive program consists of a connected set of courses in which students will see how computing techniques and ideas inform and are informed by their interaction with the real world. Student who participate in this 12-unit program will take three connected courses:</p> <p>FYS 2: Social Difference and the Politics of Technology (4 units)</p> <ul style="list-style-type: disc;"> <li>COMP 131: Fundamentals of Computer Science (4 units)</li> <li>COMP 295: Computing IRL Internship (4 units)</li> </ul> <p>By participating in this program, you will fulfill your Fall FYS and Core Lab Science requirements.</p> </div>',NULL,'Linked with COMP 131 and COMP 295 (Computing IRL Internship)',NULL);
INSERT INTO course_descriptions VALUES(15369,2027,2974,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-20','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">While the term "romance novel" today often calls to mind tawdry love stories featuring heaving bosoms and uncontrollable passions, the genre of romance is much more complex than these stereotypes would make it seem. Early examples of romance are sprawling adventure narratives of chivalry, crusades, the supernatural, and yes, occasionally even love. Today, these tales have evolved into the modern day romance novel - a genre known for celebrating love, but which also often questions gender, sexuality, family and friend relationships, and professional success. In this course we will explore the genealogy of romance, asking not only what constitutes a romance, but also what the continuously popular genre can teach us about readers'' desires and discontents across history. </span>Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15370,2027,2975,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-21','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Music lovers of all genres, styles, and eras, unite and take over! In this course we will explore different ways to write critically and powerfully about music. Students will learn how to engage and guide readers’ ears, hearts, and minds by entering current cultural conversations, responding to provocative critical assessments, and championing work that has been overlooked by the public and/or the critics. By reading and discussing some of the greatest music writers from the past few decades, students will learn how to incorporate technical terms and socio-historical context into their arguments while sharpening the sensitivity of their own observations and honing the quality of their own personal voices. We will also consider other music-related topics such as the effects of technology (streaming, generative AI), the value of print media (album artwork, zines), the impact of local college radio stations (KOXY, KXLU), and more.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15371,2027,2976,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-22','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Broadway musicals are paradoxical. For all their quality, popularity, and variety, musicals have been historically disparaged as escapist entertainment: romantic and/or comedic romps that are, for the most part, thematically light and spectacle-oriented. And then Hamilton, right? Not so fast. Singing and dancing theater artists have dramatized hard-hitting social dynamics throughout the history of the form. This course will explore the development of the distinctly "political" stage musical. Offerings will track its rise throughout the 20th century (in shows such as Showboat, Cradle Will Rock and Hair), to contemporary productions that tackle a variety of issues through a decidedly intersectional lens (like Caroline, Or Change and Passing Strange). Our inquiries will also address representation and access. For all of the evolution of the genre, musicals are out of reach for many, on stage and off. How can an essentially elite art form have meaningful resonance and impact?</span> <span style="background-color: #ffffff; color: #0c0c0c;">Open only to first-year frosh.</span></span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15372,2027,2977,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-23','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">This course will examine modes of and moral groundings for social and political resistance — ranging from highly organized revolutionary movements to distributed, asymmetrical and covert actions. We will also attend to the role of new digital technologies — from social media to AI, drones and other robotic weapons. The examples and sites we will study will be global but with special attention to the Middle East and North Africa.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15373,2027,3268,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-24','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">In this course, students will be asked to think critically about the form and content of what is known as "the campus novel," or a work of fiction that takes place on, or is centered around, student life on a university or college campus. Specifically, students will join the ongoing conversations that focus on campus novels that are set in fictional — or perhaps fictionalized — small liberal arts college (SLAC) campuses. Authors may include, but are not limited to, Donna Tartt, Don Lee, Elisabeth Thomas and Mona Awad. By analyzing creative narratives of student lives at SLACs, alongside academic scholarship on higher education in the United States, this first year seminar will invite participants to think deeply about their own desires and demands from Occidental College, and from a liberal arts education writ large. </span>Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15374,2027,3269,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-25','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">In this course, we will explore the microbial world. Bacteria, archaea, and fungi are the most dominant forms of life on Earth, and they play an enormous role in shaping and sustaining our planet. In fact, only a very tiny fraction of them do us harm. Scientific breakthroughs have uncovered a breathtaking diversity of microbes in environments ranging from compost to arctic ice, underwater volcanoes to leaf surfaces, and within the bodies of animals, from aphids to humans. Together, we will put Los Angeles under the microscope and develop an appreciation for the necessity of microbes by looking at how they evolved, how they function, and their impacts on human society.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15375,2027,2980,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-27','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Even though we do it every day, recognizing a face isn’t as easy as it seems. Different hairstyles or a sideways angle fooled our best algorithms for decades. Using principles from the human brain, artificial neural networks can now recognize faces, write stories, and even create art. Some believe these algorithms have even passed our benchmark for evaluating whether a machine possesses human-like intelligence, the classic “Turing test”. Students in this course will understand how the human brain inspired these algorithms by reading neuroscience literature, philosophy of mind literature, and implementing code. With these tools, students will explore how these algorithms shed light on, and challenge, what it means to be human. No experience is required to succeed in this course but a strong interest in cognitive science, computer science, philosophy, mathematics and/or statistics will be beneficial. </span>Open only to first-year frosh.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15376,2027,2981,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-28','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">This course explores Latinx popular culture as both a site of creative expression and a battleground for power, gender, and representation. Through music, television, film, memes, fashion, and digital platforms, we’ll examine how Latinx communities in the U.S. have navigated, resisted, and redefined dominant narratives about race, gender, class, and nation. We’ll dive into the politics of Spanglish, the symbolic resonance of La Virgen de Guadalupe, diasporic aesthetics, and the role of pop culture in shaping identity, community, and protest. Drawing on frameworks from Chicana feminism, queer theory, Afro-Latinx critique, and cultural studies, we’ll interrogate questions of visibility, voice, and authenticity. Through critical readings, multimedia analysis, and hands-on creative projects, students will sharpen media literacy skills that enable critical consumption and production of cultural content.</span> Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15377,2027,2959,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-3','<div class="desc"> <p style="color: #0c0c0c; background-color: #ffffff; margin-bottom: 15px;">"Technology" is often thought of as being neutral and at its best providing solutions to problems without human bias. Despite this, contemporary developments in predictive policing and algorithmic racism, to give only two prominent examples, suggest that this is not the case. In Social Difference and the Politics of Technology we will discuss contemporary issues like AI, automation, and environmental technologies, and a longer history of technology dating to plantation slavery and European colonialism. The course will ask students to think about the ways that technological development has never been neutral and has always been connected to histories of race, gender, sexuality, and hierarchical conceptions of what it means to be human, as well as economics and labor, and ecological issues. In doing so we will look at a wide array of texts and media to examine these histories, to imagine worlds otherwise to them, and as a foundation for developing writing skills in order to ethically engage with technological change on an increasingly unequal and unstable planet. Open only to first year frosh.</p> <p style="color: #0c0c0c; background-color: #ffffff; margin-top: 0px; margin-bottom: 15px;"><em>Note: </em>FYS 2 and FYS 3 have the same topic and instructor. While FYS 2 is only available to students participating in the Computing IRL program, FYS 3 is open to all first-year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15378,2027,2960,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-4','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;">This course is essentially an introductory course in cultural anthropology. Cultural anthropology emerged within the past two centuries as a means of coming to grips with the diversity of ways of being human. While cultural anthropology’s history has been tainted by collusion with racist and imperialist programs, it remains the single loudest academic voice on behalf of indigenous peoples around the world. In this course, we will look at a part of the world—New Ireland, Papua New Guinea—that is different, in many respects, from the WEIRD (Western, Educated, Industrialized, Rich, Democratic) societies from which most, if not all, of the students in this class come. We will discover that non-WEIRD societies have a logic to their ways of being and relating, and that sometimes, WEIRD ways of doing things are, well, weird. This is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course. </span>Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15379,2027,2961,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-5','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">This course offers a survey of German film from the origins of cinema to the present day. We will focus on questions pertaining to how one can interpret or “read” a film, as well as the relation of German film to contemporaneous developments in art, literature and politics. How is the authoritarianism of the early 20th century depicted and/or confronted in film? What do horror films tell us about the anxieties and prejudices of the societies that produced and consumed them? Throughout the course, we will investigate the ways in which the dilemmas and aspirations of the modern world became legible in film, and ask to what extent film is a medium uniquely suited for depicting and attempting to understand modernity’s paradoxes. </span>Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15380,2027,2962,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-6','<div class="desc"> <p><span style="background-color: #ffffff; color: #0c0c0c;">More than simply a "god of wine," Dionysus was for the Ancient Greeks a god of ecstatic self-abandon, of gushing fertility, of violent dismemberment and unexpected rebirth. In myth he was attended by raving Maenads and mischievous Satyrs; amongst humans he was worshiped with festive dances, communal shouts, ritual obscenities, and (perhaps most importantly) with poetry-with the literary genres of ode, comedy and tragedy that were invented specifically to honor him. What could be farther, we might ask, from the cool, reasonable practice of philosophy than this wild, uncanny, irrational god? And yet, as we shall see in this class, this reckless god of madness and poetry stands at the foundation of some of the most important ideas in modern philosophy-Hegel''s phenomenology of spirit, Nietzsche''s will to power, Heidegger''s philosophy of Existenz, Bataille''s notion of excess, and Derrida''s "non-concept" of différance. Beginning with an exploration of Dionysian poetics in Ancient Greece, this course will attempt to show what thinkers like these found so inspiring in this ancient god, and what the writers and thinkers of our own time might yet find in him still. </span>Open only to first year frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15381,2027,2963,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-7','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">This course will examine the diverse ways that Asians conceptualize and engage in romantic and sexual relationships in ways that complicate the hegemonic Western stereotype of Asian men as emasculated and Asian women as hypersexualized. For example, we will examine the sex tourism and sex work industry in different parts of Asia. We will comparatively examine the stories of Asian marriage migrants. Furthermore, we will examine how queer Asians conceptualize their queerness in relation to the hegemonic white Western queer identities. In addition to academic journal articles and books, materials we will cover throughout the course will include various forms of popular cultural contents ranging from magazine articles, photographs, and films, to music videos, and social media posts. </span>Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15382,2027,2964,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-8','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">Why are the senses important? They are our means of experiencing the physical world. We are born to see, hear, touch, taste, and smell, through which we perceive, experience, and make sense of our surroundings. This course explores the vital role of the senses in human experience and their representation in Chinese literature. Through various genres and historical periods, we will examine how sight, hearing, touch, taste, and smell are depicted in literary works. By analyzing these sensory descriptions, we will uncover how authors’ philosophical views, aesthetic preferences, and personal interests influence their ways of writing about sensory experiences. The course emphasizes that our sensory experiences are both collective and individual, highlighting the diverse ways in which we perceive and interpret the world around us.</span> Open only to first year frosh. </span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15383,2027,2965,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/fys-first-year-seminar/fys-9','<div class="desc"> <span style="background-color: #ffffff; color: #0c0c0c;"><span style="background-color: #ffffff; color: #0c0c0c;">In this class, we will learn to read poems. We will practice the slow reading that poems require. Most specimens of writing we encounter in daily life admit of fast reading. This is because these specimens of writing are not meant to draw attention to their language but to the stuff in the world that their language is about. News stories, Tweets, texts, social media posts, advertisements, and so on are typically instances of language use that are meant to inform you of things out there in the world beyond the language itself. Poems, in contrast, amount to uses of language that draw our attention to themselves. Metaphor, simile, alliteration, rhyme, word patterns, rhythm, meter, and so on are the very stuff of poetry. This is not to say that poems cannot also be about stuff. They can. But what is typically most important in poems is the way—the linguistic, verbal, wordy way—that they are about the stuff that they are about, rather than the stuff itself. In this class we will attend not only to the stuff poems are about but also to how they use their language to be about that stuff. In other words, we will learn to read poems. </span>Open only to first-year frosh.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15384,2027,171,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/100/geo-105','<div class="desc"> <p>Introduction to Geology with emphasis on the physical processes that shape the environment on the Earth''s surface. The course will cover the fundamentals of plate tectonics, rocks, minerals, geologic time, surface processes, and Earth''s interior. Special attention will be paid to geologic hazards (such as earthquakes, volcanoes, floods, and landslides), the history and future of global climate change, and the human impact on the environment. <em>Includes one two-hour laboratory per week and a one- or two-day field trip.</em> Students who have completed a substantive introductory Geology course are encouraged to seek permission of the instructor to enroll in any of the 200-level Geology courses.Open only to first- and second-year students.</p> </div>',NULL,'GEO 105L ',NULL);
INSERT INTO course_descriptions VALUES(15385,2027,1457,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/100/geo-106','<div class="desc"> <p>Nature and humanity interact with and impact one another in complex and significant ways. Human health, safety, and economic well-being are significantly impacted by natural processes, providing both opportunities and constraints on sustainability. This course focuses on these interactions as studied by earth scientists. Topics include: Earth surface properties and processes, air quality, mineral and energy resources/reserves for industrialized society, water resources, hazardous earth processes, and development and degradation of soils and climate. Labs will include using problem-solving skills and case studies. <em>Includes one two-hour laboratory per week and a one-day field trip.</em></p> </div>',NULL,'GEO 106L ',NULL);
INSERT INTO course_descriptions VALUES(15386,2027,4229,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/100/geo-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15387,2027,844,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/copy-of-geo-245','<div class="desc"> <p>An introduction to Earth''s climate system and the geological record of its change. Topics covered include: Earth''s radiative balance and the role of greenhouse gases, poleward transport of heat by the atmosphere and ocean, climate change on the plate tectonic timescale, the Cenozoic cooling, astronomical control of Pleistocene glacial cycles, rapid millennial-scale climate change, and the future of Earth''s climate. <em>Includes one three-hour laboratory per week.</em></p> </div>','GEO 105 ','GEO 245L ',NULL);
INSERT INTO course_descriptions VALUES(15388,2027,3360,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-210','<div class="desc"> <p><strong>This course will explore the physical principles, processes, and dynamics of the water cycle, including how and where water is transformed and transported around the planet. Topics will include the distribution of water on Earth, the main components of the hydrologic cycle (e.g. the storage and exchange of water phases between ocean, land, and atmosphere), and extreme weather and climate phenomena such as atmospheric rivers, floods, monsoons, hurricanes, and drought. The profound impacts of climate change and a growing human population on the hydrologic cycle and water resources on global and regional scales, especially in California, will be emphasized.</strong></p> </div>','GEO 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15389,2027,591,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-215','<div class="desc"> <p>This course offers an in-depth highlight reel of the history of the Earth and life upon it, from the origin of the planet 4.6 billion years ago to the present. The course focuses on the chemical, physical, and biological processes that have affected the planet''s interior and surface, including the atmosphere, hydrosphere, and lithosphere, through time. The formation and evolution of the North American continent and its spectacular geology is a particular focus! <em>Includes one multi-day field trip.</em></p><p><br/></p><p><br/></p> </div>','GEO 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15390,2027,2883,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-220','<div class="desc"> <p>The fundamentals of rock formation are explored through study of common rock-forming minerals and major rock types. Understanding of these processes is based on the physical, optical, chemical, and textural properties of minerals and rocks. The course includes a field trip to investigate rocks and minerals in some of California''s most interesting natural settings. <em>One three-hour laboratory per week and field trip.</em></p> </div>','GEO 105 or GEO 106 ','GEO 220L ',NULL);
INSERT INTO course_descriptions VALUES(15391,2027,173,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-225','<div class="desc"> <p>Southern Californiaâs spectacular geology is the natural laboratory for this project-based course. Working collaboratively, students will investigate geologic questions through fieldwork in the nearby deserts and mountains. The course will expand upon geologic knowledge from introductory geology classes and introduce students to the scientific processes and techniques geologists employ to understand the Earth and other planets. Special emphasis will be placed upon systematic field data collection using mobile GIS-based systems and communication of scientific results. The course will provide students from any major the opportunity to explore our local natural setting and actively participate in scientific inquiry. No experience beyond GEO 105 is expected of participants and all equipment will be provided. </p> </div>','GEO 105 ','GEO 225L ',NULL);
INSERT INTO course_descriptions VALUES(15392,2027,3879,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-230','<div class="desc"> <p>This course will examine the physical and chemical process associated with geologic hazards such as volcanism, earthquakes, and floods that have profoundly impacted civilizations globally and throughout human history. Southern California offers many excellent examples of geologic hazards that will inform our study. The course will include in-field examinations of local examples as well as evaluation of datasets associated with well-documented case studies of geologic hazards locally, in the western US, and around the world. Prerequisite: Geology 105</p> </div>','Geology 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15393,2027,593,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-235','<div class="desc"> <div><p>An introduction to the motion of tectonic plates and internal structure of the Earth. Topics include: geology of plate boundaries, techniques for describing plate motions, earthquakes and seismology, reversals of the Earth''s magnetic field, the nature of the seafloor, and the geology of mountain belts. </p></div> </div>','GEO 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15394,2027,595,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-255','<div class="desc"> <p>This project-based course will delve into scientific questions in earth, environmental, and ecological sciences using digital data on a variety of scales, from our backyard to the globe. By investigating problems such as the timing of earthquakes on the San Andreas fault, sources of contaminants in steam water, geologic controls on plant growth, and potential effects of volcanic eruptions, students will deepen their knowledge of geologic processes and develop analytical abilities that are a foundation of scientific inquiry. Course material will focus on topics to be investigated in laboratory projects using digital tools such as geographic information systems, Excel, and Google Earth. </p> </div>','GEO 105 or GEO 106 ','GEO 255L ',NULL);
INSERT INTO course_descriptions VALUES(15395,2027,4230,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-295','<div class="desc"> <p>Topics vary semester to semester.</p> </div>','GEO 105 and GEO 106 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15396,2027,4231,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/200/geo-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15397,2027,597,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/copy-of-geo-325','<div class="desc"> <p>Study of the deformation of rocks and the structures produced. Rock mechanics are introduced and the nature and origin of folds, faults, and other structures are discussed, along with the relation of structures to tectonic settings. Course includes interpretation of areas displaying complex geological relations that illustrate structural principles. <em>Includes field trips and one three-hour laboratory per week.</em></p> </div>','GEO 225 and one additional 200-level Geology course ','GEO 325L ',NULL);
INSERT INTO course_descriptions VALUES(15398,2027,938,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/copy-of-geo-342','<div class="desc"> <p>Landforms and their interpretation in terms of tectonic and climatic processes will be presented. The focus will be on landforms such as: mountain belts, faults, and landslides caused by active tectonic processes. Methods of dating and quantifying geologic events will be introduced. Scientific writing skills will be emphasized. <em>Includes one three-hour laboratory per week and field trip.</em></p> </div>','GEO 225 and one additional 200-level Geology course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15399,2027,939,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/copy-of-geo-345','<div class="desc"> <p>This course is a systematic exploration of the important minerals and rocks that comprise the solid earth. Course work will focus on the materials and processes involved in the formation of igneous and metamorphic rocks globally and seen in spectacular local examples. Students will engage in the study of rocks and minerals through analysis of specimens, microscopy, experimental and geochemical datasets, and fieldwork.</p> </div>','GEO 225 and one additional 200-level Geology course ','GEO 345L - Mineralogy and Petrology ',NULL);
INSERT INTO course_descriptions VALUES(15400,2027,3840,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/copy-of-geo-380','<div class="desc"> <p>Integrative topics in geology is a rotating suite of courses in which geologic concepts are examined primarily through application of geochemistry, data structures, or geophysics. The course may count toward the major as a supplemental course OR an upper division elective. If taken more than once, the second course will count as an upper-division elective in Geology.</p> <p><strong>Environmental Geochemistry</strong></p> <p>Low-temperature geochemical techniques are used to understand the global and local circulation of water from the atmosphere through rocks and into groundwater. In this course we will learn how stable isotope and trace elements help define the transport of water, metals, and carbon under changing climate and land-use conditions. Labs will give students an opportunity to apply geochemical tools to a variety of real world settings, using data from the Rocky Mountain headwater catchments to the karst aquifers in central Texas. A final collaborative class project will provide students the unique opportunity to sample, prepare, analyze, and interpret their own stable isotope data using a Picarro instrument in Dr. Sekhonâs laboratory</p> </div>','GEO105, GEO 245 and one additional 200-level Geology course ','Must also enroll in GEO 380L ',NULL);
INSERT INTO course_descriptions VALUES(15401,2027,1334,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-315','<div class="desc"> <p>Study of the processes of sedimentation, the properties of sedimentary rocks, and the use of stratified sedimentary sequences for correlation, dating, and interpretation of depositional environments and geologic history. Course includes field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>','GEO 105 , GEO 225 and one additional 200-level Geology course ','GEO 315L ',NULL);
INSERT INTO course_descriptions VALUES(15402,2027,1335,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-315l','<div class="desc"> <p>Field trips to classic localities throughout Southern California. <em>One three-hour laboratory per week.</em></p> </div>',NULL,'GEO 315',NULL);
INSERT INTO course_descriptions VALUES(15403,2027,1336,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-324','<div class="desc"> <p>Building on material learned in GEO 220 and GEO 225, this course involves the mapping of more complex areas. Fieldwork is the heart of this course and full participation in the 4-6 days of fieldwork is required. May be taken twice for credit.</p> </div>','GEO 225 and one additional 200-level Geology course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15404,2027,598,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-325l','<div class="desc"> <em>Three-hour per week laboratory.</em> </div>',NULL,'GEO 325',NULL);
INSERT INTO course_descriptions VALUES(15405,2027,1170,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-342l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>',NULL,'GEO 342',NULL);
INSERT INTO course_descriptions VALUES(15406,2027,940,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-345l','<div class="desc"> <p><em>Three-hour per week laboratory.</em></p> </div>','Co-enrollment in GEO 345 ','GEO 345 ',NULL);
INSERT INTO course_descriptions VALUES(15407,2027,599,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-390','<div class="desc"> <p>Advanced courses on specialized topics in Geology. May be taken more than once with department approval as topics vary.</p><p><strong>Critical Minerals for the Green Economy</strong></p><p>This course will explore the formation and geological settings of ores and critical minerals needed for the transition to a green economy, with a particular focus on the resources needed for renewable energy technologies and energy storage systems. We will focus on the identification and interpretation of ores formed in magmatic, hydrothermal, sedimentary, and weathering environments and assess the global distribution and supply chains of these critical minerals (including issues such as resource sustainability, environmental impacts, and geopolitical considerations). Through lectures, hands-on examination of rock suites, case-studies, and field trips to mine sites in southwestern US, students will gain an in-depth understanding of the geological processes, exploration methods, and mining techniques used to identify and extract key minerals for the green economy.</p><p>Satisfies CPLS; Co-requisite: GEO390L</p><p><br/></p><p><strong>Biogeochemistry of Marine Systems, Past and Present</strong></p><p>This course explores the interactions between the physical, biological, geological, and chemical processes that characterize marine ecosystems and ultimately shape the functioning of our planet. Using a combination of modern analogues and examples from the geologic past, we will study a range of topics from nutrient distribution, ocean acidification, redox reactions to climate change and global biogeochemical cycling. This interdisciplinary course will introduce concepts from chemical oceanography, marine geology and biogeochemistry, borrowing fundamental concepts of each to examine ancient and modern biotic events. Through this course, students will develop a greater understanding of Earth systems and how they have changed through time. Introductory geology, chemistry and/or biology is recommended.</p><p>Satisfies CPMS</p><p><br/></p><p><strong>Geochemistry</strong></p><p>This course will explore the geochemical principles controlling fundamental geologic systems, from the "weathering engine," to the igneous-metamorphic-hydrothermal systems that form and shape planets. This overview of Geochemistry will focus on thermodynamics and kinetics, which allow us to assess these systems with regards to temperature, pressure, and time. Quantitative evaluation of earth processes through geochemical modeling will be conducted using the programs SUPCRT, Visual Minteq, and Geochemist''s Workbench (industry standards). Laboratories, workshops, and fieldtrip(s) will reinforce and expand on many of the topics covered in class.</p><p>Satisfies CPLS; Co-requisite: GEO390L</p><p><br/></p><p><strong>Magmatic Processes</strong></p><p>This course will investigate magmatic processes from magma generation in the mantle or crust to storage within the subsurface to eruption at the surface. We will assess how magmatic rocks can give insight into broader Earth processes, including crustal evolution and volcanic hazards. The properties of magmas will play a central role in the course, shaping our understanding of magmatic systems. Course activities will include class discussions, laboratory modules, and a field trip to analyze what we know â and donât know â about magmatic systems.</p><p>Satisfies CPLS; Co-requisite: GEO390L</p><p><br/></p><p><strong>Paleontology: The Record of Life, Landscapes, and Changing Climate</strong></p><p>This course will use the fossil record as a tool to explore the geologic controls on the evolution and extinction of life on earth. From Snowball Earth to the Great American Biotic Interchange, plate tectonics and climate change drive the distribution of life through time. We will examine paleontological and modern ecosystems through classes, labs, and field trips. Students should have completed GEO105 and at least one 200-level course in biology or geology.</p><p>Satisfies CPLS; Co-requisite: GEO390L</p><p><br/></p><p><strong>Science of Soils</strong></p><p>The physical, chemical, and biological processes within soil systems are assessed. Emphasis is on factors governing the physical properties, nutrient availability, and plant growth and production within soils. How to classify soils and to assess nutrient cycling and contaminant fate will be covered. Recommended: introductory geology, chemistry and/or biology.</p><p>Satisfies CPLS; Co-requisite: GEO390L</p><p><br/></p><p><br/></p> </div>','GEO 105 and two 200-level Geology courses ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15408,2027,1071,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-390l','<div class="desc"> <p>Weekly three-hour laboratory in conjunction with GEO 390 Special Topics in Geology.</p> </div>',NULL,'GEO 390',NULL);
INSERT INTO course_descriptions VALUES(15409,2027,2627,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-391','<div class="desc"> <p>This class serves as preparation for Senior Comprehensives in Geology. Topics include comps options, analysis and presentation of scientific data, literature searches and attribution of previous work. Students will develop a formal plan to complete their senior comprehensive requirement. Open only to junior Geology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15410,2027,1522,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-395','<div class="desc"> <div><p>Research under guidance of faculty member on jointly selected project. Permission of instructor required.</p></div> </div>','GEO 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15411,2027,179,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/300/geo-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15412,2027,2551,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/400/geo-491','<div class="desc"> <p>This seminar focuses on analysis, discussion, and presentation of current issues in geological research. These topics will be explored through the geologic literature and the class will include a formal presentation to the Geology Department. Students will also learn about graduate school and career options in the Earth Sciences. Open only to senior Geology majors.</p> </div>','GEO 391 or GEO 395 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15413,2027,4232,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/400/geo-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15414,2027,600,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/geo-geology/400/geo-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15415,2027,181,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/100/germ-101','<div class="desc"> <p>Introduces basic language skills, grammar, pronunciation, oral communication, and reading simple prose. Culture taught through readings, videos, and discussions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15416,2027,602,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/100/germ-102','<div class="desc"> <p>Continuation of GERM 101.</p> </div>','GERM 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15417,2027,182,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/100/germ-151','<div class="desc"> <p>Oral practice based on articles in current periodicals and other subjects of general interest. Taught by a German language assistant from the University of the Saarland, under the supervision of a German instructor. Designed primarily for students who have completed GERM 102. Graded on Credit/No Credit basis; attendance is mandatory. Approximately two hours of work outside of class time required each week. May be repeated for credit.</p> </div>','GERM 102 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15418,2027,4233,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/100/germ-197','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15419,2027,183,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-201','<div class="desc"> <p>An advanced course to build up comprehension, as well as oral and writing skills. Reading and discussion of literary and cultural texts supplemented with video films and T.V. news on current events in Germany. Practice in essay writing.</p> </div>','GERM 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15420,2027,604,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-202','<div class="desc"> <p>Continuation of GERM 201 at an advanced level. Review of advanced German grammar, and exercises in stylistics and essay writing.</p> </div>','GERM 201 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15421,2027,941,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-232','<div class="desc"> <p>This course covers major trends and developments in the cultural history of postwar Germany. Topics include: the reconstruction of culture after 1945, the makeup of cultural institutions, the mass media, popular culture vs. traditional culture, the counter culture of the 60''s and early 70''s, and the problems of unification after 1989. Taught in German, with emphasis on oral presentations and essay writing. Readings include: literary texts, documentary material, newspaper, and magazine articles.</p> </div>','GERM 201 ; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15422,2027,184,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-251','<div class="desc"> <p>Open to all qualified students, but designed primarily for students preparing for Occidental-in-Germany program. May be repeated for credit.</p> </div>','GERM 152; or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15423,2027,1337,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-280','<div class="desc"> <p>The onset of industrialization in the 19th century created the modern metropolis and the angst and attraction of the lifestyle that went with it. In this course, we will examine how writers and intellectuals of the late-19th and early-20th century described their experience of this new urban environment - analyzing their discoveries and discontents. In addition to fiction by Rainer M. Rilke, Emile Zola, Irmgard Keun, Alfred Döblin, Walter Benjamin, and others, we will also discuss seminal texts by architects, urban planners, and theorists, and look at how visual artists and filmmakers depicted the emerging streetscape of modernity. Students will have the opportunity to explore the impact of modern urbanization in a contemporary and global context through field trips and class projects. The course is taught in English. This course is not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15424,2027,4234,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-288','<div class="desc"> <p>Decades after the fall of Nazi Germany, there is a growing concern that the spirit of Nazism still lives on. The Neo-Nazi movement continues to exist in Germany. A recent report revealed that one out of twenty 15-year-old boys belong to a Neo-Nazi group. Neo-Nazism is not an exclusively German phenomenon, though - we find similar developments in other European countries in Canada and in the U.S. This course will track the activities of Neo-Nazis in Germany from 1990 to the present. We will analyze the impact of unification on the growth of right-wing militancy throughout Germany, and examine examples of Neo-Nazi and skinhead activities, as well as the efforts of various governments to control this movement. A key question will be why exactly young people between the ages of 15 and 30 are drawn to these groups that often use and develop sophisticated networks. Finally, the question will be asked as to what the most effective means of combating these movements would, or should, be. Not open to first year students.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15425,2027,4235,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15426,2027,4236,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/200/germ-297','<div class="desc"> <span style="color: #131313;">Independent study project. Permission of instructor and department chair required.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15427,2027,2339,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/copy-of-germ-311','<div class="desc"> <p>This course introduces students to a wide range of literary, philosophical, and media-theoretical texts from the 18th century to the present that confront us with the question: What is writing? Throughout the semester, we will examine different “scenes of writing,” from the <em>écriture automatique</em> of the Age of Romanticism (Lichtenberg, Hoffmann, Goethe) to the mechanized typewriting of classical modernism (Nietzsche, Freud, Heidegger, Benjamin, Kafka), and consider how literature’s imperative of dramatizing writing frames the protocols of communication that guide a given literary work. We will also interrogate the different ways in which writing has been theorized in modernity: as a self-referential symbolic practice; as a form of communication in which memory, experience, and knowledge are produced, articulated, and organized; and as a procedure of inscription in which language, technology, and bodily gesture are inextricably intertwined. Prominent theorists of writing to be discussed in the course include: Claude Lévi-Strauss, Jacques Derrida, Roland Barthes, Bernhard Siegert, Cornelia Vismann, and Friedrich A. Kittler. Taught in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15428,2027,2944,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-301','<div class="desc"> <p>This course is designed for advanced level German students and will develop their linguistic skills with an aim towards increased fluency in speaking, reading, writing, and listening comprehension. The course will accomplish these goals by reading and discussing texts in German literature or philosophy. The texts and topics can change from year to year and may range from a novel, to a series of short stories, to a topic-based analysis of literary and philosophical texts. Student input on topics and texts is welcome. Discussion and readings will be in German. </p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15429,2027,4439,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-306','<div class="desc"> <p>Looking back on the momentous changes and shock experienced by his generation with the advent of the first world war, Walter Benjamin wrote: âA generation that had gone to school in horse-drawn streetcars found itself under open sky in a landscape in which only the clouds were unchanged and below themâ¦crossed by devastating currents and explosions, stood the tiny, fragile human body.â This course explores the sense of profound change described by the chroniclers of 20th century modernity, and connects it to modernism, that force which sought to disrupt literary and aesthetic tradition and unsettle long-held conceptions of the self, identity, justice, and political authority. Injunctions made to the literary form of the novel are examined through the humorous prose stylings of early modernist Robert Walser, while Brechtâs epic theater serves as a case study in the radical potentials of early 20th century drama. We will also focus on the poetry of Rilke, Bachmann, Celan and others. Finally, the legacy of the crises of modernity (modern warfare, fascism, ecological destruction) and modernismâs responses will be reflected on via a reading of W.G. Sebaldâs Austerlitz. This course will be offered in conjunction with CSLC 106, but will meet for an additional 90 minutes per week to read the German texts covered in class in their original German form.</p><p><br/></p><p>Students who complete the final paper for this course, with a grade of C or higher, can use this work to satisfy the second-stage writing requirement.</p><p><br/></p><p><br/></p><p><br/></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15430,2027,2654,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-307','<div class="desc"> <p>A basic understanding of Marx, Nietzsche, and Freud is a prerequisite for participating in critical debates in the humanities and social sciences. In this course we will read some of the central texts in which these thinkers developed their revolutionary models of analysis: historical materialism, post-metaphysical philosophy, and psychoanalysis. Though different, what all three of these thinkers had in common was a rejection of the rational subject and with it the notion that commonplace social norms involved in knowledge, morality, and sexuality represented timeless and universal truths determined by a neutral subjectivity. Instead, each sought to explain how these norms were in fact social constructions that are best explained by analyzing the specific historical and sociological conditions in which they arose. For Marx, this project involved an analysis of how power and class relations contribute to the production of “ideology”, for Nietzsche an investigation into the history and transformation of morality, and Freud the exploration of the unconscious. The result is a radical transformation of our understanding of subjectivity and a realization of the deeply contingent and malleable nature of human existence. We will investigate these theories by examining works of Marx, Nietzsche, and Freud within their contemporaneous contexts, drawing on the literature, art, and music of the time as well as more recent history and film as points of elucidation and comparison. This course will meet three times a week. Twice with CSLC 107 with discussion conducted in English, and a third weekly meeting in which all readings and discussions will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15431,2027,2552,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-308','<div class="desc"> <p>This course introduces students to the literature, philosophy, art and science of German Romanticism, a wide-ranging intellectual movement that flourished in German-speaking lands at the turn of the 19th century. Throughout the semester, we will read and discuss seminal works of German Romanticism by such prominent authors, artists and intellectuals as Friedrich Hölderlin, Novalis, Johann Wolfgang von Goethe, Immanuel Kant, Johann Gottlieb Fichte, F. W. J. Schelling, Caspar David Friedrich and Friedrich Schlegel. In conjunction with our readings, we will address key topics and issues related to German Romanticism, including but not limited to: Romantic poetry and the critique of art; the philosophy of nature and Romantic science; the role of the self in constituting, mediating and perceiving the world; the philosophy of language; and the expression of religious feeling. </p> <p>This course will meet three times a week, twice with CSLC 108 with lectures and discussion in English, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15432,2027,1523,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-309','<div class="desc"> <p>Small forms cover the broad field, from aphorisms, epigrams, fables and riddles to anecdotes, jokes, short stories and novellas. In each of these forms, smallness unfolds in different and historically-specific ways. From the aphorisms of the 19th century to the Twitter updates of today, the course will explore the poetics and pragmatics of small forms in German literature, philosophy, and contemporary social media. Questions to be discussed in the course include: what can small mean at the level of (literary) form? What kind of readings does small form facilitate? Which does it thwart? To what extent does small form gain epistemological significance with respect to the critique of systematic philosophy? And what can its contemporary manifestation in the form of social media “microformats,” such as tweets, blog posts, and Vine videos, inform us about condensation, narration, and knowledge in the present? Readings include Georg Lichtenberg, Schlegel, Novalis, Nietzsche, Kafka, Walser, Benjamin and Twitter. This course will meet three times a week, twice with CSLC 109, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15433,2027,1658,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-310','<div class="desc"> <p>The obsession with interpreting moral character based on physical (especially facial) features has endured since antiquity under the name of "physiognomy." Strangely, interest in this esoteric art exploded during the "Age of Reason," the Enlightenment, when it first became codified as an empirical science. Starting with the writings of Johann Caspar Lavater, whose monumental "Physiognomic Fragments" (1775-1778) advocated physiognomy as a means of "promoting human understanding and human love," this course will explore the widespread influence that the art of interpreting physical features had in the intellectual and artistic milieu of the 18th century, and, arguably, continues to exert in the modern day. We will examine physiognomy in the aesthetic, cultural, literary, and scientific contexts of the German Enlightenment, dealing with such major figures as Goethe, Lessing, Lichtenberg, Schiller, and Hegel, as well as its unprecedented boom in popularity around 1900, when it was embraced by many prominent strands of German thought, from the "philosophy of life" (Nietzsche, Spengler, Kassner) and literary modernism (Rilke, Benn, Musil), to eugenics, criminology, and racial biology. In concluding with the rise of Nazism and their attacks on modern art as "degenerate," the course will assess to what extent Walter Benjamin''s thesis that "[t]here is no document of civilization which is not at the same time a document of barbarism" holds true for the historical trajectory of German thought. Topics include: the relationship between texts and images, theories and practices of interpretation, as well as the complicity of the arts and sciences in constructing theories of racial difference. This course will meet three times a week, twice with CSLC 210, and a third weekly meeting in which all readings and discussion will be conducted in German.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15434,2027,2705,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-312','<div class="desc"> <p>What is despair and what does it tell us about being human that we alone can seemingly experience it? Is it equivalent to sadness or depression? Can it be relieved by material wealth, fame, success? For Danish philosopher Soren Kierkegaard despair was not a passing temporal condition but something that in itself points beyond itself to the possibility of its own overcoming. In doing so, despair, for Kierkegaard, forces open the crucial existential question: What does it mean to be a self? This course will examine this question by exploring changing conceptions of selfhood and despair from antiquity to modernity, moving from Achilleus’ despairing rage in the <em>Iliad</em> to Dostoyevsky’s depiction of the individual revolting against society in the<em> Notes From the Underground</em> and culminating in the seemingly irredeemable despair of Cormack McCarthy. Readings will include works by Homer, Plato, Thucydides, the Stoics, Marguerite of Porete, Meister Eckhart, Martin Luther, Soren Kierkegaard, Fyodor Dostoyevsky, Leo Tolstoy, Franz Kafka, Cormack McCarthy, and Flannery O’Connor. In addition to the English section, this course will meet for an additional session per week to read the and discuss the German language and other supplementary texts in their original. Readings will occur in German and will serve as an introduction to the major developments of the German language from Middle High German to the advent of High German in the writings of Martin Luther to its modern iterations in Hermann Hesse. Authors will include among others, Meister Eckhart, Martin Luther, Franz Kafka, and Hermann Hesse while discussion will occur in English and German and focus on the intricacies of the original language text and developing arguments out of it. </p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15435,2027,3339,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-313','<div class="desc"> <p>Although the first volume of the Grimms’ Children Stories and Household Tales was published more than 200 years ago, their fairy tales continue to enchant contemporary readers. In this course we will not only study the Grimms’ fairy tales themselves and rediscover their enduring magic, but also take a look at their origins and their social, ideological, and political contexts in 19th-century Europe. We will work with fairy tale theory (narrative, psychoanalytic, historical) and discuss the function of the tales for adult communities as well as their status as children’s literature. Alongside the “original” Grimms’ tales—a concept that we will discuss—a major portion of the course will engage the legacy of the fairy tales and the way they have been appropriated by others, particularly from a critical, feminist perspective. Points of emphasis will include: how writers in the first half of the 20th century politicized the tales in the battle for societal change during the time of the Weimar Republic and Nazi Germany; how the tales were reinterpreted in different national traditions and historical periods; how the fairy tale becomes a mass culture icon in Disney’s film versions; and how contemporary writers like Margaret Atwood continue to employ fairy tales to question the construction of gender and carve out new possibilities for relating to one another. </p> <p>This course will meet twice a week with CSLC 113, and for one additional 85 minute session per week to develop German students’ language skills. Students will have an opportunity to translate and discuss selections from texts in the original German.</p> <p>Students in this course are required to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second Stage writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15436,2027,2751,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-315','<div class="desc"> <p>This course will investigate the concept of madness as both a social category and one of the crucial terms of art and literature. On the one hand, madness often carries with it a negative connotation, as a statement or mental state beyond the realm of sense. Yet on the other, aesthetic theory has long considered madness a necessary condition of great art. For the philosopher Immanuel Kant, the art of the genius must break the rules of style and explode the bounds of the ordinary sense in order to be exceptional. Art, in this sense must necessarily push the boundaries of the normal, straddle the realms of madness and sanity and, in doing so, transform the categories we use to understand the world. Thus by seeing madness not as some eternal category, but as constructed and deconstructed in concrete contexts, the dialectic of madness and genius forces upon us the following questions: How does the concept of madness get constructed? Who gets to decide who is and isn''t mad and why? Why is the creation of art so tightly bound up with concept of madness? What does this tell us about how we make sense of the world and the possibilities of changing our own forms of understanding? We will investigate these questions by reading works of literature and philosophy that directly and indirectly address issues of madness and its relationship to creativity. Readings will include works by Michel Foucault, Franz Kafka, Heinrich von Kleist, Honore de Balzac, Virginia Woolf, Deleuze &amp; Guattari, Goethe, Adalbert Stifter, Immanuel Kant, and Ralf Waldo Emerson.</p> <p>This section will meet once a week extra to discuss these texts as read in the original German. Reading, but not speaking knowledge of German is required.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15437,2027,2865,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-316','<div class="desc"> <p>This course will be centered around an in-depth investigation of one of the most controversial and influential philosophers of the 20th Century, Martin Heidegger. Rejecting what he saw as the tradition of western metaphysics and its quest for absolute knowledge, Heidegger''s phenomenological approach focused on an analysis of lived experience and the structures that make that experience possible. Fundamental to this analysis are the ideas of finitude and fallibility. Human beings, for Heidegger, are never closed and completed, secure in their knowledge and understanding of themselves, but beings who are fundamentally concerned with their own being, who seek to determine themselves from within the complex social, historical, and interpersonal contexts into which they were thrown. As such, philosophy, for Heidegger, becomes interpretation, the attempt to interpret and reinterpret oneself and one''s place within a changing and complex world, always with the possibility of failure. The course will investigate this project of "existential hermeneutics" through an in-depth investigation of some of Heidegger''s major writings. The first half of the course will focus on a close reading of the first half of <em>Being and Time</em> while in the second half we will look at Heidegger''s post war essays, his turn to "poetic thinking" and the legacy of Heidegger''s thought on 20th century Continental philosophy. We will investigate Heidegger''s works from out of their historical context, including Heidegger''s relation to National Socialism.</p> <p>In addition to the English section, this course will meet for an additional session per week to read the texts in their original German and discuss the nuance and difference in meaning as it is transmitted through the original language. Reading the text in the original German is particularly important in the case of Heidegger, whose philosophical program cannot be separated from his thinking about language and the intricate relationship between language and meaning. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second-Stage Writing Requirement. </p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15438,2027,2896,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-318','<div class="desc"> <p>Derided or revered, there is no question that the Enlightenment is important. But what was the Enlightenment? This course will investigate the Enlightenment in all its complexities and contradictions. As an era defined by radical critique, Enlightenment thinkers rejected the authority of religion, tradition, and aristocracy, and sought to transform our understanding of nature, culture, and history by grounding these fields on the transparent rational principles of freedom, progress, and universality. In doing this, the Enlightenment embroiled itself and us in a contradiction. It both created the fundamental terms, ideals, and institutions that frame our contemporary understanding of the world while also establishing a discourse of universality and eurocentrism that serves as the object of our greatest critique. Yet far from being one thing, the Enlightenment also possessed the tools for its own self critique. Or, in the words of Johann Gottfried Herder, "What is universal reason but a cover for our favorite, whims, idolatry, blindness and laziness.?" Following, Herder, Rousseau, and Goethe, this course will also investigate the alternative conceptions of nature, culture, and history that rejected the universalist and imperialist strand of Enlightenment thinking in favor of a dynamic, process-oriented understanding of history and nature as eternally unfolding. With this conception, the Enlightenment perhaps offers an alternative to help us in our quest to think beyond it. Readings and persons of engagement may include, Descartes, Locke, Leibniz, Rousseau, Herder, Kant, Goethe, Lessing, Defoe, Alexander von Humboldt, Haydn, Mozart, and Schiller. </p> <p>No prior knowledge of the texts or the period will be assumed in instruction. By the end of the course, students will have a solid understanding of the historical, cultural, and intellectual context of the period we call The Enlightenment as well as the fundamental problems and questions that were addressed at that time. Students will also have a solid understanding of the divergent ways in which these questions were answered and the different conceptions of culture, history, and literature that arose out from these answers. Additionally, students will develop an understanding of the various legacies of the Enlightenment and have an opportunity to grapple with the positive and negative aspects of that legacy in the contemporary cultural context. <em></em></p> <p>The course will consist of two parts. First, the Tuesday-Thursday lecture in English (shared with CSLC 118) and second, a German language section in which we read the texts in which we read the texts in the original and discuss the nuances of the text as it reads in the original language. Discussion will be in English. </p> <p>A completed final paper for this course with a mark of C or higher can also serve to fulfill the Second Stage Writing requirement.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15439,2027,1019,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-320','<div class="desc"> <br/> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis - the transformation of "forms [...] into "new bodies," and vice versa - from its mythic origins in Ovid, to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought, and how the permutations of this nexus come to bear on a wide variety of different topics in the Humanities, including: myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. This course will meet three times a week, twice with CSLC 120, and a third weekly meeting in which all readings and discussion will be conducted in German. </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15440,2027,4237,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-322','<div class="desc"> <p>After the end of WWII, the generation of what would become known as the 68ers found themselves in a precarious position. They came into adulthood to realize that their parent’s generation were if not perpetrators then at least accomplices to one of the gravest genocides in human history, that they had enthusiastically endorsed a fascistic manic, that the country they inhabited stood in ruins, bombed to the ground morally and physically, and that they now stood at the epicenter of the cold war, half capitalist, half communist. From the perspective of the 68ers, the worst of all was that there had been no cultural reckoning. With the conclusion of the Nuremberg trials and the prosecution of the elite Nazi administration, the majority of the population seemed content to simply to forget. For the 68ers that was not an option. Rather than view the WWII and the Holocaust as an aberration and horrific exception to German culture, the youth of the 68er generation demanded a revolutionary reevaluation of everything German. They asked: What factors, economic, social, cultural, and historical, led to this catastrophe? How can we come to terms with this past? And what vision of a transformed future could replace the old? The answer to these questions involved a three-step approach. A radical critique of the past and the structures of nationalism, patriarchy, heteronormativity, racism, and capitalism, which they believed were the foundational underpinnings of German fascism. Active political dissent that demanded change and culminated in the domestic bombings of the left-wing group the Red Army Faction. And a total re-conception of the norms of society, sexuality, and selfhood perhaps best represented in the Love Parade and the drugs, sex, and radical experimentation that fueled the raves and Berlin techno scene after the fall of the Berlin Wall.</p> <p>This course will investigate the transformations of postwar German society in the literature, philosophy, film, photography, and art of the time. We will focus on the social critiques of the Frankfurt School of Critical Theory, political resistance in both the communist East and capitalist West Germany as well as the life in and relationship between the two, and the utopic visions of the postwar German left as well as the success and failures of this radical political movement. Readings and figures may include: Adorno, Horkheimer, Marcuse, Deleuze, Foucault, Crista Wolf, Max Frisch, The Baader-Meinhof Complex, Rainald Goetz, Anselm Kiefer, Helene Hegemann, and Felix Denk.</p> <p>The German section of the course will meet three times weekly. It will meet twice together with CSLC 122. For these meetings readings and discussion will be in English. Additionally, GERM 322 will meet once a week to read and discuss selected text in the original German. Reading knowledge of German is a prerequisite for enrolling in GERM 322. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15441,2027,3602,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-393','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">Intensive study in an area of German literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15442,2027,4238,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.<br/> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15443,2027,606,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/300/germ-397','<div class="desc"> <p>Individual study of a major author, movement, genre, or translation technique. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>','GERM 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15444,2027,4239,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/400/germ-493','<div class="desc"> <div><div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">Comprehensive-level work in an area of German literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</span></p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15445,2027,4240,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/germ-german/400/germ-497','<div class="desc"> <span style="color: #131313;">Independent study project. Permission of instructor and department chair required.</span> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15446,2027,186,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/100/grk-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Ancient Greece. Students will engage, from the beginning, with original texts from Homer, Sophocles, Plato and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Greeks, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15447,2027,607,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/100/grk-102','<div class="desc"> <p>Continuation of GRK 101 and reading of adapted Greek texts.</p> </div>','GRK 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15448,2027,4241,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/100/grk-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15449,2027,187,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/200/grk-201','<div class="desc"> <p>Homer''s epics feature some of the best known, and varied, heroes of antiquity, like Achilles, Hector, Odysseus, and Penelope. In this class, we will read selections from the <em>Odyssey </em>and <em>Iliad </em>as a way to examine ancient conceptions of heroism. For students studying ancient Greek, this will primarily be a translation course and will serve as an introduction to epic poetry. Students without Greek are also welcome and can expect to approach the topics of the class by reading translated texts and modern scholarship.</p> </div>','GRK 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15450,2027,4242,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/200/grk-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15451,2027,4243,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/200/grk-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15452,2027,3988,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-302','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; text-align: justify; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">The philosopher Martin Heidegger once famously observed that for human creatures such as ourselves, Being is always a matter of Being-</span><span style="font-size: 12pt">with</span><span style="font-size: 12pt">: that is to say, a truly human life is necessarily a life lived in constant relation and reference to other human beings. And yet as Heidegger further notes, this existential condition of sociality depends, fundamentally, on our speciesâ rich capacity for language. In this class, therefore, we shall examine the interplay of language and human social existence, or culture, from prehistoric times to the dawn of modernity itself (roughly, to the time of the Renaissance and the rise of the nation state). In reconstructing this relationship between language and culture, we shall draw on the work of a large array of thinkers, ancient and modern, spread out over a number of academic disciplines: biology, anthropology, history, linguistics, philosophy, sociology, political theory, to name but a few. Yet throughout the class special emphasis will be placed on the question of literature. How does this particularly complex use of language relate to the making, unmaking, and remaking of human cultures in the premodern period? How might it affect our sense of the relationship between language, literature, and culture, today? In pursuit of such questions, </span><span style="font-size: 12pt">the course will take us to regions as various as Mesopotamia and Ancient Egypt, Northern Africa and the Levant, Ancient Greece and Rome, India and Anatolia, Central Asia and Western Europe, and will draw upon written and oral texts as diverse as mythic theogonies and historical king-lists, philosophical disquisitions and religious incantations, publicly staged dramas and privately scrawled graffiti. Specific canonical authors covered may include, but are not limited to, Hammurabi and Jeremiah, Herodotus and Thucydides, Plato and Aristotle, Cicero and Livy, Aurelius and Augustine, Ibn Sina and al-Farabi, Suleiman the Magnificent and Petrarch, Machiavelli and Luther. Greek 302 will meet in common with CSLC 202 twice a week, and will meet for an additional session once a week to translate excerpts from the histories of Herodotus and Thucydides, Plato''s Republic, and the Politics and Ethics of Aristotle.</span></p><p dir="ltr" style="line-height: 1.38; text-align: justify; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">Students who complete the final paper for this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement. </span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15453,2027,3327,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-303','<div class="desc"> <p>It is impossible, the philosopher Martin Heidegger once declared, for any human being ever to be truly alone; to exist as a human at all, he argued, is always already to be acting and thinking and feeling in relation to other humans, to be interpreting our own being in relation to those who likewise, and reciprocally, must interpret their being in relation to ours. In this class, we shall examine the ways in which various philosophers and theorists have conceived this mutually entangled condition of togetherness, this existential condition of Being-With. We shall inquire, for example, into the ways this condition of shared being has been interpreted politically (in terms of entities such as city-state and nation-state), sociologically (through notions such as community and society), economically (through concepts such as markets and labor), and anthropologically (through the concepts of kinship group, family, and tribe). What shall distinguish this class from those to be found in any number of social science departments, however, is the close attention we shall be paying to the crucial role of culture, the role of literature in particular, in the making (and unmaking, and remaking) of all these ways of relating ourselves to one another. To put it somewhat more pithily (and alliteratively): how exactly do poetics relate to politics, and politics to poetics, in the shaping of our shared human existence? This course shall survey some of the most important ways of answering this question in the modern era, and then apply these modern theories to the translation and interpretation of select Ancient Greek texts that also attempt to deal with the question of community: the works of Greek tragedians and comedians, the historians Herodotus and Thucydides, and philosophers such as Heraclitus, Democritus, Aristotle and Plato. </p> <p>This course will be taught in conjunction with CSLC 203, with an extra weekly session devoted to the study of Ancient Greek texts. Beyond the examination of ancient texts in the original, therefore, students will also be expected to study a wide array of social and cultural theorists from the 17th century to today, including (but not limited to) figures such as Hobbes and Vico, Rousseau, and Smith; Hegel and Marx, Malthus and Mill; Durkheim and Weber, de Beauvoir and Adorno; Fanon and Bourdieu, Turner and Geertz: Habermas and Rorty, Nussbaum and Butler; Nancy and Agamben, Appiah and al-Gharbi. </p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','CSLC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15454,2027,2515,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-381','<div class="desc"> <p>The mythic queen Clytemnestra kills her husband and is murdered by her son who seeks to avenge his father. The sorceress Medea murders her two sons to punish her unfaithful husband. Classical drama revels in depicting villainous and violent women such as these, so much so that this practice inspired a contemporaneous comedy where Athenian women plot to kill the tragic playwright Euripides for his slanderous portrayal of the female sex. This course will consider the depiction of women in select Athenian plays of the 5th century BCE. We will read Aeschylus'' Oresteia trilogy, Euripides'' Medea, Aristophanes'' Thesmophoriazusae, and selections from contemporary scholars. We will examine these figures in their dramatic and historical context to acquire a deeper understanding of how the concept of woman is articulated on the Athenian stage. This course meets with CSLC 181 and is for students who will be reading texts in the original Greek.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15455,2027,1524,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-382','<div class="desc"> <p>In this course, we will trace one historic trajectory of what we, today, call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the gospels of Christianity, the troubled confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the <em>Divine Comedy</em>. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring, and frustrating complexity.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15456,2027,1701,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-383','<div class="desc"> <p>In our many attempts to make "sense" of art, literature, and music, we sometimes forget that what matters most to us about any of the arts, high or low, from the books we read and the music we listen to, to the clothes we wear, is not their "content" (if they even have any content to speak of) so much as the all-important question of their style. In this class, we shall attempt to answer the question of why style matters so deeply to us by relating the history of stylistic preferences (from ancient to modern times) to the history of metaphysics, to the question of Being itself. In other words, this course will test the thesis that our preferences for electric guitar over acoustic, for oil paint over water color, for free verse over iambic pentameter, have less to do with this or that particular thing within the world than they do with the way we answer the question of how or why there is a world for us, at all. The Greek section of this course will be devoted to translation of <em>The Iliad</em> from the original, paying particular attention to the ways in which the Homeric epic has been received in the almost three millennia since its original appearanceÍ¾ this will give our investigation into the history of style in the West (and its possible metaphysical grounds) a carefully delimited focal point.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15457,2027,2853,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-385','<div class="desc"> <p>There has been no shortage of disciplines and institutions that have sought to convince us that we interact with our world primarily through our minds. But one form of literature, at least, has always known otherwise. For no matter what philosophy, religion, ethics, or the law try to tell us, comedy will never let us forget that we exist, in this world at least, in and through our bodies. The bodies of comedy, however, unlike the bodies of science, art, or athletics, are neither orderly, nor inspiring, nor ideal. The comedic body is unruly, excessive, needy, offensive—in a word, impolite. What is special about comedy, however, as this class will endeavor to show, is that it encourages us not to despair over our shared condition of gross embodiment, but rather to unite ourselves around it. Comedy creates community from the shared experience of our bodies— from our corpulent, crapulent, concupiscent corporeality. Having no interest in the maintenance of an ideal "body politic," comedy rejoices in the humble togetherness of a "body impolitic." Though this course will aim to establish a history of comedy from the ancient Greeks and Romans to the Medieval, Renaissance, and Restoration eras (and beyond), it will also make constant reference to modern comedic phenomena; the sit-com, the rom-com, the stand-up, the parody, and the roast—to name but a few. In addition to attending the 3 hours of lecture required of students in CSLC 285, students in Greek 385 are required to attend an additional 90 minutes of class per week to read and discuss texts in the original language. Students in this course are required to complete a 10-12-page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15458,2027,1659,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-386','<div class="desc"> <p>In this course, we will be "taking on" the myth of Ulysses, through a complete reading of several of the most important ancient and modern works devoted to it: Homer''s <em>Odyssey</em>, James Joyce''s <em>Ulysses</em>, John Barth''s <em>Menelaiad</em>, and Derek Walcott''s <em>Omeros</em>. Traditionally, of course, the myth of Ulysses has been understood as a rather sentimental myth of nostos, or "homecoming": the hero, forced by fate into hateful foreign places, finally wins his way back to the security, stability, and contented self-Â­sufficiency of his own native land. Or so the story goes. In this course, however, we will test the thesis that something more like the opposite of this interpretation may hold true. It may be, in other words, that the wanderings of the Ulysses figure (whether through the seas of the Mediterranean, the streets of Dublin, or the isles of the West Indies) work not so much to affirm the selfÂ­-sufficiency and comfort of home, as to trouble and destabilize it. What the heroes of these works might finally come to understand - and may even rejoice in - is not the idea that there is "no place like home," but rather that, in the end, it is only within a certain placelessness that we are ever really "at home," at all. This course will be offered in conjunction with CSLC 286, but will meet for an additional 90 minutes per week to read Homer''s <em>Odyssey </em>in the original Greek.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15459,2027,3294,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-387','<div class="desc"> <p>“The origins of the myth of Prometheus,” it has been said, “are unclear; even in antiquity the story is never told in full.” Right from the beginning, it would seem, Prometheus arrives on the scene of literature in a torn, dismembered condition, his story diffracted from the outset into a multiplicity of incoherent elements and perspectives: is he a mighty Titan, or merely a trickster? a divine benefactor, or a threat to cosmic peace? an embodiment of the power of thought, or a figure of its eternal helplessness and misery? The primary object of this course, which will be taught in conjunction with CSLC 187, will be to survey some of the more impressive and surprising ways in which literature, art, and philosophy have engaged with, and contributed to, the strangeness of this myth of Prometheus--a figure who, as we shall discover, is as much a source of agony to the Absolute, as he is agonized by it. </p> <p>While reading the later receptions of the Prometheus myth along with their counterparts in CSLC 187 (in the works of Goethe, Shelley, Melville, Marx, Nietzsche, Heidegger, and others), this five-unit, Ancient Greek section of the class will additionally read the ancient texts covered in class (Prometheus Bound, as well as selected excerpts from Hesiod and Plato) in their original Greek form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15460,2027,4244,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-388','<div class="desc"> <p>In this course we shall be reading, both in translation and in the original Greek, that “foundational” work of Western thinking, Plato’s <em>Republic</em>. The sheer intellectual abundance of this work is, of course, well known: in its ten chapters it provides seminal reflections on--among other things—justice, psychology, music, literature, the nature of truth, economics, political science, math, physics, gender, mortality and immortality (to name but a few of its multifarious concerns). And yet, as this course shall argue, the work itself—and in some ways, the entirety of Plato’s literary and philosophic <em>oeuvre</em>—might be understood as structured around a single question: namely, how are we to connect the experience of human desire with the necessity of human community? We shall be devoting one week to each chapter of this great work, and two weeks apiece to Chapters Five, Six and Seven. Beyond the reading of individual chapters, students will be asked to provide, week by week, a detailed commentary on selected passages in the original Greek, and summations of assigned secondary literature. Where possible we shall attempt to relate the arguments of <em>The Republic</em> to relevant passages in other Platonic dialogues (in particular, <em>The Symposium</em>, <em>Gorgias, </em>the <em>Phaedo</em>, and <em>The Laws</em>).</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15461,2027,2945,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-389','<div class="desc"> <p>In the 6th century BCE, certain Greek thinkers (who have since come to be known as "philosophers") put in motion a conceptual distinction decisive for the cultural and intellectual history of the West: the division of the soul (<em>psyche</em>) from the body (<em>soma</em>), and more generally, from the "flesh" (<em>sarx</em>). By the 4th century BCE, Plato seems to have concluded that philosophy must eschew any interest in the flesh, inasmuch as flesh (whatever it may be) cannot yield to precise, philosophical investigation. Perhaps even more crucially, Plato stipulated that flesh cannot and should not be the basis of a politics, as it is only philosophical insight, in its disciplined refusal of the lure of the flesh, that could serve as the ground of genuine political communion. From here it was but a short step to conclude that poetry (and of course, "art in general"), entangled as it was with the body, could have little meaning or import for the practice of either politics or philosophy.</p> <p>Influential as these weighty pronouncements surely have been on the history and development of Western thought, resistance to them, it should be noted, was almost immediate--beginning perhaps with the work of Plato himself! In this course, we shall examine the ways in which literature and art, as a "poetics of the flesh," offers us a practice as rigorous, and productive, as any purported philosophy of abstract, spiritual forms. We shall then consider what such a poetics of the flesh might be able to offer philosophy itself as an intellectual discipline. Finally, we shall engage with recent theories concerning the way in which authentic political community might rest not on the eschewal of the flesh, but its deliberate and thoughtful "incorporation" (pun intended).</p> <p>The first half of the class will focus on older material (certain Ancient Greek and Roman poets, Plato, Aristotle, the New Testament, as well as some medieval writers and thinkers); the second half of the class, however, will turn to the work of more recent poets and theorists of the flesh, with a particular emphasis on the investigations of Jean-Luc Nancy into the significance of the arts, and what he calls the "sense of sense." </p> <p>This course will share lecture time with CSLC 288, but will meet for an additional 90 minutes per week to translate and read selections from Plato''s Republic and Ion, Aristotle''s Poetics, Physics, and Rhetoric, and the New Testament, in the original Greek. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15462,2027,3611,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-390','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the magnificent yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them. </p> <p>This course will be offered in conjunction with CSLC 190, but will meet for an additional 90 minutes per week to read the Homeric texts covered in class in their original Greek form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15463,2027,3109,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.<br/> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15464,2027,608,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/300/grk-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>','GRK 201 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15465,2027,4245,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/grk-greek/400/grk-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15466,2027,3935,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/gwss-gender-women-and-sexuality-studies/100/gwss-100','<div class="desc"> <div><p>This course provides a range of perspectives on how sex, gender, and sexuality are constructed in social and cultural contexts, with an emphasis on intersectionality. Students will learn about the origins and types of feminist theories and queer theories, and historic and contemporary social movements for gender justice and LGBTQ+ rights. This course serves as the foundation for the Gender, Women, &amp; Sexuality Studies minor.</p></div> </div>','This is an intro course. No prerequisite required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15467,2027,4440,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/gwss-gender-women-and-sexuality-studies/300/gwss-397','<div class="desc"> Independent study in Gender, Women, and Sexuality Studies. </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15468,2027,4246,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-100','<div class="desc"> <p>How and why have authoritarian regimes been able to dismantle democratic rule? This course showcases four historical case studies from Europe (the Roman Republic, Revolutionary France, Weimar Germany, and post-Soviet Russia). In each case, a (more or less) democratic state was replaced by a (more or less) authoritarian regime. What features of each democracy made it vulnerable to this fate? What strategies and political claims helped each authoritarian regime to gain popular support? How did economies, cultures, and global events affect outcomes in each case? Each of these histories resonates with current events in Europe and globally. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15469,2027,188,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-101','<div class="desc"> <p>This course is an introduction to early North American/U.S. history, reaching from colonization to the Civil War. Of particular interest in this course will be the theme of cross-cultural interactions in the midst of transforming economies, an expanding nation, and unequal power relations. We will combine a broad introduction to early American history with an in-depth look at five case studies of individuals and communities encountering each other across borders of nation, religion, race, gender, ethnicity, and class. Each case study offers a unique perspective on the question of how broad economic structures of colonization, slavery, and the market revolution shaped human encounters between natives and newcomers, captives and captors, slaves and slaveholders, Northerners and Southerners. Ultimately, these case studies encourage a critical rethinking of concepts of liberty, equality, and democracy, which have formed the bedrock of master narratives in United States history. Within the context of these broad, sweeping themes, we will look closely at primary historical documents, produced by men and women of their time period, and we will carefully read the arguments of historians in our own time. The class will emphasize history as a process of critical interpretation.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15470,2027,609,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-102','<div class="desc"> <p>This course provides an introduction to United States history from the Civil War to the early 21st century. Readings and lectures are structured around the core theme of American pluralism. They emphasize the changing demographics of the American population and consider the different strategies that Americans have used to negotiate this growing diversity over time. Topics covered include: Reconstruction, westward expansion and overseas imperialism, Industrialization and the Gilded Age, the Progressive Era, World War I, the Great Depression and New Deal, World War II and the rise of internationalism, the Cold War and third world decolonization, immigration reform and comparative civil rights movements, the Vietnam War and the rise of global dissent, conservatism and the "Reagan Revolution," America''s border wars, and the post-9/11 War on Terror. We will give particular attention to issues of race, ethnicity, gender, religion, sexuality, region, and class in the shaping of modern America. Other important themes include: the expansion of federal power and the government''s role in people''s lives, contests over national citizenship and identity, America''s changing role in the world and engagement with foreign peoples, and the demographic transformations wrought by international migration and conflicts.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15471,2027,3841,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-103','<div class="desc"> <p>This course takes place under the shadow of an unprecedented threat to our democracy. That threat starts with an attempted coup sanctioned by one of the country''s major political parties--undermining the peaceful transfer of power that has been the hallmark of American democracy for over two centuries. But the threat does not end there. The country is experiencing growing disparities between rich and poor, a radical loss of faith in its institutions, as well as the erosion of civil society with its democracy-sustaining ethics of reciprocity, humility and compromise.</p> <p><br/> This course seeks to address this ominous state of affairs (however modestly) by recovering the history of democratic debate and practice. We will explore the history of ideas that have contributed to the thickening of democratic practice in thinkers such as Aristotle, Montaigne, Locke, Rousseau, Wollstonecraft, Tocqueville, Mill, and C.L.R. James. We will supplement their contributions with four âcase studies'''' of democratic experiments. After examining the raucous, participatory democracy of Ancient Greece (with its limited suffrage and election by lottery), we will turn to the Levellers/Diggers in 17th century England, the Haitian interpretation of the French Revolution in the 18th century, and the efforts of Utopian communities to reimagine democracy in 19th Century America. Our goal throughout this course is to develop a clear-eyed understanding of the history of democratic ideas and practices in the hope of recovering the resources your generation will need in the struggles to come.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15472,2027,3313,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-105','<div class="desc"> <p>From the Vietnam Memorial in Washington to the removal of Confederate statues throughout the American South, public history has become a flashpoint for controversy. That is largely because how we remember the past can have a large impact on the way in which we shape the future. We will begin by looking at the benefits and problems associated with traditional strategies of historic preservation; and then proceed to examine the ways in which public monuments, museums, and related exhibition strategies have sought to redress significant deficiencies in our historical self-understanding. The course will conclude with two case studies where debates over the past have led to significant controversies and public misunderstandings: The Smithsonian exhibition featuring the Enola Gay (the plane which carried the nuclear weapon that some say "ended the war" with Japan); and the 1619 Project, which has become controversial for its attempts to re-conceptualize the role of race in American history and serve as a spur for rethinking the curricula of our nation''s schools.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15473,2027,4247,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-106','<div class="desc"> No decade in the last 75 years has had a more profound impact on American culture than the 1960s. It inaugurated a counter-culture that is still with us today in the way we talk, dress and the music we listen to; it fashioned a youth culture with its own distinctive sensibility (as expressed by the word "cool"); it challenged habits of deference to authority and social conventions of all kinds (most notably, sexuality). This course will begin with the Civil Rights movement, which confronted institutionalized racism and served as the inspiration for new forms of participatory democracy. From there we will follow the emergence of the student left from its early, hopeful beginnings as articulated in the Port Huron Statement--which sought to enlist college students in a broad-based coalition of political activists--to the increasingly fractious and fractured New Left as it moved from "protest to resistance" and even to revolution. That trajectory was punctuated by a number of key episodes like the Free Speech Movement in Berkeley, the "March on the Pentagon," the occupation of Columbia in ''68, the protests against the Democratic Convention in Chicago, and the subsequent violence of the Weather Underground--all of which we will examine in an attempt to understand why the politics of hope turned so resolutely to the "Days of Rage." We will also explore the accompanying cultural revolution which ultimately abandoned the politics of the New Left and sought more personalized forms of enlightenment that included LSD, communes, and other experiments in living. Join us for what promises to be a groovy semester. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15474,2027,4248,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-110','<div class="desc"> <p><strong>THE CHICAGO WORLD FAIR</strong></p> <p><img alt="Exhibits - Chicago''s 1893 Worlds Fair" src="https://i0.wp.com/worldsfairchicago1893.com/wp-content/uploads/2020/05/Visit-the-Fair.jpg?fit=1200%2C400&amp;ssl=1"/></p> In 1893, Chicago hosted the World’s Columbian Exposition honoring the 400th Anniversary of Columbus’s “discovery” of America. The Fair was designed to showcase the achievements of the United States. The Fair was an immense popular success, but from the beginning the Fair became a flashpoint for controversy. Doubts were expressed about the terrifying new technology on display and the fake Neoclassical architecture which housed it; the display of indigenous people on the Midway; and the emergence of mass culture–symbolized by the ferris wheel–at the expense of more elite forms of cultural authority. This course will examine the Chicago World’s Fair as an inflection point and symbolic drama with a special focus on the issues it foregrounded: empire, technology, race, mass culture, urban planning and the emergence of a modernity that Americans had yet to fully reckon with or understand. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15475,2027,942,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-121','<div class="desc"> This course takes on a familiar narrative—the rise of "Western Civilization"—but approaches it from a critical and expansive perspective. Rather than telling a triumphalist story of European superiority, we explore how the cultural, religious, and political traditions of Europe, West Asia, and North Africa developed in deep conversation with one another over more than 6,000 years of history. In doing so, we aim not only to understand the past, but to question the historical frameworks that have upheld ideas of cultural hierarchy and civilizational elitism.<br/> <br/> Beginning with the early cities of Mesopotamia and Egypt, we’ll move through the Hebrew Bible and Persian imperial ideology, the golden ages of Athens and Rome, and the spiritual revolutions of Christianity and Islam. We’ll study medieval trade networks, Crusader chronicles, mystics and merchants, libraries and battlefields, and end with the intellectual, religious, and political upheavals of early modern Europe and the Islamic world. To guide our study, we’ll follow thematic threads—empire, religion, gender, and knowledge—while engaging closely with a wide range of primary sources, including sacred texts, philosophical writings, scientific diagrams, law codes, letters, myth, art, and material artifacts. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15476,2027,610,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-122','<div class="desc"> <p>The course focuses on the rise, fall, and re-emergence of Europe as a global political, economic, and cultural force in the contemporary world. We begin with the Enlightenment in the 18th century and the dissemination of European power in the 19th century through capitalism, the industrial revolution, nationalism, and imperialism. We then turn to Europe’s crisis in the 20th century with attention to World War I, Fascism and Nazism, World War II and the Holocaust, and colonial wars of independence, to be followed by European rebirth in the form of reconstruction and European unity. The period 1990s to 2020s welcomed several former states of the USSR into the European Union, and witnessed UNESCO’s restoration of historic sites. Specific topics include the French Revolution, transformations in capitalism, the rise of the nation-state, colonialism and decolonization, liberalism, socialism, communism, changes in family structure and gender relations, and the movements for women''s, workers’, gay and lesbian and other minority rights.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15477,2027,2592,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-125','<div class="desc"> <p>In this course focused on European cultures, students will consider the Renaissance and Reformation, Science and Baroque Splendor, Enlightenment Reason and Revolution, Romanticism and Individualism, Industrial Revolution and New Social Thought, Modernism in Literature and the Arts, Global Influences, Cultural Pluralism, and Postmodern Culture. Students experience and critically evaluate texts and images from both historical and contemporary points of view.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15478,2027,4441,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-130','<div class="desc"> <p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">This course explores the development of scientific, medical, and technological knowledge from antiquity to the early modern period, spanning ancient Greece, the Islamic world, and Renaissance Europe. Weâll examine theories of the universe from Aristotle to Copernicus and Newton; terrestrial physics, experimentation, and alchemical traditions; and evolving ideas of the body, race, gender, and disease. Through close readings of primary sourcesâfrom Greek cosmology and Islamic astronomy to Renaissance anatomyâwe will consider how different cultures defined natural philosophy, investigated the natural world, and grappled with the unknown.</span></p><p><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">The course centers not only on </span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: italic; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">what</span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap"> people thought, but also on the </span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: italic; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">why</span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">, </span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: italic; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">how</span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">, and </span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: italic; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">where</span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap"> of knowledge-making: the political, religious, and cultural contexts that shaped early scientific inquiry. Students will leave the course with a deeper appreciation of the plural histories of scienceâand how those histories continue to shape contemporary understandings of reason, objectivity, and human difference.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15479,2027,189,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-141','<div class="desc"> <p>A survey of Chinese, Japanese, and Korean societies from the emergence of states to the present. Several themes explored include: the development of strong, centralized states; the emergence of a shared elite culture; the spread of popular religions; the continuing interaction between East Asian and other societies; contrasting roads taken by each society in order to meet the challenges of modernity; conflicts over imperialism, nationalism, and revolution; cultural debates over gender and generational issues. Finally, a review of the post-WWII era: opposing alignments in the Cold War; socialist state building and experimentations; military rule; democracy; mass culture; successive economic "miracles," and China''s re-emergence as a global power.</p> <p>Survey Requirement Met: <strong>Asia</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15480,2027,190,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15481,2027,611,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-151','<div class="desc"> <p>This course offers a survey of postcolonial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the 19th and 20th centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the 19th century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race; and the development of export agriculture. The second section introduces themes of the 20th century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources, including scholarly works, films, and primary sources to engage these topics and issues.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15482,2027,3936,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-158','<div class="desc"> <div> <p>This course serves as an introduction to the field of cultural memory studies, using Holocaust memory and memorialization as an in-depth case study. After surveying theoretical approaches to individual and collective memory, we explore how genre, politics, and national culture shaped the emergency of Holocaust memory, the potentials and pitfalls of witness testimony, as well as complex forms of transmission across generations. We consider how Holocaust memory has been institutionalized in museums and archives, its ambivalent globalization in recent decades, and ensuing dilemmas of political responsibility and post-traumatic representation. Students also have an opportunity to visit and interrogate public sites of memory in Los Angeles. Throughout, we engage the general theories and methods of cultural memory studies to reflect on the possibilities and limits of collective memory for understanding historical atrocities, enacting justice, and preventing ongoing violence. </p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15483,2027,3303,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-169','<div class="desc"> <p>Imperial violence and capitalist economic restructuring historically drove Asians to migrate to the United States. Once here, people of Asian descent engaged in transformative political activism and constructed new cultural identities and alliances to meet the challenges of diasporic and immigrant life. This course will examine the cultural and political geographies of trans-Pacific migration and identities from the 19th century to the present. From Har Dayal, Sun Yatsen, and Qiu Jin in the early 20th century to the 1960s Third World Liberation Front, the I Wo Kuen Red Guards in San Francisco working with the Black Panthers, and beyond, political activists have been crisscrossing the Pacific, building and rebuilding networks of resistance to colonialism, marginalization, and exploitation. The course draws heavily on the rich history and cultural diversity of Los Angeles and Southern California, which has been a center of Asian and Asian American movements—migratory, political, and cultural—for over a century. Students will examine a variety of primary sources, including literature, political manifestos, and films, and engage deeply with the cultural and spatial geographies of these histories. Field trips to local religious sites and neighborhoods, paired with visits from local scholars, journalists, and filmmakers, will bring these histories to life and illustrate their legacies shaping the present. Along with regular writing assignments, students will collaborate on a final project mapping transpacific migration histories and social justice alliances in LA.</p> <p>This course is part of the Humanities for Just Communities Immersive semester.</p> </div>',NULL,'FYS 1 ',NULL);
INSERT INTO course_descriptions VALUES(15484,2027,612,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-180','<div class="desc"> <p>This course offers an introduction to the modern history of Africa from the 15th century to the end of the Cold War, engaging a particular focus on the vital role African societies have played in the making of the modern world. Rather than presenting Africa as peripheral to global history and conceptions of modernity, this course emphasizes the centrality of Africa and African societies in the major political, economic and social transformations which shape and define our modern world.</p> <p>Students will examine the evolving relationship between Africa and Europe within the broader context of the global rise of mercantile capitalism, the European imperial project of the 15th - 19th centuries and the geopolitical context of the Cold War struggle for influence and resources in Africa. The course is organized around four key historical periods: the rise of mercantile capitalism and the Trans-Atlantic Slave Trade; the 19th century colonial encounter inaugurated at the Berlin Conference of 1884-85; African resistance movements and solidarity with global anti-colonial struggles; and African independence and global decolonization.</p> <p>Students will explore major themes in African history including: sovereignty and dependency, development and underdevelopment, nationalism and resistance, and pan-Africanism and black internationalism. These will be analyzed within relation to broader global forces including neocolonialism, monopoly capitalism and globalization.</p> <p>By interrogating hegemonic narratives that portray Africa as a passive recipient of external forces, students will assess the diverse ways in which Africans have exercised agency and contributed to the global processes that define modernity. The course concludes with an assessment of Africa’s role in the emerging global order.</p> <p>History Department Survey Requirement Met: Middle East and Africa</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15485,2027,848,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-182','<div class="desc"> <p>This is a survey course in which we will explore the cultural and social historical experience of the Middle East from the 19th century to the present. Our goal in this class is to develop a sense of how people in the region view themselves and their history. We consider the currents of social change wrought by political and economic transformation, focusing particularly on the rise of new social movements and cultural currents. Here we will focus on issues of gender, religion, new social categories, and notions of personhood, and new forms of collective and individual identity. Finally, we look at the emergence of modern nation-states and their attendant juridical notions of citizenship and minority status.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15486,2027,2689,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-190','<div class="desc"> <p>This course will take a historical look at the emergence and development of capitalism from the 16<sup>th</sup> century to the present. The course stresses capitalism’s global spread and interaction with other historical forces such as commercialization, urbanization, colonialism and imperialism, environmental and climate change, inequality, and social and economic instability. We will look at the emergence of various schools of thought on capitalism, such as Keynesianism, Marxism, liberalism, the Austrian School and its offshoots, and neoliberalism. We will end with a discussion on the future of capitalism, considering globalization, the rise of China, economic crisis, and the rise of nationalist and populist responses.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15487,2027,2677,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-191','<div class="desc"> <p style="margin-left: 0; margin-right: 0">This course traces the theory and practice of revolution in modern history. The course begins with a brief overview of revolutionary theories and transformations within a global historical context. We then turn to the Scientific Revolution and the Enlightenment as the paradigm shifts which brought a revolution in thought and subjectivity in Europe. From there we focus on the French Revolution, following its legacy and impact through the revolutions of the 19<sup>th</sup> century, the rise of Socialism and Communism, the Russian Revolution, the Chinese Revolution, decolonization and revolutions in Africa, and the Cuban Revolution. The course looks closely at how these revolutions in thought and politics changed the way people understood their relationship to state and society. In the search for global connectivity, we review revolutionary movements beyond the western European and United States to include cultures and civilizations of Asia, the Middle East, Africa and the Americas. We will ask a number of questions related to revolutionary change, including: what causes revolutions? Who makes a revolution? What leads to success or failure in a revolutionary situation?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15488,2027,2885,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-192','<div class="desc"> <p>The course explores gender as a malleable category of historical analysis that intersects fluidly with other categories such as race, class, and sexuality. Course materials interweave global historical studies from the 16<sup>th</sup> to the 20<sup>th</sup> centuries with theoretical work on themes including the following: gender as performance, gendered divisions of labor, gender and science studies, the politics of gender, as well as gender, space, and material culture. By continually historicizing the construction of masculinities, femininities, and gender-fluid identities, this course examines how societies over time have expressed, policed, invented, and reproduced gender as a category of human experience and a shaper of social relations of power. The geographic range of the course is oriented primarily toward the Atlantic World: North America, South America, the Caribbean, West and West Central Africa, and Europe. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15489,2027,3489,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-193','<div class="desc"> <strong>Directed Research: Marxism</strong><br/> This Directed Research course introduces Marxism as a form of social and historical research. Through reading, discussion, and short writing, students will learn: the basic categories of Marxism; the open questions in the field of Marxist research; and, how to use Marxist theory to develop and conduct social and historical research. Permission of instructor required.<br/> <br/> <br/> <strong>Directed Research in History</strong><br/> Research in an area not included in the departmental curriculum. Permission of instructor required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15490,2027,3340,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-194','<div class="desc"> <p class="MsoNormal">The class explores a range of historical experiences of imperialism from the Americas to Central, South and East Asia to the Middle East and Africa. We introduce students to major concepts, theories, and intellectual inquiries in imperialism and postcoloniality. Students will examine the historical emergence of theories and practices of imperialism in order to interrogate notions of human rights, imperial and colonial capitalism and post-coloniality. The class engages with questions concerning knowledge production, representation, and subjectivities produced by the colonial encounter and its historical legacies such as racial capitalism and uneven development. We will necessarily consider the ways that imperialism produces difference as a technique of power.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15491,2027,4249,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-195','<div class="desc"> <p class="MsoNormal">Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15492,2027,4250,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15493,2027,4442,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/100/hist-199','<div class="desc"> It is a cliche to say that "we live in a modern world." But what does that mean? Is modernity defined by science and technology? Secularism? Capitalism? Globalization? Certain forms of art or mass politics? There is a lively debate among historians and theorists about the nature of modernity and its implications for the ways in which we live our lives. We begin by exploring the vexed historiographical question of when modernity begins and ends (if indeed, it has ended). From there we will explore the question of whether modernity represents a "universal path" to the same generic phenomenon everywhere or whether it manifests itself differently in different parts of the world--sometimes with surprising results! We will also explore some of its distinctive features--rationalization, mass culture, the loss of community--along with the affective states presumed to be associated with it: anxiety, alienation, disenchantment, nostalgia. No matter what definitions and approaches we accept, there is wide agreement that modernity marks an historical transformation so profound that it alters nearly everything it touches. This course will explore these themes, with particular attention to the unprecedented challenges posed by modernity--environmental devastation, totalitarianism--as well as the very real possibilities that this "brave new world" makes available to us. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15494,2027,943,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/copy-of-hist-243','<div class="desc"> <p>Chinese history from about 1600 to the present: the growth of the domestic economy, the rise of the Manchus and territorial expansion, encounter with the West, internal decline, rebellions, imperialism, nationalism, and revolution. Gender and national identity are key lenses through which to understand transformations during the modern period, including Modernization efforts, ideological struggles, and the cultural and economic transformations under the People''s Republic.</p> <p>Survey Requirement Met: <strong>Asia<br/> </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15495,2027,2340,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-200','<div class="desc"> <p>The course traces the history of the Israel-Palestine conflict from its roots during the late Ottoman period to the current state of affairs. We will examine this topic through study of the social, economic, and cultural history of the region while remaining cognizant of how global forces from the mid-19th century affected, what was historically, the southern part of Ottoman Syria. The aim of the course is to provide a historical overview of the struggle in the eastern Mediterranean, which has become known as the proper noun, the "Arab-Israeli Conflict." Rather than treating this struggle as the latest, inevitable iteration of a millennia-old, Middle Eastern conflict, this class examines its specific modern historical contexts. Our approach is chronological and we will cover a variety of topics and questions. A sampling of our topics: 19th-century Palestine, the emergence of nationalism as a historical phenomenon, early Zionist settlement in Palestine and Palestinian society at the beginning of the twentieth Century, Zionist women activists and Palestinian women, World War I and British rule, the 1936-39 Palestinian Revolt, the 1948 War for Palestine and its aftermath, Israeli-Arab relations in the 1950s, the Suez War, the implications of gendering the nation, the 1967 War and the subsequent occupation of the West Bank, Gaza and the Golan Heights, the demographic "race," Israel in Lebanon, the Intifadas, and the peace processes.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15496,2027,4251,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-201','<div class="desc"> <p>This course will trace the emergence of anthropology as a field of study in the 19th century; its complicated relationship to imperial conquest; its attempts to free itself of scientific racism and cultural evolution; as well as its pursuit of the full range of human possibility through different ways of conceptualizing the world–particularly at a moment of Western dominance when those possibilities seemed to be increasingly foreclosed. It has been said that the purpose of “anthropology is to make the world safe for differences.” That’s not as straightforward as it sounds. Indeed, anthropology has found itself mired in a number of controversies in its attempts to understand and speak for others: ranging from Margaret Mead’s explanations of adolescent sexuality in Samoa to Napoleon Chagnon’s depiction of violence among the Yanomamo natives of Brazil. We will examine those controversies as well as the ways in which anthropologists like Clifford Geertz and Marshall Sahlins have contributed to new methodological approaches to history--especially cultural history and ethnohistory. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15497,2027,2341,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-205','<div class="desc"> <p>According to Thomas Jefferson, America was to be an "agrarian Republic" - a pastoral farmland, a different world from the dirty and decaying cities of monarchical Europe. Yet, by Jefferson''s day, it was already too late. North America had been dotted with great metropolises and minor towns for thousands of years, and new waves of European and African settlers founded hundreds of new ones, as well. Indeed, for many early migrants, America was itself a "city on the hill" - an urban image for a new society. In this course, we will survey American urban history from those early days to the present, focusing, in the second half, specifically on Los Angeles, where new forms of decentralized urbanism took form in the 20th century. We will not only explore suburbia and freeways, Disneyland, and other quasiÂ­urban outposts, but also the changing character of the inner city in the mid-20th century, as well as radical efforts to reform existing American cities. In the process, we encounter the American city of today - multicentered, privately planned, decentralized, and multiethnic. We will conclude by asking whether contemporary developments in urbanism - the changing character of public space, the turn to privatism, the neglect of public transport infrastructures, and challenges to democracy and equality - are ultimately compatible with the American dream of the "city on the hill" for the 21st century.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15498,2027,191,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-206','<div class="desc"> <p>This course will examine the variety of female experiences in 19th and 20th century America by looking at the class, racial, and ethnic dimensions that shaped women''s lives. A second major concern will be to study women in the context of the historical developments of their time; reform movements, westward migration, industrialization, and urbanization will be examined in light of their impact on women''s experiences and values. The course will also consider a number of themes, including: popular images of women, women and sexuality, women and the family, women and work, women as consumers, and women as reformers.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15499,2027,2851,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-207','<div class="desc"> <p>This course introduces students to major issues in African American history from the earliest experiences of forced African migrants to North America to the quest for abolition and freedom in the United States. With our focus on significant demographic, institutional, cultural, and political developments within Black American communities, we will explore key themes and watershed moments in the African American experience from the early seventeenth through the nineteenth centuries. By analyzing the dynamics of African American history in this way, we will better understand how enslaved Black Americans, Black abolitionists, and freedom fighters shaped the culture and politics of the United States.</p> <p><span style="color: #282b2c;">Survey Requirement Met: </span><strong style="color: #282b2c; margin: 0px; padding: 0px;">United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15500,2027,1233,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-208','<div class="desc"> <p>What does it mean to say that America is a "nation of immigrants?" This course explores the creation of America through the arrival of diverse peoples from five continents over several centuries. Topics include: the legal and political foundations of U.S. citizenship; the creation of the U.S.-Mexico border; the origins of illegal immigration; ethnic and diasporic identities; state power and resistance; popular culture; social movements; and the importance of race, as well as gender and sexuality, in shaping immigration policy and its enforcement. Special attention will also be given to exploring the diversity of immigrants'' experiences in America over time.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15501,2027,1382,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-209','<div class="desc"> <p>This course traces the United States'' rise to global superpower over the first half of the 20th century; its engagement with, and interventions in, a decolonizing Cold War world; and, finally, its transition to its contemporary role as part of an increasingly multilateral and internationalist world order. Our investigation of U.S. engagement with the wider world rests on the understanding that as America''s influence on the world grew, so did the world''s influence on America. Lectures and readings will cover America''s political and military dealings with other powers - that is, U.S. diplomatic history as traditionally understood - but will also address Americans'' cultural, social, economic, and intellectual interactions with foreign peoples, both at home and abroad. Specific topics include: U.S. overseas imperialism, the U.S. role in both World Wars and the Cold War, the heightened significance of Asia and the Pacific World after 1940, internationalism and the creation of the United Nations, the emergence of the Third World and Washington''s ambivalent relationship to global decolonization, Americans'' involvement in the global revolutions of the 1960''s, the economic upheavals of the 1970''s, the end of the Cold War, and the politics of a post-Cold War and post-9/11 world.</p> <p>Survey Requirement Met: <strong>United States</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15502,2027,2593,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-211','<div class="desc"> <p>From the Cold War to the War on Terror this course will examine the United States’ involvement in Afghanistan, Iraq and the Middle East since 1980. Among other things we will look at the connections between the events of 9/11 and the Iraq and Afghanistan wars. This class is an inquiry into the historical implications of these and other protracted US engagements from North Africa to Syria and from Somalia to Pakistan. Ultimately, we will use these events as a lens to pose a series of questions about empire, nation and national identity both in the US and in the Middle East.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15503,2027,2594,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-212','<div class="desc"> <p>With its capital in Europe since 1363 and spanning Europe, Asia and Africa for nearly five centuries the Ottoman Empire was perhaps the most successful and longest enduring experiment in multiculturalism the world has ever known. Multi-lingual, multi-ethnic and multi-religious Ottoman society and culture were comprised of Muslim, Byzantine Christian, Turkish, Greek, Persian, Mongol, Slavic, Armenian, Arab, African and Jewish cultural elements. Edicts from the Ottoman state were regularly issued in nine languages. One reason for its longevity was its willingness to draw on the diversity of this rich historical and cultural tableau. In this course, we will examine the complex social, cultural and political transformations occurring in the Ottoman Empire from its inception as a small principality in western Anatolia until it reached its zenith when it stretched into modern-day Austria.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15504,2027,1602,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-213','<div class="desc"> <p>This course explores free Black political organizing, from the American revolutionary era through Reconstruction. Students will conduct original research into African American activism that stretched from New York to California before and after the U.S. Civil War. We will explore the social networks and political institutions that 19th-century African Americans built to fight for civil rights, economic justice, and an end to chattel slavery. At the heart of the course is a digital humanities component that will involve students in researching the lives and ideas of individual Black activists. At the end of the course, we will contribute our collective research to the national website, Colored Conventions. While engaged in original historical research, students will also be reading exciting scholarship on the rise of free Black communities in the U.S. and the emergence of African American institutions (churches, schools, press, political organizations). We will delve into questions such as: how did free African Americans, from leadership to grassroots levels, organize for racial equality, abolition, and community empowerment? How did class structures and gender ideology shape the dynamics of Black organizing? What transnational relationships and diasporic identities did Black activists build in the protracted struggles for abolition and citizenship?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15505,2027,1702,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-216','<div class="desc"> <p>The "Great Books" have been seen by many as the defining element within the tradition of Western Civilization--a claim that has been the subject of fierce contemporary debate. In fact, the controversy has a long history which goes back at least as the "Quarrel between the Ancients and the Moderns" at the end of the 17th Century and extends to Matthew Arnold''s Victorian-era debate with T.H. Huxley over whether science has eclipsed the need for humanities<em>. </em>In the United States there has been an ongoing skirmish over what to read in our universities that stretches from President Eliot''s decision to abandon the core curriculum at Harvard for an open, elective system in the 1880s, to the furor that erupted with the publication of Allan Bloom''s <em>The Closing of the American Mind</em> a century later. More recently Dan-el Padilla Peralta--a professor of Roman History at Princeton--has advocated for abolishing the founding discipline of Classics altogether because of its entanglement with the origin story of white supremacy. At the bottom of the debate over the canon is the assumption that what we teach and read defines the culture as a whole, what we value, and who we are. It is a debate over the tradition''s exclusivity and chauvinism. But it is also a debate over the relevance of the humanities in a world dominated by science and the rigorous demands of pre-professional training--which is to say that it is a debate over modernity itself. Finally--and perhaps most controversially--it is debate over a putative ideal of "greatness" and "civilization," along with the role of the University in perpetuating that ideal, even as it plays the largely unexamined role of selecting leadership within a democracy. Clearly, much is at stake. This course will examine the many sides of this longstanding controversy among canon''s advocates, critics and reformers. We will also examine the attempt to institutionalize various curricular models such as the Great Books program at Columbia University and the Athens-America program at University of Wisconsin (both in the 1920s), as well as the Experimental College at Berkeley in the 1960s. We will analyze their educational goals, read some of the books they assigned, and explore the viability of the Western Tradition as a usable past.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15506,2027,3989,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-217','<div class="desc"> <p>The 1960s marks a watershed moment in American history, leading to a reexamination of everything from U.S. Foreign Policy (Vietnam and the Global South), to race (the Civil Rights Movement and Black Power), to gender ("second wave" Feminism) and sexuality ("Free Love"). Culture was central to this transformative moment, contributing to a "counter-culture" that made distinct claims on our politics and even our most private modes of social interaction. If the "personal is political"--as the 60s mantra would have it--then something as seemingly ephemeral as "style" becomes a mode of resistance. Style as resistance was expressed in everything from slang of the time (summed up in the ubiquitous epithet of "cool"), to the theater of protest (and its ubiquitous musical soundtrack), even to something as seemingly ephemeral as dress and hair. In the process, the counter-culture of the 60s sought to rethink the nature of desire, the boundaries between public and private, the "multiversity" and the objectives of higher education, the participation of women and "minorities" in society--and most especially, what it meant to be young. The focus of the course will be on the 1960s, but we will explore the ways in which culture, politics and history interact. In particular we will examine the nature of cultural politics--its confusions and limitations as well as its liberatory potential--as an arena to address the era''s most pressing social concerns. Readings will include the seminal texts of the 1960s: "The Port Huron Statement, "<em>The Feminine Mystique, </em><em>The Autobiography of Malcolm X; </em>along the cultural implications of some of its notable events such as the March on Washington, Woodstock and the violence at Altamont. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15507,2027,3257,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-218','<div class="desc"> <p>No region of the country has been as saturated by mythology as the American West. It has been variously conceived as "empty," a "frontier," a "garden of the world," the divine realization of the nation''s "manifest destiny" (emblazoned in Occidental''s motto). That expansionist mythology not only ignored the environmental limits to what John Wesley Powell memorably described as an "impoverished landscape," it ran roughshod over the claims of indigenous peoples who lived there. This course will examine the various ways in which mapmakers, historians, writers and artists have tried to challenge that mythology by reimagining a different account (and future) of the American West. We will begin with reports from those on the scene like Hinmatoowyalahqit (Chief Joseph) and Powell, turn to the historiography of the region (from Turner to Limerick); and examine the efforts of photographers (Curtis, R. Adams, Misrach); artists (Heizer, Turrell, Martinez and Luna); writers (Muir, Solnit, Erdrich) and filmmakers (Zhao). Our investigation will linger on special regions and topics such as the efforts to map the West through early government surveys, the foundations of our national parks, the Nevada Test Site and the Cold War West, the damming of the Colorado River and Hetch-Hetchy, and the efforts by indigenous writers to rethink some of the West''s most infamous episodes (Welch, Vizener). We will also devote some time to examining the approach taken to public history by nearby institutions like La Purisima Mission, the Autry Museum of the American West, and the very different Center for Land Use Interpretation. Our goal throughout will be to follow the strategies by which these activists, historians, writers and artists attempt to transform a mythological <em>space </em>of "heroic individualism" and boundless appetite, into a <em>place </em>with a distinctive history, tradition, community--a place, that is, with claims on us of stewardship and accountability.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15508,2027,2934,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-219','<div class="desc"> <p>This is a topics course consisting of specialized courses that will focus on California, and particularly the Southern California region. <em>Different topics may satisfy different Core requirements.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15509,2027,1020,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-220','<div class="desc"> <p>This course provides an opportunity to vicariously "live" in historical cities considered to be creators of democratic or representative forms of government, as well as of great literature and art. Historian Thucydides, comic Aristophanes, and philosopher Plato draw us into Athenian gender/class socialization, politics, and culture; likewise, Boccaccio, the Medici family, and Machiavelli inform us of Florentine gender/class socialization, politics, and culture. Monumental architecture and gendered sculpture continue to serve to decorate and sustain the individuality of each city. By examining documents of daily life (including court cases concerning sexual acts) and the luxury products of the diverse crafts, we increase our knowledge of the controversial behavior and productivity of a wide spectrum of women and men. By focusing on two cities in their "golden age," the class will emphasize the shared positive, as well as negative, characteristics of ages historians have designated as "golden." </p> <p> <em></em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15510,2027,192,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-223','<div class="desc"> <p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">How do we define legitimate knowledgeâand who gets to decide? This course explores the shifting boundaries between science, magic, and religion from antiquity to the early modern period, tracing how practices like astrology, alchemy, and divination once stood at the center of intellectual life. Rather than treating science as a triumphant break from superstition, we examine an entangled history in which natural, celestial, and spiritual phenomena were understood as interconnectedâoften through shared principles like the Hermetic dictum </span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: italic; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">âas above, so below.â</span></p><p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">Moving chronologically from the ancient Mediterranean to the dawn of the Enlightenment, we explore traditions of natural philosophy, the occult sciences, and religious belief across Latin Christendom and the Islamic world. Emphasizing points of transmission, translation, and shared cosmological inheritance, the course challenges Eurocentric narratives by foregrounding Greco-Arabic knowledge systems and the broader Afro-Eurasian intellectual continuum. Students will analyze how contested categories like âmagicâ and âscienceâ were shaped by theological debates, philosophical commitments, and the institutional cultures of courts, monasteries, madrasas, and universities.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15511,2027,1172,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-224','<div class="desc"> <p>This course offers a chance to come to know a variety of individuals who lived in and travelled from the Italian peninsula in the 1300''s, 1400''s, and 1500''s. We shall journey to the Far East with Marco Polo; meet peoples of the Mediterranean; and "visit" the republics of Venice and Florence, the papal court of Rome, and the ducal courts of Urbino and Mantua. We shall enjoy distinctive creations in literature, education, philosophy, and the arts, and read letters about South American peoples from Amerigo Vespucci. Diplomat Machiavelli witnessed independent Italian city-states fall to French and Habsburg conquests and described such realistic politics; courtesan Veronica Franco successfully practiced her sexual trade while writing poems celebrating her true love, as well as her mercantile city-state. Students may petition for 300-Level credit for this class with the completion of additional work arranged with the instructor.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15512,2027,4443,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-225','<div class="desc"> <p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">This course explores the medieval Mediterranean as a dynamic space of both intense conflict and rich cultural coexistence and exchange. Spanning the seventh to seventeenth centuries, we examine the interwoven histories of Christians, Muslims, and Jews across Europe, North Africa, and Southwest Asia. While the Crusades often dominate popular narratives of this eraâemphasizing religious warfare and divisionâthis course offers a revisionist account that explores periods of </span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: italic; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">convivencia</span><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">: coexistence, collaboration, and mutual influence in science, philosophy, trade, and daily life.</span></p><p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 12pt"><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">We also decenter Latin Christendom to highlight the diversity of voices and power structures across the region. From Fatimid Cairo to Norman Sicily, from the libraries of CÃ³rdoba to the battlefields of Jerusalem, we critically examine the interdependence of empires, faiths, and ideas. Through close engagement with primary sources and critical scholarship, students will interrogate the very categories of âcivilization,â âholy war,â and âcultural contact,â and consider how these concepts continue to shape our understanding of the past.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15513,2027,1173,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-226','<div class="desc"> <p>A history survey of the 14th-18th centuries: Renaissance, scientific advance, global encounters in Spanish and English empires, the Enlightenment, and revolutions (English, American, French). The luxury of European palaces and curiosity cabinets was based upon the exploitation of European peasants and global indigenous peoples. Students seeking origins of feminist and natural rights arguments will consider protest pamphlets, women''s writings, utopian fiction, and enlightenment stories (some with film versions), which created empathy for others.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15514,2027,1525,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-230','<div class="desc"> <p>This course is a critical survey of some great ideas that have shaped Western civilization. We will consider, among others, Homer, Sophocles, the Pre-Socratic philosophers, Plato, Aristotle, Cato, Marcus Aurelius, the Hebrew Bible and the New Testament, the Scholastics, Machiavelli, Luther, Copernicus, Galileo, Bacon, Locke, Voltaire, Rousseau, Condorcet, Mary Wollstonecraft and Mary Shelley, Marx, Darwin, Nietzsche, Virginia Woolf, and Simone de Beauvoir.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15515,2027,4050,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-232','<div class="desc"> <p>This course examines the Holocaust as a historical event, as well as its continuing manifestations around memory, justice, and representation. We will trace the origins, implementation, and legacies of the persecution and mass murder of Jewish people by Nazi Germany and its allies and collaborators alongside the persecution and mass murder of Communists, Socialists, Sinti and Roma, disabled people, queer and trans people, Black people, Slavic peoples, and others in Nazi-occupied territories. Situating the Holocaust within the broader history of Europe and the world from 1919 to 1945, students will study the rise of fascism and the Nazi Party, the role of nationalism, antisemitism, and colonialism, the development of racist and eugenic policy, the context of war in enabling mass atrocity, and postwar processes of memory and justice. In addition to historical frameworks, this interdisciplinary course draws on methods and sources from Jewish Studies, Genocide Studies, Cultural Studies, Visual Studies, Memory Studies, and Critical Theory. Throughout, attention will be given to the potentials and pitfalls of documentary evidence, photography, and testimony; the politics of memorialization and representation; debates over uniqueness and comparison; and the roles played by gender, sexuality, race, religion, class, geography, and political ideology in shaping the experiences of both victims and perpetrators. Students will also have an opportunity to engage the landscape of Holocaust memory in Los Angeles, including institutions such as the USC Shoah Foundation, the Holocaust Museum Los Angeles, and the Museum of Tolerance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15516,2027,2655,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-233','<div class="desc"> <p>The turn to authoritarianism and rise of fascism in Europe between the First and Second World Wars represented a profound turning point in European politics and society, as nations from Italy to Hungary, Germany, to Greece became home to fascist regimes or movements. This History course studies the rise, function, and fall of fascism , especially as it existed in Mussolini''s Italy and Hitler''s Germany, between 1922 and 1945. In the period between World War I and World War II, new and alternative models for the relationship between state and society challenged the existing political and social order, as many Europeans abandoned democracy as the ideal political system. Many turned to nationalist authoritarianism as the answer to the political, economic, and social crises shaking Europe. Italy, under the National Fascist Party, and Germany, ruled by the National Socialists, were the nations in which this flight from democracy became a full-fledged descent into dictatorship and one-Â­party rule. This course examines authoritarianism and dictatorship in interwar Europe and we assess how the elevation of the state and the nation, promoted by these regimes and parties, impacted the societies involved.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15517,2027,193,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-234','<div class="desc"> <p>The class examines the political, social, and economic crises that shook the nations of Europe in the two decades following the First World War. In particular, we address the character of the crisis; the varied European responses to it; and the challenges represented by the end of the First World War, Depression, Fascism, the Second World War, and the Holocaust. While assessing the nature of the social, political, and economic crisis of interwar Europe, we will also pay close attention to historiographic debates on the rise and nature of Fascism and the origins of the Second World War. We focus strongly on primary sources such as the novels, film, and art of the era. Topics include: the "Lost Generation," the Weimar Republic, the Spanish Civil War, and the Popular Front in France.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15518,2027,1073,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-235','<div class="desc"> <p>This course examines the history of modern Europe with a focus on popular and state-supported ideologies of exclusion and violence in the long 20th century (spanning 1890-2011). Central to this course is a focus on the discursive boundaries of civil society based on race and class. Throughout the course, we situate European developments in a world-historical framework as a way to understand the increasingly interdependent political, social, and economic relationships between Europe and the colonial periphery. We begin in fin de siècle Europe, and trace the polarization of national politics and the development of the contending state ideologies of fascism and communism. We explore the consequences of various programs of decolonization, as well as the popular revolts against cultural diversity and post-colonial immigration to the metropole. The course also investigates the origins and consequences of the neo-liberal "revolution" of the 1980''s, the ethnic violence stemming from the disintegration of the Soviet Union and eastern bloc nations, and the return of the radical right throughout Europe in the 1990''s. Our course readings combine secondary and primary sources, literature, as well as a wide range of cinematic and musical sources, in order to understand the evolution of European notions of race, national belonging, and political violence.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15519,2027,613,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-237','<div class="desc"> <p>In early modern times, popular conceptualizations of the intersection of gender and sexuality, ethnicity/race, and rank/class divided women from each other. Activist advocacy for women emerged from a debate on women''s nature to a debate on opportunities for women: to be educated, to write, to speak out, to preach, to express one''s individuality in dress and demeanor, or to work in one''s chosen occupation. For the transformation in political theory from Lockean family representation to Suffragette individual representation in the state, we shall explore the literature on "rights" from Wollstonecraft to United Nations declarations on global Women''s Rights &amp; current revival of American movement for Equal Rights Amendment. We shall experience together a diversity of films as students discuss the intersectionality of race, gender, class, religion, and sexualities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15520,2027,194,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-242','<div class="desc"> <p>A chronological and thematic survey of the Chinese civilization from Neolithic times to about 1600. Major themes will include: the nature of the Chinese world order, family and lineage, gender issues, philosophical and religious transitions, political authority and its ideological underpinnings, dynastic cycles and broader patterns in socio-political movements, interactions with other civilizations, and the impact of technological and demographic changes over time. We shall use the comparative approach on specific themes to illuminate contrasts and similarities between Chinese and Western societies, and take note of recent archeological finds and new scholarly interpretations to better understand China''s dynamic past and rapidly changing present.</p> <p>Survey Requirement Met: <strong>Asia</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15521,2027,1603,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-245','<div class="desc"> <p>This course will look at the relationship of China to the world over the last 600 years. It will emphasize the global flow of trade goods and commodities, ideas and ideologies, and religions and people. And it will look at the shifting position of China within modern international relations, including a critical investigation of the Cold War, Thirdworldism, the environment and development, and neoliberal globalization. Students will gain a working knowledge of both Chinese and world history. They will be encouraged to question the narratives we tend to tell ourselves about world history and China''s role within it. This is particularly important as the level of interactions between China and the U.S. has been increasing markedly over the past few decades. We will call into question narratives of the "rise of the West," just as we will call into question the contemporary discourse on the "rise of China."</p> <p>Survey Requirement Met: <strong>Asia</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15522,2027,944,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-248','<div class="desc"> <p>This course covers the history of Japan from the 1868 Mejii Restoration to the present, with particular focus on the emergence of modernity, the Pacific War, and popular culture. The first section of the course will examine Japan''s modern revolution in the Mejii Restoration, industrialization and modernization in the Mejii Period, and the development of Japanese colonialism. The second section of the course will focus on the Pacific War, the bombing of Hiroshima and Nagasaki, and the American occupation, with particular focus on the politics of gender and race. The third section of the course will look at Japan''s explosive postwar economic recovery and the consumer and popular culture it produced.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15523,2027,196,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-249','<div class="desc"> <p>Korea is unique, or so say the Koreans. In many ways, it is. Politically, of the democratic nations in the world, South Korea is one of the precious few to have achieved democracy through the blood and sacrifice of its everyday citizens, that is, from the bottom up. Economically, after the Korean War, Korea was one of the poorest nations in the world, ranking below sub-Saharan countries in terms of GDP; now it is a member of the G20. This survey will begin with the forced opening of the "Hermit Kingdom" in 1872, and conclude with the 21st century international phenomenon of K-pop.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15524,2027,1660,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-251','<div class="desc"> <p>This course offers an introduction to the language, writing, and culture of the Nahuas (the Aztecs) in ancient and colonial Mexico. Students will learn elementary classical Nahuatl grammar and vocabulary. In addition, we will study Nahua pictorial and alphabetic writing systems, read major texts produced by Nahua intellectuals, and use a philological approach to study changes in Nahuatl over time. The Nahuatl texts will address a number of themes, including: history and cultural expression, Nahua gods and myths, ritual and sacred relations, and gender and power. The study of classical Nahuatl language texts, written in ancient and colonial times, are indispensable for understanding ethnohistorical methods and sources, and contemporary Nahua culture, language, and communities today. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15525,2027,1459,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-252','<div class="desc"> <p>This course offers a broad survey of Mexican religion from pre-Columbian times to the present. The course begins with the study of Nahua ("Aztec") spirituality and ritual and continues with an examination of major developments of the colonial period as indigenous European and African peoples came together with their many different beliefs and practices. We will study indigenous strategies of both resistance and accommodation to the imposition of Catholicism, the origins of the devotion to the Virgin of Guadalupe, the Mexican Inquisition, millenarian movements, missions, and women in the church in the colonial period. Our study concludes with the anti-clerical reforms of the late nineteenth- and early twentieth-centuries, the Cristero Rebellion, increasing influence of Protestantism, and the persistence of local religions in modern Mexico. Students will analyze historical documents, religious dramas, confessional manuals, Inquisition records, paintings, sculptures, and films in their examination of the history of religion and spirituality in Mexico.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15526,2027,2897,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15527,2027,4051,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-255','<div class="desc"> <p>Where are the borders between memory and history? Between testimony and representation? In this course, we will explore what happens to instances of political violence as artists, writers, and radicals record their stories over time. How do contexts of political violence shape art-making and how does art-making in turn shape contexts of violence? How do different media (poetry, novels, memoirs, paintings, films, music) translate violence and history differently? And what are the ethics of documentary work; can only certain people record certain stories? Each week, we will examine a different case study of political violence in Latin Americaâfrom the Treaty of Guadalupe Hidalgo to the Guatemalan genocide to the Pinochet dictatorship in Chileâthrough historical sources and works of art. We will gain access to marginalized historical voices through our analyses of artworks, restoring power, agency, and voice to those harmed by structures of political violence. Students will create their own artistic acts of witness to a case study of violence of their choosing.</p><p><br style="color: rgba(34, 34, 34, 1); font-family: Arial, Helvetica, sans-serif; font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0; text-transform: none; widows: 2; word-spacing: 0; white-space: normal; background-color: rgba(255, 255, 255, 1); text-decoration-style: initial; text-decoration-color: initial"/></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15528,2027,3112,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-256','<div class="desc"> <p>Since the fall of the Mexica (Aztecs) to the Spaniards in August of 1521, writers and artists have represented the dramatic events leading to the conquest of Mexico. Major figures of the conquest, such as Hernando Cortés, Malinche, Moteuczoma, and Cuahtemoc, have been memorialized, mythologized, and in some cases villainized. This course examines representations of the conquest and the leading figures of the period from a variety of perspectives. We will consider how changing political and cultural contexts have shaped remembrances of the war and the consequences of colonial rule. In this course, students will analyze a variety of sources, including Spanish and indigenous accounts, pictorial writings, paintings and artworks, operas and films. In addition, we will examine contemporary artistic projects, museum exhibitions, and archival programs that have been organized to commemorate the 500-year anniversary since the fall of the Aztec Empire.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15529,2027,197,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-258','<div class="desc"> <p>A complex web of historical ties has fundamentally shaped the political, economic and cultural development of both Mexico and the United States. Our aim will be to understand the roots and development of deep interdependency despite two centuries of relations marked by antagonism, exploitation and unilateralism. We will examine how five key historical episodes in Mexico-U.S. relations, including the U.S.-Mexico War, the Mexican Revolution, the Interwar Years, the Bracero Program, and the Cold War, shaped conflict and cooperation and impacted the everyday lives of Mexican and U.S. citizens. In the last third of the course, we will focus on three contemporary issues - immigration, trade and the environment â to understand how the past has shaped the present.</p> <p>Survey Requirement Met: <strong>Latin America</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15530,2027,3227,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-259','<div class="desc"> <p class="MsoNormal">This course traces the intersection of U.S. migration and health histories from the late nineteenth century to the present. The course will be organized around historical case studies including medical inspection and quarantine of Southern and Eastern European and Asian immigrants at Ellis and Angel Islands and Mexicans at the U.S. border in the 1890s-1930s; race and epidemics in early twentieth century cities; mental health of European and Latin American political refugees in the post-World War II era; farm worker health and environmental justice movements since the 1960s; forced deportation of Caribbean migrants for HIV-positive status during the AIDS pandemic; maternal and reproductive health in post-1990s detention centers; and mutual aid during the COVID-19 crisis, among others. Taken together, students will discern how migration serves as a determinant of health, and also learn about migrant resilience despite structural violence. The themes of medical racism and scapegoating, contagion narratives, occupational health, health movements, cross-cultural health communication, and medical citizenship will anchor course units. With particular attention to the analytical categories of race, ethnicity, gender, sexuality, and class, the course posits that history can make a critical contribution to our understanding of health inequities and to the development of migrant health justice. Students will gain skills in archival research, oral history methodologies, and digital storytelling, and they will be given the opportunity to participate in community-based engagement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15531,2027,945,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-274','<div class="desc"> <p>From its earliest written records in ancient Mesopotamia and Egypt, medicine flourished through Greece and Rome, was then kept alive during the medieval golden age of Islamic science, then reawakened during the Renaissance, Scientific Revolution and Enlightenment in Europe, and then crossed the Atlantic to America where indigenous wisdom already thrived. This course traces the history of medicine through these different times, cultures and regions: theory and practice; great doctors and healers, both male and female; and the effects of epidemics, such as the Black Death, on the course of Western civilization. We will end with some historically based speculations about the medical future.</p> <p>Survey Requirement Met: <strong>Europe</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15532,2027,198,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-277','<div class="desc"> <p>This course explores reproductive politics and reproductive health in North America/U.S. from the 17th to the 21st century using the lens of Reproductive Justice (RJ). RJ is a practice, a theory, and a movement conceptualized by women of colorâand particularly Black womenâin the 1990s. Its tenets include three interrelated values: the right <em>not</em> to have children, the right to <em>have</em> children, and the right to <em>parent</em> children âin safe and healthy environments.â (Loretta J. Ross, 2017). The course centers the intellectual and organizing work of women of color who have led the struggle for reproductive justice and community wellbeing. Using an intersectional RJ framework, the course examines histories of midwifery, abortion, contraception, and sterilization as well as social movements for reproductive rights and community health. Through historical documents, first-person accounts, films, and interdisciplinary scholarship, we will analyze how colonialism, enslavement, and constructions of racial and gender inequality shaped lived experiences of reproductive injustice in contexts of environmental and institutional precarity. One important goal of this course is to make connections between historical studies of reproductive health and present-day RJ activism through involvement in a community based collective research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15533,2027,199,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-282','<div class="desc"> <p>The term "Muslim World" is often criticized as imprecise. After all, Muslims constitute a fifth of humanity and live on six different continents. Nevertheless, Muslims often describe themselves as constituting a single community with shared sets of concerns. This class engages these differing views through an examination of the lives of Muslims over the past two centuries of globalization, colonialism, post-colonialism, nationalism, and ever-changing technologies of transportation and communication. Our inquiry will concentrate on how Muslims were caught up in, and reacted to, and, in turn, influenced the Great Transformation that reshaped the entire world over the past two centuries. Dealing with issues from state building to women''s rights to radical militancy, this class considers the various features of what we might call Muslim Modernity.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15534,2027,849,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-283','<div class="desc"> <p>This course examines the role of peasants and tribal formations in the process of nation and state building in the modern Middle East. In addition to looking at some of the empirical and theoretical problems inherent in defining and writing about "peasants" and "tribes," we will also consider how nationalism complicates these issues even more. We will investigate the ways that rural populations were incorporated into, or excluded from, the processes of state-formation. Finally, we will look at how representations of peasant/tribe, in ideologies of state-building and nationalism, shaped social and political relations within some of the region''s nation-states. While we will discuss the region as a whole, we will focus most of our attention on two empirical cases: Iraq and Egypt.</p> <p>Survey Requirement Met: <strong>Middle East and Africa</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15535,2027,4017,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15536,2027,200,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-295','<div class="desc"> <p>Specific topics may satisfy different Core Program requirements.</p> <p><strong>City of Lights: A Global and Spatial Urban History of Paris</strong></p> <p>What if we understood the times people lived through by exploring the sites and spaces that they have lived in? This course moves through selected sites in Paris â as well as global sites connected to the city â to understand how built and natural urban environments reveal connections to a multiplicity of pasts that shape how urban residents understand their place in their community. We will consider landmark buildings, but also streets, slums, domestic spaces, as well as ephemeral, temporary, or imagined structures. In this way, students will reflect on how urban spaces can reflect and reinforce power structures, how marginalized people have resisted those structures by transforming spaces, as well as how national and local histories should be preserved in urban public spaces. At the same time, students will become familiar with key events in the history of France and the world from antiquity to the present day. As well as written assignments and discussions, students will create maps and timelines that engage with the course themes. <em>This topic meets the Regional Focus (CPRF) and pre-1800 (CPPE) requirements</em>.</p> <p><strong>Crime and Punishment in Russian History</strong></p> <p style="margin-left: 0; margin-right: 0">Crime and punishment constitute not only the title of a classic Russian novel, but an enduring theme in Russian history. Russian art and literature are rich in scenes of exile and incarceration, and the history of a modernizing stateâs efforts to control both crime and dissent through judicial systems reveals the shifting boundaries of its power over its people. At a moment when Americans are increasingly questioning policing and mass incarceration in their own country, this course offers students a way to understand how crime and punishment have been constructed in a different historical context.</p> <p style="margin-left: 0; margin-right: 0">Russian and Soviet practices of punishment have often embodied acute clashes of values between different social, national, and ideological groups. Actions deemed criminal by one group may be seen as justified, even admirable, by another. The course will deepen studentsâ understanding of those values as well as familiarizing them with the lived experiences of people whose circumstances or convictions led them to courts, exile, and incarceration. Using novels, poetry, memoirs, film, archival and visual materials, we will consider such questions as: How did peasants avoid or invoke the Tsarist state to order their communal lives? How did revolutionaries use the jury trial to propagate their ideas? Why did Marxists believe that a socialist state would have no need for a legal system? How did prisoners in the Gulag make sense of their experiences? How have crime and corruption shaped post-Soviet society? Assessment will include participation in class discussion, short written assignments, and a final project. <em>This topic meets the Regional Focus (CPRF) requirement. </em></p> <p style="margin-left: 0; margin-right: 0"><strong>Russian and Soviet History Since the Nineteenth Century</strong></p> <p>This course covers an epic set of events in Russian history from the emancipation of the serfs in 1861 to the rise of Vladimir Putin in the 21<sup>st</sup> century. Spanning a century and a half of upheaval and transformation, it examines what happened when workers and peasants tried to create a new society built on social justice and economic equality. The course surveys the revolutions in 1917, the ruthless power struggles of the 1920s, the triumph of Stalin, the costly industrialization and collectivization drives, the âGreat Terror,â and the battle against fascism in World War II. It then examines the Cold War, the Soviet Unionâs efforts to reform itself, the economic chaos of the 1990s, and resurgent nationalism and authoritarianism in the information age. Weâll reflect not only on high politics and power struggles, but also on how everyday life and culture developed in times of unprecedented change. <em>This topic meets the Regional Focus (CPRF) requirement.</em></p> <p><strong>United States Presidents and First Ladies</strong></p> <p>This course provides an overview of the origin and subsequent development of the position of U.S. President and that of First Lady from the eighteenth century to the present. The class meetings center around significant U.S. Presidents: George Washington, Thomas Jefferson, Andrew Jackson, Abraham Lincoln, Theodore Roosevelt, Franklin D. Roosevelt, John F. Kennedy, and Ronald Reagan. In addition, we will consider historically important First Ladies: Martha Washington, Dolley Madison, and Eleanor Roosevelt among them. Special attention will be paid to how the offices of the U.S. President and First Lady have evolved over time; when U.S. Presidents and First Ladies have provided leadership in moments of national crisis; and what Americans have come to expect of their leaders.</p> <p><strong>A History of Native California </strong></p> <p>We are in the middle of a dramatic resurgence in popular attention to Native American issues. While it may seem sudden, this moment is best understood as the culmination of a long, and often forgotten, history of persistent Native resistance and activism. This course explores that history by focusing on the place we now call California. It tracks the early Native history of the region, and the development of Indigenous cultures deeply embedded in the unique California landscape, the coming of European settlers, and the establishment of the Franciscan mission system and its eventual collapse. It directly addresses the violence perpetrated against California Natives in the mid-nineteenth centuryâthe clearest case of genocide in American history and something every American must confront. It carries the story into the twentieth century emphasizing the ways in which Native People survived and built the foundations for the resurgence that we see today. The course uses the greater Los Angeles area as one of its texts. We will be engaged in individual guided walkabout exercises, as well as occasional class site visits. Our focus in each will be the various ways in which the city continues to reflect its settler colonial past.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15537,2027,4252,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/200/hist-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15538,2027,206,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/copy-of-hist-395','<div class="desc"> <div> <p><strong>The Democrats, Jefferson to Biden</strong><br/> This course proceeds from the assumption that the history of a political party still matters to the course of the United States of America in the 2020s. As such, we will investigate the key lives, events, and movements that have shaped the Democratic Party, from its founding in the 1790s through the present day. At the same time, given the Democratic Party’s troubled legacy on questions of race, gender, sexuality, and class, the usefulness of the party as a vehicle for societal change must be questioned. The course will attend to these concerns by studying the party’s most important leaders, conventions, elections, and movements. Together we will learn how a history of a political party—and especially of who is included and who is excluded—reveals the contours of American democracy itself.<br/> Core Requirement Met: United States Diversity<br/> <br/> <strong>American History According to Hollywood</strong><br/> This class investigates the way movies have shaped Americans’ understanding of their history. Surveying major developments across the twentieth century and into our own, we will examine films as imaginative primary sources that reveal the attitudes and anxieties of past eras (e.g. concerns about race and ethnicity, global power, gender and sexuality). The last third of the class will turn to a more intensive focus on the way movies have functioned as secondary sources, offering powerful (if partial) interpretations of earlier eras. Here students will focus on a select number of topics or events (e.g. the immigrant experience, WWII, “the West”) and trace the changing historical interpretations the films present. Ultimately, we will evaluate how “cinematic history” compares to “written history” and by what interpretive or evidentiary standards or criteria we should evaluate it.<br/> Core Requirement Met: United States Diversity<br/> <br/> <strong>Disneyland and Los Angeles</strong><br/> In the summer of 1955, amidst the orange groves of Southern California and next to a brand-new freeway, Disneyland Park appeared. Broadcast across the country through a hit television program that premiered the previous year, the new theme park became an instant national media sensation, drawing on a long and varied tradition of American popular amusements. But, it was also an institution with deep roots in the specific culture and history of greater Los Angeles itself. In this course, we will trace the complex dialogue between the iconic amusement park and its urban environment in Southern California over the last half of the 20th century, carefully analyzing urban and social history, film, and literature to discover what Disneyland can teach us about the history, built environment, and culture of the strange, sprawling megalopolis that surrounds it.<br/> Core Requirement Met: United States Diversity<br/> <br/> <strong>National Parks/Native Land</strong><br/> This course examines a fundamental paradox in American society: That every National Park, National Forest, National Monument, or other form of federally protected land is Native land, and in almost all of those cases, it was acquired by the United States government through less than fully legal means, if not outright theft. At the same time, the National Park System is a national treasure. Perhaps both can be true, but certainly not without problematizing the claim made by Ken Burns that the park system was “America’s Greatest Idea.” To do this, we will explore the origins of the National Park system in nineteenth-century conservation and wilderness preservation movements, which were themselves deeply embedded in the ongoing dispossession and erasure of Native People endemic to settler colonial societies. We will also look at the various ways the NPS has struggled to honor its original mandate: “to conserve the scenery and the natural and historic objects and wildlife... and to provide for the enjoyment of the same in such manner and by such means as will leave them unimpaired for the enjoyment of future generations.” Providing access to parks, while conserving them in a manufactured state of “nature” is both challenging and false. These spaces were not empty, but emptied. Some have now become crowded again with tourists, creating additional difficulties for the NPS. Course readings will highlight a few of the efforts to address this tension. Additionally, our readings will highlight ways in which Native activists, allies, and the federal government itself have begun to challenge that erasure.</p> </div> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15539,2027,201,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-300','<div class="desc"> <p>This course introduces students to the practice and writing of history through topical approaches. Students will explore methodological approaches to historical inquiry, conduct research projects, and improve their writing skills. Open to majors and minors only or by permission of instructor. Topics include:</p><p><br/></p><p><strong>Rethinking the History of the American West</strong></p><p>No region of the country has been as saturated by mythology as the American West. It has been variously conceived as "empty," a "frontier," a "garden of the world," the divine realization of the nation''s "manifest destiny" (emblazoned in Occidental''s motto). That expansionist mythology not only ignored the environmental limits to what John Wesley Powell memorably described as an "impoverished landscape," it ran roughshod over the claims of indigenous peoples who lived there. This course will examine the various ways in which historians have tried to challenge that mythology by reimagining a different account (and future) of the American West. We will begin with Frederick Jackson Turner''s Frontier Thesis which argued that the frontier was the defining feature of our national life. The currency of that thesis lasted far longer than one might imagine before it was successfully challenged by a number of revisionist historians. This has led to a robust debate which has sought to transform the West from its mythological beginnings into a <em style="margin: 0; padding: 0">place </em>with a distinctive history, tradition, community--a place, that is, with claims on us of stewardship and accountability.</p><p><br/></p><p><strong>U.S. Immigration History</strong></p><p>What does it mean to say that the United States is a ânation of immigrants?â This course explores how historians have written about migration to and im/migrants in the United States, including what it means to understand migrants as settlers participating in Native American dispossession and removal. Topics include migrants and settler colonialism, the legal and political foundations of U.S. citizenship, the creation of the U.S.-Mexico border, the origins of illegal immigration, ethnic and racial identity, state power and resistance, popular culture, social movements, and the importance of race as well as gender and sexuality in shaping immigration policy and its enforcement. Special attention will also be given to involuntary migrations, including those of enslaved migrants, refugees, and displaced persons.</p><p><br/></p><p><strong>Christianity and Politics in America since 1945</strong></p><p>Evangelical voters and white Christian nationalism have become hot topics, but religion has long played an important role in the U.S. political arena. This junior historiography seminar will survey how historians have written about the relationship between Christianity and politics in America since the end of World War II. We will explore the role of the Protestant church in public life, Billy Graham''s rise to fame, and the work of Christians and other religious leaders in shaping U.S. Cold War policy and engagement with the world. We will also give attention to different histories of the Religious or Christian Right and its 1970s marriage with the Republican Party, which has become one of the most successful political partnerships in American history. Finally, we will consider histories charting Christians'' role in national debates over civil rights, immigration and refugee policy, LGBTQ+ movements, and environmental justice.</p><p><br/></p><p><strong>Native American and Indigenous Histories</strong></p><p>This historiography seminar examines the sources, methodologies, and theoretical approaches that scholars use to write Native American and Indigenous histories. The course highlights the field of ethnohistory, the interdisciplinary study of indigenous societies and cultures that draws from history, anthropology, archaeology, linguistics, and art history. The readings address the histories of First Nations peoples of North America, Central America, and South America, and explore a variety of topics, including native governance, sovereignty and resistance, lands and removals, wars, indigenous slavery, relations with the environment, gender and sexuality, and reproductive rights. The course is organized to illustrate major trends in ethnohistorical scholarship, and highlight shifts in themes, methods, and narrative frameworks over the last five decades.</p><p><br/></p><p><strong>Mexico-U.S. Borderlands</strong></p><p>Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. Cross-Listed as: LLAS 304</p><p><br/></p><p><strong>The Fascist Revolution: Politics Culture and Society</strong></p><p>This seminar closely studies the period known as Fascist Italy (1922 to 1945). Through a close analysis of the politics, culture, and society of Italy under Fascist dictatorship, we study the causes, character, and ramification of the Italian abandonment of democracy in the wake of World War I. Because it is a historiographic seminar, we examine the central debates of the field, such as whether Mussolini ruled primarily through coercion or consent, the extent of Fascist race ideology, and whether the regime was "modern" or "backward-looking." Other major themes include: Fascist cultural modernism, gender and Fascism, and the Italian road to empire and World War II. This course uses primary sources such as translated documents, memoirs, and diaries, as well as contemporary historical analyses.</p><p><br/></p><p><strong>Gender and Sexuality in Colonial Latin America</strong></p><p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.</p><p><br/></p><p>Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written. Cross-Listed as: LLAS 301.</p><p><br/></p><p><strong>Histories of the French and Haitian Revolutions</strong></p><p>Many histories have been, and continue to be, written about these revolutions and they differ from each other substantially. This course examines this scholarly literature, taking into account the choices historians make as they compose their narratives. We will examine the roles of race, class, and gender in these accounts, why different events and social groups are featured centrally in some but not others. And we will consider such controversial criteria as "accuracy," "truth," "evidence," and even "fact" all of which are interpreted in numerous ways within the historian''s craft.</p><p><br/></p><p><strong>Histories of U.S. Empire</strong></p><p>Was/Is the United States an empire, and if so, what kind of empire was/is it? This upper-level colloquium will familiarize history majors and other advanced students with scholarly debates over the history of U.S. imperialism and engagement in the world. Course readings draw from the writings of U.S. historians from the early twentieth century through the present. Particular attention will be given to the impact of the Cold War and the influence of the "cultural" and "transnational" turns on how historians have approached empire.</p><p><br/></p><p><strong>Interpreting Civil War, Emancipation, and Reconstruction</strong></p><p>This junior colloquium will address major debates and approaches within the historiography of the United States Civil War, Emancipation, and Reconstruction. Students will explore how American racial politics and new scholarly approaches have shaped major debates over the causes and consequences of civil war and national reconstruction. The class will take both a chronological and topical approach to historiographic analysis. We will begin by reading work from the Dunning School and critical challenges to Dunning from historians on the Left, such as W. E. B. Du Bois in his 1935 study Black Reconstruction. To understand the impact of new methods and sources, we will examine the multi-decade collaboration of social historians called the Freedmen and Southern Society Project. In the second half of the course, we will explore more recent trends in scholarship, including economic history and cultural history, as well as gender and sexuality studies and critical race theory. Finally, the class will conclude by considering historical interpretations of Civil War and Reconstruction in U.S. popular culture, through film, fiction, and drama. Students will write their own historiographic analysis on a chosen topic within Civil War, Emancipation, and Reconstruction scholarship.</p><p><br/></p><p><strong>The Mexican Revolution</strong></p><p>Studies of the Mexican Revolution have been at the forefront in the development of modern Latin American social, political, and cultural history. The studies have also contributed to comparative discussions in world history about the meanings of revolutionary experience in the twentieth century. However, historians and other social scientists have reached no consensus about the Mexican Revolution from its periodization to its actual existence. This seminar will examine the competing set of interpretations, alongside primary sources, to analyze the origins, course, and legacy of the Mexican Revolution. Prominent historiographical themes for the course include: conflict between elite liberalism and mass mobilization; agrarian reform and unionization within a capitalist project of development; corporate representation of social interests; the institutionalization of revolution; race, gender, and class in nationalist rhetoric; and the role of art, education, and science/technology in state formation. Cross-Listed as: LLAS 302</p><p><br/></p><p><strong>Re-Assessing European Global Encounters</strong></p><p>The twentieth century national movements of liberation, from modern European colonialism, initiated new histories of the previous early modern age of exploration (1300-1800), from the point of view of the enslaved, the conquered, the exploited, and the newly liberated. Each student will be writing a historiographical essay revealing changing interpretations of one distinctive global encounter. Historians are re-assessing, on the Mediterranean, both the Crusades and piracy and kidnapping. Scholars specializing in trade or colonialism of a particular nation-state, such as Portugal, Spain, Netherlands, England, and France are re-considering specific settlements and trading ports on the Atlantic and Pacific Rims. Class work will enhance student skills: we shall be discussing exemplary recent historical films and histories and we shall learn how to efficiently find diverse viewpoints through online and printed sources.</p><p><br/></p><p><strong>Reel History</strong></p><p>This course will examine some of the ways that the history of France has been represented in films. Joan of Arc, The Return of Martin Guerre, Ridicule, The Rise to Power of Louis XIV, Danton La Nuit de Varennes, Abel Gance''s Napoleon, and Night and Fog are among the great movie classics to be analyzed. We will also deal with recent theoretical work on "historical" cinema. Are images as valid as written text when making meaningful connections with the past?</p><p><br/></p><p><strong>Writing the History of the Middle East</strong></p><p>This course is a junior seminar on recent developments in the research and writing of history as practiced by professional historians of the modern Middle East. We will look at the history of historical writing about the region and the transformative developments in the field over the last thirty years or so. The objective is to cultivate your awareness of historiography and historical criticism. Historiography can be defined as the history of historical interpretation. Historical criticism refers to how we understand history as an object of study. To appreciate various modes of inquiry in the field, we will read exemplary texts embodying established traditions and new departures as well as critical works on the ideological roots of particular fields of history.</p><p><br/></p><p><strong>Writing World History</strong></p><p>This junior seminar investigates various approaches to writing world history. The course is designed to help history majors understand historiography and historical criticism. By studying recent approaches to world history, students will learn how historical debate shapes the writing of history, how historians approach and critique each other''s work, and how different styles of historical research and writing have developed over time.</p> </div>','Unless otherwise noted, one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15540,2027,4444,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-305','<div class="desc"> This course explores the Islamic Golden Age as a period of extraordinary intellectual, cultural, and scientific flourishing spanning roughly the 8th to 16th centuries. We trace its beginnings in the Abbasid translation movement—where Greco-Roman, Persian, and Indian texts were rendered into Arabic—and follow the dynamic development of philosophy, theology, medicine, astronomy, mathematics, literature, and the arts across Islamic empires from Spain to Central Asia.<br/> Rather than viewing the Mongol invasions of the 13th century as a terminal point, this course interrogates the Eurocentric narrative of “decline” and instead examines the persistence and transformation of Islamic intellectual life across time and region. Through close engagement with primary texts and modern scholarship, we will encounter thinkers such as Ibn al Haytham, Ibn Sina (Avicenna), al-Ghazali, Ibn Rushd, Ibn Khaldun, and many others, while also attending to lesser-known voices, including women, mystics, and court scholars.<br/> Students will explore how Islamic intellectual traditions engaged with earlier knowledge systems, shaped global developments, and continue to resonate today. Alongside philosophical and scientific treatises, we will read poetry, theological debates, travelogues, and historiography—building a capacious view of Islamic thought and its many afterlives. </div>','HIST 121 or HIST 225 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15541,2027,1174,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-309','<div class="desc"> <p>This course examines the southern region of the United States as a “slave society,” that is, a society in which: 1) a system of enslaved labor and human commodification drove the region’s economy and 2) a powerful slaveholding minority held the reigns of political power. How did this minority white ruling class maintain their power over a large enslaved population (1 in 3 southerners by 1860) and a majority of non-slaveholding whites (3 out of 4 white southerners by 1860)? How did enslaved women and men create community, build solidarity, chart insurgent geographies, and establish a political tradition of resistance in the face of arbitrary and institutionalized violence? We will examine the rise of chattel slavery, its importance in American capitalism, and its impact on southern households, political institutions, religion, and cultural practices. Our readings will explore how a white supremacist system of transgenerational human property shaped the social relations and lived experiences of enslaved African Americans, common whites, slaveholding planters, and Indigenous nations of the South. How did these groups of southerners use religion, violence, and ideologies of sex, gender, race, and class either to challenge or reinforce existing power relations? How was the US nation as a whole complicit in the perpetuation of chattel slavery? Finally, how does the US as a nation continue to reckon with the legacies of chattel slavery in contemporary social movements, law, and culture? Course materials include primary documents, first-person narratives, film, music, and groundbreaking historical scholarship.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15542,2027,2629,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-311','<div class="desc"> <p>Americans have long idealized the frontier as an untrammeled backcountry, a mythologized landscape of “cowboys and Indians”, prairie and homesteaders, ranchers and sodbusters. In this course, we will draw on colonial and postcolonial theory to reinterpret these stories in the historical context of a set of encounters involving the Americas and the Americans - native and immigrant, from Europe, Asia, and Africa - with the rest of the world, contacts that began in 1492 and are still going on today. In the process, we will explore a diverse array of borderlands between people, environments, mythologies, and histories - spaces of interaction and reinvention. But these borderland spaces are fragile; contact zones devolve, again and again, into conquest, domination, genocide, and empire. Although this is a transnational phenomenon, this course is primarily concerned with the frontier in North America and particularly in the American West and in California. Along the way, we will also be doing our own original archival research, so students will have a chance to make their own mark upon the long history of the American frontier experience.</p> </div>','HIST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15543,2027,615,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-312','<div class="desc"> <p>The circulation of labor goods people and cultures between Africa, Europe and the Americas created an Atlantic World whose history transcends continental and national boundaries. This course examines the relationship between race rights and revolution during the Atlantic Age of Revolution that stretched from roughly the mid-eighteen to mid-nineteenth centuries. In particular we will explore how Revolutions in British North America, France and Haiti influenced the movement to end the slave trade and slavery in the Americas and galvanized slave revolts and other movements for Black liberation and human rights around the Atlantic World. A variety of readings including autobiography social and political history and ethnography will illuminate not only the history of the Atlantic World but new forms of scholarly writing that break the mold of national historical narratives. Themes include: slavery slave revolt the discourse of human rights resistance religion labor and shifting ideologies of difference in particular gender class and race.</p> </div>','One History course or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15544,2027,4031,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-315','<div class="desc"> <div><p>This course examines the history of U.S. public health from its colonial period to the twenty-first century. We ask how politics of gender, sexuality, race, class and religion have shaped health care policies and practices at particular moments in U.S. history. Taking an interdisciplinary approach, the class will explore topics such as reproductive health, eugenics, experimental research, and societal responses to epidemics and pandemics. We will examine how public health measures at times functioned as mechanisms of social control to reinforce existing inequalities while, at other times, health justice health movements have aimed to dismantle inequalities within the body politic. Students in this upper-level course will have an opportunity to explore their own interests within U.S. public health history by conceptualizing, researching, and writing a final research paper. </p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15545,2027,2630,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-316','<div class="desc"> <p>When we think of the World War II era and its aftermath in Southern California, images of freeways, airy tract homes, and classic Hollywood glamour often jump to mind. If we look a bit deeper, the Zoot Suit Riots, the scandal of Chavez Ravine, the destruction of public transit, and other more complex, and often "noir" images might emerge. Yet beneath both sets of images lie a set of crucial social, demographic, and political changes that marked Los Angeles''s emergence as an industrial, as well as cultural, center - changes that put the city on the front lines of many struggles revolving around Civil Rights, housing, and the future of American urbanism itself. In this class, we will explore the sunshine and the noir of mid-twentieth century LA, focusing on the ways cultural forms (such as the Central Avenue Jazz Renaissance, film noir, and modern architecture) crystallize crucial postwar social and political battles within this complex modern metropolis.</p> <p>Basic knowledge of twentieth century U.S. History is strongly suggested, but may be waived in exceptional circumstances.</p> </div>','HIST 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15546,2027,851,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-330','<div class="desc"> <p>The Storming of the Bastille, the Great Fear, the Women''s March, War with the rest of Europe, the September Massacres, the King''s trial and execution, Robespierre''s Republic of Virtue, the Reign of Terror, the Thermidorian reaction, the rise and fall of Napoleon, the impact of the rhetoric of revolution overseas, the end of slavery in France''s colonies, the transformation of French colonial Saint Domingue from slave colony into the new nation of Haiti, and the meaning of "liberty, equality, fraternity" for our own time.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15547,2027,204,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-336','<div class="desc"> <p>This course traces the creation and development of the modern Italian nation state from an idea in the early 19th century through its creation in the middle 19th century to its turn to fascism in the 20th century. We will study the challenges faced by Italian politics and society as Italy moved from a disparate group of separate states toward a unified government and culture. We take an interdisciplinary approach to history and look at films, novels, and art to understand the character of modern Italian culture society, and politics. Starting in the late 18th century, the course covers themes such as: the character and legacy of Italian unification, the Southern Question, Fascism, the Mafia and postwar parliamentary democracy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15548,2027,4253,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-338','<div class="desc"> <p style="margin-left:0in; margin-right:0in">This course explores the relationship between Italian history and Italian cinema from World War II to the present. We will study the major Italian films of the years 1930 to 2015 in order to understand economic, social, and political change in Italy. We will begin with the films of the Fascist era as way to analyze the relationship between propaganda and culture. After that we will focus on the Neorealist movement of the 1950s and its relationship to postwar reconstruction and the new Italian democracy. The class will cover the films of the 1960s with their focus on both prosperity and continuing social suffering and then those of the 1970s as a lens into the political tensions and political violence that dominated Italy. We will conclude with attention to representations of the corruption and collapse of the First Republic in the 1990s and 2000s. We will evaluate the films in the light of aesthetic and historic precedent, as well as interpretive debate. The film movements addressed will include neo-realism, the auteur movement, and commedia all''italiana. We will ask a series of questions about film as a historical tool and about the unique possibilities of film as a lens onto modern society.</p> </div>','One History course, or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15549,2027,1703,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-344','<div class="desc"> <p>One of the fastest growing economies in the world and most rapidly urbanizing society, China has risen to a central role in the world today. Yet, this rise has been fraught with problems and tensions that threaten its continued development. This course looks at the social, political, cultural, environmental, and economic development of contemporary China (from the 1970''s to the present), and asks us: how do we know contemporary China? This is a hands-on research course in which students will learn how to find, evaluate, and use sources to understand present-day China from an interdisciplinary perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15550,2027,1022,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-345','<div class="desc"> <p>This course will be a research seminar that confronts the history of the Holocaust through in-depth investigations into survivor testimonies and commemoration and memorialization. The course will examine the genocide of the European Jews by the National Socialist regime, introduce students to the history of Europe from 1919 to 1945, and raise questions about the moral and ethical legacies of the Holocaust. During the semester, we will use a variety of visual and written sources to document and analyze the systematic and bureaucratic murder of European Jews by the Nazis. Using the survivor testimonies archived at the USC Shoah Foundation Visual History Archive and the museum installation at the Museum of Tolerance, we will interrogate the emerging fields of witnessing and testimony in relationship to the memory of the Holocaust and the phenomenon of Holocaust commemoration and memorialization. We will ask questions about how individuals and society assimilated to the experience of genocide: what narrative choices, what linguistic choices, and what visual choices did survivors and the larger culture make when remembering and commemorating the Holocaust? In this way, the course will be interdisciplinary, combining the methods and sources of History, Jewish Studies, Cultural Studies, and Art History.</p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15551,2027,2342,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-346','<div class="desc"> <p>China is now undergoing one of the fastest rates of urbanization in world history. Just thirty years ago, about 80% of the Chinese population lived in the countryside, mostly working in agriculture. Today, China''s population is over half urban, and the CCP has announced a new plan to speed up the urbanization process so that by 2020, 60% will be urban. Furthermore, well over 100 million migrants travel back and forth between the countryside and the city each year. While these numbers are impressive in and of themselves, it can be hard to understand what they mean for individuals, for particular social groups, and for the changing rural and urban landscapes. Nonetheless, this shift from a predominantly rural population to an urban focused society is both ambitious and fraught with problems. This class aims to give an in-depth and upÂ­-close look at this amazing social transformation through readings, class lectures, film, research projects, and, most importantly, in-country experience. This course begins with a short semester on campus at Occidental and continues with a threeÂ­-week trip to China, including a homeÂ­stay with a rural household. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15552,2027,2597,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-348','<div class="desc"> <p>This course will look at the long 1960s in China and their relationship to and influence on the global 1960s. Beginning with the rise of Third-Worldism in the mid-1950s and ending in the 1970s, this period of radicalism reached its height with the tumultuous Cultural Revolution in China (1966-1969). Through memoirs, primary source material from the time, film, and secondary sources we will investigate why after years of political and economic consolidation the People’s Republic of China underwent such a dramatic and chaotic political upsurge. We will end the course by looking at the influence of China’s Cultural Revolution on the radical 1960s movements of the world, in particular in the United States and France and peasant movements in the third world.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15553,2027,852,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing especially on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization, art forms, social structure, and religion in the colonial and modern periods and considers native responses to contemporary issues such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15554,2027,1604,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , or UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15555,2027,2690,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , UEP 101 , or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15556,2027,618,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-385','<div class="desc"> <p>One of the most consistent “commonsense truths” about the Middle East and North Africa (MENA) region one encounters is that tensions generated by mutually antagonistic sectarian identities produce eruptions of political violence and civil strife. According to this view sectarian (and ethnic) identities are static and consist of an unchanging essential core not only independent of historical, political and economic developments, but indeed even <em>generative</em> of them. For some, the Lebanese Civil War of 1975-1990 seemed to confirm the “sectarian thesis” about the Middle East. Indeed, the war-torn Lebanese capital, Beirut (divided as it was between an eastern “Christian” enclave and a western “Muslim” enclave), became a metonym for sectarian conflict. Using the Lebanese Civil War as a case study, this class will test the “sectarian thesis” of identity formation in the MENA region.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15557,2027,4445,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-388','<div class="desc"> This course explores Africa as a pivotal—though often marginalized theater—in the Cold War—the geopolitical struggle between the United States and the Soviet Union for absolute political, economic and military dominance. Moving beyond traditional narratives centered on superpower rivalry, this course reframes the conflict as a global struggle for decolonization and economic and political sovereignty waged by nations of the Global South against the imperial domination of the Global North. Foregrounding African agency, we examine how African states and movements challenged foreign intervention, economic dependency and Cold War realpolitik through radical projects of anti-colonial worldmaking, revolutionary socialism and radical pan-Africanism. We also investigate how states managed and contested control over Africa’s immense natural resource wealth—a central theme of the Cold War–and how they resisted, negotiated and redefined competing visions of the continent’s future. Ultimately, this course invites students to rethink the Cold War as a global history of liberatory struggle to reclaim political and economic autonomy and to remake the postcolonial world through revolutionary ideologies and transnational solidarity. </div>','BLST 180 or BLST 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15558,2027,205,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-390','<div class="desc"> <p><strong></strong></p> <p> Research topics vary semester to semester.</p> </div>','Satisfactory completion of at least one History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15559,2027,4254,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15560,2027,619,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/300/hist-397','<div class="desc"> <p>Reading tutorials, off-campus internships, and research projects are among options available. Permission of instructor and department chair required.</p> </div>','Permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15561,2027,620,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/400/hist-490','<div class="desc"> <p>In this fall semester seminar, students will write a major paper that involves research and analysis of primary and secondary documents. Papers may concentrate on a geographical area or take a topical approach, such as History of Science and Medicine, Women''s History, or Revolutions. In addition, the seminar participants will read works by historians reflecting on their craft. The seminar culminates with individual oral presentations on the thesis research to the Department and campus community. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15562,2027,4255,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/400/hist-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15563,2027,3974,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/hist-history/400/hist-498','<div class="desc"> <div><div><p>This advanced directed research course is designed for history majors who have completed the HIST 490 Senior Seminar and have been approved by the HIST 490 instructors to continue on as candidates for Honors designation. Over the course of the semester each honors thesis writer will work with a research mentor on advanced methodologies and multiple drafts to expand their original research and revise the thesis from a 25-page paper to a 40-page (or more) paper. The seminar will culminate with a program of oral presentations in which each student will share their work with the Department and the campus community. Instructor permission required.</p></div></div> </div>','HIST 490 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15564,2027,4256,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/int-internships/courses-folder/int-100','<div class="desc"> <p dir="ltr" style="margin-top: 0pt; margin-bottom: 0pt;"> <span style="color: #000000;">INT 100 is a zero-unit internship course that will be included on the studentâs transcript. Students that enroll in INT 100 must have a paid or unpaid internship that is an educational experiential opportunity that meets the student and internship criteria established by Occidental College and approved by the Hameetman Career Center (HCC).Â </span> <span style="color: #000000;">Students enrolled in INT 100 receive CR/NC grades for successful completion of their internship and the following INT 100 course requirements:</span> </p> <ul style="margin-top: 0px; margin-bottom: 0px;"> <li dir="ltr" style="color: #000000; list-style-type: disc;"> <p dir="ltr" style="margin-top: 0pt; margin-bottom: 0pt;">Minimum 80 hours per Semester</p> </li> <li dir="ltr" style="color: #000000; list-style-type: disc;"> <p dir="ltr" style="margin-top: 0pt; margin-bottom: 0pt;"><span style="background-color: #ffffff;">500-word Reflective Essay &amp; Internship Survey</span></p> </li> <li dir="ltr" style="color: #000000; list-style-type: disc;"> <p dir="ltr" style="margin-top: 0pt; margin-bottom: 0pt;">Internship Supervisor EvaluationÂ </p> </li> </ul> <p><span id="docs-internal-guid-6c88bd0a-7fff-c763-cb68-9f2a7ae2e345"><span style="color: #000000;">If a student fails to complete the required minimum 80 hours per semester, </span><span style="background-color: #ffffff; color: #000000;">500-word reflective essay and internship survey, </span><span style="color: #000000;">and/or internship supervisor evaluation, the student will receive a NC on their transcript.</span></span></p> </div>','Permission of Career Center ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15565,2027,4257,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/int-internships/courses-folder/int-150','<div class="desc"> <p>The Hameetman Career Center (HCC) administrates the InternLA Summer Internship Program which connects Oxy students to internships in LA-based organizations in six broad occupational sectors: Business &amp; Entrepreneurship, Law &amp; Policy, Media &amp; Entertainment, Science &amp; Research, Social Services &amp; Advocacy and Visual &amp; Performing Arts. InternLA is aimed at recruiting talented Oxy students who wish to enhance their knowledge along a career trajectory. Participating sites will host an InternLA student for a ten-week assignment. Interns will work a minimum of 24 and maximum of 32 hours per week at their internship site with two hours reserved for weekly professional development workshops called IMPACT. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15566,2027,4258,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/int-internships/courses-folder/int-200','<div class="desc"> <p dir="ltr" style="margin-top: 0pt; margin-bottom: 0pt;"><span style="color: #000000;">INT 200 is a two (2) unit internship course that will be included on the student’s transcript. Students that enroll in INT 200 must have a paid or unpaid internship that is an educational experiential opportunity that meets the student and internship criteria established by Occidental College and approved by the Hameetman Career Center (HCC). To further enhance the experiential learning of the internship by connecting it to a student’s academic goals and interests, INT 200 has an academic component designed in collaboration with a faculty supervisor. </span></p> <p dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="color: #000000;">INT 200 students must secure an on-campus faculty supervisor to assign, supervise, and approve the proposed academic component of the internship. The faculty supervisor must be a full-time faculty member on campus. Students are expected to meet with their faculty supervisor at least five (5) times over the course of the semester (or summer session) and spend at least 30 hours during the term working on the academic project in addition to the required internship minimum of 80 hours per semester.</span></p> <p dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="color: #000000;"></span><span style="color: #000000;">Students enrolled in INT 200 receive CR/NC grades for successful completion of their internship and the following INT 200 course requirements:</span></p> <ul> <li dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="color: #000000;">Minimum 80 hours per Semester</span></li> <li dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="color: #000000;"></span><span style="color: #000000;">Academic Component as Outlined in INT 200 Proposal</span></li> <li dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="color: #000000;"></span><span style="background-color: #ffffff; color: #000000;">500-word Reflective Essay &amp; Internship Survey</span></li> <li dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="background-color: #ffffff; color: #000000;"></span><span style="color: #000000;">Internship Supervisor Evaluation </span></li> <li dir="ltr" style="margin-top: 10pt; margin-bottom: 0pt;"><span style="color: #000000;"></span><span style="background-color: #ffffff; color: #131313;">500-word reflective essay &amp; internship survey</span><span style="color: #131313;"> and internship supervisor evaluations, coordinated by the HCC, are shared with the faculty supervisor and may be used at the discretion of the faculty supervisor when grading the internship. If a student fails to complete the required minimum 80 hours per semester, academic component as outlined in their INT 200 proposal, reflective essay, and/or internship evaluation, the student will receive a NC on their transcript.</span></li> </ul> <div><span style="color: #000000;"><br/> </span></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15567,2027,4259,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/100/copy-of-japn-193','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15568,2027,209,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/100/japn-101','<div class="desc"> <p>Introduction to the language in all its aspects, basics of grammar and oral communication and the reading and writing of hiragana &amp; katakana through intensive drills and exercises. Introduction to formal and casual speech styles. May not be taken for credit by those with more than one year of previous high school (grades 10, 11, 12) study or one semester of college study of Japanese. Consult instructor for details.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15569,2027,623,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/100/japn-102','<div class="desc"> <p>Continuation of JAPN 101. Further development of communication skills, both oral and written. Mastery of the basic conjugated forms of verbs and adjectives in the past-nonpast and positive-negative paradigms in both the polite -masu and plain forms. Students will learn to decode the speaker''s assumptions or attitudes as they are integrated into certain grammatical forms. Introduction to kanji (approximately 50 characters and their multiple readings).</p> </div>','JAPN 101 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15570,2027,4260,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/100/japn-195','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15571,2027,4261,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/100/japn-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15572,2027,4262,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/200/copy-of-japn-293','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15573,2027,210,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/200/japn-201','<div class="desc"> <p>While consolidating their knowledge of grammar basics, students will learn the keigo (honorific forms) system and a variety of additional verb forms, both inflectional and paraphrastic. Increased emphasis on conversational skills, as well as training in composing texts with coherence and accuracy. Introduction of additional kanji and their multiple readings (approximately 200 characters over the two semesters of the intermediate level).</p> </div>','JAPN 102 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15574,2027,624,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/200/japn-202','<div class="desc"> <p>Continuation of JAPN 201. Further development of all four skills. Students will deepen their understanding of the speaker''s attitudes, as well as the spatial and temporal concepts integrated in grammatical forms. Mastery of at least 250 kanji, with their multiple readings, by the end of this level.</p> </div>','JAPN 201 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15575,2027,854,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/200/japn-271','<div class="desc"> <p>This course examines the art of storytelling via selected works of prose, fiction, and film, which were originally written/produced in the Japanese language in the early modern, through contemporary, periods. Through close reading of texts and visual images, the student will identify and analyze specific issues that are relevant to the critical messages and the development of the narrative. The course is given in English but those whose language proficiency permits may choose to read the texts in the original Japanese. Offered in alternate years.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15576,2027,3009,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/200/japn-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Modern Japanese Literature</strong><br/> This course introduces students to key literary texts from Japan’s modern era (1868-present). During this period, Japanese literature and the Japanese written language were reinvented alongside rapid socioeconomic, political, and cultural changes. As Japan experienced the industrialization, economic success, wars, natural disasters, and technological breakthroughs that characterize this period, literature played a key role in forming the national consciousness. Authors examined in this course may include Higuchi IchiyÅ, Natsume SÅseki, Kawabata Yasunari, Tanizaki Jun''ichirÅ, Åe KenzaburÅ, Tawada YÅko, and Murakami Haruki. We will consider works of Japanese literature within their linguistic, cultural, and historical contexts. Through essays, reading responses, and class discussions, students will explore how literature transforms the human experience into words and in doing so transforms the human experience. The course is given in English, but those whose language proficiency permits may choose to reference the texts in the original Japanese. <em>Core Requirement Met: Regional Focus.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15577,2027,4263,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/200/japn-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15578,2027,4264,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/copy-of-japn-393','<div class="desc"> <p>Research in an area not otherwise included in the departmental curriculum. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15579,2027,212,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/japn-301','<div class="desc"> <p>Further development of the four skills. Mastery of certain grammatical forms with increasing emphasis on the speaker''s attitudes or assumptions regarding the situation. Introduction of the humble form in the keigo system. Introduction of additional kanji (approximately 250) and their multiple readings over the two semesters of the advanced level.</p> </div>','JAPN 202 or equivalent ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15580,2027,213,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/japn-310','<div class="desc"> <p>This course is designed for advanced-level Japanese students and will develop their linguistic skills with an aim towards increased fluency in speaking, reading, writing, and listening comprehension. The course will accomplish these goals by reading and discussing texts in Japanese. Texts may include short stories, excerpts from novels, among other materials. The texts and topics can change from year to year. Student input on topics and texts is welcome. Discussion and readings will be in Japanese.</p> </div>','JAPN 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15581,2027,855,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/japn-340','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">In this advanced-level course, we will develop skills in reading, comprehending, writing, and speaking Japanese using materials from contemporary Japanâs media and mass communication. We will learn to critically engage with authentic materials related to social issues, economics, world affairs, and other aspects of contemporary Japan while learning methods of close reading, translation, research, and presentation projects in Japanese. Our goal is to integrate advanced Japanese language skills and a deeper cultural understanding of twentieth-century Japan.</span></p></div> </div>','JAPN 301 or above ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15582,2027,626,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/japn-350','<div class="desc"> This course is an advanced-level Japanese language course for students who wish to gain speaking, reading, and writing skills in professional and academic Japanese. We will learn the nuanced usages of formal and honorific language, engage with authentic materials such as business correspondence, academic texts, and professional presentations to gain advanced vocabulary and grammar strategies. Through speaking and writing assignments, students will produce and present arguments, proposals, and reports in professional Japanese. In addition, students will enhance cultural competence and linguistic fluency in formal environments through an understanding of the social and cultural dynamics of the Japanese work space. </div>','JAPN 301 or above ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15583,2027,4265,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/japn-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15584,2027,627,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/300/japn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15585,2027,1383,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/400/japn-460','<div class="desc"> <div><p dir="ltr" style="line-height: 1.2; margin-right: 7.8pt; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This advanced-level course offers an in-depth exploration of theories and practices of Japanese studies, including linguistics and translational studies, cultural and historical inquiries, and literary studies. Through a variety of primary sources in Japanese and secondary scholarship in both English and Japanese, we will discuss critical inquiries of Japanâs social and cultural life. We will also integrate Japanese skills of reading, writing, and comprehending to formulate individual ideas and critiques, as well as express them in formal essays and presentations.</span></p><p><br/></p><p dir="ltr" style="line-height: 1.245; margin: 0 0.5pt 0 -0.5pt; text-indent: -0.5pt; padding: 0 0 0 0.5pt"><span style="font-size: 12pt">This course is open to both non-native and native speakers of Japanese who wish to develop their bilingual skills and intercultural literacy. Class discussions will be conducted in both Japanese and English.</span></p></div> </div>','JAPN 301 or above ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15586,2027,4016,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/400/japn-493','<div class="desc"> <p>"Japanese language, literature, and culture": Senior comps directed research in Japanese Studies.</p> </div>','Instructor permission required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15587,2027,4266,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/400/japn-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15588,2027,4267,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/japn-japanese-studies/400/japn-498','<div class="desc"> <div><p>Honors directed research in Japanese. Prerequisite: permission of department and instructor.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15589,2027,214,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/100/kine-104','<div class="desc"> <p>Survey of kinesiology subdisciplines: human anatomy, exercise physiology, nutrition, motor learning, and sport and exercise psychology. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15590,2027,628,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/100/kine-197','<div class="desc"> <p>Research in a subdiscipline of kinesiology for students who do not have advanced competence in kinesiology (see KINE 397). Permission of instructor required. Graded on a Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15591,2027,4446,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-200','<div class="desc"> <p>A structural survey of the human body covering the musculoskeletal, nervous, endocrine, cardiovascular, lymphatic, respiratory, digestive, urinary, reproductive, and integumentary systems. Lecture will also include the special senses of vision, hearing, and olfaction. Includes one three-hour laboratory per week.</p> </div>',NULL,'KINE 200L ',NULL);
INSERT INTO course_descriptions VALUES(15592,2027,1178,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-201','<div class="desc"> <p>This course examines the social and cultural factors that influence sport and physical activity. The positive and negative consequences of the way sport is organized in American society will be discussed. We will explore the unifying power of sport, as well as how sport serves to reproduce many of the inequalities present in our society. Topics include: violence, substance abuse, media, gender, race/ethnicity, and social class, and their roles within sport and physical activity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15593,2027,1704,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-210','<div class="desc"> Introduction to the science of nutrition. Students will learn how macronutrients and micronutrients are assimilated into the human body from both dietary and supplement sources. A significant portion of the course will focus on understanding the science behind the USDA dietary guidelines and how to prepare meals for optimal health depending on age, sex, and physical activity levels. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15594,2027,4268,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-215','<div class="desc"> <p>In this community-based learning course, students will be introduced to educational, economic, environmental, and public health perspectives related to urban green schoolyard design and implementation. The course includes off-campus visits to school sites and presentations by experts in landscape design, water conservation, and public education. Throughout the semester, students will learn how to use social science and life science research tools to evaluate the impact of green schoolyards. The semester will culminate in a green schoolyard project with community partners in the Northeast Los Angeles neighborhood. The course will include two 1.5 hour lecture meetings and one two hour seminar meeting each week.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15595,2027,4269,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-220','<div class="desc"> <p>This course introduces students to scientific methodology in the context of research in kinesiology and aligned disciplines. Basic concepts in scientific inquiry, development of a research question, design of a controlled study, data integrity, and human subject regulations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15596,2027,4447,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-235','<div class="desc"> <p>This course explores sport as a key social institution through which power, identity, and inequality are produced, contested, and negotiated. Using sociological theory and empirical research, we examine how sport intersects with systems of race, class, gender, sexuality, and nationhood—both reflecting and reshaping dominant ideologies—in the United States.</p> <p>Students will engage with sport as a site of cultural meaning and social struggle, analyzing topics such as athlete labor, educational institutions, media representation, and global sport industries. We pay particular attention to how marginalized communities navigate and challenge exclusion within athletic spaces, and how sport is mobilized in the service of both social control and collective resistance.</p> <p>Class sessions incorporate case studies, media critique, and contemporary examples—from high school athletics to global mega-events. This course is ideal for students seeking a deeper understanding of sport beyond the scoreboard.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15597,2027,216,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-295','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15598,2027,4270,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15599,2027,1236,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-298','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Prior to enrollment, students are expected to have a basic background in Kinesiology and/or public health (e.g. KINE 104). No previous research experience required. Students are permitted to repeat KINE 298 for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15600,2027,1527,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/200/kine-299','<div class="desc"> <p>This course will explore the impact of sports participation on female experiences, specifically considering multilevel psychological and socio-cultural women’s empowerment measures, such as self-esteem, self-efficacy, and solidarity. Focusing primarily on soccer, we will consider the possibility that the very act of training the body through sports contributes to a greater sense of ownership of one’s body – a critical psychological state for women’s health, personal security, and, ultimately, empowerment. Through the framework of social cognitive theory of gender development, we will also examine the relationship between physicality, psychology, and gender identity development. Finally, over the course of the semester, we will vet sports participation as an intervention to address gender inequality, including the impact of relevant policy, such as Title IX. Through a community-based learning component, students will have the chance to engage in qualitative inquiry on the effect of sports on health and self-concept. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15601,2027,217,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-300','<div class="desc"> <p>This course covers musculoskeletal anatomy and provides an in-depth study of bone composition and development; joint morphology; muscle structure, function, mechanics, and movement analysis. Includes one three-hour laboratory per week. </p> </div>',NULL,'KINE 300L ',NULL);
INSERT INTO course_descriptions VALUES(15602,2027,629,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-302','<div class="desc"> This course examines the kinematics and kinetics of human movement as applied to the musculoskeletal system. Students analyze how muscle, bone, connective tissue, and neural structures contribute to movement performance, posture, and injury mechanisms. Laboratory work is integrated with lecture material and emphasizes mechanical principles, muscle and tissue mechanics, joint motion, postural analysis, and applied movement analysis using video-based tools. <span style="background-color: #ffffff; color: #222222;">Includes one three-hour laboratory per week.</span> </div>','KINE 300 ','KINE 302L ',NULL);
INSERT INTO course_descriptions VALUES(15603,2027,1384,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-304','<div class="desc"> <p>Introduction of principles of human physiology. Presentation of an integrative approach to basic physiology of major organs and organ systems, covering aspects of cell function, including membrane transport, excitability, metabolism, and functions of organs from the nervous muscular, respiratory, cardiovascular, gastrointestinal, renal, endocrine, and reproductive systems. Includes one three-hour laboratory per week.</p> </div>',NULL,'KINE 304L ',NULL);
INSERT INTO course_descriptions VALUES(15604,2027,631,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-305','<div class="desc"> <p>The study of human functions and their physiological adaptation to, and specification for, the stress of exercise. Cardiovascular and respiratory responses to exercise; use of calorimetry to study metabolism during exercise; effects of environmental stress on exercise performance; body composition; ergogenic aids and nutritional factors in exercise performance.</p> </div>','KINE 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15605,2027,221,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-306','<div class="desc"> <p>Energy sources for human movement; substrate and energy metabolism during exercise; liver, skeletal, and cardiac muscle adaptations to acute and chronic exercise training.</p> </div>','KINE 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15606,2027,4271,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-308','<div class="desc"> <p>This advanced level course focuses on the etiology of the major degenerative diseases in our society and the role genetics, diet, and exercise play in their development and treatment. Diseases covered include: heart disease, cancer, non-insulin dependent diabetes, osteoporosis, and hypertension. Focus of course will look into treatment and prevention of disease through diet, exercise, and lifestyle modifications. The current scientific research covering the metabolic, cellular, and system changes involved in disease progression and treatment will be of particular focus.</p> </div>','KINE 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15607,2027,946,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-309','<div class="desc"> Developmental perspective of factors contributing to acquisition of motor control from infancy through adolescence. Emphasis placed on maturational and environmental factors. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15608,2027,224,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','KINE 310L ',NULL);
INSERT INTO course_descriptions VALUES(15609,2027,225,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'KINE 310',NULL);
INSERT INTO course_descriptions VALUES(15610,2027,632,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-311','<div class="desc"> <p>This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance, and level of participation of an individual or group.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15611,2027,226,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-395','<div class="desc"> <p>Intense study in an area of kinesiology under the direct supervision of a faculty member. Permission of instructor required. May be repeated for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15612,2027,227,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-396','<div class="desc"> <p>Supervised participation in the work of a nutrition exercise or other health related company or agency. Graded on a Credit/No Credit basis only. May be taken for up to a maximum of 4 units of credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15613,2027,634,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-397','<div class="desc"> <p>Individual study for students with advanced competence. Extensive study of a specialized topic or broad study of an area not otherwise included in the curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15614,2027,1237,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/300/kine-398','<div class="desc"> <p>This course examines the relative effectiveness of physical activity and nutrition resources/interventions in changing lifestyle behaviors of low-income Angelinos. Students will collaborate with community partners, under the direct supervision of the instructor, to create educational material, plan events, conduct informative workshops, and evaluate intervention strategies. Students should expect to commit to a minimum of 8 hours of course work each week, including a 1.5 hour course meeting, assigned group work, and community outreach. Enrolled students will assume leadership responsibilities in course projects (e.g. become course liaison with community partners, develop research proposals, manage course mini-projects etc.). Can be repeated for credit. Permission of instructor required.</p> </div>','KINE 298 and KINE 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15615,2027,635,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/400/kine-490','<div class="desc"> <p>This seminar course examines a selected area of current topics in Kinesiology. It is the intent of this course to utilize an integrative approach to the advanced study of Kinesiology. Students will develop and write a comprehensive research paper in a subdiscipline of Kinesiology. Open to senior kinesiology majors with permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15616,2027,4272,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/400/kine-497','<div class="desc"> <p>Individual study for students with advanced competence. Extensive study of a specialized topic or broad study of an area not otherwise included in the curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15617,2027,636,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/kine-kinesiology/400/kine-499','<div class="desc"> <p>Data collection, analysis write-up, and presentation of Honors thesis. May be repeated both semesters of senior year.</p> </div>','Permission of department ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15618,2027,4273,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/lang-language/100/lang-193','<div class="desc"> <div> <p>Intensive study in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>When taken as a 4-unit course, you should expect to spend at least twelve (12) hours a week on this course. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15619,2027,4274,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/lang-language/200/lang-293','<div class="desc"> <div> <p>Intensive study in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>2 or 4 units. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15620,2027,4275,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/lang-language/300/lang-393','<div class="desc"> Intensive study in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.<br/> <br/> 2 or 4 units. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15621,2027,3990,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/lang-language/400/lang-493','<div class="desc"> <div> <p>Comprehensive-level work in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>When taken as a 4-unit course, you should expect to spend at least twelve (12) hours a week on this course. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15622,2027,4448,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/lang-language/400/lang-498','<div class="desc"> Extended comprehensive-level work in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15623,2027,228,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/100/latn-101','<div class="desc"> <p>Study of alphabet, pronunciation, grammar, and culture of Latin. Students will engage, from the beginning, with original texts from Virgil, Horace, Caesar, Cicero and others. Focus will be placed on the ways in which the syntactic and semantic content of this language helped constitute the unique sense of the world that belonged to the Ancient Romans, a worldview which even now continues to exert a tremendous influence on world history and culture.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15624,2027,639,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/100/latn-102','<div class="desc"> <p>Continuation of LATN 101 and reading and interpretation of an original text.</p> </div>','LATN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15625,2027,4276,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/100/latn-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15626,2027,856,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/200/latn-201','<div class="desc"> <p>Advanced readings in Latin literature and/or philology in coordination with a classics course in ECLS (or another department affiliated with the classics program).</p> </div>','LATN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15627,2027,4277,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/200/latn-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15628,2027,4278,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/200/latn-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15629,2027,1705,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-320','<div class="desc"> "To speak of forms changed into new bodies [...] from the very beginning of the world up to my own times." Thus begins Ovid''s <em>Metamorphoses</em>, whose programmatic opening stanza links the birth of the world from formlessness and chaos to a narrative principle of transformation and change over time. This course will explore the shifting conceptions of metamorphosis -- the transformation of "forms [...] into new bodies," and vice versa - from its mythic origins in Ovid to its modern manifestations and modulations in the works of Goethe, Darwin, and Kafka. Throughout the course, we will examine the ambiguous relationship between "forms" and "bodies" in Western thought and how the permutations of this nexus come to bear on a wide variety of different topics in the humanities, including myths and theories of changing forms in nature (plants, clouds, animals); dynamic representations of gender, sexuality, and erotics; as well as figures of hybridity and the grotesque (human-animal hybrids, beasts, and monstrosities). More broadly, the course will explore the porous interfaces between ancient and modern poetics, myth and modernity, as well as the arts and sciences. LATN 320 is the five-unit course attached to CSLC 120. </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15630,2027,1662,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-340','<div class="desc"> <p>Petronius'' <em>Satyricon </em>depicts the erotic misadventures of male lovers, Encolpius and Giton, as they excessively feast, fête, and ... fornicate in a series of near-death experiences throughout the Mediterranean. While immensely entertaining and, at times ridiculous, this popular novel will provoke thoughtful class discussions about love (heterosexual and homoerotic), romance, gender, and sexuality in antiquity. We will examine the generic features of this work in relation to other surviving ancient novels whose authors were influenced by the second sophistic. Our consideration will also include the reception of these novels in postÂ­classical literature, art, and film. Course meets with CSLC 140.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15631,2027,1528,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-341','<div class="desc"> <p>The ancient Romans had a flair for the dramatic, creating spaces and staging performances which matched the grandness of their empire. Gladiatorial games, theatrical productions, chariot races, and other festivals played an integral role in the civic, religious, and cultural life of the ancient Romans. This course offers an introduction to the various forms of public entertainment offered during the Roman Republic and Empire. Students will read selections from ancient authors and consider modern theories about the gaze and spectatorship. In this language intensive course we will read selections from Seneca''s <em>Epistulae ad Lucilium </em>as well as Horace''s <em>Satires</em>.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15632,2027,2796,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-342','<div class="desc"> <p>In this course, students and professor will collaborate in a close reading of Umberto Eco’s 1980 novel, <em>The Name of the Rose</em> (originally published in Italian as <em>Il nome della rosa</em>). The novel is many things at once. It is a murder mystery/detective novel, a coming-of-age story, a dramatization of debates within Medieval philosophy that resonate to this day, a book about books, and a fantasy about recovering lost works from antiquity, most importantly, Aristotle’s lost book on comedy. We will read the novel slowly and deeply over the course of the semester and together we will explore its themes—such as the nature of words, names, and other signs, the meaning of laughter, and the value of tolerance in a world of dogmatic certainties—and its rich literary allusions—to Sherlock Holmes, Jorge Luis Borges, Alexandre Dumas, and to numerous Medieval and ancient authors. We will track down the novel’s literary references (by reading secondary resources, such as scholarly articles), seek to understand the rich world of philosophical and theological thought its characters inhabit (by reading primary texts of Medieval philosophy, theology, and poetry), and wallow in the sheer beauty of Eco’s writing and the sheer thrill of the story he is telling, all with the goal of interpreting the novel as deeply as possible, as one of the most significant postmodern works of fiction.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15633,2027,2517,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-345','<div class="desc"> <p>Lucretius'' poem <em>On the Nature of Things</em> is not only a watershed moment in Roman philosophy and Latin poetry, but also a touchstone in world thought and literature from the Renaissance to Postmodernism. Lucretius (c.99-c.55 BCE) was a materialist. For him, reality consisted of atoms and compounds of atoms situated in empty space. We will try to come to grips with Lucretius'' answers to questions such as the following: Where, in a purely physical world, is there a place for conscious beings like ourselves? Can we have free will and if so, how? Why do we suffer and what can we do to escape suffering? What makes life meaningful if the soul is not immortal? What does it mean to be a moral person if the gods take no interest in us or our actions? What do we owe each other, as creatures living together in community? As we examine these questions we will also attend carefully to Lucretius'' poetic artistry, to the rhetorical strategies by which he attempts to convert his audience, to his atomic physics, and to his place as a political thinker writing during the fall of the Roman republic. In this 5-unit course we will be reading Lucretius in the original Latin, and will address the ways in which his poem''s semantic content, syntax, and literary form work with (or against) one another to produce that texture of Roman cultural significance that is the <em>de Rerum. </em>Permission of instructor required.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15634,2027,2571,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-346','<div class="desc"> <p>This interdisciplinary course, featuring ancient Roman texts in the original Latin, introduces students to the ways in which theories and findings from cognitive science can cast new light on Roman literature, theater, philosophy, law, science, religious practice, and graphic arts. Cognitive science offers explanatory paradigms for everything from the appeal of literary characters, dramatic irony, belief in gods, and animal sacrifice. Distributed cognition, that is, the thesis that cognition is embodied, enactive, embedded, and extended is appealed to for new perspectives on ancient theater, public spectacles, religious ceremonies, craft knowledge, and the production, display, and appreciation of architectural forms, sculpture, and paintings. Findings from the science of memory are brought to bear upon Roman strategies for remembering, for commemorating, and for purposely forgetting. Theories of culture drawn from evolutionary anthropology, developmental psychology, and philosophy of biology are adduced to cast new light on our evidence for Roman forms of participatory rather than instructional pedagogy, in-group / out-group formation, prosocial and altruistic behavior, and mechanisms of cultural change. These topics will be examined through close readings in the original Latin drawn from Cato the Elder, Cicero, Livy, Vitruvius, and others. Permission of instructor required.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15635,2027,2775,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-347','<div class="desc"> <p>After the era of Plato and Aristotle (4th century BCE), Greek and Roman philosophers centered the therapy of psychological suffering in their philosophical programs. Epicurus, for example, wrote, “There is no use in philosophy, unless it casts out the suffering of the soul.” In this course, we examine the therapeutic programs offered by various ancient philosophical schools: the Peripatetics (followers of Aristotle), Stoics (followers of Zeno of Citium), Epicureans (followers of Epicurus), Skeptics (two schools, one descending from Plato’s Academy and the other from Pyrrho), and finally the Christian philosophy of Augustine of Hippo, which was informed by but also broke decisively with the Greco-Roman philosophical tradition that had preceded it. In order to understand the therapeutic programs of these schools, we shall first have to understand each school’s account of human nature (“anthropology,” in its original sense), of the mind or soul (“psychology,” in its original sense), and of the purpose or “end” of human existence (“ethics”). Each school’s answer to the question of <em>why </em>we suffer and <em>how </em>we might find psychological peace only makes sense in light of that school’s beliefs about what it is to be human, what is the nature of the mind/soul, and what is the purpose of life. Our source materials in this investigation will include classic texts in ancient ethical thought: Cicero’s <em>Tusculan Disputations</em>, a literary masterpiece cast as a dialogue among prominent Romans who had sought refuge in the countryside as the end of the Roman republic unfolded; Seneca’s <em>On tranquility of mind</em>, which takes the form of a letter to his friend Serenus, who had sought him out to find relief from his distress; and the third book of Augustine’s <em>Confessions</em>, which details the author’s suffering under the afflictions of lust and the apparent paradox of his perverse delight in his own misery.</p> <p><span style="background-color: #ffffff; color: #212021;">Taught in conjunction with </span>CSLC 247<span style="background-color: #ffffff; color: #212021;">, but meeting for an additional section.</span></p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15636,2027,2830,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-348','<div class="desc"> <p>The assassination of Pompey the Great in September of 48 B.C.E sealed the fate of the Roman republic. Pompey’s military leadership had been the republicans’ last hope of preserving Rome’s constitutional order in the face of the dictatorial ambitions of Julius Caesar, who had in effect declared war on his own country in 49 B.C.E when he brought his army across the Rubicon river into Italy from Gaul. With Pompey gone, the republic was lost.<br/> <br/> Some Romans—including the statesman, orator, and philosopher Marcus Tullius Cicero—resisted Caesar with the pen, not the sword. In works such as On the Republic and On the Laws, Cicero articulated and urged upon his fellow citizens the merits of republican government, its basis in popular sovereignty, and the moral and political virtues of the rule of laws not men. A group of republican conspirators who sought to restore the old order assassinated Caesar in 44 B.C.E. They were, in turn, destroyed by Caesar’s would-be heirs. In the tumult, Cicero was assassinated by the Caesarian faction for his political speech and activism.<br/> <br/> Cicero’s writings and their influence survived his assassination and have inspired opponents of tyranny and proponents of self-government for over 2000 years. In this course, we engage with the legacy of Roman republicanism, and its historically unprecedented regime of rights, laws, and constitutional norms. We read foundational texts by Cicero and the Roman historian Livy as well as by later political theorists who drew inspiration from them, such as Machiavelli, who re-introduced the theory of republican government into a Renaissance Europe ruled by princes in his 1517 treatise Discourses on Livy, and John Adams (the “American Cicero”), whose 1787 work Defence of the Constitutions of the United States of America owed much to Ciceronian thought and made the Constitution that we have today—the oldest constitution in the world, and one that many perceive as now under threat—the world-changing document that it has proved to be.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15637,2027,3287,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-349','<div class="desc"> <p>This course explores some historical examples of ways of confronting the sort of ressentiment—“a generalized feeling of resentment and oftenhostility harbored by one individual or group against another”—that pervades our cultural discourse, wracks our political life, and makes us miserable as individuals. We shall engage in close examination of the ancient Roman authors Cicero (106 – 43 BCE), Seneca (4 BCE – 65 CE), Epictetus (c.50 – 135), and Marcus Aurelius (121 – 180 CE) and the classically-influenced American cultural critic Albert Murray (1916-2013). We shall interrogate both the strengths and weaknesses of the programs and techniques that these authors—all of whom lived through times of social and personal turmoil—proposed for remaining centered in a sense of their own dignity and in a feeling of gratitude for the blessings that were intermingled with their tribulations. In the case of Murray, we shall assess the adequacy of his theory about the African-American Blues tradition and compare it to that of some scholars who had preceded him. We shall attempt to determine the limitations and strengths of his perception that the Blues idiom represented not “the anguished outcry of a victim” but “an exercise in heroic action” through which the individual makes “an affirmative and hence exemplary and heroic response” to both the suffering particular to historically conditioned forms of oppression as well as to the absurdity of the human condition. Topics covered include the theory of ressentiment, the emotions in ancient Roman thought, Roman techniques for cultivating positive, empowering affective responses not only to “microaggressions,” but to even themost horrific events, and Albert Murray’s theory of the “Blues idiom” as “survival technique [and] esthetic equipment for living.” </p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement.</p> </div>','Latin 201 or approval of instructor. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15638,2027,3216,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-350','<div class="desc"> <p>This course investigates select African American engagements with the literatures produced by ancient Greeks and Romans. It is motivated by the conviction that we do interpretive justice to the accomplishments of African American writers when we attempt to understand the tradition(s) they conceive their work to be intervening in.</p> <p>African American literature was born with the publication of Phillis Wheatley’s <em>Poems on Various Subjects, Religious and Moral,</em> in 1773. The book evinces a deep knowledge of Latin and Latin literature, which it turns to its own emancipatory end. Indeed, Wheatley secured her freedom on the strength of the book.</p> <p>Engagement with classical texts offered Wheatley and other African American writers of every era an opportunity to access, deploy, and transform a widely shared treasury of meanings, ideas, images, tropes, genres, and styles in order to create unique works of great artistic power, capable of opening up newly imagined ways of being for themselves and their readers. In addition to Wheatley, we shall explore the classical interactions of poets such as James M. Bell, Mary Livermore, Frances Ellen Watkins, and Robert Hayden and prose writers such as David Walker, William Sanders Scarborough, and W. E. B. Du Bois.</p> <p>To experience the artistic power of these works as their authors intended, we must understand the aesthetic and literary contexts and tradition(s) in which they worked, for context and tradition are the foundation of a work’s meaning. To this end, we shall read alongside African American literary creations some of the Greek and Roman literary works to which they respond. For when we see clearly how a poem by, for example, Phillis Wheatley, responds to an ode by the Roman poet Horace—himself the son of a freedman—we grasp more fully the unique aesthetic, moral, and intellectual power of her poem. To see how Horace’s poetry could communicate to Wheatley is to see how Wheatley’s poetry can communicate its emancipatory power and promise to us in our own time. </p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15639,2027,3962,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-356','<div class="desc"> <div> <div> <div> <p>Free speech was hardly invented by the First Amendment. In ancient democratic Athens, isegoria signified each (free, male) citizen''s "equal right of speech" in the public sphere. The Greeks had another, related but contrasting term, parrhesia, which signified "frankness of speech," or not holding anything back. Meanwhile, the Romans praised libertas, or "liberty of speaking," which citizens in a republic required in order to come together and deliberate about public policy. But these ideals were not always upheld. Indeed, the philosopher Socrates was put to death for his relentless exercise of parrhesia. His frank speech irritated the powerful so much that it cost him his life. The Romans, for their part, categorized some speech as licentia, or "license," because it went too far, violating social norms. When the Roman republic fell, replaced by autocracy and empire, free speech collapsed with it. The trials and tribulations of free speech in the ancient world made it, ironically, the subject of a great deal of speech. Philosophers theorized it, historians historized it, professional rhetoricians lamented attacks on it, and satirists asserted their own freedom of expression by making coded jokes about its suppression. In this course, we sample the literature of free speech in ancient Greece and Rome, trace its fate in the Middle Ages, when the expression of heretical ideas could lead to death, and read classic texts from its resurgence in the Renaissance and after, such as Milton''s Areopagitica. In the last part of the course, we look at how the troubled history of free speech informs the modern era, from John Stuart Mills''s On Liberty, to gradually expanding interpretations of the First Amendment, to the contemporary debates that continue to consume us even now. This course will be offered in conjunction with CSLC 146, but will meet for an additional 90 minutes per week to read the Latin texts covered in class in their original Latin form.</p> <p>Satisfies CPPE and CPGC.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement.</p> </div> </div> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15640,2027,4279,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-357','<div class="desc"> <div><div><div><div dir="ltr"><p>In 48 CE, the Roman empress Agrippina - granddaughter of Augustus, daughter of the late and beloved general Germanicus - orchestrated her then-seventeen year old sonâs accession to the imperial throne, after the suspicious death of her husband (also, by the way, her uncle). This new emperor, Nero, would rule for the next fifteen years, and he would become known as one of the most infamous emperors of all of Roman history. In addition to political conspiracies and murders (Agrippina herself being a notable victim), Neronian Rome witnessed a flourishing of culture, with the production of some of the most remarkable works of literature, art, and architecture. This course will investigate the literature, history, and culture of Rome under Nero. We will thus explore a wide range of material, including literary and philosophical texts such as Lucanâs epic poem on the civil war between Julius Caesar and Pompey, the tragedies and philosophical works of Seneca, and Petroniusâ novel, the Satyricon, as well as the art and architecture of Neronian Rome, such as the Domus Aurea (Golden House), the massive palace in the center of Rome commissioned by Nero. Throughout, we will consider what ideological and aesthetic features are common to these works. This course will additionally focus upon the afterlives of Nero and Neronian Rome, beginning with Tacitusâ account of the period in his Annales. We will consider why certain emperors, above all Nero, are remembered in the ancient historiographical tradition as âbadâ. We will also explore the apocalyptic dimension of Neroâs afterlife, including his evolution into the antichrist in early Christian literature. This course will be offered in conjunction with CSLC 147, but will meet for an additional 90 minutes per week to read the Latin texts covered in class in their original Latin form.</p><p style="margin: 0; font-stretch: normal; font-size: 12px; line-height: normal"><br/></p><p>Students who complete the final paper for this course, with a grade of C or higher, can use this work to satisfy the second-stage writing requirement. </p></div></div></div></div> </div>','LATN 201 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15641,2027,2706,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-382','<div class="desc"> <p>In this course we will trace one historic trajectory of what we today call "love," from Ancient Greece to the Renaissance, and shall do so through a careful examination of the literature that sought to give expression to this ever-changeable and always-provocative concept: the songs of Sappho, the dialogues of Plato, the erotic manuals of Ovid, the Gospels of Christianity, the troubled Confessions of Augustine, the courtly tales of knights in the Middle Ages, and the great all-encompassing journey of Dante through heaven, hell and purgatory in the Divine Comedy. Significant attention will be paid to the way each of these works continues to contribute to our own modern expressions and notions of love, in all their ecstatic, heartbreaking, inspiring and frustrating complexity.</p> <p>Taught in conjunction with CSLC 182, but meeting for an additional section, Latin 382 will allow students to encounter a number of Roman poets (Catullus, Horace, Tibullus, Ovid, Propertius) and writers (St. Augustine in particular) in their original language forms.</p> </div>','LATN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15642,2027,3846,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/latn-latin/300/latn-390','<div class="desc"> <p>This course will examine the peculiar aspirations and struggles of the <em>ancient</em> hero--in all the troubled and troubling glamour of their eventful, and often tragically short, lives. We shall begin the course with the four thousand year old story of Gilgamesh, the magnificent yet tormented hero-king of the Ancient Near East; we shall then attempt to interpret anew the meaning of three of the most famous Greek and Roman epic heroes (Achilles, Odysseus, and Aeneas); and finally, we shall conclude the class with an examination of the heroes of the <em>Mahabharata</em>, the great religious epic of ancient India. Too energetic, too angry and far too proud to shrink back from a challenge, these difficult figures made a habit of exposing themselves not only to the mortal dangers of advancing enemy hordes, but, more meaningfully, to all those maddening contradictions our human existence seems to entail for us: the "higher" powers that even against our wills determine us, the sad mortality that against all our longing ends us. Scorning the safety of the familiar and the everyday, the heroes of ancient epic pushed themselves relentlessly to act and to think to the very limit of things. Availing ourselves of any number of modern philosophic theories (deconstruction, phenomenology, existentialism, structuralism and the like), we shall endeavor in this class to think that exasperating limit in intimate company with them.</p> <p>This course will be offered in conjunction with CSLC 190, but will meet for an additional 90 minutes per week to read the Latin texts covered in class in their original Latin form.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>',NULL,NULL,NULL);
