INSERT INTO course_descriptions VALUES(15651,2027,4010,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/300/copy-of-ling-393','<div class="desc"> <div><p>Intensive study in an area of linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15652,2027,857,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/300/ling-301','<div class="desc"> <p>This course is designed as a solid introduction to and overview of the field of linguistics. Students will explore a number of topics that are at the core of linguistics. We begin with a theoretical background in subfields such as syntax, morphology, phonology, and phonetics. Then we move to broader issues such as sociolinguistics, language acquisition, psycho/neurolinguistics, and historical linguistics. Not normally open to first-year students.</p> </div>','One year of a modern language or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15653,2027,1180,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/300/ling-350','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','LING 301 , COGS 101 , or PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15654,2027,2831,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/300/ling-351','<div class="desc"> <p>This course aims to equip students with the understanding of how speech sounds in the world’s languages are produced via an introduction to <em>articulatory</em> and <em>acoustic phonetics</em>. Building on the basics learned in Ling 301, you will learn how speech sounds are articulated; how to describe, compare, and contrast speech sounds in different languages and dialects on the basis of articulatory and acoustic measures; and finally, why knowledge about speech sounds is important to a variety of careers and professions, from speech pathology to language teaching to voice-to-text technology.</p> </div>','LING 301 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15655,2027,4287,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/300/ling-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15656,2027,1387,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/300/ling-397','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15657,2027,3992,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/400/ling-493','<div class="desc"> <div> <p>Comprehensive-level work in an area of linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>When taken as a 4-unit course, you should expect to spend at least twelve (12) hours a week on this course. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15658,2027,3131,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/400/ling-497','<div class="desc"> <p>Independent study project. Permission of the instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15659,2027,4449,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/ling-linguistics/400/ling-498','<div class="desc"> <p>Extended comprehensive-level work in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15660,2027,1179,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-101','<div class="desc"> <p>This interdisciplinary course will introduce students to sources, methods, and approaches in the transnational study of Latin American and US Latino communities. We will focus on the social and cultural interaction of indigenous European, African, and Asian peoples from the colonial period to the present using a variety of primary and secondary materials including films, literature, historical documents, visual arts material, culture, music, scholarly books, and essays. Field experiences in Los Angeles will supplement the course materials. Specific course topics will vary by instructor but may include: migration, mestizaje, indigenism, imperialism, dependency, nationalism, urbanization, popular culture, and social movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15661,2027,2632,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-102','<div class="desc"> <p class="sc-BodyText">This course will examine the diverse forms and social contexts of Latin American and Caribbean music, while exploring the ways that musical performance has been used to negotiate power relations in the social, political, and economic spheres since the Conquest. Focusing on musical genres and movements from Argentina, Brazil, Cuba, Haiti, Mexico, Peru, and Trinidad students will learn to recognize the techniques and instruments used in a wide array of traditional and contemporary styles, particularly those which have grown out of the hybridization of African, Middle Eastern, European, Asian, and Native American performance strategies. While knowledge of music theory and performance skills are not necessary, it is essential that students be prepared for intensive music listening in and out of class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15662,2027,1663,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-150','<div class="desc"> <p>This course provides an overview of the historical evolution of Latin America, from 1492 to 1820. The course begins with an introduction to the indigenous Iberian and African backgrounds, and traces the convergence of cultures and ethnicities that shape Latin American societies and cultures. The course examines this process of change through the writings of Latin American men and women who reflected upon the peoples and culture of their own times. Topics of study include: race and ethnicity, gender, class, native resistance to colonial rule, and Afro-Brazilian religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15663,2027,2343,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-151','<div class="desc"> <p>This course offers a survey of postcolonial Latin America as a process of cultural transformation, political struggle, and economic change. We will explore the complex challenges of colonial legacies posed to emerging nation-states in the nineteenth and twentieth centuries, and seek a balance between engaging particular histories and larger processes common to the region. The first section of the course introduces themes of the nineteenth century: colonial heritage and the different routes taken to political independence; the political, economic, and social challenges of independence in a multi-cultural context; citizenship and race and the development of export agriculture. The second section introduces themes of the twentieth century: industrialization, revolution, U.S.-Latin American relations, and select intellectual trends. Students will use a variety of sources including scholarly works, films, and primary sources to engage these topics and issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15664,2027,4288,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/100/llas-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15665,2027,3870,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/copy-of-llas-207','<div class="desc"> <p>This course will examine contemporary economic, political and social conditions of women workers across the Americas. We will analyze the ways in which US-Latina and Latin American women navigate and resist hierarchical power relations in the globalized labor market. How processes of globalization, transnationalism, work, and family shape womenâs lives are integral to this course. This course will expand the field of labor inquiry to include both productive and reproductive labors. This includes the unpaid âcaringâ work of childcare, housekeeping, and the maintenance of critical community networks. We will consider both the consequences of the sexual division of labor between those considered women and those classified as men but also focus on race, class, sexuality, nationality/citizenship, and other markers of differences. In these contexts, we will explore issues such as development, im/migration and construction of the woman worker to illuminate the gender of political economy and the political economy of gender. Finally, we will analyze struggles for <em>pan con dignidad </em>(dignity and daily bread), the place of affect in organizing, and the prospects for social justice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15666,2027,2633,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-202','<div class="desc"> <p>This course will examine issues and experiences pertinent to Latino origin communities in the United States—principally Mexican/Chicano, Puerto Rican, Cuban, and Central American—from the mid-19th century to the present. Secondary source articles about these U.S. Latino communities will orient students to the consequences of macro-historical events—such as the Mexican American and the Spanish-American wars of the 19th century, and U.S. economic and military intervention in Latin America in the 20th century—and broad social phenomenon in these communities—such as migration, urbanization, labor force participation and expressive cultural production. These secondary sources will support the central critical work of the course, which is to read, discuss and interpret primary source texts and documents that represent and respond to the complex situation of Latinos as racial, gendered and class subjects within U.S. society. These primary materials will include political manifestos and declarations, literary texts, personal memoirs, journalistic essays, musical lyrics and some visual art works.</p> </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15667,2027,2344,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States, and to assess how these communities seek political empowerment, as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life, such as the economy, the state, and the cultural system, on the one hand, and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications, based on race, class, gender, national origin, and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15668,2027,1664,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-206','<div class="desc"> <p>Analysis of the English language development of listening speaking, reading, writing, and thinking skills of elementary and secondary students in culturally and linguistically diverse public-school classrooms. Includes the examination of theories and factors (both pedagogical and political) in first and second language development universals and differences in language structure and use and the transference of first and second language literacy skills. Includes instructional strategies for non-native English speakers (e.g. native language instruction sheltered/SDAIE approaches English language development) integrated into a multicultural curriculum with linguistically appropriate assessment methods and content aligned with state standards.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15669,2027,2345,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) presidents either failed to act in accordance with the transitional justice movements sweeping Latin America or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased, rather than decreased, since its transition to democracy. This class will document why this is the case, as well as look into the various movements that have mobilized since the 1970''s to the present to demand human rights in Mexico.</p> </div>','DWA 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15670,2027,3228,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-211','<div class="desc"> <p>Cultural production is central to the struggle for human rights. As cultural artifacts both conceptualize and memorialize social-political trauma, our class will take a close look at the way that Mexican film, literature and music represents both criminal and state violence. For comparative purposes, we will also look at some documentaries or film about the current violent situation in Central America. As this is a 4-unit course, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> <p><strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico (as well as Central America) through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15671,2027,2346,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-213','<div class="desc"> <p>This course will cover the historical and current educational issues relating to the largest non-white population in the United States Latinos. The term "Chicano" is used in the political context to reflect the struggle for educational equality of all Latinos. The course emphasizes the social, political, and economic condition of Chicano students and the impact these conditions have on their educational success in the United States.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15672,2027,3361,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-221','<div class="desc"> <p>Between the 1960s and the 1980s, as feminist theologians of Latin America actively confronted the Vatican’s and liberation theology’s insufficiencies in leading the marginalized out of cycles of socio-economic oppression, such theologians were commonly deemed “indecent.” In this course, we will examine how various Latin American women and social movements embraced and practiced indecent liberation, starting with the Mexican Revolutionary period and concluding with global understandings of indecent liberation in relation to religion and feminism. We will ask: How has “indecency” been constructed as a site of hegemonic power, particularly at the intersections of religion, race, gender, class, and/or able-bodiedness? In what ways is indecent liberation a form of empowerment and (how) does it relate to identity-formation? Is indecency merely a tool for liberation or a place of generative knowledge and ways of being? We will answer these questions through three main case studies, starting with “muscular” Christian women of the Mexican Revolution, continuing with indecent liberation theology during the mid- to late- twentieth century, and concluding with contemporary chicana epistemologies and ecofeminism. At the end of the class, students will apply course content to a case study of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15673,2027,4289,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-223','<div class="desc"> <p>This course is an introduction to Mexican philosophy, and indirectly to Latin American philosophy. We will discuss Mexican contributions to universal questions (such as the nature of art, democracy, humanity, and racial, sexual, and ethnic identity), and we will raise the question of Mexican philosophy (what is it, how is it different from Western philosophy) by situating it in the context of other cultural expressions of Mexican identity, such as Mexican food, literature, and Mexican muralism. Thus, this course is also an introduction to comparative philosophy more generally, since it aims to challenge Eurocentrism by demonstrating that philosophy is grounded in or is an expression of cultural identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15674,2027,4290,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-226','<div class="desc"> <p>This course examines the construction and reproduction of masculinities primarily in Latina/o and Latin American communities. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p> </div>','SOC 101 or SOC 102 or SOC 105 or LLAS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15675,2027,3229,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-228','<div class="desc"> <p>Latino/a religious social movements around the world have pursued liberation from oppressive forces and sought to move toward just and equitable futures. In this course, we will examine the ways various Latin American social movements from the late nineteenth century to the present day have defined and practiced liberation, paying special attention to the distinctive role of religion in these movements. We will ask: How can religion provide a foundation for liberation? More specifically, how can religion foster visions of life honoring justice and prosperity? In what ways have religious communities lead organized resistances? And even when mobilizing for liberation, to what extent can religion continue to solidify forms of oppression? We will seek to answer these questions through a series of case studies including: 1) a unique form of “muscular” evangelical Christianity across Latin America after the Spanish-American War (1898) that sought to combat the oppressive powers that limited their sovereignty; 2) liberation theology and spiritual praxis within the Mexican American Civil Rights Movement of the 1960s; and 3) Latino/a global missionary efforts through various evangelical organizations. At the end of the class, students will have the opportunity to apply what they have learned to a Latin American social movement of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15676,2027,3133,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-229','<div class="desc"> <p>After a review of the historical, legal, and conceptual underpinnings of the international protection of human rights, students in this course will learn about human rights and mechanisms for their protection within the context of the United States and Latin America. Students will discuss key situations from the last half century involving challenges to human rights, including the phenomenon of disappearances common in Argentina and Chile in the 1970''s, violations of human rights during leading up to and during civil conflicts in Central America, and the impact of neoliberal economic reforms on human rights in the region. Students will explore the application of the death penalty in the United States, United States foreign policy on human rights in the Americas during the Cold War, and the claims of human rights abuse by the United States during the War on Terror. They will also have a chance to examine the United States from a double perspective: on the one hand as a key country with a major interest and impact on human rights conditions in Latin America, and, on the other, as a country with its own policy areas of struggle and progress.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15677,2027,4291,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-241','<div class="desc"> <p>This course provides a multi-disciplinary insight into various aspects of migration and immigration law and politics. Students read and analyze important legal precedent through the study of case law as well as explore historical trends in migration to the United States. This course approaches the issue of immigration from three major standpoints: the legal, the political, and the historical. Topics include but are not limited to immigration from Latin America, asylum, temporary protected status and citizenship. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15678,2027,1706,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-250','<div class="desc"> <p>This highly interactive seminar brings students from different identity groups together for informed, sustained, and respectful dialogue about “hot topics” in the lives of Latinxs in the U.S. There are three components to the course. Part 1 focuses on Dialogic Skill Building; Part 2 focuses on Power, Privilege, and Group Membership; and Part 3 focuses on specific Hot Issues (see below for specific topics). Course goals include a deeper intellectual and personal understanding of the structural implications of Latinx/Latin American identity in the U.S., honed ability to communicate across difference, and development of intergroup alliances. Seminars are co-facilitated by a faculty member and trained peers representing intersectional identities within Latinx culture. A semi-structured curriculum integrates readings, experiential activities, dialogue, and reflective writing. Next year’s topics include: Identity -- Who is Latinx? (phenotype, class, language, authenticity); (in)visibility and Representational Challenges (Beyond the Black-White binary, Media, ); Politics of Intersectionality and Simultaneity Across Contexts and Generations (Assimilation, Enculturation, Gender, Sexuality, and Religion); Educational Options for Self or Community (Curricular marginalization, Counterspaces or Balkinization); Political Resistance and Coalition Possibilities (Ideological tensions, Rebellious Lawyering, Work). Student demand will determine whether an Intragroup (all Latinx) Dialogue or an Intergroup (mixed race) Dialogue option will be offered.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15679,2027,4292,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-252','<div class="desc"> <p>This course offers a broad survey of Mexican religion from pre-Columbian times to the present. The course begins with the study of Nahua ("Aztec") spirituality and ritual and continues with an examination of major developments of the colonial period as indigenous European and African peoples came together with their many different beliefs and practices. We will study indigenous strategies, of both resistance and accommodation, to the imposition of Catholicism, the origins of the devotion to the Virgin of Guadalupe, the Mexican Inquisition, millenarian movements, missions, and women in the church in the colonial period. Our study concludes with the anti-clerical reforms of the late nineteenth- and early twentieth-centuries, the Cristero Rebellion, increasing influence of Protestantism, and the persistence of local religions in modern Mexico. Students will analyze historical documents, religious dramas, confessional manuals, Inquisition records, paintings, sculptures, and films in their examination of the history of religion and spirituality in Mexico.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15680,2027,4417,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-253','<div class="desc"> <p>In this course, we will examine the lives of 1.5 and second generation immigrant youth in the United States since the 1920s, with particular attention on identity formation and youth cultures in the present day. Throughout the semester, students will read empirical studies about immigrant youth with cultural ties to numerous countries, especially countries in the Americas and Asia. Students will learn about: (1) the theories of acculturation and assimilation sociologists use to analyze the experiences of immigrant youth; (2) immigrant youth from different immigrant communities; (3) how geographical location, social class, gender, race/ethnicity, sexuality, immigration status, popular culture, mass media, and technology inform the identity construction of immigrant youth. Students will write papers that articulate an original thesis with supporting evidence.</p> </div>','SOC 101 or SOC 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15681,2027,2901,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-254','<div class="desc"> <p>This course examines historical and cultural constructions of race from the time of contact between indigenous European, African, and Asian peoples in the colonial period to the present. We begin with the establishment and evolution of the ethnic hierarchy in the colonial period; focusing especially on African slavery in Latin America; interethnic interaction among Iberians; indigenous and Africans; and attitudes toward marriage, sexuality, and racial mixing. The course continues to explore a broad variety of themes in the modern period, including racial ideology and national policies and identities, immigration, the marketing of whiteness, the legacy of slavery, and Afro-Latino and indigenous social movements. The class focuses on Mexico, the Caribbean, the Andes, and Brazil, but we will not neglect to consider many other places such as Venezuela, Central America, and California.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15682,2027,3220,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-256','<div class="desc"> <p>Since the fall of the Mexica (Aztecs) to the Spaniards in August of 1521, writers and artists have represented the dramatic events leading to the conquest of Mexico. Major figures of the conquest, such as Hernando Cortés, Malinche, Moteuczoma, and Cuahtemoc, have been memorialized, mythologized, and in some cases villainized. This course examines representations of the conquest and the leading figures of the period from a variety of perspectives. We will consider how changing political and cultural contexts have shaped remembrances of the war and the consequences of colonial rule. In this course, students will analyze a variety of sources, including Spanish and indigenous accounts, pictorial writings, paintings and artworks, operas and films. In addition, we will examine contemporary artistic projects, museum exhibitions, and archival programs that have been organized to commemorate the 500-year anniversary since the fall of the Aztec Empire.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15683,2027,2554,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-258','<div class="desc"> <p>This course seeks to engage you in the fundamental problems of twentieth century Mexican history and introduce analytical frameworks for studying cultural politics. The central theme will be how the state and grassroots society negotiated the course of the nation and its political culture since 1875. We will critically examine the production of the dominant historical narrative and develop alternative ones that can help us understand the differences in the historical experiences of subaltern groups, including women, indigenous people, and <em>campesinos </em>within the Porfirian, revolutionary, and post-revolutionary periods. We will examine what is cultural about politics and what is political about culture through an interdisciplinary format, perspective and organization drawing upon the fields of history, anthropology, literature, and visual studies.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15684,2027,2598,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-260','<div class="desc"> Through analyses of literature, film, music, and graphic art we will explore how Latinos have represented their individual and collective experiences in the United States. In order to allow some depth of comparison, primary attention will be given to the creative works of Chicanos in Los Angeles and Puerto Ricans in New York. However, other national origin communities (such as Dominican, Salvadoran, Guatemalan, and Cuban) will be selectively incorporated in the course. </div>','One First Year Seminar ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15685,2027,3238,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-261','<div class="desc"> <p>Colombia’s 2016 peace accord formally brought an end to a half-century of that country’s civil wars. The accord’s implementation, however, has been troubled. This raises issues relevant to Colombia and to other locales putatively transitioning out of violent conflicts. This course will address those issues in a Colombian context and by comparative reference to examples from other countries in the Americas and around the globe. Specifically, what is transitional justice and how might it inform peace-making in a country such as Colombia? Are human rights relevant to more effective transitional justice processes? More specifically, can they inform a truth-telling processes that takes into account the distinct context of a country such as Colombia and helps it establish the basis of a more pluralistic social contract that engages all of its remarkable diversity, including identities (ethnic, gender, sexual) that have long been marginalized? The course uses Colombia as a focal point, but will draw from other comparative cases both from Latin America and the globe.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15686,2027,3924,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-270','<div class="desc"> <p>Beginning in the late 1970s, revolutionary movements would shake Central American societies and shape U.S. foreign policy with direct military and covert intervention in the region. Often framed as the final battleground of the so-called Cold War between the U.S. and the Soviet Union, scholars of Central America prefer to emphasize the complexity of internal social and political forces and the U.S.’s continual efforts to undermine national sovereignties and control anti-capitalist and anti-authoritarian movements in its “back yard.” This course will allow students to examine the historical formation of three distinct militarized and antidemocratic states, Guatemala, Nicaragua, and El Salvador, and the revolutionary movements that sought to radically engage in social transformations between the 1970s and 1990s. Principal themes of the course include: capitalist development and structural inequalities; revolutionary ideologies; organizational development and objectives of Central American revolutions; US interventions; social transformation and change; and lasting impacts of revolutions.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15687,2027,4293,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15688,2027,4294,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/200/llas-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15689,2027,3928,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-300','<div class="desc"> <p>This course provides an introduction to a broad range of approaches and methodologies used in the interdisciplinary fields of Gender and Ethnic Studies. These methods include (but are not limited to) archival and historical research, textual analysis, fieldwork, action research and visual analysis. We will learn about these methodological approaches along with the foundational goals and theoretical discussions of fields such as Latina/o Studies, Sociology, Cultural Studies and Gender Studies to conceptualize and locate our research projects within the different disciplinary fields that inform our scholarship. The course also considers what constitutes interdisciplinary research and how we can implement it in our own practice. Throughout the semester students will develop an original research proposal and conduct preliminary research by creating a corpus of textual and visual data.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15690,2027,2797,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-301','<div class="desc"> <p>This historiography seminar examines the sources, methodologies, and theoretical approaches that shape the history of women, gender, and sexuality in colonial and nineteenth-century Latin America. A variety of interdisciplinary approaches and concerns are considered from an historical perspective, especially in relation to the fields of Latin American History, Women''s/Gender History, and Sexuality Studies. The readings represent ethnic, racial, and class-based distinctions among women in Latin America, and emphasize the importance of using diverse approaches in reconstructing gender history and culture, particularly for indigenous and African women. The course is organized to illustrate major trends in the historical scholarship on colonial Latin America, and highlight the shift over the last three decades from the study of women to gender and, most recently, sexuality and back to women again.</p> <p> Historiography is the study of how historians write history and how the field has evolved over time. In this class our emphasis will be on how the historian came to his or her conclusions, not simply on the conclusions themselves. We will also consider each work in relation to other books in the field. Students will analyze both primary and secondary sources to understand how history is conceived and written.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15691,2027,4295,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-302','<div class="desc"> <p>Studies of the Mexican Revolution have been at the forefront in the development of modern Latin American social, political, and cultural history. The studies have also contributed to comparative discussions in world history about the meanings of revolutionary experience in the twentieth century. However, historians and other social scientists have reached no consensus about the Mexican Revolution from its periodization to its actual existence. This seminar will examine the competing set of interpretations, alongside primary sources, to analyze the origins, course, and legacy of the Mexican Revolution. Prominent historiographical themes for the course include: conflict between elite liberalism and mass mobilization; agrarian reform and unionization within a capitalist project of development; corporate representation of social interests; the institutionalization of revolution; race, gender, and class in nationalist rhetoric; and the role of art, education, and science/technology in state formation. This course may not be used to satisfy a Core requirement.</p> </div>','One history course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15692,2027,1665,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-303','<div class="desc"> <p>The focus of this course is on the history, literature, and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works, as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works, while play attendance will keep our focus on these plays as performance. There is a ticket fee of $50 for the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15693,2027,2898,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-304','<div class="desc"> <p style="margin-top: 10px;">Studies of the Mexico-U.S. Borderlands have been at the forefront in the development of transnational history frameworks as well as comparative discussions about borderlands histories. This seminar engages the fields of Native American Studies, Chicanx Studies, Mexican history, and U.S. Western history to trace the historiography of a region that has undergone a series of extensive transformations in the last three hundred years. In the modern era, it changed from a periphery of the Spanish empire, to provinces of northern Mexico, and finally, to the southwestern region of the United States. The area is a site of complicated and overlapping histories marked by processes of colonialism, diaspora, nationalism, and deterritorialization. With particular attention to issues of race, gender, place and power, prominent historiographical themes for the course include: the frontier thesis; war and displacement; transborder and transcultural communities; labor and transnational capitalism; extractivism and environmental justice; and migration and militarization. </p> </div>','One History course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15694,2027,4012,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-308','<div class="desc"> <p>This course asks: what is the ghost, and when does it take hold of the world? Through a series of case studies focusing especially on Latin America and North America—ranging from classical scholarship on Haitian vodou and Brazilian Candomblé to contemporary work on alien abductions and Cuban Santería—this course examines the category of spirit possession. In it we will take a look at the ways in which spirits are understood to possess people, haunt places, and inhabit objects. We will consider different scholarly interpretations of spirit’s saturation of matter, asking how these phenomena relate to the historical traumas inflicted by chattel slavery, colonialism, and economic inequality. Finally, we will interrogate the category of “spirit possession” itself, asking how the category might relate to regimes of property ownership and serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15695,2027,2599,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. To a lesser degree we will also examine Central American immigration from an international relations perspective.</p> </div>','LLAS 101 or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15696,2027,3871,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-322','<div class="desc"> <p>Central American feminisms have been an integral dimension to struggles against imperialism, dictatorship, and globalization across the Isthmus. This course will examine the development of Central American feminisms beginning with the revolutionary period of the 1970s and 80s up to the present. We will explore feminist epistemologies and cultures of resistance, looking at how feminists make interventions through artistic practices. We will examine the transnational dimension of feminist organizing in the region, looking at how shared histories and dialogues shape how Central American women theorize about feminism through their lived experiences. To do so, we will study critical texts written by feminist writers and collectives, historical testimonios as well as feminist cultural productions such as music and art. We will also explore how global discourses touch down and shape Central American womenâs political claims as well as how Central American feminists influence international organizations and global conceptions of human rights. Topics we will explore include contemporary regional histories and womenâs roles in social change, gendered violence and femicide, reproductive rights, memory and artivism, and motherhood as a political identity.</p> </div>','LLAS 101 or SOC 101 or HIST 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15697,2027,4296,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-323','<div class="desc"> <p>This course examines philosophical reflections on the Latinx experience, focusing on the contributions of US philosophers of Latin American decent. A sample of questions to be considered: What does it mean to be authenticallyLatinx? Is Latinx identity a racial, ethnic, or political identity? How do Latinx philosophers fit into the "canon"? What are some of the overarching lessons of Latina feminist philosophy? Are Latinxs, particularly immigrants, a threat to âAmericanâ values, as some argue? What is the meaning of âLatinxâ and why is the âxâ important? Is Latinx philosophy unique, distinctive, valuable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15698,2027,3991,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-324','<div class="desc"> <p>This course explores the complex history and development of populist regimes in Latin America from the early 20th century to the present. Through a combination of historical analysis, theoretical frameworks, and case studies, we will examine how populist and nationalist ideologies have shaped and transformed political, economic, and social structures across the region. Key topics include the rise of charismatic leaders, ideological constructions of “us” vs “them,” rhetorical strategies, and the relationship between populism, nationalism, and authoritarianism. We will start with the region’s most well-known populist figures of the 20th century: Brazil’s Getulio Vargas and Argentina’s Juan and Eva Perón. We will then examine more recent figures like Peru’s Alberto Fujimori and Pink Tide figures like Venezuela’s Hugo Chávez, and Bolivia’s Evo Morales. Finally, we will turn to contemporary figures like Brazil’s Jair Bolsonaro, Nicaragua’s Daniel Ortega, and El Salvador’s Nayib Bukele.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15699,2027,2639,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-355','<div class="desc"> <p>This course on Mexican history studies the complex cultures and civilizations of indigenous peoples, from prehispanic times to the present, focusing, especially, on the Nahua ("Aztecs"), Maya, Mixtec, and Zapotec. The course examines the cultural survival of native peoples who have faced the challenges of conquest, devastating population loss, secondary status under Spanish colonial rule, constant exposure to external influences, and continuing exploitation to the present. The course traces the evolution of native community organization; art forms; social structure; and religion in the colonial and modern periods; and considers native responses to contemporary issues, such as migration, environmental degradation, and social injustice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15700,2027,2555,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-357','<div class="desc"> <p>Renowned for its dramatic scenery, from the desert of Sonora to the coasts and reefs of the Yucatán, to the volcanoes of the Sierra Madre range and cloud forest of Monteverde, Mesoamerica, is also known for its increasingly unmanageable and overpopulated capitals such as Mexico City and Guatemala City. The variety of natural and built environments in Mesoamerica has produced a diversity of social, cultural, and political landscapes. This seminar explores the ways in which different cultural groups have perceived, used, managed, and conserved the Mesoamerican environment from colonial times to the present. We will address a number of interrelated questions about the relationship between Mesoamerican societies and the environment. How have natural environments established parameters for human economic and social activity? How have Mesoamericans interpreted and then reshaped their environmental surroundings to satisfy their supposed needs? What impact have race and gender had on perceptions of the environment? What have been the environmental consequences of the colonial, subsistence, and agro-export economies the 19th century infatuation with progress and the 20th century creation of industrial and urban conglomerations under the aegis of developmentalist ideologies? What is the historical geography of five centuries of sustained degradation and sporadic conservation of Mesoamerica''s bio-physical environments? How have different groups of Latin Americans interacted in their quest to manage, control, and distribute natural resources? We will pay particular attention to how the relationship between humans and their natural and built environments shaped Mesoamerica''s social and political development.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , or UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15701,2027,2692,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-358','<div class="desc"> <p>This seminar examines Mexican foodways deemed by UNESCO as an Intangible Cultural Heritage of Humanity from the Postclassic Period to the present. We begin with the premise set by anthropologist Sidney Mintz that food is always a matter of cultural history, political economy, and systems of meaning. The themes of indigenous cuisines, food and empire, commodities and capitalism, national and popular cuisines, nutrition and nation building, and globalization and food sovereignty will guide our readings and discussions. With particular attention to issues of race, gender, and class, we will consider historical problems linked to economic inequality, gender relations, and environmental degradation.</p> </div>','HIST 150 , HIST 151 , LLAS 101 , UEP 101 , or SOC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15702,2027,3925,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-361','<div class="desc"> <p>This course centers on representations of gender, race, class, nationality, and sexuality in Latinx and Latin American film. We will examine the economic, racial, and gendered inequalities that stem from histories of colonization and neocolonialism in Latin America and in the diasporic Latinx communities that have formed in the United States. Using a transnational lens, students will assess the limits and possibilities of film in documenting histories of oppression and social inequalities facing Latin Americans and Latinx communities in the U.S. We will turn to feminist film theory, critical film theory, cultural studies, and Latin American history and politics in order to facilitate our analysis and class discussions of these films.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15703,2027,2347,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-385','<div class="desc"> <p style="margin-left:0in; margin-right:0in">The course examines key relationships between Chicanx/Latinx identity and social institutions. We begin with a brief historical foundation for Chicanx/Latinx life in the U.S. This socio-historical context sets the stage for an informed examination of identity, with particular attention focused on the <strong><em>interpersonal </em></strong>implications of cultural, gender, phenotype/color, sexuality, and geographical identities. Finally, drawing on interdisciplinary scholarship we consider the <strong><em>structural</em></strong> implications of these identities on the educational, health, and political lives of Chicanx people. Instructor permission is required and available for first-year students.</p> </div>','PSYC 101 , SOC 101 , HIST 102 , AMST 101 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15704,2027,3861,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-390','<div class="desc"> <p>This course examines the political ecology/economy of food, agriculture, and hunger in Los Angeles with an emphasis on Latin American-Caribbean relations. Students will explore these themes through readings, lectures, and a class-based research project in the city where students will gain practical experience in research design and apply techniques such as qualitative interviews and surveys, oral histories, ethnography, participant observation, and utilize archival material and visual and audio documentation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15705,2027,4297,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15706,2027,1386,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/300/llas-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15707,2027,1125,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/400/llas-490','<div class="desc"> <p>In this course, students will write their senior theses on Latin America or Latino communities. Seminar meetings will focus on issues concerning research methods and will guide students through the steps of writing a substantial essay. Students will present their findings in a public forum at the end of the course. Open only to LLAS majors.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15708,2027,4298,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/llas-latino-a-latin-american-studies/400/llas-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15709,2027,1530,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-143','<div class="desc"> <p>This 100-level gateway course introduces students to key concepts and methodologies for the critical analysis and interpretation of a broad range of media forms across the visual field - including film, television, social media, photography, games, advertising, etc. - and the cultural, historical, and ideological forces that govern them. Drawing from select case studies in media and visual culture, the course emphasizes critical reading, discussion, and writing, with forays into digital scholarship.This course is not open to Juniors or Seniors. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15710,2027,1666,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-145','<div class="desc"> <p><em>Born Digital</em>, <em>Growing Up Digital</em>, <em>Teaching Digital Natives</em>, <em>Understanding the Digital Generation</em> ... these are just some of the titles in a veritable explosion of guidebooks on how thinking, learning, and doing have changed in a world transformed by digital, networked, and social media. In this 100-level gateway course, we take a critical look at the theories and prophesies on the "Net Gen"; we explore and assess new digital possibilities for communicating, teaching, and learning; and we think critically, contextually, and historically about the ways in which new media forms and practices shape identity, community, sociality, creativity, privacy, civic engagement, and everyday life. Class projects will enable students to experiment with, and gain, practical experience applying a range of media 2.0 technologies to their own academic work. This course is not open to Juniors or Seniors. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15711,2027,1531,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/100/copy-of-mac-146','<div class="desc"> <p>This 100-level gateway course breaks down the aesthetic components of film and examines each element''s function in the production of meaning in a text. The course underscores the fact that cinema''s aesthetic language is not solely generated by Hollywood. It is a fluid system, highly contingent upon cultural, temporal, technological, and economic considerations. Selected international and alternative cinema movements will be examined for their enduring influences upon the global audiovisual aesthetic lexicon. Students will learn to connect formal analysis to cultural criticism and will engage with key disciplinary theories and writing methodologies. This course is not open to Juniors or Seniors. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15712,2027,1529,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/100/mac-110','<div class="desc"> <p>This course focuses on the fundamental processes and tools involved in digital design for the media arts: color, resolution, image manipulation, compositing, typography, vector graphics, web/app design principles, project workflow, and output/finishing formats. Students will become familiar with the interfaces of essential software platforms, including Adobe Photoshop and Illustrator, and will apply concepts and techniques to various assignments. Open only to MAC majors and minors. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15713,2027,4299,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/100/mac-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p>Laboratory fee for projects in production: $55.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15714,2027,1667,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-210','<div class="desc"> <p>Motion graphics and motion design are becoming increasingly vital, creative, and technical capacities for digital media production. This course focuses on the fundamental concepts, processes, and tools involved in motion design for the media arts: keyframe editing and interpolation, masking, effects, character rigging, camera movements, and titling. Students will become familiar with the interface of Adobe After Effects while exploring concepts of rhythm, space, and time, and will apply concepts and techniques to various assignments.</p> </div>','MAC 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15715,2027,1532,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-220','<div class="desc"> This course focuses on the fundamentals of screenwriting and on the theory, form, and practice of audiovisual, time-based storytelling for screens. Through a series of screenings, critical readings, creative writing exercises, and the crafting of a short screenplay, students will become versed in the critical, political, and creative potentials of writing for screen cultures, including manipulation of time, space, and point of view, character development, and narrative theory. Open to all students. Required for any MAC major seeking to write a screenplay/pilot script or produce a short fictional media project for Senior Comprehensives. Registration is by instructor permission only. Before the end of advising week each semester, interested students must add their name to the consideration list here: https://bit.ly/MAC220 </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15716,2027,3236,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-222','<div class="desc"> <p>This creative writing workshop will focus on fictional episodic and serialized series, also known as television shows or streaming series. Students will be required to develop their own original fiction series concept. The emphasis will be on developing a professional and impactful series pitch. This will involve extensive writing and verbal pitching. Developing a concept for a pilot episode will be part of the course but a pilot script will not be written. Students will also analyze existing series and will engage in thoughtful critique of their own work and the work of their peers. Screenings, readings, and discussions will also explore the influence that changing distribution and viewing patterns have on modes of storytelling and diversity/inclusion. This course is focused on live-action single camera dramas, live-action single-camera comedies, and, to a lesser extent, animated series. No sitcom/multi-camera comedy ideas will be considered or created.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15717,2027,1533,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-240','<div class="desc"> This course builds upon the critical and historical grounding of MAC 100-level gateway courses, providing students with foundational media production skills and exposure to the wide-ranging creative possibilities of time-based media practices. Students will conceptually and practically explore historical and contemporary approaches to fictional, documentary, and experimental media through a series of production projects, each supplemented by a range of readings, exercises, technical workshops, guests, screenings, and critiques. Not open to seniors. Required of all students in the Media Production Focus. Prioritization given to intended MAC majors (both Critical Media and Media Production focuses). Registration is by instructor permission only. Before the end of advising week each semester, interested students must add their name to the consideration list here: https://bit.ly/240MAC </div>','MAC 143 , MAC 145 , or MAC 146 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15718,2027,2454,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-241','<div class="desc"> <p>In a digital moment where both the democratizing and totalitarian possibilities of media are unprecedented, the need to analyze and understand both the politics and <em>poetics</em> (the distinct audiovisual rhetorical strategies) of documentary media has never been more vital. This class combines readings, screenings, discussions, group exercises, and distinct forms of critical and professional writing to explore the evolving histories, theories, ethical questions, and creative modes of documentary. Together we will examine how documentary media can effect social change, expand the diversity of voices and stories that are seen and heard, and challenge each us to reimagine our fundamental conceptions of "truth" and "reality." </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15719,2027,1707,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-242','<div class="desc"> In our dynamic digital moment, the question, "What is a documentary?" can be answered with ever-increasing complexity. Works professing truth claims about our historical and present "realities" are just as much constructs as any fiction film, a realization that presents both creative opportunities and ethical responsibilities for documentary practitioners. This hands-on course will explore and develop a poetics of documentary, underscoring that the politics and meaning of documentary works come not simply through their content but through their aesthetic strategies and processes of production and distribution. A series of media projects will be supplemented by discussions of theoretical readings, screenings, and technical workshops. Open to all students. Required for any MAC major seeking to make a documentary-based Media Production Senior Comprehensives project. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15720,2027,3304,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-243','<div class="desc"> <p>This course introduces students to the theoretical and analytical frameworks necessary to critically understand representations of race, gender, and sexuality (among other topics in American culture) in contemporary American film and media. Using critical theory, historical analyses, and theories of analyzing film and media, we will explore issues relevant to American studies, including race, gender, sexuality, class, family and nation, and private and public space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15721,2027,1534,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-244','<div class="desc"> <p>This intermediate topical course of varying emphases focuses on representations of difference, while underscoring the connections between race, class, gender, and sexual identity. Through screenings, and key texts from film and media studies, cultural studies, gender studies, and visual culture studies, students will learn critical methodologies for analyzing a range of media forms and the complex relationship between authors and spectators. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p><p><strong>Female Filmmakers Producing, Performing, and Screening Racial Identity </strong></p><p>From early cinema to modern motion pictures, filmâs shifting landscape has offered a place for crafting, obscuring, reflecting, and subverting ideas of race and ethnicity. Drawing on perspectives from cultural studies and critical race theory, this course will examine race and ethnicity, along with intersecting issues of gender and sexuality, from the positions of the filmmaker, film, and spectator, as well as the ways that film language and behavior construct racial and ethnic identities. Our course screenings will be drawn from a global film catalogue focusing on works written, produced, and/or directed by female filmmakers, including Jane Campionâs <em>The Piano</em> (1993), Gurinder Chadhaâs <em>Bend It Like Beckham</em> (2002), Julie Dashâs <em>Daughters of the Dust</em> (1991), Claire Denisâs <em>35 Rhums</em> (2008), and Marjane Satrapiâs <em>Persepolis</em> (2007), and our readings will incorporate texts and excerpts from such theorists as Richard Dyer, Ed Guerrero, Linda Williams, and Lola Young. Through screenings, readings, and class discussions, we will produce rhetorical analyses, visual and oral presentations, and analytical critiques to help us engage dialectics of race and ethnicity in film.</p><p><strong>The Female in Japanese Film and Media </strong></p><p>The course will consider the role of the female in Japanese film in front of and behind the camera. In the current climate of the #metoo and #timesup campaigns and revelations of sexual harassment in the Hollywood film industry, where does the Japanese film industry stand? This course will look at Japanese cinematic history whose roots are embedded in the studio system in Kyoto and consider how the role of women in film has been shaped by a changing societyâs values and norms. The contributions from Japanese female film directors such as the pioneers Sakane Tazuko and actress-director Tanaka Kinuyo to their contemporary counterparts such as award-winning Kawase Naomi, the pink films of Hamano Sachi, relationship driven films of Mishima Yukiko, to the fashionable flair of Ninagawa Mika. We will look at emerging female filmmakers such as Oda Kaori, Endo Maiko, and media artist Sputniko! who are using the format of the moving image to engage Japanese audiences in global issues. In addition to looking closely at works from female film directors, the course will examine tropes and representations of iconic actresses within Japanese cinematic history to appropriation of Japanese culture in pop music videos. <em>Additional Core Requirement Met: Regional Focus.</em></p><p><strong>Cultures of Protest</strong></p><p>The English word <em>protest</em>â âto declare publiclyâ â derives from a Latin verb meaning âto testify, give witness.â In this course we will explore a variety of films from different geopolitical regions and of different genres and different historical contexts that might be interpreted as speaking to all kinds of modalities of protest: protests against nationalisms, against ethnic cleansings, against xenophobia, racism, and homophobia, against national violence and against gender purity. We will engage with different understandings of the concept of protest and focus on its relation to migration, foreignness, national identity, racial, gender, and sexual politics, border politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations.<em>Additional Core Requirement Met: Global Connections</em></p><p><strong>From Cyborgs to Siri: Gender, Technology and Media</strong></p><p>In this course, we will examine the humanoid robots, cyborgs, and AIs imagined in film, television, and advertising, as well as the dialogue between these fictional creations and their real-life counterparts, from historical automata to the current development of robotic and virtual assistants and companions. How does techno-fantasy inform material reality, and vice versa, in the construction of these figures? What roles do we ask them to play in both realms? What social, cultural and historical conditions give rise to, and shape, their appearance? What cultural hopes and fears do they reveal? In answering these questions, we will examine issues around gender, sexuality, and race, while drawing from a wide range of critical discourses, including technoculture studies, cyborg feminism, post-humanism, and afrofuturism.</p><p><strong>Feminist Provocations</strong></p><p>In a historical moment when border walls and refugee camps are once again proliferating, ethnonationalism and white supremacy are on the rise, and womenâs rights, queer rights, and immigrant rights are being violated, we must ask about feminist provocations. The dictionary explains provocations as âsomething that incites, instigates, angers, or irritates.â Etymologically, the term comes from Latin prÅvocÄtiÅn, meaning âa calling forth.â Embracing intersectionality, multidimensionality, and historicity, this course explores questions of politics, aesthetics, and ethics as we analyze diverse representations of such âcalling forthâ in cinema and various experimental media forms. We will examine such calls for subverting various systems of oppression that perpetuate patriarchal domination in global contexts while studying feminist visuality, film theory, queer theory, and theories of difference. Additional Core Requirement Met: Global Connections.</p><p><strong>Feminist Ethnocines: Troubling Histories of Visuality from Ethnographic to Experimental Cinema </strong></p><p>This course bridges the concerns and aesthetic inquiries of ethnographic film and experimental film across the 21st century through a close examination of <em>ethnocines</em> as a feminist visual culture formation. By historicizing visual cultures of science and technology at the turn of the 20th century, we will take an expansive view of the co-emergence of cinematic and scientific instrumentation that paved the way for new modes and models of spectatorship to emerge in the 21st century. Along the way, we will consider how these techniques and practices of looking shaped both early ethnographic film experiments as well as experimental film genres that addressed and defied authoritarian scopic regimes. We will consider film texts and archives by feminist ethnographers, documentarians, experimental filmmakers, and video artists whose works query: who has the right to look? Drawing on conceptual frameworks from feminist film historians and feminist science and technology (STS) scholars, we will examine how hegemonic regimes of visualization made possible by screening architectures (from proscenium theaters to the automobileâs windshield screen) have proved fertile ground for daring feminist experiments in film to addressâand imagine beyondâthese gendered and racialized regimes.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15722,2027,2678,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-245','<div class="desc"> <p>This practice based course focuses on a specific topic in media production. Students will explore the propensities and challenges of a particular production approach, model, technology, or aesthetic practice through the creation of a series of media projects. Classes will include screenings, readings, and discussion that situate these practices conceptually, ethically, and culturally but the emphasis is on hands-on project creation as a means of understanding the production topic at hand.</p><p><strong>Visual Storytelling</strong></p><p>This course focuses on understanding and designing visual structure and story in cinematic media. Students will critically reflect on how visual components communicate meaning while creating image systems through photographic exercises, video sketches, and concept design lookbooks. Coursework explores cinematography, production design, and compositional elements including color, value, line, shape, depth, and visual rhythm. Students will examine how these principles shape visual style across film and emerging media forms.</p><p><strong>Process-Based Mediamaking</strong></p><p>A hands-on media production course in which the final result of each project is, to some extent, outside of the creatorâs control. The vast majority of traditional film and television is intentionally scripted or planned in advance and the production/filmmaking process is focused on capturing images and sound that perfectly execute that script or plan. Process-Based Mediamaking is an alternative to this system. It is rooted in the idea of developing a process, methodology, or set of rules ahead of time and then letting that open-ended, exploratory, and in some cases even random, approach generate media art. This course will consider historical and current examples of Process-Based mediamaking but the main emphasis of the course is the creation of this kind of media. No prior mediamaking experience is required.</p><p><strong>Artificial Intelligence (AI) Film and Media Creation</strong></p><p>This hands-on media-making course will explore the emerging practice of using generative AI and other artificial intelligence tools to create cinematic media. In just a few years, AI tools have gone from barely useable to being able to create highly realistic images, video, and audio. Established and emerging artists (and production companies and studios) are increasingly using these tools in both artistic and commercial contexts. Students will complete a series of creative assignments that will examine the affordances and limitations of current AI tools. A major focus of the course will be the legal and ethical questions raised by the technology, particularly in relation to intellectual property, deception/deep fakes, labor, the environment, and what it means to make art. Students who are skeptical about the use of AI are welcome in the course but must be willing to use these tools to complete assignments.</p><p><strong>Micro-Budget Feature Film Development</strong></p><p>One of the most common ways for aspiring directors to break into feature filmmaking is to produce and direct a so-called âmicro-budgetâ feature film, a varyingly defined category of film that costs âvery little moneyâ and that it is possible to produce in an entirely independent manner. This is a hands-on class where each student will focus on the creative and logistical development of a concept for a micro-budget feature film. There are many approaches to micro-budget filmmaking and students will analyze a series of case-studies to better understand the history and current state of this film genre. The micro-budget form has, historically, been a way for filmmakers to break into the feature film world and also a form that allows for a high degree of personal expression. The primary work in the class will be each student brainstorming an idea for a micro-budget feature film and creating an aesthetic and producerial plan for the film. A screenplay will not be written in this course but the plan created in the class could guide the writing of a screenplay after the course. Ideally, students will have taken at least one MAC class with a media production or screenwriting component prior to taking this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15723,2027,1708,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-246','<div class="desc"> <p style="margin-left: 0; margin-right: 0">Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p style="margin-left: 0; margin-right: 0"><strong>Obsolete Media: Analog Technology, Blackness, and Sex</strong><br/> Analog technologyâwhether it is 16 or 8 millimeter film, consumer home videos, cassette tapes, or xerography for zine-makingâ requires a certain type of touch. Steenbeck flatbed editing consoles, for example, required physically splicing, rewinding, and penciling on the film. This course invites students to both experience and theorize around the sensorial implications of audiovisual, sonic, and print analog technologies. Shifting from the recent association of the analog with hipster aesthetics, this course draws on black queer, feminist, and trans uses of the analog between the 1970s and 2000s to consider the sensorial entanglement of blackness and technology in the United States. Case studies include Kathleen Collinsâ 1982 film <em>Losing Ground </em>(originally filmed on 16mm), Matt Wolfâs 2019 documentary <em>Recorder: The Marion Stokes Project</em>, black queer zines, and Ella Fitzgeraldâs television advertisements for Memorex cassette tapes. This community-based learning course will include field trips to a local film archive and guest speakers (i.e., zinesters) during class, as well as attendance at Oxy Cinemathequeâs programming on the âBlack Analog.â Example assignments include possibly making a zine and mixtape. Additional Requirement Met: US Diversity.</p> <p style="margin-left: 0; margin-right: 0"><strong>New Waves of East Asian Cinema</strong></p> <p style="margin-left: 0; margin-right: 0">The history of cinema is marked by New Waves reflecting both artistic and cultural movements and shifts in cinematic practice. This survey course focuses on the New Waves of East Asian Cinema, engaging their sociocultural history alongside aesthetic and technological developments. Topics include: Japanâs <em>NÅ«beru bÄgu</em>in the 1950s, which borrowed its name from the inaugural movement of the French <em>Nouvelle Vague</em><em>;</em> the waves in Hong Kong cinema, which were thematically linked to the impending expiration date of the 1997 handover to China; and the developments in Taiwanese art and film that were spurred by the ending of martial law in 1982. We will examine the historical events of resistance underlying these cinematic movements and their long-lasting impacts on society and culture. Students will engage with the material critically through projects and presentations alongside weekly screenings, readings, and discussions. Additional Requirement Met: Regional Focus.</p> <p style="margin-left: 0; margin-right: 0"><br/> <strong>Modernity and the Rise of Cinematic Visuality</strong></p> <p>Many have argued that the history of modernity has been, above all, a history of visualization, changing the way we see. In this course, we will examine a diverse range of nineteenth and early twentieth century visual practices, technologies, and experiences including train rides, panoramas, shopping arcades, assembly lines, and amusement parks that helped shape the "modern observer" by altering both the perception and understanding of time and space, public and private, work and leisure, the normal and deviant, and the individual and collective. Through a combination of critical readings, screenings, and field trips, we will ask how such practices of looking not only influenced early cinematic form and content, but also how they continue to inflect postmodern media culture, from television to the internet. The course culminates in a 3D screening of HUGO (2011, Scorsese).</p> <p><strong>The Philosophy of Classical Hollywood Cinema</strong></p> <p>This course will attempt a survey of current philosophical approaches to classical Hollywood film, beginning with Stanley Cavellâs The World Viewed: Reflections on the Ontology of Cinema (1971). This work initiated a new and flourishing sub-discipline within contemporary academic philosophy called film-philosophy. The central assumption within this body of inquiry is that film is (or can be) âphilosophy in action.â In this course we will be returning to the source of this idea to read Cavellâs original work, as well as selections from his two subsequent books: Pursuits of Happiness: the Hollywood Comedy of Remarriage (1981) and Contesting Tears: The Hollywood Melodrama of the Unknown Woman (1996). We will then extend our inquiry to other writers inspired by Cavell (and reflections on later developments within Hollywood), such as Robert Pippin (writing on Film Noir), Stephen Mulhall (writing on the Alien series and other sci-fi), and William Rothman (writing on Hitchcock). Weekly screenings and discussions will be part of the course, as well as one or two field trips to Los Angeles archives.Cross-listed as PHIL 317.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15724,2027,3212,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-247','<div class="desc"> <p>Hands-on courses in animated media and visual effects production alongisde historical and critical animation studies. Students explore experimental, abstract, character-based, and hybrid live-action and animation composited approaches. Projects are supplemented by readings, screenings, and workshops. Variable topics courses may be repeated with a different sub-topic for credit. <em><strong>Note: specific topics may fulfill distinct Core requirements.</strong></em></p><p><strong>Intro to Animation</strong></p><p>A hands-on course in animated media production integrating analog and digital techniques. Students will explore experimental, abstract, and character-based approaches using hand-drawn animation, lens-based stop-motion, and digital methods alongside studying historical works and critical animation frameworks. Coursework emphasizes animation timing, audio-visual design, compositional principles, and pre-production methods for developing concepts and stories. Projects are supplemented by readings, screenings, discussion, and technical workshops. This course prepares students to create animated films and more advanced coursework in animation, games, or emerging media. No prior experience required.</p><p><strong>3D Design &amp; Animation </strong></p><p>A hands-on course in 3D animated media production. Through practical workshops, students will learn modeling, lighting, animation, rendering, and concept design alongside studying historical works and critical animation frameworks. Coursework includes technical exercises, screenings, readings, discussion, and a series of short animated projects. Prior experience with animation, 3D, media production, or instructor permission required.</p><p><strong>Representing Health, Illness, &amp; Well-being Through Storytelling</strong></p><p>Whose stories are being told, and whose are left out? How might animated storytelling voice new narratives of health, illness, and well-being? Students will examine how marginalized communities are misrepresented or absent in health conversations through readings, screenings, and discussions. Through journaling, sketching, and hands-on experimentation, students will explore animated storytelling techniquesâexperimental, abstract, and character-basedâwith emphasis on documentary animation''s ability to represent health topics with sensitivity. Students will create storyboards, animatics, voice-over, sound design, and analog and digital animation. In groups, students will produce short animated films and develop online distribution plans for outreach. No prior experience required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15725,2027,1535,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-248','<div class="desc"> <p>A survey course on the global language of film and media. Screenings and readings will cover a range of national contexts, examining questions of national identity, national cinema, alternative cinema, Third cinema, experimental ethnography, diaspora, postcoloniality, globalization, and transnationality. The course will take advantage of the international and intercultural makeup of Los Angeles, as a means of exploring media and accessing practitioners who are working across national boundaries. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics fulfill distinct Core requirements.</strong></em></p> <p><strong>African Film and Media</strong></p> <p>Africa has one of the largest film industries in the world. This course surveys significant film and media traditions within Africa along with their aesthetic, political, and cultural contexts. We will explore African film and video across a broad array of traditions, mediums, and historical periods including the griot, Yoruba theatre, colonial visual culture, independence and liberation films, counter-ethnography, the Négritude movement, Third Cinema, post-independence Francophone Art films, sub-Saharan Black African cinema, FESPACO, Anglophone Nollywood and Ghana popular video, and African new media. The goal is to focus on distinctly African film and film scholarship by critically examining the various conflicting traditions and methodologies of cross-cultural African film studies. This course will involve seminar-style discussions, presentations, extensive screenings (in and outside of class), guest lectures by African filmmakers and scholars, and critical writing. <em>Additional Core Requirement Met: Regional Focus</em>.</p> <p><strong>Diasporic Cinemas: Black x SWANA Film Formations</strong></p> <p>This course explores the aesthetic, sociopolitical, and sensorial practices associated with traditions of Black and SWANA diasporic cinemas. It surveys the visual interventions made by Black and SWANA feminist filmmakers and visual culture theorists both in and beyond the United States, offering critical insights into the praxes of collaboration, improvisation, and situated meaning-making that mark departures and routes in order to remake cinematic archives and film language itself as a tool of analysis. From the speculative Afro-Caribbean visuals of Beyoncé’s <em>Lemonade</em> (2016) to the recent Oscar-winning documentary <em>No Other Land</em> (2024), Black and SWANA filmmakers articulate and insist on alternative visions and vocabularies for enunciating ways of being and seeing in defiance of erasure. Drawing on conceptual frameworks and methods from Black Studies, critical refugee literatures, and feminist film theory, we will construct a vocabulary for reading representations of racialized and embodied difference that emerge from historical, state-sanctioned projects of racialization, anti-Blackness, and colonial violence. The films and filmmakers we will explore intervene in cinematic histories by responding to such narratives of exclusion, alienation, and dispossession through speculative visions of queerness, indigeneity, sexuality, libidinal economies, and temporalities in excess of these histories.</p> <p><strong>Foreigners and Cinematic Border Crossings</strong></p> <p>What does it mean to be-placed-into-foreignness? To be marked as foreign? To inhabit this category and feel its weight? We know that certain bodies, or regions, are labeled as foreign, but also texts and images. “Foreign” is a sticky term – it sticks to the body of a human, or to a particular image or sound – and it marks it as something else, as something other than me, alien, some form of alterity. How do transnational cinema and media approach representations of foreignness? How do they engage questions of aesthetics, politics, and ethics? We will explore these questions while focusing on films and media that privilege transcultural encounters and border crossings in various global locations. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>Speculative Othering through Worldly Frames in Television and Media</strong></p> <p>Imagined worlds, both past and present, have served as alternative prospects for audience realities. This course will use global perspectives from multicultural voices in television and media to investigate diverse cultural, social, and political contexts informing speculative fiction following Judith Merril’s definition of the term: "stories whose objective is to explore, to discover, to learn, by means of projection, extrapolation, analogue, hypothesis-and-paper-experimentation, something about the nature of the universe, of man, of ‘reality’.” Course screenings will include tv series from Brazil,<em> 3%</em> (2016-2020); Australia, <em>Cleverman</em> (2016-2017); Japan, <em>Alice in Borderland</em> (2020- ); South Africa, <em>Shadow</em> (2019); the United Kingdom, <em>Timewasters</em> (2017-2019); and the United States, <em>The Sandman</em> (2022- ). Through screenings, critical readings, observations, hypotheses, and experimentation, we will examine key terms of modern speculative fiction, including reason and technology, alien visitation, transhumanism, and utopias and dystopias, to help us draft and answer questions about identities, worlds, and existences. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>Transnational Cinemas: Borders, Walls, Difference</strong></p> <p>In film studies, the term “transnational” has opened up new ways of thinking about cinema, its production contexts, spectatorship, and ideological investments. We will explore different understandings of the concept of transnationality and focus on its relation to migration, foreignness, national identity, racial politics, globalization, and various philosophical discussions (about difference, multiculturalism and diversity). We will screen a number of fascinating films and videos from multiple regions of the world. The course is discussion-based, encouraging critical thinking, writing, and presentation skills. Expect theoretical readings and that will guide our explorations. <em>Additional Core Requirement Met: Global Connections.</em></p> <p><strong>Transpacific Social Justice</strong></p> <p>This course will explore a variety of contemporary film and multimedia productions, with a focus on social justice issues across the transpacific. Topics discussed may include, but are not limited to: race, gender, and sexuality in a networked world; war and its aftermaths; labor rights; and digital media advocacy. What are the implications of multimedia technologies for social justice and democracy, especially in marginalized communities across the Pacific and their diasporas? Students will learn about emerging art and activist movements in Asia and the Pacific through a variety of screenings, readings and lectures. There will be a particular focus on materials coming from social justice movements such as documentary film, independent film, and activist art. We will review and analyze different perspectives, for example, a rising intersectional feminist movement in South Asia, sexual politics in East Asia, participatory videos created from migrants in Southeast Asia, to the student uprisings of Taiwan’s Sunflower Occupation and Hong Kong’s Umbrella Revolution and current protests. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15726,2027,3355,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-249','<div class="desc"> <p>It is impossible to talk about the City of Angels without talking about its movie business. The history of American cinema is so intertwined with Los Angeles that the term “Hollywood” is used interchangeably with “American film” worldwide. Through screenings, readings, and discussions, we will look at the history of Los Angeles cinema and the complex relationship that American film has had with its host city. We will look at the mythical allure of the region that enticed film pioneers to leave the East Coast for the land of sunshine, as well as the dark visions of L.A. film noir that challenged this mythology. We will consider the ways that Los Angeles is depicted by native “Angelenos” and by outsiders. This course will also look at the diverse L.A. Rebellion School, the city’s penchant for destroying itself on film, and how the late 70s/early 80s Los Angeles music scene fueled a punk aesthetic in independent films. Lastly, we will explore Los Angeles neo-realist cinema – a cinema of marginalized voices that contrasts sharply with the glittering image of the city in mainstream American film and television.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15727,2027,1536,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-250','<div class="desc"> <p>This hybrid media theory and practice course directly engages the interrelationship between discursive and creative production. Classes will include screenings, lectures, discussion, and hands-on experiences in producing and collaborating on digital media projects. Topics courses may be repeated with a different topic for credit.</p><p><br/></p><p><strong>Experimental Gamemaking</strong></p><p>In this hybrid theory/practice course, students will view, play, and make video games that follow the lineage of contemporary experimental and avant-garde game makers. In addition to practicing the fundamentals of game engines, game programming, and introductory 2D/3D asset making, we will trace the history of transmedia storytelling through experimental game making, from Colossal Cave Adventure to Disco Elysium. In the process, students will learn about the pitfalls and bottlenecks of modern game production, while being introduced to alternative aesthetic, sociopolitical, and creative discourses around gaming, and the innovative strategies deployed to challenge and change the video games industry. Throughout the course, students will conduct a series of experiments ranging from short prototypes for visual novels to Machinima, and they will expand one or remix multiple prototypes into a larger game. No previous experience with games or programming necessary.</p><p><br/></p><p><strong>Media Activism through Participatory Video</strong></p><p>This is a combined theory and practice course that will engage students in looking critically at what participation means when working with members of a community. In participatory video, who holds the camera often determines who holds the power. By gaining an understanding of documentary film and ethics, we will question the relationship between filmmaker and subject. Students will learn about working with community, developing relationships and trust, and how to collaborate using participatory methods. Through readings, screenings, and guest lectures, the course will explore the potential of using digital media tools to engage communities in media activism. Students will be introduced to a variety of methodologies that will lead up to a final collaborative project that will engage a local community in participatory video. This final project will result in a series of public workshops, screenings, and exhibition.</p><p><br/></p><p><strong>Reframing the I/Eye: The Politics of Autobiographical Media</strong></p><p>In this course students will historicize, watch, debate, and make their own autobiographical media works utilizing the digital technologies and platforms that pervade our lives. The rise of identity-based social movements in the late 20th century coincided with the emergence of consumer video technologies, sparking a profusion of autobiographical media works by female-identifying, LGBTQ+, and BIPOC individuals who were not simply demanding representation in media, but that such representations be complex, intersectional, and self-produced. These autobiographical works served as hard-fought corrections, both to the essentializing, extractive, colonialist legacies of documentary production, and to the traditions of autobiographyâuntil then a largely literary tradition cultivated by white men expounding on their lives of privilege. In our own 21st century moment where digital video can increasingly be recorded, edited, and distributed via our phones, how have the politics and poetics of self-representation changed? Can autobiography still function as a political act, or has it become a digital commonplace, lost in the noise of selfie-culture and personal branding, and tinged with the looming spectre of surveillance? </p><p><br/></p><p><strong>The Archival Imagination: Found Footage Filmmaking</strong></p><p>How can we approach found media in ways that unlock latent elements in the original material? How can personal archives be re-contextualized in order to reflect on the time of its creation? How can advertisements and other disposable media be used to reveal historic progressions, disrupt nascent power structures, or speculate on the nature of truth itself? In this course, we will explore multiple techniques for working with archival material, through a combination of screenings, readings, and making. Exploring techniques that include autobiography, dÃ©tournement, reflexive critique, collage, live narration, and speculation, this class challenges students to surface their own cinematic voice using materials created by others; to draw out the unconscious properties latent in the media itself. In the largest sense, this class is about time and knowledge: how do residues from the past carry meaning, and how can we both honor and question those meanings?</p><p><br/></p><p><strong>Game Design Workshop</strong></p><p>This course will introduce students to the foundational concepts of game design through the practice of creating video games. Video games are products of culture, and this course approaches video games as media artifacts worthy of analysis, critical design, and purpose-focused production. In this course, students will learn digital tools for video game creation, such as an introductory-level game engine, basic programming skills, and audiovisual design. Students will also question and critique theories and foundational practices of game design. Readings, lectures, and in-class exercises will explore the expressive and political possibilities of games as cultural productions. No previous programming or game design experience is required.</p><p><br/></p><p><strong>Reimagining Social Media Practice</strong></p><p>This course seeks to dismantle conceptions of the internet and social media as distribution platforms and instead critically and creatively reimagines them as a production medium, one capable of producing unprecedented media content, communities, and cultural interventions. Students will engage with theories of social media and online communities by engaging with projects that explore these issues from a practical hands-on perspective. Students will become social media and online content creators to accomplish three main goals: become literate in the social media content creation process, understand current research and theories on social media and online communities, and transgressively examine the implications of a culture imbued with social media and online content. Topics to be explored in the class include influencer culture, cyberbullying, the Alt Right, strategy, public crises, identity communities, election hacking, fake news, and psychological and social implications of social media use.</p><p><br/></p><p><strong>Digital Tools for Radical Change</strong></p><p>This theory and practice course takes a critical look at the use of media communications and social media in resisting oppression and organizing for social change. Readings, class discussions, and creative assignments will engage a variety of case studies in which digital and social media were used to shape debates, advance causes, build networks, and encourage civic participation, including #BlackLivesMatter, @realdonaldtrump, and the ACLU''s Mobile Justice app. Throughout, emphasis will be placed on the art of communication as the single most important aspect of effective community organizing, activism, and advocacy. Students will put theory into practice by conceptualizing, executing, and evaluating a digital advocacy campaign via social media. Their work will be supported by skills-based workshops and class visits with Los Angeles media activists and social media influencers, which will help equip them with practical tools and insight into digital and creative practices for achieving specific goals. This course is being linked to a Cinematheque series and will include a few mandatory screenings on Thursday nights.</p><p><br/></p><p><strong>Remix Media and Culture Jamming</strong></p><p><em>What is Remix media?</em> Remixing, reusing, and reworking separate media elements from different sources to produce an entirely new work with a different meaning. <em>What is Culture Jamming? </em>Coined by Oxy alum ''82 Marc Dery, "culture jamming" is an anti-consumerist tactic used to disrupt or subvert dominant media culture, including (but not limited to) corporate advertising. This theory/practice course takes a critical look at the history of remix cultureâfrom Dada to Machinimaâalong with the gamut of aesthetic, political, and social concerns addressed by remix artists and musicians and the reception (and even appropriation) of their work by the corporate entertainment industry. Students will put theory into practice by producing their own remix projects including a <em>subvertisement </em>and remix video. We will also explore issues around copyright and fair use in the sampling of both commercial and independently-produced works.</p><p><br/></p><p><strong>Public Media and Alternative Exhibition Strategies </strong></p><p>For over 25 years Anne Bray and her Los Angeles organization FREEWAVES have created public media art events that bring diverse audiences and independent media artists together in dialogue on current issues in nontraditional, community-focused exhibition contexts. This hands-on course will engage students in theoretically and practically exploring past precedents and future possibilities for innovative and people centered media curation and exhibition. Students will work with Bray to conceptualize and realize alternative public media programming interventions on campus, in Los Angeles, and online, examining critical questions of space/venue, audience/community, and outcome/social engagement.</p><p><br/></p><p><strong>Media &amp; Social Movements in Los Angeles</strong></p><p>This theory/practice course focuses on the relationship between media and social justice struggles in the greater Los Angeles region. Readings, class discussions, and creative assignments will address the use of media tools as a form of local and global resistance against various forms of economic, racial, sexual and gender oppression. Students will learn about the theoretical and material tensions between the global political economy and local grassroots media movements, ranging from Asian American video collectives of the 1970s to the Los Angeles School of Black Filmmakers (a.k.a. L.A. Rebellion film movement) of the 1980s. In the latter half of the semester, we will examine contemporary sites of media activism online, including but not limited to #blacklivesmatter, QWOCMAP, and the Asian American Oral History project. Weekly labs will provide opportunities to explore various media forms and strategies in order to critically analyze why certain platforms have emerged within different movements and what political possibilities still resonate. While labs will focus on audiovisual production and social media, there will be room to experiment with other forms of media resistance including âzine-making, comic books, and musical performance (e.g. critical karaoke, flash mobs, etc.). We will be joined throughout the semester by media activists and local community organizers, who will share their perspectives on contemporary struggles and, at times, lead skills-based workshops. The course will culminate in a final project in which students conceptualize and begin to execute a media campaign with a Los Angeles-based community organization. <em>Additional Core Requirement Met: United States Diversity</em>.</p><p style="margin: 0 0 8pt; font-size: medium; font-family: Aptos, sans-serif; line-height: 18.4px; caret-color: rgb(0, 0, 0); color: rgba(0, 0, 0, 1); font-style: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; text-indent: 0; text-transform: none; white-space: normal; word-spacing: 0; text-decoration: none"><br/></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15728,2027,4450,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-251','<div class="desc"> <p>In this theory/practice course, we will explore what it means to âthink and write with video,â engaging the video essay as both an analytical tool and an expressive medium. We will trace the history of the video essayâfrom its literary and cinematic precursors, such as the essay film, to its contemporary forms across digital platformsâand, through close study of diverse examples, develop a nuanced understanding of its creative and rhetorical possibilities. Emphasis will be placed on analytical and conceptual work, as well as on cultivating a personal voice and aesthetic style. Readings, screenings, and class discussions will be integrated with practical assignments in which students create and refine their own video essays through an iterative process of making, reflection, and collaborative critique. Open to all students. Required for any MAC major seeking to make a video essay-based Critical Media Senior Comprehensives or Honors Project. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15729,2027,1709,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-252','<div class="desc"> <p>This course studies major movements and watershed moments in post-Civil Rights Movement black film. It begins with what is known as the "LA Rebellion," a moment of a radical reconceptualization of filmmaking, fostered by black students during their studies at the UCLA film school, and arrives in a present that is characterized by independent film and non-theatrical outlets. Emphasis will be placed on films that express innovation and experimentation. We will trace the evolution (and occasion devolution) of cinematic themes such as the representation of slavery, the depiction of black interiority, representations of gender and sexuality, and the portrayal of race itself. Films we might study include <em>Selma, Fruitvale Station, Daughters of the Dust, Lemonade, Pariah, Bush Mama, Do the Right Thing, and An Oversimplification of Her Beauty.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15730,2027,2455,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-255','<div class="desc"> <p>This course examines the history, theory, and practice of integrating time-based media into three-dimensional space. This is a theory/practice course: students will study the history of video and audio installation and attendant theories around interactivity, virtuality, and site specificity, while experimenting with different methods of troubling the passive relationship of viewer to screen in traditional cinema. Through hands-on exercises, students will develop sensitivity to three-dimensional space, explore the relationship of the human body to aural and visual environments, and create a series of linear and non-linear narratives that take into account viewers in motion. The class will culminate in the production of a media object and/or installation that demonstrates a careful consideration of form and content in relation to space.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15731,2027,1537,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-258','<div class="desc"> <p>This course introduces students to the art of film scoring and provides an in-depth exploration of the field. We will discuss functions of film music and analyze preexisting scores that demonstrate varying dramatic situations, while also investigating the aesthetic relationship between film and music. Students will be required to write music for preexisting scenes throughout the course, as well as score student short films (senior comps) from Media Production majors. </p> </div>','MUSC 148 or permission of instructor (basic experience using Logic, Ableton Live, or other Digital Audio Workstation) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15732,2027,2348,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-260','<div class="desc"> <p>This intermediate topical course addresses new and evolving issues around digital technologies and networked publics, examining their social, cultural, political, and global ramifications both on- and off-line. Coursework will engage digital media theory and scholarship. Topics courses may be repeated with a different topic for credit. <em><strong>Note: specific topics may fulfill distinct core requirements. </strong></em></p> <p><strong>Critical Game Studies: Aesthetics and Politics </strong></p> <p>Are video games addictive? Does video game violence affect people in RL (real life)? Are video games art? Can video games change the world? Even as video games have emerged as a multi-billion dollar media industry, how we discuss them remains contentious. Critics disagree over their status as a “serious” mode of artistic expression, along with their place in the “culture wars” that have shaped the political life of the United States and the world. This course provides students with the intellectual framework and critical vocabulary to examine video games as media texts via aesthetics: the value of gameplay experiences and how we fit them into our lives. How do we play, and why? The course will also address questions of politics: how can games shape, and how are they shaped by, the current of public life? Who gets to play, particularly along the lines of race, gender, sexuality, and class? Live and recorded gameplay demonstrations will provide students with the material for criticism and inquiry, alongside contemporary critical games writing, which will serve as models for student writing projects. Participants do not need previous experience with games or computers, but only a willingness to engage with games and gameplay within a critical context.</p> <p><strong>Introduction to Game Studies and Culture</strong></p> <p>Games are changing how we create, mediate, and understand our world. This course introduces students to the interdisciplinary field of game studies with a media studies and design focus. Students will read research, play games, analyze games, and think through game design. Students will also examine issues facing gaming culture. A survey of subjects will describe the foundational theories of the field, identities and game culture, and implications/effects of gameplay. Topics to be explored include disability, education and games, cheating, sexuality and games, narratives, addiction, news games, and violence.</p> <p><strong>Policing Visuality: Experiments in Mobile Cinema &amp; Surveillance Spectatorship</strong></p> <p>From “buddy cop” films to immersive “shoot to kill” virtual reality simulators deployed in law enforcement departments nationwide, policing as a digital and televisual form is one of the most enduring, captivating, and arresting genres of North American visual culture. This course takes a deep dive into the architectures of spectatorship through which policing’s visuality is <em>materialized</em>, inviting viewers to participate in the imagined carnal experience of policing <em>writ large</em>: from cinematic “ride-alongs” in films like <em>Training Day</em> (2001) to 1970s experimental films that investigate the tacit racial violence of everyday police work, we will consider how the cinema of policing has evolved through a historiographic examination of policing as mobile cinema. Focusing on the construction of police culture through what feminist film scholar Anne Friedberg described as “automotive visuality,” this course engages policing’s techniques of state violence vis-à-vis <em>mobility</em> through ethnographic films, video games and VR platforms, popular media and anthropological texts to analyze policing’s digital practices, narratives of “reality” and fiction; police propaganda and the documentary form, and the construction of the mobile frame itself as one of policing’s most underexamined tools for rendering racialized surveillance as seen in television shows like <em>COPS</em> (1989-present) and <em>Live PD </em>(2016-2020). We will extend the theory of “mobile cinema” to these cinematic and televisual examples and beyond, exploring how police VR tech and law enforcement TikTok accounts rely on the experimentation of mobile framing to develop and expand digital cultures of police image consumption.</p> <p style="margin-top: 10px;"><strong>The Art and Politics of Virtual Reality</strong></p> <p>Recent years have seen an explosion in consumer-grade virtual reality (VR) technologies — devices like the HTC Vive, PlayStation VR, Oculus Rift, and Samsung Gear VR have brought a wealth of new experiences to audiences and users, both inside and outside their homes. The new wave of VR content and hardware may feel unprecedented; in fact, the history of VR begins over a century ago. This course will examine “reality” and the “virtual”, two long-contested terms, through the lenses of history, culture, embodiment, and space. Students will walk the boundaries of “virtual reality” through readings, screenings, workshops, and VR experiences. Through this work, students will enter the discourse surrounding VR, where they will struggle with the complicated political questions that surround VR as an art form: Who gets to define what is ‘real’ and what is not? How (and for whom) is something ‘virtual’? What kinds of rules, procedures, laws, and people should govern these strange spaces and places we call “virtual reality”? And how can VR be used not simply as a vehicle for entertainment or escape, but also a space for cultural questioning, activism, and social change? This course is connected to the Oxy Cinematheque Series that will occur during select evening course sessions.</p> <p style="margin-top: 10px;"><strong>Who Owns the Internet?</strong></p> <p>This course takes a historical, critical, and experiential approach to the competing sets of interests that have struggled over control of the internet since its inception. These players - military, academic, corporate, activist, regulatory, user, etc. - will be explored through sets of readings, screenings, field trips, and hands-on workshops. Central to our inquiry will be questions of infrastructure, surveillance, and resistance, as they mark out the terrain, on which digital culture thrives, and, through which, major actors exert their influence. Students will have the opportunity to both learn about digital cultures and work in digital modes in this course, with hands on components emphasizing geo-spatial analysis, multimedia presentation, social media engagement, and webmaking.</p> <p style="margin-top: 10px;"><strong>Women Making Moves - Women’s Migration and Media</strong></p> <p>The course will apply a theoretical and practical framework to facilitate an understanding of gendered migration patterns within Asia with a focus on Japan, Hong Kong, Taiwan and the Asian diaspora. This course will be designed to encourage students to critically engage in understanding global migration flows and trends, but to also look closer at more personal narratives of migration. We will discuss forced and voluntary migration, issues of sex work and the emotional labor industry, the crossing of borders, and what it means to belong. The thematic focus will be on the feminization of migration, the monetization of the migrant worker’s body, and looking at how feminist activism is perceived within an Asian context. Students will collaborate on a visual research project that examines themes of migration and how it impacts their daily lives. <em>Additional Core Requirement Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15733,2027,2832,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-270','<div class="desc"> <p style="margin: 0; background: rgba(255, 255, 255, 1)">Theoretical and practical investigations into processes, methods, frameworks, and considerations involved with both creating and distributing emerging cinematic media. These courses examine developing concepts, methods, and works that engage with the wide-ranging creative possibilities of emerging cinematic media practices. Topics courses may be repeated with a different topic for credit.</p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0"><strong style="box-sizing: content-box">Cinematic Worldbuilding</strong></p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0">This course explores worldbuilding as a practice combining systems design, art direction, research, and storytelling to imagine plausible futures. Using methods from future studies and media artsâdigital collage, generative AI, and video productionâstudents will create speculative worlds and narratives. Projects will experiment with visual storytelling, interactivity, and transmedia, guided by the principle that reality and fiction shape each other. Readings and screenings provide context for creating worlds that invite critical conversation about the futures we want to build or prevent.</p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0"><strong style="box-sizing: content-box">Virtual Production </strong></p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0">This course explores virtual production through critical, historical, and speculative lenses. Students will design virtual sets and real-time environments in game engines, and experiment with different methods for integrating live-action and photographic capture with CG. Through hands-on projects and critical readings, students will examine cultural and technical questions raised by virtual production practices. Techniques range from introductory to intermediate. No prior experience required.</p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0"><strong style="box-sizing: content-box">Extended Realities</strong></p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0">This course explores creating XR (virtual, augmented, and mixed reality) experiences using critical, historical, and speculative lenses. Students will conceptualize, design, and prototype projects using game engines and XR tools, layering digital content onto physical space through spatial computing, photogrammetry, and interactivity. Through readings and hands-on work, students will engage with questions of embodiment, presence, and spatial storytelling. Techniques range from introductory to intermediate. No prior experience required.</p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0"><strong style="box-sizing: content-box">Immersive Media Production</strong></p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0">This course focuses on creating cinematic experiences for immersive environments including Virtual Reality, projection mapping, and real-time 3D. Students will learn production workflows for spatial storytelling using game engines, photogrammetry, 3D modeling, and generative AI tools. Through hands-on projects, students will develop skills in art direction, asset creation, animation, and interactive design for immersive platforms. Coursework emphasizes translating traditional cinematic techniques into spatial experiences, collaborative production workflows, and technical problem-solving. Techniques range from introductory to intermediate. No prior experience required.</p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0"><strong style="box-sizing: content-box">AI &amp; Creativity</strong></p><p style="margin: 0; background: rgba(255, 255, 255, 1); box-sizing: content-box; font-variant-ligatures: normal; font-variant-caps: normal; orphans: 2; widows: 2; text-decoration-style: initial; text-decoration-color: initial; word-spacing: 0">This course explores AI as a tool for creative practice and critical inquiry in cinematic arts. Students will create still and moving images using AI tools while examining questions of power, access, and authorship. Through critical making that integrates theory and practice, students will analyze contemporary digital artworks and situate AI creativity within broader histories of cinema. Coursework includes hands-on experimentation, critical discussion, and developing both a creative portfolio and critical framework for understanding their work within current social and political contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15734,2027,2902,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-271','<div class="desc"> <p>“Haptic” is a word that describes the sense of touch, derived from a Greek root meaning to grasp, perceive, or fasten, and it has been used to describe technologies and aesthetics that communicate, or mediate, this tactile sense. We often think of touch as doing things with our hands, but touch actually affects all parts of the body, and plays a role in smell (particles entering the nose), sound (as vibration or a wave), taste (of the tongue touching), and even vision (through synesthesia or haptic visuality). However, in the current age of social distancing, many of us are feeling “touch starved,” and looking to digital media as a source of intimacy and community. How can we learn in this moment from haptic technologies, haptic aesthetics, and uses of these in video games, virtual reality, digital-physical art installations, and even early moving pictures? How can we communicate felt experiences as forms of unique knowledge? Drawing from video game studies, humor and gimmicks, feminist film theory, and Black feminist thought, this course takes an interdisciplinary approach to questions of haptic media. Students will complete and give feedback on six short solo haptic pieces and one final collaborative project. The final aim of the course is an exhibition of student work accessible as a web-based virtual exhibition. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15735,2027,2456,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-295','<div class="desc"> <p>The study of film and media has involved disciplinary and interdisciplinary approaches for about half a century. This intermediate topical course of varying emphases studies the key critical terms, issues, and debates in popular media cultural study, including genre study, in relation to specific topics. Readings of film and media examples illustrate how different theories or perspectives can be applied to contemporary pop culture.</p> <p><strong>It Ainât Simply a Song and Dance: Reflections of Hollywood Musicals</strong></p> <p>Hollywood musicals can bring stage to screen and serve as a platform to explore historical, cultural, and social contexts through song and dance. The narrative and spectacle in the musical genre provide a space to examine multiple aspects of film theory that include representations of race, gender, class, and sexuality. This course will explore the film musical genre emergence in American cinema with considerations from global musicals. Our screenings will include musical films from Hollywood â <em>Show Boat</em> (1936), <em>West Side Story</em> (1961), <em>Cabaret</em> (1972), <em>School Daze</em> (1988) â to Brazil, <em>Black Orpheus</em> (1959); India, <em>Dharamputra</em> (1961); France, <em>Umbrellas of Cherbourg</em> (1964); and Senegal, <em>Karmen GeÃ¯</em> (2001). We will consult theories from Richard Dyer, Jane Feuer, Theodor Adorno and Hanna Eisler, and Rick Altman to complement our close examinations of the genre. Through weekly readings, screenings, and discussions, we will critically examine how film musicals use story, music, song, and dance to reflect complex perceptions of people(s) and societies. This course fulfills the Core Program Arts (CPFA) and Global Connections (CPGC) requirements.</p> <p><strong>Audiences and Spectators</strong></p> <p>Media is not only enjoyed by solitary viewers, but also by communities of people who come together to celebrate their love of culture. Across the 20th and 21st centuries, media fans have formed clubs, written amateur publications, altered their appearances, and made parodies of their favorite movies and TV shows as ways to express their fandom. This course will explore how audiences have taken pleasure in film, television, and contemporary digital media. Students will examine moving images in a variety of technological formats and exhibition contexts to study how communities of viewers have developed vibrant fan cultures around popular media. Students will also learn how media spectatorship has been structured by racial segregation, class-based accessibility, and other vectors of social inequity. Course screenings will include: <em>The Last Picture Show</em>; <em>Goodbye, Dragon Inn</em>; <em>The Watermelon Woman</em>; and <em>Dawson City: Frozen Time;</em> in addition to user-generated content on platforms such as YouTube, Vine, and TikTok.</p> <p><strong>Media and Your Body</strong></p> <p>Media forms require us to be spectators, audiences, and increasingly, users and participants, in ways that distinctly implicate and impact our bodies and identities. The course examines the nature of bodies, spaces, and materiality in media, specifically examining prominent theories and analyses that illuminate the nature of media as it exists off of the screen. The course will survey how we interact with media in different spaces and how our bodies form a part of the media experience. Specific topics include mobile games, humor and riffing with movies, participatory media, materialism, haptics, television spaces in the home and beyond, disability media studies, performing sexuality, and mental illness and video games. Assignments will engage students in practicing the theories they learn in class.</p> <p><strong>Genre in Contemporary Film, TV, and Digital Media</strong></p> <p>Genre films were part of Classic Hollywood, but genres started changing in interesting ways as media industries evolved after World War II, with the introduction of television, new technologies that enabled shooting on location or new opportunities with color film, the rise of drive-in movie theaters, and indie or exploitation filmmaking. We will study the shift from classic genre films and theory to hybrid genres and genre revisionism in film/media movements spearheaded by people of color, feminists, and LGBT communities, as well as studios. The focus in the class is on genre theory studied through historical and technological shifts in media production. Screenings will introduce a range of genres, from classic films like the Western and noir to more recent genres like road films, television melodramas, and war video games.</p> <p><strong>Imagining War: Genre on Screen and Battlefield</strong></p> <p>The war film has arguably been one of the most consistent and popular elements of cinema''s history. It was a component of film from its beginnings and is now a regular mainstay amongst Hollywood blockbusters. It has also undergone several political revisions and technological shifts in media production, distribution and exhibition, making it ideally suited to study the theory and history of genre. Importantly, this course will not only look at how war figures in film, but how film also profoundly effects and configures war. Entertainment and war are the United States'' primary exports. Militarism and the Hollywood studio system have had a long and deadly interdependence. By conceiving of the viewing screen as an extension of the battlefield (and vice versa), this course will look at the profound social and political implications of the classic genre system. We will do this by examining such films as <em>Apocalypse Now, The Deer Hunter, Hiroshima Mon Amour, Battle of Algiers, Black Hawk Down, Kandahar, Night and Fog, The Hurt Locker. Das Boot, Saving Private Ryan, All Quiet on the Western Front, Dr. Strangelove, Inglourious Basterds, Birth of a Nation, Rambo, MASH</em>, as well as a host of television shows, websites, and video games</p> <p><strong>The Western: From Colonialism to Gaming</strong></p> <p>This course will primarily explore the classic Hollywood genre system through a detailed look at "The Western." However, before looking at how genre operates within cinema, we take a broad historical and theoretical examination of genre within literary studies, critical theory, Wild West shows, philosophy, travel literature, ethnographic photography, and cultural studies. The aim is to critically examine a wide array of generic conventions within "The Western" film, while simultaneously situating these conventions within the broader historical and ideological context of European colonization of North America. Particular attention will be placed on the role of racial and gender performances within "The Western" genre as both a founding American myth and a component of the Hollywood film system. We will analyze both the classic Western as well as revisionist films. Additionally, we will investigate how the genre transforms as it moves into other media, including fine art, television, gaming, and other digital contexts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15736,2027,3842,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-296','<div class="desc"> <p><strong>Topic for Fall 2024: Subversive Art and Media</strong></p> <p>An 8-unit course on the ways visual artists challenge and critique dominant systems of power, and catalyze movements of social change . We will explore how photography, film, visual and media arts play powerful roles in shaping liberatory and empowering narratives in the present, as well as reimagining, reconstructing, and reclaiming histories of the past. Through readings, discussions, writing, and art practice, students will center questions of power, belonging, exclusion, visibility and invisibility among others. Students will also engage in collaborative projects and studio visits with artists, filmmakers, curators, historians, and media makers in LA/the US, South/Southeast Asia, Mexico, and Europe. Finally, students will create a final visual media social justice project. By the end of the immersive, students will have gained critical skills in discussion, research, and writing alongside creative skills in visual media making. This course is part of the Humanities for Just Communities curriculum.</p> <p>Class will meet 4-5 hours/week, depending on the class schedule as it is both an art history course and a visual art and media practice course which includes hands on, project-based work</p> </div>',NULL,'First-Year Seminar: FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(15737,2027,4300,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/200/mac-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p>Laboratory fee for projects in production: $55.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15738,2027,3661,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/copy-of-mac-393','<div class="desc"> <div><div><p>Advanced-level, faculty-supervised research project in the discipline. Permission of instructor and department chair required, and will be provided only after approval via this departmental MAC 393 Directed Research Contract.</p><p><br/></p><p>May be taken as 2 or 4 units, and must be taken for a letter grade. A maximum of 8 MAC 393 Directed Research Units may be applied to student''s academic record without a petition.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15739,2027,4301,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/copy-of-mac-397','<div class="desc"> <div><p>Specifically reserved for curricular study with a professor to a) replace a canceled course, b) provide a course not regularly offered, or c) prototype a future course. Permission of instructor and department chair required. Apply using registrarâs Independent Study Contract</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15740,2027,1710,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-320','<div class="desc"> <p>This course emphasizes the advanced design and writing of screenplays and long-form narratives for film and other audiovisual time-based media forms. Through a combination of screenings, critical readings, and creative exercises, students will develop a treatment for a long-form narrative screen work and commence writing scenes for its first act. May repeated once for credit.</p> </div>','MAC 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15741,2027,4451,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-345','<div class="desc"> <p>This course provides advanced study and hands-on experience in the ideation, direction, pre-production, and production of live-action fictional media. Distinctive emphasis will be placed on story development, directing actors, crew-based on-set practices, advanced-level technical processes in sound recording and cinematography. Required by all students intending to direct a fictional, live-action Senior Comprehensives project. </p> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15742,2027,1711,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-355','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors in the Media Production Concentration. It provides advanced study and hands-on experience in the ideation and production of digital media projects across a range of fictional, documentary, and experimental modes. Students engage in a combination of readings, screenings, technical workshops, and collaborative media production projects to prepare them for the Media Production Senior Comprehensives experience. This class is only open to junior MAC majors in the Media Production Concentration.<br/> </p> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15743,2027,4302,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-358','<div class="desc"> <p>This course focuses on the technical and aesthetic aspects of composing and recording music for picture that use various synchronization methods (MIDI sequence, click track, SMPTE timecode). Students will compose and record up to three projects, combined with live players, and score short films created by Media Arts &amp; Culture majors for their Senior Comprehensive. May be completed four times for credit.</p> </div>','MUSC 258 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15744,2027,1712,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-390','<div class="desc"> <p>This is a required spring-semester course for all MAC juniors. Fulfilling the Collegeâs Second-Stage Writing Requirement, this is a research-driven course which brings together all junior majors, regardless of the intended form of their senior comprehensives project, to read, watch, write, debate, and produce self-directed research, laying the groundwork for their senior year comprehensives projects. This class is only open to junior MAC majors. </p> </div>','One gateway class (from MAC 143 , MAC 145 , MAC 146 ) must be completed with a grade of C+ or better and one additional 4-unit MAC course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15745,2027,4452,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-392','<div class="desc"> <p>This course provides technical training in a range of post-production software platforms, best practices in sound and picture editing, and skills in post-production finishing/project delivery workflow. Open to all students with the appropriate prerequisite. Required for all students in the Media Production Focus intending to direct media production projects of any form (animated, live action, experimental, fiction, or documentary), to be completed by the end of Junior Year. </p> </div>','MAC 240 , MAC 242 , or MAC 250 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15746,2027,4303,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/300/mac-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15747,2027,1538,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-490','<div class="desc"> <p></p> <p>Advanced fall-semester course designed to provide guidance and intellectual community around the development and advancement of a Critical Media comprehensives project.</p> <p></p> </div>','MAC 390 and two courses from MAC 241 , MAC 244 , MAC 246 , MAC 248 , MAC 250 , MAC 252 , MAC 260 , MAC 295 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15748,2027,1539,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-491','<div class="desc"> <p>Advanced senior-level course designed for the collaborative development, production, and postproduction of fictional, documentary-based, and experimental live-action Media Production comprehensive projects. Required for all Media Production seniors making live-action projects requiring advanced media production equipment and support. </p> </div>','MAC 240, MAC 392, and either MAC 242 if making a documentary project or MAC 220 and MAC 345 if making a fiction project. Permission of instructor required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15749,2027,1713,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-492','<div class="desc"> <p>This course provides technical training in a range of post-production software platforms, best practices in sound and picture editing, and skills in post-production finishing/project delivery workflow. The course also provides professionalization tools, training students in development and production of media portfolio materials.</p> </div>','MAC 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15750,2027,3282,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-493','<div class="desc"> <p>Students conduct and / or complete faculty-supervised senior-level research for eventual presentation, whether a paper, formal publication, demonstration/performance, screenplay/pilot, or other project. Instructor permission required. </p><p><br/></p><p>May be taken as 2 or 4 units, and must be taken for a letter grade. Media Production Focus students who are taking MAC 493 in lieu of MAC 491 Senior Seminar must register for a 4-unit experience.</p><p><br/></p> </div>','Instructor Permission Required. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15751,2027,4304,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> <p>Laboratory fee for projects in production: $55.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15752,2027,3966,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/mac-media-arts-and-culture/400/mac-498','<div class="desc"> <div><div><p>Directed Research completion of an Honors Project in Media Arts &amp; Culture. Permission of instructor and department chair required, and will be provided only after (1) initial Honors Proposal approval, and (2) departmental approval of this MAC 498 Advanced Directed Research Contract.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15753,2027,229,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/copy-of-math-105','<div class="desc"> <p>This is a topics course for students who would like to take a mathematics course that does not require taking any prior course in college-level mathematics. Topics may be chosen from the selection below.</p> <p> <strong>Digital Security</strong></p> <p>In this course we will explore the world of digital security and the math that goes into keeping your information safe. Topics will include cryptography, hash functions, blockchain, and bitcoin.</p> <p><strong>Mathematical Thinking</strong></p> <p>Introduction to mathematical thinking. Investigation of mathematical patterns in counting, reasoning, motion and change, shape, symmetry, and position.</p> <p><strong>The Science Of Patterns</strong></p> <p>This course is a whirlwind tour of some of the greatest hits in mathematics: number, geometry, logic, algebra, symmetry, calculus, infinity, and more. This course endeavors to instill in students an appreciation for mathematics as "the science of patterns."</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15754,2027,4305,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-102','<div class="desc"> <div><div><p>This introduction to data science course is designed for all students, whether STEM students or not. It is an overview of topics popular in the quickly emerging field of data science. Topics include simple statistics, graphics and visualization, computer based tools designed for analysis and presentation of large data sets, introductory machine learning, and applications from a diverse array of fields.</p></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15755,2027,4418,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-107','<div class="desc"> <p>This course presents concepts from four points of view: geometric (graphs), numeric (tables), symbolic (formulas), and written (verbal descriptions). The emphasis is on the mathematical modeling of real-life problems using linear, polynomial, exponential, logarithmic, and trigonometric functions. Students that complete this course will be fully prepared for Math 110 or Math 114.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15756,2027,232,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-110','<div class="desc"> <p>This is a first-semester course in calculus covering single-variable differential calculus. Topics include limits, continuity, differentiation, differentiation rules, as well as applications to the natural and social sciences, including optimization. Click here for a more detailed topics list. </p> </div>','Calculus Placement Exam or Math 107: Data, Functions, and Graphs ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15757,2027,234,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-114','<div class="desc"> <p>This course is a more in-depth version of Mathematics 110. Intended for students interested in more mathematical rigor. It satisfies Calculus 1 prerequisites for subsequent courses. </p> </div>','Calculus Placement Examination or Math 107: Data, Functions, and Graphs ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15758,2027,236,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-120','<div class="desc"> <p>This is a second-semester Calculus course in integral calculus and infinite series. The topics will include integration, methods of evaluating integrals, sequences, series, and Taylor series. Applications to the natural and social sciences will be included. Click here for a more detailed topics list.</p> </div>','MATH 110 or MATH 114 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15759,2027,238,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-128','<div class="desc"> <p>A one-semester course focusing on infinite sequences and series including power series and Taylor series. More advanced topics will be chosen by the professor which may include: techniques for solving differential equations mathematical modeling, Fourier Series, the Laplace Transform, and the Fourier Transform. The course assumes mastery of the basic skills, particularly integration techniques and differentiation rules from the successful completion of Advanced Placement (AB) Calculus. This course satisfies Calculus 2 prerequisites for subsequent courses. </p> </div>','Permission of instructor or AP Calculus AB score of 4 or 5 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15760,2027,242,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-150','<div class="desc"> <p>An introductory course in statistics, emphasizing modern techniques of data analysis. Exploratory data analysis and graphical methods; random variables, statistical distributions, and linear models; classical, robust, and nonparametric methods for estimation and hypothesis testing; introduction to modern multivariate methods. Students will make significant use of a computer application specifically designed for data exploration. The course is strongly recommended for students who are going to use graphical techniques and statistics for research in their fields. Weekly lab.</p> </div>','Calculus 1 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15761,2027,243,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-160','<div class="desc"> <p>Formal and informal techniques for problem-solving developed by working on an intriguing collection of puzzles and problems which go beyond those encountered in the usual curriculum. These include problems which can be posed in elementary, mathematical, or logical terms, but which require strategy and ingenuity to solve.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15762,2027,858,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-195','<div class="desc"> <p>Topics in mathematics selected largely by student interest and faculty agreement. Instructor permission required. May be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15763,2027,4306,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/100/math-197','<div class="desc"> Independent study project. Permission of instructor and department chair required.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15764,2027,244,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-201','<div class="desc"> <p>This seminar course is a writing-intensive Community Based Learning course designed to expose students to the complicated ways in which mathematics affects the community. The CBL component of this course involves tutoring and mathematics assistance at Franklin High School in nearby Highland Park. The seminar component involves meeting weekly with processing discussions and discussion of readings. Topics will include the teaching and learning of mathematics, as well as the role of mathematics in individuals'' lives and their community. May be taken twice for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15765,2027,245,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-210','<div class="desc"> <p>This course is an introduction to proofs course centered around discrete mathematics. Topics include: The language of sets and logic, including propositional and predicate calculus, formal and informal proofs using truth tables, formal rules of inference, and mathematical induction; Congruences and modular arithmetic; Elementary counting techniques; and Abstract relations, including equivalence relations. Click here for a more detailed topics list.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15766,2027,3241,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-211','<div class="desc"> <p>This course will cover the main topics of MATH 210 Discrete Mathematics (logic, proofs, functions, sets, modular arithmetic, basic combinatorics, etc.), but through the lens of cryptography. The topics will be presented under the umbrella of learning about cryptography. We will cover topics such as affine ciphers, Enigma, RSA encryption, elliptic curve cryptography, etc.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15767,2027,246,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-212','<div class="desc"> <p>This is a third-semester Calculus course in multiple variables. The topics in this course include: calculus of functions of several variables, parametric curves and surfaces; vector fields in 2- and 3-space with applications; contour plots; applications to optimization and Lagrange multipliers; multiple and iterated integrals; line integrals; gradient, divergence, curl; and Green''s Theorem. Applications to physics, economics, chemistry and mathematics are included. Click here for a more detailed topics list. </p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15768,2027,247,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-214','<div class="desc"> <p>Introduction to basic concepts of linear algebra through the study of linear algebraic systems and matrix algebra. Topics include: an introduction to planes and lines, vector operations, subspaces, Gaussian elimination, linear independence, invertibility of matrices, orthogonality, matrix operations, eigenvalues, and eigenspaces. Click here for a more detailed topics list.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15769,2027,4307,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-274','<div class="desc"> <p>This course is an introduction to the field of Mathematical and Scientific Computing. As such, we investigate complex mathematical models and simulations, combined with related computer algorithms and tools used to generate solutions for these problems. Such problems come from a variety of areas in Mathematics, as well as from Biology, Economics, Physics, and more. Topics include very large and very precise numbers, measures of algorithmic efficiency, large systems of equations representing a variety of models, a variety of methods of solution and analysis, a brief acquaintance with a variety of programming languages and platforms, memory - speed tradeoffs, and more.</p> </div>','MATH 214 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15770,2027,1181,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-295','<div class="desc"> <p>Topics in mathematics selected largely by student interest and faculty agreement.</p> </div>','Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15771,2027,4308,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/200/math-297','<div class="desc"> Independent study project. Permission of instructor and department chair required.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15772,2027,4309,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/copy-of-math-393','<div class="desc"> <p>Students will work on a faculty-directed research project. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15773,2027,644,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-300','<div class="desc"> <p>This course is designed for mathematics majors to satisfy the college-wide Second Stage Writing Requirement and to demonstrate readiness for advancement in the major. The course emphasizes clearly written expression and oral communication in mathematics. Restricted to mathematics majors. Not open to seniors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15774,2027,248,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-310','<div class="desc"> <p>A beginning course in advanced calculus and real analysis. Properties of the real number system, sequences and series of real numbers, the Heine-Borel and Bolzano-Weierstrass Theorems, continuity and uniform continuity sequences, and series of functions.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15775,2027,645,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-312','<div class="desc"> <p>The differential and integral calculus of complex-valued functions of a complex variable, emphasizing geometry and applications. The complex number system, analytic functions and the Cauchy-Riemann equations, elementary functions and conformal mappings, contour integration, Taylor and Laurent series, function theory. Applications to physics, engineering, and real analysis.</p> </div>','MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15776,2027,949,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-320','<div class="desc"> <p>A first course in abstract algebra. Topics will be chosen from group theory (basic axioms and theorems concerning subgroups, cosets, normal subgroups, group homomorphisms), ring theory (basic axioms and theorems concerning subrings, ideals, ring homomorphisms, quotient rings), and field theory. Applications to areas such as chemistry, coding theory, and cryptography may be included. </p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15777,2027,646,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-322','<div class="desc"> <p>Introductory course in elementary number theory. Prime numbers, modular arithmetic, linear congruences, primitive roots, quadratic reciprocity, continued fractions and Pell''s equation, and applications to cryptography. Open problems in number theory will also be introduced.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15778,2027,249,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-330','<div class="desc"> <p>Standard methods of calculus are used to study probability: sample spaces, random variables, distribution theory, estimating unknown parameters of distributions. Various applications to real life problems will be discussed. Moment-generating functions and other techniques to calculate moments and characterize distributions. Probabilistic inequalities and the central limit theorem. Point estimators and unbiasedness.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15779,2027,647,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-332','<div class="desc"> <p>Theory and applications of statistical inference. Both Bayesian and classical parametric methods are considered. Point and interval estimation, hypothesis testing. Limit theorems and their use in approximation, maximum likelihood estimation, and the generalized likelihood ratio test. Introduction to linear models, nonparametric methods, and decision theory.</p> </div>','MATH 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15780,2027,1388,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-340','<div class="desc"> <p>This course will focus on theoretical qualitative and quantitative analyses of ordinary differential equations, from a modern perspective, using analytical, graphical, and numerical points of view. Topics can include: first-order linear and nonlinear differential equations, first order linear systems, second-order linear differential equations, autonomous differential equations and their bifurcations boundary value, problems solutions using infinite series, Laplace transforms, and various numerical approximation techniques.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15781,2027,648,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-342','<div class="desc"> <p>An introduction to the study of partial differential equations. This course will include the study of Fourier series; the separation of variables methods; and specifically, the wave, heat, and Laplace''s equations, as well as other elementary topics is PDEs. Numerical approximation techniques and applications to specific topics such as traffic flow, dispersive waves, or other areas may be included. Given in alternate years.</p> </div>','MATH 212 , MATH 214 , and MATH 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15782,2027,4310,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-350','<div class="desc"> <p>This course surveys results in the metatheory of first order logic including consistency, completeness, decidability, and undecidability.</p> </div>','PHIL 150 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15783,2027,950,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-354','<div class="desc"> <p>Cantor''s naïve theory of sets and equinumerosity. Paradoxes and axiomatic set theory. Finite and infinite cardinal numbers, fixed point theory, applications to computer science. Well orderings, transfinite induction and recursion, the Axiom of Choice and its consequences, ordinal numbers, and the cumulative hierarchy of sets. Discussion of the Continuum Hypothesis and its relation to models of set theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15784,2027,1182,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-360','<div class="desc"> <p>Axiomatic development of Euclidian and non-Euclidian geometries, including neutral and hyperbolic geometries, and possibly brief introductions to elliptic and projective geometries. The course will emphasize a rigorous and axiomatic approach to geometry and consequences of Euclid''s Parallel Postulate and its negations.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15785,2027,859,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-362','<div class="desc"> <p>General topology studies those properties (such as connectedness and compactness) which are preserved by continuous mappings. A disk and a solid square are topologically equivalent; so are a doughnut and a coffee cup; but a disk is different from a doughnut. This course enables you to construct your own proofs and counterexamples while getting to know the basic concepts behind modern mathematics.</p> </div>','MATH 210 , and MATH 212 or MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15786,2027,251,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-370','<div class="desc"> <p>This is a first course in studying numerical techniques in solving a variety of problems in mathematics using computer algorithms. Topics can include: methods for approximating solutions to algebraic equations, iterative methods for linear and nonlinear systems, interpolation and approximation, theory numerical integration, explicit and implicit methods for solving initial value problems, and boundary value problems. Error, estimation, stability, and performance are themes throughout. Students will be expected to be able to execute standard algorithms using a computer programming language by the end of the course.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15787,2027,951,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-372','<div class="desc"> <p>Optimal decision-making and modeling of deterministic and stochastic systems. Different systems of constraints lead to different methods. Linear integer dynamic programming and combinatorial algorithms. Practical problems from economics and game theory. Inventory strategies and stochastic models are analyzed by queuing theory.</p> </div>','MATH 210 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15788,2027,3910,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-374','<div class="desc"> <p>This is a topics course designed to provide depth in a variety of areas of computational mathematics. We will investigate complex mathematical problems, models and simulations, combined with related computer algorithms and advanced tools, used to generate solutions for these problems. Such problems come from a variety of areas in mathematics such as stochastic forecasting, large scale data problems, advanced numerical methods for ordinary and partial differential equations, matrix analysis as well as from other disciplines such as Biology, Economics, Physics, etc. Prerequisite: Math 214</p> </div>','MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15789,2027,952,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-380','<div class="desc"> <p>Investigation of the existence and classification of arrangements. Topics to include: principles of enumeration, inclusion-exclusion, the pigeon-hole principle, Ramsey theory, generating functions, special counting sequences, and introductory graph theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15790,2027,1075,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-382','<div class="desc"> <p>Graph Theory is a beautiful area of mathematics with many applications. It is used in computer science, biology, urban planning, and many other contexts. Like other areas of discrete mathematics, Graph Theory has the property that the problems are often quite approachable and understandable. Sometimes the solutions to Graph Theory problems can be complex and often require clever arguments, thus the subject is quite pleasing to study. This class will build a solid foundation in Graph Theory for the students. Possible topics are: graph isomorphisms, coverings, and colorings; independence number, clique number, connectivity, network flows, and matching theory.</p> </div>','MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15791,2027,252,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-395','<div class="desc"> <p>Special topics in advanced mathematics selected largely by student interest and faculty agreement. May be repeated for credit. </p> <p><strong>Advanced Differential Equations </strong></p> <p>The course will consist of advanced topics in differential equations not usually seen in either ordinary differential equations or partial differential equations, such as: delay differential equations and stochastic differential equations. Boundary value problems, numerical methods, and infinite series solutions. <em>Prerequisite: MATH 340 or MATH 342 or permission of instructor. </em></p> <p><strong>Galois Theory</strong></p> <p>One learns in a first course in algebra that given an equation of the form ax^2 + bx + c = 0, one can always find solutions using the quadratic formula. It is considerably harder to find comparable formulas to solve equations of this form if one allows degree 3 or degree 4 polynomials, but mathematicians found formulas for these in the 16th century. It remained a mystery if one could solve an equation of the form f(x) = 0 if f(x) is a degree 5 polynomial until the work of a young mathematician named Evariste Galois in the early 19th century. Unfortunately, Galois died in a duel at 21 years old without anyone accepting or understanding his work. Galois proved that there is no formula to solve (in radicals) an equation of the form f(x) =0 for f(x) a general polynomial of degree 5 or higher. The ultimate goal of this course will be to prove this result, but along the way it is necessary to develop the theory of rings, fields, and the connection between groups and field extensions known as Galois Theory. It is possible to take this course concurrently with Math 320.</p> <p><strong>History of Mathematics </strong></p> <p>This seminar course is a survey of selected topics from the history of mathematics. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the development and developers of mathematics in the past and present. The primary objective of the course is for students to synthesize various mathematical ideas from fundamental and advanced mathematics courses as a capstone experience for the major. Students will complete a project about an advanced mathematical topic with presentations in written and oral form at the end of the course. <em>This course satisfies the Core Program Requirement: Pre-1800 (CPPE).</em> <em>Prerequisite: Any 300-level Mathematics course (may be taken concurrently) or permission of instructor.</em></p> <p><strong>Knot Theory</strong></p> <p>How knots are described mathematically, how one can distinguish different knots, create new knots, classify knots. Topics include: Reidemeister moves, links, knot colorings, alternating knots, braids, knots and graphs, knot invariants, mirror images, unknotting, number crossing, number applications to biology and chemistry. <em>Prerequisite: MATH 210, MATH 212, or MATH 214 or permission of instructor.</em></p> <p><strong>Real Analysis II (Metric spaces and Lebesgueâs measure theory)</strong></p> <p>This course serves as a sequel to MATH 310 Real Analysis. The first part of this course will cover the main topics surrounding the topology, theory, and applications of metric spaces and their morphisms. In particular we will study certain function spaces that arise as normed vector spaces. Completeness, separability, compactness, and connectedness are some of the themes that will appear throughout the course. Fundamental results in Analysis such as the Heine-Borel Theorem, the Baire Category Theorem, the Bernstein Approximation Theorem, the Stone-Weierstrass Theorem, and the Arzela-Ascoli Theorem will be proved and applied. The second part of this class will be devoted to developing the Lebesgue measure on the real line and the Lebesgue integral along with powerful convergence theorems. Time permitting we will study some Fourier series. <em>Prerequisite: MATH 310 or permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15792,2027,1461,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-396','<div class="desc"> <p>This course which will cover various topics in applied mathematics. This course may be repeated once for credit.</p> <p><strong>Computational Mathematics (4 units)</strong></p> <p>This course investigates the enhanced problem solving techniques realized by the incorporation of the computer and well designed algorithms. We note that in the real world, mathematicians are asked to solve problems vastly more complex than those found in a homework set or final exam. The types of such problems are numerous: problems which are non-linear in nature, large systems of many equations rather than a few, problems which attempt to identify an infinite number of solutions, problems for which only approximate solutions are possible, and much more. We start by noting the basics of how the computer processes data and the fundamentals of decision making, iteration, and memory. We apply this to problems in various areas of mathematics and science. Often, we''ll make substantial headway, but run into some limitations only to find that some obscure mathematical property comes to the rescue and allows us to "upgrade" our process to obtain dramatically more or better solutions. Our overall course philosophy favors neither mathematics or computational tools, but the way in which these tools work together to produce amazing results!</p> <p><strong>Industrial Mathematics (2 units)</strong><br/> This course is a project-oriented introduction to industrial mathematics. Students will be grouped into teams and tasked with creating solutions to actual real-world problems provided by external partners from business, industry and government. Familiarity with a programming language is highly desirable but not required. The goal of this course is to provide students with an experience of what it is like to work as a mathematician in a professional setting.</p> <p><strong>Mathematical Modeling (2 units)</strong><br/> This course is a project-oriented seminar in mathematical modeling. Concepts from calculus, linear algebra, differential equations and other areas of mathematics will be used to derive, describe and solve mathematical models from the life, physical, and social sciences. Familiarity with a programming language is desirable but not required. The goal of this course is to provide students with multiple examples of how mathematics can be used to explain various phenomena, to describe real-world situations and to make (more quantitatively) informed decisions.</p> <p><strong>Applied Mathematics (2 units)</strong><br/> This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> </div>','MATH 212 and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(15793,2027,649,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/300/math-397','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15794,2027,253,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/400/math-400','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Applications of Graph Theory</strong></p> <p>We will learn a selection of interesting results in graph theory, together with their wide-ranging applications. Prior familiarity with graph theory is helpful but not required; necessary concepts and definitions from graph theory will be covered.</p> <p><strong>Applied Mathematics</strong></p> <p>This weekly seminar course is an introduction to some of the classic techniques of applied mathematics. Topics will include scaling, dimensional analysis, regular and singular perturbations, and asymptotic matching. The goals of the course are to expose students to important techniques widely used in applied mathematics; to present a different mode of classroom instruction and student involvement where students see themselves as equal participants in the learning process; to provide students with opportunities to practice and hone oral presentation skills; and to become more familiar with using modern computational tools to solve mathematical problems.</p> <p><strong>Cryptology</strong></p> <p>Cryptology is the study of sending secret messages over insecure communication channels. Cryptographic capabilities are important to politics and foreign affairs, and underlie the functioning of a great deal of the modern economy. In this course we will study the mathematical theories and techniques that make cryptography function, and also those that break it. We will learn how these mathematical tools influence the use of cryptographic systems, and practice explaining these implications to people without developed mathematical backgrounds.</p> <p><strong>History of Mathematics (Euler to Uhlenbeck)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Spring semester seminar will cover Euler to Mirzhakani and Uhlenbeck. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>History of Mathematics (Euclid to Newton)</strong></p> <p>This weekly seminar course is a survey of selected topics in the history of mathematics. The Fall semester seminar will (roughly) cover Euclid to Leibnitz and Newton. Through exposure and access to primary historical sources and other materials, students will gain deeper insights into mathematical concepts they have seen before, be introduced to new mathematical ideas, and learn about the history and development of mathematics as it used today. The objective of the course is for students to synthesize and connect various mathematical ideas as a capstone experience for the major. Students will present a project in written and oral form at the end of the course.</p> <p><strong>Introduction to Knot Theory</strong></p> <p>We learn how mathematics is used to understand knots and links, covering topics such as prime and composite knots, knot colorability and other invariants, and links in graphs.</p> <p><strong>Introductory Algebraic Number Theory</strong> </p> <p>One of the most basic facts in all of mathematics is the Fundamental Theorem of Arithmetic: given a positive integer <img alt="n" class="CToWUd" id="m_-717388230643633685l0.4701107051873412" src="https://ci4.googleusercontent.com/proxy/YC8nj2e8yBmjCq6iHNmwmKCdjEMLA1Rkg9GJ3zrI5rgl2Dm25s_TOAvkaywNnYQr_JYl-kfbaPoAk1awVJYg5EjXQffL2dYqAGm_NHlLgSa3Z5T7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09n" style="display:inline; height:7px; width:9px" title="n"/>, it has a unique (up to ordering) factorization into primes. The integers are not the only interesting set of numbers to work with though. For instance, suppose you are interested in solutions to the equation <img alt="x^2 + 1 = 0" class="CToWUd" id="m_-717388230643633685l0.27052074324938746" src="https://ci3.googleusercontent.com/proxy/xqcvy1KFxXc8K883M_1PDukXqcmZPm-5tB-iSAMkGkvFeFHMSOafhQR0uUvfixvpkuFdBXvok_lC_7waFw7tk0gW8wv3vqRPSjX-COISgNGMetOSfY0ffCmyU0Zq4BpjNPGK2YwXlx6nsA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091%09=%090" style="display:inline; height:15px; vertical-align:-1.1px; width:74px" title="x^2 + 1 = 0"/>. This naturally leads us to consider the number <img alt="i = \sqrt{-1}" class="CToWUd" id="m_-717388230643633685l0.3047216474584953" src="https://ci3.googleusercontent.com/proxy/jI9lkel1Wbpr5NOwIn5DWDtYBZ60cpzFgOtDWow484Xkd2YpuW52catXmqkkijXBDPPEeH2fk6x4MQ2-2yTaorDx5u-_pGbv5ks_d4E5C_t_scHGQDLxG6KnpH3R96QWXdRQq6ktp-8Xuw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09i%09=%09%5Csqrt%7B-1%7D" style="display:inline; height:16px; vertical-align:-2.934px; width:63px" title="i = \sqrt{-1}"/> as well. We can then define a new collection of numbers called the Gaussian integers <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.3979931267566288" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> which consist of elements of the form <img alt="a + b i" class="CToWUd" id="m_-717388230643633685l0.015155930074882695" src="https://ci3.googleusercontent.com/proxy/d6zGMURoQy94P-DoTtLy93G4MB8MbHK1GInDLAorcYJkCCWM4cFLTvHUWm7k9TPC45AYf_oh-vjDQfyz97qQtaBGFVOXHEw4i7gio3uVenCYoZ148Hq_WkbUWIOPw4ef6hw=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a%09%2B%09b%09i" style="display:inline; height:12px; vertical-align:-1.1px; width:41px" title="a + b i"/> for <img alt="a,b \in \mathbb{Z}" class="CToWUd" id="m_-717388230643633685l0.3730528622472029" src="https://ci6.googleusercontent.com/proxy/T4yrmOhXbiVysYHo65u2ng0ifI58f9fbFBHbM7FJE00vaWEiH8RIEZJB72bFauQ0qwa34Xj0I6JsGgN8seXxxvnTVCRsFaCrfX6W98sTyi-vFckX0fl8aA-HQ5IAVRdlAuYbUGWfrJKGR2lSl0LKQaM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09a,b%09%5Cin%09%5Cmathbb%7BZ%7D" style="display:inline; height:14px; vertical-align:-2.934px; width:53px" title="a,b \in \mathbb{Z}"/>. Given a prime <img alt="p \in \mathbb{Z}" class="CToWUd" id="m_-717388230643633685l0.6716878374913045" src="https://ci5.googleusercontent.com/proxy/I91pxfAy3o71ANU93zluf4FRJbNEGbX_SHuVKVPdohW_2Wwsw-Lgsztq4vsguB5AYJHfxGA4B3-lF8Z3Wf9vpwU6hcWFTZv3BO1mgkV4qOww6Cb2ajJ35ZUq_egaIzCfFdLLVUYR8f2pL09aP6pQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D" style="display:inline; height:14px; vertical-align:-2.934px; width:39px" title="p \in \mathbb{Z}"/>, we also have <img alt="p \in \mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.35769983375498393" src="https://ci3.googleusercontent.com/proxy/_X0boZvQHsr_aQSiVPqR6BIXlVDDGHiT4bYg4-VFaYiwAj2SRz9etcwOW-PHVF8NfxpBUeuJ2KgV1badjYAa0udYsnrsUF2BFfVyBBE3UMF1Rj8vNowRbWa4SiiuEuh9j8IcgeojBr0PlNAdaxl5cAy7=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p%09%5Cin%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:53px" title="p \in \mathbb{Z}[i]"/>. Is <img alt="p" class="CToWUd" id="m_-717388230643633685l0.1517664126518219" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/> still prime in <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.5476717335800629" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/>? It turns out that sometimes, but not always! For instance, in <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.4503683865279826" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> we have <img alt="2 = (1 + i)(1 - i )" class="CToWUd" id="m_-717388230643633685l0.8909417025380852" src="https://ci4.googleusercontent.com/proxy/XvwjjHBgKnD2a36lesGEq1IkFArJpjXtTykglqE2EaWNBlM9_xg03JuwnNtjGawD0g8n7QvoWgwh0pmM6lceriWU9WXg1sBmtIfdlM6JSu5uMmM_t6F4oOAy0L7mm1LgnpxILKTxKFp-G3huy6k9DSkKdcdKLQ=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%092%09=%09(1%09%2B%09i)(1%09-%09i%09)" style="display:inline; height:16px; vertical-align:-3.667px; width:123px" title="2 = (1 + i)(1 - i )"/> and <img alt="5 = (2 + i) (2 - i)" class="CToWUd" id="m_-717388230643633685l0.9367616738022781" src="https://ci4.googleusercontent.com/proxy/FyVZr4VzL5yrRbSosqkqGx04BmK6zUcoqlCLddJPUxekXPW72sf-MpLR9B9lbMIdAqpHod1zFvoBVn0d4FaWXAABuCsa8KVM2RwNcTEFBrWHh230o_Yk-l_LQEcrvyNOIfwOXU53fdiRTvUTLUTe5B3slXa1sA=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%095%09=%09(2%09%2B%09i)%09(2%09-%09i)" style="display:inline; height:16px; vertical-align:-3.667px; width:123px" title="5 = (2 + i) (2 - i)"/>, but <img alt="3" class="CToWUd" id="m_-717388230643633685l0.6355056826217114" src="https://ci6.googleusercontent.com/proxy/Er5UHWmuvViTqmbNTtg07Zo3TDld1PrKGZFpM1g1IYsbUxVg42LXa42yahDQowN9d1uGeAObmZqSYE6hywCYmc-qr5momXJ3Q9fqmsmt7t2msGmt=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%093" style="display:inline; height:11px; width:7px" title="3"/> is still prime! This fact is related to writing <img alt="p" class="CToWUd" id="m_-717388230643633685l0.7053141998565537" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/> as a sum of two squares as well as how the polynomial <img alt="x^2 + 1" class="CToWUd" id="m_-717388230643633685l0.2533482662405988" src="https://ci5.googleusercontent.com/proxy/O9U18DGHuRvAsqi0RA0hDNN3XN_cNoMh5A0X7XL4tEHMlZY45-T6w2Qf07anETTar4klaWwUOHcUdnWp5LQ2J3bAjhXiPRgi-45NwXEBc5Z2C7CwaVEmfvjIspVx6wcFjiM=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09x%5E2%09%2B%091" style="display:inline; height:15px; vertical-align:-1.1px; width:43px" title="x^2 + 1"/> factors when considered modulo <img alt="p" class="CToWUd" id="m_-717388230643633685l0.41962974130248254" src="https://ci3.googleusercontent.com/proxy/TRYThay7PQKwU5i_KnIE9lpflY6frxH6DBvqmg8j557aNwdV8zWyGDX9IUUmnzraFtuLNI67NeC7Z1OLJHlMyzYnOQ-aQ1LaEoRScPZod_5JSmj_=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09p" style="display:inline; height:10px; vertical-align:-2.934px; width:9px" title="p"/>. The study of how primes factor when considered in larger rings is referred to as algebraic number theory. In this course we will study algebraic number theory for the simplest cases of <img alt="\mathbb{Z}[i]" class="CToWUd" id="m_-717388230643633685l0.719894371208375" src="https://ci4.googleusercontent.com/proxy/FI_uOpfoA3xz7ssQtk__WOSFjOYihjX0YkAdah66AFC94shum-VOsNXVyhGwOiveR9oJBRnvFlCweBPCJz9-KjGPy0e_ccAA3cyEdu81pl6qSZEwR3Av6vDuh4keSJ_F5Esz2T-F=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[i]" style="display:inline; height:16px; vertical-align:-3.667px; width:24px" title="\mathbb{Z}[i]"/> and possibly other rings of the form <img alt="\mathbb{Z}[\sqrt{d}]" class="CToWUd" id="m_-717388230643633685l0.9347271008519611" src="https://ci3.googleusercontent.com/proxy/fykrb_Z6FYHa1OHSUz6l_6Ccl38TddheOZ5XqwFQDiTJtyJBJ2qrWG0-ZBvP45qpMtA0PEp7ENHRM7_NY_hSV-uPy-AwOGApOXctS2cmUXG322diPJNjCmvCdBrHDWjgJVN5jBXvfgSUS6PS8y57cGrr6A=s0-d-e1-ft#https://latex.codecogs.com/gif.latex?%5Cdpi%7B300%7D%5Cinline%09%5Cmathbb%7BZ%7D[%5Csqrt%7Bd%7D]" style="display:inline; height:18px; vertical-align:-3.667px; width:40px" title="\mathbb{Z}[\sqrt{d}]"/> to see the underpinnings of the overall vast theory. </p> <p><strong>Mathematical Applications of Linear Algebra</strong></p> <p>We will use the book Thirty-three Miniatures: Mathematical and Algorithmic Applications of Linear Algebra, by JiÅì Matoušek. We will concentrate mostly on the mathematical applications (as opposed to the algorithmic applications). In the first two class meetings we will learn about (generalized) vector spaces, as preparation for the remainder of the course.</p> <p><strong>Mathematical and Scientific Computing</strong></p> <p>This course is an introduction to the field of Mathematical and Scientific Computing. As such, we will investigate complex mathematical problems, models and simulations, combined with related computer algorithms and advanced tools, used to generate solutions for these problems. Such problems come from a variety of areas in mathematics, as well as from Biology, Economics, and more. Topics include very large and very precise numbers, measures of algorithmic efficiency, a variety of programming languages and platforms, memory – speed tradeoffs, and more.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15795,2027,2556,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/400/math-401','<div class="desc"> <p>An exploration of advanced topics in mathematics, chosen by the instructor. Assessment varies by seminar, but could include written assignments, oral presentations, or exams. Seniors typically take one seminar each semester. Completion of two seminars partially fulfills the comprehensive requirement for graduation with a degree in mathematics. May be repeated once for credit.</p> <p><strong>Cryptology</strong></p> <p>Cryptology is the study of sending secret messages over insecure communication channels. Cryptographic capabilities are important to politics and foreign affairs, and underlie the functioning of a great deal of the modern economy. In this course we will study the mathematical theories and techniques that make cryptography function, and also those that break it. We will learn how these mathematical tools influence the use of cryptographic systems, and practice explaining these implications to people without developed mathematical backgrounds.</p> <p><strong>Applications of Linear Algebra</strong></p> <p>We will use the book Thirty-three Miniatures: Mathematical and Algorithmic Applications of Linear Algebra, by JiÅì Matoušek. We will concentrate mostly on the mathematical applications (as opposed to the algorithmic applications). In the first two class meetings we will learn about (generalized) vector spaces, as preparation for the remainder of the course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15796,2027,4311,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/400/math-497','<div class="desc"> <p>Directed individual study of advanced topics. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15797,2027,650,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/math-mathematics/400/math-499','<div class="desc"> <p>Students who have been accepted by the Department to do honors should register for MATH 499, in lieu of MATH 400. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15798,2027,1243,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/100/musa-103','<div class="desc"> <p>An introduction to classical guitar including, basic technique and musicianship. The traditional repertoire as well as 20th century and flamenco will be explored. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15799,2027,1244,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/100/musa-104','<div class="desc"> <p>A further exploration of classical guitar, with emphasis on a thorough treatment of musicianship, technique, and expansion of the repertoire for the guitar soloist.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15800,2027,1245,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/100/musa-105','<div class="desc"> <p>The Alexander Technique helps students move naturally. They learn to prevent excess tension and replace it with a more effectively balanced movement pattern throughout the body. Does not satisfy Music Major applied music requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15801,2027,2503,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/100/musa-106','<div class="desc"> <p>Basic ukulele technique at the beginning through lower intermediate level.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15802,2027,1246,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/200/musa-201','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing/singing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15803,2027,1247,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/200/musa-202','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15804,2027,1248,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/200/musa-203','<div class="desc"> <p>Beginning to advanced instruction in improvisation, contemporary harmony, and reading lead sheets. Recommended for aspiring producers, composers, arrangers, and jazz or commercial keyboardists as a follow-up to MUSC 109. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a zero-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15805,2027,1249,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/200/musa-204','<div class="desc"> <p>Beginning to advanced instruction in improvisation, contemporary harmony, and reading lead sheets. Recommended for aspiring producers, composers, arrangers, and jazz or commercial keyboardists as a follow-up to MUSC 109. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a zero-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15806,2027,1252,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/musa-music-applied-study/200/musa-208','<div class="desc"> <p>Private, one-on-one weekly lessons. Beginning to advanced instruction in performance and musicianship, focusing on the development of technique, awareness of and proficiency in different styles of playing, and strengthening of reading skills. Private applied music lessons are one unit each (whether the duration of the lessons is one-half hour or one hour per week), but a 0-unit option is available by request. Please note that your student account will be charged a fee for this course. For the current fee scheme, please visit: https://www.oxy.edu/academics/areas-study/music/music-lessons.</p> </div>','Two semesters of applied piano study at Occidental or permission of instructor ',NULL,NULL);
