INSERT INTO course_descriptions VALUES(15990,2027,2924,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phac-physical-activities/200/phac-272','<div class="desc"> <p>This course will teach techniques of conditioning, leadership and strategy for intercollegiate competition in women''s tennis. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15991,2027,2925,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phac-physical-activities/200/phac-274','<div class="desc"> <p>This course will teach techniques of conditioning, leadership and strategy for intercollegiate competition in women''s track and field. Instructor permission required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15992,2027,4320,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phac-physical-activities/200/phac-275','<div class="desc"> <p>For individuals who are interested in recreational or competitive weightlifting and powerlifting. Participants will learn techniques of Olympic style weightlifting and power lifting. Through strength and conditioning workouts, they will enhance their strength and power. Participants are expected to have prior experience with Olympic style lifting, and/or power lifting.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15993,2027,294,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/100/phil-101','<div class="desc"> <p>This course introduces students to the central philosophical skills of critical thinking, careful reading, and analytical writing. Students will engage with a range of both historical and contemporary philosophical texts, from multiple regions and time periods, and with a range of philosophical questions that reflect the four content areas that structure our curriculum: (1) History of Philosophy, (2) Diversity in Philosophy, (3) Self &amp; Community, and (4) Mind &amp; World.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15994,2027,2679,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/100/phil-150','<div class="desc"> <p>This course introduces students to symbolic models of the structure of arguments, and to tools for representing those structures and evaluating them as patterns of good or bad arguments.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15995,2027,4321,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/100/phil-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15996,2027,2561,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/100/phil-199','<div class="desc"> <p>This course will be an introduction to case-based reasoning in practical ethics and political philosophy. Students will learn basic philosophical tools for analyzing the moral or ethical dimensions of practical problems, with an emphasis on medical or health related cases and policy. Heavy emphasis will be placed on speaking and critical thinking. May be repeated once for credit. Graded on a CR/NC basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15997,2027,3996,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-201','<div class="desc"> <div><p>A hands-on introduction to philosophy. As students bake and break bread together, they will explore a variety of philosophical topics, including the aesthetics of taste, the morality of food practices, the metaphysics of producing and consuming food, and other culinary provocations. A course in experiential learning, students will learn how to perfect the sourdough loaf while discussing the value of imperfection. </p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15998,2027,3997,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-202','<div class="desc"> <div><p>This course offers an in-depth exploration of Socrates, the enigmatic figure at the heart of Western philosophy. Often regarded as the father of moral philosophy, Socrates left no writings of his own, yet his ideas profoundly shaped the intellectual landscape of ancient Greece and beyond. This course aims to reconstruct the historical Socrates by examining a variety of sources, including the early dialogues of his student Plato, the writings of Xenophon, and the plays of Aristophanes, alongside modern scholarly interpretations. We will investigate the philosophical method attributed to Socrates, the nature of Socratic ignorance, and the legacy of Socratic irony. Additionally, the course will aim to understand how Socratesâ life and thought clashed with the democratic society that ultimately condemned him to death.</p><p><br/></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(15999,2027,864,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-210','<div class="desc"> <p>We will address some of the fundamental issues in epistemology and metaphysics while reading selections from the works of some important philosophers from the modern period (1600-1800). Among the issues addressed will be the existence of the external world, the relation between the mental and the physical, and the foundation of our knowledge of the future. Philosophers covered will include Descartes, Leibniz, Locke, Berkeley, Hume, and Kant.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16000,2027,2693,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-211','<div class="desc"> <p>This course will explore how central figures in the history of moral philosophy grapple with fundamental questions, such as: What is the best life for a human being? Should I be good? Can I be good? What are our obligations to others, both friends and strangers? Philosophers covered will include Plato, Aristotle, Kant, Mill, and Nietzsche.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16001,2027,2799,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-212','<div class="desc"> <p>Existentialist philosophy is primarily concerned with questions of authenticity, value choice, and freedom: What does it mean to live an authentic human life? Are we free to choose the kinds of people we are and the values we embrace? And what do such possibilities mean for our obligations to other people? In this class we will discuss the problems raised and solutions proposed by existentialist philosophers such as Kierkegaard, Nietzsche, Heidegger, Sartre, Camus, and Beauvoir, through critical examination of their major writings. Our aims will be to understand the intellectual motivations for existentialist thinking and the relevance of their arguments and positions for contemporary philosophy and contemporary life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16002,2027,3363,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-213','<div class="desc"> <p>Philosophers of the medieval Arabic-Islamic tradition, such as al-FÄrÄbÄ«, Ibn SÄ«nÄ, and Ibn Rushd, proposed detailed answers to numerous philosophical questions, grounding their proposals in powerful arguments. Some of these questions include: What is the nature of reality? What is the soul, and how is it related to the body? What is it to know something, and how can we achieve knowledge? What is language, and where does it come from? How should we discern good reasoning from bad? Is there a God? If so, what is God like? What is religion, and what is its role in society? By adopting a broadly Aristotelian framework, but going well beyond its confines, medieval Arabic-Islamic philosophy paved the way for later European Latin philosophy, which borrows heavily from the earlier tradition''s insights. We will study those insights in this class.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(16003,2027,3912,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-214','<div class="desc"> <div><p>Although human concerns have been similar through historyâlike âWhat is important for humans to thrive?â or âHow do we know what we know?ââanswers are sometimes very different in different historical periods. Of course, in any period there will be disagreement, so this course will focus not only on some general differences between thinking in early China versus the present day, but also on disagreements within early China itself. For example, many thinkers in early China take us to have substantial responsibilities to each other, so we will discuss whether this thinking provides a viable alternative to the contemporary U.S., where a marginalized person must often depend largely on themselves for support. We discuss Confucian views of political legitimacy and rebellion. We will also discuss disagreements between Chinese thinkers from this period, including what constitutes human nature and whether rituals (including funerals) contribute to a good life or are simply a waste of resources. We also discuss different thinkersâ understanding of the Dao (or the Way), our relation to nature, and how to engage in the highest form of action, non-action (wu wei). This course focuses primarily on the vibrant Warring States period, roughly 475-221 BC, which includes the beginnings of Confucianism and Daoism, as well as Mohism, âLegalismâ, and the School of Names or logicians.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16004,2027,1718,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-215','<div class="desc"> <p>A detailed examination of some central philosophical texts from history of Western philosophy. Topics vary by semester. Different topics may satisfy different Core requirements.</p> <p><strong>Ockham''s Manifesto: Language and Ontology in the <em>Summary of Logic</em></strong></p> <p>The <em>Summary of Logic</em> by William of Ockham (ca. 1287–1347) has been called "a manifesto masquerading as a textbook." In addition to teaching a revamped system of Aristotelian logic based on the semantic properties of signification and supposition, Ockham''s <em>Summary</em> also outlines a metaphysical program that revolutionized late medieval philosophy. This program came to be known as ''nominalism'', with ''realism'' being its adversary. Ockham''s own brand of nominalism recognizes only particulars – as opposed to universals – belonging to the Aristotelian categories of substance and quality. So among the things that exist are Kiki the cat and the grayness of her fur, but not any general felinity or gray color in virtue of which she''s a gray cat. This ontological reduction is grounded in an innovative linguistic analysis involving the semantics of connotation and the theory of mental language: ''cat'' signifies particular cats, not catness-in-general, and ''gray'' signifies particular gray things while connoting the particular graynesses that they have. In this class, we''ll investigate this doctrine along with the overall relationship between language and ontology in Ockham''s <em>Summary</em>, reading much of Book I along with supplementary material from Ockham''s other works and from other philosophers in Ockham''s context. </p> <p><strong>Medieval and Early Modern Philosophical Theology</strong></p> <p>In pursuit of wisdom, most philosophers throughout history thoughtfully engaged in a project of philosophical theology. Differing from religion, theology – the study (<em>logos</em>) of god (<em>theos</em>) – critically examines the existence, features, powers, and effects of deities. Some of the most sophisticated approaches to these issues were proposed by medieval and early modern philosophers living between about 1000 and 1800 CE. In this class, we''ll try to understand the theological views of a variety of philosophers of this period. Topics will include arguments for the existence of a god in the Latin and Arabic traditions, philosophical mysticism in medieval women philosophers, and the metaphysics and logic of the sacrament of the eucharist. <em>Additional </em><em>Core Requirements Met: Global Connections.</em></p> <p><strong>The Myth of Dualism</strong></p> <p>There are bodies and minds, and the two are fundamentally distinct. Bodies are spatial, publicly observable, and subject to mechanical laws. Minds are spectral, private, and, when things go right, observant of the rules of good reasoning and purposeful action. People are unions of the two— ghost-piloted machines whose constituents, once separated by bodily death, have very different fates: the abandoned vessel decays, while the captain somehow survives. Or so says the myth of dualism, attributed to the 17th-century French philosopher René Descartes by the 20th-century British philosopher Gilbert Ryle, who argues extensively against the "official doctrine" of Cartesian Dualism. But Descartes, ingenious as he was, didn''t think in a vacuum. He absorbed and perpetuated an intellectual tradition stretching from Classical Greece, to the Golden Age of Islam, to the European Middle Ages, and into Modernity—crude labels for internally diverse and complexly interrelated periods of philosophical history. In the first part of this course, we''ll try to locate and trace the myth throughout this roughly two-thousand-year stretch. Our approach will be chronological, and we''ll study the views of numerous philosophers, including Plato, Aristotle, Al-FÄrÄbÄ«, Ibn SÄ«nÄ, Thomas Aquinas, Teresa of Ávila, Descartes, Pierre Gassendi, Elisabeth of Bohemia, Baruch Spinoza, and Anton Wilhelm Amo. In the second part of the course, we''ll consider several approaches to rejecting the paradigm. Forsaking chronology, we''ll first attend to Ryle''s alternative to dualism—logical behaviorism—before reflecting on an assortment of challenges, raised by Ludwig Wittgenstein, W.E.B. Du Bois, Michel de Montaigne, and NÄgÄrjuna, to the very idea of an identifiable, unified, or non-illusory self. <em>Additional </em><em>Core Requirements Met: Global Connections.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16005,2027,2800,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-220','<div class="desc"> <p>This course will philosophically examine the concept of race and the way race informs identity. Topics include the reality of race, the origins and nature of the concept, and the extent to which race does and should impact our social and personal identities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16006,2027,4322,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-221','<div class="desc"> <p>What is feminism? How have classic and contemporary authors understood gender differences, the unequal treatment of women, and the role of gender in an ideal society? What contemporary issues face women today, and how have feminists deepened our understanding of these issues? This course will offer an introduction to theories of feminism, gender, and intersectionality. After laying a theoretical groundwork, the course will turn to applied issues, which may include sexual assault/violence against women, transsexual lives, pay inequity for women, work-life balance and the "second shift," pornography, reproductive rights, and impossible ideals for the feminine body.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16007,2027,2680,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-222','<div class="desc"> <p>This course will explore the relationship between knowledge and social and political power, focusing on epistemic dimensions of racial and gender oppression. The course will address several of the following questions: (1) How do stereotypes and propaganda operate, and what sort of threat do they pose to equality in the United States? (2) How do ideologies entrench privilege and injustice, and how can we counteract the effects of bias and false beliefs that persist in the face of strong opposing evidence? (3) Is there a distinctively epistemic form of injustice, and, if so, what does this form of injustice look like? (4) To what extent does epistemic injustice affect our ability to know ourselves, and how can we counteract its effects on our self-understanding? The authors that will be discussed may include Michel Foucault, Charles Mills, Kristie Dotson, Sally Haslanger, JosÃ© Medina, Tommie Shelby, Jason Stanley, Patricia Hill Collins, and Miranda Fricker.</p> <p>This course has an experiential learning component.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16008,2027,3012,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-223','<div class="desc"> <p>This course is an introduction to Mexican philosophy, and indirectly to Latin American philosophy. We will discuss Mexican contributions to universal questions (such as the nature of art, democracy, humanity, and racial, sexual, and ethnic identity), and we will raise the question of Mexican philosophy (what is it, how is it different from Western philosophy) by situating it in the context of other cultural expressions of Mexican identity, such as Mexican food, literature, and Mexican muralism. Thus, this course is also an introduction to comparative philosophy more generally, since it aims to challenge Eurocentrism by demonstrating that philosophy is grounded in or is an expression of cultural identity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16009,2027,3364,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-224','<div class="desc"> <p>This course explores some central topics in Philosophy of Religion, primarily through an examination of African American religious life from slavery and emancipation through the present. Drawing on philosophy, theology, film, and music, we will address the following sets of questions: (1) What is the religious outlook? What is faith, and is faith rational? What roles does faith occupy in social change? (2) Can we reconcile the existence and goodness of God with the existence of oppression, injustice, and other evils? (3) Can grace and other forms of love redeem us or transform our character? What roles do grace and other forms of love play in helping us resist oppression and create a more just society? Throughout the course, we will consider how religious thought and practice might help us live, and even flourish, in a broken world. The authors we will discuss may include Marilyn McCord Adams, James Baldwin, Patricia Hill Collins, James H. Cone, Henry Louis Gates, Jr., Evelyn Brooks Higginbotham, Martin Luther King, Jr. Howard Thurman, and Cornel West.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(16010,2027,296,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-230','<div class="desc"> <p>Philosophical thinkers have asked a series of related questions about how to live: What is happiness? What kinds of human activities give our lives meaning? More generally, how must a person live to have lived well? This course will examine a variety of answers to these questions. As a significant component of the course, students will practice living within one of the traditions we study, and reflect upon that experience.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16011,2027,2802,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-231','<div class="desc"> <p>This course will examine the ethical dimensions of our relationship to non-human animals and the environment, including a special emphasis on climate justice as the site of interconnected and global moral, political, and scientific concerns. Some of the questions we will address include: What is the relation between the environment and human health and well-being? Are there reasons other than human health and well-being for protecting the environment? Do nonhuman animals have rights? Do trees? Are we morally permitted to eat/experiment on/keep in zoos/hunt nonhuman animals? How do we compare environmental values against other values in making reasonable decisions?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16012,2027,2803,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-232','<div class="desc"> <p>This course will draw on philosophy, literature, and film in order to address some of the central topics in philosophy of religion. The questions that the course will address include: Does God exist? What is faith, and when, if ever, is it rational? Do we survive our bodily deaths, and if not, should we fear death? The course will also consider implications of answers to these questions for the meaning and value of our lives.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16013,2027,2695,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-233','<div class="desc"> <p>This course will introduce students to fundamental normative and ethical questions that arise in health care and the biological sciences, emphasizing those questions which raise issues of social justice within healthcare. Questions may include the following (among others): Will emerging technologies, particularly genetic technologies, promote or widen equity gaps in healthcare? Is it ableist to "treat" disabilities, such as deafness? How can doctors best communicate across race and class? Do fetuses have a right to life, and how does abortion access impact different groups across the United States? Is there a right to die? </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16014,2027,3270,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-239','<div class="desc"> <p>We all want to build a socially just community and we believe that our health, as well as that of our family, friends, and neighbors, is a vital component of such a community. At the same time, we also recognize that what justice requires is complex and contested. This interdisciplinary course will first help students conceptualize what justice looks like within the realm of health and medicine through a series of case studies from the ancient Mediterranean and the United States contexts. Through these case studies—which will include a focus on public health, the patient-provider relationship, reproductive health, and end-of-life care—we will scrutinize the conceptual framing of health justice in the past, as well as the health justice foundations of contemporary practices, policies, and institutions. At the end of the semester, we will also give students the opportunity to envision a better way forward, and to begin to enact their vision. Students will design their own social justice final project on a topic of their choice. </p> <p>This course is part of the Humanities for Just Communities Immersive semester. Students wishing to enter into careers in the health professions—whether as physicians, researchers, or policy experts—are especially encouraged to enroll. Co-requisite: FYS 2.</p> </div>',NULL,'FYS 2 ',NULL);
INSERT INTO course_descriptions VALUES(16015,2027,2804,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-241','<div class="desc"> <p>Paradoxes and their resolution have played a significant role in the development of philosophy; they still have an influence on philosophy today. While Zeno''s paradoxes of motion where first posed about 2000 years ago there is still not a consensus about what to say about them. Semantic paradoxes such as the liar paradox and the paradoxes of vagueness reveal problems with everyday concepts such as truth and implication. Supertasks reveal problems with our understanding of infinity. What to say about these problems what they show us about how to understand space, time, infinity, truth, and reasoning are some of the issues we will discuss in this class. We will examine various paradoxes, puzzles, and purported paradoxes and discuss different proposed resolutions to them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16016,2027,2805,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-242','<div class="desc"> <p>An introduction to the study of the mind and its relation to the body, the nature of human agency action, and personal identity. Questions to be investigated include: Is the mind identical to the brain, or is it something separate and immaterial? Is it possible for computers to think, to have consciousness, and to engage in actions that can be assessed as right or wrong? What makes someone the same person at two different times? Could you continue to exist after the death of your brain with a prosthetic brain, carbon or silicon based, into which your beliefs, desires, and memories have been infused?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16017,2027,2696,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-243','<div class="desc"> <p>This course will explore the relationships between the ways we describe the world and the nature of the world we describe. We will explore such questions as: Do different languages describe the world differently? Do different descriptions of the world correspond to different conceptions of it? Is the world a different place for those with different understandings of it? Could the world be other than it is, and how do we talk about these alternative possibilities? Are there limits to what we can express, and how do those limits correspond to the limits of what there is?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16018,2027,4421,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-244','<div class="desc"> <p>Emotionsâfeelings such as love, anger, grief, joy, fear, gratitude, shame, and pityâare among the most powerful aspects of human life. This course explores the role emotions play in a well-lived life. How do our emotional responses enrich our experiences and deepen our understanding of ourselves and others, and when might they lead us astray? Can emotions be rational, or are emotions and reason always in tension? And are there emotions that seem undesirable at firstâsuch as envy or guiltâbut that nonetheless serve an important or even valuable function in our moral and emotional lives? Our course will focus primarily on contemporary philosophical texts, supplemented by select historical readings and psychological studies. This course satisfies the Mind &amp; World component of the Philosophy major.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16019,2027,3283,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-246','<div class="desc"> <p>Often referred to as “Critical Thinking”, this course focuses on identifying, reconstructing, and evaluating the kind of reasoning we encounter everyday. It explores the internal relationship between evidence and explanation, as modeled by science and investigation (i.e., diagnostic reasoning), and exercises the skills involved in analytical reading and effective communication by articulating the structure of informal reasoning (i.e., where the truth of the premises does not guarantee the truth of conclusion). Examples of the kind of argument to be considered are those based on correlation, testimony, sampling, enumeration, prediction, and recommendation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16020,2027,4323,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-251','<div class="desc"> <p>This is a second course in logic. It will introduce topics in modal logic inductive logic and non-classical logic building on the foundation provided by PHIL 150. The course will have a significant CBL component involving teaching logic and critical thinking to local high school students. As part of the CBL component of the course students will design curriculum read some philosophy of education, keep a journal and write a reflection piece on their experience in the classroom.</p> </div>','PHIL 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16021,2027,3365,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-252','<div class="desc"> <p>This course is a continuation of PHIL 150: Formal Logic. It introduces polyadic predicate logic, along with identity, functions, and definite descriptions. Topics may also include some logical metatheory and an introduction to non-classical, modal, or other systems of logic.</p> </div>','N/A ','N/A ',NULL);
INSERT INTO course_descriptions VALUES(16022,2027,4041,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-260','<div class="desc"> <div><p>This course will explore foundational questions in the philosophy of art: What is art? Is there a quality, or feature, or function that all works of art share? How does art get its meaning? Does the artist or the viewer (or both, or neither) determine the meaning of an artwork? (Why) do we value the authenticity or originality of an artwork? What determines whether something is a good work of art? Can art make us better (or worse) people? Can good works of art have morally bad properties? How can we be moved by fictions (that is, how can we fear the monsters of horror films)?</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16023,2027,4408,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-293','<div class="desc"> <p>Students pursue an independent research project with the aim of making an original contribution to the field. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16024,2027,4324,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16025,2027,4325,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16026,2027,2463,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/200/phil-299','<div class="desc"> <p>This course is centered around understanding, and engaging deeply, with applied ethics cases developed for the Intercollegiate Ethics Bowl. These cases typically deal with a broad array of contemporary issues, such as immigration rights, the ethics of self-driving cars, gun control, race/gender on college campuses, etc. In the course, students will research realistic ethical cases, work in teams to develop thoughtful ethical analysis of these cases, and articulate these analyses both verbally and in writing. Throughout the semester, students will prepare for the regional Ethics Bowl competition.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16027,2027,298,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-310','<div class="desc"> <p>A detailed examination of some central philosophical texts from the 17th and 18th centuries. Topics vary by semester.</p> <p><strong>Kant''s <em>Critique of Pure Reason</em></strong></p> <p>This course will consist in a detailed study of selected parts of Immanuel Kant''s <em>Critique of Pure Reason</em> – the most important and influential 18<sup>th</sup>-century work on philosophical issues about the relationship between mind and world, and an attempt to synthesize and build upon the rationalist and empiricist approaches to those questions. We will also read selections from some of the central figures in the traditions to which Kant is responding (including Rene Descartes as an exemplar of the rationalist tradition, and David Hume as an exemplar of the empiricist tradition), in order to contextualize the motivations for Kant''s project, and to frame the issues with which the <em>Critique of Pure Reason</em> is engaged.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16028,2027,2807,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-311','<div class="desc"> <p>Ludwig Wittgenstein (1889-1951) is a central figure in the two most important philosophical traditions of the twentieth century: First the attempt early in the century to characterize language thought and the world in terms of the newly available formalism of modern logic and second the attempt to show that any such formalization will fail to do justice to the rich complexity of language as a form of life a form inseparable from the social and historical context from which it springs. We will examine two principal works the <em>Tractatus Logico-Philosophicus </em>and the <em>Philosophical Investigations</em>. There will also be some treatment of the historical and philosophical context of Wittgenstein''s work and life.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16029,2027,959,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-312','<div class="desc"> <p>Søren Kierkegaard (1813-1855), sometimes referred to as “the father of existentialism”, was a sharp critic of modern philosophy, institutionalized religion, and what he called “the present age”. For Kierkegaard, the fundamental problem of philosophy was to describe what it means and what it takes to become human—suggesting, ironically, that it is possible for a human being not to be human. The primary purpose of this course is to read Kierkegaard’s most influential texts closely, situate them in their historical and philosophical context (namely, early 19th Century Western Europe), and draw out their contemporary relevance, paying particular attention to the concepts of irony, anxiety, despair, love, and faith. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16030,2027,2808,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-313','<div class="desc"> <p>Fyodor Dostoevsky’s <em>The Brothers Karamazov</em> is a gripping story of murder and romantic rivalries, a wonderfully inventive literary work, and one of the finest philosophical novels ever written. We will read all of <em>The Brothers Karamazov</em> and discuss some of the main philosophical issues that it addresses. Furthermore, we will consider these issues in light of 19th-century Russian culture, and society. Course topics will include: (1) the conflict between faith and reason, and the role – if any – that faith occupies in a good life (2) the nature of love, and the meaning and significance of the command to “love your neighbor” (3) what it means for human beings to flourish, and what sort of community makes flourishing possible. We will also discuss more recent philosophical work and film on related topics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16031,2027,2643,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-320','<div class="desc"> <p>Contemporary health issues often raise deep ethical and theoretical concerns. In this course, we seek to connect philosophical and theoretical work on social justice with contemporary issues in health, such as abortion, trans* health, disability rights, domestic violence, international inequities, and health disparities. As a key component of this course, students will partner with a community organization for a semester-long research project, identifying an issue of practical importance to that community and offering an original, theoretical analysis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16032,2027,2809,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-321','<div class="desc"> <p>James Baldwin explored, with extraordinary sensitivity and insight, issues of race, poverty, and sexual difference in America. In this course, we will engage with Baldwin’s essays, novels, and plays, together with related philosophical work and film, in order to explore the some of the main philosophical themes in Baldwin’s work. We will focus on the roles that love, truth-telling, and self-knowledge play in living a morally good life and in creating a just society.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16033,2027,2935,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-322','<div class="desc"> <p>This course examines philosophical reflections on the Latinx experience, focusing on the contributions of US philosophers of Latin American decent. A sample of questions to be considered: What does it mean to be authenticallyLatinx? Is Latinx identity a racial, ethnic, or political identity? How do Latinx philosophers fit into the "canon"? What are some of the overarching lessons of Latina feminist philosophy? Are Latinxs, particularly immigrants, a threat to âAmericanâ values, as some argue? What is the meaning of âLatinxâ and why is the âxâ important? Is Latinx philosophy unique, distinctive, valuable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16034,2027,3221,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-323','<div class="desc"> <p>What is language, and where does it come from? What is it to know something, and how can we achieve knowledge? What is the nature of reasoning, and how should we discern good argumentation from bad? Philosophers of the medieval Arabic-Islamic tradition, such as al-FÄrÄbÄ«, Ibn SÄ«nÄ, and Ibn Rushd, proposed detailed answers to these and other related questions, grounding their proposals in powerful arguments. By adopting a broadly Aristotelian framework, but going well beyond its confines, these figures paved the way for later European Latin philosophy, which borrows heavily from their insights. We''ll study those insights and their reception in this class.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16035,2027,4042,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-324','<div class="desc"> <div><p dir="ltr">The philosophical texts of Daoism prize simplicity and naturalness, as exhibited in the metaphor of the unhewn block. This course will explore philosophical themes in Daoism, including transformation and the cycles of nature, the distinctions between humans and nature, how the Daoist ruler governs, and the limits of knowledge and language. The course will also discuss Daoist religious movements that build on these foundational texts and ideas.</p></div> </div>','At least one other philosophy course. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16036,2027,685,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-330','<div class="desc"> <p>This course is an examination of the relationship between law and morality. It is organized around three questions: (1) What is law, and what is the relationship between law, morality, and democracy?, (2) Is there a moral obligation to obey the law?, (3) Can we morally enforce the law, that is, is punishment morally justifiable?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16037,2027,3687,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-331','<div class="desc"> <p>Technology is rapidly progressing, raising new and difficult ethical problems. Should a self-driving car kill its driver to save a pedestrian? At what point does a system like ChatGPT exhibit sentience, and are we nearing that point? Is it possible to design algorithms which treat all people fairly, including facial recognition software used by police? Are we comfortable with the emergence of autonomous weapons, e.g. drones which bomb their target without a human pulling the triggers? In this course, we will explore and engage with a variety of ethical issues raised by new technologies, using this as a chance to explore substantive philosophical questions about ourselves, our society, and our relationship with our future robot overlords.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16038,2027,3284,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-332','<div class="desc"> <p>Ethical issues arise in all aspects of public health. Some questions we may explore are: what are health disparities and what makes them unjust? Should individuals be held responsible for areas of public health concern, such as smoking and obesity? When should the state mandate vaccines? How can and should public health norms impact areas of our lives, such as sexual behavior and birth control? Is public health ableist? <em>This course satisfies the Philosophy Department Experiential Learning Requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16039,2027,4326,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-341','<div class="desc"> <p>The course will cover such topics as whether space and time exist, how we know what the geometry of space and time is, whether any sense can be made of the claim that time has a direction, and the "paradoxes" of time travel. We will examine these questions in the context of both pre-relativistic and relativistic theories. The readings will range from historical figures such as Newton, Leibniz and Mach to contemporary work by both philosophers and physicists including Hawking, Feynman, Thorne and Sklar. This course does not require previous exposure to Special or General Relativity and will not require as a prerequisite technical skills that go beyond high school mathematics and physics, but students are expected to be comfortable with algebraic and geometric reasoning.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16040,2027,2697,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-342','<div class="desc"> <div><p dir="ltr" style="line-height: 1.2; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">We care about knowledge because it helps us get around in the world, and because we are social creatures who rely on other people, and we want to allow them to rely on usâand so we need to be able to discuss our reasons for doing and believing as we do. This course examines the individual and environmental conditions necessary for a person to have knowledge, addressing themes of justification and responsibility, processes of belief formation, types of beliefs (beliefs based on inference, perception, and testimony), and social conditions on the creation of both knowledge and ignorance. It will address questions like: Are there some beliefs that count as knowledge simply because they seem clearly true to us? Should we trust our perceptionâis it responsible to do so? Is it responsible to trust others by default? Can we have knowledge simply by being responsible, if our beliefs are true? How does membership in cultural groups facilitate or impair our having true beliefs, and should that lead us to challenge and complicate individualistic conceptions of knowledge? Answers to these questions will illuminate facts about our lives as social beings, including the impact of our social positions on what we know and believe. </span></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16041,2027,3817,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-343','<div class="desc"> <p>Human beings are (as far as we know) the only species that uses language, and (as far as we can tell) the only species that engages in at least certain kinds of thinking. But how are the ability to think and the ability to use language related to each other? This class will examine the relationship between language and thought from a number of different perspectives. How does language affect thought? Are there kinds of thinking that are aided or made possible only by language? Does the language you speak affect how you think, or what you can think about? What can the tools and techniques that we use to study language tell us about the structure of thinking (and vice versa)?</p> <p>This course fills the Mind and World distribution requirement for the Philosophy Major.<br/> This course fills the Philosophy Distribution Requirement for the Cognitive Science Major.</p> </div>','N/A ','N/A',NULL);
INSERT INTO course_descriptions VALUES(16042,2027,2681,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-344','<div class="desc"> <p>What is a language? And what is it to know, to speak, or to understand a language? This class will investigate the project of developing a systematic and comprehensive theory of linguistic meaning: what resources such a theory requires, what kinds of claims it makes, and what consequences it has. We will proceed by examining philosophical questions about the role translation between languages plays in a theory of meaning, about the nature of linguistic reference to the world, and about whether the notions of language and meaning are ultimately coherent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16043,2027,961,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-345','<div class="desc"> <p>How is it possible to study the mind scientifically? This class will explore philosophical issues about the application of scientific methods to cognitive phenomena, including questions such as the appropriate architecture of cognition, the possibility of artificial intelligence, the relation between commonsense psychology and theories in cognitive science, and the possibility of a scientific understanding of consciousness.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16044,2027,4327,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-346','<div class="desc"> <p>The course will focus on contemporary readings that raise some of the most fundamental questions about the nature of our conceptions of reality. The following questions are among those that will be addressed: Can we make sense of the idea that we are free agents? Can we understand the concept of causation? Is there a compelling argument for the existence of God? Is there any sense to be made of the claim that some claims are true by necessity while others are only contingently true? Are there true mathematical claims?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16045,2027,2936,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-347','<div class="desc"> <p>Imagination plays important and varied roles in human life, from understanding what someone else is thinking, to creating works of art, to deciding among different potential courses of action. This course will explore philosophical questions about the nature of imagination, including its relationship to belief, desire, perception, and memory, as well as those about its proper use and value, especially in aesthetics and moral/political life. Readings will be drawn from the work of both historical and contemporary philosophers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16046,2027,686,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-350','<div class="desc"> <p>This course surveys results in the metatheory of first order logic including consistency, completeness, decidability, and undecidability.</p> </div>','PHIL 150 or MATH 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16047,2027,301,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-360','<div class="desc"> <p>What makes something, someone, or some place beautiful? Why do we value beauty? These questions will be explored across multiple domains, including: art, the natural world, the built environment, and human practices, including norms for human bodies. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16048,2027,2682,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-361','<div class="desc"> <p>Philosophical curiosity begins in childhood: Where do words come from? Can trees think? What is love? At the heart of this course, Occidental students will have the opportunity to teach philosophy to elementary students at a local school. Doing so provides both an opportunity to serve the local community, an opportunity to reconnect with our own philosophical impulses, and a chance to reflect deeply on a variety of philosophical topics (such as friendship, courage, minds, justice). Occidental students will develop and teach their own lesson plans. Students in the class will also gain familiarity with philosophical views on young children and the nature of education, e.g. What status should children have in our society? Should children always be subservient to adults? How might our educational practices develop or stifle our creative natures? This course satisfies the Experiential Learning requirement for the philosophy major. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16049,2027,2698,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/300/phil-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements and different Philosophy major requirements.</p> <p><strong>Disagreement, Arrogance, and Ending Oppression</strong></p> <p>This course investigates personal attitudes towards disagreement; it examines how these attitudes can fuel race-, gender-, disability-, or sexuality-based prejudice and associated forms of oppression; and it thus considers means of eradicating these social ills. A portion of the course focuses on epistemic vices like arrogance, which tend to make it difficult for people to credit the value of opposing views. Then we turn to examine whether a person can, through the recognition of disagreement alone, come to identify their vices and ameliorate them, and if not, what other approaches might be effective. We will also meet with scholars currently working on related issues in order to learn about and discuss their work.</p> <p><em>This topic will count toward the Mind and World requirement for the Philosophy major. <em>This topic will satisfy the Core Program U.S. Diversity requirement.</em><br/> </em></p> <p><strong>Metaphor and Figurative Language</strong></p> <p>Metaphorical and other figurative uses of language are a pervasive part of our linguistic life. However, most systematic philosophical study of language has focused primarily on the literal meanings of linguistic expressions, with metaphor occupying a peripheral place. But what is the difference between literal and figurative uses of language? How do we produce, interpret, and understand metaphors? And is metaphor a primarily linguistic phenomenon, or does it extend into other areas of cognition as well? In this seminar we will discuss historical and current approaches to metaphor in philosophy and related disciplines, and we will meet with scholars currently working on these issues to learn about and discuss their work.<br/> <br/> <em>This topic will count toward the Mind and World requirement for the Philosophy major.</em></p> <p><strong>When Race is “Other”: In-Between and Outside of U.S. Race Categories</strong></p> <p>About 1 in 10 Americans identifies as more than one race. This group includes those who have parents of two or more races (e.g., one parent who is Black and one who is White, one parent who is Asian and one who is Pacific Islander, etc.), as well as some Latinx Americans. In this course, we will ask: what can be learned by centering the experiences of those who live “in between” race? Can one have racial privilege in some respects, but not others? Can one identify with a race, even if one ‘passes’ as something else? Why do so many American discussions of race proceed as if this group does not exist? Our course will draw on texts in philosophy, sociology, and literature, as well as the knowledge of guest speakers from Los Angeles and beyond.</p> <p><em>This topic will count towards the </em>Self &amp; Community<em>requirement for the Philosophy major. This topic will satisfy the Core Program U.S. Diversity requirement.</em></p> <p><strong>Philosophy of Food </strong></p> <p>The aim of this course is to demonstrate that food is worthy of philosophy inquiry. We will start with the deceptively simple question, what is food and why is it important? We will quickly move on to specific questions concerning the aesthetic value of food (can food be a work of art?), the nature of food criticism (who am I to tell you what you should like to eat?), a cluster of ethical questions concerning the production and consumption of food (e.g., what exactly is wrong with GMO?, what’s the connection between patriarchy and eating meat?, isn’t ethics fundamentally a question about hospitality?), and broad questions about food and cultural identity (what exactly does “authentic Mexican” mean?). Like any good philosophy course, the point is not to flatter your taste, but to change it, which we will do by cooking together and talking to a number of local food writers and philosophers.</p> <p><em>This topic will count towards the</em> Experiential Learning <em>requirement for the Philosophy major.</em></p> </div>','One course in philosophy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16050,2027,302,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/400/phil-490','<div class="desc"> <p>Open only to students with senior standing in philosophy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16051,2027,4328,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phil-philosophy/400/phil-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16052,2027,4329,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-101','<div class="desc"> <p>Exploration of physical laws and processes through simple and geeky-cool devices and demonstrations many of which students will build themselves and keep. The toys will illuminate topics from across physics including classical mechanics thermodynamics electricity and magnetism. Course Fee: $125.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 125, or PHYS 230; or equivalent.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16053,2027,4003,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-102','<div class="desc"> <p>A survey of the solar system, stars and stellar evolution, galaxies and cosmology. Students are expected to have a strong understanding of algebra and trigonometry. <span style="background-color: #ffffff; color: #222222;">Physics majors cannot take this course for credit toward the Physics major.</span></p> <p><span style="background-color: #ffffff; color: #222222;">Students are expected to have a strong understanding of high school Algebra.</span><s></s></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16054,2027,4004,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-104','<div class="desc"> <div> <p>A concept-based course on the fascinating subject of light designed for non-science majors. Topics include optics, waves, polarization and the modern view of light. In addition, applications</p> <p>will cover optical instruments, photography, color and the human eye. Identical in all respects to PHYS 105 except that there is no lab component. </p> </div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16055,2027,4005,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-105','<div class="desc"> <div><p>A concept-based course on the fascinating subject of light designed for non-science majors. Topics include optics, waves, polarization and the modern view of light. In addition, applications </p><p>will cover optical instruments, photography, color and the human eye. Includes a three-hour laboratory per week.</p></div> </div>',NULL,'PHYS 105L ',NULL);
INSERT INTO course_descriptions VALUES(16056,2027,316,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-106','<div class="desc"> <p>Our view of the physical world changed radically with the advent and development of relativity and quantum mechanics. This course is an introduction to the scientific and epistemological revolutions of 20th century physics, together with some of the discoveries and technologies which resulted. Specific topics may include: the physical structure of space and time; time dilation and length contraction; the global positioning system; fundamentals of quantum mechanics; quantum entanglement and teleportation; nuclear physics; quarks and leptons; big bang cosmology and the early universe. Students are expected to have a strong understanding of algebra and trigonometry. Not open to students who have completed PHYS 110, PHYS 115, PHYS 125, or PHYS 230; or equivalent.</p> </div>','This is not a calculus-based course. The needed math background extends merely to algebra and trig. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16057,2027,4422,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-107','<div class="desc"> <p>An introduction to the physics of waves, including travelling waves, standing waves, superposition, the Doppler Effect, polarization, reflection, refraction, thin films, interference and diffraction. Applications include those from optics, acoustics, astronomy and modern physics. Includes one three-hour lab per week.</p> </div>','Calculus 1 (may be taken concurrently) ','PHYS 107L ',NULL);
INSERT INTO course_descriptions VALUES(16058,2027,4330,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-108','<div class="desc"> <p>This course introduces the physics of energy and energy conversions. The goal of this course is to provide students with the tools to recognize and quantify the various energy conversion processes important to society. Fundamental concepts of conservation of energy efficiency work and heat will be introduced during the first half of the course. These concepts will provide a framework for topical information on global energy resources (renewable and nonrenewable) energy generation systems and societal energy demands.</p> <p>Students are expected to have a strong understanding of algebra and trigonometry.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16059,2027,694,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-110','<div class="desc"> <p>Covers classical mechanics, including kinematics and dynamics of particles and rigid bodies, conservation laws, and examination of specific force laws. <em>Includes one three-hour laboratory per week.</em></p><p><br/></p><h3><br/></h3> </div>','Calculus 2 (may be taken concurrently) ','PHYS 110L ',NULL);
INSERT INTO course_descriptions VALUES(16060,2027,318,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-115','<div class="desc"> <p>The first of a two-course introduction to physics designed for life science and premedical students. Topics include Newton''s laws of motion gravitation work and energy conservation laws. Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</p> </div>','Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16061,2027,1617,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-117','<div class="desc"> <p>An introduction to the physics of waves with examples from optics acoustics and modern physics. Also an introduction to thermodynamics including the first and second law of thermodynamics kinetic theory heat transport and phase transitions. Includes one three-hour lab per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16062,2027,696,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/100/phys-125','<div class="desc"> <p>The second of a two-course introduction to physics designed for life science and premedical students. Topics include electrostatics and electromagnetism electric circuits geometrical and physical optics. <em>Includes one three-hour laboratory per week. Courses with multiple lecture sections may require evening examinations.</em></p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16063,2027,4331,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-200','<div class="desc"> <p>An introduction to fundamental concepts in astrophysics. Topics include the fusion of elements in stars, stellar remnants (white dwarfs, pulsars and black holes), supernova, the Milky Way, other galaxies, and dark matter. This course will revisit the principles of physics needed to interpret astronomical observations. </p> </div>','PHYS 110 and PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16064,2027,4332,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-201','<div class="desc"> <p>An introduction to the numerical solutions of problems in physics. Applications are drawn from classical dynamics electrostatics magnetostatics relativistic dynamics and chaotic systems.</p> </div>','PHYS 110 or PHYS 115 , PHYS 125 or PHYS 230 , and COMP 131 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16065,2027,4333,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-202','<div class="desc"> <p>Theoretical and experimental electronics fundamental to modern research. Includes one three-hour laboratory per week.</p> </div>','PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16066,2027,4334,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-203','<div class="desc"> <p>A laboratory based course covering the C programming language the LabWindows CVI programming environment and the use of D/A and A/D converters.</p> </div>','PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16067,2027,4043,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-204','<div class="desc"> <div><p>Topics include: Fundamentals of discrete-state quantum mechanics; Bits vs qubits; the no-cloning theorem; entanglement and EPR states; teleportation; quantum encryption; Bellâs inequality and non-local correlations; interpretations of quantum mechanics; quantum logic gates; and quantum algorithms.</p></div> </div>','MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16068,2027,4335,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-205','<div class="desc"> <p>An introduction to the fundamental constituents of matter and their interactions. Topics include quarks and leptons; symmetries and conservations laws; special relativity; the fundamental forces and their relationship; and the early universe.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16069,2027,4336,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-206','<div class="desc"> <p>An introduction to the theory of relativity. The first half of the course focusing on special relativity includes discussions of the relationship between space and time; mass and energy; and cause and effect. The second half of the course presents the fundamentals of the general theory of relativity with an emphasis on the physics of black holes.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16070,2027,4337,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-207','<div class="desc"> <p>An introduction to the field of engineering. Students who have completed either of the introductory sequences in physics are well prepared to apply that knowledge to a wide variety of subjects. Applications covered include static equilibrium elastic properties of materials vibrations thermodynamics thermal properties of matter fluids waves and sound DC circuits and AC circuits.</p> </div>','PHYS 110 or PHYS 115 ; and PHYS 125 or PHYS 230 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16071,2027,4338,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-208','<div class="desc"> <p>An introduction to the physics of materials used in a wide range of engineering applications. As time permits topics will include the mechanical, elastic, thermal, electrical, magnetic, and environmental properties of metals, polymers, ceramics, glasses, composites, and "green" materials.</p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16072,2027,4339,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-209','<div class="desc"> <p>Special topics in physics selected largely by student interest and requiring no more than introductory physics courses. Possible topics include: variational methods celestial mechanics chaos nonlinear systems. May be repeated for credit. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16073,2027,2835,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-230','<div class="desc"> <p>Introduction to electricity and magnetism electronic circuits electromagnetic induction and Maxwell''s Equations. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 ; and Calculus 2 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16074,2027,699,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-240','<div class="desc"> <p>Introduction to the physics revolution of the twentieth century, emphasizing special relativity and elementary quantum mechanics. Includes the breakdown of classical concepts; light quanta and matter waves; Schrödinger equation and solutions in 1 and 3 dimensions; hydrogen atom, exclusion principle and the periodic table. Other topics include a selection from atomic nuclear particle and condensed-matter physics. Includes one three-hour laboratory per week.</p> </div>','PHYS 110 or PHYS 115 , PHYS 117 , and PHYS 230 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16075,2027,701,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-250','<div class="desc"> <p>An introduction to thermodynamics, including temperature, heat, work and entropy. The fundamental tools of statistical mechanics will also be introduced, including the Boltzmann factor, the chemical potential, the Gibbs factor and distribution functions. These tools will be applied to the ideal gas, Fermi and Bose gases, and phase transformations.</p> </div>','PHYS 107, PHYS 110 or PHYS 115 , and PHYS 230 or PHYS 125 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16076,2027,4340,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16077,2027,4341,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/200/phys-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16078,2027,4342,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-302','<div class="desc"> <p>At the turn of the century a series of discoveries transformed the ancient study of cosmology into a rigorous and well-tested theory of the universe. After a brief introduction to general relativity the equations governing the evolution of the universe will be developed and explored. Evidence in support of this standard model of cosmology and consequences will then be presented including supernovae standard candles the cosmic microwave background big bang nucleosynthesis dark matter and early-universe physics. The course will conclude with a presentation of recent topical subjects in this exciting field of study.</p> </div>','PHYS 117 and PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16079,2027,4343,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-303','<div class="desc"> <p>An introduction to the physics of solids. Topics include free electrons crystal structure lattice vibrations energy bands and the electrical magnetic and optical properties of solids.</p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16080,2027,4344,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-304','<div class="desc"> <p>An introduction to the physics of plasma including charged particle motion in electromagnetic fields plasma waves plasma confinement and non-linear effects. These ideas will be used to understand space and ionospheric phenomena laser-plasma interactions containment of matter and anti-matter and energy generation by controlled nuclear fusion.</p> </div>','PHYS 230 , PHYS 310 , and MATH 212 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16081,2027,4345,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-306','<div class="desc"> <p>Review of special relativity. Introduction to the fundamentals of general relativity and gravitation with applications to cosmology. Topics include the big bang theory primordial nucleo-synthesis the dark matter problem gravitational red shift and the expansion of the universe stellar evolution and black holes.</p> </div>','PHYS 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16082,2027,4346,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-308','<div class="desc"> <p>A critical analysis of the literature of nanoscience and nanotechnology. This course will examine the chemical and physical properties of quantum dots carbon nanotubes metal and semiconductor nanowires and biomolecules and other nanometer scale structures useful in molecular electronics chemical biology and in building macroscopic structures with tailored properties from nanoscale components. Includes introductory instruction to scanning tunneling microscopy.</p> </div>','PHYS 240 or CHEM 220 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16083,2027,4347,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-309','<div class="desc"> <p>Special topics in physics selected largely by student interest. Prerequisites vary with subject area. Possible topics include: group theory in physics applications of quantum mechanics in atomic nuclear and particle physics introduction to relativistic quantum mechanics nonlinear pattern forming systems hydrodynamic instabilities superfluidity and superconductivity methods of material science. <em>Satisfies a Physics Selective requirement.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16084,2027,324,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-310','<div class="desc"> <p>Survey of the elements of advanced mathematical ideas and techniques typically used in physics. Physical examples and intuition will be emphasized throughout. Topics covered will include Div Grad and Curl; matrices tensors and groups; complex analysis Fourier series and integrals; boundary and initial value problems; and special topics as time permits. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 117 and PHYS 230 ; and MATH 214 (may be taken concurrently with permission of instructor) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16085,2027,325,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-315','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques, including literature search, analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16086,2027,702,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-316','<div class="desc"> <p>Selected experiments in modern physics. Special emphasis on research techniques including literature search analysis of data, and preparation of written reports. <em>Not open to first year students.</em></p> </div>','PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16087,2027,326,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-320','<div class="desc"> <p>Motion of particles systems of particles and rigid bodies. conservation laws; coordinate transformations both stationary and moving; Hamilton''s and Lagrange''s equations. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 117 , PHYS 230 , and MATH 214 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16088,2027,703,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-330','<div class="desc"> <p>Electro- and magneto-statics Maxwell''s equations electrodynamics boundary value problems radiation. <em>Includes one ninety-minute laboratory per week.</em></p> </div>','PHYS 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16089,2027,705,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-340','<div class="desc"> <p>The foundations of the theory of quantum mechanics with applications to physical systems. Formal development of the postulates of quantum mechanics representation of states angular momentum spin and perturbation theory. Applications include the harmonic oscillator hydrogen atom and Zeeman effect. Includes one ninety-minute laboratory per week.</p> </div>','PHYS 240 or CHEM 305 , and PHYS 310 or PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16090,2027,2354,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-350','<div class="desc"> <p>Connects the microscopic properties of the physical world with its macroscopic properties using classical and quantum statistics. Topics include partition functions classical and quantum ideal gasses classical thermodynamics phase transitions and kinetic theory. Includes one ninety minute laboratory per week.</p> </div>','PHYS 240 and PHYS 310 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16091,2027,2937,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-370','<div class="desc"> <p>This course will provide students with a comprehensive and practical view of energy by investigating physical concepts related the way we use energy, energy sources, and connections between energy and broader systems like climate. Topics will include an overview of energy from a physics perspective with a focus on renewable energy including nuclear, solar, and wind power, fossil fuels, energy storage, and energy conservation.</p> </div>','PHYS 110 , PHYS 117 , PHYS 230 , PHYS 240 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16092,2027,328,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-395','<div class="desc"> <p>Research supervised by a member of the faculty. May be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16093,2027,4348,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-396','<div class="desc"> <p>Off-campus participation (up to full time) in the work of a major laboratory engaged in research and development that involves pure or applied physics. The student will take part in the ongoing technical work of the laboratory under joint supervision by a member of the laboratory''s professional technical staff and Occidental physics faculty. Normally formal application to the laboratory is required and admission may be competitive. Approval of department supervising instructor and the laboratory.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16094,2027,709,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/300/phys-397','<div class="desc"> <p>Supervised investigation by properly qualified students. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16095,2027,1301,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/400/phys-490','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16096,2027,1484,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/400/phys-491','<div class="desc"> <p>Students will participate in weekly seminars and conduct library-based research on topics in physics. Students will present one seminar and one written report on their work. <em>Completion of this course with a grade of C or better partially fulfills the comprehensive requirement for graduation with a degree in physics.</em></p> </div>','PHYS 240 and PHYS 320 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16097,2027,4349,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/400/phys-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16098,2027,710,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/phys-physics/400/phys-499','<div class="desc"> <p>Supervised investigation by students admitted by the department to the Honors Program. Permission of supervising instructor and approval of department required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16099,2027,330,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/100/pols-101','<div class="desc"> <p>This course introduces students to the study of politics the discipline of political science and the development of public policy. Politics involves the study of power influence and ideas in public and private life at the personal local state national and international levels. Accordingly our exploration will examine how power operates in a variety of settings and will include readings in political theory American politics and law comparative politics research methods and international relations. Open to frosh and sophomores.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16100,2027,1670,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/100/pols-120','<div class="desc"> <p>Introduction to the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16101,2027,4350,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/100/pols-130','<div class="desc"> <p>This course is an introduction to the theories and practices of international relations with a focus on the United States and its relations with other state actors. This course will visit all of the important IR theories that help us understand and predict state behavior. These theories will be applied to real-world IR events in order to test their utility.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16102,2027,1423,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/100/pols-140','<div class="desc"> <p>Law shapes the day to day experiences and functioning of individuals, communities, and institutions in multiple ways. This introductory course examines the diverse connections and relationships of law and society. The course will draw on theoretical and empirical perspectives from a diverse range of disciplines (such as legal studies, sociology, anthropology, and political science) to explore law and law’s role within the United States and internationally. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16103,2027,1553,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/100/pols-150','<div class="desc"> <p>âThis is what democracy looks like!â But what exactly<em> should</em> democracy look like? This course introduces students to political theory through historical and contemporary debates over democratic visions and challenges. By engaging with political thinkers across space and time, students will not only learn to study politics with interpretive, normative, and critical approaches, but in that process also rethink and expand on their repertoire of democratic practices.</p><p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16104,2027,712,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/100/pols-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16105,2027,2744,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-200','<div class="desc"> <p>“America will never be a socialist country, “ President Donald Trump declared in his 2019 State of the Union Address. “The American left is on the cusp of a great victory,” wrote David Brooks, the <em>New York Times</em><em>’</em> conservative columnist, in 2018.</p> <p>More than at any time since World War I, Americans are talking about socialism. Conservatives fear it. Liberals question it. Progressives and radicals embrace it. Why is that word, and the egalitarian vision it defines, enjoying a resurgence in the United States? And does it mean, as Trump warned and Brooks predicted, that socialism is on the American horizon? According to a 2018 Gallup poll, 37 percent of all Americans, and almost half of Americans under 40, have a more favorable view of socialism than of capitalism. A growing number of socialists have been elected to office at the local, state and federal levels. Democratic socialists have played key roles in the upsurge of 21st Century activism, including Occupy Wall Street, Black Lives Matter, the Fight for 15, #metoo, the Green New Deal, and others. Ideas considered radical only a decade ago – universal health care, tuition-free college, a $15 federal minimum wage, same-sex marriage, requiring big corporations to put workers and union members on their boards, green jobs, and many others – are now widely accepted. Is it possible that, within a generation, America might get closer to, or even become, a socialist democracy?</p> <p>The course will focus on the history of socialism in America as both an idea and a movement. It will examine the efforts of socialists to change public opinion and public policy, from both the outside (as a protest movement) and the inside (as elected officials). It will explore the coalitions and tensions (past and present) between America’s socialist movement and the labor, civil rights, feminist, environmental, and other movements. The course will look at the role of activists, intellectuals, artists, and politicians in shaping socialist ideas and movements. We will examine how and why socialism in the U.S. has had periods of success and periods of failure, and look at its influence in shaping American culture and politics. We’ll also discuss the conditions of life, policies, and tensions facing current democratic socialist and social democratic countries (particularly in Europe). The course will also explore the differences and similarities between democratic socialism and liberalism, progressivism, social democracy, and Communism. </p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16106,2027,2480,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-201','<div class="desc"> <p>This course provides an overview of main themes in the development of California state government and the political institutions, social and demographic trends, and public policies that give shape to its politics. We will focus on political theories that help us understand: 1) the major problems facing California and its communities, 2) the economic, social and political forces that have shaped California’s development, 3) the structure and role of government in addressing the state’s problems, and 4) the major participants and stakes in California politics.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 American Politics and Public Policy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16107,2027,1302,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-202','<div class="desc"> <p>This course examines how gender influences who participates in the American political process, from voting to campaigning and holding elected office. The course also examines how public policies are gendered in their design, implementation, and outcomes. The course adopts an intersectional approach, asking how gender interacts with other identities, including race, class, ethnicity, sexual, and disability, to fully understand how ideas about masculinity and femininity shapes access to political power in American society.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16108,2027,1303,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-204','<div class="desc"> <p>Students in this course will analyze historical and contemporary election campaigns in the United States, exploring such issues as the role of money, media, public opinion, voter registration laws, voter suppression, campaign strategy, staffing, and other topics. They will also examine the role of identity, alternative electoral systems and campaign reform options. The course will offer a particular focus on the most current election season, including campaigns for president, Congress, governor positions, and others. <em>Not open to first year frosh.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,'POLS 203 ',NULL);
INSERT INTO course_descriptions VALUES(16109,2027,1424,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-205','<div class="desc"> <p>The purpose of this course is to examine the causes of the political transformation of contemporary Latino communities in the United States and to assess how these communities seek political empowerment as activists and as voter-citizens. The analysis will focus on understanding the institutional contexts of Latino life such as the economy the state and the cultural system on the one hand and the voting behavior and electoral integration of Latinos on the other hand. This approach concentrates on the identification and examination of the relationships between the following elements: (1) the various waves of Latino/a immigration to the United States; (2) state policies and social responses to Latinos'' presence in the United States.; (3) the formation of a pan-ethnic identity and the tension between this identity and other in-group stratifications based on race class gender national origin and generation; and (4) the mobilization of Latinos as a voting bloc in congressional and presidential elections.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16110,2027,332,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-206','<div class="desc"> <p>This course is an exploration of the historical and continuing significance of race in the American political system. The relevance and role of race in shaping political institutions public opinion political behavior and public policy will be examined. Special attention will be given to theoretical debates surrounding the meaning of race and how this changes depending on political context.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16111,2027,966,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-207','<div class="desc"> <p>This is a course about urban politics that takes Los Angeles as its case study. Because of the pattern of growth in the area Los Angeles is broadly defined to encompass the city the county and the region. Since politics is the study of power we will examine power in the context of the city; who has it who seeks it how has it shifted over time and what consequences result from it being exercised? Significant attention will be paid to the agency of those who have at various times had the least power in the city; how are they represented or not represented how can they influence the exercise of power? Many look to Los Angeles as a paradigmatic city. We will query the appropriateness of this observation as we identify key concepts in urban politics apply them to Los Angeles and then consider how much Los Angeles sets follows or deviates from trends.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16112,2027,1029,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-208','<div class="desc"> <p>Examination of the impact that social protest movements have had on our society -and lessons that can apply to the current period. Case studies of the agrarian revolt (the Populists) the labor movement the women''s movement the civil rights movement the peace movement the student movement the environmental movement and the consumer/neighborhood movement. Topics include: What factors lead people to participate in social movements and political protest? Why do certain historical periods seem to feature large-scale protest and upheaval while others do not? How are social and political movements related to mainstream politics such as elections political parties voting and lobbying? What is the role of leaders activists and organizers? What strategies and tactics do movements employ? What does "success" mean for a protest movement? Do protest movements make a difference in achieving more social justice and changing public policy? In addition to classroom discussion attendance at a weekly film series is required.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16113,2027,713,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-210','<div class="desc"> <p>When we paint a picture in our minds about what American politics looks like, we often think in terms of groups rather than individuals. This is no coincidence– the relevance of an issue, interest, or perspective in any democracy is a function of numbers. And bigger is better.</p> <p>But how, and why? And when, for that matter? </p> <p>How do groups seek to influence American policymakers, and why do policymakers listen? When do policymakers ignore groups, even when they’re big? How do groups form, gain power and momentum, and seek to influence politics and policy? Are interest groups good or bad for American democracy and representation?</p> <p>This course will explore interest group politics in the US through the lens of institutions, Madisonian ideals, and the logic of political action. It will apply new understandings of interest group activity and impact to contentious political issues such as gun control, abortion, civil rights, environmental policy, and income inequality. It will do so at the federal, state, and even local level of political institutions and policymaking. 12 hours of involvement per week; 180 total hours</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16114,2027,714,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-211','<div class="desc"> <p>This course is about the U.S. Congress, arguably the world’s most powerful legislative body and the engine of the American political system. Students will learn about elections, legislative procedure, the committee system, the role of parties, and the health of the U.S. political system. Ultimately, the course will examine how Congress behaves as a collective institution, the incentives that drive the behavior of individual legislators, and the quality of representation voters receive in Congress.</p> </div>','POLS 101 American Politics and Public Policy ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16115,2027,3237,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-220','<div class="desc"> <p>From extreme weather events to insurrections, crisis seems to consume politics in the United States and the globe. This course examines political leadership, public policymaking, and public opinion during crisis, identifying how crisis transforms politics-as-usual and what these transformations mean for democratic stability, human rights, and citizen wellbeing. The course will focus especially on the politics and policy of the COVID-19 pandemic, exploring to what extent the coronavirus both is and is not a “regular” type of crisis. Topics include: the concentration of policymaking in the executive branch, with consequences for democratic governance; how crisis shapes citizens’ tendencies towards extremism, polarization, and violence; and how crises differentially affect marginalized social groups—and when governments do and do not consider marginality and intersectionality in crisis response and recovery. Throughout, the United States’ pandemic experience will be compared with that of other countries and world regions. </p> <p>Sub-field: <strong>AMERICAN POLITICS or COMPARATIVE POLITICS </strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16116,2027,1485,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-221','<div class="desc"> <p>This course is an analysis of Latin American politics in the 20th century with a focus on contemporary democratic politics. The course will discuss the historical institutional and social forces that have both accelerated and opposed democratization and will cover topics of current concern to the region including economic development security and the rule of law the design of political institutions human rights and social movements.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16117,2027,3317,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-222','<div class="desc"> <p>Did you know that the party that won a majority of seats in the US House was not always the party that got the most votes? The "simple" electoral system used in most US House elections is the primary cause! This course will explore the role of electoral systems in shaping governance, policymaking, party systems, and election outcomes. Students will primarily focus on comparative legislative elections, meaning comparing the design of election systems across the globe, though presidential elections and sub-national United States elections will also be considered. In this course, students complete a series of in-class exercises, problem sets, and a final paper where they examine election results and calculate several mathematical quantities of interest. These include the Gallagher Disproportionality Index, the effective number of vote-winning/seat-winning parties, logical expectations about the country''s party system based on mathematical models, the allocation of assembly seats at the district level based on election results using proportional allocation formulas, and the allocation of seats to parties under complex electoral systems such as the single transferable vote and mixed member proportional representation. This course counts for the Comparative Politics subfield in the Politics major and satisfies the CMPS requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16118,2027,1620,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-223','<div class="desc"> <p>Has the "Third Wave" of democratization ended? Will democracy continue to be the model for the future? This course will look at the dramatic increase in the number of democracies worldwide over the last thirty years and at case studies that illustrate the political and economic factors behind the increasing number of "illiberal" "populist" and semi-authoritarian democracies; the impact of gridlock and corruption in contemporary democratic systems including the United States; and the challenges democracies are facing in integrating formerly marginalized populations including women poor and the indigenous. It will examine the US policy of "democracy promotion" and the implications of these trends for the United States in a globalized world.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','DWA 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16119,2027,3929,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-225','<div class="desc"> Beginning in the late 1970s, revolutionary movements would shake Central American societies and shape U.S. foreign policy with direct military and covert intervention in the region. Often framed as the final battleground of the so-called Cold War between the U.S. and the Soviet Union, scholars of Central America prefer to emphasize the complexity of internal social and political forces and the U.S.’s continual efforts to undermine national sovereignties and control anti-capitalist and anti-authoritarian movements in its “back yard.” This course will allow students to examine the historical formation of three distinct militarized and antidemocratic states, Guatemala, Nicaragua, and El Salvador, and the revolutionary movements that sought to radically engage in social transformations between the 1970s and 1990s. Principal themes of the course include: capitalist development and structural inequalities; revolutionary ideologies; organizational development and objectives of Central American revolutions; US interventions; social transformation and change; and lasting impacts of revolutions. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16120,2027,715,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-226','<div class="desc"> <p>This course is an introduction to 20th Century Chinese politics. The course will explore the historical background to the current Chinese situation. Students will also examine the politics of China under Mao and during the subsequent reform period including the role of China in global politics.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16121,2027,1305,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-227','<div class="desc"> <p>A comparative analysis of the history culture and contemporary politics of the four countries in the dynamic East Asian region: China Japan Korea and Taiwan. This course will also cover the political economy of the East Asian industrialism.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16122,2027,1031,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-233','<div class="desc"> <p>This course is an introduction to international security and strategic studies. This field is fundamentally about both the use of force by and violent conflict among states and non-state actors. The course will be guided by general theoretical questions regarding security: How does violent conflict or competitions shaped by the lurking possibility of such conflict affect international relations and individual societies? How has the role of violent conflict in international politics changed since the end of World War II? What is the nature of security today? These general questions will frame explorations of more specific strategic questions. Such questions will include: How do states and non-state actors use force to persuade their enemies to take (coercion) or refrain from taking (deterrence) a particular action? How can nations best prepare to prevent violent conflicts or to win them if they occur? What has determined success and failure the intensity duration and consequences of military action? We will have a particular focus on emerging transnational security issues intra-state security and the relationship among security development and state failure. Pursuing answers to these questions will require an approach that integrates theory history and current events.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16123,2027,1082,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-235','<div class="desc"> <p>This course focuses on the evolution of U.S. foreign policy in recent Administrations with special emphasis on the post-Cold War period. Attention is paid to American policy toward "emerging issues" for example the global environment development policy in the North/South dialogue ethnic violence and nationalist civil wars human rights and humanitarian relief. It explores how policy is formulated and implemented and analyzes the relationship of foreign policy to American economic and defense policies. It examines U.S. policy toward major regional power configurations-in Europe the Far East Latin America the Middle East South Asia and Africa.</p> <p>Sub-field: <strong>INTERNATIONAL RELATIONS</strong></p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16124,2027,3318,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-236','<div class="desc"> <p>Effectively tackling global challenges such as climate change, pandemics, nuclear proliferation, and the decline of democracy and trade liberalization, to name just a few examples, is not reducible to the interests and preferences of the United States. Indeed, most outcomes in global politics never are and have never been. Other countries have interests and preferences of their own, and those influence international outcomes as well. Why, for instance, does it make sense for North Korea to have a nuclear arsenal despite US interests to the contrary? And for China to try to become a hegemonic power in East Asia despite the US decades long presence in the region? Why is Putin''s Russia pushing so hard against NATO’s eastward expansion? And Latin America against U.S. influence in the Western Hemisphere? International affairs look fundamentally different when assessed from a non U.S.-centered perspective. And, history shows, U.S. interests are best served when, at the very least, take into consideration other actors'' interests and preferences and where these may come from. This course will provide students with the analytical tools necessary to start unpacking any country''s interests and foreign policies, as a first step towards recognizing that satisfactory answers to current and future global challenges require the active acknowledgment of all actors'' preferences with stakes on the matter, no matter how "powerful" the United States might be.</p> </div>','POLS 101 or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16125,2027,4455,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-237','<div class="desc"> <p style="background: rgba(255, 255, 255, 1)">This course answers how democracies die at the turn of the twenty-first century. With a primary focus on the case of the United States but also drawing on past and ongoing developments in Latin America and Western Europe, the course will allow you to explain whatâs going on in the U.S. as of right now, why, how the country got to where it is, and the âcompetitive authoritarianismâ seemingly upon us. The course will also address what, if anything, those that value due process, civil, political and social rights, may do to help reverse the democratic backsliding in the country and beyond. After successful completion of this course, you would have gained an analytical framework to think independently and based on reliable empirical evidence about how, the actual meaning of, and why, U.S. democracy is in danger.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16126,2027,716,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-241','<div class="desc"> <p>This course provides a multi-disciplinary insight into various aspects of migration and immigration law and politics. Students read and analyze important legal precedent through the study of case law as well as explore historical trends in migration to the United States. This course approaches the issue of immigration from three major standpoints: the legal, the political, and the historical. Topics include but are not limited to immigration from Latin America, asylum, temporary protected status and citizenship. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16127,2027,2355,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-243','<div class="desc"> <p>An introductory examination of the values, principles, and practices of restorative justice. The course will draw on examples of restorative justice from the United States and internationally. Topics in the course will include competing theories of justice, informal and formal approaches to restorative justice, truth telling, reconciliation, and process of reintegration. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16128,2027,335,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-244','<div class="desc"> <p>This course provides an introduction to constitutional law and constitutional theory examining the ways in which the Constitution distributes power among the branches government in the American political system and limits the exercise of those powers. The course will also consider the role of the judiciary in creating legal and political boundaries for society. Throughout the semester this course will focus not only on legal doctrine but also on the broader intellectual and political context in which it evolves. Using constitutional law cases and moot courts the course will explore the role of the United States Supreme Court as a civil liberties policymaker and the process through which decisions are reached. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16129,2027,719,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-245','<div class="desc"> <p>An intermediate course in constitutional law and theory with a focus on how the Constitution protects individual rights while accommodating the often-competing claims of state, groups and communities. Much of the course will be dedicated to the jurisprudence surrounding the 14th Amendment and the rights it has been found to protect. Specific rights and liberties covered may include racial equality, reproductive autonomy, freedom of expression, and freedom of religion. Students will be assessed primarily through mock judicial opinions and analytical essays analyzing controversies in constitutional interpretation. Disputes over rights and liberties will be treated not solely as legal questions, but as entry points into enduring questions about the character of the American system of government. </p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 or POLS 140 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16130,2027,4351,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-247','<div class="desc"> <p>This course engages students in critical examination current term United States Supreme Court cases. The course places questions of doctrine and theory in historic social and political contexts. Student are required to co-lead class sessions and have the option with permission of instructor of selecting readings the mode of analysis for the session. In addition to co-leading a class session students are required to write a series of short analytic papers of the cases discussed and a final research paper. <em>Open to sophomores, juniors, and seniors only.</em></p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 244 or by permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16131,2027,4352,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-248','<div class="desc"> <p>This course introduces students to the art of oral argument using legal theory and Supreme Court precedent. Students will work with a teammate to prepare oral arguments and also develop skills for debating constitutional issues in a competitive environment based on a yearly prompt issued by the American Moot Court Association and its pre-defined set of Supreme Court cases. This class will ask students to prepare arguments on both sides of an issue and also to learn strategies and techniques to succeed in sparring rounds with classmates and at regional and national tournaments. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16132,2027,4353,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-249','<div class="desc"> <p>This course examines United States social and political movements (e.g.,civil rights, feminist, labor, LGBT rights, domestic human rights, and conservative movement for religious liberty, economic freedom, and property)to understand their diverse influences on the construction and interpretation of law. The course pays particular attention to role of lawyers within social movements, including advocacy strategies defined under the theories of critical lawyering, movement lawyering; law and organizing; demosprudence; and cause lawyering. The course will examine the manner in which movement lawyers and the movements they support aim to alter power in a democracy and generate new normative frameworks within the United States. For example, students will interrogate how law and lawmaking is an expression of political values, identities, and institutions.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16133,2027,1621,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-250','<div class="desc"> <p>American intelligence has often been at the center of the major national security controversies since the 1945. This course will survey the history of those controversies as they involved the US intelligence community, the outbreak of the Cold War and the US-Soviet competition but also the post-Cold War crises in Europe Asia Middle East and elsewhere. The basic question is: How does intelligence influence foreign policy and strategic decisions? This course provides an overview of the theory and practice of U.S. intelligence. It details the sources and methods used by collectors the nature of intelligence analysis and the complex and often difficult relationship between intelligence agencies and policymakers. It also contains a short history of the U.S. intelligence community and evaluates the ongoing efforts to reform it in an era of greater transparency. <em>Not open to first year students.</em></p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16134,2027,1032,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-254','<div class="desc"> <p>This course will examine American political thought as it sets out and responds to the founding of the country. Specifically, we will read the Federalist papers, consider the impact of the American Revolution on the French Revolution, and explore how thinkers have reckoned with the American founding into the 21st century.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16135,2027,1306,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-256','<div class="desc"> <p>This course will introduce students to several core analytical approaches in moral and political philosophy including consequentialism utilitarianism distributive justice freedom autonomy and an ethics of care. Students will apply these approaches to case studies in ethical decision-making in politics and policy and students will weigh arguments in favor or against specific courses of action. As such this course bridges readings in moral and political philosophy with "real world" problems confronted by policymakers and leaders. In evaluating resolutions to these problems students will sharpen their critical-thinking and decision-making skills. This is a course in applied ethics with material drawn both from philosophy and from policy.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16136,2027,969,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-257','<div class="desc"> <p>This seminar surveys the historical roots of modern conservative and libertarian political ideas with particular attention to the persistent tension between tradition and innovation. The purpose of the seminar is to enable students to recognize recurring themes that have shaped political thought and action over several thousand years. Students will be graded on weekly essays and seminar participation.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16137,2027,1486,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-260','<div class="desc"> <p>The Community Law Internship provides students with an experiential understanding of the practice of âcommunityâ or âmovementâ lawyering. The Community Law Internship must be taken simultaneously with POLS 340, where students explore the theoretical foundation of community lawyering by: (1) considering how lawyers and legal strategies have historically contributed to and impeded movements for social justice in the past; (2) exploring concepts and theories of legal liberalism, rebellious lawyering, community organizing, and law and social movements; (3) assessing contemporary case studies of community/movement lawyering practices in Los Angeles; and (4) learning core skills and tactics to align legal strategies with community power-building goals. The Community Law Internship allows students to put this theory to practice. All students enrolled in the Community Law Internship work with a community-based legal organization for a minimum of 12 hours each week, working under the supervision of and learning from practicing community lawyers. The unique approach of integrating POLS 340 and POLS 260 exposes students to the law school clinic model and takes advantage of Occidental faculty expertise and the wide-range of community-based educational opportunities available in Los Angeles. Through this integrated examination of the theory and practice of community lawyering, students will build skills and identify strategies to enhance collaboration and strengthen social justice movements in L.A. and beyond. Permission of instructor required.</p> </div>',NULL,'POLS 340',NULL);
INSERT INTO course_descriptions VALUES(16138,2027,722,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16139,2027,4354,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-266','<div class="desc"> <p>This course examines the techniques and strategies used by both professional lobbyists and community based advocates to influence elected and appointed government decision makers. The course will explore the impacts lobbyists and community activists have on decision makers as they consider policy voices. The course will include discussions with elected and appointed government officials well as with professional lobbyists and community advocates. In addition to readings and speakers the course will include case studies in order illustrate the concepts and provide students with real world examples viewed from multiple perspectives. Students will engage in role-plays in order to prepare and present a strategic plan to win support or oppose a community based project or citywide policy.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 or UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16140,2027,1307,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-270','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, POLS 272) simultaneously. Students will participate in the daily activities of a campaign for United States President or United States Senate in a key "battleground" state. Students will gain experience in the highest level of politics and gain an understanding of how a national presidential campaign or a statewide United States Senate campaign is operated. Students will learn about political strategy voter contact and turnout messaging and polling communications volunteer recruitment and team-building fundraising and other key aspects of campaigns. The internship will involve working full-time (a minimum of 40 hours a week) from the first day of class until Election Day. Following that ten-week campaign fieldwork internship students will return to campus and participate in two seminars as part of Campaign Semester. Campaigns involve long hard days. The staff that students will work with will typically be working at least 14-16 hour days. Although students are required to work at least 8 hours a day they are likely to work more. As part of the Campaign Fieldwork Internship students will be required to read three books-biographies of each major party candidate and a book describing previous presidential campaigns. Students will be required to maintain an internship journal that will be handed in at the end of the 10-week internship. The journal will describe their activities (including the projects they work on campaign meetings and events relationship of the campaign to the media and to constituency groups) the internal dynamics and work of the campaign the different roles and tasks of staff and volunteers in the campaigns the way the media reports on the campaign the students'' reflections on these matters and at the end a summary of the campaign outcome. Students will be required to email the supervising Occidental faculty member at least once a week about their activities and reflections. The students will be supervised in the field by a campaign staff member. Students will participate through teleconferencing in a two-hour course meeting with other students and faculty three times during the semester. Students who will be working in different parts of the country will stay in touch with each other as well as with the faculty through Moodle a web-based course management system. The system allows faculty members to post readings facilitate discussions give and receive assignments etc. Students in various parts of the country will thus form a virtual classroom and on-line learning community. Some students may wish to document their experiences on the campaign trail observe events and interview staff and volunteers by making videos. If so these should be posted to the faculty and other students via the internet. Enrollment limited to students participating in the Campaign Semester Program. </p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16141,2027,1308,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-271','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. In this course which will take place during the last five weeks of the semester students explore theoretical and applied concepts pertaining to United States political campaigns. Students will examine the role of money media candidates interest groups leadership gender race and political parties in terms of who wins and loses elections. Learning will take place through assigned readings professor lectures guest lectures from campaign experts and candidates and peer dialogues. Student learning will be assessed by their contribution to the classroom experience (discussion dialogue) discussion of assigned readings and examinations. Enrollment limited to students participating in the Campaign Semester Program. The program is open to all Oxy students regardless of major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16142,2027,1309,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-272','<div class="desc"> <p>Campaign Semester provides Occidental College students with an opportunity to learn about political campaigns and elections through first-hand experience. Students receive a full semester of college credit (16 units) while volunteering full-time in a Presidential U.S. Senate U.S. House or gubernatorial campaign. The program is offered during Presidential and Mid-term elections. Students can volunteer for a Republican or Democratic campaign or a "minor" party if the campaign is set up to adequately supervise volunteers. The program is open to all Oxy students regardless of major. This course entails production of a 25-page research essay addressing a major question pertaining to campaigns in American politics. Each student will work with a professor to craft a high-quality research paper that enters the academic debate on their selected topic incorporates extensive secondary data and existing research and presents original analysis based on the student''s campaign fieldwork. Enrollment limited to students participating in the Campaign Semester Program. Satisfies the Second-Stage Writing Requirement.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 270, POLS 271, and POLS 272) simultaneously.</p> <p>Subfield: American Politics</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16143,2027,1343,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-280','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics credits for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> will work four full days per week in an internship in a political office non-profit corporation or for-profit company engaged in political or policy work. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16144,2027,1344,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-281','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course develops leadership skills through the themes of public speaking professional writing networking interviewing and giving and receiving feedback. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirements for the major.</p> <p>Students who participate in Campaign Semester take the following three courses (POLS 280 and POLS 281 and either POLS 282 POLS 283 POLS 284 POLS 285 or POLS 286) simultaneously. </p> <p>Students enrolled in the Washington Internship Institute in D.C. are required to take a political leadership seminar that explores how active global citizenship can advance career goals. </p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16145,2027,1554,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-282','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on environmental law and public policy. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(16146,2027,1555,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-283','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on public health policy in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286).</p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(16147,2027,1556,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-284','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on women''s leadership in a global context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills Comparative Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(16148,2027,1345,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-285','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on politics and public policy in the Washington D.C. context. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills upper-division American Politics requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281, and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously. </p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C.</strong> are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(16149,2027,1346,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-286','<div class="desc"> <p>Washington Internship provides Occidental College students with an opportunity to learn about D.C. politics and policy making through first-hand experience through the Washington Internship Institute. Students receive a full semester of college credit (16 units) while volunteering full-time for a branch of government a policy non-profit or a media organization that covers politics. This course focuses on international relations. Enrollment limited to students participating in the Washington Internship Institute Program. Course fulfills International Relations requirement for the major.</p> <p>Students who participate in <strong>Campaign Semester</strong> take the following three courses (POLS 280, POLS 281 and either POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286) simultaneously.</p> <p>Students enrolled in the <strong>Washington Internship Institute in D.C</strong>. are required to enroll in one of five courses on policy-making (POLS 282, POLS 283, POLS 284, POLS 285, or POLS 286). </p> </div>','POLS 101 ','POLS 280 and POLS 281 ',NULL);
INSERT INTO course_descriptions VALUES(16150,2027,2837,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-287','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> <p>Subfield:<strong> American Politics</strong> or <strong>Comparative Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16151,2027,338,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-295','<div class="desc"> <p>Topics in Politics. Can be repeated once for credit if topics differ.<em>NOTE: Different topics may satisfy different Core Program requirements</em>.</p> <p><strong>The Politics of Climate Change</strong></p> <p>This course will explore the politics around climate change and climate policy, with a particular focus on the energy transition in the U.S. We will analyze the history of U.S. climate and energy policy, and explore how this policy response is shaped by public opinion, executive orders, the courts, federalism, and interest groups. We will also explore more recent climate policies such as the Inflation Reduction Act in depth, and compare U.S. climate policy to approaches in other countries. Finally, we will explore climate politics in the Trump administration, including legislation repealing climate investments and executive orders weakening climate regulations. We will discuss responses from companies and the international community and the decline of climate as a central issue in political discourse. The framework of climate justice will be applied throughout the course, and we will analyze how climate justice can best be implemented through the U.S. political system. Students will study U.S. climate and energy policy to inform class mini-conferences, policy memos, and other assignments. </p> <p><strong><span style="font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: normal; background-color: #ffffff; text-decoration-style: initial; text-decoration-color: initial;">Subfield: </span></strong><span style="font-size: small; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; white-space: normal; background-color: #ffffff; text-decoration-style: initial; text-decoration-color: initial;"><strong>American Politics</strong></span></p> <p><strong>Institutions in Flux: American Politics in the Trump Era</strong></p> <p>This course examines the historical forces that have shaped American political institutions, their role in maintaining the rule of law and informal norms, and contemporary challenges now confronting governing. Topics may include the role of increased partisanship and polarization, legislative stalemate, politicization of the courts, an expanded executive branch, and growing public distrust.</p> <p>Subfield: <strong>American Politics</strong></p> <p><strong>Classical Quest for Justice</strong></p> <p>The questions at the heart of classical political philosophy are very simple, even if the treatments of them by the ancient philosophers are extremely complex. What is justice? What does it ask of us as individuals? What does it demand of political communities with respect to their internal structure and in their interactions with other communities, especially in times of war? Finally, to what extent are the demands of political life compatible with the radical questioning of philosophy? In this course we will engage with these questions via careful study of some of the greatest works of Ancient Greece, focusing principally on Plato’s <em>Republic </em>and Thucydides’ history of the Peloponnesian War. These texts will be approached not only as crucial documents for our understanding of another culture, but also as works that address enduring questions of moral and political life. <em>Core Requirement Met: Pre-1800 (CPPE)</em></p> <p>Subfield: <strong>Political Theory</strong></p> <p style="margin-left: 0; margin-right: 0;"><strong>Comparing Colonial Legacies</strong></p> <p style="margin-left: 0; margin-right: 0;">A comparative analysis of colonial governing practices, processes and modes of decolonization, and their long-term effects on the states and societies of the postcolonial world. Critical questions focused on in this course will include the relative political legacies of different types of colonialism (i.e. settler, exploitative, internal) and different colonial powers, the effects of colonial policies regarding ethnic boundary-making, and the implications of enduring ties of various kinds between the post-colonial states and the former metropole. The geographical scope of this course will be broad, including, but not limited to, Latin America, the former Soviet Union, Sub-Saharan Africa, South Asia.<em> Core Requirement Met: Global Connections.</em></p> <p style="margin-left: 0; margin-right: 0;"><strong>Politics of Development</strong></p> <p style="margin-left: 0; margin-right: 0;">A comparative analysis of the politics and economics of states in the “developing world”, including an introduction to theories that link variation in political systems to levels of economic development. This course will also analyze questions such as the relationship of natural resource dependency to political regime characteristics, the determinants of foreign aid allocations, and the origins and roles of international development organizations. The geographical focus of the course includes Africa, Asia, Latin America, the Middle East, and the former Soviet Union. <em>Core Requirement Met: Global Connections</em>.</p> <p><strong>Reimagining Public Safety: Debates Over Policing and Criminal Justice</strong></p> <p>In the years following the murder of George Floyd by Minneapolis Police, massive demonstrations took place around the nation, demanding an end to police violence and systematic racism. During that moment, many said it was finally time to "reimagine public safety" - a wide-ranging term that encompassed perspectives as varied as police abolition and more robust community policing. It coincided with the rise of a new wave of progressive prosecutors determined to end the "carceral state" and "promote restorative justice."</p> <p>Cities that promised reimagined public safety have experienced what Black Lives Matter co-founder Patrisse Cullors refers to as "The Great Regression," a pro-police, pro-law and order backlash that has seen an increase in police budgets and targeting of progressive prosecutors.</p> <p>How did this happen? What forces shape these policy discussions and political decisions? What is the future of public safety and criminal justice in urban centers? This course will examine these questions, with an emphasis on Los Angeles, with frequent guest lectures, including policymakers, police officials and prosecutors, and community organizers.</p> <p>Subfield: <strong>American Politics</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16152,2027,340,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,'POLS 295',NULL);
INSERT INTO course_descriptions VALUES(16153,2027,968,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/200/pols-353','<div class="desc"> Increasingly people are on the move, but not on equal terms. In this class, we will approach contemporary regimes of movement normatively and critically. While our investigations are anchored in political theory, we will draw from other social sciences and read studies ranging from that of ancient Greeks to those about contemporary Tibetans.<br/> <br/> The first half of the course centers on questions of membership. We will examine the meaning of citizenship, probe into the various membership categories beyond that of citizenship, interrogate the acquisition rules of these membership categories, and question how rights and obligations are distributed across these categories. We will also explore the possibilities of going beyond the nation state, as promised by the idea of cosmopolitan citizenship.<br/> <br/> The second half of the course turns to migration. We will study the debates over whether people should be allowed to migrate across state borders and, relatedly, on what grounds could the state justify their control over borders. We will then attend to the meanings and politics of the categorization of migrants (refugees, asylum seekers, illegal immigrants, economic migrants etc.). Finally, we will ask what rights and obligations migrants have in relation to their home, host, and diasporic communities.<br/> <br/> <br/> This course fulfills the Theory Subfield for the Politics major and minor requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16154,2027,1310,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-300','<div class="desc"> <p>This course is an introduction to the process of conducting political science research including the formulation of research problems research design collection of data and statistical analysis and interpretation. Participants will learn to analyze political science data using statistical packages in a lab setting.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16155,2027,1347,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty housing transportation crime and violence pollution racial segregation and neighborhood change. It also examines how power is exercised by different groups including business citizens'' groups community organizations unions the media mayors and other government officials. The course will also examine the role of city planning and planners conflict and cooperation between cities and suburbs problems of urban sprawl loss of open space water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe Canada and the developing world. Public policies to solve urban problems.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16156,2027,1557,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-302','<div class="desc"> <p>This course examines the institution and practices of the American presidency. More specifically it encourages students to analyze the role and structure of this office as well as different ideas about presidential power and influence. Particular attention is paid to the presidency and policy making media coverage checks and balances the Constitution and public opinion.</p> <p>Sub-field: <strong>AMERICAN POLITICS</strong></p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16157,2027,3343,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-305','<div class="desc"> <p>Students are introduced to foundational theories of public policy, gaining valuable insight into "who gets what, when, and how" in the political process. Applying theory to case studies, current events, and policy alternatives, students are asked to critically evaluate policy problems and solutions, draft policy briefs, and pen opinion pieces to advocate their policy positions.</p> </div>','POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16158,2027,1671,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-320','<div class="desc"> <p>Critical examination of the major substantive concerns methods and purposes of comparative politics focusing on broad "macro-level" analytical concepts (e.g. modernization and political development dependency and world system perspectives revolution and political violence political culture and elites) rather than descriptive information about particular political systems. However a few political systems will be studied and used as cases for methodological discussions.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16159,2027,1623,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-321','<div class="desc"> <p>This course will explore the role of women in politics throughout the globe with an emphasis on case studies from the developing world. Students will examine the development of policy changes that advance gender equality paying attention to how the international system domestic institutions and social movements play in this process. Students will also study how women attain and wield power in local and national politics. The course will further emphasize how gender politics intersects with other forms of identity politics including race ethnicity and sexuality. The course is grounded in the study of comparative politics and will draw primarily on examples from Latin America Africa the Middle East and Asia.</p> <p>Sub-field: <strong>COMPARATIVE POLITICS</strong></p> </div>','POLS 101 , POLS 120 , or DWA 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16160,2027,1129,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-324','<div class="desc"> <p>This course explores the complex history and development of populist regimes in Latin America from the early 20th century to the present. Through a combination of historical analysis, theoretical frameworks, and case studies, we will examine how populist and nationalist ideologies have shaped and transformed political, economic, and social structures across the region. Key topics include the rise of charismatic leaders, ideological constructions of “us” vs “them,” rhetorical strategies, and the relationship between populism, nationalism, and authoritarianism. We will start with the region’s most well-known populist figures of the 20th century: Brazil’s Getulio Vargas and Argentina’s Juan and Eva Perón. We will then examine more recent figures like Peru’s Alberto Fujimori and Pink Tide figures like Venezuela’s Hugo Chávez, and Bolivia’s Evo Morales. Finally, we will turn to contemporary figures like Brazil’s Jair Bolsonaro, Nicaragua’s Daniel Ortega, and El Salvador’s Nayib Bukele.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16161,2027,4355,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-341','<div class="desc"> <p>Justice Lab is an advanced course for students seeking to examine contemporary justice issues. The course will provide a challenging and intellectually rigorous environment in which students ask not only what are pressing justice questions, but also develop practical tools to address these issues. Students in the course will work in collaborative teams to select issues for the "lab" to address, research all aspects of the issue selected, and coordinate and participate in drafting a series of policy papers and other "tools" for change. The course aims to create an an environment similar to that of a think tank allowing students to refine research, analysis, problem-solving, presentation, and writing skills.</p> <p>Sub-field: <strong>PUBLIC LAW</strong></p> </div>','POLS 101 or permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16162,2027,2484,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-351','<div class="desc"> <p>Alexis de Tocqueville, John Stuart Mill, and Friedrich Nietzsche are three of the most influential theorists to grapple with the tradition of liberal political thought. The first two are friendly critics who seek to fortify liberalism against what they see as its latent pathologies, while Nietzsche is a not-so-friendly critic who wants to overturn it entirely. Given that liberalism is under attack today from both the right and the left, there is much to gain from serious study of their reflections. In this course, we will compare the strengths and weaknesses of their diagnoses of the present and visions for the future. Guiding questions for the course will include the following: Does liberal democracy uplift human beings, or degrade them? How should the competing demands of individual independence and community solidarity be balanced? How can we best counter modern society’s tendency to engender stifling conformity? What is the significance of Christianity for the cultural heritage of Western society? What role, if any, should religion play in societies of the future? Finally, what does human flourishing consist of, and what kind of sociopolitical conditions best facilitate it? The culminating assignment of for the course will be a substantial research paper on one or more of these thinkers.</p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16163,2027,1312,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-352','<div class="desc"> <p>This course is an intensive exploration of black political thought from a variety of perspectives. Emphasizing conceptual diversity and continuity across time and geography we will examine a wide range of authors including but not limited to Angela Davis W.E.B. DuBois Frantz Fanon Marcus Garvey bell hooks Martin Luther King Jr. Glenn Loury Booker T. Washington Ida B Wells Cornell West and Malcolm X. The range of ideological perspectives under review will include liberalism conservatism nationalism womanism Marxism and pan Africanism. <em>Not open to frosh.</em></p> <p>Sub-field: <strong>POLITICAL THEORY</strong></p> </div>','POLS 101 or BLST 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16164,2027,3998,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-353','<div class="desc"> <p>In this course, we will move beyond the Western canon and examine important political ideas--equality, territory, state, development, gender, race, and colonialism--through an engagement with a diverse range of political traditions across space and time, with an emphasis on South and East Asian, Middle-Eastern and North African, and Caribbean traditions. Furthermore, instead of studying each tradition on its own, we will be actively tracing the transnational connections between them and compare their narratives, both with each other and against received Western notions. We will situate these traditions in the historical developments of these regions and extend our conversations to their current political developments. Students will gain a comparative understanding of how ideas and politics intertwine across these globally diffused regions.</p> </div>','POLS 150 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16165,2027,3157,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Climate Policy and U.S. Politics</strong></p> <p>This course will explore the politics around climate change and climate policy, with a specific focus on the U.S. We will analyze the history of U.S. climate and energy policy, and explore how this policy response is shaped by public opinion and polarization, executive orders, the courts, federalism and state actions, and interest group political spending. We will also explore recent climate policies such as the Inflation Reduction Act in depth, and compare them to policy approaches in other countries. The framework of climate justice will be applied throughout the course, and we will analyze how climate justice can best be implemented through the U.S. political system. Students will conduct research on U.S. climate policy to inform policy memos and other writing assignments. This course fulfills the second-stage writing requirement for the Politics major.</p> </div>','Graduate students may not enroll in this class. Frosh students may not enroll in this class. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16166,2027,725,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/300/pols-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16167,2027,726,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/400/pols-495','<div class="desc"> <p>Politics majors are required to take Politics 495 in fulfillment of their senior comprehensive obligation. They therefore should have met or be in the process of meeting all requirements for the major. The Seminar meets in the spring semester but students will be expected to submit proposals for their research papers in the fall semester prior to the actual meeting of the Seminar. The Seminar itself will engage all students in an analytical review of a wide range of materials from various aspects of the discipline and will require that students write a major research paper in one particular sub-discipline of the field. Students qualifying for College Honors will be given an opportunity to write research papers that will be evaluated by the department for honors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16168,2027,4456,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/400/pols-496','<div class="desc"> <p>Independent Research with one-on-one faculty mentoring. Includes development of topic, execution of research design, writing and oral presentation of a senior thesis. Only open to seniors. Permission of instructor and department chair required.</p> </div>','POLS 101 and POLS 300 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16169,2027,4356,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pols-politics/400/pols-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16170,2027,1130,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/100/psyc-101','<div class="desc"> <div><p>Introduction to psychology as the science of behavior. Topics include: physiology, learning, perception, motivation, development, emotion, cognition, social processes, personality, and psychopathology. <em>This course is a prerequisite for all upper division coursework. Core Credit only when taken at Occidental. Students with a 4 or 5 on the AP Psychology exam or a 6 or 7 on the IB Psychology exam are not eligible for Psych 101 but may take 200- or 300-level classes.</em></p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16171,2027,1190,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/100/psyc-111','<div class="desc"> <p>The average adult possesses over 50000 concepts ranging from physical concepts like "force" and "density" to biological concepts like "growth" and "reproduction" to mathematical concepts like "integer" and "fraction." This course will explore the cognitive foundations of that vast conceptual repertoire and the mechanisms by which we enrich revise and restructure those foundations. Emphasis will be placed on analyzing current research at the intersection of cognitive developmental and educational psychology. No prior coursework in Psychology or Cognitive Science is required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16172,2027,4357,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/100/psyc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16173,2027,344,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/200/psyc-200','<div class="desc"> <p>Introduces scientific methodology in the context of psychological research. Basic concepts in scientific inquiry and specific observational correlational and experimental techniques are covered. Includes an introduction to descriptive statistics. This course is a prerequisite to many 300-level courses in Psychology.</p> </div>','PSYC 101 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16174,2027,345,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/200/psyc-201','<div class="desc"> <p>Introduces parametric and nonparametric inferential statistics used in psychological science through analyses of variance appropriate to complex experimental designs. Includes a review of research methods and descriptive statistics and work with statistics software.</p> </div>','PSYC 200 (Students must earn a grade of C- or better) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16175,2027,4358,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/200/psyc-270','<div class="desc"> <p>This course will cover key concepts in nervous system structure and function through the lens of the sensory and affective experience of pain. Students will gain a basic understanding of nervous system organization, evolutionary adaptation, neuronal mechanism of action, sensation and perception, plasticity, and top down processing through the examination of the neuroscience of pain and the clinical experience of pain and its treatment, including coverage of disparate pain treatment on the basis of race and gender. This course will also take an interdisciplinary perspective to pain, considering how it has been represented in literature and philosophy. Although there are no specific prerequisites, the course will include (optional) materials appropriate for students with a deeper background in psychology, biology, neuroscience, and/or cognitive science.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16176,2027,347,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/200/psyc-295','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. Instructor permission required. <em>Graded on a Credit/No Credit basis only. PSYC 101 or PSYC 102 or relevant introductory course in another department and permission of instructor. May be repeated once for credit if the second project is different from the first. Instructor permission required.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16177,2027,4359,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/200/psyc-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16178,2027,348,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-321','<div class="desc"> <p>The study of continuity and change across development. Emphasis on application of research methods to issues related to cognitive emotional personality and social development. The course will focus primarily on these issues in infancy and childhood.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16179,2027,350,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-322l','<div class="desc"> <div><p>Must be taken concurrently with Psychology 322.</p></div> </div>','PSYC 101 ','PSYC 322',NULL);
INSERT INTO course_descriptions VALUES(16180,2027,351,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-323','<div class="desc"> <p>Behavior of individuals and groups in and across social contexts. Topics include self social cognition attitudes and persuasion liking and loving prejudice aggression and social conflict group identity consciousness and social action.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16181,2027,352,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-330','<div class="desc"> <p>The study of psychopathology including diagnosis and classification core dysfunctions and physiological and psychosocial causative factors. Intervention treatment and preventative strategies will also be discussed.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16182,2027,736,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-334','<div class="desc"> <p>Consideration of psychological influences on health and illness including health-and illness-promoting behavior and lifestyles cognitive and emotional processes and social and institutional practices.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16183,2027,4360,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-339','<div class="desc"> <p>This course explores the psychological phenomena that surround the optimal functioning of individuals, groups, and systems with an emphasis on scientifically-validated strategies for living a more satisfying life. Topics include gratitude, charitable giving, exercise, breath and mindfulness, habit formation, and other key tenents of positive psychology research. This course will also emphasize applications of positive psychology research to improve our own lives as well as our communities and the planet.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16184,2027,353,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-340','<div class="desc"> <p>Introduction to the study of theories and applications of psychology in profit and not-for-profit organizations. Representative topics include understanding how ability personality perception motivation leadership and group dynamics affect productivity and worker satisfaction. Issues of fairness and accuracy of assessment will also be discussed. Emphasis is on practical and personal learning of the dynamics of the work environment.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16185,2027,354,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/copy-of-psyc-350','<div class="desc"> <p>The course will survey diverse psychological perspectives on gender and its personal and cultural implications. Will explore: meanings of gender evolutionary physiological developmental and sociocultural roots of gender difference; the relation of gender to cognition personality sexuality health interpersonal relationships and political power; the commensurability of various theoretical approaches to gender.</p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16186,2027,731,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-301','<div class="desc"> <p>This course will introduce general concepts of learning in humans and other animals that will be rooted in the principles of learning developed from nonhuman animal research. Explores fundamental concepts phenomena and principles of learning such as reinforcement Pavlovian conditioning and retention/forgetting. Issues addressed are traditional views of learning biological and cognitive constraints the role of nonhuman animal models and the utility of learning theory.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16187,2027,971,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-302','<div class="desc"> <p>This course focuses on how sensory systems function, with emphasis on quantitative methodologies, neurophysiological mechanisms, structure/function relationships, and ecological contexts. How humans perceive the world is situated in a comparative landscape -- that is, human are assumed to be creatures with much in common with other creatures and yet different in some crucial ways tied to their evolutionary history and habitats. Attention is paid to phenomenology and philosophical issues, such as the relationship between perception and "reality." This course is distinguished from cognitive or social psychology approaches to perception, by virtue of its focus on evolutionarily old, fully embodied, and sensuous experience.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16188,2027,871,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-306','<div class="desc"> <p>The study of theoretical models that address the mental processes underlying knowledge and thought and the empirical research in support of those models. Emphasis is placed on how people solve problems make decisions draw inferences attend to their environment communicate remember and learn. Much of the material is applied to real-life settings.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 101 or COGS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16189,2027,2491,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-309','<div class="desc"> Ontogentetic approach to human movement behavior and physical growth from conception to adulthood with emphasis on maturational and environmental factors. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16190,2027,2493,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-310l','<div class="desc"> One and a half hour per week Motor Learning and Control laboratory. </div>',NULL,'PSYC 310L',NULL);
INSERT INTO course_descriptions VALUES(16191,2027,1736,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-311','<div class="desc"> This course provides an introduction to Sport and Exercise Psychology as a theoretical and applied discipline. It addresses major psychological concepts, providing a broad knowledge base for the understanding of the complexities and dynamics that exist for both individuals and groups in the realm of sport and exercise. A major focus of the course is the development of practical skills and interventions that can be applied to these settings with the aim of positively influencing the behavior, performance and level of participation of an individual or group. </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16192,2027,349,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-322','<div class="desc"> <p>Because the brain and central nervous system are to some degree responsible for all behavior, thoughts, and emotions that humans experience, psychology can be thought of as a biological science. This class is an introduction to that perspective and an exploration of what it means for the study of the mind. Students who enroll in PSYC 322 must enroll concurrently in the accompanying weekly 3 hour laboratory (PSYC 322L). Core Laboratory Science credit will be awarded for students completing both PSYC 322 and PSYC 322L. </p><p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ','PSYC 322L ',NULL);
INSERT INTO course_descriptions VALUES(16193,2027,972,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-336','<div class="desc"> <p>This course surveys the emerging field of Evolutionary Psychology. It begins with the historical social and political context of evolutionary theory reviews tenets of modern evolutionary theory explores the relationship between evolution and other change processes and applies evolutionary reasoning to psychological phenomena and contemporary social issues.</p> <p>Fundamental Domain: <strong>BIOLOGICALLY BASED ANALYSES</strong></p> </div>','PSYC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16194,2027,2513,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-351','<div class="desc"> <p>Traditional linguistics has revealed how complex and ambiguous natural language is. Despite this fact, people are able to effortlessly and accurately produce and understand language. At the crossroads of linguistics, psychology, and neuroscience, psycholinguistics is concerned with providing an explanation of how the human language processing system works. This course introduces students to the main goals, theories, and experimental methods of psycholinguistic research. We discuss the current state of our understanding of language learning and processing, as well as the experimental and analytical techniques that have been used to examine these issues.</p> </div>','PSYC 101 , COGS 101 , LING 301 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16195,2027,355,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-395','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required.<em>Graded on a Credit/No Credit basis only.</em></p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16196,2027,738,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/psyc-397','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16197,2027,2492,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/300/pysc-310','<div class="desc"> <p>Introduction to the processes of control and coordination in the performance of motor skills. Neurophysiological, mechanical, and cognitive bases of motor skill acquisition. Includes one three-hour laboratory per week. Open to juniors and seniors only.</p> </div>','PSYC 101 ','PSYC 310L ',NULL);
INSERT INTO course_descriptions VALUES(16198,2027,2905,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-420','<div class="desc"> <p>Introduction to the psychosocial and neurobiological basis of addiction. Substance abuse and behavioral compulsions, including drugs, gambling, eating, and sexual addictions are examined. Additional focus on diversity in addicted populations, the business and politics of drugs, and prevention. Consequences of addictions will be studied at the individual, family, community and societal levels. This course will draw on current research and controversies in the field of addictions. </p> </div>','PSYC 200 , and either PSYC 322 , PSYC 330 , or PSYC 334 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16199,2027,873,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-428','<div class="desc"> <p>The study of social cognitive physical and psychological development during adolescence and emerging adulthood. Topics include sexual development and the social consequences of being sexually active the function of family support the increasingly important role of peer relationships drug abuse and antisocial behavior and school adjustment.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16200,2027,357,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-431','<div class="desc"> <p>Introduction to the techniques and processes of clinical psychology and psychotherapy. Topics include major schools of thought and approaches, specific techniques of assessment and treatment, relevant research, assessment of effectiveness, and issues of gender and culture. <em>Open only to seniors or by permission of instructor.</em></p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 200 and PSYC 330 (Students must earn a grade of C- or better in both) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16201,2027,1349,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-444','<div class="desc"> <p>This course will examine contemporary research on higher-order cognition. Topics will include inductive reasoning deductive reasoning causal reasoning moral reasoning concept acquisition belief formation and analogical inference. Students will read empirical papers representing a variety of experimental methods and a variety of theoretical perspectives.</p> <p>Fundamental Domain: <strong>INFORMATION PROCESSING</strong></p> </div>','PSYC 200 or COGS 201 and PSYC 301 , PSYC 302 , or PSYC 306 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16202,2027,3914,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-447','<div class="desc"> <p>This course serves as an exploration of the emerging field of canine cognition, the study of thinking and reasoning in domestic dogs. Topics include social reasoning, problem solving, cooperation, communication, and other current focal points of canine cognition research. Additional emphasis will be placed on the role of domestication in shaping modern dogs, effective research methodologies and practices for canine research, implications of canine research for working dogs and responsible pet caretaking, and the future of canine cognition. This course will draw on both foundational and current research in the field of canine cognition.</p> </div>','PSYC 200 and PSYC 336 or PSYC 322 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16203,2027,973,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-448','<div class="desc"> <p>Introduction to and evaluation and application of classic and contemporary theories of personality including psychoanalytic humanistic behavioral cognitive and object relations models. Primary sources autobiographies and case studies will supplement traditional texts.</p> <p>Fundamental Domain: <strong>INTERPERSONAL AND INTERGROUP</strong></p> </div>','PSYC 200 and PSYC 321 , PSYC 323 , or PSYC 330 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16204,2027,3878,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/copy-of-psyc-495','<div class="desc"> <p>Students working with department faculty on faculty-initiated research projects for a minimum of five hours per week may enroll in this course. Responsibilities in the research project will vary from assistance with data collection to participation in data analysis and interpretation and conceptualization of future research. May be repeated once for credit if the second project is different from the first. Instructor permission required. Graded on a Credit/No Credit basis only</p> </div>','PSYC 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16205,2027,3999,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/psyc-401','<div class="desc"> <div><p>This course will support senior Psychology majors as they conduct original research to fulfill their senior comprehensive requirement. Open only to senior Psychology majors.</p></div> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16206,2027,974,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/psyc-460','<div class="desc"> <p>Psychological assessment involves the measurement and evaluation of psychological characteristics including cognitive ability personality traits motivation and more. A blend of theory-driven research and practical analysis techniques will be covered to explain how common and experimental instruments work and to examine whether certain methods are valid in academic organizational criminal and mental health contexts.</p> <p>Fundamental Domain: <strong>APPLICATION-ORIENTED</strong></p> </div>','PSYC 201 ; and PSYC 321 or PSYC 340 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16207,2027,358,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/psyc-490','<div class="desc"> <p><strong>Human Sexuality</strong></p><p>This course explores medical, biological, psychosocial, and cultural aspects of human sexuality. Course topics are explored through a biopsychosocial perspective of sexual functions, gender, sex-role orientation and preference; sexual behavior theories and sex therapy techniques; societal attitudes; contraception and reproduction; sexual arousal and response; communication in sexual relationships; sexual dysfunction; AIDS and other sexually transmitted infections; sexual deviance; sexual victimization; and commercialization of sexuality.</p><p><br/></p><p><strong>Human Development and Aging</strong></p><p>This course examines biological, cognitive, emotional, and social changes in later life and how they shape health, decision-making, and well-being. Through interviews with older adults, students connect developmental theory to lived experience and analyze aging through a social-justice lens, including ageism and equity in care.</p><p><br/></p><p><strong>Neurodivergence</strong></p><p>This course focuses on neurodiversity and neurodevelopmental disorders (including autism spectrum disorder, attention-deficit/hyperactivity disorder, intellectual disability, and specific learning disorder) through multiple lensesâincluding clinical psychology, psychiatry, developmental psychopathology, neuroscience, education, and sociology. Topics such as etiology, developmental course, symptom experience, classification, group and individual differences, and intervention and support will be discussed.</p><p><br/></p><p><strong>Psychology of Prejudice</strong></p><p>This course focuses on how we can use social psychological theories and methods to understand prejudice, stereotyping, and discrimination. We will examine how prejudice and stereotypes differ across social groups, why prejudice is prevalent, and what are the origins of prejudice. This course will also examine the ways psychology as a field has contributed to prejudice and how it can be used to combat prejudice.</p><p><br/></p><p><strong>Psychology and Law</strong></p><p>Intersection of social science theory and data with law and legal procedure: Topics may include: normative and psychological theories of justice; eyewitness memory, deception detection, investigative interviewing and interrogations; jury selection and jury decision-making; forensic psychology and assessment; corrections and sentencing.</p><p><br/></p><p><strong>Trauma</strong></p><p>This course focuses on the experience of and responses to trauma in its many forms - natural disaster war and genocide child abuse assault and violence. The impact of trauma for both the individual and society at large are examined in the context of a stress coping resilience framework. Prevention and intervention strategies will be explored.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16208,2027,4361,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/psyc-psychology/400/psyc-497','<div class="desc"> <p>Students with advanced competency will conduct an in-depth literature review on a topic of mutual interest to her/him and a faculty mentor. Completed upper-division coursework directly relevant to the project is required. Students will write an APA-style paper on her/his research. Permission of instructor and department chair required.</p> </div>','PSYC 200 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16209,2027,4362,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/100/pubh-197','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16210,2027,2838,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-203','<div class="desc"> <p>This course explores the nation''s public health challenges and the ways that public health functions as a combination of science and politics. The course examines the various social, political, and demographic factors that impact population health. Students are introduced to public health concepts and learn to analyze health problems, considering the influence and intersection of race, status, gender, income, education and sexuality. Using data, evidence, and health behavior theory, students evaluate strategies and solutions to address health inequity and improve population health.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16211,2027,2904,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-206','<div class="desc"> <p>Students will conduct a hands-on internship in Los Angeles County, supervised by the course instructor and in collaboration with a community partner, government agency, community clinic, or public health focused non-profit organization. The internship requires 8-hours each week. The topic of the course is flexible and to be determined by the course instructor. It may be repeated once for credit and does not fulfill a Public Health minor elective requirement. <em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16212,2027,2938,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-209','<div class="desc"> <p>Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16213,2027,3844,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-220','<div class="desc"> <p>Public Health Nutrition involves the application of food and nutrition knowledge, policy, and research to improve the nutritional status and health of populations. This course will examine the role of nutrition as a means of promoting, maintaining, and improving the health and wellness of community populations using evidence-based approaches. Students will explore the relationship between nutrition and the bodyâs systems, including the effects of obesity, diabetes, allergies, and autoimmune diseases. This course will include a brief overview of the causes and treatment of eating disorders and food addiction. At the conclusion of the course, students will understand how to analyze and evaluate nutrition information. The course will integrate skills obtained through practice and experience with external evidence from systematic research regarding nutrition education.</p> </div>','PUBH 203 Introduction to Public Health ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16214,2027,2886,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-238','<div class="desc"> <p>This course is designed to introduce the basic concepts, principles, and methods of epidemiologic research. In our pursuit to understand the interplay of risk factors and patterns of human disease and health, we will cover the history of epidemiology, the principles of epidemiologic thinking and of causal inference, the basic measures of disease frequency and of association, and how to compute them. We will also learn about the major types of epidemiologic study designs and explore the major fields of epidemiologic investigation. To better understand the practical application of study methods used in epidemiology, the class has a laboratory component (PUBH 238L). The laboratory component will provide students with the opportunity to apply the concepts from lecture and develop an epidemiological research proposal. Students will work through the research process, moving from developing a health related research question to operationalizing the idea into a research plan.</p> </div>','Statistics ( BIO 268 , COMP 146 , MATH 150 , PSYC 201 , or UEP 305 ) and PUBH 203 ','PUBH 238L ',NULL);
INSERT INTO course_descriptions VALUES(16215,2027,2839,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-248','<div class="desc"> <p>The course will examine major global public health problems and the range of responses from international organizations transnational networks and domestic and community-based institutions. Despite improvements in the health status of low- and middle-income countries over the last half-century the challenges to advance global public health remain daunting. What are the sorts of strategies these actors have used in addressing such health issues as HIV/AIDS malaria unsafe food and water tobacco use and others? What is the role of human rights in addressing the underlying determinants of ill-health? The course will present basic concepts for understanding global public health including morbidity mortality demography epidemiology and the political social and economic determinants of health. We will utilize a case study method to examine successful and less successful efforts to improve global health and to debate enduring political economic social and cultural controversies in the arenas of global health. Students can expect to gain knowledge of the major issues and actors in global public health and an introduction to the analytic and quantitative skills needed to monitor and evaluate evidence used in formulating policies and programs.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16216,2027,4363,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-249','<div class="desc"> <p>This course explores core concepts in global public health, the development of human rights'' instruments, and how these two fields have increasingly intersected in global and local public health work. Specifically, we will review public health methods of measurement and analysis - spanning epidemiological, economic, and political approaches - to understand if, and how, a rights-based approach to health can inform more critical and more productive approaches to issues such as HIV/AIDS and other sexual and reproductive health concerns. Finally, this course examines how global public health issues have generated dramatically different responses across and within regions, countries, and communities. We will focus, particularly, on the experience of Brazil, given its changing role in the global economy and its progressive public health approach.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16217,2027,4364,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16218,2027,4365,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/200/pubh-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16219,2027,2840,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/300/pubh-301','<div class="desc"> <p>This course provides an examination of women''s health across the life cycle, with special emphasis on the structural and societal factors that influence health outcomes among women. It introduces students to public health frameworks for assessing women’s health issues within various contexts. This course uses these frameworks as a basis for examining the relationship between social and cultural factors and women’s health. It provides an overview of the emerging and on-going issues in women''s health, including sexual and reproductive health, contraception, gender-based violence, mental health and substance abuse, in order to understand and address health inequities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16220,2027,3325,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/300/pubh-303','<div class="desc"> <p>This course introduces students to the unique health challenges faced by sexual minority populations, a group that includes lesbian, gay, bisexual, transgender, and queer individuals. As a public health class, there will be a specific focus on factors that impact health outcomes at the community and population level, paying due attention to the distinct subgroups that make up sexual minorities. Drawing from current and historical examples and case studies, we will examine how cultural, social, and political forces contribute to health disparities in these groups. Through a public health lens, we will discuss the dynamics among behavior, identity, life stage, setting, and environment, and think through implications for health outcomes. Students will assess various determinants of health and consider a range of strategies that could be used to improve health and reduce health disparities.</p> </div>','PUBH 203 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16221,2027,2841,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/300/pubh-307','<div class="desc"> The community health internship course is designed to provide students with real-world experiences to develop new skills and enhance insights into myriad community health issues and solutions. Under supervision of the course instructor and in collaboration with a community proctor/partner students will intern for two, 4-hour days a week at a health focused non-profit organization community clinic or government agency. Through the internship and course work, students explore and analyze the social, cultural, and systematic barriers to health in Los Angeles and the U.S. Students reflect on and discuss the complexities of keeping communities healthy, considering the impact of policy, identity, power, urban planning and culture. Before registering students must check with the course instructor to review their semester schedule and determine how the internship will fit into their school week. Students are encouraged to register early for this course in order to identify partner sites that can support their learning goals. Prerequisite: PUBH 203 or UEP 203 (may be taken concurrently). </div>','PUBH 203 (may be taken concurrently) ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16222,2027,4366,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/300/pubh-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16223,2027,4367,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/300/pubh-397','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16224,2027,4368,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/pubh-public-health/400/pubh-497','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16225,2027,3319,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/copy-of-rels-121','<div class="desc"> <p>In this course, we will study the various ways in which the devil has been depicted in societies of the Americas since colonialism to the contemporary moment. Considering the devil as both a figure of systemic domination and resistance, we will ask: how is the devil, heathen and demon a pillar of colonial and imperialist legacies? In what ways have these figures been at the hands of the marginalized, not merely as sites of empowerment, but as an active forging of decolonial existences and knowledges? We will seek to answer these questions by closely examining important themes in conjunction with their social(/historical) time periods, including: the âNew Worldâ (colonization and Indigenous resistance of the âheathenâ), the formation of Religious Studies as an academic discipline (Christianity as the dominant religious tradition), feminism (brujerÃ­a (witchcraft)), and popular culture (horror film and television). As major parts of their course assessment, students will have the opportunity to apply what they learned through creative projects such as zine-making and short-story writing.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16226,2027,4424,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-105','<div class="desc"> <p><span style="font-size: 11pt; font-family: Arial, sans-serif; color: rgba(0, 0, 0, 1); background-color: rgba(0, 0, 0, 0); font-weight: 400; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-variant-alternates: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; text-decoration: none; vertical-align: baseline; white-space: pre-wrap">Religion is not just located in churches and temples, it can also be found online, in sports stadiums, at movie theaters, and in many other unexpected places. In this class, we will analyze the diverse sites in which religion animates popular culture by looking at fashion, music videos, sports, TikToks, advertisements, celebrities, video games, Disney, memes, childrenâs toys, comics, and more. By exploring a variety of examples from different times, places, and religious traditions, we will study how religion intersects with popular culture and what makes it appealing, seductive, and controversial. We will also examine why religious symbols and imagery are so common in popular culture, how religious groups use popular culture, and why popular culture fandoms often resemble religion. Assignments include short papers analyzing examples of religion and popular culture and a final creative project where students will have the opportunity to create their own piece of popular culture.</span></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16227,2027,1559,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-110','<div class="desc"> <p>A survey of historical and contemporary Native American religious traditions, attending especially to how they have developed amid colonization and resistance. Students will study the broad variety of ways that Native American traditions imagine land, community, and the sacred, and study the range of practices, ceremonies, and cultural institutions related thereto. Students will also investigate how these religious traditions have been contested or negotiated when they came in contact with Christian missionaries, in contemporary treaty rights, and in intertribal new religious movements.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16228,2027,3305,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-111','<div class="desc"> <p>This course focuses on displacement as a defining feature of Mediterranean history from antiquity to the present. In the first half of the course, we will study a series of case studies on displaced peoples from antiquity: those who were forced from their homelands because of religious or political exile (including, Judeans, political criminals, sexual deviants, and heretics), because of natural disaster (including, those stranded by shipwreck or relocated by earthquakes, drought, or famine), or because of war (including, prisoners of war, and refugees). Through these case studies, we will attend to how ancient folks described their experiences of displacement, their expressions of grief and longing for home, their unique vulnerabilities in new communities, as well as the care and hospitality extended to them. In the second half of the course, we will move forward in time to see how more modern displacements across the globe have been figured in terms of ancient precedents (such as, an odyssey or exodus), and we will query the conceptual resources such precedents provide in coping with and navigating displacement. Finally, we will study the acceleration of displacements in the Mediterranean region within the last decade, and students will engage in a social justice project related thereto. This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16229,2027,3847,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-113','<div class="desc"> From <em>The Golem</em> to <em>The Exorcist</em> to <em>Raaz</em> to <em>A Girl Walks Home Alone at Night</em> to <em>Midsommar</em>, the horror genre has engaged religious traditions'' notions of the supernatural, the monstrous, the evil, and the terrifying. Studying horror films, music videos, comics, and short stories, this class will historically contextualize examples of ''religious horror'' so we better understand how different religious communities conceptualize the horrifying, the supernatural, and the monstrous. Throughout our study, we will engage the relationship between religion and horror through four major categories: religion in horror (how are religious communities, myths, rituals, monsters, fears, and ideas interpreted within the horror genre?), horror in religion (where does the ‘horrific’ appear in religion? What monsters and utmost evil appear within religious communities? How are otherworldly / supernatural beings depicted in ways that are understood as different / nonhuman?), horror as religion (how do horror narratives spawn their own religious communities?), and religion &amp; horror in dialogue (How do religion and horror speak to each other to form one another? How is this a reiterative process of creation and remaking with respect to ghost hunting, possession narratives, and cryptozoology?). Through these categories, we will investigate how horror leverages the monster as a practice of dehumanization and marginalization (religious stereotypes often entwined with features of race, class, gender, sexuality, nation, and post/coloniality). In focusing primarily on mostly U.S.-made films, this course will ultimately interrogate how the themes of religion and horror reflect larger structures of U.S. culture and power and the inevitable existential anxieties that accompany them. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16230,2027,741,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-120','<div class="desc"> <p>This course is centered around the question: How can we be "well" when the world is beset by the existential issue of climate change? To answer this question, students will study cosmological systems that conceive of human health as fundamentally connected with ecological health, and consider how these systems are responding to the challenges of climatic variability. Specifically, cosmologies from the Asia-Pacific region – where climate change have already fundamentally altered daily life in the form of receding glaciers and flooding islands – will provide students with an insight into how religions and cultural traditions conceptualize health and multispecies flourishing in the face of impacts from climate change that threaten multiple species across ecosystems. The course will be organized around case studies related to land, ocean, mountains, and space, with examples from multiple religious and cultural communities from the Pacific Coast of the United States, to Hawai’i, Tuvalu, Aotearoa New Zealand, Thailand, India, China, and Bhutan. And these case studies will cover examples from multiple moments of the Anthropocene, from the Little Ice Age that began in the fourteenth century CE to the present, as well as incorporate interdisciplinary research from the environmental Humanities, such as anthropology, environmental ethics, political ecology, and religious studies. This course will allow students to see how different cosmologies – both Indigenous and imported – provide people with holistic notions of health, explanations to understand the enormous changes brought by the Anthropocene, and to explore and develop resources for enacting measures that will bring about justice that can benefit human communities and the environment.</p> <p>This course is part of the Humanities for Just Communities curriculum.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16231,2027,360,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-130','<div class="desc"> <p>A truism in Jewish Studies says: if you want to study Jews, you have to study the world. While this course does not require knowledge of the entire world, it will offer you the exciting and challenging invitation to study Jews as an often minority population with international impact and significance. Within such an expansive aperture we will focus on the narrativesâboth ancient and contemporaryâthat have proven themselves most resonant and subject to discourse for Jews. Joining this discourse ourselves we will not merely learn dominant Jewish narratives which respect to, for example, the Hebrew Bible, exile, and the history of Jews of European origin (Ashkenazi Jews). We will also consistently complicate and subvert these narratives with the help of Jewish feminist and queer voices as well as perspectives and histories from Jews who have not gained dominant privilege from an afforded proximity to whiteness, mainly Jews with origins in the Middle East-North Africa (Mizrahi Jews) and Spain (Sephardi Jews). By the end of the course students will be more adaptable thinkers who are able to be inspired by the wide aperture of Jewish experience and identities in order to further expand the diversity and dynamism of Jewish narratives rather than limit them.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16232,2027,1035,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-145','<div class="desc"> To make sense of contemporary American culture and society, we need to understand the crucial role that religion has played in forming and shaping the nation. From the first Native American inhabitants to the early Protestant colonists, from enslaved Africans to Catholic, Jewish, Buddhist, Hindu, and Muslim immigrants, we will learn about the influence of religion on various communities throughout American history. By focusing on life in early America, we will consider how Americans have developed, negotiated, and interpreted their religious traditions in new settings and circumstances. Throughout the course, we will pay special attention to how religious debates dovetailed with the pressing social issues of the day, and how religion has alternately served as a vehicle for liberation and venue of oppression. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16233,2027,1624,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-147','<div class="desc"> <p>In the recent history of the Americas, many groups have founded intentional communities shaped by the ideals of what a faithful, utopian society ought to look like. Some aspiring utopias, like that of the People''s Temple in Jonestown, Guyana, ended in dramatic displays of violence and death. Others, like the Mormons in Salt Lake City, have succeeded in the face of sustained adversity. But most land somewhere in between, sustaining themselves through partial integration with dominant society. In this course, we will study different intentional religious communities - often called "cults" or "sects" by outsiders - throughout the Americas. As we study the Oneidan "free love" community, an ayahuasca church in Brazil, an early Rastafari group in Jamaica, we''ll ask questions like: Why have religious people sought to separate themselves from society? How have they appealed to scripture or revelation to justify their separation? What challenges - such as external political pressure or internal strife - have they faced? What groups have been "successful," and what are the measures of success? And what do these attempts at establishing utopias tell us about what it means to be religious?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16234,2027,742,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-150','<div class="desc"> <p>This course will introduce students to some of the major themes, issues, people, places, sights, and sounds of Islam past and present. This course is intended to highlight the manifold expressions of Muslim life through diverse historical, cultural, and geographical contexts. Its two broad aims are: 1) to provide students with basic knowledge of Islamic history, belief, and ritual life; and 2) to equip students with knowledge for critically and actively analyzing discussions of Islam in media and contemporary world events.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16235,2027,1673,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-160','<div class="desc"> <p>A large part of the success of Buddhism has been in its ability to travel and adapt to local cultural traditions, providing communities with a rubric for living a meaningful life. This course will provide an introduction to these traditions by looking specifically at Buddhist concepts and practices within human life and life cycles. We will ask: What do ritual and textual traditions about human life in various cultures tell us about Buddhist values and concepts of how to deal with suffering and thereby to life and die well? Are there differences between classical textual ideas about these topics and Buddhism as it is lived through ritual and community practice? How do both textual and ritual traditions maintain human life?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16236,2027,3306,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-169','<div class="desc"> <p>Imperial violence and capitalist economic restructuring historically drove Asians to migrate to the United States. Once here, people of Asian descent engaged in transformative political activism and constructed new cultural identities and alliances to meet the challenges of diasporic and immigrant life. This course will examine the cultural and political geographies of trans-Pacific migration and identities from the 19th century to the present. From Har Dayal, Sun Yatsen, and Qiu Jin in the early 20th century to the 1960s Third World Liberation Front, the I Wo Kuen Red Guards in San Francisco working with the Black Panthers, and beyond, political activists have been crisscrossing the Pacific, building and rebuilding networks of resistance to colonialism, marginalization, and exploitation. The course draws heavily on the rich history and cultural diversity of Los Angeles and Southern California, which has been a center of Asian and Asian American movements—migratory, political, and cultural—for over a century. Students will examine a variety of primary sources, including literature, political manifestos, and films, and engage deeply with the cultural and spatial geographies of these histories. Field trips to local religious sites and neighborhoods, paired with visits from local scholars, journalists, and filmmakers, will bring these histories to life and illustrate their legacies shaping the present. Along with regular writing assignments, students will collaborate on a final project mapping transpacific migration histories and social justice alliances in LA.</p> <p>This course is part of the Humanities for Just Communities Immersive semester.</p> </div>',NULL,'This course will be run alongside an FYS with the same title. ',NULL);
INSERT INTO course_descriptions VALUES(16237,2027,975,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-190','<div class="desc"> <p>From the 1st-6th centuries CE, early Christian communities throughout the Mediterranean had different ideas about who Jesus was, what kind of movement he inspired, and what it meant to be or to act like a Christian. In this course, students will investigate the variety of early Christian communities that structured their movements around the figure of Jesus by studying their primary sources: stories, letters, sermons, theological treatises, art, artifacts and architecture. Students will explore the practices and ethics that dictated the daily lives of early Christians, how they interacted with their Jewish and “pagan” neighbors, the theological issues debated among early Christian communities, including charges of "heresy" and the development of orthodoxy.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16238,2027,743,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/100/rels-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16239,2027,3352,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/copy-of-rels-221','<div class="desc"> <p>Between the 1960s and the 1980s, as feminist theologians of Latin America actively confronted the Vatican’s and liberation theology’s insufficiencies in leading the marginalized out of cycles of socio-economic oppression, such theologians were commonly deemed “indecent.” In this course, we will examine how various Latin American women and social movements embraced and practiced indecent liberation, starting with the Mexican Revolutionary period and concluding with global understandings of indecent liberation in relation to religion and feminism. We will ask: How has “indecency” been constructed as a site of hegemonic power, particularly at the intersections of religion, race, gender, class, and/or able-bodiedness? In what ways is indecent liberation a form of empowerment and (how) does it relate to identity-formation? Is indecency merely a tool for liberation or a place of generative knowledge and ways of being? We will answer these questions through three main case studies, starting with “muscular” Christian women of the Mexican Revolution, continuing with indecent liberation theology during the mid- to late- twentieth century, and concluding with contemporary chicana epistemologies and ecofeminism. At the end of the class, students will apply course content to a case study of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16240,2027,3823,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/copy-of-rels-235','<div class="desc"> <p>This course centers gender as it examines the Jews of Southwest Asia and North Africa (SWANA)—a region typically defined as stretching from Morocco to Afghanistan. Our exploration will include delving into life prior to the 19th century in places like medieval Egypt and late 1700s Morocco before colonialisms supported by western imperialism narrowed expressions of Jewish identities and histories. With a focus on correcting the negative effects of eurocentrism and colonialism, the course will uncover the potential pasts possible in SWANA where gendered Jews have been integral. Sources and topics will include fictional accounts such as <em>Ninette of Sin Street</em> exploring Jews and gender in early 20th century North Africa; speeches from early women’s rights activists throughout Egypt and the Levant such as those from Esther Moyal; biographies and music from Jewish women of culture such as artists Layla Murad in Egypt and Salima Pasha in Iraq; autobiographical accounts; and films such as <em>Dimona Twist </em>which discusses SWANA Jewish women’s racist discrimination in Israel/Palestine. By the end of the course, students will feel empowered to make more speculative assertions as a challenge to imperialist violence and possess a more varied and dynamic picture of Jewish communities and Jewish people.</p> <p>This is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16241,2027,2497,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/copy-of-rels-257','<div class="desc"> Our course will examine the history of antisemitism from late antiquity to the present. We will investigate the historical differences and continuities between anti-Judaism and antisemitism, and problematize their ahistorical conflation with anti-Zionism. Leaning on this long history, we will examine the conditions under which various historical actors articulate, proclaim, and contest claims of antisemitism, rather than assuming its universal definition. We will also take an intersectional approach to understanding the ways in which antisemitism connects with racism and Islamophobia. By the end of the course, students will be able to open up conversations about antisemitism, understand it relationally with other forms of hatred, and identify how it might be instrumentalized in contemporary political discourses. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16242,2027,1036,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-200','<div class="desc"> <p>We are currently in the midst of a "psychedelic renaissance." Over the past two decades, university-backed research institutes, non-profit organizations, and capitalist entrepreneurs around the world have celebrated drugs like psilocybin and LSD as powerful therapeutic tools capable of helping people work through trauma and improve well-being. And according to some prominent researchers, the "mystical experience"--or a feeling of union with the divine--produced from these drugs is key to their therapeutic efficacy. But is this claim valid? And why would scientists make such a claim in the first place? In this course, we will answer these and related questions by exploring the global cultural history of psychedelics from the early twentieth century to the present. With special attention to the relationship between psychedelics and religion, we will examine everything from these substances'' ritual consumption in indigenous communities and in pre-modern Europe, to scholars'' and researchers'' use of religious texts to explain psychedelic experiences, to legal issues surrounding psychedelic use and religious freedom.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16243,2027,4425,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-202','<div class="desc"> Praying, fasting, singing, kneeling, raising hands - all of these are bodily movements that are widely recognized to be “religious.” But we often don’t think of other bodily practices and experiences such as dressing and tattooing our bodies, or bodily sensations and feelings such as ecstasy and joy, as equally essential to religious life. In this course, we will consider how the human body has been a primary site of religious meaning and contestation in the United States in the past and present. We will investigate how religious traditions have shaped ideas about what bodies are for and which bodies matter by looking at how bodies intersect with state power, legal rulings, medical authority, and assumptions about race, ethnicity, gender, sexuality, and disability. In doing so, we will consider how and why some bodies have become symbols of purity, while other bodies are deemed dangerous. We will pay particular attention to moments in American history when bodies have become contested terrain in religious debates over issues such as enslavement, missionary projects, religious freedom, and reproductive rights.<br/> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16244,2027,4369,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-203','<div class="desc"> <p>Food practices are fundamentally rooted in religious beliefs and systems of morality, whether through offerings to deities, dietary taboos, or food hospitality. Moreover, eating is an act that can define who belongs in a religious community, or also define the savage Other who eats the wrong thing the wrong way. In this class we will examine a central question: how have religious traditions used food and food symbolism to construct relationships between individuals, the community, and nonhuman beings (animals, deities, ancestors, etc.)? To answer this question, we will employ critical anthropological and historical methods to consider the influence of hunting and farming on religious practices beginning in ancient Mesopotamia, the role of dietary restrictions in the spread of major world religions during the classical age (including guidelines for kosher, halal or vegan consumption), and debates around ritual sacrifice and cannibalism that surfaced in Christian missions in a global early modern world. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16245,2027,3233,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-204','<div class="desc"> <p>The project of queer theory is invested in destabilizing essentialist identity constructions, especially the links between gender, sexuality, and desire. Religious discourses have historically been a powerful force in buttressing such essentialist constructions of identity and thus have, in many instances, undermined the project of queer theory. Yet, a number of scholars have found queer theory, queer experiences, and/or queer identity useful lenses through which to engage with religious texts, practices, and communities. With course materials including scholarly readings, as well as films, documentaries, music, podcasts, comedy and visual images, we will pay particular attention to the lived aspects of queer engagements with religion. For instance, we will cover topics such as Judeo-Christian reinterpretations of Genesis to make room for same-sex marriage; conceptions of transgenderism in the time of the Prophet Muhammad; gender fluidity in iconography of the Buddhist boddhisatva, Kuan-yin; gender role mixing in Tantric Hindu ritual; and, Native American postcolonial approaches to HIV within the “two-spirit” community. Through these and other case studies, we will analyze how the intersection of religion and sexuality is inevitably entwined with questions of race, class, embodiment, nation, and post/coloniality.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16246,2027,2564,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-205','<div class="desc"> <p style="font-style: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; text-indent: 0; text-transform: none; white-space: normal; word-spacing: 0; text-decoration: none; margin: 0; line-height: 16.866667px; font-size: 11pt; font-family: Arial, sans-serif; caret-color: rgb(0, 0, 0); color: rgba(0, 0, 0, 1)">How do we relate to the nonhuman world, the "holy sh*t!", that makes up the world around us? What are our responsibilities to âstuffâ when we consider objects to be more than objects, and explore cosmologies that acknowledge agency beyond the human, in material objects including places, plants, bodily adornments, texts, and physical representations of all of these? This course considers how human communities across time and space have created, lived with, and destroyed powerful belongings by thinking about these material belongings in and out of context. These contexts include traditional settings, as well as the role of colonialism, the marketplace, and museum in the remaking of relationships. By the end of the course, we will have a variety of lenses for understanding the power of materiality in our lives.</p><p><br/></p><p><br/></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16247,2027,3320,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-207','<div class="desc"> <p>This course is an introduction to the major trends of Jewish mysticism from late antiquity to the present day. Major texts like the <em>Zohar</em> and the <em>Tanya,</em> and mystical movements like Rhineland pietism and Hasidism, will be explored chronologically to trace the development of these traditions and discern what is continuous and discontinuous within each one. Major themes such as mystical union, hermeneutics, asceticism and embodiment, esotericism, as well as meditative practices and paths will also be highlighted. What is it like to be a Jewish mystic? What is the texture of their mystical experiences and how are they woven into the mystic’s personal and communal life? Jewish mysticism will also be explored in relation to both exoteric expressions of Judaism as well as forms of mysticism found in other religions. We will conclude the course with an in-depth examination of Kabbalistic traditions still found and practiced today, from the secluded worlds of the ultra-orthodox to the universal formulations of the Kabbalah center.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16248,2027,3848,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-208','<div class="desc"> <p>In 1965, Rabbi Abraham Joshua Heschel marched with Reverend Martin Luther King Jr. and in 2014, Jews in Massachusetts protested police violence during Hanukkah under a banner that read “Jews Say #BlackLivesMatter,” two instances that illustrate the joint struggle for freedom shared by Jews and Black Americans. However, this relationship, like nearly all relationships, was not without its variances. For example, in the 1950s, civil rights activist Malcolm X criticized the Israeli occupation of Palestine and Black Americans and Palestinians found mutual recognition during the Ferguson-Gaza moment of 2014. In this course we will study multifaceted Black-Jewish partnerships, as well as Black-Jewish-Palestinian interactions. We will learn that the occupation of Palestine did not necessarily spell the breakdown of Black-Jewish interactions because these relationships have always been complex. Reading op-eds, academic articles, novels, memoirs, and films, we will explore a range of topics such as: anti-Black racism; antisemitism; Afro-Jews; mistreatment of Mizrahi (Middle Eastern Jews) at the hands of Ashkenazi (Jews of European origin); Palestinian activism and solidarity activism with Palestinians; Black Internationalism; intersectionality; and much more. By the end of the course, students will be able to identify and appreciate a much more sophisticated history of Black-Jewish-Palestinian solidarity, as well as understand both the erudition and emotional lives of committed liberation activists whether they be Ashkenazi Jews, Afro-Jews, Black folks, Palestinians, or Mizrahi Jews.</p> <p>This a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16249,2027,4457,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-209','<div class="desc"> From the first Olympic Games held in honor of Zeus to contemporary debates over public prayers on the football field to athletes who rely on meditation to perform under pressure, the relationship between religion and sports is long-standing and varied. Moreover, scholars have traced the ways in which sports function as religion in terms of the ritual structure of sporting events, the myths surrounding certain teams or players, and the community formed among fans of the same team. This course explores these many ways in which sports converge with religion. We will consider how sports and religion--from across global contexts--intersect with gender, race, sexuality, disability, commercialism, and the media by exploring case studies that students will select based on their interests. And we will extend our analyses in the classroom into the real world by taking field trips to sporting events. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16250,2027,744,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-210','<div class="desc"> <p>Scholars and cultural critics often talk about the commodification, marketization, and commercialization of religion. What do these expressions mean, and what kinds of processes and transformations do they refer to? How do they help us problematize the role of religion in economic life, the relationship between the religious and the secular, and the demarcation of “religion” and “economy” into separate realms of the sacred and the profane? This course will equip students with historical knowledge and an interdisciplinary toolkit to understand the complex material, ideological, cultural, and ethical entanglements between religious and economic life. The course is divided into two parts. In Part 1, we will survey classic debates about whether capitalism forces a progressive decline in religion or whether capitalist modernity itself is a continuation of Christianity in a secularized form. We will also question Eurocentric assumptions about capitalism’s Christian origins that inform histories of capitalist expansion from the West to the global South. Moving from theory to practice, we will then examine religious and economic interactions in everyday life: including religiously-imbued practices of symbolic exchange, market transactions, money-making, gift-giving, indebtedness, and workplace discipline from the bazaar to Wall Street. Part 2 will leverage these concepts and apply them to concrete case studies. In particular, we will investigate the emergence of strategic alliances between conservative religious movements and global neoliberal capitalism, as witnessed through examples of Evangelical Christianity in the US, Hindutva in South Asia, and the rise of Islamic banking in the Middle East. Through these cases, we will discern how religion acts as a means of resistance against capitalist exploitation but also gets co-opted and assimilated into capitalist projects.</p> <p>This course is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16251,2027,3849,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-212','<div class="desc"> <p>“The Palestinian flag was fluttering…over the Dome of the Rock. Jerusalem had finally become Al-Quds again” (Emad El-Din Aysha, <em>Palestine+100</em>). As we will discuss in this class, the key to understanding such a passionately transformative statement is to recognize that Jerusalem is both historically renowned as a major sacred site of Judaism, Islam, and Christianity and futuristically imagined as a site of (shared) belonging. Inspired by speculative works such as <em>Palestine +100 </em>and <em>East Jerusalem Noir </em>as well as poetic claims from artists such as Naomi Shihab Nye, Mahmoud Darwish, and Mohammed el-Kurd this course will show how belonging to Jerusalem has been established for over three millennia from different standpoints. Our study of poetic, fictional and futuristic works, will be buttressed by historical, archeological, ritual, and autobiographical sources. By the end of the class, students will understand how Jerusalem has been sanctified as a holy city, the various idioms used to establish belonging to Jerusalem, as well as how and why peace is still aspired to within the presence of Israel’s occupation.</p> <p>This a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16252,2027,4370,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-214','<div class="desc"> <p>This course orients students to the fields of medicine, magic, and miracle in the ancient Mediterranean (5<sup>th</sup> century BCE- 5<sup>th</sup> century CE). We will start by studying the ways people experienced, understood, and responded to illness and suffering. Then we will explore the options available to them as they sought help in the “healthcare marketplace”: physicians, “midwives,” druggists, ritual experts (aka "magicians"), or religious healers. Consulting a range of sources—such as medical treatises, folk remedies, religious texts, “magical” recipes and spells, and archaeological evidence—we will seek to understand their distinctive views about the cause and treatments of illness, as well as the bitter competition between healers. We will see that ancient rhetorical strategies to malign competitors—strategies that mobilized already well-defined social differences along political, gendered, classed, religious, and ethnic lines—created impressions of and hierarchies between medicine, religion, and magic that persist still today.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16253,2027,1191,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-215','<div class="desc"> <p>This course explores the dynamic religious and cultural landscape of East Asia, providing an overview of religion as it has been constructed in the states that are today known as China, Japan and Korea. In addition to learning about Confucianism, Daoism, Shintoism, and Buddhism, students will also learn about shamanistic and folk traditions, as well as practices that span across traditions, in order to provide students with tools to resist simplistic understandings of religious identity. Furthermore, taking both a chronological and comparative approach, the course leads students through the development of different traditions by situating them in their broader socio-political contexts. Finally, the course engages with multiple themes and perspectives, including the relationship between religion and the state, the development of institutions, literary and artistic expression, and gendered experiences of religion.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16254,2027,4371,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-222','<div class="desc"> <p>Islam and capitalism are often viewed as two systems belonging to separate spheres of religious and economic life, yet in this course we will explore their historical, conceptual, and material entanglements. We will examine how interactions between Islamic law and commerce shaped Muslim societies during watershed moments in the history of capitalism, including the rise of trade networks in the Mediterranean and Indian Ocean; the birth of the joint-stock company and the corporation; colonialism and industrialization; and most recently, the ascendancy of neoliberal financial capitalism. In addition to developing a broad understanding of the economic history of Muslim societies from West Africa to Southeast Asia, students will ask analytical questions like: Are religion and economics mutually exclusive or overlapping domains of life? In what ways is a commitment to capitalism and a faith in free markets akin to religious beliefs? Has religion contributed to the great economic divergence between Euro-American and Muslim societies? Can modern Islamic experiments in global finance inspire efforts to combat racial capitalism and climate change?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16255,2027,1351,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-228','<div class="desc"> <p>Latino/a religious social movements around the world have pursued liberation from oppressive forces and sought to move toward just and equitable futures. In this course, we will examine the ways various Latin American social movements from the late nineteenth century to the present day have defined and practiced liberation, paying special attention to the distinctive role of religion in these movements. We will ask: How can religion provide a foundation for liberation? More specifically, how can religion foster visions of life honoring justice and prosperity? In what ways have religious communities lead organized resistances? And even when mobilizing for liberation, to what extent can religion continue to solidify forms of oppression? We will seek to answer these questions through a series of case studies including: 1) a unique form of “muscular” evangelical Christianity across Latin America after the Spanish-American War (1898) that sought to combat the oppressive powers that limited their sovereignty; 2) liberation theology and spiritual praxis within the Mexican American Civil Rights Movement of the 1960s; and 3) Latino/a global missionary efforts through various evangelical organizations. At the end of the class, students will have the opportunity to apply what they have learned to a Latin American social movement of their choice in a final research project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16256,2027,1087,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-232','<div class="desc"> <p>A study of the development of the religion of ancient Israel and its expression in the Hebrew Bible. Special emphasis will be placed on the emergence of the central ideas of Biblical religion which formed the foundation for early Judaism and in time of Christianity and Islam. In addition to close reading of selected Biblical texts in translation attention will be paid to the historical context in which ancient Israel lived and to the findings of modern critical scholarship and archeology.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16257,2027,746,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-242','<div class="desc"> <p>An exploration of the relationship between religion and environmental ethics. How do various world religions view the natural world and what role do they propose for human beings in nature? What is the history of environmental ethics and how does religion figure in that history? How are religious traditions such as Buddhism Christianity Hinduism Islam Judaism Native American Spirituality and Taoism rethinking their environmental views especially in light of ecofeminism perspectives?</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16258,2027,4372,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-246','<div class="desc"> <p>This course explores modern Muslim engagements with, and resistance to, the violence of Islamophobia, colonial racial capitalism, and the carceral state. Our examination will unfold through a series of historical case studies from the Muslim abolitionist movement against the Transatlantic slave trade in colonial West Africa to the Nation of Islam’s Civil Rights Era struggle against policing and incarceration and, more recently, the astonishing rise of a capitalist-friendly American Muslim neo-conservatism that promotes a color-blind allegiance to the carceral state. Throughout the course, students will learn about different strategies of power used to discipline and regulate populations—from biopolitical and carceral technologies to new forms of surveillance capitalism—and Muslim responses to their proliferation—from strategic accommodation to decolonial critique and social justice activism. Students will be able to observe and compare Muslim approaches to prison reform and abolition through the work of organizations such as the Tayba Foundation, the Council for American Islamic Relations (CAIR), and Believers Bail Out. Finally, in addition to familiarizing students with Euro-American scholarship on race and power, the course will also introduce them to indigenous Muslim theorizations of black suffering, liberation theology, and social justice in the field of critical Muslim studies.</p> <p>This is a 4-unit course. On average, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16259,2027,4373,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-248','<div class="desc"> <p>This course will introduce students to the diverse religious history of the Los Angeles Basin, with special attention to the themes of borderlands and <em>mestizaje</em>. By studying primary source documents, visiting museums, and conducting ethnographic research, students will learn about the variety of religious traditions and religious communities that have flourished in the region—ranging from indigenous religions, to colonial Catholicism, to immigrant religions like Taiwanese Buddhism and Christianity—and we will learn about how these religious communities reflect Los Angeles’s place on the horizons of the Atlantic and Pacific Worlds. After an introductory section of the course that provides historical context for the colonial past that shaped the city’s cultural geography, we will turn to a focus on lived religion in contemporary Los Angeles. We will study distinct religious traditions, as well as practices that cut across religions and thus complicate the border between religion and culture. Finally, with an eye toward religious contact, conflict, and exchange, we will ask how religion in Los Angeles both reflects and challenges narratives of American religion more broadly.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16260,2027,976,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-250','<div class="desc"> <p>What is Religious Studies? Students in this course will answer this question first by tracing the historical formation of the academic study of religion (from monasteries to the university), and across various disciplines (sociology, psychology, anthropology, history, economics, etc.). We will then engage more deeply with the various theoretical and methodological tools available to scholars of religion by reading a range of scholarly works that illustrate these approaches and by giving students the opportunity to practice some of these approaches. In the end, students will become familiar with the landscape of the academic study of religion, will be able to assess the value and limitations of different scholarly approaches to the study of religion, and will have cultivated skills necessary to participate in conversations in the field. Required for Religious Studies majors and minors, recommended in the Sophomore or Junior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16261,2027,3824,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-255','<div class="desc"> <p>Discussions of the SharÄ«âa (Islamic law) in American public discourse conjure images of veiled women, girls barred from attending school, and public spectacles of flogging and stoning to death. Such a caricature of the SharÄ«âa as a medieval and draconian penal code elicits public fear and state suspicion. In the West, this caricature induces legislative measures to curb the SharÄ«âaâs perceived threat to security, democracy, and human rights. On the other hand, Islamists seek to harness the SharÄ«âa as an instrument of political legitimacy and authoritarian rule, using it to curb individual freedoms and stamp down on womenâs rights. Both uses of the SharÄ«âa reify it in ways that erode its rich history, cosmopolitan diversity, interpretive complexity, and lived realities across the Muslim world. This course offers an in-depth introduction to the SharÄ«âa, examining its sources, people, institutions, and their historical evolution from 7th century Arabia to the present. Students will gain a holistic understanding of the SharÄ«âaâs major doctrines and practices, ranging from laws of worship and ritual purity to institutions of marriage, slavery, war, and economic welfare. We will examine the pre-modern historical and societal contexts in which Islamic legal schools evolved, as well as challenges to their orthodoxy and patriarchal structures by Muslim modernists and feminists. Students will also study the significance of colonial modernity in transforming the SharÄ«âa from a socially embedded and pluralistic legal tradition into a codified and bureaucratic legal system. Finally, we will examine the SharÄ«âaâs vexed relationship with liberal democracy in Muslim-majority countries and its vilification in Euro-American contexts in the form of anti-Muslim racism, surveillance, and Islamophobia.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16262,2027,2604,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-256','<div class="desc"> <p>Tibetan Buddhism is a globally recognized religion, with the Dalai Lama, red-robed monks, prayer flags, and prayer beads occupying a unique position in the popular imagination. These images, though, flatten the diversity and historical complexities both of the Buddhist traditions of Tibet and the spread of these traditions into surrounding regions of the Himalayas. This course will provide an overview of these traditions, exploring their trajectories of development and interactions with diverse communities, while also considering local differences and agency.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16263,2027,4374,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-258','<div class="desc"> <p>This course explores the role of religion in contemporary Chinese society and culture. The last century has seen extraordinary changes in China, with the fall of the imperial system in 1911 and the beginning of a series of experiments with modernity that included the rise of the Communist Party, the turmoil of the Cultural Revolution, and the liberalization and openness of the Reform Period which has led China to become one of the most economically and politically powerful nations on earth. This course will provide students with the opportunity to think about a myriad of questions related to the relationship between religion, modernity, and secularism, as well as the functions of religion in one of the world’s largest, most diverse, and misunderstood nations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16264,2027,2699,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-259','<div class="desc"> <p>Stories of child sacrifice. Rumors of necromancy. Images of “voodoo dolls.” In this class, students will survey a variety of magical practices throughout the Americas to ask: what is magic, and what makes it “black?” Using a series of case studies set throughout the Americas, we’ll trace the shifting boundaries between magic, religion, and reason from the colonial period to today. Students will engage sources like inquisition records, legal statutes, newspaper records, and films and fiction, to see how depictions of witchcraft and sorcery have been used to stigmatize certain traditions and people, ranging from Catholics in the United States to practitioners of African-inspired religions in Cuba and Brazil. And in doing so, we’ll learn how magic has been a key site for negotiating questions of race, progress, and citizenship in modernity.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16265,2027,1626,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-261','<div class="desc"> <p>Buddhism is found worldwide today and is cited as an influence in a wide variety of settings, including psychology, self-motivation movements, education, statecraft, art, music, and science. However, its historical beginnings as a religious movement 2,500 years ago in India are often left out of these discussions. Buddhism is instead commonly presented as it has been reimagined by different agents as “more of a philosophy than a religion” and compatible with Western Enlightenment ideals, such as rationalism, empiricism and science. This course will provide a critical perspective on the process through which Buddhism has been constructed by various intellectual and political agents as it has developed in the modern era. Rather than attributing these characteristics of the tradition to inherent elements in some timeless ahistorical Buddhism, the course will instead encourage critical reflection on the broader cultural, political and economic processes that have influenced the development of modern Buddhism, including global networks of trade and technological exchange, colonialism (and anti-colonialism), cosmopolitanism, nationalism, the rise of secularism, and globalization between India, China, Japan, Sri Lanka, Tibet, Britain and America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16266,2027,2357,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-266','<div class="desc"> This course examines selected topics related to gender and sexuality as they have been negotiated in different global manifestations of the Buddhist tradition. Spanning over 2,500 years and multiple civilizations, Buddhism as a philosophy and Buddhist communities have constructed concepts of gender, sexuality, and the body in multiple, often conflicting, ways. Seen as androcentric and misogynist by some and liberating and non-judgmental by others, Buddhism and Buddhist institutional attitudes related to these key themes have been constructed through complex interactions between ancient traditions and the different societies in which Buddhism has developed. The course will be anchored in theoretical considerations of sexuality and gender, which we will explore through different case studies from India, China, Tibet, Thailand, Japan, and Korea. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16267,2027,1674,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-276','<div class="desc"> Mainstream historical accounts of empire tend to focus on political and economic reasons for state expansion, leaving students with little insight into the experience of colonialism and imperialism "on the ground" for both the colonizers and the colonized. This course will offer methodological tools that encourage an understanding of everyday, non-elite voices into the study of empire in Asia and the Pacific by focusing on religious experience. Studying religion -- which was used as both a tool for colonial domination, as well as for resistance -- complicates ideas of empire as straightforward and as a mono-directional process. Case studies in this course will explore the interaction between empire and religion across a range of regions and historical moments. Students will then embark on their own research project related to a place and theme of their choice. In the end, the course will give students an insight into how Asian and Pacific societies variously responded to imperialism while also influencing the societies of the colonizer. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16268,2027,2358,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-277','<div class="desc"> <p>This course will survey ancient Mediterranean views about the catastrophic end of the world. We will study how ancient folks--Greeks, Romans, Jews, and Christians--interpreted disease, natural disasters (fires, floods, food shortage), political upheavals, and social unrest as signs of the end of the world. We will study how they altered their behaviors to anticipate the near end. And we will study their visions and fantasies of the utopian societies they hoped would emerge after the devastation. At the end of the course, students will conduct a staged research project on a topic of their choice. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16269,2027,1192,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-281','<div class="desc"> <p>This course explores religion and politics in the Americas through a study of the rise of the religious right. We will open by studying this movement’s historical antecedents, surveying how Christians from the colonial era to the present debated issues like religious establishment, immigration, and slavery and abolition. We will then learn about how industrial modernity prompted a crisis of faith among American Christians that led to the birth of Christian fundamentalism. Following that movement’s retreat at the apparent victory of liberal Protestantism, we will learn how fundamentalist Christians publicly reemerged with new political force at the end of the 1970s with Jerry Fallwell’s formation of the “Moral Majority.” In the final section of the course, we will take a hemispheric perspective, tracing the transnational networks of conservative Christianity that has fueled the rise of the political right in the United States and Latin America.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16270,2027,4375,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16271,2027,4376,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/rels-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16272,2027,361,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/200/resl-245','<div class="desc"> <p>A study of the religious traditions of the African diaspora in North America. We shall investigate the role of religion in Black culture and chart the development of the mainline Black Church. Islam religious traditions from the Caribbean Islands and new religions among African Americans will also be studied.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16273,2027,2815,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/300/rels-302','<div class="desc"> <p>This course asks: what is the ghost, and when does it take hold of the world? Through a series of case studies focusing especially on Latin America and North America—ranging from classical scholarship on Haitian vodou and Brazilian Candomblé to contemporary work on alien abductions and Cuban Santería—this course examines the category of spirit possession. In it we will take a look at the ways in which spirits are understood to possess people, haunt places, and inhabit objects. We will consider different scholarly interpretations of spirit’s saturation of matter, asking how these phenomena relate to the historical traumas inflicted by chattel slavery, colonialism, and economic inequality. Finally, we will interrogate the category of “spirit possession” itself, asking how the category might relate to regimes of property ownership and serve as a foil for the construction of the autonomous (i.e., self-possessed) modern subject.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16274,2027,4377,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/300/rels-335','<div class="desc"> <p>This course will use advanced methodological techniques to orient students to the relationship between media and religion in Asia. Historically, many Asian religions developed in close concert with forms of mediated and textual culture, from palm leaf manuscripts to enormous stone carvings of deities. Students will be introduced to pre-1800 manuscripts, statues, songs, paintings and other objects before they consider contemporary manifestations of these media. This course will consider how these historical media have developed into a considerable variation in the contemporary forms of media used to represent, promulgate, and critique religious traditions in Asia, as well as how the circulation of this media continues to create both community and division. Case studies will include Bollywood films from India that feature deities as lead characters, television shows that promote Confucian values from China, and online networks that promote connections between global Muslim communities.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16275,2027,1090,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/300/rels-351','<div class="desc"> <p>Folks in the ancient Mediterranean world were deeply invested in forms of sexuality that served the interests of Empire, of elite households, and of men. In the first unit of the course, we will investigate how these specific forms of sexuality were prioritized, incentivized, and regulated in society--namely, how art, medicine, law, and religion worked together to make them appear natural and normal. But when Christians came on the scene, they advocated a significant deviation from the dominant sexual ethics of the time. In the second unit of the course, we will study early Christians'' novel ascetic movement that understood sexless (even genderless) people to embody the ideal spiritual state, positioned at the pinnacle of humanity. In these next unit, students will be given the freedom to set the direction of the course. They will conduct a research project on a topic of ancient sexuality of their choice, presenting their findings to classmates. In the final unit, we will consider how sexual ethics of antiquity are still exerting influence on us, shaping contemporary sexual taboos, values, and regulative mechanisms. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16276,2027,3972,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/300/rels-393','<div class="desc"> <p>Research in an area that contributes new knowledge to the field of Religious Studies. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16277,2027,365,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/300/rels-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16278,2027,750,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/300/rels-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16279,2027,366,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/400/rels-490','<div class="desc"> <p>This seminar is offered in conjunction with Religious Studies majors'' ongoing research for the senior comprehensive project. Seminar meetings will be devoted to instruction on research and writing in the discipline of Religious Studies as well as discussion and critique of individual students'' work in progress. Open only to senior Religious Studies majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16280,2027,4378,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/400/rels-493','<div class="desc"> <p>Research in an area that contributes new knowledge to the field of Religious Studies at an advanced level. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16281,2027,4379,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/400/rels-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16282,2027,751,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rels-religious-studies/400/rels-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16283,2027,368,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/100/rusn-101','<div class="desc"> <p>Introduction to the structure of the Russian language with an emphasis on reading and verbal communication. Films and laboratory assignments complement in-class work. May not be taken for credit by those with more than one year of high school study (grades 10 11 12) or one semester of college study of Russian.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16284,2027,752,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/100/rusn-102','<div class="desc"> <p>Continuation of RUSN 101; emphasis on reading and conversation.</p> </div>','RUSN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16285,2027,4380,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/100/rusn-197','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16286,2027,369,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-201','<div class="desc"> <p>Development of reading skills through the use of original texts by Bulgakov Chekhov Pushkin and others; improvement of conversation skills accompanied by a review and expansion of grammar. Films and laboratory assignments complement in-class work.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16287,2027,753,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-202','<div class="desc"> <p>Continuation of RUSN 201 with emphasis on reading skills; readings by Gogol Chukovsky Shukshin and others.</p> </div>','RUSN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16288,2027,4000,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-203','<div class="desc"> <p>This course builds reading knowledge of literary Russian. The prerequisite is RUSN 102. This course complements and can be taken before or after the traditional RUSN 201 and 202 sequence. The specific objective of this course is reading and translating sophisticated literary and philosophical texts in Russian.</p> </div>','RUSN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16289,2027,4381,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-234','<div class="desc"> <p>Between 1800 and 1900 Russia went from a society without any real literature theater or art to a world leader in all three areas. This course follows the rapid evolution of Russian artistic output by examing the poetry of Pushkin the short stories of Gogol the novels of Dostoevsky and Tolstoy and the great plays of Chekhov. Russia''s evolution in visual art will also be examined through the masterpieces of Repin and others. Course taught in English; no knowledge of Russian required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16290,2027,2752,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-236','<div class="desc"> <p>If you are looking for straight, well-trodden roads, do not go to Eastern Europe. If, however, obscure and deviant paths attract you; if you are beginning to suspect that the direct route is neither the safest (Tarkovsky’s Stalker), nor the shortest; if you are ready to “go I know not whither and fetch I know not what” (Slavic fairy tale)—beware, for you might suddenly find yourself in Eastern Europe (or find Eastern Europe within you). In which case... you will need this guide. Our principal areas of concentration will be Slavic mythology, the Soviet-era critic Mikhail Bakhtin, and the <em>enfant terrible</em> of contemporary literary theory, psychoanalysis and pop culture Slavoj Zizek; yet we shall also be touching upon selected works from a number of other writers and film-makers:Dostoyevsky, Tarkovsky, Tsvetaeva, Skovoroda, Paradjanov, Mamardashvili, and DrakuliÄ).</p> <p>This course meets twice a week with CSLC 236, and for one additional 85 minute session per week, to develop Russian students'' intermediate language skills, specifically by reading and discussing works under consideration in the course taught in translation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16291,2027,4382,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16292,2027,4383,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/200/rusn-297','<div class="desc"> Independent study project. Permission of instructor and department chair required. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16293,2027,3326,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-330','<div class="desc"> <p>Do we live in the era of post-truth? Is everything just another piece of propaganda? Whom do we trust and why? </p> <p>Postmodern theory offers us powerful resources to criticize and take down the houses of totalizing ideologies, but many of its most important conceptual tools have been co-opted and are now used to oppress. Postmodern propaganda corrodes the relationships of trust that connect us, and makes us feel isolated and powerless. It taps into our fears and phobias to destroy not only the reality around us, but also our humanity. The organized lies of the 21st century aim to confuse and disorient, but also (and this is where the greatest danger lies) make us cynical. Several philosophers and writers from Eastern and Central Europe, who had first-hand experience of Western European “demi-Orientalism,” Russia’s imperialism, and Soviet totalitarianism, offer an antidote to this postmodern condition. </p> <p>In this course we will read French theorists, such as Deleuze and Derrida, and their counterparts from Eastern and Central Europe: Havel, MiÅosz, Mamardashvili, Venclova, and others. Several other philosophers and writers—such as Plato, Arendt, Kundera, Orwell, Klemperer, and Platonov—will help us think about truth, trust, and propaganda.</p> <p>This course will meet twice a week with CSLC 130, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from texts in the original Russian, such as Mamardashvili’s essays and Platonov’s stories.</p> <p>Students in this course are required to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second Stage writing requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16294,2027,1677,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-331','<div class="desc"> The worldview and beliefs of the early Slavs particularly the Eastern Slavs were a complex synthesis of influences: Indo-European mythology Central Asian shamanism Scythian animal worship and ultimately a paganized" version of Christianity labeled by cultural historians as "dvoeverie" (double faith). This course examines all aspects of this culture as it developed in the years 800-1600 in order to understand how these people viewed the world and how this affected their lives and the development of Slavic culture. Communal village life legends folk genres and mythology their sources and their legacies are examined. There is a close study of the phenomenon of the vampire following its evolution from the Iron Age into eighteenth century Serbia as a specific case study of how myths are born and persist. The ways in which pagan beliefs were incorporated into Christianity to create the "dual-faith" of the Russian peasant are examined as well. In addition to analytical and historical texts readings include tales of supernatural beings and phenomena as well as testimony concerning encounters with the supernatural." This section will deal with both texts in English and with texts in the original Russian. Texts include the "Tale of Warlord Dracula," "Olga''s Revenge on the Drevlians" and other early Russian stories. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16295,2027,1561,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-332','<div class="desc"> Many of Russia''s greatest writers used the genre of science fiction and fantasy to make bold political and philosophical statements while at the same time creating some of the most memorable texts of the twentieth century. This course will explore the works of the best of these writers: Yevgeny Zamyatin, Mikhail Bulgakov, Abram Tertz, the Strugatsky Brothers, and contemporary writer Victor Pelevin, using original Russian texts to examine the use of language in the creation of science fiction and fantasy texts. Additionally, film adaptations will be shown, including the avant garde film Aelita the Queen of Mars and Andrei Tarkovsky''s masterpiece, Stalker. The course only introduce students to modern Russian literature while at the same time examine how Russian writers used science fiction to criticize society and government. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16296,2027,1627,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-333','<div class="desc"> <p>There are two fundamental philosophical positions that try to describe our relation to others. The one posits that I am different from you. The other assumes the fundamental unity of human and other beings. Both of these positions lead to serious difficulties. If I am fundamentally different from you, I run the risk of alienation, and confront the impossibility of knowledge. If I begin with the assumption of oneness, I encounter the difficulty of distinguishing myself from you, and the impossibility of agency.</p> <p>Is there a third way that avoids both of these extremes? Could we re-imagine relationships between humans and nature in a way that preserves a sense of selfhood within a community of other beings? Eastern European folklore and mythology might help us in this task.</p> <p>In the course of the semester we will focus on the myths and folk tales from Eastern Europe. We will ground our discussion in the historical context of Scythian female warrior culture and some pre-Indo-European beliefs and practices. These cultural phenomena survive in the myths and epics of the Slavs. We will analyze representations and adaptations of these myths and practices in contemporary literature, film, and art from former Yugoslavia, Romania, Ukraine, and other Eastern European countries.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> <p>This course meets the Core Program Pre-1800s Requirement.</p> <p>Second-stage writing requirement: Students may satisfy the Second-Stage Writing Requirement by submitting a substantial (12-15 page) writing assignment that addresses a subset of the primary texts studied in this course. Students satisfy the Second Stage Writing Requirement by obtaining a grade of "C" or higher on this paper.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16297,2027,1740,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-334','<div class="desc"> How would you react to the nonsense poem "dyr bul shchyl," if you were a St. Petersburg pharmacist a century ago? What meaning would you apply to a wooden lapel spoon, face painting, declaration of "Victory over the Sun" and a brazen young poet''s call to "toss Pushkin from the steamship of modernity"? This course examines linguistic innovation and (explosive) destruction at the forefront of a violent artistic assault on bourgeois complacency known otherwise as the Russian Avant-garde. Topics include poetry, painting, dance, theater, graphics, industrial design, fashion, book-making, sculpture, cinema, architecture, fictional literature, and artistic manifesti, from Azbuka to Zangezi. </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16298,2027,3751,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-335','<div class="desc"> <p>Plato thought that all we need is a philosopher-king. What if he was only partially right, and what we actually need is a philosopher-buffoon? Jokes aside, what if critical thinking needs to be accompanied by laughter? And not just any laughter, but the kind that, following Mikhail Bakhtin, one would call carnivalesque.</p> <p>Carnival laughter exposes the grotesque aspect of human bodiesâeverything that is âugly, monstrous, hideous from the point of view of âclassicâ aestheticsâ of the ready-made and the completed. It liberates an individual body by revealing the ways it is open to the world around itâby emphasizing a bodyâs orifices and protruding parts. This laughter also revives and refreshes thinking by ridiculingâwithout destroyingâthe strict laws of rationality. Carnivalesque laughter is irreverent; it crosses the lines of what is socially, politically, and morally acceptable, and in so doing reveals the connections between myself and other beings.</p> <p>Bakhtin will provide the main theoretical framework for the course that will bring together literature and philosophy of Eastern Europeâthe works of Gogol, Zizek, Andrukhovych, and othersâto explore (and pervert?) the claims made above.</p> <p>This course will meet twice a week with CSLC 235, and for one additional 85 minute session per week to develop Russian studentsâ language skills. Students will have an opportunity to translate and discuss selections from texts in the original Russian, such as Bakhtinâs essays and Gogolâs stories.</p> <p>Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> <p>This course meets the Core Program Regional Focus (CPRF) Requirement.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16299,2027,2854,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-336','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. This course can be repeated for credit when taken as different topics.</p> <p><strong>Idiots, Atheists, and Nihilists</strong></p> <p>Many of the world''s greatest novels share one common feature—they were written in Russian. In this course we will discuss some of the key works of Russian literature, encountering revolutionaries and rebels, visionaries and superfluous human beings, holy fools and dandies. These characters will reveal a peculiar world, often remarkably different from that of 21st century Western culture, yet still strangely relevant to all of our most pressing concerns. In this five unit version of CSLC 136, we will be reading excerpts in the original language from Goncharov’s Oblomov, Turgenev’s Fathers and Sons, Dostoevsky’s Idiot. Students in this course will be asked to complete a 10-12 page interpretive paper, one that incorporates the students'' own translations of original texts. A passing grade of C or higher on this paper will satisfy the Second-Stage Writing Requirement.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16300,2027,2946,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-338','<div class="desc"> <p>Should you abandon yourself to the sensual beauty of the world? Or should you embrace a life of asceticism and simplicity? Is there an even more attractive path in between? Is it also a more difficult one? Major works by Russian writers—including Pushkin, Tolstoy, and Chekhov—will guide our discussions of these questions. This course will meet twice a week with CSLC 138, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from texts by Russian writers, especially Pushkin, Tolstoy, and Chekhov. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second-Stage Writing Requirement. </p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16301,2027,3217,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-339','<div class="desc"> <p>To become a human being I need something or somebody who is not altogether human. What or who might this be? Eastern Europe gives a provocative and profound answer: to become a human one needs demons. This idea can be found in the works of the majority of Eastern European writers, painters, composers, filmmakers, and philosophers. Every major Russian writer—including Pushkin, Lermontov, Tolstoy, Dostoyevsky, and Tsvetaeva—has at least one novel, poem, or essay entitled <em>Demons </em>or <em>The Devil</em>. The final film of Andrei Tarkovsky was originally entitled <em>The Witch</em>, and even the Ocean in his <em>Solaris </em>(based on Stanislav Lem’s science fiction novel) is endowed with demonic features. The demonic—at least in Eastern Europe—is a mirror, in which a person could find their true self.</p> <p>We will begin the semester by discussing the pagan beliefs and practices of the East Slavs that included a non-hierarchical and diverse pantheon of the so-called minor spirits that were more mischievous than evil, and frequently helped humans in their everyday tasks. We will then take a close look at several literary and cinematic works, in which the traces of this pagan worldview survive until our own times. These works might include novels, stories, and poems by Pushkin, Gogol, Lermontov, Tolstoy, Dostoyevsky, Chekhov, Tsvetaeva, Schulz, Lem, and films by Tarkovsky, Paradjanov, Sokurov, and Ilyenko. Several philosophers from Eastern Europe—such as Bakhtin, Florensky, and Rozanov—will guide us in this impish inquiry. </p> <p>This class will meet simultaneously with CSLC 139 twice a week, and then meet for an additional 90 minute session to read selections of the above works in the original. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16302,2027,1490,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-340','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">The course will critically examine philosophical ideas about humans, animals, and machines. We will think about the current stage of technological developmentâthe ways in which contemporary technologies both expand and interrupt what it means to be human. We will focus on several key concepts of Gilles Deleuze and FÃ©lix Guattari (including becoming-animal, lines of flight, and reterritorialization). Our discussions will situate these concepts in the context of past and ongoing posthumanist debates, placing them alongside the contributions of contemporary philosophers, such as Bernard Stiegler and Catherine Malabou. The plays and short stories of Anton Chekhov will help chart outânot so much the lines of flight, as footpaths for slower becomings and futures. </span></p><p dir="ltr" style="line-height: 1.38; margin-top: 0; margin-bottom: 0"><span style="font-size: 12pt">This course will meet twice a week with CSLC 230, and for one additional 85 minute session per week to develop Russian studentsâ language skills. Students will have an opportunity to translate and discuss selections from Anton Chekhovâs stories and plays in the original Russian. </span>Students who complete the final paper for this course, with a grade of C or higher, can use this work to satisfy the second-stage writing requirement.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16303,2027,4384,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-375','<div class="desc"> <p>Two intimately related schools of literary analysis from the early 20th Century Russian Formalism and Prague Structuralism staked out fundamentally new theoretical terrain by isolating the functional elements of verbal artistry as discrete objects of rigorous inquiry. Their works merit close inspection as representative of a big bang in theory and cultures of binary encoding that continues to expand and proliferate to thisday subsuming the visual arts music cinema broadcast media digital computation the cognitive sciences and espionage. This course traces lines and shifts in the intellectual history of this brief moment through close reading of selected works and situates theory in the biographies and broader social cultural and political contexts of its key figures.Course taught in English; no knowledge of Russian required.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16304,2027,3179,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-395','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>To be: Ukranian</strong></p> <p>Ukraine’s rich poetic and revolutionary culture helps one trace routes of escape from oppressive imperial structures. Philosophical and literary texts written by and about Ukrainians will allow us to gain an understanding of this culture, and the works by contemporary historians will help us develop an understanding of Ukraine’s tumultuous history. Philosophers, writers, and historians could include Svetlana Alexievich, Anne Appelbaum, Ivan Kotlyarevsky, Alexander Potebnja, Mykola Riabchuk, Timothy Snyder, Lesia Ukrainka, Oksana Zabuzhko, Serhiy Zhadan, and others. No previous knowledge of the Ukrainian language or literature is required. Russian 330 will meet twice a week with CSLC 130, and for one additional 85 minute session per week to develop Russian students’ language skills. Students will have an opportunity to translate and discuss selections from literary and philosophical texts in the original Russian. Students completing the final paper in this course with a grade of C or higher can use this work to satisfy the Second Stage Writing requirement. Core Requirement Met: Regional Focus.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16305,2027,754,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/300/rusn-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>','RUSN 202 or by instructor permission ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16306,2027,4385,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/rusn-russian/400/rusn-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16307,2027,371,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/100/soc-101','<div class="desc"> <p>This course introduces students to the sociological imaginationâa way of understanding events, relationships, and social phenomena that shape our lives and history. Through a critical evaluation of the theoretical propositions of thinkers in the field, we will explore how people are shaped by society and, in turn, shape it. Students will write papers that articulate an original thesis with supporting evidence, deepening their grasp of how sociology helps us interpret the dynamics of social order and disorder. <em>Open only to frosh and sophomores, or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16308,2027,2700,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/100/soc-102','<div class="desc"> <p>This course adopts a global perspective to introduce students to sociology, the scientific study of societies. It will examine the self, socialization, social ties, social interaction, social institutions, and social change, considering both conformity and deviance. Students will leave with a "sociological imagination," the ability to see their own lives and the lives of others in the context of their wider societies and an increasingly interconnected world. Through a critical evaluation of the theoretical propositions of thinkers in the field, we will explore how people are shaped by society and, in turn, shape it. Students will write papers that articulate an original thesis with supporting evidence, deepening their grasp of how sociology helps us interpret the dynamics of social order and disorder. <em>Open only to frosh and sophomores, or by permission of instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16309,2027,879,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/100/soc-105','<div class="desc"> Through a critical evaluation of the theoretical propositions of thinkers in the field, we examine the role of youth cultures in the identity formation of immigrant adolescent youth residing in the Southwest region of the United States. Particular attention is paid to: (1) theories of acculturation and assimilation used to analyze the experiences of immigrant youth; (2) the impact of geographical location, social class, gender, race, sexuality, popular culture, mass media, and technology; and (3) the intersection of youth cultures, home cultures, and mainstream society. Students will write papers that articulate an original thesis with supporting evidence. This course is part of the California Immigration Semester, and enrollment is open only to first-year students. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16310,2027,755,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/100/soc-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16311,2027,3234,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/copy-of-soc-211','<div class="desc"> <p>Cultural production is central to the struggle for human rights. As cultural artifacts both conceptualize and memorialize social-political trauma, our class will take a close look at the way that Mexican film, literature and music represents both criminal and state violence. For comparative purposes, we will also look at some documentaries or film about the current violent situation in Central America. As this is a 4-unit course, you should expect to spend at least twelve (12) hours a week (including in-class time) on this course. </p> <p><strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico (as well as Central America) through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16312,2027,1491,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-200','<div class="desc"> <p>The course is on sociologyâs formative schools of thought. Karl Marx, Max Weber and Emile Durkheim not only founded the field of Sociology in the 19th century, their theories continue to influence contemporary thought about social relations. Through lecture and discussion we examine their general theories before we critically evaluate their concrete claims about capitalist development or âmodernization,â the state, social science and social change. Learning Outcomes: Students will learn to critically evaluate the theoretical propositions of thinkers in the field. They will also write papers that articulate an original thesis with supporting evidence.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16313,2027,372,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-205','<div class="desc"> <p>This course introduces the most influential sociological paradigms of the 20<sup>th</sup> and 21<sup>st</sup> century. These include the structural-functionalist paradigm, rational choice theory, various neo-Marxist theories (for example âworld systems,â âglobalizationâ or the âFrankfurt schoolâs critical theoryâ), as well as the symbolic interactionist paradigm. I will introduce postmodernist theory, as well as works from Giorgio Agamben and Achille Mbemebe. <strong><em>Learning Outcomes:</em></strong> Students will learn to critically evaluate the theoretical propositions of thinkers in the field. They will also write papers that articulate an original thesis with supporting evidence.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16314,2027,3872,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-207','<div class="desc"> <p>This course will examine contemporary economic, political and social conditions of women workers across the Americas. We will analyze the ways in which US-Latina and Latin American women navigate and resist hierarchical power relations in the globalized labor market. How processes of globalization, transnationalism, work, and family shape womenâs lives are integral to this course. This course will expand the field of labor inquiry to include both productive and reproductive labors. This includes the unpaid âcaringâ work of childcare, housekeeping, and the maintenance of critical community networks. We will consider both the consequences of the sexual division of labor between those considered women and those classified as men but also focus on race, class, sexuality, nationality/citizenship, and other markers of differences. In these contexts, we will explore issues such as development, im/migration and construction of the woman worker to illuminate the gender of political economy and the political economy of gender. Finally, we will analyze struggles for <em>pan con dignidad </em>(dignity and daily bread), the place of affect in organizing, and the prospects for social justice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16315,2027,1492,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-210','<div class="desc"> <p>After Mexico''s transition to electoral democracy in 2000 two alternative party (PAN) Presidents either failed to act in accordance with the transitional justice movements sweeping Latin America, or actually returned to mano dura (heavy-handed) military practices to deal with the drug cartels. Consequently, as compared to South American countries, human rights violations in Mexico have increased rather than decreased since its transition to democracy. This class will document why this is the case as well as look into the various movements that have mobilized since the 1970s to the present to demand human rights in Mexico. This class will also look at the violence committed by transnational criminal organizations as well as how ordinary people attempt to create security for their communities.</p> </div>','DWA 101 , LLAS 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16316,2027,1562,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-215','<div class="desc"> <p>Who are you? Why are you? How do you know? Surely you have heard the phrase "nature vs. nurture." It is about the ongoing quest to figure out how much of a human is genetic, biological, and chromosomal (nature), and how much is a product of socialization (nurture). To what extent are you your society? To even consider that question, we must examine the society itself, the individuals that produce it, and how the two are connected. The society and selves we will be examining are our own -- in particular, the society and selves of young Americans. How does the world you''re facing today make you who you are? How do the technology and media through which you learn about your world permeate, shape, and structure your everyday experience of self and society? Who do you want to be, who will you end up being, and what kind of world will you create?</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16317,2027,3307,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-218','<div class="desc"> <p>Over fifty years ago, the first person in the U.S. hired to coordinate a Black Studies program, Nathan Hare (1970), published an essay titled, ‘‘Black Ecology,’’ in which he argued that it was imperative that we come to ‘‘understand how both the physical and social environments of blacks and whites have increasingly evolved as contrast.’’ Since then, many scholars from across the social sciences and humanities have contributed to this endeavor. This emergent field of Black ecological thought is important because it provides insight about race and the environment from the perspective of Black study. In this survey course, we will study a range of black ecological thinkers and the concepts that they offer for understanding contemporary environmental issues.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16318,2027,4044,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-220','<div class="desc"> <p>This course examines the social, economic, and political factors that contribute to unequal health outcomes across different populations. Through a sociological lens, students will explore how race, class, gender, geography, and other social determinants shape access to healthcare, health behaviors, and overall well-being. The course will analyze structural inequalities, such as systemic racism and economic inequality, as well as policies and practices that perpetuate health disparities. Case studies and contemporary examples, including the COVID-19 pandemic, will be used to understand how power and privilege influence health outcomes globally and locally. Students will engage in critical discussions on potential solutions, emphasizing equity-focused interventions and public health strategies. By the end of the course, students will be equipped to analyze health disparities and advocate for more just and inclusive health systems.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16319,2027,4386,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-221','<div class="desc"> <p>This 2-unit course focuses on how emigration/migration from Mexico and Central America is represented in film. Before each in-class film showing, students will have read sociological analyses on the socio-economic and political conditions leading to emigration, or to the urgent exodus, from these countries beginning in the 1980s. We will also study film and sociological readings on the reception of Mexicans and Central Americans in the United States. For comparative purposes, we will examine some works on the U.S. reception of immigrants from Latin America, including Spanish-speaking caribeÃ±os. The value of learning about the socio-economic and political processes involved in the mass displacement of people through film is that students will learn about such human experiences and their contexts (that is, multiple interacting variables through time and space) in three-dimensional ways. As this is a 2-unit course, students should expect to invest at least six hours a week (including in-class time). <strong>Learning outcome(s)</strong>: Students will learn about the contemporary humanitarian crisis in Mexico and Central America through a critical analysis of cultural artifacts.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16320,2027,1628,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-225','<div class="desc"> <p>This course examines the construction and reproduction of masculinities primarily in the United States. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16321,2027,4387,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-226','<div class="desc"> <div><div><p>This course examines the construction and reproduction of masculinities primarily in Latina/o and Latin American communities. We explore the impact these gendered identities have on individual''s lives and social interactions. Consideration will be given to the intersection of ethnicity, race, class, age, sexual orientation, and gender and the role of social institutions and inequities in the social construction of masculinities.</p></div></div> </div>','SOC 101 or SOC 102 or SOC 105 or LLAS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16322,2027,1316,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-230','<div class="desc"> <p>This course examines the family as a social institution in the United States. The course emphasizes sociological and demographic perspectives on the family family change historically and contemporarily and the intersection of the family with social categories such as race and ethnicity sexual orientation gender and class. The course will highlight contemporary changes in marriage divorce and non-marital cohabitation in the United States but will also expose students to sociological thinking about family systems around the world.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16323,2027,1629,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-235','<div class="desc"> <p>This course explores sport as a key social institution through which power, identity, and inequality are produced, contested, and negotiated. Using sociological theory and empirical research, we examine how sport intersects with systems of race, class, gender, sexuality, and nationhood—both reflecting and reshaping dominant ideologies—in the United States.</p> <p>Students will engage with sport as a site of cultural meaning and social struggle, analyzing topics such as athlete labor, educational institutions, media representation, and global sport industries. We pay particular attention to how marginalized communities navigate and challenge exclusion within athletic spaces, and how sport is mobilized in the service of both social control and collective resistance.</p> <p>Class sessions incorporate case studies, media critique, and contemporary examples—from high school athletics to global mega-events. This course is ideal for students seeking a deeper understanding of sport beyond the scoreboard.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16324,2027,756,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-240','<div class="desc"> <p>This course examines the social relations surrounding the production distribution preparation and consumption of food. In doing so we will try to understand how the issues and problems of daily life reflect larger social forces and how our understanding and actions shape the social world. This means that we will treat several major questions facing sociology today including inequalities and identities based on national racial/ethnic class and gender positions; work and family; the environment; globalization; and cultural change. By the end of the course you will be able to critically examine and evaluate the connections between food culture and society.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16325,2027,373,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-245','<div class="desc"> <p>This course examines the individual cultural and structural explanations for the presence and persistence of income and wealth inequality in the U.S. The impact of inequality on social groups and the social policies developed to curtail poverty are also considered.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16326,2027,979,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-250','<div class="desc"> <p>This course provides a basic sociological understanding of relations among racial and ethnic groups in the United States. A sociological approach includes considering race and ethnicity as social constructs that permeate all social life are entrenched in social structures and institutions and shift and mutate over time and place. Such a perspective suggests that (1) race and racism are not merely the ''problems'' of/for subordinate racial and ethnic groups but are reflective of society-wide power relationships that deeply affect all of us on a daily basis (2) that racial and ethnic categories - including ''white'' - can be viewed usefully as the result of historical struggles over economic resources political access and cultural identity rather than as objective measures of biological difference and (3) the institutional forms of racism indelibly etched into this nation''s past did not end with civil rights legislation of the 1960s but continue to shape social institutions today.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16327,2027,4426,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-253','<div class="desc"> <p>In this course, we will examine the lives of 1.5 and second generation immigrant youth in the United States since the 1920s, with particular attention on identity formation and youth cultures in the present day. Throughout the semester, students will read empirical studies about immigrant youth with cultural ties to numerous countries, especially countries in the Americas and Asia. Students will learn about: (1) the theories of acculturation and assimilation sociologists use to analyze the experiences of immigrant youth; (2) immigrant youth from different immigrant communities; (3) how geographical location, social class, gender, race/ethnicity, sexuality, immigration status, popular culture, mass media, and technology inform the identity construction of immigrant youth. Students will write papers that articulate an original thesis with supporting evidence.</p> </div>','SOC 101 or SOC 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16328,2027,4388,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-257','<div class="desc"> <div><div><p>This course uses a sociological perspective to examine how youth in societies throughout the world draw on their social contexts and local resources to make globalized youth cultures their own. Among the local youth cultures studied are street skateboarding, hip hop, and punk.</p></div></div> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16329,2027,1092,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-260','<div class="desc"> <p>In this course we will focus on sociological theories of deviance with an emphasis on how behaviors and identities are socially constructed as deviant (both today and historically). We will then turn our attention to major forms of deviance as typically defined in Western societies: criminal deviance "victimless crimes" and individuals with stigmatized identities. Throughout the course we will work to understand the complex relationship between social actors and audiences in defining deviance; the nature of social control in responding to deviance; and the experiences of "deviant" individuals.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16330,2027,3344,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-263','<div class="desc"> <p>W.E.B. (William Edward Burghardt) Du Bois, was a prolific scholar, writer, and social/political analyst and organizer. Over the course of his lifetime, Du Bois wrote over 2000 bibliographical entries, across a range of genres, including: research monographs, plays, pamphlets, autobiography and biography, history, novels, poems, and popular press articles. At the same time, Du Bois utilized multiple methods, forms of data and evidence, and literary styles within and across texts. Nevertheless, in the domain of social science, and sociology more specifically, his work was intentionally marginalized. Yet while Du Bois was made a minor figure in American social science, he was a primary progenitor of the transdisciplinary field of Black, African American, or Africana studies and thus played a foundational role in circumventing the racial-colonial order of knowledge by attending to Black life and sociality. In this course, we will study the social theory of Du Bois by reading texts from across his vast corpus—from his more formally social scientific writing and data visualizations to his creative projects like poetry and short stories. For the final project of the course, students will deploy a Du Boisian approach to social theory and analysis using more expressive forms (such as illustration, painting, film and video, poetry, music, photography, data visualization, short stories, or lyrical essays).</p> <p>*This course cannot substitute for the theory requirement (SOC 200 or SOC 205) for Sociology majors.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16331,2027,374,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-265','<div class="desc"> <p>In this course we will critically examine the ways gender informs the social world in which we live. Our goals for this course will be 1) to reveal the "common-sense" world of gender around you; 2) to consider how we learn to "do" gender; 3) to expose the workings of the institutions that shape our gendered lives; and 4) to come to an understanding of the relationship between gender and the social structure.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16332,2027,2360,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-270','<div class="desc"> <p>What are the effects of urbanism on human psychology and civic life? How does urbanization structure social and economic relations as well as signifying identities and cultural meanings? Is there a common "human ecology" of cities in "natural areas" such as the CBD skid row the "Tenderloin" or the "zone-in-transition"? We examine the urban underclass through case studies of the African American ghetto and Spanish Harlem with attention to public policy perspectives on urban poverty. Urban futures are considered through gentrification growth machine boosterism (sports and convention centers) and urban theme parking.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16333,2027,3259,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-275','<div class="desc"> <p>People in the U.S. struggle every day to get the care they need. Why, in such a wealthy country, do so many go without healthcare, eldercare, childcare, food, housing, and more? This course surveys, from a comparative-historical perspective, social welfare provision in the United States. We dissect debates about the value of welfare and explore the implications of various arrangements between civil society, the market, and the state. In so doing, we consider critical race, Marxist, and feminist theories of social welfare as a tool of racial, economic, and gender power. Students use theoretical lenses developed in class to assess contemporary welfare policy interventions.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16334,2027,3235,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-281','<div class="desc"> <p>This course introduces the field of criminology. The course is designed to provide a broad understanding of the etiology of crime (i.e. what causes crime?) the measurement of crime and theories of criminal punishment. We will also discuss a wide range of criminal behaviors with a focus on violent crime and property crime (e.g. homicide sexual assault shoplifting white collar crime etc.). The final component of the course focuses on the American criminal justice system. This course emphasizes a sociological approach to understanding crime criminal behavior and criminal justice.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16335,2027,1093,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-285','<div class="desc"> <p>The relationship between humans and the non-human environment is complex and problematic. We are part of and dependent upon the natural environment even while altering that environment for our own needs and purposes. As a way of broadly thinking about these interactions we will address the social causes consequences and responses to environmental disruption. By the end of the course you will be more adept at understanding how societal characteristics -- including cultures traditions beliefs values institutions and the like -- combine with environmental conditions to shape the impact that people have on their environments.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16336,2027,1741,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-290','<div class="desc"> <p>This course is an introduction to sociological analyses of the economy, economic processes, and economic institutions. The central focus is to understand how beliefs, norms, cultures, social relations, and institutions shape our economic lives. We will also explore how the theoretical and methodological approaches of sociology differ from those orienting the discipline of economics, as well as what is at stake in these differences. By the end of the course, you will be familiar with the key approaches in economic sociology, and will be able to use a sociological lens to examine the economy.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16337,2027,1194,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-295','<div class="desc"> <p>Topics vary semester to semester. Specific topics may satisfy different Core Program requirements.</p> <p><strong>Poverty and Inequality in America</strong><br/> <br/> This course will examine why the U.S. has more poverty and more inequality than any other wealthy nation -- and what we can do about it. The course will include class discussion, readings, and films. Among the topics we''ll discuss are: Who benefits and who suffers from America''s high of poverty and inequality? Should our society try to significantly reduce poverty and inequality? If so, what can we do? Who is poor in America? Who is super-wealthy? Who is middle class? What are the major stereotypes about the lives of the poor and the super-wealthy? How have issues of race, gender, and immigration influenced the level of poverty? Why are poor, middle class, and wealthy people in America concentrated in certain locations - more so than in other wealthy societies? Has government policy made poverty and inequality better or worse? What political movements and policy reforms have made a difference in improving the lives, and reducing the number, of America''s poor? How can poor Americans and their allies influence politics and policy?<br/> <br/> Students who want to get a head start on the readings should read Barbara Ehrenreich''s book, "Nickel and Dimed: On (Not) Getting By in America."<br/> <br/> This topic is cross listed with UEP 295.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16338,2027,4389,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/200/soc-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16339,2027,4410,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/copy-of-soc-393','<div class="desc"> <p>Students working with department faculty on original research for a minimum of six hours per week may enroll in this course. The student and faculty will be meet weekly or twice per week for data analysis and framing. Students will work independently the remainder of the time. Instructor permission is required. Graded on Credit/No Credit basis only.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16340,2027,375,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-304','<div class="desc"> <p>This course looks at the ways sociologists collect information about social phenomena with a special emphasis on what can be done to yield information that is trustworthy and useful for our theoretical understanding of social life. It assumes no background in research methods or statistics. We will talk about the scientific method the complexities of applying methods to social research ethics and bias and research design. You will be given an overview of major "quantitative" and "qualitative" methodologies including surveys interviews ethnography experiments participant observation or content analysis.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16341,2027,757,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-305','<div class="desc"> <p>This course introduces quantitative research methods and statistical analysis from a social science perspective. We will address the major components of the research process and will stress the importance of critical thinking in all matters numerical. We will cover measures of central tendency the normal curve probability frequency distributions correlation and regression. We will also talk about statistics and statistical reasoning in the media. By the end of the course you will have mastered basic statistical concepts and techniques and will be able to critically examine and evaluate the (mis)use of these concepts.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16342,2027,1563,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-306','<div class="desc"> <p>This course introduces qualitative research methods from a social science perspective. We will cover systematic qualitative research design, data collection and analysis. Techniques will include interviewing, focus groups, ethnography, and/or qualitative content analysis. By the end of the course you will have mastered basic concepts and techniques and be able to carry out basic qualitative research, resulting in a paper that uses your data as evidence to support and articulate an original thesis.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16343,2027,1493,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-310','<div class="desc"> <p>On the surface, music can appear to be a non-consequential element of life and/or an individualized phenomenon. In fact, the production and consumption of music is a social process and thus plays an imperative role in the social world. Music shapes and structures how we interact as groups and individuals, who we are intimately connected to, and reflects and reinforces many of our core social institutionsâlike religion and politicsâas well as meaningful social distinctions â like race, class, and gender.</p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16344,2027,1094,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-315','<div class="desc"> <p>This course uses different sociological perspectives to examine social aspects of schooling and educational institutions in the U.S. Specifically the course focuses on factors that may impede and/or facilitate learning such as social class gender race and ethnicity teacher and parental expectations and peers. Additionally the role of education in the acculturation and assimilation process is considered as are the ways in which schools ameliorate and/or replicate social inequalities.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16345,2027,1353,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-320','<div class="desc"> <p>This course surveys sociological theories of health illness and medicine. Rather than focusing on the individual body as the site of disease the course examines the role of social context in shaping health and access to the healthcare system across population groups. The course focuses especially on medical intervention and the medicalization of disease social disparities in health and contemporary healthcare changes and challenges in the United States.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16346,2027,2605,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-321','<div class="desc"> <p>This course will survey the major analytic approaches concerning Mexican immigration to the United States. We will look at the causes and consequences of such immigration from the standpoint of binational economic integration. We will also examine Central American immigration from an international relations perspective.</p> </div>','SOC 101 , SOC 102 , SOC 105 , LLAS 101 , or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16347,2027,3873,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-322','<div class="desc"> <p>Central American feminisms have been an integral dimension to struggles against imperialism, dictatorship, and globalization across the Isthmus. This course will examine the development of Central American feminisms beginning with the revolutionary period of the 1970s and 80s up to the present. We will explore feminist epistemologies and cultures of resistance, looking at how feminists make interventions through artistic practices. We will examine the transnational dimension of feminist organizing in the region, looking at how shared histories and dialogues shape how Central American women theorize about feminism through their lived experiences. To do so, we will study critical texts written by feminist writers and collectives, historical testimonios as well as feminist cultural productions such as music and art. We will also explore how global discourses touch down and shape Central American womenâs political claims as well as how Central American feminists influence international organizations and global conceptions of human rights. Topics we will explore include contemporary regional histories and womenâs roles in social change, gendered violence and femicide, reproductive rights, memory and artivism, and motherhood as a political identity.</p> </div>','LLAS 101 or SOC 101 or HIST 151 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16348,2027,2361,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-323','<div class="desc"> <p>This course explores the sociological analysis of law, focused on the legal construction of social "groups," the moral regulation of social action, and the formal legitimization of state practices. The course is divided into two sections. The first half of the course examines theoretical approaches to the sociology of law drawing on the works of Max Weber, Niklas Luhmann, Jürgen Habermas, and Pierre Bourdieu, as well as perspectives rooted in Marxism, feminism, and critical race theory. The second half of the course focuses on contemporary legal controversies in the United States, including racial disparities in criminal justice, undocumented immigration, the regulation of sexuality, and the criminalization of political dissent and protest.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16349,2027,3260,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-326','<div class="desc"> <p>Why does the United States incarcerate more of its population than any other nation in the world? Why does death by injection seem kinder and gentler-and thus more acceptable-than public hangings of the past? What are the consequences for justice and democracy in an era of unprecedented confinement and correctional supervision? Using various historical, legal, and sociological perspectives we will focus on questions such as these with an emphasis on: the cultural life of punishment and crime control as a political issue, the racial and class dynamics of punishment, and inequality and contemporary issues surrounding modern penal sanctioning (e.g. mass incarceration) and its consequences. </p> </div>','SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16350,2027,377,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-330','<div class="desc"> <p>This course will focus on classical and contemporary theories of power and authority; theories of the state and various forms of state power the state and government the nature of democracy and political elites in modern society (especially the United States) as well as the social bases of political parties and voting behavior.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16351,2027,4390,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-334','<div class="desc"> <p>This course critically examines technology as a social phenomenon rather than a neutral tool. We will approach technology through three guiding questions: 1) What counts as technology, and what forms of agency do technologies have (or lack)?; 2) How does technology reflect and shape identity, social interaction, social structures, and systems of inequality?; And 3) What role does technology play in sustaining or transforming institutions and social change? Drawing on sociological theories of technology, inequality, and culture, we will analyze how technologies are designed, adopted, and contested across different contexts. By the end of the course, you will be equipped to interrogate the sociologically complex and multifaceted relationship between humans and technology.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16352,2027,1564,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-340','<div class="desc"> <p>China''s Environmental Challenges: A Sociological Perspective This course examines China’s environmental challenges and the policies and institutions that have an impact on those challenges. This course is divided into three parts. The first part guides student through a brief introduction of China’s political system and its recent environmental history. The second part delves into specific environmental issues ranging from air pollution, food, urbanization, biodiversity, and climate change. The last part considers China''s environmental challenges through the lens of environmental governance, focusing on the roles of the central state, local governments, businesses, NGOs, and other international institutions. To deal with such a complex topic, this course will draw insights across disciplines from political science, human geography, history, urban studies, to China studies, but we will especially use sociology to conceptualize China''s environmental ills as a deeper challenge to organize societies with sustainability. Cross-listed with East Asian Studies and Urban and Environmental Policy.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16353,2027,4391,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-345','<div class="desc"> <p>This course examines reproduction as a social process that is not only tied to biology, but also to the value placed on different bodies in society. It introduces students to empirical research and theory on a range of reproductive experiences, elucidating the social forces that fundamentally shape understandings and outcomes in each domain.</p> </div>','SOC 101, SOC 102, or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16354,2027,758,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-350','<div class="desc"> <p>This course examines why people protest for social change. We will examine the theoretical debates about the determinants of insurgency by focusing on the following models: the collective behavior the resource mobilization the political process as well as the cultural approach. We will also examine the theoretical debates on the extent to which social movements can be credited with political change. Your study of these theories will expose you to several case studies of real social movements in the United States Europe and Latin America. This is however a theory (not a history) course.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16355,2027,759,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-355','<div class="desc"> <p>This course will consider the role that sexuality plays in the American imagination especially the way that sexuality is constructed and serves as a mechanism of social control. In doing so special attention will be paid to the ways in which human sexuality intertwines with axes of power in contemporary America such as race ethnicity gender class and sexual orientation.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16356,2027,2890,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-361','<div class="desc"> <p>This class examines racism in the U.S. and globally through the lens of power. We will explore how whiteness shapes institutions, politics, pop culture, social media, technology, and identity as well as how it intersects with other systems like gender, class, and citizenship. We will also consider what it looks like to dismantle these systems for a more just and equitable society.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16357,2027,761,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-365','<div class="desc"> <p>The course will examine how mass communication systems such as radio television cinema and the Internet are produced and what they signify and represent of the social world and public life. We consider the relationship of the mass media to big business and the structure of capitalism. The ideological influences of the mass media are interrogated through concepts such as "mass culture" and "subculture". We examine how contemporary culture and everyday life are increasingly commodified through the systems and spectacles of consumption capitalism. How has globalization affected consumerism and the social construction of the contemporary self?</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16358,2027,1354,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-370','<div class="desc"> <p>This course examines the social phenomenon of human violence. We first consider classical and contemporary sociological theories on violence and violent conflicts and the main sociological definitions of violence used over the last century. We then turn to empirical studies that explore the social processes and societal structures that give rise to the various forms of violence-intrapersonal interpersonal familial collective and political-and nonviolent movements presently observed throughout the world.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16359,2027,762,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-375','<div class="desc"> <p>This course examines the political economic and cultural changes that occur as societies shift from the traditional to the modern. Why are some nations mired in debt and dependency while others have become successful "newly-industrializing countries?" We consider leading intergovernmental organizations of the global economy such as the IMF World Bank and WTO. We investigate scenarios in cultural globalization including Americanization hybridization and fundamentalism. We consider intersectional social dynamics that disenfranchise the most powerless including women children indigenous and stateless peoples.</p> </div>','SOC 101 , SOC 102 , SOC 105 , or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16360,2027,1426,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-380','<div class="desc"> <p>This course examines disaster as a social phenomenon and broader trends in managing calculating and responding to a variety of threats and catastrophes. We will focus on the history of disaster response and policy in the U.S. theories of reflexive modernity risk and trauma and cultural responses to calamity in California and in the U.S.more broadly. Case studies include Hurricane Katrina the BP Deepwater Horizon oil spill Fukushima and outbreaks of whooping cough and Ebola.</p> </div>','SOC 101 , SOC 102 or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16361,2027,1631,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-390','<div class="desc"> <p>This course offers a survey of sociological approaches to the study of religious beliefs practices and organizations in the United States in public and private life. Exceptionally devout among developed nations the U.S. is a nation of remarkable religious diversity. We will examine the relationship between religion politics and civic life; recent trends in American religion (the "new atheism" problems of pluralism secularization and declines in religious participation the rise of evangelicalism and fundamentalisms religious conflicts); as well as theoretical arguments both classical and contemporary about the role of religion in scientifically advanced modern societies. Whereas much public debate frames religion as either a unambiguously beneficial public good or else as a font of irrationality and sectarian division we will move beyond this dichotomy toward a more empirically informed consideration of just what religion is and does in the contemporary United States.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16362,2027,1040,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-395','<div class="desc"> <p>This course will function as an advanced seminar focusing on the research interests of the Sociology Department''s faculty. Topics vary.</p> <p><strong>Science, Technology, &amp; Justice: The Making of “Modern” Families</strong></p> <p>Does reproductive justice include a right to bear children using technological means? What about using 3<sup>rd</sup> parties like egg and sperm donors? Are reproductive technologies expanding definitions of family or reinforcing race, class, and gender inequalities? This upper-division seminar will examine reproduction from a social justice perspective, with particular attention to how the politics of reproduction are shaped by the intersecting inequalities of gender, race, class, dis/ability, and sexuality. Reproduction is not only a biological process; it is a battleground of social and political struggle. The course will familiarize students with foundational academic and activist approaches to reproduction. Students will learn about the history of and differences between reproductive rights and reproductive justice movements. We will then look at the new questions and challenges reproductive technologies raise for social justice. Cross Listed as UEP 395.</p> <p><strong>Policing, Power, and Violence</strong></p> <p>In this course, we will examine policing in the United States from the repression of Indigenous and enslaved peoples in the 18th century to the militarization of policing on the streets and the U.S.-Mexico border today. Using sociological understandings of power, we will analyze the judicial and extrajudicial violence that law enforcement agents engage in and how such violence serves to maintain the unjust and unequal social order. The course will close with us considering arguments for and against the abolition of police forces and prisons.</p> <p><strong>Sociology of the Southern U.S.</strong></p> <p>What, and where, is the South? Who is a southerner? What do they do down there, and why do they do what they do? Are the South and southerners still distinctive? By looking at all aspects of Southern life this course will unravel the enigma of the region while pondering a more inclusive and nuanced appreciation of "many Souths" and "southern cultures" including senses of regional identity and allegiance, and in representations of, and cultural stereotypes from and about, the South. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> <p><strong>Visualizing Gentrification: Bridging Land Use Data and Ethnography</strong></p> <p>Students are challenged with the myths and realities of gentrification in an immersive discussion. The proposed course weaves urban planning, mapping and data research with qualitative analysis to recognize gentrification drivers, examine the pending experiential trauma of displacement and the community''s aspirations and resistance. The course examines the communities of Northeast Los Angeles as they face three colossal planning projects that utilize gentrification as a catalyst and justification for their development.</p> <p>In a holistic examination of the landscape, course participants will embed with community and other partners to explore the social networks and their relationship to research data. Course discussions will include developing metrics from an activist and documentary perspective to establish the observable community. Students will operate in small teams in developing data and fostering outcomes that reveal the human narrative. They can be visual in nature from ethnographic studies to data visualization, but also critical analysis and policy recommendations of the conditions on the ground. <em>Core Program Requirement Met: United States Diversity</em> <em>(CPUD)</em>.</p> </div>','SOC 101 , SOC 102 , or SOC 105 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16363,2027,763,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/300/soc-397','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16364,2027,378,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/400/soc-490','<div class="desc"> <p>Seminar is offered in conjunction with sociology majors'' ongoing library research for the senior thesis. Seminar meetings will be devoted to discussion and critique of work in progress. We strongly encourage students to have taken Classic or Contemporary Theory Sociological Inquiry and Qualitative Quantitative or Field Methods before taking the senior seminar (always taught in the Fall). <em>Open only to senior Sociology majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16365,2027,4392,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/400/soc-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16366,2027,764,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/soc-sociology/400/soc-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16367,2027,4393,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/copy-of-span-193','<div class="desc"> <div><p>Intensive study in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16368,2027,380,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/span-101','<div class="desc"> <p>A communicative approach to the Spanish language. Emphasis is placed on the four skills of speaking, listening, reading, and writing, as well as grammar, with a particular focus on the cultures of the Spanish-speaking world. <em>Students who have had more than one year of Spanish in high school or more than one quarter in college may not take this course for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16369,2027,381,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/span-102','<div class="desc"> <p>This course is a continuation of SPAN 101, a communicative approach to the Spanish language, and expands on the four skills of speaking, listening, reading, and writing, as well as grammar, with a particular focus on the cultures of the Spanish-speaking world.</p> </div>','SPAN 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16370,2027,880,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/span-105','<div class="desc"> <p>This course offers students the opportunity to analyze narrative stories films and other cultural artifacts that document a history of immigration and migration to Los Angeles from Mexico and Central America during the twentieth and twenty-first centuries.Many of the narratives films and other cultural works studied treat significant contemporary issues (e.g. the representation of history questions of identity and alterity questions of race and ethnicity globalization authority the construction of class and gender in society) that Los Angeles faces as an emblematic socio-cultural space that continuously shifts as consequence of new arrivals to the city. Emphasis will be placed on studying narratives and films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically this course presents a critical view of the representation of migrations to Los Angeles in order to understand how these migration stories function as a socio-cultural medium that document and occupy many geographical spaces that establish Los Angeles as a heterogeneous cultural place and space.</p> </div>',NULL,'CTSJ 105 , FYS 1 , SOC 105 ',NULL);
INSERT INTO course_descriptions VALUES(16371,2027,382,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/span-151','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit. <em>Graded on Credit/No Credit basis only. </em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16372,2027,765,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/span-152','<div class="desc"> <p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. May be repeated once for credit.<em> Graded on Credit/No Credit basis only.</em></p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16373,2027,766,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/100/span-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16374,2027,386,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/copy-of-span-251','<div class="desc"> <div><p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. <em>Graded on Credit/No Credit basis only.</em></p></div> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16375,2027,767,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/copy-of-span-252','<div class="desc"> <div><p>Oral practice in an informal setting; includes at least one viewing of a Spanish feature film. Usually taught by language assistants from Spain and Latin America, under the supervision of a Spanish professor. Open to students who have completed Spanish 102, as well as those on a more advanced level. Students enroll in 251-252 according to level of previous preparation. Attendance is mandatory. Only four absences are allowed for this class, after which credit will not be granted under any circumstances. <em>Graded on Credit/No Credit basis only.</em></p></div> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16376,2027,4394,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/copy-of-span-293','<div class="desc"> <div><p>Intensive study in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16377,2027,383,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/span-201','<div class="desc"> <p>This course focuses on the development of speaking and writing skills. Students read and discuss cultural and literary texts from a variety of Spanish-speaking countries. The fundamentals of Spanish grammar are reviewed. Students are strongly encouraged also to enroll in SPAN 151 / SPAN 152 Intermediate Conversation.</p> </div>','SPAN 102 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16378,2027,384,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/span-202','<div class="desc"> <p>This course is intended to further develop language skills while introducing students to the fundamentals of literary and cultural analysis through the study of Latin American and Spanish texts. Particular emphasis is placed on oral communication and writing. Students are strongly encouraged also to enroll in SPAN 251 / SPAN 252 Advanced Conversation. <em>This course parallels SPAN 211 and is designed for non-native speakers of Spanish. Students may not take both SPAN 202 and SPAN 211 for credit.</em></p> </div>','SPAN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16379,2027,385,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/span-211','<div class="desc"> <p>This course is designed for students who have spoken some Spanish in the home and are able to understand spoken Spanish well. It aims to develop and improve students'' conceptual understanding of the grammatical structures of the Spanish language. Coursework emphasizes the practice of formal written and oral Spanish as well as the improvement of vocabulary with the goal of strengthening studentsâ fluency in academic and professional contexts. Principal readings consist of literary texts (e.g. short stories, literary essays, and drama) in order to prepare students for reading and writing in upper-level Spanish courses.</p> </div>','SPAN 201 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16380,2027,4395,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/span-295','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16381,2027,4396,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/200/span-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16382,2027,1134,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/copy-of-span-342','<div class="desc"> <div> <p>This course consists of an introduction to the Spanish language and Spanish-speaking communities in the United States, home to the second-largest Spanish-speaking population in the world. We will focus on questions like: who are the principal groups of Spanish speakers in the U.S.? What are the principal linguistic features of their Spanish? In the U.S., who uses Spanish, and in what contexts, and for what purposes? What is the role of Spanish in public services, the media, and schools? In this course, we will also confront social issues such as language attitudes, bilingualism, and the interaction between language and identity. The course will include guest speakers and require field trips and potentially other engagements outside of regular class times. This course will be conducted in Spanish.</p> </div> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16383,2027,3769,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/copy-of-span-393','<div class="desc"> <div><p>Intensive study in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16384,2027,1095,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-301','<div class="desc"> <p>General survey of Pre-Columbian civilizations and literature of Meso and South America the impact of the Discovery the Conquest the Colonial Period and the processes leading to the Independence and the formation of the new Republics. Literary and historical readings compositions and short essays and presentations will be used to continue developing language skills.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16385,2027,984,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-302','<div class="desc"> <p>An introduction to Spanish Peninsular literature and culture from the Middle Ages to the 18<sup>th</sup> century. This course examines the cross-cultural elements (Arab, Jewish, French, Italian, Trans-Atlantic and others) that have influence Spanish literature across the centuries. Readings include Mozarabic poetry, the <em>Cantar de Mio Cid</em>, Medieval narratives, <em>La Celestina</em>, Renaissance poetry, selections of <em>Don Quijote</em>, and Golden Age dramas. The class also incorporates representative examples of art and films.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16386,2027,387,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-303','<div class="desc"> <p>An introduction to major twentieth-century works of literary fiction and cinema in Latin America, with attention to the interplay of fiction and history, read in the original Spanish: Gabriel García Márquez''s <em>One Hundred Years of Solitude</em>, Isabel Allende''s <em>The House of the Spirits</em>, and stories by Jorge Luis Borges, Julio Cortázar and Roberto Bolaño. Film screenings include Cuban director Tomás Gutiérrez Alea''s <em>Memories of Underdevelopment,</em> Chilean director Patricio Guzmán''s <em>Salvador Allende</em>, and Argentine director Lucrecia Martel''s <em>La ciénaga</em>.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16387,2027,768,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-304','<div class="desc"> <p>This course surveys Spanish Peninsular literature and culture from the late 18<sup>th</sup>-century through the early 21<sup>st</sup>-century. Students engage with various intellectual and literary movements, including Neoclassicism, Romanticism, Naturalism, Surrealism, and Postmodernism. Special attention is given to the development of democratic traditions in Spain, the clash of political ideologies during the Second Spanish Republic and the Spanish Civil War, the trauma and legacy of dictatorship, and the changes in Spanish society resulting from the assertion of the distinct languages and cultures of the Iberian Peninsula and from globalization and immigration. Authors read include Leandro Fernández de Moratín, Ángel de Saavedra, Emilia Pardo Bazán, Jacinto Benavente, Ramón Sender, Antonio Buero Vallejo, and Juan José Millás. Significant examples of modern Spanish art, architecture, and music are also studied.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16388,2027,1494,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-309','<div class="desc"> <p>Many Latin American writers have chosen to live in Spain during the twentieth century. This course introduces students to the Latin American tradition of the writer acting as public intellectual or diplomat as well as to instances of the Latin American writer in political exile. Poets Pablo Neruda and CÃ©sar Vallejo chose to live in or near Madrid during the period of the Spanish Civil War whereas a later generation of fiction writers (Gabriel Garcia Marquez Cristina Peri Rossi and Roberto BolaÃ±o) lived in Barcelona after the 1970''s. The fiction writers include their own vision of Catalan nationalism and Catalan national identity in various short stories. The course concludes with a three-week stay in Spain that will provide a deeper understanding of the Latin American writers'' representation of the coutry. On-site lectures by historians and art-historians will enhance the student''s understanding of GarcÃ­a MÃ¡rquez''s Peri Rossi''s and BolaÃ±o''s incorporation of Catalan politics landscapes and cityscapes in their fiction.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16389,2027,1096,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-312','<div class="desc"> <p>This course surveys the history of Spanish film from its inception to the present. The course introduces students to basic concepts of film studies including cinematography mise-en-scÃ¨ne sound narrative and style but emphasizes representation and in particular depictions of gender sexuality and national identity in the context of dictatorship and democracy. The course further introduces students to the auteurist tradition in Spanish cinema. The films studied vary from year to year but the course typically highlights the cinematic production of Luis BuÃ±uel Carlos Saura and Pedro AlmodÃ³var.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16390,2027,1196,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-313','<div class="desc"> <p>This course offers students the opportunity to analyze films that have emerged in Latin America (e.g. Argentina, Brazil, Colombia, Cuba, Mexico, and Peru) as well as in the United States in the 20th and 21st Centuries. Many of the visual works studied treat significant contemporary issues in Latin America, such as the representation of history, questions of identity and alterity, questions of race and ethnicity, globalization, authority, the construction of class and gender in society. Emphasis will be placed on studying films within the social historical and cultural contexts of the material they treat and current critical theories. Specifically, this course is a critical survey of the representation of Latin America with representative examples from different historical periods (beginning with the pre-Columbian and Colonial periods followed by the 19th and 20th Centuries). The goals of the course are to understand how film as a medium has functioned historically and aesthetically in its representations of different sectors of society.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16391,2027,881,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-314','<div class="desc"> <p>How do Latin American women writers and film-makers use language and sound? This course analyzes questions of social critique and the use of language in essays, poetry and narrative fiction, including the work of Ecuadorian writer Yuliana Ortiz Ruano, Mexican Cristina Rivera Garza, and Chilean Claudia RodrÃ­guez, as well as the use of voice, music, and mise-en-scene in films by Latin American directors Maria Luisa Bemberg, Claudia Llosa and Sara GÃ³mez. Prerequisite: Spanish 202 or 211.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16392,2027,4397,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-316','<div class="desc"> <p>Violence is a tragic reality in Latin America. This course examines representations of violence in films and narratives in the Americas, including the United States. These films and narratives problematize the representation of key places and spaces in Latin America''s histories of violence, such as the Conquest of the Americas, the Colonial period, the emergence of nationalism, and significant contemporary social-political movements, such as dictatorships (e.g. Argentina, Brazil, Chile, and Mexico), the Colombian and Mexican drug cartels, the Brazilian favelas (slums), the civil wars in Central America, and migration experiences in the Americas. Emphasis will be placed on studying films and narratives within the socio-historical and cultural contexts of the material they address and on current critical theories of violence to show how these artistic works examine ethical and political issues that impact different communities in the Americas.</p> </div>','SPAN 202 or 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16393,2027,388,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-320','<div class="desc"> <p>An analysis of the relationship between literature and film, focusing on texts from the Spanish Golden Age and their film adaptations. Issues to be discussed include film adaptation as a cultural construct; narrative voice in literature and film; the transformation of the written word to the visual image; and the relationship between politics, literature, and film. This course includes a digital liberal arts laboratory in which students engage digitized and physical materials and develop necessary skills and critical frameworks for audiovisual and web-based course projects.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16394,2027,3240,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-321','<div class="desc"> <p>This course will examine culture and society in Spain under the dictatorship of Francisco Franco (1939-1975) and the effects of Francoism that continue to pervade present day Spanish society. We will focus on cultural productions (literature, film, television, propaganda posters, etc.) that illustrate socio-historical, political, and economic experiences during the most important chapter of 20<sup>th</sup> century Spain. In addition, we will examine cultural products created in the 20<sup>th</sup>and 21st centuries that represent the Francoist dictatorship to enable us to analyze the legacy of the historical trauma of Francoism in present day Spain. Topics to be discussed will include: ideological struggles, censorship, the oppression of women and other minority groups, the experience of exile, and the controversial process of historical/collective memory in contemporary Spain. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16395,2027,2606,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-325','<div class="desc"> <p>In this interdisciplinary course we will examine representative works of art and literature that are centered on the city of Madrid as a cultural, social, historical and intellectual space. We will discuss artistic and philosophical issues including, among others, the conception of space revolution in Diego Velázquez, the tensions of Enlightenment and Romanticism in Francisco de Goya, and the existential representation of life after the Spanish Civil War in Camilo José Cela. We will explore the interconnection of selected artistic and literary works with the purpose of approaching an understanding of the multilayered and fluid creation of the city’s identity.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16396,2027,769,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-340','<div class="desc"> <p>This course serves as a general introduction to the study of the Spanish sound system. The objectives of this course include strengthening students'' Spanish pronunciation in the direction of a more native-like normative pronunciation and introducing them to phonetics and phonology. Students will be introduced to theoretical means of analyzing the sound system of a language. They will also examine contrasts between American English and Spanish and apply these concepts in exercises of both written transcription and oral production as well as with a linguistic analysis of spoken Spanish. Finally students will also be acquainted with phonological differences among the dialects of the Spanish language.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16397,2027,1097,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-341','<div class="desc"> <p>This course consists of an introduction to historical Hispanic linguistics. Students learn about the major phonological morphosyntactic and lexical changes that have occurred in the language from the time of the arrival of the Roman armies into the Iberian Peninsula until the present. Foreign influences on the evolution of the Spanish language are discussed briefly. The primary focus of this course is the internal history of the language from Vulgar Latin to Modern Spanish.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16398,2027,1427,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-343','<div class="desc"> <p>Language use symbolically represents fundamental dimensions of human behavior and social interaction. For instance, what can you immediately infer about a Spanish speaker who uses the word “zumo” to describe the orange beverage commonly drunk at breakfast? Most likely, they are from Spain, otherwise they might describe this beverage as "jugo."</p> <p>This course introduces the basic concepts of sociolinguistics, using Spanish as our tool of exploration and description. Sociolinguistics focuses on the symbolic value of language as an expression of group identity based on region, gender, ethnicity, socioeconomic class, age, or other ways of defining group affiliation. In this course, we describe key notions of sociolinguistics such as the speech community, the sociolinguistic variable, and field methods. The core goal of the course is to identify phonological and morphosyntactic variation throughout Spain, Latin America, and the US, and identify what this variation tells us about language change and development as well as about the social characteristics and identities of the speakers themselves. The course also surveys other related topics such as language contact, bilingualism, Spanish as a heritage language, language attitudes and language identity in the U.S. and elsewhere, language and law, language and age, and language and gender. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16399,2027,1355,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-351','<div class="desc"> <p>A study of Cervantes'' narrative and drama in the context of certain literary trends of the European Renaissance. The course will focus on the Novelas Ejemplares selected parts of Don Quijote and Entremeses and it will explore Cervantes'' treatment of the genres and currents which influenced his art.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16400,2027,4427,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-361','<div class="desc"> <p>This course examines the representation of nature and environmental concerns in Peninsular Spanish literature. It focuses primarily on contemporary genres such as climate fiction, neorural narratives, ecopoetry, ecosocial theater, and feminist rural essay, through the works of authors including Jorge Riechmann, Irene SolÃ , Ana Merino, and MarÃ­a SÃ¡nchez. The course also considers earlier examples of ecological awareness, from Miguel Delibes in the latter half of the twentieth century to Golden Age writers such as Sor Marcela de San FÃ©lix, while critically engaging with genres like pastoral poetry. Students will apply ecocriticism as the main theoretical framework to analyze these diverse literary contributions.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16401,2027,986,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-362','<div class="desc"> <p>This course will focus on the theater of Federico García Lorca and the cinema of Luis Buñuel and Pedro Almodóvar. Students will engage in an in-depth study of García Lorca''s plays examining his theatrical representation of surrealism, gender, and sexuality in conjunction with key films of Buñuel and Almodóvar.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16402,2027,1098,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-363','<div class="desc"> <p>This course will apply current theories of autobiographical discourse to Spanish Latin American and U.S. Latino life-writing. Students will examine the relation of personal identity to dominant ideologies of gender race class and politics and will explore the role of memory and fantasy in literary self-expression. Authors studied will vary from year to year but will typically include Gloria AnzaldÃºa Reinaldo Arenas Juan Francisco Manzno Carmen MartÃ­n Gaite Rigoberta Menchu Constancia de la Mora and Mario Vargas Llosa. Students will have the opportunity to write their own autobiographies.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16403,2027,3261,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-365','<div class="desc"> <p>This course examines discourses of gender and sexuality and their intersections with race, politics, religion, and national identity in Spain from Francoism to the present. By reading a selection of literary works and watching representative films and TV shows through a feminist lens, we will explore cultural artefacts that subvert, perpetuate, and construct notions of gender and sexuality in 20<sup>th</sup> and 21st century Spanish society. Some of the topics to be discussed are: Women’s oppression and resistance during the Francoist dictatorship, the (de)construction of the Spanish <em>macho</em>, the post-Francoist experiences of LGBTQ+-identifying lives, gender violence, processes of exoticization and marginalization, and queer and feminist re-writing of Spanish history in the 21<sup>st</sup> century. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16404,2027,1632,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-370','<div class="desc"> <p>In this course we will look at the jungle as a space where western civilizations desires and fears come into tension with the imagined "other" so that sometimes the jungle can be beautiful and desirable like the Garden of Eden and other times savage and dark like hell. Readings will include Latin American works of fiction (by Jose Eustasio Rivera Romulo Gallegos Horacio Quiroga and William Ospina) excerpts from the anthropological discourse of Wade Davis narcotraffic narratives testimonial literature (by Ingrid Betancourt and Clara Rojas) as well as environmental discourse and film in order to analyze the particular forces of history that intersect in each narrative. Topics to be discussed will include: exploitation and subjugation vs. autonomy and self determination; the search for ethnobotanical knowledge and the hallucinogenic journey; the playground and hidden operational spaces of drug traffickers; the imprisonment of the kidnapped victims from the guerrilla war against the state and paramilitary forces; the environmental movement and the concept of ecotourism. We will frame our analysis in contemporary critical theories relevant to the topics being discussed. Upon completion of this course students will be able to critically understand the value and complexity of the jungle in the geography and imagination of the Latin-American modern landscape and identity.</p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16405,2027,3345,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-372','<div class="desc"> <p>This course includes the study of Latin American fiction dealing with representations of port cities (Callao, Valparaíso, Guayaquil, Buenaventura, etc.) and topics that range from labor movements, migration and economic struggles, gender, and ethnic tensions from the twentieth century. The narratives reflect the forces at play resulting in human exploitation, ecological devastation, and social stagnation present since the republican era. The course will explore modes of illustrating resistance, survival, and adaptation.</p> </div>','Span 202 or 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16406,2027,3926,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-373','<div class="desc"> <div> <p>This course traces the evolution of poetry in the Spanish-speaking world and includes the study of representative works of poetry produced in Spain and the Americas from the Middle Ages to the twenty-first century. The works reflect the major movements and artistic trends that characterize the context of their production, and they illustrate the richness and diversity of the Spanish-speaking world.</p> <p>This is a 4-unit course. It is expected that students in this class devote on average at least twelve (12) hours a week (including in-class time) to the course.</p> </div> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16407,2027,4007,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-374','<div class="desc"> <p>How do people from a country come to see each other as co-nationals, that is, as part of the same nation? What is the role of imagination in the formation of a national identity? And, what happens when national imagination fails to account for the variety of experiences in a country? In this course we will explore these questions by engaging with literature and film from Argentina such as short stories by Jorge Luis Borges and Mariana Enriquez, poems, films like Santiago Mitre''s <em>Argentina</em>, <em>1985</em>, graphic novels, and short novels. Through themes such as labyrinths, infinite libraries, metafiction, and philosophical paradoxes, students will engage in critical analysis, creative responses, and multimedia storytelling.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16408,2027,4045,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-375','<div class="desc"> <p><span style="font-size: 12pt">This course investigates how Latin American literature represents imprisonment, political repression, and strategies of resistance with an emphasis on 20</span><span style="font-size: 12pt"><span style="font-size: 0.6em; vertical-align: super">th</span></span><span style="font-size: 12pt"> and 21</span><span style="font-size: 12pt"><span style="font-size: 0.6em; vertical-align: super">st</span></span><span style="font-size: 12pt"> century works. We will focus on representations of confinement by engaging with a wide range of genres â including fiction, poetry, plays, literary testimonies â alongside film and critical essays, to analyze the relationship between literature, history, and human rights.</span></p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16409,2027,4398,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-376','<div class="desc"> <p>Beginning with a close reading of the Quiché Maya myth of the <em>Popol Vuh</em> and its influence on Nobel-Prize winning Guatemalan author Miguel A. Asturias, this course discusses canonical Central American works of the nineteenth and twentieth century, with attention to the literary portrayal of war and violence by Nicaraguan and Salvadorean writers Ernesto Cardenal, Gioconda Belli, Claribel Alegría, Roque Dalton, and Manlio Argueta. The course includes some discussion of Central American film. </p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16410,2027,770,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-377','<div class="desc"> <p>This course explores Latin American comics and graphic novels as a powerful medium for storytelling, social critique, and historical memory. Through the lens of visual and textual analysis, we will examine how artists and writers use the graphic novel format to address themes such as migration, gender, class, and resistance, among others. Students will engage with a diverse range of Latin American works in Spanish, from early comic strips to speculative fiction, historical retellings, and surrealist explorations of identity. </p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16411,2027,4399,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-379','<div class="desc"> <p>In <em>One Hundred Years of Solitude</em>, <em>Of Love and Other Demons</em> and <em>The General in His Labyrinth</em>, the Nobel-Prize winning Colombian author contextualizes Latin American, Colombian, and Caribbean history in differing ways. The course will discuss the allegorical, satirical, and realist uses of history in those three novels by García Márquez, with particular attention to the presentation of colonialism, nineteenth-century independence movements, slavery, and race relations. </p> </div>','One SPAN 300-level course ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16412,2027,3346,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-380','<div class="desc"> <p>This course examines the intersection of immigration, race, gender, sexuality, and nationality in contemporary Latinx cultural production in the US. Turning to cultural narratives of migration, we will explore the historical, political, and sociocultural processes that have led to the formation of Latinx diasporic communities in the U.S. and how these contexts have shaped the Latinx experience in the U.S. We will discuss questions of Latinx identity, migration, alterity, and belonging in cultural texts produced by different Latinx communities in the U.S. (such as Mexico, Colombia, The Dominican Republic, El Salvador, and Guatemala). By centering on a variety of cultural texts (including memoirs, novels, essays, poetry, short fiction, and film), this course examines the role culture plays in documenting the heterogeneity of Latinx identities, along with its intersections with other categories of difference (such as race, gender, sexuality, class, status, nationality). Some of the topics we will cover include: undocumented storytelling; coming-of-age Latinx narratives; narratives of migration and literatures of the borderlands; queer Latinx storytelling; Afro-Latinx narratives and erasures; and state violence, masculinities, and Latinx intergenerational trauma.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16413,2027,771,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-382','<div class="desc"> <p>This course analyzes the narrative development of the contemporary Mexican novel from the Mexican Revolution to the present. Principal novelists studied in this seminar are Mariano Azuela Juan Rulfo Carlos Fuentes Gustavo Sainz Elena Poniatowska Angeles Mastretta and Laura Esquivel. This course combines textual analysis with the application of contemporary literary theory.</p> </div>','SPAN 202 or SPAN 211 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16414,2027,389,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-383','<div class="desc"> <p>This course offers a representative overview of Chicano literary production covering five genres: poetry theater novel short story and essay. An historical framework is outlined to establish the different periods of Chicano creativity from its origins to contemporary times using a series of works and authors to illustrate their respective social context.</p> </div>','SPAN 301 , SPAN 302 , SPAN 303 , or SPAN 304 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16415,2027,4001,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16416,2027,772,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-397','<div class="desc"> <p>Individual study of a major author, movement, or genre. For students with advanced competence who seek study in an area not included in the department''s curriculum. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16417,2027,1428,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/300/span-398','<div class="desc"> <p>The goal of the Community Translation Internship is to provide students with an experiential understanding of the practice of translation. The Community Translation Internship allows students to learn through direct experience the different steps in the translation process as well as examine the challenges that bilingual professionals face in their efforts to reach out to underserved populations such as the Spanish-speaking communities. All students enrolled in the Community Translation Internship work with a community-based organization for an average of eight hours a week.</p> </div>','SPAN 340 or above and permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16418,2027,390,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/400/span-490','<div class="desc"> <p>This course will provide an in-depth analysis of one or more of the following genres: drama poetry essay novel short story and film with an introduction to contemporary literary film and cultural studies theory. Texts will be drawn from Spain and Latin America. Open only to Spanish majors in their senior year.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16419,2027,3917,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/400/span-493','<div class="desc"> <p>Comprehensive-level work in an area of Spanish literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> <p>When taken as a 4-unit course, you should expect to spend at least twelve (12) hours a week on this course. When taken as a 2-unit course, you should expect to spend at least six (6) hours a week on this course.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16420,2027,4400,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/400/span-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16421,2027,4409,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/400/span-498','<div class="desc"> <p>Extended comprehensive-level work in an area of literary analysis, cultural studies, or linguistics under the direct supervision of a member of the faculty. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16422,2027,773,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/span-spanish/400/span-499','<div class="desc"> <p>Independent study leading to an honors project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16423,2027,3188,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-100','<div class="desc"> <p>This course introduces students to key discourses and theories in performance and theater studies. Centered on live performance, the course treats performances themselves as our primary âtexts.â Students will attend and analyze approximately three to four performances on and off campus, including field trips to see work in Los Angeles.</p><p>Through close looking, reading, discussion, and writing, students will develop analytical tools for thinking critically about performance across a range of contexts. We will study artists and scholars who interrogate the intersections between art and life, ritual and theater, and acting and not-acting, engaging with perspectives from across the globe. Each week, we will explore different responses to the question âWhat is performance?â and examine how theory helps us understand what performance does, how it operates, and why it matters.</p><p>This is not an acting class. Instead, students will engage performance through critical analysis, written work, discussion, and praxis-based exercises that illuminate the dynamic relationship between performance theory and practice.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16424,2027,392,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-101','<div class="desc"> <p>In this course, students engage with the art of reading and writing theatrical scripts. By exploring the essentials of drama - characters in conflict, compelling language, resonant thematics, and bold theatricality - we investigate the elusive relationship between a play''s text and its ultimate destination: the live stage. The class begins by analyzing established scripts and ends with students creating their own. Along the way, we''ll discover the rule and rule-breaking techniques playwrights use, helping us to unlock the performative potential of their work and ours. The semester culminates with each student writing an original short play.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16425,2027,393,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-110','<div class="desc"> <p>This course is the foundation of our acting program and is 7 weeks in duration, allowing two sections to be offered each semester -- one in the first seven weeks of the semester and the other in the last seven weeks of the semester. This class is intended for students with a range of acting and performance experience - from the first time actor to the seasoned performer. Through group and individual exercises and projects, students will develop a stronger public presence, connection to and interpretation of text, as well as flexibility, concentration, and ways to live truthfully in imaginary circumstances. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16426,2027,394,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-120','<div class="desc"> <p>In this course we introduce students to many of the different areas of theater production with a primary focus on scenic construction, also including drafting, lighting equipment, rigging practices and special effects. <em>The course includes a laboratory through which techniques taught in class are applied. The laboratory averages 36 hours over the semester with laboratory schedules to be arranged with the instructor. Students are required to purchase some materials for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16427,2027,395,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-121','<div class="desc"> <p>Our production laboratories are applied courses for student designers, technicians and managers who are on crews of productions directed, designed or directly supervised by faculty members in the department. In order to complete a theater minor or major, students are required to complete production laboratories in two separate areas, one of which must be a running crew for a department production. The course may be repeated for credit. <em>Graded on Credit/No Credit basis only.</em></p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16428,2027,396,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-122','<div class="desc"> <p>These laboratories are designed for our student designers technicians and managers who are given primary responsibility on production crews directly supervised by faculty members in the department. In the laboratories students pursue additional research and practical applications beyond the requirements of THEA 121 and may use this course to meet one of the THEA 121 requirements for a major or minor. Permission of instructor required.</p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16429,2027,3859,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-123','<div class="desc"> <p>While 2 121s are required for the major, students might work on other productions for credit. This course can be used for students who Assistant Direct, produce the NWF, and for other mentored production opportunities with approval from the Chair.</p> <p>This can be taken for 1 or 2 units depending on the project.</p> <p><em>Graded on Credit/No Credit basis only.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16430,2027,397,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-130','<div class="desc"> <p>In this course students study the theory and apply the methodology of the Jose Limón Technique. Developed from the principles of fall and recovery the Limón Technique is built upon motion through succession suspension alignment and opposition. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16431,2027,774,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-131','<div class="desc"> <p>In this course students learn the fundamentals of jazz and tap dance with an emphasis on body alignment strength flexibility rhythm and coordination. During the semester we experiment with lyrical and contemporary jazz combinations as well as tap variations designed to develop musicality self-expression and performance skills. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16432,2027,398,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-133','<div class="desc"> <p>Tai Chi Chuan is the study and practice of slow controlled movement, breathing, and realignment of the body. Sometimes referred to as standing yoga, Tai Chi Chuan has been practiced for centuries for its many benefits, including stress management, disease prevention, and increase in energy. Our focus in this class is on relaxation, gentle movement, and meditation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16433,2027,399,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-134','<div class="desc"> <p>In <em>Beginning Ballet</em> we study the principles and execute the techniques of ballet based on the Vaganova method. Students are taught the fundamentals and elementary vocabulary of ballet through <em>barre</em> center and traveling combinations and exercises. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16434,2027,4401,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-135','<div class="desc"> <p>Classical Dance in India is a form of yoga, dance, and theater. Learn the foundational basics of two of the most popular and ancient Indian classical dance styles: <em>Bharata Natyam</em> and <em>Kathak</em>. Our semester will explore the elements of Indian dance including fast rhythms, moving<br/> expressions, and engaging story-telling. We will learn vocabulary and introductory dances in the classical forms, understand their relationship to dance in our current society and to western dance forms, and explore contemporary dance in India that is rooted to and in reaction to Indian classical forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16435,2027,1041,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-136','<div class="desc"> <p>What is Bollywood? A fun, expressive dance form that originates from the popular movie musicals out of the Indian film industry. A commercial dance style that has entered popular culture in both India and the US, Bollywood is a fusion dance style that incorporates elements from Indian Classical, Indian folk, Western styles of Hip Hop and Jazz, and world dance forms such as Salsa and African. It is a high-energy, cardio dance style that oozes style, expression, and grace. Students will learn the basics: <em>mudras</em>, foot work, and expressions to equip them in any Bollywood class or audition. They will also learn an array of choreography that covers the Bollywood landscape.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16436,2027,400,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-137','<div class="desc"> <p>This is an introduction to a study of choreography based on the Nikolais/Mettler methods of creating dances. Our tools include the manipulation of motion through space time shape and energy volumes within the context of the body and its surroundings; and our work culminates with studio performances of pieces choreographed by the students in the class. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16437,2027,401,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-139','<div class="desc"> <p>Exploring the richness of African dance and music traditions from four African regions, this course is devoted to the study of authentic dances, songs and drumming from Africa, as well as their historical and cultural contexts. Students may choose to focus on either dance or percussion. Percussion students will learn traditional rhythms for djembe and talking drum as they inform and interact with dance movements. Dancers begin with exercises to condition our bodies for the rigor of the African Dance forms -- developing strength, stamina, coordination, flexibility, and rhythmic awareness, and move to the informed and joyous practice of the dances. <em>Graded on a Credit/No Credit basis only. May be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16438,2027,1495,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-141','<div class="desc"> <p>We study and practice some of the most popular dance forms of the twentieth century. Through theater film and television many of these dances have expressed the spirit and the style and particularly the romantic temper of their times: from the quick steps of the Fred Astaire films to the swing dancing in <em>Malcolm X</em> and <em>A League of Their Own</em> and the tango of <em>The Scent of a Woman</em>. The dances taught include fox trot waltz swing and tango. We strongly recommend this class for our student actors. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16439,2027,403,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-142','<div class="desc"> <p>In this course students study folk and historical dances drawn from Eastern and Western Europe along with folk dances of the United States derived from those traditions. Performance opportunities may include Viennese waltz and dance-based children''s theater. <em>The course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16440,2027,1742,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-143','<div class="desc"> <p>Students explore the rich traditions of Latin Dance from its origins in the African diaspora found in Cuba, Caribbean and Latin American nations as well as the influence and effect of these dances throughout popular Western culture. Students embrace through performance various dance forms developed in Mexico and throughout Central and Latin America and study the place and importance of the dances in Latin cultures.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16441,2027,775,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-175','<div class="desc"> <p>This introductory design course grounds students in aesthetics as they relate to design for performance and the role of design in the collaborative process of production. Those students interested in becoming designers receive a foundational experience for specializations offered in subsequent classes. Students explore elements of design and the principles of composition as they can apply to theater and film. Over the semester students come to understand and acquire the skills to develop visual expressions of the meaning of play and film scripts. Through individual and group design projects, students learn to incorporate script analysis, design research, and visual presentation techniques. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16442,2027,1135,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-190','<div class="desc"> <div style="margin: 0; min-width: 0; padding: 0 0 20px; width: auto; color: rgba(34, 34, 34, 1)"><div style="direction: ltr; margin: 8px 0 0; padding: 0; position: relative; font-size: 0.875rem; overflow-x: hidden"><div style="direction: ltr; font: 0.888888888888889em / 1.5 Arial, Helvetica, sans-serif; position: relative"><div dir="ltr"><p>Step off campus and into Los Angelesâ vibrant theater scene. In this class we''ll see live performances by some of the cityâs most exciting artists - creators who are making work thatâs bold, diverse, and reflective of our current moment. Each week, Friday evening field trips take you across L.A.âs neighborhoods to experience performances from a range of genres and styles. Then, in class we''ll process our responses and meet some of the artists for intimate conversations about their creative process and their work. Together, weâll explore what it means to be an active theatergoer. And we''ll dive into the social and political forces driving new performance while connecting with the pulse of L.A.âs theater community. There is a ticket fee of $150 for this course.<em><br/></em></p></div></div></div></div> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16443,2027,3773,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-193','<div class="desc"> <p>Research in an area of theater &amp; performance studies that can include performances, producing, design, etc. Permission of instructor required.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16444,2027,2866,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-195','<div class="desc"> <p>What does performance do? Why perform? What is the essence of the “live” and what is the impact of being in the same time and (virtual) space? We will unpack these questions through analysis and performance, looking closely at seminal pieces that speak to this moment and calling on experts in design, technical theater, comedy and solo performance to give behind-the-scenes insight into the making of live performance. Bracketed around questions of liveness, social action, and impact, students will take specialized workshops with theater faculty who will address these questions through their areas of expertise, providing students opportunities to experiment with an array of performance practices.</p> </div>',NULL,'ARTS 250 ',NULL);
INSERT INTO course_descriptions VALUES(16445,2027,776,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/100/thea-197','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16446,2027,990,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/copy-of-thea-245','<div class="desc"> <p>Students in <em>Stage Makeup</em> learn the fundamentals of makeup design for the theater. We cover a number of makeup techniques including basic three-dimensional corrective, glamour, character and old-age makeups with some special effects makeup. During the semester, students put theory into practice as they create a variety of practical and creative makeup designs. <em>There is a materials fee for this course, not to exceed $75.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16447,2027,2567,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/copy-of-thea-290','<div class="desc"> <p>This topics course provides opportunities to work on performance outside of traditional naturalistic traditions. Topics change annually. First-year students may only take this course with permission of instructor. May be repeated once for credit when taken as a different topic. <em>Note: Different topics may satisfy different Core requirements</em>.</p> <p><strong>Autobiographical Performance: Laughing At Ourselves</strong></p> <p>In this course, participants will learn how to create compelling and humorous personal nonfiction narratives for the stage, studying classic narrative structure and paying close attention to theme &amp; detail. There is a long history of performers whose autobiographical solo work, like Crabb’s, simultaneously finds comedy in the tragedies of their lives while infusing the mundane with drama. To learn how to do this, students will study seminal storytellers and theater makers, (such as Spalding Gray, John Leguizamo, Whoopi Goldberg, Julia Sweeney, and others) who use their lives and experiences as templates for performance. Students will also review Moth-style storytelling to help find their own voice through a close examination of identity, self, and how we perform in the world.</p> <p dir="ltr" style="margin-top: 10px;"><strong>Clown and Comedy Class with Cirque du Soleil Clown and Wanlass Visiting Artist Daniel Passer</strong></p> <p dir="ltr">In this class, we dive into an exploration of the state of play through a series of exercises generated over many years as a clown and comedy conceiver for Cirque du Soleil, Dragone Entertainment and Saturday Night Live. The tools to guide the student on this journey to discover their unique, vulnerable point of view are: improvisation, status exercises, physical games, Commedia archetypes (Arlecchino, Pantalone, Doctore and others) and comedy routines. In this class, we explore the daring and vulnerability of the clown through embodying your passion, rediscovering a sense of play, and leading with joy. The pure, honest response to others (onstage and in the audience) provides a point of entry to incorporating a sense of fearlessness and authenticity into your work as a whole. As much a life philosophy as an acting technique, the performer is sure to come of class with a heightened innocence and curiosity feeding their moment-to-moment discoveries</p> <p><strong>Creating Community Engaged Theater</strong></p> <p>Under the guidance of members of the world renowned and community engaged Cornerstone Theater Company, this course will introduce students to the Cornerstone method of creating original theater work that addresses local concerns through community collaboration. During the course, students will help with The Highland Park Community Project—Cornerstone’s community engaged project in rehearsal and performance in the fall semester. This production will provide the experiential aspects of the course, some of which will take place off-campus in the Highland Park Community. In regularly scheduled class meetings, students will study the Cornerstone methodology, especially intention and engagement, and through discussion, lectures, and research, be introduced to existing approaches to community based theater. Topics will include how community engagement informs acting, directing and design. <em><em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></em></p> <p><strong>Extended Reality</strong></p> <p>For the spring of 2024, this course will be taught by Wanlass Visiting Artist Dawn Monique Williams. Through the semester we will explore hybrid performance techniques using digital/mixed/multi-media to expand the boundaries of live performance. No previous experience necessary.</p> <p><strong>Generating Independent Theater</strong></p> <p>This interdisciplinary course will provide an opportunity for students to define their interests as performers/writers/producers and to develop original material, an artistic vision, and producing expertise that will lead to a realized performance. Individual skill sets and interests including storytelling, dance, character-work, visual art and music may each provide a jumping off point for this work. At the beginning of the course, a series of improvisational exercises, mini-performances and character studies, supported by readings on contemporary solo, immersive, experimental and environmental theater, will guide students to land on personal solo or two-person projects. In the second half of the semester, students will craft these pieces utilizing their peers as a think-tank. This generative, collaborative process will emphasize the importance of ensemble both onstage and behind the scenes during the creative and production process. To culminate their work, the class will be responsible for the production aspects necessary to present their pieces in a public performance on-campus.</p> <p><strong>Reframe the Game: Strategies for a More Inclusive American Theater</strong></p> <p>Reframe the Game is a deep dive into Equity, Diversity and Inclusion (EDI) principles, as they apply to working in the theater, as well as in interpersonal communication practices. Through hands-on activities, discussions, research and interactions with guest practitioners, the course will address why this work is vital to our field, and how EDI lays the foundation for more creative and imaginative artistic workspaces and practices. The course will be organized into three parts. Part One will focus on Vocabulary and Power Structures: The cohort will focus on establishing a shared vocabulary as a foundation for conversation about social identity, privilege, historical and institutional inequities, and ally-ship, as a means to develop skills to better identify and dismantle inequity when we see it. We will look inward to examine where we as individuals fit into the social landscape of America, and how our identities affect how we move through the world. Part Two will focus Research and Examination: Students will research EDI initiatives and strategies at US regional theaters as case studies to examine how stated EDI principles may (or may not) align with programming and institutional culture. In addition, local guest artists and practitioners whose work strongly aligns with social equity will visit the class for deep dive conversations about the work that they do, the challenges they face, and where they see the future of our field. Part Three will focus on Final Projects and the question What Now?: In small groups, students will apply what they have learned over the course of the semester to create an original exercise, workshop or governing policy that addresses a specific EDI concern in their community (institutional, local, national or international) to present to their classmates and invited faculty in the final weeks of the semester. Prerequisite: THEA 101, THEA 210, or by instructor permission. <em>Additional </em><em>Core Requirement Met: U.S. Diversity.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16448,2027,2891,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-200','<div class="desc"> <p><strong>Immersive Visual Environments with Commonplace Technology</strong></p> <p>Contemporary theater—especially as performed on Broadway—has become a high tech multimedia production with budgets in the millions. How can emerging theater artists compete with this level of spectacle and/or create new work that is equally compelling? In this course students will learn how to check the boxes of the newest innovations in big budget theater and performance without the financial demands. We will level the playing field by creating forms of high spectacle through economical means. Students will learn to devise spectacular visual stories using commonplace objects. Throughout this project based course, students will study the fundamentals of visual storytelling both through playing with lights and shadow led by cutting-edge artist Christine Marie and through developing story with performance artist and professional storyteller David Crabb. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16449,2027,988,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-201','<div class="desc"> <p>We study the artistry of contemporary theatrical movements as well as American writers from divergent cultural and aesthetic backgrounds. By looking at movements and artists in their cultural and social contexts we explore the sources the aims and the artistic strategies of their works while developing an understanding of important new voices in American Theater. The focus of the class will vary from year to year. May be repeated for credit one time with a different topic.</p> <p><strong>Looking for August: A Critical Exploration into the Art, Life, and Legacy of August Wilson</strong></p> <p>African-American playwright August Wilson is perhaps the greatest American dramatist of the 20th Century. His unmatched “Century Cycle” chronicles the African-American experience, and unearths deep-rooted dysfunctions of racism and socio-economic oppression, while at the same time celebrating the joy and resilience at the heart of African-American culture. Wilson was also an arts theorist, bringing to the fore front several explosive and controversial concepts concerning the American theater industry, particularly race-based vs. multicultural based casting. In this engaging course, we will explore Wilson’s epic, ever evolving career. Course participants will collaboratively engage with some of his most iconic characters, in the attempt to re-discover what makes them so impactful and electrifying. We will discuss Wilson’s life trajectory, his roots in Pittsburgh and griot approaches to playwriting, and peer deeply into some of his most iconic works, including Fences, A Piano Lesson, and the often misunderstood Joe Turner’s Come and Gone. We will also examine Wilson’s massive impact on 21st Century playwrights of all nationalities, and attempt to come to some comprehension of Wilson’s almost limitless influence on theater and global culture. </p> <p><strong>The Black Arts Movement Explored and Deconstructed</strong></p> <p>An in-depth, intellectually stimulating exploration into the complex and impactful Black Arts Movement of the 1960s and 1970s. Through reading and analyzing the poems, plays and criticism of the time, as well as lectures and small group discussions and “on your feet” performance activities, students will gain insights into the people, the places, and the critical junctures that emerged during this profoundly explosive era of art and culture. Artists explored include Amiri Baraka, Sonia Sanchez, Nikki Giovanni, Henry Dumas, Audre Lorde, Ed Bullins, Ntozake Shange, and others. Themes/concepts include black identity, the connection between black arts and black power, the rejection of integration as an ideal, LGBTQ and Black Arts, the assassination of Malcolm X, John Coltrane and Sun Ra, black radical thought, the African-American male as a Christ figure, male chauvinism in Black Arts and Black Power, and “future directions,” i.e. the influence of the Black Arts Movement on other cultural movements and American aesthetics.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16450,2027,404,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-202','<div class="desc"> <p>Looking at a small number of Shakespeare''s scripts from the vantages of actor director and playwright we examine the unique and complex relationship between Shakespeare''s literary constructions and their possible performances. We analyze how through language and structure he develops characters of psychological complexity; how he develops stories from extra-theatrical material; and how in style and subject matter his scripts relate to one another. This course offers students a bridge between literary study and theatrical enactment: looking closely at Shakespeare''s designs from the perspective of the theater practitioner-from in most ways Shakespeare''s own perspective.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16451,2027,1136,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-203','<div class="desc"> <p>In this course we investigate a variety of 20th and 21st century theatrical productions across the globe staged during times of conflict and crisis: from online performances to amateur stages in restaurant back rooms in workers'' clubs and cafes to professional and Broadway theaters. From the 1920''s agitation trials (<em>Agitsudy</em>), mass spectacles and agitprop theater during the Russian Revolution to contemporary theater''s responses to COVID 19, anti-blackness, and other forms of racism and social oppression, we will examine how artists and activists use theater to respond to social and political unrest: sometimes as a tool to fight oppression and at other times as a tool to encourage obedience and propagate national political ideals. From performances staged in Sarajevo to Rio de Janeiro, from Mexico City to New Orleans, and from the streets of Moscow to the streets of New York City and beyond, the class thinks through art as activism and activism as art, examining how theatrical tactics transcend the boundaries of traditional performance spaces. We examine the performance theories and strategies emerging from these theatrical moments as we study seminal plays from these periods. For the final project, students in the class will develop performance projects in response to a contemporary crisis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16452,2027,1317,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-204','<div class="desc"> <p>In this course, we introduce students to the ways comedy can influence and transform society. We will study scripted as well as unscripted forms of performance, including stand-up, physical comedy, sketch, Teatro Campesino style <em>actos</em>, and faux news shows. Students learn the formal structure of the different comic forms through extensive writing and revision both individually and in collaboration with other students. Students develop an understanding of the role comedy plays in socio-political critique through research of issues about which they are passionate and in the subsequent creation of solo and group work illuminating those issues for their peers in a final cabaret performance. Not open to frosh.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16453,2027,2362,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-205','<div class="desc"> This course addresses the fluid boundary between law and performance. We will think through how performances of law influence legal practice and vice versa. We will also interrogate how theater provides an alternative site for the performance of justice, one that may satisfy needs that go unmet in state and federal courts. We will study trial transcripts as legal and cultural documents, and we will look at their dramatizations, putting these plays into conversation with contemporary theater, performance, and legal criticism while also thinking about how our own needs and impressions of justice have been, or can be, staged in and through performance. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16454,2027,2900,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-206','<div class="desc"> <p>In this energetic and creatively maddening class, students will explore Shakespeare’s <em>Richard III </em>and several adaptations in a unique and highly charged manner. By yanking the Bard off his high horse, and identifying universal themes and structural innovations inherent in Elizabethan poetic meter, course participants will gain newfound understanding and appreciation for the work and legacy of Shakespeare. Instead of looking at classic works as an untouchable, or “holier than thou,” canon instead we will investigate how playwrights have been inspired by, deconstructed and reconstructed them. In addition to Shakespeare’s <em>Richard III</em>, students will explore several bold adaptations such as Carlyle Brown’s <em>The African Company Presents "Richard III,"</em> <em>Teenage Dick </em>by Mike Lew, as well as Will Power’s own <em>Seize the King</em>. Perhaps most importantly, students will have the opportunity to learn iambic pentameter, construct their own post-modern, Shakespearean mash-up scenes, and learn the very-latest contemporary methods of verse-based performance. In this performance seminar, we will compare and contrast Shakespeare’s metric language with other heightened language forms, from ancient Greek poetry to hip hop lyrics. Filled with rhythm, poetry, and both an appreciation and utter disdain for anything old and crusty, this course promises to be a ridiculously crazy, wild ride for the ages. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16455,2027,405,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-210','<div class="desc"> <p>In this course students develop a deeper sense of physical expression, kinesthetic response, ensemble work, creativity, and imagination. Students apply this training in solo and scene work both in the studio and on camera. At the end of the semester, students apply the preparation and techniques learned throughout the semester in final scene projects using script analysis, character work, object work, and physical expression in both classical and contemporary texts. <em>There is a ticket fee not to exceed $50 for this course.</em></p> </div>','THEA 110 or permission of instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16456,2027,406,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-211','<div class="desc"> <p>Our Performance Laboratory is offered as an applied acting course based upon roles played in our professionally directed Keck Theater productions. This course is offered only for grades of Credit/No Credit and may be repeated for credit. Permission of instructor required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16457,2027,777,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-212','<div class="desc"> <p>In this course student actors will continue to develop audition techniques introduced in <em>Introduction to Performance</em> and <em>Acting 1</em> applying them to the standard "general audition" format. In addition our students learn about the audition and casting process in professional theater through a guest speaker series of casting directors and professional film and stage actors. Not open to frosh. <em>Graded on a Credit/No Credit basis only. </em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16458,2027,778,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-215','<div class="desc"> <p>Working with selected scripts from the best of recent and contemporary screenplays our students develop techniques for working in front of a camera as a specific application of the work of both <em>Acting 1</em> and <em>Acting 2</em>. <em>There is a materials fee of $60 for this course. THEA 310 is strongly recommended as preparation.</em></p> </div>','THEA 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16459,2027,408,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-234','<div class="desc"> <p>Students develop and refine ballet technique based on the Vaganova Method. This course is offered only for grades of Credit/No Credit and may be repeated for credit.</p> </div>','Two semesters of THEA 134 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16460,2027,782,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-237','<div class="desc"> <p>Building upon the work from <em>Beginning Choreography</em> students develop more sophisticated choreographic strategies language and techniques with an emphasis on group choreography including site-specific work and studio performances. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit.</em></p> </div>','Permission of instructor required ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16461,2027,411,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-244','<div class="desc"> <p>Our stage management course introduces students to the art and techniques of stage management helping them acquire the theoretical knowledge and the practical skills to manage theatrical productions from casting through performance.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16462,2027,883,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-246','<div class="desc"> <p>In <em>Costume Construction</em> students acquire the skills necessary to construct basic garments for the stage. At the end of the course each student will build a costume piece.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16463,2027,4402,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-247','<div class="desc"> <p>This course applies acoustics, electronics, and digital audio theory in the assembly and operation of Public Address (PA) systems for live concerts. We cover the practice of live sound engineering in different contexts, with a focus on skill building in the technical aspects of live music. Students will assemble PA systems and operate a front of house mixing console for a host of music events both on and off campus. Students will also learn how to set up microphones, use a graphic equalizer to tune a PA system, and run individualized monitor mixes during live performances. Lessons about the theory and practice of live sound will be presented alongside practicum exercises in live engineering, culminating with running tech for several concert-length live performances. Live recording in a DAW-based multi-track session will also be a component in the later portion of the semester.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16464,2027,1042,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-248','<div class="desc"> <p>We introduce students to the theory and application of sound and music as elements of design for theater dance and other collaborative multimedia dramatic forms. Throughout the semester we address fundamental issues of sound design: including script analysis conceptual approaches to sound music underscoring working with audio equipment and sound editing. Over the semester our students learn how to work within a creative team of designers coordinating the many design elements of various dramatic forms.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16465,2027,1102,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-250','<div class="desc"> <p>Period style can be characterized as the aesthetic traits common to a particular historic or cultural moment. For recorded media and live performance, writers, directors and designers set their storytelling in a framework of time and place. In this class, we explore examples of shifting styles across select non-Western and Western cultures and through time and seek to discern their influence on other cultures or historical periods. Through this exploration, we begin to understand how architecture, interior design, fashion history and the act of dressing evolved throughout the centuries and across cultures because of technological advancements, changes in economic and social class structures, in political climates and through appropriation of cultural aesthetics. Why was there a kimono specialist in the costume department of <em>Westworld</em>? How did Ruth E. Carter develop her Afrofuturist vision for <em>Black Panther</em>? Where would you find visual and dramaturgical resources for <em>Vietgone</em>, or <em>Hair</em>, or <em>Cambodian Rock Band</em>, the action of each set in a similar historical period but whose stories are told from very different cultural perspectives?We will investigate these and other questions through reading, and critical analysis of visual records, plays and films, in-class discussions, and presentations.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16466,2027,412,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-260','<div class="desc"> <p>This course is a community engaged course - One of two separate applied workshops in teaching theater and performance in public schools that focus on classroom management and education with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take 260 and 261 in either order. In four intensive sessions, students learn five workshops geared to the third grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Preferably, the students in the course will have taken at least THEA110 because part of teaching theater to students is to co-create and perform with them, using one''s artistic tools and techniques to teach the students how to embrace their creativity. Students will develop proficiency in being a teaching artist, which in itself is a creative practice that fuses pedagogy with performance. Students will develop their voices as teaching artists, a skill they can apply in their own creative practice and is translatable into other areas. Enrollment is limited.</p> </div>','THEA 110 and/or Permission of Instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16467,2027,783,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-261','<div class="desc"> <p>This course is one of two separate applied workshops in children''s theater that focus on work with elementary school children. We study age-appropriate methods of integrating theater into the elementary school curriculum. Students may take THEA 260 and THEA 261 in either order. In four intensive sessions students learn five workshops geared to the fifth grade after which, under the instructor''s supervision, they guide two local elementary school classes through the curriculum. Enrollment is limited. Graded on a CR/NC basis only.</p> </div>','THEA 110 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16468,2027,413,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-275','<div class="desc"> <p>The Scenic Design Studio course offers an immersive exploration into the artistry and techniques behind creating captivating and functional stage environments. Through hands-on model-building projects in a studio format, we will delve into the multifaceted world of scenic design, equipping students with the foundational skills necessary for crafting compelling theatrical spaces.</p> <p>Throughout the semester, we will investigate the historical evolution of scenic design, analyzing key movements, influential designers, and the impact of technological advancements on stagecraft. Emphasis will be placed on understanding the relationship between visual storytelling, dramatic narrative, and spatial design.</p> <p>The course will cover fundamental principles, including:</p> <ol> <li><strong>Design Process</strong>: We will learn to conceptualize, develop, and communicate their ideas effectively through sketches, models, and drafting techniques.</li> <li><strong>Set Construction and Materials</strong>: An exploration of materials, construction methods, and practical considerations essential for bringing designs to life on stage.</li> <li><strong>Script Analysis</strong>: Analyzing scripts to extract thematic elements, mood, and atmosphere, and translating these into visual design concepts.</li> <li><strong>Historical and Contemporary Perspectives</strong>: Studying the evolution of scenic design from traditional theatre to modern and experimental forms.</li> </ol> <p>In addition to theoretical discussions, we will engage in hands-on projects, culminating in the creation of their own scenic designs for selected plays. Students will have the opportunity to execute the designs through scaled models, drawings, or digital representations, honing creative skills and practical application of design theories.</p> <p>This course encourages critical thinking, creativity, and problem-solving within the realm of scenic design, preparing students for further exploration in the field of theatre production or related artistic endeavors.</p> </div>','None. However, a strong interest in theatre, design, or visual arts is recommended. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16469,2027,991,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-295','<div class="desc"> <p>Topics vary from semester to semester. Specific topics may satisfy different Core Program requirements. This may be repeated twice for a maximum of eight units.</p> <p><strong>Hip Hop Performance</strong></p> <p>What are the intricate, performative aspects of hip hop culture? How is the performance of hip hop culture powerful, revealing, potent and contradictory, all at the same time? This course examines Hip Hop as performance, and exposes both the sacred ritual of “rockin’ the mic,” as well as the various modes of complex expressions that the culture has developed and delivered to the world. Together we will wrestle with the various performative practices of legendary rappers such as Jay Z, J Cole, Cardi B, Travis Scott, and Nicki Minaj. We will imagine hip hop performance as what occurs both on the stage through lyrics, music, and stage techniques, as well as how hip hop manifests as performance off the stage, through the crafting of image and the manipulation of (or being manipulated by) social and mass media. Course participants will comprehend various performative trajectories in hip hop couture, including the layered performance of women in hip hop, as well as hip hop as expressed in the LGBTQ+ communities, and how these diverse reflections compare, contrast, and ultimately merge to create a definitive, yet sometimes elusive statement about what it means to perform hip hop artistry in the 21<sup>st</sup> century. And finally, students will get the opportunity to learn hip hop performance techniques, and experiment with these techniques in a safe, non-pressurized environment. <em>Additional Core Requirement Met: United States Diversity.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16470,2027,4403,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/200/thea-297','<div class="desc"> <p>Second year students pursue independent courses or projects guided by a theater faculty member. This course is available only to second year students.</p> </div>','Permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16471,2027,993,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/copy-of-thea-320','<div class="desc"> <p>Building on the foundation of Introduction to Technical Theater, the students in this course learn advanced construction techniques, metal working and welding, furniture construction and repair. Students in the class will also act as crew chiefs for Theater Department productions.</p> </div>','THEA 120 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16472,2027,414,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-301','<div class="desc"> <p>Topics vary semester to semester.<strong></strong></p> <p><strong>Survey</strong></p> <p>As artists and scholars, we will discuss and study several key moments in theater history from Greek Drama to Medieval religious performances to modern and experimental theater. Throughout the semester we will examine theater-in-context, attending to the circumstances (political, social, historical, and artistic) surrounding the performance event. We will engage with drama theory to deepen our analysis of dramatic texts and the performances of them. With an emphasis on close readings, critical thinking, and creative engagement with the materials, we will interrogate the boundaries between performers and audience and the ways theater makers have used performance to challenge or affirm the status quo. Topics will vary. <em>There is a $25 ticket fee for this course.</em></p> <p><strong>History of Indian Performing Arts</strong></p> <p>This class will delve into the rich and vast history of Indian performing arts and its present forms. Starting at the roots, students will study Indian theater which was an all-encompassing art form that included dance and music as integral elements. The class will include the following: A look at the Naytashastra in its comparison to Aristotle''s Poetics; a study of the different forms of theatre (classical and folk) and thereafter the branching out of classical dance; to present day work being done in India in contemporary theater, dance, and Indian cinema (independent vs commercial Bollywood) and its relationship to its roots and how it carries on a performance legacy.</p> </div>','THEA 100 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16473,2027,992,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-302','<div class="desc"> <p>During the semester we study the works of various twentieth century playwrights. Different years will feature different playwrights: so one semester might look at farceurs another semester political pioneers and another European iconoclasts. In addition to reading several scripts by each playwright our students also attend live performances prepare research projects and create performance projects in response to the semester''s writers. Students may use this course to fulfill the Junior Writing Requirement for the Theater Major.<em> There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16474,2027,1496,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-303','<div class="desc"> <p>The focus of this course is on the history literature and performance practice of Latina/o theater in the United States. Students will read the work of a number of Latina/o playwrights with particular focus on contemporary playwrights. We will ask questions about how theater is labeled Latina/o and whether it exists on the margins or within the mainstream of US theater. We will consider common themes and forms shared by these works as well as the ways in which they stand apart creating a diversity of voices. Secondary readings will provide context for our investigation into the socio-political contexts of these works while play attendance will keep our focus on these plays as performance. <em>There is a ticket fee of $50 for this course.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16475,2027,415,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-310','<div class="desc"> <span>Topics vary by semester.</span><span><br/> </span><br/> <span><strong><span style="text-decoration: underline">Scene Study</span></strong></span><br/> <span>This advanced scene study course focuses on the works of seminal American playwrights. Through intensive text analysis and performance, students will explore the themes, characters, and cultural contexts that define these playwrightsâ contributions to the American theatre canon.</span><br/> <br/> <span>Students will develop a deeper understanding of the playwrights'' distinctive voices. Emphasis will be placed on honing acting techniques, deepening emotional authenticity, and refining character development to bring these complex works to life. By the end of the course, students will have the skills necessary to tackle rich, challenging texts and will gain insights into the historical, social, and cultural underpinnings of these masterpieces. Designed for actors who have taken 210 &amp; 110, this course requires a strong foundation in acting techniques and a commitment to rigorous creative work.</span><br/> <span><br/> </span><strong><span style="text-decoration: underline"><br/> Solo Performance</span></strong><br/> <span>Advanced Acting builds on the techniques and skills introduced in Acting 1. Students will continue to explore character development and scene work through an array of texts and styles. Students will also explore acting methods that will help them become more flexible, daring, collaborative, and creative performers. An emphasis will be put on Solo-Performance techniques. Students will actively create a self-sustaining piece of solo theater from conception to creation and finally to the stage. Course participants will also discover and evaluate texts and performance practices of previous solo-theater practitioners. In the process, students will learn how to act with increased freedom and to create characters with genuine psychological complexity, accumulating tools and skills applicable to working both on stage and on screen.</span> </div>','THEA 210 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16476,2027,417,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-311','<div class="desc"> <p>Our upper-division applied acting course is available for students performing significant roles in professionally directed Theater Department productions. <em>This course is offered only for grades of Credit/No Credit and may be repeated for credit. It is available only with permission of the instructor.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16477,2027,1356,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-315','<div class="desc"> <p>Ever wonder how Broadway performers make every lyric feel like a story? In this hands-on course, youâll learn how to bring songs to life by connecting your voice and body to your character. Weâll dive into the performance side of musical theater â exploring how breath, phrasing, and emotion turn music into meaning. Youâll get to prepare and perform songs from the conventional and unconventional Broadway musical canon, discovering your unique style along the way.</p><p>Whether youâve never sung outside the shower or youâve been performing for years, this class is for anyone ready to explore the art of storytelling through song â and to build confidence on stage while doing it.</p><p><em>All experience levels welcome. Prerequisite: THEA 110 or permission of instructor.</em></p><p><br/></p><p><br/></p><p><br/></p> </div>','THEA 110 : Introduction to Acting or Permission of Instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16478,2027,784,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-316','<div class="desc"> <p>In this culmination of the Theater Department''s acting sequence our students explore through practice the demands Shakespeare''s scripts make upon actors. During the semester students in the class work with five to six of Shakespeare''s scripts from various genres in order to develop facility with Shakespeare''s verse and prose in performance.</p> </div>','THEA 202 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16479,2027,994,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-325','<div class="desc"> <p>Studying the theories the psychological foundations and techniques of lighting design for the theater our students develop in this course an intellectual and practical foundation of this significant and accessible area of theater design. During the semester we guide students in the class through bothindividual and group design projects. <em>There is a material/tickets fee of $60 for this course which includes one two-hour laboratory session each week.</em></p> </div>','THEA 120 or THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16480,2027,785,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-330','<div class="desc"> <p>Students in this course analyze the various requirements for producing live performance events. In developing solutions to the many difficulties presented by live events we examine in particular the artistic, legal and financial responsibilities of the producer. Through projects, case studies, and research, our students look at the creative and practical aspects of live presentations as they come to understand the myriad considerations required to successfully produce live performances for theater music and other cultural events. Not open to first year students.</p> </div>','THEA 120 and permission of the instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16481,2027,418,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-370','<div class="desc"> <p>This course concentrates on the skills needed to conceptualize and draw costumes for the stage and screen. In addition to drawing skills, students will learn how to break down scripts to understand and interpret a character’s world and maintain continuity in design. Costume Design is for students with wide-ranging drawing skills, including beginners. Students will learn to draw a variety of fabrics–including sheer fabrics, sequins, feathers, and patterned fabric. Live figure drawing and shorthand sketching techniques provide a foundation for sharing your creative vision. Artistic mediums covered include freehand drawing, digital rendering, and collage. A portion of the course focuses on budgeting and hidden costs in costuming for film and theater.</p> </div>','THEA 175 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16482,2027,419,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-380','<div class="desc"> <p>We engage our students in Playwriting with the art of writing for the live stage. Through reading scripts by established authors and generating original writing, students develop their dramatic skills and theatrical imaginations. Creative assignments focus on crafting well-developed characters, sound story structures and compelling dialogue. As a final project, each student writes and rewrites a short play. THEA 101 or MAC 220 is a pre-requisite - OR you may be admitted by permission of instructor. </p> </div>','THEA 101 or MAC 220 or Permission of Instructor ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16483,2027,420,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-390','<div class="desc"> <p>For advanced theater students we offer an applied course for significant work undertaken in performance design technical theater or management in faculty-supervised projects. A student enrolled in this course works directly with a faculty mentor in the design and execution of the individual project. </p> <p>Section 1 - Advanced Projects in Theater: Story/Voice/Community </p> <p>Section 2 - On-campus projects</p> <p>Permission of instructor required. Course may be repeated once for credit.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16484,2027,3776,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-393','<div class="desc"> <p>Students doing directed research at the 300 level will have completed substantial coursework in the TPS major. Students are expected to be proficient in the areas of work involved in the project and should be able to work more independently, to mentor novice students, and to begin to propose new areas of inquiry. </p> <p>The directed research could take the form of directing a performance, devising an original performance, playwriting, original research for a paper, designing scenic, lighting, or costume elements, technical directing, stage managing, and all the dramaturgical analysis that goes into such a project and that it is under the mentorship of a faculty member. The learning goals of directed research is for the students to:</p> <ul style="margin-top: 0in; list-style-type: disc;"> <li>apply and develop proficiency in the skills and tools they have learned in earlier courses and experiences </li> <li>work independently to lead a team (if applicable), collaboratively, and in line with their design/directorial/technical vision</li> <li>conduct and execute original work</li> <li>incubate new ideas and use this opportunity as an incubator for future work </li> </ul> <p>Permission of instructor is required. </p> </div>','Permission of the instructor and a B- or higher in an advanced course in the area of the student''s research ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16485,2027,4404,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-395','<div class="desc"> Topics vary semester to semester. Specific topics may satisfy different Core Program requirements. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16486,2027,787,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/300/thea-397','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16487,2027,788,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/400/thea-410','<div class="desc"> <p>We introduce students to the art of directing. Our students explore the directing processes of script analysis casting working with actors manipulation of space use of sound and images developing designs and mounting productions for theater. During the semester students in the class stage two performance sequences: one in a classroom format the other produced on the Keck stage. THEA 316 is strongly recommended for preparation. This course may be repeated for credit. Permission of instructor required.</p> </div>','THEA 120 and THEA 310 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16488,2027,421,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/400/thea-490','<div class="desc"> <p>This is a course for students engaged in senior comprehensive projects in Theater. <em>Only open to senior Theater majors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16489,2027,4405,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/thea-theater/400/thea-497','<div class="desc"> <p>Our junior and senior students have the opportunity for independent study at an advanced level. Permission of instructor and department chair required. <em>This option is only open to juniors and seniors.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16490,2027,423,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-101','<div class="desc"> <p>This is an introductory course on environment and society designed for students with an interest in urban and environmental issues who might want to pursue further studies in Urban and Environmental Policy. It is also offered for those who are interested in the topic even though they will be pursuing another major. The course will include lectures and presentations in several different topical areas; films and speakers that provide insight into the environmental problems and alternative solutions including those based here in Los Angeles; and class discussions and presentation sessions on the readings and topics. The course provides an broad introduction into core topics in urban and environmental policy such as: water issues (where our water comes from); wastes and hazards issues (sources and impacts of pollution); climate change transportation and land use issues (where we work and live and commute); nature in the city (the urban environment); and food system issues (where our food comes from and how it is manufactured and sold) the intersection of science and policy and others.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16491,2027,3350,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-120','<div class="desc"> <p>The FEAST Garden Practicum is a hands-on introductory class designed for students with an interest in learning about and applying sustainable agriculture techniques. Students will gain a deeper understanding of agricultural management and small-scale farming. With leadership provided by the FEAST Faculty Advisor and FEAST Student Managers, students will engage in seasonal farming activities with a focus on edible and medicinal plants, native habitat and pollinator gardens, resource and water management, chicken stewardship, the basics of soil health and compost, as well as how to organize and host community events. Graded on a Credit/No Credit basis only.</p> <p>Note: This class will not count towards a UEP major or minor elective</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16492,2027,3916,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-150','<div class="desc"> <p>This course focuses on teaching students how to access, integrate, and quantitatively evaluate many types of spatial information using different methods of analysis. Students use GIS software to understand, explore, and analyze information from a variety of sources, with an emphasis on understanding the geography of environmental health and the relationships between multiple determining factors. Students will learn fundamentals of geography and cartography, GIS techniques in quantitative spatial analysis, and introductory spatial statistics as applied to vector-based data. The tools and skills used in this course, and the analytical problem-solving projects used in laboratory and project assignments, will provide them with a means to better understand the environmental health risk and epidemiology, and enhance their ability to make informed and quantitative comparisons. (Students are encouraged to enroll in UEP 201, a course that explores how environmental factors impact human and ecological health).</p> </div>',NULL,'UEP 150L ',NULL);
INSERT INTO course_descriptions VALUES(16493,2027,4046,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-160','<div class="desc"> <p>An introduction to techniques of spatial analysis using GIS. You will study the fundamentals of geography and data science that guide you to valid approaches to practical problem-solving and investigate timely environmental questions that matter using real-world data: vector and raster geospatial datasets, aerial photos, satellite imagery, LiDAR. The course also includes a project combining GIS data acquisition and analysis to solve a practical question on the Oxy campus. This course will help you learn a valuable job skill that can apply to many different careers and interests. You should feel comfortable using the MS Windows operating system and Microsoft Excel software. Includes one three-hour laboratory per week. </p> </div>','UEP 150 , UEP 305 , or instructor permission ','UEP 160L ',NULL);
INSERT INTO course_descriptions VALUES(16494,2027,4406,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/100/uep-197','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16495,2027,1357,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-201','<div class="desc"> <p>This course is designed to provide students with an understanding of the environmental factors impacting human and ecological health including consequences of natural and human-made hazards. Environmental health is a rapidly growing and interdisciplinary field that involves both science and public policy. It is integrated into numerous aspects of our lives both directly and indirectly. Topics to be covered include food safety water access and equality pesticides air quality the identification of environmental hazards the assessment of various risks (including exposure to dangerous chemicals used in toys food workplaces and other activities) and the social and biological causes of disease (epidemiology) Students will gain an understanding of environmental health analytical and scientific methods. We will also explore ways that communities and policy-makers seek to address environmental health challenges. A common thread running through the course will be an examination of how exposure to environmental and health risks vary among different population groups in the Los Angeles area in the United States and around the world and the ways that scientific issues become embedded in and inseparable from issues of policy regulation and justice. We will also explore the role of science in environmental policy-making the enforcement of regulations and the efforts of community groups to influence public policy. (Students are encouraged to enroll in Geology 150 a laboratory science that in parallel explores the spatial and geographic dimensions of environmental health.</p> <p>Not open to frosh without permission of instructor.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16496,2027,1198,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-209','<div class="desc"> Why does the United States spend more on health care per person than other developed countries and still have worse health outcomes? American health care costs (including drug prices) are higher and we have a much greater use of expensive medical technology than in other countries. This course will examine the strengths and weaknesses of different approaches to health care delivery and financing, including private, single-payer and universal systems. Students will analyze the impact of these approaches on access, cost, quality, and disparities. They will also examine the historical, economic, social, and political factors that have led the U.S. to adopt its current health system, how care is delivered (hospital, community clinic, Veterans Administration), analyze its strengths and weaknesses, and examine the different proposals for reforming it. </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16497,2027,884,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-210','<div class="desc"> <p>Los Angeles is a city often known for its traffic, air pollution, auto-centric land use patterns, and car culture. However, Los Angeles is also a place of transportation innovations and a public commitment to changing the way people move to and through Los Angeles in equitable and environmentally sustainable ways. This class provides an overview of urban transportation issues and systems, focusing on the impacts of mobility policies, systems and infrastructure on cities and on Los Angeles in particular. Through lectures, guest speakers, class exercises and projects, students will explore the history of transportation in the US as well as comparatively with other countries and understand the role of policy in shaping and defining transportation systems. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16498,2027,1103,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-214','<div class="desc"> <p style="margin-left:0px; margin-right:0px">The struggle for control of our public education system in Los Angeles has become one of the most high profile conflicts facing the city and its residents. The stakes couldn’t be higher. The lives of children and the hopes and dreams their parents literally hang in the balance. In UEPI 214, Professor Steve Zimmer, a long-time teacher and the former President of the Los Angeles Unified School District Board of Education, will guide students through a journey in understanding the role of public education in our society and tensions over different visions and goals for public schools, including its mission to promote equality, equity, and mobility. The course will also explore how public policy can help or hinder public school’s equity mission. The class will examine the effects of expanding racial and economic segregation, increased standardized testing, and toxic stress have on students trying to pursue their dreams and the teachers trying to make those dreams come true. The class will also assess the impact of teacher tenure reform, the expansion of charter schools, the community schools movement and other policy based debates that could influence the future of teaching and learning. Through guest lectures, panels, films, and readings, students will understand the role that policy and collective action can play in pursuing a collaborative agenda. The final project will involve actually writing policies to be presented to the Board of Education and/or other policy makers. </p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16499,2027,1743,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-230','<div class="desc"> This course will cover the problem of climate change and the history and evolution of the climate justice movement. It will examine the organizing and policy tools used by advocates to advance climate justice. The course will begin with an exploration of climate change, the environmental and political factors that cause the climate to change, and why the issue matters to communities across the globe. The course will then look at the history and foundational concepts of climate justice with particular focus on how issues of race and class impact climate justice. Finally, the course will look at how the traditional environmental movement, the labor movement, and global movements advocate for climate justice and what priorities they advance. Key topics to be covered are: the intersection between race and the environment, the relationship between traditional environmental movements and the environmental justice movements, labor movements and the green economy, global solidarity movements. </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16500,2027,3828,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-240','<div class="desc"> <p>An in-depth class on backyard poultry and its connection to regenerative agriculture with a focus on an holistic and sustainable approach that prioritizes the health and well-being of animals, the environment, and the people involved in the process.<br/> <br/> Topics include: understanding animal welfare, legal aspects; California vs. US humane laws, overview of breeds, chicken and duck facts and behaviors, setting up proper biosecurity and how to maintain it, creating your own feed and cost effective tricks, store bought vs. pasture raised, environmental enrichment, first aid / natural and holistic solutions, health management and overview of common illnesses, troubleshooting, how to spot and diagnose sick chickens, coop management and soil and composting.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16501,2027,425,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-246','<div class="desc"> <p>This course is designed to assess and develop recommendations regarding environmental issues related to the Occidental campus with attention to sustainability as encompassing urban environments and issues of equity, justice, and community. Students will evaluate the College''s current practices such as energy and water use, transportation and parking, building construction and maintenance, landscape and grounds maintenance, hazardous and solid waste generation and management, educational and outreach strategies and how the College''s environmental issues relate to the larger Northeast Los Angeles community. Students will develop proposals and programs to reduce resource use and the College''s overall ecological footprint while also seeking to identify how the College can itself play a positive role in increasing the environmental sustainability of its neighboring community. The course is designed to develop project management and environmental leadership skills with the campus as the arena for change.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16502,2027,789,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-247','<div class="desc"> <p>This class is a collaboration between the Urban and Environmental Policy Institute (UEPI) and the FEAST (Food, Education, and Sustainability Team) student service to enhance student capacity to lead and engage with food and gardening projects both on campus and in the community. Through the implementation of projects in campus garden spaces, participation in community service learning projects, and field trips to innovative food programs in Los Angeles, students will gain hands-on understanding of food issues and will complete the course with the ability to help in the design, creation, and maintenance of a garden-based food or sustainability project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16503,2027,1430,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-265','<div class="desc"> <p>Why do cities "look" the way they do? What explains the characteristics and geographic patterns of the physical social and demographic landscape of cities? How can community members influence these characteristics and patterns? Part of the answer lies in understanding the practice of urban planning and its intersection with political processes. This course will introduce students to the history issues concepts tools and techniques of urban planning. In addition to examining a wide body of literature pertinent to the theory and practice of urban planning students will also study and discuss current planning issues and politics in Los Angeles with a particular focus on community-based planning initiatives. What are the politics of planning in LA? To extend Harold Laswell''s description of the study of politics: Who Gets What When How in the sphere of urban planning in Los Angeles? This introduction will serve as a foundation for major community based research project conducted in partnership with local non-profit community based organizations engaged in the planning process. Students will develop community-based research writing and presentation skills. Through this course students will gain an understanding of the impact that planning decisions have on the lives of city residents and how these community members can actively and effectively engage in the politics of planning.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16504,2027,3850,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-270','<div class="desc"> <p>Labor unions are the largest membership-based organizations in North American cities: they play a vital role in mobilizing urban residents, shaping urban conflict, and crafting policies that transform urban space. This course investigates the practical realities of union involvement in urban politics. It focuses on a variety of economic and government sectors (education, film, hospitality, green energy, child care, and healthcare) and explores how workers in each of these industries orient themselves toward city life; how they imagine more just and sustainable urban futures; and how they organize to make these visions real. It also considers the dilemmas that unions weigh as they make decisions about which political campaigns to take on vs. which to set aside, and how much time to dedicate to existing union members vs. the non-union workers who make up the majority of urban residents. Finally, this course invites students out of the classroom and into the field to explore the L.A. labor movement in-action. Students will be invited to to observe, interview, and speak with union members about how they understand their role in city politics; the kinds of collective actions that move the policy needle; the aspirational claims that workers make on urban futures; and how to confront the rapidly changing nature of work in fast-paced, technology-driven urban industries.</p> </div>','This course requires a basic understanding of both unions and cities, which the prerequisites below provide. ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16505,2027,1138,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-295','<div class="desc"> <p>Topics vary semester to semester.</p><p><strong>Poverty and Inequality in America</strong></p><p>This course will examine why the U.S. has more poverty and more inequality than any other wealthy nation -- and what we can do about it. The course will include class discussion, readings, and films. Among the topics we''ll discuss are: Who benefits and who suffers from America''s high of poverty and inequality? Should our society try to significantly reduce poverty and inequality? If so, what can we do? Who is poor in America? Who is super-wealthy? Who is middle class? What are the major stereotypes about the lives of the poor and the super-wealthy? How have issues of race, gender, and immigration influenced the level of poverty? Why are poor, middle class, and wealthy people in America concentrated in certain locations - more so than in other wealthy societies? Has government policy made poverty and inequality better or worse? What political movements and policy reforms have made a difference in improving the lives, and reducing the number, of America''s poor? How can poor Americans and their allies influence politics and policy?<br/><br/>Students who want to get a head start on the readings should read Barbara Ehrenreich''s book, "Nickel and Dimed: On (Not) Getting By in America."</p><p>This topic is cross listed with SOC 295.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16506,2027,1634,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/200/uep-297','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16507,2027,2568,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-300','<div class="desc"> <p>This course analyzes the legal and policy framework for environmental protection and environmental justice. The course covers the major environmental statutes, applicable civil rights laws, and the next wave of climate change litigation. This course will also place environmental law and policy within the larger conversation around environmental protection and climate change.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16508,2027,790,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-301','<div class="desc"> <p>This seminar focuses on the origin and development of cities suburbs and urban areas. It explores the causes symptoms and solutions to such urban problems as poverty, housing, transportation, crime and violence, pollution, racial segregation and gentrification. It also examines how power is exercised by different groups including business, citizens'' groups, community organizations, unions, the media, mayors and other government officials. The course will also examine the role of city planning and planners, conflict and cooperation between cities and suburbs, problems of urban sprawl, loss of open space, water and energy resources. Students will learn about federal urban policy and the role of cities in national politics. The course will also compare American cities with cities in Europe, Canada, and the developing world. Public policies to solve urban problems.</p> </div>','UEP 101 or POLS 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16509,2027,996,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-302','<div class="desc"> <p>This course examines how societies provide people with shelter - through market forces government policy and self-help efforts. The course will focus on the United States but will also look at other societies to help understand the strengths and weaknesses of the U.S. approach. Students will examine such housing problems as homelessness slums (substandard housing) the shortage of affordable housing racial segregation foreclosures and other topics. It will examine the pros and cons and different forms of rental housing and homeownership. It will look at the connection between housing issues and the environment public health education transportation suburbanization and sprawl poverty and inequality and racism. Students will explore housing as an aspect of our culture such as homeownership as the "American dream" and housing as a "haven." The course will explore the history of housing problems and housing policy including zoning racial discrimination finance public housing different government subsidies for housing and taxes. We will debate whether decent housing is a "right". We will look at housing problems and policies at the local state and national levels. Students will explore the politics of housing in terms of the various interest groups - including developers banks tenants community organizations landlords contractors unions and others -- involved in shaping housing policy. Students will also learn about housing as part of the "built environment" architecture land use urban design as a component of urban planning and as a part of "livable" cities. They will also examine housing as a component of real estate development and explore what housing developments - whether for-profit or non-profit - do.</p> </div>','UEP 101 , ECON 101 , POLS 101 , or SOC 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16510,2027,791,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-303','<div class="desc"> <p>This course examines sustainable development from a social economic and environmental perspective. The course focuses on development strategies and approaches led by community-based labor and nonprofit organizations in a context of traditional public and private-sector economic development approaches. Through lectures field trips discussion guest speakers and class exercises students will examine the history and evolution of community and economic development strategies in urban neighborhoods and communities and link these approaches to the field of sustainable development. The course focuses on the historic and contemporary debates and issues in sustainable development and delves into the challenges and opportunities of sustainable development in Los Angeles by drawing on case examples from other urban regions across the country. Through the course students will: 1) understand the historical theoretical and policy context of community development; 2) understand community and economic decline and development processes; 3) examine the key strategies of community development and related field of community economic development; 4) explore the growing intersection of community development and sustainable development including the greening of jobs buildings and urban design.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16511,2027,427,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305','<div class="desc"> In this course, students will learn how to document and analyze urban and environmental problems and public policies using quantitative data. Quantitative data provide a compelling means by which we can understand the magnitude of urban problems and who is impacted by these problems across demographic groups, neighborhoods, cities, and countries. Quantitative data can also help identify solutions, including public policies, and then evaluate the effectiveness of those solutions. Ultimately, our task is to develop quantitative reasoning skills in order to mobilize facts in the pursuit of a more just and equitable urban society. In the words of urban geographer Elvin Wyly: "Get mad. Get data. Get to work." Or, as Daniel Patrick Moynihan once said: "You can''t solve a problem until you first learn how to measure it." An important aspect of the course is how to make relevant and meaningful comparisons. How can we understand the size and significance of an urban problem such as low-wage work, or housing discrimination, racial profiling by police, or air pollution? We understand these issues best in relation to other outcomes: good jobs, nondiscriminatory housing and police practices, and clean air. We need to measure these outcomes in ways that we can compare them. Toward that goal, students will learn basic mathematical calculations and concepts such as percentages, rates, normalization, baselines, distributions, and probability. We will learn to read and interpret quantitative information presented in various formats, such as tables, graphs, geometric figures, or in text. Students will learn to assess numeric arguments and "answers" for reasonableness, as well as to recognize the limits of quantitative methods. Lastly, students will learn to evaluate how quantitative data is used, and sometimes misused, in the news media and public debates about social, economic, and environmental problems. Students will also engage basic questions of research: What data do we need to answer relevant policy questions? How can we devise a research project that would generate these data? Students will explore basic research methods using quantitative data, such as specifying a research question, research design, sampling, measurement, and validity. </div>',NULL,'UEP 305A ',NULL);
INSERT INTO course_descriptions VALUES(16512,2027,1566,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-305a','<div class="desc"> Weekly laboratory for Urban Data Analysis where students will directly manipulate, analyze, and visualize real-world data related to urban problems and policy concerns, such as poverty, wages and low-wage work, housing affordability and quality, transportation equity, air quality, water safety, green space, food access, and crime and public safety. We will focus on identifying and communicating patterns of urban inequality. Students will become familiar with Excel and be introduced to Stata, a statistical software package. Students will learn to manage data, produce basic charts and graphs, generate descriptive statistics, and test hypotheses. </div>',NULL,'UEP 305',NULL);
INSERT INTO course_descriptions VALUES(16513,2027,792,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-306','<div class="desc"> <p>This community based learning course explores a range food systems issues from a food justice lens. The course examines how our food system has been restructured over the last century to benefit large-scale agriculture interests, creating a global food system that emphasizes convenience and fast-food solutions for consumers, often to the detriment of low-income people and communities of color. Through in-depth class discussions, on-site field trips, and in-class speakers, the class will delve into the environmental, economic, health, cultural, and social impacts of to how food is grown, processed, manufactured, distributed, sold, and consumed in the U.S. The community based learning component of this course will involve project work with UEPI’s food programs as well as other Los Angeles-based nonprofit partners and food policy experts. Please note, the first half of the semester will be based in the classroom (T/Th 1:30-2:55pm). During the second half of the semester, class will be held only one time per week (from 11:45am-2:55pm) to accommodate field trips.</p> </div>','UEP 101 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16514,2027,428,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-310','<div class="desc"> <p>This seminar focuses the techniques of grassroots empowerment particularly in urban settings. This includes the following topics: developing leadership skills for citizen participation and problem solving using the media building coalitions choosing issues doing action-oriented research understanding the relations of power mobilizing constituencies developing a community oriented public policy agenda the history of community organizing in the U.S. and comparison between community development social work and direct action organizing approaches. <em>Must be taken simultaneously with UEP 311.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16515,2027,429,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-311','<div class="desc"> <p>This course provides opportunities for applying and learning through direct experience about the practice of community organization and leadership. Each student will work with a community-based organization engaged in influencing public policy for approximately 12-15 hours each week. Students will be supervised jointly by the faculty member and a staff person for the community organization. <em>Must be taken simultaneously with UEP 310.</em></p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16516,2027,3851,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-390','<div class="desc"> <p>This course examines the political ecology/economy of food, agriculture, and hunger in Los Angeles with an emphasis on Latin American-Caribbean relations. Students will explore these themes through readings, lectures, and a class-based research project in the city where students will gain practical experience in research design and apply techniques such as qualitative interviews and surveys, oral histories, ethnography, participant observation, and utilize archival material and visual and audio documentation.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16517,2027,997,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-395','<div class="desc"> <p>Topics vary semester to semester. Students are encouraged to have completed UEP 101 or other relevant UEP courses prior to enrolling in this course.</p><p><br/></p><p><strong>Ending Homelessness: The Public Policy Challenge of our Time </strong></p><p>âHomelessnessâ is the product of intersecting failures, including a broken housing market; inadequate mental health and addiction treatment services; mismatch between wages and housing costs; and reliance on law enforcement to address social breakdowns. This course will analyze the causes of homelessness; the competing political and ideological narratives around its nature and cure; as well as promising policy approaches that actually work. Using Los Angeles as the primary case study, adjunct professor Rick Cole draws on his first-hand experience as a former mayor, city manager and current Pasadena City Councilmember (along with guest speakers who are leaders in local government, non-profits, and law).</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16518,2027,793,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/300/uep-397','<div class="desc"> <p>Tutorial and Internship for junior or senior majors in Urban and Environmental Policy and other related disciplines under arrangement with faculty. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16519,2027,430,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-410','<div class="desc"> <p>Intensive study of the making of national and local public policy in the U.S. including the political environment in which policy debates take place. Extensive use will be made of case studies on a variety of domestic and international issues. Students will participate in the development of a major research project related to their senior comprehensive project on an individual or group basis.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16520,2027,794,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-411','<div class="desc"> <p>Seminar to organize and complete a senior project demonstrating competence in applied public policy. The form and format of each student''s project will vary. All students will make a presentation of their project and will critique each other''s project.</p> </div>',NULL,NULL,NULL);
INSERT INTO course_descriptions VALUES(16521,2027,4048,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-493','<div class="desc"> <div><p dir="ltr" style="line-height: 1.38; margin-top: 12pt; margin-bottom: 0">UEP 493 enrolls seniors who seek to continue their research from UEP 410 into a second semester as directed research. The Directed Research allows seniors to continue to build from their research proposal and analysis that was completed during the senior comprehensive seminar (UEP 410) during the Fall semester. In the Spring, they will have the option to carry out and apply the research methods described in UEP 410, conduct independent and applied research, write up their Results, Analysis, Discussion, and Conclusion of their project.</p></div> </div>','UEP 410 ',NULL,NULL);
INSERT INTO course_descriptions VALUES(16522,2027,4407,'https://oxy.smartcatalogiq.com/en/2026-2027/catalog/course-descriptions/uep-urban-environmental-policy/400/uep-497','<div class="desc"> <p>Independent study project. Permission of instructor and department chair required.</p> </div>',NULL,NULL,NULL);
